-- AISHA Platform - Init Migration
-- Generated from file-based source-of-truth SQL
-- Nemodifikovat ručně: generuje npm run db:init:generate ze aisha/db/sql/**

-- Safety guard: prevent applying init onto an existing schema
DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM information_schema.tables
    WHERE table_schema = 'public'
      AND table_name = 'profiles'
  ) THEN
    RAISE EXCEPTION 'Init migration must be applied to a fresh database (use npm run db:reset:local).';
  END IF;
END $$;


-- =============================================================================
-- EXTENSIONS (4)
-- =============================================================================

SET search_path TO public, extensions;
DO $$ BEGIN EXECUTE format('ALTER DATABASE %I SET search_path TO public, extensions', current_database()); END $$;
CREATE EXTENSION IF NOT EXISTS "vector";
CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";
CREATE EXTENSION IF NOT EXISTS "btree_gist";
CREATE EXTENSION IF NOT EXISTS "pg_trgm";


