-- -----------------------------------------------------------------------------

-- Table: acs_dead_letters
-- Dead letters (R4) — rejected traffic is preserved, never guessed at.

CREATE TABLE IF NOT EXISTS public.acs_dead_letters (
  id             bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  rejection_code text NOT NULL CHECK (rejection_code IN (
    'envelope_invalid','payload_invalid','unknown_schema','signature_missing',
    'signature_invalid','sender_unknown','duplicate_message','acl_denied')),
  detail         text NOT NULL DEFAULT '',
  raw            jsonb NOT NULL,
  received_by    text NOT NULL,
  created_at     timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.acs_dead_letters ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/acs_intents.sql
-- -----------------------------------------------------------------------------

-- Table: acs_intents
-- Canonical intents (R3) — immutable once written.

CREATE TABLE IF NOT EXISTS public.acs_intents (
  intent_id     text PRIMARY KEY CHECK (intent_id ~ '^int_[0-9A-HJKMNP-TV-Z]{26}$'),
  canonical     jsonb NOT NULL,                      -- frozen original request (verbatim)
  content_sha256 text NOT NULL CHECK (content_sha256 ~ '^[a-f0-9]{64}$'),
  source_class  text NOT NULL CHECK (source_class IN ('internal','partner','byod','public')),
  created_by    text NOT NULL,                       -- service.component identity
  created_at    timestamptz NOT NULL DEFAULT now(),
  ai_run_id     uuid NULL                            -- optional anchor to ai_runs
);

ALTER TABLE public.acs_intents ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/acs_message_schemas.sql
-- -----------------------------------------------------------------------------

-- Table: acs_message_schemas
-- Contract registry (R4) — rows mirror @aisha/acs-contracts schema files.

CREATE TABLE IF NOT EXISTS public.acs_message_schemas (
  schema_ref  text PRIMARY KEY CHECK (schema_ref ~ '^[a-z0-9_.-]+@[0-9]+\.[0-9]+$'),
  json_schema jsonb NOT NULL,
  semantics   text NOT NULL DEFAULT '',              -- human contract: meaning, not just shape
  mode        text NOT NULL DEFAULT 'shadow' CHECK (mode IN ('off','shadow','warn','enforce')),
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.acs_message_schemas ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/acs_agent_acl.sql
-- -----------------------------------------------------------------------------

-- Table: acs_agent_acl
-- Least-privilege routing matrix (R6) — default deny: no row, no traffic.

CREATE TABLE IF NOT EXISTS public.acs_agent_acl (
  sender_pattern    text NOT NULL,   -- exact identity or prefix ending with '.'
  schema_ref        text NOT NULL REFERENCES public.acs_message_schemas(schema_ref),
  recipient_pattern text NOT NULL,
  allowed           boolean NOT NULL DEFAULT true,
  note              text NOT NULL DEFAULT '',
  created_at        timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (sender_pattern, schema_ref, recipient_pattern)
);

ALTER TABLE public.acs_agent_acl ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/acs_message_log.sql
-- -----------------------------------------------------------------------------

-- Table: acs_message_log
-- Append-only message log (R6) — UNIQUE message_id is the replay/dedup gate.

CREATE TABLE IF NOT EXISTS public.acs_message_log (
  message_id     text PRIMARY KEY CHECK (message_id ~ '^[0-9A-HJKMNP-TV-Z]{26}$'),
  schema_ref     text NOT NULL REFERENCES public.acs_message_schemas(schema_ref),
  intent_id      text NOT NULL REFERENCES public.acs_intents(intent_id),
  correlation_id text NOT NULL CHECK (correlation_id ~ '^[0-9A-HJKMNP-TV-Z]{26}$'),
  causation_id   text NULL CHECK (causation_id IS NULL OR causation_id ~ '^[0-9A-HJKMNP-TV-Z]{26}$'),
  sender         text NOT NULL,
  recipient      text NOT NULL,
  sent_at        timestamptz NOT NULL,
  signature      text NULL,
  trust          jsonb NOT NULL,
  payload        jsonb NOT NULL,
  logged_at      timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.acs_message_log ENABLE ROW LEVEL SECURITY;


