-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/agent_phase_catalog.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: agent_phase_catalog
-- Purpose: Seed-extensible taxonomy of agent work phases. Replaces hardcoded
--          CHECK constraints / UI badge maps so AISHA can add phases by
--          inserting rows (self-tooling loop) instead of schema changes.
--          Two axes ship seeded:
--            activity — universal session state (idle, planning, tool_use,
--                       reviewing, stopped); validated by
--                       fn_upsert_agent_live_session.
--            pipeline — source-specific processing stage (routing, edge,
--                       backend, eval, streaming) used by the VS Code
--                       extension workPhase; stored in
--                       agent_live_sessions.phase_detail.
-- Managed by: seed aisha/db/seed/core/28_agent_phase_catalog.sql; reads via
--             get_agent_phase_catalog() for UI labels.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.agent_phase_catalog (
  slug        text        NOT NULL,
  -- Axis is open text (not CHECK-constrained) — new axes are a seed concern.
  axis        text        NOT NULL DEFAULT 'activity',
  -- Locale-aware display labels: {cs, en, …} — same pattern as
  -- claude_hook_bindings.messages.
  labels      jsonb       NOT NULL,
  sort_order  int         NOT NULL DEFAULT 0,
  is_active   boolean     NOT NULL DEFAULT true,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),

  PRIMARY KEY (axis, slug),
  CONSTRAINT agent_phase_catalog_labels_has_locales
    CHECK (labels ? 'cs' AND labels ? 'en')
);

COMMENT ON TABLE public.agent_phase_catalog IS
  'Seed-extensible phase taxonomy for agent_live_sessions (axis=activity validated in RPC; axis=pipeline for source-specific detail). UI reads labels via get_agent_phase_catalog().';

ALTER TABLE public.agent_phase_catalog ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/agent_tools.sql
-- -----------------------------------------------------------------------------

-- Table: agent_tools
-- Source: 20260302000000_phase2_tool_system.sql
-- RLS: ENABLED

CREATE TABLE IF NOT EXISTS agent_tools (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name              text UNIQUE NOT NULL,
  display_name_key  text NOT NULL DEFAULT '',
  description       text NOT NULL,
  parameters_schema jsonb NOT NULL DEFAULT '{}',
  handler_type      tool_handler_type NOT NULL,
  handler_ref       text NOT NULL,
  access_tier_min   text NOT NULL DEFAULT 'basic',
  is_active         boolean NOT NULL DEFAULT true,
  requires_consent  boolean NOT NULL DEFAULT false,
  audit_action      text DEFAULT NULL,
  metadata          jsonb NOT NULL DEFAULT '{}',
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  created_by        uuid REFERENCES aisha_auth.users(id),
  updated_by        uuid REFERENCES aisha_auth.users(id)
);

COMMENT ON TABLE agent_tools IS 'Registry of callable tools that AI agents can invoke during conversations.';
COMMENT ON COLUMN agent_tools.name IS 'Unique slug identifier used in tool_call references.';
COMMENT ON COLUMN agent_tools.description IS 'English description sent to the LLM for tool selection.';
COMMENT ON COLUMN agent_tools.parameters_schema IS 'JSON Schema describing the expected parameters.';
COMMENT ON COLUMN agent_tools.handler_type IS 'Execution method: rpc (Supabase RPC), edge_function, or webhook.';
COMMENT ON COLUMN agent_tools.handler_ref IS 'Reference to the handler: RPC function name, edge function name, or webhook URL.';
COMMENT ON COLUMN agent_tools.access_tier_min IS 'Minimum access tier required to execute this tool.';
COMMENT ON COLUMN agent_tools.requires_consent IS 'Whether data sharing consent is required before execution.';
COMMENT ON COLUMN agent_tools.audit_action IS 'If non-null, the tool execution is logged to audit_journal with this action.';

ALTER TABLE agent_tools ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/ai_budget.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Table: ai_budget
-- Mission Control governance — scope-generic AI spend cap.
--
-- A budget is a scope-ovatelný strop: `story` is the first scope (scope_id =
-- partner_stories.id), extensible to `partner` / `agent`. Mirrors the llm_quota
-- ledger pattern (per-user daily) but at (scope, period) granularity and
-- ALONGSIDE the per-user quota — an additional limit, not a replacement. The
-- per-story cap is metered + enforced at the orchestration control layer
-- (admission in fn_create_workflow_run, node boundary in the reflection runner).
--
-- Read paths:
--   - Admin/staff/service: all rows (ops + Mission Control board).
--   - Story participant: own story's row (board chip).
-- Write paths (mutation): service_role only, via the audited RPCs
--   (set_ai_budget_audited, fn_check_and_consume_ai_budget_audited).
--
-- scope_id is polymorphic (story=partner_stories.id, partner=partners.id,
-- agent=ai agent id) → no FK; integrity enforced by scope_type + the writing RPC.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.ai_budget (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- scope_type: story/context is the ENFORCED governance axis (multi-instance = per-context/
  -- knowledgebase; the instance boundary IS the story/context). partner + agent are a RESERVED
  -- forward-looking seam: the CHECK accepts them so policies can be authored ahead of reader
  -- wiring, but no enforcer reads them yet and nothing writes them, so they are INTENTIONALLY
  -- non-binding today — a recorded seam, NOT a fail-open hole. The scope-type-write-read-parity
  -- gate asserts every CHECK scope is either enforced (read by an enforcer fn) or reserved-here,
  -- so a FUTURE scope that is silently neither (a real fail-open) is caught at PR time.
  -- @scope-reserved: partner, agent
  scope_type        text NOT NULL
    CHECK (scope_type IN ('story', 'partner', 'agent')),
  scope_id          uuid NOT NULL,
  period            text NOT NULL DEFAULT 'lifetime'
    CHECK (period IN ('lifetime', 'daily', 'monthly')),
  token_limit       int
    CHECK (token_limit IS NULL OR token_limit >= 0),
  cost_limit    numeric(10,4)
    CHECK (cost_limit IS NULL OR cost_limit >= 0),
  consumed_tokens   int NOT NULL DEFAULT 0
    CHECK (consumed_tokens >= 0),
  consumed_cost numeric(10,4) NOT NULL DEFAULT 0
    CHECK (consumed_cost >= 0),
  last_reset_at     timestamptz NOT NULL DEFAULT now(),
  created_by        uuid,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ai_budget_scope_period_uniq UNIQUE (scope_type, scope_id, period)
);

ALTER TABLE public.ai_budget ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.ai_budget IS
  'Mission Control — scope-generic AI spend cap (story|partner|agent × lifetime|daily|monthly). NULL limit = that dimension uncapped. Service-role mutations only via audited RPCs; checked at the orchestration control layer alongside per-user llm_quota.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/ai_cost_class_catalog.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: ai_cost_class_catalog
-- Purpose: Seed-extensible mapping of task kinds (ai_runs.kind ∪
--          ai_tasks.task_type ∪ agent_runs.kind) to cost classes with
--          expected USD/token bands. This is the COLD-START side of cost
--          estimation: fn_estimate_task_cost prefers 30-day percentiles from
--          real ai_runs history and falls back to these bands when a kind has
--          too few samples. The bands also provide the DEFAULT allow/ask/deny
--          thresholds when no ai_spend_policies row matches (decided
--          2026-06-12: default posture = allow + ask above the class p90).
-- Managed by: seed aisha/db/seed/core/29_ai_cost_class_catalog.sql; admins
--             may tune rows via service_role / future audited RPC.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.ai_cost_class_catalog (
  kind        text        PRIMARY KEY,
  -- Coarse class for UI badges + reasoning: micro|small|medium|large|xl
  cost_class  text        NOT NULL DEFAULT 'small',
  -- Expected cost band (USD): p50 = typical, p90 = conservative estimate.
  usd_p50     numeric(10,4) NOT NULL DEFAULT 0,
  usd_p90     numeric(10,4) NOT NULL DEFAULT 0,
  -- Expected token band (subscription-domain runs are budgeted in tokens).
  tokens_p90  int,
  description text,
  is_active   boolean     NOT NULL DEFAULT true,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT ai_cost_class_catalog_class_check
    CHECK (cost_class IN ('micro', 'small', 'medium', 'large', 'xl')),
  CONSTRAINT ai_cost_class_catalog_band_order
    CHECK (usd_p50 >= 0 AND usd_p90 >= usd_p50)
);

COMMENT ON TABLE public.ai_cost_class_catalog IS
  'Seed-extensible kind→cost-class bands. Cold-start estimates + default spend thresholds; real history (ai_runs percentiles) takes precedence in fn_estimate_task_cost.';

ALTER TABLE public.ai_cost_class_catalog ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/ai_decisions.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: ai_decisions  (E0 decision journal)
-- Purpose: Persist EVERY AISHA execution decision (one row per dispatch) so the
--          orchestration authority is auditable and queryable. The id IS the
--          decision_id threaded onto ai_trace_events + carried by every runtime
--          adapter. Mirrors the in-memory decisionProvenance chain into durable
--          storage. Written by fn_record_execution_decision (VOLATILE wrapper);
--          the resolver/admission RPCs stay STABLE and never write.
-- Invariant (I1/I3): no dispatch without a journaled decision.
-- Security: RLS — story participants read their story's decisions; admin/staff
--           read all. Writes go through the SECURITY DEFINER wrapper only.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.ai_decisions (
  id            uuid        PRIMARY KEY DEFAULT gen_random_uuid(),   -- decision_id
  run_id        uuid,                                                -- ai_runs.id (nullable: pre-run admission)
  story_id      uuid,                                                -- denormalized for RLS chain
  clow_purpose  text,

  -- runtime axis (executor) — orthogonal to backend_kind (transport)
  runtime       text        NOT NULL DEFAULT 'direct_llm'
                CHECK (runtime IN ('direct_llm', 'openclaw', 'hermes', 'workflow', 'human', 'cli', 'workbench')),
  cli_slug      text,                                                -- when runtime='cli'

  -- model axis (from aisha_resolve_clow_backend.top) — backend_kind tolerant (string)
  provider_slug text,
  model_id      text,
  backend_kind  text,                                               -- transport; NULL for human/hermes
  strategy      text        CHECK (strategy IS NULL OR strategy IN ('sync', 'batch')),

  -- governance axis
  admission_verdict text    CHECK (admission_verdict IS NULL OR admission_verdict IN ('allow', 'ask', 'deny')),
  risk_level    text        CHECK (risk_level IS NULL OR risk_level IN ('low', 'medium', 'high', 'critical')),
  approval_required boolean NOT NULL DEFAULT false,

  -- provenance
  resolution_source text    CHECK (resolution_source IS NULL OR resolution_source IN
                ('clow_backend', 'model_override', 'slot', 'admission_deny', 'policy', 'fallback')),
  reason        text,
  estimated_cost numeric(12,6),
  -- Which operator-tunable ai_resolver_policy row produced this decision (soft ref, no FK: a
  -- historical snapshot — the policy may be retuned later). NULL for non-resolver decisions.
  resolver_policy_id uuid,

  -- Full decision blob for fidelity (the complete AishaExecutionDecision + verdict).
  decision_json jsonb       NOT NULL DEFAULT '{}'::jsonb,
  created_at    timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE public.ai_decisions IS
  'E0 decision journal: one row per AISHA execution decision. id = decision_id (threaded onto ai_trace_events + every runtime adapter). Written only by fn_record_execution_decision.';

-- Index lives in aisha/db/sql/indexes/idx_ai_decisions_run.sql (SoT separation).

ALTER TABLE public.ai_decisions ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/agent_runs.sql
-- -----------------------------------------------------------------------------

-- Table: agent_runs

CREATE TABLE IF NOT EXISTS public.agent_runs (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  kind text NOT NULL,
  profile text NOT NULL,
  image text NOT NULL,
  requested_by uuid,  -- NULLABLE: a system-spawned run (svc-agent-runner / reflection cli adapter calls fn_spawn under service_role, auth.uid()=NULL) has no human requester. Mirrors playwright_runs.requested_by.
  source text NOT NULL,
  source_ref text,
  inputs_s3_uri text,
  inputs jsonb,
  outputs_s3_uri text,
  outputs jsonb,
  status text DEFAULT 'queued'::text NOT NULL,
  exit_code integer,
  started_at timestamp with time zone,
  finished_at timestamp with time zone,
  host text,
  langfuse_trace_id text,
  error_summary text,
  -- Admission / approval (E0). A claude_cli_task whose fn_admit_clow verdict is
  -- 'ask' is created with approval_required=true + approved_at=NULL and is HELD —
  -- claim_queued_claude_run skips it — until approve_claude_run sets approved_at.
  -- Mirrors the playwright_runs approval gate (approval_required + approved_at).
  approval_required boolean DEFAULT false NOT NULL,
  approved_at timestamp with time zone,
  approved_by uuid,
  awaiting text,
  decision_id uuid REFERENCES public.ai_decisions ON DELETE SET NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT agent_runs_kind_check CHECK ((kind = ANY (ARRAY['plugin-exec'::text, 'workflow-exec'::text, 'repo-agent'::text, 'doc-agent'::text, 'claude_cli_task'::text]))),
  CONSTRAINT agent_runs_profile_check CHECK ((profile = ANY (ARRAY['docker'::text, 'kata-firecracker'::text, 'kata-dragonball'::text]))),
  CONSTRAINT agent_runs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'succeeded'::text, 'failed'::text, 'timeout'::text, 'cancelled'::text]))),
  PRIMARY KEY (id),
  CONSTRAINT agent_runs_requested_by_fkey FOREIGN KEY (requested_by) REFERENCES aisha_auth.users(id)
);

ALTER TABLE public.agent_runs ENABLE ROW LEVEL SECURITY;

-- Heal: `inputs` was added by fe939cf1 (agent-activity). CREATE TABLE IF NOT
-- EXISTS above does not add it to a pre-existing agent_runs, so seed/runtime
-- INSERTs referencing inputs fail on upgraded DBs. Idempotent ADD COLUMN IF NOT
-- EXISTS heals them (nullable → safe on existing rows; no-op on fresh DBs).
ALTER TABLE public.agent_runs ADD COLUMN IF NOT EXISTS inputs jsonb;

-- Heal: `outputs` is the executor's STRUCTURED result (the validated `__result`
-- sentinel + a log tail) — symmetric with `inputs`. Same idempotent ADD COLUMN
-- IF NOT EXISTS pattern so upgraded DBs gain it (nullable → safe; no-op on fresh).
ALTER TABLE public.agent_runs ADD COLUMN IF NOT EXISTS outputs jsonb;

-- Heal: admission/approval columns (E0 — an fn_admit_clow 'ask' verdict holds a run
-- pending human approval). Idempotent ADD COLUMN IF NOT EXISTS so upgraded DBs gain
-- them (defaulted/nullable → safe on existing rows; no-op on fresh).
ALTER TABLE public.agent_runs ADD COLUMN IF NOT EXISTS approval_required boolean DEFAULT false NOT NULL;
ALTER TABLE public.agent_runs ADD COLUMN IF NOT EXISTS approved_at timestamp with time zone;
ALTER TABLE public.agent_runs ADD COLUMN IF NOT EXISTS approved_by uuid;
ALTER TABLE public.agent_runs ADD COLUMN IF NOT EXISTS awaiting text;
ALTER TABLE public.agent_runs ADD COLUMN IF NOT EXISTS decision_id uuid;

COMMENT ON TABLE public.agent_runs IS 'Execution plane records — each isolated workload run (plugin, workflow, agent) tracked here.';
COMMENT ON COLUMN public.agent_runs.approval_required IS 'True when fn_admit_clow returned ask for this run — held (claim skips it) until approve_claude_run sets approved_at. Mirrors playwright_runs.';
COMMENT ON COLUMN public.agent_runs.awaiting IS 'The admission axis awaiting approval (e.g. risk_approval) when approval_required — surfaced to Mission Control via list_pending_claude_approvals.';
COMMENT ON COLUMN public.agent_runs.decision_id IS 'The ai_decisions row (I1 journal) minted for this dispatch by fn_record_execution_decision — links the run to its admission verdict.';
COMMENT ON COLUMN public.agent_runs.inputs IS 'Structured run inputs (jsonb). For kind=claude_cli_task: {story_id, prompt, base_ref, branch, auth_mode, context_profile}. Large/external inputs use inputs_s3_uri instead.';
COMMENT ON COLUMN public.agent_runs.outputs IS 'Structured run result (jsonb). For kind=claude_cli_task: {ok, run_id, exit_code} from the schema-validated `__result` sentinel + a trailing log slice. NULL until the run finalizes. Large/external outputs use outputs_s3_uri instead.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/ai_decision_candidates.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: ai_decision_candidates  (E0 decision lens — per-candidate ranking)
-- Purpose: The resolver already RETURNS a full per-candidate score breakdown + reasoning on every
--          decision, and fn_record_execution_decision stores it inside ai_decisions.decision_json
--          — but as an opaque blob. This normalizes that blob into queryable rows so an operator
--          can answer "why did candidate X score 0.73 / why was Y the winner" without hand-parsing
--          JSON. One row per candidate considered for a decision; written ONLY by
--          fn_record_execution_decision (alongside the ai_decisions row), forward-only.
-- Security: RLS inherits the parent decision's story scope (admin/staff read all).
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.ai_decision_candidates (
  id            uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  decision_id   uuid        NOT NULL REFERENCES public.ai_decisions(id) ON DELETE CASCADE,
  rank          integer     NOT NULL,                 -- 1 = top (highest score)
  is_top        boolean     NOT NULL DEFAULT false,
  provider_slug text,
  model_id      text,
  backend_kind  text,
  score         numeric(8,4),
  -- The resolver's transparent breakdown string: 'bench=.. local_bonus=.. cost_match=.. ..'
  reason        text,
  created_at    timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE public.ai_decision_candidates IS
  'Per-candidate ranking for an ai_decisions row (the resolver score breakdown, normalized from decision_json). Written only by fn_record_execution_decision. Lets the admin drilldown show WHY a model won.';

-- Index lives in aisha/db/sql/indexes/idx_ai_decision_candidates_decision.sql (SoT separation).
-- RLS lives in aisha/db/sql/rls/ai_decision_candidates.sql (emitted after functions).

ALTER TABLE public.ai_decision_candidates ENABLE ROW LEVEL SECURITY;


