-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/ai_resolver_policy.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: ai_resolver_policy
-- Purpose: Operator-tunable weights + thresholds for the orchestration-decision
--          resolver (public.aisha_resolve_clow_backend). Until this table, the
--          decision FUNCTION was 100% hardcoded literals (scoring weights, cost-
--          class cutoffs, batch thresholds, health allow-set, missing-data
--          defaults) — the candidate SET was registry-dynamic but the decision
--          POLICY could not be tuned without a code change. This is the single
--          operator-facing SoT for that policy: one seeded GLOBAL row carrying
--          today's exact literals, editable per scope×task-kind.
--          Resolution (most specific active row wins, like ai_spend_policies):
--            (story|instance, kind) > (story|instance, *) > (global, kind) > (global, *)
--          The GLOBAL row is the platform default and MUST always exist — the
--          resolver fails LOUD on its absence (no silent re-baked literal).
-- Read by:   public.aisha_resolve_clow_backend (wired in the follow-up PR; this
--            PR ships the substrate + seed with NO behaviour change).
-- Managed by: set_ai_resolver_policy_audited() (admin/staff) — follow-up PR.
-- @scope-reserved: story, instance
--   global is the platform-wide policy axis read by the resolver. story + instance
--   are forward-looking seams (per-context / per-instance weight overrides) —
--   accepted by the CHECK so a scoped policy can be authored ahead of reader
--   wiring, but INTENTIONALLY non-binding until the resolver reads them. Kept
--   honest by the scope-type-write-read-parity gate.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.ai_resolver_policy (
  id                           uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  -- 'global' (scope_id NULL) | 'story' | 'instance'
  scope_type                   text        NOT NULL DEFAULT 'global',
  scope_id                     uuid,
  -- NULL = applies to all task kinds within the scope ('*' wildcard row)
  task_kind                    text,

  -- Scoring weights — applied to each candidate's score in aisha_resolve_clow_backend:
  --   score = bench*bench_weight + local_bonus + cost_match_weight + tool/vision weights
  bench_weight                 numeric(6,4) NOT NULL DEFAULT 0.55,
  local_bonus                  numeric(6,4) NOT NULL DEFAULT 0.20,
  cost_match_weight            numeric(6,4) NOT NULL DEFAULT 0.15,
  tool_match_weight            numeric(6,4) NOT NULL DEFAULT 0.05,
  vision_match_weight          numeric(6,4) NOT NULL DEFAULT 0.05,

  -- Cost-class boundaries (USD): budget when budget_remaining < floor OR max_cost < budget_max;
  -- premium when max_cost > premium_max; else standard.
  budget_remaining_floor   numeric(10,4) NOT NULL DEFAULT 1.00,
  budget_max_cost          numeric(10,4) NOT NULL DEFAULT 0.50,
  premium_max_cost         numeric(10,4) NOT NULL DEFAULT 5.00,

  -- Batch eligibility thresholds.
  batch_min_deadline_hours     integer     NOT NULL DEFAULT 24,
  batch_min_tokens             integer     NOT NULL DEFAULT 50000,

  -- Health states a provider may be in to remain eligible.
  health_allow_set             text[]      NOT NULL DEFAULT ARRAY['healthy','unknown'],

  -- Missing-data defaults the resolver COALESCEs to when a caller omits an input.
  default_bench                numeric(6,4) NOT NULL DEFAULT 0.5,
  default_expected_tokens      integer     NOT NULL DEFAULT 5000,
  default_deadline_hours       integer     NOT NULL DEFAULT 24,
  default_max_cost         numeric(10,4) NOT NULL DEFAULT 1.00,
  default_budget_remaining numeric(10,4) NOT NULL DEFAULT 5.00,

  is_active                    boolean     NOT NULL DEFAULT true,
  created_by                   uuid,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  updated_at                   timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT ai_resolver_policy_scope_check
    CHECK (scope_type IN ('global', 'story', 'instance')),
  CONSTRAINT ai_resolver_policy_scope_id_presence
    CHECK ((scope_type = 'global') = (scope_id IS NULL)),
  -- Weights are non-negative (a negative weight would invert ranking semantics).
  CONSTRAINT ai_resolver_policy_weights_nonneg
    CHECK (bench_weight >= 0 AND local_bonus >= 0 AND cost_match_weight >= 0
           AND tool_match_weight >= 0 AND vision_match_weight >= 0),
  -- Cost-class boundaries must be ordered (budget cutoff <= premium cutoff).
  CONSTRAINT ai_resolver_policy_cost_order
    CHECK (budget_max_cost <= premium_max_cost),
  -- Positive operational thresholds.
  CONSTRAINT ai_resolver_policy_thresholds_pos
    CHECK (batch_min_deadline_hours > 0 AND batch_min_tokens > 0
           AND default_expected_tokens > 0 AND default_deadline_hours > 0),
  -- Health allow-set must be non-empty (an empty set would exclude every provider).
  CONSTRAINT ai_resolver_policy_health_nonempty
    CHECK (cardinality(health_allow_set) > 0),
  CONSTRAINT ai_resolver_policy_scope_kind_uniq
    UNIQUE NULLS NOT DISTINCT (scope_type, scope_id, task_kind)
);

COMMENT ON TABLE public.ai_resolver_policy IS
  'Operator-tunable weights/thresholds for aisha_resolve_clow_backend. Most specific active row wins; the GLOBAL row is the always-present platform default (resolver fails loud if absent).';

-- Index lives in aisha/db/sql/indexes/idx_ai_resolver_policy_lookup.sql (SoT separation).
-- RLS lives in aisha/db/sql/rls/ai_resolver_policy.sql (emitted after functions).
-- updated_at trigger lives in aisha/db/sql/triggers/ai_resolver_policy_updated_at.sql.

ALTER TABLE public.ai_resolver_policy ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/ai_risk_policies.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: ai_risk_policies
-- Purpose: User-set RISK authorization thresholds — the governance-as-policy
--          mechanism deciding whether a clow of a given computed risk_level may
--          dispatch. Risk is COMPUTED from the clow (criticality, side-effect
--          class) into an ordinal band (low < medium < high < critical); the
--          chosen band is compared against this scope's threshold tuple:
--            computed risk <= auto_allow_at_or_below → allow (silent)
--            computed risk >  ask_above              → ask (blocked + human
--                                                       approval triggered BY
--                                                       RISK, not by membership)
--            computed risk >  deny_above             → deny (hard policy ceiling)
--          Resolution mirrors ai_spend_policies — most specific active row wins:
--            (scope story, kind) > (scope story, *) > (global, kind) > (global, *)
--          No row matched → conservative built-in default band (NOT a stored
--          list). This is a THRESHOLD TUPLE per scope, never a roster of
--          permitted names: the clow governs itself via its own computed risk;
--          the policy only sets where the allow/ask/deny boundaries fall.
-- Managed by: set_ai_risk_policy_audited() (admin/staff); read by the admission
--             composer / risk evaluator and the Mission Control policy card.
-- Mirrors the shape of ai_spend_policies (USD bands → ordinal risk bands).
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.ai_risk_policies (
  id                    uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  -- 'global' (scope_id NULL) | 'story' | 'partner'
  scope_type            text        NOT NULL DEFAULT 'global',
  scope_id              uuid,
  -- NULL = applies to all kinds within the scope ('*' wildcard row)
  task_kind             text,
  -- Ordinal risk bands (low < medium < high < critical). Each column is a
  -- SINGLE threshold value (rather than a list of permitted things).
  auto_allow_at_or_below text       CHECK (auto_allow_at_or_below IS NULL OR auto_allow_at_or_below IN ('low', 'medium', 'high', 'critical')),
  ask_above             text        CHECK (ask_above IS NULL OR ask_above IN ('low', 'medium', 'high', 'critical')),
  deny_above            text        CHECK (deny_above IS NULL OR deny_above IN ('low', 'medium', 'high', 'critical')),
  is_active             boolean     NOT NULL DEFAULT true,
  created_by            uuid,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),

  -- scope_type: global + story are the ENFORCED axes (read by fn_admit_clow's risk-policy
  -- resolution, most-specific-wins). partner is a RESERVED forward-looking seam — accepted by
  -- the CHECK so a partner risk policy can be authored ahead of reader wiring, but no enforcer
  -- reads it yet and nothing writes it → INTENTIONALLY non-binding (a recorded seam, NOT a
  -- fail-open). The scope-type-write-read-parity gate catches a future CHECK scope that is
  -- neither enforced nor reserved-here. @scope-reserved: partner
  CONSTRAINT ai_risk_policies_scope_check
    CHECK (scope_type IN ('global', 'story', 'partner')),
  CONSTRAINT ai_risk_policies_scope_id_presence
    CHECK ((scope_type = 'global') = (scope_id IS NULL)),
  -- Threshold coherence on the ordinal band (mirrors ai_spend_policies order
  -- invariant): allow boundary <= ask boundary <= deny boundary. The rank
  -- expression is an inline ordinal map (rather than a maintained allow-list).
  CONSTRAINT ai_risk_policies_threshold_order
    CHECK (
      (auto_allow_at_or_below IS NULL OR ask_above IS NULL
        OR CASE auto_allow_at_or_below
             WHEN 'low' THEN 1 WHEN 'medium' THEN 2 WHEN 'high' THEN 3 WHEN 'critical' THEN 4 END
           <= CASE ask_above
             WHEN 'low' THEN 1 WHEN 'medium' THEN 2 WHEN 'high' THEN 3 WHEN 'critical' THEN 4 END)
      AND (ask_above IS NULL OR deny_above IS NULL
        OR CASE ask_above
             WHEN 'low' THEN 1 WHEN 'medium' THEN 2 WHEN 'high' THEN 3 WHEN 'critical' THEN 4 END
           <= CASE deny_above
             WHEN 'low' THEN 1 WHEN 'medium' THEN 2 WHEN 'high' THEN 3 WHEN 'critical' THEN 4 END)
    ),
  CONSTRAINT ai_risk_policies_scope_kind_uniq
    UNIQUE NULLS NOT DISTINCT (scope_type, scope_id, task_kind)
);

COMMENT ON TABLE public.ai_risk_policies IS
  'User-set allow/ask/deny risk-band thresholds per scope x task-kind. Risk is computed per clow and compared to this tuple; most specific active row wins. A threshold tuple, NOT a list of permitted entities.';

-- Index lives in aisha/db/sql/indexes/idx_ai_risk_policies_lookup.sql (SoT separation).
-- RLS policies live in aisha/db/sql/rls/ai_risk_policies.sql (emitted AFTER
-- functions in the baseline so is_admin_or_staff/auth.role exist when they bind).

ALTER TABLE public.ai_risk_policies ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/ai_runtime_registry.sql
-- -----------------------------------------------------------------------------

-- Table: ai_runtime_registry
-- AISHA's catalog of EXECUTION RUNTIMES — the entities that can actually carry
-- out a clow once AISHA has decided what to do. This is the runtime-axis sibling
-- of ai_provider_registry (which catalogs *model* providers): a runtime answers
-- "by what mechanism does this work get executed" (direct LLM call, OpenClaw,
-- Hermes, an n8n workflow, a human, or a registered CLI), whereas a provider
-- answers "which model backend serves the tokens".
--
-- CAPABILITY-AVAILABILITY, NOT AN ALLOW-LIST.
--   A runtime is USABLE iff it is REGISTERED here AND governs itself as available
--   (is_enabled = true) AND its adapter is reachable (adapter_health <> 'down').
--   Adding a new runtime (e.g. hermes, cli:claude-cli) = inserting one self-
--   describing row whose adapter self-registers; there is NOTHING to maintain
--   elsewhere. This table holds NO list of "permitted" names — every column below
--   is per-entity self-governance (the entity declares its own state/capability),
--   exactly as ai_provider_registry.is_enabled / supports_tool_use already work.
--   The resolver derives availability by FILTERING this registry (WHERE is_enabled
--   AND adapter healthy), the same way aisha_resolve_clow_backend filters
--   ai_provider_registry — never by consulting a hardcoded set of allowed runtimes.
--
-- CAPABILITY MATCH is DERIVED, not listed.
--   A clow's needs (needs_write / needs_internet / needs_tools) are checked
--   against the chosen runtime's DECLARED capabilities (can_write / needs_network
--   / supports_tools) — a per-entity boolean comparison, not membership in a
--   separately-maintained list.
--
-- GOVERNANCE is POLICY (thresholds/risk), not lists.
--   Risk is COMPUTED from the clow (criticality × side_effect_class × autonomy_
--   class) → threshold → allow/ask/deny, with spend governed by ai_spend_policies.
--   Human approval is triggered by RISK, never by a runtime's presence in a list.

CREATE TABLE IF NOT EXISTS public.ai_runtime_registry (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),

  -- Runtime kind controls how AISHA hands the work off (which adapter executes it).
  runtime_kind text NOT NULL CHECK (runtime_kind IN (
    'direct_llm',            -- AISHA calls a model provider directly (single-shot / reflection nodes)
    'openclaw',              -- dispatched to the OpenClaw clow executor
    'hermes',                -- dispatched to the Hermes learning/execution runtime
    'workflow',              -- handed to an n8n workflow (WF_*) for execution
    'human',                 -- routed to a human operator (Mission Control approval / manual step)
    'cli',                   -- handed to a registered CLI adapter (e.g. cli:claude-cli)
    'workbench'              -- run via the VSCode workbench extension (local ollama/llama.cpp models the extension discovers + reports into this same registry)
  )),

  -- Stable identifier the resolver + adapters key on. For multi-instance kinds
  -- (e.g. several CLIs) the slug disambiguates: 'direct_llm', 'openclaw',
  -- 'hermes', 'workflow', 'human', 'cli:claude-cli'.
  slug text NOT NULL UNIQUE,
  display_name text NOT NULL,

  -- Self-governed availability. The runtime owns this flag; the resolver derives
  -- "usable" by filtering on it (NOT by checking a list of permitted runtimes).
  is_enabled boolean NOT NULL DEFAULT true,

  -- Adapter health (set by probe; AISHA reads it as resolver input). A runtime
  -- with no registered/reachable adapter resolves to unavailable.
  adapter_health text NOT NULL DEFAULT 'unknown' CHECK (adapter_health IN ('healthy', 'degraded', 'down', 'unknown')),
  adapter_health_checked_at timestamptz,
  -- Consecutive non-healthy probes. Incremented on degraded/down, RESET to 0 on
  -- healthy — drives exponential backoff for the runtime health probe, mirroring
  -- ai_provider_registry.consecutive_failure_count.
  consecutive_failure_count int NOT NULL DEFAULT 0,

  -- DECLARED capabilities of this runtime. Matched against a clow's needs
  -- (needs_write / needs_internet / needs_tools) — derived comparison, not a list.
  can_write boolean NOT NULL DEFAULT false,         -- may perform write / side-effecting actions
  needs_network boolean NOT NULL DEFAULT false,     -- requires outbound network / internet access
  supports_tools boolean NOT NULL DEFAULT false,    -- can use tools (tool-use / function calling)

  -- Whether this runtime KIND executes via the in-process executeViaRuntime adapter
  -- axis (RUNTIME_ADAPTERS in services/svc-ai-chat/.../runtime/adapters.ts) — true for
  -- direct_llm/openclaw/hermes/workbench/cli; false for OUT-OF-BAND surfaces that have
  -- no RuntimeAdapter (human = Mission-Control inbox, workflow = n8n hand-off). The
  -- resolver derives auto-derivability by FILTERING on this self-declared flag, NOT a
  -- hardcoded NOT IN ('human','workflow') list — the same per-entity self-governance as
  -- can_write/needs_network/supports_tools. Defaults false so a runtime is fail-safe: it
  -- is never auto-derived as an executor until it DECLARES it has an adapter, so a future
  -- out-of-band runtime cannot silently resolve to a missing-adapter throw.
  -- COUPLING: when a real adapter ships for a kind, add it to RUNTIME_ADAPTERS AND set
  -- this row's is_in_process_executor=true in the SAME change.
  is_in_process_executor boolean NOT NULL DEFAULT false,

  -- Risk inputs. Combined with the clow's criticality to COMPUTE a risk level,
  -- which a threshold then maps to allow/ask/deny (governance = policy, not list).
  side_effect_class text NOT NULL DEFAULT 'read_only' CHECK (side_effect_class IN (
    'read_only',             -- observes / reads only, no external effect
    'reversible',            -- writes that can be undone / rolled back
    'irreversible'           -- writes with permanent external effect
  )),
  autonomy_class text NOT NULL DEFAULT 'supervised' CHECK (autonomy_class IN (
    'supervised',            -- every action gated by human review
    'semi',                  -- acts autonomously up to a risk/spend threshold
    'autonomous'             -- acts without per-action human gating
  )),

  notes text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,

  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.ai_runtime_registry ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.ai_runtime_registry IS
  'Capability-availability registry of execution runtimes (direct_llm/openclaw/hermes/workflow/human/cli). A runtime is usable iff registered AND is_enabled AND its adapter is healthy; clow needs are matched against per-entity declared capabilities. No allow-list — self-governing rows the resolver filters, mirroring ai_provider_registry.';

-- Indexes (e.g. idx_ai_runtime_registry_enabled, idx_ai_runtime_registry_health)
-- live in aisha/db/sql/indexes/; RLS policies live in aisha/db/sql/policies/;
-- the updated_at trigger lives in aisha/db/sql/triggers/ — per SQL Source
-- Separation rule, mirroring ai_provider_registry.


