-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/aisha_static_defense_rules.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Table: aisha_static_defense_rules
-- Purpose: Source-of-truth for static defense rules (Semgrep, ESLint policy
--   bits) that get generated INTO .semgrep/aisha-rules.yml + other tooling
--   config files via `npm run gen:static-defense`.
--
-- Why in DB: per AISHA design, policy ≡ knowledge ≡ DB. Hand-managed YAML
-- in repo can't be extended by Aisha autonomously and can't be tuned from
-- Appsmith UI. CLAUDE.md uses the same generated-from-DB pattern.
--
-- Lifecycle: draft → active (admin approval) → deprecated. Only `active`
-- rows are exported by the generator. Audit trail on every status change.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.aisha_static_defense_rules (
  -- Stable identifier referenced from generated YAML / config
  rule_id          text PRIMARY KEY,

  -- Which tool consumes this rule. Determines generator output target.
  --   'semgrep'         → .semgrep/aisha-rules.yml entry
  --   'eslint-no-secrets' → eslint.config.js additionalRegexes block
  --   'owasp-exemption' → owasp-orchestrator-adoption.gate exemption entry
  category         text NOT NULL CHECK (category IN (
    'semgrep', 'eslint-no-secrets', 'owasp-exemption'
  )),

  -- OWASP / AITG category this rule defends. Free-text label, used for
  -- grouping in operator UI + Aisha reflection summaries.
  owasp_category   text,                                       -- e.g. 'A10', 'A03', 'AITG-APP-01'

  -- Semgrep-specific fields (NULL for other categories)
  semgrep_pattern  jsonb,                                      -- pattern-either array or single pattern
  semgrep_paths    jsonb,                                      -- {include, exclude} object
  semgrep_message  text,                                       -- human-readable explanation
  languages        text[] DEFAULT ARRAY['typescript']::text[],

  -- Severity (mapped to tool-specific enum at generation time)
  severity         text NOT NULL CHECK (severity IN ('ERROR', 'WARNING', 'INFO')),

  -- Lifecycle
  status           text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'deprecated')),
  version          integer NOT NULL DEFAULT 1,

  -- Provenance
  proposed_by      text,                                       -- 'aisha-autonomous', 'operator-{user_id}', 'seed-2026-05-17'
  approved_by      uuid,                                       -- auth.uid() at publish time; NULL while draft
  rationale        text,                                       -- WHY this rule exists (shown in operator UI)

  -- Auto-bumped on every UPDATE
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.aisha_static_defense_rules ENABLE ROW LEVEL SECURITY;

-- Indexes live in aisha/db/sql/indexes/idx_aisha_static_defense_rules_*.sql
-- RLS policy lives in aisha/db/sql/policies/aisha_static_defense_rules_admin_all.sql
-- (one file per artifact — SoT source-separation convention).

COMMENT ON TABLE public.aisha_static_defense_rules IS
  'SoT for static defense rules generated into repo. Edit via Appsmith UI or RPC '
  '(aisha_propose_static_defense_rule + aisha_publish_static_defense_rule), never '
  'edit .semgrep/aisha-rules.yml directly.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/aisha_tooling_proposals.sql
-- -----------------------------------------------------------------------------

-- Table: aisha_tooling_proposals
-- AISHA-generated Claude Code skill/hook/command proposals.
-- Propagated do .claude/ po approval gate via GitHub PR (managed by WF_AISHA_TOOLING_COMMITTER).
-- Source: docs/deploy/AISHA_SELF_TOOLING.md (META-2 vrstva nad AUTONOMOUS_DEPLOY_FLOW)

CREATE TABLE IF NOT EXISTS public.aisha_tooling_proposals (
  id                  uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  proposed_at         timestamptz  NOT NULL DEFAULT now(),
  proposal_kind       text         NOT NULL CHECK (proposal_kind IN ('skill', 'hook', 'command')),
  artifact_name       text         NOT NULL,           -- 'aisha-blue-green-debug'
  artifact_path       text         NOT NULL,           -- '.claude/skills/.../SKILL.md'
  artifact_content    text         NOT NULL,           -- generated content
  trigger_pattern     jsonb        NOT NULL,           -- pattern that motivated proposal
  occurrence_count    int          NOT NULL DEFAULT 0,
  decision_provenance jsonb        NOT NULL DEFAULT '[]'::jsonb,
  approval_status     text         NOT NULL DEFAULT 'pending'
                      CHECK (approval_status IN (
                        'pending', 'approved', 'rejected', 'expired',
                        'committed', 'reverted'
                      )),
  approval_id         uuid,
  approved_by         uuid,
  approved_at         timestamptz,
  committed_sha       text,                            -- git commit SHA (GitHub contents API) of the artifact
  committed_at        timestamptz,
  reverted_sha        text,                            -- if reverted later
  reverted_at         timestamptz,
  manual_locked       boolean      NOT NULL DEFAULT false,
                                                       -- true = admin lock, AISHA neoverwrites
  proposal_bundle_id  uuid,                            -- group multiple proposals
  metadata            jsonb        NOT NULL DEFAULT '{}'::jsonb,
  created_at          timestamptz  NOT NULL DEFAULT now(),
  updated_at          timestamptz  NOT NULL DEFAULT now(),
  UNIQUE (proposal_kind, artifact_path)
);

COMMENT ON TABLE public.aisha_tooling_proposals IS
  'AISHA-generated Claude Code skill/hook/command proposals. Propagated do .claude/ po approval gate via GitHub PR (managed by WF_AISHA_TOOLING_COMMITTER).';
COMMENT ON COLUMN public.aisha_tooling_proposals.trigger_pattern IS
  'Detected pattern (action_sequence, occurrence_count, success_rate) that motivated  this proposal. Used pro decision provenance + dedup check.';
COMMENT ON COLUMN public.aisha_tooling_proposals.manual_locked IS
  'When true, AISHA neoverwrites tento artifact even if pattern still active.  Set by admin po manuální editaci.';
COMMENT ON COLUMN public.aisha_tooling_proposals.proposal_bundle_id IS
  'Optional: groups proposals that should be approved+committed atomically  (e.g., skill + hook for same pattern).';

ALTER TABLE public.aisha_tooling_proposals ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/aitg_aisha_reflections.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Table: aitg_aisha_reflections
-- Purpose: Aisha's daily diary about her own security posture. Each row is
--          one snapshot — trust score now vs previous day, what's open, what
--          changed, what she intends to do about it. This is the durable
--          memory that lets her remember her trajectory across sessions.
--
-- Aisha reads back her own history via aitg_get_reflection_history_audited
-- when she "wakes up" (start of a session / start of a workflow) so she has
-- continuity with her past self.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.aitg_aisha_reflections (
  reflection_id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  reflection_date         date NOT NULL,
  trust_score_snapshot    numeric NOT NULL CHECK (trust_score_snapshot BETWEEN 0 AND 100),
  trust_score_delta       numeric,            -- vs previous reflection
  total_runs_window       int NOT NULL DEFAULT 0,
  failed_runs_window      int NOT NULL DEFAULT 0,
  open_findings_count     int NOT NULL DEFAULT 0,
  new_failures_count      int NOT NULL DEFAULT 0,
  newly_fixed_count       int NOT NULL DEFAULT 0,
  drift_alerts_count      int NOT NULL DEFAULT 0,
  summary                 text NOT NULL CHECK (length(summary) >= 10),
  proposed_actions        jsonb NOT NULL DEFAULT '[]'::jsonb,
  generated_by            text NOT NULL DEFAULT 'aisha',
  created_at              timestamptz NOT NULL DEFAULT now(),
  UNIQUE (reflection_date, generated_by)
);

ALTER TABLE public.aitg_aisha_reflections ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/aitg_automation_settings.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Table: aitg_automation_settings
-- Purpose: Operator-controllable cadence + parameters for every AITG
--          automation (continuous heartbeat, daily reflection, nightly full
--          sweep, drift detection, auto-close findings, runtime sentinel,
--          PR gate, mode-of-operation defaults).
--
-- Modes:
--   - 'automated'  → workflow runs on its configured schedule
--   - 'manual'     → workflow only runs on operator/Aisha "trigger" button
--   - 'disabled'   → workflow short-circuits at the read-setting step
--
-- The settings row is the source of truth. Every WF_AITG_* workflow first
-- reads its row, exits early if disabled, honours interval/cron overrides,
-- and records last_run_at after execution. The Appsmith "AITG Automation
-- Control" page reads/writes this table through audited RPCs.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.aitg_automation_settings (
  automation_id        text PRIMARY KEY
                         CHECK (automation_id ~ '^[a-z][a-z0-9_]+$'),
  display_name         text NOT NULL,
  description          text NOT NULL,
  mode                 text NOT NULL DEFAULT 'automated'
                         CHECK (mode IN ('automated', 'manual', 'disabled')),
  schedule_cron        text,
  schedule_interval_minutes int CHECK (schedule_interval_minutes IS NULL
                                       OR schedule_interval_minutes BETWEEN 1 AND 1440),
  parameters           jsonb NOT NULL DEFAULT '{}'::jsonb,
  workflow_id          text,                    -- n8n workflow id when applicable
  last_run_at          timestamptz,
  last_run_status      text CHECK (last_run_status IS NULL
                                   OR last_run_status IN ('success','failed','skipped','running')),
  last_run_details     jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at           timestamptz NOT NULL DEFAULT now(),
  updated_by           uuid REFERENCES aisha_auth.users(id),
  created_at           timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT aitg_automation_settings_schedule_exclusive CHECK (
    -- exactly one of cron / interval may be set when mode = automated
    NOT (mode = 'automated' AND schedule_cron IS NOT NULL AND schedule_interval_minutes IS NOT NULL)
  )
);

ALTER TABLE public.aitg_automation_settings ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/aitg_test_catalog.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Table: aitg_test_catalog
-- Purpose: Canonical catalog of OWASP AI Testing Guide (AITG) v1 — 44 tests
--          across 4 layers (APP/MOD/INF/DAT). Seed data — append-only via
--          migration; never write at runtime.
-- ============================================================================

-- PostgreSQL does NOT support `CREATE TYPE IF NOT EXISTS`. Use idempotent
-- DO $$ EXCEPTION WHEN duplicate_object pattern — matches the same shape
-- used by the migration 20260516144654_aitg_baseline.sql that introduced
-- these types, so baseline regeneration produces valid SQL.
DO $$ BEGIN
  CREATE TYPE aitg_layer AS ENUM ('app', 'mod', 'inf', 'dat');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE aitg_severity AS ENUM ('info', 'low', 'medium', 'high', 'critical');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE aitg_status AS ENUM ('passed', 'failed', 'flaky', 'blocked', 'waived', 'not_applicable');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE TABLE IF NOT EXISTS public.aitg_test_catalog (
  test_id          text PRIMARY KEY CHECK (test_id ~ '^AITG-(APP|MOD|INF|DAT)-\d{2}$'),
  layer            aitg_layer NOT NULL,
  title            text NOT NULL,
  objective        text NOT NULL,
  remediation_ref  text NOT NULL,
  lifecycle_phases text[] NOT NULL DEFAULT '{}'::text[],
  severity_weight  numeric NOT NULL DEFAULT 1.0 CHECK (severity_weight >= 0),
  enabled          boolean NOT NULL DEFAULT true,
  created_at       timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.aitg_test_catalog ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/aitg_drift_alerts.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Table: aitg_drift_alerts
-- Purpose: Time-series regression signal. The drift-detection RPC compares
--          pass-rate over two adjacent windows; when the delta crosses a
--          threshold (e.g. -10pp WoW), a row lands here. Rows stay until
--          either acknowledged (operator triage) or resolved (subsequent
--          runs return to baseline).
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.aitg_drift_alerts (
  alert_id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  test_id          text NOT NULL REFERENCES public.aitg_test_catalog(test_id),
  window_label     text NOT NULL,           -- '24h', '7d', etc.
  current_pass_rate  numeric NOT NULL CHECK (current_pass_rate BETWEEN 0 AND 1),
  previous_pass_rate numeric NOT NULL CHECK (previous_pass_rate BETWEEN 0 AND 1),
  delta            numeric NOT NULL,        -- current - previous
  severity         aitg_severity NOT NULL,
  acknowledged_at  timestamptz,
  acknowledged_by  uuid REFERENCES aisha_auth.users(id),
  resolved_at      timestamptz,
  details          jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at       timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.aitg_drift_alerts ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/aitg_payloads.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Table: aitg_payloads
-- Purpose: Adversarial corpus (red-team prompts, evasion vectors, etc.).
-- RLS: SENSITIVE — only admin/staff/auditor may read. Leaking this corpus to
--      anon would arm attackers with a curated jailbreak list.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.aitg_payloads (
  payload_id     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  test_id        text NOT NULL REFERENCES public.aitg_test_catalog(test_id),
  payload        jsonb NOT NULL,
  expected_block text NOT NULL,
  tags           text[] NOT NULL DEFAULT '{}'::text[],
  source         text NOT NULL DEFAULT 'internal',
  active         boolean NOT NULL DEFAULT true,
  created_at     timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.aitg_payloads ENABLE ROW LEVEL SECURITY;

-- Columns added by later migrations (back-port reconciliation):
ALTER TABLE public.aitg_payloads ADD COLUMN IF NOT EXISTS last_seen_at timestamp with time zone;
ALTER TABLE public.aitg_payloads ADD COLUMN IF NOT EXISTS consecutive_passes integer NOT NULL DEFAULT 0;
ALTER TABLE public.aitg_payloads ADD COLUMN IF NOT EXISTS consecutive_failures integer NOT NULL DEFAULT 0;
ALTER TABLE public.aitg_payloads ADD COLUMN IF NOT EXISTS quarantined_at timestamp with time zone;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/aitg_payload_proposals.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Table: aitg_payload_proposals
-- Purpose: Aisha (or any service_role caller) proposes a new adversarial
--          payload. Stays pending until admin/staff promotes via
--          aitg_approve_payload_audited (which copies into aitg_payloads with
--          active=true). Keeps the corpus growing without anon-writable
--          paths into the canonical aitg_payloads table.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.aitg_payload_proposals (
  proposal_id    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  test_id        text NOT NULL REFERENCES public.aitg_test_catalog(test_id),
  payload        jsonb NOT NULL,
  expected_block text NOT NULL,
  tags           text[] NOT NULL DEFAULT '{}'::text[],
  justification  text NOT NULL CHECK (length(justification) >= 20),
  proposed_by    text NOT NULL DEFAULT 'aisha',
  status         text NOT NULL DEFAULT 'pending'
                   CHECK (status IN ('pending', 'approved', 'rejected')),
  reviewed_by    uuid REFERENCES aisha_auth.users(id),
  reviewed_at    timestamptz,
  promoted_payload_id uuid REFERENCES public.aitg_payloads(payload_id),
  created_at     timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.aitg_payload_proposals ENABLE ROW LEVEL SECURITY;


