-- Table: data_sensitivity_registry
-- §11 residency: the DB-driven source of truth for which tables are sensitive.
-- Replaces the hardcoded CONFIDENTIAL_ANCHOR_TABLES literal in svc-ai-chat — a
-- 'confidential' row here forces on-prem residency (canUseCloudApis=false). The
-- svc reads it via get_data_sensitivity_registry() into a TTL cache (NEVER on the
-- hot path / SSE handshake) and fails SAFE to its built-in baseline list if this
-- registry is empty or unreachable (graceful degradation — never less strict).
-- RLS: ENABLED (global, non-PII config — authenticated read, admin write).
CREATE TABLE IF NOT EXISTS public.data_sensitivity_registry (
  table_name  text PRIMARY KEY,
  sensitivity public.data_sensitivity NOT NULL DEFAULT 'confidential',
  category    text,
  note        text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.data_sensitivity_registry ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/data_source_grants.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- data_source_grants — ke kterým ZDROJŮM DAT má uživatel udělený přístup.
--
-- ⭐ Majitel 2026-09-28: „ingest navrhuje vazby, protistrany… ale neměl by řešit, kdo
-- k čemu má přístup; MODĚVA, Avant… to jsou zdroje dat z Money, které chceme
-- zpřístupnit". Přístup je rozhodnutí SPRÁVY u uživatele, ne výsledek ingestu:
--   `instance:<druh>/<instance>` — instance zdroje, jak ji zapsal konektor do záznamu
--                                  (např. agenda Money „money/Areál Avant Ďáblická"),
--   `cesta:<adresář ve vstupu>`  — podstrom vstupu ingestu (i podsložky),
--   `firma:<IČO>`                — smluvní dokumenty, ve kterých je firma stranou
--                                  („vazba na firmy, které vidíme v přehledu"),
--   `vstup:dokumenty`            — všechny dokumenty zpracovaného vstupu ingestu (smlouvy…),
--   `udalosti:<zdroj>`           — dvojčata, o kterých má data zdroj (twin_events.source,
--                                  např. jednotky ze sez-vyuctovani) — majitel 2026-09-28:
--                                  „všechna data, ale rozdělená po zdrojích",
--   `vse:*`                      — PLNÝ přístup ke všem datům bez výběru (majitel
--                                  2026-09-28: „možnost bez omezení… omezit chceme
--                                  zachovat"); vyhodnocuje ma_plny_pristup_k_datum.
-- Nárok vyhodnocuje li_doc_slugs_v_rozsahu přes předpočítané klíče původu
-- (li_doc_scope_keys `@instance` / `@cesta` / `@firma`); protistrany dokladů ze zdrojů čte
-- twin_ids_v_rozsahu. Přístup do SEKCE je zvlášť (surface_section_grants).
--
-- Zápis jen hr_udel_zdroj_admin (správa, audit); RLS bez politik, žádné granty.
-- =============================================================================
CREATE TABLE IF NOT EXISTS public.data_source_grants (
  user_id     uuid        NOT NULL REFERENCES aisha_auth.users (id) ON DELETE CASCADE,
  zdroj       text        NOT NULL CHECK (zdroj ~ '^(instance|cesta|firma|vstup|udalosti|vse):.+'),
  granted_by  uuid,
  granted_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT data_source_grants_pkey PRIMARY KEY (user_id, zdroj)
);

COMMENT ON TABLE public.data_source_grants IS
  'Udělený přístup uživatele ke zdroji dat (instance:<druh>/<instance> | cesta:<adresář vstupu> | firma:<IČO> | vstup:dokumenty | udalosti:<zdroj> | vse:*). Nárok přes klíče původu v li_doc_scope_keys. Zápis jen hr_udel_zdroj_admin.';

-- Existující tabulka (nasazená bez `vse`): CHECK se v CREATE IF NOT EXISTS nezmění.
ALTER TABLE public.data_source_grants DROP CONSTRAINT IF EXISTS data_source_grants_zdroj_check;
ALTER TABLE public.data_source_grants ADD CONSTRAINT data_source_grants_zdroj_check
  CHECK (zdroj ~ '^(instance|cesta|firma|vstup|udalosti|vse):.+');

ALTER TABLE public.data_source_grants ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.data_source_grants FROM PUBLIC, anon, authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/delivery_statuses.sql
-- -----------------------------------------------------------------------------

-- Table: delivery_statuses
-- Lookup table for partner_stories.delivery_status pipeline (parallel to
-- workflow_statuses on the kanban side). Exposes per-status policy flags
-- that previously lived as hardcoded TS Sets in
-- services/svc-ai-chat/src/lib/governedOrchestration.ts:272-283.
--
-- Two key flags, both consumed by the governed orchestration layer:
--   requires_approval  — actions on a story in this status require admin
--                        approval (currently delivering / delivered / archived)
--   restricts_actions  — tool execution is restricted while a story is in
--                        this status (currently qa / delivering / delivered)
--
-- Pipeline transitions themselves live in delivery_transition_rules. This
-- table is per-status metadata; the two are complementary.

CREATE TABLE IF NOT EXISTS public.delivery_statuses (
  -- Stable identifier referenced by partner_stories.delivery_status.
  status text PRIMARY KEY,

  -- i18n key path for the display label, e.g.
  -- 'storyloop.deliveryStatuses.delivering'.
  label_i18n_key text NOT NULL,

  -- Pipeline order (ASC). Lower = earlier in the lifecycle.
  sort_order int NOT NULL DEFAULT 0,

  -- Optional UI hint (Tailwind class name or hex color).
  swimlane_color text,

  -- Governance flag: actions on stories in this status require admin
  -- approval (mirrors APPROVAL_REQUIRED_STATUSES Set).
  requires_approval boolean NOT NULL DEFAULT false,

  -- Governance flag: tool execution is restricted while in this status
  -- (mirrors RESTRICTED_ACTION_STATUSES Set).
  restricts_actions boolean NOT NULL DEFAULT false,

  -- Terminal statuses are end-of-pipeline.
  is_terminal boolean NOT NULL DEFAULT false,

  -- Soft-disable a status without dropping the row.
  is_active boolean NOT NULL DEFAULT true,

  -- Operator notes — surfaces in admin status manager.
  notes text,

  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.delivery_statuses ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.delivery_statuses IS
  'Source-of-truth for partner_stories.delivery_status pipeline metadata. Exposes per-status governance flags (requires_approval, restricts_actions) previously hardcoded in governedOrchestration.ts. Parallel to workflow_statuses (kanban side); transition graph in delivery_transition_rules.';

-- Indexes live in aisha/db/sql/indexes/idx_delivery_statuses_active_order.sql
-- per SQL Source Separation rule.


