-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/federated_flow_nonces.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: federated_flow_nonces
-- Popis: Použitá nonce stavu přihlašovacího toku begin → pokracuj (ADR-004, bod 4).
--
-- Stav mezi kroky nosí klient (AEAD klíčem brokeru). Aby byl JEDNORÁZOVÝ i při víc
-- replikách brokeru, evidence použitých nonce je tady — ne v paměti procesu, která
-- by se s replikami násobila. Prošlá nonce maže plánovač brokeru
-- (`federated_flow_nonces_cleanup`).
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.federated_flow_nonces (
  nonce       text PRIMARY KEY,
  -- CASCADE je tu správně (na rozdíl od trezoru relací): za nonce žádný token není,
  -- se smazaným uživatelem ztrácí smysl i jeho rozběhnutý přihlašovací tok.
  user_id     uuid NOT NULL REFERENCES aisha_auth.users(id) ON DELETE CASCADE,
  provider    text NOT NULL,
  expires_at  timestamptz NOT NULL,
  used_at     timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT federated_flow_nonces_nonce_delka CHECK (length(nonce) >= 16)
);

COMMENT ON TABLE public.federated_flow_nonces IS
  'Použitá nonce stavu přihlašovacího toku federace (jednorázovost napříč replikami brokeru). Jen servisní role.';

ALTER TABLE public.federated_flow_nonces ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.federated_flow_nonces FROM PUBLIC, anon, authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/federated_source_sessions.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: federated_source_sessions
-- Popis: Trezor relací uživatelů u federovaného zdroje (ADR-004).
--
-- Řádek = relace JEDNOHO uživatele aishy u JEDNOHO zdroje: token, kterým broker
-- volá zdroj JAKO TEN UŽIVATEL. Heslo se neukládá nikdy.
--
-- ⛔ ŠIFRUJE BROKER, NE DATABÁZE. `token_ct` / `refresh_ct` jsou AES-256-GCM
-- s klíčem FEDERATION_VAULT_KEY, který žije jen v tajemstvích brokeru (key_id pro
-- rotaci; AAD váže šifrový text na provider | user_id | id relace). Databáze drží
-- jen neprůhledné bajty. Důvod: obecné `aisha_decrypt_column_audited` je granted
-- authenticated a pouští admin/staff, a klíče sloupců i trezoru jsou v DB jako GUC
-- (`ALTER DATABASE … SET`, `PGOPTIONS`), tedy čitelné relacemi se SQL. Klíč v DB
-- by token nechránil.
--
-- ⛔ BEZ CIZÍHO KLÍČE na aisha_auth.users. Token u zdroje bez expirace platí,
-- dokud ho někdo výslovně neodhlásí. CASCADE by při smazání uživatele zahodil
-- šifrový text i evidenci — a token by u zdroje žil navždy. Relace smazaného
-- uživatele odvolá a odhlásí `federated_source_session_logout_due`.
--
-- Odvolání: `revoked_at` + `revoke_reason`; odhlášení u zdroje je fronta nad
-- týmiž řádky (`logout_done_at IS NULL`), zpracovává ji plánovač brokeru. Po
-- odhlášení se šifrový text maže (`token_ct` = prázdné bajty).
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.federated_source_sessions (
  id               uuid PRIMARY KEY,
  user_id          uuid NOT NULL,
  provider         text NOT NULL,
  provider_id      text NOT NULL,
  token_ct         bytea NOT NULL,
  refresh_ct       bytea,
  key_id           text NOT NULL,
  version          integer NOT NULL DEFAULT 1,
  expires_at       timestamptz NOT NULL,
  verified_at      timestamptz NOT NULL DEFAULT now(),
  revoked_at       timestamptz,
  revoke_reason    text,
  logout_done_at   timestamptz,
  logout_attempts  integer NOT NULL DEFAULT 0,
  logout_next_at   timestamptz,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT federated_source_sessions_provider_nonempty CHECK (length(btrim(provider)) > 0),
  CONSTRAINT federated_source_sessions_provider_id_nonempty CHECK (length(btrim(provider_id)) > 0),
  CONSTRAINT federated_source_sessions_key_id_nonempty CHECK (length(btrim(key_id)) > 0),
  CONSTRAINT federated_source_sessions_version_positive CHECK (version >= 1),
  CONSTRAINT federated_source_sessions_logout_jen_odvolana CHECK (revoked_at IS NOT NULL OR logout_done_at IS NULL)
);

COMMENT ON TABLE public.federated_source_sessions IS
  'Trezor relací uživatelů u federovaného zdroje (ADR-004). Šifruje broker (AES-256-GCM, klíč mimo DB). Čte jen servisní role přes SECURITY DEFINER funkce.';

-- RLS v souboru TABULKY (brána production-build): bez ní by tabulka byla čitelná
-- od vzniku do doběhnutí rls/.
ALTER TABLE public.federated_source_sessions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.federated_source_sessions FROM PUBLIC, anon, authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/flowboard_graphs.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: flowboard_graphs
-- Purpose: Versioned, engine-agnostic AISHA Flowboard graphs (the visual agent
--          / automation builder). One row per saved flow; the `graph` JSONB is
--          the canonical FlowGraph (nodes + edges + meta) validated app-side by
--          src/lib/flowboard/graph.ts. Same lifecycle as a GrapesJS page:
--          AISHA drafts → user edits on canvas → publish → versioned.
-- Managed by: save_flowboard_graph() / get_flowboard_graph() /
--             list_flowboard_graphs() (SECURITY DEFINER RPCs). Compilation to
--             n8n / sandbox happens app-side; run provenance lands in
--             story_entries (entry_type flow_run | automation_step).
-- Taxonomy:  status / engine_pin are open text by design (no CHECK) — AISHA can
--            extend without a schema change, consistent with agent_phase_catalog.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.flowboard_graphs (
  id           uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  slug         text,
  name         text        NOT NULL DEFAULT 'Nový flow',
  -- Canonical FlowGraph JSON (nodes/edges/meta). Validated app-side.
  graph        jsonb       NOT NULL DEFAULT '{}'::jsonb,
  version      integer     NOT NULL DEFAULT 1,
  -- draft | published | archived | … (open text by design).
  status       text        NOT NULL DEFAULT 'draft',
  -- NULL = let selectEngine decide; 'n8n' | 'sandbox' to pin.
  engine_pin   text,
  created_by   uuid        REFERENCES aisha_auth.users(id) ON DELETE SET NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now()
);

-- RLS: ENABLE here (the ALTER references no function, so it is cold-start-safe in the
-- table SoT, and the production-build gate requires ENABLE in tables/*.sql). The POLICIES
-- live in aisha/db/sql/rls/flowboard_graphs.sql — they reference auth.uid()/is_admin_or_staff(),
-- so they are emitted after functions. RPC-only: direct table DML reserved for service_role.
ALTER TABLE public.flowboard_graphs ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.flowboard_graphs TO service_role;

COMMENT ON TABLE public.flowboard_graphs IS
  'Versioned engine-agnostic AISHA Flowboard graphs (visual agent/automation builder). graph JSONB = canonical FlowGraph; compiled app-side to n8n/sandbox, provenance flows to story_entries.';
COMMENT ON COLUMN public.flowboard_graphs.engine_pin IS
  'NULL = selectEngine decides; n8n | sandbox to pin the execution target.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/governance_proposals.sql
-- -----------------------------------------------------------------------------

-- Table: governance_proposals
-- Local governance ballot ledger (LOCKED DECISION D3): member voting is recorded
-- in a LOCAL, queryable proposal + ballot store — not only broadcast by a single
-- custodial backend signer. A proposal carries its lifecycle, quorum and a running
-- tally derived from governance_votes.
-- RLS: ENABLED

CREATE TABLE IF NOT EXISTS public.governance_proposals (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  title text NOT NULL,
  description text,
  proposal_type text NOT NULL DEFAULT 'general',
  status text NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'open', 'passed', 'rejected', 'executed', 'cancelled')),
  quorum numeric(20,8) NOT NULL DEFAULT 0,
  tally jsonb NOT NULL DEFAULT jsonb_build_object('for', 0, 'against', 0, 'abstain', 0, 'voter_count', 0),
  created_by uuid,
  opens_at timestamptz,
  closes_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (id),
  CONSTRAINT governance_proposals_created_by_fkey
    FOREIGN KEY (created_by) REFERENCES aisha_auth.users(id) ON DELETE SET NULL
);

ALTER TABLE public.governance_proposals ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.governance_proposals IS
  'Local governance proposal ledger (D3): lifecycle + quorum + weight-derived tally.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/governance_votes.sql
-- -----------------------------------------------------------------------------

-- Table: governance_votes
-- Local member ballots (LOCKED DECISION D3). One ballot per member per proposal;
-- vote weight is DERIVED server-side from governance token holdings (never a
-- client-supplied number). Every ballot is bound to the immutable hash chain by
-- cast_governance_vote (a blockchain_audit_records row keyed on
-- reference_table='governance_votes').
-- RLS: ENABLED

CREATE TABLE IF NOT EXISTS public.governance_votes (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  proposal_id uuid NOT NULL,
  user_id uuid NOT NULL,
  choice text NOT NULL
    CHECK (choice IN ('for', 'against', 'abstain')),
  weight numeric(20,8) NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (id),
  CONSTRAINT governance_votes_proposal_user_key UNIQUE (proposal_id, user_id),
  CONSTRAINT governance_votes_proposal_id_fkey
    FOREIGN KEY (proposal_id) REFERENCES public.governance_proposals(id) ON DELETE CASCADE,
  CONSTRAINT governance_votes_user_id_fkey
    FOREIGN KEY (user_id) REFERENCES aisha_auth.users(id) ON DELETE CASCADE
);

ALTER TABLE public.governance_votes ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.governance_votes IS
  'Local member ballots (D3): one per member per proposal, server-derived weight, '
  'each anchored into blockchain_audit_records via cast_governance_vote.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/growth_policy_parameters.sql
-- -----------------------------------------------------------------------------

-- Table: growth_policy_parameters
