-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/ledger_participation.sql
-- -----------------------------------------------------------------------------

-- Table: ledger_participation
-- Per-member opt-out surface for PERSONAL on-chain / Cosmos anchoring (LOCKED
-- DECISION D2). This governs ONLY layer 2 (pushing a member's activity to the
-- Cosmos chain + binding it to their personal wallet). Layer 1 — the in-DB
-- hash-chain book (blockchain_audit_records + its chain-link/guard triggers) — is
-- ALWAYS ON and is NEVER gated by this flag.
--
-- Default: participates = true (opt-out model). Absence of a row is treated as
-- participating by the readers (fn_queue_blockchain_sync). A member records their
-- choice via update_my_ledger_participation; the choice is PRESERVED across any
-- migration/heal re-apply (seed writers use ON CONFLICT DO NOTHING — mirroring the
-- provider-catalog is_enabled precedent).
-- RLS: ENABLED

CREATE TABLE IF NOT EXISTS public.ledger_participation (
  user_id uuid NOT NULL,
  participates boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id),
  CONSTRAINT ledger_participation_user_id_fkey
    FOREIGN KEY (user_id) REFERENCES aisha_auth.users(id) ON DELETE CASCADE
);

ALTER TABLE public.ledger_participation ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.ledger_participation IS
  'Per-member opt-out for personal on-chain anchoring (D2). Gates layer 2 (Cosmos '
  'dispatch) only; the in-DB hash-chain book stays unconditional. Default participates=true.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/li_entity_suggestions.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_entity_suggestions
-- Popis: Advisory návrhy sjednocení názvů protistran z local-ingest (E4) —
--        zrcadlí entity_suggestions_artifact.jsonl (record_type=
--        'entity_suggestion'). same_id_multiple_names / same_name_multiple_ids.
--        DOKTRÍNA: „Fuzzy sjednocení názvů entit smí být advisory návrh, NIKDY
--        automatická vazba" — z těchto řádků se NIKDY negeneruje FK/vazba.
--        Spravováno: svc-source-broker li-driver přes li_upsert_entity_suggestions.
--        Idempotence přes suggestion_key (suggestion + pole + hodnota).
-- RLS: ENABLED (RPC-only lockdown)
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.li_entity_suggestions (
  id                 uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  suggestion_key     text         NOT NULL,
  suggestion         text         NOT NULL,
  id_field           text,
  id_value           text,
  name_field         text,
  name_normalized    text,
  names              text[]       NOT NULL DEFAULT '{}',
  ids                text[]       NOT NULL DEFAULT '{}',
  documents          text[]       NOT NULL DEFAULT '{}',
  advisory           boolean      NOT NULL DEFAULT true,
  -- provenance
  ingest_source_slug text         NOT NULL DEFAULT 'local-ingest',
  export_id          text,
  engine_version     text,
  verify_ok          boolean      NOT NULL DEFAULT false,
  raw_data           jsonb,
  ingested_at        timestamptz  NOT NULL DEFAULT now(),
  created_at         timestamptz  NOT NULL DEFAULT now(),
  updated_at         timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT li_entity_suggestions_suggestion_key_key UNIQUE (suggestion_key),
  -- ⭐ DRUH NÁVRHU JE VLASTNOST, NE VÝČET — a je to oprava POTŘETÍ.
  --
  -- Historie téže vady: 07-31 znal CHECK dva druhy a ingest vydával čtyři
  -- (rozšířeno RUKOU v produkci, SoT pozadu); 08-03 vydává PĚT
  -- (`value_shape_foreign_to_field` = hodnota tvarem patří do jiného pole)
  -- a čtyřprvkový výčet odmítl CELÝ balíček 44 320 dokladů — jediný řádek
  -- neznámého druhu zastavil replay evidence i KB.
  --
  -- Uzavřený výčet svazuje platformu s enginem do lockstepu: každý nový nález
  -- ingestu si žádá migraci a do té doby NEPROJDE NIC. Přitom výčet tu nic
  -- nechrání — nikdo na hodnotu nespíná (`li_upsert_entity_suggestions` klíčuje
  -- obecně přes `question_id`, spotřebitelé neznámý druh ignorují) a doktrínu
  -- „advisory, nikdy vazba" drží `advisory_check`, ne jméno nálezu.
  --
  -- Kontrolujeme tedy TVAR: neprázdný slug malými písmeny. To odmítne nepořádek
  -- (prázdno, mezery, HTML, verzálky) a nechá slovník enginu růst. Brána má
  -- testovat vlastnost, ne pravopis.
  CONSTRAINT li_entity_suggestions_suggestion_check
    CHECK (suggestion ~ '^[a-z][a-z0-9_]{2,63}$'),
  CONSTRAINT li_entity_suggestions_advisory_check
    CHECK (advisory = true)
);

COMMENT ON TABLE public.li_entity_suggestions IS 'Advisory návrhy sjednocení entit z local-ingest (entity_suggestions_artifact.jsonl); NIKDY se z nich negeneruje FK/vazba';
COMMENT ON COLUMN public.li_entity_suggestions.suggestion_key IS 'Deterministický dedup klíč (suggestion + id/name field + hodnota) — počítá li_upsert_entity_suggestions';
COMMENT ON COLUMN public.li_entity_suggestions.advisory IS 'Vždy true (CHECK) — pojistka doktríny: advisory návrh, nikdy automatická vazba';

ALTER TABLE public.li_entity_suggestions ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/li_finding_verdicts.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_finding_verdicts
-- Popis: Odpověď člověka na DOTAZ NA PRAVDU — jeden řádek na pravidlo × druh
--        nálezu, ne na doklad.
--
-- ⭐ PROČ NE SLOUPEC V li_findings. Nález je jeden na DOKLAD (79 řádků na
-- produkci 2026-09-28, z toho 43× „součet položek nesedí" nad vydanými
-- fakturami). Člověk se ale nerozhoduje o dokladu, rozhoduje o TVRZENÍ PRAVIDLA:
-- „DUZP má být dřív než vystavení" buď u nájmů platí, nebo ne — a platí to
-- stejně pro první i pro čtyřicátý doklad. Verdikt u jednotlivého nálezu by
-- znamenal odpovídat 43× na tutéž otázku a nový doklad od ingestu by se ptal
-- znovu. Klíčem je proto (rule_key, finding); nálezy dokladů zůstávají
-- v li_findings jako důkaz pod dotazem.
--
-- question_id = li_finding_question_id(rule_key, finding) — deterministický,
-- takže ho vydá čtecí blok i bez řádku v téhle tabulce (dotaz bez odpovědi
-- tu řádek NEMÁ). Zápis jen submit_evidence_review_audited (větev 'finding').
-- RLS: ENABLED — čtení admin/staff (jako li_findings), zápis jen přes RPC.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.li_finding_verdicts (
  question_id     uuid         PRIMARY KEY,
  rule_key        text,
  finding         text         NOT NULL,
  decision        text         NOT NULL,
  decided_by      uuid,
  decided_at      timestamptz  NOT NULL DEFAULT now(),
  decided_note    text,
  -- Kolik dokladů dotaz v okamžiku odpovědi zahrnoval a na jakém příkladu se
  -- odpovídalo. Bez toho by po dalším ingestu nešlo zpětně říct, o čem člověk
  -- vlastně rozhodl.
  documents_count integer      NOT NULL DEFAULT 0,
  example         jsonb,
  created_at      timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT li_finding_verdicts_decision_check
    CHECK (decision IN ('confirmed', 'rejected'))
);

COMMENT ON TABLE public.li_finding_verdicts IS 'Odpověď na dotaz na pravdu nad skupinou nálezů (rule_key × finding); zápis jen submit_evidence_review_audited, větev finding';
COMMENT ON COLUMN public.li_finding_verdicts.question_id IS 'li_finding_question_id(rule_key, finding) — deterministický, dotaz bez odpovědi řádek nemá';
COMMENT ON COLUMN public.li_finding_verdicts.decision IS 'confirmed = nález platí (je to chyba v dokladech); rejected = pravidlo tu neplatí (planý poplach)';
COMMENT ON COLUMN public.li_finding_verdicts.documents_count IS 'Počet dotčených dokladů v okamžiku odpovědi';
COMMENT ON COLUMN public.li_finding_verdicts.example IS 'Příklad, nad kterým člověk odpovídal (položka dotazu v okamžiku odpovědi)';

ALTER TABLE public.li_finding_verdicts ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/li_findings.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_findings
-- Popis: Deterministické nálezy (nesoulady) z cross-document kontrol
--        local-ingest — zrcadlí findings_artifact.jsonl (record_type='finding').
--        Např. missing_counterpart, date_out_of_window, price_mismatch,
--        missing_line_item. Alert engine čte odsud.
--        Spravováno: svc-source-broker li-driver přes li_upsert_findings.
--        Idempotence přes finding_key (deterministický z rule_id + finding +
--        dotčených dokladů) — počítá RPC, driver je tenký mapper.
-- RLS: ENABLED (RPC-only lockdown)
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.li_findings (
  id                 uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  finding_key        text         NOT NULL,
  rule_key           text,
  finding            text         NOT NULL,
  severity           text,
  documents          jsonb        NOT NULL DEFAULT '[]'::jsonb,
  evidence           jsonb,
  -- provenance
  ingest_source_slug text         NOT NULL DEFAULT 'local-ingest',
  export_id          text,
  engine_version     text,
  verify_ok          boolean      NOT NULL DEFAULT false,
  raw_data           jsonb,
  ingested_at        timestamptz  NOT NULL DEFAULT now(),
  created_at         timestamptz  NOT NULL DEFAULT now(),
  updated_at         timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT li_findings_finding_key_key UNIQUE (finding_key),
  CONSTRAINT li_findings_severity_check
    CHECK (severity IS NULL OR severity IN ('low', 'medium', 'high'))
);

COMMENT ON TABLE public.li_findings IS 'Deterministické nálezy z local-ingest cross-document kontrol (findings_artifact.jsonl); alert engine čte odsud';
COMMENT ON COLUMN public.li_findings.finding_key IS 'Deterministický dedup klíč (rule_id + finding + seřazené sha dotčených dokladů) — počítá li_upsert_findings';
COMMENT ON COLUMN public.li_findings.finding IS 'Druh nálezu: missing_counterpart / date_out_of_window / missing_line_item / <rule.id> (např. price_mismatch)';
COMMENT ON COLUMN public.li_findings.rule_key IS 'TEXT slug pravidla z local-ingest (export wire-pole rule_id, např. price_mismatch) — NENÍ uuid FK na expert_rules; proto rule_key, ne rule_id';
COMMENT ON COLUMN public.li_findings.documents IS 'Dotčené doklady [{source_sha256, source_slug, filename}] — evidence, ne akce';

ALTER TABLE public.li_findings ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/li_links.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_links
-- Popis: Doložené vazby mezi doklady z local-ingest — zrcadlí
--        links_artifact.jsonl (record_type='link'). Deklarativní párování
--        (faktura↔dodací list, faktura↔platba, dodatek supersedes smlouvu).
--        relation=supersedes je zdroj projekce „platná verze" do registru.
--        Spravováno: svc-source-broker li-driver přes li_upsert_links.
--        Idempotence přes link_key (rule_id + from_sha + to_sha + relation).
-- RLS: ENABLED (RPC-only lockdown)
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.li_links (
  id                 uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  link_key           text         NOT NULL,
  rule_key           text,
  relation           text,
  from_sha256        text         NOT NULL,
  from_slug          text,
  from_doc_type      text,
  to_sha256          text         NOT NULL,
  to_slug            text,
  to_doc_type        text,
  matched_by         jsonb        NOT NULL DEFAULT '[]'::jsonb,
  -- provenance
  ingest_source_slug text         NOT NULL DEFAULT 'local-ingest',
  export_id          text,
  engine_version     text,
  verify_ok          boolean      NOT NULL DEFAULT false,
  raw_data           jsonb,
  ingested_at        timestamptz  NOT NULL DEFAULT now(),
  created_at         timestamptz  NOT NULL DEFAULT now(),
  updated_at         timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT li_links_link_key_key UNIQUE (link_key)
);

COMMENT ON TABLE public.li_links IS 'Doložené vazby mezi doklady z local-ingest (links_artifact.jsonl); relation=supersedes → projekce platné verze do registru';
COMMENT ON COLUMN public.li_links.link_key IS 'Deterministický dedup klíč (rule_id + from_sha256 + to_sha256 + relation) — počítá li_upsert_links';
COMMENT ON COLUMN public.li_links.rule_key IS 'TEXT slug pravidla z local-ingest (export wire-pole rule_id) — NENÍ uuid FK na expert_rules; proto rule_key, ne rule_id';
COMMENT ON COLUMN public.li_links.relation IS 'Sémantika vazby (např. supersedes) — nepovinná; supersedes řídí projekci platné verze';
COMMENT ON COLUMN public.li_links.matched_by IS 'Evidence shody (které podmínky/pole match — auditní stopa)';

ALTER TABLE public.li_links ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/li_obligations.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_obligations
-- Popis: Registr závazků z ustanovení smluv (local-ingest E5) — zrcadlí
--        obligations_artifact.jsonl (record_type='obligation'). Každý závazek
--        nese VERBATIM citaci (quote) + absolutní span zpět na článek.
--        candidate_status je VŽDY NEEDS_REVIEW: právně významný obsah se nikdy
--        nestává autoritativním bez člověka (promoce jen přes review flow).
--        Spravováno: svc-source-broker li-driver přes li_upsert_obligations.
--        Idempotence přes obligation_key (source_sha256 + span + rule_id).
-- RLS: ENABLED (RPC-only lockdown)
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.li_obligations (
  id                 uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  obligation_key     text         NOT NULL,
  source_sha256      text         NOT NULL,
  doc_slug           text,
  filename           text,
  rule_key           text,
  clause_ref         text,
  clause_title       text,
  quote              text         NOT NULL,
  char_start         integer,
  char_end           integer,
  page               integer,
  obliged_party      text,
  action             text,
  deadline_text      text,
  consequence_text   text,
  candidate_status   text         NOT NULL DEFAULT 'NEEDS_REVIEW',
  -- provenance
  ingest_source_slug text         NOT NULL DEFAULT 'local-ingest',
  export_id          text,
  engine_version     text,
  verify_ok          boolean      NOT NULL DEFAULT false,
  raw_data           jsonb,
  ingested_at        timestamptz  NOT NULL DEFAULT now(),
  created_at         timestamptz  NOT NULL DEFAULT now(),
  updated_at         timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT li_obligations_obligation_key_key UNIQUE (obligation_key),
  CONSTRAINT li_obligations_candidate_status_check
    CHECK (candidate_status IN ('NEEDS_REVIEW', 'HUMAN_CONFIRMED', 'REJECTED'))
);

COMMENT ON TABLE public.li_obligations IS 'Registr závazků z local-ingest (obligations_artifact.jsonl); právní obsah: default NEEDS_REVIEW, HUMAN_CONFIRMED jen přes review flow';
COMMENT ON COLUMN public.li_obligations.obligation_key IS 'Deterministický dedup klíč (source_sha256 + char_start + char_end + rule_id) — počítá li_upsert_obligations';
COMMENT ON COLUMN public.li_obligations.rule_key IS 'TEXT slug pravidla z local-ingest (export wire-pole rule_id) — NENÍ uuid FK na expert_rules; proto rule_key, ne rule_id';
COMMENT ON COLUMN public.li_obligations.quote IS 'VERBATIM citace ustanovení (pravda); interpretace (obliged_party/action/deadline) je oddělený návrh';
COMMENT ON COLUMN public.li_obligations.candidate_status IS 'Vždy NEEDS_REVIEW z importu; HUMAN_CONFIRMED nastaví jedině review RPC (nikdy driver)';

ALTER TABLE public.li_obligations ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/li_relation_suggestions.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_relation_suggestions
-- Popis: Advisory návrhy VZTAHŮ mezi entitami z local-ingest — zrcadlí
--        entity_relation_artifact.jsonl (record_type='entity_relation') a
--        relation_proposal_artifact.jsonl (record_type='relation_proposal').
--
--        DOKTRÍNA: engine oba druhy razítkuje `advisory: True` s komentářem
--        „doložený vztah, NIKDY automatická vazba". Tahle tabulka je tedy
--        DŮKAZ, ne fakt: z jejích řádků se nikdy negeneruje FK ani
--        `twin_relations`. Vazbu otevře až ratifikace
--        (`twin_relation_open_admin`), která má vlastní autorizaci.
--
--        Proč to existuje: engine vyráběl oba artefakty a driver je NEČETL —
--        síť vazeb se odvodila a zahodila u dveří (naměřeno 2026-08-30:
--        graph_nodes 0, graph_edges 0 při 345 odvozených vztazích). Axiom
--        „story je uzel v síti vazeb" bez přistání vazeb nemá z čeho vzniknout.
--
--        Spravováno: svc-source-broker li-driver přes li_upsert_relation_suggestions.
--        Idempotence přes suggestion_key (druh + parametry + hodnota).
-- RLS: ENABLED (RPC-only lockdown)
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.li_relation_suggestions (
  id                 uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  suggestion_key     text         NOT NULL,
  -- Druh záznamu i druh vztahu jsou VLASTNOSTI, ne výčty (viz CHECK níž).
  record_type        text         NOT NULL,
  relation_kind      text,
  -- Strany vztahu. `entity_relation` popisuje JEDEN parametr sdílený víc
  -- entitami (parameter_a + value, parameter_b NULL); `relation_proposal`
  -- popisuje DVOJICI parametrů (parameter_a + parameter_b, value NULL).
  parameter_a        text         NOT NULL,
  parameter_b        text,
  value              text,
  direction          text,
  -- Naměřená opora. Nezaokrouhlovat na verdikt: bez čísel se návrh nedá
  -- posoudit a rozhodnutí by nebylo učební vzorek, jen klik.
  observations       integer      NOT NULL DEFAULT 0,
  entities_reached   integer,
  -- ⭐ POZOROVÁNO, NE PLATNÉ. Engine měří rozpětí, ve kterém se dvojice v korpusu
  -- POTKÁVALA (`period`), a osu si k tomu ODVODÍ (`time_axis` = nejhustěji
  -- obsazené datumové pole; nezadává se). To NENÍ tvrzení o platnosti vztahu —
  -- platnost vzniká až ratifikací a bydlí v `twin_relations.valid_from/valid_to`.
  --
  -- Proto jiná jména než v cíli: kdyby se tyhle sloupce jmenovaly `valid_*`,
  -- splynul by důkaz s tvrzením a advisory návrh by se četl jako fakt — přesně
  -- ten posun, kterému brání `advisory_check`.
  --
  -- `date`, ne timestamptz: engine emituje ISO DNY (`value[:10]`). Širší typ by
  -- předstíral přesnost, kterou měření nemá. Prázdné u `entity_relation` —
  -- ten druh období nenese.
  observed_from      date,
  observed_to        date,
  time_axis          text,
  -- provenance
  advisory           boolean      NOT NULL DEFAULT true,
  ingest_source_slug text         NOT NULL DEFAULT 'local-ingest',
  export_id          text,
  engine_version     text,
  verify_ok          boolean      NOT NULL DEFAULT false,
  raw_data           jsonb,
  ingested_at        timestamptz  NOT NULL DEFAULT now(),
  created_at         timestamptz  NOT NULL DEFAULT now(),
  updated_at         timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT li_relation_suggestions_suggestion_key_key UNIQUE (suggestion_key),

  -- ⭐ DRUH JE VLASTNOST, NE VÝČET — poučeno ze sesterské tabulky.
  --
  -- `li_entity_suggestions` měl tutéž vadu TŘIKRÁT: uzavřený výčet druhů
  -- svázal platformu s enginem do lockstepu a jediný řádek neznámého druhu
  -- odmítl CELÝ balíček 44 320 dokladů. Výčet tu nic nechrání — spotřebitelé
  -- neznámý druh ignorují a doktrínu „advisory, nikdy vazba" drží
  -- `advisory_check`, ne jméno druhu.
  --
  -- Engine je navíc v fázi 1 (`kind='relates_to'` = „tvar, ne význam") a jeho
  -- slovník POROSTE. Kontrolujeme tedy TVAR: neprázdný slug malými písmeny.
  CONSTRAINT li_relation_suggestions_record_type_check
    CHECK (record_type ~ '^[a-z][a-z0-9_]{2,63}$'),
  CONSTRAINT li_relation_suggestions_relation_kind_check
    CHECK (relation_kind IS NULL OR relation_kind ~ '^[a-z][a-z0-9_]{2,63}$'),
  CONSTRAINT li_relation_suggestions_direction_check
    CHECK (direction IS NULL OR direction ~ '^[a-z][a-z0-9_]{2,63}$'),
  CONSTRAINT li_relation_suggestions_advisory_check
    CHECK (advisory = true)
);

COMMENT ON TABLE public.li_relation_suggestions IS 'Advisory návrhy vztahů mezi entitami z local-ingest (entity_relation + relation_proposal); NIKDY se z nich negeneruje FK/vazba — vazbu otevře až ratifikace';
COMMENT ON COLUMN public.li_relation_suggestions.suggestion_key IS 'Deterministický dedup klíč (druh + parametry + hodnota) — počítá li_upsert_relation_suggestions';
COMMENT ON COLUMN public.li_relation_suggestions.advisory IS 'Vždy true (CHECK) — pojistka doktríny: doložený vztah, nikdy automatická vazba';
COMMENT ON COLUMN public.li_relation_suggestions.raw_data IS 'Celý záznam enginu — sloupce výš jsou jen to, na co se filtruje';
COMMENT ON COLUMN public.li_relation_suggestions.observed_from IS 'První den, kdy se dvojice v korpusu potkala — DŮKAZ, ne platnost (platnost nese twin_relations.valid_from)';
COMMENT ON COLUMN public.li_relation_suggestions.observed_to IS 'Poslední den, kdy se dvojice v korpusu potkala — DŮKAZ, ne platnost';
COMMENT ON COLUMN public.li_relation_suggestions.time_axis IS 'Pole, ze kterého engine osu ODVODIL (nejhustěji obsazené datumové pole) — bez něj se období nedá interpretovat';

ALTER TABLE public.li_relation_suggestions ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/li_source_registry.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_source_registry
-- Popis: Evidenční registr dokladů z local-ingest (jeden řádek na doklad
--        evidenční třídy — transactional/contractual). Zrcadlí artefakt
--        registry_artifact.jsonl (record_type='registry_record'). Autoritativní
--        pole + pole čekající na revizi + řádkové položky + completeness status.
--        Spravováno: svc-source-broker li-driver přes li_upsert_source_registry.
--        Jediný writer je platforma (service_role za RPC); lokální box píše
--        jen soubory. Idempotence přes source_sha256 (obsahová identita dokladu).
-- RLS: ENABLED (RPC-only lockdown — čtení přes SECURITY DEFINER RPC, ne přímo)
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.li_source_registry (
  id                    uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  source_sha256         text         NOT NULL,
  doc_slug              text         NOT NULL,
  story_id              uuid,
  doc_type              text         NOT NULL,
  doc_class             text,
  filename              text,
  status                text         NOT NULL DEFAULT 'REVIEW',
  missing_required      text[]       NOT NULL DEFAULT '{}',
  fields                jsonb        NOT NULL DEFAULT '{}'::jsonb,
  fields_pending_review jsonb        NOT NULL DEFAULT '{}'::jsonb,
  line_items            jsonb        NOT NULL DEFAULT '[]'::jsonb,
  lines_pending_review  integer      NOT NULL DEFAULT 0,
  schema_version        text,
  superseded_by         text,
  -- provenance (audit doktrína: čím a odkud řádek vznikl)
  ingest_source_slug    text         NOT NULL DEFAULT 'local-ingest',
  export_id             text,
  engine_version        text,
  verify_ok             boolean      NOT NULL DEFAULT false,
  raw_data              jsonb,
  -- Umístění binárky: bucket je DATA řádku (píše ho ingest, který ví, kam
  -- objekt uložil) — nikdy konstanta v kódu funkce. Klíč objektu je odvozený
  -- content-addressed: <source_sha256>.pdf. NULL = binárka nebyla uložena.
  storage_bucket        text,
  -- Klíče pro čtečky pod RLS — PROSTÉ sloupce odvozené z `fields` (viz stráž níž).
  counterparty_id_value text GENERATED ALWAYS AS ((fields->'counterparty_id'->>'value')) STORED,
  counterparty_value    text GENERATED ALWAYS AS ((fields->'counterparty'->>'value')) STORED,
  owner_company_value   text GENERATED ALWAYS AS ((fields->'owner_company'->>'value')) STORED,
  ingested_at           timestamptz  NOT NULL DEFAULT now(),
  created_at            timestamptz  NOT NULL DEFAULT now(),
  updated_at            timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT li_source_registry_source_sha256_key UNIQUE (source_sha256),
  CONSTRAINT li_source_registry_status_check
    CHECK (status IN ('AUTO_PASS', 'REVIEW'))
);

-- ⛔ KLÍČE PRO ČTEČKY POD RLS (2026-09-29, naměřeno na riq jen čtením): pod RLS smí
-- planner pustit podmínku před politiku (a tedy do Index Cond) JEN když je leakproof.
-- `fields->'x'->>'value'` (jsonb_object_field/_text) ani `fields @> …` leakproof NEJSOU,
-- takže výraz nad `fields` jde vždy seq scanem celé evidence s rozbalováním JSON —
-- expresní i GIN index jsou pro přihlášeného uživatele mrtvé. Karta protistrany:
-- counterparty_resolve 2 706 ms jako admin, tentýž dotaz jako service_role 23 ms.
-- `texteq` na PROSTÉM sloupci leakproof je → Index Scan (throwaway 70 tis. dokladů:
-- resolve 91 → 2,8 ms, člen bez nároku 54 → 6,5 ms, výsledek shodný).
-- Hodnota je TÁŽ jako výraz (vč. NULL u staršího skalárního korpusu) — sloupec je
-- generovaný, nemůže se rozejít s `fields`. Nový klíč pro filtr patří SEM, ne do
-- expresního indexu.
--
-- Stráž: JEDEN ALTER se všemi sloupci = jeden přepis tabulky (tři ALTERy = tři
-- přepisy). `ADD COLUMN IF NOT EXISTS` sám by i nad hotovou tabulkou bral ACCESS
-- EXCLUSIVE zámek při každém migrate — fronta za ním by zastavila čtení registru.
DO $$
BEGIN
  IF (SELECT count(*) FROM pg_attribute
       WHERE attrelid = 'public.li_source_registry'::regclass AND NOT attisdropped
         AND attname IN ('counterparty_id_value', 'counterparty_value', 'owner_company_value')) < 3 THEN
    ALTER TABLE public.li_source_registry
      ADD COLUMN IF NOT EXISTS counterparty_id_value text GENERATED ALWAYS AS ((fields->'counterparty_id'->>'value')) STORED,
      ADD COLUMN IF NOT EXISTS counterparty_value    text GENERATED ALWAYS AS ((fields->'counterparty'->>'value')) STORED,
      ADD COLUMN IF NOT EXISTS owner_company_value   text GENERATED ALWAYS AS ((fields->'owner_company'->>'value')) STORED;
  END IF;
END $$;

COMMENT ON TABLE public.li_source_registry IS 'Evidenční registr dokladů z local-ingest (registry_artifact.jsonl), upsert přes li_upsert_source_registry; idempotence přes source_sha256';
COMMENT ON COLUMN public.li_source_registry.source_sha256 IS 'sha256 obsahu dokladu — obsahová identita, dedup klíč pro idempotentní replay';
COMMENT ON COLUMN public.li_source_registry.doc_slug IS 'source_slug z artefaktu = slug dokladu (doc-<sha12>), NE slug datového zdroje';
COMMENT ON COLUMN public.li_source_registry.status IS 'AUTO_PASS = všechna registry_required pole autoritativní; jinak REVIEW (fail-closed)';
COMMENT ON COLUMN public.li_source_registry.superseded_by IS 'doc_slug nahrazujícího dokladu (projekce z links relation=supersedes); NULL = platná verze';
COMMENT ON COLUMN public.li_source_registry.ingest_source_slug IS 'slug datového zdroje (broker cursor) — vždy local-ingest; NE slug dokladu';
COMMENT ON COLUMN public.li_source_registry.counterparty_id_value IS 'fields.counterparty_id.value jako prostý sloupec (generovaný) — filtr podle IČO protistrany jde pod RLS přes index; výraz nad jsonb není leakproof';
COMMENT ON COLUMN public.li_source_registry.counterparty_value IS 'fields.counterparty.value jako prostý sloupec (generovaný) — jméno protistrany pro filtr pod RLS';
COMMENT ON COLUMN public.li_source_registry.owner_company_value IS 'fields.owner_company.value jako prostý sloupec (generovaný) — naše firma bez rozbalování fields (osa firma)';
COMMENT ON COLUMN public.li_source_registry.verify_ok IS 'výsledek offline verify auditu balíčku (fail-closed: driver upsertuje jen verify-gated exporty)';

ALTER TABLE public.li_source_registry ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/li_doc_scope_keys.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- li_doc_scope_keys — PŘEDPOČÍTANÉ klíče dokladů pro nárok z vazeb.
--
-- ⛔ PROČ TABULKA, NE DOTAZ NAD fields (naměřeno 2026-09-28 na produkci, jen čtení):
--   párování nemovitostní agendy (4 vlastníci faktur + pronajímatel smluv,
--   4 589 dokladů) přímo nad `li_source_registry.fields`:
--     lower(btrim(fields->k->>'value')) = hodnota   ·  905 ms
--     fields @> vzor (GIN jsonb_path_ops), spojení  · 1 353 ms (index nepoužit)
--     fields @> konstanty přes OR (BitmapOr)       ·   201 ms, z toho 163 ms
--                                                     rozbalení velkých fields
--   Nárok je člen politiky — počítá se při KAŽDÉM dotazu uživatele na doklady;
--   sekce o deseti blocích by nesla sekundy navíc. Tady je hodnota vytažená
--   jednou (trigger na registru) a nárok je indexový dotaz bez rozbalování JSON.
--
-- Obsah: pro každou PLATNOU verzi dokladu (superseded_by IS NULL):
--   • hodnoty polí z aktivních pravidel twin_scope_doc_rules + protistrana
--     (counterparty_id, counterparty) — typy, které pravidla znají;
--   • PŮVOD (všechny doklady): `@instance` = instance zdroje ze záznamu konektoru
--     (např. agenda Money), `@cesta` = každý nadřazený adresář relativní cesty ve
--     vstupu ingestu (raw_data.source_path) — pro udělení zdroje dat uživateli.
--   `hodnota` = lower(btrim(value)) — value z `{value,…}`, u staršího korpusu skalár.
-- Udržuje: trigger na li_source_registry (řádek) a přestavba při změně pravidel.
-- Přístup jen přes funkce; RLS bez politik, žádné granty pro anon/authenticated.
-- =============================================================================
CREATE TABLE IF NOT EXISTS public.li_doc_scope_keys (
  source_sha256  text NOT NULL
                 REFERENCES public.li_source_registry (source_sha256) ON DELETE CASCADE ON UPDATE CASCADE,
  doc_slug       text NOT NULL,
  doc_type       text NOT NULL,
  field_key      text NOT NULL,
  hodnota        text NOT NULL CHECK (hodnota <> ''),
  zobrazeni      text,
  CONSTRAINT li_doc_scope_keys_pkey PRIMARY KEY (source_sha256, field_key, hodnota)
);

-- ⭐ PŮVOD DOKLADU (2026-09-28): klíče `@instance` (instance zdroje od konektoru) a `@cesta`
-- (každý nadřazený adresář relativní cesty ve vstupu ingestu) nesou i původní zápis —
-- správa v Lidé a účty vybírá zdroje podle jména, ne podle normalizované hodnoty.
ALTER TABLE public.li_doc_scope_keys ADD COLUMN IF NOT EXISTS zobrazeni text;

COMMENT ON TABLE public.li_doc_scope_keys IS
  'Předpočítané hodnoty polí dokladů pro nárok z vazeb (pole z twin_scope_doc_rules + protistrana); jen platné verze. Udržuje trigger na li_source_registry a přestavba při změně pravidel.';

ALTER TABLE public.li_doc_scope_keys ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.li_doc_scope_keys FROM PUBLIC, anon, authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/llm_tier_defaults.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Table: llm_tier_defaults
-- Phase 12 WP 2.3 — LLM token rate limit per JWT.sub
--
-- Per-tier daily token + cost budgets. New users land in the 'free' tier
-- via fn_check_and_consume_llm_quota_audited's lazy-create path. Admin
-- promotes users to higher tiers via update_llm_quota_tier_audited (future
-- WP follow-up — not in this PR).
--
-- Read-only for end users; admin can edit via SECURITY DEFINER mutation RPCs.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.llm_tier_defaults (
  tier text PRIMARY KEY,
  daily_token_limit int NOT NULL CHECK (daily_token_limit >= 0),
  daily_cost_limit numeric(10,4) NOT NULL CHECK (daily_cost_limit >= 0),
  description text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.llm_tier_defaults ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.llm_tier_defaults IS
  'Phase 12 WP 2.3 — per-tier daily token + cost budgets for LLM quota enforcement. Public read, admin write.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/llm_quota.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Table: llm_quota
-- Phase 12 WP 2.3 — LLM token rate limit per JWT.sub
--
-- Per-user daily token + cost ledger. The row is lazy-created from
-- llm_tier_defaults on first LLM call via fn_check_and_consume_llm_quota_audited.
-- Counters reset at midnight UTC via pg_cron job 'llm-quota-daily-reset'
-- (declared in aisha/db/sql/cron/llm_quota_daily_reset.sql).
--
-- Read paths:
--   - End user reads OWN row (RLS).
--   - Admin reads ALL rows (RLS).
-- Write paths (mutation): service_role only via the audited RPC.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.llm_quota (
  user_id uuid PRIMARY KEY
    REFERENCES aisha_auth.users(id) ON DELETE CASCADE,
  tier text NOT NULL DEFAULT 'free'
    REFERENCES public.llm_tier_defaults(tier) ON UPDATE CASCADE,
  daily_token_limit int NOT NULL CHECK (daily_token_limit >= 0),
  daily_cost_limit numeric(10,4) NOT NULL CHECK (daily_cost_limit >= 0),
  consumed_tokens_today int NOT NULL DEFAULT 0 CHECK (consumed_tokens_today >= 0),
  consumed_cost_today numeric(10,4) NOT NULL DEFAULT 0 CHECK (consumed_cost_today >= 0),
  last_reset_at timestamptz NOT NULL DEFAULT date_trunc('day', now()),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- Indexes live in aisha/db/sql/indexes/idx_llm_quota_tier.sql +
--                  aisha/db/sql/indexes/idx_llm_quota_consumption_today.sql
-- (architecture test sql-source-separation enforces strict separation).

ALTER TABLE public.llm_quota ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.llm_quota IS
  'Phase 12 WP 2.3 — per-user daily LLM token + cost ledger. Row lazy-created from llm_tier_defaults on first call. Service-role mutations only.';


