-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/plugin_catalog.sql
-- -----------------------------------------------------------------------------

-- Table: plugin_catalog

CREATE TABLE IF NOT EXISTS public.plugin_catalog (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  slug text NOT NULL,
  name text,
  description text,
  author text,
  kind public.plugin_kind NOT NULL,
  trust_tier public.plugin_trust_tier DEFAULT 'external'::public.plugin_trust_tier NOT NULL,
  status public.plugin_status DEFAULT 'submitted'::public.plugin_status NOT NULL,
  capabilities jsonb DEFAULT '[]'::jsonb NOT NULL,
  config_schema jsonb,
  sandbox_policy jsonb,
  lifecycle jsonb,
  -- Run-as-story template for kind='agent' (declarative agents). Carries
  -- rule_slugs + knowledge_items + story defaults; consumed by
  -- install_agent_as_story to mint a consumer-owned story. NULL for non-agents
  -- and for executable/call-mode agents (Phase 2). Kind-specific, same posture
  -- as sandbox_policy living on this shared catalog row.
  agent_spec jsonb,
  -- Per-kind materialization specs, symmetric to agent_spec: each kind that
  -- materializes into a runtime registry carries its declaration in its own
  -- column, and the matching materialize_* function is the ONLY reader. A kind
  -- with a NULL spec is skipped with a note (honest degradation), never guessed
  -- from config_schema — the spec IS the contract, config_schema stays the
  -- per-install parameter form.
  provider_spec jsonb,   -- kind=backend_provider → materialize_backend_provider → ai_provider_registry
  node_spec jsonb,       -- kind=automation_node  → materialize_automation_node  → custom_node_registry
  auth_spec jsonb,       -- kind=auth_provider    → materialize_auth_provider    → auth_provider_registry
  tracking_spec jsonb,   -- kind=web_tracking     → materialize_web_tracking     → web_tracking_registry
  source_spec jsonb,     -- kind=data_source      → materialize_data_source      → agent_knowledge_sources
  author_partner_id uuid,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT plugin_catalog_slug_key UNIQUE (slug)
);

ALTER TABLE public.plugin_catalog ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.plugin_catalog IS 'Registry of all plugins assimilated by AISHA.';
COMMENT ON COLUMN public.plugin_catalog.agent_spec IS 'kind=agent declarative spec. Run-as-story template (rule_slugs, knowledge_items, story defaults) consumed by install_agent_as_story; runtime registry keys (purpose, default_model [router KEY e.g. balanced/fast/maxQuality, not a raw provider id], allowed_tools, denied_tools, model_overrides, max_loops, safety_level, autonomy_level, context_profile) consumed by materialize_agent_runtime → agent_catalog.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/agent_catalog.sql
-- -----------------------------------------------------------------------------

-- Table: agent_catalog

CREATE TABLE IF NOT EXISTS public.agent_catalog (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  slug text NOT NULL,
  display_name text NOT NULL,
  purpose text NOT NULL,
  default_model text NOT NULL,
  model_overrides jsonb DEFAULT '{}'::jsonb NOT NULL,
  allowed_tools text[] DEFAULT '{}'::text[] NOT NULL,
  denied_tools text[] DEFAULT '{}'::text[] NOT NULL,
  default_context_profile text DEFAULT 'repo_plus_rules'::text NOT NULL,
  max_loops integer DEFAULT 3 NOT NULL,
  safety_level text DEFAULT 'standard'::text NOT NULL,
  is_active boolean DEFAULT true NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  autonomy_level text DEFAULT 'semi'::text,
  -- Provenance for marketplace-materialized agents: the plugin_catalog row this
  -- runtime entry was materialized from (NULL for built-in/seeded system agents).
  -- Used by materialize_agent_runtime (ON CONFLICT guard so a marketplace agent
  -- cannot hijack a system slug) and disable_agent_runtime (de-provision key).
  source_plugin_id uuid REFERENCES public.plugin_catalog(id) ON DELETE SET NULL,
  PRIMARY KEY (id)
);

ALTER TABLE public.agent_catalog ENABLE ROW LEVEL SECURITY;

COMMENT ON COLUMN public.agent_catalog.source_plugin_id IS 'plugin_catalog.id this runtime agent was materialized from (NULL = built-in/seed agent).';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/ai_provider_registry.sql
-- -----------------------------------------------------------------------------

-- Table: ai_provider_registry
-- AISHA's catalog of LLM providers + their access modes. AISHA reads this when
-- deciding which backend to use for each OpenClaw clow sub-agent. New providers
-- can be added at runtime (admin-gated) — AISHA tests them via
-- aisha_test_mcp_server / its own probe before relying on them in production.
--
-- This is the source-of-truth for "what providers exist". The existing
-- ai_model_registry references it via provider_registry_id (per-model).

CREATE TABLE IF NOT EXISTS public.ai_provider_registry (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),

  -- Stable identifier referenced by ai_model_registry rows
  slug text NOT NULL UNIQUE,                                  -- 'anthropic', 'openai', 'google', 'huggingface', 'ollama', 'vllm', 'custom-mcp-XYZ'
  display_name text NOT NULL,

  -- Backend kind controls how AISHA dispatches calls
  backend_kind text NOT NULL CHECK (backend_kind IN (
    'direct_cloud',          -- direct API call (Anthropic/OpenAI/Google/HuggingFace) — used for batch APIs + selected sync
    'llm_gateway',           -- routed via LLM Gateway transparent proxy (typically IDE traffic + batch passthrough)
    'local_ollama',          -- local Ollama runtime
    'local_vllm',            -- local vLLM runtime (GPU)
    'mcp_server'             -- a custom MCP server that exposes model access
  )),

  -- Network access
  endpoint_url text,                                          -- e.g. https://api.anthropic.com, http://ollama:11434, https://gateway.aisha.guru/v1
  health_url text,                                            -- optional probe path

  -- Auth
  auth_kind text NOT NULL DEFAULT 'bearer' CHECK (auth_kind IN ('bearer', 'api_key_header', 'none')),
  auth_env_var text,                                          -- env var name that holds the secret (NEVER store secret in DB)

  -- Capability flags (used by aisha_resolve_clow_backend)
  supports_chat boolean NOT NULL DEFAULT true,
  supports_tool_use boolean NOT NULL DEFAULT false,
  supports_vision boolean NOT NULL DEFAULT false,
  supports_batch boolean NOT NULL DEFAULT false,              -- has a deferred /batches endpoint (Anthropic, OpenAI)
  supports_streaming boolean NOT NULL DEFAULT true,

  -- Availability / health (set by probe; AISHA reads as input)
  is_enabled boolean NOT NULL DEFAULT true,
  last_health_status text NOT NULL DEFAULT 'unknown' CHECK (last_health_status IN ('healthy', 'degraded', 'down', 'unknown')),
  last_health_checked_at timestamptz,
  last_health_detail text,
  -- Consecutive non-healthy probes. Incremented on degraded/down, RESET to 0
  -- on healthy. Used by get_providers_due_health_probe for exponential backoff:
  -- failing providers get probed less frequently to avoid log spam + wasted
  -- probe cycles. Operator can manually reset via update_provider_admin.
  consecutive_failure_count int NOT NULL DEFAULT 0,

  -- Cost class for quick filtering (per_1m_avg_input) — refined by ai_model_benchmarks per-model
  cost_class text DEFAULT 'standard' CHECK (cost_class IN ('budget', 'standard', 'premium')),

  -- §19.4 per-instance scoping: NULL = base/global provider (visible to every
  -- instance); non-NULL = restricted to that instance only. The base ships global
  -- providers; an instance may add private ones (DB-seed/env), NEVER tenant code.
  scoped_to_instance_id uuid,

  -- Notes
  -- Provenance: NULL = built-in/operator-declared provider; non-NULL = materialized
  -- from an approved marketplace plugin (kind='backend_provider'). This column is
  -- what makes ownership enforceable: materialize_backend_provider only updates a
  -- row it already owns, so a plugin can never overwrite a built-in provider.
  source_plugin_id uuid REFERENCES public.plugin_catalog(id) ON DELETE SET NULL,

  notes text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,

  created_at timestamptz NOT NULL DEFAULT now(),
