-- Table: production_materials
-- Master data registry of all items (raw materials, intermediates, finished goods, packaging)
-- Maps to ERP md_item concept from storm-source-of-truth.md §6.2
-- RLS: ENABLED

CREATE TABLE IF NOT EXISTS production_materials (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  item_code text NOT NULL,
  item_name text NOT NULL,
  item_type text NOT NULL DEFAULT 'RAW',
  uom text NOT NULL DEFAULT 'kg',
  category text,
  description text,
  cas_number text,
  supplier_default text,
  min_stock_qty numeric(12,4),
  reorder_point numeric(12,4),
  shelf_life_days integer,
  storage_conditions text,
  is_active boolean DEFAULT true NOT NULL,
  metadata jsonb DEFAULT '{}'::jsonb,
  created_at timestamptz DEFAULT now() NOT NULL,
  updated_at timestamptz DEFAULT now(),
  created_by uuid,
  PRIMARY KEY (id),
  CONSTRAINT production_materials_item_code_key UNIQUE (item_code),
  CONSTRAINT production_materials_item_type_check CHECK (
    item_type IN ('RAW', 'INTERMEDIATE', 'FINISHED', 'PACKAGING', 'CONSUMABLE')
  ),
  CONSTRAINT production_materials_created_by_fkey FOREIGN KEY (created_by) REFERENCES aisha_auth.users(id)
);

ALTER TABLE production_materials ENABLE ROW LEVEL SECURITY;

-- Grants: admin-managed, read for authenticated
GRANT SELECT ON production_materials TO authenticated;
GRANT ALL ON production_materials TO service_role;

-- Column documentation
COMMENT ON TABLE production_materials IS 'Master data: all production items (raw materials, intermediates, finished goods, packaging). ERP md_item equivalent.';
COMMENT ON COLUMN production_materials.item_code IS 'Unique item identifier, e.g. BLOOD-RAW, HERB-DRY, RET-FINAL';
COMMENT ON COLUMN production_materials.item_type IS 'Item classification: RAW, INTERMEDIATE, FINISHED, PACKAGING, CONSUMABLE';
COMMENT ON COLUMN production_materials.uom IS 'Default unit of measure: kg, L, ml, g, ks (pieces)';
COMMENT ON COLUMN production_materials.category IS 'Product category: Retisin, Floristen, Lyastin, Společné';
COMMENT ON COLUMN production_materials.cas_number IS 'CAS registry number for chemical identification';
COMMENT ON COLUMN production_materials.shelf_life_days IS 'Shelf life in days from production date';
COMMENT ON COLUMN production_materials.storage_conditions IS 'Required storage conditions (temperature, humidity, light)';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/production_bom_entries.sql
-- -----------------------------------------------------------------------------

-- Table: production_bom_entries
-- Bill of Materials: defines parent→child material relationships per production step
-- Maps to ERP std_bom concept from storm-source-of-truth.md §6.3
-- RLS: ENABLED

CREATE TABLE IF NOT EXISTS production_bom_entries (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  parent_item_id uuid NOT NULL,
  child_item_id uuid NOT NULL,
  qty_per numeric(12,6) NOT NULL,
  uom text NOT NULL DEFAULT 'kg',
  step_code text,
  variant_code text,
  sort_order integer DEFAULT 0,
  is_active boolean DEFAULT true NOT NULL,
  notes text,
  metadata jsonb DEFAULT '{}'::jsonb,
  created_at timestamptz DEFAULT now() NOT NULL,
  updated_at timestamptz DEFAULT now(),
  created_by uuid,
  PRIMARY KEY (id),
  CONSTRAINT production_bom_entries_parent_fkey FOREIGN KEY (parent_item_id) REFERENCES production_materials(id) ON DELETE CASCADE,
  CONSTRAINT production_bom_entries_child_fkey FOREIGN KEY (child_item_id) REFERENCES production_materials(id) ON DELETE CASCADE,
  CONSTRAINT production_bom_entries_qty_positive CHECK (qty_per > 0),
  CONSTRAINT production_bom_entries_no_self_ref CHECK (parent_item_id <> child_item_id),
  CONSTRAINT production_bom_entries_created_by_fkey FOREIGN KEY (created_by) REFERENCES aisha_auth.users(id)
);

ALTER TABLE production_bom_entries ENABLE ROW LEVEL SECURITY;

-- Grants: admin-managed, read for authenticated
GRANT SELECT ON production_bom_entries TO authenticated;
GRANT ALL ON production_bom_entries TO service_role;

-- Column documentation
COMMENT ON TABLE production_bom_entries IS 'Bill of Materials: parent→child material relationships. Defines how much of child is needed to produce one unit of parent. ERP std_bom equivalent.';
COMMENT ON COLUMN production_bom_entries.parent_item_id IS 'Product/intermediate being produced';
COMMENT ON COLUMN production_bom_entries.child_item_id IS 'Input material consumed';
COMMENT ON COLUMN production_bom_entries.qty_per IS 'Quantity of child per unit of parent (e.g. 3.543 kg fresh herb per kg dry herb)';
COMMENT ON COLUMN production_bom_entries.uom IS 'Unit of measure for qty_per ratio, e.g. kg/kg, L/L, ks/ks';
COMMENT ON COLUMN production_bom_entries.step_code IS 'Production step where consumption occurs: DRYING, MACERATION, EXTRACTION, CONCENTRATION, FILLING';
COMMENT ON COLUMN production_bom_entries.variant_code IS 'Production variant: SPO, SPO+, SPO++, EKO, EKO+, EKO++, BED, FL-T48, FL-SUSH';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/production_qc_test_definitions.sql
-- -----------------------------------------------------------------------------

-- Table: production_qc_test_definitions
-- Formalized QC test specifications with method, limits, and sampling plan
-- Maps to erp-basis.md: QC test definition entity (test_code, spec_limits, method_ref, sampling_plan)
-- Provides the "what to test" master data that production_quality_params references
-- RLS: ENABLED

CREATE TABLE IF NOT EXISTS production_qc_test_definitions (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  test_code text NOT NULL,
  test_name text NOT NULL,
  method_ref text,
  description text,
  units text,
  spec_limit_low numeric(16,6),
  spec_limit_high numeric(16,6),
  target_value numeric(16,6),
  sampling_plan jsonb,
  applicable_products text[],
  applicable_steps text[],
  frequency text DEFAULT 'per_batch' NOT NULL,
  version text DEFAULT '1.0' NOT NULL,
  is_active boolean DEFAULT true NOT NULL,
  notes text,
  metadata jsonb DEFAULT '{}'::jsonb,
  created_at timestamptz DEFAULT now() NOT NULL,
  updated_at timestamptz DEFAULT now(),
  created_by uuid,
  PRIMARY KEY (id),
  CONSTRAINT production_qc_test_definitions_code_version_key UNIQUE (test_code, version),
  CONSTRAINT production_qc_test_definitions_frequency_check CHECK (
    frequency IN ('per_batch', 'per_step', 'periodic', 'on_demand', 'skip_lot', 'annual')
  ),
  CONSTRAINT production_qc_test_definitions_created_by_fkey FOREIGN KEY (created_by) REFERENCES aisha_auth.users(id)
);

ALTER TABLE production_qc_test_definitions ENABLE ROW LEVEL SECURITY;

-- Grants: admin-managed, read for authenticated
GRANT SELECT ON production_qc_test_definitions TO authenticated;
GRANT ALL ON production_qc_test_definitions TO service_role;

-- Indexes

-- Column documentation
COMMENT ON TABLE production_qc_test_definitions IS 'QC test specification master data. Per erp-basis.md: defines what to test, how, and acceptance criteria. Versioned for change control.';
COMMENT ON COLUMN production_qc_test_definitions.test_code IS 'Unique test code, e.g. QC-LOD, QC-CONC, QC-PH, QC-ETHANOL, QC-MOISTURE';
COMMENT ON COLUMN production_qc_test_definitions.method_ref IS 'Reference to analytical method: gravimetric, HPLC, UV-Vis, titration, Karl-Fischer, etc.';
COMMENT ON COLUMN production_qc_test_definitions.spec_limit_low IS 'Lower specification limit (NULL = no lower limit)';
COMMENT ON COLUMN production_qc_test_definitions.spec_limit_high IS 'Upper specification limit (NULL = no upper limit)';
COMMENT ON COLUMN production_qc_test_definitions.target_value IS 'Target/nominal value for the measurement';
COMMENT ON COLUMN production_qc_test_definitions.sampling_plan IS 'JSONB: {type, sample_size, acceptance_number, frequency_hours}';
COMMENT ON COLUMN production_qc_test_definitions.applicable_products IS 'Array of product names this test applies to: {Retisin, Floristen, Lyastin}';
COMMENT ON COLUMN production_qc_test_definitions.applicable_steps IS 'Array of step codes where test is performed: {DRYING, MACERATION, EXTRACTION}';
COMMENT ON COLUMN production_qc_test_definitions.frequency IS 'Testing frequency: per_batch, per_step, periodic (calendar), on_demand, skip_lot, annual';
COMMENT ON COLUMN production_qc_test_definitions.version IS 'Spec version for change control. New version = new record (old deactivated).';


