-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/sms_otp_codes.sql
-- -----------------------------------------------------------------------------

-- Table: sms_otp_codes
-- Description: Temporary storage for SMS OTP codes (managed by Edge Functions only)
-- Created: 2026-01-24
--
-- Used by Edge Functions:
--   - send-sms-otp: Creates OTP records
--   - verify-sms-otp: Verifies and marks as used
--
-- Security: No RLS policies for authenticated users - only service_role access

CREATE TABLE IF NOT EXISTS public.sms_otp_codes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  phone TEXT NOT NULL UNIQUE,
  code_hash TEXT NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  verified BOOLEAN DEFAULT false,
  attempts INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- Enable RLS (no policies = only service_role can access)
ALTER TABLE public.sms_otp_codes ENABLE ROW LEVEL SECURITY;

-- Comments
COMMENT ON TABLE public.sms_otp_codes IS 
  'Temporary storage for SMS OTP codes. Managed by Edge Functions only via service_role.';
COMMENT ON COLUMN public.sms_otp_codes.phone IS 'Phone number in E.164 format (+420123456789)';
COMMENT ON COLUMN public.sms_otp_codes.code_hash IS 'Bcrypt hash of the OTP code (never plaintext)';
COMMENT ON COLUMN public.sms_otp_codes.expires_at IS 'When the OTP expires (default 5 minutes)';
COMMENT ON COLUMN public.sms_otp_codes.verified IS 'Whether the OTP has been verified/used';
COMMENT ON COLUMN public.sms_otp_codes.attempts IS 'Number of verification attempts (max 3)';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/source_catalog_rows.sql
-- -----------------------------------------------------------------------------

-- Table: source_catalog_rows
-- RLS: ENABLED
--
-- Katalogy zdroje — celé množiny záznamů federovaného zdroje (nadcházející
-- akce, místa, členové, denní snímky KPI), jak je adaptér vydal přes
-- listCatalog() a svc-source-broker v taktu přelil přes
-- audience_sync_source_catalog.
--
-- PROČ TO EXISTUJE: plocha extranetu čte jen tabulky jádra, nikdy živé routy
-- brokeru (naměřeno 2026-09-15: KPI komunity a detail člena existovaly jen jako
-- živé /source/* routy pro Appsmith, blok na ně nedosáhl). Co má být na ploše,
-- musí ležet tady.
--
-- Platforma nezná jména věcí zdroje: `kind` je slug instance, `fields` jsou
-- skaláry v tvaru, jaký vydal adaptér. Typované sloupce a prezentaci (booleany
-- jako text — maska tabulky boolean nepřipouští) dělají POHLEDY instance.
--
-- `occurred_at` = časová osa katalogu (akce: začátek konání; snímek KPI: den;
-- člen: vstup), aby pohledy uměly řadit a filtrovat bez rozbalování jsonb.
-- `first_seen_at` se při dalším taktu NEPŘEPISUJE — „nové od posledně" je
-- odvoditelné bez historie změn.
CREATE TABLE IF NOT EXISTS public.source_catalog_rows (
  source_slug   text NOT NULL,
  kind          text NOT NULL CHECK (kind ~ '^[a-z][a-z0-9_]{1,39}$'),
  external_id   text NOT NULL CHECK (external_id <> ''),
  occurred_at   timestamp with time zone,
  fields        jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(fields) = 'object'),
  first_seen_at timestamp with time zone NOT NULL DEFAULT now(),
  synced_at     timestamp with time zone NOT NULL DEFAULT now(),
  PRIMARY KEY (source_slug, kind, external_id)
);

ALTER TABLE public.source_catalog_rows ENABLE ROW LEVEL SECURITY;
COMMENT ON TABLE public.source_catalog_rows IS
  'Source catalogs (whole record sets: events, venues, members, KPI snapshots) synced by svc-source-broker from the adapter listCatalog(). Read via instance audience_admin_*_v views; never edited by hand.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/source_period_stats.sql
-- -----------------------------------------------------------------------------

-- Table: source_period_stats
-- RLS: ENABLED
--
-- Per-month statistics of SOURCE entities (topics / events created in that
-- month), landed by svc-source-broker's scheduler from the source adapter's
-- listStats() — the same rows an operator used to get from an on-demand CSV
-- export. ONE table for both kinds: the row shape is a superset keyed by `kind`,
-- and the surface reads kind-specific VIEWS over it. Booleans are stored as
-- booleans (truth), the views decide how to SHOW them (the table mask rejects
-- raw booleans — measured 2026-09-07, one broke a whole detail).
-- Idempotent upsert on (source_slug, kind, month, external_id): the scheduler
-- re-syncs the last months every tick, so a rename or a new follow converges.
CREATE TABLE IF NOT EXISTS public.source_period_stats (
  source_slug   text NOT NULL,
  kind          text NOT NULL CHECK (kind IN ('topic', 'event')),
  month         text NOT NULL CHECK (month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  external_id   text NOT NULL,
  title         text NOT NULL DEFAULT '',
  created_by    text NOT NULL DEFAULT '',
  created_by_id text NOT NULL DEFAULT '',
  created_at    timestamp with time zone,
  date_from     timestamp with time zone,
  date_to       timestamp with time zone,
  deleted       boolean NOT NULL DEFAULT false,
  is_private    boolean NOT NULL DEFAULT false,
  official      boolean NOT NULL DEFAULT false,
  cancelled     boolean NOT NULL DEFAULT false,
  online        boolean NOT NULL DEFAULT false,
  follow_count  integer NOT NULL DEFAULT 0,
  posts_count   integer NOT NULL DEFAULT 0,
  tags          text NOT NULL DEFAULT '',
  synced_at     timestamp with time zone NOT NULL DEFAULT now(),
  PRIMARY KEY (source_slug, kind, month, external_id)
);
-- ⛔ SLOUPCE PŘIDANÉ POZDĚJI. `CREATE TABLE IF NOT EXISTS` běžící tabulku
-- NEDOPLNÍ — na instanci, kde už tabulka je, by nový sloupec nikdy nevznikl
-- a upsert by padal na "column does not exist". Proto explicitní ALTER
-- (týž vzor jako story_labels.sql / heals „Columns the pass ADDED").
ALTER TABLE public.source_period_stats ADD COLUMN IF NOT EXISTS created_by_id text NOT NULL DEFAULT '';

ALTER TABLE public.source_period_stats ENABLE ROW LEVEL SECURITY;
COMMENT ON TABLE public.source_period_stats IS
  'Per-month source statistics (topics/events created in the month) synced by svc-source-broker from the source adapter listStats(). Read via audience_admin_source_*_v views; never edited by hand.';


