-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/document_registry.sql
-- -----------------------------------------------------------------------------

-- Table: document_registry
-- Evidence layer (E3): every ingested document gets exactly one registry row per
-- content version. Dedup on (source_id, source_sha256); superseded_by chains
-- document versions (amendments, re-issues) without ever rewriting the original.

CREATE TABLE IF NOT EXISTS public.document_registry (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  source_id uuid NOT NULL,
  source_sha256 text NOT NULL,
  doc_type text NOT NULL,
  title text,
  doc_date date,
  counterparty text,
  sensitivity text NOT NULL,
  version integer DEFAULT 1 NOT NULL,
  superseded_by uuid,
  metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT document_registry_dedup UNIQUE (source_id, source_sha256),
  CONSTRAINT document_registry_source_fk FOREIGN KEY (source_id) REFERENCES public.agent_knowledge_sources(id),
  CONSTRAINT document_registry_superseded_fk FOREIGN KEY (superseded_by) REFERENCES public.document_registry(id),
  CONSTRAINT document_registry_sha256_format CHECK (source_sha256 ~ '^[0-9a-f]{64}$'),
  CONSTRAINT document_registry_doc_type_valid CHECK (
    doc_type IN ('invoice','delivery_note','order','contract','amendment','statement','report','certificate','communication','other')
  ),
  CONSTRAINT document_registry_sensitivity_valid CHECK (
    sensitivity IN ('public','internal','restricted','confidential')
  ),
  CONSTRAINT document_registry_version_positive CHECK (version >= 1)
);

ALTER TABLE public.document_registry ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.document_registry IS
  'Evidence registry: one row per (source, content hash). Originals are never rewritten; superseded_by chains versions.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/contract_register.sql
-- -----------------------------------------------------------------------------

-- Table: contract_register
-- Evidence layer (E5): structured contract extract per registered document.
-- Extraction is confidence-scored and NEVER authoritative without a human:
-- re-extract drops human_verified (enforced in upsert_contract_extract_audited).
-- NOTE: maintenance_contracts is Stripe billing — deliberately NOT reused here.

CREATE TABLE IF NOT EXISTS public.contract_register (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  document_id uuid NOT NULL,
  counterparty text,
  subject text,
  valid_from date,
  valid_to date,
  extract jsonb DEFAULT '{}'::jsonb NOT NULL,
  confidence numeric,
  human_verified boolean DEFAULT false NOT NULL,
  verified_by uuid,
  verified_at timestamp with time zone,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT contract_register_document_key UNIQUE (document_id),
  CONSTRAINT contract_register_document_fk FOREIGN KEY (document_id) REFERENCES public.document_registry(id),
  CONSTRAINT contract_register_confidence_range CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1)),
  CONSTRAINT contract_register_validity_order CHECK (valid_from IS NULL OR valid_to IS NULL OR valid_from <= valid_to),
  CONSTRAINT contract_register_verified_consistency CHECK (NOT human_verified OR verified_at IS NOT NULL)
);

ALTER TABLE public.contract_register ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.contract_register IS
  'Structured contract extracts (confidence 0-1, span-provenanced in extract jsonb). human_verified is dropped on re-extract.';


