-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/integration_events.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: integration_events
-- Popis: Univerzální event store pro trackování, idempotency a retry
--        všech příchozích webhooků a integračních událostí.
--        Klíčový pro: dedup (UNIQUE constraint), retry orchestration,
--        eskalaci exhausted eventů, self-learning z metrik.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.integration_events (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),

  -- Identity & source
  event_source    text NOT NULL                       -- 'github_webhook', 'git_webhook' (any other git host), 'stripe_webhook', 'deployment', 'n8n_callback', 'email_inbound'
                  CHECK (event_source IN (
                    'github_webhook', 'git_webhook', 'stripe_webhook',
                    'deployment', 'n8n_callback', 'manual', 'email_inbound'
                  )),
  external_id     text NOT NULL,                      -- X-GitHub-Delivery UUID, Stripe event ID, etc.
  event_type      text NOT NULL,                      -- 'pull_request.opened', 'push', 'installation.created', 'deploy_ssh_shell'

  -- Context resolution
  installation_id bigint,                             -- FK github_app_installations (NULL for non-GitHub)
  story_id        uuid REFERENCES public.partner_stories ON DELETE SET NULL,                               -- resolved from payload
  partner_id      uuid REFERENCES public.partner_profiles ON DELETE SET NULL,                               -- resolved from installation/story

  -- Processing lifecycle
  status          text NOT NULL DEFAULT 'received'
                  CHECK (status IN ('received', 'processing', 'completed', 'failed', 'exhausted', 'skipped_duplicate')),
  processing_started_at  timestamptz,
  processing_finished_at timestamptz,
  duration_ms     integer GENERATED ALWAYS AS (
                    CASE WHEN processing_started_at IS NOT NULL AND processing_finished_at IS NOT NULL
                         THEN EXTRACT(EPOCH FROM (processing_finished_at - processing_started_at))::integer * 1000
                         ELSE NULL
                    END
                  ) STORED,

  -- Retry
  attempt         integer NOT NULL DEFAULT 1,
  max_attempts    integer NOT NULL DEFAULT 3,
  next_retry_at   timestamptz,                        -- calculated exponential backoff

  -- Routing & correlation
  routed_to       text,                               -- n8n webhook path or edge function
  n8n_execution_id text,                              -- for trace correlation with n8n
  payload_hash    text,                               -- SHA-256 of payload (optional dedup helper)

  -- Error tracking
  error_json      jsonb,                              -- { message, code, stack_hint }

  -- Timestamps
  created_at      timestamptz NOT NULL DEFAULT now(),

  -- Idempotency constraint
  UNIQUE (event_source, external_id)
);

-- Comments
COMMENT ON TABLE public.integration_events IS 'Univerzální event store – idempotency, retry, observability';
COMMENT ON COLUMN public.integration_events.external_id IS 'X-GitHub-Delivery, Stripe event ID – klíč pro dedup';
COMMENT ON COLUMN public.integration_events.duration_ms IS 'Automaticky počítáno z processing timestamps (ms)';
COMMENT ON COLUMN public.integration_events.next_retry_at IS 'Exponenciální backoff: attempt 1→1min, 2→5min, 3→15min';

ALTER TABLE public.integration_events ENABLE ROW LEVEL SECURITY;

-- Columns added by later migrations (back-port reconciliation):
ALTER TABLE public.integration_events ADD COLUMN IF NOT EXISTS metadata jsonb NOT NULL DEFAULT '{}'::jsonb;

-- event_source: a self-hosted git host is no longer a NAMED integration — webhooks
-- from any git host other than GitHub are the generic 'git_webhook'. The inline
-- CHECK above only applies to a fresh table, so an existing database converges
-- here (idempotent): drop the old CHECK, relabel every value outside the new set
-- (only the retired self-hosted forge source can be one — the old CHECK allowed
-- nothing else) to 'git_webhook', re-add the CHECK. No (event_source,
-- external_id) collision is possible: 'git_webhook' did not exist before.
ALTER TABLE public.integration_events
  DROP CONSTRAINT IF EXISTS integration_events_event_source_check;
UPDATE public.integration_events
   SET event_source = 'git_webhook'
 WHERE event_source NOT IN (
         'github_webhook', 'git_webhook', 'stripe_webhook',
         'deployment', 'n8n_callback', 'manual', 'email_inbound'
       );
ALTER TABLE public.integration_events
  ADD CONSTRAINT integration_events_event_source_check
  CHECK (event_source IN (
    'github_webhook', 'git_webhook', 'stripe_webhook',
    'deployment', 'n8n_callback', 'manual', 'email_inbound'
  ));


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/knowledge_items.sql
-- -----------------------------------------------------------------------------

-- Table: knowledge_items

CREATE TABLE IF NOT EXISTS public.knowledge_items (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  item_type knowledge_item_type NOT NULL,
  source_type text DEFAULT 'manual'::text NOT NULL,
  source_id uuid,
  source_slug text,
  title text NOT NULL,
  summary text,
  body_markdown text NOT NULL,
  ai_instructions text,
  ai_context_tags text[] DEFAULT '{}'::text[],
  category text,
  expertise_area_id uuid,
  status text DEFAULT 'active'::text NOT NULL,
  visibility text DEFAULT 'public'::text NOT NULL,
  version integer DEFAULT 1 NOT NULL,
  author_id uuid,
  author_display_name text,
  usage_count integer DEFAULT 0 NOT NULL,
  rating_avg numeric DEFAULT 0 NOT NULL,
  is_verified boolean DEFAULT false NOT NULL,
  published_at timestamp with time zone,
  story_id uuid REFERENCES public.partner_stories(id) ON DELETE CASCADE,
  -- Ingestion safety / quarantine columns (migration 20260518240000_ingestion_safety.sql).
  -- Prompt-injection detector + LLM judge flag items; quarantined items
  -- are excluded from retrieval until a human review reinstates them.
  quarantine_status text DEFAULT 'clear'::text NOT NULL
    CHECK (quarantine_status IN ('clear', 'flagged', 'quarantined', 'reviewed', 'reinstated')),
  quarantine_reason text,
  quarantine_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
  safety_scanned_at timestamp with time zone,
  safety_score numeric(4, 3) CHECK (safety_score IS NULL OR safety_score BETWEEN 0 AND 1),
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  PRIMARY KEY (id)
);

ALTER TABLE public.knowledge_items ENABLE ROW LEVEL SECURITY;

-- Columns added by later migrations (back-port reconciliation):
ALTER TABLE public.knowledge_items ADD COLUMN IF NOT EXISTS has_multimodal boolean NOT NULL DEFAULT false;
ALTER TABLE public.knowledge_items ADD COLUMN IF NOT EXISTS multimodal_provider text;
-- RAG locale axis (Brick3). Behavior-neutral today: every row defaults to the
-- 'global' sentinel (FK → supported_languages.code, NO ON DELETE CASCADE). No
-- retrieval WHERE/score uses locale yet — later bricks add cross-lingual boost.
-- source_hash is the content-dedup key for re-ingestion idempotency (nullable).
ALTER TABLE public.knowledge_items ADD COLUMN IF NOT EXISTS locale text NOT NULL DEFAULT 'global';
ALTER TABLE public.knowledge_items ADD COLUMN IF NOT EXISTS source_hash text;
-- Brick5 cross-lingual: source_concept_id groups locale variants of one source node
-- (= COALESCE(source_id, id), set by trg_knowledge_source_concept_id). Retrieval dedups
-- by it (one winning variant per concept) + applies a p_locale preference-boost.
-- Nullable; set by the trigger on write, backfilled in heals.sql for existing rows.
ALTER TABLE public.knowledge_items ADD COLUMN IF NOT EXISTS source_concept_id uuid;
-- Brick6 tier-ACL: minimum_tier gates retrieval by the requesting user's audience tier
-- (anonymous < registered < active < qualified < partner < admin). NULL = ungated (everyone).
-- Enforced as a HARD WHERE filter in mcp_search_knowledge_v2/v3 via
-- audience_user_meets_tier_requirement(minimum_tier, audience_user) — an under-tier user
-- never retrieves the row (unlike locale, which is a soft rerank boost).
ALTER TABLE public.knowledge_items ADD COLUMN IF NOT EXISTS minimum_tier text;


