-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/knowledge_chunks.sql
-- -----------------------------------------------------------------------------

-- Table: knowledge_chunks

CREATE TABLE IF NOT EXISTS public.knowledge_chunks (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  knowledge_item_id uuid NOT NULL REFERENCES public.knowledge_items ON DELETE CASCADE,
  chunk_index integer NOT NULL,
  chunk_text text NOT NULL,
  token_count integer,
  section_title text,
  source_field text DEFAULT 'body'::text NOT NULL,
  -- Contextual retrieval columns (migration 20260518210000_contextual_retrieval.sql).
  -- The contextual prefix is an LLM-generated 1–2 sentence summary that gets
  -- concatenated with chunk_text before embedding so retrieval can match on
  -- broader semantic context. Tracking columns enable incremental backfill
  -- + cost analysis + model-version pinning for reproducibility.
  contextual_prefix text,
  contextual_prefix_model text,
  contextual_prefix_model_version text,
  contextual_prefix_generated_at timestamp with time zone,
  contextual_prefix_token_count integer,
  -- RAG locale axis (Brick3). Denormalized from the parent knowledge_item so the
  -- widened unique (knowledge_item_id, chunk_index, locale) lets the same source
  -- chunk coexist across locales. Defaults to the 'global' sentinel; FK →
  -- supported_languages.code (NO ON DELETE CASCADE). source_hash = per-chunk
  -- content key for re-ingestion idempotency.
  locale text NOT NULL DEFAULT 'global',
  source_hash text,
  -- Ingest provenance char-span (PR-1): half-open [char_start, char_end) offsets into
  -- the SOURCE document text so every chunk traces byte-precisely back to its origin
  -- (local-ingest kb_artifact provenance fields are 1:1). Nullable: legacy chunks and
  -- non-span sources stay valid.
  char_start integer,
  char_end integer,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT knowledge_chunks_char_span_valid CHECK (char_start IS NULL OR char_end IS NULL OR char_end >= char_start),
  PRIMARY KEY (id)
);

ALTER TABLE public.knowledge_chunks ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/knowledge_embeddings.sql
-- -----------------------------------------------------------------------------

-- Table: knowledge_embeddings

CREATE TABLE IF NOT EXISTS public.knowledge_embeddings (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  chunk_id uuid NOT NULL,
  knowledge_item_id uuid NOT NULL REFERENCES public.knowledge_items ON DELETE CASCADE,
  embedding vector(1024) NOT NULL,
  model text DEFAULT 'text-embedding-3-small'::text NOT NULL,
  model_version text,
  -- Brick2-guard model identity: FK from the human-readable `model` text mirror to the
  -- canonical ai_model_registry row that produced this vector. The text columns stay as
  -- the readable mirror; ai_model_registry has no single-col unique on model_id so a text
  -- FK is impossible — these uuid cols carry the identity link. NULLABLE (legacy rows +
  -- deferred backfill) and NO ON DELETE CASCADE (pattern: training_jobs.adapter_model_id)
  -- — deprecating a model must NEVER cascade-delete the corpus it embedded.
  model_registry_id uuid REFERENCES public.ai_model_registry(id),
  model_v2_registry_id uuid REFERENCES public.ai_model_registry(id),
  -- Embedding v2 (Qwen3, 2560-dim) parallel columns for migration.
  -- Migration 20260518230000_embedding_v2_qwen3.sql; backfill workers write
  -- here while the legacy 1536-dim column stays in service. Once v2 is at
  -- 100% coverage the v1 columns can be dropped in a separate forward
  -- migration.
  embedding_v2 halfvec(2560),
  model_v2 text,
  model_v2_version text,
  v2_generated_at timestamp with time zone,
  v2_status text DEFAULT 'pending'
    CHECK (v2_status IN ('pending', 'generated', 'failed', 'skipped')),
  -- RAG locale axis (Brick3). Denormalized from the parent chunk so the widened
  -- unique (chunk_id, locale) lets per-locale embeddings of one chunk coexist.
  -- Defaults to the 'global' sentinel; FK → supported_languages.code (NO ON
  -- DELETE CASCADE). No source_hash here (lives on chunks/items).
  locale text NOT NULL DEFAULT 'global',
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  PRIMARY KEY (id)
);

ALTER TABLE public.knowledge_embeddings ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/knowledge_multimodal_pages.sql
-- -----------------------------------------------------------------------------

-- Table: knowledge_multimodal_pages

CREATE TABLE IF NOT EXISTS public.knowledge_multimodal_pages (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  knowledge_item_id uuid NOT NULL,
  page_number integer NOT NULL,
  page_image_uri text,
  page_image_sha256 text,
  page_text text,
  -- halfvec type referenced UNQUALIFIED (matches sibling knowledge_embeddings) — the
  -- pgvector extension is in `extensions` on a fresh baseline, so a public-qualified
  -- type is unresolvable from zero; bare + search_path (public, extensions) resolves it.
  embedding_v2 halfvec(2560),
  embedding_model text,
  embedding_version text,
  embedding_generated_at timestamp with time zone,
  status text DEFAULT 'pending'::text NOT NULL,
  metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT knowledge_multimodal_pages_page_number_check CHECK ((page_number > 0)),
  CONSTRAINT knowledge_multimodal_pages_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'embedded'::text, 'failed'::text, 'skipped'::text]))),
  PRIMARY KEY (id),
  CONSTRAINT knowledge_multimodal_pages_knowledge_item_id_page_number_key UNIQUE (knowledge_item_id, page_number),
  CONSTRAINT knowledge_multimodal_pages_knowledge_item_id_fkey FOREIGN KEY (knowledge_item_id) REFERENCES public.knowledge_items(id) ON DELETE CASCADE
);

ALTER TABLE public.knowledge_multimodal_pages ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.knowledge_multimodal_pages IS 'Step 8: page-level multimodal embeddings for PDF/document items. Opt-in per knowledge_item via has_multimodal flag. Embedding model selected at runtime by capability-resolver rag.multimodal_page (e.g. ColQwen3-4B self-hosted on vLLM).';


