-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/obligation_register.sql
-- -----------------------------------------------------------------------------

-- Table: obligation_register
-- Evidence layer (E5): obligations extracted from contracts. LEGAL CONTENT IS
-- NEVER AUTHORITATIVE WITHOUT A HUMAN — rows land with human_confirmed=false
-- (engine emits obligations as NEEDS_REVIEW, verbatim citation + char span
-- back to the clause). due_rule drives deadline watchers (F4).

CREATE TABLE IF NOT EXISTS public.obligation_register (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  contract_id uuid NOT NULL,
  obliged_party text NOT NULL,
  action text NOT NULL,
  due_rule jsonb DEFAULT '{}'::jsonb NOT NULL,
  consequence text,
  source_clause jsonb NOT NULL,
  human_confirmed boolean DEFAULT false NOT NULL,
  confirmed_by uuid,
  confirmed_at timestamp with time zone,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT obligation_register_contract_fk FOREIGN KEY (contract_id) REFERENCES public.contract_register(id) ON DELETE CASCADE,
  CONSTRAINT obligation_register_due_rule_shape CHECK (due_rule ? 'kind'),
  CONSTRAINT obligation_register_source_clause_shape CHECK (
    source_clause ? 'section' AND source_clause ? 'char_start' AND source_clause ? 'char_end'
  ),
  CONSTRAINT obligation_register_confirmed_consistency CHECK (NOT human_confirmed OR confirmed_at IS NOT NULL)
);

ALTER TABLE public.obligation_register ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.obligation_register IS
  'Obligations per contract (obliged_party, action, due_rule, consequence, clause span). Always born unconfirmed.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/agent_knowledge_bindings.sql
-- -----------------------------------------------------------------------------

-- Table: agent_knowledge_bindings
-- Source-of-truth for "which agent has which expert_rule attached as
-- knowledge / memory / context / policy". The table was referenced by
-- mcp_get_agent_knowledge from day one but its CREATE TABLE only lived
-- in the auto-generated baseline — never in SoT. Phase 5 closes that gap.
--
-- Despite the column name `knowledge_item_id`, the FK target is
-- expert_rules(id), not knowledge_items(id). This matches the existing
-- mcp_get_agent_knowledge usage. The name is preserved for backward
-- compatibility (renaming would touch every caller).
--
-- Visibility scope: `story_id` is NULLABLE. NULL = global binding
-- (applies whenever the agent runs anywhere). A non-null story_id scopes
-- the binding to one story — the bot↔KB matrix in AdminStoryDetail
-- writes per-story rows so partner work can have its own rule set
-- without bleeding into the AISHA stack-default story.
--
-- See also: mcp_get_agent_knowledge (consumer), agent_catalog (slug
-- source), expert_rules (FK target).

CREATE TABLE IF NOT EXISTS public.agent_knowledge_bindings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),

  -- Soft FK to agent_catalog.slug — kept as text for flexibility (custom
  -- agent slugs from MCP servers may not be in agent_catalog yet).
  agent_slug text NOT NULL,

  -- FK to expert_rules.id (NOT knowledge_items — historical naming).
  knowledge_item_id uuid NOT NULL
    REFERENCES public.expert_rules(id) ON DELETE CASCADE,

  -- 'rule' | 'memory' | 'context' | 'policy' (free-text for now; tighten
  -- via lookup table if/when binding kinds stabilize).
  binding_type text NOT NULL DEFAULT 'rule',

  -- Higher = earlier in mcp_get_agent_knowledge ORDER BY priority DESC.
  -- Default 100; values 1..1000 are conventional.
  priority int NOT NULL DEFAULT 100,

  -- Optional pinned version (nullable = always use current rule version).
  version int,

  -- Soft-disable a binding without dropping the row (preserves audit
  -- history). Partial unique below enforces uniqueness only on active rows.
  is_active boolean NOT NULL DEFAULT true,

  -- NULL = global binding; non-null scopes to a partner story.
  story_id uuid REFERENCES public.partner_stories(id) ON DELETE CASCADE,

  -- Operator-facing notes — surfaces in admin binding matrix.
  notes text,

  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid REFERENCES aisha_auth.users(id) ON DELETE SET NULL
);

ALTER TABLE public.agent_knowledge_bindings ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.agent_knowledge_bindings IS
  'Bot ↔ expert_rule attachment matrix (despite the legacy column name knowledge_item_id, FK is to expert_rules). Consumed by mcp_get_agent_knowledge; written by Phase 5 StoryBindingsTab.';

-- Indexes live in aisha/db/sql/indexes/idx_agent_knowledge_bindings.sql
-- per SQL Source Separation rule.


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/openclaw_notifications.sql
-- -----------------------------------------------------------------------------

-- Table: openclaw_notifications
-- Outbox for AISHA → OpenClaw outbound notifications.
-- AISHA INSERTs a row; n8n's WF_OPENCLAW_NOTIFY scans every 30s and dispatches
-- to the appropriate channel (Telegram/Slack/Matrix/in_app) via OpenClaw.
--
-- Mirrors the blockchain_audit_records outbox pattern.

CREATE TABLE IF NOT EXISTS public.openclaw_notifications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),

  -- Channel selection
  channel text NOT NULL CHECK (channel IN ('telegram', 'slack', 'matrix', 'discord', 'email', 'in_app')),
  recipient text,
  template text NOT NULL DEFAULT 'plain',

  -- Payload — channel-specific shape, validated by template handler in OpenClaw
  payload jsonb NOT NULL,

  -- Lifecycle
  status text NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued', 'sending', 'sent', 'failed', 'cancelled')),
  attempt_count int NOT NULL DEFAULT 0,
  max_attempts int NOT NULL DEFAULT 5,
  next_retry_at timestamptz,
  sent_at timestamptz,
  error text,

  -- AISHA context
  agent_slug text DEFAULT 'aisha',
  related_run_id uuid REFERENCES public.ai_runs(id),
  story_id uuid REFERENCES public.partner_stories ON DELETE SET NULL,

  created_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.openclaw_notifications ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.openclaw_notifications IS
  'AISHA → OpenClaw outbound notification outbox. WF_OPENCLAW_NOTIFY scans + '
  'dispatches every 30s. Channels: telegram/slack/matrix/discord/email/in_app.';

-- Indexes live in aisha/db/sql/indexes/idx_openclaw_notifications.sql per
-- SQL Source Separation rule.

-- Columns added by later migrations (back-port reconciliation):
ALTER TABLE public.openclaw_notifications ADD COLUMN IF NOT EXISTS user_id uuid;
ALTER TABLE public.openclaw_notifications ADD COLUMN IF NOT EXISTS campaign_id uuid;
ALTER TABLE public.openclaw_notifications ADD COLUMN IF NOT EXISTS campaign_run_id uuid;
ALTER TABLE public.openclaw_notifications ADD COLUMN IF NOT EXISTS opened_at timestamp with time zone;
ALTER TABLE public.openclaw_notifications ADD COLUMN IF NOT EXISTS clicked_at timestamp with time zone;
ALTER TABLE public.openclaw_notifications ADD COLUMN IF NOT EXISTS bounced_at timestamp with time zone;
ALTER TABLE public.openclaw_notifications ADD COLUMN IF NOT EXISTS unsubscribed_at timestamp with time zone;


