-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/health_metrics.sql
-- -----------------------------------------------------------------------------

-- Migration: health_metrics table for baseline tracking
-- Purpose: Store time-series health metrics for comparison with registration baseline
-- Related: Registration wizard migration, baseline tracking feature

-- =============================================================================
-- 1. CREATE TABLE
-- =============================================================================

CREATE TABLE IF NOT EXISTS public.health_metrics (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES aisha_auth.users(id) ON DELETE CASCADE,
  study_registration_id UUID REFERENCES public.study_registrations(id) ON DELETE SET NULL,
  
  -- Timestamp of measurement
  measured_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  
  -- Scale metrics (1-10)
  physical_state INTEGER CHECK (physical_state IS NULL OR physical_state BETWEEN 1 AND 10),
  mental_state INTEGER CHECK (mental_state IS NULL OR mental_state BETWEEN 1 AND 10),
  energy_level INTEGER CHECK (energy_level IS NULL OR energy_level BETWEEN 1 AND 10),
  stress_level INTEGER CHECK (stress_level IS NULL OR stress_level BETWEEN 1 AND 10),
  sleep_quality INTEGER CHECK (sleep_quality IS NULL OR sleep_quality BETWEEN 1 AND 10),
  
  -- Numeric metrics
  weight_kg NUMERIC(5,2) CHECK (weight_kg IS NULL OR weight_kg BETWEEN 20 AND 500),
  height_cm NUMERIC(5,1) CHECK (height_cm IS NULL OR height_cm BETWEEN 50 AND 300),
  
  -- Pain metrics (for comparison with health_check_ins)
  pain_level INTEGER CHECK (pain_level IS NULL OR pain_level BETWEEN 0 AND 10),
  
  -- Source tracking
  source TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('registration', 'check_in', 'wearable', 'manual', 'lab_result')),
  source_id UUID,  -- Reference to source record (health_check_in.id, etc.)
  
  -- Metadata
  notes TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Comments
COMMENT ON TABLE public.health_metrics IS 'Time-series health metrics for baseline comparison';
COMMENT ON COLUMN public.health_metrics.source IS 'Origin of the metric: registration, check_in, wearable, manual, lab_result';
COMMENT ON COLUMN public.health_metrics.source_id IS 'Reference to the source record (e.g., health_check_in.id)';

-- =============================================================================
-- 2. ROW LEVEL SECURITY
-- =============================================================================

ALTER TABLE public.health_metrics ENABLE ROW LEVEL SECURITY;

-- =============================================================================
-- 3. GRANTS
-- =============================================================================

GRANT SELECT, INSERT, UPDATE ON public.health_metrics TO authenticated;

-- Note: RLS Policies are in supabase/sql/policies/health_metrics__*.sql
-- Note: Indexes are in supabase/sql/indexes/idx_health_metrics_*.sql
-- Note: Triggers are in supabase/sql/triggers/set_health_metrics_updated_at.sql


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/member_health_documents.sql
-- -----------------------------------------------------------------------------

-- Table: member_health_documents
-- RLS: ENABLED

CREATE TABLE IF NOT EXISTS member_health_documents (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  document_type text,
  file_url text,
  file_name text,
  file_size int4,
  mime_type text,
  description text,
  created_at timestamptz DEFAULT now(),
  uploaded_at timestamptz DEFAULT now(),
  verified_at timestamptz,
  verified_by uuid,
  study_registration_id uuid,
  file_path text,
  title text,
  category health_document_category DEFAULT 'other'::health_document_category,
  document_date date,
  processing_status document_processing_status DEFAULT 'pending'::document_processing_status,
  -- AV/safety gate, orthogonal to processing_status the OCR/AI lifecycle. Same value set and
  -- gating predicate as knowledge_items.quarantine_status, so one platform primitive governs
  -- malware quarantine across tables. Column DEFAULT 'clear' keeps existing and non-upload rows
  -- promotable so there is no regression; the upload preflight overrides it to 'flagged' so a
  -- new upload is fail-closed until the AV scan promotes it. Sole post-upload writer is
  -- record_document_av_scan_audited.
  quarantine_status text DEFAULT 'clear'::text NOT NULL
    CHECK (quarantine_status IN ('clear', 'flagged', 'quarantined', 'reviewed', 'reinstated')),
  av_signature text,
  av_scanned_at timestamptz,
  extracted_text text,
  ocr_metadata jsonb,
  capture_metadata jsonb,
  extracted_data jsonb,
  ai_summary text,
  ai_categories text[],
  ai_insights jsonb,
  processed_at timestamptz,
  contributed_to_statistics bool DEFAULT false,
  contributed_at timestamptz,
  tokens_awarded numeric DEFAULT 0,
  tokens_awarded_at timestamptz,
  review_notes text,
  updated_at timestamptz DEFAULT now(),
  PRIMARY KEY (id),
  CONSTRAINT member_health_documents_study_registration_id_fkey FOREIGN KEY (study_registration_id) REFERENCES study_registrations(id),
  CONSTRAINT member_health_documents_user_id_fkey FOREIGN KEY (user_id) REFERENCES aisha_auth.users(id) ON DELETE CASCADE,
  CONSTRAINT member_health_documents_verified_by_fkey FOREIGN KEY (verified_by) REFERENCES aisha_auth.users(id)
);

ALTER TABLE member_health_documents ENABLE ROW LEVEL SECURITY;

