-- File: aisha/db/sql/tables/surface_layouts.sql
-- -----------------------------------------------------------------------------

-- Přiřazení bloků na surface + pořadí. Řádky = instance data.

create table if not exists public.surface_layouts (
  id         uuid primary key default gen_random_uuid(),
  -- Sekce extranetu (ask, workflow, registry, workbench, porada, …) — NE zařízení.
  -- Otevřený text ZÁMĚRNĚ: které sekce existují, co obsahují a v jakém pořadí je
  -- DATA, která servíruje backend. Nová sekce = řádek, ne migrace a ne release
  -- klienta. Táž konvence jako `ide_sessions.source`.
  --
  -- Uzavřený výčet tu byl a stál nás to: 'porada' šla do CHECKu ALTERem mimo SoT,
  -- takže repo znalo 3 hodnoty a živá DB 4. Zároveň se zařízení pletlo se sekcí,
  -- takže se tytéž bloky duplikovaly per web/mobile — a 'porada' skončila
  -- definovaná dvakrát (kurátorovaný web layout + podmnožina propašovaná do
  -- 'mobile'), přičemž mobilní obrazovka porady nezobrazila ani jednu.
  -- Přizpůsobení zařízení je práce rendereru, ne osa téhle tabulky.
  --
  -- Uzavřený zůstává `surface_blocks.block_type` — ten pojmenovává renderer.
  -- ⛔ POJMENOVANÉ, ne anonymní (2026-08-25). Anonymní check si Postgres pojmenuje
  -- sám (`surface_layouts_surface_check`), jenže heals.sql ho od 2026-08-17
  -- přejmenovává na `surface_layouts_surface_nonempty`. Dvě cesty upgradu tím
  -- končily u schémat, která se liší JMÉNEM omezení při shodné podmínce —
  -- přesně to, co db-convergence-schema-equivalence hlídá. Nevšiml si toho nikdo
  -- osm dní, protože ta brána je DB-REQUIRING a v offline `test:gates` se
  -- PŘESKAKUJE; běží jen pod throwaway-DB harnessem.
  surface    text not null constraint surface_layouts_surface_nonempty check (length(surface) > 0),
  block_id   uuid not null references public.surface_blocks(id) on delete cascade,
  -- Publikum: dnes tier-based model (audience_user_meets_tier_requirement); po Sprint 3.7
  -- namespace ACL. Vyhodnocení se doplní do RLS/RPC — sloupec drží deklaraci.
  audience   jsonb not null default '{}'::jsonb,
  position   integer not null default 0 check (position >= 0),
  is_active  boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (surface, block_id)
);

comment on table public.surface_layouts is
  'Per-surface block placement and ordering. Rows are instance data.';

ALTER TABLE public.surface_layouts ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/surface_scope_axes.sql
-- -----------------------------------------------------------------------------

-- Table: surface_scope_axes
-- RLS: ENABLED
--
-- OSY POHLEDU JSOU DATA (ADR-003 K5).
--
-- ⛔ NAMĚŘENO 2026-09-06: seznam os („čím smím omezit, na co se dívám") byl
-- konstantou v generickém shellu (`SCOPE_AXES` v App.tsx) a nesl JMÉNA VĚCÍ
-- jedné instance — `owner_company`, `unit_site`. Důsledek: v sanghě obě osy
-- vracely nula voleb, přepínač se vůbec nevykreslil, a každá nová instance by
-- si musela osu přidat editací forku. To je přesně zákon jmen naruby: jádro
-- zná druhy věcí, nikdy jména věcí.
--
-- ⭐ Řádek tady = jedna osa. Jméno osy i její substrát dodává OVERLAY instance;
-- jádro zná jen DRUHY substrátů (viz `get_scope_options`: twin_kind, relation,
-- label, template, twin, registry). Volby se pak ODVOZUJÍ z dat, neudržují se
-- v číselníku, který by se rozešel se skutečností.
--
-- `params` jde beze změny do `get_scope_options` (druh substrátu + jeho klíč).
-- `dim` je jméno parametru, pod kterým zvolená hodnota doputuje do bloků sekce
-- (`get_block_data(slug, {dim: value})`) — blok ji přijme jen tehdy, když ji
-- deklaruje ve `filters` a (u restricted) v `client_params` (K3).
-- `surfaces` omezuje osu na sekce; prázdné pole = všechny sekce.

create table if not exists public.surface_scope_axes (
  axis_key    text primary key
              check (axis_key ~ '^[a-z][a-z0-9_.]*$'),
  title_key   text not null check (length(title_key) > 0),
  dim         text not null check (dim ~ '^[a-z][a-z0-9_]*$'),
  params      jsonb not null default '{}'::jsonb
              check (jsonb_typeof(params) = 'object'),
  surfaces    jsonb not null default '[]'::jsonb
              check (jsonb_typeof(surfaces) = 'array'),
  audience    jsonb not null default '{}'::jsonb,
  namespace   text not null,
  position    integer not null default 0 check (position >= 0),
  is_active   boolean not null default false,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

comment on table public.surface_scope_axes is
  'Declared axes of the view switcher (lens). One row = one axis; the instance overlay supplies its name and substrate, the kernel only knows substrate KINDS (see get_scope_options). Options are derived from data, never kept in a codebook.';

alter table public.surface_scope_axes enable row level security;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/surface_section_grants.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- surface_section_grants — do které sekce extranetu smí KONKRÉTNÍ uživatel.
--
-- ⭐ ROZHODNUTÍ MAJITELE 2026-09-28: „přístup k datům z podstaty úhlu pohledu je
-- jedna věc, přístup do sekce extranetu je další úroveň. Stačilo by každou sekci
-- extranetu u uživatele v administraci nastavovat — a tam pak vidí jen data, na
-- která má nárok." Proto udělení u uživatele, ne role: role je pevný výčet stacku
-- a jméno sekce je slovník instance.
--
-- Vyhodnocuje ho JEDINÝ interpret publika (surface_audience_allows, osa
-- `"udeleni": "<sekce>"`): řádek umístění s touhle osou uvidí správa (bypass)
-- nebo uživatel s udělením. Data v sekci dál řídí nárok (RLS) — udělení otevírá
-- dveře, ne data.
--
-- Zápis jen přes surface_udel_admin (auditované); čtení přes interpret a
-- surface_udeleni_admin. RLS bez politik, žádné granty pro anon/authenticated.
-- =============================================================================
CREATE TABLE IF NOT EXISTS public.surface_section_grants (
  user_id     uuid        NOT NULL REFERENCES aisha_auth.users (id) ON DELETE CASCADE,
  surface     text        NOT NULL CHECK (surface ~ '^[a-z][a-z0-9_]*$'),
  granted_by  uuid,
  granted_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT surface_section_grants_pkey PRIMARY KEY (user_id, surface)
);

COMMENT ON TABLE public.surface_section_grants IS
  'Udělení sekce extranetu uživateli (osa publika "udeleni"). Otevírá sekci, data dál řídí nárok. Zápis jen surface_udel_admin.';

ALTER TABLE public.surface_section_grants ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.surface_section_grants FROM PUBLIC, anon, authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/surface_sections.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: surface_sections
-- Popis: NAVIGACE JAKO DATA — ŠABLONA sekcí extranetu, kterou vlastní OVERLAY
--        INSTANCE (deploy): jaké sekce existují, klíč jména, ikona, skupina,
--        pořadí, výchozí stav a publikum.
--
--        Zákaznické úpravy žijí VEDLE, v public.surface_section_overrides
--        (vlastní administrace). Efektivní hodnota = coalesce(override, šablona),
--        takže deploy smí šablonu opravovat a rozšiřovat, aniž smaže, co si
--        zákazník přejmenoval; reset = smazání override. Jedna tabulka se dvěma
--        zapisovateli by nekonvergovala nikdy — přesně jako kdysi rozvržení.
--
--        VŠE PŘES KLÍČE: title_key/group_key/reason_key míří do `translations`
--        (key, namespace, locale) — tam, kde žijí překlady stránek i dotazníků.
--        Přejmenování sekce v administraci = upsert překladu pod klíčem, NIKDY
--        uložený řetězec v jednom jazyce.
--
--        Stav 'inactive' = sekce deklarovaná, ale bez napojeného zdroje:
--        v navigaci VIDITELNÁ, zašedlá, s důvodem (reason_key). Skrýt ji by
--        zákazníkovi tvrdilo, že to produkt neumí; nechat ji aktivní by ukázalo
--        prázdno, které vypadá jako chyba.
--
--        Sekce s bloky ŠABLONU NEPOTŘEBUJE — list_surface_sections ji odvodí
--        z rozvržení jako dosud. Šablona jen přidává: skupinu, pořadí, ikonu
--        a deklarované neaktivní sekce. Instance bez šablony funguje beze změny.
-- RLS: ENABLED — politika v sql/policies/surface_sections_read.sql, granty
--        v sql/grants/surface_tables.sql, trigger updated_at v sql/triggers/.
--        Rozdělení do těch složek NENÍ kosmetika: baseline emituje tables/ PŘED
--        functions/, takže trigger volající public.set_updated_at() musí přijít
--        až z triggers/, jinak cold start padne na neexistující funkci.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.surface_sections (
  surface      text PRIMARY KEY,
  title_key    text,
  icon         text,
  group_key    text,
  group_order  integer      NOT NULL DEFAULT 0,
  position     integer      NOT NULL DEFAULT 0,
  state        text         NOT NULL DEFAULT 'active'
               CHECK (state IN ('active', 'inactive')),
  reason_key   text,
  -- Publikum ŠABLONOVÉ sekce (hlavně těch neaktivních — ty nemají rozvržení,
  -- takže je RLS nad surface_layouts neořeže). Týž interpret jako všude:
  -- surface_audience_allows; {} = každý přihlášený, neznámý klíč = DENY.
  audience     jsonb        NOT NULL DEFAULT '{}'::jsonb,
  is_active    boolean      NOT NULL DEFAULT true,
  created_at   timestamptz  NOT NULL DEFAULT now(),
  updated_at   timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT surface_sections_surface_not_blank CHECK (btrim(surface) <> '')
);

COMMENT ON TABLE public.surface_sections IS
  'Šablona navigace extranetu (vlastní instance overlay). Override vrstvu vlastní administrace; efektivní hodnota = coalesce(override, šablona).';

-- ⭐ SONDA DAT (rozhodnutí majitele 2026-09-28): „pokud nemá žádná data, která
-- má možnost vidět, není potřeba, aby danou sekci viděl, byť do ní má přístup."
-- Deklarace, podle které list_surface_sections sekci běžnému uživateli skryje,
-- když pro něj nic nemá (správa vidí vždy). Druhy: {"doklady": ["contract", …]}
-- = existuje aspoň jeden platný doklad těch typů, který uživatel pod RLS vidí.
-- Sonda NENÍ hranice přístupu (tu drží publikum a RLS): chybná deklarace sekci
-- neskryje. NULL = bez sondy.
ALTER TABLE public.surface_sections ADD COLUMN IF NOT EXISTS presence jsonb
  CHECK (presence IS NULL OR jsonb_typeof(presence) = 'object');

ALTER TABLE public.surface_sections ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/surface_section_overrides.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: surface_section_overrides
-- Popis: ZÁKAZNICKÁ VRSTVA nad šablonou navigace (public.surface_sections).
--        Vlastní ji ADMINISTRACE a zapisuje se výhradně přes
--        set_surface_section_override_admin — deploy soubor se jí nikdy nedotkne.
--
--        Všechny osy jsou NULLABLE a null znamená „platí šablona"; efektivní
--        hodnota = coalesce(override, šablona), reset = smazání řádku. Proto
--        smí instance overlay šablonu opravovat a rozšiřovat, aniž přepíše, co
--        si zákazník přejmenoval nebo přesunul.
--
--        ON DELETE CASCADE je záměr: sekce, kterou deploy už nedeklaruje, nemá
--        co ladit — její override zmizí s ní.
--
--        Jména VÝHRADNĚ klíči (title_key/group_key/reason_key) do `translations`,
--        nikdy uložený text: přejmenování v administraci je upsert překladu.
-- RLS: ENABLED — politika v sql/policies/surface_section_overrides_read.sql,
--        granty v sql/grants/surface_tables.sql, trigger v sql/triggers/.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.surface_section_overrides (
  surface      text PRIMARY KEY REFERENCES public.surface_sections(surface) ON DELETE CASCADE,
  title_key    text,
  icon         text,
  group_key    text,
  group_order  integer,
  position     integer,
  state        text CHECK (state IS NULL OR state IN ('active', 'inactive')),
  reason_key   text,
  updated_at   timestamptz NOT NULL DEFAULT now(),
  updated_by   uuid REFERENCES aisha_auth.users(id)
);

COMMENT ON TABLE public.surface_section_overrides IS
  'Zákaznické úpravy šablony sekcí (vlastní administrace, zapisuje se výhradně přes set_surface_section_override_admin). NULL sloupec = platí šablona.';

ALTER TABLE public.surface_section_overrides ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/surface_snapshots.sql
-- -----------------------------------------------------------------------------

-- Publikované podepsané read-only snímky (Ed25519). CHECK vynucuje offline cap:
-- confidential se do snímku NIKDY nedostane (fail-closed už na zápisu, parita s emitorem,
-- který při bloku > restricted ABORTUJE — žádné tiché stripování).

create table if not exists public.surface_snapshots (
  id               uuid primary key default gen_random_uuid(),
  snapshot_slug    text not null check (snapshot_slug ~ '^[a-z0-9][a-z0-9_-]*$'),
  -- Sekce, ne zařízení — otevřený text, viz surface_layouts.surface. Uzavřený
  -- výčet tu znamenal, že pro 'porada' NEŠLO snímek vůbec podepsat.
  -- Bezpečnostní hranicí snímku je max_sensitivity níže, ne jméno sekce.
  -- Pojmenované, ne anonymní — týž důvod jako u surface_layouts.surface:
  -- heals.sql omezení přejmenovává, takže anonymní jméno rozchází baseline
  -- s reconcile cestou (viz komentář tam).
  surface          text not null constraint surface_snapshots_surface_nonempty check (length(surface) > 0),
  -- payload = SnapshotEnvelope (schema @aisha/surface-blocks snapshot/v1) BEZ podpisových polí
  payload          jsonb not null,
  max_sensitivity  text not null
                   check (max_sensitivity in ('public','internal','restricted')),
  sha256           text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  signature        text not null check (length(signature) > 0),  -- base64url Ed25519
  key_id           text not null check (length(key_id) > 0),
  published_at     timestamptz not null default now(),
  expires_at       timestamptz not null,
  check (expires_at > published_at)
);

comment on table public.surface_snapshots is
  'Signed read-only snapshots for offline surfaces. max_sensitivity capped at restricted BY CHECK.';

ALTER TABLE public.surface_snapshots ENABLE ROW LEVEL SECURITY;


