-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/twin_events.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_events
-- Popis: Události dvojčat (jízda, příjezd, přiřazení řidič↔vůz, plánovaný
--        úkol, výpadek GPS…) — append-only doménová vrstva, na které se
--        potkávají tvary: plán (úkol zdroje) × skutečnost (telemetrie) ×
--        doklad (dokument v li_*/document_registry přes story).
--        Idempotentní import: dedup přes partial unique index
--        uq_twin_events_source_ref (source, event_type, source_ref) —
--        opakovaný import stejného okna aktualizuje ended_at/attrs,
--        nevytváří duplicitu (vzor wd_rides).
--        ended_at IS NULL = událost trvá / rozpracovaná (vzor wd_rides.end_time).
--        Temporální vazby (přiřazení řidič↔vůz) jsou událost s ended_at,
--        NIKDY mutable sloupec na entitě.
--        story_id = vazba na obchodní případ (story spine) — bez FK: story
--        žije ve vlastní doméně, událost ji jen referencuje.
--        Spravováno: twin_record_events_audited (service/adaptéry).
-- RLS: ENABLED
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.twin_events (
  id              uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  event_type      text         NOT NULL,
  twin_id         uuid         NOT NULL REFERENCES public.twin_entities(id) ON DELETE CASCADE,
  related_twin_id uuid         REFERENCES public.twin_entities(id) ON DELETE SET NULL,
  place_twin_id   uuid         REFERENCES public.twin_entities(id) ON DELETE SET NULL,
  story_id        uuid,
  occurred_at     timestamptz  NOT NULL,
  ended_at        timestamptz,
  attrs           jsonb        NOT NULL DEFAULT '{}'::jsonb,
  source          text         NOT NULL,
  source_ref      text,
  created_at      timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT twin_events_event_type_not_blank CHECK (btrim(event_type) <> ''),
  CONSTRAINT twin_events_source_not_blank CHECK (btrim(source) <> ''),
  CONSTRAINT twin_events_time_order CHECK (ended_at IS NULL OR ended_at >= occurred_at)
);

COMMENT ON TABLE public.twin_events IS 'Události dvojčat (append-only) — místo setkání plán×skutečnost×doklad; dedup importu přes (source, event_type, source_ref)';
COMMENT ON COLUMN public.twin_events.event_type IS 'Volný slug (ride/arrival/assignment/task_planned/gps_gap…) — slovník je doménová/instance volba';
COMMENT ON COLUMN public.twin_events.related_twin_id IS 'Druhá strana vazby — u jízdy řidič k vozidlu, u přiřazení vůz k řidiči';
COMMENT ON COLUMN public.twin_events.place_twin_id IS 'Místo události jako twin entita (Place) — příjezd/odjezd/nakládka';
COMMENT ON COLUMN public.twin_events.story_id IS 'Obchodní případ (story spine), v němž událost figuruje — bez FK, story je vlastní doména';
COMMENT ON COLUMN public.twin_events.ended_at IS 'NULL = trvá / rozpracovaná (jízda bez konce, otevřené přiřazení)';
COMMENT ON COLUMN public.twin_events.source_ref IS 'Externí id události ve zdroji (Id_jizda, task id…) — klíč idempotence importu';

ALTER TABLE public.twin_events ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/twin_external_refs.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_external_refs
-- Popis: Mapování externích identit na dvojčata (= „external_entity_refs"
--        ze zadání digital twin) S RATIFIKAČNÍM WORKFLOW: zdroj/pravidlo
--        vazbu NAVRHUJE (proposed, s evidencí proposed_by/confidence),
--        člověk POTVRZUJE (confirmed + confirmed_by = audit trail).
--        Import NIKDY nepřepisuje potvrzené — nová evidence na potvrzený
--        klíč vzniká jako další proposed řádek (review, ne overwrite).
--        Vazby jsou TEMPORÁLNÍ (valid_from/valid_to): čip/vůz se předává,
--        účet se ruší — historie se neztrácí, ukončuje se platnost.
--        Unikátnost aktivního vlastníka klíče vynucuje partial unique index
--        uq_twin_external_refs_active_owner (Dallas čip nemůže patřit dvěma
--        lidem naráz).
--        Spravováno: twin_upsert_entity_audited (primary_id z importu,
--        confirmed_by NULL = systémové potvrzení identity vlastního zdroje)
--        a twin_identity_*_binding RPC (lidská ratifikace cross-source vazeb)
--        a claim_invitation (vazba účtu z UPLATNĚNÉ POZVÁNKY). Ta zapisuje
--        DVĚMA způsoby a rozdíl je podstatný: pozvánka je propojení BUDOUCÍ
--        identity s entitou, takže autorizaci předpřipravil odesílatel — otázka
--        při uplatnění není „smí?", ale „je to on?".
--          · ADRESOVANÁ (e-mail pozvánky = e-mail účtu) → `confirmed`,
--            `confirmed_by` = správce, který ji vystavil (rozhodl on).
--          · NEADRESOVANÁ (kód předaný jinak) → `proposed`; není koho ověřit,
--            takže předpřipravená autorizace nemá nositele a ratifikuje člověk.
-- RLS: ENABLED
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.twin_external_refs (
  id            uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  twin_id       uuid         NOT NULL REFERENCES public.twin_entities(id) ON DELETE CASCADE,
  source        text         NOT NULL,
  source_key    text         NOT NULL,
  ref_kind      text         NOT NULL DEFAULT 'primary_id',
  -- Druh dvojčete, na které vazba ukazuje — ODVOZENÝ (trigger z twin_entities),
  -- nikdy od volajícího. Je součástí klíče jedinečnosti potvrzené vazby.
  entity_type   text         NOT NULL,
  state         text         NOT NULL DEFAULT 'proposed'
                CHECK (state IN ('proposed', 'confirmed', 'rejected', 'superseded')),
  proposed_by   text         NOT NULL,
  confidence    numeric      CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1)),
  confirmed_by  uuid,
  confirmed_at  timestamptz,
  valid_from    timestamptz  NOT NULL DEFAULT now(),
  valid_to      timestamptz,
  note          text,
  created_at    timestamptz  NOT NULL DEFAULT now(),
  updated_at    timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT twin_external_refs_source_not_blank CHECK (btrim(source) <> ''),
  CONSTRAINT twin_external_refs_key_not_blank CHECK (btrim(source_key) <> ''),
  CONSTRAINT twin_external_refs_kind_not_blank CHECK (btrim(ref_kind) <> ''),
  -- ⛔ MODEL A ČTENÁŘ SI NESMÍ PROTIŘEČIT (2026-09-10).
  -- Obecně `source` ROZLIŠUJE: týž klíč ve dvou zdrojích jsou dvě různé věci
  -- (osobní číslo ve Webdispečinku × osobní číslo jinde spolu nesouvisejí).
  -- U vazby ÚČTU to ale neplatí — účet je jeden bez ohledu na to, kdo o něm
  -- píše — a `workflow_step_visible_to` proto `source` VŮBEC NEČTE.
  --
  -- Ten rozpor se dosud jen zakrýval indexem. Index je pojistka; tohle je
  -- odstranění nejednoznačnosti: u `account` smí být jediná hodnota, takže
  -- dvě vazby na týž účet z různých zdrojů NEJDE ani vyrobit.
  CONSTRAINT twin_external_refs_account_source
    CHECK (ref_kind <> 'account' OR source = 'aisha_auth'),
  CONSTRAINT twin_external_refs_confirmed_has_at
    CHECK (state <> 'confirmed' OR confirmed_at IS NOT NULL),
  CONSTRAINT twin_external_refs_validity_order
    CHECK (valid_to IS NULL OR valid_to >= valid_from)
);

COMMENT ON TABLE public.twin_external_refs IS 'Externí identity dvojčat s ratifikací (proposed→confirmed) a temporální platností; import nikdy nepřepisuje potvrzené';
COMMENT ON COLUMN public.twin_external_refs.source IS 'Volný slug zdroje (webdispecink/erp/keycloak/…) — seznam zdrojů jsou instance data, jádro vendor enum nemá';
COMMENT ON COLUMN public.twin_external_refs.source_key IS 'Klíč v externím systému (iddriver, carid, dallas čip, osobní číslo, user id…)';
COMMENT ON COLUMN public.twin_external_refs.ref_kind IS 'Druh vazby: primary_id (identita ve vlastním zdroji) / field_identity (čip v terénu) / hr_ref / account / calendar… — volný slug, slovník je doménová volba';
COMMENT ON COLUMN public.twin_external_refs.proposed_by IS 'Evidence návrhu: ''import'' | ''rule:<slug>'' | ''human:<uuid>''';
COMMENT ON COLUMN public.twin_external_refs.confirmed_by IS 'Kdo ratifikoval (auth.uid()); NULL = systémové potvrzení primární identity vlastního zdroje importem';
COMMENT ON COLUMN public.twin_external_refs.valid_to IS 'Konec platnosti (předání čipu, zrušení účtu) — řádek zůstává jako historie, state se nemění';

ALTER TABLE public.twin_external_refs ENABLE ROW LEVEL SECURITY;

-- ⛔ NA ŽIVOU DATABÁZI SE CHECK Z `CREATE TABLE` NEDOSTANE (tabulka existuje),
-- takže se přidává zvlášť a idempotentně.
--
-- ⚠️ `NOT VALID` JE VĚDOMÉ. Ověřit existující řádky odsud nejde: produkci
-- nevidím (dveře odmítly, HTTP 403), takže bych `ALTER` psal naslepo a
-- migrace by spadla na datech, o kterých nic nevím. `NOT VALID` vymáhá
-- podmínku na VŠECH nových a měněných řádcích, jen nesahá na historii —
-- a tu kryjí indexy. Ověřit ji jde kdykoli později:
--     ALTER TABLE public.twin_external_refs
--       VALIDATE CONSTRAINT twin_external_refs_account_source;
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conname = 'twin_external_refs_account_source'
       AND conrelid = 'public.twin_external_refs'::regclass
  ) THEN
    ALTER TABLE public.twin_external_refs
      ADD CONSTRAINT twin_external_refs_account_source
      CHECK (ref_kind <> 'account' OR source = 'aisha_auth') NOT VALID;
  END IF;
END
$$;

-- ⭐ DRUH ENTITY V KLÍČI VAZBY (2026-09-27). Vazba byla jedinečná jen
-- v (source, source_key, ref_kind). Zdroj, který čísluje dva druhy objektů
-- zvlášť (T-cars vozidloId × osobaId, Eurowag monitoredObjectId × driver id),
-- pak pod holým číslem kolidoval: potvrzené vozidlo 5 „zabralo" klíč osoby 5,
-- návrh pro osobu se tiše přeskočil jako potvrzený, resolve u jízdy vrátil za
-- řidiče vozidlo a twin_upsert_entity_audited by osobě přepsal vozidlo.
--
-- Na živé DB: sloupec přidat a DOPLNIT z dvojčete, na které vazba ukazuje.
-- NOT NULL a hlídání druhu nastaví až triggers/twin_external_refs_entity_type.sql
-- (běží po funkcích): kdyby byl sloupec povinný dřív, než ho trigger umí
-- doplnit, starý kód aplikace by během nasazení vazby zakládat nemohl.
DO $$
BEGIN
  ALTER TABLE public.twin_external_refs ADD COLUMN IF NOT EXISTS entity_type text;
  UPDATE public.twin_external_refs r
     SET entity_type = t.entity_type
    FROM public.twin_entities t
   WHERE t.id = r.twin_id
     AND r.entity_type IS DISTINCT FROM t.entity_type;
END
$$;

-- Komentář až PO přidání sloupce: na živé DB CREATE TABLE IF NOT EXISTS nic
-- nezaloží a komentář nad chybějícím sloupcem by shodil migraci (změřeno
-- upgrade testem nad DB předchozího mainu 2026-09-27).
COMMENT ON COLUMN public.twin_external_refs.entity_type IS 'Druh dvojčete (kopie twin_entities.entity_type, udržuje trigger) — součást jedinečnosti: týž klíč zdroje smí patřit vozidlu i osobě, protože zdroje číslují druhy zvlášť';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/twin_parameter_definitions.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_parameter_definitions
-- Popis: Metadatový katalog vlastností dvojčat (ParameterDefinition ze zadání
--        digital twin §4): nové parametry se přidávají DATY, ne změnou schématu
--        či extranetu. Odděluje surová data (source = slug zdroje) od
--        dopočítaných metrik (source = 'computed') a ručních vstupů.
--        Tvar 1:1 s instance katalogem (riq_parameter_definitions.v1:
--        code/name/entityType/dataType/unit/source/aggregation/description) —
--        JSON v gitu je autor, tato tabulka je runtime, seed je most.
--        Hodnoty parametrů NEŽIJÍ tady: vysokofrekvenční telemetrie zůstává
--        ve zdrojových silech (wd_* current/history) a čte se přes VIEW/RPC
--        s mapováním přes tento katalog; materializují se jen slow-changing
--        observations a události (twin_events). Žádná duplikace dat.
-- RLS: ENABLED
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.twin_parameter_definitions (
  code           text         PRIMARY KEY,
  name           text         NOT NULL,
  entity_type    text         NOT NULL,
  data_type      text         NOT NULL,
  unit           text,
  source         text,
  aggregation    text,
  historization  text,
  description    text,
  metadata       jsonb        NOT NULL DEFAULT '{}'::jsonb,
  created_at     timestamptz  NOT NULL DEFAULT now(),
  updated_at     timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT twin_parameter_definitions_code_not_blank CHECK (btrim(code) <> ''),
  CONSTRAINT twin_parameter_definitions_entity_type_not_blank CHECK (btrim(entity_type) <> '')
);

COMMENT ON TABLE public.twin_parameter_definitions IS 'Katalog vlastností dvojčat — parametry se přidávají daty; hodnoty žijí ve zdrojových silech/twin_events, ne tady';
COMMENT ON COLUMN public.twin_parameter_definitions.code IS 'Stabilní kód parametru (utilization_percent, meter_water_m3…) — klíč pro API i seed';
COMMENT ON COLUMN public.twin_parameter_definitions.source IS 'Původ hodnoty: slug zdroje (webdispecink…) / computed / manual / field_capture — volný slug, instance slovník';
COMMENT ON COLUMN public.twin_parameter_definitions.aggregation IS 'Způsob agregace (last/sum/daily/monotonic_last/event_log…) — volný slug dle instance katalogu';
COMMENT ON COLUMN public.twin_parameter_definitions.historization IS 'Jak se hodnota historizuje: current / timeseries / slowly_changing / event_log — řídí, kde hodnota žije a jak se čte';

ALTER TABLE public.twin_parameter_definitions ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/twin_ref_davky.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- twin_ref_davky — deník HROMADNÉHO schválení návrhů identit (po položkách).
--
-- Majitel 2026-09-28: skupinu návrhů se shodou dvou nezávislých zdrojů pravdy
-- schválit najednou, „bez nutnosti každou klikat zvlášť" — a vše vratné, s původem
-- u dat. Dávka (twin_ref_group_decide) volá pro každou položku tutéž lidskou
-- ratifikaci jako jednotlivé schválení (twin_identity_confirm_binding); tenhle deník
-- nese, CO dávka udělala, aby šla vrátit po položkách v opačném pořadí
-- (twin_ref_davka_vratit) a aby se nevrátilo, co se mezitím změnilo.
--
-- vysledek:        potvrzeno | uz_potvrzeno (klíč už drželo totéž dvojče → návrh
--                  bezpředmětný) | chyba (položka neprošla, dávka jela dál)
-- stav_pred:       stav návrhu před dávkou (vždy proposed; drží se pro vrácení)
-- platnost_pred:   valid_from návrhu před dávkou (ratifikace ho přepíše na „teď")
-- potvrzeno_at:    confirmed_at, které dávka zapsala — vrací se jen nezměněné
-- vraceno:         vraceno | preskoceno_zmenene
--
-- Zápis jen twin_ref_group_decide / twin_ref_davka_vratit (správa, audit); RLS bez
-- politik, žádné granty.
-- =============================================================================
CREATE TABLE IF NOT EXISTS public.twin_ref_davky (
  batch_id      uuid        NOT NULL,
  poradi        integer     NOT NULL,
  ref_id        uuid        NOT NULL REFERENCES public.twin_external_refs (id) ON DELETE CASCADE,
  group_key     text        NOT NULL,
  vysledek      text        NOT NULL CHECK (vysledek IN ('potvrzeno', 'uz_potvrzeno', 'chyba')),
  chyba         text,
  stav_pred     text        NOT NULL,
  platnost_pred timestamptz NOT NULL,
  potvrzeno_at  timestamptz,
  provedl       uuid        NOT NULL,
  provedeno_at  timestamptz NOT NULL DEFAULT now(),
  vraceno       text        CHECK (vraceno IN ('vraceno', 'preskoceno_zmenene')),
  vraceno_at    timestamptz,
  vratil        uuid,
  CONSTRAINT twin_ref_davky_pkey PRIMARY KEY (batch_id, ref_id)
);

COMMENT ON TABLE public.twin_ref_davky IS
  'Deník hromadného schválení návrhů identit po položkách (výsledek, stav před, zapsané confirmed_at) — podklad pro vrácení dávky v opačném pořadí. Zápis jen twin_ref_group_decide / twin_ref_davka_vratit.';

ALTER TABLE public.twin_ref_davky ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.twin_ref_davky FROM PUBLIC, anon, authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/twin_relation_proposal_groups.sql
-- -----------------------------------------------------------------------------

-- Table: twin_relation_proposal_groups — JEDNOTKA ROZHODNUTÍ nad návrhy hran
--
-- Návrh vazby mezi dvojčaty se rozhoduje PO SKUPINÁCH (rozhodnutí majitele
-- 2026-09-28: „po skupinách"). Skupina je to, co člověk umí posoudit jedním
-- pohledem: „těchto 19 podružných měřidel visí pod elektroměrem zásuvek
-- v Mlýně" je JEDNA otázka se stejným důkazem, ne devatenáct. Nejistý návrh
-- (smlouva ↔ jednotka podle plochy) je prostě skupina o jednom členu — tvar
-- zůstává jeden, liší se jen velikost.
--
-- PROČ VLASTNÍ ŘÁDEK A NE JEN group_key NA NÁVRZÍCH: fronta (review_queue)
-- a dispečer rozhodnutí (submit_evidence_review_audited) adresují položku
-- UUID-em. Skupina tedy potřebuje identitu, kterou lze poslat tam a zpátky;
-- odvozovat ji z nejmenšího id členů by znamenalo, že přidání člena změní,
-- o čem člověk rozhoduje.
--
-- group_key je idempotentní klíč NAVRHOVATELE (zdroj + pravidlo + předmět):
-- opakovaný běh téhož navrhovatele trefí tutéž skupinu, nevyrobí druhou.
-- Stav skupiny se NEUKLÁDÁ — odvozuje se ze členů (kolik čeká, kolik
-- rozhodnuto). Uložený stav by se rozešel se členy při prvním dalším návrhu.
--
-- Zápis: POUZE přes definer RPC (twin_relation_propose). Bez INSERT policy.

CREATE TABLE IF NOT EXISTS public.twin_relation_proposal_groups (
  id          uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  group_key   text         NOT NULL,
  source      text         NOT NULL,
  rule_key    text         NOT NULL,
  title       text,
  evidence    jsonb        NOT NULL DEFAULT '{}'::jsonb,
  created_at  timestamptz  NOT NULL DEFAULT now(),
  updated_at  timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT twin_relation_proposal_groups_key_unique UNIQUE (group_key),
  CONSTRAINT twin_relation_proposal_groups_key_not_blank CHECK (btrim(group_key) <> ''),
  CONSTRAINT twin_relation_proposal_groups_source_not_blank CHECK (btrim(source) <> ''),
  CONSTRAINT twin_relation_proposal_groups_rule_not_blank CHECK (btrim(rule_key) <> '')
);

COMMENT ON TABLE public.twin_relation_proposal_groups IS
  'Jednotka rozhodnutí nad návrhy hran (review_queue položka). Stav se odvozuje ze členů, neukládá se.';
COMMENT ON COLUMN public.twin_relation_proposal_groups.group_key IS
  'Idempotentní klíč navrhovatele (zdroj + pravidlo + předmět) — opakovaný běh trefí tutéž skupinu.';
COMMENT ON COLUMN public.twin_relation_proposal_groups.source IS
  'Kdo navrhuje (kanál/zdroj, např. sez-vyuctovani, local-ingest). Skupinu jednoho navrhovatele jiný nepřepíše.';
COMMENT ON COLUMN public.twin_relation_proposal_groups.title IS
  'Čitelný popis předmětu skupiny od navrhovatele (DATA ze zdroje, ne prezentace platformy).';
COMMENT ON COLUMN public.twin_relation_proposal_groups.evidence IS
  'Důkaz společný celé skupině (list, řádky, kontrolní součty zdroje…). Hodnota, ne závěr.';

ALTER TABLE public.twin_relation_proposal_groups ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/twin_relations.sql
-- -----------------------------------------------------------------------------

-- Table: twin_relations — hrany twinsverse S PLATNOSTÍ (osa B: příslušnost)
--
-- Vztah mezi dvojčaty je FAKT S INTERVALEM PLATNOSTI, ne vlastnost entity.
-- Čte se „source —relation_kind→ target" (místo —part_of→ nadřazené místo,
-- osoba —member_of→ skupina, subjekt —responsible_for→ uzel).
--
-- PROČ HRANA A NE SLOUPEC: příslušnost jako hodnota na entitě umí říct jen
-- „teď". Neumí souběh (subjekt patří do N skupin najednou), neumí historii
-- („kam patřil k rozhodnému dni") a přesun znamená PŘEPIS — stará pravda
-- zmizí. Hrana s platností umí všechno trojí: přesun = uzavřít starou hranu
-- + založit novou; historie zůstává zdarma; publikum, auditorium i elektorát
-- se pak odvozují K DATU (derive_audience), ne ze snapshotu.
--
-- PROČ NE graph_edges: to je znalostní graf (Hippocampus RAG) — uzavřený výčet
-- vztahů, confidence, bez platnosti. Tohle je substrát reality; jiná otázka,
-- jiná tabulka.
--
-- relation_kind je VOLNÝ SLUG jako twin_entities.entity_type: druhy vztahů
-- definují instance data, ne jádro. Platforma vynucuje jen tvar (neprázdný).
--
-- EXCLUDE brání PŘEKRYVU téže hrany (source, target, kind) v čase — dvě
-- současně platné kopie téhož vztahu jsou duplicitní pravda, ne souběh.
-- Souběh je legitimní přes RŮZNÉ cíle nebo RŮZNÉ druhy. Vyžaduje btree_gist
-- (v baseline je).
--
-- Zápis: POUZE přes definer RPC (twin_relation_open_admin/_close_admin, ingest
-- driver) — přímý zápis nemá INSERT policy záměrně; hrana bez auditní stopy
-- by byla nárok bez důkazu.

CREATE TABLE IF NOT EXISTS public.twin_relations (
  id              uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  source_twin_id  uuid         NOT NULL REFERENCES public.twin_entities(id) ON DELETE CASCADE,
  target_twin_id  uuid         NOT NULL REFERENCES public.twin_entities(id) ON DELETE CASCADE,
  relation_kind   text         NOT NULL,
  valid_from      timestamptz  NOT NULL DEFAULT now(),
  valid_to        timestamptz,
  metadata        jsonb        NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz  NOT NULL DEFAULT now(),
  updated_at      timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT twin_relations_kind_not_blank CHECK (btrim(relation_kind) <> ''),
  CONSTRAINT twin_relations_no_self_loop   CHECK (source_twin_id <> target_twin_id),
  CONSTRAINT twin_relations_interval_sane  CHECK (valid_to IS NULL OR valid_to > valid_from),
  -- táž hrana nesmí platit dvakrát současně; '[)' aby na sebe intervaly
  -- navazovaly beze spáry i bez překryvu (uzavřít v T a založit od T je legální)
  CONSTRAINT twin_relations_no_overlap EXCLUDE USING gist (
    source_twin_id WITH =,
    target_twin_id WITH =,
    relation_kind  WITH =,
    tstzrange(valid_from, valid_to, '[)') WITH &&
  )
);

COMMENT ON TABLE public.twin_relations IS
  'Hrany twinsverse s intervalem platnosti (osa B: příslušnost). Přesun = uzavřít + založit; historie zůstává. Čte se source —kind→ target.';
COMMENT ON COLUMN public.twin_relations.relation_kind IS
  'Volný slug druhu vztahu (part_of/member_of/responsible_for…) — druhy definují instance data, ne jádro; stejný princip jako twin_entities.entity_type.';
COMMENT ON COLUMN public.twin_relations.valid_to IS
  'NULL = hrana platí. Uzavření hrany NENÍ smazání — „kam patřil k rozhodnému dni" musí zůstat zodpověditelné.';
COMMENT ON COLUMN public.twin_relations.metadata IS
  'Důkazní stopa a doplňky (odkud hrana pochází — návrh, potvrzení, zdroj). Autoritativní hodnoty parametrů patří do observations, ne sem.';

-- Indexy mají VLASTNÍ soubory (sql/indexes/idx_twin_relations_*) — dva částečné
-- nad oběma konci hrany a jeden rozsahový GiST pro dotazy k datu. Oddělení
-- vynucuje brána sql-source-separation a je to správně: index je samostatné
-- rozhodnutí s vlastním zdůvodněním, ne detail tabulky.

ALTER TABLE public.twin_relations ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/twin_relation_proposals.sql
-- -----------------------------------------------------------------------------

-- Table: twin_relation_proposals — NÁVRH hrany twinsverse čekající na člověka
--
-- DOKTRÍNA (majitel 2026-09-28): vazby mezi zdroji NAVRHUJE systém sám
-- a SCHVALUJE člověk. Návrh je DŮKAZ, ne fakt: z tohohle řádku nikdy nevzniká
-- hrana sama od sebe. Hranu v twin_relations otevře až rozhodnutí
-- (twin_relation_proposal_decide) — a to týmž zápisovým místem jako ruční
-- vazba (twin_relation_open_admin), takže platí jedno pravidlo překryvu
-- a jedna auditní stopa.
--
-- PROČ NE li_relation_suggestions: ta nese souběh PARAMETRŮ uvnitř dokladu
-- („protistrana souvisí s plochou"), tedy tvrzení o slovníku, ne hranu mezi
-- dvěma konkrétními dvojčaty. Naměřeno 2026-09-28: 1 735 řádků, žádný čtenář,
-- žádný stav rozhodnutí. Míchat do ní hrany by spojilo dvě otázky pod jednu
-- tabulku a obě by se četly špatně.
--
-- PROČ NE stav přímo na twin_relations: každý čtenář hran (twin_graph_
-- descendants, publikum, bloky) by musel začít filtrovat „jen potvrzené"
-- a první, kdo zapomene, prohlásí návrh za fakt. Fakt a návrh bydlí zvlášť.
--
-- ROZHODNUTÍ JE LEPKAVÉ: opakovaný návrh téhož proposal_key NEOŽIVÍ zamítnutý
-- ani nepřepíše schválený — lidské „ne" se nevrací (týž princip jako
-- twin_propose_identity_by_signals). Aktualizuje se jen ČEKAJÍCÍ návrh.
--
-- relation_kind je volný slug jako v twin_relations (druhy definují instance
-- data); tvar hlídá CHECK stejný jako li_relation_suggestions.

CREATE TABLE IF NOT EXISTS public.twin_relation_proposals (
  id              uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  group_id        uuid         NOT NULL REFERENCES public.twin_relation_proposal_groups(id) ON DELETE CASCADE,
  proposal_key    text         NOT NULL,
  source_twin_id  uuid         NOT NULL REFERENCES public.twin_entities(id) ON DELETE CASCADE,
  target_twin_id  uuid         NOT NULL REFERENCES public.twin_entities(id) ON DELETE CASCADE,
  relation_kind   text         NOT NULL,
  valid_from      timestamptz,
  confidence      numeric,
  evidence        jsonb        NOT NULL DEFAULT '{}'::jsonb,
  state           text         NOT NULL DEFAULT 'proposed',
  relation_id     uuid         REFERENCES public.twin_relations(id) ON DELETE SET NULL,
  decided_by      uuid,
  decided_at      timestamptz,
  decision_note   text,
  created_at      timestamptz  NOT NULL DEFAULT now(),
  updated_at      timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT twin_relation_proposals_key_unique UNIQUE (proposal_key),
  CONSTRAINT twin_relation_proposals_key_not_blank CHECK (btrim(proposal_key) <> ''),
  CONSTRAINT twin_relation_proposals_kind_shape CHECK (relation_kind ~ '^[a-z][a-z0-9_]{2,63}$'),
  CONSTRAINT twin_relation_proposals_no_self_loop CHECK (source_twin_id <> target_twin_id),
  CONSTRAINT twin_relation_proposals_confidence_range
    CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1)),
  -- 'superseded' = v okamžiku návrhu už totéž PLATILO jako fakt (hrana existuje);
  -- návrh se neztrácí, ale do fronty nepatří — nic k rozhodnutí.
  CONSTRAINT twin_relation_proposals_state_vocab
    CHECK (state IN ('proposed', 'approved', 'rejected', 'superseded')),
  CONSTRAINT twin_relation_proposals_decision_complete
    CHECK (state <> 'approved' OR relation_id IS NOT NULL)
);

COMMENT ON TABLE public.twin_relation_proposals IS
  'Návrh hrany mezi dvojčaty s důkazem — advisory, dokud ho člověk nerozhodne. Hranu otevře jen twin_relation_proposal_decide.';
COMMENT ON COLUMN public.twin_relation_proposals.proposal_key IS
  'Idempotentní klíč navrhovatele; opakovaný návrh aktualizuje jen ČEKAJÍCÍ řádek, rozhodnutí je lepkavé.';
COMMENT ON COLUMN public.twin_relation_proposals.valid_from IS
  'Od kdy zdroj vazbu tvrdí (např. začátek období sešitu). NULL = od okamžiku schválení.';
COMMENT ON COLUMN public.twin_relation_proposals.evidence IS
  'Co se s čím shodlo a kde (doklad, list, řádek, druh shody). Hodnota ze zdroje, ne závěr.';
COMMENT ON COLUMN public.twin_relation_proposals.relation_id IS
  'Hrana, kterou schválení otevřelo (nebo která už platila). NULL u čekajících a zamítnutých.';

ALTER TABLE public.twin_relation_proposals ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/twin_scope_doc_rules.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- twin_scope_doc_rules — jak VAZBA osoby na identitu zakládá nárok na DOKLAD.
--
-- ⭐ PROČ (rozhodnutí majitele 2026-09-28). Oprávnění neplyne z role, ale z toho,
-- s čím je uživatel spojen: účet → osoba (potvrzená vazba účtu) → platná vazba
-- osoby na identitu (twin_relations) → doklady té identity. Běžný uživatel tak
-- v sekci vidí jen data, na která má nárok; přístup do sekce je zvlášť.
--
-- Řádek říká: „vazba druhu `relation_kind` pouští doklady typu `doc_type`,
-- jejichž pole `field_key` se rovná POTVRZENÉMU identifikátoru identity některého
-- z druhů `ref_kinds`". Příklad (data instance, ne jádro):
--   spravuje · invoice  · owner_company · {company_name}
--   spravuje · contract · supplier_id   · {company_ico}
-- Porovnává se s identifikátory (twin_external_refs, state=confirmed, platné),
-- ne s názvem dvojčete: o tom, čím se identita pozná, rozhoduje člověk (HR),
-- ne shoda textu. Druhy vazeb i klíče polí jsou slovník instance.
--
-- ⛔ Prázdná tabulka = nikdo nic nepustí (fail-closed), ne „všichni všechno".
-- ⛔ Přístup jen přes funkce (li_doc_slugs_v_rozsahu, twin_ids_v_rozsahu) a data
-- instance; RLS bez politik, žádné granty pro anon/authenticated.
-- =============================================================================
CREATE TABLE IF NOT EXISTS public.twin_scope_doc_rules (
  id             uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  relation_kind  text        NOT NULL CHECK (btrim(relation_kind) <> ''),
  doc_type       text        NOT NULL CHECK (btrim(doc_type) <> ''),
  field_key      text        NOT NULL CHECK (field_key ~ '^[a-z][a-z0-9_]*$'),
  ref_kinds      text[]      NOT NULL CHECK (cardinality(ref_kinds) > 0),
  is_active      boolean     NOT NULL DEFAULT true,
  note           text,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT twin_scope_doc_rules_unique UNIQUE (relation_kind, doc_type, field_key)
);

COMMENT ON TABLE public.twin_scope_doc_rules IS
  'Nárok z vazeb: druh vazby osoby na identitu × typ dokladu × pole dokladu × druhy potvrzených identifikátorů identity. Slovník instance; prázdno = nikdo nic.';

ALTER TABLE public.twin_scope_doc_rules ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.twin_scope_doc_rules FROM PUBLIC, anon, authenticated;


