COMMENT ON COLUMN public.wd_drivers.erp_employee_ref IS 'Ruční mapování na ERP zaměstnance — import nepřepisuje';

ALTER TABLE public.wd_drivers ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/wd_import_log.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_import_log
-- Popis: Log importních běhů z Webdispečinku (zadání 8: veškeré importy
--        logované a opakovatelné). Řádek vzniká na startu běhu a uzavírá se
--        po dokončení/chybě přes wd_record_import_audited.
-- RLS: ENABLED
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.wd_import_log (
  id                uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  import_type       text         NOT NULL,
  status            text         NOT NULL DEFAULT 'running',
  started_at        timestamptz  NOT NULL DEFAULT now(),
  finished_at       timestamptz,
  records_total     integer,
  records_upserted  integer,
  records_failed    integer,
  error_message     text,
  details           jsonb,
  created_at        timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT wd_import_log_status_check
    CHECK (status IN ('running', 'success', 'error')),
  CONSTRAINT wd_import_log_import_type_check
    CHECK (import_type IN ('vehicles', 'drivers', 'positions', 'rides', 'worklogs', 'tachograph'))
);

COMMENT ON TABLE public.wd_import_log IS 'Průběh a výsledky importních běhů svc-webdispecink';
COMMENT ON COLUMN public.wd_import_log.import_type IS 'Typ importu — fáze 1 používá vehicles/drivers, další typy rezervované pro fáze 2+';

ALTER TABLE public.wd_import_log ENABLE ROW LEVEL SECURITY;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/wd_overspeed.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_overspeed
-- Popis: Překročení rychlosti z Webdispečinku (_getCarOverSpeed). Jeden řádek =
--        jeden úsek s maximem rychlosti (MSpeed), časem, polohou a řidičem.
--        Upsert podle (wd_car_id, time_from) — opakovaný import okna aktualizuje.
--        Spravováno: svc-webdispecink přes wd_upsert_overspeed_audited.
-- RLS: ENABLED
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.wd_overspeed (
  id             uuid          PRIMARY KEY DEFAULT gen_random_uuid(),
  wd_car_id      integer       NOT NULL,
  wd_driver_id   integer,
  max_speed_kmh  numeric(6,2),
  time_from      timestamptz   NOT NULL,
  time_to        timestamptz,
  lat            numeric(9,6),
  lon            numeric(9,6),
  distance_km    numeric(10,3),
  raw_data       jsonb,
  last_import_at timestamptz,
  created_at     timestamptz   NOT NULL DEFAULT now(),
  updated_at     timestamptz   NOT NULL DEFAULT now(),
  CONSTRAINT wd_overspeed_key UNIQUE (wd_car_id, time_from)
);

COMMENT ON TABLE public.wd_overspeed IS 'Překročení rychlosti z Webdispečinku (_getCarOverSpeed); úsek = max. rychlost + poloha + řidič, upsert přes wd_upsert_overspeed_audited';
COMMENT ON COLUMN public.wd_overspeed.max_speed_kmh IS 'MSpeed — maximální rychlost v úseku (km/h)';


ALTER TABLE public.wd_overspeed ENABLE ROW LEVEL SECURITY;


