-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/web_tracking_registry.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- web_tracking_registry — declarative catalog of web analytics/tracking
-- integrations.
--
-- The materialization target for plugin_catalog kind='web_tracking' (declared
-- since the plugin control plane, previously loaderless — see expert_rule
-- declared-extension-must-reach-the-resolver, measured 2026-07-26).
--
-- A row DECLARES a tracker; the consumer is the web surface: it reads
-- get_active_web_tracking() at boot and injects only entries whose
-- consent_category the visitor has granted — tracking is therefore
-- consent-gated by construction, and a tracker with no granted consent is
-- simply never loaded. No secrets here; site keys that are genuinely secret
-- belong in env and are resolved server-side.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.web_tracking_registry (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),

  slug text NOT NULL UNIQUE,
  display_name text NOT NULL,

  -- Which loader template the web surface uses.
  provider text NOT NULL CHECK (provider IN ('matomo', 'plausible', 'umami', 'custom')),

  -- Where the tracker script lives and what site it reports as. For
  -- provider='custom', config carries the full snippet contract instead.
  script_url text,
  site_id text,

  -- Consent gate: the web surface loads this tracker ONLY when the visitor has
  -- granted this consent category (ties into the existing consent flow —
  -- get_my_pending_consents et al.). 'essential' is reserved for strictly
  -- functional measurement and still renders a disclosure.
  consent_category text NOT NULL DEFAULT 'analytics'
    CHECK (consent_category IN ('essential', 'analytics', 'marketing')),

  config jsonb NOT NULL DEFAULT '{}'::jsonb,

  is_enabled boolean NOT NULL DEFAULT false,

  -- §19.4 per-instance scoping (same contract as ai_provider_registry).
  scoped_to_instance_id uuid,

  -- Provenance + ownership guard (see materialize_web_tracking).
  source_plugin_id uuid REFERENCES public.plugin_catalog(id) ON DELETE SET NULL,

  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.web_tracking_registry ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.web_tracking_registry IS
  'Declarative web-tracking catalog. Materialization target for plugin kind=web_tracking; consumed by the web surface via get_active_web_tracking(), consent-gated per visitor.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/workbench_execution_requests.sql
-- -----------------------------------------------------------------------------

-- Table: workbench_execution_requests
-- PR-J workbench execution rail: svc-ai-chat ENQUEUES work (pending), the aisha-dirigent
-- VSCode extension CLAIMS it (claimed), runs it on a LOCAL model, and posts the result
-- back (completed/failed). A capability-availability WORK SURFACE — not a model catalog
-- (that is ai_model_registry). The central adapter blocks-polls for the result; there is
-- no push to the dev's machine, so the rail works behind NAT/firewall.
--
-- RLS: service_role full access (the adapter enqueues/polls) + admin/staff read; the
-- extension claim/complete go through SECURITY DEFINER RPCs, not direct DML.
-- Triggers -> triggers/, policies -> policies/ (table SoT must not inline either, so the
-- cold-start table-before-function ordering holds). run_id is a plain uuid (no FK) so an
-- orphaned/absent run never blocks an enqueue.
CREATE TABLE IF NOT EXISTS public.workbench_execution_requests (
  id              uuid NOT NULL DEFAULT gen_random_uuid(),
  -- work payload (mirrors RuntimeWork; the full clow is stored for trace/replay)
  clow            jsonb NOT NULL DEFAULT '{}'::jsonb,
  request_input   text NOT NULL,
  model_id        text,
  provider_slug   text,
  run_id          uuid REFERENCES public.ai_runs ON DELETE SET NULL,
  story_id        uuid REFERENCES public.partner_stories ON DELETE SET NULL,
  decision_id     uuid REFERENCES public.ai_decisions ON DELETE SET NULL,
  -- lifecycle
  status          text NOT NULL DEFAULT 'pending',
  claimed_by      text,
  response        text,
  error_detail    jsonb,
  tokens_in       integer,
  tokens_out      integer,
  latency_ms      integer,
  -- how many times this request has been (re)claimed; claim_pending_workbench_requests
  -- dead-letters it to 'failed' once it exceeds the max, instead of re-running a
  -- request whose claimant keeps dying before completing it. See that function.
  claim_attempts  integer NOT NULL DEFAULT 0,
  -- timestamps
  enqueued_at     timestamptz NOT NULL DEFAULT now(),
  claimed_at      timestamptz,
  completed_at    timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (id),
  CONSTRAINT workbench_execution_requests_status_check
    CHECK (status IN ('pending', 'claimed', 'completed', 'failed'))
);

ALTER TABLE public.workbench_execution_requests ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.workbench_execution_requests IS
  'PR-J workbench poll+block work queue. svc enqueues (pending) -> extension claims (claimed) -> runs local model -> completes (completed/failed). RLS: service_role writes, admin/staff read.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/workflow_statuses.sql
-- -----------------------------------------------------------------------------

-- Table: workflow_statuses
-- Lookup table for kanban lifecycle statuses on partner_stories.status.
-- Drives kanban swimlanes, i18n labels, sort order, and DB-level validation
-- in update_story_status_audited.
--
-- This is the source-of-truth that replaces the hardcoded list previously
-- duplicated in three places:
--   - update_story_status_audited.sql IN-clause validator
--   - get_storyloop_admin_overview.sql COUNT FILTER predicates
--   - frontend storyloop.<status> i18n key references
--
-- See also: delivery_transition_rules + delivery_transitions (the parallel
-- lookup system that governs partner_stories.delivery_status — a separate
-- pipeline status orthogonal to kanban lifecycle).

CREATE TABLE IF NOT EXISTS public.workflow_statuses (
  -- Stable identifier referenced by partner_stories.status FK.
  status text PRIMARY KEY,

  -- i18n key path that resolves to the display label, e.g.
  -- 'storyloop.statuses.inbox'. UI must call t(label_i18n_key) — never
  -- render the raw `status` column.
  label_i18n_key text NOT NULL,

  -- Kanban column ordering (ASC). Lower = leftmost.
  sort_order int NOT NULL DEFAULT 0,

  -- Optional UI hint (Tailwind class name or hex color) used by kanban
  -- swimlane headers. NULL means "use default theme".
  swimlane_color text,

  -- Terminal statuses are end-of-pipeline (e.g. 'archived', 'trash').
  -- Kanban renders them collapsed by default.
  is_terminal boolean NOT NULL DEFAULT false,

  -- Soft-disable a status without dropping the row (FK references stay
  -- valid). UI hides inactive statuses for new transitions.
  is_active boolean NOT NULL DEFAULT true,

  -- Operator notes — surfaces in admin status manager.
  notes text,

  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.workflow_statuses ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.workflow_statuses IS
  'Source-of-truth for partner_stories.status kanban lifecycle. Drives swimlane labels, sort order, and update_story_status_audited validation. Parallel to delivery_transition_rules (delivery_status side).';

-- Indexes live in aisha/db/sql/indexes/idx_workflow_statuses_active_order.sql
-- per SQL Source Separation rule.


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/tables/workflow_status_transitions.sql
-- -----------------------------------------------------------------------------

-- Table: workflow_status_transitions
-- Per-(from_status, to_status) lookup of legal kanban lifecycle transitions
-- on partner_stories.status. Parallel to delivery_transition_rules — same
-- shape, different domain.
--
-- A row exists IFF the transition is legal. Absence of a row = illegal
-- transition (update_story_status_audited rejects with ERRCODE 22023).
--
-- Optional `requires_role` enforces admin/staff gating server-side.
-- NULL = any authenticated owner of the story may perform the transition.
--
-- Initial seed (see migrations) mirrors today's permissive behavior so
-- the FK + validator rollout is non-breaking. Operators can tighten via
-- a later admin tool without schema changes.

CREATE SEQUENCE IF NOT EXISTS public.workflow_status_transitions_id_seq;

CREATE TABLE IF NOT EXISTS public.workflow_status_transitions (
  id integer PRIMARY KEY DEFAULT nextval('public.workflow_status_transitions_id_seq'::regclass),

  -- Source state. Both columns FK to workflow_statuses(status) so a
  -- status can't be soft-deleted without also disabling its transitions.
  from_status text NOT NULL REFERENCES public.workflow_statuses(status),
  to_status   text NOT NULL REFERENCES public.workflow_statuses(status),

  -- Role gating. NULL = any owner; 'admin' = is_admin_or_staff() required.
  -- Matches delivery_transition_rules semantics.
  requires_role text,

  -- Soft-disable a rule without dropping it.
  is_active boolean NOT NULL DEFAULT true,

  -- Operator notes — surfaces in admin transition manager.
  notes text,

  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),

  -- One canonical row per (from, to) pair.
  UNIQUE (from_status, to_status),

  -- Prevent self-loops at the schema level (no UI value, easy to seed wrong).
  CHECK (from_status <> to_status)
);

ALTER SEQUENCE public.workflow_status_transitions_id_seq
  OWNED BY public.workflow_status_transitions.id;

ALTER TABLE public.workflow_status_transitions ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.workflow_status_transitions IS
  'Legal (from_status, to_status) pairs for partner_stories.status. Parallel to delivery_transition_rules but for the kanban lifecycle. Enforced by update_story_status_audited.';

-- Indexes live in aisha/db/sql/indexes/idx_workflow_status_transitions_lookup.sql
-- per SQL Source Separation rule.


