-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/audience_actor_overlay_v.sql
-- -----------------------------------------------------------------------------

-- View: public.audience_actor_overlay_v
-- Per-actor marketer overlay (notes, follow-ups, tags, assigned partner) composed from reused signals.

CREATE OR REPLACE VIEW public.audience_actor_overlay_v AS
 SELECT user_id AS actor_user_id,
    display_name,
    email,
    ( SELECT array_agg(jsonb_build_object('id', se.id, 'content', se.content, 'created_at', se.created_at, 'created_by', se.created_by) ORDER BY se.created_at DESC) AS array_agg
           FROM story_entries se
             JOIN partner_stories ps ON ps.id = se.story_id
          WHERE ps.user_id = p.user_id AND se.entry_type = 'actor_note'::text) AS notes,
    ( SELECT array_agg(jsonb_build_object('id', b.id, 'due_at', b.due_at, 'note', b.note, 'status', b.status, 'source_type', b.source_type) ORDER BY b.due_at) AS array_agg
           FROM story_pulse_beats b
          WHERE b.status = 'open'
            AND ((b.subject_type = 'actor' AND b.subject_id = p.user_id)
              OR (b.subject_type = 'twin' AND b.subject_id IN (
                    SELECT r.twin_id FROM twin_external_refs r
                     WHERE r.ref_kind = 'account' AND r.source_key = p.user_id::text
                       AND r.state = 'confirmed' AND r.valid_to IS NULL)))) AS pending_followups,
    ( SELECT array_agg(DISTINCT sl.label) AS array_agg
           FROM story_labels sl
          WHERE sl.resource_type = 'actor'::text AND sl.resource_id = p.user_id) AS tags,
    ( SELECT sc.partner_id
           FROM study_consultants sc
          WHERE sc.scope_type = 'actor'::text AND sc.study_id = p.user_id AND sc.role = 'account_manager'::consultant_role_enum AND sc.status = 'approved'::consultant_status_enum
         LIMIT 1) AS assigned_to_partner_id
   FROM profiles p;

COMMENT ON VIEW public.audience_actor_overlay_v IS
  'Composite "overlay" view emulating a per-actor marketer context record.
   Joins story_entries (notes), story_pulse_beats (open beats = follow-ups, ADR-003 K2), story_labels (tags),
   study_consultants (assigned_to). One row per actor. No new table needed.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/audience_actor_tier_v.sql
-- -----------------------------------------------------------------------------

-- View: public.audience_actor_tier_v
-- Computed member tier per user — DERIVED, never stored.

CREATE OR REPLACE VIEW public.audience_actor_tier_v AS
 SELECT p.user_id,
    p.display_name,
    p.email,
        CASE
            WHEN pp.is_visible AND pp.is_production_provider THEN 'partner'::text
            WHEN pp.is_certified THEN 'qualified'::text
            WHEN COALESCE(ea.app_accesses_30d, 0) > 0 THEN 'active'::text
            ELSE 'registered'::text
        END AS member_tier,
    m.tier AS membership_tier,
    m.status AS membership_status,
    pp.certification_level,
    pp.certification_passed_at,
    pp.business_name,
    pp.services AS specializations,
    ea.audience_size,
    ea.last_active_at
   FROM profiles p
     LEFT JOIN partner_profiles pp ON pp.user_id = p.user_id
     LEFT JOIN memberships m ON m.user_id = p.user_id
     LEFT JOIN audience_actor_aggregate_latest_v ea ON ea.user_id = p.user_id;

COMMENT ON VIEW public.audience_actor_tier_v IS
  'Computed member tier per user (anonymous|registered|active|qualified|partner).
   Tier is DERIVED, never stored — single source of truth via this view.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/audience_actor_timeline_v.sql
-- -----------------------------------------------------------------------------

-- View: public.audience_actor_timeline_v
-- Unified chronological timeline per actor (story entries + audit + communications).

CREATE OR REPLACE VIEW public.audience_actor_timeline_v AS
 SELECT ps.user_id AS actor_user_id,
    se.id AS event_id,
    'story_entry'::text AS event_source,
    se.entry_type AS event_type,
    se.content,
    se.metadata,
    se.created_by,
    COALESCE(se.occurred_at, se.created_at) AS occurred_at
   FROM story_entries se
     JOIN partner_stories ps ON ps.id = se.story_id
UNION ALL
 SELECT aj.user_id AS actor_user_id,
    aj.id AS event_id,
    'audit'::text AS event_source,
    aj.action AS event_type,
    aj.summary AS content,
    aj.details AS metadata,
    aj.user_id AS created_by,
    aj.created_at AS occurred_at
   FROM audit_journal aj
  WHERE aj.area = ANY (ARRAY['outreach'::text, 'crm_ops'::text, 'crm'::text])
UNION ALL
 SELECT o.user_id AS actor_user_id,
    o.id AS event_id,
    'communication'::text AS event_source,
    o.channel AS event_type,
    COALESCE(o.payload ->> 'title_key'::text, o.payload ->> 'description'::text, o.template) AS content,
    jsonb_build_object('campaign_id', o.campaign_id, 'status', o.status, 'opened_at', o.opened_at, 'clicked_at', o.clicked_at, 'recipient', o.recipient, 'template', o.template) AS metadata,
    o.created_by,
    o.created_at AS occurred_at
   FROM openclaw_notifications o
  WHERE o.user_id IS NOT NULL;

COMMENT ON VIEW public.audience_actor_timeline_v IS
  'Unified chronological timeline per actor. UNION of story_entries (manual
   notes), openclaw_notifications (outbound communications), and audit_journal
   (system events with CRM relevance). Single source for "Communication
   timeline" UI panel. RLS filtering happens at underlying table level.';


