-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/audience_admin_actor_detail_v.sql
-- -----------------------------------------------------------------------------

-- View: public.audience_admin_actor_detail_v
-- Composite actor detail (profile + tier + overlay + engagement + roles + cohorts).

CREATE OR REPLACE VIEW public.audience_admin_actor_detail_v AS
 SELECT p.user_id,
    p.display_name,
    p.email,
    p.phone,
    p.date_of_birth,
    p.preferred_language,
    p.created_at AS profile_created_at,
    tier.member_tier,
    tier.business_name,
    tier.specializations,
    tier.certification_level,
    tier.certification_passed_at,
    ovl.notes,
    ovl.pending_followups,
    ovl.tags,
    ovl.assigned_to_partner_id,
    agg.audience_size,
    agg.audience_growth_30d,
    agg.unique_attendees_30d,
    agg.total_attendance_30d,
    agg.events_created_30d,
    agg.events_created_90d,
    agg.app_accesses_30d,
    agg.app_accesses_90d,
    agg.last_active_at,
    agg.email_open_rate_90d,
    agg.email_click_rate_90d,
    ( SELECT jsonb_agg(jsonb_build_object('role', sc.role, 'scope_type', sc.scope_type, 'scope_id', sc.study_id, 'status', sc.status, 'approved_at', sc.approved_at)) AS jsonb_agg
           FROM study_consultants sc
          WHERE sc.partner_id = p.user_id AND sc.status = 'approved'::consultant_status_enum) AS active_roles,
    ( SELECT jsonb_agg(jsonb_build_object('cohort_id', sr.study_id, 'cohort_name', s.name, 'cohort_type', s.study_type, 'status', sr.status, 'enrolled_at', sr.enrolled_at)) AS jsonb_agg
           FROM study_registrations sr
             JOIN studies s ON s.id = sr.study_id
          WHERE sr.user_id = p.user_id AND (sr.status = ANY (ARRAY['active'::text, 'enrolled'::text]))) AS active_cohorts
   FROM profiles p
     LEFT JOIN audience_actor_tier_v tier ON tier.user_id = p.user_id
     LEFT JOIN audience_actor_overlay_v ovl ON ovl.actor_user_id = p.user_id
     LEFT JOIN audience_actor_aggregate_latest_v agg ON agg.user_id = p.user_id;

COMMENT ON VIEW public.audience_admin_actor_detail_v IS
  'Composite detail view: profile + tier + overlay + engagement + roles +
   cohorts. One row per actor. Drives Appsmith "Actor Detail" page.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/audience_admin_campaign_performance_v.sql
-- -----------------------------------------------------------------------------

-- View: public.audience_admin_campaign_performance_v
-- Per-campaign performance dashboard (channels, latest run, per-channel breakdown).

CREATE OR REPLACE VIEW public.audience_admin_campaign_performance_v AS
 SELECT id AS campaign_id,
    name AS campaign_name,
    description,
    is_active,
    channels,
    audience_type,
    audience_filter,
    created_at,
    ( SELECT row_to_json(runs.*) AS row_to_json
           FROM ( SELECT notification_campaign_runs.run_at,
                    notification_campaign_runs.status,
                    notification_campaign_runs.recipients_count,
                    notification_campaign_runs.push_sent,
                    notification_campaign_runs.inapp_sent
                   FROM notification_campaign_runs
                  WHERE notification_campaign_runs.campaign_id = nc.id
                  ORDER BY notification_campaign_runs.run_at DESC
                 LIMIT 1) runs) AS latest_run,
    ( SELECT jsonb_object_agg(per_channel.channel, per_channel.stats) AS jsonb_object_agg
           FROM ( SELECT openclaw_notifications.channel,
                    jsonb_build_object('queued', count(*) FILTER (WHERE openclaw_notifications.status = 'queued'::text), 'sent', count(*) FILTER (WHERE openclaw_notifications.status = ANY (ARRAY['sent'::text, 'sending'::text])), 'opened', count(openclaw_notifications.opened_at), 'clicked', count(openclaw_notifications.clicked_at), 'bounced', count(openclaw_notifications.bounced_at), 'unsubscribed', count(openclaw_notifications.unsubscribed_at)) AS stats
                   FROM openclaw_notifications
                  WHERE openclaw_notifications.campaign_id = nc.id
                  GROUP BY openclaw_notifications.channel) per_channel) AS per_channel_stats,
    ( SELECT count(DISTINCT openclaw_notifications.user_id) AS count
           FROM openclaw_notifications
          WHERE openclaw_notifications.campaign_id = nc.id) AS total_recipients,
    ( SELECT count(*)::numeric / NULLIF(count(*), 0)::numeric
           FROM openclaw_notifications
          WHERE openclaw_notifications.campaign_id = nc.id AND openclaw_notifications.opened_at IS NOT NULL) AS open_rate
   FROM notification_campaigns nc;

COMMENT ON VIEW public.audience_admin_campaign_performance_v IS
  'Per-campaign performance dashboard. Channels[], latest run, per-channel
   delivery + engagement breakdown. Drives Appsmith "Campaign Performance".';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/audience_admin_cohort_overview_v.sql
-- -----------------------------------------------------------------------------

-- View: public.audience_admin_cohort_overview_v
-- Cohorts listing with registrations + engagement metrics (studies-backed).

CREATE OR REPLACE VIEW public.audience_admin_cohort_overview_v AS
 SELECT id AS cohort_id,
    name AS cohort_name,
    title,
    study_type AS cohort_type,
    status,
    is_active,
    starts_at,
    ends_at,
    target_registration,
    current_registration,
    ( SELECT avg(ea.audience_size)::integer AS avg
           FROM study_registrations sr
             JOIN audience_actor_aggregate_latest_v ea ON ea.user_id = sr.user_id
          WHERE sr.study_id = s.id AND sr.status = 'active'::text) AS avg_audience_size,
    ( SELECT count(*) AS count
           FROM study_registrations
          WHERE study_registrations.study_id = s.id AND study_registrations.status = 'active'::text) AS active_registrations,
    ( SELECT count(*) AS count
           FROM study_registrations
          WHERE study_registrations.study_id = s.id AND study_registrations.status = 'completed'::text) AS completed_registrations,
    ( SELECT count(DISTINCT ncr.user_id) AS count
           FROM openclaw_notifications ncr
          WHERE (ncr.campaign_id IN ( SELECT notification_campaigns.id
                   FROM notification_campaigns
                  WHERE (notification_campaigns.audience_filter ->> 'cohort_id'::text) = s.id::text)) AND ncr.created_at > (now() - '30 days'::interval)) AS unique_reached_30d,
    created_at,
    updated_at
   FROM studies s
  WHERE is_active = true;

COMMENT ON VIEW public.audience_admin_cohort_overview_v IS
  'Cohorts listing with registrations + engagement metrics. Studies-backed,
   filters out archived. Drives Appsmith "Cohort Manager" template.';


