-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/audience_admin_signal_feed_v.sql
-- -----------------------------------------------------------------------------

-- View: public.audience_admin_signal_feed_v
-- Recent signals across all sources with resolved actor + rule-applied tags.

CREATE OR REPLACE VIEW public.audience_admin_signal_feed_v AS
 SELECT id AS event_id,
    event_source,
    event_type,
    status,
    story_id,
    metadata,
    routed_to,
    created_at,
    COALESCE((metadata ->> 'user_id'::text)::uuid, (metadata ->> 'actor_user_id'::text)::uuid, (metadata ->> 'profile_id'::text)::uuid) AS actor_user_id,
    ( SELECT array_agg(DISTINCT unnest_tags.unnest_tags) AS array_agg
           FROM signal_tag_rules,
            LATERAL unnest(signal_tag_rules.tags) unnest_tags(unnest_tags)
          WHERE signal_tag_rules.is_active AND ie.event_type ~ signal_tag_rules.event_type_pattern AND (signal_tag_rules.source_pattern IS NULL OR ie.event_source ~ signal_tag_rules.source_pattern)) AS would_apply_tags
   FROM integration_events ie
  ORDER BY created_at DESC;

COMMENT ON VIEW public.audience_admin_signal_feed_v IS
  'Recent signals across all data sources with resolved actor + tags that
   would be applied by rules. Used for debugging + audit + understanding
   signal flow. Drives Appsmith "Signal Feed" page.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/audience_admin_source_event_stats_v.sql
-- -----------------------------------------------------------------------------

-- View: public.audience_admin_source_event_stats_v
-- Události vzniklé v měsíci — tvar CSV exportu (Event ID; title; created by;
-- date from/to; official; cancelled; online; follows; tags) + `month`.
-- Booleany jako text a sloupce jen na konec — viz topic_stats_v.
CREATE OR REPLACE VIEW public.audience_admin_source_event_stats_v AS
SELECT
  s.month,
  s.external_id                                   AS event_id,
  s.title,
  s.created_by,
  s.created_at,
  s.date_from,
  s.date_to,
  CASE WHEN s.official  THEN 'true' ELSE 'false' END AS official,
  CASE WHEN s.cancelled THEN 'true' ELSE 'false' END AS cancelled,
  CASE WHEN s.online    THEN 'true' ELSE 'false' END AS online,
  s.follow_count,
  s.tags,
  s.source_slug,
  s.synced_at,
  -- ⛔ NA KONEC, NE DOPROSTŘED. `CREATE OR REPLACE VIEW` umí sloupce jen PŘIDAT
  -- za poslední; vložení doprostřed je pro Postgres PŘEJMENOVÁNÍ a v provozu
  -- spadne (naměřeno 2026-09-06, API 502 na 9 minut). Hlídá brána
  -- `pohled-jde-nahradit`, která nechá o slučitelnosti rozhodnout sám Postgres.
  s.created_by_id
FROM public.source_period_stats s
WHERE s.kind = 'event';
COMMENT ON VIEW public.audience_admin_source_event_stats_v IS
  'Events created per month (operator export shape). Filter by month (YYYY-MM). Admin/staff via get_audience_view_*_block.';

-- ⛔ Pohled s právy vlastníka (mimo RLS podkladu) — čte se JEN přes DEFINER
-- blokové funkce get_audience_view_*_block (is_admin_or_staff + jmenný prostor
-- audience_admin_*_v). Přímý grant klientské roli tu stráž obchází (nález
-- 2026-10-04); REVOKE i z authenticated kvůli explicitním grantům z heals
-- a default privileges na běžící DB.
REVOKE ALL ON public.audience_admin_source_event_stats_v FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.audience_admin_source_event_stats_v TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/audience_admin_source_stats_monthly_v.sql
-- -----------------------------------------------------------------------------

-- View: public.audience_admin_source_stats_monthly_v
-- „Vysvětleno v grafu": jeden řádek = (druh, měsíc) s počtem vzniklých položek
-- a součtem sledujících. Nad tímhle stojí grafy; tabulky výše nesou detail.
CREATE OR REPLACE VIEW public.audience_admin_source_stats_monthly_v AS
SELECT
  s.kind,
  s.month,
  count(*)::bigint                                         AS items_count,
  sum(s.follow_count)::bigint                              AS follows_total,
  count(*) FILTER (WHERE s.cancelled OR s.deleted)::bigint AS withdrawn_count,
  count(*) FILTER (WHERE s.official)::bigint               AS official_count,
  count(*) FILTER (WHERE s.online)::bigint                 AS online_count
FROM public.source_period_stats s
GROUP BY s.kind, s.month;
COMMENT ON VIEW public.audience_admin_source_stats_monthly_v IS
  'Per (kind, month) counts over source_period_stats — chart source. Admin/staff.';

-- ⛔ Pohled s právy vlastníka (mimo RLS podkladu) — čte se JEN přes DEFINER
-- blokové funkce get_audience_view_*_block (is_admin_or_staff + jmenný prostor
