-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/public_service_health.sql
-- -----------------------------------------------------------------------------

-- View: public.public_service_health
--
-- VEŘEJNÁ PROJEKCE provozního stavu služeb. Existuje proto, aby funkce, kterou
-- smí volat anonym, neměla na dosah nic, co by mohlo uniknout.
--
-- PROČ POHLED A NE FILTR V DOTAZU
-- `integration_services` drží vedle stavu i `api_token`, `base_url` a `config`.
-- Dokud veřejná funkce četla přímo tuhle tabulku, byla bezpečná jen tím, JAK
-- byl napsaný její SELECT — tedy do první úpravy. Brána `security.gate` to
-- 2026-08-02 odmítla („NEW sensitive data functions with anon grant") a měla
-- pravdu: veřejná cesta nemá mít tajemství v dosahu, ne je jen nečíst.
--
-- Tajemství tu proto nejsou FYZICKY. Rozšíření zdrojové tabulky o další
-- citlivý sloupec tuhle projekci nerozšíří — musel by ho sem někdo dopsat
-- ručně, a to je viditelná změna v review, ne tichý důsledek.
--
-- CO NESE: jméno služby, stav, příznak aktivity, čas poslední kontroly.
-- CO NENESE: `api_token`, `base_url`, `config`, `service_type`, interní id.

CREATE OR REPLACE VIEW public.public_service_health AS
SELECT
  service_name,
  health_status,
  is_active,
  last_health_check
FROM public.integration_services;

COMMENT ON VIEW public.public_service_health IS
  'Veřejná projekce integration_services: jen stav a čas kontroly. Bez api_token, base_url a config — veřejná RPC čte tenhle pohled, ne zdrojovou tabulku.';

-- Pohled sám se anonovi NEUDĚLUJE: čte ho SECURITY DEFINER funkce
-- get_public_service_status() jménem vlastníka. Anon má jen EXECUTE na tu
-- funkci, takže ven jde agregát, ne řádky se jmény služeb.
REVOKE ALL ON public.public_service_health FROM PUBLIC;
GRANT SELECT ON public.public_service_health TO authenticated;
GRANT SELECT ON public.public_service_health TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/selfeval_story_verdict_v.sql
-- -----------------------------------------------------------------------------

-- View: public.selfeval_story_verdict_v
-- Self-evaluation LENS — per-story operational dimension aggregates (30d rolling).
-- Reads ONLY reused signals (faithfulness/drift/incidents/goal/proposals). The
-- composite score + level is composed by evaluate_story_self() RPC via
-- get_story_aisha_maturity(). "Evaluation je perspektiva, ne entita" — vzor
-- audience_actor_aggregate_latest_v. NO new table (viz SELF_EVAL_REUSE_VERIFICATION.md).
--
-- Story↔app correlation: drift_state / sentry_issue_snapshot link to a story via
-- coolify_app_slots.app_name → coolify_app_slots.story_id.
-- @security: granted to service_role only; authenticated reach is via the
-- SECURITY DEFINER evaluate_story_self() RPC (visibility-gated).

CREATE OR REPLACE VIEW public.selfeval_story_verdict_v AS
SELECT
  s.id AS story_id,
  -- faithfulness dimension (ai_runs.faithfulness_score_estimate)
  (SELECT ROUND(AVG(ar.faithfulness_score_estimate), 4)
     FROM public.ai_runs ar
    WHERE ar.story_id = s.id
      AND ar.faithfulness_score_estimate IS NOT NULL
      AND ar.started_at > now() - interval '30 days')          AS faithfulness_avg,
  (SELECT COUNT(*)
     FROM public.ai_runs ar
    WHERE ar.story_id = s.id
      AND ar.faithfulness_score_estimate IS NOT NULL
      AND ar.started_at > now() - interval '30 days')          AS faithfulness_n,
  -- drift dimension (drift_state via coolify_app_slots.story_id)
  (SELECT COUNT(*)
     FROM public.drift_state d
     JOIN public.coolify_app_slots c ON c.app_name = d.app_name
    WHERE c.story_id = s.id AND d.resolved_at IS NULL)          AS open_drift_count,
  (SELECT COUNT(*)
     FROM public.drift_state d
     JOIN public.coolify_app_slots c ON c.app_name = d.app_name
    WHERE c.story_id = s.id AND d.resolved_at IS NULL
      AND d.risk_level IN ('high','critical'))                 AS open_drift_high,
  -- incidents dimension (sentry_issue_snapshot via coolify_app_slots.story_id)
  (SELECT COALESCE(SUM(se.count), 0)
     FROM public.sentry_issue_snapshot se
     JOIN public.coolify_app_slots c ON c.app_name = se.app_name
    WHERE c.story_id = s.id AND se.level = 'fatal'
      AND se.observed_at > now() - interval '30 days')          AS sentry_fatal_30d,
  -- goal dimension (story_goal_state — autonomous loop acceptance criteria)
  g.acceptance_criteria,
  g.loop_iterations,
  g.loop_max,
  -- proposals (improvement_proposals correlated via run_id→ai_runs.story_id or metadata.story_id)
  (SELECT COUNT(*)
     FROM public.improvement_proposals ip
     LEFT JOIN public.ai_runs ar2 ON ar2.id = ip.run_id
    WHERE (ar2.story_id = s.id OR ip.metadata->>'story_id' = s.id::text)
      AND ip.status NOT IN ('applied','rejected','rolled_back')) AS open_proposals,
  (SELECT COUNT(*)
     FROM public.improvement_proposals ip
     LEFT JOIN public.ai_runs ar3 ON ar3.id = ip.run_id
    WHERE (ar3.story_id = s.id OR ip.metadata->>'story_id' = s.id::text)
      AND ip.applied_at IS NOT NULL
      AND ip.applied_at > now() - interval '30 days')           AS applied_proposals_30d
FROM public.partner_stories s
LEFT JOIN public.story_goal_state g ON g.story_id = s.id;

-- Least-privilege: direct reads only for service_role; authenticated reaches the
-- verdict through evaluate_story_self() (SECURITY DEFINER, visibility-gated).
REVOKE ALL ON public.selfeval_story_verdict_v FROM PUBLIC;
GRANT SELECT ON public.selfeval_story_verdict_v TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/shipment_statistics.sql
-- -----------------------------------------------------------------------------

-- View: public.shipment_statistics
-- Description: Shipment aggregates by month and status.

CREATE OR REPLACE VIEW public.shipment_statistics AS
SELECT
  sr.distribution_month,
  sr.status,
  COUNT(*)::int4 AS shipment_count,
  SUM(sr.discount_amount) AS total_discounts,
  SUM(sr.full_price) AS total_full_price,
  SUM(sr.final_price) AS total_revenue,
  SUM(sr.tokens_used) AS total_tokens_used
FROM shipment_records sr
GROUP BY sr.distribution_month, sr.status;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/study_cohort_lab_trends.sql
-- -----------------------------------------------------------------------------

-- View: public.study_cohort_lab_trends
-- Description: Monthly aggregated lab results trends per study cohort.
-- Security: Used by get_study_cohort_lab_trends() which enforces compliance Safe Harbor.

CREATE OR REPLACE VIEW public.study_cohort_lab_trends AS
SELECT 
  se.study_id,
  date_trunc('month', lr.test_date::timestamp)::date AS month_start,
  count(DISTINCT lr.user_id) AS participant_count,
  round(avg(lr.crp), 2) AS avg_crp,
  round(avg(lr.vitamin_d), 2) AS avg_vitamin_d,
  round(avg(lr.glucose), 2) AS avg_glucose,
  round(avg(lr.cholesterol_total), 2) AS avg_cholesterol,
  round(avg(lr.hemoglobin), 2) AS avg_hemoglobin,
  count(lr.id) AS lab_count
FROM study_registrations se
JOIN lab_results lr ON lr.study_registration_id = se.id
WHERE lr.test_date >= (CURRENT_DATE - INTERVAL '1 year')
  AND lr.status IN ('completed', 'reviewed')
GROUP BY se.study_id, date_trunc('month', lr.test_date::timestamp)::date
ORDER BY se.study_id, month_start;

-- Security: View is accessed only through get_study_cohort_lab_trends()
-- which enforces compliance Safe Harbor (min 5 participants) and auth checks


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/study_cohort_statistics.sql
-- -----------------------------------------------------------------------------

-- View: public.study_cohort_statistics
-- Description: Aggregated statistics per study cohort for research analysis.
-- Security: Used by get_study_cohort_statistics() which enforces compliance Safe Harbor.

CREATE OR REPLACE VIEW public.study_cohort_statistics AS
SELECT 
  se.study_id,
  count(DISTINCT se.user_id) AS total_participants,
  count(DISTINCT CASE WHEN se.status = 'active' THEN se.user_id END) AS active_participants,
  count(DISTINCT CASE WHEN se.status = 'completed' THEN se.user_id END) AS completed_participants,
  round(avg(hci.pain_level), 1) AS avg_pain_level,
  round(avg(hci.energy_level), 1) AS avg_energy_level,
  round(avg(hci.mood_level), 1) AS avg_mood_level,
  round(avg(hci.sleep_quality), 1) AS avg_sleep_quality,
  round(avg(hci.sleep_hours), 1) AS avg_sleep_hours,
  round(avg(lr.crp), 2) AS avg_crp,
  round(avg(lr.vitamin_d), 1) AS avg_vitamin_d,
  round(avg(lr.glucose), 1) AS avg_glucose,
  count(DISTINCT hci.id) AS total_check_ins,
  count(DISTINCT lr.id) AS total_lab_results,
  count(DISTINCT dl.id) AS total_dosing_logs
FROM study_registrations se
LEFT JOIN health_check_ins hci ON hci.user_id = se.user_id
LEFT JOIN lab_results lr ON lr.user_id = se.user_id
LEFT JOIN dosing_logs dl ON dl.user_id = se.user_id
WHERE se.status IN ('enrolled', 'active', 'completed')
GROUP BY se.study_id;

-- Security: View is accessed only through get_study_cohort_statistics() 
-- which enforces compliance Safe Harbor (min 5 participants) and auth checks


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/study_cohort_trends.sql
-- -----------------------------------------------------------------------------

-- View: public.study_cohort_trends
-- Description: Weekly aggregated health trends per study cohort.
-- Security: Used by get_study_cohort_trends() which enforces compliance Safe Harbor.

CREATE OR REPLACE VIEW public.study_cohort_trends AS
SELECT 
  se.study_id,
  date_trunc('week', hc.check_in_date::timestamp)::date AS week_start,
  count(DISTINCT hc.user_id) AS participant_count,
  round(avg(hc.pain_level), 2) AS avg_pain,
  round(avg(hc.energy_level), 2) AS avg_energy,
  round(avg(hc.mood_level), 2) AS avg_mood,
  round(avg(hc.sleep_quality), 2) AS avg_sleep_quality,
  round(avg(hc.sleep_hours), 2) AS avg_sleep_hours,
  count(hc.id) AS check_in_count
FROM study_registrations se
JOIN health_check_ins hc ON hc.study_registration_id = se.id
WHERE hc.check_in_date >= (CURRENT_DATE - INTERVAL '84 days')
GROUP BY se.study_id, date_trunc('week', hc.check_in_date::timestamp)::date
ORDER BY se.study_id, week_start;

-- Security: View is accessed only through get_study_cohort_trends()
-- which enforces compliance Safe Harbor (min 5 participants) and auth checks


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/views/v_health_monthly_summary.sql
-- -----------------------------------------------------------------------------

-- View: public.v_health_monthly_summary
-- Description: Monthly health metrics summary per user.
--
-- ⛔ security_invoker JE POVINNÝ (nález 2026-10-04). Bez něj se pohled čte
-- právy VLASTNÍKA, tedy MIMO RLS tabulky health_check_ins — a s GRANT SELECT
-- pro anon/authenticated vydával zdravotní souhrny (tep, bolest, nálada,
-- spánek) VŠECH uživatelů komukoli, i bez účtu. S security_invoker platí
-- policies podkladu: člen vidí své, konzultant souhlasem sdílené, admin vše.
CREATE OR REPLACE VIEW public.v_health_monthly_summary
WITH (security_invoker = true) AS
SELECT
  user_id,
  date_trunc('month', check_in_date)::date AS month_start,
  AVG(energy_level)::numeric AS avg_energy,
  AVG(heart_rate_avg)::numeric AS avg_heart_rate,
  AVG(mood_level)::numeric AS avg_mood,
  AVG(pain_level)::numeric AS avg_pain,
  AVG(sleep_hours)::numeric AS avg_sleep_hours,
  AVG(steps_count)::numeric AS avg_steps,
  COUNT(*)::int4 AS days_tracked,
  MAX(heart_rate_max)::int4 AS max_heart_rate,
  MIN(heart_rate_min)::int4 AS min_heart_rate,
  SUM(active_energy_burned)::numeric AS total_calories,
  SUM(distance_meters)::numeric AS total_distance_m
FROM health_check_ins
GROUP BY user_id, date_trunc('month', check_in_date)::date;


