-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/add_story_system_entry.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: add_story_system_entry
-- Popis: Story-cílený systémový zápis narace (tracking_event/system/action).
--        Doplňuje add_system_timeline_entry (per-user routing) o story-target pro
--        procesní fakta; dedup + provenance metadata. ACL: jen service_role —
--        volán interně z definer RPC (award_tokens vzor).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- Pozn.: definice = regenerát z nasazené DB (ověřeno provozním testem 07-25).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.add_story_system_entry(p_story_id uuid, p_entry_type text, p_content text, p_metadata jsonb DEFAULT NULL::jsonb, p_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source_table text DEFAULT NULL::text, p_source_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_allowed text[] := array['tracking_event','system','action'];
  v_entry_id uuid;
begin
  if not (p_entry_type = any(v_allowed)) then
    return jsonb_build_object('ok',false,'error',
      format('entry type %s not allowed (allowed: %s)', p_entry_type, v_allowed::text));
  end if;
  if not exists (select 1 from partner_stories where id = p_story_id) then
    return jsonb_build_object('ok',false,'error','story not found');
  end if;
  -- dedup: same source fact within 1 minute (trigger re-fire protection)
  if p_source_table is not null and p_source_id is not null then
    if exists (
      select 1 from story_entries se
      where se.story_id = p_story_id
        and se.entry_type = p_entry_type
        and se.content = p_content
        and se.metadata->>'source_table' = p_source_table
        and (se.metadata->>'source_id')::uuid = p_source_id
        and se.created_at > now() - interval '1 minute'
    ) then
      return jsonb_build_object('ok',false,'reason','duplicate');
    end if;
  end if;
  insert into story_entries (story_id, entry_type, content, metadata, occurred_at, created_by, is_internal)
  values (
    p_story_id, p_entry_type, p_content,
    jsonb_build_object('source_table',p_source_table,'source_id',p_source_id,'is_system',true)
      || coalesce(p_metadata,'{}'::jsonb),
    coalesce(p_occurred_at, now()),
    null,   -- system entry
    false
  ) returning id into v_entry_id;
  update partner_stories set last_activity_at = now(), updated_at = now() where id = p_story_id;
  return jsonb_build_object('ok',true,'entry_id',v_entry_id);
end $function$;

REVOKE ALL ON FUNCTION public.add_story_system_entry(uuid,text,text,jsonb,timestamp with time zone,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.add_story_system_entry(uuid,text,text,jsonb,timestamp with time zone,text,uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/add_system_timeline_entry.sql
-- -----------------------------------------------------------------------------

-- Function: add_system_timeline_entry
-- Purpose: System trigger adds automatic entries to member timeline
-- Access: Internal only (called by triggers)
-- Security: SECURITY DEFINER with audit logging. Internal-only per the line above — and yet it
--   was GRANTed to `authenticated` until the 2026-07-15 IDOR fix
--   (docs/security/IDOR_P_USER_ID_AUDIT_2026-07-15.md). Any logged-in user could call it with
--   another user's p_user_id and fabricate 'system_'-prefixed entries — system_lab_result,
--   system_payment, system_document — in that user's timeline. Those entry types exist precisely
--   to mark records the PLATFORM vouches for, as opposed to what a member wrote themselves, so
--   forging them is forging provenance: a fabricated lab result or payment in someone's medical
--   timeline, indistinguishable from a real one. The v_system_types check bounded the TYPE of the
--   forgery, never the AUTHOR — it reads as a guard and is not one.
--   Its 12 callers are trigger functions: SECURITY DEFINER, executed as the owner, who keeps
--   EXECUTE by ownership. Nothing outside the database calls it, so the grant bought nothing.

CREATE OR REPLACE FUNCTION public.add_system_timeline_entry(
  p_user_id UUID,
  p_entry_type TEXT,
  p_content TEXT,
  p_metadata JSONB DEFAULT NULL,
  p_occurred_at TIMESTAMPTZ DEFAULT NULL,
  p_source_table TEXT DEFAULT NULL,
  p_source_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_story RECORD;
  v_entry_id UUID;
  v_system_types TEXT[] := ARRAY[
    'system_registration',
    'system_order', 
    'system_lab_result',
    'system_check_in',
    'system_payment',
    'system_document',
    'system_questionnaire',
    'system_dosing',
    'system_health_sync'
  ];
BEGIN
  -- Validate entry type (only system types allowed)
  IF NOT (p_entry_type = ANY(v_system_types)) THEN
    RAISE EXCEPTION USING MESSAGE = format('Invalid system entry type: %s. Allowed: %s', p_entry_type, v_system_types::text), ERRCODE = '22023';
  END IF;

  -- Find user's primary story (or create one if not exists)
  SELECT ps.id
  INTO v_story
  FROM partner_stories ps
  WHERE ps.user_id = p_user_id
  ORDER BY ps.created_at ASC
  LIMIT 1;

  -- If user has no story, skip (they haven't opted into timeline yet)
  IF v_story.id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'reason', 'no_story'
    );
  END IF;

  -- Check for duplicate (same source within 1 minute to prevent trigger re-fires)
  IF p_source_table IS NOT NULL AND p_source_id IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM story_entries se
      WHERE se.story_id = v_story.id
        AND se.entry_type = p_entry_type
        AND se.metadata->>'source_table' = p_source_table
        AND (se.metadata->>'source_id')::uuid = p_source_id
        AND se.created_at > now() - interval '1 minute'
    ) THEN
      RETURN jsonb_build_object(
        'success', false,
        'reason', 'duplicate'
      );
    END IF;
  END IF;

  -- Create entry
  INSERT INTO story_entries (
    story_id,
    entry_type,
    content,
    metadata,
    occurred_at,
    created_by,
    is_internal
  )
  VALUES (
    v_story.id,
    p_entry_type,
    p_content,
    jsonb_build_object(
      'source_table', p_source_table,
      'source_id', p_source_id,
      'is_system', true
    ) || COALESCE(p_metadata, '{}'::jsonb),
    COALESCE(p_occurred_at, now()),
    NULL,  -- System entries have no created_by
    false  -- Visible to partner
  )
  RETURNING id INTO v_entry_id;

  -- Update story last_activity_at
  UPDATE partner_stories
  SET last_activity_at = now()
  WHERE id = v_story.id;

  -- Audit log (no sensitive data!)
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    p_user_id,
    'TIMELINE_SYSTEM_ENTRY',
    jsonb_build_object(
      'area', 'member_timeline',
      'severity', 'info',
      'entity_type', 'story_entry',
      'entity_id', v_entry_id,
      'entry_type', p_entry_type,
      'story_id', v_story.id,
      'source_table', p_source_table,
      'source_id', p_source_id
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'entry_id', v_entry_id,
    'story_id', v_story.id
  );
END;
$$;

-- Security: This is internal function, but grant to authenticated for testing
REVOKE ALL ON FUNCTION public.add_system_timeline_entry(uuid, text, text, jsonb, timestamptz, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.add_system_timeline_entry(uuid, text, text, jsonb, timestamptz, text, uuid) TO service_role;

COMMENT ON FUNCTION public.add_system_timeline_entry(uuid, text, text, jsonb, timestamptz, text, uuid) IS 'System function to add automatic timeline entries from triggers. Internal use only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/add_timeline_entry_audited.sql
-- -----------------------------------------------------------------------------

-- Function: add_timeline_entry_audited
-- Purpose: Member adds an entry to their own timeline (with optional backdating)
-- Access: Authenticated members only
-- Security: SECURITY DEFINER with audit logging

CREATE OR REPLACE FUNCTION public.add_timeline_entry_audited(
  p_story_id UUID,
  p_entry_type TEXT,
  p_content TEXT,
  p_metadata JSONB DEFAULT NULL,
  p_occurred_at TIMESTAMPTZ DEFAULT NULL,
  p_document_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id UUID;
  v_story RECORD;
  v_entry_id UUID;
  v_allowed_types TEXT[] := ARRAY[
    'note', 'health_event', 'document', 'message'
  ];
BEGIN
  -- Get current user
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Validate entry type (members can only add certain types)
  IF NOT (p_entry_type = ANY(v_allowed_types)) THEN
    RAISE EXCEPTION USING MESSAGE = format('Invalid entry type for member: %s. Allowed: %s', p_entry_type, v_allowed_types::text), ERRCODE = '22023';
  END IF;

  -- Verify story ownership (user_id = current user)
  SELECT ps.id, ps.title, ps.user_id, ps.partner_id
  INTO v_story
  FROM partner_stories ps
  WHERE ps.id = p_story_id
    AND ps.user_id = v_user_id;

  IF v_story.id IS NULL THEN
    RAISE EXCEPTION 'Story not found or not authorized'
      USING ERRCODE = 'no_data_found';
  END IF;

  -- Create entry
  INSERT INTO story_entries (
    story_id,
    entry_type,
    content,
    metadata,
    occurred_at,
    document_id,
    created_by,
    is_internal
  )
  VALUES (
    p_story_id,
    p_entry_type,
    p_content,
    COALESCE(p_metadata, '{}'::jsonb),
    COALESCE(p_occurred_at, now()),
    p_document_id,
    v_user_id,
    false  -- Member entries are always visible to partner
  )
  RETURNING id INTO v_entry_id;

  -- Update story last_activity_at
  UPDATE partner_stories
  SET 
    last_activity_at = now(),
    unread_count = unread_count + 1
  WHERE id = p_story_id;

  -- Audit log (no sensitive data!)
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'TIMELINE_ENTRY_CREATE',
    jsonb_build_object(
      'area', 'member_timeline',
      'severity', 'info',
      'entity_type', 'story_entry',
      'entity_id', v_entry_id,
      'entry_type', p_entry_type,
      'story_id', p_story_id,
      'is_backdated', p_occurred_at IS NOT NULL AND p_occurred_at < now()
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'entry_id', v_entry_id,
    'story_id', p_story_id
  );
END;
$$;

-- Security: Revoke all, grant only to authenticated
REVOKE ALL ON FUNCTION public.add_timeline_entry_audited(uuid, text, text, jsonb, timestamptz, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.add_timeline_entry_audited(uuid, text, text, jsonb, timestamptz, uuid) TO authenticated;

COMMENT ON FUNCTION public.add_timeline_entry_audited(uuid, text, text, jsonb, timestamptz, uuid) IS 'Member adds an entry to their own timeline with optional backdating. Audit logged.';


