-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aggregate_questionnaire_responses.sql
-- -----------------------------------------------------------------------------

-- Function: public.aggregate_questionnaire_responses
-- Arguments: p_questionnaire_code text, p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_study_registration_id uuid, p_group_by text
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:25:51+01:00

CREATE OR REPLACE FUNCTION public.aggregate_questionnaire_responses(p_questionnaire_code text, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_study_registration_id uuid DEFAULT NULL::uuid, p_group_by text DEFAULT 'week'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_questionnaire_id uuid;
  v_result jsonb;
  v_blocks jsonb;
  v_time_series jsonb;
BEGIN
  -- Audit log for sensitive data aggregation
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'aggregate_questionnaire_responses',
    jsonb_build_object(
      'area', 'phi',
      'severity', 'info',
      'entity_type', 'questionnaire_responses',
      'questionnaire_code', p_questionnaire_code,
      'study_registration_id', p_study_registration_id,
      'group_by', p_group_by
    )
  );

  -- Get questionnaire ID
  SELECT id INTO v_questionnaire_id
  FROM questionnaires
  WHERE code = p_questionnaire_code AND is_active = true;
  
  IF v_questionnaire_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Questionnaire not found', 'code', p_questionnaire_code);
  END IF;

  -- Aggregate per-block statistics
  WITH response_data AS (
    SELECT 
      qr.id,
      qr.user_id,
      qr.responses,
      qr.completed_at,
      qr.study_registration_id
    FROM questionnaire_responses qr
    WHERE qr.questionnaire_id = v_questionnaire_id
      AND (p_start_date IS NULL OR qr.completed_at >= p_start_date)
      AND (p_end_date IS NULL OR qr.completed_at <= p_end_date)
      AND (p_study_registration_id IS NULL OR qr.study_registration_id = p_study_registration_id)
  ),
  block_stats AS (
    SELECT 
      qb.block_id,
      qblk.code AS block_code,
      qblk.question_type,
      qblk.config,
      COUNT(DISTINCT rd.id) AS response_count,
      -- Scale/number aggregations
      CASE WHEN qblk.question_type IN ('scale', 'number') THEN
        AVG((rd.responses->qblk.code->>'value')::numeric)
      END AS avg_value,
      CASE WHEN qblk.question_type IN ('scale', 'number') THEN
        PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY (rd.responses->qblk.code->>'value')::numeric)
      END AS median_value,
      CASE WHEN qblk.question_type IN ('scale', 'number') THEN
        STDDEV((rd.responses->qblk.code->>'value')::numeric)
      END AS std_dev,
      CASE WHEN qblk.question_type IN ('scale', 'number') THEN
        MIN((rd.responses->qblk.code->>'value')::numeric)
      END AS min_value,
      CASE WHEN qblk.question_type IN ('scale', 'number') THEN
        MAX((rd.responses->qblk.code->>'value')::numeric)
      END AS max_value,
      -- Boolean aggregation
      CASE WHEN qblk.question_type = 'boolean' THEN
        COUNT(*) FILTER (WHERE (rd.responses->qblk.code->>'value')::boolean = true)
      END AS true_count,
      CASE WHEN qblk.question_type = 'boolean' THEN
        COUNT(*) FILTER (WHERE (rd.responses->qblk.code->>'value')::boolean = false)
      END AS false_count,
      -- Tags aggregation (collect all tags)
      CASE WHEN qblk.question_type = 'tags' THEN
        jsonb_agg(rd.responses->qblk.code->'selectedTags')
      END AS all_tags
    FROM questionnaire_blocks qb
    JOIN question_blocks qblk ON qblk.id = qb.block_id
    LEFT JOIN response_data rd ON rd.responses ? qblk.code
    WHERE qb.questionnaire_id = v_questionnaire_id
    GROUP BY qb.block_id, qblk.code, qblk.question_type, qblk.config
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'block_code', block_code,
      'question_type', question_type,
      'response_count', response_count,
      'aggregation', CASE 
        WHEN question_type IN ('scale', 'number') THEN
          jsonb_build_object(
            'type', question_type,
            'avg', COALESCE(avg_value, 0),
            'median', COALESCE(median_value, 0),
            'std_dev', COALESCE(std_dev, 0),
            'min', COALESCE(min_value, 0),
            'max', COALESCE(max_value, 0)
          )
        WHEN question_type = 'boolean' THEN
          jsonb_build_object(
            'type', 'boolean',
            'true_count', COALESCE(true_count, 0),
            'false_count', COALESCE(false_count, 0),
            'true_percentage', CASE WHEN response_count > 0 
              THEN ROUND((COALESCE(true_count, 0)::numeric / response_count) * 100, 2)
              ELSE 0 
            END
          )
        WHEN question_type = 'tags' THEN
          jsonb_build_object(
            'type', 'tags',
            'all_tags', COALESCE(all_tags, '[]'::jsonb)
          )
        ELSE
          jsonb_build_object('type', question_type, 'raw', 'text-based')
      END
    )
  ) INTO v_blocks
  FROM block_stats;

  -- Time series aggregation
  WITH time_buckets AS (
    SELECT 
      CASE p_group_by
        WHEN 'day' THEN date_trunc('day', qr.completed_at)
        WHEN 'week' THEN date_trunc('week', qr.completed_at)
        WHEN 'month' THEN date_trunc('month', qr.completed_at)
        ELSE date_trunc('week', qr.completed_at)
      END AS bucket,
      COUNT(*) AS response_count,
      AVG(jsonb_array_length(
        (SELECT jsonb_agg(k) FROM jsonb_object_keys(qr.responses) AS k)
      )) AS avg_blocks_answered
    FROM questionnaire_responses qr
    WHERE qr.questionnaire_id = v_questionnaire_id
      AND (p_start_date IS NULL OR qr.completed_at >= p_start_date)
      AND (p_end_date IS NULL OR qr.completed_at <= p_end_date)
      AND (p_study_registration_id IS NULL OR qr.study_registration_id = p_study_registration_id)
    GROUP BY bucket
    ORDER BY bucket
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'period', bucket,
      'response_count', response_count,
      'avg_blocks_answered', COALESCE(avg_blocks_answered, 0)
    )
  ) INTO v_time_series
  FROM time_buckets;

  -- Build final result
  v_result := jsonb_build_object(
    'questionnaire_code', p_questionnaire_code,
    'questionnaire_id', v_questionnaire_id,
    'filters', jsonb_build_object(
      'start_date', p_start_date,
      'end_date', p_end_date,
      'study_registration_id', p_study_registration_id,
      'group_by', p_group_by
    ),
    'blocks', COALESCE(v_blocks, '[]'::jsonb),
    'time_series', COALESCE(v_time_series, '[]'::jsonb),
    'generated_at', now()
  );

  RETURN v_result;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.aggregate_questionnaire_responses(p_questionnaire_code text, p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_study_registration_id uuid, p_group_by text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aggregate_questionnaire_responses(p_questionnaire_code text, p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_study_registration_id uuid, p_group_by text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_assert_definer_grants.sql
-- -----------------------------------------------------------------------------

-- Function: aisha_assert_definer_grants
-- Auto-extracted (back-port reconciliation)

CREATE OR REPLACE FUNCTION public.aisha_assert_definer_grants()
 RETURNS TABLE(schema_name text, function_ident text, grantee text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT
    n.nspname::text AS schema_name,
    (p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')')::text
      AS function_ident,
    COALESCE((SELECT r.rolname FROM pg_roles r WHERE r.oid = a.grantee), 'PUBLIC')::text
      AS grantee
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  -- COALESCE to acldefault so functions that NEVER had an explicit grant/revoke
  -- (NULL proacl == Postgres default == EXECUTE TO PUBLIC) are still surfaced.
  CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl, acldefault('f'::"char", p.proowner))) AS a
  WHERE n.nspname NOT IN ('pg_catalog', 'information_schema')
    AND p.prosecdef = true                       -- SECURITY DEFINER only
    AND a.privilege_type = 'EXECUTE'
    AND (
      a.grantee = 0                              -- 0 == the PUBLIC pseudo-role
      OR a.grantee = (SELECT r.oid FROM pg_roles r WHERE r.rolname = 'anon')
    )
  ORDER BY 1, 2, 3
$function$
;

REVOKE ALL ON FUNCTION aisha_assert_definer_grants() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION aisha_assert_definer_grants() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_assert_rls_self_reference.sql
-- -----------------------------------------------------------------------------

-- Function: aisha_assert_rls_self_reference
-- Auto-extracted (back-port reconciliation)

CREATE OR REPLACE FUNCTION public.aisha_assert_rls_self_reference()
 RETURNS TABLE(table_ident text, policy_name text, clause text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  -- pg_policies.qual / .with_check hold the EXPANDED expression text, in which
  -- Postgres rewrites every column reference as `tablename.column`. So a policy
  -- that merely filters on its OWN columns (the normal, safe case) ALWAYS names
  -- its table -- a naked `\mtablename\M` match flags all of them (~80% false
  -- positives observed: 20 hits, only 4 real). The actual 42P17 recursion risk
  -- is narrower: the own table appearing in a FROM / JOIN, i.e. a SUBQUERY that
  -- re-enters the table's own policies. We anchor the match to
  -- `(FROM|JOIN) [schema.]tablename` so own-column refs (`tablename.col`) are
  -- excluded while real self-subqueries are caught. A policy that delegates to a
  -- SECURITY DEFINER helper never names its own table in a FROM/JOIN -- which is
  -- exactly why the helper fix breaks the recursion. (Keyword case is stable:
  -- Postgres deparse upper-cases FROM/JOIN in the stored expression.)
  SELECT
    (pol.schemaname || '.' || pol.tablename)::text AS table_ident,
    pol.policyname::text                           AS policy_name,
    (CASE
       WHEN pol.qual ~ ('\m(FROM|JOIN)\s+(ONLY\s+)?(' || pol.schemaname || '\.)?' || pol.tablename || '\M')
         THEN 'USING'
       ELSE 'WITH CHECK'
     END)::text                                    AS clause
  FROM pg_policies pol
  WHERE pol.schemaname NOT IN ('pg_catalog', 'information_schema')
    AND (
      pol.qual       ~ ('\m(FROM|JOIN)\s+(ONLY\s+)?(' || pol.schemaname || '\.)?' || pol.tablename || '\M')
      OR pol.with_check ~ ('\m(FROM|JOIN)\s+(ONLY\s+)?(' || pol.schemaname || '\.)?' || pol.tablename || '\M')
    )
  ORDER BY 1, 2
$function$
;

REVOKE ALL ON FUNCTION aisha_assert_rls_self_reference() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION aisha_assert_rls_self_reference() TO service_role;


