-- ============================================================================
-- Source of truth: aisha_column_encryption_key
--
-- OWASP A02 — Cryptographic Failures. Klíč pgp_sym pro šifrování sloupců
-- (aisha_{encrypt,decrypt}_column_audited). Hodnotu doručuje trezor instance
-- (COLUMN_ENCRYPTION_KEY v env služby db) — NIKDY v repu.
--
-- ⛔ KLÍČ NENÍ GUC. Dřív ho nesl `ALTER DATABASE postgres SET
-- app.column_encryption_key` (+ PGOPTIONS). NAMĚŘENO 2026-09-25 na dočasné DB:
-- vlastní GUC nejde omezit, takže ho přes current_setting() / pg_db_role_setting
-- přečetla KAŽDÁ role — 11 login rolí i anon/authenticated/service_role — a
-- anon s ním dešifroval sloupec mimo audit. REVOKE na téhle funkci byl divadlo.
--
-- ✅ Teď: entrypoint-wrapper.sh při startu zapíše klíč do souboru mimo databázi
-- (/run/aisha-keys, vlastník postgres, 0400) a tahle funkce ho čte. Klíč tak
-- není v GUC, v katalogu ani v záloze DB. Čte ji jen VLASTNÍK (superuživatel,
-- který ji zakládá migrate) — tedy definer funkce téhož vlastníka. Žádný GRANT:
-- dřívější grant pro service_role dával klíč i přes PostgREST /rpc.
--
-- Chybějící nebo slabý klíč = výjimka. Žádná záloha na GUC ani jiný zdroj.
-- Brány: src/tests/gates/klice-sifrovani-doruceni.gate.test.ts (kontrakt
-- doručení), src/tests/db/tajemstvi-nejsou-citelna.runtime.test.ts (čitelnost).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.aisha_column_encryption_key()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $$
DECLARE
  v_key text;
BEGIN
  BEGIN
    -- Bez ořezu: hodnota musí být BAJTOVĚ táž jako dřív v GUC (jinak starý
    -- šifrový text nejde otevřít); zapisovatel píše printf '%s', bez konce řádku.
    v_key := pg_read_file('/run/aisha-keys/column_encryption.key');
  EXCEPTION
    WHEN undefined_file THEN
      RAISE EXCEPTION 'AISHA_ENCRYPTION_KEY_MISSING_OR_WEAK'
        USING DETAIL = 'Soubor /run/aisha-keys/column_encryption.key neexistuje.',
              HINT = 'Zapisuje ho infra/postgres/entrypoint-wrapper.sh z COLUMN_ENCRYPTION_KEY při startu služby db.';
  END;
  IF v_key IS NULL OR length(v_key) < 32 THEN
    RAISE EXCEPTION 'AISHA_ENCRYPTION_KEY_MISSING_OR_WEAK';
  END IF;
  RETURN v_key;
END;
$$;
REVOKE ALL ON FUNCTION public.aisha_column_encryption_key() FROM PUBLIC;
-- Existující DB drží dřívější grant pro service_role — výslovně odebrat.
REVOKE ALL ON FUNCTION public.aisha_column_encryption_key() FROM anon, authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_dryrun_in_openclaw_sandbox.sql
-- -----------------------------------------------------------------------------

-- Function: aisha_dryrun_in_openclaw_sandbox
-- AISHA → OpenClaw sandbox dry-run request. Used by reflection openclaw_sandbox
-- node + risky n8n workflow validation.
--
-- Same two-step pattern as aisha_request_plan_from_openclaw: audits the
-- request, returns a request_id; the TS caller then invokes the edge fn
-- openclaw-bridge to perform the actual HTTP roundtrip.

CREATE OR REPLACE FUNCTION public.aisha_dryrun_in_openclaw_sandbox(
  p_workflow_json jsonb,
  p_inputs jsonb DEFAULT '{}'::jsonb,
  p_timeout_s int DEFAULT 120,
  p_related_run_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_request_id      uuid;
  v_user_id         uuid;
  v_request_payload jsonb;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_workflow_json IS NULL OR p_workflow_json = '{}'::jsonb THEN
    RAISE EXCEPTION 'p_workflow_json is required';
  END IF;
  IF p_timeout_s < 5 OR p_timeout_s > 600 THEN
    RAISE EXCEPTION 'p_timeout_s must be 5..600 seconds';
  END IF;

  v_user_id := auth.uid();
  v_request_id := gen_random_uuid();

  v_request_payload := jsonb_build_object(
    'request_id', v_request_id,
    'workflow_json', p_workflow_json,
    'inputs', COALESCE(p_inputs, '{}'::jsonb),
    'timeout_s', p_timeout_s,
    'related_run_id', p_related_run_id,
    'requested_at', now(),
    'requested_by', v_user_id
  );

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'openclaw.sandbox_dryrun_requested',
    v_request_payload
  );

  RETURN jsonb_build_object(
    'request_id', v_request_id,
    'status', 'queued',
    'message', 'Sandbox request audited; caller invokes openclaw-bridge.',
    'payload', v_request_payload
  );
END;
$$;

COMMENT ON FUNCTION public.aisha_dryrun_in_openclaw_sandbox(jsonb, jsonb, int, uuid) IS
  'Audits a sandbox dry-run request for OpenClaw advisory. Caller invokes the '
  'openclaw-bridge edge fn to perform the HTTP call.';

REVOKE ALL ON FUNCTION public.aisha_dryrun_in_openclaw_sandbox(jsonb, jsonb, int, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aisha_dryrun_in_openclaw_sandbox(jsonb, jsonb, int, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aisha_dryrun_in_openclaw_sandbox(jsonb, jsonb, int, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_evaluate_provider_for_task.sql
-- -----------------------------------------------------------------------------

-- Function: aisha_evaluate_provider_for_task
-- AISHA's internal provider scorer. Given a task description + task_kind,
-- returns per-(provider × model) scores so AISHA can reason about *why* it
-- picked a specific backend without running the full clow resolver.
--
-- Used by:
--   - Admin dashboard (Appsmith) to inspect AISHA's current preferences
--   - WF_MODEL_BENCHMARK n8n workflow to compare benchmarks pre/post update
--   - Debugging: "why did AISHA pick model X for this clow?"

CREATE OR REPLACE FUNCTION public.aisha_evaluate_provider_for_task(
  p_task_kind text,
  p_filters jsonb DEFAULT '{}'::jsonb
)
RETURNS TABLE (
  provider_slug text,
  backend_kind text,
  model_id text,
  cost_class text,
  overall_score numeric,
  is_available boolean,
  health_status text,
  bench_relevance numeric,
  bench_latency_ms integer,
  bench_success_rate numeric,
  reason text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_include_local      boolean := COALESCE((p_filters->>'include_local')::boolean, true);
  v_include_mcp        boolean := COALESCE((p_filters->>'include_mcp')::boolean, true);
  v_only_cost_class    text    := p_filters->>'only_cost_class';
  v_requires_tools     boolean := COALESCE((p_filters->>'requires_tools')::boolean, false);
  v_requires_vision    boolean := COALESCE((p_filters->>'requires_vision')::boolean, false);
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  RETURN QUERY
  SELECT
    p.slug         AS provider_slug,
    p.backend_kind AS backend_kind,
    r.model_id     AS model_id,
    p.cost_class   AS cost_class,
    COALESCE(b.overall_score, 0.5) AS overall_score,
    r.is_available AS is_available,
    p.last_health_status AS health_status,
    COALESCE((b.scores->>'relevance')::numeric, 0.0) AS bench_relevance,
    COALESCE(b.avg_latency_ms, 0) AS bench_latency_ms,
    COALESCE(b.success_rate, 0.0) AS bench_success_rate,
    format(
      'provider=%s/%s, kind=%s, cost=%s, health=%s, bench_score=%.2f',
      p.slug, r.model_id, p.backend_kind, p.cost_class, p.last_health_status,
      COALESCE(b.overall_score, 0.5)
    ) AS reason
  FROM public.ai_provider_registry p
  JOIN public.ai_model_registry r
    ON COALESCE(r.provider_registry_id, NULL) = p.id
    OR r.provider = p.slug
  LEFT JOIN public.ai_model_benchmarks b
    ON b.model_registry_id = r.id AND b.task_type = p_task_kind
  WHERE p.is_enabled
    AND r.is_available AND NOT r.is_deprecated
    AND (v_include_local OR p.backend_kind NOT IN ('local_ollama', 'local_vllm'))
    AND (v_include_mcp OR p.backend_kind != 'mcp_server')
    AND (v_only_cost_class IS NULL OR p.cost_class = v_only_cost_class)
    AND (NOT v_requires_tools OR r.is_function_calling)
    AND (NOT v_requires_vision OR r.is_vision)
  ORDER BY COALESCE(b.overall_score, 0.5) DESC,
           CASE p.cost_class WHEN 'budget' THEN 1 WHEN 'standard' THEN 2 WHEN 'premium' THEN 3 ELSE 4 END;
END;
$$;

COMMENT ON FUNCTION public.aisha_evaluate_provider_for_task(text, jsonb) IS
  'AISHA provider/model scorer for a given task_kind. Read-only, STABLE. '
  'Used by admin UI + debug + WF_MODEL_BENCHMARK comparison.';

REVOKE ALL ON FUNCTION public.aisha_evaluate_provider_for_task(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aisha_evaluate_provider_for_task(text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aisha_evaluate_provider_for_task(text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_get_active_static_defense_rules.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: aisha_get_active_static_defense_rules
-- Popis: Read-only RPC consumed by `scripts/gen-static-defense.mjs` to
--        generate .semgrep/aisha-rules.yml + other policy files.
-- Bezpečnost: SECURITY DEFINER, anon may read (rules are public policy).
-- Audit: žádný (read-only, idempotent).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.aisha_get_active_static_defense_rules(
  p_category text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_rows jsonb;
BEGIN
  -- No auth check: this is policy metadata, intentionally readable so
  -- generators run in CI environments without DB credentials too.

  IF p_category IS NOT NULL AND p_category NOT IN ('semgrep', 'eslint-no-secrets', 'owasp-exemption') THEN
    RAISE EXCEPTION 'Unknown category: %', p_category;
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'rule_id', rule_id,
      'category', category,
      'owasp_category', owasp_category,
      'semgrep_pattern', semgrep_pattern,
      'semgrep_paths', semgrep_paths,
      'semgrep_message', semgrep_message,
      'languages', languages,
      'severity', severity,
      'version', version,
      'rationale', rationale
    )
    ORDER BY category, rule_id
  ), '[]'::jsonb)
  INTO v_rows
  FROM public.aisha_static_defense_rules
  WHERE status = 'active'
    AND (p_category IS NULL OR category = p_category);

  RETURN v_rows;
END;
$$;

REVOKE ALL ON FUNCTION public.aisha_get_active_static_defense_rules(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aisha_get_active_static_defense_rules(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aisha_get_active_static_defense_rules(text) TO anon;
GRANT EXECUTE ON FUNCTION public.aisha_get_active_static_defense_rules(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_notify_via_openclaw.sql
-- -----------------------------------------------------------------------------

-- Function: aisha_notify_via_openclaw
-- AISHA → OpenClaw multi-channel notification enqueue.
-- INSERT into openclaw_notifications outbox; WF_OPENCLAW_NOTIFY n8n workflow
-- scans every 30s and dispatches to the configured channel.

CREATE OR REPLACE FUNCTION public.aisha_notify_via_openclaw(
  p_channel text,
  p_recipient text,
  p_payload jsonb,
  p_template text DEFAULT 'plain',
  p_agent_slug text DEFAULT 'aisha',
  p_related_run_id uuid DEFAULT NULL,
  p_story_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id      uuid;
  v_user_id uuid;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;
  IF p_channel NOT IN ('telegram','slack','matrix','discord','email','in_app') THEN
    RAISE EXCEPTION 'Invalid channel: %', p_channel USING ERRCODE = '22023';
  END IF;
  IF p_payload IS NULL OR p_payload = '{}'::jsonb THEN
    RAISE EXCEPTION 'p_payload is required' USING ERRCODE = '22023';
  END IF;

  v_user_id := auth.uid();

  INSERT INTO openclaw_notifications (
    channel, recipient, template, payload,
    status, agent_slug, related_run_id, story_id,
    created_by
  )
  VALUES (
    p_channel, p_recipient, COALESCE(p_template, 'plain'), p_payload,
    'queued', p_agent_slug, p_related_run_id, p_story_id,
    v_user_id
  )
  RETURNING id INTO v_id;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id, 'openclaw.notification_queued',
    jsonb_build_object(
      'notification_id', v_id,
      'channel', p_channel,
      'recipient', p_recipient,
      'template', p_template,
      'agent_slug', p_agent_slug,
      'related_run_id', p_related_run_id
    )
  );

  RETURN jsonb_build_object('notification_id', v_id, 'status', 'queued');
END;
$$;

COMMENT ON FUNCTION public.aisha_notify_via_openclaw(text, text, jsonb, text, text, uuid, uuid) IS
  'Enqueue a notification into the openclaw_notifications outbox. n8n '
  'WF_OPENCLAW_NOTIFY dispatches every 30s.';

REVOKE ALL ON FUNCTION public.aisha_notify_via_openclaw(text, text, jsonb, text, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aisha_notify_via_openclaw(text, text, jsonb, text, text, uuid, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aisha_notify_via_openclaw(text, text, jsonb, text, text, uuid, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_record_mcp_test_result.sql
-- -----------------------------------------------------------------------------

-- Function: aisha_record_mcp_test_result
-- Records the outcome of an MCP probe performed by the TS layer.
-- Updates status: tested_ok | tested_failed. After 3 consecutive failures,
-- promotes to 'rejected' so AISHA stops retrying.

CREATE OR REPLACE FUNCTION public.aisha_record_mcp_test_result(
  p_slug text,
  p_ok boolean,
  p_latency_ms int DEFAULT NULL,
  p_supported_methods text[] DEFAULT NULL,
  p_sample_response_excerpt text DEFAULT NULL,
  p_error text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_server   RECORD;
  v_new_status text;
  v_new_failures int;
  v_user_id  uuid;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_server FROM mcp_server_registry WHERE slug = p_slug FOR UPDATE;
  IF v_server IS NULL THEN
    RAISE EXCEPTION 'MCP server % not found', p_slug;
  END IF;

  v_user_id := auth.uid();

  IF p_ok THEN
    v_new_status := 'tested_ok';
    v_new_failures := 0;
  ELSE
    v_new_failures := v_server.test_failure_count + 1;
    v_new_status := CASE
      WHEN v_new_failures >= 3 THEN 'rejected'
      ELSE 'tested_failed'
    END;
  END IF;

  UPDATE mcp_server_registry
  SET status = v_new_status,
      last_tested_at = now(),
      last_test_result = jsonb_build_object(
        'ok', p_ok,
        'latency_ms', p_latency_ms,
        'supported_methods', to_jsonb(COALESCE(p_supported_methods, ARRAY[]::text[])),
        'sample_response_excerpt', p_sample_response_excerpt,
        'error', p_error
      ),
      test_failure_count = v_new_failures,
      updated_at = now()
  WHERE id = v_server.id;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    CASE WHEN p_ok THEN 'mcp.test_succeeded' ELSE 'mcp.test_failed' END,
    jsonb_build_object(
      'mcp_server_id', v_server.id, 'slug', p_slug,
      'new_status', v_new_status, 'failure_count', v_new_failures,
      'latency_ms', p_latency_ms, 'error', p_error
    )
  );

  RETURN jsonb_build_object(
    'slug', p_slug,
    'new_status', v_new_status,
    'failure_count', v_new_failures
  );
END;
$$;

COMMENT ON FUNCTION public.aisha_record_mcp_test_result(text, boolean, int, text[], text, text) IS
  'Records MCP test outcome. Transitions status; after 3 failures auto-rejects.';

REVOKE ALL ON FUNCTION public.aisha_record_mcp_test_result(text, boolean, int, text[], text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aisha_record_mcp_test_result(text, boolean, int, text[], text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aisha_record_mcp_test_result(text, boolean, int, text[], text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_request_plan_from_openclaw.sql
-- -----------------------------------------------------------------------------

-- Function: aisha_request_plan_from_openclaw
-- AISHA → OpenClaw advisory planner. Used by reflection openclaw_plan node.
-- The HTTP call to OpenClaw is performed by the edge function
-- openclaw-bridge; this RPC delegates to it via pg_net (deferred) and stores
-- the resulting plan in audit_journal for replay + traceability.
--
-- Soft-fails when OpenClaw unavailable — returns {error, fallback: 'direct'}
-- so the caller can degrade to direct execution.

CREATE OR REPLACE FUNCTION public.aisha_request_plan_from_openclaw(
  p_task jsonb,
  p_constraints jsonb DEFAULT '{}'::jsonb,
  p_related_run_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_request_id      uuid;
  v_user_id         uuid;
  v_request_payload jsonb;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_task IS NULL OR p_task = '{}'::jsonb THEN
    RAISE EXCEPTION 'p_task is required';
  END IF;

  v_user_id := auth.uid();
  v_request_id := gen_random_uuid();

  v_request_payload := jsonb_build_object(
    'request_id', v_request_id,
    'task', p_task,
    'constraints', COALESCE(p_constraints, '{}'::jsonb),
    'related_run_id', p_related_run_id,
    'requested_at', now(),
    'requested_by', v_user_id
  );

  -- Persist request in audit_journal for replay + traceability.
  -- The actual HTTP call to OpenClaw happens out-of-band: the
  -- supabase/functions/openclaw-bridge edge fn is invoked by the caller
  -- (TS layer) with this request_payload. We do NOT call HTTP from the RPC
  -- (Postgres functions shouldn't do outbound HTTP — too risky for STABLE-ness
  -- expectations and timeouts).
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'openclaw.plan_requested',
    v_request_payload
  );

  RETURN jsonb_build_object(
    'request_id', v_request_id,
    'status', 'queued',
    'message', 'Request audited; caller must invoke openclaw-bridge edge fn with this payload.',
    'payload', v_request_payload
  );
END;
$$;

COMMENT ON FUNCTION public.aisha_request_plan_from_openclaw(jsonb, jsonb, uuid) IS
  'Audits a plan request payload for OpenClaw advisory. The caller (svc-ai-chat) '
  'then calls the openclaw-bridge edge function with the returned payload. '
  'Two-step pattern keeps HTTP out of plpgsql while preserving audit invariant.';

REVOKE ALL ON FUNCTION public.aisha_request_plan_from_openclaw(jsonb, jsonb, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aisha_request_plan_from_openclaw(jsonb, jsonb, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aisha_request_plan_from_openclaw(jsonb, jsonb, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_resolve_clow_backend.sql
-- -----------------------------------------------------------------------------

-- Function: aisha_resolve_clow_backend
-- Per-clow backend dispatch decision. Given a clow sub-agent's purpose +
-- constraints, returns AISHA's choice of {backend, model, strategy, mcp_servers}.
--
-- Input ingredients:
--   - p_clow: { purpose, capability_tags[], task_kind, expected_tokens, deadline_hours, max_cost, allow_batch, allow_local }
--   - p_context: { agent_slug, story_id, parent_run_id, budget_remaining }
--
-- Decision rules (transparent, STABLE):
--   1. Filter providers by enabled + healthy
--   2. Filter by capability flags (supports_tool_use, supports_vision, supports_batch)
--   3. Prefer local (Ollama/vLLM) when allow_local=true and provider can serve task
--   4. Apply deadline → batch eligibility (matches aisha_choose_execution_strategy)
--   5. Apply cost class filter: budget_remaining < $1 → cost_class='budget'
--   6. Per-(provider × task_kind) score from ai_model_benchmarks
--   7. Top candidate wins; ties broken by lowest cost
--
-- Returns ranked candidates so caller can fall back if top fails health probe.

CREATE OR REPLACE FUNCTION public.aisha_resolve_clow_backend(
  p_clow jsonb,
  p_context jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  -- Clow inputs
  v_purpose           text   := p_clow->>'purpose';
  v_capability_tags   text[] := COALESCE(
    ARRAY(SELECT jsonb_array_elements_text(p_clow->'capability_tags')),
    ARRAY[]::text[]
  );
  v_task_kind         text   := COALESCE(p_clow->>'task_kind', 'chat');
  -- Raw caller inputs; policy defaults applied in BEGIN once ai_resolver_policy is loaded
  -- (was COALESCE(..., <literal>) — the literal now lives in the operator-tunable policy row).
  v_expected_tokens   int    := (p_clow->>'expected_tokens')::int;
  v_deadline_hours    int    := (p_clow->>'deadline_hours')::int;
  v_max_cost      numeric := (p_clow->>'max_cost')::numeric;
  v_allow_batch       boolean := COALESCE((p_clow->>'allow_batch')::boolean, true);
  v_allow_local       boolean := COALESCE((p_clow->>'allow_local')::boolean, true);
  v_cloud_forbidden   boolean := COALESCE((p_clow->>'cloud_forbidden')::boolean, false);
  v_needs_tools       boolean := COALESCE((p_clow->>'needs_tools')::boolean, false);
  v_needs_vision      boolean := COALESCE((p_clow->>'needs_vision')::boolean, false);

  -- Context inputs
  v_budget_remaining  numeric := (p_context->>'budget_remaining')::numeric;  -- policy default in BEGIN
  v_session_id        text    := p_context->>'session_id';
  v_parent_run_id     uuid    := NULLIF(p_context->>'parent_run_id', '')::uuid;
  -- Runtime serviceability: provider slugs whose key/endpoint is configured in the
  -- CALLING process (from getAllBackends). Empty = unconstrained (e.g. the scheduled
  -- discovery probe) so a 0-length array does NOT filter; non-empty intersects.
  v_serviceable       text[]  := ARRAY(SELECT jsonb_array_elements_text(p_context->'serviceable_slugs'));
  -- §19.4 per-instance scoping: the caller's instance (from p_context). Empty/NULL
  -- ⇒ only base/global providers (scoped_to_instance_id IS NULL) are candidates.
  v_instance_id       uuid    := NULLIF(p_context->>'instance_id', '')::uuid;

  -- Computed
  v_prefer_batch      boolean;
  v_cost_class_filter text;
  v_candidates        jsonb;
  v_top               jsonb;
  v_reasoning         text;
  -- Operator-tunable decision policy (weights/thresholds/defaults) — see ai_resolver_policy.
  v_pol               public.ai_resolver_policy%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF v_purpose IS NULL OR v_purpose = '' THEN
    RAISE EXCEPTION 'p_clow.purpose is required';
  END IF;

  -- Operator-tunable decision policy (public.ai_resolver_policy): the GLOBAL row, with an optional
  -- per-task-kind override (global×kind > global×*). The GLOBAL row is seeded + healed to ALWAYS
  -- exist; its absence is a fail-loud config error — NEVER a silent re-baked literal. (story +
  -- instance scopes are @scope-reserved forward seams — not yet read here.)
  SELECT * INTO v_pol
    FROM public.ai_resolver_policy
   WHERE is_active AND scope_type = 'global'
     AND (task_kind IS NULL OR task_kind = v_task_kind)
   ORDER BY (task_kind IS NOT NULL) DESC
   LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ai_resolver_policy has no active GLOBAL row — resolver decision policy is unconfigured (seed 37 / heals must apply)';
  END IF;

  -- Apply policy defaults for caller-omitted inputs (were hardcoded COALESCE literals).
  v_expected_tokens  := COALESCE(v_expected_tokens,  v_pol.default_expected_tokens);
  v_deadline_hours   := COALESCE(v_deadline_hours,   v_pol.default_deadline_hours);
  v_max_cost     := COALESCE(v_max_cost,     v_pol.default_max_cost);
  v_budget_remaining := COALESCE(v_budget_remaining, v_pol.default_budget_remaining);

  -- Batch eligibility (mirrors aisha_choose_execution_strategy)
  v_prefer_batch :=
    v_allow_batch
    AND v_deadline_hours >= v_pol.batch_min_deadline_hours
    AND v_expected_tokens >= v_pol.batch_min_tokens
    AND v_task_kind NOT IN ('chat')
    AND p_clow->>'criticality' IS DISTINCT FROM 'critical'
    AND p_clow->>'criticality' IS DISTINCT FROM 'high';

  -- Cost class
  v_cost_class_filter := CASE
    WHEN v_budget_remaining < v_pol.budget_remaining_floor OR v_max_cost < v_pol.budget_max_cost THEN 'budget'
    WHEN v_max_cost > v_pol.premium_max_cost THEN 'premium'
    ELSE 'standard'
  END;

  -- Build candidate list: join providers × models × benchmarks
  -- Ranking: bench-score weighted by cost preference; local providers boosted when allow_local=true.
  SELECT COALESCE(jsonb_agg(c.cand ORDER BY (c.cand->>'score')::numeric DESC), '[]'::jsonb)
  INTO v_candidates
  FROM (
    -- rank, do NOT truncate: the WHERE clause already bounds the set to serviceable ×
    -- available × capability-matched models — that filter IS the bound. An extra row cap
    -- on TOP of it silently drops the lowest-scored SERVICEABLE models, which is exactly
    -- the tail reResolveExcluding falls back to. When the filtered population exceeded the
    -- cap (e.g. 11 chat-capable candidates vs a LIMIT 10), a legitimately-resolvable model
    -- was hidden from EVERY candidates[] consumer — a false "no backend" that violates the
    -- no-fallback contract (fail loud only on a GENUINELY empty set). A predecessor fix
    -- (ef6409ba) corrected WHICH rows survived (order-before-limit); this removes the cap.
    SELECT _ranked.cand FROM (
    SELECT jsonb_build_object(
      'provider_slug',     p.slug,
      'provider_id',       p.id,
      'backend_kind',      p.backend_kind,
      'endpoint_url',      p.endpoint_url,
      'auth_env_var',      p.auth_env_var,
      'model_id',          r.model_id,
      'model_registry_id', r.id,
      -- Capacity + pricing of the RESOLVED model (no extra join — ai_model_registry r is
      -- already joined). The Omni /v1 lane clamps client max_tokens to max_output_tokens and
      -- derives a token-aware spend estimate from the pricing — both DYNAMIC, never hardcoded.
      -- NULL when the registry row lacks the data → the caller falls back to a config default.
      'max_output_tokens',  r.max_output_tokens,
      'context_window',     r.context_window,
      'input_price_per_m',  r.input_price_per_m,
      'output_price_per_m', r.output_price_per_m,
      'cost_class',        p.cost_class,
      'is_local',          (p.backend_kind IN ('local_ollama', 'local_vllm')),
      'supports_batch',    p.supports_batch,
      'use_batch',         (v_prefer_batch AND p.supports_batch),
      'strategy',          CASE WHEN v_prefer_batch AND p.supports_batch THEN 'batch' ELSE 'sync' END,
      'score',             ROUND(
        (
          COALESCE(b.overall_score, v_pol.default_bench) * v_pol.bench_weight
          + CASE WHEN p.backend_kind IN ('local_ollama','local_vllm') AND v_allow_local THEN v_pol.local_bonus ELSE 0.0 END
          + CASE WHEN p.cost_class = v_cost_class_filter THEN v_pol.cost_match_weight ELSE 0.0 END
          + CASE WHEN v_needs_tools AND r.is_function_calling THEN v_pol.tool_match_weight ELSE 0.0 END
          + CASE WHEN v_needs_vision AND r.is_vision THEN v_pol.vision_match_weight ELSE 0.0 END
        )::numeric, 4
      ),
      'reason', format(
        -- PostgreSQL format() supports only %s/%I/%L — NOT C-style %.2f. The old
        -- '%.2f' raised "unrecognized format() type specifier" on EVERY candidate,
        -- so the resolver always errored and openclaw_resolve_clow swallowed it →
        -- the hardcoded matrices were the de-facto path. Round + %s instead.
        'bench=%s local_bonus=%s cost_match=%s tool_match=%s vision_match=%s',
        round(COALESCE(b.overall_score, v_pol.default_bench), 2),
        (p.backend_kind IN ('local_ollama','local_vllm') AND v_allow_local),
        (p.cost_class = v_cost_class_filter),
        (v_needs_tools AND r.is_function_calling),
        (v_needs_vision AND r.is_vision)
      )
    ) AS cand
    FROM public.ai_provider_registry p
    JOIN public.ai_model_registry r
      ON COALESCE(r.provider_registry_id, NULL) = p.id
      OR r.provider = p.slug                         -- fallback for unmigrated rows
    LEFT JOIN public.ai_model_benchmarks b
      ON b.model_registry_id = r.id AND b.task_type = v_task_kind
    WHERE p.is_enabled
      AND p.last_health_status = ANY(v_pol.health_allow_set)
      AND r.is_available AND NOT r.is_deprecated
      -- RAG brick 1a: task-kind ⇄ embedding-capability gate (symmetric with the
      -- is_function_calling / is_vision filters below — capability-derived, never an
      -- allow-list). An embedding task MUST resolve to an embedding model; a non-embedding
      -- task must NOT pick an embedding-only model (they are not chat-capable). Without
      -- this, resolveRagBackend('rag.embedding') ranked CHAT models for an embedding task.
      AND (v_task_kind <> 'embedding' OR r.is_embedding)
      AND (v_task_kind =  'embedding' OR NOT r.is_embedding)
      -- Symmetric chat-capability gate (capability-derived from the model id at discovery
      -- via deriveModelCaps, NEVER an allow-list): a GENERATIVE (non-embedding) task MUST
      -- resolve to a chat-capable model. Without it, non-chat AND non-embedding models
      -- (tts/whisper/dall-e/moderation/realtime/audio — is_chat_capable=false) leaked into
      -- chat resolution, because only the embedding gate above existed. Proved live on the
      -- local stack: gpt-4o-mini forced is_chat_capable=false still ranked for a chat task
      -- until this gate landed.
      AND (v_task_kind = 'embedding' OR r.is_chat_capable)
      -- Moderation: exclude an admin-REJECTED model, unless an admin explicitly
      -- force-activated it (is_admin_active). NOT a sole is_admin_active gate — that
      -- DEFAULTs false (the seed never sets it) so requiring it would exclude every
      -- model; a discovered/pending model stays resolvable (auto-setup).
      AND (r.eval_status <> 'rejected' OR r.is_admin_active)
      AND (NOT v_needs_tools OR r.is_function_calling)
      AND (NOT v_needs_vision OR r.is_vision)
      AND (NOT v_prefer_batch OR p.supports_batch)
      -- allow_local=false hard-excludes LOCAL backends (discovery §6 invariant).
      AND (v_allow_local OR p.backend_kind NOT IN ('local_ollama','local_vllm'))
      -- §11 residency hard-filter (ORTHOGONAL to the local opt-out above): when
      -- clow.cloud_forbidden=true (set by detectDataSensitivity at confidential) ONLY
      -- on-prem backends are eligible, so cloud (direct_cloud/llm_gateway) reaches ZERO
      -- invocations. Expressed as a POSITIVE local-allow rather than a llm_gateway
      -- blacklist, so when cloud IS permitted (cloud_forbidden=false) the gateway stays
      -- a first-class peer (llm-gateway resolver-contract: never blacklist the gateway).
      AND (NOT v_cloud_forbidden OR p.backend_kind IN ('local_ollama','local_vllm'))
      -- Only providers serviceable by the caller (key present). Not a roster — the
      -- array IS the live runtime key truth; empty = unconstrained.
      AND (cardinality(v_serviceable) = 0 OR p.slug = ANY(v_serviceable))
      -- §19.4 per-instance scoping: SECURITY DEFINER bypasses RLS, so tenant-filter
      -- candidates EXPLICITLY here — base/global (NULL) or the caller's own instance.
      AND (p.scoped_to_instance_id IS NULL OR p.scoped_to_instance_id = v_instance_id)
    ) _ranked
    ORDER BY (_ranked.cand->>'score')::numeric DESC
  ) c;

  -- Top candidate
  v_top := COALESCE(v_candidates->0, NULL);

  IF v_top IS NULL THEN
    v_reasoning := format(
      'No backend matched: task_kind=%s, capability_tags=%s, batch_pref=%s, cost_class=%s, allow_local=%s, needs_tools=%s, needs_vision=%s',
      v_task_kind, array_to_string(v_capability_tags, ','),
      v_prefer_batch, v_cost_class_filter, v_allow_local, v_needs_tools, v_needs_vision
    );

    -- No substitution: an empty derived set is a real "no capable + available +
    -- serviceable provider" condition the caller must surface (fail loud), not mask.
    RETURN jsonb_build_object(
      'resolved', false,
      'reasoning', v_reasoning,
      'candidates', v_candidates
    );
  END IF;

  v_reasoning := format(
    'Picked %s/%s (score=%s, strategy=%s) — %s',
    v_top->>'provider_slug', v_top->>'model_id',
    v_top->>'score', v_top->>'strategy', v_top->>'reason'
  );

  RETURN jsonb_build_object(
    'resolved', true,
    'top', v_top,
    'candidates', v_candidates,
    'reasoning', v_reasoning,
    'inputs', jsonb_build_object(
      'task_kind', v_task_kind,
      'expected_tokens', v_expected_tokens,
      'deadline_hours', v_deadline_hours,
      'max_cost', v_max_cost,
      'prefer_batch', v_prefer_batch,
      'cost_class_filter', v_cost_class_filter,
      'allow_local', v_allow_local,
      -- The ACTIVE operator-tunable policy that produced this decision (the lens persisted by
      -- fn_record_execution_decision: which weights/thresholds were live + which row id).
      'policy', jsonb_build_object(
        'id', v_pol.id, 'scope_type', v_pol.scope_type,
        'bench_weight', v_pol.bench_weight, 'local_bonus', v_pol.local_bonus,
        'cost_match_weight', v_pol.cost_match_weight, 'tool_match_weight', v_pol.tool_match_weight,
        'vision_match_weight', v_pol.vision_match_weight,
        'budget_remaining_floor', v_pol.budget_remaining_floor,
        'budget_max_cost', v_pol.budget_max_cost, 'premium_max_cost', v_pol.premium_max_cost,
        'batch_min_deadline_hours', v_pol.batch_min_deadline_hours, 'batch_min_tokens', v_pol.batch_min_tokens,
        'health_allow_set', to_jsonb(v_pol.health_allow_set)
      )
    )
  );
END;
$$;

COMMENT ON FUNCTION public.aisha_resolve_clow_backend(jsonb, jsonb) IS
  'Per-clow backend resolver. Ranks providers × models for a specific sub-agent task. '
  'STABLE; returns ranked candidates + top pick + transparent reasoning. '
  'Caller is OpenClaw bridge route (TS layer) which then dispatches the clow with the resolved backend.';

REVOKE ALL ON FUNCTION public.aisha_resolve_clow_backend(jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aisha_resolve_clow_backend(jsonb, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aisha_resolve_clow_backend(jsonb, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_test_mcp_server.sql
-- -----------------------------------------------------------------------------

-- Function: aisha_test_mcp_server
-- Two-step pattern: records a test-attempt audit + returns a probe payload.
-- The TS layer (svc-ai-chat /mcp/test route) actually performs the HTTP/stdio
-- probe and then calls aisha_record_mcp_test_result with the outcome.
--
-- Why two-step: same reason as aisha_request_plan_from_openclaw — keep HTTP
-- out of plpgsql to preserve STABLE semantics and avoid pool exhaustion.

CREATE OR REPLACE FUNCTION public.aisha_test_mcp_server(
  p_slug text,
  p_probe_method text DEFAULT 'tools/list'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_server  RECORD;
  v_user_id uuid;
  v_test_id uuid;
  v_payload jsonb;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_server
  FROM mcp_server_registry
  WHERE slug = p_slug;

  IF v_server IS NULL THEN
    RAISE EXCEPTION 'MCP server % not found in registry', p_slug;
  END IF;

  v_user_id := auth.uid();
  v_test_id := gen_random_uuid();

  v_payload := jsonb_build_object(
    'test_id', v_test_id,
    'mcp_server_id', v_server.id,
    'slug', v_server.slug,
    'transport', v_server.transport,
    'endpoint_url', v_server.endpoint_url,
    'stdio_command', to_jsonb(v_server.stdio_command),
    'auth_kind', v_server.auth_kind,
    'auth_env_var', v_server.auth_env_var,
    'probe_method', p_probe_method,
    'requested_at', now()
  );

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (v_user_id, 'mcp.test_requested', v_payload);

  RETURN jsonb_build_object(
    'test_id', v_test_id,
    'slug', p_slug,
    'status', 'queued',
    'payload', v_payload,
    'message', 'Test request audited; caller invokes /mcp/test on svc-ai-chat with this payload.'
  );
END;
$$;

COMMENT ON FUNCTION public.aisha_test_mcp_server(text, text) IS
  'Audits an MCP server test request. Caller (svc-ai-chat) performs the probe and writes result via aisha_record_mcp_test_result.';

REVOKE ALL ON FUNCTION public.aisha_test_mcp_server(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aisha_test_mcp_server(text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aisha_test_mcp_server(text, text) TO service_role;


