-- File: aisha/db/sql/functions/aisha_vault_encryption_key.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: aisha_vault_encryption_key
--
-- Klíč pgp_sym trezoru (vault.secrets). Hodnotu doručuje trezor instance
-- (VAULT_ENCRYPTION_KEY v env služby db) — NIKDY v repu.
--
-- ⛔ KLÍČ NENÍ GUC. Dřív ho nesl `ALTER DATABASE postgres SET
-- app.settings.vault_encryption_key`, PGOPTIONS služby db a PostgREST
-- `PGRST_APP_SETTINGS_VAULT_ENCRYPTION_KEY` (ten ho vkládal do KAŽDÉHO
-- požadavku). NAMĚŘENO 2026-09-25: četla ho každá role včetně anon přes /rpc.
--
-- ✅ Teď stejně jako aisha_column_encryption_key(): soubor
-- /run/aisha-keys/vault_encryption.key (entrypoint-wrapper.sh), čte jen
-- vlastník — tj. vault.create_secret/update_secret a SECURITY DEFINER
-- spotřebitelé pohledu vault.decrypted_secrets. Žádný GRANT.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.aisha_vault_encryption_key()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $$
DECLARE
  v_key text;
BEGIN
  BEGIN
    -- Bez ořezu: hodnota musí být BAJTOVĚ táž jako dřív v GUC (jinak starý
    -- šifrový text nejde otevřít); zapisovatel píše printf '%s', bez konce řádku.
    v_key := pg_read_file('/run/aisha-keys/vault_encryption.key');
  EXCEPTION
    WHEN undefined_file THEN
      RAISE EXCEPTION 'AISHA_VAULT_KEY_MISSING_OR_WEAK'
        USING DETAIL = 'Soubor /run/aisha-keys/vault_encryption.key neexistuje.',
              HINT = 'Zapisuje ho infra/postgres/entrypoint-wrapper.sh z VAULT_ENCRYPTION_KEY při startu služby db.';
  END;
  -- Jen prázdnota, ne délka: dřívější čtení z GUC délku neověřovalo a instance
  -- se starším (kratším) klíčem nesmí po změně DORUČENÍ přijít o trezor.
  IF v_key IS NULL OR v_key = '' THEN
    RAISE EXCEPTION 'AISHA_VAULT_KEY_MISSING_OR_WEAK';
  END IF;
  RETURN v_key;
END;
$$;
REVOKE ALL ON FUNCTION public.aisha_vault_encryption_key() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.aisha_vault_encryption_key() FROM anon, authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/append_flowboard_run_entry_service.sql
-- -----------------------------------------------------------------------------

-- Function: public.append_flowboard_run_entry_service
-- Per-node Flowboard run provenance from the n8n engine. The n8n execution callback
-- (svc-ai-chat /flowboard-n8n-callback) calls this per executed node to append an
-- automation_step story_entry — the SAME iconographic StoryLoop timeline as the sandbox
-- engine, just written from a service context (n8n carries no auth.uid()).
--
-- Mirrors append_inbound_comm_entry_audited (service-role-only story_entries writer) but
-- for flowboard run steps: owner-attributed (created_by = the flow owner, validated) and
-- idempotent by (run_id, node_id) so an n8n callback retry never double-writes.
--
-- Security: SECURITY DEFINER, service_role ONLY. @audit: required
CREATE OR REPLACE FUNCTION public.append_flowboard_run_entry_service(
  p_story_id   uuid,
  p_owner_id   uuid,
  p_run_id     text,
  p_node_id    text,
  p_entry_type text,
  p_content    text,
  p_metadata   jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_existing uuid;
  v_entry_id uuid;
BEGIN
  -- service-role only: the n8n execution callback carries no auth.uid().
  IF current_setting('role', true) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'append_flowboard_run_entry_service is service-role only' USING ERRCODE = '42501';
  END IF;
  -- defense in depth: the owner must really own the run's story.
  IF NOT EXISTS (SELECT 1 FROM public.partner_stories WHERE id = p_story_id AND user_id = p_owner_id) THEN
    RAISE EXCEPTION 'owner % does not own story %', p_owner_id, p_story_id USING ERRCODE = '42501';
  END IF;
  -- idempotency: same (run_id, node_id) already recorded → return it (callback retry-safe).
  SELECT id INTO v_existing
    FROM public.story_entries
   WHERE story_id = p_story_id
     AND entry_type = p_entry_type
     AND metadata->'flowboard'->>'runId' = p_run_id
     AND metadata->'flowboard'->>'nodeId' = p_node_id
   LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('entry_id', v_existing, 'deduped', true);
  END IF;

  INSERT INTO public.story_entries (story_id, entry_type, content, metadata, is_internal, created_by)
  VALUES (p_story_id, p_entry_type, p_content, COALESCE(p_metadata, '{}'::jsonb), false, p_owner_id)
  RETURNING id INTO v_entry_id;

  UPDATE public.partner_stories SET last_activity_at = now() WHERE id = p_story_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (p_owner_id, 'FLOWBOARD_N8N_STEP',
    jsonb_build_object('area','flowboard','severity','info','entity_type','story_entries',
      'entity_id',v_entry_id,'story_id',p_story_id,'run_id',p_run_id,'node_id',p_node_id));

  RETURN jsonb_build_object('entry_id', v_entry_id, 'deduped', false);
END;
$function$;

REVOKE ALL ON FUNCTION public.append_flowboard_run_entry_service(uuid, uuid, text, text, text, text, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.append_flowboard_run_entry_service(uuid, uuid, text, text, text, text, jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.append_flowboard_run_entry_service(uuid, uuid, text, text, text, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/append_inbound_comm_entry_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.append_inbound_comm_entry_audited
-- Generic inbound-communication ingest primitive. Appends an externally-received
-- message (email, chat, webhook, ...) onto a RESOLVED story as a system-provenance
-- story_entry. This is the service-role entry point that inbound adapters / n8n call
-- AFTER resolving the target story (via resolve_story_from_* or the stack default
-- inbox story).
--
-- Why a new function: create_story_entry_audited is auth.uid()-gated (cannot run for a
-- system-initiated message) and add_system_timeline_entry is restricted to a fixed
-- system-type allow-list on the user's PRIMARY story only. This fills that gap with
-- created_by = NULL (system) provenance + idempotent dedup by (channel, external_id).
--
-- Composes with promote_entry_to_story_audited: an inbound item lands as an entry in
-- the resolved/inbox story and can later be branched into its own child story —
-- "co email to story, pokud to není email zařazený do existující story".
--
-- Security: SECURITY DEFINER, service_role ONLY (bypasses story-ownership checks).
-- @audit: required

CREATE OR REPLACE FUNCTION public.append_inbound_comm_entry_audited(
  p_story_id        uuid,
  p_channel         text,
  p_external_id     text,
  p_from            text DEFAULT NULL::text,
  p_subject         text DEFAULT NULL::text,
  p_body            text DEFAULT NULL::text,
  p_parent_entry_id uuid DEFAULT NULL::uuid,
  p_metadata        jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_entry_type text;
  v_existing   uuid;
  v_entry_id   uuid;
BEGIN
  -- System ingestion path: service_role only. Inbound messages carry no auth.uid().
  IF current_setting('role', true) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'append_inbound_comm_entry_audited is service-role only' USING ERRCODE = '42501';
  END IF;

  IF p_channel IS NULL OR btrim(p_channel) = '' THEN
    RAISE EXCEPTION 'p_channel is required' USING ERRCODE = '22023';
  END IF;
  IF p_external_id IS NULL OR btrim(p_external_id) = '' THEN
    RAISE EXCEPTION 'p_external_id is required (idempotency key)' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.partner_stories WHERE id = p_story_id) THEN
    RAISE EXCEPTION 'Target story not found: %', p_story_id USING ERRCODE = '22023';
  END IF;

  v_entry_type := 'inbound_' || lower(p_channel);

  -- Idempotency: same provider message already ingested → return the existing entry.
  SELECT id INTO v_existing
    FROM public.story_entries
   WHERE entry_type = v_entry_type
     AND metadata->>'external_id' = p_external_id
   LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('entry_id', v_existing, 'story_id', p_story_id, 'deduped', true);
  END IF;

  -- Explicit envelope fields are authoritative (merged last so they win over p_metadata).
  INSERT INTO public.story_entries (
    story_id, parent_id, entry_type, content, metadata, is_internal, created_by
  ) VALUES (
    p_story_id, p_parent_entry_id, v_entry_type, p_body,
    COALESCE(p_metadata, '{}'::jsonb)
      || jsonb_build_object(
           'channel',     lower(p_channel),
           'external_id', p_external_id,
           'from',        p_from,
           'subject',     p_subject,
           'is_system',   true
         ),
    false,   -- visible to partner; not internal
    NULL     -- system provenance
  )
  RETURNING id INTO v_entry_id;

  UPDATE public.partner_stories SET last_activity_at = now() WHERE id = p_story_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (NULL, 'COMM_INBOUND_ENTRY',
    jsonb_build_object(
      'area',        'communication',
      'severity',    'info',
      'entity_type', 'story_entries',
      'entity_id',   v_entry_id,
      'story_id',    p_story_id,
      'channel',     lower(p_channel),
      'external_id', p_external_id));

  RETURN jsonb_build_object('entry_id', v_entry_id, 'story_id', p_story_id, 'deduped', false);
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.append_inbound_comm_entry_audited(uuid, text, text, text, text, text, uuid, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.append_inbound_comm_entry_audited(uuid, text, text, text, text, text, uuid, jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.append_inbound_comm_entry_audited(uuid, text, text, text, text, text, uuid, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/append_subject_entry_service.sql
-- -----------------------------------------------------------------------------

-- Function: public.append_subject_entry_service
-- Arguments: p_subject_type text, p_subject_id uuid, p_entry_type text, p_content text,
--            p_metadata jsonb, p_created_by uuid, p_story_id uuid, p_is_internal boolean,
--            p_occurred_at timestamptz
-- Description: The single privileged writer of a TYPED RECORD onto a subject's
--              timeline (the polymorphic story_entries axis). Every doctrine
--              statement of the form "work with a twin leaves a typed record in
--              its story" funnels through here, so attribution and shape are
--              decided in one place instead of in each caller.
-- Security: SECURITY DEFINER, service_role only. This function performs NO
--           authorization of its own — it is an internal primitive, and the
--           CALLING RPC is responsible for deciding who may write to which
--           subject. That is why it is REVOKEd from authenticated: exposed
--           directly it would be an entry-forgery tool, the same reason
--           write_audit_journal was revoked from authenticated (2026-07-15).

CREATE OR REPLACE FUNCTION public.append_subject_entry_service(
  p_subject_type text,
  p_subject_id uuid,
  p_entry_type text,
  p_content text DEFAULT NULL,
  p_metadata jsonb DEFAULT '{}'::jsonb,
  p_created_by uuid DEFAULT NULL,
  p_story_id uuid DEFAULT NULL,
  p_is_internal boolean DEFAULT false,
  p_occurred_at timestamptz DEFAULT now()
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_entry_id uuid;
BEGIN
  IF p_subject_type IS NULL OR btrim(p_subject_type) = '' THEN
    RAISE EXCEPTION 'subject_type is required' USING ERRCODE = '22023';
  END IF;
  IF p_subject_id IS NULL THEN
    RAISE EXCEPTION 'subject_id is required' USING ERRCODE = '22023';
  END IF;
  IF p_entry_type IS NULL OR btrim(p_entry_type) = '' THEN
    RAISE EXCEPTION 'entry_type is required' USING ERRCODE = '22023';
  END IF;

  -- story_id stays the legacy binding: set it only for the 'story' axis, where
  -- the FK to partner_stories can actually hold. For every other kind the
  -- polymorphic pair is the whole address.
  INSERT INTO public.story_entries (
    story_id, subject_type, subject_id, entry_type, content, metadata,
    is_internal, created_by, occurred_at
  ) VALUES (
    CASE WHEN p_subject_type = 'story' THEN COALESCE(p_story_id, p_subject_id) ELSE p_story_id END,
    p_subject_type,
    p_subject_id,
    p_entry_type,
    p_content,
    COALESCE(p_metadata, '{}'::jsonb),
    COALESCE(p_is_internal, false),
    p_created_by,
    COALESCE(p_occurred_at, now())
  )
  RETURNING id INTO v_entry_id;

  RETURN v_entry_id;
END;
$function$
;

-- Permissions — internal primitive: never reachable from a member session.
REVOKE ALL ON FUNCTION public.append_subject_entry_service(text, uuid, text, text, jsonb, uuid, uuid, boolean, timestamptz) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.append_subject_entry_service(text, uuid, text, text, jsonb, uuid, uuid, boolean, timestamptz) FROM anon;
REVOKE ALL ON FUNCTION public.append_subject_entry_service(text, uuid, text, text, jsonb, uuid, uuid, boolean, timestamptz) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.append_subject_entry_service(text, uuid, text, text, jsonb, uuid, uuid, boolean, timestamptz) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/apply_as_study_consultant.sql
-- -----------------------------------------------------------------------------

-- Function: public.apply_as_study_consultant
-- Arguments: p_study_id uuid, p_role text, p_notes text
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:25:51+01:00

CREATE OR REPLACE FUNCTION public.apply_as_study_consultant(p_study_id uuid, p_role text DEFAULT 'consultant'::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_user_id UUID;
  v_partner_id UUID;
  v_result JSONB;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT id INTO v_partner_id FROM partner_profiles WHERE user_id = v_user_id;
  IF v_partner_id IS NULL THEN
    RAISE EXCEPTION 'Partner profile not found';
  END IF;

  INSERT INTO study_consultants (study_id, partner_id, role, notes, status)
  VALUES (p_study_id, v_partner_id, p_role, p_notes, 'pending')
  RETURNING row_to_json(study_consultants)::jsonb INTO v_result;

  RETURN v_result;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.apply_as_study_consultant(p_study_id uuid, p_role text, p_notes text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.apply_as_study_consultant(p_study_id uuid, p_role text, p_notes text) FROM anon;
GRANT EXECUTE ON FUNCTION public.apply_as_study_consultant(p_study_id uuid, p_role text, p_notes text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/apply_as_study_consultant_full.sql
-- -----------------------------------------------------------------------------

-- Function: public.apply_as_study_consultant_full
-- Arguments: p_study_id uuid, p_partner_id uuid, p_role text, p_max_participants integer, p_notes text
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:25:52+01:00

CREATE OR REPLACE FUNCTION public.apply_as_study_consultant_full(p_study_id uuid, p_partner_id uuid, p_role text DEFAULT 'consultant'::text, p_max_participants integer DEFAULT NULL::integer, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_consultant_id uuid;
  v_partner_user_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  -- Verify the partner belongs to the current user
  SELECT user_id INTO v_partner_user_id
  FROM partner_profiles
  WHERE id = p_partner_id;
  
  IF v_partner_user_id IS NULL OR v_partner_user_id != v_user_id THEN
    RAISE EXCEPTION 'Unauthorized: Partner profile does not belong to current user';
  END IF;
  
  -- Check if application already exists
  SELECT id INTO v_consultant_id
  FROM study_consultants
  WHERE study_id = p_study_id AND partner_id = p_partner_id;
  
  IF v_consultant_id IS NOT NULL THEN
    -- Update existing application
    UPDATE study_consultants
    SET notes = COALESCE(p_notes, notes),
        max_participants = COALESCE(p_max_participants, max_participants),
        updated_at = NOW()
    WHERE id = v_consultant_id;
  ELSE
    -- Insert new application
    INSERT INTO study_consultants (study_id, partner_id, role, max_participants, notes, status)
    VALUES (p_study_id, p_partner_id, p_role::consultant_role_enum, p_max_participants, p_notes, 'pending')
    RETURNING id INTO v_consultant_id;
  END IF;
  
  RETURN v_consultant_id;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.apply_as_study_consultant_full(p_study_id uuid, p_partner_id uuid, p_role text, p_max_participants integer, p_notes text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.apply_as_study_consultant_full(p_study_id uuid, p_partner_id uuid, p_role text, p_max_participants integer, p_notes text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_audit_grants.sql
-- -----------------------------------------------------------------------------

-- Function: audience_audit_grants

CREATE OR REPLACE FUNCTION public.audience_audit_grants()
 RETURNS TABLE(severity text, invariant text, object_type text, object_name text, role_name text, problem text, fix_sql text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  -- Functions only the broker may write through (must NOT be reachable by
  -- `authenticated` or anon). Keep in sync with 20260524140000.
  v_broker_only TEXT[] := ARRAY[
    'audience_upsert_user_engagement',
    'audience_process_signal_audited',
    'audience_broker_record_sync'
  ];
  v_has_anon BOOLEAN := EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon');
  v_has_authd BOOLEAN := EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated');
  v_has_svc BOOLEAN := EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role');
  v_has_broker BOOLEAN := EXISTS (SELECT 1 FROM pg_roles WHERE rolname='svc_source_broker_writer');
BEGIN
  -- ── I1: PUBLIC EXECUTE on audience functions (incl. NULL acl = default) ──
  RETURN QUERY
  SELECT
    'CRITICAL', 'I1_public_execute', 'function',
    format('%s(%s)', p.proname, pg_get_function_identity_arguments(p.oid)),
    'PUBLIC',
    CASE WHEN p.proacl IS NULL
         THEN 'proacl IS NULL → Postgres default grants PUBLIC EXECUTE'
         ELSE 'explicit PUBLIC EXECUTE grant' END,
    format('REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM PUBLIC;',
           p.proname, pg_get_function_identity_arguments(p.oid))
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname='public' AND p.proname LIKE 'audience%'
    AND ( p.proacl IS NULL
          OR EXISTS (SELECT 1 FROM aclexplode(p.proacl) a
                     WHERE a.grantee = 0 AND a.privilege_type='EXECUTE') );

  -- ── I2: anon EXECUTE on audience functions ──────────────────────────────
  IF v_has_anon THEN
    RETURN QUERY
    SELECT
      'CRITICAL', 'I2_anon_execute', 'function',
      format('%s(%s)', p.proname, pg_get_function_identity_arguments(p.oid)),
      'anon', 'anon can EXECUTE (SECURITY DEFINER → RLS bypass)',
      format('REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM anon;',
             p.proname, pg_get_function_identity_arguments(p.oid))
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname='public' AND p.proname LIKE 'audience%'
      AND has_function_privilege('anon', p.oid, 'EXECUTE');
  END IF;

  -- ── I3: anon SELECT on audience views/tables + cohorts* ─────────────────
  IF v_has_anon THEN
    RETURN QUERY
    SELECT
      'CRITICAL', 'I3_anon_select', 'relation',
      g.table_name::text, 'anon',
      'anon can SELECT a privileged audience relation',
      format('REVOKE SELECT ON public.%I FROM anon;', g.table_name)
    FROM information_schema.role_table_grants g
    WHERE g.table_schema='public' AND g.grantee='anon' AND g.privilege_type='SELECT'
      AND (g.table_name LIKE 'audience%' OR g.table_name IN ('cohorts','cohort_arms'));
  END IF;

  -- ── I4: authenticated EXECUTE on broker-only write functions ────────────
  IF v_has_authd THEN
    RETURN QUERY
    SELECT
      'HIGH', 'I4_authd_broker_write', 'function',
      format('%s(%s)', p.proname, pg_get_function_identity_arguments(p.oid)),
      'authenticated',
      'logged-in marketer can EXECUTE a broker-only write function',
      format('REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM authenticated;',
             p.proname, pg_get_function_identity_arguments(p.oid))
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname='public' AND p.proname = ANY(v_broker_only)
      AND has_function_privilege('authenticated', p.oid, 'EXECUTE');
  END IF;

  -- ── I5: service_role MISSING EXECUTE on an audience function (under-grant)
  IF v_has_svc THEN
    RETURN QUERY
    SELECT
      'MEDIUM', 'I5_service_role_missing', 'function',
      format('%s(%s)', p.proname, pg_get_function_identity_arguments(p.oid)),
      'service_role', 'admin role lacks EXECUTE (audience admin path broken)',
      format('GRANT EXECUTE ON FUNCTION public.%I(%s) TO service_role;',
             p.proname, pg_get_function_identity_arguments(p.oid))
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname='public' AND p.proname LIKE 'audience%'
      AND NOT has_function_privilege('service_role', p.oid, 'EXECUTE');
  END IF;

  -- ── I6: broker writer MISSING EXECUTE on a broker-write fn (under-grant) ─
  IF v_has_broker THEN
    RETURN QUERY
    SELECT
      'MEDIUM', 'I6_broker_writer_missing', 'function',
      format('%s(%s)', p.proname, pg_get_function_identity_arguments(p.oid)),
      'svc_source_broker_writer', 'broker role lacks EXECUTE (sync broken)',
      format('GRANT EXECUTE ON FUNCTION public.%I(%s) TO svc_source_broker_writer;',
             p.proname, pg_get_function_identity_arguments(p.oid))
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname='public' AND p.proname = ANY(v_broker_only)
      AND NOT has_function_privilege('svc_source_broker_writer', p.oid, 'EXECUTE');
  END IF;
END;
$function$

;

REVOKE ALL ON FUNCTION audience_audit_grants() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_audit_grants() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_audit_to_story_entry.sql
-- -----------------------------------------------------------------------------

-- Function: audience_audit_to_story_entry

CREATE OR REPLACE FUNCTION public.audience_audit_to_story_entry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_story_id UUID;
  v_partner_id UUID;
BEGIN
  -- Only process CRM-relevant areas
  IF NEW.area NOT IN ('outreach', 'crm_ops', 'crm') THEN
    RETURN NEW;
  END IF;

  -- Skip if user_id missing (system events without actor context)
  IF NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Story-per-actor only applies to partner-tier contacts: partner_stories
  -- requires partner_id (NOT NULL FK → partner_profiles). For non-partner
  -- actors, skip the story promotion silently — the audit row already persisted;
  -- the story timeline is best-effort and must never break the audited op.
  SELECT id INTO v_partner_id FROM public.partner_profiles WHERE user_id = NEW.user_id LIMIT 1;
  IF v_partner_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Find or create partner_story for this user (title + partner_id are NOT NULL)
  SELECT id INTO v_story_id FROM public.partner_stories WHERE user_id = NEW.user_id LIMIT 1;
  IF v_story_id IS NULL THEN
    INSERT INTO public.partner_stories (partner_id, user_id, title, created_at, last_activity_at)
    VALUES (v_partner_id, NEW.user_id,
            'Audience timeline — ' || COALESCE((SELECT display_name FROM public.profiles WHERE user_id = NEW.user_id), NEW.user_id::text),
            now(), now())
    RETURNING id INTO v_story_id;
  ELSE
    UPDATE public.partner_stories SET last_activity_at = now() WHERE id = v_story_id;
  END IF;

  -- Insert story entry referencing the audit row
  INSERT INTO public.story_entries (story_id, entry_type, content, metadata, created_by, occurred_at)
  VALUES (
    v_story_id,
    'audit_event',
    NEW.summary,
    jsonb_build_object(
      'audit_id', NEW.id,
      'action_type', NEW.action_type,
      'action', NEW.action,
      'entity_type', NEW.entity_type,
      'area', NEW.area,
      'severity', NEW.severity
    ) || COALESCE(NEW.details, '{}'::jsonb),
    NEW.user_id,
    NEW.created_at
  );

  RETURN NEW;
END;
$function$

;

REVOKE ALL ON FUNCTION audience_audit_to_story_entry() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_audit_to_story_entry() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_autorevoke_public_execute.sql
-- -----------------------------------------------------------------------------

-- Function: audience_autorevoke_public_execute

CREATE OR REPLACE FUNCTION public.audience_autorevoke_public_execute()
 RETURNS event_trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  obj RECORD;
BEGIN
  FOR obj IN
    SELECT object_identity, schema_name, object_type
    FROM pg_event_trigger_ddl_commands()
  LOOP
    -- object_identity for a function is e.g. 'public.audience_foo(uuid, text)'.
    -- Match only public.audience_* functions; leave everything else untouched.
    IF obj.object_type = 'function'
       AND obj.schema_name = 'public'
       AND obj.object_identity LIKE 'public.audience\_%' THEN

      EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC', obj.object_identity);

      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
        EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM anon', obj.object_identity);
      END IF;

      RAISE NOTICE 'audience auto-lockdown: revoked PUBLIC/anon EXECUTE on %', obj.object_identity;
    END IF;
  END LOOP;
END;
$function$

;

REVOKE ALL ON FUNCTION audience_autorevoke_public_execute() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_autorevoke_public_execute() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_broker_record_sync.sql
-- -----------------------------------------------------------------------------

-- Function: audience_broker_record_sync

CREATE OR REPLACE FUNCTION public.audience_broker_record_sync(p_source_slug text, p_started_at timestamp with time zone, p_finished_at timestamp with time zone, p_ok boolean, p_error_message text DEFAULT NULL::text, p_recent_active integer DEFAULT 0, p_upserted integer DEFAULT 0, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS audience_broker_sync_state
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.audience_broker_sync_state;
BEGIN
  INSERT INTO public.audience_broker_sync_state AS s (
    source_slug, last_sync_started_at, last_sync_finished_at,
    last_success_at, last_error_at, last_error_message,
    consecutive_failures, total_syncs, total_failures,
    last_recent_active_count, last_upserted_count,
    metadata, updated_at
  )
  VALUES (
    p_source_slug, p_started_at, p_finished_at,
    CASE WHEN p_ok THEN p_finished_at ELSE NULL END,
    CASE WHEN p_ok THEN NULL ELSE p_finished_at END,
    p_error_message,
    CASE WHEN p_ok THEN 0 ELSE 1 END,
    1,
    CASE WHEN p_ok THEN 0 ELSE 1 END,
    p_recent_active, p_upserted,
    p_metadata, now()
  )
  ON CONFLICT (source_slug) DO UPDATE
    SET last_sync_started_at  = EXCLUDED.last_sync_started_at,
        last_sync_finished_at = EXCLUDED.last_sync_finished_at,
        last_success_at       = CASE WHEN p_ok THEN p_finished_at ELSE s.last_success_at END,
        last_error_at         = CASE WHEN p_ok THEN s.last_error_at ELSE p_finished_at END,
        last_error_message    = CASE WHEN p_ok THEN NULL ELSE p_error_message END,
        consecutive_failures  = CASE WHEN p_ok THEN 0 ELSE s.consecutive_failures + 1 END,
        total_syncs           = s.total_syncs + 1,
        total_failures        = s.total_failures + (CASE WHEN p_ok THEN 0 ELSE 1 END),
        last_recent_active_count = p_recent_active,
        last_upserted_count   = p_upserted,
        metadata              = p_metadata,
        updated_at            = now()
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$function$

;

REVOKE ALL ON FUNCTION audience_broker_record_sync(text,timestamp with time zone,timestamp with time zone,boolean,text,integer,integer,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_broker_record_sync(text,timestamp with time zone,timestamp with time zone,boolean,text,integer,integer,jsonb) TO authenticator;
GRANT EXECUTE ON FUNCTION audience_broker_record_sync(text,timestamp with time zone,timestamp with time zone,boolean,text,integer,integer,jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_compute_actor_tier.sql
-- -----------------------------------------------------------------------------

-- Function: audience_compute_actor_tier (Brick6 — UNGUARDED tier source of truth)
--
-- The pure tier label for a user (anonymous / registered / active / qualified / partner)
-- WITHOUT the audience_user_can_see_creator_stats privacy guard. A tier label gates content
-- but exposes no stats, so this is the single source of truth shared by:
--   - audience_derive_actor_tier(uuid)            — wraps this WITH the privacy guard (the
--                                                    public, stats-exposing path);
--   - audience_user_meets_tier_requirement(text, uuid) — the tier-ACL boolean gate (trusted
--                                                    internal callers that already pinned the
--                                                    actor, e.g. mcp_search_knowledge_v3).
-- service_role only — never call this where a privacy guard is required; use the guarded
-- audience_derive_actor_tier for that. A NULL p_user_id yields 'anonymous'.
CREATE OR REPLACE FUNCTION public.audience_compute_actor_tier(p_user_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    CASE
      WHEN p.user_id IS NULL THEN 'anonymous'
      WHEN pp.is_visible AND pp.is_production_provider THEN 'partner'
      WHEN pp.is_certified THEN 'qualified'
      WHEN COALESCE(ea.app_accesses_30d, 0) > 0 THEN 'active'
      ELSE 'registered'
    END
  FROM (SELECT p_user_id AS user_id) ids
  LEFT JOIN public.profiles p ON p.user_id = ids.user_id
  LEFT JOIN public.partner_profiles pp ON pp.user_id = ids.user_id
  LEFT JOIN public.audience_actor_aggregate_latest_v ea ON ea.user_id = ids.user_id;
$function$;

REVOKE ALL ON FUNCTION audience_compute_actor_tier(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_compute_actor_tier(uuid) TO service_role;


