-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_note_vectorize.sql
-- -----------------------------------------------------------------------------

-- Function: audience_note_vectorize

CREATE OR REPLACE FUNCTION public.audience_note_vectorize()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_user_id UUID;
BEGIN
  -- Only process actor_note entries
  IF NEW.entry_type NOT IN ('actor_note', 'audit_event') THEN
    RETURN NEW;
  END IF;

  -- Resolve actor (story owner)
  SELECT user_id INTO v_actor_user_id FROM public.partner_stories WHERE id = NEW.story_id;
  IF v_actor_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Nothing to vectorize without body text (knowledge_items.body_markdown is NOT NULL).
  IF NEW.content IS NULL OR length(trim(NEW.content)) = 0 THEN
    RETURN NEW;
  END IF;

  -- Insert into knowledge_items; svc-mcp-knowledge embedding pipeline picks it up.
  -- Mapped to the current knowledge_items schema: note text -> body_markdown, a
  -- derived title, item_type as the enum, and the former metadata fields routed to
  -- their real columns (story_id, author_id) + ai_context_tags. (The original
  -- back-ported body inserted non-existent content/metadata columns.)
  INSERT INTO public.knowledge_items (
    item_type,
    source_type,
    source_id,
    title,
    body_markdown,
    story_id,
    author_id,
    ai_context_tags
  ) VALUES (
    'domain_doc'::public.knowledge_item_type,
    CASE NEW.entry_type
      WHEN 'actor_note' THEN 'actor_overlay'
      WHEN 'audit_event' THEN 'audit_journal'
      ELSE 'story_entry'
    END,
    NEW.id,
    COALESCE(NULLIF(left(NEW.content, 120), ''), 'Story entry ' || NEW.id::text),
    NEW.content,
    NEW.story_id,
    v_actor_user_id,
    ARRAY[NEW.entry_type]
  )
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$function$

;

REVOKE ALL ON FUNCTION public.audience_note_vectorize() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.audience_note_vectorize() FROM authenticated;
GRANT EXECUTE ON FUNCTION public.audience_note_vectorize() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_process_signal_audited.sql
-- -----------------------------------------------------------------------------

-- Function: audience_process_signal_audited

CREATE OR REPLACE FUNCTION public.audience_process_signal_audited(p_event_id uuid, p_extra_tags text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event public.integration_events%ROWTYPE;
  v_rule public.signal_tag_rules%ROWTYPE;
  v_applied_tags TEXT[] := p_extra_tags;
  v_actor_id UUID;
BEGIN
  -- Load event
  SELECT * INTO v_event FROM public.integration_events WHERE id = p_event_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Event % not found', p_event_id;
  END IF;

  -- Resolve actor from event payload (heuristics)
  v_actor_id := COALESCE(
    (v_event.metadata->>'user_id')::uuid,
    (v_event.metadata->>'actor_user_id')::uuid,
    (v_event.metadata->>'profile_id')::uuid
  );

  -- Apply matching rules
  FOR v_rule IN
    SELECT tags FROM public.signal_tag_rules
    WHERE is_active = true
      AND v_event.event_type ~ event_type_pattern
      AND (source_pattern IS NULL OR v_event.event_source ~ source_pattern)
    ORDER BY priority ASC
  LOOP
    v_applied_tags := array_cat(v_applied_tags, v_rule.tags);
  END LOOP;

  -- Dedupe tags
  v_applied_tags := ARRAY(SELECT DISTINCT unnest(v_applied_tags));

  -- Apply as polymorphic tags on the actor (if resolved)
  IF v_actor_id IS NOT NULL AND array_length(v_applied_tags, 1) > 0 THEN
    INSERT INTO public.story_labels (label, resource_type, resource_id, story_id)
    SELECT tag, 'actor', v_actor_id, NULL
    FROM unnest(v_applied_tags) tag
    ON CONFLICT DO NOTHING;
  END IF;

  -- Audit
  PERFORM public.audience_log_event(
    'process',
    'process_signal',
    'integration_event',
    p_event_id,
    'Auto-tagged signal',
    jsonb_build_object('actor_id', v_actor_id, 'tags', v_applied_tags, 'rule_count', array_length(v_applied_tags, 1))
  );

  RETURN jsonb_build_object(
    'event_id', p_event_id,
    'actor_id', v_actor_id,
    'tags_applied', v_applied_tags,
    'tag_count', COALESCE(array_length(v_applied_tags, 1), 0)
  );
END;
$function$

;

REVOKE ALL ON FUNCTION audience_process_signal_audited(uuid,text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_process_signal_audited(uuid,text[]) TO authenticator;
GRANT EXECUTE ON FUNCTION audience_process_signal_audited(uuid,text[]) TO service_role;


