-- -----------------------------------------------------------------------------

-- Function: audit_revenue_payout
-- Trigger function for auditing revenue split payouts.

CREATE OR REPLACE FUNCTION audit_revenue_payout()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF OLD.payout_status IS DISTINCT FROM NEW.payout_status
     AND NEW.payout_status = 'paid' THEN
    -- user_id = auth.uid() (nullable): this trigger can fire under a service/system
    -- actor (auth.uid() NULL); the COALESCE fallback to '00000000-…0000' is not a
    -- real aisha_auth.users id → audit_journal_user_id_fkey violation that would
    -- abort the payout UPDATE. NULL is FK-safe.
    INSERT INTO audit_journal (user_id, action, metadata)
    VALUES (
      auth.uid(),
      'REVENUE_PAYOUT',
      jsonb_build_object(
        'area', 'marketplace',
        'severity', 'info',
        'entity_type', 'revenue_split',
        'entity_id', NEW.id,
        'amount', NEW.amount,
        'recipient_type', NEW.recipient_type::text
      )
    );
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION audit_revenue_payout() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audit_revenue_payout() TO authenticated;
GRANT EXECUTE ON FUNCTION audit_revenue_payout() TO service_role;



-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audit_role_changes.sql
-- -----------------------------------------------------------------------------

-- Function: public.audit_role_changes
-- Arguments: (none)
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:25:53+01:00

CREATE OR REPLACE FUNCTION public.audit_role_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Guard: audit_logs may not exist during initial bootstrap
  IF to_regclass('public.audit_logs') IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.audit_logs (
      user_id,
      action,
      table_name,
      record_id,
      new_values,
      ip_address
    ) VALUES (
      auth.uid(),
      'role_created',
      'roles',
      NEW.id,
      jsonb_build_object(
        'name', NEW.name,
        'is_admin', NEW.is_admin,
        'is_system', NEW.is_system
      ),
      NULL
    );
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.audit_logs (
      user_id,
      action,
      table_name,
      record_id,
      old_values,
      new_values,
      ip_address
    ) VALUES (
      auth.uid(),
      'role_updated',
      'roles',
      NEW.id,
      jsonb_build_object(
        'name', OLD.name,
        'is_admin', OLD.is_admin,
        'can_manage_users', OLD.can_manage_users
      ),
      jsonb_build_object(
        'name', NEW.name,
        'is_admin', NEW.is_admin,
        'can_manage_users', NEW.can_manage_users
      ),
      NULL
    );
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.audit_logs (
      user_id,
      action,
      table_name,
      record_id,
      old_values,
      ip_address
    ) VALUES (
      auth.uid(),
      'role_deleted',
      'roles',
      OLD.id,
      jsonb_build_object('name', OLD.name),
      NULL
    );
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.audit_role_changes() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.audit_role_changes() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/award_tokens.sql
-- -----------------------------------------------------------------------------

-- Function: public.award_tokens
-- Arguments: p_user_id uuid, p_token_type text, p_amount integer, p_reference_type text, p_reference_id uuid, p_description text
-- Description: Mints tokens onto a membership's ledger. PRIVILEGED PRIMITIVE — the CALLER is
--   trusted to have authorized the award; this function does NOT authorize it. Reachable only
--   by service_role and by in-DB SECURITY DEFINER callers. NOT callable from the browser.
-- Security: the GRANT is the authorization boundary, deliberately — there is no JWT guard here.
--   2026-07-15 IDOR fix (docs/security/IDOR_P_USER_ID_AUDIT_2026-07-15.md): this function was
--   GRANTed to `authenticated` with ZERO authorization logic, so any logged-in user could
--   POST /rest/v1/rpc/award_tokens {p_user_id:<self>, p_token_type:'governance', p_amount:1e8}
--   and mint unlimited voting weight; a NEGATIVE p_amount against a victim's uuid drained their
--   balance and forged a 'reward' row in their ledger. The only "guard" was
--   useAdminGuard.guardAdminMutation — CLIENT-side React, which enforces nothing in the DB.
--   Self-award IS the exploit, so a `p_user_id <> auth.uid()` guard cannot fix it: the CALLER
--   must be restricted instead — hence REVOKE, not a predicate.
--
--   WHY NO is_service_role()/is_admin_or_staff() GUARD HERE: SECURITY DEFINER swaps current_user,
--   NOT the JWT claims, so such a guard would still read the ORIGINAL caller's claims and would
--   reject the legitimate in-DB awarders that mint for an ordinary user — log_health_state_audited,
--   confirm_product_taken_audited and submit_health_document_analysis_audited all award auth.uid()
--   after verifying ownership. Those callers run as the OWNER, who keeps EXECUTE by virtue of
--   ownership (REVOKE ... FROM PUBLIC does not touch it), and each authorizes its own recipient:
--     - award_leaderboard_rewards      → is_admin_or_staff(), recipient from period data
--     - log_health_state_audited       → recipient = auth.uid(), ownership-verified
--     - confirm_product_taken_audited  → recipient = auth.uid(), ownership-verified
--     - submit_health_document_analysis_audited → recipient = auth.uid(), access-verified
--     - process_token_reward           → p_user_id = auth.uid() unless service_role/admin
--   ANY NEW CALLER MUST DO THE SAME. Re-granting this function to `authenticated`/`anon` reopens
--   the hole; idor-prevention.gate.test.ts fails the build if that happens.
-- @audit: none (the ledger row in token_transactions is the record; the caller is trusted)

CREATE OR REPLACE FUNCTION public.award_tokens(p_user_id uuid, p_token_type text, p_amount integer, p_reference_type text DEFAULT NULL::text, p_reference_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_membership_id uuid;
  v_current_balance integer := 0;
  v_new_balance integer;
  v_transaction_id uuid;
BEGIN
  -- Positive amounts only. `v_new_balance := v_current_balance + p_amount` below means a
  -- negative amount is a BALANCE DRAIN that also forges a 'reward' ledger row — a distinct
  -- bug from the missing authorization, closed here. Use a debit RPC to spend tokens.
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION USING MESSAGE = format('award_tokens amount must be positive, got: %s', p_amount), ERRCODE = '22023';
  END IF;

  -- Validate token type
  IF p_token_type NOT IN ('governance', 'impact', 'data', 'aisha') THEN
    RAISE EXCEPTION USING MESSAGE = format('Invalid token type: %s', p_token_type), ERRCODE = '22023';
  END IF;

  -- Get user's membership and current balance
  SELECT id,
    CASE p_token_type
      WHEN 'governance' THEN COALESCE(tokens_governance, 0)
      WHEN 'impact' THEN COALESCE(tokens_impact, 0)
      WHEN 'data' THEN COALESCE(tokens_data, 0)
      WHEN 'aisha' THEN COALESCE(tokens_aisha, 0)
    END
  INTO v_membership_id, v_current_balance
  FROM memberships
  WHERE user_id = p_user_id
  ORDER BY created_at DESC
  LIMIT 1;

  -- Create membership if it doesn't exist
  IF v_membership_id IS NULL THEN
    INSERT INTO memberships (user_id, tier, status, payment_type)
    VALUES (p_user_id, 'basic', 'active', 'one_time')
    RETURNING id INTO v_membership_id;
    v_current_balance := 0;
  END IF;

  -- Calculate new balance
  v_new_balance := v_current_balance + p_amount;

  -- Update membership balance
  IF p_token_type = 'governance' THEN
    UPDATE memberships SET tokens_governance = v_new_balance WHERE id = v_membership_id;
  ELSIF p_token_type = 'impact' THEN
    UPDATE memberships SET tokens_impact = v_new_balance WHERE id = v_membership_id;
  ELSIF p_token_type = 'data' THEN
    UPDATE memberships SET tokens_data = v_new_balance WHERE id = v_membership_id;
  ELSIF p_token_type = 'aisha' THEN
    UPDATE memberships SET tokens_aisha = v_new_balance WHERE id = v_membership_id;
  END IF;

  -- Record transaction
  INSERT INTO token_transactions (
    user_id,
    token_type,
    transaction_type,
    amount,
    balance_after,
    reference_type,
    reference_id,
    description
  ) VALUES (
    p_user_id,
    p_token_type,
    'reward',
    p_amount,
    v_new_balance,
    p_reference_type,
    p_reference_id,
    p_description
  ) RETURNING id INTO v_transaction_id;

  RETURN jsonb_build_object(
    'success', true,
    'transaction_id', v_transaction_id,
    'previous_balance', v_current_balance,
    'new_balance', v_new_balance,
    'amount_awarded', p_amount
  );
END;
$function$
;

-- Permissions
-- service_role ONLY. The `authenticated` grant was the IDOR: PostgREST exposes every public
-- function, the gateway /rest/v1/* is a blanket proxy with no RPC allowlist, and
-- buildPostgrestClaims() hands every valid Keycloak token role=authenticated — so the grant
-- alone made this reachable by any logged-in user. Admin token-award goes through
-- award_tokens_admin_audited (which checks is_admin_or_staff IN THE DB, not in React).
REVOKE ALL ON FUNCTION public.award_tokens(p_user_id uuid, p_token_type text, p_amount integer, p_reference_type text, p_reference_id uuid, p_description text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.award_tokens(p_user_id uuid, p_token_type text, p_amount integer, p_reference_type text, p_reference_id uuid, p_description text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/backfill_user_streaks.sql
-- -----------------------------------------------------------------------------

-- Function: public.backfill_user_streaks
-- Arguments: (none)
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:25:53+01:00

CREATE OR REPLACE FUNCTION public.backfill_user_streaks()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user RECORD;
  v_updated INTEGER := 0;
  v_current_streak INTEGER;
  v_best_streak INTEGER;
  v_last_activity DATE;
BEGIN
  FOR v_user IN
    SELECT DISTINCT user_id FROM token_allocations WHERE balance > 0
  LOOP
    -- Calculate current streak
    WITH daily_activity AS (
      SELECT DISTINCT DATE(completed_at) as activity_date
      FROM reminder_completions
      WHERE user_id = v_user.user_id
      UNION
      SELECT DISTINCT check_in_date
      FROM health_check_ins
      WHERE user_id = v_user.user_id
    ),
    streak_groups AS (
      SELECT
        activity_date,
        activity_date - (ROW_NUMBER() OVER (ORDER BY activity_date) * INTERVAL '1 day')::DATE as grp
      FROM daily_activity
    ),
    streak_lengths AS (
      SELECT grp, COUNT(*) as length, MAX(activity_date) as last_date
      FROM streak_groups
      GROUP BY grp
    )
    SELECT
      COALESCE(
        (SELECT length FROM streak_lengths WHERE last_date >= CURRENT_DATE - 1 ORDER BY last_date DESC LIMIT 1),
        0
      ),
      COALESCE(MAX(length), 0),
      MAX(last_date)
    INTO v_current_streak, v_best_streak, v_last_activity
    FROM streak_lengths;

    -- Update user
    UPDATE token_allocations
    SET
      current_streak = v_current_streak,
      best_streak = v_best_streak,
      last_activity_date = v_last_activity
    WHERE user_id = v_user.user_id;

    v_updated := v_updated + 1;
  END LOOP;

  RETURN v_updated;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.backfill_user_streaks() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.backfill_user_streaks() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/build_guidance_contract.sql
-- -----------------------------------------------------------------------------

-- Function: build_guidance_contract
-- Maps expertise_level enum to a rich guidance contract JSONB.
-- Used by moderate_development_flow and other moderation functions.
-- beginner = Educating (senior decision-support),
-- intermediate = Collaborative, advanced = Autonomous, expert = Supervisory.

CREATE OR REPLACE FUNCTION public.build_guidance_contract(p_expertise_level text DEFAULT 'intermediate'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  RETURN CASE p_expertise_level

    -- "Educating" — senior decision-support for users who cannot maintain
    -- full project context on their own. Dirigent holds the systemic view,
    -- frames decisions, explains trade-offs, surfaces failure modes, and
    -- asks confirming questions before high-impact changes.
    WHEN 'beginner' THEN jsonb_build_object(
      'level', 'beginner',
      'guidance_mode', 'educating',
      'label', 'Educating',
      'decision_support_level', 'full',
      'context_retention_support', true,
      'ask_for_missing_constraints', true,
      'explain_tradeoffs', true,
      'surface_failure_modes', true,
      'confirm_before_high_impact', true,
      'teaching_depth', 'deep',
      'verbosity', 'detailed_with_examples',
      'explain_why', true,
      'show_alternatives', true,
      'code_examples', true,
      'expected_response_sections', jsonb_build_array(
        'decision_frame',
        'context_summary',
        'tradeoffs',
        'failure_modes',
        'recommendation',
        'verification_checkpoint'
      )
    )

    -- "Collaborative" — balanced guidance for users who understand the
    -- project but benefit from structured recommendations and occasional
    -- context reminders.
    WHEN 'intermediate' THEN jsonb_build_object(
      'level', 'intermediate',
      'guidance_mode', 'collaborative',
      'label', 'Collaborative',
      'decision_support_level', 'moderate',
      'context_retention_support', false,
      'ask_for_missing_constraints', true,
      'explain_tradeoffs', true,
      'surface_failure_modes', false,
      'confirm_before_high_impact', true,
      'teaching_depth', 'standard',
      'verbosity', 'standard',
      'explain_why', true,
      'show_alternatives', false,
      'code_examples', true,
      'expected_response_sections', jsonb_build_array(
        'recommendation',
        'tradeoffs',
        'verification_checkpoint'
      )
    )

    -- "Autonomous" — concise pattern-focused guidance for experienced users
    -- who need Dirigent mainly as a second pair of eyes.
    WHEN 'advanced' THEN jsonb_build_object(
      'level', 'advanced',
      'guidance_mode', 'autonomous',
      'label', 'Autonomous',
      'decision_support_level', 'light',
      'context_retention_support', false,
      'ask_for_missing_constraints', false,
      'explain_tradeoffs', false,
      'surface_failure_modes', false,
      'confirm_before_high_impact', false,
      'teaching_depth', 'concise',
      'verbosity', 'concise',
      'explain_why', false,
      'show_alternatives', true,
      'code_examples', false,
      'expected_response_sections', jsonb_build_array(
        'recommendation'
      )
    )

    -- "Supervisory" — minimal output; the user drives, Dirigent intervenes
    -- only for exceptions, compliance violations, and security concerns.
    WHEN 'expert' THEN jsonb_build_object(
      'level', 'expert',
      'guidance_mode', 'supervisory',
      'label', 'Supervisory',
      'decision_support_level', 'minimal',
      'context_retention_support', false,
      'ask_for_missing_constraints', false,
      'explain_tradeoffs', false,
      'surface_failure_modes', false,
      'confirm_before_high_impact', false,
      'teaching_depth', 'minimal',
      'verbosity', 'minimal',
      'explain_why', false,
      'show_alternatives', false,
      'code_examples', false,
      'expected_response_sections', jsonb_build_array(
        'recommendation'
      )
    )

    -- Fallback to collaborative
    ELSE jsonb_build_object(
      'level', p_expertise_level,
      'guidance_mode', 'collaborative',
      'label', 'Collaborative',
      'decision_support_level', 'moderate',
      'context_retention_support', false,
      'ask_for_missing_constraints', true,
      'explain_tradeoffs', true,
      'surface_failure_modes', false,
      'confirm_before_high_impact', true,
      'teaching_depth', 'standard',
      'verbosity', 'standard',
      'explain_why', true,
      'show_alternatives', false,
      'code_examples', true,
      'expected_response_sections', jsonb_build_array(
        'recommendation',
        'tradeoffs',
        'verification_checkpoint'
      )
    )
  END;
END;
$function$;

REVOKE ALL ON FUNCTION public.build_guidance_contract(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.build_guidance_contract(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.build_guidance_contract(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/calculate_domain_scores.sql
-- -----------------------------------------------------------------------------

-- Function: public.calculate_domain_scores
-- Description: Calculate domain scores from responses JSONB for Longevity Score
-- Security: STABLE (no DEFINER needed - helper function)
-- Related: Part of Longevity Score calculation system
-- Note: This file also defines custom types used by longevity score functions

-- ============================================================================
-- Type: longevity_domain_score
-- ============================================================================
DROP TYPE IF EXISTS public.longevity_domain_score CASCADE;

CREATE TYPE public.longevity_domain_score AS (
  domain_code TEXT,
  domain_name_key TEXT,
  questions_answered INTEGER,
  raw_score NUMERIC,
  max_possible NUMERIC,
  percentage NUMERIC  -- 0-100
);

COMMENT ON TYPE public.longevity_domain_score IS 'Domain score result for Longevity Score (CLS) calculation';

-- ============================================================================
-- Type: longevity_score_result
-- ============================================================================
DROP TYPE IF EXISTS public.longevity_score_result CASCADE;

CREATE TYPE public.longevity_score_result AS (
  response_id UUID,
  user_id UUID,
  completed_at TIMESTAMPTZ,
  cls_score NUMERIC,           -- Celkový Longevity Score (0-100)
  domain_scores JSONB,         -- Array of domain scores
  trend_vs_baseline NUMERIC,   -- Difference from baseline (NULL if first)
  trend_direction TEXT         -- 'improving', 'stable', 'declining'
);

COMMENT ON TYPE public.longevity_score_result IS 'Complete Longevity Score (CLS) result with trend information';

-- ============================================================================
-- Function: calculate_domain_scores
-- Spec: "DOTAZNÍK – SUBJEKTIVNÍ HODNOCENÍ ÚČASTNÍKA" (28 items, 10 domains A-J + pain)
-- Domains aligned with seed STEP 15 scoring_domain values.
-- Scale: 0-10 per question. Reversed questions already oriented 0=bad,10=good by UI.
-- change_perception (section J) is optional (from 2nd measurement) — NULL percentage
-- when unanswered is naturally excluded from CLS average.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.calculate_domain_scores(
  p_responses JSONB
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  v_domains JSONB := '[]'::JSONB;
  v_domain_keys TEXT[] := ARRAY[
    'vitality',           -- A) Celkový stav a vitalita
    'energy',             -- B) Energie a únava
    'sleep',              -- C) Spánek a regenerace
    'physical',           -- D) Fyzické tělo
    'metabolism',         -- E) Metabolismus a trávení
    'immunity',           -- F) Imunita a odolnost
    'psyche',             -- G) Psychika a stres
    'cognition',          -- H) Kognice a mentální výkon
    'mood',               -- I) Nálada a motivace
    'pain',               -- extra: Bolest (kept for operational value)
    'change_perception'   -- J) Celkové vnímání změny (from 2nd measurement)
  ];
  v_domain_name_keys TEXT[] := ARRAY[
    'longevityScore.domains.vitality',
    'longevityScore.domains.energy',
    'longevityScore.domains.sleep',
    'longevityScore.domains.physical',
    'longevityScore.domains.metabolism',
    'longevityScore.domains.immunity',
    'longevityScore.domains.psyche',
    'longevityScore.domains.cognition',
    'longevityScore.domains.mood',
    'longevityScore.domains.pain',
    'longevityScore.domains.change_perception'
  ];
  v_question_prefixes TEXT[] := ARRAY[
    'os_vitality_',                       -- os_vitality_overall, os_vitality_vs_peers, os_vitality_trend
    'os_energy_|os_fatigue_',             -- os_energy_morning, os_energy_afternoon, os_fatigue_frequency
    'os_sleep_',                          -- os_sleep_quality_subj, os_sleep_falling_asleep, os_sleep_waking_refreshed
    'os_physical_',                       -- os_physical_endurance, os_physical_strength, os_physical_flexibility
    'os_digestion_|os_appetite',          -- os_digestion_quality, os_digestion_regularity, os_appetite
    'os_immunity_',                       -- os_immunity_resistance, os_immunity_recovery, os_immunity_sickness_freq
    'os_emotional_',                      -- os_emotional_mood, os_emotional_stress, os_emotional_resilience
    'os_cognitive_',                      -- os_cognitive_concentration, os_cognitive_memory, os_cognitive_clarity
    'os_overall_',                        -- os_overall_health, os_overall_life_quality, os_overall_optimism
    'os_pain_',                           -- os_pain_intensity, os_pain_frequency, os_pain_impact
    'os_change_perception'                -- os_change_perception (single item, section J)
  ];
  v_domain_key TEXT;
  v_prefix TEXT;
  v_raw_score NUMERIC := 0;
  v_count INTEGER := 0;
  v_value NUMERIC;
  v_key TEXT;
  v_max_possible NUMERIC;
  v_percentage NUMERIC;
BEGIN
  -- Iterate through each domain
  FOR i IN 1..array_length(v_domain_keys, 1) LOOP
    v_domain_key := v_domain_keys[i];
    v_prefix := v_question_prefixes[i];
    v_raw_score := 0;
    v_count := 0;
    
    -- Sum all matching question responses
    FOR v_key IN SELECT jsonb_object_keys(p_responses) LOOP
      -- Handle multiple prefixes (separated by |)
      IF v_key ~ ('^(' || replace(v_prefix, '|', '|^') || ')') THEN
        v_value := (p_responses->v_key)::NUMERIC;
        IF v_value IS NOT NULL THEN
          v_raw_score := v_raw_score + v_value;
          v_count := v_count + 1;
        END IF;
      END IF;
    END LOOP;
    
    -- Calculate percentage (scale 0-10, so max = 10 * count)
    IF v_count > 0 THEN
      v_max_possible := 10.0 * v_count;
      v_percentage := (v_raw_score / v_max_possible) * 100.0;
    ELSE
      v_max_possible := 0;
      v_percentage := NULL;
    END IF;
    
    -- Add to domains array
    v_domains := v_domains || jsonb_build_object(
      'domain_code', v_domain_key,
      'domain_name_key', v_domain_name_keys[i],
      'questions_answered', v_count,
      'raw_score', v_raw_score,
      'max_possible', v_max_possible,
      'percentage', ROUND(v_percentage, 1)
    );
  END LOOP;
  
  RETURN v_domains;
END;
$$;

REVOKE ALL ON FUNCTION public.calculate_domain_scores(jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.calculate_domain_scores(jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.calculate_domain_scores(jsonb) TO authenticated;

COMMENT ON FUNCTION public.calculate_domain_scores(jsonb) IS 'Calculate domain scores from OS-SUBJECTIVE responses JSONB. Domains: vitality, energy, sleep, physical, metabolism, immunity, psyche, cognition, mood, pain, change_perception.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/calculate_member_compliance.sql
-- -----------------------------------------------------------------------------

-- Function: public.calculate_member_compliance
-- Arguments: p_member_token uuid, p_period_start date, p_period_end date
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:25:54+01:00

CREATE OR REPLACE FUNCTION public.calculate_member_compliance(p_member_token uuid, p_period_start date, p_period_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_required_checkins INTEGER;
  v_completed_checkins INTEGER;
  v_required_dosing INTEGER;
  v_completed_dosing INTEGER;
  v_score NUMERIC;
BEGIN
  -- Get user_id from member_distribution_plans
  SELECT user_id INTO v_user_id
  FROM member_distribution_plans
  WHERE member_token = p_member_token;
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Member not found');
  END IF;
  
  -- Count required check-ins (days in period)
  v_required_checkins := (p_period_end - p_period_start);
  
  -- Count completed check-ins
  SELECT COUNT(*) INTO v_completed_checkins
  FROM health_check_ins
  WHERE user_id = v_user_id
    AND check_in_date >= p_period_start
    AND check_in_date <= p_period_end;
  
  -- Count required dosing logs (days * doses_per_day from protocol)
  SELECT COALESCE(SUM(
    COALESCE(sdp.doses_per_day, 1) * (p_period_end - p_period_start)
  ), 0)
  INTO v_required_dosing
  FROM member_distribution_plans mdp
  JOIN study_distribution_protocols sdp ON sdp.id = mdp.protocol_id
  WHERE mdp.member_token = p_member_token
    AND mdp.status = 'active';
  
  -- Count completed dosing logs
  SELECT COUNT(*) INTO v_completed_dosing
  FROM dosing_logs
  WHERE user_id = v_user_id
    AND logged_at >= p_period_start
    AND logged_at <= p_period_end;
  
  -- Upsert compliance score
  INSERT INTO member_compliance_scores (
    member_token,
    period_start,
    period_end,
    required_checkins,
    completed_checkins,
    required_dosing_logs,
    completed_dosing_logs
  ) VALUES (
    p_member_token,
    p_period_start,
    p_period_end,
    v_required_checkins,
    LEAST(v_completed_checkins, v_required_checkins),
    v_required_dosing,
    LEAST(v_completed_dosing, v_required_dosing)
  )
  ON CONFLICT (member_token, period_start)
  DO UPDATE SET
    required_checkins = EXCLUDED.required_checkins,
    completed_checkins = EXCLUDED.completed_checkins,
    required_dosing_logs = EXCLUDED.required_dosing_logs,
    completed_dosing_logs = EXCLUDED.completed_dosing_logs;
  
  -- Return result
  SELECT jsonb_build_object(
    'member_token', member_token,
    'period', jsonb_build_object('start', period_start, 'end', period_end),
    'compliance_score', compliance_score,
    'checkins', jsonb_build_object('required', required_checkins, 'completed', completed_checkins),
    'dosing', jsonb_build_object('required', required_dosing_logs, 'completed', completed_dosing_logs)
  )
  INTO v_score
  FROM member_compliance_scores
  WHERE member_token = p_member_token AND period_start = p_period_start;
  
  RETURN v_score;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.calculate_member_compliance(p_member_token uuid, p_period_start date, p_period_end date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.calculate_member_compliance(p_member_token uuid, p_period_start date, p_period_end date) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/calculate_next_reminder_time.sql
-- -----------------------------------------------------------------------------

-- Function: public.calculate_next_reminder_time
-- Arguments: p_reminder_id uuid
-- Description: Helper function to calculate next reminder time.
-- Security: Internal helper - called by trigger/other functions.
-- @internal: true

CREATE OR REPLACE FUNCTION public.calculate_next_reminder_time(p_reminder_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reminder RECORD;
  v_next_date DATE;
  v_current_dow INTEGER;
  v_target_dow INTEGER;
  v_days_until INTEGER;
  v_min_days INTEGER;
BEGIN
  -- Get reminder details
  SELECT * INTO v_reminder
  FROM user_reminders
  WHERE id = p_reminder_id;

  IF v_reminder IS NULL THEN
    RETURN NULL;
  END IF;

  v_current_dow := EXTRACT(DOW FROM CURRENT_DATE)::INTEGER; -- 0=Sunday, 1=Monday, etc.

  CASE v_reminder.frequency
    WHEN 'daily' THEN
      -- Next occurrence is today if time hasn't passed, else tomorrow
      IF CURRENT_TIME < v_reminder.time_of_day THEN
        v_next_date := CURRENT_DATE;
      ELSE
        v_next_date := CURRENT_DATE + 1;
      END IF;

    WHEN 'weekly' THEN
      -- Find next matching day of week
      v_min_days := 8; -- Start with more than a week
      IF v_reminder.custom_frequency_days IS NOT NULL THEN
        FOREACH v_target_dow IN ARRAY v_reminder.custom_frequency_days
        LOOP
          v_days_until := (v_target_dow - v_current_dow + 7) % 7;
          -- If today is a target day and time hasn't passed
          IF v_days_until = 0 AND CURRENT_TIME >= v_reminder.time_of_day THEN
            v_days_until := 7; -- Move to next week
          END IF;
          IF v_days_until < v_min_days THEN
            v_min_days := v_days_until;
          END IF;
        END LOOP;
        v_next_date := CURRENT_DATE + v_min_days;
      ELSE
        -- Default to next Monday if no days specified
        v_days_until := (1 - v_current_dow + 7) % 7;
        IF v_days_until = 0 AND CURRENT_TIME >= v_reminder.time_of_day THEN
          v_days_until := 7;
        END IF;
        v_next_date := CURRENT_DATE + v_days_until;
      END IF;

    WHEN 'biweekly' THEN
      -- Every 2 weeks from start_date
      IF v_reminder.start_date IS NOT NULL THEN
        v_days_until := 14 - ((CURRENT_DATE - v_reminder.start_date) % 14);
        IF v_days_until = 14 AND CURRENT_TIME >= v_reminder.time_of_day THEN
          v_days_until := 14;
        ELSIF v_days_until = 14 THEN
          v_days_until := 0;
        END IF;
      ELSE
        v_days_until := 14;
      END IF;
      v_next_date := CURRENT_DATE + v_days_until;

    WHEN 'monthly' THEN
      -- Same day each month
      v_next_date := date_trunc('month', CURRENT_DATE) + INTERVAL '1 month';
      IF CURRENT_DATE < date_trunc('month', CURRENT_DATE)::DATE + EXTRACT(DAY FROM COALESCE(v_reminder.start_date, CURRENT_DATE))::INTEGER - 1 THEN
        v_next_date := date_trunc('month', CURRENT_DATE)::DATE + EXTRACT(DAY FROM COALESCE(v_reminder.start_date, CURRENT_DATE))::INTEGER - 1;
      END IF;

    WHEN 'custom' THEN
      -- Same as weekly with custom days
      v_min_days := 8;
      IF v_reminder.custom_frequency_days IS NOT NULL THEN
        FOREACH v_target_dow IN ARRAY v_reminder.custom_frequency_days
        LOOP
          v_days_until := (v_target_dow - v_current_dow + 7) % 7;
          IF v_days_until = 0 AND CURRENT_TIME >= v_reminder.time_of_day THEN
            v_days_until := 7;
          END IF;
          IF v_days_until < v_min_days THEN
            v_min_days := v_days_until;
          END IF;
        END LOOP;
        v_next_date := CURRENT_DATE + v_min_days;
      ELSE
        v_next_date := CURRENT_DATE + 1;
      END IF;

    ELSE
      -- Default: tomorrow
      v_next_date := CURRENT_DATE + 1;
  END CASE;

  -- Combine date with time and apply timezone
  RETURN (v_next_date + v_reminder.time_of_day)::TIMESTAMP
    AT TIME ZONE COALESCE(v_reminder.user_timezone, 'Europe/Prague');
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.calculate_next_reminder_time(p_reminder_id uuid) FROM PUBLIC;
-- No GRANT - internal/helper function


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/calculate_revenue_split_audited.sql
-- -----------------------------------------------------------------------------

-- Function: calculate_revenue_split_audited
-- Purpose: Calculate revenue split for a completed booking/story
-- Revenue model:
--   PROJECT:     70% specialist, 20% knowledge contributors, 10% platform
--   MAINTENANCE: 70% platform,  20% knowledge contributors, 10% specialist

CREATE OR REPLACE FUNCTION calculate_revenue_split_audited(
  p_project_revenue_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_revenue RECORD;
  v_specialist_user_id uuid;
  v_specialist_pct numeric(5,2);
  v_platform_pct numeric(5,2);
  v_knowledge_pct numeric(5,2) := 20.00;
  v_knowledge_total numeric(10,2);
  v_specialist_amount numeric(10,2);
  v_platform_amount numeric(10,2);
  v_attribution RECORD;
  v_total_weight numeric;
  v_split_count integer := 0;
BEGIN
  -- 1. Fetch revenue record
  SELECT pr.*, ps.partner_id
  INTO v_revenue
  FROM project_revenue pr
  JOIN partner_stories ps ON ps.id = pr.story_id
  WHERE pr.id = p_project_revenue_id;

  IF v_revenue IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Revenue record not found');
  END IF;

  IF v_revenue.status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Revenue already calculated');
  END IF;

  -- 2. Get specialist user_id
  SELECT user_id INTO v_specialist_user_id
  FROM partner_profiles
  WHERE id = v_revenue.partner_id;

  -- 3. Determine split percentages by revenue type
  IF v_revenue.revenue_type = 'project' THEN
    v_specialist_pct := 70.00;
    v_platform_pct := 10.00;
  ELSIF v_revenue.revenue_type = 'maintenance' THEN
    v_specialist_pct := 10.00;
    v_platform_pct := 70.00;
  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'Unknown revenue type');
  END IF;

  -- 4. Calculate amounts
  v_specialist_amount := ROUND(v_revenue.total_amount * v_specialist_pct / 100, 2);
  v_platform_amount := ROUND(v_revenue.total_amount * v_platform_pct / 100, 2);
  v_knowledge_total := v_revenue.total_amount - v_specialist_amount - v_platform_amount;

  -- 5. Delete any existing splits (idempotent recalculation)
  DELETE FROM revenue_splits WHERE project_revenue_id = p_project_revenue_id;

  -- 6. Insert specialist split
  INSERT INTO revenue_splits (
    project_revenue_id, recipient_type, recipient_id,
    percentage, amount, attribution_details
  ) VALUES (
    p_project_revenue_id, 'specialist', v_specialist_user_id,
    v_specialist_pct, v_specialist_amount,
    jsonb_build_object('role', 'dirigent', 'partner_id', v_revenue.partner_id)
  );
  v_split_count := v_split_count + 1;

  -- 7. Insert platform split
  INSERT INTO revenue_splits (
    project_revenue_id, recipient_type, recipient_id,
    percentage, amount, attribution_details
  ) VALUES (
    p_project_revenue_id, 'platform', NULL,
    v_platform_pct, v_platform_amount,
    jsonb_build_object('role', 'platform')
  );
  v_split_count := v_split_count + 1;

  -- 8. Calculate knowledge contributor splits (weighted by attribution)
  SELECT COALESCE(SUM(attribution_weight), 0)
  INTO v_total_weight
  FROM knowledge_attribution
  WHERE story_id = v_revenue.story_id
    AND attribution_weight > 0
    AND author_id IS NOT NULL;

  IF v_total_weight > 0 THEN
    -- Distribute knowledge pool proportionally by attribution_weight
    FOR v_attribution IN
      SELECT
        author_id,
        SUM(attribution_weight) AS total_author_weight,
        COUNT(*) AS rules_used
      FROM knowledge_attribution
      WHERE story_id = v_revenue.story_id
        AND attribution_weight > 0
        AND author_id IS NOT NULL
      GROUP BY author_id
    LOOP
      INSERT INTO revenue_splits (
        project_revenue_id, recipient_type, recipient_id,
        percentage, amount, attribution_details
      ) VALUES (
        p_project_revenue_id,
        'knowledge_contributor',
        v_attribution.author_id,
        ROUND(v_knowledge_pct * v_attribution.total_author_weight / v_total_weight, 2),
        ROUND(v_knowledge_total * v_attribution.total_author_weight / v_total_weight, 2),
        jsonb_build_object(
          'author_weight', v_attribution.total_author_weight,
          'total_weight', v_total_weight,
          'rules_used', v_attribution.rules_used
        )
      );
      v_split_count := v_split_count + 1;
    END LOOP;
  ELSE
    -- No knowledge attribution — knowledge share goes to platform
    UPDATE revenue_splits
    SET amount = amount + v_knowledge_total,
        percentage = percentage + v_knowledge_pct,
        attribution_details = attribution_details || jsonb_build_object(
          'knowledge_pool_absorbed', true,
          'reason', 'no_attributions'
        )
    WHERE project_revenue_id = p_project_revenue_id
      AND recipient_type = 'platform';
  END IF;

  -- 9. Update revenue status
  UPDATE project_revenue
  SET status = 'calculated', calculated_at = now(), updated_at = now()
  WHERE id = p_project_revenue_id;

  -- 10. Audit log
  -- user_id = auth.uid() (nullable): callable by service_role (revenue workflow)
  -- where auth.uid() is NULL; the COALESCE fallback to '00000000-…0000' is not a
  -- real aisha_auth.users id → audit_journal_user_id_fkey violation that would
  -- abort the whole calculation. NULL is FK-safe.
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'REVENUE_SPLIT_CALCULATED',
    jsonb_build_object(
      'area', 'marketplace',
      'severity', 'info',
      'entity_type', 'project_revenue',
      'entity_id', p_project_revenue_id,
      'total_amount', v_revenue.total_amount,
      'revenue_type', v_revenue.revenue_type::text,
      'splits_count', v_split_count
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'splits_count', v_split_count,
    'total_amount', v_revenue.total_amount,
    'specialist_amount', v_specialist_amount,
    'knowledge_amount', v_knowledge_total,
    'platform_amount', v_platform_amount
  );
END;
$$;

REVOKE ALL ON FUNCTION calculate_revenue_split_audited(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION calculate_revenue_split_audited(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION calculate_revenue_split_audited(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/cancel_account_deletion.sql
-- -----------------------------------------------------------------------------

-- Cancel a pending account deletion request
-- User can cancel the deletion within the 30-day grace period

CREATE OR REPLACE FUNCTION cancel_account_deletion()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id UUID;
  v_request_id UUID;
BEGIN
  -- Get current user
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  -- Find pending deletion request
  SELECT id INTO v_request_id
  FROM account_deletion_requests
  WHERE user_id = v_user_id
  AND status = 'pending'
  ORDER BY requested_at DESC
  LIMIT 1;
  
  IF v_request_id IS NULL THEN
    RAISE EXCEPTION 'No pending deletion request found';
  END IF;
  
  -- Cancel the request
  UPDATE account_deletion_requests
  SET 
    status = 'cancelled',
    cancelled_at = NOW()
  WHERE id = v_request_id;
  
  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'ACCOUNT_DELETION_CANCELLED',
    jsonb_build_object(
      'area', 'account',
      'severity', 'info',
      'request_id', v_request_id
    )
  );
  
  RETURN jsonb_build_object(
    'success', TRUE,
    'request_id', v_request_id,
    'message', 'Account deletion cancelled'
  );
END;
$$;

-- Permissions
REVOKE ALL ON FUNCTION cancel_account_deletion() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION cancel_account_deletion() TO authenticated;

COMMENT ON FUNCTION cancel_account_deletion() IS 
'Cancels a pending account deletion request within the 30-day grace period.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/cancel_agent_run.sql
-- -----------------------------------------------------------------------------

-- Function: public.cancel_agent_run
-- Description: Cancel a queued or running agent run owned by the caller.
--   Returns true if the run was cancelled, false if not found / not cancellable.
-- Security: SECURITY DEFINER, grants to authenticated

CREATE OR REPLACE FUNCTION public.cancel_agent_run(p_run_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_updated int;
BEGIN
  UPDATE public.agent_runs SET
    status      = 'cancelled',
    finished_at = now()
  WHERE id = p_run_id
    AND requested_by = auth.uid()
    AND status IN ('queued', 'running');

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated > 0;
END;
$$;

REVOKE ALL ON FUNCTION public.cancel_agent_run(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.cancel_agent_run(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/cancel_ai_task.sql
-- -----------------------------------------------------------------------------

-- Function: public.cancel_ai_task
-- Arguments: p_task_id uuid
-- Security: SECURITY DEFINER
-- Source: Phase 4 — Agent Loop & Memory

CREATE OR REPLACE FUNCTION public.cancel_ai_task(p_task_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $$
DECLARE
  v_updated boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  UPDATE ai_tasks
  SET status = 'cancelled', completed_at = now(), updated_at = now()
  WHERE id = p_task_id AND user_id = auth.uid() AND status IN ('queued', 'running');

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated;
END;
$$;

REVOKE ALL ON FUNCTION public.cancel_ai_task(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.cancel_ai_task(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/canonical_ingest_source.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: canonical_ingest_source
-- Popis: Kanonická identita zdroje, pod kterou se zapisují vazby twinů.
--        Zdroj POHLCENÝ jiným (agent_knowledge_sources: neaktivní +
--        config.superseded_by) se převede na toho, kdo ho pohltil.
-- Bezpečnost: SECURITY INVOKER, bez grantu klientům — volají ji jen zapisovatelé
--             twinů (SECURITY DEFINER) zevnitř, takže běží jejich právy.
--
-- ⛔ PROČ VZNIKLA (naměřeno 2026-09-19 v produkci riq). Tři balíčky ze 3.–4. 8.
--    nesly jméno aplikace `aisha-local-ingest` místo registrovaného zdroje
--    `local-ingest`. V registru zdrojů se to 2026-09-02 sjednotilo pohlcením
--    (ensure_source_story, config.superseded_by) — ale zapisovatelé twinů
--    párují PŘESNĚ podle (source, source_key), takže přehrání 30. 8. založilo
--    839 duplikátních firem (21 % všech twinů). Jedna skutečnost, DVĚ identity.
--    Pohlcení je kurátorované rozhodnutí o světě; tady se jen DODRŽUJE i pro
--    twiny — nové rozhodnutí se tu nevyrábí.
--
-- Kontrakt: (text) -> text  (nepohlcený nebo neznámý zdroj vrací beze změny)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.canonical_ingest_source(p_source text)
RETURNS text
LANGUAGE sql
STABLE
SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT coalesce(
    (SELECT btrim(s.config ->> 'superseded_by')
       FROM public.agent_knowledge_sources s
      WHERE s.source_slug = p_source
        AND NOT s.is_active
        AND coalesce(btrim(s.config ->> 'superseded_by'), '') <> ''
      LIMIT 1),
    p_source);
$function$;

REVOKE ALL ON FUNCTION public.canonical_ingest_source(text) FROM PUBLIC, anon, authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/capture_lead.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: capture_lead
-- Purpose: Public, anon-callable intake for contact/quote/inquiry leads from
--          seeded web pages. Validates + normalizes input, inserts one
--          lead_submissions row, and writes a PII-free audit entry.
-- Security: SECURITY DEFINER so anonymous visitors can write a single row into
--           the RLS-locked lead_submissions table WITHOUT direct table access.
--           Intentionally public (no auth check) — this is a public web form.
--           access.mjs exempts anon-granted definers from SEC_DEF_NO_AUTH; the
--           table is non-PHI, so SEC_DEF_ANON_GRANT/CONSENT do not apply.
-- Input is hard-bounded (length caps) to limit abuse; further spam mitigation
-- (rate limiting / captcha) is a deployment-layer concern — see docs follow-up.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.capture_lead(
  p_name     text,
  p_contact  text,
  p_message  text,
  p_source   text  DEFAULT 'website',
  p_subject  text  DEFAULT NULL,
  p_locale   text  DEFAULT NULL,
  p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id      uuid;
  v_name    text := btrim(coalesce(p_name, ''));
  v_contact text := btrim(coalesce(p_contact, ''));
  v_message text := btrim(coalesce(p_message, ''));
  v_source  text := btrim(coalesce(nullif(p_source, ''), 'website'));
  v_subject text := nullif(btrim(coalesce(p_subject, '')), '');
  v_locale  text := nullif(btrim(coalesce(p_locale, '')), '');
BEGIN
  -- Validate / reject unexpected shapes (CLAUDE.md: validate all input).
  IF v_name = '' OR char_length(v_name) > 200 THEN
    RAISE EXCEPTION 'capture_lead: invalid name' USING ERRCODE = '22023';
  END IF;
  IF v_contact = '' OR char_length(v_contact) > 320 THEN
    RAISE EXCEPTION 'capture_lead: invalid contact' USING ERRCODE = '22023';
  END IF;
  IF v_message = '' OR char_length(v_message) > 5000 THEN
    RAISE EXCEPTION 'capture_lead: invalid message' USING ERRCODE = '22023';
  END IF;
  IF v_subject IS NOT NULL AND char_length(v_subject) > 200 THEN
    v_subject := left(v_subject, 200);
  END IF;
  IF char_length(v_source) > 100 THEN
    v_source := left(v_source, 100);
  END IF;
  IF v_locale IS NOT NULL AND v_locale NOT IN ('en', 'cs', 'de', 'fr', 'ru', 'th') THEN
    v_locale := NULL;
  END IF;

  INSERT INTO public.lead_submissions
    (source, name, contact, subject, message, locale, metadata)
  VALUES
    (v_source, v_name, v_contact, v_subject, v_message, v_locale,
     coalesce(p_metadata, '{}'::jsonb))
  RETURNING id INTO v_id;

  -- Audit: IDs + routing metadata only — never the lead's PII (name/contact/message).
  INSERT INTO public.audit_journal
    (user_id, action_type, action, entity_type, entity_id, area, severity, summary, metadata)
  VALUES
    (auth.uid(), 'create', 'lead_submission.created', 'lead_submission', v_id::text,
     'web', 'info', 'Public web lead submitted',
     jsonb_build_object('source', v_source, 'has_subject', v_subject IS NOT NULL, 'locale', v_locale));

  RETURN v_id;
END;
$$;

-- Public web form: anon may submit; authenticated/service inherit. No direct
-- table grant — the SECURITY DEFINER body is the only write path.
REVOKE ALL ON FUNCTION public.capture_lead(text, text, text, text, text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.capture_lead(text, text, text, text, text, text, jsonb) TO anon;
GRANT EXECUTE ON FUNCTION public.capture_lead(text, text, text, text, text, text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.capture_lead(text, text, text, text, text, text, jsonb) TO service_role;

COMMENT ON FUNCTION public.capture_lead(text, text, text, text, text, text, jsonb) IS
  'Public anon-callable lead intake for seeded web pages. Validates, inserts one lead_submissions row, audits (no PII). Returns the new lead id.';


