-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/complete_integration_event.sql
-- -----------------------------------------------------------------------------

-- Function: public.complete_integration_event
-- Marks an integration event as completed/failed with optional retry scheduling.
-- Retry uses exponential backoff: 5^attempt minutes (5m, 25m, 125m).
-- @security: service_role only

CREATE OR REPLACE FUNCTION public.complete_integration_event(
  p_event_id         uuid,
  p_status           text,
  p_n8n_execution_id text DEFAULT NULL,
  p_error_json       jsonb DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  UPDATE integration_events
  SET
    status = p_status,
    processing_finished_at = now(),
    n8n_execution_id = COALESCE(p_n8n_execution_id, n8n_execution_id),
    error_json = COALESCE(p_error_json, error_json),
    attempt = CASE WHEN p_status = 'failed' THEN attempt + 1 ELSE attempt END,
    next_retry_at = CASE
      WHEN p_status = 'failed' AND attempt < max_attempts
      THEN now() + (POWER(5, attempt) || ' minutes')::interval
      ELSE NULL
    END
  WHERE id = p_event_id;
END;
$$;

REVOKE ALL ON FUNCTION public.complete_integration_event(uuid, text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.complete_integration_event(uuid, text, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/complete_workbench_request.sql
-- -----------------------------------------------------------------------------

-- Function: complete_workbench_request
-- The aisha-dirigent extension posts a request's result here after running it locally.
-- Idempotent: the status guard (only pending/claimed) makes a retried POST a no-op once the
-- request is already completed/failed. Authenticated (dev = admin/staff) or service_role.
-- Params alphabetical (rpc-params gate).

CREATE OR REPLACE FUNCTION public.complete_workbench_request(
  p_error      text    DEFAULT NULL,
  p_latency_ms integer DEFAULT NULL,
  p_ok         boolean DEFAULT false,
  p_output     text    DEFAULT NULL,
  p_request_id uuid    DEFAULT NULL,
  p_tokens_in  integer DEFAULT NULL,
  p_tokens_out integer DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row workbench_execution_requests;
BEGIN
  IF auth.uid() IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb ->> 'role') <> 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'p_request_id required' USING ERRCODE = '22023';
  END IF;

  UPDATE workbench_execution_requests
  SET status       = CASE WHEN p_ok THEN 'completed' ELSE 'failed' END,
      response     = p_output,
      error_detail = CASE WHEN p_ok THEN NULL
                          ELSE jsonb_build_object('message', COALESCE(p_error, 'workbench_error')) END,
      tokens_in    = p_tokens_in,
      tokens_out   = p_tokens_out,
      latency_ms   = p_latency_ms,
      completed_at = now()
  WHERE id = p_request_id
    AND status IN ('pending', 'claimed')   -- idempotent: a second POST after completion is a no-op
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    RETURN jsonb_build_object('request_id', p_request_id, 'updated', false);
  END IF;
  RETURN jsonb_build_object('request_id', v_row.id, 'status', v_row.status, 'updated', true);
END;
$$;

REVOKE ALL ON FUNCTION public.complete_workbench_request(text, integer, boolean, text, uuid, integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.complete_workbench_request(text, integer, boolean, text, uuid, integer, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.complete_workbench_request(text, integer, boolean, text, uuid, integer, integer) TO service_role;

COMMENT ON FUNCTION public.complete_workbench_request(text, integer, boolean, text, uuid, integer, integer) IS
  'PR-J: the extension posts a workbench request result (completed/failed); idempotent via the status guard. authenticated/service_role.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/confirm_product_taken_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.confirm_product_taken_audited
-- Arguments: p_plan_id uuid, p_taken_at timestamp with time zone DEFAULT now(), p_dose_taken numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.confirm_product_taken_audited(p_plan_id uuid, p_taken_at timestamp with time zone DEFAULT now(), p_dose_taken numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_log_id uuid;
  v_plan record;
  v_actual_dose numeric;
  v_reward_rule record;
  v_tokens_earned int := 0;
  v_token_type text := NULL;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Get and verify plan
  SELECT * INTO v_plan FROM member_product_plans WHERE id = p_plan_id AND user_id = auth.uid();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Plan not found or not owned';
  END IF;

  -- Use provided dose or plan default
  v_actual_dose := COALESCE(p_dose_taken, v_plan.dose_amount);

  -- Log the dose
  INSERT INTO member_product_logs (user_id, plan_id, product_id, catalog_product_id, dose_taken, logged_at, notes)
  VALUES (auth.uid(), p_plan_id, v_plan.product_id, v_plan.product_id, v_actual_dose, p_taken_at, p_notes)
  RETURNING id INTO v_log_id;

  -- Update plan
  UPDATE member_product_plans 
  SET 
    last_taken_at = p_taken_at,
    remaining_doses = GREATEST(0, remaining_doses - v_actual_dose),
    next_reminder_at = NULL
  WHERE id = p_plan_id;

  -- Award tokens based on reward rules
  SELECT * INTO v_reward_rule FROM token_reward_rules 
  WHERE action_type = 'dosing_log' AND is_active = true LIMIT 1;
  
  IF v_reward_rule IS NOT NULL THEN
    v_token_type := v_reward_rule.token_type;
    v_tokens_earned := COALESCE(v_reward_rule.base_amount * v_reward_rule.multiplier, 0)::int;
    
    IF v_tokens_earned > 0 THEN
      PERFORM award_tokens(
        auth.uid(),
        v_reward_rule.token_type,
        v_tokens_earned,
        'product_log',
        v_log_id,
        format('Dosing log: %s', v_plan.dose_unit)
      );
    END IF;
  END IF;

  INSERT INTO audit_journal (user_id, action_type, entity_type, entity_id, area, severity, summary)
  VALUES (auth.uid(), 'create', 'member_product_log', v_log_id::text, 'member', 'info', 
          format('Confirmed product taken: %s %s (+%s tokens)', v_actual_dose, v_plan.dose_unit, v_tokens_earned));

  RETURN jsonb_build_object(
    'success', true,
    'log_id', v_log_id,
    'tokens_earned', v_tokens_earned,
    'token_type', v_token_type
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.confirm_product_taken_audited(uuid, timestamptz, numeric, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.confirm_product_taken_audited(uuid, timestamptz, numeric, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.confirm_product_taken_audited(uuid, timestamptz, numeric, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/consult_decision_tree.sql
-- -----------------------------------------------------------------------------

-- Function: consult_decision_tree

CREATE OR REPLACE FUNCTION public.consult_decision_tree(p_agent_slug text, p_tree_name text, p_context jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tree jsonb;
  v_nodes jsonb;
  v_current_id text;
  v_current_node jsonb;
  v_node_type text;
  v_field text;
  v_field_value text;
  v_branches jsonb;
  v_branch jsonb;
  v_matched boolean;
  v_max_iterations integer := 20;
  v_iteration integer := 0;
BEGIN
  -- Fetch the tree
  SELECT adt.tree_definition INTO v_tree
  FROM agent_decision_trees adt
  JOIN agent_catalog ac ON ac.id = adt.agent_id
  WHERE ac.slug = p_agent_slug
    AND adt.tree_name = p_tree_name
    AND adt.is_active = true;

  IF v_tree IS NULL THEN
    RETURN jsonb_build_object('status', 'no_tree', 'message', 'No active decision tree found');
  END IF;

  v_nodes := v_tree->'nodes';
  v_current_id := v_tree->>'root';

  -- Walk the tree
  WHILE v_iteration < v_max_iterations LOOP
    v_iteration := v_iteration + 1;

    -- Find current node
    SELECT node INTO v_current_node
    FROM jsonb_array_elements(v_nodes) AS node
    WHERE node->>'id' = v_current_id;

    IF v_current_node IS NULL THEN
      RETURN jsonb_build_object('status', 'error', 'message', 'Node not found: ' || v_current_id);
    END IF;

    v_node_type := v_current_node->>'type';

    -- Terminal nodes
    IF v_node_type IN ('action', 'escalation') THEN
      RETURN v_current_node || jsonb_build_object('status', 'resolved', 'iterations', v_iteration);
    END IF;

    -- Condition node: evaluate branches
    IF v_node_type = 'condition' THEN
      v_field := v_current_node->>'field';
      -- Extract value from context using dot notation (e.g., "task.category")
      v_field_value := p_context #>> string_to_array(v_field, '.');
      v_branches := v_current_node->'branches';
      v_matched := false;

      FOR v_branch IN SELECT * FROM jsonb_array_elements(v_branches) LOOP
        IF v_branch->>'value' = v_field_value OR v_branch->>'value' = 'default' THEN
          v_current_id := v_branch->>'next';
          v_matched := true;
          EXIT;
        END IF;
      END LOOP;

      IF NOT v_matched THEN
        -- Try default branch
        FOR v_branch IN SELECT * FROM jsonb_array_elements(v_branches) LOOP
          IF v_branch->>'value' = 'default' THEN
            v_current_id := v_branch->>'next';
            v_matched := true;
            EXIT;
          END IF;
        END LOOP;
      END IF;

      IF NOT v_matched THEN
        RETURN jsonb_build_object('status', 'no_match', 'message', 'No matching branch for field ' || v_field || ' = ' || COALESCE(v_field_value, 'NULL'));
      END IF;
    ELSE
      RETURN jsonb_build_object('status', 'error', 'message', 'Unknown node type: ' || v_node_type);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('status', 'error', 'message', 'Max iterations reached');
END;
$function$;

REVOKE ALL ON FUNCTION consult_decision_tree(p_agent_slug text, p_tree_name text, p_context jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION consult_decision_tree(text,text,jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION consult_decision_tree(text,text,jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/convert_currency_amount.sql
-- -----------------------------------------------------------------------------

-- Function: public.convert_currency_amount
-- Arguments: p_amount numeric, p_from_currency text, p_to_currency text
-- Description: Helper function to convert currency amounts.
-- Security: Internal helper - used by other functions.
-- @internal: true

CREATE OR REPLACE FUNCTION public.convert_currency_amount(p_amount numeric, p_from_currency text, p_to_currency text)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    CASE
      WHEN p_amount IS NULL THEN NULL
      WHEN p_from_currency IS NULL OR p_to_currency IS NULL THEN NULL
      WHEN upper(p_from_currency) = upper(p_to_currency) THEN p_amount
      ELSE
        p_amount
        * (
          (SELECT cr_to.rate_to_base
           FROM public.currency_rates cr_to
           WHERE cr_to.code = upper(p_to_currency)
             AND cr_to.is_active = true)
          /
          (SELECT cr_from.rate_to_base
           FROM public.currency_rates cr_from
           WHERE cr_from.code = upper(p_from_currency)
             AND cr_from.is_active = true)
        )
    END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.convert_currency_amount(p_amount numeric, p_from_currency text, p_to_currency text) FROM PUBLIC;
-- No GRANT - internal/helper function


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/counterparty_docs.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: counterparty_docs
-- Popis: platné doklady (superseded_by is null) daného typu jedné protistrany.
--        Podle IČO (`fields.counterparty_id` = any icos); podle JMÉNA jen u protistrany
--        BEZ IČO a jen doklady bez IČO — totéž jméno nese víc firem (firma se
--        přejmenovává, jméno je parametr v čase).
--        Oba predikáty jdou po svém indexu (idx_li_source_registry_counterparty_id_value /
--        _counterparty_value); `OR` dvou indexovaných podmínek zvládne BitmapOr.
--        ⛔ Filtr nad GENEROVANÝM sloupcem, ne nad `fields` (2026-09-29): pod RLS smí
--        planner do indexu jen leakproof podmínku a výraz nad jsonb jí není — expresní
--        index se pro přihlášeného nepoužil nikdy (viz tables/li_source_registry.sql).
-- SECURITY INVOKER: viditelnost rozhoduje RLS nad li_source_registry.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.counterparty_docs(p_icos text[], p_names text[], p_doc_type text)
RETURNS SETOF li_source_registry
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  select r.*
    from public.li_source_registry r
   where r.superseded_by is null
     and r.doc_type = p_doc_type
     and (r.counterparty_id_value = any(p_icos)
          -- Podle JMÉNA jen protistrana, která IČO NEMÁ (fyzická osoba). Naměřeno
          -- 23. 9.: u IČO dlužníků by jméno přitáhlo doklady bez IČO — 909 v evidenci,
          -- u jednoho dlužníka 60 dokladů / 30 mil. Kč, typicky PDF kopie téže faktury
          -- z Money (bez owner_company, bez amount_unpaid). Čísla karty je filtr
          -- `issued` sice odfiltroval, ale jména v čase a adresu by zkreslily.
          or (cardinality(p_icos) = 0
              and r.counterparty_value = any(p_names)
              and r.counterparty_id_value is null));
$$;

REVOKE ALL ON FUNCTION public.counterparty_docs(text[], text[], text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.counterparty_docs(text[], text[], text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/counterparty_contracts.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: counterparty_contracts
-- Popis: SMLOUVY PROTISTRANY — jedna odpověď pro kartu (počet) i síť vazeb
--        (uzly). Dvě cesty, každá se svou jistotou:
--          derived    smlouva nese IČO/jméno protistrany v polích (counterparty_docs)
--          proposed   ingest ji navrhl k twinu firmy (identified_tenant, čeká na člověka)
--          confirmed  člověk návrh potvrdil
--        Jedna smlouva jednou; vyhrává nejvyšší jistota.
--
-- ⭐ PROČ JEDNO MÍSTO: naměřeno 2026-09-25 na kartě Inspirace — síť vazeb
--    smlouvu ukázala (návrh k twinu), hlavička karty napsala „Smluv: 0", protože
--    počítala jen smlouvy s IČO v polích. Pole smluv strany dnes nenesou
--    (li_links / contract_register 0), takže bez návrhů by karta smlouvy neviděla
--    vůbec. Dvě čtečky, dvě pravdy — teď jedna.
--
-- Vstup je výstup counterparty_resolve (icos, names, twins) — karta i síť
-- rozřeší protistranu jednou a sem pošlou totéž.
-- SECURITY INVOKER: viditelnost rozhoduje RLS nad li_source_registry a twin_*.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.counterparty_contracts(p_icos text[], p_names text[], p_twins jsonb)
RETURNS TABLE (doc_slug text, filename text, fields jsonb, certainty text)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  with tw as (
    select (x->>'id')::uuid as id from jsonb_array_elements(coalesce(p_twins, '[]'::jsonb)) x
  ),
  smlouvy as (
    select d.doc_slug, d.filename, d.fields, 'derived' as certainty
      from public.counterparty_docs(p_icos, p_names, 'contract') d
    union all
    select l.doc_slug, l.filename, l.fields,
           case r.state when 'confirmed' then 'confirmed' else 'proposed' end
      from tw
      join public.twin_external_refs r on r.twin_id = tw.id and r.ref_kind = 'identified_tenant' and r.state <> 'rejected'
      join public.li_source_registry l on l.source_sha256 = r.source_key and l.superseded_by is null
  )
  select distinct on (s.doc_slug) s.doc_slug, s.filename, s.fields, s.certainty
    from smlouvy s
   order by s.doc_slug, case s.certainty when 'confirmed' then 0 when 'proposed' then 1 else 2 end;
$$;

REVOKE ALL ON FUNCTION public.counterparty_contracts(text[], text[], jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.counterparty_contracts(text[], text[], jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/counterparty_labels.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: counterparty_labels
-- Popis: AKTUÁLNÍ JMÉNO protistrany pro MNOŽINU IČO — totéž pravidlo, jaké má karta
--        (counterparty_resolve.label), jen spočtené najednou pro celý přehled.
--
-- ⛔ JMÉNO NENÍ IDENTITA (majitel 2026-07-31, 2026-09-29): firma se přejmenuje,
--    fúzuje, a její staré jméno může převzít JINÁ firma. Naměřeno 2026-09-29 na riq
--    (vydané faktury): 14 IČO nese víc jmen (přejmenování), 6 jmen nese víc IČO —
--    „Slezské kamenolomy a.s." přešlo 1. 10. 2019 z IČO 29243661 (dnes Business Park
--    Ďáblická) na 08300283. Přehledy seskupené podle jména proto jednu firmu ROZDĚLILY
--    a dvě různé SLILY (142 268 = 117 975 + 24 293 Kč v jednom řádku).
--
-- Pořadí zdrojů jména (jako karta):
--   1. SCHVÁLENÝ název — `company_name`/`nase_firma` potvrzený člověkem a platný TEĎ
--      (valid_from/valid_to) u dvojčete nesoucího to IČO. Změna jména na dokladu je
--      návrh ingestu, pravdou je až po schválení.
--   2. do schválení: jméno z NEJNOVĚJŠÍHO dokladu s tím IČO (podle data vystavení) —
--      přejmenovaná firma se tak ukáže pod dnešním jménem, i když jí po splatnosti
--      visí faktura vystavená na jméno staré.
-- Jméno platné k datu dokladu (jména v čase, fúze) je samostatná vrstva — tady jen „teď".
--
-- Vstup: pole IČO (prázdné / NULL prvky se ignorují). Výstup: (ico, label, schvaleno).
-- SECURITY INVOKER: viditelnost dokladů i vazeb rozhoduje RLS volajícího.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.counterparty_labels(p_icos text[])
RETURNS TABLE (ico text, label text, schvaleno boolean)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  with vstup as (
    select distinct i as ico from unnest(coalesce(p_icos, '{}'::text[])) i
     where nullif(btrim(i), '') is not null
  ),
  -- 2. nejnovější jméno z dokladů (kterýkoli druh dokladu s tím IČO)
  z_dokladu as (
    select distinct on (r.counterparty_id_value)
           r.counterparty_id_value        as ico,
           btrim(r.counterparty_value)    as jmeno
      from public.li_source_registry r
     where r.superseded_by is null
       and r.counterparty_id_value in (select ico from vstup)
       and length(btrim(coalesce(r.counterparty_value, ''))) between 2 and 80
     order by r.counterparty_id_value,
              coalesce(r.fields->'issue_date'->>'value', r.created_at::date::text) desc,
              r.created_at desc
  ),
  -- 1. schválený název platný teď, u dvojčete s vazbou na to IČO
  schvalene as (
    select distinct on (ri.source_key)
           ri.source_key as ico, rn.source_key as jmeno
      from public.twin_external_refs ri
      join public.twin_external_refs rn on rn.twin_id = ri.twin_id
     where ri.ref_kind = 'company_ico' and ri.state <> 'rejected'
       and ri.source_key in (select ico from vstup)
       and rn.ref_kind in ('company_name', 'nase_firma') and rn.state = 'confirmed'
       and (rn.valid_from is null or rn.valid_from <= now())
       and (rn.valid_to is null or rn.valid_to > now())
     order by ri.source_key, rn.valid_from desc nulls last, rn.confirmed_at desc nulls last
  )
  select v.ico,
         coalesce(s.jmeno, d.jmeno)  as label,
         (s.jmeno is not null)       as schvaleno
    from vstup v
    left join schvalene s on s.ico = v.ico
    left join z_dokladu d on d.ico = v.ico;
$$;

COMMENT ON FUNCTION public.counterparty_labels(text[]) IS
  'Aktuální jméno protistrany pro množinu IČO: schválený název platný teď (company_name/nase_firma), jinak jméno z nejnovějšího dokladu s tím IČO. Totéž pravidlo jako counterparty_resolve.label, množinově pro přehledy.';

REVOKE ALL ON FUNCTION public.counterparty_labels(text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.counterparty_labels(text[]) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/counterparty_resolve.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: counterparty_resolve
-- Popis: rozřeší PROTISTRANU na její identitu v modelu — jeden tvar pro oba
--        vstupy karty protistrany:
--          { debtor: IČO | jméno }   ← řádek přehledu dlužníků (row_kind counterparty)
--          { twin_id: uuid }         ← twin firmy (registr nájemců, identita)
--        Vrací IČO (icos), jména z dokladů (names) a twiny firmy (twins).
--
-- ⭐ TWIN JE ENTITA, IČO JE PARAMETR (majitel 2026-07-26). Karta proto nestojí
--    na řetězci IČO — ukazuje, KOLIK twinů danou identitu nese: naměřeno
--    2026-09-23 na <fork>-instanci, ze 102 dlužníků po splatnosti má 27 právě jeden twin,
--    42 VÍC twinů se stejným IČO (duplicita dvou identit ingestu téhož zdroje)
--    a 33 žádný. Roztříštěná identita je nález, který se má ukázat, ne schovat.
--
-- ⛔ JMÉNO NENÍ IDENTITA: totéž jméno nese víc IČO (různé firmy) a firma se
--    přejmenovává. Doklady se proto berou podle IČO; podle jména JEN ty, které
--    IČO nemají (fyzické osoby, doklady bez IČO) — viz counterparty_docs.
--    Návrhy `company_name` u twinů jsou zašuměné (u IČO ETRK s.r.o. stojí
--    „Moravská nemovitostní a.s." — jméno NAŠÍ firmy), proto se jména berou
--    z dokladů, ne z návrhů.
--
-- twins: [{id, label, certainty}] — certainty 'confirmed' = vazbu IČO potvrdil
--        člověk, 'proposed' = navrhl stroj (fronta identifikace), 'derived' =
--        twin BEZ IČO, jehož jméno v dokladech nese jen tahle firma (druhá
--        identita téže firmy — nález „ke sjednocení", ne sloučení; sjednocuje
--        člověk přes ingest_navrhy).
-- label: SCHVÁLENÝ název (company_name potvrzený člověkem, platný teď); dočasně bez
--        schválení jméno z nejnovějšího dokladu s IČO firmy; teprve pak název dvojčete.
-- SECURITY INVOKER: viditelnost rozhoduje RLS. ⛔ Proto se filtruje přes GENEROVANÉ
--    sloupce registru (counterparty_id_value, counterparty_value), ne přes výraz nad
--    `fields`: výraz nad jsonb není leakproof, pod RLS jde za politiku a index nepoužije
--    (naměřeno riq 2026-09-29: 2 706 ms jako admin, 23 ms jako service_role).
-- ROWS 1 = PRAVDA, ne ladění: závěrečný SELECT jsou jen skalární poddotazy BEZ FROM,
--    takže funkce vrací VŽDY právě jeden řádek. Výchozí ROWS 1000 lhal: volající
--    `id × counterparty_docs(...)` odhadl na 1 000 000 řádků (skutečně 0–stovky) →
--    karta 676 317, aging 810 514, web 305 974 → plný JIT (naměřeno riq 2026-09-30:
--    karta 1,8–2,8 s s JIT, 14–240 ms bez). S ROWS 1: 4 038 / 811 / 4 606, md5 36/36.
--    Kdo sem přidá FROM nebo SETOF, MUSÍ ROWS změnit — hlídá výjimka v bráně
--    predikat-naroku-vychozi-cost a runtime test odhad-karty-protistrany.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.counterparty_resolve(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS TABLE (icos text[], names text[], twins jsonb, label text)
LANGUAGE sql
STABLE
SECURITY INVOKER
ROWS 1
SET search_path TO 'public', 'pg_temp'
AS $$
  with vstup as (
    select nullif(btrim(p_params->>'debtor'), '') as debtor,
           case when coalesce(p_params->>'twin_id', '')
                     ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                then (p_params->>'twin_id')::uuid end as twin_id
  ),
  -- ⛔ DVOJČATA SE ČTOU JEN VE SDÍLENÝCH MNOŽINÁCH (2026-09-30, riq, člen 7f2a3dd3):
  -- každý výskyt twin_entities / twin_external_refs v dotazu nese vlastní výpočet
  -- rozsahu uživatele v RLS (twin_ids_v_rozsahu, ~120 ms, Postgres ho mezi výskyty
  -- nesdílí). Resolve jich měl 4 (EXPLAIN ANALYZE: 487 z 642 ms), karta člena 37×.
  -- Proto: v_ent/v_ref (vstup twin_id), ref_ico → ent → ref_ent (firma) — každá
  -- jednou, MATERIALIZED; větve níž berou z nich. Při vstupu {debtor} je twin_id
  -- NULL → index v_ent/v_ref nevrátí nic a politika se vůbec nevyhodnotí.
  v_ent as materialized (
    select t.id, t.label
      from public.twin_entities t
     where t.id = (select twin_id from vstup)
  ),
  v_ref as materialized (
    select r.source_key
      from public.twin_external_refs r
     where r.twin_id = (select twin_id from vstup)
       and r.ref_kind = 'company_ico' and r.state <> 'rejected'
  ),
  -- IČO: z twinu (vazby company_ico, kromě zamítnutých), nebo dlužník sám, je-li to IČO
  ico as (
    select distinct r.source_key as ico from v_ref r
    union
    select v.debtor from vstup v where v.debtor ~ '^[0-9]{6,8}$'
    union
    -- Twin BEZ vazby IČO (druhá identita ingestu, klíčovaná jménem): IČO z dokladů
    -- se jménem = label twinu — jen když to jméno nese JEDINÉ IČO. Zrcadlo
    -- jmena_jednoznacna níž: z twinu bez IČO musí karta i Ask dojít k týmž
    -- fakturám jako z twinu s IČO (naměřeno 2026-09-25: Ask trefil twin bez IČO
    -- a o dluhu nevěděl nic).
    select min(r.counterparty_id_value)
      from v_ent t
      join public.li_source_registry r
        on r.superseded_by is null and r.counterparty_value = t.label
     where r.counterparty_id_value is not null
       and not exists (select 1 from v_ref)
    having count(distinct r.counterparty_id_value) = 1
  ),
  -- jméno bez IČO: dlužník, který není IČO, nebo label twinu bez vazby IČO
  jmeno_vstup as (
    select v.debtor as jmeno from vstup v where v.debtor is not null and v.debtor !~ '^[0-9]{6,8}$'
    union
    select t.label from v_ent t
     where not exists (select 1 from ico)
  ),
  -- DOKLADY s IČO firmy — JEDNOU (MATERIALIZED): z téže množiny jména v čase
  -- (jmena) i jméno z nejnovějšího dokladu (aktualni). ⛔ Každý výskyt registru
  -- v dotazu nese vlastní vyhodnocení politiky RLS (u člena li_doc_slugs_claimed_by,
  -- riq 2026-09-29 ~5,4 s za výskyt; Postgres stejné poddotazy mezi výskyty
  -- neslučuje) — dva výskyty téže množiny = dvojí cena.
  doklady_ico as materialized (
    select r.counterparty_value as jmeno,
           coalesce(r.fields->'issue_date'->>'value', r.created_at::date::text) as datum,
           r.created_at
      from public.li_source_registry r
     where r.superseded_by is null
       and r.counterparty_id_value in (select ico from ico)
  ),
  -- jména z DOKLADŮ s daným IČO (jména v čase), plus jméno ze vstupu
  jmena as (
    select distinct d.jmeno from doklady_ico d where d.jmeno is not null
    union
    select jmeno from jmeno_vstup where jmeno is not null
  ),
  -- Jména, která v dokladech nese JEN tahle firma: žádný platný doklad s tím
  -- jménem nemá jiné IČO. Jméno sdílené víc firmami twin nepřipojí (⛔ jméno
  -- není identita) — jednoznačné jméno ale je důkaz, že twin bez IČO se týmž
  -- jménem je DRUHÁ identita téže firmy (dva ingesty téhož zdroje, naměřeno
  -- 2026-09-25 na Inspiraci: twin s IČO + twin bez IČO nesoucí jedinou smlouvu).
  jmena_jednoznacna as (
    select j.jmeno from jmena j
     where exists (select 1 from ico)
       and not exists (
         select 1 from public.li_source_registry r
          where r.superseded_by is null
            and r.counterparty_value = j.jmeno
            and r.counterparty_id_value is not null
            and r.counterparty_id_value not in (select ico from ico))
  ),
  -- Firma v dvojčatech — tři sdílené množiny místo čtení v každé větvi (viz v_ent):
  -- vazby IČO → dvojčata firmy (podle vazby nebo jména) → jejich vazby.
  ref_ico as materialized (
    select r.twin_id, r.state
      from public.twin_external_refs r
     where r.ref_kind = 'company_ico' and r.state <> 'rejected'
       and r.source_key in (select ico from ico)
  ),
  ent as materialized (
    select t.id, t.label
      from public.twin_entities t
     where t.entity_type = 'company' and t.status = 'active'
       and (t.id in (select twin_id from ref_ico)
            or t.label in (select jmeno from jmeno_vstup)
            or t.label in (select jmeno from jmena_jednoznacna))
  ),
  ref_ent as materialized (
    select r.twin_id, r.ref_kind, r.state, r.source_key, r.valid_from, r.valid_to, r.confirmed_at
      from public.twin_external_refs r
     -- pole, ne `in (select … union …)`: bez odhadu velikosti planner volil sekvenční
     -- průchod celé tabulky (riq 2026-09-30: +150 ms); `= any(pole)` jde po indexu twin_id
     where r.twin_id = any(array(select id from ent union select id from v_ent))
       and r.ref_kind in ('company_ico', 'company_name', 'nase_firma')
  ),
  -- twiny firmy: nesoucí některé z IČO, nebo (bez IČO) se shodným labelem, nebo zadaný
  tw as (
    select t.id, t.label,
           case when bool_or(r.state = 'confirmed') then 'confirmed' else 'proposed' end as certainty
      from ref_ico r
      join ent t on t.id = r.twin_id
     group by t.id, t.label
    union
    select t.id, t.label, 'derived'
      from ent t
     where not exists (select 1 from ico)
       and t.label in (select jmeno from jmeno_vstup)
    union
    -- twin BEZ vazby IČO se jménem, které nese jen tahle firma → odvozeno ze jména
    select t.id, t.label, 'derived'
      from ent t
     where t.label in (select jmeno from jmena_jednoznacna)
       and not exists (select 1 from ref_ent r
                        where r.twin_id = t.id and r.ref_kind = 'company_ico' and r.state <> 'rejected')
    union
    select t.id, t.label, 'confirmed'
      from v_ent t
  ),
  -- ⭐ JMÉNO FIRMY (majitel 2026-09-28): platí SCHVÁLENÝ název — company_name, který
  -- potvrdil člověk (platný teď). Změna jména na dokladu je NÁVRH ingestu, ne pravda,
  -- dokud ji člověk neschválí. Do té doby (dnes schválených jen 17 jmen, 2 193 návrhů
  -- čeká) je DOČASNOU zálohou jméno z nejnovějšího dokladu s IČO firmy, teprve pak
  -- název dvojčete — naměřeno: z 1 518 firem s IČO má 181 název jiný než poslední jméno
  -- z dokladů, 53 ADRESU („Petrská 1426/1" místo SFR Motor s.r.o.), 28 samotné IČO.
  aktualni as (
    select btrim(d.jmeno) as jmeno
      from doklady_ico d
     where length(btrim(coalesce(d.jmeno, ''))) between 2 and 80
     order by d.datum desc, d.created_at desc
     limit 1
  ),
  twu as (
    select id, min(label) as label,
           case when bool_or(certainty = 'confirmed') then 'confirmed'
                when bool_or(certainty = 'proposed') then 'proposed' else 'derived' end as certainty
      from tw group by id
  )
  , schvalene as (
    select r.source_key as jmeno
      from ref_ent r
     -- `nase_firma` = potvrzená naše firma (agenda zdroje) — její jméno je schválené
     where r.ref_kind in ('company_name', 'nase_firma') and r.state = 'confirmed'
       and r.twin_id in (select id from twu)
       and (r.valid_from is null or r.valid_from <= now())
       and (r.valid_to is null or r.valid_to > now())
     order by r.valid_from desc nulls last, r.confirmed_at desc nulls last
     limit 1
  )
  select
    coalesce((select array_agg(ico order by ico) from ico where ico is not null), '{}'::text[]),
    coalesce((select array_agg(jmeno order by jmeno) from jmena), '{}'::text[]),
    coalesce((select jsonb_agg(jsonb_build_object('id', id, 'label', label, 'certainty', certainty) order by label, id) from twu), '[]'::jsonb),
    coalesce((select jmeno from schvalene),
             (select jmeno from aktualni),
             (select label from twu order by (certainty = 'confirmed') desc, label limit 1),
             (select jmeno from jmeno_vstup limit 1),
             (select min(jmeno) from jmena),
             (select debtor from vstup));
$$;

REVOKE ALL ON FUNCTION public.counterparty_resolve(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.counterparty_resolve(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_ai_task.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_ai_task
-- Arguments: p_task_type text, p_input jsonb DEFAULT '{}'::jsonb
-- Security: SECURITY DEFINER
-- Source: Phase 4 — Agent Loop & Memory

CREATE OR REPLACE FUNCTION public.create_ai_task(p_task_type text, p_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $$
DECLARE
  v_task_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  INSERT INTO ai_tasks (user_id, task_type, input)
  VALUES (auth.uid(), p_task_type, p_input)
  RETURNING id INTO v_task_id;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'AI_TASK_CREATED', jsonb_build_object(
    'area', 'ai', 'severity', 'info',
    'task_id', v_task_id::text, 'task_type', p_task_type
  ));

  RETURN jsonb_build_object('task_id', v_task_id, 'status', 'queued');
END;
$$;

REVOKE ALL ON FUNCTION public.create_ai_task(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_ai_task(text, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_consultation_booking_audited.sql
-- -----------------------------------------------------------------------------

-- Function: create_consultation_booking_audited
-- Purpose: Create a new consultation booking, auto-create story, audit log

CREATE OR REPLACE FUNCTION create_consultation_booking_audited(
  p_specialist_id uuid,
  p_duration_hours numeric DEFAULT 4,
  p_scheduled_start timestamptz DEFAULT NULL,
  p_description text DEFAULT '',
  p_tags text[] DEFAULT '{}',
  p_preferred_communication text DEFAULT 'written',
  p_urgency text DEFAULT 'normal'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_member_id uuid;
  v_pricing RECORD;
  v_price numeric(10,2);
  v_booking_id uuid;
  v_story_id uuid;
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- 1. Get specialist pricing
  SELECT sp.*, pp.user_id AS specialist_user_id, pp.display_name
  INTO v_pricing
  FROM specialist_pricing sp
  JOIN partner_profiles pp ON pp.id = sp.partner_id
  WHERE sp.partner_id = p_specialist_id
    AND sp.is_active = true;

  IF v_pricing IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Specialist pricing not found or inactive');
  END IF;

  -- 2. Validate duration meets minimum
  IF p_duration_hours < v_pricing.min_block_hours THEN
    RETURN jsonb_build_object('success', false, 'error',
      'Minimum block is ' || v_pricing.min_block_hours || ' hours');
  END IF;

  -- 3. Check specialist capacity
  IF (SELECT COUNT(*) FROM consultation_bookings
      WHERE specialist_id = p_specialist_id
        AND status IN ('confirmed', 'in_progress'))
     >= v_pricing.max_concurrent_projects THEN
    RETURN jsonb_build_object('success', false, 'error', 'Specialist at capacity');
  END IF;

  -- 4. Calculate price
  v_price := ROUND(v_pricing.hourly_rate * p_duration_hours, 2);

  -- 5. Create story for this consultation
  INSERT INTO partner_stories (
    partner_id, user_id, title, status, priority, origin, delivery_status
  ) VALUES (
    p_specialist_id, v_member_id,
    'Konzultace s ' || v_pricing.display_name,
    'inbox', 'normal', 'marketplace', 'analyzing'
  )
  RETURNING id INTO v_story_id;

  -- 6. Create booking
  INSERT INTO consultation_bookings (
    member_id, specialist_id, story_id,
    scheduled_start,
    scheduled_end,
    duration_hours, price, currency, status
  ) VALUES (
    v_member_id, p_specialist_id, v_story_id,
    p_scheduled_start,
    CASE WHEN p_scheduled_start IS NOT NULL
      THEN p_scheduled_start + (p_duration_hours || ' hours')::interval
      ELSE NULL END,
    p_duration_hours, v_price, v_pricing.currency, 'pending_payment'
  )
  RETURNING id INTO v_booking_id;

  -- 7. Create booking requirements
  INSERT INTO booking_requirements (
    booking_id, description, tags, preferred_communication, urgency
  ) VALUES (
    v_booking_id, p_description, p_tags, p_preferred_communication, p_urgency
  );

  -- 8. Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_member_id,
    'BOOKING_CREATED',
    jsonb_build_object(
      'area', 'marketplace',
      'severity', 'info',
      'entity_type', 'consultation_booking',
      'entity_id', v_booking_id,
      'specialist_id', p_specialist_id,
      'price', v_price,
      'duration_hours', p_duration_hours
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'booking_id', v_booking_id,
    'story_id', v_story_id,
    'price', v_price,
    'currency', v_pricing.currency
  );
END;
$$;

REVOKE ALL ON FUNCTION create_consultation_booking_audited(uuid,numeric,timestamptz,text,text[],text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION create_consultation_booking_audited(uuid,numeric,timestamptz,text,text[],text,text) TO authenticated;
GRANT EXECUTE ON FUNCTION create_consultation_booking_audited(uuid,numeric,timestamptz,text,text[],text,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_discussion_entry_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: public.create_discussion_entry_audited
-- Popis: Generic "discussion under any content node" post primitive. Any
--        authenticated member can thread a comment under a DISCUSSABLE subject
--        (news_article, knowledge_topic, web_page, story). Validates the subject
--        exists + is discussable per subject_type, enforces same-subject
--        threading, and audits. Replaces per-type comment tables with one
--        polymorphic story_entries row (subject_type, subject_id).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT; auth.uid() required.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.create_discussion_entry_audited(
  p_subject_type text,
  p_subject_id   uuid,
  p_content      text,
  p_entry_type   text  DEFAULT 'comment',
  p_parent_id    uuid  DEFAULT NULL,
  p_metadata     jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id  uuid;
  v_ok       boolean := false;
  v_entry_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_content IS NULL OR length(btrim(p_content)) = 0 THEN
    RAISE EXCEPTION 'Empty discussion content';
  END IF;

  -- Validate the subject exists AND is discussable (publicly readable) per type.
  -- subject_id is polymorphic (no FK) so this is the integrity gate.
  CASE p_subject_type
    WHEN 'news_article' THEN
      SELECT true INTO v_ok FROM public.news_articles  WHERE id = p_subject_id AND is_published;
    WHEN 'knowledge_topic' THEN
      SELECT true INTO v_ok FROM public.knowledge_topics WHERE id = p_subject_id AND visibility IN ('public','members');
    WHEN 'web_page' THEN
      -- draft web_pages are admin-only (web_pages.status: draft|published); a member must
      -- not comment on an unpublished page even if they guess its UUID. Mirrors the sibling
      -- per-type publication gates (news_article -> is_published).
      SELECT true INTO v_ok FROM public.web_pages       WHERE id = p_subject_id AND status = 'published';
    WHEN 'story' THEN
      SELECT true INTO v_ok FROM public.partner_stories WHERE id = p_subject_id;
    ELSE
      RAISE EXCEPTION 'Unsupported subject_type: %', p_subject_type;
  END CASE;

  IF NOT COALESCE(v_ok, false) THEN
    RAISE EXCEPTION 'Subject not found or not discussable: % %', p_subject_type, p_subject_id;
  END IF;

  -- The post TYPE must be a registered, ACTIVE type valid for this subject —
  -- types are template/config-driven via entry_type_definitions (stack ships the
  -- universals; implementations add their own). Keeps entry_type from drifting.
  PERFORM 1 FROM public.entry_type_definitions d
    WHERE d.entry_type = COALESCE(p_entry_type, 'comment')
      AND d.is_active
      AND (cardinality(d.applies_to) = 0 OR p_subject_type = ANY(d.applies_to));
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unknown or inapplicable entry_type: % (subject %)',
      COALESCE(p_entry_type, 'comment'), p_subject_type;
  END IF;

  -- Threading: a reply must target an entry on the SAME subject.
  IF p_parent_id IS NOT NULL THEN
    PERFORM 1 FROM public.story_entries
      WHERE id = p_parent_id AND subject_type = p_subject_type AND subject_id = p_subject_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Parent entry % is not on this subject', p_parent_id;
    END IF;
  END IF;

  INSERT INTO public.story_entries (
    subject_type, subject_id, story_id, parent_id, entry_type, content, metadata, status, is_internal, created_by
  ) VALUES (
    p_subject_type, p_subject_id,
    CASE WHEN p_subject_type = 'story' THEN p_subject_id ELSE NULL END,
    p_parent_id, COALESCE(p_entry_type, 'comment'), p_content, COALESCE(p_metadata, '{}'::jsonb),
    'visible', false, v_user_id
  )
  RETURNING id INTO v_entry_id;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, metadata)
  VALUES (
    v_user_id, 'discussion_entry.created', 'create', 'member',
    jsonb_build_object(
      'entry_id', v_entry_id,
      'subject_type', p_subject_type,
      'subject_id', p_subject_id,
      'is_reply', p_parent_id IS NOT NULL
    )
  );

  RETURN v_entry_id;
END;
$$;

REVOKE ALL ON FUNCTION public.create_discussion_entry_audited(text, uuid, text, text, uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_discussion_entry_audited(text, uuid, text, text, uuid, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.create_discussion_entry_audited(text, uuid, text, text, uuid, jsonb) TO service_role;


