-- Function: create_lab_test_order
-- Description: Create a new lab test order from AI recommendations
-- Created: 2026-02-03

CREATE OR REPLACE FUNCTION create_lab_test_order(
  p_tests jsonb,
  p_story_id uuid DEFAULT NULL,
  p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid;
  v_order_id uuid;
  v_total_price numeric(10,2);
BEGIN
  -- Get current user
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Validate tests array
  IF p_tests IS NULL OR jsonb_array_length(p_tests) = 0 THEN
    RAISE EXCEPTION 'At least one test is required';
  END IF;

  -- Calculate total price from tests array
  SELECT COALESCE(SUM((test->>'price')::numeric), 0)
  INTO v_total_price
  FROM jsonb_array_elements(p_tests) AS test;

  -- Create order
  INSERT INTO lab_test_orders (
    user_id,
    tests,
    story_id,
    metadata,
    total_price,
    status
  )
  VALUES (
    v_user_id,
    p_tests,
    p_story_id,
    p_metadata,
    v_total_price,
    'pending'
  )
  RETURNING id INTO v_order_id;

  -- Audit log
  INSERT INTO audit_journal (
    user_id,
    action,
    metadata
  )
  VALUES (
    v_user_id,
    'LAB_TEST_ORDER_CREATED',
    jsonb_build_object(
      'area', 'lab_tests',
      'severity', 'info',
      'order_id', v_order_id,
      'test_count', jsonb_array_length(p_tests),
      'total_price', v_total_price
    )
  );

  RETURN v_order_id;
END;
$$;

-- Security
REVOKE ALL ON FUNCTION create_lab_test_order(jsonb, uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION create_lab_test_order(jsonb, uuid, jsonb) TO authenticated;

COMMENT ON FUNCTION create_lab_test_order(jsonb, uuid, jsonb) IS 'Create a new lab test order with audit logging';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_member_distribution_plan_on_registration.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_member_distribution_plan_on_registration
-- Arguments: (none)
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:05+01:00

CREATE OR REPLACE FUNCTION public.create_member_distribution_plan_on_registration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_protocol RECORD;
  v_subscription_id UUID;
BEGIN
  -- Only trigger for 'enrolled' or 'active' status
  IF NEW.status NOT IN ('enrolled', 'active') THEN
    RETURN NEW;
  END IF;
  
  -- Check if plan already exists
  IF EXISTS (SELECT 1 FROM member_distribution_plans WHERE user_id = NEW.user_id AND study_registration_id = NEW.id) THEN
    RETURN NEW;
  END IF;
  
  -- Get active subscription
  SELECT id INTO v_subscription_id
  FROM member_subscriptions
  WHERE user_id = NEW.user_id AND status = 'active'
  ORDER BY period_end DESC
  LIMIT 1;
  
  -- Create plan for each protocol in the study
  FOR v_protocol IN
    SELECT id, duration_days FROM study_distribution_protocols
    WHERE study_id = NEW.study_id AND is_active = true
  LOOP
    INSERT INTO member_distribution_plans (
      user_id,
      study_registration_id,
      subscription_id,
      protocol_id,
      starts_at,
      ends_at
    ) VALUES (
      NEW.user_id,
      NEW.id,
      v_subscription_id,
      v_protocol.id,
      CURRENT_DATE,
      CASE 
        WHEN v_protocol.duration_days IS NOT NULL 
        THEN CURRENT_DATE + v_protocol.duration_days
        ELSE NULL
      END
    );
  END LOOP;
  
  RETURN NEW;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.create_member_distribution_plan_on_registration() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_member_distribution_plan_on_registration() TO authenticated;


