-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/current_device_kid.sql
-- -----------------------------------------------------------------------------

-- Function: current_device_kid
-- `kid` tabletu, jehož relací volající právě jedná — z claimu `device_kid` tokenu,
-- který vydává gateway (/auth/v1/device/session). Claim se NEBERE na slovo: platí jen,
-- když průkaz s tím kid patří účtu volajícího a je platný. Jinak NULL (člověk, nebo
-- podvržený claim). Zapisuje se do záznamu příběhu a auditu odbavení („na kterém
-- tabletu k předání došlo“).
CREATE OR REPLACE FUNCTION public.current_device_kid()
  RETURNS text
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_kid text;
BEGIN
  BEGIN
    v_kid := nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'device_kid';
  EXCEPTION WHEN others THEN
    RETURN NULL;
  END;
  IF v_kid IS NULL OR auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;
  RETURN (SELECT d.kid FROM public.knock_device_credentials d
           WHERE d.kid = v_kid
             AND d.ucet_id = auth.uid()
             AND d.druh = 'tablet'
             AND d.approved_at IS NOT NULL
             AND d.revoked_at IS NULL
             AND (d.plati_do IS NULL OR d.plati_do > now()));
END;
$function$;

REVOKE ALL ON FUNCTION public.current_device_kid() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.current_device_kid() TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/db_diagnose.sql
-- -----------------------------------------------------------------------------

-- Function: public.db_diagnose
-- Arguments: (none)
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:20+01:00

CREATE OR REPLACE FUNCTION public.db_diagnose()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_issues jsonb := '[]'::jsonb;
  v_tables_without_rls INTEGER;
BEGIN
  -- Check extensions
  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pgcrypto') THEN
    v_issues := v_issues || jsonb_build_object(
      'severity', 'critical',
      'type', 'extension',
      'message', 'pgcrypto extension is missing'
    );
  END IF;

  -- Check RLS
  SELECT COUNT(*) INTO v_tables_without_rls
  FROM pg_tables t
  LEFT JOIN pg_class c ON t.tablename = c.relname AND c.relnamespace = 'public'::regnamespace
  WHERE t.schemaname = 'public'
  AND t.tablename NOT LIKE 'pg_%'
  AND (c.relrowsecurity IS NULL OR c.relrowsecurity = false);

  IF v_tables_without_rls > 0 THEN
    v_issues := v_issues || jsonb_build_object(
      'severity', 'critical',
      'type', 'security',
      'message', format('%s tables without RLS enabled', v_tables_without_rls)
    );
  END IF;

  -- Check required roles
  IF NOT EXISTS (SELECT 1 FROM public.roles WHERE name = 'admin') THEN
    v_issues := v_issues || jsonb_build_object(
      'severity', 'high',
      'type', 'data',
      'message', 'Admin role is missing'
    );
  END IF;

  -- Return result
  RETURN jsonb_build_object(
    'healthy', jsonb_array_length(v_issues) = 0,
    'issues_count', jsonb_array_length(v_issues),
    'issues', v_issues,
    'checked_at', NOW()
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.db_diagnose() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.db_diagnose() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/db_self_repair.sql
-- -----------------------------------------------------------------------------

-- Function: public.db_self_repair
-- Arguments: (none)
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:20+01:00

CREATE OR REPLACE FUNCTION public.db_self_repair()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_repairs jsonb := '[]'::jsonb;
  v_repair_count INTEGER := 0;
  v_start_time TIMESTAMPTZ := NOW();
BEGIN
  -- CHECK: Default supported languages
  IF NOT EXISTS (SELECT 1 FROM public.supported_languages WHERE code = 'cs') THEN
    BEGIN
      INSERT INTO public.supported_languages (code, name_native, name_key, is_default, is_active, sort_order)
      VALUES ('cs', 'Čeština', 'languages.czech', false, true, 1);
      v_repairs := v_repairs || jsonb_build_object('type', 'data', 'table', 'supported_languages', 'value', 'cs', 'action', 'inserted');
      v_repair_count := v_repair_count + 1;
    EXCEPTION WHEN OTHERS THEN
      -- user_id = auth.uid() (nullable): the '00000000-…0000' sentinel is not a
      -- real aisha_auth.users row → it violated audit_journal_user_id_fkey.
      INSERT INTO audit_journal(user_id, action, metadata)
      VALUES (
        auth.uid(),
        'SELF_REPAIR_FAILED',
        jsonb_build_object(
          'severity', 'error',
          'table', 'supported_languages',
          'value', 'cs',
          'error', SQLERRM
        )
      );
    END;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.supported_languages WHERE code = 'en') THEN
    BEGIN
      INSERT INTO public.supported_languages (code, name_native, name_key, is_default, is_active, sort_order)
      VALUES ('en', 'English', 'languages.english', true, true, 2);
      v_repairs := v_repairs || jsonb_build_object('type', 'data', 'table', 'supported_languages', 'value', 'en', 'action', 'inserted');
      v_repair_count := v_repair_count + 1;
    EXCEPTION WHEN OTHERS THEN
      -- user_id = auth.uid() (nullable): the '00000000-…0000' sentinel is not a
      -- real aisha_auth.users row → it violated audit_journal_user_id_fkey.
      INSERT INTO audit_journal(user_id, action, metadata)
      VALUES (
        auth.uid(),
        'SELF_REPAIR_FAILED',
        jsonb_build_object(
          'severity', 'error',
          'table', 'supported_languages',
          'value', 'en',
          'error', SQLERRM
        )
      );
    END;
  END IF;

  -- 'global' is the locale-axis FK sentinel (knowledge_items/chunks/embeddings
  -- default locale='global'). Existing DBs must converge it BEFORE the locale FK
  -- ALTER lands, else every knowledge_* write 23503-fails. Mirrors the cs/en arms.
  IF NOT EXISTS (SELECT 1 FROM public.supported_languages WHERE code = 'global') THEN
    BEGIN
      INSERT INTO public.supported_languages (code, name_native, name_key, is_active, is_default, sort_order)
      VALUES ('global', 'Global', 'languages.global.name', true, false, 0);
      v_repairs := v_repairs || jsonb_build_object('type', 'data', 'table', 'supported_languages', 'value', 'global', 'action', 'inserted');
      v_repair_count := v_repair_count + 1;
    EXCEPTION WHEN OTHERS THEN
      -- user_id = auth.uid() (nullable): the '00000000-…0000' sentinel is not a
      -- real aisha_auth.users row → it violated audit_journal_user_id_fkey.
      INSERT INTO audit_journal(user_id, action, metadata)
      VALUES (
        auth.uid(),
        'SELF_REPAIR_FAILED',
        jsonb_build_object(
          'severity', 'error',
          'table', 'supported_languages',
          'value', 'global',
          'error', SQLERRM
        )
      );
    END;
  END IF;

  -- Return summary
  RETURN jsonb_build_object(
    'success', true,
    'repairs_count', v_repair_count,
    'repairs', v_repairs,
    'duration_ms', EXTRACT(MILLISECOND FROM (NOW() - v_start_time)),
    'timestamp', NOW()
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.db_self_repair() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.db_self_repair() FROM anon;
REVOKE EXECUTE ON FUNCTION public.db_self_repair() FROM authenticated;
GRANT EXECUTE ON FUNCTION public.db_self_repair() TO aisha_admin;
GRANT EXECUTE ON FUNCTION public.db_self_repair() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/deactivate_github_app_repositories.sql
-- -----------------------------------------------------------------------------

-- Function: public.deactivate_github_app_repositories
-- Named, audited replacement for the raw_query_admin update in
-- svc-github-app/routes/webhook-bridge.ts — marks repos removed from a GitHub App
-- installation as inactive (soft delete). Called on installation_repositories
-- (removed) webhooks.
-- Security: SECURITY DEFINER (service_role-invoked via rpcService), search_path pinned.

CREATE OR REPLACE FUNCTION public.deactivate_github_app_repositories(
  p_installation_id bigint,
  p_repo_ids bigint[]
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF p_installation_id IS NULL THEN
    RAISE EXCEPTION 'installation_id is required' USING ERRCODE = 'check_violation';
  END IF;

  IF p_repo_ids IS NULL OR array_length(p_repo_ids, 1) IS NULL THEN
    RETURN; -- nothing to deactivate
  END IF;

  UPDATE public.github_app_repositories
     SET is_active = false,
         updated_at = now()
   WHERE installation_id = p_installation_id
     AND repo_id = ANY (p_repo_ids);
END;
$function$;

COMMENT ON FUNCTION public.deactivate_github_app_repositories(bigint, bigint[]) IS
  'Soft-deactivates repos removed from a GitHub App installation (is_active=false).';

REVOKE ALL ON FUNCTION public.deactivate_github_app_repositories(bigint, bigint[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.deactivate_github_app_repositories(bigint, bigint[]) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/deactivate_web_push_subscriptions_by_endpoints.sql
-- -----------------------------------------------------------------------------

-- Function: public.deactivate_web_push_subscriptions_by_endpoints
-- Arguments: p_endpoints text[], p_reason text
-- Description: Internal helper to disable invalid browser push endpoints.
-- Security: SECURITY DEFINER. Intended for service_role callers only.

CREATE OR REPLACE FUNCTION public.deactivate_web_push_subscriptions_by_endpoints(
  p_endpoints text[],
  p_reason text DEFAULT NULL::text
)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
BEGIN
  IF p_endpoints IS NULL OR array_length(p_endpoints, 1) IS NULL THEN
    RETURN 0;
  END IF;

  UPDATE public.web_push_subscriptions
  SET
    is_active = false,
    last_error_at = now(),
    last_error_reason = COALESCE(NULLIF(trim(p_reason), ''), 'remote_endpoint_invalid'),
    updated_at = now()
  WHERE endpoint = ANY(p_endpoints)
    AND is_active = true;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$;

REVOKE ALL ON FUNCTION public.deactivate_web_push_subscriptions_by_endpoints(text[], text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.deactivate_web_push_subscriptions_by_endpoints(text[], text) TO service_role;


-- -----------------------------------------------------------------------------
