-- -----------------------------------------------------------------------------

-- Function: delete_featured_product_admin
-- Description: Delete featured product (admin only)
-- Security: SECURITY DEFINER with admin check + audit
-- Created: 2026-02-03

CREATE OR REPLACE FUNCTION delete_featured_product_admin(
  p_id uuid
)
RETURNS bool
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
BEGIN
  -- Authorization check
  IF NOT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = auth.uid()
    AND role IN ('admin', 'staff')
  ) THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff role required';
  END IF;

  -- Delete
  DELETE FROM featured_products WHERE id = p_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Featured product not found: %', p_id;
  END IF;

  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'ADMIN_DELETE',
    jsonb_build_object(
      'area', 'featured_products',
      'entity_id', p_id,
      'severity', 'warning'
    )
  );

  RETURN true;
END;
$$;

-- Security
REVOKE ALL ON FUNCTION delete_featured_product_admin(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION delete_featured_product_admin(uuid) TO authenticated;

COMMENT ON FUNCTION delete_featured_product_admin(uuid) IS 'Delete featured product configuration (admin only)';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/delete_notification.sql
-- -----------------------------------------------------------------------------

-- Function: public.delete_notification
-- Arguments: p_notification_id uuid
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:22+01:00

CREATE OR REPLACE FUNCTION public.delete_notification(p_notification_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_was_unread BOOLEAN;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT NOT is_read INTO v_was_unread
  FROM notifications
  WHERE id = p_notification_id AND user_id = v_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Notification not found or access denied';
  END IF;

  DELETE FROM notifications
  WHERE id = p_notification_id AND user_id = v_user_id;

  RETURN json_build_object('success', true, 'was_unread', COALESCE(v_was_unread, false));
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.delete_notification(p_notification_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.delete_notification(p_notification_id uuid) TO authenticated;


