-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/connector_write_audit.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: connector_write_audit
-- Popis: THE single deterministic v2-hash audit writer for the whole connector
--        substrate (connector doctrine: one hash site, exact inverse of
--        fn_verify_audit_journal_entry). Source-neutral: every connector state
--        change — read, ingest, control write-back, identity federation — audits
--        through here, so provenance is symmetric across all connectors.
--
-- p_source_ref (a story-spine reference, e.g. story_id::text) is folded into the
-- metadata ONLY when non-null, so callers that pass none (hub_write_audit) get a
-- byte-identical row+hash to before. The hash commits over the STORED columns
-- (metadata WITHOUT blockchain_hash) — see fn_verify_audit_journal_entry.
--
-- Internal-only: REVOKEd from PUBLIC; called from other SECURITY DEFINER connector
-- procs running as owner. Never a direct external write path.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.connector_write_audit(
  p_action        text,
  p_action_type   text,
  p_area          text,
  p_severity      text,
  p_summary       text,
  p_entity_type   text,
  p_entity_id     text,
  p_new_data      jsonb   DEFAULT NULL,
  p_actor         uuid    DEFAULT NULL,
  p_source_ref    text    DEFAULT NULL,
  p_extra_metadata jsonb  DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
  v_id        uuid;
  v_now       timestamptz := now();
  v_actor     uuid := p_actor;
  v_user_role text;
  v_metadata  jsonb;
  v_hash      text;
BEGIN
  -- Defensive actor resolution: audit_journal.user_id FKs aisha_auth.users; a
  -- not-yet-provisioned actor would 23503 and roll back the audited operation.
  IF v_actor IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM aisha_auth.users u WHERE u.id = v_actor) THEN
    v_actor := NULL;
  END IF;
  IF v_actor IS NOT NULL THEN
    SELECT ur.role::text INTO v_user_role
    FROM public.user_roles ur WHERE ur.user_id = v_actor LIMIT 1;
  END IF;

  v_metadata := jsonb_build_object(
    'area', p_area,
    'severity', p_severity,
    'summary', p_summary,
    'user_role', v_user_role
  ) || COALESCE(p_extra_metadata, '{}'::jsonb);
  IF p_source_ref IS NOT NULL THEN
    v_metadata := v_metadata || jsonb_build_object('source_ref', p_source_ref);
  END IF;

  v_hash := 'v2:' || encode(extensions.digest(convert_to(jsonb_build_object(
    'schema', 'aisha.audit_journal.hash.v2',
    'action', p_action,
    'entity_type', p_entity_type,
    'entity_id', p_entity_id,
    'created_at_epoch_us', (extract(epoch FROM v_now) * 1000000)::bigint,
    'new_data', p_new_data,
    'metadata', v_metadata
  )::text, 'UTF8'), 'sha256'), 'hex');

  INSERT INTO public.audit_journal (
    user_id, action_type, action, area, severity, summary,
    entity_type, entity_id, new_data, metadata, blockchain_hash, created_at
  ) VALUES (
    v_actor, p_action_type, p_action, p_area, p_severity, p_summary,
    p_entity_type, p_entity_id, p_new_data,
    v_metadata || jsonb_build_object('blockchain_hash', v_hash),
    v_hash, v_now
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.connector_write_audit(text, text, text, text, text, text, text, jsonb, uuid, text, jsonb) FROM PUBLIC;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/disable_agent_runtime.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: disable_agent_runtime
-- Purpose: De-provision a marketplace agent's runtime when its plugin_catalog
--          row is disabled/archived (the operator kill-switch). Deactivates the
--          materialized agent_catalog row + its global bindings — NOT a delete,
--          so ai_runs / audit history that reference the slug stay intact.
--          route_task already filters is_active=true, so deactivation removes
--          routability immediately.
-- Called from transition_plugin_status when a kind='agent' plugin moves to
-- 'disabled'/'archived'. Idempotent (no-op if already disabled / never materialized).
-- Security: SECURITY DEFINER, service_role only.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.disable_agent_runtime(p_plugin_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_catalog_id uuid;
  v_agent_slug text;
BEGIN
  UPDATE public.agent_catalog
     SET is_active = false, updated_at = now()
   WHERE source_plugin_id = p_plugin_id
   RETURNING id, slug INTO v_catalog_id, v_agent_slug;

  IF v_agent_slug IS NULL THEN
    -- never materialized (e.g. executable agent) → nothing to disable
    RETURN jsonb_build_object('disabled', false, 'plugin_id', p_plugin_id);
  END IF;

  UPDATE public.agent_knowledge_bindings
     SET is_active = false, updated_at = now()
   WHERE agent_slug = v_agent_slug AND story_id IS NULL;

  -- Audit (auth.uid() may be NULL in service context — FK-safe).
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'AGENT_RUNTIME_DISABLED', jsonb_build_object(
    'area', 'marketplace', 'severity', 'info',
    'plugin_id', p_plugin_id, 'agent_slug', v_agent_slug
  ));

  RETURN jsonb_build_object('disabled', true, 'agent_slug', v_agent_slug);
END;
$$;

COMMENT ON FUNCTION public.disable_agent_runtime(uuid) IS
  'Deactivate a marketplace agent''s materialized agent_catalog row + bindings on plugin disable/archive. Idempotent; service_role only.';

REVOKE ALL ON FUNCTION public.disable_agent_runtime(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.disable_agent_runtime(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/deactivate_plugin_runtime.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: deactivate_plugin_runtime — the kill-switch dispatcher.
--
-- Counterpart of materialize_plugin: when a plugin is disabled/archived, its
-- materialized runtime rows are switched off — ONLY rows this plugin owns
-- (source_plugin_id), so a shared slug never lets one plugin's kill-switch
-- darken a built-in or another plugin's row. Rows are disabled, never deleted:
-- provenance and operator forensics survive, and re-approval re-materializes
-- without resurrecting operator-disabled trust boundaries (each materializer's
-- ON CONFLICT leaves is_enabled untouched for auth/tracking).
-- Security: SECURITY DEFINER, service_role only.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.deactivate_plugin_runtime(p_plugin_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_pc       record;
  v_counts   jsonb := '{}'::jsonb;
  v_n        int;
BEGIN
  SELECT id, slug, kind::text AS kind INTO v_pc
    FROM public.plugin_catalog WHERE id = p_plugin_id;

  IF v_pc.id IS NULL THEN
    RAISE EXCEPTION 'Plugin not found: %', p_plugin_id USING ERRCODE = 'P0002';
  END IF;

  -- Agents have a dedicated disabler (bindings + catalog row semantics).
  IF v_pc.kind IN ('agent', 'full_stack') THEN
    PERFORM public.disable_agent_runtime(p_plugin_id);
    v_counts := v_counts || jsonb_build_object('agent', 'disable_agent_runtime called');
  END IF;

  UPDATE public.ai_provider_registry SET is_enabled = false, updated_at = now()
   WHERE source_plugin_id = p_plugin_id AND is_enabled;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_counts := v_counts || jsonb_build_object('providers_disabled', v_n); END IF;

  UPDATE public.custom_node_registry SET is_active = false, updated_at = now()
   WHERE source_plugin_id = p_plugin_id AND is_active;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_counts := v_counts || jsonb_build_object('nodes_disabled', v_n); END IF;

  UPDATE public.auth_provider_registry SET is_enabled = false, updated_at = now()
   WHERE source_plugin_id = p_plugin_id AND is_enabled;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_counts := v_counts || jsonb_build_object('idps_disabled', v_n); END IF;

  UPDATE public.web_tracking_registry SET is_enabled = false, updated_at = now()
   WHERE source_plugin_id = p_plugin_id AND is_enabled;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_counts := v_counts || jsonb_build_object('trackers_disabled', v_n); END IF;

  UPDATE public.agent_knowledge_sources SET is_active = false, updated_at = now()
   WHERE source_plugin_id = p_plugin_id AND is_active;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_counts := v_counts || jsonb_build_object('sources_deactivated', v_n); END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'PLUGIN_RUNTIME_DEACTIVATED', jsonb_build_object(
    'area', 'marketplace', 'severity', 'warning',
    'plugin_id', p_plugin_id, 'plugin_slug', v_pc.slug, 'kind', v_pc.kind,
    'effects', v_counts
  ));

  RETURN jsonb_build_object('plugin_slug', v_pc.slug, 'kind', v_pc.kind, 'effects', v_counts);
END;
$$;

COMMENT ON FUNCTION public.deactivate_plugin_runtime(uuid) IS
  'Kill-switch dispatcher: disable every runtime row a plugin owns (source_plugin_id) across all registries. Disables, never deletes. service_role only.';

REVOKE ALL ON FUNCTION public.deactivate_plugin_runtime(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.deactivate_plugin_runtime(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/document_sensitivity_min_tier.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: document_sensitivity_min_tier
-- Popis: Mapování třídy dokumentu (document_registry.sensitivity) na MINIMÁLNÍ
--        úroveň tazatele v existujícím audience žebříku
--        (anonymous < registered < active < qualified < partner < admin).
--        Doktrína: úroveň se POČÍTÁ z dění (audience_compute_actor_tier),
--        nepřiděluje se; tenhle převod je jediné místo, kde se třída dokumentu
--        potkává s žebříkem. Vyhodnocení dělá audience_user_meets_tier_requirement
--        (fail-closed: neznámý uživatel = anonymous).
-- Fail-closed: neznámá/NULL třída → 'admin' (nepromovaný nebo neznámý dokument
--        nesmí být viditelný nikomu pod adminem).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.document_sensitivity_min_tier(p_sensitivity text)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT CASE p_sensitivity
    WHEN 'public'       THEN 'registered'   -- každý přihlášený vázaný účet
    WHEN 'internal'     THEN 'active'       -- spočtená aktivita, ne jmenovka
    WHEN 'restricted'   THEN 'qualified'
    WHEN 'confidential' THEN 'admin'
    ELSE 'admin'                            -- fail-closed (NULL / neznámá třída)
  END;
$$;

REVOKE ALL ON FUNCTION public.document_sensitivity_min_tier(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.document_sensitivity_min_tier(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.document_sensitivity_min_tier(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_app_versions.sql
-- -----------------------------------------------------------------------------

-- Function: public.edge_app_versions
-- Purpose: Edge-safe mobile app version reads.

CREATE OR REPLACE FUNCTION public.edge_app_versions(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_platform text;
  v_row jsonb;
BEGIN
  IF p_action = 'get_platform' THEN
    v_platform := lower(COALESCE(p_payload ->> 'platform', 'ios'));
    IF v_platform NOT IN ('ios', 'android') THEN
      v_platform := 'ios';
    END IF;

    SELECT jsonb_build_object(
      'created_at', a.created_at,
      'features', a.features,
      'id', a.id,
      'latest_version', a.latest_version,
      'maintenance_enabled', a.maintenance_enabled,
      'maintenance_end', a.maintenance_end,
      'maintenance_message', a.maintenance_message,
      'min_version', a.min_version,
      'platform', a.platform,
      'store_url', a.store_url,
      'updated_at', a.updated_at
    )
    INTO v_row
    FROM public.app_versions a
    WHERE a.platform = v_platform
    LIMIT 1;

    RETURN jsonb_build_object('row', v_row);
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_app_versions(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edge_app_versions(text, jsonb) TO anon;
GRANT EXECUTE ON FUNCTION public.edge_app_versions(text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.edge_app_versions(text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_blockchain_audit.sql
-- -----------------------------------------------------------------------------

-- Function: public.edge_blockchain_audit
-- Purpose: Edge-safe blockchain audit queue helpers.

CREATE OR REPLACE FUNCTION public.edge_blockchain_audit(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF p_action = 'count_requests' THEN
    RETURN jsonb_build_object(
      'count',
      (
        SELECT count(*)
        FROM public.audit_journal a
        WHERE a.user_id = NULLIF(p_payload ->> 'user_id', '')::uuid
          AND a.action_type = 'integration'
          AND a.area = 'blockchain'
          AND a.entity_type = 'blockchain_audit'
          AND a.created_at >= COALESCE(NULLIF(p_payload ->> 'since', '')::timestamptz, now() - interval '1 hour')
      )
    );
  END IF;

  IF p_action = 'insert_record' THEN
    INSERT INTO public.blockchain_audit_records (
      data,
      record_hash,
      record_type
    )
    VALUES (
      jsonb_build_object(
        'created_by', NULLIF(p_payload ->> 'created_by', '')::uuid,
        'event_type', NULLIF(p_payload ->> 'event_type', ''),
        'payload', COALESCE(p_payload -> 'payload', '{}'::jsonb),
        'reference_id', NULLIF(p_payload ->> 'reference_id', ''),
        'reference_table', NULLIF(p_payload ->> 'reference_table', ''),
        'status', 'pending'
      ),
      NULLIF(p_payload ->> 'payload_hash', ''),
      NULLIF(p_payload ->> 'event_type', '')
    )
    RETURNING id INTO v_id;

    RETURN jsonb_build_object('id', v_id, 'ok', true);
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_blockchain_audit(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edge_blockchain_audit(text, jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.edge_blockchain_audit(text, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_payment_sessions.sql
-- -----------------------------------------------------------------------------

-- Function: public.edge_payment_sessions
-- Purpose: Edge-safe payment session writes.

CREATE OR REPLACE FUNCTION public.edge_payment_sessions(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF p_action = 'insert' THEN
    INSERT INTO public.payment_sessions (
      amount,
      currency,
      expires_at,
      metadata,
      reference_id,
      reference_type,
      session_type,
      status,
      stripe_session_id,
      user_id
    )
    VALUES (
      NULLIF(p_payload ->> 'amount', '')::numeric,
      COALESCE(NULLIF(p_payload ->> 'currency', ''), public.commerce_base_currency()),
      NULLIF(p_payload ->> 'expires_at', '')::timestamptz,
      COALESCE(p_payload -> 'metadata', '{}'::jsonb),
      NULLIF(p_payload ->> 'reference_id', ''),
      NULLIF(p_payload ->> 'reference_type', ''),
      NULLIF(p_payload ->> 'session_type', ''),
      COALESCE(NULLIF(p_payload ->> 'status', ''), 'pending'),
      NULLIF(p_payload ->> 'stripe_session_id', ''),
      NULLIF(p_payload ->> 'user_id', '')::uuid
    )
    RETURNING id INTO v_id;

    RETURN jsonb_build_object('id', v_id, 'ok', true);
  END IF;

  IF p_action = 'update_status' THEN
    UPDATE public.payment_sessions
    SET
      completed_at = CASE WHEN p_payload ? 'completed_at' THEN NULLIF(p_payload ->> 'completed_at', '')::timestamptz ELSE completed_at END,
      status = COALESCE(NULLIF(p_payload ->> 'status', ''), status),
      updated_at = now()
    WHERE stripe_session_id = NULLIF(p_payload ->> 'stripe_session_id', '');

    RETURN jsonb_build_object('ok', true, 'updated', FOUND);
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_payment_sessions(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edge_payment_sessions(text, jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.edge_payment_sessions(text, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_public_partners_directory.sql
-- -----------------------------------------------------------------------------

-- Function: public.edge_public_partners_directory
-- Purpose: Edge-safe helpers for partners directory endpoint.

CREATE OR REPLACE FUNCTION public.edge_public_partners_directory(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_city text;
  v_limit integer;
BEGIN
  IF p_action = 'count_requests_authenticated' THEN
    RETURN jsonb_build_object(
      'count',
      (
        SELECT count(*)
        FROM public.audit_journal a
        WHERE a.action_type = 'view'
          AND a.area = 'partners'
          AND a.entity_type = 'partner_profiles'
          AND a.summary = COALESCE(NULLIF(p_payload ->> 'summary', ''), 'Partners directory queried')
          AND a.user_id = NULLIF(p_payload ->> 'user_id', '')::uuid
          AND a.created_at >= COALESCE(NULLIF(p_payload ->> 'since', '')::timestamptz, now() - interval '1 hour')
      )
    );
  END IF;

  IF p_action = 'count_requests_anonymous' THEN
    RETURN jsonb_build_object(
      'count',
      (
        SELECT count(*)
        FROM public.audit_journal a
        WHERE a.action_type = 'view'
          AND a.area = 'partners'
          AND a.entity_type = 'partner_profiles'
          AND a.summary = COALESCE(NULLIF(p_payload ->> 'summary', ''), 'Partners directory queried (anonymous)')
          AND (a.details ->> 'ip_hash') = NULLIF(p_payload ->> 'ip_hash', '')
          AND a.created_at >= COALESCE(NULLIF(p_payload ->> 'since', '')::timestamptz, now() - interval '1 hour')
      )
    );
  END IF;

  IF p_action = 'count_visible' THEN
    RETURN jsonb_build_object(
      'count',
      (
        SELECT count(*)
        FROM public.partner_profiles_public p
        WHERE p.is_visible = true
      )
    );
  END IF;

  IF p_action = 'get_partners' THEN
    v_city := NULLIF(btrim(COALESCE(p_payload ->> 'city', '')), '');
    v_limit := COALESCE(NULLIF(p_payload ->> 'limit', '')::integer, 20);
    v_limit := GREATEST(1, LEAST(100, v_limit));

    IF COALESCE((p_payload ->> 'authenticated')::boolean, false) THEN
      RETURN jsonb_build_object(
        'rows',
        COALESCE(
          (
            SELECT jsonb_agg(
              jsonb_build_object(
                'accepts_in_person_appointments', p.accepts_in_person_appointments,
                'accepts_online_appointments', p.accepts_online_appointments,
                'avatar_url', p.avatar_url,
                'business_name', p.business_name,
                'certification_level', p.certification_level,
                'certification_passed_at', p.certification_passed_at,
                'certification_score', p.certification_score,
                'city', p.city,
                'country', p.country,
                'created_at', p.created_at,
                'description', p.description,
                'display_name', p.display_name,
                'id', p.id,
                'is_production_provider', p.is_production_provider,
                'is_visible', p.is_visible,
                'services', p.services,
                'user_id', p.user_id,
                'website', p.website
              )
            )
            FROM (
              SELECT
                p.accepts_in_person_appointments,
                p.accepts_online_appointments,
                p.avatar_url,
                p.business_name,
                p.certification_level,
                p.certification_passed_at,
                p.certification_score,
                p.city,
                p.country,
                p.created_at,
                p.description,
                p.display_name,
                p.id,
                p.is_production_provider,
                p.is_visible,
                p.services,
                p.user_id,
                p.website
              FROM public.partner_profiles_public p
              WHERE p.is_visible = true
                AND (v_city IS NULL OR p.city = v_city)
              ORDER BY p.certification_level DESC, p.display_name
              LIMIT v_limit
            ) p
          ),
          '[]'::jsonb
        )
      );
    END IF;

    RETURN jsonb_build_object(
      'rows',
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'accepts_in_person_appointments', p.accepts_in_person_appointments,
              'accepts_online_appointments', p.accepts_online_appointments,
              'avatar_url', p.avatar_url,
              'certification_level', p.certification_level,
              'city', p.city,
              'country', p.country,
              'display_name', p.display_name,
              'id', p.id,
              'is_production_provider', p.is_production_provider
            )
          )
          FROM (
            SELECT
              p.accepts_in_person_appointments,
              p.accepts_online_appointments,
              p.avatar_url,
              p.certification_level,
              p.city,
              p.country,
              p.display_name,
              p.id,
              p.is_production_provider
            FROM public.partner_profiles_public p
            WHERE p.is_visible = true
              AND (v_city IS NULL OR p.city = v_city)
            ORDER BY p.certification_level DESC, p.display_name
            LIMIT v_limit
          ) p
        ),
        '[]'::jsonb
      )
    );
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_public_partners_directory(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edge_public_partners_directory(text, jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.edge_public_partners_directory(text, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_sms_otp.sql
-- -----------------------------------------------------------------------------

-- Function: public.edge_sms_otp
-- Purpose: Edge-safe OTP reads and writes.

CREATE OR REPLACE FUNCTION public.edge_sms_otp(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_phone text;
  v_code text;
  v_hash text;
  v_row record;
  v_row_json jsonb;
  v_attempts integer;
BEGIN
  IF p_action = 'upsert' THEN
    v_phone := NULLIF(p_payload ->> 'phone', '');
    v_code := NULLIF(p_payload ->> 'code', '');
    IF v_phone IS NULL THEN
      RAISE EXCEPTION 'Missing phone';
    END IF;
    IF v_code IS NULL THEN
      RAISE EXCEPTION 'Missing code';
    END IF;

    v_hash := extensions.crypt(v_code, extensions.gen_salt('bf'));

    INSERT INTO public.sms_otp_codes (
      code_hash,
      expires_at,
      phone,
      verified
    )
    VALUES (
      v_hash,
      NULLIF(p_payload ->> 'expires_at', '')::timestamptz,
      v_phone,
      COALESCE((p_payload ->> 'verified')::boolean, false)
    )
    ON CONFLICT (phone) DO UPDATE
    SET
      attempts = 0,
      code_hash = EXCLUDED.code_hash,
      expires_at = EXCLUDED.expires_at,
      updated_at = now(),
      verified = EXCLUDED.verified;

    RETURN jsonb_build_object('ok', true);
  END IF;

  IF p_action = 'verify' THEN
    v_phone := NULLIF(p_payload ->> 'phone', '');
    v_code := NULLIF(p_payload ->> 'code', '');
    IF v_phone IS NULL THEN
      RAISE EXCEPTION 'Missing phone';
    END IF;
    IF v_code IS NULL THEN
      RAISE EXCEPTION 'Missing code';
    END IF;

    SELECT
      s.attempts,
      s.code_hash,
      s.expires_at,
      s.verified
    INTO v_row
    FROM public.sms_otp_codes s
    WHERE s.phone = v_phone
    LIMIT 1;

    IF v_row IS NULL THEN
      RETURN jsonb_build_object('valid', false, 'error', 'not_found');
    END IF;

    IF v_row.verified THEN
      RETURN jsonb_build_object('valid', false, 'error', 'already_used');
    END IF;

    IF v_row.expires_at < now() THEN
      RETURN jsonb_build_object('valid', false, 'error', 'expired');
    END IF;

    IF COALESCE(v_row.attempts, 0) >= 3 THEN
      UPDATE public.sms_otp_codes
      SET verified = true, updated_at = now()
      WHERE phone = v_phone;
      RETURN jsonb_build_object('valid', false, 'error', 'max_attempts');
    END IF;

    IF extensions.crypt(v_code, v_row.code_hash) = v_row.code_hash THEN
      UPDATE public.sms_otp_codes
      SET verified = true, updated_at = now()
      WHERE phone = v_phone;
      RETURN jsonb_build_object('valid', true);
    END IF;

    v_attempts := COALESCE(v_row.attempts, 0) + 1;
    UPDATE public.sms_otp_codes
    SET attempts = v_attempts, updated_at = now()
    WHERE phone = v_phone;

    IF v_attempts >= 3 THEN
      UPDATE public.sms_otp_codes
      SET verified = true, updated_at = now()
      WHERE phone = v_phone;
      RETURN jsonb_build_object(
        'valid', false,
        'error', 'max_attempts',
        'attempts_remaining', 0
      );
    END IF;

    RETURN jsonb_build_object(
      'valid', false,
      'error', 'invalid_code',
      'attempts_remaining', 3 - v_attempts
    );
  END IF;

  IF p_action = 'get' THEN
    v_phone := NULLIF(p_payload ->> 'phone', '');
    IF v_phone IS NULL THEN
      RAISE EXCEPTION 'Missing phone';
    END IF;

    SELECT jsonb_build_object(
      'attempts', s.attempts,
      'expires_at', s.expires_at,
      'phone', s.phone,
      'verified', s.verified
    )
    INTO v_row_json
    FROM public.sms_otp_codes s
    WHERE s.phone = v_phone
    LIMIT 1;

    RETURN jsonb_build_object('row', v_row_json);
  END IF;

  IF p_action = 'update' THEN
    v_phone := NULLIF(p_payload ->> 'phone', '');
    IF v_phone IS NULL THEN
      RAISE EXCEPTION 'Missing phone';
    END IF;

    UPDATE public.sms_otp_codes
    SET
      attempts = CASE WHEN p_payload ? 'attempts' THEN NULLIF(p_payload ->> 'attempts', '')::integer ELSE attempts END,
      updated_at = now(),
      verified = CASE WHEN p_payload ? 'verified' THEN (p_payload ->> 'verified')::boolean ELSE verified END
    WHERE phone = v_phone;

    RETURN jsonb_build_object('ok', true, 'updated', FOUND);
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_sms_otp(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edge_sms_otp(text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_stripe_disputes.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.edge_stripe_disputes(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_dispute_id uuid;
  v_stripe_dispute_id text;
  v_order_id uuid;
  v_result jsonb;
BEGIN
  -- ========== UPSERT DISPUTE ==========
  IF p_action = 'upsert_dispute' THEN
    v_stripe_dispute_id := NULLIF(p_payload ->> 'stripe_dispute_id', '');
    IF v_stripe_dispute_id IS NULL THEN
      RAISE EXCEPTION 'Missing stripe_dispute_id';
    END IF;

    INSERT INTO public.stripe_disputes (
      amount,
      currency,
      evidence_due_by,
      is_charge_refundable,
      metadata,
      order_id,
      reason,
      status,
      stripe_charge_id,
      stripe_dispute_id,
      stripe_payment_intent_id,
      user_id
    ) VALUES (
      COALESCE((p_payload ->> 'amount')::bigint, 0),
      COALESCE(p_payload ->> 'currency', public.commerce_base_currency()),
      CASE WHEN p_payload ? 'evidence_due_by' THEN (p_payload ->> 'evidence_due_by')::timestamptz ELSE NULL END,
      COALESCE((p_payload ->> 'is_charge_refundable')::boolean, false),
      COALESCE(p_payload -> 'metadata', '{}'::jsonb),
      CASE WHEN p_payload ? 'order_id' THEN (p_payload ->> 'order_id')::uuid ELSE NULL END,
      p_payload ->> 'reason',
      COALESCE(p_payload ->> 'status', 'needs_response'),
      COALESCE(p_payload ->> 'stripe_charge_id', ''),
      v_stripe_dispute_id,
      p_payload ->> 'stripe_payment_intent_id',
      CASE WHEN p_payload ? 'user_id' THEN (p_payload ->> 'user_id')::uuid ELSE NULL END
    )
    ON CONFLICT (stripe_dispute_id) DO UPDATE SET
      amount = COALESCE((p_payload ->> 'amount')::bigint, stripe_disputes.amount),
      closed_at = CASE WHEN p_payload ? 'closed_at' THEN (p_payload ->> 'closed_at')::timestamptz ELSE stripe_disputes.closed_at END,
      evidence_due_by = CASE WHEN p_payload ? 'evidence_due_by' THEN (p_payload ->> 'evidence_due_by')::timestamptz ELSE stripe_disputes.evidence_due_by END,
      is_charge_refundable = COALESCE((p_payload ->> 'is_charge_refundable')::boolean, stripe_disputes.is_charge_refundable),
      metadata = COALESCE(p_payload -> 'metadata', stripe_disputes.metadata),
      reason = COALESCE(p_payload ->> 'reason', stripe_disputes.reason),
      status = COALESCE(p_payload ->> 'status', stripe_disputes.status),
      updated_at = now()
    RETURNING id INTO v_dispute_id;

    RETURN jsonb_build_object('ok', true, 'dispute_id', v_dispute_id);
  END IF;

  -- ========== UPDATE DISPUTE STATUS ==========
  IF p_action = 'update_status' THEN
    v_stripe_dispute_id := NULLIF(p_payload ->> 'stripe_dispute_id', '');
    IF v_stripe_dispute_id IS NULL THEN
      RAISE EXCEPTION 'Missing stripe_dispute_id';
    END IF;

    UPDATE public.stripe_disputes
    SET
      closed_at = CASE WHEN p_payload ? 'closed_at' THEN (p_payload ->> 'closed_at')::timestamptz ELSE closed_at END,
      status = COALESCE(p_payload ->> 'status', status),
      updated_at = now()
    WHERE stripe_dispute_id = v_stripe_dispute_id
    RETURNING order_id INTO v_order_id;

    -- Also update order dispute_status if linked
    IF v_order_id IS NOT NULL THEN
      UPDATE public.orders
      SET
        dispute_status = COALESCE(p_payload ->> 'status', dispute_status),
        updated_at = now()
      WHERE id = v_order_id;
    END IF;

    RETURN jsonb_build_object('ok', true, 'updated', FOUND);
  END IF;

  -- ========== FIND ORDER BY PAYMENT INTENT ==========
  IF p_action = 'find_order_by_payment_intent' THEN
    SELECT jsonb_build_object(
      'order_id', o.id,
      'user_id', o.user_id
    ) INTO v_result
    FROM public.orders o
    WHERE o.stripe_payment_intent_id = (p_payload ->> 'stripe_payment_intent_id')
    LIMIT 1;

    RETURN COALESCE(v_result, jsonb_build_object('order_id', NULL, 'user_id', NULL));
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_stripe_disputes(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edge_stripe_disputes(text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/enforce_rate_limit.sql
-- -----------------------------------------------------------------------------

-- Function: public.enforce_rate_limit
-- Arguments: p_endpoint_key text, p_window_ms integer, p_max_requests integer
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:28+01:00

CREATE OR REPLACE FUNCTION public.enforce_rate_limit(p_endpoint_key text, p_window_ms integer DEFAULT 60000, p_max_requests integer DEFAULT 60)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_current_count INTEGER;
  v_window_end TIMESTAMPTZ;
  v_existing_id UUID;
  v_user_exists BOOLEAN;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  -- Verify user exists in aisha_auth.users before any INSERT to prevent FK violation
  SELECT EXISTS(SELECT 1 FROM aisha_auth.users WHERE id = v_user_id) INTO v_user_exists;
  IF NOT v_user_exists THEN
    RETURN;
  END IF;

  v_window_end := now() + (p_window_ms || ' milliseconds')::INTERVAL;

  -- Check for existing active window
  SELECT id, request_count INTO v_existing_id, v_current_count
  FROM api_rate_limits
  WHERE user_id = v_user_id 
    AND endpoint_key = p_endpoint_key 
    AND window_end > now()
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    -- Increment existing
    UPDATE api_rate_limits 
    SET request_count = request_count + 1
    WHERE id = v_existing_id;
    v_current_count := v_current_count + 1;
  ELSE
    -- Clean up expired and insert fresh
    DELETE FROM api_rate_limits 
    WHERE user_id = v_user_id AND endpoint_key = p_endpoint_key;
    
    INSERT INTO api_rate_limits (user_id, endpoint_key, request_count, window_start, window_end)
    VALUES (v_user_id, p_endpoint_key, 1, now(), v_window_end);
    v_current_count := 1;
  END IF;

  IF v_current_count > p_max_requests THEN
    RAISE EXCEPTION 'Rate limit exceeded for %. Max % requests per % ms.', p_endpoint_key, p_max_requests, p_window_ms;
  END IF;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.enforce_rate_limit(p_endpoint_key text, p_window_ms integer, p_max_requests integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.enforce_rate_limit(p_endpoint_key text, p_window_ms integer, p_max_requests integer) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/enqueue_workbench_request.sql
-- -----------------------------------------------------------------------------

-- Function: enqueue_workbench_request
-- The central adapter (runtime_dispatch → workbenchAdapter.execute) enqueues a unit of
-- work for the aisha-dirigent extension to run on a local model. Returns the request id;
-- the adapter then block-polls fetch_workbench_result. service_role only (the adapter runs
-- as the system). Params alphabetical (rpc-params gate).

CREATE OR REPLACE FUNCTION public.enqueue_workbench_request(
  p_clow          jsonb,
  p_decision_id   uuid    DEFAULT NULL,
  p_input         text    DEFAULT '',
  p_model_id      text    DEFAULT NULL,
  p_provider_slug text    DEFAULT NULL,
  p_run_id        uuid    DEFAULT NULL,
  p_story_id      uuid    DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id uuid;
BEGIN
  IF (current_setting('request.jwt.claims', true)::jsonb ->> 'role') <> 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;

  INSERT INTO workbench_execution_requests
    (clow, request_input, model_id, provider_slug, run_id, story_id, decision_id, status)
  VALUES (p_clow, p_input, p_model_id, p_provider_slug, p_run_id, p_story_id, p_decision_id, 'pending')
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.enqueue_workbench_request(jsonb, uuid, text, text, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.enqueue_workbench_request(jsonb, uuid, text, text, text, uuid, uuid) TO service_role;

COMMENT ON FUNCTION public.enqueue_workbench_request(jsonb, uuid, text, text, text, uuid, uuid) IS
  'PR-J: enqueue a workbench execution request (pending) for the extension to claim+run. service_role only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/enroll_in_study.sql
-- -----------------------------------------------------------------------------

-- Function: public.enroll_in_study
-- Arguments: p_study_id uuid, p_baseline_data jsonb
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:28+01:00

CREATE OR REPLACE FUNCTION public.enroll_in_study(p_study_id uuid, p_baseline_data jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_study RECORD;
  v_existing_registration RECORD;
  v_registration_id UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT id, name INTO v_study FROM studies WHERE id = p_study_id AND is_active = true;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Study not found or not active';
  END IF;

  SELECT id INTO v_existing_registration 
  FROM study_registrations 
  WHERE user_id = v_user_id AND study_id = p_study_id AND status NOT IN ('withdrawn', 'completed');
  
  IF FOUND THEN
    RAISE EXCEPTION 'Already enrolled in this study';
  END IF;

  INSERT INTO study_registrations (user_id, study_id, status, baseline_data)
  VALUES (v_user_id, p_study_id, 'screening', p_baseline_data)
  RETURNING id INTO v_registration_id;

  INSERT INTO audit_journal (user_id, action, action_type, area, entity_type, entity_id, summary, severity, details)
  VALUES (v_user_id, 'ENROLL_STUDY', 'create', 'registrations', 'study_registration', v_registration_id::TEXT, 'User enrolled in study', 'notice',
    jsonb_build_object('study_id', p_study_id, 'study_name', v_study.name));

  RETURN jsonb_build_object('success', true, 'registration_id', v_registration_id);
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.enroll_in_study(p_study_id uuid, p_baseline_data jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.enroll_in_study(p_study_id uuid, p_baseline_data jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/ensure_current_user.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: ensure_current_user
-- Purpose: Just-in-time (JIT) provisioning of the authenticated caller into
--          aisha_auth.users — the "first-request hook" that aisha_auth.users
--          was always documented to expect ("Populated by: keycloak-role-sync,
--          user_upsert triggers, or first-request hooks") but which was never
--          wired for runtime. Without it, a Keycloak user created after the
--          bootstrap import has a valid JWT (aisha_auth.uid() resolves their
--          sub-as-uuid) but NO aisha_auth.users row, so every write to a table
--          with a NOT NULL FK to aisha_auth.users (notification_preferences,
--          push_subscriptions, …) fails with FK violation 23503.
--
--          On first call this INSERTs the row; the AFTER INSERT trigger
--          on_auth_user_created → handle_new_user() then provisions the
--          member role + profile. Idempotent (ON CONFLICT DO NOTHING).
--
-- Returns: the provisioned user's id, or NULL for anonymous/service callers
--          (no JWT subject to provision).
-- Security: SECURITY DEFINER. Runs as the function owner (migration role),
--          which holds INSERT on aisha_auth.users; callers only have SELECT.
--          search_path includes aisha_auth so the cross-schema insert resolves.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.ensure_current_user(
  p_email text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'aisha_auth'
AS $$
DECLARE
  v_uid   uuid := auth.uid();
  v_email text;
BEGIN
  -- No JWT subject (anon / service-without-actor) → nothing to provision.
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;

  -- Already provisioned → fast path, no write.
  IF EXISTS (SELECT 1 FROM aisha_auth.users u WHERE u.id = v_uid) THEN
    RETURN v_uid;
  END IF;

  -- Resolve email best-effort: explicit arg > JWT email claim.
  v_email := COALESCE(
    NULLIF(btrim(COALESCE(p_email, '')), ''),
    NULLIF(auth.jwt() ->> 'email', '')
  );

  -- INSERT the registry anchor. The AFTER INSERT trigger
  -- (on_auth_user_created → handle_new_user) provisions role + profile.
  -- ON CONFLICT guards the race where two concurrent requests both miss the
  -- EXISTS check.
  INSERT INTO aisha_auth.users (id, email, raw_user_meta_data)
  VALUES (
    v_uid,
    v_email,
    jsonb_strip_nulls(jsonb_build_object(
      'provisioned_via', 'ensure_current_user',
      'email', v_email
    ))
  )
  ON CONFLICT (id) DO NOTHING;

  RETURN v_uid;
END;
$$;

REVOKE ALL ON FUNCTION public.ensure_current_user(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.ensure_current_user(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ensure_current_user(text) TO service_role;

COMMENT ON FUNCTION public.ensure_current_user(text) IS
  'JIT-provisions the authenticated caller into aisha_auth.users (first-request hook). Idempotent; trigger handles role+profile. Returns the user id or NULL for anonymous callers.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_pre_request.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: aisha_pre_request  (PostgREST db-pre-request hook)
-- Purpose: Wire the documented "first-request hook" — public.ensure_current_user
--          — as PostgREST's global PGRST_DB_PRE_REQUEST, so EVERY authenticated
--          request JIT-provisions its caller into aisha_auth.users BEFORE the
--          request body runs. Without this, a Keycloak user created after the
--          bootstrap import has a valid JWT (auth.uid() resolves) but no
--          aisha_auth.users row, and the first write to ANY of the ~dozens of
--          tables whose user_id FKs aisha_auth.users (consents, chat_*, health_*,
--          notification_preferences, …) fails with FK 23503 → PostgREST 409.
--          Per-function ensure_current_user() calls only cover the functions that
--          remember to call it (a fragile minority); a single pre-request hook
--          closes the entire class centrally.
--
-- Contract (PostgREST db-pre-request):
--   - runs ONCE before every request, as the request role (anon / authenticated
--     / service_role) — hence EXECUTE is granted to all three;
--   - takes no args, returns void;
--   - MUST NOT raise: any error here fails the whole request. This is wrapped so
--     provisioning is strictly best-effort — a write that still needs the row
--     surfaces its own error, and reads never depend on it.
--
-- Read-only guard: PostgREST GET runs in a READ ONLY transaction; reads never
--   write an FK row, and the ensure_current_user INSERT would error there. We
--   skip provisioning on read-only transactions (the EXCEPTION block is a
--   second backstop).
--
-- Security: SECURITY DEFINER so the body may call ensure_current_user (and thus
--   INSERT into aisha_auth.users) regardless of the request role's own grants.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.aisha_pre_request()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'aisha_auth'
AS $$
BEGIN
  -- Reads (read-only tx) never need provisioning and cannot INSERT — skip.
  IF current_setting('transaction_read_only', true) = 'on' THEN
    RETURN;
  END IF;

  -- JIT-provision the authenticated caller. Idempotent (fast EXISTS path);
  -- returns NULL for anon / service callers with no JWT subject (a no-op).
  PERFORM public.ensure_current_user();
EXCEPTION WHEN OTHERS THEN
  -- Never block a request on best-effort provisioning.
  NULL;
END;
$$;

REVOKE ALL ON FUNCTION public.aisha_pre_request() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aisha_pre_request() TO anon;
GRANT EXECUTE ON FUNCTION public.aisha_pre_request() TO authenticated;
GRANT EXECUTE ON FUNCTION public.aisha_pre_request() TO service_role;

COMMENT ON FUNCTION public.aisha_pre_request() IS
  'PostgREST db-pre-request hook (set PGRST_DB_PRE_REQUEST=public.aisha_pre_request). JIT-provisions the authenticated caller via ensure_current_user before every request so FK-to-aisha_auth.users writes never 409; no-op on read-only tx and for anon. Exception-safe — never blocks a request.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/ensure_leaderboard_periods.sql
-- -----------------------------------------------------------------------------

-- Function: public.ensure_leaderboard_periods
-- Arguments: (none)
-- Description: Helper function to ensure leaderboard periods exist.
-- Security: Internal helper - called by scheduled jobs.
-- @internal: true

CREATE OR REPLACE FUNCTION public.ensure_leaderboard_periods()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_week_start DATE;
  v_week_end DATE;
  v_month_start DATE;
  v_month_end DATE;
BEGIN
  v_week_start := date_trunc('week', CURRENT_DATE)::DATE;
  v_week_end := (date_trunc('week', CURRENT_DATE) + INTERVAL '6 days')::DATE;
  v_month_start := date_trunc('month', CURRENT_DATE)::DATE;
  v_month_end := (date_trunc('month', CURRENT_DATE) + INTERVAL '1 month - 1 day')::DATE;

  INSERT INTO leaderboard_periods (period_type, period_start, period_end)
  VALUES ('weekly', v_week_start, v_week_end)
  ON CONFLICT (period_type, period_start, period_end) DO NOTHING;

  INSERT INTO leaderboard_periods (period_type, period_start, period_end)
  VALUES ('monthly', v_month_start, v_month_end)
  ON CONFLICT (period_type, period_start, period_end) DO NOTHING;

  INSERT INTO leaderboard_periods (period_type, period_start, period_end)
  VALUES ('all_time', '2020-01-01'::DATE, '2099-12-31'::DATE)
  ON CONFLICT (period_type, period_start, period_end) DO NOTHING;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.ensure_leaderboard_periods() FROM PUBLIC;
