-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/evaluate_story_process_goal.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: evaluate_story_process_goal
-- Popis: StoryLoop nad procesní story: milníky × success_criteria → story_goal_state; nudge JEN při změně fingerprint (goal_met / goal-correction).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- Pozn.: definice = regenerát z nasazené DB (ověřeno provozním testem 07-25).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.evaluate_story_process_goal(p_story_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_criteria jsonb;
  v_per jsonb;
  v_total int; v_completed int; v_failed int;
  v_met boolean;
  v_fp text;
  v_old_fp text;
  v_out jsonb;
begin
  select project_preview->'success_criteria' into v_criteria
  from partner_stories where id = p_story_id;
  if v_criteria is null or jsonb_typeof(v_criteria) <> 'array' then
    return jsonb_build_object('ok',false,'error','story has no success criteria');
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'criterion', c.name,
           'status', coalesce(s.status,'pending')) order by c.ord),'[]'::jsonb),
         count(*), count(*) filter (where s.status='completed'),
         count(*) filter (where s.status='failed')
    into v_per, v_total, v_completed, v_failed
  from jsonb_array_elements_text(v_criteria) with ordinality c(name, ord)
  left join lateral (
    select st.status from production_workflow_steps st
    join production_batches b on b.id = st.batch_id
    where b.story_id = p_story_id and st.step_name = c.name
    order by st.updated_at desc limit 1
  ) s on true;
  v_met := (v_total > 0 and v_completed = v_total);
  v_fp := md5(v_criteria::text || v_per::text);
  v_out := jsonb_build_object('met',v_met,'total',v_total,'completed',v_completed,
                              'failed',v_failed,'per_criterion',v_per);
  select fingerprint into v_old_fp from story_goal_state where story_id = p_story_id;
  insert into story_goal_state (story_id, acceptance_criteria, last_evaluated_at,
                                loop_iterations, fingerprint, last_evaluator_output)
  values (p_story_id, v_criteria, now(), 1, v_fp, v_out)
  on conflict (story_id) do update set
    acceptance_criteria = excluded.acceptance_criteria,
    last_evaluated_at = now(),
    loop_iterations = story_goal_state.loop_iterations + 1,
    fingerprint = excluded.fingerprint,
    last_evaluator_output = excluded.last_evaluator_output,
    updated_at = now();
  -- nudge only on CHANGE (no spam on repeated evaluation of the same state)
  if v_old_fp is distinct from v_fp then
    if v_met then
      insert into dirigent_nudges (story_id, event_origin, severity, message, metadata, expires_at)
      values (p_story_id, 'goal_evaluator', 'info', 'workflow.nudge.goal_met',
              v_out, now() + interval '48 hours');
    elsif v_failed > 0 then
      insert into dirigent_nudges (story_id, event_origin, severity, message, metadata, expires_at)
      values (p_story_id, 'goal_evaluator', 'goal-correction', 'workflow.nudge.goal_correction',
              v_out, now() + interval '48 hours');
    end if;
  end if;
  return jsonb_build_object('ok',true) || v_out;
end $function$;

REVOKE ALL ON FUNCTION public.evaluate_story_process_goal(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.evaluate_story_process_goal(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/evidence_device_geo.sql
-- -----------------------------------------------------------------------------

-- Function: public.evidence_device_geo
-- Arguments: p_device jsonb, p_derived jsonb
-- Security: INVOKER, STABLE — nesahá na žádnou tabulku (STABLE, ne IMMUTABLE:
--           převod textu na timestamptz závisí na TimeZone relace). Volá ji
--           submit_evidence_review_audited (definer); sama není RPC.
--
-- Poloha TABLETU k potvrzení předání → normalizovaný záznam `device_geo`.
--
-- ⭐ ROZHODNUTÍ MAJITELE (2026-09-18). Pravidlo z 2026-07-28 platí dál: DŮKAZNÍ
-- poloha předání se ODVOZUJE (workflow_step_derived_position — signál příjezdu,
-- telematika vozu) a souřadnice od toho, koho záznam dokumentuje, důkaz není.
-- Poloha tabletu je DALŠÍ METAINFORMACE vedle ní: zvyšuje důvěryhodnost záznamu
-- v čase a místě, nikdy nenahrazuje `geo`. Proto má vlastní klíč a `geo_source`
-- začínající `device`, aby se nedala zaměnit s odvozenou polohou.
--
-- ⭐ SHODA DVOU ZDROJŮ je to, co důvěryhodnost skutečně zvyšuje: když má odvozená
-- poloha souřadnice, spočítá se vzdálenost (`agreement_m`, haversine, metry).
-- Samotná poloha tabletu bez druhého zdroje je jen tvrzení zařízení.
--
-- Tvar vstupu (uzavřený; neznámý klíč nebo hodnota = výjimka 22023, stejně
-- jako uzavřená množina klíčů evidence — překlep nesmí tiše zmizet):
--   { lat, lon, accuracy_m?, captured_at }     — naměřená poloha
--   { unavailable: denied|disabled|timeout|error } — poctivá mezera
--   NULL                                        — klient polohu neposlal
CREATE OR REPLACE FUNCTION public.evidence_device_geo(p_device jsonb, p_derived jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', pg_temp
AS $function$
DECLARE
  v_stray  text;
  v_lat    double precision;
  v_lon    double precision;
  v_acc    double precision;
  v_at     timestamptz;
  v_out    jsonb;
  v_dlat   double precision;
  v_dlon   double precision;
  v_a      double precision;
BEGIN
  IF p_device IS NULL OR jsonb_typeof(p_device) = 'null' THEN
    RETURN NULL;
  END IF;
  IF jsonb_typeof(p_device) <> 'object' THEN
    RAISE EXCEPTION 'device_position must be an object' USING errcode = '22023';
  END IF;

  IF p_device ? 'unavailable' THEN
    SELECT string_agg(k, ', ') INTO v_stray FROM jsonb_object_keys(p_device) k WHERE k <> 'unavailable';
    IF v_stray IS NOT NULL THEN
      RAISE EXCEPTION 'device_position.unavailable carries no other keys (got: %)', v_stray USING errcode = '22023';
    END IF;
    IF coalesce(p_device->>'unavailable', '') NOT IN ('denied', 'disabled', 'timeout', 'error') THEN
      RAISE EXCEPTION 'device_position.unavailable must be denied, disabled, timeout or error (got: %)',
        p_device->>'unavailable' USING errcode = '22023';
    END IF;
    RETURN jsonb_build_object('geo_source', 'device_unavailable', 'reason', p_device->>'unavailable');
  END IF;

  SELECT string_agg(k, ', ') INTO v_stray
    FROM jsonb_object_keys(p_device) k
   WHERE k NOT IN ('lat', 'lon', 'accuracy_m', 'captured_at');
  IF v_stray IS NOT NULL THEN
    RAISE EXCEPTION 'unknown device_position key(s): % (allowed: lat, lon, accuracy_m, captured_at)', v_stray
      USING errcode = '22023';
  END IF;

  IF jsonb_typeof(p_device->'lat') IS DISTINCT FROM 'number' OR jsonb_typeof(p_device->'lon') IS DISTINCT FROM 'number' THEN
    RAISE EXCEPTION 'device_position needs numeric lat and lon' USING errcode = '22023';
  END IF;
  v_lat := (p_device->>'lat')::double precision;
  v_lon := (p_device->>'lon')::double precision;
  IF v_lat NOT BETWEEN -90 AND 90 OR v_lon NOT BETWEEN -180 AND 180 THEN
    RAISE EXCEPTION 'device_position out of range (lat %, lon %)', v_lat, v_lon USING errcode = '22023';
  END IF;

  IF p_device ? 'accuracy_m' AND jsonb_typeof(p_device->'accuracy_m') <> 'null' THEN
    IF jsonb_typeof(p_device->'accuracy_m') <> 'number' OR (p_device->>'accuracy_m')::double precision < 0 THEN
      RAISE EXCEPTION 'device_position.accuracy_m must be a non-negative number' USING errcode = '22023';
    END IF;
    v_acc := (p_device->>'accuracy_m')::double precision;
  END IF;

  -- Čas měření je součást tvrzení: poloha bez času neříká, KDY tam tablet byl.
  IF coalesce(p_device->>'captured_at', '') = '' THEN
    RAISE EXCEPTION 'device_position.captured_at is required' USING errcode = '22023';
  END IF;
  BEGIN
    v_at := (p_device->>'captured_at')::timestamptz;
  EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
    RAISE EXCEPTION 'device_position.captured_at is not a timestamp (got: %)', p_device->>'captured_at'
      USING errcode = '22023';
  END;

  v_out := jsonb_strip_nulls(jsonb_build_object(
    'geo_source',  'device',
    'lat',         v_lat,
    'lon',         v_lon,
    'accuracy_m',  v_acc,
    'captured_at', v_at));

  -- Shoda s odvozenou polohou vozu. Jen když ta souřadnice MÁ — `unavailable`
  -- odvození se s ničím neporovnává, jinak by vzniklo číslo z ničeho.
  IF p_derived IS NOT NULL
     AND jsonb_typeof(p_derived->'lat') = 'number' AND jsonb_typeof(p_derived->'lon') = 'number' THEN
    v_dlat := radians((p_derived->>'lat')::double precision - v_lat);
    v_dlon := radians((p_derived->>'lon')::double precision - v_lon);
    v_a := power(sin(v_dlat / 2), 2)
         + cos(radians(v_lat)) * cos(radians((p_derived->>'lat')::double precision)) * power(sin(v_dlon / 2), 2);
    v_out := v_out || jsonb_build_object('agreement_m', round((2 * 6371000 * asin(least(1, sqrt(v_a))))::numeric));
  END IF;

  RETURN v_out;
END;
$function$
;

-- Žádný grant pro `authenticated`: tohle není blokové RPC, klient ho nevolá.
-- Jediná cesta k němu vede přes submit_evidence_review_audited (SECURITY DEFINER).
-- Stejně jako workflow_step_derived_position — výchozí práva Supabase by jinak
-- funkci vystavila v PostgRESTu jako volatelné RPC.
REVOKE ALL ON FUNCTION public.evidence_device_geo(jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.evidence_device_geo(jsonb, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fetch_workbench_result.sql
-- -----------------------------------------------------------------------------

-- Function: fetch_workbench_result
-- The central adapter block-polls this for a request's status/result after enqueue.
-- service_role only. STABLE (read-only).

CREATE OR REPLACE FUNCTION public.fetch_workbench_result(p_request_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_row workbench_execution_requests;
BEGIN
  IF (current_setting('request.jwt.claims', true)::jsonb ->> 'role') <> 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row FROM workbench_execution_requests WHERE id = p_request_id;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Request % not found', p_request_id USING ERRCODE = '22023';
  END IF;

  RETURN jsonb_build_object(
    'request_id', v_row.id,
    'status', v_row.status,
    'output', v_row.response,
    'tokens_in', v_row.tokens_in,
    'tokens_out', v_row.tokens_out,
    'latency_ms', v_row.latency_ms,
    'error_detail', v_row.error_detail
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fetch_workbench_result(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fetch_workbench_result(uuid) TO service_role;

COMMENT ON FUNCTION public.fetch_workbench_result(uuid) IS
  'PR-J: poll a workbench request status/result (the central adapter blocks on this). service_role only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/finish_ai_run.sql
-- -----------------------------------------------------------------------------

-- Function: finish_ai_run
-- Finalizes an ai_runs row: sets terminal status + aggregates cost.
--
-- Cost contract (canonical): cost_total_json = { total, tokens_input,
-- tokens_output, total_duration_ms, event_count }. Two runtime cost paths feed it:
--   - tracer path (insert_ai_trace_event) → per-event cost_json {usd, tokens_in,
--     tokens_out}; aggregated here.
--   - reflection path (appendCost) → live-accumulated cost_total_json on the row.
-- This function PREFERS the event-sourced aggregate but FALLS BACK to the
-- live-accumulated value, so a reflection run (no trace events) is preserved
-- rather than clobbered. The reader (list_active_agent_runs) and the Mission
-- Control board both read cost_total_json->>'total'.

CREATE OR REPLACE FUNCTION public.finish_ai_run(p_run_id uuid, p_status text DEFAULT 'succeeded'::text, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cost     jsonb;
  v_existing jsonb;
BEGIN
  -- Validate status
  IF p_status NOT IN ('succeeded', 'failed', 'canceled', 'blocked') THEN
    RAISE EXCEPTION USING MESSAGE = format('Invalid run status: %s', p_status), ERRCODE = 'P0001';
  END IF;

  -- Live-accumulated cost (reflection appendCost path) — used as fallback so a
  -- run with no trace events keeps its real cost instead of being zeroed.
  SELECT cost_total_json INTO v_existing FROM ai_runs WHERE id = p_run_id;

  -- Aggregate canonical cost from trace events, falling back to the live value.
  SELECT jsonb_build_object(
    'total', COALESCE(
                   NULLIF(SUM(COALESCE((ate.cost_json->>'usd')::numeric, 0)), 0),
                   (v_existing->>'total')::numeric,
                   0),
    'tokens_input', COALESCE(
                   NULLIF(SUM(COALESCE((ate.cost_json->>'tokens_in')::int, 0)), 0),
                   (v_existing->>'tokens_input')::int,
                   0),
    'tokens_output', COALESCE(
                   NULLIF(SUM(COALESCE((ate.cost_json->>'tokens_out')::int, 0)), 0),
                   (v_existing->>'tokens_output')::int,
                   0),
    'total_duration_ms', COALESCE(SUM(ate.duration_ms), 0),
    'event_count', COUNT(*)
  )
  INTO v_cost
  FROM ai_trace_events ate
  WHERE ate.run_id = p_run_id;

  UPDATE ai_runs
  SET
    status = p_status,
    finished_at = now(),
    cost_total_json = COALESCE(v_cost, '{}'::jsonb),
    metadata = CASE
      WHEN p_metadata IS NOT NULL THEN ai_runs.metadata || p_metadata
      ELSE ai_runs.metadata
    END
  WHERE id = p_run_id;
END;
$function$;

REVOKE ALL ON FUNCTION finish_ai_run(uuid, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION finish_ai_run(uuid,text,jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION finish_ai_run(uuid,text,jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fmt_num_cs.sql
-- -----------------------------------------------------------------------------

-- České formátování čísel (mezery po tisících) pro answer_verified_facts.
-- SoT doplněn 2026-07-29 — týž důvod jako norm_text: baseline není zdroj.
CREATE OR REPLACE FUNCTION public.fmt_num_cs(n numeric, p_dec integer DEFAULT 0)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when n is null then '—' else translate(to_char(round(n,p_dec),
    'FM999G999G999G990'|| case when p_dec>0 then 'D'||repeat('0',p_dec) else '' end), ',.', ' ,') end; $function$;

-- Stejná úvaha jako u norm_text: volá se pod právy volajícího (SECURITY INVOKER
-- nadřazené funkce), authenticated grant je nutný; PUBLIC/anon se odebírá.
revoke all on function public.fmt_num_cs(numeric, integer) from public, anon;
grant execute on function public.fmt_num_cs(numeric, integer) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_advise_session_router.sql
-- -----------------------------------------------------------------------------

-- Function: fn_advise_session_router
-- Dirigent router-coach RPC. Given a session id + recent tool-uses array,
-- returns advisory output for the current dev session:
--   - rolling cost (USD over last 2h)
--   - read/write ratio (Read/Grep vs Edit/Write tools)
--   - batch-eligible count (analyze/summarize patterns in recent uses)
--   - suggested slot + suggested model + reasoning
--
-- ADVISORY-ONLY invariant: this never mutates session state. Pure read +
-- compute. Callers are .claude/hooks/* hooks (stderr only, exit 0).

CREATE OR REPLACE FUNCTION public.fn_advise_session_router(
  p_session_id text,
  p_recent_tool_uses jsonb DEFAULT '[]'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_tool_count       int;
  v_read_count       int;
  v_batch_eligible_count int;
  v_read_ratio       numeric;
  v_rolling_cost     numeric;
  v_suggested_slot   text;
  v_suggested_model  text;
  v_suggested_profile text;
  v_reasoning        text;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_tool_count := COALESCE(jsonb_array_length(p_recent_tool_uses), 0);

  -- Tool-use shape: [{ tool, timestamp, input_tokens?, output_tokens? }, ...]
  -- read tools: Read, Grep, Glob, WebFetch, WebSearch
  -- batch-eligible patterns: analyze/summarize-style tool input.command
  IF v_tool_count > 0 THEN
    SELECT
      COUNT(*) FILTER (WHERE (t->>'tool')::text IN ('Read', 'Grep', 'Glob', 'WebFetch', 'WebSearch')),
      COUNT(*) FILTER (
        WHERE (t->'input'->>'command')::text ~* '\y(analyz|summariz|aggregate|report|audit\s+last)\y'
           OR (t->>'tool')::text IN ('WebSearch', 'WebFetch')
      )
    INTO v_read_count, v_batch_eligible_count
    FROM jsonb_array_elements(p_recent_tool_uses) AS t;

    v_read_ratio := (v_read_count::numeric / v_tool_count::numeric);
  ELSE
    v_read_count := 0;
    v_batch_eligible_count := 0;
    v_read_ratio := 0.0;
  END IF;

  -- Rolling cost over last 2h for this session.
  -- ai_trace_events stores cost_json with a USD field per llmRouter convention.
  -- session_id may live in request_summary or response_summary (Dirigent writes
  -- whichever is available in fn_log_dev_signal). We accept either.
  SELECT COALESCE(SUM(
    COALESCE((cost_json->>'usd')::numeric, 0)
  ), 0)
  INTO v_rolling_cost
  FROM public.ai_trace_events
  WHERE created_at > now() - interval '2 hours'
    AND (
      (request_summary->>'session_id') = p_session_id
      OR (response_summary->>'session_id') = p_session_id
    );

  -- Suggested slot from read ratio
  v_suggested_slot := CASE
    WHEN v_read_ratio > 0.65 THEN 'spark'
    WHEN v_read_ratio < 0.30 THEN 'ember'
    ELSE 'default'
  END;

  -- Suggested profile: budget when cost > $0.50, balanced otherwise
  v_suggested_profile := CASE
    WHEN v_rolling_cost > 0.50 THEN 'budget'
    ELSE 'balanced'
  END;

  -- Suggested model: read-heavy + budget cap → flash; else keep current
  v_suggested_model := CASE
    WHEN v_rolling_cost > 0.50 AND v_suggested_slot = 'spark' THEN 'gemini-2.5-flash'
    WHEN v_rolling_cost > 0.50 THEN 'claude-haiku-4-20250514'
    ELSE NULL
  END;

  v_reasoning := format(
    'read_ratio=%.2f over %s tool_uses; rolling_cost=$%s; batch_eligible=%s/%s → slot=%s, profile=%s',
    v_read_ratio, v_tool_count, v_rolling_cost::text,
    v_batch_eligible_count, v_tool_count, v_suggested_slot, v_suggested_profile
  );

  RETURN jsonb_build_object(
    'session_id', p_session_id,
    'tool_count', v_tool_count,
    'read_count', v_read_count,
    'read_ratio', round(v_read_ratio, 3),
    'batch_eligible_count', v_batch_eligible_count,
    'rolling_cost', round(v_rolling_cost, 4),
    'suggested_slot', v_suggested_slot,
    'suggested_profile', v_suggested_profile,
    'suggested_model', v_suggested_model,
    'reasoning', v_reasoning
  );
END;
$$;

COMMENT ON FUNCTION public.fn_advise_session_router(text, jsonb) IS
  'Dirigent advisory router-coach: rolling cost + read/write ratio + batch '
  'eligibility from ai_trace_events for a session. Pure STABLE read; '
  'advisory-only — never mutates session state. Hooks consume via stderr.';

REVOKE ALL ON FUNCTION public.fn_advise_session_router(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_advise_session_router(text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_advise_session_router(text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_ai_runs_default_story.sql
-- -----------------------------------------------------------------------------

-- Function: fn_ai_runs_default_story (BEFORE INSERT trigger on ai_runs)
--
-- Every run belongs to a story. Not "usually" — always. An internal run (a PR
-- gate, a rule-change notification, a fingerprint recalculation) is not an
-- exception to that rule; it belongs to the stack-default story, which is a
-- perfectly ordinary story whose own SoT says so: "Logic is identical to any
-- other story: same table, same lifecycle, same chat-driven UI. Only difference:
-- partner_id IS NULL and is_stack_default = true."
--
-- WHY A TRIGGER AND NOT NINE COALESCEs: ai_runs has NINE writers today
-- (create_ai_run, fn_create_workflow_run, fn_create_improvement_proposal,
-- fn_log_ai_trace_event, fn_notify_rule_change, fn_upsert_agent_live_session,
-- log_n8n_trace_event, recalculate_all_ruleset_fingerprints, route_task).
-- Patching each is nine places to forget and a tenth writer that never learns
-- the rule. A column DEFAULT would not do either: DEFAULT applies only when the
-- column is OMITTED, and most of these pass story_id explicitly as NULL.
-- BEFORE INSERT is the one seam every writer must pass through, and it runs
-- before the NOT NULL check — which is what makes the constraint enforceable
-- rather than aspirational.
--
-- CONSEQUENCE WORTH NAMING: with a story always present,
-- fn_authorize_task_spend(kind, story_id) stops receiving NULL, so internal runs
-- go through the same budget admission as everything else instead of slipping
-- past it. That is the point, not a side effect.

--
-- ⛔ NAMĚŘENO 2026-09-27: kotva VYHLEDÁVÁ, nevolá hlídanou RPC. Verze z 2026-07-26
-- volala `ensure_stack_default_story()` — SECURITY INVOKER s guardem „admin/staff
-- nebo service_role", který čte claims VOLAJÍCÍHO (SECURITY DEFINER tohohle
-- triggeru na tom nic nemění). Od 2026-08-04 (guardy totální, 578285d5d) tak každý
-- oprávněný zapisovatel pod běžnou identitou dostal „Unauthorized" — certifikovaný
-- partner v call-mode `route_task` (grant pro authenticated), agentní testy tržiště
-- padaly i na čistém mainu. Autorizaci ZÁPISU dělá zapisovatel (route_task a spol.),
-- kotva je systémový invariant, ne druhé autorizační místo.
-- Singleton zakládá seed (core/00_setup.sql, kanonická ensure_stack_default_story()
-- pod service_role), takže vyhledání vždy najde; chybí-li, je to vada nasazení —
-- nahlas, ne tiché zakládání pod cizí identitou.
-- JEDEN domov: dřívější zdvojený trigger trg_ai_runs_default_system_story (2026-06-22,
-- týž účel, jen vyhledání) je zrušen v heals.sql.
CREATE OR REPLACE FUNCTION public.fn_ai_runs_default_story()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NEW.story_id IS NULL THEN
    SELECT ps.id INTO NEW.story_id
      FROM public.partner_stories ps
     WHERE ps.is_stack_default = true
     LIMIT 1;
    IF NEW.story_id IS NULL THEN
      RAISE EXCEPTION 'ai_runs: běh bez story a stack-default story chybí — seed core/00_setup.sql (ensure_stack_default_story) neproběhl'
        USING ERRCODE = '23502';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.fn_ai_runs_default_story() IS
  'BEFORE INSERT on ai_runs: a run with no story is anchored to the stack-default story, so story_id can be NOT NULL and every run (internal ones included) passes the same spend admission.';

REVOKE ALL ON FUNCTION public.fn_ai_runs_default_story() FROM PUBLIC;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_anchor_decision.sql
-- -----------------------------------------------------------------------------

-- Function: fn_anchor_decision
-- Cosmos cognition anchor: compose a canonical decision payload from a
-- reflection run, hash it (SHA-256), and queue it into the existing
-- blockchain_audit_records outbox. Cross-chain sync is handled downstream by
-- svc-blockchain (Cosmos ledger dispatcher) per its existing pipeline.
--
-- The anchor binds: run metadata + workflow definition + ruleset fingerprint
-- (from compose_context) + hippocampus memory IDs used. Immutable, replayable.

CREATE OR REPLACE FUNCTION public.fn_anchor_decision(
  p_run_id uuid,
  p_decision_context jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
  v_run                RECORD;
  v_workflow_name      text;
  v_workflow_version   int;
  v_canonical_payload  jsonb;
  v_canonical_json     text;
  v_payload_hash       text;
  v_memory_ids         uuid[];
  v_node_count         int;
  v_ruleset_fingerprint text;
  v_audit_id           uuid;
  v_user_id            uuid;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_run_id IS NULL THEN
    RAISE EXCEPTION 'p_run_id is required';
  END IF;

  -- Load the run + workflow metadata
  SELECT r.*, d.name AS wf_name, d.version AS wf_version
  INTO v_run
  FROM ai_runs r
  LEFT JOIN ai_workflow_definitions d ON d.id = r.workflow_definition_id
  WHERE r.id = p_run_id;

  IF v_run IS NULL THEN
    RAISE EXCEPTION 'ai_run % not found', p_run_id;
  END IF;

  v_workflow_name := COALESCE(v_run.wf_name, 'inline');
  v_workflow_version := COALESCE(v_run.wf_version, 1);

  -- Hippocampus memories that contributed to / were produced by this run.
  -- A run uses a learning when fn_search_learnings retrieved it (tracked via
  -- audit_journal action='hippocampus.learnings_retrieved'); a run produces
  -- one when source_run_id matches.
  SELECT COALESCE(array_agg(DISTINCT am.id), ARRAY[]::uuid[])
  INTO v_memory_ids
  FROM agent_memories am
  WHERE am.source_run_id = p_run_id
     OR am.id::text IN (
       SELECT jsonb_array_elements_text(metadata -> 'memory_ids')
       FROM audit_journal
       WHERE action = 'hippocampus.learnings_retrieved'
         AND metadata ->> 'run_id' = p_run_id::text
     );

  -- Node count + ruleset fingerprint from run checkpoint
  SELECT COUNT(*) INTO v_node_count
  FROM ai_workflow_node_runs
  WHERE run_id = p_run_id;

  v_ruleset_fingerprint := v_run.metadata
    #> '{checkpoint,state,composed_context,layers,ruleset,fingerprint}' #>> '{}';

  -- Canonical payload — deterministic, sorted, hashable. Excludes timestamps
  -- where they would cause replay-incompatibility (we keep run started_at as
  -- a witnessed moment, but no `now()`).
  v_canonical_payload := jsonb_build_object(
    'schema', 'aisha.cosmos.anchor.v1',
    'run_id', p_run_id,
    'run_kind', v_run.kind,
    'workflow_name', v_workflow_name,
    'workflow_version', v_workflow_version,
    'workflow_definition_id', v_run.workflow_definition_id,
    'story_id', v_run.story_id,
    'actor_user_id', v_run.actor_user_id,
    'ruleset_fingerprint', v_ruleset_fingerprint,
    'hippocampus_memory_ids', to_jsonb(v_memory_ids),
    'node_count', v_node_count,
    'status', v_run.status,
    'started_at', v_run.started_at,
    'finished_at', v_run.finished_at,
    'cost_total', v_run.cost_total_json,
    'decision_context', COALESCE(p_decision_context, '{}'::jsonb)
  );

  -- Hash the canonical JSON form. We sort keys deterministically by relying on
  -- jsonb_build_object key ordering (insertion order) which is preserved.
  v_canonical_json := v_canonical_payload::text;
  v_payload_hash := encode(digest(v_canonical_json, 'sha256'), 'hex');

  -- Queue the audit record via existing outbox helper
  v_user_id := COALESCE(auth.uid(), v_run.actor_user_id);

  INSERT INTO blockchain_audit_records (
    record_type,
    record_hash,
    data,
    status
  )
  VALUES (
    'aisha_cognition_anchor',
    v_payload_hash,
    v_canonical_payload || jsonb_build_object('created_by', v_user_id),
    'queued'
  )
  RETURNING id INTO v_audit_id;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'cosmos.decision_anchored',
    jsonb_build_object(
      'run_id', p_run_id,
      'audit_record_id', v_audit_id,
      'payload_hash', v_payload_hash,
      'workflow_name', v_workflow_name,
      'memory_ids_count', COALESCE(array_length(v_memory_ids, 1), 0)
    )
  );

  RETURN jsonb_build_object(
    'audit_record_id', v_audit_id,
    'payload_hash', v_payload_hash,
    'status', 'queued',
    'workflow_name', v_workflow_name,
    'workflow_version', v_workflow_version,
    'memory_ids_count', COALESCE(array_length(v_memory_ids, 1), 0)
  );
END;
$$;

COMMENT ON FUNCTION public.fn_anchor_decision(uuid, jsonb) IS
  'Cosmos cognition anchor: composes canonical reflection payload (run + workflow + '
  'ruleset fingerprint + hippocampus memory IDs), SHA-256 hashes it, queues into '
  'blockchain_audit_records outbox for svc-blockchain to dispatch to Cosmos ledger.';

REVOKE ALL ON FUNCTION public.fn_anchor_decision(uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_anchor_decision(uuid, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_anchor_decision(uuid, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_apply_graph_extraction_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_apply_graph_extraction_audited
-- Step:  Step 7.2 (Hippocampus Graph extraction worker)
-- Used by: services/svc-mcp-knowledge/src/routes/graph-extract.ts
-- Migration: aisha/db/migrations/20260520040000_graph_extraction_worker.sql
-- ============================================================================
-- Expected p_extraction shape (validated below; bad shapes raise):
--   {
--     "nodes": [
--       { "entity_type": "Concept", "entity_slug": "<slug>", "entity_label": "<label>",
--         "metadata": { ... } }
--     ],
--     "edges": [
--       { "from_type": "Run", "from_slug": "<uuid::text>",
--         "to_type":   "Concept", "to_slug":   "<concept-slug>",
--         "relationship": "REFERENCES", "confidence": 0.0..1.0,
--         "metadata": { ... } }
--     ]
--   }
--
-- Constraints enforced server-side:
--   - Only 'Concept' nodes accepted. Other types are bootstrap-owned (Step 7.1).
--   - Edge relationship must be in the graph_edges CHECK enum.
--   - Edges whose source or target slug doesn't resolve to an existing
--     graph_node are SKIPPED (counted in result), not errors.
--   - Confidence clamped to [0,1].
--   - Single audit_journal row 'graph.extraction_completed' written at end.

CREATE OR REPLACE FUNCTION public.fn_apply_graph_extraction_audited(
  p_run_id      uuid,
  p_extraction  jsonb,
  p_judge_model text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_node          jsonb;
  v_edge          jsonb;
  v_entity_type   text;
  v_entity_slug   text;
  v_entity_label  text;
  v_from_type     text;
  v_from_slug     text;
  v_to_type       text;
  v_to_slug       text;
  v_relationship  text;
  v_confidence    numeric;
  v_source_id     uuid;
  v_target_id     uuid;
  v_story_id      uuid;
  v_nodes_added   int := 0;
  v_edges_added   int := 0;
  v_edges_skipped int := 0;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  IF p_run_id IS NULL THEN
    RAISE EXCEPTION 'p_run_id required';
  END IF;
  IF p_extraction IS NULL OR jsonb_typeof(p_extraction) != 'object' THEN
    RAISE EXCEPTION 'p_extraction must be a jsonb object';
  END IF;

  SELECT story_id INTO v_story_id FROM public.ai_runs WHERE id = p_run_id;

  FOR v_node IN SELECT jsonb_array_elements(COALESCE(p_extraction->'nodes', '[]'::jsonb))
  LOOP
    v_entity_type  := v_node->>'entity_type';
    v_entity_slug  := v_node->>'entity_slug';
    v_entity_label := v_node->>'entity_label';

    CONTINUE WHEN v_entity_type IS DISTINCT FROM 'Concept';
    CONTINUE WHEN v_entity_slug IS NULL OR length(trim(v_entity_slug)) = 0;
    CONTINUE WHEN v_entity_label IS NULL OR length(trim(v_entity_label)) = 0;

    INSERT INTO public.graph_nodes (
      entity_type, entity_slug, entity_label, source_table, source_id,
      story_id, metadata
    ) VALUES (
      'Concept', v_entity_slug, v_entity_label, NULL, NULL,
      v_story_id, COALESCE(v_node->'metadata', '{}'::jsonb)
    )
    ON CONFLICT (entity_type, entity_slug, story_id) DO UPDATE
      SET entity_label = EXCLUDED.entity_label,
          metadata     = EXCLUDED.metadata,
          updated_at   = now();
    v_nodes_added := v_nodes_added + 1;
  END LOOP;

  FOR v_edge IN SELECT jsonb_array_elements(COALESCE(p_extraction->'edges', '[]'::jsonb))
  LOOP
    v_from_type    := v_edge->>'from_type';
    v_from_slug    := v_edge->>'from_slug';
    v_to_type      := v_edge->>'to_type';
    v_to_slug      := v_edge->>'to_slug';
    v_relationship := v_edge->>'relationship';
    v_confidence   := GREATEST(0.0, LEAST(1.0, COALESCE((v_edge->>'confidence')::numeric, 0.7)));

    IF v_from_type IS NULL OR v_from_slug IS NULL
       OR v_to_type IS NULL OR v_to_slug IS NULL
       OR v_relationship IS NULL THEN
      v_edges_skipped := v_edges_skipped + 1;
      CONTINUE;
    END IF;

    SELECT id INTO v_source_id FROM public.graph_nodes
      WHERE entity_type = v_from_type AND entity_slug = v_from_slug
      ORDER BY (story_id = v_story_id) DESC NULLS LAST, created_at ASC
      LIMIT 1;
    SELECT id INTO v_target_id FROM public.graph_nodes
      WHERE entity_type = v_to_type AND entity_slug = v_to_slug
      ORDER BY (story_id = v_story_id) DESC NULLS LAST, created_at ASC
      LIMIT 1;

    IF v_source_id IS NULL OR v_target_id IS NULL THEN
      v_edges_skipped := v_edges_skipped + 1;
      CONTINUE;
    END IF;

    BEGIN
      INSERT INTO public.graph_edges (
        source_node_id, target_node_id, relationship, confidence,
        source_audit_journal_id, source_ai_run_id, metadata
      ) VALUES (
        v_source_id, v_target_id, v_relationship, v_confidence,
        NULL, p_run_id, COALESCE(v_edge->'metadata', '{}'::jsonb)
      )
      ON CONFLICT (source_node_id, target_node_id, relationship) DO UPDATE
        SET confidence       = EXCLUDED.confidence,
            source_ai_run_id = COALESCE(EXCLUDED.source_ai_run_id, graph_edges.source_ai_run_id),
            metadata         = EXCLUDED.metadata;
      v_edges_added := v_edges_added + 1;
    EXCEPTION WHEN check_violation THEN
      v_edges_skipped := v_edges_skipped + 1;
    END;
  END LOOP;

  INSERT INTO public.audit_journal (
    action_type, action, area, severity, summary, metadata, ai_run_id
  ) VALUES (
    'graph.extraction_completed',
    'graph.extraction_completed',
    'retrieval',
    'info',
    format('Graph extraction completed for run %s', p_run_id),
    jsonb_build_object(
      'run_id',          p_run_id,
      'nodes_added',     v_nodes_added,
      'edges_added',     v_edges_added,
      'edges_skipped',   v_edges_skipped,
      'judge_model',     p_judge_model,
      'extraction_size', jsonb_build_object(
        'node_count', jsonb_array_length(COALESCE(p_extraction->'nodes', '[]'::jsonb)),
        'edge_count', jsonb_array_length(COALESCE(p_extraction->'edges', '[]'::jsonb))
      )
    ),
    p_run_id
  );

  RETURN jsonb_build_object(
    'run_id',        p_run_id,
    'nodes_added',   v_nodes_added,
    'edges_added',   v_edges_added,
    'edges_skipped', v_edges_skipped
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_apply_graph_extraction_audited(uuid, jsonb, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_apply_graph_extraction_audited(uuid, jsonb, text) TO service_role;

COMMENT ON FUNCTION public.fn_apply_graph_extraction_audited(uuid, jsonb, text) IS
  'Step 7.2: validates + applies an LLM extraction (Concept nodes + edges) for one ai_run and writes the graph.extraction_completed audit row that drives the "needs extract" filter. Atomic per call.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_audit_journal_guard.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_audit_journal_guard
-- Arguments: (none - trigger function, BEFORE UPDATE/DELETE + TRUNCATE ON audit_journal)
-- Description: Tamper guard for the SECOND audit surface — audit_journal, the sink
--   ~200 *_audited RPCs write via write_audit_journal. It makes audit_journal
--   tamper-evident like blockchain_audit_records:
--     • DELETE and TRUNCATE are rejected — a removed audit row is a broken record.
--     • the per-row content hash (blockchain_hash) is IMMUTABLE once set; a row
--       may still transition its chain-sync status columns (blockchain_tx_hash,
--       blockchain_recorded_at, blockchain_status) and trace-correlation columns
--       (ai_run_id, langfuse_trace_id) — those are not the content fingerprint.
--   Escape hatch: the transaction-local GUC aisha.audit_ledger_rebuild='on' (set
--   ONLY by the idempotent heals backfill) permits a hash (re)build on existing DBs.
--   Guards against application bugs / casual tampering, not superusers — external
--   tamper-evidence is the on-chain anchor of the chain head.
-- Security: SECURITY DEFINER trigger function, search_path pinned, service_role-only EXECUTE.

CREATE OR REPLACE FUNCTION public.fn_audit_journal_guard()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  -- Explicit, transaction-local rebuild path (heals backfill only).
  IF current_setting('aisha.audit_ledger_rebuild', true) = 'on' THEN
    IF TG_OP = 'UPDATE' THEN
      RETURN NEW;
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'TRUNCATE' THEN
    RAISE EXCEPTION 'audit ledger: TRUNCATE forbidden on audit_journal (tamper-evident journal)';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'audit ledger: DELETE forbidden on audit_journal (tamper-evident journal), id=%', OLD.id;
  END IF;

  -- UPDATE: the content fingerprint is immutable once set. Mutating it is tampering.
  IF OLD.blockchain_hash IS NOT NULL
     AND NEW.blockchain_hash IS DISTINCT FROM OLD.blockchain_hash
  THEN
    RAISE EXCEPTION 'audit ledger: blockchain_hash is immutable on audit_journal, id=%', OLD.id;
  END IF;

  RETURN NEW;
END;
$function$;

COMMENT ON FUNCTION public.fn_audit_journal_guard() IS
  'Tamper guard trigger fn for audit_journal: DELETE/TRUNCATE forbidden, blockchain_hash '
  'immutable once set; chain-sync status + trace-correlation columns stay mutable.';

REVOKE ALL ON FUNCTION public.fn_audit_journal_guard() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_audit_journal_guard() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_audit_ledger_record_hash.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_audit_ledger_record_hash
-- Arguments: p_previous_hash text, p_record_type text, p_data jsonb, p_reference_table text,
--            p_reference_id uuid, p_token_transaction_id uuid, p_correlation_id uuid, p_created_at timestamptz
-- Description: Canonical, deterministic SHA-256 record hash for the blockchain_audit_records
--   hash chain. NO now()/random salt — every input is a stored column of the row, so any
--   auditor can recompute the hash from the row alone. The previous_hash input links the
--   row to its predecessor (tamper-evident chain). created_at is folded in as an epoch
--   microsecond integer (timezone/locale independent); jsonb::text is PostgreSQL-canonical
--   (sorted keys, normalized whitespace) and therefore deterministic.
-- Security: IMMUTABLE SQL, schema-qualified pgcrypto call, search_path pinned.

CREATE OR REPLACE FUNCTION public.fn_audit_ledger_record_hash(
  p_previous_hash text,
  p_record_type text,
  p_data jsonb,
  p_reference_table text,
  p_reference_id uuid,
  p_token_transaction_id uuid,
  p_correlation_id uuid,
  p_created_at timestamptz
)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path TO 'public', 'extensions'
AS $function$
  SELECT encode(extensions.digest(convert_to(jsonb_build_object(
    'schema', 'aisha.audit_ledger.v1',
    'previous_hash', p_previous_hash,
    'record_type', p_record_type,
    'data', COALESCE(p_data, '{}'::jsonb),
    'reference_table', p_reference_table,
    'reference_id', p_reference_id,
    'token_transaction_id', p_token_transaction_id,
    'correlation_id', p_correlation_id,
    'created_at_epoch_us', CASE
      WHEN p_created_at IS NULL THEN NULL
      ELSE (extract(epoch FROM p_created_at) * 1000000)::bigint
    END
  )::text, 'UTF8'), 'sha256'), 'hex');
$function$;

COMMENT ON FUNCTION public.fn_audit_ledger_record_hash(text, text, jsonb, text, uuid, uuid, uuid, timestamptz) IS
  'Deterministic canonical SHA-256 for the audit-ledger hash chain (aisha.audit_ledger.v1). '
  'Recomputable from stored row columns only — no clock/random salt.';

-- Permissions
REVOKE ALL ON FUNCTION public.fn_audit_ledger_record_hash(text, text, jsonb, text, uuid, uuid, uuid, timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_audit_ledger_record_hash(text, text, jsonb, text, uuid, uuid, uuid, timestamptz) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_audit_ledger_record_hash(text, text, jsonb, text, uuid, uuid, uuid, timestamptz) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_blockchain_audit_guard.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_blockchain_audit_guard
-- Arguments: (none - trigger function, BEFORE UPDATE/DELETE + TRUNCATE ON blockchain_audit_records)
-- Description: In-database tamper guard for the audit ledger. The chain-carrying columns
--   (id, record_type, data, record_hash, previous_hash, created_at, correlation_id,
--   token_transaction_id, reference_table, reference_id) are immutable after INSERT;
--   only the outbox status machine (status, retry_count, max_attempts, next_retry_at,
--   processing_started_at, updated_at, cosmos_tx_hash, error_message) may change.
--   DELETE and TRUNCATE are rejected — a removed row is a broken chain link.
--   Escape hatch: the transaction-local GUC aisha.audit_ledger_rebuild='on' is set ONLY by
--   the idempotent heals backfill (aisha/db/heals.sql) that (re)builds the chain on existing
--   DBs. This guards against application bugs and casual tampering, not superusers — real
--   external tamper-evidence is Path 2 (anchoring the chain head on the Cosmos ledger).
-- Security: SECURITY DEFINER trigger function, search_path pinned, service_role-only EXECUTE.

CREATE OR REPLACE FUNCTION public.fn_blockchain_audit_guard()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  -- Explicit, transaction-local rebuild path (heals backfill only).
  IF current_setting('aisha.audit_ledger_rebuild', true) = 'on' THEN
    IF TG_OP = 'UPDATE' THEN
      RETURN NEW;
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'TRUNCATE' THEN
    RAISE EXCEPTION 'audit ledger: TRUNCATE forbidden on blockchain_audit_records (tamper-evident chain)';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'audit ledger: DELETE forbidden on blockchain_audit_records (tamper-evident chain), id=%', OLD.id;
  END IF;

  IF NEW.id                   IS DISTINCT FROM OLD.id
     OR NEW.record_type          IS DISTINCT FROM OLD.record_type
     OR NEW.data                 IS DISTINCT FROM OLD.data
     OR NEW.record_hash          IS DISTINCT FROM OLD.record_hash
     OR NEW.previous_hash        IS DISTINCT FROM OLD.previous_hash
     OR NEW.created_at           IS DISTINCT FROM OLD.created_at
     OR NEW.correlation_id       IS DISTINCT FROM OLD.correlation_id
     OR NEW.token_transaction_id IS DISTINCT FROM OLD.token_transaction_id
     OR NEW.reference_table      IS DISTINCT FROM OLD.reference_table
     OR NEW.reference_id         IS DISTINCT FROM OLD.reference_id
  THEN
    RAISE EXCEPTION 'audit ledger: immutable column update forbidden on blockchain_audit_records, id=%', OLD.id;
  END IF;

  RETURN NEW;
END;
$function$;

COMMENT ON FUNCTION public.fn_blockchain_audit_guard() IS
  'Tamper guard trigger fn for blockchain_audit_records: chain columns immutable, '
  'DELETE/TRUNCATE forbidden; only the outbox status machine may be updated.';

-- Permissions — trigger function: not callable directly by clients.
REVOKE ALL ON FUNCTION public.fn_blockchain_audit_guard() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_blockchain_audit_guard() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_capture_learning.sql
-- -----------------------------------------------------------------------------

-- Function: fn_capture_learning
-- Hippocampus learning: capture a pattern→resolution mapping from a reflection run.
-- Learnings live in agent_memories with memory_type='learning', analogous to
-- the existing memory_type='personality' Psyché pattern.
-- After N reuses (tracked via access_count via fn_search_learnings), a learning
-- can be promoted to expert_rules via fn_maybe_promote_learning + WF_KB_COMPLIANCE_GATE.

CREATE OR REPLACE FUNCTION public.fn_capture_learning(
  p_run_id uuid,
  p_pattern text,
  p_resolution text,
  p_critic_scores jsonb DEFAULT '{}'::jsonb,
  p_story_id uuid DEFAULT NULL,
  p_agent_slug text DEFAULT 'aisha',
  p_embedding vector(1024) DEFAULT NULL,
  p_importance integer DEFAULT NULL,
  p_expires_in_days integer DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
  v_id uuid;
  v_run_user_id uuid;
  v_run_kind text;
  v_content text;
  v_metadata jsonb;
  v_importance integer;
  v_expires_at timestamptz;
  v_composite_score numeric;
BEGIN
  -- Auth: authenticated user or service_role
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_run_id IS NULL THEN
    RAISE EXCEPTION 'p_run_id is required';
  END IF;
  IF p_pattern IS NULL OR p_pattern = '' THEN
    RAISE EXCEPTION 'p_pattern is required';
  END IF;
  IF p_resolution IS NULL OR p_resolution = '' THEN
    RAISE EXCEPTION 'p_resolution is required';
  END IF;

  -- Pull run context (user_id, kind) for ownership + audit trail
  SELECT actor_user_id, kind
  INTO v_run_user_id, v_run_kind
  FROM ai_runs
  WHERE id = p_run_id;

  IF v_run_user_id IS NULL AND auth.role() != 'service_role' THEN
    RAISE EXCEPTION 'ai_run % not found or not accessible', p_run_id;
  END IF;

  -- Compose memory content: pattern → resolution as canonical form
  v_content := format('pattern: %s\nresolution: %s', p_pattern, p_resolution);

  -- Compute importance from critic scores (avg of numeric values) when not given
  IF p_importance IS NOT NULL THEN
    v_importance := LEAST(10, GREATEST(1, p_importance));
  ELSE
    SELECT COALESCE(
      ROUND(AVG((v.value)::numeric) * 10)::integer,
      5
    )
    INTO v_composite_score
    FROM jsonb_each_text(p_critic_scores) v
    WHERE v.value ~ '^[0-9]+\.?[0-9]*$';

    v_importance := LEAST(10, GREATEST(1, COALESCE(v_composite_score::integer, 5)));
  END IF;

  -- Optional expiration
  IF p_expires_in_days IS NOT NULL THEN
    v_expires_at := now() + (p_expires_in_days || ' days')::interval;
  END IF;

  -- Metadata captures the structured learning shape for later promotion logic
  v_metadata := jsonb_build_object(
    'pattern', p_pattern,
    'resolution', p_resolution,
    'critic_scores', p_critic_scores,
    'story_id', p_story_id,
    'run_kind', v_run_kind,
    'access_count', 0,
    'promoted_to_expert_rule', false,
    'captured_at', now()
  );

  INSERT INTO agent_memories (
    agent_slug,
    user_id,
    memory_type,
    content,
    importance,
    source_run_id,
    embedding,
    expires_at
  )
  VALUES (
    p_agent_slug,
    v_run_user_id,
    'learning',
    v_content || E'\n\n[meta]' || v_metadata::text,
    v_importance,
    p_run_id,
    p_embedding,
    v_expires_at
  )
  RETURNING id INTO v_id;

  -- Audit trail
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    COALESCE(auth.uid(), v_run_user_id),
    'hippocampus.learning_captured',
    jsonb_build_object(
      'memory_id', v_id,
      'run_id', p_run_id,
      'story_id', p_story_id,
      'agent_slug', p_agent_slug,
      'importance', v_importance,
      'pattern_preview', LEFT(p_pattern, 100)
    )
  );

  RETURN v_id;
END;
$$;

COMMENT ON FUNCTION public.fn_capture_learning(uuid, text, text, jsonb, uuid, text, vector, integer, integer) IS
  'Hippocampus learning: capture a pattern→resolution mapping from a reflection run. '
  'Stored as agent_memories.memory_type=learning. Importance derived from critic_scores. '
  'After repeated reuse, may be promoted to expert_rules via fn_maybe_promote_learning.';

REVOKE ALL ON FUNCTION public.fn_capture_learning(uuid, text, text, jsonb, uuid, text, vector, integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_capture_learning(uuid, text, text, jsonb, uuid, text, vector, integer, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_capture_learning(uuid, text, text, jsonb, uuid, text, vector, integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_chunks_bez_zive_identity.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_chunks_bez_zive_identity
-- Popis: ČISTÝ výběr chunků bez vektoru dané živé identity — jádro
--        fn_get_chunks_needing_v1 (ta identitu zjistí z resolveru v1 a registru).
--        Oddělené, aby šel výběr ověřit bez resolveru a providerů (runtime test).
--
-- Živý vektor = model = p_model A model_version začíná p_identita (`gguf:<sha>`,
-- recept za `;` libovolný). Chunk s vynecháním pro TUTÉŽ identitu se nevrací
-- (nad_limitem — jinak by ucpal frontu). Nejstarší položky první.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_chunks_bez_zive_identity(
  p_model      text,
  p_identita   text,
  p_max_tokens integer,
  p_batch_size integer DEFAULT 20
)
RETURNS TABLE (
  chunk_id           uuid,
  knowledge_item_id  uuid,
  chunk_text         text,
  contextual_prefix  text,
  locale             text,
  model_id           text,
  identita           text,
  max_tokens         integer
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;
  IF p_model IS NULL OR p_identita IS NULL OR p_identita !~ '^gguf:[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'živá identita neplatná: model %, identita %', p_model, p_identita USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  SELECT kc.id, kc.knowledge_item_id, kc.chunk_text, kc.contextual_prefix, kc.locale,
         p_model, p_identita, p_max_tokens
    FROM public.knowledge_chunks kc
    JOIN public.knowledge_items ki ON ki.id = kc.knowledge_item_id
   WHERE NOT EXISTS (
           SELECT 1 FROM public.knowledge_embeddings e
            WHERE e.chunk_id = kc.id AND e.locale = kc.locale
              AND e.model = p_model
              AND split_part(coalesce(e.model_version, ''), ';', 1) = p_identita)
     AND NOT EXISTS (
           SELECT 1 FROM public.knowledge_embedding_vynechani v
            WHERE v.chunk_id = kc.id AND v.locale = kc.locale AND v.identita = p_identita)
   ORDER BY ki.created_at, kc.knowledge_item_id, kc.chunk_index
   LIMIT greatest(1, least(coalesce(p_batch_size, 20), 200));
END;
$$;

REVOKE ALL ON FUNCTION public.fn_chunks_bez_zive_identity(text, text, integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_chunks_bez_zive_identity(text, text, integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_compare_rag_embedding_models.sql
-- -----------------------------------------------------------------------------

-- Function: fn_compare_rag_embedding_models
-- The brick-1 verdict: head-to-head comparison of TWO embedding models on the SAME golden
-- set, per (context_profile, language). The existing baseline RPCs bucket BY embedding_model
-- but never DIFF two buckets, and the regression detector compares a group only to its OWN
-- time-series — neither can answer "which embedding space retrieves better for THIS context".
--
-- The winner is decided by nDCG@K (the retrieval north-star for CHOOSING an embedding model —
-- rank-aware, computed from expected_chunk_slugs, independent of the LLM answer). composite_score
-- (RAGAS generation quality) is returned alongside for context but does NOT pick the winner: a
-- better answer with worse retrieval is the LLM compensating, not a better index.
--
-- Only retrieval-SCORED runs (metadata.retrieval.num_expected > 0) feed the nDCG/recall/MRR
-- means; if the golden set is not yet labelled with expected_chunk_slugs for a group, the
-- winner is 'insufficient_data' (NOT a fabricated tie) — the honest "needs a labelled golden"
-- signal. This is the head-to-head AISHA reads to pin embedding_model_pref per context (brick 2).

CREATE OR REPLACE FUNCTION public.fn_compare_rag_embedding_models(
  p_model_a text,
  p_model_b text,
  p_period_hours integer DEFAULT 168
)
 RETURNS TABLE(
   context_profile_slug text,
   language text,
   a_ndcg numeric, b_ndcg numeric,
   a_recall numeric, b_recall numeric,
   a_mrr numeric, b_mrr numeric,
   a_composite numeric, b_composite numeric,
   a_scored_rows bigint, b_scored_rows bigint,
   ndcg_delta numeric,
   winner text
 )
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;
  IF p_model_a IS NULL OR p_model_b IS NULL OR p_model_a = p_model_b THEN
    RAISE EXCEPTION 'p_model_a and p_model_b are required and must differ';
  END IF;

  RETURN QUERY
  WITH runs AS (
    SELECT
      r.embedding_model,
      r.context_profile_slug AS cps,
      COALESCE(r.metadata->>'language', 'unknown') AS lang,
      r.composite_score AS composite,
      NULLIF(r.metadata->'retrieval'->>'num_expected', '')::int     AS num_expected,
      NULLIF(r.metadata->'retrieval'->>'ndcg_at_k', '')::numeric     AS ndcg,
      NULLIF(r.metadata->'retrieval'->>'recall_at_k', '')::numeric   AS recall,
      NULLIF(r.metadata->'retrieval'->>'mrr', '')::numeric           AS mrr
    FROM public.rag_eval_runs r
    WHERE r.embedding_model IN (p_model_a, p_model_b)
      AND r.created_at >= now() - make_interval(hours => p_period_hours)
  ),
  agg AS (
    SELECT
      cps, lang, embedding_model,
      round(avg(ndcg)   FILTER (WHERE num_expected > 0), 4) AS ndcg,
      round(avg(recall) FILTER (WHERE num_expected > 0), 4) AS recall,
      round(avg(mrr)    FILTER (WHERE num_expected > 0), 4) AS mrr,
      round(avg(composite), 3)                              AS composite,
      count(*) FILTER (WHERE num_expected > 0)              AS scored_rows
    FROM runs
    GROUP BY cps, lang, embedding_model
  )
  SELECT
    COALESCE(a.cps, b.cps),
    COALESCE(a.lang, b.lang),
    a.ndcg, b.ndcg, a.recall, b.recall, a.mrr, b.mrr,
    a.composite, b.composite,
    COALESCE(a.scored_rows, 0), COALESCE(b.scored_rows, 0),
    round(COALESCE(a.ndcg, 0) - COALESCE(b.ndcg, 0), 4) AS ndcg_delta,
    CASE
      WHEN a.ndcg IS NULL AND b.ndcg IS NULL THEN 'insufficient_data'
      WHEN COALESCE(a.ndcg, -1) > COALESCE(b.ndcg, -1) THEN p_model_a
      WHEN COALESCE(b.ndcg, -1) > COALESCE(a.ndcg, -1) THEN p_model_b
      ELSE 'tie'
    END AS winner
  FROM (SELECT * FROM agg WHERE embedding_model = p_model_a) a
  FULL OUTER JOIN (SELECT * FROM agg WHERE embedding_model = p_model_b) b
    ON a.cps IS NOT DISTINCT FROM b.cps
   AND a.lang = b.lang
  ORDER BY 1, 2;
END;
$function$
;

REVOKE ALL ON FUNCTION fn_compare_rag_embedding_models(text, text, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_compare_rag_embedding_models(text, text, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_compute_clow_risk.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_compute_clow_risk  (E0 capability-availability — risk axis)
-- Purpose: COMPUTE a clow's risk band from FIRST PRINCIPLES — never a lookup
--          list of "high-risk runtimes/tools". Risk is DERIVED:
--            base band  = the chosen runtime's DECLARED side_effect_class
--                         (read_only → low, reversible → medium, irreversible → high)
--            +1 band    if the clow's own criticality is high|critical
--            +1 band    if the clow both reaches the internet AND writes
--                         (egress + side-effect = exfiltration / blast-radius class)
--            clamp      at 'critical' (the top band)
--          The resulting risk_level feeds governance-as-POLICY: a threshold
--          decides allow/ask/deny + whether human approval is forced. There is
--          NO maintained allow-list anywhere — the runtime row governs itself via
--          its own side_effect_class, exactly like ai_provider_registry governs
--          availability via is_enabled. Adding a runtime/tool changes nothing here.
-- Security: SECURITY DEFINER, read-only (pure). authenticated + service_role.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_compute_clow_risk(
  p_clow        jsonb,
  p_runtime_row jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  -- Risk bands, lowest → highest. This is an ORDINAL SCALE, not an allow-list:
  -- it never enumerates which entities are permitted, only how to escalate a band.
  v_bands           text[]  := ARRAY['low', 'medium', 'high', 'critical'];
  v_max_idx         int     := array_length(v_bands, 1);  -- 4 (clamp ceiling)

  v_side_effect     text    := COALESCE(NULLIF(p_runtime_row->>'side_effect_class', ''), 'reversible');
  v_criticality     text    := COALESCE(NULLIF(p_clow->>'criticality', ''), 'normal');
  v_needs_internet  boolean := COALESCE((p_clow->>'needs_internet')::boolean, false);
  v_needs_write     boolean := COALESCE((p_clow->>'needs_write')::boolean, false);

  v_base_idx        int;
  v_idx             int;
  v_bump_crit       boolean := (v_criticality IN ('high', 'critical'));
  v_bump_egress     boolean := (v_needs_internet AND v_needs_write);
  v_factors         jsonb   := jsonb_build_array();
BEGIN
  -- Auth: any authenticated caller or service_role. Pure read-only function.
  IF auth.uid() IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  -- ── base band — DERIVED from the runtime's own declared side-effect class ──
  -- Unknown/unset side_effect_class → treat as 'reversible' (medium): a runtime
  -- that has not declared itself read-only is not assumed harmless.
  v_base_idx := CASE v_side_effect
    WHEN 'read_only'    THEN 1   -- low
    WHEN 'reversible'   THEN 2   -- medium
    WHEN 'irreversible' THEN 3   -- high
    ELSE 2                       -- conservative default = medium
  END;
  v_idx := v_base_idx;
  v_factors := v_factors || jsonb_build_object(
    'factor', 'side_effect_class',
    'value',  v_side_effect,
    'band',   v_bands[v_base_idx]
  );

  -- ── +1 band — the clow's OWN criticality (high|critical) ───────────────────
  IF v_bump_crit THEN
    v_idx := v_idx + 1;
    v_factors := v_factors || jsonb_build_object(
      'factor', 'criticality',
      'value',  v_criticality,
      'delta',  1
    );
  END IF;

  -- ── +1 band — egress + side-effect (exfiltration / blast-radius) ───────────
  IF v_bump_egress THEN
    v_idx := v_idx + 1;
    v_factors := v_factors || jsonb_build_object(
      'factor', 'internet_and_write',
      'value',  true,
      'delta',  1
    );
  END IF;

  -- ── clamp at the top band ('critical') ─────────────────────────────────────
  IF v_idx > v_max_idx THEN
    v_factors := v_factors || jsonb_build_object(
      'factor', 'clamp',
      'value',  'critical',
      'raw_idx', v_idx
    );
    v_idx := v_max_idx;
  END IF;
  IF v_idx < 1 THEN
    v_idx := 1;  -- defensive floor (bands are 1-indexed)
  END IF;

  RETURN jsonb_build_object(
    'risk_level', v_bands[v_idx],
    'factors',    v_factors
  );
END;
$$;

COMMENT ON FUNCTION public.fn_compute_clow_risk(jsonb, jsonb) IS
  'E0 capability-availability risk axis. COMPUTES risk_level (low|medium|high|critical) from '
  'the runtime row''s declared side_effect_class (read_only→low, reversible→medium, '
  'irreversible→high), +1 band on clow criticality high|critical, +1 band on needs_internet AND '
  'needs_write, clamped at critical. Pure/STABLE; no allow-list — risk drives governance-as-POLICY '
  '(threshold → allow/ask/deny + human approval), not membership in any permitted-names list.';

REVOKE ALL ON FUNCTION public.fn_compute_clow_risk(jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_compute_clow_risk(jsonb, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_compute_clow_risk(jsonb, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_compute_rag_baseline_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_compute_rag_baseline_audited
-- Popis: Recompute aggregated rows in public.rag_eval_baselines for the last
--        N hours. Called by:
--          - services/svc-mcp-knowledge/src/routes/rag-eval.ts (after each batch)
--          - WF_RAG_EVAL_NIGHTLY (n8n cron) via the same endpoint
--
-- Step:   Step 0 of retrieval optimization plan 2026
-- Bezpečnost: SECURITY DEFINER + service_role only
-- Audit:  INSERT INTO audit_journal (action='rag_eval.baseline_recomputed', metadata)
-- Source migration: aisha/db/migrations/20260518200000_rag_eval_foundation.sql
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_compute_rag_baseline_audited(
  p_period_hours integer DEFAULT 24
)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_rows_inserted integer := 0;
  v_period_start  timestamptz;
  v_period_end    timestamptz;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  v_period_end   := date_trunc('hour', now());
  v_period_start := v_period_end - make_interval(hours => p_period_hours);

  WITH agg AS (
    SELECT
      r.context_profile_slug,
      r.embedding_model,
      r.llm_model,
      count(*)::integer                          AS n_runs,
      round(avg(r.faithfulness_score)::numeric,        3) AS faithfulness_avg,
      round(avg(r.answer_relevancy_score)::numeric,    3) AS answer_relevancy_avg,
      round(avg(r.context_precision_score)::numeric,   3) AS context_precision_avg,
      round(avg(r.context_recall_score)::numeric,      3) AS context_recall_avg,
      round(avg(r.composite_score)::numeric,           3) AS composite_avg,
      round(percentile_cont(0.5) WITHIN GROUP (ORDER BY r.faithfulness_score)::numeric, 3) AS faithfulness_p50,
      round(percentile_cont(0.9) WITHIN GROUP (ORDER BY r.faithfulness_score)::numeric, 3) AS faithfulness_p90
    FROM public.rag_eval_runs r
    WHERE r.created_at >= v_period_start
      AND r.created_at <  v_period_end
    GROUP BY r.context_profile_slug, r.embedding_model, r.llm_model
  )
  INSERT INTO public.rag_eval_baselines (
    period_start, period_end, context_profile_slug, embedding_model, llm_model,
    n_runs, faithfulness_avg, answer_relevancy_avg, context_precision_avg,
    context_recall_avg, composite_avg, faithfulness_p50, faithfulness_p90
  )
  SELECT
    v_period_start, v_period_end, agg.context_profile_slug, agg.embedding_model, agg.llm_model,
    agg.n_runs, agg.faithfulness_avg, agg.answer_relevancy_avg, agg.context_precision_avg,
    agg.context_recall_avg, agg.composite_avg, agg.faithfulness_p50, agg.faithfulness_p90
  FROM agg
  ON CONFLICT (period_start, period_end, context_profile_slug, embedding_model, llm_model)
  DO UPDATE SET
    n_runs                = EXCLUDED.n_runs,
    faithfulness_avg      = EXCLUDED.faithfulness_avg,
    answer_relevancy_avg  = EXCLUDED.answer_relevancy_avg,
    context_precision_avg = EXCLUDED.context_precision_avg,
    context_recall_avg    = EXCLUDED.context_recall_avg,
    composite_avg         = EXCLUDED.composite_avg,
    faithfulness_p50      = EXCLUDED.faithfulness_p50,
    faithfulness_p90      = EXCLUDED.faithfulness_p90;

  GET DIAGNOSTICS v_rows_inserted = ROW_COUNT;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'rag_eval.baseline_recomputed',
    jsonb_build_object(
      'period_start', v_period_start,
      'period_end',   v_period_end,
      'period_hours', p_period_hours,
      'rows_upserted', v_rows_inserted
    )
  );

  RETURN v_rows_inserted;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_compute_rag_baseline_audited(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_compute_rag_baseline_audited(integer) TO service_role;

COMMENT ON FUNCTION public.fn_compute_rag_baseline_audited(integer) IS
  'Recompute rag_eval_baselines for last N hours. Called by WF_RAG_EVAL_NIGHTLY after batch. Service-role only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_create_approval_request.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_create_approval_request
-- Persists a new approval request raised by WF_APPROVAL_GATE (Create Approval
-- node). The workflow supplies a client-generated approval id plus the
-- classification/risk context; this records it into the approval_requests ledger
-- so the decision state survives beyond the workflow run. Idempotent on the id.
-- Security: SECURITY DEFINER (service_role-invoked via aishaRpc), search_path pinned.

CREATE OR REPLACE FUNCTION public.fn_create_approval_request(
  p_approval_id        uuid,
  p_action_description text DEFAULT NULL,
  p_severity           text DEFAULT NULL,
  p_computed_risk      numeric DEFAULT NULL,
  p_agent_slug         text DEFAULT NULL,
  p_category           text DEFAULT NULL,
  p_source             text DEFAULT NULL,
  p_context            jsonb DEFAULT '{}'::jsonb,
  p_context_hash       text DEFAULT NULL,
  p_expires_at         timestamptz DEFAULT NULL,
  p_status             text DEFAULT 'pending'
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.approval_requests
    (id, action_description, severity, computed_risk, agent_slug, category,
     source, context, context_hash, expires_at, status)
  VALUES
    (COALESCE(p_approval_id, gen_random_uuid()), p_action_description, p_severity,
     p_computed_risk, p_agent_slug, p_category, p_source,
     COALESCE(p_context, '{}'::jsonb), p_context_hash, p_expires_at,
     COALESCE(p_status, 'pending'))
  ON CONFLICT (id) DO UPDATE
    SET action_description = EXCLUDED.action_description,
        severity          = EXCLUDED.severity,
        computed_risk      = EXCLUDED.computed_risk,
        agent_slug         = EXCLUDED.agent_slug,
        category           = EXCLUDED.category,
        source             = EXCLUDED.source,
        context            = EXCLUDED.context,
        context_hash       = EXCLUDED.context_hash,
        expires_at         = EXCLUDED.expires_at,
        updated_at         = now()
  RETURNING id INTO v_id;

  INSERT INTO public.audit_journal
    (user_id, action_type, action, entity_type, entity_id, area, severity, summary, details)
  VALUES
    (NULL, 'create', 'APPROVAL_REQUESTED', 'approval_request', v_id::text,
     'system', COALESCE(p_severity, 'info'),
     'Approval request created',
     jsonb_build_object('agent_slug', p_agent_slug, 'category', p_category,
       'computed_risk', p_computed_risk, 'source', p_source));

  RETURN v_id;
END;
$function$;

COMMENT ON FUNCTION public.fn_create_approval_request(uuid, text, text, numeric, text, text, text, jsonb, text, timestamptz, text) IS
  'Persists a WF_APPROVAL_GATE approval request into approval_requests (idempotent on id).';

