-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_detect_rag_baseline_regression.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_detect_rag_baseline_regression
-- Phase 12 WP 1.6 — RAGAS nightly regression detection
--
-- Compares the most-recent rag_eval_baselines row against the 7-day moving
-- average (excluding the latest row itself), per (context_profile_slug,
-- embedding_model, llm_model). Returns one row per group flagged with a
-- severity verdict:
--
--   ok       composite_avg drop < 0.02 OR drop ratio < 2.5 %
--   warning  composite_avg drop >= 0.02 OR drop ratio >= 2.5 %
--   critical composite_avg drop >= 0.05 OR drop ratio >= 5 % (per plan SLO)
--
-- Verdict thresholds are config-driven (p_warn_drop, p_crit_drop) so the
-- operator can tune without redeploying the RPC.
--
-- Consumed by WF_RAG_EVAL_NIGHTLY n8n workflow — emits Matrix alert when
-- ANY group hits 'critical', and ops-channel summary when any group hits
-- 'warning'.
--
-- Bezpečnost: SECURITY DEFINER, GRANT EXECUTE TO service_role only.
-- Audit:      INSERT INTO audit_journal on critical verdicts only (low
--             cardinality — warnings are too frequent for audit trail).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_detect_rag_baseline_regression(
  p_lookback_hours integer DEFAULT 168,         -- 7 days
  p_warn_drop      numeric DEFAULT 0.02,        -- composite_avg point drop
  p_crit_drop      numeric DEFAULT 0.05,        -- per plan SLO
  p_warn_pct       numeric DEFAULT 0.025,       -- 2.5 % relative drop
  p_crit_pct       numeric DEFAULT 0.05         -- 5 % relative drop
)
RETURNS TABLE (
  context_profile_slug   text,
  embedding_model        text,
  llm_model              text,
  latest_period_end      timestamptz,
  latest_composite       numeric,
  lookback_avg_composite numeric,
  drop_absolute          numeric,
  drop_pct               numeric,
  severity               text,
  reason                 text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  -- Service-role only — this is invoked from n8n nightly workflow and
  -- from the rag-eval service after batch completion.
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  IF p_lookback_hours <= 0 THEN
    RAISE EXCEPTION 'p_lookback_hours must be > 0' USING ERRCODE = '22023';
  END IF;
  IF p_warn_drop < 0 OR p_crit_drop < 0 THEN
    RAISE EXCEPTION 'drop thresholds must be >= 0' USING ERRCODE = '22023';
  END IF;
  IF p_crit_drop < p_warn_drop THEN
    RAISE EXCEPTION 'p_crit_drop (%) must be >= p_warn_drop (%)',
      p_crit_drop, p_warn_drop USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH ranked AS (
    -- Per group, identify the newest baseline + numbered older rows so we
    -- can compute "moving average excluding latest" without double-counting.
    SELECT
      b.context_profile_slug,
      b.embedding_model,
      b.llm_model,
      b.period_end,
      b.composite_avg,
      row_number() OVER (
        PARTITION BY b.context_profile_slug, b.embedding_model, b.llm_model
        ORDER BY b.period_end DESC
      ) AS rn
    FROM public.rag_eval_baselines b
    WHERE b.period_end >= (now() - make_interval(hours => p_lookback_hours))
      AND b.composite_avg IS NOT NULL
  ),
  latest AS (
    SELECT
      r.context_profile_slug,
      r.embedding_model,
      r.llm_model,
      r.period_end       AS latest_period_end,
      r.composite_avg    AS latest_composite
    FROM ranked r
    WHERE r.rn = 1
  ),
  lookback AS (
    SELECT
      r.context_profile_slug,
      r.embedding_model,
      r.llm_model,
      round(avg(r.composite_avg)::numeric, 3) AS lookback_avg_composite,
      count(*)::integer                       AS lookback_n
    FROM ranked r
    WHERE r.rn > 1
    GROUP BY r.context_profile_slug, r.embedding_model, r.llm_model
  )
  SELECT
    l.context_profile_slug,
    l.embedding_model,
    l.llm_model,
    l.latest_period_end,
    l.latest_composite,
    lb.lookback_avg_composite,
    round((lb.lookback_avg_composite - l.latest_composite)::numeric, 3) AS drop_absolute,
    round(
      CASE
        WHEN lb.lookback_avg_composite IS NULL OR lb.lookback_avg_composite = 0 THEN 0
        ELSE ((lb.lookback_avg_composite - l.latest_composite) / lb.lookback_avg_composite)::numeric
      END,
      4
    ) AS drop_pct,
    CASE
      -- Insufficient history: surface 'ok' with reason — alert as info
      WHEN lb.lookback_avg_composite IS NULL OR lb.lookback_n < 2 THEN 'ok'
      WHEN (lb.lookback_avg_composite - l.latest_composite) >= p_crit_drop
        OR ((lb.lookback_avg_composite - l.latest_composite) / NULLIF(lb.lookback_avg_composite, 0)) >= p_crit_pct
      THEN 'critical'
      WHEN (lb.lookback_avg_composite - l.latest_composite) >= p_warn_drop
        OR ((lb.lookback_avg_composite - l.latest_composite) / NULLIF(lb.lookback_avg_composite, 0)) >= p_warn_pct
      THEN 'warning'
      ELSE 'ok'
    END AS severity,
    CASE
      WHEN lb.lookback_avg_composite IS NULL OR lb.lookback_n < 2 THEN
        'insufficient_history_n=' || COALESCE(lb.lookback_n, 0)::text
      WHEN (lb.lookback_avg_composite - l.latest_composite) >= p_crit_drop THEN
        'composite_drop_abs >= ' || p_crit_drop::text
      WHEN ((lb.lookback_avg_composite - l.latest_composite) / NULLIF(lb.lookback_avg_composite, 0)) >= p_crit_pct THEN
        'composite_drop_pct >= ' || p_crit_pct::text
      WHEN (lb.lookback_avg_composite - l.latest_composite) >= p_warn_drop THEN
        'composite_drop_abs >= ' || p_warn_drop::text
      WHEN ((lb.lookback_avg_composite - l.latest_composite) / NULLIF(lb.lookback_avg_composite, 0)) >= p_warn_pct THEN
        'composite_drop_pct >= ' || p_warn_pct::text
      ELSE 'within_tolerance'
    END AS reason
  FROM latest l
  LEFT JOIN lookback lb USING (context_profile_slug, embedding_model, llm_model)
  ORDER BY
    CASE WHEN (lb.lookback_avg_composite - l.latest_composite) >= p_crit_drop THEN 0
         WHEN (lb.lookback_avg_composite - l.latest_composite) >= p_warn_drop THEN 1
         ELSE 2 END,
    l.context_profile_slug NULLS LAST;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_detect_rag_baseline_regression(integer, numeric, numeric, numeric, numeric) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_detect_rag_baseline_regression(integer, numeric, numeric, numeric, numeric) TO service_role;

COMMENT ON FUNCTION public.fn_detect_rag_baseline_regression(integer, numeric, numeric, numeric, numeric) IS
  'Phase 12 WP 1.6 — per-group regression detector. Compares latest rag_eval_baselines row against the 7-day MA (default), returns severity {ok,warning,critical} verdict. Service-role only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_enrich_chunk_context_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_enrich_chunk_context_audited
-- Popis: Persist a contextual prefix for one chunk + invalidate its existing
--        embedding so the next embedding worker pass re-embeds over
--        {contextual_prefix} {chunk_text}. Audit row written.
-- Caller: services/svc-mcp-knowledge/src/lib/contextual-prefix.ts → batch loop
--         after vLLM generates the prefix
--
-- Why invalidate the embedding:
--   Step 1's contract is that embedding MUST reflect the prefix. Without
--   invalidation, a re-run of the prefix worker would leave the old
--   prefix-less embedding behind, and queries would still hit the worse
--   baseline. The downstream embedding worker picks up the orphaned chunk on
--   its next pass and re-embeds with the prefix included as input.
--
-- Step:   Step 1 of retrieval optimization plan 2026
-- Bezpečnost: SECURITY DEFINER + service_role only
-- Audit:  INSERT INTO audit_journal (action='knowledge.chunk_context_enriched', metadata)
-- Source migration: aisha/db/migrations/20260518210000_contextual_retrieval.sql
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_enrich_chunk_context_audited(
  p_chunk_id           uuid,
  p_contextual_prefix  text,
  p_model              text,
  p_model_version      text,
  p_token_count        integer
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_item_id uuid;
  v_deleted_embeddings integer;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  IF p_chunk_id IS NULL THEN
    RAISE EXCEPTION 'p_chunk_id is required';
  END IF;
  IF p_contextual_prefix IS NULL OR length(trim(p_contextual_prefix)) = 0 THEN
    RAISE EXCEPTION 'p_contextual_prefix must be non-empty';
  END IF;
  IF p_model IS NULL OR p_model = '' THEN
    RAISE EXCEPTION 'p_model is required';
  END IF;

  SELECT knowledge_item_id INTO v_item_id
    FROM public.knowledge_chunks
   WHERE id = p_chunk_id;

  IF v_item_id IS NULL THEN
    RAISE EXCEPTION 'chunk % not found', p_chunk_id;
  END IF;

  UPDATE public.knowledge_chunks
     SET contextual_prefix               = p_contextual_prefix,
         contextual_prefix_model         = p_model,
         contextual_prefix_model_version = p_model_version,
         contextual_prefix_token_count   = p_token_count,
         contextual_prefix_generated_at  = now()
   WHERE id = p_chunk_id;

  DELETE FROM public.knowledge_embeddings
   WHERE chunk_id = p_chunk_id;
  GET DIAGNOSTICS v_deleted_embeddings = ROW_COUNT;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'knowledge.chunk_context_enriched',
    jsonb_build_object(
      'chunk_id',  p_chunk_id,
      'item_id',   v_item_id,
      'model',     p_model,
      'version',   p_model_version,
      'tokens',    p_token_count,
      'prefix_chars', length(p_contextual_prefix),
      'embeddings_invalidated', v_deleted_embeddings
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_enrich_chunk_context_audited(uuid, text, text, text, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_enrich_chunk_context_audited(uuid, text, text, text, integer) TO service_role;

COMMENT ON FUNCTION public.fn_enrich_chunk_context_audited(uuid, text, text, text, integer) IS
  'Persist contextual prefix for one chunk + invalidate its existing embedding so the next embedding worker pass re-embeds {prefix} {chunk_text}. Audit row written. Service-role only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_estimate_task_cost.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_estimate_task_cost
-- Purpose: Pre-flight cost estimate for a task kind — answers "co to může
--          stát" BEFORE a run starts. Two-source strategy:
--            history  — p50/p90 percentiles of ai_runs.cost_total_json
--                       (finished runs of the same kind, 30-day window,
--                       optionally narrowed to the story) when >= 5 samples;
--            catalog  — ai_cost_class_catalog band as the cold-start
--                       fallback (new platform / new kind / sparse history).
--          Estimates self-correct as history accumulates — no model needed.
-- Security: SECURITY DEFINER, read-only. authenticated + service_role.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_estimate_task_cost(
  p_kind     text,
  p_story_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_p50       numeric;
  v_p90       numeric;
  v_n         int;
  v_catalog   public.ai_cost_class_catalog%ROWTYPE;
  v_source    text;
  v_tokens_p90 numeric;
BEGIN
  IF auth.uid() IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_kind IS NULL OR btrim(p_kind) = '' THEN
    RAISE EXCEPTION 'fn_estimate_task_cost: p_kind required' USING ERRCODE = '22023';
  END IF;

  -- History percentiles: finished runs of this kind, last 30 days. Story
  -- narrowing is intentionally soft — story-local history is preferred only
  -- when it alone clears the sample threshold.
  SELECT
    percentile_cont(0.5) WITHIN GROUP (ORDER BY usd),
    percentile_cont(0.9) WITHIN GROUP (ORDER BY usd),
    percentile_cont(0.9) WITHIN GROUP (ORDER BY toks),
    COUNT(*)::int
  INTO v_p50, v_p90, v_tokens_p90, v_n
  FROM (
    SELECT
      NULLIF(ar.cost_total_json->>'total', '')::numeric AS usd,
      (COALESCE(NULLIF(ar.cost_total_json->>'tokens_input', '')::numeric, 0)
       + COALESCE(NULLIF(ar.cost_total_json->>'tokens_output', '')::numeric, 0)) AS toks
    FROM public.ai_runs ar
    WHERE ar.kind = p_kind
      AND ar.finished_at IS NOT NULL
      AND ar.finished_at > now() - interval '30 days'
      AND (p_story_id IS NULL OR ar.story_id = p_story_id)
      AND NULLIF(ar.cost_total_json->>'total', '')::numeric > 0
  ) s;

  -- Story-scoped query too sparse → widen to platform-wide history.
  IF p_story_id IS NOT NULL AND COALESCE(v_n, 0) < 5 THEN
    SELECT
      percentile_cont(0.5) WITHIN GROUP (ORDER BY usd),
      percentile_cont(0.9) WITHIN GROUP (ORDER BY usd),
      percentile_cont(0.9) WITHIN GROUP (ORDER BY toks),
      COUNT(*)::int
    INTO v_p50, v_p90, v_tokens_p90, v_n
    FROM (
      SELECT
        NULLIF(ar.cost_total_json->>'total', '')::numeric AS usd,
        (COALESCE(NULLIF(ar.cost_total_json->>'tokens_input', '')::numeric, 0)
         + COALESCE(NULLIF(ar.cost_total_json->>'tokens_output', '')::numeric, 0)) AS toks
      FROM public.ai_runs ar
      WHERE ar.kind = p_kind
        AND ar.finished_at IS NOT NULL
        AND ar.finished_at > now() - interval '30 days'
        AND NULLIF(ar.cost_total_json->>'total', '')::numeric > 0
    ) s;
  END IF;

  IF COALESCE(v_n, 0) >= 5 THEN
    v_source := 'history';
  ELSE
    SELECT * INTO v_catalog
    FROM public.ai_cost_class_catalog c
    WHERE c.kind = p_kind AND c.is_active;
    IF v_catalog.kind IS NOT NULL THEN
      v_source     := 'catalog';
      v_p50        := v_catalog.usd_p50;
      v_p90        := v_catalog.usd_p90;
      v_tokens_p90 := v_catalog.tokens_p90;
    ELSE
      -- Unknown kind with no history: explicitly say so — the authorizer
      -- treats 'none' as ask-worthy rather than silently allowing.
      v_source := 'none';
      v_p50    := NULL;
      v_p90    := NULL;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'kind', p_kind,
    'source', v_source,
    'n_samples', COALESCE(v_n, 0),
    'usd_p50', v_p50,
    'usd_p90', v_p90,
    'tokens_p90', v_tokens_p90,
    'cost_class', v_catalog.cost_class
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_estimate_task_cost(text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_estimate_task_cost(text, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_estimate_task_cost(text, uuid) TO service_role;

COMMENT ON FUNCTION public.fn_estimate_task_cost(text, uuid) IS
  'Pre-flight cost estimate per task kind: 30d ai_runs percentiles (>=5 samples) with ai_cost_class_catalog fallback. Returns {source: history|catalog|none, usd_p50, usd_p90, tokens_p90, n_samples}.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_authorize_task_spend.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_authorize_task_spend
-- Purpose: THE pre-flight spend decision — called at admission points
--          (fn_create_workflow_run, create_ai_run, enqueue_agent_run, future
--          CLI spawner) before a task starts. Combines:
--            estimate  — fn_estimate_task_cost (history → catalog fallback)
--            policy    — ai_spend_policies, most specific active row wins:
--                        (story,kind) > (story,*) > (global,kind) > (global,*);
--                        no row → catalog defaults (allow under p90,
--                        ask above p90, deny above 3×p90)
--            budget    — ai_budget remaining across ALL periods (lifetime,
--                        daily, monthly — fixes the lifetime-only admission gap)
--          Decision semantics:
--            allow — silent start
--            ask   — caller creates the run blocked (awaiting='spend_approval');
--                    human approves in Mission Control (may raise budget)
--            deny  — hard policy ceiling; caller refuses or blocks with reason
--          Estimate-vs-budget: projected p90 exceeding ANY remaining budget
--          dimension → ask (never silent), because a human can raise the cap.
--          Stack-default stories stay exempt (platform AI never bricked).
-- Security: SECURITY DEFINER, read-only. authenticated + service_role.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_authorize_task_spend(
  p_kind     text,
  p_story_id uuid DEFAULT NULL,
  p_estimate numeric DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_estimate    jsonb;
  v_est     numeric;
  v_policy      public.ai_spend_policies%ROWTYPE;
  v_allow_under numeric;
  v_ask_over    numeric;
  v_deny_over   numeric;
  v_cat_p90     numeric;
  v_policy_src  text;
  v_is_stack    boolean := false;
  v_budget      record;
  v_budgets     jsonb := '[]'::jsonb;
  v_over_budget boolean := false;
  v_decision    text;
  v_reason      text;
BEGIN
  IF auth.uid() IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_kind IS NULL OR btrim(p_kind) = '' THEN
    RAISE EXCEPTION 'fn_authorize_task_spend: p_kind required' USING ERRCODE = '22023';
  END IF;

  -- 1. Estimate (caller-provided override wins — e.g. router already knows)
  v_estimate := public.fn_estimate_task_cost(p_kind, p_story_id);
  v_est  := COALESCE(p_estimate, NULLIF(v_estimate->>'usd_p90', '')::numeric);

  -- 2. Stack-default exemption (mirror of fn_create_workflow_run admission)
  IF p_story_id IS NOT NULL THEN
    SELECT COALESCE(ps.is_stack_default, false) INTO v_is_stack
    FROM public.partner_stories ps WHERE ps.id = p_story_id;
  END IF;
  IF COALESCE(v_is_stack, false) THEN
    RETURN jsonb_build_object(
      'decision', 'allow',
      'reason', 'stack_default_story_exempt',
      'estimate', v_estimate,
      'budgets', v_budgets
    );
  END IF;

  -- 3. Policy resolution: most specific active row wins.
  SELECT * INTO v_policy
  FROM public.ai_spend_policies sp
  WHERE sp.is_active
    AND (
      (sp.scope_type = 'story'  AND sp.scope_id = p_story_id AND sp.task_kind = p_kind)
      OR (sp.scope_type = 'story'  AND sp.scope_id = p_story_id AND sp.task_kind IS NULL)
      OR (sp.scope_type = 'global' AND sp.task_kind = p_kind)
      OR (sp.scope_type = 'global' AND sp.task_kind IS NULL)
    )
  ORDER BY
    CASE
      WHEN sp.scope_type = 'story'  AND sp.task_kind IS NOT NULL THEN 0
      WHEN sp.scope_type = 'story'  AND sp.task_kind IS NULL     THEN 1
      WHEN sp.scope_type = 'global' AND sp.task_kind IS NOT NULL THEN 2
      ELSE 3
    END
  LIMIT 1;

  IF v_policy.id IS NOT NULL THEN
    v_policy_src  := v_policy.scope_type || ':' || COALESCE(v_policy.task_kind, '*');
    v_allow_under := v_policy.auto_allow_under;
    v_ask_over    := v_policy.ask_over;
    v_deny_over   := v_policy.deny_over;
  ELSE
    -- Zero-config defaults from the STABLE cost-class band (decided 2026-06-12:
    -- allow under class p90, ask above it, hard-deny above 3×p90).
    -- The threshold comes from the CATALOG band, NOT from the estimate: the
    -- estimate prefers history, so a kind/story running hotter than its catalog
    -- band must trip 'ask' — comparing the (history) estimate against its own
    -- p90 would always tie and make EVERYTHING ask.
    v_policy_src := 'catalog_default';
    SELECT c.usd_p90 INTO v_cat_p90
    FROM public.ai_cost_class_catalog c
    WHERE c.kind = p_kind AND c.is_active;
    -- Fall back to the estimate's own p90 if the kind has no catalog row
    -- (strict '>' below then lets a within-band run allow).
    v_ask_over    := COALESCE(v_cat_p90, NULLIF(v_estimate->>'usd_p90', '')::numeric);
    v_allow_under := v_ask_over;
    v_deny_over   := v_ask_over * 3;
  END IF;

  -- 4. Budget remaining across ALL periods with a configured cap.
  FOR v_budget IN
    SELECT ab.period,
           ab.cost_limit,
           ab.consumed_cost,
           ab.token_limit,
           ab.consumed_tokens
    FROM public.ai_budget ab
    WHERE ab.scope_type = 'story'
      AND ab.scope_id = p_story_id
      AND (ab.cost_limit IS NOT NULL OR ab.token_limit IS NOT NULL)
  LOOP
    v_budgets := v_budgets || jsonb_build_object(
      'period', v_budget.period,
      'cost_limit', v_budget.cost_limit,
      'consumed_cost', v_budget.consumed_cost,
      'remaining',
        CASE WHEN v_budget.cost_limit IS NULL THEN NULL
             ELSE v_budget.cost_limit - v_budget.consumed_cost END,
      'token_limit', v_budget.token_limit,
      'consumed_tokens', v_budget.consumed_tokens
    );
    IF v_budget.cost_limit IS NOT NULL AND v_est IS NOT NULL
       AND v_budget.consumed_cost + v_est > v_budget.cost_limit THEN
      v_over_budget := true;
    END IF;
    IF v_budget.cost_limit IS NOT NULL
       AND v_budget.consumed_cost >= v_budget.cost_limit THEN
      v_over_budget := true;
    END IF;
    IF v_budget.token_limit IS NOT NULL
       AND v_budget.consumed_tokens >= v_budget.token_limit THEN
      v_over_budget := true;
    END IF;
  END LOOP;

  -- 5. Decision.
  IF v_est IS NULL THEN
    -- Unknown kind, no history, no catalog band: a human should look once;
    -- after the first few runs, history takes over and this self-resolves.
    v_decision := 'ask';
    v_reason   := 'no_estimate_available';
  ELSIF v_deny_over IS NOT NULL AND v_est >= v_deny_over THEN
    v_decision := 'deny';
    v_reason   := format('estimate %s >= deny threshold %s', v_est, v_deny_over);
  ELSIF v_over_budget THEN
    v_decision := 'ask';
    v_reason   := 'projected_cost_exceeds_remaining_budget';
  ELSIF v_ask_over IS NOT NULL AND v_est > v_ask_over THEN
    -- Strict '>' so a run whose conservative estimate sits exactly at the band
    -- (the cold-start case: catalog estimate == catalog threshold) ALLOWS; only
    -- a run projected ABOVE the band asks.
    v_decision := 'ask';
    v_reason   := format('estimate %s > ask threshold %s', v_est, v_ask_over);
  ELSE
    v_decision := 'allow';
    v_reason   := 'within_policy';
  END IF;

  RETURN jsonb_build_object(
    'decision', v_decision,
    'reason', v_reason,
    'estimate', v_estimate,
    'estimate_used', v_est,
    'policy_source', v_policy_src,
    'thresholds', jsonb_build_object(
      'allow_under', v_allow_under,
      'ask_over', v_ask_over,
      'deny_over', v_deny_over
    ),
    'budgets', v_budgets
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_authorize_task_spend(text, uuid, numeric) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_authorize_task_spend(text, uuid, numeric) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_authorize_task_spend(text, uuid, numeric) TO service_role;

COMMENT ON FUNCTION public.fn_authorize_task_spend(text, uuid, numeric) IS
  'Pre-flight spend authorization: estimate (history→catalog) × ai_spend_policies (most specific wins, catalog-band default) × ai_budget remaining (all periods) → {decision: allow|ask|deny, reason, estimate, thresholds, budgets}.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_ai_run.sql
-- -----------------------------------------------------------------------------

-- Source of Truth: create_ai_run
-- Purpose: Create a new AI run record for tracking agent execution.
--          Validates the run kind and assigns the actor user.
-- Used by: route_task (internal), ai-chat edge function, orchestrationBridge.ts
-- Migration: 20260216_aisha_phase3_router.sql (original)

-- 2026-07-30: p_estimate_usd forwarded to the admission it already calls.
-- fn_authorize_task_spend has taken a p_estimate since it was written; this
-- caller simply could not supply one, so every run was admitted against the p90
-- estimate of its KIND. For a run whose cost is known to be zero — a
-- deterministic SQL answer read out of verified facts, no model call — that
-- guess is the difference between a recorded run and no record at all: on a
-- story that is over budget, admission returns deny and the run is lost exactly
-- where accountability matters most. A caller that KNOWS its cost may now say so;
-- one that does not still gets the estimate. Denial stays possible and stays
-- meaningful (a policy may deny at 0), it just stops being a guess.
CREATE OR REPLACE FUNCTION public.create_ai_run(
  p_kind text,
  p_story_id uuid DEFAULT NULL::uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_route_plan jsonb DEFAULT '{}'::jsonb,
  p_estimate_usd numeric DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_run_id uuid;
  v_authz  jsonb;
BEGIN
  -- Validate kind
  IF p_kind NOT IN (
    'chat','project_delivery','compliance_check','guild_review',
    'pr_gate','incident','doc_update'
  ) THEN
    RAISE EXCEPTION USING MESSAGE = format('Invalid ai_run kind: %s', p_kind), ERRCODE = 'P0001';
  END IF;

  -- Spend admission (pre-flight). This path returns an immediately-running
  -- run (chat & friends), so ask/deny refuse LOUDLY instead of creating a
  -- blocked row (the INSERT would roll back with the exception anyway).
  -- Under catalog defaults interactive kinds (chat=micro) always allow;
  -- expensive kinds launched here surface a clear actionable error.
  v_authz := public.fn_authorize_task_spend(p_kind, p_story_id, p_estimate_usd);
  IF v_authz->>'decision' IN ('ask', 'deny') THEN
    RAISE EXCEPTION USING
      MESSAGE = format(
        'spend_%s: kind %s estimate $%s (%s) — adjust ai_spend_policies or use the workflow path for Mission Control approval',
        v_authz->>'decision', p_kind,
        COALESCE(v_authz->>'estimate_used', '?'),
        v_authz->>'reason'),
      ERRCODE = 'P0001';
  END IF;

  INSERT INTO ai_runs (kind, story_id, actor_user_id, route_plan, status)
  VALUES (p_kind, p_story_id, COALESCE(p_actor_user_id, auth.uid()), p_route_plan, 'running')
  RETURNING id INTO v_run_id;

  RETURN v_run_id;
END;
$function$;

-- Permissions. The 4-arg signature is DROPPED in heals before this file runs:
-- leaving both would make every 4-argument call ambiguous ("function is not
-- unique"), which is how an added default parameter breaks a working caller.
REVOKE ALL ON FUNCTION public.create_ai_run(text, uuid, uuid, jsonb, numeric) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_ai_run(text, uuid, uuid, jsonb, numeric) TO authenticated;
GRANT EXECUTE ON FUNCTION public.create_ai_run(text, uuid, uuid, jsonb, numeric) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/enqueue_agent_run.sql
-- -----------------------------------------------------------------------------

-- Function: public.enqueue_agent_run
-- Description: Create a new agent execution record and return its ID.
--   Called by svc-agent-runner / plugin-host / n8n to queue isolated workloads.
--   Writes an audit entry for every enqueue operation.
-- Security: SECURITY DEFINER, JEN service_role (volající jsou služby výš).
--
-- ⛔ NAMĚŘENO 2026-09-27 (fork <fork>): funkce byla udělená `authenticated`, ne
-- `service_role` — naopak, než jak se volá:
--   · svc-agent-runner ji volá SLUŽEBNÍM tokenem (rpcService) → PostgREST 403
--     „permission denied for function enqueue_agent_run" → každý běh pluginu
--     (plugin-exec) končil „Agent runner error 500";
--   · přihlášený uživatel ji mohl volat přímo a sám si zvolit `p_image` i druh.
--     Zařazený `claude_cli_task` bez politik útraty projde (výchozí pásmo katalogu
--     → allow, approval_required=false) a poller runneru spouští OBRAZ Z ŘÁDKU
--     (`run.image || config.agentClaudeImage`) — tedy obraz zvolený uživatelem.
--     Web ani appky ji nevolají; běhy uživatelů jdou přes POST /runs runneru.

CREATE OR REPLACE FUNCTION public.enqueue_agent_run(
  p_kind        text,
  p_profile     text,
  p_image       text,
  p_source      text,
  p_source_ref  text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_run_id uuid;
  v_authz  jsonb;
BEGIN
  -- Spend admission (pre-flight): execution-plane workloads have no story
  -- scope, so global policies + catalog bands decide. ask/deny refuse loudly.
  v_authz := public.fn_authorize_task_spend(p_kind, NULL);
  IF v_authz->>'decision' IN ('ask', 'deny') THEN
    RAISE EXCEPTION USING
      MESSAGE = format(
        'spend_%s: kind %s estimate $%s (%s) — adjust ai_spend_policies',
        v_authz->>'decision', p_kind,
        COALESCE(v_authz->>'estimate_used', '?'),
        v_authz->>'reason'),
      ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.agent_runs (kind, profile, image, requested_by, source, source_ref)
  VALUES (p_kind, p_profile, p_image, auth.uid(), p_source, p_source_ref)
  RETURNING id INTO v_run_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'agent_run.enqueued',
          jsonb_build_object('run_id', v_run_id, 'kind', p_kind, 'source', p_source));

  RETURN v_run_id;
END;
$$;

REVOKE ALL ON FUNCTION public.enqueue_agent_run(text, text, text, text, text) FROM PUBLIC;
-- Výslovně: CREATE OR REPLACE dřívější grant NEODEBERE, existující DB by ho držely dál.
REVOKE ALL ON FUNCTION public.enqueue_agent_run(text, text, text, text, text) FROM authenticated, anon;
GRANT EXECUTE ON FUNCTION public.enqueue_agent_run(text, text, text, text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_create_workflow_run.sql
-- -----------------------------------------------------------------------------

-- Function: fn_create_workflow_run
-- AISHA kick-off helper: creates an ai_runs entry bound to a workflow definition.
-- Returns the new run_id which the langgraph runner then orchestrates.
-- The graph itself is loaded by the runner from ai_workflow_definitions.graph.

CREATE OR REPLACE FUNCTION public.fn_create_workflow_run(
  p_workflow_definition_id uuid,
  p_input jsonb DEFAULT '{}'::jsonb,
  p_context jsonb DEFAULT '{}'::jsonb,
  p_story_id uuid DEFAULT NULL,
  p_actor_user_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_run_id     uuid;
  v_def        RECORD;
  v_kind       text;
  v_actor      uuid;
  v_run_status text := 'pending';
  v_authz      jsonb;
  v_awaiting   text;
BEGIN
  -- Auth
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_workflow_definition_id IS NULL THEN
    RAISE EXCEPTION 'p_workflow_definition_id is required';
  END IF;

  -- Load workflow definition + validate active
  SELECT id, name, display_name, context, is_active, version
  INTO v_def
  FROM ai_workflow_definitions
  WHERE id = p_workflow_definition_id;

  IF v_def IS NULL THEN
    RAISE EXCEPTION 'Workflow definition % not found', p_workflow_definition_id;
  END IF;

  IF NOT v_def.is_active THEN
    RAISE EXCEPTION 'Workflow definition % (%) is not active', v_def.name, p_workflow_definition_id;
  END IF;

  -- Derive run kind from workflow context (chat/reflection/deploy/...)
  v_kind := COALESCE(v_def.context, 'reflection');

  -- Resolve actor: explicit param > auth.uid() > NULL (service_role acting autonomously)
  v_actor := COALESCE(p_actor_user_id, auth.uid());

  -- Spend admission gate (pre-flight): estimate × policy × budget via
  -- fn_authorize_task_spend (history→catalog estimate; ai_spend_policies
  -- most-specific-wins with catalog-band defaults; ai_budget remaining
  -- across ALL periods — supersedes the old binary lifetime-only check).
  -- Stack-default exemption lives inside the authorizer.
  --   allow → pending (runner picks up)
  --   ask   → blocked + awaiting='spend_approval' (Mission Control pane)
  --   deny  → blocked + awaiting='spend_denied' (visible, not silently lost)
  v_authz := public.fn_authorize_task_spend(v_kind, p_story_id);
  IF v_authz->>'decision' = 'ask' THEN
    v_run_status := 'blocked';
    v_awaiting   := 'spend_approval';
  ELSIF v_authz->>'decision' = 'deny' THEN
    v_run_status := 'blocked';
    v_awaiting   := 'spend_denied';
  END IF;

  INSERT INTO ai_runs (
    kind,
    story_id,
    actor_user_id,
    status,
    workflow_definition_id,
    metadata,
    cost_total_json
  )
  VALUES (
    v_kind,
    p_story_id,
    v_actor,
    v_run_status,        -- 'pending' (runner picks up) | 'blocked' (spend ask/deny)
    p_workflow_definition_id,
    jsonb_strip_nulls(jsonb_build_object(
      'workflow_name', v_def.name,
      'workflow_version', v_def.version,
      'input', p_input,
      'context', p_context,
      'checkpoint', jsonb_build_object(
        'current_node', NULL,
        'iteration', 0,
        'history', '[]'::jsonb
      ),
      'created_via', 'fn_create_workflow_run',
      'awaiting', v_awaiting,
      'estimated_cost', NULLIF(v_authz->>'estimate_used', ''),
      'spend_authorization', v_authz
    )),
    '{}'::jsonb
  )
  RETURNING id INTO v_run_id;

  -- Trace event
  INSERT INTO ai_trace_events (
    run_id, event_type, operation, status, request_summary, response_summary
  )
  VALUES (
    v_run_id,
    -- 'workflow_start' is the matching ai_event_type member; 'workflow_create'
    -- is not a member, so this INSERT (event_type is ai_event_type NOT NULL)
    -- raised `invalid input value for enum ai_event_type` on every call.
    'workflow_start',
    'fn_create_workflow_run',
    'ok',
    jsonb_build_object(
      'workflow_definition_id', p_workflow_definition_id,
      'workflow_name', v_def.name,
      'story_id', p_story_id
    ),
    jsonb_build_object('run_id', v_run_id, 'kind', v_kind)
  );

  -- Audit
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_actor,
    'workflow.run_created',
    jsonb_build_object(
      'run_id', v_run_id,
      'workflow_definition_id', p_workflow_definition_id,
      'workflow_name', v_def.name,
      'story_id', p_story_id,
      'admission_status', v_run_status
    )
  );

  -- Governance signal: run blocked at admission by an exhausted story budget.
  IF v_run_status = 'blocked' THEN
    INSERT INTO audit_journal (user_id, action, metadata)
    VALUES (
      v_actor,
      'ai.budget.run_blocked',
      jsonb_build_object(
        'run_id', v_run_id,
        'story_id', p_story_id,
        'stage', 'admission'
      )
    );
  END IF;

  RETURN v_run_id;
END;
$$;

COMMENT ON FUNCTION public.fn_create_workflow_run(uuid, jsonb, jsonb, uuid, uuid) IS
  'Creates an ai_runs entry bound to a workflow definition. svc-langgraph-runner '
  'then loads the graph JSONB from ai_workflow_definitions and orchestrates nodes. '
  'Initial status=pending; runner transitions to running on first node execution.';

REVOKE ALL ON FUNCTION public.fn_create_workflow_run(uuid, jsonb, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_create_workflow_run(uuid, jsonb, jsonb, uuid, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_create_workflow_run(uuid, jsonb, jsonb, uuid, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_evaluate_proposal_risk.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_evaluate_proposal_risk
-- Popis: Centrální risk-evaluation RPC. Vrací 'low'|'medium'|'high'|'critical'
--        podle agent slug, category, a metadata. Rozšířeno (2026-04-28) o
--        Phase 1-4 deploy flow kategorie:
--           dashboard_rebuild     → vždy 'low' (read-only)
--           rollback              → 'medium'/'high'/'critical' (vždy >= medium)
--           blue_green_switch     → low/medium/high podle smoke + triggered_by
--           infrastructure_drift  → low/medium/high/critical podle drift_kind
--        Plus original logika pro security/database/auth/rls/function categories.
-- Volá: WF_APPROVAL_GATE, všechny 4 phase observers + orchestrator
-- Auth: authenticated nebo service_role
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_evaluate_proposal_risk(
  p_agent_slug text,
  p_category text,
  p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_score int := 0;
  v_agent record;
  v_files_changed int;
  v_drift_kind text;
  v_is_production boolean;
  v_triggered_by text;
  v_smoke_test_passed boolean;
BEGIN
  ----------------------------------------------------------------------------
  -- New category: dashboard_rebuild — always low
  ----------------------------------------------------------------------------
  IF p_category = 'dashboard_rebuild' THEN
    RETURN 'low';
  END IF;

  ----------------------------------------------------------------------------
  -- New category: rollback — always high or critical
  ----------------------------------------------------------------------------
  IF p_category = 'rollback' THEN
    -- Critical conditions
    IF (p_metadata->>'fatal_count')::int >= 10
       AND COALESCE((p_metadata->>'is_production')::boolean, false) THEN
      RETURN 'critical';
    END IF;
    IF (p_metadata->>'unique_users_affected')::int >= 1000
       AND COALESCE((p_metadata->>'is_production')::boolean, false) THEN
      RETURN 'critical';
    END IF;
    -- Production rollback always high
    IF COALESCE((p_metadata->>'is_production')::boolean, false) THEN
      RETURN 'high';
    END IF;
    -- Staging/preview rollback medium
    RETURN 'medium';
  END IF;

  ----------------------------------------------------------------------------
  -- New category: blue_green_switch
  ----------------------------------------------------------------------------
  IF p_category = 'blue_green_switch' THEN
    v_smoke_test_passed := COALESCE((p_metadata->>'smoke_test_passed')::boolean, false);
    v_triggered_by := COALESCE(p_metadata->>'triggered_by', 'manual');

    IF NOT v_smoke_test_passed THEN
      RETURN 'high';
    END IF;

    -- Major semver change → high
    IF p_metadata#>>'{image_tag_change,semver_kind}' = 'major' THEN
      RETURN 'high';
    END IF;

    -- Drift remediation triggered → medium (auto + notify)
    IF v_triggered_by = 'drift_remediation' THEN
      RETURN 'medium';
    END IF;

    -- Manual trigger → medium
    IF v_triggered_by = 'manual' THEN
      RETURN 'medium';
    END IF;

    -- CI push with patch semver → low
    IF v_triggered_by = 'ci_push'
       AND p_metadata#>>'{image_tag_change,semver_kind}' = 'patch' THEN
      RETURN 'low';
    END IF;

    -- CI push with minor semver → medium
    IF v_triggered_by = 'ci_push'
       AND p_metadata#>>'{image_tag_change,semver_kind}' = 'minor' THEN
      RETURN 'medium';
    END IF;

    -- Default for B/G
    RETURN 'medium';
  END IF;

  ----------------------------------------------------------------------------
  -- New category: infrastructure_drift
  ----------------------------------------------------------------------------
  IF p_category = 'infrastructure_drift' THEN
    v_drift_kind := COALESCE(p_metadata->>'drift_kind', 'unknown');
    v_is_production := COALESCE((p_metadata->>'is_production')::boolean, false);

    -- Critical: extra app (potentially rogue), prod database drift
    IF v_drift_kind = 'extra_app' THEN
      RETURN 'critical';
    END IF;
    IF v_is_production AND p_metadata->>'app_role' = 'database' THEN
      RETURN 'critical';
    END IF;

    -- High: secret drift, missing app, auth service drift
    IF v_drift_kind = 'secret_drift' THEN
      RETURN 'high';
    END IF;
    IF v_drift_kind = 'missing_app' THEN
      RETURN 'high';
    END IF;
    IF p_metadata->>'app_role' = 'auth' THEN
      RETURN 'high';
    END IF;

    -- Medium: image_tag in prod, replicas drift, traefik labels, env_var in prod
    IF v_drift_kind = 'image_tag' AND v_is_production THEN
      RETURN 'medium';
    END IF;
    IF v_drift_kind IN ('replicas', 'traefik_labels', 'domain_mismatch') THEN
      RETURN 'medium';
    END IF;
    IF v_drift_kind = 'env_var_value' AND v_is_production THEN
      RETURN 'medium';
    END IF;

    -- Low: env_var in non-prod, image_tag in non-prod, env_var_extra
    IF v_drift_kind IN ('env_var_value', 'env_var_missing', 'env_var_extra', 'image_tag') THEN
      RETURN 'low';
    END IF;

    -- Default for unknown drift kind
    RETURN 'medium';
  END IF;

  ----------------------------------------------------------------------------
  -- Category: task_spend — spend-approval escalations (WF_APPROVAL_GATE)
  -- Metadata: { estimate, threshold, budget_remaining?, kind }
  ----------------------------------------------------------------------------
  IF p_category = 'task_spend' THEN
    -- Critical: estimate dwarfs the threshold by an order of magnitude
    IF COALESCE((p_metadata->>'estimate')::numeric, 0)
       >= COALESCE(NULLIF((p_metadata->>'threshold')::numeric, 0), 1) * 10 THEN
      RETURN 'critical';
    END IF;
    -- High: estimate at 3x threshold or budget already exhausted
    IF COALESCE((p_metadata->>'estimate')::numeric, 0)
       >= COALESCE(NULLIF((p_metadata->>'threshold')::numeric, 0), 1) * 3 THEN
      RETURN 'high';
    END IF;
    IF COALESCE((p_metadata->>'budget_remaining')::numeric, 1) <= 0 THEN
      RETURN 'high';
    END IF;
    -- Default: a human look, no alarm
    RETURN 'medium';
  END IF;

  ----------------------------------------------------------------------------
  -- Original logic for non-deploy categories (unchanged)
  ----------------------------------------------------------------------------
  SELECT safety_level INTO v_agent FROM agent_catalog WHERE slug = p_agent_slug;

  -- Agent safety level score
  v_score := v_score + CASE v_agent.safety_level
    WHEN 'strict' THEN 30
    WHEN 'standard' THEN 15
    WHEN 'minimal' THEN 5
    ELSE 20
  END;

  -- Category risk score
  v_score := v_score + CASE p_category
    WHEN 'security' THEN 40
    WHEN 'database' THEN 35
    WHEN 'authentication' THEN 35
    WHEN 'rls' THEN 30
    WHEN 'function' THEN 20
    WHEN 'performance' THEN 15
    WHEN 'translation' THEN 5
    WHEN 'documentation' THEN 5
    ELSE 10
  END;

  -- Files changed score
  v_files_changed := COALESCE((p_metadata->>'files_changed')::int, 0);
  v_score := v_score + CASE
    WHEN v_files_changed > 10 THEN 25
    WHEN v_files_changed > 5 THEN 15
    WHEN v_files_changed > 2 THEN 10
    ELSE 0
  END;

  -- Sensitive path bonus
  IF p_metadata ? 'files_affected' AND
     p_metadata->>'files_affected' ~* '(security|auth|rls|migration|sensitive)' THEN
    v_score := v_score + 20;
  END IF;

  RETURN CASE
    WHEN v_score >= 70 THEN 'critical'
    WHEN v_score >= 45 THEN 'high'
    WHEN v_score >= 25 THEN 'medium'
    ELSE 'low'
  END;
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_evaluate_proposal_risk(text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_evaluate_proposal_risk(text, text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_evaluate_proposal_risk(text, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_get_chunks_needing_context.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_get_chunks_needing_context
-- Popis: Worker pickup queue for contextual retrieval backfill (Step 1).
--        Returns chunks whose contextual_prefix is NULL, joined with parent
--        knowledge_item for prompt construction (title + body excerpt).
-- Caller: services/svc-mcp-knowledge/src/routes/knowledge-embeddings.ts
--         (both inline new-chunk path and WF_CHUNK_CONTEXT_BACKFILL batch path)
--
-- Step:   Step 1 of retrieval optimization plan 2026
-- Bezpečnost: SECURITY DEFINER + service_role only
-- Audit:  N/A — read-only pickup, no audit row per worker poll
-- Source migration: aisha/db/migrations/20260518210000_contextual_retrieval.sql
-- ============================================================================

-- Brick3 locale axis: locale added to RETURNS TABLE. Appending an OUT column
-- changes the result shape, so the old definition must be DROPped before CREATE
-- (CREATE OR REPLACE cannot change the return type).
DROP FUNCTION IF EXISTS public.fn_get_chunks_needing_context(integer, uuid);

CREATE OR REPLACE FUNCTION public.fn_get_chunks_needing_context(
  p_batch_size integer DEFAULT 20,
  p_item_id    uuid    DEFAULT NULL
)
RETURNS TABLE (
  chunk_id            uuid,
  knowledge_item_id   uuid,
  chunk_index         integer,
  chunk_text          text,
  item_title          text,
  item_body_markdown  text,
  section_title       text,
  locale              text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT kc.id, kc.knowledge_item_id, kc.chunk_index, kc.chunk_text,
         ki.title, ki.body_markdown, kc.section_title, kc.locale
    FROM public.knowledge_chunks kc
    JOIN public.knowledge_items ki ON ki.id = kc.knowledge_item_id
   WHERE kc.contextual_prefix IS NULL
     AND ki.status = 'active'
     AND (p_item_id IS NULL OR kc.knowledge_item_id = p_item_id)
   ORDER BY kc.knowledge_item_id, kc.chunk_index
   LIMIT p_batch_size;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_get_chunks_needing_context(integer, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_get_chunks_needing_context(integer, uuid) TO service_role;

COMMENT ON FUNCTION public.fn_get_chunks_needing_context(integer, uuid) IS
  'Backfill / new-chunk worker queue: returns up to p_batch_size chunks (from active items) whose contextual_prefix is NULL. Service-role only.';


