CREATE OR REPLACE FUNCTION public.fn_get_runs_needing_graph_extract(
  p_batch_size     integer DEFAULT 20,
  p_max_age_hours  integer DEFAULT 168
)
RETURNS TABLE (
  run_id      uuid,
  kind        text,
