-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_graph_multihop.sql
-- -----------------------------------------------------------------------------

-- Source of Truth: fn_graph_multihop (Step 7)
-- Used by src/hooks/useRunGraphContext.ts (next-PR explainability panel)
-- and compose_context graph_context layer (Step 7.3 follow-up).
-- Migration: aisha/db/migrations/20260518270000_hippocampus_graph.sql

CREATE OR REPLACE FUNCTION public.fn_graph_multihop(
  p_start_node_id   uuid,
  p_max_depth       integer DEFAULT 3,
  p_relationships   text[]  DEFAULT NULL,
  p_story_id        uuid    DEFAULT NULL,
  p_limit           integer DEFAULT 50
)
RETURNS TABLE (
  depth                 integer,
  path                  uuid[],
  target_id             uuid,
  target_type           text,
  target_label          text,
  cumulative_confidence numeric,
  last_relationship     text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;
  IF p_max_depth < 1 OR p_max_depth > 6 THEN
    RAISE EXCEPTION 'p_max_depth must be 1..6';
  END IF;

  RETURN QUERY
  WITH RECURSIVE traversal AS (
    SELECT 0 AS depth, ARRAY[p_start_node_id] AS path,
           p_start_node_id AS current_id, 1.0::numeric AS confidence,
           NULL::text AS last_rel
     UNION ALL
    SELECT t.depth + 1, t.path || ge.target_node_id, ge.target_node_id,
           t.confidence * ge.confidence, ge.relationship
      FROM traversal t
      JOIN public.graph_edges ge ON ge.source_node_id = t.current_id
     WHERE t.depth < p_max_depth
       AND NOT (ge.target_node_id = ANY(t.path))
       AND (p_relationships IS NULL OR ge.relationship = ANY(p_relationships))
  )
  SELECT t.depth, t.path, t.current_id, gn.entity_type, gn.entity_label,
         t.confidence, t.last_rel
    FROM traversal t
    JOIN public.graph_nodes gn ON gn.id = t.current_id
   WHERE t.depth > 0
     AND (p_story_id IS NULL OR gn.story_id IS NULL OR gn.story_id = p_story_id)
   ORDER BY t.confidence DESC, t.depth ASC
   LIMIT p_limit;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_graph_multihop(uuid, integer, text[], uuid, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_graph_multihop(uuid, integer, text[], uuid, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_graph_multihop(uuid, integer, text[], uuid, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_log_agent_session_event.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_log_agent_session_event
-- Purpose: Record one agent-session event into ai_trace_events (the universal
--          telemetry signal) keyed by the session's ide_session ai_run —
--          NOT into a parallel per-source event table. Mapping:
--            tool_use            → event_type 'tool_call'
--            subagents_snapshot  → event_type 'task_checkpoint'
--          session_id rides in request_summary (indexed:
--          idx_ai_trace_events_session_id_request), so fn_advise_session_router
--          and the anomaly/performance readers see IDE activity natively.
--          Side effect: maintains agent_live_sessions.subagents for Agent
--          tool pre/post events (server-side accumulation, capped at 20).
-- Callers: dirigent-supervisor route (service_role), extension (authenticated).
-- Security: SECURITY DEFINER + REVOKE/GRANT. Fail-soft: unknown session → NULL
--           (caller relays are fire-and-forget fail-open).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_log_agent_session_event(
  p_session_id text,
  p_event_kind text,
  p_tool_name  text  DEFAULT NULL,
  p_file_path  text  DEFAULT NULL,
  p_payload    jsonb DEFAULT '{}'::jsonb,
  p_cost       jsonb DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_session    public.agent_live_sessions%ROWTYPE;
  v_event_type ai_event_type;
  v_event_id   uuid;
  v_agent_phase text;
  v_label      text;
  v_subagents  jsonb;
  v_idx        int;
  v_entry      jsonb;
  v_is_service boolean :=
    (current_setting('request.jwt.claims', true)::jsonb->>'role') = 'service_role';
  v_caller     uuid := auth.uid();
BEGIN
  -- Auth: service_role (dirigent relay backend) or an authenticated user.
  IF NOT v_is_service AND v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_session_id IS NULL OR btrim(p_session_id) = '' THEN
    RAISE EXCEPTION 'fn_log_agent_session_event: p_session_id required'
      USING ERRCODE = '22023';
  END IF;

  v_event_type := CASE p_event_kind
    WHEN 'tool_use'           THEN 'tool_call'::ai_event_type
    WHEN 'subagents_snapshot' THEN 'task_checkpoint'::ai_event_type
    ELSE NULL
  END;
  IF v_event_type IS NULL THEN
    RAISE EXCEPTION 'fn_log_agent_session_event: unknown event_kind %', p_event_kind
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_session
  FROM public.agent_live_sessions
  WHERE session_id = p_session_id;

  -- Fail-soft: relay callers are fail-open fire-and-forget; an event arriving
  -- before the session upsert (race) is dropped rather than erroring.
  IF v_session.id IS NULL OR v_session.ai_run_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Ownership: non-service callers may log only into their own sessions.
  IF NOT v_is_service
     AND v_session.user_id IS NOT NULL
     AND v_session.user_id <> v_caller THEN
    RAISE EXCEPTION 'Not authorized for session %', p_session_id
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.ai_trace_events
    (run_id, event_type, agent_slug, operation, status, cost_json,
     request_summary, response_summary)
  VALUES (
    v_session.ai_run_id,
    v_event_type,
    'ide:' || v_session.source,
    COALESCE(p_tool_name, p_event_kind),
    'ok',
    p_cost,
    jsonb_strip_nulls(jsonb_build_object(
      'session_id', p_session_id,
      'source', v_session.source,
      'story_id', v_session.story_id,
      'file_path', p_file_path,
      'branch', v_session.branch
    )),
    COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object('session_id', p_session_id)
  )
  RETURNING id INTO v_event_id;

  -- Server-side sub-agent accumulation: the Claude Code relay only sees
  -- Agent tool pre/post hook events; the live subagents snapshot is derived
  -- here so every UI consumer reads one canonical column.
  IF p_tool_name = 'Agent' THEN
    v_agent_phase := COALESCE(p_payload->>'phase', 'pre');
    v_label := COALESCE(
      NULLIF(btrim(p_payload->>'label'), ''),
      'agent'
    );
    v_subagents := COALESCE(v_session.subagents, '[]'::jsonb);

    IF v_agent_phase = 'pre' THEN
      v_subagents := v_subagents || jsonb_build_array(jsonb_build_object(
        'label', v_label,
        'status', 'running',
        'started_at', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
      ));
      -- Cap at the most recent 20 entries.
      IF jsonb_array_length(v_subagents) > 20 THEN
        SELECT jsonb_agg(elem) INTO v_subagents
        FROM (
          SELECT elem
          FROM jsonb_array_elements(v_subagents) WITH ORDINALITY AS t(elem, ord)
          ORDER BY t.ord
          OFFSET jsonb_array_length(v_subagents) - 20
        ) trimmed;
      END IF;
    ELSE
      -- post: mark the most recent running entry with this label completed.
      FOR v_idx IN REVERSE jsonb_array_length(v_subagents) - 1 .. 0 LOOP
        v_entry := v_subagents -> v_idx;
        IF v_entry->>'status' = 'running'
           AND (v_entry->>'label' = v_label OR v_label = 'agent') THEN
          v_subagents := jsonb_set(
            v_subagents,
            ARRAY[v_idx::text],
            v_entry || jsonb_build_object(
              'status', 'completed',
              'ended_at', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
            )
          );
          EXIT;
        END IF;
      END LOOP;
    END IF;

    UPDATE public.agent_live_sessions
    SET subagents = v_subagents, updated_at = now()
    WHERE id = v_session.id;
  END IF;

  RETURN v_event_id;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_log_agent_session_event(text, text, text, text, jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_log_agent_session_event(text, text, text, text, jsonb, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_log_agent_session_event(text, text, text, text, jsonb, jsonb) TO service_role;

COMMENT ON FUNCTION public.fn_log_agent_session_event(text, text, text, text, jsonb, jsonb) IS
  'Logs one agent-session event into ai_trace_events (tool_use→tool_call, subagents_snapshot→task_checkpoint) via the session''s ide_session ai_run; maintains agent_live_sessions.subagents from Agent tool pre/post events. Fail-soft NULL on unknown session.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_log_runtime_dispatch_trace.sql
-- -----------------------------------------------------------------------------

-- Function: fn_log_runtime_dispatch_trace
-- Writes ONE ai_trace_events row for an E3 runtime/executor dispatch, carrying the
-- runtime identity the generic insert_ai_trace_event drops: backend_kind, model_id,
-- and decision_id (→ ai_decisions.runtime). This is what makes the executor axis
-- OBSERVABLE — without it the reflection trace shows setup events (from
-- fn_create_workflow_run / compose_context) but never WHICH runtime ran the work.
--
-- Binds to the EXISTING run (p_run_id from the orchestrator) — unlike
-- fn_log_ai_trace_event it does NOT mint a new ai_run. Called by the runtime_dispatch
-- node after executeViaRuntime. Soft by design: a tracing failure must never brick a
-- dispatch, so the caller ignores errors.

CREATE OR REPLACE FUNCTION public.fn_log_runtime_dispatch_trace(
  p_run_id       uuid,
  p_runtime      text,
  p_event_type   text    DEFAULT 'llm_call',
  p_model_id     text    DEFAULT NULL,
  p_backend_kind text    DEFAULT NULL,
  p_decision_id  uuid    DEFAULT NULL,
  p_provider     text    DEFAULT NULL,
  p_status       text    DEFAULT 'ok',
  p_duration_ms  integer DEFAULT NULL,
  p_cost_json    jsonb   DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_event_id uuid;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  IF p_run_id IS NULL THEN
    RAISE EXCEPTION 'p_run_id required' USING ERRCODE = '22023';
  END IF;
  IF p_status NOT IN ('ok', 'error', 'timeout', 'skipped') THEN
    RAISE EXCEPTION 'Invalid status: %', p_status USING ERRCODE = '22023';
  END IF;

  INSERT INTO ai_trace_events (
    run_id, event_type, agent_slug, provider, operation,
    status, duration_ms, cost_json,
    decision_id, model_id, backend_kind
  )
  VALUES (
    p_run_id, p_event_type::ai_event_type, 'runtime_dispatch', p_provider,
    format('execute via %s', p_runtime),
    p_status, p_duration_ms, p_cost_json,
    p_decision_id, p_model_id, p_backend_kind
  )
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_log_runtime_dispatch_trace(uuid, text, text, text, text, uuid, text, text, integer, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_log_runtime_dispatch_trace(uuid, text, text, text, text, uuid, text, text, integer, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_log_runtime_dispatch_trace(uuid, text, text, text, text, uuid, text, text, integer, jsonb) TO service_role;

COMMENT ON FUNCTION public.fn_log_runtime_dispatch_trace(uuid, text, text, text, text, uuid, text, text, integer, jsonb) IS
  'E3 observability — one ai_trace_events row per runtime dispatch carrying backend_kind/model_id/decision_id (the executor identity the generic tracer drops), bound to the existing reflection run.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_maybe_promote_learning.sql
-- -----------------------------------------------------------------------------

-- Function: fn_maybe_promote_learning
-- Hippocampus learning: after repeated reuse, propose learning for promotion
-- to expert_rules via improvement_proposals (proposal_type='hippocampus_learning_promotion').
-- Promotion is human-gated through existing review workflow (WF_KB_COMPLIANCE_GATE
-- or similar improvement_proposals approval pipeline).

CREATE OR REPLACE FUNCTION public.fn_maybe_promote_learning(
  p_memory_id uuid,
  p_reuse_threshold integer DEFAULT 5,
  p_min_importance integer DEFAULT 6
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_memory RECORD;
  v_reuse_count integer;
  v_proposal_id uuid;
  v_proposal_existed boolean;
  v_pattern text;
  v_resolution text;
BEGIN
  -- Auth: authenticated user or service_role
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_memory_id IS NULL THEN
    RAISE EXCEPTION 'p_memory_id is required';
  END IF;

  -- Load the learning memory
  SELECT *
  INTO v_memory
  FROM agent_memories
  WHERE id = p_memory_id
    AND memory_type = 'learning';

  IF v_memory IS NULL THEN
    RAISE EXCEPTION 'Learning memory % not found', p_memory_id;
  END IF;

  -- Skip already-promoted
  IF v_memory.content ~ '"promoted_to_expert_rule":\s*true' THEN
    RETURN jsonb_build_object(
      'memory_id', p_memory_id,
      'action', 'skipped_already_promoted',
      'proposal_id', NULL
    );
  END IF;

  -- Count reuse via audit_journal entries
  SELECT COUNT(*)::integer
  INTO v_reuse_count
  FROM audit_journal
  WHERE action = 'hippocampus.learnings_retrieved'
    AND (metadata->'memory_ids') ? p_memory_id::text;

  -- Eligibility: enough reuses + sufficient importance
  IF v_reuse_count < p_reuse_threshold THEN
    RETURN jsonb_build_object(
      'memory_id', p_memory_id,
      'action', 'below_reuse_threshold',
      'reuse_count', v_reuse_count,
      'threshold', p_reuse_threshold
    );
  END IF;

  IF v_memory.importance < p_min_importance THEN
    RETURN jsonb_build_object(
      'memory_id', p_memory_id,
      'action', 'below_importance_threshold',
      'importance', v_memory.importance,
      'threshold', p_min_importance
    );
  END IF;

  -- Check idempotency: don't double-enqueue
  SELECT EXISTS(
    SELECT 1 FROM improvement_proposals
    WHERE proposal_type = 'hippocampus_learning_promotion'
      AND (metadata->>'memory_id')::uuid = p_memory_id
      AND status IN ('draft', 'pending_review', 'approved')
  )
  INTO v_proposal_existed;

  IF v_proposal_existed THEN
    SELECT id INTO v_proposal_id
    FROM improvement_proposals
    WHERE proposal_type = 'hippocampus_learning_promotion'
      AND (metadata->>'memory_id')::uuid = p_memory_id
    ORDER BY created_at DESC
    LIMIT 1;

    RETURN jsonb_build_object(
      'memory_id', p_memory_id,
      'action', 'proposal_already_pending',
      'proposal_id', v_proposal_id
    );
  END IF;

  -- Parse pattern + resolution from content (canonical form from fn_capture_learning)
  v_pattern    := split_part(split_part(v_memory.content, 'pattern: ', 2), E'\nresolution:', 1);
  v_resolution := split_part(split_part(v_memory.content, E'resolution: ', 2), E'\n\n[meta]', 1);

  -- Enqueue promotion proposal
  INSERT INTO improvement_proposals (
    proposal_type,
    title,
    description,
    rationale,
    proposed_value,
    source,
    priority,
    agent_slug,
    category,
    risk_level,
    metadata,
    created_by,
    status
  )
  VALUES (
    'hippocampus_learning_promotion',
    format('Promote learning: %s', LEFT(v_pattern, 80)),
    format('Pattern reused %s times reaches promotion threshold.', v_reuse_count),
    format(
      'This learning was captured from reflection runs and reused %s times '
      'with importance %s/10. Promoting to expert_rules makes it available '
      'as authoritative guidance for future runs (higher decision-provenance rank).',
      v_reuse_count, v_memory.importance
    ),
    jsonb_build_object(
      'pattern', v_pattern,
      'resolution', v_resolution,
      'memory_id', p_memory_id,
      'agent_slug', v_memory.agent_slug,
      'importance', v_memory.importance
    ),
    'hippocampus',
    7,
    v_memory.agent_slug,
    'knowledge',
    'low',
    jsonb_build_object(
      'memory_id', p_memory_id,
      'source_run_id', v_memory.source_run_id,
      'reuse_count', v_reuse_count
    ),
    COALESCE(auth.uid(), v_memory.user_id),
    'pending_review'
  )
  RETURNING id INTO v_proposal_id;

  -- Audit
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'hippocampus.learning_promotion_proposed',
    jsonb_build_object(
      'memory_id', p_memory_id,
      'proposal_id', v_proposal_id,
      'reuse_count', v_reuse_count,
      'importance', v_memory.importance
    )
  );

  RETURN jsonb_build_object(
    'memory_id', p_memory_id,
    'action', 'proposed',
    'proposal_id', v_proposal_id,
    'reuse_count', v_reuse_count,
    'importance', v_memory.importance
  );
END;
$$;

COMMENT ON FUNCTION public.fn_maybe_promote_learning(uuid, integer, integer) IS
  'Hippocampus learning: after p_reuse_threshold retrievals, propose promotion '
  'of a learning memory to expert_rules via improvement_proposals '
  '(proposal_type=hippocampus_learning_promotion). Idempotent: skips if '
  'already pending. Promotion itself is human-gated.';

REVOKE ALL ON FUNCTION public.fn_maybe_promote_learning(uuid, integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_maybe_promote_learning(uuid, integer, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_maybe_promote_learning(uuid, integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_notify_ai_feedback_ready.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- Function: fn_notify_ai_feedback_ready
-- Purpose: Notify local listeners and n8n when new AI feedback arrives
-- Part of: AISHA Learning Engine (ALE) — event-driven feedback pipeline
-- =============================================================================

CREATE OR REPLACE FUNCTION public.fn_notify_ai_feedback_ready()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_has_correction boolean := false;
  v_is_service_role boolean := false;
  v_payload jsonb;
  v_pending_count integer := 0;
  v_request_id bigint;
  v_webhook_url text;
BEGIN
  v_is_service_role := COALESCE(
    (current_setting('request.jwt.claims', true)::jsonb ->> 'role') = 'service_role',
    false
  );

  IF auth.uid() IS NULL AND NOT v_is_service_role THEN
    RAISE EXCEPTION 'Unauthorized: authenticated or service_role required';
  END IF;

  IF TG_OP <> 'INSERT' OR NEW.is_processed THEN
    RETURN NEW;
  END IF;

  v_has_correction := NEW.correction_text IS NOT NULL AND length(trim(NEW.correction_text)) > 10;

  SELECT count(*)
  INTO v_pending_count
  FROM public.ai_feedback af
  WHERE af.is_processed = false
    AND (
      (NEW.org_id IS NULL AND af.org_id IS NULL)
      OR af.org_id = NEW.org_id
    );

  v_payload := jsonb_build_object(
    'feedback_id', NEW.id,
    'org_id', NEW.org_id,
    'story_id', NEW.story_id,
    'run_id', NEW.run_id,
    'rating', NEW.rating,
    'feedback_category', NEW.feedback_category,
    'domain_tags', to_jsonb(COALESCE(NEW.domain_tags, '{}'::text[])),
    'has_correction', v_has_correction,
    'pending_count', v_pending_count,
    'triggered_at', now(),
    'source', 'db_trigger'
  );

  PERFORM pg_notify('ale_feedback_ready', v_payload::text);

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    NEW.user_id,
    'ALE_FEEDBACK_READY',
    jsonb_build_object(
      'area', 'ai_feedback',
      'severity', CASE WHEN v_has_correction THEN 'notice' ELSE 'info' END,
      'entity_type', 'ai_feedback',
      'entity_id', NEW.id,
      'pending_count', v_pending_count,
      'story_id', NEW.story_id
    )
  );

  BEGIN
    v_webhook_url := current_setting('app.settings.n8n_webhook_base_url', true);
    IF v_webhook_url IS NOT NULL AND v_webhook_url != '' THEN
      SELECT net.http_post(
        url     := v_webhook_url || '/webhook/ale-feedback-process',
        body    := v_payload,
        headers := '{"Content-Type": "application/json"}'::jsonb
      ) INTO v_request_id;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- user_id = auth.uid() (nullable): the '00000000-…0000' sentinel is not a real
    -- aisha_auth.users row → it violated audit_journal_user_id_fkey and turned a
    -- webhook hiccup into a hard failure of the triggering statement.
    INSERT INTO audit_journal(user_id, action, metadata)
    VALUES (
      auth.uid(),
      'ALE_WEBHOOK_DELIVERY_FAILED',
      jsonb_build_object(
        'severity', 'warning',
        'channel', 'ale_feedback_process',
        'feedback_id', NEW.id,
        'error', SQLERRM
      )
    );
  END;

  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_notify_ai_feedback_ready() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_notify_ai_feedback_ready() TO service_role;

COMMENT ON FUNCTION public.fn_notify_ai_feedback_ready() IS
  'Trigger function for ai_feedback inserts. Emits pg_notify ale_feedback_ready and bridges to n8n webhook when configured.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_notify_knowledge_change.sql
-- -----------------------------------------------------------------------------

-- Function: fn_notify_knowledge_change
-- Trigger function for knowledge_items and expert_rules changes → Ragnarok KB sync
-- Fires webhook to n8n WF_KB_RAGNAROK_SYNC workflow
--
-- Unlike fn_notify_rule_change (which handles copilot-instructions propagation),
-- this function handles the Ragnarok search index synchronization.

CREATE OR REPLACE FUNCTION public.fn_notify_knowledge_change()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_source_id uuid;
  v_source_slug text;
  v_action text;
  v_title text;
  v_category text;
  v_tags text[];
  v_story_id uuid;
  v_payload jsonb;
  v_webhook_url text;
BEGIN
  -- Determine action
  IF TG_OP = 'DELETE' THEN
    v_action := 'deleted';
  ELSIF TG_OP = 'INSERT' THEN
    v_action := 'created';
  ELSE
    v_action := 'updated';
  END IF;

  -- Extract fields based on source table
  IF TG_TABLE_NAME = 'expert_rules' THEN
    IF TG_OP = 'DELETE' THEN
      v_source_id := OLD.id;
      v_source_slug := OLD.slug;
      v_title := OLD.title;
      v_category := OLD.category::text;
      v_tags := OLD.ai_context_tags;
    ELSE
      v_source_id := NEW.id;
      v_source_slug := NEW.slug;
      v_title := NEW.title;
      v_category := NEW.category::text;
      v_tags := NEW.ai_context_tags;

      -- Skip if only timestamp changed (not meaningful for Ragnarok)
      IF TG_OP = 'UPDATE'
         AND OLD.body_markdown IS NOT DISTINCT FROM NEW.body_markdown
         AND OLD.ai_instructions IS NOT DISTINCT FROM NEW.ai_instructions
         AND OLD.title IS NOT DISTINCT FROM NEW.title
         AND OLD.summary IS NOT DISTINCT FROM NEW.summary
         AND OLD.status IS NOT DISTINCT FROM NEW.status
      THEN
        RETURN NEW;
      END IF;

      -- Skip draft and review rules (only sync published/archived)
      -- review = pending AISHA compliance gate, not yet approved
      IF NEW.status IN ('draft', 'review') THEN
        RETURN NEW;
      END IF;

      -- If archived, treat as delete from Ragnarok
      IF NEW.status = 'archived' THEN
        v_action := 'archived';
      END IF;
    END IF;

  ELSIF TG_TABLE_NAME = 'knowledge_items' THEN
    IF TG_OP = 'DELETE' THEN
      v_source_id := OLD.id;
      v_source_slug := OLD.source_slug;
      v_title := OLD.title;
      v_category := OLD.category;
      v_tags := OLD.ai_context_tags;
      v_story_id := OLD.story_id;
    ELSE
      v_source_id := NEW.id;
      v_source_slug := NEW.source_slug;
      v_title := NEW.title;
      v_category := NEW.category;
      v_tags := NEW.ai_context_tags;
      v_story_id := NEW.story_id;

      -- Skip non-meaningful changes
      IF TG_OP = 'UPDATE'
         AND OLD.body_markdown IS NOT DISTINCT FROM NEW.body_markdown
         AND OLD.ai_instructions IS NOT DISTINCT FROM NEW.ai_instructions
         AND OLD.title IS NOT DISTINCT FROM NEW.title
         AND OLD.summary IS NOT DISTINCT FROM NEW.summary
         AND OLD.status IS NOT DISTINCT FROM NEW.status
      THEN
        RETURN NEW;
      END IF;

      -- Skip inactive items
      IF NEW.status != 'active' AND v_action = 'created' THEN
        RETURN NEW;
      END IF;

      -- If archived, treat as delete from Ragnarok
      IF NEW.status = 'archived' THEN
        v_action := 'archived';
      END IF;
    END IF;
  END IF;

  -- Build payload (story_id surfaces per-story scope to n8n; routes upload to
  -- Ragnarok project_id='story-{uuid}' so Maestro per-story queries find it)
  v_payload := jsonb_build_object(
    'source_table', TG_TABLE_NAME,
    'source_id', v_source_id,
    'source_slug', v_source_slug,
    'story_id', v_story_id,
    'action', v_action,
    'title', v_title,
    'category', v_category,
    'tags', to_jsonb(COALESCE(v_tags, ARRAY[]::text[])),
    'triggered_at', now()
  );

  -- 1. pg_notify for local listeners
  PERFORM pg_notify('kb_ragnarok_sync', v_payload::text);

  -- 2. Log to audit_journal (user_id is NULL during seed/system triggers)
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'KB_RAGNAROK_SYNC_TRIGGER',
    jsonb_build_object(
      'area', 'knowledge',
      'severity', 'info',
      'entity_type', TG_TABLE_NAME,
      'entity_id', v_source_id,
      'change_action', v_action,
      'source_slug', v_source_slug
    )
  );

  -- 3. Bridge to n8n webhook via pg_net (if configured)
  DECLARE
    v_request_id bigint;
  BEGIN
    v_webhook_url := current_setting('app.settings.n8n_webhook_base_url', true);
    IF v_webhook_url IS NOT NULL AND v_webhook_url != '' THEN
      SELECT net.http_post(
        url     := v_webhook_url || '/webhook/kb-ragnarok-sync',
        body    := v_payload,
        headers := '{"Content-Type": "application/json"}'::jsonb
      ) INTO v_request_id;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- pg_net not available — pg_notify still works, but log the failure.
    -- user_id = auth.uid() (nullable, same as the success-path audit above): the
    -- previous '00000000-…0000' sentinel is NOT a real aisha_auth.users row, so
    -- this INSERT violated audit_journal_user_id_fkey and RAISEd — turning any
    -- webhook hiccup on an expert_rule/knowledge_item DELETE/publish/archive into
    -- a hard failure of the triggering statement. FK allows NULL, so auth.uid()
    -- (NULL for system/seed triggers) is safe.
    INSERT INTO audit_journal(user_id, action, metadata)
    VALUES (
      auth.uid(),
      'KB_WEBHOOK_DELIVERY_FAILED',
      jsonb_build_object(
        'severity', 'warning',
        'channel', 'kb_ragnarok_sync',
        'entity_type', TG_TABLE_NAME,
        'entity_id', v_source_id,
        'error', SQLERRM
      )
    );
  END;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION fn_notify_knowledge_change() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_notify_knowledge_change() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_notify_queued_agent_run.sql
-- -----------------------------------------------------------------------------

-- Function: fn_notify_queued_agent_run
-- Event source for the agent-runner: replaces svc-agent-runner's 500ms poll of
-- claim_queued_claude_run with a wake-on-event. Fires pg_notify('agent_run_queued')
-- the moment a claude_cli_task run BECOMES claimable — i.e. inserted already-queued,
-- or an approval-held run just got approved. event-worker (the cluster's LISTEN hub)
-- forwards the payload to svc-agent-runner's /wake endpoint, which claims immediately
-- (FOR UPDATE SKIP LOCKED, unchanged). A missed NOTIFY is harmless: the runner keeps a
-- slow safety-net poll. Claimable mirrors claim_queued_claude_run's guard exactly.
--
-- Includes table/schema in the payload so event-worker's existing table-keyed
-- webhookRoutes map routes it with config only (no event-worker code change).

CREATE OR REPLACE FUNCTION public.fn_notify_queued_agent_run()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_new_claimable boolean;
  v_old_claimable boolean;
BEGIN
  -- Claimable = a queued claude_cli_task not held for approval (mirror of the claim RPC).
  v_new_claimable := (NEW.kind = 'claude_cli_task'
                      AND NEW.status = 'queued'
                      AND NOT (NEW.approval_required AND NEW.approved_at IS NULL));

  IF TG_OP = 'UPDATE' THEN
    v_old_claimable := (OLD.kind = 'claude_cli_task'
                        AND OLD.status = 'queued'
                        AND NOT (OLD.approval_required AND OLD.approved_at IS NULL));
  ELSE
    v_old_claimable := false;  -- INSERT: nothing before
  END IF;

  -- Only wake on the transition INTO claimable (avoids spurious notifies on unrelated updates).
  IF v_new_claimable AND NOT v_old_claimable THEN
    PERFORM pg_notify('agent_run_queued', jsonb_build_object(
      'schema',     'public',
      'table',      'agent_runs',
      'event',      'agent_run_queued',
      'run_id',     NEW.id,
      'kind',       NEW.kind,
      'profile',    NEW.profile,
      'source',     NEW.source,
      'created_at', NEW.created_at
    )::text);
  END IF;

  RETURN NEW;
END;
$function$;

-- Trigger function: fires via trg_agent_runs_notify_queued as the definer; never
-- called directly, so service_role only (no client grant).
REVOKE ALL ON FUNCTION fn_notify_queued_agent_run() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_notify_queued_agent_run() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_proactive_condition_matches.sql
-- -----------------------------------------------------------------------------

-- Function: fn_proactive_condition_matches
-- Pure evaluator for an ai_proactive_trigger_definitions.condition against a row.
--
-- The condition JSONB is a small, injection-free DSL (no dynamic SQL):
--   {}                              → always matches
--   {"status": "queued"}            → NEW row's fields contain these (jsonb @>)
--   {"kind": "agent", "tier": 2}    → all key/values must match (containment)
--   {"__changed": ["status"]}       → on UPDATE, listed fields must DIFFER (OLD≠NEW);
--                                      vacuously true on INSERT
-- Equality + __changed can be combined. This covers the common reactive cases
-- (field-equals, field-changed) safely; richer operators can be layered later
-- without touching the dispatcher.

CREATE OR REPLACE FUNCTION public.fn_proactive_condition_matches(
  p_condition jsonb,
  p_new jsonb,
  p_old jsonb,
  p_event text
) RETURNS boolean
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO 'public'
AS $function$
DECLARE
  v_changed jsonb;
  v_field text;
  v_equality jsonb;
BEGIN
  IF p_condition IS NULL OR p_condition = '{}'::jsonb THEN
    RETURN true;
  END IF;

  -- __changed: fields that must differ between OLD and NEW (UPDATE only).
  v_changed := p_condition -> '__changed';
  IF v_changed IS NOT NULL AND jsonb_typeof(v_changed) = 'array' THEN
    IF p_event = 'UPDATE' AND p_old IS NOT NULL THEN
      FOR v_field IN SELECT jsonb_array_elements_text(v_changed) LOOP
        IF (p_old -> v_field) IS NOT DISTINCT FROM (p_new -> v_field) THEN
          RETURN false;  -- a required-changed field did not change
        END IF;
      END LOOP;
    END IF;
    -- INSERT: __changed is vacuously satisfied (the row is new).
  END IF;

  -- Remaining keys: exact key/value match against NEW via jsonb containment.
  v_equality := p_condition - '__changed';
  IF v_equality <> '{}'::jsonb THEN
    IF p_new IS NULL OR NOT (p_new @> v_equality) THEN
      RETURN false;
    END IF;
  END IF;

  RETURN true;
END;
$function$;

REVOKE ALL ON FUNCTION fn_proactive_condition_matches(jsonb, jsonb, jsonb, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_proactive_condition_matches(jsonb, jsonb, jsonb, text) TO service_role;
GRANT EXECUTE ON FUNCTION fn_proactive_condition_matches(jsonb, jsonb, jsonb, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_dispatch_proactive_triggers.sql
-- -----------------------------------------------------------------------------

-- Function: fn_dispatch_proactive_triggers
-- Generic AFTER INSERT/UPDATE trigger — the data-driven proactive dispatch engine.
--
-- Attached (automatically, via trg_proactive_defs_sync → fn_apply_proactive_dispatch_install)
-- to every table named by an ACTIVE ai_proactive_trigger_definitions row. For each firing
-- row it evaluates the matching definitions and, for each that passes its condition and is
-- outside its cooldown, records a pending ai_proactive_runs row (the OUTBOX — written in the
-- same transaction as the business row) and wakes the executor EVENT-DRIVEN with
-- pg_notify('ai_proactive_dispatch'). The executor in event-worker claims the run
-- (claim_proactive_run), acts on the rule's channel and finalizes it (finish_proactive_run);
-- a notify missed while it was down is caught up from the outbox (claim_pending_proactive_runs).
--
-- ⛔ NO pg_net (2026-09-28). This function used to bridge rules with `workflow_name` to n8n
-- via net.http_post — but pg_net is NOT in the DB image, so that branch never delivered a
-- single request (measured: no `net` schema). A dead branch that looks like delivery is
-- worse than none; it is removed and the outbox + executor is the only delivery path.
-- Gate sot-bez-pg-net keeps the remaining net.http_* users as a ratchet that only shrinks.
--
-- This is the generalized form of fn_notify_rule_change: instead of one hardcoded channel
-- and webhook path, the reactive rules live as DATA in ai_proactive_trigger_definitions.
--
-- Fail-safe: per-definition work is wrapped so one bad rule can never abort the source
-- table's transaction nor block sibling rules (RAISE WARNING to the server log + continue).

CREATE OR REPLACE FUNCTION public.fn_dispatch_proactive_triggers()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_new         jsonb;
  v_old         jsonb;
  v_record_id   uuid;
  v_def         record;
  v_user_id     uuid;
  v_run_id      uuid;
  v_payload     jsonb;
BEGIN
  v_new := to_jsonb(NEW);
  v_old := CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) ELSE NULL END;
  -- Best-effort source record id (most tables use an `id uuid` PK).
  BEGIN
    v_record_id := NULLIF(v_new ->> 'id', '')::uuid;
  EXCEPTION WHEN OTHERS THEN
    v_record_id := NULL;
  END;

  FOR v_def IN
    SELECT *
    FROM ai_proactive_trigger_definitions
    WHERE source_table = TG_TABLE_NAME
      AND source_event = TG_OP
      AND is_active = true
  LOOP
    BEGIN
      -- 1. Condition gate (pure, injection-free DSL).
      IF NOT fn_proactive_condition_matches(v_def.condition, v_new, v_old, TG_OP) THEN
        CONTINUE;
      END IF;

      -- 2. Resolve the owning user (proactive runs are user-scoped). A rule whose
      --    source row + author yield no user is misconfigured → skip (never fabricate).
      v_user_id := COALESCE(NULLIF(v_new ->> 'user_id', '')::uuid, v_def.created_by);
      IF v_user_id IS NULL THEN
        RAISE WARNING 'proactive: rule % on % has no resolvable user_id — skipped', v_def.name, TG_TABLE_NAME;
        CONTINUE;
      END IF;

      -- 3. Cooldown — recorded at dispatch time so it holds even if the executor is down.
      IF v_def.cooldown_minutes > 0 AND EXISTS (
        SELECT 1 FROM ai_proactive_runs r
        WHERE r.trigger_definition_id = v_def.id
          AND (v_record_id IS NULL OR r.source_record_id IS NOT DISTINCT FROM v_record_id)
          AND r.created_at > now() - make_interval(mins => v_def.cooldown_minutes)
      ) THEN
        CONTINUE;
      END IF;

      -- 4. Record the pending run (the durable event record + cooldown anchor).
      INSERT INTO ai_proactive_runs (
        trigger_definition_id, user_id, source_record_id, source_data, status, metadata
      ) VALUES (
        v_def.id, v_user_id, v_record_id, v_new, 'pending',
        jsonb_build_object('source_table', TG_TABLE_NAME, 'source_event', TG_OP, 'dispatched_at', now())
      )
      RETURNING id INTO v_run_id;

      -- 5. Build the wake-up payload — IDENTIFIERS ONLY. ⛔ pg_notify caps the payload at
      --    8000 bytes; the source row used to ride along, so a large row made pg_notify raise,
      --    the EXCEPTION below rolled the block back — INCLUDING the run just inserted — and
      --    the rule silently never fired. The executor reads source_data and action_config
      --    from the outbox when it claims the run; the wake-up only has to name it.
      v_payload := jsonb_build_object(
        'proactive_run_id', v_run_id,
        'definition_id',    v_def.id,
        'definition_name',  v_def.name,
        'channel',          v_def.action_config ->> 'channel',
        'source_table',     TG_TABLE_NAME,
        'source_event',     TG_OP,
        'source_record_id', v_record_id,
        'triggered_at',     now()
      );

      -- 6. Wake the executor (event-worker LISTEN). Only a wake-up: the run above is the
      --    durable record, so a notify lost while nobody listens is caught up from the outbox.
      PERFORM pg_notify('ai_proactive_dispatch', v_payload::text);

    EXCEPTION WHEN OTHERS THEN
      -- One rule failing must never abort the business write or the sibling rules.
      -- Record it durably so a broken rule is discoverable (v_user_id may be null if
      -- the failure preceded resolution — audit_journal.user_id is nullable) and warn.
      INSERT INTO audit_journal (user_id, action, metadata)
      VALUES (v_user_id, 'PROACTIVE_DISPATCH_FAILED', jsonb_build_object(
        'area', 'proactive', 'severity', 'warning',
        'definition_id', v_def.id, 'source_table', TG_TABLE_NAME, 'error', SQLERRM));
      RAISE WARNING 'proactive: rule % on % failed: %', v_def.name, TG_TABLE_NAME, SQLERRM;
    END;
  END LOOP;

  RETURN NEW;
END;
$function$;

-- Trigger function: fires via trg_proactive_dispatch as the definer; never called
-- directly, so it is granted to service_role only (no client grant — matches
-- fn_queue_embedding_generation, and keeps it out of the SEC_DEF_NO_AUTH class).
REVOKE ALL ON FUNCTION fn_dispatch_proactive_triggers() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_dispatch_proactive_triggers() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_apply_proactive_dispatch_install.sql
-- -----------------------------------------------------------------------------

-- Function: fn_apply_proactive_dispatch_install
-- Reconcile the presence of the generic proactive dispatch trigger on ONE source table
-- against whether any ACTIVE ai_proactive_trigger_definitions row still references it.
--
--   any active rule for table  +  trigger absent  → CREATE TRIGGER
--   no active rule for table    +  trigger present → DROP TRIGGER
--
-- Injection-safe: the table name is validated via to_regclass (must be a real relation)
-- and only ever interpolated with format('%I'). Unknown tables are skipped silently so a
-- typo in a rule can never error the caller. SECURITY DEFINER because it issues DDL.

CREATE OR REPLACE FUNCTION public.fn_apply_proactive_dispatch_install(p_source_table text)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_has_active     boolean;
  v_trigger_exists boolean;
BEGIN
  IF p_source_table IS NULL OR p_source_table = '' THEN
    RETURN;
  END IF;

  -- Validate: must be a real relation in `public` (injection-safe gate).
  IF to_regclass('public.' || quote_ident(p_source_table)) IS NULL THEN
    RAISE WARNING 'proactive: source_table public.% does not exist — dispatch trigger not installed', p_source_table;
    RETURN;
  END IF;

  v_has_active := EXISTS (
    SELECT 1 FROM ai_proactive_trigger_definitions
    WHERE source_table = p_source_table AND is_active = true
  );

  v_trigger_exists := EXISTS (
    SELECT 1
    FROM pg_trigger t
    JOIN pg_class c     ON c.oid = t.tgrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relname = p_source_table
      AND t.tgname  = 'trg_proactive_dispatch'
  );

  IF v_has_active AND NOT v_trigger_exists THEN
    EXECUTE format(
      'CREATE TRIGGER trg_proactive_dispatch AFTER INSERT OR UPDATE ON public.%I '
      || 'FOR EACH ROW EXECUTE FUNCTION fn_dispatch_proactive_triggers()',
      p_source_table
    );
    RAISE NOTICE 'proactive: installed trg_proactive_dispatch on public.%', p_source_table;
  ELSIF NOT v_has_active AND v_trigger_exists THEN
    EXECUTE format('DROP TRIGGER IF EXISTS trg_proactive_dispatch ON public.%I', p_source_table);
    RAISE NOTICE 'proactive: removed trg_proactive_dispatch from public.%', p_source_table;
  END IF;
END;
$function$;

REVOKE ALL ON FUNCTION fn_apply_proactive_dispatch_install(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_apply_proactive_dispatch_install(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_protect_core_values.sql
-- -----------------------------------------------------------------------------

-- Function: fn_protect_core_values

CREATE OR REPLACE FUNCTION public.fn_protect_core_values()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.item_type = 'core_value' THEN
      RAISE EXCEPTION 'Core values (tao) are immutable and cannot be deleted. item_id=%', OLD.id
        USING ERRCODE = 'P0001';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.item_type = 'core_value' THEN
      -- Allow only usage_count and rating_avg updates (read tracking)
      IF OLD.body_markdown IS DISTINCT FROM NEW.body_markdown
         OR OLD.ai_instructions IS DISTINCT FROM NEW.ai_instructions
         OR OLD.title IS DISTINCT FROM NEW.title
         OR OLD.summary IS DISTINCT FROM NEW.summary
         OR OLD.item_type IS DISTINCT FROM NEW.item_type
         OR OLD.status IS DISTINCT FROM NEW.status
         OR OLD.ai_context_tags IS DISTINCT FROM NEW.ai_context_tags
      THEN
        RAISE EXCEPTION 'Core values (tao) are immutable. Only usage_count/rating_avg may change. item_id=%', OLD.id
          USING ERRCODE = 'P0001';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$function$

;

REVOKE ALL ON FUNCTION fn_protect_core_values() FROM PUBLIC;


