-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_recalculate_ruleset_fingerprint.sql
-- -----------------------------------------------------------------------------

-- Function: fn_recalculate_ruleset_fingerprint

CREATE OR REPLACE FUNCTION public.fn_recalculate_ruleset_fingerprint(p_rule_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_affected integer := 0;
  v_ruleset RECORD;
  v_new_fingerprint text;
BEGIN
  -- Find all story_rulesets that reference this rule_id
  FOR v_ruleset IN
    SELECT id, rule_ids
    FROM story_rulesets
    WHERE p_rule_id = ANY(rule_ids)
  LOOP
    -- Recalculate fingerprint from current published rules content
    SELECT md5(string_agg(
      er.slug || ':' || er.version::text || ':' || COALESCE(er.ai_instructions, ''),
      '|' ORDER BY er.slug
    ))
    INTO v_new_fingerprint
    FROM expert_rules er
    WHERE er.id = ANY(v_ruleset.rule_ids)
      AND er.status = 'published';

    -- Update fingerprint (NULL if no published rules remain)
    UPDATE story_rulesets
    SET ruleset_fingerprint = COALESCE(v_new_fingerprint, 'empty')
    WHERE id = v_ruleset.id
      AND ruleset_fingerprint IS DISTINCT FROM COALESCE(v_new_fingerprint, 'empty');

    IF FOUND THEN
      v_affected := v_affected + 1;
    END IF;
  END LOOP;

  RETURN v_affected;
END;
$function$;

REVOKE ALL ON FUNCTION fn_recalculate_ruleset_fingerprint(p_rule_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_recalculate_ruleset_fingerprint(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION fn_recalculate_ruleset_fingerprint(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_notify_rule_change.sql
-- -----------------------------------------------------------------------------

-- Function: fn_notify_rule_change

CREATE OR REPLACE FUNCTION public.fn_notify_rule_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule_id uuid;
  v_action text;
  v_affected integer;
  v_payload jsonb;
  v_run_id uuid;
  v_webhook_url text;
BEGIN
  -- Determine the rule_id and action
  IF TG_OP = 'DELETE' THEN
    v_rule_id := OLD.id;
    v_action := 'deleted';
  ELSE
    v_rule_id := NEW.id;
    IF TG_OP = 'INSERT' THEN
      v_action := 'created';
    ELSE
      -- Only propagate on meaningful changes
      IF OLD.status = NEW.status
         AND OLD.version = NEW.version
         AND OLD.ai_instructions IS NOT DISTINCT FROM NEW.ai_instructions
         AND OLD.body_markdown IS NOT DISTINCT FROM NEW.body_markdown
         AND OLD.slug = NEW.slug
      THEN
        -- No meaningful change, skip propagation
        RETURN NEW;
      END IF;
      v_action := 'updated';
    END IF;
  END IF;

  -- 1. Recalculate affected ruleset fingerprints
  v_affected := fn_recalculate_ruleset_fingerprint(v_rule_id);

  -- 2. Build notification payload
  v_payload := jsonb_build_object(
    'rule_id', v_rule_id,
    'action', v_action,
    'slug', CASE WHEN TG_OP = 'DELETE' THEN OLD.slug ELSE NEW.slug END,
    'status', CASE WHEN TG_OP = 'DELETE' THEN OLD.status::text ELSE NEW.status::text END,
    'rulesets_affected', v_affected,
    'triggered_at', now()
  );

  -- 3. Create ai_run for trace FK
  v_run_id := gen_random_uuid();
  -- §16: a platform/system run has no tenant story, so it is anchored to the
  -- STACK-DEFAULT story — a real row, not a zero-uuid placeholder. The sentinel
  -- satisfied NOT NULL but referenced nothing, which is why story_id could never
  -- carry a foreign key. With a real anchor the constraint becomes enforceable
  -- AND fn_authorize_task_spend stops being handed a story that does not exist.
  --
  -- ⛔ story_id NULL, NE `ensure_stack_default_story()` (naměřeno 2026-09-29): ta je
  -- SECURITY INVOKER s guardem „admin/staff nebo service_role“ nad claims VOLAJÍCÍHO,
  -- takže každá změna pravidla pod běžnou identitou (autor-partner, publish_expert_rule)
  -- padala „Unauthorized“ uvnitř tohoto triggeru. Kotvu doplní BEFORE INSERT trigger
  -- `fn_ai_runs_default_story` vyhledáním (jeden domov invariantu, 2026-09-27); zápis
  -- pravidla autorizuje RLS na expert_rules, trigger je jen jeho vedlejší záznam.
  INSERT INTO ai_runs (id, story_id, kind, status, started_at, finished_at, cost_total_json, metadata)
  VALUES (
    v_run_id,
    NULL,
    'proactive',
    'succeeded',
    now(),
    now(),
    '{"usd": 0}'::jsonb,
    v_payload
  );

  -- 4. Log trace event
  INSERT INTO ai_trace_events (
    run_id,
    event_type,
    agent_slug,
    operation,
    status,
    request_summary,
    created_at
  ) VALUES (
    v_run_id,
    'proactive_trigger',
    'dirigent',
    'rule_propagation',
    'ok',
    v_payload,
    now()
  );

  -- 5. Send pg_notify for local listeners (edge functions, realtime)
  PERFORM pg_notify('expert_rule_changed', v_payload::text);

  -- 6. Bridge to n8n webhook via pg_net (if configured)
  --    Set n8n URL via: ALTER DATABASE postgres SET app.settings.n8n_webhook_base_url = 'https://...';
  DECLARE
    v_request_id bigint;
  BEGIN
    v_webhook_url := current_setting('app.settings.n8n_webhook_base_url', true);
    IF v_webhook_url IS NOT NULL AND v_webhook_url != '' THEN
      SELECT net.http_post(
        url     := v_webhook_url || '/webhook/rule-propagation',
        body    := v_payload,
        headers := '{"Content-Type": "application/json"}'::jsonb
      ) INTO v_request_id;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- pg_net not available or network error — rely on pg_notify only.
    -- NOTE: intentionally NO audit_journal insert here. The fallback user_id
    -- '00000000-...' is not FK-valid in aisha_auth.users and would abort the caller's
    -- transaction (breaks any INSERT into expert_rules from a migration run as
    -- supabase_admin where auth.uid() is NULL).
    NULL;
  END;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION fn_notify_rule_change() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_notify_rule_change() TO authenticated;
GRANT EXECUTE ON FUNCTION fn_notify_rule_change() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_reconcile_proactive_dispatch_installs.sql
-- -----------------------------------------------------------------------------

-- Function: fn_reconcile_proactive_dispatch_installs
-- Idempotent full reconcile of dispatch triggers across every table referenced by an
-- ACTIVE rule, plus removal of any stale trg_proactive_dispatch left on tables that no
-- longer have an active rule. Safe to run any number of times; intended for cold-start
-- (post-seed) and operational healing after a table is recreated. Returns the count of
-- tables that now carry the dispatch trigger.

CREATE OR REPLACE FUNCTION public.fn_reconcile_proactive_dispatch_installs()
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_table text;
  v_count integer := 0;
BEGIN
  -- Tables that SHOULD have the trigger (any active rule).
  FOR v_table IN
    SELECT DISTINCT source_table FROM ai_proactive_trigger_definitions WHERE is_active = true
  LOOP
    PERFORM fn_apply_proactive_dispatch_install(v_table);
  END LOOP;

  -- Tables that currently HAVE the trigger but no longer have an active rule → remove.
  FOR v_table IN
    SELECT c.relname
    FROM pg_trigger t
    JOIN pg_class c     ON c.oid = t.tgrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND t.tgname  = 'trg_proactive_dispatch'
      AND NOT EXISTS (
        SELECT 1 FROM ai_proactive_trigger_definitions d
        WHERE d.source_table = c.relname AND d.is_active = true
      )
  LOOP
    PERFORM fn_apply_proactive_dispatch_install(v_table);
  END LOOP;

  SELECT count(*) INTO v_count
  FROM pg_trigger t
  JOIN pg_class c     ON c.oid = t.tgrelid
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND t.tgname = 'trg_proactive_dispatch';

  RETURN v_count;
END;
$function$;

REVOKE ALL ON FUNCTION fn_reconcile_proactive_dispatch_installs() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_reconcile_proactive_dispatch_installs() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_record_critic_iteration_audited.sql
-- -----------------------------------------------------------------------------

-- Source of Truth: fn_record_critic_iteration_audited (Step 5)
-- Used by services/svc-ai-chat/src/lib/criticLoop.ts
-- Behavior: logs critic iteration AND propagates final faithfulness to
--           ai_runs.faithfulness_score_estimate on terminal decisions
--           (stop_threshold_met / stop_iter_cap) — so Step 2 UI
--           useRunFaithfulness reads the right value.
-- Migrations: 20260518250000_critic_loop.sql (table + initial RPC)
--             20260519010000_critic_iteration_updates_ai_run.sql (ai_runs propagation)

CREATE OR REPLACE FUNCTION public.fn_record_critic_iteration_audited(
  p_run_id              uuid,
  p_iteration           smallint,
  p_faithfulness        numeric,
  p_context_recall      numeric,
  p_retrieved_chunk_ids uuid[],
  p_retrieval_strategy  text,
  p_decision            text,
  p_judge_model         text,
  p_judge_provider_slug text,
  p_metadata            jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE v_id uuid;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;
  IF p_run_id IS NULL THEN RAISE EXCEPTION 'p_run_id is required'; END IF;
  IF p_iteration IS NULL THEN RAISE EXCEPTION 'p_iteration is required'; END IF;

  INSERT INTO public.ai_run_critic_iterations (
    ai_run_id, iteration, faithfulness_estimate, context_recall_estimate,
    retrieved_chunk_ids, retrieval_strategy, decision,
    judge_model, judge_provider_slug, metadata
  ) VALUES (
    p_run_id, p_iteration, p_faithfulness, p_context_recall,
    COALESCE(p_retrieved_chunk_ids, '{}'::uuid[]), p_retrieval_strategy, p_decision,
    p_judge_model, p_judge_provider_slug, COALESCE(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (ai_run_id, iteration) DO UPDATE
    SET faithfulness_estimate = EXCLUDED.faithfulness_estimate,
        context_recall_estimate = EXCLUDED.context_recall_estimate,
        retrieved_chunk_ids = EXCLUDED.retrieved_chunk_ids,
        retrieval_strategy = EXCLUDED.retrieval_strategy,
        decision = EXCLUDED.decision,
        judge_model = EXCLUDED.judge_model,
        judge_provider_slug = EXCLUDED.judge_provider_slug,
        metadata = EXCLUDED.metadata
  RETURNING id INTO v_id;

  -- Step 5 micro-fix (migration 20260519010000): propagate FINAL faithfulness
  -- to ai_runs.faithfulness_score_estimate on terminal decisions so Step 2
  -- UI useRunFaithfulness reads the right value. Non-terminal 'continue'
  -- iterations don't update because they're not the final answer score.
  IF p_decision LIKE 'stop_%' AND p_faithfulness IS NOT NULL THEN
    UPDATE public.ai_runs
       SET faithfulness_score_estimate = p_faithfulness
     WHERE id = p_run_id;
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'hippocampus.critic_iteration',
    jsonb_build_object('iteration_id', v_id, 'run_id', p_run_id,
      'iteration', p_iteration, 'decision', p_decision,
      'strategy', p_retrieval_strategy, 'faithfulness', p_faithfulness,
      'judge_model', p_judge_model, 'judge_provider', p_judge_provider_slug,
      'propagated_to_ai_run', p_decision LIKE 'stop_%' AND p_faithfulness IS NOT NULL));

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_record_critic_iteration_audited(uuid, smallint, numeric, numeric, uuid[], text, text, text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_record_critic_iteration_audited(uuid, smallint, numeric, numeric, uuid[], text, text, text, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_record_execution_decision.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_record_execution_decision  (E0 decision journal writer)
-- Purpose: THE only writer of ai_decisions. Persists one AishaExecutionDecision
--          (+ admission verdict) and returns its decision_id (the row id) so the
--          caller threads it onto ai_trace_events + every runtime adapter.
--          Structured columns are projected from the decision blob; the full
--          blob is stored for fidelity. VOLATILE wrapper around the STABLE
--          resolver/admission RPCs (which must never write).
-- Security: SECURITY DEFINER, VOLATILE. authenticated + service_role.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_record_execution_decision(
  p_decision jsonb,
  p_run_id   uuid DEFAULT NULL,
  p_story_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id uuid;
BEGIN
  -- Fail-closed: NULL-safe role check. With absent/empty claims the role is NULL,
  -- and `NULL <> 'service_role'` is NULL (not TRUE) — which would let an
  -- unauthenticated caller through. IS DISTINCT FROM treats NULL as a value, so a
  -- caller with no auth.uid() and no service_role role is rejected. (Defense in
  -- depth behind the authenticated/service_role-only EXECUTE grant.)
  IF auth.uid() IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') IS DISTINCT FROM 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_decision IS NULL OR p_decision = '{}'::jsonb THEN
    RAISE EXCEPTION 'fn_record_execution_decision: p_decision required' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.ai_decisions (
    run_id, story_id, clow_purpose,
    runtime, cli_slug,
    provider_slug, model_id, backend_kind, strategy,
    admission_verdict, risk_level, approval_required,
    resolution_source, reason, estimated_cost,
    resolver_policy_id,
    decision_json
  )
  VALUES (
    p_run_id,
    p_story_id,
    p_decision->>'clow_purpose',
    COALESCE(p_decision->>'runtime', 'direct_llm'),
    p_decision->>'cli_slug',
    p_decision->>'provider_slug',
    p_decision->>'model_id',
    p_decision->>'backend_kind',
    p_decision->>'strategy',
    p_decision->>'admission_verdict',
    p_decision->>'risk_level',
    COALESCE((p_decision->>'approval_required')::boolean, false),
    p_decision->>'resolution_source',
    p_decision->>'reason',
    NULLIF(p_decision->>'cost', '')::numeric,
    -- the active resolver policy that produced this decision (threaded from inputs.policy.id).
    NULLIF(COALESCE(p_decision->'policy'->>'id', p_decision->'inputs'->'policy'->>'id'), '')::uuid,
    p_decision
  )
  RETURNING id INTO v_id;

  -- Normalize the resolver's per-candidate ranking (already carried in the blob) into queryable
  -- rows so the admin drilldown can show WHY each candidate scored. Graceful: a decision with no
  -- candidate array (non-resolver path) inserts nothing.
  INSERT INTO public.ai_decision_candidates
    (decision_id, rank, is_top, provider_slug, model_id, backend_kind, score, reason)
  SELECT
    v_id,
    row_number() OVER (ORDER BY (c->>'score')::numeric DESC NULLS LAST)::int,
    (row_number() OVER (ORDER BY (c->>'score')::numeric DESC NULLS LAST) = 1),
    c->>'provider_slug', c->>'model_id', c->>'backend_kind',
    NULLIF(c->>'score', '')::numeric, c->>'reason'
  FROM jsonb_array_elements(
    CASE WHEN jsonb_typeof(p_decision->'candidates') = 'array'
         THEN p_decision->'candidates' ELSE '[]'::jsonb END) AS c;

  RETURN v_id;
END;
$$;

COMMENT ON FUNCTION public.fn_record_execution_decision(jsonb, uuid, uuid) IS
  'E0 decision journal writer (the only writer of ai_decisions). Persists an AishaExecutionDecision + verdict, returns decision_id. VOLATILE wrapper; resolver/admission RPCs stay STABLE.';

REVOKE ALL ON FUNCTION public.fn_record_execution_decision(jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_record_execution_decision(jsonb, uuid, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_record_execution_decision(jsonb, uuid, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_record_multimodal_page_audited.sql
-- -----------------------------------------------------------------------------

-- Function: fn_record_multimodal_page_audited
-- Single text-input audited writer for a multimodal page's v2 (halfvec(2560)) embedding —
-- mirrors the chunk path insert_knowledge_embedding_v2_audited(text). Takes the embedding
-- as a JSON text array (NULL/'' = page recorded without an embedding yet), casts it to
-- halfvec(2560) for knowledge_multimodal_pages.embedding_v2, upserts the page, and writes
-- its audit_journal row (the _audited contract).
--
-- ONE overload by design: the prior vector/halfvec typed overloads were a PGRST203-
-- ambiguous back-port artifact with identical parameter names and zero callers, consolidated
-- into this canonical text form (rewrite, not capability removal — the multimodal v2 space,
-- the embedding_v2 halfvec(2560) column, is untouched).

CREATE OR REPLACE FUNCTION public.fn_record_multimodal_page_audited(p_item_id uuid, p_page_number integer, p_page_image_uri text, p_page_image_sha256 text, p_page_text text, p_embedding_v2 text, p_embedding_model text, p_embedding_version text, p_metadata jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_id uuid;
  v_embedding halfvec(2560);
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;
  IF p_item_id IS NULL OR p_page_number IS NULL THEN
    RAISE EXCEPTION 'p_item_id and p_page_number are required';
  END IF;

  -- text -> halfvec(2560) (the v2 space constant); NULL/'' means "page recorded, no
  -- embedding yet" so status stays 'pending'. Cast after the auth/arg guards.
  v_embedding := CASE
    WHEN p_embedding_v2 IS NULL OR p_embedding_v2 = '' THEN NULL
    ELSE p_embedding_v2::halfvec(2560)
  END;

  INSERT INTO public.knowledge_multimodal_pages (
    knowledge_item_id, page_number, page_image_uri, page_image_sha256,
    page_text, embedding_v2, embedding_model, embedding_version,
    embedding_generated_at, status, metadata
  ) VALUES (
    p_item_id, p_page_number, p_page_image_uri, p_page_image_sha256,
    p_page_text, v_embedding, p_embedding_model, p_embedding_version,
    CASE WHEN v_embedding IS NOT NULL THEN now() ELSE NULL END,
    CASE WHEN v_embedding IS NOT NULL THEN 'embedded' ELSE 'pending' END,
    COALESCE(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (knowledge_item_id, page_number) DO UPDATE
    SET page_image_uri = EXCLUDED.page_image_uri,
        page_image_sha256 = EXCLUDED.page_image_sha256,
        page_text = EXCLUDED.page_text,
        embedding_v2 = EXCLUDED.embedding_v2,
        embedding_model = EXCLUDED.embedding_model,
        embedding_version = EXCLUDED.embedding_version,
        embedding_generated_at = EXCLUDED.embedding_generated_at,
        status = EXCLUDED.status,
        metadata = EXCLUDED.metadata
  RETURNING id INTO v_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'knowledge.multimodal_page_recorded',
    jsonb_build_object('page_id', v_id, 'item_id', p_item_id,
      'page_number', p_page_number, 'embedding_model', p_embedding_model));

  RETURN v_id;
END;
$function$
;

REVOKE ALL ON FUNCTION fn_record_multimodal_page_audited(uuid,integer,text,text,text,text,text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_record_multimodal_page_audited(uuid,integer,text,text,text,text,text,text,jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_record_rag_eval_run_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_record_rag_eval_run_audited
-- Popis: Persist a single eval run row in public.rag_eval_runs with all 4
--        RAGAS-style scores + audit_journal entry. Called per golden row
--        by services/svc-mcp-knowledge/src/routes/rag-eval.ts.
--
-- Step:   Step 0 of retrieval optimization plan 2026
-- Bezpečnost: SECURITY DEFINER + service_role only
-- Audit:  INSERT INTO audit_journal (action='rag_eval.run_recorded', metadata)
-- Source migration: aisha/db/migrations/20260518200000_rag_eval_foundation.sql
-- ============================================================================

-- A currency-suffixed name (`*_usd`) was removed from this function's signature.
-- The TYPES did not change, so CREATE OR REPLACE matches the deployed function and
-- Postgres refuses to rename in place ("cannot change name of input parameter", or
-- "cannot change return type" when the renamed name is a RETURNS TABLE column).
-- DROP-first is the convention used elsewhere in this directory; the REVOKE/GRANT
-- below re-applies whatever privileges the drop clears.
DROP FUNCTION IF EXISTS public.fn_record_rag_eval_run_audited(uuid, uuid, text, text, text, text, text, uuid[], text, jsonb, integer, numeric, uuid, jsonb);

CREATE OR REPLACE FUNCTION public.fn_record_rag_eval_run_audited(
  p_golden_id                uuid,
  p_batch_id                 uuid,
  p_embedding_model          text,
  p_embedding_model_version  text,
  p_llm_model                text,
  p_judge_model              text,
  p_context_profile_slug     text,
  p_retrieved_chunk_ids      uuid[],
  p_generated_answer         text,
  p_scores                   jsonb,
  p_latency_ms               integer,
  p_cost                 numeric,
  p_ai_run_id                uuid DEFAULT NULL,
  p_metadata                 jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_run_id uuid;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  IF p_golden_id IS NULL THEN
    RAISE EXCEPTION 'p_golden_id is required';
  END IF;
  IF p_batch_id IS NULL THEN
    RAISE EXCEPTION 'p_batch_id is required';
  END IF;
  IF p_embedding_model IS NULL OR p_embedding_model = '' THEN
    RAISE EXCEPTION 'p_embedding_model is required';
  END IF;
  IF p_llm_model IS NULL OR p_llm_model = '' THEN
    RAISE EXCEPTION 'p_llm_model is required';
  END IF;

  INSERT INTO public.rag_eval_runs (
    golden_id, batch_id, embedding_model, embedding_model_version,
    llm_model, judge_model, context_profile_slug, retrieved_chunk_ids,
    generated_answer,
    faithfulness_score, answer_relevancy_score,
    context_precision_score, context_recall_score,
    latency_ms, cost, metadata, ai_run_id
  ) VALUES (
    p_golden_id, p_batch_id, p_embedding_model, p_embedding_model_version,
    p_llm_model, p_judge_model, p_context_profile_slug, COALESCE(p_retrieved_chunk_ids, '{}'::uuid[]),
    p_generated_answer,
    NULLIF(p_scores->>'faithfulness', '')::numeric,
    NULLIF(p_scores->>'answer_relevancy', '')::numeric,
    NULLIF(p_scores->>'context_precision', '')::numeric,
    NULLIF(p_scores->>'context_recall', '')::numeric,
    p_latency_ms, p_cost, COALESCE(p_metadata, '{}'::jsonb), p_ai_run_id
  )
  RETURNING id INTO v_run_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'rag_eval.run_recorded',
    jsonb_build_object(
      'run_id', v_run_id,
      'golden_id', p_golden_id,
      'batch_id', p_batch_id,
      'embedding_model', p_embedding_model,
      'llm_model', p_llm_model,
      'profile', p_context_profile_slug,
      'scores', p_scores,
      'chunk_count', COALESCE(array_length(p_retrieved_chunk_ids, 1), 0),
      'latency_ms', p_latency_ms,
      'cost', p_cost
    )
  );

  RETURN v_run_id;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_record_rag_eval_run_audited(uuid, uuid, text, text, text, text, text, uuid[], text, jsonb, integer, numeric, uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_record_rag_eval_run_audited(uuid, uuid, text, text, text, text, text, uuid[], text, jsonb, integer, numeric, uuid, jsonb) TO service_role;
-- service_role ONLY — no end user records an eval run. REVOKE ... FROM PUBLIC does
-- NOT remove a grant made explicitly to a role, so a database that once granted
-- this to authenticated would silently keep it. Revoke by name so the intent
-- reaches an already-deployed instance too (heals-revoke-reaches-existing-db gate).
REVOKE ALL ON FUNCTION public.fn_record_rag_eval_run_audited(uuid, uuid, text, text, text, text, text, uuid[], text, jsonb, integer, numeric, uuid, jsonb) FROM authenticated;
REVOKE ALL ON FUNCTION public.fn_record_rag_eval_run_audited(uuid, uuid, text, text, text, text, text, uuid[], text, jsonb, integer, numeric, uuid, jsonb) FROM anon;

COMMENT ON FUNCTION public.fn_record_rag_eval_run_audited(uuid, uuid, text, text, text, text, text, uuid[], text, jsonb, integer, numeric, uuid, jsonb) IS
  'Persist single eval run with all 4 RAGAS-style scores; writes audit row (rag_eval.run_recorded). Service-role only.';


