-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_record_safety_scan_audited.sql
-- -----------------------------------------------------------------------------

-- Source of Truth: fn_record_safety_scan_audited (Step 4)
-- Used by services/svc-mcp-knowledge ingestion-safety scanner.
-- Migration: aisha/db/migrations/20260518240000_ingestion_safety.sql

CREATE OR REPLACE FUNCTION public.fn_record_safety_scan_audited(
  p_item_id  uuid,
  p_metadata jsonb,
  p_reason   text,
  p_score    numeric,
  p_status   text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;
  IF p_item_id IS NULL THEN RAISE EXCEPTION 'p_item_id is required'; END IF;
  IF p_status NOT IN ('clear', 'flagged', 'quarantined') THEN
    RAISE EXCEPTION 'p_status must be clear, flagged, or quarantined';
  END IF;
  IF p_score IS NULL OR p_score < 0 OR p_score > 1 THEN
    RAISE EXCEPTION 'p_score must be in [0, 1]';
  END IF;

  UPDATE public.knowledge_items
     SET quarantine_status   = p_status,
         quarantine_reason   = p_reason,
         quarantine_metadata = COALESCE(p_metadata, '{}'::jsonb),
         safety_scanned_at   = now(),
         safety_score        = p_score
   WHERE id = p_item_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'ingestion.safety_scan_completed',
    jsonb_build_object('item_id', p_item_id, 'status', p_status, 'score', p_score, 'reason', p_reason));
END;
$$;

REVOKE ALL ON FUNCTION public.fn_record_safety_scan_audited(uuid, jsonb, text, numeric, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_record_safety_scan_audited(uuid, jsonb, text, numeric, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_resolve_approval_request.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_resolve_approval_request
-- Persists an approval DECISION raised by WF_APPROVAL_GATE (Resolve Approval
-- node). Records the human/operator decision + comment + responder against an
-- existing request in the approval_requests ledger and transitions its status.
-- Security: SECURITY DEFINER (service_role-invoked via aishaRpc), search_path pinned.

CREATE OR REPLACE FUNCTION public.fn_resolve_approval_request(
  p_approval_id  uuid,
  p_decision     text,
  p_responded_by text DEFAULT NULL,
  p_comment      text DEFAULT NULL,
  p_responded_at timestamptz DEFAULT now()
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_status text;
BEGIN
  IF p_approval_id IS NULL THEN
    RAISE EXCEPTION 'approval_id is required' USING ERRCODE = 'check_violation';
  END IF;

  -- Normalise the decision to the request lifecycle status.
  v_status := CASE lower(COALESCE(p_decision, ''))
    WHEN 'approve'  THEN 'approved'
    WHEN 'approved' THEN 'approved'
    WHEN 'reject'   THEN 'rejected'
    WHEN 'rejected' THEN 'rejected'
    WHEN 'deny'     THEN 'rejected'
    WHEN 'denied'   THEN 'rejected'
    WHEN 'cancel'   THEN 'cancelled'
    WHEN 'cancelled' THEN 'cancelled'
    WHEN 'expire'   THEN 'expired'
    WHEN 'expired'  THEN 'expired'
    ELSE 'rejected' -- fail-closed: an unrecognised decision is not an approval
  END;

  UPDATE public.approval_requests
     SET decision     = p_decision,
         status       = v_status,
         responded_by = p_responded_by,
         responded_at = COALESCE(p_responded_at, now()),
         updated_at   = now()
   WHERE id = p_approval_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Approval request not found: %', p_approval_id USING ERRCODE = 'no_data_found';
  END IF;

  INSERT INTO public.audit_journal
    (user_id, action_type, action, entity_type, entity_id, area, severity, summary, details)
  VALUES
    (NULL, 'approval', 'APPROVAL_RESOLVED', 'approval_request', p_approval_id::text,
     'system', 'info',
     format('Approval request %s', v_status),
     jsonb_build_object('decision', p_decision, 'status', v_status, 'responded_by', p_responded_by));

  RETURN jsonb_build_object(
    'approval_id', p_approval_id,
    'status', v_status,
    'decision', p_decision
  );
END;
$function$;

COMMENT ON FUNCTION public.fn_resolve_approval_request(uuid, text, text, text, timestamptz) IS
  'Records a WF_APPROVAL_GATE decision onto approval_requests (fail-closed status normalisation).';

REVOKE ALL ON FUNCTION public.fn_resolve_approval_request(uuid, text, text, text, timestamptz) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fn_resolve_approval_request(uuid, text, text, text, timestamptz) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_resolve_embedding_model.sql
-- -----------------------------------------------------------------------------

-- Function: fn_resolve_embedding_model
-- Resolve a NAMED embedding model's backend + corpus space — the eval/sweep (brick 1)
-- needs to test a SPECIFIC candidate embedding model, not let the per-call CLOW ranker
-- pick one (that ranker is the model-as-index-constant anti-pattern; here we deliberately
-- name the model under test). Returns the provider transport (backend_kind/endpoint/auth)
-- so the query can be embedded with exactly that model, plus the corpus vector SPACE the
-- model targets (derived from its native dimension: 2560 ⇒ v2 halfvec, else v1 vector).
--
-- Availability still honours capability-availability: only an enabled provider serving an
-- is_embedding model that is available + not deprecated + healthy is returned. Empty result
-- ⇒ the named model has no live embedding backend (caller must fail loud, never silently
-- substitute a different model — that would compare a query against a corpus embedded by a
-- DIFFERENT model). Prefer the FK-linked provider row over the legacy provider=slug arm.

CREATE OR REPLACE FUNCTION public.fn_resolve_embedding_model(p_model_id text)
 RETURNS TABLE(
   model_id text,
   provider_slug text,
   backend_kind text,
   endpoint_url text,
   auth_env_var text,
   embedding_dimensions integer,
   rag_space text
 )
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;
  IF p_model_id IS NULL OR p_model_id = '' THEN
    RAISE EXCEPTION 'p_model_id is required';
  END IF;

  RETURN QUERY
  SELECT
    r.model_id,
    p.slug,
    p.backend_kind,
    p.endpoint_url,
    p.auth_env_var,
    r.embedding_dimensions,
    -- Prostor se určuje SHODOU rozměru se sloupcem, ne „všechno ostatní je v1".
    -- Dřív tu stálo `CASE WHEN dim = 2560 THEN 'v2' ELSE 'v1'`: nebyla to derivace,
    -- ale dvouhodnotová tabulka, která KAŽDÝ jiný rozměr mlčky prohlásila za v1.
    -- Model s 1024 tak dostal nálepku v1 a jeho vektor by šel do sloupce jiného
    -- rozměru — Postgres to odmítne až při zápisu, daleko od místa rozhodnutí,
    -- a u dotazu by se neshoda projevila jen jako nevysvětlitelně horší výsledky.
    -- NULL = „tenhle model do žádného zdejšího prostoru nepatří"; volající to musí
    -- ošetřit hlasitě, protože mlčky zvolený špatný prostor je horší než chyba.
    CASE r.embedding_dimensions
      WHEN 2560 THEN 'v2'
      WHEN 1024 THEN 'v1'
      ELSE NULL
    END AS rag_space
  FROM public.ai_model_registry r
  JOIN public.ai_provider_registry p
    ON (r.provider_registry_id = p.id OR r.provider = p.slug)
  WHERE r.model_id = p_model_id
    AND r.is_embedding
    AND r.is_available
    AND NOT r.is_deprecated
    AND p.is_enabled
    AND p.last_health_status IN ('healthy', 'unknown')
  ORDER BY (r.provider_registry_id = p.id) DESC  -- prefer the FK-linked provider row
  LIMIT 1;
END;
$function$
;

REVOKE ALL ON FUNCTION fn_resolve_embedding_model(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_resolve_embedding_model(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_resolve_embedding_model_for_space.sql
-- -----------------------------------------------------------------------------

-- Function: fn_resolve_embedding_model_for_space
-- Brick2-PIN: resolve the embedding model to embed a query IN a given corpus SPACE
-- ('v1' vector(1024) | 'v2' halfvec(2560)). The prod search path passes the context profile
-- slug; this function reads that context's embedding_model_pref (= the space the corpus was
-- indexed in) DB-side (honours RPC-only data access — the route never reads context_profiles
-- directly), then resolves which live model targets that space — so the query is embedded
-- with a model whose native dimension routes to the SAME column it will be cosine-compared
-- against (dim-routing: 2560 ⇒ v2, 1024 ⇒ v1, jiný rozměr ⇒ NULL — nepatří do zdejšího prostoru). When no profile slug is given (or it has no
-- pref) the explicit p_rag_space is used. Symmetric twin of fn_resolve_embedding_model,
-- which resolves a NAMED model; here we resolve a model FOR a space.
--
-- Availability honours capability-availability identically: only an enabled provider serving
-- an is_embedding + is_available + NOT is_deprecated model on a healthy/unknown provider is
-- returned. Empty result ⇒ no live embedding backend for that space (the caller MUST fail
-- loud / degrade to text-only — never silently embed with a different-space model, which
-- would compare a query against a corpus embedded by a model of the wrong dimension). The
-- FK-linked provider row is preferred over the legacy provider=slug arm.

CREATE OR REPLACE FUNCTION public.fn_resolve_embedding_model_for_space(p_rag_space text DEFAULT 'v1'::text, p_context_profile_slug text DEFAULT NULL::text)
 RETURNS TABLE(
   model_id text,
   provider_slug text,
   backend_kind text,
   endpoint_url text,
   auth_env_var text,
   embedding_dimensions integer,
   rag_space text
 )
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_space text := p_rag_space;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  -- Prefer the context profile's pinned embedding space (the corpus's index generation)
  -- when a slug is supplied; fall back to the explicit p_rag_space otherwise.
  IF p_context_profile_slug IS NOT NULL THEN
    SELECT cp.embedding_model_pref INTO v_space
    FROM public.context_profiles cp
    WHERE cp.slug = p_context_profile_slug;
    v_space := COALESCE(v_space, p_rag_space);
  END IF;

  IF v_space IS NULL OR v_space NOT IN ('v1', 'v2') THEN
    RAISE EXCEPTION 'resolved rag space must be one of v1, v2 (got %)', v_space;
  END IF;

  RETURN QUERY
  SELECT
    r.model_id,
    p.slug,
    p.backend_kind,
    p.endpoint_url,
    p.auth_env_var,
    r.embedding_dimensions,
    CASE r.embedding_dimensions WHEN 2560 THEN 'v2' WHEN 1024 THEN 'v1' ELSE NULL END AS rag_space
  FROM public.ai_model_registry r
  JOIN public.ai_provider_registry p
    ON (r.provider_registry_id = p.id OR r.provider = p.slug)
  WHERE r.is_embedding
    AND r.is_available
    AND NOT r.is_deprecated
    AND p.is_enabled
    AND p.last_health_status IN ('healthy', 'unknown')
    -- Dim-routing: the model's native dimension must map to the requested corpus space.
    AND (CASE r.embedding_dimensions WHEN 2560 THEN 'v2' WHEN 1024 THEN 'v1' ELSE NULL END) = v_space
  ORDER BY (r.provider_registry_id = p.id) DESC,  -- prefer the FK-linked provider row
           r.latest_eval_score DESC NULLS LAST     -- then the better-benchmarked model
  LIMIT 1;
END;
$function$
;

REVOKE ALL ON FUNCTION fn_resolve_embedding_model_for_space(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_resolve_embedding_model_for_space(text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_get_chunks_needing_v1.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_get_chunks_needing_v1
-- Popis: Dávka chunků BEZ vektoru ŽIVÉ identity v prostoru v1 — pro platformní
--        dopočet (POST /embeddings/v1-backfill).
--
-- ŽIVÁ IDENTITA = model, kterým se kódují dotazy (fn_resolve_embedding_model_for_space
-- ('v1')) + DEKLAROVANÝ pin vah (ai_model_registry.provider_metadata.declared
-- .weights_sha256, data instance). Vektor je živý, když nese to jméno A model_version
-- začíná `gguf:<pin>` (recept za středníkem může být jakýkoli: engine local-ingest
-- `embed_text_v1`, tento dopočet `chunk_text_v1`). Vše ostatní — chybějící vektor,
-- jiné jméno (MLX), totéž jméno z jiného runtime (sentence-transformers) — se dopočítá
-- a přepíše NA MÍSTĚ (insert_knowledge_embedding: ON CONFLICT (chunk_id, locale)).
--
-- Bez deklarovaného pinu NEVRACÍ NIC a hlásí chybu: identitu runtime platforma nezná
-- a „živé" by nešlo odlišit od cizího (fail-closed).
-- Pořadí: nejstarší položky první — dokumenty, které dnes spravuje ingest (engine
-- je kóduje sám, s receptem embed_text_v1), přijdou na řadu až nakonec.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_get_chunks_needing_v1(p_batch_size integer DEFAULT 20)
RETURNS TABLE (
  chunk_id           uuid,
  knowledge_item_id  uuid,
  chunk_text         text,
  contextual_prefix  text,
  locale             text,
  model_id           text,
  identita           text,
  max_tokens         integer
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_model text;
  v_pin   text;
  v_max   integer;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;
  SELECT r.model_id INTO v_model FROM public.fn_resolve_embedding_model_for_space('v1') r LIMIT 1;
  IF v_model IS NULL THEN
    RETURN;
  END IF;
  SELECT m.provider_metadata->'declared'->>'weights_sha256',
         nullif(m.provider_metadata->'declared'->>'max_tokens', '')::integer
    INTO v_pin, v_max
    FROM public.ai_model_registry m
   WHERE m.model_id = v_model AND m.is_embedding
   ORDER BY m.is_available DESC NULLS LAST
   LIMIT 1;
  IF v_pin IS NULL OR v_pin !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'živá identita embeddingu % neznámá: ai_model_registry.provider_metadata.declared.weights_sha256 chybí', v_model
      USING ERRCODE = '22023';
  END IF;
  IF v_max IS NULL OR v_max < 1 THEN
    RAISE EXCEPTION 'embedding % nemá declared.max_tokens — bez stropu nelze vyloučit tichý ořez', v_model
      USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  SELECT c.chunk_id, c.knowledge_item_id, c.chunk_text, c.contextual_prefix, c.locale,
         c.model_id, c.identita, c.max_tokens
    FROM public.fn_chunks_bez_zive_identity(v_model, 'gguf:' || v_pin, v_max, p_batch_size) c;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_get_chunks_needing_v1(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_get_chunks_needing_v1(integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_resolve_runtime.sql
-- -----------------------------------------------------------------------------

-- Function: fn_resolve_runtime
-- Derives the EXECUTOR runtime (direct_llm / openclaw / hermes / cli / workflow)
-- for a clow from ai_runtime_registry — capability-availability, NOT a hardcoded
-- 'direct_llm' default (fn_admit_clow:48 used COALESCE(clow->>'runtime','direct_llm'),
-- which both blind-defaulted AND skipped any availability check).
--
-- Symmetric to aisha_resolve_clow_backend (the MODEL axis): the clow's needs
-- (needs_write / needs_internet / needs_tools) are matched against each runtime's
-- OWN declared capabilities (can_write / needs_network / supports_tools); only
-- enabled + healthy runtimes are candidates. An explicitly-stated clow.runtime is
-- honored ONLY if it is itself available+capable. If NO capable+available runtime
-- exists, returns {resolved:false} so the caller FAILS LOUD — never a blind default
-- (a runtime hardcoded/defaulted while its adapter is down masks non-functionality).
--
-- Ranking is derived, not a roster: prefer direct_llm (the universal LLM executor)
-- when it satisfies, then the least side-effecting + healthiest. Adding a runtime
-- (hermes, a cli) makes it derivable purely by its own registry row.

CREATE OR REPLACE FUNCTION public.fn_resolve_runtime(p_clow jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_needs_net   boolean := COALESCE((p_clow->>'needs_internet')::boolean, false);
  v_needs_write boolean := COALESCE((p_clow->>'needs_write')::boolean, false);
  v_needs_tools boolean := COALESCE((p_clow->>'needs_tools')::boolean, false);
  v_stated      text    := NULLIF(p_clow->>'runtime', '');
  v_cli_slug    text    := NULLIF(p_clow->>'cli_slug', '');
  v_kind        text;
  v_slug        text;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT r.runtime_kind, r.slug
  INTO v_kind, v_slug
  FROM public.ai_runtime_registry r
  WHERE r.is_enabled
    -- Exclude only a runtime the health probe (WF_RUNTIME_HEALTH_PROBE →
    -- record_runtime_health_result) has CONFIRMED 'down'. 'unknown' (never probed)
    -- and 'degraded' (reachable but slow/erroring) stay usable — degraded is
    -- deprioritized below healthy by the ORDER BY, not excluded.
    AND r.adapter_health <> 'down'
    AND (NOT v_needs_write OR r.can_write)
    AND (NOT v_needs_net   OR r.needs_network)
    AND (NOT v_needs_tools OR r.supports_tools)
    -- Only IN-PROCESS executors are auto-derivable: filter on the runtime's OWN
    -- self-declared is_in_process_executor flag — NOT a hardcoded NOT IN list of kinds.
    -- direct_llm/openclaw/hermes/workbench/cli declare true; out-of-band surfaces
    -- (human = manual inbox, workflow = n8n hand-off) declare false → never derived as an
    -- executeViaRuntime target (which would THROW "No RuntimeAdapter"). Adding/retiring a
    -- derivable runtime is now a per-row data change, not an edit here — the same
    -- capability-availability derivation as is_enabled/can_write/etc.
    -- cli is additionally derivable only with an explicit slug.
    AND r.is_in_process_executor
    AND (r.runtime_kind <> 'cli' OR (v_cli_slug IS NOT NULL AND r.slug = 'cli:' || v_cli_slug))
    -- An explicitly-stated runtime narrows the candidate set (honored iff capable+available).
    AND (v_stated IS NULL OR r.runtime_kind = v_stated)
  ORDER BY
    (r.adapter_health = 'healthy') DESC,         -- prefer a probe-confirmed-healthy runtime
    (r.runtime_kind = 'direct_llm') DESC,        -- then the universal LLM executor
    (r.side_effect_class = 'read_only') DESC,    -- then the least side-effecting
    r.consecutive_failure_count ASC,             -- then the healthiest
    r.runtime_kind ASC
  LIMIT 1;

  IF v_kind IS NULL THEN
    RETURN jsonb_build_object(
      'resolved', false,
      'reason', format(
        'no enabled+healthy runtime satisfies the clow (needs_write=%s, needs_internet=%s, needs_tools=%s, stated=%s)',
        v_needs_write, v_needs_net, v_needs_tools, COALESCE(v_stated, '(derive)')
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'resolved', true,
    'runtime',  v_kind,
    'slug',     v_slug,
    'reason',   format('runtime=%s derived (capability+availability match)', v_kind)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_resolve_runtime(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_resolve_runtime(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_resolve_runtime(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_risk_level_ordinal.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_risk_level_ordinal  (E0 risk-severity rank transform)
-- Purpose: Ordinal map for risk severity (low < medium < high < critical → 0..3).
--          A pure value transform — one rank per level, NOT a list of permitted
--          names. Lets fn_admit_clow compare a COMPUTED clow risk level against a
--          resolved ai_risk_policies threshold using a plain numeric >=.
--          Unknown severity → 1 (medium), the conservative default.
-- Security: IMMUTABLE pure function. authenticated + service_role.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_risk_level_ordinal(p_level text)
RETURNS int
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT CASE lower(COALESCE(p_level, ''))
    WHEN 'low'      THEN 0
    WHEN 'medium'   THEN 1
    WHEN 'high'     THEN 2
    WHEN 'critical' THEN 3
    ELSE 1  -- unknown severity → treat as medium (conservative)
  END;
$$;

COMMENT ON FUNCTION public.fn_risk_level_ordinal(text) IS
  'Pure rank transform for risk severity (low<medium<high<critical → 0..3; unknown→1). '
  'Lets fn_admit_clow compare a computed clow risk level against a policy threshold. '
  'IMMUTABLE; a value map, not an allow-list.';

REVOKE ALL ON FUNCTION public.fn_risk_level_ordinal(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_risk_level_ordinal(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_risk_level_ordinal(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_runtime_available.sql
-- -----------------------------------------------------------------------------

-- Function: fn_runtime_available
-- Capability-availability predicate for the runtime axis (E0 — AISHA
-- Orchestration Authority). Given a runtime kind (direct_llm | openclaw |
-- hermes | workflow | human | cli) — and, for kind='cli', a specific CLI slug —
-- answers the single question AISHA asks before dispatching a clow:
--   "Can this platform actually run that runtime right now?"
--
-- AVAILABILITY IS DERIVED, NOT ALLOW-LISTED. A runtime is usable IFF its OWN
-- ai_runtime_registry row is registered + enabled + has a live adapter:
--     row.is_enabled AND row.adapter_health IN ('healthy','unknown')
-- A new runtime (hermes, a new CLI) becomes available simply by self-registering
-- its row + adapter — there is NOTHING to maintain here. This mirrors the
-- provider resolver in aisha_resolve_clow_backend, which filters providers by
--     is_enabled AND last_health_status IN ('healthy','unknown')
-- — capability-availability, not a maintained list of permitted names. The only
-- IN(...) set below is the health-status predicate (a state check), identical to
-- that resolver filter; it is NOT a list of permitted entities.
--
-- DERIVED CHAINING for direct_llm: a 'direct_llm' runtime can only do work if at
-- least one PROVIDER is itself available (same resolver filter), so for that kind
-- we additionally require EXISTS such a provider. Other runtimes
-- (openclaw/hermes/workflow/human/cli) gate solely on their own registry row.
--
-- Runtime slug convention (matches ai_runtime_registry.slug):
--   - kind != 'cli'  → slug = p_runtime_kind            (e.g. 'openclaw')
--   - kind  = 'cli'  → slug = 'cli:' || p_cli_slug      (e.g. 'cli:claude-cli')
--
-- Returns jsonb { available boolean, reason text, row jsonb|null } so callers
-- (orchestrationBridge / admission composer) get both the verdict and the
-- evidence row in one STABLE read.

CREATE OR REPLACE FUNCTION public.fn_runtime_available(
  p_runtime_kind text,
  p_cli_slug text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  -- The registry slug this kind resolves to (single value transform — not a list).
  v_slug    text;
  v_row     public.ai_runtime_registry%ROWTYPE;
  v_found   boolean := false;
  v_provider_ok boolean;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_runtime_kind IS NULL OR p_runtime_kind = '' THEN
    RAISE EXCEPTION 'p_runtime_kind is required';
  END IF;

  -- Derive the registry slug. For 'cli' the specific tool lives in p_cli_slug;
  -- a single composed value, never a maintained set of permitted CLIs.
  IF p_runtime_kind = 'cli' THEN
    IF p_cli_slug IS NULL OR p_cli_slug = '' THEN
      RETURN jsonb_build_object(
        'available', false,
        'reason', 'runtime kind=cli requires a cli_slug',
        'row', NULL
      );
    END IF;
    v_slug := 'cli:' || p_cli_slug;
  ELSE
    v_slug := p_runtime_kind;
  END IF;

  -- Look up the entity's OWN registry row. Not registered → not available.
  SELECT * INTO v_row
  FROM public.ai_runtime_registry rr
  WHERE rr.slug = v_slug;
  v_found := FOUND;

  IF NOT v_found THEN
    RETURN jsonb_build_object(
      'available', false,
      'reason', format('runtime %s is not registered (no ai_runtime_registry row)', v_slug),
      'row', NULL
    );
  END IF;

  -- The entity governs itself: enabled + live adapter. Same health predicate the
  -- provider resolver uses ('healthy','unknown'); a state check, not an allow-list.
  IF NOT v_row.is_enabled THEN
    RETURN jsonb_build_object(
      'available', false,
      'reason', format('runtime %s is registered but disabled (is_enabled=false)', v_slug),
      'row', to_jsonb(v_row)
    );
  END IF;

  IF v_row.adapter_health NOT IN ('healthy', 'unknown') THEN
    RETURN jsonb_build_object(
      'available', false,
      'reason', format('runtime %s adapter is unhealthy (adapter_health=%s)', v_slug, v_row.adapter_health),
      'row', to_jsonb(v_row)
    );
  END IF;

  -- DERIVED chaining: a direct_llm runtime needs at least one available provider.
  -- Mirror the resolver filter exactly (is_enabled AND last_health_status IN
  -- ('healthy','unknown')) — capability-availability, not a provider allow-list.
  IF p_runtime_kind = 'direct_llm' THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.ai_provider_registry p
      WHERE p.is_enabled
        AND p.last_health_status IN ('healthy', 'unknown')
    ) INTO v_provider_ok;

    IF NOT v_provider_ok THEN
      RETURN jsonb_build_object(
        'available', false,
        'reason', 'runtime direct_llm has no available provider (none enabled + healthy in ai_provider_registry)',
        'row', to_jsonb(v_row)
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'available', true,
    'reason', format('runtime %s available (enabled, adapter_health=%s)', v_slug, v_row.adapter_health),
    'row', to_jsonb(v_row)
  );
END;
$$;

COMMENT ON FUNCTION public.fn_runtime_available(text, text) IS
  'Capability-availability predicate for the runtime axis. Returns '
  '{available, reason, row}: available IFF the matching ai_runtime_registry row '
  '(slug=p_runtime_kind, or cli:p_cli_slug when kind=cli) is_enabled AND '
  'adapter_health IN (healthy,unknown); for direct_llm ALSO requires an available '
  'provider (mirrors the aisha_resolve_clow_backend resolver filter). Availability '
  'is DERIVED from the registry — no allow-list. STABLE; SECURITY DEFINER.';

REVOKE ALL ON FUNCTION public.fn_runtime_available(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_runtime_available(text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_runtime_available(text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_admit_clow.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_admit_clow  (E0 Admission Layer composer)
-- Purpose: THE pre-resolver admission gate. Runs BEFORE aisha_resolve_clow_backend
--          and composes ONE verdict over FOUR DERIVED axes — capability-availability,
--          NOT membership allow-lists (owner Q4: "AISHA = systémová/infrastrukturní
--          vrstva, která podle dostupných možností ví, zda a jak umí naložit s úkolem").
--
--            spend       — fn_authorize_task_spend (REUSE; policy thresholds, not a list)
--            runtime     — fn_runtime_available (REUSE; availability DERIVED from the
--                          ai_runtime_registry row: registered + enabled + live adapter)
--            capability  — the chosen runtime's OWN declared capabilities are matched
--                          against the clow's needs (needs_write→can_write,
--                          needs_internet→needs_network, needs_tools→supports_tools,
--                          + provider supports_tool_use for tools under direct_llm).
--                          DERIVED from each entity's self-declared flags, not a list.
--            risk        — fn_compute_clow_risk(clow, runtime_row) COMPUTED severity vs
--                          a resolved ai_risk_policies threshold row (policy, not a list).
--
--          Combine: deny dominates, then ask, else allow.
--            deny → caller blocks the run (status='blocked', awaiting='admission_denied');
--            ask  → caller blocks with awaiting=<axis>_approval (Mission Control).
--          `awaiting` is taken from the FIRST axis that asks (spend → runtime n/a →
--          capability → risk), preserving a stable, explainable reason.
--
-- DESIGN — NO MAINTAINED ALLOW-LISTS. There is no governance_flags lookup, no
-- @> array-membership test, and no _admit_capability_axis flag helper. Adding a
-- new runtime (hermes, a CLI) or provider makes it admissible purely by its own
-- registry row (is_enabled + adapter/health) and its own capability columns — the
-- entity governs itself; nothing here is edited when capabilities are added. This
-- mirrors the provider resolver, which filters by is_enabled AND healthy.
--
-- Security: SECURITY DEFINER, read-only (STABLE). authenticated + service_role.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_admit_clow(
  p_clow    jsonb,
  p_context jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  -- ── clow / context inputs ──────────────────────────────────────────────────
  v_story_id     uuid    := NULLIF(p_context->>'story_id', '')::uuid;
  v_runtime      text    := COALESCE(p_clow->>'runtime', 'direct_llm');
  v_cli_slug     text    := NULLIF(p_clow->>'cli_slug', '');
  v_task_kind    text    := COALESCE(p_clow->>'task_kind', 'chat');
  v_estimate     numeric := NULLIF(p_context->>'estimate', '')::numeric;
  v_needs_net    boolean := COALESCE((p_clow->>'needs_internet')::boolean, false);
  v_needs_write  boolean := COALESCE((p_clow->>'needs_write')::boolean, false);
  v_needs_tools  boolean := COALESCE((p_clow->>'needs_tools')::boolean, false);

  -- ── verdict accumulation ───────────────────────────────────────────────────
  v_axis         jsonb   := '{}'::jsonb;
  v_decisions    text[]  := ARRAY[]::text[];
  v_final        text;
  v_awaiting     text    := NULL;

  -- ── spend axis ─────────────────────────────────────────────────────────────
  v_spend        jsonb;
  v_spend_dec    text;

  -- ── runtime-availability axis ──────────────────────────────────────────────
  v_runtime_av   jsonb;
  v_runtime_row  jsonb;
  v_runtime_dec  text;

  -- ── capability-match axis (DERIVED from the chosen runtime/provider) ────────
  v_can_write    boolean;
  v_can_net      boolean;
  v_can_tools    boolean;
  v_provider_tools boolean;
  v_cap_dec      text    := 'allow';
  v_cap          jsonb   := '{}'::jsonb;

  -- ── risk axis (COMPUTED severity vs resolved policy thresholds) ─────────────
  v_risk_level   text;
  v_risk_ord     int;
  v_ask_at       text;
  v_deny_at      text;
  v_ask_ord      int;
  v_deny_ord     int;
  v_risk_src     text;
  v_risk_dec     text;

  -- ── autonomy axis (the runtime's DECLARED autonomy_class) ───────────────────
  v_autonomy     text;
  v_autonomy_dec text;
BEGIN
  IF auth.uid() IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_clow IS NULL OR (p_clow->>'purpose') IS NULL THEN
    RAISE EXCEPTION 'fn_admit_clow: p_clow.purpose required' USING ERRCODE = '22023';
  END IF;

  -- ══ axis 1: spend (REUSE — policy thresholds, NOT a list) ══════════════════
  v_spend := public.fn_authorize_task_spend(v_task_kind, v_story_id, v_estimate);
  v_spend_dec := v_spend->>'decision';
  v_axis := v_axis || jsonb_build_object('spend',
    jsonb_build_object(
      'decision', v_spend_dec,
      'reason',   v_spend->>'reason',
      'detail',   v_spend
    ));
  v_decisions := array_append(v_decisions, v_spend_dec);
  IF v_spend_dec = 'ask' THEN
    v_awaiting := COALESCE(v_awaiting, 'spend_approval');
  END IF;

  -- ══ axis 2: runtime-availability (REUSE — DERIVED from the registry row) ════
  -- Available IFF the runtime's OWN ai_runtime_registry row is registered +
  -- enabled + has a live adapter. Not available → deny (runtime_unavailable).
  v_runtime_av  := public.fn_runtime_available(v_runtime, v_cli_slug);
  v_runtime_row := v_runtime_av->'row';
  v_runtime_dec := CASE WHEN (v_runtime_av->>'available')::boolean THEN 'allow' ELSE 'deny' END;
  v_axis := v_axis || jsonb_build_object('runtime',
    jsonb_build_object(
      'decision',    v_runtime_dec,
      'reason_code', CASE WHEN v_runtime_dec = 'deny' THEN 'runtime_unavailable' ELSE 'runtime_available' END,
      'requested',   v_runtime,
      'cli_slug',    v_cli_slug,
      'reason',      v_runtime_av->>'reason'
    ));
  v_decisions := array_append(v_decisions, v_runtime_dec);

  -- ══ axis 3: capability-match (DERIVED — runtime/provider self-declared) ════
  -- Each need is matched against the chosen runtime's OWN capability columns
  -- (loaded above). A need the runtime cannot satisfy → ask (a human can grant /
  -- redirect), never a silent allow. No flag-set, no list — the entity declares
  -- what it can do.
  -- Defaults are fail-closed: an absent capability column reads as false, so a
  -- need without an explicit capability asks rather than silently allowing.
  v_can_write := COALESCE((v_runtime_row->>'can_write')::boolean, false);
  v_can_net   := COALESCE((v_runtime_row->>'needs_network')::boolean, false);
  v_can_tools := COALESCE((v_runtime_row->>'supports_tools')::boolean, false);

  -- For direct_llm tool use, the resolved provider must itself support tool use
  -- (supports_tool_use already exists per ai_provider_registry). DERIVED chaining,
  -- mirroring fn_runtime_available's provider check — not a provider allow-list.
  IF v_runtime = 'direct_llm' AND v_needs_tools THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.ai_provider_registry p
      WHERE p.is_enabled
        AND p.last_health_status IN ('healthy', 'unknown')
        AND p.supports_tool_use
    ) INTO v_provider_tools;
    v_can_tools := v_can_tools AND COALESCE(v_provider_tools, false);
  END IF;

  -- write
  v_cap := v_cap || jsonb_build_object('write',
    jsonb_build_object(
      'needed',    v_needs_write,
      'satisfied', (NOT v_needs_write) OR v_can_write,
      'decision',  CASE WHEN NOT v_needs_write OR v_can_write THEN 'allow' ELSE 'ask' END));
  IF v_needs_write AND NOT v_can_write THEN
    v_cap_dec  := 'ask';
    v_awaiting := COALESCE(v_awaiting, 'capability_write_requires_approval');
  END IF;

  -- internet
  v_cap := v_cap || jsonb_build_object('internet',
    jsonb_build_object(
      'needed',    v_needs_net,
      'satisfied', (NOT v_needs_net) OR v_can_net,
      'decision',  CASE WHEN NOT v_needs_net OR v_can_net THEN 'allow' ELSE 'ask' END));
  IF v_needs_net AND NOT v_can_net THEN
    v_cap_dec  := 'ask';
    v_awaiting := COALESCE(v_awaiting, 'capability_internet_requires_approval');
  END IF;

  -- tools
  v_cap := v_cap || jsonb_build_object('tools',
    jsonb_build_object(
      'needed',    v_needs_tools,
      'satisfied', (NOT v_needs_tools) OR v_can_tools,
      'decision',  CASE WHEN NOT v_needs_tools OR v_can_tools THEN 'allow' ELSE 'ask' END));
  IF v_needs_tools AND NOT v_can_tools THEN
    v_cap_dec  := 'ask';
    v_awaiting := COALESCE(v_awaiting, 'capability_tools_requires_approval');
  END IF;

  v_axis := v_axis || jsonb_build_object('capability',
    (v_cap || jsonb_build_object('decision', v_cap_dec)));
  v_decisions := array_append(v_decisions, v_cap_dec);

  -- ══ axis 4: risk (COMPUTED severity vs resolved policy thresholds) ═════════
  -- Risk is computed from the clow itself (criticality, side-effect class) against
  -- the chosen runtime; the verdict is a policy comparison, not list membership.
  v_risk_level := (public.fn_compute_clow_risk(p_clow, v_runtime_row))->>'risk_level';
  v_risk_ord   := public.fn_risk_level_ordinal(v_risk_level);

  -- Resolve the governing ai_risk_policies row — most specific active row wins
  -- (story over global), exactly like ai_spend_policies. No row → conservative
  -- built-in band: ask at 'high', deny at 'critical'. A single threshold value
  -- per dimension is a variable, NOT a maintained list of permitted names.
  SELECT rp.ask_above, rp.deny_above,
         rp.scope_type || COALESCE(':' || NULLIF(rp.scope_id::text, ''), ':global')
    INTO v_ask_at, v_deny_at, v_risk_src
  FROM public.ai_risk_policies rp
  WHERE rp.is_active
    AND (
      (rp.scope_type = 'story'  AND rp.scope_id = v_story_id)
      OR rp.scope_type = 'global'
    )
  ORDER BY
    CASE WHEN rp.scope_type = 'story' THEN 0 ELSE 1 END
  LIMIT 1;

  IF v_ask_at IS NULL THEN
    v_ask_at   := 'medium';
    v_deny_at  := 'critical';
    v_risk_src := COALESCE(v_risk_src, 'builtin_default');
  END IF;

  v_ask_ord  := public.fn_risk_level_ordinal(v_ask_at);
  v_deny_ord := public.fn_risk_level_ordinal(v_deny_at);

  v_risk_dec := CASE
    WHEN v_deny_ord IS NOT NULL AND v_risk_ord > v_deny_ord THEN 'deny'
    WHEN v_ask_ord  IS NOT NULL AND v_risk_ord > v_ask_ord  THEN 'ask'
    ELSE 'allow'
  END;

  v_axis := v_axis || jsonb_build_object('risk',
    jsonb_build_object(
      'decision',     v_risk_dec,
      'level',        v_risk_level,
      'ask_at',       v_ask_at,
      'deny_at',      v_deny_at,
      'policy_source', v_risk_src
    ));
  v_decisions := array_append(v_decisions, v_risk_dec);
  IF v_risk_dec = 'ask' THEN
    v_awaiting := COALESCE(v_awaiting, 'risk_approval');
  END IF;

  -- ══ axis 5: autonomy (the runtime's DECLARED autonomy_class) ═══════════════
  -- ai_runtime_registry.autonomy_class carries ENFORCEMENT semantics that no
  -- decision function previously read: 'supervised' = "every action gated by human
  -- review". Honour that contract as its own axis — a supervised runtime must never
  -- be admitted straight to 'allow'; it asks (human review) regardless of the
  -- computed risk band. 'semi'/'autonomous' add nothing here (their gating IS the
  -- risk band). deny from another axis still dominates via the combine below.
  -- Fail-closed: a missing autonomy_class (never expected — NOT NULL DEFAULT
  -- 'supervised' in the registry) is treated as the most-gated value.
  v_autonomy     := COALESCE(v_runtime_row->>'autonomy_class', 'supervised');
  v_autonomy_dec := CASE WHEN v_autonomy = 'supervised' THEN 'ask' ELSE 'allow' END;
  v_axis := v_axis || jsonb_build_object('autonomy',
    jsonb_build_object('decision', v_autonomy_dec, 'autonomy_class', v_autonomy));
  v_decisions := array_append(v_decisions, v_autonomy_dec);
  IF v_autonomy_dec = 'ask' THEN
    v_awaiting := COALESCE(v_awaiting, 'supervision_approval');
  END IF;

  -- ══ combine: deny dominates, then ask, else allow ═════════════════════════
  IF 'deny' = ANY(v_decisions) THEN
    v_final    := 'deny';
    v_awaiting := 'admission_denied';
  ELSIF 'ask' = ANY(v_decisions) THEN
    v_final    := 'ask';
  ELSE
    v_final    := 'allow';
  END IF;

  RETURN jsonb_build_object(
    'decision', v_final,
    'axis_results', v_axis,
    'reason_code', CASE
      WHEN v_final = 'deny' THEN 'admission_denied'
      WHEN v_final = 'ask'  THEN COALESCE(v_awaiting, 'approval_required')
      ELSE 'admitted' END,
    'awaiting', v_awaiting
  );
END;
$$;

-- fn_risk_level_ordinal (the low<medium<high<critical → 0..3 rank transform used
-- by the risk axis above) lives in its own SoT file: functions/fn_risk_level_ordinal.sql
-- (one DB object per file). fn_admit_clow calls it as public.fn_risk_level_ordinal(...).

COMMENT ON FUNCTION public.fn_admit_clow(jsonb, jsonb) IS
  'E0 Admission Layer composer (pre-resolver). Composes FOUR DERIVED axes — '
  'spend (fn_authorize_task_spend) + runtime-availability (fn_runtime_available) + '
  'capability-match (runtime/provider self-declared can_write/needs_network/'
  'supports_tools, + provider supports_tool_use for direct_llm tools) + risk '
  '(fn_compute_clow_risk vs resolved ai_risk_policies threshold) — into one verdict '
  '{decision: allow|ask|deny, axis_results, reason_code, awaiting}. Capability-'
  'availability, NOT allow-lists: every entity governs itself via its own registry '
  'row + capability columns. deny>ask>allow; awaiting from first asking axis; '
  'deny→admission_denied. STABLE; SECURITY DEFINER.';

REVOKE ALL ON FUNCTION public.fn_admit_clow(jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_admit_clow(jsonb, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_admit_clow(jsonb, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_search_learnings.sql
-- -----------------------------------------------------------------------------

-- Function: fn_search_learnings
-- Hippocampus learning: retrieve relevant learnings via vector similarity.
-- Scoped by story_id (or global when NULL). Increments access_count for
-- promotion threshold tracking. Analogous to fn_search_personality_context but
-- targets memory_type='learning'.

CREATE OR REPLACE FUNCTION public.fn_search_learnings(
  p_query_embedding vector(1024),
  p_story_id uuid DEFAULT NULL,
  p_agent_slug text DEFAULT 'aisha',
  p_limit integer DEFAULT 5,
  p_min_importance integer DEFAULT 3
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
  v_results jsonb;
  v_ids uuid[];
BEGIN
  -- Auth: authenticated user or service_role
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_query_embedding IS NULL THEN
    RAISE EXCEPTION 'p_query_embedding is required';
  END IF;

  -- Top-K retrieval by cosine + importance compound score
  SELECT
    COALESCE(jsonb_agg(sub.obj ORDER BY sub.score DESC), '[]'::jsonb),
    array_agg(sub.id ORDER BY sub.score DESC)
  INTO v_results, v_ids
  FROM (
    SELECT
      am.id,
      jsonb_build_object(
        'memory_id', am.id,
        'source_run_id', am.source_run_id,
        'content', am.content,
        'importance', am.importance,
        'created_at', am.created_at,
        'score', round((
          (1 - (am.embedding <=> p_query_embedding)) * 0.6
          + (am.importance / 10.0) * 0.4
        )::numeric, 4)
      ) AS obj,
      (1 - (am.embedding <=> p_query_embedding)) * 0.6
        + (am.importance / 10.0) * 0.4 AS score
    FROM agent_memories am
    LEFT JOIN ai_runs r ON r.id = am.source_run_id
    WHERE am.memory_type = 'learning'
      AND am.agent_slug = p_agent_slug
      AND am.embedding IS NOT NULL
      AND am.importance >= p_min_importance
      AND (am.expires_at IS NULL OR am.expires_at > now())
      AND (
        p_story_id IS NULL
        OR r.story_id = p_story_id
        OR r.story_id IS NULL  -- global learnings always included
      )
    ORDER BY score DESC
    LIMIT p_limit
  ) sub;

  -- Increment access_count for promotion threshold tracking
  -- (access_count lives in updated_at touch; we capture via audit_journal too)
  IF v_ids IS NOT NULL AND array_length(v_ids, 1) > 0 THEN
    UPDATE agent_memories
    SET updated_at = now()
    WHERE id = ANY(v_ids);

    -- Audit retrieval for promotion engine consumption
    INSERT INTO audit_journal (user_id, action, metadata)
    VALUES (
      auth.uid(),
      'hippocampus.learnings_retrieved',
      jsonb_build_object(
        'memory_ids', to_jsonb(v_ids),
        'story_id', p_story_id,
        'agent_slug', p_agent_slug,
        'limit', p_limit
      )
    );
  END IF;

  RETURN COALESCE(v_results, '[]'::jsonb);
END;
$$;

COMMENT ON FUNCTION public.fn_search_learnings(vector, uuid, text, integer, integer) IS
  'Hippocampus learning: vector search over agent_memories where memory_type=''learning''. '
  'Scoped by story_id (NULL = global learnings only). Score = 0.6*cosine + 0.4*importance. '
  'Touches updated_at for promotion access_count tracking; audits retrieval to audit_journal.';

REVOKE ALL ON FUNCTION public.fn_search_learnings(vector, uuid, text, integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_search_learnings(vector, uuid, text, integer, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_search_learnings(vector, uuid, text, integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_submit_message_feedback_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_submit_message_feedback_audited
-- Step:  Step 2 of retrieval optimization plan 2026
-- Used by: src/hooks/useSubmitMessageFeedback.ts → FeedbackButtons.tsx
-- Audit:  INSERT INTO audit_journal (action='chat.message_feedback', metadata)
-- Migration: aisha/db/migrations/20260518220000_chat_message_eval_link.sql
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_submit_message_feedback_audited(
  p_ai_run_id  uuid,
  p_metadata   jsonb,
  p_rating     smallint,
  p_reason     text
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_fb_id     uuid;
  v_audit_id  uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authenticated user required' USING ERRCODE = '22023';
  END IF;
  IF p_ai_run_id IS NULL THEN
    RAISE EXCEPTION 'p_ai_run_id is required';
  END IF;
  IF p_rating IS NULL OR p_rating NOT IN (-1, 0, 1) THEN
    RAISE EXCEPTION 'p_rating must be -1, 0, or 1';
  END IF;

  INSERT INTO public.message_user_feedback (ai_run_id, user_id, rating, reason, metadata)
  VALUES (p_ai_run_id, auth.uid(), p_rating, p_reason, COALESCE(p_metadata, '{}'::jsonb))
  ON CONFLICT (ai_run_id, user_id) DO UPDATE
    SET rating = EXCLUDED.rating,
        reason = EXCLUDED.reason,
        metadata = EXCLUDED.metadata
  RETURNING id INTO v_fb_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'chat.message_feedback',
    jsonb_build_object(
      'feedback_id', v_fb_id,
      'ai_run_id', p_ai_run_id,
      'rating', p_rating,
      'has_reason', p_reason IS NOT NULL AND length(p_reason) > 0
    )
  )
  RETURNING id INTO v_audit_id;

  UPDATE public.message_user_feedback
     SET audit_journal_id = v_audit_id
   WHERE id = v_fb_id;

  RETURN v_fb_id;
END;
$$;

