-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fulfill_reward_claim.sql
-- -----------------------------------------------------------------------------

-- Function: public.fulfill_reward_claim
-- Arguments: p_claim_id uuid, p_tx_hash text
-- Description: service_role marks a reward claim fulfilled after the on-chain
--   MsgSend broadcast succeeds (svc-blockchain POST /claim-reward). Idempotent-safe:
--   returns success:false when the claim id is unknown.
-- Security: SECURITY DEFINER, service_role only

CREATE OR REPLACE FUNCTION public.fulfill_reward_claim(p_claim_id uuid, p_tx_hash text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_found uuid;
BEGIN
  UPDATE reward_claims
  SET status = 'fulfilled',
      tx_hash = p_tx_hash,
      fulfilled_at = now(),
      updated_at = now()
  WHERE id = p_claim_id
  RETURNING id INTO v_found;

  IF v_found IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'claim_not_found');
  END IF;

  RETURN jsonb_build_object('success', true, 'claim_id', v_found);
END;
$$;

REVOKE ALL ON FUNCTION public.fulfill_reward_claim(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fulfill_reward_claim(uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/generate_next_invoice_number.sql
-- -----------------------------------------------------------------------------

-- generate_next_invoice_number: Generate next sequential invoice number
-- Uses invoice_sequences table for atomic counter with year+prefix partitioning
-- Format: PREFIX-YYYY-NNNNN (e.g., FAK-2026-00001)
--
-- Arguments:
--   p_prefix text (default 'FAK') — invoice number prefix
--
-- Returns: text — generated invoice number
-- Security: SECURITY DEFINER (accesses invoice_sequences table)
CREATE OR REPLACE FUNCTION public.generate_next_invoice_number(
  p_prefix text DEFAULT 'FAK'::text
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_year int := EXTRACT(YEAR FROM CURRENT_DATE)::int;
  v_next_val int;
BEGIN
  INSERT INTO public.invoice_sequences (prefix, year, current_value)
  VALUES (p_prefix, v_year, 1)
  ON CONFLICT (prefix, year)
  DO UPDATE SET
    current_value = invoice_sequences.current_value + 1,
    updated_at = now()
  RETURNING current_value INTO v_next_val;

  RETURN p_prefix || '-' || v_year::text || '-' || lpad(v_next_val::text, 5, '0');
END;
$function$;

REVOKE ALL ON FUNCTION public.generate_next_invoice_number(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.generate_next_invoice_number(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.generate_next_invoice_number(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/generate_variable_symbol.sql
-- -----------------------------------------------------------------------------

-- generate_variable_symbol: Generate unique variable symbol for bank transfer
-- Uses variable_symbol_sequences table for atomic counter with year partitioning
-- Format: YYMM + 6-digit sequence (e.g., 2602000001 for Feb 2026, first order)
-- Idempotent: returns existing VS if order already has one
--
-- Arguments:
--   p_order_id uuid — order to generate/get variable symbol for
--
-- Returns: text — variable symbol (10 digits)
-- Security: SECURITY DEFINER (accesses orders + variable_symbol_sequences)
CREATE OR REPLACE FUNCTION public.generate_variable_symbol(
  p_order_id uuid
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_year int := EXTRACT(YEAR FROM CURRENT_DATE)::int;
  v_next_val int;
  v_prefix text;
  v_vs text;
BEGIN
  -- Check if order already has a variable symbol
  SELECT variable_symbol INTO v_vs
  FROM public.orders WHERE id = p_order_id;

  IF v_vs IS NOT NULL THEN
    RETURN v_vs;
  END IF;

  -- Get next sequence value
  INSERT INTO public.variable_symbol_sequences (year, current_value)
  VALUES (v_year, 1)
  ON CONFLICT (year)
  DO UPDATE SET current_value = variable_symbol_sequences.current_value + 1
  RETURNING current_value INTO v_next_val;

  -- Build VS: YYMM prefix + 6-digit sequence (max 10 digits total)
  v_prefix := to_char(CURRENT_DATE, 'YYMM');
  v_vs := v_prefix || lpad(v_next_val::text, 6, '0');

  -- Store on order
  UPDATE public.orders
  SET variable_symbol = v_vs, updated_at = now()
  WHERE id = p_order_id;

  RETURN v_vs;
END;
$function$;

REVOKE ALL ON FUNCTION public.generate_variable_symbol(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.generate_variable_symbol(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.generate_variable_symbol(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_active_consultation_session.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- get_active_consultation_session
-- =============================================================================
-- Active/pending/ringing session for current user with room name.
-- =============================================================================

CREATE OR REPLACE FUNCTION public.get_active_consultation_session()
RETURNS TABLE(
  id uuid,
  voice_room_id uuid,
  booking_id uuid,
  caller_id uuid,
  callee_id uuid,
  status text,
  started_at timestamptz,
  ended_at timestamptz,
  duration_seconds integer,
  recording_consent boolean,
  recording_consent_at timestamptz,
  created_at timestamptz,
  livekit_room_name text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    cs.id,
    cs.voice_room_id,
    cs.booking_id,
    cs.caller_id,
    cs.callee_id,
    cs.status::text,
    cs.started_at,
    cs.ended_at,
    cs.duration_seconds,
    cs.recording_consent,
    cs.recording_consent_at,
    cs.created_at,
    vr.livekit_room_name
  FROM consultation_sessions cs
  JOIN voice_rooms vr ON cs.voice_room_id = vr.id
  WHERE (cs.caller_id = v_user_id OR cs.callee_id = v_user_id)
    AND cs.status IN ('pending', 'ringing', 'active')
  ORDER BY cs.created_at DESC
  LIMIT 1;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_active_consultation_session() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_active_consultation_session() TO authenticated;


