-- -----------------------------------------------------------------------------

-- Function: public.get_active_web_push_subscriptions_for_users
-- Arguments: p_user_ids uuid[]
-- Description: Internal helper for service jobs to fetch active web push subscriptions.
-- Security: SECURITY DEFINER. Intended for service_role callers only.

CREATE OR REPLACE FUNCTION public.get_active_web_push_subscriptions_for_users(
  p_user_ids uuid[]
)
RETURNS TABLE (
  user_id uuid,
  endpoint text,
  p256dh text,
  auth text,
  expiration_time timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF p_user_ids IS NULL OR array_length(p_user_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    s.user_id,
    s.endpoint,
    s.p256dh,
    s.auth,
    s.expiration_time
  FROM public.web_push_subscriptions s
  WHERE s.user_id = ANY(p_user_ids)
    AND s.is_active = true
    AND (s.expiration_time IS NULL OR s.expiration_time > now())
  ORDER BY s.user_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_active_web_push_subscriptions_for_users(uuid[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_active_web_push_subscriptions_for_users(uuid[]) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_active_web_tracking.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_active_web_tracking
-- Purpose: THE consumer seam of web_tracking_registry. The web surface calls
--          this at boot and loads each returned tracker ONLY after the visitor
--          has granted its consent_category — the registry declares, this RPC
--          filters enabled+scope, the client's consent state gates loading.
--          A tracker that is disabled, out of scope, or unconsented is never
--          loaded; there is no other injection path.
-- SECURITY DEFINER so the anonymous web surface can read the deliberate
-- public shape (direct table read stays authenticated+scoped via RLS).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_active_web_tracking()
RETURNS TABLE (
  slug             text,
  provider         text,
  script_url       text,
  site_id          text,
  consent_category text,
  config           jsonb
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT r.slug, r.provider, r.script_url, r.site_id, r.consent_category,
         COALESCE(r.config, '{}'::jsonb) AS config
    FROM public.web_tracking_registry r
   WHERE r.is_enabled
     AND (
       r.scoped_to_instance_id IS NULL
       OR r.scoped_to_instance_id = NULLIF(current_setting('aisha.instance_id', true), '')::uuid
     )
   ORDER BY r.slug;
$$;

COMMENT ON FUNCTION public.get_active_web_tracking() IS
  'Web-surface enumeration of enabled trackers; the client loads each only after the visitor granted its consent_category.';

REVOKE ALL ON FUNCTION public.get_active_web_tracking() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_active_web_tracking() TO anon, authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_adaptive_model_tiers.sql
-- -----------------------------------------------------------------------------

-- Function: get_adaptive_model_tiers
-- Two-phase adaptive model tier selection (benchmark-based or heuristic).
-- Source: migration 20260418130100_cost_intelligence_and_hippocampus.sql
--
-- odysseus impl 03: the payload additionally carries `windows` —
--   { "<model_id>": { "context_window": int|null, "max_output_tokens": int|null } }
-- for every distinct tier model, so the chat path can enforce the input-token
-- budget from ai_model_registry (ONE window source, impl/08 §5) without a new
-- RPC. Additive + backward compatible: existing consumers read only the tier
-- keys. NULL window = consumer keeps today's behavior (no trimming).

CREATE OR REPLACE FUNCTION public.get_adaptive_model_tiers(
  p_task_type text DEFAULT 'chat'
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result JSONB := '{}'::jsonb;
  v_model TEXT;
  v_has_benchmarks BOOLEAN;
BEGIN
  -- Two-phase adaptive selection:
  --   Phase A: Use ai_model_benchmarks data (post-evaluation)
  --   Phase B: Use heuristics from ai_model_registry (pre-eval)

  SELECT EXISTS(
    SELECT 1 FROM ai_model_benchmarks b
    JOIN ai_model_registry r ON r.id = b.model_registry_id
    WHERE r.is_available AND NOT r.is_deprecated AND r.is_chat_capable
      AND (r.eval_status <> 'rejected' OR r.is_admin_active)  -- moderation: exclude admin-rejected (unless force-activated)
      AND b.task_type = p_task_type AND b.overall_score IS NOT NULL
  ) INTO v_has_benchmarks;

  IF v_has_benchmarks THEN
    -- PHASE A: BENCHMARK-BASED SELECTION

    -- greeting + simple: cheapest model with acceptable quality (score >= 0.6)
    SELECT r.model_id INTO v_model
    FROM ai_model_registry r
    JOIN ai_model_benchmarks b ON b.model_registry_id = r.id
    WHERE r.is_available AND NOT r.is_deprecated AND r.is_chat_capable
      AND (r.eval_status <> 'rejected' OR r.is_admin_active)  -- moderation: exclude admin-rejected (unless force-activated)
      AND NOT r.is_reasoning AND b.task_type = p_task_type
      AND COALESCE(b.overall_score, 0) >= 0.6
    ORDER BY b.avg_cost_per_call ASC NULLS LAST, b.overall_score DESC NULLS LAST
    LIMIT 1;
    IF v_model IS NOT NULL THEN
      v_result := v_result || jsonb_build_object('greeting', v_model, 'simple', v_model);
    END IF;

    -- moderate: balanced quality/cost
    SELECT r.model_id INTO v_model
    FROM ai_model_registry r
    JOIN ai_model_benchmarks b ON b.model_registry_id = r.id
    WHERE r.is_available AND NOT r.is_deprecated AND r.is_chat_capable
      AND (r.eval_status <> 'rejected' OR r.is_admin_active)  -- moderation: exclude admin-rejected (unless force-activated)
      AND NOT r.is_reasoning AND b.task_type = p_task_type
    ORDER BY (COALESCE(b.overall_score, 0) * 0.6 - COALESCE(b.avg_cost_per_call, 0) * 0.4) DESC
    LIMIT 1;
    IF v_model IS NOT NULL THEN
      v_result := v_result || jsonb_build_object('moderate', v_model);
    END IF;

    -- complex: highest quality non-reasoning
    SELECT r.model_id INTO v_model
    FROM ai_model_registry r
    JOIN ai_model_benchmarks b ON b.model_registry_id = r.id
    WHERE r.is_available AND NOT r.is_deprecated AND r.is_chat_capable
      AND (r.eval_status <> 'rejected' OR r.is_admin_active)  -- moderation: exclude admin-rejected (unless force-activated)
      AND NOT r.is_reasoning AND b.task_type = p_task_type
    ORDER BY b.overall_score DESC NULLS LAST, b.avg_latency_ms ASC NULLS LAST
    LIMIT 1;
    IF v_model IS NOT NULL THEN
      v_result := v_result || jsonb_build_object('complex', v_model);
    END IF;

    -- deep_analysis: highest quality reasoning model
    SELECT r.model_id INTO v_model
    FROM ai_model_registry r
    JOIN ai_model_benchmarks b ON b.model_registry_id = r.id
    WHERE r.is_available AND NOT r.is_deprecated AND r.is_chat_capable
      AND (r.eval_status <> 'rejected' OR r.is_admin_active)  -- moderation: exclude admin-rejected (unless force-activated)
      AND r.is_reasoning AND b.task_type = p_task_type
    ORDER BY b.overall_score DESC NULLS LAST
    LIMIT 1;
    IF v_model IS NOT NULL THEN
      v_result := v_result || jsonb_build_object('deep_analysis', v_model);
    END IF;

  ELSE
    -- PHASE B: HEURISTIC SELECTION (price-based)
    --
    -- Heuristic cost estimates ($/M tokens) by model name pattern:
    --   nano = 0.05, flash/haiku = 0.10, mini = 0.50,
    --   standard = 3.0, pro/opus/ultra = 15.0
    --
    -- Dated variants (e.g. gpt-4o-2024-11-20) are excluded to prefer
    -- canonical model names. Transcription models are also excluded.

    -- greeting + simple: cheapest available non-reasoning model
    SELECT model_id INTO v_model FROM ai_model_registry
    WHERE is_available AND NOT is_deprecated AND is_chat_capable AND NOT is_reasoning
      AND model_id !~ '-\d{4}-\d{2}(-\d{2})?$'
      AND model_id !~* 'transcrib|diariz|realtime|search'
    ORDER BY
      COALESCE(input_price_per_m, CASE
        WHEN model_id ~* 'nano' THEN 0.05
        WHEN model_id ~* 'flash|haiku' THEN 0.10
        WHEN model_id ~* 'mini' THEN 0.50
        WHEN model_id ~* 'pro|opus|ultra' THEN 15.0
        ELSE 3.0
      END) ASC,
      latest_eval_score DESC NULLS LAST
    LIMIT 1;
    IF v_model IS NOT NULL THEN
      v_result := v_result || jsonb_build_object('greeting', v_model, 'simple', v_model);
    END IF;

    -- moderate: mid-tier non-reasoning (closest to ~$1/M tokens)
    SELECT model_id INTO v_model FROM ai_model_registry
    WHERE is_available AND NOT is_deprecated AND is_chat_capable AND NOT is_reasoning
      AND model_id !~ '-\d{4}-\d{2}(-\d{2})?$'
      AND model_id !~* 'transcrib|diariz|realtime|search'
    ORDER BY
      ABS(COALESCE(input_price_per_m, CASE
        WHEN model_id ~* 'nano' THEN 0.05
        WHEN model_id ~* 'flash|haiku' THEN 0.10
        WHEN model_id ~* 'mini' THEN 0.50
        WHEN model_id ~* 'pro|opus|ultra' THEN 15.0
        ELSE 3.0
      END) - 1.0) ASC,
      latest_eval_score DESC NULLS LAST
    LIMIT 1;
    IF v_model IS NOT NULL THEN
      v_result := v_result || jsonb_build_object('moderate', v_model);
    END IF;

    -- complex: highest-tier non-reasoning
    SELECT model_id INTO v_model FROM ai_model_registry
    WHERE is_available AND NOT is_deprecated AND is_chat_capable AND NOT is_reasoning
      AND model_id !~ '-\d{4}-\d{2}(-\d{2})?$'
      AND model_id !~* 'transcrib|diariz|realtime|search'
    ORDER BY
      COALESCE(input_price_per_m, CASE
        WHEN model_id ~* 'nano' THEN 0.05
        WHEN model_id ~* 'flash|haiku' THEN 0.10
        WHEN model_id ~* 'mini' THEN 0.50
        WHEN model_id ~* 'pro|opus|ultra' THEN 15.0
        ELSE 3.0
      END) DESC,
      latest_eval_score DESC NULLS LAST
    LIMIT 1;
    IF v_model IS NOT NULL THEN
      v_result := v_result || jsonb_build_object('complex', v_model);
    END IF;

    -- deep_analysis: best reasoning model
    SELECT model_id INTO v_model FROM ai_model_registry
    WHERE is_available AND NOT is_deprecated AND is_chat_capable AND is_reasoning
      AND model_id !~ '-\d{4}-\d{2}(-\d{2})?$'
      AND model_id !~* 'transcrib|diariz|realtime|search'
    ORDER BY
      COALESCE(input_price_per_m, CASE
        WHEN model_id ~* 'nano' THEN 0.05
        WHEN model_id ~* 'flash|haiku' THEN 0.10
        WHEN model_id ~* 'mini' THEN 0.50
        WHEN model_id ~* 'pro|opus|ultra' THEN 15.0
        ELSE 3.0
      END) DESC,
      latest_eval_score DESC NULLS LAST
    LIMIT 1;
    IF v_model IS NOT NULL THEN
      v_result := v_result || jsonb_build_object('deep_analysis', v_model);
    END IF;

  END IF;

  -- odysseus impl 03: attach registry windows for the chosen tier models
  -- (budget enforcement source — additive `windows` key, never breaks old readers).
  IF v_result <> '{}'::jsonb THEN
    v_result := v_result || jsonb_build_object('windows', COALESCE((
      SELECT jsonb_object_agg(
               r.model_id,
               jsonb_build_object(
                 'context_window', r.context_window,
                 'max_output_tokens', r.max_output_tokens
               )
             )
      FROM ai_model_registry r
      WHERE r.model_id IN (
        SELECT DISTINCT value #>> '{}'
        FROM jsonb_each(v_result - 'windows')
        WHERE jsonb_typeof(value) = 'string'
      )
    ), '{}'::jsonb));
  END IF;

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION get_adaptive_model_tiers(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION get_adaptive_model_tiers(text) TO authenticated;
GRANT EXECUTE ON FUNCTION get_adaptive_model_tiers(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_agent_phase_catalog.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_agent_phase_catalog
-- Description: Returns the active agent phase taxonomy (all axes) for UI
--   consumers — Mission Control badges and the Dirigent VS Code panel read
--   labels from here instead of hardcoding phase→label maps. Static fallback
--   maps in clients cover offline/cold-start.
-- Security: SECURITY DEFINER, read-only.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_agent_phase_catalog()
RETURNS TABLE (
  slug       text,
  axis       text,
  labels     jsonb,
  sort_order int
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  -- Auth: authenticated users and service_role; catalog labels are not
  -- sensitive but follow the platform default-deny posture for RPCs.
  IF auth.uid() IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT c.slug, c.axis, c.labels, c.sort_order
  FROM public.agent_phase_catalog c
  WHERE c.is_active = true
  ORDER BY c.axis, c.sort_order, c.slug;
END;
$$;

REVOKE ALL ON FUNCTION public.get_agent_phase_catalog() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_agent_phase_catalog() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_agent_phase_catalog() TO service_role;

COMMENT ON FUNCTION public.get_agent_phase_catalog() IS
  'Active agent phase taxonomy (axis + slug + locale labels) for UI badge rendering. Clients keep a static fallback map for cold-start.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_agent_publish_detail.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_agent_publish_detail
-- Purpose: Return the evaluable content of a marketplace agent for the
--          WF_KB_COMPLIANCE_GATE n8n workflow (AISHA compliance review).
--          publish_agent's webhook carries only plugin_id; the workflow needs
--          the full agent content (name, description, capabilities, agent_spec)
--          to evaluate. get_available_plugins can't serve this — it filters
--          status IN ('canary','ga') (excludes 'reviewing') and omits agent_spec.
--
-- Keyed on plugin_catalog.id (the webhook payload field).
-- Security: SECURITY DEFINER, **service_role ONLY** — a 'reviewing' (not yet
-- public) agent's content must not leak to anon/authenticated.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_agent_publish_detail(p_plugin_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id',                pc.id,
    'slug',              pc.slug,
    'name',              pc.name,
    'description',       pc.description,
    'kind',              pc.kind::text,
    'status',            pc.status::text,
    'trust_tier',        pc.trust_tier::text,
    'capabilities',      COALESCE(pc.capabilities, '[]'::jsonb),
    'agent_spec',        pc.agent_spec,
    'author_partner_id', pc.author_partner_id
  )
  INTO v_result
  FROM public.plugin_catalog pc
  WHERE pc.id = p_plugin_id AND pc.kind = 'agent';

  RETURN v_result;  -- NULL when not found / not an agent
END;
$$;

COMMENT ON FUNCTION public.get_agent_publish_detail(uuid) IS
  'Full marketplace-agent content for the compliance-gate workflow. service_role only (review content must not leak).';

REVOKE ALL ON FUNCTION public.get_agent_publish_detail(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_agent_publish_detail(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_agent_run.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_agent_run
-- Description: Fetch full details of a single agent run by ID.
--   Accessible to the requesting user and service_role.
-- Security: SECURITY DEFINER, grants to authenticated + service_role

-- Return shape gained the structured `outputs` + the admission/approval columns
-- (approval_required / approved_at / awaiting) — DROP the prior shape so the new
-- RETURNS TABLE replaces it (a column-set change is not a CREATE OR REPLACE).
DROP FUNCTION IF EXISTS public.get_agent_run(uuid);

CREATE OR REPLACE FUNCTION public.get_agent_run(p_run_id uuid)
RETURNS TABLE (
  id                uuid,
  kind              text,
  profile           text,
  status            text,
  source            text,
  source_ref        text,
  outputs_s3_uri    text,
  outputs           jsonb,
  exit_code         integer,
  error_summary     text,
  approval_required boolean,
  approved_at       timestamptz,
  awaiting          text,
  started_at        timestamptz,
  finished_at       timestamptz,
  created_at        timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  RETURN QUERY
  SELECT
    r.id, r.kind, r.profile, r.status, r.source, r.source_ref,
    r.outputs_s3_uri, r.outputs, r.exit_code, r.error_summary,
    r.approval_required, r.approved_at, r.awaiting,
    r.started_at, r.finished_at, r.created_at
  FROM public.agent_runs r
  WHERE r.id = p_run_id
    AND (r.requested_by = auth.uid() OR auth.jwt() ->> 'role' = 'service_role');
END;
$$;

REVOKE ALL ON FUNCTION public.get_agent_run(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_agent_run(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_agent_run(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_agent_tool.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_agent_tool
-- Description: Runtime lookup of a tool by name. Used by edge functions to resolve tool definitions.
-- Security: SECURITY DEFINER, grants to service_role + authenticated
-- Created: Phase 2 — Tool System

CREATE OR REPLACE FUNCTION public.get_agent_tool(p_name text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', t.id,
    'name', t.name,
    'description', t.description,
    'parameters_schema', t.parameters_schema,
    'handler_type', t.handler_type::text,
    'handler_ref', t.handler_ref,
    'access_tier_min', t.access_tier_min,
    'requires_consent', t.requires_consent,
    'audit_action', t.audit_action,
    'metadata', t.metadata
  )
  INTO v_result
  FROM agent_tools t
  WHERE t.name = p_name AND t.is_active = true;

  IF v_result IS NULL THEN
    RAISE EXCEPTION 'Tool not found or inactive: %', p_name USING ERRCODE = 'P0002';
  END IF;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.get_agent_tool(text) FROM PUBLIC;
