-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_autonomy_enforcement_rules.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_autonomy_enforcement_rules
-- Purpose: Returns the enforcement policy (approval, notification, escalation, audit)
--          for a given risk level (low/medium/high/critical).
--          Used by n8n workflows and AI agent runtime to enforce risk-to-autonomy policy.
-- Security: SECURITY DEFINER with search_path set.
-- Part of: Fáze 2 — Critical Gap Closure (risk-to-autonomy enforcement)

CREATE OR REPLACE FUNCTION public.get_autonomy_enforcement_rules(
  p_risk_level text
)
RETURNS TABLE (
  risk_level          text,
  requires_approval   boolean,
  auto_approve        boolean,
  notify_level        text,        -- 'none' | 'log_only' | 'dirigent' | 'expert'
  escalation_minutes  int,         -- 0 = no auto-escalation; >0 = escalate after N minutes
  audit_required      boolean,
  action_description  text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  -- Only authenticated users or service_role may query enforcement rules
  IF auth.uid() IS NULL AND auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Unauthorized: authentication required to query enforcement rules';
  END IF;

  RETURN QUERY SELECT
    lower(p_risk_level)::text,
    CASE lower(p_risk_level)
      WHEN 'critical' THEN true
      WHEN 'high'     THEN true
      WHEN 'medium'   THEN false
      WHEN 'low'      THEN false
      ELSE true  -- deny-by-default: unknown risk requires approval
    END,
    CASE lower(p_risk_level)
      WHEN 'critical' THEN false
      WHEN 'high'     THEN false
      WHEN 'medium'   THEN true
      WHEN 'low'      THEN true
      ELSE false  -- deny-by-default: unknown risk NOT auto-approved
    END,
    CASE lower(p_risk_level)
      WHEN 'critical' THEN 'expert'::text
      WHEN 'high'     THEN 'expert'::text
      WHEN 'medium'   THEN 'dirigent'::text
      WHEN 'low'      THEN 'log_only'::text
      ELSE 'expert'::text  -- deny-by-default: unknown risk escalates to expert
    END,
    CASE lower(p_risk_level)
      WHEN 'critical' THEN 60
      WHEN 'high'     THEN 240
      WHEN 'medium'   THEN 0
      WHEN 'low'      THEN 0
      ELSE 60  -- deny-by-default: unknown risk auto-escalates in 60min
    END,
    CASE lower(p_risk_level)
      WHEN 'critical' THEN true
      WHEN 'high'     THEN true
      WHEN 'medium'   THEN true
      WHEN 'low'      THEN false
      ELSE true  -- deny-by-default: unknown risk requires audit
    END,
    CASE lower(p_risk_level)
      WHEN 'critical' THEN 'HARD STOP: Manual expert approval required. Auto-escalate after 60min. Full audit mandatory.'::text
      WHEN 'high'     THEN 'APPROVAL REQUIRED: Expert approval needed. Notify Dirigent + Expert. Auto-escalate after 4h.'::text
      WHEN 'medium'   THEN 'AUTO-APPROVE with notification: Notify Dirigent. Audit trail recorded.'::text
      WHEN 'low'      THEN 'AUTO-APPROVE: Log only. No explicit notification.'::text
      ELSE 'BLOCKED: Unknown risk level — deny-by-default. Requires expert approval + full audit.'::text
    END;
END;
$$;

REVOKE ALL ON FUNCTION public.get_autonomy_enforcement_rules(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_autonomy_enforcement_rules(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_autonomy_enforcement_rules(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_batch_detail_transparency.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_batch_detail_transparency
-- Description: Returns detailed batch transparency info for a specific production batch.
--   Includes QC status, materials, blockchain verification, protocol steps.
--   Non-sensitive data, member-accessible.
-- Security: SECURITY DEFINER - authenticated batch transparency access.
-- @security: authenticated
-- @audit: none

CREATE OR REPLACE FUNCTION public.get_batch_detail_transparency(p_batch_code text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_batch RECORD;
  v_product RECORD;
  v_protocol_steps jsonb;
  v_materials jsonb;
  v_topics jsonb;
BEGIN
  -- Get batch info
  SELECT
    pb.id,
    pb.batch_code,
    pb.batch_number,
    pb.product_id,
    pb.status,
    pb.production_date,
    pb.expiry_date,
    pb.quality_approved,
    pb.qc_approved_at,
    pb.qc_notes,
    pb.raw_material_lot,
    pb.supplier_info,
    pb.blockchain_tx_hash,
    pb.blockchain_recorded_at,
    pb.unit,
    pb.total_units,
    pb.available_units,
    pb.released_at,
    pb.content_type,
    pb.purpose,
    pb.projected_yield_percent
  INTO v_batch
  FROM production_batches pb
  WHERE (pb.batch_code = p_batch_code OR pb.batch_number = p_batch_code)
    AND pb.status IN ('released', 'completed');

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Batch not found or not released');
  END IF;

  -- Get product info
  SELECT
    p.name,
    p.slug,
    p.category,
    p.image_url
  INTO v_product
  FROM products p
  WHERE p.id = v_batch.product_id;

  -- Get completed protocol steps (non-sensitive, transparency-only fields)
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'step_name', pps.step_name,
      'step_order', pps.step_order,
      'step_type', pps.step_type,
      'description', pps.description,
      'is_completed', pps.is_completed,
      'completed_at', pps.completed_at,
      'status', pps.status
    ) ORDER BY pps.step_order
  ), '[]'::jsonb) INTO v_protocol_steps
  FROM production_protocol_steps pps
  WHERE pps.batch_id = v_batch.id;

  -- Get batch materials (non-sensitive, join to get material names)
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'material_name', pm.item_name,
      'item_code', pm.item_code,
      'direction', pbm.direction,
      'planned_qty', pbm.planned_qty,
      'actual_qty', pbm.actual_qty,
      'unit', pbm.uom,
      'lot_number', pl.lot_number
    )
  ), '[]'::jsonb) INTO v_materials
  FROM production_batch_materials pbm
  JOIN production_materials pm ON pm.id = pbm.item_id
  LEFT JOIN production_lots pl ON pl.id = pbm.lot_id
  WHERE pbm.batch_id = v_batch.id
    AND pbm.direction IN ('IN', 'OUT');

  -- Get related knowledge topics (via batch link)
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'topic_id', kt.id,
      'slug', kt.slug,
      'title_key', kt.title_key,
      'verification_status', kt.verification_status
    ) ORDER BY ktl.sort_order
  ), '[]'::jsonb) INTO v_topics
  FROM knowledge_topic_links ktl
  JOIN knowledge_topics kt ON kt.id = ktl.topic_id
  WHERE ktl.production_batch_id = v_batch.id
    AND kt.visibility IN ('public', 'members');

  RETURN jsonb_build_object(
    'batch', jsonb_build_object(
      'id', v_batch.id,
      'batch_code', v_batch.batch_code,
      'batch_number', v_batch.batch_number,
      'status', v_batch.status,
      'production_date', v_batch.production_date,
      'expiry_date', v_batch.expiry_date,
      'quality_approved', v_batch.quality_approved,
      'qc_approved_at', v_batch.qc_approved_at,
      'qc_notes', v_batch.qc_notes,
      'raw_material_lot', v_batch.raw_material_lot,
      'supplier_info', v_batch.supplier_info,
      'blockchain_tx_hash', v_batch.blockchain_tx_hash,
      'blockchain_recorded_at', v_batch.blockchain_recorded_at,
      'released_at', v_batch.released_at,
      'content_type', v_batch.content_type,
      'purpose', v_batch.purpose,
      'total_units', v_batch.total_units,
      'available_units', v_batch.available_units,
      'projected_yield_percent', v_batch.projected_yield_percent
    ),
    'product', jsonb_build_object(
      'name', v_product.name,
      'slug', v_product.slug,
      'category', v_product.category,
      'image_url', v_product.image_url
    ),
    'protocol_steps', v_protocol_steps,
    'materials', v_materials,
    'knowledge_topics', v_topics
  );
END;
$function$;

-- Permissions: authenticated only (members can see batch details)
REVOKE ALL ON FUNCTION public.get_batch_detail_transparency(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_batch_detail_transparency(text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_best_model_for_task.sql
-- -----------------------------------------------------------------------------

-- Function: get_best_model_for_task

CREATE OR REPLACE FUNCTION public.get_best_model_for_task(p_task_type text, p_provider text DEFAULT NULL::text, p_min_safety_score numeric DEFAULT 0.8, p_max_cost_per_call numeric DEFAULT NULL::numeric, p_require_reasoning boolean DEFAULT false, p_require_vision boolean DEFAULT false, p_require_function_calling boolean DEFAULT false)
 RETURNS TABLE(model_registry_id uuid, provider text, model_id text, overall_score numeric, avg_latency_ms integer, avg_cost_per_call numeric, safety_score numeric, is_reasoning boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- This function is used by ai-router, needs service_role or authenticated
  RETURN QUERY
  SELECT
    r.id AS model_registry_id,
    r.provider,
    r.model_id,
    b.overall_score,
    b.avg_latency_ms,
    b.avg_cost_per_call,
    b.safety_score,
    r.is_reasoning
  FROM ai_model_registry r
  INNER JOIN ai_model_benchmarks b ON b.model_registry_id = r.id
  WHERE r.is_available = true
    AND r.eval_status = 'approved'
    AND NOT r.is_deprecated
    AND b.task_type = p_task_type
    AND (b.safety_score IS NULL OR b.safety_score >= p_min_safety_score)
    AND (p_provider IS NULL OR r.provider = p_provider)
    AND (p_max_cost_per_call IS NULL OR b.avg_cost_per_call <= p_max_cost_per_call)
    AND (NOT p_require_reasoning OR r.is_reasoning = true)
    AND (NOT p_require_vision OR r.is_vision = true)
    AND (NOT p_require_function_calling OR r.is_function_calling = true)
  ORDER BY
    b.overall_score DESC NULLS LAST,
    b.avg_latency_ms ASC NULLS LAST,
    b.avg_cost_per_call ASC NULLS LAST
  LIMIT 5;
END;
$function$;

REVOKE ALL ON FUNCTION get_best_model_for_task(text, text, numeric, numeric, boolean, boolean, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION get_best_model_for_task(text,text,numeric,numeric,boolean,boolean,boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION get_best_model_for_task(text,text,numeric,numeric,boolean,boolean,boolean) TO service_role;


