-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_branding_profile.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- Function: get_branding_profile — Resolved branding with fallback chain
-- =============================================================================
-- Returns published branding profile for a given partner.
-- If partner has no published profile, falls back to global (partner_id IS NULL).
-- Public access (SECURITY DEFINER) — branding must be visible for login pages.

CREATE OR REPLACE FUNCTION public.get_branding_profile(
  p_partner_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_partner_row jsonb;
  v_global_row jsonb;
  v_result jsonb;
BEGIN
  -- Try partner-specific published profile
  IF p_partner_id IS NOT NULL THEN
    SELECT jsonb_build_object(
      'id', bp.id,
      'partner_id', bp.partner_id,
      'status', bp.status,
      'color_primary', bp.color_primary,
      'color_secondary', bp.color_secondary,
      'color_accent', bp.color_accent,
      'color_background', bp.color_background,
      'color_foreground', bp.color_foreground,
      'color_muted', bp.color_muted,
      'color_surface', bp.color_surface,
      'color_destructive', bp.color_destructive,
      'dark_color_primary', bp.dark_color_primary,
      'dark_color_background', bp.dark_color_background,
      'dark_color_foreground', bp.dark_color_foreground,
      'dark_color_surface', bp.dark_color_surface,
      'dark_color_muted', bp.dark_color_muted,
      'font_family_brand', bp.font_family_brand,
      'font_family_body', bp.font_family_body,
      'font_family_code', bp.font_family_code,
      'font_faces', bp.font_faces,
      'logo_path', bp.logo_path,
      'logo_dark_path', bp.logo_dark_path,
      'favicon_path', bp.favicon_path,
      'login_logo_path', bp.login_logo_path,
      'operator_name', bp.operator_name,
      'operator_email', bp.operator_email,
      'operator_phone', bp.operator_phone,
      'operator_address', bp.operator_address,
      'operator_url', bp.operator_url,
      'email_header_bg', bp.email_header_bg,
      'email_footer_text', bp.email_footer_text,
      'login_background_color', bp.login_background_color,
      'login_card_bg', bp.login_card_bg,
      'login_accent_color', bp.login_accent_color,
      'profile_version', bp.profile_version,
      'updated_at', bp.updated_at,
      'published_at', bp.published_at
    ) INTO v_partner_row
    FROM branding_profiles bp
    WHERE bp.partner_id = p_partner_id
      AND bp.status = 'published'
    ORDER BY bp.published_at DESC NULLS LAST, bp.id
    LIMIT 1;
  END IF;

  -- Always load global fallback
  SELECT jsonb_build_object(
    'id', bp.id,
    'partner_id', bp.partner_id,
    'status', bp.status,
    'color_primary', bp.color_primary,
    'color_secondary', bp.color_secondary,
    'color_accent', bp.color_accent,
    'color_background', bp.color_background,
    'color_foreground', bp.color_foreground,
    'color_muted', bp.color_muted,
    'color_surface', bp.color_surface,
    'color_destructive', bp.color_destructive,
    'dark_color_primary', bp.dark_color_primary,
    'dark_color_background', bp.dark_color_background,
    'dark_color_foreground', bp.dark_color_foreground,
    'dark_color_surface', bp.dark_color_surface,
    'dark_color_muted', bp.dark_color_muted,
    'font_family_brand', bp.font_family_brand,
    'font_family_body', bp.font_family_body,
    'font_family_code', bp.font_family_code,
    'font_faces', bp.font_faces,
    'logo_path', bp.logo_path,
    'logo_dark_path', bp.logo_dark_path,
    'favicon_path', bp.favicon_path,
    'login_logo_path', bp.login_logo_path,
    'operator_name', bp.operator_name,
    'operator_email', bp.operator_email,
    'operator_phone', bp.operator_phone,
    'operator_address', bp.operator_address,
    'operator_url', bp.operator_url,
    'email_header_bg', bp.email_header_bg,
    'email_footer_text', bp.email_footer_text,
    'login_background_color', bp.login_background_color,
    'login_card_bg', bp.login_card_bg,
    'login_accent_color', bp.login_accent_color,
    'profile_version', bp.profile_version,
    'updated_at', bp.updated_at,
    'published_at', bp.published_at
  ) INTO v_global_row
  FROM branding_profiles bp
  WHERE bp.partner_id IS NULL
    AND bp.status = 'published'
  -- The unique index only covers partner brands (partner_id IS NOT NULL), so N
  -- published platform brands are allowed to coexist. Without an explicit order a
  -- SELECT INTO picked whichever the planner happened to return — the "default"
  -- brand was decided by chance. Newest published wins; id breaks ties.
  ORDER BY bp.published_at DESC NULLS LAST, bp.id
  LIMIT 1;

  -- Merge: partner values override global; NULL partner fields fall through to global
  IF v_partner_row IS NOT NULL AND v_global_row IS NOT NULL THEN
    -- Strip null values from partner row before merge so global acts as fallback
    v_result := v_global_row;
    -- Overlay non-null partner values
    SELECT jsonb_object_agg(key, value) INTO v_partner_row
    FROM jsonb_each(v_partner_row)
    WHERE value != 'null'::jsonb;
    v_result := v_result || COALESCE(v_partner_row, '{}'::jsonb);
  ELSIF v_partner_row IS NOT NULL THEN
    v_result := v_partner_row;
  ELSIF v_global_row IS NOT NULL THEN
    v_result := v_global_row;
  ELSE
    RETURN jsonb_build_object('status', 'not_found');
  END IF;

  v_result := v_result || jsonb_build_object(
    'resolved_for', COALESCE(p_partner_id, '00000000-0000-0000-0000-000000000000'::uuid)
  );

  RETURN jsonb_build_object('status', 'ok', 'profile', v_result);
END;
$$;

REVOKE ALL ON FUNCTION public.get_branding_profile(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_branding_profile(uuid) TO public;

COMMENT ON FUNCTION public.get_branding_profile(uuid) IS
  'Returns resolved branding profile (partner override merged over global fallback). Public access for login pages.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_certified_partners.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_certified_partners
-- Arguments: p_include_availability BOOLEAN, p_randomize BOOLEAN, p_limit INTEGER
-- Description: Returns certified partners with optional availability data, randomization, and limit.
-- Restored 2026-01-08: Full parameterized version from migration 20251220030000.
-- Security: SECURITY DEFINER, public access (seznam partnerů na /partners je veřejný)

CREATE OR REPLACE FUNCTION public.get_certified_partners(
  p_include_availability BOOLEAN DEFAULT FALSE,
  p_randomize BOOLEAN DEFAULT FALSE,
  p_limit INTEGER DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $function$
DECLARE
  v_result JSONB;
  v_partners JSONB;
  v_availability JSONB;
BEGIN
  -- Get certified partners from partner_profiles
  SELECT jsonb_agg(row_to_json(p)::jsonb)
  INTO v_partners
  FROM (
    SELECT 
      pp.id,
      pp.user_id,
      pp.certification_level,
      pp.is_production_provider,
      pp.business_name,
      pp.display_name,
      pp.description,
      pp.notes_for_visitors,
      pp.languages,
      pp.city,
      pp.country,
      pp.website,
      pp.services,
      pp.is_visible,
      pp.accepts_online_appointments,
      pp.accepts_in_person_appointments,
      pp.certification_passed_at,
      pp.certification_score,
      pp.avatar_url,
      pp.created_at,
      pp.updated_at
    FROM partner_profiles pp
    WHERE pp.certification_passed_at IS NOT NULL
      AND pp.is_visible = TRUE
    ORDER BY 
      CASE WHEN p_randomize THEN RANDOM() ELSE 0 END,
      pp.certification_score DESC NULLS LAST
    LIMIT p_limit
  ) p;

  IF v_partners IS NULL THEN
    RETURN '[]'::JSONB;
  END IF;

  -- Include availability if requested
  IF p_include_availability THEN
    SELECT jsonb_object_agg(partner_id, slots)
    INTO v_availability
    FROM (
      SELECT 
        pa.partner_id,
        jsonb_agg(jsonb_build_object(
          'id', pa.id,
          'partner_id', pa.partner_id,
          'day_of_week', pa.day_of_week,
          'start_time', pa.start_time,
          'end_time', pa.end_time,
          'is_online', pa.is_online,
          'created_at', pa.created_at
        )) AS slots
      FROM partner_availability pa
      WHERE pa.partner_id IN (SELECT (p->>'id')::UUID FROM jsonb_array_elements(v_partners) p)
      GROUP BY pa.partner_id
    ) a;

    -- Merge availability into partners
    SELECT jsonb_agg(
      p || jsonb_build_object(
        'availability', COALESCE(v_availability->(p->>'id'), '[]'::JSONB),
        'hasAvailability', v_availability->(p->>'id') IS NOT NULL 
          AND jsonb_array_length(COALESCE(v_availability->(p->>'id'), '[]'::JSONB)) > 0
      )
    )
    INTO v_result
    FROM jsonb_array_elements(v_partners) p;
    
    RETURN COALESCE(v_result, '[]'::JSONB);
  END IF;

  -- Add hasAvailability: false to all if not including availability
  SELECT jsonb_agg(
    p || jsonb_build_object('hasAvailability', FALSE, 'availability', '[]'::JSONB)
  )
  INTO v_result
  FROM jsonb_array_elements(v_partners) p;

  RETURN COALESCE(v_result, '[]'::JSONB);
END;
$function$;

COMMENT ON FUNCTION public.get_certified_partners(boolean, boolean, integer) IS 
  'Get certified partners with optional availability, randomization, and limit. RPC-only.';

-- Permissions (PUBLIC: seznam partnerů na /partners je veřejný)
REVOKE ALL ON FUNCTION public.get_certified_partners(BOOLEAN, BOOLEAN, INTEGER) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_certified_partners(BOOLEAN, BOOLEAN, INTEGER) TO anon;
GRANT EXECUTE ON FUNCTION public.get_certified_partners(BOOLEAN, BOOLEAN, INTEGER) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_chat_context_story_id.sql
-- -----------------------------------------------------------------------------

-- Source of Truth: get_chat_context_story_id
-- Purpose: Resolve the most relevant story context for AI chat composition.
--          Prioritizes caller-owned active stories with story_contexts/rulesets.
-- Used by: ai-chat edge function

CREATE OR REPLACE FUNCTION public.get_chat_context_story_id(
  p_story_id uuid DEFAULT NULL::uuid,
  p_user_id uuid DEFAULT auth.uid()
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_story_id uuid;
BEGIN
  -- §19.1: an explicit story_id resolves ONLY when owned by the caller.
  IF p_story_id IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM partner_stories ps WHERE ps.id = p_story_id AND ps.user_id = p_user_id) THEN
      RETURN p_story_id;
    END IF;
    -- Non-owned explicit id is a hard tenancy error — fail closed, never resolve
    -- a foreign story and never silently substitute the caller's own.
    RETURN NULL;
  END IF;

  -- Prefer active stories owned by the caller and already context-ready.
  SELECT ps.id INTO v_story_id
  FROM partner_stories ps
  LEFT JOIN story_contexts sc ON sc.story_id = ps.id
  WHERE ps.user_id = p_user_id
    AND ps.status = 'active'
  ORDER BY
    CASE WHEN sc.story_id IS NOT NULL THEN 0 ELSE 1 END,
    ps.updated_at DESC NULLS LAST,
    ps.created_at DESC
  LIMIT 1;

  -- §19.1: NO arbitrary-active fallback. Returning another tenant's story would
  -- poison story-scope/RLS/chargeback. NULL ⇒ caller fail-closes (story-required).
  RETURN v_story_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_chat_context_story_id(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_chat_context_story_id(uuid, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_chat_context_story_id(uuid, uuid) TO service_role;


