-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_completed_batches_pending_resume.sql
-- -----------------------------------------------------------------------------

-- Function: get_completed_batches_pending_resume
-- Returns batch jobs that completed at the provider AND have a related run
-- still in 'waiting_batch' status (so WF_BATCH_RESUMER must fetch results +
-- resume). Idempotent: jobs whose state.batch_result is already populated
-- are excluded (means a prior resumer run already handled them but the run
-- hasn't progressed yet — likely runWorkflow is in flight).
--
-- Called by n8n WF_BATCH_RESUMER on its scheduleTrigger (every 5 min).
-- Pairs with persist_batch_result_and_resume which closes the loop.

CREATE OR REPLACE FUNCTION public.get_completed_batches_pending_resume(
  p_limit int DEFAULT 20
)
RETURNS TABLE (
  batch_job_id uuid,
  external_batch_id text,
  provider text,
  result_url text,
  related_run_id uuid,
  succeeded_count int,
  errored_count int,
  metadata jsonb,
  agent_slug text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT j.id            AS batch_job_id,
         j.external_batch_id,
         j.provider,
         j.result_url,
         j.related_run_id,
         j.succeeded_count,
         j.errored_count,
         j.metadata,
         j.agent_slug
  FROM   ai_batch_jobs j
  JOIN   ai_runs r ON r.id = j.related_run_id
  WHERE  j.status = 'completed'
    AND  j.related_run_id IS NOT NULL
    AND  j.result_url IS NOT NULL
    AND  r.status = 'waiting_batch'
    -- Idempotency: skip if state.batch_result already populated. The presence
    -- of this key indicates persist_batch_result_and_resume already ran;
    -- runWorkflow is either in-flight or will be picked up on next call.
    AND  (
           (r.metadata -> 'checkpoint' -> 'state' -> 'batch_result') IS NULL
        OR (r.metadata -> 'checkpoint' -> 'state' -> 'batch_result') = 'null'::jsonb
         )
  ORDER  BY j.completed_at ASC NULLS LAST
  LIMIT  p_limit;
END;
$$;

REVOKE ALL ON FUNCTION public.get_completed_batches_pending_resume(int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_completed_batches_pending_resume(int) TO service_role;

COMMENT ON FUNCTION public.get_completed_batches_pending_resume(int) IS
  'WF_BATCH_RESUMER discovery RPC — returns completed batch jobs whose related ai_runs are still in waiting_batch + don''t yet have a batch_result in state. Service-role only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_consented_users_longevity_scores.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_consented_users_longevity_scores
-- Arguments: p_limit integer DEFAULT 50
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.get_consented_users_longevity_scores(p_limit integer DEFAULT 50)
 RETURNS TABLE(user_id uuid, display_name text, overall_score numeric, trend text, trend_percentage numeric, domains jsonb, assessed_at timestamp with time zone, assessment_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Authorization: Must be authenticated and be a partner with consents
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'sensitive data_READ',
    jsonb_build_object(
      'area', 'partner',
      'severity', 'info',
      'entity_type', 'longevity_score',
      'action_detail', 'consented_users_scores',
      'limit', p_limit
    )
  );

  RETURN QUERY
  WITH consented AS (
    -- Get user IDs where current user (as partner) has consent
    SELECT DISTINCT dsc.user_id AS user_id
    FROM data_sharing_consents dsc
    JOIN partner_profiles pp ON pp.id = dsc.partner_id
    WHERE pp.user_id = auth.uid()
      AND dsc.revoked_at IS NULL
  ),
  latest_scores AS (
    -- Get latest longevity score for each consented user
    SELECT DISTINCT ON (ls.user_id)
      ls.user_id,
      ls.overall_score,
      ls.domains,
      ls.created_at AS assessed_at
    FROM longevity_scores ls
    JOIN consented c ON c.user_id = ls.user_id
    ORDER BY ls.user_id, ls.created_at DESC
  ),
  score_counts AS (
    -- Count total assessments per user
    SELECT ls.user_id, COUNT(*)::INTEGER AS assessment_count
    FROM longevity_scores ls
    JOIN consented c ON c.user_id = ls.user_id
    GROUP BY ls.user_id
  ),
  trends AS (
    -- Calculate trend from last two assessments
    SELECT 
      ls.user_id,
      CASE 
        WHEN COUNT(*) < 2 THEN 'neutral'::TEXT
        WHEN (array_agg(ls.overall_score ORDER BY ls.created_at DESC))[1] > 
             (array_agg(ls.overall_score ORDER BY ls.created_at DESC))[2] THEN 'up'::TEXT
        WHEN (array_agg(ls.overall_score ORDER BY ls.created_at DESC))[1] < 
             (array_agg(ls.overall_score ORDER BY ls.created_at DESC))[2] THEN 'down'::TEXT
        ELSE 'neutral'::TEXT
      END AS trend,
      CASE 
        WHEN COUNT(*) < 2 THEN 0
        ELSE ABS(
          (array_agg(ls.overall_score ORDER BY ls.created_at DESC))[1] - 
          (array_agg(ls.overall_score ORDER BY ls.created_at DESC))[2]
        )
      END AS trend_percentage
    FROM longevity_scores ls
    JOIN consented c ON c.user_id = ls.user_id
    GROUP BY ls.user_id
  )
  SELECT 
    lsc.user_id,
    COALESCE(p.display_name, 'Member ' || LEFT(lsc.user_id::TEXT, 8)) AS display_name,
    lsc.overall_score,
    COALESCE(tr.trend, 'neutral') AS trend,
    COALESCE(tr.trend_percentage, 0) AS trend_percentage,
    lsc.domains,
    lsc.assessed_at,
    COALESCE(sc.assessment_count, 0) AS assessment_count
  FROM latest_scores lsc
  LEFT JOIN profiles p ON p.user_id = lsc.user_id
  LEFT JOIN score_counts sc ON sc.user_id = lsc.user_id
  LEFT JOIN trends tr ON tr.user_id = lsc.user_id
  ORDER BY lsc.assessed_at DESC
  LIMIT p_limit;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_consented_users_longevity_scores(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_consented_users_longevity_scores(integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_consented_users_longevity_scores(integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_consultant_studies.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_consultant_studies
-- Arguments: (none)
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:44+01:00

CREATE OR REPLACE FUNCTION public.get_consultant_studies()
 RETURNS TABLE(id uuid, study_id uuid, partner_id uuid, status text, applied_at timestamptz, approved_at timestamptz, study_name text, study_code text, study_status text, registration_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_id UUID;
BEGIN
  -- Get partner profile for current user
  SELECT pp.id INTO v_partner_id
  FROM partner_profiles pp
  WHERE pp.user_id = auth.uid();

  IF v_partner_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT 
    sc.id,
    sc.study_id,
    sc.partner_id,
    sc.status::TEXT,
    sc.applied_at,
    sc.approved_at,
    s.name as study_name,
    s.code as study_code,
    s.status::TEXT as study_status,
    (SELECT COUNT(*) FROM study_registrations se WHERE se.study_id = sc.study_id AND se.consultant_id = sc.id) as registration_count
  FROM study_consultants sc
  JOIN studies s ON s.id = sc.study_id
  WHERE sc.partner_id = v_partner_id
  ORDER BY sc.applied_at DESC;
END;
$function$
;

-- Permissions
