-- -----------------------------------------------------------------------------

-- =============================================================================
-- Function: get_design_profile — Occipitum: fetch design DNA for a partner
-- =============================================================================
CREATE OR REPLACE FUNCTION public.get_design_profile(
  p_partner_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', dp.id,
    'partner_id', dp.partner_id,
    'brand_dna', dp.brand_dna,
    'ux_persona', dp.ux_persona,
    'style_preferences', dp.style_preferences,
    'design_constraints', dp.design_constraints,
    'profile_version', dp.profile_version,
    'created_at', dp.created_at,
    'updated_at', dp.updated_at
  ) INTO v_result
  FROM public.design_profiles dp
  WHERE dp.partner_id = p_partner_id;

  IF v_result IS NULL THEN
    RETURN jsonb_build_object('status', 'not_found', 'partner_id', p_partner_id);
  END IF;

  RETURN jsonb_build_object('status', 'ok', 'profile', v_result);
END;
$$;

COMMENT ON FUNCTION public.get_design_profile(uuid) IS
  'Occipitum: returns design DNA profile for a partner. RLS-enforced (SECURITY INVOKER).';

-- Permissions: SECURITY INVOKER → must grant explicitly. Frontend caller:
-- src/hooks/useDesignProfile.ts (aisha.rpc("get_design_profile", ...)).
REVOKE ALL ON FUNCTION public.get_design_profile(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_design_profile(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_design_profile(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_dirigent_questionnaires_mobile.sql
-- -----------------------------------------------------------------------------

-- get_dirigent_questionnaires_mobile: Mobile-optimized questionnaire listing
-- Called by: mobile-app/src/hooks/useQuestionnaires.ts
CREATE OR REPLACE FUNCTION public.get_dirigent_questionnaires_mobile(
  p_story_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  -- Questionnaires are GLOBAL templates keyed by `code`; they carry no title/
  -- story_id/status/created_by column (the previous body selected four columns that
  -- do not exist, so every call raised 42703). Per-user state lives in
  -- questionnaire_responses — same shape the sibling get_study_questionnaires_mobile
  -- returns. p_story_id is kept in the signature for call-site compatibility but is
  -- not a real dimension of questionnaires, so it is accepted and ignored.
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', q.id,
      'code', q.code,
      'title', q.name,
      'status', CASE WHEN r.last_completed_at IS NOT NULL THEN 'completed' ELSE 'pending' END,
      'completed_at', r.last_completed_at
    ) ORDER BY q.created_at DESC
  ), '[]'::jsonb)
  INTO v_result
  FROM questionnaires q
  LEFT JOIN (
    SELECT qr.questionnaire_id, MAX(qr.completed_at) AS last_completed_at
    FROM questionnaire_responses qr
    WHERE qr.user_id = v_user_id
    GROUP BY qr.questionnaire_id
  ) r ON r.questionnaire_id = q.id
  WHERE q.is_active = true;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.get_dirigent_questionnaires_mobile(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_dirigent_questionnaires_mobile(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_discussion_entries.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: public.get_discussion_entries
-- Popis: Threaded READ of the discussion under a PUBLIC content node (article /
--        web_page). Returns visible, non-internal entries with their author +
--        parent so the client can render the thread. SECURITY DEFINER bypasses
--        RLS, so access is enforced here: the subject must be publicly
--        discussable (mirrors story_entries__public_discussion_read) — this
--        function never exposes member-private story or internal entries.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT; authenticated only.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_discussion_entries(
  p_subject_type text,
  p_subject_id   uuid,
  p_limit        integer DEFAULT 100,
  p_offset       integer DEFAULT 0
)
RETURNS TABLE(
  id          uuid,
  parent_id   uuid,
  entry_type  text,
  content     text,
  metadata    jsonb,
  created_by  uuid,
  created_at  timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_ok boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  -- Only PUBLIC content nodes are readable through this generic surface.
  -- table aliases: this function's RETURNS TABLE has an OUT column `id`, so the
  -- subject-check WHERE must qualify the table column to avoid ambiguity.
  CASE p_subject_type
    WHEN 'news_article' THEN
      SELECT true INTO v_ok FROM public.news_articles na WHERE na.id = p_subject_id AND na.is_published;
    WHEN 'web_page' THEN
      -- draft web_pages are admin-only; the public read surface must not expose a draft's
      -- thread even to a member who guesses its UUID. Mirrors news_article -> is_published.
      SELECT true INTO v_ok FROM public.web_pages wp     WHERE wp.id = p_subject_id AND wp.status = 'published';
    ELSE
      v_ok := false;
  END CASE;
  IF NOT COALESCE(v_ok, false) THEN
    RAISE EXCEPTION 'Subject not found or not publicly discussable: % %', p_subject_type, p_subject_id;
  END IF;

  RETURN QUERY
    SELECT e.id, e.parent_id, e.entry_type, e.content, e.metadata, e.created_by, e.created_at
    FROM public.story_entries e
    WHERE e.subject_type = p_subject_type
      AND e.subject_id   = p_subject_id
      AND e.status       = 'visible'
      AND e.is_internal  = false
    ORDER BY e.created_at ASC
    LIMIT  GREATEST(p_limit, 0)
    OFFSET GREATEST(p_offset, 0);
END;
$$;

REVOKE ALL ON FUNCTION public.get_discussion_entries(text, uuid, integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_discussion_entries(text, uuid, integer, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_discussion_entries(text, uuid, integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_distribution_protocols_for_product.sql
-- -----------------------------------------------------------------------------

-- Function: get_distribution_protocols_for_product
-- Returns available distribution protocols for a specific product
-- Security: Public read (no sensitive data)
-- Created: 2026-01-17

CREATE OR REPLACE FUNCTION public.get_distribution_protocols_for_product(
  p_product_id uuid
)
RETURNS TABLE (
  id uuid,
  name text,
  description text,
  dose_amount numeric,
  dose_unit text,
  doses_per_day int,
  dose_timing text[],
  arm_code text,
  study_id uuid,
  study_name text,
  is_active boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
BEGIN
  RETURN QUERY
  SELECT 
    dp.id,
    dp.name,
    dp.description,
    dp.dose_amount,
    dp.dose_unit,
    dp.doses_per_day,
    dp.dose_timing,
    dp.arm_code,
    dp.study_id,
    COALESCE(s.name, '') as study_name,
    dp.is_active
  FROM distribution_protocols dp
  LEFT JOIN studies s ON s.id = dp.study_id
  WHERE dp.product_id = p_product_id 
    AND dp.is_active = true
  ORDER BY dp.name;
END;
$$;

-- Permissions - public access since this is just protocol info, no sensitive data
REVOKE ALL ON FUNCTION public.get_distribution_protocols_for_product(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_distribution_protocols_for_product(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_distribution_protocols_for_product(uuid) TO anon;

COMMENT ON FUNCTION public.get_distribution_protocols_for_product(uuid) IS 
'Returns available distribution protocols for a specific product. No sensitive data, public access.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_document_detail.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'record_detail' block: one document's extracted fields from the
-- local-ingest evidence silo (li_source_registry.fields). SECURITY INVOKER — the
-- li_source_registry RLS decides visibility.
--
-- Scoped by p_params->>'doc_slug' (or 'document_id' as an alias — the workbench
-- passes whatever the register row's `id` carried, which is doc_slug). Reads the
-- authoritative fields jsonb whose per-field shape is the ingest artifact field:
--   { value, raw, confidence, status, source_span:{char_start,char_end,page} }.
-- Maps each to a RecordField {key,label_key,value,state,confidence,source_ref}.
-- fields_pending_review ({ <key>: <status> }) marks which keys still await a human;
-- a pending key overrides the field state to needs_review so the operator sees it.
--
-- Contract: (jsonb) -> jsonb {data:{record_id,badges,fields,quote?}, provenance}.

-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, 2026-09-27): `freshness_at` = nejnovější čas
-- univerza bloku, spočtený ze STEJNÝCH řádků jako hodnota. Pořadí zdrojů času: čas ze zdroje
-- (u Money `source_modified_at`, až bude úplný; u jízd/událostí `occurred_at`) › příchod verze
-- dokladu (`created_at`). NE `ingested_at`/`updated_at` — ty přepisuje KAŽDÝ import (naměřeno
-- 2026-09-27: 813 smluv = jediný čas), takže by lhaly jako faktury zamrzlé na exportu ze 6. 8.
-- Hranice `created_at`: backfill starých dokladů má čas dnešní — pravda o příchodu, ne o obsahu.
-- Prázdné univerzum → `trace_id` nese `:no_data` a čas je jen záloha `coalesce(…, now())`.
-- Stav linky (běží/neběží) sem NEPATŘÍ — je to jiný signál.
create or replace function public.get_document_detail(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with doc as (
    select r.*
    from public.li_source_registry r
    where r.doc_slug = coalesce(p_params->>'doc_slug', p_params->>'document_id')
    limit 1
  ),
  flds as (
    select jsonb_agg(
             jsonb_build_object(
               'key',        f.key,
               'label_key',  'app.wb.field.' || f.key,
               'value',      coalesce(f.value->>'value', f.value #>> '{}'),
               'state',      lower(coalesce(
                               -- a still-pending field wins over its stored status
                               doc.fields_pending_review->>f.key,
                               f.value->>'status',
                               'needs_review')),
               'confidence', (f.value->>'confidence')::numeric,
               'source_ref', case when f.value ? 'source_span' then f.value->'source_span' else null end
             )
             order by f.key
           ) as arr
    from doc, lateral jsonb_each(coalesce(doc.fields, '{}'::jsonb)) as f
    where jsonb_typeof(doc.fields) = 'object'
  )
  -- A record_detail block asks for ONE document, so an absent or unknown slug is
  -- an ordinary state, not a failure. Returning NULL made get_block_data raise
  -- "data rpc returned null", which reads like a broken producer; the block now
  -- degrades the same way every other block does — shaped, empty, and honest
  -- about why.
  select coalesce(
    (select jsonb_build_object(
    'data', jsonb_build_object(
      'record_id', doc.doc_slug,
      'badges', jsonb_build_array(
        'app.wb.doctype.' || doc.doc_type,
        case when doc.status = 'AUTO_PASS' then 'app.wb.state.auto_pass' else 'app.wb.state.needs_review' end
      ),
      'fields', coalesce(flds.arr, '[]'::jsonb),
      -- ⭐ ŘÁDKOVÉ POLOŽKY (doplněno 2026-08-05). Bez nich detail faktury
      -- odpovídal jen „kolik", nikdy „za co" — a u pohledávky je právě to
      -- druhé důvod, proč se na doklad kliká. Položky nese registr jako pole
      -- validovaných řádků; posílají se, jak jsou, aby tu nevzniklo další
      -- místo se znalostí toho, co zdroj obsahuje.
      'line_items', coalesce(doc.line_items, '[]'::jsonb),
      'lines_pending', coalesce(doc.lines_pending_review, 0),
      -- Co dokladu chybí do úplnosti — neúplný doklad se má poznat, ne mlčet.
      'missing', to_jsonb(coalesce(doc.missing_required, '{}'::text[])),
      -- ⭐ ZDROJ VERBATIM jen na vyžádání (`include_source=true`): původní záznam
      -- z ERP tak, jak přišel. Slouží k doložení „odkud to číslo je" a k revizi
      -- výkladu proti zdroji. Ve výchozím stavu se NEPOSÍLÁ — je to nejtučnější
      -- část odpovědi a k vykreslení detailu není potřeba.
      'source_record', case when coalesce(p_params->>'include_source', '') = 'true'
                            then doc.raw_data->'source_record' end,
      'quote', doc.filename
    ),
    'provenance', jsonb_build_object(
      'source_slug',  coalesce(doc.ingest_source_slug, 'li-source-registry'),
      'freshness_at', to_char(doc.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'doc-detail:' || doc.doc_slug
    )
  )
  from doc left join flds on true),
    jsonb_build_object(
      'data', jsonb_build_object('record_id', null, 'badges', '[]'::jsonb, 'fields', '[]'::jsonb),
      -- Kontraktní tvar i v prázdné větvi: `error` navíc a chybějící
      -- freshness_at porušovaly schéma obálky, takže klient blok CELÝ zahodil
      -- místo aby ukázal prázdno. Důvod prázdna (chybějící param, neznámý slug,
      -- neviditelný dokument) NENÍ provenance — a rozlišovat ho pro volajícího
      -- by navíc prozradilo existenci dokumentu, který nesmí vidět.
      'provenance', jsonb_build_object(
        'source_slug',  'li-source-registry',
        'trace_id',     'doc-detail:not_found',
        'freshness_at', now())));
$$;

revoke all on function public.get_document_detail(jsonb) from public, anon;
grant execute on function public.get_document_detail(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_document_lines.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_document_lines
-- Popis: Řádkové POLOŽKY jednoho dokladu jako tabulka — odpověď na „ZA CO".
--
-- ⭐ PROČ (majitel 2026-09-29, náčrtek „Smlouvy a nájmy"): u faktury chce po
-- prokliku vidět „detail POLOŽEK, ne co je ke schválení". Detail dokladu
-- (get_document_detail) je revizní — pole se stavy a jistotou nahoře, položky
-- surově pod nimi, čísla jako text, bez třídy. Tahle čtečka vydá TYTÉŽ položky
-- (li_source_registry.line_items, žádná kopie) jako tabulku: text, množství,
-- jednotka, jednotková cena, celkem a TŘÍDA (nájem / energie / služby …).
--
-- Třídy se NEKOPÍRUJÍ: `tridy_z_bloku` jmenuje blok, jehož `source_params.classes`
-- je katalog (kniha faktur `sm_breakdown`) — jeden katalog pro knihu i detail,
-- aby položka nebyla v knize „energie" a v detailu „nájem". Lze poslat i přímo
-- `classes` (přednost). Bez katalogu se třída neukáže vůbec (ne „neurčeno").
--
-- Pravdivost: položky dodává zdroj; starší exporty Money je nemají (naměřeno
-- riq 2026-09-29: 6 538 z 25 317 faktur). Prázdná tabulka proto nese v provenienci
-- DŮVOD (coverage label), ne ticho. U faktury s položkami provenience porovná
-- součet položek se základem bez DPH z hlavičky: přesně / do 1 Kč (zaokrouhlení) /
-- = celkem s DPH (položky jsou hrubé) / nesedí. DPH po položkách zdroj nedodává.
--
-- SECURITY INVOKER: viditelnost dokladu rozhoduje RLS li_source_registry (jako
-- get_document_detail). Scope: p_params->>'doc_slug' (alias 'document_id').
-- Contract: (jsonb) -> jsonb {data:{columns,rows}, provenance}.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_document_lines(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
  with doc as (
    select r.doc_slug, r.doc_type, r.line_items, r.fields, r.created_at, r.ingest_source_slug
      from public.li_source_registry r
     where r.doc_slug = coalesce(p_params->>'doc_slug', p_params->>'document_id')
     limit 1
  ),
  katalog as (
    select coalesce(
             case when jsonb_typeof(p_params->'classes') = 'array' then p_params->'classes' end,
             (select b.source_params->'classes'
                from public.surface_blocks b
               where b.block_slug = p_params->>'tridy_z_bloku' and b.is_active
                 and jsonb_typeof(b.source_params->'classes') = 'array'
               limit 1)) as classes
  ),
  num as (
    -- pole položky je objekt s provenancí ({value, raw, …}); číslo jen když je číslo
    select li.ord,
           li.item->'fields'->'item_name'->>'value' as nazev,
           case when (li.item->'fields'->'quantity'->>'value')   ~ '^-?[0-9]+(\.[0-9]+)?$'
                then (li.item->'fields'->'quantity'->>'value')::numeric end   as mnozstvi,
           nullif(li.item->'fields'->'unit'->>'value', '')                     as jednotka,
           case when (li.item->'fields'->'unit_price'->>'value') ~ '^-?[0-9]+(\.[0-9]+)?$'
                then (li.item->'fields'->'unit_price'->>'value')::numeric end as cena,
           case when (li.item->'fields'->'line_total'->>'value') ~ '^-?[0-9]+(\.[0-9]+)?$'
                then (li.item->'fields'->'line_total'->>'value')::numeric end as celkem
      from doc
      cross join lateral jsonb_array_elements(coalesce(doc.line_items, '[]'::jsonb))
           with ordinality as li(item, ord)
  ),
  zatridene as (
    select n.*,
           case when (select classes from katalog) is null then null
                else coalesce((
                  select c->>'key'
                    from katalog, jsonb_array_elements(katalog.classes) with ordinality t(c, o)
                   where n.nazev ~* (c->>'pattern')
                   order by t.o
                   limit 1), '?') end as trida
      from num n
  ),
  hlava as (
    select case when (doc.fields->'amount_without_vat'->>'value') ~ '^-?[0-9]+(\.[0-9]+)?$'
                then (doc.fields->'amount_without_vat'->>'value')::numeric end as zaklad,
           case when (doc.fields->'total_amount'->>'value') ~ '^-?[0-9]+(\.[0-9]+)?$'
                then (doc.fields->'total_amount'->>'value')::numeric end as celkem
      from doc
  ),
  soucet as (
    select sum(celkem) as s from num
  )
  select coalesce(
    (select jsonb_build_object(
      'data', jsonb_build_object(
        'columns', (
          select jsonb_agg(c order by o)
            from (values
              (1, jsonb_build_object('key','poradi',   'label_key','app.cols.line_no',    'align','right')),
              (2, jsonb_build_object('key','polozka',  'label_key','app.cols.item_name')),
              (3, jsonb_build_object('key','mnozstvi', 'label_key','app.cols.quantity',   'align','right')),
              (4, jsonb_build_object('key','jednotka', 'label_key','app.cols.unit')),
              (5, jsonb_build_object('key','cena',     'label_key','app.cols.unit_price', 'align','right')),
              (6, jsonb_build_object('key','celkem',   'label_key','app.cols.line_total', 'align','right')),
              -- třída jako ŠTÍTEK (i18n klíč) — jen když je katalog
              (7, case when (select classes from katalog) is not null
                       then jsonb_build_object('key','trida','label_key','app.cols.class','value_keys',true) end)
            ) v(o, c)
           where c is not null),
        'rows', coalesce((
          select jsonb_agg(jsonb_build_object(
                   'poradi',   z.ord::text,
                   'polozka',  coalesce(z.nazev, '—'),
                   'mnozstvi', case when z.mnozstvi is null then '—'
                                    when z.mnozstvi = round(z.mnozstvi) then public.fmt_num_cs(z.mnozstvi, 0)
                                    -- desetinné množství bez koncových nul (2,5 ne 2,500)
                                    else regexp_replace(public.fmt_num_cs(z.mnozstvi, 3), ',?0+$', '') end,
                   'jednotka', coalesce(z.jednotka, ''),
                   'cena',     public.fmt_num_cs(z.cena, 2),
                   'celkem',   public.fmt_num_cs(z.celkem, 2),
                   'trida',    case when z.trida is null then null
                                    when z.trida = '?' then 'app.cols.class.none'
                                    else 'app.cols.class.' || z.trida end)
                 order by z.ord)
            from zatridene z), '[]'::jsonb)
      ),
      'provenance', jsonb_build_object(
        'source_slug',  coalesce(doc.ingest_source_slug, 'li-source-registry'),
        'freshness_at', to_char(doc.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'trace_id',     'doc-lines:' || doc.doc_slug,
        -- Pokrytí: n = položek, m = položek s částkou; label říká, co to znamená.
        'coverage', jsonb_build_object(
          'n', (select count(*) from num),
          'm', (select count(*) from num where celkem is not null),
          -- ⛔ Naměřeno na riq 2026-09-29 (6 538 faktur s položkami): 3 063 přesně,
          -- 2 375 do 1 Kč (haléřové zaokrouhlení, průměr 0,44 Kč), 190 položky VČETNĚ
          -- DPH (součet = celkem), 862 skutečně jinak. „Nesedí" jen pro ten poslední
          -- případ — zaokrouhlení ani hrubé položky nejsou chyba dokladu.
          'label_key', case
            when (select count(*) from num) = 0 then 'app.prov.coverage.lines_missing'
            when (select zaklad from hlava) is null
              or (select count(*) from num where celkem is null) > 0 then 'app.prov.coverage.lines_unchecked'
            when abs((select s from soucet) - (select zaklad from hlava)) <= 0.01 then 'app.prov.coverage.lines_sum_ok'
            when abs((select s from soucet) - (select zaklad from hlava)) <= 1.00 then 'app.prov.coverage.lines_sum_rounding'
            when (select celkem from hlava) is not null
             and abs((select s from soucet) - (select celkem from hlava)) <= 1.00 then 'app.prov.coverage.lines_sum_gross'
            else 'app.prov.coverage.lines_sum_mismatch' end)
      )
    )
    from doc),
    jsonb_build_object(
      'data', jsonb_build_object('columns', '[]'::jsonb, 'rows', '[]'::jsonb),
      'provenance', jsonb_build_object(
        'source_slug',  'li-source-registry',
        'trace_id',     'doc-lines:not_found',
        'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'))));
$$;

REVOKE ALL ON FUNCTION public.get_document_lines(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_document_lines(jsonb) TO authenticated, service_role;


