-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_drift_remediation_rate.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_drift_remediation_rate
-- Popis: Vrací počet auto-remediated drift incidentů per app v posledních X minutách.
--        Používáno pro rate-limit check ("max 5 auto-remediations per hour"
--        z DRIFT_OBSERVER.md §5.2). Pokud rate překročí threshold, eskalace na approval.
-- Volá: WF_DRIFT_OBSERVER před auto-remediation
-- Auth: any authenticated user
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_drift_remediation_rate(
  p_app_uuid text,
  p_window_minutes int DEFAULT 60
)
RETURNS int
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_count int := 0;
  v_caller uuid;
BEGIN
  -- Auth check: require authenticated user OR service_role
  v_caller := auth.uid();
  IF v_caller IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role' THEN
    RAISE EXCEPTION 'Unauthorized: authentication required';
  END IF;

  SELECT count(*) INTO v_count
  FROM public.drift_state
  WHERE app_uuid = p_app_uuid
    AND remediation = 'auto'
    AND resolved_at > now() - (p_window_minutes || ' minutes')::interval;

  RETURN v_count;
END;
$$;

REVOKE ALL ON FUNCTION public.get_drift_remediation_rate(text, int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_drift_remediation_rate(text, int) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_drift_remediation_rate(text, int) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_due_reminders_for_notification.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_due_reminders_for_notification
-- Arguments: p_current_time text, p_current_dow integer, p_current_date date
-- Description: Returns reminders due for notification with FCM tokens.
-- Security: SECURITY DEFINER

CREATE OR REPLACE FUNCTION public.get_due_reminders_for_notification(
  p_current_time text,
  p_current_dow integer,
  p_current_date date
)
 RETURNS TABLE(
  user_id uuid,
  reminder_id uuid,
  reminder_title text,
  reminder_type text,
  points_per_completion integer,
  fcm_tokens text[]
)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  WITH candidate_reminders AS (
    SELECT r.*
    FROM user_reminders r
    WHERE r.is_active = true
      AND r.notification_enabled = true
      AND (r.end_date IS NULL OR r.end_date >= p_current_date)
      AND r.time_of_day >= (p_current_time || ':00')::time
      AND r.time_of_day < (p_current_time || ':59')::time
      AND (
        r.frequency = 'daily'
        OR (
          (r.frequency = 'weekly' OR r.frequency = 'custom')
          AND p_current_dow = ANY(r.custom_frequency_days)
        )
        -- biweekly + monthly are accepted by create_user_reminder and scheduled by
        -- calculate_next_reminder_time, but were absent here, so their notifications
        -- never fired. Mirror the engine's "due today" test exactly.
        OR (
          r.frequency = 'biweekly'
          AND ((p_current_date - r.start_date) % 14) = 0
        )
        OR (
          r.frequency = 'monthly'
          AND EXTRACT(DAY FROM p_current_date) = EXTRACT(DAY FROM r.start_date)
        )
      )
  ),
  uncompleted AS (
    SELECT r.*
    FROM candidate_reminders r
    WHERE NOT EXISTS (
      SELECT 1
      FROM reminder_completions rc
      WHERE rc.reminder_id = r.id
        AND rc.completed_at >= (p_current_date::text || 'T00:00:00')::timestamptz
    )
  )
  SELECT
    u.user_id,
    u.id AS reminder_id,
    u.title AS reminder_title,
    u.reminder_type,
    u.points_per_completion,
    COALESCE(array_remove(array_agg(ms.fcm_token), NULL), ARRAY[]::text[]) AS fcm_tokens
  FROM uncompleted u
  LEFT JOIN mobile_sessions ms ON ms.user_id = u.user_id
  GROUP BY
    u.user_id,
    u.id,
    u.title,
    u.reminder_type,
    u.points_per_completion
  HAVING COUNT(ms.fcm_token) > 0
  ORDER BY reminder_id;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.get_due_reminders_for_notification(p_current_time text, p_current_dow integer, p_current_date date) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.get_due_reminders_for_notification(p_current_time text, p_current_dow integer, p_current_date date) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_due_reminders_for_notification(p_current_time text, p_current_dow integer, p_current_date date) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_enabled_auth_providers.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_enabled_auth_providers
-- Purpose: THE consumer seam of auth_provider_registry. Two readers:
--   1. the login surface (anonymous!) — renders external-IdP buttons; gets the
--      public shape only (no env var names, no metadata),
--   2. the Keycloak admin-API reconciler (service_role) — reads the table
--      directly for the full row incl. client_secret_env_var.
-- This RPC serves reader 1: enabled rows, instance-scoped, ordered by priority.
-- SECURITY DEFINER so anon can enumerate ONLY the deliberate public shape
-- (direct table read stays authenticated+scoped via RLS).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_enabled_auth_providers()
RETURNS TABLE (
  slug         text,
  display_name text,
  protocol     text,
  issuer_url   text,
  priority     int,
  button       jsonb   -- display hints subset of config (icon, label overrides)
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT r.slug, r.display_name, r.protocol, r.issuer_url, r.priority,
         COALESCE(r.config->'button', '{}'::jsonb) AS button
    FROM public.auth_provider_registry r
   WHERE r.is_enabled
     AND (
       r.scoped_to_instance_id IS NULL
       OR r.scoped_to_instance_id = NULLIF(current_setting('aisha.instance_id', true), '')::uuid
     )
   ORDER BY r.priority, r.slug;
$$;

COMMENT ON FUNCTION public.get_enabled_auth_providers() IS
  'Login-surface enumeration of enabled IdPs (public shape only — no secrets, no env var names). The Keycloak reconciler reads the table directly as service_role.';

REVOKE ALL ON FUNCTION public.get_enabled_auth_providers() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_enabled_auth_providers() TO anon, authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_entry_types.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: public.get_entry_types
-- Popis: List the ACTIVE discussion post types available for a subject (the
--        composer asks "what can I post here?"). Stack universals + the
--        implementation's own types, filtered by applies_to.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT; authenticated only.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_entry_types(
  p_subject_type text DEFAULT NULL
)
RETURNS TABLE(
  entry_type      text,
  name_key        text,
  description_key text,
  metadata_schema jsonb,
  render_block    text,
  sort_order      integer
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
    SELECT d.entry_type, d.name_key, d.description_key, d.metadata_schema, d.render_block, d.sort_order
    FROM public.entry_type_definitions d
    WHERE d.is_active
      AND (
        p_subject_type IS NULL
        OR cardinality(d.applies_to) = 0
        OR p_subject_type = ANY(d.applies_to)
      )
    ORDER BY d.sort_order, d.entry_type;
END;
$$;

REVOKE ALL ON FUNCTION public.get_entry_types(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_entry_types(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_entry_types(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_evidence_findings.sql
-- -----------------------------------------------------------------------------

-- Data RPC for an 'alert_feed' block: deterministic cross-document findings from
-- the local-ingest evidence silo (li_findings) — price_mismatch, missing_counterpart,
-- date_out_of_window, missing_line_item. These are the discrepancies the ingest
-- consistency checks surface across documents. SECURITY INVOKER — li_findings RLS
-- decides visibility.
--
-- Optional filter p_params->>'severity' (high|medium|low). Ordered high→low then
-- most-recent, matching the li_list_findings read contract.
-- Contract: (jsonb) -> jsonb {data:{items[]}, provenance}.

create or replace function public.get_evidence_findings(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with items as (
    select
      f.id::text                                as id,
      f.finding                                 as finding,
      coalesce(f.severity, 'low')               as severity,
      coalesce(jsonb_array_length(f.documents), 0) as doc_count,
      f.documents,
      f.ingested_at
    from public.li_findings f
    where (p_params->>'severity' is null or f.severity = p_params->>'severity')
    order by case coalesce(f.severity, 'low')
               when 'high' then 1 when 'medium' then 2 else 3 end,
             f.ingested_at desc
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'items', coalesce(jsonb_agg(
        jsonb_build_object(
          'id', items.id,
          'title_key', 'app.wb.finding.' || items.finding,
          'severity', items.severity,
          'fields', jsonb_build_array(
            jsonb_build_object('key', 'documents', 'label_key', 'app.wb.field.documents', 'value', items.doc_count)
          ),
          'evidence', items.documents
        )
        order by case items.severity when 'high' then 1 when 'medium' then 2 else 3 end, items.id
      ), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'li-findings',
      'freshness_at', to_char(coalesce(max(items.ingested_at), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'evidence-findings'
    )
  )
  from items;
$$;

revoke all on function public.get_evidence_findings(jsonb) from public, anon;
grant execute on function public.get_evidence_findings(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_expert_rule_detail.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_expert_rule_detail
-- Arguments: p_rule_slug text
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.get_expert_rule_detail(p_rule_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule record;
  v_result jsonb;
BEGIN
  SELECT er.*, pp.display_name AS author_display_name, pp.avatar_url AS author_avatar_url,
         pp.guild_tier AS author_guild_tier, pp.guild_bio AS author_guild_bio,
         gea.slug AS expertise_area_slug, gea.name_key AS expertise_area_name_key,
         gea.icon AS expertise_area_icon
  INTO v_rule
  FROM expert_rules er
  JOIN partner_profiles pp ON pp.id = er.author_partner_id
  LEFT JOIN guild_expertise_areas gea ON gea.id = er.expertise_area_id
  WHERE er.slug = p_rule_slug
    AND (
      er.status = 'published'
      OR (er.author_partner_id IN (SELECT id FROM partner_profiles WHERE user_id = auth.uid()))
    );

  IF v_rule IS NULL THEN
    RETURN NULL;
  END IF;

  -- Log audit for rule access
  IF auth.uid() IS NOT NULL THEN
    INSERT INTO audit_journal (user_id, action, metadata)
    VALUES (auth.uid(), 'EXPERT_RULE_VIEW', jsonb_build_object(
      'area', 'knowledge',
      'severity', 'info',
      'rule_id', v_rule.id,
      'rule_slug', v_rule.slug
    ));
  END IF;

  v_result := jsonb_build_object(
    'id', v_rule.id,
    'slug', v_rule.slug,
    'title', v_rule.title,
    'summary', v_rule.summary,
    'body_markdown', v_rule.body_markdown,
    'category', v_rule.category,
    'expertise_area_slug', v_rule.expertise_area_slug,
    'expertise_area_name_key', v_rule.expertise_area_name_key,
    'expertise_area_icon', v_rule.expertise_area_icon,
    'author_partner_id', v_rule.author_partner_id,
    'author_display_name', v_rule.author_display_name,
    'author_avatar_url', v_rule.author_avatar_url,
    'author_guild_tier', v_rule.author_guild_tier,
    'ai_instructions', v_rule.ai_instructions,
    'ai_context_tags', v_rule.ai_context_tags,
    'is_verified', v_rule.is_verified,
    'version', v_rule.version,
    'subscriber_count', v_rule.subscriber_count,
    'usage_count', v_rule.usage_count,
    'rating_avg', v_rule.rating_avg,
    'rating_count', v_rule.rating_count,
    'status', v_rule.status,
    'visibility', v_rule.visibility,
    'published_at', v_rule.published_at,
    'created_at', v_rule.created_at,
    'updated_at', v_rule.updated_at,
    'documents', COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
        'id', erd.id,
        'title', erd.title,
        'description', erd.description,
        'file_path', erd.file_path,
        'file_name', erd.file_name,
        'mime_type', erd.mime_type,
        'content_markdown', erd.content_markdown,
        'document_type', erd.document_type,
        'sort_order', erd.sort_order
      ) ORDER BY erd.sort_order)
      FROM expert_rule_documents erd
      WHERE erd.rule_id = v_rule.id),
      '[]'::jsonb
    ),
    'is_subscribed', COALESCE(
      (SELECT true FROM expert_rule_subscriptions ers
       WHERE ers.rule_id = v_rule.id AND ers.user_id = auth.uid() AND ers.is_active = true),
      false
    )
  );

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_expert_rule_detail(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_expert_rule_detail(text) TO anon;
GRANT EXECUTE ON FUNCTION public.get_expert_rule_detail(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_expert_rule_detail(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_expert_rules.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_expert_rules
-- Arguments: p_category text DEFAULT NULL::text, p_expertise_slug text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_author_partner_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.get_expert_rules(p_category text DEFAULT NULL::text, p_expertise_slug text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_author_partner_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, slug text, title text, summary text, category text, expertise_area_slug text, expertise_area_name_key text, expertise_area_icon text, author_partner_id uuid, author_display_name text, author_avatar_url text, author_guild_tier text, is_verified boolean, subscriber_count integer, usage_count integer, rating_avg numeric, rating_count integer, document_count bigint, ai_context_tags text[], published_at timestamptz, created_at timestamptz)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    er.id,
    er.slug,
    er.title,
    er.summary,
    er.category::text,
    gea.slug AS expertise_area_slug,
    gea.name_key AS expertise_area_name_key,
    gea.icon AS expertise_area_icon,
    er.author_partner_id,
    pp.display_name AS author_display_name,
    pp.avatar_url AS author_avatar_url,
    pp.guild_tier::text AS author_guild_tier,
    er.is_verified,
    er.subscriber_count,
    er.usage_count,
    er.rating_avg,
    er.rating_count,
    (SELECT count(*) FROM expert_rule_documents erd WHERE erd.rule_id = er.id) AS document_count,
    er.ai_context_tags,
    er.published_at,
    er.created_at
  FROM expert_rules er
  LEFT JOIN guild_expertise_areas gea ON gea.id = er.expertise_area_id
  JOIN partner_profiles pp ON pp.id = er.author_partner_id
  WHERE er.status = 'published'
    AND (
      er.visibility = 'public'
      OR (er.visibility = 'members' AND auth.uid() IS NOT NULL)
      OR (er.visibility = 'guild' AND EXISTS (
        SELECT 1 FROM partner_profiles pp2 WHERE pp2.user_id = auth.uid()
      ))
    )
    AND (p_category IS NULL OR er.category::text = p_category)
    AND (p_expertise_slug IS NULL OR gea.slug = p_expertise_slug)
    AND (p_author_partner_id IS NULL OR er.author_partner_id = p_author_partner_id)
    AND (p_search IS NULL OR p_search = '' OR
      er.title ILIKE '%' || p_search || '%' OR
      er.summary ILIKE '%' || p_search || '%' OR
      p_search = ANY(er.ai_context_tags)
    )
  ORDER BY er.is_verified DESC, er.rating_avg DESC NULLS LAST, er.subscriber_count DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_expert_rules(text, text, text, uuid, integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_expert_rules(text, text, text, uuid, integer, integer) TO anon;
GRANT EXECUTE ON FUNCTION public.get_expert_rules(text, text, text, uuid, integer, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_expert_rules(text, text, text, uuid, integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
