-- Function: get_featured_products_admin
-- Description: Get all featured products for admin management
-- Security: SECURITY DEFINER with admin check + audit
-- Created: 2026-02-03

CREATE OR REPLACE FUNCTION get_featured_products_admin()
RETURNS TABLE (
  id uuid,
  product_id uuid,
  product_name text,
  product_slug text,
  product_price numeric,
  badge_key text,
  title_key text,
  subtitle_key text,
  feature_keys text[],
  cta_text_key text,
  cta_url text,
  price_period_days int4,
  show_price bool,
  image_url text,
  background_gradient text,
  display_location text,
  sort_order int4,
  is_active bool,
  created_at timestamptz,
  updated_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
BEGIN
  -- Authorization check
  IF NOT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = auth.uid()
    AND role IN ('admin', 'staff')
  ) THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff role required';
  END IF;

  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'ADMIN_VIEW',
    jsonb_build_object(
      'area', 'featured_products',
      'severity', 'info'
    )
  );

  RETURN QUERY
  SELECT 
    fp.id,
    fp.product_id,
    p.name AS product_name,
    p.slug AS product_slug,
    p.price AS product_price,
    fp.badge_key,
    fp.title_key,
    fp.subtitle_key,
    fp.feature_keys,
    fp.cta_text_key,
    fp.cta_url,
    fp.price_period_days,
    fp.show_price,
    fp.image_url,
    fp.background_gradient,
    fp.display_location,
    fp.sort_order,
    fp.is_active,
    fp.created_at,
    fp.updated_at
  FROM featured_products fp
  LEFT JOIN products p ON p.id = fp.product_id
  ORDER BY fp.display_location, fp.sort_order;
END;
$$;

-- Security
REVOKE ALL ON FUNCTION get_featured_products_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION get_featured_products_admin() TO authenticated;

COMMENT ON FUNCTION get_featured_products_admin() IS 'Get all featured products for admin management with audit logging';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_fleet_consumption.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'chart' block (kind='bar'): per-vehicle fuel consumption
-- (l/100 km) over the window, with average trip length as the point `note` so a
-- reader can normalise — short routes mean more cold starts and idling, hence a
-- structurally higher l/100 km, so the same number means different things at 42 km
-- and at 76 km. Points are ordered worst-first (highest consumption on top).
--
-- Reads Eurowag `trip` events off the twin substrate; a trip counts only when it
-- reports a plausible l/100 km (the plugin already dropped the −1 sentinel and the
-- physically-impossible short-trip spikes before the event was recorded).
-- Window is p_params->>'days' (default 7). SECURITY INVOKER → RLS on twin_* fails
-- closed. Contract: (jsonb) -> jsonb {data:{kind,unit_key,points[]}, provenance}.

create or replace function public.get_fleet_consumption(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with win as (
    select now() - make_interval(days => coalesce((p_params->>'days')::int, 7)) as since
  ),
  per as (
    select
      t.label,
      round(avg((e.attrs->>'consumption_l_100km')::numeric), 1) as l100,
      round(avg((e.attrs->>'distance_km')::numeric))            as avg_km
    from public.twin_events e
    join public.twin_entities t on t.id = e.twin_id
    where e.event_type = 'trip'
      and e.occurred_at >= (select since from win)
      and e.attrs->>'consumption_l_100km' ~ '^[0-9]+(\.[0-9]+)?$'
    group by t.label
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'kind', 'bar',
      'unit_key', 'app.fleet.unit.l100km',
      'points', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'label', per.label,
            'value', per.l100,
            -- `note` = Ø délka trasy (km) — čím se spotřeba normalizuje.
            'note',  coalesce(per.avg_km::text, '')
          ) order by per.l100 desc nulls last
        ) from per
      ), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'eurowag-telematics',
      'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'fleet-consumption'
    )
  );
$$;

revoke all on function public.get_fleet_consumption(jsonb) from public, anon;
grant execute on function public.get_fleet_consumption(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_fleet_findings.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'findings' block: „co vyřídit" — deterministic fleet findings
-- DERIVED from the twin substrate (not a passthrough read). Each finding carries a
-- catalogue rule id as title_key (i18n, never a literal) + severity + grounded
-- `fields` (the numbers that fired it). Two rules today, both computable from what
-- the connectors already record:
--   • unassigned_driver — km driven on trips with no resolved driver (related twin
--     null), summed per vehicle over a threshold. A compliance gap: a card must be
--     pulled from the unit, or the ride has no legal driver.
--   • speeding — overspeed segments from Webdispečink (wd_overspeed) above the
--     limit, per vehicle, WITH the location of the fastest one. For 12t+ the
--     limiter should hold 90; repeated overspeed is a workshop item, not a talk.
-- More rules (missing-from-fleet, tacho-silent) need context this reader does not
-- yet have and are left out rather than faked.
--
-- SECURITY INVOKER → RLS on twin_* fails closed. Window p_params->>'days' (7);
-- p_params->>'speed_limit_kmh' (100), p_params->>'min_unassigned_km' (100).
-- Contract: (jsonb) -> jsonb {data:{items[]}, provenance}.

-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, 2026-09-27): `freshness_at` = nejnovější čas
-- univerza bloku, spočtený ze STEJNÝCH řádků jako hodnota. Pořadí zdrojů času: čas ze zdroje
-- (u Money `source_modified_at`, až bude úplný; u jízd/událostí `occurred_at`) › příchod verze
-- dokladu (`created_at`). NE `ingested_at`/`updated_at` — ty přepisuje KAŽDÝ import (naměřeno
-- 2026-09-27: 813 smluv = jediný čas), takže by lhaly jako faktury zamrzlé na exportu ze 6. 8.
-- Hranice `created_at`: backfill starých dokladů má čas dnešní — pravda o příchodu, ne o obsahu.
-- Prázdné univerzum → `trace_id` nese `:no_data` a čas je jen záloha `coalesce(…, now())`.
-- Stav linky (běží/neběží) sem NEPATŘÍ — je to jiný signál.
create or replace function public.get_fleet_findings(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with p as (
    select coalesce((p_params->>'days')::int, 7)                       as days,
           -- 12t+ tahače: omezovač drží 90, cokoli výš je porušení.
           coalesce((p_params->>'speed_limit_kmh')::numeric, 90)       as speed_limit,
           coalesce((p_params->>'min_unassigned_km')::numeric, 100)    as min_km
  ),
  win as (select now() - make_interval(days => (select days from p)) as since),
  cerstvost as (
    select greatest(
      (select max(e.occurred_at) from public.twin_events e
        where e.event_type = 'trip' and e.occurred_at >= (select since from win)),
      (select max(o.time_from) from public.wd_overspeed o
        where o.time_from >= (select since from win))) as fresh
  ),
  unassigned as (
    select t.id, t.label, sum((e.attrs->>'distance_km')::numeric) as km
    from public.twin_events e
    join public.twin_entities t on t.id = e.twin_id
    where e.event_type = 'trip'
      and e.occurred_at >= (select since from win)
      and e.related_twin_id is null
      and e.attrs->>'distance_km' ~ '^[0-9]+(\.[0-9]+)?$'
    group by t.id, t.label
    having sum((e.attrs->>'distance_km')::numeric) >= (select min_km from p)
  ),
  -- Překročení rychlosti z Webdispečinku (wd_overspeed) — narozdíl od dopočtu
  -- z telematiky nese POLOHU, čas i řidiče. Vrací nejrychlejší úsek jako místo.
  speeding as (
    select
      v.wd_car_id as id,
      v.identifier as label,
      count(*)     as cnt,
      max(o.max_speed_kmh) as max_speed,
      (array_agg(
         round(o.lat, 4)::text || ', ' || round(o.lon, 4)::text
         order by o.max_speed_kmh desc
       ) filter (where o.lat is not null and o.lon is not null))[1] as top_loc
    from public.wd_overspeed o
    join public.wd_vehicles v on v.wd_car_id = o.wd_car_id
    where o.time_from >= (select since from win)
      and o.max_speed_kmh > (select speed_limit from p)
    group by v.wd_car_id, v.identifier
  ),
  items as (
    select 'unassigned:' || id::text as id,
           'app.fleet.finding.unassigned_driver'    as title_key,
           'high'                                    as severity,
           jsonb_build_array(
             jsonb_build_object('key','vehicle','label_key','app.fleet.col.vehicle',        'value', label),
             jsonb_build_object('key','km',     'label_key','app.fleet.col.unassigned_km',  'value', round(km))
           )                                         as fields
    from unassigned
    union all
    select 'speeding:' || id::text,
           'app.fleet.finding.speeding',
           'medium',
           jsonb_build_array(
             jsonb_build_object('key','vehicle',  'label_key','app.fleet.col.vehicle',   'value', label),
             jsonb_build_object('key','count',    'label_key','app.fleet.col.count',     'value', cnt),
             jsonb_build_object('key','max_speed','label_key','app.fleet.col.max_speed', 'value', round(max_speed)),
             jsonb_build_object('key','location', 'label_key','app.fleet.col.location',  'value', top_loc)
           )
    from speeding
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'items', coalesce((
        select jsonb_agg(
          jsonb_build_object('id', id, 'title_key', title_key, 'severity', severity, 'fields', fields)
          order by case severity when 'high' then 1 when 'medium' then 2 else 3 end, id
        ) from items
      ), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'webdispecink-fleet+twin-core',
      'freshness_at', to_char(coalesce((select fresh from cerstvost), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'fleet-findings'
                      || case when (select fresh from cerstvost) is null then ':no_data' else '' end
    )
  );
$$;

revoke all on function public.get_fleet_findings(jsonb) from public, anon;
grant execute on function public.get_fleet_findings(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_fleet_fuel_balance.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'table' block: the fuel balance per vehicle over the window —
--   natankováno (AVP `fueling`.liters) − spotřeba (Eurowag `trip`.consumption_l)
--   = Δ nádrž (kolik za týden v nádrži přibylo/ubylo)
-- with the last measured tank level as `sonda` (Eurowag `vehicle_state`.fuel_level_l,
-- populated only where the vehicle has a working CAN/probe — null otherwise, which
-- the renderer draws as '—', NOT as 0).
--
-- The Δ is why a naive "dispensed ≠ consumed" alarm is wrong: diesel goes into a
-- buffer stock in the tank, not into a leak. Only vehicles with fuelling OR trips
-- in the window appear. Reads three event types off the twin substrate; SECURITY
-- INVOKER → RLS on twin_* fails closed. Window is p_params->>'days' (default 7).
-- Contract: (jsonb) -> jsonb {data:{columns[],row_kind,rows[]}, provenance}.

create or replace function public.get_fleet_fuel_balance(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with win as (
    select now() - make_interval(days => coalesce((p_params->>'days')::int, 7)) as since
  ),
  fuel as (
    select twin_id, sum((attrs->>'liters')::numeric) as tanked
    from public.twin_events
    where event_type = 'fueling' and occurred_at >= (select since from win)
      and attrs->>'liters' ~ '^[0-9]+(\.[0-9]+)?$'
    group by twin_id
  ),
  cons as (
    select twin_id, sum((attrs->>'consumption_l')::numeric) as used
    from public.twin_events
    where event_type = 'trip' and occurred_at >= (select since from win)
      and attrs->>'consumption_l' ~ '^[0-9]+(\.[0-9]+)?$'
    group by twin_id
  ),
  sonda as (
    select distinct on (twin_id) twin_id,
      case when attrs->>'fuel_level_l' ~ '^[0-9]+(\.[0-9]+)?$' then (attrs->>'fuel_level_l')::numeric end as level
    from public.twin_events
    where event_type = 'vehicle_state'
    order by twin_id, occurred_at desc
  ),
  reg as (
    select
      t.id, t.label,
      coalesce(f.tanked, 0) as tanked,
      coalesce(c.used, 0)   as used,
      coalesce(f.tanked, 0) - coalesce(c.used, 0) as delta,
      s.level
    from public.twin_entities t
    left join fuel  f on f.twin_id = t.id
    left join cons  c on c.twin_id = t.id
    left join sonda s on s.twin_id = t.id
    where t.entity_type = 'vehicle'
      and (f.tanked is not null or c.used is not null)
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'row_kind', 'twin',
      'columns', jsonb_build_array(
        jsonb_build_object('key','label', 'label_key','app.fleet.col.vehicle', 'align','left'),
        jsonb_build_object('key','tanked','label_key','app.fleet.col.tanked',  'align','right'),
        jsonb_build_object('key','used',  'label_key','app.fleet.col.used',    'align','right'),
        jsonb_build_object('key','delta', 'label_key','app.fleet.col.delta',   'align','right'),
        jsonb_build_object('key','sonda', 'label_key','app.fleet.col.sonda',   'align','right')
      ),
      'rows', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id',     reg.id::text,
            'label',  reg.label,
            'tanked', round(reg.tanked),
            'used',   round(reg.used),
            'delta',  round(reg.delta),
            'sonda',  reg.level  -- null = neměřeno (renderer kreslí '—')
          ) order by reg.delta desc nulls last
        ) from reg
      ), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'avp-portal+eurowag-telematics',
      'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'fleet-fuel-balance'
    )
  );
$$;

revoke all on function public.get_fleet_fuel_balance(jsonb) from public, anon;
grant execute on function public.get_fleet_fuel_balance(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_fleet_kpi.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'kpi_tile' block: one headline figure for the fleet console
-- (surface `vozovy_park`), over the twin substrate the telematics connectors write.
-- The metric is chosen by p_params->>'metric' (seeded per block via source_params):
--   'km_week'         — kilometres driven in the window (Eurowag `trip`.distance_km)
--   'consumption_avg' — mean l/100 km over trips that report it (short-trip noise
--                       already filtered by the plugin before it becomes an event)
--   'diesel_week'     — litres dispensed in the window (AVP `fueling`.liters)
--   'active_vehicles' — distinct vehicles with a trip in the window
--   'tonnage_week' / 'exported_value' / 'invoiced_value' — Money-backed (tonnage,
--                       Kč). These land as DOCUMENTS (document_registry: delivery_note
--                       / invoice), NOT on the twin lane, and their extracted weight/
--                       price fields are not wired yet — so the metric is NEMĚŘENO
--                       (null → the tile shows '—'), never a fabricated 0.
-- Window is p_params->>'days' (default 7 — a week, matching the report the view grew from).
-- SECURITY INVOKER → RLS on twin_* fails closed (non-staff get an empty figure, not
-- an error), same doctrine as get_document_digest / get_twin_register.
-- Contract: (jsonb) -> jsonb {data:{value,unit_key,state}, provenance}.
--
-- `value = null` means NEMĚŘENO — the renderer draws '—'. A 0 would assert a
-- measurement that did not happen; until the sources are active and events flow,
-- the twin metrics are legitimately null too.

create or replace function public.get_fleet_kpi(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with p as (
    select coalesce(nullif(p_params->>'metric',''), 'km_week') as m,
           coalesce((p_params->>'days')::int, 7)               as days
  ),
  win as (select now() - make_interval(days => (select days from p)) as since),
  trips as (
    select e.twin_id, e.attrs
    from public.twin_events e
    where e.event_type = 'trip' and e.occurred_at >= (select since from win)
  ),
  fuelings as (
    select e.attrs
    from public.twin_events e
    where e.event_type = 'fueling' and e.occurred_at >= (select since from win)
  ),
  v as (
    select case (select m from p)
      when 'km_week' then
        (select sum((attrs->>'distance_km')::numeric)
           from trips where attrs->>'distance_km' ~ '^-?[0-9]+(\.[0-9]+)?$')
      when 'consumption_avg' then
        (select round(avg((attrs->>'consumption_l_100km')::numeric), 1)
           from trips where attrs->>'consumption_l_100km' ~ '^-?[0-9]+(\.[0-9]+)?$')
      when 'diesel_week' then
        (select sum((attrs->>'liters')::numeric)
           from fuelings where attrs->>'liters' ~ '^-?[0-9]+(\.[0-9]+)?$')
      when 'active_vehicles' then
        (select count(distinct twin_id)::numeric from trips)
      -- Money (tuny/Kč) — čeká na extrakci dodacích listů/faktur; NEMĚŘENO.
      else null
    end as value
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'value', (select value from v),
      'unit_key', case (select m from p)
        when 'km_week'         then 'app.fleet.unit.km'
        when 'consumption_avg' then 'app.fleet.unit.l100km'
        when 'diesel_week'     then 'app.fleet.unit.l'
        when 'active_vehicles' then 'app.fleet.unit.vehicles'
        when 'tonnage_week'    then 'app.fleet.unit.t'
        else 'app.fleet.unit.czk'
      end,
      'state', 'ok'
    ),
    'provenance', jsonb_build_object(
      'source_slug',  case (select m from p)
                        when 'diesel_week' then 'avp-portal'
                        when 'tonnage_week' then 'money-s5'
                        when 'exported_value' then 'money-s5'
                        when 'invoiced_value' then 'money-s5'
                        else 'eurowag-telematics' end,
      'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'fleet-kpi:' || (select m from p)
    )
  );
$$;

revoke all on function public.get_fleet_kpi(jsonb) from public, anon;
grant execute on function public.get_fleet_kpi(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_fleet_parked.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'table' block: odstavená vozidla — vehicles with no trip in the
-- idle window (default 14 days). Report mentions them in prose; this makes the
-- standing decision an evidenced row (last activity + days parked), so leasing/
-- insurance carried without revenue is visible, not narrated.
--
-- Reads twin_entities (active vehicles) LEFT JOIN their last `trip` event. A
-- vehicle with no trip at all, or none since the cutoff, is parked. SECURITY
-- INVOKER → RLS on twin_* fails closed. Window is p_params->>'idle_days'.
-- Contract: (jsonb) -> jsonb {data:{columns[],row_kind,rows[]}, provenance}.

create or replace function public.get_fleet_parked(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with p as (select coalesce((p_params->>'idle_days')::int, 14) as idle_days),
  last_trip as (
    select twin_id, max(occurred_at) as last_at
    from public.twin_events
    where event_type = 'trip'
    group by twin_id
  ),
  parked as (
    select
      t.id, t.label, lt.last_at,
      case when lt.last_at is null then null
           else floor(extract(epoch from (now() - lt.last_at)) / 86400)::int end as idle_days
    from public.twin_entities t
    left join last_trip lt on lt.twin_id = t.id
    where t.entity_type = 'vehicle'
      and t.status = 'active'
      and (lt.last_at is null
           or lt.last_at < now() - make_interval(days => (select idle_days from p)))
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'row_kind', 'twin',
      'columns', jsonb_build_array(
        jsonb_build_object('key','label',    'label_key','app.fleet.col.vehicle',  'align','left'),
        jsonb_build_object('key','last_trip','label_key','app.fleet.col.last_trip', 'align','left'),
        jsonb_build_object('key','idle_days','label_key','app.fleet.col.idle_days', 'align','right')
      ),
      'rows', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id',        parked.id::text,
            'label',     parked.label,
            'last_trip', case when parked.last_at is null then null
                             else to_char(parked.last_at at time zone 'UTC', 'YYYY-MM-DD') end,
            'idle_days', parked.idle_days  -- null = nikdy nejela v evidenci
          ) order by parked.idle_days desc nulls first, parked.label
        ) from parked
      ), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'twin-core',
      'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'fleet-parked'
    )
  );
$$;

revoke all on function public.get_fleet_parked(jsonb) from public, anon;
grant execute on function public.get_fleet_parked(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_fleet_worktime.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'table' block: „Dodržování jízdních dob" — driver worktime per
-- the 561/2006 tachograph, aggregated over the window. Per driver: the vehicle
-- they drove (most recent), weekly driving time (HH:MM) and a status against the
-- weekly driving limit (56 h). Reads wd_worktime (WD `_getDriverWorkTacho`,
-- seconds) joined to wd_drivers for the name.
--
-- SECURITY INVOKER → RLS on wd_* (is_admin_or_staff) fails closed. Window is
-- p_params->>'days' (default 7 — one week). Contract: (jsonb) -> jsonb
-- {data:{columns[],row_kind,rows[]}, provenance}.

create or replace function public.get_fleet_worktime(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with p as (select coalesce((p_params->>'days')::int, 7) as days),
  win as (select (now() - make_interval(days => (select days from p)))::date as since),
  agg as (
    select
      w.wd_driver_id,
      sum(coalesce(w.total_drive_seconds, 0)) as drive_s,
      (array_agg(w.car_identifikator order by w.work_date desc)
         filter (where w.car_identifikator <> ''))[1] as car
    from public.wd_worktime w
    where w.work_date >= (select since from win)
    group by w.wd_driver_id
  ),
  reg as (
    select
      a.wd_driver_id,
      nullif(trim(coalesce(d.first_name, '') || ' ' || coalesce(d.last_name, '')), '') as driver,
      a.car,
      a.drive_s,
      -- obohacení z _getStaDrivers (wd_driver_stats): služební/soukromé km + noční jízda
      s.service_km,
      s.private_km,
      s.driving_service_night_seconds as night_s
    from agg a
    left join public.wd_drivers d on d.wd_driver_id = a.wd_driver_id
    left join public.wd_driver_stats s on s.wd_driver_id = a.wd_driver_id
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'row_kind', 'driver',
      'columns', jsonb_build_array(
        jsonb_build_object('key','driver',    'label_key','app.fleet.col.driver',     'align','left'),
        jsonb_build_object('key','vehicle',   'label_key','app.fleet.col.vehicle',    'align','left'),
        jsonb_build_object('key','drive',     'label_key','app.fleet.col.driving',    'align','right'),
        jsonb_build_object('key','service_km','label_key','app.fleet.col.service_km', 'align','right'),
        jsonb_build_object('key','night',     'label_key','app.fleet.col.night',      'align','right'),
        jsonb_build_object('key','status',    'label_key','app.fleet.col.status',     'align','right')
      ),
      'rows', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id',      reg.wd_driver_id::text,
            'driver',  reg.driver,
            'vehicle', reg.car,
            -- doba řízení za okno jako HH:MM (interval > 24 h se nesmí přetočit)
            'drive',   (reg.drive_s / 3600)::int || ':' || lpad(((reg.drive_s % 3600) / 60)::int::text, 2, '0'),
            'service_km', round(reg.service_km),
            'night',   case when reg.night_s is null then null
                            else (reg.night_s / 3600)::int || ':' || lpad(((reg.night_s % 3600) / 60)::int::text, 2, '0') end,
            'status',  case when reg.drive_s > 201600 then 'over'
                            when reg.drive_s > 180000 then 'near'
                            else 'ok' end
          ) order by reg.drive_s desc
        ) from reg
      ), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'webdispecink-fleet',
      'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'fleet-worktime'
    )
  );
$$;

revoke all on function public.get_fleet_worktime(jsonb) from public, anon;
grant execute on function public.get_fleet_worktime(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_flowboard_agent_catalog.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_flowboard_agent_catalog
-- Popis: Registry feed — active agents projected for the federated flowboard
--        palette. Non-sensitive catalog projection (slug/purpose/model/tools/
--        safety/autonomy of ACTIVE agents only); granted to authenticated for
--        the builder UI. No row-level data, only the agent catalog surface.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.get_flowboard_agent_catalog()
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
BEGIN
  -- The builder palette is owner-scoped UI: require an authenticated caller. The
  -- projection is non-sensitive, but a SECURITY DEFINER function must still verify
  -- the caller rather than rely on EXECUTE grants alone (no anonymous palette).
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING errcode = '42501';
  END IF;
  RETURN (
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'slug', ac.slug, 'purpose', ac.purpose, 'default_model', ac.default_model,
             'allowed_tools', ac.allowed_tools, 'safety_level', ac.safety_level,
             'autonomy_level', ac.autonomy_level) ORDER BY ac.slug), '[]'::jsonb)
      FROM public.agent_catalog ac WHERE ac.is_active
  );
END;
$$;
REVOKE ALL ON FUNCTION public.get_flowboard_agent_catalog() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_flowboard_agent_catalog() TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_guild_member_detail.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_guild_member_detail
-- Arguments: p_partner_id uuid
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.get_guild_member_detail(p_partner_id uuid)
 RETURNS TABLE(id uuid, user_id uuid, display_name text, avatar_url text, business_name text, description text, guild_tier guild_tier, guild_bio text, expertise_summary text, city text, country text, website text, certification_level text, is_production_provider boolean, guild_joined_at timestamptz, services text[], languages text[], expertise_areas jsonb, published_rules jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    pp.id,
    pp.user_id,
    pp.display_name,
    pp.avatar_url,
    pp.business_name,
    pp.description,
    pp.guild_tier,
    pp.guild_bio,
    pp.expertise_summary,
    pp.city,
    pp.country,
    pp.website,
    pp.certification_level::text,
    pp.is_production_provider,
    pp.guild_joined_at,
    pp.services,
    pp.languages,
    COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
        'id', gea.id,
        'slug', gea.slug,
        'name_key', gea.name_key,
        'icon', gea.icon,
        'proficiency_level', gme.proficiency_level,
        'years_experience', gme.years_experience,
        'description', gme.description,
        'is_primary', gme.is_primary
      ) ORDER BY gme.is_primary DESC, gme.proficiency_level DESC)
      FROM guild_member_expertise gme
      JOIN guild_expertise_areas gea ON gea.id = gme.expertise_area_id
      WHERE gme.partner_id = pp.id),
      '[]'::jsonb
    ) AS expertise_areas,
    COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
        'id', er.id,
        'slug', er.slug,
        'title', er.title,
        'summary', er.summary,
        'category', er.category,
        'subscriber_count', er.subscriber_count,
        'rating_avg', er.rating_avg,
        'rating_count', er.rating_count,
        'published_at', er.published_at
      ) ORDER BY er.published_at DESC NULLS LAST)
      FROM expert_rules er
      WHERE er.author_partner_id = pp.id AND er.status = 'published'),
      '[]'::jsonb
    ) AS published_rules
  FROM partner_profiles pp
  WHERE pp.id = p_partner_id AND pp.is_visible = true;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_guild_member_detail(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_guild_member_detail(uuid) TO anon;
GRANT EXECUTE ON FUNCTION public.get_guild_member_detail(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_guild_member_detail(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_guild_members.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_guild_members
-- Arguments: p_expertise_slug text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.get_guild_members(p_expertise_slug text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, user_id uuid, display_name text, avatar_url text, guild_tier guild_tier, guild_bio text, expertise_summary text, city text, country text, certification_level text, is_production_provider boolean, guild_joined_at timestamptz, rules_count bigint, expertise_areas jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    pp.id,
    pp.user_id,
    pp.display_name,
    pp.avatar_url,
    pp.guild_tier,
    pp.guild_bio,
    pp.expertise_summary,
    pp.city,
    pp.country,
    pp.certification_level::text,
    pp.is_production_provider,
    pp.guild_joined_at,
    (SELECT count(*) FROM expert_rules er WHERE er.author_partner_id = pp.id AND er.status = 'published') AS rules_count,
    COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
        'id', gea.id,
        'slug', gea.slug,
        'name_key', gea.name_key,
        'icon', gea.icon,
        'proficiency_level', gme.proficiency_level,
        'is_primary', gme.is_primary
      ) ORDER BY gme.is_primary DESC, gme.proficiency_level DESC)
      FROM guild_member_expertise gme
      JOIN guild_expertise_areas gea ON gea.id = gme.expertise_area_id
      WHERE gme.partner_id = pp.id),
      '[]'::jsonb
    ) AS expertise_areas
  FROM partner_profiles pp
  WHERE pp.is_visible = true
    AND pp.guild_tier IS NOT NULL
    AND (p_expertise_slug IS NULL OR EXISTS (
      SELECT 1 FROM guild_member_expertise gme2
      JOIN guild_expertise_areas gea2 ON gea2.id = gme2.expertise_area_id
      WHERE gme2.partner_id = pp.id AND gea2.slug = p_expertise_slug
    ))
    AND (p_search IS NULL OR p_search = '' OR
      pp.display_name ILIKE '%' || p_search || '%' OR
      pp.guild_bio ILIKE '%' || p_search || '%' OR
      pp.expertise_summary ILIKE '%' || p_search || '%'
    )
  ORDER BY
    CASE pp.guild_tier
      WHEN 'grandmaster' THEN 1
      WHEN 'master' THEN 2
      WHEN 'journeyman' THEN 3
      WHEN 'apprentice' THEN 4
    END,
    pp.display_name
  LIMIT p_limit
  OFFSET p_offset;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_guild_members(text, text, integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_guild_members(text, text, integer, integer) TO anon;
GRANT EXECUTE ON FUNCTION public.get_guild_members(text, text, integer, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_guild_members(text, text, integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_guild_members_marketplace.sql
-- -----------------------------------------------------------------------------

-- Function: get_guild_members_marketplace
-- Purpose: Enhanced guild directory query with pricing, availability, activity metrics
-- Used by: GuildDirectory marketplace view

CREATE OR REPLACE FUNCTION get_guild_members_marketplace(
  p_expertise_slug text DEFAULT NULL,
  p_search text DEFAULT NULL,
  p_min_rating numeric DEFAULT NULL,
  p_max_hourly_rate numeric DEFAULT NULL,
  p_min_hourly_rate numeric DEFAULT NULL,
  p_availability_status text DEFAULT NULL,
  p_instant_booking boolean DEFAULT NULL,
  p_sort_by text DEFAULT 'relevance',
  p_limit integer DEFAULT 20,
  p_offset integer DEFAULT 0
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  RETURN COALESCE(
    (SELECT jsonb_build_object(
      'items', jsonb_agg(member_row),
      'total', (SELECT count(DISTINCT pp.id)
        FROM partner_profiles pp
        LEFT JOIN guild_member_expertise gme ON gme.partner_id = pp.id
        LEFT JOIN guild_expertise_areas gea ON gea.id = gme.expertise_area_id
        WHERE pp.is_visible = true
          AND pp.guild_tier IS NOT NULL
          AND (p_expertise_slug IS NULL OR gea.slug = p_expertise_slug)
          AND (p_search IS NULL OR pp.display_name ILIKE '%' || p_search || '%'
               OR pp.expertise_summary ILIKE '%' || p_search || '%')
          AND (p_min_rating IS NULL OR pp.avg_rating >= p_min_rating)
      )
    )
    FROM (
      SELECT jsonb_build_object(
        'id', pp.id,
        'user_id', pp.user_id,
        'display_name', pp.display_name,
        'avatar_url', pp.avatar_url,
        'city', pp.city,
        'country', pp.country,
        'guild_tier', pp.guild_tier,
        'bio', pp.guild_bio,
        'expertise_summary', pp.expertise_summary,
        'avg_rating', pp.avg_rating,
        'total_ratings_count', pp.total_ratings_count,
        'completed_projects_count', pp.completed_projects_count,
        'last_active_at', pp.last_active_at,
        'accepts_online', pp.accepts_online_appointments,
        'accepts_in_person', pp.accepts_in_person_appointments,
        -- Pricing
        'hourly_rate', sp.hourly_rate,
        'min_block_hours', sp.min_block_hours,
        'block_price', COALESCE(sp.hourly_rate * sp.min_block_hours, 0),
        'currency', COALESCE(sp.currency, public.commerce_base_currency()),
        'instant_booking_enabled', COALESCE(sp.instant_booking, false),
        'availability_status', COALESCE(sp.availability_status::text, 'offline'),
        'response_time_hours', sp.response_time_hours,
        'conditions_text', sp.conditions_text,
        -- Activity metrics
        'activity_score', COALESCE(sam.activity_score, 0),
        'response_time_avg_hours', sam.response_time_avg_hours,
        'acceptance_rate', COALESCE(sam.acceptance_rate, 100),
        'rules_contributed_count', COALESCE(sam.rules_contributed_count, 0),
        -- Expertise areas (aggregated)
        'expertise', COALESCE(
          (SELECT jsonb_agg(jsonb_build_object(
            'slug', gea2.slug,
            'name', gea2.name_key,
            'is_primary', gme2.is_primary,
            'proficiency_level', gme2.proficiency_level
          ))
          FROM guild_member_expertise gme2
          JOIN guild_expertise_areas gea2 ON gea2.id = gme2.expertise_area_id
          WHERE gme2.partner_id = pp.id AND gea2.is_active = true),
          '[]'::jsonb
        ),
        -- Relevance score for sorting
        'relevance_score', (
          COALESCE(pp.avg_rating, 0) * 15
          + COALESCE(sam.activity_score, 0) * 0.3
          + CASE WHEN pp.guild_tier = 'grandmaster' THEN 50
                 WHEN pp.guild_tier = 'master' THEN 40
                 WHEN pp.guild_tier = 'expert' THEN 30
                 WHEN pp.guild_tier = 'journeyman' THEN 20
                 WHEN pp.guild_tier = 'apprentice' THEN 10
                 ELSE 0 END
          + COALESCE(pp.completed_projects_count, 0) * 2
          + CASE WHEN sp.availability_status = 'available' THEN 20
                 WHEN sp.availability_status = 'busy' THEN 5
                 ELSE 0 END
        )
      ) AS member_row
      FROM partner_profiles pp
      LEFT JOIN specialist_pricing sp ON sp.partner_id = pp.id AND sp.is_active = true
      LEFT JOIN specialist_activity_metrics sam ON sam.partner_id = pp.id
      WHERE pp.is_visible = true
        AND pp.guild_tier IS NOT NULL
        -- Filters
        AND (p_expertise_slug IS NULL OR pp.id IN (
          SELECT gme3.partner_id FROM guild_member_expertise gme3
          JOIN guild_expertise_areas gea3 ON gea3.id = gme3.expertise_area_id
          WHERE gea3.slug = p_expertise_slug
        ))
        AND (p_search IS NULL OR pp.display_name ILIKE '%' || p_search || '%'
             OR pp.expertise_summary ILIKE '%' || p_search || '%')
        AND (p_min_rating IS NULL OR pp.avg_rating >= p_min_rating)
        AND (p_max_hourly_rate IS NULL OR sp.hourly_rate IS NULL
             OR sp.hourly_rate <= p_max_hourly_rate)
        AND (p_min_hourly_rate IS NULL OR sp.hourly_rate IS NULL
             OR sp.hourly_rate >= p_min_hourly_rate)
        AND (p_availability_status IS NULL
             OR sp.availability_status::text = p_availability_status)
        AND (p_instant_booking IS NULL
             OR sp.instant_booking = p_instant_booking)
      ORDER BY
        CASE WHEN p_sort_by = 'relevance' THEN (
          COALESCE(pp.avg_rating, 0) * 15
          + COALESCE(sam.activity_score, 0) * 0.3
          + CASE WHEN pp.guild_tier = 'grandmaster' THEN 50
                 WHEN pp.guild_tier = 'master' THEN 40
                 WHEN pp.guild_tier = 'expert' THEN 30
                 WHEN pp.guild_tier = 'journeyman' THEN 20
                 WHEN pp.guild_tier = 'apprentice' THEN 10
                 ELSE 0 END
          + COALESCE(pp.completed_projects_count, 0) * 2
        ) END DESC NULLS LAST,
        CASE WHEN p_sort_by = 'price_asc' THEN sp.hourly_rate END ASC NULLS LAST,
        CASE WHEN p_sort_by = 'price_desc' THEN sp.hourly_rate END DESC NULLS LAST,
        CASE WHEN p_sort_by = 'rating' THEN pp.avg_rating END DESC NULLS LAST,
        CASE WHEN p_sort_by = 'activity' THEN sam.activity_score END DESC NULLS LAST,
        pp.display_name ASC
      LIMIT p_limit OFFSET p_offset
    ) sub),
    jsonb_build_object('items', '[]'::jsonb, 'total', 0)
  );
END;
$$;

REVOKE ALL ON FUNCTION get_guild_members_marketplace(text,text,numeric,numeric,numeric,text,boolean,text,integer,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION get_guild_members_marketplace(text,text,numeric,numeric,numeric,text,boolean,text,integer,integer) TO anon;
GRANT EXECUTE ON FUNCTION get_guild_members_marketplace(text,text,numeric,numeric,numeric,text,boolean,text,integer,integer) TO authenticated;
GRANT EXECUTE ON FUNCTION get_guild_members_marketplace(text,text,numeric,numeric,numeric,text,boolean,text,integer,integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_instruction_payload.sql
-- -----------------------------------------------------------------------------

-- Function: get_instruction_payload
-- Returns structured JSON payload for IDE instruction generation.
-- Loads expert rules grouped by category — either story-specific or default set.
-- Used by scripts/generate-ide-instructions.mjs to produce per-IDE instruction files.

CREATE OR REPLACE FUNCTION public.get_instruction_payload(p_story_id uuid DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_story jsonb := 'null'::jsonb;
  v_ruleset jsonb := 'null'::jsonb;
  v_rule_ids uuid[];
  v_rules jsonb;
  v_categories jsonb;
  v_use_defaults boolean;
BEGIN
  -- Auth guard: require authenticated user or service_role
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  -- 1. Load story metadata (optional)
  IF p_story_id IS NOT NULL THEN
    SELECT jsonb_build_object(
      'id', ps.id,
      'title', ps.title,
      'tech_stack', to_jsonb(COALESCE(ps.tech_stack, '{}'::text[])),
      'domain', to_jsonb(COALESCE(ps.domain, '{}'::text[])),
      'risk_profile', COALESCE(ps.risk_profile, 'low')
    )
    INTO v_story
    FROM partner_stories ps
    WHERE ps.id = p_story_id;

    -- Load active ruleset for story
    SELECT jsonb_build_object(
      'fingerprint', sr.ruleset_fingerprint,
      'context_profile', COALESCE(sr.context_profile, 'repo_plus_rules'),
      'rule_count', COALESCE(array_length(sr.rule_ids, 1), 0)
    ), sr.rule_ids
    INTO v_ruleset, v_rule_ids
    FROM story_contexts sc
    JOIN story_rulesets sr ON sr.id = sc.ruleset_id
    WHERE sc.story_id = p_story_id;
  END IF;

  v_use_defaults := (v_rule_ids IS NULL);

  -- 2. Load expert rules as structured JSON array
  IF NOT v_use_defaults THEN
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'slug', er.slug,
        'title', er.title,
        'category', er.category::text,
        'ai_instructions', COALESCE(er.ai_instructions, ''),
        'summary', COALESCE(er.summary, '')
      ) ORDER BY er.category::text, er.slug
    ), '[]'::jsonb)
    INTO v_rules
    FROM expert_rules er
    WHERE er.id = ANY(v_rule_ids)
      AND er.status = 'published'
      AND er.visibility IN ('public', 'members');
  ELSE
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'slug', er.slug,
        'title', er.title,
        'category', er.category::text,
        'ai_instructions', COALESCE(er.ai_instructions, ''),
        'summary', COALESCE(er.summary, '')
      ) ORDER BY er.category::text, er.slug
    ), '[]'::jsonb)
    INTO v_rules
    FROM expert_rules er
    WHERE er.is_default = true
      AND er.status = 'published'
      AND er.visibility = 'public';
  END IF;

  -- 3. Extract distinct categories
  SELECT COALESCE(jsonb_agg(c ORDER BY c), '[]'::jsonb)
  INTO v_categories
  FROM (
    SELECT DISTINCT r->>'category' AS c
    FROM jsonb_array_elements(v_rules) AS r
  ) sub;

  -- 4. Build payload
  RETURN jsonb_build_object(
    'generated_at', now()::text,
    'payload_version', 1,
    'scope', CASE WHEN v_use_defaults THEN 'default' ELSE 'story' END,
    'story', v_story,
    'ruleset', v_ruleset,
    'categories', v_categories,
    'rules', v_rules
  );
END;
$$;

REVOKE ALL ON FUNCTION get_instruction_payload(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION get_instruction_payload(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION get_instruction_payload(uuid) TO service_role;

COMMENT ON FUNCTION get_instruction_payload(uuid) IS
  'Returns structured JSON payload for IDE instruction file generation. Story-specific or default rules.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_intranet_channels.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.get_intranet_channels()
RETURNS TABLE (
  id uuid,
  slug text,
  display_name text,
  channel_type text,
  description text,
  is_default boolean,
  member_count bigint,
  last_message_at timestamptz
)
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_caller uuid := auth.uid();
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  RETURN QUERY
  SELECT
    c.id,
    c.slug,
    c.display_name,
    c.channel_type,
    c.description,
    c.is_default,
    (SELECT count(*) FROM intranet_chat_members m2 WHERE m2.channel_id = c.id) AS member_count,
    (SELECT max(msg.created_at) FROM intranet_chat_messages msg WHERE msg.channel_id = c.id) AS last_message_at
  FROM intranet_chat_channels c
  JOIN intranet_chat_members m ON m.channel_id = c.id AND m.user_id = v_caller
  WHERE NOT c.is_archived
  ORDER BY last_message_at DESC NULLS LAST, c.display_name;
END;
$$;

REVOKE ALL ON FUNCTION get_intranet_channels() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION get_intranet_channels() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_intranet_messages.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.get_intranet_messages(
  p_channel_slug text,
  p_limit int DEFAULT 50,
  p_before timestamptz DEFAULT NULL
)
RETURNS TABLE (
  id uuid,
  user_id uuid,
  user_email text,
  content text,
  metadata jsonb,
  is_edited boolean,
  created_at timestamptz
)
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_channel_id uuid;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT c.id INTO v_channel_id
  FROM intranet_chat_channels c
  JOIN intranet_chat_members m ON m.channel_id = c.id AND m.user_id = v_caller
  WHERE c.slug = p_channel_slug AND NOT c.is_archived;

  IF v_channel_id IS NULL THEN
    RAISE EXCEPTION 'channel_not_found_or_not_member';
  END IF;

  RETURN QUERY
  SELECT
    msg.id,
    msg.user_id,
    u.email AS user_email,
    msg.content,
    msg.metadata,
    msg.is_edited,
    msg.created_at
  FROM intranet_chat_messages msg
  JOIN auth.users u ON u.id = msg.user_id
  WHERE msg.channel_id = v_channel_id
    AND (p_before IS NULL OR msg.created_at < p_before)
  ORDER BY msg.created_at DESC
  LIMIT LEAST(p_limit, 200);
END;
$$;

REVOKE ALL ON FUNCTION get_intranet_messages(text, int, timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION get_intranet_messages(text, int, timestamptz) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_jwt_role.sql
-- -----------------------------------------------------------------------------

-- Function: get_jwt_role
-- Returns the JWT role claim from the current request context.
-- Compatible with both PostgREST <12 (request.jwt.claim.role)
-- and PostgREST 14+ (request.jwt.claims JSON object).

CREATE OR REPLACE FUNCTION public.get_jwt_role()
  RETURNS text
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
AS $$
  SELECT COALESCE(
    current_setting('request.jwt.claim.role', true),
    (current_setting('request.jwt.claims', true)::jsonb ->> 'role')
  );
$$;

REVOKE ALL ON FUNCTION get_jwt_role() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION get_jwt_role() TO anon, authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/clear_knowledge_item_chunks.sql
-- -----------------------------------------------------------------------------

-- Function: clear_knowledge_item_chunks

-- Brick4: adding p_locale (DEFAULT NULL) changes the arity (1 → 2). Drop the 1-arg
-- overload first so the per-locale and clear-all forms don't become an ambiguous pair.
DROP FUNCTION IF EXISTS public.clear_knowledge_item_chunks(uuid);

CREATE OR REPLACE FUNCTION public.clear_knowledge_item_chunks(p_item_id uuid, p_locale text DEFAULT NULL)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_chunks_deleted integer;
  v_embeds_deleted integer;
BEGIN
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required';
  END IF;

  IF p_item_id IS NULL THEN
    RETURN jsonb_build_object('error', 'p_item_id is required');
  END IF;

  -- Brick4 per-locale clear: p_locale NULL clears ALL locales (back-compat); a passed
  -- locale clears only that locale's rows, leaving sibling locales intact. The earlier
  -- behaviour (always all-locales) silently wiped other languages on a single-locale
  -- re-ingest.
  WITH deleted AS (
    DELETE FROM knowledge_embeddings
     WHERE knowledge_item_id = p_item_id
       AND (p_locale IS NULL OR locale = p_locale) RETURNING 1
  )
  SELECT count(*) INTO v_embeds_deleted FROM deleted;

  WITH deleted AS (
    DELETE FROM knowledge_chunks
     WHERE knowledge_item_id = p_item_id
       AND (p_locale IS NULL OR locale = p_locale) RETURNING 1
  )
  SELECT count(*) INTO v_chunks_deleted FROM deleted;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    NULL, 'KB_CHUNKS_CLEARED',
    jsonb_build_object('entity_type','knowledge_item','entity_id',p_item_id,
                       'locale', p_locale,
                       'chunks_deleted', v_chunks_deleted,
                       'embeddings_deleted', v_embeds_deleted)
  );

  RETURN jsonb_build_object(
    'status','cleared',
    'chunks_deleted', v_chunks_deleted,
    'embeddings_deleted', v_embeds_deleted
  );
END;
$function$

;

REVOKE ALL ON FUNCTION clear_knowledge_item_chunks(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION clear_knowledge_item_chunks(uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/count_ai_proactive_runs_today.sql
-- -----------------------------------------------------------------------------

-- Function: public.count_ai_proactive_runs_today
-- Arguments: (none)
-- Returns: integer — number of proactive runs created today
-- Security: SECURITY DEFINER (service_role only — used by proactive engine stats)
-- Purpose: Count today's proactive runs for dashboard/stats without direct table access

CREATE OR REPLACE FUNCTION public.count_ai_proactive_runs_today()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
BEGIN
  -- Auth check: service_role only
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Access denied: service_role only';
  END IF;

  SELECT count(*)::integer INTO v_count
  FROM ai_proactive_runs
  WHERE created_at >= (current_date AT TIME ZONE 'UTC');

  RETURN v_count;
END;
$function$;

REVOKE ALL ON FUNCTION public.count_ai_proactive_runs_today() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.count_ai_proactive_runs_today() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/dirigent_dispatch_event.sql
-- -----------------------------------------------------------------------------

-- Function: public.dirigent_dispatch_event
-- Arguments: p_event_name text, p_payload jsonb
-- Security: SECURITY DEFINER (server-side router; service_role only)
-- Source: hand-authored; deploy via migration 20260501000000_dirigent_supervisor.sql
--
-- Purpose: Internal router called by the dirigent-supervisor edge function after
--          it receives a Claude Code hook event. Updates moderation_sessions.hook_event_log
--          (ring buffer, last 50 events) and returns the n8n playbook key for
--          the edge function to dispatch. Keeps event-to-playbook mapping in DB
--          rather than hardcoded in edge fn (easier to tune without redeploy).

CREATE OR REPLACE FUNCTION public.dirigent_dispatch_event(
  p_event_name text,
  p_payload jsonb
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_session_id uuid;
  v_story_id uuid;
  v_user_id uuid;
  v_playbook text;
  v_priority int;
  v_existing_log jsonb;
  v_new_entry jsonb;
BEGIN
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required';
  END IF;

  -- Map event_name → n8n playbook key. Centralised so edge fn stays thin.
  v_playbook := CASE p_event_name
    WHEN 'session_start'   THEN 'briefing'
    WHEN 'prompt_submit'   THEN 'intent_advisor'
    WHEN 'pre_tool'        THEN 'compliance_pre_check'
    WHEN 'post_tool'       THEN 'compliance_enforcement'
    WHEN 'stop'            THEN 'goal_evaluator'
    ELSE NULL
  END;

  IF v_playbook IS NULL THEN
    RETURN jsonb_build_object('error', 'unknown event', 'event', p_event_name);
  END IF;

  v_story_id := nullif(p_payload->>'story_id', '')::uuid;
  v_user_id  := nullif(p_payload->>'user_id', '')::uuid;
  v_session_id := nullif(p_payload->>'session_id', '')::uuid;

  -- Find or create the moderation_sessions row keyed by Claude session id.
  -- Note: requires moderation_sessions.user_id to be nullable (see migration).
  IF v_session_id IS NOT NULL THEN
    UPDATE moderation_sessions
       SET updated_at = now()
     WHERE id = v_session_id;
  END IF;

  IF NOT FOUND OR v_session_id IS NULL THEN
    INSERT INTO moderation_sessions (id, story_id, user_id, session_type, expertise_level, tech_stack, status, metadata)
    VALUES (
      coalesce(v_session_id, gen_random_uuid()),
      v_story_id,
      v_user_id,
      'claude_code_supervised',
      coalesce(p_payload->>'expertise_level', 'intermediate'),
      coalesce(p_payload->'tech_stack', '[]'::jsonb),
      'active',
      jsonb_build_object('ide_kind', 'claude_code', 'origin', 'dirigent-supervisor')
    )
    ON CONFLICT (id) DO UPDATE
       SET updated_at = now()
    RETURNING id INTO v_session_id;
  END IF;

  -- Append event to hook_event_log (ring buffer of last 50)
  v_new_entry := jsonb_build_object(
    'event', p_event_name,
    'at', now(),
    'tool_name', p_payload->'tool_input'->>'tool_name',
    'summary', left(coalesce(p_payload->>'summary', p_payload->'tool_input'->>'command', ''), 200)
  );

  UPDATE moderation_sessions
     SET metadata = jsonb_set(
       metadata,
       '{hook_event_log}',
       (
         SELECT jsonb_agg(elem)
         FROM (
           SELECT elem FROM jsonb_array_elements(
             coalesce(metadata->'hook_event_log', '[]'::jsonb) || v_new_entry
           ) AS t(elem)
           ORDER BY (elem->>'at')::timestamptz DESC NULLS LAST
           LIMIT 50
         ) sub
       )
     ),
     updated_at = now()
   WHERE id = v_session_id;

  -- Stop event priority depends on goal evaluator outcome — set lower budget.
  v_priority := CASE p_event_name
    WHEN 'stop' THEN 1
    WHEN 'session_start' THEN 1
    ELSE 5
  END;

  RETURN jsonb_build_object(
    'session_id', v_session_id,
    'playbook', v_playbook,
    'priority', v_priority,
    'event_logged', true
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.dirigent_dispatch_event(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.dirigent_dispatch_event(text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/dirigent_drain_nudges.sql
-- -----------------------------------------------------------------------------

-- Function: public.dirigent_drain_nudges
-- Arguments: p_story_id uuid, p_conversation_id text DEFAULT NULL, p_limit int DEFAULT 10
-- Security: SECURITY DEFINER, service_role only
-- Source: hand-authored; deploy via migration 20260524010000_dirigent_drain_nudges.sql
--
-- Purpose: Atomically SELECT + mark consumed_at on dirigent_nudges that have
--          not yet been delivered to the agent. Called by the
--          dirigent-supervisor edge fn (services/svc-ai-chat/src/routes/dirigent-supervisor.ts)
--          on every event dispatch (especially Stop) so the agent receives
--          backend-queued advisories from n8n / scheduled flows /
--          compliance engine.
--
-- Atomicity: UPDATE ... RETURNING in a single statement ensures no nudge is
--           delivered twice if two relay calls race (CTE locks via FOR UPDATE
--           SKIP LOCKED would also work; UPDATE...RETURNING with the
--           consumed_at IS NULL predicate is simpler and the worst-case
--           outcome is one nudge skipped, not duplicated — caller can retry
--           on the next Stop event).
--
-- Cold-start parity: empty result on no nudges (not NULL); caller treats as no
--           additional context to inject. RPC must remain callable even when
--           the dirigent_nudges table has 0 rows.

CREATE OR REPLACE FUNCTION public.dirigent_drain_nudges(
  p_story_id uuid,
  p_conversation_id text DEFAULT NULL,
  p_limit int DEFAULT 10
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_drained jsonb;
BEGIN
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required';
  END IF;

  -- Atomic drain: pick at most p_limit unconsumed, unexpired nudges scoped to
  -- the story (and optionally the conversation), mark consumed, return content.
  WITH picked AS (
    SELECT id
    FROM public.dirigent_nudges
    WHERE consumed_at IS NULL
      AND expires_at > now()
      AND (p_story_id IS NULL OR story_id = p_story_id)
      AND (p_conversation_id IS NULL OR conversation_id = p_conversation_id)
    ORDER BY created_at ASC
    LIMIT greatest(p_limit, 1)
    FOR UPDATE SKIP LOCKED
  ),
  consumed AS (
    UPDATE public.dirigent_nudges n
    SET consumed_at = now()
    FROM picked
    WHERE n.id = picked.id
    RETURNING n.id, n.event_origin, n.severity, n.message, n.metadata, n.created_at
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', id,
      'event_origin', event_origin,
      'severity', severity,
      'message', message,
      'metadata', metadata,
      'created_at', created_at
    )
    ORDER BY created_at ASC
  )
  INTO v_drained
  FROM consumed;

  RETURN COALESCE(v_drained, '[]'::jsonb);
END;
$function$;

REVOKE ALL ON FUNCTION public.dirigent_drain_nudges(uuid, text, int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.dirigent_drain_nudges(uuid, text, int) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_orders.sql
-- -----------------------------------------------------------------------------

-- Function: public.edge_orders
-- Purpose: Edge-safe order reads and writes with ownership validation.
-- Security: SECURITY DEFINER with auth.uid() ownership checks per action.
--           service_role bypasses ownership (for edge functions / webhooks).

CREATE OR REPLACE FUNCTION public.edge_orders(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_order_id uuid;
  v_row jsonb;
  v_user_id uuid;
  v_caller_id uuid;
  v_is_service_role boolean;
BEGIN
  -- Determine caller identity
  v_caller_id := auth.uid();
  v_is_service_role := (public.get_jwt_role() = 'service_role');

  -- ── get_checkout_context ───────────────────────────────────────────────
  IF p_action = 'get_checkout_context' THEN
    v_order_id := NULLIF(p_payload ->> 'order_id', '')::uuid;
    v_user_id := NULLIF(p_payload ->> 'user_id', '')::uuid;

    IF v_order_id IS NULL OR v_user_id IS NULL THEN
      RAISE EXCEPTION 'Missing required payload fields';
    END IF;

    -- Ownership: caller must match requested user_id (unless service_role)
    IF NOT v_is_service_role AND v_caller_id IS DISTINCT FROM v_user_id THEN
      RAISE EXCEPTION 'Unauthorized: caller does not own this resource';
    END IF;

    SELECT jsonb_build_object(
      'currency', o.currency,
      'id', o.id,
      'order_items', COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'id', oi.id,
              'price_at_purchase', oi.price_at_purchase,
              'product', (
                SELECT jsonb_build_array(
                  jsonb_build_object(
                    'description', p.description,
                    'name', p.name
                  )
                )
                FROM public.products p
                WHERE p.id = oi.product_id
                LIMIT 1
              ),
              'product_id', oi.product_id,
              'quantity', oi.quantity
            )
          )
          FROM public.order_items oi
          WHERE oi.order_id = o.id
        ),
        '[]'::jsonb
      ),
      'shipping', o.shipping,
      'shipping_address', o.shipping_address,
      'status', o.status,
      'total', o.total,
      'user_id', o.user_id
    )
    INTO v_row
    FROM public.orders o
    WHERE o.id = v_order_id
      AND o.user_id = v_user_id
    LIMIT 1;

    RETURN jsonb_build_object('row', v_row);
  END IF;

  -- ── get_order_id_by_payment_intent ─────────────────────────────────────
  -- Only service_role (Stripe webhook edge functions) should look up by payment intent
  IF p_action = 'get_order_id_by_payment_intent' THEN
    IF NOT v_is_service_role THEN
      RAISE EXCEPTION 'Unauthorized: service_role required for payment intent lookup';
    END IF;

    SELECT jsonb_build_object('order_id', o.id)
    INTO v_row
    FROM public.orders o
    WHERE o.stripe_payment_intent_id = NULLIF(p_payload ->> 'stripe_payment_intent_id', '')
    ORDER BY o.created_at DESC
    LIMIT 1;

    RETURN COALESCE(v_row, jsonb_build_object('order_id', NULL));
  END IF;

  -- ── get_packeta_context ────────────────────────────────────────────────
  IF p_action = 'get_packeta_context' THEN
    v_order_id := NULLIF(p_payload ->> 'order_id', '')::uuid;
    IF v_order_id IS NULL THEN
      RAISE EXCEPTION 'Missing order_id';
    END IF;

    -- Ownership check
    IF NOT v_is_service_role THEN
      PERFORM 1 FROM public.orders WHERE id = v_order_id AND user_id = v_caller_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Unauthorized: caller does not own this order';
      END IF;
    END IF;

    SELECT jsonb_build_object(
      'order', jsonb_build_object(
        'id', o.id,
        'packeta_branch_id', o.packeta_branch_id,
        'packeta_packet_id', o.packeta_packet_id,
        'shipping_address', o.shipping_address,
        'status', o.status,
        'total', o.total,
        'user_id', o.user_id
      ),
      'order_items',
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'product_id', oi.product_id,
              'quantity', oi.quantity
            )
          )
          FROM public.order_items oi
          WHERE oi.order_id = o.id
        ),
        '[]'::jsonb
      )
    )
    INTO v_row
    FROM public.orders o
    WHERE o.id = v_order_id
    LIMIT 1;

    RETURN jsonb_build_object('row', v_row);
  END IF;

  -- ── update_order ───────────────────────────────────────────────────────
  -- Only service_role can update orders (edge functions handling webhooks/fulfillment)
  IF p_action = 'update_order' THEN
    IF NOT v_is_service_role THEN
      RAISE EXCEPTION 'Unauthorized: service_role required for order updates';
    END IF;

    v_order_id := NULLIF(p_payload ->> 'order_id', '')::uuid;
    IF v_order_id IS NULL THEN
      RAISE EXCEPTION 'Missing order_id';
    END IF;

    UPDATE public.orders
    SET
      packeta_barcode = CASE WHEN p_payload ? 'packeta_barcode' THEN NULLIF(p_payload ->> 'packeta_barcode', '') ELSE packeta_barcode END,
      packeta_branch_id = CASE WHEN p_payload ? 'packeta_branch_id' THEN NULLIF(p_payload ->> 'packeta_branch_id', '')::integer ELSE packeta_branch_id END,
      packeta_packet_id = CASE WHEN p_payload ? 'packeta_packet_id' THEN NULLIF(p_payload ->> 'packeta_packet_id', '') ELSE packeta_packet_id END,
      status = COALESCE(NULLIF(p_payload ->> 'status', ''), status),
      payment_status = CASE WHEN p_payload ? 'payment_status' THEN NULLIF(p_payload ->> 'payment_status', '') ELSE payment_status END,
      stripe_payment_intent_id = CASE WHEN p_payload ? 'stripe_payment_intent_id' THEN NULLIF(p_payload ->> 'stripe_payment_intent_id', '') ELSE stripe_payment_intent_id END,
      stripe_session_id = CASE WHEN p_payload ? 'stripe_session_id' THEN NULLIF(p_payload ->> 'stripe_session_id', '') ELSE stripe_session_id END,
      tracking_url = CASE WHEN p_payload ? 'tracking_url' THEN NULLIF(p_payload ->> 'tracking_url', '') ELSE tracking_url END,
      invoice_number = CASE WHEN p_payload ? 'invoice_number' THEN NULLIF(p_payload ->> 'invoice_number', '') ELSE invoice_number END,
      invoice_pdf_path = CASE WHEN p_payload ? 'invoice_pdf_path' THEN NULLIF(p_payload ->> 'invoice_pdf_path', '') ELSE invoice_pdf_path END,
      invoice_generated_at = CASE WHEN p_payload ? 'invoice_generated_at' THEN (NULLIF(p_payload ->> 'invoice_generated_at', ''))::timestamptz ELSE invoice_generated_at END,
      updated_at = now()
    WHERE id = v_order_id;

    RETURN jsonb_build_object('ok', true, 'updated', FOUND);
  END IF;

  -- ── get_order_full ─────────────────────────────────────────────────────
  -- Service_role or order owner can read full order details
  IF p_action = 'get_order_full' THEN
    v_order_id := NULLIF(p_payload ->> 'order_id', '')::uuid;
    IF v_order_id IS NULL THEN
      RAISE EXCEPTION 'Missing order_id';
    END IF;

    -- Ownership check
    IF NOT v_is_service_role THEN
      PERFORM 1 FROM public.orders WHERE id = v_order_id AND user_id = v_caller_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Unauthorized: caller does not own this order';
      END IF;
    END IF;

    SELECT jsonb_build_object(
      'id', o.id,
      'user_id', o.user_id,
      'status', o.status,
      'payment_status', o.payment_status,
      'payment_method', o.payment_method,
      'total', o.total,
      'subtotal', o.subtotal,
      'shipping', o.shipping,
      'tax', o.tax,
      'currency', o.currency,
      'shipping_address', o.shipping_address,
      'billing_address', o.billing_address,
      'shipping_method', o.shipping_method,
      'variable_symbol', o.variable_symbol,
      'bank_transfer_iban', o.bank_transfer_iban,
      'bank_transfer_bic', o.bank_transfer_bic,
      'bank_transfer_amount', o.bank_transfer_amount,
      'bank_transfer_due_date', o.bank_transfer_due_date,
      'invoice_number', o.invoice_number,
      'invoice_pdf_path', o.invoice_pdf_path,
      'invoice_generated_at', o.invoice_generated_at,
      'stripe_payment_intent_id', o.stripe_payment_intent_id,
      'tracking_url', o.tracking_url,
      'packeta_barcode', o.packeta_barcode,
      'created_at', o.created_at,
      'order_items', COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'id', oi.id,
              'product_id', oi.product_id,
              'quantity', oi.quantity,
              'price', oi.price,
              'price_at_purchase', oi.price_at_purchase,
              'product_name', p.name,
              'product_sku', p.sku
            )
          )
          FROM public.order_items oi
          LEFT JOIN public.products p ON p.id = oi.product_id
          WHERE oi.order_id = o.id
        ),
        '[]'::jsonb
      ),
      'user_email', (SELECT email FROM aisha_auth.users WHERE id = o.user_id),
      'profile_name', (SELECT display_name FROM public.profiles WHERE user_id = o.user_id)
    )
    INTO v_row
    FROM public.orders o
    WHERE o.id = v_order_id;

    RETURN jsonb_build_object('row', v_row);
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_orders(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edge_orders(text, jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.edge_orders(text, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_build_ragnarok_document.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_build_ragnarok_document
-- Popis: Sestaví strukturovaný markdown dokument z řádku knowledge_items nebo
--        expert_rules pro upload do Ragnarok KB. Volá ji WF_KB_RAGNAROK_SYNC
--        node "Build Ragnarok Document" (ks-build-003) hned po Parse Change
--        Event — bez ní workflow padá na druhém kroku (PGRST202).
-- Bezpečnost: SECURITY DEFINER + service_role only (volá z n8n workflow).
--
-- Pozn.: Tento SoT soubor byl doplněn dodatečně — funkce dosud existovala jen
--        v migraci 20260429000000_fn_build_ragnarok_document.sql (pending), bez
--        SoT páru. To je latentní bug: při příštím `db:init:generate` se baseline
--        regeneruje z SoT, a funkce bez SoT páru by z baseline zmizela → návrat
--        PGRST202. DDL je drženo BYTE-IDENTICKÉ s migrací.
-- Vrací: jsonb { filename, source_type='txt', mime='text/markdown',
--               file_content, metadata }
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_build_ragnarok_document(
  p_source_table text,
  p_source_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_filename text;
  v_content text;
  v_metadata jsonb;
BEGIN
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required';
  END IF;

  IF p_source_table = 'expert_rules' THEN
    SELECT
      'rule-' || er.slug || '.md',
      -- Markdown structure: title heading + summary + ai_instructions + body
      '# ' || COALESCE(er.title, er.slug) || E'\n\n' ||
      CASE WHEN er.summary IS NOT NULL AND er.summary <> ''
           THEN '> ' || er.summary || E'\n\n'
           ELSE '' END ||
      CASE WHEN er.ai_instructions IS NOT NULL AND er.ai_instructions <> ''
           THEN '## AI Instructions' || E'\n\n' || er.ai_instructions || E'\n\n'
           ELSE '' END ||
      CASE WHEN er.body_markdown IS NOT NULL AND er.body_markdown <> ''
           THEN '## Content' || E'\n\n' || er.body_markdown
           ELSE '' END,
      jsonb_build_object(
        'title', er.title,
        'slug', er.slug,
        'category', er.category::text,
        'tags', to_jsonb(COALESCE(er.ai_context_tags, ARRAY[]::text[])),
        'visibility', er.visibility,
        'version', er.version,
        'author_partner_id', er.author_partner_id,
        'source_table', 'expert_rules',
        'source_id', er.id
      )
    INTO v_filename, v_content, v_metadata
    FROM public.expert_rules er
    WHERE er.id = p_source_id;

  ELSIF p_source_table = 'knowledge_items' THEN
    SELECT
      'ki-' || COALESCE(ki.source_slug, ki.id::text) || '.md',
      '# ' || COALESCE(ki.title, ki.source_slug) || E'\n\n' ||
      CASE WHEN ki.summary IS NOT NULL AND ki.summary <> ''
           THEN '> ' || ki.summary || E'\n\n'
           ELSE '' END ||
      CASE WHEN ki.ai_instructions IS NOT NULL AND ki.ai_instructions <> ''
           THEN '## AI Instructions' || E'\n\n' || ki.ai_instructions || E'\n\n'
           ELSE '' END ||
      CASE WHEN ki.body_markdown IS NOT NULL AND ki.body_markdown <> ''
           THEN '## Content' || E'\n\n' || ki.body_markdown
           ELSE '' END,
      jsonb_build_object(
        'title', ki.title,
        'source_slug', ki.source_slug,
        'category', ki.category,
        'tags', to_jsonb(COALESCE(ki.ai_context_tags, ARRAY[]::text[])),
        'visibility', ki.visibility,
        'item_type', ki.item_type::text,
        'story_id', ki.story_id,
        'source_table', 'knowledge_items',
        'source_id', ki.id
      )
    INTO v_filename, v_content, v_metadata
    FROM public.knowledge_items ki
    WHERE ki.id = p_source_id;

  ELSE
    RETURN jsonb_build_object(
      'error', 'Unsupported source_table: ' || p_source_table,
      'supported', jsonb_build_array('expert_rules', 'knowledge_items')
    );
  END IF;

  IF v_filename IS NULL THEN
    RETURN jsonb_build_object(
      'error', 'Row not found',
      'source_table', p_source_table,
      'source_id', p_source_id
    );
  END IF;

  RETURN jsonb_build_object(
    'filename', v_filename,
    'source_type', 'txt',
    'mime', 'text/markdown',
    'file_content', v_content,
    'metadata', v_metadata
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_build_ragnarok_document(text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_build_ragnarok_document(text, uuid) TO service_role;

COMMENT ON FUNCTION public.fn_build_ragnarok_document(text, uuid) IS
  'Build structured markdown document from knowledge_items or expert_rules row for Ragnarok KB upload. Called by WF_KB_RAGNAROK_SYNC workflow.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_get_llm_quota_status.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_get_llm_quota_status
-- Phase 12 WP 2.3 — LLM token rate limit per JWT.sub (read-only companion)
--
-- Returns the caller's own quota status WITHOUT consuming anything. Used by
-- the workbench to display "X tokens remaining today" + tier badge on the
-- chat surface header.
--
-- If the caller has no llm_quota row yet (never made an LLM call), returns
-- the FREE tier defaults — same value the next fn_check_and_consume call
-- would lazy-create. No write side-effect.
--
-- Security: SECURITY DEFINER + GRANT EXECUTE TO authenticated. Returns own
-- row only (auth.uid() filter); admin can pass p_user_id to query any user.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_get_llm_quota_status(
  p_user_id uuid DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_target_id uuid;
  v_quota     public.llm_quota%ROWTYPE;
  v_default   public.llm_tier_defaults%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  -- Auth-first: default to auth.uid(), promote to p_user_id ONLY after an
  -- explicit role check. This pattern prevents the parameter-first
  -- vulnerability where a malicious caller passes p_user_id to bypass
  -- auth.uid() before the admin guard fires.
  v_target_id := auth.uid();
  IF p_user_id IS NOT NULL AND p_user_id != auth.uid() THEN
    IF public.get_jwt_role() NOT IN ('admin', 'staff', 'service_role') THEN
      RAISE EXCEPTION 'Forbidden: only admin/staff may query other users'
        USING ERRCODE = '42501';
    END IF;
    v_target_id := p_user_id;
  END IF;

  SELECT * INTO v_quota
  FROM public.llm_quota
  WHERE user_id = v_target_id;

  IF NOT FOUND THEN
    -- No row yet → return free-tier defaults shape WITHOUT side effect
    SELECT * INTO v_default
    FROM public.llm_tier_defaults
    WHERE tier = 'free';

    RETURN jsonb_build_object(
      'user_id',               v_target_id,
      'tier',                  COALESCE(v_default.tier, 'free'),
      'daily_token_limit',     COALESCE(v_default.daily_token_limit, 0),
      'daily_cost_limit',  COALESCE(v_default.daily_cost_limit, 0),
      'consumed_tokens_today', 0,
      'consumed_cost_today',   0,
      'remaining_tokens',      COALESCE(v_default.daily_token_limit, 0),
      'remaining_cost',    COALESCE(v_default.daily_cost_limit, 0),
      'last_reset_at',         date_trunc('day', now()),
      'reset_at',              date_trunc('day', now()) + interval '1 day',
      'lazy_only',             true
    );
  END IF;

  -- Mid-day phantom reset for callers (counters reset at midnight UTC by
  -- pg_cron — but if cron hasn't fired yet and last_reset_at is from
  -- yesterday, surface the post-reset values so the UI doesn't show stale
  -- "0 remaining" on the dot.
  IF v_quota.last_reset_at < date_trunc('day', now()) THEN
    RETURN jsonb_build_object(
      'user_id',               v_target_id,
      'tier',                  v_quota.tier,
      'daily_token_limit',     v_quota.daily_token_limit,
      'daily_cost_limit',  v_quota.daily_cost_limit,
      'consumed_tokens_today', 0,
      'consumed_cost_today',   0,
      'remaining_tokens',      v_quota.daily_token_limit,
      'remaining_cost',    v_quota.daily_cost_limit,
      'last_reset_at',         date_trunc('day', now()),
      'reset_at',              date_trunc('day', now()) + interval '1 day',
      'lazy_only',             false
    );
  END IF;

  RETURN jsonb_build_object(
    'user_id',               v_quota.user_id,
    'tier',                  v_quota.tier,
    'daily_token_limit',     v_quota.daily_token_limit,
    'daily_cost_limit',  v_quota.daily_cost_limit,
    'consumed_tokens_today', v_quota.consumed_tokens_today,
    'consumed_cost_today',   v_quota.consumed_cost_today,
    'remaining_tokens',      GREATEST(0, v_quota.daily_token_limit - v_quota.consumed_tokens_today),
    'remaining_cost',    GREATEST(0, v_quota.daily_cost_limit - v_quota.consumed_cost_today),
    'last_reset_at',         v_quota.last_reset_at,
    'reset_at',              v_quota.last_reset_at + interval '1 day',
    'lazy_only',             false
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_get_llm_quota_status(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_get_llm_quota_status(uuid) TO authenticated;

COMMENT ON FUNCTION public.fn_get_llm_quota_status(uuid) IS
  'Phase 12 WP 2.3 — read-only LLM quota status for self (auth.uid()) or any user (admin only). No write side-effect.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_get_memories_without_embeddings.sql
-- -----------------------------------------------------------------------------

/**
 * SQL Function: fn_get_memories_without_embeddings
 *
 * Returns agent_memories rows that don't have an embedding yet,
 * ordered by importance (descending). Used by the generate-memory-embeddings
 * edge function to batch-generate OpenAI embeddings.
 *
 * @param p_agent_slug - Optional filter by agent slug
 * @param p_batch_size - Max rows to return (default 50, max 100)
 * @param p_memory_id - Optional: fetch a single memory by ID
 * @returns setof records (id, content, agent_slug, memory_type)
 */
CREATE OR REPLACE FUNCTION public.fn_get_memories_without_embeddings(
  p_agent_slug text DEFAULT NULL,
  p_batch_size integer DEFAULT 50,
  p_memory_id uuid DEFAULT NULL
)
RETURNS TABLE (
  id uuid,
  content text,
  agent_slug text,
  memory_type text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  -- Auth check: service_role only (called from edge function)
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required';
  END IF;

  -- Clamp batch size
  IF p_batch_size > 100 THEN
    p_batch_size := 100;
  END IF;

  RETURN QUERY
  SELECT am.id, am.content, am.agent_slug, am.memory_type
  FROM agent_memories am
  WHERE am.embedding IS NULL
    AND (p_memory_id IS NULL OR am.id = p_memory_id)
    AND (p_agent_slug IS NULL OR am.agent_slug = p_agent_slug)
  ORDER BY am.importance DESC
  LIMIT p_batch_size;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_get_memories_without_embeddings(text, integer, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_get_memories_without_embeddings(text, integer, uuid) TO service_role;


