-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_app_secret.sql
-- -----------------------------------------------------------------------------

-- get_app_secret: Retrieve a single secret value by key from the VAULT (encrypted).
-- Dřív četla nešifrovanou tabulku app_secrets; ta se převádí do trezoru
-- (migrate_app_secrets_to_vault) a přímý grant na ni nemá nikdo.
-- Called by: deployment-executor/index.ts (3x) for SSH keys, credentials
-- SECURITY: service_role only — secrets must not be accessible from frontend
CREATE OR REPLACE FUNCTION public.get_app_secret(
  p_key text
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_value text;
BEGIN
  -- Auth: JEN služba (service_role). ⛔ Dřív `auth.uid() IS NULL → Not authenticated`:
  -- servisní token nenese `sub`, takže volání SLUŽBY (gateway deployment-executor,
  -- svc-github-app) vždy padlo a čtenář tiše přešel na env (rozbor úložišť
  -- pověření, Guru 2026-09-28). Uživatel s `sub` tajemství číst nemá.
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Forbidden: service_role required' USING ERRCODE = '42501';
  END IF;

  SELECT ds.decrypted_secret INTO v_value
  FROM vault.decrypted_secrets ds
  WHERE ds.name = p_key
  ORDER BY ds.updated_at DESC NULLS LAST
  LIMIT 1;

  RETURN v_value;
END;
$$;

REVOKE ALL ON FUNCTION public.get_app_secret(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_app_secret(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_app_secrets_batch.sql
-- -----------------------------------------------------------------------------

-- get_app_secrets_batch: Retrieve multiple secrets by key array from the VAULT (encrypted).
-- Dřív četla nešifrovanou tabulku app_secrets (viz get_app_secret).
-- Called by: github-app-auth/index.ts for GITHUB_APP_ID + GITHUB_APP_PRIVATE_KEY
-- SECURITY: service_role only
CREATE OR REPLACE FUNCTION public.get_app_secrets_batch(
  p_keys text[]
)
RETURNS TABLE(key text, value text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  -- Auth: JEN služba (service_role). ⛔ Dřív `auth.uid() IS NULL → Not authenticated`:
  -- servisní token nenese `sub`, takže volání SLUŽBY (gateway deployment-executor,
  -- svc-github-app) vždy padlo a čtenář tiše přešel na env (rozbor úložišť
  -- pověření, Guru 2026-09-28). Uživatel s `sub` tajemství číst nemá.
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Forbidden: service_role required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT DISTINCT ON (ds.name) ds.name::text, ds.decrypted_secret::text
  FROM vault.decrypted_secrets ds
  WHERE ds.name = ANY(p_keys)
  ORDER BY ds.name, ds.updated_at DESC NULLS LAST;
END;
$$;

REVOKE ALL ON FUNCTION public.get_app_secrets_batch(text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_app_secrets_batch(text[]) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_github_app_secrets_from_vault.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_github_app_secrets_from_vault
-- Returns GitHub App credentials (app_id + private_key) from Supabase Vault.
-- JEN trezor (2026-09-28): záloha na nešifrovanou app_secrets zrušena a chyba
-- trezoru se nespolyká — tichá záloha by z rozbitého trezoru udělala čtení
-- nešifrované kopie (přesně tak to běželo, dokud #1080 trezor neopravil).
-- @security: service_role only

CREATE OR REPLACE FUNCTION public.get_github_app_secrets_from_vault()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_app_id     text;
  v_private_key text;
BEGIN
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Forbidden: service_role required';
  END IF;

  SELECT decrypted_secret INTO v_app_id
    FROM vault.decrypted_secrets
   WHERE name = 'GITHUB_APP_ID'
   ORDER BY updated_at DESC NULLS LAST
   LIMIT 1;

  SELECT decrypted_secret INTO v_private_key
    FROM vault.decrypted_secrets
   WHERE name = 'GITHUB_APP_PRIVATE_KEY'
   ORDER BY updated_at DESC NULLS LAST
   LIMIT 1;

  RETURN jsonb_build_object(
    'app_id', v_app_id,
    'private_key', v_private_key,
    'source', CASE
      WHEN v_app_id IS NOT NULL AND v_private_key IS NOT NULL THEN 'vault'
      ELSE 'not_found'
    END
  );
END;
$$;

REVOKE ALL ON FUNCTION public.get_github_app_secrets_from_vault() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_github_app_secrets_from_vault() TO service_role;


