-- File: aisha/db/sql/functions/get_keycloak_ids_for_role.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.get_keycloak_ids_for_role(p_role text)
RETURNS TABLE(user_id uuid, keycloak_id text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  -- Auth: service_role access verified by GRANT, extra safety check
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  RETURN QUERY
  SELECT ur.user_id, i.provider_id::text AS keycloak_id
  FROM user_roles ur
  JOIN auth.identities i
    ON i.user_id = ur.user_id
   AND i.provider = 'keycloak'
  WHERE ur.role = p_role::app_role
  ORDER BY ur.user_id;
END;
$$;

REVOKE ALL ON FUNCTION public.get_keycloak_ids_for_role(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_keycloak_ids_for_role(text) TO service_role;

COMMENT ON FUNCTION public.get_keycloak_ids_for_role(text) IS
  'Returns Keycloak provider IDs for all users with the given app_role. Used by keycloak-role-sync edge function.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_knowledge_items_for_embedding.sql
-- -----------------------------------------------------------------------------

-- Function: get_knowledge_items_for_embedding

-- PR-1 (ingest provenance & dedup): the batch gate additionally re-emits items whose
-- chunks were built from a different content key (see WHERE below).
-- Brick4: surface ki.locale (+ source_hash) so the embedding worker can thread the
-- item's locale into chunk/embedding writes and the language-aware contextual prefix.
-- Adding result columns changes the return type — DROP before CREATE (CREATE OR
-- REPLACE cannot change a function's RETURNS TABLE shape).
DROP FUNCTION IF EXISTS public.get_knowledge_items_for_embedding(integer, boolean, uuid, text, text);

CREATE OR REPLACE FUNCTION public.get_knowledge_items_for_embedding(p_batch_size integer DEFAULT 10, p_force boolean DEFAULT false, p_item_id uuid DEFAULT NULL::uuid, p_item_type text DEFAULT NULL::text, p_source_slug text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, title text, summary text, body_markdown text, ai_instructions text, source_slug text, item_type text, locale text, source_hash text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required';
  END IF;

  IF p_batch_size > 100 THEN
    p_batch_size := 100;
  END IF;

  RETURN QUERY
  SELECT ki.id,
         ki.title,
         ki.summary,
         ki.body_markdown,
         ki.ai_instructions,
         ki.source_slug,
         ki.item_type::text,
         ki.locale,
         ki.source_hash
  FROM knowledge_items ki
  WHERE ki.status = 'active'
    AND (p_item_id IS NULL OR ki.id = p_item_id)
    AND (p_item_type IS NULL OR ki.item_type::text = p_item_type)
    AND (p_source_slug IS NULL OR ki.source_slug = p_source_slug)
    AND (
      p_force
      -- fresh item: nothing chunked yet
      OR NOT EXISTS (
        SELECT 1 FROM knowledge_chunks kc WHERE kc.knowledge_item_id = ki.id
      )
      -- stale item (PR-1 dedup): chunks exist but carry a different NON-NULL content
      -- key than the item's current source_hash (workers write chunks with
      -- p_source_hash = ki.source_hash, so equality = up-to-date). Both sides must be
      -- non-NULL: legacy hash-less chunks are NOT treated as stale, so enabling this
      -- cannot trigger a fleet-wide re-embedding storm.
      OR EXISTS (
        SELECT 1 FROM knowledge_chunks kc
        WHERE kc.knowledge_item_id = ki.id
          AND kc.source_hash IS NOT NULL
          AND ki.source_hash IS NOT NULL
          AND kc.source_hash <> ki.source_hash
      )
    )
  ORDER BY ki.updated_at DESC NULLS LAST, ki.created_at DESC
  LIMIT p_batch_size;
END;
$function$

;

REVOKE ALL ON FUNCTION get_knowledge_items_for_embedding(integer,boolean,uuid,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION get_knowledge_items_for_embedding(integer,boolean,uuid,text,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_latest_snapshot.sql
-- -----------------------------------------------------------------------------

-- Poslední platný podepsaný snímek pro surface. SECURITY INVOKER (RLS: jen neexpirované).
-- Vrací payload + podpisová pole — klient si podpis ověřuje pinovaným public klíčem.

create or replace function public.get_latest_snapshot(p_surface text)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  select s.payload || jsonb_build_object(
           'sha256',    s.sha256,
           'signature', s.signature,
           'key_id',    s.key_id
         )
  from public.surface_snapshots s
  where s.surface = p_surface
    and s.expires_at > now()
  order by s.published_at desc
  limit 1;
$$;

-- Grants: authenticated + service_role (NOT anon, #566 floor); RLS on the underlying
-- tables is the real access boundary (SECURITY INVOKER — runs as the caller).
REVOKE ALL ON FUNCTION public.get_latest_snapshot(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_latest_snapshot(text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_leaderboard.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_leaderboard
-- Arguments: p_period_type text, p_limit integer
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:49+01:00

CREATE OR REPLACE FUNCTION public.get_leaderboard(p_period_type text DEFAULT 'weekly'::text, p_limit integer DEFAULT 100)
 RETURNS TABLE(rank integer, user_id uuid, display_name text, total_points integer, completions_count integer, streak_days integer, is_current_user boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_current_period_id UUID;
  v_current_user_id UUID;
BEGIN
  v_current_user_id := auth.uid();

  -- RATE LIMITING: 30 requests per minute
  PERFORM enforce_rate_limit('get_leaderboard', 60000, 30);

  -- Get current period (don't create - that's for cron job)
  SELECT id INTO v_current_period_id
  FROM leaderboard_periods
  WHERE period_type = p_period_type
    AND period_start <= CURRENT_DATE
    AND period_end >= CURRENT_DATE
  ORDER BY created_at DESC
  LIMIT 1;

  -- If no period exists, return empty (cron job will create it)
  IF v_current_period_id IS NULL THEN
    RETURN;
  END IF;

  -- Return leaderboard with anonymized display names
  RETURN QUERY
  SELECT
    le.rank,
    le.user_id,
    CASE
      WHEN le.user_id = v_current_user_id THEN 'You'
      ELSE 'Anonymous#' || SUBSTR(le.user_id::TEXT, 1, 4) -- Anonymize
    END as display_name,
    le.total_points,
    le.completions_count,
    le.streak_days,
    (le.user_id = v_current_user_id) as is_current_user
  FROM leaderboard_entries le
  WHERE le.period_id = v_current_period_id
    AND le.rank IS NOT NULL
  ORDER BY le.rank ASC
  LIMIT p_limit;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.get_leaderboard(p_period_type text, p_limit integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_leaderboard(p_period_type text, p_limit integer) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_mcp_servers_due_probe.sql
-- -----------------------------------------------------------------------------

-- Function: get_mcp_servers_due_probe
-- Returns mcp_server_registry rows that the WF_MCP_PROBE n8n workflow should
-- test next. Rate-limited per server via last_tested_at + EXPONENTIAL
-- BACKOFF on test_failure_count.
--
-- Exponential backoff schedule (mirrors get_providers_due_health_probe):
--   0-2 failures: probe every p_min_interval_seconds (5min default)
--   3-4 failures: probe every 1h
--   5-7 failures: probe every 6h
--   8+ failures:  probe every 24h (max — operator should investigate)
--
-- Counter is in test_failure_count column (managed by aisha_record_mcp_test_result).
-- Reset to 0 on first successful probe via that same RPC.
--
-- Excludes:
--   * status='rejected' OR 'deprecated' — operator has explicitly retired
--   * transport='stdio' — n8n can't execute stdio probes reliably; those
--     belong to the svc-ai-chat in-process reflection runner where the
--     mcp_test node has proper subprocess management.
--   * NULL endpoint_url for non-stdio transports — can't probe
--
-- Sorts NULL last_tested_at first (never probed → highest priority).

CREATE OR REPLACE FUNCTION public.get_mcp_servers_due_probe(
  p_min_interval_seconds int DEFAULT 300,
  p_limit                int DEFAULT 20
)
RETURNS TABLE (
  slug text,
  transport text,
  endpoint_url text,
  auth_env_var text,
  status text,
  last_tested_at timestamptz,
  test_failure_count int
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT m.slug,
         m.transport,
         m.endpoint_url,
         m.auth_env_var,
         m.status,
         m.last_tested_at,
         m.test_failure_count
  FROM   mcp_server_registry m
  WHERE  m.status NOT IN ('rejected', 'deprecated')
    AND  m.transport != 'stdio'
    AND  m.endpoint_url IS NOT NULL
    AND  (
           m.last_tested_at IS NULL
        OR m.last_tested_at < now() - make_interval(secs =>
             CASE
               WHEN m.test_failure_count <= 2 THEN p_min_interval_seconds
               WHEN m.test_failure_count <= 4 THEN 3600     -- 1h
               WHEN m.test_failure_count <= 7 THEN 21600    -- 6h
               ELSE                                86400    -- 24h
             END
           )
         )
  ORDER  BY m.last_tested_at ASC NULLS FIRST
  LIMIT  p_limit;
END;
$$;

REVOKE ALL ON FUNCTION public.get_mcp_servers_due_probe(int, int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_mcp_servers_due_probe(int, int) TO service_role;

COMMENT ON FUNCTION public.get_mcp_servers_due_probe(int, int) IS
  'WF_MCP_PROBE discovery RPC — returns active MCP servers (excl. stdio transport + rejected/deprecated) due for HTTP/SSE probe. NULL-first ordering surfaces never-probed servers first. Service-role only.';


