-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_member_diary_calendar_audited.sql
-- -----------------------------------------------------------------------------

-- Function: get_member_diary_calendar_audited
-- Returns calendar view with health/product data for a month
-- Security: DEFINER with audit trail
-- Created: 2026-01-17

CREATE OR REPLACE FUNCTION public.get_member_diary_calendar_audited(p_month date)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
DECLARE
  v_result jsonb;
  v_start_date date;
  v_end_date date;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_start_date := date_trunc('month', p_month)::date;
  v_end_date := (date_trunc('month', p_month) + interval '1 month' - interval '1 day')::date;

  INSERT INTO audit_journal (user_id, action_type, entity_type, area, severity, summary)
  VALUES (auth.uid(), 'read', 'member_diary_calendar', 'member', 'info', 
          format('Member viewed calendar for %s', to_char(p_month, 'YYYY-MM')));

  SELECT jsonb_build_object(
    'month', to_char(p_month, 'YYYY-MM'),
    'days', COALESCE((
      SELECT jsonb_agg(day_data ORDER BY (day_data->>'date'))
      FROM (
        SELECT jsonb_build_object(
          'date', d::date,
          'products_taken', COALESCE((
            SELECT COUNT(*)::int FROM member_product_logs msl 
            WHERE msl.user_id = auth.uid() AND msl.logged_at::date = d::date
          ), 0),
          'states_logged', COALESCE((
            SELECT COUNT(*)::int FROM member_health_logs mhl 
            WHERE mhl.user_id = auth.uid() AND mhl.logged_at::date = d::date
          ), 0),
          'has_active_issues', EXISTS(
            SELECT 1 FROM member_health_logs mhl 
            WHERE mhl.user_id = auth.uid() 
              AND mhl.started_at::date <= d::date 
              AND (mhl.ended_at IS NULL OR mhl.ended_at::date >= d::date)
              AND mhl.severity >= 3
          ),
          'distribution_received', EXISTS(
            SELECT 1 FROM user_distribution_schedule uds
            WHERE uds.user_id = auth.uid()
              AND uds.delivered_at::date = d::date
          )
        ) as day_data
        FROM generate_series(v_start_date, v_end_date, '1 day'::interval) d
      ) days
    ), '[]'::jsonb),
    'distributions', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'date', uds.scheduled_date,
        'status', uds.status,
        'vial_count', uds.vial_count,
        'tracking_number', uds.tracking_number,
        'carrier', uds.carrier,
        'shipped_at', uds.shipped_at,
        'delivered_at', uds.delivered_at
      ))
      FROM user_distribution_schedule uds
      WHERE uds.user_id = auth.uid()
        AND uds.scheduled_date BETWEEN v_start_date AND v_end_date
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;

-- Permissions
REVOKE ALL ON FUNCTION public.get_member_diary_calendar_audited(date) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.get_member_diary_calendar_audited(date) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_member_diary_calendar_audited(date) TO authenticated;

COMMENT ON FUNCTION public.get_member_diary_calendar_audited(date) IS 
'Returns calendar view with product/health data for a given month. Audited.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_member_diary_for_partner_audited.sql
-- -----------------------------------------------------------------------------

-- Function: get_member_diary_for_partner_audited
-- Returns member diary view for partners with consent
-- Security: DEFINER with audit trail and consent check
-- Created: 2026-01-17

CREATE OR REPLACE FUNCTION public.get_member_diary_for_partner_audited(p_member_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
DECLARE
  v_result jsonb;
  v_has_consent boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Check if partner has consent
  SELECT EXISTS(
    SELECT 1 FROM data_sharing_consents dsc
    JOIN partner_profiles pp ON pp.user_id = auth.uid()
    WHERE dsc.user_id = p_member_id 
      AND dsc.partner_id = pp.id
      AND dsc.revoked_at IS NULL
      AND (dsc.expires_at IS NULL OR dsc.expires_at > now())
  ) INTO v_has_consent;

  IF NOT v_has_consent THEN
    RAISE EXCEPTION 'No valid data sharing consent';
  END IF;

  INSERT INTO audit_journal (user_id, action_type, entity_type, entity_id, area, severity, summary)
  VALUES (auth.uid(), 'read', 'member_diary_partner_view', p_member_id::text, 'partner', 'info', 
          'Partner viewed member diary');

  SELECT jsonb_build_object(
    'health_logs', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', mhl.id,
        'state_name', COALESCE(mhs.custom_name, mhs.name_key),
        'severity', mhl.severity,
        'logged_at', mhl.logged_at,
        'started_at', mhl.started_at,
        'ended_at', mhl.ended_at,
        'notes', mhl.notes
      ) ORDER BY mhl.logged_at DESC)
      FROM member_health_logs mhl
      JOIN member_health_states mhs ON mhs.id = mhl.state_id
      WHERE mhl.user_id = p_member_id
      LIMIT 50
    ), '[]'::jsonb),
    'health_states', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', mhs.id,
        'name', COALESCE(mhs.custom_name, mhs.name_key),
        'icon', mhs.icon,
        'color', mhs.color,
        'is_active', mhs.is_active
      ))
      FROM member_health_states mhs
      WHERE mhs.user_id = p_member_id AND mhs.is_active = true
    ), '[]'::jsonb),
    'product_logs', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', msl.id,
        'plan_id', msl.plan_id,
        'logged_at', msl.logged_at,
        'dose_taken', msl.dose_taken,
        'notes', msl.notes
      ) ORDER BY msl.logged_at DESC)
      FROM member_product_logs msl
      WHERE msl.user_id = p_member_id
      LIMIT 50
    ), '[]'::jsonb),
    'product_plans', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', msp.id,
        'name', COALESCE(p.name, ms.name),
        'dose_amount', msp.dose_amount,
        'dose_unit', msp.dose_unit,
        'doses_per_day', msp.doses_per_day,
        'is_active', msp.is_active
      ))
      FROM member_product_plans msp
      LEFT JOIN products p ON p.id = msp.product_id
      LEFT JOIN member_products ms ON ms.id = msp.product_id
      WHERE msp.user_id = p_member_id AND msp.is_active = true
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;

-- Permissions
REVOKE ALL ON FUNCTION public.get_member_diary_for_partner_audited(uuid) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.get_member_diary_for_partner_audited(uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_member_diary_for_partner_audited(uuid) TO authenticated;

COMMENT ON FUNCTION public.get_member_diary_for_partner_audited(uuid) IS 
'Returns member diary data for partners with valid data sharing consent. Audited.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_model_pricing.sql
-- -----------------------------------------------------------------------------

-- Function: get_model_pricing
-- Return per-model pricing from ai_model_registry.
-- Used by VS Code resource tracker for accurate per-model cost calculation.
-- Source: migration 20260418130100_cost_intelligence_and_hippocampus.sql

CREATE OR REPLACE FUNCTION public.get_model_pricing()
RETURNS jsonb
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb := '{}'::jsonb;
  v_row record;
BEGIN
  FOR v_row IN
    SELECT
      r.cached_input_price_per_m,
      r.input_price_per_m,
      r.model_id,
      r.output_price_per_m,
      r.provider
    FROM ai_model_registry r
    WHERE r.is_available AND NOT r.is_deprecated
    ORDER BY r.provider, r.model_id
  LOOP
    v_result := v_result || jsonb_build_object(v_row.model_id, jsonb_build_object(
      'cached_input_per_m', v_row.cached_input_price_per_m,
      'input_per_m', v_row.input_price_per_m,
      'output_per_m', v_row.output_price_per_m,
      'provider', v_row.provider
    ));
  END LOOP;

  RETURN v_result;
END;
$function$;

COMMENT ON FUNCTION get_model_pricing() IS
  'Return per-model pricing from ai_model_registry. '
  'Used by resource tracker for accurate per-model cost calculation.';

REVOKE ALL ON FUNCTION public.get_model_pricing() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_model_pricing() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_model_pricing() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_models_due_self_test.sql
-- -----------------------------------------------------------------------------

-- Function: get_models_due_self_test
-- Returns models the self-test runner should probe next. Default (p_mode='pending')
-- = discovered-but-untested available models (the boot path). Re-test modes let an
-- admin re-probe ALREADY-settled models: 'rejected-only' (re-prove a model that failed,
-- e.g. after a transient provider outage) or 'all-settled' (pending+tested+rejected).
-- 'approved' is NEVER returned — an admin verdict is not auto-re-tested.
-- service_role only. Pairs with record_model_self_test (the verdict).

-- p_mode added → drop the old single-arg signature so the overload does not linger.
DROP FUNCTION IF EXISTS public.get_models_due_self_test(int);

CREATE OR REPLACE FUNCTION public.get_models_due_self_test(
  p_limit int  DEFAULT 25,
  p_mode  text DEFAULT 'pending'
)
RETURNS TABLE (
  id uuid,
  provider text,
  model_id text,
  eval_status text,
  first_seen_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'service_role required' USING ERRCODE = '22023';
  END IF;
  IF p_mode NOT IN ('pending', 'rejected-only', 'all-settled') THEN
    RAISE EXCEPTION 'invalid p_mode: %', p_mode USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT r.id, r.provider, r.model_id, r.eval_status, r.first_seen_at
  FROM   ai_model_registry r
  WHERE  r.is_available
    AND  NOT r.is_deprecated
    AND  CASE p_mode
           WHEN 'pending'       THEN r.eval_status = 'pending'
           WHEN 'rejected-only' THEN r.eval_status = 'rejected'
           WHEN 'all-settled'   THEN r.eval_status IN ('pending', 'tested', 'rejected')
           ELSE false
         END
  ORDER  BY r.first_seen_at ASC NULLS FIRST  -- oldest first
  LIMIT  p_limit;
END;
$$;

REVOKE ALL ON FUNCTION public.get_models_due_self_test(int, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_models_due_self_test(int, text) TO service_role;

COMMENT ON FUNCTION public.get_models_due_self_test(int, text) IS
  'Self-test runner discovery RPC. p_mode: pending (boot default) | rejected-only | all-settled (admin re-test). Never returns approved. service_role only.';


