    mhs.icon,
    mhs.id,
    mhs.is_active,
    mhs.last_logged_at,
    mhs.name_key,
    mhs.severity_scale,
    mhs.show_on_dashboard,
    mhs.updated_at,
    mhs.user_id
  FROM member_health_states mhs
  WHERE mhs.user_id = auth.uid() AND mhs.is_active = true
  ORDER BY mhs.name_key;
END;
$$;

