-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_news_tags.sql
-- -----------------------------------------------------------------------------

-- Source of truth for get_news_tags
-- The distinct tags in use across published articles (+ usage count) — feeds the
-- archive/blog browser's tag filter, the same way get_archive_filter_options
-- feeds the archive browser. Dynamic; no hardcoded taxonomy.

CREATE OR REPLACE FUNCTION public.get_news_tags()
RETURNS TABLE(tag text, usage_count bigint)
LANGUAGE sql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
  SELECT t.tag, count(*)::bigint AS usage_count
  FROM public.news_articles na
  CROSS JOIN LATERAL unnest(na.tags) AS t(tag)
  WHERE na.is_published = true
  GROUP BY t.tag
  ORDER BY count(*) DESC, t.tag ASC;
$$;

REVOKE ALL ON FUNCTION public.get_news_tags() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_news_tags() TO anon;
GRANT EXECUTE ON FUNCTION public.get_news_tags() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_news_timeline_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_news_timeline_block
-- Popis: GENERICKÝ 'timeline' blok nad publikovanými články (news_articles):
--        jedna položka = jeden článek, `at` = published_at, `label_key` =
--        title_key (překlad řeší klient, hlavička je v šesti jazycích).
--
-- ⛔ PROČ VZNIKL (naměřeno 2026-09-03, audit U4-3): sekce „oznámení" extranetu
-- byla v seedu napojená na get_workflow_timeline_block — časovou osu VÝROBNÍHO
-- workflow, která navíc vrací tvar TABULKY (columns/rows), zatímco blok byl
-- deklarovaný jako `timeline` (items). Ajv ho odmítl a sekce ukazovala jen
-- banner „Některé bloky se nepodařilo zobrazit". Oznámení komunity jsou
-- publikované články — tenhle blok je vydá ve tvaru, který timeline čeká.
--
-- Konfigurace (p_params):
--   limit   volitelné  default 20, strop 100
--   tag     volitelné  jen články, jejichž `tags` (text[]) obsahují PRÁVĚ
--                      tenhle štítek jako prvek (ne podřetězec)
--
-- Bezpečnost: SECURITY INVOKER — čte přes RLS volajícího; publikované články
-- jsou veřejné i na webu, takže blok nic neodkrývá. Prázdno je poctivé prázdno:
-- `items: []` s provenance, žádná výjimka.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.get_news_timeline_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  with cfg as (
    select
      least(greatest(coalesce((p_params->>'limit')::int, 20), 1), 100) as lim,
      nullif(trim(p_params->>'tag'), '')                               as tag
  ),
  vybrane as (
    select n.title_key, n.published_at, n.slug
    from public.news_articles n, cfg
    where n.is_published
      and n.published_at is not null
      -- ⛔ `tags` je text[], ne text. Řetězcové `ilike` na poli operátor nemá
      -- a CREATE FUNCTION selže UŽ PŘI VYTVOŘENÍ (check_function_bodies),
      -- takže spadne celý heals.sql a s ním krok migrace — naměřeno
      -- 2026-09-04: `core` se nenasadil a API leželo na 502.
      -- Štítek je PRVEK pole, ne podřetězec; rovnost je i pravdivější:
      -- 'novinky' by jinak potichu chytalo i 'novinkytest'.
      and (cfg.tag is null or cfg.tag = any(n.tags))
    order by n.published_at desc
    limit (select lim from cfg)
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'items', coalesce(
        (select jsonb_agg(jsonb_build_object(
            'at',        to_char(v.published_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
            'label_key', v.title_key)
          order by v.published_at desc)
         from vybrane v),
        '[]'::jsonb)),
    'provenance', jsonb_build_object(
      'source_slug',  'news_articles',
      'trace_id',     'news:timeline',
      'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'))
  );
$$;

REVOKE ALL ON FUNCTION public.get_news_timeline_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_news_timeline_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_news_timeline_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_or_create_public_chat_session.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_or_create_public_chat_session
-- Arguments: p_channel_id uuid, p_visitor_id text, p_metadata jsonb
-- Description: Find existing active session or create a new one, return session info with recent messages
-- Security: SECURITY DEFINER
-- Search path: public (set per-function below)
-- Source: aisha/db/migrations/20260410150000_public_chat_channels.sql

CREATE OR REPLACE FUNCTION public.get_or_create_public_chat_session(
  p_channel_id  uuid,
  p_visitor_id  text,
  p_metadata    jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_session record;
  v_messages jsonb;
BEGIN
  -- Try to find existing active session
  SELECT
    pcs.id,
    pcs.message_count
  INTO v_session
  FROM public.public_chat_sessions pcs
  WHERE pcs.channel_id = p_channel_id
    AND pcs.visitor_id = p_visitor_id
    AND pcs.status = 'active'
    AND pcs.updated_at > now() - interval '24 hours'
  ORDER BY pcs.created_at DESC
  LIMIT 1;

  IF v_session IS NULL THEN
    -- Create new session
    INSERT INTO public.public_chat_sessions (channel_id, visitor_id, visitor_metadata)
    VALUES (p_channel_id, p_visitor_id, p_metadata)
    RETURNING id, message_count INTO v_session;

    -- Increment channel session count
    UPDATE public.public_chat_channels
    SET total_sessions = total_sessions + 1
    WHERE id = p_channel_id;

    v_messages := '[]'::jsonb;
  ELSE
    -- Load last 20 messages for context
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object('role', m.role, 'content', m.content, 'created_at', m.created_at)
      ORDER BY m.created_at
    ), '[]'::jsonb) INTO v_messages
    FROM (
      SELECT role, content, created_at
      FROM public.public_chat_messages
      WHERE session_id = v_session.id
      ORDER BY created_at DESC
      LIMIT 20
    ) m;
  END IF;

  RETURN jsonb_build_object(
    'session_id', v_session.id,
    'is_new', v_session.message_count = 0,
    'message_count', v_session.message_count,
    'messages', v_messages
  );
END;
$$;

REVOKE ALL ON FUNCTION public.get_or_create_public_chat_session(uuid, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_or_create_public_chat_session(uuid, text, jsonb) TO authenticated;


