-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_pending_approval_count
-- Popis: Phase 4 dashboard StatBoxWidget — počet pending approvals (drift + rollback).
--        Bezpečně agreguje napříč integration_service_logs (přes WF_APPROVAL_GATE).
--        Last 24h window + filter na unresolved.
-- Volá: dashboard StatBox widget
-- Auth: any authenticated (counts only, no PII)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_pending_approval_count()
RETURNS int
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_count int := 0;
  v_caller uuid;
BEGIN
  -- Auth check: require authenticated user OR service_role (counts only, no PII)
  v_caller := auth.uid();
  IF v_caller IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role' THEN
    RAISE EXCEPTION 'Unauthorized: authentication required';
  END IF;

  SELECT count(*) INTO v_count
  FROM public.integration_service_logs
  WHERE action = 'approval_request_pending'
    AND status = 'success'
    AND created_at > now() - interval '24 hours'
    AND COALESCE(action_detail->>'resolved', 'false') = 'false';

  RETURN v_count;
END;
$$;

REVOKE ALL ON FUNCTION public.get_pending_approval_count() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_pending_approval_count() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_pending_approval_count() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_pending_batch_jobs.sql
-- -----------------------------------------------------------------------------

-- Function: get_pending_batch_jobs
-- Returns batch jobs that WF_BATCH_POLLER should poll next. Rate-limited per
-- job via last_polled_at (don't poll the same job more than once per 5min).

CREATE OR REPLACE FUNCTION public.get_pending_batch_jobs(
  p_limit int DEFAULT 50,
  p_min_poll_interval_seconds int DEFAULT 300
)
RETURNS TABLE (
  id uuid,
  provider text,
  external_batch_id text,
  status text,
  submitted_at timestamptz,
  last_polled_at timestamptz,
  request_count int,
  related_run_id uuid,
  agent_slug text,
  metadata jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  RETURN QUERY
  SELECT j.id, j.provider, j.external_batch_id, j.status,
         j.submitted_at, j.last_polled_at, j.request_count,
         j.related_run_id, j.agent_slug, j.metadata
  FROM ai_batch_jobs j
  WHERE j.status IN ('submitted', 'in_progress')
    AND (
      j.last_polled_at IS NULL
      OR j.last_polled_at < now() - make_interval(secs => p_min_poll_interval_seconds)
    )
  ORDER BY j.last_polled_at NULLS FIRST, j.submitted_at
  LIMIT GREATEST(1, p_limit);
END;
$$;

COMMENT ON FUNCTION public.get_pending_batch_jobs(int, int) IS
  'Lists batch jobs eligible for polling (status in submitted/in_progress, '
  'not polled within p_min_poll_interval_seconds).';

REVOKE ALL ON FUNCTION public.get_pending_batch_jobs(int, int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_pending_batch_jobs(int, int) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_pending_batch_jobs(int, int) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_pending_questionnaires_for_notifications.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_pending_questionnaires_for_notifications
-- Arguments: p_frequencies text[], p_current_date date, p_current_timestamp timestamptz
-- Description: Returns pending questionnaires for reminder notifications with timezone-aware period cutoffs.
-- Security: SECURITY DEFINER

CREATE OR REPLACE FUNCTION public.get_pending_questionnaires_for_notifications(
  p_current_date date,
  p_current_timestamp timestamptz,
  p_frequencies text[]
)
 RETURNS TABLE(
  due_date date,
  frequency text,
  questionnaire_code text,
  questionnaire_id uuid,
  questionnaire_title text,
  study_registration_id uuid,
  user_id uuid
)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reference_ts timestamptz;
BEGIN
  v_reference_ts := COALESCE(
    p_current_timestamp,
    (p_current_date::text || ' 00:00:00+00')::timestamptz,
    now()
  );

  RETURN QUERY
  WITH candidates AS (
    SELECT
      se.user_id,
      se.id AS study_registration_id,
      sq.questionnaire_id,
      q.code AS questionnaire_code,
      q.name AS questionnaire_title,
      COALESCE(sq.frequency_type, sq.questionnaire_type) AS frequency,
      tz.user_timezone,
      timezone(tz.user_timezone, v_reference_ts) AS local_now
    FROM study_registrations se
    JOIN studies s ON s.id = se.study_id AND s.is_active = true
    JOIN study_questionnaires sq ON sq.study_id = s.id AND sq.is_active = true
    JOIN questionnaires q ON q.id = sq.questionnaire_id AND q.is_active = true
    LEFT JOIN notification_preferences np ON np.user_id = se.user_id
    LEFT JOIN LATERAL (
      SELECT COALESCE(
        (
          SELECT tzn.name
          FROM pg_timezone_names tzn
          WHERE tzn.name = np.user_timezone
          LIMIT 1
        ),
        'UTC'
      ) AS user_timezone
    ) tz ON true
    WHERE se.status = 'active'
      AND COALESCE(sq.frequency_type, sq.questionnaire_type) = ANY(p_frequencies)
  ),
  with_cutoffs AS (
    SELECT
      c.user_id,
      c.study_registration_id,
      c.questionnaire_id,
      c.questionnaire_code,
      c.questionnaire_title,
      c.frequency,
      CASE
        WHEN c.frequency = 'monthly'
          THEN date_trunc('month', c.local_now) AT TIME ZONE c.user_timezone
        WHEN c.frequency = 'weekly'
          THEN date_trunc('week', c.local_now) AT TIME ZONE c.user_timezone
        ELSE date_trunc('day', c.local_now) AT TIME ZONE c.user_timezone
      END AS cutoff_at
    FROM candidates c
  )
  SELECT
    NULL::date AS due_date,
    c.frequency,
    c.questionnaire_code,
    c.questionnaire_id,
    c.questionnaire_title,
    c.study_registration_id,
    c.user_id
  FROM with_cutoffs c
  WHERE NOT EXISTS (
    SELECT 1
    FROM questionnaire_responses qr
    WHERE qr.user_id = c.user_id
      AND qr.questionnaire_id = c.questionnaire_id
      AND qr.completed_at >= c.cutoff_at
  )
  ORDER BY c.user_id;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.get_pending_questionnaires_for_notifications(DATE, TIMESTAMPTZ, TEXT[]) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.get_pending_questionnaires_for_notifications(DATE, TIMESTAMPTZ, TEXT[]) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_pending_questionnaires_for_notifications(DATE, TIMESTAMPTZ, TEXT[]) TO service_role;


