-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_rules_for_embedding.sql
-- -----------------------------------------------------------------------------

-- Function: get_rules_for_embedding
--
-- Returns published expert_rules that still need a content_embedding (or ALL of
-- them when p_force), for the svc-mcp-knowledge POST /embeddings/rules worker.
-- Idempotent: skips rules that already carry a content_embedding unless p_force,
-- so a cold-start embed-kickstart that re-runs produces processed:0 on the second
-- pass. Mirrors get_knowledge_items_for_embedding (the knowledge_items twin).
-- Service-role only — matches the route's verifyServiceRole gate.
CREATE OR REPLACE FUNCTION public.get_rules_for_embedding(p_force boolean DEFAULT false, p_batch_size integer DEFAULT 10, p_slug text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, slug text, title text, summary text, body_markdown text, ai_instructions text, ai_context_tags text[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required';
  END IF;

  IF p_batch_size > 100 THEN
    p_batch_size := 100;
  END IF;

  RETURN QUERY
  SELECT er.id,
         er.slug,
         er.title,
         er.summary,
         er.body_markdown,
         er.ai_instructions,
         er.ai_context_tags
  FROM expert_rules er
  WHERE er.status = 'published'
    AND (p_slug IS NULL OR er.slug = p_slug)
    AND (p_force OR er.content_embedding IS NULL)
  ORDER BY er.updated_at DESC NULLS LAST, er.created_at DESC
  LIMIT p_batch_size;
END;
$function$
;

REVOKE ALL ON FUNCTION get_rules_for_embedding(boolean, integer, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION get_rules_for_embedding(boolean, integer, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_runtimes_due_health_probe.sql
-- -----------------------------------------------------------------------------

-- Function: get_runtimes_due_health_probe
-- Returns ai_runtime_registry rows that WF_RUNTIME_HEALTH_PROBE should probe next.
-- Rate-limited per runtime via adapter_health_checked_at + EXPONENTIAL BACKOFF on
-- consecutive_failure_count (mirrors get_providers_due_health_probe):
--   0-2 failures: every p_min_interval_seconds (5min default)
--   3-4:          every 1h
--   5-7:          every 6h
--   8+:           every 24h (max — operator should investigate)
--
-- The probe TARGET is NOT stored on the row (a runtime's reachability endpoint —
-- e.g. OPENCLAW_URL — is env/config, not a static seed value); the WF's code node
-- resolves it per runtime_kind. This RPC only schedules WHICH runtimes are due.
--
-- Excludes:
--   * is_enabled=false   — operator explicitly disabled the runtime
--   * runtime_kind='human' — a human executor has no probeable service
--
-- NULL adapter_health_checked_at sorts first (never probed → highest priority), so
-- a newly-registered runtime gets probed on the very next workflow tick.

CREATE OR REPLACE FUNCTION public.get_runtimes_due_health_probe(
  p_min_interval_seconds int DEFAULT 300,
  p_limit                int DEFAULT 50
)
RETURNS TABLE (
  runtime_kind text,
  slug text,
  adapter_health text,
  adapter_health_checked_at timestamptz,
  consecutive_failure_count int
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT r.runtime_kind,
         r.slug,
         r.adapter_health,
         r.adapter_health_checked_at,
         r.consecutive_failure_count
  FROM   ai_runtime_registry r
  WHERE  r.is_enabled = true
    AND  r.runtime_kind <> 'human'
    AND  (
           r.adapter_health_checked_at IS NULL
        OR r.adapter_health_checked_at < now() - make_interval(secs =>
             CASE
               WHEN r.consecutive_failure_count <= 2 THEN p_min_interval_seconds
               WHEN r.consecutive_failure_count <= 4 THEN 3600     -- 1h
               WHEN r.consecutive_failure_count <= 7 THEN 21600    -- 6h
               ELSE                                        86400   -- 24h
             END
           )
         )
  ORDER  BY r.adapter_health_checked_at ASC NULLS FIRST
  LIMIT  p_limit;
END;
$$;

REVOKE ALL ON FUNCTION public.get_runtimes_due_health_probe(int, int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_runtimes_due_health_probe(int, int) TO service_role;

COMMENT ON FUNCTION public.get_runtimes_due_health_probe(int, int) IS
  'WF_RUNTIME_HEALTH_PROBE discovery RPC — enabled runtimes (excl. human) due for a reachability probe, exponential backoff, NULL-first. Service-role only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_scope_options.sql
-- -----------------------------------------------------------------------------

-- VOLBY POHLEDU — čím vším smí uživatel omezit, na co se dívá.
--
-- Přepínač pohledu potřebuje seznam možností. Ten seznam NESMÍ být v kódu klienta
-- ani v překladech: která firma existuje a kolik má dokladů je vlastnost PODNIKU
-- a mění se bez releasu. Klient se proto ptá a dostane, co v datech skutečně je —
-- včetně počtu, protože „firma se třemi doklady" a „firma s osmnácti tisíci" jsou
-- pro volbu pohledu různě zajímavé.
--
-- ⭐ VOLBY SE ODVOZUJÍ, NEUDRŽUJÍ
-- Žádný číselník, který by se rozešel se skutečností. Zdroj je buď registr dokladů
-- (pole hlavičky, typicky `owner_company` = za kterou z našich firem doklad je),
-- nebo twin parametr (`unit_landlord`, `unit_site`…). Obojí je táž otázka položená
-- nad jiným substrátem, takže je to jedna funkce s parametrem, ne dvě.
--
-- ⭐ 2026-09-06 (ADR-003 K5): druhů substrátu je šest, ne dva. Osy, které K5
-- jmenuje — druh entity, vazba, skupina, rodina šablon — se dosud odvodit
-- nedaly, takže přepínač uměl mluvit jen o dokladech a jednotkách. Každý nový
-- druh je tu VĚTEV NAD JINÝM SUBSTRÁTEM, ne nová funkce: otázka „co všechno
-- v datech je" je pořád jedna.
--
-- Konfigurace (p_params):
--   source : druh substrátu, výchozí 'registry'
--            'registry'  pole hlavičky dokladu (li_source_registry)
--            'twin'      hodnota twin parametru (twin_events.attrs code/value)
--            'twin_kind' DRUH ENTITY (twin_entities.entity_type)
--            'relation'  VAZBA (twin_relations.relation_kind, jen platné)
--            'label'     SKUPINA / štítek (story_labels.label nad druhem zdroje)
--            'template'  RODINA ŠABLON (jméno šablony běhu + počet běhů)
--   key    : název pole hlavičky (registry), kód twin parametru (twin),
--            resp. druh zdroje štítku (label; default 'actor')
--   entity_type : jen pro source='twin' — nad kterou doménou (default 'unit')
--   limit  : kolik voleb (default 50, strop 200)
--
-- SECURITY INVOKER → RLS rozhoduje: kdo na doklady nárok nemá, dostane prázdný
-- seznam, ne chybu. Přepínač tak sám od sebe nabízí jen to, co uživatel smí vidět,
-- a nemusí se to nikde podruhé hlídat.
--
-- Kontrakt: (jsonb) -> jsonb {data:{dim, options:[{value,count}]}, provenance}.

create or replace function public.get_scope_options(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with cfg as (
    select
      coalesce(nullif(p_params->>'source', ''), 'registry')          as zdroj,
      coalesce(nullif(p_params->>'key', ''),
               case when p_params->>'source' = 'label' then 'actor'
                    else 'owner_company' end)                          as klic,
      coalesce(nullif(p_params->>'entity_type', ''), 'unit')         as typ,
      least(coalesce(nullif(p_params->>'limit', '')::int, 50), 200)  as lim
  ),
  -- ⭐ 2026-09-29: výchozí osa `owner_company` čte GENEROVANÝ sloupec registru, ne
  -- `fields`. Agregace přes celý registr jinak rozbaluje JSON každého dokladu
  -- (riq jako správce: 777–973 ms; přes prostý sloupec 85–100 ms). Výsledek je
  -- TÝŽ: sloupec = `fields->'owner_company'->>'value'` a řádek s klíčem bez hodnoty
  -- (`fields ? klic`, hodnota NULL) by `souhrn` níž stejně zahodil. Ostatní klíče
  -- (dynamické) dál přes `fields`.
  z_registru as (
    select r.owner_company_value as hodnota
    from public.li_source_registry r, cfg
    where cfg.zdroj = 'registry'
      and cfg.klic = 'owner_company'
      and r.superseded_by is null
      and r.owner_company_value is not null
    union all
    select r.fields->(select klic from cfg)->>'value' as hodnota
    from public.li_source_registry r, cfg
    where cfg.zdroj = 'registry'
      and cfg.klic <> 'owner_company'
      and r.superseded_by is null
      and r.fields ? cfg.klic
  ),
  -- Twin varianta bere POSLEDNÍ hodnotu parametru per entita, aby se přejmenovaná
  -- firma nepočítala dvakrát (jednou pod starým a jednou pod novým jménem).
  z_twinu as (
    select distinct on (e.twin_id) e.attrs->>'value' as hodnota
    from public.twin_events e
    join public.twin_entities t on t.id = e.twin_id
    cross join cfg
    where cfg.zdroj = 'twin'
      and t.entity_type = cfg.typ
      and e.attrs->>'code' = cfg.klic
    order by e.twin_id, e.occurred_at desc
  ),
  -- DRUH ENTITY. Počet = kolik entit toho druhu je; „osob 812" a „firem 9" je
  -- pro volbu pohledu jiná informace než holý seznam.
  z_druhu as (
    select t.entity_type as hodnota
    from public.twin_entities t, cfg
    where cfg.zdroj = 'twin_kind'
  ),
  -- VAZBA. Jen platné vazby (valid_to is null) — zrušené členství není osa,
  -- pod kterou by se dnes někdo chtěl dívat.
  z_vazeb as (
    select r.relation_kind as hodnota
    from public.twin_relations r, cfg
    where cfg.zdroj = 'relation'
      and r.valid_to is null
  ),
  -- SKUPINA (štítek). `key` říká, nad jakým DRUHEM zdroje se ptáme (actor,
  -- story, campaign…), ne jméno konkrétní skupiny.
  z_stitku as (
    select l.label as hodnota
    from public.story_labels l, cfg
    where cfg.zdroj = 'label'
      and l.resource_type = cfg.klic
  ),
  -- RODINA ŠABLON. Hodnota je JMÉNO šablony, protože právě jménem šablony
  -- filtruje věž (get_timing_tower_block, parametr `template`); počet je počet
  -- běhů, takže šablona bez jediného běhu se nabízí až za těmi živými.
  z_sablon as (
    select tpl.name as hodnota
    from public.production_batches b
    join public.production_workflow_templates tpl on tpl.id = b.workflow_template_id
    cross join cfg
    where cfg.zdroj = 'template'
  ),
  vse as (
    select hodnota from z_registru
    union all select hodnota from z_twinu
    union all select hodnota from z_druhu
    union all select hodnota from z_vazeb
    union all select hodnota from z_stitku
    union all select hodnota from z_sablon
  ),
  souhrn as (
    select hodnota, count(*) as pocet
    from vse
    where hodnota is not null and btrim(hodnota) <> ''
    group by hodnota
    order by count(*) desc, hodnota
    limit (select lim from cfg)
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'dim', (select klic from cfg),
      'options', coalesce((
        select jsonb_agg(jsonb_build_object('value', s.hodnota, 'count', s.pocet)
                         order by s.pocet desc, s.hodnota)
        from souhrn s), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  case (select zdroj from cfg)
                        when 'twin'      then 'twin-core'
                        when 'twin_kind' then 'twin_entities'
                        when 'relation'  then 'twin_relations'
                        when 'label'     then 'story_labels'
                        when 'template'  then 'production_workflow_templates'
                        else 'li-source-registry' end,
      'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'scope-options:' || (select zdroj from cfg)
    )
  );
$$;

comment on function public.get_scope_options(jsonb) is
  'Volby přepínače pohledu ODVOZENÉ z dat (registr dokladů nebo twin parametr), s počty. Žádný číselník, který by se rozešel se skutečností; SECURITY INVOKER, takže nabídne jen to, na co má volající nárok.';

revoke all on function public.get_scope_options(jsonb) from public, anon;
grant execute on function public.get_scope_options(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_session_memory.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_session_memory
-- Arguments: p_conversation_id uuid
-- Security: SECURITY DEFINER
-- Source: Phase 4 — Agent Loop & Memory

CREATE OR REPLACE FUNCTION public.get_session_memory(p_conversation_id uuid)
 RETURNS TABLE(key text, value jsonb, expires_at timestamptz, updated_at timestamptz)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  RETURN QUERY
  SELECT sm.key, sm.value, sm.expires_at, sm.updated_at
  FROM ai_session_memory sm
  WHERE sm.conversation_id = p_conversation_id
    AND sm.user_id = auth.uid()
    AND (sm.expires_at IS NULL OR sm.expires_at > now())
  ORDER BY sm.updated_at DESC;
END;
$$;

REVOKE ALL ON FUNCTION public.get_session_memory(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_session_memory(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_shipping_cost.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_shipping_cost
-- Arguments: p_shipping_method text, p_country text, p_currency text, p_order_subtotal numeric, p_weight_grams integer
-- Description: Calculates shipping cost from shipment_settings with currency conversion.
--   Supports 6 methods, free shipping thresholds, weight surcharges.
-- Security: SECURITY DEFINER - public pricing helper (no sensitive data).

CREATE OR REPLACE FUNCTION public.get_shipping_cost(
  p_shipping_method text,
  p_country text DEFAULT NULL,
  p_currency text DEFAULT NULL,
  p_order_subtotal numeric DEFAULT NULL,
  p_weight_grams integer DEFAULT NULL
)
RETURNS numeric
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_rates jsonb;
  v_method jsonb;
  v_base_currency text := public.commerce_base_currency();
  v_amount_base numeric := 0;
  v_country text := upper(coalesce(p_country, ''));
  v_target_currency text;
  v_free_threshold numeric;
  v_weight_surcharge numeric := 0;
  v_max_weight_kg numeric;
BEGIN
  SELECT setting_value::jsonb
  INTO v_rates
  FROM public.shipment_settings
  WHERE setting_key = 'shipping_rates'
  LIMIT 1;

  IF v_rates IS NULL THEN
    v_rates := jsonb_build_object(
      'base_currency', public.commerce_base_currency(),
      'free_shipping_thresholds', jsonb_build_object(
        'CZ', 1500,
        'SK', 1500,
        'DE', 2000,
        'AT', 2000,
        'PL', 1500
      ),
      'methods', jsonb_build_object(
        'packeta_pickup', jsonb_build_object('default', 89, 'by_country', jsonb_build_object()),
        'packeta_zbox', jsonb_build_object('default', 79, 'by_country', jsonb_build_object()),
        'packeta_home', jsonb_build_object('default', 139, 'by_country', jsonb_build_object()),
        'carrier_pickup', jsonb_build_object('default', 99, 'by_country', jsonb_build_object()),
        'carrier_home', jsonb_build_object('default', 149, 'by_country', jsonb_build_object()),
        'personal_pickup', jsonb_build_object('default', 0, 'by_country', jsonb_build_object())
      )
    );
  END IF;

  v_base_currency := COALESCE(v_rates->>'base_currency', public.commerce_base_currency());

  -- Check free shipping threshold
  IF p_order_subtotal IS NOT NULL AND p_shipping_method <> 'personal_pickup' THEN
    IF v_country <> '' AND (v_rates->'free_shipping_thresholds' ? v_country) THEN
      v_free_threshold := COALESCE(
        NULLIF(v_rates->'free_shipping_thresholds'->>v_country, '')::numeric,
        0
      );
    ELSE
      v_free_threshold := COALESCE(
        NULLIF(v_rates->'free_shipping_thresholds'->>'default', '')::numeric,
        0
      );
    END IF;

    IF v_free_threshold > 0 AND p_order_subtotal >= v_free_threshold THEN
      RETURN 0;
    END IF;
  END IF;

  v_method := v_rates->'methods'->p_shipping_method;

  IF v_method IS NULL THEN
    RETURN 0;
  END IF;

  -- Base price (per country or default)
  IF v_country <> '' AND (v_method->'by_country' ? v_country) THEN
    v_amount_base := COALESCE(NULLIF(v_method->'by_country'->>v_country, '')::numeric, 0);
  ELSE
    v_amount_base := COALESCE(NULLIF(v_method->>'default', '')::numeric, 0);
  END IF;

  -- Weight surcharge (if configured)
  IF p_weight_grams IS NOT NULL AND (v_method ? 'weight_surcharge') THEN
    v_max_weight_kg := COALESCE(NULLIF(v_method->>'max_weight_kg', '')::numeric, 30);
    -- Return -1 to indicate "too heavy" for this method
    IF p_weight_grams > v_max_weight_kg * 1000 THEN
      RETURN -1;
    END IF;

    -- Example: +20 CZK per additional kg over 5kg
    IF p_weight_grams > 5000 AND (v_method ? 'surcharge_per_kg') THEN
      v_weight_surcharge := CEIL((p_weight_grams - 5000)::numeric / 1000)
        * COALESCE(NULLIF(v_method->>'surcharge_per_kg', '')::numeric, 0);
    END IF;
  END IF;

  v_amount_base := v_amount_base + v_weight_surcharge;
  v_target_currency := COALESCE(p_currency, v_base_currency);

  IF upper(v_target_currency) = upper(v_base_currency) THEN
    RETURN v_amount_base;
  END IF;

  RETURN public.convert_currency_amount(v_amount_base, v_base_currency, v_target_currency);
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.get_shipping_cost(text, text, text, numeric, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_shipping_cost(text, text, text, numeric, integer) TO anon, authenticated;


