-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_surface_actions_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_surface_actions_block
-- Popis: GENERICKÝ blok masky `action_form` (ADR-003, K4): vydá akce správy
--   dostupné VOLAJÍCÍMU pro daný druh cíle — z allowlistu surface_actions pod
--   RLS (aktivní + publikum), s deklarací polí, kterou renderer nakreslí jako
--   formulář. Identitu cíle nese klientský parametr (u restricted bloku jen přes
--   deklaraci client_params — get_block_data); bez identity blok vydá akce
--   s `target_id: null` (renderer je nabídne až po výběru záznamu).
--
-- Konfigurace (p_params):
--   target_kind  POVINNÉ  'twin' | 'actor' | 'story' | 'none'
--   id_param     volitelné jméno parametru s identitou (default podle druhu:
--                twin→twin_id, actor→user_id, story→story_id)
--   namespace    volitelné filtr na vlastníka řádků akcí
--
-- SECURITY INVOKER: seznam akcí je přesně to, co RLS volajícímu pustí — týž
-- filtr, který pak platí při submitu. Poctivá degradace: prázdné `actions`.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.get_surface_actions_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_kind     text := nullif(btrim(coalesce(p_params->>'target_kind', '')), '');
  v_ns       text := nullif(btrim(coalesce(p_params->>'namespace', '')), '');
  v_id_param text;
  v_id       text;
  v_now      timestamptz := now();
BEGIN
  IF v_kind IS NULL OR v_kind NOT IN ('twin','actor','story','none') THEN
    RETURN jsonb_build_object(
      'data', jsonb_build_object('target_kind', coalesce(v_kind, 'none'), 'target_id', NULL, 'actions', '[]'::jsonb),
      'provenance', jsonb_build_object('source_slug', 'surface_actions',
                                       'trace_id', 'surface-actions:missing_config', 'freshness_at', v_now));
  END IF;
  v_id_param := coalesce(nullif(btrim(coalesce(p_params->>'id_param', '')), ''),
                         CASE v_kind WHEN 'twin' THEN 'twin_id' WHEN 'actor' THEN 'user_id' WHEN 'story' THEN 'story_id' ELSE 'record_id' END);
  v_id := nullif(btrim(coalesce(p_params->>v_id_param, '')), '');
  IF v_id IS NOT NULL AND v_id !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    v_id := NULL;
  END IF;

  RETURN jsonb_build_object(
    'data', jsonb_build_object(
      'target_kind', v_kind,
      'target_id', v_id,
      'actions', coalesce((
        SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                 'slug',            a.action_slug,
                 'title_key',       a.title_key,
                 'description_key', a.description_key,
                 'fields',          (SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                                        'key',       f->>'key',
                                        'label_key', f->>'label_key',
                                        'type',      coalesce(f->>'type', 'text'),
                                        'required',  coalesce((f->>'required')::boolean, false),
                                        'options',   CASE WHEN jsonb_typeof(f->'options') = 'array' THEN f->'options' END,
                                        'default',   f->>'default'))
                                      ORDER BY ord), '[]'::jsonb)
                                     FROM jsonb_array_elements(coalesce(a.fields, '[]'::jsonb)) WITH ORDINALITY AS fs(f, ord)
                                     WHERE coalesce(f->>'key', '') ~ '^[a-z][a-z0-9_]*$'
                                       AND nullif(f->>'label_key', '') IS NOT NULL)))
               ORDER BY a.position, a.action_slug)
        FROM public.surface_actions a
        WHERE a.is_active
          AND a.target_kind = v_kind
          AND (v_ns IS NULL OR a.namespace = v_ns)
      ), '[]'::jsonb)),
    'provenance', jsonb_build_object(
      'source_slug', 'surface_actions',
      'trace_id', 'surface-actions:' || v_kind,
      'freshness_at', v_now));
END;
$$;

REVOKE ALL ON FUNCTION public.get_surface_actions_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_surface_actions_block(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_surface_layout.sql
-- -----------------------------------------------------------------------------

-- SECURITY INVOKER: o viditelnosti rozhoduje RLS (default deny). Uživatel bez grantu dostane
-- prázdný layout, ne chybu (acceptance kritérium multi-surface spec §3 — nevyzrazovat existenci).

create or replace function public.get_surface_layout(p_surface text)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  select jsonb_build_object(
    'schema_version', 1,
    'surface', p_surface,
    'blocks', coalesce(
      jsonb_agg(
        -- strip_nulls: blok bez deklarované prezentace klíč vůbec nenese —
        -- starší nasazený shell (schema bez 'presentation') by na null spadl
        -- a s additionalProperties:false by zahodil CELÝ layout.
        jsonb_strip_nulls(jsonb_build_object(
          'block_slug', b.block_slug,
          'block_type', b.block_type,
          'title_key',  b.title_key,
          'position',   l.position,
          -- Uspořádání je vlastnost KONFIGURACE bloku (DATA), ne kódu: shell
          -- dostane nápovědu a neznámou hodnotu ignoruje (degradace na default).
          'presentation', b.source_params->>'presentation'
        ))
        -- Tiebreak block_slug: bez něj je pořadí při shodné position nedeterministické
        -- (naměřeno 07-27 — 4 kolize na tehdejší 'mobile' skládce, layout se mohl
        -- přeskládat mezi voláními).
        order by l.position, b.block_slug
      ) filter (where b.id is not null),
      '[]'::jsonb
    )
  )
  from public.surface_layouts l
  join public.surface_blocks b on b.id = l.block_id and b.is_active
  where l.surface = p_surface
    and l.is_active;
$$;

-- Grants: authenticated + service_role (NOT anon, #566 floor); RLS on the underlying
-- tables is the real access boundary (SECURITY INVOKER — runs as the caller).
REVOKE ALL ON FUNCTION public.get_surface_layout(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_surface_layout(text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_surface_layout_ui.sql
-- -----------------------------------------------------------------------------

-- get_surface_layout_ui — UI METADATA bloků sekce: čím smí uživatel blok ovládat.
--
-- Blok smí vzít od klienta parametry, které jeho konfigurace deklaruje
-- (`source_params.client_params`, viz surface_client_params_filter), jenže extranet
-- o nich nevěděl — měsíc knihy faktur, „jen nad rok“ u pohledávek ani hledání nešlo
-- nikde nastavit (2026-09-29, náčrtek majitele „Smlouvy a nájmy“). Tahle funkce shellu
-- řekne, JAK blok nabídnout: deklarace parametrů (typ, druh ovladače, popisky),
-- výchozí řazení tabulky a zda nad ní ukázat hledání.
--
-- ⭐ SAMOSTATNÁ FUNKCE, NE KLÍČ V LAYOUTU. Schéma layoutu je uzavřené a Ajv je
-- all-or-nothing: nový klíč u bloku by starší nasazený shell přinutil zahodit CELÝ
-- layout sekce. Starý shell tuhle funkci nevolá, takže pořadí nasazení DB × extranet
-- je v obou směrech bezpečné.
--
-- Vydává JEN deklarativní klíče (client_params, default_sort, search) — nikdy celou
-- konfiguraci bloku (ta smí nést věci, které klient vidět nemá).
--
-- SECURITY INVOKER: tytéž řádky jako get_surface_layout (RLS + publikum layoutu).
--
-- Contract: (text) -> jsonb {schema_version:1, surface, blocks:{<block_slug>:{client_params?, default_sort?, search?}}}.
create or replace function public.get_surface_layout_ui(p_surface text)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  select jsonb_build_object(
    'schema_version', 1,
    'surface', p_surface,
    'blocks', coalesce(
      jsonb_object_agg(
        b.block_slug,
        jsonb_strip_nulls(jsonb_build_object(
          'client_params', case when jsonb_typeof(b.source_params->'client_params') = 'object'
                                then b.source_params->'client_params' end,
          'default_sort',  case when jsonb_typeof(b.source_params->'default_sort') = 'object'
                                then b.source_params->'default_sort' end,
          'search',        case when b.source_params->'search' = 'true'::jsonb
                                then true end
        ))
      ) filter (where b.source_params ?| array['client_params', 'default_sort', 'search']),
      '{}'::jsonb
    )
  )
  from public.surface_layouts l
  join public.surface_blocks b on b.id = l.block_id and b.is_active
  where l.surface = p_surface
    and l.is_active;
$$;

comment on function public.get_surface_layout_ui(text) is
  'UI metadata of a section''s blocks for the shell: declared client_params (typed controls), default_sort and search flag. Separate from get_surface_layout so an older shell never sees an unknown layout key.';

revoke all on function public.get_surface_layout_ui(text) from public, anon;
grant execute on function public.get_surface_layout_ui(text) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_surface_scope_axes.sql
-- -----------------------------------------------------------------------------

-- OSY POHLEDU PRO SEKCI — deklarace z dat, volby odvozené z dat.
--
-- Klient se ptá JEDNOU na sekci a dostane hotový přepínač: které osy smí použít
-- (řádky `surface_scope_axes`, které mu RLS pustí) a jaké volby na nich reálně
-- existují (`get_scope_options` nad deklarovaným substrátem). Dřív měl klient
-- osy v konstantě a volal options per osa — seznam os tím byl v KÓDU a nesl
-- jména věcí jedné instance (naměřeno 2026-09-06, viz surface_scope_axes).
--
-- ⭐ Osa bez jediné volby se NEVYDÁ. Přepínač, který nabízí prázdnou osu, lže
-- o tom, že je čím filtrovat; a instance, která osu deklaruje „do zásoby",
-- nemá mít poloprázdnou lištu, dokud data nedorostou.
--
-- SECURITY INVOKER dvakrát: RLS rozhoduje, které OSY volající vidí, a táž
-- pravidla platí uvnitř `get_scope_options` pro VOLBY. Nikde se neobchází.
--
-- Konfigurace (p_params):
--   surface : sekce, pro kterou se osy ptají (povinné; osa s prázdným
--             `surfaces` platí pro všechny sekce)
--   limit   : kolik voleb na osu (default 50, strop 200) — postoupí dál
--
-- Kontrakt: (jsonb) -> jsonb
--   {data:{surface, axes:[{axis_key,title_key,dim,options:[{value,count}]}]},
--    provenance}

create or replace function public.get_surface_scope_axes(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with cfg as (
    select
      nullif(btrim(coalesce(p_params->>'surface', '')), '')            as sekce,
      least(coalesce(nullif(p_params->>'limit', '')::int, 50), 200)    as lim
  ),
  -- ⛔ MATERIALIZED = optimalizační plot, ne kosmetika (naměřeno 2026-09-29
  -- na produkci). Bez něj planner CTE vložil do dotazu, filtr
  -- `jsonb_array_length(options) > 0` z `s_volbami` sjel do skenu os a
  -- podmínka „osa patří sekci" zůstala jako Join Filter NAD ním — drahé
  -- `get_scope_options` (sken registru, ~0,9 s) se tak spočítalo i pro sekci,
  -- kde osa vůbec není, a pak se zahodilo. Sekce bez osy 807–939 → 1–2 ms,
  -- výstup md5 shodný. Druhý `materialized` na `s_volbami` nepomůže (změřeno).
  osy as materialized (
    select a.axis_key, a.title_key, a.dim, a.params, a.position
    from public.surface_scope_axes a, cfg
    where a.is_active
      and (jsonb_array_length(a.surfaces) = 0
           or (cfg.sekce is not null and a.surfaces ? cfg.sekce))
  ),
  s_volbami as (
    select o.axis_key, o.title_key, o.dim, o.position,
           coalesce(
             public.get_scope_options(o.params || jsonb_build_object('limit', (select lim from cfg)))
               ->'data'->'options',
             '[]'::jsonb) as options
    from osy o
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'surface', (select sekce from cfg),
      'axes', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'axis_key',  v.axis_key,
                 'title_key', v.title_key,
                 'dim',       v.dim,
                 'options',   v.options)
               order by v.position, v.axis_key)
        from s_volbami v
        where jsonb_array_length(v.options) > 0), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'surface_scope_axes',
      'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'scope-axes:' || coalesce((select sekce from cfg), '-')
    )
  );
$$;

comment on function public.get_surface_scope_axes(jsonb) is
  'Declared view axes for one surface section, each with options derived from data. Axes are rows in surface_scope_axes (instance overlay); SECURITY INVOKER so RLS decides both which axes and which options the caller sees. An axis with no options is not returned.';

revoke all on function public.get_surface_scope_axes(jsonb) from public, anon;
grant execute on function public.get_surface_scope_axes(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_symptom_catalog.sql
-- -----------------------------------------------------------------------------

-- Function: get_symptom_catalog
-- Purpose: Returns localized symptom catalog (official entries)
-- Access: authenticated + anon (public catalog)
-- Security: SECURITY DEFINER (anon needs access)

CREATE OR REPLACE FUNCTION public.get_symptom_catalog(
  p_locale TEXT DEFAULT 'en',
  p_category TEXT DEFAULT NULL
)
RETURNS TABLE (
  id UUID,
  code TEXT,
  category TEXT,
  icon TEXT,
  color TEXT,
  default_severity_scale INTEGER,
  sort_order INTEGER,
  is_active BOOLEAN,
  name TEXT,
  description TEXT
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  RETURN QUERY
  SELECT
    syc.id,
    syc.code,
    syc.category,
    syc.icon,
    syc.color,
    syc.default_severity_scale,
    syc.sort_order,
    syc.is_active,
    COALESCE(
      (SELECT t.value FROM translations t WHERE t.namespace = 'symptom_catalog' AND t.key = syc.code || '.name' AND t.locale = p_locale),
      (SELECT t.value FROM translations t WHERE t.namespace = 'symptom_catalog' AND t.key = syc.code || '.name' AND t.locale = 'en'),
      syc.code
    ) AS name,
    COALESCE(
      (SELECT t.value FROM translations t WHERE t.namespace = 'symptom_catalog' AND t.key = syc.code || '.description' AND t.locale = p_locale),
      (SELECT t.value FROM translations t WHERE t.namespace = 'symptom_catalog' AND t.key = syc.code || '.description' AND t.locale = 'en'),
      ''
    ) AS description
  FROM symptom_catalog syc
  WHERE syc.is_active = true
    AND (p_category IS NULL OR syc.category = p_category)
  ORDER BY syc.sort_order, syc.code;
END;
$$;

REVOKE ALL ON FUNCTION public.get_symptom_catalog(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_symptom_catalog(text, text) TO anon;
GRANT EXECUTE ON FUNCTION public.get_symptom_catalog(text, text) TO authenticated;

COMMENT ON FUNCTION public.get_symptom_catalog(text, text) IS 'Returns localized symptom catalog. Translations from translations table, fallback to EN then code.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_system_config.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_system_config
-- Arguments: p_key text DEFAULT NULL, p_with_meta boolean DEFAULT false
-- Description: Get system configuration. If p_key is NULL, returns all public configs as object.
--              If p_with_meta is true and p_key is provided, returns object with value + updated_at.
-- Security: SECURITY DEFINER - public system configuration.
-- @security: public
-- @audit: none

DROP FUNCTION IF EXISTS public.get_system_config(text);

CREATE OR REPLACE FUNCTION public.get_system_config(
  p_key text DEFAULT NULL,
  p_with_meta boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  IF p_key IS NOT NULL THEN
    IF p_with_meta THEN
      SELECT jsonb_build_object(
        'key', key,
        'value', value,
        'updated_at', updated_at
      ) INTO v_result
      FROM system_config
      WHERE key = p_key AND (is_public = true OR auth.uid() IS NOT NULL);

      RETURN COALESCE(
        v_result,
        jsonb_build_object(
          'key', p_key,
          'value', '{}'::jsonb,
          'updated_at', NULL
        )
      );
    END IF;

    -- Return single config value
    SELECT value INTO v_result
    FROM system_config
    WHERE key = p_key AND (is_public = true OR auth.uid() IS NOT NULL);
  ELSE
    -- Return all public configs as object
    SELECT jsonb_object_agg(key, value) INTO v_result
    FROM system_config
    WHERE is_public = true OR auth.uid() IS NOT NULL;
  END IF;

  RETURN COALESCE(v_result, '{}'::jsonb);
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.get_system_config(text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_system_config(text, boolean) TO public;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_spawn_claude_cli_run.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_spawn_claude_cli_run
-- Description: Enqueue an AISHA-spawned Claude Code CLI run on the execution
--   plane (agent_runs, kind='claude_cli_task'). The caller (Dirigent task-picker
--   UI / n8n spawner) hands a story-derived prompt + branch in p_inputs; the
--   svc-agent-runner picks the row up, creates a per-run git worktree, mounts it
--   into an isolated container, and launches `claude -p`. E0 admission
--   (fn_admit_clow) gates the run: deny refuses loudly, ask creates the run HELD
--   pending approval (approve_claude_run), allow proceeds — and every dispatch
--   mints an ai_decisions row (I1) threaded onto the run.
-- Security: SECURITY DEFINER, grants to authenticated.

-- Signature changed (added p_max_inflight) — drop the prior 5-arg overload so a
-- 5-positional call is never ambiguous between it and the new default-arg form.
DROP FUNCTION IF EXISTS public.fn_spawn_claude_cli_run(text, text, jsonb, text, text);
-- p_cli_slug appended (default claude-cli) so the SAME spawn drives ANY cli:<slug>
-- tool — claude-cli or codex-cli. The image picks the agent (docker/agent-claude vs
-- agent-codex), the slug drives admission (fn_admit_clow checks cli:<slug>
-- availability — a disabled/absent tool denies, so nothing tool-specific is
-- hardcoded here) + the I1 journal. DROP the prior 6-arg form so a 6-positional
-- call is never ambiguous against the new default-7th.
DROP FUNCTION IF EXISTS public.fn_spawn_claude_cli_run(text, text, jsonb, text, text, int);

CREATE OR REPLACE FUNCTION public.fn_spawn_claude_cli_run(
  p_image       text,
  p_source      text,
  p_inputs      jsonb,                              -- {story_id, prompt, base_ref, branch, auth_mode, context_profile}
  p_profile     text DEFAULT 'kata-dragonball',     -- workspace-friendly VMM isolation
  p_source_ref  text DEFAULT NULL,                  -- branch carrier (falls back to p_inputs->>'branch')
  p_max_inflight int DEFAULT NULL,                  -- override; else resolved dynamically (see below)
  p_cli_slug    text DEFAULT 'claude-cli'           -- which cli:<slug> tool: 'claude-cli' | 'codex-cli'
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_run_id       uuid;
  v_admit        jsonb;
  v_verdict      text;
  v_awaiting     text;
  v_approval_req boolean := false;
  v_decision_id  uuid;
  v_story_id     uuid := NULLIF(p_inputs->>'story_id', '')::uuid;
  -- Queue-depth ceiling resolved DYNAMICALLY: explicit arg → system_config
  -- ('agent_runner'.max_inflight, tunable at runtime) → conservative fail-safe.
  v_max_inflight int := GREATEST(
    COALESCE(
      p_max_inflight,
      NULLIF(public.get_system_config('agent_runner')->>'max_inflight', '')::int,
      50
    ), 1);
BEGIN
  -- JIT-provision the caller row so requested_by FK never trips (KC user with a
  -- valid JWT but no aisha_auth.users row yet). See ensure_current_user.
  PERFORM public.ensure_current_user();

  -- p_image may be empty: a producer (Dirigent UI / n8n) need not know the agent
  -- image — the svc-agent-runner defaults it from AGENT_CLAUDE_IMAGE at execution.
  IF p_inputs IS NULL OR NULLIF(p_inputs->>'prompt', '') IS NULL THEN
    RAISE EXCEPTION 'fn_spawn_claude_cli_run: p_inputs.prompt required' USING ERRCODE = '22023';
  END IF;

  -- E0 admission (replaces the spend-only gate). Composes ALL FOUR derived axes —
  -- spend + runtime-availability (the cli:claude-cli registry row must be enabled +
  -- adapter-live) + capability-match + risk — into one verdict. A CLI run writes
  -- code, reaches the network, and uses tools, so the clow declares those needs;
  -- fn_admit_clow derives the risk band from the runtime's side_effect_class.
  v_admit := public.fn_admit_clow(
    jsonb_build_object(
      'purpose',        'claude_cli_task',
      'runtime',        'cli',
      'cli_slug',       p_cli_slug,
      'task_kind',      'claude_cli_task',
      'needs_write',    true,
      'needs_internet', true,
      'needs_tools',    true
    ),
    jsonb_build_object('story_id', v_story_id)
  );
  v_verdict  := v_admit->>'decision';
  v_awaiting := v_admit->>'awaiting';

  -- deny → refuse loudly (spend over budget, runtime disabled, capability mismatch,
  -- or risk above the deny ceiling). The run is never created.
  IF v_verdict = 'deny' THEN
    RAISE EXCEPTION USING
      MESSAGE = format('admission_deny: claude_cli_task refused — %s (%s)',
        v_admit->>'reason_code', COALESCE(v_awaiting, 'admission_denied')),
      ERRCODE = 'P0001';
  END IF;

  -- ask → the run IS created but HELD pending human approval (approval_required +
  -- approved_at IS NULL); claim_queued_claude_run skips it until approve_claude_run
  -- clears it via Mission Control. allow → proceeds immediately.
  v_approval_req := (v_verdict = 'ask');

  -- Anti-pile-up at the SOURCE (the backlog the runner later drains into
  -- containers). Two guards, both bound how many rows can ever sit queued:
  --   1) idempotency: never two concurrently-active runs for the SAME story, so a
  --      retrying producer (n8n/client) is ABSORBED, not multiplied — the root
  --      reason "dozens of queued rows" can form.
  --   2) global queued+running ceiling: even across distinct stories / NULL-story
  --      runs, the total in-flight backlog cannot exceed p_max_inflight, so a
  --      poller restart can never face an unbounded queue to drain.
  IF v_story_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.agent_runs r
    WHERE r.kind = 'claude_cli_task'
      AND r.status IN ('queued', 'running')
      AND NULLIF(r.inputs->>'story_id', '')::uuid = v_story_id
  ) THEN
    RAISE EXCEPTION USING
      MESSAGE = format('claude_cli_task already active for story %s', v_story_id),
      ERRCODE = 'P0001';
  END IF;

  IF (
    SELECT count(*) FROM public.agent_runs
    WHERE kind = 'claude_cli_task' AND status IN ('queued', 'running')
  ) >= v_max_inflight THEN
    RAISE EXCEPTION USING
      MESSAGE = format('claude_cli_task queue depth at limit (%s) — try later', v_max_inflight),
      ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.agent_runs (kind, profile, image, requested_by, source, source_ref, inputs,
                                 approval_required, awaiting)
  VALUES (
    'claude_cli_task',
    p_profile,
    p_image,
    auth.uid(),
    p_source,
    COALESCE(p_source_ref, NULLIF(p_inputs->>'branch', '')),
    p_inputs,
    v_approval_req,
    CASE WHEN v_approval_req THEN v_awaiting ELSE NULL END
  )
  RETURNING id INTO v_run_id;

  -- I1 — journal the dispatch: mint the single ai_decisions row (the only writer is
  -- fn_record_execution_decision) carrying the admission verdict, and thread its id
  -- onto the run. Matches direct_llm/openclaw/hermes — every dispatch is journaled.
  v_decision_id := public.fn_record_execution_decision(
    jsonb_build_object(
      'clow_purpose',      'claude_cli_task',
      'runtime',           'cli',
      'cli_slug',          p_cli_slug,
      'backend_kind',      'cli',
      'admission_verdict', v_verdict,
      'risk_level',        v_admit->'axis_results'->'risk'->>'level',
      'approval_required', v_approval_req,
      'resolution_source', 'policy',  -- the verdict is policy-driven (spend + risk thresholds); precise source in reason + decision_json
      'reason',            format('fn_spawn_claude_cli_run admission %s', v_verdict),
      'cost',              v_admit->'axis_results'->'spend'->'detail'->>'estimate_used'
    ),
    v_run_id,
    v_story_id
  );
  UPDATE public.agent_runs SET decision_id = v_decision_id WHERE id = v_run_id;

  -- Audit breadcrumb (without the prompt body — may be large / sensitive); now
  -- carries the admission verdict + the decision id for traceability.
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'agent_run.spawned',
          jsonb_build_object(
            'run_id', v_run_id,
            'kind', 'claude_cli_task',
            'story_id', v_story_id,
            'source', p_source,
            'profile', p_profile,
            'admission_verdict', v_verdict,
            'approval_required', v_approval_req,
            'decision_id', v_decision_id));

  RETURN v_run_id;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_spawn_claude_cli_run(text, text, jsonb, text, text, int, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_spawn_claude_cli_run(text, text, jsonb, text, text, int, text) TO authenticated;
-- service_role: a SYSTEM-spawned CLI run (the reflection cli RuntimeAdapter, or the
-- svc-agent-runner POST /runs executor) calls this with no human user — requested_by
-- lands NULL. Same admission (fn_admit_clow accepts service_role) + journal apply.
GRANT EXECUTE ON FUNCTION public.fn_spawn_claude_cli_run(text, text, jsonb, text, text, int, text) TO service_role;

COMMENT ON FUNCTION public.fn_spawn_claude_cli_run(text, text, jsonb, text, text, int, text) IS
  'Enqueue an AISHA-spawned Claude CLI run (agent_runs kind=claude_cli_task) gated by E0 admission (fn_admit_clow: spend + runtime-availability + capability + risk). deny refuses; ask creates the run held pending approval (approve_claude_run); allow proceeds. Every dispatch mints an ai_decisions row (fn_record_execution_decision, I1) threaded onto the run. Anti-pile-up: one active run per story + a global queued+running ceiling (p_max_inflight). The svc-agent-runner consumes a claimable (allow or approved) row, builds a per-run worktree, and launches claude.';


