-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_biomarker_reference_ranges_localized.sql
-- -----------------------------------------------------------------------------

-- Function: get_biomarker_reference_ranges_localized
-- Purpose: Returns biomarker reference ranges with localized name and description
-- Created: 2026-02-03

CREATE OR REPLACE FUNCTION public.get_biomarker_reference_ranges_localized(
  p_locale TEXT DEFAULT 'en',
  p_category TEXT DEFAULT NULL
)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result JSONB;
  v_locale TEXT;
BEGIN
  -- Validate locale (supported: cs, de, en, fr, ru, th)
  v_locale := CASE
    WHEN p_locale IN ('cs', 'de', 'en', 'fr', 'ru', 'th') THEN p_locale
    ELSE 'en'
  END;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', brr.id,
      'biomarker_key', brr.biomarker_key,
      'name', public.get_translation_value_with_fallback(
        brr.name_key, 'biomarkers', v_locale, 'en', NULL
      ),
      'description', public.get_translation_value_with_fallback(
        brr.description_key, 'biomarkers', v_locale, 'en', NULL
      ),
      'category', brr.category,
      'unit', brr.unit,
      'min_value', brr.min_value,
      'max_value', brr.max_value,
      'optimal_min', brr.optimal_min,
      'optimal_max', brr.optimal_max,
      'critical_low', brr.critical_low,
      'critical_high', brr.critical_high,
      'is_active', brr.is_active
    ) ORDER BY brr.category, brr.biomarker_key
  )
  INTO v_result
  FROM biomarker_reference_ranges brr
  WHERE brr.is_active = true
    AND (p_category IS NULL OR brr.category = p_category);

  RETURN COALESCE(v_result, '[]'::JSONB);
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.get_biomarker_reference_ranges_localized(TEXT, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_biomarker_reference_ranges_localized(TEXT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_biomarker_reference_ranges_localized(TEXT, TEXT) TO anon;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_combined_consent_requirements_localized.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_combined_consent_requirements_localized
-- Arguments: p_study_id uuid, p_locale text
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:42+01:00

CREATE OR REPLACE FUNCTION public.get_combined_consent_requirements_localized(p_study_id uuid, p_locale text DEFAULT 'en'::text)
 RETURNS TABLE(id uuid, consent_template_id uuid, is_required boolean, sort_order integer, template_key text, title text, content text, version text, requires_signature boolean, study_id uuid, study_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_parent_study_id UUID;
  v_locale TEXT;
BEGIN
  v_locale := COALESCE(p_locale, 'en');
  
  -- Get parent study if exists
  SELECT s.parent_study_id INTO v_parent_study_id
  FROM studies s WHERE s.id = p_study_id;
  
  RETURN QUERY
  WITH all_study_ids AS (
    -- Include target study
    SELECT p_study_id AS sid
    UNION
    -- Include parent umbrella study if exists
    SELECT v_parent_study_id WHERE v_parent_study_id IS NOT NULL
  ),
  study_consents AS (
    SELECT 
      scr.id,
      scr.consent_template_id,
      scr.is_required,
      scr.sort_order,
      ct.template_key,
      public.get_translation_value_with_fallback(
        ct.title_key,
        'consents',
        v_locale,
        COALESCE(NULLIF(ct.base_locale, ''), 'en'),
        COALESCE(ct.template_key, ct.code, '')
      ) AS title,
      public.get_translation_value_with_fallback(
        ct.content_key,
        'consents',
        v_locale,
        COALESCE(NULLIF(ct.base_locale, ''), 'en'),
        ''
      ) AS content,
      ct.version,
      ct.requires_signature,
      scr.study_id,
      st.name AS study_name,
      -- Priority: umbrella first, then child
      CASE WHEN st.is_umbrella THEN 0 ELSE 1 END AS priority
    FROM study_consent_requirements scr
    JOIN consent_templates ct ON ct.id = scr.consent_template_id
    JOIN studies st ON st.id = scr.study_id
    WHERE scr.study_id IN (SELECT sid FROM all_study_ids)
      AND ct.is_active = true
  )
  SELECT DISTINCT ON (sc.template_key)
    sc.id,
    sc.consent_template_id,
    sc.is_required,
    sc.sort_order,
    sc.template_key,
    sc.title,
    sc.content,
    sc.version,
    sc.requires_signature,
    sc.study_id,
    sc.study_name
  FROM study_consents sc
  ORDER BY sc.template_key, sc.priority, sc.sort_order;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.get_combined_consent_requirements_localized(p_study_id uuid, p_locale text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_combined_consent_requirements_localized(p_study_id uuid, p_locale text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_combined_study_consents.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_combined_study_consents
-- Arguments: p_study_id uuid, p_locale text
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:42+01:00

CREATE OR REPLACE FUNCTION public.get_combined_study_consents(p_study_id uuid, p_locale text DEFAULT 'en'::text)
 RETURNS TABLE(id uuid, consent_key text, title text, description text, checkbox_label text, is_required boolean, display_order integer, document_url text, study_code text, is_umbrella boolean)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_parent_study_id UUID;
  v_locale TEXT;
BEGIN
  v_locale := lower(split_part(coalesce(p_locale, 'en'), '-', 1));

  -- Get parent study ID
  SELECT s.parent_study_id INTO v_parent_study_id
  FROM studies s
  WHERE s.id = p_study_id
  LIMIT 1;
  
  -- Return combined consents: umbrella first, then child study
  -- Use DISTINCT ON to deduplicate by consent_key, preferring child study entries.
  RETURN QUERY
  WITH all_consents AS (
    -- Umbrella study consents (if this study has a parent)
    SELECT 
      sci.id,
      sci.consent_key,
      public.get_translation_value_with_fallback(sci.title_key, 'consents', v_locale, 'en', NULL) as title,
      public.get_translation_value_with_fallback(sci.description_key, 'consents', v_locale, 'en', NULL) as description,
      public.get_translation_value_with_fallback(sci.checkbox_label_key, 'consents', v_locale, 'en', NULL) as checkbox_label,
      sci.is_required,
      sci.display_order,
      sci.document_url,
      s.code as study_code,
      true as is_umbrella,
      1 as priority -- Lower priority for umbrella
    FROM study_consent_items sci
    JOIN studies s ON s.id = sci.study_id
    WHERE sci.study_id = v_parent_study_id
      AND sci.is_active = true
      AND v_parent_study_id IS NOT NULL
    
    UNION ALL
    
    -- Child study consents (current study)
    SELECT 
      sci.id,
      sci.consent_key,
      public.get_translation_value_with_fallback(sci.title_key, 'consents', v_locale, 'en', NULL) as title,
      public.get_translation_value_with_fallback(sci.description_key, 'consents', v_locale, 'en', NULL) as description,
      public.get_translation_value_with_fallback(sci.checkbox_label_key, 'consents', v_locale, 'en', NULL) as checkbox_label,
      sci.is_required,
      sci.display_order,
      sci.document_url,
      s.code as study_code,
      false as is_umbrella,
      2 as priority -- Higher priority for child study
    FROM study_consent_items sci
    JOIN studies s ON s.id = sci.study_id
    WHERE sci.study_id = p_study_id
      AND sci.is_active = true
  )
  SELECT DISTINCT ON (ac.consent_key)
    ac.id,
    ac.consent_key,
    ac.title,
    ac.description,
    ac.checkbox_label,
    ac.is_required,
    ac.display_order,
    ac.document_url,
    ac.study_code,
    ac.is_umbrella
  FROM all_consents ac
  ORDER BY ac.consent_key, ac.priority DESC, ac.display_order;
END;
$function$
;

