-- -----------------------------------------------------------------------------

-- Function: public.get_my_achievements
-- Arguments: p_locale TEXT (optional, defaults to 'en')
-- Description: Returns user achievements with localized titles and descriptions.
--              Falls back to English if translation not found.
-- Security: SECURITY DEFINER - runs with owner privileges.
-- Updated: 2026-01-25

CREATE OR REPLACE FUNCTION public.get_my_achievements(
  p_locale TEXT DEFAULT 'en'
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_locale TEXT;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Validate locale (supported: cs, de, en, fr, ru, th)
  v_locale := CASE
    WHEN p_locale IN ('cs', 'de', 'en', 'fr', 'ru', 'th') THEN p_locale
    ELSE 'en'
  END;

  -- First check for new achievements
  PERFORM check_user_achievements(v_user_id);

  RETURN jsonb_build_object(
    'unlocked', (
      SELECT jsonb_agg(jsonb_build_object(
        'id', a.id,
        'code', a.code,
        'name', public.get_translation_value_with_fallback(
          a.title_key, 'achievements', v_locale, 'en', a.title
        ),
        'description', public.get_translation_value_with_fallback(
          a.description_key, 'achievements', v_locale, 'en', a.description
        ),
        'icon', a.icon,
        'category', a.category,
        'points_reward', a.points_reward,
        'is_unlocked', true,
        'unlocked_at', ua.unlocked_at
      ) ORDER BY ua.unlocked_at DESC)
      FROM user_achievements ua
      JOIN achievements a ON ua.achievement_id = a.id
      WHERE ua.user_id = v_user_id
    ),
    'available', (
      SELECT jsonb_agg(jsonb_build_object(
        'id', a.id,
        'code', a.code,
        'name', public.get_translation_value_with_fallback(
          a.title_key, 'achievements', v_locale, 'en', a.title
        ),
        'description', public.get_translation_value_with_fallback(
          a.description_key, 'achievements', v_locale, 'en', a.description
        ),
        'icon', a.icon,
        'category', a.category,
        'points_reward', a.points_reward,
        'is_unlocked', false,
        'unlocked_at', NULL,
        'requirement_type', a.requirement_type,
        'requirement_value', a.requirement_value
      ) ORDER BY a.requirement_value)
      FROM achievements a
      WHERE a.is_active = true
        AND NOT EXISTS (
          SELECT 1 FROM user_achievements ua
          WHERE ua.user_id = v_user_id AND ua.achievement_id = a.id
        )
    )
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.get_my_achievements(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_my_achievements(TEXT) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_my_pending_consents.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_my_pending_consents
-- Arguments: p_locale text
-- Description: Returns the caller's OUTSTANDING (not-yet-accepted, in-window) consent
--   requirements across their active study registrations, localized. This is the
--   first-class "what do I still need to sign" reader that previously did not exist —
--   the client had to diff get_(combined_)consent_requirements_localized against
--   get_my_consents. Backs the member charter-signing surface.
-- Security: SECURITY DEFINER, authenticated only (subject is always the caller).

CREATE OR REPLACE FUNCTION public.get_my_pending_consents(p_locale text DEFAULT 'en')
 RETURNS TABLE(
   id uuid,
   study_id uuid,
   study_name text,
   consent_template_id uuid,
   template_key text,
   title text,
   content text,
   version text,
   is_required boolean,
   requires_signature boolean
 )
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    scr.id,
    scr.study_id,
    s.name AS study_name,
    scr.consent_template_id,
    COALESCE(ct.template_key, ct.code, '') AS template_key,
    public.get_translation_value_with_fallback(
      ct.title_key, 'consents', p_locale,
      COALESCE(NULLIF(ct.base_locale, ''), 'en'),
      COALESCE(ct.template_key, ct.code, '')
    ) AS title,
    public.get_translation_value_with_fallback(
      ct.content_key, 'consents', p_locale,
      COALESCE(NULLIF(ct.base_locale, ''), 'en'),
      ''
    ) AS content,
    COALESCE(ct.version, '1.0') AS version,
    scr.is_required,
    COALESCE(ct.requires_signature, false) AS requires_signature
  FROM public.study_registrations sr
  JOIN public.study_consent_requirements scr
    ON scr.study_id = sr.study_id AND COALESCE(scr.is_active, true) = true
  JOIN public.consent_templates ct
    ON ct.id = scr.consent_template_id AND COALESCE(ct.is_active, true) = true
  JOIN public.studies s ON s.id = scr.study_id
  -- Already accepted (and not revoked) for the pinned major version → excluded.
  LEFT JOIN public.study_consent_acceptances sca
    ON sca.user_id = sr.user_id
   AND sca.study_id = scr.study_id
   AND sca.consent_template_id = scr.consent_template_id
   AND sca.consent_template_version = floor(scr.consent_template_version::numeric)::integer
   AND sca.revoked_at IS NULL
  WHERE sr.user_id = v_user_id
    AND sr.status IN ('enrolled', 'active')
    AND sca.id IS NULL
    AND (scr.valid_from IS NULL OR now() >= scr.valid_from)
    AND (scr.valid_until IS NULL OR now() <= scr.valid_until)
  ORDER BY scr.sort_order, COALESCE(ct.template_key, ct.code, '');
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.get_my_pending_consents(p_locale text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_my_pending_consents(p_locale text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_public_hero_slides.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_public_hero_slides
-- Arguments: none
-- Description: Returns active hero slides for public display with linked product info.
-- Security: SECURITY DEFINER with search_path set. Public access.
-- Extracted: 2026-01-09
-- Updated: 2026-01-17 - Added circle_icon and circle_text fields

DROP FUNCTION IF EXISTS public.get_public_hero_slides();
DROP FUNCTION IF EXISTS public.get_public_hero_slides(text);

CREATE OR REPLACE FUNCTION public.get_public_hero_slides(p_locale text DEFAULT 'en')
RETURNS TABLE (
  background_gradient text,
  background_image_url text,
  badge text,
  circle_icon text,
  circle_text text,
  cta_text text,
  cta_url text,
  id uuid,
  linked_product_id uuid,
  linked_product_name text,
  linked_product_price numeric,
  linked_product_slug text,
  sort_order integer,
  subtitle text,
  target_audience text,
  title text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
BEGIN
  RETURN QUERY
  SELECT 
    COALESCE(hs.background_gradient, '') AS background_gradient,
    COALESCE(hs.background_image_url, '') AS background_image_url,
    COALESCE(
      public.get_translation_value_with_fallback(
        hs.badge_key,
        'hero',
        p_locale,
        COALESCE(hs.base_locale, 'en'),
        NULL
      ),
      ''
    ) AS badge,
    COALESCE(
      public.get_translation_value_with_fallback(
        hs.circle_icon_key,
        'hero',
        p_locale,
        COALESCE(hs.base_locale, 'en'),
        NULL
      ),
      'Sparkles'
    ) AS circle_icon,
    COALESCE(
      public.get_translation_value_with_fallback(
        hs.circle_text_key,
        'hero',
        p_locale,
        COALESCE(hs.base_locale, 'en'),
        NULL
      ),
      ''
    ) AS circle_text,
    COALESCE(
      public.get_translation_value_with_fallback(
        hs.cta_text_key,
        'hero',
        p_locale,
        COALESCE(hs.base_locale, 'en'),
        NULL
      ),
      ''
    ) AS cta_text,
    COALESCE(hs.cta_url, '') AS cta_url,
    hs.id,
    hs.linked_product_id,
    COALESCE(p.name, '') AS linked_product_name,
    COALESCE(p.price, 0) AS linked_product_price,
    COALESCE(p.slug, '') AS linked_product_slug,
    COALESCE(hs.sort_order, 0) AS sort_order,
    COALESCE(
      public.get_translation_value_with_fallback(
        hs.subtitle_key,
        'hero',
        p_locale,
        COALESCE(hs.base_locale, 'en'),
        NULL
      ),
      ''
    ) AS subtitle,
    COALESCE(hs.target_audience, 'all') AS target_audience,
    COALESCE(
      public.get_translation_value_with_fallback(
        hs.title_key,
        'hero',
        p_locale,
        COALESCE(hs.base_locale, 'en'),
        NULL
      ),
      ''
    ) AS title
  FROM hero_slides hs
  LEFT JOIN products p ON p.id = hs.linked_product_id
  WHERE hs.is_active = true
  ORDER BY hs.sort_order ASC, hs.created_at DESC;
END;
$$;

-- Permissions - public access for anonymous and authenticated users
REVOKE ALL ON FUNCTION public.get_public_hero_slides(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_public_hero_slides(text) TO anon;
GRANT EXECUTE ON FUNCTION public.get_public_hero_slides(text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_public_product_by_slug.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_public_product_by_slug
-- Arguments: p_slug text, p_locale text
-- Description: Public product detail with localized fields and marketing content.
-- Security: SECURITY DEFINER (anon access).

CREATE OR REPLACE FUNCTION public.get_public_product_by_slug(p_slug text, p_locale text DEFAULT 'en')
RETURNS TABLE(
  archive_document_id uuid,
  base_locale text,
  badge text,
  benefits_content jsonb,
  benefits_title text,
  category text,
  compare_at_price numeric(10,2),
  composition_title text,
  created_at timestamptz,
  description text,
  id uuid,
  image_alt text,
  image_url text,
  images text[],
  in_stock boolean,
  membership_tier_required text,
  name text,
  origin_content jsonb,
  original_price double precision,
  price numeric(10,2),
  requires_membership boolean,
  short_description text,
  slug text,
  stock_quantity integer,
  substances_content jsonb,
  tagline text,
  target_audience text,
  updated_at timestamptz,
  usage_content jsonb,
  usage_title text,
  use_case text,
  -- Default protocol info for longevity display
  default_protocol jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    COALESCE(p.archive_document_id::text, '') as archive_document_id,
    COALESCE(p.base_locale, 'en') as base_locale,
    -- Badge (translation key)
    COALESCE(
      public.get_translation_value_with_fallback(
        p.badge_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      ''
    ) as badge,
    -- Benefits content (JSONB with locale keys or translation keys)
    CASE
      WHEN p.benefits_content IS NULL THEN NULL::jsonb
      WHEN jsonb_typeof(p.benefits_content) <> 'object' THEN p.benefits_content
      WHEN p.benefits_content ? p_locale THEN p.benefits_content -> p_locale
      WHEN p.benefits_content ? 'en' THEN p.benefits_content -> 'en'
      ELSE p.benefits_content
    END as benefits_content,
    -- Benefits title (translation key)
    COALESCE(
      public.get_translation_value_with_fallback(
        p.benefits_title_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      ''
    ) as benefits_title,
    COALESCE(p.category, '') as category,
    COALESCE(p.compare_at_price::float8, 0) as compare_at_price,
    -- Composition title (translation key)
    COALESCE(
      public.get_translation_value_with_fallback(
        p.composition_title_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      ''
    ) as composition_title,
    p.created_at,
    COALESCE(
      public.get_translation_value_with_fallback(
        p.description_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      COALESCE(p.description, '')
    ) as description,
    p.id,
    -- Image alt (translation key)
    COALESCE(
      public.get_translation_value_with_fallback(
        p.image_alt_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      ''
    ) as image_alt,
    COALESCE(p.image_url, '') as image_url,
    COALESCE(p.images, ARRAY[]::text[]) as images,
    COALESCE(p.in_stock, true) as in_stock,
    '' as membership_tier_required,
    COALESCE(
      public.get_translation_value_with_fallback(
        p.name_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      p.name
    ) as name,
    -- Origin content (JSONB with locale keys or translation keys)
    CASE
      WHEN p.origin_content IS NULL THEN NULL::jsonb
      WHEN jsonb_typeof(p.origin_content) <> 'object' THEN p.origin_content
      WHEN p.origin_content ? p_locale THEN p.origin_content -> p_locale
      WHEN p.origin_content ? 'en' THEN p.origin_content -> 'en'
      ELSE p.origin_content
    END as origin_content,
    COALESCE(p.compare_at_price::float8, 0) as original_price,
    p.price::float8 as price,
    false as requires_membership,
    COALESCE(
      public.get_translation_value_with_fallback(
        p.short_description_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      COALESCE(p.short_description, '')
    ) as short_description,
    p.slug,
    COALESCE(p.stock_quantity, 0) as stock_quantity,
    -- Substances content (JSONB with locale keys or translation keys)
    CASE
      WHEN p.substances_content IS NULL THEN NULL::jsonb
      WHEN jsonb_typeof(p.substances_content) <> 'object' THEN p.substances_content
      WHEN p.substances_content ? p_locale THEN p.substances_content -> p_locale
      WHEN p.substances_content ? 'en' THEN p.substances_content -> 'en'
      ELSE p.substances_content
    END as substances_content,
    -- Tagline (translation key)
    COALESCE(
      public.get_translation_value_with_fallback(
        p.tagline_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      ''
    ) as tagline,
    p.target_audience,
    p.updated_at,
    -- Usage content (JSONB with locale keys or translation keys)
    CASE
      WHEN p.usage_content IS NULL THEN NULL::jsonb
      WHEN jsonb_typeof(p.usage_content) <> 'object' THEN p.usage_content
      WHEN p.usage_content ? p_locale THEN p.usage_content -> p_locale
      WHEN p.usage_content ? 'en' THEN p.usage_content -> 'en'
      ELSE p.usage_content
    END as usage_content,
    -- Usage title (translation key)
    COALESCE(
      public.get_translation_value_with_fallback(
        p.usage_title_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      ''
    ) as usage_title,
    p.use_case,
    -- Default protocol (if set)
    CASE 
      WHEN dp.id IS NOT NULL THEN jsonb_build_object(
        'id', dp.id,
        'name', COALESCE(
          (SELECT t.value FROM translations t 
           WHERE t.key = dp.name_key AND t.locale = p_locale AND t.namespace = 'distribution_protocols'),
          (SELECT t.value FROM translations t 
           WHERE t.key = dp.name_key AND t.locale = 'en' AND t.namespace = 'distribution_protocols'),
          dp.name
        ),
        'description', COALESCE(
          (SELECT t.value FROM translations t 
           WHERE t.key = dp.description_key AND t.locale = p_locale AND t.namespace = 'distribution_protocols'),
          (SELECT t.value FROM translations t 
           WHERE t.key = dp.description_key AND t.locale = 'en' AND t.namespace = 'distribution_protocols'),
          dp.description
        ),
        'dose_amount', dp.dose_amount,
        'dose_unit', dp.dose_unit,
        'doses_per_day', dp.doses_per_day,
        'dose_timing', dp.dose_timing
      )
      ELSE NULL::jsonb
    END as default_protocol
  FROM public.products p
  LEFT JOIN public.distribution_protocols dp ON dp.id = p.default_protocol_id AND dp.is_active = true
  WHERE p.slug = p_slug
    AND p.is_active = true;
END;
$function$;

-- Permissions (PUBLIC: product detail is public)
REVOKE ALL ON FUNCTION public.get_public_product_by_slug(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_public_product_by_slug(text, text) TO anon;
GRANT EXECUTE ON FUNCTION public.get_public_product_by_slug(text, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_public_products.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_public_products
-- Arguments: p_locale text
-- Description: Public product catalog with localized fields and marketing content.
-- Security: SECURITY DEFINER (anon access).

CREATE OR REPLACE FUNCTION public.get_public_products(p_locale text DEFAULT 'en')
RETURNS TABLE(
  archive_document_id uuid,
  base_locale text,
  badge text,
  benefits_content jsonb,
  benefits_title text,
  category text,
  compare_at_price numeric,
  composition_title text,
  created_at timestamptz,
  description text,
  id uuid,
  image_alt text,
  image_url text,
  images text[],
  in_stock boolean,
  membership_tier_required text,
  name text,
  origin_content jsonb,
  original_price numeric,
  price numeric,
  requires_membership boolean,
  short_description text,
  slug text,
  stock_quantity integer,
  substances_content jsonb,
  tagline text,
  target_audience text,
  updated_at timestamptz,
  usage_content jsonb,
  usage_title text,
  use_case text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    COALESCE(p.archive_document_id::text, '') as archive_document_id,
    COALESCE(p.base_locale, 'en') as base_locale,
    -- Badge (translation key)
    COALESCE(
      public.get_translation_value_with_fallback(
        p.badge_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      ''
    ) as badge,
    -- Benefits content (JSONB with locale keys or translation keys)
    CASE
      WHEN p.benefits_content IS NULL THEN NULL::jsonb
      WHEN jsonb_typeof(p.benefits_content) <> 'object' THEN p.benefits_content
      WHEN p.benefits_content ? p_locale THEN p.benefits_content -> p_locale
      WHEN p.benefits_content ? 'en' THEN p.benefits_content -> 'en'
      ELSE p.benefits_content
    END as benefits_content,
    -- Benefits title (translation key)
    COALESCE(
      public.get_translation_value_with_fallback(
        p.benefits_title_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      ''
    ) as benefits_title,
    COALESCE(p.category, '') as category,
    COALESCE(p.compare_at_price, 0::numeric(10,2)) as compare_at_price,
    -- Composition title (translation key)
    COALESCE(
      public.get_translation_value_with_fallback(
        p.composition_title_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      ''
    ) as composition_title,
    p.created_at,
    COALESCE(
      public.get_translation_value_with_fallback(
        p.description_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      COALESCE(p.description, '')
    ) as description,
    p.id,
    -- Image alt (translation key)
    COALESCE(
      public.get_translation_value_with_fallback(
        p.image_alt_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      ''
    ) as image_alt,
    COALESCE(p.image_url, '') as image_url,
    COALESCE(p.images, ARRAY[]::text[]) as images,
    COALESCE(p.in_stock, true) as in_stock,
    '' as membership_tier_required,
    COALESCE(
      public.get_translation_value_with_fallback(
        p.name_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      p.name
    ) as name,
    -- Origin content (JSONB with locale keys or translation keys)
    CASE
      WHEN p.origin_content IS NULL THEN NULL::jsonb
      WHEN jsonb_typeof(p.origin_content) <> 'object' THEN p.origin_content
      WHEN p.origin_content ? p_locale THEN p.origin_content -> p_locale
      WHEN p.origin_content ? 'en' THEN p.origin_content -> 'en'
      ELSE p.origin_content
    END as origin_content,
    COALESCE(p.compare_at_price, 0::numeric(10,2)) as original_price,
    p.price as price,
    false as requires_membership,
    COALESCE(
      public.get_translation_value_with_fallback(
        p.short_description_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      COALESCE(p.short_description, '')
    ) as short_description,
    p.slug,
    COALESCE(p.stock_quantity, 0) as stock_quantity,
    -- Substances content (JSONB with locale keys or translation keys)
    CASE
      WHEN p.substances_content IS NULL THEN NULL::jsonb
      WHEN jsonb_typeof(p.substances_content) <> 'object' THEN p.substances_content
      WHEN p.substances_content ? p_locale THEN p.substances_content -> p_locale
      WHEN p.substances_content ? 'en' THEN p.substances_content -> 'en'
      ELSE p.substances_content
    END as substances_content,
    -- Tagline (translation key)
    COALESCE(
      public.get_translation_value_with_fallback(
        p.tagline_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      ''
    ) as tagline,
    p.target_audience,
    p.updated_at,
    -- Usage content (JSONB with locale keys or translation keys)
    CASE
      WHEN p.usage_content IS NULL THEN NULL::jsonb
      WHEN jsonb_typeof(p.usage_content) <> 'object' THEN p.usage_content
      WHEN p.usage_content ? p_locale THEN p.usage_content -> p_locale
      WHEN p.usage_content ? 'en' THEN p.usage_content -> 'en'
      ELSE p.usage_content
    END as usage_content,
    -- Usage title (translation key)
    COALESCE(
      public.get_translation_value_with_fallback(
        p.usage_title_key,
        'products',
        p_locale,
        COALESCE(p.base_locale, 'en'),
        NULL
      ),
      ''
    ) as usage_title,
    p.use_case
  FROM public.products p
  WHERE p.is_active = true
  ORDER BY p.name;
END;
$function$;

-- Permissions (PUBLIC: product catalog is public)
REVOKE ALL ON FUNCTION public.get_public_products(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_public_products(text) TO anon;
GRANT EXECUTE ON FUNCTION public.get_public_products(text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_question_blocks_for_context.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_question_blocks_for_context
-- Arguments: p_block_codes text[], p_locale text
-- Description: Returns question blocks for questionnaires. Public template data.
-- Security: SECURITY DEFINER - public read-only questionnaire templates.
-- @security: public
-- @audit: none

CREATE OR REPLACE FUNCTION public.get_question_blocks_for_context(p_block_codes text[], p_locale text DEFAULT 'en'::text)
 RETURNS TABLE(block_code text, config jsonb, display_order integer, id uuid, is_active boolean, is_required boolean, question_type text, text_key text, translated_text text, translated_description text, option_translations jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_all_label_keys text[];
  v_translations_map jsonb := '{}'::jsonb;
  v_fallback_map jsonb := '{}'::jsonb;
BEGIN
  -- First, collect all label_key values from configs of requested blocks
  SELECT array_agg(DISTINCT label_key)
  INTO v_all_label_keys
  FROM (
    -- Extract label_key from tags options
    SELECT opt->>'label_key' AS label_key
    FROM question_blocks qb,
         jsonb_array_elements(qb.config->'options') AS opt
    WHERE qb.code = ANY(p_block_codes)
      AND qb.is_active = true
      AND qb.question_type IN ('tags', 'select', 'radio', 'checkbox')
      AND opt->>'label_key' IS NOT NULL
    
    UNION
    
    -- Extract description_key from tags options
    SELECT opt->>'description_key' AS label_key
    FROM question_blocks qb,
         jsonb_array_elements(qb.config->'options') AS opt
    WHERE qb.code = ANY(p_block_codes)
      AND qb.is_active = true
      AND qb.question_type IN ('tags', 'select', 'radio', 'checkbox')
      AND opt->>'description_key' IS NOT NULL
    
    UNION
    
    -- Extract label_key from feeling presets
    SELECT preset->>'label_key' AS label_key
    FROM question_blocks qb,
         jsonb_array_elements(qb.config->'presets') AS preset
    WHERE qb.code = ANY(p_block_codes)
      AND qb.is_active = true
      AND qb.question_type = 'feeling_preset'
      AND preset->>'label_key' IS NOT NULL
    
    UNION
    
    -- Extract description_key from feeling presets
    SELECT preset->>'description_key' AS label_key
    FROM question_blocks qb,
         jsonb_array_elements(qb.config->'presets') AS preset
    WHERE qb.code = ANY(p_block_codes)
      AND qb.is_active = true
      AND qb.question_type = 'feeling_preset'
      AND preset->>'description_key' IS NOT NULL

    UNION

    -- Extract lowLabel_key, highLabel_key, midLabel_key from scale configs
    SELECT unnest(ARRAY[
      qb.config->>'lowLabel_key',
      qb.config->>'highLabel_key',
      qb.config->>'midLabel_key'
    ]) AS label_key
    FROM question_blocks qb
    WHERE qb.code = ANY(p_block_codes)
      AND qb.is_active = true
      AND qb.question_type = 'scale'

    UNION

    -- Extract trueLabel_key, falseLabel_key from boolean configs
    SELECT unnest(ARRAY[
      qb.config->>'trueLabel_key',
      qb.config->>'falseLabel_key'
    ]) AS label_key
    FROM question_blocks qb
    WHERE qb.code = ANY(p_block_codes)
      AND qb.is_active = true
      AND qb.question_type = 'boolean'

    UNION

    -- Extract placeholder_key from text/date/textarea configs
    SELECT qb.config->>'placeholder_key' AS label_key
    FROM question_blocks qb
    WHERE qb.code = ANY(p_block_codes)
      AND qb.is_active = true
      AND qb.question_type IN ('text', 'date', 'textarea')
      AND qb.config->>'placeholder_key' IS NOT NULL

    UNION

    -- Extract unit_key from number configs
    SELECT qb.config->>'unit_key' AS label_key
    FROM question_blocks qb
    WHERE qb.code = ANY(p_block_codes)
      AND qb.is_active = true
      AND qb.question_type = 'number'
      AND qb.config->>'unit_key' IS NOT NULL

    UNION

    -- Extract label_key from scale labels array (WOMAC scale point labels)
    SELECT lbl->>'label_key' AS label_key
    FROM question_blocks qb,
         jsonb_array_elements(qb.config->'labels') AS lbl
    WHERE qb.code = ANY(p_block_codes)
      AND qb.is_active = true
      AND qb.question_type = 'scale'
      AND qb.config ? 'labels'
      AND lbl->>'label_key' IS NOT NULL
  ) AS keys
  WHERE label_key IS NOT NULL;

  -- Fetch translations for all collected keys
  IF v_all_label_keys IS NOT NULL AND array_length(v_all_label_keys, 1) > 0 THEN
    -- First get English fallback translations
    SELECT jsonb_object_agg(t.key, t.value)
    INTO v_fallback_map
    FROM translations t
    WHERE t.key = ANY(v_all_label_keys)
      AND t.locale = 'en'
      AND t.namespace = 'questionnaires';
    
    -- Then get requested locale translations (if not English)
    IF p_locale != 'en' THEN
      SELECT jsonb_object_agg(t.key, t.value)
      INTO v_translations_map
      FROM translations t
      WHERE t.key = ANY(v_all_label_keys)
        AND t.locale = p_locale
        AND t.namespace = 'questionnaires';
    END IF;
    
    -- Merge: locale translations override English fallback
    v_translations_map := COALESCE(v_fallback_map, '{}'::jsonb) || COALESCE(v_translations_map, '{}'::jsonb);
  END IF;

  -- Return blocks with translations (using standard helper with English fallback)
  RETURN QUERY
  SELECT 
    qb.code AS block_code,
    qb.config,
    qb.display_order,
    qb.id,
    qb.is_active,
    qb.is_required_default AS is_required,
    qb.question_type,
    qb.text_key,
    public.get_translation_value_with_fallback(
      qb.text_key, 'questionnaires', p_locale, 'en', qb.text_key
    ) AS translated_text,
    public.get_translation_value_with_fallback(
      qb.text_key || '.description', 'questionnaires', p_locale, 'en', ''
    ) AS translated_description,
    COALESCE(v_translations_map, '{}'::jsonb) AS option_translations
  FROM question_blocks qb
  WHERE qb.code = ANY(p_block_codes)
    AND qb.is_active = true
  ORDER BY qb.display_order;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.get_question_blocks_for_context(p_block_codes text[], p_locale text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_question_blocks_for_context(p_block_codes text[], p_locale text) TO public;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_question_blocks_by_context_type.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_question_blocks_by_context_type
-- Arguments: p_context_type text, p_locale text
-- Description: Returns question blocks by context_type, delegating to get_question_blocks_for_context.
-- Replaces the frontend CONTEXT_BLOCK_CODES hardcoded mapping.
-- Security: SECURITY DEFINER - public read-only questionnaire templates.
-- @security: public
-- @audit: none

CREATE OR REPLACE FUNCTION public.get_question_blocks_by_context_type(
  p_context_type text,
  p_locale text DEFAULT 'en'
)
RETURNS TABLE(
  block_code text,
  config jsonb,
  display_order integer,
  id uuid,
  is_active boolean,
  is_required boolean,
  question_type text,
  text_key text,
  translated_text text,
  translated_description text,
  option_translations jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_block_codes text[];
BEGIN
  -- Resolve block codes from context_type
  SELECT array_agg(qb.code ORDER BY qb.display_order)
  INTO v_block_codes
  FROM question_blocks qb
  WHERE qb.context_type = p_context_type
    AND qb.is_active = true;

  IF v_block_codes IS NULL OR array_length(v_block_codes, 1) IS NULL THEN
    RETURN;
  END IF;

  -- Delegate to existing function that handles all translation resolution
  RETURN QUERY
  SELECT
    q.block_code,
    q.config,
    q.display_order,
    q.id,
    q.is_active,
    q.is_required,
    q.question_type,
    q.text_key,
    q.translated_text,
    q.translated_description,
    q.option_translations
  FROM public.get_question_blocks_for_context(v_block_codes, p_locale) q;
END;
$$;

REVOKE ALL ON FUNCTION public.get_question_blocks_by_context_type(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_question_blocks_by_context_type(text, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_study_consent_items_localized.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_study_consent_items_localized
-- Arguments: p_study_id uuid, p_locale text
-- Description: Returns localized consent items for a study (newer consent system).
--              This function is PUBLIC (no auth required) because consent
--              items must be visible during registration before signup.
-- Security: SECURITY DEFINER with search_path.

CREATE OR REPLACE FUNCTION public.get_study_consent_items_localized(p_study_id uuid, p_locale text DEFAULT 'en')
 RETURNS TABLE(
   id uuid,
   consent_key text,
   title text,
   description text,
   checkbox_label text,
   document_url text,
   is_required boolean,
   display_order integer
 )
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- No auth check - consent items are public information
  -- needed for registration flow before user signup

  RETURN QUERY
  SELECT
    sci.id,
    sci.consent_key,
    -- Localized title
    public.get_translation_value_with_fallback(
      sci.title_key, 'consents', p_locale, 'en', NULL
    ) AS title,
    -- Localized description
    public.get_translation_value_with_fallback(
      sci.description_key, 'consents', p_locale, 'en', NULL
    ) AS description,
    -- Localized checkbox label
    public.get_translation_value_with_fallback(
      sci.checkbox_label_key, 'consents', p_locale, 'en', NULL
    ) AS checkbox_label,
    sci.document_url,
    sci.is_required,
    sci.display_order
  FROM public.study_consent_items sci
  WHERE sci.study_id = p_study_id
    AND COALESCE(sci.is_active, true) = true
  ORDER BY sci.display_order, sci.created_at;
END;
$function$;

-- Permissions: grant to both anon (for registration) and authenticated
REVOKE ALL ON FUNCTION public.get_study_consent_items_localized(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_study_consent_items_localized(uuid, text) TO anon;
GRANT EXECUTE ON FUNCTION public.get_study_consent_items_localized(uuid, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_study_consent_requirements_localized.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_study_consent_requirements_localized
-- Arguments: p_study_id uuid, p_locale text
-- Description: Returns localized consent requirements for a study.
--              This function is PUBLIC (no auth required) because consent
--              requirements must be visible during registration before signup.
-- Security: SECURITY DEFINER with search_path.
-- Extracted: 2026-01-08T18:27:33+01:00

CREATE OR REPLACE FUNCTION public.get_study_consent_requirements_localized(p_study_id uuid, p_locale text)
 RETURNS TABLE(id uuid, consent_template_id uuid, is_required boolean, sort_order integer, template_key text, title text, content text, version text, requires_signature boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- No auth check - consent requirements are public information
  -- needed for registration flow before user signup

  RETURN QUERY
  SELECT
    scr.id,
    scr.consent_template_id,
    scr.is_required,
    scr.sort_order,
    COALESCE(ct.template_key, ct.code, '') AS template_key,
    -- Localized title from translation key with fallback to template key
    public.get_translation_value_with_fallback(
      ct.title_key,
      'consents',
      p_locale,
      COALESCE(NULLIF(ct.base_locale, ''), 'en'),
      COALESCE(ct.template_key, ct.code, '')
    ) AS title,
    -- Localized content from translation key with empty fallback
    public.get_translation_value_with_fallback(
      ct.content_key,
      'consents',
      p_locale,
      COALESCE(NULLIF(ct.base_locale, ''), 'en'),
      ''
    ) AS content,
    COALESCE(ct.version, '1.0') AS version,
    COALESCE(ct.requires_signature, false) AS requires_signature
  FROM public.study_consent_requirements scr
  JOIN public.consent_templates ct ON ct.id = scr.consent_template_id
  WHERE scr.study_id = p_study_id
    AND COALESCE(scr.is_active, true) = true
    AND COALESCE(ct.is_active, true) = true
  ORDER BY scr.sort_order, COALESCE(ct.template_key, ct.code, '');
END;
$function$
;

-- Permissions: grant to both anon (for registration) and authenticated
REVOKE ALL ON FUNCTION public.get_study_consent_requirements_localized(p_study_id uuid, p_locale text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_study_consent_requirements_localized(p_study_id uuid, p_locale text) TO anon;
GRANT EXECUTE ON FUNCTION public.get_study_consent_requirements_localized(p_study_id uuid, p_locale text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_subscription_packages.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_subscription_packages
-- Arguments: p_locale text (default 'en')
-- Description: Returns active subscription packages with localized name/description.
-- Security: SECURITY DEFINER - public read-only pricing data.
-- @security: public
-- @audit: none

-- A currency-suffixed name (`*_usd`) was removed from this function's signature.
-- The TYPES did not change, so CREATE OR REPLACE matches the deployed function and
-- Postgres refuses to rename in place ("cannot change name of input parameter", or
-- "cannot change return type" when the renamed name is a RETURNS TABLE column).
-- DROP-first is the convention used elsewhere in this directory; the REVOKE/GRANT
-- below re-applies whatever privileges the drop clears.
DROP FUNCTION IF EXISTS public.get_subscription_packages(text);

CREATE OR REPLACE FUNCTION public.get_subscription_packages(p_locale text DEFAULT 'en')
 RETURNS TABLE(allow_one_time_payment boolean, allow_recurring_payment boolean, billing_interval_months integer, currency text, description text, governance_tokens integer, id uuid, impact_tokens integer, includes_diagnostics text[], includes_products text[], is_active boolean, is_recurring boolean, min_billing_months integer, name text, period text, price numeric, slug text, sort_order integer, stripe_price_id text, stripe_price_id_one_time text, stripe_price_id_recurring text, stripe_product_id text, tier text, tokens_governance integer, tokens_impact integer, tokens_data integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    COALESCE(sp.allow_one_time_payment, false) AS allow_one_time_payment,
    COALESCE(sp.allow_recurring_payment, COALESCE(sp.is_recurring, false)) AS allow_recurring_payment,
    sp.billing_interval_months,
    sp.currency,
    -- Localized description with fallback
    public.get_translation_value_with_fallback(
      sp.description_key,
      'subscription_packages',
      p_locale,
      'en',
      sp.description
    ) AS description,
    COALESCE(sp.governance_tokens, 0) AS governance_tokens,
    sp.id,
    COALESCE(sp.impact_tokens, 0) AS impact_tokens,
    sp.includes_diagnostics,
    sp.includes_products,
    COALESCE(sp.is_active, true) AS is_active,
    COALESCE(sp.is_recurring, false) AS is_recurring,
    COALESCE(sp.min_billing_months, 1) AS min_billing_months,
    -- Localized name with fallback
    public.get_translation_value_with_fallback(
      sp.name_key,
      'subscription_packages',
      p_locale,
      'en',
      sp.name
    ) AS name,
    sp.period::text,
    sp.price,
    sp.slug,
    COALESCE(sp.sort_order, 0) AS sort_order,
    sp.stripe_price_id,
    sp.stripe_price_id_one_time,
    sp.stripe_price_id_recurring,
    sp.stripe_product_id,
    sp.tier::text,
    sp.tokens_governance,
    sp.tokens_impact,
    sp.tokens_data
  FROM public.subscription_packages sp
  WHERE COALESCE(sp.is_active, true) = true
  ORDER BY COALESCE(sp.sort_order, 0);
END;
$function$
;

-- Permissions (public access for pricing page)
REVOKE ALL ON FUNCTION public.get_subscription_packages(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_subscription_packages(text) TO anon;
GRANT EXECUTE ON FUNCTION public.get_subscription_packages(text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_test_questions_public_localized.sql
-- -----------------------------------------------------------------------------


-- Function: get_test_questions_public_localized
-- Purpose: Returns test questions with localized text (no correct answer).
-- Security: SECURITY DEFINER, public access.
-- Replaces: get_test_questions_public (enhanced version)

CREATE OR REPLACE FUNCTION public.get_test_questions_public_localized(
  p_locale TEXT DEFAULT 'en',
  p_test_type TEXT DEFAULT NULL
)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result JSONB;
  v_locale TEXT;
BEGIN
  -- Normalize locale
  v_locale := CASE
    WHEN p_locale IN ('cs', 'de', 'en', 'fr', 'ru', 'th') THEN p_locale
    ELSE 'en'
  END;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', tq.id,
      'test_type', tq.test_type,
      'question_order', tq.question_order,
      -- Fetch translated values
      'question', public.get_translation_value_with_fallback(
        tq.question_key, 'tests', v_locale, 'en', NULL
      ),
      'option_a', public.get_translation_value_with_fallback(
        tq.option_a_key, 'tests', v_locale, 'en', NULL
      ),
      'option_b', public.get_translation_value_with_fallback(
        tq.option_b_key, 'tests', v_locale, 'en', NULL
      ),
      'option_c', CASE WHEN tq.option_c_key IS NOT NULL THEN
        public.get_translation_value_with_fallback(
          tq.option_c_key, 'tests', v_locale, 'en', NULL
        )
      ELSE NULL END,
      'option_d', CASE WHEN tq.option_d_key IS NOT NULL THEN
        public.get_translation_value_with_fallback(
          tq.option_d_key, 'tests', v_locale, 'en', NULL
        )
      ELSE NULL END,
      -- Include keys for reference
      'question_key', tq.question_key,
      'option_a_key', tq.option_a_key,
      'option_b_key', tq.option_b_key,
      'option_c_key', tq.option_c_key,
      'option_d_key', tq.option_d_key,
      'is_active', tq.is_active
    ) ORDER BY tq.question_order
  )
  INTO v_result
  FROM test_questions tq
  WHERE tq.is_active = true
    AND (p_test_type IS NULL OR tq.test_type = p_test_type);

  RETURN COALESCE(v_result, '[]'::JSONB);
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.get_test_questions_public_localized(TEXT, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_test_questions_public_localized(TEXT, TEXT) TO anon;
GRANT EXECUTE ON FUNCTION public.get_test_questions_public_localized(TEXT, TEXT) TO authenticated;


