GRANT EXECUTE ON FUNCTION public.get_user_permissions() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_vedeni_aging.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'chart' block (kind='bar'): receivables/payables AGING — unpaid
-- invoices bucketed by how far past (or before) their due date they sit, so the
-- reader sees WHERE the money is stuck, not just the total. p_params->>'direction'
-- picks the ledger: 'issued' = pohledávky (owed to us), 'received' = závazky (owed
-- by us). One function, two blocks (DRY).
--
-- Buckets, oldest-debt-last on the axis: do splatnosti (dueDate ≥ today), 1–30,
-- 31–60, 61–90, 90+ dní po splatnosti. Bar value = Kč in the bucket, `note` = how
-- many invoices. Bucket labels are literal range descriptors: a chart point label
-- is DATA by the block contract (schemas.ts chartPoint has no label_key channel,
-- same as the per-vehicle/per-month labels on the other fleet/vedení charts).
--
-- Reads document_registry (metadata contract: see get_vedeni_finance_kpi). Unpaid =
-- financial.paidDate IS NULL. SECURITY INVOKER → RLS fails closed; empty ledger →
-- five 0-bars (a real "nothing outstanding"), distinct from an error. Contract:
-- (jsonb) -> jsonb {data:{kind,unit_key,points[]}, provenance}.

-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, 2026-09-27): `freshness_at` = nejnovější čas
-- univerza bloku, spočtený ze STEJNÝCH řádků jako hodnota. Pořadí zdrojů času: čas ze zdroje
-- (u Money `source_modified_at`, až bude úplný; u jízd/událostí `occurred_at`) › příchod verze
-- dokladu (`created_at`). NE `ingested_at`/`updated_at` — ty přepisuje KAŽDÝ import (naměřeno
-- 2026-09-27: 813 smluv = jediný čas), takže by lhaly jako faktury zamrzlé na exportu ze 6. 8.
-- Hranice `created_at`: backfill starých dokladů má čas dnešní — pravda o příchodu, ne o obsahu.
-- Prázdné univerzum → `trace_id` nese `:no_data` a čas je jen záloha `coalesce(…, now())`.
-- Stav linky (běží/neběží) sem NEPATŘÍ — je to jiný signál.
create or replace function public.get_vedeni_aging(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with p as (
    select case when p_params->>'direction' = 'received' then 'received' else 'issued' end as dir
  ),
  unpaid as (
    select
      r.created_at as vznik,
      (r.metadata->'financial'->>'totalAmount')::numeric as total,
      (r.metadata->'financial'->>'dueDate')::date        as due
    from public.document_registry r, p
    where r.doc_type = 'invoice'
      and coalesce(r.metadata->>'direction','issued') = p.dir
      and r.doc_date >= date '2024-01-01'
      and nullif(r.metadata->'financial'->>'paidDate','') is null           -- neuhrazené
      and r.metadata->'financial'->>'totalAmount' ~ '^-?[0-9]+(\.[0-9]+)?$'
  ),
  bucketed as (
    select
      case
        when due is null then 4                          -- bez splatnosti → k „po splatnosti"
        when due >= current_date then 0                  -- do splatnosti
        when current_date - due <= 30 then 1
        when current_date - due <= 60 then 2
        when current_date - due <= 90 then 3
        else 4
      end as b,
      total
    from unpaid
  ),
  -- Kostra košů (i prázdné se musí vykreslit) × naměřené sumy.
  buckets(b, lbl) as (
    values (0,'do spl.'), (1,'1–30 d'), (2,'31–60 d'), (3,'61–90 d'), (4,'90+ d')
  ),
  agg as (
    select k.b, k.lbl,
           coalesce(count(x.total), 0) as cnt,
           coalesce(sum(x.total), 0)   as amount
    from buckets k
    left join bucketed x on x.b = k.b
    group by k.b, k.lbl
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'kind', 'bar',
      'unit_key', 'app.vedeni.unit.czk',
      'points', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'label', lbl,
            'value', round(amount),
            'note',  cnt::text        -- kolik faktur v koši
          ) order by b
        ) from agg
      ), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'money-s5',
      'freshness_at', to_char(coalesce((select max(vznik) from unpaid), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'vedeni-aging:' || (select dir from p)
                      || case when (select max(vznik) from unpaid) is null then ':no_data' else '' end
    )
  );
$$;

revoke all on function public.get_vedeni_aging(jsonb) from public, anon;
grant execute on function public.get_vedeni_aging(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_vedeni_alerts.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'findings' block: „Manažerské alerty" — deterministic leadership
-- findings DERIVED from the Money evidence substrate (not a passthrough read). Each
-- carries a catalogue rule id as title_key (i18n, never a literal) + severity +
-- grounded `fields` (the numbers that fired it). Three rules, all computable from
-- the metadata contract (see get_vedeni_finance_kpi):
--   • overdue_exposure — the counterparty with the largest past-due receivable,
--     when it clears p_params->>'exposure_min_czk' (500 000). Naming the biggest
--     hole is the first move before it becomes a write-off.
--   • old_receivable — any receivable past due beyond p_params->>'stale_days' (180):
--     a debt that old rarely pays itself; it needs a decision, not another reminder.
--   • customer_concentration — a single customer over p_params->>'concentration_pct'
--     (40) of trailing-year turnover: a dependency risk to see named, not buried.
-- Fakturační skluz (delivered-not-yet-invoiced) needs a delivery-note↔invoice match
-- this reader does not have and is left out rather than faked.
--
-- SECURITY INVOKER → RLS on document_registry fails closed. Contract:
-- (jsonb) -> jsonb {data:{items[]}, provenance}.

-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, 2026-09-27): `freshness_at` = nejnovější čas
-- univerza bloku, spočtený ze STEJNÝCH řádků jako hodnota. Pořadí zdrojů času: čas ze zdroje
-- (u Money `source_modified_at`, až bude úplný; u jízd/událostí `occurred_at`) › příchod verze
-- dokladu (`created_at`). NE `ingested_at`/`updated_at` — ty přepisuje KAŽDÝ import (naměřeno
-- 2026-09-27: 813 smluv = jediný čas), takže by lhaly jako faktury zamrzlé na exportu ze 6. 8.
-- Hranice `created_at`: backfill starých dokladů má čas dnešní — pravda o příchodu, ne o obsahu.
-- Prázdné univerzum → `trace_id` nese `:no_data` a čas je jen záloha `coalesce(…, now())`.
-- Stav linky (běží/neběží) sem NEPATŘÍ — je to jiný signál.
create or replace function public.get_vedeni_alerts(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with p as (
    select coalesce((p_params->>'exposure_min_czk')::numeric, 500000) as exposure_min,
           coalesce((p_params->>'stale_days')::int, 180)              as stale_days,
           coalesce((p_params->>'concentration_pct')::numeric, 40)    as concentration_pct
  ),
  -- Neuhrazené vydané faktury (pohledávky) s validní částkou.
  recv as (
    select
      r.created_at as vznik,
      coalesce(nullif(r.counterparty,''), '—')           as party,
      (r.metadata->'financial'->>'totalAmount')::numeric as total,
      (r.metadata->'financial'->>'dueDate')::date        as due,
      r.doc_date
    from public.document_registry r
    where r.doc_type = 'invoice'
      and coalesce(r.metadata->>'direction','issued') = 'issued'
      and r.doc_date >= date '2024-01-01'
      and nullif(r.metadata->'financial'->>'paidDate','') is null
      and r.metadata->'financial'->>'totalAmount' ~ '^-?[0-9]+(\.[0-9]+)?$'
  ),
  -- ── overdue_exposure: největší expozice po splatnosti po odběratelích ──
  exposure as (
    select party, sum(total) as amount, max(current_date - due) as oldest
    from recv
    where due < current_date
    group by party
    having sum(total) >= (select exposure_min from p)
    order by sum(total) desc
    limit 1
  ),
  exposure_item as (
    select 'exposure:' || md5(party)                       as id,
           'app.vedeni.alert.overdue_exposure'             as title_key,
           'high'                                           as severity,
           jsonb_build_array(
             jsonb_build_object('key','party', 'label_key','app.vedeni.col.party',   'value', party),
             jsonb_build_object('key','amount','label_key','app.vedeni.col.overdue', 'value', round(amount)),
             jsonb_build_object('key','oldest','label_key','app.vedeni.col.oldest',  'value', oldest)
           )                                                as fields
    from exposure
  ),
  -- ── old_receivable: nejstarší jedna pohledávka za hranicí ──
  stale as (
    select party, total, current_date - due as days
    from recv
    where due < current_date - (select stale_days from p)
    order by due asc
    limit 1
  ),
  stale_item as (
    select 'stale:' || md5(party || days::text)            as id,
           'app.vedeni.alert.old_receivable'               as title_key,
           'high'                                           as severity,
           jsonb_build_array(
             jsonb_build_object('key','party', 'label_key','app.vedeni.col.party',   'value', party),
             jsonb_build_object('key','amount','label_key','app.vedeni.col.amount',  'value', round(total)),
             jsonb_build_object('key','oldest','label_key','app.vedeni.col.oldest',  'value', days)
           )                                                as fields
    from stale
  ),
  -- ── customer_concentration: podíl top odběratele na ročním obratu ──
  billed as (
    select r.created_at as vznik,
           coalesce(nullif(r.counterparty,''), '—') as party,
           (r.metadata->'financial'->>'totalAmount')::numeric as total
    from public.document_registry r
    where r.doc_type = 'invoice'
      and coalesce(r.metadata->>'direction','issued') = 'issued'
      and r.doc_date >= current_date - 365
      and r.metadata->'financial'->>'totalAmount' ~ '^-?[0-9]+(\.[0-9]+)?$'
  ),
  concentration as (
    select party, sum(total) as revenue,
           round(100.0 * sum(total) / nullif((select sum(total) from billed), 0)) as share
    from billed
    group by party
    order by sum(total) desc
    limit 1
  ),
  concentration_item as (
    select 'concentration:' || md5(party)                  as id,
           'app.vedeni.alert.customer_concentration'       as title_key,
           case when share >= 50 then 'high' else 'medium' end as severity,
           jsonb_build_array(
             jsonb_build_object('key','party', 'label_key','app.vedeni.col.party',   'value', party),
             jsonb_build_object('key','share', 'label_key','app.vedeni.col.share',   'value', share),
             jsonb_build_object('key','revenue','label_key','app.vedeni.col.revenue','value', round(revenue))
           )                                                as fields
    from concentration
    where share >= (select concentration_pct from p)
  ),
  items as (
    select * from exposure_item
    union all select * from stale_item
    union all select * from concentration_item
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'items', coalesce((
        select jsonb_agg(
          jsonb_build_object('id', id, 'title_key', title_key, 'severity', severity, 'fields', fields)
          order by case severity when 'high' then 1 when 'medium' then 2 else 3 end, id
        ) from items
      ), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'money-s5',
      'freshness_at', to_char(coalesce(greatest((select max(vznik) from recv), (select max(vznik) from billed)), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'vedeni-alerts'
                      || case when greatest((select max(vznik) from recv), (select max(vznik) from billed)) is null then ':no_data' else '' end
    )
  );
$$;

revoke all on function public.get_vedeni_alerts(jsonb) from public, anon;
grant execute on function public.get_vedeni_alerts(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_vedeni_cena_t_trend.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'chart' block (kind='bar'): average realised price per tonne of
-- stone, month by month — the single number that says whether the pit is holding
-- its margin or discounting to keep trucks moving. Per month = Σ(line value of
-- stone rows) / Σ(tonnes billed), from issued invoices. p_params->>'months' (12).
--
-- Reads document_registry (metadata contract: see get_vedeni_finance_kpi); a line
-- is stone when unit='t'. A month with no stone billed is omitted (no bar), never
-- drawn as 0 — a zero price would read as "gave it away", which is not what
-- "didn't sell any" means. SECURITY INVOKER → RLS fails closed. Contract:
-- (jsonb) -> jsonb {data:{kind,unit_key,points[]}, provenance}.

-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, 2026-09-27): `freshness_at` = nejnovější čas
-- univerza bloku, spočtený ze STEJNÝCH řádků jako hodnota. Pořadí zdrojů času: čas ze zdroje
-- (u Money `source_modified_at`, až bude úplný; u jízd/událostí `occurred_at`) › příchod verze
-- dokladu (`created_at`). NE `ingested_at`/`updated_at` — ty přepisuje KAŽDÝ import (naměřeno
-- 2026-09-27: 813 smluv = jediný čas), takže by lhaly jako faktury zamrzlé na exportu ze 6. 8.
-- Hranice `created_at`: backfill starých dokladů má čas dnešní — pravda o příchodu, ne o obsahu.
-- Prázdné univerzum → `trace_id` nese `:no_data` a čas je jen záloha `coalesce(…, now())`.
-- Stav linky (běží/neběží) sem NEPATŘÍ — je to jiný signál.
create or replace function public.get_vedeni_cena_t_trend(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with p as (select coalesce((p_params->>'months')::int, 12) as months),
  win as (
    select date_trunc('month', now())::date
           - make_interval(months => (select months from p) - 1) as since
  ),
  stone as (
    select
      r.created_at as vznik,
      date_trunc('month', r.doc_date)::date          as mon,
      (l->>'quantity')::numeric                       as qty,
      case when l->>'lineTotal' ~ '^-?[0-9]+(\.[0-9]+)?$'
           then (l->>'lineTotal')::numeric end        as line_total
    from public.document_registry r
    cross join lateral jsonb_array_elements(coalesce(r.metadata->'lines','[]'::jsonb)) l
    where r.doc_type = 'invoice'
      and coalesce(r.metadata->>'direction','issued') = 'issued'
      and r.doc_date >= (select since from win)::date
      and l->>'unit' = 't'
      and l->>'quantity' ~ '^-?[0-9]+(\.[0-9]+)?$'
  ),
  per_month as (
    select mon, sum(qty) as tonnes, sum(line_total) as value
    from stone
    group by mon
    having sum(qty) > 0
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'kind', 'bar',
      'unit_key', 'app.vedeni.unit.czk_t',
      'points', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'label', to_char(mon, 'MM/YYYY'),
            'value', round(value / tonnes),
            'note',  round(tonnes)::text     -- kolik tun stálo za tou cenou
          ) order by mon
        ) from per_month
      ), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'money-s5',
      'freshness_at', to_char(coalesce((select max(vznik) from stone), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'vedeni-cena-t-trend'
                      || case when (select max(vznik) from stone) is null then ':no_data' else '' end
    )
  );
$$;

revoke all on function public.get_vedeni_cena_t_trend(jsonb) from public, anon;
grant execute on function public.get_vedeni_cena_t_trend(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_vedeni_finance_kpi.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'kpi_tile' block: one headline figure for the leadership console
-- (surface `vedeni`), over the EVIDENCE substrate the Money connector writes as
-- documents. The metric is chosen by p_params->>'metric' (seeded per block via
-- source_params). Window is p_params->>'days' (default 30 — the month the owner's
-- view is framed in); receivables/payables ignore the window (a debt is overdue
-- regardless of when the invoice was issued), the flow metrics honour it.
--
-- ── METADATA CONTRACT (document_registry.metadata) ──────────────────────────
-- The Money ingest maps each `DocumentRecord` onto register_source_document_audited
-- with this jsonb shape (the seam is invoice-mapping.ts; NOTHING here learns Money's
-- own field names). doc_type ∈ {'invoice','delivery_note'}, doc_date = issue date,
-- counterparty = AdresaNazev. metadata =
--   { "direction": "issued" | "received",          -- vydaná (pohledávka) / přijatá (závazek)
--     "financial": { "totalAmount": num,           -- SumaCelkem, incl. VAT
--                    "dueDate":  "YYYY-MM-DD",      -- DatumSplatnosti
--                    "paidDate": "YYYY-MM-DD"|null, -- DatumUhrady; NULL = NEUHRAZENO
--                    "currency": "CZK", … },         --   (sentinel 1753/0001 → null at the seam)
--     "lines": [ { "quantity": num, "unit": "t"|"x", -- t = kámen, x = doprava
--                  "lineTotal": num, "catalog": … } ] }
-- Until that ingest runs the table is empty, so every metric is legitimately
-- NEMĚŘENO (value=null → tile shows '—'), never a fabricated 0. `paidDate IS NULL`
-- is the ONLY reliable unpaid indicator — `status` (Money `Stav`) is always 0.
-- Older than 2024 is dropped: those are migration artifacts, not live receivables.
--
-- SECURITY INVOKER → RLS on document_registry fails closed (non-staff get an empty
-- figure, not an error), same doctrine as get_document_digest / get_fleet_kpi.
-- Contract: (jsonb) -> jsonb {data:{value,unit_key,state}, provenance}.

-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, 2026-09-27): `freshness_at` = nejnovější čas
-- univerza bloku, spočtený ze STEJNÝCH řádků jako hodnota. Pořadí zdrojů času: čas ze zdroje
-- (u Money `source_modified_at`, až bude úplný; u jízd/událostí `occurred_at`) › příchod verze
-- dokladu (`created_at`). NE `ingested_at`/`updated_at` — ty přepisuje KAŽDÝ import (naměřeno
-- 2026-09-27: 813 smluv = jediný čas), takže by lhaly jako faktury zamrzlé na exportu ze 6. 8.
-- Hranice `created_at`: backfill starých dokladů má čas dnešní — pravda o příchodu, ne o obsahu.
-- Prázdné univerzum → `trace_id` nese `:no_data` a čas je jen záloha `coalesce(…, now())`.
-- Stav linky (běží/neběží) sem NEPATŘÍ — je to jiný signál.
create or replace function public.get_vedeni_finance_kpi(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with p as (
    select coalesce(nullif(p_params->>'metric',''), 'pohledavky') as m,
           coalesce((p_params->>'days')::int, 30)                 as days
  ),
  win as (select (now() - make_interval(days => (select days from p)))::date as since),
  -- Faktury s validní částkou; směr rozlišuje pohledávku (issued) od závazku (received).
  inv as (
    select
      r.created_at as vznik,
      coalesce(r.metadata->>'direction','issued')            as dir,
      (r.metadata->'financial'->>'totalAmount')::numeric     as total,
      (r.metadata->'financial'->>'dueDate')::date            as due,
      nullif(r.metadata->'financial'->>'paidDate','')::date  as paid,
      r.doc_date
    from public.document_registry r
    where r.doc_type = 'invoice'
      and r.doc_date >= date '2024-01-01'
      and r.metadata->'financial'->>'totalAmount' ~ '^-?[0-9]+(\.[0-9]+)?$'
  ),
  -- Řádky kamene (unit='t') na fakturách/dodacích listech — tuny a jejich hodnota.
  stone as (
    select
      r.created_at as vznik,
      r.doc_type,
      coalesce(r.metadata->>'direction','issued')  as dir,
      r.doc_date,
      (l->>'quantity')::numeric                     as qty,
      case when l->>'lineTotal' ~ '^-?[0-9]+(\.[0-9]+)?$'
           then (l->>'lineTotal')::numeric end      as line_total
    from public.document_registry r
    cross join lateral jsonb_array_elements(coalesce(r.metadata->'lines','[]'::jsonb)) l
    where r.doc_date >= (select since from win)
      and l->>'unit' = 't'
      and l->>'quantity' ~ '^-?[0-9]+(\.[0-9]+)?$'
  ),
  v as (
    select case (select m from p)
      -- ── Pohledávky (vydané, neuhrazené) ──
      when 'pohledavky' then
        (select sum(total) from inv where dir = 'issued' and paid is null)
      when 'pohledavky_po_splatnosti' then
        (select sum(total) from inv where dir = 'issued' and paid is null and due < current_date)
      -- ── Závazky (přijaté, neuhrazené) ──
      when 'zavazky' then
        (select sum(total) from inv where dir = 'received' and paid is null)
      when 'zavazky_po_splatnosti' then
        (select sum(total) from inv where dir = 'received' and paid is null and due < current_date)
      -- Čistá pozice = kolik nám dluží mínus kolik dlužíme.
      when 'cista_pozice' then
        (select coalesce(sum(total) filter (where dir='issued'  and paid is null), 0)
              - coalesce(sum(total) filter (where dir='received' and paid is null), 0)
           from inv)
      -- ── Tok (v okně) ──
      when 'vyfakturovano_30d' then
        (select sum(total) from inv where dir = 'issued' and doc_date >= (select since from win))
      -- DSO = pohledávky / (roční fakturace / 365). Bez fakturace = NEMĚŘENO.
      when 'dso' then
        (select case when a.rev > 0
                     then round(coalesce(o.open, 0) / (a.rev / 365.0))
                end
           from (select sum(total) rev from inv
                  where dir='issued' and doc_date >= current_date - 365) a,
                (select sum(total) open from inv where dir='issued' and paid is null) o)
      -- ── Materiál (řádky t) ──
      when 'vyvezeno_t' then
        (select sum(qty) from stone where doc_type = 'delivery_note' and dir = 'issued')
      when 'vyvezeno_hodnota' then
        (select sum(line_total) from stone where doc_type = 'invoice' and dir = 'issued')
      when 'fakturovano_t' then
        (select sum(qty) from stone where doc_type = 'invoice' and dir = 'issued')
      when 'cena_za_tunu' then
        (select case when sum(qty) > 0 then round(sum(line_total) / sum(qty))
                end from stone where doc_type = 'invoice' and dir = 'issued')
      -- Fakturační skluz = kolik z vyvezeného (dodací listy) ještě není na faktuře.
      when 'fakturacni_skluz_pct' then
        (select case when d.deliv > 0 then round(100.0 * (d.deliv - i.inv) / d.deliv) end
           from (select coalesce(sum(qty),0) deliv from stone where doc_type='delivery_note' and dir='issued') d,
                (select coalesce(sum(qty),0) inv   from stone where doc_type='invoice'       and dir='issued') i)
      else null
    end as value
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'value', (select value from v),
      'unit_key', case (select m from p)
        when 'vyvezeno_t'    then 'app.vedeni.unit.t'
        when 'fakturovano_t' then 'app.vedeni.unit.t'
        when 'cena_za_tunu'  then 'app.vedeni.unit.czk_t'
        when 'dso'           then 'app.vedeni.unit.days'
        when 'fakturacni_skluz_pct' then 'app.vedeni.unit.pct'
        else 'app.vedeni.unit.czk'
      end,
      'state', 'ok'
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'money-s5',
      'freshness_at', to_char(coalesce(greatest((select max(vznik) from inv), (select max(vznik) from stone)), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'vedeni-kpi:' || (select m from p)
                      || case when greatest((select max(vznik) from inv), (select max(vznik) from stone)) is null then ':no_data' else '' end
    )
  );
$$;

revoke all on function public.get_vedeni_finance_kpi(jsonb) from public, anon;
grant execute on function public.get_vedeni_finance_kpi(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_vedeni_overdue.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'table' block: WHO owes the most past due — unpaid, past-due
-- invoices grouped by counterparty, worst exposure first. p_params->>'direction'
-- ('issued'=pohledávky, 'received'=závazky). p_params->>'limit' (default 12).
--
-- Reads document_registry (metadata contract: see get_vedeni_finance_kpi). A row is
-- one counterparty: number of overdue invoices, total Kč past due, and age of the
-- oldest one (the number that decides whether it is a phone call or a lawyer).
--
-- SECURITY INVOKER → RLS on document_registry fails closed. Contract:
-- (jsonb) -> jsonb {data:{columns[],row_kind,rows[]}, provenance}.

-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, 2026-09-27): `freshness_at` = nejnovější čas
-- univerza bloku, spočtený ze STEJNÝCH řádků jako hodnota. Pořadí zdrojů času: čas ze zdroje
-- (u Money `source_modified_at`, až bude úplný; u jízd/událostí `occurred_at`) › příchod verze
-- dokladu (`created_at`). NE `ingested_at`/`updated_at` — ty přepisuje KAŽDÝ import (naměřeno
-- 2026-09-27: 813 smluv = jediný čas), takže by lhaly jako faktury zamrzlé na exportu ze 6. 8.
-- Hranice `created_at`: backfill starých dokladů má čas dnešní — pravda o příchodu, ne o obsahu.
-- Prázdné univerzum → `trace_id` nese `:no_data` a čas je jen záloha `coalesce(…, now())`.
-- Stav linky (běží/neběží) sem NEPATŘÍ — je to jiný signál.
create or replace function public.get_vedeni_overdue(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with p as (
    select case when p_params->>'direction' = 'received' then 'received' else 'issued' end as dir,
           coalesce((p_params->>'limit')::int, 12) as lim
  ),
  overdue as (
    select
      r.created_at as vznik,
      coalesce(nullif(r.counterparty,''), '—')            as party,
      (r.metadata->'financial'->>'totalAmount')::numeric  as total,
      (r.metadata->'financial'->>'dueDate')::date         as due
    from public.document_registry r, p
    where r.doc_type = 'invoice'
      and coalesce(r.metadata->>'direction','issued') = p.dir
      and r.doc_date >= date '2024-01-01'
      and nullif(r.metadata->'financial'->>'paidDate','') is null
      and r.metadata->'financial'->>'totalAmount' ~ '^-?[0-9]+(\.[0-9]+)?$'
      and (r.metadata->'financial'->>'dueDate')::date < current_date
  ),
  per_party as (
    select party,
           count(*)              as cnt,
           sum(total)            as amount,
           max(current_date - due) as oldest_days
    from overdue
    group by party
    order by sum(total) desc
    limit (select lim from p)
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'row_kind', 'overdue_party',
      'columns', jsonb_build_array(
        jsonb_build_object('key','party',  'label_key','app.vedeni.col.party',  'align','left'),
        jsonb_build_object('key','count',  'label_key','app.vedeni.col.count',  'align','right'),
        jsonb_build_object('key','amount', 'label_key','app.vedeni.col.overdue','align','right'),
        jsonb_build_object('key','oldest', 'label_key','app.vedeni.col.oldest', 'align','right')
      ),
      'rows', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id',     md5(party),
            'party',  party,
            'count',  cnt,
            'amount', round(amount),
            'oldest', oldest_days
          ) order by amount desc
        ) from per_party
      ), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'money-s5',
      'freshness_at', to_char(coalesce((select max(vznik) from overdue), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'vedeni-overdue:' || (select dir from p)
                      || case when (select max(vznik) from overdue) is null then ':no_data' else '' end
    )
  );
$$;

revoke all on function public.get_vedeni_overdue(jsonb) from public, anon;
grant execute on function public.get_vedeni_overdue(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_vedeni_top_customers.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'table' block: top customers by revenue — how concentrated the
-- business is. Issued invoices over the window (p_params->>'days', default 365)
-- summed per counterparty, with each one's share of total turnover. The share
-- column is the point: a single customer at 40 %+ is a dependency risk the owner
-- should see named, not buried. p_params->>'limit' (default 10).
--
-- Reads document_registry (metadata contract: see get_vedeni_finance_kpi).
-- SECURITY INVOKER → RLS on document_registry fails closed. Contract:
-- (jsonb) -> jsonb {data:{columns[],row_kind,rows[]}, provenance}.

-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, 2026-09-27): `freshness_at` = nejnovější čas
-- univerza bloku, spočtený ze STEJNÝCH řádků jako hodnota. Pořadí zdrojů času: čas ze zdroje
-- (u Money `source_modified_at`, až bude úplný; u jízd/událostí `occurred_at`) › příchod verze
-- dokladu (`created_at`). NE `ingested_at`/`updated_at` — ty přepisuje KAŽDÝ import (naměřeno
-- 2026-09-27: 813 smluv = jediný čas), takže by lhaly jako faktury zamrzlé na exportu ze 6. 8.
-- Hranice `created_at`: backfill starých dokladů má čas dnešní — pravda o příchodu, ne o obsahu.
-- Prázdné univerzum → `trace_id` nese `:no_data` a čas je jen záloha `coalesce(…, now())`.
-- Stav linky (běží/neběží) sem NEPATŘÍ — je to jiný signál.
create or replace function public.get_vedeni_top_customers(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with p as (
    select coalesce((p_params->>'days')::int, 365) as days,
           coalesce((p_params->>'limit')::int, 10) as lim
  ),
  win as (select (now() - make_interval(days => (select days from p)))::date as since),
  billed as (
    select
      r.created_at as vznik,
      coalesce(nullif(r.counterparty,''), '—')           as party,
      (r.metadata->'financial'->>'totalAmount')::numeric as total
    from public.document_registry r
    where r.doc_type = 'invoice'
      and coalesce(r.metadata->>'direction','issued') = 'issued'
      and r.doc_date >= (select since from win)
      and r.metadata->'financial'->>'totalAmount' ~ '^-?[0-9]+(\.[0-9]+)?$'
  ),
  total as (select nullif(sum(total), 0) as grand from billed),
  per_party as (
    select party, count(*) as cnt, sum(total) as revenue
    from billed
    group by party
    order by sum(total) desc
    limit (select lim from p)
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'row_kind', 'customer',
      'columns', jsonb_build_array(
        jsonb_build_object('key','party',   'label_key','app.vedeni.col.party',   'align','left'),
        jsonb_build_object('key','revenue', 'label_key','app.vedeni.col.revenue', 'align','right'),
        jsonb_build_object('key','share',   'label_key','app.vedeni.col.share',   'align','right'),
        jsonb_build_object('key','count',   'label_key','app.vedeni.col.invoices','align','right')
      ),
      'rows', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id',      md5(party),
            'party',   party,
            'revenue', round(revenue),
            -- podíl na obratu; bez obratu (grand null) je NEMĚŘENO, ne 0
            'share',   case when (select grand from total) is not null
                            then round(100.0 * revenue / (select grand from total)) end,
            'count',   cnt
          ) order by revenue desc
        ) from per_party
      ), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'money-s5',
      'freshness_at', to_char(coalesce((select max(vznik) from billed), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'vedeni-top-customers'
                      || case when (select max(vznik) from billed) is null then ':no_data' else '' end
    )
  );
$$;

revoke all on function public.get_vedeni_top_customers(jsonb) from public, anon;
grant execute on function public.get_vedeni_top_customers(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_vedeni_vyhled_inkasa.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'chart' block (kind='bar'): cash-flow outlook — how much is due
-- to come IN over the next 30 days, bucketed by week, from unpaid issued invoices
-- whose dueDate falls ahead of today. This is the "what should land in the account"
-- line, deliberately SEPARATE from money already past due (that is get_vedeni_aging /
-- _overdue) — mixing the two would let overdue debt masquerade as expected inflow.
-- p_params->>'weeks' (default 4 → the horizon the owner plans wages and diesel on).
--
-- Reads document_registry (metadata contract: see get_vedeni_finance_kpi). Unpaid =
-- financial.paidDate IS NULL; due in [today, today + weeks·7). SECURITY INVOKER →
-- RLS fails closed. Contract: (jsonb) -> jsonb {data:{kind,unit_key,points[]}, provenance}.

-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, 2026-09-27): `freshness_at` = nejnovější čas
-- univerza bloku, spočtený ze STEJNÝCH řádků jako hodnota. Pořadí zdrojů času: čas ze zdroje
-- (u Money `source_modified_at`, až bude úplný; u jízd/událostí `occurred_at`) › příchod verze
-- dokladu (`created_at`). NE `ingested_at`/`updated_at` — ty přepisuje KAŽDÝ import (naměřeno
-- 2026-09-27: 813 smluv = jediný čas), takže by lhaly jako faktury zamrzlé na exportu ze 6. 8.
-- Hranice `created_at`: backfill starých dokladů má čas dnešní — pravda o příchodu, ne o obsahu.
-- Prázdné univerzum → `trace_id` nese `:no_data` a čas je jen záloha `coalesce(…, now())`.
-- Stav linky (běží/neběží) sem NEPATŘÍ — je to jiný signál.
create or replace function public.get_vedeni_vyhled_inkasa(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with p as (
    select coalesce((p_params->>'weeks')::int, 4) as weeks,
           coalesce((p_params->>'days')::int, 30)  as horizon
  ),
  due as (
    select
      r.created_at as vznik,
      (r.metadata->'financial'->>'totalAmount')::numeric as total,
      (r.metadata->'financial'->>'dueDate')::date        as due
    from public.document_registry r
    where r.doc_type = 'invoice'
      and coalesce(r.metadata->>'direction','issued') = 'issued'
      and r.doc_date >= date '2024-01-01'
      and nullif(r.metadata->'financial'->>'paidDate','') is null
      and r.metadata->'financial'->>'totalAmount' ~ '^-?[0-9]+(\.[0-9]+)?$'
      and (r.metadata->'financial'->>'dueDate')::date >= current_date
      and (r.metadata->'financial'->>'dueDate')::date
            < current_date + (select horizon from p)
  ),
  -- Kostra týdnů (i prázdné) × naměřené sumy. Poslední koš pohltí zbytek horizontu
  -- (LEAST), takže „+3–4 týdny" pokrývá dny 22–30, ne jen jeden týden.
  weeks as (
    select gs as w from generate_series(0, (select weeks from p) - 1) gs
  ),
  agg as (
    select
      w.w,
      -- začátek/konec týdenního okna jako DATA (chart point label nemá i18n kanál);
      -- poslední koš končí na horizontu, ne po sedmi dnech.
      current_date + (w.w * 7)                                         as w_start,
      least(current_date + (w.w * 7) + 6,
            current_date + (select horizon from p) - 1)                as w_end,
      coalesce(sum(d.total) filter (
        where least((d.due - current_date) / 7, (select weeks from p) - 1) = w.w
      ), 0) as amount
    from weeks w
    left join due d on true
    group by w.w
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'kind', 'bar',
      'unit_key', 'app.vedeni.unit.czk',
      'points', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'label', to_char(w_start, 'DD.MM.') || '–' || to_char(w_end, 'DD.MM.'),
            'value', round(amount)
          ) order by w
        ) from agg
      ), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'money-s5',
      'freshness_at', to_char(coalesce((select max(vznik) from due), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'vedeni-vyhled-inkasa'
                      || case when (select max(vznik) from due) is null then ':no_data' else '' end
    )
  );
$$;

revoke all on function public.get_vedeni_vyhled_inkasa(jsonb) from public, anon;
grant execute on function public.get_vedeni_vyhled_inkasa(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_visible_partners.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_visible_partners
-- Arguments: p_city TEXT
-- Description: Returns visible certified partners, optionally filtered by city.
-- Restored 2026-01-08: Full parameterized version from migration 20251220030000.
-- Security: SECURITY DEFINER, public access (seznam partnerů je veřejný - bez sensitive data/PII dat)
-- @security: public
-- @audit: none

CREATE OR REPLACE FUNCTION public.get_visible_partners(p_city TEXT DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $function$
DECLARE
  v_result JSONB;
BEGIN
  SELECT jsonb_agg(row_to_json(p)::jsonb)
  INTO v_result
  FROM (
    SELECT 
      pp.id,
      pp.user_id,
      pp.certification_level,
      pp.is_production_provider,
      pp.business_name,
      pp.display_name,
      pp.description,
      pp.city,
      pp.country,
      pp.website,
      pp.services,
      pp.is_visible,
      pp.accepts_online_appointments,
      pp.accepts_in_person_appointments,
      pp.certification_passed_at,
      pp.certification_score,
      pp.avatar_url,
      pp.created_at,
      pp.updated_at
    FROM partner_profiles pp
    WHERE pp.is_visible = TRUE
      AND pp.certification_passed_at IS NOT NULL
      AND (p_city IS NULL OR pp.city = p_city)
    ORDER BY pp.certification_level DESC, pp.display_name
  ) p;

  RETURN jsonb_build_object(
    'partners', COALESCE(v_result, '[]'::JSONB),
    'isAuthenticated', auth.uid() IS NOT NULL
  );
END;
$function$;

COMMENT ON FUNCTION public.get_visible_partners(text) IS 
  'Get visible partner profiles for directory with optional city filter. RPC-only.';

-- Permissions (PUBLIC: seznam partnerů je veřejný - bez sensitive data/PII dat)
REVOKE ALL ON FUNCTION public.get_visible_partners(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_visible_partners(TEXT) TO public;


