SET search_path TO 'public'
AS $$
  SELECT j.id, j.story_id, j.kind, j.source_type, j.status, j.source_url, j.source_storage_path,
         j.brief, j.slot_profile, j.extracted_tokens, j.result_canvas_html, j.applied_to_page_id,
