-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/insert_knowledge_chunk.sql
-- -----------------------------------------------------------------------------

-- Function: insert_knowledge_chunk

-- Brick3 locale axis: p_locale appended (7-arg). DROP the old 6-arg overload first
-- so the added trailing arg does not create a second overload (PGRST203 ambiguity).
DROP FUNCTION IF EXISTS public.insert_knowledge_chunk(integer,text,uuid,text,text,integer);
-- PR-1 ingest provenance & dedup: p_source_hash + p_char_start/p_char_end appended
-- (10-arg). DROP the 7-arg overload for the same PGRST203 reason. source_hash column
-- existed but was never written; char-span columns land in the same change. The
-- upsert becomes skip-if-unchanged on the content key so re-syncs are no-ops.
DROP FUNCTION IF EXISTS public.insert_knowledge_chunk(integer,text,uuid,text,text,integer,text);

CREATE OR REPLACE FUNCTION public.insert_knowledge_chunk(p_chunk_index integer, p_chunk_text text, p_knowledge_item_id uuid, p_section_title text DEFAULT NULL::text, p_source_field text DEFAULT 'body'::text, p_token_count integer DEFAULT NULL::integer, p_locale text DEFAULT 'global'::text, p_source_hash text DEFAULT NULL::text, p_char_start integer DEFAULT NULL::integer, p_char_end integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required';
  END IF;

  INSERT INTO knowledge_chunks (
    knowledge_item_id, chunk_index, chunk_text, token_count, section_title, source_field, locale,
    source_hash, char_start, char_end
  )
  VALUES (
    p_knowledge_item_id, p_chunk_index, p_chunk_text, p_token_count, p_section_title, COALESCE(p_source_field, 'body'), COALESCE(p_locale, 'global'),
    p_source_hash, p_char_start, p_char_end
  )
  ON CONFLICT (knowledge_item_id, chunk_index, locale) DO UPDATE
    SET chunk_text    = EXCLUDED.chunk_text,
        token_count   = EXCLUDED.token_count,
        section_title = EXCLUDED.section_title,
        source_field  = EXCLUDED.source_field,
        source_hash   = EXCLUDED.source_hash,
        char_start    = EXCLUDED.char_start,
        char_end      = EXCLUDED.char_end
    -- skip-if-unchanged: identical NON-NULL content key is a no-op, so replays do not
    -- churn rows. A NULL stored hash always updates (legacy rows converge on first
    -- re-ingest); NULL-safety via IS DISTINCT FROM.
    WHERE knowledge_chunks.source_hash IS NULL
       OR knowledge_chunks.source_hash IS DISTINCT FROM EXCLUDED.source_hash
  RETURNING knowledge_chunks.id INTO v_id;

  IF v_id IS NULL THEN
    -- conflict row already carries this content key → skipped (idempotent re-ingest)
    SELECT kc.id INTO v_id
    FROM knowledge_chunks kc
    WHERE kc.knowledge_item_id = p_knowledge_item_id
      AND kc.chunk_index = p_chunk_index
      AND kc.locale = COALESCE(p_locale, 'global');
    RETURN jsonb_build_object('id', v_id, 'skipped', true);
  END IF;

  RETURN jsonb_build_object('id', v_id, 'skipped', false);
END;
$function$

;

REVOKE ALL ON FUNCTION insert_knowledge_chunk(integer,text,uuid,text,text,integer,text,text,integer,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION insert_knowledge_chunk(integer,text,uuid,text,text,integer,text,text,integer,integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/insert_knowledge_embedding.sql
-- -----------------------------------------------------------------------------

-- Function: insert_knowledge_embedding

-- Brick3 locale axis: p_locale appended (6-arg). DROP the old 5-arg overload first
-- so the added trailing arg does not create a second overload (PGRST203 ambiguity).
DROP FUNCTION IF EXISTS public.insert_knowledge_embedding(uuid,text,uuid,text,text);

CREATE OR REPLACE FUNCTION public.insert_knowledge_embedding(p_chunk_id uuid, p_embedding text, p_knowledge_item_id uuid, p_model text DEFAULT 'text-embedding-3-small'::text, p_model_version text DEFAULT NULL::text, p_locale text DEFAULT 'global'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_model_registry_id uuid;
BEGIN
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required';
  END IF;

  IF p_chunk_id IS NULL OR p_embedding IS NULL OR p_embedding = '' THEN
    RETURN jsonb_build_object('error', 'p_chunk_id and p_embedding are required');
  END IF;

  -- Brick2-guard: resolve the canonical ai_model_registry row for the named embedding
  -- model and PIN its id onto the row (precedence: FK-linked provider row first, mirrors
  -- fn_resolve_embedding_model). Fail loud if the model is unregistered — silently writing
  -- a NULL model_registry_id would let an unknown model's vectors join the corpus with no
  -- identity, breaking the model-as-index-constant invariant the cross-model guard enforces.
  SELECT id INTO v_model_registry_id
  FROM public.ai_model_registry
  WHERE model_id = p_model AND is_embedding
  ORDER BY (provider_registry_id IS NOT NULL) DESC
  LIMIT 1;

  IF v_model_registry_id IS NULL THEN
    RAISE EXCEPTION 'Embedding model % is not a registered is_embedding model in ai_model_registry', p_model
      USING ERRCODE = '23503';
  END IF;

  INSERT INTO knowledge_embeddings (chunk_id, knowledge_item_id, embedding, model, model_version, model_registry_id, locale)
  VALUES (p_chunk_id, p_knowledge_item_id, p_embedding::vector(1024), p_model, p_model_version, v_model_registry_id, COALESCE(p_locale, 'global'))
  ON CONFLICT (chunk_id, locale) DO UPDATE
    SET embedding         = EXCLUDED.embedding,
        model             = EXCLUDED.model,
        model_version     = EXCLUDED.model_version,
        model_registry_id = EXCLUDED.model_registry_id,
        created_at        = now();

  RETURN jsonb_build_object('status', 'inserted', 'chunk_id', p_chunk_id);
END;
$function$

;

REVOKE ALL ON FUNCTION insert_knowledge_embedding(uuid,text,uuid,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION insert_knowledge_embedding(uuid,text,uuid,text,text,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/insert_knowledge_embedding_v2_audited.sql
-- -----------------------------------------------------------------------------

-- Function: insert_knowledge_embedding_v2_audited
-- Single text-input audited writer for the v2 (Qwen3, halfvec(2560)) embedding space —
-- mirrors the v1 path insert_knowledge_embedding(p_embedding text). Takes the embedding
-- as a JSON text array (what PostgREST/rpcService send), casts it to halfvec(2560),
-- updates the v2 columns and writes its audit_journal row (the _audited contract).
--
-- ONE overload by design: the prior vector/halfvec typed overloads were a back-port
-- artifact with identical parameter names (PGRST203 ambiguity) and zero callers, so they
-- are consolidated into this canonical text form (rewrite, not capability removal — the
-- v2 SPACE itself, the halfvec(2560) column + mcp_search_v3 v1/v2 routing, is untouched).
-- The SPACE choice (v1 1536 vs v2 2560) is the per-context decision the resolver makes
-- upstream; this writer only persists the resolved v2 vector.

-- Brick3 locale axis: p_locale appended (5-arg). The v2 writer UPDATEs an existing
-- knowledge_embeddings row; with the widened (chunk_id, locale) unique it must
-- scope by locale to target the right per-locale row. DROP the old 4-arg overload
-- first so the added trailing arg does not create a second overload (PGRST203).
DROP FUNCTION IF EXISTS public.insert_knowledge_embedding_v2_audited(uuid,text,text,text);

CREATE OR REPLACE FUNCTION public.insert_knowledge_embedding_v2_audited(p_chunk_id uuid, p_embedding_v2 text, p_model text, p_model_version text, p_locale text DEFAULT 'global'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_model_v2_registry_id uuid;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;
  IF p_chunk_id IS NULL THEN
    RAISE EXCEPTION 'p_chunk_id is required';
  END IF;
  IF p_embedding_v2 IS NULL OR p_embedding_v2 = '' THEN
    RAISE EXCEPTION 'p_embedding_v2 is required';
  END IF;
  IF p_model IS NULL OR p_model = '' THEN
    RAISE EXCEPTION 'p_model is required';
  END IF;

  -- Brick2-guard: resolve + PIN the canonical ai_model_registry id for the v2 model
  -- (same precedence as fn_resolve_embedding_model). Fail loud on an unregistered model
  -- rather than silently leaving model_v2_registry_id NULL — an unknown v2 model's halfvec
  -- vectors must never join the corpus without a verifiable identity.
  SELECT id INTO v_model_v2_registry_id
  FROM public.ai_model_registry
  WHERE model_id = p_model AND is_embedding
  ORDER BY (provider_registry_id IS NOT NULL) DESC
  LIMIT 1;

  IF v_model_v2_registry_id IS NULL THEN
    RAISE EXCEPTION 'Embedding model % is not a registered is_embedding model in ai_model_registry', p_model
      USING ERRCODE = '23503';
  END IF;

  UPDATE public.knowledge_embeddings
     SET embedding_v2        = p_embedding_v2::halfvec(2560),
         model_v2            = p_model,
         model_v2_version    = p_model_version,
         model_v2_registry_id = v_model_v2_registry_id,
         v2_generated_at     = now(),
         v2_status           = 'generated'
   WHERE chunk_id = p_chunk_id
     AND locale = COALESCE(p_locale, 'global');

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'knowledge.embedding_v2_generated',
    jsonb_build_object('chunk_id', p_chunk_id, 'model', p_model, 'version', p_model_version, 'locale', COALESCE(p_locale, 'global'))
  );

  RETURN jsonb_build_object('ok', true, 'chunk_id', p_chunk_id);
END;
$function$
;

REVOKE ALL ON FUNCTION insert_knowledge_embedding_v2_audited(uuid,text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION insert_knowledge_embedding_v2_audited(uuid,text,text,text,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/install_agent_as_story.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: install_agent_as_story
-- Purpose: Install a published marketplace agent (kind='agent') as a NEW
--          consumer-owned story ("run-as-story"). Mints partner_stories +
--          story_rulesets + story_contexts from the agent's declarative
--          agent_spec, and hydrates the agent's knowledge items under the new
--          story_id (per-story KB isolation in mcp_search_knowledge_v3 /
--          compose_context then scopes them to this story).
--
-- Reuses the create_story_from_preset minting shape but: (a) sources config from
-- plugin_catalog.agent_spec instead of project_presets, (b) hydrates KB, and
-- (c) fixes the create_story_from_preset ACL gap by verifying the caller owns
-- p_partner_id.
--
-- This is NOT import_story_bundle — that is same-story replica sync and cannot
-- mint a consumer-owned copy of another author's content.
-- Security: SECURITY DEFINER + REVOKE/GRANT.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.install_agent_as_story(
  p_plugin_id  uuid,
  p_partner_id uuid DEFAULT NULL,
  p_title      text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id      uuid := auth.uid();
  v_plugin       record;
  v_spec         jsonb;
  v_rule_slugs   text[];
  v_rule_ids     uuid[];
  v_rule_versions jsonb;
  v_fingerprint  text;
  v_story_id     uuid;
  v_ruleset_id   uuid;
  v_title        text;
  v_kb_item      jsonb;
  v_kb_count     integer := 0;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'P0001';
  END IF;

  -- ACL: if a partner identity is supplied, the caller must own it.
  IF p_partner_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.partner_profiles
       WHERE id = p_partner_id AND user_id = v_user_id
    ) THEN
      RAISE EXCEPTION 'partner_id % is not owned by the caller', p_partner_id
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- Resolve the agent; only marketplace-visible agents are installable.
  SELECT pc.id, pc.slug, pc.name, pc.kind, pc.status, pc.agent_spec
    INTO v_plugin
    FROM public.plugin_catalog pc
   WHERE pc.id = p_plugin_id;

  IF v_plugin.id IS NULL THEN
    RAISE EXCEPTION 'Agent not found: %', p_plugin_id USING ERRCODE = 'P0002';
  END IF;

  IF v_plugin.kind <> 'agent' THEN
    RAISE EXCEPTION 'Plugin % is not an agent', p_plugin_id USING ERRCODE = 'P0002';
  END IF;

  IF v_plugin.status NOT IN ('canary'::public.plugin_status, 'ga'::public.plugin_status) THEN
    RAISE EXCEPTION 'Agent % is not available for install (status=%)', p_plugin_id, v_plugin.status
      USING ERRCODE = 'P0002';
  END IF;

  v_spec := v_plugin.agent_spec;
  IF v_spec IS NULL THEN
    RAISE EXCEPTION 'Agent % has no run-as-story template (call-mode only)', p_plugin_id
      USING ERRCODE = 'P0002';
  END IF;

  v_title := COALESCE(p_title, v_plugin.name, 'Agent: ' || v_plugin.slug);

  -- Resolve published rules referenced by the agent template (optional).
  v_rule_slugs := ARRAY(
    SELECT jsonb_array_elements_text(COALESCE(v_spec->'rule_slugs', '[]'::jsonb))
  );

  IF array_length(v_rule_slugs, 1) > 0 THEN
    SELECT array_agg(er.id ORDER BY er.slug),
           jsonb_object_agg(er.slug, er.version)
      INTO v_rule_ids, v_rule_versions
      FROM public.expert_rules er
     WHERE er.slug = ANY(v_rule_slugs)
       AND er.status = 'published';
  END IF;

  -- Mint the consumer-owned story.
  v_story_id := gen_random_uuid();
  INSERT INTO public.partner_stories (
    id, partner_id, user_id, title, status, priority,
    tech_stack, domain, risk_profile, origin
  ) VALUES (
    v_story_id, p_partner_id, v_user_id, v_title, 'active', 'normal',
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_spec->'tech_stack', '[]'::jsonb))),
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_spec->'domain', '[]'::jsonb))),
    COALESCE(v_spec->>'risk_profile', 'medium'),
    'agent_install'
  );

  -- Create ruleset + context only when the agent references published rules.
  IF v_rule_ids IS NOT NULL AND array_length(v_rule_ids, 1) > 0 THEN
    SELECT 'rset:agent:' || v_plugin.slug || '-' || array_length(v_rule_ids, 1) || '-rules:'
        || md5(string_agg(er.slug || ':' || er.version::text, ',' ORDER BY er.slug))
      INTO v_fingerprint
      FROM public.expert_rules er
     WHERE er.id = ANY(v_rule_ids);

    v_ruleset_id := gen_random_uuid();
    INSERT INTO public.story_rulesets (
      id, story_id, rule_ids, rule_versions,
      context_profile, ruleset_fingerprint, created_by
    ) VALUES (
      v_ruleset_id, v_story_id, v_rule_ids, v_rule_versions,
      COALESCE(v_spec->>'context_profile', 'repo_plus_rules'),
      v_fingerprint, 'agent:' || v_plugin.slug
    );
  END IF;

  INSERT INTO public.story_contexts (story_id, ruleset_id, build_config, env_hints)
  VALUES (
    v_story_id, v_ruleset_id,
    COALESCE(v_spec->'build_config', '{}'::jsonb),
    '{}'::jsonb
  );

  -- Hydrate the agent's knowledge items under the new story_id (story-scoped,
  -- private). Per-story KB isolation then protects them from non-participants.
  FOR v_kb_item IN
    SELECT value FROM jsonb_array_elements(COALESCE(v_spec->'knowledge_items', '[]'::jsonb)) AS value
  LOOP
    INSERT INTO public.knowledge_items (
      item_type, source_type, source_slug,
      title, summary, body_markdown, ai_context_tags,
      status, visibility, author_id, story_id
    ) VALUES (
      COALESCE(v_kb_item->>'item_type', 'domain_doc')::knowledge_item_type,
      'agent_install',
      v_plugin.slug,
      v_kb_item->>'title',
      v_kb_item->>'summary',
      v_kb_item->>'body_markdown',
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_kb_item->'ai_context_tags', '[]'::jsonb))),
      'active',
      'private',
      v_user_id,
      v_story_id
    );
    v_kb_count := v_kb_count + 1;
  END LOOP;

  -- Audit
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_user_id, 'AGENT_INSTALLED', jsonb_build_object(
    'area', 'marketplace',
    'severity', 'info',
    'plugin_id', p_plugin_id,
    'slug', v_plugin.slug,
    'story_id', v_story_id,
    'partner_id', p_partner_id,
    'rule_count', COALESCE(array_length(v_rule_ids, 1), 0),
    'kb_count', v_kb_count
  ));

  RETURN jsonb_build_object(
    'story_id', v_story_id,
    'ruleset_id', v_ruleset_id,
    'plugin_id', p_plugin_id,
    'slug', v_plugin.slug,
    'rule_count', COALESCE(array_length(v_rule_ids, 1), 0),
    'kb_count', v_kb_count
  );
END;
$$;

COMMENT ON FUNCTION public.install_agent_as_story(uuid, uuid, text) IS
  'Install a published marketplace agent as a new consumer-owned story (run-as-story). Mints story + ruleset + context + story-scoped KB from agent_spec.';

REVOKE ALL ON FUNCTION public.install_agent_as_story(uuid, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.install_agent_as_story(uuid, uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.install_agent_as_story(uuid, uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/invoice_state.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: invoice_state
-- Popis: STAV POHLEDÁVKY jednoho dokladu — jeden slovník pro všechny čtečky
--        (karta protistrany, stáří dluhu, faktury odběratele, dlužníci, Ask).
--        Vrací klíč stavu; i18n klíč buňky je 'app.inv.state.' || stav.
--
--          storno      doklad stornovaný ve zdroji — není dluh, není vyfakturováno,
--                      nemá stáří. KTERÉ hodnoty pole `storno` znamenají storno,
--                      je KÓDOVÁNÍ ZDROJE, ne vlastnost platformy: deklaruje ho
--                      instance (`storno_values` v source_params, viz
--                      storno_values_param). Bez deklarace se storno nerozpozná.
--                      (RIQ/Money, naměřeno 2026-09-26: 1 = stornovaný doklad,
--                      2 = stornovací doklad s touž kladnou částkou — oba se dosud
--                      sčítaly do „vyfakturováno".)
--          unknown     doklad bez stavu úhrady (`amount_unpaid` chybí) — mlčet,
--                      ne hádat (starší korpus bez Money)
--          paid        zbývá 0
--          scheduled   PŘEDEPSÁNO: datum vzniku pohledávky je v budoucnu
--                      (faktura vystavená dopředu) — předpis, ne dluh
--          correction  opravný doklad (záporné `amount_unpaid`) — odečítá
--                      (rozhodnutí majitele 2026-08-05, get_receivables_overdue)
--          overdue     zbývá > 0 a splatnost minula
--          open        zbývá > 0, ve splatnosti (nebo splatnost neznáme)
--
-- ⭐ PROČ JEDNO MÍSTO: naměřeno 2026-09-25 na kartě Inspirace — pět čteček,
--    pět definic: karta dobropis nepočítala, tabulka dlužníků ano; storno
--    nepočítal nikdo; faktury vystavené dopředu (85 ks / 6,2 mil. Kč) se
--    sčítaly jako dluh a karta hlásila 588 383 Kč místo 259 597 Kč.
--
-- ⭐ OD KDY JE DOKLAD POHLEDÁVKOU = parametr instance `receivable_from`
--    (source_params bloku: issue_date | taxable_supply_date | due_date).
--    Rozhodnutí majitele 2026-09-25: datum VYSTAVENÍ — proto je to výchozí.
--    Neznámá hodnota je chyba konfigurace, ne tichý jiný výklad (viz
--    receivable_from_param).
--
-- Pořadí větví je význam: storno přebije vše; uhrazený doklad vystavený
-- dopředu je „uhrazeno", ne „předepsáno" (nic nedluží); datum v budoucnu
-- přebije splatnost (předpis nemůže být po splatnosti).
--
-- STABLE (current_date), jeden výraz bez SET → planner ji VLOŽÍ do volající
-- čtečky (vzor norm_text); tabulka dlužníků ji volá nad celým registrem faktur.
-- Nestaví na žádné tabulce, jen na operátorech pg_catalog — search_path
-- nepotřebuje. CASE drží pořadí vyhodnocení: přetypování až po regexu.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.invoice_state(
  p_fields jsonb,
  p_receivable_from text DEFAULT 'issue_date',
  p_storno_values text[] DEFAULT '{}'::text[]
)
RETURNS text
LANGUAGE sql
STABLE
AS $$
  select case
    when p_fields->'storno'->>'value' = any(p_storno_values)
      then 'storno'
    when coalesce(p_fields->'amount_unpaid'->>'value', '') !~ '^-?[0-9]+(\.[0-9]+)?$'
      then 'unknown'
    when abs((p_fields->'amount_unpaid'->>'value')::numeric) <= 0.005
      then 'paid'
    when case when p_fields->p_receivable_from->>'value' ~ '^\d{4}-\d{2}-\d{2}$'
              then (p_fields->p_receivable_from->>'value')::date end > current_date
      then 'scheduled'
    when (p_fields->'amount_unpaid'->>'value')::numeric < 0
      then 'correction'
    when case when p_fields->'due_date'->>'value' ~ '^\d{4}-\d{2}-\d{2}$'
              then (p_fields->'due_date'->>'value')::date end < current_date
      then 'overdue'
    else 'open'
  end;
$$;

REVOKE ALL ON FUNCTION public.invoice_state(jsonb, text, text[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.invoice_state(jsonb, text, text[]) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/counterparty_periods.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: counterparty_periods
-- Popis: VZTAH PROTISTRANY V ČASE z dokladů — role × období. Jedna pravda pro
--        hlavičku karty (get_counterparty_card) i Ask (answer_verified_facts).
--          customer  odběratel: NAŠE vydané faktury (document_subtype = issued)
--          supplier  dodavatel: přijaté faktury (received)
--        prvni/posledni = datum VYSTAVENÍ do dneška včetně. Faktura vystavená
--        dopředu (předpis) vztah neprodlužuje — nese ji `predepsano`.
--        bez_stavu = doklady role, k nimž zdroj NEDODAL stav úhrady
--        (invoice_state = unknown), s vlastním obdobím.
--
-- ⭐ PROČ (majitel 2026-09-28, příklad protistrany z let 2021–22): uživatel se
--    ptá na AKTUÁLNÍ stav; historie doplňuje, nesmí převážit. Firma mohla být
--    odběratelem před čtyřmi lety a dnes nic — karta ani Ask to neuměly říct
--    a odpovídaly „dluh 0 Kč" / „bez dluhu" nad fakturami, u nichž zdroj stav
--    úhrady vůbec nedodal.
-- ⭐ STAV ÚHRADY JE SNÍMEK ZDROJE s časem, kdy ho zdroj dodal. Kde snímek chybí,
--    čtečka ho nesmí nahradit nulou (naměřeno 2026-09-28: 929 protistran,
--    jejichž žádná vydaná faktura stav úhrady nenese, karta hlásila „bez dluhu").
--
-- Doklady jsou TYTÉŽ jako v kartě (counterparty_docs: podle IČO, jménem jen
-- protistrana bez IČO). Storno pozná jen z kódů instance (p_storno, viz
-- storno_values_param); stav úhrady na datu pohledávky nezávisí, proto
-- invoice_state dostává pevně issue_date.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.counterparty_periods(
  p_icos text[],
  p_names text[],
  p_storno text[] DEFAULT '{}'::text[]
)
RETURNS TABLE (
  vztah text,
  prvni date,
  posledni date,
  dokladu bigint,
  predepsano bigint,
  bez_stavu bigint,
  bez_stavu_prvni date,
  bez_stavu_posledni date
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  with d as (
    select case r.fields->'document_subtype'->>'value'
             when 'issued' then 'customer'
             when 'received' then 'supplier' end as druh,
           -- CASE drží pořadí: přetypování až po regexu
           case when r.fields->'issue_date'->>'value' ~ '^\d{4}-\d{2}-\d{2}$'
                then (r.fields->'issue_date'->>'value')::date end as vystaveno,
           public.invoice_state(r.fields, 'issue_date', coalesce(p_storno, '{}'::text[])) as stav
      from public.counterparty_docs(p_icos, p_names, 'invoice') r
  )
  select druh,
         min(vystaveno) filter (where vystaveno <= current_date),
         max(vystaveno) filter (where vystaveno <= current_date),
         count(*) filter (where vystaveno <= current_date),
         count(*) filter (where vystaveno > current_date),
         count(*) filter (where stav = 'unknown'),
         min(vystaveno) filter (where stav = 'unknown'),
         max(vystaveno) filter (where stav = 'unknown')
    from d
   where druh is not null
   group by druh
   order by druh;
$$;

REVOKE ALL ON FUNCTION public.counterparty_periods(text[], text[], text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.counterparty_periods(text[], text[], text[]) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/is_admin_or_staff.sql
-- -----------------------------------------------------------------------------

-- Function: public.is_admin_or_staff
-- Arguments: p_user_id uuid DEFAULT NULL
-- Description: Helper to check if a user is admin or staff.
-- Notes:
-- - Supports calls with 0 args via DEFAULT.
-- - Safe for use in RLS policies and SECURITY DEFINER RPCs.
-- Extracted: 2026-01-08T18:27:53+01:00

-- Historický overload bez argumentu (dnešní 1-arg varianta ho pokrývá DEFAULTem).
-- Bezpečný: na dnešní DB neexistuje, a kdyby existoval, nic na něm nevisí.
DROP FUNCTION IF EXISTS public.is_admin_or_staff();

-- ⛔ ZDE NESMÍ BÝT `DROP FUNCTION IF EXISTS public.is_admin_or_staff(uuid)`.
-- Na prázdné DB (baseline, cold start) je to neškodný no-op — ale tenhle soubor
-- je od 2026-07-30 zapojený i v heals.sql, který se přehrává na BĚŽÍCÍ databázi,
-- kde na funkci závisí 253 policies. Cold-start brána to chytila okamžitě:
--   ERROR: cannot drop function is_admin_or_staff(uuid) because other objects
--   depend on it — policy Admins and staff can view audit journal on table
--   audit_journal … and 231 other objects
-- `CREATE OR REPLACE` níž zvládne změnu těla i volatility bez zahození závislostí;
-- DROP by byl potřeba jen při změně návratového typu nebo jmen parametrů — a to
-- je změna kontraktu, která si žádá vlastní rozvahu, ne tichý DROP v heals.

CREATE OR REPLACE FUNCTION public.is_admin_or_staff(p_user_id uuid DEFAULT NULL)
RETURNS boolean
LANGUAGE plpgsql
-- STABLE: čte user_roles, nic nemění, a v rámci jednoho dotazu je výsledek
-- konstantní. Do 2026-07-30 byla funkce (defaultně) VOLATILE — jediná ze své
-- třídy (document_visible_to i is_service_role STABLE už byly). VOLATILE zakazuje
-- plánovači jakoukoli úsporu, takže se v RLS predikátu volala per řádek.
-- POZOR — samotné STABLE latenci NEŘEŠÍ: změřeno na 43 157 řádcích 10 405 ms
-- (volatile) vs 10 509 ms (stable). Postgres STABLE funkci z RLS `qual` sám
-- nevytáhne; vytáhne ji jen jako poddotaz `(select f())` → InitPlan (27 ms).
-- Volající policy tedy MUSÍ funkci obalit; tady se jen srovnává deklarace
-- s realitou (a otevírá se úspora tam, kde ji plánovač využít umí).
STABLE
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := COALESCE(p_user_id, auth.uid());
  IF v_user_id IS NULL THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.user_roles
    WHERE user_id = v_user_id
      AND role IN ('admin', 'staff')
  );
END;
$$;

-- Permissions
REVOKE ALL ON FUNCTION public.is_admin_or_staff(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_admin_or_staff(uuid) TO authenticated;
-- service_role: SECURITY INVOKER seed-chain RPCs (ensure_stack_default_story,
-- start_web_artifact_ingest) evaluate this read-only authz helper as the real
-- service_role role at boot (Postgres does not guarantee AND/OR short-circuit,
-- so it runs even when the service_role branch already passed). Returns the same
-- result (false, auth.uid() NULL) — the grant only avoids a permission error.
GRANT EXECUTE ON FUNCTION public.is_admin_or_staff(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_register_mcp_server.sql
-- -----------------------------------------------------------------------------

-- Function: aisha_register_mcp_server
-- Admin/staff registers a new MCP server into mcp_server_registry. Status starts
-- at 'discovered'; AISHA must then run aisha_test_mcp_server before bumping to
-- 'tested_ok' or 'tested_failed'. If exposes_llm=true and tests pass, AISHA
-- pairs it into ai_provider_registry as backend_kind='mcp_server'.

-- ⛔ VLASTNICTVÍ A POVĚŘENÍ (2026-09-29): `slug` je globální klíč. Dřív DO UPDATE
--    přepsal transport/endpoint/stdio_command serveru, který zaregistroval KDOKOLI
--    jiný, a ponechal mu `auth_kind`/`auth_env_var` i `status` — schválený server šel
--    přesměrovat i s jeho tajemstvím (aisha_test_mcp_server → svc-ai-chat pošle token
--    z `auth_env_var` na nový endpoint). Teď: existující registraci mění jen týž
--    vlastník (`source`, `registered_by` — IS NOT DISTINCT FROM, služba má NULL),
--    jinak 42501 s klíčem a vlastníkem. Při změně transportu, endpointu nebo příkazu
--    se vazba na tajemství NEPŘEVEZME: `auth_kind`/`auth_env_var` = jen to, co volající
--    deklaruje spolu se změnou (bez nich NULL), a `status` = 'discovered' (znovu otestovat).
CREATE OR REPLACE FUNCTION public.aisha_register_mcp_server(
  p_slug text,
  p_display_name text,
  p_transport text,
  p_endpoint_url text DEFAULT NULL,
  p_stdio_command text[] DEFAULT NULL,
  p_auth_kind text DEFAULT 'bearer',
  p_auth_env_var text DEFAULT NULL,
  p_capability_tags text[] DEFAULT '{}'::text[],
  p_exposes_llm boolean DEFAULT false,
  p_description text DEFAULT NULL,
  p_source text DEFAULT 'manual',
  p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id      uuid;
  v_user_id uuid;
  v_zdroj   text;
  v_kdo     uuid;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'admin_or_staff role required' USING ERRCODE = '22023';
  END IF;

  IF p_slug IS NULL OR p_slug = '' THEN
    RAISE EXCEPTION 'p_slug is required' USING ERRCODE = '22023';
  END IF;
  IF p_transport NOT IN ('http', 'sse', 'stdio', 'websocket') THEN
    RAISE EXCEPTION 'Invalid transport: %', p_transport USING ERRCODE = '22023';
  END IF;
  IF p_transport IN ('http', 'sse', 'websocket') AND (p_endpoint_url IS NULL OR p_endpoint_url = '') THEN
    RAISE EXCEPTION 'p_endpoint_url is required for transport %', p_transport USING ERRCODE = '22023';
  END IF;
  IF p_transport = 'stdio' AND (p_stdio_command IS NULL OR array_length(p_stdio_command, 1) IS NULL) THEN
    RAISE EXCEPTION 'p_stdio_command is required for stdio transport' USING ERRCODE = '22023';
  END IF;

  v_user_id := auth.uid();

  SELECT r.source, r.registered_by INTO v_zdroj, v_kdo
    FROM mcp_server_registry r
   WHERE r.slug = p_slug
   FOR UPDATE;
  IF FOUND AND (v_zdroj IS DISTINCT FROM p_source OR v_kdo IS DISTINCT FROM v_user_id) THEN
    RAISE EXCEPTION 'MCP server % is registered by another owner (source %, registered_by %)',
      p_slug, COALESCE(v_zdroj, '(none)'), COALESCE(v_kdo::text, '(service)')
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO mcp_server_registry (
    slug, display_name, description, transport, endpoint_url, stdio_command,
    auth_kind, auth_env_var, capability_tags, exposes_llm, status,
    source, registered_by, metadata
  )
  VALUES (
    p_slug, p_display_name, p_description, p_transport, p_endpoint_url, p_stdio_command,
    p_auth_kind, p_auth_env_var, p_capability_tags, p_exposes_llm, 'discovered',
    p_source, v_user_id, COALESCE(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (slug) DO UPDATE
  SET display_name = EXCLUDED.display_name,
      description = EXCLUDED.description,
      transport = EXCLUDED.transport,
      endpoint_url = EXCLUDED.endpoint_url,
      stdio_command = EXCLUDED.stdio_command,
      capability_tags = EXCLUDED.capability_tags,
      exposes_llm = EXCLUDED.exposes_llm,
      metadata = mcp_server_registry.metadata || EXCLUDED.metadata,
      -- Jiný cíl → vazba na tajemství jen znovu deklarovaná, server znovu k otestování.
      auth_kind = CASE WHEN (mcp_server_registry.transport, mcp_server_registry.endpoint_url, mcp_server_registry.stdio_command)
                            IS DISTINCT FROM (EXCLUDED.transport, EXCLUDED.endpoint_url, EXCLUDED.stdio_command)
                       THEN EXCLUDED.auth_kind ELSE mcp_server_registry.auth_kind END,
      auth_env_var = CASE WHEN (mcp_server_registry.transport, mcp_server_registry.endpoint_url, mcp_server_registry.stdio_command)
                               IS DISTINCT FROM (EXCLUDED.transport, EXCLUDED.endpoint_url, EXCLUDED.stdio_command)
                          THEN EXCLUDED.auth_env_var ELSE mcp_server_registry.auth_env_var END,
      status = CASE WHEN (mcp_server_registry.transport, mcp_server_registry.endpoint_url, mcp_server_registry.stdio_command)
                         IS DISTINCT FROM (EXCLUDED.transport, EXCLUDED.endpoint_url, EXCLUDED.stdio_command)
                    THEN 'discovered' ELSE mcp_server_registry.status END,
      updated_at = now()
  WHERE mcp_server_registry.source IS NOT DISTINCT FROM EXCLUDED.source
    AND mcp_server_registry.registered_by IS NOT DISTINCT FROM EXCLUDED.registered_by
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    -- Souběh: registrace změnila vlastníka mezi kontrolou a zápisem — nic se nepřevzalo.
    RAISE EXCEPTION 'MCP server % is registered by another owner', p_slug USING ERRCODE = '42501';
  END IF;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id, 'mcp.server_registered',
    jsonb_build_object(
      'mcp_server_id', v_id, 'slug', p_slug, 'transport', p_transport,
      'exposes_llm', p_exposes_llm, 'capability_tags', p_capability_tags
    )
  );

  RETURN jsonb_build_object('mcp_server_id', v_id, 'slug', p_slug, 'status', 'discovered');
END;
$$;

COMMENT ON FUNCTION public.aisha_register_mcp_server(text, text, text, text, text[], text, text, text[], boolean, text, text, jsonb) IS
  'Admin/staff registers a new MCP server. Starts at status=discovered; AISHA tests it before use.';

REVOKE ALL ON FUNCTION public.aisha_register_mcp_server(text, text, text, text, text[], text, text, text[], boolean, text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aisha_register_mcp_server(text, text, text, text, text[], text, text, text[], boolean, text, text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aisha_register_mcp_server(text, text, text, text, text[], text, text, text[], boolean, text, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aitg_approve_payload_audited.sql
-- -----------------------------------------------------------------------------

-- Function: aitg_approve_payload_audited

CREATE OR REPLACE FUNCTION public.aitg_approve_payload_audited(p_proposal_id uuid, p_status text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_proposal public.aitg_payload_proposals;
  v_new_payload_id uuid;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'AITG_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  IF p_status NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'AITG_INVALID_STATUS' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_proposal FROM public.aitg_payload_proposals WHERE proposal_id = p_proposal_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'AITG_PROPOSAL_NOT_FOUND' USING ERRCODE = '02000';
  END IF;
  IF v_proposal.status <> 'pending' THEN
    RAISE EXCEPTION 'AITG_PROPOSAL_ALREADY_REVIEWED' USING ERRCODE = '22023';
  END IF;

  IF p_status = 'approved' THEN
    INSERT INTO public.aitg_payloads (test_id, payload, expected_block, tags, source, active)
    VALUES (v_proposal.test_id, v_proposal.payload, v_proposal.expected_block,
            v_proposal.tags, 'aisha-proposed', true)
    RETURNING payload_id INTO v_new_payload_id;
  END IF;

  UPDATE public.aitg_payload_proposals
  SET status = p_status,
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      promoted_payload_id = v_new_payload_id
  WHERE proposal_id = p_proposal_id;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (auth.uid(), 'aitg.payload_' || p_status, 'aitg.payload_' || p_status,
          'security', CASE p_status WHEN 'approved' THEN 'info' ELSE 'warn' END,
          ARRAY['aitg','corpus', v_proposal.test_id],
          jsonb_build_object('proposal_id', p_proposal_id, 'test_id', v_proposal.test_id,
                              'promoted_payload_id', v_new_payload_id));

  RETURN COALESCE(v_new_payload_id, p_proposal_id);
END;
$function$

;

REVOKE ALL ON FUNCTION aitg_approve_payload_audited(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION aitg_approve_payload_audited(uuid,text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aitg_update_automation_audited.sql
-- -----------------------------------------------------------------------------

-- Function: aitg_update_automation_audited

CREATE OR REPLACE FUNCTION public.aitg_update_automation_audited(p_automation_id text, p_mode text DEFAULT NULL::text, p_schedule_cron text DEFAULT NULL::text, p_schedule_interval_minutes integer DEFAULT NULL::integer, p_parameters jsonb DEFAULT NULL::jsonb)
 RETURNS aitg_automation_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.aitg_automation_settings;
  v_changed jsonb := '{}'::jsonb;
BEGIN
  -- Mutations are admin-only (no service_role fallback) — operators decide
  -- cadence, not Aisha. Aisha can REQUEST changes via a proposal mechanism
  -- (out of scope for this RPC).
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'AITG_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  IF p_mode IS NOT NULL AND p_mode NOT IN ('automated','manual','disabled') THEN
    RAISE EXCEPTION 'AITG_INVALID_MODE' USING ERRCODE = '22023';
  END IF;
  IF p_schedule_interval_minutes IS NOT NULL
     AND (p_schedule_interval_minutes < 1 OR p_schedule_interval_minutes > 1440) THEN
    RAISE EXCEPTION 'AITG_INVALID_INTERVAL' USING ERRCODE = '22023';
  END IF;

  UPDATE public.aitg_automation_settings
  SET
    mode = COALESCE(p_mode, mode),
    schedule_cron = COALESCE(p_schedule_cron, schedule_cron),
    schedule_interval_minutes = COALESCE(p_schedule_interval_minutes, schedule_interval_minutes),
    parameters = COALESCE(p_parameters, parameters),
    updated_at = now(),
    updated_by = auth.uid()
  WHERE automation_id = p_automation_id
  RETURNING * INTO v_row;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'AITG_AUTOMATION_NOT_FOUND' USING ERRCODE = '02000';
  END IF;

  IF p_mode IS NOT NULL                       THEN v_changed := v_changed || jsonb_build_object('mode', p_mode); END IF;
  IF p_schedule_cron IS NOT NULL              THEN v_changed := v_changed || jsonb_build_object('cron', p_schedule_cron); END IF;
  IF p_schedule_interval_minutes IS NOT NULL  THEN v_changed := v_changed || jsonb_build_object('interval_min', p_schedule_interval_minutes); END IF;
  IF p_parameters IS NOT NULL                 THEN v_changed := v_changed || jsonb_build_object('parameters_keys', (SELECT jsonb_agg(k) FROM jsonb_object_keys(p_parameters) k)); END IF;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (auth.uid(), 'aitg.automation_updated', 'aitg.automation_updated',
          'security', 'warn', ARRAY['aitg','automation','config', p_automation_id],
          jsonb_build_object('automation_id', p_automation_id, 'changes', v_changed));

  RETURN v_row;
END;
$function$

;

REVOKE ALL ON FUNCTION aitg_update_automation_audited(text,text,text,integer,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION aitg_update_automation_audited(text,text,text,integer,jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/allocate_batch_for_shipment.sql
-- -----------------------------------------------------------------------------

-- Function: public.allocate_batch_for_shipment
-- Arguments: p_shipment_id uuid, p_product_id uuid, p_quantity integer
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:25:51+01:00

CREATE OR REPLACE FUNCTION public.allocate_batch_for_shipment(p_shipment_id uuid, p_product_id uuid, p_quantity integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_allocated INTEGER := 0;
  v_batch RECORD;
  v_allocations JSONB := '[]'::jsonb;
  v_remaining INTEGER := p_quantity;
  v_alloc_qty INTEGER;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT is_admin_or_staff(v_user_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  FOR v_batch IN
    SELECT id, batch_number, available_units, expiry_date
    FROM production_batches
    WHERE product_id = p_product_id
      AND status = 'completed'
      AND available_units > 0
      AND (expiry_date IS NULL OR expiry_date > CURRENT_DATE)
    ORDER BY expiry_date NULLS LAST
  LOOP
    IF v_remaining <= 0 THEN
      EXIT;
    END IF;

    v_alloc_qty := LEAST(v_batch.available_units, v_remaining);

    UPDATE production_batches
    SET available_units = available_units - v_alloc_qty,
        updated_at = now()
    WHERE id = v_batch.id;

    v_allocated := v_allocated + v_alloc_qty;
    v_remaining := v_remaining - v_alloc_qty;

    v_allocations := v_allocations || jsonb_build_object(
      'batch_id', v_batch.id,
      'batch_number', v_batch.batch_number,
      'quantity', v_alloc_qty,
      'expiry_date', v_batch.expiry_date,
      'allocated_at', now()
    );
  END LOOP;

  INSERT INTO audit_journal (user_id, action_type, area, entity_type, entity_id, summary, severity)
  VALUES (v_user_id, 'create', 'admin', 'batch_allocation', p_shipment_id::text, 
          format('Allocated %s units for shipment', v_allocated), 'info');

  RETURN jsonb_build_object(
    'success', v_remaining = 0,
    'requested', p_quantity,
    'allocated', v_allocated,
    'remaining', v_remaining,
    'allocations', v_allocations
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.allocate_batch_for_shipment(p_shipment_id uuid, p_product_id uuid, p_quantity integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.allocate_batch_for_shipment(p_shipment_id uuid, p_product_id uuid, p_quantity integer) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/analyze_integration_performance.sql
-- -----------------------------------------------------------------------------

-- Function: public.analyze_integration_performance
-- Analyzes integration event performance over a rolling window.
-- Per-event_type metrics: count, avg_duration, p95, error_rate, retry_rate.
-- Per-installation metrics: total events, health score, trend.
-- Per-story metrics: webhook count, failure rate, delivery correlation.
-- Hourly time-series for trend visualization.
-- @security: admin/staff via is_admin_or_staff()

CREATE OR REPLACE FUNCTION public.analyze_integration_performance(
  p_hours_back integer DEFAULT 24,
  p_installation_id bigint DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_cutoff timestamptz := now() - (p_hours_back || ' hours')::interval;
  v_by_event_type jsonb;
  v_by_installation jsonb;
  v_by_story jsonb;
  v_hourly_trend jsonb;
  v_summary jsonb;
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  -- Per event_type metrics
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO v_by_event_type
  FROM (
    SELECT
      event_type,
      event_source,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'completed') AS completed,
      COUNT(*) FILTER (WHERE status IN ('failed', 'exhausted')) AS failed,
      ROUND(AVG(duration_ms) FILTER (WHERE duration_ms IS NOT NULL)) AS avg_duration_ms,
      ROUND(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY duration_ms)
        FILTER (WHERE duration_ms IS NOT NULL)) AS p95_duration_ms,
      ROUND(
        COUNT(*) FILTER (WHERE status IN ('failed', 'exhausted'))::numeric /
        NULLIF(COUNT(*), 0) * 100, 1
      ) AS error_rate_pct,
      ROUND(
        COUNT(*) FILTER (WHERE attempt > 1)::numeric /
        NULLIF(COUNT(*), 0) * 100, 1
      ) AS retry_rate_pct
    FROM integration_events
    WHERE created_at > v_cutoff
      AND (p_installation_id IS NULL OR installation_id = p_installation_id)
    GROUP BY event_type, event_source
    ORDER BY total DESC
    LIMIT 20
  ) t;

  -- Per installation metrics
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO v_by_installation
  FROM (
    SELECT
      ie.installation_id,
      gai.account_login,
      COUNT(*) AS total_events,
      COUNT(*) FILTER (WHERE ie.status = 'completed') AS completed,
      COUNT(*) FILTER (WHERE ie.status IN ('failed', 'exhausted')) AS failed,
      ROUND(AVG(ie.duration_ms) FILTER (WHERE ie.duration_ms IS NOT NULL)) AS avg_duration_ms,
      ROUND(
        COUNT(*) FILTER (WHERE ie.status = 'completed')::numeric /
        NULLIF(COUNT(*), 0) * 100, 1
      ) AS health_score
    FROM integration_events ie
    LEFT JOIN github_app_installations gai ON gai.installation_id = ie.installation_id
    WHERE ie.created_at > v_cutoff
      AND ie.installation_id IS NOT NULL
      AND (p_installation_id IS NULL OR ie.installation_id = p_installation_id)
    GROUP BY ie.installation_id, gai.account_login
    ORDER BY total_events DESC
    LIMIT 10
  ) t;

  -- Per story metrics
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO v_by_story
  FROM (
    SELECT
      story_id,
      COUNT(*) AS total_events,
      COUNT(*) FILTER (WHERE status = 'completed') AS completed,
      COUNT(*) FILTER (WHERE status IN ('failed', 'exhausted')) AS failed,
      COUNT(*) FILTER (WHERE event_source = 'deployment') AS deploy_events,
      ROUND(AVG(duration_ms) FILTER (WHERE duration_ms IS NOT NULL)) AS avg_duration_ms
    FROM integration_events
    WHERE created_at > v_cutoff
      AND story_id IS NOT NULL
      AND (p_installation_id IS NULL OR installation_id = p_installation_id)
    GROUP BY story_id
    ORDER BY total_events DESC
    LIMIT 10
  ) t;

  -- Hourly time-series
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.hour), '[]'::jsonb)
  INTO v_hourly_trend
  FROM (
    SELECT
      date_trunc('hour', created_at) AS hour,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'completed') AS completed,
      COUNT(*) FILTER (WHERE status IN ('failed', 'exhausted')) AS failed,
      ROUND(AVG(duration_ms) FILTER (WHERE duration_ms IS NOT NULL)) AS avg_duration_ms
    FROM integration_events
    WHERE created_at > v_cutoff
      AND (p_installation_id IS NULL OR installation_id = p_installation_id)
    GROUP BY date_trunc('hour', created_at)
    ORDER BY hour
  ) t;

  -- Summary
  SELECT jsonb_build_object(
    'period_hours', p_hours_back,
    'total_events', COUNT(*),
    'completed', COUNT(*) FILTER (WHERE status = 'completed'),
    'failed', COUNT(*) FILTER (WHERE status IN ('failed', 'exhausted')),
    'exhausted', COUNT(*) FILTER (WHERE status = 'exhausted'),
    'avg_duration_ms', ROUND(AVG(duration_ms) FILTER (WHERE duration_ms IS NOT NULL)),
    'error_rate_pct', ROUND(
      COUNT(*) FILTER (WHERE status IN ('failed', 'exhausted'))::numeric /
      NULLIF(COUNT(*), 0) * 100, 1
    )
  )
  INTO v_summary
  FROM integration_events
  WHERE created_at > v_cutoff
    AND (p_installation_id IS NULL OR installation_id = p_installation_id);

  RETURN jsonb_build_object(
    'summary', v_summary,
    'by_event_type', v_by_event_type,
    'by_installation', v_by_installation,
    'by_story', v_by_story,
    'hourly_trend', v_hourly_trend
  );
END;
$$;

REVOKE ALL ON FUNCTION public.analyze_integration_performance(integer, bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.analyze_integration_performance(integer, bigint) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/approve_claude_run.sql
-- -----------------------------------------------------------------------------

-- Function: public.approve_claude_run
-- Description: Mission Control approval for a HELD claude_cli_task — one whose
--   fn_admit_clow verdict was 'ask' (approval_required=true, approved_at IS NULL).
--   Setting approved_at clears the hold so claim_queued_claude_run drains it. The
--   approver-side twin of fn_spawn_claude_cli_run's ask branch. Mirrors
--   approve_playwright_run: admin/staff + segregation of duties + audit.
-- Security: SECURITY INVOKER (admin check + approver identity from the caller).

CREATE OR REPLACE FUNCTION public.approve_claude_run(p_run_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_run record;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin/staff required to approve a claude_cli_task';
  END IF;

  SELECT id, kind, status, approval_required, approved_at, requested_by, inputs
  INTO v_run
  FROM public.agent_runs
  WHERE id = p_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'agent_run not found: %', p_run_id;
  END IF;
  IF v_run.kind <> 'claude_cli_task' THEN
    RAISE EXCEPTION 'agent_run % is not a claude_cli_task (kind=%)', p_run_id, v_run.kind;
  END IF;
  IF NOT v_run.approval_required THEN
    RAISE EXCEPTION 'agent_run % does not require approval', p_run_id;
  END IF;
  IF v_run.approved_at IS NOT NULL THEN
    RAISE EXCEPTION 'agent_run % already approved at %', p_run_id, v_run.approved_at;
  END IF;
  -- Only a still-held (queued) run can be approved; a run that already ran/failed
  -- cannot be retro-approved.
  IF v_run.status <> 'queued' THEN
    RAISE EXCEPTION 'agent_run % not in a holdable state (status=%)', p_run_id, v_run.status;
  END IF;

  -- Segregation of duties: the requester cannot self-approve their own held run
  -- (mirrors approve_playwright_run).
  IF v_run.requested_by IS NOT NULL AND v_run.requested_by = auth.uid() THEN
    RAISE EXCEPTION 'Segregation of duties: approver must differ from the requester';
  END IF;

  UPDATE public.agent_runs
  SET approved_by = auth.uid(),
      approved_at = now()
  WHERE id = p_run_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'agent_run.approved',
    jsonb_build_object(
      'run_id', p_run_id,
      'kind', 'claude_cli_task',
      'story_id', NULLIF(v_run.inputs->>'story_id', '')::uuid
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION public.approve_claude_run(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.approve_claude_run(uuid) TO authenticated;

COMMENT ON FUNCTION public.approve_claude_run(uuid) IS
  'Mission Control approval for a HELD claude_cli_task (fn_admit_clow ask verdict). Admin/staff only + segregation of duties (approver <> requester); sets approved_at so claim_queued_claude_run drains it. Mirrors approve_playwright_run.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/approve_improvement_proposal_admin.sql
-- -----------------------------------------------------------------------------

-- Function: approve_improvement_proposal_admin
-- Schválení návrhu zlepšení; s p_auto_apply ho i aplikuje na agent_catalog.
-- Snapshot původního stavu jde do current_value (podklad pro rollback).
--
-- Oprava 2026-09-28 (SELF_IMPROVEMENT_LOOP.md §3, K-05) — naměřeno na main 9087ef3df:
--   `fn_create_improvement_proposal` proposal_type NIKDY nenastaví (je NULL) a proposed_value
--   nevyplní. Auto-apply pak prošel `CASE … ELSE NULL` a PŘESTO zapsal status 'applied'
--   a vrátil 'applied' — „aplikováno" bez jediné změny; outcome review a rollback pak
--   měřily a vracely změnu, která nikdy nenastala. Stejně lhal výsledek, když agent
--   neexistoval nebo proposed_value nic neměnil.
-- Teď: 'applied' jen tehdy, když se agent_catalog SKUTEČNĚ změnil. Jinak zůstane
-- 'approved' (schválení platí) a výsledek řekne proč se neaplikovalo (fail-closed):
--   agent_not_found · type_not_auto_appliable · no_effective_change.
-- Funkce nebyla v heals — běžící DB držela verzi z cold startu.

CREATE OR REPLACE FUNCTION public.approve_improvement_proposal_admin(
  p_auto_apply boolean DEFAULT false,
  p_proposal_id uuid DEFAULT NULL,
  p_review_note text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_agent        record;
  v_proposal     record;
  v_new_model    text;
  v_new_overrides jsonb;
  v_new_allowed  text[];
  v_new_denied   text[];
  v_applied      boolean := false;
  v_reason       text := NULL;
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = 'P0003';
  END IF;

  IF p_proposal_id IS NULL THEN
    RAISE EXCEPTION 'proposal_id is required' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_proposal
  FROM improvement_proposals
  WHERE id = p_proposal_id AND status IN ('pending', 'pending_review', 'auto_approved')
  FOR UPDATE;

  IF v_proposal IS NULL THEN
    RAISE EXCEPTION 'Proposal not found or not in reviewable status' USING ERRCODE = 'P0002';
  END IF;

  UPDATE improvement_proposals
  SET reviewed_at = now(),
      reviewed_by = auth.uid(),
      review_note = p_review_note,
      status = 'approved'
  WHERE id = p_proposal_id;

  IF p_auto_apply THEN
    IF v_proposal.agent_slug IS NOT NULL THEN
      SELECT * INTO v_agent
      FROM agent_catalog
      WHERE slug = v_proposal.agent_slug
      FOR UPDATE;
    END IF;

    IF v_agent IS NULL THEN
      v_reason := 'agent_not_found';
    ELSIF v_proposal.proposal_type IS DISTINCT FROM 'model_change'
      AND v_proposal.proposal_type IS DISTINCT FROM 'tool_config_change' THEN
      -- Neznámý i chybějící typ = nic se neaplikuje (fail-closed). Schválení platí.
      v_reason := 'type_not_auto_appliable';
    ELSE
      -- Cílový stav z proposed_value; co návrh neuvádí, zůstává.
      v_new_model := v_agent.default_model;
      v_new_overrides := v_agent.model_overrides;
      v_new_allowed := v_agent.allowed_tools;
      v_new_denied := v_agent.denied_tools;

      IF v_proposal.proposal_type = 'model_change' THEN
        v_new_model := COALESCE(v_proposal.proposed_value->>'default_model', v_agent.default_model);
        IF v_proposal.proposed_value ? 'model_overrides' THEN
          v_new_overrides := v_proposal.proposed_value->'model_overrides';
        END IF;
      ELSE
        IF v_proposal.proposed_value ? 'allowed_tools' THEN
          v_new_allowed := ARRAY(SELECT jsonb_array_elements_text(v_proposal.proposed_value->'allowed_tools'));
        END IF;
        IF v_proposal.proposed_value ? 'denied_tools' THEN
          v_new_denied := ARRAY(SELECT jsonb_array_elements_text(v_proposal.proposed_value->'denied_tools'));
        END IF;
      END IF;

      IF v_new_model IS NOT DISTINCT FROM v_agent.default_model
        AND v_new_overrides IS NOT DISTINCT FROM v_agent.model_overrides
        AND v_new_allowed IS NOT DISTINCT FROM v_agent.allowed_tools
        AND v_new_denied IS NOT DISTINCT FROM v_agent.denied_tools THEN
        v_reason := 'no_effective_change';
      ELSE
        UPDATE improvement_proposals
        SET current_value = jsonb_build_object(
          'allowed_tools', to_jsonb(v_agent.allowed_tools),
          'default_model', v_agent.default_model,
          'denied_tools', to_jsonb(v_agent.denied_tools),
          'model_overrides', v_agent.model_overrides
        )
        WHERE id = p_proposal_id;

        UPDATE agent_catalog
        SET default_model = v_new_model,
            model_overrides = v_new_overrides,
            allowed_tools = v_new_allowed,
            denied_tools = v_new_denied,
            updated_at = now()
        WHERE slug = v_proposal.agent_slug;

        UPDATE improvement_proposals
        SET applied_at = now(), status = 'applied'
        WHERE id = p_proposal_id;

        v_applied := true;
      END IF;
    END IF;
  END IF;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'IMPROVEMENT_PROPOSAL_APPROVED', jsonb_build_object(
    'agent_slug', v_proposal.agent_slug,
    'auto_apply_requested', p_auto_apply,
    'auto_applied', v_applied,
    'not_applied_reason', v_reason,
    'proposal_id', p_proposal_id,
    'proposal_type', v_proposal.proposal_type
  ));

  RETURN jsonb_build_object(
    'auto_applied', v_applied,
    'not_applied_reason', v_reason,
    'proposal_id', p_proposal_id,
    'status', CASE WHEN v_applied THEN 'applied' ELSE 'approved' END
  );
END;
$$;

COMMENT ON FUNCTION public.approve_improvement_proposal_admin(boolean, uuid, text) IS
  'Schválí návrh zlepšení; s p_auto_apply ho aplikuje na agent_catalog. Status applied jen při '
  'skutečné změně, jinak approved + not_applied_reason (agent_not_found | type_not_auto_appliable | '
  'no_effective_change). Snapshot původního stavu v current_value.';

REVOKE ALL ON FUNCTION public.approve_improvement_proposal_admin(boolean, uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.approve_improvement_proposal_admin(boolean, uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.approve_improvement_proposal_admin(boolean, uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/approve_model_admin.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.approve_model_admin(
  p_model_registry_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_model_id text;
  v_provider text;
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Admin or staff role required';
  END IF;

  -- Get model info + verify exists
  SELECT model_id, provider INTO v_model_id, v_provider
  FROM ai_model_registry
  WHERE id = p_model_registry_id;

  IF v_model_id IS NULL THEN
    RAISE EXCEPTION 'Model not found: %', p_model_registry_id;
  END IF;

  -- Update eval_status
  UPDATE ai_model_registry
  SET eval_status = 'approved',
      updated_at = now()
  WHERE id = p_model_registry_id;

  -- Audit trail
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'MODEL_APPROVED',
    jsonb_build_object(
      'area', 'ai',
      'severity', 'info',
      'entity_type', 'ai_model_registry',
      'entity_id', p_model_registry_id::text,
      'model_id', v_model_id,
      'provider', v_provider
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'model_id', v_model_id,
    'provider', v_provider,
    'eval_status', 'approved'
  );
END;
$$;

REVOKE ALL ON FUNCTION approve_model_admin(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION approve_model_admin(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/approve_playwright_run.sql
-- -----------------------------------------------------------------------------

-- approve_playwright_run
-- Admin approval for production_manual runs. Unblocks the runner.
--
-- Production integration (migration 20260518040000):
--  • Segregation of duties — approver MUST differ from requester (auth.uid()).
--  • Story-linked runs emit qa_playwright_approved entry into the storyloop timeline.

CREATE OR REPLACE FUNCTION public.approve_playwright_run(p_run_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_run record;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin/staff required';
  END IF;

  SELECT id, status, approval_required, approved_at, trigger_kind, target_env, story_id, requested_by
  INTO v_run
  FROM public.playwright_runs
  WHERE id = p_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Playwright run not found: %', p_run_id;
  END IF;

  IF NOT v_run.approval_required THEN
    RAISE EXCEPTION 'Run does not require approval (trigger=%)', v_run.trigger_kind;
  END IF;

  IF v_run.approved_at IS NOT NULL THEN
    RAISE EXCEPTION 'Run already approved at %', v_run.approved_at;
  END IF;

  IF v_run.status <> 'queued' THEN
    RAISE EXCEPTION 'Run not in queued state (got %)', v_run.status;
  END IF;

  -- Segregation of duties: requester cannot self-approve a production_manual run.
  IF v_run.requested_by IS NOT NULL AND v_run.requested_by = auth.uid() THEN
    RAISE EXCEPTION 'Segregation of duties: approver must differ from requester';
  END IF;

  UPDATE public.playwright_runs
  SET approved_by = auth.uid(),
      approved_at = now()
  WHERE id = p_run_id;

  IF v_run.story_id IS NOT NULL THEN
    INSERT INTO public.story_entries (story_id, entry_type, content, metadata, created_by)
    VALUES (
      v_run.story_id,
      'qa_playwright_approved',
      NULL,
      jsonb_build_object(
        'type', 'qa_playwright_approved',
        'run_id', p_run_id,
        'target_env', v_run.target_env
      ),
      auth.uid()
    );
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'PLAYWRIGHT_RUN_APPROVE',
    jsonb_build_object(
      'area', 'qa',
      'severity', 'info',
      'entity_type', 'playwright_run',
      'entity_id', p_run_id::text,
      'target_env', v_run.target_env,
      'story_id', v_run.story_id,
      'tags', ARRAY['stack', 'qa', 'playwright', 'approval']
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION public.approve_playwright_run(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.approve_playwright_run(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/approve_story_promotion.sql
-- -----------------------------------------------------------------------------

-- Function: public.approve_story_promotion
-- Arguments: p_operation_id uuid
-- Description: Approves a pending promote operation and materializes its payload
--              into the origin story. v1 materializes knowledge_items: matched by
--              (story_id, slug → source_slug); existing items are updated only
--              when the incoming version is higher, new items are inserted
--              (locale from item metadata, default 'global'; source_type
--              'story_promotion'). Embeddings are
--              rebuilt by trg_knowledge_embedding_auto — never synced.
--              Marks the operation success + committed_at and records approver
--              and materialization counts in operation metadata.
-- Security: SECURITY DEFINER — admin/staff only (auth.uid() required)

CREATE OR REPLACE FUNCTION public.approve_story_promotion(p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_operation record;
  v_items jsonb;
  v_item jsonb;
  v_slug text;
  v_title text;
  v_content text;
  v_summary text;
  v_ai_instructions text;
  v_locale text;
  v_version integer;
  v_item_type knowledge_item_type;
  v_tags text[];
  v_existing record;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_skipped integer := 0;
  v_materialized integer := 0;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff role required' USING ERRCODE = '22023';
  END IF;

  SELECT sso.id, sso.story_id, sso.operation_type, sso.outcome,
         sso.source_instance_id, sso.target_instance_id, sso.metadata
  INTO v_operation
  FROM story_sync_operations sso
  WHERE sso.id = p_operation_id
  FOR UPDATE;

  IF v_operation.id IS NULL THEN
    RAISE EXCEPTION 'Sync operation not found: %', p_operation_id USING ERRCODE = '22023';
  END IF;

  IF v_operation.operation_type != 'promote' THEN
    RAISE EXCEPTION 'Operation % is not a promote operation (type: %)',
      p_operation_id, v_operation.operation_type USING ERRCODE = '22023';
  END IF;

  IF v_operation.outcome != 'pending' THEN
    RAISE EXCEPTION 'Operation % is not pending (outcome: %)',
      p_operation_id, v_operation.outcome USING ERRCODE = '22023';
  END IF;

  -- ===== MATERIALIZE KNOWLEDGE ITEMS =====
  v_items := COALESCE(v_operation.metadata->'payload'->'knowledge_items', '[]'::jsonb);

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) AS value
  LOOP
    -- Manifest carries 'slug'/'content'/'tags'/'verified'; tolerate the raw
    -- column names as well (source_slug/body_markdown/ai_context_tags/is_verified).
    -- Export bundles may nest secondary fields under item 'metadata' — read
    -- top-level first, then fall back to metadata.
    v_slug := COALESCE(v_item->>'slug', v_item->>'source_slug');
    v_title := v_item->>'title';
    v_content := COALESCE(v_item->>'content', v_item->>'body_markdown');
    v_summary := COALESCE(v_item->>'summary', v_item->'metadata'->>'summary');
    v_ai_instructions := COALESCE(v_item->>'ai_instructions', v_item->'metadata'->>'ai_instructions');
    v_locale := COALESCE(v_item->'metadata'->>'locale', 'global');
    v_version := COALESCE(NULLIF(v_item->>'version', '')::integer, 1);

    -- NOT NULL columns of knowledge_items: skip items that cannot satisfy them
    IF v_slug IS NULL OR v_title IS NULL OR v_content IS NULL THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    -- Tags may be absent or JSON null — only unpack a real array
    v_tags := CASE
      WHEN jsonb_typeof(v_item->'tags') = 'array'
        THEN ARRAY(SELECT jsonb_array_elements_text(v_item->'tags'))
      WHEN jsonb_typeof(v_item->'ai_context_tags') = 'array'
        THEN ARRAY(SELECT jsonb_array_elements_text(v_item->'ai_context_tags'))
      ELSE '{}'::text[]
    END;

    SELECT ki.id, ki.version INTO v_existing
    FROM knowledge_items ki
    WHERE ki.story_id = v_operation.story_id
      AND ki.source_slug = v_slug
    ORDER BY ki.version DESC
    LIMIT 1;

    IF v_existing.id IS NOT NULL THEN
      -- Same rule as import: update only when the incoming version is higher
      IF v_version > v_existing.version THEN
        UPDATE knowledge_items SET
          title = v_title,
          summary = v_summary,
          body_markdown = v_content,
          ai_instructions = v_ai_instructions,
          ai_context_tags = v_tags,
          category = COALESCE(v_item->>'category', category),
          version = v_version,
          is_verified = COALESCE(
            (v_item->>'verified')::boolean,
            (v_item->>'is_verified')::boolean,
            is_verified
          ),
          updated_at = now()
        WHERE id = v_existing.id;
        v_updated := v_updated + 1;
      ELSE
        v_skipped := v_skipped + 1;
      END IF;
    ELSE
      -- idx_knowledge_items_source_slug_locale_unique is GLOBAL on
      -- (source_slug, locale) — a slug already used by another story cannot
      -- be inserted; skip instead of aborting the whole approval
      IF EXISTS (
        SELECT 1 FROM knowledge_items ki
        WHERE ki.source_slug = v_slug AND ki.locale = v_locale
      ) THEN
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;

      -- item_type is NOT NULL without default; fall back to 'domain_doc' for
      -- unknown/missing values
      BEGIN
        v_item_type := COALESCE(
          NULLIF(v_item->>'item_type', ''),
          NULLIF(v_item->'metadata'->>'item_type', ''),
          'domain_doc'
        )::knowledge_item_type;
      EXCEPTION WHEN invalid_text_representation THEN
        v_item_type := 'domain_doc'::knowledge_item_type;
      END;

      INSERT INTO knowledge_items (
        item_type, source_type, source_slug, locale,
        title, summary, body_markdown, ai_instructions,
        ai_context_tags, category, status, visibility,
        version, is_verified, story_id
      ) VALUES (
        v_item_type, 'story_promotion', v_slug, v_locale,
        v_title, v_summary, v_content, v_ai_instructions,
        v_tags, v_item->>'category',
        COALESCE(v_item->>'status', 'active'),
        COALESCE(v_item->>'visibility', 'public'),
        v_version,
        COALESCE(
          (v_item->>'verified')::boolean,
          (v_item->>'is_verified')::boolean,
          false
        ),
        v_operation.story_id
      );
      v_inserted := v_inserted + 1;
    END IF;
  END LOOP;

  v_materialized := v_inserted + v_updated;

  -- ===== MARK OPERATION APPROVED =====
  UPDATE story_sync_operations SET
    outcome = 'success',
    committed_at = now(),
    metadata = metadata || jsonb_build_object(
      'approved_by', v_user_id,
      'approved_at', now(),
      'materialized', jsonb_build_object(
        'knowledge_items_inserted', v_inserted,
        'knowledge_items_updated', v_updated,
        'knowledge_items_skipped', v_skipped
      )
    )
  WHERE id = p_operation_id;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (v_user_id, 'STORY_PROMOTE_APPROVED', jsonb_build_object(
    'area', 'story_sync',
    'severity', 'info',
    'entity_type', 'story_sync_operation',
    'entity_id', p_operation_id,
    'story_id', v_operation.story_id,
    'source_instance_id', v_operation.source_instance_id,
    'target_instance_id', v_operation.target_instance_id,
    'knowledge_items_inserted', v_inserted,
    'knowledge_items_updated', v_updated,
    'knowledge_items_skipped', v_skipped
  ));

  RETURN jsonb_build_object(
    'status', 'success',
    'materialized_knowledge_items', v_materialized,
    'operation_id', p_operation_id,
    'inserted', v_inserted,
    'updated', v_updated,
    'skipped', v_skipped,
    'note', 'Embeddings are rebuilt locally by trigger — never synced.'
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.approve_story_promotion(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.approve_story_promotion(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/approve_task_spend_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: approve_task_spend_audited
-- Purpose: Human approval of a spend-blocked run ('ask' decision outcome).
--          Unblocks the ai_runs row (status blocked → pending so the runner
--          admission re-picks it), optionally raises the story lifetime
--          budget cap in the same action, records the decision in run
--          metadata + audit_journal, and nudges the story's agent channel.
-- Security: SECURITY DEFINER + is_admin_or_staff() guard + audit.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.approve_task_spend_audited(
  p_run_id           uuid,
  p_raise_budget numeric DEFAULT NULL,
  p_note             text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_run     public.ai_runs%ROWTYPE;
  v_new_cap numeric;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff required' USING ERRCODE = '42501';
  END IF;

  -- JIT-provision the admin actor so the audit_journal insert below can't
  -- FK-violate (23503) for a Keycloak admin created after bootstrap import.
  PERFORM public.ensure_current_user();

  SELECT * INTO v_run FROM public.ai_runs WHERE id = p_run_id FOR UPDATE;
  IF v_run.id IS NULL THEN
    RAISE EXCEPTION 'approve_task_spend_audited: run % not found', p_run_id
      USING ERRCODE = 'P0002';
  END IF;
  IF v_run.status <> 'blocked'
     OR COALESCE(v_run.metadata->>'awaiting', '') <> 'spend_approval' THEN
    RAISE EXCEPTION 'approve_task_spend_audited: run % is not awaiting spend approval', p_run_id
      USING ERRCODE = '22023';
  END IF;

  -- Optional budget raise: bump the story lifetime USD cap so the post-paid
  -- meter (fn_check_and_consume_ai_budget_audited) won't re-block mid-run.
  IF p_raise_budget IS NOT NULL AND v_run.story_id IS NOT NULL THEN
    IF p_raise_budget <= 0 THEN
      RAISE EXCEPTION 'p_raise_budget must be > 0' USING ERRCODE = '22023';
    END IF;
    UPDATE public.ai_budget
    SET cost_limit = COALESCE(cost_limit, 0) + p_raise_budget,
        updated_at = now()
    WHERE scope_type = 'story' AND scope_id = v_run.story_id AND period = 'lifetime'
    RETURNING cost_limit INTO v_new_cap;
    -- No lifetime budget row yet → nothing to raise; the approval itself
    -- still unblocks the run (caps stay unconfigured = uncapped).
  END IF;

  UPDATE public.ai_runs
  SET status = 'pending',
      metadata = (metadata - 'awaiting') || jsonb_build_object(
        'spend_approval', jsonb_strip_nulls(jsonb_build_object(
          'decision', 'approved',
          'by', auth.uid(),
          'at', now(),
          'raised_budget', p_raise_budget,
          'note', p_note
        ))
      )
  WHERE id = p_run_id;

  -- Agent notification on the story channel (drained on next Stop event).
  IF v_run.story_id IS NOT NULL THEN
    INSERT INTO public.dirigent_nudges
      (story_id, event_origin, severity, message, metadata, expires_at)
    VALUES (
      v_run.story_id,
      'manual',
      'info',
      format('✅ Spend approved for run %s (kind %s)%s — task may proceed.',
             p_run_id, v_run.kind,
             CASE WHEN p_raise_budget IS NOT NULL
                  THEN format(', budget raised by $%s', p_raise_budget)
                  ELSE '' END),
      jsonb_build_object('run_id', p_run_id, 'kind', v_run.kind),
      now() + interval '4 hours'
    );
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'ai.spend.approved',
    jsonb_strip_nulls(jsonb_build_object(
      'run_id', p_run_id,
      'kind', v_run.kind,
      'story_id', v_run.story_id,
      'raised_budget', p_raise_budget,
      'new_lifetime_cap', v_new_cap,
      'note', p_note
    ))
  );

  RETURN jsonb_build_object(
    'success', true,
    'run_id', p_run_id,
    'status', 'pending',
    'new_lifetime_cap', v_new_cap
  );
END;
$$;

REVOKE ALL ON FUNCTION public.approve_task_spend_audited(uuid, numeric, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.approve_task_spend_audited(uuid, numeric, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.approve_task_spend_audited(uuid, numeric, text) TO service_role;

COMMENT ON FUNCTION public.approve_task_spend_audited(uuid, numeric, text) IS
  'Approve a spend-blocked run: status blocked→pending, optional story lifetime budget raise, dirigent nudge + audit. Admin/staff only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/assess_code_quality.sql
-- -----------------------------------------------------------------------------

-- Function: assess_code_quality

CREATE OR REPLACE FUNCTION public.assess_code_quality(p_session_id uuid, p_file_paths text[], p_check_types text[] DEFAULT ARRAY['consistency'::text, 'rpc_only'::text, 'i18n'::text, 'no_any'::text, 'no_console'::text])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_session RECORD;
  v_findings jsonb := '[]'::jsonb;
  v_refactor_candidates jsonb := '[]'::jsonb;
  v_quality_rules jsonb;
  v_decision_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  -- Verify session ownership
  SELECT * INTO v_session
  FROM moderation_sessions ms
  WHERE ms.id = p_session_id AND (ms.user_id = v_user_id OR is_admin_or_staff());

  IF v_session IS NULL THEN
    RAISE EXCEPTION 'Session not found or access denied' USING ERRCODE = 'P0002';
  END IF;

  -- Load quality + compliance rules
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'slug', er.slug,
      'title', er.title,
      'category', er.category,
      'ai_instructions', er.ai_instructions
    )
  ), '[]'::jsonb)
  INTO v_quality_rules
  FROM expert_rules er
  WHERE er.status = 'published'
    AND er.category IN ('quality', 'compliance', 'security', 'patterns')
  LIMIT 25;

  -- Build check-type-specific findings structure
  -- (AI agent will populate actual findings via follow-up code analysis)
  IF 'rpc_only' = ANY(p_check_types) THEN
    v_findings := v_findings || jsonb_build_array(
      jsonb_build_object(
        'check', 'rpc_only',
        'description', 'Verify no direct .from() queries on sensitive tables',
        'status', 'pending'
      )
    );
  END IF;

  IF 'i18n' = ANY(p_check_types) THEN
    v_findings := v_findings || jsonb_build_array(
      jsonb_build_object(
        'check', 'i18n',
        'description', 'No hardcoded strings in JSX, no defaultValue fallbacks',
        'status', 'pending'
      )
    );
  END IF;

  IF 'no_any' = ANY(p_check_types) THEN
    v_findings := v_findings || jsonb_build_array(
      jsonb_build_object(
        'check', 'no_any',
        'description', 'No any types — use proper types or unknown + type guard',
        'status', 'pending'
      )
    );
  END IF;

  IF 'no_console' = ANY(p_check_types) THEN
    v_findings := v_findings || jsonb_build_array(
      jsonb_build_object(
        'check', 'no_console',
        'description', 'No console.log() — use safeError() for error logging',
        'status', 'pending'
      )
    );
  END IF;

  IF 'consistency' = ANY(p_check_types) THEN
    v_findings := v_findings || jsonb_build_array(
      jsonb_build_object(
        'check', 'consistency',
        'description', 'Naming conventions, file structure, export patterns',
        'status', 'pending'
      )
    );
  END IF;

  -- Record decision
  INSERT INTO moderation_decisions (session_id, decision_type, severity, context, recommendation, evidence)
  VALUES (
    p_session_id, 'quality_issue', 'info',
    jsonb_build_object('file_paths', to_jsonb(p_file_paths), 'check_types', to_jsonb(p_check_types)),
    'Code quality assessment for ' || array_length(p_file_paths, 1) || ' file(s)',
    jsonb_build_object('rules', v_quality_rules)
  )
  RETURNING id INTO v_decision_id;

  RETURN jsonb_build_object(
    'decision_id', v_decision_id,
    'findings', v_findings,
    'refactor_candidates', v_refactor_candidates,
    'consistency_score', NULL,
    'quality_rules', v_quality_rules,
    'check_types_applied', p_check_types
  );
END;
$function$;

REVOKE ALL ON FUNCTION assess_code_quality(uuid, text[], text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION assess_code_quality(uuid,text[],text[]) TO authenticated;
GRANT EXECUTE ON FUNCTION assess_code_quality(uuid,text[],text[]) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_admin_approve_source.sql
-- -----------------------------------------------------------------------------

-- Function: public.audience_admin_approve_source
-- Description: Operator approval for a federated source, over the story spine.
--   Replaces the #572 bare is_active toggle with a real source-onboarding
--   activation: it REFUSES to approve a source whose 4-dimension classification
--   (source_type / data_sensitivity / retention_class / legal_basis) + namespace
--   is incomplete (contract §1), then transitions the ONE lifecycle on the story
--   instance (metadata.source_approved + status) and audits into the integrations
--   sink with the contract action (§7 krok5), not the crm_ops area #572 mis-filed.
--   The approved flag is exactly what audience_resolve_source_binding gates the
--   live read on — closing the approve↔read decoupling #572 shipped.
--
-- Security: SECURITY DEFINER, search_path pinned. OPERATOR (admin/staff) ONLY — a
--   trusted service must NOT self-approve (contract §7: restricted/confidential
--   require a human/Dirigent gate). `audience_` prefix inherits the module gates.

CREATE OR REPLACE FUNCTION public.audience_admin_approve_source(
  p_instance_id      uuid,
  p_data_sensitivity text DEFAULT NULL
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $$
DECLARE
  v_instance    public.story_instances%ROWTYPE;
  v_meta        jsonb;
  v_sensitivity text;
  v_missing     text[] := '{}';
BEGIN
  -- Operator-only. is_admin_or_staff() is the human gate; a bare service_role JWT
  -- does not satisfy it, so a service cannot self-approve.
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied — source approval requires admin/staff' USING ERRCODE = '42501';
  END IF;

  SELECT si.* INTO v_instance
  FROM public.story_instances si
  WHERE si.id = p_instance_id
  FOR UPDATE;

  IF v_instance.id IS NULL THEN
    RAISE EXCEPTION 'Unknown source instance %', p_instance_id USING ERRCODE = 'no_data_found';
  END IF;

  v_meta        := COALESCE(v_instance.metadata, '{}'::jsonb);
  v_sensitivity := COALESCE(p_data_sensitivity, v_meta ->> 'data_sensitivity');

  -- Contract-completeness gate (§1): classify BEFORE activation. Fail LOUD.
  -- array_append (not `|| 'literal'`): an untyped literal RHS makes `||` bind to
  -- the anyarray||anyarray overload, which parses the string AS an array literal
  -- (22P02 malformed array literal). array_append forces element concatenation.
  IF v_meta ->> 'source_type'     IS NULL THEN v_missing := array_append(v_missing, 'source_type');     END IF;
  IF v_sensitivity                IS NULL THEN v_missing := array_append(v_missing, 'data_sensitivity'); END IF;
  IF v_meta ->> 'retention_class' IS NULL THEN v_missing := array_append(v_missing, 'retention_class'); END IF;
  IF v_meta ->> 'legal_basis'     IS NULL THEN v_missing := array_append(v_missing, 'legal_basis');     END IF;
  IF v_meta ->> 'namespace'       IS NULL THEN v_missing := array_append(v_missing, 'namespace');       END IF;
  IF array_length(v_missing, 1) IS NOT NULL THEN
    RAISE EXCEPTION 'Source classification incomplete — missing: %', array_to_string(v_missing, ', ')
      USING ERRCODE = 'check_violation';
  END IF;

  -- Contract §1: each classification dimension must carry a VALUE from its closed
  -- legal set (D2 remediation) — presence is not enough. A source whose metadata
  -- says data_sensitivity:'banana' is unclassified-with-a-typo, not governed. The
  -- onboarding gate is the ONE place this is checked, so it enforces set-membership
  -- (not just NOT NULL) over each of the four dimensions. Fail LOUD (check_violation).
  IF (v_meta ->> 'source_type') NOT IN ('internal', 'partner', 'external', 'user_provided') THEN
    RAISE EXCEPTION 'Invalid source_type "%": allowed = internal|partner|external|user_provided', v_meta ->> 'source_type'
      USING ERRCODE = 'check_violation';
  END IF;
  IF COALESCE(p_data_sensitivity, v_meta ->> 'data_sensitivity') NOT IN ('public', 'internal', 'restricted', 'confidential') THEN
    RAISE EXCEPTION 'Invalid data_sensitivity "%": allowed = public|internal|restricted|confidential', v_sensitivity
      USING ERRCODE = 'check_violation';
  END IF;
  IF (v_meta ->> 'retention_class') NOT IN ('ephemeral', 'short_term', 'long_term', 'permanent') THEN
    RAISE EXCEPTION 'Invalid retention_class "%": allowed = ephemeral|short_term|long_term|permanent', v_meta ->> 'retention_class'
      USING ERRCODE = 'check_violation';
  END IF;
  IF (v_meta ->> 'legal_basis') NOT IN ('consent', 'contract', 'legitimate_interest', 'legal_obligation') THEN
    RAISE EXCEPTION 'Invalid legal_basis "%": allowed = consent|contract|legitimate_interest|legal_obligation', v_meta ->> 'legal_basis'
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.story_instances
     SET metadata = v_meta || jsonb_build_object(
           'source_approved', true,
           'data_sensitivity', v_sensitivity,
           'approved_at', now(),
           'approved_by', auth.uid()
         ),
         status     = 'active',
         updated_at = now()
   WHERE id = p_instance_id;

  INSERT INTO public.audit_journal
    (user_id, action_type, action, entity_type, entity_id, area, severity, summary, details)
  VALUES
    (auth.uid(), 'approval', 'SOURCE_ACTIVATED', 'story_instance', p_instance_id,
     'integrations', 'info',
     format('Source instance %s approved + activated', v_instance.instance_label),
     jsonb_build_object('story_id', v_instance.story_id, 'data_sensitivity', v_sensitivity));

  RETURN jsonb_build_object(
    'instance_id', p_instance_id,
    'approved', true,
    'data_sensitivity', v_sensitivity
  );
END;
$$;

REVOKE ALL ON FUNCTION public.audience_admin_approve_source(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.audience_admin_approve_source(uuid, text) TO authenticated, service_role;

COMMENT ON FUNCTION public.audience_admin_approve_source(uuid, text) IS
  'Operator (admin/staff-only) source activation over the story spine: refuses to '
  'approve an incompletely-classified source (§1), transitions story_instances '
  'lifecycle (metadata.source_approved + status), audits SOURCE_ACTIVATED into the '
  'integrations area. The approved flag gates audience_resolve_source_binding.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_admin_assign_actors.sql
-- -----------------------------------------------------------------------------

-- Function: audience_admin_assign_actors

CREATE OR REPLACE FUNCTION public.audience_admin_assign_actors(p_actor_ids uuid[], p_assigned_to_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inserted INT := 0;
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Use study_consultants as universal scoped role binding (scope_type='actor')
  INSERT INTO public.study_consultants (study_id, partner_id, role, status, scope_type, approved_at, approved_by)
  SELECT actor_id, p_assigned_to_user_id, 'account_manager', 'approved', 'actor', now(), auth.uid()
  FROM unnest(p_actor_ids) actor_id
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  PERFORM public.audience_log_event(
    'bulk_assign',
    'audience_admin_assign_actors',
    'role_assignment',
    NULL,
    format('Assigned %s actors to user %s', v_inserted, p_assigned_to_user_id),
    jsonb_build_object('assigned_to', p_assigned_to_user_id, 'actor_ids', p_actor_ids, 'inserted', v_inserted)
  );

  RETURN v_inserted;
END;
$function$

;

REVOKE ALL ON FUNCTION audience_admin_assign_actors(uuid[],uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_admin_assign_actors(uuid[],uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION audience_admin_assign_actors(uuid[],uuid) TO authenticator;
GRANT EXECUTE ON FUNCTION audience_admin_assign_actors(uuid[],uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_admin_bulk_tag.sql
-- -----------------------------------------------------------------------------

-- Function: audience_admin_bulk_tag

CREATE OR REPLACE FUNCTION public.audience_admin_bulk_tag(p_actor_ids uuid[], p_label text, p_color text DEFAULT 'gray'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inserted INT := 0;
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  INSERT INTO public.story_labels (label, color, resource_type, resource_id, story_id, partner_id)
  SELECT p_label, p_color, 'actor', actor_id, NULL, public.get_current_partner_id()
  FROM unnest(p_actor_ids) actor_id
  ON CONFLICT (resource_type, resource_id, label) WHERE resource_id IS NOT NULL DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  PERFORM public.audience_log_event(
    'bulk_tag',
    'audience_admin_bulk_tag',
    'tag',
    NULL,
    format('Bulk-tagged %s actors with label "%s"', v_inserted, p_label),
    jsonb_build_object('label', p_label, 'actor_ids', p_actor_ids, 'inserted', v_inserted)
  );

  RETURN v_inserted;
END;
$function$

;

REVOKE ALL ON FUNCTION audience_admin_bulk_tag(uuid[],text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_admin_bulk_tag(uuid[],text,text) TO authenticated;
GRANT EXECUTE ON FUNCTION audience_admin_bulk_tag(uuid[],text,text) TO authenticator;
GRANT EXECUTE ON FUNCTION audience_admin_bulk_tag(uuid[],text,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_admin_content_reach.sql
-- -----------------------------------------------------------------------------

-- Function: audience_admin_content_reach
--
-- Governed SECURITY DEFINER replacement for the direct-granted admin view
-- public.audience_admin_content_reach_v (#572, finding N2). The view ran
-- owner-rights and was GRANT SELECT to authenticated/anon, so any logged-in
-- (or anonymous) caller could read every creator's PII (creator_email) with
-- RLS bypassed. This RPC serves the IDENTICAL projection through an admin gate:
-- is_admin_or_staff() must pass or the call RAISEs 42501. No column is dropped
-- — creator_email is preserved, but now only reachable by admin/staff.
--
-- Shape is identical to the view: one row per creator per content item,
-- unioning news (deliveries=reads + story_entries discussion/reactions) and
-- partner stories (participants=reads/attendance + story_entries discussion/
-- reactions), with 30d/90d windows, a composite reach_total, and a
-- 30d-over-prior-30d reach_trend_pct_30d. reads_prev_30d stays CTE-internal
-- (exactly as in the view) — it only feeds the trend, it was never projected.
-- Paginated (LIMIT/OFFSET) for PostgREST/Appsmith.

CREATE OR REPLACE FUNCTION public.audience_admin_content_reach(
  p_limit  integer DEFAULT 500,
  p_offset integer DEFAULT 0
)
 RETURNS TABLE(
   metric_source        text,
   content_id           uuid,
   creator_user_id      uuid,
   creator_name         text,
   creator_email        text,
   content_title        text,
   content_slug         text,
   is_published         boolean,
   published_at         timestamp with time zone,
   content_created_at   timestamp with time zone,
   reads_total          bigint,
   reads_30d            bigint,
   reads_90d            bigint,
   discussion_total     bigint,
   discussion_30d       bigint,
   discussion_90d       bigint,
   reactions_total      bigint,
   reactions_30d        bigint,
   reactions_90d        bigint,
   attendance_total     bigint,
   attendance_30d       bigint,
   attendance_90d       bigint,
   reach_total          bigint,
   reach_30d            bigint,
   reach_90d            bigint,
   reach_trend_pct_30d  numeric
 )
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  v_is_admin boolean := public.is_admin_or_staff();
  v_uid      uuid    := auth.uid();
BEGIN
  -- Role-scoped, per extranet spec 02 §3 "Studio autora / školitele":
  --   admin/staff        → every creator's rows (unchanged)
  --   authenticated author → ONLY their own rows (scoped in the final WHERE)
  --   anonymous          → denied, exactly as before
  --
  -- This does NOT reopen #572 finding N2. That leak was an owner-rights VIEW
  -- granted to authenticated/anon, so anyone could read EVERY creator's
  -- creator_email with RLS bypassed. Here a non-admin is filtered to
  -- creator_user_id = auth.uid(), so the only PII they can reach is their own —
  -- which is the whole point of an author-facing Creator Studio.
  IF NOT v_is_admin AND v_uid IS NULL THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH news_content AS (
    SELECT 'news'::text AS metric_source,
      na.id AS content_id,
      na.created_by AS creator_user_id,
      -- Resolve the i18n key to a human title. news_articles stores title_key
      -- (namespace `news`); the story branch below projects a plain-text title,
      -- so emitting the raw key here made one column carry two meanings and the
      -- Studio tiles would read "some-slug.title". Falls back locale → en → the
      -- key itself, so a missing translation degrades to today's behaviour
      -- rather than to NULL.
      public.get_translation_value_with_fallback(
        na.title_key, 'news', NULL, 'en', na.title_key
      ) AS content_title,
      na.slug AS content_slug,
      na.is_published,
      na.published_at,
      na.created_at AS content_created_at,
      -- reads / deliveries: one delivery row per recipient
      ( SELECT count(*) FROM news_article_deliveries d
         WHERE d.news_article_id = na.id) AS reads_total,
      ( SELECT count(*) FROM news_article_deliveries d
         WHERE d.news_article_id = na.id
           AND d.delivered_at > (now() - '30 days'::interval)) AS reads_30d,
      ( SELECT count(*) FROM news_article_deliveries d
         WHERE d.news_article_id = na.id
           AND d.delivered_at > (now() - '60 days'::interval)
           AND d.delivered_at <= (now() - '30 days'::interval)) AS reads_prev_30d,
      ( SELECT count(*) FROM news_article_deliveries d
         WHERE d.news_article_id = na.id
           AND d.delivered_at > (now() - '90 days'::interval)) AS reads_90d,
      -- discussion + reactions attach via story_entries subject pointer
      ( SELECT count(*) FROM story_entries se
         WHERE se.subject_type = 'news'::text AND se.subject_id = na.id
           AND se.status = 'visible'::text AND se.entry_type <> 'reaction'::text) AS discussion_total,
      ( SELECT count(*) FROM story_entries se
         WHERE se.subject_type = 'news'::text AND se.subject_id = na.id
           AND se.status = 'visible'::text AND se.entry_type <> 'reaction'::text
           AND se.created_at > (now() - '30 days'::interval)) AS discussion_30d,
      ( SELECT count(*) FROM story_entries se
         WHERE se.subject_type = 'news'::text AND se.subject_id = na.id
           AND se.status = 'visible'::text AND se.entry_type <> 'reaction'::text
           AND se.created_at > (now() - '90 days'::interval)) AS discussion_90d,
      ( SELECT count(*) FROM story_entries se
         WHERE se.subject_type = 'news'::text AND se.subject_id = na.id
           AND se.status = 'visible'::text AND se.entry_type = 'reaction'::text) AS reactions_total,
      ( SELECT count(*) FROM story_entries se
         WHERE se.subject_type = 'news'::text AND se.subject_id = na.id
           AND se.status = 'visible'::text AND se.entry_type = 'reaction'::text
           AND se.created_at > (now() - '30 days'::interval)) AS reactions_30d,
      ( SELECT count(*) FROM story_entries se
         WHERE se.subject_type = 'news'::text AND se.subject_id = na.id
           AND se.status = 'visible'::text AND se.entry_type = 'reaction'::text
           AND se.created_at > (now() - '90 days'::interval)) AS reactions_90d,
      0::bigint AS attendance_total,
      0::bigint AS attendance_30d,
      0::bigint AS attendance_90d
    FROM news_articles na
  ), story_content AS (
    SELECT 'story'::text AS metric_source,
      ps.id AS content_id,
      COALESCE(ps.user_id, ps.partner_id) AS creator_user_id,
      ps.title AS content_title,
      NULL::text AS content_slug,
      (ps.status = 'published'::text) AS is_published,
      ps.last_activity_at AS published_at,
      ps.created_at AS content_created_at,
      -- stories have no delivery log; reach surrogate is its participants
      ( SELECT count(*) FROM story_participants sp
         WHERE sp.story_id = ps.id) AS reads_total,
      ( SELECT count(*) FROM story_participants sp
         WHERE sp.story_id = ps.id
           AND sp.joined_at > (now() - '30 days'::interval)) AS reads_30d,
      ( SELECT count(*) FROM story_participants sp
         WHERE sp.story_id = ps.id
           AND sp.joined_at > (now() - '60 days'::interval)
           AND sp.joined_at <= (now() - '30 days'::interval)) AS reads_prev_30d,
      ( SELECT count(*) FROM story_participants sp
         WHERE sp.story_id = ps.id
           AND sp.joined_at > (now() - '90 days'::interval)) AS reads_90d,
      ( SELECT count(*) FROM story_entries se
         WHERE se.story_id = ps.id AND se.status = 'visible'::text
           AND se.entry_type <> 'reaction'::text) AS discussion_total,
      ( SELECT count(*) FROM story_entries se
         WHERE se.story_id = ps.id AND se.status = 'visible'::text
           AND se.entry_type <> 'reaction'::text
           AND se.created_at > (now() - '30 days'::interval)) AS discussion_30d,
      ( SELECT count(*) FROM story_entries se
         WHERE se.story_id = ps.id AND se.status = 'visible'::text
           AND se.entry_type <> 'reaction'::text
           AND se.created_at > (now() - '90 days'::interval)) AS discussion_90d,
      ( SELECT count(*) FROM story_entries se
         WHERE se.story_id = ps.id AND se.status = 'visible'::text
           AND se.entry_type = 'reaction'::text) AS reactions_total,
      ( SELECT count(*) FROM story_entries se
         WHERE se.story_id = ps.id AND se.status = 'visible'::text
           AND se.entry_type = 'reaction'::text
           AND se.created_at > (now() - '30 days'::interval)) AS reactions_30d,
      ( SELECT count(*) FROM story_entries se
         WHERE se.story_id = ps.id AND se.status = 'visible'::text
           AND se.entry_type = 'reaction'::text
           AND se.created_at > (now() - '90 days'::interval)) AS reactions_90d,
      ( SELECT count(*) FROM story_participants sp
         WHERE sp.story_id = ps.id) AS attendance_total,
      ( SELECT count(*) FROM story_participants sp
         WHERE sp.story_id = ps.id
           AND sp.joined_at > (now() - '30 days'::interval)) AS attendance_30d,
      ( SELECT count(*) FROM story_participants sp
         WHERE sp.story_id = ps.id
           AND sp.joined_at > (now() - '90 days'::interval)) AS attendance_90d
    FROM partner_stories ps
  ), unioned AS (
    SELECT * FROM news_content
    UNION ALL
    SELECT * FROM story_content
  )
  SELECT u.metric_source,
    u.content_id,
    u.creator_user_id,
    p.display_name AS creator_name,
    p.email AS creator_email,
    u.content_title,
    u.content_slug,
    u.is_published,
    u.published_at,
    u.content_created_at,
    u.reads_total,
    u.reads_30d,
    u.reads_90d,
    u.discussion_total,
    u.discussion_30d,
    u.discussion_90d,
    u.reactions_total,
    u.reactions_30d,
    u.reactions_90d,
    u.attendance_total,
    u.attendance_30d,
    u.attendance_90d,
    -- single composite reach metric across all engagement kinds
    (u.reads_total + u.discussion_total + u.reactions_total + u.attendance_total) AS reach_total,
    (u.reads_30d + u.discussion_30d + u.reactions_30d + u.attendance_30d) AS reach_30d,
    (u.reads_90d + u.discussion_90d + u.reactions_90d + u.attendance_90d) AS reach_90d,
    -- 30d-over-prior-30d trend on the reads/deliveries spine (NULL when no base)
    CASE
      WHEN u.reads_prev_30d > 0 THEN round(((u.reads_30d - u.reads_prev_30d)::numeric / u.reads_prev_30d::numeric) * 100::numeric, 1)
      WHEN u.reads_30d > 0 THEN 100.0
      ELSE NULL::numeric
    END AS reach_trend_pct_30d
  FROM unioned u
    LEFT JOIN profiles p ON p.user_id = u.creator_user_id
  -- Author self-scope. Admin/staff short-circuits to the full set; everyone else
  -- is pinned to their own content. Filtering here (not in the CTEs) keeps the
  -- union shape intact and makes LIMIT/OFFSET paginate the scoped result.
  WHERE v_is_admin OR u.creator_user_id = v_uid
  ORDER BY u.content_created_at DESC, u.content_id
  LIMIT p_limit OFFSET p_offset;
END;
$function$;

REVOKE ALL ON FUNCTION audience_admin_content_reach(integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_admin_content_reach(integer, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION audience_admin_content_reach(integer, integer) TO authenticator;
GRANT EXECUTE ON FUNCTION audience_admin_content_reach(integer, integer) TO service_role;

COMMENT ON FUNCTION public.audience_admin_content_reach(integer, integer) IS
  'Governed admin RPC replacing the direct-granted view audience_admin_content_reach_v (#572 finding N2: owner-rights view + GRANT SELECT to authenticated/anon = RLS-bypass PII leak). SECURITY DEFINER, role-scoped (extranet spec 02 §3): admin/staff see every creator; an authenticated non-admin is filtered to their OWN rows (creator_user_id = auth.uid()) so authors get a Creator Studio without reaching anyone else''s PII; anonymous is denied (RAISE 42501). Projection is identical to the view — one row per creator per content item, unioning news (news_article_deliveries=reads + story_entries discussion/reactions) and partner stories (story_participants=reads/attendance + story_entries discussion/reactions), with 30d/90d windows, composite reach_total/reach_30d/reach_90d and a 30d-over-prior-30d reach_trend_pct_30d. creator_email PII is preserved (no downgrade); admin/staff read it for every creator, an author only for themselves. content_title resolves news title_key via get_translation_value_with_fallback(namespace ''news'', locale→en→key) so the column is a human title for BOTH branches, not a raw i18n key on the news side. metric_source is ''news''|''story''. ORDER BY content_created_at DESC, content_id; LIMIT/OFFSET paginated. audience_ prefix inherits audience_autorevoke_public_execute (auto-strips PUBLIC/anon EXECUTE) + audience_audit_grants gates.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_admin_create_cohort_from_filter.sql
-- -----------------------------------------------------------------------------

-- Function: audience_admin_create_cohort_from_filter

CREATE OR REPLACE FUNCTION public.audience_admin_create_cohort_from_filter(p_name text, p_description text, p_filter jsonb, p_cohort_type text DEFAULT 'marketing_segment'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cohort_id UUID;
  v_registered INT := 0;
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Insert cohort (studies row)
  INSERT INTO public.studies (
    code, name, description, study_type, status,
    is_active, starts_at, created_at
  ) VALUES (
    'cohort_' || extract(epoch from now())::text,
    p_name,
    p_description,
    p_cohort_type::study_type,
    'screening',
    true,
    now(),
    now()
  )
  RETURNING id INTO v_cohort_id;

  -- Auto-register matching actors based on filter
  -- (Simple implementation: filter by member_tier; expand as needed)
  IF p_filter ? 'tier' THEN
    INSERT INTO public.study_registrations (study_id, user_id, status, enrolled_at, created_at)
    SELECT v_cohort_id, t.user_id, 'active', now(), now()
    FROM public.audience_actor_tier_v t
    WHERE t.member_tier = p_filter->>'tier'
    ON CONFLICT DO NOTHING;

    GET DIAGNOSTICS v_registered = ROW_COUNT;

    UPDATE public.studies
    SET current_registration = v_registered
    WHERE id = v_cohort_id;
  END IF;

  PERFORM public.audience_log_event(
    'create_cohort',
    'audience_admin_create_cohort_from_filter',
    'cohort',
    v_cohort_id,
    format('Created cohort "%s" with %s registrations', p_name, v_registered),
    jsonb_build_object('filter', p_filter, 'cohort_id', v_cohort_id, 'registered', v_registered)
  );

  RETURN v_cohort_id;
END;
$function$

;

