-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_user_can_see_creator_stats.sql
-- -----------------------------------------------------------------------------

-- Function: audience_user_can_see_creator_stats

CREATE OR REPLACE FUNCTION public.audience_user_can_see_creator_stats(p_target_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    is_admin_or_staff()
    OR p_target_user_id = auth.uid()
    OR EXISTS (
      SELECT 1
      FROM public.study_consultants ra_caller
      JOIN public.study_consultants ra_target
        ON ra_target.scope_type = ra_caller.scope_type
       AND ra_target.study_id = ra_caller.study_id
       AND ra_target.partner_id = p_target_user_id
       AND ra_target.status = 'approved'
      WHERE ra_caller.partner_id = auth.uid()
        AND ra_caller.status = 'approved'
        AND ra_caller.role IN ('communication', 'secretary', 'account_manager')
    );
$function$

;

REVOKE ALL ON FUNCTION audience_user_can_see_creator_stats(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_user_can_see_creator_stats(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION audience_user_can_see_creator_stats(uuid) TO authenticator;
GRANT EXECUTE ON FUNCTION audience_user_can_see_creator_stats(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_derive_actor_tier.sql
-- -----------------------------------------------------------------------------

-- Function: audience_derive_actor_tier
--
-- Public, privacy-guarded tier derivation: only an admin/staff caller, the actor themselves,
-- or an approved consultant may derive (and thereby observe) an actor's tier. Delegates the
-- actual tier computation to audience_compute_actor_tier (the single source of truth, shared
-- with the Brick6 tier-ACL) so the tier rules live in exactly one place.
CREATE OR REPLACE FUNCTION public.audience_derive_actor_tier(p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.audience_user_can_see_creator_stats(p_user_id) THEN
    RAISE EXCEPTION 'Access denied: caller % cannot derive tier for actor %',
      COALESCE(auth.uid()::text, '<anon>'), p_user_id
      USING ERRCODE = '42501';
  END IF;

  RETURN public.audience_compute_actor_tier(p_user_id);
END;
$function$;

REVOKE ALL ON FUNCTION audience_derive_actor_tier(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_derive_actor_tier(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION audience_derive_actor_tier(uuid) TO authenticator;
GRANT EXECUTE ON FUNCTION audience_derive_actor_tier(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_get_my_tier.sql
-- -----------------------------------------------------------------------------

-- Function: audience_get_my_tier

CREATE OR REPLACE FUNCTION public.audience_get_my_tier()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'user_id', auth.uid(),
    'member_tier', public.audience_derive_actor_tier(auth.uid()),
    'is_admin_or_staff', is_admin_or_staff(),
    'effective_tier', CASE
      WHEN is_admin_or_staff() THEN 'admin'
      ELSE public.audience_derive_actor_tier(auth.uid())
    END
  );
$function$

;

REVOKE ALL ON FUNCTION audience_get_my_tier() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_get_my_tier() TO authenticated;
GRANT EXECUTE ON FUNCTION audience_get_my_tier() TO authenticator;
GRANT EXECUTE ON FUNCTION audience_get_my_tier() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_get_tags_for.sql
-- -----------------------------------------------------------------------------

-- Function: audience_get_tags_for

CREATE OR REPLACE FUNCTION public.audience_get_tags_for(p_resource_type text, p_resource_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL AND public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Access denied: authentication required to read tags' USING ERRCODE = '42501';
  END IF;
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' AND NOT public.is_admin_or_staff() THEN
    IF p_resource_type = 'actor' THEN
      IF NOT public.audience_user_can_see_creator_stats(p_resource_id) THEN
        RAISE EXCEPTION 'Access denied: cannot read tags for actor %', p_resource_id USING ERRCODE = '42501';
      END IF;
    ELSE
      RAISE EXCEPTION 'Access denied: tag read for resource_type % requires admin/staff', p_resource_type USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN (
    SELECT array_agg(DISTINCT label ORDER BY label)
    FROM public.story_labels
    WHERE resource_type = p_resource_type AND resource_id = p_resource_id
  );
END;
$function$

;

REVOKE ALL ON FUNCTION audience_get_tags_for(text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_get_tags_for(text,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION audience_get_tags_for(text,uuid) TO authenticator;
GRANT EXECUTE ON FUNCTION audience_get_tags_for(text,uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_user_meets_tier_requirement.sql
-- -----------------------------------------------------------------------------

-- Function: audience_user_meets_tier_requirement
--
-- 1-arg: does the CURRENT caller (auth.uid(), or 'admin' if staff) meet p_required_tier?
-- 2-arg (Brick6 tier-ACL): does a SPECIFIC user meet it? Used by mcp_search_knowledge_v2/v3
--   to gate knowledge by minimum_tier. Properties:
--     * FAIL CLOSED — a NULL/unknown user is 'anonymous' (the lowest tier);
--     * uses the UNGUARDED audience_compute_actor_tier (a boolean gate exposes no stats, so the
--       privacy guard would only get in the way of a service-role tier check);
--     * admin/staff users meet every tier;
--     * spoof-safety is the caller's responsibility — v2/v3 only let service_role pass an
--       arbitrary p_user_id; authenticated callers are pinned to auth.uid().

CREATE OR REPLACE FUNCTION public.audience_user_meets_tier_requirement(p_required_tier text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH tier_rank AS (
    SELECT * FROM (VALUES
      ('anonymous', 0), ('registered', 1), ('active', 2),
      ('qualified', 3), ('partner', 4), ('admin', 5)
    ) AS t(name, rank)
  )
  SELECT caller.rank >= required.rank
  FROM tier_rank required, tier_rank caller
  WHERE required.name = p_required_tier
    AND caller.name = CASE
      WHEN is_admin_or_staff() THEN 'admin'
      ELSE public.audience_derive_actor_tier(auth.uid())
    END;
$function$;

CREATE OR REPLACE FUNCTION public.audience_user_meets_tier_requirement(p_required_tier text, p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tier text;
BEGIN
  IF p_required_tier IS NULL THEN
    RETURN true;  -- ungated knowledge: everyone qualifies
  END IF;
  -- FAIL CLOSED: NULL/unknown user => 'anonymous'. is_admin_or_staff(p_user_id) so an
  -- admin/staff actor meets every tier (audience_compute_actor_tier itself never returns 'admin').
  v_tier := CASE
    WHEN p_user_id IS NOT NULL AND public.is_admin_or_staff(p_user_id) THEN 'admin'
    ELSE public.audience_compute_actor_tier(p_user_id)
  END;
  RETURN (
    WITH tier_rank AS (
      SELECT * FROM (VALUES
        ('anonymous', 0), ('registered', 1), ('active', 2),
        ('qualified', 3), ('partner', 4), ('admin', 5)
      ) AS t(name, rank)
    )
    SELECT caller.rank >= required.rank
    FROM tier_rank required, tier_rank caller
    WHERE required.name = p_required_tier AND caller.name = v_tier
  );
END;
$function$;

REVOKE ALL ON FUNCTION audience_user_meets_tier_requirement(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_user_meets_tier_requirement(text) TO authenticated;
GRANT EXECUTE ON FUNCTION audience_user_meets_tier_requirement(text) TO authenticator;
GRANT EXECUTE ON FUNCTION audience_user_meets_tier_requirement(text) TO service_role;
REVOKE ALL ON FUNCTION audience_user_meets_tier_requirement(text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_user_meets_tier_requirement(text, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_user_can_access_via_profile.sql
-- -----------------------------------------------------------------------------

-- Function: audience_user_can_access_via_profile

CREATE OR REPLACE FUNCTION public.audience_user_can_access_via_profile(p_profile_slug text, p_target_user_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_profile public.context_profiles%ROWTYPE;
  v_scope_filter TEXT;
BEGIN
  SELECT * INTO v_profile FROM public.context_profiles WHERE slug = p_profile_slug AND is_active = true;
  IF NOT FOUND THEN
    RETURN false;
  END IF;

  -- Tier gate
  IF v_profile.tier_required IS NOT NULL THEN
    IF NOT public.audience_user_meets_tier_requirement(v_profile.tier_required) THEN
      RETURN false;
    END IF;
  END IF;

  -- Permission gate
  IF v_profile.permission_required IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM unnest(public.get_user_permissions()) AS perm
      WHERE perm = v_profile.permission_required
    ) THEN
      RETURN false;
    END IF;
  END IF;

  -- Scope filter evaluation
  v_scope_filter := v_profile.data_scope_rule->>'filter';
  IF v_scope_filter IS NULL OR v_scope_filter = '' THEN
    RETURN true;
  END IF;

  -- Known filter patterns
  IF v_scope_filter = 'creator_user_id = auth.uid()' THEN
    RETURN p_target_user_id IS NULL OR p_target_user_id = auth.uid();
  END IF;

  IF v_scope_filter = 'target_user_id = auth.uid()' THEN
    RETURN p_target_user_id IS NULL OR p_target_user_id = auth.uid();
  END IF;

  IF v_scope_filter LIKE '%scope_member_of%' THEN
    RETURN public.audience_user_can_see_creator_stats(p_target_user_id);
  END IF;

  IF v_scope_filter = 'is_admin_or_staff()' THEN
    RETURN is_admin_or_staff();
  END IF;

  -- Deny by default for unknown patterns
  RETURN false;
END;
$function$

;

REVOKE ALL ON FUNCTION audience_user_can_access_via_profile(text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_user_can_access_via_profile(text,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION audience_user_can_access_via_profile(text,uuid) TO authenticator;
GRANT EXECUTE ON FUNCTION audience_user_can_access_via_profile(text,uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_start_actor_ai_session.sql
-- -----------------------------------------------------------------------------

-- Function: audience_start_actor_ai_session

CREATE OR REPLACE FUNCTION public.audience_start_actor_ai_session(p_focus_actor_id uuid, p_mode text DEFAULT 'chat'::text, p_context_profile_slug text DEFAULT 'audience_ai_actor_assistant'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_conversation_id UUID;
  v_story_id UUID;
  v_partner_id UUID;
  v_can_access BOOLEAN;
BEGIN
  -- Permission check
  v_can_access := public.audience_user_can_access_via_profile(p_context_profile_slug, p_focus_actor_id);
  IF NOT v_can_access THEN
    RAISE EXCEPTION 'Access denied: caller cannot use context profile % for actor %', p_context_profile_slug, p_focus_actor_id;
  END IF;

  -- story_ai_sessions.story_id is NOT NULL → a partner_story is required, which
  -- in turn requires partner_id. Deep AI relationship sessions therefore apply
  -- only to partner-tier (managed) contacts. Fail clearly otherwise.
  SELECT id INTO v_partner_id FROM public.partner_profiles WHERE user_id = p_focus_actor_id LIMIT 1;
  IF v_partner_id IS NULL THEN
    RAISE EXCEPTION 'Actor % is not a managed partner contact (no partner_profiles row); actor AI sessions require a partner-tier contact', p_focus_actor_id;
  END IF;

  -- Create chat conversation
  INSERT INTO public.chat_conversations (user_id, title, status)
  VALUES (auth.uid(),
          'AI: ' || COALESCE((SELECT display_name FROM public.profiles WHERE user_id = p_focus_actor_id), p_focus_actor_id::text),
          'active')
  RETURNING id INTO v_conversation_id;

  -- Find or create partner_story for the focus actor (partner_id NOT NULL)
  SELECT id INTO v_story_id FROM public.partner_stories WHERE user_id = p_focus_actor_id LIMIT 1;
  IF v_story_id IS NULL THEN
    INSERT INTO public.partner_stories (partner_id, user_id, title, last_activity_at, created_at)
    VALUES (v_partner_id, p_focus_actor_id,
            'Audience relationship — ' || COALESCE((SELECT display_name FROM public.profiles WHERE user_id = p_focus_actor_id), p_focus_actor_id::text),
            now(), now())
    RETURNING id INTO v_story_id;
  END IF;

  -- Create story_ai_sessions row with focus_actor_id
  INSERT INTO public.story_ai_sessions (
    story_id,
    conversation_id,
    session_type,
    focus_actor_id,
    context_snapshot
  ) VALUES (
    v_story_id,
    v_conversation_id,
    p_mode,
    p_focus_actor_id,
    jsonb_build_object(
      'context_profile_slug', p_context_profile_slug,
      'started_at', now(),
      'started_by', auth.uid()
    )
  );

  -- Audit log
  PERFORM public.audience_log_event(
    'create',
    'start_actor_ai_session',
    'chat_conversation',
    v_conversation_id,
    'Started AI session about actor',
    jsonb_build_object('focus_actor_id', p_focus_actor_id, 'mode', p_mode)
  );

  RETURN v_conversation_id;
END;
$function$

;

REVOKE ALL ON FUNCTION audience_start_actor_ai_session(uuid,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_start_actor_ai_session(uuid,text,text) TO authenticated;
GRANT EXECUTE ON FUNCTION audience_start_actor_ai_session(uuid,text,text) TO authenticator;
GRANT EXECUTE ON FUNCTION audience_start_actor_ai_session(uuid,text,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/award_leaderboard_rewards.sql
-- -----------------------------------------------------------------------------

-- award_leaderboard_rewards: Process token and voucher rewards for a completed leaderboard period
CREATE OR REPLACE FUNCTION public.award_leaderboard_rewards(
  p_period_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_admin_id uuid := auth.uid();
  v_period record;
  v_entry record;
  v_config record;
  v_awarded_count integer := 0;
  v_vouchers_created integer := 0;
  v_voucher_code text;
  v_voucher_id uuid;
  v_attempt integer;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  -- Get period info
  SELECT * INTO v_period
  FROM public.leaderboard_periods
  WHERE id = p_period_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Period not found' USING ERRCODE = 'P0001';
  END IF;

  -- Process each ranked entry
  FOR v_entry IN
    SELECT le.user_id, le.rank, le.total_points
    FROM public.leaderboard_entries le
    WHERE le.period_id = p_period_id
      AND le.rank IS NOT NULL
    ORDER BY le.rank ASC
  LOOP
    -- Find matching reward configs
    FOR v_config IN
      SELECT *
      FROM public.leaderboard_reward_config
      WHERE period_type = v_period.period_type
        AND is_active = true
        AND v_entry.rank >= rank_from
        AND v_entry.rank <= rank_to
    LOOP
      -- Award bonus tokens
      IF v_config.bonus_tokens > 0 THEN
        PERFORM public.award_tokens(
          v_entry.user_id,
          v_config.bonus_token_type,
          v_config.bonus_tokens,
          'leaderboard_reward',
          p_period_id,
          'Leaderboard rank #' || v_entry.rank || ' reward'
        );
        v_awarded_count := v_awarded_count + 1;
      END IF;

      -- Create voucher if product configured
      IF v_config.voucher_product_id IS NOT NULL THEN
        FOR v_attempt IN 1..10 LOOP
          v_voucher_code := upper(substring(md5(gen_random_uuid()::text || clock_timestamp()::text) FROM 1 FOR 8));
          BEGIN
            INSERT INTO public.product_vouchers (
              code, product_id, user_id, status, points_cost, expires_at, metadata
            ) VALUES (
              v_voucher_code,
              v_config.voucher_product_id,
              v_entry.user_id,
              'active',
              0,
              now() + interval '1 year',
              jsonb_build_object(
                'type', 'leaderboard_reward',
                'period_id', p_period_id,
                'rank', v_entry.rank,
                'created_by', v_admin_id
              )
            ) RETURNING product_vouchers.id INTO v_voucher_id;
            v_vouchers_created := v_vouchers_created + 1;
            EXIT;
          EXCEPTION
            WHEN unique_violation THEN NULL;
          END;
        END LOOP;
      END IF;
    END LOOP;
  END LOOP;

  -- Audit log
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_admin_id, 'LEADERBOARD_REWARDS_AWARDED', jsonb_build_object(
    'area', 'admin',
    'severity', 'info',
    'period_id', p_period_id,
    'period_type', v_period.period_type,
    'tokens_awarded', v_awarded_count,
    'vouchers_created', v_vouchers_created
  ));

  RETURN jsonb_build_object(
    'success', true,
    'tokens_awarded', v_awarded_count,
    'vouchers_created', v_vouchers_created
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.award_leaderboard_rewards(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.award_leaderboard_rewards(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/calculate_user_product_max_daily_distribution.sql
-- -----------------------------------------------------------------------------

-- Function: public.calculate_user_product_max_daily_distribution
-- Arguments: p_user_id uuid, p_product_id uuid
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.calculate_user_product_max_daily_distribution(p_user_id uuid, p_product_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_study_max numeric := 0;
  v_subscription_max numeric := 0;
  v_drops_per_ml numeric := 22;
  v_drops_per_spray numeric := 4;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_user_id IS NULL OR p_product_id IS NULL THEN
    RETURN 0;
  END IF;

  IF p_user_id <> v_actor_id AND NOT public.is_admin_or_staff(v_actor_id) THEN
    RAISE EXCEPTION 'Insufficient privileges' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(drops_per_ml, 22)
  INTO v_drops_per_ml
  FROM public.products
  WHERE id = p_product_id;

  SELECT COALESCE(
    MAX(
      CASE
        WHEN dp.dose_unit = 'ml' THEN (dp.dose_amount * v_drops_per_ml) * dp.doses_per_day
        WHEN dp.dose_unit = 'sprays' THEN (dp.dose_amount * v_drops_per_spray) * dp.doses_per_day
        ELSE dp.dose_amount * dp.doses_per_day
      END
    ),
    0
  )
  INTO v_study_max
  FROM public.member_distribution_plans mdp
  JOIN public.study_registrations se ON se.id = mdp.study_registration_id
  JOIN public.study_distribution_protocols dp ON dp.study_id = se.study_id
  JOIN public.studies s ON s.id = se.study_id
  WHERE mdp.user_id = p_user_id
    AND mdp.status = 'active'
    AND s.status = 'active'
    AND dp.product_id = p_product_id
    AND dp.is_active = true;

  SELECT COALESCE(
    MAX((COALESCE(p.volume_ml, 30) * COALESCE(p.drops_per_ml, 22)) / 30.0),
    0
  )
  INTO v_subscription_max
  FROM public.memberships m
  JOIN public.subscription_packages sp ON sp.tier = m.tier
  CROSS JOIN unnest(sp.includes_products) AS included_slug
  JOIN public.products p ON p.slug = included_slug
  WHERE m.user_id = p_user_id
    AND m.status = 'active'
    AND sp.is_active = true
    AND (m.expires_at IS NULL OR m.expires_at >= now())
    AND p.id = p_product_id;

  RETURN GREATEST(v_study_max, v_subscription_max);
END;
$function$;

REVOKE ALL ON FUNCTION public.calculate_user_product_max_daily_distribution(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.calculate_user_product_max_daily_distribution(uuid, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.calculate_user_product_max_daily_distribution(uuid, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/calculate_monthly_bottle_allowance.sql
-- -----------------------------------------------------------------------------

-- Function: public.calculate_monthly_bottle_allowance
-- Converts max allowed daily drops into monthly bottle count for one product.

CREATE OR REPLACE FUNCTION public.calculate_monthly_bottle_allowance(
  p_user_id uuid,
  p_product_id uuid
)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_daily_drops numeric := 0;
  v_bottle_drops numeric := 0;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_user_id IS NULL OR p_product_id IS NULL THEN
    RETURN 0;
  END IF;

  IF p_user_id <> v_actor_id AND NOT public.is_admin_or_staff(v_actor_id) THEN
    RAISE EXCEPTION 'Insufficient privileges' USING ERRCODE = '42501';
  END IF;

  v_daily_drops := public.calculate_user_product_max_daily_distribution(p_user_id, p_product_id);

  SELECT COALESCE(volume_ml, 30) * COALESCE(drops_per_ml, 22)
  INTO v_bottle_drops
  FROM public.products
  WHERE id = p_product_id;

  IF v_bottle_drops IS NULL OR v_bottle_drops <= 0 THEN
    v_bottle_drops := 600;
  END IF;

  IF v_daily_drops IS NULL OR v_daily_drops <= 0 THEN
    RETURN 0;
  END IF;

  RETURN CEIL((v_daily_drops * 30.0) / v_bottle_drops)::integer;
END;
$function$;

REVOKE ALL ON FUNCTION public.calculate_monthly_bottle_allowance(uuid, uuid) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.calculate_monthly_bottle_allowance(uuid, uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.calculate_monthly_bottle_allowance(uuid, uuid) TO authenticated;


