-- File: aisha/db/sql/functions/create_archive_tag_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Function: create_archive_tag_admin
-- Purpose: Create a new archive tag (admin only)
-- Access: Admin/Staff only
-- ============================================================================

CREATE OR REPLACE FUNCTION public.create_archive_tag_admin(
  p_code TEXT,
  p_category TEXT,
  p_display_name TEXT,
  p_name_key TEXT DEFAULT NULL,
  p_sort_order INTEGER DEFAULT 0,
  p_is_active BOOLEAN DEFAULT TRUE
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
DECLARE
  v_id UUID;
  v_name_key TEXT;
BEGIN
  -- Authorization check
  IF NOT is_admin_or_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Unauthorized: Admin or staff role required';
  END IF;

  -- Validate category
  IF p_category NOT IN ('person', 'keyword', 'preparation', 'facility', 'place') THEN
    RAISE EXCEPTION USING MESSAGE = format('Invalid category: %s', p_category), ERRCODE = '22023';
  END IF;

  -- Generate name_key if not provided
  v_name_key := COALESCE(
    p_name_key,
    'archive.tags.' || p_category || '.' || regexp_replace(lower(trim(p_code)), '[^a-z0-9]+', '_', 'g')
  );

  -- Insert
  INSERT INTO archive_tags (
    code,
    category,
    name_key,
    display_name,
    sort_order,
    is_active
  )
  VALUES (
    lower(trim(p_code)),
    p_category::archive_tag_category,
    v_name_key,
    trim(p_display_name),
    p_sort_order,
    p_is_active
  )
  RETURNING id INTO v_id;

  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'create',
    jsonb_build_object(
      'area', 'archive_tags',
      'tag_id', v_id,
      'category', p_category,
      'code', p_code
    )
  );

  RETURN v_id;
END;
$$;

-- Security
REVOKE ALL ON FUNCTION public.create_archive_tag_admin(text, text, text, text, integer, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_archive_tag_admin(text, text, text, text, integer, boolean) TO authenticated;

COMMENT ON FUNCTION public.create_archive_tag_admin(text, text, text, text, integer, boolean) IS 'Create a new archive tag (admin only)';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_manual_voucher_admin.sql
-- -----------------------------------------------------------------------------

-- create_manual_voucher_admin: Admin creates voucher manually (promo, compensation)
CREATE OR REPLACE FUNCTION public.create_manual_voucher_admin(
  p_product_id uuid,
  p_reason text DEFAULT 'manual',
  p_user_id uuid DEFAULT NULL
)
RETURNS TABLE (
  code text,
  id uuid
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_admin_id uuid := auth.uid();
  v_voucher_id uuid;
  v_voucher_code text;
  v_attempt int4;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  IF p_product_id IS NULL THEN
    RAISE EXCEPTION 'Product is required' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.products WHERE products.id = p_product_id) THEN
    RAISE EXCEPTION 'Product not found' USING ERRCODE = 'P0001';
  END IF;

  -- Generate unique 8-char code
  FOR v_attempt IN 1..10 LOOP
    v_voucher_code := upper(substring(md5(gen_random_uuid()::text || clock_timestamp()::text) FROM 1 FOR 8));

    BEGIN
      INSERT INTO public.product_vouchers (
        code,
        product_id,
        user_id,
        status,
        points_cost,
        expires_at,
        metadata
      )
      VALUES (
        v_voucher_code,
        p_product_id,
        p_user_id,  -- NULL means unassigned (general promo)
        'active',
        0,  -- no token cost for manual vouchers
        now() + interval '1 year',
        jsonb_build_object(
          'created_by', v_admin_id,
          'reason', p_reason,
          'type', 'manual'
        )
      )
      RETURNING product_vouchers.id INTO v_voucher_id;
      EXIT;
    EXCEPTION
      WHEN unique_violation THEN NULL;
    END;
  END LOOP;

  IF v_voucher_id IS NULL THEN
    RAISE EXCEPTION 'Failed to generate voucher code' USING ERRCODE = 'P0001';
  END IF;

  -- Audit log
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_admin_id, 'VOUCHER_MANUAL_CREATE', jsonb_build_object(
    'area', 'admin',
    'severity', 'info',
    'voucher_id', v_voucher_id,
    'product_id', p_product_id,
    'target_user_id', p_user_id,
    'reason', p_reason
  ));

  RETURN QUERY SELECT v_voucher_code, v_voucher_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.create_manual_voucher_admin(uuid, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_manual_voucher_admin(uuid, text, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_membership.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_membership
-- Arguments: p_tier membership_tier
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:05+01:00

CREATE OR REPLACE FUNCTION public.create_membership(p_tier membership_tier DEFAULT 'basic'::membership_tier)
 RETURNS TABLE(id uuid, user_id uuid, tier membership_tier, status membership_status, payment_type payment_type, subscription_period subscription_period, stripe_subscription_id text, stripe_customer_id text, starts_at timestamptz, expires_at timestamptz, auto_renew boolean, tokens_governance integer, tokens_impact integer, tokens_data integer, notes text, created_at timestamptz, updated_at timestamptz)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
    v_id UUID;
    v_tier membership_tier := p_tier;
BEGIN
    -- Self-service cannot self-grant a paid tier: this function is SECURITY INVOKER
    -- and only requires the authenticated role, so without this a member could create
    -- their own 'upgraded' membership for free. Paid tiers must come from the
    -- subscription->membership bridge (admin activation). Non-admins are coerced to
    -- 'basic'; admin/staff may still create any tier directly.
    IF v_tier <> 'basic'::membership_tier AND NOT public.is_admin_or_staff(auth.uid()) THEN
      v_tier := 'basic'::membership_tier;
    END IF;

    INSERT INTO public.memberships (user_id, tier, status, payment_type, starts_at)
    VALUES (auth.uid(), v_tier, 'active', 'one_time', NOW())
    RETURNING memberships.id INTO v_id;

    RETURN QUERY SELECT m.id, m.user_id, m.tier, m.status, m.payment_type, m.subscription_period,
           m.stripe_subscription_id, m.stripe_customer_id, m.starts_at, m.expires_at,
           m.auto_renew, m.tokens_governance, m.tokens_impact, m.tokens_data,
           m.notes, m.created_at, m.updated_at
    FROM public.memberships m WHERE m.id = v_id;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.create_membership(p_tier membership_tier) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.create_membership(p_tier membership_tier) FROM anon;
GRANT EXECUTE ON FUNCTION public.create_membership(p_tier membership_tier) TO authenticated;


