-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/detect_project_context_from_analysis.sql
-- -----------------------------------------------------------------------------

-- Function: detect_project_context_from_analysis
-- Purpose: Accept repo analysis results and update story delivery context
-- Security: SECURITY DEFINER (admin/staff or story owner)
-- MCP tool: detect_project_context_from_analysis

CREATE OR REPLACE FUNCTION public.detect_project_context_from_analysis(
  p_story_id uuid,
  p_analysis jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_tech_stack text[];
  v_domain text[];
  v_risk_profile text;
  v_repo_url text;
  v_repo_provider text;
  v_default_branch text;
  v_updated int := 0;
BEGIN
  -- Authorization: admin/staff or story owner
  IF NOT is_admin_or_staff() THEN
    IF NOT EXISTS (
      SELECT 1 FROM partner_stories
      WHERE id = p_story_id AND partner_id = auth.uid()
    ) THEN
      RAISE EXCEPTION 'Unauthorized: not story owner or admin/staff';
    END IF;
  END IF;

  IF p_analysis IS NULL OR p_analysis = '{}'::jsonb THEN
    RETURN jsonb_build_object('success', false, 'error', 'Empty analysis provided');
  END IF;

  -- Extract fields from analysis JSON
  SELECT
    CASE WHEN p_analysis ? 'tech_stack'
      THEN ARRAY(SELECT jsonb_array_elements_text(p_analysis->'tech_stack'))
      ELSE NULL
    END,
    CASE WHEN p_analysis ? 'domain'
      THEN ARRAY(SELECT jsonb_array_elements_text(p_analysis->'domain'))
      ELSE NULL
    END,
    p_analysis->>'risk_profile',
    p_analysis->>'repo_url',
    p_analysis->>'repo_provider',
    p_analysis->>'default_branch'
  INTO v_tech_stack, v_domain, v_risk_profile, v_repo_url, v_repo_provider, v_default_branch;

  -- Update partner_stories with detected context
  UPDATE partner_stories SET
    tech_stack = COALESCE(v_tech_stack, tech_stack),
    domain = COALESCE(v_domain, domain),
    risk_profile = COALESCE(v_risk_profile, risk_profile),
    repo_url = COALESCE(v_repo_url, repo_url),
    repo_provider = COALESCE(v_repo_provider, repo_provider),
    default_branch = COALESCE(v_default_branch, default_branch),
    delivery_status = COALESCE(delivery_status, 'analyzing'),
    updated_at = now()
  WHERE id = p_story_id;

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  -- Audit
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'PROJECT_CONTEXT_DETECTED',
    jsonb_build_object(
      'area', 'ai',
      'severity', 'info',
      'story_id', p_story_id,
      'tech_stack_count', COALESCE(array_length(v_tech_stack, 1), 0),
      'domain_count', COALESCE(array_length(v_domain, 1), 0),
      'risk_profile', v_risk_profile,
      'source', COALESCE(p_analysis->>'source', 'manual')
    )
  );

  RETURN jsonb_build_object(
    'success', v_updated > 0,
    'story_id', p_story_id,
    'detected', jsonb_build_object(
      'tech_stack', COALESCE(to_jsonb(v_tech_stack), '[]'::jsonb),
      'domain', COALESCE(to_jsonb(v_domain), '[]'::jsonb),
      'risk_profile', v_risk_profile,
      'repo_url', v_repo_url
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION public.detect_project_context_from_analysis(uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.detect_project_context_from_analysis(uuid, jsonb) TO authenticated;

COMMENT ON FUNCTION public.detect_project_context_from_analysis(uuid, jsonb) IS
  'Accepts project analysis results (from MCP/n8n repo analyzer) and updates story delivery context. '
  'Used by AISHA onboarding pipeline after repo analysis.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/discard_news_article_draft_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.discard_news_article_draft_admin
-- Description: Zahodí koncept zveřejněného článku — web nic nepozná, editor se
--              vrátí k poslednímu zveřejněnému stavu. Vrací razítko po zahození
--              (= updated_at článku). Bez konceptu je to no-op.
-- Security: SECURITY DEFINER, admin/staff.
-- Created: 2026-09-24

CREATE OR REPLACE FUNCTION public.discard_news_article_draft_admin(p_article_id uuid)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_updated timestamptz;
  v_smazano integer;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT a.updated_at INTO v_updated FROM public.news_articles a WHERE a.id = p_article_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Article not found';
  END IF;

  DELETE FROM public.news_article_versions d
  WHERE d.article_id = p_article_id AND d.kind = 'draft';
  GET DIAGNOSTICS v_smazano = ROW_COUNT;

  IF v_smazano > 0 THEN
    INSERT INTO public.audit_journal (user_id, action, metadata)
    VALUES (auth.uid(), 'NEWS_DRAFT_DISCARD',
            jsonb_build_object('area', 'content', 'severity', 'info', 'entity_type', 'news_article',
                               'entity_id', p_article_id::text));
  END IF;

  RETURN v_updated;
END;
$$;

REVOKE ALL ON FUNCTION public.discard_news_article_draft_admin(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.discard_news_article_draft_admin(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_story_ai.sql
-- -----------------------------------------------------------------------------

-- Function: public.edge_story_ai
-- Purpose: Edge-safe story AI session persistence and audit.

CREATE OR REPLACE FUNCTION public.edge_story_ai(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_caller_id uuid;
  v_user_id uuid;
  v_story_id uuid;
  v_conversation_id uuid;
  v_is_admin_staff boolean := false;
  v_is_service_role boolean := false;
  v_has_story_access boolean := false;
  v_created boolean := false;
BEGIN
  v_caller_id := auth.uid();
  v_is_service_role := COALESCE(
    (current_setting('request.jwt.claims', true)::jsonb ->> 'role') = 'service_role',
    false
  );
  v_user_id := NULLIF(p_payload ->> 'user_id', '')::uuid;
  v_story_id := NULLIF(p_payload ->> 'story_id', '')::uuid;

  IF v_user_id IS NULL THEN
    v_user_id := v_caller_id;
  END IF;

  IF NOT v_is_service_role THEN
    IF v_caller_id IS NULL THEN
      RAISE EXCEPTION 'Not authenticated';
    END IF;

    IF v_user_id IS DISTINCT FROM v_caller_id THEN
      RAISE EXCEPTION 'Unauthorized: user mismatch';
    END IF;
  END IF;

  IF p_action = 'get_or_create_story_conversation' THEN
    IF v_user_id IS NULL THEN
      RAISE EXCEPTION 'user_id is required';
    END IF;

    IF v_story_id IS NULL THEN
      RAISE EXCEPTION 'story_id is required';
    END IF;

    v_is_admin_staff := public.is_admin_or_staff(v_user_id);

    SELECT EXISTS (
      SELECT 1
      FROM public.partner_stories ps
      LEFT JOIN public.partner_profiles pp ON pp.id = ps.partner_id
      WHERE ps.id = v_story_id
        AND (
          ps.user_id = v_user_id
          OR pp.user_id = v_user_id
          OR v_is_admin_staff
        )
    ) INTO v_has_story_access;

    IF NOT v_has_story_access THEN
      RAISE EXCEPTION 'Unauthorized: Story access denied';
    END IF;

    SELECT sas.conversation_id
    INTO v_conversation_id
    FROM public.story_ai_sessions sas
    JOIN public.chat_conversations cc ON cc.id = sas.conversation_id
    WHERE sas.story_id = v_story_id
      AND sas.conversation_id IS NOT NULL
      AND cc.user_id = v_user_id
      AND cc.status = 'active'
    ORDER BY sas.created_at DESC
    LIMIT 1;

    IF v_conversation_id IS NULL THEN
      SELECT cc.id
      INTO v_conversation_id
      FROM public.chat_conversations cc
      WHERE cc.user_id = v_user_id
        AND cc.status = 'active'
        AND cc.summary = format('story_id:%s', v_story_id::text)
      ORDER BY cc.last_message_at DESC NULLS LAST, cc.created_at DESC
      LIMIT 1;
    END IF;

    IF v_conversation_id IS NULL THEN
      INSERT INTO public.chat_conversations (
        user_id,
        title,
        summary,
        status
      )
      VALUES (
        v_user_id,
        COALESCE(
          NULLIF(p_payload ->> 'title', ''),
          'Story consultation'
        ),
        format('story_id:%s', v_story_id::text),
        'active'
      )
      RETURNING id INTO v_conversation_id;

      v_created := true;
    END IF;

    RETURN jsonb_build_object(
      'conversation_id', v_conversation_id,
      'created', v_created,
      'story_id', v_story_id,
      'user_id', v_user_id
    );
  END IF;

  IF p_action = 'insert_session' THEN
    IF v_story_id IS NULL THEN
      RAISE EXCEPTION 'story_id is required';
    END IF;

    v_conversation_id := NULLIF(p_payload ->> 'conversation_id', '')::uuid;

    IF v_user_id IS NOT NULL THEN
      v_is_admin_staff := public.is_admin_or_staff(v_user_id);

      SELECT EXISTS (
        SELECT 1
        FROM public.partner_stories ps
        LEFT JOIN public.partner_profiles pp ON pp.id = ps.partner_id
        WHERE ps.id = v_story_id
          AND (
            ps.user_id = v_user_id
            OR pp.user_id = v_user_id
            OR v_is_admin_staff
          )
      ) INTO v_has_story_access;

      IF NOT v_has_story_access THEN
        RAISE EXCEPTION 'Unauthorized: Story access denied';
      END IF;
    END IF;

    IF v_conversation_id IS NOT NULL AND v_user_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1
        FROM public.chat_conversations cc
        WHERE cc.id = v_conversation_id
          AND cc.user_id = v_user_id
      ) THEN
        RAISE EXCEPTION 'Conversation does not belong to user';
      END IF;
    END IF;

    INSERT INTO public.story_ai_sessions (
      context_snapshot,
      conversation_id,
      session_type,
      story_id,
      tokens_used
    )
    VALUES (
      COALESCE(p_payload -> 'context_snapshot', '{}'::jsonb),
      v_conversation_id,
      COALESCE(NULLIF(p_payload ->> 'session_type', ''), 'consultation'),
      v_story_id,
      COALESCE(NULLIF(p_payload ->> 'tokens_used', '')::integer, 0)
    )
    RETURNING id INTO v_id;

    INSERT INTO public.audit_journal (
      action_type,
      area,
      details,
      entity_id,
      entity_type,
      severity,
      summary,
      user_id
    )
    VALUES (
      'ai_interaction',
      'partner_portal',
      jsonb_build_object(
        'action', NULLIF(p_payload ->> 'action', ''),
        'conversation_id', v_conversation_id,
        'health_data_included', COALESCE((p_payload ->> 'health_data_included')::boolean, false),
        'partner_access_level', NULLIF(p_payload ->> 'partner_access_level', ''),
        'response_time_ms', COALESCE(NULLIF(p_payload ->> 'response_time_ms', '')::integer, 0),
        'story_id', v_story_id,
        'tokens_used', COALESCE(NULLIF(p_payload ->> 'tokens_used', '')::integer, 0)
      ),
      v_id::text,
      'story_ai_session',
      'low',
      COALESCE(NULLIF(p_payload ->> 'summary', ''), 'AI story consultation'),
      v_user_id
    );

    RETURN jsonb_build_object(
      'id', v_id,
      'ok', true,
      'conversation_id', v_conversation_id
    );
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_story_ai(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edge_story_ai(text, jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.edge_story_ai(text, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/ensure_feedback_training_dataset.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- Function: ensure_feedback_training_dataset
-- Purpose: Ensure an org-scoped ALE feedback training dataset exists
-- Part of: AISHA Learning Engine (ALE) — event-driven feedback pipeline
-- =============================================================================

CREATE OR REPLACE FUNCTION public.ensure_feedback_training_dataset(
  p_domain_tags text[] DEFAULT '{}'::text[],
  p_org_id uuid DEFAULT NULL,
  p_story_id uuid DEFAULT NULL,
  p_name text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_created boolean := false;
  v_dataset_id uuid;
  v_dataset_name text;
  v_is_service_role boolean := false;
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  v_is_service_role := COALESCE(
    (current_setting('request.jwt.claims', true)::jsonb ->> 'role') = 'service_role',
    false
  );

  IF NOT v_is_service_role AND (v_user_id IS NULL OR NOT public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Permission denied: admin or staff required';
  END IF;

  SELECT td.id, td.name
  INTO v_dataset_id, v_dataset_name
  FROM public.training_datasets td
  WHERE td.source_type = 'feedback'
    AND td.metadata ->> 'pipeline' = 'ale_feedback'
    AND (
      (p_org_id IS NULL AND td.org_id IS NULL)
      OR td.org_id = p_org_id
    )
  ORDER BY td.created_at DESC
  LIMIT 1;

  IF v_dataset_id IS NULL THEN
    v_created := true;
    v_dataset_name := COALESCE(
      p_name,
      CASE
        WHEN p_org_id IS NULL THEN 'ALE Feedback Dataset (Global)'
        ELSE 'ALE Feedback Dataset (' || left(p_org_id::text, 8) || ')'
      END
    );

    INSERT INTO public.training_datasets (
      org_id,
      name,
      description,
      source_type,
      format,
      domain_tags,
      status,
      metadata,
      created_by
    ) VALUES (
      p_org_id,
      v_dataset_name,
      'Auto-managed dataset for AISHA feedback loop. Mixed SFT + DPO examples.',
      'feedback',
      'instruction',
      COALESCE(p_domain_tags, '{}'::text[]),
      'curating',
      jsonb_build_object(
        'pipeline', 'ale_feedback',
        'mixed_formats', jsonb_build_array('instruction', 'preference_pair'),
        'last_story_id', p_story_id,
        'auto_managed', true
      ),
      v_user_id
    )
    RETURNING id, name INTO v_dataset_id, v_dataset_name;
  ELSE
    UPDATE public.training_datasets td
    SET
      domain_tags = (
        SELECT COALESCE(array_agg(DISTINCT x), '{}'::text[])
        FROM unnest(COALESCE(td.domain_tags, '{}'::text[]) || COALESCE(p_domain_tags, '{}'::text[])) AS x
      ),
      metadata = td.metadata || jsonb_build_object('last_story_id', p_story_id, 'auto_managed', true)
    WHERE td.id = v_dataset_id;
  END IF;

  RETURN jsonb_build_object(
    'dataset_id', v_dataset_id,
    'name', v_dataset_name,
    'created', v_created,
    'org_id', p_org_id,
    'story_id', p_story_id
  );
END;
$$;

REVOKE ALL ON FUNCTION public.ensure_feedback_training_dataset(text[], uuid, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.ensure_feedback_training_dataset(text[], uuid, uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ensure_feedback_training_dataset(text[], uuid, uuid, text) TO service_role;

COMMENT ON FUNCTION public.ensure_feedback_training_dataset(text[], uuid, uuid, text) IS
  'Ensure an ALE feedback dataset exists per org. Used by n8n feedback processor before process_feedback_to_training.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/estimate_effort.sql
-- -----------------------------------------------------------------------------

-- Function: estimate_effort

CREATE OR REPLACE FUNCTION public.estimate_effort(p_session_id uuid, p_task_description text, p_affected_files text[], p_complexity_factors jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_session RECORD;
  v_breakdown jsonb := '[]'::jsonb;
  v_risks jsonb := '[]'::jsonb;
  v_file_count int;
  v_base_hours numeric;
  v_confidence text;
  v_decision_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  -- Verify session ownership
  SELECT * INTO v_session
  FROM moderation_sessions ms
  WHERE ms.id = p_session_id AND (ms.user_id = v_user_id OR is_admin_or_staff());

  IF v_session IS NULL THEN
    RAISE EXCEPTION 'Session not found or access denied' USING ERRCODE = 'P0002';
  END IF;

  -- Basic effort heuristic based on file count and complexity
  v_file_count := COALESCE(array_length(p_affected_files, 1), 0);

  -- Base estimate: ~1h per file, adjusted by session expertise
  v_base_hours := GREATEST(0.5, v_file_count * 1.0);

  -- Adjust by expertise level (beginners take ~2x longer)
  v_base_hours := v_base_hours * CASE v_session.expertise_level
    WHEN 'beginner' THEN 2.0
    WHEN 'intermediate' THEN 1.5
    WHEN 'advanced' THEN 1.0
    WHEN 'expert' THEN 0.8
  END;

  -- Adjust by complexity factors
  IF (p_complexity_factors->>'has_migration')::boolean IS TRUE THEN
    v_base_hours := v_base_hours + 1.5;
    v_breakdown := v_breakdown || jsonb_build_array(
      jsonb_build_object('item', 'Database migration', 'hours', 1.5)
    );
  END IF;

  IF (p_complexity_factors->>'has_rpc')::boolean IS TRUE THEN
    v_base_hours := v_base_hours + 1.0;
    v_breakdown := v_breakdown || jsonb_build_array(
      jsonb_build_object('item', 'RPC function implementation', 'hours', 1.0)
    );
  END IF;

  IF (p_complexity_factors->>'has_tests')::boolean IS TRUE THEN
    v_base_hours := v_base_hours + v_file_count * 0.5;
    v_breakdown := v_breakdown || jsonb_build_array(
      jsonb_build_object('item', 'Test implementation', 'hours', v_file_count * 0.5)
    );
  END IF;

  -- Confidence based on info completeness
  v_confidence := CASE
    WHEN v_file_count > 0 AND p_task_description IS NOT NULL AND p_complexity_factors != '{}'::jsonb THEN 'high'
    WHEN v_file_count > 0 OR p_task_description IS NOT NULL THEN 'medium'
    ELSE 'low'
  END;

  -- Risk assessment
  IF v_file_count > 10 THEN
    v_risks := v_risks || jsonb_build_array(
      jsonb_build_object('risk', 'Large changeset', 'impact', 'high', 'mitigation', 'Consider splitting into smaller PRs')
    );
  END IF;

  -- Add file work to breakdown
  IF v_file_count > 0 THEN
    v_breakdown := jsonb_build_array(
      jsonb_build_object('item', 'Code changes (' || v_file_count || ' files)', 'hours', v_file_count * 1.0)
    ) || v_breakdown;
  END IF;

  -- Record decision
  INSERT INTO moderation_decisions (session_id, decision_type, severity, context, recommendation, evidence)
  VALUES (
    p_session_id, 'estimation_adjustment', 'info',
    jsonb_build_object(
      'task', p_task_description,
      'files', to_jsonb(p_affected_files),
      'complexity', p_complexity_factors
    ),
    'Effort estimate: ~' || round(v_base_hours, 1) || ' hours (' || v_confidence || ' confidence)',
    jsonb_build_object('breakdown', v_breakdown, 'risks', v_risks)
  )
  RETURNING id INTO v_decision_id;

  RETURN jsonb_build_object(
    'decision_id', v_decision_id,
    'estimate_hours', round(v_base_hours, 1),
    'confidence', v_confidence,
    'breakdown', v_breakdown,
    'risks', v_risks,
    'expertise_factor', v_session.expertise_level
  );
END;
$function$;

REVOKE ALL ON FUNCTION estimate_effort(uuid, text, text[], jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION estimate_effort(uuid,text,text[],jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION estimate_effort(uuid,text,text[],jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/evaluate_test_strategy.sql
-- -----------------------------------------------------------------------------

-- Function: evaluate_test_strategy

CREATE OR REPLACE FUNCTION public.evaluate_test_strategy(p_session_id uuid, p_hook_name text, p_file_path text, p_test_file_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_session RECORD;
  v_chain jsonb := '[]'::jsonb;
  v_gaps jsonb := '[]'::jsonb;
  v_recommendations jsonb := '[]'::jsonb;
  v_test_rules jsonb;
  v_decision_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  -- Verify session ownership
  SELECT * INTO v_session
  FROM moderation_sessions ms
  WHERE ms.id = p_session_id AND (ms.user_id = v_user_id OR is_admin_or_staff());

  IF v_session IS NULL THEN
    RAISE EXCEPTION 'Session not found or access denied' USING ERRCODE = 'P0002';
  END IF;

  -- Load testing rules
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'slug', er.slug,
      'title', er.title,
      'ai_instructions', er.ai_instructions
    )
  ), '[]'::jsonb)
  INTO v_test_rules
  FROM expert_rules er
  WHERE er.status = 'published'
    AND er.category IN ('testing', 'quality')
  LIMIT 15;

  -- Build test chain (what tests should exist)
  v_chain := jsonb_build_array(
    jsonb_build_object('step', 'unit', 'description', 'Unit tests for ' || p_hook_name, 'required', true),
    jsonb_build_object('step', 'mock_validation', 'description', 'Mock matches implementation pattern', 'required', true),
    jsonb_build_object('step', 'error_handling', 'description', 'Error cases covered', 'required', true),
    jsonb_build_object('step', 'edge_cases', 'description', 'Edge cases and boundary conditions', 'required', false)
  );

  -- Identify gaps (AI will refine these based on actual code analysis)
  IF p_test_file_path IS NULL THEN
    v_gaps := jsonb_build_array(
      jsonb_build_object(
        'type', 'missing_test_file',
        'description', 'No test file found for ' || p_hook_name,
        'severity', 'error'
      )
    );
  END IF;

  -- Build recommendations
  v_recommendations := jsonb_build_array(
    jsonb_build_object(
      'type', 'mock_pattern',
      'description', 'Verify mock matches actual RPC calls (rpc-only pattern)',
      'priority', 'high'
    ),
    jsonb_build_object(
      'type', 'vi_mocked',
      'description', 'Use vi.mocked() consistently, avoid double tracking',
      'priority', 'medium'
    )
  );

  -- Record decision
  INSERT INTO moderation_decisions (session_id, decision_type, severity, context, recommendation, evidence)
  VALUES (
    p_session_id, 'test_gap',
    CASE WHEN p_test_file_path IS NULL THEN 'error' ELSE 'info' END,
    jsonb_build_object('hook_name', p_hook_name, 'file_path', p_file_path, 'test_file_path', p_test_file_path),
    'Evaluate test strategy for ' || p_hook_name,
    jsonb_build_object('rules', v_test_rules)
  )
  RETURNING id INTO v_decision_id;

  RETURN jsonb_build_object(
    'decision_id', v_decision_id,
    'chain', v_chain,
    'gaps', v_gaps,
    'recommendations', v_recommendations,
    'test_rules', v_test_rules
  );
END;
$function$;

REVOKE ALL ON FUNCTION evaluate_test_strategy(uuid, text, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION evaluate_test_strategy(uuid,text,text,text) TO authenticated;
GRANT EXECUTE ON FUNCTION evaluate_test_strategy(uuid,text,text,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/execute_improvement_proposal_rollback_admin.sql
-- -----------------------------------------------------------------------------

-- Function: execute_improvement_proposal_rollback_admin
-- Closes L5: EXECUTES a rollback of an APPLIED improvement proposal by restoring agent_catalog from
-- the pre-apply snapshot captured in improvement_proposals.current_value (written by
-- approve_improvement_proposal_admin at apply time). Mirrors that function's auth/lock/audit pattern.
-- Until now the loop only PROPOSED a rollback (advisory); this is the gated executor.
--
-- Guarded: admin/staff only. Only an 'applied' proposal with a non-empty current_value snapshot and an
-- agent_slug can be rolled back. Sets status='rolled_back'. Idempotent-ish: a non-applied proposal errors.
-- @security: admin/staff (mirrors approve_improvement_proposal_admin — human/gated, NOT service_role auto).

CREATE OR REPLACE FUNCTION public.execute_improvement_proposal_rollback_admin(
  p_proposal_id uuid DEFAULT NULL,
  p_review_note text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_proposal record;
  v_cv       jsonb;
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = 'P0003';
  END IF;
  IF p_proposal_id IS NULL THEN
    RAISE EXCEPTION 'proposal_id is required' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_proposal
  FROM improvement_proposals
  WHERE id = p_proposal_id AND status = 'applied'
  FOR UPDATE;

  IF v_proposal IS NULL THEN
    RAISE EXCEPTION 'Proposal not found or not in applied status (only applied proposals can be rolled back)'
      USING ERRCODE = 'P0002';
  END IF;

  v_cv := COALESCE(v_proposal.current_value, '{}'::jsonb);
  IF v_proposal.agent_slug IS NULL OR v_cv = '{}'::jsonb THEN
    RAISE EXCEPTION 'No pre-apply snapshot to restore (current_value empty or agent_slug NULL)'
      USING ERRCODE = 'P0002';
  END IF;

  -- Restore the agent to its pre-apply state from the snapshot (symmetric to the apply UPDATEs).
  UPDATE agent_catalog
  SET default_model   = COALESCE(v_cv->>'default_model', default_model),
      model_overrides = COALESCE(v_cv->'model_overrides', model_overrides),
      allowed_tools   = COALESCE(
        CASE WHEN v_cv ? 'allowed_tools'
          THEN ARRAY(SELECT jsonb_array_elements_text(v_cv->'allowed_tools')) ELSE NULL END,
        allowed_tools),
      denied_tools    = COALESCE(
        CASE WHEN v_cv ? 'denied_tools'
          THEN ARRAY(SELECT jsonb_array_elements_text(v_cv->'denied_tools')) ELSE NULL END,
        denied_tools),
      updated_at      = now()
  WHERE slug = v_proposal.agent_slug;

  UPDATE improvement_proposals
  SET status      = 'rolled_back',
      review_note = COALESCE(p_review_note, review_note),
      reviewed_by = auth.uid(),
      reviewed_at = now()
  WHERE id = p_proposal_id;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'IMPROVEMENT_PROPOSAL_ROLLED_BACK', jsonb_build_object(
    'agent_slug', v_proposal.agent_slug,
    'proposal_id', p_proposal_id,
    'proposal_type', v_proposal.proposal_type,
    'restored_from', 'current_value'
  ));

  RETURN jsonb_build_object(
    'proposal_id', p_proposal_id,
    'agent_slug', v_proposal.agent_slug,
    'status', 'rolled_back'
  );
END;
$$;

COMMENT ON FUNCTION public.execute_improvement_proposal_rollback_admin(uuid, text) IS
  'L5 gated rollback EXECUTOR: restores agent_catalog from the pre-apply snapshot in improvement_proposals.current_value, sets status=rolled_back, audits. admin/staff only (mirrors approve_improvement_proposal_admin).';

REVOKE ALL ON FUNCTION public.execute_improvement_proposal_rollback_admin(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.execute_improvement_proposal_rollback_admin(uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.execute_improvement_proposal_rollback_admin(uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/extract_training_pairs_from_kb.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- Function: extract_training_pairs_from_kb
-- Purpose: Extract instruction/response training pairs from knowledge base
-- Part of: AISHA Learning Engine (ALE) — Phase 1 (L2 Data Curation)
-- =============================================================================

CREATE OR REPLACE FUNCTION public.extract_training_pairs_from_kb(
  p_dataset_id uuid,
  p_domain_tags text[] DEFAULT '{}'::text[],
  p_limit integer DEFAULT 500,
  p_org_id uuid DEFAULT NULL,
  p_source_types text[] DEFAULT ARRAY['knowledge_items', 'expert_rules']
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid;
  v_inserted_count integer := 0;
  v_skipped_count integer := 0;
  v_ki_count integer := 0;
  v_er_count integer := 0;
  rec record;
BEGIN
  -- Auth check: admin/staff only
  v_user_id := auth.uid();
  IF v_user_id IS NULL OR NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Permission denied: admin or staff required';
  END IF;

  -- Validate dataset exists
  IF NOT EXISTS (SELECT 1 FROM public.training_datasets WHERE id = p_dataset_id) THEN
    RAISE EXCEPTION 'Dataset not found: %', p_dataset_id;
  END IF;

  -- -------------------------------------------------------------------------
  -- Extract from knowledge_items (body_markdown + ai_instructions → pairs)
  -- -------------------------------------------------------------------------
  IF 'knowledge_items' = ANY(p_source_types) THEN
    FOR rec IN
      SELECT
        ki.id,
        ki.title,
        ki.summary,
        ki.body_markdown,
        ki.ai_instructions,
        ki.ai_context_tags
      FROM public.knowledge_items ki
      WHERE ki.status = 'active'
        AND ki.is_verified = true
        AND (array_length(p_domain_tags, 1) IS NULL OR ki.ai_context_tags && p_domain_tags)
        -- Skip already-extracted items for this dataset
        AND NOT EXISTS (
          SELECT 1 FROM public.training_examples te
          WHERE te.dataset_id = p_dataset_id
            AND te.source_type = 'knowledge_items'
            AND te.source_id = ki.id
        )
      ORDER BY ki.updated_at DESC
      LIMIT p_limit
    LOOP
      -- Pair 1: "Explain {title}" → body_markdown (knowledge instruction)
      IF rec.body_markdown IS NOT NULL AND length(rec.body_markdown) > 50 THEN
        INSERT INTO public.training_examples (
          dataset_id, example_type, instruction, input, output,
          domain_tags, source_id, source_type, metadata
        ) VALUES (
          p_dataset_id,
          'instruction',
          'Explain the following topic according to our knowledge base: ' || rec.title,
          COALESCE(rec.summary, ''),
          rec.body_markdown,
          COALESCE(rec.ai_context_tags, '{}'::text[]),
          rec.id,
          'knowledge_items',
          jsonb_build_object('extraction_type', 'kb_explain', 'title', rec.title)
        );
        v_ki_count := v_ki_count + 1;
      ELSE
        v_skipped_count := v_skipped_count + 1;
      END IF;

      -- Pair 2: If ai_instructions exist → "How should AI handle {title}?" → ai_instructions
      IF rec.ai_instructions IS NOT NULL AND length(rec.ai_instructions) > 20 THEN
        INSERT INTO public.training_examples (
          dataset_id, example_type, instruction, input, output,
          domain_tags, source_id, source_type, metadata
        ) VALUES (
          p_dataset_id,
          'instruction',
          'What are the AI guidelines for: ' || rec.title || '?',
          '',
          rec.ai_instructions,
          COALESCE(rec.ai_context_tags, '{}'::text[]),
          rec.id,
          'knowledge_items',
          jsonb_build_object('extraction_type', 'kb_ai_instructions', 'title', rec.title)
        );
        v_ki_count := v_ki_count + 1;
      END IF;
    END LOOP;
  END IF;

  -- -------------------------------------------------------------------------
  -- Extract from expert_rules (rule → ai_instructions pairs)
  -- -------------------------------------------------------------------------
  IF 'expert_rules' = ANY(p_source_types) THEN
    FOR rec IN
      SELECT
        er.id,
        er.title,
        er.category,
        er.body_markdown,
        er.ai_instructions,
        er.ai_context_tags
      FROM public.expert_rules er
      WHERE er.status = 'published'
        AND (array_length(p_domain_tags, 1) IS NULL OR er.ai_context_tags && p_domain_tags)
        AND NOT EXISTS (
          SELECT 1 FROM public.training_examples te
          WHERE te.dataset_id = p_dataset_id
            AND te.source_type = 'expert_rules'
            AND te.source_id = er.id
        )
      ORDER BY er.updated_at DESC
      LIMIT p_limit
    LOOP
      -- Expert rule → compliance instruction pair
      IF rec.ai_instructions IS NOT NULL AND length(rec.ai_instructions) > 20 THEN
        INSERT INTO public.training_examples (
          dataset_id, example_type, instruction, input, output,
          system_prompt, domain_tags, source_id, source_type, metadata
        ) VALUES (
          p_dataset_id,
          'instruction',
          'What is the expert rule for "' || rec.title || '" in category "' || COALESCE(rec.category, 'general') || '"?',
          COALESCE(rec.body_markdown, ''),
          rec.ai_instructions,
          'You are a compliance-aware AI assistant that follows organizational expert rules strictly.',
          COALESCE(rec.ai_context_tags, '{}'::text[]),
          rec.id,
          'expert_rules',
          jsonb_build_object('extraction_type', 'rule_compliance', 'category', rec.category)
        );
        v_er_count := v_er_count + 1;
      ELSE
        v_skipped_count := v_skipped_count + 1;
      END IF;
    END LOOP;
  END IF;

  v_inserted_count := v_ki_count + v_er_count;

  -- Audit
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'ALE_KB_EXTRACTION',
    jsonb_build_object(
      'dataset_id', p_dataset_id,
      'inserted', v_inserted_count,
      'skipped', v_skipped_count,
      'from_knowledge_items', v_ki_count,
      'from_expert_rules', v_er_count,
      'domain_tags', p_domain_tags
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'inserted_count', v_inserted_count,
    'skipped_count', v_skipped_count,
    'knowledge_items_count', v_ki_count,
    'expert_rules_count', v_er_count
  );
END;
$$;

-- Permissions: admin/staff only
REVOKE ALL ON FUNCTION public.extract_training_pairs_from_kb(uuid, text[], integer, uuid, text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.extract_training_pairs_from_kb(uuid, text[], integer, uuid, text[]) TO authenticated;

COMMENT ON FUNCTION public.extract_training_pairs_from_kb(uuid, text[], integer, uuid, text[]) IS
  'Extract instruction/response training pairs from knowledge_items and expert_rules into a training dataset. Admin/staff only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_detect_agent_runaway.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_detect_agent_runaway
-- Description: GOAL 2 — the autonomous supervisor analysis pass. Scans LIVE agent
--   sessions (agent_live_sessions × ai_trace_events cost rollup) and, for any run
--   over the runtime / token / cost thresholds, queues a Dirigent nudge (advisory,
--   drained on the next hook by the relay). Idempotent per session within the
--   nudge window. Thresholds are ARGUMENTS (operator/config-driven — no policy
--   baked as a literal). Returns the number of nudges created.
--   Closes the plan's GOAL 2 (something actually analyses the ingested activity)
--   and the "Automatický supervisor trigger" (driven by WF_DIRIGENT_AGENT_WATCHDOG).
-- Security: SECURITY DEFINER, read-mostly + queue insert. service_role + authenticated.

-- A currency-suffixed name (`*_usd`) was removed from this function's signature.
-- The TYPES did not change, so CREATE OR REPLACE matches the deployed function and
-- Postgres refuses to rename in place ("cannot change name of input parameter", or
-- "cannot change return type" when the renamed name is a RETURNS TABLE column).
-- DROP-first is the convention used elsewhere in this directory; the REVOKE/GRANT
-- below re-applies whatever privileges the drop clears.
DROP FUNCTION IF EXISTS public.fn_detect_agent_runaway(integer, bigint, numeric);

CREATE OR REPLACE FUNCTION public.fn_detect_agent_runaway(
  p_max_runtime_minutes int     DEFAULT 15,
  p_max_tokens          bigint  DEFAULT NULL,
  p_max_cost        numeric DEFAULT NULL
)
RETURNS int
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_count    int := 0;
  v_row      record;
  v_reason   text;
  v_user_id  uuid := auth.uid();
BEGIN
  -- Supervisor-scope: this pass enumerates ALL users' live sessions, so it is
  -- restricted to admins/staff and the service_role watchdog. A regular
  -- authenticated caller must not be able to scan other users' agent activity.
  -- Robust allow-list (COALESCE guards the NULL-role / NULL-uid edges).
  IF NOT (
       COALESCE(current_setting('request.jwt.claims', true)::jsonb->>'role', '') = 'service_role'
       OR COALESCE(public.is_admin_or_staff(v_user_id), false)
     )
  THEN
    RAISE EXCEPTION 'fn_detect_agent_runaway requires admin/staff or service_role'
      USING ERRCODE = '42501';
  END IF;

  FOR v_row IN
    -- Cost rollup uses the SAME canonical predicate as list_active_agent_sessions
    -- and finish_ai_run: ai_trace_events.run_id = the session's per-session ai_run
    -- (agent_live_sessions.ai_run_id). Joining on session_id via request_summary
    -- would be fragile (relays don't guarantee that key) and silently zero-out the
    -- token/cost thresholds.
    SELECT s.session_id,
           s.story_id,
           s.source,
           s.agent_run_id,
           (EXTRACT(EPOCH FROM (now() - s.started_at)) / 60)::int AS runtime_min,
           COALESCE(tc.tokens, 0) AS tokens,
           COALESCE(tc.usd, 0)    AS cost
    FROM public.agent_live_sessions s
    LEFT JOIN LATERAL (
      SELECT SUM(COALESCE((ate.cost_json->>'tokens_in')::bigint, 0)
               + COALESCE((ate.cost_json->>'tokens_out')::bigint, 0)) AS tokens,
             SUM(COALESCE((ate.cost_json->>'usd')::numeric, 0))       AS usd
      FROM public.ai_trace_events ate
      WHERE ate.run_id = s.ai_run_id
    ) tc ON s.ai_run_id IS NOT NULL
    WHERE s.current_phase <> 'stopped'
      AND s.updated_at > now() - interval '2 hours'   -- ignore stale rows
  LOOP
    -- Threshold check (first breached dimension wins the message).
    v_reason := NULL;
    IF v_row.runtime_min >= p_max_runtime_minutes THEN
      v_reason := format('running %s min with no Stop', v_row.runtime_min);
    ELSIF p_max_tokens IS NOT NULL AND v_row.tokens >= p_max_tokens THEN
      v_reason := format('%s tokens used (>= %s)', v_row.tokens, p_max_tokens);
    ELSIF p_max_cost IS NOT NULL AND v_row.cost >= p_max_cost THEN
      v_reason := format('$%s spent (>= $%s)', v_row.cost, p_max_cost);
    END IF;
    IF v_reason IS NULL THEN CONTINUE; END IF;

    -- Idempotent: one live watchdog nudge per session within the window.
    IF EXISTS (
      SELECT 1 FROM public.dirigent_nudges n
      WHERE n.event_origin = 'agent_watchdog'
        AND n.consumed_at IS NULL
        AND n.expires_at > now()
        AND n.metadata->>'session_id' = v_row.session_id
    ) THEN CONTINUE; END IF;

    INSERT INTO public.dirigent_nudges (story_id, event_origin, severity, message, metadata, expires_at)
    VALUES (
      v_row.story_id,
      'agent_watchdog',
      'warn',
      format('Agent session %s (%s) %s — consider checking in or stopping the run.',
             v_row.session_id, v_row.source, v_reason),
      jsonb_build_object(
        'session_id', v_row.session_id,
        'agent_run_id', v_row.agent_run_id,
        'runtime_min', v_row.runtime_min,
        'tokens', v_row.tokens,
        'cost', v_row.cost),
      now() + interval '1 hour'
    );
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_detect_agent_runaway(int, bigint, numeric) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_detect_agent_runaway(int, bigint, numeric) TO service_role;
GRANT EXECUTE ON FUNCTION public.fn_detect_agent_runaway(int, bigint, numeric) TO authenticated;

COMMENT ON FUNCTION public.fn_detect_agent_runaway(int, bigint, numeric) IS
  'GOAL 2 autonomous supervisor pass: scans live agent_live_sessions x ai_trace_events cost rollup; queues a Dirigent nudge (event_origin=agent_watchdog) for runs over the runtime/token/cost thresholds, idempotent per session. Returns nudge count. Driven by n8n WF_DIRIGENT_AGENT_WATCHDOG.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_export_training_data.sql
-- -----------------------------------------------------------------------------

/**
 * SQL Function: fn_export_training_data
 *
 * Exports validated training examples from a dataset as JSONL-compatible rows.
 * Used by WF_TRAINING_EXPORT to prepare data for LoRA training.
 *
 * Returns rows formatted for SFT (instruction/output) or DPO (chosen/rejected).
 *
 * @param p_dataset_id - Training dataset to export from
 * @param p_min_quality - Minimum quality_score threshold (default 0.6)
 * @param p_limit - Maximum rows to export (default 10000)
 * @returns TABLE of JSONL-ready rows
 */
CREATE OR REPLACE FUNCTION public.fn_export_training_data(
  p_dataset_id uuid,
  p_limit integer DEFAULT 10000,
  p_min_quality numeric DEFAULT 0.6
)
RETURNS TABLE (
  example_id uuid,
  example_type text,
  jsonl_row jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  -- Auth check: only admin/staff can export training data
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Permission denied: admin or staff role required';
  END IF;

  RETURN QUERY
  SELECT
    te.id AS example_id,
    te.example_type,
    CASE
      WHEN te.example_type = 'preference_pair' THEN
        jsonb_build_object(
          'prompt', te.instruction,
          'chosen', te.chosen,
          'rejected', te.rejected
        )
      ELSE
        jsonb_build_object(
          'instruction', te.instruction,
          'input', COALESCE(te.input, ''),
          'output', te.output
        )
    END AS jsonl_row
  FROM training_examples te
  WHERE te.dataset_id = p_dataset_id
    AND te.is_validated = true
    AND (te.quality_score IS NULL OR te.quality_score >= p_min_quality)
  ORDER BY te.quality_score DESC NULLS LAST
  LIMIT p_limit;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_export_training_data(uuid, integer, numeric) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_export_training_data(uuid, integer, numeric) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_get_ai_budget_status.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_get_ai_budget_status
-- Mission Control governance — read a scope's spend cap status (remaining + state).
-- Used by the admission gate (fn_create_workflow_run), the story-consult route,
-- and the board chip. NO write side-effect (STABLE) — period reset happens only
-- in the consume RPC.
-- Security: SECURITY DEFINER STABLE (read-only). Admin/staff OR story participant.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_get_ai_budget_status(
  p_scope_type text,
  p_scope_id   uuid,
  p_period     text DEFAULT 'lifetime'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_row   public.ai_budget%ROWTYPE;
  v_state text;
  v_pct   numeric := 0;
BEGIN
  -- Authorization: admin/staff see any scope; story participants see their story;
  -- service_role (autonomous control layer) always allowed.
  IF current_setting('role', true) <> 'service_role' AND NOT public.is_admin_or_staff() THEN
    IF NOT (
      p_scope_type = 'story' AND EXISTS (
        SELECT 1 FROM public.story_participants sp
        WHERE sp.story_id = p_scope_id AND sp.user_id = auth.uid()
      )
    ) THEN
      RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Explicit column list (security gate: no SELECT * on real tables).
  -- Order matches public.ai_budget definition for %ROWTYPE compatibility.
  SELECT id, scope_type, scope_id, period, token_limit, cost_limit,
         consumed_tokens, consumed_cost, last_reset_at,
         created_by, created_at, updated_at
  INTO v_row
  FROM public.ai_budget
  WHERE scope_type = p_scope_type
    AND scope_id = p_scope_id
    AND period = p_period;

  -- No cap configured → unlimited (state ok).
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'scope_type',         p_scope_type,
      'scope_id',           p_scope_id,
      'period',             p_period,
      'has_budget',         false,
      'token_limit',        NULL,
      'cost_limit',     NULL,
      'consumed_tokens',    0,
      'consumed_cost',  0,
      'remaining_tokens',   NULL,
      'remaining_cost', NULL,
      'state',              'ok'
    );
  END IF;

  -- State from the most-consumed limited dimension.
  IF v_row.cost_limit IS NOT NULL AND v_row.cost_limit > 0 THEN
    v_pct := GREATEST(v_pct, v_row.consumed_cost / v_row.cost_limit);
  END IF;
  IF v_row.token_limit IS NOT NULL AND v_row.token_limit > 0 THEN
    v_pct := GREATEST(v_pct, v_row.consumed_tokens::numeric / v_row.token_limit);
  END IF;

  v_state := CASE
    WHEN v_pct >= 1   THEN 'stopped'
    WHEN v_pct >= 0.8 THEN 'approaching'
    ELSE 'ok'
  END;

  RETURN jsonb_build_object(
    'scope_type',         v_row.scope_type,
    'scope_id',           v_row.scope_id,
    'period',             v_row.period,
    'has_budget',         true,
    'token_limit',        v_row.token_limit,
    'cost_limit',     v_row.cost_limit,
    'consumed_tokens',    v_row.consumed_tokens,
    'consumed_cost',  v_row.consumed_cost,
    'remaining_tokens',   CASE WHEN v_row.token_limit IS NULL THEN NULL
                               ELSE GREATEST(0, v_row.token_limit - v_row.consumed_tokens) END,
    'remaining_cost', CASE WHEN v_row.cost_limit IS NULL THEN NULL
                               ELSE GREATEST(0, v_row.cost_limit - v_row.consumed_cost) END,
    'state',              v_state
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_get_ai_budget_status(text, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_get_ai_budget_status(text, uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_get_ai_budget_status(text, uuid, text) TO service_role;


