-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_rollback_agent_config.sql
-- -----------------------------------------------------------------------------

-- Function: fn_rollback_agent_config

CREATE OR REPLACE FUNCTION public.fn_rollback_agent_config(p_agent_configuration_id uuid, p_proposal_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT 'auto_rollback_regression'::text, p_target_version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_snapshot jsonb;
  v_current_version integer;
  v_rollback_version integer;
  v_agent_name text;
  v_new_version integer;
BEGIN
  -- Auth check: admin/staff only (or service_role for automated rollbacks)
  IF current_setting('request.jwt.claim.role', true) IS DISTINCT FROM 'service_role'
     AND NOT public.is_admin_or_staff() THEN
    RETURN jsonb_build_object('error', 'Permission denied: admin or staff role required');
  END IF;

  SELECT name, instructions_version
  INTO v_agent_name, v_current_version
  FROM agent_configurations
  WHERE id = p_agent_configuration_id;

  IF v_agent_name IS NULL THEN
    RETURN jsonb_build_object('error', 'Agent configuration not found');
  END IF;

  v_rollback_version := COALESCE(p_target_version, v_current_version - 1);

  IF v_rollback_version < 1 THEN
    RETURN jsonb_build_object('error', 'No previous version to roll back to');
  END IF;

  SELECT configuration_snapshot
  INTO v_snapshot
  FROM agent_configuration_history
  WHERE agent_configuration_id = p_agent_configuration_id
    AND version = v_rollback_version;

  IF v_snapshot IS NULL THEN
    RETURN jsonb_build_object(
      'error', 'Version ' || v_rollback_version || ' not found in history'
    );
  END IF;

  UPDATE agent_configurations SET
    model = COALESCE(v_snapshot->>'model', model),
    model_settings = COALESCE(v_snapshot->'model_settings', model_settings),
    temperature = COALESCE((v_snapshot->>'temperature')::numeric, temperature),
    max_tokens = COALESCE((v_snapshot->>'max_tokens')::integer, max_tokens),
    instructions = COALESCE(v_snapshot->>'instructions', instructions),
    instructions_version = v_current_version + 1,
    tools_config = COALESCE(v_snapshot->'tools_config', tools_config),
    guardrails_config = COALESCE(v_snapshot->'guardrails_config', guardrails_config),
    updated_at = now()
  WHERE id = p_agent_configuration_id
  RETURNING instructions_version INTO v_new_version;

  INSERT INTO agent_configuration_history (
    agent_configuration_id, configuration_snapshot, version, change_summary, changed_at
  ) VALUES (
    p_agent_configuration_id, v_snapshot, v_new_version,
    'ROLLBACK to v' || v_rollback_version || ': ' || p_reason, now()
  );

  IF p_proposal_id IS NOT NULL THEN
    UPDATE improvement_proposals
    SET status = 'rolled_back',
        metadata = metadata || jsonb_build_object(
          'rollback_reason', p_reason,
          'rollback_from_version', v_current_version,
          'rollback_to_version', v_rollback_version,
          'rolled_back_at', now()::text
        ),
        updated_at = now()
    WHERE id = p_proposal_id;
  END IF;

  INSERT INTO audit_journal (user_id, action, metadata) VALUES (
    auth.uid(),
    'AGENT_CONFIG_ROLLBACK',
    jsonb_build_object(
      'agent_configuration_id', p_agent_configuration_id,
      'agent_name', v_agent_name,
      'from_version', v_current_version,
      'to_version', v_rollback_version,
      'new_version', v_new_version,
      'reason', p_reason,
      'proposal_id', p_proposal_id
    )
  );

  RETURN jsonb_build_object(
    'status', 'rolled_back',
    'agent_name', v_agent_name,
    'from_version', v_current_version,
    'to_version', v_rollback_version,
    'new_version', v_new_version,
    'proposal_id', p_proposal_id
  );
END;
$function$

;

REVOKE ALL ON FUNCTION fn_rollback_agent_config(uuid,uuid,text,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_rollback_agent_config(uuid,uuid,text,integer) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_rollback_agent_model.sql
-- -----------------------------------------------------------------------------

-- Function: fn_rollback_agent_model
-- Rollback an agent's model configuration to the state before a proposal was applied.
-- Reads the current_value snapshot from the proposal and restores agent_catalog.
-- Source: migration 20260418130000_fix_self_improvement_foundation.sql

CREATE OR REPLACE FUNCTION public.fn_rollback_agent_model(
  p_agent_slug text,
  p_proposal_id uuid,
  p_reason text DEFAULT 'manual_rollback'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_proposal record;
  v_old_value jsonb;
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized — admin or staff required';
  END IF;

  SELECT id, agent_slug, status, category, current_value, metadata
  INTO v_proposal
  FROM improvement_proposals
  WHERE id = p_proposal_id
    AND agent_slug = p_agent_slug
    AND status = 'approved';

  IF v_proposal IS NULL THEN
    RETURN jsonb_build_object(
      'error', 'No approved proposal found for this agent',
      'proposal_id', p_proposal_id
    );
  END IF;

  v_old_value := COALESCE(v_proposal.current_value, '{}'::jsonb);

  -- Restore previous model configuration
  UPDATE agent_catalog
  SET
    default_model = COALESCE(v_old_value->>'default_model', default_model),
    model_overrides = COALESCE(v_old_value->'model_overrides', model_overrides),
    updated_at = now()
  WHERE slug = p_agent_slug;

  -- Mark proposal as rolled back
  UPDATE improvement_proposals
  SET
    status = 'rolled_back',
    metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
      'rolled_back_at', now(),
      'rollback_reason', p_reason
    ),
    updated_at = now()
  WHERE id = p_proposal_id;

  -- Audit
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'AGENT_MODEL_ROLLBACK',
    jsonb_build_object(
      'agent_slug', p_agent_slug,
      'area', 'ai',
      'proposal_id', p_proposal_id,
      'reason', p_reason,
      'restored_model', v_old_value->>'default_model',
      'severity', 'warning'
    )
  );

  RETURN jsonb_build_object(
    'agent_slug', p_agent_slug,
    'proposal_id', p_proposal_id,
    'restored_model', v_old_value->>'default_model',
    'status', 'rolled_back'
  );
END;
$$;

COMMENT ON FUNCTION fn_rollback_agent_model(text, uuid, text) IS
  'Rollback an agent model configuration to the state before a proposal was applied. '
  'Reads the current_value snapshot from the proposal and restores agent_catalog. '
  'Requires admin or staff role.';

REVOKE ALL ON FUNCTION public.fn_rollback_agent_model(text, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_rollback_agent_model(text, uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_rollback_agent_model(text, uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_verify_audit_chain.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_verify_audit_chain
-- Arguments: p_limit integer DEFAULT NULL (max chain links to verify; NULL = whole chain)
-- Description: Broken-chain detector for the blockchain_audit_records hash chain.
--   Walks the linked list from genesis (previous_hash = 64 zeros) following
--   record_hash -> previous_hash links, recomputing every record_hash via
--   fn_audit_ledger_record_hash. Returns the FIRST broken link (fail-loud, precise):
--     { ok, rows_total, rows_verified, head_hash, first_broken }
--   first_broken reasons:
--     record_hash_mismatch                   — row content no longer matches its stored hash (tampered/corrupt)
--     fork_multiple_rows_share_previous_hash — two rows claim the same predecessor
--     cycle_detected                         — links loop (mass tampering)
--     missing_genesis                        — rows exist but nothing chains from genesis
--     unchained_rows                         — chain ended before covering every row (deleted/unhealed links)
-- Security: SECURITY DEFINER, search_path pinned, admin/staff or service_role only.

CREATE OR REPLACE FUNCTION public.fn_verify_audit_chain(
  p_limit integer DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_total    bigint;
  v_pos      bigint := 0;
  v_prev     text := repeat('0', 64);
  v_ids      uuid[];
  v_row      public.blockchain_audit_records%ROWTYPE;
  v_expected text;
BEGIN
  IF NOT (current_setting('role', true) = 'service_role' OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Access denied: admin/staff or service_role required';
  END IF;

  SELECT count(*) INTO v_total FROM public.blockchain_audit_records;

  LOOP
    EXIT WHEN p_limit IS NOT NULL AND v_pos >= p_limit;

    SELECT array_agg(id) INTO v_ids
    FROM public.blockchain_audit_records
    WHERE previous_hash = v_prev;

    IF v_ids IS NULL THEN
      EXIT; -- end of chain
    END IF;

    IF array_length(v_ids, 1) > 1 THEN
      RETURN jsonb_build_object(
        'ok', false, 'rows_total', v_total, 'rows_verified', v_pos,
        'first_broken', jsonb_build_object(
          'position', v_pos + 1, 'ids', to_jsonb(v_ids),
          'reason', 'fork_multiple_rows_share_previous_hash'));
    END IF;

    IF v_pos >= v_total THEN
      RETURN jsonb_build_object(
        'ok', false, 'rows_total', v_total, 'rows_verified', v_pos,
        'first_broken', jsonb_build_object(
          'position', v_pos + 1, 'ids', to_jsonb(v_ids), 'reason', 'cycle_detected'));
    END IF;

    SELECT * INTO v_row FROM public.blockchain_audit_records WHERE id = v_ids[1];

    v_expected := public.fn_audit_ledger_record_hash(
      v_row.previous_hash, v_row.record_type, v_row.data, v_row.reference_table,
      v_row.reference_id, v_row.token_transaction_id, v_row.correlation_id, v_row.created_at);

    IF v_expected IS DISTINCT FROM v_row.record_hash THEN
      RETURN jsonb_build_object(
        'ok', false, 'rows_total', v_total, 'rows_verified', v_pos,
        'first_broken', jsonb_build_object(
          'position', v_pos + 1, 'id', v_row.id,
          'reason', 'record_hash_mismatch',
          'stored_hash', v_row.record_hash, 'expected_hash', v_expected));
    END IF;

    v_pos := v_pos + 1;
    v_prev := v_row.record_hash;
  END LOOP;

  IF p_limit IS NULL AND v_pos < v_total THEN
    RETURN jsonb_build_object(
      'ok', false, 'rows_total', v_total, 'rows_verified', v_pos,
      'first_broken', jsonb_build_object(
        'position', v_pos + 1,
        'reason', CASE WHEN v_pos = 0 THEN 'missing_genesis' ELSE 'unchained_rows' END,
        'rows_unreached', v_total - v_pos,
        'sample_unchained_ids', (
          SELECT COALESCE(jsonb_agg(s.id), '[]'::jsonb)
          FROM (
            SELECT id FROM public.blockchain_audit_records
            WHERE previous_hash IS NULL OR record_hash IS NULL
            LIMIT 5
          ) s)));
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'rows_total', v_total, 'rows_verified', v_pos,
    'head_hash', CASE WHEN v_pos > 0 THEN v_prev ELSE NULL END,
    'first_broken', NULL);
END;
$function$;

COMMENT ON FUNCTION public.fn_verify_audit_chain(integer) IS
  'Walks the blockchain_audit_records hash chain from genesis, recomputing every link; '
  'returns the first broken link (fail-loud) or ok=true with the chain head hash.';

-- Permissions
REVOKE ALL ON FUNCTION public.fn_verify_audit_chain(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_verify_audit_chain(integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_verify_audit_chain(integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_blockchain_audit_chain_link.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_blockchain_audit_chain_link
-- Arguments: (none - trigger function, BEFORE INSERT ON blockchain_audit_records)
-- Description: Makes the blockchain_audit_records hash chain REAL. On every INSERT it
--   (1) serializes chain writers with a transaction-scoped advisory lock,
--   (2) preserves any caller-supplied record_hash (legacy "payload hash" semantic from
--       edge_blockchain_audit / fn_anchor_decision) into data.payload_hash so nothing is lost,
--   (3) fills previous_hash from the current chain tip (the one row whose record_hash is
--       not referenced by any other row's previous_hash; genesis constant for an empty table),
--   (4) recomputes record_hash deterministically via fn_audit_ledger_record_hash over the
--       row's stored columns INCLUDING previous_hash — the chain link.
--   Fail-loud: if rows exist but no unique tip is found the ledger is unhealed/broken and
--   the INSERT is rejected (run the heals backfill / fn_verify_audit_chain), never silently
--   forked. ON CONFLICT DO NOTHING inserters (fn_queue_blockchain_sync) stay correct: a
--   skipped row never becomes the tip, so the next insert re-reads the same tip.
-- Security: SECURITY DEFINER trigger function, search_path pinned, service_role-only EXECUTE.

CREATE OR REPLACE FUNCTION public.fn_blockchain_audit_chain_link()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_tips text[];
  v_prev text;
BEGIN
  -- Serialize concurrent chain writers; released at COMMIT/ROLLBACK.
  PERFORM pg_advisory_xact_lock(hashtextextended('public.blockchain_audit_records:hash_chain', 0));

  -- Preserve the caller-supplied payload hash (pre-chain record_hash semantic).
  IF NEW.record_hash IS NOT NULL AND (NEW.data IS NULL OR NOT (NEW.data ? 'payload_hash')) THEN
    NEW.data := COALESCE(NEW.data, '{}'::jsonb) || jsonb_build_object('payload_hash', NEW.record_hash);
  END IF;

  -- Current chain tip: the row whose record_hash no other row points at.
  SELECT array_agg(r.record_hash) INTO v_tips
  FROM public.blockchain_audit_records r
  WHERE r.record_hash IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.blockchain_audit_records c
      WHERE c.previous_hash = r.record_hash
    );

  IF v_tips IS NULL THEN
    IF EXISTS (SELECT 1 FROM public.blockchain_audit_records) THEN
      RAISE EXCEPTION 'audit ledger: rows exist but no chain tip found — run the heals backfill (aisha/db/heals.sql) before inserting';
    END IF;
    v_prev := repeat('0', 64); -- genesis
  ELSIF array_length(v_tips, 1) > 1 THEN
    RAISE EXCEPTION 'audit ledger: % chain tips found — chain is broken or unhealed; run fn_verify_audit_chain() / the heals backfill', array_length(v_tips, 1);
  ELSE
    v_prev := v_tips[1];
  END IF;

  NEW.previous_hash := v_prev;
  NEW.record_hash := public.fn_audit_ledger_record_hash(
    NEW.previous_hash,
    NEW.record_type,
    NEW.data,
    NEW.reference_table,
    NEW.reference_id,
    NEW.token_transaction_id,
    NEW.correlation_id,
    NEW.created_at
  );

  RETURN NEW;
END;
$function$;

COMMENT ON FUNCTION public.fn_blockchain_audit_chain_link() IS
  'BEFORE INSERT trigger fn: links each blockchain_audit_records row to the chain tip '
  '(previous_hash) and computes the deterministic chained record_hash. Fail-loud on broken/unhealed chain.';

-- Permissions — trigger function: not callable directly by clients.
REVOKE ALL ON FUNCTION public.fn_blockchain_audit_chain_link() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_blockchain_audit_chain_link() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_verify_audit_journal_entry.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_verify_audit_journal_entry
-- Arguments: p_entry_id uuid
-- Description: Chain-of-custody verification for a single audit_journal entry hash.
--   write_audit_journal (v2) computes blockchain_hash deterministically over the row's
--   STORED columns (action, entity_type, entity_id, created_at, new_data, metadata minus
--   the hash itself) with a 'v2:' prefix — this function recomputes it and reports:
--     verified            — recomputed hash matches the stored hash
--     broken              — stored v2 hash does NOT match the row content (tampered/corrupt)
--     unverifiable_legacy — pre-v2 hash (salted with insert-time now()::text, session-timezone
--                           dependent, and computed over inputs that were not stored 1:1);
--                           decorative by construction, honestly reported as unverifiable
--     no_hash             — row carries no hash at all
--   user_id is deliberately NOT part of the hash: audit_journal.user_id has FK
--   ON DELETE SET NULL (user erasure mutates the row by design).
-- Security: SECURITY DEFINER, search_path pinned, admin/staff or service_role only.

CREATE OR REPLACE FUNCTION public.fn_verify_audit_journal_entry(
  p_entry_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_row      public.audit_journal%ROWTYPE;
  v_stored   text;
  v_expected text;
BEGIN
  IF NOT (current_setting('role', true) = 'service_role' OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Access denied: admin/staff or service_role required';
  END IF;

  SELECT * INTO v_row FROM public.audit_journal WHERE id = p_entry_id;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'audit_journal entry % not found', p_entry_id;
  END IF;

  v_stored := COALESCE(v_row.blockchain_hash, v_row.metadata ->> 'blockchain_hash');

  IF v_stored IS NULL THEN
    RETURN jsonb_build_object('entry_id', p_entry_id, 'state', 'no_hash', 'stored_hash', NULL);
  END IF;

  IF v_stored NOT LIKE 'v2:%' THEN
    RETURN jsonb_build_object('entry_id', p_entry_id, 'state', 'unverifiable_legacy', 'stored_hash', v_stored);
  END IF;

  v_expected := 'v2:' || encode(extensions.digest(convert_to(jsonb_build_object(
    'schema', 'aisha.audit_journal.hash.v2',
    'action', v_row.action,
    'entity_type', v_row.entity_type,
    'entity_id', v_row.entity_id,
    'created_at_epoch_us', (extract(epoch FROM v_row.created_at) * 1000000)::bigint,
    'new_data', v_row.new_data,
    'metadata', COALESCE(v_row.metadata, '{}'::jsonb) - 'blockchain_hash'
  )::text, 'UTF8'), 'sha256'), 'hex');

  RETURN jsonb_build_object(
    'entry_id', p_entry_id,
    'state', CASE WHEN v_expected = v_stored THEN 'verified' ELSE 'broken' END,
    'stored_hash', v_stored,
    'expected_hash', v_expected);
END;
$function$;

COMMENT ON FUNCTION public.fn_verify_audit_journal_entry(uuid) IS
  'Recomputes the deterministic v2 audit_journal blockchain_hash from stored columns; '
  'returns verified/broken/unverifiable_legacy/no_hash (fail-loud on missing entry).';

-- Permissions
REVOKE ALL ON FUNCTION public.fn_verify_audit_journal_entry(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_verify_audit_journal_entry(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_verify_audit_journal_entry(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/generate_expedition_plan.sql
-- -----------------------------------------------------------------------------

-- Function: public.generate_expedition_plan
-- Arguments: p_expedition_date date, p_cut_off_date date
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:29+01:00

CREATE OR REPLACE FUNCTION public.generate_expedition_plan(p_expedition_date date, p_cut_off_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_cut_off DATE;
  v_result JSONB;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT is_admin_or_staff(v_user_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  v_cut_off := COALESCE(p_cut_off_date, p_expedition_date - INTERVAL '3 days');

  SELECT jsonb_build_object(
    'expedition_date', p_expedition_date,
    'cut_off_date', v_cut_off,
    'plans', COALESCE((
      SELECT jsonb_agg(row_to_json(t))
      FROM (
        SELECT 
          p.id AS product_id,
          p.name AS product_name,
          s.id AS study_id,
          s.name AS study_name,
          COUNT(DISTINCT se.user_id) AS member_count,
          COUNT(DISTINCT se.user_id) AS packages_needed
        FROM study_registrations se
        JOIN studies s ON se.study_id = s.id
        LEFT JOIN products p ON true
        WHERE se.status = 'active'
        GROUP BY p.id, p.name, s.id, s.name
      ) t
    ), '[]'::jsonb)
  )
  INTO v_result;

  INSERT INTO audit_journal (user_id, action_type, area, entity_type, summary, severity)
  VALUES (v_user_id, 'create', 'admin', 'expedition_plan', 'Generated expedition plan', 'info');

  RETURN v_result;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.generate_expedition_plan(p_expedition_date date, p_cut_off_date date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.generate_expedition_plan(p_expedition_date date, p_cut_off_date date) TO authenticated;


-- -----------------------------------------------------------------------------
