-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_audience_view_chart_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_audience_view_chart_block
-- Popis: GENERICKÝ 'chart' blok nad ADMIN pohledy publika. Dvojče
--        get_audience_view_table_block — tytéž dvě pojistky, tentýž jmenný
--        prostor, jen jiný tvar dat: body grafu místo řádků tabulky.
--
-- Nahrazuje Appsmith stránky "Tier Funnel" a "Campaign Performance"
-- (appsmith-templates/audience/) plochou extranetu.
--
-- Konfigurace (p_params):
--   view       POVINNÉ  jméno pohledu, MUSÍ odpovídat ^audience_admin_[a-z0-9_]+_v$
--   label_src  POVINNÉ  sloupec pohledu → ChartPoint.label
--   value_src  POVINNÉ  sloupec pohledu → ChartPoint.value (číslo)
--   kind       volitelné 'bar' (default) | 'trend' | 'donut' — UZAVŘENÁ množina,
--                        protože jmenuje renderer; neznámá hodnota => 'bar'
--   pct_src    volitelné sloupec 0–100 → ChartPoint.pct
--   note_src   volitelné sloupec → ChartPoint.note
--   limit      volitelné default 20, strop 100
--   order_by   volitelné jméno sloupce; MUSÍ být jeden z *_src výše
--   order_dir  volitelné 'asc' | 'desc' (default 'desc')
--   unit_key   volitelné i18n klíč jednotky
--
-- ⛔ NULA NENÍ NEMĚŘENO. `value` je v kontraktu číslo; řádek, jehož hodnota se
-- na číslo přeložit nedá, se do bodů NEZAHRNE. Dosadit nulu by tvrdilo měření,
-- které nikdo neprovedl — týž důvod, proč KpiTileBlock.value smí být null.
--
-- Bezpečnost: viz get_audience_view_table_block — is_admin_or_staff() jako
-- autorizace a jmenný prostor `audience_admin_*_v` jako druhá, nezávislá
-- pojistka. Klientské parametry v get_block_data PŘEBÍJEJÍ konfiguraci bloku,
-- takže konfigurace hranicí není a být nemůže.
--
-- Poctivá degradace: chybějící konfigurace i nedostatek práv vracejí prázdné
-- body s důvodem v provenance.trace_id, nikdy výjimku.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_audience_view_chart_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_view      text  := nullif(btrim(coalesce(p_params->>'view', '')), '');
  v_label     text  := nullif(btrim(coalesce(p_params->>'label_src', '')), '');
  v_value     text  := nullif(btrim(coalesce(p_params->>'value_src', '')), '');
  v_pct       text  := nullif(btrim(coalesce(p_params->>'pct_src', '')), '');
  v_note      text  := nullif(btrim(coalesce(p_params->>'note_src', '')), '');
  v_kind      text  := lower(coalesce(p_params->>'kind', 'bar'));
  v_limit     int   := least(greatest(coalesce((p_params->>'limit')::int, 20), 1), 100);
  v_order_by  text  := nullif(btrim(coalesce(p_params->>'order_by', '')), '');
  v_order_dir text  := lower(coalesce(p_params->>'order_dir', 'desc'));
  v_now       timestamptz := now();
  v_raw       jsonb;
  v_points    jsonb := '[]'::jsonb;
  v_order_sql text  := '';
BEGIN
  -- 'kind' jmenuje RENDERER, takže je uzavřený. Neznámá hodnota nesmí blok
  -- shodit ani ho nechat zmizet — degraduje na 'bar', který umí každý řez dat.
  IF v_kind NOT IN ('bar', 'trend', 'donut') THEN
    v_kind := 'bar';
  END IF;

  IF NOT public.is_admin_or_staff() THEN
    RETURN jsonb_build_object(
      'data', jsonb_build_object('kind', v_kind, 'points', '[]'::jsonb),
      'provenance', jsonb_build_object(
        'source_slug', 'audience',
        'trace_id', 'audience-chart:unauthorized',
        'freshness_at', v_now));
  END IF;

  IF v_view IS NULL
     OR v_view !~ '^audience_admin_[a-z0-9_]+_v$'
     OR to_regclass('public.' || quote_ident(v_view)) IS NULL
     OR v_label IS NULL
     OR v_value IS NULL
  THEN
    RETURN jsonb_build_object(
      'data', jsonb_build_object('kind', v_kind, 'points', '[]'::jsonb),
      'provenance', jsonb_build_object(
        'source_slug', 'audience',
        'trace_id', 'audience-chart:missing_config',
        'freshness_at', v_now));
  END IF;

  -- Řazení smí ukázat jen na sloupec, který už je v konfiguraci deklarovaný —
  -- jinak by `order_by` byl druhá cesta, jak do dotazu propašovat identifikátor.
  IF v_order_by IS NOT NULL
     AND v_order_by IN (v_label, v_value, coalesce(v_pct, v_label), coalesce(v_note, v_label))
  THEN
    v_order_sql := format('order by %I %s nulls last',
                          v_order_by,
                          CASE WHEN v_order_dir = 'asc' THEN 'asc' ELSE 'desc' END);
  END IF;

  EXECUTE format(
    'select coalesce(jsonb_agg(to_jsonb(t) order by t.__rn), ''[]''::jsonb)'
    || ' from (select v.*, row_number() over (%s) as __rn from public.%I v limit %s) t',
    v_order_sql, v_view, v_limit)
  INTO v_raw;

  SELECT coalesce(jsonb_agg(pt ORDER BY ord), '[]'::jsonb)
    INTO v_points
  FROM (
    SELECT (row_value->>'__rn')::bigint AS ord,
           jsonb_strip_nulls(jsonb_build_object(
             'label', coalesce(row_value->>v_label, ''),
             'value', to_jsonb(nullif(row_value->>v_value, '')::numeric),
             'pct',   CASE WHEN v_pct  IS NULL THEN NULL
                           ELSE to_jsonb(nullif(row_value->>v_pct, '')::numeric) END,
             'note',  CASE WHEN v_note IS NULL THEN NULL
                           ELSE to_jsonb(nullif(row_value->>v_note, '')) END)) AS pt
    FROM jsonb_array_elements(v_raw) AS row_value
    -- Řádek bez čitelné hodnoty se vynechá — viz „nula není neměřeno" výše.
    WHERE nullif(row_value->>v_value, '') IS NOT NULL
      AND (row_value->>v_value) ~ '^-?[0-9]+(\.[0-9]+)?$'
  ) s;

  -- ⛔ KLÍČE `data` JSOU DOSLOVA VE ZDROJI (naměřeno 2026-09-03, brána
  -- block-data-keys-fit-contract s instančním overlayem). Dřívější
  -- `jsonb_strip_nulls(jsonb_build_object(…))` měla jediný účel — nevydat
  -- `unit_key: null` (kontrakt zná jen string) — jenže bráně tím schovala
  -- klíče; ta pak nemohla dosvědčit, že blok vydává jen to, co kontrakt zná.
  -- Volitelný klíč se přidá jen když má hodnotu; povinné jsou vidět doslova.
  RETURN jsonb_build_object(
    'data', jsonb_build_object(
      'kind', v_kind,
      'points', v_points)
      || CASE
           WHEN nullif(btrim(coalesce(p_params->>'unit_key', '')), '') IS NULL THEN '{}'::jsonb
           ELSE jsonb_build_object('unit_key', btrim(p_params->>'unit_key'))
         END,
    'provenance', jsonb_build_object(
      'source_slug', v_view,
      'trace_id', 'audience-chart:' || v_view,
      'freshness_at', v_now));
END;
$$;

REVOKE ALL ON FUNCTION public.get_audience_view_chart_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_audience_view_chart_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_audience_view_chart_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_audience_view_kpi_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_audience_view_kpi_block
-- Popis: GENERICKÝ 'kpi_tile' blok nad ADMIN pohledy publika. Třetí sourozenec
--        get_audience_view_{table,chart}_block — tytéž dvě pojistky, tentýž
--        jmenný prostor, jen jiný tvar: JEDNO číslo místo řádků nebo bodů.
--
-- ⛔ PROČ VZNIKL (naměřeno 2026-09-07): čísla o komunitě se dala spočítat
-- (agregační pohledy existují) i přinést zvenčí (federační adaptér), ale na
-- ploše je nebylo KUDY ukázat — žádná maska nad jedním číslem neměla producenta.
-- Statistika, kterou nikdo nevidí, je stejně užitečná jako statistika, která
-- neexistuje.
--
-- Konfigurace (p_params):
--   view       POVINNÉ  jméno pohledu, MUSÍ odpovídat ^audience_admin_[a-z0-9_]+_v$
--   value_src  POVINNÉ  sloupec pohledu → data.value
--   agg        volitelné 'count' (default) | 'sum' | 'max' | 'first'
--                        UZAVŘENÁ množina; neznámá hodnota => 'count'
--   where_src  volitelné sloupec pro filtr
--   where_val  volitelné hodnota filtru (rovnost, porovnává se jako text)
--   unit_key   volitelné i18n klíč jednotky
--   state      volitelné 'ok' | 'warning' | 'loss' — STAV JE DEKLARACE, ne odhad:
--                        funkce si ho nedovodí z hodnoty, protože neví, jestli je
--                        větší lepší (počet členů) nebo horší (počet po termínu)
--
-- ⭐ `value: null` = NEMĚŘENO a je to PLATNÁ odpověď (viz maska kpi_tile). Nula by
-- tvrdila měření, které nikdo neprovedl — u „kolik jich přišlo ze zdroje" je to
-- rozdíl mezi „zdroj mlčí" a „zdroj říká nula". Prázdná konfigurace i chybějící
-- právo proto vracejí null, ne 0.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.get_audience_view_kpi_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_view      text := nullif(btrim(coalesce(p_params->>'view', '')), '');
  v_value_src text := nullif(btrim(coalesce(p_params->>'value_src', '')), '');
  v_agg       text := lower(coalesce(nullif(btrim(coalesce(p_params->>'agg','')),''), 'count'));
  v_where_src text := nullif(btrim(coalesce(p_params->>'where_src', '')), '');
  v_where_val text := p_params->>'where_val';
  v_unit_key  text := nullif(btrim(coalesce(p_params->>'unit_key', '')), '');
  v_state     text := lower(coalesce(nullif(btrim(coalesce(p_params->>'state','')),''), 'ok'));
  v_now       timestamptz := now();
  v_value     numeric;
  v_sql       text;
BEGIN
  -- Neznámá hodnota degraduje na výchozí místo pádu: nová deklarace nesmí
  -- shodit starší databázi (táž úvaha jako u `kind` v grafu a `op` ve filtru).
  IF v_agg NOT IN ('count','sum','max','first') THEN v_agg := 'count'; END IF;
  IF v_state NOT IN ('ok','warning','loss')     THEN v_state := 'ok';   END IF;

  -- Prázdná odpověď se skládá na jednom místě, aby se všechny důvody vracely
  -- v témž tvaru — renderer nesmí poznat rozdíl mezi „nemáš právo" a „nic tu
  -- není". Důvod nese trace_id, protože obálka bloku `error` nezná.
  IF NOT public.is_admin_or_staff() THEN
    RETURN jsonb_build_object(
      'data', jsonb_build_object('value', NULL),
      'provenance', jsonb_build_object('source_slug', 'audience',
        'trace_id', 'audience-kpi:unauthorized', 'freshness_at', v_now));
  END IF;

  IF v_view IS NULL OR v_value_src IS NULL
     OR v_view !~ '^audience_admin_[a-z0-9_]+_v$'
     OR to_regclass('public.' || quote_ident(v_view)) IS NULL
  THEN
    RETURN jsonb_build_object(
      'data', jsonb_build_object('value', NULL),
      'provenance', jsonb_build_object('source_slug', coalesce(v_view, 'audience'),
        'trace_id', 'audience-kpi:missing_config', 'freshness_at', v_now));
  END IF;

  -- Identifikátory přes %I, hodnota filtru přes %L — jmenný prostor pohledů
  -- hlídá `view`, ale sloupec i hodnota jsou pořád VSTUP.
  v_sql := format(
    CASE v_agg
      WHEN 'sum'   THEN 'select sum(%1$I)::numeric from public.%2$I'
      WHEN 'max'   THEN 'select max(%1$I)::numeric from public.%2$I'
      WHEN 'first' THEN 'select (%1$I)::numeric from public.%2$I'
      ELSE              'select count(%1$I)::numeric from public.%2$I'
    END, v_value_src, v_view);

  IF v_where_src IS NOT NULL THEN
    v_sql := v_sql || format(' where %I::text = %L', v_where_src, coalesce(v_where_val, ''));
  END IF;
  IF v_agg = 'first' THEN v_sql := v_sql || ' limit 1'; END IF;

  BEGIN
    EXECUTE v_sql INTO v_value;
  EXCEPTION WHEN undefined_column OR invalid_text_representation THEN
    -- Špatně pojmenovaný sloupec je vada KONFIGURACE, ne důvod shodit plochu.
    RETURN jsonb_build_object(
      'data', jsonb_build_object('value', NULL),
      'provenance', jsonb_build_object('source_slug', v_view,
        'trace_id', 'audience-kpi:bad_column', 'freshness_at', v_now));
  END;

  RETURN jsonb_build_object(
    'data', jsonb_strip_nulls(jsonb_build_object(
      'value', v_value,
      'unit_key', v_unit_key,
      'state', v_state)),
    'provenance', jsonb_build_object(
      'source_slug', v_view,
      'trace_id', 'audience-kpi:' || v_agg,
      'freshness_at', v_now));
END;
$$;

REVOKE ALL ON FUNCTION public.get_audience_view_kpi_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_audience_view_kpi_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_audience_view_kpi_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_audience_view_record_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_audience_view_record_block
-- Popis: GENERICKÝ 'record_detail' blok nad ADMIN pohledy publika (ADR-003, K3).
--   Jeden řádek pohledu = jeden záznam: pole, odznaky a citace z KONFIGURACE
--   bloku, identita záznamu z KLIENTSKÉHO parametru (u restricted bloku dorazí
--   jen přes deklaraci `client_params` — get_block_data). Táž stavba a tytéž
--   dvě pojistky jako get_audience_view_table_block: is_admin_or_staff() +
--   jmenný prostor `audience_admin_*_v`.
--
-- Konfigurace (p_params):
--   view       POVINNÉ  ^audience_admin_[a-z0-9_]+_v$
--   key_src    POVINNÉ  sloupec pohledu s identitou záznamu (porovnává se ::text)
--   id_param   volitelné jméno parametru, ve kterém klient posílá identitu
--                        (default 'record_id'; workbench posílá detail_by_kind.param)
--   fields     POVINNÉ  [{key, label_key, src, numeric?}] — pole ke zobrazení
--   badges     volitelné [{src, key_prefix?}] — hodnota sloupce (nebo každý prvek
--                        pole) jako odznak; s key_prefix se z ní stane i18n klíč
--   quote_src  volitelné sloupec s citací (např. poznámka)
--
-- Poctivá degradace: bez práv, bez konfigurace, bez identity nebo bez řádku
-- vrací `record_id: null` s důvodem v provenance.trace_id — nikdy výjimku.
-- Blok „o žádném záznamu" je legitimní stav (klient ještě nic nevybral).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.get_audience_view_record_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_view      text  := nullif(btrim(coalesce(p_params->>'view', '')), '');
  v_key_src   text  := nullif(btrim(coalesce(p_params->>'key_src', '')), '');
  v_id_param  text  := coalesce(nullif(btrim(coalesce(p_params->>'id_param', '')), ''), 'record_id');
  v_fields    jsonb := CASE WHEN jsonb_typeof(p_params->'fields') = 'array' THEN p_params->'fields' ELSE '[]'::jsonb END;
  v_badges    jsonb := CASE WHEN jsonb_typeof(p_params->'badges') = 'array' THEN p_params->'badges' ELSE '[]'::jsonb END;
  v_quote_src text  := nullif(btrim(coalesce(p_params->>'quote_src', '')), '');
  v_id        text;
  v_row       jsonb;
  v_now       timestamptz := now();
BEGIN
  v_id := nullif(btrim(coalesce(p_params->>v_id_param, '')), '');

  IF NOT public.is_admin_or_staff() THEN
    RETURN public.audience_record_block_empty(v_view, 'unauthorized', v_now);
  END IF;
  IF v_view IS NULL
     OR v_view !~ '^audience_admin_[a-z0-9_]+_v$'
     OR to_regclass('public.' || quote_ident(v_view)) IS NULL
     OR v_key_src IS NULL OR v_key_src !~ '^[a-z_][a-z0-9_]*$'
     OR jsonb_array_length(v_fields) = 0 THEN
    RETURN public.audience_record_block_empty(v_view, 'missing_config', v_now);
  END IF;
  IF v_id IS NULL OR length(v_id) > 200 THEN
    RETURN public.audience_record_block_empty(v_view, 'no_record', v_now);
  END IF;

  -- Dynamický je jen identifikátor pohledu a klíčového sloupce (%I); hodnota
  -- identity je literál (%L). Celý řádek se načte jako jsonb a promítne až potom.
  EXECUTE format('select to_jsonb(v) from public.%I v where v.%I::text = %L limit 1',
                 v_view, v_key_src, v_id)
  INTO v_row;
  IF v_row IS NULL THEN
    RETURN public.audience_record_block_empty(v_view, 'not_found', v_now);
  END IF;

  RETURN jsonb_build_object(
    'data', jsonb_strip_nulls(jsonb_build_object(
      'record_id', v_id,
      'badges', coalesce((
        SELECT jsonb_agg(coalesce(b->>'key_prefix', '') || val ORDER BY ord, val)
        FROM jsonb_array_elements(v_badges) WITH ORDINALITY AS bs(b, ord)
        CROSS JOIN LATERAL (
          SELECT e #>> '{}' AS val
          FROM jsonb_array_elements(
                 CASE WHEN jsonb_typeof(v_row->(b->>'src')) = 'array' THEN v_row->(b->>'src')
                      WHEN v_row->(b->>'src') IS NULL OR jsonb_typeof(v_row->(b->>'src')) = 'null' THEN '[]'::jsonb
                      ELSE jsonb_build_array(v_row->(b->>'src')) END) e
          WHERE nullif(btrim(e #>> '{}'), '') IS NOT NULL
        ) vals
        WHERE coalesce(b->>'src', '') ~ '^[a-z_][a-z0-9_]*$'
      ), '[]'::jsonb),
      'fields', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
                 'key',       f->>'key',
                 'label_key', f->>'label_key',
                 'value',     CASE
                                WHEN (f->>'numeric')::boolean IS TRUE
                                  THEN to_jsonb(nullif(v_row->>(f->>'src'), '')::numeric)
                                WHEN jsonb_typeof(v_row->(f->>'src')) = 'array'
                                  THEN to_jsonb((SELECT string_agg(e #>> '{}', ', ')
                                                 FROM jsonb_array_elements(v_row->(f->>'src')) e))
                                WHEN v_row->(f->>'src') IS NULL OR jsonb_typeof(v_row->(f->>'src')) = 'null'
                                  THEN 'null'::jsonb
                                ELSE to_jsonb(v_row->>(f->>'src'))
                              END)
               ORDER BY ord)
        FROM jsonb_array_elements(v_fields) WITH ORDINALITY AS fs(f, ord)
        WHERE nullif(f->>'key', '') IS NOT NULL AND nullif(f->>'label_key', '') IS NOT NULL
      ), '[]'::jsonb),
      'quote', CASE WHEN v_quote_src IS NOT NULL THEN nullif(v_row->>v_quote_src, '') END)),
    'provenance', jsonb_build_object(
      'source_slug', v_view,
      'trace_id', 'audience-record:' || v_view,
      'freshness_at', v_now));
END;
$$;

REVOKE ALL ON FUNCTION public.get_audience_view_record_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_audience_view_record_block(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_audience_view_table_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_audience_view_table_block
-- Popis: GENERICKÝ 'table' blok nad ADMIN pohledy publika. Který pohled a jaké
--        sloupce, říká KONFIGURACE bloku (surface_blocks.source_params, tedy
--        řádek v instančním overlayi) — v kódu není žádná doménová ani
--        instanční hodnota. Táž stavba jako get_twin_events_table_block, jen
--        substrátem nejsou twin události, ale `audience_admin_*_v`.
--
-- Nahrazuje Appsmith stránky "Contact Directory" a "Cohort Manager"
-- (appsmith-templates/audience/) plochou extranetu: tytéž pohledy, tentýž
-- allowlist, ale povrch, který je project-specific a měřitelný.
--
-- Konfigurace (p_params):
--   view      POVINNÉ  jméno pohledu, MUSÍ odpovídat ^audience_admin_[a-z0-9_]+_v$
--   columns   POVINNÉ  pole [{key, label | label_key, src, numeric?}]
--                      src = jméno sloupce pohledu
--   limit     volitelné  default 50, strop 200
--   order_by  volitelné  jméno sloupce; MUSÍ být mezi `src` deklarovaných columns
--   order_dir volitelné  'asc' | 'desc' (default 'desc')
--
-- ── BEZPEČNOST: DVĚ NEZÁVISLÉ POJISTKY ─────────────────────────────────────
-- ⛔ PROČ VÍC NEŽ „je přihlášen". Dispatcher get_block_data slučuje parametry
-- jako `source_params || p_params` — KLIENTSKÉ VYHRÁVAJÍ. Konfigurace bloku
-- tedy NENÍ hranice: volající si `view` přepíše. A `surface_layouts.audience`
-- taky ne — ta filtruje jen list_surface_sections, tedy co se VYPÍŠE; kdo zná
-- block_slug, zavolá get_block_data přímo. (Naměřeno 2026-08-25 na
-- get_twin_events_table_block, který je SECURITY DEFINER „napříč RLS" a jedinou
-- pojistku má `auth.uid() is null` — tedy přihlášen, ne oprávněn.)
--
-- U kontaktních údajů publika je to rozdíl mezi provozem a únikem, proto:
--   1. AUTORIZACE: is_admin_or_staff() — táž hranice, jakou drží každé
--      audience_admin_* RPC (viz audience_admin_create_followup).
--   2. JMENNÝ PROSTOR: `view` smí být jen `audience_admin_*_v`. I kdyby první
--      pojistka jednou padla, dosah je omezen na pohledy, které jsou admin
--      z konstrukce — ne na libovolnou tabulku.
-- Každá pojistka platí sama o sobě; obě dohromady jsou obrana do hloubky.
--
-- Poctivá degradace: chybějící/neplatná konfigurace i nedostatek práv vracejí
-- PRÁZDNÁ data s důvodem v provenance.trace_id — nikdy výjimku. Blok se přizná
-- místo aby zmizel (neshoda se schématem rendereru = tichý zánik bloku).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_audience_view_table_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_view      text  := nullif(btrim(coalesce(p_params->>'view', '')), '');
  v_cols      jsonb := coalesce(p_params->'columns', '[]'::jsonb);
  v_limit     int   := least(greatest(coalesce((p_params->>'limit')::int, 50), 1), 200);
  v_order_by  text  := nullif(btrim(coalesce(p_params->>'order_by', '')), '');
  v_order_dir text  := lower(coalesce(p_params->>'order_dir', 'desc'));
  v_now       timestamptz := now();
  v_raw       jsonb;
  v_rows      jsonb;
  v_order_sql text  := '';
  -- ⭐ (K3, 2026-09-05) řádek jako ZÁZNAM a filtr jako DATA:
  --   row_kind  volitelné  druh záznamu, který řádek představuje (např. 'twin');
  --                        shell podle něj vybere čtečku detailu (detail_by_kind)
  --   id_src    volitelné  sloupec pohledu s identitou řádku → rows[].id
  --   filters   volitelné  [{src, param, op?}] — porovnání sloupce pohledu s
  --                        hodnotou parametru; chybí-li parametr, filtr se
  --                        neuplatní. Hodnota jde do dotazu jako LITERÁL (%L),
  --                        sloupec jako identifikátor (%I) — nic z klienta se
  --                        neskládá do SQL jako text. U restricted bloku
  --                        parametr dorazí jen přes deklaraci client_params
  --                        (get_block_data).
  --                        `op` je OPERÁTOR, tedy DRUH porovnání, ne jméno věci:
  --                          'eq'       (výchozí) rovnost nad textem sloupce
  --                          'contains' hodnota je PRVKEM sloupce s více
  --                                     hodnotami (pole) — bez něj by osa nad
  --                                     štítky či vazbami jen zdobila lištu
  --                                     a nic nefiltrovala (K5, 2026-09-06).
  --                        Neznámý operátor degraduje na 'eq'; nová deklarace
  --                        tak nikdy neshodí starší databázi.
  v_row_kind  text  := nullif(btrim(coalesce(p_params->>'row_kind', '')), '');
  v_id_src    text  := nullif(btrim(coalesce(p_params->>'id_src', '')), '');
  v_filters   jsonb := CASE WHEN jsonb_typeof(p_params->'filters') = 'array'
                            THEN p_params->'filters' ELSE '[]'::jsonb END;
  v_where_sql text  := '';
  v_f         jsonb;
  v_fval      text;
BEGIN
  IF v_row_kind IS NOT NULL AND v_row_kind !~ '^[a-z_][a-z0-9_]*$' THEN v_row_kind := NULL; END IF;
  IF v_id_src   IS NOT NULL AND v_id_src   !~ '^[a-z_][a-z0-9_]*$' THEN v_id_src   := NULL; END IF;
  FOR v_f IN SELECT * FROM jsonb_array_elements(v_filters) LOOP
    v_fval := nullif(btrim(coalesce(p_params->>(v_f->>'param'), '')), '');
    IF v_fval IS NOT NULL
       AND coalesce(v_f->>'src', '') ~ '^[a-z_][a-z0-9_]*$'
       AND length(v_fval) <= 200 THEN
      IF coalesce(v_f->>'op', 'eq') = 'contains' THEN
        -- Sloupec s více hodnotami: ptáme se na PRVEK, ne na rovnost celku.
        -- `::text[]` je explicitní, aby se pole čísel nebo enumů chovalo stejně.
        v_where_sql := v_where_sql || format(' and %L = any(v.%I::text[])', v_fval, v_f->>'src');
      ELSE
        v_where_sql := v_where_sql || format(' and v.%I::text = %L', v_f->>'src', v_fval);
      END IF;
    END IF;
  END LOOP;
  -- Prázdná odpověď se skládá na jednom místě, aby se všechny důvody vracely
  -- v témž tvaru — renderer nesmí poznat rozdíl mezi „nemáš právo" a „nic tu
  -- není". Důvod nese trace_id, protože `error` obálka bloku nezná.
  v_rows := '[]'::jsonb;

  IF NOT public.is_admin_or_staff() THEN
    RETURN jsonb_build_object(
      'data', jsonb_build_object('columns', '[]'::jsonb, 'rows', v_rows),
      'provenance', jsonb_build_object(
        'source_slug', 'audience',
        'trace_id', 'audience-table:unauthorized',
        'freshness_at', v_now));
  END IF;

  IF v_view IS NULL
     OR v_view !~ '^audience_admin_[a-z0-9_]+_v$'
     OR to_regclass('public.' || quote_ident(v_view)) IS NULL
     OR jsonb_array_length(v_cols) = 0
  THEN
    RETURN jsonb_build_object(
      'data', jsonb_build_object('columns', '[]'::jsonb, 'rows', v_rows),
      'provenance', jsonb_build_object(
        'source_slug', 'audience',
        'trace_id', 'audience-table:missing_config',
        'freshness_at', v_now));
  END IF;

  -- Řazení je taky vstup, takže se taky ověřuje: sloupec MUSÍ být mezi
  -- deklarovanými `src`. Bez toho by `order_by` byl druhá cesta, jak do dotazu
  -- dostat cizí identifikátor — jmenný prostor pohledů by hlídal `view`, ale
  -- tudy by prošlo cokoli.
  IF v_order_by IS NOT NULL
     AND EXISTS (SELECT 1 FROM jsonb_array_elements(v_cols) c WHERE c->>'src' = v_order_by)
  THEN
    v_order_sql := format(' order by %I %s nulls last',
                          v_order_by,
                          CASE WHEN v_order_dir = 'asc' THEN 'asc' ELSE 'desc' END);
  END IF;

  -- Celé řádky se načtou jako jsonb a promítnou se AŽ POTOM. Dynamický je tak
  -- jen identifikátor pohledu a ověřený sloupec řazení — ne seznam sloupců.
  EXECUTE format(
    'select coalesce(jsonb_agg(to_jsonb(t) order by t.__rn), ''[]''::jsonb)'
    || ' from (select v.*, row_number() over (%s) as __rn from public.%I v where true%s limit %s) t',
    CASE WHEN v_order_sql = '' THEN '' ELSE substr(v_order_sql, 2) END,
    v_view, v_where_sql, v_limit)
  INTO v_raw;

  SELECT coalesce(jsonb_agg(projected ORDER BY ord), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT (row_value->>'__rn')::bigint AS ord,
           (SELECT jsonb_object_agg(
                     col->>'key',
                     CASE
                       WHEN (col->>'numeric')::boolean IS TRUE
                         THEN to_jsonb(nullif(row_value->>(col->>'src'), '')::numeric)
                       ELSE coalesce(row_value->(col->>'src'), 'null'::jsonb)
                     END)
              FROM jsonb_array_elements(v_cols) col)
           || CASE WHEN v_id_src IS NOT NULL AND nullif(row_value->>v_id_src, '') IS NOT NULL
                   THEN jsonb_build_object('id', row_value->>v_id_src)
                   ELSE '{}'::jsonb END AS projected
    FROM jsonb_array_elements(v_raw) AS row_value
  ) s;

  RETURN jsonb_build_object(
    'data', jsonb_build_object(
      'columns', (SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                    'key', c->>'key', 'label', c->>'label', 'label_key', c->>'label_key')))
                  FROM jsonb_array_elements(v_cols) c),
      'rows', v_rows)
      || CASE WHEN v_row_kind IS NOT NULL THEN jsonb_build_object('row_kind', v_row_kind)
              ELSE '{}'::jsonb END,
    'provenance', jsonb_build_object(
      'source_slug', v_view,
      'trace_id', 'audience-table:' || v_view,
      'freshness_at', v_now));
END;
$$;

-- Grants podle kontraktu get_block_data: nikdy anon. Autorizaci uvnitř drží
-- is_admin_or_staff(), takže `authenticated` je tu vstupenka do funkce, ne
-- k datům.
REVOKE ALL ON FUNCTION public.get_audience_view_table_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_audience_view_table_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_audience_view_table_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_audience_view_timeline_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_audience_view_timeline_block
-- Popis: GENERICKÝ 'timeline' blok nad ADMIN pohledy publika (ADR-003, K3):
--   jeden řádek pohledu = jedna položka osy. Který pohled, který sloupec je
--   „kdy" a který „co", říká konfigurace; koho osa ukazuje, říká filtr
--   z klientského parametru (u restricted bloku jen přes `client_params`).
--   Tytéž dvě pojistky jako sesterské bloky: is_admin_or_staff() + jmenný
--   prostor `audience_admin_*_v`.
--
-- Konfigurace (p_params):
--   view          POVINNÉ  ^audience_admin_[a-z0-9_]+_v$
--   at_src        POVINNÉ  sloupec s časem položky (timestamptz)
--   label_src     volitelné sloupec s textem položky
--   label_key_src volitelné sloupec s i18n klíčem položky (přednost před textem)
--   state_src     volitelné sloupec se stavem; propustí se jen ok|warning|loss
--   kind_src      volitelné sloupec s DRUHEM položky (email / meeting / …).
--                 Projde jen hodnota tvaru štítku (^[a-z][a-z0-9_-]{0,39}$), tedy
--                 strojová hodnota ze zdroje — NE obsah. Kdo sem omylem namíří
--                 sloupec s textem, dostane prázdno, ne odstavec v odznaku.
--   filters       volitelné [{src, param}] — rovnost sloupce s hodnotou parametru
--   limit         volitelné default 50, strop 200
--   order_dir     volitelné 'asc' | 'desc' (default 'desc' — nejnovější nahoře)
--
-- Poctivá degradace: prázdné `items` s důvodem v provenance.trace_id, nikdy výjimka.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.get_audience_view_timeline_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_view      text  := nullif(btrim(coalesce(p_params->>'view', '')), '');
  v_at        text  := nullif(btrim(coalesce(p_params->>'at_src', '')), '');
  v_label     text  := nullif(btrim(coalesce(p_params->>'label_src', '')), '');
  v_label_key text  := nullif(btrim(coalesce(p_params->>'label_key_src', '')), '');
  v_state     text  := nullif(btrim(coalesce(p_params->>'state_src', '')), '');
  v_kind      text  := nullif(btrim(coalesce(p_params->>'kind_src', '')), '');
  v_filters   jsonb := CASE WHEN jsonb_typeof(p_params->'filters') = 'array' THEN p_params->'filters' ELSE '[]'::jsonb END;
  v_limit     int   := least(greatest(coalesce((p_params->>'limit')::int, 50), 1), 200);
  v_dir       text  := CASE WHEN lower(coalesce(p_params->>'order_dir', 'desc')) = 'asc' THEN 'asc' ELSE 'desc' END;
  v_where_sql text  := '';
  v_f         jsonb;
  v_fval      text;
  v_raw       jsonb;
  v_now       timestamptz := now();
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RETURN jsonb_build_object(
      'data', jsonb_build_object('items', '[]'::jsonb),
      'provenance', jsonb_build_object('source_slug', coalesce(v_view, 'audience'),
                                       'trace_id', 'audience-timeline:unauthorized', 'freshness_at', v_now));
  END IF;
  IF v_view IS NULL OR v_view !~ '^audience_admin_[a-z0-9_]+_v$'
     OR to_regclass('public.' || quote_ident(v_view)) IS NULL
     OR v_at IS NULL OR v_at !~ '^[a-z_][a-z0-9_]*$'
     OR (v_label     IS NOT NULL AND v_label     !~ '^[a-z_][a-z0-9_]*$')
     OR (v_label_key IS NOT NULL AND v_label_key !~ '^[a-z_][a-z0-9_]*$')
     OR (v_state     IS NOT NULL AND v_state     !~ '^[a-z_][a-z0-9_]*$')
     OR (v_kind      IS NOT NULL AND v_kind      !~ '^[a-z_][a-z0-9_]*$') THEN
    RETURN jsonb_build_object(
      'data', jsonb_build_object('items', '[]'::jsonb),
      'provenance', jsonb_build_object('source_slug', coalesce(v_view, 'audience'),
                                       'trace_id', 'audience-timeline:missing_config', 'freshness_at', v_now));
  END IF;

  FOR v_f IN SELECT * FROM jsonb_array_elements(v_filters) LOOP
    v_fval := nullif(btrim(coalesce(p_params->>(v_f->>'param'), '')), '');
    IF v_fval IS NOT NULL AND coalesce(v_f->>'src', '') ~ '^[a-z_][a-z0-9_]*$' AND length(v_fval) <= 200 THEN
      v_where_sql := v_where_sql || format(' and v.%I::text = %L', v_f->>'src', v_fval);
    END IF;
  END LOOP;

  EXECUTE format(
    'select coalesce(jsonb_agg(to_jsonb(t) order by t.__rn), ''[]''::jsonb)'
    || ' from (select v.*, row_number() over (order by v.%I %s nulls last) as __rn'
    || '       from public.%I v where v.%I is not null%s limit %s) t',
    v_at, v_dir, v_view, v_at, v_where_sql, v_limit)
  INTO v_raw;

  RETURN jsonb_build_object(
    'data', jsonb_build_object(
      'items', coalesce((
        SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                 'at',        to_char((r->>v_at)::timestamptz AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                 'label',     CASE WHEN v_label IS NOT NULL THEN nullif(r->>v_label, '') END,
                 'label_key', CASE WHEN v_label_key IS NOT NULL THEN nullif(r->>v_label_key, '') END,
                 'state',     CASE WHEN v_state IS NOT NULL AND (r->>v_state) IN ('ok', 'warning', 'loss')
                                   THEN r->>v_state END,
                 -- ⛔ DRUH JE ŠTÍTEK, NE OBSAH (naměřeno 2026-09-07). Osa dvojčete
                 -- veze 1 573 doteků z CRM, kde `content` je předmět e-mailu. Kdyby
                 -- sem šlo namířit libovolný sloupec, propašoval by se OBSAH do
                 -- odznaku — táž vada, jakou jsme odmítli řešit slepením
                 -- „E-mail · Re: …" do popisku. Obsah zůstává obsahem, druh je
                 -- strojová hodnota ze zdroje (ingest ji vyrábí mapou v profilu).
                 -- Proto projde jen hodnota TVARU ŠTÍTKU; delší nebo s mezerami ne.
                 'kind',      CASE WHEN v_kind IS NOT NULL
                                    AND (r->>v_kind) ~ '^[a-z][a-z0-9_-]{0,39}$'
                                   THEN r->>v_kind END))
               ORDER BY (r->>'__rn')::bigint)
        FROM jsonb_array_elements(v_raw) r), '[]'::jsonb)),
    'provenance', jsonb_build_object(
      'source_slug', v_view,
      'trace_id', 'audience-timeline:' || v_view,
      'freshness_at', v_now));
END;
$$;

REVOKE ALL ON FUNCTION public.get_audience_view_timeline_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_audience_view_timeline_block(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_audit_journal.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_audit_journal
-- Arguments: p_limit, p_action_type, p_area, p_severity, p_entity_type, p_start_date, p_end_date, p_search
-- Description: Get audit journal entries with filtering. Admin/staff only.
-- Security: SECURITY DEFINER, admin/staff only.

CREATE OR REPLACE FUNCTION public.get_audit_journal(
  p_limit INTEGER DEFAULT 100,
  p_action_type TEXT DEFAULT NULL,
  p_area TEXT DEFAULT NULL,
  p_severity TEXT DEFAULT NULL,
  p_entity_type TEXT DEFAULT NULL,
  p_start_date TIMESTAMPTZ DEFAULT NULL,
  p_end_date TIMESTAMPTZ DEFAULT NULL,
  p_search TEXT DEFAULT NULL
)
RETURNS TABLE (
  id UUID,
  user_id UUID,
  user_email TEXT,
  user_role TEXT,
  action_type TEXT,
  entity_type TEXT,
  entity_id TEXT,
  area TEXT,
  severity TEXT,
  summary TEXT,
  details JSONB,
  old_values JSONB,
  new_values JSONB,
  blockchain_hash TEXT,
  blockchain_tx_hash TEXT,
  blockchain_status TEXT,
  tags TEXT[],
  created_at TIMESTAMPTZ
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied: admin or staff role required';
  END IF;

  RETURN QUERY
  SELECT
    aj.id,
    aj.user_id,
    COALESCE(au.email::text, aj.user_email) AS user_email,
    aj.user_role,
    aj.action_type,
    aj.entity_type,
    aj.entity_id,
    aj.area,
    aj.severity,
    aj.summary,
    aj.details,
    aj.old_values,
    aj.new_values,
    aj.blockchain_hash,
    aj.blockchain_tx_hash,
    aj.blockchain_status,
    aj.tags,
    aj.created_at
  FROM public.audit_journal aj
  LEFT JOIN aisha_auth.users au ON au.id = aj.user_id
  WHERE (p_action_type IS NULL OR aj.action_type::text = p_action_type)
    AND (p_area IS NULL OR aj.area::text = p_area)
    AND (p_severity IS NULL OR aj.severity::text = p_severity)
    AND (p_entity_type IS NULL OR aj.entity_type = p_entity_type)
    AND (p_start_date IS NULL OR aj.created_at >= p_start_date)
    AND (p_end_date IS NULL OR aj.created_at <= p_end_date)
    AND (p_search IS NULL OR
         aj.action_type::text ILIKE '%' || p_search || '%' OR
         aj.entity_type ILIKE '%' || p_search || '%' OR
         aj.summary ILIKE '%' || p_search || '%' OR
         COALESCE(au.email, aj.user_email) ILIKE '%' || p_search || '%')
  ORDER BY aj.created_at DESC
  LIMIT p_limit;
END;
$function$;

COMMENT ON FUNCTION public.get_audit_journal(integer, text, text, text, text, timestamptz, timestamptz, text) IS
  'Get audit journal entries with filtering. Admin/staff only.';

-- Permissions (admin/staff only via function check)
REVOKE ALL ON FUNCTION public.get_audit_journal(INTEGER, TEXT, TEXT, TEXT, TEXT, TIMESTAMPTZ, TIMESTAMPTZ, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_audit_journal(INTEGER, TEXT, TEXT, TEXT, TEXT, TIMESTAMPTZ, TIMESTAMPTZ, TEXT) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_audit_journal_stats_24h.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_audit_journal_stats_24h
-- Arguments: (none)
-- Description: Get 24h audit journal statistics grouped by action, area, severity.
-- Security: SECURITY DEFINER, admin/staff only.
-- Updated: 2026-01-18 - Added severity column for complete stats

CREATE OR REPLACE FUNCTION public.get_audit_journal_stats_24h()
 RETURNS TABLE(action text, area text, severity text, count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied: admin or staff role required';
  END IF;

  RETURN QUERY
  SELECT 
    aj.action,
    aj.metadata->>'area' AS area,
    COALESCE(aj.metadata->>'severity', aj.severity, 'info')::text AS severity,
    count(*)::bigint
  FROM public.audit_journal aj
  WHERE aj.created_at >= now() - interval '24 hours'
  GROUP BY aj.action, aj.metadata->>'area', COALESCE(aj.metadata->>'severity', aj.severity, 'info')
  ORDER BY count(*) DESC;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.get_audit_journal_stats_24h() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_audit_journal_stats_24h() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_baseline_comparison_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_baseline_comparison_audited
-- Description: Get baseline vs current comparison for all health metrics
-- Security: SECURITY DEFINER with audit logging
-- sensitive data: Yes - reads health metrics data

CREATE OR REPLACE FUNCTION public.get_baseline_comparison_audited(
  p_study_registration_id UUID
)
RETURNS TABLE (
  metric_name TEXT,
  baseline_value NUMERIC,
  baseline_measured_at TIMESTAMPTZ,
  current_value NUMERIC,
  current_measured_at TIMESTAMPTZ,
  change_absolute NUMERIC,
  change_percent NUMERIC,
  trend TEXT,
  measurements_count BIGINT
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
DECLARE
  v_user_id UUID;
BEGIN
  -- Get registration owner
  SELECT user_id INTO v_user_id
  FROM study_registrations
  WHERE id = p_study_registration_id;

  -- Authorization: own data or admin/staff
  IF v_user_id != auth.uid() AND NOT is_admin_or_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'BASELINE_COMPARISON_VIEW',
    jsonb_build_object(
      'area', 'health',
      'severity', 'info',
      'registration_id', p_study_registration_id,
      'target_user_id', v_user_id
    )
  );

  -- Return comparison for each metric
  RETURN QUERY
  WITH baseline AS (
    SELECT
      hm.physical_state,
      hm.mental_state,
      hm.energy_level,
      hm.stress_level,
      hm.weight_kg,
      hm.pain_level,
      hm.measured_at
    FROM health_metrics hm
    WHERE hm.study_registration_id = p_study_registration_id
    AND hm.source = 'registration'
    ORDER BY hm.measured_at ASC
    LIMIT 1
  ),
  latest AS (
    SELECT
      hm.physical_state,
      hm.mental_state,
      hm.energy_level,
      hm.stress_level,
      hm.weight_kg,
      hm.pain_level,
      hm.measured_at
    FROM health_metrics hm
    WHERE hm.study_registration_id = p_study_registration_id
    AND hm.source != 'registration'
    ORDER BY hm.measured_at DESC
    LIMIT 1
  ),
  counts AS (
    SELECT COUNT(*) as total
    FROM health_metrics
    WHERE study_registration_id = p_study_registration_id
  )
  -- Physical state
  SELECT 
    'physical_state'::TEXT,
    b.physical_state::NUMERIC,
    b.measured_at,
    l.physical_state::NUMERIC,
    l.measured_at,
    (l.physical_state - b.physical_state)::NUMERIC,
    CASE WHEN b.physical_state > 0 
      THEN ROUND(((l.physical_state - b.physical_state)::NUMERIC / b.physical_state) * 100, 1)
      ELSE NULL 
    END,
    CASE 
      WHEN l.physical_state > b.physical_state THEN 'improving'
      WHEN l.physical_state = b.physical_state THEN 'stable'
      ELSE 'declining'
    END,
    c.total
  FROM baseline b, latest l, counts c
  WHERE b.physical_state IS NOT NULL AND l.physical_state IS NOT NULL

  UNION ALL
  
  -- Mental state
  SELECT 
    'mental_state'::TEXT,
    b.mental_state::NUMERIC,
    b.measured_at,
    l.mental_state::NUMERIC,
    l.measured_at,
    (l.mental_state - b.mental_state)::NUMERIC,
    CASE WHEN b.mental_state > 0 
      THEN ROUND(((l.mental_state - b.mental_state)::NUMERIC / b.mental_state) * 100, 1)
      ELSE NULL 
    END,
    CASE 
      WHEN l.mental_state > b.mental_state THEN 'improving'
      WHEN l.mental_state = b.mental_state THEN 'stable'
      ELSE 'declining'
    END,
    c.total
  FROM baseline b, latest l, counts c
  WHERE b.mental_state IS NOT NULL AND l.mental_state IS NOT NULL

  UNION ALL
  
  -- Energy level
  SELECT 
    'energy_level'::TEXT,
    b.energy_level::NUMERIC,
    b.measured_at,
    l.energy_level::NUMERIC,
    l.measured_at,
    (l.energy_level - b.energy_level)::NUMERIC,
    CASE WHEN b.energy_level > 0 
      THEN ROUND(((l.energy_level - b.energy_level)::NUMERIC / b.energy_level) * 100, 1)
      ELSE NULL 
    END,
    CASE 
      WHEN l.energy_level > b.energy_level THEN 'improving'
      WHEN l.energy_level = b.energy_level THEN 'stable'
      ELSE 'declining'
    END,
    c.total
  FROM baseline b, latest l, counts c
  WHERE b.energy_level IS NOT NULL AND l.energy_level IS NOT NULL

  UNION ALL
  
  -- Stress level (inverse - lower is better)
  SELECT 
    'stress_level'::TEXT,
    b.stress_level::NUMERIC,
    b.measured_at,
    l.stress_level::NUMERIC,
    l.measured_at,
    (l.stress_level - b.stress_level)::NUMERIC,
    CASE WHEN b.stress_level > 0 
      THEN ROUND(((l.stress_level - b.stress_level)::NUMERIC / b.stress_level) * 100, 1)
      ELSE NULL 
    END,
    CASE 
      WHEN l.stress_level < b.stress_level THEN 'improving'  -- Lower stress = better
      WHEN l.stress_level = b.stress_level THEN 'stable'
      ELSE 'declining'
    END,
    c.total
  FROM baseline b, latest l, counts c
  WHERE b.stress_level IS NOT NULL AND l.stress_level IS NOT NULL

  UNION ALL
  
  -- Weight
  SELECT 
    'weight_kg'::TEXT,
    b.weight_kg::NUMERIC,
    b.measured_at,
    l.weight_kg::NUMERIC,
    l.measured_at,
    (l.weight_kg - b.weight_kg)::NUMERIC,
    CASE WHEN b.weight_kg > 0 
      THEN ROUND(((l.weight_kg - b.weight_kg)::NUMERIC / b.weight_kg) * 100, 1)
      ELSE NULL 
    END,
    'neutral'::TEXT,  -- Weight change is context-dependent
    c.total
  FROM baseline b, latest l, counts c
  WHERE b.weight_kg IS NOT NULL AND l.weight_kg IS NOT NULL

  UNION ALL
  
  -- Pain level (inverse - lower is better)
  SELECT 
    'pain_level'::TEXT,
    b.pain_level::NUMERIC,
    b.measured_at,
    l.pain_level::NUMERIC,
    l.measured_at,
    (l.pain_level - b.pain_level)::NUMERIC,
    CASE WHEN b.pain_level > 0 
      THEN ROUND(((l.pain_level - b.pain_level)::NUMERIC / b.pain_level) * 100, 1)
      ELSE NULL 
    END,
    CASE 
      WHEN l.pain_level < b.pain_level THEN 'improving'  -- Less pain = better
      WHEN l.pain_level = b.pain_level THEN 'stable'
      ELSE 'declining'
    END,
    c.total
  FROM baseline b, latest l, counts c
  WHERE b.pain_level IS NOT NULL AND l.pain_level IS NOT NULL;
END;
$$;

REVOKE ALL ON FUNCTION public.get_baseline_comparison_audited(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_baseline_comparison_audited(uuid) TO authenticated;

COMMENT ON FUNCTION public.get_baseline_comparison_audited(uuid) IS 'Get baseline vs current comparison for all health metrics';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_batch_inventory_list.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_batch_inventory_list
-- Arguments: p_product_id uuid, p_status text, p_include_empty boolean
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:40+01:00

CREATE OR REPLACE FUNCTION public.get_batch_inventory_list(p_product_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_include_empty boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_result JSONB;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT is_admin_or_staff(v_user_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT 
      pb.id AS batch_id,
      pb.batch_number,
      pb.product_id,
      p.name AS product_name,
      pb.status AS batch_status,
      pb.total_units,
      pb.available_units,
      pb.total_units - pb.available_units AS assigned_units,
      0 AS shipped_units,
      pb.expiry_date,
      pb.created_at AS batch_created_at,
      pb.quality_approved
    FROM production_batches pb
    JOIN products p ON pb.product_id = p.id
    WHERE (p_product_id IS NULL OR pb.product_id = p_product_id)
      AND (p_status IS NULL OR pb.status = p_status)
      AND (p_include_empty OR pb.available_units > 0)
    ORDER BY pb.expiry_date NULLS LAST, pb.created_at
  ) t;

  INSERT INTO audit_journal (user_id, action_type, area, entity_type, summary, severity)
  VALUES (v_user_id, 'view', 'admin', 'batch_inventory', 'Viewed batch inventory', 'info');

  RETURN v_result;
END;
$function$
;

-- Permissions
