-- Function: public.get_exhausted_integration_events
-- Returns integration events that exhausted all retry attempts.
-- For monitoring dashboards and alerting.
-- @security: admin/staff only

CREATE OR REPLACE FUNCTION public.get_exhausted_integration_events(
  p_hours_back integer DEFAULT 24
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  RETURN (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', ie.id,
        'event_source', ie.event_source,
        'event_type', ie.event_type,
        'external_id', ie.external_id,
        'attempt', ie.attempt,
        'max_attempts', ie.max_attempts,
        'error_message', ie.error_json->>'message',
        'story_id', ie.story_id,
        'created_at', ie.created_at
      )
      ORDER BY ie.created_at DESC
    ), '[]'::jsonb)
    FROM integration_events ie
    WHERE ie.status = 'exhausted'
      AND ie.created_at > now() - (p_hours_back || ' hours')::interval
  );
END;
$$;

REVOKE ALL ON FUNCTION public.get_exhausted_integration_events(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_exhausted_integration_events(integer) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_expedition_overview_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_expedition_overview_audited
-- Arguments: p_start_date date, p_end_date date
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:47+01:00

CREATE OR REPLACE FUNCTION public.get_expedition_overview_audited(p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_result JSONB;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT is_admin_or_staff(v_user_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT 
      ec.id,
      ec.expedition_date,
      ec.cut_off_date,
      p.name AS product_name,
      ec.product_id,
      s.name AS study_name,
      ec.study_id,
      ec.planned_shipments,
      ec.confirmed_shipments,
      ec.packed_shipments,
      ec.sent_shipments,
      ec.status,
      -- Return actual allocated_batches from expedition_calendar
      COALESCE(ec.allocated_batches, '[]'::jsonb) AS allocated_batches,
      ec.notes
    FROM expedition_calendar ec
    LEFT JOIN products p ON ec.product_id = p.id
    LEFT JOIN studies s ON ec.study_id = s.id
    WHERE (p_start_date IS NULL OR ec.expedition_date >= p_start_date)
      AND (p_end_date IS NULL OR ec.expedition_date <= p_end_date)
    ORDER BY ec.expedition_date
  ) t;

  -- Audit log
  INSERT INTO audit_journal (user_id, action_type, area, entity_type, summary, severity, details)
  VALUES (
    v_user_id, 
    'view', 
    'logistics', 
    'expedition', 
    'Viewed expedition overview', 
    'info',
    jsonb_build_object('start_date', p_start_date, 'end_date', p_end_date)
  );

  RETURN v_result;
END;
$function$
;

