-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_longevity_score_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_longevity_score_audited
-- Description: Get Longevity Score for a specific questionnaire response
-- Security: SECURITY DEFINER with audit logging
-- sensitive data: Yes - reads questionnaire responses (health data)

CREATE OR REPLACE FUNCTION public.get_longevity_score_audited(
  p_response_id UUID
)
RETURNS longevity_score_result
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_result longevity_score_result;
  v_responses JSONB;
  v_domain_scores JSONB;
  v_cls_score NUMERIC;
  v_valid_domains INTEGER := 0;
  v_domain JSONB;
  v_baseline_score NUMERIC;
  v_user_id UUID;
  v_questionnaire_id UUID;
BEGIN
  -- Get response data
  SELECT qr.id, qr.user_id, qr.completed_at, qr.responses, qr.questionnaire_id
  INTO v_result.response_id, v_user_id, v_result.completed_at, v_responses, v_questionnaire_id
  FROM questionnaire_responses qr
  WHERE qr.id = p_response_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Response not found';
  END IF;
  
  -- Authorization check
  IF NOT (
    v_user_id = auth.uid() OR
    is_admin_or_staff(auth.uid())
  ) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  
  v_result.user_id := v_user_id;
  
  -- Calculate domain scores
  v_domain_scores := calculate_domain_scores(v_responses);
  v_result.domain_scores := v_domain_scores;
  
  -- Calculate CLS (average of valid domain percentages)
  v_cls_score := 0;
  FOR v_domain IN SELECT * FROM jsonb_array_elements(v_domain_scores) LOOP
    IF (v_domain->>'percentage') IS NOT NULL THEN
      v_cls_score := v_cls_score + (v_domain->>'percentage')::NUMERIC;
      v_valid_domains := v_valid_domains + 1;
    END IF;
  END LOOP;
  
  IF v_valid_domains > 0 THEN
    v_result.cls_score := ROUND(v_cls_score / v_valid_domains, 1);
  ELSE
    v_result.cls_score := NULL;
  END IF;
  
  -- Get baseline score for trend calculation
  SELECT cls.cls_score INTO v_baseline_score
  FROM questionnaire_responses qr
  CROSS JOIN LATERAL (
    SELECT ROUND(
      (SELECT AVG((d->>'percentage')::NUMERIC) 
       FROM jsonb_array_elements(calculate_domain_scores(qr.responses)) d 
       WHERE (d->>'percentage') IS NOT NULL
      ), 1
    ) AS cls_score
  ) cls
  WHERE qr.user_id = v_user_id
    AND qr.questionnaire_id = v_questionnaire_id
    AND qr.completed_at < v_result.completed_at
  ORDER BY qr.completed_at ASC
  LIMIT 1;
  
  IF v_baseline_score IS NOT NULL AND v_result.cls_score IS NOT NULL THEN
    v_result.trend_vs_baseline := ROUND(v_result.cls_score - v_baseline_score, 1);
    v_result.trend_direction := CASE
      WHEN v_result.trend_vs_baseline > 2 THEN 'improving'
      WHEN v_result.trend_vs_baseline < -2 THEN 'declining'
      ELSE 'stable'
    END;
  ELSE
    v_result.trend_vs_baseline := NULL;
    v_result.trend_direction := NULL;
  END IF;
  
  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'sensitive data_READ',
    jsonb_build_object(
      'area', 'longevity_score',
      'severity', 'info',
      'entity_type', 'questionnaire_response',
      'entity_id', p_response_id,
      'user_id', v_user_id
    )
  );
  
  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.get_longevity_score_audited(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_longevity_score_audited(uuid) TO authenticated;

COMMENT ON FUNCTION public.get_longevity_score_audited(uuid) IS 'Get Longevity Score (CLS) for a specific questionnaire response with audit logging';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_mcp_registry_admin.sql
-- -----------------------------------------------------------------------------

-- Function: get_mcp_registry_admin
-- Returns mcp_server_registry rows for AdminMcpServerRegistry UI. Parallel
-- to get_provider_registry_admin but for the MCP catalog (aisha-knowledge,
-- huggingface-inference, github-mcp, etc.).
--
-- After PR #81 (WF_MCP_PROBE), last_tested_at + last_test_result are
-- updated every 5 min — this RPC surfaces that data to the admin UI.
--
-- Lifecycle awareness: status field has 7 values (discovered → tested_ok
-- → enabled → in_use → tested_failed → deprecated/rejected). Sort order
-- prioritizes operational ones (in_use, enabled) at top.
--
-- Admin-or-staff gate via is_admin_or_staff(). Service role bypasses.

CREATE OR REPLACE FUNCTION public.get_mcp_registry_admin(
  p_transport text    DEFAULT NULL,
  p_status    text    DEFAULT NULL,
  p_active_only boolean DEFAULT false
)
RETURNS TABLE (
  id uuid,
  slug text,
  display_name text,
  description text,
  transport text,
  endpoint_url text,
  stdio_command text[],
  auth_kind text,
  auth_env_var text,
  capability_tags text[],
  exposes_llm boolean,
  status text,
  last_tested_at timestamptz,
  last_test_result jsonb,
  test_failure_count int,
  source text,
  registered_by uuid,
  metadata jsonb,
  created_at timestamptz,
  updated_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF NOT is_admin_or_staff() AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Admin or staff role required' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    m.id,
    m.slug,
    m.display_name,
    m.description,
    m.transport,
    m.endpoint_url,
    m.stdio_command,
    m.auth_kind,
    m.auth_env_var,
    m.capability_tags,
    m.exposes_llm,
    m.status,
    m.last_tested_at,
    m.last_test_result,
    m.test_failure_count,
    m.source,
    m.registered_by,
    m.metadata,
    m.created_at,
    m.updated_at
  FROM mcp_server_registry m
  WHERE (p_transport IS NULL OR m.transport = p_transport)
    AND (p_status IS NULL OR m.status = p_status)
    AND (NOT p_active_only OR m.status IN ('enabled', 'in_use'))
  ORDER BY
    -- Operational lifecycle priority: in_use > enabled > tested_ok > discovered > tested_failed > deprecated > rejected
    CASE m.status
      WHEN 'in_use'         THEN 1
      WHEN 'enabled'        THEN 2
      WHEN 'tested_ok'      THEN 3
      WHEN 'discovered'     THEN 4
      WHEN 'tested_failed'  THEN 5
      WHEN 'deprecated'     THEN 6
      WHEN 'rejected'       THEN 7
      ELSE                       8
    END,
    m.test_failure_count ASC,  -- fewer failures = healthier among same status
    m.slug;
END;
$$;

REVOKE ALL ON FUNCTION public.get_mcp_registry_admin(text, text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_mcp_registry_admin(text, text, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_mcp_registry_admin(text, text, boolean) TO service_role;

COMMENT ON FUNCTION public.get_mcp_registry_admin(text, text, boolean) IS
  'AdminMcpServerRegistry UI read RPC — full mcp_server_registry rows + test history. Admin/staff gate. Sorted by operational lifecycle priority (in_use → rejected) then failure_count then slug.';


