-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_playwright_runs_health_summary.sql
-- -----------------------------------------------------------------------------

-- get_playwright_runs_health_summary
-- Admin/staff facing audited READ used by the Appsmith Playwright QA page
-- stat cards (queued / running / awaiting approval / passed-24h / failed-24h
-- / rollbacks-triggered). Window defaults to 24 h to match the AITG page.

CREATE OR REPLACE FUNCTION public.get_playwright_runs_health_summary(
  p_window_hours integer DEFAULT 24
)
RETURNS TABLE (
  queued integer,
  running integer,
  awaiting_approval integer,
  passed integer,
  failed integer,
  errored integer,
  aborted integer,
  rollbacks_triggered integer,
  window_hours integer
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_window integer := LEAST(GREATEST(COALESCE(p_window_hours, 24), 1), 24 * 30);
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin/staff required';
  END IF;

  RETURN QUERY
  SELECT
    -- "queued / running / awaiting_approval" are point-in-time gauges; they
    -- include rows that were queued long ago and never picked up (stuck-runner
    -- detection). Operator notices those because the count won't fall.
    COUNT(*) FILTER (WHERE status = 'queued')::integer AS queued,
    COUNT(*) FILTER (WHERE status = 'running')::integer AS running,
    COUNT(*) FILTER (WHERE status = 'queued' AND approval_required AND approved_at IS NULL)::integer AS awaiting_approval,
    -- Terminal counters are windowed (operator wants "did QA hold up in the
    -- last day?", not "lifetime totals").
    COUNT(*) FILTER (WHERE status = 'passed' AND finished_at >= now() - make_interval(hours => v_window))::integer AS passed,
    COUNT(*) FILTER (WHERE status = 'failed' AND finished_at >= now() - make_interval(hours => v_window))::integer AS failed,
    COUNT(*) FILTER (WHERE status = 'errored' AND finished_at >= now() - make_interval(hours => v_window))::integer AS errored,
    COUNT(*) FILTER (WHERE status = 'aborted' AND finished_at >= now() - make_interval(hours => v_window))::integer AS aborted,
    COUNT(*) FILTER (WHERE triggered_rollback_id IS NOT NULL AND finished_at >= now() - make_interval(hours => v_window))::integer AS rollbacks_triggered,
    v_window AS window_hours
  FROM public.playwright_runs;
END;
$$;

REVOKE ALL ON FUNCTION public.get_playwright_runs_health_summary(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_playwright_runs_health_summary(integer) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_plugin_health_summary.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- get_plugin_health_summary(p_plugin_id, p_hours)
-- =============================================================================
-- Aggregates plugin health events over the last N hours.
-- Returns: total invocations, error count, error rate, P95 latency, last error.
-- Used by WF_PLUGIN_HEALTH_WATCH for canary monitoring + Appsmith dashboard.
-- =============================================================================

CREATE OR REPLACE FUNCTION public.get_plugin_health_summary(
  p_hours     integer DEFAULT 24,
  p_plugin_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_total   bigint;
  v_errors  bigint;
  v_p95     numeric;
  v_last_error text;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Only admin or staff can view plugin health summary';
  END IF;

  IF p_plugin_id IS NULL THEN
    RAISE EXCEPTION 'p_plugin_id is required';
  END IF;

  -- Total invocations (load + invoke events)
  SELECT count(*)
  INTO v_total
  FROM public.plugin_health_events
  WHERE plugin_id = p_plugin_id
    AND recorded_at >= now() - (p_hours || ' hours')::interval
    AND event_kind IN ('load', 'invoke');

  -- Error count
  SELECT count(*)
  INTO v_errors
  FROM public.plugin_health_events
  WHERE plugin_id = p_plugin_id
    AND recorded_at >= now() - (p_hours || ' hours')::interval
    AND event_kind IN ('error', 'timeout');

  -- P95 latency
  SELECT percentile_cont(0.95) WITHIN GROUP (ORDER BY latency_ms)
  INTO v_p95
  FROM public.plugin_health_events
  WHERE plugin_id = p_plugin_id
    AND recorded_at >= now() - (p_hours || ' hours')::interval
    AND latency_ms IS NOT NULL;

  -- Last error text
  SELECT error_text
  INTO v_last_error
  FROM public.plugin_health_events
  WHERE plugin_id = p_plugin_id
    AND recorded_at >= now() - (p_hours || ' hours')::interval
    AND event_kind IN ('error', 'timeout')
    AND error_text IS NOT NULL
  ORDER BY recorded_at DESC
  LIMIT 1;

  RETURN jsonb_build_object(
    'plugin_id', p_plugin_id,
    'total_invocations', COALESCE(v_total, 0),
    'error_count', COALESCE(v_errors, 0),
    'error_rate', CASE
      WHEN COALESCE(v_total, 0) + COALESCE(v_errors, 0) = 0 THEN 0
      ELSE round(v_errors::numeric / (v_total + v_errors)::numeric, 4)
    END,
    'p95_latency_ms', COALESCE(v_p95, 0),
    'last_error', v_last_error,
    'period_hours', p_hours
  );
END;
$$;

COMMENT ON FUNCTION public.get_plugin_health_summary(integer, uuid) IS
  'Aggregates plugin health over N hours: invocations, errors, P95 latency.';

REVOKE ALL ON FUNCTION public.get_plugin_health_summary(integer, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_plugin_health_summary(integer, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
