GRANT EXECUTE ON FUNCTION public.get_tokenomics_overview() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_translation_metrics_admin.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.get_translation_metrics_admin(
  p_days integer DEFAULT 30
)
RETURNS TABLE (
  content_type text,
  provider text,
  model text,
  locale text,
  translation_count bigint,
  avg_token_count numeric,
  avg_latency_ms numeric,
  avg_quality_score numeric,
  human_reviewed_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = 'P0001';
  END IF;

  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'TRANSLATION_METRICS_READ',
    jsonb_build_object(
      'area', 'knowledge',
      'severity', 'info',
      'p_days', p_days
    )
  );

  RETURN QUERY
  -- Topic translations
  SELECT
    'topic'::text AS content_type,
    ktt.provider,
    ktt.model,
    ktt.locale,
    count(*)::bigint AS translation_count,
    round(avg(ktt.token_count)::numeric, 0) AS avg_token_count,
    round(avg(ktt.latency_ms)::numeric, 0) AS avg_latency_ms,
    round(avg(ktt.quality_score)::numeric, 2) AS avg_quality_score,
    count(*) FILTER (WHERE ktt.is_human_reviewed)::bigint AS human_reviewed_count
  FROM knowledge_topic_translations ktt
  WHERE ktt.created_at >= now() - (p_days || ' days')::interval
  GROUP BY ktt.provider, ktt.model, ktt.locale

  UNION ALL

  -- Post translations
  SELECT
    'post'::text AS content_type,
    kpt.provider,
    kpt.model,
    kpt.locale,
    count(*)::bigint AS translation_count,
    round(avg(kpt.token_count)::numeric, 0) AS avg_token_count,
    round(avg(kpt.latency_ms)::numeric, 0) AS avg_latency_ms,
    round(avg(kpt.quality_score)::numeric, 2) AS avg_quality_score,
    count(*) FILTER (WHERE kpt.is_human_reviewed)::bigint AS human_reviewed_count
  FROM knowledge_post_translations kpt
  WHERE kpt.created_at >= now() - (p_days || ' days')::interval
  GROUP BY kpt.provider, kpt.model, kpt.locale

  ORDER BY content_type, translation_count DESC;
END;
$$;

REVOKE ALL ON FUNCTION public.get_translation_metrics_admin(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_translation_metrics_admin(integer) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_user_memory_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_user_memory_audited
-- Arguments: p_target_user_id uuid DEFAULT NULL
-- Security: SECURITY DEFINER
-- Source: Phase 4 — Agent Loop & Memory

CREATE OR REPLACE FUNCTION public.get_user_memory_audited(p_target_user_id uuid DEFAULT NULL)
 RETURNS TABLE(key text, value jsonb, confidence real, source text, last_updated timestamptz)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_target   uuid := COALESCE(p_target_user_id, v_actor_id);
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF v_target <> v_actor_id THEN
    IF NOT is_admin_or_staff() THEN
      RAISE EXCEPTION 'Access denied: admin or staff required for cross-user memory access';
    END IF;
  END IF;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (v_actor_id, 'AI_MEMORY_READ', jsonb_build_object(
    'area', 'ai', 'severity', 'info',
    'target_user_id', v_target::text,
    'self_access', (v_target = v_actor_id)
  ));

  RETURN QUERY
  SELECT um.key, um.value, um.confidence, um.source, um.last_updated
  FROM ai_user_memory um
  WHERE um.user_id = v_target
  ORDER BY um.last_updated DESC;
END;
$$;

REVOKE ALL ON FUNCTION public.get_user_memory_audited(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_user_memory_audited(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
