-- -----------------------------------------------------------------------------

-- Function: public.get_user_memory_for_agent
-- Arguments: p_user_id uuid
-- Security: SECURITY DEFINER
-- Source: Phase 4 — Agent Loop & Memory

CREATE OR REPLACE FUNCTION public.get_user_memory_for_agent(p_user_id uuid)
 RETURNS TABLE(key text, value jsonb, confidence real, source text, last_updated timestamptz)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $$
DECLARE
  v_actor_id uuid := auth.uid();
BEGIN
  IF v_actor_id IS NOT NULL AND NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  SELECT um.key, um.value, um.confidence, um.source, um.last_updated
  FROM ai_user_memory um
  WHERE um.user_id = p_user_id
  ORDER BY um.confidence DESC, um.last_updated DESC;
END;
$$;

REVOKE ALL ON FUNCTION public.get_user_memory_for_agent(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_user_memory_for_agent(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_voucher_analytics_admin.sql
-- -----------------------------------------------------------------------------

-- get_voucher_analytics_admin: Aggregated voucher metrics
CREATE OR REPLACE FUNCTION public.get_voucher_analytics_admin()
RETURNS TABLE (
  active_count bigint,
  avg_points_cost numeric,
  conversion_rate numeric,
  expired_count bigint,
  total_issued bigint,
  total_points_spent bigint,
  used_count bigint
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  -- Audit log
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_user_id, 'VOUCHER_ANALYTICS_VIEW', jsonb_build_object(
    'area', 'admin',
    'severity', 'info'
  ));

  RETURN QUERY
  SELECT
    COUNT(*) FILTER (WHERE v.status = 'active') AS active_count,
    COALESCE(AVG(v.points_cost) FILTER (WHERE v.points_cost > 0), 0) AS avg_points_cost,
    CASE
      WHEN COUNT(*) > 0 THEN
        ROUND((COUNT(*) FILTER (WHERE v.status = 'used'))::numeric / COUNT(*)::numeric * 100, 1)
      ELSE 0
    END AS conversion_rate,
    COUNT(*) FILTER (WHERE v.status = 'expired' OR (v.status = 'active' AND v.expires_at < now())) AS expired_count,
    COUNT(*) AS total_issued,
    COALESCE(SUM(v.points_cost) FILTER (WHERE v.points_cost > 0), 0)::bigint AS total_points_spent,
    COUNT(*) FILTER (WHERE v.status = 'used') AS used_count
  FROM public.product_vouchers v;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_voucher_analytics_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_voucher_analytics_admin() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_vouchers_admin.sql
-- -----------------------------------------------------------------------------

-- get_vouchers_admin: Admin list of all vouchers with filtering and pagination
CREATE OR REPLACE FUNCTION public.get_vouchers_admin(
  p_limit integer DEFAULT 50,
  p_offset integer DEFAULT 0,
  p_status text DEFAULT NULL
)
RETURNS TABLE (
  code text,
  created_at timestamptz,
  expires_at timestamptz,
  id uuid,
  metadata jsonb,
  points_cost integer,
  product_id uuid,
  product_name text,
  status text,
  updated_at timestamptz,
  used_at timestamptz,
  user_email text,
  user_id uuid
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  -- Audit log
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_user_id, 'VOUCHER_ADMIN_LIST', jsonb_build_object(
    'area', 'admin',
    'severity', 'info',
    'limit', p_limit,
    'offset', p_offset,
    'status_filter', p_status
  ));

  RETURN QUERY
  SELECT
    v.code,
    v.created_at,
    v.expires_at,
    v.id,
    v.metadata,
    v.points_cost::integer,
    v.product_id,
    COALESCE(p.name, '') AS product_name,
    v.status,
    v.updated_at,
    v.used_at,
    COALESCE(u.email, '') AS user_email,
    v.user_id
  FROM public.product_vouchers v
  LEFT JOIN public.products p ON p.id = v.product_id
  LEFT JOIN aisha_auth.users u ON u.id = v.user_id
  WHERE (p_status IS NULL OR v.status = p_status)
  ORDER BY v.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_vouchers_admin(integer, integer, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_vouchers_admin(integer, integer, text) TO authenticated;


