-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/is_service_role.sql
-- -----------------------------------------------------------------------------

-- Function: public.is_service_role
-- Description: The single canonical answer to "is the current request the
--   trusted service_role?" — boolean-NOT-NULL by construction.
--
--   Replaces the inline idiom
--     (current_setting('request.jwt.claims', true)::jsonb ->> 'role') = 'service_role'
--   which folds to SQL NULL when the `role` claim is absent (anon / a token with
--   no role), and a NULL then propagates through negative deny-guards
--   (`IF v_user_id IS NULL AND NOT v_is_service` / `IF NOT v_is_service AND ...`)
--   so `IF NULL` never RAISEs → the guard FAILS OPEN. Both disjuncts here
--   COALESCE to false, so the result is never NULL and any deny-guard built on
--   `NOT is_service_role()` is total (fails CLOSED).
--
--   Reuses get_jwt_role() as the single reader of request.jwt.claims (keeps the
--   legacy-GUC / JSON-claims compatibility in one place) and keeps the SET ROLE
--   GUC disjunct so an in-DB `SET ROLE service_role` caller is still recognised.
--
--   LANGUAGE plpgsql (not sql) so the body is not name-resolved at CREATE time —
--   this makes it ordering-immune on both the cold-start baseline and heals
--   (no dependency-ordering hazard vs get_jwt_role).
-- Security: SECURITY DEFINER, search_path pinned. Safe in RLS policies and
--   SECURITY DEFINER RPCs. Granted to anon too (returns false) so anon-granted
--   callers can adopt it without a permission-denied.

CREATE OR REPLACE FUNCTION public.is_service_role()
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
AS $$
BEGIN
  RETURN COALESCE(public.get_jwt_role() = 'service_role', false)
      OR COALESCE(current_setting('role', true) = 'service_role', false);
END;
$$;

REVOKE ALL ON FUNCTION public.is_service_role() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_service_role() TO anon, authenticated, service_role;

COMMENT ON FUNCTION public.is_service_role() IS
  'Boolean-NOT-NULL service_role detector. Canonical replacement for the inline '
  'request.jwt.claims->>''role''=''service_role'' idiom that folds to NULL (and '
  'fails OPEN in negative deny-guards) when the role claim is absent. Reuses '
  'get_jwt_role(); keeps the SET ROLE GUC disjunct. plpgsql = ordering-immune.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/abort_slot_switch.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: abort_slot_switch
-- Popis: Releases switch lock without committing — rollback path on smoke test
--        failure or approval rejection. Allows force-release i pokud lock owner
--        mismatch (loguje warning v audit_journal).
-- Volá: WF_BLUE_GREEN_ORCHESTRATOR (Abort Smoke Fail / Abort Pending Approval)
-- Auth: service_role nebo admin/staff
-- ============================================================================

CREATE OR REPLACE FUNCTION public.abort_slot_switch(
  p_app_name   text,
  p_lock_owner text,
  p_reason     text DEFAULT 'manual_abort'
)
RETURNS public.coolify_app_slots
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row public.coolify_app_slots;
  v_is_service boolean;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  -- Allow abort even if lock owner mismatch (force-release)
  -- ale loguje warning v audit
  UPDATE public.coolify_app_slots
  SET switch_lock = false,
      switch_lock_at = NULL,
      switch_lock_by = NULL,
      updated_at = now()
  WHERE app_name = p_app_name
  RETURNING * INTO v_row;

  IF v_row IS NULL THEN
    RAISE EXCEPTION 'App slot not found: %', p_app_name;
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'blue_green_switch_aborted',
    jsonb_build_object(
      'app_name', p_app_name,
      'reason', p_reason,
      'lock_owner_was', v_row.switch_lock_by,
      'lock_owner_provided', p_lock_owner,
      'force_release', v_row.switch_lock_by IS DISTINCT FROM p_lock_owner
    )
  );

  RETURN v_row;
END;
$$;

REVOKE ALL ON FUNCTION public.abort_slot_switch(text, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.abort_slot_switch(text, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.abort_slot_switch(text, text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/acquire_slot_lock.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: acquire_slot_lock
-- Popis: Atomický pokus získat switch lock na coolify_app_slots row.
--        Selhává rychle, pokud lock drží jiný proces (a není stale).
--        Stale lock (>10 min) se auto-uvolní novým acquirerem.
-- Volá: WF_BLUE_GREEN_ORCHESTRATOR (n8n workflow)
-- Auth: service_role (n8n) nebo admin/staff
-- ============================================================================

CREATE OR REPLACE FUNCTION public.acquire_slot_lock(
  p_app_name   text,
  p_lock_owner text
)
RETURNS public.coolify_app_slots
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row public.coolify_app_slots;
  v_is_service boolean;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  IF p_app_name IS NULL OR p_app_name = '' THEN
    RAISE EXCEPTION 'app_name required';
  END IF;
  IF p_lock_owner IS NULL OR p_lock_owner = '' THEN
    RAISE EXCEPTION 'lock_owner required';
  END IF;

  UPDATE public.coolify_app_slots
  SET switch_lock = true,
      switch_lock_at = now(),
      switch_lock_by = p_lock_owner,
      updated_at = now()
  WHERE app_name = p_app_name
    AND (
      switch_lock = false
      OR switch_lock_at < now() - interval '10 minutes'  -- stale lock auto-release
    )
  RETURNING * INTO v_row;

  IF v_row IS NULL THEN
    RAISE EXCEPTION 'Switch lock held by another process for app: %', p_app_name;
  END IF;

  -- Audit
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'slot_lock_acquired',
    jsonb_build_object(
      'app_name', p_app_name,
      'lock_owner', p_lock_owner,
      'active_slot', v_row.active_slot
    )
  );

  RETURN v_row;
END;
$$;

REVOKE ALL ON FUNCTION public.acquire_slot_lock(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.acquire_slot_lock(text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.acquire_slot_lock(text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/acs_create_intent.sql
-- -----------------------------------------------------------------------------

-- Function: acs_create_intent
CREATE OR REPLACE FUNCTION acs_create_intent(
  p_intent_id      text,
  p_canonical      jsonb,
  p_content_sha256 text,
  p_source_class   text,
  p_created_by     text,
  p_ai_run_id      uuid DEFAULT NULL
) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'acs: service role required' USING ERRCODE = '42501';
  END IF;

  INSERT INTO acs_intents (intent_id, canonical, content_sha256, source_class, created_by, ai_run_id)
  VALUES (p_intent_id, p_canonical, p_content_sha256, p_source_class, p_created_by, p_ai_run_id);
  RETURN p_intent_id;
EXCEPTION WHEN unique_violation THEN
  -- Same id twice is legal ONLY for identical content (idempotent replay).
  IF EXISTS (SELECT 1 FROM acs_intents WHERE intent_id = p_intent_id AND content_sha256 = p_content_sha256) THEN
    RETURN p_intent_id;
  END IF;
  RAISE EXCEPTION 'acs_create_intent: intent % exists with different content (immutability violation)', p_intent_id;
END $$;

REVOKE ALL ON FUNCTION acs_create_intent(text, jsonb, text, text, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION acs_create_intent(text, jsonb, text, text, text, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/acs_effect_decide.sql
-- -----------------------------------------------------------------------------

-- Function: acs_effect_decide
CREATE OR REPLACE FUNCTION acs_effect_decide(p_effect_id text, p_decision jsonb)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_state text;
  v_hash  text;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'acs: service role required' USING ERRCODE = '42501';
  END IF;

  SELECT state, params_sha256 INTO v_state, v_hash FROM acs_pending_effects WHERE effect_id = p_effect_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'acs_effect_decide: unknown effect %', p_effect_id; END IF;
  IF v_state <> 'proposed' THEN RAISE EXCEPTION 'acs_effect_decide: effect % is %, not proposed', p_effect_id, v_state; END IF;
  IF (p_decision ->> 'params_sha256') IS DISTINCT FROM v_hash THEN
    RAISE EXCEPTION 'acs_effect_decide: params hash mismatch for % (R5 drift)', p_effect_id;
  END IF;
  UPDATE acs_pending_effects
  SET state = CASE WHEN p_decision ->> 'decision' = 'confirm' THEN 'confirmed' ELSE 'aborted' END,
      decision = p_decision,
      decided_at = now()
  WHERE effect_id = p_effect_id;
END $$;

REVOKE ALL ON FUNCTION acs_effect_decide(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION acs_effect_decide(text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/acs_effect_mark_executed.sql
-- -----------------------------------------------------------------------------

-- Function: acs_effect_mark_executed
CREATE OR REPLACE FUNCTION acs_effect_mark_executed(p_effect_id text)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE v_state text;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'acs: service role required' USING ERRCODE = '42501';
  END IF;

  SELECT state INTO v_state FROM acs_pending_effects WHERE effect_id = p_effect_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'acs_effect_mark_executed: unknown effect %', p_effect_id; END IF;
  IF v_state <> 'confirmed' THEN
    RAISE EXCEPTION 'acs_effect_mark_executed: effect % is %, not confirmed (R5)', p_effect_id, v_state;
  END IF;
  UPDATE acs_pending_effects SET state = 'executed', executed_at = now() WHERE effect_id = p_effect_id;
END $$;

REVOKE ALL ON FUNCTION acs_effect_mark_executed(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION acs_effect_mark_executed(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/acs_effect_propose.sql
-- -----------------------------------------------------------------------------

-- Function: acs_effect_propose
CREATE OR REPLACE FUNCTION acs_effect_propose(p_payload jsonb)
RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'acs: service role required' USING ERRCODE = '42501';
  END IF;

  INSERT INTO acs_pending_effects (effect_id, intent_id, tool_name, effect_class, proposal, params_sha256)
  VALUES (
    p_payload ->> 'effect_id',
    p_payload ->> 'intent_ref',
    p_payload ->> 'tool_name',
    p_payload ->> 'effect_class',
    p_payload -> 'proposal',
    p_payload -> 'proposal' ->> 'params_sha256'
  );
  RETURN p_payload ->> 'effect_id';
END $$;

REVOKE ALL ON FUNCTION acs_effect_propose(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION acs_effect_propose(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/acs_ingest_message.sql
-- -----------------------------------------------------------------------------

-- Function: acs_ingest_message
CREATE OR REPLACE FUNCTION acs_ingest_message(p_message jsonb, p_received_by text DEFAULT 'db')
RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_env        jsonb;
  v_schema_ref text;
  v_mode       text;
  v_code       text := NULL;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'acs: service role required' USING ERRCODE = '42501';
  END IF;

  v_env := p_message -> 'envelope';
  IF v_env IS NULL OR p_message -> 'payload' IS NULL THEN
    v_code := 'envelope_invalid';
  ELSE
    v_schema_ref := v_env ->> 'schema';
    IF v_schema_ref IS NULL OR v_schema_ref !~ '^[a-z0-9_.-]+@[0-9]+\.[0-9]+$' THEN
      v_code := 'envelope_invalid';
    ELSIF (v_env ->> 'message_id') IS NULL OR (v_env ->> 'message_id') !~ '^[0-9A-HJKMNP-TV-Z]{26}$' THEN
      v_code := 'envelope_invalid';
    ELSIF (v_env ->> 'intent_id') IS NULL OR (v_env ->> 'intent_id') !~ '^int_[0-9A-HJKMNP-TV-Z]{26}$' THEN
      v_code := 'envelope_invalid';
    ELSIF NOT EXISTS (SELECT 1 FROM acs_message_schemas s WHERE s.schema_ref = v_schema_ref) THEN
      v_code := 'unknown_schema';
    ELSIF NOT EXISTS (SELECT 1 FROM acs_intents i WHERE i.intent_id = v_env ->> 'intent_id') THEN
      v_code := 'envelope_invalid';  -- lineage anchor must exist (R3)
    ELSIF EXISTS (SELECT 1 FROM acs_message_log l WHERE l.message_id = v_env ->> 'message_id') THEN
      v_code := 'duplicate_message';
    END IF;
  END IF;

  IF v_code IS NULL THEN
    INSERT INTO acs_message_log (
      message_id, schema_ref, intent_id, correlation_id, causation_id,
      sender, recipient, sent_at, signature, trust, payload
    ) VALUES (
      v_env ->> 'message_id', v_schema_ref, v_env ->> 'intent_id',
      v_env ->> 'correlation_id', v_env ->> 'causation_id',
      v_env ->> 'sender', v_env ->> 'recipient',
      (v_env ->> 'sent_at')::timestamptz, v_env ->> 'signature',
      COALESCE(v_env -> 'trust', '{}'::jsonb), p_message -> 'payload'
    );
    RETURN NULL;
  END IF;

  SELECT COALESCE(s.mode, 'shadow') INTO v_mode FROM acs_message_schemas s WHERE s.schema_ref = v_schema_ref;
  IF COALESCE(v_mode, 'shadow') IN ('warn', 'enforce') THEN
    INSERT INTO acs_dead_letters (rejection_code, detail, raw, received_by)
    VALUES (v_code, 'acs_ingest_message rejection', p_message, p_received_by);
  END IF;
  RETURN v_code;
END $$;

REVOKE ALL ON FUNCTION acs_ingest_message(jsonb, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION acs_ingest_message(jsonb, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/activate_data_source.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: activate_data_source
-- Popis: Zapne zdroj dat. Protějšek k deaktivaci, který dosud CHYBĚL.
--
-- ⛔ PROČ VZNIKÁ. Naměřeno 2026-09-01: jediný UPDATE nad
-- `agent_knowledge_sources` v celém SoT byl `is_active = false`
-- (`deactivate_plugin_runtime`). `materialize_data_source` zakládá řádek
-- neaktivní „BY CONSTRUCTION" — jenže protějšek k tomu záměru nikdo nedopsal.
-- Broker proto u zdroje `money` každou minutu psal „aktivace je rozhodnutí
-- člověka", zatímco ten člověk NEMĚL ČÍM rozhodnout. Systém uměl bezpečně
-- říct „ne" a neuměl říct „ano".
--
-- ⭐ STRÁŽ SE NEVYMÝŠLÍ, ČTE SE ZE SCHÉMATU PLUGINU. Zapnout nejde, dokud
-- chybí pověření, která plugin sám označil jako `required` ∧ `secret`. Bez
-- toho by šlo zapnout zdroj naprázdno: cron by tikal, log by vypadal jako
-- provoz a tabulky by zůstaly na nule — tvar poruchy, který se nepozná.
--
-- Zdroj bez pluginu (money, local-ingest) nemá schéma; nevyžaduje se tedy nic.
-- Prázdný požadavek je „nic se nevyžaduje", ne „nevím".
--
-- Idempotentní: zapnutí už zapnutého nic nemění a nezapisuje do žurnálu
-- druhou událost.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.activate_data_source(p_source_slug text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_source_id uuid;
  v_active    boolean;
  v_schema    jsonb;
  v_chybi     text[];
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT s.id, s.is_active, pc.config_schema
    INTO v_source_id, v_active, v_schema
    FROM public.agent_knowledge_sources s
    LEFT JOIN public.plugin_catalog pc ON pc.id = s.source_plugin_id
   WHERE s.source_slug = p_source_slug;

  IF v_source_id IS NULL THEN
    RAISE EXCEPTION 'activate_data_source: zdroj % neexistuje', p_source_slug;
  END IF;

  IF v_active THEN
    RETURN jsonb_build_object('source_slug', p_source_slug, 'is_active', true, 'changed', false);
  END IF;

  SELECT coalesce(array_agg(r.k ORDER BY r.k), '{}')
    INTO v_chybi
    FROM jsonb_array_elements_text(coalesce(v_schema->'required', '[]'::jsonb)) AS r(k)
   WHERE coalesce((v_schema->'properties'->r.k->>'secret')::boolean, false)
     AND NOT EXISTS (
       SELECT 1 FROM public.agent_knowledge_source_secrets sec
        WHERE sec.source_id = v_source_id AND sec.secret_key = r.k
     );

  IF array_length(v_chybi, 1) > 0 THEN
    RAISE EXCEPTION 'activate_data_source: zdroj % nelze zapnout — chybí pověření: %',
      p_source_slug, array_to_string(v_chybi, ', ');
  END IF;

  UPDATE public.agent_knowledge_sources
     SET is_active = true, updated_at = now()
   WHERE id = v_source_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'DATA_SOURCE_ACTIVATED', jsonb_build_object(
    'area', 'ingest', 'severity', 'warning',
    'source_slug', p_source_slug, 'source_id', v_source_id
  ));

  RETURN jsonb_build_object('source_slug', p_source_slug, 'is_active', true, 'changed', true);
END;
$$;

COMMENT ON FUNCTION public.activate_data_source(text) IS
  'Zapne zdroj dat. Odmítne, dokud chybí pověření označená v config_schema pluginu jako required ∧ secret. Idempotentní, auditované. Admin/staff nebo service_role.';

REVOKE ALL ON FUNCTION public.activate_data_source(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.activate_data_source(text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/admin_list_knock_devices.sql
-- -----------------------------------------------------------------------------

-- Function: public.admin_list_knock_devices
-- Arguments: p_user_id uuid, p_druh text ('osobni' | 'tablet' | NULL = oba)
-- Security: SECURITY DEFINER, jen admin/staff nebo service_role.
--
-- Co správce v administraci u uživatele vidí.
--
-- ⭐ „KDO POUŽÍVÁ KTERÁ ZAŘÍZENÍ" se NEČTE z průkazu, ale z `mobile_sessions`
-- přes most `push_device_id` — tam ta vazba bydlí (řádek na dvojici
-- uživatel×zařízení). Průkaz nese jen toho, kdo zařízení ZAVEDL.
--
-- ⛔ VEŘEJNÝ KLÍČ SE VRACÍ CELÝ a je to v pořádku: je veřejný z definice a
-- správce podle něj zařízení pozná. Soukromá půlka v téhle tabulce NENÍ a být
-- nesmí — kdyby tu jednou byla, vracela by ji i tahle funkce.

-- 2026-09-28: výstup nese i druh průkazu, adresu ohlášení a verze (tablet v kiosku se
-- ohlašuje sám — správce vidí, co schvaluje). Změna návratového typu = DROP předem.
-- ⛔ Jednoparametrová verze vracela užší tvar (bez druhu, adresy a verzí). Tvar
-- výsledku CREATE OR REPLACE změnit neumí, proto nová signatura se dvěma
-- parametry a starší přetížení JINÉ arity se zahodí (2026-09-28, tablety).
DROP FUNCTION IF EXISTS public.admin_list_knock_devices(uuid);
CREATE OR REPLACE FUNCTION public.admin_list_knock_devices(
  p_user_id uuid DEFAULT NULL::uuid,
  p_druh text DEFAULT NULL::text
)
 RETURNS TABLE (
   kid text,
   public_key_hex text,
   scope text,
   owner_user_id uuid,
   push_device_id text,
   first_seen_at timestamptz,
   last_seen_at timestamptz,
   approved_at timestamptz,
   revoked_at timestamptz,
   uzivatele jsonb,
   druh text,
   ohlaseno_z_ip text,
   verze jsonb
 )
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT ((SELECT public.is_service_role()) OR (SELECT public.is_admin_or_staff())) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  RETURN QUERY
  SELECT
    d.kid, d.public_key_hex, d.scope, d.owner_user_id, d.push_device_id,
    d.first_seen_at, d.last_seen_at, d.approved_at, d.revoked_at,
    COALESCE(
      (SELECT jsonb_agg(jsonb_build_object('user_id', s.user_id, 'last_active_at', s.last_active_at)
                        ORDER BY s.last_active_at DESC)
         FROM public.mobile_sessions s
        WHERE s.device_id = d.push_device_id),
      '[]'::jsonb
    ) AS uzivatele,
    d.druh,
    host(d.ohlaseno_z_ip) AS ohlaseno_z_ip,
    d.verze
  FROM public.knock_device_credentials d
  WHERE (p_druh IS NULL OR d.druh = p_druh)
    AND (p_user_id IS NULL
     OR d.owner_user_id = p_user_id
     -- Zařízení patří do výpisu u uživatele i tehdy, když ho jen POUŽÍVÁ:
     -- zavedl ho někdo jiný, ale odvolání se týká i jeho.
     OR EXISTS (SELECT 1 FROM public.mobile_sessions s
                 WHERE s.device_id = d.push_device_id AND s.user_id = p_user_id))
  ORDER BY d.last_seen_at DESC;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.admin_list_knock_devices(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_list_knock_devices(uuid, text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/adopt_story_as_stack_default.sql
-- -----------------------------------------------------------------------------

-- Function: public.adopt_story_as_stack_default
-- Arguments: p_story_id uuid, p_demote_existing boolean DEFAULT false
-- Description: Marks a story as THE stack-default story (singleton enforced by
--              partial unique index uniq_partner_stories_stack_default).
--              Idempotent when the story is already the default. If another
--              story currently holds the flag, it is demoted first when
--              p_demote_existing = true; otherwise the call fails.
--              Typical use: a replica instance adopts the bootstrapped story
--              as the story that owns its public default web.
-- Security: SECURITY INVOKER + explicit role check (service_role or admin/staff)
--           per ensure_stack_default_story — admin RLS policy on partner_stories
--           permits the UPDATEs, service_role bypasses RLS.

CREATE OR REPLACE FUNCTION public.adopt_story_as_stack_default(
  p_story_id uuid,
  p_demote_existing boolean DEFAULT false
)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY INVOKER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_service boolean;
  v_story record;
  v_current_default_id uuid;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin/staff or service_role required' USING ERRCODE = '22023';
  END IF;

  SELECT id, is_stack_default INTO v_story
  FROM public.partner_stories
  WHERE id = p_story_id;

  IF v_story.id IS NULL THEN
    RAISE EXCEPTION 'Story not found: %', p_story_id USING ERRCODE = '22023';
  END IF;

  -- Idempotent: already the stack default
  IF v_story.is_stack_default THEN
    RETURN v_story.id;
  END IF;

  SELECT id INTO v_current_default_id
  FROM public.partner_stories
  WHERE is_stack_default = true
    AND id != p_story_id
  LIMIT 1;

  IF v_current_default_id IS NOT NULL THEN
    IF NOT p_demote_existing THEN
      RAISE EXCEPTION 'Another story is already the stack default: %. Pass p_demote_existing = true to replace it.',
        v_current_default_id USING ERRCODE = '22023';
    END IF;

    -- Demote BEFORE adopting — the partial unique index allows only one default
    UPDATE public.partner_stories
    SET is_stack_default = false,
        updated_at = now()
    WHERE id = v_current_default_id;

    INSERT INTO public.audit_journal (user_id, action, metadata)
    VALUES (auth.uid(), 'STACK_DEFAULT_STORY_DEMOTED', jsonb_build_object(
      'area', 'story_sync',
      'severity', 'info',
      'entity_type', 'partner_story',
      'entity_id', v_current_default_id,
      'replaced_by', p_story_id
    ));
  END IF;

  UPDATE public.partner_stories
  SET is_stack_default = true,
      updated_at = now()
  WHERE id = p_story_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'STACK_DEFAULT_STORY_ADOPTED', jsonb_build_object(
    'area', 'story_sync',
    'severity', 'info',
    'entity_type', 'partner_story',
    'entity_id', p_story_id,
    'demoted_previous', v_current_default_id
  ));

  RETURN p_story_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.adopt_story_as_stack_default(uuid, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.adopt_story_as_stack_default(uuid, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.adopt_story_as_stack_default(uuid, boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_decrypt_column_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: aisha_decrypt_column_audited
--
-- OWASP A02 — Cryptographic Failures. pgp_sym_decrypt helper that
-- (a) reads the active key via aisha_column_encryption_key()
-- (b) requires service_role or admin/staff role
-- (c) emits an audit_journal row for every successful decrypt — plaintext is
--     never logged, only "who saw what" metadata.
--
-- Encrypt side: see aisha_encrypt_column_audited.sql — emits a symmetric
-- 'crypto.column_encrypt' audit row so key use is traceable in both
-- directions, plaintext never logged.
--
-- ⛔ ZPEVNĚNÍ (b) 2026-09-29 — ŽÁDNÉ OBECNÉ DEŠIFROVACÍ ORÁKULUM:
--   · EXECUTE nemá žádná role kromě vlastníka. Dřív authenticated + service_role:
--     služba si šifrotext přečetla přes REST a dešifrovala přes RPC; admin/staff
--     dešifroval libovolný šifrotext, který získal. Změřeno 2026-09-29: jediný
--     volající v kódu je get_plugin_runtime_config (DEFINER, stráž „jen služba"),
--     na riq 0 dešifrování za celou historii — REVOKE nic nerozbije.
--   · Audit nese KONTEXT (p_kontext): účel, jméno klíče, plugin, zdroj, a roli
--     z JWT. Přes DEFINER je auth.uid() u služby NULL — bez kontextu audit nevěděl
--     ani kdo, ani co dešifroval. Hodnota ani délka se nezapisuje nikdy.
-- ============================================================================

DROP FUNCTION IF EXISTS public.aisha_decrypt_column_audited(bytea);

CREATE OR REPLACE FUNCTION public.aisha_decrypt_column_audited(
  p_ciphertext bytea,
  p_kontext    jsonb DEFAULT '{}'::jsonb
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
  v_plaintext text;
  v_is_service boolean;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'AISHA_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  IF p_ciphertext IS NULL THEN
    RETURN NULL;
  END IF;

  v_plaintext := pgp_sym_decrypt(p_ciphertext, public.aisha_column_encryption_key());

  -- Audit every decrypt — this is the data-access event. We DON'T log the
  -- plaintext, only the fact that decryption happened + by whom.
  INSERT INTO public.audit_journal (user_id, user_role, action, action_type, area, severity, tags,
                                    entity_type, entity_id, details)
  VALUES (auth.uid(), public.get_jwt_role(), 'crypto.column_decrypt', 'crypto.column_decrypt',
          'security', 'info', ARRAY['crypto','decrypt'],
          nullif(p_kontext->>'entita', ''), nullif(p_kontext->>'entita_id', ''),
          coalesce(p_kontext, '{}'::jsonb) - 'hodnota');

  RETURN v_plaintext;
END;
$$;
-- Jen vlastník (volají ho DEFINER funkce domova pověření). Žádný GRANT — brána to hlídá.
REVOKE ALL ON FUNCTION public.aisha_decrypt_column_audited(bytea, jsonb) FROM PUBLIC, anon, authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_encrypt_column_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: aisha_encrypt_column_audited
--
-- OWASP A02 — Cryptographic Failures. pgp_sym_encrypt helper that uses the
-- key from aisha_column_encryption_key(). Every encrypt is audited to
-- audit_journal as 'crypto.column_encrypt' — plaintext is NEVER stored, only
-- "who encrypted (something)" metadata. Matches the decrypt counterpart so
-- key use is symmetrically traceable.
--
-- Použití: JEN uvnitř SECURITY DEFINER funkce domova, která sama hlídá volajícího
-- (např. set_data_source_secrets), s kontextem pro audit:
--   public.aisha_encrypt_column_audited(v_hodnota,
--     jsonb_build_object('ucel', …, 'entita', …, 'entita_id', …, 'klic', …))
-- Role (anon/authenticated/service_role) EXECUTE nemají — přímé volání přes REST
-- by bylo obecné šifrovací/dešifrovací orákulum.
--
-- Requires the pgcrypto extension (installed via migrations).
-- ============================================================================

-- ⛔ ZPEVNĚNÍ (b) 2026-09-29: EXECUTE jen vlastník (volá ho set_data_source_secrets,
-- DEFINER); audit nese kontext (účel, klíč, zdroj, role z JWT) — symetricky s decrypt.
DROP FUNCTION IF EXISTS public.aisha_encrypt_column_audited(text);

CREATE OR REPLACE FUNCTION public.aisha_encrypt_column_audited(
  p_plaintext text,
  p_kontext   jsonb DEFAULT '{}'::jsonb
)
RETURNS bytea
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
  v_is_service boolean;
  v_ciphertext bytea;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'AISHA_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  IF p_plaintext IS NULL THEN
    RETURN NULL;
  END IF;

  v_ciphertext := pgp_sym_encrypt(p_plaintext, public.aisha_column_encryption_key());

  -- Audit every encrypt — symmetric with decrypt. Plaintext NEVER lands here;
  -- this only records "who used the encryption key" so key-use is traceable.
  INSERT INTO public.audit_journal (user_id, user_role, action, action_type, area, severity, tags,
                                    entity_type, entity_id, details)
  VALUES (auth.uid(), public.get_jwt_role(), 'crypto.column_encrypt', 'crypto.column_encrypt',
          'security', 'info', ARRAY['crypto','encrypt'],
          nullif(p_kontext->>'entita', ''), nullif(p_kontext->>'entita_id', ''),
          coalesce(p_kontext, '{}'::jsonb) - 'hodnota');

  RETURN v_ciphertext;
END;
$$;
-- Jen vlastník (volá ho set_data_source_secrets, DEFINER). Žádný GRANT — brána to hlídá.
REVOKE ALL ON FUNCTION public.aisha_encrypt_column_audited(text, jsonb) FROM PUBLIC, anon, authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_propose_static_defense_rule.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: aisha_propose_static_defense_rule
-- Popis: Insert nebo overwrite-draft rule v aisha_static_defense_rules. Pokud
--        rule_id už existuje a má status='active' nebo 'deprecated', vyhazuje
--        chybu — používej rather aisha_publish_static_defense_rule pro
--        status transitions a aisha_deprecate_static_defense_rule pro retire.
--
-- Volá:  WF_AISHA_TOOLING_OBSERVER (autonomous detection), Appsmith operator UI
-- Auth:  service_role nebo admin/staff
-- Audit: insert do audit_journal s decision_provenance chain
-- ============================================================================

CREATE OR REPLACE FUNCTION public.aisha_propose_static_defense_rule(
  p_rule_id              text,
  p_category             text,
  p_severity             text,
  p_owasp_category       text DEFAULT NULL,
  p_semgrep_pattern      jsonb DEFAULT NULL,
  p_semgrep_paths        jsonb DEFAULT NULL,
  p_semgrep_message      text DEFAULT NULL,
  p_languages            text[] DEFAULT ARRAY['typescript']::text[],
  p_rationale            text DEFAULT NULL,
  p_proposed_by          text DEFAULT NULL,
  p_decision_provenance  jsonb DEFAULT '[]'::jsonb
)
RETURNS public.aisha_static_defense_rules
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row        public.aisha_static_defense_rules;
  v_existing   public.aisha_static_defense_rules;
  v_is_service boolean;
  v_proposer   text;
BEGIN
  -- 1. Auth check (FIRST, before any data access — defense in depth)
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required'
      USING ERRCODE = '22023';
  END IF;

  -- 2. Input validation
  IF p_rule_id IS NULL OR length(p_rule_id) < 3 THEN
    RAISE EXCEPTION 'rule_id required (min 3 chars)' USING ERRCODE = '22023';
  END IF;
  IF p_rule_id !~ '^[a-z][a-z0-9-]+$' THEN
    RAISE EXCEPTION 'rule_id must be kebab-case (^[a-z][a-z0-9-]+$): %', p_rule_id
      USING ERRCODE = '22023';
  END IF;
  IF p_category NOT IN ('semgrep', 'eslint-no-secrets', 'owasp-exemption') THEN
    RAISE EXCEPTION 'Invalid category: % (must be semgrep, eslint-no-secrets, owasp-exemption)', p_category
      USING ERRCODE = '22023';
  END IF;
  IF p_severity NOT IN ('ERROR', 'WARNING', 'INFO') THEN
    RAISE EXCEPTION 'Invalid severity: %', p_severity USING ERRCODE = '22023';
  END IF;
  IF p_category = 'semgrep' AND p_semgrep_pattern IS NULL THEN
    RAISE EXCEPTION 'semgrep_pattern required for category=semgrep' USING ERRCODE = '22023';
  END IF;
  IF p_category = 'semgrep' AND p_semgrep_message IS NULL THEN
    RAISE EXCEPTION 'semgrep_message required for category=semgrep' USING ERRCODE = '22023';
  END IF;

  -- 3. Proposer identification — fallback chain: explicit p_proposed_by →
  --    auth.uid() string → 'aisha-autonomous' for service_role calls
  v_proposer := COALESCE(
    p_proposed_by,
    (auth.uid())::text,
    CASE WHEN v_is_service THEN 'aisha-autonomous' ELSE 'unknown' END
  );

  -- 4. Idempotency — UPDATE draft, INSERT if missing, REFUSE active/deprecated
  SELECT * INTO v_existing
  FROM public.aisha_static_defense_rules
  WHERE rule_id = p_rule_id;

  IF v_existing IS NOT NULL THEN
    IF v_existing.status = 'active' THEN
      RAISE EXCEPTION 'Rule "%" is active — use aisha_deprecate_static_defense_rule before re-proposing, or call propose with a new rule_id', p_rule_id
        USING ERRCODE = '22023';
    END IF;
    IF v_existing.status = 'deprecated' THEN
      RAISE EXCEPTION 'Rule "%" is deprecated — use a new rule_id for replacement', p_rule_id
        USING ERRCODE = '22023';
    END IF;

    -- Status is draft → overwrite the proposal (the previous draft must not
    -- yet have been published). Bump version so consumers can detect change.
    UPDATE public.aisha_static_defense_rules
    SET category         = p_category,
        owasp_category   = p_owasp_category,
        semgrep_pattern  = p_semgrep_pattern,
        semgrep_paths    = p_semgrep_paths,
        semgrep_message  = p_semgrep_message,
        languages        = COALESCE(p_languages, languages),
        severity         = p_severity,
        version          = version + 1,
        proposed_by      = v_proposer,
        rationale        = COALESCE(p_rationale, rationale)
        -- updated_at bumped by trigger
    WHERE rule_id = p_rule_id
    RETURNING * INTO v_row;
  ELSE
    INSERT INTO public.aisha_static_defense_rules (
      rule_id, category, owasp_category,
      semgrep_pattern, semgrep_paths, semgrep_message, languages,
      severity, status, version,
      proposed_by, rationale
    )
    VALUES (
      p_rule_id, p_category, p_owasp_category,
      p_semgrep_pattern, p_semgrep_paths, p_semgrep_message, p_languages,
      p_severity, 'draft', 1,
      v_proposer, p_rationale
    )
    RETURNING * INTO v_row;
  END IF;

  -- 5. Audit trail with decision_provenance chain
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'static_defense_rule_proposed',
    jsonb_build_object(
      'rule_id', p_rule_id,
      'category', p_category,
      'severity', p_severity,
      'owasp_category', p_owasp_category,
      'proposer', v_proposer,
      'version', v_row.version,
      'is_update', v_existing IS NOT NULL,
      'decision_provenance', p_decision_provenance
    )
  );

  RETURN v_row;
END;
$$;

REVOKE ALL ON FUNCTION public.aisha_propose_static_defense_rule(
  text, text, text, text, jsonb, jsonb, text, text[], text, text, jsonb
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aisha_propose_static_defense_rule(
  text, text, text, text, jsonb, jsonb, text, text[], text, text, jsonb
) TO authenticated;
