-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aitg_get_trust_score_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Function: aitg_get_trust_score_audited
-- Purpose: Single-number self-assessment for Aisha. Severity-weighted pass-rate
--          across all enabled tests over a sliding window. Returns 0..100
--          where 100 = every test passed every run, 0 = every test failed
--          every run.
-- AuthZ: admin/staff/service_role.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.aitg_get_trust_score_audited(p_window_days int DEFAULT 30)
RETURNS TABLE (
  trust_score      numeric,
  weighted_total   numeric,
  weighted_passed  numeric,
  measured_tests   int,
  failing_tests    int,
  window_days      int
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service_role boolean;
BEGIN
  v_is_service_role := public.is_service_role();
  IF NOT v_is_service_role AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'AITG_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (auth.uid(), 'aitg.trust_score_read', 'aitg.trust_score_read', 'security', 'info',
          ARRAY['aitg', 'trust'], jsonb_build_object('window_days', p_window_days));

  RETURN QUERY
  WITH coverage AS (
    SELECT c.test_id,
           c.severity_weight AS w,
           COUNT(r.run_id) FILTER (WHERE r.status IN ('passed', 'failed'))::numeric AS total,
           COUNT(r.run_id) FILTER (WHERE r.status = 'passed')::numeric AS passed,
           COUNT(r.run_id) FILTER (WHERE r.status = 'failed')::int AS failed
    FROM public.aitg_test_catalog c
    LEFT JOIN public.aitg_runs r
      ON r.test_id = c.test_id
     AND r.finished_at >= now() - (p_window_days || ' days')::interval
    WHERE c.enabled
    GROUP BY c.test_id, c.severity_weight
  )
  SELECT
    ROUND(
      COALESCE(SUM(passed * w) / NULLIF(SUM(total * w), 0), 0) * 100, 2
    ) AS trust_score,
    SUM(total * w) AS weighted_total,
    SUM(passed * w) AS weighted_passed,
    COUNT(*) FILTER (WHERE total > 0)::int AS measured_tests,
    COUNT(*) FILTER (WHERE failed > 0)::int AS failing_tests,
    p_window_days AS window_days
  FROM coverage;
END;
$$;

REVOKE ALL ON FUNCTION public.aitg_get_trust_score_audited(int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aitg_get_trust_score_audited(int) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aitg_get_trust_score_audited(int) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aitg_health_summary_audited.sql
-- -----------------------------------------------------------------------------

-- Function: aitg_health_summary_audited

CREATE OR REPLACE FUNCTION public.aitg_health_summary_audited(p_window_hours integer DEFAULT 24)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_service boolean;
  v_summary jsonb;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'AITG_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;

  WITH agg AS (
    SELECT
      COUNT(*) FILTER (WHERE r.status = 'passed')::int AS passed,
      COUNT(*) FILTER (WHERE r.status = 'failed')::int AS failed,
      COUNT(*)::int AS total
    FROM public.aitg_runs r
    WHERE r.finished_at >= now() - (p_window_hours || ' hours')::interval
  ),
  trust AS (
    SELECT trust_score, weighted_total, weighted_passed, measured_tests, failing_tests, window_days FROM public.aitg_get_trust_score_audited(
      GREATEST(1, (p_window_hours / 24)::int)
    ) LIMIT 1
  ),
  open_findings AS (
    SELECT COUNT(*)::int AS c FROM public.aitg_findings WHERE fixed_at IS NULL
  ),
  drift AS (
    SELECT COUNT(*)::int AS c FROM public.aitg_drift_alerts
    WHERE resolved_at IS NULL AND created_at >= now() - (p_window_hours || ' hours')::interval
  ),
  last_refl AS (
    SELECT reflection_date, trust_score_snapshot, summary
    FROM public.aitg_aisha_reflections
    ORDER BY reflection_date DESC LIMIT 1
  )
  SELECT jsonb_build_object(
    'window_hours', p_window_hours,
    'total_runs', COALESCE((SELECT total FROM agg), 0),
    'passed_runs', COALESCE((SELECT passed FROM agg), 0),
    'failed_runs', COALESCE((SELECT failed FROM agg), 0),
    'trust_score', (SELECT trust_score FROM trust),
    'open_findings', (SELECT c FROM open_findings),
    'open_drift_alerts', (SELECT c FROM drift),
    'last_reflection', (SELECT jsonb_build_object(
        'date', reflection_date,
        'trust_score', trust_score_snapshot,
        'summary', summary) FROM last_refl)
  ) INTO v_summary;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (auth.uid(), 'aitg.health_summary_read', 'aitg.health_summary_read',
          'security', 'info', ARRAY['aitg','health'], v_summary);

  RETURN v_summary;
END;
$function$

;

REVOKE ALL ON FUNCTION aitg_health_summary_audited(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION aitg_health_summary_audited(integer) TO authenticated;
GRANT EXECUTE ON FUNCTION aitg_health_summary_audited(integer) TO service_role;


