-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aitg_propose_remediation_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Function: aitg_propose_remediation_audited
-- Purpose: Aisha (or a human auditor) proposes a fix for an open finding.
--          Wires into improvement_proposals so the existing
--          WF_KNOWLEDGE_AGENT / WF_APPROVAL_GATE pipeline picks it up.
-- AuthZ: admin/staff/service_role. The proposal still goes through the
--        approval gate before any expert_rules / code change is applied —
--        so Aisha can SUGGEST but not unilaterally PATCH.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.aitg_propose_remediation_audited(
  p_finding_id  uuid,
  p_proposal    text,
  p_proposed_by text DEFAULT 'aisha'
) RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service_role boolean;
  v_finding         public.aitg_findings;
  v_test_id         text;
  v_proposal_id     uuid;
BEGIN
  v_is_service_role := public.is_service_role();
  IF NOT v_is_service_role AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'AITG_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;

  IF length(p_proposal) < 20 THEN
    RAISE EXCEPTION 'AITG_PROPOSAL_TOO_SHORT' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_finding FROM public.aitg_findings WHERE finding_id = p_finding_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'AITG_FINDING_NOT_FOUND' USING ERRCODE = '02000';
  END IF;
  IF v_finding.fixed_at IS NOT NULL THEN
    RAISE EXCEPTION 'AITG_FINDING_ALREADY_FIXED' USING ERRCODE = '22023';
  END IF;

  SELECT test_id INTO v_test_id FROM public.aitg_runs WHERE run_id = v_finding.run_id;

  -- Record proposal on the finding itself (lightweight; full lifecycle in
  -- improvement_proposals if that table exists in this deployment).
  UPDATE public.aitg_findings
  SET remediation = p_proposal
  WHERE finding_id = p_finding_id
  RETURNING finding_id INTO v_proposal_id;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (auth.uid(), 'aitg.remediation_proposed', 'aitg.remediation_proposed', 'security', 'info',
          ARRAY['aitg', 'remediation', v_test_id],
          jsonb_build_object('finding_id', p_finding_id, 'test_id', v_test_id,
                             'proposed_by', p_proposed_by));

  RETURN v_proposal_id;
END;
$$;

REVOKE ALL ON FUNCTION public.aitg_propose_remediation_audited(uuid, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aitg_propose_remediation_audited(uuid, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aitg_propose_remediation_audited(uuid, text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aitg_record_automation_run_audited.sql
-- -----------------------------------------------------------------------------

-- Function: aitg_record_automation_run_audited

CREATE OR REPLACE FUNCTION public.aitg_record_automation_run_audited(p_automation_id text, p_status text, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_is_service boolean;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'AITG_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  IF p_status NOT IN ('success','failed','skipped','running') THEN
    RAISE EXCEPTION 'AITG_INVALID_STATUS' USING ERRCODE = '22023';
  END IF;

  UPDATE public.aitg_automation_settings
  SET last_run_at = now(),
      last_run_status = p_status,
      last_run_details = p_details
  WHERE automation_id = p_automation_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'AITG_AUTOMATION_NOT_FOUND' USING ERRCODE = '02000';
  END IF;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (auth.uid(), 'aitg.automation_run_recorded', 'aitg.automation_run_recorded',
          'security',
          CASE p_status WHEN 'failed' THEN 'warn' WHEN 'skipped' THEN 'info' ELSE 'info' END,
          ARRAY['aitg','automation','run', p_automation_id, p_status],
          jsonb_build_object('automation_id', p_automation_id, 'status', p_status));
END;
$function$

;

REVOKE ALL ON FUNCTION aitg_record_automation_run_audited(text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION aitg_record_automation_run_audited(text,text,jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION aitg_record_automation_run_audited(text,text,jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aitg_record_reflection_audited.sql
-- -----------------------------------------------------------------------------

-- Function: aitg_record_reflection_audited

CREATE OR REPLACE FUNCTION public.aitg_record_reflection_audited(p_summary text, p_proposed_actions jsonb DEFAULT '[]'::jsonb, p_generated_by text DEFAULT 'aisha'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_service boolean;
  v_id uuid;
  v_today date := current_date;
  v_trust numeric;
  v_prev_trust numeric;
  v_total int;
  v_failed int;
  v_open int;
  v_new_failures int;
  v_newly_fixed int;
  v_drifts int;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'AITG_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  IF length(p_summary) < 10 THEN
    RAISE EXCEPTION 'AITG_REFLECTION_SUMMARY_TOO_SHORT' USING ERRCODE = '22023';
  END IF;

  SELECT trust_score INTO v_trust FROM public.aitg_get_trust_score_audited(1) LIMIT 1;
  SELECT trust_score_snapshot INTO v_prev_trust
  FROM public.aitg_aisha_reflections
  WHERE generated_by = p_generated_by AND reflection_date < v_today
  ORDER BY reflection_date DESC LIMIT 1;

  SELECT
    COUNT(*) FILTER (WHERE r.finished_at >= now() - interval '24 hours')::int,
    COUNT(*) FILTER (WHERE r.status = 'failed' AND r.finished_at >= now() - interval '24 hours')::int
  INTO v_total, v_failed
  FROM public.aitg_runs r;

  SELECT COUNT(*)::int INTO v_open FROM public.aitg_findings WHERE fixed_at IS NULL;
  SELECT COUNT(*)::int INTO v_new_failures
    FROM public.aitg_findings WHERE fixed_at IS NULL
      AND finding_id IN (
        SELECT f.finding_id FROM public.aitg_findings f
        JOIN public.aitg_runs r ON r.run_id = f.run_id
        WHERE r.finished_at >= now() - interval '24 hours'
      );
  SELECT COUNT(*)::int INTO v_newly_fixed FROM public.aitg_findings
    WHERE fixed_at >= now() - interval '24 hours';
  SELECT COUNT(*)::int INTO v_drifts FROM public.aitg_drift_alerts
    WHERE resolved_at IS NULL AND created_at >= now() - interval '24 hours';

  INSERT INTO public.aitg_aisha_reflections (
    reflection_date, trust_score_snapshot, trust_score_delta,
    total_runs_window, failed_runs_window, open_findings_count,
    new_failures_count, newly_fixed_count, drift_alerts_count,
    summary, proposed_actions, generated_by
  ) VALUES (
    v_today, COALESCE(v_trust, 0), v_trust - v_prev_trust,
    v_total, v_failed, v_open,
    v_new_failures, v_newly_fixed, v_drifts,
    p_summary, p_proposed_actions, p_generated_by
  )
  ON CONFLICT (reflection_date, generated_by) DO UPDATE SET
    summary = EXCLUDED.summary,
    proposed_actions = EXCLUDED.proposed_actions,
    trust_score_snapshot = EXCLUDED.trust_score_snapshot,
    trust_score_delta = EXCLUDED.trust_score_delta
  RETURNING reflection_id INTO v_id;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (auth.uid(), 'aitg.reflection_recorded', 'aitg.reflection_recorded', 'security', 'info',
          ARRAY['aitg','reflection', p_generated_by],
          jsonb_build_object('reflection_id', v_id, 'trust_score', v_trust,
                              'delta', v_trust - v_prev_trust, 'open_findings', v_open));

  RETURN v_id;
END;
$function$

;

REVOKE ALL ON FUNCTION aitg_record_reflection_audited(text,jsonb,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION aitg_record_reflection_audited(text,jsonb,text) TO authenticated;
GRANT EXECUTE ON FUNCTION aitg_record_reflection_audited(text,jsonb,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aitg_record_run_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Function: aitg_record_run_audited
-- Purpose: Append-only record of a single AITG test execution.
-- AuthZ: admin, staff, OR service_role (service_role used by svc-aitg-probes
--        + Aisha's MCP tool surface).
-- Side effects: writes to aitg_runs AND audit_journal (action='aitg.run_recorded').
-- ============================================================================

CREATE OR REPLACE FUNCTION public.aitg_record_run_audited(
  p_test_id      text,
  p_build_sha    text,
  p_triggered_by text,
  p_status       aitg_status,
  p_severity     aitg_severity,
  p_evidence_uri text,
  p_ai_run_id    uuid,
  p_details      jsonb
) RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_run_id           uuid;
  v_is_service_role  boolean;
BEGIN
  v_is_service_role := public.is_service_role();
  IF NOT v_is_service_role AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'AITG_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.aitg_runs (test_id, build_sha, triggered_by, status, severity,
                                evidence_uri, ai_run_id, details, finished_at)
  VALUES (p_test_id, p_build_sha, p_triggered_by, p_status, p_severity,
          p_evidence_uri, p_ai_run_id, p_details, now())
  RETURNING run_id INTO v_run_id;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details, metadata)
  VALUES (
    auth.uid(),
    'aitg.run_recorded',
    'aitg.run_recorded',
    'security',
    CASE p_status WHEN 'failed' THEN 'warn' WHEN 'blocked' THEN 'warn' ELSE 'info' END,
    ARRAY['aitg', p_test_id, p_status::text],
    jsonb_build_object('test_id', p_test_id, 'build_sha', p_build_sha,
                       'status', p_status, 'severity', p_severity, 'run_id', v_run_id),
    p_details
  );

  RETURN v_run_id;
END;
$$;

REVOKE ALL ON FUNCTION public.aitg_record_run_audited(text, text, text, aitg_status, aitg_severity, text, uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aitg_record_run_audited(text, text, text, aitg_status, aitg_severity, text, uuid, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aitg_record_run_audited(text, text, text, aitg_status, aitg_severity, text, uuid, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aitg_request_waiver_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Function: aitg_request_waiver_audited
-- Purpose: Aisha or a human requests a time-bound waiver for a failing test.
--          The function INSERTS the waiver but only an admin can actually
--          approve it via approved_by — service_role calls leave approved_by
--          set to a marker UUID and the row is "pending" until human flips it
--          to approved.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.aitg_request_waiver_audited(
  p_test_id       text,
  p_scope         jsonb,
  p_justification text,
  p_expires_at    timestamptz
) RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service_role boolean;
  v_approver        uuid;
  v_waiver_id       uuid;
BEGIN
  v_is_service_role := public.is_service_role();
  IF NOT v_is_service_role AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'AITG_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;

  IF p_expires_at <= now() THEN
    RAISE EXCEPTION 'AITG_WAIVER_EXPIRY_IN_PAST' USING ERRCODE = '22023';
  END IF;
  IF p_expires_at > now() + interval '90 days' THEN
    RAISE EXCEPTION 'AITG_WAIVER_EXPIRY_TOO_FAR' USING ERRCODE = '22023';
  END IF;

  -- approved_by is required NOT NULL on the table; for self-service requests
  -- we set the requester (admin) or a system marker for service_role.
  v_approver := COALESCE(auth.uid(),
    (SELECT id FROM aisha_auth.users WHERE email LIKE 'system@%' LIMIT 1));
  IF v_approver IS NULL THEN
    RAISE EXCEPTION 'AITG_WAIVER_NO_APPROVER' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.aitg_waivers (test_id, scope, justification, approved_by, expires_at)
  VALUES (p_test_id, p_scope, p_justification, v_approver, p_expires_at)
  RETURNING waiver_id INTO v_waiver_id;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (auth.uid(), 'aitg.waiver_requested', 'aitg.waiver_requested', 'security', 'warn',
          ARRAY['aitg', 'waiver', p_test_id],
          jsonb_build_object('waiver_id', v_waiver_id, 'test_id', p_test_id,
                             'expires_at', p_expires_at,
                             'requested_by_service_role', v_is_service_role));

  RETURN v_waiver_id;
END;
$$;

REVOKE ALL ON FUNCTION public.aitg_request_waiver_audited(text, jsonb, text, timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aitg_request_waiver_audited(text, jsonb, text, timestamptz) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aitg_request_waiver_audited(text, jsonb, text, timestamptz) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aitg_trigger_automation_audited.sql
-- -----------------------------------------------------------------------------

-- Function: aitg_trigger_automation_audited

CREATE OR REPLACE FUNCTION public.aitg_trigger_automation_audited(p_automation_id text, p_initiator text DEFAULT 'operator'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.aitg_automation_settings;
  v_trigger_id uuid := gen_random_uuid();
  v_is_service boolean;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'AITG_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row FROM public.aitg_automation_settings WHERE automation_id = p_automation_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'AITG_AUTOMATION_NOT_FOUND' USING ERRCODE = '02000';
  END IF;
  IF v_row.mode = 'disabled' THEN
    RAISE EXCEPTION 'AITG_AUTOMATION_DISABLED' USING ERRCODE = '22023';
  END IF;

  -- Record running status; the workflow webhook is responsible for the
  -- actual execution (via aitg_record_automation_run_audited on completion).
  UPDATE public.aitg_automation_settings
  SET last_run_at = now(),
      last_run_status = 'running',
      last_run_details = jsonb_build_object('trigger_id', v_trigger_id, 'initiator', p_initiator,
                                             'requested_at', now())
  WHERE automation_id = p_automation_id;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (auth.uid(), 'aitg.automation_triggered', 'aitg.automation_triggered',
          'security', 'info', ARRAY['aitg','automation','trigger', p_automation_id],
          jsonb_build_object('automation_id', p_automation_id, 'trigger_id', v_trigger_id,
                              'initiator', p_initiator, 'mode_at_trigger', v_row.mode,
                              'workflow_id', v_row.workflow_id));

  RETURN v_trigger_id;
END;
$function$

;

REVOKE ALL ON FUNCTION aitg_trigger_automation_audited(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION aitg_trigger_automation_audited(text,text) TO authenticated;
GRANT EXECUTE ON FUNCTION aitg_trigger_automation_audited(text,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_list_approved_sources.sql
-- -----------------------------------------------------------------------------

-- Function: public.audience_list_approved_sources
-- ENT-01 multi-source enumeration (SOURCE_ONBOARDING_CONTRACT §6/§7): returns the
-- APPROVED, ACTIVE federated sources over the story federation spine so the broker
-- (svc-source-broker scheduler) can sync EVERY approved source per-source, instead
-- of pinning to one hardcoded slug. A source is a story (partner_stories)
-- materialised on an active instance (story_instances) that carries a live
-- source_pg_readonly endpoint binding AND whose metadata.source_approved = true.
--
-- Namespace scoping (contract §6, "caller's namespace"): when p_namespace is
-- supplied only sources in that namespace are returned; the trusted broker
-- (service_role) passes NULL to enumerate all approved sources it must drain.
--
-- Security: SECURITY DEFINER, search_path pinned. Operator (admin/staff) OR trusted
--   service only (NULL-safe deny-guard, mirroring audience_resolve_source_binding).
--   Returns the credential REFERENCE (auth_secret_ref), never the secret. The
--   `audience_` prefix auto-inherits audience_autorevoke_public_execute (revokes
--   PUBLIC/anon EXECUTE) + the audience_audit_grants regression gate.

CREATE OR REPLACE FUNCTION public.audience_list_approved_sources(
  p_namespace text DEFAULT NULL
)
  RETURNS TABLE (
    source_id        uuid,
    story_id         uuid,
    source_slug      text,
    namespace        text,
    data_sensitivity text,
    endpoint_url     text,
    auth_secret_ref  text,
    last_sync_at     timestamp with time zone
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    si.id                                     AS source_id,
    si.story_id                               AS story_id,
    ps.title                                  AS source_slug,
    si.metadata ->> 'namespace'               AS namespace,
    si.metadata ->> 'data_sensitivity'        AS data_sensitivity,
    b.endpoint_url                            AS endpoint_url,
    b.auth_secret_ref                         AS auth_secret_ref,
    si.last_sync_at                           AS last_sync_at
  FROM public.story_instances si
  JOIN public.partner_stories ps
    ON ps.id = si.story_id
  JOIN public.instance_endpoint_bindings b
    ON b.instance_id = si.id
   AND b.endpoint_role = 'source_pg_readonly'
   AND b.is_active = true
  WHERE si.status = 'active'
    AND COALESCE((si.metadata ->> 'source_approved')::boolean, false) = true
    AND (p_namespace IS NULL OR si.metadata ->> 'namespace' = p_namespace)
  ORDER BY ps.title, si.instance_label;
END;
$function$;

COMMENT ON FUNCTION public.audience_list_approved_sources(text) IS
  'ENT-01 multi-source enumeration: approved + active federated sources over the '
  'story spine (story_instances + instance_endpoint_bindings, metadata.source_approved), '
  'optionally scoped to a namespace. Returns endpoint + credential REFERENCE (not the '
  'secret). Admin/staff or service_role only. Drives svc-source-broker per-source sync.';

REVOKE ALL ON FUNCTION public.audience_list_approved_sources(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.audience_list_approved_sources(text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_resolve_source_binding.sql
-- -----------------------------------------------------------------------------

-- Function: public.audience_resolve_source_binding
-- Description: Generic source-connection resolver over the story federation spine.
--   Replaces the broker's hardcoded SOURCE_PG_URL env with a per-source lookup:
--   a federated source IS a story (partner_stories), materialized on an instance
--   (story_instances), whose connection endpoints live in instance_endpoint_bindings
--   (endpoint_role + endpoint_url + auth_secret_ref). This is what makes live-read
--   generalize to N sources / N forks — each downstream fork registers its own
--   source story + binding; nothing fork-specific is hardcoded upstream.
--
--   Returns the endpoint + credential REFERENCE (never the secret itself — the
--   broker resolves auth_secret_ref against its own secret store), the declared
--   data_sensitivity, and whether the source is APPROVED. A caller MUST refuse to
--   read an unapproved source: this is the tie between approve_source (governance)
--   and the live read (which #572 left fully decoupled).
--
-- Security: SECURITY DEFINER, search_path pinned. Operator (admin/staff) OR trusted
--   service only, via the NULL-safe is_service_role() so the deny-guard is total.
--   The `audience_` prefix auto-inherits audience_autorevoke_public_execute (revokes
--   PUBLIC/anon EXECUTE) and the audience_audit_grants I1-I6 regression gate.

CREATE OR REPLACE FUNCTION public.audience_resolve_source_binding(
  p_story_id uuid,
  p_endpoint_role text DEFAULT 'source_pg_readonly'
)
  RETURNS TABLE (
    instance_id       uuid,
    endpoint_url      text,
    auth_method       text,
    auth_secret_ref   text,
    data_sensitivity  text,
    is_approved       boolean
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
AS $$
DECLARE
  v_instance public.story_instances%ROWTYPE;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  -- Resolve the story's active materialization (origin preferred).
  SELECT si.* INTO v_instance
  FROM public.story_instances si
  WHERE si.story_id = p_story_id
    AND si.status = 'active'
  ORDER BY si.is_origin DESC, si.updated_at DESC
  LIMIT 1;

  IF v_instance.id IS NULL THEN
    RAISE EXCEPTION 'No active instance materializes story %', p_story_id
      USING ERRCODE = 'no_data_found';
  END IF;

  -- Classification + approval live on the instance metadata (source-onboarding
  -- lifecycle, transitioned by audience_admin_approve_source). Fail-closed
  -- defaults: unclassified => 'restricted', unapproved => false.
  RETURN QUERY
  SELECT
    b.instance_id,
    b.endpoint_url,
    b.auth_method,
    b.auth_secret_ref,
    COALESCE(v_instance.metadata ->> 'data_sensitivity', 'restricted'),
    COALESCE((v_instance.metadata ->> 'source_approved')::boolean, false)
  FROM public.instance_endpoint_bindings b
  WHERE b.instance_id = v_instance.id
    AND b.endpoint_role = p_endpoint_role
    AND b.is_active = true;
END;
$$;

REVOKE ALL ON FUNCTION public.audience_resolve_source_binding(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.audience_resolve_source_binding(uuid, text) TO authenticated, service_role;

COMMENT ON FUNCTION public.audience_resolve_source_binding(uuid, text) IS
  'Generic source-connection resolver over the story federation spine (story_instances '
  '+ instance_endpoint_bindings). Replaces the hardcoded SOURCE_PG_URL env so live-read '
  'generalises to N sources/forks. Returns endpoint + credential REFERENCE (not the secret) '
  '+ data_sensitivity + is_approved; callers must refuse unapproved sources. Admin/service only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_sync_source_catalog.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: audience_sync_source_catalog
-- Popis: Přelije jednu dávku katalogu zdroje (listCatalog adaptéru) do
--        source_catalog_rows. Volá jen svc-source-broker pod service_role.
--
-- Režimy (SourceCatalogMode, packages/audience-types):
--   snapshot  dávka = CELÁ množina. Upsert + smazání řádků (zdroj, druh), které
--             v dávce nejsou — co ve zdroji zmizelo, zmizí i tady.
--   series    dávka = přírůstek. Jen upsert, starší řádky zůstávají (historie,
--             kterou zdroj sám nedrží — např. denní snímky KPI).
--
-- ⛔ PRÁZDNÁ DÁVKA NEVYMAŽE NEPRÁZDNÝ SNAPSHOT (p_allow_empty=false). Adaptér
-- při chybě vyhazuje, ale oříznutý / prázdný výsledek ze špatně nastavené role
-- nebo prázdné repliky by jinak smazal dobrá data. Vrátí se `refused_empty`
-- a broker to zaloguje; vědomé vyprázdnění = p_allow_empty=true.
--
-- Vstup p_rows = jsonb pole SourceCatalogRow v camelCase:
--   [{"externalId": "…", "occurredAt": "ISO|null", "fields": {…skaláry…}}]
-- Duplicitní externalId v jedné dávce vyhraje POSLEDNÍ výskyt.
-- Výstup: {"kind","mode","upserted","removed","refused_empty"}.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.audience_sync_source_catalog(
  p_source_slug text,
  p_kind text,
  p_mode text,
  p_rows jsonb,
  p_allow_empty boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_upserted int := 0;
  v_removed  int := 0;
  v_existing int := 0;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'audience_sync_source_catalog: service role only' USING ERRCODE = '42501';
  END IF;
  IF coalesce(p_source_slug, '') = '' THEN
    RAISE EXCEPTION 'audience_sync_source_catalog: source_slug is required' USING ERRCODE = '22023';
  END IF;
  IF p_kind IS NULL OR p_kind !~ '^[a-z][a-z0-9_]{1,39}$' THEN
    RAISE EXCEPTION 'audience_sync_source_catalog: kind must match ^[a-z][a-z0-9_]{1,39}$ (got %)', p_kind
      USING ERRCODE = '22023';
  END IF;
  IF p_mode IS NULL OR p_mode NOT IN ('snapshot', 'series') THEN
    RAISE EXCEPTION 'audience_sync_source_catalog: mode must be snapshot|series (got %)', p_mode
      USING ERRCODE = '22023';
  END IF;
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'audience_sync_source_catalog: rows must be a json array' USING ERRCODE = '22023';
  END IF;
  -- Řádek bez identity nebo s vnořeným polem je vadný adaptér — odmítne se CELÁ
  -- dávka, ne jen řádek: u snapshotu by vynechaný řádek znamenal smazání.
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_rows) r
     WHERE coalesce(r->>'externalId', '') = ''
        OR (r ? 'fields' AND jsonb_typeof(r->'fields') <> 'object')
        OR EXISTS (SELECT 1 FROM jsonb_each(coalesce(r->'fields', '{}'::jsonb)) f
                    WHERE jsonb_typeof(f.value) IN ('object', 'array'))
  ) THEN
    RAISE EXCEPTION 'audience_sync_source_catalog: every row needs externalId and scalar fields (kind %)', p_kind
      USING ERRCODE = '22023';
  END IF;

  IF p_mode = 'snapshot' AND jsonb_array_length(p_rows) = 0 AND NOT coalesce(p_allow_empty, false) THEN
    SELECT count(*) INTO v_existing FROM public.source_catalog_rows
     WHERE source_slug = p_source_slug AND kind = p_kind;
    IF v_existing > 0 THEN
      RETURN jsonb_build_object('kind', p_kind, 'mode', p_mode,
        'upserted', 0, 'removed', 0, 'refused_empty', true);
    END IF;
  END IF;

  WITH davka AS (
    SELECT DISTINCT ON (r->>'externalId')
           r->>'externalId' AS external_id,
           nullif(r->>'occurredAt', '')::timestamptz AS occurred_at,
           coalesce(r->'fields', '{}'::jsonb) AS fields
      FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS t(r, ord)
     ORDER BY r->>'externalId', ord DESC
  ), zapsano AS (
    INSERT INTO public.source_catalog_rows AS c
      (source_slug, kind, external_id, occurred_at, fields, first_seen_at, synced_at)
    SELECT p_source_slug, p_kind, d.external_id, d.occurred_at, d.fields, now(), now()
      FROM davka d
    ON CONFLICT (source_slug, kind, external_id) DO UPDATE SET
      occurred_at = EXCLUDED.occurred_at,
      fields      = EXCLUDED.fields,
      synced_at   = now()
    RETURNING 1
  )
  SELECT count(*) INTO v_upserted FROM zapsano;

  IF p_mode = 'snapshot' THEN
    WITH smazano AS (
      DELETE FROM public.source_catalog_rows c
       WHERE c.source_slug = p_source_slug
         AND c.kind = p_kind
         -- NOT IN nad poddotazem = hashovaný subplan (jedno sestavení množiny),
         -- ne průchod dávkou pro každý řádek. NULL v dávce být nemůže (ověřeno výš).
         AND c.external_id NOT IN (SELECT r->>'externalId' FROM jsonb_array_elements(p_rows) r)
      RETURNING 1
    )
    SELECT count(*) INTO v_removed FROM smazano;
  END IF;

  RETURN jsonb_build_object('kind', p_kind, 'mode', p_mode,
    'upserted', v_upserted, 'removed', v_removed, 'refused_empty', false);
END;
$function$;

REVOKE ALL ON FUNCTION public.audience_sync_source_catalog(text, text, text, jsonb, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.audience_sync_source_catalog(text, text, text, jsonb, boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_upsert_source_stat.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: audience_upsert_source_stat
-- Popis: Uloží/aktualizuje jeden řádek měsíční statistiky zdroje (téma nebo
--        událost vzniklá v daném měsíci), jak ji doručil svc-source-broker
--        z adaptéru (listStats). Idempotentní na (zdroj, druh, měsíc, id).
-- Bezpečnost: SECURITY DEFINER; volá jen broker pod service_role. Vstup je
--        jsonb v camelCase tvaru StatRow (packages/audience-types), NE sloupce —
--        tak se řádek nerozbije, když adaptér přidá pole, které tabulka nezná.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.audience_upsert_source_stat(
  p_kind text, p_month text, p_external_id text, p_row jsonb, p_source_slug text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'audience_upsert_source_stat: service role only' USING ERRCODE = '42501';
  END IF;
  IF p_kind NOT IN ('topic', 'event') THEN
    RAISE EXCEPTION 'audience_upsert_source_stat: kind must be topic|event (got %)', p_kind USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.source_period_stats (
    source_slug, kind, month, external_id, title, created_by, created_by_id, created_at, date_from, date_to,
    deleted, is_private, official, cancelled, online, follow_count, posts_count, tags, synced_at
  ) VALUES (
    p_source_slug, p_kind, p_month, p_external_id,
    coalesce(p_row->>'title', ''),
    coalesce(p_row->>'createdBy', ''),
    coalesce(p_row->>'createdById', ''),
    nullif(p_row->>'createdAt', '')::timestamptz,
    nullif(p_row->>'dateFrom', '')::timestamptz,
    nullif(p_row->>'dateTo', '')::timestamptz,
    coalesce((p_row->>'deleted')::boolean, false),
    coalesce((p_row->>'private')::boolean, false),
    coalesce((p_row->>'official')::boolean, false),
    coalesce((p_row->>'cancelled')::boolean, false),
    coalesce((p_row->>'online')::boolean, false),
    coalesce((p_row->>'followCount')::int, 0),
    coalesce((p_row->>'postsCount')::int, 0),
    coalesce(p_row->>'tags', ''),
    now()
  )
  ON CONFLICT (source_slug, kind, month, external_id) DO UPDATE SET
    title = EXCLUDED.title, created_by = EXCLUDED.created_by,
    created_by_id = EXCLUDED.created_by_id, created_at = EXCLUDED.created_at,
    date_from = EXCLUDED.date_from, date_to = EXCLUDED.date_to,
    deleted = EXCLUDED.deleted, is_private = EXCLUDED.is_private, official = EXCLUDED.official,
    cancelled = EXCLUDED.cancelled, online = EXCLUDED.online,
    follow_count = EXCLUDED.follow_count, posts_count = EXCLUDED.posts_count, tags = EXCLUDED.tags,
    synced_at = now();
END;
$function$;
REVOKE ALL ON FUNCTION public.audience_upsert_source_stat(text, text, text, jsonb, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.audience_upsert_source_stat(text, text, text, jsonb, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/bootstrap_story_replica.sql
-- -----------------------------------------------------------------------------

-- Function: public.bootstrap_story_replica
-- Arguments: p_manifest jsonb, p_manifest_hash text, p_instance_label text DEFAULT 'replica', p_instance_type text DEFAULT 'self-hosted'
-- Description: Bootstraps a replica of a story on this instance from a portable
--              manifest (produced by export_story_bundle on the origin stack).
--              Verifies SHA-256 manifest integrity, then idempotently creates:
--              1. partner_stories row with the SAME id as the origin story
--                 (origin 'replica_sync', no partner/user binding)
--              2. story_contexts row (defaults; filled by subsequent import)
--              3. a non-origin story_instances row for this replica
--              Safe to re-run: existing rows are kept untouched.
-- Security: SECURITY DEFINER — service_role or admin/staff only.
--           DEFINER (not INVOKER per ensure_stack_default_story) because
--           story_instances has RLS enabled with NO policies, so an admin/staff
--           invoker could never INSERT the replica instance row under INVOKER
--           semantics. Explicit role check below compensates.

CREATE OR REPLACE FUNCTION public.bootstrap_story_replica(
  p_manifest jsonb,
  p_manifest_hash text,
  p_instance_label text DEFAULT 'replica',
  p_instance_type text DEFAULT 'self-hosted'
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_is_service boolean;
  v_computed_hash text;
  v_story_id_text text;
  v_story_id uuid;
  v_metadata jsonb;
  v_project_preview jsonb;
  v_existing_story_id uuid;
  v_existing_context_story_id uuid;
  v_instance_id uuid;
  v_created_story boolean := false;
  v_created_context boolean := false;
  v_created_instance boolean := false;
BEGIN
  -- ===== AUTHORIZATION: service_role or admin/staff =====
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin/staff or service_role required' USING ERRCODE = '22023';
  END IF;

  -- ===== INTEGRITY VERIFICATION =====
  v_computed_hash := encode(digest(p_manifest::text, 'sha256'), 'hex');
  IF v_computed_hash != p_manifest_hash THEN
    RAISE EXCEPTION 'Manifest hash mismatch — expected %, computed %',
      p_manifest_hash, v_computed_hash USING ERRCODE = '22023';
  END IF;

  v_metadata := p_manifest->'story_metadata';
  v_story_id_text := v_metadata->>'id';
  IF v_story_id_text IS NULL
     OR v_story_id_text !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    RAISE EXCEPTION 'Invalid or missing story id in manifest' USING ERRCODE = '22023';
  END IF;
  v_story_id := v_story_id_text::uuid;

  -- ===== 1. partner_stories (same id as origin story) =====
  SELECT id INTO v_existing_story_id
  FROM partner_stories
  WHERE id = v_story_id;

  IF v_existing_story_id IS NULL THEN
    -- project_preview must satisfy the shape check constraint
    v_project_preview := v_metadata->'project_preview';
    IF v_project_preview IS NULL
       OR jsonb_typeof(v_project_preview) != 'object'
       OR NOT (v_project_preview ?& ARRAY['summary', 'goals', 'constraints', 'success_criteria']) THEN
      v_project_preview := '{"summary":"","goals":[],"constraints":[],"success_criteria":[],"meta":{}}'::jsonb;
    END IF;

    INSERT INTO partner_stories (
      id, partner_id, user_id, title, status,
      tech_stack, domain, project_preview, risk_profile,
      repo_url, repo_provider, default_branch, origin
    ) VALUES (
      v_story_id, NULL, NULL,
      COALESCE(v_metadata->>'title', 'Replicated story'),
      COALESCE(v_metadata->>'status', 'active'),
      CASE WHEN jsonb_typeof(v_metadata->'tech_stack') = 'array'
        THEN ARRAY(SELECT jsonb_array_elements_text(v_metadata->'tech_stack'))
        ELSE NULL END,
      CASE WHEN jsonb_typeof(v_metadata->'domain') = 'array'
        THEN ARRAY(SELECT jsonb_array_elements_text(v_metadata->'domain'))
        ELSE NULL END,
      v_project_preview,
      v_metadata->>'risk_profile',
      v_metadata->>'repo_url',
      v_metadata->>'repo_provider',
      v_metadata->>'default_branch',
      'replica_sync'
    );
    v_created_story := true;
  END IF;

  -- ===== 2. story_contexts (PK on story_id — check-then-insert) =====
  SELECT story_id INTO v_existing_context_story_id
  FROM story_contexts
  WHERE story_id = v_story_id;

  IF v_existing_context_story_id IS NULL THEN
    INSERT INTO story_contexts (story_id) VALUES (v_story_id);
    v_created_context := true;
  END IF;

  -- ===== 3. story_instances (non-origin replica instance) =====
  -- Concurrency-safe upsert backed by the partial unique index
  -- idx_story_instances_replica_label_unique (story_id, instance_label)
  -- WHERE is_origin = false — parallel bootstraps cannot duplicate the row.
  INSERT INTO story_instances (
    story_id, instance_label, instance_type, is_origin
  ) VALUES (
    v_story_id, p_instance_label, p_instance_type, false
  )
  ON CONFLICT (story_id, instance_label) WHERE is_origin = false
  DO NOTHING
  RETURNING id INTO v_instance_id;

  v_created_instance := FOUND;

  IF v_instance_id IS NULL THEN
    SELECT id INTO v_instance_id
    FROM story_instances
    WHERE story_id = v_story_id
      AND instance_label = p_instance_label
      AND is_origin = false
    ORDER BY created_at
    LIMIT 1;
  END IF;

  -- Audit journal (user_id nullable — service actors have auth.uid() NULL, FK-safe)
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'STORY_REPLICA_BOOTSTRAPPED', jsonb_build_object(
    'area', 'story_sync',
    'severity', 'info',
    'entity_type', 'partner_story',
    'entity_id', v_story_id,
    'instance_id', v_instance_id,
    'instance_label', p_instance_label,
    'manifest_hash', p_manifest_hash,
    'created_story', v_created_story,
    'created_context', v_created_context,
    'created_instance', v_created_instance
  ));

  RETURN jsonb_build_object(
    'story_id', v_story_id,
    'instance_id', v_instance_id,
    'created_story', v_created_story,
    'created_context', v_created_context,
    'created_instance', v_created_instance
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.bootstrap_story_replica(jsonb, text, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.bootstrap_story_replica(jsonb, text, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.bootstrap_story_replica(jsonb, text, text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/broker_quarantine_discard_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: broker_quarantine_discard_admin
-- Popis: Zahodí odložené (karanténované) balíčky zdroje ROZHODNUTÍM ČLOVĚKA —
--        se stopou původu a s možností vrácení.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (admin/staff nebo service_role)
--
-- ⛔ PROČ VZNIKLA. Naměřeno 2026-09-16 v produkci instance: tři balíčky ze 3.–4. 8.
--    ležely v `metadata->'karantena'` od té doby. Driver je při KAŽDÉM tiku hlásí
--    („balíčky v karanténě čekají na rozhodnutí — fronta jede dál"), ale vyřídit je
--    nešlo ničím: karanténa se vyprázdní jen tím, že se týž balíček znovu objeví
--    na disku a projde. Ty soubory už neexistují (retence exportu je dávno smazala),
--    takže by se seznam nevyprázdnil NIKDY. Varování, které nejde vyřídit, učí
--    operátora přehlížet varování.
--
-- ⭐ ZAHOZENÍ NENÍ ZTRÁTA DAT. Engine skládá korpus při každém běhu znovu ze vstupu
--    a exportuje ho CELÝ: obsah starého balíčku veze i ten dnešní (ověřeno 09-16 —
--    registr 4 923 řádků pokrývá doklady 2022–2026). Zahazuje se ZÁZNAM O ČEKÁNÍ,
--    ne doklady.
--
-- ⛔ VÝSLOVNÝ SEZNAM, NE „všechno staré". `p_export_ids` NULL = celá karanténa
--    zdroje, ale i tehdy se do rozhodnutí zapíše, co přesně se zahodilo —
--    aby vrácení vědělo, co obnovit, a aby šlo dohledat, co v seznamu bylo.
--
-- ⭐ NÁHLED JE VÝCHOZÍ (p_dry_run = true): vrátí, co by se zahodilo, a nic nezapíše.
--
-- ⭐ DOHLEDATELNÉ A VRATNÉ (zadání majitele 2026-09-15: „všechny tyto autonomní
--    kroky potřebujeme umět dohledat, dohledovat a případně zrušit a opravit
--    uživatelem z UI"). Ostrý běh = řádek audit_journal (entity_type
--    'broker_decision') s důvodem, kritériem a seznamem PŘED zahozením; vrácení
--    dělá revert_broker_quarantine_discard_admin, přehled get_decisions_admin.
--
-- Kontrakt: (text, text[], text, boolean) ->
--   jsonb {ok, dry_run, decision_id?, zahozeno, zbyva, nezname, kriterium} | {ok:false, error}
-- ============================================================================

CREATE OR REPLACE FUNCTION public.broker_quarantine_discard_admin(
  p_source_slug text,
  p_export_ids  text[] DEFAULT NULL,
  p_reason      text DEFAULT NULL,
  p_dry_run     boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_decision   uuid := gen_random_uuid();
  v_karantena  text[];
  v_zahodit    text[];
  v_zbyva      text[];
  v_nezname    text[];
  v_kriterium  jsonb;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff(auth.uid())) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nedostatečné oprávnění');
  END IF;
  IF coalesce(btrim(p_source_slug), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'p_source_slug je povinný');
  END IF;
  -- Důvod je povinný i u náhledu: rozhodnutí bez důvodu se nedá doložit, a kdo
  -- si ho vymyslí až u ostrého běhu, vymyslí ho jinak než ten, kdo náhled četl.
  IF coalesce(btrim(p_reason), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'důvod (p_reason) je povinný');
  END IF;

  SELECT array(SELECT jsonb_array_elements_text(coalesce(s.metadata->'karantena', '[]'::jsonb)))
    INTO v_karantena
    FROM public.audience_broker_sync_state s
   WHERE s.source_slug = p_source_slug;
  IF v_karantena IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error',
      format('zdroj %s nemá stav synchronizace — není co zahazovat', p_source_slug));
  END IF;

  v_zahodit := coalesce(
    ARRAY(SELECT x FROM unnest(v_karantena) x
           WHERE p_export_ids IS NULL OR x = ANY (p_export_ids)),
    ARRAY[]::text[]);
  v_zbyva := coalesce(
    ARRAY(SELECT x FROM unnest(v_karantena) x WHERE NOT (x = ANY (v_zahodit))),
    ARRAY[]::text[]);
  -- Id, které v karanténě není, se NEPŘEJDE MLČKY: buď je překlep, nebo už
  -- někdo zahodil dřív — a obojí má volající vidět.
  v_nezname := coalesce(
    ARRAY(SELECT x FROM unnest(coalesce(p_export_ids, ARRAY[]::text[])) x
           WHERE NOT (x = ANY (v_karantena))),
    ARRAY[]::text[]);

  v_kriterium := jsonb_build_object('source_slug', p_source_slug,
                                    'export_ids', to_jsonb(coalesce(p_export_ids, ARRAY[]::text[])));

  IF p_dry_run THEN
    RETURN jsonb_build_object('ok', true, 'dry_run', true,
                              'zahozeno', to_jsonb(v_zahodit), 'zbyva', to_jsonb(v_zbyva),
                              'nezname', to_jsonb(v_nezname), 'kriterium', v_kriterium);
  END IF;

  IF array_length(v_zahodit, 1) IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'v karanténě není nic, co by odpovídalo',
                              'nezname', to_jsonb(v_nezname), 'kriterium', v_kriterium);
  END IF;

  UPDATE public.audience_broker_sync_state s
     SET metadata = jsonb_set(coalesce(s.metadata, '{}'::jsonb), '{karantena}', to_jsonb(v_zbyva)),
         updated_at = now()
   WHERE s.source_slug = p_source_slug;

  INSERT INTO public.audit_journal (id, user_id, action, action_type, area, entity_type, entity_id,
                                    summary, details, metadata)
  VALUES (v_decision, auth.uid(), 'broker.quarantine_discarded', 'update', 'integrations',
          'broker_decision', v_decision::text,
          format('Karanténa zdroje %s: zahozeno %s balíčků — %s',
                 p_source_slug, array_length(v_zahodit, 1), p_reason),
          jsonb_build_object('duvod', p_reason, 'kriterium', v_kriterium,
                             'pocty', jsonb_build_object('zahozeno', array_length(v_zahodit, 1),
                                                         'zbyva', coalesce(array_length(v_zbyva, 1), 0)),
                             'zahozeno', to_jsonb(v_zahodit),
                             'pred_zahozenim', to_jsonb(v_karantena),
                             'vratne', true),
          jsonb_build_object('source_slug', p_source_slug,
                             'zahozeno', array_length(v_zahodit, 1)));

  RETURN jsonb_build_object('ok', true, 'dry_run', false, 'decision_id', v_decision,
                            'zahozeno', to_jsonb(v_zahodit), 'zbyva', to_jsonb(v_zbyva),
                            'nezname', to_jsonb(v_nezname), 'kriterium', v_kriterium);
END;
$function$;

REVOKE ALL ON FUNCTION public.broker_quarantine_discard_admin(text, text[], text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.broker_quarantine_discard_admin(text, text[], text, boolean) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/can_access_story.sql
-- -----------------------------------------------------------------------------

-- Function: public.can_access_story
-- Arguments: p_story_id uuid, p_for_write boolean DEFAULT false
-- Description: Smí volající (auth.uid() / service_role) na story? Jediný predikát
--   pro story-scoped SECURITY DEFINER RPC, které dřív nekontrolovaly NIC.
-- Security: SECURITY DEFINER
-- Search path: public
--
-- ⛔ NAMĚŘENO 2026-09-14: transition_story_delivery_status, get_allowed_transitions,
-- moderate_development_flow, mcp_get_compliance_context a generate_copilot_instructions
-- byly SECURITY DEFINER s GRANT authenticated a bez jakékoli kontroly story —
-- každý přihlášený mohl číst kontext a ruleset cizí story a měnit její
-- delivery_status. Příprava na MCP Client Tool (nástroje nad těmito RPC poběží
-- pod identitou uživatele / PAT) to z latentní díry dělá otevřenou.
--
-- Pravidla:
--   service_role, admin/staff  → vždy (strojová lane a správa)
--   vlastník story (partner_stories.user_id)  → čtení i zápis
--   účastník story  → čtení; zápis jen s rolí jinou než 'viewer'
--   kdokoli jiný, nepřihlášený, neexistující story  → false
-- Neexistující a cizí story vrací totéž (false) — volající stráž tak není orákulum
-- existence story.

CREATE OR REPLACE FUNCTION public.can_access_story(p_story_id uuid, p_for_write boolean DEFAULT false)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF public.is_service_role() OR public.is_admin_or_staff() THEN
    RETURN true;
  END IF;

  IF v_user_id IS NULL OR p_story_id IS NULL THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
           SELECT 1 FROM public.partner_stories ps
           WHERE ps.id = p_story_id AND ps.user_id = v_user_id
         )
      OR EXISTS (
           SELECT 1 FROM public.story_participants sp
           WHERE sp.story_id = p_story_id
             AND sp.user_id = v_user_id
             AND (NOT p_for_write OR sp.role <> 'viewer')
         );
END;
$function$;

REVOKE ALL ON FUNCTION public.can_access_story(uuid, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_access_story(uuid, boolean) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/can_enter_voice_room.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- can_enter_voice_room — JEDINÝ predikát „smí tahle osoba do hlasové místnosti“
-- =============================================================================
-- ⛔ NAMĚŘENO 2026-09-29 (docs/audit/2026-09-29-hlas-a-matrix-audit.md, H-5) a
-- 2026-10-01 (audit veřejného vydání, B2): o vstupu do místnosti nerozhodovalo
-- nic. svc-livekit /create-token kontroloval členství jen u místnosti se story,
-- takže token do KONZULTACE (story_id NULL, jméno `consultation-` + 8 hex znaků)
-- dostal kdokoli přihlášený, kdo jméno znal nebo uhodl — a zapsal se jako její
-- účastník. U konzultace navázané na story pustil každého člena story do hovoru
-- dvou lidí. RPC nad místnostmi (seznam účastníků, PTT místnost story) se
-- neptala vůbec.
--
-- Pravidla (podle druhu místnosti, ne podle toho, kdo se ptá):
--   consultation        → jen volající a volaný z consultation_sessions.
--                         Ani člen story, ani správa: hovor dvou lidí je soukromý.
--   se story (ptt, …)    → vlastník story nebo její účastník (jakákoli role).
--   bez story           → zakladatel, nebo kdo už v místnosti účast má.
--   neaktivní místnost  → nikdo.
-- Správa (admin/staff) VĚDOMĚ bez obchvatu — na rozdíl od can_access_story:
-- k obsahu story ano, do živého hovoru ne.
--
-- Odpovídá jen o VOLAJÍCÍM; služba se smí ptát na kohokoli (svc-livekit vydává
-- token jménem ověřeného uživatele). Tvar viz is_story_participant — predikát
-- o třetí osobě je orákulum. EXECUTE má jen service_role: definer funkce níž ho
-- volají s právy vlastníka, PostgREST ho nevystavuje.
-- =============================================================================

CREATE OR REPLACE FUNCTION public.can_enter_voice_room(p_voice_room_id uuid, p_user_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  SELECT (COALESCE(p_user_id = auth.uid(), false) OR public.is_service_role())
    AND EXISTS (
      SELECT 1
      FROM public.voice_rooms vr
      WHERE vr.id = p_voice_room_id
        AND vr.is_active
        AND CASE
          WHEN vr.room_type = 'consultation' THEN EXISTS (
            SELECT 1 FROM public.consultation_sessions cs
            WHERE cs.voice_room_id = vr.id
              AND p_user_id IN (cs.caller_id, cs.callee_id)
          )
          WHEN vr.story_id IS NOT NULL THEN
            EXISTS (
              SELECT 1 FROM public.partner_stories ps
              WHERE ps.id = vr.story_id AND ps.user_id = p_user_id
            )
            OR EXISTS (
              SELECT 1 FROM public.story_participants sp
              WHERE sp.story_id = vr.story_id AND sp.user_id = p_user_id
            )
          ELSE
            vr.created_by = p_user_id
            OR EXISTS (
              SELECT 1 FROM public.call_participants cp
              WHERE cp.voice_room_id = vr.id AND cp.user_id = p_user_id
            )
        END
    );
$function$;

REVOKE ALL ON FUNCTION public.can_enter_voice_room(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.can_enter_voice_room(uuid, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/can_receive_reward.sql
-- -----------------------------------------------------------------------------

-- Function: public.can_receive_reward
-- Arguments: p_user_id uuid, p_action_type text, p_token_type text
-- Description: Checks if user can receive a reward.
-- Security: SECURITY DEFINER with search_path + stráž volajícího (p_user_id = auth.uid(),
--   jinak jen service_role nebo admin/staff) — stejný tvar jako process_token_reward.
-- @audit: none (read-only check)

CREATE OR REPLACE FUNCTION public.can_receive_reward(p_user_id uuid, p_action_type text, p_token_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule record;
  v_daily_count integer;
  v_weekly_count integer;
  v_monthly_count integer;
  v_last_reward timestamptz;
  v_hours_since_last numeric;
BEGIN
  -- ⛔ PREDIKÁT O TŘETÍ OSOBĚ JE ORÁKULUM (naměřeno 2026-09-19). Odpověď nese
  -- členství (`Membership requirement not met`), počty odměn za den/týden/měsíc
  -- (`current_count`) i zbývající hodiny cooldownu — pro libovolné uuid, které
  -- přihlášený pošle. Sourozenec process_token_reward má stráž od 2026-07-15
  -- (docs/security/IDOR_P_USER_ID_AUDIT_2026-07-15.md); tahle funkce, kterou
  -- volá, ji neměla, takže týž údaj šel přečíst přímo.
  --
  -- Stráž je PŘESNĚ tvar sourozence: ptá se o sobě, nebo služba/správa. Změřeno,
  -- že to nic nerozbije: useCanReceiveReward (src/hooks/useTokens.ts) posílá
  -- `p_user_id: user.id`, tedy sebe, a process_token_reward předává p_user_id,
  -- který už prošel touž stráží. `auth.uid() IS NULL` je součást odmítnutí
  -- záměrně: bez něj by NULL uid a NULL p_user_id nebyly DISTINCT a anonym by
  -- prošel.
  IF NOT public.is_service_role()
     AND NOT public.is_admin_or_staff()
     AND (auth.uid() IS NULL OR p_user_id IS DISTINCT FROM auth.uid())
  THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  -- Get the reward rule
  SELECT * INTO v_rule
  FROM token_reward_rules
  WHERE action_type = p_action_type
    AND token_type = p_token_type
    AND is_active = true
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'can_receive', false,
      'reason', 'No active reward rule found for this action'
    );
  END IF;

  -- Check membership requirement
  IF v_rule.requires_membership THEN
    IF NOT EXISTS (
      SELECT 1 FROM memberships
      WHERE user_id = p_user_id
        AND status = 'active'
        AND (v_rule.membership_tier_required IS NULL OR tier::text = v_rule.membership_tier_required)
    ) THEN
      RETURN jsonb_build_object(
        'can_receive', false,
        'reason', 'Membership requirement not met'
      );
    END IF;
  END IF;

  -- Check daily limit
  IF v_rule.daily_limit IS NOT NULL THEN
    SELECT COUNT(*) INTO v_daily_count
    FROM token_transactions
    WHERE user_id = p_user_id
      AND token_type = p_token_type
      AND reference_type = p_action_type
      AND created_at >= CURRENT_DATE;
    
    IF v_daily_count >= v_rule.daily_limit THEN
      RETURN jsonb_build_object(
        'can_receive', false,
        'reason', 'Daily limit reached',
        'limit', v_rule.daily_limit,
        'current_count', v_daily_count
      );
    END IF;
  END IF;

  -- Check weekly limit
  IF v_rule.weekly_limit IS NOT NULL THEN
    SELECT COUNT(*) INTO v_weekly_count
    FROM token_transactions
    WHERE user_id = p_user_id
      AND token_type = p_token_type
      AND reference_type = p_action_type
      AND created_at >= date_trunc('week', CURRENT_TIMESTAMP);
    
    IF v_weekly_count >= v_rule.weekly_limit THEN
      RETURN jsonb_build_object(
        'can_receive', false,
        'reason', 'Weekly limit reached',
        'limit', v_rule.weekly_limit,
        'current_count', v_weekly_count
      );
    END IF;
  END IF;

  -- Check monthly limit
  IF v_rule.monthly_limit IS NOT NULL THEN
    SELECT COUNT(*) INTO v_monthly_count
    FROM token_transactions
    WHERE user_id = p_user_id
      AND token_type = p_token_type
      AND reference_type = p_action_type
      AND created_at >= date_trunc('month', CURRENT_TIMESTAMP);
    
    IF v_monthly_count >= v_rule.monthly_limit THEN
      RETURN jsonb_build_object(
        'can_receive', false,
        'reason', 'Monthly limit reached',
        'limit', v_rule.monthly_limit,
        'current_count', v_monthly_count
      );
    END IF;
  END IF;

  -- Check cooldown
  IF v_rule.cooldown_hours IS NOT NULL THEN
    SELECT created_at INTO v_last_reward
    FROM token_transactions
    WHERE user_id = p_user_id
      AND token_type = p_token_type
      AND reference_type = p_action_type
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_last_reward IS NOT NULL THEN
      v_hours_since_last := EXTRACT(EPOCH FROM (now() - v_last_reward)) / 3600;
      IF v_hours_since_last < v_rule.cooldown_hours THEN
        RETURN jsonb_build_object(
          'can_receive', false,
          'reason', 'Cooldown period active',
          'hours_remaining', v_rule.cooldown_hours - v_hours_since_last
        );
      END IF;
    END IF;
  END IF;

  -- All checks passed
  RETURN jsonb_build_object(
    'can_receive', true,
    'rule_id', v_rule.id,
    'base_amount', v_rule.base_amount,
    'multiplier', v_rule.multiplier
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.can_receive_reward(p_user_id uuid, p_action_type text, p_token_type text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_receive_reward(p_user_id uuid, p_action_type text, p_token_type text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/check_trigger_cooldown.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION check_trigger_cooldown(
  p_trigger_definition_id uuid,
  p_user_id uuid
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_cooldown_minutes integer;
  v_last_run timestamptz;
  v_is_service_role BOOLEAN;
BEGIN
  v_is_service_role := public.is_service_role();
  IF auth.uid() IS NULL AND NOT v_is_service_role THEN
    RAISE EXCEPTION 'Access denied: authentication required';
  END IF;

  SELECT t.cooldown_minutes INTO v_cooldown_minutes
  FROM ai_proactive_trigger_definitions t
  WHERE t.id = p_trigger_definition_id;

  IF v_cooldown_minutes IS NULL THEN
    RETURN true; -- trigger not found, allow (will fail later)
  END IF;

  SELECT MAX(r.created_at) INTO v_last_run
  FROM ai_proactive_runs r
  WHERE r.trigger_definition_id = p_trigger_definition_id
    AND r.user_id = p_user_id
    AND r.status IN ('completed', 'running');

  IF v_last_run IS NULL THEN
    RETURN true; -- never triggered, allow
  END IF;

  RETURN (now() - v_last_run) > (v_cooldown_minutes || ' minutes')::interval;
END;
$$;

REVOKE ALL ON FUNCTION check_trigger_cooldown(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION check_trigger_cooldown(uuid, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/claim_pending_proactive_runs.sql
-- -----------------------------------------------------------------------------

-- Function: claim_pending_proactive_runs
-- DOHNÁNÍ executoru akcí po události. `pg_notify('ai_proactive_dispatch')` je jen
-- budík: notify vydaný, když executor neběžel (nasazení, pád spojení), se ztratí.
-- Běh ale v `ai_proactive_runs` zůstal jako `pending` — outbox vzniká v transakci
-- se zdrojovým zápisem — a tahle funkce ho při pravidelném tiku i po startu vezme.
--
-- `p_min_age_seconds` dává přednost notify: čerstvý běh zabere cesta přes notify,
-- dohnání bere jen to, co zjevně zůstalo ležet. `FOR UPDATE … SKIP LOCKED` → dva
-- executory si dávku nerozdělí dvakrát.
--
-- Vrací pole { run, definition } (tvar jako claim_proactive_run), nejstarší napřed.

CREATE OR REPLACE FUNCTION public.claim_pending_proactive_runs(
  p_worker          text,
  p_channels        text[],
  p_limit           integer DEFAULT 20,
  p_min_age_seconds integer DEFAULT 5
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_out jsonb;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;

  WITH k AS (
    SELECT r.id
      FROM ai_proactive_runs r
      JOIN ai_proactive_trigger_definitions d ON d.id = r.trigger_definition_id
     WHERE r.status = 'pending'
       AND r.created_at < now() - make_interval(secs => greatest(coalesce(p_min_age_seconds, 0), 0))
       AND (d.action_config ->> 'channel') = ANY (p_channels)
     ORDER BY r.created_at
     LIMIT least(greatest(coalesce(p_limit, 20), 1), 200)
     FOR UPDATE OF r SKIP LOCKED
  ), u AS (
    UPDATE ai_proactive_runs r
       SET status     = 'running',
           started_at = now(),
           metadata   = coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object(
                          'worker',     p_worker,
                          'claimed_at', now(),
                          'attempts',   coalesce((r.metadata ->> 'attempts')::int, 0) + 1,
                          'via',        'catchup')
      FROM k, ai_proactive_trigger_definitions d
     WHERE r.id = k.id
       AND d.id = r.trigger_definition_id
    RETURNING r.created_at, jsonb_build_object(
      'run', jsonb_build_object(
        'id',               r.id,
        'user_id',          r.user_id,
        'source_record_id', r.source_record_id,
        'source_data',      r.source_data,
        'metadata',         r.metadata,
        'created_at',       r.created_at),
      'definition', jsonb_build_object(
        'id',            d.id,
        'name',          d.name,
        'action_type',   d.action_type,
        'source_table',  d.source_table,
        'source_event',  d.source_event,
        'action_config', d.action_config)) AS item
  )
  SELECT coalesce(jsonb_agg(u.item ORDER BY u.created_at), '[]'::jsonb) INTO v_out FROM u;

  RETURN v_out;
END;
$function$;

REVOKE ALL ON FUNCTION public.claim_pending_proactive_runs(text, text[], integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.claim_pending_proactive_runs(text, text[], integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/claim_proactive_run.sql
-- -----------------------------------------------------------------------------

-- Function: claim_proactive_run
-- Executor akcí po události (event-worker) si ZABERE jeden běh: pending → running
-- v jedné instrukci. Dva workery, dvě doručená notify téhož běhu, restart uprostřed —
-- vždy vyhraje právě jeden (druhé UPDATE po uvolnění zámku řádku znovu vyhodnotí
-- `status = 'pending'` a nezmění nic). Proto executor nepotřebuje žádný unikátní
-- index „jeden záznam = jedna akce“: jeden běh = jedno zabrání = jedna akce.
--
-- Bere jen běhy pravidel, jejichž kanál (`action_config.channel`) volající umí.
-- Ostatní (AI akce svc-ai-chat, kanál `in_app` ze seedu) zůstanou netknuté — executor
-- je nesmí ani zabrat, ani „vyřídit“.
--
-- Vrací { run, definition } nebo NULL (už zabráno / jiný kanál / neexistuje).
-- `attempts` se počítá při zabrání: requeue_stale_proactive_runs podle něj pozná,
-- kdy přestat vracet běh, na kterém executor opakovaně padá.

CREATE OR REPLACE FUNCTION public.claim_proactive_run(
  p_run_id   uuid,
  p_worker   text,
  p_channels text[]
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_out jsonb;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;

  UPDATE ai_proactive_runs r
     SET status     = 'running',
         started_at = now(),
         metadata   = coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object(
                        'worker',     p_worker,
                        'claimed_at', now(),
                        'attempts',   coalesce((r.metadata ->> 'attempts')::int, 0) + 1)
    FROM ai_proactive_trigger_definitions d
   WHERE r.id = p_run_id
     AND r.status = 'pending'
     AND d.id = r.trigger_definition_id
     AND (d.action_config ->> 'channel') = ANY (p_channels)
  RETURNING jsonb_build_object(
    'run', jsonb_build_object(
      'id',               r.id,
      'user_id',          r.user_id,
      'source_record_id', r.source_record_id,
      'source_data',      r.source_data,
      'metadata',         r.metadata,
      'created_at',       r.created_at),
    'definition', jsonb_build_object(
      'id',            d.id,
      'name',          d.name,
      'action_type',   d.action_type,
      'source_table',  d.source_table,
      'source_event',  d.source_event,
      'action_config', d.action_config))
  INTO v_out;

  RETURN v_out;
END;
$function$;

REVOKE ALL ON FUNCTION public.claim_proactive_run(uuid, text, text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.claim_proactive_run(uuid, text, text[]) TO service_role;


