-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/close_stale_workflow_runs_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: close_stale_workflow_runs_admin
-- Popis: Uzavře ZASTARALÉ běhy procesu ROZHODNUTÍM ČLOVĚKA (správce/majitele):
--        všechny jejich čekající uzly, s důvodem a stopou původu, bez odměn.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (admin/staff nebo service_role)
--
-- ⛔ PROČ VZNIKLA. Naměřeno 2026-09-15 v produkci instance: 126 běhů expedice
--    z let 2020–2024 viselo s čekajícím předáním BEZ řidiče (a s čekající
--    nakládkou i přepravou). Účetnictví je neuzavřelo (settled False nebo
--    chybí), takže reconcile_workflow_from_documents je z principu nezavře —
--    a správně: chybějící údaj není „uzavřeno". Uzavřít je může jen ČLOVĚK,
--    a majitel to rozhodl. Ruční UPDATE by nenechal stopu, proč a kdo.
--
-- ⭐ ROZHODNUTÍ ≠ DOKONČENÍ. Uzel dostane status 'completed' (jediné dva stavy,
--    kterým konzumenti rozumějí jako „už se nečeká", jsou completed/failed;
--    failed znamená odchylku při výkonu a spouští nudge), ALE output_data nese
--    `outcome: 'cancelled'` — týž význam, jaký complete_workflow_step dává
--    zrušenému taktu — a `uzavreno_rozhodnutim` s důvodem, kdo a kdy. Otevřené
--    takty uzlů se uzavřou jako 'cancelled'. ODMĚNA SE NEPŘIPISUJE: nikdo
--    práci nevykonal. Sourozenec `uzavreno_srovnanim` (reconcile) tak zůstane
--    odlišitelný.
--
-- ⛔ KRITÉRIUM JE VÝSLOVNÉ, NE „STARÉ VĚCI". Šablona + datum běhu PŘED hranicí
--    + uzel, který je čekající a NIKOMU nepřiřazený (bez authorized_twin_id
--    i assigned_user_id). Běh, jehož práci má konkrétní člověk, se touto cestou
--    nezavře — to by bylo rozhodnutí o jeho práci, ne o zapomenutém záznamu.
--    Uzavírají se VŠECHNY čekající uzly takového běhu: nechat nakládku
--    a přepravu viset v rolových frontách by znamenalo polovinu rozhodnutí.
--
-- ⭐ NÁHLED JE VÝCHOZÍ (p_dry_run = true): vrátí počty běhů, uzlů a taktů,
--    nic nezapíše.
--
-- ⭐ DOHLEDATELNÉ A VRATNÉ (zadání majitele 2026-09-15: „všechny tyto autonomní
--    kroky potřebujeme umět dohledat, dohledovat a případně zrušit a opravit
--    uživatelem z UI"). Ostrý běh = JEDNO ROZHODNUTÍ: řádek audit_journal
--    (entity_type 'workflow_decision', id = decision_id) s kritériem, důvodem,
--    počty a seznamem uzlů; každý uzel nese decision_id a svůj stav PŘED
--    uzavřením (`pred_uzavrenim`). Vrácení dělá revert_workflow_decision_admin
--    podle decision_id, přehled get_workflow_decisions_admin.
--
-- Kontrakt: (text, date, text, text, boolean) ->
--   jsonb {ok, dry_run, decision_id?, behu, uzlu, taktu, kriterium} | {ok:false, error}
-- ============================================================================

CREATE OR REPLACE FUNCTION public.close_stale_workflow_runs_admin(
  p_template_name     text,
  p_before            date,
  p_unbound_step_code text,
  p_reason            text,
  p_dry_run           boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_behu      integer;
  v_uzlu      integer := 0;
  v_taktu     integer := 0;
  v_kriterium jsonb;
  v_decision  uuid := gen_random_uuid();
  v_uzly      jsonb;
  v_takty     jsonb;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff(auth.uid())) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nedostatečné oprávnění');
  END IF;
  IF coalesce(btrim(p_template_name), '') = '' OR p_before IS NULL
     OR coalesce(btrim(p_unbound_step_code), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error',
      'kritérium je povinné: p_template_name, p_before, p_unbound_step_code');
  END IF;
  IF coalesce(btrim(p_reason), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'důvod (p_reason) je povinný — rozhodnutí bez důvodu nejde doložit');
  END IF;
  IF p_before > current_date THEN
    RETURN jsonb_build_object('ok', false, 'error', 'p_before nesmí být v budoucnosti');
  END IF;

  v_kriterium := jsonb_build_object('template_name', p_template_name, 'before', p_before,
                                    'unbound_step_code', p_unbound_step_code);

  CREATE TEMPORARY TABLE IF NOT EXISTS _stare_behy (batch_id uuid PRIMARY KEY) ON COMMIT DROP;
  TRUNCATE _stare_behy;
  INSERT INTO _stare_behy (batch_id)
  SELECT DISTINCT b.id
    FROM public.production_batches b
    JOIN public.production_workflow_templates w ON w.id = b.workflow_template_id
    JOIN public.production_workflow_steps s ON s.batch_id = b.id
   WHERE w.name = p_template_name
     AND b.production_date < p_before
     AND s.step_code = p_unbound_step_code
     AND s.status = 'pending'
     AND coalesce(s.input_data->>'authorized_twin_id', '') = ''
     AND s.assigned_user_id IS NULL;
  GET DIAGNOSTICS v_behu = ROW_COUNT;

  IF p_dry_run THEN
    SELECT count(*) INTO v_uzlu
      FROM public.production_workflow_steps s JOIN _stare_behy x ON x.batch_id = s.batch_id
     WHERE s.status = 'pending';
    SELECT count(*) INTO v_taktu
      FROM public.story_pulse_beats pb
      JOIN public.production_workflow_steps s ON pb.source_type = 'workflow_step' AND pb.source_id = s.id
      JOIN _stare_behy x ON x.batch_id = s.batch_id
     WHERE pb.status = 'open';
    RETURN jsonb_build_object('ok', true, 'dry_run', true, 'behu', v_behu, 'uzlu', v_uzlu,
                              'taktu', v_taktu, 'kriterium', v_kriterium);
  END IF;

  WITH zrusene AS (
    UPDATE public.story_pulse_beats pb
       SET status = 'cancelled', closed_at = now(), closed_by = auth.uid(), updated_at = now()
      FROM public.production_workflow_steps s
      JOIN _stare_behy x ON x.batch_id = s.batch_id
     WHERE pb.source_type = 'workflow_step' AND pb.source_id = s.id AND pb.status = 'open'
    RETURNING pb.id
  )
  -- id taktů jdou do rozhodnutí: vrácení otevře PRÁVĚ tyhle, ne nové
  SELECT count(*), coalesce(jsonb_agg(id ORDER BY id), '[]'::jsonb) INTO v_taktu, v_takty FROM zrusene;

  WITH zavrene AS (
    UPDATE public.production_workflow_steps s
       SET status = 'completed',
           completed_at = now(),
           -- Stav PŘED uzavřením jde s sebou celý: vrácení ho obnoví přesně,
           -- ne odhadem, které klíče sem kdo přidal.
           output_data = jsonb_build_object('outcome', 'cancelled',
                                            'uzavreno_rozhodnutim', true,
                                            'decision_id', v_decision,
                                            'duvod', p_reason,
                                            'kdo', auth.uid(),
                                            'kdy', now(),
                                            'kriterium', v_kriterium,
                                            'pred_uzavrenim', coalesce(s.output_data, '{}'::jsonb)),
           updated_at = now()
      FROM _stare_behy x
     WHERE x.batch_id = s.batch_id AND s.status = 'pending'
    RETURNING s.id
  )
  SELECT count(*), coalesce(jsonb_agg(id ORDER BY id), '[]'::jsonb) INTO v_uzlu, v_uzly FROM zavrene;

  INSERT INTO public.audit_journal (id, user_id, action, action_type, area, entity_type, entity_id,
                                    summary, details, metadata)
  VALUES (v_decision, auth.uid(), 'workflow.runs_closed_by_decision', 'update', 'workflow',
          'workflow_decision', v_decision::text,
          format('Uzavřeno rozhodnutím: %s běhů, %s uzlů (%s) — %s', v_behu, v_uzlu, p_template_name, p_reason),
          jsonb_build_object('behu', v_behu, 'uzlu', v_uzlu, 'taktu', v_taktu, 'duvod', p_reason,
                             'kriterium', v_kriterium, 'uzly', v_uzly, 'takty', v_takty, 'vratne', true),
          jsonb_build_object('behu', v_behu, 'uzlu', v_uzlu, 'taktu', v_taktu, 'kriterium', v_kriterium));

  RETURN jsonb_build_object('ok', true, 'dry_run', false, 'decision_id', v_decision, 'behu', v_behu,
                            'uzlu', v_uzlu, 'taktu', v_taktu, 'kriterium', v_kriterium);
END;
$function$;

REVOKE ALL ON FUNCTION public.close_stale_workflow_runs_admin(text, date, text, text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.close_stale_workflow_runs_admin(text, date, text, text, boolean) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/commit_slot_switch.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: commit_slot_switch
-- Popis: Commituje B/G switch (mění active_slot, updatuje image_tag) a uvolňuje
--        lock. Idempotent: pokud active_slot už je p_new_active_slot, vrátí
--        current row bez změny. Pokud lock není drženo aktuálním ownerem, raisuje.
-- Volá: WF_BLUE_GREEN_ORCHESTRATOR po smoke-test pass + approval
-- Auth: service_role (n8n) nebo admin/staff
-- ============================================================================

CREATE OR REPLACE FUNCTION public.commit_slot_switch(
  p_app_name        text,
  p_new_active_slot text,
  p_image_tag       text,
  p_lock_owner      text,
  p_actor           uuid DEFAULT NULL
)
RETURNS public.coolify_app_slots
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row     public.coolify_app_slots;
  v_old_slot text;
  v_is_service boolean;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required' USING ERRCODE = '22023';
  END IF;

  IF p_new_active_slot NOT IN ('blue', 'green') THEN
    RAISE EXCEPTION 'Invalid slot: % (must be blue or green)', p_new_active_slot USING ERRCODE = '22023';
  END IF;

  -- Verify lock held by this owner
  SELECT * INTO v_row
  FROM public.coolify_app_slots
  WHERE app_name = p_app_name;

  IF v_row IS NULL THEN
    RAISE EXCEPTION 'App slot not found: %', p_app_name USING ERRCODE = '22023';
  END IF;

  IF NOT v_row.switch_lock THEN
    RAISE EXCEPTION 'No active lock for app: %', p_app_name USING ERRCODE = '22023';
  END IF;

  IF v_row.switch_lock_by IS DISTINCT FROM p_lock_owner THEN
    RAISE EXCEPTION 'Lock owned by another process: % (current: %)',
      v_row.switch_lock_by, p_lock_owner USING ERRCODE = '22023';
  END IF;

  v_old_slot := v_row.active_slot;

  -- Idempotent: same slot, no-op (just release lock + update image_tag)
  IF v_old_slot = p_new_active_slot THEN
    UPDATE public.coolify_app_slots
    SET switch_lock = false,
        switch_lock_at = NULL,
        switch_lock_by = NULL,
        blue_image_tag = CASE WHEN p_new_active_slot = 'blue' THEN p_image_tag ELSE blue_image_tag END,
        green_image_tag = CASE WHEN p_new_active_slot = 'green' THEN p_image_tag ELSE green_image_tag END,
        updated_at = now()
    WHERE app_name = p_app_name
    RETURNING * INTO v_row;
    RETURN v_row;
  END IF;

  -- Real switch
  UPDATE public.coolify_app_slots
  SET active_slot     = p_new_active_slot,
      blue_image_tag  = CASE WHEN p_new_active_slot = 'blue' THEN p_image_tag ELSE blue_image_tag END,
      green_image_tag = CASE WHEN p_new_active_slot = 'green' THEN p_image_tag ELSE green_image_tag END,
      last_switch_at  = now(),
      last_switch_by  = COALESCE(p_actor, auth.uid()),
      switch_lock     = false,
      switch_lock_at  = NULL,
      switch_lock_by  = NULL,
      updated_at      = now()
  WHERE app_name = p_app_name
  RETURNING * INTO v_row;

  -- Audit
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    COALESCE(p_actor, auth.uid()),
    'blue_green_switch_committed',
    jsonb_build_object(
      'app_name', p_app_name,
      'from_slot', v_old_slot,
      'to_slot', p_new_active_slot,
      'image_tag', p_image_tag,
      'lock_owner', p_lock_owner
    )
  );

  RETURN v_row;
END;
$$;

REVOKE ALL ON FUNCTION public.commit_slot_switch(text, text, text, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.commit_slot_switch(text, text, text, text, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.commit_slot_switch(text, text, text, text, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/complete_web_artifact_ingest.sql
-- -----------------------------------------------------------------------------

-- complete_web_artifact_ingest
-- service_role only: transition processing -> ready_for_review with parser results.
-- Appends a story_entries row (entry_type=web_artifact_aisha_proposal) so the
-- storyloop timeline surfaces Aisha's proposed canvas + runtime block suggestions.

CREATE OR REPLACE FUNCTION public.complete_web_artifact_ingest(
  p_job_id uuid,
  p_canvas_data jsonb,
  p_canvas_html text,
  p_canvas_css text,
  p_extracted_tokens jsonb DEFAULT NULL,
  p_metadata jsonb DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean;
  v_job record;
  v_proposal_metadata jsonb;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service THEN
    RAISE EXCEPTION 'Unauthorized: service_role required';
  END IF;

  IF p_canvas_data IS NULL THEN
    RAISE EXCEPTION 'canvas_data required';
  END IF;

  IF jsonb_typeof(p_canvas_data->'pages') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'canvas_data.pages must be array (got %)', jsonb_typeof(p_canvas_data->'pages');
  END IF;

  SELECT id, status, story_id, kind, source_type INTO v_job
  FROM public.web_artifact_jobs
  WHERE id = p_job_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found: %', p_job_id;
  END IF;

  IF v_job.status NOT IN ('processing', 'pending') THEN
    RAISE EXCEPTION 'Job not in processing/pending state (got %)', v_job.status;
  END IF;

  UPDATE public.web_artifact_jobs
  SET status = 'ready_for_review',
      result_canvas_data = p_canvas_data,
      result_canvas_html = p_canvas_html,
      result_canvas_css = p_canvas_css,
      extracted_tokens = COALESCE(p_extracted_tokens, extracted_tokens),
      metadata = COALESCE(metadata, '{}'::jsonb) || COALESCE(p_metadata, '{}'::jsonb),
      processed_at = now()
  WHERE id = p_job_id;

  IF v_job.story_id IS NOT NULL THEN
    v_proposal_metadata := jsonb_build_object(
      'type', 'web_artifact_aisha_proposal',
      'job_id', p_job_id,
      'source_type', v_job.source_type::text,
      'style_band', COALESCE(p_metadata->>'style_band', NULL),
      'mock_mode', COALESCE((p_metadata->>'mock_mode')::boolean, false),
      'runtime_block_suggestions', COALESCE(p_metadata->'runtime_block_suggestions', '[]'::jsonb)
    );
    INSERT INTO public.story_entries (story_id, entry_type, content, metadata, created_by)
    VALUES (v_job.story_id, 'web_artifact_aisha_proposal', NULL, v_proposal_metadata, NULL);
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    NULL,
    'WEB_ARTIFACT_INGEST_COMPLETE',
    jsonb_build_object(
      'area', 'content',
      'severity', 'info',
      'entity_type', 'web_artifact_job',
      'entity_id', p_job_id::text,
      'story_id', v_job.story_id,
      'kind', v_job.kind::text,
      'tags', ARRAY['stack', 'story', 'web_artifact', 'ingest', 'complete']
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION public.complete_web_artifact_ingest(uuid, jsonb, text, text, jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.complete_web_artifact_ingest(uuid, jsonb, text, text, jsonb, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/correlate_sentry_with_deploys.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: correlate_sentry_with_deploys
-- Popis: Centrální RPC Phase 3 — pro každou recently-switched app spočítá Sentry
--        issues v okně (default 15 min od switche), vrátí rollback recommendation.
--        Threshold pravidla: ≥3 fatal, ≥50 error, nebo ≥100 dotčených uživatelů
--        → rollback_recommended = true.
-- Volá: WF_SENTRY_OBSERVER (Phase 3)
-- Auth: admin/staff nebo service_role
-- ============================================================================

CREATE OR REPLACE FUNCTION public.correlate_sentry_with_deploys(
  p_window_minutes int DEFAULT 15
)
RETURNS TABLE (
  app_name             text,
  active_slot          text,
  switched_at          timestamptz,
  last_image_tag       text,
  fatal_count          int,
  error_count          int,
  warning_count        int,
  new_issues_in_window int,
  unique_users_affected int,
  rollback_recommended boolean,
  rollback_reason      text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF NOT public.is_admin_or_staff()
     AND NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  RETURN QUERY
  WITH recent_switches AS (
    SELECT
      cas.app_name,
      cas.active_slot,
      cas.last_switch_at,
      CASE cas.active_slot
        WHEN 'blue' THEN cas.blue_image_tag
        WHEN 'green' THEN cas.green_image_tag
      END AS image_tag
    FROM public.coolify_app_slots cas
    WHERE cas.last_switch_at IS NOT NULL
      AND cas.last_switch_at > now() - interval '30 minutes'
  ),
  sentry_window AS (
    SELECT
      sis.app_name,
      sis.level,
      sis.user_count,
      sis.first_seen,
      sis.sentry_issue_id
    FROM public.sentry_issue_snapshot sis
    INNER JOIN recent_switches rs ON sis.app_name = rs.app_name
    WHERE sis.first_seen > rs.last_switch_at
      AND sis.first_seen < rs.last_switch_at + (p_window_minutes || ' minutes')::interval
      AND sis.status = 'unresolved'
  ),
  agg AS (
    SELECT
      sw.app_name,
      count(*) FILTER (WHERE sw.level = 'fatal')::int AS fatal_count,
      count(*) FILTER (WHERE sw.level = 'error')::int AS error_count,
      count(*) FILTER (WHERE sw.level = 'warning')::int AS warning_count,
      count(DISTINCT sw.sentry_issue_id)::int AS new_issues,
      sum(sw.user_count)::int AS users
    FROM sentry_window sw
    GROUP BY sw.app_name
  )
  SELECT
    rs.app_name,
    rs.active_slot,
    rs.last_switch_at AS switched_at,
    rs.image_tag AS last_image_tag,
    COALESCE(a.fatal_count, 0) AS fatal_count,
    COALESCE(a.error_count, 0) AS error_count,
    COALESCE(a.warning_count, 0) AS warning_count,
    COALESCE(a.new_issues, 0) AS new_issues_in_window,
    COALESCE(a.users, 0) AS unique_users_affected,
    (
      COALESCE(a.fatal_count, 0) >= 3
      OR COALESCE(a.error_count, 0) >= 50
      OR COALESCE(a.users, 0) >= 100
    ) AS rollback_recommended,
    CASE
      WHEN COALESCE(a.fatal_count, 0) >= 3
        THEN '≥3 fatal issues po switchi'
      WHEN COALESCE(a.error_count, 0) >= 50
        THEN '≥50 error issues po switchi'
      WHEN COALESCE(a.users, 0) >= 100
        THEN '≥100 dotčených uživatelů'
      ELSE NULL
    END AS rollback_reason
  FROM recent_switches rs
  LEFT JOIN agg a ON a.app_name = rs.app_name;
END;
$$;

REVOKE ALL ON FUNCTION public.correlate_sentry_with_deploys(int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.correlate_sentry_with_deploys(int) TO authenticated;
GRANT EXECUTE ON FUNCTION public.correlate_sentry_with_deploys(int) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_consultation_call.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- create_consultation_call
-- =============================================================================
-- Creates voice room + consultation session atomically.
-- =============================================================================

CREATE OR REPLACE FUNCTION public.create_consultation_call(
  p_booking_id uuid DEFAULT NULL,
  p_callee_id uuid DEFAULT NULL,
  p_livekit_room_name text DEFAULT NULL,
  p_recording_consent boolean DEFAULT false,
  p_room_name text DEFAULT NULL,
  p_story_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_room_id uuid;
  v_session_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_callee_id IS NULL OR p_livekit_room_name IS NULL OR p_room_name IS NULL THEN
    RAISE EXCEPTION 'Missing required parameters';
  END IF;
  -- ⛔ Audit vydání 2026-10-01 (B2): hovor šel navázat na KTEROUKOLI story.
  -- Story je volitelná; když je uvedená, musí ji volající vidět.
  IF p_story_id IS NOT NULL AND NOT public.can_access_story(p_story_id) THEN
    RAISE EXCEPTION 'Access denied: story owner or participant required'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO voice_rooms (name, room_type, story_id, livekit_room_name, max_participants, created_by)
  VALUES (p_room_name, 'consultation', p_story_id, p_livekit_room_name, 2, v_user_id)
  RETURNING id INTO v_room_id;

  INSERT INTO consultation_sessions (voice_room_id, booking_id, caller_id, callee_id, status, recording_consent)
  VALUES (v_room_id, p_booking_id, v_user_id, p_callee_id, 'ringing', p_recording_consent)
  RETURNING id INTO v_session_id;

  RETURN jsonb_build_object(
    'session_id', v_session_id,
    'room_id', v_room_id
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.create_consultation_call(uuid, uuid, text, boolean, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_consultation_call(uuid, uuid, text, boolean, text, uuid) TO authenticated;


