-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_web_page_version.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_web_page_version
-- Description: Creates a snapshot version of a web page's current state.
-- Security: SECURITY INVOKER, authenticated only, admin/staff check inside
-- Created: 2026-04-14

CREATE OR REPLACE FUNCTION public.create_web_page_version(
  p_page_id uuid,
  p_label text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_version_id uuid;
  v_next_version integer;
  v_page record;
BEGIN
  -- Admin/staff (editor) OR service_role (boot-time /seed-default publishes via
  -- apply_web_artifact_to_page, which snapshots a version). Consistent with the
  -- rest of the now service_role-aware seed chain.
  IF NOT public.is_admin_or_staff()
     AND NOT public.is_service_role()
  THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Get current page data
  SELECT canvas_data, canvas_html, canvas_css, page_settings
  INTO v_page
  FROM public.web_pages
  WHERE id = p_page_id AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Page not found';
  END IF;

  -- Nothing to snapshot: a freshly-created page (no canvas yet) has no prior
  -- state worth versioning. web_page_versions.canvas_data is NOT NULL, so an
  -- empty snapshot is both meaningless and illegal. Return NULL — callers
  -- (apply_web_artifact_to_page) treat a NULL pre-apply version as "no prior
  -- version". This is what makes the FIRST seed of a page work.
  IF v_page.canvas_data IS NULL AND v_page.canvas_html IS NULL THEN
    RETURN NULL;
  END IF;

  -- Get next version number
  SELECT COALESCE(MAX(version_number), 0) + 1
  INTO v_next_version
  FROM public.web_page_versions
  WHERE page_id = p_page_id;

  -- Insert version
  INSERT INTO public.web_page_versions (
    page_id, version_number, canvas_data, canvas_html, canvas_css,
    page_settings, created_by, label
  ) VALUES (
    p_page_id, v_next_version, v_page.canvas_data, v_page.canvas_html,
    v_page.canvas_css, v_page.page_settings, auth.uid(), p_label
  )
  RETURNING id INTO v_version_id;

  -- Audit log
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'PAGE_VERSION_CREATE',
    jsonb_build_object(
      'area', 'web_pages',
      'severity', 'info',
      'entity_type', 'web_page_version',
      'entity_id', v_version_id::text,
      'page_id', p_page_id::text,
      'version_number', v_next_version
    )
  );

  RETURN v_version_id;
END;
$$;

REVOKE ALL ON FUNCTION public.create_web_page_version(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_web_page_version(uuid, text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/apply_web_page_template.sql
-- -----------------------------------------------------------------------------

-- Function: public.apply_web_page_template
-- Description: Applies a template to a page (auto-snapshots current state first).
-- Security: SECURITY INVOKER, authenticated only, admin/staff check inside
-- Created: 2026-04-14

CREATE OR REPLACE FUNCTION public.apply_web_page_template(
  p_page_id uuid,
  p_template_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_tpl record;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Snapshot before overwrite
  PERFORM public.create_web_page_version(p_page_id, 'auto: before template apply');

  SELECT canvas_data, canvas_html, canvas_css, page_settings
  INTO v_tpl
  FROM public.web_page_templates
  WHERE id = p_template_id AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Template not found';
  END IF;

  UPDATE public.web_pages
  SET canvas_data = v_tpl.canvas_data,
      canvas_html = v_tpl.canvas_html,
      canvas_css = v_tpl.canvas_css,
      page_settings = v_tpl.page_settings,
      updated_at = now()
  WHERE id = p_page_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'PAGE_TEMPLATE_APPLY',
    jsonb_build_object(
      'area', 'web_pages',
      'severity', 'info',
      'entity_type', 'web_page_template',
      'entity_id', p_template_id::text,
      'page_id', p_page_id::text
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION public.apply_web_page_template(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.apply_web_page_template(uuid, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/deactivate_data_source.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: deactivate_data_source
-- Popis: Vypne JEDEN zdroj dat podle slugu.
--
-- Doplňuje `deactivate_plugin_runtime`, který je kill-switch nad CELÝM
-- pluginem (všechny registry naráz) a bere `plugin_id`. Administrace ale
-- potřebuje vypnout jeden zdroj, a to bez pluginu vůbec nejde vyjádřit —
-- `money` žádný plugin nemá.
--
-- Vypnutí NIKDY nic nemaže a nesahá na pověření: vypnutý zdroj se má dát zapnout
-- zpět, aniž je člověk musí zadávat znovu.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.deactivate_data_source(p_source_slug text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_source_id uuid;
  v_active    boolean;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT id, is_active INTO v_source_id, v_active
    FROM public.agent_knowledge_sources
   WHERE source_slug = p_source_slug;

  IF v_source_id IS NULL THEN
    RAISE EXCEPTION 'deactivate_data_source: zdroj % neexistuje', p_source_slug;
  END IF;

  IF NOT v_active THEN
    RETURN jsonb_build_object('source_slug', p_source_slug, 'is_active', false, 'changed', false);
  END IF;

  UPDATE public.agent_knowledge_sources
     SET is_active = false, updated_at = now()
   WHERE id = v_source_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'DATA_SOURCE_DEACTIVATED', jsonb_build_object(
    'area', 'ingest', 'severity', 'warning',
    'source_slug', p_source_slug, 'source_id', v_source_id
  ));

  RETURN jsonb_build_object('source_slug', p_source_slug, 'is_active', false, 'changed', true);
END;
$$;

COMMENT ON FUNCTION public.deactivate_data_source(text) IS
  'Vypne jeden zdroj dat podle slugu. Nemaže pověření — vypnutý zdroj jde zapnout zpět. Idempotentní, auditované. Admin/staff nebo service_role.';

REVOKE ALL ON FUNCTION public.deactivate_data_source(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.deactivate_data_source(text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/document_visible_to.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: document_visible_to
-- Popis: JEDINÝ vlastník pravidla „smí tazatel vidět tento doklad?". Skládá
--        existující mašinerii, nic nového nevynalézá:
--          1. kanonická třída dokladu: document_registry.sensitivity
--             (promotion přes register_source_document_audited přiděluje třídu)
--          2. úroveň tazatele: audience_user_meets_tier_requirement — SPOČTENÁ
--             z dění, fail-closed (NULL uživatel = anonymous)
--          3. převod třída→úroveň: document_sensitivity_min_tier
--        NEPROMOVANÝ doklad (bez řádku v document_registry) je viditelný jen
--        adminovi/service — tím se enforcementem stává promotion šev: raw lane
--        se členům neukazuje, dokud doklad nedostane kanonickou identitu a třídu.
--
-- Použití: RLS policy li_source_registry_member_tier_select (INVOKER čtenáři
--        register/detail/digest ji dědí beze změny kódu) + download RPC.
--        Rozšíření o strukturální scope (vztah dvojčat) se zapne TADY — žádné
--        inline kopie (lekce z P0 #824).
--
-- ŠEV MEZI VRSTVAMI = `source_sha256` (obsahová identita dokladu), NIKOLI
--        `source_id`: document_registry.source_id je FK na agent_knowledge_sources
--        (tj. DATOVÝ ZDROJ, ze kterého doklad přišel), zatímco totožnost doklad↔
--        doklad nese content hash. Obě vrstvy ho mají (li_source_registry
--        UNIQUE(source_sha256), document_registry UNIQUE(source_id, sha)).
--        Spojení přes source_id by nikdy nesedlo a všechno by tiše zůstalo
--        neviditelné — ověřeno testem na čisté DB.
--
-- Argument je proto sha, ne id: predikát nezávisí na tom, ze které lane se ptáme.
--
-- Bezpečnost: SECURITY DEFINER (policy běží jako tazatel, ale lookup do
--        document_registry nesmí podléhat jeho RLS — jinak by se pravidlo
--        nikdy nevyhodnotilo). STABLE, bez zápisů.
-- Pozn. výkon: volá se per řádek; tier compute je uvnitř audience mašinerie.
--        Pro dnešní objemy (stovky dokladů) v pořádku; při růstu kešovat tier
--        per statement.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.document_visible_to(p_uid uuid, p_source_sha256 text)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_sensitivity text;
BEGIN
  -- Oracle guard (týž vzor jako workflow_step_visible_to): přihlášený volající
  -- smí vyhodnocovat JEN SVOJI viditelnost; service_role/admin za kohokoliv.
  -- Bez něj by predikát prozrazoval úroveň cizích účtů.
  IF NOT (p_uid IS NOT DISTINCT FROM auth.uid()
          OR public.is_service_role()
          OR public.is_admin_or_staff()) THEN
    RETURN false;
  END IF;

  SELECT dr.sensitivity INTO v_sensitivity
  FROM public.document_registry dr
  WHERE dr.source_sha256 = p_source_sha256
    AND dr.superseded_by IS NULL
  ORDER BY dr.version DESC
  LIMIT 1;

  IF v_sensitivity IS NULL THEN
    RETURN false;  -- nepromovaný doklad: jen admin/service (ti jdou mimo predikát)
  END IF;

  -- 2-arg forma (tier-ACL): (požadovaná úroveň, uživatel) — pořadí dle SoT.
  RETURN public.audience_user_meets_tier_requirement(
    public.document_sensitivity_min_tier(v_sensitivity),
    p_uid
  );
END;
$$;

REVOKE ALL ON FUNCTION public.document_visible_to(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.document_visible_to(uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.document_visible_to(uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_bank_transactions.sql
-- -----------------------------------------------------------------------------

-- edge_bank_transactions: Edge-safe bank transaction operations (insert, match, list)
--   služba (svc-fio-bank): insert_transaction, auto_match_by_vs
--   admin/staff (AdminBankReconciliation): get_unmatched, get_all, get_awaiting_orders,
--                                          match_to_order, dismiss_transaction
--   vlastník objednávky: get_order_bank_transfer
CREATE OR REPLACE FUNCTION public.edge_bank_transactions(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_row jsonb;
  v_rows jsonb;
  v_tx_id text;
  v_order_id uuid;
  v_expected numeric;
  v_order_currency text;
  v_tx_uuid uuid;
  v_limit int;
BEGIN
  -- ⛔ SECURITY DEFINER vypíná RLS, takže nárok musí vymáhat tělo. Do 2026-10-04
  -- tu žádná stráž nebyla a funkce má GRANT pro `authenticated` (admin UI ji volá
  -- přímo): kdokoli přihlášený si přímým /rpc/edge_bank_transactions mohl
  -- označit vlastní objednávku za zaplacenou (match_to_order), podstrčit
  -- platbu (insert_transaction) a přečíst účty a jména plátců (get_unmatched).
  -- Zápis pohybů z banky dělá jen služba (svc-fio-bank); párování a frontu
  -- nespárovaných admin/staff. get_order_bank_transfer stráží vlastníka níž.
  IF p_action IN ('insert_transaction', 'auto_match_by_vs') AND NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;
  IF p_action IN ('match_to_order', 'get_unmatched', 'get_all', 'get_awaiting_orders', 'dismiss_transaction')
     AND NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  -- INSERT a new bank transaction (deduplicate by fio_transaction_id)
  IF p_action = 'insert_transaction' THEN
    v_tx_id := NULLIF(p_payload ->> 'fio_transaction_id', '');

    -- Check for duplicate
    IF v_tx_id IS NOT NULL THEN
      SELECT id INTO v_order_id FROM public.bank_transactions WHERE fio_transaction_id = v_tx_id;
      IF FOUND THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'duplicate');
      END IF;
    END IF;

    INSERT INTO public.bank_transactions (
      fio_transaction_id, amount, currency, variable_symbol,
      sender_account, sender_name, transaction_date, message,
      match_status, raw_data
    ) VALUES (
      v_tx_id,
      (p_payload ->> 'amount')::numeric,
      COALESCE(NULLIF(p_payload ->> 'currency', ''), public.commerce_base_currency()),
      NULLIF(p_payload ->> 'variable_symbol', ''),
      NULLIF(p_payload ->> 'sender_account', ''),
      NULLIF(p_payload ->> 'sender_name', ''),
      (NULLIF(p_payload ->> 'transaction_date', ''))::date,
      NULLIF(p_payload ->> 'message', ''),
      COALESCE(NULLIF(p_payload ->> 'match_status', ''), 'unmatched'),
      p_payload -> 'raw_data'
    );

    RETURN jsonb_build_object('ok', true);
  END IF;

  -- MATCH a transaction to an order
  IF p_action = 'match_to_order' THEN
    v_order_id := (p_payload ->> 'order_id')::uuid;

    UPDATE public.bank_transactions
    SET matched_order_id = v_order_id,
        match_status = 'matched',
        match_type = 'manual',
        match_notes = NULLIF(p_payload ->> 'notes', '')
    WHERE id = (p_payload ->> 'transaction_id')::uuid;

    -- Update order payment status
    UPDATE public.orders
    SET payment_status = 'paid',
        status = 'paid',
        updated_at = now()
    WHERE id = v_order_id
      AND payment_status = 'awaiting_transfer';

    RETURN jsonb_build_object('ok', true);
  END IF;

  -- LIST unmatched transactions (admin)
  IF p_action = 'get_unmatched' THEN
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', bt.id,
        'fio_transaction_id', bt.fio_transaction_id,
        'amount', bt.amount,
        'currency', bt.currency,
        'variable_symbol', bt.variable_symbol,
        'sender_account', bt.sender_account,
        'sender_name', bt.sender_name,
        'transaction_date', bt.transaction_date,
        'message', bt.message,
        'match_status', bt.match_status,
        'created_at', bt.created_at
      ) ORDER BY bt.transaction_date DESC NULLS LAST
    ), '[]'::jsonb) INTO v_rows
    FROM public.bank_transactions bt
    WHERE bt.match_status IN ('unmatched', 'amount_mismatch');

    RETURN jsonb_build_object('rows', v_rows);
  END IF;

  -- ⛔ DO 2026-10-04 NÁSLEDUJÍCÍ ČTYŘI AKCE NEEXISTOVALY, ačkoli je volali
  -- klienti: svc-fio-bank `auto_match_by_vs` (po prvním pohybu s VS spadla celá
  -- synchronizace na „Unsupported action") a admin UI `get_all`,
  -- `get_awaiting_orders`, `dismiss_transaction` (stránka párování ukazovala
  -- chybu místo dat). Tvar odpovědí odpovídá Zod schématům v
  -- src/hooks/useBankReconciliation.ts a očekávání svc-fio-bank.

  -- AUTO-MATCH právě vloženého pohybu na objednávku podle variabilního symbolu.
  -- Zaplaceno jen při PŘESNÉ shodě částky (a měny, je-li známá) — přeplatek
  -- i nedoplatek jde adminovi jako amount_mismatch, nic se nedomýšlí.
  IF p_action = 'auto_match_by_vs' THEN
    SELECT o.id, COALESCE(o.bank_transfer_amount, o.total), o.currency
      INTO v_order_id, v_expected, v_order_currency
    FROM public.orders o
    WHERE o.variable_symbol = NULLIF(p_payload ->> 'variable_symbol', '')
      AND o.payment_status = 'awaiting_transfer'
    ORDER BY o.created_at DESC
    LIMIT 1;

    IF v_order_id IS NULL THEN
      RETURN jsonb_build_object('matched', false, 'reason', 'no_order');
    END IF;

    SELECT bt.id INTO v_tx_uuid
    FROM public.bank_transactions bt
    WHERE bt.variable_symbol = NULLIF(p_payload ->> 'variable_symbol', '')
      AND bt.match_status = 'unmatched'
    ORDER BY bt.created_at DESC
    LIMIT 1;

    IF v_tx_uuid IS NULL THEN
      RETURN jsonb_build_object('matched', false, 'reason', 'no_transaction');
    END IF;

    IF (p_payload ->> 'amount')::numeric IS DISTINCT FROM v_expected
       OR (NULLIF(p_payload ->> 'currency', '') IS NOT NULL AND v_order_currency IS NOT NULL
           AND upper(p_payload ->> 'currency') <> upper(v_order_currency)) THEN
      UPDATE public.bank_transactions
      SET match_status = 'amount_mismatch',
          matched_order_id = v_order_id,
          match_type = 'auto_vs',
          match_notes = format('Očekáváno %s %s', v_expected, COALESCE(v_order_currency, ''))
      WHERE id = v_tx_uuid;
      RETURN jsonb_build_object('matched', false, 'reason', 'amount_mismatch', 'order_id', v_order_id);
    END IF;

    UPDATE public.bank_transactions
    SET matched_order_id = v_order_id,
        match_status = 'matched',
        match_type = 'auto_vs'
    WHERE id = v_tx_uuid;

    UPDATE public.orders
    SET payment_status = 'paid',
        status = 'paid',
        updated_at = now()
    WHERE id = v_order_id
      AND payment_status = 'awaiting_transfer';

    RETURN jsonb_build_object('matched', true, 'order_id', v_order_id);
  END IF;

  -- LIST all transactions (admin), newest first
  IF p_action = 'get_all' THEN
    v_limit := LEAST(GREATEST(COALESCE(NULLIF(p_payload ->> 'limit', '')::int, 500), 1), 2000);
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', t.id,
        'fio_transaction_id', t.fio_transaction_id,
        'amount', t.amount,
        'currency', COALESCE(t.currency, public.commerce_base_currency()),
        'variable_symbol', t.variable_symbol,
        'sender_account', t.sender_account,
        'sender_name', t.sender_name,
        'transaction_date', t.transaction_date,
        'message', t.message,
        'match_status', t.match_status,
        'match_type', t.match_type,
        'match_notes', t.match_notes,
        'matched_order_id', t.matched_order_id,
        'created_at', t.created_at
      ) ORDER BY t.transaction_date DESC NULLS LAST, t.created_at DESC
    ), '[]'::jsonb) INTO v_rows
    FROM (
      SELECT bt.*
      FROM public.bank_transactions bt
      ORDER BY bt.transaction_date DESC NULLS LAST, bt.created_at DESC
      LIMIT v_limit
    ) t;

    RETURN jsonb_build_object('rows', v_rows);
  END IF;

  -- LIST orders awaiting a bank transfer (admin, manual matching)
  IF p_action = 'get_awaiting_orders' THEN
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', o.id,
        'total', o.total,
        'currency', COALESCE(o.currency, public.commerce_base_currency()),
        'variable_symbol', o.variable_symbol,
        'bank_transfer_amount', o.bank_transfer_amount,
        'bank_transfer_due_date', o.bank_transfer_due_date,
        'created_at', o.created_at
      ) ORDER BY o.created_at DESC
    ), '[]'::jsonb) INTO v_rows
    FROM public.orders o
    WHERE o.payment_status = 'awaiting_transfer';

    RETURN jsonb_build_object('rows', v_rows);
  END IF;

  -- DISMISS (ignore) a transaction that is not a payment for any order (admin)
  IF p_action = 'dismiss_transaction' THEN
    UPDATE public.bank_transactions
    SET match_status = 'dismissed',
        match_notes = NULLIF(p_payload ->> 'notes', '')
    WHERE id = (p_payload ->> 'transaction_id')::uuid
      AND match_status IN ('unmatched', 'amount_mismatch');

    RETURN jsonb_build_object('ok', FOUND);
  END IF;

  -- GET bank transfer details for an order (member view)
  IF p_action = 'get_order_bank_transfer' THEN
    v_order_id := (p_payload ->> 'order_id')::uuid;

    SELECT jsonb_build_object(
      'order_id', o.id,
      'variable_symbol', o.variable_symbol,
      'iban', o.bank_transfer_iban,
      'bic', o.bank_transfer_bic,
      'amount', o.bank_transfer_amount,
      'currency', o.currency,
      'due_date', o.bank_transfer_due_date,
      'payment_method', o.payment_method,
      'payment_status', o.payment_status,
      'status', o.status,
      'total', o.total,
      'invoice_number', o.invoice_number,
      'invoice_pdf_path', o.invoice_pdf_path
    ) INTO v_row
    FROM public.orders o
    WHERE o.id = v_order_id
      AND (o.user_id = auth.uid() OR EXISTS (
        SELECT 1 FROM public.user_roles ur
        WHERE ur.user_id = auth.uid()
          AND ur.role IN ('admin', 'staff')
      ));

    RETURN jsonb_build_object('row', v_row);
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_bank_transactions(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edge_bank_transactions(text, jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.edge_bank_transactions(text, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_mobile_notifications.sql
-- -----------------------------------------------------------------------------

-- Function: public.edge_mobile_notifications
-- Purpose: Edge-safe mobile session + notification reads/writes.

CREATE OR REPLACE FUNCTION public.edge_mobile_notifications(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_inserted bigint;
  v_user_id uuid;
BEGIN
  -- ⛔ SECURITY DEFINER vypíná RLS, takže nárok musí vymáhat tělo. Do 2026-10-04
  -- tu stráž měla jen admin akce a funkce má GRANT pro `authenticated` (admin UI
  -- čte doručení kampaně). Kdokoli přihlášený si tak přímým
  -- /rpc/edge_mobile_notifications mohl přečíst FCM tokeny cizích zařízení
  -- (get_mobile_sessions → push komukoli mimo platformu), poslat in-app
  -- notifikaci s odkazem libovolnému účtu (insert_notifications_bulk → phishing),
  -- vynulovat tokeny VŠEM (null_mobile_session_token bez user_id) a číst
  -- preference cizích účtů. Všechno kromě admin čtení doručení je práce služby
  -- (svc-push, gateway — volají service tokenem).
  IF p_action IS DISTINCT FROM 'get_campaign_notification_deliveries_admin'
     AND NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  IF p_action = 'get_mobile_sessions' THEN
    RETURN jsonb_build_object(
      'rows',
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'device_platform', m.device_platform,
              'fcm_token', m.fcm_token,
              'user_id', m.user_id
            )
          )
          FROM public.mobile_sessions m
          WHERE m.user_id = ANY(
            COALESCE(
              (
                SELECT array_agg(value::uuid)
                FROM jsonb_array_elements_text(COALESCE(p_payload -> 'user_ids', '[]'::jsonb)) AS t(value)
              ),
              ARRAY[]::uuid[]
            )
          )
          AND m.fcm_token IS NOT NULL
        ),
        '[]'::jsonb
      )
    );
  END IF;

  IF p_action = 'get_notification_preferences' THEN
    RETURN jsonb_build_object(
      'rows',
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'afternoon_start', n.afternoon_start::text,
              'evening_start', n.evening_start::text,
              'morning_start', n.morning_start::text,
              'push_enabled', n.push_enabled,
              'push_reminders', n.push_reminders,
              'push_study_updates', n.push_study_updates,
              'questionnaire_reminder_period', n.questionnaire_reminder_period,
              'quiet_hours_enabled', n.quiet_hours_enabled,
              'quiet_hours_end', n.quiet_hours_end::text,
              'quiet_hours_start', n.quiet_hours_start::text,
              'user_id', n.user_id,
              'user_timezone', n.user_timezone
            )
          )
          FROM public.notification_preferences n
          WHERE n.user_id = ANY(
            COALESCE(
              (
                SELECT array_agg(value::uuid)
                FROM jsonb_array_elements_text(COALESCE(p_payload -> 'user_ids', '[]'::jsonb)) AS t(value)
              ),
              ARRAY[]::uuid[]
            )
          )
        ),
        '[]'::jsonb
      )
    );
  END IF;

  IF p_action = 'insert_notification_log' THEN
    INSERT INTO public.notification_logs (
      created_at,
      data,
      devices_failed,
      devices_sent,
      error_message,
      notification_type,
      recipients_count,
      title
    )
    VALUES (
      COALESCE(NULLIF(p_payload ->> 'created_at', '')::timestamptz, now()),
      COALESCE(p_payload -> 'data', '{}'::jsonb),
      COALESCE(NULLIF(p_payload ->> 'devices_failed', '')::integer, 0),
      COALESCE(NULLIF(p_payload ->> 'devices_sent', '')::integer, 0),
      NULLIF(p_payload ->> 'error_message', ''),
      COALESCE(NULLIF(p_payload ->> 'notification_type', ''), 'push'),
      COALESCE(NULLIF(p_payload ->> 'recipients_count', '')::integer, 0),
      NULLIF(p_payload ->> 'title', '')
    )
    RETURNING id INTO v_id;

    RETURN jsonb_build_object('id', v_id, 'ok', true);
  END IF;

  IF p_action = 'insert_notifications_bulk' THEN
    -- ⛔ WITH s INSERT MUSÍ BÝT NA NEJVYŠŠÍ ÚROVNI. Do 2026-10-04 tu byl jako
    -- poddotaz uvnitř jsonb_build_object(...) a Postgres ho odmítal při KAŽDÉM
    -- volání („WITH clause containing a data-modifying statement must be at
    -- the top level") — in-app notifikace kampaní a připomínek dotazníků
    -- nevznikla ani jedna, svc-push jen zalogoval chybu.
    WITH input_rows AS (
      SELECT
        NULLIF(row ->> 'link', '') AS link,
        NULLIF(row ->> 'message', '') AS message,
        COALESCE(row -> 'metadata', '{}'::jsonb) AS metadata,
        COALESCE(NULLIF(row ->> 'title', ''), 'Notification') AS title,
        COALESCE(NULLIF(row ->> 'type', ''), 'campaign') AS type,
        NULLIF(row ->> 'user_id', '')::uuid AS user_id
      FROM jsonb_array_elements(COALESCE(p_payload -> 'rows', '[]'::jsonb)) AS t(row)
    ),
    inserted AS (
      INSERT INTO public.notifications (
        link,
        message,
        metadata,
        title,
        type,
        user_id
      )
      SELECT
        i.link,
        i.message,
        i.metadata,
        i.title,
        i.type,
        i.user_id
      FROM input_rows i
      WHERE i.user_id IS NOT NULL
      RETURNING 1
    )
    SELECT count(*) INTO v_inserted FROM inserted;

    RETURN jsonb_build_object('inserted', v_inserted);
  END IF;

  IF p_action = 'get_existing_questionnaire_reminder_keys' THEN
    RETURN jsonb_build_object(
      'rows',
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'dedupe_key', n.metadata ->> 'dedupe_key'
            )
          )
          FROM public.notifications n
          WHERE n.user_id = ANY(
            COALESCE(
              (
                SELECT array_agg(value::uuid)
                FROM jsonb_array_elements_text(COALESCE(p_payload -> 'user_ids', '[]'::jsonb)) AS t(value)
              ),
              ARRAY[]::uuid[]
            )
          )
            AND n.type = 'questionnaire_request'
            AND n.metadata ? 'dedupe_key'
            AND (n.metadata ->> 'dedupe_key') = ANY(
              COALESCE(
                (
                  SELECT array_agg(value)
                  FROM jsonb_array_elements_text(COALESCE(p_payload -> 'dedupe_keys', '[]'::jsonb)) AS t(value)
                ),
                ARRAY[]::text[]
              )
            )
        ),
        '[]'::jsonb
      )
    );
  END IF;

  IF p_action = 'get_campaign_notification_deliveries_admin' THEN
    IF NOT public.is_admin_or_staff() THEN
      RAISE EXCEPTION 'Access denied';
    END IF;

    RETURN jsonb_build_object(
      'rows',
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'created_at', q.created_at,
              'id', q.id,
              'is_read', q.is_read,
              'link', q.link,
              'message', q.message,
              'profile_display_name', q.profile_display_name,
              'profile_email', q.profile_email,
              'schedule_id', q.schedule_id,
              'title', q.title,
              'type', q.type,
              'user_id', q.user_id
            )
          )
          FROM (
            SELECT
              n.created_at,
              n.id,
              n.is_read,
              n.link,
              n.message,
              p.display_name AS profile_display_name,
              p.email AS profile_email,
              NULLIF(n.metadata ->> 'schedule_id', '')::uuid AS schedule_id,
              n.title,
              n.type,
              n.user_id
            FROM public.notifications n
            LEFT JOIN public.profiles p ON p.user_id = n.user_id
            WHERE (n.metadata ->> 'campaign_id') = NULLIF(p_payload ->> 'campaign_id', '')
            ORDER BY n.created_at DESC
            LIMIT GREATEST(COALESCE(NULLIF(p_payload ->> 'limit', '')::integer, 200), 1)
          ) AS q
        ),
        '[]'::jsonb
      )
    );
  END IF;

  IF p_action = 'null_mobile_session_token' THEN
    v_user_id := NULLIF(p_payload ->> 'user_id', '')::uuid;

    UPDATE public.mobile_sessions
    SET
      fcm_token = NULL,
      updated_at = now()
    WHERE
      (
        v_user_id IS NULL
        OR user_id = v_user_id
      )
      AND (
        NOT (p_payload ? 'fcm_token')
        OR fcm_token = NULLIF(p_payload ->> 'fcm_token', '')
      );

    RETURN jsonb_build_object('ok', true, 'updated', FOUND);
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_mobile_notifications(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edge_mobile_notifications(text, jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.edge_mobile_notifications(text, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_subscriptions.sql
-- -----------------------------------------------------------------------------

-- Function: public.edge_subscriptions
-- Purpose: Edge-safe subscription and package operations.

CREATE OR REPLACE FUNCTION public.edge_subscriptions(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_package_id uuid;
  v_row jsonb;
  v_statuses text[];
  v_stripe_subscription_id text;
  v_user_id uuid;
BEGIN
  -- ⛔ SECURITY DEFINER vypíná RLS, takže nárok musí vymáhat tělo. Do 2026-10-04
  -- tu žádná stráž nebyla a funkce má GRANT pro `authenticated` (svc-stripe čte
  -- předplatné uživatelským tokenem): kdokoli přihlášený si přímým
  -- /rpc/edge_subscriptions mohl přepnout VLASTNÍ předplatné na 'active' bez
  -- platby (update_subscription), založit si ho (create_member_subscription),
  -- přepsat Stripe ceny balíčku (update_package_stripe) a číst předplatné cizích
  -- účtů (get_user_subscriptions s cizím user_id).
  -- Zápisy dělá jen služba (svc-stripe po ověření u Stripe / z webhooku); číst
  -- předplatné smí vlastník, služba a správa. Katalog balíčků zůstává čitelný.
  IF p_action IN ('create_member_subscription', 'update_package_stripe', 'update_subscription')
     AND NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  IF p_action = 'create_member_subscription' THEN
    INSERT INTO public.member_subscriptions (
      amount_paid,
      billing_interval_months,
      currency,
      package_id,
      payment_type,
      period_end,
      period_start,
      status,
      user_id
    )
    VALUES (
      NULLIF(p_payload ->> 'amount_paid', '')::numeric,
      NULLIF(p_payload ->> 'billing_interval_months', '')::integer,
      COALESCE(NULLIF(p_payload ->> 'currency', ''), public.commerce_base_currency()),
      NULLIF(p_payload ->> 'package_id', '')::uuid,
      COALESCE(NULLIF(p_payload ->> 'payment_type', ''), 'one_time')::public.payment_type,
      NULLIF(p_payload ->> 'period_end', '')::timestamptz,
      NULLIF(p_payload ->> 'period_start', '')::timestamptz,
      COALESCE(NULLIF(p_payload ->> 'status', ''), 'pending_payment'),
      NULLIF(p_payload ->> 'user_id', '')::uuid
    )
    RETURNING id INTO v_id;

    RETURN jsonb_build_object('id', v_id, 'ok', true);
  END IF;

  IF p_action = 'get_package_by_id' THEN
    v_package_id := NULLIF(p_payload ->> 'package_id', '')::uuid;
    IF v_package_id IS NULL THEN
      RAISE EXCEPTION 'Missing package_id';
    END IF;

    SELECT jsonb_build_object(
      'allow_one_time_payment', p.allow_one_time_payment,
      'allow_recurring_payment', p.allow_recurring_payment,
      'billing_interval_months', p.billing_interval_months,
      'currency', p.currency,
      'description', p.description,
      'governance_tokens', p.governance_tokens,
      'id', p.id,
      'impact_tokens', p.impact_tokens,
      'is_recurring', p.is_recurring,
      'min_billing_months', p.min_billing_months,
      'name', p.name,
      'period', p.period,
      'price', p.price,
      'slug', p.slug,
      'stripe_price_id', p.stripe_price_id,
      'stripe_price_id_one_time', p.stripe_price_id_one_time,
      'stripe_price_id_recurring', p.stripe_price_id_recurring,
      'stripe_product_id', p.stripe_product_id,
      'tier', p.tier
    )
    INTO v_row
    FROM public.subscription_packages p
    WHERE p.id = v_package_id
      AND COALESCE(p.is_active, true) = true
    LIMIT 1;

    RETURN jsonb_build_object('row', v_row);
  END IF;

  IF p_action = 'get_user_subscriptions' THEN
    v_user_id := NULLIF(p_payload ->> 'user_id', '')::uuid;
    IF v_user_id IS NULL THEN
      RAISE EXCEPTION 'Missing user_id';
    END IF;
    IF v_user_id IS DISTINCT FROM auth.uid()
       AND NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
      RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
    END IF;

    v_statuses := COALESCE(
      (
        SELECT array_agg(value)
        FROM jsonb_array_elements_text(COALESCE(p_payload -> 'statuses', '[]'::jsonb)) AS t(value)
      ),
      ARRAY[]::text[]
    );

    RETURN jsonb_build_object(
      'rows',
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'cancel_at_period_end', ms.cancel_at_period_end,
              'id', ms.id,
              'next_billing_date', ms.next_billing_date,
              'package', jsonb_build_object(
                'governance_tokens', sp.governance_tokens,
                'impact_tokens', sp.impact_tokens,
                'name', sp.name,
                'period', sp.period,
                'tier', sp.tier
              ),
              'package_id', ms.package_id,
              'payment_type', ms.payment_type,
              'period_end', ms.period_end,
              'period_start', ms.period_start,
              'status', ms.status,
              'stripe_subscription_id', ms.stripe_subscription_id
            )
            ORDER BY ms.created_at DESC
          )
          FROM public.member_subscriptions ms
          LEFT JOIN public.subscription_packages sp ON sp.id = ms.package_id
          WHERE ms.user_id = v_user_id
            AND (
              cardinality(v_statuses) = 0
              OR ms.status = ANY(v_statuses)
            )
        ),
        '[]'::jsonb
      )
    );
  END IF;

  IF p_action = 'update_package_stripe' THEN
    v_package_id := NULLIF(p_payload ->> 'package_id', '')::uuid;
    IF v_package_id IS NULL THEN
      RAISE EXCEPTION 'Missing package_id';
    END IF;

    UPDATE public.subscription_packages
    SET
      stripe_price_id_one_time = CASE WHEN p_payload ? 'stripe_price_id_one_time' THEN NULLIF(p_payload ->> 'stripe_price_id_one_time', '') ELSE stripe_price_id_one_time END,
      stripe_price_id_recurring = CASE WHEN p_payload ? 'stripe_price_id_recurring' THEN NULLIF(p_payload ->> 'stripe_price_id_recurring', '') ELSE stripe_price_id_recurring END,
      stripe_product_id = CASE WHEN p_payload ? 'stripe_product_id' THEN NULLIF(p_payload ->> 'stripe_product_id', '') ELSE stripe_product_id END,
      updated_at = now()
    WHERE id = v_package_id;

    RETURN jsonb_build_object('ok', true, 'updated', FOUND);
  END IF;

  IF p_action = 'update_subscription' THEN
    v_id := NULLIF(p_payload ->> 'id', '')::uuid;
    v_stripe_subscription_id := NULLIF(p_payload ->> 'stripe_subscription_id', '');

    IF v_id IS NULL AND v_stripe_subscription_id IS NULL THEN
      RAISE EXCEPTION 'Missing subscription selector';
    END IF;

    UPDATE public.member_subscriptions
    SET
      cancel_at_period_end = CASE WHEN p_payload ? 'cancel_at_period_end' THEN (p_payload ->> 'cancel_at_period_end')::boolean ELSE cancel_at_period_end END,
      next_billing_date = CASE WHEN p_payload ? 'next_billing_date' THEN NULLIF(p_payload ->> 'next_billing_date', '')::timestamptz ELSE next_billing_date END,
      status = COALESCE(NULLIF(p_payload ->> 'status', ''), status),
      stripe_invoice_id = CASE WHEN p_payload ? 'stripe_invoice_id' THEN NULLIF(p_payload ->> 'stripe_invoice_id', '') ELSE stripe_invoice_id END,
      stripe_payment_intent_id = CASE WHEN p_payload ? 'stripe_payment_intent_id' THEN NULLIF(p_payload ->> 'stripe_payment_intent_id', '') ELSE stripe_payment_intent_id END,
      stripe_subscription_id = CASE WHEN p_payload ? 'new_stripe_subscription_id' THEN NULLIF(p_payload ->> 'new_stripe_subscription_id', '') ELSE stripe_subscription_id END
    WHERE (
      (v_id IS NOT NULL AND id = v_id)
      OR
      (v_id IS NULL AND v_stripe_subscription_id IS NOT NULL AND stripe_subscription_id = v_stripe_subscription_id)
    );

    RETURN jsonb_build_object('ok', true, 'updated', FOUND);
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_subscriptions(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edge_subscriptions(text, jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.edge_subscriptions(text, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/enforce_rate_limit_for.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: enforce_rate_limit_for
-- Servisní varianta enforce_rate_limit nad TOUŽ tabulkou api_rate_limits (ADR-004,
-- bod 4; revize B4: connect je jinak orákulum hesel proti zdroji).
--
-- ⛔ PROČ NE enforce_rate_limit: ta počítá podle auth.uid() a BEZ něj tiše
-- propustí (RETURN) — pro broker, který volá jako servis, by limitovala naoko.
-- Tahle je FAIL-CLOSED: chybějící nebo neexistující uživatel = výjimka, ne průchod.
-- Stav je v DB → limit platí napříč replikami brokeru (paměť procesu by se násobila).
-- Úklid: cleanup_old_rate_limits() v tiku plánovače brokeru. JEN servisní role.
-- Překročení = výjimka 'RATE_LIMIT_EXCEEDED' (SQLSTATE P0429), broker ji mapuje na 429.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.enforce_rate_limit_for(p_user_id uuid, p_endpoint_key text, p_window_ms integer, p_max_requests integer)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $$
DECLARE
  v_id uuid;
  v_count integer;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'AISHA_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  IF p_user_id IS NULL OR coalesce(btrim(p_endpoint_key), '') = ''
     OR coalesce(p_window_ms, 0) <= 0 OR coalesce(p_max_requests, 0) <= 0 THEN
    RAISE EXCEPTION 'RATE_LIMIT_INVALID' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM aisha_auth.users u WHERE u.id = p_user_id) THEN
    RAISE EXCEPTION 'RATE_LIMIT_UNKNOWN_USER' USING ERRCODE = '22023';
  END IF;
  -- Souběžné požadavky téhož klíče (i z víc replik) serializovat, jinak dva INSERTy
  -- vyrobí dvě okna a limit se zdvojí.
  PERFORM pg_advisory_xact_lock(hashtext('api_rate_limits'), hashtext(p_user_id::text || '|' || p_endpoint_key));
  SELECT id, request_count INTO v_id, v_count
    FROM public.api_rate_limits
   WHERE user_id = p_user_id AND endpoint_key = p_endpoint_key AND window_end > now()
   LIMIT 1;
  IF v_id IS NOT NULL THEN
    UPDATE public.api_rate_limits SET request_count = request_count + 1, updated_at = now() WHERE id = v_id;
    v_count := v_count + 1;
  ELSE
    DELETE FROM public.api_rate_limits WHERE user_id = p_user_id AND endpoint_key = p_endpoint_key;
    INSERT INTO public.api_rate_limits (user_id, endpoint_key, request_count, window_start, window_end)
    VALUES (p_user_id, p_endpoint_key, 1, now(), now() + (p_window_ms || ' milliseconds')::interval);
    v_count := 1;
  END IF;
  IF v_count > p_max_requests THEN
    RAISE EXCEPTION 'RATE_LIMIT_EXCEEDED' USING ERRCODE = 'P0429';
  END IF;
END;
$$;
REVOKE ALL ON FUNCTION public.enforce_rate_limit_for(uuid, text, integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.enforce_rate_limit_for(uuid, text, integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/enrol_kiosk_device.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: enrol_kiosk_device
-- Popis: TABLET v kiosku ohlásí svůj průkaz (klíč VER 2) SÁM, bez přihlášeného
--        člověka. Průkaz vznikne jako ČEKAJÍCÍ; schvaluje ho vždy správce
--        (admin_set_knock_device_approval) — ohlášení nic neschvaluje.
-- Bezpečnost: SECURITY DEFINER, JEN služba (brána). Brána volá až po ověření:
--   · adresa požadavku je právě OTEVŘENÁ zaťukáním (svc-knock /dvere = 204) —
--     tablet se ohlašuje ze sítě, kam ho pustil technik svým kódem,
--   · požadavek je PODEPSANÝ klíčem, který ohlašuje (AISHA-REQ1, knock-protocol)
--     — kdo ohlašuje, klíč opravdu drží.
--
-- ⭐ ROZHODNUTÍ MAJITELE (2026-09-28): „po kliknutí na zavedení zařízení se klíč
--    odešle na backend, protože je odemčeno, a následně to zařízení můžeme
--    permanentně v administraci schválit, aby si tablet mohl ťukat sám bez
--    zadávání kódu." Průkaz vždy schvaluje správce v seznamu tabletů, které se
--    ohlásily (rozhodnutí 26. 9.) — žádné automatické schválení.
--
-- ⛔ OHLÁŠENÍ NIKDY NEMĚNÍ STAV SCHVÁLENÍ. Existující `kid` jen obnoví „naposledy
--    viděn", adresu a verze; odvolaný průkaz se ohlášením NEOBNOVÍ (jinak by
--    odvolání šlo obejít opakovaným ohlášením) a osobní průkaz se NEPŘEPÍŠE na
--    průkaz tabletu.
-- ⛔ STROP NA ADRESU: z jedné adresy nejvýš 20 nových tabletů za hodinu. Ohlášení
--    je bez přihlášení; bez stropu by šlo zaplavit seznam ke schválení.
--
-- Kontrakt: (text, text, text, inet, jsonb) -> jsonb {ok, stav, kid} | {ok:false, error}
--   stav: 'ceka' | 'schvaleno' | 'odvolano'
-- ============================================================================

CREATE OR REPLACE FUNCTION public.enrol_kiosk_device(
  p_kid text,
  p_public_key_hex text,
  p_scope text,
  p_ip inet,
  p_verze jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_radek public.knock_device_credentials%ROWTYPE;
  v_novych int;
BEGIN
  IF NOT (SELECT public.is_service_role()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF p_public_key_hex IS NULL OR p_public_key_hex !~ '^04[0-9a-f]{128}$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'public_key_hex musí být SEC1 nekomprimovaný bod (04 || X || Y, 65 B)');
  END IF;
  IF p_kid IS DISTINCT FROM 'dev-' || substring(p_public_key_hex from 3 for 16) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'kid neodpovídá klíči');
  END IF;
  IF p_scope IS NULL OR length(p_scope) = 0 OR length(p_scope) > 64 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'scope je povinný');
  END IF;
  IF p_ip IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'adresa ohlášení je povinná');
  END IF;
  IF p_verze IS NOT NULL AND (jsonb_typeof(p_verze) <> 'object' OR length(p_verze::text) > 1024) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'verze musí být malý objekt');
  END IF;

  SELECT * INTO v_radek FROM public.knock_device_credentials WHERE kid = p_kid;
  IF FOUND THEN
    UPDATE public.knock_device_credentials
       SET last_seen_at = now(),
           ohlaseno_z_ip = CASE WHEN druh = 'tablet' THEN p_ip ELSE ohlaseno_z_ip END,
           verze = CASE WHEN druh = 'tablet' THEN COALESCE(p_verze, verze) ELSE verze END,
           updated_at = now()
     WHERE kid = p_kid;
    RETURN jsonb_build_object(
      'ok', true,
      'kid', p_kid,
      'stav', CASE
        WHEN v_radek.revoked_at IS NOT NULL THEN 'odvolano'
        WHEN v_radek.approved_at IS NOT NULL THEN 'schvaleno'
        ELSE 'ceka'
      END
    );
  END IF;

  SELECT count(*) INTO v_novych
    FROM public.knock_device_credentials
   WHERE druh = 'tablet' AND ohlaseno_z_ip = p_ip AND first_seen_at > now() - interval '1 hour';
  IF v_novych >= 20 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'z této adresy se za hodinu ohlásilo příliš mnoho tabletů');
  END IF;

  INSERT INTO public.knock_device_credentials (kid, public_key_hex, scope, owner_user_id, druh, ohlaseno_z_ip, verze)
  VALUES (p_kid, p_public_key_hex, p_scope, NULL, 'tablet', p_ip, p_verze);

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (NULL, 'knock_device_enrolled', jsonb_build_object('kid', p_kid, 'druh', 'tablet', 'scope', p_scope));

  RETURN jsonb_build_object('ok', true, 'kid', p_kid, 'stav', 'ceka');
END;
$function$;

REVOKE ALL ON FUNCTION public.enrol_kiosk_device(text, text, text, inet, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.enrol_kiosk_device(text, text, text, inet, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/ensure_production_batch_story.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: ensure_production_batch_story
-- Popis: Story per procesní běh (idempotentní): partner_stories origin=process, success_criteria = milníky šablony, extends link na nadřazenou story, batch_created zápis.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- Pozn.: definice = regenerát z nasazené DB (ověřeno provozním testem 07-25).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.ensure_production_batch_story(p_batch_id uuid, p_parent_story_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_batch production_batches%rowtype;
  v_steps jsonb;
  v_criteria jsonb;
  v_tpl_name text;
  v_tpl_desc text;
  v_story_id uuid;
begin
  if not (is_admin_or_staff(auth.uid()) or is_service_role()) then
    return jsonb_build_object('ok',false,'error','admin, staff or service role required');
  end if;
  select * into v_batch from production_batches where id = p_batch_id;
  if not found then
    return jsonb_build_object('ok',false,'error','batch not found');
  end if;
  if v_batch.story_id is not null then
    return jsonb_build_object('ok',true,'story_id',v_batch.story_id,'created',false);
  end if;
  select name, description, coalesce(nullif(workflow_steps,'null'::jsonb), steps)
    into v_tpl_name, v_tpl_desc, v_steps
  from production_workflow_templates where id = v_batch.workflow_template_id;
  -- milestones become the story's success criteria (goal surface for the loop)
  select coalesce(jsonb_agg(s->>'step_name' order by (s->>'step_order')::int), '[]'::jsonb)
    into v_criteria
  from jsonb_array_elements(coalesce(v_steps,'[]'::jsonb)) s;
  insert into partner_stories (user_id, title, status, priority, origin, is_stack_default, project_preview)
  values (
    auth.uid(),
    coalesce(p_title, v_batch.batch_code || ' · ' || coalesce(v_batch.product_name,'')),
    'active', 'normal', 'process', false,
    jsonb_build_object(
      'summary', coalesce(v_tpl_desc, v_tpl_name, 'Process run'),
      'goals', coalesce(to_jsonb(array[v_tpl_name]), '[]'::jsonb),
      'constraints', '[]'::jsonb,
      'success_criteria', v_criteria)
  ) returning id into v_story_id;
  update production_batches set story_id = v_story_id where id = p_batch_id;
  if p_parent_story_id is not null then
    insert into story_links (source_story_id, target_story_id, link_type, link_direction,
                             created_by, created_by_agent, is_accepted, metadata)
    values (v_story_id, p_parent_story_id, 'extends', 'forward',
            auth.uid(), 'workflow', true,
            jsonb_build_object('origin','process','batch_id',p_batch_id));
  end if;
  perform add_story_system_entry(
    v_story_id, 'tracking_event', 'workflow.timeline.batch_created',
    jsonb_build_object('batch_id',p_batch_id,'batch_code',v_batch.batch_code,
                       'template_id',v_batch.workflow_template_id,'template_name',v_tpl_name),
    now(), 'production_batches', p_batch_id);
  return jsonb_build_object('ok',true,'story_id',v_story_id,'created',true);
end $function$;

REVOKE ALL ON FUNCTION public.ensure_production_batch_story(uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.ensure_production_batch_story(uuid,uuid,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ensure_production_batch_story(uuid,uuid,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/ensure_source_story.sql
-- -----------------------------------------------------------------------------

-- Function: public.ensure_source_story
-- Story ingestovaného zdroje se RESOLVUJE z identity, nezadává se do konfigurace.
--
-- Proč: engine razítkoval do každého emitovaného řádku `impl.json → story_id`,
-- tedy UUID vypsané do konfigurace (v šabloně dokonce PRÁZDNÝ řetězec). Takový
-- balíček nepřežije přestavbu databáze — naměřeno 2026-08-30: 3 822 řádků
-- odkazovalo na story, která má v DB nula řádků, a driver na ní fail-closed
-- padal. Twins tutéž přestavbu přežívají právě proto, že jsou klíčované
-- IDENTITOU `(source, source_key)`, ne syrovým UUID.
--
-- Tvar je kanonický, ne nový: `ensure_production_batch_story` dělá totéž pro
-- výrobní dávku — VĚC, o které story je, si `story_id` drží, a RPC ho najde
-- nebo založí. Zde je tou věcí registrovaný zdroj.
--
-- Fail-closed: neznámý nebo neaktivní zdroj je STOP, ne založení story.
-- Shodně s `register_source_document_audited` — zdroj musí nejdřív projít
-- onboardingem (klasifikace, consent), teprve pak smí vlastnit obsah.
-- Nejistota se neobchází výchozí hodnotou.
--
-- Story vzniká ve stavu `inbox`, tedy NEVIDITELNÁ: o tom, že story vznikla,
-- rozhoduje automatika ingestu; o tom, že ji člověk uvidí, rozhoduje člověk.
--
-- Security: SECURITY DEFINER. Admin/staff nebo service_role.
-- @audit: required

CREATE OR REPLACE FUNCTION public.ensure_source_story(
  p_source_slug text,
  p_title       text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_source   public.agent_knowledge_sources%ROWTYPE;
  v_story_id uuid;
  v_navrzen  uuid;
  -- ⛔ NE `FOUND`: přepíše ho KAŽDÝ následující příkaz (UPDATE i INSERT níž),
  -- takže by rozhodnutí „zdroj mám" záviselo na tom, kolik řádků se právě
  -- dotklo auditu. Příznak drží ODPOVĚĎ, ne poslední vedlejší účinek.
  v_mam      boolean := false;
BEGIN
  IF NOT (public.is_admin_or_staff(auth.uid()) OR public.is_service_role()) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'admin, staff or service role required');
  END IF;

  IF p_source_slug IS NULL OR btrim(p_source_slug) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'source slug required');
  END IF;

  SELECT * INTO v_source
  FROM public.agent_knowledge_sources
  WHERE source_slug = p_source_slug AND is_active;
  v_mam := FOUND;

  -- ⭐ SJEDNOCENÍ IDENTITY: aktivní zdroj smí POHLTIT historický slug.
  --
  -- ⛔ NAMĚŘENO 2026-09-02: engine značí balíčky `local-ingest`, ale TŘI balíčky
  -- ze 3.–4. 8. nesou `aisha-local-ingest` (jméno aplikace, ne registrovaného
  -- zdroje) — jednorázová anomálie jednoho exportního běhu, poznatelná i podle
  -- odlišného tvaru `export_id` (bez časové zóny). Ta tři jména založila NÁVRH,
  -- který se nedá aktivovat, a od té doby blokují každý běh: 1435 syncs, 1435
  -- failures, `last_success_at` NULL.
  --
  -- Bez tohohle kroku má jedna skutečnost DVĚ identity a obě se tváří jako
  -- samostatný zdroj. Řešit to přejmenováním v balíčcích nejde — jsou podepsané
  -- a už odeslané; řešit to druhým aktivním zdrojem by duplicitu zabetonovalo.
  --
  -- Pohlcení je KURÁTOROVANÉ ROZHODNUTÍ, ne heuristika: zapisuje ho člověk přes
  -- `set_data_source_config` do `config.nahrazuje`. Stroj nikdy neuhodne, že dvě
  -- jména znamenají totéž — to je tvrzení o světě, ne o datech.
  IF NOT v_mam THEN
    SELECT * INTO v_source
    FROM public.agent_knowledge_sources
    WHERE is_active AND (config -> 'nahrazuje') ? p_source_slug
    ORDER BY source_slug
    LIMIT 1;
    v_mam := FOUND;
    IF v_mam THEN
      -- Aby administrace neukazovala pohlcený návrh dál jako „čeká na
      -- klasifikaci": stav se zapíše k němu, ne jen do logu. Idempotentní.
      UPDATE public.agent_knowledge_sources
         SET config = coalesce(config, '{}'::jsonb)
                      || jsonb_build_object('superseded_by', v_source.source_slug),
             updated_at = now()
       WHERE source_slug = p_source_slug
         AND coalesce(config ->> 'superseded_by', '') <> v_source.source_slug;
      INSERT INTO public.audit_journal (user_id, action, metadata)
      VALUES (auth.uid(), 'ingest.source.absorbed',
              jsonb_build_object('slug', p_source_slug,
                                 'resolved_to', v_source.source_slug));
    END IF;
  END IF;

  IF NOT v_mam THEN
    -- ⭐ ZDROJ NAJDE INGEST, AKTIVUJE HO ČLOVĚK.
    --
    -- Odmítnutí zůstává (viz níž `ok:false`) — obsah bez kontextu nemá scope.
    -- Co se mění: dřív po sobě odmítnutí NENECHALO STOPU, takže operátor musel
    -- tušit, že se někde hlásí zdroj čekající na klasifikaci. „Nic tu není" se
    -- nedalo odlišit od „nikdo se nehlásil".
    --
    -- Zakládá se proto NEAKTIVNÍ řádek — návrh. Žádné oprávnění tím nevzniká:
    -- neaktivní zdroj nesmí vyrobit obsah ani kontext a `activation_guard` ho
    -- bez úplné 4D klasifikace ani nepustí aktivovat. Je to táž doktrína jako
    -- u vazeb: stroj navrhuje s důkazem, člověk ratifikuje VZOR — jednou pro
    -- zdroj, ne pro každý balíček.
    --
    -- Klasifikace se ZÁMĚRNĚ nedoplňuje ani prázdná: `legal_basis` a `retention_class`
    -- jsou fakta o právním vztahu, ne o datech. Uhodnout je nejde ani nemá.
    IF EXISTS (SELECT 1 FROM public.agent_knowledge_sources WHERE source_slug = p_source_slug) THEN
      -- Zdroj JE, jen není aktivní. Nesaháme na něj: mohl být vypnutý záměrně
      -- a přepsat cizí rozhodnutí návrhem by bylo horší než mlčet.
      RETURN jsonb_build_object('ok', false, 'error', 'unknown or inactive source',
                                'source_slug', p_source_slug, 'proposed', false);
    END IF;

    -- Slug musí projít formátem tabulky, jinak by INSERT spadl výjimkou místo
    -- odpovědi. Neplatný slug je vada balíčku, ne důvod ke zhroucení.
    IF p_source_slug ~ '^[a-z0-9][a-z0-9_-]*$' THEN
      INSERT INTO public.agent_knowledge_sources (source_slug, namespace, is_active, config)
      VALUES (p_source_slug,
              -- Provizorní jmenný prostor: říká, ODKUD se zdroj ohlásil.
              -- Není to tvrzení o zařazení — to nastaví člověk při schválení.
              'ingest/' || p_source_slug,
              false,
              jsonb_build_object('proposed_by', 'ingest',
                                 'proposed_at', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SSOF'),
                                 'note', 'Ohlásil se ingest. Chybí 4D klasifikace '
                                      || '(source_type, data_sensitivity, retention_class, legal_basis) '
                                      || 'a vlastník (owner); bez nich zdroj nelze aktivovat.'))
      ON CONFLICT (source_slug) DO NOTHING
      RETURNING id INTO v_navrzen;

      IF v_navrzen IS NOT NULL THEN
        INSERT INTO public.audit_journal (user_id, action, metadata)
        VALUES (auth.uid(), 'ingest.source.proposed',
                jsonb_build_object('source_slug', p_source_slug, 'source_id', v_navrzen));
      END IF;
    END IF;

    -- Táž chyba a týž kód jako register_source_document_audited: jedna vlastnost,
    -- jedna odpověď. Zdroj mimo registr nesmí vyrobit obsah ani kontext.
    RETURN jsonb_build_object('ok', false, 'error', 'unknown or inactive source',
                              'source_slug', p_source_slug,
                              'proposed', v_navrzen IS NOT NULL);
  END IF;

  IF v_source.story_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'story_id', v_source.story_id, 'created', false);
  END IF;

  INSERT INTO public.partner_stories (
    partner_id, user_id, title, status, priority, origin, is_stack_default, project_preview
  ) VALUES (
    NULL,
    auth.uid(),
    COALESCE(NULLIF(btrim(p_title), ''), v_source.source_slug),
    'inbox',            -- neviditelná, dokud ji člověk nepřijme
    'normal',
    'ingest',
    false,
    jsonb_build_object(
      'summary', 'Kontext ingestovaného zdroje ' || v_source.source_slug,
      'goals', '[]'::jsonb,
      'constraints', '[]'::jsonb,
      'success_criteria', '[]'::jsonb)
  ) RETURNING id INTO v_story_id;

  UPDATE public.agent_knowledge_sources
     SET story_id = v_story_id, updated_at = now()
   WHERE id = v_source.id;

  PERFORM public.add_story_system_entry(
    v_story_id, 'tracking_event', 'ingest.source.story_created',
    jsonb_build_object('source_slug', v_source.source_slug,
                       'namespace', v_source.namespace),
    now(), 'agent_knowledge_sources', v_source.id);

  RETURN jsonb_build_object('ok', true, 'story_id', v_story_id, 'created', true);
END $function$;

REVOKE ALL ON FUNCTION public.ensure_source_story(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.ensure_source_story(text,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ensure_source_story(text,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/ensure_stack_default_story.sql
-- -----------------------------------------------------------------------------

-- ensure_stack_default_story
-- Returns the id of the singleton stack-default story, creating it if missing.
-- Stack-default = the story that owns iterations for the public default web
-- ( = "your Aisha stack is online" landing page).
--
-- Logic is identical to any other story: same table, same lifecycle, same
-- chat-driven UI. Only difference: partner_id IS NULL and is_stack_default = true.
-- Singleton enforced by a partial UNIQUE INDEX.

CREATE OR REPLACE FUNCTION public.ensure_stack_default_story()
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_story_id uuid;
  v_is_service boolean;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin/staff or service_role required';
  END IF;

  SELECT id INTO v_story_id
  FROM public.partner_stories
  WHERE is_stack_default = true
  LIMIT 1;

  IF v_story_id IS NOT NULL THEN
    RETURN v_story_id;
  END IF;

  INSERT INTO public.partner_stories (
    partner_id, user_id, title, status, priority,
    is_stack_default, origin, project_preview
  ) VALUES (
    NULL, NULL,
    'Stack default web',
    'inbox', 'normal',
    true, 'stack_bootstrap',
    jsonb_build_object(
      'summary', 'Singleton story owning iterations for the public default web page (slug=index).',
      'goals', jsonb_build_array('Surface the seeded hello-stack landing', 'Allow operators to iterate on it like any other story'),
      'constraints', jsonb_build_array('Singleton — only one row with is_stack_default=true exists.'),
      'success_criteria', jsonb_build_array('Default seed applies first artifact to web_pages.slug=index'),
      'meta', jsonb_build_object('owner', 'stack')
    )
  )
  RETURNING id INTO v_story_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'STACK_DEFAULT_STORY_CREATED',
    jsonb_build_object(
      'area', 'content',
      'severity', 'info',
      'entity_type', 'partner_story',
      'entity_id', v_story_id::text,
      'tags', ARRAY['stack', 'story', 'web_artifact', 'bootstrap']
    )
  );

  RETURN v_story_id;
END;
$$;

REVOKE ALL ON FUNCTION public.ensure_stack_default_story() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.ensure_stack_default_story() TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/evaluate_workflow_milestone_signal.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: evaluate_workflow_milestone_signal
-- Popis: Milník dosažený SIGNÁLEM po nativní integration_events sběrnici. Kritéria = DATA na uzlu (complete_on: event_type + match containment). Bez odměny (signál nemá lidského příjemce). Goal re-evaluace.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- Pozn.: definice = regenerát z nasazené DB (ověřeno provozním testem 07-25).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.evaluate_workflow_milestone_signal(p_event_id uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ev integration_events%rowtype;
  v_step record;
  v_done jsonb := '[]'::jsonb;
  v_n int := 0;
begin
  if not (is_admin_or_staff(auth.uid()) or is_service_role()) then
    return jsonb_build_object('ok',false,'error','admin, staff or service role required');
  end if;
  select * into v_ev from integration_events where id = p_event_id;
  if not found then
    return jsonb_build_object('ok',false,'error','integration event not found');
  end if;
  if v_ev.story_id is null then
    return jsonb_build_object('ok',false,'error','event has no story routing');
  end if;
  for v_step in
    select s.* from production_workflow_steps s
    join production_batches b on b.id = s.batch_id
    where b.story_id = v_ev.story_id
      and s.status in ('pending','in_progress')
      and s.input_data ? 'complete_on'
      and s.input_data->'complete_on'->>'event_type' = v_ev.event_type
      and (not (s.input_data->'complete_on' ? 'match')
           or p_payload @> (s.input_data->'complete_on'->'match'))
    order by s.step_order
    for update of s
  loop
    update production_workflow_steps set
      status = 'completed', completed_by = null, completed_at = now(),
      output_data = jsonb_build_object('signal_event_id',p_event_id,
                                       'event_source',v_ev.event_source,
                                       'event_type',v_ev.event_type,
                                       'payload',p_payload),
      notes = 'signal-completed', updated_at = now()
    where id = v_step.id;
    perform add_story_system_entry(
      v_ev.story_id, 'tracking_event', 'workflow.timeline.milestone_signal',
      jsonb_build_object('step_code',v_step.step_code,'step_name',v_step.step_name,
                         'step_order',v_step.step_order,'batch_id',v_step.batch_id,
                         'event_source',v_ev.event_source,'event_type',v_ev.event_type,
                         'signal_event_id',p_event_id),
      now(), 'production_workflow_steps', v_step.id);
    v_done := v_done || jsonb_build_object('step_id',v_step.id,'step_code',v_step.step_code);
    v_n := v_n + 1;
  end loop;
  update integration_events
    set metadata = coalesce(metadata,'{}'::jsonb)
        || jsonb_build_object('payload',p_payload,'workflow_completed_steps',v_n)
  where id = p_event_id;
  perform complete_integration_event(p_event_id, 'completed', null, null);
  if v_n > 0 then
    begin
      perform evaluate_story_process_goal(v_ev.story_id);
        exception when others then
      -- goal re-evaluation is a side effect and must never roll back the
      -- operational fact — but the failure is LOGGED, never swallowed
      insert into audit_journal (user_id, action, metadata)
      values (auth.uid(), 'workflow.goal_evaluation_failed',
              jsonb_build_object('error', SQLERRM));
    end;
  end if;
  return jsonb_build_object('ok',true,'completed_count',v_n,'completed_steps',v_done);
end $function$;

REVOKE ALL ON FUNCTION public.evaluate_workflow_milestone_signal(uuid,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.evaluate_workflow_milestone_signal(uuid,jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fail_web_artifact_ingest.sql
-- -----------------------------------------------------------------------------

-- fail_web_artifact_ingest
-- service_role only: transition any non-terminal state -> failed.
-- Appends a story_entries row (entry_type=web_artifact_failed) so operators
-- see the failure in the storyloop timeline.

CREATE OR REPLACE FUNCTION public.fail_web_artifact_ingest(
  p_job_id uuid,
  p_error_message text
)
RETURNS void
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean;
  v_job record;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service THEN
    RAISE EXCEPTION 'Unauthorized: service_role required';
  END IF;

  SELECT id, status, story_id, kind INTO v_job
  FROM public.web_artifact_jobs
  WHERE id = p_job_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found: %', p_job_id;
  END IF;

  IF v_job.status IN ('applied', 'failed', 'rejected') THEN
    RAISE EXCEPTION 'Job in terminal state (%), cannot fail', v_job.status;
  END IF;

  UPDATE public.web_artifact_jobs
  SET status = 'failed',
      error_message = COALESCE(p_error_message, 'Unknown error'),
      processed_at = COALESCE(processed_at, now())
  WHERE id = p_job_id;

  IF v_job.story_id IS NOT NULL THEN
    INSERT INTO public.story_entries (story_id, entry_type, content, metadata, created_by)
    VALUES (
      v_job.story_id,
      'web_artifact_failed',
      NULL,
      jsonb_build_object(
        'type', 'web_artifact_failed',
        'job_id', p_job_id,
        'kind', v_job.kind::text,
        'error_message', COALESCE(p_error_message, 'Unknown error')
      ),
      NULL
    );
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    NULL,
    'WEB_ARTIFACT_INGEST_FAIL',
    jsonb_build_object(
      'area', 'content',
      'severity', 'warning',
      'entity_type', 'web_artifact_job',
      'entity_id', p_job_id::text,
      'story_id', v_job.story_id,
      'kind', v_job.kind::text,
      'error_message', p_error_message,
      'tags', ARRAY['stack', 'story', 'web_artifact', 'fail']
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fail_web_artifact_ingest(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fail_web_artifact_ingest(uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/federated_caller_for.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: federated_caller_for
-- Popis: Provider-generic federation resolver — the AISHA user's external identity
--        at a given provider, so a connector can drive that external system AS THE
--        REAL USER (caller_id federation, connector doctrine). Generalizes
--        the named predecessor over the already provider-generic aisha_auth.identities;
--        a new controllable source declares only its provider slug and reuses this.
--
-- Fail-CLOSED authz via is_service_role() (NOT the inline NULL-3VL idiom that the
-- named predecessor carried). Returns the provider_id or NULL if unlinked.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.federated_caller_for(
  p_provider text,
  p_user_id  uuid
)
RETURNS text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'aisha_auth'
AS $$
DECLARE v_caller text;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;
  IF p_provider IS NULL OR btrim(p_provider) = '' THEN
    RAISE EXCEPTION 'federated_caller_for: a provider is required';
  END IF;
  SELECT provider_id INTO v_caller
  FROM aisha_auth.identities
  WHERE user_id = p_user_id AND provider = p_provider
  LIMIT 1;
  RETURN v_caller;
END;
$$;

REVOKE ALL ON FUNCTION public.federated_caller_for(text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.federated_caller_for(text, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.federated_caller_for(text, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/federated_flow_nonce_use.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: federated_flow_nonce_use
-- Spotřebuje nonce stavu přihlašovacího toku (ADR-004, bod 4; revize V1, B10).
-- true = první použití; false = přehrání (stav už byl použit) nebo prošlý stav.
-- Evidence v DB → jednorázovost platí napříč replikami brokeru. JEN servisní role.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.federated_flow_nonce_use(p_nonce text, p_user_id uuid, p_provider text, p_expires_at timestamptz)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $$
DECLARE
  v_n integer;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'AISHA_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  IF p_nonce IS NULL OR length(p_nonce) < 16 OR p_user_id IS NULL OR coalesce(btrim(p_provider), '') = '' THEN
    RAISE EXCEPTION 'FEDERATED_FLOW_INVALID' USING ERRCODE = '22023';
  END IF;
  IF p_expires_at IS NULL OR p_expires_at <= now() THEN
    RETURN false;
  END IF;
  INSERT INTO public.federated_flow_nonces (nonce, user_id, provider, expires_at)
  VALUES (p_nonce, p_user_id, p_provider, p_expires_at)
  ON CONFLICT (nonce) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n = 1;
END;
$$;
REVOKE ALL ON FUNCTION public.federated_flow_nonce_use(text, uuid, text, timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.federated_flow_nonce_use(text, uuid, text, timestamptz) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/federated_flow_nonces_cleanup.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: federated_flow_nonces_cleanup
-- Smaže prošlá nonce přihlašovacího toku. Volá plánovač brokeru (scheduler.ts) pod
-- advisory lockem, ve stejném tiku jako cleanup_old_rate_limits(). JEN servisní role.
-- Prošlé nonce už přehrát nejde (federated_flow_nonce_use odmítá prošlé), takže
-- mazání jednorázovost neoslabí.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.federated_flow_nonces_cleanup()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $$
DECLARE
  v_n integer;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'AISHA_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  DELETE FROM public.federated_flow_nonces WHERE expires_at < now();
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;
REVOKE ALL ON FUNCTION public.federated_flow_nonces_cleanup() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.federated_flow_nonces_cleanup() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/federated_identity_link.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: federated_identity_link
-- Popis: Provider-generic identity federation — link an AISHA user to their
--        external identity at any provider (connector doctrine). Generalizes
--        the named predecessor over aisha_auth.identities. Fail-CLOSED authz via
--        is_service_role(); the link is audited through connector_write_audit (v2
--        hashed, provable) instead of a best-effort raw INSERT.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.federated_identity_link(
  p_provider    text,
  p_user_id     uuid,
  p_provider_id text,
  p_email       text DEFAULT NULL
)
RETURNS aisha_auth.identities
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'aisha_auth'
AS $$
DECLARE v_row aisha_auth.identities;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;
  IF p_provider IS NULL OR btrim(p_provider) = ''
     OR p_user_id IS NULL
     OR p_provider_id IS NULL OR btrim(p_provider_id) = '' THEN
    RAISE EXCEPTION 'federated_identity_link: provider, user_id and a non-empty provider_id are required';
  END IF;

  INSERT INTO aisha_auth.identities (user_id, provider, provider_id, email, identity_data, last_sign_in_at)
  VALUES (p_user_id, p_provider, btrim(p_provider_id), p_email,
          jsonb_build_object('linked_via', 'federated_identity_link'), now())
  ON CONFLICT (provider, provider_id) DO UPDATE SET
    user_id    = EXCLUDED.user_id,
    email      = COALESCE(EXCLUDED.email, aisha_auth.identities.email),
    updated_at = now(), last_sign_in_at = now()
  RETURNING * INTO v_row;

  PERFORM public.connector_write_audit(
    'federated_identity.linked', 'curation', 'content', 'info',
    format('Federated an AISHA user to a %s identity', p_provider),
    'federated_identity', p_user_id::text,
    jsonb_build_object('provider', p_provider, 'provider_id', btrim(p_provider_id)),
    auth.uid(), p_provider);

  RETURN v_row;
END;
$$;

REVOKE ALL ON FUNCTION public.federated_identity_link(text, uuid, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.federated_identity_link(text, uuid, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.federated_identity_link(text, uuid, text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/federated_source_session_get_for_caller.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: federated_source_session_get_for_caller
-- Vrátí šifrový text AKTIVNÍ relace uživatele u zdroje (ADR-004). JEN servisní role.
-- Odvolaná nebo prošlá relace se nevrací: volání „za uživatele" pak skončí
-- „připoj účet", NIKDY tichým pádem na servisní účet (revize rady B5).
-- Každé čtení šifrového textu = řádek auditu bez hodnot (broker čte jednou za
-- naplnění své paměti; platnost ověřuje levnou `…_version` bez šifrového textu).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.federated_source_session_get_for_caller(p_user_id uuid, p_provider text)
RETURNS TABLE (source_session_id uuid, version integer, provider_id text, token_ct bytea, refresh_ct bytea, key_id text, expires_at timestamptz)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $$
DECLARE
  r record;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'AISHA_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  SELECT s.id, s.version, s.provider_id, s.token_ct, s.refresh_ct, s.key_id, s.expires_at
    INTO r
    FROM public.federated_source_sessions s
   WHERE s.user_id = p_user_id AND s.provider = p_provider
     AND s.revoked_at IS NULL AND s.expires_at > now();
  IF NOT FOUND THEN
    RETURN;
  END IF;
  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, entity_type, entity_id, metadata)
  VALUES ((SELECT u.id FROM aisha_auth.users u WHERE u.id = p_user_id), 'federace.relace_ctena', 'federace.relace_ctena', 'security', 'info',
          'federated_source_session', r.id::text, jsonb_build_object('provider', p_provider, 'version', r.version, 'uzivatel', p_user_id));
  RETURN QUERY SELECT r.id, r.version, r.provider_id, r.token_ct, r.refresh_ct, r.key_id, r.expires_at;
END;
$$;
REVOKE ALL ON FUNCTION public.federated_source_session_get_for_caller(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.federated_source_session_get_for_caller(uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/federated_source_session_logout_due.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: federated_source_session_logout_due
-- Fronta odhlášení u zdroje (ADR-004, bod 6; revize B3). Nová fronta NEVZNIKÁ:
-- frontou jsou řádky trezoru s `revoked_at` a bez `logout_done_at`. Zpracovává ji
-- plánovač brokeru (scheduler.ts) pod advisory lockem; `FOR UPDATE SKIP LOCKED` je
-- druhá pojistka proti zdvojení mezi replikami.
-- Nejdřív odvolá relace, které odvolat MÁ: prošlé (`expires_at`) a relace
-- uživatelů, kteří v aishe už nejsou (bez cizího klíče — viz tabulka).
-- Vrací šifrový text, protože odhlášení u zdroje potřebuje ten token → audit.
-- `p_providers` = zdroje, které volající broker umí odhlásit (má jejich plugin);
-- relace ostatních zdrojů zůstávají ve frontě a nečtou se (žádný audit naprázdno).
-- JEN servisní role.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.federated_source_session_logout_due(p_providers text[], p_limit integer DEFAULT 20)
RETURNS TABLE (source_session_id uuid, user_id uuid, provider text, token_ct bytea, key_id text, logout_attempts integer)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $$
DECLARE
  r record;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'AISHA_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;

  UPDATE public.federated_source_sessions s
     SET revoked_at = now(), revoke_reason = 'vyprsela', logout_next_at = now()
   WHERE s.revoked_at IS NULL AND s.expires_at <= now();

  UPDATE public.federated_source_sessions s
     SET revoked_at = now(), revoke_reason = 'uzivatel_neexistuje', logout_next_at = now()
   WHERE s.revoked_at IS NULL
     AND NOT EXISTS (SELECT 1 FROM aisha_auth.users u WHERE u.id = s.user_id);

  FOR r IN
    SELECT s.id, s.user_id, s.provider, s.token_ct, s.key_id, s.logout_attempts
      FROM public.federated_source_sessions s
     WHERE s.revoked_at IS NOT NULL AND s.logout_done_at IS NULL
       AND s.logout_next_at IS NOT NULL AND s.logout_next_at <= now()
       AND length(s.token_ct) > 0
       AND s.provider = ANY (coalesce(p_providers, ARRAY[]::text[]))
     ORDER BY s.logout_next_at
     LIMIT greatest(coalesce(p_limit, 20), 1)
     FOR UPDATE SKIP LOCKED
  LOOP
    INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, entity_type, entity_id, metadata)
    VALUES ((SELECT u.id FROM aisha_auth.users u WHERE u.id = r.user_id), 'federace.odhlaseni_cteno', 'federace.odhlaseni_cteno', 'security', 'info',
            'federated_source_session', r.id::text, jsonb_build_object('provider', r.provider, 'pokus', r.logout_attempts + 1, 'uzivatel', r.user_id));
    source_session_id := r.id; user_id := r.user_id; provider := r.provider;
    token_ct := r.token_ct; key_id := r.key_id; logout_attempts := r.logout_attempts;
    RETURN NEXT;
  END LOOP;
END;
$$;
REVOKE ALL ON FUNCTION public.federated_source_session_logout_due(text[], integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.federated_source_session_logout_due(text[], integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/federated_source_session_logout_result.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: federated_source_session_logout_result
-- Výsledek odhlášení u zdroje (ADR-004, bod 6).
--   'hotovo'        — zdroj token zneplatnil → logout_done_at, šifrový text se MAŽE;
--   'nepodporovano' — zdroj odhlášení neumí (povoleno jen zdrojům s expirací tokenů,
--                     hlídá registrace pluginu) → totéž + audit;
--   'selhalo'       — síť / 5xx: pokus +1, další za 2^pokus minut (strop 6 h);
--                     od 10. pokusu audit „ruční zásah" (warning) a fronta pokračuje.
-- JEN servisní role.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.federated_source_session_logout_result(p_session_id uuid, p_vysledek text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $$
DECLARE
  v_user uuid;
  v_provider text;
  v_pokus integer;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'AISHA_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  IF p_vysledek NOT IN ('hotovo', 'nepodporovano', 'selhalo') THEN
    RAISE EXCEPTION 'FEDERATED_LOGOUT_RESULT_INVALID' USING ERRCODE = '22023';
  END IF;
  IF p_vysledek IN ('hotovo', 'nepodporovano') THEN
    UPDATE public.federated_source_sessions s
       SET logout_done_at = now(), logout_next_at = NULL, token_ct = '\x'::bytea, refresh_ct = NULL
     WHERE s.id = p_session_id AND s.revoked_at IS NOT NULL AND s.logout_done_at IS NULL
    RETURNING s.user_id, s.provider INTO v_user, v_provider;
    IF v_user IS NOT NULL THEN
      INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, entity_type, entity_id, metadata)
      VALUES ((SELECT u.id FROM aisha_auth.users u WHERE u.id = v_user), 'federace.odhlaseno_u_zdroje', 'federace.odhlaseno_u_zdroje', 'security',
              CASE WHEN p_vysledek = 'hotovo' THEN 'info' ELSE 'warning' END,
              'federated_source_session', p_session_id::text,
              jsonb_build_object('provider', v_provider, 'vysledek', p_vysledek, 'uzivatel', v_user));
    END IF;
    RETURN;
  END IF;
  UPDATE public.federated_source_sessions s
     SET logout_attempts = s.logout_attempts + 1,
         logout_next_at = now() + least(power(2, s.logout_attempts + 1) * interval '1 minute', interval '6 hours')
   WHERE s.id = p_session_id AND s.revoked_at IS NOT NULL AND s.logout_done_at IS NULL
  RETURNING s.user_id, s.provider, s.logout_attempts INTO v_user, v_provider, v_pokus;
  IF v_user IS NOT NULL THEN
    INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, entity_type, entity_id, metadata)
    VALUES ((SELECT u.id FROM aisha_auth.users u WHERE u.id = v_user),
            CASE WHEN v_pokus >= 10 THEN 'federace.odhlaseni_rucni_zasah' ELSE 'federace.odhlaseni_neprobehlo' END,
            'federace.odhlaseni_neprobehlo', 'security', CASE WHEN v_pokus >= 10 THEN 'warning' ELSE 'info' END,
            'federated_source_session', p_session_id::text,
            jsonb_build_object('provider', v_provider, 'pokus', v_pokus, 'uzivatel', v_user));
  END IF;
END;
$$;
REVOKE ALL ON FUNCTION public.federated_source_session_logout_result(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.federated_source_session_logout_result(uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/federated_source_session_put.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: federated_source_session_put
-- Uloží relaci uživatele u zdroje (ADR-004, bod 1–4). JEN servisní role (broker).
--
-- `p_session_id` volí broker PŘEDEM, protože je součástí AAD šifrového textu.
-- Předchozí aktivní relace téhož (uživatel, zdroj) se ODVOLÁ s důvodem „nahrazena"
-- a zařadí do fronty odhlášení u zdroje — starý token u zdroje bez expirace jinak
-- platí navždy (revize rady B3). Její id se vrací, aby ji broker mohl odhlásit hned.
-- Účet zdroje (`provider_id`) živě patří nejvýš jednomu uživateli aishy: navázaný
-- u jiného uživatele = odmítnutí (převzetí se neřeší tiše).
-- Audit bez hodnot: jen id relace, zdroj a key_id.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.federated_source_session_put(
  p_session_id uuid,
  p_user_id uuid,
  p_provider text,
  p_provider_id text,
  p_token_ct bytea,
  p_refresh_ct bytea,
  p_key_id text,
  p_expires_at timestamptz
)
RETURNS TABLE (source_session_id uuid, version integer, replaced_source_session_id uuid)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $$
DECLARE
  v_old uuid;
BEGIN
  -- Stráž stojí na VOLAJÍCÍM (role z JWT / SET ROLE), ne na current_user: uvnitř
  -- SECURITY DEFINER je current_user vlastník funkce a prošel by vždy.
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'AISHA_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  IF p_session_id IS NULL OR p_user_id IS NULL OR coalesce(btrim(p_provider), '') = ''
     OR coalesce(btrim(p_provider_id), '') = '' OR p_token_ct IS NULL OR length(p_token_ct) = 0
     OR coalesce(btrim(p_key_id), '') = '' THEN
    RAISE EXCEPTION 'FEDERATED_SESSION_INVALID' USING ERRCODE = '22023';
  END IF;
  IF p_expires_at IS NULL OR p_expires_at <= now() THEN
    RAISE EXCEPTION 'FEDERATED_SESSION_EXPIRES_IN_PAST' USING ERRCODE = '22023';
  END IF;

  -- Relace patří EXISTUJÍCÍMU uživateli aishy (vlastní chyba místo pádu na FK auditu).
  IF NOT EXISTS (SELECT 1 FROM aisha_auth.users u WHERE u.id = p_user_id) THEN
    RAISE EXCEPTION 'FEDERATED_UNKNOWN_USER' USING ERRCODE = '22023';
  END IF;

  -- Souběžné connect téhož uživatele u téhož zdroje serializovat.
  PERFORM pg_advisory_xact_lock(hashtext('federated_source_sessions'), hashtext(p_user_id::text || '|' || p_provider));

  IF EXISTS (
    SELECT 1 FROM public.federated_source_sessions s
    WHERE s.provider = p_provider AND s.provider_id = p_provider_id
      AND s.user_id <> p_user_id AND s.revoked_at IS NULL
  ) THEN
    RAISE EXCEPTION 'FEDERATED_PROVIDER_ID_TAKEN' USING ERRCODE = '23505';
  END IF;

  UPDATE public.federated_source_sessions s
     SET revoked_at = now(), revoke_reason = 'nahrazena', logout_next_at = now()
   WHERE s.user_id = p_user_id AND s.provider = p_provider AND s.revoked_at IS NULL
  RETURNING s.id INTO v_old;

  INSERT INTO public.federated_source_sessions
    (id, user_id, provider, provider_id, token_ct, refresh_ct, key_id, expires_at)
  VALUES
    (p_session_id, p_user_id, p_provider, p_provider_id, p_token_ct, p_refresh_ct, p_key_id, p_expires_at);

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, entity_type, entity_id, metadata)
  VALUES (p_user_id, 'federace.relace_ulozena', 'federace.relace_ulozena', 'security', 'info',
          'federated_source_session', p_session_id::text,
          jsonb_build_object('provider', p_provider, 'key_id', p_key_id, 'nahrazena', v_old));

  RETURN QUERY SELECT p_session_id, 1, v_old;
END;
$$;
REVOKE ALL ON FUNCTION public.federated_source_session_put(uuid, uuid, text, text, bytea, bytea, text, timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.federated_source_session_put(uuid, uuid, text, text, bytea, bytea, text, timestamptz) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/federated_source_session_revoke.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: federated_source_session_revoke
-- Odvolá aktivní relaci uživatele u zdroje (ADR-004, bod 6).
-- Smí: servisní role (broker: odpojení, 401 bez refresh), SÁM uživatel pro SVOU
-- relaci (kontrola subjektu, revize S5) a admin/staff výslovně. Cizí relaci běžný
-- uživatel neodvolá. `revoked_at` se nastaví vždy; token jde do fronty odhlášení
-- u zdroje (bez expirace by jinak platil navždy — revize B3).
-- Vrací počet odvolaných relací (0 nebo 1).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.federated_source_session_revoke(p_user_id uuid, p_provider text, p_reason text)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $$
DECLARE
  v_id uuid;
BEGIN
  IF p_user_id IS NULL OR coalesce(btrim(p_provider), '') = '' THEN
    RAISE EXCEPTION 'FEDERATED_SESSION_INVALID' USING ERRCODE = '22023';
  END IF;
  IF NOT (public.is_service_role()
          OR p_user_id IS NOT DISTINCT FROM auth.uid()
          OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'AISHA_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  UPDATE public.federated_source_sessions s
     SET revoked_at = now(),
         revoke_reason = coalesce(nullif(btrim(p_reason), ''), 'odvolana'),
         logout_next_at = now()
   WHERE s.user_id = p_user_id AND s.provider = p_provider AND s.revoked_at IS NULL
  RETURNING s.id INTO v_id;
  IF v_id IS NULL THEN
    RETURN 0;
  END IF;
  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, entity_type, entity_id, metadata)
  VALUES ((SELECT u.id FROM aisha_auth.users u WHERE u.id = coalesce(auth.uid(), p_user_id)), 'federace.relace_odvolana', 'federace.relace_odvolana', 'security', 'info',
          'federated_source_session', v_id::text,
          jsonb_build_object('provider', p_provider, 'duvod', coalesce(nullif(btrim(p_reason), ''), 'odvolana'),
                             'pro_uzivatele', p_user_id));
  RETURN 1;
END;
$$;
REVOKE ALL ON FUNCTION public.federated_source_session_revoke(uuid, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.federated_source_session_revoke(uuid, text, text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/federated_source_session_rotate.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: federated_source_session_rotate
-- Atomicky vymění šifrový text AKTIVNÍ relace (refresh u zdroje, rotace klíče
-- brokeru) — compare-and-swap na `version` (ADR-004, bod 6–7; revize V2, A14).
-- Nový access token a nový refresh se ukládají SPOLU. Neshoda verze nebo odvolaná
-- relace = FEDERATED_SESSION_STALE: souběžný refresh prohrál, broker si relaci
-- přečte znovu, NEodvolává ji. JEN servisní role.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.federated_source_session_rotate(
  p_session_id uuid,
  p_expected_version integer,
  p_token_ct bytea,
  p_refresh_ct bytea,
  p_key_id text,
  p_expires_at timestamptz
)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $$
DECLARE
  v_new integer;
  v_user uuid;
  v_provider text;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'AISHA_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  IF p_token_ct IS NULL OR length(p_token_ct) = 0 OR coalesce(btrim(p_key_id), '') = ''
     OR p_expires_at IS NULL OR p_expires_at <= now() THEN
    RAISE EXCEPTION 'FEDERATED_SESSION_INVALID' USING ERRCODE = '22023';
  END IF;
  UPDATE public.federated_source_sessions s
     SET token_ct = p_token_ct, refresh_ct = p_refresh_ct, key_id = p_key_id,
         expires_at = p_expires_at, version = s.version + 1, verified_at = now()
   WHERE s.id = p_session_id AND s.version = p_expected_version AND s.revoked_at IS NULL
  RETURNING s.version, s.user_id, s.provider INTO v_new, v_user, v_provider;
  IF v_new IS NULL THEN
    RAISE EXCEPTION 'FEDERATED_SESSION_STALE' USING ERRCODE = '40001';
  END IF;
  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, entity_type, entity_id, metadata)
  VALUES ((SELECT u.id FROM aisha_auth.users u WHERE u.id = v_user), 'federace.relace_obnovena', 'federace.relace_obnovena', 'security', 'info',
          'federated_source_session', p_session_id::text,
          jsonb_build_object('provider', v_provider, 'version', v_new, 'key_id', p_key_id, 'uzivatel', v_user));
  RETURN v_new;
END;
$$;
REVOKE ALL ON FUNCTION public.federated_source_session_rotate(uuid, integer, bytea, bytea, text, timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.federated_source_session_rotate(uuid, integer, bytea, bytea, text, timestamptz) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/federated_source_session_version.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: federated_source_session_version
-- Levná kontrola platnosti relace BEZ šifrového textu (ADR-004, bod 5; revize S2).
-- Broker smí držet dešifrovaný token v paměti procesu, ale při KAŽDÉM použití se
-- zeptá tady: odvolání i nahrazení relace tak platí okamžitě i napříč replikami.
-- Nečte tajemství → žádný zápis auditu (čtecí cesta).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.federated_source_session_version(p_user_id uuid, p_provider text)
RETURNS TABLE (source_session_id uuid, version integer)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $$
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'AISHA_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
    SELECT s.id, s.version
      FROM public.federated_source_sessions s
     WHERE s.user_id = p_user_id AND s.provider = p_provider
       AND s.revoked_at IS NULL AND s.expires_at > now();
END;
$$;
REVOKE ALL ON FUNCTION public.federated_source_session_version(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.federated_source_session_version(uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/finish_proactive_run.sql
-- -----------------------------------------------------------------------------

-- Function: finish_proactive_run
-- Executor akcí po události zapíše výsledek zabraného běhu. Jen z `running` —
-- běh, který mezitím vrátil requeue_stale_proactive_runs (a zabral jiný worker),
-- se pozdním dokončením nepřepíše; volající dostane false a ví, že výsledek zahodil.
--
-- Stavy: completed | failed | skipped. `skipped` = pravidlo se vědomě neprovedlo
-- (např. chybějící příjemce není porucha transportu) — odlišitelné od `failed`.
-- `p_error_message` se ořízne; do výsledku NIKDY nepatří tajemství ani tělo zprávy.

CREATE OR REPLACE FUNCTION public.finish_proactive_run(
  p_run_id        uuid,
  p_status        text,
  p_action_taken  text  DEFAULT NULL,
  p_action_result jsonb DEFAULT NULL,
  p_error_message text  DEFAULT NULL
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('completed', 'failed', 'skipped') THEN
    RAISE EXCEPTION 'finish_proactive_run: stav „%“ není completed | failed | skipped', p_status
      USING ERRCODE = '22023';
  END IF;

  UPDATE ai_proactive_runs r
     SET status        = p_status,
         completed_at  = now(),
         duration_ms   = CASE WHEN r.started_at IS NULL THEN NULL
                              ELSE (extract(epoch FROM now() - r.started_at) * 1000)::int END,
         action_taken  = left(p_action_taken, 200),
         action_result = p_action_result,
         error_message = left(p_error_message, 1000)
   WHERE r.id = p_run_id
     AND r.status = 'running';

  RETURN FOUND;
END;
$function$;

REVOKE ALL ON FUNCTION public.finish_proactive_run(uuid, text, text, jsonb, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.finish_proactive_run(uuid, text, text, jsonb, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_aggregate_personality_signals.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.fn_aggregate_personality_signals(
  p_user_id uuid,
  p_days integer DEFAULT 30
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_result jsonb;
BEGIN
  -- Auth: ensure caller is authenticated
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Authz: reject cross-user access (service_role / admin may target another user)
  IF p_user_id <> auth.uid()
     AND NOT public.is_service_role()
     AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(jsonb_agg(sub.obj ORDER BY sub.signal_count DESC), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      jsonb_build_object(
        'signal_type', ps.signal_type,
        'signal_count', count(*),
        'avg_weight', round(avg(ps.weight)::numeric, 3),
        'max_weight', round(max(ps.weight)::numeric, 3),
        'first_seen', min(ps.created_at),
        'last_seen', max(ps.created_at),
        'trend', CASE
          WHEN avg(CASE WHEN ps.created_at > now() - (p_days / 2 || ' days')::interval THEN ps.weight END)
             > avg(CASE WHEN ps.created_at <= now() - (p_days / 2 || ' days')::interval THEN ps.weight END)
          THEN 'increasing'
          WHEN avg(CASE WHEN ps.created_at > now() - (p_days / 2 || ' days')::interval THEN ps.weight END)
             < avg(CASE WHEN ps.created_at <= now() - (p_days / 2 || ' days')::interval THEN ps.weight END)
          THEN 'decreasing'
          ELSE 'stable'
        END
      ) AS obj,
      count(*) AS signal_count
    FROM personality_signals ps
    WHERE ps.user_id = p_user_id
      AND ps.created_at > now() - (p_days || ' days')::interval
    GROUP BY ps.signal_type
    HAVING count(*) >= 3  -- minimum signal threshold for relevance
  ) sub;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_aggregate_personality_signals(uuid, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_aggregate_personality_signals(uuid, integer) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_capture_personality_signal.sql
-- -----------------------------------------------------------------------------

-- Function: fn_capture_personality_signal
-- Hippocampus: Capture a raw interaction signal for personality evolution.
-- Signals are aggregated periodically into experiential traits.

CREATE OR REPLACE FUNCTION public.fn_capture_personality_signal(
  p_user_id uuid,
  p_signal_type text,
  p_value jsonb DEFAULT '{}',
  p_weight real DEFAULT 0.5,
  p_conversation_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id uuid;
BEGIN
  -- Auth check: require authenticated user or service_role
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- IDOR guard: bind the write to the caller unless service/admin.
  IF p_user_id IS NULL THEN
    p_user_id := auth.uid();
  END IF;
  IF p_user_id <> auth.uid() AND NOT public.is_service_role() AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required';
  END IF;
  IF p_signal_type IS NULL OR p_signal_type = '' THEN
    RAISE EXCEPTION 'p_signal_type is required';
  END IF;

  INSERT INTO personality_signals (user_id, signal_type, value, weight, conversation_id)
  VALUES (p_user_id, p_signal_type, p_value, LEAST(1.0, GREATEST(0.0, p_weight)), p_conversation_id)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;

COMMENT ON FUNCTION fn_capture_personality_signal(uuid, text, jsonb, real, uuid) IS
  'Hippocampus: Capture a raw interaction signal for personality evolution. '
  'Signals are aggregated periodically into experiential traits.';

REVOKE ALL ON FUNCTION fn_capture_personality_signal(uuid, text, jsonb, real, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_capture_personality_signal(uuid, text, jsonb, real, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION fn_capture_personality_signal(uuid, text, jsonb, real, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_check_and_consume_llm_quota_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_check_and_consume_llm_quota_audited
-- Phase 12 WP 2.3 — LLM token rate limit per JWT.sub
--
-- Pre-LLM-call quota gate. Called from svc-ai-chat (and any other service
-- that issues LLM calls on behalf of an authenticated user) BEFORE actually
-- dispatching to the LLM provider. The RPC:
--
--   1. Lazy-creates the user's llm_quota row from llm_tier_defaults('free')
--      on first call
--   2. Resets daily counters if last_reset_at is from a previous day
--   3. Checks both token + cost budgets
--   4. If allowed: increments the counters atomically, returns ok
--   5. If denied: writes an audit_journal entry (security signal — repeated
--      denials = compromised account or runaway script), returns 429 envelope
--
-- IMPORTANT: This is called per LLM call (not per chat turn). The token + cost
-- estimates are PRE-call values; the caller may over-estimate slightly to be
-- safe. Future WP will reconcile post-call actuals via a separate
-- fn_reconcile_llm_consumption RPC (not in this PR).
--
-- Security: SECURITY DEFINER, GRANT EXECUTE TO authenticated + service_role. The function
-- gates on the END-USER identified by p_user_id rather than on the calling service's own
-- token — that is the point of the RPC, and why `authenticated` keeps the grant. What
-- changed on 2026-07-15 is that a non-service caller may now only assert THEMSELVES as
-- p_user_id (see the guard in the body).
--
-- Audit: INSERT INTO audit_journal on DENIAL only. Metadata: tier, reason,
-- requested + consumed counters, limits. NO PII (no user email, no prompt).
-- ============================================================================

-- The third parameter was renamed p_cost_usd → p_cost when hardcoded currency
-- literals were removed from the schema. The SIGNATURE is unchanged
-- (uuid, int, numeric), so CREATE OR REPLACE matches the existing function and
-- then fails — Postgres cannot rename an input parameter in place:
--
--   ERROR: cannot change name of input parameter "p_cost_usd"
--   HINT:  Use DROP FUNCTION fn_check_and_consume_llm_quota_audited(...) first.
--
-- heals.sql runs on EVERY migrate, so this aborts the whole run (exit 1) on any
-- database created before the rename. A from-baseline database has no prior
-- function and never hits it — which is exactly why it stayed invisible: the
-- fresh-DB path is green and only UPGRADING installs break.
--
-- Same DROP-first convention as get_study_detail.sql / import_story_bundle.sql.
-- Dropping clears the privileges, which the REVOKE/GRANT/COMMENT block at the
-- end of this file re-applies on every run.
DROP FUNCTION IF EXISTS public.fn_check_and_consume_llm_quota_audited(uuid, int, numeric);

CREATE OR REPLACE FUNCTION public.fn_check_and_consume_llm_quota_audited(
  p_user_id  uuid,
  p_tokens   int,
  p_cost numeric
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_quota   public.llm_quota%ROWTYPE;
  v_default public.llm_tier_defaults%ROWTYPE;
  v_allowed boolean;
  v_reason  text;
BEGIN
  -- AUTHORIZATION FIRST. The old guard here had two defects (2026-07-15 IDOR audit,
  -- docs/security/IDOR_P_USER_ID_AUDIT_2026-07-15.md):
  --
  --  (a) It asked only "is SOMEONE authenticated?", never "is p_user_id actually them?".
  --      Combined with the `authenticated` GRANT, any logged-in user could bill their own
  --      LLM spend to a victim's daily quota — raising their effective limit while denying
  --      the victim service, and poisoning the victim's audit trail with the denials.
  --  (b) It read the role GUC directly. NOT a fail-open — an earlier version of the audit claimed
  --      `current_setting('role', true) != 'service_role'` folds to NULL, and that is FALSE:
  --      `role` is a BUILT-IN GUC and returns 'none', never NULL, so the old guard fired correctly.
  --      (Only DOTTED custom GUCs like request.jwt.claims fold to NULL; PostgreSQL rejects undotted
  --      custom GUCs outright.) is_service_role() is used here because it is the canonical reader —
  --      one place that knows the legacy-GUC/JSON-claims compatibility and the SET ROLE case — not
  --      because the old expression was unsafe.
  --
  -- The p_user_id pin below IS the fix. The `authenticated` grant stays (WP 2.3 gates an end user
  -- on their own quota, per JWT.sub) — a grant is not a defect, a grant without an ownership check is.
  IF NOT public.is_service_role()
     AND NOT public.is_admin_or_staff()
     AND (auth.uid() IS NULL OR p_user_id IS DISTINCT FROM auth.uid())
  THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  -- Validate inputs
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required' USING ERRCODE = '22023';
  END IF;
  IF p_tokens IS NULL OR p_tokens < 0 THEN
    RAISE EXCEPTION 'p_tokens must be >= 0' USING ERRCODE = '22023';
  END IF;
  IF p_cost IS NULL OR p_cost < 0 THEN
    RAISE EXCEPTION 'p_cost must be >= 0' USING ERRCODE = '22023';
  END IF;

  -- Lock the row (or upsert from 'free' tier defaults)
  SELECT * INTO v_quota
  FROM public.llm_quota
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    -- Lazy create from free tier defaults
    SELECT * INTO v_default
    FROM public.llm_tier_defaults
    WHERE tier = 'free';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'llm_tier_defaults seed missing — free tier not configured'
        USING ERRCODE = '42704';
    END IF;

    INSERT INTO public.llm_quota (
      user_id, tier, daily_token_limit, daily_cost_limit
    ) VALUES (
      p_user_id, 'free', v_default.daily_token_limit, v_default.daily_cost_limit
    )
    RETURNING * INTO v_quota;
  END IF;

  -- Reset if new day (UTC)
  IF v_quota.last_reset_at < date_trunc('day', now()) THEN
    UPDATE public.llm_quota SET
      consumed_tokens_today = 0,
      consumed_cost_today   = 0,
      last_reset_at         = date_trunc('day', now()),
      updated_at            = now()
    WHERE user_id = p_user_id
    RETURNING * INTO v_quota;
  END IF;

  -- Check limits
  IF v_quota.consumed_tokens_today + p_tokens > v_quota.daily_token_limit THEN
    v_allowed := false;
    v_reason  := 'token_limit_exceeded';
  ELSIF v_quota.consumed_cost_today + p_cost > v_quota.daily_cost_limit THEN
    v_allowed := false;
    v_reason  := 'cost_limit_exceeded';
  ELSE
    v_allowed := true;
    v_reason  := 'ok';

    -- Consume atomically (already locked above)
    UPDATE public.llm_quota SET
      consumed_tokens_today = consumed_tokens_today + p_tokens,
      consumed_cost_today   = consumed_cost_today + p_cost,
      updated_at            = now()
    WHERE user_id = p_user_id
    RETURNING * INTO v_quota;
  END IF;

  -- AUDIT on denial only — security signal. No PII (only IDs + numeric stats).
  IF NOT v_allowed THEN
    INSERT INTO public.audit_journal (user_id, action, metadata)
    VALUES (
      p_user_id,
      'llm.quota.denied',
      jsonb_build_object(
        'reason',                v_reason,
        'tier',                  v_quota.tier,
        'requested_tokens',      p_tokens,
        'requested_cost',    p_cost,
        'consumed_tokens_today', v_quota.consumed_tokens_today,
        'consumed_cost_today',   v_quota.consumed_cost_today,
        'daily_token_limit',     v_quota.daily_token_limit,
        'daily_cost_limit',  v_quota.daily_cost_limit
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'allowed',             v_allowed,
    'reason',              v_reason,
    'remaining_tokens',    GREATEST(0, v_quota.daily_token_limit - v_quota.consumed_tokens_today),
    'remaining_cost',  GREATEST(0, v_quota.daily_cost_limit - v_quota.consumed_cost_today),
    'tier',                v_quota.tier,
    'reset_at',            v_quota.last_reset_at + interval '1 day'
  );
END;
$$;

-- The `authenticated` grant is deliberate and part of the WP 2.3 contract (an end user gates
-- their OWN quota per JWT.sub — src/tests/gates/wp-2-3-llm-quota.gate.test.ts asserts it). It was
-- never the defect: the defect was granting it with no check that p_user_id was the caller, which
-- let one user bill their spend to another's ledger. The guard in the body now enforces that, so
-- the grant is safe — an authenticated caller can only ever consume their own quota.
REVOKE ALL ON FUNCTION public.fn_check_and_consume_llm_quota_audited(uuid, int, numeric) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_check_and_consume_llm_quota_audited(uuid, int, numeric) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_check_and_consume_llm_quota_audited(uuid, int, numeric) TO service_role;

COMMENT ON FUNCTION public.fn_check_and_consume_llm_quota_audited(uuid, int, numeric) IS
  'Phase 12 WP 2.3 — pre-LLM-call quota gate. Lazy-creates row from free tier, resets daily, atomically consumes, audits denial only. Returns jsonb {allowed, reason, remaining_tokens, remaining_cost, tier, reset_at}.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_create_improvement_proposal.sql
-- -----------------------------------------------------------------------------

-- Function: fn_create_improvement_proposal
-- Creates an improvement proposal for an AISHA agent.
-- Includes anomaly_key dedup, rate limiting, automatic risk evaluation,
-- and auto-approve for low-risk proposals on fully autonomous agents.
-- Source: migration 20260418130000_fix_self_improvement_foundation.sql

CREATE OR REPLACE FUNCTION public.fn_create_improvement_proposal(
  p_agent_slug text,
  p_category text DEFAULT 'general',
  p_description text DEFAULT '',
  p_metadata jsonb DEFAULT '{}',
  p_title text DEFAULT ''
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_anomaly_key text;
  v_agent record;
  v_existing_id uuid;
  v_proposal_id uuid;
  v_recent_count int;
  v_risk text;
  v_run_id uuid;
BEGIN
  -- Stráž (2026-09-28, SELF_IMPROVEMENT_LOOP.md K-15): SECURITY DEFINER s grantem
  -- `authenticated` bez vlastní stráže = každý přihlášený zakládal návrhy zlepšení;
  -- u plně autonomního agenta s nízkým rizikem rovnou 'auto_approved' — vstup do
  -- smyčky sebezměny pro kohokoli. Volají ji jen služba (n8n, svc-agent-runner,
  -- fn_hermes_learning_loop, fn_record_proposal_outcome) a správcovské UI.
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  -- Validate agent exists in catalog
  SELECT slug, default_model, autonomy_level, safety_level
    INTO v_agent
    FROM agent_catalog
   WHERE slug = p_agent_slug;

  IF v_agent IS NULL THEN
    RAISE EXCEPTION 'Unknown agent: %', p_agent_slug;
  END IF;

  -- Extract anomaly_key from metadata (if provided by n8n workflow)
  v_anomaly_key := p_metadata ->> 'anomaly_key';

  -- Dedup: check if active proposal with same anomaly_key exists (7-day window)
  IF v_anomaly_key IS NOT NULL THEN
    SELECT ip.id INTO v_existing_id
      FROM improvement_proposals ip
     WHERE ip.anomaly_key = v_anomaly_key
       AND ip.status IN ('draft','pending','pending_review','approved','auto_approved','in_progress')
       AND ip.created_at >= now() - interval '7 days'
     LIMIT 1;

    IF v_existing_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'error', 'duplicate',
        'existing_proposal_id', v_existing_id,
        'message', format('Active proposal %s already exists for anomaly_key %s', v_existing_id, v_anomaly_key)
      );
    END IF;
  END IF;

  -- Rate limit: max 3 proposals per hour per agent
  SELECT count(*) INTO v_recent_count
    FROM improvement_proposals ip
   WHERE ip.agent_slug = p_agent_slug
     AND ip.created_at > now() - interval '1 hour';

  IF v_recent_count >= 3 THEN
    RETURN jsonb_build_object(
      'error', 'rate_limit',
      'message', format('Agent %s exceeded 3 proposals/hour', p_agent_slug)
    );
  END IF;

  -- Evaluate risk
  v_risk := fn_evaluate_proposal_risk(p_agent_slug, p_category, p_metadata);

  -- Create tracking ai_run
  v_run_id := gen_random_uuid();
  -- §16: platform/system run → platform sentinel story (ai_runs.story_id NOT NULL).
  INSERT INTO ai_runs (id, story_id, kind, metadata, route_plan, started_at, status)
  VALUES (
    v_run_id,
    public.ensure_stack_default_story(),
    'proactive',
    jsonb_build_object('model', v_agent.default_model, 'type', 'improvement_proposal'),
    jsonb_build_array(p_agent_slug),
    now(),
    'running'
  );

  -- Store current agent state for rollback capability
  v_proposal_id := gen_random_uuid();
  INSERT INTO improvement_proposals (
    id, agent_slug, anomaly_key, category, created_at,
    current_value, description, metadata,
    risk_level, run_id, status, title, updated_at
  ) VALUES (
    v_proposal_id, p_agent_slug, v_anomaly_key, p_category, now(),
    jsonb_build_object(
      'default_model', v_agent.default_model
    ),
    p_description, p_metadata,
    v_risk, v_run_id,
    CASE
      WHEN v_risk = 'low' AND v_agent.autonomy_level = 'full' THEN 'auto_approved'
      ELSE 'pending'
    END,
    p_title, now()
  );

  -- Log trace event
  INSERT INTO ai_trace_events (
    agent_slug, event_type, operation, request_summary,
    response_summary, run_id, status
  ) VALUES (
    p_agent_slug, 'improvement_proposal', 'create_proposal',
    jsonb_build_object('anomaly_key', v_anomaly_key, 'category', p_category, 'title', p_title),
    jsonb_build_object('proposal_id', v_proposal_id, 'risk', v_risk),
    v_run_id, 'ok'
  );

  -- Finish run
  UPDATE ai_runs SET finished_at = now(), status = 'succeeded' WHERE id = v_run_id;

  RETURN jsonb_build_object(
    'agent', p_agent_slug,
    'anomaly_key', v_anomaly_key,
    'proposal_id', v_proposal_id,
    'risk_level', v_risk,
    'run_id', v_run_id,
    'status', CASE
      WHEN v_risk = 'low' AND v_agent.autonomy_level = 'full' THEN 'auto_approved'
      ELSE 'pending'
    END
  );
END;
$$;

COMMENT ON FUNCTION fn_create_improvement_proposal(text, text, text, jsonb, text) IS
  'Create an improvement proposal for an AISHA agent. Includes anomaly_key dedup, '
  'rate limiting (3/hour/agent), automatic risk evaluation, and auto-approve for '
  'low-risk proposals on fully autonomous agents.';

REVOKE ALL ON FUNCTION fn_create_improvement_proposal(text, text, text, jsonb, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION fn_create_improvement_proposal(text, text, text, jsonb, text) TO authenticated;
GRANT EXECUTE ON FUNCTION fn_create_improvement_proposal(text, text, text, jsonb, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_get_agent_performance_snapshot.sql
-- -----------------------------------------------------------------------------

-- Function: fn_get_agent_performance_snapshot
-- Snímek výkonu agenta AISHY podle slugu: kvalita z hodnocení (eval) a provoz z trace
-- (chybovost, latence, náklad) za časové okno.
--
-- Oprava 2026-09-28 (SELF_IMPROVEMENT_LOOP.md §3, K-01) — naměřeno na main 9087ef3df:
--   1. Kvalita se spojovala `JOIN ai_runs r ON r.id = er.run_id`, ale `ai_eval_runs`
--      sloupec `run_id` NEMÁ → každé volání padlo („column er.run_id does not exist").
--      WF_IMPROVEMENT_EVAL i WF_MODEL_ADVISORY tak nikdy nedostaly snímek.
--      Agent se k hodnocení váže přes existující vazbu: ai_eval_results.golden_example_id
--      → ai_golden_examples.agent_slug (jediný nosič „tahle odpověď patří agentovi X").
--   2. Neměřená kvalita/chybovost se vracela jako 0 (COALESCE). WF_IMPROVEMENT_EVAL pak
--      četl „kvalita po změně = 0" jako regresi a navrhl rollback dobré změny. Teď:
--      null = neměřeno, nikdy nula (ONE_WORLD_MODEL Z3); `eval_measured` to říká výslovně.
--   3. `total_events` čte WF_MODEL_ADVISORY na nejvyšší úrovni, funkce ho vracela jen
--      zanořený v `trace_metrics` → poradce viděl vždy 0 < 50 a nikdy nic nenavrhl.
--      Klíč je nově i nahoře (vnořený tvar zůstává kvůli kompatibilitě).
--   4. SECURITY DEFINER s grantem `authenticated` bez vlastní autorizace = orákulum
--      výkonu libovolného agenta pro každého přihlášeného. Volají ho jen n8n (služba)
--      a správa → stráž service_role / admin_or_staff.
-- Klíč nákladu `cost_json->>'usd'` zůstává — kanonizace tvaru je samostatný krok (K-07).

CREATE OR REPLACE FUNCTION public.fn_get_agent_performance_snapshot(
  p_agent_slug text,
  p_hours_window integer DEFAULT 24
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_cutoff        timestamptz;
  v_eval_metrics  jsonb;
  v_trace_metrics jsonb;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM agent_catalog WHERE slug = p_agent_slug) THEN
    RETURN jsonb_build_object('error', 'Agent not found: ' || p_agent_slug);
  END IF;

  IF p_hours_window IS NULL OR p_hours_window <= 0 THEN
    RAISE EXCEPTION 'p_hours_window must be a positive number of hours' USING ERRCODE = '22023';
  END IF;

  v_cutoff := now() - make_interval(hours => p_hours_window);

  -- Kvalita: výsledky dokončených hodnocení, jejichž zlatý příklad patří agentovi.
  SELECT jsonb_build_object(
    'avg_coherence',    round(avg(res.coherence_score), 4),
    'avg_groundedness', round(avg(res.groundedness_score), 4),
    'avg_overall',      round(avg(res.overall_score), 4),
    'avg_relevance',    round(avg(res.relevance_score), 4),
    'avg_safety',       round(avg(res.safety_score), 4),
    'eval_count',       count(DISTINCT er.id),
    'result_count',     count(*)
  )
  INTO v_eval_metrics
  FROM ai_eval_results res
  JOIN ai_eval_runs er       ON er.id = res.eval_run_id
  JOIN ai_golden_examples ge ON ge.id = res.golden_example_id
  WHERE ge.agent_slug = p_agent_slug
    AND er.status = 'completed'
    AND er.completed_at >= v_cutoff;

  -- Provoz
  SELECT jsonb_build_object(
    'avg_duration_ms', round(avg(te.duration_ms), 0),
    'error_count',     count(*) FILTER (WHERE te.status = 'error'),
    'error_rate',      CASE
                         WHEN count(*) > 0
                           THEN round(count(*) FILTER (WHERE te.status = 'error')::numeric / count(*)::numeric, 4)
                         ELSE NULL
                       END,
    'total_cost',      round(sum((te.cost_json->>'usd')::numeric), 4),
    'total_events',    count(*)
  )
  INTO v_trace_metrics
  FROM ai_trace_events te
  WHERE te.agent_slug = p_agent_slug
    AND te.created_at >= v_cutoff;

  RETURN jsonb_build_object(
    'agent_slug',     p_agent_slug,
    'avg_overall',    (v_eval_metrics->>'avg_overall')::numeric,            -- null = neměřeno
    'eval_measured',  COALESCE((v_eval_metrics->>'result_count')::int, 0) > 0,
    'error_rate',     (v_trace_metrics->>'error_rate')::numeric,             -- null = žádná událost
    'total_events',   COALESCE((v_trace_metrics->>'total_events')::int, 0),
    'eval_metrics',   COALESCE(v_eval_metrics, '{}'::jsonb),
    'measured_at',    now(),
    'trace_metrics',  COALESCE(v_trace_metrics, '{}'::jsonb),
    'window_hours',   p_hours_window
  );
END;
$$;

COMMENT ON FUNCTION public.fn_get_agent_performance_snapshot(text, integer) IS
  'Snímek výkonu agenta: kvalita z hodnocení (přes ai_golden_examples.agent_slug) a provoz '
  'z ai_trace_events za okno. null = neměřeno (nikdy 0). Jen služba a správa.';

REVOKE ALL ON FUNCTION public.fn_get_agent_performance_snapshot(text, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fn_get_agent_performance_snapshot(text, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_get_agent_performance_snapshot(text, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_get_decision_outcomes.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_get_decision_outcomes  (L0 feedback-plane outcome read)
-- Purpose: one row per execution DECISION (ai_decisions) joined to its execution
--   TRACE (ai_trace_events by decision_id) and the RUN (ai_runs) — "what did
--   decision D actually produce: runtime/model/backend, cost, latency, status,
--   eval — for real". This is the substrate the feedback plane (L1 rollup,
--   champion/challenger, proof harness) reads.
-- SINGLE-SoT: the outcome is DERIVED over the one decision journal (ai_decisions);
--   there is NO separate routing-outcomes table (guarded by no-second-routing-sot.gate).
-- Security: SECURITY DEFINER, STABLE. service_role (trusted backend) and admin/staff
--   see all; a user JWT must be a story_participants member of the run's story (or
--   the stack-default story). Platform/system runs (story_id IS NULL) are
--   service_role/admin-only. Mirrors the story_timeline auth pattern.

CREATE OR REPLACE FUNCTION public.fn_get_decision_outcomes(
  p_run_id uuid
)
RETURNS TABLE (
  decision_id        uuid,
  run_id             uuid,
  story_id           uuid,
  clow_purpose       text,
  runtime            text,
  model_id           text,
  backend_kind       text,
  strategy           text,
  admission_verdict  text,
  risk_level         text,
  resolution_source  text,
  estimated_cost numeric,
  exec_status        text,
  duration_ms        int,
  exec_cost      numeric,
  run_status         text,
  run_cost       numeric,
  eval_score         numeric,
  created_at         timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_user_id    uuid    := auth.uid();
  -- Canonical boolean-NOT-NULL service check. The prior inline idiom folded to
  -- SQL NULL when the role claim was absent, and NULL propagated through the
  -- negative deny-guards below (IF NULL never RAISEs) → fail-OPEN. is_service_role()
  -- COALESCEs to false, so both guards are total and fail CLOSED. Same auth
  -- contract (service bypass preserved); only the NULL edge now denies.
  v_is_service boolean := public.is_service_role();
  v_is_admin   boolean := false;
  v_story_id   uuid;
BEGIN
  IF v_user_id IS NULL AND NOT v_is_service THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT ar.story_id INTO v_story_id FROM public.ai_runs ar WHERE ar.id = p_run_id;

  v_is_admin := public.is_admin_or_staff(v_user_id);

  -- Authorization: trusted backend (service_role) OR admin/staff OR a participant
  -- of the run's story OR the stack-default story. A run with no story (platform/
  -- system) is service_role/admin-only.
  IF NOT v_is_service
     AND NOT v_is_admin
     AND NOT (
       v_story_id IS NOT NULL
       AND EXISTS (
         SELECT 1 FROM public.partner_stories ps
         WHERE ps.id = v_story_id
           AND (
             ps.is_stack_default = true
             OR EXISTS (
               SELECT 1 FROM public.story_participants sp
               WHERE sp.story_id = ps.id AND sp.user_id = v_user_id
             )
           )
       )
     )
  THEN
    RAISE EXCEPTION 'Access denied: story participant or admin/staff required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    d.id                                                    AS decision_id,
    d.run_id,
    d.story_id,
    d.clow_purpose,
    d.runtime,
    d.model_id,
    d.backend_kind,
    d.strategy,
    d.admission_verdict,
    d.risk_level,
    d.resolution_source,
    d.estimated_cost,
    t.status                                                AS exec_status,
    t.duration_ms,
    NULLIF(t.cost_json ->> 'total', '')::numeric        AS exec_cost,
    r.status                                                AS run_status,
    NULLIF(r.cost_total_json ->> 'total', '')::numeric  AS run_cost,
    r.faithfulness_score_estimate                           AS eval_score,
    d.created_at
  FROM public.ai_decisions d
  LEFT JOIN public.ai_trace_events t
    ON t.decision_id = d.id
   AND t.event_type IN ('llm_call', 'tool_call')
  LEFT JOIN public.ai_runs r ON r.id = d.run_id
  WHERE d.run_id = p_run_id
  ORDER BY d.created_at ASC;
END;
$$;

COMMENT ON FUNCTION public.fn_get_decision_outcomes(uuid) IS
  'L0 feedback-plane outcome read: ai_decisions join ai_trace_events (by decision_id) join ai_runs for one run. Derived over the single decision journal (no separate routing-outcomes table). SECURITY DEFINER + STABLE; service_role/admin or run-story participant.';

REVOKE ALL ON FUNCTION public.fn_get_decision_outcomes(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_get_decision_outcomes(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_get_decision_outcomes(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_get_platform_warmup_state.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_get_platform_warmup_state
-- Step:  Step W1 (Platform warmup wizard — admin onboarding into stack-default)
-- Used by: src/hooks/usePlatformWarmupState.ts → AdminWarmupWizard.tsx
-- Migration: aisha/db/migrations/20260520080000_platform_warmup_state.sql
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_get_platform_warmup_state()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_is_service       boolean;
  v_is_admin         boolean;
  v_default_story_id uuid;
  v_completed_steps  text[];
  v_last_step        text;
  v_last_step_at     timestamptz;
  v_kb_count         int;
  v_needs_warmup     boolean;
BEGIN
  v_is_service := public.is_service_role();
  v_is_admin := public.is_admin_or_staff(auth.uid());

  IF NOT v_is_service AND NOT v_is_admin THEN
    RAISE EXCEPTION 'Unauthorized: admin/staff or service_role required'
      USING ERRCODE = '42501';
  END IF;

  SELECT id INTO v_default_story_id
    FROM public.partner_stories
   WHERE is_stack_default = true
   LIMIT 1;

  SELECT
    COALESCE(array_agg(DISTINCT (aj.metadata->>'step') ORDER BY (aj.metadata->>'step')),
             ARRAY[]::text[]),
    (SELECT aj2.metadata->>'step'
       FROM public.audit_journal aj2
      WHERE aj2.action = 'warmup.step_completed'
      ORDER BY aj2.created_at DESC
      LIMIT 1),
    (SELECT aj2.created_at
       FROM public.audit_journal aj2
      WHERE aj2.action = 'warmup.step_completed'
      ORDER BY aj2.created_at DESC
      LIMIT 1)
  INTO v_completed_steps, v_last_step, v_last_step_at
  FROM public.audit_journal aj
  WHERE aj.action = 'warmup.step_completed'
    AND aj.metadata ? 'step';

  IF v_default_story_id IS NOT NULL THEN
    SELECT count(*) INTO v_kb_count
      FROM public.knowledge_items ki
     WHERE ki.story_id = v_default_story_id
       AND ki.status = 'active'
       AND (ki.quarantine_status IS NULL
            OR ki.quarantine_status NOT IN ('flagged', 'quarantined'));
  ELSE
    v_kb_count := 0;
  END IF;

  v_needs_warmup := NOT ('complete' = ANY(v_completed_steps));

  RETURN jsonb_build_object(
    'needs_warmup',             v_needs_warmup,
    'default_story_id',         v_default_story_id,
    'completed_steps',          to_jsonb(v_completed_steps),
    'last_step',                v_last_step,
    'last_step_at',             v_last_step_at,
    'default_story_kb_count',   v_kb_count
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_get_platform_warmup_state() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_get_platform_warmup_state() TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_get_platform_warmup_state() TO service_role;

COMMENT ON FUNCTION public.fn_get_platform_warmup_state() IS
  'Step W1: read-only warmup state derived from audit_journal warmup.step_completed rows + live stack-default KB count. Admin/staff or service_role only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_get_trace_anomalies_24h.sql
-- -----------------------------------------------------------------------------

-- Function: fn_get_trace_anomalies_24h

CREATE OR REPLACE FUNCTION public.fn_get_trace_anomalies_24h(p_min_occurrences integer DEFAULT 3, p_max_results integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  -- Only service_role or admin can call this
  IF NOT (
    public.is_service_role()
    OR is_admin_or_staff()
  ) THEN
    RAISE EXCEPTION 'Unauthorized: requires service_role or admin';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      a.event_type,
      a.agent_slug,
      a.operation,
      a.status,
      a.occurrences,
      a.first_seen,
      a.last_seen,
      a.request_summary,
      a.anomaly_key
    FROM (
      -- Source 1: ai_trace_events (existing). event_type is cast to text so the
      -- UNION ALL with integration_events (whose event_type column is text — a
      -- different domain: 'pull_request.opened', 'push', …) is type-compatible.
      -- Without the cast the function raised "UNION types ai_event_type and text
      -- cannot be matched" at plan time and never ran. A unified text label is the
      -- correct representation for an anomaly report spanning both event domains
      -- (the anomaly_key concat below already treats event_type as text). Separate
      -- defect from the 'system' enum literal fixed below; found by direct-call verify.
      SELECT
        event_type::text AS event_type,
        agent_slug,
        operation,
        status,
        count(*) AS occurrences,
        min(created_at) AS first_seen,
        max(created_at) AS last_seen,
        (array_agg(request_summary ORDER BY created_at DESC))[1] AS request_summary,
        agent_slug || '::' || event_type || '::' || operation || '::' || status AS anomaly_key
      FROM ai_trace_events
      WHERE created_at >= now() - interval '24 hours'
        AND status IN ('error', 'failed', 'timeout', 'rejected')
      GROUP BY event_type, agent_slug, operation, status
      HAVING count(*) >= p_min_occurrences

      UNION ALL

      -- Source 2: integration_events (GitHub App, webhooks, deployments)
      SELECT
        event_type,
        'integration' AS agent_slug,
        event_source AS operation,
        status,
        count(*) AS occurrences,
        min(created_at) AS first_seen,
        max(created_at) AS last_seen,
        (array_agg(error_json ORDER BY created_at DESC))[1] AS request_summary,
        'integration::' || event_source || '::' || event_type || '::' || status AS anomaly_key
      FROM integration_events
      WHERE created_at >= now() - interval '24 hours'
        AND status IN ('failed', 'exhausted')
      GROUP BY event_type, event_source, status
      HAVING count(*) >= p_min_occurrences
    ) a
    WHERE NOT EXISTS (
      SELECT 1 FROM improvement_proposals ip
      WHERE ip.anomaly_key = a.anomaly_key
        AND ip.status IN ('draft','pending','pending_review','approved','auto_approved','in_progress')
        AND ip.created_at >= now() - interval '7 days'
    )
    ORDER BY a.occurrences DESC
    LIMIT LEAST(p_max_results, 20)
  ) t;

  -- Log that we ran the analysis
  INSERT INTO ai_trace_events (
    run_id,
    event_type,
    agent_slug,
    operation,
    status,
    request_summary,
    created_at
  ) VALUES (
    gen_random_uuid(),
    -- 'dirigent_action' is a valid ai_event_type member (Dirigent self-scan,
    -- agent_slug='dirigent'). The prior 'system' was not a member, so this
    -- audit INSERT (event_type is ai_event_type NOT NULL) raised `invalid input
    -- value for enum ai_event_type` and aborted the nightly anomaly scan.
    'dirigent_action',
    'dirigent',
    'trace_anomaly_scan',
    'ok',
    jsonb_build_object(
      'anomalies_found', jsonb_array_length(v_result),
      'min_occurrences', p_min_occurrences,
      'window', '24h',
      'dedup_window', '7d'
    ),
    now()
  );

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION fn_get_trace_anomalies_24h(integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_get_trace_anomalies_24h(integer,integer) TO authenticated;
GRANT EXECUTE ON FUNCTION fn_get_trace_anomalies_24h(integer,integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_log_ai_trace_event.sql
-- -----------------------------------------------------------------------------

-- Function: fn_log_ai_trace_event
-- Log an AI trace event with optional cost data.
-- Source: migration 20260418130100_cost_intelligence_and_hippocampus.sql
-- Note: p_event_type defaults to 'dirigent_action' (a valid ai_event_type
--   member that pairs with the 'dirigent' p_agent_slug default). It is cast
--   p_event_type::ai_event_type at the INSERT below, so the default MUST be a
--   real enum member. The earlier 'system_event' default was NOT a member of
--   ai_event_type (it belongs to journal_action_type), so any caller omitting
--   p_event_type failed with `invalid input value for enum ai_event_type`.
--   Repaired in migration 20260602120000_fix_trace_event_enum_mismatch.sql.

CREATE OR REPLACE FUNCTION public.fn_log_ai_trace_event(
  p_agent_slug text DEFAULT 'dirigent'::text,
  p_cost_json jsonb DEFAULT NULL,
  p_duration_ms integer DEFAULT 0,
  p_event_type text DEFAULT 'dirigent_action'::text,
  p_operation text DEFAULT NULL::text,
  p_request_summary jsonb DEFAULT '{}'::jsonb,
  p_response_summary jsonb DEFAULT '{}'::jsonb,
  p_status text DEFAULT 'ok'::text
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id uuid;
  v_run_id uuid;
BEGIN
  -- Create a minimal ai_run for FK
  v_run_id := gen_random_uuid();
  -- §16: platform/system run → platform sentinel story (ai_runs.story_id NOT NULL).
  INSERT INTO ai_runs (id, story_id, cost_total_json, finished_at, kind, metadata, started_at, status)
  VALUES (
    v_run_id,
    public.ensure_stack_default_story(),
    COALESCE(p_cost_json, '{"usd": 0}'::jsonb),
    now(),
    'proactive',
    p_request_summary,
    now(),
    'succeeded'
  );

  INSERT INTO ai_trace_events (
    agent_slug,
    cost_json,
    created_at,
    duration_ms,
    event_type,
    operation,
    request_summary,
    response_summary,
    run_id,
    status
  ) VALUES (
    p_agent_slug,
    p_cost_json,
    now(),
    p_duration_ms,
    p_event_type::ai_event_type,
    p_operation,
    p_request_summary,
    p_response_summary,
    v_run_id,
    p_status
  )
  RETURNING id INTO v_event_id;

  RETURN jsonb_build_object(
    'event_id', v_event_id,
    'run_id', v_run_id,
    'status', 'logged'
  );
END;
$function$;

REVOKE ALL ON FUNCTION fn_log_ai_trace_event(text, jsonb, integer, text, text, jsonb, jsonb, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_log_ai_trace_event(text, jsonb, integer, text, text, jsonb, jsonb, text) TO authenticated;
GRANT EXECUTE ON FUNCTION fn_log_ai_trace_event(text, jsonb, integer, text, text, jsonb, jsonb, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_log_dev_signal.sql
-- -----------------------------------------------------------------------------

-- Function: fn_log_dev_signal
-- Purpose: Log development signals from VS Code extension (terminal failures, compliance violations).
--          Wraps fn_log_ai_trace_event with dev_signal event_type and structured payload.
-- Used by: aisha-dirigent VS Code extension (terminal-watcher, copilot-watcher)
-- Migration: 20260406120000_add_dev_signal_event_type.sql

CREATE OR REPLACE FUNCTION public.fn_log_dev_signal(
  p_signal_type text,
  p_severity text DEFAULT 'info'::text,
  p_payload jsonb DEFAULT '{}'::jsonb,
  p_agent_slug text DEFAULT 'dirigent'::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
  v_valid_types text[] := ARRAY[
    'compliance_violation',
    'terminal_failure',
    'terminal_success',
    'build_result',
    'test_result'
  ];
BEGIN
  -- Validate signal_type
  IF NOT (p_signal_type = ANY(v_valid_types)) THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'message', 'Invalid signal_type: ' || p_signal_type ||
                 '. Must be one of: ' || array_to_string(v_valid_types, ', ')
    );
  END IF;

  -- Validate severity
  IF p_severity NOT IN ('info', 'warning', 'error', 'critical') THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'message', 'Invalid severity: ' || p_severity
    );
  END IF;

  -- Delegate to existing fn_log_ai_trace_event (creates ai_run + ai_trace_event)
  v_result := fn_log_ai_trace_event(
    p_event_type := 'dev_signal',
    p_agent_slug := p_agent_slug,
    p_operation := p_signal_type,
    p_status := CASE
      WHEN p_severity IN ('error', 'critical') THEN 'error'
      WHEN p_severity = 'warning' THEN 'warning'
      ELSE 'ok'
    END,
    p_request_summary := jsonb_build_object(
      'signal_type', p_signal_type,
      'severity', p_severity,
      'payload', p_payload,
      'source', 'vscode_extension'
    )
  );

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION fn_log_dev_signal(text, text, jsonb, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_log_dev_signal(text, text, jsonb, text) TO authenticated;
GRANT EXECUTE ON FUNCTION fn_log_dev_signal(text, text, jsonb, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_log_kb_sync_event.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_log_kb_sync_event
-- Popis: Zaznamená výsledek jednoho KB→Ragnarok sync běhu (per change event).
--        Volá ji WF_KB_RAGNAROK_SYNC node "Log Sync Event" (ks-log-012) po
--        "AISHA Impact Evaluation". Funkce byla v workflow referencována, ale
--        nikde v repu nedefinována — každé volání tedy 404'lo (PostgREST
--        PGRST202) a bylo tiše spolknuto onError:"continueRegularOutput", takže
--        se sync event nikdy nezaznamenal.
-- Vzor:  fn_log_dev_signal — tenký doménový wrapper, který deleguje na
--        fn_log_ai_trace_event s event_type 'n8n_workflow' (validní člen
--        ai_event_type enumu, určený přímo pro n8n workflow eventy). Žádná nová
--        tabulka — využívá existující ai_trace_events telemetry spine.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (authenticated + service_role).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_log_kb_sync_event(
  p_source_table text    DEFAULT NULL,
  p_source_slug  text    DEFAULT NULL,
  p_action       text    DEFAULT 'UNKNOWN',
  p_ragnarok_ok  boolean DEFAULT NULL,
  p_severity     text    DEFAULT 'MEDIUM',
  p_needs_review boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  -- Auth: telemetry-write RPC. Callers are the n8n workflow (service_role) or an
  -- authenticated operator; reject anon/unauthenticated. SECURITY DEFINER means
  -- the body runs as owner, so the caller identity must be checked explicitly.
  IF auth.uid() IS NULL
     AND COALESCE(current_setting('request.jwt.claims', true)::jsonb->>'role', '') <> 'service_role' THEN
    RAISE EXCEPTION 'fn_log_kb_sync_event: authentication required' USING ERRCODE = '42501';
  END IF;
  -- Delegace na trace-event spine (vytvoří ai_run + ai_trace_event).
  -- Status odráží OPERAČNÍ výsledek syncu, ne severity KB změny (ta je dopad
  -- a ukládá se do request_summary):
  --   ragnarok upload selhal       -> 'error'
  --   prošel, ale vyžaduje review  -> 'warning'
  --   prošel, auto-approved        -> 'ok'
  -- Všechny parametry mají default, takže volání je odolné i vůči prázdnému
  -- argument setu (PostgREST overload resolution najde nullary variantu).
  v_result := public.fn_log_ai_trace_event(
    p_event_type      := 'n8n_workflow',
    p_agent_slug      := 'kb-ragnarok-sync',
    p_operation       := 'kb_sync:' || COALESCE(p_action, 'UNKNOWN'),
    p_status          := CASE
                           WHEN p_ragnarok_ok IS FALSE THEN 'error'
                           WHEN p_needs_review        THEN 'warning'
                           ELSE 'ok'
                         END,
    p_request_summary := jsonb_build_object(
      'source_table', p_source_table,
      'source_slug',  p_source_slug,
      'action',       p_action,
      'ragnarok_ok',  p_ragnarok_ok,
      'severity',     p_severity,
      'needs_review', p_needs_review,
      'workflow',     'WF_KB_RAGNAROK_SYNC'
    )
  );

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_log_kb_sync_event(text, text, text, boolean, text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_log_kb_sync_event(text, text, text, boolean, text, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_log_kb_sync_event(text, text, text, boolean, text, boolean) TO service_role;

COMMENT ON FUNCTION public.fn_log_kb_sync_event(text, text, text, boolean, text, boolean) IS
  'Log a KB->Ragnarok sync outcome. Thin wrapper over fn_log_ai_trace_event (event_type n8n_workflow). Called by WF_KB_RAGNAROK_SYNC node Log Sync Event.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_maybe_evolve_personality.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.fn_maybe_evolve_personality(
  p_user_id uuid,
  p_signal_type text,
  -- Tunable thresholds (sensible defaults)
  p_min_signals integer DEFAULT 8,
  p_min_span_days integer DEFAULT 3,
  p_max_traits_per_user integer DEFAULT 20,
  p_cooldown_days integer DEFAULT 7
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_signal_count integer;
  v_avg_weight numeric;
  v_max_weight numeric;
  v_first_seen timestamptz;
  v_last_seen timestamptz;
  v_span_days numeric;
  v_trend text;
  v_existing_trait_count integer;
  v_existing_trait_for_type uuid;
  v_last_evolution timestamptz;
  v_trait_content text;
  v_trait_importance integer;
  v_new_trait_id uuid;
BEGIN
  -- Auth: ensure caller is authenticated
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Default to the calling user when target is unspecified
  IF p_user_id IS NULL THEN
    p_user_id := auth.uid();
  END IF;

  -- Self/authority gate: only act on your own data unless service or admin/staff
  IF p_user_id IS DISTINCT FROM auth.uid()
     AND NOT public.is_service_role()
     AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;

  -- -----------------------------------------------------------------------
  -- 1. Aggregate signals for this user + type (last 60 days)
  -- -----------------------------------------------------------------------
  SELECT
    count(*),
    round(avg(ps.weight)::numeric, 3),
    round(max(ps.weight)::numeric, 3),
    min(ps.created_at),
    max(ps.created_at)
  INTO v_signal_count, v_avg_weight, v_max_weight, v_first_seen, v_last_seen
  FROM personality_signals ps
  WHERE ps.user_id = p_user_id
    AND ps.signal_type = p_signal_type
    AND ps.created_at > now() - interval '60 days';

  -- Not enough signals → skip
  IF v_signal_count < p_min_signals THEN
    RETURN jsonb_build_object(
      'evolved', false,
      'reason', 'insufficient_signals',
      'signal_count', v_signal_count,
      'threshold', p_min_signals
    );
  END IF;

  -- -----------------------------------------------------------------------
  -- 2. Check time span — signals must not be a single-session burst
  -- -----------------------------------------------------------------------
  v_span_days := EXTRACT(EPOCH FROM (v_last_seen - v_first_seen)) / 86400.0;

  IF v_span_days < p_min_span_days THEN
    RETURN jsonb_build_object(
      'evolved', false,
      'reason', 'insufficient_span',
      'span_days', round(v_span_days::numeric, 1),
      'min_span', p_min_span_days
    );
  END IF;

  -- -----------------------------------------------------------------------
  -- 3. Check evolution cooldown — don't re-evolve same type too soon
  -- -----------------------------------------------------------------------
  SELECT max(am.updated_at)
  INTO v_last_evolution
  FROM agent_memories am
  WHERE am.user_id = p_user_id
    AND am.memory_type = 'personality'
    AND am.agent_slug = 'hippocampus:' || p_signal_type;

  IF v_last_evolution IS NOT NULL
     AND v_last_evolution > now() - (p_cooldown_days || ' days')::interval THEN
    RETURN jsonb_build_object(
      'evolved', false,
      'reason', 'cooldown',
      'last_evolution', v_last_evolution,
      'cooldown_days', p_cooldown_days
    );
  END IF;

  -- -----------------------------------------------------------------------
  -- 4. Check max traits per user — prevent trait explosion
  -- -----------------------------------------------------------------------
  SELECT count(*)
  INTO v_existing_trait_count
  FROM agent_memories am
  WHERE am.user_id = p_user_id
    AND am.memory_type = 'personality';

  -- Check if trait for this signal_type already exists (update vs insert)
  SELECT am.id
  INTO v_existing_trait_for_type
  FROM agent_memories am
  WHERE am.user_id = p_user_id
    AND am.memory_type = 'personality'
    AND am.agent_slug = 'hippocampus:' || p_signal_type
  LIMIT 1;

  IF v_existing_trait_for_type IS NULL AND v_existing_trait_count >= p_max_traits_per_user THEN
    RETURN jsonb_build_object(
      'evolved', false,
      'reason', 'max_traits_reached',
      'current_count', v_existing_trait_count,
      'max', p_max_traits_per_user
    );
  END IF;

  -- -----------------------------------------------------------------------
  -- 5. Calculate trend (same logic as fn_aggregate)
  -- -----------------------------------------------------------------------
  SELECT CASE
    WHEN avg(CASE WHEN ps.created_at > now() - interval '30 days' THEN ps.weight END)
       > avg(CASE WHEN ps.created_at <= now() - interval '30 days' THEN ps.weight END)
    THEN 'increasing'
    WHEN avg(CASE WHEN ps.created_at > now() - interval '30 days' THEN ps.weight END)
       < avg(CASE WHEN ps.created_at <= now() - interval '30 days' THEN ps.weight END)
    THEN 'decreasing'
    ELSE 'stable'
  END
  INTO v_trend
  FROM personality_signals ps
  WHERE ps.user_id = p_user_id
    AND ps.signal_type = p_signal_type
    AND ps.created_at > now() - interval '60 days';

  -- -----------------------------------------------------------------------
  -- 6. Compose trait content — the crystallized experience
  --    This is a structured description the evolution LLM can understand.
  --    The actual human-readable trait will be enriched by Hippocampus
  --    on retrieval (buildPersonalityPrompt formats it).
  -- -----------------------------------------------------------------------
  v_trait_content := format(
    'User behavioral pattern: %s (observed %s times over %s days, '
    'avg intensity %s, trend: %s). Adapt AISHA''s expression accordingly — '
    'this reflects who this person is in interaction.',
    p_signal_type,
    v_signal_count,
    round(v_span_days::numeric, 0),
    v_avg_weight,
    v_trend
  );

  -- Importance: scale from signal density + weight (min 4, max 8)
  -- Base traits (DNA) always dominate via retrieval bonus
  v_trait_importance := LEAST(8, GREATEST(4,
    round((v_avg_weight * 5 + LEAST(v_signal_count, 30)::numeric / 30 * 3)::numeric)::integer
  ));

  -- -----------------------------------------------------------------------
  -- 7. Upsert: create new or update existing experiential trait
  -- -----------------------------------------------------------------------
  IF v_existing_trait_for_type IS NOT NULL THEN
    -- UPDATE existing trait — refine based on new signal data
    UPDATE agent_memories
    SET content = v_trait_content,
        importance = v_trait_importance,
        updated_at = now(),
        -- Clear embedding so it gets re-embedded with new content
        embedding = NULL
    WHERE id = v_existing_trait_for_type;

    v_new_trait_id := v_existing_trait_for_type;
  ELSE
    -- INSERT new experiential trait
    INSERT INTO agent_memories (
      agent_slug, user_id, memory_type, content, importance, source_run_id
    ) VALUES (
      'hippocampus:' || p_signal_type,
      p_user_id,
      'personality',
      v_trait_content,
      v_trait_importance,
      NULL
    )
    RETURNING id INTO v_new_trait_id;
  END IF;

  -- -----------------------------------------------------------------------
  -- 8. Prune old signals — keep last 30, discard older ones
  --    The experience has been consolidated; raw signals can decay.
  -- -----------------------------------------------------------------------
  DELETE FROM personality_signals
  WHERE user_id = p_user_id
    AND signal_type = p_signal_type
    AND id NOT IN (
      SELECT id FROM personality_signals
      WHERE user_id = p_user_id
        AND signal_type = p_signal_type
      ORDER BY created_at DESC
      LIMIT 30
    );

  RETURN jsonb_build_object(
    'evolved', true,
    'reason', CASE WHEN v_existing_trait_for_type IS NOT NULL
      THEN 'updated' ELSE 'created' END,
    'trait_id', v_new_trait_id,
    'signal_count', v_signal_count,
    'span_days', round(v_span_days::numeric, 1),
    'importance', v_trait_importance,
    'trend', v_trend
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_maybe_evolve_personality(uuid, text, integer, integer, integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_maybe_evolve_personality(uuid, text, integer, integer, integer, integer) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_record_proposal_outcome.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_record_proposal_outcome
-- Closes the self-improvement loop: measures whether an APPLIED improvement
-- proposal actually helped, by comparing the story's self-eval maturity score
-- before vs after the change.
--
-- Two-phase (auto-detected by presence of outcome.score_before), so a single
-- cron (WF_PROPOSAL_OUTCOME_REVIEW) can drive both:
--   Phase 1 (baseline): right after apply, snapshot score_before.
--   Phase 2 (outcome):  after p_window_hours, snapshot score_after + delta;
--                       on regression beyond threshold, PROPOSE a gated rollback.
--
-- ADVISORY-ONLY: never executes a rollback — only creates a 'rollback'-category
-- improvement_proposal via fn_create_improvement_proposal (which is itself gated:
-- risk eval + human approval). The loop proposes; humans/gates dispose.
--
-- @security: service_role (cron) or admin/staff.

CREATE OR REPLACE FUNCTION public.fn_record_proposal_outcome(
  p_proposal_id          uuid,
  p_regression_threshold numeric DEFAULT 5,
  p_window_hours         int     DEFAULT 24
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean := current_setting('role', true) = 'service_role';
  v_p          public.improvement_proposals;
  v_story_id   uuid;
  v_score_now  numeric;
  v_score_before numeric;
  v_delta      numeric;
  v_regressed  boolean;
  v_outcome    jsonb;
BEGIN
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_p FROM public.improvement_proposals WHERE id = p_proposal_id;
  IF v_p IS NULL THEN
    RAISE EXCEPTION 'proposal % not found', p_proposal_id;
  END IF;
  IF v_p.status <> 'applied' THEN
    RETURN jsonb_build_object('proposal_id', p_proposal_id, 'skipped', 'not_applied', 'status', v_p.status);
  END IF;

  -- Resolve story scope: run_id → ai_runs.story_id, else metadata.story_id.
  v_story_id := COALESCE(
    (SELECT ar.story_id FROM public.ai_runs ar WHERE ar.id = v_p.run_id),
    NULLIF(v_p.metadata->>'story_id', '')::uuid
  );
  IF v_story_id IS NULL THEN
    v_outcome := COALESCE(v_p.outcome, '{}'::jsonb) || jsonb_build_object('error', 'no_story_scope', 'measured_at', now());
    UPDATE public.improvement_proposals SET outcome = v_outcome, updated_at = now() WHERE id = p_proposal_id;
    RETURN v_outcome || jsonb_build_object('proposal_id', p_proposal_id, 'phase', 'no_scope');
  END IF;

  v_score_now := (public.get_story_aisha_maturity(v_story_id)->>'maturity_score')::numeric;

  -- Phase 1 — baseline.
  IF (v_p.outcome->>'score_before') IS NULL THEN
    v_outcome := COALESCE(v_p.outcome, '{}'::jsonb) || jsonb_build_object(
      'story_id', v_story_id, 'score_before', v_score_now, 'baseline_at', now());
    UPDATE public.improvement_proposals SET outcome = v_outcome, updated_at = now() WHERE id = p_proposal_id;
    RETURN v_outcome || jsonb_build_object('proposal_id', p_proposal_id, 'phase', 'baseline');
  END IF;

  -- Phase 2 — outcome (delta vs baseline).
  v_score_before := (v_p.outcome->>'score_before')::numeric;
  v_delta := v_score_now - v_score_before;
  v_regressed := v_delta < -abs(p_regression_threshold);
  v_outcome := v_p.outcome || jsonb_build_object(
    'score_after', v_score_now, 'score_delta', round(v_delta, 2),
    'regressed', v_regressed, 'window_hours', p_window_hours, 'measured_at', now());
  UPDATE public.improvement_proposals SET outcome = v_outcome, updated_at = now() WHERE id = p_proposal_id;

  -- On regression: PROPOSE a gated rollback (advisory-only — never executes here).
  IF v_regressed THEN
    PERFORM public.fn_create_improvement_proposal(
      COALESCE(v_p.agent_slug, 'dirigent'),
      'rollback',
      format('Applied proposal %s regressed story self-eval score by %s (%s → %s). Consider rollback (gated).',
             p_proposal_id, round(v_delta, 2), v_score_before, v_score_now),
      jsonb_build_object(
        'anomaly_key', 'rollback:' || p_proposal_id::text,
        'story_id', v_story_id,
        'regressed_proposal_id', p_proposal_id,
        'score_delta', round(v_delta, 2),
        'source', 'fn_record_proposal_outcome'),
      format('Rollback regressed proposal %s', left(p_proposal_id::text, 8))
    );
  END IF;

  RETURN v_outcome || jsonb_build_object('proposal_id', p_proposal_id, 'phase', 'outcome');
END;
$$;

REVOKE ALL ON FUNCTION public.fn_record_proposal_outcome(uuid, numeric, int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_record_proposal_outcome(uuid, numeric, int) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_record_proposal_outcome(uuid, numeric, int) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_search_agent_memories.sql
-- -----------------------------------------------------------------------------

-- fn_search_agent_memories: Vector-based semantic search over agent memories
-- Uses hybrid scoring: cosine similarity (60%) + importance weight (40%)
-- Called from ai-context-composer edge function for relevance-ranked memory retrieval.

CREATE OR REPLACE FUNCTION public.fn_search_agent_memories(
  p_query_embedding vector(1024),
  p_agent_slug text,
  p_user_id uuid DEFAULT NULL,
  p_limit integer DEFAULT 10,
  p_min_importance integer DEFAULT 3
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
  v_results jsonb;
  v_user_id uuid;
BEGIN
  -- Resolve the effective scope BEFORE reading. The previous guard asked only "is SOMEONE
  -- authenticated?" while p_user_id defaulted to NULL and NULL meant "match every user"
  -- (2026-07-15 IDOR audit, docs/security/IDOR_P_USER_ID_AUDIT_2026-07-15.md) — so any logged-in
  -- caller could semantically search every user's agent memories (PII) with one embedding.
  -- service_role (the MCP/agent runtimes) and admin/staff keep the cross-user wildcard; everyone
  -- else is pinned to themselves. Memories with am.user_id IS NULL are agent-global, not
  -- user-owned, and stay visible to all — that disjunct is intentional, not part of the defect.
  IF public.is_service_role() OR public.is_admin_or_staff() THEN
    v_user_id := p_user_id;
  ELSE
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
    END IF;
    IF p_user_id IS NOT NULL AND p_user_id <> auth.uid() THEN
      RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
    END IF;
    v_user_id := auth.uid();
  END IF;

  -- Validate inputs
  IF p_query_embedding IS NULL THEN
    RAISE EXCEPTION 'p_query_embedding is required';
  END IF;
  IF p_agent_slug IS NULL OR p_agent_slug = '' THEN
    RAISE EXCEPTION 'p_agent_slug is required';
  END IF;

  SELECT COALESCE(jsonb_agg(sub.obj ORDER BY sub.hybrid_score DESC), '[]'::jsonb)
  INTO v_results
  FROM (
    SELECT
      jsonb_build_object(
        'memory_id', am.id,
        'type', am.memory_type,
        'content', am.content,
        'importance', am.importance,
        'cosine_similarity', round((1 - (am.embedding <=> p_query_embedding))::numeric, 4),
        'hybrid_score', round((
          (1 - (am.embedding <=> p_query_embedding)) * 0.6
          + (am.importance / 10.0) * 0.4
        )::numeric, 4),
        'created_at', am.created_at
      ) AS obj,
      (1 - (am.embedding <=> p_query_embedding)) * 0.6
        + (am.importance / 10.0) * 0.4
      AS hybrid_score
    FROM agent_memories am
    WHERE am.agent_slug = p_agent_slug
      AND am.embedding IS NOT NULL
      AND am.importance >= p_min_importance
      AND (am.expires_at IS NULL OR am.expires_at > now())
      AND (v_user_id IS NULL OR am.user_id IS NULL OR am.user_id = v_user_id)
    LIMIT p_limit
  ) sub;

  RETURN jsonb_build_object(
    'memories', v_results,
    'count', jsonb_array_length(v_results),
    'search_method', 'vector_hybrid'
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_search_agent_memories(vector(1024), text, uuid, integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_search_agent_memories(vector(1024), text, uuid, integer, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_search_agent_memories(vector(1024), text, uuid, integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_search_personality_context.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.fn_search_personality_context(
  p_user_id uuid DEFAULT NULL,
  p_query_embedding vector(1024) DEFAULT NULL,
  p_limit integer DEFAULT 12
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
  v_base_traits jsonb;
  v_experiential jsonb;
  v_merged jsonb;
  v_effective_user_id uuid;
BEGIN
  -- Auth: ensure caller is authenticated
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- IDOR guard: resolve effective user id before any user-scoped read
  IF public.is_service_role() OR public.is_admin_or_staff() THEN
    v_effective_user_id := p_user_id;
  ELSE
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Not authenticated';
    END IF;
    IF p_user_id IS NOT NULL AND p_user_id <> auth.uid() THEN
      RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
    END IF;
    v_effective_user_id := auth.uid();
  END IF;

  -- -----------------------------------------------------------------------
  -- A) Base traits (DNA) — always included, from knowledge_items
  --    If embedding provided: score by cosine similarity + bonus 0.2
  --    If no embedding: return all base traits with score 1.0 (DNA is core)
  -- -----------------------------------------------------------------------
  IF p_query_embedding IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(sub.obj ORDER BY sub.score DESC), '[]'::jsonb)
    INTO v_base_traits
    FROM (
      SELECT
        jsonb_build_object(
          'trait_id', ki.id,
          'source', 'base',
          'slug', ki.source_slug,
          'title', ki.title,
          'content', ki.body_markdown,
          'ai_instructions', ki.ai_instructions,
          'tags', ki.ai_context_tags,
          'score', round((
            LEAST(1.0, (1 - (ke.embedding <=> p_query_embedding)) + 0.2)
          )::numeric, 4)
        ) AS obj,
        LEAST(1.0, (1 - (ke.embedding <=> p_query_embedding)) + 0.2) AS score
      FROM knowledge_items ki
      JOIN knowledge_chunks kc ON kc.knowledge_item_id = ki.id
      JOIN knowledge_embeddings ke ON ke.chunk_id = kc.id
      WHERE ki.item_type = 'personality_trait'
        AND ki.status = 'active'
        AND ke.embedding IS NOT NULL
      ORDER BY score DESC
      LIMIT p_limit
    ) sub;
  ELSE
    -- No embedding: return all base traits with max score
    SELECT COALESCE(jsonb_agg(sub.obj ORDER BY ki_title), '[]'::jsonb)
    INTO v_base_traits
    FROM (
      SELECT
        jsonb_build_object(
          'trait_id', ki.id,
          'source', 'base',
          'slug', ki.source_slug,
          'title', ki.title,
          'content', ki.body_markdown,
          'ai_instructions', ki.ai_instructions,
          'tags', ki.ai_context_tags,
          'score', 1.0
        ) AS obj,
        ki.title AS ki_title
      FROM knowledge_items ki
      WHERE ki.item_type = 'personality_trait'
        AND ki.status = 'active'
    ) sub;
  END IF;

  -- -----------------------------------------------------------------------
  -- B) Experiential traits — user-scoped from agent_memories
  --    Only if user_id provided and embedding available
  -- -----------------------------------------------------------------------
  IF p_user_id IS NOT NULL AND p_query_embedding IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(sub.obj ORDER BY sub.score DESC), '[]'::jsonb)
    INTO v_experiential
    FROM (
      SELECT
        jsonb_build_object(
          'trait_id', am.id,
          'source', 'experiential',
          'slug', NULL,
          'title', 'Experiential: ' || am.agent_slug,
          'content', am.content,
          'ai_instructions', NULL,
          'tags', ARRAY['personality', 'experiential'],
          'score', round((
            (1 - (am.embedding <=> p_query_embedding)) * 0.6
            + (am.importance / 10.0) * 0.4
          )::numeric, 4)
        ) AS obj,
        (1 - (am.embedding <=> p_query_embedding)) * 0.6
          + (am.importance / 10.0) * 0.4
        AS score
      FROM agent_memories am
      WHERE am.memory_type = 'personality'
        AND am.user_id = v_effective_user_id
        AND am.embedding IS NOT NULL
        AND am.importance >= 3
        AND (am.expires_at IS NULL OR am.expires_at > now())
      ORDER BY score DESC
      LIMIT GREATEST(1, p_limit / 3)  -- experiential gets ~1/3 of budget
    ) sub;
  ELSE
    v_experiential := '[]'::jsonb;
  END IF;

  -- -----------------------------------------------------------------------
  -- C) Merge: base traits first (DNA dominates), then experiential
  -- -----------------------------------------------------------------------
  SELECT jsonb_agg(elem ORDER BY (elem->>'score')::numeric DESC)
  INTO v_merged
  FROM (
    SELECT jsonb_array_elements(v_base_traits) AS elem
    UNION ALL
    SELECT jsonb_array_elements(v_experiential) AS elem
  ) combined;

  RETURN COALESCE(v_merged, '[]'::jsonb);
END;
$$;

REVOKE ALL ON FUNCTION public.fn_search_personality_context(uuid, vector, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_search_personality_context(uuid, vector, integer) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/generate_copilot_instructions.sql
-- -----------------------------------------------------------------------------

-- Function: generate_copilot_instructions
-- Fixed: uses actual expert_rule_category enum values instead of hardcoded section names

CREATE OR REPLACE FUNCTION public.generate_copilot_instructions(p_story_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_story RECORD;
  v_ruleset RECORD;
  v_rule RECORD;
  v_md text := '';
  v_cat text;
  v_cat_rules text;
  v_cat_label text;
  v_categories text[];
BEGIN
  -- Stráž (can_access_story.sql) — PŘED dohledáním, ať cizí a neexistující story vypadají stejně.
  IF NOT public.can_access_story(p_story_id) THEN
    RAISE EXCEPTION 'Access denied to story %', p_story_id USING ERRCODE = '42501';
  END IF;

  -- Load story
  SELECT ps.title, ps.tech_stack, ps.domain, ps.risk_profile
  INTO v_story
  FROM partner_stories ps
  WHERE ps.id = p_story_id;

  IF v_story IS NULL THEN
    RAISE EXCEPTION 'Story not found: %', p_story_id USING ERRCODE = 'P0002';
  END IF;

  -- Load active ruleset
  SELECT sr.ruleset_fingerprint, sr.rule_ids, sr.context_profile
  INTO v_ruleset
  FROM story_contexts sc
  JOIN story_rulesets sr ON sr.id = sc.ruleset_id
  WHERE sc.story_id = p_story_id;

  -- Header
  v_md := '# Copilot Instructions — ' || v_story.title || E'\n\n';
  v_md := v_md || '> Auto-generated from Evymo Expert Overlay ruleset.' || E'\n';
  v_md := v_md || '> **Do not edit manually** — regenerate via `generate_copilot_instructions(story_id)`.' || E'\n\n';

  -- Project metadata
  v_md := v_md || '## 🎯 Project' || E'\n\n';
  v_md := v_md || '**Tech Stack:** ' || COALESCE(array_to_string(v_story.tech_stack, ', '), 'Not specified') || E'\n';
  v_md := v_md || '**Domain:** ' || COALESCE(array_to_string(v_story.domain, ', '), 'General') || E'\n';
  v_md := v_md || '**Risk Profile:** ' || COALESCE(v_story.risk_profile, 'low') || E'\n\n';

  IF v_ruleset.ruleset_fingerprint IS NOT NULL THEN
    v_md := v_md || '**Ruleset Fingerprint:** `' || v_ruleset.ruleset_fingerprint || '`' || E'\n';
    v_md := v_md || '**Context Profile:** ' || COALESCE(v_ruleset.context_profile, 'repo_plus_rules') || E'\n\n';
  END IF;

  v_md := v_md || '---' || E'\n\n';

  -- If no ruleset, return minimal
  IF v_ruleset.rule_ids IS NULL THEN
    v_md := v_md || '_No ruleset pinned to this story. Pin rules via `create_story_ruleset(story_id, rule_ids[])`._' || E'\n';
    RETURN v_md;
  END IF;

  -- Group rules by actual categories present in the ruleset
  v_md := v_md || '## ⚠️ Expert Rules' || E'\n\n';

  -- Dynamically get distinct categories from the pinned rules
  SELECT array_agg(DISTINCT er.category::text ORDER BY er.category::text)
  INTO v_categories
  FROM expert_rules er
  WHERE er.id = ANY(v_ruleset.rule_ids)
    AND er.status = 'published'
    AND er.visibility IN ('public', 'members');

  IF v_categories IS NOT NULL THEN
    FOREACH v_cat IN ARRAY v_categories
    LOOP
      v_cat_rules := '';

      -- Human-readable category label
      v_cat_label := replace(initcap(replace(v_cat, '_', ' ')), '_', ' ');

      FOR v_rule IN
        SELECT er.slug, er.title, er.category::text, er.ai_instructions, er.summary
        FROM expert_rules er
        WHERE er.id = ANY(v_ruleset.rule_ids)
          AND er.status = 'published'
          AND er.visibility IN ('public', 'members')
          AND er.category::text = v_cat
        ORDER BY er.slug
      LOOP
        -- Rule title as H4 (under H3 category)
        v_cat_rules := v_cat_rules || '#### ' || v_rule.title || E'\n\n';

        IF v_rule.ai_instructions IS NOT NULL AND v_rule.ai_instructions != '' THEN
          v_cat_rules := v_cat_rules || v_rule.ai_instructions || E'\n\n';
        ELSIF v_rule.summary IS NOT NULL THEN
          v_cat_rules := v_cat_rules || v_rule.summary || E'\n\n';
        END IF;
      END LOOP;

      IF v_cat_rules != '' THEN
        v_md := v_md || '### ' || v_cat_label || E'\n\n';
        v_md := v_md || v_cat_rules;
      END IF;
    END LOOP;
  END IF;

  v_md := v_md || E'\n---\n\n';

  -- Footer
  v_md := v_md || E'## 📋 PR Checklist\n\n';
  v_md := v_md || '- [ ] All expert rules followed' || E'\n';
  v_md := v_md || '- [ ] `npm run test` — passing' || E'\n';
  v_md := v_md || '- [ ] `npm run build` — successful' || E'\n';
  v_md := v_md || '- [ ] `npm run lint` — no errors' || E'\n';
  v_md := v_md || '- [ ] No hardcoded text in JSX (use i18n)' || E'\n';
  v_md := v_md || '- [ ] No `any` types' || E'\n';
  v_md := v_md || '- [ ] No `console.log` in production code' || E'\n';

  RETURN v_md;
END;
$function$;

REVOKE ALL ON FUNCTION generate_copilot_instructions(p_story_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION generate_copilot_instructions(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION generate_copilot_instructions(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/generate_default_copilot_instructions.sql
-- -----------------------------------------------------------------------------

-- Function: generate_default_copilot_instructions
-- Returns copilot-instructions.md content from default (public, is_default=true) rules only.
-- Accessible to anon — no authentication required.

CREATE OR REPLACE FUNCTION public.generate_default_copilot_instructions()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_md text := '';
  v_rule RECORD;
  v_cat text;
  v_cat_rules text;
  v_cat_label text;
  v_categories text[];
BEGIN
  v_md := '# Copilot Instructions — Default Standards' || E'\n\n';
  v_md := v_md || '> Auto-generated from AISHA Knowledge Base (default rule set).' || E'\n';
  v_md := v_md || '> These are generic best-practice rules available to all users.' || E'\n';
  v_md := v_md || '> For project-specific rules, connect to AISHA Cloud and use `generate_copilot_instructions(story_id)`.' || E'\n\n';
  v_md := v_md || '---' || E'\n\n';

  SELECT array_agg(DISTINCT er.category::text ORDER BY er.category::text)
  INTO v_categories
  FROM expert_rules er
  WHERE er.is_default = true
    AND er.status = 'published'
    AND er.visibility = 'public';

  IF v_categories IS NULL THEN
    v_md := v_md || '_No default rules found. Seed the database with default expert rules._' || E'\n';
    RETURN v_md;
  END IF;

  v_md := v_md || '## Expert Rules' || E'\n\n';

  FOREACH v_cat IN ARRAY v_categories
  LOOP
    v_cat_rules := '';
    v_cat_label := replace(initcap(replace(v_cat, '_', ' ')), '_', ' ');

    FOR v_rule IN
      SELECT er.slug, er.title, er.ai_instructions, er.summary
      FROM expert_rules er
      WHERE er.is_default = true
        AND er.status = 'published'
        AND er.visibility = 'public'
        AND er.category::text = v_cat
      ORDER BY er.slug
    LOOP
      -- Rule title as H4 (under H3 category)
      v_cat_rules := v_cat_rules || '#### ' || v_rule.title || E'\n\n';
      IF v_rule.ai_instructions IS NOT NULL AND v_rule.ai_instructions != '' THEN
        v_cat_rules := v_cat_rules || v_rule.ai_instructions || E'\n\n';
      ELSIF v_rule.summary IS NOT NULL THEN
        v_cat_rules := v_cat_rules || v_rule.summary || E'\n\n';
      END IF;
    END LOOP;

    IF v_cat_rules != '' THEN
      v_md := v_md || '### ' || v_cat_label || E'\n\n';
      v_md := v_md || v_cat_rules;
    END IF;
  END LOOP;

  v_md := v_md || E'\n---\n\n';
  v_md := v_md || '> **Tip:** Connect to AISHA Cloud for project-specific expert rules, automated onboarding, and full knowledge base access.' || E'\n';

  RETURN v_md;
END;
$function$;

REVOKE ALL ON FUNCTION generate_default_copilot_instructions() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION generate_default_copilot_instructions() TO anon;
GRANT EXECUTE ON FUNCTION generate_default_copilot_instructions() TO authenticated;
GRANT EXECUTE ON FUNCTION generate_default_copilot_instructions() TO service_role;

COMMENT ON FUNCTION generate_default_copilot_instructions() IS
  'Returns copilot-instructions.md from default (public) rules. No auth required.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_active_channel_config.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_active_channel_config
-- Arguments: p_channel_slug text
-- Description: Returns full channel config for n8n / edge functions. Channel is the sole config source.
-- Security: SECURITY DEFINER
-- Search path: public (set per-function below)
-- Source: aisha/db/migrations/20260411180000_drop_agent_configurations.sql

CREATE OR REPLACE FUNCTION public.get_active_channel_config(p_channel_slug text)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_channel record;
  v_result  jsonb;
BEGIN
  -- ⛔ NÁROK, NE JEN DOSTUPNOST (naměřeno 2026-09-12). Funkce vydává
  -- `system_prompt`, `guardrails`, `routing_rules`, `allowed_tools`
  -- a `vector_store_config` — tedy přesně to, co útočník potřebuje, aby
  -- guardraily obešel. Volat ji směl i ANONYM, stačil slug kanálu.
  --
  -- Hlavička sama říká, čí je to pohled: „for n8n / edge functions". Změřeno,
  -- kdo ji v repu volá: svc-ai-chat (chat, public-chat, story-consult),
  -- svc-mcp-knowledge a WF_PUBLIC_CHATBOT — všichni přes SERVICE klíč
  -- (`rpcService`, resp. AISHA_POSTGREST_SERVICE_KEY). Z prohlížeče ji nevolá
  -- nikdo, takže zúžení na službu a správu žádného konzumenta nebere.
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Service role or admin access required';
  END IF;

  SELECT
    pcc.id,
    pcc.slug,
    pcc.display_name,
    pcc.channel_type,
    pcc.context_profile,
    pcc.personality_enabled,
    pcc.model,
    pcc.temperature,
    pcc.max_tokens,
    pcc.system_prompt,
    pcc.model_settings,
    pcc.vector_store_config,
    pcc.guardrails,
    pcc.routing_rules,
    pcc.allowed_tools,
    pcc.widget_config,
    pcc.lead_capture
  INTO v_channel
  FROM public.public_chat_channels pcc
  WHERE pcc.slug = p_channel_slug AND pcc.status = 'active';

  IF v_channel IS NULL THEN
    RETURN jsonb_build_object('error', 'Channel not found or inactive');
  END IF;

  v_result := jsonb_build_object(
    'channel_id',           v_channel.id,
    'slug',                 v_channel.slug,
    'display_name',         v_channel.display_name,
    'channel_type',         v_channel.channel_type,
    'context_profile',      v_channel.context_profile,
    'personality_enabled',  v_channel.personality_enabled,
    -- LLM config — channel is the sole source
    'model',                v_channel.model,
    'temperature',          v_channel.temperature,
    'max_tokens',           v_channel.max_tokens,
    'system_prompt',        v_channel.system_prompt,
    'model_settings',       v_channel.model_settings,
    -- RAG pipeline config
    'vector_store_config',  v_channel.vector_store_config,
    -- Channel-specific config
    'guardrails',           v_channel.guardrails,
    'routing_rules',        v_channel.routing_rules,
    'allowed_tools',        v_channel.allowed_tools,
    'widget_config',        v_channel.widget_config,
    'lead_capture',         v_channel.lead_capture
  );

  RETURN v_result;
END;
$$;

-- `anon` tu ZÁMĚRNĚ není: bez účtu se k systémovému promptu nikdo nedostane.
-- `authenticated` zůstává, protože správce kanály nastavuje — nárok mu ale
-- dává STRÁŽ V TĚLE, ne grant (týž tvar jako get_test_questions_admin_localized).
REVOKE ALL ON FUNCTION public.get_active_channel_config(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_active_channel_config(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_active_channel_config(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_active_slots.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_active_slots
-- Popis: Read-only view pro Phase 4 dashboard — vrací current B/G state s
--        active/inactive slot, image tags, healths, switch lock state.
--        Včetně managed_kind: 'system' (NULL story_id) | 'user_story'.
-- Volá: WF_APPSMITH_DASHBOARD_BUILDER, dashboard widgets
-- Auth: admin/staff (read-only) nebo service_role
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_active_slots()
RETURNS TABLE (
  app_name             text,
  active_slot          text,
  active_image_tag     text,
  active_health        text,
  inactive_slot        text,
  inactive_image_tag   text,
  inactive_health      text,
  last_switch_at       timestamptz,
  last_switch_by       uuid,
  switch_lock          boolean,
  switch_lock_age_min  int,
  domain               text,
  story_id             uuid,
  managed_kind         text     -- 'system' (NULL story_id) | 'user_story'
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF NOT public.is_admin_or_staff()
     AND NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  RETURN QUERY
  SELECT
    cas.app_name,
    cas.active_slot,
    CASE cas.active_slot
      WHEN 'blue' THEN cas.blue_image_tag
      ELSE cas.green_image_tag
    END AS active_image_tag,
    CASE cas.active_slot
      WHEN 'blue' THEN cas.blue_health
      ELSE cas.green_health
    END AS active_health,
    CASE cas.active_slot WHEN 'blue' THEN 'green' ELSE 'blue' END AS inactive_slot,
    CASE cas.active_slot
      WHEN 'blue' THEN cas.green_image_tag
      ELSE cas.blue_image_tag
    END AS inactive_image_tag,
    CASE cas.active_slot
      WHEN 'blue' THEN cas.green_health
      ELSE cas.blue_health
    END AS inactive_health,
    cas.last_switch_at,
    cas.last_switch_by,
    cas.switch_lock,
    CASE
      WHEN cas.switch_lock_at IS NULL THEN NULL
      ELSE EXTRACT(EPOCH FROM (now() - cas.switch_lock_at))::int / 60
    END AS switch_lock_age_min,
    cas.domain,
    cas.story_id,
    CASE WHEN cas.story_id IS NULL THEN 'system' ELSE 'user_story' END AS managed_kind
  FROM public.coolify_app_slots cas
  ORDER BY cas.app_name;
END;
$$;

REVOKE ALL ON FUNCTION public.get_active_slots() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_active_slots() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_active_slots() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_active_triggers_for_source.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION get_active_triggers_for_source(
  p_source_table text,
  p_source_event text DEFAULT 'INSERT'
)
RETURNS TABLE (
  id uuid,
  name text,
  condition jsonb,
  action_type text,
  agent_name text,
  workflow_name text,
  action_config jsonb,
  target_roles text[],
  priority text,
  cooldown_minutes integer
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service_role BOOLEAN;
BEGIN
  v_is_service_role := public.is_service_role();
  IF auth.uid() IS NULL AND NOT v_is_service_role THEN
    RAISE EXCEPTION 'Access denied: authentication required';
  END IF;

  RETURN QUERY
    SELECT
      t.id, t.name, t.condition, t.action_type,
      t.agent_name, t.workflow_name, t.action_config,
      t.target_roles, t.priority, t.cooldown_minutes
    FROM ai_proactive_trigger_definitions t
    WHERE t.source_table = p_source_table
      AND t.source_event = p_source_event
      AND t.is_active = true
    ORDER BY
      CASE t.priority
        WHEN 'critical' THEN 0
        WHEN 'high' THEN 1
        WHEN 'normal' THEN 2
        WHEN 'low' THEN 3
      END;
END;
$$;

REVOKE ALL ON FUNCTION get_active_triggers_for_source(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION get_active_triggers_for_source(text, text) TO authenticated;


