-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_allowed_transitions.sql
-- -----------------------------------------------------------------------------

-- Function: get_allowed_transitions

CREATE OR REPLACE FUNCTION public.get_allowed_transitions(p_story_id uuid)
 RETURNS TABLE(to_status text, requires_role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_current_status text;
BEGIN
  -- Stráž (can_access_story.sql) — PŘED dohledáním, ať cizí a neexistující story vypadají stejně.
  IF NOT public.can_access_story(p_story_id) THEN
    RAISE EXCEPTION 'Access denied to story %', p_story_id USING ERRCODE = '42501';
  END IF;

  SELECT delivery_status INTO v_current_status
  FROM partner_stories
  WHERE id = p_story_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Story not found: %', p_story_id USING ERRCODE = 'P0002';
  END IF;

  RETURN QUERY
  SELECT dtr.to_status, dtr.requires_role
  FROM delivery_transition_rules dtr
  WHERE dtr.is_active = true
    AND (dtr.from_status IS NOT DISTINCT FROM v_current_status)
  ORDER BY dtr.to_status;
END;
$function$;

REVOKE ALL ON FUNCTION get_allowed_transitions(p_story_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION get_allowed_transitions(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION get_allowed_transitions(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_answer_chain_costs.sql
-- -----------------------------------------------------------------------------

-- Náklad podle modelu (blok typu `chart`, kind=bar).
--
-- Doktrína „fakta z PG jsou zadarmo, model jen formuluje" má smysl jen tehdy,
-- když je ten zbytek VIDĚT. Tenhle blok ukazuje, kam peníze skutečně tečou —
-- po modelech, ne jedním součtem, protože součet neřekne, který model se
-- vyplatí vyměnit.
--
-- `usd` čte z cost_json, kam ho zapisuje llm-gateway. Modely bez ceny (lokální,
-- sovereign) vyjdou v nule — a nula je tu správná odpověď, ne chybějící údaj.

create or replace function public.get_answer_chain_costs(p_params jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
stable
security definer
SET search_path TO 'public', 'pg_temp'
as $$
declare
  v_uid    uuid := auth.uid();
  v_days   int  := least(coalesce((p_params->>'days')::int, 30), 365);
  v_points jsonb;
begin
  -- ⛔ NÁROK, NE JEN PŘIHLÁŠENÍ (naměřeno 2026-09-11). Guard tu zněl
  -- `uid is null and not is_service_role()` — to ověřuje, že jsi PŘIHLÁŠENÝ,
  -- ne že na to máš nárok. Diferenciální sondou (admin × řidič bez rolí nad
  -- týmiž daty) vycházelo obojí STEJNĚ, tedy kterýkoli řidič dostal admin
  -- pohled. `SECURITY DEFINER` vypne RLS a odpovědnost tím přechází na tělo
  -- funkce; chybějící `if` tu neznamená „zamítnuto", ale plnou odpověď.
  if not (public.is_admin_or_staff() or public.is_service_role()) then
    return jsonb_build_object(
      'data', jsonb_build_object('kind','bar','points','[]'::jsonb),
      'provenance', jsonb_build_object('source_slug','ai_trace_events','trace_id','answer_chain:case_costs','freshness_at',now()));
  end if;

  select coalesce(jsonb_agg(p order by (p->>'value')::numeric desc), '[]'::jsonb) into v_points
  from (
    select jsonb_build_object(
      'label', model,
      -- Mikrocenty by se zaokrouhlily na nulu; 6 desetinných míst udrží rozdíl
      -- mezi „skoro zdarma" a „doopravdy nula" viditelný.
      'value', round(sum(coalesce((e.cost_json->>'usd')::numeric, 0)), 6),
      'note',  count(*)::text
    ) as p
    from (
      select coalesce(nullif(e.cost_json->>'model_id',''), e.model_id, 'neuvedeno') as model,
             e.cost_json
      from public.ai_trace_events e
      where e.created_at >= now() - make_interval(days => v_days)
        and (e.cost_json is not null or e.model_id is not null)
    ) e
    group by model
  ) t;

  return jsonb_build_object(
    'data', jsonb_build_object('kind','bar','points', v_points, 'unit_key','app.units.usd'),
    'provenance', jsonb_build_object('source_slug','ai_trace_events','trace_id','answer_chain:case_costs','freshness_at',now()));
end;
$$;

REVOKE ALL ON FUNCTION public.get_answer_chain_costs(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_answer_chain_costs(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_answer_chain_metrics.sql
-- -----------------------------------------------------------------------------

-- Provozní metriky odpovídacího řetězu (admin pohled).
--
-- Nosič se staví i tam, kde hodnoty zatím nejsou: prázdný blok s provenancí je
-- SIGNÁL, že si data máme vyžádat, ne důvod blok nepostavit. Proto tu není
-- žádná podmínka „vrať null když je málo řádků" — vrátí se, co je.
--
-- Zdroj: ai_trace_events (jeden řádek na krok běhu — router, kompozice, nástroj).

create or replace function public.get_answer_chain_metrics(p_params jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
stable
security definer
SET search_path TO 'public', 'pg_temp'
as $$
declare
  v_uid  uuid := auth.uid();
  v_days int  := least(coalesce((p_params->>'days')::int, 30), 365);
  v_rows jsonb;
  -- Sloupce jsou KONTRAKT bloku (která maska, jaké popisky), ne data. Drží se
  -- v proměnné, aby odmítavá i plná větev vydaly TÝŽ tvar a nemohly se rozejít.
  v_cols jsonb := jsonb_build_array(
    jsonb_build_object('key','kind',   'label_key','app.cols.kind'),
    jsonb_build_object('key','calls',  'label_key','app.cols.calls',  'align','right'),
    jsonb_build_object('key','ok',     'label_key','app.cols.ok',     'align','right'),
    jsonb_build_object('key','errors', 'label_key','app.cols.errors', 'align','right'),
    jsonb_build_object('key','p50_ms', 'label_key','app.cols.p50',    'align','right'),
    jsonb_build_object('key','p95_ms', 'label_key','app.cols.p95',    'align','right'));
begin
  -- ⛔ NÁROK, NE JEN PŘIHLÁŠENÍ (naměřeno 2026-09-11). Guard tu zněl
  -- `uid is null and not is_service_role()` — to ověřuje, že jsi PŘIHLÁŠENÝ,
  -- ne že na to máš nárok. Diferenciální sondou (admin × řidič bez rolí nad
  -- týmiž daty) vycházelo obojí STEJNĚ, tedy kterýkoli řidič dostal admin
  -- pohled. `SECURITY DEFINER` vypne RLS a odpovědnost tím přechází na tělo
  -- funkce; chybějící `if` tu neznamená „zamítnuto", ale plnou odpověď.
  if not (public.is_admin_or_staff() or public.is_service_role()) then
    -- Odmítnutí vydá TÝŽ kontrakt s NULOU řádků, ne `columns: []`. Dva důvody:
    -- (1) tabulka bez sloupců neprojde maskou, povrch ji zahodí a uživatel místo
    --     prázdné tabulky nevidí blok vůbec (brána kontraktu bloků 2026-09-12);
    -- (2) odmítnutí tím vypadá stejně jako prázdná instance — nevzniká orákulum,
    --     které by nepovolanému prozradilo, že tu NĚCO je, jen ne pro něj.
    return jsonb_build_object(
      'data', jsonb_build_object('columns', v_cols, 'rows', '[]'::jsonb),
      'provenance', jsonb_build_object('source_slug','ai_trace_events','trace_id','answer_chain:metrics','freshness_at',now()));
  end if;

  select coalesce(jsonb_agg(r order by r->>'kind'), '[]'::jsonb) into v_rows
  from (
    select jsonb_build_object(
      'kind',      e.event_type,
      'calls',     count(*),
      'ok',        count(*) filter (where e.status = 'ok'),
      'errors',    count(*) filter (where e.status is distinct from 'ok'),
      -- Medián, ne průměr: jeden pomalý běh nesmí posunout obrázek o zdraví.
      'p50_ms',    percentile_disc(0.5) within group (order by e.duration_ms),
      'p95_ms',    percentile_disc(0.95) within group (order by e.duration_ms)
    ) as r
    from public.ai_trace_events e
    where e.created_at >= now() - make_interval(days => v_days)
    group by e.event_type
  ) t;

  return jsonb_build_object(
    'data', jsonb_build_object(
      'columns', v_cols,
      'rows', v_rows),
    'provenance', jsonb_build_object('source_slug','ai_trace_events','trace_id','answer_chain:metrics','freshness_at',now()));
end;
$$;

REVOKE ALL ON FUNCTION public.get_answer_chain_metrics(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_answer_chain_metrics(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_answer_chain_runs.sql
-- -----------------------------------------------------------------------------

-- Poslední běhy (admin pohled) — co systém dělal sám od sebe a jak to dopadlo.
--
-- Zdroj ai_runs: každý běh patří ke story (axiom „běh vždy patří ke story"),
-- takže se sem dostane i vnitřní běh přes stack-default story. `kind` je nosič
-- druhu běhu — proactive, ide_session, … — a NErozšiřuje se o další tabulku
-- *_runs, ať se ten anti-vzor neopakuje.
--
-- Prázdný výsledek je legitimní stav čerstvé instance, ne chyba.

create or replace function public.get_answer_chain_runs(p_params jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
stable
security definer
SET search_path TO 'public', 'pg_temp'
as $$
declare
  v_uid   uuid := auth.uid();
  v_limit int  := least(coalesce((p_params->>'limit')::int, 20), 200);
  v_rows  jsonb;
  -- Sloupce jsou KONTRAKT bloku, ne data — viz get_answer_chain_metrics.
  v_cols jsonb := jsonb_build_array(
    jsonb_build_object('key','started','label_key','app.cols.started'),
    jsonb_build_object('key','kind',   'label_key','app.cols.kind'),
    jsonb_build_object('key','status', 'label_key','app.cols.status'),
    jsonb_build_object('key','steps',  'label_key','app.cols.steps','align','right'));
begin
  -- ⛔ NÁROK, NE JEN PŘIHLÁŠENÍ (naměřeno 2026-09-11). Guard tu zněl
  -- `uid is null and not is_service_role()` — to ověřuje, že jsi PŘIHLÁŠENÝ,
  -- ne že na to máš nárok. Diferenciální sondou (admin × řidič bez rolí nad
  -- týmiž daty) vycházelo obojí STEJNĚ, tedy kterýkoli řidič dostal admin
  -- pohled. `SECURITY DEFINER` vypne RLS a odpovědnost tím přechází na tělo
  -- funkce; chybějící `if` tu neznamená „zamítnuto", ale plnou odpověď.
  if not (public.is_admin_or_staff() or public.is_service_role()) then
    -- Odmítnutí vydá TÝŽ kontrakt s NULOU řádků (viz get_answer_chain_metrics):
    -- tabulka bez sloupců maskou neprojde a povrch blok zahodí.
    return jsonb_build_object(
      'data', jsonb_build_object('columns', v_cols, 'row_kind', 'answer_run', 'rows', '[]'::jsonb),
      'provenance', jsonb_build_object('source_slug','ai_runs','trace_id','answer_chain:test_run','freshness_at',now()));
  end if;

  select coalesce(jsonb_agg(r order by r->>'started' desc), '[]'::jsonb) into v_rows
  from (
    select jsonb_build_object(
      'id',      left(a.id::text, 8),
      'kind',    a.kind,
      'status',  a.status,
      'started', to_char(a.started_at, 'YYYY-MM-DD HH24:MI'),
      -- Kroky běhu jsou v ai_trace_events; jejich počet říká, jestli běh
      -- doopravdy něco dělal, nebo jen vznikl a zhasl.
      'steps',   (select count(*) from public.ai_trace_events e where e.run_id = a.id)
    ) as r
    from public.ai_runs a
    order by a.started_at desc nulls last
    limit v_limit
  ) t;

  return jsonb_build_object(
    'data', jsonb_build_object(
      'columns', v_cols,
      -- `id` je ZKRÁCENÝ běh (left(...,8)) — zobrazovací hodnota, kterou
      -- nelze ničím otevřít. Druh se přesto říká: shell pak řekne „tenhle
      -- řádek nemá detail" místo aby poslal zkomolené id čtečce dokladů
      -- a vydal prázdnou kartu.
      'row_kind', 'answer_run',
      'rows', v_rows),
    'provenance', jsonb_build_object('source_slug','ai_runs','trace_id','answer_chain:test_run','freshness_at',now()));
end;
$$;

REVOKE ALL ON FUNCTION public.get_answer_chain_runs(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_answer_chain_runs(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_answer_chain_trend.sql
-- -----------------------------------------------------------------------------

-- Vývoj zátěže odpovídacího řetězu v čase (blok typu `chart`, kind=trend).
--
-- Vrací JEDEN bod na den, i když je ten den prázdný — díra v řadě je informace
-- („tehdy se nic nedělo"), kdežto vynechaný den by graf tiše zkreslil tím, že
-- by sousední dny slepil k sobě. generate_series drží osu poctivou.
--
-- Zdroj: ai_trace_events. Když nejsou žádná data, řada vyjde v nulách — nosič
-- stojí a prázdno je signál, že si data máme vyžádat.

create or replace function public.get_answer_chain_trend(p_params jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
stable
security definer
SET search_path TO 'public', 'pg_temp'
as $$
declare
  v_uid    uuid := auth.uid();
  v_days   int  := least(coalesce((p_params->>'days')::int, 14), 90);
  v_points jsonb;
begin
  -- ⛔ NÁROK, NE JEN PŘIHLÁŠENÍ (naměřeno 2026-09-11). Guard tu zněl
  -- `uid is null and not is_service_role()` — to ověřuje, že jsi PŘIHLÁŠENÝ,
  -- ne že na to máš nárok. Diferenciální sondou (admin × řidič bez rolí nad
  -- týmiž daty) vycházelo obojí STEJNĚ, tedy kterýkoli řidič dostal admin
  -- pohled. `SECURITY DEFINER` vypne RLS a odpovědnost tím přechází na tělo
  -- funkce; chybějící `if` tu neznamená „zamítnuto", ale plnou odpověď.
  if not (public.is_admin_or_staff() or public.is_service_role()) then
    return jsonb_build_object(
      'data', jsonb_build_object('kind','trend','points','[]'::jsonb),
      'provenance', jsonb_build_object('source_slug','ai_trace_events','trace_id','answer_chain:trend','freshness_at',now()));
  end if;

  select coalesce(jsonb_agg(p order by p->>'label'), '[]'::jsonb) into v_points
  from (
    select jsonb_build_object(
      'label', to_char(d.day, 'MM-DD'),
      'value', coalesce(c.n, 0)
    ) as p
    from generate_series(
           (now() - make_interval(days => v_days - 1))::date,
           now()::date,
           interval '1 day') as d(day)
    left join (
      select created_at::date as day, count(*) as n
      from public.ai_trace_events
      where created_at >= now() - make_interval(days => v_days)
      group by 1
    ) c on c.day = d.day
  ) t;

  return jsonb_build_object(
    'data', jsonb_build_object('kind','trend','points', v_points),
    'provenance', jsonb_build_object('source_slug','ai_trace_events','trace_id','answer_chain:trend','freshness_at',now()));
end;
$$;

REVOKE ALL ON FUNCTION public.get_answer_chain_trend(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_answer_chain_trend(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_answer_coverage_block.sql
-- -----------------------------------------------------------------------------

-- Pokrytí odpovědního řetězu — které oblasti jsou ověřené a v jakém stavu.
--
-- OBNOVENO ZE ŽIVÉ DATABÁZE (2026-07-28). Tahle funkce běžela v produkci a její
-- definice neexistovala v žádném repu — ani tady, ani v instance-datech, ani
-- v rozpuštěném surfaces repu. Cold start by blok i řádek allowlistu vyrobil
-- a pak zavolal funkci, kterou nikdo nevytvořil.
--
-- Při obnově opraveny tři vady, které měla živá verze:
--
-- 1. PROVENANCE porušovala kontrakt. Vracela {source_slug, kind}, schéma žádá
--    {source_slug, freshness_at, trace_id} a nic navíc. Klient proto CELÝ blok
--    přeskakoval ("block contract violation") — data existovala a nikdo je
--    neviděl.
--
-- 2. INSTANCE LITERÁL v generickém SQL: `context_profile_slug = '<instance>'`. Schéma
--    dědí celý stack, takže tohle je nejdražší možné místo pro jméno instance.
--    Profil teď chodí z `source_params` bloku — tedy generický mechanismus,
--    instanční hodnota (`<instance>/41_surface_blocks.sql` v instančním repu).
--
-- 3. POPISKY bez překladu (`col.oblast`, `col.stav`) — mimo prefix `app.`,
--    takže je i18n brána nevidí. Přejmenováno na `app.cols.*`.
--
-- Bez profilu vrátí PRÁZDNO, ne chybu: prázdný nosič s provenancí je signál
-- „tahle instance pokrytí nedeklaruje", kdežto pád vypadá jako rozbitý blok.

-- 4. BEZ KONTROLY IDENTITY. `security definer` obchází RLS, a živá verze
--    nekontrolovala vůbec nic — kdokoli, kdo se dostal k volání, dostal data.
--    Ostatní blokové RPC mají fail-closed stráž (prázdná obálka bez identity);
--    tahle ji do teď neměla. Doplněno, a proto je funkce plpgsql, ne sql.

create or replace function public.get_answer_coverage_block(p_params jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
stable
security definer
SET search_path TO 'public', 'pg_temp'
as $$
declare
  v_uid uuid := auth.uid();
begin
  -- Fail-closed: bez identity PRÁZDNO, ne chyba. Prázdný nosič s provenancí je
  -- signál; chyba by vypadala jako rozbitý blok.
  -- ⛔ NÁROK, NE JEN PŘIHLÁŠENÍ (naměřeno 2026-09-11). Guard tu zněl
  -- `uid is null and not is_service_role()` — to ověřuje, že jsi PŘIHLÁŠENÝ,
  -- ne že na to máš nárok. Diferenciální sondou (admin × řidič bez rolí nad
  -- týmiž daty) vycházelo obojí STEJNĚ, tedy kterýkoli řidič dostal admin
  -- pohled. `SECURITY DEFINER` vypne RLS a odpovědnost tím přechází na tělo
  -- funkce; chybějící `if` tu neznamená „zamítnuto", ale plnou odpověď.
  if not (public.is_admin_or_staff() or public.is_service_role()) then
    return jsonb_build_object(
      'data', jsonb_build_object(
        'columns', jsonb_build_array(
          jsonb_build_object('key','oblast','label_key','app.cols.area'),
          jsonb_build_object('key','stav',  'label_key','app.cols.state')),
        'rows', '[]'::jsonb),
      'provenance', jsonb_build_object(
        'source_slug',  'rag_eval_golden',
        'trace_id',     'answer_chain:coverage',
        'freshness_at', now()));
  end if;

  return (select jsonb_build_object(
    'data', jsonb_build_object(
      'columns', jsonb_build_array(
        jsonb_build_object('key','oblast','label_key','app.cols.area'),
        jsonb_build_object('key','stav',  'label_key','app.cols.state')),
      'rows', coalesce((
        select jsonb_agg(distinct jsonb_build_object(
                 'oblast', tags[3],
                 'stav',   replace(tags[4], 'cov:', '')))
        from public.rag_eval_golden
        where context_profile_slug = nullif(p_params->>'context_profile', '')
          and array_length(tags, 1) >= 4
      ), '[]'::jsonb)),
    'provenance', jsonb_build_object(
      'source_slug',  'rag_eval_golden',
      'trace_id',     'answer_chain:coverage',
      'freshness_at', now())));
end;
$$;

REVOKE ALL ON FUNCTION public.get_answer_coverage_block(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_answer_coverage_block(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_audit_aggregates.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_audit_aggregates
-- Popis: Pattern detection helper pro WF_AISHA_TOOLING_OBSERVER. Vrátí akce
--        s ≥ p_min_occurrences výskyty v posledních p_window_days dnech, group
--        by action. Computes success_rate (heuristic: action ending in '_failed'/'_error'
--        = failure) a vrací sample recent metadata (latest occurrence per action).
-- Volá: WF_AISHA_TOOLING_OBSERVER (META-2)
-- Auth: admin/staff nebo service_role
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_audit_aggregates(
  p_window_days int DEFAULT 7,
  p_min_occurrences int DEFAULT 5
)
RETURNS TABLE (
  action            text,
  occurrence_count  int,
  unique_users      int,
  success_rate      numeric,
  recent_metadata   jsonb,
  first_seen        timestamptz,
  last_seen         timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF NOT public.is_admin_or_staff()
     AND NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  RETURN QUERY
  SELECT
    aj.action,
    count(*)::int AS occurrence_count,
    count(DISTINCT aj.user_id)::int AS unique_users,
    -- success_rate via heuristic — actions ending in '_failed', '_error' = failure
    (
      count(*) FILTER (
        WHERE aj.action !~ '_(failed|error|aborted|rejected)$'
      )::numeric / NULLIF(count(*), 0)::numeric
    ) AS success_rate,
    -- Sample of metadata (most recent occurrence)
    (
      SELECT aj2.metadata
      FROM public.audit_journal aj2
      WHERE aj2.action = aj.action
      ORDER BY aj2.created_at DESC
      LIMIT 1
    ) AS recent_metadata,
    min(aj.created_at) AS first_seen,
    max(aj.created_at) AS last_seen
  FROM public.audit_journal aj
  WHERE aj.created_at > now() - (p_window_days || ' days')::interval
  GROUP BY aj.action
  HAVING count(*) >= p_min_occurrences
  ORDER BY count(*) DESC;
END;
$$;

REVOKE ALL ON FUNCTION public.get_audit_aggregates(int, int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_audit_aggregates(int, int) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_audit_aggregates(int, int) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_available_plugins.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- get_available_plugins(p_kind, p_tenant_id) — KATALOG pluginů
-- =============================================================================
-- Vrací instalovatelné pluginy (status canary/ga), volitelně jen daného druhu.
-- S p_tenant_id vynechá pluginy, které si tenant vypnul
-- (plugin_tenant_overrides.enabled = false).
--
-- Volající (naměřeno 2026-09-15):
--   · SPA `/agents` (veřejná routa, loader bez RequireAuth) — anon i
--     authenticated, p_kind='agent', bez tenanta
--   · svc-plugin-system `/registry` a `resolvePlugin` — service_role, bez tenanta
--   · broker sandboxu `/sandbox/rpc` — service_role s parametry, které zvolí
--     PLUGIN (pokud instance funkci povolí v PLUGIN_RPC_WHITELIST; šablona
--     scaffoldu ji pluginům dává jako výchozí schopnost)
--
-- ⛔ KATALOG NENESE KONFIGURACI PLUGINU (2026-09-15). Dřív projektoval
-- `plugin_tenant_overrides.config_override` jako `config` — a v něm žijí
-- přihlašovací údaje konektorů (tokeny, hesla, API klíče dodavatelů). Funkce je
-- SECURITY DEFINER, takže RLS tabulky overrides neplatila: stačil anon klíč a
-- p_tenant_id. Rozhoduje ÚČEL, ne jména klíčů: tajemství v konfiguraci nejde
-- vyjmenovat, a proto ji katalog nevydá nikomu. Ani service_role — tu roli
-- nese i broker, kterým se ptá plugin. Konfigurace má domov v tabulce pod RLS
-- (tenant sám, admin/staff, služba); běhová cesta k ní patří k rozlišení
-- tenanta v svc-plugin-system, ne ke katalogu.
--
-- ⛔ p_tenant_id ČTE overrides TENANTA. RLS tabulky to dovoluje jen tenantovi
-- samotnému (`tenant_id = auth.uid()`) a admin/staff; DEFINER ji obchází, takže
-- tentýž nárok tu stojí explicitně (+ služba). Bez něj by anon zjistil, co si
-- cizí tenant vypnul. Nárok se počítá JEDNOU do proměnné a je TOTÁLNÍ:
-- `p_tenant_id = auth.uid()` je pro anon NULL a `NOT NULL` by guard otevřel.
-- =============================================================================

CREATE OR REPLACE FUNCTION public.get_available_plugins(
  p_kind    text DEFAULT NULL,
  p_tenant_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_result jsonb;
  v_smi_tenanta boolean;
BEGIN
  IF p_tenant_id IS NOT NULL THEN
    v_smi_tenanta := public.is_service_role()
                  OR COALESCE(p_tenant_id = auth.uid(), false)
                  OR public.is_admin_or_staff();
    IF NOT v_smi_tenanta THEN
      RAISE EXCEPTION 'Unauthorized: plugin overrides of another tenant'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT jsonb_agg(row_to_json(sub))
  INTO v_result
  FROM (
    SELECT
      pc.id            AS plugin_id,
      pc.slug,
      pc.name,
      pc.description,
      pc.kind::text,
      pc.trust_tier::text,
      pc.status::text,
      pc.capabilities,
      COALESCE(pc.sandbox_policy, '{}'::jsonb)   AS sandbox,
      CASE
        WHEN pc.kind IN ('auth_provider', 'backend_provider') THEN 'cold'
        WHEN pc.lifecycle->>'load_strategy' = 'cold' THEN 'cold'
        ELSE 'hot'
      END AS load_strategy,
      pv.artifact_url,
      pv.artifact_sha256,
      pv.version
    FROM public.plugin_catalog pc
    -- Latest version (highest semver = latest created_at)
    LEFT JOIN LATERAL (
      SELECT artifact_url, artifact_sha256, version
      FROM public.plugin_versions
      WHERE plugin_id = pc.id
      ORDER BY created_at DESC
      LIMIT 1
    ) pv ON true
    -- Tenant override (if tenant_id provided and authorized above) — only the
    -- `enabled` flag is read; config_override never leaves this join.
    LEFT JOIN public.plugin_tenant_overrides pto
      ON pto.plugin_id = pc.id
      AND pto.tenant_id = p_tenant_id
    WHERE pc.status IN ('canary', 'ga')
      AND (p_kind IS NULL OR pc.kind::text = p_kind)
      -- If tenant override exists and disabled, exclude
      AND (pto.id IS NULL OR pto.enabled = true)
  ) sub;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;

COMMENT ON FUNCTION public.get_available_plugins(text, uuid) IS
  'Plugin catalog (canary/ga), optionally per kind; p_tenant_id (tenant itself, admin/staff or service_role only) hides plugins the tenant disabled. Never returns plugin configuration (config_override carries vendor credentials).';

REVOKE ALL ON FUNCTION public.get_available_plugins(text, uuid) FROM PUBLIC;
-- anon: veřejná routa /agents; authenticated: SPA přihlášeného; service_role:
-- svc-plugin-system (registry, resolvePlugin, broker).
GRANT EXECUTE ON FUNCTION public.get_available_plugins(text, uuid) TO anon, authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_chat_access_level.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_chat_access_level
-- Arguments: p_user_id uuid
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:41+01:00

CREATE OR REPLACE FUNCTION public.get_chat_access_level(p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_access_level TEXT := 'none';
  v_can_chat BOOLEAN := false;
  v_block_reason TEXT := NULL;
  v_has_terms_consent BOOLEAN := false;
  v_has_registration BOOLEAN := false;
  v_has_pending_registration BOOLEAN := false;
  v_has_active_membership BOOLEAN := false;
  v_membership_tier TEXT := NULL;
  v_registration_status TEXT := NULL;
  v_has_completed_questionnaire BOOLEAN := false;
  v_study_name TEXT := NULL;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'access_level', 'none',
      'can_chat', false,
      'block_reason', 'not_authenticated',
      'has_terms_consent', false
    );
  END IF;

  -- IDOR guard: the subject is always the caller. A cross-user lookup
  -- (p_user_id for a different user) is only honored for service role or admin/staff.
  IF p_user_id IS NOT NULL AND p_user_id <> v_user_id THEN
    IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
      RAISE EXCEPTION 'Not authorized to read chat access for another user'
        USING ERRCODE = '42501';
    END IF;
    v_user_id := p_user_id;
  END IF;

  -- Legal gate: user must have active data processing consent (acts as terms acceptance).
  SELECT EXISTS (
    SELECT 1
    FROM public.consents c
    WHERE c.user_id = v_user_id
      AND c.consent_type = 'data_processing'::public.consent_type
      AND c.granted = true
      AND c.revoked_at IS NULL
  ) INTO v_has_terms_consent;
  
  -- Check for active study registration
  SELECT 
    se.status,
    s.name
  INTO v_registration_status, v_study_name
  FROM public.study_registrations se
  JOIN public.studies s ON s.id = se.study_id
  WHERE se.user_id = v_user_id
  AND se.status IN ('active', 'enrolled', 'completed', 'screening', 'pending')
  ORDER BY 
    CASE se.status 
      WHEN 'active' THEN 1 
      WHEN 'enrolled' THEN 2 
      WHEN 'completed' THEN 3
      WHEN 'screening' THEN 4
      WHEN 'pending' THEN 5
    END
  LIMIT 1;
  
  -- Determine registration state
  v_has_registration := v_registration_status IN ('active', 'enrolled', 'completed');
  v_has_pending_registration := v_registration_status IN ('screening', 'pending');
  
  -- Check if user has completed onboarding questionnaire
  SELECT EXISTS (
    SELECT 1 FROM public.operational_assessments ca
    WHERE ca.user_id = v_user_id
    AND ca.assessment_type = 'onboarding'
    AND ca.status = 'completed'
  ) INTO v_has_completed_questionnaire;
  
  -- Check membership
  SELECT m.tier, m.status = 'active'
  INTO v_membership_tier, v_has_active_membership
  FROM public.memberships m
  WHERE m.user_id = v_user_id
  ORDER BY m.created_at DESC
  LIMIT 1;
  
  -- Determine access level with legal gate first.
  IF NOT v_has_terms_consent THEN
    v_access_level := 'basic';
    v_can_chat := false;
    v_block_reason := 'terms_not_accepted';
  ELSIF v_has_active_membership AND v_membership_tier = 'upgraded' THEN
    -- 'upgraded' is the paid tier (membership_tier: basic|upgraded|trial). The prior
    -- 'premium' literal was outside the enum, so this branch was dead.
    v_access_level := 'premium';
    v_can_chat := true;
  ELSIF v_has_active_membership THEN
    v_access_level := 'active';
    v_can_chat := true;
  ELSIF v_has_registration THEN
    v_access_level := 'enrolled';
    v_can_chat := true;
  ELSIF v_has_pending_registration THEN
    -- Registered user can still use chat after accepting terms.
    v_access_level := 'pending_approval';
    v_can_chat := true;
    v_block_reason := NULL;
  ELSIF NOT v_has_completed_questionnaire THEN
    -- Registered user can still use basic chat after accepting terms.
    v_access_level := 'needs_questionnaire';
    v_can_chat := true;
    v_block_reason := NULL;
  ELSE
    -- Registered user with terms accepted.
    v_access_level := 'basic';
    v_can_chat := true;
    v_block_reason := NULL;
  END IF;
  
  RETURN jsonb_build_object(
    'access_level', v_access_level,
    'can_chat', v_can_chat,
    'block_reason', v_block_reason,
    'has_terms_consent', v_has_terms_consent,
    'has_registration', v_has_registration,
    'has_pending_registration', v_has_pending_registration,
    'has_membership', v_has_active_membership,
    'membership_tier', v_membership_tier,
    'registration_status', v_registration_status,
    'study_name', v_study_name,
    'has_completed_questionnaire', v_has_completed_questionnaire
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.get_chat_access_level(p_user_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_chat_access_level(p_user_id uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_chat_message_by_id.sql
-- -----------------------------------------------------------------------------

-- Function: get_chat_message_by_id
-- Zpráva chatu podle id pro hodnocení kvality (svc-ai-chat routes/evaluate.ts, jen služba).
--
-- Vznik 2026-09-29 (SELF_IMPROVEMENT_LOOP.md §3, K-17): evaluate.ts ji volal od začátku,
-- ale SoT neexistoval (brána rpc-sql-mapping ji vedla jako V2_PENDING) → každé hodnocení
-- odpovědi z chatu padlo dřív, než se soudce vůbec zeptal. chat_messages čte přes RLS jen
-- správce, služba potřebuje definer čtečku; vrací jen pole, která hodnocení čte.
-- Vrací objekt, nebo NULL, když zpráva neexistuje (route z toho dělá 404).

CREATE OR REPLACE FUNCTION public.get_chat_message_by_id(p_message_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  RETURN (
    SELECT jsonb_build_object(
      'id', cm.id,
      'content', cm.content,
      'role', cm.role,
      'conversation_id', cm.conversation_id
    )
    FROM public.chat_messages cm
    WHERE cm.id = p_message_id
  );
END;
$$;

COMMENT ON FUNCTION public.get_chat_message_by_id(uuid) IS
  'Zpráva chatu (id, content, role, conversation_id) pro hodnocení kvality; jen služba. NULL = neexistuje.';

REVOKE ALL ON FUNCTION public.get_chat_message_by_id(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_chat_message_by_id(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_data_source_secret_status.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_data_source_secret_status
-- Popis: Co zdroj pro připojení POTŘEBUJE a co z toho je vyplněné.
--
-- ⭐ SEZNAM SE NEPÍŠE, ODVOZUJE SE. Povinná pověření vycházejí z pluginu:
-- `config_schema.required` průnik s poli, která mají `secret: true`. Kdyby tu
-- byl ruční výčet, byl by to druhý udržovaný seznam — a rozešel by se stejně
-- tiše jako ten, který má hlídat.
--
-- ⛔ VRACÍ PŘÍTOMNOST, NE HODNOTU. `is_set` vzniká z EXISTS nad šifrovanou
-- tabulkou; nic se nedešifruje, takže tahle cesta neumí tajemství vydat ani
-- omylem.
--
-- Zdroj bez pluginu (`source_plugin_id IS NULL` — např. `money`, `local-ingest`)
-- nemá schéma, ze kterého by se dalo odvozovat. Vrací tedy prázdný seznam:
-- „nic se nevyžaduje", ne „nevím".
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_data_source_secret_status(p_source_slug text)
RETURNS TABLE (
  secret_key  text,
  is_required boolean,
  is_set      boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_source_id uuid;
  v_schema    jsonb;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT s.id, pc.config_schema
    INTO v_source_id, v_schema
    FROM public.agent_knowledge_sources s
    LEFT JOIN public.plugin_catalog pc ON pc.id = s.source_plugin_id
   WHERE s.source_slug = p_source_slug;

  IF v_source_id IS NULL THEN
    RAISE EXCEPTION 'get_data_source_secret_status: zdroj % neexistuje', p_source_slug;
  END IF;

  RETURN QUERY
  WITH pozadovane AS (
    SELECT r.k AS klic
      FROM jsonb_array_elements_text(coalesce(v_schema->'required', '[]'::jsonb)) AS r(k)
     WHERE coalesce((v_schema->'properties'->r.k->>'secret')::boolean, false)
  ),
  ulozene AS (
    SELECT sec.secret_key AS klic
      FROM public.agent_knowledge_source_secrets sec
     WHERE sec.source_id = v_source_id
  )
  SELECT k.klic,
         (k.klic IN (SELECT klic FROM pozadovane)),
         (k.klic IN (SELECT klic FROM ulozene))
    FROM (SELECT klic FROM pozadovane UNION SELECT klic FROM ulozene) AS k
   ORDER BY 1;
END;
$$;

COMMENT ON FUNCTION public.get_data_source_secret_status(text) IS
  'Která pověření zdroj vyžaduje (odvozeno z config_schema pluginu: required ∩ secret) a která jsou uložená. Vrací PŘÍTOMNOST, nikdy hodnotu. Admin/staff nebo service_role.';

REVOKE ALL ON FUNCTION public.get_data_source_secret_status(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_data_source_secret_status(text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_decisions_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_decisions_admin
-- Popis: Přehled ROZHODNUTÍ napříč oblastmi (proces, doprava balíčků, …) — kdo,
--        kdy, proč, kolik, a jestli už bylo vráceno. Podklad obrazovky správce
--        „Rozhodnutí a automatika": dohledat → vrátit.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (admin/staff nebo service_role)
--
-- ⭐ ZADÁNÍ MAJITELE 2026-09-15: autonomní i hromadné kroky musí jít dohledat
--    a z UI vrátit. Rozhodnutí žije v audit_journal (neměnný deník).
--
-- ⛔ JEDEN ČTENÁŘ PRO VŠECHNY DRUHY. Do 2026-09-16 uměl přehled jen rozhodnutí
--    nad procesem, takže zahození karantény brokeru by v UI nebylo vidět a vzniklo
--    by druhé okno do téhož deníku. Druh se FILTRUJE parametrem; sourozenec
--    `get_workflow_decisions_admin` je tenká obálka nad tímhle (jedna implementace,
--    žádný rozchod dvou čteček).
--
-- ⭐ VRÁCENÍ SE POZNÁ KONVENCÍ JMÉNA AKCE (obsahuje `revert`), ne výčtem typů:
--    výčet by byl druhý domov pravdy a při třetím druhu rozhodnutí by se rozešel.
--
-- ⛔ SEZNAM ZÁZNAMŮ SE NEVRACÍ (stovky UUID / id balíčků) — ten patří vrácení,
--    které ho čte z rozhodnutí. Přehled nese jen počty.
--
-- Kontrakt: (integer, text) -> jsonb {items:[{decision_id, druh, oblast, akce, kdy,
--   kdo, souhrn, duvod, kriterium, pocty, vratne, vraceno:{kdy,kdo,obnoveno,duvod}|null}]}
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_decisions_admin(
  p_limit integer DEFAULT 50,
  p_druh  text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_items jsonb;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff(auth.uid())) THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff or service_role required';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY x->>'kdy' DESC), '[]'::jsonb) INTO v_items
  FROM (
    SELECT jsonb_build_object(
             'decision_id', d.id,
             'druh', d.entity_type,
             'oblast', d.area,
             'akce', d.action,
             'kdy', d.created_at,
             'kdo', d.user_id,
             'souhrn', d.summary,
             'duvod', d.details->>'duvod',
             'kriterium', d.details->'kriterium',
             -- Starší rozhodnutí nesou počty jako samostatné klíče; novější mají
             -- `pocty`. Čtenář obojí sjednotí, aby se historie nemusela přepisovat.
             'pocty', coalesce(d.details->'pocty',
                               jsonb_strip_nulls(jsonb_build_object(
                                 'behu', d.details->'behu', 'uzlu', d.details->'uzlu',
                                 'taktu', d.details->'taktu'))),
             'vratne', coalesce((d.details->>'vratne')::boolean, false) AND r.id IS NULL,
             'vraceno', CASE WHEN r.id IS NULL THEN NULL
                        ELSE jsonb_build_object('kdy', r.created_at, 'kdo', r.user_id,
                                                'obnoveno', r.details->'obnoveno',
                                                'duvod', r.details->>'duvod') END
           ) AS x
      FROM public.audit_journal d
      LEFT JOIN public.audit_journal r
             ON r.entity_id = d.id::text AND r.action LIKE '%revert%'
     WHERE d.entity_type LIKE '%_decision'
       AND (p_druh IS NULL OR d.entity_type = p_druh)
       -- Vrácení je také řádek deníku, ale není to rozhodnutí k vrácení.
       AND d.action NOT LIKE '%revert%'
     ORDER BY d.created_at DESC
     LIMIT GREATEST(1, LEAST(coalesce(p_limit, 50), 500))
  ) s;

  RETURN jsonb_build_object('items', v_items);
END;
$function$;

REVOKE ALL ON FUNCTION public.get_decisions_admin(integer, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_decisions_admin(integer, text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_document_download_info_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_document_download_info_audited
-- Popis: Vydá informaci pro stažení binárky dokladu (bucket + content-addressed
--        klíč <sha256>.pdf). Uživatel se k objektu ve storage nikdy nedostává
--        přímo — tohle RPC je jediná cesta a každé vydání se audituje (kdo se
--        díval, je součást příběhu).
--        Bucket je DATA řádku (li_source_registry.storage_bucket, píše ingest)
--        — žádná instanční konstanta v kódu; chybějící bucket = jasná chyba.
-- Autorizace: service/admin vše; člen přes document_visible_to (třída
--        promovaného dokladu × spočtená úroveň tazatele; nepromovaný doklad
--        fail-closed). Jediný vlastník pravidla = document_visible_to.
-- Záchrana: regenerát z nasazené DB 2026-07-25 (live-only drift, task #16)
--        + odstraněn zadrátovaný bucket + zapojen sdílený predikát.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_document_download_info_audited(p_doc_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_doc record;
  v_uid uuid := auth.uid();
BEGIN
  SELECT id, source_sha256, filename, doc_type, story_id, storage_bucket
    INTO v_doc
    FROM li_source_registry
   WHERE id = p_doc_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Dokument nenalezen' USING errcode = 'P0002';
  END IF;

  IF NOT (public.is_service_role()
          OR public.is_admin_or_staff()
          OR public.document_visible_to(v_uid, v_doc.source_sha256)) THEN
    RAISE EXCEPTION 'Nemáte oprávnění k tomuto dokumentu' USING errcode = '42501';
  END IF;

  IF v_doc.storage_bucket IS NULL THEN
    RAISE EXCEPTION 'Doklad % nemá uloženou binárku (storage_bucket je NULL)', p_doc_id
      USING errcode = 'P0002';
  END IF;

  INSERT INTO audit_journal(user_id, action, metadata)
  VALUES (v_uid, 'DOCUMENT_DOWNLOAD',
          jsonb_build_object('doc_id', p_doc_id, 'filename', v_doc.filename,
                             'sha', v_doc.source_sha256));

  RETURN jsonb_build_object(
    'doc_id', v_doc.id, 'filename', v_doc.filename, 'doc_type', v_doc.doc_type,
    'storage_bucket', v_doc.storage_bucket,
    'storage_key', v_doc.source_sha256 || '.pdf',
    'provenance', jsonb_build_object('source_slug', 'li-source-registry',
                                     'trace_id', 'doc:download'));
END;
$$;

REVOKE ALL ON FUNCTION public.get_document_download_info_audited(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_document_download_info_audited(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_document_download_info_audited(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_ingest_karantena.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_ingest_karantena
-- Blok povrchu: balíčky, které li-driver ODLOŽIL a čekají na rozhodnutí člověka.
--
-- PROČ TO MÁ BÝT VIDĚT: karanténa vznikla proto, že nezpracovatelný balíček
-- nesmí zastavit frontu. Jenže odložený balíček, o kterém nikdo neví, je jen
-- tišší podoba téhož problému — fronta jede, ale rozhodnutí nikdo neudělá,
-- protože ho nevidí. Naměřeno 2026-08-30: jeden balíček blokoval pět dalších
-- a poznalo se to jen z logu kontejneru.
--
-- Zdrojem je stav driveru (`audience_broker_sync_state.metadata->'karantena'`),
-- ne odvozenina — jediné místo, kde je pravda o tom, co driver odložil.
create or replace function public.get_ingest_karantena(p_params jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
stable
security definer
SET search_path TO 'public', 'pg_temp'
as $$
declare
  v_rows jsonb;
  -- ⭐ SLOUPCE JSOU VEŘEJNÉ, OBSAH NE. Fail-closed větev vracela `columns: []`
  -- a maska `table` takový tvar ODMÍTNE (minItems 1) — povrch by odpověď zahodil
  -- a napsal „Zatím není co zobrazit". Odepřený přístup by vypadal jako prázdná
  -- data. Hlavičky proto jdou ven vždy; řádky jen tomu, kdo má nárok.
  v_cols jsonb := jsonb_build_array(
        jsonb_build_object('key','balicek','label_key','app.cols.bundle'),
        jsonb_build_object('key','zdroj',  'label_key','app.cols.source'),
        jsonb_build_object('key','stav',   'label_key','app.cols.state'),
        jsonb_build_object('key','od',     'label_key','app.cols.started'));
  v_prov jsonb := jsonb_build_object(
    'source_slug', 'audience_broker_sync_state',
    'trace_id', 'ingest:karantena',
    'freshness_at', now());
begin
  -- ⛔ NÁROK, ne přihlášení. Funkce běží pod právy vlastníka, takže RLS na ni
  -- NEPLATÍ — kdyby stačilo „je někdo přihlášen", přečetl by registr zdrojů
  -- i řidič. `audience` v rozložení řídí UMÍSTĚNÍ bloku, ne přístup k datům;
  -- ta obrana musí být tady.
  --
  -- PRÁZDNO, ne chyba: kdo nemá nárok, se nemá dozvědět ani to, že se ptal.
  if not (public.is_service_role() or public.is_admin_or_staff()) then
    return jsonb_build_object(
      'data', jsonb_build_object('columns', v_cols, 'rows', '[]'::jsonb),
      'provenance', v_prov);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id',        b.export_id,
           'balicek',   b.export_id,
           'zdroj',     s.source_slug,
           'stav',      case when s.source_slug is null then 'zdroj neznámý'
                             when s.is_active then 'zdroj aktivní — projde příště'
                             else 'čeká na klasifikaci' end,
           'od',        to_char(s.created_at, 'YYYY-MM-DD HH24:MI')
         ) order by b.export_id), '[]'::jsonb)
    into v_rows
  from public.audience_broker_sync_state st
  cross join lateral jsonb_array_elements_text(
         coalesce(st.metadata->'karantena', '[]'::jsonb)) as b(export_id)
  -- Zdroj se k balíčku váže jen VOLNĚ: karanténa nese id balíčku, ne slug.
  -- Návrh zdroje (proposed_by='ingest') je nejpravděpodobnější důvod odložení.
  left join public.agent_knowledge_sources s
         on s.config->>'proposed_by' = 'ingest'
  where st.source_slug = 'local-ingest';

  return jsonb_build_object(
    'data', jsonb_build_object(
      'columns', v_cols,
      'rows', v_rows,
      'row_kind', 'ingest_bundle'),
    'provenance', v_prov);
end $$;

REVOKE ALL ON FUNCTION public.get_ingest_karantena(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_ingest_karantena(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_ingest_karantena(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_ingest_zdroje.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_ingest_zdroje
-- Blok povrchu: registr zdrojů ingestu — co je aktivní, co čeká na klasifikaci.
--
-- PROČ: zdroj musí být registrovaný a AKTIVNÍ, jinak obsah nemá kontext a
-- KB pruh fail-closed padá. Do 2026-08-30 se to dalo zjistit jedině dotazem
-- do databáze; operátor tedy nevěděl, že se někde hlásí zdroj čekající na
-- rozhodnutí. Tenhle blok dělá ten stav viditelným.
--
-- ⛔ POVĚŘENÍ SE NEVYDÁVÁ, ANI ČÁSTEČNĚ. Vydává se jen ANO/NE, jestli je
-- odkaz na tajemství nastavený. Povrch je čtený lidmi i klienty v šesti
-- jazycích; hodnota tajemství tam nemá co dělat v žádné podobě — ani
-- zkrácená, ani maskovaná (maskovaná hodnota pořád prozrazuje délku a tvar).
create or replace function public.get_ingest_zdroje(p_params jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
stable
security definer
SET search_path TO 'public', 'pg_temp'
as $$
declare
  v_rows jsonb;
  -- ⭐ SLOUPCE JSOU VEŘEJNÉ, OBSAH NE. Fail-closed větev vracela `columns: []`
  -- a maska `table` takový tvar ODMÍTNE (minItems 1) — povrch by odpověď zahodil
  -- a napsal „Zatím není co zobrazit". Odepřený přístup by vypadal jako prázdná
  -- data. Hlavičky proto jdou ven vždy; řádky jen tomu, kdo má nárok.
  v_cols jsonb := jsonb_build_array(
        jsonb_build_object('key','zdroj',      'label_key','app.cols.source'),
        jsonb_build_object('key','stav',       'label_key','app.cols.state'),
        jsonb_build_object('key','klasifikace','label_key','app.cols.classification','align','center'),
        jsonb_build_object('key','citlivost',  'label_key','app.cols.sensitivity'),
        jsonb_build_object('key','povereni',   'label_key','app.cols.credentials'),
        jsonb_build_object('key','story',      'label_key','app.cols.story','align','center'),
        jsonb_build_object('key','namespace',  'label_key','app.cols.namespace'));
  v_prov jsonb := jsonb_build_object(
    'source_slug', 'agent_knowledge_sources',
    'trace_id', 'ingest:zdroje',
    'freshness_at', now());
begin
  -- ⛔ NÁROK, ne přihlášení. Funkce běží pod právy vlastníka, takže RLS na ni
  -- NEPLATÍ — kdyby stačilo „je někdo přihlášen", přečetl by registr zdrojů
  -- i řidič. `audience` v rozložení řídí UMÍSTĚNÍ bloku, ne přístup k datům;
  -- ta obrana musí být tady.
  --
  -- PRÁZDNO, ne chyba: kdo nemá nárok, se nemá dozvědět ani to, že se ptal.
  if not (public.is_service_role() or public.is_admin_or_staff()) then
    return jsonb_build_object(
      'data', jsonb_build_object('columns', v_cols, 'rows', '[]'::jsonb),
      'provenance', v_prov);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id',      s.id::text,
           'zdroj',   s.source_slug,
           'stav',    case when s.is_active then 'aktivní'
                           when s.config->>'proposed_by' is not null then 'návrh z ingestu'
                           else 'neaktivní' end,
           'namespace', s.namespace,
           -- Klasifikace jako POČET z pěti: aktivovat jde jen s úplnou, takže
           -- „4/5" je přesně ta informace, kvůli které zdroj nejde spustit.
           -- Klíče = závora agent_knowledge_sources_activation_guard (kontrakt
           -- §1 + vlastník §3); musí s ní souhlasit, jinak výpis hlásí úplnou
           -- klasifikaci zdroji, který závora nepustí (2026-09-24).
           'klasifikace', (
              (case when s.config ? 'source_type'      then 1 else 0 end)
            + (case when s.config ? 'data_sensitivity' then 1 else 0 end)
            + (case when s.config ? 'retention_class'  then 1 else 0 end)
            + (case when s.config ? 'legal_basis'      then 1 else 0 end)
            + (case when s.config ? 'owner'            then 1 else 0 end))::text || '/5',
           'citlivost', coalesce(s.config->>'data_sensitivity', '—'),
           -- ⛔ Jen PŘÍTOMNOST odkazu, nikdy hodnota.
           'povereni', case when s.config ? 'secret_ref' or s.config ? 'credentials_ref'
                            then 'nastaveno' else '—' end,
           'story',   case when s.story_id is null then '—' else 'ano' end
         ) order by s.is_active desc, s.source_slug), '[]'::jsonb)
    into v_rows
  from public.agent_knowledge_sources s;

  return jsonb_build_object(
    'data', jsonb_build_object(
      'columns', v_cols,
      'rows', v_rows,
      'row_kind', 'ingest_source'),
    'provenance', v_prov);
end $$;

REVOKE ALL ON FUNCTION public.get_ingest_zdroje(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_ingest_zdroje(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_ingest_zdroje(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_last_dashboard_hash.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_last_dashboard_hash
-- Popis: Returns hash z posledního "published" rendering (skip-if-unchanged check).
--        Pokud žádný úspěšný render neexistuje, vrátí NULL (forces first import).
-- Volá: WF_APPSMITH_DASHBOARD_BUILDER před content hash compare
-- Auth: admin/staff nebo service_role
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_last_dashboard_hash(
  p_dashboard_slug text DEFAULT 'aisha-ops'
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_hash text;
BEGIN
  IF NOT public.is_admin_or_staff()
     AND NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT content_hash INTO v_hash
  FROM public.dashboard_render_history
  WHERE dashboard_slug = p_dashboard_slug
    AND publish_status IN ('published', 'skipped_no_change')
  ORDER BY rendered_at DESC
  LIMIT 1;

  RETURN v_hash;  -- NULL pokud first run
END;
$$;

REVOKE ALL ON FUNCTION public.get_last_dashboard_hash(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_last_dashboard_hash(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_last_dashboard_hash(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_latest_drift_state.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_latest_drift_state
-- Popis: Read-only query pro Phase 4 dashboard. Vrací poslední N drift záznamů
--        s age_minutes (kolik minut starý). Volitelně filtrovat jen unresolved.
-- Volá: dashboard widgets (Recent Drift table, drill-down panels)
-- Auth: admin/staff (read-only) nebo service_role
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_latest_drift_state(
  p_limit        int     DEFAULT 50,
  p_only_unresolved boolean DEFAULT true
)
RETURNS TABLE (
  id              uuid,
  observed_at     timestamptz,
  app_uuid        text,
  app_name        text,
  drift_kind      text,
  risk_level      text,
  remediation     text,
  observation_count int,
  resolved_at     timestamptz,
  resolution_note text,
  age_minutes     int
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF NOT public.is_admin_or_staff()
     AND NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  RETURN QUERY
  SELECT
    ds.id, ds.observed_at, ds.app_uuid, ds.app_name, ds.drift_kind,
    ds.risk_level, ds.remediation, ds.observation_count,
    ds.resolved_at, ds.resolution_note,
    EXTRACT(EPOCH FROM (now() - ds.observed_at))::int / 60 AS age_minutes
  FROM public.drift_state ds
  WHERE (p_only_unresolved IS FALSE OR ds.resolved_at IS NULL)
  ORDER BY ds.observed_at DESC
  LIMIT GREATEST(p_limit, 1);
END;
$$;

REVOKE ALL ON FUNCTION public.get_latest_drift_state(int, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_latest_drift_state(int, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_latest_drift_state(int, boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_meter_balance_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_meter_balance_block
-- Popis: 'table' blok — BILANCE hlavního měřidla proti součtu podružných po
--        obdobích: sedí spotřeba na podružných měřidlech s tím, co naměřilo
--        (a vyfakturovalo) hlavní? Majitel 2026-09-28: „chceme vidět, zda součty
--        na podružných měřidlech odpovídají hlavnímu měřidlu".
--
-- Rozsah = JEDNO hlavní měřidlo (p_params->>'twin_id' z detail_by_kind), jako
-- karta dvojčete: blok o jednom záznamu nesmí číst svět.
--
-- Konfigurace (source_params bloku — slovník je instanční, ne platformní):
--   relation_kind      POVINNÉ  druh hrany podružné —kind→ hlavní (např. submeter_of)
--   consumption_event  POVINNÉ  event_type spotřeby HLAVNÍHO měřidla za období
--                              (attrs {period 'YYYY-MM', value, unit})
--   multiplier_path    volitelné cesta k násobiteli v metadatech podružného
--                              (např. ["energie","nasobitel"]); bez ní 1
--   residual_path      volitelné cesta k seznamu dopočtových řádků v metadatech
--                              hlavního (neprázdný = rozdíl vychází nulový Z PRINCIPU)
--
-- ⭐ PODRUŽNÁ JEN PŘES POTVRZENÉ HRANY (twin_relations). Návrh vazby, o kterém
-- ještě nikdo nerozhodl, do bilance nevstupuje — jinak by bilance tvrdila
-- strukturu, kterou člověk neschválil. Hrana musí platit v daném období.
--
-- ⭐ SPOTŘEBA SE POČÍTÁ Z ODEČTŮ (event_type 'meter_reading', tatáž veličina jako
-- terénní odečet): konec období − počátek období, kde počátek je výslovný
-- odečet 'pocatek' (výměna měřidla, první měsíc), jinak konec předchozího
-- období; krát násobitel. Odečet bez `period` do bilance nevstupuje — neví se,
-- kam patří (hlásí se jako chybějící, ne jako nula).
--
-- STAV řádku (klíč app.meters.balance.state.*, sloupec value_keys) říká, JAK
-- rozdíl číst — bilance bez něj svádí k závěru i tam, kde žádný není:
--   no_submeters     pod měřidlem není potvrzené podružné
--   no_main          hlavní za období nemá spotřebu
--   unit_mismatch    jednotky hlavního a podružných se liší (nepřepočítává se)
--   missing_readings některému podružnému chybí odečet → součet je neúplný
--   residual         hlavní má dopočtový řádek → rozdíl je nulový z principu
--   measured         změřená bilance
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_meter_balance_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
-- INVOKER: dvojčata, hrany i události čte RLS (admin/staff), jako karta dvojčete.
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  with cfg as (
    select case
             when coalesce(p_params->>'twin_id', '')
                  ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             then (p_params->>'twin_id')::uuid
           end                                              as twin,
           nullif(p_params->>'relation_kind', '')           as kind,
           nullif(p_params->>'consumption_event', '')       as cons_ev,
           coalesce(array(select jsonb_array_elements_text(
             case when jsonb_typeof(p_params->'multiplier_path') = 'array'
                  then p_params->'multiplier_path' else '[]'::jsonb end)), '{}'::text[]) as mult_path,
           coalesce(array(select jsonb_array_elements_text(
             case when jsonb_typeof(p_params->'residual_path') = 'array'
                  then p_params->'residual_path' else '[]'::jsonb end)), '{}'::text[]) as resid_path
  ),
  sloupce as (
    select jsonb_build_array(
      jsonb_build_object('key', 'obdobi',     'label_key', 'app.meters.balance.col.period'),
      jsonb_build_object('key', 'jednotka',   'label_key', 'app.meters.balance.col.unit'),
      jsonb_build_object('key', 'hlavni',     'label_key', 'app.meters.balance.col.main', 'align', 'right'),
      jsonb_build_object('key', 'podruzne',   'label_key', 'app.meters.balance.col.submeters', 'align', 'right'),
      jsonb_build_object('key', 'rozdil',     'label_key', 'app.meters.balance.col.difference', 'align', 'right'),
      jsonb_build_object('key', 'rozdil_pct', 'label_key', 'app.meters.balance.col.difference_pct', 'align', 'right'),
      jsonb_build_object('key', 'chybi',      'label_key', 'app.meters.balance.col.missing', 'align', 'right'),
      jsonb_build_object('key', 'stav',       'label_key', 'app.meters.balance.col.state', 'value_keys', true)
    ) as c
  ),
  hlavni as (
    select t.id, t.metadata from twin_entities t, cfg where t.id = cfg.twin
  ),
  dopocet as (
    select coalesce(jsonb_typeof(h.metadata #> (select resid_path from cfg)) = 'array'
                    and jsonb_array_length(h.metadata #> (select resid_path from cfg)) > 0, false) as ano
      from hlavni h
     where cardinality((select resid_path from cfg)) > 0
  ),
  podruzna as (
    select r.source_twin_id as id, r.valid_from, r.valid_to,
           coalesce(nullif(s.metadata #>> (select mult_path from cfg), '')::numeric, 1) as nas
      from twin_relations r
      join twin_entities s on s.id = r.source_twin_id
      join cfg on r.target_twin_id = cfg.twin and r.relation_kind = cfg.kind
  ),
  -- Jeden odečet na (měřidlo, období, druh): při souběhu platí poslední pořízený.
  odecty as (
    select distinct on (e.twin_id, e.attrs->>'period', e.attrs->>'kind')
           e.twin_id, e.attrs->>'period' as per, e.attrs->>'kind' as druh,
           (e.attrs->>'value')::numeric as v, e.attrs->>'unit' as j, e.occurred_at
      from twin_events e
      join podruzna p on p.id = e.twin_id
     where e.event_type = 'meter_reading'
       and e.attrs->>'period' ~ '^\d{4}-\d{2}$'
       and jsonb_typeof(e.attrs->'value') = 'number'
     order by e.twin_id, e.attrs->>'period', e.attrs->>'kind', e.occurred_at desc, e.id
  ),
  spotreba_hl as (
    select e.attrs->>'period' as per, sum((e.attrs->>'value')::numeric) as v,
           min(e.attrs->>'unit') as j, count(distinct e.attrs->>'unit') as jednotek,
           max(e.occurred_at) as fresh
      from twin_events e, cfg
     where e.twin_id = cfg.twin and e.event_type = cfg.cons_ev
       and e.attrs->>'period' ~ '^\d{4}-\d{2}$'
       and jsonb_typeof(e.attrs->'value') = 'number'
     group by e.attrs->>'period'
  ),
  obdobi as (
    select per from odecty where druh = 'konec'
    union
    select per from spotreba_hl
  ),
  spotreba_pod as (
    select o.per, p.id,
           (k.v - coalesce(z.v, pk.v)) * p.nas as sp,
           coalesce(k.j, z.j) as j
      from obdobi o
      cross join podruzna p
      left join odecty k  on k.twin_id = p.id and k.per = o.per and k.druh = 'konec'
      left join odecty z  on z.twin_id = p.id and z.per = o.per and z.druh = 'pocatek'
      left join odecty pk on pk.twin_id = p.id and pk.druh = 'konec'
                         and pk.per = to_char(to_date(o.per, 'YYYY-MM') - interval '1 month', 'YYYY-MM')
     -- hrana musí platit v období (osa B: příslušnost k datu)
     where p.valid_from < (to_date(o.per, 'YYYY-MM') + interval '1 month')
       and (p.valid_to is null or p.valid_to > to_date(o.per, 'YYYY-MM'))
  ),
  bilance as (
    select o.per,
           h.v as hlavni, h.j as j_hl, h.jednotek as jednotek_hl,
           (select sum(s.sp) from spotreba_pod s where s.per = o.per) as podruzne,
           (select count(*) from spotreba_pod s where s.per = o.per) as podruznych,
           (select count(*) from spotreba_pod s where s.per = o.per and s.sp is null) as chybi,
           (select count(distinct s.j) from spotreba_pod s where s.per = o.per and s.j is not null) as jednotek_pod,
           (select min(s.j) from spotreba_pod s where s.per = o.per) as j_pod
      from obdobi o
      left join spotreba_hl h on h.per = o.per
  ),
  -- Čerstvost = nejnovější odečet nebo spotřeba, ze kterých bilance vznikla
  -- (brána cerstvost-z-dat): čas zavolání funkce by o stáří dat lhal.
  cerstvost as (
    select greatest((select max(occurred_at) from odecty), (select max(fresh) from spotreba_hl)) as fresh
  ),
  radky as (
    select b.per,
           jsonb_build_object(
             'id',         b.per,
             'obdobi',     b.per,
             'jednotka',   coalesce(b.j_hl, b.j_pod),
             'hlavni',     round(b.hlavni, 3),
             'podruzne',   round(b.podruzne, 3),
             'rozdil',     round(b.hlavni - b.podruzne, 3),
             'rozdil_pct', case when b.hlavni is not null and b.hlavni <> 0 and b.podruzne is not null
                                then round(100 * (b.hlavni - b.podruzne) / b.hlavni, 1) end,
             'chybi',      b.chybi,
             'stav', 'app.meters.balance.state.' || case
                when b.podruznych = 0                                        then 'no_submeters'
                when b.hlavni is null                                        then 'no_main'
                when b.jednotek_hl > 1 or b.jednotek_pod > 1
                  or b.j_hl is distinct from b.j_pod                         then 'unit_mismatch'
                when b.chybi > 0                                             then 'missing_readings'
                when coalesce((select ano from dopocet), false)              then 'residual'
                else 'measured' end
           ) as r
      from bilance b
  )
  select case
    -- Bez nároku nebo bez konfigurace: platná prázdná tabulka (maska table
    -- prázdno připouští — „nic tu není" je poctivější než vymyšlená hlavička).
    -- Odmítací větve žádná data nemají, důvod nese literál v trace_id.
    when not (public.is_admin_or_staff() or public.is_service_role())
    then jsonb_build_object(
      'data', jsonb_build_object('columns', '[]'::jsonb, 'rows', '[]'::jsonb),
      'provenance', jsonb_build_object('source_slug', 'meter-balance',
        'trace_id', 'meter-balance:unauthorized', 'freshness_at', now()))
    when (select twin from cfg) is null
      or (select kind from cfg) is null
      or (select cons_ev from cfg) is null
    then jsonb_build_object(
      'data', jsonb_build_object('columns', '[]'::jsonb, 'rows', '[]'::jsonb),
      'provenance', jsonb_build_object('source_slug', 'meter-balance',
        'trace_id', 'meter-balance:missing_config', 'freshness_at', now()))
    else jsonb_build_object(
      'data', jsonb_build_object(
        'columns', (select c from sloupce),
        'rows', coalesce((select jsonb_agg(r order by per desc) from radky), '[]'::jsonb),
        'row_kind', 'meter_period'),
      'provenance', jsonb_build_object('source_slug', 'meter-balance',
        'trace_id', 'meter-balance:' || (select twin from cfg)::text
                    || case when (select fresh from cerstvost) is null then ':no_data' else '' end,
        'freshness_at', coalesce((select fresh from cerstvost), now())))
  end;
$$;

REVOKE ALL ON FUNCTION public.get_meter_balance_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_meter_balance_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_meter_balance_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_next_playwright_run.sql
-- -----------------------------------------------------------------------------

-- get_next_playwright_run
-- Runner container polls this — returns at most one queued run that is
-- either auto-trigger OR has been approved. Service-role only.

CREATE OR REPLACE FUNCTION public.get_next_playwright_run()
RETURNS TABLE (
  id uuid,
  trigger_kind public.playwright_run_trigger,
  target_env text,
  target_base_url text,
  suite text,
  deploy_ref text,
  metadata jsonb,
  created_at timestamptz
)
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service THEN
    RAISE EXCEPTION 'Unauthorized: service_role required';
  END IF;

  RETURN QUERY
  SELECT pr.id, pr.trigger_kind, pr.target_env, pr.target_base_url, pr.suite,
         pr.deploy_ref, pr.metadata, pr.created_at
  FROM public.playwright_runs pr
  WHERE pr.status = 'queued'
    AND (pr.approval_required = false OR pr.approved_at IS NOT NULL)
  ORDER BY pr.created_at ASC
  LIMIT 1;
END;
$$;

REVOKE ALL ON FUNCTION public.get_next_playwright_run() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_next_playwright_run() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_pending_tooling_proposals.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_pending_tooling_proposals
-- Popis: Read-only query pending tooling proposals pro Phase 4 dashboard.
--        Vrací stručný list (id, kind, name, path, occurrence_count, age_minutes,
--        manual_locked, bundle_id) — bez full content (load on-demand).
-- Volá: dashboard "Pending Proposals" widget
-- Auth: admin/staff nebo service_role
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_pending_tooling_proposals(
  p_limit int DEFAULT 50
)
RETURNS TABLE (
  id                uuid,
  proposed_at       timestamptz,
  proposal_kind     text,
  artifact_name     text,
  artifact_path     text,
  occurrence_count  int,
  age_minutes       int,
  manual_locked     boolean,
  proposal_bundle_id uuid
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF NOT public.is_admin_or_staff()
     AND NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  RETURN QUERY
  SELECT
    p.id, p.proposed_at, p.proposal_kind, p.artifact_name, p.artifact_path,
    p.occurrence_count,
    EXTRACT(EPOCH FROM (now() - p.proposed_at))::int / 60 AS age_minutes,
    p.manual_locked,
    p.proposal_bundle_id
  FROM public.aisha_tooling_proposals p
  WHERE p.approval_status = 'pending'
  ORDER BY p.proposed_at DESC
  LIMIT GREATEST(p_limit, 1);
END;
$$;

REVOKE ALL ON FUNCTION public.get_pending_tooling_proposals(int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_pending_tooling_proposals(int) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_pending_tooling_proposals(int) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_plugin_runtime_config.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- get_plugin_runtime_config(p_plugin_slug, p_tenant_id)
--
-- Konfigurace, se kterou plugin POBĚŽÍ (ctx.config) — složená z domovů, kde ji
-- platforma drží, v pořadí od obecného ke konkrétnímu:
--   1. výchozí hodnoty z config_schema.properties.*.default (jen ne-tajné pole),
--   2. source_spec.default_config (konektory),
--   3. konfigurace datového zdroje (set_data_source_config) — zdroj napojený na
--      plugin (agent_knowledge_sources.source_plugin_id),
--   4. pověření zdroje (set_data_source_secrets) — DEŠIFROVANÁ auditovaně,
--   5. přepis tenanta (plugin_tenant_overrides.config_override), pokud ho tenant má.
--
-- ⛔ NAMĚŘENO 2026-09-16: host předával pluginu `ctx.config = {}` (config šel
-- v ENV kontejneru, kam pověření nesmí) a `set_data_source_secrets` nikdo nečetl
-- — konektor tedy neměl endpoint ani pověření a mohl jen selhat.
--
-- Jen služba: volá ji broker hostu (/sandbox/config) pro plugin a tenanta, které
-- nese broker token běhu. Výsledek nese tajemství — nikdy do ENV, nikdy do logu.
-- =============================================================================
CREATE OR REPLACE FUNCTION public.get_plugin_runtime_config(
  p_plugin_slug text,
  p_tenant_id   uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
  v_plugin  public.plugin_catalog%ROWTYPE;
  v_config  jsonb := '{}'::jsonb;
  v_zdroj   public.agent_knowledge_sources%ROWTYPE;
  v_tajne   jsonb;
  v_prepis  jsonb;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'get_plugin_runtime_config: jen služba (broker svc-plugin-system)' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_plugin FROM public.plugin_catalog WHERE slug = p_plugin_slug;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'get_plugin_runtime_config: plugin % neexistuje', p_plugin_slug;
  END IF;

  -- 1. výchozí hodnoty schématu (pole označená secret se z výchozích hodnot neberou)
  SELECT COALESCE(jsonb_object_agg(k, v->'default'), '{}'::jsonb)
    INTO v_config
    FROM jsonb_each(COALESCE(v_plugin.config_schema->'properties', '{}'::jsonb)) AS e(k, v)
   WHERE v ? 'default' AND COALESCE((v->>'secret')::boolean, false) = false;

  -- 2. výchozí konfigurace konektoru
  v_config := v_config || COALESCE(v_plugin.source_spec->'default_config', '{}'::jsonb);

  -- 3. + 4. datový zdroj napojený na plugin
  -- ⚠ Víc zdrojů téhož pluginu (druhá instance konektoru) = dnes první podle vzniku,
  -- deterministicky (dřív LIMIT 1 bez ORDER BY = náhodně cizí pověření). Změřeno
  -- 2026-09-29 riq: plugin:zdroj 1:1. Správně: zdroj z BĚHU (run → source_id) — krok B.
  SELECT * INTO v_zdroj FROM public.agent_knowledge_sources
   WHERE source_plugin_id = v_plugin.id ORDER BY created_at, id LIMIT 1;
  IF FOUND THEN
    v_config := v_config || COALESCE(v_zdroj.config, '{}'::jsonb);
    -- Audit každého dešifrování nese účel, klíč, plugin a zdroj (ne hodnotu) — kdo co četl.
    SELECT COALESCE(jsonb_object_agg(s.secret_key, public.aisha_decrypt_column_audited(s.value_enc, jsonb_build_object(
             'ucel', 'plugin_runtime', 'entita', 'agent_knowledge_source', 'entita_id', v_zdroj.id::text,
             'klic', s.secret_key, 'plugin', p_plugin_slug, 'tenant', p_tenant_id))), '{}'::jsonb)
      INTO v_tajne
      FROM public.agent_knowledge_source_secrets s
     WHERE s.source_id = v_zdroj.id;
    v_config := v_config || v_tajne;
  END IF;

  -- 5. přepis tenanta
  IF p_tenant_id IS NOT NULL THEN
    SELECT config_override INTO v_prepis
      FROM public.plugin_tenant_overrides
     WHERE plugin_id = v_plugin.id AND tenant_id = p_tenant_id;
    v_config := v_config || COALESCE(v_prepis, '{}'::jsonb);
  END IF;

  RETURN v_config;
END;
$$;

COMMENT ON FUNCTION public.get_plugin_runtime_config(text, uuid) IS
  'Konfigurace běhu pluginu (výchozí → zdroj → dešifrovaná pověření → přepis tenanta). Nese tajemství. Jen služba.';

REVOKE ALL ON FUNCTION public.get_plugin_runtime_config(text, uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_plugin_runtime_config(text, uuid) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_plugin_runtime_config(text, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_plugin_sandbox_policy.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- get_plugin_sandbox_policy(p_plugin_slug)
--
-- Kam smí plugin z sandboxu volat — hostitelé (`network_allowlist`) a RPC
-- (`rpc_allowlist`) z jeho SCHVÁLENÉ sandbox politiky (`plugin_catalog.sandbox_policy`,
-- tedy `sandbox` z manifestu).
--
-- ⛔ PROČ (naměřeno 2026-09-26 v produkci instance): broker bral povolené hostitele
-- i RPC z proměnných služby `PLUGIN_NETWORK_ALLOWLIST` / `PLUGIN_RPC_WHITELIST` —
-- a ty byly prázdné. Každý plugin by tak po schválení dostal na první volání
-- dodavatele 403 „No network destinations are allowed" a na první zápis „No RPC
-- functions are allowed". Komentář brokeru přitom tvrdil, že zdrojem je manifest
-- — ten seznam hostitelů nesl, jen ho nikdo nečetl. Seznam, který musí někdo
-- ručně opsat do env každé instance, je třetí domov téže pravdy.
--
-- ⭐ `source_slug` = jméno zdroje ze `source_spec` pluginu. Broker podle něj
-- vynucuje, že plugin zapisuje do OBECNÝCH drah (např. source_catalog_rows přes
-- audience_sync_source_catalog) jen pod SVÝM jménem — argument `p_source_slug`
-- s cizím zdrojem odmítne. Bez toho by plugin se zápisem do katalogu mohl
-- přepsat (snapshot = i smazat) katalog jiného zdroje.
--
-- ⭐ JEN SCHVÁLENÝ PLUGIN. Sandbox politika je součást toho, co člověk schvaluje
-- (`submit_plugin` při její změně vrátí plugin na `submitted`). Plugin mimo
-- `canary`/`ga` dostane PRÁZDNÉ seznamy = žádné volání ven, žádný zápis
-- (default-deny, ne „co si manifest přeje").
--
-- Jen služba: volá ji broker hostu pro plugin, který nese broker token běhu.
-- =============================================================================
CREATE OR REPLACE FUNCTION public.get_plugin_sandbox_policy(p_plugin_slug text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_status public.plugin_status;
  v_policy jsonb;
  v_zdroj  text;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'get_plugin_sandbox_policy: jen služba (broker svc-plugin-system)' USING ERRCODE = '42501';
  END IF;

  SELECT pc.status, COALESCE(pc.sandbox_policy, '{}'::jsonb), NULLIF(pc.source_spec->>'source_slug', '')
    INTO v_status, v_policy, v_zdroj
    FROM public.plugin_catalog pc
   WHERE pc.slug = p_plugin_slug;

  IF NOT FOUND OR v_status NOT IN ('canary'::public.plugin_status, 'ga'::public.plugin_status) THEN
    RETURN jsonb_build_object('schvaleno', false, 'source_slug', NULL,
                              'network_allowlist', '[]'::jsonb, 'rpc_allowlist', '[]'::jsonb);
  END IF;

  -- Jen řetězce: cokoli jiného v seznamu je vada manifestu, ne povolení.
  RETURN jsonb_build_object(
    'schvaleno', true,
    'source_slug', v_zdroj,
    'network_allowlist', COALESCE((SELECT jsonb_agg(h) FROM jsonb_array_elements(
                            CASE WHEN jsonb_typeof(v_policy->'network_allowlist') = 'array'
                                 THEN v_policy->'network_allowlist' ELSE '[]'::jsonb END) AS h
                          WHERE jsonb_typeof(h) = 'string'), '[]'::jsonb),
    'rpc_allowlist',     COALESCE((SELECT jsonb_agg(f) FROM jsonb_array_elements(
                            CASE WHEN jsonb_typeof(v_policy->'rpc_allowlist') = 'array'
                                 THEN v_policy->'rpc_allowlist' ELSE '[]'::jsonb END) AS f
                          WHERE jsonb_typeof(f) = 'string'), '[]'::jsonb));
END;
$$;

COMMENT ON FUNCTION public.get_plugin_sandbox_policy(text) IS
  'Service only (plugin broker): network and RPC allowlists from the APPROVED (canary/ga) plugin''s sandbox policy; anything else gets empty lists (default-deny).';

REVOKE ALL ON FUNCTION public.get_plugin_sandbox_policy(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_plugin_sandbox_policy(text) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_plugin_sandbox_policy(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_preceding_user_message.sql
-- -----------------------------------------------------------------------------

-- Function: get_preceding_user_message
-- Poslední zpráva UŽIVATELE před danou zprávou v téže konverzaci — otázka, na kterou
-- hodnocená odpověď odpovídala (svc-ai-chat routes/evaluate.ts, jen služba).
--
-- Vznik 2026-09-29 (SELF_IMPROVEMENT_LOOP.md §3, K-17): evaluate.ts ji volal, SoT neexistoval
-- (V2_PENDING v bráně rpc-sql-mapping). Bez otázky soudce hodnotí odpověď naslepo.
-- Vrací {content} nebo NULL, když otázka před zprávou není.

CREATE OR REPLACE FUNCTION public.get_preceding_user_message(p_conversation_id uuid, p_message_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  RETURN (
    SELECT jsonb_build_object('content', cm.content)
    FROM public.chat_messages cm
    WHERE cm.conversation_id = p_conversation_id
      AND cm.role = 'user'
      AND cm.created_at < (SELECT m.created_at FROM public.chat_messages m WHERE m.id = p_message_id)
    ORDER BY cm.created_at DESC
    LIMIT 1
  );
END;
$$;

COMMENT ON FUNCTION public.get_preceding_user_message(uuid, uuid) IS
  'Poslední zpráva uživatele před danou zprávou v konverzaci ({content}); jen služba. NULL = není.';

REVOKE ALL ON FUNCTION public.get_preceding_user_message(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_preceding_user_message(uuid, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_recent_b_g_switches.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_recent_b_g_switches
-- Popis: Reads recent blue_green_switch_committed events from audit_journal.
--        Vrací app_name, from→to slot, image_tag, switched_by user, is_rollback flag.
-- Volá: WF_APPSMITH_DASHBOARD_BUILDER (Recent B/G Switches table widget)
-- Auth: admin/staff nebo service_role
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_recent_b_g_switches(
  p_limit int DEFAULT 20
)
RETURNS TABLE (
  switched_at  timestamptz,
  app_name     text,
  from_slot    text,
  to_slot      text,
  image_tag    text,
  switched_by  uuid,
  is_rollback  boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF NOT public.is_admin_or_staff()
     AND NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  RETURN QUERY
  SELECT
    aj.created_at AS switched_at,
    aj.metadata->>'app_name' AS app_name,
    aj.metadata->>'from_slot' AS from_slot,
    aj.metadata->>'to_slot' AS to_slot,
    aj.metadata->>'image_tag' AS image_tag,
    aj.user_id AS switched_by,
    COALESCE((aj.metadata->>'is_rollback')::boolean, false) AS is_rollback
  FROM public.audit_journal aj
  WHERE aj.action = 'blue_green_switch_committed'
  ORDER BY aj.created_at DESC
  LIMIT GREATEST(p_limit, 1);
END;
$$;

REVOKE ALL ON FUNCTION public.get_recent_b_g_switches(int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_recent_b_g_switches(int) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_recent_b_g_switches(int) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_recent_sentry_issues.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_recent_sentry_issues
-- Popis: Dashboard query Sentry issues — vrací deduplikované issues filtered by
--        min level (fatal | error | warning | info | debug) a optional app_name.
--        DISTINCT ON (sentry_issue_id) → per issue jen latest snapshot.
-- Auth: admin/staff nebo service_role
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_recent_sentry_issues(
  p_limit int DEFAULT 50,
  p_min_level text DEFAULT 'error',
  p_app_name text DEFAULT NULL
)
RETURNS TABLE (
  sentry_issue_id text,
  app_name        text,
  project_slug    text,
  level           text,
  title           text,
  first_seen      timestamptz,
  last_seen       timestamptz,
  count           int,
  user_count      int,
  release         text,
  permalink       text,
  age_minutes     int
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_min_idx int;
BEGIN
  IF NOT public.is_admin_or_staff()
     AND NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  v_min_idx := CASE p_min_level
    WHEN 'fatal'   THEN 0
    WHEN 'error'   THEN 1
    WHEN 'warning' THEN 2
    WHEN 'info'    THEN 3
    WHEN 'debug'   THEN 4
    ELSE 1
  END;

  RETURN QUERY
  SELECT DISTINCT ON (sis.sentry_issue_id)
    sis.sentry_issue_id, sis.app_name, sis.project_slug, sis.level, sis.title,
    sis.first_seen, sis.last_seen, sis.count, sis.user_count,
    sis.release, sis.permalink,
    EXTRACT(EPOCH FROM (now() - sis.first_seen))::int / 60 AS age_minutes
  FROM public.sentry_issue_snapshot sis
  WHERE sis.status = 'unresolved'
    AND CASE sis.level
      WHEN 'fatal'   THEN 0
      WHEN 'error'   THEN 1
      WHEN 'warning' THEN 2
      WHEN 'info'    THEN 3
      WHEN 'debug'   THEN 4
    END <= v_min_idx
    AND (p_app_name IS NULL OR sis.app_name = p_app_name)
  ORDER BY sis.sentry_issue_id, sis.observed_at DESC
  LIMIT GREATEST(p_limit, 1);
END;
$$;

REVOKE ALL ON FUNCTION public.get_recent_sentry_issues(int, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_recent_sentry_issues(int, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_recent_sentry_issues(int, text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_recent_switches.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_recent_switches
-- Popis: Returns apps switched in last X minutes. Used by WF_SENTRY_OBSERVER pro
--        deploy correlation. is_production flag detekován z domain pattern nebo
--        explicit metadata.is_production override.
-- Volá: WF_SENTRY_OBSERVER (Phase 3) — koreluje Sentry issues s recent switches
-- Auth: admin/staff nebo service_role
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_recent_switches(
  p_window_minutes int DEFAULT 30
)
RETURNS TABLE (
  app_name        text,
  active_slot     text,
  active_image_tag text,
  switched_at     timestamptz,
  is_production   boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
BEGIN
  IF NOT public.is_admin_or_staff()
     AND NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  RETURN QUERY
  SELECT
    cas.app_name,
    cas.active_slot,
    CASE cas.active_slot
      WHEN 'blue' THEN cas.blue_image_tag
      ELSE cas.green_image_tag
    END AS active_image_tag,
    cas.last_switch_at AS switched_at,
    -- AISHA prod = domain matches main aisha.guru patterns
    -- Pro user stories: production je fixed convention v config
    COALESCE(
      (cas.metadata->>'is_production')::boolean,
      cas.domain ~ '^(aisha\.guru|app\.aisha\.guru|api\.aisha\.guru)$'
    ) AS is_production
  FROM public.coolify_app_slots cas
  WHERE cas.last_switch_at IS NOT NULL
    AND cas.last_switch_at > now() - (p_window_minutes || ' minutes')::interval
  ORDER BY cas.last_switch_at DESC;
END;
$$;

REVOKE ALL ON FUNCTION public.get_recent_switches(int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_recent_switches(int) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_recent_switches(int) TO service_role;


