RETURNS TABLE(
  id uuid,
  name text,
  livekit_room_name text,
  is_active boolean,
  max_participants integer
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
