-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_test_questions_localized.sql
-- -----------------------------------------------------------------------------

-- Function: get_test_questions_localized
-- Purpose: Returns test questions with localized text using translation keys only (no _cs/_en fallback).
-- Security: SECURITY DEFINER, public access.

CREATE OR REPLACE FUNCTION public.get_test_questions_localized(
  p_locale TEXT DEFAULT 'en',
  p_test_type TEXT DEFAULT NULL
)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result JSONB;
  v_locale TEXT;
BEGIN
  -- ⛔ NÁROK, NE JEN DOSTUPNOST (naměřeno 2026-09-12 diferenciální sondou).
  -- Tahle funkce vydává `correct_answer` — klíč správných odpovědí
  -- certifikačního testu — a směl ji volat i ANONYM. Zamýšlený rozpad ukazují
  -- sourozenci v témže adresáři: `get_test_questions_public_localized` vydá
  -- TYTÉŽ otázky BEZ odpovědí (a jen tu volá appka, viz useTestQuestions.ts),
  -- `get_test_questions_admin_localized` vydá odpovědi a nárok hlídá. Tahle
  -- varianta nesla admin obsah bez admin stráže — díra, ne rozhodnutí.
  IF NOT (public.is_admin_or_staff() OR public.is_service_role()) THEN
    RAISE EXCEPTION 'Admin or staff access required';
  END IF;

  v_locale := CASE
    WHEN p_locale IN ('cs', 'de', 'en', 'fr', 'ru', 'th') THEN p_locale
    ELSE 'en'
  END;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', tq.id,
      'test_type', tq.test_type,
      'question_order', tq.question_order,
      'question', public.get_translation_value_with_fallback(
        tq.question_key, 'tests', v_locale, 'en', NULL
      ),
      'option_a', public.get_translation_value_with_fallback(
        tq.option_a_key, 'tests', v_locale, 'en', NULL
      ),
      'option_b', public.get_translation_value_with_fallback(
        tq.option_b_key, 'tests', v_locale, 'en', NULL
      ),
      'option_c', CASE WHEN tq.option_c_key IS NOT NULL THEN
        public.get_translation_value_with_fallback(
          tq.option_c_key, 'tests', v_locale, 'en', NULL
        )
      ELSE NULL END,
      'option_d', CASE WHEN tq.option_d_key IS NOT NULL THEN
        public.get_translation_value_with_fallback(
          tq.option_d_key, 'tests', v_locale, 'en', NULL
        )
      ELSE NULL END,
      'correct_answer', tq.correct_answer,
      'points', tq.points,
      'is_active', tq.is_active
    ) ORDER BY tq.question_order
  )
  INTO v_result
  FROM test_questions tq
  WHERE tq.is_active = true
    AND (p_test_type IS NULL OR tq.test_type = p_test_type);

  RETURN COALESCE(v_result, '[]'::JSONB);
END;
$function$;

-- Permissions
-- `anon` tu ZÁMĚRNĚ není: funkce vydává klíč správných odpovědí. Veřejný web
-- má `get_test_questions_public_localized`, která odpovědi nenese.
REVOKE ALL ON FUNCTION public.get_test_questions_localized(TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_test_questions_localized(TEXT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_test_questions_localized(TEXT, TEXT) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_twin_events_table_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_twin_events_table_block
-- Popis: GENERICKÝ 'table' blok nad twin substrátem: události daného typu
--        jako řádky, sloupce deklarované KONFIGURACÍ bloku. Žádná doménová
--        ani instanční hodnota v kódu — vše přichází v p_params (dispatcher
--        get_block_data merguje surface_blocks.source_params || p_params,
--        takže konfigurace = řádek bloku v instance overlay).
--
-- Konfigurace (p_params):
--   event_type   POVINNÉ   typ události (twin_events.event_type)
--   columns      POVINNÉ   pole [{key, label | label_key, src, numeric?}]
--                          src: 'twin_label' | 'place_label' | 'occurred_at'
--                               | 'attr:<jméno>' (hodnota z attrs)
--                          numeric: true → attr se emituje jako číslo
--   limit        volitelné default 50, strop 200
--   sort         volitelné 'occurred_desc' (default) | 'place_label_asc'
--   sort_attr_desc volitelné jméno attrs klíče — sekundární číselné řazení
--                  (jen se sort='place_label_asc')
--
-- Poctivá degradace: chybějící konfigurace → prázdná data s
--   provenance.error='missing_config', nikdy výjimka (blok se přizná).
-- Provenance: source_slug ODVOZEN z dat (distinct twin_events.source).
-- Bezpečnost: SECURITY DEFINER (čte substrát napříč RLS) + auth guard.
-- Vzniklo vykostěním get_porada_activity + get_object_tenants (07-25):
--   tytéž bloky teď jedou přes tuhle funkci s konfigurací v instančním datovém repu.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_twin_events_table_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
  with cfg as (
    select p_params->>'event_type' as ev,
           coalesce(p_params->'columns', '[]'::jsonb) as cols,
           least(coalesce((p_params->>'limit')::int, 50), 200) as lim,
           coalesce(p_params->>'sort', 'occurred_desc') as srt,
           p_params->>'sort_attr_desc' as srt_attr
  ),
  src as (
    select e.id, coalesce(e.occurred_at, e.created_at) as ts, e.source,
           c.label as twin_label, o.label as place_label, e.attrs,
           row_number() over (order by
             case when (select srt from cfg) = 'place_label_asc' then o.label end asc nulls last,
             case when (select srt from cfg) = 'place_label_asc' and (select srt_attr from cfg) is not null
                  then nullif(e.attrs->>(select srt_attr from cfg), '')::numeric end desc nulls last,
             coalesce(e.occurred_at, e.created_at) desc) as rn
    from twin_events e
    join twin_entities c on c.id = e.twin_id
    left join twin_entities o on o.id = e.place_twin_id
    where e.event_type = (select ev from cfg)
  ),
  rendered as (
    select s.rn, s.source,
      (select jsonb_object_agg(col->>'key',
         case
           when col->>'src' = 'twin_label'  then to_jsonb(s.twin_label)
           when col->>'src' = 'place_label' then to_jsonb(s.place_label)
           when col->>'src' = 'occurred_at' then to_jsonb(to_char(s.ts, 'YYYY-MM-DD'))
           when (col->>'numeric')::boolean is true
             then to_jsonb(nullif(s.attrs->>(substring(col->>'src' from '^attr:(.*)$')), '')::numeric)
           else coalesce(to_jsonb(s.attrs->>(substring(col->>'src' from '^attr:(.*)$'))), 'null'::jsonb)
         end)
       from jsonb_array_elements((select cols from cfg)) col) as row_obj
    from src s
    where s.rn <= (select lim from cfg)
  )
  select case
    -- ⛔ NÁROK PODLE ROLE, NE PODLE PUBLIKA BLOKU (slití 2026-09-13). Upstream tu
    -- měl kontrolu „volající je v publiku NĚJAKÉHO aktivního bloku s touto
    -- funkcí" (audit U4-5). Ta ale neváže `event_type` z požadavku na
    -- `source_params` toho bloku — funkce je GRANT authenticated a volá se přímo
    -- přes /rpc/, takže člen publika bloku s typem A přečetl libovolný typ B.
    -- Tabulka navíc NEMÁ omezení po řádcích, tedy patří jen tomu, kdo smí vidět
    -- všechno. Diferenciálně měří `definer-narok-ne-jen-prihlaseni.runtime.test.ts`.
    -- ⛔ NÁROK, NE JEN PŘIHLÁŠENÍ (naměřeno 2026-09-11): guard ověřoval, že jsi
    -- přihlášený, ne že na to máš nárok — řidič bez rolí dostával totéž co admin.
    when not (public.is_admin_or_staff() or public.is_service_role()) then
      -- Tabulka BEZ `columns` není kontraktní tabulka, takže tahle větev
      -- (a s ní celý blok) mizela beze slova. Provenance ze stejného důvodu:
      -- `error` v ní schéma nezná, důvod patří do `trace_id`.
      jsonb_build_object('data', jsonb_build_object('columns', '[]'::jsonb, 'rows', '[]'::jsonb),
        'provenance', jsonb_build_object('source_slug', 'twin_events',
          'trace_id', 'twin-events:unauthenticated', 'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')))
    when (select ev from cfg) is null or jsonb_array_length((select cols from cfg)) = 0 then
      jsonb_build_object('data', jsonb_build_object('columns', '[]'::jsonb, 'rows', '[]'::jsonb),
        'provenance', jsonb_build_object('source_slug', 'twin_events',
          'trace_id', 'twin-events:missing_config', 'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')))
    else jsonb_build_object(
      'data', jsonb_build_object(
        'columns', (select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                      'key', c->>'key', 'label', c->>'label', 'label_key', c->>'label_key')))
                    from jsonb_array_elements((select cols from cfg)) c),
        'rows', coalesce((select jsonb_agg(row_obj order by rn) from rendered), '[]'::jsonb)),
      'provenance', jsonb_build_object(
        'source_slug', coalesce((select string_agg(distinct r2.source, '+') from rendered r2), 'twin_events'),
        'trace_id', 'twin-events:' || (select ev from cfg),
        'freshness_at', now()))
  end;
$$;

REVOKE ALL ON FUNCTION public.get_twin_events_table_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_twin_events_table_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_twin_events_table_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_twin_ref_pending_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_twin_ref_pending_block
-- Popis: GENERICKÝ 'kpi_tile' blok — počet navržených (neratifikovaných)
--        twin identity vazeb z daného zdroje; >0 = warning (fronta na
--        člověka). Zdroj je KONFIGURACE bloku, ne konstanta v kódu.
--
-- Konfigurace (p_params):
--   source  POVINNÉ   twin_external_refs.source (slug lane, který blok hlídá)
--   state   volitelné default 'proposed' (slovník mechanismu, ne instance)
--
-- Poctivá degradace: bez source → error='missing_config'.
-- Vzniklo vykostěním get_porada_pending (07-25).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_twin_ref_pending_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
  select case
    -- ⛔ NÁROK, NE JEN PŘIHLÁŠENÍ (naměřeno 2026-09-11): guard ověřoval, že jsi
    -- přihlášený, ne že na to máš nárok — řidič bez rolí dostával totéž co admin.
    when not (public.is_admin_or_staff() or public.is_service_role()) then
      -- ⭐ POCTIVÁ DEGRADACE MUSÍ BÝT KONTRAKTNÍ, jinak se zahodí i ona.
      -- Do 2026-08-08 tu stálo `'provenance', jsonb_build_object('error', …)`:
      -- provenance je uzavřená na {source_slug, freshness_at, trace_id}, takže
      -- klient CELÝ blok zahodil a přiznání se k uživateli nikdy nedostalo.
      -- Důvod patří do `trace_id` — stejně jako u get_doc_expiry_review_block.
      -- `value` je null, ne nula: nula by tvrdila měření, které nikdo neprovedl.
      jsonb_build_object('data', jsonb_build_object('value', null),
        'provenance', jsonb_build_object('source_slug', 'twin-identity',
          'trace_id', 'twin-ref-pending:unauthenticated', 'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')))
    when p_params->>'source' is null then
      jsonb_build_object('data', jsonb_build_object('value', null),
        'provenance', jsonb_build_object('source_slug', 'twin-identity',
          'trace_id', 'twin-ref-pending:missing_config', 'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')))
    else (
      select jsonb_build_object(
        'data', jsonb_build_object('value', n, 'state', case when n > 0 then 'warning' else 'ok' end),
        'provenance', jsonb_build_object('source_slug', 'twin-identity',
          'trace_id', 'twin-ref-pending:' || (p_params->>'source'), 'freshness_at', now()))
      from (select count(*) as n
            from twin_external_refs
            where source = p_params->>'source'
              and state = coalesce(p_params->>'state', 'proposed')) q)
  end;
$$;

REVOKE ALL ON FUNCTION public.get_twin_ref_pending_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_twin_ref_pending_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_twin_ref_pending_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_twin_relation_proposal_queue.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_twin_relation_proposal_queue
-- Popis: GENERICKÝ 'review_queue' blok — skupiny návrhů hran mezi dvojčaty,
--        které čekají na člověka. Položka = SKUPINA (jednotka rozhodnutí),
--        ne jednotlivá hrana: „19 podružných měřidel pod elektroměrem X" je
--        jedna otázka se společným důkazem.
--
-- Konfigurace (p_params, vše volitelné):
--   source    filtr navrhovatele (twin_relation_proposal_groups.source)
--   rule_key  filtr pravidla
--   sample    kolik čekajících hran ukázat v citaci (výchozí 5, strop 20)
--   limit     počet skupin (výchozí 50, strop 200)
--
-- Texty: nadpis skupiny a štítky dvojčat jsou DATA (od navrhovatele a ze zdroje),
-- popisky polí jdou přes klíče app.twins.proposal.* (i18n). Druh vazby se
-- ukazuje přes value_key app.twins.relation.<kind> — nepřeložený klíč je vidět,
-- to je vlastnost (i18n.ts), ne vada.
--
-- Zápis rozhodnutí: submit_evidence_review_audited(entity_kind 'twin_relation',
-- id skupiny) → twin_relation_proposal_decide.
--
-- ⛔ OBÁLKA: maska review_queue vyžaduje {entity_kind, items, actions} a
-- provenance je UZAVŘENÁ na {source_slug, trace_id, freshness_at} — větev bez
-- nároku proto nese tutéž obálku s prázdnými položkami a důvod v trace_id
-- (naměřeno u get_twin_ref_review_block 2026-09-15: jinak klient zahodí blok).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_twin_relation_proposal_queue(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
-- INVOKER: viditelnost rozhoduje RLS nad návrhy i dvojčaty (admin/staff), týž
-- nárok jako sesterské fronty identit. Guard níž jen zajistí tvar odpovědi.
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  with akce as (
    select jsonb_build_array(
      jsonb_build_object('action_key', 'app.twins.proposal.action.approve', 'decision', 'approved', 'intent', 'approve'),
      jsonb_build_object('action_key', 'app.twins.proposal.action.reject',  'decision', 'rejected', 'intent', 'reject')
    ) as a
  ),
  cfg as (
    select nullif(p_params->>'source', '')   as src,
           nullif(p_params->>'rule_key', '') as rule,
           least(greatest(coalesce(nullif(p_params->>'sample', '')::int, 5), 1), 20)  as smp,
           least(greatest(coalesce(nullif(p_params->>'limit', '')::int, 50), 1), 200) as lim
  ),
  cekajici as (
    select x.group_id,
           count(*)                                   as pending,
           min(x.confidence)                          as conf_min,
           array_agg(distinct x.relation_kind)        as kinds,
           max(x.updated_at)                          as fresh
      from twin_relation_proposals x
     where x.state = 'proposed'
     group by x.group_id
  ),
  skupiny as (
    select g.id, g.source, g.rule_key, coalesce(g.title, g.group_key) as title,
           c.pending, c.conf_min, c.kinds, greatest(c.fresh, g.updated_at) as fresh,
           (select count(*) from twin_relation_proposals d
             where d.group_id = g.id and d.state in ('approved', 'rejected', 'superseded')) as decided
      from twin_relation_proposal_groups g
      join cekajici c on c.group_id = g.id
     where ((select src from cfg) is null or g.source = (select src from cfg))
       and ((select rule from cfg) is null or g.rule_key = (select rule from cfg))
     order by g.source, coalesce(g.title, g.group_key), g.id
     limit (select lim from cfg)
  ),
  ukazky as (
    -- Prvních N čekajících hran skupiny jako „zdroj → cíl". Štítek dvojčete je
    -- to, co člověk ze zdroje zná (číslo OM, název místnosti), ne UUID.
    select s.id,
           string_agg(coalesce(se.label, x.source_twin_id::text) || ' → ' || coalesce(te.label, x.target_twin_id::text),
                      '; ' order by x.proposal_key) as hrany
      from skupiny s
      cross join lateral (
        select y.proposal_key, y.source_twin_id, y.target_twin_id
          from twin_relation_proposals y
         where y.group_id = s.id and y.state = 'proposed'
         order by y.proposal_key
         limit (select smp from cfg)
      ) x
      left join twin_entities se on se.id = x.source_twin_id
      left join twin_entities te on te.id = x.target_twin_id
     group by s.id
  ),
  polozky as (
    select s.*, u.hrany
      from skupiny s
      left join ukazky u on u.id = s.id
  )
  select case
    when not (public.is_admin_or_staff() or public.is_service_role()) then
      jsonb_build_object(
        'data', jsonb_build_object('entity_kind', 'twin_relation', 'items', '[]'::jsonb,
                                   'actions', (select a from akce)),
        'provenance', jsonb_build_object('source_slug', 'twin-relation-proposals',
          'trace_id', 'twin-relation-queue:unauthorized', 'freshness_at', now()))
    else jsonb_build_object(
      'data', jsonb_build_object(
        'entity_kind', 'twin_relation',
        'items', coalesce((
          select jsonb_agg(jsonb_build_object(
                   'id',    p.id::text,
                   'title', p.title,
                   'quote', coalesce(p.hrany, '')
                            || case when p.pending > (select smp from cfg)
                                    then ' … (+' || (p.pending - (select smp from cfg))::text || ')'
                                    else '' end,
                   'fields', jsonb_build_array(
                       jsonb_build_object('key', 'pending', 'label_key', 'app.twins.proposal.pending',
                                          'value', p.pending),
                       case when cardinality(p.kinds) = 1
                            then jsonb_build_object('key', 'relation_kind', 'label_key', 'app.twins.proposal.kind',
                                                    'value_key', 'app.twins.relation.' || p.kinds[1])
                            else jsonb_build_object('key', 'relation_kind', 'label_key', 'app.twins.proposal.kind',
                                                    'value', array_to_string(p.kinds, ', '))
                       end,
                       jsonb_build_object('key', 'source', 'label_key', 'app.twins.proposal.source',
                                          'value', p.source)
                     )
                     || case when p.conf_min is null then '[]'::jsonb
                             else jsonb_build_array(jsonb_build_object(
                                    'key', 'confidence', 'label_key', 'app.twins.proposal.confidence',
                                    'value', round(p.conf_min * 100)::text || ' %',
                                    'confidence', p.conf_min)) end
                     || case when p.decided = 0 then '[]'::jsonb
                             else jsonb_build_array(jsonb_build_object(
                                    'key', 'decided', 'label_key', 'app.twins.proposal.decided',
                                    'value', p.decided)) end
                 ) order by p.source, p.title, p.id)
            from polozky p), '[]'::jsonb),
        'actions', (select a from akce)),
      'provenance', jsonb_build_object(
        'source_slug',  'twin-relation-proposals',
        'trace_id',     'twin-relation-queue:' || coalesce((select src from cfg), 'all')
                        || case when not exists (select 1 from polozky) then ':no_data' else '' end,
        'freshness_at', coalesce((select max(fresh) from polozky), now())))
  end;
$$;

REVOKE ALL ON FUNCTION public.get_twin_relation_proposal_queue(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_twin_relation_proposal_queue(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_twin_relation_proposal_queue(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_user_sections.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_user_sections
-- Arguments: p_user_id uuid
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:27:47+01:00

CREATE OR REPLACE FUNCTION public.get_user_sections(p_user_id uuid DEFAULT auth.uid())
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- ⛔ PREDIKÁT O TŘETÍ OSOBĚ JE ORÁKULUM (naměřeno 2026-09-19). Sekce jsou
  -- odvozené z rolí, takže seznam sekcí cizího uuid prozradí jeho role (admin,
  -- staff, partner …) — tatáž třída jako has_role, jen s víc bity najednou.
  --
  -- Odpovídá se jen o VOLAJÍCÍM (výchozí `p_user_id` je sám volající); služba
  -- a správa na kohokoli. Cizí dotaz dostane prázdné pole — totéž, co účet bez
  -- rolí, takže zamítnutí nic neprozradí. Změřeno, že to nic nerozbije: v repu
  -- ji nevolá žádná politika, funkce ani klient.
  SELECT CASE
    WHEN p_user_id = auth.uid()
      OR public.is_service_role()
      OR public.is_admin_or_staff()
    THEN (
      SELECT COALESCE(
        ARRAY_AGG(DISTINCT rp.section::text),
        ARRAY[]::TEXT[]
      )
      FROM public.role_permissions rp
      JOIN public.user_roles ur ON ur.role = rp.role
      WHERE ur.user_id = p_user_id
    )
    ELSE ARRAY[]::TEXT[]
  END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.get_user_sections(p_user_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_user_sections(p_user_id uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_voice_room_entry.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- get_voice_room_entry — místnost podle jména v LiveKitu + verdikt vstupu
-- =============================================================================
-- Služební čtečka pro svc-livekit /create-token. Nahrazuje dvě RPC, která
-- trasa volala a která NIKDY neexistovala (get_voice_room_by_livekit_name,
-- check_story_membership — audit hlasu 2026-09-29, krok 5b): trasa proto
-- každou místnost hlásila 404. Rozhodnutí o vstupu nese can_enter_voice_room,
-- ne služba — jedno pravidlo pro token i pro RPC nad místnostmi.
-- =============================================================================

