-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_workflow_decisions_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_workflow_decisions_admin
-- Popis: Přehled rozhodnutí NAD PROCESEM (hromadná uzavření, …) — kdo, kdy, proč,
--        kolik, a jestli už bylo vráceno. Podklad pro správce: dohledat → vrátit.
-- Bezpečnost: bez zvýšených práv (INVOKER) + REVOKE/GRANT; autorizuje volaná
--             get_decisions_admin sama za sebe (admin/staff nebo service_role)
--
-- ⭐ ZADÁNÍ MAJITELE 2026-09-15: autonomní i hromadné kroky musí jít dohledat
--    a z UI vrátit. Rozhodnutí žije v audit_journal (neměnný deník).
--
-- ⛔ OD 2026-09-16 JE TO OBÁLKA, NE DRUHÁ ČTEČKA. Rozhodnutí přibyla i mimo proces
--    (zahození karantény brokeru), a dvě čtečky téhož deníku by se rozešly —
--    jedna by uměla nový druh, druhá ne, a správce by podle toho, kterou obrazovku
--    otevře, viděl jinou pravdu. Implementace je `get_decisions_admin`; tahle
--    funkce jen drží svůj kontrakt a filtruje druh `workflow_decision`.
--
-- Kontrakt (nezměněn): (integer) -> jsonb {items:[{decision_id, akce, kdy, kdo,
--   souhrn, duvod, kriterium, pocty, vraceno:{kdy, kdo, obnoveno}|null, vratne}]}
--   — položka navíc nese `druh` a `oblast` z obecné čtečky.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_workflow_decisions_admin(
  p_limit integer DEFAULT 50
)
RETURNS jsonb
LANGUAGE sql
STABLE
-- ⛔ ZÁMĚRNĚ BEZ SECURITY DEFINER. Obálka žádná zvýšená práva nepotřebuje: autorizaci
-- dělá `get_decisions_admin` sama za sebe (brána `definer musí autorizovat sám sebe`).
-- Definer, který se spoléhá na volaného, je otevřené dveře ve chvíli, kdy se volaný změní.
SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT public.get_decisions_admin(p_limit, 'workflow_decision');
$function$;

REVOKE ALL ON FUNCTION public.get_workflow_decisions_admin(integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_workflow_decisions_admin(integer) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_workflow_timeline_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_workflow_timeline_block
-- Popis: Surface blok table: narace procesních stories, nejnovější nahoře.
--        p_params: story_id (volitelné), limit (výchozí 50, strop 500).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- Pozn.: definice = regenerát z nasazené DB (ověřeno provozním testem 07-25).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_workflow_timeline_block(p_params jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_limit int := least(greatest(coalesce(nullif(p_params->>'limit', '')::int, 50), 1), 500);
  -- ⛔ NÁROK JAKO MNOŽINY, JEDNOU ZA VOLÁNÍ (naměřeno 2026-09-29 na produkci).
  -- Dřív tu stálo `is_service_role() or is_admin_or_staff(v_uid) or exists(…
  -- workflow_step_visible_to(v_uid, …))` — predikát (SECURITY DEFINER, plpgsql,
  -- dynamické SQL) se pro běžného uživatele volal pro KAŽDÝ krok každého běhu:
  -- člen bez role 92–95 s pro 0 řádků, a funkci smí přímo přes /rpc volat
  -- kdokoli přihlášený = DoS páka. Admin platil 1,7 s: obě pomocné funkce po
  -- řádcích a EXISTS pod OR, který planner ocenil po řádcích (odhad 119 mil.
  -- → JIT). Vzor je týž jako CTE `scope` ve frontě kroků a ve věži (07-30 V3):
  -- ramena 1:1 s predikátem při volání bez rozsahu a bez kódu kroku —
  -- přiřazení · role · potvrzená vazba účtu na `authorized_twin_id`.
  v_all boolean := public.is_service_role() or public.is_admin_or_staff(v_uid);
  v_roles text[] := '{}';
  v_twins text[] := '{}';
  v_rows jsonb;
begin
  if not v_all then
    select coalesce(array_agg(ur.role::text), '{}')
      into v_roles
      from public.user_roles ur
     where ur.user_id = v_uid;
    select coalesce(array_agg(r.twin_id::text), '{}')
      into v_twins
      from public.twin_external_refs r
     where r.ref_kind = 'account'
       and r.source_key = v_uid::text
       and r.state = 'confirmed' and r.valid_from <= now()
       and (r.valid_to is null or r.valid_to > now());
  end if;

  -- ⛔ LIMIT PŘED AGREGACÍ (naměřeno 2026-09-23 na produkci): `limit` stál za
  -- `jsonb_agg`, tedy omezoval JEDEN výsledný řádek agregátu, ne záznamy. Blok
  -- `wf_timeline` v poradě vydával všech 41 193 záznamů = 7 MB a 4,9 s při
  -- každém otevření sekce — a shell ho pak stejně zahodil (viz sloupce níž).
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', v.id,
           'when', to_char(v.occurred_at, 'DD.MM HH24:MI'),
           'run', v.run,
           'milestone', v.milestone,
           'event', v.event) order by v.occurred_at desc, v.id), '[]'::jsonb)
    into v_rows
  from (
    select se.id, se.occurred_at, ps.title as run,
           coalesce(se.metadata->>'step_name', se.metadata->>'step_code', '—') as milestone,
           se.content as event
    from story_entries se
    join partner_stories ps on ps.id = se.story_id
    where ps.origin = 'process'
      and (p_params->>'story_id' is null or se.story_id = (p_params->>'story_id')::uuid)
      -- Nekorelovaný `IN`, ne `EXISTS` pod OR: ten planner ocení z alternativy
      -- „po řádcích" (costsize.c: „Arbitrarily use the first alternative plan
      -- for costing"), i když za běhu použije hashovanou — odhad pak lže a JIT
      -- kompiluje zbytečně. `IN` má jedinou variantu a cenu jednou.
      and (v_all or se.story_id in (
            select b.story_id
              from production_batches b
              join production_workflow_steps s on s.batch_id = b.id
             where s.assigned_user_id = v_uid
                or s.assigned_role = any(v_roles)
                or (s.input_data->>'authorized_twin_id') = any(v_twins)))
    order by se.occurred_at desc, se.id
    limit v_limit
  ) v;
  return jsonb_build_object(
    'data', jsonb_build_object(
      -- `label_key`, ne hotový `label`: kontrakt tabulky hotový text v hlavičce
      -- nepřipouští (extranet běží v šesti jazycích) a blok s `label` shell
      -- ZAHODIL celý. Dřívější `labels` ze source_params se už nečtou —
      -- znění nese tabulka překladů.
      'columns', jsonb_build_array(
        jsonb_build_object('key','when','label_key','app.wf.col.when'),
        jsonb_build_object('key','run','label_key','app.wf.col.run'),
        jsonb_build_object('key','milestone','label_key','app.wf.col.milestone'),
        jsonb_build_object('key','event','label_key','app.wf.col.event')),
      -- `id` je záznam story (`story_entries.id`), ne doklad.
      'row_kind', 'story_entry',
      'rows', v_rows),
    'provenance', jsonb_build_object('source_slug','production_workflow',
      'trace_id','wf:timeline','freshness_at',now()));
end $function$;

REVOKE ALL ON FUNCTION public.get_workflow_timeline_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_workflow_timeline_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_workflow_timeline_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/has_data_sharing_consent.sql
-- -----------------------------------------------------------------------------

-- Function: public.has_data_sharing_consent
-- Arguments: p_user_id uuid, p_accessor_user_id uuid
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:27:51+01:00

CREATE OR REPLACE FUNCTION public.has_data_sharing_consent(p_user_id uuid, p_accessor_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_has_consent boolean;
  v_uid uuid := auth.uid();
BEGIN
  -- ⛔ PREDIKÁT O TŘETÍ OSOBĚ JE ORÁKULUM (naměřeno 2026-09-19). Kterýkoli
  -- přihlášený uměl přes `/rpc/has_data_sharing_consent` zjistit, zda člen X
  -- sdílí zdravotní data s partnerem Y — tedy kdo je čím klientem, pro libovolnou
  -- dvojici uuid. A protože se níž zapisuje audit s `user_id = p_accessor_user_id`,
  -- každý takový dotaz navíc PODVRHL záznam „partner Y ověřoval přístup ke členu X"
  -- pod cizím jménem.
  --
  -- Ptát se smí jen ten, kdo přistupuje (accessor = volající); služba a správa
  -- na kohokoli. Změřeno, že to nic nerozbije: všech 13 politik předává jako
  -- accessor `auth.uid()` a všech 24 volání z definer funkcí proměnnou naplněnou
  -- z `auth.uid()` (řádek dat je vždy `p_user_id`, nikdy accessor). `false` bez
  -- auditního zápisu: zamítnutý dotaz nic nečetl a predikát v RLS má vracet deny,
  -- ne shodit dotaz.
  --
  -- Pořadí je záměrné: „ptám se za sebe" se ověří první (levně, per řádek v RLS)
  -- a role až potom. `IS DISTINCT FROM` + `v_uid IS NULL` drží stráž NULL-bezpečnou —
  -- prosté `<>` by pro anonyma dalo NULL a IF by stráž tiše přeskočil.
  IF v_uid IS NULL OR p_accessor_user_id IS DISTINCT FROM v_uid THEN
    IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
      RETURN false;
    END IF;
  END IF;

  -- Check if consent exists
  SELECT EXISTS (
    SELECT 1
    FROM data_sharing_consents dsc
    JOIN partner_profiles pp ON pp.id = dsc.partner_id
    WHERE dsc.user_id = p_user_id
      AND pp.user_id = p_accessor_user_id
      AND dsc.revoked_at IS NULL
      AND (dsc.expires_at IS NULL OR dsc.expires_at > now())
  ) INTO v_has_consent;

  -- Audit log for consent check (sensitive data access verification)
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    p_accessor_user_id,
    'has_data_sharing_consent',
    jsonb_build_object(
      'area', 'phi',
      'severity', 'info',
      'entity_type', 'data_sharing_consents',
      'target_user_id', p_user_id,
      'result', v_has_consent
    )
  );

  RETURN v_has_consent;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.has_data_sharing_consent(p_user_id uuid, p_accessor_user_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_data_sharing_consent(p_user_id uuid, p_accessor_user_id uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_storyloop_notification.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_storyloop_notification
-- Arguments: p_user_id uuid, p_type text, p_title text, p_message text, p_link text
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:13+01:00

CREATE OR REPLACE FUNCTION public.create_storyloop_notification(p_user_id uuid, p_type text, p_title text, p_message text, p_link text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_notification_id UUID;
  v_caller_partner_id UUID;
  v_user_id uuid := auth.uid();
  v_is_admin boolean := false;
  v_is_consultant boolean := false;
  v_has_consent boolean := false;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Get caller's partner ID
  SELECT pp.id INTO v_caller_partner_id
  FROM partner_profiles pp
  WHERE pp.user_id = auth.uid();
  
  v_is_admin := is_admin_or_staff(v_user_id);
  v_is_consultant := public.is_consultant_for_user(p_user_id);
  v_has_consent := public.has_data_sharing_consent(p_user_id, v_user_id);
  
  -- Must be a partner or admin/staff
  IF v_caller_partner_id IS NULL AND NOT v_is_admin THEN
    RAISE EXCEPTION 'Not authorized to create notifications';
  END IF;

  -- If not admin/staff, require relationship or consent with the target member
  IF NOT v_is_admin AND NOT (v_is_consultant OR v_has_consent) THEN
    RAISE EXCEPTION 'Not authorized to notify this user';
  END IF;
  
  -- Create the notification
  INSERT INTO notifications (user_id, type, title, message, link)
  VALUES (p_user_id, p_type, p_title, p_message, p_link)
  RETURNING id INTO v_notification_id;

  INSERT INTO audit_journal (user_id, action_type, entity_type, entity_id, area, severity, summary, metadata)
  VALUES (
    v_user_id,
    'create',
    'notification',
    v_notification_id::text,
    'partner',
    'info',
    'Created StoryLoop notification',
    jsonb_build_object('target_user_id', p_user_id, 'type', p_type)
  );
  
  RETURN v_notification_id;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.create_storyloop_notification(p_user_id uuid, p_type text, p_title text, p_message text, p_link text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_storyloop_notification(p_user_id uuid, p_type text, p_title text, p_message text, p_link text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_consultant_users.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_consultant_users
-- Arguments: none
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.get_consultant_users()
 RETURNS TABLE(registration_id uuid, user_id uuid, study_id uuid, study_name text, study_code text, status text, enrolled_at timestamptz, display_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_id uuid;
BEGIN
  -- Get partner ID for current user
  SELECT id INTO v_partner_id
  FROM public.partner_profiles
  WHERE partner_profiles.user_id = auth.uid()
  LIMIT 1;

  IF v_partner_id IS NULL THEN
    RETURN; -- Return empty if not a partner
  END IF;

  INSERT INTO audit_journal (
    user_id, action_type, entity_type, area, severity, summary
  ) VALUES (
    auth.uid(), 'read'::journal_action_type, 'study_registrations',
    'research'::journal_area, 'info'::journal_severity,
    'Partner viewed their users list'
  );

  -- Return users assigned to this partner via study_consultants
  -- Only return users who have granted data_sharing_consent
  RETURN QUERY
  SELECT 
    se.id AS registration_id,
    se.user_id,
    se.study_id,
    COALESCE(st.name, '') AS study_name,
    COALESCE(st.code, '') AS study_code,
    se.status,
    se.enrolled_at,
    COALESCE(pr.display_name, '') AS display_name
  FROM public.study_registrations se
  JOIN public.study_consultants sc ON sc.study_id = se.study_id AND sc.partner_id = v_partner_id
  JOIN public.studies st ON st.id = se.study_id
  LEFT JOIN public.profiles pr ON pr.user_id = se.user_id
  WHERE sc.status = 'approved'
    AND se.status IN ('active', 'completed', 'pending')
    AND public.has_data_sharing_consent(se.user_id, auth.uid())
  ORDER BY se.enrolled_at DESC;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_consultant_users() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_consultant_users() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_consultant_users() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_longevity_score_history_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_longevity_score_history_audited
-- Description: Get Longevity Score history for a user
-- Security: SECURITY DEFINER with audit logging
-- sensitive data: Yes - reads questionnaire responses history

CREATE OR REPLACE FUNCTION public.get_longevity_score_history_audited(
  p_user_id UUID DEFAULT NULL,
  p_limit INTEGER DEFAULT 12
)
RETURNS TABLE (
  response_id UUID,
  completed_at TIMESTAMPTZ,
  cls_score NUMERIC,
  domain_scores JSONB,
  trend_vs_previous NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_target_user UUID;
  v_questionnaire_id UUID;
BEGIN
  -- Determine target user
  v_target_user := COALESCE(p_user_id, auth.uid());
  
  -- Authorization check
  IF NOT (
    v_target_user = auth.uid() OR
    is_admin_or_staff(auth.uid()) OR
    has_data_sharing_consent(v_target_user, auth.uid())
  ) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  
  -- Get OS-SUBJECTIVE questionnaire ID
  SELECT id INTO v_questionnaire_id
  FROM questionnaires
  WHERE code = 'OS-SUBJECTIVE';
  
  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'sensitive data_READ',
    jsonb_build_object(
      'area', 'longevity_score',
      'severity', 'info',
      'entity_type', 'history',
      'user_id', v_target_user,
      'limit', p_limit
    )
  );
  
  -- Return history with calculated scores
  RETURN QUERY
  WITH scored_responses AS (
    SELECT 
      qr.id AS response_id,
      qr.completed_at,
      calculate_domain_scores(qr.responses) AS domain_scores
    FROM questionnaire_responses qr
    WHERE qr.user_id = v_target_user
      AND qr.questionnaire_id = v_questionnaire_id
      AND qr.completed_at IS NOT NULL
    ORDER BY qr.completed_at DESC
    LIMIT p_limit
  ),
  with_cls AS (
    SELECT 
      sr.response_id,
      sr.completed_at,
      sr.domain_scores,
      ROUND((
        SELECT AVG((d->>'percentage')::NUMERIC) 
        FROM jsonb_array_elements(sr.domain_scores) d 
        WHERE (d->>'percentage') IS NOT NULL
      ), 1) AS cls_score
    FROM scored_responses sr
  ),
  with_trend AS (
    SELECT 
      wc.*,
      wc.cls_score - LAG(wc.cls_score) OVER (ORDER BY wc.completed_at) AS trend_vs_previous
    FROM with_cls wc
  )
  SELECT 
    wt.response_id,
    wt.completed_at,
    wt.cls_score,
    wt.domain_scores,
    ROUND(wt.trend_vs_previous, 1)
  FROM with_trend wt
  ORDER BY wt.completed_at DESC;
END;
$$;

REVOKE ALL ON FUNCTION public.get_longevity_score_history_audited(uuid, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_longevity_score_history_audited(uuid, integer) TO authenticated;

COMMENT ON FUNCTION public.get_longevity_score_history_audited(uuid, integer) IS 'Get Longevity Score history with trend calculation';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_partner_user_registrations.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_partner_user_registrations
-- Arguments: (none)
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:27:11+01:00

CREATE OR REPLACE FUNCTION public.get_partner_user_registrations()
 RETURNS TABLE(registration_id uuid, user_id uuid, study_id uuid, study_name text, study_code text, registration_status text, consultant_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_id UUID;
BEGIN
  -- Audit log for partner accessing user registrations (sensitive data)
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'get_partner_user_registrations',
    jsonb_build_object(
      'area', 'phi',
      'severity', 'info',
      'entity_type', 'study_registrations'
    )
  );

  -- Get partner profile
  SELECT pp.id INTO v_partner_id
  FROM partner_profiles pp
  WHERE pp.user_id = auth.uid();

  IF v_partner_id IS NULL THEN
    RETURN;
  END IF;

  -- Return registrations where this partner is the consultant
  -- Only return users who have granted data_sharing_consent
  RETURN QUERY
  SELECT 
    se.id as registration_id,
    se.user_id,
    se.study_id,
    s.name as study_name,
    s.code as study_code,
    se.status::TEXT as registration_status,
    se.consultant_id
  FROM study_registrations se
  JOIN studies s ON s.id = se.study_id
  JOIN study_consultants sc ON sc.id = se.consultant_id
  WHERE sc.partner_id = v_partner_id
    AND sc.status = 'approved'
    AND public.has_data_sharing_consent(se.user_id, auth.uid())
  ORDER BY se.enrolled_at DESC;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.get_partner_user_registrations() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.get_partner_user_registrations() FROM anon;
GRANT EXECUTE ON FUNCTION public.get_partner_user_registrations() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_questionnaire_response_detail_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_questionnaire_response_detail_audited
-- Arguments: p_response_id uuid
-- Description: Returns full questionnaire response detail with questionnaire metadata. Audit logged.
-- Security: SECURITY DEFINER - checks self-access, partner/consultant consent, admin bypass.
-- @security: authenticated
-- @audit: SELECT on questionnaire_responses

CREATE OR REPLACE FUNCTION public.get_questionnaire_response_detail_audited(
  p_response_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_actor_id uuid;
  v_response_user_id uuid;
  v_partner_id uuid;
  v_has_access boolean := false;
  v_result jsonb;
BEGIN
  v_actor_id := auth.uid();
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Get the owner of the response
  SELECT qr.user_id INTO v_response_user_id
  FROM questionnaire_responses qr
  WHERE qr.id = p_response_id;

  IF v_response_user_id IS NULL THEN
    RAISE EXCEPTION 'Response not found';
  END IF;

  -- Self-access
  IF v_actor_id = v_response_user_id THEN
    v_has_access := true;
  END IF;

  -- Partner/consultant access with consent check
  IF NOT v_has_access THEN
    SELECT pp.id INTO v_partner_id
    FROM partner_profiles pp
    WHERE pp.user_id = v_actor_id;

    IF v_partner_id IS NOT NULL THEN
      SELECT EXISTS (
        SELECT 1 FROM study_registrations se
        JOIN study_consultants sc ON sc.id = se.consultant_id
        WHERE se.user_id = v_response_user_id
          AND sc.partner_id = v_partner_id
          AND sc.status = 'approved'
      ) AND public.has_data_sharing_consent(v_response_user_id, v_actor_id)
      INTO v_has_access;
    END IF;
  END IF;

  -- Admin/staff bypass
  IF NOT v_has_access AND public.is_admin_or_staff(v_actor_id) THEN
    v_has_access := true;
  END IF;

  IF NOT v_has_access THEN
    RAISE EXCEPTION 'Access denied to response data';
  END IF;

  -- Audit log (no sensitive data in metadata)
  INSERT INTO audit_journal (
    entity_type,
    entity_id,
    action,
    user_id,
    new_data
  ) VALUES (
    'questionnaire_responses',
    p_response_id,
    'SELECT',
    v_actor_id,
    jsonb_build_object('context', 'response_detail_view')
  );

  -- Build response detail
  SELECT jsonb_build_object(
    'id', qr.id,
    'user_id', qr.user_id,
    'questionnaire_id', qr.questionnaire_id,
    'responses', qr.responses,
    'score', qr.score,
    'completed_at', qr.completed_at,
    'created_at', qr.created_at,
    'questionnaire_version', qr.questionnaire_version,
    'response_version', qr.response_version,
    'questionnaire_name', q.name,
    'questionnaire_name_key', q.name_key,
    'questionnaire_code', q.code,
    'questionnaire_description', q.description,
    'questionnaire_description_key', q.description_key,
    'questionnaire_questions', q.questions,
    'questionnaire_type', q.questionnaire_type
  ) INTO v_result
  FROM questionnaire_responses qr
  JOIN questionnaires q ON q.id = qr.questionnaire_id
  WHERE qr.id = p_response_id;

  RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;

REVOKE ALL ON FUNCTION public.get_questionnaire_response_detail_audited(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_questionnaire_response_detail_audited(uuid) TO authenticated;


