-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_app_secrets.sql
-- -----------------------------------------------------------------------------

-- Function: public.edge_app_secrets
-- Purpose: Backend-only read/write access to API secrets via Postgres vault (encrypted at rest).
-- Storage: Reads from vault.decrypted_secrets, writes via vault.create_secret/update_secret.
-- Security: SECURITY DEFINER, service_role only

CREATE OR REPLACE FUNCTION public.edge_app_secrets(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_user_id uuid;
  v_key text;
  v_updated_by uuid;
  v_value text;
  v_existing_id uuid;
  v_description text;
BEGIN
  -- ── get_many: Read secrets from Vault ──────────────────────────
  IF p_action = 'get_many' THEN
    RETURN jsonb_build_object(
      'rows',
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'key', ds.name,
              'updated_at', ds.updated_at,
              'updated_by', CASE
                WHEN ds.description IS NOT NULL
                  AND ds.description ~ '^\{' -- is JSON
                THEN ds.description::jsonb ->> 'updated_by'
                ELSE NULL
              END,
              'value', ds.decrypted_secret
            )
          )
          FROM vault.decrypted_secrets ds
          WHERE ds.name = ANY(
            COALESCE(
              (
                SELECT array_agg(val)
                FROM jsonb_array_elements_text(
                  COALESCE(p_payload -> 'keys', '[]'::jsonb)
                ) AS t(val)
              ),
              ARRAY[]::text[]
            )
          )
        ),
        '[]'::jsonb
      )
    );
  END IF;

  -- ── upsert_admin: Write secret to Vault ────────────────────────
  IF p_action = 'upsert_admin' THEN
    v_actor_user_id := NULLIF(p_payload ->> 'actor_user_id', '')::uuid;
    v_key := NULLIF(p_payload ->> 'key', '');
    v_updated_by := NULLIF(p_payload ->> 'updated_by', '')::uuid;
    v_value := p_payload ->> 'value';

    IF v_actor_user_id IS NULL OR v_key IS NULL OR v_value IS NULL OR btrim(v_value) = '' THEN
      RAISE EXCEPTION 'Missing required payload fields';
    END IF;

    IF NOT public.has_role(v_actor_user_id, 'admin') THEN
      RAISE EXCEPTION 'Unauthorized: admin role required';
    END IF;

    v_description := jsonb_build_object(
      'updated_by', COALESCE(v_updated_by, v_actor_user_id)
    )::text;

    -- Check if secret already exists in vault
    SELECT id INTO v_existing_id FROM vault.secrets WHERE name = v_key;

    IF v_existing_id IS NOT NULL THEN
      PERFORM vault.update_secret(
        v_existing_id,   -- secret_id
        v_value,         -- new_secret (will be re-encrypted)
        v_key,           -- new_name
        v_description    -- new_description
      );
    ELSE
      PERFORM vault.create_secret(
        v_value,         -- new_secret (will be encrypted)
        v_key,           -- new_name
        v_description    -- new_description
      );
    END IF;

    RETURN jsonb_build_object('ok', true);
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_app_secrets(text, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.edge_app_secrets(text, jsonb) FROM authenticated;
REVOKE EXECUTE ON FUNCTION public.edge_app_secrets(text, jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.edge_app_secrets(text, jsonb) TO service_role;

COMMENT ON FUNCTION public.edge_app_secrets(text, jsonb) IS
  'Backend-only read/write for API secrets. Storage: Postgres vault (encrypted). Migrated from app_secrets table.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_database_dump_table.sql
-- -----------------------------------------------------------------------------

-- Function: public.edge_database_dump_table
-- Purpose: Export allowlisted public tables with explicit column lists generated from schema metadata.

CREATE OR REPLACE FUNCTION public.edge_database_dump_table(
  p_actor_user_id uuid,
  p_table text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_user_id uuid := auth.uid();
  v_jwt_role text := current_setting('request.jwt.claim.role', true);
  v_allowlist text[] := ARRAY[
    'archive_documents',
    'audit_journal',
    'cart_items',
    'consents',
    'data_sharing_consents',
    'dosing_logs',
    'health_check_ins',
    'invitations',
    'lab_results',
    'memberships',
    'member_health_documents',
    'notifications',
    'onboarding_responses',
    'order_items',
    'orders',
    'partner_appointments',
    'partner_availability',
    'partner_certifications',
    'partner_profiles',
    'products',
    'production_batches',
    'profiles',
    'studies',
    'study_registrations',
    'token_transactions',
    'user_roles'
  ];
  v_columns text;
  v_rows jsonb;
BEGIN
  IF v_actor_user_id IS NULL AND v_jwt_role = 'service_role' THEN
    v_actor_user_id := p_actor_user_id;
  END IF;

  IF v_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'Missing actor user';
  END IF;

  IF NOT public.has_role(v_actor_user_id, 'admin')
     AND NOT public.has_role(v_actor_user_id, 'staff') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF p_table IS NULL OR NOT (p_table = ANY(v_allowlist)) THEN
    RAISE EXCEPTION 'Table not allowlisted: %', p_table;
  END IF;

  SELECT string_agg(format('%I', c.column_name), ', ' ORDER BY c.ordinal_position)
  INTO v_columns
  FROM information_schema.columns c
  WHERE c.table_schema = 'public'
    AND c.table_name = p_table;

  IF v_columns IS NULL THEN
    RETURN jsonb_build_object('rows', '[]'::jsonb);
  END IF;

  EXECUTE format(
    'SELECT COALESCE(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) FROM (SELECT %s FROM public.%I) t',
    v_columns,
    p_table
  )
  INTO v_rows;

  RETURN jsonb_build_object('rows', COALESCE(v_rows, '[]'::jsonb));
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_database_dump_table(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edge_database_dump_table(uuid, text) TO service_role;
GRANT EXECUTE ON FUNCTION public.edge_database_dump_table(uuid, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_profiles.sql
-- -----------------------------------------------------------------------------

-- Function: public.edge_profiles
-- Purpose: Edge-safe profile access helpers.

CREATE OR REPLACE FUNCTION public.edge_profiles(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_user_id uuid;
  v_rows jsonb;
  v_stripe_customer_id text;
  v_user_id uuid;
BEGIN
  v_actor_user_id := auth.uid();

  IF auth.role() <> 'service_role' THEN
    IF v_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'Unauthorized';
    END IF;

    IF NOT public.has_role(v_actor_user_id, 'admin') AND NOT public.has_role(v_actor_user_id, 'staff') THEN
      RAISE EXCEPTION 'Unauthorized';
    END IF;
  END IF;

  IF p_action = 'get_languages' THEN
    RETURN jsonb_build_object(
      'rows',
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'preferred_language', p.preferred_language,
              'user_id', p.user_id
            )
          )
          FROM public.profiles p
          WHERE p.user_id = ANY(
            COALESCE(
              (
                SELECT array_agg(value::uuid)
                FROM jsonb_array_elements_text(COALESCE(p_payload -> 'user_ids', '[]'::jsonb)) AS t(value)
              ),
              ARRAY[]::uuid[]
            )
          )
        ),
        '[]'::jsonb
      )
    );
  END IF;

  IF p_action = 'get_user_ids' THEN
    RETURN jsonb_build_object(
      'rows',
      COALESCE(
        (
          SELECT jsonb_agg(jsonb_build_object('user_id', p.user_id))
          FROM public.profiles p
          WHERE p.user_id IS NOT NULL
        ),
        '[]'::jsonb
      )
    );
  END IF;

  IF p_action = 'get_user_profile' THEN
    v_user_id := NULLIF(p_payload ->> 'user_id', '')::uuid;

    IF v_user_id IS NULL THEN
      RAISE EXCEPTION 'Missing user_id';
    END IF;

    SELECT jsonb_build_object(
      'email', p.email,
      'first_name', p.first_name,
      'last_name', p.last_name,
      'preferred_language', p.preferred_language,
      'stripe_customer_id', p.stripe_customer_id,
      'user_id', p.user_id
    )
    INTO v_rows
    FROM public.profiles p
    WHERE p.user_id = v_user_id;

    RETURN jsonb_build_object('row', v_rows);
  END IF;

  IF p_action = 'set_stripe_customer' THEN
    v_user_id := NULLIF(p_payload ->> 'user_id', '')::uuid;
    v_stripe_customer_id := NULLIF(p_payload ->> 'stripe_customer_id', '');

    IF v_user_id IS NULL OR v_stripe_customer_id IS NULL THEN
      RAISE EXCEPTION 'Missing required payload fields';
    END IF;

    UPDATE public.profiles
    SET stripe_customer_id = v_stripe_customer_id,
        updated_at = now()
    WHERE user_id = v_user_id;

    RETURN jsonb_build_object('ok', true, 'updated', FOUND);
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_profiles(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edge_profiles(text, jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.edge_profiles(text, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_audit_journal_summary.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_audit_journal_summary
-- Arguments: p_limit integer, p_offset integer
-- Description: Returns audit journal summary for admin dashboard.
-- Security: SECURITY DEFINER, admin-only
-- Note: Returns 'action' (from action_type) and 'metadata' (from details) for API compatibility

CREATE OR REPLACE FUNCTION public.get_audit_journal_summary(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS TABLE(
   id uuid, 
   created_at timestamp with time zone, 
   user_email text, 
   user_role text, 
   action text, 
   entity_type text, 
   entity_id text, 
   area text, 
   severity text, 
   summary text, 
   blockchain_status text, 
   blockchain_tx_hash text,
   metadata jsonb
 )
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Only admins can access audit journal
  IF NOT has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;
  
  RETURN QUERY
  SELECT 
    aj.id, 
    aj.created_at, 
    aj.user_email, 
    aj.user_role, 
    aj.action_type::text AS action,
    COALESCE(aj.details->>'entity_type', aj.entity_type)::text AS entity_type, 
    COALESCE(aj.details->>'entity_id', aj.entity_id)::text AS entity_id, 
    COALESCE(aj.details->>'area', aj.area::text)::text AS area, 
    COALESCE(aj.details->>'severity', aj.severity::text)::text AS severity, 
    aj.summary,
    aj.blockchain_status, 
    aj.blockchain_tx_hash,
    aj.details AS metadata
  FROM audit_journal aj
  ORDER BY aj.created_at DESC
  LIMIT p_limit OFFSET p_offset;
END;
$function$
;

