-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/hr_druhy_osob_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: hr_druhy_osob_admin
-- Popis: Druhy twinů a kolik z nich nemá účet — nabídka filtru HR obrazovky.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT; jen admin/staff nebo service_role
--
-- ⛔ NAMĚŘENO 2026-09-23 po nasazení „Lidí a účtů" na produkci: seznam osob bez
--    účtu bez filtru obsahuje i 2 286 firem a nabídka druhů se skládala z prvních
--    200 načtených položek — když byly abecedně napřed firmy, „driver" v nabídce
--    NEBYL a HR by řidiče nenašlo jinak než hledáním jména.
--
-- ⛔ DRUHY SE NEDOSAZUJÍ: kód nezná slovo „driver" ani „company" (parametry
--    rozhodují, čím entita je). Nabídka je ODVOZENÁ z dat — každý druh s aktivními
--    twiny, s počtem těch bez účtu, aby HR vidělo, kde je práce.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.hr_druhy_osob_admin()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_items jsonb;
BEGIN
  IF NOT ((SELECT public.is_service_role()) OR (SELECT public.is_admin_or_staff())) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('entity_type', d.entity_type, 'celkem', d.celkem, 'bez_uctu', d.bez_uctu)
                            ORDER BY d.bez_uctu DESC, d.entity_type), '[]'::jsonb)
    INTO v_items
  FROM (
    SELECT t.entity_type,
           count(*) AS celkem,
           count(*) FILTER (WHERE NOT EXISTS (
             SELECT 1 FROM public.twin_external_refs r
              WHERE r.twin_id = t.id AND r.ref_kind = 'account' AND r.state = 'confirmed'
                AND r.valid_from <= now() AND (r.valid_to IS NULL OR r.valid_to > now()))) AS bez_uctu
      FROM public.twin_entities t
     WHERE t.status = 'active'
     GROUP BY t.entity_type
  ) d;

  RETURN jsonb_build_object('items', v_items);
END;
$$;

REVOKE ALL ON FUNCTION public.hr_druhy_osob_admin() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.hr_druhy_osob_admin() TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/hr_ucty_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: hr_ucty_admin
-- Popis: Účty platformy a OSOBA (twin), na kterou je každý navázaný — druhá
--        půlka HR obrazovky „Lidé a účty" (první je twin_accounts_missing:
--        osoby bez účtu).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT; jen admin/staff nebo service_role (PII)
--
-- ⭐ ZADÁNÍ MAJITELE (2026-09-23): „obrazovka speciálně pro HR, kdy účty v KC
-- propojujeme s entitami z twinverse".
--
-- ⛔ ÚČET = ŘÁDEK V `profiles`, tedy účet, který se aspoň JEDNOU přihlásil.
-- Keycloak zná i účty, které se nikdy nepřihlásily — ty tu nejsou, protože
-- vazba se váže na `sub`, a ten platforma zná až od prvního přihlášení. Stejně
-- jako stránka Role. UI to řekne, místo aby účet tiše chyběl.
--
-- ⛔ ODVOZENÉ, NE ULOŽENÉ: „osoba účtu" je potvrzená a platná `account` vazba
-- (táž podmínka jako workflow_step_visible_to a twin_for_account). Žádný sloupec
-- navíc, který by se s vazbami rozešel.
--
-- Hledání ve jméně, e-mailu i jménu navázané osoby; `limitovano` jako
-- u twin_accounts_missing („našlo se 200" ≠ „našlo se všech 200").
-- ============================================================================
CREATE OR REPLACE FUNCTION public.hr_ucty_admin(
  p_hledat text DEFAULT NULL,
  p_limit integer DEFAULT 200
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_items jsonb;
  v_limit int := GREATEST(1, LEAST(COALESCE(p_limit, 200), 500));
  v_limitovano boolean := false;
  v_vzor text := CASE WHEN p_hledat IS NULL OR btrim(p_hledat) = '' THEN NULL
                      ELSE '%' || replace(replace(replace(btrim(p_hledat), '\', '\\'), '%', '\%'), '_', '\_') || '%'
                 END;
BEGIN
  IF NOT ((SELECT public.is_service_role()) OR (SELECT public.is_admin_or_staff())) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'jmeno_razeni'), '[]'::jsonb)
    INTO v_items
  FROM (
    SELECT jsonb_build_object(
             'user_id', p.user_id,
             'email', p.email,
             'jmeno', COALESCE(NULLIF(btrim(p.display_name), ''),
                               NULLIF(btrim(concat_ws(' ', p.first_name, p.last_name)), '')),
             'jmeno_razeni', lower(COALESCE(NULLIF(btrim(p.display_name), ''), p.email, p.user_id::text)),
             'vytvoreno', p.created_at,
             'osoba', (SELECT jsonb_build_object(
                                'ref_id', r.id,
                                'twin_id', t.id,
                                'label', t.label,
                                'entity_type', t.entity_type,
                                'od', r.valid_from)
                         FROM public.twin_external_refs r
                         JOIN public.twin_entities t ON t.id = r.twin_id
                        WHERE r.ref_kind = 'account'
                          AND r.source_key = p.user_id::text
                          AND r.state = 'confirmed'
                          AND r.valid_from <= now()
                          AND (r.valid_to IS NULL OR r.valid_to > now())
                        LIMIT 1)
           ) AS x
      FROM public.profiles p
     WHERE p.user_id IS NOT NULL
       AND (v_vzor IS NULL
            OR p.email ILIKE v_vzor
            OR p.display_name ILIKE v_vzor
            OR concat_ws(' ', p.first_name, p.last_name) ILIKE v_vzor
            OR EXISTS (SELECT 1
                         FROM public.twin_external_refs r
                         JOIN public.twin_entities t ON t.id = r.twin_id
                        WHERE r.ref_kind = 'account'
                          AND r.source_key = p.user_id::text
                          AND r.state = 'confirmed'
                          AND (r.valid_to IS NULL OR r.valid_to > now())
                          AND t.label ILIKE v_vzor))
     ORDER BY lower(COALESCE(NULLIF(btrim(p.display_name), ''), p.email, p.user_id::text))
     LIMIT v_limit + 1
  ) s;

  IF jsonb_array_length(v_items) > v_limit THEN
    v_items := v_items - v_limit;
    v_limitovano := true;
  END IF;

  RETURN jsonb_build_object('items', v_items, 'count', jsonb_array_length(v_items),
                            'limitovano', v_limitovano);
END;
$$;

REVOKE ALL ON FUNCTION public.hr_ucty_admin(text, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.hr_ucty_admin(text, integer) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/hub_apply_reprice.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: hub_apply_reprice
-- Popis: Apply a CONFIRMED repricing proposal into the target — the final stage of
--        the cenotvorba loop. The connector service does the target's
--        price_put FIRST, then calls this to record applied + post a typed
--        `reprice_applied` story_entry (the operator sees the resolution in the
--        story they confirmed in). Gated on status='confirmed'. service_role/admin/staff.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT.
-- Pár: aisha/db/migrations/20260627190000_hub_reprice_apply.sql
-- ============================================================================

CREATE OR REPLACE FUNCTION public.hub_apply_reprice(
  p_proposal_id uuid, p_applied_ref jsonb DEFAULT '{}'::jsonb, p_applied_by uuid DEFAULT NULL)
RETURNS public.hub_reprice_proposal
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $$
DECLARE v_row public.hub_reprice_proposal; v_actor uuid; v_audit_actor uuid;
BEGIN
  -- service_role (the connector, AFTER the human gate) OR admin/staff (direct).
  IF NOT (public.is_service_role())
     AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  v_actor := COALESCE(p_applied_by, auth.uid());

  -- ONLY a confirmed proposal may be applied (not pending, not rejected, not re-applied).
  UPDATE public.hub_reprice_proposal SET
    status = 'applied', applied_by = v_actor, applied_at = now(),
    applied_ref = COALESCE(p_applied_ref, '{}'::jsonb), updated_at = now()
  WHERE id = p_proposal_id AND status = 'confirmed'
  RETURNING * INTO v_row;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'No confirmed proposal to apply %', p_proposal_id; END IF;

  -- Audit must never block a real operation: the target write already landed, so an
  -- actor absent from aisha_auth.users (e.g. an admin whose JIT row was never
  -- provisioned) must NOT roll the apply back on the audit FK. Null it for the audit
  -- only (applied_by has no FK, so it keeps the true operator id for provenance).
  v_audit_actor := v_actor;
  IF v_audit_actor IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM aisha_auth.users u WHERE u.id = v_audit_actor) THEN
    v_audit_actor := NULL;
  END IF;

  -- verifiable audit (v2 blockchain_hash) — dealer can prove this apply is untampered.
  PERFORM public.hub_write_audit(
    'hub_reprice.applied', 'curation', 'content', 'info',
    'Repricing proposal applied into the target',
    'hub_reprice_proposal', p_proposal_id::text,
    jsonb_build_object('proposed_price_retail', v_row.proposed_price_retail,
                       'applied_ref', COALESCE(p_applied_ref, '{}'::jsonb)),
    v_audit_actor);

  -- The operator sees the resolution in the same story they confirmed in.
  IF v_row.story_id IS NOT NULL THEN
    INSERT INTO public.story_entries
      (story_id, subject_type, subject_id, entry_type, content, metadata, created_by, occurred_at)
    VALUES
      (v_row.story_id, 'story', v_row.story_id, 'reprice_applied',
       format('Cena aplikována do cílového systému: %s %s', v_row.proposed_price_retail::text,
              COALESCE(v_row.context->>'currency', public.commerce_base_currency())),
       jsonb_build_object('proposal_id', v_row.id, 'proposed_price_retail', v_row.proposed_price_retail,
         'applied_ref', COALESCE(p_applied_ref, '{}'::jsonb)),
       COALESCE(v_actor, '00000000-0000-4000-a000-00000000a070'::uuid), now());
  END IF;

  RETURN v_row;
END; $$;

REVOKE ALL ON FUNCTION public.hub_apply_reprice(uuid,jsonb,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.hub_apply_reprice(uuid,jsonb,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.hub_apply_reprice(uuid,jsonb,uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/hub_assert_source_writable.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: hub_assert_source_writable
-- Popis: The fail-closed governance gate every connector WRITE passes before it
--        mutates. Resolves the story-spine binding (audience_resolve_source_binding)
--        and RAISEs unless the source is APPROVED and classified. Makes "a source
--        cannot be written unless onboarded/approved" a DB law, not a convention.
--
-- Called from connector write procs with the source's story reference. Returns the
-- resolved data_sensitivity (so the caller can enforce retention/PII rules) — or
-- RAISEs 42501 if unapproved / no binding. Fail-closed by construction: an absent
-- instance, absent binding, or source_approved=false all deny.
--
-- Internal-only: REVOKEd from PUBLIC (callers are SECURITY DEFINER, run as owner).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.hub_assert_source_writable(
  p_story_id      uuid,
  p_endpoint_role text DEFAULT 'control-api'
)
RETURNS text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_sensitivity text;
  v_approved    boolean;
  v_found       boolean := false;
BEGIN
  -- Self-gate (defense in depth; the inner resolver also gates): only a trusted
  -- caller may probe source approval.
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required'
      USING ERRCODE = '42501';
  END IF;

  IF p_story_id IS NULL THEN
    RAISE EXCEPTION 'hub_assert_source_writable: story reference is required'
      USING ERRCODE = '42501';
  END IF;

  -- audience_resolve_source_binding self-gates (service_role or admin/staff) and
  -- fail-closes classification/approval (unclassified => 'restricted', unapproved
  -- => false). It RAISEs no_data_found when no active instance materializes.
  BEGIN
    SELECT rb.data_sensitivity, rb.is_approved
      INTO v_sensitivity, v_approved
    FROM public.audience_resolve_source_binding(p_story_id, p_endpoint_role) rb
    LIMIT 1;
    v_found := FOUND;
  EXCEPTION WHEN no_data_found THEN
    RAISE EXCEPTION 'hub_assert_source_writable: no active instance for story %', p_story_id
      USING ERRCODE = '42501';
  END;

  IF NOT v_found OR v_approved IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'hub_assert_source_writable: source for story % (%s) is not approved',
      p_story_id, p_endpoint_role
      USING ERRCODE = '42501';
  END IF;

  RETURN COALESCE(v_sensitivity, 'restricted');
END;
$$;

-- Read-only approval check (no mutation); wraps audience_resolve_source_binding,
-- which is itself granted authenticated+service_role — same exposure.
REVOKE ALL ON FUNCTION public.hub_assert_source_writable(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.hub_assert_source_writable(uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.hub_assert_source_writable(uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/hub_compute_price.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: hub_compute_price
-- Popis: The hamburger composer — stack the active, condition-matching layers
--        over price_buy and return {price_buy, price_retail, currency, breakdown}.
--        Conditions: category/brand/product_type/tenant_id/season/weather (exact),
--        min_qty/max_qty/min_age_days/max_age_days/fx_above/fx_below (range).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (admin/staff or service).
-- Pár: aisha/db/migrations/20260627150000_hub_price_layers.sql
-- ============================================================================

CREATE OR REPLACE FUNCTION public.hub_compute_price(p_context jsonb)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $$
DECLARE
  v_buy       numeric := COALESCE((p_context->>'price_buy')::numeric, 0);
  v_running   numeric := v_buy;
  v_qty       integer := COALESCE((p_context->>'quantity')::int, 1);
  v_breakdown jsonb := '[]'::jsonb;
  v_layer     public.hub_price_layer;
  v_cond      jsonb;
  v_match     boolean;
  v_delta     numeric;
BEGIN
  IF NOT (public.is_service_role())
     AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  FOR v_layer IN SELECT id, slug, name, layer_kind, value_kind, value, condition, target_kind, target_price_type, target_source_price_type, sort_order, is_active, created_at, updated_at FROM public.hub_price_layer WHERE is_active ORDER BY sort_order, slug LOOP
    v_cond := COALESCE(v_layer.condition, '{}'::jsonb);
    v_match := true;
    IF v_cond ? 'category'     AND COALESCE(p_context->>'category','')     <> (v_cond->>'category')     THEN v_match := false; END IF;
    IF v_cond ? 'brand'        AND COALESCE(p_context->>'brand','')        <> (v_cond->>'brand')        THEN v_match := false; END IF;
    IF v_cond ? 'product_type' AND COALESCE(p_context->>'product_type','') <> (v_cond->>'product_type') THEN v_match := false; END IF;
    IF v_cond ? 'tenant_id'    AND COALESCE(p_context->>'tenant_id','')    <> (v_cond->>'tenant_id')    THEN v_match := false; END IF;
    IF v_cond ? 'season'       AND COALESCE(p_context->>'season','')       <> (v_cond->>'season')       THEN v_match := false; END IF;
    IF v_cond ? 'weather'      AND COALESCE(p_context->>'weather','')      <> (v_cond->>'weather')      THEN v_match := false; END IF;
    IF v_cond ? 'min_qty'      AND v_qty < (v_cond->>'min_qty')::int       THEN v_match := false; END IF;
    IF v_cond ? 'max_qty'      AND v_qty > (v_cond->>'max_qty')::int       THEN v_match := false; END IF;
    IF v_cond ? 'min_age_days' AND COALESCE((p_context->>'age_days')::numeric, 0)   < (v_cond->>'min_age_days')::numeric THEN v_match := false; END IF;
    IF v_cond ? 'max_age_days' AND COALESCE((p_context->>'age_days')::numeric, 1e9) > (v_cond->>'max_age_days')::numeric THEN v_match := false; END IF;
    IF v_cond ? 'fx_above'     AND COALESCE((p_context->>'fx_rate')::numeric, 0)     <= (v_cond->>'fx_above')::numeric    THEN v_match := false; END IF;
    IF v_cond ? 'fx_below'     AND COALESCE((p_context->>'fx_rate')::numeric, 1e9)   >= (v_cond->>'fx_below')::numeric    THEN v_match := false; END IF;

    IF v_match THEN
      v_delta := CASE v_layer.value_kind
        WHEN 'percent'  THEN v_running * v_layer.value / 100.0
        WHEN 'absolute' THEN v_layer.value
        ELSE 0 END;
      v_running := v_running + v_delta;
      v_breakdown := v_breakdown || jsonb_build_object(
        'slug', v_layer.slug, 'name', v_layer.name, 'kind', v_layer.layer_kind,
        'value_kind', v_layer.value_kind, 'value', v_layer.value,
        'delta', round(v_delta, 2), 'running', round(v_running, 2));
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'price_buy', v_buy, 'price_retail', round(v_running, 2),
    'currency', COALESCE(p_context->>'currency', public.commerce_base_currency()), 'breakdown', v_breakdown);
END; $$;

REVOKE ALL ON FUNCTION public.hub_compute_price(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.hub_compute_price(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.hub_compute_price(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/hub_compose_propagation_plan.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: hub_compose_propagation_plan
-- Popis: Turn the hamburger composition into a TARGET PROPAGATION PLAN. The commerce
--        target already owns pricing (collection rules + price_calculate); AISHA composes/
--        simulates and propagates AS the user. This reuses hub_compute_price's exact
--        condition-matching (the simulation) and classifies each MATCHED layer:
--          • native ('rule')      → a target-native product_collection_price rule
--                                    (amount/percentage) to set + refresh on the collection;
--          • non-native ('simulated': date/quantity/customer) → folded into the
--                                    simulated price and pushed PRE-CALCULATED (specific_price_put).
--        The connector then drives the target (refresh_prices / specific_price_put) as the
--        federated caller. AISHA never reimplements the target's pricing — it propagates into it.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (service/admin/staff).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.hub_compose_propagation_plan(
  p_context jsonb, p_collection_id text DEFAULT NULL, p_instance_id text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $$
DECLARE
  v_sim       jsonb;
  v_entry     jsonb;
  v_layer     public.hub_price_layer;
  v_rules     jsonb := '[]'::jsonb;
  v_simulated jsonb := '[]'::jsonb;
BEGIN
  IF NOT (public.is_service_role())
     AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  -- The hamburger simulation (reuses the exact condition-matching of hub_compute_price).
  v_sim := public.hub_compute_price(p_context);

  -- Classify each MATCHED layer (breakdown = the layers that applied).
  FOR v_entry IN SELECT * FROM jsonb_array_elements(v_sim->'breakdown') LOOP
    SELECT * INTO v_layer FROM public.hub_price_layer WHERE slug = v_entry->>'slug';
    IF v_layer.target_kind = 'simulated' THEN
      v_simulated := v_simulated || jsonb_build_object(
        'slug', v_layer.slug, 'name', v_layer.name, 'delta', v_entry->'delta',
        'reason', 'non-native in the target (date/quantity/customer) — push the pre-calculated price');
    ELSE
      -- target-native product_collection_price rule
      v_rules := v_rules || jsonb_build_object(
        'slug', v_layer.slug, 'name', v_layer.name, 'layer_kind', v_layer.layer_kind,
        'price_type', v_layer.target_price_type, 'source_price_type', v_layer.target_source_price_type,
        'percentage', CASE WHEN v_layer.value_kind = 'percent'  THEN v_layer.value ELSE NULL END,
        'amount',     CASE WHEN v_layer.value_kind = 'absolute' THEN v_layer.value ELSE NULL END,
        'set_with_vat', false);
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'collection_id',    p_collection_id,
    'instance_id',      p_instance_id,
    'currency',         v_sim->>'currency',
    'simulated_price',  (v_sim->>'price_retail')::numeric,
    'rules',            v_rules,                              -- set + refresh_prices on the collection
    'simulated_layers', v_simulated,                          -- push the pre-calculated price
    'pre_calc_required', jsonb_array_length(v_simulated) > 0, -- did any non-native layer apply?
    'simulation',       v_sim);
END; $$;

REVOKE ALL ON FUNCTION public.hub_compose_propagation_plan(jsonb,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.hub_compose_propagation_plan(jsonb,text,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.hub_compose_propagation_plan(jsonb,text,text) TO service_role;


