-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/hub_upsert_supplier_offer.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: hub_upsert_supplier_offer
-- Popis: Connector write — idempotent UPSERT of a supplier offer (EDI/PRICAT). service.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT.
-- Pár: aisha/db/migrations/20260627160000_hub_supplier_offer_reprice.sql
-- ============================================================================

CREATE OR REPLACE FUNCTION public.hub_upsert_supplier_offer(p_payload jsonb)
RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $$
DECLARE v_id uuid;
BEGIN
  IF NOT (public.is_service_role()) THEN
    RAISE EXCEPTION 'Unauthorized: service_role required';
  END IF;
  INSERT INTO public.hub_supplier_offer
    (source_id, supplier_sku, ean, product_type, brand, title, size, season,
     price_buy, currency, stock_qty, warehouse, valid_from, snapshot_token, refreshed_at)
  VALUES
    ((p_payload->>'source_id')::uuid, p_payload->>'supplier_sku', p_payload->>'ean',
     p_payload->>'product_type', p_payload->>'brand', p_payload->>'title', p_payload->>'size',
     p_payload->>'season', (p_payload->>'price_buy')::numeric, COALESCE(p_payload->>'currency', public.commerce_base_currency()),
     (p_payload->>'stock_qty')::int, p_payload->>'warehouse', (p_payload->>'valid_from')::date,
     p_payload->>'snapshot_token', now())
  ON CONFLICT (source_id, supplier_sku) DO UPDATE SET
    ean=EXCLUDED.ean, product_type=EXCLUDED.product_type, brand=EXCLUDED.brand, title=EXCLUDED.title,
    size=EXCLUDED.size, season=EXCLUDED.season, price_buy=EXCLUDED.price_buy, currency=EXCLUDED.currency,
    stock_qty=EXCLUDED.stock_qty, warehouse=EXCLUDED.warehouse, valid_from=EXCLUDED.valid_from,
    snapshot_token=EXCLUDED.snapshot_token, refreshed_at=now(), updated_at=now()
  RETURNING id INTO v_id;
  RETURN v_id;
END; $$;

REVOKE ALL ON FUNCTION public.hub_upsert_supplier_offer(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.hub_upsert_supplier_offer(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/hub_verify_provenance.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: hub_verify_provenance
-- Popis: Generic provenance check for ANY connector action, keyed by the business
--        entity (not the internal audit id). Finds the latest audit_journal row
--        matching (entity_type, entity_id, action) and returns
--        fn_verify_audit_journal_entry's verdict. The universal generalization of
--        hub_verify_reprice_provenance — any connector state change is provable.
--
-- Returns jsonb: { entity_type, entity_id, action, state, audit_id, decided_at,
--   stored_hash }. state ∈ verified | broken | unverifiable_legacy | no_hash |
--   no_audit (no matching row). Gated admin/staff OR service_role.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.hub_verify_provenance(
  p_entity_type text,
  p_entity_id   text,
  p_action      text
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
  v_audit  public.audit_journal%ROWTYPE;
  v_verify jsonb;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  SELECT * INTO v_audit
  FROM public.audit_journal
  WHERE entity_type = p_entity_type
    AND entity_id   = p_entity_id
    AND action      = p_action
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_audit.id IS NULL THEN
    RETURN jsonb_build_object(
      'entity_type', p_entity_type, 'entity_id', p_entity_id, 'action', p_action,
      'state', 'no_audit', 'audit_id', NULL);
  END IF;

  v_verify := public.fn_verify_audit_journal_entry(v_audit.id);

  RETURN jsonb_build_object(
    'entity_type', p_entity_type, 'entity_id', p_entity_id, 'action', p_action,
    'state', v_verify ->> 'state',
    'audit_id', v_audit.id,
    'decided_at', v_audit.created_at,
    'stored_hash', v_verify ->> 'stored_hash');
END;
$$;

REVOKE ALL ON FUNCTION public.hub_verify_provenance(text, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.hub_verify_provenance(text, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.hub_verify_provenance(text, text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/hub_verify_reprice_provenance.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: hub_verify_reprice_provenance
-- Popis: Dealer-facing provenance check for a repricing proposal — thin wrapper
--        over the generic hub_verify_provenance, keyed by the proposal id. Kept as
--        a stable name for the Cenotvorba cockpit (verifyProvenance query). Returns
--        { proposal_id, state, audit_id, decided_at, stored_hash }; state='no_audit'
--        when not yet applied. Gated admin/staff OR service_role (inherited).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.hub_verify_reprice_provenance(
  p_proposal_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
  v jsonb;
BEGIN
  v := public.hub_verify_provenance('hub_reprice_proposal', p_proposal_id::text, 'hub_reprice.applied');
  RETURN jsonb_build_object(
    'proposal_id', p_proposal_id,
    'state',       v ->> 'state',
    'audit_id',    v -> 'audit_id',
    'decided_at',  v -> 'decided_at',
    'stored_hash', v ->> 'stored_hash');
END;
$$;

REVOKE ALL ON FUNCTION public.hub_verify_reprice_provenance(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.hub_verify_reprice_provenance(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.hub_verify_reprice_provenance(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/ingest_sentry_issue.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: ingest_sentry_issue
-- Popis: Insert Sentry issue snapshot. Idempotent on (sentry_issue_id, observed_at).
--        Volaný z WF_SENTRY_INGEST nebo rozšířeného WF_SENTRY_MONITOR (po Sentry API call).
-- Volá: WF_SENTRY_INGEST, WF_SENTRY_MONITOR
-- Auth: service_role nebo admin/staff
-- ============================================================================

CREATE OR REPLACE FUNCTION public.ingest_sentry_issue(p_payload jsonb)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id uuid;
  v_is_service boolean;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Idempotent: skip pokud existuje
  SELECT id INTO v_id
  FROM public.sentry_issue_snapshot
  WHERE sentry_issue_id = p_payload->>'sentry_issue_id'
    AND observed_at = (p_payload->>'observed_at')::timestamptz;

  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  INSERT INTO public.sentry_issue_snapshot (
    sentry_issue_id, app_name, project_slug, level, title,
    first_seen, last_seen, count, user_count, status, release, permalink, metadata
  )
  VALUES (
    p_payload->>'sentry_issue_id',
    p_payload->>'app_name',
    p_payload->>'project_slug',
    COALESCE(p_payload->>'level', 'error'),
    COALESCE(p_payload->>'title', '(no title)'),
    (p_payload->>'first_seen')::timestamptz,
    COALESCE((p_payload->>'last_seen')::timestamptz, now()),
    COALESCE((p_payload->>'count')::int, 1),
    COALESCE((p_payload->>'user_count')::int, 0),
    COALESCE(p_payload->>'status', 'unresolved'),
    p_payload->>'release',
    p_payload->>'permalink',
    COALESCE(p_payload->'metadata', '{}'::jsonb)
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.ingest_sentry_issue(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.ingest_sentry_issue(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ingest_sentry_issue(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/insert_audit_journal_entry.sql
-- -----------------------------------------------------------------------------

-- insert_audit_journal_entry: Wrapper for edge functions to log audit events
-- Called by: toolExecutor.ts (service), n8n (service), mobile-app biometric (sám za sebe)
-- Security: za cizí user_id smí psát jen service_role (2026-09-19).
CREATE OR REPLACE FUNCTION public.insert_audit_journal_entry(
  p_action text,
  p_metadata jsonb DEFAULT '{}'::jsonb,
  p_user_id uuid DEFAULT auth.uid()
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  -- ⛔ PODVRH AUDITU POD CIZÍM JMÉNEM (naměřeno 2026-09-19). GRANT pro
  -- `authenticated` + volný p_user_id znamenal, že kterýkoli přihlášený zapsal
  -- do audit_journal záznam s `user_id` KOHOKOLI — tedy „tohle udělal admin X".
  -- Audit, do kterého smí psát cizí jménem kdokoli, nic nedokazuje.
  --
  -- Za jiného smí psát jen služba (toolExecutor, n8n — nesou service klíč
  -- a user_id z ověřeného kontextu). Správa NE: audit je právě místo, kde se
  -- nesmí vydávat za jiného ani správce. Změřeno, že to nic nerozbije: mobilní
  -- appka (biometric) p_user_id neposílá (výchozí = volající), toolExecutor
  -- a n8n volají service klíčem. `IS DISTINCT FROM` + `auth.uid() IS NULL`
  -- drží stráž NULL-bezpečnou.
  IF NOT public.is_service_role()
     AND (auth.uid() IS NULL OR p_user_id IS DISTINCT FROM auth.uid())
  THEN
    RAISE EXCEPTION 'Unauthorized: audit entry may only be written for the caller'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (p_user_id, p_action, p_metadata);
END;
$$;

REVOKE ALL ON FUNCTION public.insert_audit_journal_entry(text, jsonb, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.insert_audit_journal_entry(text, jsonb, uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.insert_audit_journal_entry(text, jsonb, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/insert_eval_result.sql
-- -----------------------------------------------------------------------------

-- Function: insert_eval_result
-- Description: Inserts an evaluation result for an AI eval run
-- Security: SECURITY DEFINER

CREATE OR REPLACE FUNCTION public.insert_eval_result(
  p_eval_run_id uuid,
  p_message_id uuid DEFAULT NULL::uuid,
  p_conversation_id uuid DEFAULT NULL::uuid,
  p_relevance numeric DEFAULT 0,
  p_groundedness numeric DEFAULT 0,
  p_safety numeric DEFAULT 0,
  p_coherence numeric DEFAULT 0,
  p_overall numeric DEFAULT 0,
  p_reasoning text DEFAULT NULL::text,
  p_evaluator_model text DEFAULT 'gpt-4o-mini'::text,
  p_tokens_used integer DEFAULT NULL::integer,
  p_latency_ms integer DEFAULT NULL::integer,
  p_golden_example_id uuid DEFAULT NULL::uuid
)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result_id uuid;
  v_completed integer;
  v_total integer;
  v_is_service BOOLEAN;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Service role or admin required';
  END IF;

  INSERT INTO ai_eval_results (
    eval_run_id, message_id, conversation_id, golden_example_id,
    relevance_score, groundedness_score, safety_score,
    coherence_score, overall_score, reasoning,
    evaluator_model, tokens_used, latency_ms
  ) VALUES (
    p_eval_run_id, p_message_id, p_conversation_id, p_golden_example_id,
    p_relevance, p_groundedness, p_safety,
    p_coherence, p_overall, p_reasoning,
    p_evaluator_model, p_tokens_used, p_latency_ms
  )
  RETURNING id INTO v_result_id;

  -- Update the message's eval_score (only if message_id provided)
  IF p_message_id IS NOT NULL THEN
    UPDATE chat_messages
    SET eval_score = jsonb_build_object(
      'relevance', p_relevance,
      'groundedness', p_groundedness,
      'safety', p_safety,
      'coherence', p_coherence,
      'overall', p_overall,
      'eval_run_id', p_eval_run_id,
      'evaluated_at', now()
    )
    WHERE id = p_message_id;
  END IF;

  -- Update run progress + aggregates
  SELECT COUNT(*) INTO v_completed FROM ai_eval_results WHERE eval_run_id = p_eval_run_id;
  SELECT total_examples INTO v_total FROM ai_eval_runs WHERE id = p_eval_run_id;

  UPDATE ai_eval_runs
  SET completed_examples = v_completed,
      status = CASE WHEN v_completed >= v_total THEN 'completed' ELSE 'running' END,
      started_at = COALESCE(started_at, now()),
      completed_at = CASE WHEN v_completed >= v_total THEN now() ELSE NULL END,
      avg_relevance = sub.avg_r,
      avg_groundedness = sub.avg_g,
      avg_safety = sub.avg_s,
      avg_coherence = sub.avg_c,
      avg_overall = sub.avg_o
  FROM (
    SELECT
      AVG(relevance_score) AS avg_r,
      AVG(groundedness_score) AS avg_g,
      AVG(safety_score) AS avg_s,
      AVG(coherence_score) AS avg_c,
      AVG(overall_score) AS avg_o
    FROM ai_eval_results
    WHERE eval_run_id = p_eval_run_id
  ) sub
  WHERE ai_eval_runs.id = p_eval_run_id;

  -- When run is completed, compute score_delta vs previous run
  IF v_completed >= v_total THEN
    UPDATE ai_eval_runs er
    SET score_delta = er.avg_overall - prev.avg_overall
    FROM ai_eval_runs prev
    WHERE er.id = p_eval_run_id
      AND prev.id = er.previous_run_id
      AND prev.avg_overall IS NOT NULL;
  END IF;

  RETURN v_result_id;
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.insert_eval_result(uuid,uuid,uuid,numeric,numeric,numeric,numeric,numeric,text,text,integer,integer,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.insert_eval_result(uuid,uuid,uuid,numeric,numeric,numeric,numeric,numeric,text,text,integer,integer,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.insert_eval_result(uuid,uuid,uuid,numeric,numeric,numeric,numeric,numeric,text,text,integer,integer,uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/insert_model_benchmark.sql
-- -----------------------------------------------------------------------------

-- Function: insert_model_benchmark

CREATE OR REPLACE FUNCTION public.insert_model_benchmark(p_model_registry_id uuid, p_task_type text, p_relevance numeric DEFAULT NULL::numeric, p_groundedness numeric DEFAULT NULL::numeric, p_safety numeric DEFAULT NULL::numeric, p_coherence numeric DEFAULT NULL::numeric, p_overall numeric DEFAULT NULL::numeric, p_avg_latency_ms integer DEFAULT NULL::integer, p_p95_latency_ms integer DEFAULT NULL::integer, p_avg_tokens_input integer DEFAULT NULL::integer, p_avg_tokens_output integer DEFAULT NULL::integer, p_avg_cost_per_call numeric DEFAULT NULL::numeric, p_success_rate numeric DEFAULT NULL::numeric, p_timeout_rate numeric DEFAULT NULL::numeric, p_error_rate numeric DEFAULT NULL::numeric, p_eval_run_id uuid DEFAULT NULL::uuid, p_sample_count integer DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_benchmark_id uuid;
BEGIN
  IF NOT (
    public.is_service_role()
    OR is_admin_or_staff()
  ) THEN
    RAISE EXCEPTION 'Service role or admin required';
  END IF;

  INSERT INTO ai_model_benchmarks (
    model_registry_id, task_type,
    relevance_score, groundedness_score, safety_score, coherence_score, overall_score,
    avg_latency_ms, p95_latency_ms,
    avg_tokens_input, avg_tokens_output, avg_cost_per_call,
    success_rate, timeout_rate, error_rate,
    eval_run_id, sample_count
  ) VALUES (
    p_model_registry_id, p_task_type,
    p_relevance, p_groundedness, p_safety, p_coherence, p_overall,
    p_avg_latency_ms, p_p95_latency_ms,
    p_avg_tokens_input, p_avg_tokens_output, p_avg_cost_per_call,
    p_success_rate, p_timeout_rate, p_error_rate,
    p_eval_run_id, p_sample_count
  )
  ON CONFLICT (model_registry_id, task_type, eval_run_id)
  DO UPDATE SET
    relevance_score = EXCLUDED.relevance_score,
    groundedness_score = EXCLUDED.groundedness_score,
    safety_score = EXCLUDED.safety_score,
    coherence_score = EXCLUDED.coherence_score,
    overall_score = EXCLUDED.overall_score,
    avg_latency_ms = EXCLUDED.avg_latency_ms,
    p95_latency_ms = EXCLUDED.p95_latency_ms,
    avg_tokens_input = EXCLUDED.avg_tokens_input,
    avg_tokens_output = EXCLUDED.avg_tokens_output,
    avg_cost_per_call = EXCLUDED.avg_cost_per_call,
    success_rate = EXCLUDED.success_rate,
    timeout_rate = EXCLUDED.timeout_rate,
    error_rate = EXCLUDED.error_rate,
    sample_count = EXCLUDED.sample_count,
    measured_at = now()
  RETURNING id INTO v_benchmark_id;

  RETURN v_benchmark_id;
END;
$function$;

REVOKE ALL ON FUNCTION insert_model_benchmark(uuid, text, numeric, numeric, numeric, numeric, numeric, integer, integer, integer, integer, numeric, numeric, numeric, numeric, uuid, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION insert_model_benchmark(uuid,text,numeric,numeric,numeric,numeric,numeric,integer,integer,integer,integer,numeric,numeric,numeric,numeric,uuid,integer) TO authenticated;
GRANT EXECUTE ON FUNCTION insert_model_benchmark(uuid,text,numeric,numeric,numeric,numeric,numeric,integer,integer,integer,integer,numeric,numeric,numeric,numeric,uuid,integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/is_qualified.sql
-- -----------------------------------------------------------------------------

-- Function: public.is_qualified
-- Arguments: p_user_id uuid (defaults to the caller)
-- Description: Non-forgeable "qualified member" marker — true iff the user has a
--   server-authored passing qualification_results row. qualification_results is
--   written only by assign_member_role_after_qualification (SECURITY DEFINER) and
--   clients hold no write access to it, so this cannot be self-asserted.
-- Security: SECURITY DEFINER; boolean gate (leaks no data beyond qualified-or-not).
--   Cross-user lookups are restricted to admin/staff/service; anyone else resolves
--   to themselves.

CREATE OR REPLACE FUNCTION public.is_qualified(p_user_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target uuid;
BEGIN
  v_target := CASE
    WHEN p_user_id IS NULL THEN auth.uid()
    WHEN p_user_id = auth.uid() THEN p_user_id
    WHEN public.is_service_role() OR public.is_admin_or_staff(auth.uid()) THEN p_user_id
    ELSE auth.uid()
  END;

  IF v_target IS NULL THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1 FROM public.qualification_results qr
    WHERE qr.user_id = v_target AND qr.passed = true
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.is_qualified(p_user_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_qualified(p_user_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.is_qualified(p_user_id uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/is_story_participant.sql
-- -----------------------------------------------------------------------------

/**
 * is_story_participant
 *
 * Checks whether a user is a participant of a given story.
 * Used as a security helper for story collaboration RLS and RPC functions.
 *
 * @param p_user_id - UUID of the user to check
 * @param p_story_id - UUID of the story to check participation in
 * @returns boolean - true if the user is a participant
 */
CREATE OR REPLACE FUNCTION public.is_story_participant(p_user_id uuid, p_story_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  -- ⛔ PREDIKÁT O TŘETÍ OSOBĚ JE ORÁKULUM (naměřeno 2026-09-19). Funkce je
  -- přes PostgREST vystavená (`/rpc/is_story_participant`) a pravdivě odpovídala
  -- o KOMKOLI: přihlášený člen z ní složil, kdo patří do které story — tedy
  -- graf spoluprací cizích lidí, uuid po uuid.
  --
  -- Odpovídá se proto jen o VOLAJÍCÍM; služba a správa se smí ptát na kohokoli.
  -- Změřeno, že to nic nerozbije: všech 10 volání v politikách (sql/rls,
  -- sql/policies — story_participants, web_artifact_jobs, story_links) jí
  -- předává `auth.uid()`, ani jedno sloupec řádku; 21 volání z definer funkcí
  -- předává proměnnou naplněnou z `auth.uid()`; fn_user_can_read_run
  -- a can_access_linked_story mají tutéž stráž před sebou a svc-ai-chat
  -- (dirigent-supervisor) volá service klíčem. `false` místo výjimky je záměr —
  -- predikát v RLS má vracet deny, ne shodit dotaz.
  --
  -- REVOKE tady řešením NENÍ: RLS predikát se vyhodnocuje právy volajícího,
  -- takže odebrání EXECUTE by shodilo obyčejné čtení story_links.
  --
  -- TVAR JE ZMĚŘENÝ, ne estetický. V politice story_links se predikát volá PER
  -- ŘÁDEK se sloupcem řádku (`is_story_participant(auth.uid(), source_story_id)`),
  -- takže do InitPlanu nejde. Throwaway DB, 29 903 odkazů, tvar té politiky:
  --     bez stráže                    ~1 770 ms
  --     stráž napřed (CASE)           ~3 180 ms   ← auth.uid() za každý řádek
  --     EXISTS napřed, stráž potom    ~1 690 ms   ← tenhle tvar
  -- Většina řádků účast nemá, EXISTS vrátí false a stráž se nevyhodnotí vůbec.
  -- Výsledek je v obou pořadích totožný (AND); pořadí nese jen cenu.
  -- COALESCE drží anonyma: `p_user_id = NULL` je NULL → false, ne NULL.
  SELECT EXISTS (
      SELECT 1 FROM public.story_participants
      WHERE user_id = p_user_id AND story_id = p_story_id
    )
    AND (
      COALESCE(p_user_id = auth.uid(), false)
      OR public.is_service_role()
      OR public.is_admin_or_staff()
    );
$function$;

REVOKE ALL ON FUNCTION public.is_story_participant(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_story_participant(uuid, uuid) TO authenticated;
-- service_role: start_web_artifact_ingest (SECURITY INVOKER) evaluates this as the
-- real service_role role at boot; same result, grant only avoids a permission error.
GRANT EXECUTE ON FUNCTION public.is_story_participant(uuid, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/accept_story_link.sql
-- -----------------------------------------------------------------------------

/**
 * accept_story_link
 *
 * Accepts a pending story link. Only participants of the target story
 * or admin/staff can accept. Logs the action to audit_journal.
 *
 * @param p_link_id - UUID of the story link to accept
 * @returns jsonb - Result with link id, acceptance status, and update flag
 */
CREATE OR REPLACE FUNCTION public.accept_story_link(
  p_link_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_link record;
  v_rows_updated int := 0;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: not authenticated';
  END IF;

  SELECT id, source_story_id, target_story_id, link_type, is_accepted
  INTO v_link
  FROM public.story_links
  WHERE id = p_link_id;

  IF v_link IS NULL THEN
    RAISE EXCEPTION 'Story link not found: %', p_link_id;
  END IF;

  IF v_link.is_accepted = true THEN
    RETURN jsonb_build_object('id', p_link_id, 'already_accepted', true);
  END IF;

  IF NOT public.is_story_participant(v_user_id, v_link.target_story_id) AND NOT public.is_admin_or_staff(v_user_id) THEN
    RAISE EXCEPTION 'Unauthorized: not a participant of target story';
  END IF;

  UPDATE public.story_links
  SET is_accepted = true
  WHERE id = p_link_id;

  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'STORY_LINK_ACCEPTED',
    jsonb_build_object(
      'area', 'collaboration',
      'severity', 'info',
      'link_id', p_link_id,
      'source_story_id', v_link.source_story_id,
      'target_story_id', v_link.target_story_id,
      'link_type', v_link.link_type
    )
  );

  RETURN jsonb_build_object(
    'id', p_link_id,
    'is_accepted', true,
    'updated', v_rows_updated > 0
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.accept_story_link(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.accept_story_link(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/apply_web_artifact_to_page.sql
-- -----------------------------------------------------------------------------

-- apply_web_artifact_to_page
-- Apply a ready_for_review job's result canvas to a web_pages row.
-- Concurrency guard: raises stale_artifact_apply_another_version_landed if web_pages
-- has been updated since this job was created.
-- Always creates a pre-apply version snapshot for rollback.
-- Appends a story_entries row (entry_type=web_artifact_applied) so the storyloop
-- timeline records the transition.
-- Authz: admin/staff (or story participant when story_id is set).

CREATE OR REPLACE FUNCTION public.apply_web_artifact_to_page(
  p_job_id uuid,
  p_page_id uuid,
  p_publish boolean DEFAULT false
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_job record;
  v_page record;
  v_latest_version_id uuid;
  v_pre_apply_version_id uuid;
BEGIN
  SELECT id, status, story_id, result_canvas_data, result_canvas_html, result_canvas_css, created_at
  INTO v_job
  FROM public.web_artifact_jobs
  WHERE id = p_job_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found: %', p_job_id;
  END IF;

  IF v_job.status NOT IN ('ready_for_review', 'approved') THEN
    RAISE EXCEPTION 'Job must be ready_for_review/approved (got %)', v_job.status;
  END IF;

  IF v_job.result_canvas_data IS NULL THEN
    RAISE EXCEPTION 'Job has no result canvas to apply';
  END IF;

  SELECT id, story_id, updated_at, status INTO v_page
  FROM public.web_pages
  WHERE id = p_page_id AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Page not found: %', p_page_id;
  END IF;

  -- Boot-time /seed-default publishes via service_role (sub-less system runner,
  -- not a story participant) — admit it, consistent with start/mark/complete
  -- which are already service_role-aware. Admin/staff + story-participant paths
  -- are unchanged.
  IF NOT public.is_admin_or_staff()
     AND NOT public.is_service_role()
     AND (v_job.story_id IS NULL OR NOT public.is_story_participant(auth.uid(), v_job.story_id))
  THEN
    RAISE EXCEPTION 'Unauthorized: admin/staff, service_role, or story participant required';
  END IF;

  SELECT id INTO v_latest_version_id
  FROM public.web_page_versions
  WHERE page_id = p_page_id
  ORDER BY version_number DESC
  LIMIT 1;

  IF v_page.updated_at > v_job.created_at
     AND (v_latest_version_id IS NULL OR v_latest_version_id IS DISTINCT FROM (
       SELECT applied_version_id FROM public.web_artifact_jobs WHERE id = p_job_id
     ))
  THEN
    RAISE EXCEPTION 'stale_artifact_apply_another_version_landed: page updated_at=% > job created_at=%, regenerate artifact', v_page.updated_at, v_job.created_at;
  END IF;

  v_pre_apply_version_id := public.create_web_page_version(p_page_id, 'auto: before web_artifact apply');

  UPDATE public.web_pages
  SET canvas_data = v_job.result_canvas_data,
      canvas_html = v_job.result_canvas_html,
      canvas_css = v_job.result_canvas_css,
      story_id = v_job.story_id,
      status = CASE WHEN p_publish THEN 'published' ELSE status END,
      updated_at = now()
  WHERE id = p_page_id;

  UPDATE public.web_artifact_jobs
  SET status = 'applied',
      applied_to_page_id = p_page_id,
      applied_version_id = v_pre_apply_version_id,
      applied_at = now()
  WHERE id = p_job_id;

  IF v_job.story_id IS NOT NULL THEN
    INSERT INTO public.story_entries (story_id, entry_type, content, metadata, created_by)
    VALUES (
      v_job.story_id,
      'web_artifact_applied',
      NULL,
      jsonb_build_object(
        'type', 'web_artifact_applied',
        'job_id', p_job_id,
        'page_id', p_page_id,
        'pre_apply_version_id', v_pre_apply_version_id,
        'published', p_publish
      ),
      auth.uid()
    );
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'WEB_ARTIFACT_APPLY',
    jsonb_build_object(
      'area', 'content',
      'severity', 'info',
      'entity_type', 'web_artifact_job',
      'entity_id', p_job_id::text,
      'page_id', p_page_id::text,
      'pre_apply_version_id', v_pre_apply_version_id::text,
      'published', p_publish,
      'tags', ARRAY['stack', 'story', 'web_artifact', 'apply']
    )
  );

  RETURN v_pre_apply_version_id;
END;
$$;

REVOKE ALL ON FUNCTION public.apply_web_artifact_to_page(uuid, uuid, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.apply_web_artifact_to_page(uuid, uuid, boolean) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/can_access_linked_story.sql
-- -----------------------------------------------------------------------------

/**
 * can_access_linked_story
 *
 * Determines whether a user can access a linked story based on their role
 * and participation. Admin/staff can access any accepted link; regular users
 * must be a participant of the source story with an accepted link to the target.
 *
 * @param p_user_id - UUID of the user requesting access
 * @param p_source_story_id - UUID of the source story
 * @param p_target_story_id - UUID of the target story
 * @returns boolean - true if the user can access the linked story
 */
CREATE OR REPLACE FUNCTION public.can_access_linked_story(
  p_user_id uuid,
  p_source_story_id uuid,
  p_target_story_id uuid
)
RETURNS boolean
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  -- ⛔ PREDIKÁT O TŘETÍ OSOBĚ JE ORÁKULUM (naměřeno 2026-09-19). Přes
  -- `/rpc/can_access_linked_story` se dal pro CIZÍ uuid zjistit, jestli je
  -- účastníkem zdrojové story a (větví níž) jestli je admin/staff — funkce
  -- se ptala `is_admin_or_staff(p_user_id)`, tedy na roli toho, na koho se
  -- volající ptá, ne na jeho vlastní.
  --
  -- Odpovídá se jen o VOLAJÍCÍM; služba a správa na kohokoli. Změřeno, že to
  -- nic nerozbije: jediný volající v repu (get_cross_story_summary) předává
  -- `v_user_id := auth.uid()`. `false` = deny, stejně jako „odkaz neexistuje",
  -- takže zamítnutí nic neprozradí.
  IF v_uid IS NULL OR p_user_id IS DISTINCT FROM v_uid THEN
    IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
      RETURN false;
    END IF;
  END IF;

  -- Admin/staff can access any linked story (but link must still be accepted)
  IF public.is_admin_or_staff(p_user_id) THEN
    RETURN EXISTS (
      SELECT 1 FROM public.story_links
      WHERE (
        (source_story_id = p_source_story_id AND target_story_id = p_target_story_id)
        OR (source_story_id = p_target_story_id AND target_story_id = p_source_story_id)
      )
      AND is_accepted = true
    );
  END IF;

  -- Regular users: must be participant of source story,
  -- and an accepted link must exist between source and target
  RETURN (
    public.is_story_participant(p_user_id, p_source_story_id)
    AND EXISTS (
      SELECT 1 FROM public.story_links
      WHERE (
        (source_story_id = p_source_story_id AND target_story_id = p_target_story_id)
        OR (source_story_id = p_target_story_id AND target_story_id = p_source_story_id)
      )
      AND is_accepted = true
    )
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.can_access_linked_story(uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_access_linked_story(uuid, uuid, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_mcp_token.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_mcp_token
-- Arguments: p_scope text, p_account_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_allowed_tools text[] DEFAULT '{}'::text[], p_denied_tools text[] DEFAULT '{}'::text[], p_rate_limit_rpm integer DEFAULT 60, p_rate_limit_daily integer DEFAULT 1000, p_expires_in_days integer DEFAULT 90
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.create_mcp_token(p_scope text, p_account_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_allowed_tools text[] DEFAULT '{}'::text[], p_denied_tools text[] DEFAULT '{}'::text[], p_rate_limit_rpm integer DEFAULT 60, p_rate_limit_daily integer DEFAULT 1000, p_expires_in_days integer DEFAULT 90)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_raw_token text;
  v_token_hash text;
  v_token_id uuid;
BEGIN
  -- Only admin/staff can create tokens
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Insufficient permissions' USING ERRCODE = '42501';
  END IF;

  -- Generate raw token (this is the only time it's visible)
  v_raw_token := 'mcp_' || encode(gen_random_bytes(32), 'hex');
  v_token_hash := encode(digest(v_raw_token, 'sha256'), 'hex');

  INSERT INTO mcp_auth_tokens (
    token_hash, scope, account_id, project_id,
    allowed_tools, denied_tools, rate_limit_rpm, rate_limit_daily,
    expires_at, created_by, user_id
  )
  VALUES (
    v_token_hash, p_scope, p_account_id, p_project_id,
    p_allowed_tools, p_denied_tools, p_rate_limit_rpm, p_rate_limit_daily,
    CASE WHEN p_expires_in_days > 0 THEN now() + (p_expires_in_days || ' days')::interval ELSE NULL END,
    auth.uid(), auth.uid()
  )
  RETURNING id INTO v_token_id;

  -- Return raw token ONCE (never stored in plaintext)
  RETURN jsonb_build_object(
    'token_id', v_token_id,
    'raw_token', v_raw_token,
    'scope', p_scope,
    'expires_at', CASE WHEN p_expires_in_days > 0 THEN now() + (p_expires_in_days || ' days')::interval ELSE NULL END,
    'warning', 'Store this token securely. It cannot be retrieved again.'
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.create_mcp_token(text, uuid, uuid, text[][], text[][], integer, integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_mcp_token(text, uuid, uuid, text[][], text[][], integer, integer, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.create_mcp_token(text, uuid, uuid, text[][], text[][], integer, integer, integer) TO service_role;

-- §8.5 bind-at-issuance — scoped PAT minting (9-arg overload, distinct arity).
-- Mints a token bound to a story (scoped_to_story_id NOT NULL). This is the path
-- Omni provisioning + e2e fixtures use; the 8-arg form above mints unscoped tokens
-- that fail-closed at /v1 until re-issued via this function.
CREATE OR REPLACE FUNCTION public.create_mcp_token(p_scope text, p_scoped_to_story_id uuid, p_account_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_allowed_tools text[] DEFAULT '{}'::text[], p_denied_tools text[] DEFAULT '{}'::text[], p_rate_limit_rpm integer DEFAULT 60, p_rate_limit_daily integer DEFAULT 1000, p_expires_in_days integer DEFAULT 90)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_raw_token text;
  v_token_hash text;
  v_token_id uuid;
BEGIN
  -- §8.5 bind-at-issuance: a scoped token MUST name its story (both admin and self-service).
  IF p_scoped_to_story_id IS NULL THEN
    RAISE EXCEPTION 'scoped_to_story_id is required for bind-at-issuance (§8.5)' USING ERRCODE = '22004';
  END IF;

  -- Self-service minting (2026-07-07, IDE-axis napoj): a KC-authenticated user may mint a token
  -- bound to THEIR OWN identity (user_id = auth.uid(), hardcoded below — no identity escalation),
  -- scoped to a story they can access, with capped limits. Admin/staff retain unrestricted minting.
  -- Least-privilege: no scope escalation (mint-time story check mirrors fn_user_can_read_run's story
  -- authority; use-time /v1 story-binding via fn_user_can_read_run remains the backstop).
  IF NOT is_admin_or_staff() THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Authentication required to mint a token' USING ERRCODE = '42501';
    END IF;
    IF NOT (
      public.is_story_participant(auth.uid(), p_scoped_to_story_id)
      OR EXISTS (
        SELECT 1 FROM public.partner_stories ps
        WHERE ps.id = p_scoped_to_story_id
          AND (ps.user_id = auth.uid() OR ps.is_stack_default = true)
      )
    ) THEN
      RAISE EXCEPTION 'Cannot mint a token scoped to a story you cannot access' USING ERRCODE = '42501';
    END IF;
    -- Cap self-service caps + expiry (a self-minted token cannot request absurd limits).
    p_rate_limit_rpm   := LEAST(GREATEST(COALESCE(p_rate_limit_rpm, 60), 1), 120);
    p_rate_limit_daily := LEAST(GREATEST(COALESCE(p_rate_limit_daily, 1000), 1), 5000);
    p_expires_in_days  := LEAST(GREATEST(COALESCE(p_expires_in_days, 90), 1), 90);
    -- Self-service tokens carry a non-privileged scope only.
    IF p_scope IS NULL OR p_scope NOT IN ('story', 'chat') THEN
      p_scope := 'story';
    END IF;
  END IF;

  v_raw_token := 'mcp_' || encode(gen_random_bytes(32), 'hex');
  v_token_hash := encode(digest(v_raw_token, 'sha256'), 'hex');

  INSERT INTO mcp_auth_tokens (
    token_hash, scope, account_id, project_id,
    allowed_tools, denied_tools, rate_limit_rpm, rate_limit_daily,
    expires_at, created_by, user_id, scoped_to_story_id
  )
  VALUES (
    v_token_hash, p_scope, p_account_id, p_project_id,
    p_allowed_tools, p_denied_tools, p_rate_limit_rpm, p_rate_limit_daily,
    CASE WHEN p_expires_in_days > 0 THEN now() + (p_expires_in_days || ' days')::interval ELSE NULL END,
    auth.uid(), auth.uid(), p_scoped_to_story_id
  )
  RETURNING id INTO v_token_id;

  RETURN jsonb_build_object(
    'token_id', v_token_id,
    'raw_token', v_raw_token,
    'scope', p_scope,
    'scoped_to_story_id', p_scoped_to_story_id,
    'expires_at', CASE WHEN p_expires_in_days > 0 THEN now() + (p_expires_in_days || ' days')::interval ELSE NULL END,
    'warning', 'Store this token securely. It cannot be retrieved again.'
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.create_mcp_token(text, uuid, uuid, uuid, text[][], text[][], integer, integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_mcp_token(text, uuid, uuid, uuid, text[][], text[][], integer, integer, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.create_mcp_token(text, uuid, uuid, uuid, text[][], text[][], integer, integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_story_link.sql
-- -----------------------------------------------------------------------------

/**
 * create_story_link
 *
 * Creates a link between two partner stories in the collaboration graph.
 * Validates user authorization, link_type, and story existence.
 * Logs the action to audit_journal.
 *
 * @param p_link_type - Type of link: depends_on, related_to, blocks, extends, shares_context
 * @param p_metadata - Optional JSONB metadata for the link
 * @param p_source_story_id - UUID of the source story
 * @param p_target_story_id - UUID of the target story
 * @returns jsonb - Created link details including id, story IDs, link_type
 */
CREATE OR REPLACE FUNCTION public.create_story_link(
  p_link_type text,
  p_metadata jsonb DEFAULT '{}'::jsonb,
  p_source_story_id uuid DEFAULT NULL,
  p_target_story_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_link_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: not authenticated' USING ERRCODE = '22023';
  END IF;

  IF NOT public.is_story_participant(v_user_id, p_source_story_id) AND NOT public.is_admin_or_staff(v_user_id) THEN
    RAISE EXCEPTION 'Unauthorized: not a participant of source story' USING ERRCODE = '22023';
  END IF;

  IF p_link_type NOT IN ('depends_on', 'related_to', 'blocks', 'extends', 'shares_context') THEN
    RAISE EXCEPTION 'Invalid link_type: %', p_link_type USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.partner_stories WHERE id = p_source_story_id) THEN
    RAISE EXCEPTION 'Source story not found: %', p_source_story_id USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.partner_stories WHERE id = p_target_story_id) THEN
    RAISE EXCEPTION 'Target story not found: %', p_target_story_id USING ERRCODE = '22023';
  END IF;

  IF p_source_story_id = p_target_story_id THEN
    RAISE EXCEPTION 'Cannot link a story to itself' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.story_links (source_story_id, target_story_id, link_type, created_by, metadata)
  VALUES (p_source_story_id, p_target_story_id, p_link_type, v_user_id, p_metadata)
  ON CONFLICT (source_story_id, target_story_id, link_type) DO NOTHING
  RETURNING id INTO v_link_id;

  IF v_link_id IS NULL THEN
    RAISE EXCEPTION 'Link already exists between these stories with type: %', p_link_type USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'STORY_LINK_CREATED',
    jsonb_build_object(
      'area', 'collaboration',
      'severity', 'info',
      'link_id', v_link_id,
      'source_story_id', p_source_story_id,
      'target_story_id', p_target_story_id,
      'link_type', p_link_type
    )
  );

  RETURN jsonb_build_object(
    'id', v_link_id,
    'source_story_id', p_source_story_id,
    'target_story_id', p_target_story_id,
    'link_type', p_link_type,
    'is_accepted', NULL::boolean,
    'created', true
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.create_story_link(text, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_story_link(text, jsonb, uuid, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/dismiss_story_link.sql
-- -----------------------------------------------------------------------------

/**
 * dismiss_story_link
 *
 * Dismisses (rejects) a story link. Participants of either the source
 * or target story, or admin/staff, can dismiss. Logs to audit_journal.
 *
 * @param p_link_id - UUID of the story link to dismiss
 * @returns jsonb - Result with link id, acceptance status (false), and update flag
 */
CREATE OR REPLACE FUNCTION public.dismiss_story_link(
  p_link_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_link record;
  v_rows_updated int := 0;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: not authenticated';
  END IF;

  SELECT id, source_story_id, target_story_id, link_type, is_accepted
  INTO v_link
  FROM public.story_links
  WHERE id = p_link_id;

  IF v_link IS NULL THEN
    RAISE EXCEPTION 'Story link not found: %', p_link_id;
  END IF;

  IF NOT public.is_story_participant(v_user_id, v_link.source_story_id)
    AND NOT public.is_story_participant(v_user_id, v_link.target_story_id)
    AND NOT public.is_admin_or_staff(v_user_id) THEN
    RAISE EXCEPTION 'Unauthorized: not a participant of linked stories';
  END IF;

  UPDATE public.story_links
  SET is_accepted = false
  WHERE id = p_link_id;

  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'STORY_LINK_DISMISSED',
    jsonb_build_object(
      'area', 'collaboration',
      'severity', 'info',
      'link_id', p_link_id,
      'source_story_id', v_link.source_story_id,
      'target_story_id', v_link.target_story_id,
      'link_type', v_link.link_type
    )
  );

  RETURN jsonb_build_object(
    'id', p_link_id,
    'is_accepted', false,
    'updated', v_rows_updated > 0
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.dismiss_story_link(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.dismiss_story_link(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/evaluate_story_self.sql
-- -----------------------------------------------------------------------------

-- Function: public.evaluate_story_self
-- Self-evaluation LENS — jednotný per-story verdikt. NE bespoke subsystém:
-- slévá get_story_aisha_maturity() (skóre + level) se selfeval_story_verdict_v
-- (faithfulness / drift / incidents / goal / proposals dimenze) do akceschopného
-- verdiktu. "Evaluation je perspektiva, ne entita" — vzor audience modul.
--
-- ADVISORY-ONLY: STABLE, read-only — NIKDY nemutuje stav. recommended_actions je
-- jen text; vznik ai_task / improvement_proposal / rollback jsou separátní gated
-- kroky (PR 4/5), ne tady.
--
-- GENERIC přes (story, backend): p_backend NULL = origin instance. PR 8 napojí
-- resolver přes story_instances / instance_endpoint_bindings; zatím echo do výstupu.
--
-- @security: authenticated (admin/staff/participant/stack-default — stejný P7 RLS
-- kontrakt jako fn_list_story_faithfulness_trend) + service_role (n8n/workflow).

CREATE OR REPLACE FUNCTION public.evaluate_story_self(
  p_story_id uuid,
  p_backend  text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id    uuid := auth.uid();
  v_is_service boolean := current_setting('role', true) = 'service_role';
  v_maturity   jsonb;
  v_score      numeric;
  v_level      text;
  -- Dimensions read from selfeval_story_verdict_v via explicit-column SELECT.
  -- NOT %ROWTYPE: that would be a compile-time dependency on the view, and the
  -- generated baseline emits functions before views — so %ROWTYPE breaks cold-start.
  v_faithfulness_avg      numeric;
  v_faithfulness_n        integer;
  v_open_drift_count      integer;
  v_open_drift_high       integer;
  v_sentry_fatal_30d      integer;
  v_acceptance_criteria   jsonb;
  v_loop_iterations       integer;
  v_loop_max              integer;
  v_open_proposals        integer;
  v_applied_proposals_30d integer;
  v_dimensions jsonb;
  v_findings   jsonb := '[]'::jsonb;
  v_actions    jsonb := '[]'::jsonb;
BEGIN
  -- service_role (n8n/workflow) is a trusted system caller without a JWT;
  -- authenticated users must have auth.uid(). Bypass auth + gate for service_role.
  IF v_user_id IS NULL AND NOT v_is_service THEN
    RAISE EXCEPTION 'Unauthorized: not authenticated' USING ERRCODE = '22023';
  END IF;
  IF p_story_id IS NULL THEN
    RAISE EXCEPTION 'p_story_id is required' USING ERRCODE = '22023';
  END IF;

  -- Visibility: admin/staff sees all, participants see own stories, stack-default
  -- story is visible to all authenticated users (reuse P7 contract). service_role
  -- (trusted system caller) bypasses the participant gate.
  IF NOT v_is_service
     AND NOT public.is_admin_or_staff(v_user_id)
     AND NOT public.is_story_participant(v_user_id, p_story_id)
     AND NOT EXISTS (
       SELECT 1 FROM public.partner_stories
       WHERE id = p_story_id AND is_stack_default = true
     ) THEN
    RAISE EXCEPTION 'Forbidden: not a participant of story %', p_story_id
      USING ERRCODE = '42501';
  END IF;

  -- Reuse maturity (score + level) — fix-at-source, ne re-implement.
  v_maturity := public.get_story_aisha_maturity(p_story_id);
  v_score := COALESCE((v_maturity->>'maturity_score')::numeric, 0);
  v_level := COALESCE(v_maturity->>'maturity_level', 'novice');

  -- Reused operational dimensions from the lens view.
  SELECT faithfulness_avg, faithfulness_n, open_drift_count, open_drift_high,
         sentry_fatal_30d, acceptance_criteria, loop_iterations, loop_max,
         open_proposals, applied_proposals_30d
    INTO v_faithfulness_avg, v_faithfulness_n, v_open_drift_count, v_open_drift_high,
         v_sentry_fatal_30d, v_acceptance_criteria, v_loop_iterations, v_loop_max,
         v_open_proposals, v_applied_proposals_30d
    FROM public.selfeval_story_verdict_v WHERE story_id = p_story_id;

  v_dimensions := jsonb_build_array(
    jsonb_build_object('key', 'maturity', 'score', v_score, 'weight', 1.0, 'evidence', v_maturity),
    jsonb_build_object('key', 'faithfulness',
      'score', COALESCE(v_faithfulness_avg, 0),
      'evidence', jsonb_build_object('avg', v_faithfulness_avg, 'n', COALESCE(v_faithfulness_n, 0))),
    jsonb_build_object('key', 'drift',
      'evidence', jsonb_build_object('open', COALESCE(v_open_drift_count, 0), 'high', COALESCE(v_open_drift_high, 0))),
    jsonb_build_object('key', 'incidents',
      'evidence', jsonb_build_object('sentry_fatal_30d', COALESCE(v_sentry_fatal_30d, 0))),
    jsonb_build_object('key', 'goal',
      'evidence', jsonb_build_object(
        'loop_iterations', v_loop_iterations,
        'loop_max', v_loop_max,
        'acceptance_criteria', v_acceptance_criteria))
  );

  -- Findings (advisory only — derived, NOT actioned here).
  IF COALESCE(v_open_drift_high, 0) > 0 THEN
    v_findings := v_findings || jsonb_build_object(
      'severity', 'high', 'kind', 'drift',
      'summary', v_open_drift_high || ' high/critical drift open on story apps');
  END IF;
  IF COALESCE(v_sentry_fatal_30d, 0) > 0 THEN
    v_findings := v_findings || jsonb_build_object(
      'severity', 'high', 'kind', 'incident',
      'summary', v_sentry_fatal_30d || ' fatal Sentry events (30d) on story apps');
  END IF;
  IF v_loop_iterations IS NOT NULL AND v_loop_max IS NOT NULL
     AND v_loop_iterations >= v_loop_max THEN
    v_findings := v_findings || jsonb_build_object(
      'severity', 'medium', 'kind', 'goal',
      'summary', 'autonomous loop reached cap — review acceptance criteria');
  END IF;

  -- Recommended actions (advisory text — NIKDY se neaplikují odsud).
  IF jsonb_array_length(v_findings) > 0 THEN
    v_actions := v_actions || jsonb_build_object(
      'kind', 'review', 'target', 'operator',
      'rationale', 'open findings present — consider improvement_proposal / rollback (gated, advisory-only)');
  END IF;

  RETURN jsonb_build_object(
    'story_id', p_story_id,
    'backend', COALESCE(p_backend, 'origin'),
    'evaluated_at', now(),
    'period_days', 30,
    'score', v_score,
    'level', v_level,
    'dimensions', v_dimensions,
    'findings', v_findings,
    'recommended_actions', v_actions,
    'open_proposals', COALESCE(v_open_proposals, 0),
    'applied_proposals_30d', COALESCE(v_applied_proposals_30d, 0)
  );
END;
$$;

-- Permissions per CLAUDE.md SECURITY DEFINER pattern.
REVOKE ALL ON FUNCTION public.evaluate_story_self(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.evaluate_story_self(uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.evaluate_story_self(uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_check_and_consume_ai_budget_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_check_and_consume_ai_budget_audited
-- Mission Control governance — story-aware spend gate, called at the orchestration
-- control layer (reflection node boundary) with a node's ACTUAL token+USD cost.
--
-- Composition (NOT a parallel mechanism):
--   1. Per-user daily quota — reuse fn_check_and_consume_llm_quota_audited
--      (it consumes + audits its own denial).
--   2. Per-story budget — post-paid metering: record the actual spend against the
--      story's ai_budget row(s) (lifetime/daily/monthly), then signal halt when a
--      cap is reached. A completed LLM call cannot be un-spent, so we meter actuals
--      and stop the NEXT node — accepting a single last-node overshoot.
--   p_story_id NULL or no row → unlimited story side (backward compatible).
--
-- Returns: { allowed, reason ('ok'|'user_quota'|'story_budget'), user_quota, story_state }.
-- Security: SECURITY DEFINER. Audits the story-budget denial (user denial is
-- audited by the per-user RPC). No PII — IDs + numerics only.
-- ============================================================================

-- p_cost_usd → p_cost (currency literals removed from the schema). The type
-- signature did not change, so CREATE OR REPLACE matches the existing function
-- and Postgres refuses: "cannot change name of input parameter". DROP-first is
-- the convention used elsewhere in this directory; the REVOKE/GRANT below
-- re-applies the privileges the drop clears.
DROP FUNCTION IF EXISTS public.fn_check_and_consume_ai_budget_audited(uuid, uuid, int, numeric);

CREATE OR REPLACE FUNCTION public.fn_check_and_consume_ai_budget_audited(
  p_user_id  uuid,
  p_story_id uuid,
  p_tokens   int,
  p_cost numeric
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_result   jsonb;
  v_user_allowed  boolean := true;
  v_story_allowed boolean := true;
  v_reason        text := 'ok';
  v_row           public.ai_budget%ROWTYPE;
BEGIN
  -- AUTHORIZATION FIRST. The old guard had two defects (2026-07-15 IDOR audit,
  -- docs/security/IDOR_P_USER_ID_AUDIT_2026-07-15.md):
  --
  --  (a) It asked only "is SOMEONE authenticated?", never whether p_user_id was them or
  --      whether they had any claim on p_story_id. With the `authenticated` GRANT, a
  --      logged-in user could meter spend against ANY user's quota and ANY story's budget —
  --      exhausting a story they cannot even read, which halts its runs (`story_budget`).
  --  (b) It read the role GUC directly. NOT a fail-open — an earlier version of the audit claimed
  --      `current_setting('role', true) <> 'service_role'` folds to NULL, and that is FALSE:
  --      `role` is a BUILT-IN GUC and returns 'none', never NULL. Only DOTTED custom GUCs
  --      (request.jwt.claims) fold to NULL. is_service_role() is used because it is the canonical
  --      reader, not because the old expression was unsafe.
  --
  -- The p_user_id and p_story_id checks are the fix.
  IF NOT public.is_service_role() AND NOT public.is_admin_or_staff() THEN
    IF auth.uid() IS NULL OR p_user_id IS DISTINCT FROM auth.uid() THEN
      RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
    END IF;
    IF p_story_id IS NOT NULL AND NOT public.is_story_participant(auth.uid(), p_story_id) THEN
      RAISE EXCEPTION 'Unauthorized: not a story participant' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Validate inputs.
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required' USING ERRCODE = '22023';
  END IF;
  IF p_tokens IS NULL OR p_tokens < 0 THEN
    RAISE EXCEPTION 'p_tokens must be >= 0' USING ERRCODE = '22023';
  END IF;
  IF p_cost IS NULL OR p_cost < 0 THEN
    RAISE EXCEPTION 'p_cost must be >= 0' USING ERRCODE = '22023';
  END IF;

  -- 1) Per-user daily quota (reuse the existing audited gate — consumes + audits).
  v_user_result := public.fn_check_and_consume_llm_quota_audited(p_user_id, p_tokens, p_cost);
  v_user_allowed := COALESCE((v_user_result ->> 'allowed')::boolean, true);
  IF NOT v_user_allowed THEN
    v_reason := 'user_quota';
  END IF;

  -- 2) Per-story budget — meter actuals across the story's period rows.
  IF p_story_id IS NOT NULL THEN
    FOR v_row IN
      -- Explicit column list (security gate: no SELECT * on real tables).
      -- Order matches public.ai_budget definition for %ROWTYPE compatibility.
      SELECT id, scope_type, scope_id, period, token_limit, cost_limit,
             consumed_tokens, consumed_cost, last_reset_at,
             created_by, created_at, updated_at
      FROM public.ai_budget
      WHERE scope_type = 'story' AND scope_id = p_story_id
      FOR UPDATE
    LOOP
      -- Period reset (daily/monthly) before metering this window.
      IF (v_row.period = 'daily'   AND v_row.last_reset_at < date_trunc('day',   now()))
      OR (v_row.period = 'monthly' AND v_row.last_reset_at < date_trunc('month', now())) THEN
        v_row.consumed_tokens   := 0;
        v_row.consumed_cost := 0;
        v_row.last_reset_at     := now();
      END IF;

      -- Meter the actual spend (post-paid).
      v_row.consumed_tokens   := v_row.consumed_tokens   + p_tokens;
      v_row.consumed_cost := v_row.consumed_cost + p_cost;

      UPDATE public.ai_budget SET
        consumed_tokens   = v_row.consumed_tokens,
        consumed_cost = v_row.consumed_cost,
        last_reset_at     = v_row.last_reset_at,
        updated_at        = now()
      WHERE id = v_row.id;

      -- Cap reached on either limited dimension?
      IF (v_row.token_limit    IS NOT NULL AND v_row.consumed_tokens   >= v_row.token_limit)
      OR (v_row.cost_limit IS NOT NULL AND v_row.consumed_cost >= v_row.cost_limit) THEN
        v_story_allowed := false;
      END IF;
    END LOOP;

    IF NOT v_story_allowed AND v_user_allowed THEN
      v_reason := 'story_budget';
    END IF;
  END IF;

  -- Audit the story-budget denial only (user denial already audited by its RPC).
  IF NOT v_story_allowed THEN
    INSERT INTO public.audit_journal (user_id, action, metadata)
    VALUES (
      p_user_id,
      'ai.budget.denied',
      jsonb_build_object(
        'reason',             'story_budget',
        'story_id',           p_story_id,
        'requested_tokens',   p_tokens,
        'requested_cost', p_cost
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'allowed',     (v_user_allowed AND v_story_allowed),
    'reason',      v_reason,
    'user_quota',  v_user_result,
    'story_state', CASE WHEN p_story_id IS NULL THEN 'ok'
                        WHEN v_story_allowed     THEN 'ok'
                        ELSE 'stopped' END
  );
END;
$$;

-- The `authenticated` grant is part of the design contract (asserted by
-- src/tests/gates/ai-budget.gate.test.ts, mirroring WP 2.3's per-JWT.sub gating), even though the
-- only caller today is svc-ai-chat's reflection orchestrator
-- (services/svc-ai-chat/src/reflection/orchestrator.ts), which reaches PostgREST through
-- @aisha/postgrest-client with the service_role bearer token. The grant was never the defect:
-- granting it with no check that p_user_id was the caller, and no check that they had any claim
-- on p_story_id, was. The guard in the body enforces both, so the grant is safe.
REVOKE ALL ON FUNCTION public.fn_check_and_consume_ai_budget_audited(uuid, uuid, int, numeric) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_check_and_consume_ai_budget_audited(uuid, uuid, int, numeric) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_check_and_consume_ai_budget_audited(uuid, uuid, int, numeric) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_hermes_learning_loop.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_hermes_learning_loop
-- Hermes reflexive-learning loop (E3) — the "Hermes learns" leg, automated.
--
-- On story closure it (1) runs the advisory self-evaluation (evaluate_story_self,
-- which also refreshes story_goal_state — E15), then for ACTIONABLE findings it
-- (2) captures a hippocampus learning and (3) synthesizes one improvement_proposal
-- per finding through fn_create_improvement_proposal.
--
-- AGGRESSIVE but governed, NOT an allow-list: fn_create_improvement_proposal itself
-- risk-evaluates (fn_evaluate_proposal_risk → low|medium|high|critical|manual),
-- rate-limits (3/agent/hour), dedups by anomaly_key, and AUTO-APPROVES only low-risk
-- proposals on fully-autonomous agents — everything else stays pending for the human
-- gate. So "how aggressive" is decided by computed risk + the agent's autonomy level,
-- never a roster of permitted actions. evaluate_story_self stays advisory-only; this
-- driver is the separate, gated action step it explicitly defers to.
--
-- Security: SECURITY DEFINER, service_role + authenticated.

CREATE OR REPLACE FUNCTION public.fn_hermes_learning_loop(
  p_story_id  uuid,
  p_run_id    uuid DEFAULT NULL,
  p_backend   text DEFAULT NULL,
  p_agent_slug text DEFAULT 'aisha'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id     uuid := auth.uid();
  v_is_service  boolean := current_setting('role', true) = 'service_role';
  v_eval        jsonb;
  v_findings    jsonb;
  v_finding     jsonb;
  v_learning_id uuid;
  v_proposals   jsonb := '[]'::jsonb;
  v_proposal    jsonb;
  v_score       numeric;
  v_level       text;
BEGIN
  -- Auth gate (mirrors evaluate_story_self): service_role is the trusted system
  -- caller (svc-agent-runner) without a user JWT; any other caller needs auth.uid().
  IF v_user_id IS NULL AND NOT v_is_service THEN
    RAISE EXCEPTION 'Unauthorized: not authenticated' USING ERRCODE = '22023';
  END IF;

  -- 1. Advisory evaluation (also refreshes story_goal_state — E15).
  v_eval := evaluate_story_self(p_story_id, p_backend);
  v_findings := COALESCE(v_eval -> 'findings', '[]'::jsonb);
  v_score := COALESCE((v_eval ->> 'score')::numeric, 0);
  v_level := COALESCE(v_eval ->> 'level', 'novice');

  -- No actionable findings → advisory-only; nothing to learn or propose.
  IF jsonb_array_length(v_findings) = 0 THEN
    RETURN jsonb_build_object(
      'eval', v_eval, 'learning_id', NULL, 'proposals', v_proposals, 'actioned', false);
  END IF;

  -- 2. Capture the hippocampus learning (needs a run_id to anchor the reflection).
  IF p_run_id IS NOT NULL THEN
    v_learning_id := fn_capture_learning(
      p_run_id := p_run_id,
      p_pattern := format('story %s at maturity %s (score %s): %s open finding(s)',
                          p_story_id, v_level, v_score, jsonb_array_length(v_findings)),
      p_resolution := COALESCE(
        v_eval -> 'recommended_actions' -> 0 ->> 'rationale',
        'review open findings; consider a gated improvement_proposal'),
      p_critic_scores := jsonb_build_object('score', v_score, 'level', v_level),
      p_story_id := p_story_id,
      p_agent_slug := p_agent_slug,
      p_importance := CASE WHEN v_findings @> '[{"severity":"high"}]'::jsonb THEN 7 ELSE 5 END
    );
  END IF;

  -- 3. Aggressive synthesis: one improvement_proposal per finding. The RPC itself
  --    risk-evaluates + rate-limits + dedups + auto-approves low-risk-on-autonomous.
  FOR v_finding IN SELECT * FROM jsonb_array_elements(v_findings)
  LOOP
    BEGIN
      v_proposal := fn_create_improvement_proposal(
        p_agent_slug := p_agent_slug,
        p_category := COALESCE(v_finding ->> 'kind', 'general'),
        p_description := COALESCE(v_finding ->> 'summary', ''),
        p_metadata := jsonb_build_object(
          'story_id', p_story_id,
          'severity', v_finding ->> 'severity',
          'kind', v_finding ->> 'kind',
          'maturity_level', v_level,
          'score', v_score,
          'anomaly_key', format('hermes:%s:%s', p_story_id, v_finding ->> 'kind'),
          'source', 'hermes_learning_loop'
        ),
        p_title := left(format('Hermes: %s', COALESCE(v_finding ->> 'summary', v_finding ->> 'kind')), 200)
      );
      v_proposals := v_proposals || v_proposal;
    EXCEPTION WHEN OTHERS THEN
      -- rate-limit / dedup / unknown-agent → record + continue (advisory: never brick).
      v_proposals := v_proposals || jsonb_build_object(
        'skipped', true, 'kind', v_finding ->> 'kind', 'reason', SQLERRM);
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'eval', v_eval, 'learning_id', v_learning_id, 'proposals', v_proposals, 'actioned', true);
END;
$$;

-- service_role only: this is a system-triggered orchestration step (svc-agent-runner
-- on story closure), not a user-callable RPC. Restricting to service_role keeps it a
-- least-privilege SECURITY DEFINER function whose access IS its auth gate (no broad
-- 'authenticated' grant that would demand an in-body auth check).
REVOKE ALL ON FUNCTION public.fn_hermes_learning_loop(uuid, uuid, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_hermes_learning_loop(uuid, uuid, text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_list_story_faithfulness_trend.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_list_story_faithfulness_trend
-- Phase 12 WP 1.5 — Faithfulness UI panel
-- Used by: src/hooks/useStoryFaithfulnessTrend.ts → StoryFaithfulnessSparkline.tsx
-- ============================================================================
--
-- Returns the most recent N faithfulness scores for a given story by joining
-- ai_runs (where faithfulness_score_estimate is populated by the critic loop
-- + RAG eval pipeline) and ordering by started_at DESC.
--
-- Visibility: re-enforces P7 RLS contract via is_admin_or_staff() OR
-- is_story_participant() — same pattern as get_workspace_context (WP 13.1).
--
-- NO PII in output — only score, timestamp, agent_slug. Body/prompt content
-- stays in Langfuse traces; this is a cardinal-low trend view for the
-- Overview tab sparkline.

CREATE OR REPLACE FUNCTION public.fn_list_story_faithfulness_trend(
  p_story_id uuid,
  p_limit int DEFAULT 50
)
RETURNS TABLE (
  run_id        uuid,
  faithfulness  numeric,
  agent_slug    text,
  kind          text,
  started_at    timestamptz,
  finished_at   timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_limit int := LEAST(GREATEST(p_limit, 1), 200);  -- cap at 200 for safety
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: not authenticated' USING ERRCODE = '22023';
  END IF;

  IF p_story_id IS NULL THEN
    RAISE EXCEPTION 'p_story_id is required' USING ERRCODE = '22023';
  END IF;

  -- Visibility check: admin/staff sees all, participants see own stories,
  -- stack-default story is visible to all authenticated users.
  IF NOT public.is_admin_or_staff(v_user_id)
     AND NOT public.is_story_participant(v_user_id, p_story_id)
     AND NOT EXISTS (
       SELECT 1 FROM public.partner_stories
       WHERE id = p_story_id AND is_stack_default = true
     ) THEN
    RAISE EXCEPTION 'Forbidden: not a participant of story %', p_story_id
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    ar.id,
    ar.faithfulness_score_estimate,
    (ar.metadata->>'current_agent_slug')::text AS agent_slug,
    ar.kind,
    ar.started_at,
    ar.finished_at
  FROM public.ai_runs ar
  WHERE ar.story_id = p_story_id
    AND ar.faithfulness_score_estimate IS NOT NULL
  ORDER BY ar.started_at DESC
  LIMIT v_limit;
END;
$$;

-- Permissions per CLAUDE.md SECURITY DEFINER pattern
REVOKE ALL ON FUNCTION public.fn_list_story_faithfulness_trend(uuid, int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_list_story_faithfulness_trend(uuid, int) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_user_can_read_run.sql
-- -----------------------------------------------------------------------------

/**
 * fn_user_can_read_run
 *
 * On-behalf-of authorization for reading an ai_run: returns true iff the given
 * user may read the given run. Mirrors the canonical ai_runs read authority
 * (RLS policies participant_read_ai_runs + admin_staff_read_ai_runs) and adds
 * the story OWNER, so the user who started a run can always drain it:
 *   - admin/staff                                  → always
 *   - run bound to a story AND (
 *       user is a story participant
 *       OR user owns the story (partner_stories.user_id)
 *       OR the story is the stack-default story )  → yes
 *   - system run (story_id IS NULL)                → admin/staff only
 *
 * Used by the Omni reflection-poll endpoint (GET /reflect/runs/:id) to authorize
 * a PAT caller against the LOADED run's story — identity comes from the validated
 * PAT (user_id), resource authz is checked here against the run. This lets a
 * scoped, unscoped, OR legacy PAT drain ITS OWN deferred run without relaxing the
 * §8.5 token story-binding that /v1/chat/completions still enforces.
 *
 * FAIL-CLOSED: a non-existent run_id matches no ai_runs row → EXISTS is false →
 * returns false, identical to "not allowed" (no existence oracle for the caller).
 *
 * STRÁŽ VOLAJÍCÍHO (2026-09-19): odpovídá jen o volajícím (p_user_id = auth.uid());
 * na kohokoli se smí ptát service_role (reflect.ts) a admin/staff — jinak false.
 *
 * @param p_user_id - the caller's user id (from the validated PAT)
 * @param p_run_id  - the ai_run to authorize
 * @returns boolean - true iff the user may read the run
 */
CREATE OR REPLACE FUNCTION public.fn_user_can_read_run(p_user_id uuid, p_run_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  -- ⛔ PREDIKÁT O TŘETÍ OSOBĚ JE ORÁKULUM (naměřeno 2026-09-19). Funkce je
  -- on-behalf-of autorizace pro SLUŽBU (svc-ai-chat reflect.ts ji volá service
  -- klíčem s user_id z ověřeného PAT), jenže GRANT pro `authenticated` ji vystavil
  -- i přímo: přihlášený člen se pro cizí uuid dozvěděl, zda smí číst který běh —
  -- tedy vlastnictví a účast v cizích story (a přes is_admin_or_staff(p_user_id)
  -- i cizí roli).
  --
  -- Odpovídá se jen o VOLAJÍCÍM; služba a správa na kohokoli. Změřeno, že to nic
  -- nerozbije: jediný volající v repu je reflect.ts přes rpcService (service_role).
  -- `false` = totéž, co „nesmí" i „běh neexistuje", takže zamítnutí nic neprozradí.
  SELECT CASE
    WHEN p_user_id IS NULL THEN false
    WHEN p_user_id = auth.uid()
      OR public.is_service_role()
      OR public.is_admin_or_staff()
    THEN EXISTS (
      SELECT 1
      FROM public.ai_runs r
      WHERE r.id = p_run_id
        AND (
          public.is_admin_or_staff(p_user_id)
          OR (
            r.story_id IS NOT NULL
            AND (
              public.is_story_participant(p_user_id, r.story_id)
              OR EXISTS (
                SELECT 1 FROM public.partner_stories ps
                WHERE ps.id = r.story_id
                  AND (ps.user_id = p_user_id OR ps.is_stack_default = true)
              )
            )
          )
        )
    )
    ELSE false
  END;
$function$;

REVOKE ALL ON FUNCTION public.fn_user_can_read_run(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_user_can_read_run(uuid, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_user_can_read_run(uuid, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_cross_story_summary.sql
-- -----------------------------------------------------------------------------

/**
 * get_cross_story_summary
 *
 * Returns a summary of a target story accessible via an accepted cross-story link.
 * Includes story metadata, recent entries (status updates, blockers, architecture
 * decisions, milestones), and link info. Access is validated via can_access_linked_story.
 * Logs the read to audit_journal.
 *
 * @param p_requesting_story_id - UUID of the story requesting the summary
 * @param p_target_story_id - UUID of the target story to summarize
 * @returns jsonb - Summary object with story details, recent entries, and link info
 */
CREATE OR REPLACE FUNCTION public.get_cross_story_summary(
  p_requesting_story_id uuid,
  p_target_story_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: not authenticated';
  END IF;

  IF NOT public.can_access_linked_story(v_user_id, p_requesting_story_id, p_target_story_id) THEN
    RAISE EXCEPTION 'Unauthorized: no cross-story access';
  END IF;

  SELECT jsonb_build_object(
    'story_id', ps.id,
    'title', ps.title,
    'delivery_status', ps.delivery_status,
    'tech_stack', ps.tech_stack,
    'domain', ps.domain,
    'participant_count', (
      SELECT count(*)::int
      FROM public.story_participants sp
      WHERE sp.story_id = ps.id
    ),
    'recent_entries', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'entry_type', se.entry_type,
        'summary', LEFT(se.content, 200),
        'created_at', se.created_at
      ) ORDER BY se.created_at DESC), '[]'::jsonb)
      FROM (
        SELECT entry_type, content, created_at
        FROM public.story_entries
        WHERE story_id = ps.id
          AND entry_type IN ('status_update', 'blocker', 'architecture_decision', 'milestone')
        ORDER BY created_at DESC
        LIMIT 5
      ) se
    ),
    'link_info', (
      SELECT jsonb_build_object(
        'link_type', sl.link_type,
        'link_direction', sl.link_direction,
        'created_at', sl.created_at,
        'confidence_score', sl.confidence_score
      )
      FROM public.story_links sl
      WHERE (
        (sl.source_story_id = p_requesting_story_id AND sl.target_story_id = p_target_story_id)
        OR (sl.source_story_id = p_target_story_id AND sl.target_story_id = p_requesting_story_id)
      )
      AND sl.is_accepted = true
      LIMIT 1
    )
  )
  INTO v_result
  FROM public.partner_stories ps
  WHERE ps.id = p_target_story_id;

  IF v_result IS NULL THEN
    RAISE EXCEPTION 'Target story not found: %', p_target_story_id;
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'CROSS_STORY_SUMMARY_READ',
    jsonb_build_object(
      'area', 'collaboration',
      'severity', 'info',
      'requesting_story_id', p_requesting_story_id,
      'target_story_id', p_target_story_id
    )
  );

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_cross_story_summary(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_cross_story_summary(uuid, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_linked_stories.sql
-- -----------------------------------------------------------------------------

/**
 * get_linked_stories
 *
 * Returns all stories linked to a given story (both incoming and outgoing links).
 * Includes linked story metadata, participant counts, and link details.
 * User must be a participant or admin/staff.
 *
 * @param p_story_id - UUID of the story to get links for
 * @returns jsonb - Array of linked story objects with link metadata
 */
CREATE OR REPLACE FUNCTION public.get_linked_stories(
  p_story_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: not authenticated';
  END IF;

  IF NOT public.is_story_participant(v_user_id, p_story_id) AND NOT public.is_admin_or_staff(v_user_id) THEN
    RAISE EXCEPTION 'Unauthorized: not a participant of this story';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      sl.id AS link_id,
      sl.link_type,
      sl.link_direction,
      sl.is_accepted,
      sl.confidence_score,
      sl.created_by_agent,
      sl.created_at AS link_created_at,
      CASE
        WHEN sl.source_story_id = p_story_id THEN sl.target_story_id
        ELSE sl.source_story_id
      END AS linked_story_id,
      CASE
        WHEN sl.source_story_id = p_story_id THEN 'outgoing'
        ELSE 'incoming'
      END AS direction,
      ps.title AS linked_story_title,
      ps.delivery_status AS linked_delivery_status,
      ps.tech_stack AS linked_tech_stack,
      ps.domain AS linked_domain,
      (
        SELECT count(*)::int
        FROM public.story_participants sp2
        WHERE sp2.story_id = CASE
          WHEN sl.source_story_id = p_story_id THEN sl.target_story_id
          ELSE sl.source_story_id
        END
      ) AS linked_participant_count
    FROM public.story_links sl
    JOIN public.partner_stories ps
      ON ps.id = CASE
        WHEN sl.source_story_id = p_story_id THEN sl.target_story_id
        ELSE sl.source_story_id
      END
    WHERE (sl.source_story_id = p_story_id OR sl.target_story_id = p_story_id)
    ORDER BY sl.created_at DESC
  ) t;

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_linked_stories(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_linked_stories(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_story_graph.sql
-- -----------------------------------------------------------------------------

/**
 * get_story_graph
 *
 * Returns a recursive graph of linked stories up to a configurable depth (max 3).
 * Uses a CTE to traverse accepted links and returns story metadata at each node.
 * Prevents cycles via path tracking.
 *
 * @param p_max_depth - Maximum traversal depth (capped at 3)
 * @param p_story_id - UUID of the root story
 * @returns jsonb - Array of graph node objects with depth, link info, and story metadata
 */
CREATE OR REPLACE FUNCTION public.get_story_graph(
  p_max_depth int DEFAULT 3,
  p_story_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: not authenticated';
  END IF;

  IF NOT public.is_story_participant(v_user_id, p_story_id) AND NOT public.is_admin_or_staff(v_user_id) THEN
    RAISE EXCEPTION 'Unauthorized: not a participant of this story';
  END IF;

  IF p_max_depth > 3 THEN
    p_max_depth := 3;
  END IF;

  WITH RECURSIVE story_graph AS (
    SELECT
      sl.id AS link_id,
      sl.source_story_id,
      sl.target_story_id,
      sl.link_type,
      sl.confidence_score,
      CASE
        WHEN sl.source_story_id = p_story_id THEN sl.target_story_id
        ELSE sl.source_story_id
      END AS connected_story_id,
      1 AS depth,
      ARRAY[p_story_id, CASE
        WHEN sl.source_story_id = p_story_id THEN sl.target_story_id
        ELSE sl.source_story_id
      END] AS path
    FROM public.story_links sl
    WHERE (sl.source_story_id = p_story_id OR sl.target_story_id = p_story_id)
      AND sl.is_accepted = true

    UNION ALL

    SELECT
      sl2.id AS link_id,
      sl2.source_story_id,
      sl2.target_story_id,
      sl2.link_type,
      sl2.confidence_score,
      CASE
        WHEN sl2.source_story_id = sg.connected_story_id THEN sl2.target_story_id
        ELSE sl2.source_story_id
      END AS connected_story_id,
      sg.depth + 1 AS depth,
      sg.path || CASE
        WHEN sl2.source_story_id = sg.connected_story_id THEN sl2.target_story_id
        ELSE sl2.source_story_id
      END
    FROM public.story_links sl2
    JOIN story_graph sg ON (
      sl2.source_story_id = sg.connected_story_id
      OR sl2.target_story_id = sg.connected_story_id
    )
    WHERE sg.depth < p_max_depth
      AND sl2.is_accepted = true
      AND NOT (CASE
        WHEN sl2.source_story_id = sg.connected_story_id THEN sl2.target_story_id
        ELSE sl2.source_story_id
      END = ANY(sg.path))
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'link_id', sg.link_id,
    'link_type', sg.link_type,
    'connected_story_id', sg.connected_story_id,
    'confidence_score', sg.confidence_score,
    'depth', sg.depth,
    'title', ps.title,
    'delivery_status', ps.delivery_status,
    'tech_stack', ps.tech_stack,
    'domain', ps.domain,
    'participant_count', (
      SELECT count(*)::int
      FROM public.story_participants sp
      WHERE sp.story_id = sg.connected_story_id
    )
  ) ORDER BY sg.depth, sg.link_type), '[]'::jsonb)
  INTO v_result
  FROM story_graph sg
  JOIN public.partner_stories ps ON ps.id = sg.connected_story_id;

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_story_graph(int, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_story_graph(int, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_story_matrix_rooms.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- get_story_matrix_rooms
-- =============================================================================
-- List active Matrix rooms for a story (optional filter).
-- =============================================================================

CREATE OR REPLACE FUNCTION public.get_story_matrix_rooms(
  p_story_id uuid DEFAULT NULL
)
RETURNS TABLE(
  id uuid,
  story_id uuid,
  matrix_room_id text,
  room_type text,
  bridge_type text,
  display_name text,
  is_active boolean,
  created_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  IF p_story_id IS NOT NULL THEN
    -- Room *metadata* is guarded by an RLS policy on the table, but this function
    -- is SECURITY DEFINER and so runs past it. Re-assert the same rule here: only a
    -- participant of THIS story (or admin/staff) may see its room mappings.
    IF NOT (public.is_admin_or_staff(v_user_id)
            OR public.is_story_participant(v_user_id, p_story_id)) THEN
      RAISE EXCEPTION 'Access denied: story participant or admin/staff required'
        USING ERRCODE = '42501';
    END IF;

    RETURN QUERY
    SELECT smr.id, smr.story_id, smr.matrix_room_id, smr.room_type::text,
           smr.bridge_type, smr.display_name, smr.is_active, smr.created_at
    FROM story_matrix_rooms smr
    WHERE smr.is_active = true
      AND smr.story_id = p_story_id
    ORDER BY smr.created_at DESC;
  ELSE
    -- "My rooms" (MatrixInbox): every mapping the caller is entitled to. Without
    -- this filter a NULL argument returned every room on the instance — a
    -- cross-story metadata leak to any authenticated user.
    RETURN QUERY
    SELECT smr.id, smr.story_id, smr.matrix_room_id, smr.room_type::text,
           smr.bridge_type, smr.display_name, smr.is_active, smr.created_at
    FROM story_matrix_rooms smr
    WHERE smr.is_active = true
      AND (
        public.is_admin_or_staff(v_user_id)
        OR EXISTS (
          SELECT 1 FROM story_participants sp
          WHERE sp.story_id = smr.story_id
            AND sp.user_id = v_user_id
        )
      )
    ORDER BY smr.created_at DESC;
  END IF;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_story_matrix_rooms(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_story_matrix_rooms(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_workspace_context.sql
-- -----------------------------------------------------------------------------

/**
 * get_workspace_context
 *
 * Returns a JSONB envelope of the caller's current AISHA workspace state for
 * Phase 13.1 (svc-ide-context). The envelope is consumed by per-IDE template
 * adapters (Claude Code, Cursor, GitHub Copilot, JetBrains future) to render
 * dynamic agent instructions that reflect what is actually happening RIGHT
 * NOW — not what was true at the time CLAUDE.md was generated.
 *
 * Contract:
 *   - SECURITY DEFINER + SET search_path TO 'public' (CLAUDE.md mandatory)
 *   - Caller MUST be authenticated (auth.uid() non-NULL)
 *   - Visibility is enforced application-side via is_story_participant() +
 *     is_admin_or_staff() helpers; RLS on underlying tables is bypassed by
 *     SECURITY DEFINER, so we manually re-implement the participant+admin
 *     visibility contract from P7 RLS policies.
 *   - NO PII in output — only IDs, slugs, statuses, timestamps, counts.
 *     `audit_journal.summary` field is INCLUDED because it is already PII-safe
 *     per project convention (per `feedback_no_pii_in_metadata.md`).
 *   - Output capped at small bounded sizes (top N stories, last 30 audit rows)
 *     so the rendered IDE instructions stay under a few KB.
 *
 * Returns jsonb with shape:
 *   {
 *     "user_id": uuid,
 *     "workspace_id": text (optional, opaque caller-supplied id),
 *     "generated_at": timestamptz,
 *     "stories": [ { id, title, status, delivery_status, is_stack_default,
 *                    default_branch, last_activity_at } ],
 *     "active_runs": [ { id, story_id, kind, status, started_at,
 *                        current_agent_slug } ],
 *     "pending_approvals": [ { story_id, story_title, delivery_status,
 *                              last_activity_at } ],
 *     "recent_audit": [ { id, action, severity, area, summary, created_at } ],
 *     "deploy_state": [ { app_name, story_id, active_slot, last_switch_at,
 *                         blue_health, green_health } ]
 *   }
 *
 * @param p_workspace_id - Optional opaque caller workspace id (e.g. local
 *                        machine + repo identifier). Echoed back in envelope.
 * @returns jsonb envelope
 */
CREATE OR REPLACE FUNCTION public.get_workspace_context(
  p_workspace_id text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_is_privileged boolean;
  v_envelope jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: not authenticated';
  END IF;

  v_is_privileged := public.is_admin_or_staff(v_user_id);

  WITH visible_stories AS (
    SELECT
      s.id,
      s.title,
      s.status,
      s.delivery_status,
      s.is_stack_default,
      s.default_branch,
      s.last_activity_at
    FROM public.partner_stories s
    WHERE
      v_is_privileged
      OR s.is_stack_default = true
      OR public.is_story_participant(v_user_id, s.id)
    ORDER BY s.last_activity_at DESC NULLS LAST
    LIMIT 10
  ),
  active_runs AS (
    SELECT
      r.id,
      r.story_id,
      r.kind,
      r.status,
      r.started_at,
      r.metadata->>'current_agent_slug' AS current_agent_slug
    FROM public.ai_runs r
    WHERE r.status = 'running'
      AND r.story_id IN (SELECT vs.id FROM visible_stories vs)
    ORDER BY r.started_at DESC
    LIMIT 20
  ),
  pending_approvals AS (
    SELECT
      vs.id AS story_id,
      vs.title AS story_title,
      vs.delivery_status,
      vs.last_activity_at
    FROM visible_stories vs
    JOIN public.delivery_statuses ds ON ds.status = vs.delivery_status
    WHERE ds.requires_approval = true
      AND ds.is_active = true
    ORDER BY vs.last_activity_at DESC
    LIMIT 20
  ),
  recent_audit AS (
    SELECT
      aj.id,
      aj.action,
      aj.severity,
      aj.area,
      aj.summary,
      aj.created_at
    FROM public.audit_journal aj
    WHERE v_is_privileged
       OR aj.user_id = v_user_id
    ORDER BY aj.created_at DESC
    LIMIT 30
  ),
  deploy_state AS (
    SELECT
      cas.app_name,
      cas.story_id,
      cas.active_slot,
      cas.last_switch_at,
      cas.blue_health,
      cas.green_health
    FROM public.coolify_app_slots cas
    WHERE cas.story_id IN (SELECT vs.id FROM visible_stories vs)
       OR (cas.story_id IS NULL AND v_is_privileged)
    ORDER BY cas.last_switch_at DESC NULLS LAST
    LIMIT 20
  )
  SELECT jsonb_build_object(
    'user_id', v_user_id,
    'workspace_id', p_workspace_id,
    'generated_at', now(),
    'is_privileged', v_is_privileged,
    'stories', COALESCE((SELECT jsonb_agg(row_to_json(s)) FROM visible_stories s), '[]'::jsonb),
    'active_runs', COALESCE((SELECT jsonb_agg(row_to_json(r)) FROM active_runs r), '[]'::jsonb),
    'pending_approvals', COALESCE((SELECT jsonb_agg(row_to_json(p)) FROM pending_approvals p), '[]'::jsonb),
    'recent_audit', COALESCE((SELECT jsonb_agg(row_to_json(a)) FROM recent_audit a), '[]'::jsonb),
    'deploy_state', COALESCE((SELECT jsonb_agg(row_to_json(d)) FROM deploy_state d), '[]'::jsonb)
  ) INTO v_envelope;

  RETURN v_envelope;
END;
$function$;

-- Permissions per CLAUDE.md SECURITY DEFINER pattern
REVOKE ALL ON FUNCTION public.get_workspace_context(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_workspace_context(text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/is_story_partner.sql
-- -----------------------------------------------------------------------------

-- Function: is_story_partner

CREATE OR REPLACE FUNCTION public.is_story_partner(p_user_id uuid, p_story_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- ⛔ PREDIKÁT O TŘETÍ OSOBĚ JE ORÁKULUM (2026-09-18, sesterská oprava has_role).
  -- Funkce má GRANT pro anon a pravdivě odpovídala komukoli na „je uživatel X
  -- partnerem příběhu Y?". Odpověď dostane jen ten, na koho se ptá, service_role
  -- a admin/staff; ostatním `false`. Jediný volající (RLS na story_participants)
  -- se ptá na `(SELECT auth.uid())`, takže první větev platí a RLS se nemění.
  -- Vnořený CASE, ne `OR`: u RLS se vyhodnotí jen levné porovnání, dotaz na roli
  -- (is_service_role/is_admin_or_staff) až tehdy, když se ptá někdo jiný.
  SELECT CASE
    WHEN p_user_id IS NULL THEN false
    WHEN p_user_id = auth.uid() THEN EXISTS (
      SELECT 1 FROM public.story_participants
      WHERE user_id = p_user_id AND story_id = p_story_id AND role = 'partner'
    )
    WHEN public.is_service_role() OR public.is_admin_or_staff() THEN EXISTS (
      SELECT 1 FROM public.story_participants
      WHERE user_id = p_user_id AND story_id = p_story_id AND role = 'partner'
    )
    ELSE false
  END;
$function$

;

REVOKE ALL ON FUNCTION is_story_partner(uuid,uuid) FROM PUBLIC;
-- ⚠️ ZÁMĚRNĚ BEZ GRANTU — a je to ZNÁMÁ ŽIVÁ VADA, ne stav, který by byl v pořádku.
--
-- Funkci volají dvě politiky na story_participants. Bez grantu spadne dotaz na
-- „permission denied for function". Grant sem ale nemůže padnout jen tak:
-- funkce bere uživatele PARAMETREM a uvnitř nemá vazbu na volajícího, takže by
-- kdokoli přihlášený mohl zjišťovat partnerství KOHOKOLI na kterékoli story.
-- security.gate to právem odmítá (SECURITY DEFINER bez auth checku).
--
-- Zkusil jsem doplnit vazbu `p_user_id IS DISTINCT FROM auth.uid() AND NOT
-- is_admin_or_staff() → false`; obě volající politiky předávají auth.uid(),
-- takže se chování nemění. Analyzátor to ale neuznal a nedopátral jsem se
-- proč — neověřenou změnu bezpečnostního pravidla nenasazuji.
--
-- Otevřené (viz PR): buď dořešit vazbu tak, aby ji analyzátor uznal, nebo
-- politiky přepsat na jiný pomocník. Do rozhodnutí zůstává bez grantu.
-- ⛔ REVOKE bez následného GRANTu: funkci volá RLS politika, ale spustit ji
-- nesměl NIKDO — ani service_role. Každý dotaz na dotčenou tabulku spadl na
-- „permission denied for function". SECURITY DEFINER, boolean, NULL-bezpečná.
GRANT EXECUTE ON FUNCTION is_story_partner(uuid,uuid) TO anon;
GRANT EXECUTE ON FUNCTION is_story_partner(uuid,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION is_story_partner(uuid,uuid) TO service_role;


