-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/is_user_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: is_user_admin
-- Popis: Helper RPC volaný z n8n webhook handlerů (action button targets) pro
--        ověření admin role. Mapuje na is_admin_or_staff ale s explicitním
--        admin-only check (NEberou v potaz staff).
-- Volá: n8n action handlers (drift-now, force B/G switch, manual rollback, ...)
-- Auth: any authenticated (returns boolean, no exception throw)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.is_user_admin(
  p_user_id uuid DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_user_id uuid;
BEGIN
  -- ⛔ PREDIKÁT O TŘETÍ OSOBĚ JE ORÁKULUM (naměřeno 2026-09-19). S pořadím
  -- COALESCE s parametrem na prvním místě vyhrál parametr, takže kterýkoli přihlášený
  -- se pro libovolné uuid dozvěděl, zda je to administrátor — tatáž třída jako
  -- has_role. Oprava je fáze 2 z brány security-hardened-helpers: JWT vyhrává.
  -- Přihlášený se ptá vždy za sebe; parametr platí jen tam, kde JWT identitu
  -- nenese (service klíč n8n handlerů). Změřeno, že to nic nerozbije: všechna
  -- volání v repu (aisha_publish/deprecate_static_defense_rule, lock_tooling_proposal)
  -- jsou bez argumentu, tedy za sebe. Anon právo nemá — kdyby ho dostal,
  -- auth-first by ho NEchránil; hlídá to brána definer-subjekt-jen-volajici.
  v_user_id := COALESCE(auth.uid(), p_user_id);

  IF v_user_id IS NULL THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.user_roles
    WHERE user_id = v_user_id
      AND role = 'admin'
  );
END;
$$;

REVOKE ALL ON FUNCTION public.is_user_admin(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_user_admin(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.is_user_admin(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_deprecate_static_defense_rule.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: aisha_deprecate_static_defense_rule
-- Popis: State transition active → deprecated. Pravidlo se přestane objevovat
--        v gen-static-defense výstupu (a Semgrep ho přestane enforce), ale
--        řádek zůstane v tabulce pro audit/historii a pro fail-loud guard:
--        budoucí propose se stejným rule_id selže (musíš použít nový name).
--
-- Volá: Appsmith operator UI (retire), Aisha autonomní decay logic
-- Auth: Admin only
-- Audit: insert do audit_journal s rationale (proč rule retired)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.aisha_deprecate_static_defense_rule(
  p_rule_id              text,
  p_deprecation_rationale text
)
RETURNS public.aisha_static_defense_rules
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row      public.aisha_static_defense_rules;
  v_existing public.aisha_static_defense_rules;
BEGIN
  IF NOT public.is_user_admin() THEN
    RAISE EXCEPTION 'Unauthorized: deprecating static-defense rules requires admin role'
      USING ERRCODE = '22023';
  END IF;

  IF p_deprecation_rationale IS NULL OR length(p_deprecation_rationale) < 20 THEN
    RAISE EXCEPTION 'Deprecation rationale required (min 20 chars) — explain WHY this rule is being retired'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_existing
  FROM public.aisha_static_defense_rules
  WHERE rule_id = p_rule_id;

  IF v_existing IS NULL THEN
    RAISE EXCEPTION 'Rule % not found', p_rule_id USING ERRCODE = '22023';
  END IF;
  IF v_existing.status = 'deprecated' THEN
    RAISE EXCEPTION 'Rule % is already deprecated', p_rule_id USING ERRCODE = '22023';
  END IF;

  UPDATE public.aisha_static_defense_rules
  SET status = 'deprecated'
  WHERE rule_id = p_rule_id
  RETURNING * INTO v_row;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'static_defense_rule_deprecated',
    jsonb_build_object(
      'rule_id', p_rule_id,
      'category', v_row.category,
      'previous_status', v_existing.status,
      'deprecation_rationale', p_deprecation_rationale,
      'reminder', 'Operator must add migration capturing this status change + regenerate YAML + commit. CI gate static-defense-generator-integrity.gate.test.ts enforces sync.'
    )
  );

  RETURN v_row;
END;
$$;

REVOKE ALL ON FUNCTION public.aisha_deprecate_static_defense_rule(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aisha_deprecate_static_defense_rule(text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aisha_deprecate_static_defense_rule(text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_publish_static_defense_rule.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: aisha_publish_static_defense_rule
-- Popis: State transition draft → active. Marks rule as live; from this point
--        gen-static-defense includes it in .semgrep/aisha-rules.yml output
--        and Semgrep CI enforces it.
--
--        Důležité: po úspěšném publish operator MUSÍ vytvořit migration
--        (nebo nový timestamp s INSERT statement) + spustit gen:static-defense
--        + commit. CI gates verifies sync mezi DB seed migrations a checked-in
--        YAML — bez tohoto follow-up by se rule v live YAML neobjevila.
--
-- Volá: Appsmith operator approve action, WF_APPROVAL_GATE callback
-- Auth: Admin only (publish je závazné rozhodnutí, ne autonomní)
-- Audit: insert do audit_journal s reviewer + rationale
-- ============================================================================

CREATE OR REPLACE FUNCTION public.aisha_publish_static_defense_rule(
  p_rule_id           text,
  p_publish_rationale text DEFAULT NULL
)
RETURNS public.aisha_static_defense_rules
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row     public.aisha_static_defense_rules;
  v_existing public.aisha_static_defense_rules;
BEGIN
  -- Auth: publish je závazné, jen admin
  IF NOT public.is_user_admin() THEN
    RAISE EXCEPTION 'Unauthorized: publishing static-defense rules requires admin role'
      USING ERRCODE = '22023';
  END IF;

  -- Validation: rule must exist as draft
  SELECT * INTO v_existing
  FROM public.aisha_static_defense_rules
  WHERE rule_id = p_rule_id;

  IF v_existing IS NULL THEN
    RAISE EXCEPTION 'Rule % not found', p_rule_id USING ERRCODE = '22023';
  END IF;
  IF v_existing.status = 'active' THEN
    RAISE EXCEPTION 'Rule % is already active', p_rule_id USING ERRCODE = '22023';
  END IF;
  IF v_existing.status = 'deprecated' THEN
    RAISE EXCEPTION 'Rule % is deprecated — propose a new rule_id', p_rule_id USING ERRCODE = '22023';
  END IF;

  -- Transition draft → active
  UPDATE public.aisha_static_defense_rules
  SET status      = 'active',
      approved_by = auth.uid()
      -- updated_at via trigger
  WHERE rule_id = p_rule_id
  RETURNING * INTO v_row;

  -- Audit trail — link reviewer + rationale to the state change
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'static_defense_rule_published',
    jsonb_build_object(
      'rule_id', p_rule_id,
      'category', v_row.category,
      'severity', v_row.severity,
      'version', v_row.version,
      'previous_status', v_existing.status,
      'publish_rationale', p_publish_rationale,
      'reminder', 'Operator must add INSERT migration + regenerate YAML + commit. CI gate static-defense-generator-integrity.gate.test.ts will fail until both are committed.'
    )
  );

  RETURN v_row;
END;
$$;

REVOKE ALL ON FUNCTION public.aisha_publish_static_defense_rule(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aisha_publish_static_defense_rule(text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aisha_publish_static_defense_rule(text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/je_ucet_zarizeni_platny.sql
-- -----------------------------------------------------------------------------

-- Function: je_ucet_zarizeni_platny
-- Je účet účtem tabletu s PLATNÝM průkazem — schválený, neodvolaný, nevypršelý?
-- Pátá cesta workflow_step_visible_to se ptá TADY při každém volání, takže odvolání
-- průkazu platí hned (nejpozději do vypršení krátkého tokenu, i kdyby ho někdo držel).
-- Oracle guard: přihlášený se smí ptát jen na sebe; service/admin na kohokoli.
CREATE OR REPLACE FUNCTION public.je_ucet_zarizeni_platny(p_uid uuid)
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF (p_uid = auth.uid() OR public.is_service_role() OR public.is_admin_or_staff()) IS NOT TRUE THEN
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.knock_device_credentials d
     WHERE d.ucet_id = p_uid
       AND d.druh = 'tablet'
       AND d.approved_at IS NOT NULL
       AND d.revoked_at IS NULL
       AND (d.plati_do IS NULL OR d.plati_do > now()));
END;
$function$;

REVOKE ALL ON FUNCTION public.je_ucet_zarizeni_platny(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.je_ucet_zarizeni_platny(uuid) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/join_intranet_channel.sql
-- -----------------------------------------------------------------------------

-- Join a user to an intranet chat channel.
-- Auth-first COALESCE: auth.uid() (JWT) always wins for authenticated callers.
-- Service_role (auth.uid() IS NULL) falls back to explicit p_user_id.
CREATE OR REPLACE FUNCTION public.join_intranet_channel(
  p_channel_slug text,
  p_user_id uuid DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_caller uuid := COALESCE(auth.uid(), p_user_id);
  v_channel record;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT
    icc.id,
    icc.channel_type
  INTO v_channel
  FROM intranet_chat_channels icc
  WHERE icc.slug = p_channel_slug AND NOT icc.is_archived;

  IF v_channel IS NULL THEN
    RAISE EXCEPTION 'channel_not_found';
  END IF;

  -- Only general channels allow self-join; others require admin/staff
  IF v_channel.channel_type != 'general' THEN
    IF NOT EXISTS (SELECT 1 FROM user_roles ur WHERE ur.user_id = v_caller AND ur.role IN ('admin', 'staff')) THEN
      RAISE EXCEPTION 'channel_requires_invite';
    END IF;
  END IF;

  INSERT INTO intranet_chat_members (channel_id, user_id, role)
  VALUES (v_channel.id, v_caller, 'member')
  ON CONFLICT (channel_id, user_id) DO NOTHING;

  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION join_intranet_channel(text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION join_intranet_channel(text, uuid) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/join_ptt_channel.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- join_ptt_channel
-- =============================================================================
-- Find-or-create PTT room + upsert self as participant.
-- =============================================================================

CREATE OR REPLACE FUNCTION public.join_ptt_channel(
  p_livekit_room_name text DEFAULT NULL,
  p_room_name text DEFAULT NULL,
  p_story_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_room_id uuid;
  v_room_livekit_name text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_story_id IS NULL OR p_livekit_room_name IS NULL OR p_room_name IS NULL THEN
    RAISE EXCEPTION 'Missing required parameters';
  END IF;
  -- ⛔ Audit vydání 2026-10-01 (B2): kdokoli přihlášený se zapsal do PTT kanálu
  -- cizí story (a když žádný nebyl, rovnou ho založil). Poslouchat smí každý,
  -- kdo story vidí; založit kanál jen ten, kdo do ní smí psát (role ≠ viewer).
  IF NOT public.can_access_story(p_story_id) THEN
    RAISE EXCEPTION 'Access denied: story owner or participant required'
      USING ERRCODE = '42501';
  END IF;

  -- Try to find existing active PTT room for story
  SELECT vr.id, vr.livekit_room_name
  INTO v_room_id, v_room_livekit_name
  FROM voice_rooms vr
  WHERE vr.story_id = p_story_id
    AND vr.room_type = 'ptt'
    AND vr.is_active = true
  LIMIT 1;

  -- Create new room if none exists
  IF v_room_id IS NULL THEN
    IF NOT public.can_access_story(p_story_id, true) THEN
      RAISE EXCEPTION 'Access denied: creating a PTT channel requires write access to the story'
        USING ERRCODE = '42501';
    END IF;
    INSERT INTO voice_rooms (name, room_type, story_id, livekit_room_name, max_participants, created_by)
    VALUES (p_room_name, 'ptt', p_story_id, p_livekit_room_name, 20, v_user_id)
    RETURNING id, livekit_room_name INTO v_room_id, v_room_livekit_name;
  END IF;

  -- Upsert participant
  INSERT INTO call_participants (voice_room_id, user_id, role, is_muted, joined_at, left_at)
  VALUES (v_room_id, v_user_id, 'participant', true, now(), NULL)
  ON CONFLICT (voice_room_id, user_id) DO UPDATE SET
    is_muted = true,
    joined_at = now(),
    left_at = NULL;

  RETURN jsonb_build_object(
    'room_id', v_room_id,
    'room_name', v_room_livekit_name
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.join_ptt_channel(text, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.join_ptt_channel(text, text, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/kanban_stories_view.sql
-- -----------------------------------------------------------------------------

-- Function: public.kanban_stories_view
-- Description: Drives the mission-control kanban (`/admin/mission-control/kanban`).
--   Returns one row per visible story, joined with:
--     - workflow_statuses (swimlane label, sort order, color, is_terminal)
--     - latest ai_runs row (current_agent_slug, current_run_status)
--     - latest ai_trace_event timestamp (last_event_at)
--     - per-story AI cost aggregate (cost_to_date, tokens_to_date) over ai_runs
--     - per-story budget cap (ai_budget scope_type='story') → limit / consumed / state
--   Visibility:
--     - Admin/staff: every story
--     - Otherwise: participant stories ∪ stack-default singleton
--   The query is intentionally read-only — drag-drop mutations go through
--   update_story_status_audited (transition graph in workflow_status_transitions).
-- Security: SECURITY DEFINER. Authorization performed inline (mirrors
--   get_story_detail_audited's admin-or-participant pattern).
-- See also: workflow_statuses, workflow_status_transitions,
--   update_story_status_audited, ai_budget, useKanbanBoard hook.

-- A currency-suffixed name (`*_usd`) was removed from this function's signature.
-- The TYPES did not change, so CREATE OR REPLACE matches the deployed function and
-- Postgres refuses to rename in place ("cannot change name of input parameter", or
-- "cannot change return type" when the renamed name is a RETURNS TABLE column).
-- DROP-first is the convention used elsewhere in this directory; the REVOKE/GRANT
-- below re-applies whatever privileges the drop clears.
DROP FUNCTION IF EXISTS public.kanban_stories_view(uuid);

CREATE OR REPLACE FUNCTION public.kanban_stories_view(
  p_partner_id uuid DEFAULT NULL
)
RETURNS TABLE (
  story_id              uuid,
  partner_id            uuid,
  user_id               uuid,
  is_stack_default      boolean,
  title                 text,
  status                text,
  status_label_i18n_key text,
  status_sort_order     int,
  status_swimlane_color text,
  status_is_terminal    boolean,
  priority              text,
  is_starred            boolean,
  last_activity_at      timestamptz,
  default_branch        text,
  latest_run_id         uuid,
  current_agent_slug    text,
  current_run_status    text,
  last_event_at         timestamptz,
  cost_to_date      numeric,
  tokens_to_date        bigint,
  budget_cost_limit numeric,
  budget_consumed   numeric,
  budget_state          text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_is_admin boolean := false;
BEGIN
  IF v_user_id IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  v_is_admin := public.is_admin_or_staff(v_user_id);

  RETURN QUERY
  WITH visible_stories AS (
    SELECT ps.*
    FROM public.partner_stories ps
    WHERE
      (p_partner_id IS NULL OR ps.partner_id = p_partner_id)
      AND (
        v_is_admin
        OR ps.is_stack_default = true
        OR EXISTS (
          SELECT 1 FROM public.story_participants sp
          WHERE sp.story_id = ps.id AND sp.user_id = v_user_id
        )
      )
  ),
  latest_runs AS (
    SELECT DISTINCT ON (ar.story_id)
      ar.story_id,
      ar.id        AS run_id,
      ar.status    AS run_status,
      COALESCE(
        ar.route_plan -> 'agents' -> 0 ->> 'slug',
        ar.metadata ->> 'agent_slug',
        ar.kind
      ) AS agent_slug,
      ar.started_at,
      ar.finished_at
    FROM public.ai_runs ar
    WHERE ar.story_id IS NOT NULL
      AND ar.story_id IN (SELECT id FROM visible_stories)
    ORDER BY ar.story_id, ar.started_at DESC
  ),
  cost_agg AS (
    -- Per-story AI spend to date, aggregated over the canonical
    -- ai_runs.cost_total_json = { total, tokens_input, tokens_output }.
    SELECT
      ar.story_id,
      COALESCE(SUM(NULLIF(ar.cost_total_json->>'total', '')::numeric), 0) AS cost_to_date,
      -- SUM() over bigint operands returns numeric; the RETURNS TABLE column
      -- is declared bigint, so cast back explicitly or the function raises
      -- 42804 (numeric vs bigint) for every caller. See also final projection.
      COALESCE(SUM(
        COALESCE(NULLIF(ar.cost_total_json->>'tokens_input',  '')::bigint, 0) +
        COALESCE(NULLIF(ar.cost_total_json->>'tokens_output', '')::bigint, 0)
      ), 0)::bigint AS tokens_to_date
    FROM public.ai_runs ar
    WHERE ar.story_id IS NOT NULL
      AND ar.story_id IN (SELECT id FROM visible_stories)
    GROUP BY ar.story_id
  ),
  latest_events AS (
    SELECT lr.story_id, MAX(ate.created_at) AS last_event_at
    FROM latest_runs lr
    LEFT JOIN public.ai_trace_events ate ON ate.run_id = lr.run_id
    GROUP BY lr.story_id
  )
  SELECT
    vs.id                                       AS story_id,
    vs.partner_id,
    vs.user_id,
    vs.is_stack_default,
    vs.title,
    vs.status,
    ws.label_i18n_key                           AS status_label_i18n_key,
    ws.sort_order                               AS status_sort_order,
    ws.swimlane_color                           AS status_swimlane_color,
    COALESCE(ws.is_terminal, false)             AS status_is_terminal,
    vs.priority,
    vs.is_starred,
    vs.last_activity_at,
    vs.default_branch,
    lr.run_id                                   AS latest_run_id,
    lr.agent_slug                               AS current_agent_slug,
    lr.run_status                               AS current_run_status,
    le.last_event_at,
    COALESCE(ca.cost_to_date, 0)            AS cost_to_date,
    COALESCE(ca.tokens_to_date, 0)::bigint      AS tokens_to_date,
    ab.cost_limit                           AS budget_cost_limit,
    ab.consumed_cost                        AS budget_consumed,
    CASE
      WHEN ab.id IS NULL THEN NULL
      WHEN (ab.cost_limit IS NOT NULL AND ab.cost_limit > 0
            AND ab.consumed_cost / ab.cost_limit >= 1)
        OR (ab.token_limit IS NOT NULL AND ab.token_limit > 0
            AND ab.consumed_tokens::numeric / ab.token_limit >= 1)
        THEN 'stopped'
      WHEN (ab.cost_limit IS NOT NULL AND ab.cost_limit > 0
            AND ab.consumed_cost / ab.cost_limit >= 0.8)
        OR (ab.token_limit IS NOT NULL AND ab.token_limit > 0
            AND ab.consumed_tokens::numeric / ab.token_limit >= 0.8)
        THEN 'approaching'
      ELSE 'ok'
    END                                         AS budget_state
  FROM visible_stories vs
  LEFT JOIN public.workflow_statuses ws ON ws.status = vs.status
  LEFT JOIN latest_runs lr              ON lr.story_id = vs.id
  LEFT JOIN latest_events le            ON le.story_id = vs.id
  LEFT JOIN cost_agg ca                 ON ca.story_id = vs.id
  LEFT JOIN public.ai_budget ab         ON ab.scope_type = 'story'
                                       AND ab.scope_id = vs.id
                                       AND ab.period = 'lifetime'
  ORDER BY
    -- Stack-default first (pinned lane), then by sort_order, then by recency.
    vs.is_stack_default DESC,
    COALESCE(ws.sort_order, 9999) ASC,
    vs.last_activity_at DESC;
END;
$$;

REVOKE ALL ON FUNCTION public.kanban_stories_view(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.kanban_stories_view(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.kanban_stories_view(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/kiosk_device_stav.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: kiosk_device_stav
-- Popis: Stav průkazu zařízení pro samotné zařízení (tablet čeká na schválení
--        a ptá se, jestli už smí klepat sám) a veřejný klíč pro ověření jeho
--        podepsaného požadavku v bráně.
-- Bezpečnost: SECURITY DEFINER, JEN služba (brána). Tablet se ptá přes bránu
--             podepsaným požadavkem; bez podpisu klíčem `kid` odpověď nedostane.
--
-- Kontrakt: (text) -> jsonb {ok, stav, public_key_hex} | {ok:false, error:'nezname'}
--   stav: 'ceka' | 'schvaleno' | 'odvolano'
-- ============================================================================

CREATE OR REPLACE FUNCTION public.kiosk_device_stav(p_kid text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_radek public.knock_device_credentials%ROWTYPE;
BEGIN
  IF NOT (SELECT public.is_service_role()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  SELECT * INTO v_radek FROM public.knock_device_credentials WHERE kid = p_kid;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nezname');
  END IF;
  RETURN jsonb_build_object(
    'ok', true,
    'public_key_hex', v_radek.public_key_hex,
    'stav', CASE
      WHEN v_radek.revoked_at IS NOT NULL THEN 'odvolano'
      WHEN v_radek.approved_at IS NOT NULL THEN 'schvaleno'
      ELSE 'ceka'
    END
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.kiosk_device_stav(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.kiosk_device_stav(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/kiosk_projekce.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: kiosk_projekce
-- Popis: CO Z KROKU SMÍ NA TABLET (F2-C). Jediné místo, které z `input_data` kroku
--        vybere klíče povolené rozsahem instance (`kiosk_rozsah.pole` všech aktivních
--        řádků, které krok pokrývají). Používají ji všechna čtení pro účet zařízení
--        (get_kiosk_rozvozy, get_workflow_step_detail) — dvě kopie by se rozešly
--        a osobní údaj by utekl tou, na kterou se zapomnělo.
--
-- ⭐ Majitel 2026-09-29: osobní údaje odběratele (přebírající, kontakty, telefon,
--    e-mail) na tablet NEJDOU. Co jde, určuje instance v datech (`pole`), ne kód.
--
-- Bez pokrývajícího řádku = prázdný objekt (fail-closed). Interní pomocník volaný
-- z SECURITY DEFINER čtení: klientům žádný grant.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.kiosk_projekce(p_step_code text, p_input jsonb)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb)
    FROM jsonb_each(coalesce(p_input, '{}'::jsonb)) e
   WHERE e.key IN (SELECT p
                     FROM public.kiosk_rozsah r, unnest(r.pole) p
                    WHERE r.aktivni
                      AND r.step_code = p_step_code
                      AND coalesce(p_input, '{}'::jsonb) @> r.input_match)
$function$;

REVOKE ALL ON FUNCTION public.kiosk_projekce(text, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.kiosk_projekce(text, jsonb) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.kiosk_projekce(text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/kiosk_tahac.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: kiosk_tahac
-- Popis: Registrační značka TAHAČE ze zápisu soupravy (F2-C, výběr „podle vozidla“).
--        vehicle_registration nese i soupravu („1T2 3456/2T3 4567“, „…+…“): tahač je
--        první část před / , + ; velká písmena A–Z0–9 (měření RIQi 2026-09-29).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.kiosk_tahac(p_rz text)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT nullif(upper(regexp_replace(split_part(regexp_replace(coalesce(p_rz, ''), '[,+]', '/', 'g'), '/', 1),
                                     '[^A-Za-z0-9]', '', 'g')), '')
$function$;

REVOKE ALL ON FUNCTION public.kiosk_tahac(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.kiosk_tahac(text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/kiosk_krok_nasi_flotily.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Function: kiosk_krok_nasi_flotily(p_input jsonb) → boolean
-- Patří krok (jeho input_data) NAŠÍ flotile — řidiči nebo vozidlu spárovanému
-- s Webdispečinkem? Jediný rozhodce „čí“ pro tablet (účet zařízení).
-- ============================================================================
-- ⭐ MAJITEL 2026-09-30 (přes RIQi): „podle SPZ a podle řidiče, z našich řidičů —
--    co máme spárované s Webdispečinkem. To, že je to naše doprava, má pomáhat
--    ingestu, ale nemá si to sám řešit tablet.“
--
-- Krok patří naší flotile, když platí ALESPOŇ jedno:
--   ŘIDIČ    — dvojče řidiče z dodáku (`authorized_twin_id`, vazbu dělá ingest) je DRUHU
--              `driver` a má POTVRZENÉ, právě platné párování s Webdispečinkem
--              (`webdispecink` / `primary_id` / `ridic:<id>`).
--   VOZIDLO  — SPZ z dodáku (`vehicle_registration`, tahač = první část, `kiosk_tahac`)
--              je SPZ aktivního vozidla Webdispečinku, jehož párování na dvojče DRUHU
--              `vehicle` je POTVRZENÉ a právě platné (`webdispecink` / `primary_id` /
--              `wd_car_id`).
--
-- ⛔ JEN POTVRZENÉ PÁROVÁNÍ (pravidlo majitele): shoda jména nebo SPZ z dodáku sama
--    o sobě nic neznamená — návrh sjednocení dělá ingest a schvaluje člověk
--    (`twin_identity_confirm_binding`). `proposed` / `rejected` / `superseded`
--    ani párování mimo platnost (valid_from/valid_to) tablet nepustí.
-- ⛔ DRUH ENTITY JE SOUČÁST KLÍČE (09-27: vozidlo 5 kolidovalo s osobou 5): SPZ se
--    páruje jen na dvojče vozidla, klíč řidiče jen na dvojče řidiče.
-- ⛔ SPZ SE BERE ZE STRANY WEBDISPEČINKU (`wd_vehicles.identifier`, evidence flotily),
--    ne z vazeb navržených ingestem — ty jsou `proposed` a podle pravidla výše nestačí.
--    `identifier` je „SPZ nebo název“: název se se SPZ z dodáku nepotká a vozidlo tím
--    poctivě vypadne (řidičova větev ho může pokrýt).
--
-- Bez párování (dnes 0 odkazů Webdispečinku) je výsledek false → tablet je poctivě
-- prázdný, žádný návrat k „všichni“.
--
-- Klient ji volat nesmí (byla by to věštírna „je tahle SPZ naše?“): volá ji jen definer
-- predikátu viditelnosti (`workflow_step_visible_to`, větev zařízení).
--
-- plpgsql, ne sql: tělo SQL funkce se ověřuje při CREATE a na čisté DB (baseline) by se
-- tahle funkce mohla založit dřív než `kiosk_tahac`, na kterou sahá.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.kiosk_krok_nasi_flotily(p_input jsonb)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN (
  WITH krok AS (
    SELECT CASE
             WHEN (p_input->>'authorized_twin_id') ~* '^[0-9a-f]{8}-([0-9a-f]{4}-){3}[0-9a-f]{12}$'
               THEN (p_input->>'authorized_twin_id')::uuid
           END AS ridic,
           public.kiosk_tahac(p_input->>'vehicle_registration') AS tahac
  )
  SELECT EXISTS (
           SELECT 1
             FROM krok k
             JOIN public.twin_entities t ON t.id = k.ridic
             JOIN public.twin_external_refs r ON r.twin_id = t.id
            WHERE t.entity_type = 'driver'
              AND t.status = 'active'
              AND r.source = 'webdispecink'
              AND r.ref_kind = 'primary_id'
              AND r.source_key LIKE 'ridic:%'
              AND r.state = 'confirmed'
              AND r.valid_from <= now()
              AND (r.valid_to IS NULL OR r.valid_to > now()))
      OR EXISTS (
           SELECT 1
             FROM krok k
             JOIN public.wd_vehicles v ON public.kiosk_tahac(v.identifier) = k.tahac
             JOIN public.twin_external_refs r ON r.source = 'webdispecink'
                                            AND r.ref_kind = 'primary_id'
                                            AND r.source_key = v.wd_car_id::text
             JOIN public.twin_entities t ON t.id = r.twin_id
            WHERE k.tahac IS NOT NULL
              AND v.active
              AND t.entity_type = 'vehicle'
              AND t.status = 'active'
              AND r.state = 'confirmed'
              AND r.valid_from <= now()
              AND (r.valid_to IS NULL OR r.valid_to > now()))
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.kiosk_krok_nasi_flotily(jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.kiosk_krok_nasi_flotily(jsonb) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.kiosk_krok_nasi_flotily(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/kiosk_vydej_relaci.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: kiosk_vydej_relaci
-- Popis: Vydání RELACE TABLETU (F2-B) — průkaz → účet zařízení. Volá JEN gateway
--        (`POST /auth/v1/device/session`), a to AŽ PO ověření podpisu AISHA-REQ1
--        klíčem z průkazu: zápis (audit, last_seen) tedy nespustí nikdo, kdo klíč
--        nedrží. Veřejný klíč si gateway bere předem z `kiosk_device_stav`.
--
-- ⭐ ROZHODNUTÍ MAJITELE (2026-09-29): „po validaci otisku resp. zařazení, jeho podpis
--    resp. klepání odemyká … a následně je možnost se dostat do aplikace bez přihlášení
--    pouze k našim dodákům“. Klíč zůstává z ohlášení (Keystore = navazující úkol).
--
-- ⛔ PLATNOST SE KONTROLUJE TADY I PŘI KAŽDÉM VOLÁNÍ S RELACÍ. Vydaná relace je krátká
--    (gateway: nejvýš 15 min, nikdy za `plati_do`), ale ani ta nic neotevře po odvolání:
--    pátá cesta workflow_step_visible_to ověřuje průkaz (je_ucet_zarizeni_platny) při
--    KAŽDÉM volání. Relace je jen „kdo mluví“, ne „co smí“.
--
-- Vrací: {ok:true, ucet_id, kid, plati_do} | {ok:false, duvod: nezname|ceka|odvolano|neplatne}
-- Bezpečnost: SECURITY DEFINER, JEN service_role (žádný grant klientům).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.kiosk_vydej_relaci(p_kid text)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_d public.knock_device_credentials%ROWTYPE;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT * INTO v_d FROM public.knock_device_credentials WHERE kid = p_kid AND druh = 'tablet';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'duvod', 'nezname');
  END IF;
  IF v_d.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'duvod', 'odvolano');
  END IF;
  IF v_d.approved_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'duvod', 'ceka');
  END IF;
  -- Účet i platnost stejnou funkcí, jakou ověřuje pátá cesta — jedno pravidlo, ne dvě.
  IF v_d.ucet_id IS NULL OR NOT public.je_ucet_zarizeni_platny(v_d.ucet_id) THEN
    RETURN jsonb_build_object('ok', false, 'duvod', 'neplatne');
  END IF;

  UPDATE public.knock_device_credentials SET last_seen_at = now() WHERE kid = p_kid;
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_d.ucet_id, 'knock_device_session_issued', jsonb_build_object('kid', p_kid));

  RETURN jsonb_build_object('ok', true, 'ucet_id', v_d.ucet_id, 'kid', p_kid, 'plati_do', v_d.plati_do);
END;
$function$;

REVOKE ALL ON FUNCTION public.kiosk_vydej_relaci(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.kiosk_vydej_relaci(text) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.kiosk_vydej_relaci(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/knock_roster_zarizeni.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: knock_roster_zarizeni
-- Popis: Klíče SCHVÁLENÝCH a NEODVOLANÝCH zařízení pro dveře (svc-knock), aby
--        schválení v administraci platilo bez ručního exportu rosteru.
-- Bezpečnost: SECURITY DEFINER, JEN služba (brána ho vydává dveřím úzkým tokenem).
--
-- ⭐ ROZHODNUTÍ MAJITELE (2026-09-28): „to zařízení samozřejmě musí umět samo
--    klepat, když je schválené." Mění rozhodnutí z 9. 9. (roster exportuje člověk,
--    scripts/knock-devices-to-roster.mjs) — jeho obavy zůstávají splněné:
--   · VYDÁVAJÍ SE JEN VEŘEJNÉ KLÍČE (VER 2). Žádné sdílené tajemství: záznam bez
--     veřejného klíče tudy neprojde (tabulka ho ani mít nemůže — CHECK tvaru).
--   · ZÁKLAD (kódy techniků, break-glass) zůstává JEN v prostředí dveří a zařízení
--     ho nepřepíše — kolizi `kid` řeší dveře odmítnutím (svc-knock roster).
--   · Dveře nedostanou přístup do databáze; přečtou jen tenhle výstup přes bránu.
--
-- Kontrakt: () -> jsonb {operators: {kid: {publicKeyHex, scopes, kind}}, version, count}
--   version = otisk obsahu (dveře stahují celý roster jen při změně).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.knock_roster_zarizeni()
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_operators jsonb;
BEGIN
  IF NOT (SELECT public.is_service_role()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT COALESCE(
           jsonb_object_agg(
             d.kid,
             jsonb_build_object('publicKeyHex', d.public_key_hex, 'scopes', jsonb_build_array(d.scope), 'kind', 'device')
             ORDER BY d.kid
           ),
           '{}'::jsonb
         )
    INTO v_operators
    FROM public.knock_device_credentials d
   WHERE d.approved_at IS NOT NULL
     AND d.revoked_at IS NULL;

  RETURN jsonb_build_object(
    'operators', v_operators,
    'version', md5(v_operators::text),
    'count', (SELECT count(*) FROM jsonb_object_keys(v_operators))
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.knock_roster_zarizeni() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.knock_roster_zarizeni() TO service_role;


