-- =============================================================================
-- leave_voice_room
-- =============================================================================
-- Mark current user as left from voice room.
-- =============================================================================

CREATE OR REPLACE FUNCTION public.leave_voice_room(
  p_voice_room_id uuid DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  UPDATE call_participants
  SET left_at = now()
  WHERE voice_room_id = p_voice_room_id
    AND user_id = v_user_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.leave_voice_room(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.leave_voice_room(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_dedupe_knowledge_items.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_dedupe_knowledge_items
-- Popis: Sjednotí znalostní vrstvu na PRAVIDLO JEDNOHO ZÁZNAMU NA JEDEN DOKLAD.
--        V rámci (story_id, item_type, title) nechá jediný — nejnovější — záznam
--        a ostatní odstraní i s jejich chunky a embeddingy.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT; service_role / admin / staff.
-- Audit: knowledge_items.dedupe_completed s rozpadem po kategorii (bez PII).
--
-- PROČ TA DUPLICITA VŮBEC VZNIKÁ. li-driver zapisuje KB přes
-- upsert_story_knowledge_item_audited s p_id = NULL, což je vždy INSERT. Balíček
-- přitom identitu NESE (source_type='local_ingest', source_slug='<instance>-doc-…',
-- source_hash=sha dokladu) — driver ji zahodí, protože ji RPC neumí přijmout, a
-- záznam spadne na source_type='manual' s prázdným source_slug. Tím se vyřadí
-- OBĚ strukturální pojistky, které platforma proti duplicitě má
-- (idx_knowledge_items_source_slug_locale_unique i idx_knowledge_items_source_
-- unique) — nemají na čem zabrat. Měřeno 2026-07-30: 63 376 strojově
-- ingestovaných dokladů je v KB k nerozeznání od ručních poznámek.
-- Tahle funkce následek uklízí; PŘÍČINU musí opravit zápisní cesta driveru.
--
-- ROZSAH SE MUSÍ POJMENOVAT. p_categories je povinné a neprázdné: „smaž
-- duplicitní tituly v celé KB" je příliš velká zbraň na to, aby šla vystřelit
-- opomenutím. Volající řekne, kterou kategorii uklízí.
--
-- CO SE NESMÍ SMAZAT ANI OMYLEM: záznam, na kterém visí lidská práce —
-- knowledge_attribution nebo agent_knowledge_bindings. Takový se z úklidu
-- VYJME a vrátí se v `blocked`. Duplicita tam zůstane vidět; to je menší škoda
-- než tiše zahozená kurátorská vazba.
--
-- MAZAT MUSÍME RUČNĚ A V POŘADÍ: knowledge_chunks ani knowledge_embeddings
-- nemají FK na knowledge_items (ověřeno na živé DB 2026-07-30 — jediný CASCADE
-- vede z knowledge_multimodal_pages). DELETE nad položkami by tedy nechal
-- osiřelé chunky, které retrieval dál vidí.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.li_dedupe_knowledge_items(
  p_categories text[],
  p_dry_run    boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service     boolean := public.is_service_role();
  v_victims        uuid[];
  v_blocked        uuid[];
  v_by_category    jsonb;
  v_del_items      integer := 0;
  v_del_chunks     integer := 0;
  v_del_embeddings integer := 0;
BEGIN
  -- Authorization (FIRST, před jakýmkoli přístupem k datům)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required'
      USING ERRCODE = '42501';
  END IF;

  IF p_categories IS NULL OR array_length(p_categories, 1) IS NULL THEN
    RAISE EXCEPTION 'p_categories must be a non-empty array of knowledge_items.category values';
  END IF;

  WITH ranked AS MATERIALIZED (
    SELECT ki.id,
           ki.category,
           row_number() OVER (
             PARTITION BY ki.story_id, ki.item_type, ki.title
             ORDER BY ki.created_at DESC, ki.id
           ) AS rn
    FROM public.knowledge_items ki
    WHERE ki.category = ANY (p_categories)
  ),
  losers AS (
    SELECT r.id, r.category,
           (EXISTS (SELECT 1 FROM public.knowledge_attribution a WHERE a.knowledge_item_id = r.id)
            OR EXISTS (SELECT 1 FROM public.agent_knowledge_bindings b WHERE b.knowledge_item_id = r.id)
           ) AS has_curation
    FROM ranked r
    WHERE r.rn > 1
  ),
  per_category AS (
    SELECT r.category,
           jsonb_build_object(
             'items',   count(*),
             'titles',  count(*) FILTER (WHERE r.rn = 1),
             'remove',  count(*) FILTER (WHERE r.rn > 1)
           ) AS detail
    FROM ranked r
    GROUP BY r.category
  )
  SELECT COALESCE((SELECT array_agg(id) FROM losers WHERE NOT has_curation), '{}'::uuid[]),
         COALESCE((SELECT array_agg(id) FROM losers WHERE has_curation), '{}'::uuid[]),
         COALESCE((SELECT jsonb_object_agg(category, detail) FROM per_category), '{}'::jsonb)
    INTO v_victims, v_blocked, v_by_category;

  IF NOT p_dry_run AND array_length(v_victims, 1) IS NOT NULL THEN
    -- Embeddingy visí na chunku i na položce; obě cesty musí zmizet, jinak
    -- zůstane vektor ukazující na neexistující text.
    WITH gone AS (
      DELETE FROM public.knowledge_embeddings e
      WHERE e.knowledge_item_id = ANY (v_victims)
         OR e.chunk_id IN (SELECT c.id FROM public.knowledge_chunks c
                            WHERE c.knowledge_item_id = ANY (v_victims))
      RETURNING 1
    )
    SELECT count(*) INTO v_del_embeddings FROM gone;

    WITH gone AS (
      DELETE FROM public.knowledge_chunks c
      WHERE c.knowledge_item_id = ANY (v_victims)
      RETURNING 1
    )
    SELECT count(*) INTO v_del_chunks FROM gone;

    WITH gone AS (
      DELETE FROM public.knowledge_items ki
      WHERE ki.id = ANY (v_victims)
      RETURNING 1
    )
    SELECT count(*) INTO v_del_items FROM gone;

    INSERT INTO public.audit_journal (user_id, action, metadata)
    VALUES (
      auth.uid(),
      'knowledge_items.dedupe_completed',
      jsonb_build_object(
        'categories', to_jsonb(p_categories),
        'by_category', v_by_category,
        'blocked', COALESCE(array_length(v_blocked, 1), 0),
        'removed', jsonb_build_object(
          'items', v_del_items,
          'chunks', v_del_chunks,
          'embeddings', v_del_embeddings
        )
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'dry_run', p_dry_run,
    'duplicate_items', COALESCE(array_length(v_victims, 1), 0),
    'blocked_by_curation', COALESCE(array_length(v_blocked, 1), 0),
    'by_category', v_by_category,
    'removed', jsonb_build_object(
      'items', v_del_items,
      'chunks', v_del_chunks,
      'embeddings', v_del_embeddings
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION public.li_dedupe_knowledge_items(text[], boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.li_dedupe_knowledge_items(text[], boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.li_dedupe_knowledge_items(text[], boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_dedupe_source_registry.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_dedupe_source_registry
-- Popis: Sjednotí evidenční registr na PRAVIDLO JEDNOHO ŘÁDKU NA JEDEN SKUTEČNÝ
--        DOKLAD. V rámci (doc_type, hodnota identifikujícího pole) nechá jedinou
--        — nejnovější — generaci a ostatní odstraní i s navázanými li_obligations
--        a li_links.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT; service_role / admin / staff.
-- Audit: li_source_registry.dedupe_completed s rozpadem po doc_type (bez PII).
--
-- PROČ TO NEUMÍ INGEST SÁM. Engine supersedes UMÍ (stage_link relation=supersedes
-- → registry.superseded_by, verify to re-derivuje), ale vidí jen JEDEN korpus
-- jednoho běhu. Dvě generace téhož dokladu vzniknou ve dvou během — a ty vedle
-- sebe vidí jedině databáze. Proto tahle funkce žije tady a ne v enginu.
--
-- PROČ SE IDENTITA PŘEDÁVÁ PARAMETREM. Kterým polem je doklad identifikován je
-- DATA instance (ingest/field_schemas/*.schema.json), ne vlastnost platformy:
-- dodací list má dn_number, faktura invoice_number, jiná instance bude mít jiná
-- jména. Natvrdo v SQL by to byl instanční název ve stack kódu. Volající pošle
-- mapu {doc_type: field_name} odvozenou z instance dat.
--
-- IDENTITA NEMUSÍ BÝT VYTĚŽENÉ POLE. Hodnota '@filename' říká „identitou je
-- jméno zdrojového souboru" — sloupec registru, ne extrakce. Někdy je to jediná
-- možnost: běh s vadnou konfigurací uloží doklad s fields = {} a vytěžený klíč
-- prostě NEMÁ, takže s opravenou generací nejde spárovat ničím jiným (změřeno
-- 2026-07-30: 22 000 z 22 916 faktur takhle dopadlo, ale filename mají všechny
-- a je unikátní). Často je to i identita LEPŠÍ: rozbalovač skládá jméno z čísla
-- dokladu a z ID zdrojového systému, které se novým stažením nemění — na rozdíl
-- od pole, které může vytěžit špatně. Whitelist je uzavřený (žádné dynamické
-- SQL): neznámý '@sloupec' je chyba, ne tiché nic.
--
-- CO SE DĚJE S TYPEM, PRO KTERÝ IDENTITA DEKLAROVANÁ NENÍ: NIC — ale funkce to
-- ŘEKNE. Vrací undeclared_doc_types s počty řádků, takže mlčení o nepokrytém
-- typu se nedá splést s „tam nic nebylo". Totéž pro řádky, kde deklarované pole
-- v dokladu chybí (no_identity_value): nejsou ani ponechané „protože jsou v
-- pořádku", ani smazané — jsou vidět jako mezera měřidla.
--
-- KTERÁ GENERACE VYHRAJE: nejpozději ingestovaná. Při shodě (celá dávka jednoho
-- exportu nese totéž now()) rozhoduje bohatší doklad — víc vyplněných polí, pak
-- víc položek — a nakonec id, aby byl výsledek deterministický. Pořadí je stejné
-- jako u ON CONFLICT v li_upsert_source_registry: poslední zápis vyhrává.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.li_dedupe_source_registry(
  p_identity_fields jsonb,
  p_dry_run         boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  -- Kanonický boolean-NOT-NULL service check — deny-guard fail-CLOSED i bez claimu.
  v_is_service    boolean := public.is_service_role();
  v_victims       uuid[];
  v_shas          text[];
  v_by_doc_type   jsonb;
  v_no_identity   jsonb;
  v_undeclared    jsonb;
  v_del_registry  integer := 0;
  v_del_oblig     integer := 0;
  v_del_links     integer := 0;
BEGIN
  -- Authorization (FIRST, před jakýmkoli přístupem k datům)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required'
      USING ERRCODE = '42501';
  END IF;

  IF p_identity_fields IS NULL OR jsonb_typeof(p_identity_fields) <> 'object' THEN
    RAISE EXCEPTION 'p_identity_fields must be a jsonb object {doc_type: field_name}';
  END IF;

  -- Uzavřený whitelist sloupcových identit. Překlep v '@filename' by jinak
  -- spadl na „pole toho jména neexistuje" → identita NULL → celý typ by se
  -- tvářil jako nepokrytý a mlčky se neuklidil.
  IF EXISTS (
    SELECT 1 FROM jsonb_each_text(p_identity_fields) AS e(k, v)
    WHERE v LIKE '@%' AND v <> '@filename'
  ) THEN
    RAISE EXCEPTION 'unknown column identity in p_identity_fields (only ''@filename'' is supported)';
  END IF;

  -- Jedno pořadí, jedna cesta daty: MATERIALIZED drží žebříček v jednom průchodu,
  -- takže seznam obětí i rozpad po typu vycházejí prokazatelně z TÉHOŽ řazení
  -- (a ne ze dvou nezávisle spočítaných pohledů, které se mohou rozejít).
  WITH keyed AS (
    -- Identita se čte na JEDNOM místě; níž už se s ní jen pracuje.
    SELECT r.id,
           r.source_sha256,
           r.doc_type,
           CASE WHEN (p_identity_fields ->> r.doc_type) = '@filename'
                THEN r.filename
                ELSE r.fields -> (p_identity_fields ->> r.doc_type) ->> 'value'
           END AS identity_value,
           r.ingested_at,
           (SELECT count(*) FROM jsonb_object_keys(r.fields)) AS field_count,
           jsonb_array_length(r.line_items) AS line_count
    FROM public.li_source_registry r
    WHERE p_identity_fields ? r.doc_type
  ),
  ranked AS MATERIALIZED (
    SELECT k.id, k.source_sha256, k.doc_type, k.identity_value,
           row_number() OVER (
             PARTITION BY k.doc_type, k.identity_value
             ORDER BY k.ingested_at DESC, k.field_count DESC, k.line_count DESC, k.id
           ) AS rn
    FROM keyed k
    WHERE k.identity_value IS NOT NULL
  ),
  per_type AS (
    SELECT doc_type,
           jsonb_build_object(
             'rows',       count(*),
             'identities', count(DISTINCT identity_value),
             'remove',     count(*) FILTER (WHERE rn > 1)
           ) AS detail
    FROM ranked
    GROUP BY doc_type
  )
  SELECT COALESCE((SELECT array_agg(id) FROM ranked WHERE rn > 1), '{}'::uuid[]),
         COALESCE((SELECT array_agg(source_sha256) FROM ranked WHERE rn > 1), '{}'::text[]),
         COALESCE((SELECT jsonb_object_agg(doc_type, detail) FROM per_type), '{}'::jsonb)
    INTO v_victims, v_shas, v_by_doc_type;

  -- Mezera č. 1: typ má identitu deklarovanou, ale doklad ji nenese.
  SELECT COALESCE(jsonb_object_agg(doc_type, n), '{}'::jsonb) INTO v_no_identity
  FROM (
    SELECT r.doc_type, count(*) AS n
    FROM public.li_source_registry r
    WHERE p_identity_fields ? r.doc_type
      AND (CASE WHEN (p_identity_fields ->> r.doc_type) = '@filename'
                THEN r.filename
                ELSE r.fields -> (p_identity_fields ->> r.doc_type) ->> 'value'
           END) IS NULL
    GROUP BY r.doc_type
  ) missing;

  -- Mezera č. 2: typ v registru je, identitu pro něj nikdo nedeklaroval.
  SELECT COALESCE(jsonb_object_agg(doc_type, n), '{}'::jsonb) INTO v_undeclared
  FROM (
    SELECT r.doc_type, count(*) AS n
    FROM public.li_source_registry r
    WHERE NOT (p_identity_fields ? r.doc_type)
    GROUP BY r.doc_type
  ) undeclared;

  IF NOT p_dry_run AND array_length(v_victims, 1) IS NOT NULL THEN
    -- Odvozené vrstvy první: obojí ukazuje na doklad přes source_sha256, takže
    -- po smazání registru by z nich byly nedohledatelné sirotky.
    WITH gone AS (
      DELETE FROM public.li_obligations o
      WHERE o.source_sha256 = ANY (v_shas)
      RETURNING 1
    )
    SELECT count(*) INTO v_del_oblig FROM gone;

    -- Vazba ztrácí smysl, jakmile zmizí kterýkoli z jejích konců.
    WITH gone AS (
      DELETE FROM public.li_links l
      WHERE l.from_sha256 = ANY (v_shas) OR l.to_sha256 = ANY (v_shas)
      RETURNING 1
    )
    SELECT count(*) INTO v_del_links FROM gone;

    WITH gone AS (
      DELETE FROM public.li_source_registry r
      WHERE r.id = ANY (v_victims)
      RETURNING 1
    )
    SELECT count(*) INTO v_del_registry FROM gone;

    INSERT INTO public.audit_journal (user_id, action, metadata)
    VALUES (
      auth.uid(),
      'li_source_registry.dedupe_completed',
      jsonb_build_object(
        'identity_fields', p_identity_fields,
        'by_doc_type', v_by_doc_type,
        'no_identity_value', v_no_identity,
        'undeclared_doc_types', v_undeclared,
        'removed', jsonb_build_object(
          'registry', v_del_registry,
          'obligations', v_del_oblig,
          'links', v_del_links
        )
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'dry_run', p_dry_run,
    'duplicate_rows', COALESCE(array_length(v_victims, 1), 0),
    'by_doc_type', v_by_doc_type,
    'no_identity_value', v_no_identity,
    'undeclared_doc_types', v_undeclared,
    'removed', jsonb_build_object(
      'registry', v_del_registry,
      'obligations', v_del_oblig,
      'links', v_del_links
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION public.li_dedupe_source_registry(jsonb, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.li_dedupe_source_registry(jsonb, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.li_dedupe_source_registry(jsonb, boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_doc_scope_keys_z_dokladu.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_doc_scope_keys_z_dokladu
-- Popis: Klíče JEDNOHO dokladu pro nárok — JEDINÉ místo té logiky (volá ji trigger
--        na registru i přestavba, aby se klíče z jednotlivého zápisu a z přestavby
--        nemohly rozejít):
--          • pole, která zná aktivní pravidlo twin_scope_doc_rules pro typ dokladu
--            (nárok z vazeb), a protistrana (counterparty_id, counterparty) u každého
--            dokladu (dvojčata v rozsahu);
--          • PŮVOD (každý doklad, bez ohledu na pravidla) — zdroj dat pro udělení přístupu:
--              `@instance` = instance zdroje, ze které doklad přišel, jak ji zapsal KONEKTOR
--                            do zdrojového záznamu (`source_record._instance`, druh zdroje
--                            z `_marker` před tečkou): „money/Areál Avant Ďáblická";
--              `@cesta`    = každý nadřazený adresář relativní cesty ve vstupu ingestu
--                            (raw_data.source_path; „A/B/c.pdf" → „A", „A/B");
--              `@vstup`    = „dokumenty": doklad ze ZPRACOVANÉHO VSTUPU ingestu (soubor, ne záznam
--                            konektoru — `source_record` je JSON null, nebo nese source_path).
--                            ⭐ Majitel 2026-09-28: „všechna data, ale rozdělená po zdrojích —
--                            Money už máme, teď nám jde o dokumenty, smlouvy…". Naměřeno: 1 023
--                            dokladů (813 smluv, 114 dodatků, 94 faktur v PDF, 2 vyúčtování).
--              `@firma`    = IČO smluvní strany (supplier_id, counterparty_id) u SMLUVNÍCH
--                            dokumentů (třída `contractual`) — „vazba na firmy, které vidíme
--                            v přehledu". Doklady z konektoru (Money) se zpřístupňují instancí,
--                            ne firmou: jinak by udělení firmy otevřelo cizí faktury, kde je
--                            firma odběratelem, a blok dlužníků by z ní udělal dlužníka.
--            Předpona `@` se nesrazí se jménem pole dokladu v pravidlech.
--        ⭐ Majitel 2026-09-28: „ingest navrhuje vazby, protistrany… ale neměl by řešit, kdo
--        k čemu má přístup; MODĚVA, Avant… to jsou zdroje dat z Money, které chceme
--        zpřístupnit". Proto původ ze ZÁZNAMU KONEKTORU, ne z pole vytaženého ingestem
--        (owner_company) — přístup nezávisí na tom, co ingest z dokladu přečetl.
--
-- Hodnota: `{value, status, …}` → value; starší korpus má skalár. Bere se jen
--   řetězec nebo číslo. Normalizace lower(btrim(...)); `zobrazeni` = původní zápis
--   (jen u klíčů původu — pro výběr zdroje v administraci).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.li_doc_scope_keys_z_dokladu(p_doc_type text, p_doc_class text, p_fields jsonb, p_raw jsonb)
RETURNS TABLE (field_key text, hodnota text, zobrazeni text)
LANGUAGE sql
STABLE
SET search_path TO 'public', 'pg_temp'
AS $$
  WITH klice AS (
    SELECT p.field_key
      FROM public.twin_scope_doc_rules p
     WHERE p.is_active AND p.doc_type = p_doc_type
    UNION
    -- Protistrana u KAŽDÉHO dokladu: čtení dvojčat v rozsahu (karta dlužníka, síť
    -- vazeb) ji potřebuje i u dokladů z udělených zdrojů, ne jen z pravidel.
    SELECT k FROM unnest(ARRAY['counterparty_id', 'counterparty']) AS k
  ),
  hodnoty AS (
    SELECT k.field_key,
           coalesce(p_fields->k.field_key->'value', p_fields->k.field_key) AS v
      FROM klice k
  ),
  instance AS (
    SELECT nullif(btrim(p_raw->'source_record'->>'_instance'), '') AS jmeno,
           coalesce(nullif(split_part(p_raw->'source_record'->>'_marker', '.', 1), ''), 'zdroj') AS druh
     WHERE jsonb_typeof(p_raw->'source_record') = 'object'
  ),
  cesta AS (
    SELECT string_to_array(btrim(p_raw->>'source_path', '/'), '/') AS casti
     WHERE nullif(btrim(coalesce(p_raw->>'source_path', ''), '/'), '') IS NOT NULL
  ),
  strana AS (
    SELECT btrim(coalesce(p_fields->k->'value', p_fields->k) #>> '{}') AS ico
      FROM unnest(ARRAY['supplier_id', 'counterparty_id']) AS k
     WHERE p_doc_class = 'contractual'
       AND jsonb_typeof(coalesce(p_fields->k->'value', p_fields->k)) IN ('string', 'number')
  )
  SELECT DISTINCT h.field_key, lower(btrim(h.v #>> '{}')), NULL::text
    FROM hodnoty h
   WHERE jsonb_typeof(h.v) IN ('string', 'number')
     AND btrim(h.v #>> '{}') <> ''
  UNION
  SELECT '@instance', lower(i.druh || '/' || i.jmeno), i.druh || '/' || i.jmeno
    FROM instance i
   WHERE i.jmeno IS NOT NULL
  UNION
  SELECT '@cesta', lower(array_to_string(c.casti[1:n], '/')), array_to_string(c.casti[1:n], '/')
    FROM cesta c, generate_series(1, cardinality(c.casti) - 1) AS n
  UNION
  SELECT '@firma', s.ico, s.ico
    FROM strana s
   WHERE s.ico ~ '^[0-9]{8}$'
  UNION
  SELECT '@vstup', 'dokumenty', 'dokumenty'
   WHERE (p_raw ? 'source_record' AND jsonb_typeof(p_raw->'source_record') = 'null')
      OR nullif(btrim(coalesce(p_raw->>'source_path', '')), '') IS NOT NULL;
$$;

REVOKE ALL ON FUNCTION public.li_doc_scope_keys_z_dokladu(text, text, jsonb, jsonb) FROM PUBLIC;

COMMENT ON FUNCTION public.li_doc_scope_keys_z_dokladu(text, text, jsonb, jsonb) IS
  'Klíče jednoho dokladu: pole z aktivních twin_scope_doc_rules + protistrana, a PŮVOD pro udělení zdroje dat (@instance = instance zdroje ze záznamu konektoru, @cesta = nadřazené adresáře relativní cesty ve vstupu, @firma = IČO smluvní strany smluvního dokumentu, @vstup = dokumenty zpracovaného vstupu). Jediná logika pro trigger i přestavbu.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_li_source_registry_scope_keys.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_li_source_registry_scope_keys (trigger)
-- Popis: Drží li_doc_scope_keys v souladu s JEDNÍM řádkem registru: klíče
--        dokladu se zahodí a znovu vytáhnou (li_doc_scope_keys_z_dokladu), když
--        se změní typ, pole, slug nebo platnost verze. Nahrazená verze klíče
--        nemá — nárok míří na platnou verzi.
-- Pár: triggers/li_source_registry_scope_keys.sql
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_li_source_registry_scope_keys()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
BEGIN
  DELETE FROM public.li_doc_scope_keys WHERE source_sha256 = NEW.source_sha256;
  IF NEW.superseded_by IS NULL AND NEW.doc_slug IS NOT NULL THEN
    INSERT INTO public.li_doc_scope_keys (source_sha256, doc_slug, doc_type, field_key, hodnota, zobrazeni)
    SELECT NEW.source_sha256, NEW.doc_slug, NEW.doc_type, k.field_key, k.hodnota, k.zobrazeni
      FROM public.li_doc_scope_keys_z_dokladu(NEW.doc_type, NEW.doc_class, NEW.fields, NEW.raw_data) AS k
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_li_source_registry_scope_keys() FROM PUBLIC;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_doc_scope_keys_prestav.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_doc_scope_keys_prestav
-- Popis: Přestaví li_doc_scope_keys z celého registru (platné verze dokladů
--        typů, které zná aktivní pravidlo). Volá ji trigger při změně pravidel
--        (nové pole = klíče i pro doklady, které přišly dřív) a heals při každé
--        migraci — konvergence, kdyby trigger někdy chyběl.
--        Vrací počet zapsaných klíčů.
--
-- Bezpečnost: SECURITY DEFINER bez guardu na volajícího, ale EXECUTE má jen
--   service_role (a vlastník / migrace). Nic nevrací z dat, jen počet.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.li_doc_scope_keys_prestav()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_n integer;
BEGIN
  DELETE FROM public.li_doc_scope_keys;
  -- Všechny platné doklady: původ (@instance, @cesta) mají všechny, pole z pravidel jen
  -- typy, které pravidla znají (to rozhodne li_doc_scope_keys_z_dokladu).
  INSERT INTO public.li_doc_scope_keys (source_sha256, doc_slug, doc_type, field_key, hodnota, zobrazeni)
  SELECT d.source_sha256, d.doc_slug, d.doc_type, k.field_key, k.hodnota, k.zobrazeni
    FROM public.li_source_registry d
    CROSS JOIN LATERAL public.li_doc_scope_keys_z_dokladu(d.doc_type, d.doc_class, d.fields, d.raw_data) AS k
   WHERE d.superseded_by IS NULL
     AND d.doc_slug IS NOT NULL
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;

REVOKE ALL ON FUNCTION public.li_doc_scope_keys_prestav() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.li_doc_scope_keys_prestav() TO service_role;

COMMENT ON FUNCTION public.li_doc_scope_keys_prestav() IS
  'Přestavba li_doc_scope_keys z registru (platné verze, typy s aktivním pravidlem). Trigger při změně pravidel a heals; vrací počet klíčů.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_twin_scope_doc_rules_prestav.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_twin_scope_doc_rules_prestav (trigger, FOR EACH STATEMENT)
-- Popis: Změna pravidel nároku (nové pole, vypnutí, smazání) přestaví
--        li_doc_scope_keys — nové pole musí mít klíče i u dokladů, které přišly
--        dřív. Pravidla se mění zřídka (data instance), přestavba je levná.
-- Pár: triggers/twin_scope_doc_rules_prestav.sql
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_twin_scope_doc_rules_prestav()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
BEGIN
  PERFORM public.li_doc_scope_keys_prestav();
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_twin_scope_doc_rules_prestav() FROM PUBLIC;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_doc_slugs_v_rozsahu.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_doc_slugs_v_rozsahu
-- Popis: Doklady, na které má volající nárok Z VAZEB — „jsem spojen s identitou,
--        které ten doklad patří" — nebo ze ZDROJE DAT, ke kterému mu správa udělila
--        přístup (data_source_grants: instance zdroje od konektoru / podstrom vstupu
--        ingestu). Sourozenec li_doc_slugs_claimed_by (nárok
--        z kroků procesu); oba jsou množinové členy politiky li_source_registry_read.
--
-- Řetěz (vše musí platit TEĎ):
--   účet ──(twin_external_refs ref_kind='account', confirmed)──▶ osoba
--   osoba ──(twin_relations, druh z twin_scope_doc_rules)──▶ identita
--   identita ──(twin_external_refs confirmed, druh z pravidla)──▶ hodnota
--   doklad (doc_type pravidla) · fields.<field_key> == hodnota  ──▶ doc_slug
--
-- ⭐ PROČ (rozhodnutí majitele 2026-09-28): běžný uživatel má vidět smlouvy,
--   faktury a dlužníky jen z přiřazených identit. Bloky dlužníků, nájmů a smluv
--   jsou SECURITY INVOKER, takže nárok zdědí z politiky bez jediné změny čtečky.
--
-- ⛔ Porovnání hodnoty: lower(btrim(...)) na obou stranách. Hodnoty polí dokladů
--   jsou předpočítané v li_doc_scope_keys (li_doc_scope_keys_z_dokladu).
-- ⛔ Jen PLATNÉ verze dokladů mají klíče — nárok míří na platnou verzi.
-- ⛔ Správa vidí vše prvním členem politiky — tady se pro ni vrací prázdno, aby
--   se řetěz nepočítal zbytečně.
--
-- Bezpečnost: SECURITY DEFINER + oracle guard (volající smí vyhodnocovat JEN
--   SVŮJ nárok; service_role / správa za kohokoliv).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.li_doc_slugs_v_rozsahu(p_uid uuid)
RETURNS SETOF text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
BEGIN
  IF p_uid IS NULL
     OR NOT (p_uid = auth.uid() OR public.is_service_role() OR public.is_admin_or_staff()) THEN
    RETURN;
  END IF;
  IF public.is_admin_or_staff(p_uid) THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH osoba AS (
    SELECT a.twin_id
      FROM public.twin_external_refs a
     WHERE a.ref_kind = 'account' AND a.state = 'confirmed'
       AND a.source_key = p_uid::text
       AND a.valid_from <= now() AND (a.valid_to IS NULL OR a.valid_to > now())
  ),
  identita AS (
    SELECT DISTINCT v.target_twin_id AS twin_id, v.relation_kind
      FROM osoba o
      JOIN public.twin_relations v ON v.source_twin_id = o.twin_id
     WHERE v.valid_from <= now() AND (v.valid_to IS NULL OR v.valid_to > now())
  ),
  klic AS (
    SELECT DISTINCT p.doc_type, p.field_key, lower(btrim(r.source_key)) AS hodnota
      FROM identita i
      JOIN public.twin_scope_doc_rules p ON p.is_active AND p.relation_kind = i.relation_kind
      JOIN public.twin_external_refs r
        ON r.twin_id = i.twin_id AND r.state = 'confirmed' AND r.ref_kind = ANY (p.ref_kinds)
       AND r.valid_from <= now() AND (r.valid_to IS NULL OR r.valid_to > now())
  )
  -- Předpočítané klíče (li_doc_scope_keys), ne rozbalování fields: nad fields
  -- stálo párování nemovitostní agendy 201–1 353 ms (produkce 2026-09-28).
  SELECT DISTINCT s.doc_slug
    FROM klic k
    JOIN public.li_doc_scope_keys s
      ON s.field_key = k.field_key AND s.hodnota = k.hodnota AND s.doc_type = k.doc_type
  UNION
  -- ⭐ UDĚLENÝ ZDROJ DAT (2026-09-28): „MODĚVA, Avant… to jsou zdroje dat z Money, které
  -- chceme zpřístupnit" — přístup uděluje správa, ingest o něm nerozhoduje. Klíč původu
  -- `@instance` / `@cesta` (cesta obsahuje každý nadřazený adresář — udělený podstrom
  -- pustí i podsložky).
  SELECT s.doc_slug
    FROM public.data_source_grants g
    JOIN public.li_doc_scope_keys s
      ON s.field_key = '@' || split_part(g.zdroj, ':', 1)
     AND s.hodnota = lower(btrim(substr(g.zdroj, strpos(g.zdroj, ':') + 1)))
   WHERE g.user_id = p_uid;
END;
$$;

REVOKE ALL ON FUNCTION public.li_doc_slugs_v_rozsahu(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.li_doc_slugs_v_rozsahu(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.li_doc_slugs_v_rozsahu(uuid) TO service_role;

COMMENT ON FUNCTION public.li_doc_slugs_v_rozsahu(uuid) IS
  'Doklady s nárokem z vazeb (účet → osoba → platná vazba druhu z twin_scope_doc_rules → identita → potvrzený identifikátor == pole dokladu) nebo z udělených zdrojů dat (data_source_grants → klíče původu). Množinový člen li_source_registry_read.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_finding_field.sql
-- -----------------------------------------------------------------------------

-- Function: public.li_finding_field
-- Jedno pole dotazu na pravdu ve tvaru RecordField {key, label_key, value}.
--
-- Hodnota smí být podle kontraktu jen text, číslo nebo null. Důkaz z ingestu je
-- jsonb libovolného tvaru, takže číslo zůstane číslem (klient ho naformátuje)
-- a všechno ostatní jde jako text — objekt nebo pole by shodilo celou frontu.
-- Chybí-li klíč nebo popisek, vrací NULL a volající pole vynechá.

create or replace function public.li_finding_field(p_key text, p_label_key text, p_value jsonb)
returns jsonb
language sql
immutable
parallel safe
set search_path = public, pg_temp
as $$
  select case
    when nullif(p_key, '') is null or nullif(p_label_key, '') is null then null
    else jsonb_build_object(
      'key',       p_key,
      'label_key', p_label_key,
      'value',     case
                     when p_value is null or jsonb_typeof(p_value) = 'null' then 'null'::jsonb
                     when jsonb_typeof(p_value) in ('number', 'string') then p_value
                     else to_jsonb(p_value::text)
                   end)
  end;
$$;

revoke all on function public.li_finding_field(text, text, jsonb) from public, anon;
grant execute on function public.li_finding_field(text, text, jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_finding_evidence_fields.sql
-- -----------------------------------------------------------------------------

-- Function: public.li_finding_evidence_fields
-- Z důkazu jednoho nálezu (li_findings.evidence) udělá pole k zobrazení — CO
-- přesně na příkladu nesedí. Bez toho dotaz na pravdu nejde zodpovědět: „součet
-- položek nesedí" je tvrzení, „položky 12 340, základ 12 338, rozdíl 2" je
-- teprve něco, podle čeho člověk pozná, jestli jde o chybu, nebo o zaokrouhlení.
--
-- Tvar důkazu určuje OPERÁTOR kontroly (evidence.op), a ten je v ingestu
-- UZAVŘENÝ výčet (stage_consistency.CHECKS: date_order, date_max_gap,
-- sum_equals, lines_sum_equals, equals). Neznámý operátor — typicky nálezy
-- mezidokladových pravidel, která `op` nenesou — vrátí prázdné pole: příkladem
-- pak zůstává jméno dokladu, nic se nedomýšlí.
--
-- Popisky polí dokladu jdou přes `app.wb.field.<pole>`, tedy TÝŽ klíč, kterým
-- je popisuje detail dokladu (get_document_detail). Jména polí pocházejí
-- z pravidel instance (consistency_rules.json), takže jejich překlady patří
-- k instanci spolu s pravidly.

create or replace function public.li_finding_evidence_fields(p_evidence jsonb)
returns jsonb
language plpgsql
immutable
set search_path = public, pg_temp
as $$
declare
  e      jsonb := coalesce(p_evidence, '{}'::jsonb);
  v_out  jsonb := '[]'::jsonb;
  v_pole text;
begin
  case e->>'op'
    when 'lines_sum_equals', 'sum_equals' then
      v_out := jsonb_build_array(
        public.li_finding_field(
          case when e->>'op' = 'lines_sum_equals' then 'lines_sum' else 'parts_sum' end,
          case when e->>'op' = 'lines_sum_equals' then 'app.wb.finding_question.lines_sum'
               else 'app.wb.finding_question.parts_sum' end,
          coalesce(e->'lines_sum', e->'parts_sum')),
        public.li_finding_field(e->>'total_field', 'app.wb.field.' || (e->>'total_field'), e->'total_value'),
        public.li_finding_field('diff', 'app.wb.finding_question.diff', e->'diff'));
    when 'date_order' then
      -- Jen ta dvojice, která pořadí porušila — ne všechna data dokladu.
      for v_pole in select jsonb_array_elements_text(coalesce(e->'violated', '[]'::jsonb)) loop
        v_out := v_out || jsonb_build_array(
          public.li_finding_field(v_pole, 'app.wb.field.' || v_pole, e->'values'->v_pole));
      end loop;
    when 'date_max_gap', 'equals' then
      for v_pole in select jsonb_array_elements_text(coalesce(e->'fields', '[]'::jsonb)) loop
        v_out := v_out || jsonb_build_array(
          public.li_finding_field(v_pole, 'app.wb.field.' || v_pole, e->'values'->v_pole));
      end loop;
      if e->>'op' = 'date_max_gap' then
        v_out := v_out || jsonb_build_array(
          public.li_finding_field('days_apart', 'app.wb.finding_question.days_apart', e->'days_apart'));
      end if;
    else
      null;
  end case;
  -- Pole bez klíče (důkaz bez total_field apod.) by neprošlo kontraktem a shodilo
  -- by celou frontu; raději ho vynechat.
  return coalesce((
    select jsonb_agg(p) from jsonb_array_elements(v_out) p where p ? 'key'
  ), '[]'::jsonb);
end;
$$;

revoke all on function public.li_finding_evidence_fields(jsonb) from public, anon;
grant execute on function public.li_finding_evidence_fields(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_finding_is_current.sql
-- -----------------------------------------------------------------------------

-- Function: public.li_finding_is_current
-- Týká se nález AKTUÁLNÍ verze dokladů? (documents = li_findings.documents)
--
-- Registr při změně obsahu doklad překlíčuje na nový sha
-- (li_upsert_source_registry), ale nález staré verze v li_findings zůstává —
-- odtud tentýž soubor 2× v seznamu nálezů (produkce 2026-09-28). Nález je
-- starý, jen když to jde PROKÁZAT: jeho verze je nahrazená (superseded_by),
-- nebo registr doklad téhož jména zná, ale s jiným obsahem. Chybí-li doklad
-- v registru úplně, nález platí — mlčet o něm by bylo horší než ho ukázat.
--
-- Jediné místo toho predikátu: čtení dotazů (get_finding_questions) i zápis
-- odpovědi (submit_evidence_review_audited, větev 'finding') musí počítat
-- tytéž doklady, jinak by verdikt zapsal jiný počet, než člověk viděl.

create or replace function public.li_finding_is_current(p_documents jsonb)
returns boolean
language sql
stable
set search_path = public, pg_temp
as $$
  select not exists (
    select 1
      from jsonb_array_elements(coalesce(p_documents, '[]'::jsonb)) d
     where d->>'source_sha256' is not null
       and (
         exists (select 1 from public.li_source_registry r
                  where r.source_sha256 = d->>'source_sha256'
                    and r.superseded_by is not null)
         or (
           not exists (select 1 from public.li_source_registry r
                        where r.source_sha256 = d->>'source_sha256')
           and exists (select 1 from public.li_source_registry r
                        where r.filename = d->>'filename')
         )
       )
  );
$$;

revoke all on function public.li_finding_is_current(jsonb) from public, anon;
grant execute on function public.li_finding_is_current(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_finding_question_id.sql
-- -----------------------------------------------------------------------------

-- Function: public.li_finding_question_id
-- Identita DOTAZU NA PRAVDU nad nálezy: jedno pravidlo × jeden druh nálezu.
--
-- Deterministická (md5 → uuid), aby ji čtecí blok vydal i pro dotaz, na který
-- ještě nikdo neodpověděl a který proto nemá řádek v li_finding_verdicts —
-- a zápisová větev z ní pak poznala, o jaký dotaz jde. Jediné místo výpočtu:
-- čtení (get_finding_questions) i zápis (submit_evidence_review_audited) ji
-- volají, aby se klíč nemohl rozejít.
--
-- rule_key smí být NULL (starší nálezy bez rule_id) — skládá se jako ''.

create or replace function public.li_finding_question_id(p_rule_key text, p_finding text)
returns uuid
language sql
immutable
parallel safe
set search_path = public, pg_temp
as $$
  select md5('finding-question|' || coalesce(p_rule_key, '') || '|' || coalesce(p_finding, ''))::uuid;
$$;

revoke all on function public.li_finding_question_id(text, text) from public, anon;
grant execute on function public.li_finding_question_id(text, text) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_finding_questions.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'review_queue' block: DOTAZY NA PRAVDU nad nálezy ingestu.
--
-- ⛔ NAMĚŘENO 2026-09-28 (produkce, extranet): blok „Nálezy" ukazoval 79 řádků
-- „Součet položek nesedí s celkovou částkou" / „Data dokladu jsou v nesprávném
-- pořadí", každý s jedním souborem a bez čísel. Uživatel: „nevím k čemu to je
-- a nejde s tím stejně nic dělat". Tři vady najednou:
--   1. jeden řádek na DOKLAD — tatáž otázka 43× za sebou;
--   2. bez důkazu — get_evidence_findings zahodil evidence (o kolik, která data);
--   3. bez akce — nález nešlo potvrdit ani odmítnout, seznam nikdy nezmizel.
--
-- Tady je jednotkou DOTAZ: jedno pravidlo × jeden druh nálezu (question_id =
-- li_finding_question_id). Nese počet dotčených dokladů, popis pravidla (co
-- tvrdí) a jeden PŘÍKLAD s čísly, a ptá se: platí to? Odpověď (větev 'finding'
-- v submit_evidence_review_audited) platí pro celé pravidlo — i pro doklady,
-- které ingest přinese později — a dotaz z fronty zmizí.
--
-- ⭐ SKUPINA = PRAVIDLO, ne titulek. Dvě různá pravidla smí vydat týž druh
-- nálezu (date_order_violation: faktura „DUZP ≤ vystavení ≤ splatnost" i smlouva
-- „podpis ≤ platnost od ≤ do"), a odpověď na ně se může lišit — nájmy se
-- fakturují předem, smlouvy se podepisují zpětně. Sloučit je by znamenalo
-- ukázat příklad jednoho a nechat člověka rozhodnout o obou.
--
-- ZASTARALÉ VERZE DOKLADŮ SE NEPOČÍTAJÍ (li_finding_is_current) — odtud
-- dřív tentýž soubor 2× v seznamu.
--
-- SECURITY INVOKER — o viditelnosti rozhoduje RLS (li_findings,
-- li_source_registry i li_finding_verdicts čte jen admin/staff).
-- Contract: (jsonb) -> jsonb {data:{entity_kind, items[], actions[]}, provenance}.

create or replace function public.get_finding_questions(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with platne as (
    select
      f.id,
      f.rule_key,
      f.finding,
      case coalesce(f.severity, 'low') when 'high' then 3 when 'medium' then 2 else 1 end as vaha,
      f.documents,
      f.evidence,
      nullif(btrim(f.raw_data->>'description'), '')             as popis,
      f.ingested_at,
      public.li_finding_question_id(f.rule_key, f.finding)       as question_id
    from public.li_findings f
    where public.li_finding_is_current(f.documents)
  ),
  otevrene as (
    select p.*
      from platne p
     where not exists (select 1 from public.li_finding_verdicts v
                        where v.question_id = p.question_id)
  ),
  skupiny as (
    select
      o.question_id,
      max(o.vaha)         as vaha,
      max(o.ingested_at)  as naposledy,
      (select count(distinct coalesce(d->>'filename', d->>'source_sha256'))
         from otevrene o2, jsonb_array_elements(coalesce(o2.documents, '[]'::jsonb)) d
        where o2.question_id = o.question_id)                   as dokladu
    from otevrene o
    group by o.question_id
  ),
  -- Příklad = nejnovější nález skupiny (deterministicky: čas, soubor, id).
  priklady as (
    select distinct on (o.question_id) o.*
      from otevrene o
     order by o.question_id, o.ingested_at desc, o.documents->0->>'filename', o.id
  ),
  dotazy as (
    select
      s.vaha,
      s.dokladu,
      s.naposledy,
      p.question_id,
      jsonb_strip_nulls(jsonb_build_object(
        'id',           p.question_id::text,
        'title_key',    'app.wb.finding.' || p.finding,
        'subtitle_key', 'app.wb.finding_question.subtitle',
        'state',        'needs_review',
        'quote',        p.popis,
        'fields',       jsonb_build_array(
                          public.li_finding_field('documents', 'app.wb.field.documents', to_jsonb(s.dokladu)),
                          public.li_finding_field('example', 'app.wb.finding_question.example',
                            to_jsonb(coalesce(p.documents->0->>'filename', p.documents->0->>'source_slug'))))
                        || public.li_finding_evidence_fields(p.evidence)
      )) as item
    from skupiny s
    join priklady p on p.question_id = s.question_id
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'entity_kind', 'finding',
      'items', coalesce(jsonb_agg(d.item order by d.vaha desc, d.dokladu desc, d.question_id), '[]'::jsonb),
      'actions', jsonb_build_array(
        jsonb_build_object('action_key', 'app.wb.finding_question.action.confirm',
                           'decision', 'confirmed', 'intent', 'approve'),
        jsonb_build_object('action_key', 'app.wb.finding_question.action.reject',
                           'decision', 'rejected', 'intent', 'reject'))
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'li-findings',
      'freshness_at', to_char(coalesce(max(d.naposledy), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'finding-questions'
    )
  )
  from dotazy d;
$$;

revoke all on function public.get_finding_questions(jsonb) from public, anon;
grant execute on function public.get_finding_questions(jsonb) to authenticated, service_role;


