-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_upsert_entity_suggestions.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_upsert_entity_suggestions
-- Popis: Batch upsert advisory návrhů sjednocení entit z local-ingest. Volá
--        svc-source-broker li-driver z entity_suggestions_artifact.jsonl.
--        suggestion_key (dedup) počítá RPC. advisory zůstává vždy true (tabulka
--        má CHECK) — z těchto řádků se NIKDY negeneruje FK/vazba.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT; service_role / admin / staff.
-- Audit: li_entity_suggestions.upsert_completed s počty (bez PII).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.li_upsert_entity_suggestions(
  p_rows           jsonb,
  p_export_id      text DEFAULT NULL,
  p_engine_version text DEFAULT NULL,
  p_verify_ok      boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean := public.is_service_role();
  v_keyed      jsonb;
  v_batch      jsonb;
  v_total      integer;
  v_updated    integer;
  v_inserted   integer;
BEGIN
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'p_rows must be a jsonb array';
  END IF;

  -- suggestion_key = md5(suggestion | pole | hodnota) — DETERMINISTICKY ROZLIŠUJÍCÍ.
  --
  -- ⛔ DEGENEROVANÝ KLÍČ SLEPÍ CELOU DÁVKU DO JEDNOHO ŘÁDKU (naměřeno 2026-07-31).
  -- Původní klíč znal jen tvar `same_*` (`id_field`/`name_field` + `id_value`/
  -- `name_normalized`). Novější `similar_values_may_merge` nese místo nich
  -- `field` + `values` + `question_id`, takže mu VŠECHNY tři složky vyšly prázdné
  -- a 659 různých návrhů dostalo týž klíč `md5('similar_values_may_merge||')`.
  -- `DISTINCT ON` níž z nich udělal JEDEN. Totéž `merge_scan_truncated` (2 → 1).
  -- Z 672 návrhů se uložilo 13 a nikde nevznikla chyba: dedup je legitimní
  -- operace, takže ztráta vypadá jako úspěch (`msg: "bundle ingested"`).
  -- Cena: 197 z těch 659 bylo sloučení jmen řidičů (`KOŽUŠNÍK`×`Kožušník`,
  -- `MATYAŠ`×`Matyáš`), takže produkce drží 1 476 twinů `driver` — jeden na každý
  -- pravopis místo jednoho na člověka.
  --
  -- `question_id` je stabilní identifikátor návrhu z ingestu (ověřeno: unikátní
  -- pro všech 659); `values` je záloha, kdyby ho starší artefakt neměl. Pořadí
  -- COALESCE drží zpětnou kompatibilitu — pro tvar `same_*` vyjde TÝŽ klíč jako
  -- dřív, takže se existující řádky aktualizují a nezaloží se duplikáty.
  SELECT COALESCE(jsonb_agg(
    item || jsonb_build_object('_suggestion_key', md5(
      COALESCE(item->>'suggestion', '') || '|' ||
      COALESCE(item->>'id_field', item->>'name_field', item->>'field', '') || '|' ||
      COALESCE(item->>'id_value', item->>'name_normalized',
               item->>'question_id', item->>'values', '')
    ))
  ), '[]'::jsonb) INTO v_keyed
  FROM jsonb_array_elements(p_rows) AS item
  WHERE item->>'suggestion' IS NOT NULL;

  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON (item->>'_suggestion_key') item
    FROM jsonb_array_elements(v_keyed) AS item
  ) AS deduped;

  v_total := jsonb_array_length(v_batch);

  SELECT count(*) INTO v_updated
  FROM public.li_entity_suggestions e
  WHERE e.suggestion_key IN (
    SELECT item->>'_suggestion_key'
    FROM jsonb_array_elements(v_batch) AS item
  );

  INSERT INTO public.li_entity_suggestions (
    suggestion_key, suggestion, id_field, id_value, name_field, name_normalized,
    names, ids, documents, advisory,
    export_id, engine_version, verify_ok, raw_data, ingested_at, updated_at
  )
  SELECT
    item->>'_suggestion_key',
    item->>'suggestion',
    item->>'id_field',
    item->>'id_value',
    item->>'name_field',
    item->>'name_normalized',
    COALESCE(ARRAY(SELECT jsonb_array_elements_text(item->'names')), '{}'::text[]),
    COALESCE(ARRAY(SELECT jsonb_array_elements_text(item->'ids')), '{}'::text[]),
    COALESCE(ARRAY(SELECT jsonb_array_elements_text(item->'documents')), '{}'::text[]),
    true,  -- doktrína: advisory návrh, nikdy automatická vazba (tabulka má CHECK)
    p_export_id,
    p_engine_version,
    p_verify_ok,
    item - '_suggestion_key',
    now(),
    now()
  FROM jsonb_array_elements(v_batch) AS item
  ON CONFLICT (suggestion_key) DO UPDATE SET
    suggestion      = EXCLUDED.suggestion,
    id_field        = EXCLUDED.id_field,
    id_value        = EXCLUDED.id_value,
    name_field      = EXCLUDED.name_field,
    name_normalized = EXCLUDED.name_normalized,
    names           = EXCLUDED.names,
    ids             = EXCLUDED.ids,
    documents       = EXCLUDED.documents,
    export_id       = EXCLUDED.export_id,
    engine_version  = EXCLUDED.engine_version,
    verify_ok       = EXCLUDED.verify_ok,
    raw_data        = EXCLUDED.raw_data,
    ingested_at     = EXCLUDED.ingested_at,
    updated_at      = now();

  v_inserted := v_total - v_updated;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'li_entity_suggestions.upsert_completed',
    jsonb_build_object(
      'export_id', p_export_id,
      'engine_version', p_engine_version,
      'verify_ok', p_verify_ok,
      'total', v_total,
      'inserted', v_inserted,
      'updated', v_updated
    )
  );

  RETURN jsonb_build_object(
    'total', v_total,
    'inserted', v_inserted,
    'updated', v_updated
  );
END;
$$;

REVOKE ALL ON FUNCTION public.li_upsert_entity_suggestions(jsonb, text, text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.li_upsert_entity_suggestions(jsonb, text, text, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.li_upsert_entity_suggestions(jsonb, text, text, boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_upsert_findings.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_upsert_findings
-- Popis: Batch upsert deterministických nálezů z local-ingest. Volá
--        svc-source-broker li-driver z findings_artifact.jsonl. finding_key
--        (dedup) počítá RPC z rule_id + finding + seřazených sha dotčených
--        dokladů — driver zůstává tenký mapper, idempotence je server-side.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT; service_role / admin / staff.
-- Audit: li_findings.upsert_completed s počty (bez PII).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.li_upsert_findings(
  p_rows           jsonb,
  p_export_id      text DEFAULT NULL,
  p_engine_version text DEFAULT NULL,
  p_verify_ok      boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean := public.is_service_role();
  v_keyed      jsonb;
  v_batch      jsonb;
  v_total      integer;
  v_updated    integer;
  v_inserted   integer;
BEGIN
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'p_rows must be a jsonb array';
  END IF;

  -- finding_key = md5(rule_id | finding | seřazené sha dokladů). Seřazení sha
  -- činí klíč nezávislý na pořadí dokumentů v poli (stabilní napříč exporty).
  SELECT COALESCE(jsonb_agg(
    item || jsonb_build_object('_finding_key', md5(
      COALESCE(item->>'rule_id', '') || '|' ||
      COALESCE(item->>'finding', '') || '|' ||
      COALESCE((
        SELECT string_agg(doc->>'source_sha256', ',' ORDER BY doc->>'source_sha256')
        FROM jsonb_array_elements(COALESCE(item->'documents', '[]'::jsonb)) AS doc
        WHERE doc->>'source_sha256' IS NOT NULL
      ), '')
    ))
  ), '[]'::jsonb) INTO v_keyed
  FROM jsonb_array_elements(p_rows) AS item
  WHERE item->>'finding' IS NOT NULL;

  -- Dedup v dávce podle vypočteného klíče (poslední výskyt vyhrává).
  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON (item->>'_finding_key') item
    FROM jsonb_array_elements(v_keyed) AS item
  ) AS deduped;

  v_total := jsonb_array_length(v_batch);

  SELECT count(*) INTO v_updated
  FROM public.li_findings f
  WHERE f.finding_key IN (
    SELECT item->>'_finding_key'
    FROM jsonb_array_elements(v_batch) AS item
  );

  -- rule_key ← export wire-pole 'rule_id' (local-ingest slug pravidla, např.
  -- 'price_mismatch'; TEXT klíč, NE uuid FK na expert_rules). Sloupec se jmenuje
  -- rule_key právě proto, aby název nesliboval FK, kterým není.
  INSERT INTO public.li_findings (
    finding_key, rule_key, finding, severity, documents, evidence,
    export_id, engine_version, verify_ok, raw_data, ingested_at, updated_at
  )
  SELECT
    item->>'_finding_key',
    item->>'rule_id',
    item->>'finding',
    item->>'severity',
    COALESCE(item->'documents', '[]'::jsonb),
    item->'evidence',
    p_export_id,
    p_engine_version,
    p_verify_ok,
    item - '_finding_key',
    now(),
    now()
  FROM jsonb_array_elements(v_batch) AS item
  ON CONFLICT (finding_key) DO UPDATE SET
    rule_key       = EXCLUDED.rule_key,
    finding        = EXCLUDED.finding,
    severity       = EXCLUDED.severity,
    documents      = EXCLUDED.documents,
    evidence       = EXCLUDED.evidence,
    export_id      = EXCLUDED.export_id,
    engine_version = EXCLUDED.engine_version,
    verify_ok      = EXCLUDED.verify_ok,
    raw_data       = EXCLUDED.raw_data,
    ingested_at    = EXCLUDED.ingested_at,
    updated_at     = now();

  v_inserted := v_total - v_updated;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'li_findings.upsert_completed',
    jsonb_build_object(
      'export_id', p_export_id,
      'engine_version', p_engine_version,
      'verify_ok', p_verify_ok,
      'total', v_total,
      'inserted', v_inserted,
      'updated', v_updated
    )
  );

  RETURN jsonb_build_object(
    'total', v_total,
    'inserted', v_inserted,
    'updated', v_updated
  );
END;
$$;

REVOKE ALL ON FUNCTION public.li_upsert_findings(jsonb, text, text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.li_upsert_findings(jsonb, text, text, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.li_upsert_findings(jsonb, text, text, boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_upsert_links.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_upsert_links
-- Popis: Batch upsert doložených vazeb mezi doklady z local-ingest. Volá
--        svc-source-broker li-driver z links_artifact.jsonl. link_key (dedup)
--        počítá RPC z rule_id + from_sha + to_sha + relation. relation=supersedes
--        je zdroj projekce „platná verze" — driver mapper, klíč server-side.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT; service_role / admin / staff.
-- Audit: li_links.upsert_completed s počty (bez PII).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.li_upsert_links(
  p_rows           jsonb,
  p_export_id      text DEFAULT NULL,
  p_engine_version text DEFAULT NULL,
  p_verify_ok      boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean := public.is_service_role();
  v_keyed      jsonb;
  v_batch      jsonb;
  v_total      integer;
  v_updated    integer;
  v_inserted   integer;
BEGIN
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'p_rows must be a jsonb array';
  END IF;

  -- link_key = md5(rule_id | from_sha | to_sha | relation).
  SELECT COALESCE(jsonb_agg(
    item || jsonb_build_object('_link_key', md5(
      COALESCE(item->>'rule_id', '') || '|' ||
      COALESCE(item->'from'->>'source_sha256', '') || '|' ||
      COALESCE(item->'to'->>'source_sha256', '') || '|' ||
      COALESCE(item->>'relation', '')
    ))
  ), '[]'::jsonb) INTO v_keyed
  FROM jsonb_array_elements(p_rows) AS item
  WHERE item->'from'->>'source_sha256' IS NOT NULL
    AND item->'to'->>'source_sha256' IS NOT NULL;

  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON (item->>'_link_key') item
    FROM jsonb_array_elements(v_keyed) AS item
  ) AS deduped;

  v_total := jsonb_array_length(v_batch);

  SELECT count(*) INTO v_updated
  FROM public.li_links l
  WHERE l.link_key IN (
    SELECT item->>'_link_key'
    FROM jsonb_array_elements(v_batch) AS item
  );

  -- rule_key ← export wire-pole 'rule_id' (TEXT slug pravidla, NE uuid FK).
  INSERT INTO public.li_links (
    link_key, rule_key, relation,
    from_sha256, from_slug, from_doc_type,
    to_sha256, to_slug, to_doc_type, matched_by,
    export_id, engine_version, verify_ok, raw_data, ingested_at, updated_at
  )
  SELECT
    item->>'_link_key',
    item->>'rule_id',
    item->>'relation',
    item->'from'->>'source_sha256',
    item->'from'->>'source_slug',
    item->'from'->>'doc_type',
    item->'to'->>'source_sha256',
    item->'to'->>'source_slug',
    item->'to'->>'doc_type',
    COALESCE(item->'matched_by', '[]'::jsonb),
    p_export_id,
    p_engine_version,
    p_verify_ok,
    item - '_link_key',
    now(),
    now()
  FROM jsonb_array_elements(v_batch) AS item
  ON CONFLICT (link_key) DO UPDATE SET
    rule_key       = EXCLUDED.rule_key,
    relation       = EXCLUDED.relation,
    from_sha256    = EXCLUDED.from_sha256,
    from_slug      = EXCLUDED.from_slug,
    from_doc_type  = EXCLUDED.from_doc_type,
    to_sha256      = EXCLUDED.to_sha256,
    to_slug        = EXCLUDED.to_slug,
    to_doc_type    = EXCLUDED.to_doc_type,
    matched_by     = EXCLUDED.matched_by,
    export_id      = EXCLUDED.export_id,
    engine_version = EXCLUDED.engine_version,
    verify_ok      = EXCLUDED.verify_ok,
    raw_data       = EXCLUDED.raw_data,
    ingested_at    = EXCLUDED.ingested_at,
    updated_at     = now();

  v_inserted := v_total - v_updated;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'li_links.upsert_completed',
    jsonb_build_object(
      'export_id', p_export_id,
      'engine_version', p_engine_version,
      'verify_ok', p_verify_ok,
      'total', v_total,
      'inserted', v_inserted,
      'updated', v_updated
    )
  );

  RETURN jsonb_build_object(
    'total', v_total,
    'inserted', v_inserted,
    'updated', v_updated
  );
END;
$$;

REVOKE ALL ON FUNCTION public.li_upsert_links(jsonb, text, text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.li_upsert_links(jsonb, text, text, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.li_upsert_links(jsonb, text, text, boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_upsert_obligations.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_upsert_obligations
-- Popis: Batch upsert registru závazků z local-ingest. Volá svc-source-broker
--        li-driver z obligations_artifact.jsonl. obligation_key (dedup) počítá
--        RPC z source_sha256 + span + rule_id. candidate_status z importu je
--        VŽDY NEEDS_REVIEW — driver nikdy nezvyšuje na HUMAN_CONFIRMED (jen
--        review flow); RPC proto candidate_status z payloadu ignoruje a vynutí
--        NEEDS_REVIEW, a existující řádky nezreví-downgraduje.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT; service_role / admin / staff.
-- Audit: li_obligations.upsert_completed s počty (bez PII).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.li_upsert_obligations(
  p_rows           jsonb,
  p_export_id      text DEFAULT NULL,
  p_engine_version text DEFAULT NULL,
  p_verify_ok      boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean := public.is_service_role();
  v_keyed      jsonb;
  v_batch      jsonb;
  v_total      integer;
  v_updated    integer;
  v_inserted   integer;
BEGIN
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'p_rows must be a jsonb array';
  END IF;

  -- obligation_key = md5(source_sha256 | char_start | char_end | rule_id).
  -- Span v dokladu je unikátní; klíč je stabilní napříč exporty téhož dokladu.
  SELECT COALESCE(jsonb_agg(
    item || jsonb_build_object('_obligation_key', md5(
      COALESCE(item->>'source_sha256', '') || '|' ||
      COALESCE(item->'span'->>'char_start', '') || '|' ||
      COALESCE(item->'span'->>'char_end', '') || '|' ||
      COALESCE(item->>'rule_id', '')
    ))
  ), '[]'::jsonb) INTO v_keyed
  FROM jsonb_array_elements(p_rows) AS item
  WHERE item->>'source_sha256' IS NOT NULL
    AND item->>'quote' IS NOT NULL;

  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON (item->>'_obligation_key') item
    FROM jsonb_array_elements(v_keyed) AS item
  ) AS deduped;

  v_total := jsonb_array_length(v_batch);

  SELECT count(*) INTO v_updated
  FROM public.li_obligations o
  WHERE o.obligation_key IN (
    SELECT item->>'_obligation_key'
    FROM jsonb_array_elements(v_batch) AS item
  );

  -- rule_key ← export wire-pole 'rule_id' (TEXT slug pravidla, NE uuid FK).
  INSERT INTO public.li_obligations (
    obligation_key, source_sha256, doc_slug, filename, rule_key,
    clause_ref, clause_title, quote, char_start, char_end, page,
    obliged_party, action, deadline_text, consequence_text, candidate_status,
    export_id, engine_version, verify_ok, raw_data, ingested_at, updated_at
  )
  SELECT
    item->>'_obligation_key',
    item->>'source_sha256',
    item->>'source_slug',
    item->>'filename',
    item->>'rule_id',
    item->>'clause_ref',
    item->>'clause_title',
    item->>'quote',
    (item->'span'->>'char_start')::integer,
    (item->'span'->>'char_end')::integer,
    (item->'span'->>'page')::integer,
    item->>'obliged_party',
    item->>'action',
    item->>'deadline_text',
    item->>'consequence_text',
    'NEEDS_REVIEW',  -- vždy z importu; promoce jen přes review flow
    p_export_id,
    p_engine_version,
    p_verify_ok,
    item - '_obligation_key',
    now(),
    now()
  FROM jsonb_array_elements(v_batch) AS item
  ON CONFLICT (obligation_key) DO UPDATE SET
    source_sha256    = EXCLUDED.source_sha256,
    doc_slug         = EXCLUDED.doc_slug,
    filename         = EXCLUDED.filename,
    rule_key         = EXCLUDED.rule_key,
    clause_ref       = EXCLUDED.clause_ref,
    clause_title     = EXCLUDED.clause_title,
    quote            = EXCLUDED.quote,
    char_start       = EXCLUDED.char_start,
    char_end         = EXCLUDED.char_end,
    page             = EXCLUDED.page,
    obliged_party    = EXCLUDED.obliged_party,
    action           = EXCLUDED.action,
    deadline_text    = EXCLUDED.deadline_text,
    consequence_text = EXCLUDED.consequence_text,
    -- candidate_status se přes replay NIKDY nesnižuje: HUMAN_CONFIRMED z review
    -- flow přetrvá, i když re-export nese NEEDS_REVIEW (advisory ≠ pravda).
    export_id        = EXCLUDED.export_id,
    engine_version   = EXCLUDED.engine_version,
    verify_ok        = EXCLUDED.verify_ok,
    raw_data         = EXCLUDED.raw_data,
    ingested_at      = EXCLUDED.ingested_at,
    updated_at       = now();

  v_inserted := v_total - v_updated;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'li_obligations.upsert_completed',
    jsonb_build_object(
      'export_id', p_export_id,
      'engine_version', p_engine_version,
      'verify_ok', p_verify_ok,
      'total', v_total,
      'inserted', v_inserted,
      'updated', v_updated
    )
  );

  RETURN jsonb_build_object(
    'total', v_total,
    'inserted', v_inserted,
    'updated', v_updated
  );
END;
$$;

REVOKE ALL ON FUNCTION public.li_upsert_obligations(jsonb, text, text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.li_upsert_obligations(jsonb, text, text, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.li_upsert_obligations(jsonb, text, text, boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_upsert_relation_suggestions.sql
-- -----------------------------------------------------------------------------

-- Function: public.li_upsert_relation_suggestions
-- Konzument entity_relation_artifact.jsonl + relation_proposal_artifact.jsonl.
--
-- Proč vzniká: engine oba artefakty VYRÁBĚL a driver je NEČETL. Naměřeno
-- 2026-08-30 na produkci — 345 odvozených vztahů, a přitom `graph_nodes` i
-- `graph_edges` měly nula řádků. Síť vazeb se odvodila a zahodila u dveří.
--
-- Dva různé tvary, jedna tabulka (druh je vlastnost, ne výčet):
--   `entity_relation`    — JEDEN parametr sdílený víc entitami: parameter+value,
--                          nese `entities_reached` (kolik identit provází).
--   `relation_proposal`  — DVOJICE parametrů: parameter_a+parameter_b+direction,
--                          nese míry funkční závislosti a lift.
-- Co se nefiltruje, jde celé do `raw_data` — sloupce jsou jen to, na co se ptáme.
--
-- Zůstává NÁVRHEM: engine oba druhy razítkuje `advisory: True` („doložený vztah,
-- nikdy automatická vazba"), tabulka to drží CHECKem. Vazbu otevře až ratifikace.
--
-- Security: SECURITY DEFINER. Admin/staff nebo service_role.
-- @audit: required

CREATE OR REPLACE FUNCTION public.li_upsert_relation_suggestions(
  p_rows              jsonb,
  p_export_id         text    DEFAULT NULL,
  p_engine_version    text    DEFAULT NULL,
  p_verify_ok         boolean DEFAULT false,
  p_ingest_source_slug text   DEFAULT 'local-ingest'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_keyed    jsonb;
  v_batch    jsonb;
  v_total    integer;
  v_updated  integer;
  v_inserted integer;
BEGIN
  IF NOT public.is_service_role() AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'p_rows must be a jsonb array';
  END IF;

  -- Klíč nese OBĚ strany i hodnotu: tentýž parametr sdílený jinou hodnotou je
  -- jiný vztah. Kdyby se klíčovalo jen parametrem, druhý běh by první přepsal.
  SELECT COALESCE(jsonb_agg(
    item || jsonb_build_object('_suggestion_key', md5(
      COALESCE(item->>'record_type', '') || '|' ||
      COALESCE(item->>'kind', '') || '|' ||
      COALESCE(item->>'parameter_a', item->>'parameter', '') || '|' ||
      COALESCE(item->>'parameter_b', '') || '|' ||
      COALESCE(item->>'value', '')
    ))
  ), '[]'::jsonb) INTO v_keyed
  FROM jsonb_array_elements(p_rows) AS item
  WHERE item->>'record_type' IS NOT NULL
    AND COALESCE(item->>'parameter_a', item->>'parameter') IS NOT NULL;

  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON (item->>'_suggestion_key') item
    FROM jsonb_array_elements(v_keyed) AS item
  ) AS deduped;

  v_total := jsonb_array_length(v_batch);

  SELECT count(*) INTO v_updated
  FROM public.li_relation_suggestions e
  WHERE e.suggestion_key IN (
    SELECT item->>'_suggestion_key' FROM jsonb_array_elements(v_batch) AS item
  );

  INSERT INTO public.li_relation_suggestions (
    suggestion_key, record_type, relation_kind, parameter_a, parameter_b, value,
    direction, observations, entities_reached, observed_from, observed_to, time_axis, advisory,
    ingest_source_slug, export_id, engine_version, verify_ok, raw_data,
    ingested_at, updated_at
  )
  SELECT
    item->>'_suggestion_key',
    item->>'record_type',
    item->>'kind',
    COALESCE(item->>'parameter_a', item->>'parameter'),
    item->>'parameter_b',
    item->>'value',
    item->>'direction',
    COALESCE((item->>'observations')::integer, 0),
    (item->>'entities_reached')::integer,
    -- Perioda je POLE ['od','do']; `entity_relation` ji nenese, proto NULL.
    -- Bez `time_axis` se období nedá interpretovat, tak jde ven s ním.
    (item->'period'->>0)::date,
    (item->'period'->>1)::date,
    item->>'time_axis',
    true,  -- doktrína: advisory návrh, nikdy automatická vazba (tabulka má CHECK)
    p_ingest_source_slug,
    p_export_id,
    p_engine_version,
    p_verify_ok,
    item - '_suggestion_key',
    now(),
    now()
  FROM jsonb_array_elements(v_batch) AS item
  ON CONFLICT (suggestion_key) DO UPDATE SET
    record_type      = EXCLUDED.record_type,
    relation_kind    = EXCLUDED.relation_kind,
    parameter_a      = EXCLUDED.parameter_a,
    parameter_b      = EXCLUDED.parameter_b,
    value            = EXCLUDED.value,
    direction        = EXCLUDED.direction,
    observations     = EXCLUDED.observations,
    entities_reached = EXCLUDED.entities_reached,
    observed_from    = EXCLUDED.observed_from,
    observed_to      = EXCLUDED.observed_to,
    time_axis        = EXCLUDED.time_axis,
    export_id        = EXCLUDED.export_id,
    engine_version   = EXCLUDED.engine_version,
    verify_ok        = EXCLUDED.verify_ok,
    raw_data         = EXCLUDED.raw_data,
    ingested_at      = EXCLUDED.ingested_at,
    updated_at       = now();

  v_inserted := v_total - v_updated;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'li_relation_suggestions.upsert_completed',
    jsonb_build_object(
      'export_id', p_export_id,
      'engine_version', p_engine_version,
      'verify_ok', p_verify_ok,
      'ingest_source_slug', p_ingest_source_slug,
      'total', v_total,
      'inserted', v_inserted,
      'updated', v_updated
    )
  );

  RETURN jsonb_build_object('total', v_total, 'inserted', v_inserted, 'updated', v_updated);
END;
$$;

REVOKE ALL ON FUNCTION public.li_upsert_relation_suggestions(jsonb, text, text, boolean, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.li_upsert_relation_suggestions(jsonb, text, text, boolean, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.li_upsert_relation_suggestions(jsonb, text, text, boolean, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_usable_field_count.sql
-- -----------------------------------------------------------------------------

-- Počet POUŽITELNÝCH polí ve vytěžení (fields jsonb registru local-ingestu).
-- Použitelné = klíč, jehož 'value' není prázdná. Tvar hodnoty je
-- {"confidence":…, "raw":…, "value":…} — samotný počet klíčů by počítal
-- i vytěžení, kde brány všechno zamítly a zůstal jen obal.
-- Měřítko monotonicity v li_upsert_source_registry: porovnává se tímhle
-- číslem, ne bajty — dva různé exporty téhož dokladu se liší v raw_data
-- vždycky, ale o kvalitě vypovídá jen kolik polí přežilo brány.
CREATE OR REPLACE FUNCTION public.li_usable_field_count(p_fields jsonb)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT count(*)::integer
  FROM jsonb_each(COALESCE(p_fields, '{}'::jsonb)) AS f(key, val)
  WHERE NULLIF(val->>'value', '') IS NOT NULL;
$function$;

-- Helper volá li_upsert_source_registry zevnitř (definer kontext, exekuuje owner);
-- přímé volání nemá pro anon/PUBLIC důvod, authenticated ho může chtít v testech.
REVOKE ALL ON FUNCTION public.li_usable_field_count(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.li_usable_field_count(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_upsert_source_registry.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_upsert_source_registry
-- Popis: Batch upsert evidenčního registru dokladů z local-ingest. Volá
--        svc-source-broker li-driver po přečtení verify-gated export balíčku.
--        Idempotence přes source_sha256 (obsahová identita dokladu) — replay
--        téhož exportu nevytvoří duplicity. Jediný writer registru (RPC-only).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT; service_role / admin / staff.
-- Audit: li_source_registry.upsert_completed s počty (bez PII).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.li_upsert_source_registry(
  p_rows           jsonb,
  p_export_id      text DEFAULT NULL,
  p_engine_version text DEFAULT NULL,
  p_verify_ok      boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  -- Kanonický boolean-NOT-NULL service check (is_service_role.sql, #588):
  -- deny-guard níže tak fail-CLOSED i bez role claimu.
  v_is_service boolean := public.is_service_role();
  v_batch      jsonb;
  v_total      integer;
  v_updated    integer;
  v_inserted   integer;
  v_written    integer := 0;
  v_kept_better integer := 0;
  v_rekeyed    integer := 0;
  -- sha příchozích verzí, které by brána monotonicity odmítla u dokladu, jenž
  -- by se jinak překlíčoval — ty se nepřeklíčují ani nevkládají (viz níže)
  v_odmitnute  text[]  := '{}';
  v_odmitnuto  integer := 0;
BEGIN
  -- Authorization (FIRST, před jakýmkoli přístupem k datům)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  -- Input validation
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'p_rows must be a jsonb array';
  END IF;

  -- Dedup podle source_sha256 — ON CONFLICT nesmí zasáhnout stejný řádek dvakrát.
  -- Poslední výskyt v dávce vyhrává (DISTINCT ON drží první po ORDER, viz níže).
  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON (item->>'source_sha256') item
    FROM jsonb_array_elements(p_rows) AS item
    WHERE item->>'source_sha256' IS NOT NULL
  ) AS deduped;

  v_total := jsonb_array_length(v_batch);

  -- ── REKEY: identitou dokladu je JMÉNO, sha je jen verze obsahu ─────────────
  -- `source_sha256` = hash OBSAHU. Když se týž doklad stáhne znovu bohatší
  -- (přibude stav úhrady, položky…), obsah se změní → jiný hash → ON CONFLICT
  -- nic nenajde a vznikne DRUHÝ řádek téhož dokladu. Naměřeno 2026-07-30 na
  -- produkci: re-ingest 4 050 faktur přidal 4 050 řádků a 3 227 jmen bylo
  -- rázem dvakrát. A refresh není výjimka — úhrady se mění pořád, takže tohle
  -- je NORMÁLNÍ provoz, ne okrajový případ.
  --
  -- Schémata to celou dobu deklarovala (`doc_identity: "@filename"`), jen to
  -- nikdy nic nevyhodnocovalo: v ingestu se řetězec `doc_identity` nevyskytuje
  -- a `li_dedupe_source_registry` z komentáře schématu neexistuje. Tady se ta
  -- deklarace poprvé stává chováním: existující řádek se PŘEKLÍČUJE na nový
  -- hash a následný ON CONFLICT ho aktualizuje na místě.
  --
  -- Proč je to bezpečné (změřeno na produkci 2026-07-31, ne odhad):
  --   · na `li_source_registry` NEUKAZUJE ŽÁDNÝ cizí klíč (0 constraintů) —
  --     přepis sha nemůže osiřet vazbu,
  --   · `filename` je vyplněné u všech 63 830 řádků a je UNIKÁTNÍ (0 kolizí).
  --
  -- Fail-safe: rekey se provede JEN u jednoznačného případu — právě jeden řádek
  -- s tím jménem a příchozí hash zatím nikomu nepatří. Jinak se nedělá nic a
  -- platí dosavadní chování (nový řádek), takže dvojznačnost nikdy nepřepíše
  -- cizí doklad. Pro dva různé dokumenty téhož jména tedy zůstává stará cesta.
  --
  -- ⛔ REKEY NESMÍ PŘEDBĚHNOUT BRÁNU MONOTONICITY (níže u ON CONFLICT). Do
  -- 2026-09-23 se překlíčovalo VŽDY a brána rozhodovala až potom: chudší verze
  -- téhož dokladu (méně než ½ polí) tak řádek překlíčovala na SVŮJ sha, brána
  -- přepis odmítla a řádek nesl nový otisk se starým obsahem — `doc_slug`,
  -- `raw_data` i klíč binárky `<sha256>.pdf` ukazovaly jinam než vytěžení,
  -- a další replay bohatší verze překlíčoval zpět. Nalezeno recenzí aisha-team,
  -- potvrzeno testem 35_li_registry_rekey_za_branou. Naměřeno v produkci
  -- 2026-09-23: 0 z 69 695 řádků nese nesoulad — vada byla zatím SKRYTÁ
  -- (odmítnutí dosud jen u replaye se stejným sha), spustila by ji první chudší
  -- verze pod novým otiskem.
  -- Proto se brána vyhodnotí UŽ TADY: kandidát, kterého by odmítla, se
  -- nepřeklíčuje a jeho verze se ani NEVLOŽÍ (jinak by pod novým sha vznikl
  -- druhý řádek téhož dokladu). Započítá se do kept_better jako každé odmítnutí.
  WITH incoming AS (
    SELECT DISTINCT ON (item->>'filename')
           item->>'filename'      AS filename,
           item->>'source_sha256' AS sha,
           item->'fields'         AS fields
    FROM jsonb_array_elements(v_batch) AS item
    WHERE NULLIF(item->>'filename', '') IS NOT NULL
    ORDER BY item->>'filename'
  ),
  -- Jeden průchod tabulkou, ne poddotaz na řádek. První verze se u každého
  -- příchozího dokladu ptala `SELECT count(*) … WHERE filename = …`, což je při
  -- dávce 4 050 dokladů proti 63 830 řádkům 4 050 sekvenčních průchodů —
  -- naměřeno na produkci 2026-07-31 jako `Query read timeout` (li-driver bundle
  -- fail-closed odmítl a držel kurzor). Agregace předem + join dělá totéž na
  -- jedno projití; `idx_li_source_registry_filename` je k tomu ten index.
  -- DISTINCT ON, ne agregace: `min()` pro uuid v Postgresu neexistuje a řádek
  -- stejně bereme jen tehdy, když je JEDINÝ (počet z window funkce vedle).
  existing AS (
    SELECT DISTINCT ON (r.filename)
           r.filename,
           r.id,
           r.source_sha256 AS sha,
           r.fields,
           count(*) OVER (PARTITION BY r.filename) AS n
    FROM public.li_source_registry r
    JOIN incoming i ON i.filename = r.filename
    ORDER BY r.filename, r.id
  ),
  kandidati AS (
    SELECT e.id, i.sha,
           -- TÁŽ podmínka jako brána u ON CONFLICT níže (jediný zdroj pravdy:
           -- li_usable_field_count; poměr ½ viz komentář u brány)
           (public.li_usable_field_count(e.fields) > 0
            AND public.li_usable_field_count(i.fields) * 2
                < public.li_usable_field_count(e.fields)) AS horsi
    FROM incoming i
    JOIN existing e ON e.filename = i.filename
    WHERE e.n = 1                 -- právě jeden řádek toho jména (jinak nehádat)
      AND e.sha <> i.sha          -- obsah se opravdu změnil (replay nic nepřeklíčuje)
      AND NOT EXISTS (SELECT 1 FROM public.li_source_registry r3
                       WHERE r3.source_sha256 = i.sha)  -- cílový hash je volný
  ),
  prekliceno AS (
    UPDATE public.li_source_registry t
       SET source_sha256 = k.sha
      FROM kandidati k
     WHERE t.id = k.id
       AND NOT k.horsi
    RETURNING 1
  )
  SELECT (SELECT count(*) FROM prekliceno)::integer,
         COALESCE((SELECT array_agg(k.sha) FROM kandidati k WHERE k.horsi), '{}')
    INTO v_rekeyed, v_odmitnute;
  v_odmitnuto := cardinality(v_odmitnute);

  -- Počítá se AŽ po rekeyi: překlíčované řádky jsou update, ne insert. Jinak by
  -- audit hlásil vložení tam, kde se doklad jen aktualizoval.
  SELECT count(*) INTO v_updated
  FROM public.li_source_registry r
  WHERE r.source_sha256 IN (
    SELECT item->>'source_sha256'
    FROM jsonb_array_elements(v_batch) AS item
  );

  INSERT INTO public.li_source_registry (
    source_sha256, doc_slug, story_id, doc_type, doc_class, filename, status,
    missing_required, fields, fields_pending_review, line_items,
    lines_pending_review, schema_version, superseded_by,
    export_id, engine_version, verify_ok, raw_data, storage_bucket,
    ingested_at, updated_at
  )
  SELECT
    item->>'source_sha256',
    item->>'source_slug',
    NULLIF(item->>'story_id', '')::uuid,
    item->>'doc_type',
    item->>'doc_class',
    item->>'filename',
    COALESCE(item->>'status', 'REVIEW'),
    COALESCE(
      ARRAY(SELECT jsonb_array_elements_text(item->'missing_required')),
      '{}'::text[]
    ),
    COALESCE(item->'fields', '{}'::jsonb),
    COALESCE(item->'fields_pending_review', '{}'::jsonb),
    COALESCE(item->'line_items', '[]'::jsonb),
    COALESCE((item->>'lines_pending_review')::integer, 0),
    item->>'schema_version',
    item->>'superseded_by',
    p_export_id,
    p_engine_version,
    p_verify_ok,
    item,
    -- Umístění binárky je DATA řádku: píše ho ingest, který ví, kam objekt
    -- uložil (žádná konstanta v kódu; klíč objektu = <sha256>.pdf).
    NULLIF(item->>'storage_bucket', ''),
    now(),
    now()
  FROM jsonb_array_elements(v_batch) AS item
  -- verze odmítnuté už při rekeyi se nevkládají (viz REKEY NESMÍ PŘEDBĚHNOUT BRÁNU)
  WHERE NOT (item->>'source_sha256' = ANY (v_odmitnute))
  ON CONFLICT (source_sha256) DO UPDATE SET
    doc_slug             = EXCLUDED.doc_slug,
    story_id             = EXCLUDED.story_id,
    doc_type             = EXCLUDED.doc_type,
    doc_class            = EXCLUDED.doc_class,
    filename             = EXCLUDED.filename,
    status               = EXCLUDED.status,
    missing_required     = EXCLUDED.missing_required,
    fields               = EXCLUDED.fields,
    fields_pending_review = EXCLUDED.fields_pending_review,
    line_items           = EXCLUDED.line_items,
    lines_pending_review = EXCLUDED.lines_pending_review,
    schema_version       = EXCLUDED.schema_version,
    superseded_by        = EXCLUDED.superseded_by,
    export_id            = EXCLUDED.export_id,
    engine_version       = EXCLUDED.engine_version,
    verify_ok            = EXCLUDED.verify_ok,
    raw_data             = EXCLUDED.raw_data,
    -- replay bez bucketu nesmí smazat známé umístění binárky
    storage_bucket       = COALESCE(EXCLUDED.storage_bucket, li_source_registry.storage_bucket),
    ingested_at          = EXCLUDED.ingested_at,
    updated_at           = now()
  -- ── MONOTONICITA: pozdější balík nesmí být HORŠÍ ──────────────────────────
  -- Upsert je idempotentní, ale do 2026-08-01 nebyl monotónní: „pozdější
  -- vždycky vyhraje". Naměřeno 2026-07-30 na produkci — balík z neverzovaného
  -- lokálního běhu (engine 'local', schema null) přepsal smlouvy a shodil
  -- 11 z 20 polí (counterparty 29→9, supplier_name 45→11). Registr od té doby
  -- nesl poslední, co někdo shodil, ne nejlepší, co jsme kdy naměřili.
  --
  -- Řádek se proto NEPŘEPÍŠE, když příchozí vytěžení nemá ani polovinu
  -- použitelných polí existujícího — celý řádek zůstává, včetně provenience,
  -- která tak dál ukazuje na balík, jenž obsah skutečně vyrobil. Poměr ½ je
  -- záměrně hrubý: legitimní oprava jednotek polí projde, propad na pětinu ne.
  -- Plánovaný hromadný re-ingest nad kompletními vstupy vytěží VÍC polí, takže
  -- touhle branou projde přirozeně — brána chrání před regresí, ne před opravou.
  -- Odmítnuté řádky počítá v_kept_better (viz audit) a li-driver je hlásí WARN.
  WHERE NOT (
    public.li_usable_field_count(li_source_registry.fields) > 0
    AND public.li_usable_field_count(EXCLUDED.fields) * 2
        < public.li_usable_field_count(li_source_registry.fields)
  );

  -- ROW_COUNT u INSERT … ON CONFLICT nepočítá řádky, které DO UPDATE WHERE
  -- odmítl — rozdíl proti dávce je tedy přesně počet ochráněných řádků.
  GET DIAGNOSTICS v_written = ROW_COUNT;
  -- kept_better = odmítnuté branou u ON CONFLICT + odmítnuté už při rekeyi
  -- (ty se nevložily, v_written je nezná).
  v_kept_better := v_total - v_written;
  -- Odmítnuté při rekeyi nejsou ani vložené, ani mezi existujícími (jejich sha
  -- v tabulce není) — odečtou se zvlášť, jinak by audit hlásil vložení.
  v_inserted := v_total - v_updated - v_odmitnuto;
  -- 'updated' odteď znamená SKUTEČNĚ přepsané (dřív: kolik řádků existovalo).
  v_updated := v_updated - (v_kept_better - v_odmitnuto);

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'li_source_registry.upsert_completed',
    jsonb_build_object(
      'export_id', p_export_id,
      'engine_version', p_engine_version,
      'verify_ok', p_verify_ok,
      'total', v_total,
      'inserted', v_inserted,
      'updated', v_updated,
      -- Kolik dokladů se překlíčovalo na nový obsah (refresh téhož dokladu).
      -- Patří do auditu: bez toho by „updated" nešlo odlišit od replaye beze změny.
      'rekeyed', v_rekeyed,
      -- Kolik řádků brána monotonicity ochránila před horším vytěžením.
      'kept_better', v_kept_better
    )
  );

  RETURN jsonb_build_object(
    'total', v_total,
    'inserted', v_inserted,
    'updated', v_updated,
    'rekeyed', v_rekeyed,
    'kept_better', v_kept_better
  );
END;
$$;

REVOKE ALL ON FUNCTION public.li_upsert_source_registry(jsonb, text, text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.li_upsert_source_registry(jsonb, text, text, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.li_upsert_source_registry(jsonb, text, text, boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/link_audit_to_ai_run.sql
-- -----------------------------------------------------------------------------

-- Function: public.link_audit_to_ai_run
-- Purpose: Post-hoc correlation — attach an audit_journal entry to an AI run
--          and/or Langfuse trace after the entry was created.
--          Enables full audit ↔ ai_runs ↔ ai_trace_events ↔ Langfuse traceability.
-- Requires: audit_journal.ai_run_id column (added in migration 20260404120000)
-- Security: SECURITY DEFINER with search_path set.
-- Part of: Fáze 2 — Audit-Trace Correlation

CREATE OR REPLACE FUNCTION public.link_audit_to_ai_run(
  p_audit_id          uuid,
  p_ai_run_id         uuid,
  p_langfuse_trace_id text DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  -- Verify ai_run_id ownership: caller must own the run or be service_role
  IF auth.role() <> 'service_role' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.ai_runs
      WHERE id = p_ai_run_id
        AND actor_user_id = auth.uid()
    ) THEN
      RAISE EXCEPTION 'ai_run not found or access denied: %', p_ai_run_id;
    END IF;
  END IF;

  -- Only allow updating if audit entry belongs to current user OR caller is service_role
  UPDATE public.audit_journal
  SET
    ai_run_id         = p_ai_run_id,
    langfuse_trace_id = COALESCE(p_langfuse_trace_id, langfuse_trace_id)
  WHERE id = p_audit_id
    AND (user_id = auth.uid() OR auth.role() = 'service_role');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'audit_journal entry not found or access denied: %', p_audit_id;
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.link_audit_to_ai_run(uuid, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.link_audit_to_ai_run(uuid, uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.link_audit_to_ai_run(uuid, uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/link_installation_to_partner.sql
-- -----------------------------------------------------------------------------

-- Function: public.link_installation_to_partner
-- Links a GitHub App installation to a partner profile.
-- @security: admin/staff only (SECURITY INVOKER)

CREATE OR REPLACE FUNCTION public.link_installation_to_partner(
  p_installation_id bigint,
  p_partner_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
  v_row public.github_app_installations;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff role required';
  END IF;

  UPDATE public.github_app_installations
  SET partner_id = p_partner_id,
      updated_at = now()
  WHERE installation_id = p_installation_id
    AND suspended_at IS NULL
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Installation % not found or suspended', p_installation_id;
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'GITHUB_INSTALLATION_LINKED',
    jsonb_build_object(
      'installation_id', p_installation_id,
      'partner_id', p_partner_id,
      'account_login', v_row.account_login,
      'area', 'github_app',
      'severity', 'info'
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'installation_id', p_installation_id,
    'partner_id', p_partner_id,
    'account_login', v_row.account_login
  );
END;
$$;

REVOKE ALL ON FUNCTION public.link_installation_to_partner(bigint, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.link_installation_to_partner(bigint, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/link_story_to_installation_repo.sql
-- -----------------------------------------------------------------------------

-- Function: public.link_story_to_installation_repo
-- Links a partner_story to a GitHub App installation and repository.
-- Updates repo_url, repo_provider, default_branch on the story.
-- @security: admin/staff only (SECURITY INVOKER)

CREATE OR REPLACE FUNCTION public.link_story_to_installation_repo(
  p_story_id uuid,
  p_installation_id bigint,
  p_repo_full_name text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
  v_repo public.github_app_repositories;
  v_install public.github_app_installations;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff role required';
  END IF;

  SELECT * INTO v_install
  FROM public.github_app_installations
  WHERE installation_id = p_installation_id
    AND suspended_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Installation % not found or suspended', p_installation_id;
  END IF;

  SELECT * INTO v_repo
  FROM public.github_app_repositories
  WHERE installation_id = p_installation_id
    AND repo_full_name = p_repo_full_name
    AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Repository % not found in installation %', p_repo_full_name, p_installation_id;
  END IF;

  UPDATE public.partner_stories
  SET github_installation_id = p_installation_id,
      repo_url = 'https://github.com/' || p_repo_full_name,
      repo_provider = 'github',
      default_branch = COALESCE(v_repo.default_branch, 'main'),
      updated_at = now()
  WHERE id = p_story_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Story % not found', p_story_id;
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'STORY_REPO_LINKED',
    jsonb_build_object(
      'story_id', p_story_id,
      'installation_id', p_installation_id,
      'repo_full_name', p_repo_full_name,
      'area', 'github_app',
      'severity', 'info'
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'story_id', p_story_id,
    'installation_id', p_installation_id,
    'repo_full_name', p_repo_full_name,
    'partner_id', v_install.partner_id
  );
END;
$$;

REVOKE ALL ON FUNCTION public.link_story_to_installation_repo(uuid, bigint, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.link_story_to_installation_repo(uuid, bigint, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/list_active_agent_runs.sql
-- -----------------------------------------------------------------------------

-- Function: public.list_active_agent_runs
-- Description: Returns currently-running ai_runs for the mission-control
--   LiveAgentsStrip pane. Joined with most-recent ai_trace_event for
--   "what is the agent doing right now" summary.
-- Security: SECURITY DEFINER. Admin/staff visibility on every row;
--   non-admins see only runs whose story they participate in (matches
--   kanban_stories_view semantics so the same user sees consistent slice
--   of "AISHA activity" across panels).
-- See also: ai_runs (table), ai_trace_events (table), kanban_stories_view
--   (parallel viewer), useLiveTable hook (UI consumer).

CREATE OR REPLACE FUNCTION public.list_active_agent_runs(
  p_limit int DEFAULT 20
)
RETURNS TABLE (
  run_id                uuid,
  kind                  text,
  story_id              uuid,
  story_title           text,
  is_stack_default      boolean,
  status                text,
  started_at            timestamptz,
  elapsed_ms            bigint,
  current_agent_slug    text,
  current_step          text,
  step_count            int,
  cost_total        numeric
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id  uuid := auth.uid();
  v_is_admin boolean := false;
BEGIN
  IF v_user_id IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  v_is_admin := public.is_admin_or_staff(v_user_id);

  RETURN QUERY
  WITH active AS (
    SELECT ar.id, ar.kind, ar.story_id, ar.status, ar.started_at,
           ar.route_plan, ar.metadata, ar.cost_total_json
    FROM public.ai_runs ar
    WHERE ar.status = 'running'
      -- ide_session aggregates (agent_live_sessions telemetry runs) surface in
      -- the AgentSessionsStrip pane via list_active_agent_sessions — exclude
      -- them here so the two mission-control panes stay disjoint.
      AND ar.kind <> 'ide_session'
  ),
  visible AS (
    SELECT a.*
    FROM active a
    LEFT JOIN public.partner_stories ps ON ps.id = a.story_id
    WHERE
      v_is_admin
      OR a.story_id IS NULL                 -- system run, admin-only via fallback below
      OR ps.is_stack_default = true
      OR EXISTS (
        SELECT 1 FROM public.story_participants sp
        WHERE sp.story_id = a.story_id AND sp.user_id = v_user_id
      )
  ),
  latest_event AS (
    SELECT DISTINCT ON (ate.run_id)
      ate.run_id, ate.agent_slug, ate.operation, ate.created_at
    FROM public.ai_trace_events ate
    WHERE ate.run_id IN (SELECT id FROM visible)
    ORDER BY ate.run_id, ate.created_at DESC
  ),
  event_count AS (
    SELECT ate.run_id, COUNT(*)::int AS n
    FROM public.ai_trace_events ate
    WHERE ate.run_id IN (SELECT id FROM visible)
    GROUP BY ate.run_id
  )
  SELECT
    v.id                                                     AS run_id,
    v.kind,
    v.story_id,
    ps.title                                                 AS story_title,
    COALESCE(ps.is_stack_default, false)                     AS is_stack_default,
    v.status,
    v.started_at,
    -- elapsed_ms: now - started, capped at int8 range; clients render hh:mm:ss.
    EXTRACT(EPOCH FROM (now() - v.started_at))::bigint * 1000 AS elapsed_ms,
    COALESCE(
      le.agent_slug,
      v.route_plan -> 'agents' -> 0 ->> 'slug',
      v.metadata ->> 'agent_slug',
      v.kind
    )                                                        AS current_agent_slug,
    le.operation                                             AS current_step,
    COALESCE(ec.n, 0)                                        AS step_count,
    -- cost_total_json shape: { total, breakdown[] }. Fallback to 0.
    NULLIF(v.cost_total_json ->> 'total', '')::numeric   AS cost_total
  FROM visible v
  LEFT JOIN public.partner_stories ps ON ps.id = v.story_id
  LEFT JOIN latest_event           le ON le.run_id = v.id
  LEFT JOIN event_count            ec ON ec.run_id = v.id
  ORDER BY v.started_at DESC
  LIMIT LEAST(p_limit, 100);
END;
$$;

REVOKE ALL ON FUNCTION public.list_active_agent_runs(int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.list_active_agent_runs(int) TO authenticated;
GRANT EXECUTE ON FUNCTION public.list_active_agent_runs(int) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/list_active_agent_sessions.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: list_active_agent_sessions
-- Description: Active agent work sessions (any source) for the Mission
--   Control AgentSessionsStrip and the Dirigent VS Code live panel.
--   Live token/cost figures are aggregated from ai_trace_events through the
--   session's ide_session ai_run — the same rollup finish_ai_run persists.
-- Security: SECURITY DEFINER. Mirrors list_active_agent_runs visibility:
--   admin/staff see everything, others see their own sessions.
-- See also: agent_live_sessions (table), list_active_agent_runs (the
--   AISHA-orchestrated-runs twin pane), useAgentLiveSessions (UI consumer).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.list_active_agent_sessions(
  p_limit  int  DEFAULT 20,
  p_source text DEFAULT NULL
)
RETURNS TABLE (
  session_id      text,
  source          text,
  story_id        uuid,
  story_title     text,
  user_id         uuid,
  agent_run_id    uuid,
  ai_run_id       uuid,
  branch          text,
  current_phase   text,
  phase_detail    text,
  current_task    text,
  last_tool       text,
  last_file       text,
  subagents       jsonb,
  tokens_estimate int,
  tokens_input    bigint,
  tokens_output   bigint,
  cost        numeric,
  started_at      timestamptz,
  updated_at      timestamptz,
  elapsed_ms      bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id  uuid    := auth.uid();
  v_is_admin boolean := false;
BEGIN
  IF v_user_id IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  v_is_admin := public.is_admin_or_staff(v_user_id);

  RETURN QUERY
  SELECT
    s.session_id,
    s.source,
    s.story_id,
    ps.title                                                   AS story_title,
    s.user_id,
    s.agent_run_id,
    s.ai_run_id,
    s.branch,
    s.current_phase,
    s.phase_detail,
    s.current_task,
    s.last_tool,
    s.last_file,
    s.subagents,
    s.tokens_estimate,
    -- SUM() over bigint widens to numeric; cast back to match the bigint
    -- column types declared in RETURNS TABLE (else 42804 at call time).
    COALESCE(tc.tokens_in, 0)::bigint                          AS tokens_input,
    COALESCE(tc.tokens_out, 0)::bigint                         AS tokens_output,
    COALESCE(tc.usd, 0)::numeric                               AS cost,
    s.started_at,
    s.updated_at,
    EXTRACT(EPOCH FROM (now() - s.started_at))::bigint * 1000  AS elapsed_ms
  FROM public.agent_live_sessions s
  LEFT JOIN public.partner_stories ps ON ps.id = s.story_id
  LEFT JOIN LATERAL (
    SELECT
      SUM(COALESCE((ate.cost_json->>'tokens_in')::bigint, 0))  AS tokens_in,
      SUM(COALESCE((ate.cost_json->>'tokens_out')::bigint, 0)) AS tokens_out,
      SUM(COALESCE((ate.cost_json->>'usd')::numeric, 0))       AS usd
    FROM public.ai_trace_events ate
    WHERE ate.run_id = s.ai_run_id
  ) tc ON s.ai_run_id IS NOT NULL
  WHERE
    s.current_phase <> 'stopped'
    AND s.updated_at > now() - interval '1 hour'
    AND (p_source IS NULL OR s.source = p_source)
    AND (
      v_is_admin
      OR s.user_id = v_user_id
    )
  ORDER BY s.updated_at DESC
  LIMIT LEAST(p_limit, 100);
END;
$$;

REVOKE ALL ON FUNCTION public.list_active_agent_sessions(int, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.list_active_agent_sessions(int, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.list_active_agent_sessions(int, text) TO service_role;

COMMENT ON FUNCTION public.list_active_agent_sessions(int, text) IS
  'Active agent work sessions (source-dimensioned) with live token/cost rollup from ai_trace_events. Admin sees all; others own sessions only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/list_agent_kb_bindings.sql
-- -----------------------------------------------------------------------------

-- Function: public.list_agent_kb_bindings
-- Description: Returns one row per (agent, knowledge_item) binding for a
--   given story, joined with the expert_rules metadata the matrix UI
--   needs to render rich rows. Includes both story-scoped (story_id =
--   p_story_id) AND global (story_id IS NULL) bindings so the matrix can
--   show which globals apply to this story too.
-- Security: SECURITY DEFINER. Same admin-or-participant gate as
--   story_timeline / kanban_stories_view.

CREATE OR REPLACE FUNCTION public.list_agent_kb_bindings(
  p_story_id uuid,
  p_agent_slug text DEFAULT NULL
)
RETURNS TABLE (
  binding_id        uuid,
  agent_slug        text,
  knowledge_item_id uuid,
  knowledge_title   text,
  knowledge_slug    text,
  knowledge_category text,
  knowledge_status  text,
  binding_type      text,
  priority          int,
  version           int,
  is_active         boolean,
  story_id          uuid,
  is_global         boolean,
  notes             text,
  created_at        timestamptz,
  updated_at        timestamptz,
  created_by        uuid
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id  uuid := auth.uid();
  v_is_admin boolean := false;
BEGIN
  IF v_user_id IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  v_is_admin := public.is_admin_or_staff(v_user_id);

  IF NOT v_is_admin
     AND NOT EXISTS (
       SELECT 1 FROM public.partner_stories ps
       WHERE ps.id = p_story_id
         AND (
           ps.is_stack_default = true
           OR EXISTS (
             SELECT 1 FROM public.story_participants sp
             WHERE sp.story_id = ps.id AND sp.user_id = v_user_id
           )
         )
     )
  THEN
    RAISE EXCEPTION 'Access denied: story participant or admin/staff required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    akb.id                          AS binding_id,
    akb.agent_slug,
    akb.knowledge_item_id,
    er.title                        AS knowledge_title,
    er.slug                         AS knowledge_slug,
    er.category::text               AS knowledge_category,
    er.status::text                 AS knowledge_status,
    akb.binding_type,
    akb.priority,
    akb.version,
    akb.is_active,
    akb.story_id,
    (akb.story_id IS NULL)          AS is_global,
    akb.notes,
    akb.created_at,
    akb.updated_at,
    akb.created_by
  FROM public.agent_knowledge_bindings akb
  JOIN public.expert_rules er ON er.id = akb.knowledge_item_id
  WHERE (akb.story_id = p_story_id OR akb.story_id IS NULL)
    AND (p_agent_slug IS NULL OR akb.agent_slug = p_agent_slug)
  ORDER BY
    akb.agent_slug ASC,
    akb.priority DESC,
    er.title ASC;
END;
$$;

REVOKE ALL ON FUNCTION public.list_agent_kb_bindings(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.list_agent_kb_bindings(uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.list_agent_kb_bindings(uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/list_agent_runs.sql
-- -----------------------------------------------------------------------------

-- Function: public.list_agent_runs
-- Description: Paginated list of the caller's agent runs, newest first.
--   Max 100 rows per call; service_role sees all via RLS policy.
-- Security: SECURITY DEFINER, grants to authenticated

CREATE OR REPLACE FUNCTION public.list_agent_runs(
  p_limit  int DEFAULT 20,
  p_offset int DEFAULT 0
)
RETURNS TABLE (
  id           uuid,
  kind         text,
  status       text,
  source       text,
  source_ref   text,
  started_at   timestamptz,
  finished_at  timestamptz,
  created_at   timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  RETURN QUERY
  SELECT r.id, r.kind, r.status, r.source, r.source_ref,
         r.started_at, r.finished_at, r.created_at
  FROM public.agent_runs r
  WHERE r.requested_by = auth.uid()
  ORDER BY r.created_at DESC
  LIMIT LEAST(p_limit, 100) OFFSET p_offset;
END;
$$;

REVOKE ALL ON FUNCTION public.list_agent_runs(int, int) FROM PUBLIC;
