-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/list_pending_claude_approvals.sql
-- -----------------------------------------------------------------------------

-- Function: public.list_pending_claude_approvals
-- Description: Mission Control inbox — claude_cli_task runs HELD pending approval
--   (fn_admit_clow returned 'ask': approval_required + approved_at IS NULL). Joins
--   the journaled ai_decisions row so an approver sees the admission reason
--   (awaiting) + computed risk before calling approve_claude_run. Read-only.
-- Security: SECURITY DEFINER (reads across requesters; the admin/staff gate is the
--   access control), admin/staff only.

CREATE OR REPLACE FUNCTION public.list_pending_claude_approvals()
RETURNS TABLE (
  run_id       uuid,
  story_id     uuid,
  source       text,
  awaiting     text,
  decision_id  uuid,
  risk_level   text,
  requested_by uuid,
  created_at   timestamptz
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin/staff required';
  END IF;

  RETURN QUERY
  SELECT r.id,
         NULLIF(r.inputs->>'story_id', '')::uuid,
         r.source,
         r.awaiting,
         r.decision_id,
         d.risk_level,
         r.requested_by,
         r.created_at
  FROM public.agent_runs r
  LEFT JOIN public.ai_decisions d ON d.id = r.decision_id
  WHERE r.kind = 'claude_cli_task'
    AND r.approval_required
    AND r.approved_at IS NULL
    AND r.status = 'queued'
  ORDER BY r.created_at;
END;
$$;

REVOKE ALL ON FUNCTION public.list_pending_claude_approvals() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.list_pending_claude_approvals() TO authenticated;

COMMENT ON FUNCTION public.list_pending_claude_approvals() IS
  'Mission Control inbox of claude_cli_task runs held pending approval (fn_admit_clow ask). Admin/staff only; joins ai_decisions for the admission reason + risk. Feeds approve_claude_run.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/list_pending_spend_approvals.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: list_pending_spend_approvals
-- Purpose: Mission Control SpendApprovalPending pane — runs blocked at
--          admission with awaiting='spend_approval', newest first, with the
--          authorization payload (estimate, thresholds, reason) persisted in
--          run metadata at admission time.
-- Security: SECURITY DEFINER; admin/staff see all, others see runs on
--           stories they participate in (mirrors list_active_agent_runs).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.list_pending_spend_approvals(
  p_limit int DEFAULT 20
)
RETURNS TABLE (
  run_id          uuid,
  kind            text,
  story_id        uuid,
  story_title     text,
  requested_at    timestamptz,
  age_ms          bigint,
  estimate    numeric,
  decision_reason text,
  authorization_json jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id  uuid    := auth.uid();
  v_is_admin boolean := false;
BEGIN
  IF v_user_id IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  v_is_admin := public.is_admin_or_staff(v_user_id);

  RETURN QUERY
  SELECT
    ar.id                                                       AS run_id,
    ar.kind,
    ar.story_id,
    ps.title                                                    AS story_title,
    ar.started_at                                               AS requested_at,
    EXTRACT(EPOCH FROM (now() - ar.started_at))::bigint * 1000  AS age_ms,
    NULLIF(ar.metadata->'spend_authorization'->>'estimate_used', '')::numeric
                                                                AS estimate,
    ar.metadata->'spend_authorization'->>'reason'               AS decision_reason,
    ar.metadata->'spend_authorization'                          AS authorization_json
  FROM public.ai_runs ar
  LEFT JOIN public.partner_stories ps ON ps.id = ar.story_id
  WHERE ar.status = 'blocked'
    AND ar.metadata->>'awaiting' = 'spend_approval'
    AND (
      v_is_admin
      OR EXISTS (
        SELECT 1 FROM public.story_participants sp
        WHERE sp.story_id = ar.story_id AND sp.user_id = v_user_id
      )
    )
  ORDER BY ar.started_at DESC
  LIMIT LEAST(p_limit, 100);
END;
$$;

REVOKE ALL ON FUNCTION public.list_pending_spend_approvals(int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.list_pending_spend_approvals(int) TO authenticated;
GRANT EXECUTE ON FUNCTION public.list_pending_spend_approvals(int) TO service_role;

COMMENT ON FUNCTION public.list_pending_spend_approvals(int) IS
  'Runs blocked awaiting spend approval, with admission-time authorization payload, for the Mission Control SpendApprovalPending pane.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/list_playwright_runs.sql
-- -----------------------------------------------------------------------------

-- list_playwright_runs
-- Admin/staff facing audited READ used by the Appsmith Playwright QA page.
-- Returns the latest N runs (newest first) with the columns the dashboard
-- table renders, optionally filtered by status set + time window.
--
-- Does NOT leak service-role concerns (no internal runner tokens, no raw
-- runner stdout) — those live in the report bucket which Appsmith renders
-- through a signed URL when the operator clicks "View Report".

CREATE OR REPLACE FUNCTION public.list_playwright_runs(
  p_limit integer DEFAULT 50,
  p_status_filter text[] DEFAULT NULL,
  p_window_hours integer DEFAULT 168
)
RETURNS TABLE (
  id uuid,
  trigger_kind public.playwright_run_trigger,
  target_env text,
  target_base_url text,
  suite text,
  deploy_ref text,
  status public.playwright_run_status,
  total integer,
  passed integer,
  failed integer,
  skipped integer,
  duration_ms integer,
  report_storage_path text,
  error_message text,
  requested_by uuid,
  approval_required boolean,
  approved_by uuid,
  approved_at timestamptz,
  created_at timestamptz,
  started_at timestamptz,
  finished_at timestamptz,
  app_name text,
  active_slot text,
  story_id uuid,
  triggered_rollback_id uuid,
  metadata jsonb
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 500);
  v_window integer := LEAST(GREATEST(COALESCE(p_window_hours, 168), 1), 24 * 30);
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin/staff required';
  END IF;

  RETURN QUERY
  SELECT
    r.id, r.trigger_kind, r.target_env, r.target_base_url, r.suite, r.deploy_ref,
    r.status, r.total, r.passed, r.failed, r.skipped, r.duration_ms,
    r.report_storage_path, r.error_message,
    r.requested_by, r.approval_required, r.approved_by, r.approved_at,
    r.created_at, r.started_at, r.finished_at,
    r.app_name, r.active_slot, r.story_id, r.triggered_rollback_id,
    r.metadata
  FROM public.playwright_runs r
  WHERE r.created_at >= now() - make_interval(hours => v_window)
    AND (p_status_filter IS NULL OR r.status::text = ANY(p_status_filter))
  ORDER BY r.created_at DESC
  LIMIT v_limit;
END;
$$;

REVOKE ALL ON FUNCTION public.list_playwright_runs(integer, text[], integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.list_playwright_runs(integer, text[], integer) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/list_plugins_to_declare.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: list_plugins_to_declare
-- Popis: Které pluginy má host „zapálit" — spustit v režimu jen-deklaruj (init
--        bez stahování), aby jejich rozvrhy vznikly v plugin_schedules.
--
-- ⛔ PROČ VZNIKÁ. Naměřeno 2026-09-24 v produkci RIQ: rozvrhy vznikaly jen po
-- úspěšném běhu pluginu, ale první běh nespouštělo nic → plugin_schedules = 0,
-- žádný plugin nikdy neběžel, přestože zdroje byly aktivní a měly pověření.
--
-- Kandidát = plugin, který JE v provozu (canary/ga, tentýž filtr jako katalog
-- hostu) a je napojený na AKTIVNÍ zdroj dat, jehož vlastník je znám, a zároveň:
--   · ještě nebyl zapálen pro tohoto tenanta, NEBO
--   · od posledního zapálení vyšla nová verze (nová verze může deklarovat jiné
--     rozvrhy — stará deklarace by jinak platila navždy), NEBO
--   · poslední zapálení selhalo a od té doby uběhlo p_retry_minutes (opakování,
--     ne smyčka každou minutou).
--
-- ⭐ TENANT = vlastník příběhu zdroje (partner_stories.user_id, jinak
-- partner_id). Zdroj bez vlastníka se NEZAPÁLÍ — hádat tenanta by znamenalo
-- spouštět cizí data pod náhodnou identitou. Takový zdroj ukáže hlídač stavu
-- zdrojů (get_data_source_feed_health) jako „bez vlastníka".
--
-- Bezpečnost: jen služba (svc-plugin-system).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.list_plugins_to_declare(
  p_limit         integer DEFAULT 5,
  p_retry_minutes integer DEFAULT 60
)
RETURNS TABLE (
  plugin_slug    text,
  tenant_id      uuid,
  source_slug    text,
  plugin_version text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'list_plugins_to_declare: jen služba (svc-plugin-system)' USING ERRCODE = '42501';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_retry_minutes IS NULL OR p_retry_minutes < 1 THEN
    RAISE EXCEPTION 'list_plugins_to_declare: limit >= 1 a opakování >= 1 min';
  END IF;

  RETURN QUERY
  WITH kandidati AS (
    SELECT DISTINCT ON (pc.id, COALESCE(ps.user_id, ps.partner_id))
           pc.id                                   AS plugin_id,
           pc.slug                                 AS plugin_slug,
           COALESCE(ps.user_id, ps.partner_id)     AS tenant_id,
           s.source_slug,
           (SELECT v.version FROM public.plugin_versions v
             WHERE v.plugin_id = pc.id
             ORDER BY v.created_at DESC LIMIT 1)   AS plugin_version
      FROM public.agent_knowledge_sources s
      JOIN public.plugin_catalog pc ON pc.id = s.source_plugin_id
      JOIN public.partner_stories ps ON ps.id = s.story_id
     WHERE s.is_active
       AND pc.status IN ('canary', 'ga')
       AND COALESCE(ps.user_id, ps.partner_id) IS NOT NULL
     ORDER BY pc.id, COALESCE(ps.user_id, ps.partner_id), s.source_slug
  )
  SELECT k.plugin_slug, k.tenant_id, k.source_slug, k.plugin_version
    FROM kandidati k
    LEFT JOIN public.plugin_declarations d
      ON d.plugin_id = k.plugin_id AND d.tenant_id = k.tenant_id
   WHERE k.plugin_version IS NOT NULL
     AND (d.plugin_id IS NULL
          OR d.plugin_version IS DISTINCT FROM k.plugin_version
          OR (d.status = 'failed' AND d.declared_at < now() - make_interval(mins => p_retry_minutes)))
   ORDER BY d.declared_at NULLS FIRST, k.plugin_slug
   LIMIT p_limit;
END;
$$;

COMMENT ON FUNCTION public.list_plugins_to_declare(integer, integer) IS
  'Plugins to ignite (declare-only run → schedules): canary/ga, linked to an ACTIVE data source with a known owner (tenant), never declared / new version / failed and retry due. Service only.';

REVOKE ALL ON FUNCTION public.list_plugins_to_declare(integer, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.list_plugins_to_declare(integer, integer) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.list_plugins_to_declare(integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/list_project_vulnerabilities.sql
-- -----------------------------------------------------------------------------

/**
 * list_project_vulnerabilities — List vulnerability findings for a project.
 *
 * Called by vulnerability-aggregator edge function (service_role).
 * Returns JSON array of vulnerabilities matching filters.
 *
 * @param p_is_resolved boolean — Filter by resolved status (default false)
 * @param p_limit integer — Max rows to return (default 100)
 * @param p_project_slug text — Project slug to filter by
 */
CREATE OR REPLACE FUNCTION public.list_project_vulnerabilities(
  p_is_resolved boolean DEFAULT false,
  p_limit integer DEFAULT 100,
  p_project_slug text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF p_project_slug IS NULL THEN
    RAISE EXCEPTION 'p_project_slug is required';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      id,
      project_slug,
      package_name,
      severity,
      title,
      fixed_in,
      url,
      source,
      is_resolved,
      first_detected_at
    FROM public.project_vulnerabilities
    WHERE project_slug = p_project_slug
      AND is_resolved = p_is_resolved
    ORDER BY severity ASC, first_detected_at DESC
    LIMIT p_limit
  ) t;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.list_project_vulnerabilities(boolean, integer, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.list_project_vulnerabilities(boolean, integer, text)
  TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/list_story_knowledge_items.sql
-- -----------------------------------------------------------------------------

-- Function: public.list_story_knowledge_items
-- Description: Lists knowledge_items scoped to a story for the Phase 8
--   StoryKnowledgeTab UI. Returns items where story_id = p_story_id with
--   tag arrays, category, ingestion safety status, and basic metadata —
--   excludes body_markdown payload by default (use mcp_get_knowledge_item
--   for full body when an item is opened).
-- Security: SECURITY DEFINER. Admin/staff OR story_participants member OR
--   stack-default story — matches kanban_stories_view / story_timeline.

CREATE OR REPLACE FUNCTION public.list_story_knowledge_items(
  p_story_id uuid,
  p_include_archived boolean DEFAULT false
)
RETURNS TABLE (
  id                 uuid,
  item_type          text,
  title              text,
  summary            text,
  category           text,
  ai_context_tags    text[],
  status             text,
  visibility         text,
  version            int,
  author_display_name text,
  is_verified        boolean,
  quarantine_status  text,
  safety_score       numeric,
  created_at         timestamptz,
  updated_at         timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id  uuid := auth.uid();
  v_is_admin boolean := false;
BEGIN
  IF v_user_id IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  v_is_admin := public.is_admin_or_staff(v_user_id);

  IF NOT v_is_admin
     AND NOT EXISTS (
       SELECT 1 FROM public.partner_stories ps
       WHERE ps.id = p_story_id
         AND (
           ps.is_stack_default = true
           OR EXISTS (
             SELECT 1 FROM public.story_participants sp
             WHERE sp.story_id = ps.id AND sp.user_id = v_user_id
           )
         )
     )
  THEN
    RAISE EXCEPTION 'Access denied: story participant or admin/staff required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    ki.id,
    ki.item_type::text,
    ki.title,
    ki.summary,
    ki.category,
    COALESCE(ki.ai_context_tags, '{}'::text[]) AS ai_context_tags,
    ki.status,
    ki.visibility,
    ki.version,
    ki.author_display_name,
    ki.is_verified,
    ki.quarantine_status,
    ki.safety_score,
    ki.created_at,
    ki.updated_at
  FROM public.knowledge_items ki
  WHERE ki.story_id = p_story_id
    AND (p_include_archived OR ki.status NOT IN ('archived', 'deleted'))
  ORDER BY ki.updated_at DESC, ki.created_at DESC;
END;
$$;

REVOKE ALL ON FUNCTION public.list_story_knowledge_items(uuid, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.list_story_knowledge_items(uuid, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.list_story_knowledge_items(uuid, boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/list_workflow_statuses.sql
-- -----------------------------------------------------------------------------

-- Function: public.list_workflow_statuses
-- Description: Returns the active kanban lifecycle statuses in sort order.
--   Drives the kanban swimlane header layout and any UI dropdown that lets
--   a user pick a status. UI must use the returned `label_i18n_key` with
--   t() — never render `status` directly.
-- Security: SECURITY DEFINER; readable by any authenticated user (matches
--   RLS policy authenticated_can_read_workflow_statuses).
-- See also: workflow_statuses (table), get_allowed_kanban_transitions (RPC).

CREATE OR REPLACE FUNCTION public.list_workflow_statuses(
  p_include_inactive boolean DEFAULT false
)
RETURNS TABLE (
  status         text,
  label_i18n_key text,
  sort_order     int,
  swimlane_color text,
  is_terminal    boolean,
  is_active      boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT ws.status,
         ws.label_i18n_key,
         ws.sort_order,
         ws.swimlane_color,
         ws.is_terminal,
         ws.is_active
  FROM public.workflow_statuses ws
  WHERE (p_include_inactive OR ws.is_active = true)
  ORDER BY ws.sort_order ASC;
END;
$$;

REVOKE ALL ON FUNCTION public.list_workflow_statuses(boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.list_workflow_statuses(boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.list_workflow_statuses(boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/lock_tooling_proposal.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: lock_tooling_proposal
-- Popis: Admin manual edit guard — když admin ručně upraví AISHA-generated artifact,
--        nastaví manual_locked=true aby AISHA artifact znovu nepřepsala při dalším
--        cycle. "Lidský dotek" gate.
-- Volá: dashboard admin button, manual SQL by admin
-- Auth: admin only (changes AISHA's autonomous behavior)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.lock_tooling_proposal(
  p_artifact_path text,
  p_locked        boolean DEFAULT true
)
RETURNS public.aisha_tooling_proposals
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row public.aisha_tooling_proposals;
BEGIN
  -- Admin only (this changes AISHA's autonomous behavior)
  IF NOT public.is_user_admin() THEN
    RAISE EXCEPTION 'Admin role required';
  END IF;

  UPDATE public.aisha_tooling_proposals
  SET manual_locked = p_locked,
      updated_at = now()
  WHERE artifact_path = p_artifact_path
  RETURNING * INTO v_row;

  IF v_row IS NULL THEN
    RAISE EXCEPTION 'Proposal not found for path: %', p_artifact_path;
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'aisha_tooling_lock_changed',
    jsonb_build_object(
      'proposal_id', v_row.id,
      'artifact_path', p_artifact_path,
      'locked', p_locked
    )
  );

  RETURN v_row;
END;
$$;

REVOKE ALL ON FUNCTION public.lock_tooling_proposal(text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.lock_tooling_proposal(text, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.lock_tooling_proposal(text, boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/log_ai_trace_event.sql
-- -----------------------------------------------------------------------------

-- Source of Truth: log_ai_trace_event
-- Purpose: Log a trace event for an existing AI run. Requires p_run_id (non-NULL).
--          For n8n workflows that may not have a run_id, use log_n8n_trace_event() instead.
-- Used by: ai-chat edge function, internal RPC calls
-- Migration: 20260216_aisha_phase3_router.sql (original)
-- See also: log_n8n_trace_event.sql (wrapper that auto-creates runs)

CREATE OR REPLACE FUNCTION public.log_ai_trace_event(
  p_run_id uuid,
  p_event_type text,
  p_agent_slug text DEFAULT NULL::text,
  p_provider text DEFAULT NULL::text,
  p_operation text DEFAULT NULL::text,
  p_status text DEFAULT 'ok'::text,
  p_duration_ms integer DEFAULT NULL::integer,
  p_cost_json jsonb DEFAULT NULL::jsonb,
  p_request_summary jsonb DEFAULT NULL::jsonb,
  p_response_summary jsonb DEFAULT NULL::jsonb,
  p_error_json jsonb DEFAULT NULL::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO ai_trace_events (
    run_id, event_type, agent_slug, provider, operation,
    status, duration_ms, cost_json, request_summary, response_summary, error_json
  )
  VALUES (
    p_run_id, p_event_type::ai_event_type, p_agent_slug, p_provider, p_operation,
    p_status, p_duration_ms, p_cost_json, p_request_summary, p_response_summary, p_error_json
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.log_ai_trace_event(uuid, text, text, text, text, text, integer, jsonb, jsonb, jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.log_ai_trace_event(uuid, text, text, text, text, text, integer, jsonb, jsonb, jsonb, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.log_ai_trace_event(uuid, text, text, text, text, text, integer, jsonb, jsonb, jsonb, jsonb) TO service_role;


