-- File: aisha/db/sql/functions/log_knowledge_attribution.sql
-- -----------------------------------------------------------------------------

-- Function: log_knowledge_attribution
-- Purpose: AISHA logs which expert rules were used for a story and their relevance

CREATE OR REPLACE FUNCTION log_knowledge_attribution(
  p_story_id uuid,
  p_attributions jsonb  -- array of { rule_id, rule_owner_id, usage_intensity, relevance_score, quality_score, usage_context }
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid;
  v_count int := 0;
  v_attr jsonb;
  v_total_weight numeric;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Verify story exists
  IF NOT EXISTS (SELECT 1 FROM partner_stories WHERE id = p_story_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Story not found');
  END IF;

  -- Process each attribution
  FOR v_attr IN SELECT * FROM jsonb_array_elements(p_attributions)
  LOOP
    INSERT INTO knowledge_attribution (
      story_id,
      rule_id,
      author_id,
      usage_intensity,
      relevance_score,
      quality_score,
      attribution_weight,
      context_used
    ) VALUES (
      p_story_id,
      (v_attr->>'rule_id')::uuid,
      (v_attr->>'author_id')::uuid,
      COALESCE((v_attr->>'usage_intensity')::numeric, 1.0),
      COALESCE((v_attr->>'relevance_score')::numeric, 0.5),
      COALESCE((v_attr->>'quality_score')::numeric, 0.5),
      -- Composite weight: intensity * relevance * quality
      ROUND(
        COALESCE((v_attr->>'usage_intensity')::numeric, 1.0) *
        COALESCE((v_attr->>'relevance_score')::numeric, 0.5) *
        COALESCE((v_attr->>'quality_score')::numeric, 0.5),
        4
      ),
      COALESCE(v_attr->>'context_used', 'consultation')
    )
    ON CONFLICT (story_id, rule_id) DO UPDATE SET
      usage_intensity = EXCLUDED.usage_intensity,
      relevance_score = EXCLUDED.relevance_score,
      quality_score = EXCLUDED.quality_score,
      attribution_weight = EXCLUDED.attribution_weight,
      context_used = EXCLUDED.context_used,
      updated_at = now();

    v_count := v_count + 1;
  END LOOP;

  -- Normalize weights so they sum to 1.0 within this story
  SELECT COALESCE(SUM(attribution_weight), 0)
  INTO v_total_weight
  FROM knowledge_attribution
  WHERE story_id = p_story_id;

  IF v_total_weight > 0 THEN
    UPDATE knowledge_attribution
    SET attribution_weight = ROUND(attribution_weight / v_total_weight, 4)
    WHERE story_id = p_story_id;
  END IF;

  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'KNOWLEDGE_ATTRIBUTED',
    jsonb_build_object(
      'area', 'marketplace',
      'severity', 'info',
      'entity_type', 'knowledge_attribution',
      'story_id', p_story_id,
      'attributions_count', v_count
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'story_id', p_story_id,
    'attributions_logged', v_count
  );
END;
$$;

REVOKE ALL ON FUNCTION log_knowledge_attribution(uuid,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION log_knowledge_attribution(uuid,jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION log_knowledge_attribution(uuid,jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/log_n8n_trace_event.sql
-- -----------------------------------------------------------------------------

-- Source of Truth: log_n8n_trace_event
-- Wrapper for n8n workflows to log trace events with auto ai_run creation.
-- When p_run_id IS NULL, auto-creates an ai_run and uses that run_id.

CREATE OR REPLACE FUNCTION log_n8n_trace_event(
  p_event_type text,
  p_run_id uuid DEFAULT NULL,
  p_run_kind text DEFAULT 'chat',
  p_agent_slug text DEFAULT NULL,
  p_provider text DEFAULT NULL,
  p_operation text DEFAULT NULL,
  p_status text DEFAULT 'ok',
  p_duration_ms int DEFAULT NULL,
  p_cost_json jsonb DEFAULT NULL,
  p_request_summary jsonb DEFAULT NULL,
  p_response_summary jsonb DEFAULT NULL,
  p_error_json jsonb DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_run_id uuid;
  v_event_id uuid;
  v_run_created boolean := false;
BEGIN
  IF p_run_id IS NOT NULL THEN
    v_run_id := p_run_id;
  ELSE
    -- §16: platform/system run → platform sentinel story (ai_runs.story_id NOT NULL).
    INSERT INTO ai_runs (story_id, kind, status, metadata)
    VALUES (
      public.ensure_stack_default_story(),
      COALESCE(p_run_kind, 'chat'),
      'running',
      jsonb_build_object(
        'source', 'n8n',
        'agent_slug', COALESCE(p_agent_slug, 'unknown'),
        'auto_created', true
      )
    )
    RETURNING id INTO v_run_id;
    v_run_created := true;
  END IF;

  INSERT INTO ai_trace_events (
    run_id, event_type, agent_slug, provider, operation,
    status, duration_ms, cost_json, request_summary, response_summary, error_json
  )
  VALUES (
    v_run_id,
    p_event_type::ai_event_type,
    p_agent_slug,
    p_provider,
    p_operation,
    p_status,
    p_duration_ms,
    p_cost_json,
    p_request_summary,
    p_response_summary,
    p_error_json
  )
  RETURNING id INTO v_event_id;

  IF v_run_created THEN
    UPDATE ai_runs
    SET status = 'succeeded', finished_at = now()
    WHERE id = v_run_id;
  END IF;

  RETURN jsonb_build_object(
    'event_id', v_event_id,
    'run_id', v_run_id,
    'run_created', v_run_created
  );
END;
$$;

REVOKE ALL ON FUNCTION log_n8n_trace_event(text, uuid, text, text, text, text, text, integer, jsonb, jsonb, jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION log_n8n_trace_event(text, uuid, text, text, text, text, text, integer, jsonb, jsonb, jsonb, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION log_n8n_trace_event(text, uuid, text, text, text, text, text, integer, jsonb, jsonb, jsonb, jsonb) TO service_role;

COMMENT ON FUNCTION log_n8n_trace_event(text, uuid, text, text, text, text, text, integer, jsonb, jsonb, jsonb, jsonb) IS
  'Wrapper for n8n workflows to log trace events. Auto-creates ai_run when '
  'p_run_id is NULL. Returns { event_id, run_id, run_created }.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/log_permission_change.sql
-- -----------------------------------------------------------------------------

-- Function: public.log_permission_change
-- Arguments: (none)
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:27:55+01:00

CREATE OR REPLACE FUNCTION public.log_permission_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new jsonb;
  v_old jsonb;
BEGIN
  -- audit_logs may not exist yet during initial bootstrap/migrations.
  -- Never fail permission writes just because audit trail table is created later.
  IF to_regclass('public.audit_logs') IS NULL THEN
    IF TG_OP = 'INSERT' THEN
      RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_new := to_jsonb(NEW);
    INSERT INTO public.audit_logs (user_id, action, table_name, record_id, new_values)
    VALUES (
      auth.uid(),
      'grant_permission',
      TG_TABLE_NAME,
      COALESCE(v_new->>'id', NULL),
      jsonb_build_object(
        'role', v_new->>'role',
        'permission_id', v_new->>'permission_id',
        'section', v_new->>'section',
        'permission', v_new->>'permission'
      )
    );
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    v_old := to_jsonb(OLD);
    INSERT INTO public.audit_logs (user_id, action, table_name, record_id, old_values)
    VALUES (
      auth.uid(),
      'revoke_permission',
      TG_TABLE_NAME,
      COALESCE(v_old->>'id', NULL),
      jsonb_build_object(
        'role', v_old->>'role',
        'permission_id', v_old->>'permission_id',
        'section', v_old->>'section',
        'permission', v_old->>'permission'
      )
    );
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.log_permission_change() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.log_permission_change() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/log_security_event.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: log_security_event
--
-- OWASP A09 — append-only audit trail for security events emitted by orchestrator
-- services. Called from @aisha/security/audit.ts (createPostgrestAuditEmitter).
--
-- Distinct from log_integration_action which targets integration_services
-- bookkeeping (NocoDB/Langfuse): this one is for cross-cutting security
-- events (auth fail, MFA challenge, rate-limit hit, SSRF block, etc.) and
-- writes directly to audit_journal with area='security' and tags=['owasp', …].
--
-- Authorization:
--   - authenticated → may log events about their own session (actor=auth.uid())
--   - service_role  → may log events on behalf of any actor (n8n, services)
--   - anon          → only when service_role bridge passes through (rare)
--
-- Metadata is JSONB; callers are responsible for redacting PII upstream
-- (the @aisha/security logger applies redact() before transport).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.log_security_event(
  p_service     text,
  p_action      text,
  p_actor_id    uuid     DEFAULT NULL,
  p_target_type text     DEFAULT NULL,
  p_target_id   text     DEFAULT NULL,
  p_outcome     text     DEFAULT 'allow',
  p_reason      text     DEFAULT NULL,
  p_metadata    jsonb    DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id              uuid;
  v_is_service_role boolean;
  v_actor           uuid;
BEGIN
  -- Validate outcome enum (defensive: prevents free-form values from polluting
  -- the audit trail and breaking downstream dashboards / alert rules).
  IF p_outcome NOT IN ('allow', 'deny', 'error') THEN
    RAISE EXCEPTION 'log_security_event: invalid outcome %, expected allow|deny|error', p_outcome;
  END IF;

  v_is_service_role := (current_setting('request.jwt.claims', true)::jsonb->>'role') = 'service_role';

  -- service_role may log with any actor; authenticated users may only log
  -- events about themselves. This stops a compromised user JWT from forging
  -- audit entries for other principals.
  IF v_is_service_role THEN
    v_actor := COALESCE(p_actor_id, auth.uid());
  ELSE
    IF p_actor_id IS NOT NULL AND p_actor_id <> auth.uid() THEN
      RAISE EXCEPTION 'log_security_event: actor mismatch (caller=%, requested=%)',
        auth.uid(), p_actor_id;
    END IF;
    v_actor := auth.uid();
  END IF;

  INSERT INTO public.audit_journal (
    user_id,
    action,
    action_type,
    entity_type,
    entity_id,
    area,
    severity,
    summary,
    details,
    metadata,
    tags
  ) VALUES (
    v_actor,
    p_action,
    p_action,
    p_target_type,
    p_target_id,
    'security',
    CASE p_outcome WHEN 'deny' THEN 'warn' WHEN 'error' THEN 'error' ELSE 'info' END,
    p_reason,
    jsonb_build_object(
      'service',  p_service,
      'outcome',  p_outcome,
      'reason',   p_reason
    ),
    p_metadata,
    ARRAY['owasp', p_outcome, p_service]
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.log_security_event(text, text, uuid, text, text, text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.log_security_event(text, text, uuid, text, text, text, text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.log_security_event(text, text, uuid, text, text, text, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/ma_plny_pristup_k_datum.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: ma_plny_pristup_k_datum
-- Popis: Má uživatel od správy udělený PLNÝ přístup k datům (zdroj `vse:*`)?
--        ⭐ Majitel 2026-09-28: „pokud mám přístup do dané sekce, měl bych vidět veškerý
--        obsah, ke kterému mám právo… rád bych dal možnost bez omezení, ne s výběrem toho,
--        kdo se o daného nájemce stará; možnost omezit chceme zachovat". Plný přístup =
--        všechny doklady a dvojčata (smlouvy, agendy, jednotky, nájemci) — ale ne správa:
--        sekce se dál udělují zvlášť, administrace zůstává rolím.
--        Množinový/InitPlan člen čtecích politik registru a dvojčat (jedno vyhodnocení
--        za dotaz, ne per řádek).
-- Bezpečnost: SECURITY DEFINER (data_source_grants nemá granty pro authenticated) +
--        oracle guard: přihlášený se ptá jen na SEBE; služba a správa za kohokoli.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.ma_plny_pristup_k_datum(p_uid uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
  SELECT p_uid IS NOT NULL
     AND (p_uid = auth.uid() OR public.is_service_role() OR public.is_admin_or_staff())
     AND EXISTS (SELECT 1 FROM public.data_source_grants g
                  WHERE g.user_id = p_uid AND g.zdroj = 'vse:*');
$$;

REVOKE ALL ON FUNCTION public.ma_plny_pristup_k_datum(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.ma_plny_pristup_k_datum(uuid) TO authenticated, service_role;
COMMENT ON FUNCTION public.ma_plny_pristup_k_datum(uuid) IS
  'Plný přístup k datům udělený správou (data_source_grants vse:*) — člen čtecích politik registru a dvojčat; ne správa. Oracle guard: jen vlastní účet.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/ma_zdroj_dat.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: ma_zdroj_dat
-- Popis: Má uživatel od správy udělený ASPOŇ JEDEN zdroj dat (data_source_grants)?
--        Člen čtecí politiky katalogu parametrů dvojčat: popisky sloupců registru
--        (jednotky, nájemci) potřebuje každý, komu správa nějaký zdroj dat udělila —
--        jinak by registr z uděleného zdroje ukázal řádky bez sloupců.
-- Bezpečnost: SECURITY DEFINER (data_source_grants nemá granty pro authenticated) +
--        oracle guard: přihlášený se ptá jen na SEBE; služba a správa za kohokoli.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.ma_zdroj_dat(p_uid uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
  SELECT p_uid IS NOT NULL
     AND (p_uid = auth.uid() OR public.is_service_role() OR public.is_admin_or_staff())
     AND EXISTS (SELECT 1 FROM public.data_source_grants g WHERE g.user_id = p_uid);
$$;

REVOKE ALL ON FUNCTION public.ma_zdroj_dat(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.ma_zdroj_dat(uuid) TO authenticated, service_role;
COMMENT ON FUNCTION public.ma_zdroj_dat(uuid) IS
  'Má uživatel udělený aspoň jeden zdroj dat (data_source_grants)? Člen čtecí politiky katalogu parametrů dvojčat. Oracle guard: jen vlastní účet.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/manage_guild_member_expertise.sql
-- -----------------------------------------------------------------------------

-- Function: public.manage_guild_member_expertise
-- Arguments: p_expertise_entries jsonb
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.manage_guild_member_expertise(p_expertise_entries jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id uuid;
  v_partner_id uuid;
  v_entry jsonb;
  v_area_id uuid;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT id INTO v_partner_id
  FROM partner_profiles WHERE user_id = v_caller_id;

  IF v_partner_id IS NULL THEN
    RAISE EXCEPTION 'Only partners can manage expertise';
  END IF;

  -- Remove all current entries
  DELETE FROM guild_member_expertise WHERE partner_id = v_partner_id;

  -- Insert new entries
  FOR v_entry IN SELECT * FROM jsonb_array_elements(p_expertise_entries)
  LOOP
    SELECT id INTO v_area_id
    FROM guild_expertise_areas WHERE slug = v_entry->>'expertise_area_slug' AND is_active = true;

    IF v_area_id IS NOT NULL THEN
      INSERT INTO guild_member_expertise (
        partner_id, expertise_area_id, proficiency_level, years_experience,
        description, is_primary
      ) VALUES (
        v_partner_id,
        v_area_id,
        COALESCE((v_entry->>'proficiency_level')::int, 1),
        (v_entry->>'years_experience')::int,
        v_entry->>'description',
        COALESCE((v_entry->>'is_primary')::boolean, false)
      );
    END IF;
  END LOOP;

  -- Audit
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (v_caller_id, 'GUILD_EXPERTISE_UPDATE', jsonb_build_object(
    'area', 'knowledge', 'severity', 'info', 'partner_id', v_partner_id
  ));

  RETURN true;
END;
$function$;

REVOKE ALL ON FUNCTION public.manage_guild_member_expertise(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.manage_guild_member_expertise(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.manage_guild_member_expertise(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mark_all_notifications_read.sql
-- -----------------------------------------------------------------------------

-- Function: public.mark_all_notifications_read
-- Arguments: (none)
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:27:56+01:00

CREATE OR REPLACE FUNCTION public.mark_all_notifications_read()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_count INTEGER;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  UPDATE notifications
  SET is_read = true
  WHERE user_id = v_user_id
    AND is_read = false;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN json_build_object('success', true, 'count', v_count);
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.mark_all_notifications_read() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mark_all_notifications_read() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mark_drift_pending_approval.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: mark_drift_pending_approval
-- Popis: Linkuje drift_state row na approval request (z WF_APPROVAL_GATE) přes
--        approval_id. Změní remediation na 'approval_pending'.
-- Volá: WF_DRIFT_OBSERVER pro high/critical risk drifty
-- Auth: service_role nebo admin/staff
-- ============================================================================

CREATE OR REPLACE FUNCTION public.mark_drift_pending_approval(
  p_drift_id    uuid,
  p_approval_id uuid
)
RETURNS public.drift_state
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row public.drift_state;
  v_is_service boolean;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  UPDATE public.drift_state
  SET remediation = 'approval_pending',
      approval_id = p_approval_id
  WHERE id = p_drift_id
    AND resolved_at IS NULL
  RETURNING * INTO v_row;

  IF v_row IS NULL THEN
    RAISE EXCEPTION 'Drift % not found or already resolved', p_drift_id;
  END IF;

  RETURN v_row;
END;
$$;

REVOKE ALL ON FUNCTION public.mark_drift_pending_approval(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mark_drift_pending_approval(uuid, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.mark_drift_pending_approval(uuid, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mark_models_unavailable.sql
-- -----------------------------------------------------------------------------

-- Function: mark_models_unavailable
--
-- Dostupnost modelu je vlastnost ŽIVÉHO listingu providera: co v jeho ÚPLNÉM seznamu
-- (/v1/models) není, se neobsluhuje. Volá svc-ai-chat discovery (modelDiscovery.ts)
-- jen nad listingem, který backend výslovně označil jako úplný — stránkovaný nebo
-- nedostupný listing dostupnost NEMĚŘÍ a sem nedojde. Zpět na dostupný vrací model
-- upsert_discovered_model, jakmile se v listingu znovu objeví.
--
-- ⛔ NAMĚŘENO 2026-09-13: funkci nevolal nikdo, takže seedované vLLM řádky, které nic
-- neobsluhovalo, zůstávaly is_available=true a resolver je nabízel.
--
-- Audit: zmizení modelu z nabídky resolveru je rozhodnutí se stopou (kolik, u koho),
-- ne tichá změna — bez PII, jen provider a počet.

CREATE OR REPLACE FUNCTION public.mark_models_unavailable(p_provider text, p_available_model_ids text[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
BEGIN
  IF NOT (
    public.is_service_role()
    OR is_admin_or_staff()
  ) THEN
    RAISE EXCEPTION 'Service role or admin required';
  END IF;

  -- NULL seznam není „nic se neobsluhuje", je to nezměřeno — `!= ALL(NULL)` by
  -- nic neoznačilo, ale tiché no-op by vypadalo jako úspěch. Hlasitě.
  IF p_provider IS NULL OR p_available_model_ids IS NULL THEN
    RAISE EXCEPTION 'p_provider and p_available_model_ids are required (empty array = provider serves nothing)';
  END IF;

  UPDATE ai_model_registry
  SET is_available = false
  WHERE provider = p_provider
    AND model_id != ALL(p_available_model_ids)
    AND is_available = true;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF v_count > 0 THEN
    INSERT INTO public.audit_journal (user_id, action, metadata)
    VALUES (
      auth.uid(),
      'models_marked_unavailable',
      jsonb_build_object(
        'provider', p_provider,
        'marked_unavailable', v_count,
        'listed_models', cardinality(p_available_model_ids),
        'source', 'live_listing'
      )
    );
  END IF;

  RETURN v_count;
END;
$function$;

REVOKE ALL ON FUNCTION mark_models_unavailable(p_provider text, p_available_model_ids text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mark_models_unavailable(text,text[]) TO authenticated;
GRANT EXECUTE ON FUNCTION mark_models_unavailable(text,text[]) TO service_role;


