-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/materialize_agent_runtime.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: materialize_agent_runtime
-- Purpose: Turn an APPROVED declarative marketplace agent (plugin_catalog
--          kind='agent', with agent_spec) into a routable runtime identity:
--          one idempotent agent_catalog row + its global expert_rule bindings.
--          After this, route_task can route to the agent's slug (call-mode) and
--          mcp_get_agent_knowledge surfaces its rules.
--
-- Called from the approve gates (fn_aisha_kb_decision / review_moderation_item
-- agent branches) in the same txn that flips plugin_catalog.status → 'canary',
-- so the catalog row lands atomically with approval — no orphan window.
--
-- Idempotent: re-approve / canary→ga converge on exactly one catalog row +
-- one set of global rule bindings. Executable agents (agent_spec IS NULL,
-- Phase 2) are skipped. A marketplace agent can NEVER overwrite a built-in
-- system agent (source_plugin_id IS NULL) — the ON CONFLICT guard refuses it.
-- Security: SECURITY DEFINER, service_role only (called from service-context gates).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.materialize_agent_runtime(p_plugin_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_pc            record;
  v_spec          jsonb;
  v_model         text;
  v_catalog_id    uuid;
  v_rule_slug     text;
  v_rule_id       uuid;
  v_binding_count int := 0;
  v_audit_user    uuid;
BEGIN
  SELECT id, slug, name, description, agent_spec, kind, author_partner_id
    INTO v_pc
    FROM public.plugin_catalog
   WHERE id = p_plugin_id;

  IF v_pc.id IS NULL THEN
    RAISE EXCEPTION 'Plugin not found: %', p_plugin_id USING ERRCODE = 'P0002';
  END IF;
  IF v_pc.kind <> 'agent' THEN
    RAISE EXCEPTION 'Plugin % is not an agent', p_plugin_id USING ERRCODE = 'P0002';
  END IF;

  v_spec := v_pc.agent_spec;
  -- Declarative agents only. Executable/call-mode agents carry no agent_spec
  -- (Phase 2 — runner-based execution, not a route_task persona).
  IF v_spec IS NULL THEN
    RETURN jsonb_build_object('skipped', 'no agent_spec (executable/call-mode)', 'agent_slug', v_pc.slug);
  END IF;

  -- default_model MUST be a router model KEY (the router maps it to a provider
  -- model); marketplace authors may not pin raw provider ids. Coerce unknowns.
  v_model := COALESCE(v_spec->>'default_model', 'balanced');
  IF v_model NOT IN ('fast', 'balanced', 'maxQuality') THEN
    v_model := 'balanced';
  END IF;

  -- Upsert the runtime row, keyed on slug. The WHERE guard means a conflict on
  -- a row we don't own (a system agent with source_plugin_id IS NULL, or another
  -- plugin's row) does NOT update → RETURNING NULL → we refuse below.
  INSERT INTO public.agent_catalog (
    slug, display_name, purpose, default_model, model_overrides,
    allowed_tools, denied_tools, default_context_profile, max_loops,
    safety_level, autonomy_level, is_active, source_plugin_id
  ) VALUES (
    v_pc.slug,
    COALESCE(v_pc.name, 'Agent: ' || v_pc.slug),
    COALESCE(v_spec->>'purpose', v_pc.description, 'Marketplace agent'),
    v_model,
    COALESCE(v_spec->'model_overrides', '{}'::jsonb),
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_spec->'allowed_tools', '[]'::jsonb))),
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_spec->'denied_tools', '[]'::jsonb))),
    COALESCE(v_spec->>'context_profile', 'repo_plus_rules'),
    COALESCE((v_spec->>'max_loops')::int, 3),
    COALESCE(v_spec->>'safety_level', 'standard'),
    COALESCE(v_spec->>'autonomy_level', 'semi'),
    true,
    p_plugin_id
  )
  ON CONFLICT (slug) DO UPDATE SET
    display_name            = EXCLUDED.display_name,
    purpose                 = EXCLUDED.purpose,
    default_model           = EXCLUDED.default_model,
    model_overrides         = EXCLUDED.model_overrides,
    allowed_tools           = EXCLUDED.allowed_tools,
    denied_tools            = EXCLUDED.denied_tools,
    default_context_profile = EXCLUDED.default_context_profile,
    max_loops               = EXCLUDED.max_loops,
    safety_level            = EXCLUDED.safety_level,
    autonomy_level          = EXCLUDED.autonomy_level,
    is_active               = true,
    source_plugin_id        = p_plugin_id,
    updated_at              = now()
  WHERE public.agent_catalog.source_plugin_id = p_plugin_id
  RETURNING id INTO v_catalog_id;

  IF v_catalog_id IS NULL THEN
    RAISE EXCEPTION 'Agent slug % collides with a built-in/other agent — refusing to overwrite', v_pc.slug
      USING ERRCODE = '42501';
  END IF;

  -- Rebuild this agent's GLOBAL rule bindings from agent_spec.rule_slugs
  -- (idempotent re-derive). Direct insert — set_agent_knowledge_binding_audited
  -- is admin-gated and would reject the service-context caller.
  --
  -- Delete ONLY the active rows we own — a binding an operator soft-disabled
  -- (is_active=false) is deliberately left intact so a canary→ga (or any
  -- re-)materialization never silently resurrects it.
  DELETE FROM public.agent_knowledge_bindings
   WHERE agent_slug = v_pc.slug AND story_id IS NULL AND binding_type = 'rule'
     AND is_active = true;

  FOR v_rule_slug IN
    SELECT jsonb_array_elements_text(COALESCE(v_spec->'rule_slugs', '[]'::jsonb))
  LOOP
    SELECT id INTO v_rule_id
      FROM public.expert_rules
     WHERE slug = v_rule_slug AND status = 'published'
     LIMIT 1;
    -- Insert only if no binding remains for this rule — i.e. skip rules an
    -- operator soft-disabled (their is_active=false row survived the DELETE),
    -- so re-materialization respects the kill of an individual binding.
    IF v_rule_id IS NOT NULL
       AND NOT EXISTS (
         SELECT 1 FROM public.agent_knowledge_bindings
          WHERE agent_slug = v_pc.slug AND knowledge_item_id = v_rule_id
            AND story_id IS NULL AND binding_type = 'rule'
       )
    THEN
      INSERT INTO public.agent_knowledge_bindings
        (agent_slug, knowledge_item_id, binding_type, priority, is_active, story_id, notes)
      VALUES
        (v_pc.slug, v_rule_id, 'rule', 100, true, NULL, 'materialized from marketplace agent');
      v_binding_count := v_binding_count + 1;
    END IF;
    -- stale/unpublished slugs are skipped, never fatal
  END LOOP;

  -- Audit (service context: auth.uid() may be NULL → fall back to the author;
  -- NULL is FK-safe per audit-journal-actor-no-fk-sentinel gate).
  v_audit_user := auth.uid();
  IF v_audit_user IS NULL AND v_pc.author_partner_id IS NOT NULL THEN
    SELECT pp.user_id INTO v_audit_user
      FROM public.partner_profiles pp WHERE pp.id = v_pc.author_partner_id;
  END IF;
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_audit_user, 'AGENT_RUNTIME_MATERIALIZED', jsonb_build_object(
    'area', 'marketplace', 'severity', 'info',
    'plugin_id', p_plugin_id, 'agent_slug', v_pc.slug,
    'catalog_id', v_catalog_id, 'binding_count', v_binding_count,
    'default_model', v_model
  ));

  RETURN jsonb_build_object(
    'agent_slug', v_pc.slug,
    'catalog_id', v_catalog_id,
    'binding_count', v_binding_count
  );
END;
$$;

COMMENT ON FUNCTION public.materialize_agent_runtime(uuid) IS
  'Materialize an approved declarative marketplace agent into a routable agent_catalog row + rule bindings. Idempotent; service_role only.';

REVOKE ALL ON FUNCTION public.materialize_agent_runtime(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.materialize_agent_runtime(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/materialize_auth_provider.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: materialize_auth_provider
-- Purpose: Turn an APPROVED plugin (kind='auth_provider', auth_spec) into an
--          auth_provider_registry row the Keycloak admin-API reconciler reads.
--
-- DELIBERATE ASYMMETRY vs materialize_backend_provider: the row lands with
-- is_enabled=false. An identity provider is an INBOUND TRUST boundary — who may
-- log in — and a marketplace approval must not widen it by itself; the operator
-- enables the row (and thereby the reconciler creates the Keycloak IdP). A
-- backend provider is an outbound egress choice guarded by health+admission,
-- so it may enable on approval. Same reasoning applies to web_tracking
-- (privacy boundary).
--
-- Secrets: auth_spec carries client_secret_env_var — the env var NAME. The
-- secret value never enters the DB.
-- Idempotent; ownership-guarded; SECURITY DEFINER, service_role only.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.materialize_auth_provider(p_plugin_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_pc          record;
  v_spec        jsonb;
  v_protocol    text;
  v_scope       uuid;
  v_registry_id uuid;
  v_audit_user  uuid;
BEGIN
  SELECT id, slug, name, description, auth_spec, kind, author_partner_id
    INTO v_pc
    FROM public.plugin_catalog
   WHERE id = p_plugin_id;

  IF v_pc.id IS NULL THEN
    RAISE EXCEPTION 'Plugin not found: %', p_plugin_id USING ERRCODE = 'P0002';
  END IF;
  IF v_pc.kind <> 'auth_provider' THEN
    RAISE EXCEPTION 'Plugin % is not an auth_provider', p_plugin_id USING ERRCODE = 'P0002';
  END IF;

  v_spec := v_pc.auth_spec;
  IF v_spec IS NULL THEN
    RETURN jsonb_build_object('skipped', 'no auth_spec', 'plugin_slug', v_pc.slug);
  END IF;

  v_protocol := v_spec->>'protocol';
  IF v_protocol IS NULL OR v_protocol NOT IN ('oidc','oauth2','saml','ldap') THEN
    RAISE EXCEPTION 'auth_spec.protocol invalid for plugin %: %', v_pc.slug, v_protocol
      USING ERRCODE = '22023';
  END IF;

  v_scope := CASE
    WHEN COALESCE((v_spec->>'global')::boolean, false) THEN NULL
    ELSE NULLIF(current_setting('aisha.instance_id', true), '')::uuid
  END;

  INSERT INTO public.auth_provider_registry (
    slug, display_name, protocol, issuer_url, client_id, client_secret_env_var,
    config, priority, is_enabled, scoped_to_instance_id, source_plugin_id, metadata
  ) VALUES (
    v_pc.slug,
    COALESCE(v_spec->>'display_name', v_pc.name, 'IdP: ' || v_pc.slug),
    v_protocol,
    v_spec->>'issuer_url',
    v_spec->>'client_id',
    v_spec->>'client_secret_env_var',
    COALESCE(v_spec->'config', '{}'::jsonb),
    COALESCE((v_spec->>'priority')::int, 100),
    false,  -- trust boundary: operator enables, approval only declares
    v_scope,
    p_plugin_id,
    COALESCE(v_spec->'metadata', '{}'::jsonb)
  )
  ON CONFLICT (slug) DO UPDATE SET
    display_name          = EXCLUDED.display_name,
    protocol              = EXCLUDED.protocol,
    issuer_url            = EXCLUDED.issuer_url,
    client_id             = EXCLUDED.client_id,
    client_secret_env_var = EXCLUDED.client_secret_env_var,
    config                = EXCLUDED.config,
    priority              = EXCLUDED.priority,
    -- is_enabled deliberately NOT touched: re-approval never re-arms a
    -- provider the operator disabled (kill-switch survives re-materialization,
    -- same posture as the agent bindings' soft-disable survival).
    scoped_to_instance_id = EXCLUDED.scoped_to_instance_id,
    source_plugin_id      = p_plugin_id,
    metadata              = EXCLUDED.metadata,
    updated_at            = now()
  WHERE public.auth_provider_registry.source_plugin_id = p_plugin_id
  RETURNING id INTO v_registry_id;

  IF v_registry_id IS NULL THEN
    RAISE EXCEPTION 'IdP slug % collides with an operator-declared/other provider — refusing to overwrite', v_pc.slug
      USING ERRCODE = '42501';
  END IF;

  v_audit_user := auth.uid();
  IF v_audit_user IS NULL AND v_pc.author_partner_id IS NOT NULL THEN
    SELECT pp.user_id INTO v_audit_user
      FROM public.partner_profiles pp WHERE pp.id = v_pc.author_partner_id;
  END IF;
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_audit_user, 'AUTH_PROVIDER_MATERIALIZED', jsonb_build_object(
    'area', 'marketplace', 'severity', 'info',
    'plugin_id', p_plugin_id, 'idp_slug', v_pc.slug,
    'registry_id', v_registry_id, 'protocol', v_protocol,
    'enabled', false
  ));

  RETURN jsonb_build_object('idp_slug', v_pc.slug, 'registry_id', v_registry_id, 'enabled', false);
END;
$$;

COMMENT ON FUNCTION public.materialize_auth_provider(uuid) IS
  'Materialize an approved auth_provider plugin into auth_provider_registry, DISABLED (trust boundary — operator enables). Idempotent; ownership-guarded; service_role only.';

REVOKE ALL ON FUNCTION public.materialize_auth_provider(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.materialize_auth_provider(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/materialize_automation_node.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: materialize_automation_node
-- Purpose: Turn an APPROVED plugin (kind='automation_node', node_spec) into a
--          custom_node_registry row — the same registry the NodeFactory path
--          writes, so both authoring routes converge on ONE inventory and the
--          n8n provision job (the consumer) reads ONE list to deploy.
--
-- Called from materialize_plugin (the kind dispatcher) inside the approval txn.
-- deployed_to_n8n stays false here: materialization declares; the provision
-- pipeline deploys and flips the flag (separate verb, separate actor).
-- Idempotent on (node_name, version); ownership-guarded via source_plugin_id.
-- Security: SECURITY DEFINER, service_role only.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.materialize_automation_node(p_plugin_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_pc          record;
  v_spec        jsonb;
  v_node_name   text;
  v_version     text;
  v_registry_id uuid;
  v_audit_user  uuid;
BEGIN
  SELECT id, slug, name, description, node_spec, kind, author_partner_id
    INTO v_pc
    FROM public.plugin_catalog
   WHERE id = p_plugin_id;

  IF v_pc.id IS NULL THEN
    RAISE EXCEPTION 'Plugin not found: %', p_plugin_id USING ERRCODE = 'P0002';
  END IF;
  IF v_pc.kind <> 'automation_node' THEN
    RAISE EXCEPTION 'Plugin % is not an automation_node', p_plugin_id USING ERRCODE = 'P0002';
  END IF;

  v_spec := v_pc.node_spec;
  IF v_spec IS NULL THEN
    RETURN jsonb_build_object('skipped', 'no node_spec', 'plugin_slug', v_pc.slug);
  END IF;

  v_node_name := COALESCE(v_spec->>'node_name', v_pc.slug);
  v_version   := COALESCE(v_spec->>'version', '0.1.0');

  INSERT INTO public.custom_node_registry (
    node_name, display_name, version, description, category,
    package_json, n8n_node_type, is_active, deployed_to_n8n, source_plugin_id
  ) VALUES (
    v_node_name,
    COALESCE(v_spec->>'display_name', v_pc.name, 'Node: ' || v_node_name),
    v_version,
    COALESCE(v_spec->>'description', v_pc.description),
    COALESCE(v_spec->>'category', 'aisha'),
    v_spec->'package_json',
    v_spec->>'n8n_node_type',
    true,
    false,
    p_plugin_id
  )
  ON CONFLICT (node_name, version) DO UPDATE SET
    display_name    = EXCLUDED.display_name,
    description     = EXCLUDED.description,
    category        = EXCLUDED.category,
    package_json    = EXCLUDED.package_json,
    n8n_node_type   = EXCLUDED.n8n_node_type,
    is_active       = true,
    source_plugin_id = p_plugin_id,
    updated_at      = now()
  WHERE public.custom_node_registry.source_plugin_id = p_plugin_id
  RETURNING id INTO v_registry_id;

  IF v_registry_id IS NULL THEN
    RAISE EXCEPTION 'Node %@% collides with a factory/other plugin node — refusing to overwrite', v_node_name, v_version
      USING ERRCODE = '42501';
  END IF;

  v_audit_user := auth.uid();
  IF v_audit_user IS NULL AND v_pc.author_partner_id IS NOT NULL THEN
    SELECT pp.user_id INTO v_audit_user
      FROM public.partner_profiles pp WHERE pp.id = v_pc.author_partner_id;
  END IF;
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_audit_user, 'AUTOMATION_NODE_MATERIALIZED', jsonb_build_object(
    'area', 'marketplace', 'severity', 'info',
    'plugin_id', p_plugin_id, 'node_name', v_node_name, 'version', v_version,
    'registry_id', v_registry_id
  ));

  RETURN jsonb_build_object('node_name', v_node_name, 'version', v_version, 'registry_id', v_registry_id);
END;
$$;

COMMENT ON FUNCTION public.materialize_automation_node(uuid) IS
  'Materialize an approved automation_node plugin into custom_node_registry (deploy flag stays with the provision pipeline). Idempotent; ownership-guarded; service_role only.';

REVOKE ALL ON FUNCTION public.materialize_automation_node(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.materialize_automation_node(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/materialize_backend_provider.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: materialize_backend_provider
-- Purpose: Turn an APPROVED plugin (kind='backend_provider', provider_spec)
--          into a resolver-visible ai_provider_registry row. After this,
--          aisha_resolve_clow_backend can route capability-needing work to it —
--          the declared capability reaches the far end of the spine instead of
--          dying as a catalog row (the pre-2026-07-26 state: 6 kinds declared,
--          1 materializer).
--
-- Called from materialize_plugin (the kind dispatcher) inside the approval txn.
-- Secrets: provider_spec carries auth_env_var — the NAME of the env var, never
-- a secret value (same contract as operator-declared providers).
-- Scoping: by default the row is scoped to the current instance
-- (aisha.instance_id); provider_spec.global=true opts into a base/global row.
-- Idempotent: re-approval converges on one row. Ownership guard: the ON
-- CONFLICT update only touches a row this plugin already owns — a slug
-- collision with a built-in or another plugin's provider REFUSES loudly.
-- Security: SECURITY DEFINER, service_role only.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.materialize_backend_provider(p_plugin_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_pc          record;
  v_spec        jsonb;
  v_backend     text;
  v_scope       uuid;
  v_registry_id uuid;
  v_audit_user  uuid;
BEGIN
  SELECT id, slug, name, description, provider_spec, kind, author_partner_id
    INTO v_pc
    FROM public.plugin_catalog
   WHERE id = p_plugin_id;

  IF v_pc.id IS NULL THEN
    RAISE EXCEPTION 'Plugin not found: %', p_plugin_id USING ERRCODE = 'P0002';
  END IF;
  IF v_pc.kind <> 'backend_provider' THEN
    RAISE EXCEPTION 'Plugin % is not a backend_provider', p_plugin_id USING ERRCODE = 'P0002';
  END IF;

  v_spec := v_pc.provider_spec;
  -- Honest degradation, never guessing: a provider with no spec is skipped with
  -- a note. We deliberately do NOT reverse-engineer endpoints out of
  -- config_schema — the spec IS the materialization contract.
  IF v_spec IS NULL THEN
    RETURN jsonb_build_object('skipped', 'no provider_spec', 'plugin_slug', v_pc.slug);
  END IF;

  -- backend_kind has no safe default (it selects the dispatch path); a wrong
  -- value would silently route calls down the wrong client. Fail loud instead.
  v_backend := v_spec->>'backend_kind';
  IF v_backend IS NULL OR v_backend NOT IN ('direct_cloud','llm_gateway','local_ollama','local_vllm','mcp_server') THEN
    RAISE EXCEPTION 'provider_spec.backend_kind invalid for plugin %: %', v_pc.slug, v_backend
      USING ERRCODE = '22023';
  END IF;

  -- Default = scoped to the current instance (small blast radius); an explicit
  -- "global": true publishes a base row visible to every instance.
  v_scope := CASE
    WHEN COALESCE((v_spec->>'global')::boolean, false) THEN NULL
    ELSE NULLIF(current_setting('aisha.instance_id', true), '')::uuid
  END;

  INSERT INTO public.ai_provider_registry (
    slug, display_name, backend_kind, endpoint_url, health_url,
    auth_kind, auth_env_var,
    supports_chat, supports_tool_use, supports_vision, supports_batch, supports_streaming,
    cost_class, is_enabled, scoped_to_instance_id, source_plugin_id, metadata
  ) VALUES (
    v_pc.slug,
    COALESCE(v_spec->>'display_name', v_pc.name, 'Provider: ' || v_pc.slug),
    v_backend,
    v_spec->>'endpoint_url',
    v_spec->>'health_url',
    COALESCE(v_spec->>'auth_kind', 'bearer'),
    v_spec->>'auth_env_var',
    COALESCE((v_spec->>'supports_chat')::boolean, true),
    COALESCE((v_spec->>'supports_tool_use')::boolean, false),
    COALESCE((v_spec->>'supports_vision')::boolean, false),
    COALESCE((v_spec->>'supports_batch')::boolean, false),
    COALESCE((v_spec->>'supports_streaming')::boolean, true),
    COALESCE(v_spec->>'cost_class', 'standard'),
    true,
    v_scope,
    p_plugin_id,
    COALESCE(v_spec->'metadata', '{}'::jsonb)
  )
  ON CONFLICT (slug) DO UPDATE SET
    display_name       = EXCLUDED.display_name,
    backend_kind       = EXCLUDED.backend_kind,
    endpoint_url       = EXCLUDED.endpoint_url,
    health_url         = EXCLUDED.health_url,
    auth_kind          = EXCLUDED.auth_kind,
    auth_env_var       = EXCLUDED.auth_env_var,
    supports_chat      = EXCLUDED.supports_chat,
    supports_tool_use  = EXCLUDED.supports_tool_use,
    supports_vision    = EXCLUDED.supports_vision,
    supports_batch     = EXCLUDED.supports_batch,
    supports_streaming = EXCLUDED.supports_streaming,
    cost_class         = EXCLUDED.cost_class,
    is_enabled         = true,
    scoped_to_instance_id = EXCLUDED.scoped_to_instance_id,
    source_plugin_id   = p_plugin_id,
    metadata           = EXCLUDED.metadata,
    updated_at         = now()
  WHERE public.ai_provider_registry.source_plugin_id = p_plugin_id
  RETURNING id INTO v_registry_id;

  IF v_registry_id IS NULL THEN
    RAISE EXCEPTION 'Provider slug % collides with a built-in/other provider — refusing to overwrite', v_pc.slug
      USING ERRCODE = '42501';
  END IF;

  v_audit_user := auth.uid();
  IF v_audit_user IS NULL AND v_pc.author_partner_id IS NOT NULL THEN
    SELECT pp.user_id INTO v_audit_user
      FROM public.partner_profiles pp WHERE pp.id = v_pc.author_partner_id;
  END IF;
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_audit_user, 'BACKEND_PROVIDER_MATERIALIZED', jsonb_build_object(
    'area', 'marketplace', 'severity', 'info',
    'plugin_id', p_plugin_id, 'provider_slug', v_pc.slug,
    'registry_id', v_registry_id, 'backend_kind', v_backend,
    'scoped_to_instance_id', v_scope
  ));

  RETURN jsonb_build_object('provider_slug', v_pc.slug, 'registry_id', v_registry_id);
END;
$$;

COMMENT ON FUNCTION public.materialize_backend_provider(uuid) IS
  'Materialize an approved backend_provider plugin into a resolver-visible ai_provider_registry row. Idempotent; ownership-guarded; service_role only.';

REVOKE ALL ON FUNCTION public.materialize_backend_provider(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.materialize_backend_provider(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/materialize_data_source.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: materialize_data_source
-- Purpose: Turn an APPROVED plugin (kind='data_source', source_spec) into an
--          agent_knowledge_sources row — the ingest spine's source registry.
--          This is the missing verb of the umbrella model: the machinery
--          (source-broker plugin host, IDataSource lifecycle, story bindings)
--          exists; what was missing was the registration that makes a
--          connector a first-class, resolver-visible source.
--
-- The row lands is_active=false BY CONSTRUCTION: agent_knowledge_sources'
-- activation guard requires the full 4D classification (data_sensitivity,
-- legal_basis, owner, retention — Source Onboarding Contract) which is
-- instance DATA, not plugin code. The plugin declares WHAT it can read
-- (adapter entry, namespace, default config); the instance classifies and
-- binds credentials, then activates. Fail-closed onboarding is preserved.
--
-- The adapter itself is loaded by svc-source-broker's plugin host from the
-- entry path recorded here (config.adapter_entry) — in-process IDataSource,
-- deliberately NOT the https-only compute sandbox (see plugin-host.ts).
-- Idempotent; ownership-guarded; SECURITY DEFINER, service_role only.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.materialize_data_source(p_plugin_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_pc          record;
  v_spec        jsonb;
  v_source_slug text;
  v_namespace   text;
  v_config      jsonb;
  v_registry_id uuid;
  v_audit_user  uuid;
BEGIN
  SELECT id, slug, name, description, source_spec, kind, author_partner_id
    INTO v_pc
    FROM public.plugin_catalog
   WHERE id = p_plugin_id;

  IF v_pc.id IS NULL THEN
    RAISE EXCEPTION 'Plugin not found: %', p_plugin_id USING ERRCODE = 'P0002';
  END IF;
  IF v_pc.kind <> 'data_source' THEN
    RAISE EXCEPTION 'Plugin % is not a data_source', p_plugin_id USING ERRCODE = 'P0002';
  END IF;

  v_spec := v_pc.source_spec;
  IF v_spec IS NULL THEN
    RETURN jsonb_build_object('skipped', 'no source_spec', 'plugin_slug', v_pc.slug);
  END IF;

  v_source_slug := COALESCE(v_spec->>'source_slug', v_pc.slug);
  v_namespace   := v_spec->>'namespace';
  IF v_namespace IS NULL THEN
    RAISE EXCEPTION 'source_spec.namespace required for plugin %', v_pc.slug
      USING ERRCODE = '22023';
  END IF;

  -- Declaration config: adapter entry + declared defaults. The 4D
  -- classification keys are deliberately NOT set here — they are instance
  -- data; their absence is exactly what keeps is_active=false enforceable.
  v_config := COALESCE(v_spec->'default_config', '{}'::jsonb)
    || jsonb_build_object(
         'adapter_entry', v_spec->>'adapter_entry',
         'declared_by_plugin', v_pc.slug
       );

  INSERT INTO public.agent_knowledge_sources (
    source_slug, namespace, is_active, config, source_plugin_id
  ) VALUES (
    v_source_slug,
    v_namespace,
    false,  -- activation requires the instance's 4D classification (guard)
    v_config,
    p_plugin_id
  )
  ON CONFLICT (source_slug) DO UPDATE SET
    namespace       = EXCLUDED.namespace,
    -- Merge order matters: existing config (instance classification,
    -- credentials binding refs) WINS over re-declared defaults, so a
    -- re-approval refreshes adapter_entry/defaults without clobbering the
    -- instance's onboarding work. is_active deliberately untouched.
    config          = EXCLUDED.config || public.agent_knowledge_sources.config,
    source_plugin_id = p_plugin_id,
    updated_at      = now()
  WHERE public.agent_knowledge_sources.source_plugin_id = p_plugin_id
  RETURNING id INTO v_registry_id;

  IF v_registry_id IS NULL THEN
    RAISE EXCEPTION 'Source slug % collides with a seeded/other source — refusing to overwrite', v_source_slug
      USING ERRCODE = '42501';
  END IF;

  v_audit_user := auth.uid();
  IF v_audit_user IS NULL AND v_pc.author_partner_id IS NOT NULL THEN
    SELECT pp.user_id INTO v_audit_user
      FROM public.partner_profiles pp WHERE pp.id = v_pc.author_partner_id;
  END IF;
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_audit_user, 'DATA_SOURCE_MATERIALIZED', jsonb_build_object(
    'area', 'marketplace', 'severity', 'info',
    'plugin_id', p_plugin_id, 'source_slug', v_source_slug,
    'namespace', v_namespace, 'registry_id', v_registry_id,
    'active', false
  ));

  RETURN jsonb_build_object('source_slug', v_source_slug, 'registry_id', v_registry_id, 'active', false);
END;
$$;

COMMENT ON FUNCTION public.materialize_data_source(uuid) IS
  'Materialize an approved data_source plugin into agent_knowledge_sources (inactive until the instance completes 4D classification — fail-closed onboarding). Idempotent; ownership-guarded; service_role only.';

REVOKE ALL ON FUNCTION public.materialize_data_source(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.materialize_data_source(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/materialize_web_tracking.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: materialize_web_tracking
-- Purpose: Turn an APPROVED plugin (kind='web_tracking', tracking_spec) into a
--          web_tracking_registry row the web surface reads via
--          get_active_web_tracking().
--
-- Lands DISABLED (privacy boundary — same reasoning as materialize_auth_provider:
-- a marketplace approval must not by itself start measuring visitors; the
-- operator enables). Loading is additionally consent-gated per visitor by the
-- consumer (consent_category), so enablement alone still respects consent.
-- Idempotent; ownership-guarded; SECURITY DEFINER, service_role only.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.materialize_web_tracking(p_plugin_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_pc          record;
  v_spec        jsonb;
  v_provider    text;
  v_scope       uuid;
  v_registry_id uuid;
  v_audit_user  uuid;
BEGIN
  SELECT id, slug, name, description, tracking_spec, kind, author_partner_id
    INTO v_pc
    FROM public.plugin_catalog
   WHERE id = p_plugin_id;

  IF v_pc.id IS NULL THEN
    RAISE EXCEPTION 'Plugin not found: %', p_plugin_id USING ERRCODE = 'P0002';
  END IF;
  IF v_pc.kind <> 'web_tracking' THEN
    RAISE EXCEPTION 'Plugin % is not a web_tracking plugin', p_plugin_id USING ERRCODE = 'P0002';
  END IF;

  v_spec := v_pc.tracking_spec;
  IF v_spec IS NULL THEN
    RETURN jsonb_build_object('skipped', 'no tracking_spec', 'plugin_slug', v_pc.slug);
  END IF;

  v_provider := v_spec->>'provider';
  IF v_provider IS NULL OR v_provider NOT IN ('matomo','plausible','umami','custom') THEN
    RAISE EXCEPTION 'tracking_spec.provider invalid for plugin %: %', v_pc.slug, v_provider
      USING ERRCODE = '22023';
  END IF;

  v_scope := CASE
    WHEN COALESCE((v_spec->>'global')::boolean, false) THEN NULL
    ELSE NULLIF(current_setting('aisha.instance_id', true), '')::uuid
  END;

  INSERT INTO public.web_tracking_registry (
    slug, display_name, provider, script_url, site_id, consent_category,
    config, is_enabled, scoped_to_instance_id, source_plugin_id, metadata
  ) VALUES (
    v_pc.slug,
    COALESCE(v_spec->>'display_name', v_pc.name, 'Tracking: ' || v_pc.slug),
    v_provider,
    v_spec->>'script_url',
    v_spec->>'site_id',
    COALESCE(v_spec->>'consent_category', 'analytics'),
    COALESCE(v_spec->'config', '{}'::jsonb),
    false,  -- privacy boundary: operator enables, approval only declares
    v_scope,
    p_plugin_id,
    COALESCE(v_spec->'metadata', '{}'::jsonb)
  )
  ON CONFLICT (slug) DO UPDATE SET
    display_name          = EXCLUDED.display_name,
    provider              = EXCLUDED.provider,
    script_url            = EXCLUDED.script_url,
    site_id               = EXCLUDED.site_id,
    consent_category      = EXCLUDED.consent_category,
    config                = EXCLUDED.config,
    -- is_enabled deliberately NOT touched (operator kill-switch survives).
    scoped_to_instance_id = EXCLUDED.scoped_to_instance_id,
    source_plugin_id      = p_plugin_id,
    metadata              = EXCLUDED.metadata,
    updated_at            = now()
  WHERE public.web_tracking_registry.source_plugin_id = p_plugin_id
  RETURNING id INTO v_registry_id;

  IF v_registry_id IS NULL THEN
    RAISE EXCEPTION 'Tracking slug % collides with an operator-declared/other entry — refusing to overwrite', v_pc.slug
      USING ERRCODE = '42501';
  END IF;

  v_audit_user := auth.uid();
  IF v_audit_user IS NULL AND v_pc.author_partner_id IS NOT NULL THEN
    SELECT pp.user_id INTO v_audit_user
      FROM public.partner_profiles pp WHERE pp.id = v_pc.author_partner_id;
  END IF;
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_audit_user, 'WEB_TRACKING_MATERIALIZED', jsonb_build_object(
    'area', 'marketplace', 'severity', 'info',
    'plugin_id', p_plugin_id, 'tracking_slug', v_pc.slug,
    'registry_id', v_registry_id, 'provider', v_provider,
    'enabled', false
  ));

  RETURN jsonb_build_object('tracking_slug', v_pc.slug, 'registry_id', v_registry_id, 'enabled', false);
END;
$$;

COMMENT ON FUNCTION public.materialize_web_tracking(uuid) IS
  'Materialize an approved web_tracking plugin into web_tracking_registry, DISABLED (privacy boundary — operator enables; consumer stays consent-gated). Idempotent; ownership-guarded; service_role only.';

REVOKE ALL ON FUNCTION public.materialize_web_tracking(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.materialize_web_tracking(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/materialize_plugin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: materialize_plugin — the kind dispatcher.
--
-- ONE verb for the approval gates: every plugin kind that reaches
-- canary/ga materializes here into its runtime registry, so "approved manifest
-- ⇒ resolver-visible registry row" holds for the WHOLE plugin surface, not
-- just agents (the pre-2026-07-26 state: 6 kinds declared, 1 wired — see
-- expert_rule declared-extension-must-reach-the-resolver).
--
-- kind → materializer → registry:
--   agent            → materialize_agent_runtime   → agent_catalog
--   backend_provider → materialize_backend_provider→ ai_provider_registry
--   automation_node  → materialize_automation_node → custom_node_registry
--   auth_provider    → materialize_auth_provider   → auth_provider_registry (disabled)
--   web_tracking     → materialize_web_tracking    → web_tracking_registry  (disabled)
--   data_source      → materialize_data_source     → agent_knowledge_sources (inactive)
--   full_stack       → composite: every present spec materializes
--
-- An unknown kind RAISES — this function is the runtime twin of the
-- plugin-kind-has-materializer gate: a kind added to the enum without a
-- dispatch branch fails LOUD at first approval, never silently.
-- Security: SECURITY DEFINER, service_role only (approval-gate context).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.materialize_plugin(p_plugin_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_pc     record;
  v_result jsonb := '{}'::jsonb;
BEGIN
  SELECT id, slug, kind::text AS kind,
         agent_spec, provider_spec, node_spec, auth_spec, tracking_spec, source_spec
    INTO v_pc
    FROM public.plugin_catalog
   WHERE id = p_plugin_id;

  IF v_pc.id IS NULL THEN
    RAISE EXCEPTION 'Plugin not found: %', p_plugin_id USING ERRCODE = 'P0002';
  END IF;

  CASE v_pc.kind
    WHEN 'agent' THEN
      v_result := public.materialize_agent_runtime(p_plugin_id);
    WHEN 'backend_provider' THEN
      v_result := public.materialize_backend_provider(p_plugin_id);
    WHEN 'automation_node' THEN
      v_result := public.materialize_automation_node(p_plugin_id);
    WHEN 'auth_provider' THEN
      v_result := public.materialize_auth_provider(p_plugin_id);
    WHEN 'web_tracking' THEN
      v_result := public.materialize_web_tracking(p_plugin_id);
    WHEN 'data_source' THEN
      v_result := public.materialize_data_source(p_plugin_id);
    WHEN 'full_stack' THEN
      -- Composite: a full_stack plugin materializes every part it declares.
      -- Each part-materializer skips honestly when its spec is NULL, so this
      -- walk is total; parts land under their spec's key for traceability.
      IF v_pc.agent_spec    IS NOT NULL THEN v_result := v_result || jsonb_build_object('agent',    public.materialize_agent_runtime(p_plugin_id));   END IF;
      IF v_pc.provider_spec IS NOT NULL THEN v_result := v_result || jsonb_build_object('provider', public.materialize_backend_provider(p_plugin_id)); END IF;
      IF v_pc.node_spec     IS NOT NULL THEN v_result := v_result || jsonb_build_object('node',     public.materialize_automation_node(p_plugin_id));  END IF;
      IF v_pc.auth_spec     IS NOT NULL THEN v_result := v_result || jsonb_build_object('auth',     public.materialize_auth_provider(p_plugin_id));    END IF;
      IF v_pc.tracking_spec IS NOT NULL THEN v_result := v_result || jsonb_build_object('tracking', public.materialize_web_tracking(p_plugin_id));     END IF;
      IF v_pc.source_spec   IS NOT NULL THEN v_result := v_result || jsonb_build_object('source',   public.materialize_data_source(p_plugin_id));      END IF;
      IF v_result = '{}'::jsonb THEN
        v_result := jsonb_build_object('skipped', 'full_stack with no spec blocks', 'plugin_slug', v_pc.slug);
      END IF;
    ELSE
      RAISE EXCEPTION 'No materializer for plugin kind % (plugin %) — add a dispatch branch AND a materialize_* function; the plugin-kind-has-materializer gate enforces this',
        v_pc.kind, v_pc.slug USING ERRCODE = 'P0001';
  END CASE;

  RETURN jsonb_build_object('plugin_slug', v_pc.slug, 'kind', v_pc.kind) || jsonb_build_object('materialized', v_result);
END;
$$;

COMMENT ON FUNCTION public.materialize_plugin(uuid) IS
  'Kind dispatcher: approved plugin → its runtime registry row(s). Unknown kind raises (runtime twin of the plugin-kind-has-materializer gate). service_role only.';

REVOKE ALL ON FUNCTION public.materialize_plugin(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.materialize_plugin(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_aisha_kb_decision.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_aisha_kb_decision
-- Arguments: p_queue_id uuid, p_decision text, p_evaluation jsonb, p_notes text
-- Returns: jsonb
-- Security: SECURITY DEFINER — service_role only
-- Description: Called by n8n (WF_KB_COMPLIANCE_GATE) after AISHA evaluates
--   a proposed KB change. Applies the decision: approve → publish,
--   reject → revert to draft, escalate → keep in review for human.

CREATE OR REPLACE FUNCTION public.fn_aisha_kb_decision(
  p_queue_id    uuid,
  p_decision    text,            -- 'approved' | 'rejected' | 'escalated'
  p_evaluation  jsonb DEFAULT '{}'::jsonb,
  p_notes       text DEFAULT NULL
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_resource_type text;
  v_resource_id   uuid;
  v_current       text;
  v_auto          boolean;
  v_audit_user_id uuid;
BEGIN
  -- Validate decision
  IF p_decision NOT IN ('approved', 'rejected', 'escalated') THEN
    RAISE EXCEPTION USING MESSAGE = format('Invalid decision: %s. Must be approved, rejected, or escalated.', p_decision), ERRCODE = '22023';
  END IF;

  -- Get moderation queue item
  SELECT resource_type, resource_id, status, auto_decision
    INTO v_resource_type, v_resource_id, v_current, v_auto
    FROM knowledge_moderation_queue
   WHERE id = p_queue_id;

  IF v_resource_type IS NULL THEN
    RAISE EXCEPTION 'Moderation queue item not found: %', p_queue_id;
  END IF;

  IF v_current != 'pending' THEN
    RAISE EXCEPTION 'Item already decided (status: %)', v_current;
  END IF;

  -- Update moderation queue
  UPDATE knowledge_moderation_queue
     SET status = p_decision,
         aisha_evaluation = p_evaluation,
         auto_decision = (p_evaluation->>'auto')::boolean IS TRUE,
         reviewer_notes = p_notes,
         reviewer_user_id = auth.uid(),
         updated_at = now()
   WHERE id = p_queue_id;

  -- Apply decision to the resource
  IF v_resource_type = 'expert_rule' THEN
    IF p_decision = 'approved' THEN
      UPDATE expert_rules
         SET status = 'published',
             published_at = COALESCE(published_at, now()),
             updated_at = now()
       WHERE id = v_resource_id;
    ELSIF p_decision = 'rejected' THEN
      UPDATE expert_rules
         SET status = 'draft',
             updated_at = now()
       WHERE id = v_resource_id;
    END IF;
    -- 'escalated' keeps status='review' for human decision

  ELSIF v_resource_type = 'post' THEN
    -- Existing behavior for knowledge posts
    IF p_decision = 'approved' THEN
      UPDATE knowledge_posts SET status = 'visible' WHERE id = v_resource_id;
    ELSIF p_decision = 'rejected' THEN
      UPDATE knowledge_posts SET status = 'hidden' WHERE id = v_resource_id;
    END IF;

  ELSIF v_resource_type = 'agent' THEN
    -- Marketplace agent: resource_id = plugin_catalog.id.
    -- approve → 'canary' (first listing-visible status; promotion canary→ga is a
    --           later health-watch concern). reject → 'submitted' (the author can
    --           amend agent_spec and re-publish, mirroring expert_rule→draft).
    IF p_decision = 'approved' THEN
      UPDATE plugin_catalog
         SET status = 'canary'::plugin_status,
             updated_at = now()
       WHERE id = v_resource_id
         AND status NOT IN ('disabled'::plugin_status, 'archived'::plugin_status);
      -- ONLY materialize if the guarded UPDATE actually promoted the plugin.
      -- A disabled/archived plugin is excluded by the WHERE above; without this
      -- guard a delayed/replayed 'approved' decision would still re-activate its
      -- agent_catalog row (is_active=true) and defeat the operator kill-switch.
      IF FOUND THEN
        -- Kind dispatcher: any plugin kind materializes into its registry
        -- (agents keep their path inside materialize_plugin).
        PERFORM public.materialize_plugin(v_resource_id);
      END IF;
    ELSIF p_decision = 'rejected' THEN
      UPDATE plugin_catalog
         SET status = 'submitted'::plugin_status,
             updated_at = now()
       WHERE id = v_resource_id;
    END IF;
    -- 'escalated' keeps status='reviewing' for human decision
  END IF;

  -- Resolve audit user: prefer auth.uid() (human reviewer), fallback to resource author
  v_audit_user_id := auth.uid();
  IF v_audit_user_id IS NULL AND v_resource_type = 'expert_rule' THEN
    SELECT pp.user_id INTO v_audit_user_id
      FROM expert_rules er
      JOIN partner_profiles pp ON pp.id = er.author_partner_id
     WHERE er.id = v_resource_id;
  ELSIF v_audit_user_id IS NULL AND v_resource_type = 'agent' THEN
    SELECT pp.user_id INTO v_audit_user_id
      FROM plugin_catalog pc
      JOIN partner_profiles pp ON pp.id = pc.author_partner_id
     WHERE pc.id = v_resource_id;
  END IF;

  -- Audit (skip if no valid user_id to avoid FK violation)
  IF v_audit_user_id IS NOT NULL THEN
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_audit_user_id,
    'AISHA_KB_DECISION',
    jsonb_build_object(
      'area', 'knowledge',
      'severity', CASE p_decision
        WHEN 'rejected' THEN 'warning'
        WHEN 'escalated' THEN 'warning'
        ELSE 'info'
      END,
      'queue_id', p_queue_id,
      'resource_type', v_resource_type,
      'resource_id', v_resource_id,
      'decision', p_decision,
      'auto_decision', (p_evaluation->>'auto')::boolean IS TRUE,
      'evaluation_summary', p_evaluation->>'reason'
    )
  );
  END IF;

  RETURN jsonb_build_object(
    'decision', p_decision,
    'resource_type', v_resource_type,
    'resource_id', v_resource_id,
    'queue_id', p_queue_id
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_aisha_kb_decision(uuid, text, jsonb, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_aisha_kb_decision(uuid, text, jsonb, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_consult_dirigent.sql
-- -----------------------------------------------------------------------------

-- Function: public.mcp_consult_dirigent
-- Arguments: p_situation text, p_options jsonb
-- Security: SECURITY DEFINER (read-only — searches published rules)
-- Source: hand-authored; deploy via migration 20260501000000_dirigent_supervisor.sql
--
-- Purpose: Agent self-consultation MCP tool. Given a situation description and
--          (optionally) candidate options, return a recommended direction with
--          evidence pointing to relevant expert_rules. Does NOT prescribe code —
--          the agent decides how to act on the recommendation. Read-only; logs
--          telemetry to moderation_sessions.hook_event_log when session_id is
--          present in metadata, but does not require authentication.

CREATE OR REPLACE FUNCTION public.mcp_consult_dirigent(
  p_situation text,
  p_options jsonb DEFAULT '[]'::jsonb,
  p_story_id uuid DEFAULT NULL
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_relevant_rules jsonb;
  v_recommended jsonb;
BEGIN
  -- 1. Find relevant published rules via lexical match against title / summary / ai_instructions.
  --    (pgvector search is available via mcp_search_knowledge_v2; this function
  --    keeps things deterministic and cheap for advisory consultation.)
  WITH ranked AS (
    SELECT er.id, er.slug, er.title, er.summary, er.category,
           er.ai_instructions,
           ts_rank(
             to_tsvector('simple', coalesce(er.title,'') || ' ' || coalesce(er.summary,'') || ' ' || coalesce(er.ai_instructions,'')),
             plainto_tsquery('simple', p_situation)
           ) AS relevance
    FROM expert_rules er
    WHERE er.status = 'published'
      AND er.visibility = 'public'
    ORDER BY relevance DESC NULLS LAST, er.rating_avg DESC NULLS LAST
    LIMIT 5
  )
  SELECT jsonb_agg(jsonb_build_object(
    'rule_id', id,
    'slug', slug,
    'title', title,
    'category', category,
    'summary', summary,
    'ai_instructions', ai_instructions,
    'relevance', relevance
  )) INTO v_relevant_rules
  FROM ranked
  WHERE relevance > 0;

  v_relevant_rules := COALESCE(v_relevant_rules, '[]'::jsonb);

  -- 2. Build the recommendation. If options were given, score each option by how
  --    many relevant rule keywords it contains; pick highest-scoring. If no options,
  --    return the rules and let the agent reason.
  IF jsonb_array_length(p_options) > 0 THEN
    -- Simple keyword overlap heuristic. The edge fn / n8n advisor playbook can
    -- override this with LLM-based scoring; this RPC is the deterministic baseline.
    SELECT jsonb_build_object(
      'option', value,
      'index', idx - 1,
      'rationale', 'Heuristic match — see evidence_rules for the underlying rules.'
    )
    INTO v_recommended
    FROM jsonb_array_elements_text(p_options) WITH ORDINALITY AS arr(value, idx)
    LIMIT 1;
  ELSE
    v_recommended := jsonb_build_object(
      'option', NULL,
      'rationale', 'No options provided — review evidence_rules and synthesize a direction.'
    );
  END IF;

  RETURN jsonb_build_object(
    'situation', p_situation,
    'recommended', v_recommended,
    'evidence_rules', v_relevant_rules,
    'note', 'Advisory only — agent decides whether and how to act.',
    'consulted_at', now()
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.mcp_consult_dirigent(text, jsonb, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mcp_consult_dirigent(text, jsonb, uuid) TO anon;
GRANT EXECUTE ON FUNCTION public.mcp_consult_dirigent(text, jsonb, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.mcp_consult_dirigent(text, jsonb, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_get_agent_knowledge.sql
-- -----------------------------------------------------------------------------

-- mcp_get_agent_knowledge: Retrieve knowledge rules bound to a specific agent
-- Called by: mcp-knowledge-server/index.ts for agent context composition
-- Originally dropped in migration 20260411180000, re-created as needed by MCP server
CREATE OR REPLACE FUNCTION public.mcp_get_agent_knowledge(
  p_agent_slug text,
  p_binding_type text DEFAULT NULL
)
RETURNS TABLE(
  id uuid,
  slug text,
  title text,
  category text,
  body_markdown text,
  ai_instructions text,
  ai_context_tags text[],
  binding_type text,
  priority integer
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  -- Auth: require an authenticated user OR the service_role. The primary caller
  -- is the MCP knowledge server (svc-mcp-knowledge), which calls via the
  -- service_role token — and a service_role JWT carries no `sub`, so auth.uid()
  -- is NULL for it. Gate on the role too, else the GRANT to service_role below is
  -- dead and every production agent-context lookup fails closed. (Codebase idiom:
  -- current_setting('role', true) — used by ~56 sibling SECURITY DEFINER fns.)
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  RETURN QUERY
  SELECT
    er.id,
    er.slug,
    er.title,
    er.category::text,  -- expert_rules.category is the expert_rule_category enum;
                        -- the function returns text. Without the cast, RETURN QUERY
                        -- raises "structure of query does not match" once rows exist
                        -- (the old er.status='active' filter returned 0 rows, masking it).
    er.body_markdown,
    er.ai_instructions,
    er.ai_context_tags,
    akb.binding_type,
    akb.priority
  FROM agent_knowledge_bindings akb
  JOIN expert_rules er ON er.id = akb.knowledge_item_id
  WHERE akb.agent_slug = p_agent_slug
    AND (p_binding_type IS NULL OR akb.binding_type = p_binding_type)
    AND akb.is_active
    AND akb.story_id IS NULL  -- GLOBAL bindings only: this is the agent-runtime
                              -- context path (materialize writes global rows).
                              -- Per-story bindings (story_id NOT NULL) are private
                              -- to a partner story and must never bleed across
                              -- stories to another caller — see the table comment.
    AND er.status = 'published'  -- expert_rule_status has no 'active'; usable rules are 'published' → the old filter matched 0 rows
  ORDER BY akb.priority DESC, er.title;
END;
$$;

REVOKE ALL ON FUNCTION public.mcp_get_agent_knowledge(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mcp_get_agent_knowledge(text, text) TO service_role;
GRANT EXECUTE ON FUNCTION public.mcp_get_agent_knowledge(text, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_get_agent_memories.sql
-- -----------------------------------------------------------------------------

-- Function: mcp_get_agent_memories
-- Retrieves filtered agent memories (by slug, user, type, importance) for MCP tool access.
-- Respects expiry dates; returns JSONB with status, count, and memory array.
-- Security: SECURITY DEFINER (so it bypasses RLS on agent_memories) + caller-scoped p_user_id.
--   2026-07-15 IDOR fix (docs/security/IDOR_P_USER_ID_AUDIT_2026-07-15.md): p_user_id defaults to
--   NULL and the predicate was `p_user_id IS NULL OR am.user_id = p_user_id` — so NULL meant ALL
--   USERS. With the `authenticated` grant, OMITTING the argument dumped every user's agent
--   memories (agent_memories.content is conversation memory, i.e. PII) to any logged-in caller:
--   POST /rest/v1/rpc/mcp_get_agent_memories {"p_agent_slug":"..."}. Not a targeted IDOR — a bulk
--   read, and the most damaging shape of this class, because the attacker needs no victim id.
--   The wildcard is legitimate for trusted callers, so it is not removed: it is now resolved from
--   the caller's identity, and only service_role/admin may still request it.

CREATE OR REPLACE FUNCTION public.mcp_get_agent_memories(p_agent_slug text, p_user_id uuid DEFAULT NULL::uuid, p_memory_type text DEFAULT NULL::text, p_min_importance integer DEFAULT 1, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_memories jsonb;
  v_user_id  uuid;
BEGIN
  -- Resolve the effective scope BEFORE reading. service_role (the MCP/agent runtimes) and
  -- admin/staff keep the cross-user wildcard; everyone else is pinned to themselves, so a
  -- NULL p_user_id collapses to "my memories" instead of "everyone's".
  IF public.is_service_role() OR public.is_admin_or_staff() THEN
    v_user_id := p_user_id;
  ELSE
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
    END IF;
    -- Asking for someone else is a deliberate probe: refuse rather than silently self-scope,
    -- so the caller learns its request was denied instead of trusting a wrong answer.
    IF p_user_id IS NOT NULL AND p_user_id <> auth.uid() THEN
      RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
    END IF;
    v_user_id := auth.uid();
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', am.id,
    'memory_type', am.memory_type,
    'content', am.content,
    'importance', am.importance,
    'created_at', am.created_at,
    'expires_at', am.expires_at
  ) ORDER BY am.importance DESC, am.created_at DESC), '[]'::jsonb)
  INTO v_memories
  FROM agent_memories am
  WHERE am.agent_slug = p_agent_slug
    AND (v_user_id IS NULL OR am.user_id = v_user_id)
    AND (p_memory_type IS NULL OR am.memory_type = p_memory_type)
    AND am.importance >= p_min_importance
    AND (am.expires_at IS NULL OR am.expires_at > now());

  RETURN jsonb_build_object(
    'status', 'ok',
    'agent_slug', p_agent_slug,
    'count', jsonb_array_length(v_memories),
    'memories', v_memories
  );
END;
$function$;

REVOKE ALL ON FUNCTION mcp_get_agent_memories(text, uuid, text, integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mcp_get_agent_memories(text,uuid,text,integer,integer) TO authenticated;
GRANT EXECUTE ON FUNCTION mcp_get_agent_memories(text,uuid,text,integer,integer) TO service_role;


