-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_get_knowledge_item.sql
-- -----------------------------------------------------------------------------

-- Function: mcp_get_knowledge_item

CREATE OR REPLACE FUNCTION public.mcp_get_knowledge_item(p_item_id uuid DEFAULT NULL::uuid, p_source_slug text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', ki.id,
    'item_type', ki.item_type::text,
    'source_type', ki.source_type,
    'source_slug', ki.source_slug,
    'title', ki.title,
    'summary', ki.summary,
    'body_markdown', ki.body_markdown,
    'ai_instructions', ki.ai_instructions,
    'ai_context_tags', ki.ai_context_tags,
    'category', ki.category,
    'expertise_area_slug', gea.slug,
    'expertise_area_icon', gea.icon,
    'author_display_name', ki.author_display_name,
    'is_verified', ki.is_verified,
    'version', ki.version,
    'usage_count', ki.usage_count,
    'rating_avg', ki.rating_avg,
    'published_at', ki.published_at,
    'updated_at', ki.updated_at,
    'chunks', COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
        'chunk_index', kc.chunk_index,
        'chunk_text', kc.chunk_text,
        'section_title', kc.section_title,
        'token_count', kc.token_count,
        'has_embedding', EXISTS(
          SELECT 1 FROM knowledge_embeddings ke WHERE ke.chunk_id = kc.id
        )
      ) ORDER BY kc.chunk_index)
      FROM knowledge_chunks kc
      WHERE kc.knowledge_item_id = ki.id),
      '[]'::jsonb
    ),
    'bindings', COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
        'target_type', rb.target_type::text,
        'binding_type', rb.binding_type,
        'priority', rb.priority
      ))
      FROM rule_bindings rb
      WHERE rb.rule_id = ki.source_id AND rb.is_active = true),
      '[]'::jsonb
    )
  )
  INTO v_result
  FROM knowledge_items ki
  LEFT JOIN guild_expertise_areas gea ON gea.id = ki.expertise_area_id
  WHERE ki.status = 'active'
    AND ki.visibility IN ('public', 'members')
    -- Brick6 tier-ACL. Gate single-item retrieval by the caller's audience tier,
    -- mirroring the HARD filter in mcp_search_knowledge_v2/v3 — an under-tier caller
    -- must never fetch a gated item by id/slug. Pinned to auth.uid() with NO
    -- service_role override, same rationale as the story-isolation block below: the
    -- MCP get_knowledge_item tool dispatches this as service_role (auth.uid() NULL),
    -- so tier-gated items collapse to ungated-only there — fail-closed is correct.
    AND (
      ki.minimum_tier IS NULL
      OR public.audience_user_meets_tier_requirement(ki.minimum_tier, auth.uid())
    )
    -- Per-story isolation. Story-scoped items default to visibility='public'
    -- (upsert_story_knowledge_item_audited), so the visibility filter alone would
    -- hand any anon/authenticated caller another story's full body_markdown +
    -- ai_instructions + chunk_text by id/slug. Global items (story_id IS NULL)
    -- stay public; story-scoped items only go to owner/participant/admin.
    -- Deliberately NO service_role bypass: the MCP get_knowledge_item tool
    -- dispatches this as service_role (auth.uid() NULL), so story items collapse
    -- to global-only there — the correct behaviour for a global KB accessor.
    AND (
      ki.story_id IS NULL
      OR public.is_admin_or_staff(auth.uid())
      OR EXISTS (
        SELECT 1 FROM partner_stories ps
        WHERE ps.id = ki.story_id AND ps.user_id = auth.uid()
      )
      OR EXISTS (
        SELECT 1 FROM story_participants sp
        WHERE sp.story_id = ki.story_id AND sp.user_id = auth.uid()
      )
    )
    AND (
      (p_item_id IS NOT NULL AND ki.id = p_item_id)
      OR (p_source_slug IS NOT NULL AND ki.source_slug = p_source_slug)
    );

  -- Track usage
  IF v_result IS NOT NULL THEN
    UPDATE knowledge_items SET usage_count = usage_count + 1
    WHERE id = (v_result->>'id')::uuid;
  END IF;

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION mcp_get_knowledge_item(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mcp_get_knowledge_item(uuid,text) TO anon;
GRANT EXECUTE ON FUNCTION mcp_get_knowledge_item(uuid,text) TO authenticated;
GRANT EXECUTE ON FUNCTION mcp_get_knowledge_item(uuid,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_get_knowledge_stats.sql
-- -----------------------------------------------------------------------------

-- Function: mcp_get_knowledge_stats

CREATE OR REPLACE FUNCTION public.mcp_get_knowledge_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN (
    SELECT jsonb_build_object(
      'total_items', (SELECT count(*) FROM knowledge_items WHERE status = 'active'),
      'total_chunks', (SELECT count(*) FROM knowledge_chunks),
      'total_embeddings', (SELECT count(*) FROM knowledge_embeddings),
      'items_by_type', COALESCE(
        (SELECT jsonb_object_agg(item_type::text, cnt)
         FROM (
           SELECT item_type, count(*) as cnt
           FROM knowledge_items
           WHERE status = 'active'
           GROUP BY item_type
         ) sub),
        '{}'::jsonb
      ),
      'items_by_category', COALESCE(
        (SELECT jsonb_object_agg(COALESCE(category, 'uncategorized'), cnt)
         FROM (
           SELECT category, count(*) as cnt
           FROM knowledge_items
           WHERE status = 'active'
           GROUP BY category
         ) sub),
        '{}'::jsonb
      ),
      'embedding_coverage', (
        SELECT jsonb_build_object(
          'items_with_chunks', (SELECT count(DISTINCT knowledge_item_id) FROM knowledge_chunks),
          'chunks_with_embeddings', (SELECT count(DISTINCT chunk_id) FROM knowledge_embeddings)
        )
      )
    )
  );
END;
$function$;

REVOKE ALL ON FUNCTION mcp_get_knowledge_stats() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mcp_get_knowledge_stats() TO anon;
GRANT EXECUTE ON FUNCTION mcp_get_knowledge_stats() TO authenticated;
GRANT EXECUTE ON FUNCTION mcp_get_knowledge_stats() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_get_rule_detail.sql
-- -----------------------------------------------------------------------------

-- Function: mcp_get_rule_detail

CREATE OR REPLACE FUNCTION public.mcp_get_rule_detail(p_rule_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', er.id,
    'slug', er.slug,
    'title', er.title,
    'summary', er.summary,
    'body_markdown', er.body_markdown,
    'category', er.category::text,
    'expertise_area_slug', gea.slug,
    'expertise_area_name_key', gea.name_key,
    'expertise_area_icon', gea.icon,
    'author_display_name', pp.display_name,
    'author_guild_tier', pp.guild_tier,
    'ai_instructions', er.ai_instructions,
    'ai_context_tags', er.ai_context_tags,
    'is_verified', er.is_verified,
    'version', er.version,
    'rating_avg', er.rating_avg,
    'rating_count', er.rating_count,
    'usage_count', er.usage_count,
    'published_at', er.published_at,
    'updated_at', er.updated_at,
    'documents', COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
        'title', erd.title,
        'description', erd.description,
        'content_markdown', erd.content_markdown,
        'document_type', erd.document_type,
        'sort_order', erd.sort_order
      ) ORDER BY erd.sort_order)
      FROM expert_rule_documents erd
      WHERE erd.rule_id = er.id),
      '[]'::jsonb
    )
  )
  INTO v_result
  FROM expert_rules er
  JOIN partner_profiles pp ON pp.id = er.author_partner_id
  LEFT JOIN guild_expertise_areas gea ON gea.id = er.expertise_area_id
  WHERE er.slug = p_rule_slug
    AND er.status = 'published'
    AND er.visibility IN ('public', 'members');

  -- Track usage
  IF v_result IS NOT NULL THEN
    UPDATE expert_rules SET usage_count = usage_count + 1
    WHERE slug = p_rule_slug;
  END IF;

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION mcp_get_rule_detail(p_rule_slug text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mcp_get_rule_detail(text) TO anon;
GRANT EXECUTE ON FUNCTION mcp_get_rule_detail(text) TO authenticated;
GRANT EXECUTE ON FUNCTION mcp_get_rule_detail(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_get_story_context.sql
-- -----------------------------------------------------------------------------

-- Function: public.mcp_get_story_context
-- Arguments: p_story_id uuid
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.mcp_get_story_context(p_story_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'story', jsonb_build_object(
      'id', ps.id,
      'title', ps.title,
      'status', ps.status,
      'delivery_status', ps.delivery_status,
      'repo_url', ps.repo_url,
      'repo_provider', ps.repo_provider,
      'default_branch', ps.default_branch,
      'tech_stack', ps.tech_stack,
      'domain', ps.domain,
      'project_preview', ps.project_preview,
      'risk_profile', ps.risk_profile,
      'origin', ps.origin
    ),
    'project_preview', ps.project_preview,
    'ruleset', CASE WHEN sr.id IS NOT NULL THEN jsonb_build_object(
      'id', sr.id,
      'fingerprint', sr.ruleset_fingerprint,
      'rule_count', array_length(sr.rule_ids, 1),
      'context_profile', sr.context_profile,
      'rule_versions', sr.rule_versions,
      'created_at', sr.created_at
    ) ELSE NULL END,
    'build_config', COALESCE(sc.build_config, '{}'::jsonb),
    'env_hints', COALESCE(sc.env_hints, '{}'::jsonb),
    'mcp_endpoint', sc.mcp_endpoint,
    'participants', COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
        'user_id', sp.user_id,
        'role', sp.role,
        'joined_at', sp.joined_at
       ))
       FROM story_participants sp WHERE sp.story_id = ps.id),
      '[]'::jsonb
    ),
    'rules_preview', COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
        'id', er.id,
        'slug', er.slug,
        'title', er.title,
        'category', er.category,
        'version', er.version
       ))
       FROM unnest(sr.rule_ids) AS rid
       JOIN expert_rules er ON er.id = rid
       WHERE er.status = 'published'),
      '[]'::jsonb
    )
  ) INTO v_result
  FROM partner_stories ps
  LEFT JOIN story_contexts sc ON sc.story_id = ps.id
  LEFT JOIN story_rulesets sr ON sr.id = sc.ruleset_id
  WHERE ps.id = p_story_id;

  IF v_result IS NULL THEN
    RETURN jsonb_build_object('error', 'Story not found', 'story_id', p_story_id);
  END IF;

  RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION public.mcp_get_story_context(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mcp_get_story_context(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.mcp_get_story_context(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_match_experts.sql
-- -----------------------------------------------------------------------------

-- Function: mcp_match_experts

CREATE OR REPLACE FUNCTION public.mcp_match_experts(p_expertise_slug text DEFAULT NULL::text, p_context_tags text[] DEFAULT '{}'::text[], p_min_proficiency integer DEFAULT 1, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN COALESCE(
    (SELECT jsonb_agg(expert_row ORDER BY expert_row->>'relevance_score' DESC)
    FROM (
      SELECT jsonb_build_object(
        'partner_id', pp.id,
        'display_name', pp.display_name,
        'avatar_url', pp.avatar_url,
        'guild_tier', pp.guild_tier,
        'guild_bio', pp.guild_bio,
        'expertise_area_slug', gea.slug,
        'expertise_area_name_key', gea.name_key,
        'proficiency_level', gme.proficiency_level,
        'published_rules_count', (
          SELECT count(*) FROM expert_rules er2
          WHERE er2.author_partner_id = pp.id AND er2.status = 'published'
        ),
        'matching_rules_count', (
          SELECT count(*) FROM expert_rules er3
          WHERE er3.author_partner_id = pp.id
            AND er3.status = 'published'
            AND (p_context_tags = '{}' OR er3.ai_context_tags && p_context_tags)
        ),
        'relevance_score', (
          gme.proficiency_level * 10
          + CASE WHEN pp.guild_tier = 'grandmaster' THEN 50
                 WHEN pp.guild_tier = 'master' THEN 40
                 WHEN pp.guild_tier = 'expert' THEN 30
                 WHEN pp.guild_tier = 'journeyman' THEN 20
                 WHEN pp.guild_tier = 'apprentice' THEN 10
                 ELSE 0 END
          + (SELECT count(*) FROM expert_rules er4
             WHERE er4.author_partner_id = pp.id
               AND er4.status = 'published'
               AND er4.is_verified = true) * 5
        )
      ) AS expert_row
      FROM guild_member_expertise gme
      JOIN partner_profiles pp ON pp.id = gme.partner_id
      JOIN guild_expertise_areas gea ON gea.id = gme.expertise_area_id
      WHERE gea.is_active = true
        AND gme.proficiency_level >= p_min_proficiency
        AND (p_expertise_slug IS NULL OR gea.slug = p_expertise_slug)
      ORDER BY gme.proficiency_level DESC, pp.guild_tier DESC
      LIMIT p_limit
    ) sub),
    '[]'::jsonb
  );
END;
$function$;

REVOKE ALL ON FUNCTION mcp_match_experts(text, text[], integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mcp_match_experts(text,text[],integer,integer) TO anon;
GRANT EXECUTE ON FUNCTION mcp_match_experts(text,text[],integer,integer) TO authenticated;
GRANT EXECUTE ON FUNCTION mcp_match_experts(text,text[],integer,integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_propose_improvement.sql
-- -----------------------------------------------------------------------------

-- Function: public.mcp_propose_improvement
-- Arguments: p_rule_id uuid, p_suggestion text, p_rationale text
-- Security: SECURITY DEFINER (writes a draft proposal — never auto-applies)
-- Source: hand-authored; deploy via migration 20260501000000_dirigent_supervisor.sql
--
-- Purpose: Agent suggests an improvement to a rule (or to platform behavior in
--          general) based on what it observed. Inserts into improvement_proposals
--          with status='draft' for human review. Mirrors the proposer_mode of
--          participant.ts in the VS Code extension.

CREATE OR REPLACE FUNCTION public.mcp_propose_improvement(
  p_rule_id uuid,
  p_suggestion text,
  p_rationale text DEFAULT NULL
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_proposal_id uuid;
  v_rule_slug text;
  v_rule_title text;
  v_proposed_value jsonb;
BEGIN
  -- Auth: require authenticated caller (writes to improvement_proposals + audit)
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_rule_id IS NULL OR coalesce(trim(p_suggestion), '') = '' THEN
    RETURN jsonb_build_object('error', 'rule_id and non-empty suggestion required');
  END IF;

  SELECT slug, title INTO v_rule_slug, v_rule_title
  FROM expert_rules
  WHERE id = p_rule_id;

  IF v_rule_slug IS NULL THEN
    RETURN jsonb_build_object('error', 'rule not found', 'rule_id', p_rule_id);
  END IF;

  v_proposed_value := jsonb_build_object(
    'rule_id', p_rule_id,
    'rule_slug', v_rule_slug,
    'suggested_change', p_suggestion
  );

  INSERT INTO improvement_proposals (
    proposal_type, status, title, description, proposed_value, rationale,
    source, priority, category, risk_level, agent_slug, metadata
  ) VALUES (
    'rule_improvement',
    'draft',
    'Rule improvement: ' || v_rule_slug,
    p_suggestion,
    v_proposed_value,
    coalesce(p_rationale, 'Submitted via mcp_propose_improvement (autonomous agent observation).'),
    'mcp_propose_improvement',
    5,
    'expert_rules',
    'low',
    'aisha-claude-code',
    jsonb_build_object('rule_id', p_rule_id, 'origin', 'claude_code_agent')
  )
  RETURNING id INTO v_proposal_id;

  -- Audit
  INSERT INTO audit_journal (action_type, action, entity_type, entity_id, area, severity, summary, metadata)
  VALUES (
    'create', 'mcp_propose_improvement', 'improvement_proposals', v_proposal_id::text,
    'aisha-supervisor', 'info',
    'Agent proposed improvement for rule ' || v_rule_slug,
    jsonb_build_object('rule_id', p_rule_id)
  );

  RETURN jsonb_build_object(
    'proposal_id', v_proposal_id,
    'status', 'draft',
    'rule_slug', v_rule_slug,
    'note', 'Proposal logged for human review. No automatic application.'
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.mcp_propose_improvement(uuid, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mcp_propose_improvement(uuid, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.mcp_propose_improvement(uuid, text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_report_milestone.sql
-- -----------------------------------------------------------------------------

-- Function: public.mcp_report_milestone
-- Arguments: p_session_id uuid, p_name text, p_evidence jsonb
-- Security: SECURITY DEFINER (logs progress to moderation_decisions)
-- Source: hand-authored; deploy via migration 20260501000000_dirigent_supervisor.sql
--
-- Purpose: Agent reports a milestone reached during work (e.g. "RPC implemented",
--          "RLS policy added"). This feeds the Stop hook goal_evaluator and gives
--          the user a checkpoint timeline. Pure logging — no decision returned.

CREATE OR REPLACE FUNCTION public.mcp_report_milestone(
  p_session_id uuid,
  p_name text,
  p_evidence jsonb DEFAULT '{}'::jsonb
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_decision_id uuid;
BEGIN
  -- Auth: require authenticated caller (writes to moderation_decisions)
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_session_id IS NULL OR coalesce(trim(p_name), '') = '' THEN
    RETURN jsonb_build_object('error', 'session_id and non-empty name required');
  END IF;

  INSERT INTO moderation_decisions (
    session_id, decision_type, severity, context, recommendation, evidence, accepted
  ) VALUES (
    p_session_id,
    'milestone_log',
    'info',
    jsonb_build_object('milestone', p_name, 'reported_at', now()),
    'Agent reached milestone: ' || p_name,
    coalesce(p_evidence, '{}'::jsonb),
    true  -- self-reported milestones are accepted unless retracted
  )
  RETURNING id INTO v_decision_id;

  RETURN jsonb_build_object(
    'decision_id', v_decision_id,
    'milestone', p_name,
    'recorded_at', now()
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.mcp_report_milestone(uuid, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mcp_report_milestone(uuid, text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.mcp_report_milestone(uuid, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_request_unblock.sql
-- -----------------------------------------------------------------------------

-- Function: public.mcp_request_unblock
-- Arguments: p_rule_id uuid, p_justification text, p_session_id uuid
-- Security: SECURITY DEFINER (writes a pending decision row; never auto-approves)
-- Source: hand-authored; deploy via migration 20260501000000_dirigent_supervisor.sql
--
-- Purpose: Agent flags that a rule feels mis-applied to its current context and
--          requests a temporary relaxation. NEVER auto-approves — inserts a row
--          into moderation_decisions with accepted=NULL (pending). The user (or
--          a senior reviewer) decides via Dirigent UI / n8n approval flow.

CREATE OR REPLACE FUNCTION public.mcp_request_unblock(
  p_rule_id uuid,
  p_justification text,
  p_session_id uuid DEFAULT NULL
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_decision_id uuid;
  v_session_id uuid;
  v_rule_slug text;
  v_rule_title text;
BEGIN
  -- Auth: require authenticated caller (writes to moderation_decisions + audit)
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_rule_id IS NULL OR coalesce(trim(p_justification), '') = '' THEN
    RETURN jsonb_build_object('error', 'rule_id and non-empty justification required');
  END IF;

  -- Resolve rule for evidence + sanity check
  SELECT slug, title INTO v_rule_slug, v_rule_title
  FROM expert_rules
  WHERE id = p_rule_id;

  IF v_rule_slug IS NULL THEN
    RETURN jsonb_build_object('error', 'rule not found', 'rule_id', p_rule_id);
  END IF;

  -- Use provided session_id or fall back to a synthetic one for traceability.
  v_session_id := COALESCE(p_session_id, gen_random_uuid());

  INSERT INTO moderation_decisions (
    session_id, decision_type, severity, context, recommendation, evidence, accepted
  ) VALUES (
    v_session_id,
    'unblock_request',
    'warn',
    jsonb_build_object(
      'rule_id', p_rule_id,
      'rule_slug', v_rule_slug,
      'rule_title', v_rule_title
    ),
    'Agent requests relaxation of rule "' || v_rule_slug || '". Justification: ' || p_justification,
    jsonb_build_object('justification', p_justification),
    NULL  -- pending review
  )
  RETURNING id INTO v_decision_id;

  -- Audit trail
  INSERT INTO audit_journal (action_type, action, entity_type, entity_id, area, severity, summary, metadata)
  VALUES (
    'create', 'mcp_request_unblock', 'moderation_decisions', v_decision_id::text,
    'aisha-supervisor', 'warn',
    'Agent requested unblock for rule ' || v_rule_slug,
    jsonb_build_object('rule_id', p_rule_id, 'session_id', v_session_id)
  );

  RETURN jsonb_build_object(
    'decision_id', v_decision_id,
    'status', 'pending_review',
    'rule_slug', v_rule_slug,
    'note', 'Request logged. Decision pending — agent should proceed without relying on relaxation.'
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.mcp_request_unblock(uuid, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mcp_request_unblock(uuid, text, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.mcp_request_unblock(uuid, text, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_search_knowledge.sql
-- -----------------------------------------------------------------------------

-- Function: mcp_search_knowledge
-- Word-level search: splits query into individual words, matches ANY word (OR logic)

CREATE OR REPLACE FUNCTION public.mcp_search_knowledge(
  p_query text DEFAULT NULL::text,
  p_category text DEFAULT NULL::text,
  p_expertise_slug text DEFAULT NULL::text,
  p_context_tags text[] DEFAULT '{}'::text[],
  p_include_ai_instructions boolean DEFAULT true,
  p_limit integer DEFAULT 20
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_results jsonb;
  v_words text[];
  v_is_authenticated boolean;
BEGIN
  v_is_authenticated := (auth.uid() IS NOT NULL);

  -- Split query into individual words (min 2 chars), for word-level matching
  IF p_query IS NOT NULL AND trim(p_query) != '' THEN
    v_words := ARRAY(
      SELECT w FROM unnest(regexp_split_to_array(lower(trim(p_query)), '\s+')) AS w
      WHERE length(w) >= 2
    );
    IF array_length(v_words, 1) IS NULL THEN
      v_words := NULL;
    END IF;
  ELSE
    v_words := NULL;
  END IF;

  SELECT COALESCE(jsonb_agg(rule_row ORDER BY rule_row->>'relevance_score' DESC), '[]'::jsonb)
  INTO v_results
  FROM (
    SELECT jsonb_build_object(
      'id', er.id,
      'slug', er.slug,
      'title', er.title,
      'summary', er.summary,
      'category', er.category::text,
      'expertise_area_slug', gea.slug,
      'expertise_area_name_key', gea.name_key,
      'expertise_area_icon', gea.icon,
      'author_display_name', pp.display_name,
      'author_guild_tier', pp.guild_tier,
      'is_verified', er.is_verified,
      'ai_context_tags', er.ai_context_tags,
      'ai_instructions', CASE WHEN p_include_ai_instructions THEN er.ai_instructions ELSE NULL END,
      'rating_avg', er.rating_avg,
      'usage_count', er.usage_count,
      'version', er.version,
      'published_at', er.published_at,
      'relevance_score', (
        -- Scoring: tag overlap > text match (per word) > verified
        CASE WHEN p_context_tags != '{}' AND er.ai_context_tags && p_context_tags
          THEN array_length(
            ARRAY(SELECT unnest(er.ai_context_tags) INTERSECT SELECT unnest(p_context_tags)),
            1
          ) * 10
          ELSE 0
        END
        +
        -- Word-level text matching: score per matching word
        CASE WHEN v_words IS NOT NULL THEN
          (SELECT count(*)::int FROM unnest(v_words) AS word
           WHERE er.title ILIKE '%' || word || '%'
              OR er.summary ILIKE '%' || word || '%'
              OR er.body_markdown ILIKE '%' || word || '%'
              OR er.ai_instructions ILIKE '%' || word || '%'
          ) * 5
          ELSE 0
        END
        +
        CASE WHEN er.is_verified THEN 3 ELSE 0 END
      )
    ) AS rule_row
    FROM expert_rules er
    JOIN partner_profiles pp ON pp.id = er.author_partner_id
    LEFT JOIN guild_expertise_areas gea ON gea.id = er.expertise_area_id
    WHERE er.status = 'published'
      AND (er.visibility = 'public' OR (er.visibility = 'members' AND v_is_authenticated))
      AND (p_category IS NULL OR er.category::text = p_category)
      AND (p_expertise_slug IS NULL OR gea.slug = p_expertise_slug)
      AND (
        -- No query: return all (filtered by category/expertise/tags)
        v_words IS NULL
        -- Word match: at least one word matches in any text field
        OR EXISTS (
          SELECT 1 FROM unnest(v_words) AS word
          WHERE er.title ILIKE '%' || word || '%'
             OR er.summary ILIKE '%' || word || '%'
             OR er.body_markdown ILIKE '%' || word || '%'
             OR er.ai_instructions ILIKE '%' || word || '%'
        )
        -- Tag match
        OR (p_context_tags != '{}' AND er.ai_context_tags && p_context_tags)
      )
    ORDER BY (
      CASE WHEN p_context_tags != '{}' AND er.ai_context_tags && p_context_tags
        THEN array_length(
          ARRAY(SELECT unnest(er.ai_context_tags) INTERSECT SELECT unnest(p_context_tags)),
          1
        ) * 10
        ELSE 0
      END
      +
      CASE WHEN v_words IS NOT NULL THEN
        (SELECT count(*)::int FROM unnest(v_words) AS word
         WHERE er.title ILIKE '%' || word || '%'
            OR er.summary ILIKE '%' || word || '%'
        ) * 5
        ELSE 0
      END
      +
      CASE WHEN er.is_verified THEN 3 ELSE 0 END
    ) DESC
    LIMIT p_limit
  ) sub;

  RETURN v_results;
END;
$function$;

REVOKE ALL ON FUNCTION mcp_search_knowledge(text, text, text, text[], boolean, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mcp_search_knowledge(text,text,text,text[],boolean,integer) TO anon;
GRANT EXECUTE ON FUNCTION mcp_search_knowledge(text,text,text,text[],boolean,integer) TO authenticated;
GRANT EXECUTE ON FUNCTION mcp_search_knowledge(text,text,text,text[],boolean,integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_search_knowledge_v3.sql
-- -----------------------------------------------------------------------------

-- Function: mcp_search_knowledge_v3

-- Brick3 locale axis: chunk_locale added to RETURNS TABLE (surfaced).
-- Brick2-guard model identity: p_query_model is a HARD WHERE filter on ke.model /
-- ke.model_v2 — model identity is a CORRECTNESS invariant (a query embedded by model X
-- must only be cosine-compared against chunks embedded by model X), NOT a score term.
-- Brick5 cross-lingual (14-arg): p_locale text DEFAULT NULL appended AFTER p_query_model.
--   * preference-BOOST, never a hard filter (HARD invariant): a chunk whose locale = p_locale
--     gets a small subtraction from its vector distance so it reranks slightly earlier; a
--     non-matching locale still ranks (cross-lingual fallback rides the shared vector space).
--   * variant DEDUP via source_concept_id: locale variants of one source node collapse to one
--     WINNING variant (the item owning the best-scoring chunk), and only that item's chunks are
--     returned. Single-variant concepts are unaffected (winner = the one item → no regression).
-- Brick6 tier-ACL (15-arg): p_audience_user_id uuid DEFAULT NULL appended AFTER p_locale. The
-- WHERE gains a HARD filter audience_user_meets_tier_requirement(ki.minimum_tier, audience_user)
-- so under-tier users never retrieve a gated row. Only service_role may name a different
-- end-user; authenticated callers are pinned to auth.uid() (no tier spoof). The signature
-- changed (14→15), so the prior overloads are DROPped and REVOKE/GRANT re-issued at 15 args.
DROP FUNCTION IF EXISTS public.mcp_search_knowledge_v3(vector,halfvec,text,text[],text,text,text[],boolean,integer,numeric,uuid,text);
DROP FUNCTION IF EXISTS public.mcp_search_knowledge_v3(vector,halfvec,text,text[],text,text,text[],boolean,integer,numeric,uuid,text,text);
DROP FUNCTION IF EXISTS public.mcp_search_knowledge_v3(vector,halfvec,text,text[],text,text,text[],boolean,integer,numeric,uuid,text,text,text);

CREATE OR REPLACE FUNCTION public.mcp_search_knowledge_v3(p_query_embedding_v1 vector DEFAULT NULL::vector, p_query_embedding_v2 halfvec DEFAULT NULL::halfvec, p_query_text text DEFAULT NULL::text, p_item_types text[] DEFAULT NULL::text[], p_category text DEFAULT NULL::text, p_expertise_slug text DEFAULT NULL::text, p_context_tags text[] DEFAULT NULL::text[], p_include_ai_instructions boolean DEFAULT true, p_limit integer DEFAULT 10, p_similarity_threshold numeric DEFAULT 0.3, p_story_id uuid DEFAULT NULL::uuid, p_model_pref text DEFAULT 'v1'::text, p_query_model text DEFAULT NULL::text, p_locale text DEFAULT NULL::text, p_audience_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(knowledge_item_id uuid, chunk_id uuid, chunk_text text, chunk_slug text, similarity numeric, embedding_version text, chunk_locale text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_role text;
  v_caller_id uuid;
  -- Brick6: the end-user whose tier gates retrieval (service may override via the arg; else self).
  v_audience_user uuid;
  -- locale preference nudge (rerank only): a locale match subtracts this from the cosine
  -- distance. Small relative to the [0,2] distance range — a same-language tie-breaker /
  -- gentle preference, never enough to override a materially better cross-lingual hit.
  c_locale_boost constant numeric := 0.05;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  -- ── RBAC: Per-story access check (ported verbatim from mcp_search_knowledge_v2) ─
  v_caller_role := public.get_jwt_role();
  v_caller_id := auth.uid();

  IF p_story_id IS NOT NULL AND v_caller_role IS DISTINCT FROM 'service_role' THEN
    IF NOT (
      public.is_admin_or_staff()
      OR EXISTS (
        SELECT 1 FROM public.partner_stories ps
        WHERE ps.id = p_story_id AND ps.user_id = v_caller_id
      )
      OR EXISTS (
        SELECT 1 FROM public.story_participants sp
        WHERE sp.story_id = p_story_id AND sp.user_id = v_caller_id
      )
    ) THEN
      RAISE EXCEPTION 'Access denied to story %', p_story_id
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Brick6 tier-ACL audience identity: only service_role (trusted orchestration) may name a
  -- different end-user via p_audience_user_id; authenticated callers are pinned to themselves
  -- (no tier spoofing). The tier check itself fails closed (unknown user ⇒ anonymous).
  v_audience_user := CASE
    WHEN v_caller_role = 'service_role' THEN COALESCE(p_audience_user_id, auth.uid())
    ELSE auth.uid()
  END;

  IF p_model_pref = 'v2' THEN
    IF p_query_embedding_v2 IS NULL THEN
      RAISE EXCEPTION 'p_query_embedding_v2 is required when p_model_pref = v2';
    END IF;
    RETURN QUERY
    WITH scored AS (
      SELECT
        ke.knowledge_item_id AS s_item_id,
        ke.chunk_id AS s_chunk_id,
        kc.chunk_text AS s_chunk_text,
        (COALESCE(ki.source_slug, ki.id::text) || ':' || kc.chunk_index)::text AS s_chunk_slug,
        (1 - (ke.embedding_v2 <=> p_query_embedding_v2))::numeric AS s_similarity,
        kc.locale AS s_chunk_locale,
        -- COALESCE so a NULL source_concept_id (trigger-bypassed insert, bulk load, or a
        -- not-yet-backfilled row) degrades to "own item = its own concept" (a singleton, no
        -- dedup) instead of NULL — a NULL concept would drop the row at the winner JOIN.
        COALESCE(ki.source_concept_id, ki.id) AS s_concept,
        (ke.embedding_v2 <=> p_query_embedding_v2)
          - CASE WHEN p_locale IS NOT NULL AND kc.locale = p_locale THEN c_locale_boost ELSE 0 END AS s_eff_dist
      FROM public.knowledge_embeddings ke
      JOIN public.knowledge_chunks kc ON kc.id = ke.chunk_id
      JOIN public.knowledge_items ki ON ki.id = ke.knowledge_item_id
     WHERE ke.embedding_v2 IS NOT NULL
       AND ki.status = 'active'
       AND ki.quarantine_status NOT IN ('flagged', 'quarantined')
       AND (p_item_types IS NULL OR ki.item_type::text = ANY(p_item_types))
       AND (p_category IS NULL OR ki.category = p_category)
       AND (
         ki.item_type::text IN ('core_value', 'personality_trait')
         OR (p_story_id IS NULL AND ki.story_id IS NULL)
         OR (p_story_id IS NOT NULL AND (ki.story_id = p_story_id OR ki.story_id IS NULL))
       )
       -- Brick2-guard: HARD model-identity filter (correctness, not a score term).
       AND (p_query_model IS NULL OR ke.model_v2 = p_query_model)
       -- Brick6 tier-ACL: HARD filter — an under-tier audience user never retrieves a gated row.
       AND (ki.minimum_tier IS NULL OR public.audience_user_meets_tier_requirement(ki.minimum_tier, v_audience_user))
       AND (1 - (ke.embedding_v2 <=> p_query_embedding_v2)) >= p_similarity_threshold
    ),
    winner AS (
      -- one winning variant (knowledge_item) per source-concept: the item owning the
      -- best (locale-boosted) chunk. Collapses cross-lingual near-duplicates.
      SELECT DISTINCT ON (s_concept) s_concept, s_item_id
      FROM scored ORDER BY s_concept, s_eff_dist ASC, s_item_id
    )
    SELECT s.s_item_id, s.s_chunk_id, s.s_chunk_text, s.s_chunk_slug, s.s_similarity,
           'v2'::text, s.s_chunk_locale
    FROM scored s
    JOIN winner w ON w.s_concept = s.s_concept AND w.s_item_id = s.s_item_id
    ORDER BY s.s_eff_dist ASC
    LIMIT p_limit;
  ELSE
    IF p_query_embedding_v1 IS NULL THEN
      RAISE EXCEPTION 'p_query_embedding_v1 is required when p_model_pref = v1';
    END IF;
    RETURN QUERY
    WITH scored AS (
      SELECT
        ke.knowledge_item_id AS s_item_id,
        ke.chunk_id AS s_chunk_id,
        kc.chunk_text AS s_chunk_text,
        (COALESCE(ki.source_slug, ki.id::text) || ':' || kc.chunk_index)::text AS s_chunk_slug,
        (1 - (ke.embedding <=> p_query_embedding_v1))::numeric AS s_similarity,
        kc.locale AS s_chunk_locale,
        -- COALESCE so a NULL source_concept_id (trigger-bypassed insert, bulk load, or a
        -- not-yet-backfilled row) degrades to "own item = its own concept" (a singleton, no
        -- dedup) instead of NULL — a NULL concept would drop the row at the winner JOIN.
        COALESCE(ki.source_concept_id, ki.id) AS s_concept,
        (ke.embedding <=> p_query_embedding_v1)
          - CASE WHEN p_locale IS NOT NULL AND kc.locale = p_locale THEN c_locale_boost ELSE 0 END AS s_eff_dist
      FROM public.knowledge_embeddings ke
      JOIN public.knowledge_chunks kc ON kc.id = ke.chunk_id
      JOIN public.knowledge_items ki ON ki.id = ke.knowledge_item_id
     WHERE ke.embedding IS NOT NULL
       AND ki.status = 'active'
       AND ki.quarantine_status NOT IN ('flagged', 'quarantined')
       AND (p_item_types IS NULL OR ki.item_type::text = ANY(p_item_types))
       AND (p_category IS NULL OR ki.category = p_category)
       AND (
         ki.item_type::text IN ('core_value', 'personality_trait')
         OR (p_story_id IS NULL AND ki.story_id IS NULL)
         OR (p_story_id IS NOT NULL AND (ki.story_id = p_story_id OR ki.story_id IS NULL))
       )
       -- Brick2-guard: HARD model-identity filter (correctness, not a score term).
       AND (p_query_model IS NULL OR ke.model = p_query_model)
       -- Brick6 tier-ACL: HARD filter — an under-tier audience user never retrieves a gated row.
       AND (ki.minimum_tier IS NULL OR public.audience_user_meets_tier_requirement(ki.minimum_tier, v_audience_user))
       AND (1 - (ke.embedding <=> p_query_embedding_v1)) >= p_similarity_threshold
    ),
    winner AS (
      SELECT DISTINCT ON (s_concept) s_concept, s_item_id
      FROM scored ORDER BY s_concept, s_eff_dist ASC, s_item_id
    )
    SELECT s.s_item_id, s.s_chunk_id, s.s_chunk_text, s.s_chunk_slug, s.s_similarity,
           'v1'::text, s.s_chunk_locale
    FROM scored s
    JOIN winner w ON w.s_concept = s.s_concept AND w.s_item_id = s.s_item_id
    ORDER BY s.s_eff_dist ASC
    LIMIT p_limit;
  END IF;
END;
$function$
;

REVOKE ALL ON FUNCTION mcp_search_knowledge_v3(vector,halfvec,text,text[],text,text,text[],boolean,integer,numeric,uuid,text,text,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mcp_search_knowledge_v3(vector,halfvec,text,text[],text,text,text[],boolean,integer,numeric,uuid,text,text,text,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION mcp_search_knowledge_v3(vector,halfvec,text,text[],text,text,text[],boolean,integer,numeric,uuid,text,text,text,uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_store_agent_memory.sql
-- -----------------------------------------------------------------------------

-- Function: mcp_store_agent_memory

CREATE OR REPLACE FUNCTION public.mcp_store_agent_memory(p_agent_slug text, p_memory_type text, p_content text, p_importance integer DEFAULT 5, p_user_id uuid DEFAULT NULL::uuid, p_run_id uuid DEFAULT NULL::uuid, p_ttl_hours integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_memory_id uuid;
  v_expires timestamptz;
BEGIN
  -- Authorization: non-elevated callers may only write memories for themselves
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
    END IF;
    IF p_user_id IS NOT NULL AND p_user_id <> auth.uid() THEN
      RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
    END IF;
    p_user_id := auth.uid();
  END IF;

  -- Validate agent exists
  IF NOT EXISTS (SELECT 1 FROM agent_catalog WHERE slug = p_agent_slug AND is_active = true) THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Agent not found: ' || p_agent_slug);
  END IF;

  -- Calculate expiry
  IF p_ttl_hours IS NOT NULL AND p_ttl_hours > 0 THEN
    v_expires := now() + (p_ttl_hours || ' hours')::interval;
  END IF;

  INSERT INTO agent_memories (agent_slug, user_id, memory_type, content, importance, source_run_id, expires_at)
  VALUES (p_agent_slug, p_user_id, p_memory_type, p_content, p_importance, p_run_id, v_expires)
  RETURNING id INTO v_memory_id;

  RETURN jsonb_build_object(
    'status', 'ok',
    'memory_id', v_memory_id,
    'expires_at', v_expires
  );
END;
$function$;

REVOKE ALL ON FUNCTION mcp_store_agent_memory(text, text, text, integer, uuid, uuid, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mcp_store_agent_memory(text,text,text,integer,uuid,uuid,integer) TO authenticated;
GRANT EXECUTE ON FUNCTION mcp_store_agent_memory(text,text,text,integer,uuid,uuid,integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_summarize_agent_memories.sql
-- -----------------------------------------------------------------------------

-- Function: mcp_summarize_agent_memories
-- Security: SECURITY DEFINER (bypasses RLS on agent_memories) + caller-scoped p_user_id.
--   2026-07-15 IDOR fix (docs/security/IDOR_P_USER_ID_AUDIT_2026-07-15.md): p_user_id defaults to
--   NULL and every predicate treated a NULL p_user_id as "match every user". Granted to
--   `authenticated`, omitting the argument returned a cross-user census — total count, a breakdown
--   by memory_type, and the top-5 memory CONTENTS (200 chars each, PII) over every user of that
--   agent. Same wildcard defect as mcp_get_agent_memories; fixed the same way, so the two cannot
--   drift apart.

CREATE OR REPLACE FUNCTION public.mcp_summarize_agent_memories(p_agent_slug text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_summary jsonb;
  v_total integer;
  v_by_type jsonb;
  v_top_memories jsonb;
  v_user_id uuid;
BEGIN
  -- Resolve the effective scope BEFORE reading. service_role (the MCP/agent runtimes) and
  -- admin/staff keep the cross-user wildcard; everyone else is pinned to themselves, so a
  -- NULL p_user_id collapses to "my memories" instead of "everyone's".
  IF public.is_service_role() OR public.is_admin_or_staff() THEN
    v_user_id := p_user_id;
  ELSE
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
    END IF;
    IF p_user_id IS NOT NULL AND p_user_id <> auth.uid() THEN
      RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
    END IF;
    v_user_id := auth.uid();
  END IF;

  -- Count total active memories
  SELECT count(*) INTO v_total
  FROM agent_memories am
  WHERE am.agent_slug = p_agent_slug
    AND (v_user_id IS NULL OR am.user_id = v_user_id)
    AND (am.expires_at IS NULL OR am.expires_at > now());

  -- Count by type
  SELECT COALESCE(jsonb_object_agg(memory_type, cnt), '{}'::jsonb) INTO v_by_type
  FROM (
    SELECT am.memory_type, count(*) as cnt
    FROM agent_memories am
    WHERE am.agent_slug = p_agent_slug
      AND (v_user_id IS NULL OR am.user_id = v_user_id)
      AND (am.expires_at IS NULL OR am.expires_at > now())
    GROUP BY am.memory_type
  ) sub;

  -- Top 5 by importance
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'memory_type', am.memory_type,
    'content', left(am.content, 200),
    'importance', am.importance
  ) ORDER BY am.importance DESC, am.created_at DESC), '[]'::jsonb)
  INTO v_top_memories
  FROM (
    SELECT am2.memory_type, am2.content, am2.importance, am2.created_at
    FROM agent_memories am2
    WHERE am2.agent_slug = p_agent_slug
      AND (v_user_id IS NULL OR am2.user_id = v_user_id)
      AND (am2.expires_at IS NULL OR am2.expires_at > now())
    ORDER BY am2.importance DESC, am2.created_at DESC
    LIMIT 5
  ) am;

  RETURN jsonb_build_object(
    'status', 'ok',
    'agent_slug', p_agent_slug,
    'total_memories', v_total,
    'by_type', v_by_type,
    'top_memories', v_top_memories
  );
END;
$function$;

REVOKE ALL ON FUNCTION mcp_summarize_agent_memories(text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mcp_summarize_agent_memories(text,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION mcp_summarize_agent_memories(text,uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/merge_stories_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.merge_stories_audited
-- Merges one story INTO another ("slučování do celku"): all of the source story's
-- content moves into the target, and the source is left as a 'merged' stub that points
-- at the target. The inverse of promote_entry_to_story_audited (which branches OUT).
--
-- Additive evolution — reuses the move pattern + existing primitives, touches nothing
-- existing (the promote story_links/graph dual-track stays as-is; merge is a separate op).
-- Nothing is deleted: the source story survives as status='merged' with a 'related_to'
-- link to the target, so dependents that still reference it can follow the pointer.
--
-- What follows the merge (handled here so the merge does not corrupt structure):
--   * story_entries          → re-homed to target (entry-tree intact; stamped merged_from)
--   * knowledge_items.story_id → re-scoped to target (RAG isolation follows the content,
--                                so retrieval stays gated by the RIGHT story)
--   * story_reminders        → re-pointed to target
--   * story_participants     → unioned into target (people keep access to merged content)
--   * partner_stories.status → source set to 'merged' + a 'related_to' merged_into link
--
-- Authorization: caller must access BOTH stories (partner owner / member owner /
-- participant / admin-staff) or be service_role.
-- Security: SECURITY DEFINER.
-- @audit: required

CREATE OR REPLACE FUNCTION public.merge_stories_audited(
  p_source_story_id uuid,
  p_target_story_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_is_service boolean := current_setting('role', true) = 'service_role';
  v_user_id    uuid := auth.uid();
  v_partner_id uuid;
  v_source     public.partner_stories%ROWTYPE;
  v_target     public.partner_stories%ROWTYPE;
  v_can_source boolean;
  v_can_target boolean;
  v_entries     integer;
  v_knowledge   integer;
  v_reminders   integer;
  v_participants integer;
BEGIN
  IF v_user_id IS NULL AND NOT v_is_service THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_source FROM public.partner_stories WHERE id = p_source_story_id;
  SELECT * INTO v_target FROM public.partner_stories WHERE id = p_target_story_id;
  IF v_source.id IS NULL THEN RAISE EXCEPTION 'Source story not found: %', p_source_story_id USING ERRCODE = '22023'; END IF;
  IF v_target.id IS NULL THEN RAISE EXCEPTION 'Target story not found: %', p_target_story_id USING ERRCODE = '22023'; END IF;
  IF v_source.id = v_target.id THEN RAISE EXCEPTION 'Cannot merge a story into itself' USING ERRCODE = '22023'; END IF;

  -- Authorization: access to BOTH stories.
  v_partner_id := public.get_current_partner_id();
  v_can_source := v_is_service
    OR (v_partner_id IS NOT NULL AND v_partner_id = v_source.partner_id)
    OR (v_user_id IS NOT NULL AND v_user_id = v_source.user_id)
    OR (v_user_id IS NOT NULL AND public.is_story_participant(v_user_id, v_source.id))
    OR (v_user_id IS NOT NULL AND public.is_admin_or_staff(v_user_id));
  v_can_target := v_is_service
    OR (v_partner_id IS NOT NULL AND v_partner_id = v_target.partner_id)
    OR (v_user_id IS NOT NULL AND v_user_id = v_target.user_id)
    OR (v_user_id IS NOT NULL AND public.is_story_participant(v_user_id, v_target.id))
    OR (v_user_id IS NOT NULL AND public.is_admin_or_staff(v_user_id));
  IF NOT (v_can_source AND v_can_target) THEN
    RAISE EXCEPTION 'Unauthorized: need access to both the source and the target story'
      USING ERRCODE = '42501';
  END IF;

  -- (1) Re-home all source entries (the entry-tree moves wholesale → parent_id stays valid).
  UPDATE public.story_entries
     SET story_id = p_target_story_id,
         metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('merged_from_story_id', p_source_story_id)
   WHERE story_id = p_source_story_id;
  GET DIAGNOSTICS v_entries = ROW_COUNT;

  -- (2) Re-scope vectorized content so RAG isolation follows the content to the target.
  UPDATE public.knowledge_items SET story_id = p_target_story_id WHERE story_id = p_source_story_id;
  GET DIAGNOSTICS v_knowledge = ROW_COUNT;

  -- (3) Re-point reminders.
  UPDATE public.story_reminders SET story_id = p_target_story_id WHERE story_id = p_source_story_id;
  GET DIAGNOSTICS v_reminders = ROW_COUNT;

  -- (4) Union participants (people keep access to the merged content).
  INSERT INTO public.story_participants (story_id, user_id, role)
  SELECT p_target_story_id, sp.user_id, sp.role
    FROM public.story_participants sp
   WHERE sp.story_id = p_source_story_id
  ON CONFLICT (story_id, user_id, role) DO NOTHING;
  GET DIAGNOSTICS v_participants = ROW_COUNT;

  -- (5) Leave the source as a 'merged' stub that points at the target (nothing deleted).
  UPDATE public.partner_stories SET status = 'merged', last_activity_at = now() WHERE id = p_source_story_id;
  UPDATE public.partner_stories SET last_activity_at = now() WHERE id = p_target_story_id;

  INSERT INTO public.story_links
    (source_story_id, target_story_id, link_type, link_direction, created_by, confidence_score, is_accepted, metadata)
  VALUES
    (p_source_story_id, p_target_story_id, 'related_to', 'forward', v_user_id, 1.0, true,
     jsonb_build_object('relation', 'merged_into'))
  ON CONFLICT (source_story_id, target_story_id, link_type) DO NOTHING;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_user_id, 'STORY_MERGED',
    jsonb_build_object(
      'area',             'collaboration',
      'severity',         'notice',
      'source_story_id',  p_source_story_id,
      'target_story_id',  p_target_story_id,
      'merged_entries',   v_entries,
      'merged_knowledge', v_knowledge,
      'merged_reminders', v_reminders,
      'merged_participants', v_participants));

  RETURN jsonb_build_object(
    'source_story_id',  p_source_story_id,
    'target_story_id',  p_target_story_id,
    'merged_entries',   v_entries,
    'merged_knowledge', v_knowledge,
    'merged_reminders', v_reminders,
    'merged_participants', v_participants);
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.merge_stories_audited(uuid, uuid) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.merge_stories_audited(uuid, uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.merge_stories_audited(uuid, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.merge_stories_audited(uuid, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/migrate_app_secrets_to_vault.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: migrate_app_secrets_to_vault
-- Popis: IDEMPOTENTNÍ převod nešifrovaných řádků `app_secrets` do trezoru
--        (vault.secrets, šifrovaně). Volá ho heals při každém nasazení: klíč se
--        přenese JEN tam, kde ho trezor ještě nemá — hodnota, kterou mezitím
--        někdo nastavil v administraci (set_api_key_admin → trezor), se nepřepíše.
--
-- ⛔ PROČ (naměřeno 2026-09-28): set_api_key_admin psal vedle trezoru i
-- nešifrovanou kopii a get_app_secret/_batch četly právě ji. Po převodu čtou
-- všichni trezor a tabulka nemá grant pro nikoho (grants/app_secrets.sql).
--
-- Řádky v app_secrets NEMAŽE: smazání až po ověření sondou (návrh „jeden domov
-- pověření" §4) — smazat hodnotu dřív, než se ověří, že ji čtenář najde v
-- trezoru, by byla ztráta klíče. Vrací jen POČET převedených klíčů — žádné
-- hodnoty ani názvy (výstup heals jde do logu nasazení).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.migrate_app_secrets_to_vault()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  r record;
  n integer := 0;
BEGIN
  FOR r IN
    SELECT s.key, s.value
      FROM public.app_secrets s
     WHERE coalesce(s.value, '') <> ''
       AND NOT EXISTS (SELECT 1 FROM vault.secrets v WHERE v.name = s.key)
     ORDER BY s.key
  LOOP
    PERFORM vault.create_secret(
      r.value,
      r.key,
      jsonb_build_object('migrated_from', 'app_secrets')::text
    );
    n := n + 1;
  END LOOP;
  RETURN n;
END;
$$;

REVOKE ALL ON FUNCTION public.migrate_app_secrets_to_vault() FROM PUBLIC, anon, authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mirror_story_entries_subject.sql
-- -----------------------------------------------------------------------------

-- Function: public.mirror_story_entries_subject
-- Makes the documented legacy-story binding guarantee durable: when a story_entries
-- row is inserted with only the legacy story_id set (no polymorphic subject_id),
-- mirror it into (subject_type='story', subject_id=story_id). story_entries.subject_id
-- is NOT NULL with no default, so without this the seed + any legacy direct insert
-- would violate the not-null constraint. The discussion RPC
-- (create_discussion_entry_audited) sets subject_id explicitly, so this is a no-op
-- for it — it only backfills the legacy story_id-only path.

CREATE OR REPLACE FUNCTION public.mirror_story_entries_subject()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.subject_id IS NULL AND NEW.story_id IS NOT NULL THEN
    NEW.subject_id := NEW.story_id;
    -- subject_type defaults to 'story'; keep it consistent for the mirrored row.
    IF NEW.subject_type IS NULL OR NEW.subject_type = '' THEN
      NEW.subject_type := 'story';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/moderate_development_flow.sql
-- -----------------------------------------------------------------------------

-- Function: moderate_development_flow

CREATE OR REPLACE FUNCTION public.moderate_development_flow(p_session_type text, p_story_id uuid DEFAULT NULL::uuid, p_tech_stack jsonb DEFAULT '[]'::jsonb, p_file_paths text[] DEFAULT '{}'::text[], p_diff_summary text DEFAULT NULL::text, p_expertise_level text DEFAULT 'intermediate'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_session_id uuid;
  v_rules jsonb := '[]'::jsonb;
  v_context_bundle jsonb := '{}'::jsonb;
  v_expertise_hints jsonb := '{}'::jsonb;
  v_story_ctx jsonb;
  v_tech_tags text[];
  v_pinned uuid[];
  v_categories expert_rule_category[];
  v_compliance boolean;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  -- Validate session_type
  IF p_session_type NOT IN ('chat_flow', 'pre_commit', 'pr_review', 'test_strategy', 'architecture', 'estimation') THEN
    RAISE EXCEPTION USING MESSAGE = format('Invalid session_type: %s', p_session_type), ERRCODE = 'P0001';
  END IF;

  -- Stráž (can_access_story.sql) — story je volitelná; když je zadaná, relace se k ní
  -- neváže a její kontext se nevrací, pokud na ni volající nesmí.
  IF p_story_id IS NOT NULL AND NOT public.can_access_story(p_story_id) THEN
    RAISE EXCEPTION 'Access denied to story %', p_story_id USING ERRCODE = '42501';
  END IF;

  -- Create moderation session
  INSERT INTO moderation_sessions (user_id, story_id, session_type, expertise_level, tech_stack)
  VALUES (v_user_id, p_story_id, p_session_type, p_expertise_level, p_tech_stack)
  RETURNING id INTO v_session_id;

  -- Extract tech stack tags for rule matching
  SELECT array_agg(t.value::text)
  INTO v_tech_tags
  FROM jsonb_array_elements_text(p_tech_stack) AS t(value);

  -- ⛔ NAMĚŘENO 2026-09-14: filtr porovnával enum expert_rule_category s literály
  -- 'testing'/'quality'/'compliance'/'security'/'architecture'/'patterns', které
  -- v enumu nejsou → 22P02 KAŽDÉMU volajícímu, jakmile existovalo pravidlo. Pod tím
  -- se schovávala druhá vada: ORDER BY/LIMIT stály na agregačním dotazu, ne na
  -- pravidlech. Mapování (rozhodnuto 2026-09-14):
  --   compliance = pravidla PŘIPNUTÁ ke story (story_rulesets.rule_ids — týž zdroj
  --                jako mcp_get_compliance_context); u pr_review/pre_commit severity
  --                error a patří do výběru bez ohledu na kategorii. Bez story žádná.
  --   quality    = coding_standard + performance_optimization
  --   security   = security_practice (error vždy)
  --   testing    = testing_strategy
  --   architecture/patterns = architecture_pattern + integration_pattern + data_modeling
  -- Kategorie jsou TYPOVANÉ pole: neplatná hodnota padne při prvním volání
  -- a runtime test volá každý session_type.
  IF p_story_id IS NOT NULL THEN
    SELECT sr.rule_ids INTO v_pinned
    FROM story_contexts sc
    JOIN story_rulesets sr ON sr.id = sc.ruleset_id
    WHERE sc.story_id = p_story_id;
  END IF;
  v_pinned := COALESCE(v_pinned, '{}'::uuid[]);

  v_categories := CASE p_session_type
    WHEN 'test_strategy' THEN ARRAY['testing_strategy', 'coding_standard', 'performance_optimization']::expert_rule_category[]
    WHEN 'pr_review'     THEN ARRAY['coding_standard', 'performance_optimization', 'security_practice', 'testing_strategy']::expert_rule_category[]
    WHEN 'pre_commit'    THEN ARRAY['coding_standard', 'performance_optimization', 'security_practice']::expert_rule_category[]
    WHEN 'architecture'  THEN ARRAY['architecture_pattern', 'integration_pattern', 'data_modeling']::expert_rule_category[]
    ELSE NULL  -- chat_flow, estimation: všechna publikovaná pravidla
  END;
  v_compliance := p_session_type IN ('pr_review', 'pre_commit');

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'slug', r.slug,
      'title', r.title,
      'category', r.category,
      'ai_instructions', r.ai_instructions,
      'pinned', r.pinned,
      'severity', CASE
        WHEN v_compliance AND r.pinned THEN 'error'
        WHEN r.category = 'security_practice'::expert_rule_category THEN 'error'
        ELSE 'warning'
      END
    ) ORDER BY r.pinned DESC, r.slug
  ), '[]'::jsonb)
  INTO v_rules
  FROM (
    SELECT er.slug, er.title, er.category, er.ai_instructions,
           er.id = ANY(v_pinned) AS pinned
    FROM expert_rules er
    WHERE er.status = 'published'
      AND (
        v_categories IS NULL
        OR er.category = ANY(v_categories)
        OR (v_compliance AND er.id = ANY(v_pinned))
      )
    ORDER BY (er.id = ANY(v_pinned)) DESC, er.slug
    LIMIT 30
  ) r;

  -- Load story context if available
  IF p_story_id IS NOT NULL THEN
    SELECT jsonb_build_object(
      'story_id', ps.id,
      'title', ps.title,
      'delivery_status', ps.delivery_status,
      'tech_stack', ps.tech_stack,
      'risk_profile', ps.risk_profile,
      'domain', ps.domain
    ) INTO v_story_ctx
    FROM partner_stories ps
    WHERE ps.id = p_story_id;

    IF v_story_ctx IS NOT NULL THEN
      v_context_bundle := v_context_bundle || jsonb_build_object('story', v_story_ctx);
    END IF;
  END IF;

  -- Build guidance contract from expertise level (replaces simple verbosity hints)
  v_expertise_hints := build_guidance_contract(p_expertise_level);

  -- Add file context
  IF array_length(p_file_paths, 1) > 0 THEN
    v_context_bundle := v_context_bundle || jsonb_build_object('file_paths', to_jsonb(p_file_paths));
  END IF;

  -- Add diff summary
  IF p_diff_summary IS NOT NULL THEN
    v_context_bundle := v_context_bundle || jsonb_build_object('diff_summary', p_diff_summary);
  END IF;

  -- Add tech stack to context
  v_context_bundle := v_context_bundle || jsonb_build_object('tech_stack', p_tech_stack);

  RETURN jsonb_build_object(
    'session_id', v_session_id,
    'rules', v_rules,
    'context_bundle', v_context_bundle,
    'expertise_hints', v_expertise_hints
  );
END;
$function$;

REVOKE ALL ON FUNCTION moderate_development_flow(text, uuid, jsonb, text[], text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION moderate_development_flow(text,uuid,jsonb,text[],text,text) TO authenticated;
GRANT EXECUTE ON FUNCTION moderate_development_flow(text,uuid,jsonb,text[],text,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/move_story_entry_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.move_story_entry_audited
-- Moves a story_entry (e.g. an inbound mail) — together with its reply subtree — to a
-- DIFFERENT story. "Mail můžu přesunout do jiné story protože k ní patří": because the
-- STORY is the ACL boundary (story_entries RLS keys off story access), re-homing an
-- entry changes the scope of who/how/when it can be reached. The inverse-ish of
-- promote_entry_to_story_audited (which spins a record out into its OWN child story).
--
-- Invariants:
--   * the whole subtree rooted at the entry moves together (a thread stays intact);
--   * the root entry's parent_id is cleared (it was a reply in the source story; in the
--     target it becomes a top-level entry) — descendants keep their in-subtree parents;
--   * provenance: the root entry is stamped metadata.moved_from_story_id + moved_at.
--
-- Authorization: the caller must be able to access BOTH the source and the target story
-- (partner owner / member owner / participant / admin-staff) — or be service_role.
-- This prevents moving a record into (or out of) a story the caller cannot see.
--
-- Security: SECURITY DEFINER.
-- @audit: required

CREATE OR REPLACE FUNCTION public.move_story_entry_audited(
  p_entry_id        uuid,
  p_target_story_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_is_service boolean := current_setting('role', true) = 'service_role';
  v_user_id    uuid := auth.uid();
  v_partner_id uuid;
  v_entry      public.story_entries%ROWTYPE;
  v_source     public.partner_stories%ROWTYPE;
  v_target     public.partner_stories%ROWTYPE;
  v_can_source boolean;
  v_can_target boolean;
  v_count      integer;
BEGIN
  IF v_user_id IS NULL AND NOT v_is_service THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_entry FROM public.story_entries WHERE id = p_entry_id;
  IF v_entry.id IS NULL THEN
    RAISE EXCEPTION 'Story entry not found: %', p_entry_id USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_source FROM public.partner_stories WHERE id = v_entry.story_id;
  SELECT * INTO v_target FROM public.partner_stories WHERE id = p_target_story_id;
  IF v_target.id IS NULL THEN
    RAISE EXCEPTION 'Target story not found: %', p_target_story_id USING ERRCODE = '22023';
  END IF;
  IF v_source.id = v_target.id THEN
    RAISE EXCEPTION 'Entry is already in the target story' USING ERRCODE = '22023';
  END IF;

  -- Authorization: access to BOTH stories.
  v_partner_id := public.get_current_partner_id();
  v_can_source := v_is_service
    OR (v_partner_id IS NOT NULL AND v_partner_id = v_source.partner_id)
    OR (v_user_id IS NOT NULL AND v_user_id = v_source.user_id)
    OR (v_user_id IS NOT NULL AND public.is_story_participant(v_user_id, v_source.id))
    OR (v_user_id IS NOT NULL AND public.is_admin_or_staff(v_user_id));
  v_can_target := v_is_service
    OR (v_partner_id IS NOT NULL AND v_partner_id = v_target.partner_id)
    OR (v_user_id IS NOT NULL AND v_user_id = v_target.user_id)
    OR (v_user_id IS NOT NULL AND public.is_story_participant(v_user_id, v_target.id))
    OR (v_user_id IS NOT NULL AND public.is_admin_or_staff(v_user_id));

  IF NOT (v_can_source AND v_can_target) THEN
    RAISE EXCEPTION 'Unauthorized: need access to both the source and the target story'
      USING ERRCODE = '42501';
  END IF;

  -- Move the whole subtree rooted at the entry. Root: clear parent_id + stamp provenance.
  WITH RECURSIVE subtree AS (
    SELECT id FROM public.story_entries WHERE id = p_entry_id
    UNION ALL
    SELECT se.id FROM public.story_entries se JOIN subtree s ON se.parent_id = s.id
  )
  UPDATE public.story_entries se
     SET story_id  = p_target_story_id,
         parent_id = CASE WHEN se.id = p_entry_id THEN NULL ELSE se.parent_id END,
         metadata  = CASE WHEN se.id = p_entry_id
                          THEN COALESCE(se.metadata, '{}'::jsonb)
                               || jsonb_build_object('moved_from_story_id', v_source.id, 'moved_at', now())
                          ELSE se.metadata END
   WHERE se.id IN (SELECT id FROM subtree);
  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- Bump activity on both ends (UPDATE does not fire the insert-time activity trigger).
  UPDATE public.partner_stories SET last_activity_at = now() WHERE id IN (v_source.id, v_target.id);

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_user_id, 'STORY_ENTRY_MOVED',
    jsonb_build_object(
      'area',          'collaboration',
      'severity',      'notice',
      'entry_id',      p_entry_id,
      'from_story_id', v_source.id,
      'to_story_id',   v_target.id,
      'moved_count',   v_count));

  RETURN jsonb_build_object(
    'entry_id',      p_entry_id,
    'from_story_id', v_source.id,
    'to_story_id',   v_target.id,
    'moved_count',   v_count);
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.move_story_entry_audited(uuid, uuid) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.move_story_entry_audited(uuid, uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.move_story_entry_audited(uuid, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.move_story_entry_audited(uuid, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/navrhni_nase_firmy_z_agend.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: navrhni_nase_firmy_z_agend
-- Popis: NÁVRH „naše firma" pro každou instanci zdroje, která se objevila v datech
--        (klíč původu `@instance`, např. agenda Money „money/Areál Drutěva, družstvo")
--        a o které ještě nikdo nerozhodl. Návrh = twin_external_refs ref_kind
--        'nase_firma' ve stavu proposed (source = druh zdroje, source_key = jméno
--        instance) na firmě téhož jména; když firma není, založí se. Schvaluje člověk
--        ve frontě identifikátorů (review_queue twin_identity) — jedním potvrzením;
--        potvrzený název je zároveň SCHVÁLENÝ název firmy (counterparty_resolve).
--        ⭐ Majitel 2026-09-28: „až příště přidáme novou agendu z Money… aby nám to
--        odhalil a doporučil ve správě ingestu a stačilo to jen potvrdit".
--        Zamítnutý návrh se znovu nenavrhne (rozhodnutí člověka platí).
--        Jméno instance přichází ze ZÁZNAMU KONEKTORU, ne z pole vytaženého ingestem.
-- Volá: trigger li_doc_scope_keys_nase_firmy (nové instance) a heals (jednorázově).
-- Bezpečnost: SECURITY DEFINER bez grantů — volá jen vlastník (trigger, migrace).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.navrhni_nase_firmy_z_agend(p_zobrazeni text[] DEFAULT NULL)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  r      record;
  v_twin uuid;
  v_n    integer := 0;
BEGIN
  FOR r IN
    SELECT split_part(k.zobrazeni, '/', 1)                             AS druh,
           btrim(substr(k.zobrazeni, strpos(k.zobrazeni, '/') + 1))    AS jmeno,
           count(DISTINCT k.source_sha256)                             AS dokladu
      FROM public.li_doc_scope_keys k
     WHERE k.field_key = '@instance'
       AND k.zobrazeni IS NOT NULL
       AND strpos(k.zobrazeni, '/') > 1
       AND (p_zobrazeni IS NULL OR k.zobrazeni = ANY (p_zobrazeni))
     GROUP BY 1, 2
  LOOP
    CONTINUE WHEN r.jmeno = '';
    -- O instanci už někdo rozhodl (navrženo, schváleno i zamítnuto) → nic.
    CONTINUE WHEN EXISTS (SELECT 1 FROM public.twin_external_refs x
                           WHERE x.ref_kind = 'nase_firma' AND x.source = r.druh
                             AND lower(x.source_key) = lower(r.jmeno));
    v_twin := NULL;
    SELECT t.id INTO v_twin
      FROM public.twin_entities t
     WHERE t.entity_type = 'company' AND t.status = 'active'
       AND lower(btrim(t.label)) = lower(r.jmeno)
     ORDER BY t.created_at
     LIMIT 1;
    IF v_twin IS NULL THEN
      INSERT INTO public.twin_entities (entity_type, label)
      VALUES ('company', r.jmeno)
      RETURNING id INTO v_twin;
    END IF;
    INSERT INTO public.twin_external_refs (twin_id, source, source_key, ref_kind, state, proposed_by, confidence, note)
    VALUES (v_twin, r.druh, r.jmeno, 'nase_firma', 'proposed', 'ingest:' || r.druh, 1.0,
            format('nová agenda v datech zdroje %s (%s dokladů)', r.druh, r.dokladu));
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END;
$$;

REVOKE ALL ON FUNCTION public.navrhni_nase_firmy_z_agend(text[]) FROM PUBLIC;
COMMENT ON FUNCTION public.navrhni_nase_firmy_z_agend(text[]) IS
  'Návrh „naše firma" (twin_external_refs nase_firma, proposed) pro instance zdroje z dat, o kterých ještě nikdo nerozhodl; firmu téhož jména najde, jinak založí. Schvaluje člověk ve frontě identifikátorů.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_li_doc_scope_keys_nase_firmy.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: fn_li_doc_scope_keys_nase_firmy (trigger, po příkazu)
-- Popis: Když do klíčů původu přibude instance zdroje, o které ještě nikdo nerozhodl
--        (nová agenda Money…), vznikne návrh „naše firma" (navrhni_nase_firmy_z_agend).
--        Po příkazu s tabulkou přechodu: přestavba klíčů (stovky tisíc řádků) = jedno
--        volání; běžný zápis dokladu známé agendy skončí na NOT EXISTS bez práce.
-- Pár: triggers/li_doc_scope_keys_nase_firmy.sql
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_li_doc_scope_keys_nase_firmy()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_nove text[];
BEGIN
  -- Nejdřív ODLIŠNÉ instance (přestavba = desítky tisíc řádků `@instance`, instancí
  -- jednotky), teprve na nich dotaz do twin_external_refs — ne jednou za řádek.
  SELECT array_agg(d.z) INTO v_nove
    FROM (SELECT DISTINCT n.zobrazeni AS z
            FROM nove n
           WHERE n.field_key = '@instance'
             AND n.zobrazeni IS NOT NULL
             AND strpos(n.zobrazeni, '/') > 1) d
   WHERE NOT EXISTS (SELECT 1 FROM public.twin_external_refs x
                      WHERE x.ref_kind = 'nase_firma'
                        AND x.source = split_part(d.z, '/', 1)
                        AND lower(x.source_key) = lower(btrim(substr(d.z, strpos(d.z, '/') + 1))));
  IF v_nove IS NOT NULL THEN
    PERFORM public.navrhni_nase_firmy_z_agend(v_nove);
  END IF;
  RETURN NULL;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_li_doc_scope_keys_nase_firmy() FROM PUBLIC;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/nazev_firmy_klic.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: nazev_firmy_klic
-- Popis: KLÍČ JMÉNA FIRMY pro porovnání „je to totéž jméno?" mezi zdroji.
--        Totéž jméno zapíše účetnictví, smlouva a veřejný rejstřík různě:
--        „Alfa, s.r.o." · „ALFA s. r. o." · „Alfa spol. s r.o.". Klíč srovná JEN
--        zápis — malá písmena, bez diakritiky, bez interpunkce, jedna mezera —
--        a právní formu na jednu zkratku. Nic víc: jiné slovo v názvu je jiné
--        jméno (přejmenování, jiná firma), a to se schovávat nesmí.
--
-- Proč ne norm_text: ten jen sníží písmena a odstraní diakritiku, takže
-- „a.s." a „a. s." by byla dvě jména a každá druhá shoda by spadla do rozporu.
--
-- Použití: twin_ref_tridy (shoda jména mezi zdroji v čase).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.nazev_firmy_klic(p_nazev text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path TO 'public', 'pg_temp'
AS $$
  select nullif(btrim(
    -- právní forma na konci názvu → jedna zkratka (zápis „spol. s r. o." i „s.r.o.")
    regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(
    regexp_replace(regexp_replace(regexp_replace(
      ' ' || btrim(regexp_replace(regexp_replace(
        translate(lower(coalesce(p_nazev, '')), 'áčďéěíňóřšťúůýžäöü', 'acdeeinorstuuyzaou'),
        '[^a-z0-9]+', ' ', 'g'), '\s+', ' ', 'g')) || ' ',
      ' spol s r o $', ' sro '),
      ' s r o $', ' sro '),
      ' a s $', ' as '),
      ' v o s $', ' vos '),
      ' k s $', ' ks '),
      ' o p s $', ' ops '),
      ' z s $', ' zs '),
      ' z u $', ' zu ')
  ), '');
$$;

COMMENT ON FUNCTION public.nazev_firmy_klic(text) IS
  'Klíč jména firmy pro porovnání mezi zdroji: malá písmena, bez diakritiky a interpunkce, právní forma jednou zkratkou. Jiné slovo = jiné jméno.';

REVOKE ALL ON FUNCTION public.nazev_firmy_klic(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.nazev_firmy_klic(text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/news_article_check_fields.sql
-- -----------------------------------------------------------------------------

-- Function: public.news_article_check_fields
-- Description: Ověří tvar hlavičky článku přicházející z klienta (p_fields):
--              ohnisko 0–1, přiblížení 1–4, štítky = pole textů, texty = objekt
--              po jazycích. Vadný vstup skončí výjimkou, ne tichým přeskočením —
--              koncept se ukládá automaticky a nikdo se na chybu nedívá.
-- Security: čistá validace, bez čtení tabulek.
-- Created: 2026-09-24

CREATE OR REPLACE FUNCTION public.news_article_check_fields(p_fields jsonb)
RETURNS void
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_n numeric;
BEGIN
  IF p_fields IS NULL THEN
    RETURN;
  END IF;
  IF jsonb_typeof(p_fields) <> 'object' THEN
    RAISE EXCEPTION 'fields must be a JSON object';
  END IF;

  IF p_fields ? 'image_url' AND jsonb_typeof(p_fields -> 'image_url') NOT IN ('string', 'null') THEN
    RAISE EXCEPTION 'fields.image_url must be a string or null';
  END IF;

  IF p_fields ? 'image_focus_x' THEN
    v_n := (p_fields ->> 'image_focus_x')::numeric;
    IF v_n IS NULL OR v_n < 0 OR v_n > 1 THEN RAISE EXCEPTION 'fields.image_focus_x must be within 0..1'; END IF;
  END IF;
  IF p_fields ? 'image_focus_y' THEN
    v_n := (p_fields ->> 'image_focus_y')::numeric;
    IF v_n IS NULL OR v_n < 0 OR v_n > 1 THEN RAISE EXCEPTION 'fields.image_focus_y must be within 0..1'; END IF;
  END IF;
  IF p_fields ? 'image_zoom' THEN
    v_n := (p_fields ->> 'image_zoom')::numeric;
    IF v_n IS NULL OR v_n < 1 OR v_n > 4 THEN RAISE EXCEPTION 'fields.image_zoom must be within 1..4'; END IF;
  END IF;

  IF p_fields ? 'tags' THEN
    IF jsonb_typeof(p_fields -> 'tags') <> 'array' THEN
      RAISE EXCEPTION 'fields.tags must be an array of strings';
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_fields -> 'tags') x WHERE jsonb_typeof(x) <> 'string') THEN
      RAISE EXCEPTION 'fields.tags must be an array of strings';
    END IF;
  END IF;

  IF p_fields ? 'texts' AND jsonb_typeof(p_fields -> 'texts') <> 'object' THEN
    RAISE EXCEPTION 'fields.texts must be an object keyed by locale';
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.news_article_check_fields(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.news_article_check_fields(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/news_article_edit_stamp.sql
-- -----------------------------------------------------------------------------

-- Function: public.news_article_edit_stamp
-- Description: Razítko stavu, který editor upravuje: novější z `updated_at`
--              článku a `updated_at` jeho konceptu. Klient ho dostane při načtení
--              a posílá zpět jako `p_expected_stamp`; když mezitím uložil někdo
--              jiný, razítko nesedí a zápis skončí 409 místo tichého přepsání
--              cizí práce (do 2026-09-24 vyhrával poslední zápis, beze slova).
-- Security: SECURITY DEFINER (čte i nezveřejněné) — autorizuje sám: admin/staff
--           nebo service_role.
-- Created: 2026-09-24

CREATE OR REPLACE FUNCTION public.news_article_edit_stamp(p_article_id uuid)
RETURNS timestamptz
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT (public.is_admin_or_staff() OR public.is_service_role()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  RETURN (
    SELECT GREATEST(a.updated_at, COALESCE(d.updated_at, a.updated_at))
    FROM public.news_articles a
    LEFT JOIN public.news_article_versions d
      ON d.article_id = a.id AND d.kind = 'draft'
    WHERE a.id = p_article_id
  );
END;
$$;

REVOKE ALL ON FUNCTION public.news_article_edit_stamp(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.news_article_edit_stamp(uuid) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_news_article_admin.sql
-- -----------------------------------------------------------------------------

-- Source of truth for get_news_article_admin
-- Admin single-article load by id INCLUDING the canvas (canvas_data ProjectData
-- + html/css) and draft state — the editor needs the full canvas to hydrate
-- GrapesJS and must see unpublished drafts. Admin only.
--
-- 2026-09-24: + štítky, ohnisko/přiblížení, `edit_stamp` (razítko pro souběh) a
-- `draft` — KONCEPT zveřejněného článku jako JSON {canvas_data, canvas_html,
-- canvas_css, fields, updated_at}, nebo NULL. Editor hydratuje plátno z konceptu,
-- je-li; dialog hlavičky čte `draft.fields` (obrázek, štítky, texty).
-- Změna návratového typu = DROP v heals.sql (CREATE OR REPLACE typ nezmění; čistá DB ho nepotřebuje).

CREATE OR REPLACE FUNCTION public.get_news_article_admin(p_id uuid)
RETURNS TABLE (
  id uuid,
  slug text,
  title_key text,
  content_key text,
  excerpt_key text,
  image_url text,
  canvas_data jsonb,
  canvas_html text,
  canvas_css text,
  is_published boolean,
  tags text[],
  image_focus_x numeric,
  image_focus_y numeric,
  image_zoom numeric,
  updated_at timestamptz,
  edit_stamp timestamptz,
  draft jsonb
)
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_admin_or_staff() THEN RAISE EXCEPTION 'Unauthorized'; END IF;
  RETURN QUERY
  SELECT na.id, na.slug, na.title_key, na.content_key, na.excerpt_key, na.image_url,
         na.canvas_data, na.canvas_html, na.canvas_css, na.is_published,
         na.tags, na.image_focus_x, na.image_focus_y, na.image_zoom, na.updated_at,
         public.news_article_edit_stamp(na.id),
         (SELECT jsonb_build_object(
                   'canvas_data', d.canvas_data,
                   'canvas_html', d.canvas_html,
                   'canvas_css',  d.canvas_css,
                   'fields',      d.fields,
                   'updated_at',  d.updated_at)
            FROM public.news_article_versions d
           WHERE d.article_id = na.id AND d.kind = 'draft')
  FROM public.news_articles na WHERE na.id = p_id LIMIT 1;
END;
$$;
REVOKE ALL ON FUNCTION public.get_news_article_admin(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_news_article_admin(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_news_articles_admin.sql
-- -----------------------------------------------------------------------------

-- Source of truth for get_news_articles_admin
-- Admin listing of all news articles (admin/staff only).
--
-- 2026-09-24: seznam v administraci potřebuje HLEDAT a ŘADIT podle titulku, ne
-- podle i18n klíče (naměřeno: sloupec „Klíč nadpisu" a řazení podle sort_order,
-- které import naplnil chronologií 1–92, takže nahoře byl rok 2019). Proto:
--   • `p_locale` → `title`/`excerpt` = hodnota v jazyce rozhraní (NULL bez
--     překladu; ŽÁDNÝ jazyk se nedosazuje — klient locale posílá vždy);
--   • `tags`, `has_draft` (zveřejněný článek s rozdělaným konceptem),
--     `edit_stamp` (razítko pro souběh), ohnisko/přiblížení.
-- Pořadí zůstává sort_order/created_at — výchozí řazení „nejnovější nahoře,
-- koncepty první" dělá klient nad úplným seznamem (92 řádků, jeden dotaz).
-- Nový parametr + návratový typ = nový podpis → DROP bezargumentové verze.

DROP FUNCTION IF EXISTS public.get_news_articles_admin();

CREATE OR REPLACE FUNCTION public.get_news_articles_admin(p_locale text DEFAULT NULL)
RETURNS TABLE (
  id uuid,
  slug text,
  title_key text,
  content_key text,
  excerpt_key text,
  image_url text,
  is_published boolean,
  published_at timestamptz,
  sort_order integer,
  created_by uuid,
  created_at timestamptz,
  updated_at timestamptz,
  title text,
  excerpt text,
  tags text[],
  has_draft boolean,
  edit_stamp timestamptz,
  image_focus_x numeric,
  image_focus_y numeric,
  image_zoom numeric
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  SELECT
    na.id,
    na.slug,
    na.title_key,
    na.content_key,
    na.excerpt_key,
    na.image_url,
    na.is_published,
    na.published_at,
    na.sort_order,
    na.created_by,
    na.created_at,
    na.updated_at,
    (SELECT tr.value FROM public.translations tr
      WHERE tr.namespace = 'news' AND tr.key = na.title_key AND tr.locale = p_locale LIMIT 1),
    (SELECT tr.value FROM public.translations tr
      WHERE tr.namespace = 'news' AND tr.key = na.excerpt_key AND tr.locale = p_locale LIMIT 1),
    na.tags,
    EXISTS (SELECT 1 FROM public.news_article_versions d WHERE d.article_id = na.id AND d.kind = 'draft'),
    public.news_article_edit_stamp(na.id),
    na.image_focus_x,
    na.image_focus_y,
    na.image_zoom
  FROM public.news_articles na
  ORDER BY na.sort_order ASC, na.created_at DESC;
END;
$$;

REVOKE ALL ON FUNCTION public.get_news_articles_admin(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_news_articles_admin(text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/news_article_texts.sql
-- -----------------------------------------------------------------------------

-- Function: public.news_article_texts
-- Description: Texty článku (titulek/perex/tělo) po jazycích jako jeden JSON —
--              {"cs": {"title": "…", "excerpt": "…"}, "en": {…}}.
--              Texty žijí v `translations` pod třemi klíči článku; tohle je
--              jediné místo, kde se skládají do snímku (verze, koncept).
-- Security: SECURITY INVOKER — `translations` smí číst i anon; pomocník
--           nedává víc, než tabulka sama. Volají ho DEFINER RPC novinek.
-- Created: 2026-09-24

CREATE OR REPLACE FUNCTION public.news_article_texts(p_article_id uuid)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public'
AS $$
  SELECT COALESCE(jsonb_object_agg(s.locale, s.texty), '{}'::jsonb)
  FROM (
    SELECT tr.locale,
           jsonb_strip_nulls(jsonb_build_object(
             'title',   MAX(CASE WHEN tr.key = a.title_key   THEN tr.value END),
             'excerpt', MAX(CASE WHEN tr.key = a.excerpt_key THEN tr.value END),
             'content', MAX(CASE WHEN tr.key = a.content_key THEN tr.value END)
           )) AS texty
    FROM public.news_articles a
    JOIN public.translations tr
      ON tr.namespace = 'news'
     AND tr.key IN (a.title_key, a.excerpt_key, a.content_key)
    WHERE a.id = p_article_id
    GROUP BY tr.locale
  ) s;
$$;

REVOKE ALL ON FUNCTION public.news_article_texts(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.news_article_texts(uuid) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/news_article_live_fields.sql
-- -----------------------------------------------------------------------------

-- Function: public.news_article_live_fields
-- Description: Hlavička článku tak, jak ji vidí web (živý stav), jako jeden JSON:
--              {image_url, image_focus_x, image_focus_y, image_zoom, tags, texts}.
--              Stejný tvar nese `news_article_versions.fields` — snímek verze i
--              koncept z něj vycházejí, takže „obnovit verzi" a „založit koncept"
--              čtou a píší tentýž tvar.
-- Security: SECURITY DEFINER (čte i NEZVEŘEJNĚNÝ článek) — proto autorizuje sám:
--           admin/staff nebo service_role. „Volá se jen zevnitř" není autorizace.
-- Created: 2026-09-24

CREATE OR REPLACE FUNCTION public.news_article_live_fields(p_article_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT (public.is_admin_or_staff() OR public.is_service_role()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  RETURN (
    SELECT jsonb_build_object(
             'image_url',     a.image_url,
             'image_focus_x', a.image_focus_x,
             'image_focus_y', a.image_focus_y,
             'image_zoom',    a.image_zoom,
             'tags',          to_jsonb(a.tags),
             'texts',         public.news_article_texts(a.id)
           )
    FROM public.news_articles a
    WHERE a.id = p_article_id
  );
END;
$$;

REVOKE ALL ON FUNCTION public.news_article_live_fields(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.news_article_live_fields(uuid) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_news_article_version.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_news_article_version
-- Description: Snímek ŽIVÉHO stavu článku (plátno + hlavička + texty) do historie.
--              Druhy: 'manual' (ruční uložení), 'auto' (před obnovou verze),
--              'published' (každé zveřejnění). Koncept ('draft') se sem NEZAPISUJE —
--              ten má vlastní cestu (save_news_article_draft_admin).
--
--              Retence: 'manual' + 'auto' se drží posledních 30 na článek,
--              'published' se nemaže nikdy — je to to, co kdy viděl web.
--
-- Security: SECURITY DEFINER; admin/staff NEBO service_role (seed zveřejňuje).
-- Created: 2026-09-24 (zrcadlí create_web_page_version)

CREATE OR REPLACE FUNCTION public.create_news_article_version(
  p_article_id uuid,
  p_kind text DEFAULT 'manual',
  p_label text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_a public.news_articles%ROWTYPE;
  v_next integer;
  v_id uuid;
BEGIN
  IF NOT (public.is_admin_or_staff() OR public.is_service_role()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF p_kind NOT IN ('manual', 'auto', 'published') THEN
    RAISE EXCEPTION 'Invalid version kind: %', p_kind;
  END IF;

  SELECT * INTO v_a FROM public.news_articles WHERE id = p_article_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Article not found';
  END IF;

  SELECT COALESCE(MAX(v.version_number), 0) + 1
    INTO v_next
  FROM public.news_article_versions v
  WHERE v.article_id = p_article_id AND v.kind <> 'draft';

  INSERT INTO public.news_article_versions (
    article_id, version_number, kind, canvas_data, canvas_html, canvas_css, fields, label, created_by
  ) VALUES (
    p_article_id, v_next, p_kind, v_a.canvas_data, v_a.canvas_html, v_a.canvas_css,
    public.news_article_live_fields(p_article_id), p_label, auth.uid()
  )
  RETURNING id INTO v_id;

  -- Retence: ruční a automatické snímky jen posledních 30; zveřejněné zůstávají.
  DELETE FROM public.news_article_versions v
  WHERE v.article_id = p_article_id
    AND v.kind IN ('manual', 'auto')
    AND v.id NOT IN (
      SELECT k.id FROM public.news_article_versions k
      WHERE k.article_id = p_article_id AND k.kind IN ('manual', 'auto')
      ORDER BY k.version_number DESC
      LIMIT 30
    );

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'NEWS_VERSION_CREATE',
    jsonb_build_object(
      'area', 'content',
      'severity', 'info',
      'entity_type', 'news_article_version',
      'entity_id', v_id::text,
      'article_id', p_article_id::text,
      'kind', p_kind,
      'version_number', v_next
    )
  );

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.create_news_article_version(uuid, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_news_article_version(uuid, text, text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_news_article_admin.sql
-- -----------------------------------------------------------------------------

-- Source of truth for create_news_article_admin
-- Admin creates a new news article with audit logging.
-- 2026-09-24: + štítky, ohnisko a přiblížení titulního obrázku (nový podpis → DROP).
-- Texty a plátno se zapisují až po založení přes save_news_article_draft_admin
-- (článek vzniká nezveřejněný, takže jdou rovnou do živého stavu).

DROP FUNCTION IF EXISTS public.create_news_article_admin(text, text, text, boolean, timestamptz, text, integer, text);

CREATE OR REPLACE FUNCTION public.create_news_article_admin(
  p_content_key text,
  p_excerpt_key text DEFAULT NULL,
  p_image_focus_x numeric DEFAULT 0.5,
  p_image_focus_y numeric DEFAULT 0.5,
  p_image_url text DEFAULT NULL,
  p_image_zoom numeric DEFAULT 1,
  p_is_published boolean DEFAULT false,
  p_published_at timestamptz DEFAULT NULL,
  p_slug text DEFAULT NULL,
  p_sort_order integer DEFAULT 0,
  p_tags text[] DEFAULT '{}'::text[],
  p_title_key text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id uuid;
  v_slug text;
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Generate slug from title_key if not provided
  v_slug := COALESCE(p_slug, 'article-' || to_char(now(), 'YYYYMMDD-HH24MISS'));

  INSERT INTO public.news_articles (
    content_key,
    created_by,
    excerpt_key,
    image_focus_x,
    image_focus_y,
    image_url,
    image_zoom,
    is_published,
    published_at,
    slug,
    sort_order,
    tags,
    title_key
  ) VALUES (
    p_content_key,
    auth.uid(),
    p_excerpt_key,
    COALESCE(p_image_focus_x, 0.5),
    COALESCE(p_image_focus_y, 0.5),
    p_image_url,
    COALESCE(p_image_zoom, 1),
    p_is_published,
    CASE WHEN p_is_published THEN COALESCE(p_published_at, now()) ELSE p_published_at END,
    v_slug,
    p_sort_order,
    COALESCE(p_tags, '{}'::text[]),
    COALESCE(p_title_key, 'news.' || v_slug || '.title')
  )
  RETURNING news_articles.id INTO v_id;

  -- Zveřejnění rovnou při založení = první verze do historie.
  IF p_is_published THEN
    PERFORM public.create_news_article_version(v_id, 'published', NULL);
  END IF;

  -- Audit
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'NEWS_CREATE',
    jsonb_build_object(
      'area', 'content',
      'severity', 'info',
      'entity_type', 'news_article',
      'entity_id', v_id
    )
  );

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.create_news_article_admin(text, text, numeric, numeric, text, numeric, boolean, timestamptz, text, integer, text[], text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_news_article_admin(text, text, numeric, numeric, text, numeric, boolean, timestamptz, text, integer, text[], text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/norm_text.sql
-- -----------------------------------------------------------------------------

-- Normalizace textu dotazu (lowercase + bez diakritiky) pro answer_verified_facts.
-- SoT doplněn 2026-07-29: funkce žila jen v generované baseline a v živé DB —
-- nešla opravit pipeline cestou. Odteď je zdrojem TENHLE soubor.
CREATE OR REPLACE FUNCTION public.norm_text(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select translate(lower(coalesce(t,'')),'áčďéěíňóřšťúůýžäöü','acdeeinorstuuyzaou'); $function$;

-- answer_verified_facts je SECURITY INVOKER — tenhle helper tedy exekuuje přímo
-- volající role a authenticated ho potřebuje; PUBLIC/anon nemá důvod.
revoke all on function public.norm_text(text) from public, anon;
grant execute on function public.norm_text(text) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/emit_rent_claim_contradictions.sql
-- -----------------------------------------------------------------------------

-- ROZPOR JE OTÁZKA — starší tvrzení × derivace z dokladů.
--
-- ⭐ PROČ TAHLE FUNKCE EXISTUJE
-- Když se nájem přestal číst ze seedu a začal se derivovat z fakturovaných
-- položek, nabízelo se starý snímek smazat. Majitel rozhodl jinak a je to
-- lepší: starší tvrzení má cenu právě jako KONTROLA. Naměřeno 2026-08-04
-- (33 seedových nájmů × derivace ze 116 plátců):
--   ·  3 SEDÍ         → kotva: měřidlo měří správně
--   · 26 se LIŠÍ      → hodnota zestárla (valorizace) — tvrzení platilo, dnes ne
--   ·  4 BEZ PROTĚJŠKU→ jiná otázka: konec nájmu? nefakturuje se? jiné jméno?
-- Ta TROJICE je to podstatné: bez shodujících se případů by „26 se liší" byl
-- podezřelý na vadu derivace, ne na stárnutí dat. Rozpor sám neříká, kdo se
-- mýlí — teprve kotva z něj dělá nález.
--
-- ⛔ NIC SE NEPŘEPISUJE. Výstupem je NÁVRH v advisory kanálu
-- (`li_entity_suggestions`, `advisory = true`, doktrína „nikdy automatická
-- vazba"). Člověk rozhoduje; funkce jen ukazuje obě strany a DŮVOD.
--
-- ⭐ KAŽDÝ ZÁZNAM VYSVĚTLUJE CO, JAK A PROČ
-- Vzorek bez důvodu nikoho nic nenaučí a nedá se podle něj rozhodnout
-- (zákon „ukázat vstup měřidla před nálezem" platí i pro návrhy). Proto
-- `raw_data` nese: obě hodnoty, období derivace, zdroj tvrzení, druh rozporu
-- a větu, která ho vysvětluje česky.
--
-- Konfigurace (p_params):
--   rent  : jsonb pro get_rent_current (rent_patterns, exclude_owner, …)
--   claim_source : text — zdroj tvrzení v twin_events; POVINNÝ, bez defaultu
--                  (jméno zdroje je instanční údaj — viz deklarace v_src níže)
--   claim_attr   : text — atribut s částkou; POVINNÝ, bez defaultu (jméno
--                  atributu nese měnu instance, platforma žádnou nepředjímá)
--
-- SECURITY INVOKER: kdo nemá nárok na doklady, nevyrobí ani návrhy.
-- Kontrakt: (jsonb) -> jsonb {emitted, anchors, stale, orphans, period}.

create or replace function public.emit_rent_claim_contradictions(
  p_params jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = public, pg_temp
as $fn$
declare
  v_rent    jsonb := public.get_rent_current(coalesce(p_params->'rent','{}'::jsonb));
  v_period  text  := v_rent->'data'->'summary'->>'period';
  -- ⛔ ŽÁDNÁ VÝCHOZÍ HODNOTA ZDROJE. Jméno zdroje tvrzení je instanční údaj
  -- (každá instance vlastní, platforma žádný nepředjímá) a v generickém kanálu nemá co dělat —
  -- brána `instance-nazvy-nepatri-do-stack-kodu` to chytla správně. Bez
  -- `claim_source` se tedy neporovnává nic a řekne se to: mlčení by vypadalo
  -- jako „žádné rozpory", což je jiné tvrzení než „nebylo co porovnat".
  v_src     text  := nullif(p_params->>'claim_source','');
  -- ⛔ ŽÁDNÁ VÝCHOZÍ HODNOTA ATRIBUTU. Jméno atributu s částkou nese měnu
  -- instance (`…_czk`, `…_eur`, …) a platforma žádnou měnu nepředjímá —
  -- stejné pravidlo jako u claim_source o pár řádků výš.
  v_attr    text  := nullif(p_params->>'claim_attr','');
  v_rows    jsonb := '[]'::jsonb;
  v_anchor  int := 0; v_stale int := 0; v_orphan int := 0;
begin
  -- Bez vzorů se nederivuje nic a rozpor by byl domyšlený, ne naměřený.
  if not coalesce((v_rent->'data'->'summary'->>'configured')::boolean,false) then
    return jsonb_build_object('emitted',0,'reason','bez vzorů nájmu se nederivuje — rozpor nelze měřit');
  end if;
  -- Bez zdroje tvrzení není co porovnávat. Vrací se DŮVOD, ne nula: „0 rozporů"
  -- a „nebylo co porovnat" jsou různá tvrzení a spletly by se.
  if v_src is null then
    return jsonb_build_object('emitted',0,'reason',
      'claim_source neuveden — instance musí říct, který zdroj tvrzení porovnávat');
  end if;
  -- Stejná logika pro atribut částky: bez něj se neporovnává a řekne se to.
  if v_attr is null then
    return jsonb_build_object('emitted',0,'reason',
      'claim_attr neuveden — instance musí říct, který atribut nese částku (jméno nese i měnu)');
  end if;

  with derivace as (
    select t->>'tenant' as najemce, (t->>'monthly_amount')::numeric as ded, t->>'period' as obd
    from jsonb_array_elements(v_rent->'data'->'tenants') t
  ),
  tvrzeni as (
    select e.label as najemce, (ev.attrs->>v_attr)::numeric as castka,
           to_char(ev.occurred_at,'YYYY-MM-DD') as kdy
    from twin_events ev join twin_entities e on e.id = ev.twin_id
    where ev.event_type='lease' and ev.source = v_src
      and (ev.attrs->>v_attr) ~ '^-?[0-9]+(\.[0-9]+)?$'
  ),
  -- Spárování jménem: přesná shoda neexistuje (seed nese zkomoleniny), takže
  -- se páruje normalizovaným obsažením — a to, že je to SLABÉ spárování, je
  -- součástí nálezu: „bez protějšku" může znamenat i „jiné jméno téže osoby".
  parovani as (
    select t.najemce as tvrdi_kdo, t.castka, t.kdy,
           d.najemce as derivace_kdo, d.ded, d.obd
    from tvrzeni t
    left join lateral (
      select * from derivace d
       where public.norm_text(d.najemce) like '%'||public.norm_text(t.najemce)||'%'
       order by abs(d.ded - t.castka) limit 1) d on true
  )
  select jsonb_agg(jsonb_build_object(
           'tvrdi_kdo', tvrdi_kdo, 'castka', castka, 'kdy', kdy,
           'derivace_kdo', derivace_kdo, 'ded', ded, 'obd', obd,
           'druh', case
             when derivace_kdo is null then 'bez_protejsku'
             when ded = castka        then 'kotva'
             else 'zestarlo' end))
    into v_rows from parovani;

  -- Zápis návrhů. `same_*` druhy tenhle kanál už zná; tenhle je nový a projde,
  -- protože kontrakt druhu je od 2026-08-04 TVAR (slug), ne uzavřený výčet —
  -- přesně proto, aby slovník nálezů směl růst bez migrace.
  insert into public.li_entity_suggestions
    (suggestion_key, suggestion, name_field, name_normalized, names, advisory,
     ingest_source_slug, raw_data)
  select
    md5('rent_claim_vs_derivation|'||(r->>'tvrdi_kdo')||'|'||coalesce(v_period,'')),
    'rent_claim_contradicts_derivation',
    'counterparty',
    public.norm_text(r->>'tvrdi_kdo'),
    array_remove(array[r->>'tvrdi_kdo', r->>'derivace_kdo'], null),
    true,
    'derived:rent-current',
    jsonb_build_object(
      'druh',            r->>'druh',
      'tvrzeni_kdo',     r->>'tvrdi_kdo',
      'tvrzeni_castka',  (r->>'castka')::numeric,
      'tvrzeni_zdroj',   v_src,
      'tvrzeni_kdy',     r->>'kdy',
      'derivace_kdo',    r->>'derivace_kdo',
      'derivace_castka', (r->>'ded')::numeric,
      'derivace_obdobi', r->>'obd',
      'rozdil',          case when r->>'ded' is null then null
                              else round((r->>'ded')::numeric - (r->>'castka')::numeric, 2) end,
      -- CO, JAK a PROČ jednou větou — bez důvodu se nedá rozhodnout.
      'vysvetleni', case r->>'druh'
        when 'kotva' then
          'CO: starší tvrzení ('||(r->>'castka')||') SEDÍ na derivaci z faktur. '
          ||'JAK: spárováno jménem, částka shodná. '
          ||'PROČ ukazujeme: shodující se případy jsou kotva měřidla — dokládají, '
          ||'že rozdíly u ostatních jsou stárnutí dat, ne vada derivace.'
        when 'zestarlo' then
          'CO: tvrzení '||(r->>'castka')||' z '||coalesce(r->>'kdy','?')
          ||', ale faktury za '||coalesce(r->>'obd','?')||' říkají '||(r->>'ded')||'. '
          ||'JAK: součet fakturovaných položek nájmu v posledním období nájemce. '
          ||'PROČ: hodnota nemá interval platnosti, takže zestárla TIŠE — '
          ||'nejspíš valorizace. Rozhodnutí: přijmout derivaci jako aktuální, '
          ||'nebo doložit, proč platí starší číslo.'
        else
          'CO: tvrzení '||(r->>'castka')||', ale v derivaci nemá protějšek. '
          ||'JAK: hledáno normalizovaným jménem v plátcích nájmu za poslední období. '
          ||'PROČ: tři možnosti a NELZE je rozlišit bez člověka — nájem skončil, '
          ||'nefakturuje se, nebo je táž osoba vedená pod jiným jménem '
          ||'(u seedu doloženo: zkomolená jména jako Clevištan × Chlevišťan).'
        end)
  from jsonb_array_elements(coalesce(v_rows,'[]'::jsonb)) r
  on conflict (suggestion_key) do update
     set raw_data = excluded.raw_data, ingested_at = now();

  select count(*) filter (where r->>'druh'='kotva'),
         count(*) filter (where r->>'druh'='zestarlo'),
         count(*) filter (where r->>'druh'='bez_protejsku')
    into v_anchor, v_stale, v_orphan
  from jsonb_array_elements(coalesce(v_rows,'[]'::jsonb)) r;

  return jsonb_build_object(
    'emitted', jsonb_array_length(coalesce(v_rows,'[]'::jsonb)),
    'anchors', v_anchor, 'stale', v_stale, 'orphans', v_orphan,
    'period', v_period,
    -- Kotva je podmínka důvěryhodnosti celku, ne detail: bez ní se nedá říct,
    -- jestli rozdíly ukazují stárnutí dat, nebo vadu měřidla.
    'trustworthy', v_anchor > 0);
end
$fn$;

comment on function public.emit_rent_claim_contradictions(jsonb) is
  'Porovná starší tvrzení o nájmu (twin_events lease) s derivací z faktur a vydá ROZPORY jako advisory otázky do li_entity_suggestions — každou s oběma stranami a vysvětlením co/jak/proč. Nic nepřepisuje; kotva (shodující se případy) je podmínka důvěryhodnosti nálezu.';

revoke all on function public.emit_rent_claim_contradictions(jsonb) from public, anon;
grant execute on function public.emit_rent_claim_contradictions(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/mcp_search_knowledge_v2.sql
-- -----------------------------------------------------------------------------

-- Function: mcp_search_knowledge_v2
-- Auto-extracted (all overloads incl halfvec/story-scoped; back-port reconciliation)
-- Brick6: the story overload gained p_audience_user_id (10→11 args). DROP the old 10-arg story
-- overload so it cannot linger WITHOUT the tier-ACL (CREATE OR REPLACE only replaces an exact
-- signature match; the 11-arg is a NEW function). The 9-arg global overload is unchanged (its
-- audience user is auth.uid() — adding the arg there would collide with this story signature).
DROP FUNCTION IF EXISTS public.mcp_search_knowledge_v2(vector,text,text[],text,text,text[],boolean,integer,double precision,uuid);

CREATE OR REPLACE FUNCTION public.mcp_search_knowledge_v2(p_query_embedding vector DEFAULT NULL::vector, p_query_text text DEFAULT NULL::text, p_item_types text[] DEFAULT '{}'::text[], p_category text DEFAULT NULL::text, p_expertise_slug text DEFAULT NULL::text, p_context_tags text[] DEFAULT '{}'::text[], p_include_ai_instructions boolean DEFAULT true, p_limit integer DEFAULT 20, p_similarity_threshold double precision DEFAULT 0.3, p_story_id uuid DEFAULT NULL::uuid, p_audience_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_results jsonb;
  v_words text[];
  v_caller_role text;
  v_caller_id uuid;
  v_audience_user uuid;  -- Brick6: end-user whose tier gates retrieval (service may override; else self)
BEGIN
  v_caller_role := public.get_jwt_role();
  v_caller_id := auth.uid();

  -- ── RBAC: Per-story access check ───────────────────────────────────────
  -- service_role bypasses (used by compose_context, n8n internal workflows).
  -- Any other caller asking for a specific story must be admin/owner/participant.
  IF p_story_id IS NOT NULL AND v_caller_role IS DISTINCT FROM 'service_role' THEN
    IF NOT (
      public.is_admin_or_staff()
      OR EXISTS (
        SELECT 1 FROM public.partner_stories ps
        WHERE ps.id = p_story_id AND ps.user_id = v_caller_id
      )
      OR EXISTS (
        SELECT 1 FROM public.story_participants sp
        WHERE sp.story_id = p_story_id AND sp.user_id = v_caller_id
      )
    ) THEN
      RAISE EXCEPTION 'Access denied to story %', p_story_id
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Brick6 tier-ACL audience identity: only service_role (trusted orchestration) may name a
  -- different end-user via p_audience_user_id; authenticated callers are pinned to themselves.
  v_audience_user := CASE
    WHEN v_caller_role = 'service_role' THEN COALESCE(p_audience_user_id, auth.uid())
    ELSE auth.uid()
  END;

  -- Split query text into individual words (min 2 chars)
  IF p_query_text IS NOT NULL AND trim(p_query_text) != '' THEN
    v_words := ARRAY(
      SELECT w FROM unnest(regexp_split_to_array(lower(trim(p_query_text)), '\s+')) AS w
      WHERE length(w) >= 2
    );
    IF array_length(v_words, 1) IS NULL THEN
      v_words := NULL;
    END IF;
  ELSE
    v_words := NULL;
  END IF;

  SELECT COALESCE(jsonb_agg(result_row ORDER BY (result_row->>'score')::float DESC), '[]'::jsonb)
  INTO v_results
  FROM (
    SELECT jsonb_build_object(
      'knowledge_item_id', ki.id,
      'item_type', ki.item_type::text,
      'source_slug', ki.source_slug,
      'story_id', ki.story_id,
      'title', ki.title,
      'summary', ki.summary,
      'category', ki.category,
      'expertise_area_slug', gea.slug,
      'expertise_area_icon', gea.icon,
      'author_display_name', ki.author_display_name,
      'is_verified', ki.is_verified,
      'ai_context_tags', ki.ai_context_tags,
      'ai_instructions', CASE WHEN p_include_ai_instructions THEN ki.ai_instructions ELSE NULL END,
      'chunk_text', kc.chunk_text,
      'chunk_index', kc.chunk_index,
      -- Brick3 locale axis: surfaced for downstream consumers only. NO locale
      -- WHERE filter and NO locale score term — retrieval is byte-identical today.
      'locale', kc.locale,
      'similarity', CASE WHEN p_query_embedding IS NOT NULL AND ke.embedding IS NOT NULL
        THEN 1 - (ke.embedding <=> p_query_embedding)
        ELSE NULL END,
      'version', ki.version,
      'published_at', ki.published_at,
      'score', (
        CASE WHEN p_query_embedding IS NOT NULL AND ke.embedding IS NOT NULL
          THEN (1 - (ke.embedding <=> p_query_embedding)) * 40
          ELSE 0 END
        +
        CASE WHEN p_context_tags != '{}' AND ki.ai_context_tags && p_context_tags
          THEN COALESCE(array_length(
            ARRAY(SELECT unnest(ki.ai_context_tags) INTERSECT SELECT unnest(p_context_tags)),
            1
          ), 0) * 10
          ELSE 0 END
        +
        CASE WHEN v_words IS NOT NULL THEN
          (SELECT count(*)::int FROM unnest(v_words) AS word
           WHERE ki.title ILIKE '%' || word || '%'
              OR ki.summary ILIKE '%' || word || '%'
          ) * 15
          ELSE 0
        END
        +
        -- ZNĚNÍ dokumentu, ne jen jeho popisky. Do 2026-07-30 lexikální větev
        -- prohledávala pouze title + summary; chunky se připojovaly jen kvůli
        -- výstupu, takže dotaz na formulaci ZE SMLOUVY nenašel nic, dokud ji
        -- někdo neopsal do shrnutí. S prázdnou vektorovou vrstvou (naměřeno:
        -- 4 292 chunků / 0 embeddingů) tím retrieval prakticky nefungoval.
        --
        -- norm_text() na obou stranách = tentýž výraz jako v indexu
        -- idx_knowledge_chunks_text_trgm, jinak by se index nepoužil. Skládá
        -- diakritiku i velikost písmen; LIKE nad trigramovým GIN indexem snese
        -- i české skloňování (shodný kmen), což `simple` tsvector neumí a
        -- český slovník na serveru není.
        --
        -- Váha 8 < 15 záměrně: shoda v nadpisu je silnější signál než výskyt
        -- slova kdesi v těle dokumentu.
        CASE WHEN v_words IS NOT NULL AND kc.chunk_text IS NOT NULL THEN
          (SELECT count(*)::int FROM unnest(v_words) AS word
           WHERE public.norm_text(kc.chunk_text) LIKE '%' || public.norm_text(word) || '%'
          ) * 8
          ELSE 0
        END
        +
        CASE WHEN ki.is_verified THEN 5 ELSE 0 END
        +
        -- Per-story bonus: items scoped to current story rank above global
        CASE WHEN p_story_id IS NOT NULL AND ki.story_id = p_story_id THEN 25 ELSE 0 END
      )
    ) AS result_row
    FROM public.knowledge_items ki
    LEFT JOIN public.knowledge_chunks kc ON kc.knowledge_item_id = ki.id
    LEFT JOIN public.knowledge_embeddings ke ON ke.chunk_id = kc.id
    LEFT JOIN public.guild_expertise_areas gea ON gea.id = ki.expertise_area_id
    WHERE ki.status = 'active'
      -- ── Viditelnost: TÁŽ pravidla, jaká deklaruje sama tabulka ──────────────
      -- Do 2026-07-30 tu stál paušál `visibility IN (public, members, guild)`.
      -- Byl PŘÍSNĚJŠÍ než RLS politika knowledge_items a odřízl přesně to, co
      -- máme: interní smlouvy jsou `private` a story-scoped, takže z nich
      -- retrieval nevrátil NIKDY nic (naměřeno: všech 4 292 chunků leží pod
      -- private+story; 791 „public" položek nemá ani jeden chunk).
      --
      -- Tohle NENÍ rozvolnění přístupu. Politika „Per-story KB visible to
      -- participants" o `visibility` vůbec nemluví — pouští vlastníka story,
      -- jejího účastníka a admin/staff. `private` tedy vylučuje z VEŘEJNÉ
      -- politiky, ne z oprávněných čtenářů. Definer funkce si vedle toho psala
      -- druhé, vlastní pravidlo — a dvě pravidla o jedné věci se rozešla.
      --
      -- Vyhodnocuje se proti v_audience_user (Brick6): service_role smí říct,
      -- ZA KOHO se ptá, jinak je to volající sám. Bez identity zbývá jen
      -- veřejná/globální vrstva — fail-closed, žádný service_role bypass.
      AND (
        (ki.story_id IS NULL AND ki.visibility IN ('public', 'members', 'guild'))
        OR ki.item_type::text IN ('core_value', 'personality_trait')
        OR public.is_admin_or_staff(v_audience_user)
        OR EXISTS (
          SELECT 1 FROM public.partner_stories ps
          WHERE ps.id = ki.story_id AND ps.user_id = v_audience_user
        )
        OR EXISTS (
          SELECT 1 FROM public.story_participants sp
          WHERE sp.story_id = ki.story_id AND sp.user_id = v_audience_user
        )
      )
      -- Systemic safety: flagged/quarantined (prompt-injected) items never reach
      -- retrieval. The global overload already had this; the story-scoped overload
      -- (called by compose_context) was missing it — closing that gap here.
      AND ki.quarantine_status NOT IN ('flagged', 'quarantined')
      AND (p_item_types = '{}' OR ki.item_type::text = ANY(p_item_types))
      AND (p_category IS NULL OR ki.category = p_category)
      AND (p_expertise_slug IS NULL OR gea.slug = p_expertise_slug)
      AND (
        p_query_embedding IS NULL
        OR ke.embedding IS NULL
        OR (1 - (ke.embedding <=> p_query_embedding)) >= p_similarity_threshold
      )
      AND (
        p_query_embedding IS NOT NULL
        OR (v_words IS NOT NULL AND EXISTS (
          SELECT 1 FROM unnest(v_words) AS word
          WHERE ki.title ILIKE '%' || word || '%'
             OR ki.summary ILIKE '%' || word || '%'
        ))
        -- Bez tohohle by dokument, jehož ZNĚNÍ dotazu odpovídá, nebyl vůbec
        -- kandidátem — skóre výš by se na něj nikdy nedostalo.
        OR (v_words IS NOT NULL AND kc.chunk_text IS NOT NULL AND EXISTS (
          SELECT 1 FROM unnest(v_words) AS word
          WHERE public.norm_text(kc.chunk_text) LIKE '%' || public.norm_text(word) || '%'
        ))
        OR p_context_tags != '{}'
        OR (p_item_types != '{}')
      )
      -- ── Per-story isolation filter ───────────────────────────────────
      -- Brain layer: always included (item_type override).
      -- p_story_id NULL → only global items (story_id IS NULL).
      -- p_story_id NOT NULL → matching story + global items.
      AND (
        ki.item_type::text IN ('core_value', 'personality_trait')
        OR (p_story_id IS NULL AND ki.story_id IS NULL)
        OR (p_story_id IS NOT NULL AND (ki.story_id = p_story_id OR ki.story_id IS NULL))
      )
      -- Brick6 tier-ACL: HARD filter — an under-tier audience user never retrieves a gated row.
      AND (ki.minimum_tier IS NULL OR public.audience_user_meets_tier_requirement(ki.minimum_tier, v_audience_user))
    ORDER BY (
      CASE WHEN p_query_embedding IS NOT NULL AND ke.embedding IS NOT NULL
        THEN (1 - (ke.embedding <=> p_query_embedding)) * 40
        ELSE 0 END
      +
      CASE WHEN p_context_tags != '{}' AND ki.ai_context_tags && p_context_tags
        THEN COALESCE(array_length(
          ARRAY(SELECT unnest(ki.ai_context_tags) INTERSECT SELECT unnest(p_context_tags)),
          1
        ), 0) * 10
        ELSE 0 END
      +
      CASE WHEN v_words IS NOT NULL THEN
        (SELECT count(*)::int FROM unnest(v_words) AS word
         WHERE ki.title ILIKE '%' || word || '%'
            OR ki.summary ILIKE '%' || word || '%'
        ) * 15
        ELSE 0
      END
      +
      CASE WHEN ki.is_verified THEN 5 ELSE 0 END
      +
      CASE WHEN p_story_id IS NOT NULL AND ki.story_id = p_story_id THEN 25 ELSE 0 END
    ) DESC
    LIMIT p_limit
  ) sub;

  RETURN v_results;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.mcp_search_knowledge_v2(p_query_embedding vector DEFAULT NULL::vector, p_query_text text DEFAULT NULL::text, p_item_types text[] DEFAULT '{}'::text[], p_category text DEFAULT NULL::text, p_expertise_slug text DEFAULT NULL::text, p_context_tags text[] DEFAULT '{}'::text[], p_include_ai_instructions boolean DEFAULT true, p_limit integer DEFAULT 20, p_similarity_threshold double precision DEFAULT 0.3)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_results jsonb;
  v_words text[];
  -- Globální přetížení nemá p_audience_user_id (kolidovalo by se story
  -- signaturou), takže publikem je vždy volající sám. Drží se tím totéž
  -- pravidlo viditelnosti jako u story přetížení — jen bez možnosti ptát se
  -- za někoho jiného.
  v_audience_user uuid;
BEGIN
  v_audience_user := auth.uid();
  IF p_query_text IS NOT NULL AND trim(p_query_text) != '' THEN
    v_words := ARRAY(
      SELECT w FROM unnest(regexp_split_to_array(lower(trim(p_query_text)), '\s+')) AS w
      WHERE length(w) >= 2
    );
    IF array_length(v_words, 1) IS NULL THEN
      v_words := NULL;
    END IF;
  ELSE
    v_words := NULL;
  END IF;

  SELECT COALESCE(jsonb_agg(result_row ORDER BY (result_row->>'score')::float DESC), '[]'::jsonb)
  INTO v_results
  FROM (
    SELECT jsonb_build_object(
      'knowledge_item_id', ki.id,
      'item_type', ki.item_type::text,
      'source_slug', ki.source_slug,
      'title', ki.title,
      'summary', ki.summary,
      'category', ki.category,
      'expertise_area_slug', gea.slug,
      'expertise_area_icon', gea.icon,
      'author_display_name', ki.author_display_name,
      'is_verified', ki.is_verified,
      'ai_context_tags', ki.ai_context_tags,
      'ai_instructions', CASE WHEN p_include_ai_instructions THEN ki.ai_instructions ELSE NULL END,
      'chunk_text', kc.chunk_text,
      'chunk_index', kc.chunk_index,
      -- Brick3 locale axis: surfaced for downstream consumers only. NO locale
      -- WHERE filter and NO locale score term — retrieval is byte-identical today.
      'locale', kc.locale,
      'similarity', CASE WHEN p_query_embedding IS NOT NULL AND ke.embedding IS NOT NULL
        THEN 1 - (ke.embedding <=> p_query_embedding)
        ELSE NULL END,
      'version', ki.version,
      'published_at', ki.published_at,
      'score', (
        CASE WHEN p_query_embedding IS NOT NULL AND ke.embedding IS NOT NULL
          THEN (1 - (ke.embedding <=> p_query_embedding)) * 40
          ELSE 0 END
        +
        CASE WHEN p_context_tags != '{}' AND ki.ai_context_tags && p_context_tags
          THEN COALESCE(array_length(
            ARRAY(SELECT unnest(ki.ai_context_tags) INTERSECT SELECT unnest(p_context_tags)),
            1
          ), 0) * 10
          ELSE 0 END
        +
        CASE WHEN v_words IS NOT NULL THEN
          (SELECT count(*)::int FROM unnest(v_words) AS word
           WHERE ki.title ILIKE '%' || word || '%'
              OR ki.summary ILIKE '%' || word || '%'
          ) * 15
          ELSE 0
        END
        +
        CASE WHEN ki.is_verified THEN 5 ELSE 0 END
      )
    ) AS result_row
    FROM knowledge_items ki
    LEFT JOIN knowledge_chunks kc ON kc.knowledge_item_id = ki.id
    LEFT JOIN knowledge_embeddings ke ON ke.chunk_id = kc.id
    LEFT JOIN guild_expertise_areas gea ON gea.id = ki.expertise_area_id
    WHERE ki.status = 'active'
      -- ── Viditelnost: TÁŽ pravidla, jaká deklaruje sama tabulka ──────────────
      -- Do 2026-07-30 tu stál paušál `visibility IN (public, members, guild)`.
      -- Byl PŘÍSNĚJŠÍ než RLS politika knowledge_items a odřízl přesně to, co
      -- máme: interní smlouvy jsou `private` a story-scoped, takže z nich
      -- retrieval nevrátil NIKDY nic (naměřeno: všech 4 292 chunků leží pod
      -- private+story; 791 „public" položek nemá ani jeden chunk).
      --
      -- Tohle NENÍ rozvolnění přístupu. Politika „Per-story KB visible to
      -- participants" o `visibility` vůbec nemluví — pouští vlastníka story,
      -- jejího účastníka a admin/staff. `private` tedy vylučuje z VEŘEJNÉ
      -- politiky, ne z oprávněných čtenářů. Definer funkce si vedle toho psala
      -- druhé, vlastní pravidlo — a dvě pravidla o jedné věci se rozešla.
      --
      -- Vyhodnocuje se proti v_audience_user (Brick6): service_role smí říct,
      -- ZA KOHO se ptá, jinak je to volající sám. Bez identity zbývá jen
      -- veřejná/globální vrstva — fail-closed, žádný service_role bypass.
      AND (
        (ki.story_id IS NULL AND ki.visibility IN ('public', 'members', 'guild'))
        OR ki.item_type::text IN ('core_value', 'personality_trait')
        OR public.is_admin_or_staff(v_audience_user)
        OR EXISTS (
          SELECT 1 FROM public.partner_stories ps
          WHERE ps.id = ki.story_id AND ps.user_id = v_audience_user
        )
        OR EXISTS (
          SELECT 1 FROM public.story_participants sp
          WHERE sp.story_id = ki.story_id AND sp.user_id = v_audience_user
        )
      )
      -- Step 4 systemic: hide flagged/quarantined items from retrieval.
      AND ki.quarantine_status NOT IN ('flagged', 'quarantined')
      -- Per-story isolation: this 9-arg overload takes NO p_story_id, so it is a
      -- GLOBAL-KB search. Per-story items default to visibility='public'
      -- (upsert_story_knowledge_item_audited), so without this clause an anon
      -- caller could read EVERY story's chunks. Restrict to global items only;
      -- story-scoped retrieval goes through the 10-arg overload (p_story_id + the
      -- RBAC guard above), mcp_search_knowledge_v3, or compose_context.
      AND ki.story_id IS NULL
      AND (p_item_types = '{}' OR ki.item_type::text = ANY(p_item_types))
      AND (p_category IS NULL OR ki.category = p_category)
      AND (p_expertise_slug IS NULL OR gea.slug = p_expertise_slug)
      AND (
        p_query_embedding IS NULL
        OR ke.embedding IS NULL
        OR (1 - (ke.embedding <=> p_query_embedding)) >= p_similarity_threshold
      )
      AND (
        p_query_embedding IS NOT NULL
        OR (v_words IS NOT NULL AND EXISTS (
          SELECT 1 FROM unnest(v_words) AS word
          WHERE ki.title ILIKE '%' || word || '%'
             OR ki.summary ILIKE '%' || word || '%'
        ))
        -- Bez tohohle by dokument, jehož ZNĚNÍ dotazu odpovídá, nebyl vůbec
        -- kandidátem — skóre výš by se na něj nikdy nedostalo.
        OR (v_words IS NOT NULL AND kc.chunk_text IS NOT NULL AND EXISTS (
          SELECT 1 FROM unnest(v_words) AS word
          WHERE public.norm_text(kc.chunk_text) LIKE '%' || public.norm_text(word) || '%'
        ))
        OR p_context_tags != '{}'
        OR (p_item_types != '{}')
      )
      -- Brick6 tier-ACL: HARD filter. The GLOBAL overload pins the audience user to auth.uid()
      -- (no service override here — to avoid colliding with the story overload's signature;
      -- a service/no-user caller falls CLOSED to anonymous = ungated content only).
      AND (ki.minimum_tier IS NULL OR public.audience_user_meets_tier_requirement(ki.minimum_tier, auth.uid()))
    ORDER BY (
      CASE WHEN p_query_embedding IS NOT NULL AND ke.embedding IS NOT NULL
        THEN (1 - (ke.embedding <=> p_query_embedding)) * 40
        ELSE 0 END
      +
      CASE WHEN p_context_tags != '{}' AND ki.ai_context_tags && p_context_tags
        THEN COALESCE(array_length(
          ARRAY(SELECT unnest(ki.ai_context_tags) INTERSECT SELECT unnest(p_context_tags)),
          1
        ), 0) * 10
        ELSE 0 END
      +
      CASE WHEN v_words IS NOT NULL THEN
        (SELECT count(*)::int FROM unnest(v_words) AS word
         WHERE ki.title ILIKE '%' || word || '%'
            OR ki.summary ILIKE '%' || word || '%'
        ) * 15
        ELSE 0
      END
      +
      CASE WHEN ki.is_verified THEN 5 ELSE 0 END
    ) DESC
    LIMIT p_limit
  ) sub;

  RETURN v_results;
END;
$function$
;

REVOKE ALL ON FUNCTION mcp_search_knowledge_v2(vector,text,text[],text,text,text[],boolean,integer,double precision) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mcp_search_knowledge_v2(vector,text,text[],text,text,text[],boolean,integer,double precision) TO anon;
GRANT EXECUTE ON FUNCTION mcp_search_knowledge_v2(vector,text,text[],text,text,text[],boolean,integer,double precision) TO authenticated;
GRANT EXECUTE ON FUNCTION mcp_search_knowledge_v2(vector,text,text[],text,text,text[],boolean,integer,double precision) TO service_role;

REVOKE ALL ON FUNCTION mcp_search_knowledge_v2(vector,text,text[],text,text,text[],boolean,integer,double precision,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mcp_search_knowledge_v2(vector,text,text[],text,text,text[],boolean,integer,double precision,uuid,uuid) TO anon;
GRANT EXECUTE ON FUNCTION mcp_search_knowledge_v2(vector,text,text[],text,text,text[],boolean,integer,double precision,uuid,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION mcp_search_knowledge_v2(vector,text,text[],text,text,text[],boolean,integer,double precision,uuid,uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/compose_context.sql
-- -----------------------------------------------------------------------------

-- Source of Truth: compose_context
-- Purpose: Build a context bundle for an AI agent based on a context profile.
--          Assembles project context, rulesets, KB retrieval, agent memory, trace memory,
--          governance (TAO) and personality (Psyché) layers within a token budget.
--          Traces the compose event.
--          Phase E: Query-based rule relevance scoring — only pertinent rules in system prompt.
--          Psyché module: personality_context layer for character DNA (unconditional).
-- Used by: ai-context-composer edge function, orchestrationBridge.ts
-- Migration: 20260216_aisha_phase3_router.sql (original), 20260309091500 (agent memory),
--            20260312214929 (fix GROUP BY + LIMIT bugs), 20260329100000 (project-scoped KB + scoring),
--            20260405133819 (Phase E: query-based rule relevance filtering),
--            20260603002713 (Step 7.3: graph_context retrieval layer — seeds from
--                            kb_retrieval, walks fn_graph_multihop; enabled on RAG profiles)

-- Drop the legacy 5-arg signature so the requester-scoped 6-arg version below is
-- the ONLY overload. Without this, an upgrade-in-place would leave both — and a
-- PostgREST call omitting p_requester_id could resolve to the old unguarded
-- function, re-opening LEAK 2. No-op on a fresh baseline apply (IF EXISTS).
DROP FUNCTION IF EXISTS public.compose_context(uuid, text, uuid, text, text);

CREATE OR REPLACE FUNCTION public.compose_context(
  p_story_id uuid,
  p_context_profile_slug text DEFAULT 'repo_plus_rules'::text,
  p_run_id uuid DEFAULT NULL::uuid,
  p_query text DEFAULT NULL::text,
  p_agent_slug text DEFAULT NULL::text,
  p_requester_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_profile RECORD;
  v_bundle jsonb := '{}'::jsonb;
  v_project_ctx jsonb;
  v_project_preview_ctx jsonb;
  v_ruleset_ctx jsonb;
  v_kb_ctx jsonb;
  v_memory_ctx jsonb;
  v_agent_memory_ctx jsonb;
  v_governance_ctx jsonb;
  v_psyche_ctx jsonb;
  v_tokens_used int := 0;
  v_layer text;
  v_user_id uuid;
  v_requester uuid;
  -- Phase A: project scoping variables
  v_story_domain text[];
  v_story_tech_stack text[];
  v_project_tags text[];
  v_max_chunks int;
  -- Phase E: query-based rule filtering
  v_query_lower text;
BEGIN
  -- ── RBAC: a story-scoped composition requires a verified requester ─────────
  -- compose_context is SECURITY DEFINER and GRANTed to service_role, so its internal
  -- mcp_search_knowledge_v2(p_story_id) call runs as service_role and BYPASSES v2's own
  -- per-story RBAC. The MCP tool surface is safe (it runs as the user via rpcUserClaims),
  -- but the agent path (orchestrationBridge.enrichWithAishaContext) reaches this through a
  -- service-role client and could otherwise be pointed at ANY p_story_id and leak that
  -- story's KB / learnings / graph layers — a cross-tenant RAG leak.
  --
  -- Fail-closed: when p_story_id is set, a requester WITH access is required. Authenticated
  -- direct callers fall back to auth.uid(); service-role orchestration MUST pass
  -- p_requester_id. Unlike a permissive `p_requester_id IS NOT NULL` skip, a NULL identity on
  -- a story-scoped call is REFUSED — a genuine background job passes an explicit system
  -- principal as p_requester_id rather than relying on a silent service-role bypass.
  IF p_story_id IS NOT NULL THEN
    v_requester := COALESCE(p_requester_id, auth.uid());
    IF v_requester IS NULL THEN
      RAISE EXCEPTION 'compose_context: p_requester_id required for a story-scoped composition'
        USING ERRCODE = '42501';
    END IF;
    IF NOT (
      public.is_admin_or_staff(v_requester)
      OR EXISTS (SELECT 1 FROM public.partner_stories ps WHERE ps.id = p_story_id AND ps.user_id = v_requester)
      OR EXISTS (SELECT 1 FROM public.story_participants sp WHERE sp.story_id = p_story_id AND sp.user_id = v_requester)
    ) THEN
      RAISE EXCEPTION 'Access denied to story %', p_story_id USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Load profile
  SELECT * INTO v_profile
  FROM context_profiles
  WHERE slug = p_context_profile_slug AND is_active = true;

  IF v_profile IS NULL THEN
    RAISE EXCEPTION 'Context profile not found: %', p_context_profile_slug
      USING ERRCODE = 'P0002';
  END IF;

  -- Try to get user_id and project metadata from the story
  IF p_story_id IS NOT NULL THEN
    SELECT s.user_id, s.domain, s.tech_stack
    INTO v_user_id, v_story_domain, v_story_tech_stack
    FROM partner_stories s
    WHERE s.id = p_story_id;
  END IF;

  -- Phase A: Build project-scoped context tags for KB filtering
  -- Convention: project tags like 'project:acme', domain/tech tags
  v_project_tags := COALESCE(v_story_domain, '{}') || COALESCE(v_story_tech_stack, '{}');

  -- Phase E: Prepare query for rule relevance scoring
  v_query_lower := lower(COALESCE(p_query, ''));

  -- Build each layer in priority order
  FOREACH v_layer IN ARRAY v_profile.priority_order
  LOOP
    -- Respect token budget
    IF v_tokens_used >= v_profile.token_budget THEN
      EXIT;
    END IF;

    CASE v_layer
      WHEN 'project_context' THEN
        IF (v_profile.layers->'project_context'->>'enabled')::boolean THEN
          SELECT mcp_get_story_context(p_story_id) INTO v_project_ctx;
          v_bundle := v_bundle || jsonb_build_object('project_context', v_project_ctx);
          v_tokens_used := v_tokens_used + 500;
        END IF;

      WHEN 'project_preview' THEN
        IF (v_profile.layers->'project_preview'->>'enabled')::boolean AND p_story_id IS NOT NULL THEN
          SELECT ps.project_preview INTO v_project_preview_ctx
          FROM partner_stories ps
          WHERE ps.id = p_story_id;

          IF v_project_preview_ctx IS NOT NULL THEN
            v_bundle := v_bundle || jsonb_build_object('project_preview', v_project_preview_ctx);
            v_tokens_used := v_tokens_used + 300;
          END IF;
        END IF;

      WHEN 'ruleset' THEN
        IF (v_profile.layers->'ruleset'->>'enabled')::boolean THEN
          -- Phase E: Query-based rule relevance filtering.
          -- When p_query is provided, rules are scored by text relevance
          -- so only the most pertinent rules enter the system prompt.
          -- Without query, all rules are equally weighted (score=1).
          SELECT jsonb_build_object(
            'fingerprint', sr.ruleset_fingerprint,
            'rules', COALESCE((
              SELECT jsonb_agg(
                jsonb_build_object(
                  'slug', scored.slug,
                  'title', scored.title,
                  'category', scored.category,
                  'ai_instructions', scored.ai_instructions,
                  'relevance_score', scored.relevance_score
                ) ||
                CASE
                  WHEN (v_profile.layers->'ruleset'->>'include_body')::boolean
                  THEN jsonb_build_object('body_markdown', scored.body_markdown)
                  ELSE '{}'::jsonb
                END
                ORDER BY scored.relevance_score DESC, scored.slug
              )
              FROM (
                -- CTE-like subquery: score each rule once
                SELECT
                  er.slug,
                  er.title,
                  er.category,
                  er.ai_instructions,
                  er.body_markdown,
                  CASE
                    WHEN v_query_lower = '' THEN 1
                    ELSE (
                      -- Title word match: highest signal
                      CASE WHEN v_query_lower ~ ANY(
                        string_to_array(
                          regexp_replace(lower(er.title), '[^a-z0-9]+', '|', 'g'),
                          '|'
                        )
                      ) THEN 10 ELSE 0 END
                      +
                      -- AI instructions: query words (4+ chars) match
                      CASE WHEN lower(COALESCE(er.ai_instructions, '')) ~ ANY(
                        ARRAY(
                          SELECT w FROM unnest(
                            string_to_array(
                              regexp_replace(v_query_lower, '[^a-záčďéěíňóřšťúůýž0-9]+', ' ', 'g'),
                              ' '
                            )
                          ) AS w
                          WHERE length(w) >= 4
                        )
                      ) THEN 5 ELSE 0 END
                      +
                      -- Category match
                      CASE WHEN v_query_lower LIKE '%' || replace(lower(er.category::text), '_', ' ') || '%'
                        OR v_query_lower LIKE '%' || replace(lower(er.category::text), '_', '%') || '%'
                      THEN 3 ELSE 0 END
                      +
                      -- Base: every rule gets minimum 1
                      1
                    )
                  END AS relevance_score
                FROM expert_rules er
                WHERE er.id = ANY(sr.rule_ids)
                  AND er.status = 'published'
                ORDER BY relevance_score DESC, er.slug
                LIMIT COALESCE((v_profile.layers->'ruleset'->>'max_rules')::int, 20)
              ) scored
              -- Phase E: When query is present, filter out irrelevant rules (base-only score).
              -- min_relevance_score in profile overrides default threshold of 2.
              WHERE CASE
                WHEN v_query_lower = '' THEN true  -- no query → keep all rules
                ELSE scored.relevance_score >= COALESCE(
                  (v_profile.layers->'ruleset'->>'min_relevance_score')::int, 2
                )
              END
            ), '[]'::jsonb)
          ) INTO v_ruleset_ctx
          FROM story_contexts sc
          JOIN story_rulesets sr ON sr.id = sc.ruleset_id
          WHERE sc.story_id = p_story_id;

          IF v_ruleset_ctx IS NOT NULL THEN
            v_bundle := v_bundle || jsonb_build_object('ruleset', v_ruleset_ctx);
            v_tokens_used := v_tokens_used + COALESCE(
              (SELECT count(*) FROM jsonb_array_elements(v_ruleset_ctx->'rules')) *
                CASE WHEN (v_profile.layers->'ruleset'->>'include_body')::boolean THEN 300 ELSE 100 END,
              0
            );
          END IF;
        END IF;

      WHEN 'kb_retrieval' THEN
        IF (v_profile.layers->'kb_retrieval'->>'enabled')::boolean AND p_query IS NOT NULL THEN
          v_max_chunks := COALESCE((v_profile.layers->'kb_retrieval'->>'max_chunks')::int, 10);

          -- Phase D: Use mcp_search_knowledge_v2 scoring instead of naive created_at ordering
          -- Phase A: Filter by project tags from story metadata
          SELECT jsonb_build_object(
            'chunks', COALESCE(
              (SELECT jsonb_agg(jsonb_build_object(
                'knowledge_item_id', (r->>'knowledge_item_id')::uuid,
                'title', r->>'title',
                'chunk_text', r->>'chunk_text',
                'source_slug', r->>'source_slug',
                'score', (r->>'score')::float
              ))
              FROM (
                SELECT jsonb_array_elements(
                  mcp_search_knowledge_v2(
                    p_query_embedding := NULL,  -- No embedding in compose_context (text-only search)
                    p_query_text := p_query,
                    p_context_tags := v_project_tags,
                    p_limit := v_max_chunks,
                    p_story_id := p_story_id,   -- Per-story isolation: search scoped to this story + globals
                    p_audience_user_id := v_requester  -- Brick6 tier-ACL: gate by the requesting user's tier
                  )
                ) AS r
              ) sub),
              '[]'::jsonb
            )
          ) INTO v_kb_ctx;

          v_bundle := v_bundle || jsonb_build_object('kb_retrieval', v_kb_ctx);
          v_tokens_used := v_tokens_used +
            COALESCE((SELECT count(*) FROM jsonb_array_elements(v_kb_ctx->'chunks')) * 150, 0);
        END IF;

      WHEN 'agent_memory' THEN
        IF (v_profile.layers->'agent_memory'->>'enabled')::boolean AND p_agent_slug IS NOT NULL THEN
          -- Subquery so LIMIT actually restricts rows before aggregation
          SELECT COALESCE(
            (SELECT jsonb_agg(sub.obj) FROM (
              SELECT jsonb_build_object(
                'type', am.memory_type,
                'content', am.content,
                'importance', am.importance
              ) AS obj
              FROM agent_memories am
              WHERE am.agent_slug = p_agent_slug
                AND (am.user_id IS NULL OR am.user_id = v_user_id)
                AND am.importance >= COALESCE((v_profile.layers->'agent_memory'->>'min_importance')::int, 3)
                AND (am.expires_at IS NULL OR am.expires_at > now())
              ORDER BY am.importance DESC, am.created_at DESC
              LIMIT COALESCE((v_profile.layers->'agent_memory'->>'max_memories')::int, 10)
            ) sub),
            '[]'::jsonb
          ) INTO v_agent_memory_ctx;

          IF jsonb_array_length(v_agent_memory_ctx) > 0 THEN
            v_bundle := v_bundle || jsonb_build_object('agent_memory', v_agent_memory_ctx);
            -- Estimate: ~50 tokens per memory
            v_tokens_used := v_tokens_used + jsonb_array_length(v_agent_memory_ctx) * 50;
          END IF;
        END IF;

      WHEN 'memory' THEN
        IF (v_profile.layers->'memory'->>'enabled')::boolean AND p_run_id IS NOT NULL THEN
          -- Subquery so ORDER BY + LIMIT apply to rows before jsonb_agg()
          SELECT jsonb_build_object(
            'events', COALESCE(
              (SELECT jsonb_agg(sub.obj) FROM (
                SELECT jsonb_build_object(
                  'event_type', ate.event_type,
                  'status', ate.status,
                  'operation', ate.operation,
                  'agent_slug', ate.agent_slug,
                  'created_at', ate.created_at
                ) AS obj
                FROM ai_trace_events ate
                WHERE ate.run_id = p_run_id
                ORDER BY ate.created_at DESC
                LIMIT COALESCE((v_profile.layers->'memory'->>'max_events')::int, 10)
              ) sub),
              '[]'::jsonb
            )
          ) INTO v_memory_ctx;

          v_bundle := v_bundle || jsonb_build_object('memory', v_memory_ctx);
          v_tokens_used := v_tokens_used +
            COALESCE((SELECT count(*) FROM jsonb_array_elements(v_memory_ctx->'events')) * 50, 0);
        END IF;

      ELSE
        -- =====================================================================
        -- Named brain module layers (governance_context, psyche_context)
        -- These are unconditional — they define AISHA's core identity.
        -- =====================================================================

        -- TAO: governance_context — philosophical foundation, risk/escalation decisions
        IF v_layer = 'governance_context' THEN
          SELECT jsonb_build_object(
            'tao_principles', fn_get_tao_principles()
          ) INTO v_governance_ctx;

          IF v_governance_ctx IS NOT NULL AND
             jsonb_array_length(v_governance_ctx->'tao_principles') > 0 THEN
            v_bundle := v_bundle || jsonb_build_object('governance_context', v_governance_ctx);
            v_tokens_used := v_tokens_used +
              jsonb_array_length(v_governance_ctx->'tao_principles') * 30;
          END IF;
        END IF;

        -- Psyché: psyche_context — character DNA, behavioral patterns, warmth
        -- Unconditional: personality shapes EVERY response, not just governance.
        IF v_layer = 'psyche_context' THEN
          SELECT jsonb_build_object(
            'psyche_traits', fn_get_psyche_traits()
          ) INTO v_psyche_ctx;

          IF v_psyche_ctx IS NOT NULL AND
             jsonb_array_length(v_psyche_ctx->'psyche_traits') > 0 THEN
            v_bundle := v_bundle || jsonb_build_object('psyche_context', v_psyche_ctx);
            -- ~40 tokens per trait (includes ai_instructions + cluster)
            v_tokens_used := v_tokens_used +
              jsonb_array_length(v_psyche_ctx->'psyche_traits') * 40;
          END IF;
        END IF;

        -- Hippocampus learnings: pattern→resolution memories from prior reflection runs.
        -- Reuse-tracked: every retrieval touches updated_at + audits to audit_journal,
        -- enabling fn_maybe_promote_learning to promote to expert_rules.
        -- Note: requires p_query (text used for cheap server-side embedding via fn_search_learnings).
        IF v_layer = 'learnings' THEN
          IF (v_profile.layers->'learnings'->>'enabled')::boolean AND p_query IS NOT NULL THEN
            DECLARE
              v_learnings_ctx jsonb;
              v_max int := COALESCE((v_profile.layers->'learnings'->>'max_learnings')::int, 5);
              v_min_importance int := COALESCE((v_profile.layers->'learnings'->>'min_importance')::int, 3);
              v_query_embedding vector(1024);
            BEGIN
              -- Get embedding for query if knowledge_embeddings pipeline is available.
              -- Fallback: skip when embedding not derivable (caller should pre-compute).
              BEGIN
                SELECT ke.embedding
                INTO v_query_embedding
                FROM knowledge_embeddings ke
                JOIN knowledge_chunks kc ON kc.id = ke.chunk_id
                JOIN knowledge_items ki ON ki.id = kc.knowledge_item_id
                WHERE lower(kc.chunk_text) LIKE '%' || lower(p_query) || '%'
                LIMIT 1;
              EXCEPTION WHEN OTHERS THEN
                v_query_embedding := NULL;
              END;

              IF v_query_embedding IS NOT NULL THEN
                v_learnings_ctx := fn_search_learnings(
                  p_query_embedding := v_query_embedding,
                  p_story_id := p_story_id,
                  p_agent_slug := COALESCE(p_agent_slug, 'aisha'),
                  p_limit := v_max,
                  p_min_importance := v_min_importance
                );

                IF v_learnings_ctx IS NOT NULL AND jsonb_array_length(v_learnings_ctx) > 0 THEN
                  v_bundle := v_bundle || jsonb_build_object('learnings', v_learnings_ctx);
                  -- ~60 tokens per learning (content + critic context)
                  v_tokens_used := v_tokens_used + jsonb_array_length(v_learnings_ctx) * 60;
                END IF;
              END IF;
            END;
          END IF;
        END IF;

        -- Knowledge graph: the concepts/rules/memories the just-retrieved KB items
        -- connect to. Seeds from the kb_retrieval chunks (v_kb_ctx) → graph_nodes →
        -- fn_graph_multihop. Requires kb_retrieval to run earlier in priority_order so
        -- v_kb_ctx is populated. Reuses the exact traversal proven by
        -- fn_get_run_graph_context (Step 7.3) — here applied at compose time so the LLM
        -- can reason over the graph, not just see it in the explainability panel.
        IF v_layer = 'graph_context' THEN
          IF (v_profile.layers->'graph_context'->>'enabled')::boolean
             AND v_kb_ctx IS NOT NULL
             AND jsonb_array_length(COALESCE(v_kb_ctx->'chunks', '[]'::jsonb)) > 0 THEN
            DECLARE
              v_graph_ctx jsonb;
              -- Graph traversal depth/per_seed are governance-relevant reasoning
              -- budget → the typed, CHECK-constrained context_profiles columns are the
              -- single SoT (queryable by the resolver/admission), NOT the layers JSONB.
              -- fn_get_run_graph_context (explainability panel) reads the same columns,
              -- so panel-depth == retrieval-depth. max_edges stays per-layer JSONB config.
              v_graph_depth int := v_profile.graph_depth;
              v_graph_per_seed int := v_profile.graph_per_seed;
              v_graph_max int := COALESCE(
                (v_profile.layers->'graph_context'->>'max_edges')::int, 20);
            BEGIN
              SELECT COALESCE(
                       jsonb_agg(e.obj ORDER BY e.confidence DESC NULLS LAST, e.depth ASC),
                       '[]'::jsonb)
              INTO v_graph_ctx
              FROM (
                WITH seeds AS (
                  SELECT DISTINCT ON (gn.id)
                         gn.id          AS seed_id,
                         gn.entity_label AS seed_label
                  FROM jsonb_array_elements(v_kb_ctx->'chunks') AS c
                  JOIN graph_nodes gn
                    ON gn.source_table = 'knowledge_items'
                   AND gn.source_id = (c->>'knowledge_item_id')::uuid
                  ORDER BY gn.id,
                           (gn.story_id IS NOT DISTINCT FROM p_story_id) DESC,
                           gn.created_at ASC
                ),
                hops AS (
                  SELECT s.seed_label,
                         h.target_label,
                         h.target_type,
                         h.depth,
                         h.cumulative_confidence,
                         h.last_relationship
                  FROM seeds s
                  CROSS JOIN LATERAL public.fn_graph_multihop(
                    s.seed_id, v_graph_depth, NULL::text[], p_story_id, v_graph_per_seed
                  ) h
                  WHERE h.depth > 0
                )
                SELECT jsonb_build_object(
                         'from',       hops.seed_label,
                         'rel',        hops.last_relationship,
                         'to',         hops.target_label,
                         'type',       hops.target_type,
                         'depth',      hops.depth,
                         'confidence', round(hops.cumulative_confidence, 3)
                       ) AS obj,
                       hops.cumulative_confidence AS confidence,
                       hops.depth                 AS depth
                FROM hops
                ORDER BY hops.cumulative_confidence DESC NULLS LAST, hops.depth ASC
                LIMIT v_graph_max
              ) e;

              IF v_graph_ctx IS NOT NULL AND jsonb_array_length(v_graph_ctx) > 0 THEN
                v_bundle := v_bundle || jsonb_build_object('graph_context', v_graph_ctx);
                -- ~25 tokens per edge (from/rel/to/type/confidence)
                v_tokens_used := v_tokens_used + jsonb_array_length(v_graph_ctx) * 25;
              END IF;
            END;
          END IF;
        END IF;

        -- Unknown layer, skip
    END CASE;
  END LOOP;

  -- Trace the compose event if we have a run
  IF p_run_id IS NOT NULL THEN
    INSERT INTO ai_trace_events (run_id, event_type, operation, status, response_summary)
    VALUES (p_run_id, 'context_compose', 'compose_context', 'ok',
      jsonb_build_object('profile', p_context_profile_slug, 'tokens_used', v_tokens_used, 'agent_slug', p_agent_slug)
    );
  END IF;

  RETURN jsonb_build_object(
    'profile', p_context_profile_slug,
    'token_budget', v_profile.token_budget,
    'tokens_used', v_tokens_used,
    'layers', v_bundle,
    'profile_layers', v_profile.layers
  );
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.compose_context(uuid, text, uuid, text, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.compose_context(uuid, text, uuid, text, text, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.compose_context(uuid, text, uuid, text, text, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/normalize_task_kind.sql
-- -----------------------------------------------------------------------------

-- Function: public.normalize_task_kind  (T1 — non-ossifying task_kind normalizer)
-- The ONE normalizer for task_kind across the stack. Pure/IMMUTABLE: lower-case, trim, collapse
-- internal whitespace to '_'. Empty/NULL → 'chat' (the established resolver default, line 37 of
-- aisha_resolve_clow_backend: COALESCE(p_clow->>'task_kind','chat')) — so this is a no-op on the
-- existing clean vocabulary ('chat','classification','reasoning','extraction','embedding') and a
-- pure robustness win on dirty input ('Chat ' → 'chat', 'multi step' → 'multi_step').
--
-- DELIBERATELY NOT a closed set: any string maps to a normalized string. There is no enum / DOMAIN /
-- CHECK that could reject an unseen kind — the taxonomy stays OPEN and grows from reality
-- (ai_task_kind_registry is observed, not authoritative). This is the anti-ossification rule the
-- owner mandated ("abychom nikde nezatvrdli").

CREATE OR REPLACE FUNCTION public.normalize_task_kind(p_raw text)
RETURNS text
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
AS $$
  SELECT COALESCE(
    NULLIF(regexp_replace(lower(btrim(p_raw)), '\s+', '_', 'g'), ''),
    'chat'
  );
$$;

COMMENT ON FUNCTION public.normalize_task_kind(text) IS
  'T1: the single, pure task_kind normalizer (lower/trim/collapse-ws; empty→chat). Idempotent on the existing vocabulary; never rejects an unseen kind (taxonomy stays open).';

GRANT EXECUTE ON FUNCTION public.normalize_task_kind(text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_observe_task_kind.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_observe_task_kind  (T1 — record an observed task_kind)
-- Normalizes p_task_kind and upserts it into the observed registry (bumps sample_count + last_seen_at).
-- Descriptive only — it records what was seen; it never rejects or gates. Returns the normalized kind.
-- service_role (rollup/cron) or admin/staff only (it writes the registry).

CREATE OR REPLACE FUNCTION public.fn_observe_task_kind(
  p_task_kind text,
  p_n         bigint DEFAULT 1
)
RETURNS text
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_norm text;
BEGIN
  IF auth.uid() IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') IS DISTINCT FROM 'service_role'
     AND NOT public.is_admin_or_staff(auth.uid())
  THEN
    RAISE EXCEPTION 'Not authorized: service_role or admin/staff required' USING ERRCODE = '42501';
  END IF;

  v_norm := public.normalize_task_kind(p_task_kind);

  INSERT INTO public.ai_task_kind_registry (task_kind, sample_count, first_seen_at, last_seen_at)
  VALUES (v_norm, GREATEST(p_n, 0), now(), now())
  ON CONFLICT (task_kind) DO UPDATE
    SET sample_count = public.ai_task_kind_registry.sample_count + GREATEST(EXCLUDED.sample_count, 0),
        last_seen_at = now();

  RETURN v_norm;
END $$;

COMMENT ON FUNCTION public.fn_observe_task_kind(text, bigint) IS
  'T1: normalize + upsert an observed task_kind into ai_task_kind_registry (descriptive; never gates). service_role/admin only.';

REVOKE ALL ON FUNCTION public.fn_observe_task_kind(text, bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_observe_task_kind(text, bigint) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/notify_expert_rules_changed.sql
-- -----------------------------------------------------------------------------

-- Function: notify_expert_rules_changed

CREATE OR REPLACE FUNCTION public.notify_expert_rules_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule_slug text;
  v_action text;
  v_admin_id uuid;
BEGIN
  -- Determine which rule changed
  IF TG_OP = 'DELETE' THEN
    v_rule_slug := OLD.slug;
  ELSE
    v_rule_slug := NEW.slug;
  END IF;

  v_action := TG_OP;

  -- Notify all admin and staff users (limit 50 to prevent runaway)
  FOR v_admin_id IN
    SELECT DISTINCT ur.user_id
    FROM user_roles ur
    WHERE ur.role IN ('admin', 'staff')
    LIMIT 50
  LOOP
    INSERT INTO notifications (user_id, title, message, type, metadata)
    VALUES (
      v_admin_id,
      'Expert rules updated: ' || COALESCE(v_rule_slug, 'unknown'),
      'Rule "' || COALESCE(v_rule_slug, 'unknown') || '" was ' ||
        CASE v_action
          WHEN 'INSERT' THEN 'added'
          WHEN 'UPDATE' THEN 'modified'
          WHEN 'DELETE' THEN 'removed'
          ELSE 'changed'
        END || '. Sync copilot-instructions.md to get the latest rules.',
      'rules_updated',
      jsonb_build_object(
        'source', 'aisha',
        'rule_slug', COALESCE(v_rule_slug, 'unknown'),
        'operation', v_action,
        'auto_sync', true
      )
    );
  END LOOP;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION notify_expert_rules_changed() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION notify_expert_rules_changed() TO authenticated;
GRANT EXECUTE ON FUNCTION notify_expert_rules_changed() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/obdobi_od_param.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: obdobi_od_param
-- Popis: ZAČÁTEK MĚSÍCE, za který čtečka počítá (kniha faktur za měsíc) —
--        z parametrů bloku, v tomto pořadí:
--          1. `mesic` (klientský parametr, date: kterýkoli den měsíce) — volba uživatele,
--          2. `obdobi_vychozi` (konfigurace instance): 'aktualni_mesic' = tento měsíc,
--          3. nic = NULL = celá historie (dosavadní chování čteček).
--        Výchozí hodnota je v konfiguraci pod JINÝM klíčem než volba klienta —
--        konfigurace je autoritativní a klíč, který nese, klient nepřepíše
--        (surface_client_params_filter). Neznámá hodnota `obdobi_vychozi` nebo
--        neplatné datum `mesic` = chyba konfigurace/volání (22023), ne tichá
--        celá historie. Volá se JEDNOU na dotaz (cfg čtečky).
-- STABLE: čte current_date.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.obdobi_od_param(p_params jsonb)
RETURNS date
LANGUAGE plpgsql
STABLE
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_mesic   text := nullif(btrim(coalesce(p_params->>'mesic', '')), '');
  v_vychozi text := nullif(btrim(coalesce(p_params->>'obdobi_vychozi', '')), '');
BEGIN
  IF v_mesic IS NOT NULL THEN
    IF v_mesic !~ '^\d{4}-\d{2}-\d{2}' THEN
      RAISE EXCEPTION 'mesic=% není datum (YYYY-MM-DD)', v_mesic USING ERRCODE = '22023';
    END IF;
    RETURN date_trunc('month', left(v_mesic, 10)::date)::date;
  END IF;
  IF v_vychozi IS NULL THEN
    RETURN NULL;
  END IF;
  IF v_vychozi <> 'aktualni_mesic' THEN
    RAISE EXCEPTION 'obdobi_vychozi=% není známé období (aktualni_mesic)', v_vychozi USING ERRCODE = '22023';
  END IF;
  RETURN date_trunc('month', current_date)::date;
END;
$$;

REVOKE ALL ON FUNCTION public.obdobi_od_param(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obdobi_od_param(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/owasp_rls_coverage_report.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: owasp_rls_coverage_report
--
-- OWASP A01 — produces a coverage report of RLS enforcement across all user-
-- facing tables in the `public` schema. Returns one row per table with:
--   - has_rls       — whether ALTER TABLE … ENABLE ROW LEVEL SECURITY is set
--   - policy_count  — number of CREATE POLICY entries
--   - is_force_rls  — whether RLS bypass is denied even to table owners
--   - gap_reason    — null if compliant, otherwise short diagnostic message
--
-- Intended consumers:
--   1. CI gate test (src/tests/gates/owasp-rls-coverage.gate.test.ts) — fails
--      the build when a new table is added without RLS or policies.
--   2. Admin dashboard panel — operator visibility into the security posture.
--
-- Authorization: admin/staff only (sensitive infrastructure metadata).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.owasp_rls_coverage_report()
RETURNS TABLE (
  table_name    text,
  has_rls       boolean,
  is_force_rls  boolean,
  policy_count  integer,
  gap_reason    text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff required';
  END IF;

  RETURN QUERY
  SELECT
    t.tablename::text                                                AS table_name,
    c.relrowsecurity                                                 AS has_rls,
    c.relforcerowsecurity                                            AS is_force_rls,
    COALESCE(p.policy_count, 0)::int                                 AS policy_count,
    CASE
      WHEN NOT c.relrowsecurity THEN 'rls_disabled'
      WHEN COALESCE(p.policy_count, 0) = 0 THEN 'no_policies'
      WHEN c.relrowsecurity AND NOT c.relforcerowsecurity AND t.tableowner = 'postgres' THEN 'rls_bypassable_by_owner'
      ELSE NULL
    END                                                              AS gap_reason
  FROM pg_tables t
  JOIN pg_class c ON c.relname = t.tablename AND c.relkind = 'r'
  LEFT JOIN (
    SELECT polrelid, COUNT(*)::int AS policy_count
    FROM pg_policy
    GROUP BY polrelid
  ) p ON p.polrelid = c.oid
  WHERE t.schemaname = 'public'
  ORDER BY (CASE WHEN c.relrowsecurity THEN 1 ELSE 0 END), t.tablename;
END;
$$;

REVOKE ALL ON FUNCTION public.owasp_rls_coverage_report() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.owasp_rls_coverage_report() TO authenticated;
GRANT EXECUTE ON FUNCTION public.owasp_rls_coverage_report() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/persist_batch_result_and_resume.sql
-- -----------------------------------------------------------------------------

-- Function: persist_batch_result_and_resume
-- WF_BATCH_RESUMER calls this after fetching + normalizing batch results
-- from the provider (Anthropic results_url or OpenAI files/{id}/content).
--
-- Mutations (atomic):
--   1. ai_runs.metadata.checkpoint.state.batch_result ← normalized result
--   2. ai_runs.metadata.checkpoint.state.last_generation ← extracted text
--      (so a downstream node can read it like any other sync generator output)
--   3. ai_runs.status: 'waiting_batch' → 'running'
--   4. ai_runs.cost_total_json: accrue tokens_input + tokens_output
--   5. audit_journal: action='batch.resumed' with batch_job_id + run_id
--
-- Idempotency: if ai_runs.status != 'waiting_batch' (e.g. someone already
-- resumed it, or run was cancelled), this is a no-op success — caller should
-- treat as already-processed and skip the runWorkflow re-invocation.
--
-- The actual orchestrator re-invocation (runWorkflow) happens TS-side via
-- the /reflect/runs/:id/resume-batch endpoint — this RPC just does the
-- DB-side state transition.

CREATE OR REPLACE FUNCTION public.persist_batch_result_and_resume(
  p_batch_job_id   uuid,
  p_result         jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_job             RECORD;
  v_run             RECORD;
  v_new_metadata    jsonb;
  v_tokens_input    int;
  v_tokens_output   int;
  v_text            text;
  v_already_resumed boolean := false;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  IF p_batch_job_id IS NULL THEN
    RAISE EXCEPTION 'p_batch_job_id required' USING ERRCODE = '22023';
  END IF;
  IF p_result IS NULL OR jsonb_typeof(p_result) != 'object' THEN
    RAISE EXCEPTION 'p_result must be a JSON object' USING ERRCODE = '22023';
  END IF;

  -- Lock the row to prevent concurrent resumers from racing.
  SELECT * INTO v_job
  FROM   ai_batch_jobs
  WHERE  id = p_batch_job_id
  FOR    UPDATE;

  IF v_job IS NULL THEN
    RAISE EXCEPTION 'Batch job % not found', p_batch_job_id USING ERRCODE = '22023';
  END IF;

  IF v_job.related_run_id IS NULL THEN
    RAISE EXCEPTION 'Batch job % has no related_run_id', p_batch_job_id USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_run
  FROM   ai_runs
  WHERE  id = v_job.related_run_id
  FOR    UPDATE;

  IF v_run IS NULL THEN
    RAISE EXCEPTION 'Run % (related to batch %) not found',
                    v_job.related_run_id, p_batch_job_id USING ERRCODE = '22023';
  END IF;

  -- Idempotency: if the run is no longer waiting_batch, treat as already-
  -- resumed (someone won the race or operator cancelled). Return success
  -- so the caller knows not to re-trigger runWorkflow.
  IF v_run.status != 'waiting_batch' THEN
    v_already_resumed := true;
  END IF;

  v_tokens_input  := COALESCE((p_result ->> 'tokens_input')::int, 0);
  v_tokens_output := COALESCE((p_result ->> 'tokens_output')::int, 0);
  v_text          := COALESCE(p_result ->> 'text', '');

  IF NOT v_already_resumed THEN
    -- Merge batch_result + last_generation into checkpoint.state. Use jsonb
    -- path UPDATE to preserve all other state keys (clow_backend, etc.).
    v_new_metadata := v_run.metadata;
    v_new_metadata := jsonb_set(
      v_new_metadata,
      '{checkpoint,state,batch_result}',
      p_result,
      true
    );
    v_new_metadata := jsonb_set(
      v_new_metadata,
      '{checkpoint,state,last_generation}',
      to_jsonb(v_text),
      true
    );

    UPDATE ai_runs
    SET    status            = 'running',
           metadata          = v_new_metadata,
           cost_total_json   = jsonb_set(
             COALESCE(cost_total_json, '{}'::jsonb),
             '{tokens_input}',
             to_jsonb(COALESCE((cost_total_json ->> 'tokens_input')::int, 0) + v_tokens_input)
           ) || jsonb_build_object(
             'tokens_output',
             COALESCE((cost_total_json ->> 'tokens_output')::int, 0) + v_tokens_output
           )
    WHERE  id = v_run.id;
  END IF;

  -- Audit always (even if already_resumed — operator can see retry attempts)
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'batch.resumed',
    jsonb_build_object(
      'batch_job_id',     p_batch_job_id,
      'run_id',           v_run.id,
      'provider',         v_job.provider,
      'external_batch_id', v_job.external_batch_id,
      'tokens_input',     v_tokens_input,
      'tokens_output',    v_tokens_output,
      'already_resumed',  v_already_resumed
    )
  );

  RETURN jsonb_build_object(
    'run_id',          v_run.id,
    'batch_job_id',    p_batch_job_id,
    'already_resumed', v_already_resumed,
    'new_status',      CASE WHEN v_already_resumed THEN v_run.status ELSE 'running' END,
    'tokens_input',    v_tokens_input,
    'tokens_output',   v_tokens_output
  );
END;
$$;

REVOKE ALL ON FUNCTION public.persist_batch_result_and_resume(uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.persist_batch_result_and_resume(uuid, jsonb) TO service_role;

COMMENT ON FUNCTION public.persist_batch_result_and_resume(uuid, jsonb) IS
  'WF_BATCH_RESUMER persistence RPC — merges batch result into ai_runs.checkpoint.state and flips status waiting_batch → running. Idempotent: no-op success if run not in waiting_batch. Service-role only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/plugin_capability_allowed.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: plugin_capability_allowed
-- Popis: Smí plugin v tomto okamžiku použít danou schopnost? JEDINÉ místo, kde
--        se to rozhoduje — ptá se ho zápis rozvrhu (reconcile), zabrání
--        splatného rozvrhu (claim) i host před během (/execute, zapálení).
--
-- ⛔ PROČ VZNIKÁ. Naměřeno 2026-09-24 v produkci RIQ: `granted_capabilities`
-- zdroje dat (instanční data, např. Webdispečink bez `cron.poll_positions` —
-- rozhodnutí majitele „polohy ne") NEČETL NIKDO: ani host, ani shim, ani runner,
-- ani jediná SQL funkce. Plugin si v init() naplánuje, co chce, a po zapálení
-- rozvrhů by stahoval polohy à 5 min proti výslovnému rozhodnutí. Deklarace,
-- kterou nic nevynucuje, je jen komentář.
--
-- PRAVIDLO:
--   · Plugin NENAPOJENÝ na zdroj dat (agent, uzel, provider…) se tu neomezuje —
--     jeho schopnosti řídí manifest a přepis tenanta jako dosud.
--   · Plugin napojený na zdroj (agent_knowledge_sources.source_plugin_id) smí
--     jen schopnost, kterou AKTIVNÍ zdroj výslovně povolil v
--     `config.granted_capabilities`. Chybějící seznam = nic povoleno (default
--     deny): zdroj bez rozhodnutí o rozsahu nesmí stahovat „všechno".
--   · Vypnutý zdroj nesmí nic — vypnutí má zastavit stahování hned, ne až po
--     dalším zápisu rozvrhů.
--
-- Bezpečnost: SECURITY DEFINER (čte konfiguraci zdroje, na kterou volající
-- nemusí mít právo), jen služba. Neprozrazuje nic kromě ano/ne.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.plugin_capability_allowed(
  p_plugin_id  uuid,
  p_capability text
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT CASE
    WHEN p_plugin_id IS NULL OR p_capability IS NULL OR btrim(p_capability) = '' THEN false
    WHEN NOT EXISTS (SELECT 1 FROM public.agent_knowledge_sources s
                      WHERE s.source_plugin_id = p_plugin_id) THEN true
    ELSE EXISTS (
      SELECT 1
        FROM public.agent_knowledge_sources s
       WHERE s.source_plugin_id = p_plugin_id
         AND s.is_active
         AND jsonb_typeof(s.config->'granted_capabilities') = 'array'
         AND (s.config->'granted_capabilities') ? p_capability)
  END;
$$;

COMMENT ON FUNCTION public.plugin_capability_allowed(uuid, text) IS
  'Smí plugin použít schopnost? Nenapojený na zdroj: ano (řídí manifest). Napojený: jen pokud AKTIVNÍ zdroj ji má v config.granted_capabilities (chybějící seznam = nic). Jen služba.';

REVOKE ALL ON FUNCTION public.plugin_capability_allowed(uuid, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.plugin_capability_allowed(uuid, text) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.plugin_capability_allowed(uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/claim_due_plugin_schedules.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- claim_due_plugin_schedules(p_limit, p_lease_seconds)
--
-- Plánovač v svc-plugin-system si ATOMICKY zabere splatné rozvrhy (SKIP LOCKED)
-- a odloží je o pronájem, takže ani víc replik téhož hostu nespustí týž rozvrh
-- dvakrát. Po běhu host zapíše skutečný příští termín (set_plugin_schedule_next_run);
-- když host mezitím spadne, pronájem vyprší a rozvrh se zabere znovu.
--
-- Spouští se jen rozvrh pluginu v provozu (canary/ga) a tenanta, který si plugin
-- nevypnul (plugin_tenant_overrides.enabled) — tatáž pravidla jako katalog.
-- A jen schopnost, kterou zdroj dat pluginu povolil a který je zapnutý
-- (plugin_capability_allowed) — rozhoduje se při každém zabrání, ne jednou.
-- Vzor převzat z claim_queued_claude_run (svc-agent-runner poller).
-- =============================================================================
CREATE OR REPLACE FUNCTION public.claim_due_plugin_schedules(
  p_limit         integer DEFAULT 10,
  p_lease_seconds integer DEFAULT 900
)
RETURNS TABLE (
  schedule_id        uuid,
  plugin_slug        text,
  tenant_id          uuid,
  handler_capability text,
  cron_expr          text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'claim_due_plugin_schedules: jen služba (svc-plugin-system)' USING ERRCODE = '42501';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_lease_seconds IS NULL OR p_lease_seconds < 30 THEN
    RAISE EXCEPTION 'claim_due_plugin_schedules: limit >= 1 a pronájem >= 30 s';
  END IF;

  RETURN QUERY
  WITH splatne AS (
    SELECT s.id
      FROM public.plugin_schedules s
      JOIN public.plugin_catalog pc ON pc.id = s.plugin_id
      LEFT JOIN public.plugin_tenant_overrides pto
        ON pto.plugin_id = s.plugin_id AND pto.tenant_id = s.tenant_id
     WHERE s.enabled
       AND pc.status IN ('canary', 'ga')
       AND (pto.id IS NULL OR pto.enabled)
       -- Zdroj dat rozhoduje v okamžiku BĚHU, ne jen při zápisu rozvrhu:
       -- vypnutí zdroje nebo odebrání povolení zastaví i rozvrh zapsaný dřív.
       AND public.plugin_capability_allowed(s.plugin_id, s.handler_capability)
       AND s.next_run_at IS NOT NULL
       AND s.next_run_at <= now()
     ORDER BY s.next_run_at
     LIMIT p_limit
       FOR UPDATE OF s SKIP LOCKED
  )
  UPDATE public.plugin_schedules ps
     SET last_run_at = now(),
         next_run_at = now() + make_interval(secs => p_lease_seconds),
         updated_at  = now()
    FROM splatne, public.plugin_catalog pc
   WHERE ps.id = splatne.id
     AND pc.id = ps.plugin_id
  RETURNING ps.id, pc.slug, ps.tenant_id, ps.handler_capability, ps.cron_expr;
END;
$$;

COMMENT ON FUNCTION public.claim_due_plugin_schedules(integer, integer) IS
  'Atomicky zabere splatné rozvrhy pluginů (SKIP LOCKED) a odloží je o pronájem. Jen služba.';

REVOKE ALL ON FUNCTION public.claim_due_plugin_schedules(integer, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.claim_due_plugin_schedules(integer, integer) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_due_plugin_schedules(integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/plugin_kv_delete.sql
-- -----------------------------------------------------------------------------

-- Function: public.plugin_kv_delete
-- Per-plugin key/value DELETE for the plugin sandbox broker. Removes the key from
-- the shared plugin_kv store under the fixed broker partition (nil tenant
-- sentinel), resolving the plugin slug to plugin_catalog.id. Mirrors
-- sandbox_kv_op 'delete'.
-- Security: SECURITY DEFINER (service_role-invoked via rpcService), search_path pinned.

CREATE OR REPLACE FUNCTION public.plugin_kv_delete(
  p_key text,
  p_plugin text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_broker_tenant constant uuid := '00000000-0000-0000-0000-000000000000';
  v_plugin_id uuid;
BEGIN
  IF p_plugin IS NULL OR p_key IS NULL THEN
    RAISE EXCEPTION 'plugin and key are required' USING ERRCODE = 'check_violation';
  END IF;

  SELECT id INTO v_plugin_id FROM public.plugin_catalog WHERE slug = p_plugin;
  IF v_plugin_id IS NULL THEN
    RAISE EXCEPTION 'Unknown plugin slug: %', p_plugin USING ERRCODE = 'no_data_found';
  END IF;

  DELETE FROM public.plugin_kv
  WHERE plugin_id = v_plugin_id
    AND tenant_id = v_broker_tenant
    AND key = p_key;
END;
$function$;

COMMENT ON FUNCTION public.plugin_kv_delete(text, text) IS
  'Per-plugin (slug-keyed) sandbox KV delete for the plugin broker.';

REVOKE ALL ON FUNCTION public.plugin_kv_delete(text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.plugin_kv_delete(text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/plugin_kv_get.sql
-- -----------------------------------------------------------------------------

-- Function: public.plugin_kv_get
-- Per-plugin key/value READ for the plugin sandbox broker (svc-plugin-system
-- routes/broker.ts + sandbox.ts). The broker identifies the plugin by SLUG
-- (broker token source_ref), tenant-agnostic — distinct from sandbox_kv_op which
-- is tenant-scoped. Resolves the slug to plugin_catalog.id and reads the row from
-- the shared plugin_kv store under a fixed broker partition (nil tenant sentinel).
-- Returns 'null'::jsonb when the key is absent.
-- Security: SECURITY DEFINER (service_role-invoked via rpcService), search_path pinned.

CREATE OR REPLACE FUNCTION public.plugin_kv_get(
  p_key text,
  p_plugin text
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  -- Broker KV is per-plugin (not per-tenant); park it under a fixed sentinel
  -- tenant so the (plugin_id, tenant_id, key) unique key still holds.
  v_broker_tenant constant uuid := '00000000-0000-0000-0000-000000000000';
  v_plugin_id uuid;
  v_result jsonb;
BEGIN
  IF p_plugin IS NULL OR p_key IS NULL THEN
    RAISE EXCEPTION 'plugin and key are required' USING ERRCODE = 'check_violation';
  END IF;

  SELECT id INTO v_plugin_id FROM public.plugin_catalog WHERE slug = p_plugin;
  IF v_plugin_id IS NULL THEN
    RAISE EXCEPTION 'Unknown plugin slug: %', p_plugin USING ERRCODE = 'no_data_found';
  END IF;

  SELECT value INTO v_result
  FROM public.plugin_kv
  WHERE plugin_id = v_plugin_id
    AND tenant_id = v_broker_tenant
    AND key = p_key;

  RETURN COALESCE(v_result, 'null'::jsonb);
END;
$function$;

COMMENT ON FUNCTION public.plugin_kv_get(text, text) IS
  'Per-plugin (slug-keyed) sandbox KV read for the plugin broker. Returns null jsonb when absent.';

REVOKE ALL ON FUNCTION public.plugin_kv_get(text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.plugin_kv_get(text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/plugin_kv_set.sql
-- -----------------------------------------------------------------------------

-- Function: public.plugin_kv_set
-- Per-plugin key/value WRITE for the plugin sandbox broker. Upserts into the
-- shared plugin_kv store under the fixed broker partition (nil tenant sentinel),
-- resolving the plugin slug to plugin_catalog.id. Mirrors sandbox_kv_op 'set'.
-- Security: SECURITY DEFINER (service_role-invoked via rpcService), search_path pinned.

CREATE OR REPLACE FUNCTION public.plugin_kv_set(
  p_key text,
  p_plugin text,
  p_value jsonb DEFAULT '{}'::jsonb
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_broker_tenant constant uuid := '00000000-0000-0000-0000-000000000000';
  v_plugin_id uuid;
BEGIN
  IF p_plugin IS NULL OR p_key IS NULL THEN
    RAISE EXCEPTION 'plugin and key are required' USING ERRCODE = 'check_violation';
  END IF;

  SELECT id INTO v_plugin_id FROM public.plugin_catalog WHERE slug = p_plugin;
  IF v_plugin_id IS NULL THEN
    RAISE EXCEPTION 'Unknown plugin slug: %', p_plugin USING ERRCODE = 'no_data_found';
  END IF;

  INSERT INTO public.plugin_kv (plugin_id, tenant_id, key, value)
  VALUES (v_plugin_id, v_broker_tenant, p_key, COALESCE(p_value, '{}'::jsonb))
  ON CONFLICT (plugin_id, tenant_id, key) DO UPDATE
    SET value = EXCLUDED.value, updated_at = now();
END;
$function$;

COMMENT ON FUNCTION public.plugin_kv_set(text, text, jsonb) IS
  'Per-plugin (slug-keyed) sandbox KV upsert for the plugin broker.';

REVOKE ALL ON FUNCTION public.plugin_kv_set(text, text, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.plugin_kv_set(text, text, jsonb) TO service_role;


