-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/process_feedback_to_training.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- Function: process_feedback_to_training
-- Purpose: Convert AI feedback into training examples (SFT/DPO)
-- Part of: AISHA Learning Engine (ALE) — Phase 1 (Feedback→Training pipeline)
-- Called by: n8n workflow or admin dashboard
--
-- Oprava 2026-09-28 (SELF_IMPROVEMENT_LOOP.md §3, K-02) — naměřeno na main 9087ef3df:
--   oba INSERTy dávaly `input = NULL` do `input text NOT NULL DEFAULT ''` a DPO řádek
--   nevyplnil `output` (NOT NULL). První vhodná zpětná vazba tak shodila CELOU dávku
--   (transakce se vrátí, nic se neoznačí jako zpracované) a každý další běh padl znovu:
--   z opravy uživatele nikdy nevznikl trénovací pár. Teď `input = ''` (prázdný kontext,
--   jak ho deklaruje tabulka) a u DPO `output = chosen` (dobrá odpověď je výstupem i pro SFT).
--   Příklady vznikají NEVALIDOVANÉ (is_validated = false) — export bere jen validované,
--   takže syrový obsah konverzace se touhle opravou do tréninku nedostane (filtr hodnot
--   a validace jsou SELF_IMPROVEMENT_LOOP.md §5.5 / §6.5).
-- =============================================================================

CREATE OR REPLACE FUNCTION public.process_feedback_to_training(
  p_dataset_id uuid,
  p_feedback_ids uuid[] DEFAULT NULL,
  p_limit integer DEFAULT 100,
  p_min_rating smallint DEFAULT 4,
  p_org_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid;
  v_is_service_role boolean := false;
  v_sft_count integer := 0;
  v_dpo_count integer := 0;
  v_skipped_count integer := 0;
  rec record;
  v_user_msg text;
  v_assistant_msg text;
BEGIN
  -- Auth check: admin/staff or service_role
  v_user_id := auth.uid();
  v_is_service_role := COALESCE(
    (current_setting('request.jwt.claims', true)::jsonb ->> 'role') = 'service_role',
    false
  );

  IF NOT v_is_service_role AND (v_user_id IS NULL OR NOT public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Permission denied: admin or staff required';
  END IF;

  -- Validate dataset exists
  IF NOT EXISTS (SELECT 1 FROM public.training_datasets WHERE id = p_dataset_id) THEN
    RAISE EXCEPTION 'Dataset not found: %', p_dataset_id;
  END IF;

  -- Process unprocessed feedback
  FOR rec IN
    SELECT
      af.id AS feedback_id,
      af.message_id,
      af.conversation_id,
      af.rating,
      af.correction_text,
      af.feedback_category,
      af.domain_tags,
      af.story_id,
      cm.content AS assistant_content,
      cm.model_used,
      cm.routing_category
    FROM public.ai_feedback af
    LEFT JOIN public.chat_messages cm ON cm.id = af.message_id
    WHERE af.is_processed = false
      AND (p_feedback_ids IS NULL OR af.id = ANY(p_feedback_ids))
      AND (p_org_id IS NULL OR af.org_id = p_org_id)
      AND (
        af.rating >= p_min_rating
        OR (af.correction_text IS NOT NULL AND length(trim(af.correction_text)) > 10)
      )
    ORDER BY af.created_at ASC
    LIMIT p_limit
  LOOP
    -- Get corresponding user message (previous message in conversation)
    SELECT cm.content INTO v_user_msg
    FROM public.chat_messages cm
    WHERE cm.conversation_id = rec.conversation_id
      AND cm.role = 'user'
      AND cm.created_at < (
        SELECT created_at FROM public.chat_messages WHERE id = rec.message_id
      )
    ORDER BY cm.created_at DESC
    LIMIT 1;

    v_assistant_msg := rec.assistant_content;

    -- Skip if we can't reconstruct the pair
    IF v_user_msg IS NULL OR v_assistant_msg IS NULL THEN
      v_skipped_count := v_skipped_count + 1;
      UPDATE public.ai_feedback SET is_processed = true, processed_at = now()
      WHERE id = rec.feedback_id;
      CONTINUE;
    END IF;

    -- Skip duplicates
    IF EXISTS (
      SELECT 1 FROM public.training_examples
      WHERE dataset_id = p_dataset_id
        AND source_id = rec.feedback_id
        AND source_type = 'ai_feedback'
    ) THEN
      v_skipped_count := v_skipped_count + 1;
      UPDATE public.ai_feedback SET is_processed = true, processed_at = now()
      WHERE id = rec.feedback_id;
      CONTINUE;
    END IF;

    -- Case A: Has correction → DPO preference pair (chosen=correction, rejected=original)
    IF rec.correction_text IS NOT NULL AND length(trim(rec.correction_text)) > 10 THEN
      INSERT INTO public.training_examples (
        dataset_id, example_type, instruction, input, output,
        chosen, rejected,
        source_id, source_type, domain_tags, quality_score
      ) VALUES (
        p_dataset_id,
        'preference_pair',
        v_user_msg,
        '',
        rec.correction_text,
        rec.correction_text,
        v_assistant_msg,
        rec.feedback_id,
        'ai_feedback',
        rec.domain_tags,
        GREATEST(COALESCE(rec.rating, 0)::numeric, 1::numeric) / 5.0
      );
      v_dpo_count := v_dpo_count + 1;

    -- Case B: High rating without correction → SFT instruction pair
    ELSE
      INSERT INTO public.training_examples (
        dataset_id, example_type, instruction, input, output,
        source_id, source_type, domain_tags, quality_score
      ) VALUES (
        p_dataset_id,
        'instruction',
        v_user_msg,
        '',
        v_assistant_msg,
        rec.feedback_id,
        'ai_feedback',
        rec.domain_tags,
        rec.rating::numeric / 5.0
      );
      v_sft_count := v_sft_count + 1;
    END IF;

    -- Mark feedback as processed
    UPDATE public.ai_feedback SET is_processed = true, processed_at = now()
    WHERE id = rec.feedback_id;
  END LOOP;

  -- Update dataset stats
  UPDATE public.training_datasets
  SET record_count = (
    SELECT count(*) FROM public.training_examples WHERE dataset_id = p_dataset_id
  )
  WHERE id = p_dataset_id;

  -- Audit journal
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'TRAINING_DATA_PROCESSED',
    jsonb_build_object(
      'dataset_id', p_dataset_id,
      'sft_pairs', v_sft_count,
      'dpo_pairs', v_dpo_count,
      'skipped', v_skipped_count
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'sft_pairs', v_sft_count,
    'dpo_pairs', v_dpo_count,
    'skipped', v_skipped_count,
    'total_processed', v_sft_count + v_dpo_count
  );
END;
$$;

REVOKE ALL ON FUNCTION public.process_feedback_to_training(uuid, uuid[], integer, smallint, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.process_feedback_to_training(uuid, uuid[], integer, smallint, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.process_feedback_to_training(uuid, uuid[], integer, smallint, uuid) TO service_role;

COMMENT ON FUNCTION public.process_feedback_to_training(uuid, uuid[], integer, smallint, uuid) IS
  'Convert AI feedback into training examples (SFT/DPO). Called by n8n workflow or admin. Rate 4+ → SFT, corrections → DPO preference pairs even for low-rated responses.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/process_token_reward.sql
-- -----------------------------------------------------------------------------

-- Function: public.process_token_reward
-- Arguments: p_user_id uuid, p_action_type text, p_reference_id uuid
-- Description: Awards the configured token_reward_rules payout for an action the CALLER performed.
--   Self-service by design (useProcessReward passes the session user's own id), so p_user_id is
--   pinned to auth.uid() rather than revoked.
-- Security: SECURITY DEFINER with search_path + auth.uid() ownership guard.
--   2026-07-15 IDOR fix (docs/security/IDOR_P_USER_ID_AUDIT_2026-07-15.md): granted to
--   `authenticated` and accepted ANY p_user_id with no authorization, so a logged-in user could
--   POST /rest/v1/rpc/process_token_reward with a victim's uuid and burn their once-per-action
--   reward eligibility (can_receive_reward cooldown) — the victim then permanently loses a payout
--   they never received. This is the mirror image of award_tokens: here the caller legitimately
--   awards THEMSELVES, so pinning p_user_id to auth.uid() is the correct fix and the grant stays.
-- KNOWN CRITICAL GAP — unlimited self-mint, NOT closed by the fix above (tracked, fix in flight):
--   p_action_type/p_reference_id are never verified against a real action. A user may claim a
--   reward for something they never did — and, contrary to a first reading, this is NOT bounded:
--   every limit in can_receive_reward is `IF v_rule.<limit> IS NOT NULL THEN ... END IF`, so a rule
--   with cooldown_hours/daily_limit/weekly_limit/monthly_limit all NULL skips EVERY check and
--   returns can_receive=true unconditionally. 8 of the 12 seeded rules are exactly that shape,
--   including study_completion at 100 tokens and placebo_compensation at 50 — repeatable in a loop.
--   The ONLY reason this is not exploitable today is an accident: all 12 seeded rules carry
--   token_type='PLATFORM' (aisha/db/seed/core/06_subscriptions.sql), and award_tokens raises on
--   any token_type outside ('governance','impact','data','aisha'). The reward feature is therefore
--   DEAD, and its deadness is the security control. DO NOT "fix" the token_type without landing the
--   evidence contract first — that single edit silently arms an unlimited mint.
--   The pin above is still necessary and orthogonal: it stops a user burning a VICTIM's eligibility.
--   Fixing the mint needs a per-action evidence contract (see the audit doc).
-- @audit: none (token operations logged in token_transactions table)

CREATE OR REPLACE FUNCTION public.process_token_reward(p_user_id uuid, p_action_type text, p_reference_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule record;
  v_can_receive jsonb;
  v_amount integer;
  v_result jsonb;
BEGIN
  -- AUTHORIZATION FIRST — before any rule read or ledger write. A user may only process their
  -- OWN rewards; service_role (trusted backend) and admin/staff may act for anyone.
  -- is_service_role() is the NULL-safe reader — the inline request.jwt.claims idiom folds to
  -- NULL when the role claim is absent and would make this deny-guard fail OPEN.
  -- `auth.uid() IS NULL` is part of the deny condition on purpose: without it a NULL uid and a
  -- NULL p_user_id are NOT DISTINCT, so an unauthenticated caller would slip through the guard.
  IF NOT public.is_service_role()
     AND NOT public.is_admin_or_staff()
     AND (auth.uid() IS NULL OR p_user_id IS DISTINCT FROM auth.uid())
  THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  -- Get all active rules for this action type
  FOR v_rule IN
    SELECT
      token_type,
      base_amount,
      multiplier,
      min_amount,
      max_amount,
      action_name_key,
      action_type
    FROM token_reward_rules
    WHERE action_type = p_action_type AND is_active = true
  LOOP
    -- Check if user can receive this reward
    v_can_receive := can_receive_reward(p_user_id, p_action_type, v_rule.token_type);
    
    IF (v_can_receive->>'can_receive')::boolean THEN
      -- Calculate amount
      v_amount := FLOOR(v_rule.base_amount * v_rule.multiplier);
      
      -- Apply min/max constraints
      IF v_rule.min_amount IS NOT NULL AND v_amount < v_rule.min_amount THEN
        v_amount := v_rule.min_amount;
      END IF;
      IF v_rule.max_amount IS NOT NULL AND v_amount > v_rule.max_amount THEN
        v_amount := v_rule.max_amount;
      END IF;
      
      -- Award the tokens
      v_result := award_tokens(
        p_user_id,
        v_rule.token_type,
        v_amount,
        p_action_type,
        p_reference_id,
        COALESCE(
          public.get_translation_value_with_fallback(v_rule.action_name_key, 'rewards', 'en', 'en', NULL),
          v_rule.action_type
        )
      );
    END IF;
  END LOOP;

  RETURN COALESCE(v_result, jsonb_build_object('success', false, 'reason', 'No rewards processed'));
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.process_token_reward(p_user_id uuid, p_action_type text, p_reference_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.process_token_reward(p_user_id uuid, p_action_type text, p_reference_id uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/promote_entry_to_story_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.promote_entry_to_story_audited
-- Recursive story tree: promotes a single story_entry into the root of its OWN
-- child story. "Every record in a story can become the beginning of its own
-- story; at the top level the context is everything." The child inherits the
-- parent's partner/user/study context. The parent→child relationship is recorded
-- three ways, one per consumer:
--   1. story_links ('extends', forward)        — member-visible hot-path hierarchy
--                                                 (story-scoped RLS, NOT admin-only)
--   2. graph_edges (PART_OF + DERIVED_FROM)     — graph/context rollup; feeds the
--                                                 compose_context `graph_context` layer
--   3. source story_entries.metadata.promoted_to_story_id — timeline branch marker
--
-- The parent Story graph node is resolved by source_id (slug-convention-agnostic)
-- so we never duplicate the bootstrap-seeded node.
--
-- Security: SECURITY DEFINER. Caller must own / participate in the parent story
-- (partner owner, member owner, participant, admin/staff) or be service_role.
-- @audit: required

CREATE OR REPLACE FUNCTION public.promote_entry_to_story_audited(
  p_entry_id uuid,
  p_title    text DEFAULT NULL::text,
  p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_is_service  boolean := current_setting('role', true) = 'service_role';
  v_user_id     uuid := auth.uid();
  v_partner_id  uuid;
  v_parent      public.partner_stories%ROWTYPE;
  v_entry       public.story_entries%ROWTYPE;
  v_title       text;
  v_child_id    uuid;
  v_parent_node uuid;
  v_child_node  uuid;
BEGIN
  IF v_user_id IS NULL AND NOT v_is_service THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  -- Resolve the entry and its parent story.
  SELECT * INTO v_entry FROM public.story_entries WHERE id = p_entry_id;
  IF v_entry.id IS NULL THEN
    RAISE EXCEPTION 'Story entry not found: %', p_entry_id USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_parent FROM public.partner_stories WHERE id = v_entry.story_id;
  IF v_parent.id IS NULL THEN
    RAISE EXCEPTION 'Parent story not found for entry %', p_entry_id USING ERRCODE = '22023';
  END IF;

  -- Authorization: service role, partner owner, member owner, participant, or admin/staff.
  v_partner_id := public.get_current_partner_id();
  IF NOT (
        v_is_service
     OR (v_partner_id IS NOT NULL AND v_partner_id = v_parent.partner_id)
     OR (v_user_id IS NOT NULL AND v_user_id = v_parent.user_id)
     OR (v_user_id IS NOT NULL AND public.is_story_participant(v_user_id, v_parent.id))
     OR (v_user_id IS NOT NULL AND public.is_admin_or_staff(v_user_id))
  ) THEN
    RAISE EXCEPTION 'Unauthorized: cannot promote entry from this story' USING ERRCODE = '42501';
  END IF;

  v_title := COALESCE(
    NULLIF(TRIM(p_title), ''),
    NULLIF(TRIM(LEFT(v_entry.content, 80)), ''),
    'Odbočka ' || to_char(now(), 'YYYY-MM-DD')
  );

  -- (1) Child story, inheriting the parent's context. origin marks the provenance;
  -- status falls back to the table default ('inbox') so it surfaces for triage.
  INSERT INTO public.partner_stories (partner_id, user_id, study_id, title, origin)
  VALUES (v_parent.partner_id, v_parent.user_id, v_parent.study_id, v_title, 'promoted_entry')
  RETURNING id INTO v_child_id;

  -- (2) Mark the source entry so the timeline shows the branch point.
  UPDATE public.story_entries
     SET metadata = COALESCE(metadata, '{}'::jsonb)
                 || jsonb_build_object('promoted_to_story_id', v_child_id,
                                       'promoted_at', now())
   WHERE id = p_entry_id;

  -- (3) Hot-path hierarchy edge (member-visible): parent --extends--> child.
  INSERT INTO public.story_links
    (source_story_id, target_story_id, link_type, link_direction,
     created_by, confidence_score, is_accepted, metadata)
  VALUES
    (v_parent.id, v_child_id, 'extends', 'forward',
     v_user_id, 1.0, true,
     COALESCE(p_metadata, '{}'::jsonb)
       || jsonb_build_object('relation', 'promoted_from_entry',
                             'source_entry_id', p_entry_id))
  ON CONFLICT (source_story_id, target_story_id, link_type) DO NOTHING;

  -- (4) Graph rollup edges (feed compose_context graph_context layer). Resolve the
  -- parent Story node by source_id (slug-agnostic); upsert one only if absent.
  SELECT id INTO v_parent_node
    FROM public.graph_nodes
   WHERE source_table = 'partner_stories' AND source_id = v_parent.id
   LIMIT 1;
  IF v_parent_node IS NULL THEN
    v_parent_node := public.fn_upsert_graph_node_audited(
      'Story', v_parent.id::text, v_parent.title,
      'partner_stories', v_parent.id, v_parent.id, '{}'::jsonb);
  END IF;

  v_child_node := public.fn_upsert_graph_node_audited(
    'Story', v_child_id::text, v_title,
    'partner_stories', v_child_id, v_child_id,
    jsonb_build_object('origin', 'promoted_entry', 'promoted_from_entry_id', p_entry_id));

  PERFORM public.fn_upsert_graph_edge_audited(
    v_child_node, v_parent_node, 'PART_OF', 1.0, NULL, NULL,
    jsonb_build_object('via', 'promote_entry_to_story'));
  PERFORM public.fn_upsert_graph_edge_audited(
    v_child_node, v_parent_node, 'DERIVED_FROM', 1.0, NULL, NULL,
    jsonb_build_object('source_entry_id', p_entry_id));

  -- (5) Decision-provenance audit.
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_user_id, 'STORY_PROMOTED_FROM_ENTRY',
    jsonb_build_object(
      'area', 'collaboration',
      'severity', 'notice',
      'parent_story_id', v_parent.id,
      'child_story_id', v_child_id,
      'source_entry_id', p_entry_id));

  RETURN jsonb_build_object(
    'child_story_id', v_child_id,
    'parent_story_id', v_parent.id,
    'source_entry_id', p_entry_id,
    'title', v_title
  );
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.promote_entry_to_story_audited(uuid, text, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.promote_entry_to_story_audited(uuid, text, jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.promote_entry_to_story_audited(uuid, text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.promote_entry_to_story_audited(uuid, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/propose_tooling_artifact.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: propose_tooling_artifact
-- Popis: Insert new AISHA-generated skill/hook/command proposal. Idempotent na
--        (proposal_kind, artifact_path) — pokud existuje pending nebo committed
--        proposal pro stejnou cestu, raises. Manual_locked artifacts cannot be
--        overwritten (admin "lidský dotek" gate).
-- Volá: WF_AISHA_TOOLING_OBSERVER po pattern detection + factory rendering
-- Auth: service_role nebo admin/staff
-- ============================================================================

CREATE OR REPLACE FUNCTION public.propose_tooling_artifact(
  p_kind                text,
  p_name                text,
  p_path                text,
  p_content             text,
  p_trigger_pattern     jsonb,
  p_occurrence_count    int,
  p_decision_provenance jsonb DEFAULT '[]'::jsonb,
  p_proposal_bundle_id  uuid DEFAULT NULL,
  p_metadata            jsonb DEFAULT '{}'::jsonb
)
RETURNS public.aisha_tooling_proposals
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_existing public.aisha_tooling_proposals;
  v_row      public.aisha_tooling_proposals;
  v_is_service boolean;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '22023';
  END IF;

  IF p_kind NOT IN ('skill', 'hook', 'command') THEN
    RAISE EXCEPTION 'Invalid kind: % (must be skill, hook, command)', p_kind USING ERRCODE = '22023';
  END IF;

  IF length(p_content) < 100 THEN
    RAISE EXCEPTION 'Artifact content too short (min 100 chars)' USING ERRCODE = '22023';
  END IF;

  -- Check for existing proposal at same path
  SELECT * INTO v_existing
  FROM public.aisha_tooling_proposals
  WHERE proposal_kind = p_kind AND artifact_path = p_path;

  IF v_existing IS NOT NULL THEN
    -- Allow overwrite only if:
    -- 1. Not manual_locked AND
    -- 2. Previous status was rejected/expired/reverted (allow re-proposal)
    IF v_existing.manual_locked THEN
      RAISE EXCEPTION 'Path % is manual-locked; AISHA cannot overwrite', p_path USING ERRCODE = '22023';
    END IF;

    IF v_existing.approval_status IN ('pending', 'approved', 'committed') THEN
      RAISE EXCEPTION 'Active proposal already exists for %: status=%',
        p_path, v_existing.approval_status USING ERRCODE = '22023';
    END IF;

    -- Update for re-proposal
    UPDATE public.aisha_tooling_proposals
    SET artifact_content = p_content,
        artifact_name = p_name,
        trigger_pattern = p_trigger_pattern,
        occurrence_count = p_occurrence_count,
        decision_provenance = p_decision_provenance,
        proposal_bundle_id = p_proposal_bundle_id,
        metadata = p_metadata,
        approval_status = 'pending',
        approval_id = NULL,
        approved_by = NULL,
        approved_at = NULL,
        committed_sha = NULL,
        committed_at = NULL,
        reverted_sha = NULL,
        reverted_at = NULL,
        proposed_at = now(),
        updated_at = now()
    WHERE id = v_existing.id
    RETURNING * INTO v_row;
  ELSE
    -- New proposal
    INSERT INTO public.aisha_tooling_proposals (
      proposal_kind, artifact_name, artifact_path, artifact_content,
      trigger_pattern, occurrence_count, decision_provenance,
      proposal_bundle_id, metadata
    )
    VALUES (
      p_kind, p_name, p_path, p_content,
      p_trigger_pattern, p_occurrence_count, p_decision_provenance,
      p_proposal_bundle_id, p_metadata
    )
    RETURNING * INTO v_row;
  END IF;

  -- Audit
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'aisha_tooling_proposed',
    jsonb_build_object(
      'proposal_id', v_row.id,
      'kind', p_kind,
      'path', p_path,
      'occurrence_count', p_occurrence_count
    )
  );

  RETURN v_row;
END;
$$;

REVOKE ALL ON FUNCTION public.propose_tooling_artifact(text, text, text, text, jsonb, int, jsonb, uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.propose_tooling_artifact(text, text, text, text, jsonb, int, jsonb, uuid, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.propose_tooling_artifact(text, text, text, text, jsonb, int, jsonb, uuid, jsonb) TO service_role;


