-- -----------------------------------------------------------------------------

-- Function: public.protect_system_roles
-- Arguments: (none)
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:27:59+01:00

CREATE OR REPLACE FUNCTION public.protect_system_roles()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.is_system = true AND NEW.is_system = false THEN
    RAISE EXCEPTION 'Cannot remove system role protection' USING ERRCODE = 'P0001';
  END IF;
  IF OLD.is_system = true AND OLD.is_admin != NEW.is_admin THEN
    RAISE EXCEPTION 'Cannot change admin status of system roles' USING ERRCODE = 'P0001';
  END IF;
  IF OLD.is_system = true AND OLD.name != NEW.name THEN
    RAISE EXCEPTION 'Cannot rename system roles' USING ERRCODE = 'P0001';
  END IF;
  NEW.updated_at = now();
  NEW.updated_by = auth.uid();
  RETURN NEW;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.protect_system_roles() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.protect_system_roles() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/publish_agent.sql
-- -----------------------------------------------------------------------------

-- Function: public.publish_agent
-- Arguments: p_plugin_id uuid
-- Returns: jsonb (status + queue_id + message)
-- Security: SECURITY DEFINER
-- Description: Submits a kind='agent' plugin for moderation review. Mirrors
--   publish_expert_rule: the agent transitions to 'reviewing' status and enters
--   the polymorphic knowledge_moderation_queue (resource_type='agent',
--   resource_id = plugin_catalog.id). AISHA evaluates via the WF_KB_COMPLIANCE_GATE
--   webhook (best-effort), then service_role calls fn_aisha_kb_decision to
--   approve (→ canary) / reject (→ submitted). Until then a human admin can decide
--   via review_moderation_item.
--
--   Difference vs publish_expert_rule (intentional, safer for executable content):
--   if the n8n webhook is unconfigured or fails, the item stays PENDING for human
--   review — it is never auto-approved. We never call fn_aisha_kb_decision with the
--   invalid 'pending_review' decision (a latent bug in publish_expert_rule).

CREATE OR REPLACE FUNCTION public.publish_agent(p_plugin_id uuid)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id   uuid;
  v_is_admin    boolean;
  v_partner_id  uuid;
  v_plugin      record;
  v_queue_id    uuid;
  v_existing    uuid;
  v_risk_tags   text[];
  v_webhook_url text;
  v_request_id  bigint;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_is_admin := public.is_admin_or_staff();

  SELECT pc.id, pc.slug, pc.name, pc.description, pc.kind, pc.status,
         pc.capabilities, pc.author_partner_id
    INTO v_plugin
    FROM public.plugin_catalog pc
   WHERE pc.id = p_plugin_id;

  IF v_plugin.id IS NULL THEN
    RAISE EXCEPTION 'Agent not found: %', p_plugin_id;
  END IF;

  IF v_plugin.kind <> 'agent' THEN
    RAISE EXCEPTION 'Plugin % is not an agent (kind=%)', p_plugin_id, v_plugin.kind;
  END IF;

  -- Ownership: the authoring certified partner, or admin/staff.
  IF NOT v_is_admin THEN
    SELECT id INTO v_partner_id
      FROM public.partner_profiles
     WHERE user_id = v_caller_id;
    IF v_partner_id IS NULL OR v_plugin.author_partner_id IS DISTINCT FROM v_partner_id THEN
      RAISE EXCEPTION 'Only the authoring partner or admin/staff can publish this agent';
    END IF;
  END IF;

  -- Idempotency: if a review is already pending, return it (checked BEFORE the
  -- publishable-state gate, because a pending agent is already in 'reviewing').
  SELECT id INTO v_existing
    FROM public.knowledge_moderation_queue
   WHERE resource_type = 'agent'
     AND resource_id = p_plugin_id
     AND status = 'pending'
   LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object(
      'status', 'review',
      'queue_id', v_existing,
      'message', 'Agent already pending review'
    );
  END IF;

  -- Publishable only from a pre-review state.
  IF v_plugin.status NOT IN ('submitted'::public.plugin_status) THEN
    RAISE EXCEPTION 'Agent % is not in a publishable state (status=%)', p_plugin_id, v_plugin.status;
  END IF;

  -- Transition to 'reviewing' — decision will flip to canary/submitted.
  UPDATE public.plugin_catalog
     SET status = 'reviewing'::public.plugin_status, updated_at = now()
   WHERE id = p_plugin_id;

  -- Risk tags derived from declared capabilities (for the compliance evaluator).
  v_risk_tags := ARRAY(
    SELECT jsonb_array_elements_text(COALESCE(v_plugin.capabilities, '[]'::jsonb))
  );

  -- Enter the polymorphic moderation queue.
  INSERT INTO public.knowledge_moderation_queue
    (resource_type, resource_id, status, risk_tags)
  VALUES
    ('agent', p_plugin_id, 'pending', v_risk_tags)
  RETURNING id INTO v_queue_id;

  -- Audit
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_caller_id, 'AGENT_PUBLISH_REQUESTED', jsonb_build_object(
    'area', 'marketplace',
    'severity', 'info',
    'plugin_id', p_plugin_id,
    'queue_id', v_queue_id,
    'slug', v_plugin.slug
  ));

  -- Fire AISHA compliance webhook (best-effort). Unlike publish_expert_rule we
  -- do NOT auto-approve when n8n is absent — agents stay pending for human review.
  BEGIN
    v_webhook_url := current_setting('app.settings.n8n_webhook_base_url', true);
    IF v_webhook_url IS NOT NULL AND v_webhook_url <> '' THEN
      SELECT net.http_post(
        url     := v_webhook_url || '/webhook/kb-compliance-gate',
        body    := jsonb_build_object(
          'queue_id', v_queue_id,
          'resource_type', 'agent',
          'plugin_id', p_plugin_id,
          'slug', v_plugin.slug,
          'name', v_plugin.name,
          'description', v_plugin.description,
          'capabilities', COALESCE(v_plugin.capabilities, '[]'::jsonb),
          'requester_id', v_caller_id,
          'action', 'publish_agent'
        ),
        headers := '{"Content-Type": "application/json"}'::jsonb
      ) INTO v_request_id;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- pg_net unavailable / webhook post failed → leave PENDING for human review.
    INSERT INTO public.audit_journal (user_id, action, metadata)
    VALUES (v_caller_id, 'AGENT_APPROVAL_ESCALATED', jsonb_build_object(
      'area', 'marketplace',
      'severity', 'warning',
      'plugin_id', p_plugin_id,
      'queue_id', v_queue_id,
      'reason', 'AISHA evaluation unavailable — awaiting manual review',
      'error', SQLERRM
    ));
  END;

  RETURN jsonb_build_object(
    'status', 'review',
    'queue_id', v_queue_id,
    'message', 'Submitted for compliance review'
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.publish_agent(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.publish_agent(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.publish_agent(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/publish_expert_rule.sql
-- -----------------------------------------------------------------------------

-- Function: public.publish_expert_rule
-- Arguments: p_rule_id uuid
-- Returns: jsonb  (status + queue_id + message)
-- Security: SECURITY DEFINER
-- Description: Submits an expert rule for AISHA compliance review instead of
--   directly publishing. The rule transitions to 'review' status and enters
--   the knowledge_moderation_queue. AISHA evaluates via n8n webhook
--   (WF_KB_COMPLIANCE_GATE), then calls fn_aisha_kb_decision to approve/reject.
--   Fallback: auto-approves if AISHA is unavailable.

CREATE OR REPLACE FUNCTION public.publish_expert_rule(p_rule_id uuid)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id   uuid;
  v_rule        record;
  v_queue_id    uuid;
  v_webhook_url text;
  v_request_id  bigint;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Must be owner and in publishable state
  SELECT er.id, er.title, er.summary, er.body_markdown,
         er.category::text AS category, er.ai_context_tags, er.slug
    INTO v_rule
    FROM expert_rules er
    JOIN partner_profiles pp ON pp.id = er.author_partner_id
   WHERE er.id = p_rule_id
     AND pp.user_id = v_caller_id
     AND er.status IN ('draft', 'review');

  IF v_rule IS NULL THEN
    RAISE EXCEPTION 'Rule not found, not owned, or not in publishable state';
  END IF;

  -- Transition to 'review' — AISHA will decide
  UPDATE expert_rules
     SET status = 'review', updated_at = now()
   WHERE id = p_rule_id;

  -- Create moderation queue entry
  INSERT INTO knowledge_moderation_queue
    (resource_type, resource_id, status, risk_tags)
  VALUES
    ('expert_rule', p_rule_id, 'pending', v_rule.ai_context_tags)
  RETURNING id INTO v_queue_id;

  -- Audit
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (v_caller_id, 'EXPERT_RULE_PUBLISH_REQUESTED', jsonb_build_object(
    'area', 'knowledge',
    'severity', 'info',
    'rule_id', p_rule_id,
    'queue_id', v_queue_id,
    'title', v_rule.title
  ));

  -- Fire n8n webhook for AISHA evaluation (best-effort)
  BEGIN
    v_webhook_url := current_setting('app.settings.n8n_webhook_base_url', true);
    IF v_webhook_url IS NOT NULL AND v_webhook_url != '' THEN
      SELECT net.http_post(
        url     := v_webhook_url || '/webhook/kb-compliance-gate',
        body    := jsonb_build_object(
          'queue_id', v_queue_id,
          'rule_id', p_rule_id,
          'slug', v_rule.slug,
          'title', v_rule.title,
          'summary', v_rule.summary,
          'category', v_rule.category,
          'body_preview', left(v_rule.body_markdown, 1000),
          'ai_context_tags', to_jsonb(COALESCE(v_rule.ai_context_tags, ARRAY[]::text[])),
          'requester_id', v_caller_id,
          'action', 'publish'
        ),
        headers := '{"Content-Type": "application/json"}'::jsonb
      ) INTO v_request_id;
    ELSE
      -- n8n not configured → auto-approve
      PERFORM fn_aisha_kb_decision(
        p_queue_id := v_queue_id,
        p_decision := 'approved',
        p_evaluation := jsonb_build_object(
          'auto', true,
          'reason', 'n8n webhook not configured, auto-approved'
        )
      );
      RETURN jsonb_build_object(
        'status', 'published',
        'queue_id', v_queue_id,
        'message', 'Auto-approved (AISHA not available)'
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- pg_net unavailable or webhook failed → leave the queue row PENDING for human
    -- review (NEVER auto-approve on failure). The rule already sits at 'review' and
    -- the queue row was inserted as 'pending' above — both are outside this inner
    -- BEGIN block, so they survive the subtransaction rollback. We must NOT call
    -- fn_aisha_kb_decision here: 'pending_review' is not a valid decision (it
    -- validates approved|rejected|escalated), so the call RAISEd inside this handler
    -- and aborted the whole publish (rule + queue lost). And 'escalated' would flip
    -- the queue to 'escalated', which review_moderation_item rejects (it requires
    -- 'pending'). Mirror publish_agent: just audit and return — the item stays
    -- reviewable by an admin via review_moderation_item.
    INSERT INTO audit_journal(user_id, action, metadata)
    VALUES (
      v_caller_id,
      'RULE_APPROVAL_ESCALATED',
      jsonb_build_object(
        'severity', 'critical',
        'queue_id', v_queue_id,
        'rule_id', p_rule_id,
        'reason', 'AISHA evaluation unavailable — awaiting manual review',
        'error', SQLERRM
      )
    );
    RETURN jsonb_build_object(
      'status', 'pending_review',
      'queue_id', v_queue_id,
      'message', 'AISHA evaluation unavailable — awaiting manual review'
    );
  END;

  RETURN jsonb_build_object(
    'status', 'review',
    'queue_id', v_queue_id,
    'message', 'Submitted for AISHA compliance review'
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.publish_expert_rule(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.publish_expert_rule(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.publish_expert_rule(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/publish_surface_snapshot_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: publish_surface_snapshot_audited
-- Popis: Emit podepsaného read-only snímku surface (Ed25519). SERVICE-ROLE-ONLY
--        přes NULL-safe public.is_service_role() (#588) — fail-closed: bez jwt
--        claims / s cizí rolí končí výjimkou. Parita audited-write posture s
--        upsert_surface_block_audited (emise snímku nesmí jít mimo audit).
-- Podpis: Ed25519 vzniká v emitující SLUŽBĚ (privátní klíč jen v jejím env); DB
--         ukládá sha256/signature/key_id a NIKDY neověřuje (asymetrie — klient
--         ověřuje pinovaným public klíčem). max_sensitivity je v surface_snapshots
--         CHECK zastropováno na 'restricted' (confidential se do snímku nedostane).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.publish_surface_snapshot_audited(
  p_snapshot_slug   text,
  p_surface         text,
  p_payload         jsonb,
  p_max_sensitivity text,
  p_sha256          text,
  p_signature       text,
  p_key_id          text,
  p_expires_at      timestamptz
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id uuid;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'service role required' USING errcode = '42501';
  END IF;

  -- max_sensitivity nad 'restricted' je zamítnuto surface_snapshots CHECK
  -- (fail-closed na zápisu); INSERT propadne s jasnou chybou, žádné tiché stripování.
  INSERT INTO public.surface_snapshots AS ss
    (snapshot_slug, surface, payload, max_sensitivity, sha256, signature, key_id, expires_at)
  VALUES
    (p_snapshot_slug, p_surface, p_payload, p_max_sensitivity, p_sha256, p_signature, p_key_id, p_expires_at)
  RETURNING ss.id INTO v_id;

  -- Audit — platformní vzor (přímý INSERT do audit_journal, aditivně, hash-chain #585);
  -- tvar sloupců dle upsert_surface_block_audited (ověřeno proti HEAD).
  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (auth.uid(), 'surface.snapshot_published', 'surface.snapshot_published', 'content', 'info',
          array['surface', 'snapshot'],
          jsonb_build_object('snapshot_slug', p_snapshot_slug, 'surface', p_surface,
                             'max_sensitivity', p_max_sensitivity, 'sha256', p_sha256, 'key_id', p_key_id));

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.publish_surface_snapshot_audited(text,text,jsonb,text,text,text,text,timestamptz) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.publish_surface_snapshot_audited(text,text,jsonb,text,text,text,text,timestamptz) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/publish_web_artifact.sql
-- -----------------------------------------------------------------------------

-- publish_web_artifact
-- Flip applied page status to 'published'. Job must already be in 'applied' state.
-- Appends a story_entries row (entry_type=web_artifact_published).
-- Authz: admin/staff or story participant.

CREATE OR REPLACE FUNCTION public.publish_web_artifact(p_job_id uuid)
RETURNS text
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_job record;
  v_slug text;
BEGIN
  SELECT id, status, story_id, applied_to_page_id INTO v_job
  FROM public.web_artifact_jobs
  WHERE id = p_job_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found: %', p_job_id;
  END IF;

  IF v_job.status <> 'applied' THEN
    RAISE EXCEPTION 'Job must be applied (got %)', v_job.status;
  END IF;

  IF v_job.applied_to_page_id IS NULL THEN
    RAISE EXCEPTION 'Job has no applied page reference';
  END IF;

  IF NOT public.is_admin_or_staff()
     AND (v_job.story_id IS NULL OR NOT public.is_story_participant(auth.uid(), v_job.story_id))
  THEN
    RAISE EXCEPTION 'Unauthorized: admin/staff or story participant required';
  END IF;

  UPDATE public.web_pages
  SET status = 'published', updated_at = now()
  WHERE id = v_job.applied_to_page_id
  RETURNING slug INTO v_slug;

  IF v_job.story_id IS NOT NULL THEN
    INSERT INTO public.story_entries (story_id, entry_type, content, metadata, created_by)
    VALUES (
      v_job.story_id,
      'web_artifact_published',
      NULL,
      jsonb_build_object(
        'type', 'web_artifact_published',
        'job_id', p_job_id,
        'page_id', v_job.applied_to_page_id,
        'slug', v_slug
      ),
      auth.uid()
    );
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'WEB_ARTIFACT_PUBLISH',
    jsonb_build_object(
      'area', 'content',
      'severity', 'info',
      'entity_type', 'web_artifact_job',
      'entity_id', p_job_id::text,
      'page_id', v_job.applied_to_page_id::text,
      'slug', v_slug,
      'tags', ARRAY['stack', 'story', 'web_artifact', 'publish']
    )
  );

  RETURN v_slug;
END;
$$;

REVOKE ALL ON FUNCTION public.publish_web_artifact(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.publish_web_artifact(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/purchase_product_voucher.sql
-- -----------------------------------------------------------------------------

-- Function: public.purchase_product_voucher
-- Deducts tokens from wallet and creates an active voucher for a product.

CREATE OR REPLACE FUNCTION public.purchase_product_voucher(
  p_product_id uuid,
  p_point_cost int4,
  p_token_type text
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_current_balance numeric := 0;
  v_voucher_id uuid;
  v_voucher_code text;
  v_attempt int4;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_product_id IS NULL THEN
    RAISE EXCEPTION 'Product is required' USING ERRCODE = '22023';
  END IF;

  IF p_point_cost IS NULL OR p_point_cost <= 0 THEN
    RAISE EXCEPTION 'Point cost must be greater than zero' USING ERRCODE = '22023';
  END IF;

  IF p_token_type NOT IN ('governance', 'impact', 'data') THEN
    RAISE EXCEPTION 'Invalid token type' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.products WHERE id = p_product_id) THEN
    RAISE EXCEPTION 'Product not found' USING ERRCODE = 'P0001';
  END IF;

  -- Lock wallet row for consistent balance check.
  SELECT
    CASE
      WHEN p_token_type = 'governance' THEN governance_tokens
      WHEN p_token_type = 'impact' THEN impact_tokens
      WHEN p_token_type = 'data' THEN data_tokens
      ELSE 0
    END
  INTO v_current_balance
  FROM public.user_wallets
  WHERE user_id = v_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.user_wallets (
      user_id,
      governance_tokens,
      impact_tokens,
      data_tokens,
      created_at,
      updated_at
    )
    SELECT
      v_user_id,
      COALESCE(SUM(CASE WHEN token_type = 'governance' THEN amount ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN token_type = 'impact' THEN amount ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN token_type = 'data' THEN amount ELSE 0 END), 0),
      now(),
      now()
    FROM public.token_transactions
    WHERE user_id = v_user_id
    ON CONFLICT (user_id) DO NOTHING;

    SELECT
      CASE
        WHEN p_token_type = 'governance' THEN governance_tokens
        WHEN p_token_type = 'impact' THEN impact_tokens
        WHEN p_token_type = 'data' THEN data_tokens
        ELSE 0
      END
    INTO v_current_balance
    FROM public.user_wallets
    WHERE user_id = v_user_id
    FOR UPDATE;
  END IF;

  v_current_balance := COALESCE(v_current_balance, 0);

  IF v_current_balance < p_point_cost THEN
    RAISE EXCEPTION 'Insufficient % tokens', p_token_type USING ERRCODE = 'P0001';
  END IF;

  FOR v_attempt IN 1..10 LOOP
    v_voucher_code := upper(substring(md5(gen_random_uuid()::text || clock_timestamp()::text) FROM 1 FOR 8));

    BEGIN
      INSERT INTO public.product_vouchers (
        code,
        product_id,
        user_id,
        status,
        points_cost,
        expires_at
      )
      VALUES (
        v_voucher_code,
        p_product_id,
        v_user_id,
        'active',
        p_point_cost,
        now() + interval '1 year'
      )
      RETURNING id INTO v_voucher_id;

      EXIT;
    EXCEPTION
      WHEN unique_violation THEN
        -- Retry with a new generated code.
        NULL;
    END;
  END LOOP;

  IF v_voucher_id IS NULL THEN
    RAISE EXCEPTION 'Failed to generate voucher code' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.token_transactions (
    user_id,
    amount,
    token_type,
    transaction_type,
    description,
    reference_id
  )
  VALUES (
    v_user_id,
    -p_point_cost,
    p_token_type,
    'spent',
    'Purchased voucher ' || v_voucher_code,
    v_voucher_id
  );

  RETURN v_voucher_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.purchase_product_voucher(uuid, int4, text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.purchase_product_voucher(uuid, int4, text) FROM anon;
GRANT EXECUTE ON FUNCTION public.purchase_product_voucher(uuid, int4, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/rate_expert_rule.sql
-- -----------------------------------------------------------------------------

-- Function: public.rate_expert_rule
-- Arguments: p_rule_id uuid, p_rating integer, p_review_text text DEFAULT NULL::text
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.rate_expert_rule(p_rule_id uuid, p_rating integer, p_review_text text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id uuid;
  v_new_avg numeric;
  v_new_count int;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_rating < 1 OR p_rating > 5 THEN
    RAISE EXCEPTION 'Rating must be between 1 and 5';
  END IF;

  -- Must be subscribed
  PERFORM 1 FROM expert_rule_subscriptions
  WHERE user_id = v_caller_id AND rule_id = p_rule_id AND is_active = true;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'You must subscribe to a rule before rating it';
  END IF;

  INSERT INTO expert_rule_ratings (rule_id, user_id, rating, review_text)
  VALUES (p_rule_id, v_caller_id, p_rating, p_review_text)
  ON CONFLICT (rule_id, user_id) DO UPDATE SET
    rating = EXCLUDED.rating,
    review_text = EXCLUDED.review_text,
    updated_at = now();

  -- Recalculate averages
  SELECT avg(rating)::numeric(3,2), count(*) INTO v_new_avg, v_new_count
  FROM expert_rule_ratings WHERE rule_id = p_rule_id;

  UPDATE expert_rules SET rating_avg = v_new_avg, rating_count = v_new_count
  WHERE id = p_rule_id;

  RETURN true;
END;
$function$;

REVOKE ALL ON FUNCTION public.rate_expert_rule(uuid, integer, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rate_expert_rule(uuid, integer, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rate_expert_rule(uuid, integer, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/rate_specialist_audited.sql
-- -----------------------------------------------------------------------------

-- Function: rate_specialist_audited
-- Purpose: Client rates specialist after booking completion

CREATE OR REPLACE FUNCTION rate_specialist_audited(
  p_booking_id uuid,
  p_rating_overall int,
  p_rating_communication int DEFAULT NULL,
  p_rating_expertise int DEFAULT NULL,
  p_rating_delivery int DEFAULT NULL,
  p_comment text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid;
  v_booking RECORD;
  v_rating_id uuid;
  v_avg_rating numeric;
  v_total_count int;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Validate rating range
  IF p_rating_overall < 1 OR p_rating_overall > 5 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Rating must be 1-5');
  END IF;

  -- Get booking and verify ownership
  SELECT cb.*
  INTO v_booking
  FROM consultation_bookings cb
  WHERE cb.id = p_booking_id;

  IF v_booking IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Booking not found');
  END IF;

  IF v_booking.member_id != v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not your booking');
  END IF;

  IF v_booking.status != 'completed' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Booking not yet completed');
  END IF;

  -- Check if already rated
  IF EXISTS (
    SELECT 1 FROM specialist_ratings
    WHERE booking_id = p_booking_id AND rater_id = v_user_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Already rated');
  END IF;

  -- Create rating
  INSERT INTO specialist_ratings (
    rated_specialist_id, rater_id, booking_id, story_id,
    overall_rating, communication_rating, expertise_rating, value_rating,
    review_text
  ) VALUES (
    v_booking.specialist_id, v_user_id, p_booking_id, v_booking.story_id,
    p_rating_overall,
    COALESCE(p_rating_communication, p_rating_overall),
    COALESCE(p_rating_expertise, p_rating_overall),
    COALESCE(p_rating_delivery, p_rating_overall),
    p_comment
  )
  RETURNING id INTO v_rating_id;

  -- Update specialist avg_rating
  SELECT AVG(overall_rating), COUNT(*)
  INTO v_avg_rating, v_total_count
  FROM specialist_ratings
  WHERE rated_specialist_id = v_booking.specialist_id;

  UPDATE partner_profiles
  SET avg_rating = ROUND(v_avg_rating, 2),
      total_ratings_count = v_total_count
  WHERE id = v_booking.specialist_id;

  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'SPECIALIST_RATED',
    jsonb_build_object(
      'area', 'marketplace',
      'severity', 'info',
      'entity_type', 'specialist_rating',
      'entity_id', v_rating_id,
      'specialist_id', v_booking.specialist_id,
      'rating_overall', p_rating_overall
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'rating_id', v_rating_id,
    'new_avg_rating', v_avg_rating
  );
END;
$$;

REVOKE ALL ON FUNCTION rate_specialist_audited(uuid,int,int,int,int,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION rate_specialist_audited(uuid,int,int,int,int,text) TO authenticated;
GRANT EXECUTE ON FUNCTION rate_specialist_audited(uuid,int,int,int,int,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/rate_topic_translation.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.rate_topic_translation(
  p_topic_version_id uuid,
  p_locale text,
  p_quality_score numeric
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = 'P0001';
  END IF;

  IF p_quality_score < 0 OR p_quality_score > 1 THEN
    RAISE EXCEPTION 'quality_score must be between 0 and 1' USING ERRCODE = 'P0002';
  END IF;

  UPDATE knowledge_topic_translations
  SET quality_score = p_quality_score,
      is_human_reviewed = true
  WHERE topic_version_id = p_topic_version_id
    AND locale = p_locale;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Translation not found' USING ERRCODE = 'P0003';
  END IF;

  -- Log to audit journal
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'TRANSLATION_RATED',
    jsonb_build_object(
      'area', 'knowledge',
      'severity', 'info',
      'topic_version_id', p_topic_version_id,
      'locale', p_locale,
      'quality_score', p_quality_score
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION public.rate_topic_translation(uuid, text, numeric) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rate_topic_translation(uuid, text, numeric) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/raw_query_admin.sql
-- -----------------------------------------------------------------------------

-- raw_query_admin: Execute parameterized SQL from edge functions (admin only)
-- Called by: github-webhook-bridge/index.ts for upsert operations
-- SECURITY: service_role only — this is a powerful function, restrict carefully
CREATE OR REPLACE FUNCTION public.raw_query_admin(
  p_sql text,
  p_params text[] DEFAULT '{}'::text[]
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  -- Only service_role can call this (enforced by GRANT)
  EXECUTE p_sql USING
    p_params[1], p_params[2], p_params[3], p_params[4], p_params[5],
    p_params[6], p_params[7], p_params[8], p_params[9], p_params[10];
END;
$$;

REVOKE ALL ON FUNCTION public.raw_query_admin(text, text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.raw_query_admin(text, text[]) TO service_role;

COMMENT ON FUNCTION public.raw_query_admin(text, text[]) IS
  'Execute parameterized SQL from edge functions. RESTRICTED to service_role. Used by github-webhook-bridge for dynamic upserts.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/recalculate_all_ruleset_fingerprints.sql
-- -----------------------------------------------------------------------------

-- Function: recalculate_all_ruleset_fingerprints

CREATE OR REPLACE FUNCTION public.recalculate_all_ruleset_fingerprints()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total_affected integer := 0;
  v_ruleset RECORD;
  v_new_fingerprint text;
  v_run_id uuid;
BEGIN
  FOR v_ruleset IN
    SELECT id, rule_ids FROM story_rulesets
  LOOP
    SELECT md5(string_agg(
      er.slug || ':' || er.version::text || ':' || COALESCE(er.ai_instructions, ''),
      '|' ORDER BY er.slug
    ))
    INTO v_new_fingerprint
    FROM expert_rules er
    WHERE er.id = ANY(v_ruleset.rule_ids)
      AND er.status = 'published';

    UPDATE story_rulesets
    SET ruleset_fingerprint = COALESCE(v_new_fingerprint, 'empty')
    WHERE id = v_ruleset.id
      AND ruleset_fingerprint IS DISTINCT FROM COALESCE(v_new_fingerprint, 'empty');

    IF FOUND THEN
      v_total_affected := v_total_affected + 1;
    END IF;
  END LOOP;

  -- Log the batch operation
  v_run_id := gen_random_uuid();
  -- §16: platform/system run → platform sentinel story (ai_runs.story_id NOT NULL).
  INSERT INTO ai_runs (id, story_id, kind, status, started_at, finished_at, cost_total_json, metadata)
  VALUES (
    v_run_id,
    public.ensure_stack_default_story(),
    'proactive',
    'succeeded',
    now(),
    now(),
    '{"usd": 0}'::jsonb,
    jsonb_build_object('rulesets_affected', v_total_affected)
  );

  INSERT INTO ai_trace_events (
    run_id, event_type, agent_slug, operation, status,
    request_summary, created_at
  ) VALUES (
    v_run_id, 'proactive_trigger', 'dirigent',
    'batch_fingerprint_recalculation', 'ok',
    jsonb_build_object('rulesets_affected', v_total_affected), now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'rulesets_recalculated', v_total_affected
  );
END;
$function$;

REVOKE ALL ON FUNCTION recalculate_all_ruleset_fingerprints() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION recalculate_all_ruleset_fingerprints() TO authenticated;
GRANT EXECUTE ON FUNCTION recalculate_all_ruleset_fingerprints() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/recalculate_distribution_forecasts_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.recalculate_distribution_forecasts_admin
-- Arguments: p_month date, p_study_id uuid
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:27:59+01:00

CREATE OR REPLACE FUNCTION public.recalculate_distribution_forecasts_admin(p_month date DEFAULT NULL::date, p_study_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target_month date;
  v_rec RECORD;
  v_total_members integer;
  v_vip_members integer;
  v_daily_dose_ml numeric;
  v_monthly_consumption numeric;
  v_deviation_percent numeric;
  v_deviation_sample integer;
  v_adjusted_consumption numeric;
  v_required_packages numeric;
  v_product_price numeric;
  v_compensated_value numeric;
  v_package_size_ml numeric := 30.0; -- Standard 30ml bottle
  v_drops_to_ml numeric := 0.05; -- 1 drop ≈ 0.05ml (20 drops per ml)
BEGIN
  -- Authorization check
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: Admin or staff access required';
  END IF;

  -- Default to current month if not specified
  v_target_month := COALESCE(p_month, date_trunc('month', CURRENT_DATE)::date);

  -- Iterate over all active study+product combinations from distribution_protocols
  FOR v_rec IN
    SELECT DISTINCT
      dp.study_id,
      dp.product_id,
      dp.dose_amount,
      dp.dose_unit,
      dp.doses_per_day,
      s.parent_study_id,
      p.price
    FROM distribution_protocols dp
    JOIN studies s ON s.id = dp.study_id
    JOIN products p ON p.id = dp.product_id
    WHERE dp.is_active = true
      AND s.is_active = true
      AND (p_study_id IS NULL OR dp.study_id = p_study_id)
  LOOP
    -- 1. Count total active members in this study
    SELECT COUNT(DISTINCT se.user_id)
    INTO v_total_members
    FROM study_registrations se
    WHERE se.study_id = v_rec.study_id
      AND se.status = 'active';

    -- 2. Count VIP members (those in child studies - where study has parent_study_id)
    IF v_rec.parent_study_id IS NOT NULL THEN
      -- This IS a child study, so all its members are VIP
      v_vip_members := v_total_members;
    ELSE
      -- This is umbrella study, VIP are those who are ALSO in child studies
      SELECT COUNT(DISTINCT se_child.user_id)
      INTO v_vip_members
      FROM study_registrations se_umbrella
      JOIN study_registrations se_child ON se_child.user_id = se_umbrella.user_id
      JOIN studies s_child ON s_child.id = se_child.study_id AND s_child.parent_study_id = v_rec.study_id
      WHERE se_umbrella.study_id = v_rec.study_id
        AND se_umbrella.status = 'active'
        AND se_child.status = 'active';
    END IF;

    -- 3. Calculate default daily dose in ml
    IF v_rec.dose_unit = 'drops' THEN
      v_daily_dose_ml := v_rec.dose_amount * v_rec.doses_per_day * v_drops_to_ml;
    ELSIF v_rec.dose_unit = 'ml' THEN
      v_daily_dose_ml := v_rec.dose_amount * v_rec.doses_per_day;
    ELSE
      -- Default assumption for unknown units
      v_daily_dose_ml := v_rec.dose_amount * v_rec.doses_per_day * v_drops_to_ml;
    END IF;

    -- 4. Calculate monthly consumption (all members × daily dose × 30 days)
    v_monthly_consumption := v_total_members * v_daily_dose_ml * 30;

    -- 5. Calculate deviation from dosing_logs (last 3 months)
    -- Deviation = AVG(actual_dose / expected_dose) - 1
    -- Positive = over-consumption, Negative = under-consumption
    SELECT 
      COALESCE(
        AVG(
          CASE 
            WHEN dl.dose_count IS NOT NULL AND v_rec.doses_per_day > 0 THEN
              (dl.dose_count::numeric / v_rec.doses_per_day::numeric) - 1
            WHEN dl.dose_amount IS NOT NULL AND v_rec.dose_amount > 0 THEN
              (CAST(dl.dose_amount AS numeric) / v_rec.dose_amount) - 1
            ELSE 0
          END
        ) * 100, -- Convert to percentage
        0
      ),
      COUNT(dl.id)
    INTO v_deviation_percent, v_deviation_sample
    FROM dosing_logs dl
    JOIN study_registrations se ON se.id = dl.study_registration_id
    WHERE se.study_id = v_rec.study_id
      AND dl.product_id = v_rec.product_id
      AND dl.logged_at >= (v_target_month - INTERVAL '3 months')
      AND dl.logged_at < v_target_month;

    -- 6. Adjust monthly consumption by deviation
    v_adjusted_consumption := v_monthly_consumption * (1 + (v_deviation_percent / 100));

    -- 7. Calculate required packages (ceil to whole bottles)
    IF v_package_size_ml > 0 THEN
      v_required_packages := CEIL(v_adjusted_consumption / v_package_size_ml);
    ELSE
      v_required_packages := 0;
    END IF;

    -- 8. Calculate compensated value (VIP members × product price)
    -- This represents the value of products delivered within the subscription
    v_product_price := COALESCE(v_rec.price, 0);
    v_compensated_value := v_vip_members * v_product_price;

    -- UPSERT the forecast item
    INSERT INTO distribution_forecast_items (
      forecast_month,
      study_id,
      product_id,
      total_members,
      vip_members,
      required_packages,
      compensated_value,
      reported_deviation_percent,
      deviation_sample_size,
      production_status,
      updated_at
    )
    VALUES (
      v_target_month,
      v_rec.study_id,
      v_rec.product_id,
      v_total_members,
      v_vip_members,
      v_required_packages,
      v_compensated_value,
      v_deviation_percent,
      v_deviation_sample,
      'planning',
      now()
    )
    ON CONFLICT (forecast_month, study_id, product_id)
    DO UPDATE SET
      total_members = EXCLUDED.total_members,
      vip_members = EXCLUDED.vip_members,
      required_packages = EXCLUDED.required_packages,
      compensated_value = EXCLUDED.compensated_value,
      reported_deviation_percent = EXCLUDED.reported_deviation_percent,
      deviation_sample_size = EXCLUDED.deviation_sample_size,
      updated_at = now();

  END LOOP;

  -- Audit log
  INSERT INTO audit_journal (action, 
    action_type,
    area,
    entity_type,
    summary,
    user_id,
    details,
    severity
  ) VALUES ('RECALCULATE_DISTRIBUTION_FORECASTS_ADMIN', 
    'update',
    'production',
    'distribution_forecast_items',
    'Distribution forecast recalculated for ' || v_target_month::text,
    auth.uid(),
    jsonb_build_object(
      'month', v_target_month,
      'study_id', p_study_id,
      'calculation_method', 'full_with_deviations'
    ),
    'info'
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.recalculate_distribution_forecasts_admin(p_month date, p_study_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.recalculate_distribution_forecasts_admin(p_month date, p_study_id uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/receivable_from_param.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: receivable_from_param
-- Popis: OD KDY JE VYDANÁ FAKTURA POHLEDÁVKOU — parametr instance
--        `receivable_from` ze source_params bloku (issue_date |
--        taxable_supply_date | due_date). Rozhodnutí majitele 2026-09-25:
--        datum VYSTAVENÍ (faktura vystavená dopředu = „předepsáno", ne dluh);
--        bloky instance ho deklarují výslovně. Neznámá hodnota = chyba
--        konfigurace (22023), ne tichý jiný výklad. Volá se JEDNOU na dotaz
--        (cfg čtečky), výsledek jde do invoice_state.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.receivable_from_param(p_params jsonb)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v text := nullif(btrim(coalesce(p_params->>'receivable_from', '')), '');
BEGIN
  IF v IS NULL THEN
    RETURN 'issue_date';   -- rozhodnutí majitele 2026-09-25, ne odhad
  END IF;
  IF v NOT IN ('issue_date', 'taxable_supply_date', 'due_date') THEN
    RAISE EXCEPTION 'receivable_from=% není známé datum pohledávky (issue_date | taxable_supply_date | due_date)', v
      USING ERRCODE = '22023';
  END IF;
  RETURN v;
END;
$$;

REVOKE ALL ON FUNCTION public.receivable_from_param(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.receivable_from_param(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/recommend_ruleset_for_story.sql
-- -----------------------------------------------------------------------------

-- Function: recommend_ruleset_for_story
-- Purpose: Match story tech_stack/domain against expert_rules.ai_context_tags
-- Security: SECURITY DEFINER (admin/staff or story owner)
-- MCP tool: recommend_ruleset_for_story

CREATE OR REPLACE FUNCTION public.recommend_ruleset_for_story(
  p_story_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_tech_stack text[];
  v_domain text[];
  v_risk_profile text;
  v_result jsonb;
BEGIN
  -- Authorization: admin/staff or story owner
  IF NOT is_admin_or_staff() THEN
    IF NOT EXISTS (
      SELECT 1 FROM partner_stories
      WHERE id = p_story_id AND partner_id = auth.uid()
    ) THEN
      RAISE EXCEPTION 'Unauthorized: not story owner or admin/staff';
    END IF;
  END IF;

  -- Load story metadata
  SELECT tech_stack, domain, risk_profile
  INTO v_tech_stack, v_domain, v_risk_profile
  FROM partner_stories
  WHERE id = p_story_id;

  IF v_tech_stack IS NULL AND v_domain IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Story has no tech_stack or domain set. Run detect_project_context first.',
      'story_id', p_story_id
    );
  END IF;

  -- Combine tech_stack + domain for tag matching
  WITH story_tags AS (
    SELECT unnest(COALESCE(v_tech_stack, '{}') || COALESCE(v_domain, '{}')) AS tag
  ),
  rule_scores AS (
    SELECT
      er.id AS rule_id,
      er.slug,
      er.title,
      er.category::text AS category,
      er.ai_context_tags,
      (
        SELECT count(*)
        FROM unnest(er.ai_context_tags) rt
        JOIN story_tags st ON lower(rt) = lower(st.tag)
      ) AS tag_overlap,
      array_length(er.ai_context_tags, 1) AS total_tags,
      CASE WHEN 'aisha' = ANY(er.ai_context_tags) THEN 1 ELSE 0 END AS aisha_boost,
      CASE
        WHEN v_risk_profile = 'high' AND er.category = 'security_practice' THEN 2
        WHEN v_risk_profile = 'medium' AND er.category = 'security_practice' THEN 1
        ELSE 0
      END AS risk_boost
    FROM expert_rules er
    WHERE er.status = 'published'
      AND er.ai_context_tags IS NOT NULL
      AND array_length(er.ai_context_tags, 1) > 0
  ),
  ranked AS (
    SELECT
      rule_id, slug, title, category, ai_context_tags,
      tag_overlap, total_tags, aisha_boost, risk_boost,
      (tag_overlap + aisha_boost + risk_boost) AS total_score
    FROM rule_scores
    WHERE tag_overlap > 0 OR aisha_boost > 0
    ORDER BY total_score DESC, tag_overlap DESC, slug
  )
  SELECT jsonb_build_object(
    'success', true,
    'story_id', p_story_id,
    'tech_stack', v_tech_stack,
    'domain', v_domain,
    'risk_profile', v_risk_profile,
    'recommended_rule_ids', COALESCE((SELECT jsonb_agg(rule_id) FROM ranked), '[]'::jsonb),
    'match_details', COALESCE(
      (SELECT jsonb_agg(
        jsonb_build_object(
          'rule_id', rule_id,
          'slug', slug,
          'title', title,
          'category', category,
          'tag_overlap', tag_overlap,
          'aisha_boost', aisha_boost,
          'risk_boost', risk_boost,
          'total_score', total_score
        ) ORDER BY total_score DESC
      ) FROM ranked),
      '[]'::jsonb
    ),
    'total_recommended', (SELECT count(*) FROM ranked)
  ) INTO v_result;

  -- Audit
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'RULESET_RECOMMENDATION',
    jsonb_build_object(
      'area', 'ai',
      'severity', 'info',
      'story_id', p_story_id,
      'rules_recommended', (v_result->>'total_recommended')::int
    )
  );

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.recommend_ruleset_for_story(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.recommend_ruleset_for_story(uuid) TO authenticated;

COMMENT ON FUNCTION public.recommend_ruleset_for_story(uuid) IS
  'Recommends expert rules for a story based on tech_stack/domain tag overlap. '
  'Returns match details with scoring. Used by AISHA onboarding pipeline.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/recommend_slot_for_task.sql
-- -----------------------------------------------------------------------------

-- Function: recommend_slot_for_task
-- Soulforge: classify a task into a slot (spark/ember/verify/...) on the DB side.
-- Mirrors the TypeScript heuristic in services/svc-ai-chat/src/reflection/soulforge.ts.
-- Used by reflection nodes when local classifier confidence < 0.6 (e.g. ambiguous
-- task descriptions) and by n8n workflows that need a slot decision without
-- loading the TS lib.

CREATE OR REPLACE FUNCTION public.recommend_slot_for_task(
  p_message text,
  p_context jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_slot       text;
  v_confidence numeric;
  v_reason     text;
  v_len        int := length(COALESCE(p_message, ''));
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_message IS NULL OR p_message = '' THEN
    RETURN jsonb_build_object('slot', 'default', 'confidence', 0.0, 'reason', 'empty_input');
  END IF;

  -- Pattern matching mirrors the TS classifier order (specificity descending).
  -- Highest-confidence patterns win.
  -- Stems (summariz, analyz, evaluat, diagnos, condens, compar) deliberately
  -- lack trailing \y because the next char is usually a word char (e/i/ing).
  -- Whole verbs keep \y on both ends.
  IF p_message ~* '\y(summariz|condens|shorten|tldr)' THEN
    v_slot := 'compact';  v_confidence := 0.80; v_reason := 'pattern_compact';
  ELSIF p_message ~* '\y(read|explore|fetch|open|show|browse|load)\y' AND v_len < 400 THEN
    v_slot := 'spark';    v_confidence := 0.75; v_reason := 'pattern_spark_short';
  ELSIF p_message ~* '\y(write|edit|create|implement|fix|refactor|build|add)\y' THEN
    v_slot := 'ember';    v_confidence := 0.75; v_reason := 'pattern_ember';
  ELSIF p_message ~* '\y(review|test|check|verify|audit|validate)\y' THEN
    v_slot := 'verify';   v_confidence := 0.75; v_reason := 'pattern_verify';
  ELSIF p_message ~* '\y(clean|format|lint|tidy)\y' THEN
    v_slot := 'desloppify'; v_confidence := 0.70; v_reason := 'pattern_desloppify';
  ELSIF p_message ~* '\y(analyz|explain|compar|evaluat|diagnos)' THEN
    v_slot := 'semantic'; v_confidence := 0.65; v_reason := 'pattern_semantic';
  ELSIF p_message ~* '\y(search|google|lookup|web|find)\y' THEN
    v_slot := 'webSearch'; v_confidence := 0.60; v_reason := 'pattern_webSearch';
  ELSE
    v_slot := 'default';  v_confidence := 0.40; v_reason := 'no_pattern_matched';
  END IF;

  RETURN jsonb_build_object(
    'slot', v_slot,
    'confidence', v_confidence,
    'reason', v_reason,
    'message_length', v_len,
    'context_keys', (SELECT COALESCE(array_agg(k), '{}'::text[])
                     FROM jsonb_object_keys(p_context) AS k)
  );
END;
$$;

COMMENT ON FUNCTION public.recommend_slot_for_task(text, jsonb) IS
  'Soulforge: DB-side slot classifier (spark/ember/webSearch/desloppify/verify/'
  'compact/semantic/default). STABLE, regex-based, ~ms. TS classifier in '
  'svc-ai-chat/src/reflection/soulforge.ts is authoritative; this RPC is used '
  'when the TS lib is not in scope (n8n, edge fns, direct DB callers).';

REVOKE ALL ON FUNCTION public.recommend_slot_for_task(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.recommend_slot_for_task(text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.recommend_slot_for_task(text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/reconcile_plugin_schedules.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- reconcile_plugin_schedules(p_plugin_slug, p_tenant_id, p_declarations)
--
-- Zapíše rozvrhy, které plugin deklaroval v init() (ctx.schedule(cron, capability)),
-- pro jednoho tenanta — a VYPNE ty, které už nedeklaruje.
--
-- ⛔ NAMĚŘENO 2026-09-16: `plugin_schedules` nikdo neplnil ani nečetl;
-- `register_plugin_schedule` neměl volajícího a byl povolený KAŽDÉMU přihlášenému
-- bez kontroly nároku. Cron capability pluginů proto nikdy neběžely.
--
-- Jen služba (svc-plugin-system po úspěšném běhu pluginu). Deklarace se
-- VALIDUJÍ, nevěří se jim: capability musí být `cron.*` a v manifestu pluginu,
-- cron pět polí. Neplatné se nezapíšou a vrátí se v `odmitnuto` — host je nahlásí.
-- `next_run_at` spočítá host (parser cronu žije v Node, ne v SQL).
-- =============================================================================
CREATE OR REPLACE FUNCTION public.reconcile_plugin_schedules(
  p_plugin_slug  text,
  p_tenant_id    uuid,
  p_declarations jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_plugin   public.plugin_catalog%ROWTYPE;
  v_dekl     jsonb;
  v_cap      text;
  v_cron     text;
  v_next     timestamptz;
  v_platne   text[] := ARRAY[]::text[];
  v_odmitnuto jsonb := '[]'::jsonb;
  v_zapsano  int := 0;
  v_vypnuto  int := 0;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'reconcile_plugin_schedules: jen služba (svc-plugin-system)' USING ERRCODE = '42501';
  END IF;
  IF p_plugin_slug IS NULL OR p_tenant_id IS NULL THEN
    RAISE EXCEPTION 'reconcile_plugin_schedules: plugin_slug a tenant_id jsou povinné';
  END IF;
  IF p_declarations IS NULL OR jsonb_typeof(p_declarations) <> 'array' THEN
    RAISE EXCEPTION 'reconcile_plugin_schedules: deklarace musí být pole';
  END IF;

  SELECT * INTO v_plugin FROM public.plugin_catalog WHERE slug = p_plugin_slug;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reconcile_plugin_schedules: plugin % neexistuje', p_plugin_slug;
  END IF;

  FOR v_dekl IN SELECT * FROM jsonb_array_elements(p_declarations) LOOP
    v_cap  := v_dekl->>'capability';
    v_cron := btrim(COALESCE(v_dekl->>'cron', ''));
    IF v_cap IS NULL THEN
      v_odmitnuto := v_odmitnuto || jsonb_build_object('deklarace', v_dekl, 'duvod', 'chybí capability (starý tvar schedule(cron, fn))');
    ELSIF v_cap NOT LIKE 'cron.%' OR NOT (v_plugin.capabilities ? v_cap) THEN
      v_odmitnuto := v_odmitnuto || jsonb_build_object('deklarace', v_dekl, 'duvod', 'capability není cron.* z manifestu pluginu');
    ELSIF v_cron !~ '^\S+\s+\S+\s+\S+\s+\S+\s+\S+$' THEN
      v_odmitnuto := v_odmitnuto || jsonb_build_object('deklarace', v_dekl, 'duvod', 'cron nemá pět polí');
    ELSIF v_cap = ANY(v_platne) THEN
      v_odmitnuto := v_odmitnuto || jsonb_build_object('deklarace', v_dekl, 'duvod', 'capability deklarovaná dvakrát');
    -- Manifest říká, co plugin UMÍ; zdroj dat, co SMÍ (plugin_capability_allowed).
    -- Neudělená schopnost se nezapíše a už zapsaný rozvrh vypne UPDATE níž
    -- (není v v_platne) — odebrání povolení tak rozvrh zastaví i bez nového běhu.
    ELSIF NOT public.plugin_capability_allowed(v_plugin.id, v_cap) THEN
      v_odmitnuto := v_odmitnuto || jsonb_build_object('deklarace', v_dekl, 'duvod', 'neudělená schopnost (granted_capabilities zdroje) nebo vypnutý zdroj');
    ELSE
      BEGIN
        v_next := NULLIF(v_dekl->>'next_run_at', '')::timestamptz;
      EXCEPTION WHEN others THEN
        v_next := NULL;
      END;
      INSERT INTO public.plugin_schedules (plugin_id, tenant_id, cron_expr, handler_capability, enabled, next_run_at)
      VALUES (v_plugin.id, p_tenant_id, v_cron, v_cap, true, v_next)
      ON CONFLICT (plugin_id, tenant_id, handler_capability) DO UPDATE
        SET cron_expr   = EXCLUDED.cron_expr,
            enabled     = true,
            -- změněný cron = nový termín; stejný cron nechá běžící rozpis být
            next_run_at = CASE WHEN plugin_schedules.cron_expr IS DISTINCT FROM EXCLUDED.cron_expr
                                 OR plugin_schedules.next_run_at IS NULL
                               THEN EXCLUDED.next_run_at
                               ELSE plugin_schedules.next_run_at END,
            updated_at  = now();
      v_platne  := v_platne || v_cap;
      v_zapsano := v_zapsano + 1;
    END IF;
  END LOOP;

  UPDATE public.plugin_schedules
     SET enabled = false, updated_at = now()
   WHERE plugin_id = v_plugin.id
     AND tenant_id = p_tenant_id
     AND enabled
     AND NOT (handler_capability = ANY(v_platne));
  GET DIAGNOSTICS v_vypnuto = ROW_COUNT;

  RETURN jsonb_build_object('zapsano', v_zapsano, 'vypnuto', v_vypnuto, 'odmitnuto', v_odmitnuto);
END;
$$;

COMMENT ON FUNCTION public.reconcile_plugin_schedules(text, uuid, jsonb) IS
  'Zapíše rozvrhy deklarované pluginem v init() pro tenanta (validované proti manifestu) a vypne nedeklarované. Jen služba.';

REVOKE ALL ON FUNCTION public.reconcile_plugin_schedules(text, uuid, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.reconcile_plugin_schedules(text, uuid, jsonb) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.reconcile_plugin_schedules(text, uuid, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/reconcile_workflow_from_documents.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: reconcile_workflow_from_documents
-- Popis: Proces se srovná s PRAVDOU DOKLADU. Doklad, který účetnictví uzavřelo
--        (`settled=True`), uzavře i svůj procesní krok.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (admin/staff nebo service_role)
--
-- ⛔ PROČ VZNIKLA. Naměřeno 2026-08-31 na produkci: ze 40 863 kroků „předání"
--    bylo pending VŠECH 40 863 — a přitom 20 070 z nich má doklad se
--    `settled=True`. Účetnictví je uzavřelo, proces se to nikdy nedozvěděl,
--    takže „neuzavřené" znamenalo prakticky všechno a nešlo z toho
--    rozhodovat. Skutečně otevřených bylo 522.
--
-- ⭐ SMĚR JE JEDNOZNAČNÝ: doklad je zdroj, proces je odvozenina. Narovnává se
--    tedy proces podle dokladu, NIKDY naopak — a nikdy ručním zápisem do
--    úložiště. Když se doklad znovu natáhne z Money, tahle funkce z něj
--    pravdu převezme; to je celý mechanismus samoopravy.
--
-- ⭐ JEDEN KÓD, DVĚ CESTY: volá ji ingest po každém balíčku (nativně)
--    i administrace na vyžádání. Ne dvě implementace, které se rozejdou.
--
-- ⛔ NEUZAVÍRÁ, CO NEVÍ. Doklad bez údaje `settled` se NECHÁVÁ BÝT. Chybějící
--    údaj není „uzavřeno"; domněnka by tu vyrobila přesně ta falešná data,
--    kvůli kterým funkce vzniká.
--
-- ⛔ ČTE REGISTR, NE KROK. První verze brala `settled` z `input_data` kroku —
--    jenže ten je ZAMRZLÝ ve chvíli, kdy krok vznikl, takže čerstvý tah
--    z Money by proces nikdy nenarovnal a celý mechanismus samoopravy by byl
--    na papíře. Pravda teče INGESTEM do `li_source_registry` a odtud se čte;
--    párování `dl_number ↔ dn_number` ověřeno na 122 589 krocích.
--
-- ⛔ NEOTVÍRÁ ZPĚT. Krok, který člověk potvrdil (`completed`), zůstává —
--    lidské rozhodnutí nepřepisuje strojové srovnání.
--
-- Kontrakt: (boolean) -> jsonb {ok, zavreno, preskoceno_bez_udaje, dry_run}
-- ============================================================================

create or replace function public.reconcile_workflow_from_documents(
  p_dry_run boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path to 'public', 'pg_temp'
as $function$
declare
  v_kandidatu integer;
  v_bez_udaje integer;
  v_zavreno   integer := 0;
begin
  if not (public.is_service_role() or public.is_admin_or_staff()) then
    -- Fail-closed a POJMENOVANĚ: tohle je zápis do provozních dat, takže
    -- prázdný výsledek by byl horší než odmítnutí — vypadal by jako „nic
    -- k narovnání".
    return jsonb_build_object('ok', false, 'error', 'nedostatečné oprávnění');
  end if;

  -- Aktuální pravda dokladu z registru. `max` proto, že týž doklad může být
  -- v registru vícekrát (duplicity ze dvou generací ingestu) — a stačí, když
  -- ho JEDNA kopie hlásí jako uzavřený: uzavřenost se odvolat nedá.
  create temporary table if not exists _pravda_dokladu on commit drop as
  select r.fields->'dn_number'->>'value' as dl,
         max(r.fields->'settled'->>'value') as settled
  from public.li_source_registry r
  where r.doc_type = 'delivery_note' and r.fields ? 'dn_number'
  group by 1;

  select count(*) into v_kandidatu
  from public.production_workflow_steps s
  join _pravda_dokladu d on d.dl = s.input_data->>'dl_number'
  where s.status = 'pending' and d.settled = 'True';

  select count(*) into v_bez_udaje
  from public.production_workflow_steps s
  left join _pravda_dokladu d on d.dl = s.input_data->>'dl_number'
  where s.status = 'pending' and coalesce(d.settled, '') <> 'True'
    and coalesce(d.settled, '') <> 'False';

  if not p_dry_run then
    update public.production_workflow_steps s
       set status = 'completed',
           completed_at = coalesce(s.completed_at, now()),
           -- Stopa PŮVODU uzávěrky: aby šlo poznat, co uzavřel člověk a co
           -- srovnání s dokladem. Bez toho by se za měsíc nedalo rozlišit.
           output_data = coalesce(s.output_data, '{}'::jsonb)
                         || jsonb_build_object('uzavreno_srovnanim', true,
                                               'zdroj', 'li_source_registry.settled',
                                               'kdy', now())
     from _pravda_dokladu d
     where d.dl = s.input_data->>'dl_number'
       and s.status = 'pending'
       and d.settled = 'True';
    get diagnostics v_zavreno = row_count;
  end if;

  return jsonb_build_object(
    'ok', true,
    'dry_run', p_dry_run,
    'kandidatu', v_kandidatu,
    'zavreno', v_zavreno,
    'preskoceno_bez_udaje', v_bez_udaje
  );
end;
$function$;

revoke all on function public.reconcile_workflow_from_documents(boolean) from public, anon;
grant execute on function public.reconcile_workflow_from_documents(boolean) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_comm_av_scan_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.record_comm_av_scan_audited
-- Records an antivirus (ClamAV) scan verdict for an inbound-communication QUEUE item
-- (an integration_events row) and FAIL-CLOSES on anything but a clean result. This is
-- the av_scan stage of the content pipeline: the av-scan worker streams the attachment
-- to clamd (INSTREAM) and calls this with the verdict. Only a 'clean' item advances to
-- store → story_entry → vectorize.
--
--   clean    → no lifecycle change; the item proceeds (append + complete elsewhere).
--   infected → terminal block: status='exhausted' (definitive malware, retrying is futile);
--              object stays quarantined, NEVER promoted, NEVER vectorized.
--   error    → fail-closed retriable failure (scan error / timeout / clamd unreachable):
--              status='failed' (backoff retry); still never promotes/vectorizes.
--
-- Complementary to fn_record_safety_scan_audited (prompt-injection, TEXT stage). AV is the
-- BYTE/file stage — it protects the object store + humans; injection protects the RAG/LLM.
--
-- Security: SECURITY DEFINER, service_role ONLY (the scanner is a system worker).
-- @audit: required

CREATE OR REPLACE FUNCTION public.record_comm_av_scan_audited(
  p_event_id  uuid,
  p_verdict   text,
  p_engine    text  DEFAULT 'clamav'::text,
  p_signature text  DEFAULT NULL::text,
  p_file_hash text  DEFAULT NULL::text,
  p_metadata  jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_blocked boolean;
BEGIN
  IF current_setting('role', true) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'record_comm_av_scan_audited is service-role only' USING ERRCODE = '42501';
  END IF;
  IF p_verdict NOT IN ('clean', 'infected', 'error') THEN
    RAISE EXCEPTION 'p_verdict must be clean, infected, or error' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.integration_events WHERE id = p_event_id) THEN
    RAISE EXCEPTION 'integration_events row not found: %', p_event_id USING ERRCODE = '22023';
  END IF;

  v_blocked := p_verdict IS DISTINCT FROM 'clean';

  -- Persist the verdict on the queue item (observability + downstream gate).
  UPDATE public.integration_events
     SET metadata = COALESCE(metadata, '{}'::jsonb)
                 || jsonb_build_object('av',
                      COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object(
                        'verdict',    p_verdict,
                        'engine',     p_engine,
                        'signature',  p_signature,
                        'file_hash',  p_file_hash,
                        'blocked',    v_blocked,
                        'scanned_at', now()))
   WHERE id = p_event_id;

  -- Fail-closed lifecycle: only 'clean' advances.
  IF p_verdict = 'infected' THEN
    PERFORM public.complete_integration_event(p_event_id, 'exhausted', NULL,
      jsonb_build_object('message', 'av_infected', 'engine', p_engine, 'signature', p_signature));
  ELSIF p_verdict = 'error' THEN
    PERFORM public.complete_integration_event(p_event_id, 'failed', NULL,
      jsonb_build_object('message', 'av_scan_error', 'engine', p_engine));
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (NULL, 'comm.av_scan',
    jsonb_build_object(
      'area',      'communication',
      'severity',  CASE WHEN p_verdict = 'infected' THEN 'warning' ELSE 'info' END,
      'event_id',  p_event_id,
      'verdict',   p_verdict,
      'engine',    p_engine,
      'signature', p_signature,
      'blocked',   v_blocked));

  RETURN jsonb_build_object('event_id', p_event_id, 'verdict', p_verdict, 'blocked', v_blocked);
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.record_comm_av_scan_audited(uuid, text, text, text, text, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.record_comm_av_scan_audited(uuid, text, text, text, text, jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.record_comm_av_scan_audited(uuid, text, text, text, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_cron_proactive_run.sql
-- -----------------------------------------------------------------------------

-- Function: record_cron_proactive_run
-- Pravidla `source_event = 'CRON'` nemají zdrojový zápis, na který by se zavěsil
-- trigger — a do 2026-09-28 je nevykonával NIKDO (svc-ai-chat je čistě event-driven,
-- routu s CRON nikdo nevolá). Executor v event-workeru je bere na svůj tik: spočítá
-- poslední splatný slot podle `action_config.schedule` a zapíše běh do outboxu.
--
-- Idempotentní na (pravidlo, slot) — unikátní index uq_ai_proactive_runs_cron_slot.
-- Tik po restartu, dva executory, opakování téže minuty: slot se zapíše jednou.
-- Slot se normalizuje na UTC text, aby tentýž okamžik nedal dva různé klíče.
--
-- Principál = `created_by` pravidla (outbox je user-scoped, `user_id NOT NULL`).
-- Pravidlo bez principála se nezapíše (NULL) — pro kanály executoru to navíc
-- zakazuje omezení ai_proactive_defs_executor_principal_check už při zápisu pravidla.
--
-- Vrací id nového běhu, nebo NULL (slot už zapsán / pravidlo neplatí).

CREATE OR REPLACE FUNCTION public.record_cron_proactive_run(
  p_definition_id uuid,
  p_slot          timestamptz
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_def  ai_proactive_trigger_definitions%ROWTYPE;
  v_slot text;
  v_id   uuid;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_def
    FROM ai_proactive_trigger_definitions
   WHERE id = p_definition_id
     AND is_active
     AND source_event = 'CRON';
  IF NOT FOUND OR v_def.created_by IS NULL OR p_slot IS NULL THEN
    RETURN NULL;
  END IF;

  v_slot := to_char(p_slot AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');

  INSERT INTO ai_proactive_runs (
    trigger_definition_id, user_id, source_record_id, source_data, status, metadata
  ) VALUES (
    v_def.id, v_def.created_by, NULL,
    jsonb_build_object('cron_slot', v_slot),
    'pending',
    jsonb_build_object(
      'source_table',  v_def.source_table,
      'source_event',  'CRON',
      'cron_slot',     v_slot,
      'dispatched_at', now())
  )
  ON CONFLICT (trigger_definition_id, ((metadata ->> 'cron_slot')))
    WHERE (metadata ? 'cron_slot')
  DO NOTHING
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.record_cron_proactive_run(uuid, timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_cron_proactive_run(uuid, timestamptz) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_document_av_scan_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.record_document_av_scan_audited
-- Records an antivirus (ClamAV) scan verdict for an UPLOADED document
-- (a member_health_documents row) and FAIL-CLOSES on anything but a clean result. The
-- storage-auth scan worker streams the quarantined object to clamd (INSTREAM) and calls this
-- with the verdict; only a 'clean' document is promoted to a durable bucket + becomes eligible
-- for OCR/AI processing + vectorization.
--
--   clean    → quarantine_status='clear'; on a non-null p_durable_path also stamp the promoted
--              (durable-bucket) file_path. The OCR/AI pipeline (processing_status) proceeds.
--   infected → quarantine_status='quarantined' (terminal block; object deleted from quarantine
--              by the worker, NEVER promoted, NEVER vectorized).
--   error    → quarantine_status='flagged' (fail-closed: scan error / timeout / clamd
--              unreachable). Stays blocked; surfaces in the quarantine review queue.
--
-- Sibling of record_comm_av_scan_audited (the inbound-comm/mail-attachment queue variant) — same
-- fail-closed contract, different substrate (a document row vs an integration_events row). AV is
-- the BYTE/file stage; scanForInjection is the prompt-injection TEXT stage.
--
-- Security: SECURITY DEFINER, service_role ONLY (the scanner is a system worker, no auth.uid()).
-- @audit: required

CREATE OR REPLACE FUNCTION public.record_document_av_scan_audited(
  p_document_id  uuid,
  p_verdict      text,
  p_engine       text  DEFAULT 'clamav'::text,
  p_signature    text  DEFAULT NULL::text,
  p_durable_path text  DEFAULT NULL::text,
  p_metadata     jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_blocked boolean;
  v_qstatus text;
  v_user    uuid;
BEGIN
  IF current_setting('role', true) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'record_document_av_scan_audited is service-role only' USING ERRCODE = '42501';
  END IF;
  IF p_verdict NOT IN ('clean', 'infected', 'error') THEN
    RAISE EXCEPTION 'p_verdict must be clean, infected, or error' USING ERRCODE = '22023';
  END IF;

  SELECT user_id INTO v_user FROM public.member_health_documents WHERE id = p_document_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'member_health_documents row not found: %', p_document_id USING ERRCODE = '22023';
  END IF;

  -- Fail-closed verdict → quarantine_status (same value set + gating predicate as knowledge_items).
  v_qstatus := CASE p_verdict
                 WHEN 'clean'    THEN 'clear'
                 WHEN 'infected' THEN 'quarantined'
                 ELSE                 'flagged'   -- scan error/timeout/unreachable: blocked, needs review
               END;
  v_blocked := p_verdict IS DISTINCT FROM 'clean';

  UPDATE public.member_health_documents
     SET quarantine_status = v_qstatus,
         av_signature      = CASE WHEN p_verdict = 'clean' THEN NULL ELSE COALESCE(p_signature, p_verdict) END,
         av_scanned_at     = now(),
         -- On a clean verdict, stamp the promoted (durable) path if the worker copied the object.
         file_path         = CASE WHEN p_verdict = 'clean' AND p_durable_path IS NOT NULL
                                  THEN p_durable_path ELSE file_path END,
         updated_at        = now()
   WHERE id = p_document_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_user, 'document.av_scan',
    COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'area',              'documents',
      'severity',          CASE WHEN p_verdict = 'infected' THEN 'warning' ELSE 'info' END,
      'document_id',       p_document_id,
      'verdict',           p_verdict,
      'engine',            p_engine,
      'signature',         p_signature,
      'quarantine_status', v_qstatus,
      'blocked',           v_blocked));

  RETURN jsonb_build_object(
    'document_id',       p_document_id,
    'verdict',           p_verdict,
    'quarantine_status', v_qstatus,
    'blocked',           v_blocked);
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.record_document_av_scan_audited(uuid, text, text, text, text, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.record_document_av_scan_audited(uuid, text, text, text, text, jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.record_document_av_scan_audited(uuid, text, text, text, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_drift_observation.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: record_drift_observation
-- Popis: Insertuje novou drift observation. Idempotent v 5min buckets — pokud
--        existuje unresolved row se stejným (app_uuid, drift_kind) v posledních
--        5 minutách, updatne `observation_count` a vrátí existující ID
--        (nedělá nový insert). Drift kind validovaný proti CHECK constraint.
-- Volá: WF_DRIFT_OBSERVER (n8n cron 10min) na výsledcích z coolify-drift-check.mjs
-- Auth: service_role nebo admin/staff
-- ============================================================================

CREATE OR REPLACE FUNCTION public.record_drift_observation(
  p_app_uuid      text,
  p_app_name      text,
  p_drift_kind    text,
  p_desired_value jsonb,
  p_actual_value  jsonb,
  p_risk_level    text,
  p_metadata      jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_existing_id uuid;
  v_new_id      uuid;
  v_is_service  boolean;
BEGIN
  -- Authorization: service_role nebo admin
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required' USING ERRCODE = '22023';
  END IF;

  -- Validate inputs
  IF p_app_uuid IS NULL OR p_app_uuid = '' THEN
    RAISE EXCEPTION 'app_uuid required' USING ERRCODE = '22023';
  END IF;
  IF p_risk_level NOT IN ('low','medium','high','critical') THEN
    RAISE EXCEPTION 'Invalid risk_level: %', p_risk_level USING ERRCODE = '22023';
  END IF;

  -- Dedup: existing unresolved row in last 5 min?
  SELECT id INTO v_existing_id
  FROM public.drift_state
  WHERE app_uuid = p_app_uuid
    AND drift_kind = p_drift_kind
    AND observed_at > now() - interval '5 minutes'
    AND resolved_at IS NULL
  ORDER BY observed_at DESC
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    UPDATE public.drift_state
    SET observation_count = observation_count + 1,
        actual_value = p_actual_value,    -- update s nejnovější hodnotou
        observed_at = now(),
        metadata = metadata || p_metadata
    WHERE id = v_existing_id;
    RETURN v_existing_id;
  END IF;

  -- New observation
  INSERT INTO public.drift_state (
    app_uuid, app_name, drift_kind,
    desired_value, actual_value, risk_level,
    remediation, metadata
  )
  VALUES (
    p_app_uuid, p_app_name, p_drift_kind,
    p_desired_value, p_actual_value, p_risk_level,
    'pending', p_metadata
  )
  RETURNING id INTO v_new_id;

  RETURN v_new_id;
END;
$$;

REVOKE ALL ON FUNCTION public.record_drift_observation(text, text, text, jsonb, jsonb, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_drift_observation(text, text, text, jsonb, jsonb, text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.record_drift_observation(text, text, text, jsonb, jsonb, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_integration_event.sql
-- -----------------------------------------------------------------------------

-- Function: public.record_integration_event
-- Idempotent upsert for incoming integration events (webhooks, deployments, etc.)
-- Deduplicates by (event_source, external_id) UNIQUE constraint.
-- @security: service_role only

CREATE OR REPLACE FUNCTION public.record_integration_event(
  p_event_source    text,
  p_external_id     text,
  p_event_type      text,
  p_installation_id bigint DEFAULT NULL,
  p_story_id        uuid DEFAULT NULL,
  p_partner_id      uuid DEFAULT NULL,
  p_routed_to       text DEFAULT NULL,
  p_payload_hash    text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_event_id uuid;
  v_is_duplicate boolean := false;
BEGIN
  INSERT INTO integration_events (
    event_source, external_id, event_type,
    installation_id, story_id, partner_id,
    routed_to, payload_hash,
    status, processing_started_at
  ) VALUES (
    p_event_source, p_external_id, p_event_type,
    p_installation_id, p_story_id, p_partner_id,
    p_routed_to, p_payload_hash,
    'processing', now()
  )
  ON CONFLICT (event_source, external_id) DO NOTHING
  RETURNING id INTO v_event_id;

  IF v_event_id IS NULL THEN
    v_is_duplicate := true;
    SELECT id INTO v_event_id
    FROM integration_events
    WHERE event_source = p_event_source AND external_id = p_external_id;

    UPDATE integration_events
    SET status = 'skipped_duplicate'
    WHERE id = v_event_id AND status = 'received';
  END IF;

  RETURN jsonb_build_object(
    'event_id', v_event_id,
    'is_duplicate', v_is_duplicate,
    'status', CASE WHEN v_is_duplicate THEN 'skipped_duplicate' ELSE 'processing' END
  );
END;
$$;

REVOKE ALL ON FUNCTION public.record_integration_event(text, text, text, bigint, uuid, uuid, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_integration_event(text, text, text, bigint, uuid, uuid, text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/ingest_inbound_comm_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.ingest_inbound_comm_audited
-- Atomic production ingest for the inbound-communication QUEUE. This is the single
-- entry point the inbound adapter (svc / n8n) calls per received message. It ties
-- the two existing primitives together with the queue as the AUTHORITATIVE dedup,
-- so we never deduplicate twice:
--
--   1. record_integration_event(event_source, external_id, …)  ← QUEUE + dedup + lifecycle
--      (durable, retry/backoff, status, story_id) — the operational envelope.
--   2. IF the event is a duplicate → return the existing story entry (do NOT create a
--      second one — this is what resolves the dedup duplication between the queue and
--      append_inbound_comm_entry_audited's own idempotency guard).
--   3. ELSE append_inbound_comm_entry_audited(…)              ← STORY view (the content)
--      — the email becomes a story_entry: "mail seen from the story's perspective".
--   4. complete_integration_event(event_id, 'completed')      ← close the ingest stage.
--
-- The event ↔ entry are linked both ways: integration_events.story_id points at the
-- story; the story_entry carries metadata.integration_event_id. The story timeline
-- (get_story_entries_audited) shows the message; get_integration_events_for_story shows
-- the queue/ops status. No separate mail inbox — the STORY is the inbox.
--
-- Scope note: AV malware scan is a PRE-ingest guard and vectorization is a POST-ingest
-- async feed via the existing knowledge_items→Ragnarok pipeline — both are the M2
-- content pipeline and are intentionally NOT part of this event's lifecycle.
--
-- Security: SECURITY DEFINER, service_role ONLY (system ingestion path).
-- @audit: required (delegated — record_integration_event + append both audit)

CREATE OR REPLACE FUNCTION public.ingest_inbound_comm_audited(
  p_channel         text,
  p_external_id     text,
  p_story_id        uuid,
  p_from            text DEFAULT NULL::text,
  p_subject         text DEFAULT NULL::text,
  p_body            text DEFAULT NULL::text,
  p_parent_entry_id uuid DEFAULT NULL::uuid,
  p_routed_to       text DEFAULT NULL::text,
  p_metadata        jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_channel       text := lower(p_channel);
  v_event_source  text;
  v_rec           jsonb;
  v_event_id      uuid;
  v_is_dup        boolean;
  v_entry_id      uuid;
  v_append        jsonb;
BEGIN
  -- System ingestion path: service_role only. Inbound messages carry no auth.uid().
  IF current_setting('role', true) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'ingest_inbound_comm_audited is service-role only' USING ERRCODE = '42501';
  END IF;

  IF v_channel IS NULL OR btrim(v_channel) = '' THEN
    RAISE EXCEPTION 'p_channel is required' USING ERRCODE = '22023';
  END IF;
  IF p_external_id IS NULL OR btrim(p_external_id) = '' THEN
    RAISE EXCEPTION 'p_external_id is required (idempotency key)' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.partner_stories WHERE id = p_story_id) THEN
    RAISE EXCEPTION 'Target story not found: %', p_story_id USING ERRCODE = '22023';
  END IF;

  -- Map channel → integration_events.event_source. Only 'email' is wired today
  -- (event_source CHECK). Extend the CHECK + this map when chat/webhook adapters land.
  v_event_source := CASE v_channel WHEN 'email' THEN 'email_inbound' ELSE NULL END;
  IF v_event_source IS NULL THEN
    RAISE EXCEPTION 'unsupported inbound channel: % (extend integration_events.event_source first)', v_channel
      USING ERRCODE = '22023';
  END IF;

  -- (1) Enqueue with the queue's authoritative dedup.
  v_rec      := public.record_integration_event(
                  v_event_source, p_external_id, v_channel || '.inbound',
                  NULL, p_story_id, NULL, p_routed_to, NULL);
  v_event_id := (v_rec->>'event_id')::uuid;
  v_is_dup   := (v_rec->>'is_duplicate')::boolean;

  -- (2) Duplicate → reuse the existing story entry; never create a second one.
  -- (3) Fresh    → create the story-view entry (links back to the queue event) and
  --               close the ingest stage. AV (pre) + vectorization (post, via the
  --               existing knowledge→Ragnarok feed) are the M2 content pipeline,
  --               NOT this event's lifecycle.
  IF v_is_dup THEN
    SELECT id INTO v_entry_id
      FROM public.story_entries
     WHERE entry_type = 'inbound_' || v_channel
       AND metadata->>'external_id' = p_external_id
     LIMIT 1;
  ELSE
    v_append := public.append_inbound_comm_entry_audited(
                  p_story_id, v_channel, p_external_id, p_from, p_subject, p_body, p_parent_entry_id,
                  COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object('integration_event_id', v_event_id));
    v_entry_id := (v_append->>'entry_id')::uuid;
    PERFORM public.complete_integration_event(v_event_id, 'completed', NULL, NULL);
  END IF;

  -- (4) Orchestration-level provenance (record_integration_event + append audit too).
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (NULL, 'COMM_INBOUND_INGESTED',
    jsonb_build_object(
      'area',        'communication',
      'severity',    'info',
      'event_id',    v_event_id,
      'entry_id',    v_entry_id,
      'story_id',    p_story_id,
      'channel',     v_channel,
      'external_id', p_external_id,
      'deduped',     v_is_dup));

  RETURN jsonb_build_object(
    'event_id', v_event_id, 'entry_id', v_entry_id,
    'story_id', p_story_id, 'deduped', v_is_dup);
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.ingest_inbound_comm_audited(text, text, uuid, text, text, text, uuid, text, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.ingest_inbound_comm_audited(text, text, uuid, text, text, text, uuid, text, jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.ingest_inbound_comm_audited(text, text, uuid, text, text, text, uuid, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_media_asset.sql
-- -----------------------------------------------------------------------------

-- Function: public.record_media_asset
-- Description: Zapíše (nebo obnoví) záznam nahraného média. Volá storage-auth
--              pod service_role ve chvíli, kdy objekt PROŠEL antivirem a leží
--              v cílovém veřejném bucketu — dřív záznam vzniknout nesmí, jinak
--              by galerie nabízela obrázek, který se nikdy neservíruje.
--              Idempotentní: (bucket, object_key) je klíč objektu; opakované
--              ohlášení téhož nahrání záznam jen obnoví (deleted_at → NULL).
-- Security: SECURITY DEFINER, JEN service_role — identita nahrávajícího přichází
--           v p_uploaded_by z ověřeného tokenu ve storage-auth, ne od klienta.
-- Created: 2026-09-24

CREATE OR REPLACE FUNCTION public.record_media_asset(
  p_bucket text,
  p_bytes bigint,
  p_content_type text,
  p_object_key text,
  p_original_name text DEFAULT NULL,
  p_uploaded_by uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id uuid;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF COALESCE(p_bucket, '') = '' OR COALESCE(p_object_key, '') = '' OR COALESCE(p_content_type, '') = '' THEN
    RAISE EXCEPTION 'bucket, object_key and content_type are required';
  END IF;

  INSERT INTO public.media_assets (bucket, object_key, content_type, bytes, original_name, uploaded_by)
  VALUES (p_bucket, p_object_key, p_content_type, COALESCE(p_bytes, 0), NULLIF(p_original_name, ''), p_uploaded_by)
  ON CONFLICT (bucket, object_key) DO UPDATE SET
    content_type  = EXCLUDED.content_type,
    bytes         = EXCLUDED.bytes,
    original_name = COALESCE(EXCLUDED.original_name, media_assets.original_name),
    uploaded_by   = COALESCE(EXCLUDED.uploaded_by, media_assets.uploaded_by),
    deleted_at    = NULL
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.record_media_asset(text, bigint, text, text, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_media_asset(text, bigint, text, text, text, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_model_benchmark.sql
-- -----------------------------------------------------------------------------

-- Function: record_model_benchmark
-- Records a QUALITY benchmark for (model, task_type) with REPLACE semantics: it first
-- deletes any prior row for that exact pair, then inserts the fresh scores. This is the
-- write-path for the benchmark runner (the real quality eval, beyond the smoke
-- self-test). insert_model_benchmark APPENDS, but the resolver LEFT JOINs
-- ai_model_benchmarks ON task_type = v_task_kind with NO dedup — so two rows for the
-- same (model, task_type) would BOTH become candidates and a stale run could skew the
-- ranking. Replace keeps exactly one CURRENT score per pair. service_role only.

CREATE OR REPLACE FUNCTION public.record_model_benchmark(
  p_model_registry_id uuid,
  p_task_type         text,
  p_relevance         numeric DEFAULT NULL,
  p_groundedness      numeric DEFAULT NULL,
  p_safety            numeric DEFAULT NULL,
  p_coherence         numeric DEFAULT NULL,
  p_overall           numeric DEFAULT NULL,
  p_avg_latency_ms    integer DEFAULT NULL,
  p_avg_tokens_input  integer DEFAULT NULL,
  p_avg_tokens_output integer DEFAULT NULL,
  p_avg_cost_per_call numeric DEFAULT NULL,
  p_success_rate      numeric DEFAULT NULL,
  p_eval_run_id       uuid    DEFAULT NULL,
  p_sample_count      integer DEFAULT 1
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id uuid;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'service_role required' USING ERRCODE = '22023';
  END IF;
  IF p_model_registry_id IS NULL OR p_task_type IS NULL THEN
    RAISE EXCEPTION 'p_model_registry_id + p_task_type required' USING ERRCODE = '22023';
  END IF;

  -- Replace → exactly one CURRENT benchmark per (model, task_type).
  DELETE FROM ai_model_benchmarks
  WHERE model_registry_id = p_model_registry_id AND task_type = p_task_type;

  INSERT INTO ai_model_benchmarks (
    model_registry_id, task_type, relevance_score, groundedness_score, safety_score,
    coherence_score, overall_score, avg_latency_ms, avg_tokens_input, avg_tokens_output,
    avg_cost_per_call, success_rate, eval_run_id, sample_count
  ) VALUES (
    p_model_registry_id, p_task_type, p_relevance, p_groundedness, p_safety,
    p_coherence, p_overall, p_avg_latency_ms, p_avg_tokens_input, p_avg_tokens_output,
    p_avg_cost_per_call, p_success_rate, p_eval_run_id, COALESCE(p_sample_count, 1)
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.record_model_benchmark(uuid, text, numeric, numeric, numeric, numeric, numeric, integer, integer, integer, numeric, numeric, uuid, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_model_benchmark(uuid, text, numeric, numeric, numeric, numeric, numeric, integer, integer, integer, numeric, numeric, uuid, integer) TO service_role;

COMMENT ON FUNCTION public.record_model_benchmark(uuid, text, numeric, numeric, numeric, numeric, numeric, integer, integer, integer, numeric, numeric, uuid, integer) IS
  'Quality benchmark write-path with REPLACE semantics (one current row per model+task_type) so the resolver score JOIN is never skewed by a stale run. service_role only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_model_reliability.sql
-- -----------------------------------------------------------------------------

-- Function: public.record_model_reliability  —  L1 REPLACE writer for ai_model_reliability
-- Upserts exactly one CURRENT reliability row per (model_registry_id, normalized task_kind).
-- Mirrors record_model_benchmark's REPLACE discipline, but targets the SEPARATE reliability table
-- so reactive telemetry never touches the curated quality benchmarks the resolver ranks on.
-- service_role (rollup/cron) or admin/staff only. Returns the row id.

CREATE OR REPLACE FUNCTION public.record_model_reliability(
  p_model_registry_id uuid,
  p_task_kind         text,
  p_sample_count      bigint  DEFAULT 0,
  p_success_rate      numeric DEFAULT NULL,
  p_error_rate        numeric DEFAULT NULL,
  p_avg_latency_ms    integer DEFAULT NULL,
  p_p95_latency_ms    integer DEFAULT NULL,
  p_avg_cost_per_call numeric DEFAULT NULL,
  p_avg_eval_score    numeric DEFAULT NULL,
  p_window_hours      integer DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_norm text;
  v_id   uuid;
BEGIN
  -- NULL-safe fail-closed guard (parity with fn_get_decision_outcomes / fn_rollup / fn_observe):
  -- is_service_role() returns a non-null boolean and is_admin_or_staff is COALESCEd, so an absent
  -- claim can never leave the predicate NULL (which would skip the RAISE and fail OPEN).
  IF NOT (public.is_service_role() OR COALESCE(public.is_admin_or_staff(auth.uid()), false)) THEN
    RAISE EXCEPTION 'Not authorized: service_role or admin/staff required' USING ERRCODE = '42501';
  END IF;
  IF p_model_registry_id IS NULL OR p_task_kind IS NULL THEN
    RAISE EXCEPTION 'p_model_registry_id + p_task_kind required' USING ERRCODE = '22023';
  END IF;

  v_norm := public.normalize_task_kind(p_task_kind);

  INSERT INTO public.ai_model_reliability (
    model_registry_id, task_kind, sample_count, success_rate, error_rate,
    avg_latency_ms, p95_latency_ms, avg_cost_per_call, avg_eval_score, window_hours, measured_at
  ) VALUES (
    p_model_registry_id, v_norm, GREATEST(p_sample_count, 0), p_success_rate, p_error_rate,
    p_avg_latency_ms, p_p95_latency_ms, p_avg_cost_per_call, p_avg_eval_score, p_window_hours, now()
  )
  ON CONFLICT (model_registry_id, task_kind) DO UPDATE SET
    sample_count      = EXCLUDED.sample_count,
    success_rate      = EXCLUDED.success_rate,
    error_rate        = EXCLUDED.error_rate,
    avg_latency_ms    = EXCLUDED.avg_latency_ms,
    p95_latency_ms    = EXCLUDED.p95_latency_ms,
    avg_cost_per_call = EXCLUDED.avg_cost_per_call,
    avg_eval_score    = EXCLUDED.avg_eval_score,
    window_hours      = EXCLUDED.window_hours,
    measured_at       = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END $$;

COMMENT ON FUNCTION public.record_model_reliability(uuid, text, bigint, numeric, numeric, integer, integer, numeric, numeric, integer) IS
  'L1 REPLACE writer for ai_model_reliability (one current row per model+normalized task_kind). Reactive telemetry sink, separate from ai_model_benchmarks. service_role/admin only.';

REVOKE ALL ON FUNCTION public.record_model_reliability(uuid, text, bigint, numeric, numeric, integer, integer, numeric, numeric, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_model_reliability(uuid, text, bigint, numeric, numeric, integer, integer, numeric, numeric, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_rollup_outcomes_to_benchmark.sql
-- -----------------------------------------------------------------------------

-- Function: public.fn_rollup_outcomes_to_benchmark  (L1 — reactive outcome rollup)
--
-- NAME NOTE: the historical name is retained (the SoT reconcile expects it), but this function
-- writes the ADVISORY reliability sink public.ai_model_reliability via record_model_reliability.
-- It deliberately does NOT write the resolver-ranked quality table: that table is LEFT JOINed by
-- aisha_resolve_clow_backend with no dedup, so a second row there would fan out the candidate set
-- and leak telemetry into the quality score (the curated REPLACE writer documents this very hazard).
-- Reactive telemetry therefore lands only in ai_model_reliability, which nothing in the resolver reads today
-- → zero ranking impact, fully advisory. L2 (advisory proposals) / a future, deliberately-reviewed
-- resolver tie-breaker can consume it explicitly.
--
-- MODEL AXIS = the model's OWN calls only: ai_trace_events restricted to event_type='llm_call'
--   (one per direct_llm dispatch) — tool-call latencies/failures never pollute a model metric.
-- IDENTITY = (provider_slug, model_id): both are join keys, so a model_id served by two providers
--   is never conflated. Decisions without task_kind/provider/model are skipped (no guessing).
-- QUALITY = avg_eval_score is sourced ONLY from a real eval (ai_runs.faithfulness_score_estimate),
--   carried for observability; it is never a ranking input here.
-- task_kind is NORMALIZED (T1 normalize_task_kind) and each kind RECORDED (fn_observe_task_kind).
--
-- Security: SECURITY DEFINER, VOLATILE. EXECUTE restricted to service_role (cron); the NULL-safe
--   body guard also accepts admin/staff. Returns the number of (model × task) reliability rows upserted.
-- Driven by: n8n WF_OUTCOME_ROLLUP (scheduleTrigger ~6h → POST /rpc/fn_rollup_outcomes_to_benchmark).

-- Consolidated under this name; drop the short-lived alias if a prior build created it.
DROP FUNCTION IF EXISTS public.fn_rollup_outcomes_to_reliability(int, int);

CREATE OR REPLACE FUNCTION public.fn_rollup_outcomes_to_benchmark(
  p_window_hours int DEFAULT 168,
  p_min_samples  int DEFAULT 1
)
RETURNS int
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  -- NULL-safe authorization: an absent claim / unset GUC folds to false, never NULL, so the guard
  -- cannot fail open; a non-service, non-admin caller is rejected.
  v_is_service boolean := COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '') = 'service_role'
                          OR COALESCE(current_setting('role', true), '') = 'service_role';
  v_is_admin   boolean := COALESCE(public.is_admin_or_staff(auth.uid()), false);
  v_count      int := 0;
  rec          record;
BEGIN
  IF NOT (v_is_service OR v_is_admin) THEN
    RAISE EXCEPTION 'Not authorized: service_role or admin/staff required' USING ERRCODE = '42501';
  END IF;

  FOR rec IN
    SELECT
      reg.id                                                       AS model_registry_id,
      public.normalize_task_kind(d.decision_json->>'task_kind')    AS task_kind,
      count(*)                                                     AS n,
      avg(t.duration_ms)::int                                      AS avg_latency,
      (percentile_cont(0.95) WITHIN GROUP (ORDER BY t.duration_ms))::int AS p95_latency,
      avg(NULLIF(t.cost_json->>'total', '')::numeric)          AS avg_cost,
      avg((t.status = 'ok')::int)::numeric                         AS success_rate,
      avg((t.status = 'error')::int)::numeric                      AS error_rate,
      avg(r.faithfulness_score_estimate)                           AS avg_eval  -- REAL quality; NULL when no eval ran
    FROM public.ai_decisions d
    JOIN public.ai_trace_events t
      ON t.decision_id = d.id AND t.event_type = 'llm_call'   -- model axis only (no tool_call pollution)
    JOIN public.ai_model_registry reg
      ON reg.model_id = d.model_id AND reg.provider = d.provider_slug  -- (provider, model_id) identity → no conflation
    LEFT JOIN public.ai_runs r ON r.id = d.run_id
    WHERE d.created_at >= now() - make_interval(hours => p_window_hours)
      AND d.model_id IS NOT NULL
      AND d.provider_slug IS NOT NULL
      AND (d.decision_json->>'task_kind') IS NOT NULL
      AND d.runtime = 'direct_llm'
    GROUP BY reg.id, public.normalize_task_kind(d.decision_json->>'task_kind')
    HAVING count(*) >= p_min_samples
  LOOP
    -- Reactive telemetry → ADVISORY reliability sink (REPLACE: one current row per pair).
    -- NEVER the resolver-ranked quality table.
    PERFORM public.record_model_reliability(
      p_model_registry_id => rec.model_registry_id,
      p_task_kind         => rec.task_kind,
      p_sample_count      => rec.n::bigint,
      p_success_rate      => rec.success_rate,
      p_error_rate        => rec.error_rate,
      p_avg_latency_ms    => rec.avg_latency,
      p_p95_latency_ms    => rec.p95_latency,
      p_avg_cost_per_call => rec.avg_cost,
      p_avg_eval_score    => rec.avg_eval,   -- advisory observability only; not read by the resolver
      p_window_hours      => p_window_hours
    );
    -- T1: keep the observed task_kind registry current (descriptive; never gates).
    PERFORM public.fn_observe_task_kind(rec.task_kind, rec.n::bigint);
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END $$;

COMMENT ON FUNCTION public.fn_rollup_outcomes_to_benchmark(int, int) IS
  'L1 reactive feedback rollup: aggregates REAL production dispatch outcomes (ai_decisions join ai_trace_events on event_type=llm_call, identity provider+model_id) per (model x normalized task_kind) into the ADVISORY ai_model_reliability sink via record_model_reliability; records observed kinds via fn_observe_task_kind. Does NOT write the resolver-ranked quality table (no ranking impact). avg_eval from real eval only. EXECUTE service_role only.';

REVOKE ALL ON FUNCTION public.fn_rollup_outcomes_to_benchmark(int, int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_rollup_outcomes_to_benchmark(int, int) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_model_self_test.sql
-- -----------------------------------------------------------------------------

-- Function: record_model_self_test
-- The AUTOMATED self-test verdict for a discovered model — the missing transition
-- that closes the discover→self-test→moderate→resolve loop. After discovery upserts
-- a model as eval_status='pending', AISHA runs a smoke probe and calls this: it
-- records a benchmark row AND transitions eval_status to 'tested' (the model
-- responded) or 'rejected' (it failed). This is the system counterpart to the
-- admin-driven approve_model_admin / reject_model_admin.
--
-- Eligibility: 'pending'/'tested' are always re-testable. A 'rejected' model is
-- re-tested ONLY with p_force=true (an admin-triggered re-test, e.g. after a transient
-- provider outage) — so the boot self-test never silently re-promotes a rejected model.
-- An 'approved' verdict is NEVER overwritten. A benchmark row is always recorded (it
-- refreshes the score) even when the status is not eligible to change. service_role only.

-- p_force added → drop the old 7-arg signature so the overload does not linger.
DROP FUNCTION IF EXISTS public.record_model_self_test(uuid, text, boolean, numeric, integer, integer, text);

CREATE OR REPLACE FUNCTION public.record_model_self_test(
  p_model_registry_id uuid,
  p_task_type         text    DEFAULT 'smoke',
  p_passed            boolean DEFAULT false,
  p_overall           numeric DEFAULT NULL,
  p_avg_latency_ms    integer DEFAULT NULL,
  p_sample_count      integer DEFAULT 1,
  p_detail            text    DEFAULT NULL,
  p_force             boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_old_status text;
  v_new_status text;
  v_eligible   boolean;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'service_role required' USING ERRCODE = '22023';
  END IF;
  IF p_model_registry_id IS NULL THEN
    RAISE EXCEPTION 'p_model_registry_id required' USING ERRCODE = '22023';
  END IF;

  SELECT eval_status INTO v_old_status FROM ai_model_registry WHERE id = p_model_registry_id FOR UPDATE;
  IF v_old_status IS NULL THEN
    RAISE EXCEPTION 'Model % not found', p_model_registry_id USING ERRCODE = '22023';
  END IF;

  -- pending/tested always re-testable; rejected only under an explicit force;
  -- approved is NEVER auto-overwritten.
  v_eligible := v_old_status IN ('pending', 'tested') OR (v_old_status = 'rejected' AND p_force);

  -- Benchmark row — feeds the resolver's score-based ranking (recorded regardless).
  INSERT INTO ai_model_benchmarks (model_registry_id, task_type, overall_score, avg_latency_ms, success_rate, sample_count)
  VALUES (p_model_registry_id, p_task_type, p_overall, p_avg_latency_ms,
          CASE WHEN p_passed THEN 1.0 ELSE 0.0 END, COALESCE(p_sample_count, 1));

  v_new_status := CASE WHEN p_passed THEN 'tested' ELSE 'rejected' END;
  UPDATE ai_model_registry
  SET    eval_status = v_new_status, updated_at = now()
  WHERE  id = p_model_registry_id
    AND  v_eligible;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'model.self_tested', jsonb_build_object(
    'model_registry_id', p_model_registry_id::text, 'task_type', p_task_type,
    'passed', p_passed, 'overall', p_overall, 'from', v_old_status,
    'to', CASE WHEN v_eligible THEN v_new_status ELSE v_old_status END,
    'forced', p_force,
    'detail', LEFT(COALESCE(p_detail, ''), 200)
  ));

  RETURN jsonb_build_object(
    'model_registry_id', p_model_registry_id,
    'passed', p_passed,
    'from', v_old_status,
    'eval_status', CASE WHEN v_eligible THEN v_new_status ELSE v_old_status END,
    'admin_verdict_preserved', NOT v_eligible,
    'forced', p_force
  );
END;
$$;

REVOKE ALL ON FUNCTION public.record_model_self_test(uuid, text, boolean, numeric, integer, integer, text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_model_self_test(uuid, text, boolean, numeric, integer, integer, text, boolean) TO service_role;

COMMENT ON FUNCTION public.record_model_self_test(uuid, text, boolean, numeric, integer, integer, text, boolean) IS
  'Automated model self-test verdict — records a benchmark + transitions eval_status pending/tested→tested|rejected; a rejected model re-tests only with p_force=true; approved is never overwritten. service_role only.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_plugin_declaration.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: record_plugin_declaration
-- Popis: Host zapíše výsledek zapálení pluginu (běh jen-deklaruj) pro tenanta:
--        verzi, ok/failed a detail (počty zapsaných/odmítnutých rozvrhů, chyba).
--        Nová verze nebo selhání tak znamená opakování, úspěch klid.
--
-- ⛔ Do `detail` NIKDY hodnoty konfigurace ani pověření — jen počty, důvody
-- odmítnutí rozvrhů a zkrácený text chyby (host ho krátí na 200 znaků).
-- Bezpečnost: jen služba.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.record_plugin_declaration(
  p_plugin_slug    text,
  p_tenant_id      uuid,
  p_plugin_version text,
  p_status         text,
  p_detail         jsonb DEFAULT '{}'::jsonb
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_plugin_id uuid;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'record_plugin_declaration: jen služba (svc-plugin-system)' USING ERRCODE = '42501';
  END IF;
  IF p_status NOT IN ('ok', 'failed') THEN
    RAISE EXCEPTION 'record_plugin_declaration: status musí být ok|failed';
  END IF;
  IF p_tenant_id IS NULL OR NULLIF(btrim(COALESCE(p_plugin_version, '')), '') IS NULL THEN
    RAISE EXCEPTION 'record_plugin_declaration: tenant a verze jsou povinné';
  END IF;
  SELECT id INTO v_plugin_id FROM public.plugin_catalog WHERE slug = p_plugin_slug;
  IF v_plugin_id IS NULL THEN
    RAISE EXCEPTION 'record_plugin_declaration: plugin % neexistuje', p_plugin_slug;
  END IF;

  INSERT INTO public.plugin_declarations (plugin_id, tenant_id, plugin_version, status, detail, declared_at)
  VALUES (v_plugin_id, p_tenant_id, p_plugin_version, p_status,
          CASE WHEN jsonb_typeof(p_detail) = 'object' THEN p_detail ELSE '{}'::jsonb END, now())
  ON CONFLICT (plugin_id, tenant_id) DO UPDATE
    SET plugin_version = EXCLUDED.plugin_version,
        status         = EXCLUDED.status,
        detail         = EXCLUDED.detail,
        declared_at    = EXCLUDED.declared_at;
END;
$$;

COMMENT ON FUNCTION public.record_plugin_declaration(text, uuid, text, text, jsonb) IS
  'Records the outcome of a plugin ignition (declare-only run) for a tenant: version, ok/failed, detail without secrets. Service only.';

REVOKE ALL ON FUNCTION public.record_plugin_declaration(text, uuid, text, text, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.record_plugin_declaration(text, uuid, text, text, jsonb) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.record_plugin_declaration(text, uuid, text, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_provider_health_result.sql
-- -----------------------------------------------------------------------------

-- Function: record_provider_health_result
-- WF_PROVIDER_HEALTH_PROBE calls this after fetching the provider's health
-- endpoint. Updates ai_provider_registry.last_health_{status,checked_at,detail}
-- so aisha_resolve_clow_backend's scoring can deprioritize degraded/down
-- providers in real time.
--
-- Status enum (must match ai_provider_registry CHECK constraint):
--   * healthy   — HTTP 2xx + parseable response + latency < 3s
--   * degraded  — HTTP 2xx but slow (>3s) OR partial response
--   * down      — HTTP 4xx/5xx OR network error
--   * unknown   — initial state; should NOT be set by this RPC (probe failed
--                 to even run → caller should record 'down' with detail)
--
-- Audits via audit_journal action='provider.health_probed' so operators can
-- see the probe history (and detect probe gaps if WF_PROVIDER_HEALTH_PROBE
-- itself goes down). Idempotent: writes always succeed, even if status
-- didn't change (latency_ms still useful for monitoring).

CREATE OR REPLACE FUNCTION public.record_provider_health_result(
  p_slug       text,
  p_status     text,
  p_latency_ms int  DEFAULT NULL,
  p_detail     text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_provider RECORD;
  v_user_id  uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;

  IF p_slug IS NULL OR p_slug = '' THEN
    RAISE EXCEPTION 'p_slug required' USING ERRCODE = '22023';
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('healthy', 'degraded', 'down', 'unknown') THEN
    RAISE EXCEPTION 'Invalid p_status: % (allowed: healthy|degraded|down|unknown)', p_status
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_provider
  FROM   ai_provider_registry
  WHERE  slug = p_slug
  FOR    UPDATE;

  IF v_provider IS NULL THEN
    RAISE EXCEPTION 'Provider with slug % not found', p_slug USING ERRCODE = '22023';
  END IF;

  UPDATE ai_provider_registry
  SET    last_health_status     = p_status,
         last_health_checked_at = now(),
         last_health_detail     = LEFT(COALESCE(p_detail, ''), 500),
         -- Exponential-backoff counter: increment on non-healthy probes, reset
         -- on healthy. get_providers_due_health_probe reads this to extend
         -- the probe interval for persistently-failing providers (5min →
         -- 1h → 6h → 24h based on count).
         consecutive_failure_count = CASE
           WHEN p_status = 'healthy' THEN 0
           ELSE consecutive_failure_count + 1
         END,
         updated_at             = now()
  WHERE  slug = p_slug;

  -- Audit. Operators can query audit_journal for action='provider.health_probed'
  -- to see probe history (status transitions + latency trend) per provider.
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'provider.health_probed',
    jsonb_build_object(
      'slug',          p_slug,
      'backend_kind',  v_provider.backend_kind,
      'from_status',   v_provider.last_health_status,
      'to_status',     p_status,
      'latency_ms',    p_latency_ms,
      'detail',        LEFT(COALESCE(p_detail, ''), 200),
      'status_changed', (v_provider.last_health_status IS DISTINCT FROM p_status)
    )
  );

  RETURN jsonb_build_object(
    'slug',           p_slug,
    'from_status',    v_provider.last_health_status,
    'to_status',      p_status,
    'status_changed', (v_provider.last_health_status IS DISTINCT FROM p_status),
    'latency_ms',     p_latency_ms,
    'recorded_at',    now()
  );
END;
$$;

REVOKE ALL ON FUNCTION public.record_provider_health_result(text, text, int, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_provider_health_result(text, text, int, text) TO service_role;

COMMENT ON FUNCTION public.record_provider_health_result(text, text, int, text) IS
  'WF_PROVIDER_HEALTH_PROBE result-recording RPC — updates ai_provider_registry.last_health_* and audits status transitions. Service-role only.';


-- -----------------------------------------------------------------------------
