-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/register_plugin_event.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- register_plugin_event(p_plugin_id, p_event_kind, p_latency_ms, p_error, p_tenant_id, p_metadata)
-- =============================================================================
-- Records a health event after each plugin invocation.
-- Called by svc-plugin-system after every plugin run (invoke/error/timeout).
-- SECURITY DEFINER, service role only (was anon-callable until 2026-09-24).
-- =============================================================================

CREATE OR REPLACE FUNCTION public.register_plugin_event(
  p_error       text DEFAULT NULL,
  p_event_kind  text DEFAULT NULL,
  p_latency_ms  integer DEFAULT NULL,
  p_metadata    jsonb DEFAULT '{}'::jsonb,
  p_plugin_id   uuid DEFAULT NULL,
  p_tenant_id   uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_event_id uuid;
BEGIN
  -- ⛔ 2026-09-24: funkce byla povolená anon i authenticated („callable from edge
  -- functions running as anon") — kdokoli mohl podvrhnout telemetrii, ze které
  -- teď čte hlídač stavu zdrojů. Zapisuje JEN host pluginů (svc-plugin-system).
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'register_plugin_event: jen služba (svc-plugin-system)' USING ERRCODE = '42501';
  END IF;
  IF p_plugin_id IS NULL OR p_event_kind IS NULL THEN
    RAISE EXCEPTION 'p_plugin_id and p_event_kind are required';
  END IF;

  INSERT INTO public.plugin_health_events (
    plugin_id, tenant_id, event_kind, latency_ms, error_text, metadata
  ) VALUES (
    p_plugin_id,
    p_tenant_id,
    p_event_kind::public.plugin_health_event_kind,
    p_latency_ms,
    p_error,
    COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_event_id;

  RETURN jsonb_build_object(
    'event_id', v_event_id,
    'plugin_id', p_plugin_id,
    'event_kind', p_event_kind
  );
END;
$$;

COMMENT ON FUNCTION public.register_plugin_event(text, text, integer, jsonb, uuid, uuid) IS
  'Records a plugin health event (load/invoke/error/timeout). Called by plugin-host.';

REVOKE ALL ON FUNCTION public.register_plugin_event(text, text, integer, jsonb, uuid, uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.register_plugin_event(text, text, integer, jsonb, uuid, uuid) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.register_plugin_event(text, text, integer, jsonb, uuid, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/register_plugin_schedule.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- register_plugin_schedule — Register/update a cron-scheduled task for a plugin
-- Called by plugin-host when plugin calls SandboxContext.schedule()
-- ============================================================================
CREATE OR REPLACE FUNCTION public.register_plugin_schedule(
  p_cron_expr text DEFAULT NULL,
  p_enabled boolean DEFAULT true,
  p_handler_capability text DEFAULT NULL,
  p_plugin_id uuid DEFAULT NULL,
  p_tenant_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_schedule_id uuid;
BEGIN
  -- ⛔ NAMĚŘENO 2026-09-16: funkce byla SECURITY DEFINER, povolená KAŽDÉMU
  -- přihlášenému a bez kontroly nároku — kdokoli mohl zapsat rozvrh cizímu
  -- pluginu a tenantovi, a jakmile plánovač rozvrhy spouští, byla by to cesta
  -- k běhu pluginu nad daty cizího tenanta. Rozvrhy zapisuje host
  -- (reconcile_plugin_schedules); ručně jen služba nebo admin/staff.
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'register_plugin_schedule: jen služba nebo admin/staff' USING ERRCODE = '42501';
  END IF;
  IF p_plugin_id IS NULL OR p_tenant_id IS NULL OR p_handler_capability IS NULL THEN
    RAISE EXCEPTION 'plugin_id, tenant_id, and handler_capability are required';
  END IF;

  INSERT INTO public.plugin_schedules (plugin_id, tenant_id, cron_expr, handler_capability, enabled)
  VALUES (p_plugin_id, p_tenant_id, p_cron_expr, p_handler_capability, p_enabled)
  ON CONFLICT (plugin_id, tenant_id, handler_capability) DO UPDATE
    SET cron_expr = EXCLUDED.cron_expr,
        enabled = EXCLUDED.enabled,
        updated_at = now()
  RETURNING id INTO v_schedule_id;

  RETURN jsonb_build_object('schedule_id', v_schedule_id, 'ok', true);
END;
$$;

COMMENT ON FUNCTION public.register_plugin_schedule(text, boolean, text, uuid, uuid) IS 'Register or update a cron-scheduled task for a plugin.';

REVOKE ALL ON FUNCTION public.register_plugin_schedule(text, boolean, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.register_plugin_schedule(text, boolean, text, uuid, uuid) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/register_source_document_audited.sql
-- -----------------------------------------------------------------------------

-- Function: register_source_document_audited
-- Evidence layer (E3): registers one ingested document version. Service-role
-- only (NULL-safe is_service_role — deny-guard is total, #588 idiom). Rules:
--   * only an ACTIVE source may register documents (fail-closed onboarding),
--   * sensitivity is INHERITED from the source classification (never caller-supplied),
--   * idempotent on (source, content hash): replay returns the existing row.

CREATE OR REPLACE FUNCTION public.register_source_document_audited(
  p_source_slug text,
  p_source_sha256 text,
  p_doc_type text,
  p_title text DEFAULT NULL::text,
  p_doc_date date DEFAULT NULL::date,
  p_counterparty text DEFAULT NULL::text,
  p_metadata jsonb DEFAULT '{}'::jsonb
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_source public.agent_knowledge_sources%ROWTYPE;
  v_id uuid;
  v_registered boolean := true;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_source
  FROM public.agent_knowledge_sources
  WHERE source_slug = p_source_slug AND is_active;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown or inactive source' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.document_registry (
    source_id, source_sha256, doc_type, title, doc_date, counterparty, sensitivity, metadata
  )
  VALUES (
    v_source.id, p_source_sha256, p_doc_type, p_title, p_doc_date, p_counterparty,
    COALESCE(v_source.config->>'data_sensitivity', 'confidential'),  -- inherit; absent = most restrictive
    COALESCE(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (source_id, source_sha256) DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    v_registered := false;  -- idempotent replay
    SELECT id INTO v_id FROM public.document_registry
    WHERE source_id = v_source.id AND source_sha256 = p_source_sha256;
  END IF;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (auth.uid(), 'DOCUMENT_REGISTERED', 'DOCUMENT_REGISTERED', 'content', 'info',
          ARRAY['evidence', 'ingest'],
          jsonb_build_object('source_slug', p_source_slug, 'doc_type', p_doc_type,
                             'sha256', p_source_sha256, 'registered', v_registered));

  RETURN jsonb_build_object('id', v_id, 'registered', v_registered);
END;
$function$

;

REVOKE ALL ON FUNCTION register_source_document_audited(text,text,text,text,date,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION register_source_document_audited(text,text,text,text,date,text,jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/register_story_instance.sql
-- -----------------------------------------------------------------------------

-- Function: public.register_story_instance
-- Arguments: p_instance_label text, p_instance_type text, p_is_origin boolean, p_story_id uuid
-- Description: Registers a new instance (environment) for a story.
-- Security: SECURITY DEFINER — admin/staff only

CREATE OR REPLACE FUNCTION public.register_story_instance(
  p_instance_label text,
  p_instance_type text,
  p_is_origin boolean DEFAULT false,
  p_story_id uuid DEFAULT NULL
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_instance_id uuid;
  v_resolved_story_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff role required';
  END IF;

  v_resolved_story_id := p_story_id;

  IF p_is_origin AND EXISTS (
    SELECT 1 FROM story_instances
    WHERE story_id = v_resolved_story_id AND is_origin = true
  ) THEN
    RAISE EXCEPTION 'Origin instance already exists for story %', v_resolved_story_id;
  END IF;

  INSERT INTO story_instances (
    story_id, instance_label, instance_type, is_origin
  ) VALUES (
    v_resolved_story_id, p_instance_label, p_instance_type, p_is_origin
  ) RETURNING id INTO v_instance_id;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (v_user_id, 'STORY_INSTANCE_REGISTER', jsonb_build_object(
    'area', 'story_sync', 'severity', 'info',
    'entity_type', 'story_instance', 'entity_id', v_instance_id,
    'story_id', v_resolved_story_id,
    'instance_type', p_instance_type, 'is_origin', p_is_origin
  ));

  RETURN jsonb_build_object(
    'instance_id', v_instance_id,
    'story_id', v_resolved_story_id,
    'instance_label', p_instance_label,
    'instance_type', p_instance_type,
    'is_origin', p_is_origin
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.register_story_instance(text, text, boolean, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.register_story_instance(text, text, boolean, uuid) TO authenticated;


