-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/request_account_deletion.sql
-- -----------------------------------------------------------------------------

-- Request account deletion
-- This creates an account deletion request that will be processed within 30 days
-- User data is anonymized, not immediately deleted, for compliance

CREATE OR REPLACE FUNCTION request_account_deletion(
  p_reason TEXT DEFAULT NULL,
  p_feedback TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id UUID;
  v_user_email TEXT;
  v_request_id UUID;
  v_deletion_date TIMESTAMPTZ;
BEGIN
  -- Get current user
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  -- Get user email for confirmation
  SELECT email INTO v_user_email
  FROM aisha_auth.users
  WHERE id = v_user_id;
  
  -- Calculate deletion date (30 days from now for compliance)
  v_deletion_date := NOW() + INTERVAL '30 days';
  
  -- Check if there's already a pending deletion request
  IF EXISTS (
    SELECT 1 FROM account_deletion_requests
    WHERE user_id = v_user_id
    AND status = 'pending'
  ) THEN
    RAISE EXCEPTION 'Deletion request already pending';
  END IF;
  
  -- Create deletion request
  INSERT INTO account_deletion_requests (
    user_id,
    reason,
    feedback,
    requested_at,
    scheduled_deletion_at,
    status
  )
  VALUES (
    v_user_id,
    p_reason,
    p_feedback,
    NOW(),
    v_deletion_date,
    'pending'
  )
  RETURNING id INTO v_request_id;
  
  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'ACCOUNT_DELETION_REQUESTED',
    jsonb_build_object(
      'area', 'account',
      'severity', 'warning',
      'request_id', v_request_id,
      'scheduled_deletion_at', v_deletion_date
    )
  );
  
  RETURN jsonb_build_object(
    'success', TRUE,
    'request_id', v_request_id,
    'scheduled_deletion_at', v_deletion_date,
    'message', 'Account deletion scheduled'
  );
END;
$$;

-- Permissions
REVOKE ALL ON FUNCTION request_account_deletion(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION request_account_deletion(text, text) TO authenticated;

COMMENT ON FUNCTION request_account_deletion(text, text) IS 
'Creates an account deletion request. Account will be deleted after 30 days for compliance.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/request_rollback.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: request_rollback
-- Popis: Insert nový pending rollback request. Volat z WF_SENTRY_OBSERVER po
--        detekci threshold breach. Throttle: max 1 rollback request per app per 30 min
--        (proti spam-u). Loguje do audit_journal.
-- Volá: WF_SENTRY_OBSERVER po correlate_sentry_with_deploys returns rollback_recommended=true
-- Auth: service_role nebo admin/staff
-- ============================================================================

CREATE OR REPLACE FUNCTION public.request_rollback(
  p_app_name           text,
  p_triggered_by       text,
  p_sentry_correlation jsonb DEFAULT NULL,
  p_approval_id        uuid DEFAULT NULL,
  p_metadata           jsonb DEFAULT '{}'::jsonb
)
RETURNS public.rollback_history
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_slot_row public.coolify_app_slots;
  v_row      public.rollback_history;
  v_is_service boolean;
  v_throttle_minutes constant int := 30;
  v_recent_count int;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Throttle: max 1 rollback request per app per 30 min
  SELECT count(*) INTO v_recent_count
  FROM public.rollback_history
  WHERE app_name = p_app_name
    AND triggered_at > now() - (v_throttle_minutes || ' minutes')::interval
    AND approval_status NOT IN ('rejected', 'expired', 'aborted');

  IF v_recent_count > 0 THEN
    RAISE EXCEPTION 'Rollback request throttled for %: % minute window already has pending/active request',
      p_app_name, v_throttle_minutes;
  END IF;

  -- Resolve current slot state
  SELECT * INTO v_slot_row
  FROM public.coolify_app_slots
  WHERE app_name = p_app_name;

  IF v_slot_row IS NULL THEN
    RAISE EXCEPTION 'App slot not found: %', p_app_name;
  END IF;

  -- Insert pending rollback
  INSERT INTO public.rollback_history (
    app_name, triggered_by,
    from_slot, to_slot,
    from_image_tag, to_image_tag,
    sentry_correlation, approval_id,
    approval_status, metadata
  )
  VALUES (
    p_app_name, p_triggered_by,
    v_slot_row.active_slot,
    CASE v_slot_row.active_slot WHEN 'blue' THEN 'green' ELSE 'blue' END,
    CASE v_slot_row.active_slot WHEN 'blue' THEN v_slot_row.blue_image_tag ELSE v_slot_row.green_image_tag END,
    CASE v_slot_row.active_slot WHEN 'blue' THEN v_slot_row.green_image_tag ELSE v_slot_row.blue_image_tag END,
    p_sentry_correlation,
    p_approval_id,
    'pending',
    p_metadata
  )
  RETURNING * INTO v_row;

  -- Audit
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'rollback_requested',
    jsonb_build_object(
      'rollback_id', v_row.id,
      'app_name', p_app_name,
      'triggered_by', p_triggered_by,
      'from_slot', v_row.from_slot,
      'to_slot', v_row.to_slot
    )
  );

  RETURN v_row;
END;
$$;

REVOKE ALL ON FUNCTION public.request_rollback(text, text, jsonb, uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.request_rollback(text, text, jsonb, uuid, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.request_rollback(text, text, jsonb, uuid, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_playwright_result.sql
-- -----------------------------------------------------------------------------

-- record_playwright_result
-- Service-role only: runner posts final counts + report path after Chromium exits.
-- Status derives from counts: failed>0 → 'failed', else if total>0 → 'passed', else 'errored'.
--
-- Production integration (migration 20260518040000):
--  • App-linked runs (app_name+active_slot set): update coolify_app_slots.{slot}_health.
--  • staging_auto + failed/errored + app-linked → auto-call request_rollback() (throttled by SoT).
--  • Story-linked runs (story_id set): emit qa_playwright_passed | qa_playwright_failed entry.

CREATE OR REPLACE FUNCTION public.record_playwright_result(
  p_run_id uuid,
  p_total integer,
  p_passed integer,
  p_failed integer,
  p_skipped integer,
  p_duration_ms integer,
  p_report_storage_path text,
  p_trace_json_path text DEFAULT NULL,
  p_error_message text DEFAULT NULL,
  p_metadata jsonb DEFAULT NULL
)
RETURNS public.playwright_run_status
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean;
  v_status public.playwright_run_status;
  v_run record;
  v_rollback_id uuid;
  v_should_rollback boolean := false;
  v_health text;
  v_slot_col text;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service THEN
    RAISE EXCEPTION 'Unauthorized: service_role required';
  END IF;

  SELECT id, status, trigger_kind, target_env, app_name, active_slot, story_id, requested_by
  INTO v_run FROM public.playwright_runs WHERE id = p_run_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Run not found: %', p_run_id;
  END IF;
  IF v_run.status NOT IN ('queued', 'running') THEN
    RAISE EXCEPTION 'Run in terminal state (%), cannot record', v_run.status;
  END IF;

  -- Status derivation: explicit error message wins, then counts.
  IF p_error_message IS NOT NULL AND p_total IS NULL THEN
    v_status := 'errored';
  ELSIF p_failed IS NOT NULL AND p_failed > 0 THEN
    v_status := 'failed';
  ELSIF p_total IS NOT NULL AND p_total > 0 THEN
    v_status := 'passed';
  ELSE
    v_status := 'errored';
  END IF;

  -- Update slot health when run is app-linked. Passed → healthy, failed/errored → degraded.
  IF v_run.app_name IS NOT NULL AND v_run.active_slot IS NOT NULL THEN
    v_health := CASE v_status WHEN 'passed' THEN 'healthy' ELSE 'degraded' END;
    v_slot_col := v_run.active_slot || '_health';
    EXECUTE format(
      'UPDATE public.coolify_app_slots SET %I = %L, updated_at = now() WHERE app_name = %L',
      v_slot_col, v_health, v_run.app_name
    );
  END IF;

  -- Auto-rollback path: staging_auto + failed/errored + app linked → request_rollback().
  -- request_rollback throttles to one open request per app per 30 min; we soft-fail on throttle.
  v_should_rollback := (
    v_run.trigger_kind = 'staging_auto'
    AND v_status IN ('failed', 'errored')
    AND v_run.app_name IS NOT NULL
  );
  IF v_should_rollback THEN
    BEGIN
      SELECT (public.request_rollback(
        v_run.app_name,
        'playwright_staging_auto',
        jsonb_build_object('run_id', p_run_id, 'failed', p_failed, 'error_message', p_error_message),
        NULL,
        jsonb_build_object('source', 'WF_PLAYWRIGHT_RUN', 'target_env', v_run.target_env)
      )).id INTO v_rollback_id;
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO public.audit_journal (user_id, action, metadata) VALUES (
        NULL, 'PLAYWRIGHT_RUN_ROLLBACK_THROTTLED',
        jsonb_build_object(
          'area', 'qa', 'severity', 'warning', 'entity_type', 'playwright_run',
          'entity_id', p_run_id::text, 'app_name', v_run.app_name,
          'error', SQLERRM,
          'tags', ARRAY['stack', 'qa', 'playwright', 'rollback', 'throttled']
        )
      );
    END;
  END IF;

  UPDATE public.playwright_runs
  SET status = v_status,
      total = p_total,
      passed = p_passed,
      failed = p_failed,
      skipped = p_skipped,
      duration_ms = p_duration_ms,
      report_storage_path = p_report_storage_path,
      trace_json_path = p_trace_json_path,
      error_message = p_error_message,
      metadata = COALESCE(metadata, '{}'::jsonb) || COALESCE(p_metadata, '{}'::jsonb),
      triggered_rollback_id = v_rollback_id,
      finished_at = now()
  WHERE id = p_run_id;

  -- Story entries: pass / fail block (mirrors web_artifact_applied / web_artifact_failed shape).
  IF v_run.story_id IS NOT NULL THEN
    INSERT INTO public.story_entries (story_id, entry_type, content, metadata, created_by)
    VALUES (
      v_run.story_id,
      CASE v_status WHEN 'passed' THEN 'qa_playwright_passed' ELSE 'qa_playwright_failed' END,
      NULL,
      jsonb_build_object(
        'type', CASE v_status WHEN 'passed' THEN 'qa_playwright_passed' ELSE 'qa_playwright_failed' END,
        'run_id', p_run_id,
        'result_status', v_status::text,
        'total', p_total, 'passed', p_passed, 'failed', p_failed, 'skipped', p_skipped,
        'duration_ms', p_duration_ms,
        'report_storage_path', p_report_storage_path,
        'error_message', p_error_message,
        'app_name', v_run.app_name,
        'active_slot', v_run.active_slot,
        'rollback_id', v_rollback_id
      ),
      NULL
    );
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    NULL,
    'PLAYWRIGHT_RUN_RESULT',
    jsonb_build_object(
      'area', 'qa',
      'severity', CASE WHEN v_status IN ('failed', 'errored') THEN 'warning' ELSE 'info' END,
      'entity_type', 'playwright_run',
      'entity_id', p_run_id::text,
      'trigger_kind', v_run.trigger_kind::text,
      'target_env', v_run.target_env,
      'app_name', v_run.app_name,
      'active_slot', v_run.active_slot,
      'story_id', v_run.story_id,
      'result_status', v_status::text,
      'counts', jsonb_build_object('total', p_total, 'passed', p_passed, 'failed', p_failed, 'skipped', p_skipped),
      'duration_ms', p_duration_ms,
      'triggered_rollback', v_rollback_id IS NOT NULL,
      'rollback_id', v_rollback_id,
      'tags', ARRAY['stack', 'qa', 'playwright', 'result', v_status::text]
    )
  );

  RETURN v_status;
END;
$$;

REVOKE ALL ON FUNCTION public.record_playwright_result(uuid, integer, integer, integer, integer, integer, text, text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_playwright_result(uuid, integer, integer, integer, integer, integer, text, text, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/request_web_artifact_redesign.sql
-- -----------------------------------------------------------------------------

-- request_web_artifact_redesign
-- Spawns a new redesign job seeded from an existing ready_for_review job's canvas.
-- Authz: admin/staff OR story participant.

CREATE OR REPLACE FUNCTION public.request_web_artifact_redesign(
  p_job_id uuid,
  p_brief text,
  p_slot_profile text DEFAULT 'balanced',
  p_creativity_seed numeric DEFAULT 0.5
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
  v_source_job record;
  v_new_job_id uuid;
  v_idempotency_key text;
BEGIN
  SELECT id, story_id, result_canvas_data, status, kind
  INTO v_source_job
  FROM public.web_artifact_jobs
  WHERE id = p_job_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Source job not found: %', p_job_id;
  END IF;

  IF v_source_job.status NOT IN ('ready_for_review', 'approved', 'applied') THEN
    RAISE EXCEPTION 'Source job must be ready_for_review/approved/applied (got %)', v_source_job.status;
  END IF;

  IF v_source_job.result_canvas_data IS NULL THEN
    RAISE EXCEPTION 'Source job has no result canvas to seed redesign from';
  END IF;

  IF NOT public.is_admin_or_staff()
     AND (v_source_job.story_id IS NULL OR NOT public.is_story_participant(auth.uid(), v_source_job.story_id))
  THEN
    RAISE EXCEPTION 'Unauthorized: admin/staff or story participant required';
  END IF;

  IF p_slot_profile NOT IN ('budget', 'balanced', 'maxQuality') THEN
    RAISE EXCEPTION 'slot_profile must be budget | balanced | maxQuality';
  END IF;

  v_idempotency_key := encode(digest(
    'llm_redesign|' || p_job_id::text || '|' || COALESCE(p_brief, '') || '|' || p_slot_profile || '|' || now()::text,
    'sha256'
  ), 'hex');

  INSERT INTO public.web_artifact_jobs (
    story_id, kind, source_type, status,
    seed_canvas_data, brief, slot_profile, creativity_seed,
    idempotency_key, created_by, metadata
  ) VALUES (
    v_source_job.story_id,
    'redesign',
    'llm_redesign',
    'pending',
    v_source_job.result_canvas_data,
    p_brief,
    p_slot_profile,
    p_creativity_seed,
    v_idempotency_key,
    auth.uid(),
    jsonb_build_object('source_job_id', p_job_id::text)
  )
  RETURNING id INTO v_new_job_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'WEB_ARTIFACT_REDESIGN_REQUEST',
    jsonb_build_object(
      'area', 'content',
      'severity', 'info',
      'entity_type', 'web_artifact_job',
      'entity_id', v_new_job_id::text,
      'story_id', v_source_job.story_id,
      'kind', 'redesign',
      'source_job_id', p_job_id::text,
      'slot_profile', p_slot_profile,
      'tags', ARRAY['stack', 'story', 'web_artifact', 'redesign']
    )
  );

  RETURN v_new_job_id;
END;
$$;

REVOKE ALL ON FUNCTION public.request_web_artifact_redesign(uuid, text, text, numeric) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.request_web_artifact_redesign(uuid, text, text, numeric) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/requeue_stale_proactive_runs.sql
-- -----------------------------------------------------------------------------

-- Function: requeue_stale_proactive_runs
-- Běh zabraný executorem, který se nedokončil (worker spadl mezi claim a finish),
-- by zůstal `running` napořád a akce by se nikdy nestala. Po `p_stale_seconds` ho
-- tahle funkce vrátí do `pending` — dohnání ho vezme znovu.
--
-- ⛔ Ne donekonečna: běh, na kterém executor padá opakovaně, by se vracel v kruhu.
-- Po `p_max_attempts` zabráních končí `failed` se stopou v `error_message` — je to
-- nález k přečtení, ne smyčka. `attempts` počítá claim_proactive_run(s).
--
-- Jen běhy kanálů volajícího (cizí `running` z jiných executorů se nesmí vracet).

CREATE OR REPLACE FUNCTION public.requeue_stale_proactive_runs(
  p_channels      text[],
  p_stale_seconds integer DEFAULT 600,
  p_max_attempts  integer DEFAULT 5
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_out jsonb;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;

  WITH s AS (
    SELECT r.id, coalesce((r.metadata ->> 'attempts')::int, 1) AS attempts
      FROM ai_proactive_runs r
      JOIN ai_proactive_trigger_definitions d ON d.id = r.trigger_definition_id
     WHERE r.status = 'running'
       AND r.started_at < now() - make_interval(secs => greatest(coalesce(p_stale_seconds, 600), 1))
       AND (d.action_config ->> 'channel') = ANY (p_channels)
     FOR UPDATE OF r SKIP LOCKED
  ), f AS (
    UPDATE ai_proactive_runs r
       SET status        = 'failed',
           completed_at  = now(),
           error_message = format('stale: executor běh %s× zabral a nedokončil', s.attempts)
      FROM s
     WHERE r.id = s.id
       AND s.attempts >= greatest(coalesce(p_max_attempts, 5), 1)
    RETURNING r.id
  ), q AS (
    UPDATE ai_proactive_runs r
       SET status     = 'pending',
           started_at = NULL,
           metadata   = coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object('requeued_at', now())
      FROM s
     WHERE r.id = s.id
       AND s.attempts < greatest(coalesce(p_max_attempts, 5), 1)
    RETURNING r.id
  )
  SELECT jsonb_build_object(
           'requeued', (SELECT count(*) FROM q),
           'failed',   (SELECT count(*) FROM f))
    INTO v_out;

  RETURN v_out;
END;
$function$;

REVOKE ALL ON FUNCTION public.requeue_stale_proactive_runs(text[], integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.requeue_stale_proactive_runs(text[], integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/resolve_brand_for_hostname.sql
-- -----------------------------------------------------------------------------

-- resolve_brand_for_hostname — inbound hostname → id značky (branding_profiles.id).
--
-- ⛔ JEDNO ROZLIŠENÍ ZNAČKY PRO VŠECHNY ČTEČKY WEBU. Stejný dotaz byl dřív
-- vepsaný ve čtyřech funkcích (get_branding_for_hostname, get_web_page_by_slug,
-- get_published_web_page_index, get_published_web_partials) a kopie se
-- rozešly: get_branding_for_hostname dostal 2026-06-01 opravu „rozlišuj podle
-- mapování bez ohledu na status", tři čtečky stránek ji nedostaly.
--
-- Změřený důsledek (2026-09-19, instance se čtyřmi značkami): platforma smí mít
-- publikovanou JEN JEDNU značku bez partnera (výchozí resolver
-- get_branding_profile by jinak vybíral podle pořadí publikace), ostatní jsou
-- 'draft' ZÁMĚRNĚ a dosažitelné jen přes branding_hostname_mapping. Čtečky
-- stránek ale filtrovaly `bp.status = 'published'`, takže pro tři ze čtyř
-- hostnamů vrátily NULL → globální stránky. Téma se přitom načetlo správně
-- (get_branding_for_hostname) — výsledkem byl web v barvách jedné značky
-- s obsahem jiné. Žádná chyba, jen tiše špatný web.
--
-- Pravidlo: řádek mapování JE rozhodnutí operátora „na tomhle hostname
-- servíruj tuhle značku". Status profilu určuje jen výchozí značku pro
-- nenamapované hostnamy, ne dosažitelnost namapovaných. Stránky samotné dál
-- hlídá jejich vlastní `web_pages.status = 'published'`.
--
-- ⛔ NEJMENŠÍ OPRÁVNĚNÍ: SECURITY INVOKER a EXECUTE jen pro service_role.
-- Všichni čtyři konzumenti jsou SECURITY DEFINER, takže vnořené volání běží
-- s právy vlastníka a anon/authenticated pomocníka volat NEPOTŘEBUJÍ. Jako
-- DEFINER s grantem pro anon by ho PostgREST vystavil jako další veřejné RPC
-- s definer právy — přesně třída, kterou core odstraňuje. Hlídá to brána
-- web-znacka-podle-mapovani (anon EXECUTE = false a čtečky pro anon fungují).
CREATE OR REPLACE FUNCTION public.resolve_brand_for_hostname(p_hostname text)
RETURNS uuid
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public'
AS $$
  SELECT m.branding_profile_id
  FROM public.branding_hostname_mapping m
  WHERE p_hostname IS NOT NULL
    AND length(trim(p_hostname)) > 0
    AND lower(m.hostname) = lower(trim(p_hostname))
  LIMIT 1;
$$;

REVOKE ALL ON FUNCTION public.resolve_brand_for_hostname(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.resolve_brand_for_hostname(text) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_brand_for_hostname(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_branding_for_hostname.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- Function: get_branding_for_hostname — hostname → mapped branding profile
-- =============================================================================
-- Resolves a request hostname (e.g. window.location.hostname from the SPA)
-- to its mapped branding profile via the branding_hostname_mapping table.
-- The mapping row is the authority — the profile resolves by id regardless of
-- its draft/published status (see the WHERE clause below for the multi-brand
-- rationale).
--
-- Use case: multi-brand single-instance deployments. A single SPA bundle
-- serves multiple hostnames (e.g. umbrella.example.com → umbrella brand,
-- therapy.example.com → therapy-first brand). The frontend calls this RPC during
-- bootstrap to pick the correct theme + landing route before first paint.
--
-- Return shape (jsonb):
--   {
--     "status": "ok",
--     "brand_variant": "umbrella" | "therapy-first",
--     "primary_route":   text | null,   -- default landing for this hostname
--     "secondary_route": text | null,   -- alternate route the brand exposes
--     "profile": { ...branding_profiles row... }
--   }
--
-- Returns NULL when:
--   - Hostname has no row in branding_hostname_mapping, OR
--   - The mapping references a branding_profile id that no longer exists.
-- Caller falls back to the global default brand via get_branding_profile().
--
-- Caller is ALWAYS anon (this fires before login). Hence SECURITY DEFINER
-- + EXECUTE grant to anon — branding is intentionally public.
-- =============================================================================

CREATE OR REPLACE FUNCTION public.get_branding_for_hostname(p_hostname text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_brand_id uuid;
  v_mapping RECORD;
  v_profile jsonb;
BEGIN
  -- Značka podle hostname: JEDEN resolver pro všechny čtyři čtečky (tahle +
  -- get_web_page_by_slug, get_published_web_page_index, get_published_web_partials).
  -- Mapování je autorita, status profilu ne — viz resolve_brand_for_hostname.
  v_brand_id := public.resolve_brand_for_hostname(p_hostname);
  IF v_brand_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Nápovědy rout téhož řádku mapování (hostname je PK; táž normalizace
  -- jako v resolveru, jinak by se id a nápovědy mohly vzít z různých řádků).
  SELECT brand_variant, primary_route, secondary_route
    INTO v_mapping
  FROM public.branding_hostname_mapping
  WHERE lower(hostname) = lower(trim(p_hostname))
  LIMIT 1;

  -- Build the same profile shape as get_branding_profile produces, but
  -- selected by branding_profile_id directly (not partner_id).
  SELECT jsonb_build_object(
    'id', bp.id,
    'partner_id', bp.partner_id,
    'status', bp.status,
    'color_primary', bp.color_primary,
    'color_secondary', bp.color_secondary,
    'color_accent', bp.color_accent,
    'color_background', bp.color_background,
    'color_foreground', bp.color_foreground,
    'color_muted', bp.color_muted,
    'color_surface', bp.color_surface,
    'color_destructive', bp.color_destructive,
    'dark_color_primary', bp.dark_color_primary,
    'dark_color_background', bp.dark_color_background,
    'dark_color_foreground', bp.dark_color_foreground,
    'dark_color_surface', bp.dark_color_surface,
    'dark_color_muted', bp.dark_color_muted,
    'font_family_brand', bp.font_family_brand,
    'font_family_body', bp.font_family_body,
    'font_family_code', bp.font_family_code,
    'font_faces', bp.font_faces,
    'logo_path', bp.logo_path,
    'logo_dark_path', bp.logo_dark_path,
    'favicon_path', bp.favicon_path,
    'login_logo_path', bp.login_logo_path,
    'operator_name', bp.operator_name,
    'operator_email', bp.operator_email,
    'operator_phone', bp.operator_phone,
    'operator_address', bp.operator_address,
    'operator_url', bp.operator_url,
    'email_header_bg', bp.email_header_bg,
    'email_footer_text', bp.email_footer_text,
    'login_background_color', bp.login_background_color,
    'login_card_bg', bp.login_card_bg,
    'login_accent_color', bp.login_accent_color,
    'profile_version', bp.profile_version,
    'updated_at', bp.updated_at,
    'published_at', bp.published_at
  )
    INTO v_profile
  FROM public.branding_profiles bp
  WHERE bp.id = v_brand_id
  -- Resolve by mapping id REGARDLESS of bp.status. The branding_hostname_mapping
  -- row is the explicit operator decision "serve this brand on this hostname" —
  -- it is the gate, not the profile's draft/published label.
  --
  -- Required by the multi-brand-per-instance model: only ONE platform-level
  -- brand (partner_id IS NULL) may be 'published', because get_branding_profile
  -- (the default resolver) would otherwise pick non-deterministically between
  -- two published NULL-partner rows. The SECONDARY brand is therefore kept
  -- 'draft' ON PURPOSE and reached purely via its hostname mapping.
  --
  -- MĚŘENO: filtrování na status='published' tady tiše zahodilo KAŽDOU
  -- sekundární značku — hostname na ni namapovaný se vyhodnotil na NULL
  -- a spadl zpátky na zastřešující značku. Vada se neprojevila chybou,
  -- jen "špatnou značkou". Viz migraci
  -- 20260601120000_branding_hostname_resolve_by_id pro plné odůvodnění.
  LIMIT 1;

  IF v_profile IS NULL THEN
    -- Mapping references a profile id that no longer exists — caller falls back
    -- to the global default brand via get_branding_profile().
    RETURN NULL;
  END IF;

  -- Compose the result: profile object + hostname-mapping metadata at top level.
  RETURN jsonb_build_object(
    'status', 'ok',
    'brand_variant', v_mapping.brand_variant,
    'primary_route', v_mapping.primary_route,
    'secondary_route', v_mapping.secondary_route,
    'profile', v_profile
  );
END;
$$;

COMMENT ON FUNCTION public.get_branding_for_hostname(text) IS
  'Resolve hostname → mapped branding profile via branding_hostname_mapping. '
  'Resolves by mapping id regardless of profile status (the mapping is the '
  'authority; secondary multi-brand profiles are kept draft so the default '
  'resolver stays deterministic). Returns NULL only when the hostname is '
  'unmapped or the mapped profile id is gone (caller falls back to global '
  'default). SECURITY DEFINER + anon grant — branding is public (pre-login).';

GRANT EXECUTE ON FUNCTION public.get_branding_for_hostname(text)
  TO anon, authenticated, service_role;

-- Upstream 2026-05-26: revoke PUBLIC grant (per-role grants below)
REVOKE ALL ON FUNCTION public.get_branding_for_hostname(text) FROM PUBLIC;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_published_web_page_index.sql
-- -----------------------------------------------------------------------------

-- get_published_web_page_index — seznam publikovaných stránek pro daný hostname
-- plus razítko poslední změny.
--
-- PROČ EXISTUJE (2026-08-30). Veřejný web je dnes prázdná SPA skořápka:
-- návštěvník stáhne 3,5 MB JS, teprve pak se aplikace zeptá na obsah stránky.
-- Generátor statických stránek to obrací — HTML publikované stránky vyrobí
-- dopředu, takže první vykreslení JE hotový design. K tomu potřebuje dvě věci,
-- které dosud žádná veřejná RPC nedávala:
--
--   1) SEZNAM slugů, které má vygenerovat. `get_web_page_by_slug` umí jednu
--      stránku podle jména — generátor ale jména předem nezná a hádat je
--      (natvrdo vepsaný výčet) by znamenalo, že nová stránka z editoru se
--      na webu nikdy neobjeví.
--   2) RAZÍTKO `max(updated_at)` jako levnou kontrolu čerstvosti. Generátor
--      se jím ptá „změnilo se něco?" místo aby tahal obsah všech stránek;
--      je to záchytná síť pro případ, že se ztratí push signál z editoru.
--
-- Přístupová třída je TÁŽ jako u get_web_page_by_slug: vrací jen slugy stránek,
-- které jsou UŽ TEĎ veřejně čitelné. Nepřidává tedy žádnou novou expozici —
-- kdo si může vyžádat obsah, může si vyžádat i seznam. Proto anon, a proto
-- žádná autorizační stráž nad rámec filtru `status = 'published'`.
--
-- Na čtecí cestě se ZÁMĚRNĚ neaudituje: audit per request by z levné kontroly
-- čerstvosti udělal zapisující transakci každých pár sekund.
CREATE OR REPLACE FUNCTION public.get_published_web_page_index(p_hostname text DEFAULT NULL)
RETURNS TABLE (
  slug text,
  updated_at timestamptz
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_brand_id uuid;
BEGIN
  -- Táž logika jako get_web_page_by_slug (sdílený resolver), aby generátor
  -- dostal PRÁVĚ TY stránky, které týž hostname pak servíruje.
  v_brand_id := public.resolve_brand_for_hostname(p_hostname);

  -- DISTINCT ON (slug) + týž ORDER BY jako v get_web_page_by_slug: když
  -- existuje značková i globální varianta téhož slugu, vyhrává značková.
  -- Bez toho by generátor vyrobil stránku z jednoho řádku a runtime by
  -- servíroval druhý — dvě pravdy o téže adrese.
  RETURN QUERY
  SELECT DISTINCT ON (wp.slug)
    wp.slug,
    wp.updated_at
  FROM web_pages wp
  WHERE wp.status = 'published'
    AND wp.is_active = true
    -- ⛔ ÚTRŽEK NENÍ STRÁNKA. Hlavička a patička žijí v `web_pages` se
    -- `page_settings->>'role' = 'partial'`, aby je šlo editovat týmž editorem.
    -- Bez tohohle filtru by se servírovaly jako samostatné adresy (/nav/)
    -- a generátor by jim vyráběl vlastní soubory — tedy hlavička bez stránky.
    AND coalesce(wp.page_settings->>'role', '') <> 'partial'
    AND (
      wp.branding_profile_id = v_brand_id
      OR wp.branding_profile_id IS NULL
    )
  ORDER BY wp.slug, (wp.branding_profile_id IS NOT NULL) DESC;
END;
$$;

REVOKE ALL ON FUNCTION public.get_published_web_page_index(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_published_web_page_index(text) TO anon;
GRANT EXECUTE ON FUNCTION public.get_published_web_page_index(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_published_web_page_index(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_published_web_partials.sql
-- -----------------------------------------------------------------------------

-- Sdílené útržky (hlavička, patička) publikovaného webu.
--
-- ⛔ PROČ VLASTNÍ FUNKCE A NE SLOUPEC V `get_web_page_by_slug`. Útržek NENÍ
-- vlastnost stránky — je to obsah sdílený VŠEMI stránkami. Vracet ho u každé
-- stránky zvlášť by znamenalo přenášet tutéž hlavičku pokaždé, tedy přesně tu
-- duplikaci, kterou útržky ruší (naměřeno 2026-08-30: hlavička byla zkopírovaná
-- v 10 plátnech a na `news` se už rozešla, aniž to kdo chtěl).
--
-- Útržek je `web_pages` se `page_settings->>'role' = 'partial'`: týž editor,
-- totéž plátno, tytéž i18n klíče — jen se neservíruje jako samostatná stránka.
--
-- ⛔ ROZLIŠENÍ ZNAČKY JE POVINNÉ. Táž logika jako v `get_published_web_page_index`
-- a `get_web_page_by_slug`: bez ní by vícemznačková instance dostala do hlavičky
-- cizí navigaci — tedy tiše špatný web, ne chybu.
CREATE OR REPLACE FUNCTION public.get_published_web_partials(p_hostname text DEFAULT NULL)
RETURNS TABLE (
  ref text,
  canvas_html text,
  canvas_css text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_brand_id uuid;
BEGIN
  -- Značka podle hostname: sdílený resolve_brand_for_hostname — mapování je
  -- autorita, status profilu ne (viz komentář v té funkci, 2026-09-19).
  v_brand_id := public.resolve_brand_for_hostname(p_hostname);

  -- DISTINCT ON (slug) + týž ORDER BY jako u stránek: existuje-li značková
  -- i globální varianta téhož útržku, vyhrává značková. Jinak by generátor
  -- vzal jeden řádek a prohlížeč druhý — dvě pravdy o téže hlavičce.
  RETURN QUERY
  SELECT DISTINCT ON (wp.slug)
    wp.slug AS ref,
    wp.canvas_html,
    wp.canvas_css
  FROM web_pages wp
  WHERE wp.status = 'published'
    AND wp.is_active = true
    AND wp.page_settings->>'role' = 'partial'
    AND (
      wp.branding_profile_id = v_brand_id
      OR wp.branding_profile_id IS NULL
    )
  ORDER BY wp.slug, (wp.branding_profile_id IS NOT NULL) DESC;
END;
$$;

REVOKE ALL ON FUNCTION public.get_published_web_partials(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_published_web_partials(text) TO anon;
GRANT EXECUTE ON FUNCTION public.get_published_web_partials(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_published_web_partials(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_web_page_by_slug.sql
-- -----------------------------------------------------------------------------

-- Function: public.get_web_page_by_slug
-- Description: Returns a single published page for public rendering (anon access).
--   Multi-site: p_hostname resolves → brand via branding_hostname_mapping and
--   prefers the brand page over the global fallback. p_hostname DEFAULTs NULL so
--   a caller may omit it entirely (global page) — a single function serves both
--   the one-arg (global) and two-arg (brand-scoped) call forms, so there is no
--   overload ambiguity and no required-param mismatch for the one-arg callers.
-- Security: SECURITY DEFINER, anon + authenticated
-- Created: 2026-04-11

CREATE OR REPLACE FUNCTION public.get_web_page_by_slug(p_slug text, p_hostname text DEFAULT NULL)
RETURNS TABLE (
  id uuid,
  slug text,
  title_key text,
  description_key text,
  canvas_data jsonb,
  canvas_html text,
  canvas_css text,
  og_image_url text,
  page_settings jsonb
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
DECLARE
  v_brand_id uuid;
BEGIN
  -- Značka podle hostname: sdílený resolve_brand_for_hostname — mapování je
  -- autorita, status profilu ne (viz komentář v té funkci, 2026-09-19).
  v_brand_id := public.resolve_brand_for_hostname(p_hostname);

  RETURN QUERY
  SELECT
    wp.id,
    wp.slug,
    wp.title_key,
    wp.description_key,
    wp.canvas_data,
    wp.canvas_html,
    wp.canvas_css,
    wp.og_image_url,
    wp.page_settings
  FROM web_pages wp
  WHERE wp.slug = p_slug
    AND wp.status = 'published'
    AND wp.is_active = true
    -- ⛔ ÚTRŽEK NENÍ STRÁNKA. Hlavička a patička žijí v `web_pages` se
    -- `page_settings->>'role' = 'partial'`, aby je šlo editovat týmž editorem.
    -- Bez tohohle filtru by se servírovaly jako samostatné adresy (/nav/)
    -- a generátor by jim vyráběl vlastní soubory — tedy hlavička bez stránky.
    AND coalesce(wp.page_settings->>'role', '') <> 'partial'
    AND (
      wp.branding_profile_id = v_brand_id
      OR wp.branding_profile_id IS NULL
    )
  -- Prefer the brand-specific row over the global fallback.
  ORDER BY (wp.branding_profile_id IS NOT NULL) DESC
  LIMIT 1;
END;
$$;

REVOKE ALL ON FUNCTION public.get_web_page_by_slug(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_web_page_by_slug(text, text) TO anon;
GRANT EXECUTE ON FUNCTION public.get_web_page_by_slug(text, text) TO authenticated;
-- service_role: boot-time /seed-default's per-page idempotency check resolves
-- the (slug, hostname) brand page as service_role before deciding to re-seed.
GRANT EXECUTE ON FUNCTION public.get_web_page_by_slug(text, text) TO service_role;

-- No separate one-arg overload: p_hostname DEFAULT NULL lets the single function
-- serve the global (one-arg) call form directly. A distinct get_web_page_by_slug(text)
-- would make a one-arg call ambiguous, so it is deliberately not defined.


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/resolve_deployed_url.sql
-- -----------------------------------------------------------------------------

-- resolve_deployed_url
-- Helper: maps coolify_app_slots.app_name → the live slot's URL + identity.
-- Used by start_playwright_run when caller passes p_app_name + p_target_base_url='auto'
-- so the runner always hits the slot that is actively serving traffic right now.
--
-- Returns NULL target_base_url when the app has no domain configured — caller decides
-- whether that's fatal (production_manual) or an explicit URL override path.
--
-- SECURITY: function is SECURITY DEFINER so it can bypass coolify_app_slots RLS
-- (which gates reads to admin-or-staff). The auth check below replicates that
-- gate inside the function so non-admin authenticated users cannot leak
-- B/G slot topology via this helper. service_role calls (n8n WF_PLAYWRIGHT_RUN)
-- bypass the check because they're trusted infrastructure callers.

CREATE OR REPLACE FUNCTION public.resolve_deployed_url(p_app_name text)
RETURNS TABLE (target_base_url text, active_slot text, blue_app_uuid text, green_app_uuid text)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required to resolve deployed URL'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    CASE
      WHEN s.domain IS NULL OR s.domain = '' THEN NULL
      WHEN s.domain LIKE 'http%://%'         THEN s.domain
      ELSE 'https://' || s.domain
    END AS target_base_url,
    s.active_slot,
    s.blue_app_uuid,
    s.green_app_uuid
  FROM public.coolify_app_slots s
  WHERE s.app_name = p_app_name
  LIMIT 1;
END;
$$;

REVOKE ALL ON FUNCTION public.resolve_deployed_url(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.resolve_deployed_url(text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/resolve_drift.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: resolve_drift
-- Popis: Označí drift jako resolved. Volat po úspěšné remediation
--        (auto, approved, manual) nebo pro ignored drift. Loguje do audit_journal.
-- Volá: WF_DRIFT_OBSERVER (po auto-fix) nebo admin manuálně
-- Auth: service_role nebo admin/staff
-- ============================================================================

CREATE OR REPLACE FUNCTION public.resolve_drift(
  p_drift_id        uuid,
  p_remediation     text,
  p_resolution_note text DEFAULT NULL
)
RETURNS public.drift_state
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row public.drift_state;
  v_is_service boolean;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required' USING ERRCODE = '22023';
  END IF;

  IF p_remediation NOT IN ('auto', 'approved', 'manual', 'ignored') THEN
    RAISE EXCEPTION 'Invalid remediation: % (must be auto, approved, manual, ignored)', p_remediation USING ERRCODE = '22023';
  END IF;

  UPDATE public.drift_state
  SET remediation     = p_remediation,
      resolved_at     = now(),
      resolved_by     = auth.uid(),
      resolution_note = COALESCE(p_resolution_note, resolution_note)
  WHERE id = p_drift_id
    AND resolved_at IS NULL
  RETURNING * INTO v_row;

  IF v_row IS NULL THEN
    RAISE EXCEPTION 'Drift % not found or already resolved', p_drift_id USING ERRCODE = '22023';
  END IF;

  -- Audit
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'drift_resolved',
    jsonb_build_object(
      'drift_id', p_drift_id,
      'app_name', v_row.app_name,
      'drift_kind', v_row.drift_kind,
      'remediation', p_remediation,
      'risk_level', v_row.risk_level
    )
  );

  RETURN v_row;
END;
$$;

REVOKE ALL ON FUNCTION public.resolve_drift(uuid, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.resolve_drift(uuid, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_drift(uuid, text, text) TO service_role;


