-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/respond_to_escalation_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.respond_to_escalation_admin
-- Arguments: p_escalation_id uuid, p_response text, p_new_status text
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:28:01+01:00

CREATE OR REPLACE FUNCTION public.respond_to_escalation_admin(p_escalation_id uuid, p_response text, p_new_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_partner_id UUID;
BEGIN
  -- Get the partner_id for this escalation and verify access
  SELECT me.partner_id INTO v_partner_id
  FROM message_escalations me
  WHERE me.id = p_escalation_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Escalation not found';
  END IF;

  -- Verify the user is the partner or admin
  IF NOT EXISTS (
    SELECT 1 FROM partner_profiles pp
    WHERE pp.id = v_partner_id AND pp.user_id = v_user_id
  ) AND NOT is_admin_or_staff(v_user_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  UPDATE message_escalations SET
    partner_response = p_response,
    partner_responded_at = NOW(),
    status = p_new_status,
    resolved_at = CASE WHEN p_new_status = 'resolved' THEN NOW() ELSE NULL END,
    updated_at = NOW()
  WHERE id = p_escalation_id;

  -- Log to audit journal
  INSERT INTO audit_journal (
    user_id, action_type, area, entity_type, entity_id, summary, severity
  ) VALUES (
    v_user_id, 'update', 'partner', 'message_escalation', p_escalation_id,
    'Partner responded to escalation, new status: ' || p_new_status, 'info'
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.respond_to_escalation_admin(p_escalation_id uuid, p_response text, p_new_status text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.respond_to_escalation_admin(p_escalation_id uuid, p_response text, p_new_status text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/restore_web_page_version.sql
-- -----------------------------------------------------------------------------

-- Function: public.restore_web_page_version
-- Description: Restores a web page to a previous version snapshot (auto-snapshots current state first).
-- Security: SECURITY INVOKER, authenticated only, admin/staff check inside
-- Created: 2026-04-14

CREATE OR REPLACE FUNCTION public.restore_web_page_version(
  p_page_id uuid,
  p_version_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_version record;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Get version data
  SELECT canvas_data, canvas_html, canvas_css, page_settings
  INTO v_version
  FROM public.web_page_versions
  WHERE id = p_version_id AND page_id = p_page_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Version not found';
  END IF;

  -- Create snapshot of current state before restore
  PERFORM public.create_web_page_version(p_page_id, 'auto: before restore');

  -- Apply version
  UPDATE public.web_pages
  SET canvas_data = v_version.canvas_data,
      canvas_html = v_version.canvas_html,
      canvas_css = v_version.canvas_css,
      page_settings = v_version.page_settings,
      updated_at = now()
  WHERE id = p_page_id;

  -- Audit log
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'PAGE_VERSION_RESTORE',
    jsonb_build_object(
      'area', 'web_pages',
      'severity', 'warning',
      'entity_type', 'web_page_version',
      'entity_id', p_version_id::text,
      'page_id', p_page_id::text
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION public.restore_web_page_version(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.restore_web_page_version(uuid, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/retry_pending_blockchain_syncs.sql
-- -----------------------------------------------------------------------------

-- Function: retry_pending_blockchain_syncs
-- Dispatcher RPC: picks queued/failed items ready for retry, marks as dispatched.
-- Called by blockchain-dispatch edge function.
-- Uses FOR UPDATE SKIP LOCKED for concurrent-safe consumption.
--
-- Returns: array of records to dispatch to RabbitMQ

CREATE OR REPLACE FUNCTION public.retry_pending_blockchain_syncs(
  p_batch_size integer DEFAULT 20
)
  RETURNS SETOF blockchain_audit_records
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
BEGIN
  -- Auth check: service_role only (called from blockchain-dispatch EF)
  IF public.get_jwt_role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role required'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  WITH batch AS (
    SELECT id
    FROM blockchain_audit_records
    WHERE status IN ('queued', 'failed')
      AND (next_retry_at IS NULL OR next_retry_at <= now())
      AND retry_count < max_attempts
    ORDER BY created_at ASC
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  )
  UPDATE blockchain_audit_records bar
  SET
    status = 'dispatched',
    updated_at = now()
  FROM batch
  WHERE bar.id = batch.id
  RETURNING bar.*;
END;
$function$;

REVOKE ALL ON FUNCTION retry_pending_blockchain_syncs(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION retry_pending_blockchain_syncs(integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/revert_broker_quarantine_discard_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: revert_broker_quarantine_discard_admin
-- Popis: Vrátí zahození karantény — odložené balíčky se do seznamu vrátí.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (admin/staff nebo service_role)
--
-- ⭐ Sourozenec revert_workflow_decision_admin: rozhodnutí se vrací PODLE ID,
--    ne opakováním kritéria. Kritérium totiž mezitím platí na jiná data.
--
-- ⛔ VRACÍ SE SEZNAM, NE SOUBORY. Karanténa je záznam „tenhle balíček čeká na
--    rozhodnutí". Zahození ho smaže, vrácení ho vrátí — ale jestli balíček někde
--    ještě leží, je otázka retence, ne tohohle rozhodnutí. Proto se vrací jen
--    to, co v seznamu opravdu bylo (`zahozeno`), a co tam mezitím přibylo, zůstává.
--
-- ⭐ NÁHLED JE VÝCHOZÍ (p_dry_run = true).
--
-- Kontrakt: (uuid, text, boolean) ->
--   jsonb {ok, dry_run, decision_id, obnoveno, karantena} | {ok:false, error}
-- ============================================================================

CREATE OR REPLACE FUNCTION public.revert_broker_quarantine_discard_admin(
  p_decision_id uuid,
  p_reason      text,
  p_dry_run     boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rozhodnuti public.audit_journal%ROWTYPE;
  v_zdroj      text;
  v_zahozeno   text[];
  v_karantena  text[];
  v_nova       text[];
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff(auth.uid())) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nedostatečné oprávnění');
  END IF;
  IF p_decision_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'p_decision_id je povinné');
  END IF;
  IF coalesce(btrim(p_reason), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'důvod (p_reason) je povinný — vrácení bez důvodu nejde doložit');
  END IF;

  SELECT * INTO v_rozhodnuti FROM public.audit_journal
   WHERE id = p_decision_id AND entity_type = 'broker_decision';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'rozhodnutí nenalezeno');
  END IF;
  IF v_rozhodnuti.action <> 'broker.quarantine_discarded' THEN
    RETURN jsonb_build_object('ok', false, 'error',
      format('typ rozhodnutí %s zatím vrátit neumím', v_rozhodnuti.action));
  END IF;
  IF EXISTS (SELECT 1 FROM public.audit_journal
              WHERE action = 'broker.quarantine_discard_reverted' AND entity_id = p_decision_id::text) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'rozhodnutí už bylo vráceno');
  END IF;

  v_zdroj := v_rozhodnuti.details->'kriterium'->>'source_slug';
  v_zahozeno := ARRAY(SELECT jsonb_array_elements_text(coalesce(v_rozhodnuti.details->'zahozeno', '[]'::jsonb)));

  SELECT array(SELECT jsonb_array_elements_text(coalesce(s.metadata->'karantena', '[]'::jsonb)))
    INTO v_karantena
    FROM public.audience_broker_sync_state s
   WHERE s.source_slug = v_zdroj;
  IF v_karantena IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error',
      format('zdroj %s už nemá stav synchronizace — není kam vracet', v_zdroj));
  END IF;

  -- Sjednocení, ne přepsání: co do karantény přibylo po zahození, zůstává.
  v_nova := ARRAY(SELECT DISTINCT x FROM unnest(v_karantena || v_zahozeno) x ORDER BY x);

  IF p_dry_run THEN
    RETURN jsonb_build_object('ok', true, 'dry_run', true, 'decision_id', p_decision_id,
                              'obnoveno', to_jsonb(ARRAY(SELECT x FROM unnest(v_zahozeno) x
                                                          WHERE NOT (x = ANY (v_karantena)))),
                              'karantena', to_jsonb(v_nova));
  END IF;

  UPDATE public.audience_broker_sync_state s
     SET metadata = jsonb_set(coalesce(s.metadata, '{}'::jsonb), '{karantena}', to_jsonb(v_nova)),
         updated_at = now()
   WHERE s.source_slug = v_zdroj;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, entity_type, entity_id,
                                    summary, details, metadata)
  VALUES (auth.uid(), 'broker.quarantine_discard_reverted', 'update', 'integrations',
          'broker_decision', p_decision_id::text,
          format('Vráceno zahození karantény zdroje %s: %s balíčků zpět — %s',
                 v_zdroj, array_length(v_zahozeno, 1), p_reason),
          jsonb_build_object('duvod', p_reason, 'obnoveno', to_jsonb(v_zahozeno),
                             'karantena', to_jsonb(v_nova)),
          jsonb_build_object('source_slug', v_zdroj, 'obnoveno', array_length(v_zahozeno, 1)));

  RETURN jsonb_build_object('ok', true, 'dry_run', false, 'decision_id', p_decision_id,
                            'obnoveno', to_jsonb(v_zahozeno), 'karantena', to_jsonb(v_nova));
END;
$function$;

REVOKE ALL ON FUNCTION public.revert_broker_quarantine_discard_admin(uuid, text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.revert_broker_quarantine_discard_admin(uuid, text, boolean) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/revert_twin_decision_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: revert_twin_decision_admin
-- Popis: VRÁTÍ jedno rozhodnutí nad twiny (podle decision_id z audit_journal):
--        twiny, vazby i zdroj vazeb obnoví do stavu PŘED rozhodnutím, s důvodem
--        a stopou, kdo vracel.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (admin/staff nebo service_role)
--
-- ⭐ VRACÍ PŘESNĚ, NE ODHADEM. Rozhodnutí si uložilo stav PŘED sebou u každého
--    twinu (`pred_status`) a každé ukončené vazby (`pred_state`) a seznam
--    převedených vazeb. Vrací se jen řádky, které jsou pořád v tom stavu, do
--    kterého je rozhodnutí dalo (twin nese `archivovano_rozhodnutim` = toto id;
--    vazba je pořád ukončená / pořád pod kanonickým zdrojem). Řádek, se kterým
--    od té doby někdo pracoval, se nepřepíše — počítá se jako
--    `preskoceno_zmenene` a vrácení to řekne.
--
-- ⛔ Obnovení potvrzené vazby by mohlo narazit na jedinečnost vlastníka klíče
--    (source, source_key, ref_kind), kdyby klíč mezitím potvrdil jiný twin.
--    Takovou vazbu vrácení přeskočí (`preskoceno_zmenene`), nespadne celé.
--
-- ⛔ audit_journal je neměnný: vrácení se ZAPISUJE jako nový řádek
--    `twin.decision_reverted` s entity_id = decision_id. Dvojí vrácení se odmítne.
--
-- ⭐ NÁHLED JE VÝCHOZÍ (p_dry_run = true).
--
-- Typy rozhodnutí:
--   · twin.absorbed_source_resolved (resolve_absorbed_ingest_source_admin),
--   · twin.person_unified (hr_sjednot_osobu_admin, 2026-09-23): úlomky zpět
--     z archivu, přesunuté vazby zpět k úlomkům, ukončené obnovit, ČEKAJÍCÍ
--     úkoly zpět (hotové se nevracejí — tu práci už někdo odvedl), a odemknout
--     jméno kanonu, pokud ho zamklo PRÁVĚ toto rozhodnutí.
-- Jiný typ se odmítne pojmenovaně — vrácení, které neví, co vrací, je horší než žádné.
--
-- Kontrakt: (uuid, text, boolean) ->
--   jsonb {ok, dry_run, decision_id, akce, twinu, vazeb_obnoveno, vazeb_vraceno_zdroji,
--          preskoceno_zmenene}
-- ============================================================================

CREATE OR REPLACE FUNCTION public.revert_twin_decision_admin(
  p_decision_id uuid,
  p_reason      text,
  p_dry_run     boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rozhodnuti public.audit_journal%ROWTYPE;
  v_zdroj      text;
  v_kanon      text;
  v_twinu      integer := 0;
  v_vazeb      integer := 0;
  v_zdroji     integer := 0;
  v_celkem     integer := 0;
  v_kanon_id   uuid;
  v_zpet       integer := 0;
  v_kroku      integer := 0;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff(auth.uid())) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nedostatečné oprávnění');
  END IF;
  IF p_decision_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'p_decision_id je povinné');
  END IF;
  IF coalesce(btrim(p_reason), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'důvod (p_reason) je povinný — vrácení bez důvodu nejde doložit');
  END IF;

  SELECT * INTO v_rozhodnuti FROM public.audit_journal
   WHERE id = p_decision_id AND entity_type = 'twin_decision';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'rozhodnutí nenalezeno');
  END IF;
  IF v_rozhodnuti.action NOT IN ('twin.absorbed_source_resolved', 'twin.person_unified') THEN
    RETURN jsonb_build_object('ok', false, 'error',
      format('typ rozhodnutí %s zatím vrátit neumím', v_rozhodnuti.action));
  END IF;
  IF EXISTS (SELECT 1 FROM public.audit_journal
              WHERE action = 'twin.decision_reverted' AND entity_id = p_decision_id::text) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'rozhodnutí už bylo vráceno');
  END IF;

  -- ── SJEDNOCENÍ OSOBY (hr_sjednot_osobu_admin) ─────────────────────────────
  -- Vrací se jen řádky, které jsou pořád tam, kam je rozhodnutí dalo; ostatní
  -- (někdo s nimi mezitím pracoval) se přeskočí a vrácení to spočítá.
  IF v_rozhodnuti.action = 'twin.person_unified' THEN
    v_kanon_id := (v_rozhodnuti.details ->> 'kanon')::uuid;
    v_celkem := jsonb_array_length(coalesce(v_rozhodnuti.details -> 'archivovane_twiny', '[]'::jsonb))
              + jsonb_array_length(coalesce(v_rozhodnuti.details -> 'presunute_vazby', '[]'::jsonb))
              + jsonb_array_length(coalesce(v_rozhodnuti.details -> 'nahrazene_vazby', '[]'::jsonb))
              + jsonb_array_length(coalesce(v_rozhodnuti.details -> 'prepojene_kroky', '[]'::jsonb));
    IF p_dry_run THEN
      SELECT count(*) INTO v_twinu
        FROM public.twin_entities e
        JOIN jsonb_to_recordset(v_rozhodnuti.details -> 'archivovane_twiny') AS x(id uuid, pred_status text) ON x.id = e.id
       WHERE e.status = 'archived' AND e.metadata ->> 'archivovano_rozhodnutim' = p_decision_id::text;
      SELECT count(*) INTO v_zpet
        FROM public.twin_external_refs r
        JOIN jsonb_to_recordset(v_rozhodnuti.details -> 'presunute_vazby') AS x(id uuid, pred_twin_id uuid) ON x.id = r.id
       WHERE r.twin_id = v_kanon_id AND r.valid_to IS NULL;
      SELECT count(*) INTO v_vazeb
        FROM public.twin_external_refs r
        JOIN jsonb_to_recordset(v_rozhodnuti.details -> 'nahrazene_vazby') AS x(id uuid, pred_state text) ON x.id = r.id
       WHERE r.state = 'superseded' AND r.valid_to IS NOT NULL;
      SELECT count(*) INTO v_kroku
        FROM public.production_workflow_steps st
        JOIN jsonb_to_recordset(v_rozhodnuti.details -> 'prepojene_kroky') AS x(id uuid, pred_twin_id text) ON x.id = st.id
       WHERE st.status = 'pending' AND st.input_data ->> 'authorized_twin_id' = v_kanon_id::text;
      RETURN jsonb_build_object('ok', true, 'dry_run', true, 'decision_id', p_decision_id,
                                'akce', v_rozhodnuti.action, 'twinu', v_twinu,
                                'vazeb_zpet', v_zpet, 'vazeb_obnoveno', v_vazeb, 'kroku_zpet', v_kroku,
                                'preskoceno_zmenene', v_celkem - v_twinu - v_zpet - v_vazeb - v_kroku);
    END IF;

    UPDATE public.twin_entities e
       SET status = x.pred_status,
           metadata = e.metadata - 'archivovano_rozhodnutim' - 'sjednoceno_do',
           updated_at = now()
      FROM jsonb_to_recordset(v_rozhodnuti.details -> 'archivovane_twiny') AS x(id uuid, pred_status text)
     WHERE e.id = x.id AND e.status = 'archived'
       AND e.metadata ->> 'archivovano_rozhodnutim' = p_decision_id::text;
    GET DIAGNOSTICS v_twinu = ROW_COUNT;

    UPDATE public.twin_external_refs r
       SET twin_id = x.pred_twin_id, updated_at = now()
      FROM jsonb_to_recordset(v_rozhodnuti.details -> 'presunute_vazby') AS x(id uuid, pred_twin_id uuid)
     WHERE r.id = x.id AND r.twin_id = v_kanon_id AND r.valid_to IS NULL;
    GET DIAGNOSTICS v_zpet = ROW_COUNT;

    UPDATE public.twin_external_refs r
       SET state = x.pred_state, valid_to = NULL, updated_at = now()
      FROM jsonb_to_recordset(v_rozhodnuti.details -> 'nahrazene_vazby') AS x(id uuid, pred_state text)
     WHERE r.id = x.id AND r.state = 'superseded' AND r.valid_to IS NOT NULL;
    GET DIAGNOSTICS v_vazeb = ROW_COUNT;

    UPDATE public.production_workflow_steps st
       SET input_data = jsonb_set(st.input_data, '{authorized_twin_id}', to_jsonb(x.pred_twin_id))
      FROM jsonb_to_recordset(v_rozhodnuti.details -> 'prepojene_kroky') AS x(id uuid, pred_twin_id text)
     WHERE st.id = x.id AND st.status = 'pending'
       AND st.input_data ->> 'authorized_twin_id' = v_kanon_id::text;
    GET DIAGNOSTICS v_kroku = ROW_COUNT;

    UPDATE public.twin_entities e
       SET metadata = e.metadata - 'label_hr' - 'label_hr_rozhodnutim', updated_at = now()
     WHERE e.id = v_kanon_id AND e.metadata ->> 'label_hr_rozhodnutim' = p_decision_id::text;

    INSERT INTO public.audit_journal (user_id, action, action_type, area, entity_type, entity_id,
                                      summary, details)
    VALUES (auth.uid(), 'twin.decision_reverted', 'update', 'twin',
            'twin_decision_revert', p_decision_id::text,
            format('Vráceno sjednocení osoby %s: %s úlomků, %s vazeb zpět, %s obnoveno, %s úkolů zpět — %s',
                   p_decision_id, v_twinu, v_zpet, v_vazeb, v_kroku, p_reason),
            jsonb_build_object('decision_id', p_decision_id, 'akce', v_rozhodnuti.action,
                               'twinu', v_twinu, 'vazeb_zpet', v_zpet, 'vazeb_obnoveno', v_vazeb,
                               'kroku_zpet', v_kroku,
                               'preskoceno_zmenene', v_celkem - v_twinu - v_zpet - v_vazeb - v_kroku,
                               'duvod', p_reason));

    RETURN jsonb_build_object('ok', true, 'dry_run', false, 'decision_id', p_decision_id,
                              'akce', v_rozhodnuti.action, 'twinu', v_twinu,
                              'vazeb_zpet', v_zpet, 'vazeb_obnoveno', v_vazeb, 'kroku_zpet', v_kroku,
                              'preskoceno_zmenene', v_celkem - v_twinu - v_zpet - v_vazeb - v_kroku);
  END IF;

  v_zdroj := v_rozhodnuti.details ->> 'zdroj';
  v_kanon := v_rozhodnuti.details ->> 'kanon';
  v_celkem := jsonb_array_length(coalesce(v_rozhodnuti.details -> 'archivovane_twiny', '[]'::jsonb))
            + jsonb_array_length(coalesce(v_rozhodnuti.details -> 'nahrazene_vazby', '[]'::jsonb))
            + jsonb_array_length(coalesce(v_rozhodnuti.details -> 'prevedene_vazby', '[]'::jsonb));

  IF p_dry_run THEN
    SELECT count(*) INTO v_twinu
      FROM public.twin_entities e
      JOIN jsonb_to_recordset(v_rozhodnuti.details -> 'archivovane_twiny') AS x(id uuid, pred_status text) ON x.id = e.id
     WHERE e.status = 'archived' AND e.metadata ->> 'archivovano_rozhodnutim' = p_decision_id::text;
    SELECT count(*) INTO v_vazeb
      FROM public.twin_external_refs r
      JOIN jsonb_to_recordset(v_rozhodnuti.details -> 'nahrazene_vazby') AS x(id uuid, pred_state text) ON x.id = r.id
     WHERE r.state = 'superseded' AND r.valid_to IS NOT NULL
       AND NOT (x.pred_state = 'confirmed' AND EXISTS (
             SELECT 1 FROM public.twin_external_refs o
              WHERE o.source = r.source AND o.source_key = r.source_key AND o.ref_kind = r.ref_kind
                AND o.entity_type = r.entity_type
                AND o.state = 'confirmed' AND o.valid_to IS NULL AND o.id <> r.id));
    SELECT count(*) INTO v_zdroji
      FROM public.twin_external_refs r
     WHERE r.id IN (SELECT (jsonb_array_elements_text(v_rozhodnuti.details -> 'prevedene_vazby'))::uuid)
       AND r.source = v_kanon AND r.valid_to IS NULL;
    RETURN jsonb_build_object('ok', true, 'dry_run', true, 'decision_id', p_decision_id,
                              'akce', v_rozhodnuti.action, 'twinu', v_twinu,
                              'vazeb_obnoveno', v_vazeb, 'vazeb_vraceno_zdroji', v_zdroji,
                              'preskoceno_zmenene', v_celkem - v_twinu - v_vazeb - v_zdroji);
  END IF;

  UPDATE public.twin_entities e
     SET status = x.pred_status,
         metadata = e.metadata - 'archivovano_rozhodnutim',
         updated_at = now()
    FROM jsonb_to_recordset(v_rozhodnuti.details -> 'archivovane_twiny') AS x(id uuid, pred_status text)
   WHERE e.id = x.id
     AND e.status = 'archived'
     AND e.metadata ->> 'archivovano_rozhodnutim' = p_decision_id::text;
  GET DIAGNOSTICS v_twinu = ROW_COUNT;

  UPDATE public.twin_external_refs r
     SET state = x.pred_state, valid_to = NULL, updated_at = now()
    FROM jsonb_to_recordset(v_rozhodnuti.details -> 'nahrazene_vazby') AS x(id uuid, pred_state text)
   WHERE r.id = x.id
     AND r.state = 'superseded' AND r.valid_to IS NOT NULL
     AND NOT (x.pred_state = 'confirmed' AND EXISTS (
           SELECT 1 FROM public.twin_external_refs o
            WHERE o.source = r.source AND o.source_key = r.source_key AND o.ref_kind = r.ref_kind
              AND o.entity_type = r.entity_type
              AND o.state = 'confirmed' AND o.valid_to IS NULL AND o.id <> r.id));
  GET DIAGNOSTICS v_vazeb = ROW_COUNT;

  UPDATE public.twin_external_refs r
     SET source = v_zdroj, updated_at = now()
   WHERE r.id IN (SELECT (jsonb_array_elements_text(v_rozhodnuti.details -> 'prevedene_vazby'))::uuid)
     AND r.source = v_kanon AND r.valid_to IS NULL;
  GET DIAGNOSTICS v_zdroji = ROW_COUNT;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, entity_type, entity_id,
                                    summary, details)
  VALUES (auth.uid(), 'twin.decision_reverted', 'update', 'twin',
          'twin_decision_revert', p_decision_id::text,
          format('Vráceno rozhodnutí %s: %s twinů, %s vazeb obnoveno, %s vráceno zdroji %s — %s',
                 p_decision_id, v_twinu, v_vazeb, v_zdroji, v_zdroj, p_reason),
          jsonb_build_object('decision_id', p_decision_id, 'akce', v_rozhodnuti.action,
                             'obnoveno', v_twinu + v_vazeb + v_zdroji,
                             'twinu', v_twinu, 'vazeb_obnoveno', v_vazeb, 'vazeb_vraceno_zdroji', v_zdroji,
                             'preskoceno_zmenene', v_celkem - v_twinu - v_vazeb - v_zdroji,
                             'duvod', p_reason));

  RETURN jsonb_build_object('ok', true, 'dry_run', false, 'decision_id', p_decision_id,
                            'akce', v_rozhodnuti.action, 'twinu', v_twinu,
                            'vazeb_obnoveno', v_vazeb, 'vazeb_vraceno_zdroji', v_zdroji,
                            'preskoceno_zmenene', v_celkem - v_twinu - v_vazeb - v_zdroji);
END;
$function$;

REVOKE ALL ON FUNCTION public.revert_twin_decision_admin(uuid, text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.revert_twin_decision_admin(uuid, text, boolean) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/revert_workflow_decision_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: revert_workflow_decision_admin
-- Popis: VRÁTÍ jedno rozhodnutí nad procesem (podle decision_id z audit_journal):
--        uzly obnoví do stavu PŘED rozhodnutím, s důvodem a stopou, kdo vracel.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (admin/staff nebo service_role)
--
-- ⭐ ZADÁNÍ MAJITELE 2026-09-15: „všechny tyto autonomní kroky potřebujeme umět
--    dohledat, dohledovat a případně zrušit a opravit uživatelem z UI". Hromadný
--    zásah bez cesty zpět je jednosměrný — a chyba v kritériu by se opravovala
--    dalším ručním zásahem, tentokrát bez stopy.
--
-- ⭐ VRACÍ PŘESNĚ, NE ODHADEM. Rozhodnutí si u každého uzlu uložilo jeho stav
--    PŘED sebou (`pred_uzavrenim`) a v audit_journal seznam uzlů. Vrací se jen
--    uzly, které pořád nesou TOTO decision_id a jsou pořád v tom stavu, do kterého
--    je rozhodnutí dalo. Uzel, se kterým od té doby někdo pracoval, se nepřepíše —
--    počítá se jako `preskoceno_zmenene` a vrácení to řekne.
--
-- ⛔ audit_journal je neměnný (fn_audit_journal_guard): vrácení se ZAPISUJE jako
--    nový řádek `workflow.decision_reverted` s entity_id = decision_id. Dvojí
--    vrácení se odmítne.
--
-- ⭐ NÁHLED JE VÝCHOZÍ (p_dry_run = true).
--
-- Typy rozhodnutí: workflow.runs_closed_by_decision (close_stale_workflow_runs_admin).
-- Jiný typ se odmítne pojmenovaně — vrácení, které neví, co vrací, je horší než žádné.
--
-- Kontrakt: (uuid, text, boolean) ->
--   jsonb {ok, dry_run, decision_id, akce, obnoveno, preskoceno_zmenene, taktu_otevreno}
-- ============================================================================

CREATE OR REPLACE FUNCTION public.revert_workflow_decision_admin(
  p_decision_id uuid,
  p_reason      text,
  p_dry_run     boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rozhodnuti public.audit_journal%ROWTYPE;
  v_obnoveno   integer := 0;
  v_zmenene    integer := 0;
  v_taktu      integer := 0;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff(auth.uid())) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nedostatečné oprávnění');
  END IF;
  IF p_decision_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'p_decision_id je povinné');
  END IF;
  IF coalesce(btrim(p_reason), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'důvod (p_reason) je povinný — vrácení bez důvodu nejde doložit');
  END IF;

  SELECT * INTO v_rozhodnuti FROM public.audit_journal
   WHERE id = p_decision_id AND entity_type = 'workflow_decision';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'rozhodnutí nenalezeno');
  END IF;
  IF v_rozhodnuti.action <> 'workflow.runs_closed_by_decision' THEN
    RETURN jsonb_build_object('ok', false, 'error',
      format('typ rozhodnutí %s zatím vrátit neumím', v_rozhodnuti.action));
  END IF;
  IF EXISTS (SELECT 1 FROM public.audit_journal
              WHERE action = 'workflow.decision_reverted' AND entity_id = p_decision_id::text) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'rozhodnutí už bylo vráceno');
  END IF;

  SELECT count(*) FILTER (WHERE s.status = 'completed'
                            AND s.output_data->>'decision_id' = p_decision_id::text
                            AND s.output_data->>'uzavreno_rozhodnutim' = 'true'),
         count(*) FILTER (WHERE NOT (s.status = 'completed'
                            AND coalesce(s.output_data->>'decision_id', '') = p_decision_id::text
                            AND coalesce(s.output_data->>'uzavreno_rozhodnutim', '') = 'true'))
    INTO v_obnoveno, v_zmenene
    FROM public.production_workflow_steps s
   WHERE s.id IN (SELECT (jsonb_array_elements_text(v_rozhodnuti.details->'uzly'))::uuid);

  IF p_dry_run THEN
    RETURN jsonb_build_object('ok', true, 'dry_run', true, 'decision_id', p_decision_id,
                              'akce', v_rozhodnuti.action, 'obnoveno', v_obnoveno,
                              'preskoceno_zmenene', v_zmenene, 'taktu_otevreno', jsonb_array_length(coalesce(v_rozhodnuti.details->'takty', '[]'::jsonb)));
  END IF;

  UPDATE public.production_workflow_steps s
     SET status = 'pending',
         completed_at = NULL,
         output_data = nullif(s.output_data->'pred_uzavrenim', '{}'::jsonb),
         updated_at = now()
   WHERE s.id IN (SELECT (jsonb_array_elements_text(v_rozhodnuti.details->'uzly'))::uuid)
     AND s.status = 'completed'
     AND s.output_data->>'decision_id' = p_decision_id::text
     AND s.output_data->>'uzavreno_rozhodnutim' = 'true';
  GET DIAGNOSTICS v_obnoveno = ROW_COUNT;

  -- Takty: znovu se otevřou PRÁVĚ ty, které rozhodnutí zrušilo (id v rozhodnutí),
  -- a jen pokud jsou pořád v jeho stavu. Nové takty se nezakládají — vrácení má
  -- obnovit stav před rozhodnutím, ne vyrobit dluh, který tu předtím nebyl
  -- (naměřeno: staré běhy takty neměly a otevření nových by je vytáhlo do front).
  UPDATE public.story_pulse_beats pb
     SET status = 'open', closed_at = NULL, closed_by = NULL, updated_at = now()
   WHERE pb.id IN (SELECT (jsonb_array_elements_text(coalesce(v_rozhodnuti.details->'takty', '[]'::jsonb)))::uuid)
     AND pb.status = 'cancelled';
  GET DIAGNOSTICS v_taktu = ROW_COUNT;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, entity_type, entity_id,
                                    summary, details)
  VALUES (auth.uid(), 'workflow.decision_reverted', 'update', 'workflow',
          'workflow_decision_revert', p_decision_id::text,
          format('Vráceno rozhodnutí %s: obnoveno %s uzlů — %s', p_decision_id, v_obnoveno, p_reason),
          jsonb_build_object('decision_id', p_decision_id, 'akce', v_rozhodnuti.action,
                             'obnoveno', v_obnoveno, 'preskoceno_zmenene', v_zmenene,
                             'taktu_otevreno', v_taktu, 'duvod', p_reason));

  RETURN jsonb_build_object('ok', true, 'dry_run', false, 'decision_id', p_decision_id,
                            'akce', v_rozhodnuti.action, 'obnoveno', v_obnoveno,
                            'preskoceno_zmenene', v_zmenene, 'taktu_otevreno', v_taktu);
END;
$function$;

REVOKE ALL ON FUNCTION public.revert_workflow_decision_admin(uuid, text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.revert_workflow_decision_admin(uuid, text, boolean) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/review_moderation_item.sql
-- -----------------------------------------------------------------------------

-- Function: public.review_moderation_item
-- Description: Updates moderation queue status and the underlying resource.
-- Security: SECURITY DEFINER - admin only.
-- @category: ADMIN
-- @audit: true

CREATE OR REPLACE FUNCTION public.review_moderation_item(
  p_decision text,
  p_notes text DEFAULT NULL,
  p_queue_id uuid DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_resource_type text;
  v_resource_id uuid;
  v_current_status text;
BEGIN
  -- 1. Check permissions
  IF NOT public.has_role(auth.uid(), 'admin') AND NOT public.has_role(auth.uid(), 'staff') THEN
    RAISE EXCEPTION 'Access denied. Admin or Staff role required.';
  END IF;

  -- 2. Get Item Details
  SELECT resource_type, resource_id, status INTO v_resource_type, v_resource_id, v_current_status
  FROM knowledge_moderation_queue
  WHERE id = p_queue_id;

  IF v_resource_type IS NULL THEN
    RAISE EXCEPTION 'Moderation item not found.';
  END IF;
  
  -- 'escalated' is the state AISHA sets when it defers to a human, so the
  -- human-review RPC MUST accept it — otherwise an escalated agent/rule is
  -- frozen forever (queue 'escalated', resource stuck in 'reviewing'). Only a
  -- terminal decision (approved/rejected) blocks re-review.
  IF v_current_status NOT IN ('pending', 'escalated') THEN
    RAISE EXCEPTION 'Item already reviewed (status: %).', v_current_status;
  END IF;

  -- 3. Update Queue Item
  UPDATE knowledge_moderation_queue
  SET
    status = p_decision,
    reviewer_user_id = auth.uid(),
    reviewer_notes = p_notes,
    updated_at = now()
  WHERE id = p_queue_id;

  -- 4. Update Resource Status
  IF v_resource_type = 'post' THEN
    IF p_decision = 'approved' THEN
      UPDATE knowledge_posts SET status = 'visible' WHERE id = v_resource_id;
    ELSE -- rejected
      UPDATE knowledge_posts SET status = 'hidden' WHERE id = v_resource_id;
    END IF;

  ELSIF v_resource_type = 'expert_rule' THEN
    -- Was previously stranded: escalated/queued expert_rules had no human-review
    -- resolution path. approve → published, reject → draft (author can re-publish).
    IF p_decision = 'approved' THEN
      UPDATE expert_rules
         SET status = 'published',
             published_at = COALESCE(published_at, now()),
             updated_at = now()
       WHERE id = v_resource_id;
    ELSE -- rejected
      UPDATE expert_rules SET status = 'draft', updated_at = now() WHERE id = v_resource_id;
    END IF;

  ELSIF v_resource_type = 'agent' THEN
    -- Marketplace agent: resource_id = plugin_catalog.id.
    IF p_decision = 'approved' THEN
      UPDATE plugin_catalog
         SET status = 'canary'::plugin_status, updated_at = now()
       WHERE id = v_resource_id
         AND status NOT IN ('disabled'::plugin_status, 'archived'::plugin_status);
      -- Materialize only if the guarded UPDATE promoted the plugin — never
      -- re-activate a disabled/archived agent's runtime on a late human approval
      -- (mirrors fn_aisha_kb_decision; protects the kill-switch).
      IF FOUND THEN
        -- Kind dispatcher (mirrors fn_aisha_kb_decision).
        PERFORM public.materialize_plugin(v_resource_id);
      END IF;
    ELSE -- rejected
      UPDATE plugin_catalog
         SET status = 'submitted'::plugin_status, updated_at = now()
       WHERE id = v_resource_id;
    END IF;
  END IF;

  -- 5. Audit
  -- Direct insert mirrors fn_aisha_kb_decision (action is free text on
  -- audit_journal). The previous write_audit_journal call passed
  -- 'REVIEW_MODERATION_ITEM' as a journal_action_type enum value — which is not a
  -- member of that curated verb vocabulary — so the audit RAISEd for every
  -- decision (a latent, untested bug). Fixed at source.
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'REVIEW_MODERATION_ITEM',
    jsonb_build_object(
      'area', 'knowledge',
      'severity', 'info',
      'queue_id', p_queue_id,
      'decision', p_decision,
      'notes', p_notes,
      'resource_type', v_resource_type,
      'resource_id', v_resource_id
    )
  );
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.review_moderation_item(text, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.review_moderation_item(text, text, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/revoke_instance_auth_token.sql
-- -----------------------------------------------------------------------------

-- Function: public.revoke_instance_auth_token
-- Arguments: p_token_id uuid
-- Description: Soft-revokes an instance auth token. Sets revoked_at timestamp.
-- Security: SECURITY DEFINER — admin/staff only

CREATE OR REPLACE FUNCTION public.revoke_instance_auth_token(p_token_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_token record;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff role required';
  END IF;

  SELECT * INTO v_token
  FROM instance_auth_tokens WHERE id = p_token_id;

  IF v_token.id IS NULL THEN
    RAISE EXCEPTION 'Token not found: %', p_token_id;
  END IF;

  IF v_token.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('status', 'already_revoked', 'revoked_at', v_token.revoked_at);
  END IF;

  UPDATE instance_auth_tokens SET
    revoked_at = now(), updated_at = now()
  WHERE id = p_token_id;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (v_user_id, 'INSTANCE_TOKEN_REVOKE', jsonb_build_object(
    'area', 'story_sync', 'severity', 'warning',
    'entity_type', 'instance_auth_token', 'entity_id', p_token_id,
    'instance_id', v_token.instance_id
  ));

  RETURN jsonb_build_object('status', 'revoked', 'token_id', p_token_id);
END;
$function$;

REVOKE ALL ON FUNCTION public.revoke_instance_auth_token(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.revoke_instance_auth_token(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/revoke_mcp_token_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.revoke_mcp_token_admin
-- Arguments: p_id uuid
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.revoke_mcp_token_admin(p_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Permission denied' USING ERRCODE = 'P0003';
  END IF;

  UPDATE mcp_auth_tokens
  SET
    is_active = false,
    expires_at = now(),
    allowed_tools = '{}'::text[],
    denied_tools = '{}'::text[]
  WHERE id = p_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'MCP token not found: %', p_id USING ERRCODE = 'P0002';
  END IF;

  RETURN p_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.revoke_mcp_token_admin(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.revoke_mcp_token_admin(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.revoke_mcp_token_admin(uuid) TO service_role;


