-- -----------------------------------------------------------------------------

-- Function: public.save_health_metric_audited
-- Description: Save a health metric with audit logging
-- Security: SECURITY DEFINER with audit logging
-- sensitive data: Yes - writes health metrics data

CREATE OR REPLACE FUNCTION public.save_health_metric_audited(
  p_study_registration_id UUID DEFAULT NULL,
  p_physical_state INTEGER DEFAULT NULL,
  p_mental_state INTEGER DEFAULT NULL,
  p_energy_level INTEGER DEFAULT NULL,
  p_stress_level INTEGER DEFAULT NULL,
  p_sleep_quality INTEGER DEFAULT NULL,
  p_pain_level INTEGER DEFAULT NULL,
  p_weight_kg NUMERIC DEFAULT NULL,
  p_height_cm NUMERIC DEFAULT NULL,
  p_source TEXT DEFAULT 'manual',
  p_source_id UUID DEFAULT NULL,
  p_measured_at TIMESTAMPTZ DEFAULT NOW(),
  p_notes TEXT DEFAULT NULL
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
DECLARE
  v_metric_id UUID;
BEGIN
  -- Insert metric
  INSERT INTO health_metrics (
    user_id,
    study_registration_id,
    measured_at,
    physical_state,
    mental_state,
    energy_level,
    stress_level,
    sleep_quality,
    pain_level,
    weight_kg,
    height_cm,
    source,
    source_id,
    notes
  ) VALUES (
    auth.uid(),
    p_study_registration_id,
    p_measured_at,
    p_physical_state,
    p_mental_state,
    p_energy_level,
    p_stress_level,
    p_sleep_quality,
    p_pain_level,
    p_weight_kg,
    p_height_cm,
    p_source,
    p_source_id,
    p_notes
  )
  RETURNING id INTO v_metric_id;

  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'HEALTH_METRIC_CREATED',
    jsonb_build_object(
      'area', 'health',
      'severity', 'info',
      'metric_id', v_metric_id,
      'source', p_source,
      'registration_id', p_study_registration_id
    )
  );

  RETURN v_metric_id;
END;
$$;

REVOKE ALL ON FUNCTION public.save_health_metric_audited(uuid, integer, integer, integer, integer, integer, integer, numeric, numeric, text, uuid, timestamptz, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.save_health_metric_audited(uuid, integer, integer, integer, integer, integer, integer, numeric, numeric, text, uuid, timestamptz, text) FROM anon;
GRANT EXECUTE ON FUNCTION public.save_health_metric_audited(uuid, integer, integer, integer, integer, integer, integer, numeric, numeric, text, uuid, timestamptz, text) TO authenticated;

COMMENT ON FUNCTION public.save_health_metric_audited(uuid, integer, integer, integer, integer, integer, integer, numeric, numeric, text, uuid, timestamptz, text) IS 'Save a health metric with audit logging';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/save_operational_assessment_dimension.sql
-- -----------------------------------------------------------------------------

-- Function: public.save_operational_assessment_dimension
-- Arguments: p_assessment_id uuid, p_dimension text, p_raw_score numeric, p_normalized_score numeric, p_tag_count integer, p_has_negative_indicators boolean, p_operational_flags text[], p_tag_ids text[] DEFAULT NULL::text[], p_follow_up_answers jsonb DEFAULT NULL::jsonb
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.save_operational_assessment_dimension(p_assessment_id uuid, p_dimension text, p_raw_score numeric, p_normalized_score numeric, p_tag_count integer, p_has_negative_indicators boolean, p_operational_flags text[], p_tag_ids text[] DEFAULT NULL::text[], p_follow_up_answers jsonb DEFAULT NULL::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_dimensions JSONB;
  v_new_dim JSONB;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.operational_assessments
    WHERE id = p_assessment_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  v_new_dim := jsonb_build_object(
    'dimension', p_dimension,
    'rawScore', p_raw_score,
    'normalizedScore', p_normalized_score,
    'tagCount', p_tag_count,
    'hasNegativeIndicators', p_has_negative_indicators,
    'operationalFlags', p_operational_flags,
    'tagIds', COALESCE(p_tag_ids, ARRAY[]::TEXT[]),
    'followUps', COALESCE(p_follow_up_answers, '[]'::JSONB)
  );

  SELECT COALESCE(dimensions, '[]'::JSONB)
  INTO v_dimensions
  FROM public.operational_assessments
  WHERE id = p_assessment_id;

  v_dimensions := (
    SELECT jsonb_agg(d)
    FROM jsonb_array_elements(v_dimensions) d
    WHERE d->>'dimension' != p_dimension
  );

  v_dimensions := COALESCE(v_dimensions, '[]'::JSONB) || jsonb_build_array(v_new_dim);

  UPDATE public.operational_assessments
  SET dimensions = v_dimensions, updated_at = now()
  WHERE id = p_assessment_id;

  -- Persist the dimension as a normalized row as well. This is the queryable
  -- source of truth (one row per assessment+dimension, cross-assessment/user
  -- analytics); the JSONB above is a per-row denormalized cache. The score
  -- stored here is the OUTPUT of the client scoring logic, not a free blob.
  -- get_my_latest_operational_assessment_audited reads this table first.
  INSERT INTO public.operational_assessment_dimensions (
    assessment_id, dimension, raw_score, normalized_score,
    tag_count, has_negative_indicators, operational_flags
  )
  VALUES (
    p_assessment_id, p_dimension::operational_dimension, p_raw_score, p_normalized_score,
    p_tag_count, p_has_negative_indicators, COALESCE(p_operational_flags, '{}'::text[])
  )
  ON CONFLICT (assessment_id, dimension) DO UPDATE SET
    raw_score = EXCLUDED.raw_score,
    normalized_score = EXCLUDED.normalized_score,
    tag_count = EXCLUDED.tag_count,
    has_negative_indicators = EXCLUDED.has_negative_indicators,
    operational_flags = EXCLUDED.operational_flags;

  RETURN true;
END;
$function$;

REVOKE ALL ON FUNCTION public.save_operational_assessment_dimension(uuid, text, numeric, numeric, integer, boolean, text[][], text[][], jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_operational_assessment_dimension(uuid, text, numeric, numeric, integer, boolean, text[][], text[][], jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.save_operational_assessment_dimension(uuid, text, numeric, numeric, integer, boolean, text[][], text[][], jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/save_partner_template.sql
-- -----------------------------------------------------------------------------

-- Function: public.save_partner_template
-- Arguments: p_name text, p_blocks jsonb, p_id uuid, p_description text, p_category text, p_is_active boolean, p_is_default boolean
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:28:05+01:00

CREATE OR REPLACE FUNCTION public.save_partner_template(p_name text, p_blocks jsonb, p_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_category text DEFAULT 'general'::text, p_is_active boolean DEFAULT true, p_is_default boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_id UUID;
  v_template_id UUID;
BEGIN
  -- Get partner ID for current user
  SELECT pp.id INTO v_partner_id
  FROM partner_profiles pp
  WHERE pp.user_id = auth.uid();
  
  IF v_partner_id IS NULL THEN
    RAISE EXCEPTION 'User is not a partner';
  END IF;
  
  IF p_id IS NOT NULL THEN
    -- Update existing template
    UPDATE partner_templates
    SET 
      name = p_name,
      description = p_description,
      category = p_category,
      is_active = p_is_active,
      is_default = p_is_default,
      blocks = p_blocks,
      updated_at = now()
    WHERE id = p_id AND partner_id = v_partner_id
    RETURNING id INTO v_template_id;
    
    IF v_template_id IS NULL THEN
      RAISE EXCEPTION 'Template not found or not authorized';
    END IF;
  ELSE
    -- Insert new template
    INSERT INTO partner_templates (partner_id, name, description, category, is_active, is_default, blocks)
    VALUES (v_partner_id, p_name, p_description, p_category, p_is_active, p_is_default, p_blocks)
    RETURNING id INTO v_template_id;
  END IF;
  
  -- If this is set as default, unset other defaults in same category
  IF p_is_default THEN
    UPDATE partner_templates
    SET is_default = false
    WHERE partner_id = v_partner_id 
      AND category = p_category 
      AND id != v_template_id;
  END IF;
  
  RETURN v_template_id;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.save_partner_template(p_name text, p_blocks jsonb, p_id uuid, p_description text, p_category text, p_is_active boolean, p_is_default boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_partner_template(p_name text, p_blocks jsonb, p_id uuid, p_description text, p_category text, p_is_active boolean, p_is_default boolean) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/save_proactive_run.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION save_proactive_run(
  p_trigger_definition_id uuid,
  p_user_id uuid,
  p_source_record_id uuid DEFAULT NULL,
  p_source_data jsonb DEFAULT NULL,
  p_status text DEFAULT 'completed',
  p_ai_run_id uuid DEFAULT NULL,
  p_output_text text DEFAULT NULL,
  p_output_data jsonb DEFAULT NULL,
  p_action_taken text DEFAULT NULL,
  p_action_result jsonb DEFAULT NULL,
  p_started_at timestamptz DEFAULT NULL,
  p_completed_at timestamptz DEFAULT NULL,
  p_duration_ms integer DEFAULT NULL,
  p_tokens_input integer DEFAULT 0,
  p_tokens_output integer DEFAULT 0,
  p_error_message text DEFAULT NULL,
  p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id uuid;
  v_is_service_role BOOLEAN;
BEGIN
  v_is_service_role := public.is_service_role();
  IF auth.uid() IS NULL AND NOT v_is_service_role THEN
    RAISE EXCEPTION 'Access denied: authentication required';
  END IF;

  INSERT INTO ai_proactive_runs (
    trigger_definition_id, user_id, source_record_id, source_data,
    status, ai_run_id, output_text, output_data,
    action_taken, action_result,
    started_at, completed_at, duration_ms,
    tokens_input, tokens_output,
    error_message, metadata
  )
  VALUES (
    p_trigger_definition_id, p_user_id, p_source_record_id, p_source_data,
    p_status, p_ai_run_id, p_output_text, p_output_data,
    p_action_taken, p_action_result,
    p_started_at, p_completed_at, p_duration_ms,
    p_tokens_input, p_tokens_output,
    p_error_message, p_metadata
  )
  RETURNING ai_proactive_runs.id INTO v_id;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION save_proactive_run(uuid, uuid, uuid, jsonb, text, uuid, text, jsonb, text, jsonb, timestamptz, timestamptz, integer, integer, integer, text, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION save_proactive_run(uuid, uuid, uuid, jsonb, text, uuid, text, jsonb, text, jsonb, timestamptz, timestamptz, integer, integer, integer, text, jsonb) FROM authenticated;
GRANT EXECUTE ON FUNCTION save_proactive_run(uuid, uuid, uuid, jsonb, text, uuid, text, jsonb, text, jsonb, timestamptz, timestamptz, integer, integer, integer, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/save_web_page_as_template.sql
-- -----------------------------------------------------------------------------

-- Function: public.save_web_page_as_template
-- Description: Saves a web page's current state as a reusable template.
-- Security: SECURITY INVOKER, authenticated only, admin/staff check inside
-- Created: 2026-04-14

CREATE OR REPLACE FUNCTION public.save_web_page_as_template(
  p_page_id uuid,
  p_name text,
  p_description text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_template_id uuid;
  v_page record;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT canvas_data, canvas_html, canvas_css, page_settings
  INTO v_page
  FROM public.web_pages
  WHERE id = p_page_id AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Page not found';
  END IF;

  INSERT INTO public.web_page_templates (
    name, description, canvas_data, canvas_html, canvas_css,
    page_settings, created_by
  ) VALUES (
    p_name, p_description, v_page.canvas_data, v_page.canvas_html,
    v_page.canvas_css, v_page.page_settings, auth.uid()
  )
  RETURNING id INTO v_template_id;

  RETURN v_template_id;
END;
$$;

REVOKE ALL ON FUNCTION public.save_web_page_as_template(uuid, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_web_page_as_template(uuid, text, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/save_workflow_node_run.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION save_workflow_node_run(
  p_run_id uuid,
  p_node_id text,
  p_node_type text,
  p_agent_name text DEFAULT NULL,
  p_status text DEFAULT 'completed',
  p_input_data jsonb DEFAULT NULL,
  p_output_data jsonb DEFAULT NULL,
  p_transition_key text DEFAULT NULL,
  p_started_at timestamptz DEFAULT NULL,
  p_ended_at timestamptz DEFAULT NULL,
  p_duration_ms integer DEFAULT NULL,
  p_tokens_input integer DEFAULT 0,
  p_tokens_output integer DEFAULT 0,
  p_error_message text DEFAULT NULL,
  p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id uuid;
  v_is_service_role BOOLEAN;
BEGIN
  v_is_service_role := public.is_service_role();

  IF auth.uid() IS NULL AND NOT v_is_service_role THEN
    RAISE EXCEPTION 'Access denied: authentication required';
  END IF;

  INSERT INTO ai_workflow_node_runs (
    run_id, node_id, node_type, agent_name, status,
    input_data, output_data, transition_key,
    started_at, ended_at, duration_ms,
    tokens_input, tokens_output,
    error_message, metadata
  )
  VALUES (
    p_run_id, p_node_id, p_node_type, p_agent_name, p_status,
    p_input_data, p_output_data, p_transition_key,
    p_started_at, p_ended_at, p_duration_ms,
    p_tokens_input, p_tokens_output,
    p_error_message, p_metadata
  )
  RETURNING ai_workflow_node_runs.id INTO v_id;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION save_workflow_node_run(uuid, text, text, text, text, jsonb, jsonb, text, timestamptz, timestamptz, integer, integer, integer, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION save_workflow_node_run(uuid, text, text, text, text, jsonb, jsonb, text, timestamptz, timestamptz, integer, integer, integer, text, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/scope_applied.sql
-- -----------------------------------------------------------------------------

-- scope_applied — the block's OWN statement that it honoured a lens coordinate.
--
-- The extranet lens (surface_scope_axes, get_scope_options) sends the picked
-- value to EVERY block of the section as p_params->>'<dim>'. A block whose data
-- RPC does not read that key used to answer with ALL rows, looking exactly like a
-- filtered one — measured 2026-09-28 on the contracts section: 5 of 10 blocks
-- (units, tenants, the contracts KPI, identification, obligations) ignored the
-- company and the operator could not tell. "A filter that shows and does nothing
-- is worse than no filter" (see scope_effective, the vouching half).
--
-- WHY THE RPC SAYS IT, NOT A DECLARATION: whether a block honours a dim can
-- depend on the block's configuration (get_twin_register honours owner_company
-- only when source_params.scope_map maps it), so a per-RPC capability flag would
-- lie for one of two blocks sharing the RPC. The RPC calls this ONLY in the branch
-- where it actually filtered; the client compares its lens with
-- provenance.scope_effective and labels every block that stayed silent.
--
-- Shape is the existing contract coordinate (packages/surface-blocks schemas.ts
-- scopeCoordinate): origin 'user_pick' — the lens is the only producer of these
-- keys — and resolver 'none': this RPC matched a value, it did not vouch for a
-- node (that is scope_effective's job).
--
-- Returns {} when the dim is absent or blank, so `provenance || scope_applied(…)`
-- leaves an unscoped call byte-identical.
--
-- Contract: (jsonb, text) -> jsonb {} | {scope_effective:[coordinate]}.
create or replace function public.scope_applied(p_params jsonb, p_dim text)
returns jsonb
language sql
immutable
set search_path = public, pg_temp
as $$
  select case
    -- Same emptiness test as the consumers (`nullif(p_params->>'<dim>', '')`),
    -- so "filtered" and "reported as filtered" can never disagree.
    when nullif(p_params->>p_dim, '') is null then '{}'::jsonb
    else jsonb_build_object('scope_effective', jsonb_build_array(jsonb_build_object(
           'dim',        p_dim,
           'value',      p_params->>p_dim,
           'origin',     'user_pick',
           'confidence', 1,
           'resolver',   'none')))
  end;
$$;

comment on function public.scope_applied(jsonb, text) is
  'Provenance fragment a data RPC appends when it FILTERED by lens dim p_dim: {scope_effective:[{dim,value,origin:user_pick,confidence:1,resolver:none}]}, or {} when the dim is absent. The client labels blocks that do not return it as unfiltered.';

revoke all on function public.scope_applied(jsonb, text) from public, anon;
grant execute on function public.scope_applied(jsonb, text) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_doc_expiry_review_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_doc_expiry_review_block
-- Popis: GENERICKÝ blok `table` — platnosti dokladů z JEJICH VLASTNÍCH POLÍ:
--        doklady daného typu, které nesou datum v poli `date_field`, seřazené
--        od toho nejbližšího dnešku („končí nejdřív", resp. „skončilo nedávno").
--        Řádek otevírá detail dokladu (`row_kind: document`, `id` = doc_slug,
--        týž klíč jako registr dokladů).
--
-- ⛔ PROČ NAD POLI DOKLADU, A NE NAD VAZBAMI NA TWINY (naměřeno 2026-09-23 na
--   produkci, analýza smluv v2 §C a §5):
--   Do 2026-09-24 funkce četla `twin_external_refs` (source `li-contracts`) a
--   spojovala je přes `li.id::text = source_key`. Takové vazby v provozu NEJSOU
--   (0) a žádný zapisovatel je nevyrábí — bloky sm_expiry a pd_recommend proto
--   nemohly ukázat NIC a musely být schovány (idata #100). Vazby smlouva↔firma
--   sice existují (185 návrhů „nájemce smlouvy"), ale jsou jen NAVRŽENÉ a
--   většinou chybné (TZÚS jako nájemce bytů); přepojit blok na ně by ukázalo
--   špatné nájemce jako fakt. Datum platnosti přitom smlouva nese sama
--   (`fields.valid_to`, 141 z 813). Protistrana se proto ukazuje TAK, JAK JI
--   UVÁDÍ DOKLAD — stejně jako v registru dokladů (get_document_register),
--   aby celé prostředí mluvilo o protistraně jedním způsobem.
--
--   Zároveň vypadla heuristika „následný doklad" (filename ILIKE '%<první slovo
--   labelu twinu>%'): stála na labelu twinu, který tu už není, a na slově
--   z názvu souboru se nedá poctivě rozhodnout, že smlouva má dodatek.
--
-- ⭐ ČERSTVOST Z DAT (vzor get_twin_metric_kpi_block, #1052): `freshness_at` =
--   nejnovější `created_at` v univerzu bloku (NE `ingested_at` — ten přepisuje každý import,
--   naměřeno 2026-09-27: 813 smluv = jediný čas; pořadí: čas ze zdroje › příchod verze), spočtený VE STEJNÉM DOTAZU jako
--   řádky. Prázdné univerzum → `now()` JEN jako záloha a `trace_id` končí
--   `:no_data`, aby se prázdno nedalo číst jako čerstvé „nic nekončí".
--
-- Konfigurace (p_params):
--   doc_type        POVINNÉ   li_source_registry.doc_type (např. contract)
--   date_field      POVINNÉ   klíč v li_source_registry.fields (např. valid_to)
--   direction       volitelné 'upcoming' (výchozí: datum ≥ dnes, nejbližší první)
--                             | 'expired' (datum < dnes, naposledy skončené první,
--                             se sloupcem počtu dní po skončení)
--   owner_company   volitelné pohled podle firmy — TÝŽ parametr, jaký posílá
--                             přepínač nad sekcí registru dokladů
--   date_label_key  volitelné klíč překladu hlavičky data (výchozí app.cols.valid_to)
--   limit           volitelné počet řádků (výchozí 100, strop 500)
--   Dřívější klíče (source, entity_type, absent_doc_type, title_template, …)
--   funkce nečte; jejich přítomnost nevadí.
--
-- Vzniklo vykostěním get_porada_recommendations (07-25); přestavěno 2026-09-24.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_doc_expiry_review_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
-- ⛔ SECURITY INVOKER, NE DEFINER — sesterská oprava k get_twin_ref_review_block
-- (bezpečnostní oprava 2026-07-31). Jako DEFINER obcházela RLS nad
-- li_source_registry a pouštěla data každému PŘIHLÁŠENÉMU.
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  with cfg as (
    select nullif(btrim(p_params->>'doc_type'), '')      as dtype,
           nullif(btrim(p_params->>'date_field'), '')    as dfield,
           case lower(coalesce(nullif(btrim(p_params->>'direction'), ''), 'upcoming'))
             when 'upcoming' then 'upcoming'
             when 'expired'  then 'expired'
           end                                           as dir,
           nullif(btrim(p_params->>'owner_company'), '') as owner,
           coalesce(nullif(btrim(p_params->>'date_label_key'), ''), 'app.cols.valid_to') as date_label,
           least(greatest(coalesce(nullif(p_params->>'limit', '')::int, 100), 1), 500) as lim
  ),
  univerzum as (
    -- Datum z OCR se bere, jen když je to SKUTEČNÉ datum ve tvaru ISO. CASE drží
    -- pořadí vyhodnocení: přetypování `'2026-02-30'::date` by jinak shodilo celý
    -- blok, kdyby plánovač podmínku `vdate >= dnes` vyhodnotil před kontrolou.
    select r.doc_slug                                          as id,
           coalesce(r.fields->'counterparty'->>'value', '—')   as counterparty,
           coalesce(r.filename, r.doc_slug)                    as filename,
           coalesce(r.fields->'owner_company'->>'value', '—')  as owner_company,
           case
             when (r.fields->cfg.dfield->>'value') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(r.fields->cfg.dfield->>'value', 'date')
             then (r.fields->cfg.dfield->>'value')::date
           end                                                 as vdate,
           r.created_at
    from li_source_registry r
    cross join cfg
    where r.superseded_by is null
      and r.doc_slug is not null
      and r.doc_type = cfg.dtype
      and (cfg.owner is null or r.fields->'owner_company'->>'value' = cfg.owner)
  ),
  s_datem as (
    select * from univerzum where vdate is not null
  ),
  vybrane as (
    select s.*
    from s_datem s
    cross join cfg
    where (cfg.dir = 'upcoming' and s.vdate >= current_date)
       or (cfg.dir = 'expired'  and s.vdate <  current_date)
    -- Nejbližší dnešku první v obou směrech: co končí nejdřív / co skončilo naposledy.
    order by abs(s.vdate - current_date), s.id
    limit (select lim from cfg)
  ),
  cerstvost as (
    select max(created_at) as fresh from s_datem
  ),
  sloupce as (
    select jsonb_build_array(
             jsonb_build_object('key', 'counterparty',  'label_key', 'app.wb.col.counterparty'),
             jsonb_build_object('key', 'filename',      'label_key', 'app.wb.col.filename'),
             jsonb_build_object('key', 'owner_company', 'label_key', 'app.wb.col.owner_company'),
             jsonb_build_object('key', 'date',          'label_key', cfg.date_label, 'align', 'right'))
           || case when cfg.dir = 'expired' then jsonb_build_array(
             jsonb_build_object('key', 'days',          'label_key', 'app.cols.days_expired', 'align', 'right'))
              else '[]'::jsonb end as c
    from cfg
  )
  select case
    -- ⛔ NÁROK, NE JEN PŘIHLÁŠENÍ (naměřeno 2026-09-11): blok čte smlouvy celého
    -- podniku; guard ověřoval jen přihlášení, takže je viděl kterýkoli řidič.
    -- Odmítnutí i chybějící konfigurace vydají PLATNOU prázdnou tabulku
    -- (`columns: []` je podle kontraktu poctivé „o ničem") — důvod nese `trace_id`.
    when not (public.is_admin_or_staff() or public.is_service_role()) then
      jsonb_build_object('data', jsonb_build_object('columns', '[]'::jsonb, 'rows', '[]'::jsonb,
          'row_kind', 'document'),
        'provenance', jsonb_build_object(
          'source_slug', 'li-source-registry',
          'trace_id', 'doc-expiry:unauthenticated',
          'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')))
    when (select dtype from cfg) is null or (select dfield from cfg) is null
      or (select dir from cfg) is null then
      jsonb_build_object('data', jsonb_build_object('columns', '[]'::jsonb, 'rows', '[]'::jsonb,
          'row_kind', 'document'),
        'provenance', jsonb_build_object(
          'source_slug', 'li-source-registry',
          'trace_id', 'doc-expiry:missing_config',
          'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')))
    else jsonb_build_object(
      'data', jsonb_build_object(
        'columns', (select c from sloupce),
        'row_kind', 'document',
        'rows', coalesce(
          (select jsonb_agg(
                    jsonb_build_object(
                      'id', v.id,
                      'counterparty', v.counterparty,
                      'filename', v.filename,
                      'owner_company', v.owner_company,
                      'date', to_char(v.vdate, 'YYYY-MM-DD'))
                    || case when (select dir from cfg) = 'expired'
                         then jsonb_build_object('days', current_date - v.vdate)
                         else '{}'::jsonb end
                    order by abs(v.vdate - current_date), v.id)
           from vybrane v), '[]'::jsonb)),
      'provenance', jsonb_build_object(
        'source_slug', 'li-source-registry',
        'trace_id', 'doc-expiry:' || (select dtype from cfg) || ':' || (select dir from cfg)
                    || case when (select fresh from cerstvost) is null then ':no_data' else '' end,
        'freshness_at', to_char(coalesce((select fresh from cerstvost), now()) at time zone 'UTC',
                                'YYYY-MM-DD"T"HH24:MI:SS"Z"'))
        || public.scope_applied(p_params, 'owner_company'))
  end;
$$;

REVOKE ALL ON FUNCTION public.get_doc_expiry_review_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_doc_expiry_review_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_doc_expiry_review_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_document_digest.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'kpi_tile' block: one headline count for the document-management
-- console, over the local-ingest evidence silo. SECURITY INVOKER — li_* RLS decides
-- what the operator can count. The metric is chosen by p_params->>'metric' (seeded
-- per block via source_params):
--   'registered'     — valid (non-superseded) documents in li_source_registry
--   'pending_review' — docs still in REVIEW + obligations still NEEDS_REVIEW
--                      (the actionable backlog)
--   'contracts'      — documents of the contractual evidence class
--   'findings'       — deterministic cross-document findings (li_findings)
-- Unknown metric → pending_review (the safe actionable default).
-- Contract: (jsonb) -> jsonb {data:{value,state?}, provenance}.

-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, 2026-09-27): `freshness_at` = nejnovější čas
-- univerza bloku, spočtený ze STEJNÝCH řádků jako hodnota. Pořadí zdrojů času: čas ze zdroje
-- (u Money `source_modified_at`, až bude úplný; u jízd/událostí `occurred_at`) › příchod verze
-- dokladu (`created_at`). NE `ingested_at`/`updated_at` — ty přepisuje KAŽDÝ import (naměřeno
-- 2026-09-27: 813 smluv = jediný čas), takže by lhaly jako faktury zamrzlé na exportu ze 6. 8.
-- Hranice `created_at`: backfill starých dokladů má čas dnešní — pravda o příchodu, ne o obsahu.
-- Prázdné univerzum → `trace_id` nese `:no_data` a čas je jen záloha `coalesce(…, now())`.
-- Stav linky (běží/neběží) sem NEPATŘÍ — je to jiný signál.
-- ⭐ OSA „PODLE FIRMY" (2026-09-28). Blok stál v sekci Smlouvy vedle přehledů, které
-- firmu filtrují, a sám ukazoval celý podnik — pod zvolenou firmou tak dvě čísla vedle
-- sebe mluvila o jiné množině. Firma = `owner_company` v hlavičce dokladu (táž hodnota,
-- jakou nabízí get_scope_options); povinnosti a zjištění patří firmě přes SVŮJ doklad.
-- Bez osy je výsledek bajtově týž jako dřív. Že filtroval, říká blok sám:
-- provenance || scope_applied(…).
create or replace function public.get_document_digest(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with metric as (select coalesce(p_params->>'metric', 'pending_review') as m),
  cfg as (select nullif(p_params->>'owner_company', '') as firma),
  -- Jeden výřez registru pro všechny metriky. Úzké sloupce: CTE čtená víckrát se
  -- materializuje a `select r.*` by kopírovalo raw_data desítek tisíc dokladů.
  reg as (
    select r.source_sha256, r.doc_class, r.status, r.created_at
    from public.li_source_registry r, cfg
    where r.superseded_by is null
      and (cfg.firma is null or r.fields->'owner_company'->>'value' = cfg.firma)
  ),
  obl as (
    select o.candidate_status, o.created_at
    from public.li_obligations o, cfg
    where cfg.firma is null
       or exists (select 1 from reg where reg.source_sha256 = o.source_sha256)
  ),
  fnd as (
    select f.created_at
    from public.li_findings f, cfg
    where cfg.firma is null
       or exists (select 1 from jsonb_array_elements(f.documents) d
                   join reg on reg.source_sha256 = d->>'source_sha256')
  ),
  v as (
    select case (select m from metric)
      when 'registered' then
        (select count(*) from reg)
      when 'contracts' then
        (select count(*) from reg where doc_class = 'contractual')
      when 'findings' then
        (select count(*) from fnd)
      else /* pending_review */ (
          (select count(*) from reg where status = 'REVIEW')
        + (select count(*) from obl where candidate_status = 'NEEDS_REVIEW')
      )
    end as value
  ),
  f as (
    select case (select m from metric)
      when 'registered' then
        (select max(created_at) from reg)
      when 'contracts' then
        (select max(created_at) from reg where doc_class = 'contractual')
      when 'findings' then
        (select max(created_at) from fnd)
      else greatest(
          (select max(created_at) from reg where status = 'REVIEW'),
          (select max(created_at) from obl where candidate_status = 'NEEDS_REVIEW'))
    end as fresh
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'value', v.value,
      -- Only the actionable backlog gets a warning tint; other metrics stay neutral.
      'state', case when (select m from metric) = 'pending_review' and v.value > 0 then 'warning' else 'ok' end
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'li-evidence-registry',
      'freshness_at', to_char(coalesce((select fresh from f), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'doc-digest:' || (select m from metric)
                      || case when (select fresh from f) is null then ':no_data' else '' end
    ) || public.scope_applied(p_params, 'owner_company')
  )
  from v;
$$;

revoke all on function public.get_document_digest(jsonb) from public, anon;
grant execute on function public.get_document_digest(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_document_register.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'table' block: the document register from the local-ingest
-- evidence silo (li_source_registry). SECURITY INVOKER — li_source_registry RLS
-- (is_admin_or_staff, RPC-only lockdown) decides visibility; a caller without a
-- grant sees an empty table, never an error (existence is not leaked).
--
-- Reads li_source_registry (what ingest actually fills via li_upsert_source_registry),
-- NOT the generic document_registry (which has no writer — the surface DRAFT pointed
-- there and would have rendered an empty console over real evidence). The per-field
-- authoritative shape lives in li_source_registry.fields
--   { <key>: { value, raw, confidence, status, source_span:{char_start,char_end,page} } }.
--
-- Contract: (jsonb) -> jsonb {data:{columns,rows}, provenance{source_slug,freshness_at,trace_id}}.
-- Each row carries `id` = doc_slug — the content identity li keys everything on
-- (obligations.doc_slug, links.from_slug); the workbench opens detail/obligations by it.
-- Optional filter p_params->>'doc_type'. Superseded versions (superseded_by not null) are excluded.

create or replace function public.get_document_register(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with rows as (
    select
      r.doc_slug                                        as id,
      r.doc_type                                        as doc_type,
      coalesce(r.filename, r.doc_slug)                  as filename,
      coalesce(r.fields->'counterparty'->>'value', '—') as counterparty,
      -- ZA KTEROU Z NAŠICH FIREM doklad je. Bez toho sloupce se v knize faktur
      -- nepozná, čí ta faktura vlastně je — a u portfolia víc firem je to první
      -- otázka, ne detail.
      coalesce(r.fields->'owner_company'->>'value', '—') as owner_company,
      -- STAV ÚHRADY. Pravdu nese `amount_unpaid` (Money UhradyZbyva): 0 = uhrazeno,
      -- > 0 = dluh. NIKOLI `settled` — to je PriznakVyrizeno a u uhrazené faktury
      -- bývá False. Doklad, který stav úhrady vůbec nenese (starší korpus), říká
      -- „?" a NE „neuhrazeno": mlčet je správnější než tvrdit dluh z pole, které
      -- o platbě nic neví.
      case
        when not (r.fields ? 'amount_unpaid') then '?'
        when (r.fields->'amount_unpaid'->>'value') !~ '^-?[0-9]+(\.[0-9]+)?$' then '?'
        when (r.fields->'amount_unpaid'->>'value')::numeric <= 0.005 then 'ano'
        else 'ne'
      end                                                as paid,
      r.status                                          as status,
      cardinality(r.missing_required)                   as missing,
      to_char(r.ingested_at, 'YYYY-MM-DD')              as ingested,
      r.ingested_at                                     as _sort
    from public.li_source_registry r
    where r.superseded_by is null
      and (p_params->>'doc_type' is null or r.doc_type = p_params->>'doc_type')
      -- Pohled podle firmy: týž parametr, jaký posílá přepínač nad sekcí.
      and (nullif(p_params->>'owner_company','') is null
           or r.fields->'owner_company'->>'value' = p_params->>'owner_company')
    order by r.ingested_at desc
    -- STROP, protože registr roste a tabulka na obrazovce ne. Naměřeno na
    -- produkci 2026-07-31 (surface-timing, identita extranet-test-admin) hned po
    -- nasazení sekce „Smlouvy a nájmy": blok `sm_invoices` vrátil 23 739 řádků
    -- = 5,06 MB / 727 ms v JEDNÉ odpovědi. Doklad má ve wire formátu ~220 B,
    -- takže „vrátíme všechno" je linie rostoucí s korpusem bez konce — ne
    -- vlastnost. Default 500 unese i telefon; kdo chce jinak, řekne si o to
    -- v source_params bloku (limit je DATA, ne konstanta v kódu). 5 000 je tvrdá
    -- pojistka: nad ní to není tabulka k prohlížení, ale export — a ten má
    -- vlastní cestu.
    limit least(coalesce(nullif(p_params->>'limit', '')::int, 500), 5000)
    offset greatest(coalesce(nullif(p_params->>'offset', '')::int, 0), 0)
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'columns', jsonb_build_array(
        jsonb_build_object('key', 'doc_type',     'label_key', 'app.wb.col.doc_type'),
        jsonb_build_object('key', 'filename',     'label_key', 'app.wb.col.filename'),
        jsonb_build_object('key', 'counterparty', 'label_key', 'app.wb.col.counterparty'),
        jsonb_build_object('key', 'owner_company','label_key', 'app.wb.col.owner_company'),
        jsonb_build_object('key', 'paid',         'label_key', 'app.wb.col.paid', 'align', 'center'),
        jsonb_build_object('key', 'status',       'label_key', 'app.wb.col.status',  'align', 'center'),
        jsonb_build_object('key', 'missing',      'label_key', 'app.wb.col.missing',  'align', 'right'),
        jsonb_build_object('key', 'ingested',     'label_key', 'app.wb.col.ingested', 'align', 'right')
      ),
      -- Druh se říká VÝSLOVNĚ, i když je shodný s výchozím: mlčení by
      -- znamenalo, že se na chování spoléhá, aniž by to kdokoli deklaroval.
      'row_kind', 'document',
      'rows', coalesce(jsonb_agg(to_jsonb(rows) - '_sort'), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'li-source-registry',
      'freshness_at', to_char(coalesce(max(rows._sort), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'doc-register'
    ) || public.scope_applied(p_params, 'owner_company')
  )
  from rows;
$$;

revoke all on function public.get_document_register(jsonb) from public, anon;
grant execute on function public.get_document_register(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_ingest_recap.sql
-- -----------------------------------------------------------------------------

-- Recap zpracování ingestu: JEDNO RPC, TŘI POHLEDY (p_params->>'view').
--
-- ⛔ PROČ VZNIKLO. Doklady, zjištění i běhy zdrojů v databázi UŽ JSOU — naměřeno
-- 2026-09-05 na produkci: 68 511 dokladů (67 616 AUTO_PASS / 895 REVIEW),
-- 350 zjištění (35 high), 348 závazků, `local-ingest` 2 227 synců. Chybělo jim
-- jediné: okno. Bez něj se člověk o stavu zpracování dozví až tím, že něco
-- nesedí — a `money` má NULA synců od registrace, což tenhle blok ukáže
-- první den.
--
-- Pohledy (source_params.view v bloku):
--   'stav'    — kpi_tile: jedna hlavička podle `metric`
--   'sync'    — table:    per zdroj běží / chybuje / nikdy, poslední úspěch, selhání
--   'by_type' — chart(bar): doklady podle typu; `note` nese počet k revizi
-- Zjištění tu ZÁMĚRNĚ nejsou: mají vlastní masku (`findings`) a RPC
-- `get_evidence_findings` — druhý zdroj téže pravdy by se dřív nebo později
-- rozešel s prvním. Blok `wb_findings` se do sekcí jen UMÍSTÍ.
-- Neznámý pohled → 'stav' (nejméně překvapivý, nic nezamlčí).
--
-- SECURITY INVOKER: o tom, co operátor uvidí, rozhoduje RLS nad li_* a
-- audience_broker_sync_state. Fail-closed na identitu tím platí bez extra kódu.
--
-- ⭐ OSA `owner_company` SE DEKLARUJE, ne mlčky ignoruje: doklady ji nesou
-- v hlavičce (`fields->>'owner_company'`), takže filtr TU dává smysl. Osa
-- areálu se sem VĚDOMĚ nedostala — ingest o areálech nic neví a nabízet
-- filtr, který nic nedělá, je horší než ho nenabídnout.
create or replace function public.get_ingest_recap(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with cfg as (
    select
      coalesce(nullif(p_params->>'view', ''), 'stav')       as v,
      coalesce(nullif(p_params->>'metric', ''), 'doklady')  as metric,
      nullif(p_params->>'owner_company', '')                as firma
  ),
  -- Jeden filtrovaný pohled na registr, ať se podmínka firmy nepíše třikrát.
  reg as (
    select r.*
    from public.li_source_registry r, cfg
    where r.superseded_by is null
      -- ⛔ `fields->>'owner_company'` NENÍ skalár. Doklad nese u každého pole i to,
      -- JAK k hodnotě došel: {raw, value, status, confidence, source_span}. Bez
      -- `->'owner_company'->>'value'` se porovnává celý ten objekt s názvem firmy
      -- a filtr tiše vrací NULU — tedy přesně ta osa bez konzumenta, kvůli které
      -- tenhle blok vzniká. Naměřeno 2026-09-05 při ověřování proti produkci.
      and (cfg.firma is null or r.fields->'owner_company'->>'value' = cfg.firma)
  ),
  stav as (
    select case (select metric from cfg)
      when 'k_revizi'      then (select count(*) from reg where status = 'REVIEW')
      when 'chybi_povinne' then (select count(*) from reg where cardinality(missing_required) > 0)
      -- Zjištění patří firmě přes své doklady (`documents[].source_sha256`); bez
      -- toho by jediné číslo v řadě mluvilo o celém podniku pod zvolenou firmou.
      when 'zjisteni_high' then (select count(*) from public.li_findings f
                                  where f.severity = 'high'
                                    and ((select firma from cfg) is null
                                         or exists (select 1 from jsonb_array_elements(f.documents) d
                                                     join reg on reg.source_sha256 = d->>'source_sha256')))
      else                      (select count(*) from reg)
    end as value
  ),
  typy as (
    select coalesce(doc_type, '—')                    as doc_type,
           count(*)                                   as celkem,
           count(*) filter (where status = 'REVIEW')  as k_revizi
    from reg
    group by coalesce(doc_type, '—')
  )
  select case (select v from cfg)

    when 'sync' then jsonb_build_object(
      'data', jsonb_build_object(
        'columns', jsonb_build_array(
          jsonb_build_object('key','zdroj',   'label_key','app.ingest.col.zdroj',   'align','left'),
          jsonb_build_object('key','stav',    'label_key','app.ingest.col.stav',    'align','left'),
          jsonb_build_object('key','uspech',  'label_key','app.ingest.col.uspech',  'align','left'),
          jsonb_build_object('key','selhani', 'label_key','app.ingest.col.selhani', 'align','right'),
          jsonb_build_object('key','syncu',   'label_key','app.ingest.col.syncu',   'align','right'),
          jsonb_build_object('key','chyba',   'label_key','app.ingest.col.chyba',   'align','left')
        ),
        'row_kind', 'source',
        'rows', coalesce((
          select jsonb_agg(jsonb_build_object(
                   'id',      s.source_slug,
                   'label',   s.source_slug,
                   'zdroj',   s.source_slug,
                   -- ⛔ „Nikdy neběžel" NENÍ totéž co „běží a je v pořádku". Zdroj
                   -- s nulou synců je registrovaný a mrtvý; bez tohohle rozlišení
                   -- by splynul se zdravým.
                   'stav',    case
                                when coalesce(s.total_syncs, 0) = 0 then 'nikdy'
                                when coalesce(s.consecutive_failures, 0) > 0 then 'chybuje'
                                else 'běží'
                              end,
                   'uspech',  coalesce(to_char(s.last_success_at at time zone 'UTC', 'YYYY-MM-DD HH24:MI'), '—'),
                   'selhani', coalesce(s.consecutive_failures, 0),
                   'syncu',   coalesce(s.total_syncs, 0),
                   'chyba',   left(coalesce(s.last_error_message, ''), 80)
                 ) order by coalesce(s.total_syncs, 0), s.source_slug)
          from public.audience_broker_sync_state s
        ), '[]'::jsonb)
      ),
      'provenance', jsonb_build_object(
        'source_slug',  'audience-broker',
        'freshness_at', to_char(coalesce((select max(updated_at) from public.audience_broker_sync_state), now())
                                at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'trace_id',     'ingest-recap:sync'
      )
    )

    when 'by_type' then jsonb_build_object(
      'data', jsonb_build_object(
        'kind', 'bar',
        -- Kontrakt `chart`: uniformní `points` (label, value, pct 0–100, note, state).
        -- `pct` je podíl na celku, aby šířka pruhu odpovídala datům, ne renderu.
        'points', coalesce((
          select jsonb_agg(jsonb_build_object(
                   'label', t.doc_type,
                   'value', t.celkem,
                   -- Podíl 91 smluv na 68 511 dokladech je 0,13 % → `round` dá 0 a pruh
                   -- zmizí, ač řádek existuje. Nenulová hodnota má vždy aspoň 1 %:
                   -- šířka pruhu nesmí tvrdit „nic", když číslo vedle říká 91.
                   'pct',   greatest(1, round(100.0 * t.celkem / nullif((select sum(celkem) from typy), 0))),
                   'note',  case when t.k_revizi > 0 then t.k_revizi || ' k revizi' else null end,
                   'state', case when t.k_revizi > 0 then 'warning' else 'ok' end
                 ) order by t.celkem desc)
          from typy t
        ), '[]'::jsonb)
      ),
      'provenance', jsonb_build_object(
        'source_slug',  'li-evidence-registry',
        'freshness_at', to_char(coalesce((select max(ingested_at) from reg), now())
                                at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'trace_id',     'ingest-recap:by_type'
      ) || public.scope_applied(p_params, 'owner_company')
    )

    else jsonb_build_object(
      'data', jsonb_build_object(
        'value', (select value from stav),
        -- Tint jen tam, kde má člověk co dělat; počet dokladů sám o sobě není poplach.
        'state', case
                   when (select metric from cfg) in ('k_revizi','chybi_povinne','zjisteni_high')
                        and (select value from stav) > 0 then 'warning'
                   else 'ok'
                 end
      ),
      'provenance', jsonb_build_object(
        'source_slug',  'li-evidence-registry',
        'freshness_at', to_char(coalesce((select max(ingested_at) from reg), now())
                                at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'trace_id',     'ingest-recap:' || (select metric from cfg)
      ) || public.scope_applied(p_params, 'owner_company')
    )
  end;
$$;

revoke all on function public.get_ingest_recap(jsonb) from public, anon;
grant execute on function public.get_ingest_recap(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_obligation_queue.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'review_queue' block: obligations awaiting human confirmation,
-- from the local-ingest evidence silo (li_obligations). Legal content is born
-- NEEDS_REVIEW and is never authoritative without a human (li_obligations schema
-- doctrine); this queue is where a reviewer confirms it. SECURITY INVOKER.
--
-- Global on the console; scoped to one document via p_params->>'doc_slug'
-- (or 'document_id' alias). Each item carries `id` = li_obligations.id (uuid) —
-- the entity_id submit_evidence_review_audited('obligation', id, ...) mutates.
-- The verbatim quote + clause_ref travel with every item: without them an
-- obligation is a claim, not evidence (provenance doctrine).
--
-- p_params->>'limit' caps the page (default 100, max 500), newest first. Naměřeno
-- 2026-09-23 na produkci: bez stropu vydávala konzole všech 3 909 závazků =
-- 2,8 MB v jedné odpovědi, v sekci Smlouvy i Workbench, při každém otevření.
-- Pořadí stránky i položek je (ingested_at desc, clause_ref, id) — dřív se
-- výsledek řadil podle náhodného uuid, takže „nejnovější" nebylo nahoře.
--
-- Contract: (jsonb) -> jsonb {data:{entity_kind:'obligation', items[], actions[]}, provenance}.

create or replace function public.get_obligation_queue(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with items as (
    select
      o.id::text                                     as id,
      coalesce(o.action, o.clause_title, o.clause_ref) as title,
      o.quote,
      o.clause_ref,
      o.obliged_party,
      o.deadline_text,
      o.consequence_text,
      o.updated_at,
      o.ingested_at
    from public.li_obligations o
    where o.candidate_status = 'NEEDS_REVIEW'
      and (coalesce(p_params->>'doc_slug', p_params->>'document_id') is null
           or o.doc_slug = coalesce(p_params->>'doc_slug', p_params->>'document_id'))
      -- Osa „podle firmy" (2026-09-28): závazek patří firmě přes SVŮJ doklad. Bez
      -- `superseded_by` záměrně — výřez má být přesná podmnožina fronty bez osy,
      -- a ta ukazuje i závazky ze starší verze dokladu.
      and (nullif(p_params->>'owner_company', '') is null
           or exists (select 1 from public.li_source_registry r
                       where r.source_sha256 = o.source_sha256
                         and r.fields->'owner_company'->>'value' = p_params->>'owner_company'))
    order by o.ingested_at desc nulls last, o.clause_ref, o.id
    limit least(greatest(coalesce(nullif(p_params->>'limit', '')::int, 100), 1), 500)
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'entity_kind', 'obligation',
      'items', coalesce(jsonb_agg(
        jsonb_build_object(
          'id', items.id,
          'title', coalesce(items.title, items.clause_ref),
          'subtitle_key', 'app.wb.review.needs_review',
          'state', 'needs_review',
          'quote', items.quote,
          'fields', jsonb_build_array(
            jsonb_build_object('key', 'obliged_party', 'label_key', 'app.wb.field.obliged_party', 'value', items.obliged_party),
            jsonb_build_object('key', 'deadline',      'label_key', 'app.wb.field.deadline',      'value', items.deadline_text),
            jsonb_build_object('key', 'consequence',   'label_key', 'app.wb.field.consequence',   'value', items.consequence_text),
            jsonb_build_object('key', 'clause',        'label_key', 'app.wb.field.clause',        'value', items.clause_ref)
          )
        )
        order by items.ingested_at desc nulls last, items.clause_ref, items.id
      ), '[]'::jsonb),
      'actions', jsonb_build_array(
        jsonb_build_object('action_key', 'app.wb.action.approve', 'decision', 'HUMAN_CONFIRMED', 'intent', 'approve'),
        jsonb_build_object('action_key', 'app.wb.action.reject',  'decision', 'REJECTED',        'intent', 'reject')
      )
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'li-obligations',
      'freshness_at', to_char(coalesce(max(items.updated_at), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'obligation-queue'
    ) || public.scope_applied(p_params, 'owner_company')
  )
  from items;
$$;

revoke all on function public.get_obligation_queue(jsonb) from public, anon;
grant execute on function public.get_obligation_queue(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_rent_breakdown.sql
-- -----------------------------------------------------------------------------

-- Data RPC pro blok 'table': ROZPAD PŘÍJMŮ ZA NÁJEMCE — nájem / energie / služby.
--
-- Rozpad se NEDÁ číst z hlavičky faktury: přefakturace energií chodí i na
-- SAMOSTATNÉ faktuře, takže jedna hlavička může být celá „energie" a jiná celá
-- „nájem". Pravda je v ŘÁDCÍCH dokladů (`li_source_registry.line_items`) a
-- agregace je přes VŠECHNY doklady jednoho nájemce, ne per faktura.
--
-- ⭐ KLASIFIKACE JE DATA, NE KÓD
-- Které texty řádků znamenají nájem/energie/služby, je vlastnost podniku, ne
-- platformy — a mění se s tím, jak se fakturuje. Vzory proto přicházejí
-- v `p_params.classes` jako pole `{key, label_key, pattern}`; RPC jen aplikuje
-- první shodu v pořadí. Bez konfigurace vrátí všechno jako nezařazené, a to je
-- POCTIVÉ mlčení: prázdný katalog není důvod něco si domyslet.
--
-- ⚠️ POŘADÍ VZORŮ ROZHODUJE a je součástí konfigurace: „spotřeba plynu" je
-- energie, i když na faktuře za nájem; „Poskytnutí sídla" je vlastní kategorie,
-- ne nájem. Naměřeno na korpusu 2026-07-31: bez kontextu faktury je text řádku
-- nejednoznačný — „za měsíc 6/2022" JE nájem, ale samo o sobě to neřekne.
-- Proto se nezařazené drží ZVLÁŠŤ (klíč '?') a nikam se netichu nepřičítají:
-- kbelík „ostatní" s viditelnou částkou je odpověď, tiché rozpuštění lež.
--
-- ⭐ KNIHA FAKTUR ZA MĚSÍC (majitel 2026-09-29, náčrt „Smlouvy a nájmy v2", bod 3):
-- rozpad se dřív sčítal přes VŠECHNY doklady celé historie. Teď umí období
-- (měsíc vystavení) a faktury BEZ položek neztratí: jejich částka z hlavičky jde
-- do sloupce „bez rozpisu" — třídu neznáme, ale částku ano (neznámé ≠ 0, a ne
-- ani „ostatní"). Naměřeno 2026-09-29 (vydané): s položkami 5 797, BEZ 10 822
-- (hlavně starší exporty; od 08/2026 mají položky všechny).
--
-- Sloupce: klient · `trida_<klíč>` pro každou třídu z `classes` (popisek z konfigurace) ·
-- ostatni (řádek bez shody, klíč '?') · bez_rozpisu · celkem · dokladu.
--
-- Konfigurace (p_params):
--   classes          : [{key,label_key,pattern}] — vzory (regex, case-insensitive)
--   owner_company    : jen doklady té firmy (osa pohledu „podle firmy")
--   document_subtype : jen doklady toho druhu (kniha = 'issued', vydané); bez = všechny
--   obdobi_vychozi   : 'aktualni_mesic' = bez volby klienta jen aktuální měsíc;
--                      bez = celá historie (dosavadní chování). Jiná hodnota = chyba.
--   limit            : kolik nájemců (default 50, strop 500)
-- Klientské parametry (deklarace v source_params.client_params, volba uživatele):
--   mesic     : date — měsíc vystavení (kterýkoli den měsíce); přebíjí obdobi_vychozi
--   jen_tridy : ["N","E",…] — jen nájemci s nenulovou částkou v některé z tříd
--
-- SECURITY INVOKER → RLS rozhoduje; bez nároku prázdno, ne chyba.
-- Kontrakt: (jsonb) -> jsonb {data:{columns[], rows[]}, provenance}.

-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, 2026-09-27): `freshness_at` = nejnovější čas
-- univerza bloku, spočtený ze STEJNÝCH řádků jako hodnota. Pořadí zdrojů času: čas ze zdroje
-- (u Money `source_modified_at`, až bude úplný; u jízd/událostí `occurred_at`) › příchod verze
-- dokladu (`created_at`). NE `ingested_at`/`updated_at` — ty přepisuje KAŽDÝ import (naměřeno
-- 2026-09-27: 813 smluv = jediný čas), takže by lhaly jako faktury zamrzlé na exportu ze 6. 8.
-- Hranice `created_at`: backfill starých dokladů má čas dnešní — pravda o příchodu, ne o obsahu.
-- Prázdné univerzum → `trace_id` nese `:no_data` a čas je jen záloha `coalesce(…, now())`.
-- Stav linky (běží/neběží) sem NEPATŘÍ — je to jiný signál.
create or replace function public.get_rent_breakdown(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with cfg as (
    select
      nullif(p_params->>'owner_company','')                          as company,
      nullif(p_params->>'document_subtype','')                       as subtype,
      coalesce(p_params->'classes', '[]'::jsonb)                     as classes,
      least(coalesce(nullif(p_params->>'limit','')::int, 50), 500)   as lim,
      -- období: volba klienta (mesic) › výchozí z konfigurace › celá historie
      public.obdobi_od_param(p_params)                               as mesic_od,
      case when jsonb_typeof(p_params->'jen_tridy') = 'array'
           then array(select jsonb_array_elements_text(p_params->'jen_tridy')) end as jen_tridy
  ),
  -- Doklady období (jedna řádka = jedna faktura), s položkami i bez.
  doklady as (
    select
      r.id,
      r.created_at as vznik,
      coalesce(r.fields->'counterparty'->>'value', '—') as klient,
      -- ⛔ nájemce = IČO, ne jméno (viz get_receivables_overdue): bez IČO jménem
      case when (r.fields->'counterparty_id'->>'value') ~ '^[0-9]{6,8}$'
           then r.fields->'counterparty_id'->>'value' end as ico,
      r.fields->'owner_company'->>'value'               as firma,
      case when (r.fields->'total_amount'->>'value') ~ '^-?[0-9]+(\.[0-9]+)?$'
           then (r.fields->'total_amount'->>'value')::numeric end as hlavicka,
      coalesce(r.line_items, '[]'::jsonb)               as polozky
    from public.li_source_registry r
    cross join cfg
    where r.doc_type = 'invoice'
      and r.superseded_by is null
      and (cfg.company is null or r.fields->'owner_company'->>'value' = cfg.company)
      and (cfg.subtype is null or r.fields->'document_subtype'->>'value' = cfg.subtype)
      and (cfg.mesic_od is null or (
            (r.fields->'issue_date'->>'value') ~ '^\d{4}-\d{2}-\d{2}$'
            and (r.fields->'issue_date'->>'value')::date >= cfg.mesic_od
            and (r.fields->'issue_date'->>'value')::date <  (cfg.mesic_od + interval '1 month')::date))
  ),
  radky as (
    select
      d.id, d.klient, d.ico, d.firma,
      -- ⛔ Řádek NENÍ plochý objekt. Ingest zapisuje každou hodnotu s provenancí
      -- (`{value, raw, gate, span}`) — `li->>'item_name'` vracelo NULL a částka
      -- spadla na 0 ve VŠECH řádcích (naměřeno v produkci 2026-07-31). Nula
      -- z nedosažitelných dat vypadá jako „nájemce nic neplatí".
      li->'fields'->'item_name'->>'value'               as nazev,
      case when (li->'fields'->'line_total'->>'value') ~ '^-?[0-9]+(\.[0-9]+)?$'
           then (li->'fields'->'line_total'->>'value')::numeric else 0 end as castka
    from doklady d
    cross join lateral jsonb_array_elements(d.polozky) li
  ),
  -- První shoda v pořadí vyhrává; bez shody klíč '?' (viditelné „ostatní").
  -- Faktura BEZ položek = třída 'bez' s částkou z hlavičky (třídu neznáme).
  zatridene as (
    select radky.id, radky.klient, radky.ico, radky.firma, radky.castka,
      coalesce((
        select c->>'key'
        from cfg, jsonb_array_elements(cfg.classes) with ordinality t(c, ord)
        where radky.nazev ~* (c->>'pattern')
        order by t.ord
        limit 1), '?') as trida
    from radky
    union all
    select d.id, d.klient, d.ico, d.firma, coalesce(d.hlavicka, 0), 'bez'
    from doklady d
    where jsonb_array_length(d.polozky) = 0
  ),
  -- ⭐ SLOUPCE Z KONFIGURACE (majitel 2026-09-29: třídy U = úroky a penále, S = počáteční
  -- stav): každá třída z `classes` má svůj sloupec `trida_<klíč>` s popiskem z konfigurace
  -- (první výskyt klíče v pořadí). Dřív byly sloupce N/E/P natvrdo a nová třída by se
  -- sečetla jen do „celkem" — neviditelná.
  tridy as (
    select key, label_key, ord from (
      select distinct on (c->>'key') c->>'key' as key, c->>'label_key' as label_key, t.ord
        from cfg, jsonb_array_elements(cfg.classes) with ordinality t(c, ord)
       where nullif(c->>'key', '') is not null
       order by c->>'key', t.ord) x
  ),
  po_tridach as (
    select coalesce(ico, 'jmeno:' || klient) as klic, trida, round(sum(castka))::text as castka
      from zatridene
     where trida in (select key from tridy)
     group by 1, 2
  ),
  souhrn as (
    select
      coalesce(ico, 'jmeno:' || klient)                                   as klic,
      min(klient)                                                         as klient,
      max(ico)                                                            as ico,
      string_agg(distinct firma, ' · ' order by firma)                    as firma,
      round(sum(castka) filter (where trida = '?'))::text                 as ostatni,
      round(sum(castka) filter (where trida = 'bez'))::text               as bez_rozpisu,
      round(sum(castka))::text                                            as celkem,
      count(distinct id)::text                                            as dokladu,
      sum(castka)                                                         as _sort
    from zatridene
    group by coalesce(ico, 'jmeno:' || klient)
    -- jen nájemci s nenulovou částkou v některé z vybraných tříd (volba klienta)
    having (select jen_tridy from cfg) is null
        or coalesce(sum(abs(castka)) filter (where trida = any (((select jen_tridy from cfg))::text[])), 0) > 0.005
    order by sum(castka) desc
    limit (select lim from cfg)
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'columns',
        jsonb_build_array(jsonb_build_object('key','klient', 'label_key','app.cols.counterparty'))
        || coalesce((select jsonb_agg(jsonb_build_object('key', 'trida_' || key, 'label_key', coalesce(label_key, 'app.cols.other'), 'align', 'right') order by ord)
                       from tridy), '[]'::jsonb)
        || jsonb_build_array(
             jsonb_build_object('key','ostatni',     'label_key','app.cols.other',      'align','right'),
             jsonb_build_object('key','bez_rozpisu', 'label_key','app.cols.unitemized', 'align','right'),
             jsonb_build_object('key','celkem',      'label_key','app.cols.total',      'align','right'),
             jsonb_build_object('key','dokladu',     'label_key','app.cols.documents',  'align','right')),
      -- `id` je IČO nájemce (bez IČO jméno) — `get_debtor_invoices` bere IČO
      -- i jméno, týž druh jako u dlužníků. Jméno je AKTUÁLNÍ (counterparty_labels).
      'row_kind', 'counterparty',
      'rows', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'id',          coalesce(s.ico, s.klient),
                 'klient',      coalesce(l.label, s.klient),
                 'ostatni',     coalesce(s.ostatni,'0'),
                 'bez_rozpisu', coalesce(s.bez_rozpisu,'0'),
                 'celkem',      coalesce(s.celkem, '0'),
                 'dokladu',     s.dokladu)
               || coalesce((select jsonb_object_agg('trida_' || t.key, coalesce(p.castka, '0'))
                              from tridy t left join po_tridach p on p.klic = s.klic and p.trida = t.key), '{}'::jsonb)
               order by s._sort desc)
        from souhrn s
        left join public.counterparty_labels((select array_agg(ico) from souhrn)) l on l.ico = s.ico),
        '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'li-source-registry',
      'freshness_at', to_char(coalesce((select max(vznik) from doklady), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'rent-breakdown'
                      || case when (select max(vznik) from doklady) is null then ':no_data' else '' end,
      -- Kolik řádků stojí na IČO (zbytek je klíčovaný jménem = nižší jistota identity:
      -- jméno může nést víc subjektů, a stroj podle jména jen navrhuje).
      'coverage', jsonb_build_object(
        'n', (select count(*) from souhrn where ico is not null),
        'm', (select count(*) from souhrn),
        'label_key', 'app.prov.coverage.with_ico')
    ) || public.scope_applied(p_params, 'owner_company')
  );
$$;

comment on function public.get_rent_breakdown(jsonb) is
  'Rozpad příjmů za NÁJEMCE (ne za fakturu — přefakturace energií chodí zvlášť) z řádků dokladů. Klasifikace přichází v p_params.classes jako vzory = DATA; nezařazené se drží zvlášť pod klíčem ? a nikam se tiše nepřičítají.';

revoke all on function public.get_rent_breakdown(jsonb) from public, anon;
grant execute on function public.get_rent_breakdown(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_twin_ref_review_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_twin_ref_review_block
-- Popis: GENERICKÝ 'review_queue' blok — navržené twin identity vazby
--        k lidské ratifikaci (návrh není zápis). Texty položek se skládají
--        z ŠABLON v konfiguraci bloku — žádná prezentace v kódu.
--
-- Konfigurace (p_params):
--   source            POVINNÉ   twin_external_refs.source
--   title_template    POVINNÉ   placeholdery: {label} {filename} {confidence} {note}
--   quote_template    POVINNÉ   tytéž placeholdery
--   entity_type       volitelné filtr twin_entities.entity_type
--   filename_fallback volitelné text místo chybějícího filename (default '')
--   limit             volitelné počet položek (výchozí 100, strop 500)
--
-- Placeholder sémantika: {confidence} = round(conf*100) · {note} = ' · <note>'
--   nebo prázdno (oddělovač je součást hodnoty, šablona ho nedubluje).
-- Vzniklo vykostěním get_porada_review (07-25).
--
-- ⛔ OBÁLKA review_queue (naměřeno 2026-09-15): funkce vracela jen {items}.
-- Maska review_queue vyžaduje {entity_kind, items, actions} (packages/
-- surface-blocks/src/schemas.ts) — klient takový blok ZAHODIL, takže 907
-- návrhů identit z ingestu Raynetu správce nikdy neviděl, a i kdyby, neměl
-- by čím rozhodnout. Brána kontraktu to nechytila: bez konfigurace funkce
-- vracela {items:[]}, což měřidlo zařadilo jako „nemíří na žádnou masku".
-- Teď nese obálku KAŽDÁ větev; akce jsou tytéž jako u sesterské
-- get_twin_identity_queue a zápis jde přes submit_evidence_review_audited
-- (entity_kind 'twin_identity' → twin_identity_confirm/reject_binding).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_twin_ref_review_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
-- ⛔ SECURITY INVOKER, NE DEFINER (bezpečnostní oprava 2026-07-31).
-- Jako DEFINER běžela funkce pod právy vlastníka → RLS nad twin_external_refs
-- a li_source_registry se NEUPLATNILA a jediný guard byl `auth.uid() is null`,
-- tedy pouhé PŘIHLÁŠENÍ. Změřeno na produkci: uživatel BEZ JAKÝCHKOLI ROLÍ
-- dostal přes blok pd_review 14 položek twin identity návrhů (jména reálných
-- protistran), zatímco sesterské bloky nad týmiž daty (get_document_register,
-- get_obligation_queue, get_evidence_findings — všechny INVOKER) mu správně
-- vracely prázdno. Dva bloky z pěti tedy obcházely nárok.
-- Po přepnutí (změřeno v rollback transakci): bez rolí 0 · admin 14 (beze změny).
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  with akce as (
    -- Tytéž rozhodnutí jako get_twin_identity_queue; dispečer je přeloží
    -- na twin_identity_confirm_binding / twin_identity_reject_binding.
    select jsonb_build_array(
      jsonb_build_object('action_key', 'app.twins.action.confirm', 'decision', 'confirmed', 'intent', 'approve'),
      jsonb_build_object('action_key', 'app.twins.action.reject',  'decision', 'rejected',  'intent', 'reject')
    ) as a
  ),
  cfg as (
    select p_params->>'source' as src,
           p_params->>'entity_type' as etype,
           p_params->>'title_template' as t_tpl,
           p_params->>'quote_template' as q_tpl,
           coalesce(p_params->>'filename_fallback', '') as f_fb,
           least(greatest(coalesce(nullif(p_params->>'limit', '')::int, 100), 1), 500) as lim,
           -- Osa „podle firmy" (2026-09-28) jen tam, kde ji konfigurace bloku zapne
           -- (`scope_map.owner_company.via = 'document'`): návrh patří firmě přes
           -- doklad, ze kterého vzešel. Návrhy BEZ dokladu (např. „naše firma" z agendy
           -- Money) by filtr vyprázdnil — takový blok osu nezapíná a klient ho označí
           -- jako nefiltrovaný, místo aby mlčky ukázal nic.
           nullif(p_params->>'owner_company', '') as firma,
           p_params#>>'{scope_map,owner_company,via}' = 'document' as po_dokladu
  ),
  items as (
    select r.id, r.confidence as conf,
           replace(replace(replace(replace((select t_tpl from cfg),
             '{label}', coalesce(c.label, '')),
             '{filename}', coalesce(li.filename, (select f_fb from cfg))),
             '{confidence}', round(coalesce(r.confidence, 0) * 100)::text),
             '{note}', coalesce(' · ' || r.note, '')) as title,
           replace(replace(replace(replace((select q_tpl from cfg),
             '{label}', coalesce(c.label, '')),
             '{filename}', coalesce(li.filename, (select f_fb from cfg))),
             '{confidence}', round(coalesce(r.confidence, 0) * 100)::text),
             '{note}', coalesce(' · ' || r.note, '')) as quote
    from twin_external_refs r
    join twin_entities c on c.id = r.twin_id
      and ((select etype from cfg) is null or c.entity_type = (select etype from cfg))
    -- Dokument se dohledá OBĚMA identitami, které návrhy nosí: platformní UUID
    -- (porada lane) i content-addressed sha256 (promoce z ingestu — engine
    -- platformní UUID nezná a znát nemá; sha je identita dokladu napříč světy).
    --
    -- ⛔ DVA JOINY, NE JEDEN S `OR` (naměřeno 2026-09-23 na produkci): blok
    -- `sm_identifikace` (source local-ingest, tisíce návrhů) neodpověděl do 30 s
    -- a držel kostru celé sekce Smlouvy ~20 s. `id::text = k OR source_sha256 = k`
    -- nesmí použít ani funkční index na id::text, ani unikátní index na
    -- source_sha256 — plánovač porovná každý návrh s každým dokladem. Každá
    -- identita zvlášť jde po svém indexu.
    left join li_source_registry li_id  on li_id.id::text = r.source_key
    left join li_source_registry li_sha on li_sha.source_sha256 = r.source_key
    cross join lateral (select coalesce(li_id.filename, li_sha.filename) as filename) li
    where r.source = (select src from cfg)
      and r.state = 'proposed'
      and ((select firma from cfg) is null
           or (select po_dokladu from cfg) is not true
           or coalesce(li_id.fields, li_sha.fields)->'owner_company'->>'value' = (select firma from cfg))
  ),
  -- Fronta k ratifikaci je pracovní seznam, ne export: bez stropu vydala VŠECHNY
  -- návrhy zdroje (tisíce položek) v jedné odpovědi.
  vybrane as (
    select * from items order by conf desc nulls last, id limit (select lim from cfg)
  )
  select case
    -- ⛔ NÁROK, NE JEN PŘIHLÁŠENÍ (naměřeno 2026-09-11): ratifikace vazeb je práce
    -- správce; guard ověřoval jen přihlášení, takže ji viděl kterýkoli řidič.
    when not (public.is_admin_or_staff() or public.is_service_role()) then
      -- ⭐ Provenance je UZAVŘENÁ na {source_slug, trace_id, freshness_at} —
      -- `error` ji poruší a klient zahodí CELÝ blok, takže se přiznání
      -- k uživateli nikdy nedostane (týž nález jako u get_twin_ref_pending_block
      -- a get_doc_expiry_review_block). Důvod patří do `trace_id`.
      -- Do 2026-09-12 tahle větev nevadila, protože na ni dosáhl jen
      -- NEPŘIHLÁŠENÝ; od zpřísnění guardu na nárok ji potká každý běžný člen.
      jsonb_build_object('data', jsonb_build_object('entity_kind', 'twin_identity', 'items', '[]'::jsonb,
          'actions', (select a from akce)),
        'provenance', jsonb_build_object('source_slug', 'twin-identity',
          'trace_id', 'twin-ref-review:unauthenticated', 'freshness_at', now()))
    when (select src from cfg) is null
      or (select t_tpl from cfg) is null or (select q_tpl from cfg) is null then
      jsonb_build_object('data', jsonb_build_object('entity_kind', 'twin_identity', 'items', '[]'::jsonb,
          'actions', (select a from akce)),
        'provenance', jsonb_build_object('source_slug', 'twin-identity',
          'trace_id', 'twin-ref-review:missing_config', 'freshness_at', now()))
    else jsonb_build_object(
      'data', jsonb_build_object('entity_kind', 'twin_identity', 'items', coalesce(
        (select jsonb_agg(jsonb_build_object('id', id, 'title', title, 'quote', quote)
                          order by conf desc nulls last, id) from vybrane), '[]'::jsonb),
        'actions', (select a from akce)),
      'provenance', jsonb_build_object('source_slug', 'twin-identity',
        'trace_id', 'twin-ref-review:' || (select src from cfg), 'freshness_at', now())
        || case when (select po_dokladu from cfg) then public.scope_applied(p_params, 'owner_company')
                else '{}'::jsonb end)
  end;
$$;

REVOKE ALL ON FUNCTION public.get_twin_ref_review_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_twin_ref_review_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_twin_ref_review_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/scope_normalize.sql
-- -----------------------------------------------------------------------------

-- scope_normalize — canonical form of a SCOPE VECTOR.
--
-- A scope is a vector, not a boolean filter: an ordered set of coordinates
--   {dim, value, origin, confidence, detail?}
-- naming WHICH node the reader stands on and — the part that carries
-- accountability — WHO supplied that coordinate.
--
-- WHY A VECTOR AND NOT A FILTER STRING: with a filter you can only ask "is it
-- on"; with a vector you can ask "who says so, and how sure are they". Those are
-- the two questions an answer has to survive a month later. The alternative
-- (scope guessed per call from the wording of a question) is already measured in
-- this repo: answer_verified_facts picks a company by matching tokens of 1194
-- twin labels against the question text, which is how "kolik je hodin?" returned
-- a tenant overview with coverage FULL (production, 2026-07-29). Two sources of
-- truth about scope is noise by construction, and the accidental one wins.
--
-- WHY `origin` IS CLOSED: responsibility cannot be an open string. A coordinate
-- the user picked, one a detector derived and one guessed from wording are three
-- different liabilities, and only a closed vocabulary keeps them apart in the
-- record. The free-text specifics (which detector, which heuristic) ride in
-- `detail`, so naming them never dilutes the four responsibilities.
-- `dim` is open text for the mirror reason: a new axis must be DATA (a row, a
-- derivation), never a release — same doctrine as surface_layouts.surface.
--
-- STRICT, NOT FORGIVING: an unparsable coordinate raises. A scope that silently
-- drops what it did not understand would let the UI claim a narrowing that never
-- happened — the failure class this whole mechanism exists to prevent.
--
-- INPUT SANITATION: `resolver` is an OUTPUT of scope_effective and is stripped
-- here. The caller controls p_params, so a caller-supplied "resolver":"twin"
-- would be a claim of having been vouched for, made by the party that needs
-- vouching.

create or replace function public.scope_normalize(p_scope jsonb default '[]'::jsonb)
returns jsonb
language plpgsql
immutable
set search_path = public, pg_temp
as $$
declare
  v_in    jsonb := coalesce(p_scope, '[]'::jsonb);
  v_c     jsonb;
  v_dim   text;
  v_value text;
  v_origin text;
  v_conf  numeric;
  v_out   jsonb := '[]'::jsonb;
begin
  -- An empty object is the natural "no scope" a JSON client sends; treat it as
  -- the empty vector rather than an error, but anything else non-array is a bug
  -- in the caller and says so.
  if v_in = '{}'::jsonb or v_in = 'null'::jsonb then
    return '[]'::jsonb;
  end if;
  if jsonb_typeof(v_in) <> 'array' then
    raise exception 'scope_normalize: scope must be a JSON array of coordinates, got %', jsonb_typeof(v_in)
      using errcode = '22023';
  end if;

  for v_c in select value from jsonb_array_elements(v_in) loop
    if jsonb_typeof(v_c) <> 'object' then
      raise exception 'scope_normalize: coordinate must be an object, got %', jsonb_typeof(v_c)
        using errcode = '22023';
    end if;

    v_dim   := btrim(coalesce(v_c->>'dim', ''));
    v_value := btrim(coalesce(v_c->>'value', ''));
    v_origin := coalesce(nullif(btrim(coalesce(v_c->>'origin', '')), ''), 'user_pick');

    if v_dim !~ '^[a-z][a-z0-9_]*$' then
      raise exception 'scope_normalize: dim % is not a slug ([a-z][a-z0-9_]*)', coalesce(nullif(v_dim, ''), '<empty>')
        using errcode = '22023';
    end if;
    if v_value = '' then
      raise exception 'scope_normalize: coordinate % has an empty value', v_dim using errcode = '22023';
    end if;
    if v_origin not in ('user_pick', 'derived', 'guessed_from_text', 'system') then
      raise exception 'scope_normalize: unknown origin % (closed vocabulary)', v_origin using errcode = '22023';
    end if;

    -- Certainty: a human pick and a platform-imposed coordinate are certain by
    -- definition; a derivation or a guess MUST state how sure it is, because
    -- that number is what a later reader weighs the answer by.
    if v_c ? 'confidence' and jsonb_typeof(v_c->'confidence') = 'number' then
      v_conf := (v_c->>'confidence')::numeric;
    elsif v_origin in ('user_pick', 'system') then
      v_conf := 1.0;
    else
      raise exception 'scope_normalize: origin % on dim % requires an explicit confidence', v_origin, v_dim
        using errcode = '22023';
    end if;
    if v_conf < 0 or v_conf > 1 then
      raise exception 'scope_normalize: confidence % on dim % is outside 0..1', v_conf, v_dim
        using errcode = '22023';
    end if;
    -- A guess is never certain. Allowing 1.0 here would let the weakest origin
    -- masquerade as the strongest and win the dedup below.
    if v_origin = 'guessed_from_text' and v_conf >= 1 then
      raise exception 'scope_normalize: a guessed coordinate (dim %) cannot have confidence 1', v_dim
        using errcode = '22023';
    end if;

    v_out := v_out || jsonb_build_array(
      jsonb_build_object('dim', v_dim, 'value', v_value, 'origin', v_origin, 'confidence', v_conf)
      || case when nullif(btrim(coalesce(v_c->>'detail', '')), '') is null
              then '{}'::jsonb
              else jsonb_build_object('detail', btrim(v_c->>'detail')) end
    );
  end loop;

  -- ONE coordinate per dimension, and the strongest ORIGIN wins before
  -- confidence does: an explicit human pick outranks a system default, which
  -- outranks a derivation, which outranks a guess. Confidence only breaks ties
  -- inside one origin — otherwise a detector reporting 0.99 could quietly
  -- overrule the person who said "I want to look at this company".
  -- Sorted by dim so the same scope is byte-identical every time: a vector that
  -- is recorded, compared and read back has to be canonical, not merely correct.
  select coalesce(jsonb_agg(c order by c->>'dim'), '[]'::jsonb)
    into v_out
  from (
    select distinct on (c->>'dim') c
    from jsonb_array_elements(v_out) c
    order by c->>'dim',
             case c->>'origin'
               when 'user_pick' then 4 when 'system' then 3
               when 'derived' then 2 else 1 end desc,
             (c->>'confidence')::numeric desc
  ) s(c);

  return v_out;
end;
$$;

comment on function public.scope_normalize(jsonb) is
  'Canonical form of a scope vector: validates {dim,value,origin,confidence}, strips caller-claimed resolver, keeps one coordinate per dim (strongest origin first) and sorts by dim so the vector is byte-stable for recording and comparison.';

revoke all on function public.scope_normalize(jsonb) from public, anon;
grant execute on function public.scope_normalize(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/scope_effective.sql
-- -----------------------------------------------------------------------------

-- scope_effective — THE SINGLE OWNER of the scope rule.
--
-- Every consumer inherits its verdict; nobody re-implements it. That is the
-- whole point: if each RPC applied the scope its own way, then everyone is
-- responsible for it and therefore nobody is. Same pattern as
-- document_visible_to, the single owner of the sensitivity rule — consumers did
-- not change when that landed, and they must not change when this does.
--
-- WHAT IT IS NOT: an authorization input. The caller controls p_params, so a
-- scope can only ever SUBTRACT from what the identity may already see. The real
-- boundary stays where it is (RLS + relations); running SECURITY INVOKER is what
-- makes that structural rather than promised — the visibility probes below
-- execute as the caller, so an invisible row is invisible here too.
--
-- NOT AN EXISTENCE ORACLE: "no such row" and "not yours" collapse into ONE
-- reason, `not_visible`. A distinguishable answer would turn the lens into a
-- probe for rows the caller cannot read — ask for company X, read the reason,
-- learn whether X exists. Same oracle guard as workflow_step_visible_to.
--
-- WHAT VOUCHING MEANS. Three resolvers, chosen by the SHAPE of the value, so no
-- instance vocabulary leaks into the platform:
--   * story — dim = 'story' and the value is a uuid → must be a visible story.
--   * twin  — any other dim whose value is a uuid → must be a visible twin
--     WHOSE entity_type EQUALS the dim. A company coordinate carrying a
--     vehicle's uuid is not a company; accepting it would let a caller relabel
--     one node as another and get an answer titled with the wrong node.
--   * none  — value is not a uuid (a slug like 'najmy'). Passed through
--     UNVERIFIED and marked as such: this function cannot vouch for an axis it
--     has no substrate for, and pretending otherwise is the lie this mechanism
--     exists to prevent. The CONSUMER then declares whether it honoured the
--     coordinate (block-level scope_applied) — that is where that loop closes.
--
-- Contract: (jsonb) -> jsonb {requested[], effective[], dropped[]}.

create or replace function public.scope_effective(p_scope jsonb default '[]'::jsonb)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public, pg_temp
as $$
declare
  v_req  jsonb := public.scope_normalize(p_scope);
  v_c    jsonb;
  v_dim  text;
  v_val  text;
  v_eff  jsonb := '[]'::jsonb;
  v_drop jsonb := '[]'::jsonb;
  v_ok   boolean;
begin
  for v_c in select value from jsonb_array_elements(v_req) loop
    v_dim := v_c->>'dim';
    v_val := v_c->>'value';

    -- uuid by shape, not by cast: a failed cast inside a loop would need an
    -- exception block per coordinate, and this predicate is IMMUTABLE-cheap.
    if v_val !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_eff := v_eff || jsonb_build_array(v_c || jsonb_build_object('resolver', 'none'));
      continue;
    end if;

    if v_dim = 'story' then
      select true into v_ok
      from public.partner_stories s
      where s.id = v_val::uuid
      limit 1;
      if coalesce(v_ok, false) then
        v_eff := v_eff || jsonb_build_array(v_c || jsonb_build_object('resolver', 'story'));
      else
        v_drop := v_drop || jsonb_build_array(
          jsonb_build_object('dim', v_dim, 'value', v_val, 'reason', 'not_visible'));
      end if;
      v_ok := null;
      continue;
    end if;

    select true into v_ok
    from public.twin_entities t
    where t.id = v_val::uuid
      and t.entity_type = v_dim
      and t.status = 'active'
    limit 1;
    if coalesce(v_ok, false) then
      v_eff := v_eff || jsonb_build_array(v_c || jsonb_build_object('resolver', 'twin'));
    else
      -- Covers all three of: no such twin, not visible to this identity, and
      -- visible but of another type. One reason on purpose (see oracle guard).
      v_drop := v_drop || jsonb_build_array(
        jsonb_build_object('dim', v_dim, 'value', v_val, 'reason', 'not_visible'));
    end if;
    v_ok := null;
  end loop;

  return jsonb_build_object('requested', v_req, 'effective', v_eff, 'dropped', v_drop);
end;
$$;

comment on function public.scope_effective(jsonb) is
  'Single owner of the scope rule: canonicalises a scope vector, vouches for uuid coordinates against the story/twin substrate as the CALLER (SECURITY INVOKER, so RLS decides), passes unverifiable slug coordinates through marked resolver=none, and reports drops with one non-oracle reason.';

revoke all on function public.scope_effective(jsonb) from public, anon;
grant execute on function public.scope_effective(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/scope_story_id.sql
-- -----------------------------------------------------------------------------

-- scope_story_id — which STORY a run under this scope belongs to.
--
-- "Every run belongs to a story. Not usually — always." (fn_ai_runs_default_story)
-- ai_runs.story_id is NOT NULL, so the schema already insists that a run stands
-- on a node in the network of relations. This function says WHICH node, and —
-- when it cannot say — makes that audible instead of letting the answer quietly
-- collapse into the one bucket everything currently shares.
--
-- Resolution, strongest first:
--   1. an explicit, VOUCHED story coordinate (resolver='story') → that story.
--   2. otherwise NULL + a reason. The BEFORE INSERT trigger then anchors the run
--      to the stack-default story, which is a perfectly ordinary story, and the
--      reason travels in the run's metadata so "this scope has no story yet" is
--      a readable fact rather than a silence.
--
-- WHY NO DERIVATION FROM A COMPANY/OBJECT COORDINATE (yet): measured on
-- production 2026-07-30 — li_links has 0 rows and no table binds a twin to a
-- document, so there is nothing to join a company node to the documents whose
-- story_id we would inherit. Writing a derivation over a substrate that is
-- provably empty would produce a rule that cannot fire and therefore reports
-- neither a relation nor a gap. The seam is named here so that when the binding
-- lands, this is the ONE place that learns it.
--
-- WHAT THIS FUNCTION MUST NEVER DO: create a story. A story per viewpoint is a
-- ratification — a human act on data — and a read path that mints nodes as a
-- side effect of someone changing a dropdown would make the network of relations
-- a landfill.
--
-- Contract: (jsonb) -> jsonb {story_id (uuid|null), origin, detail}.

create or replace function public.scope_story_id(p_scope jsonb default '[]'::jsonb)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public, pg_temp
as $$
declare
  v_res   jsonb := public.scope_effective(p_scope);
  v_story text;
  v_dims  text;
begin
  select c->>'value' into v_story
  from jsonb_array_elements(v_res->'effective') c
  where c->>'dim' = 'story' and c->>'resolver' = 'story'
  limit 1;

  if v_story is not null then
    return jsonb_build_object(
      'story_id', v_story,
      'origin',   'scope_explicit',
      'detail',   'story coordinate vouched by scope_effective');
  end if;

  select string_agg(distinct c->>'dim', ',' order by c->>'dim') into v_dims
  from jsonb_array_elements(v_res->'effective') c;

  return jsonb_build_object(
    'story_id', null,
    'origin',   case when v_dims is null then 'no_scope' else 'no_binding' end,
    -- Names the dimensions that were present but could not be turned into a
    -- node. This string is the gap report: it is what tells a reader later that
    -- the answer was anchored to the default story, and why.
    'detail',   case when v_dims is null
                     then 'no scope requested'
                     else 'scope dims [' || v_dims || '] have no story binding (li_links empty, no twin→document link)' end);
end;
$$;

comment on function public.scope_story_id(jsonb) is
  'Resolves a scope vector to the story a run belongs to: an explicit vouched story coordinate wins, otherwise NULL plus the reason (the ai_runs trigger then anchors to the stack-default story). Never creates a story — that is a ratification, not a read.';

revoke all on function public.scope_story_id(jsonb) from public, anon;
grant execute on function public.scope_story_id(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/seed_default_sync_policies.sql
-- -----------------------------------------------------------------------------

-- Function: public.seed_default_sync_policies
-- Arguments: p_story_id uuid
-- Description: Seeds default sync policies for a story based on the 3-class data model.
-- Security: SECURITY DEFINER — admin/staff only

CREATE OR REPLACE FUNCTION public.seed_default_sync_policies(p_story_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_count integer := 0;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff role required';
  END IF;

  INSERT INTO story_sync_policies (story_id, data_domain, data_class, flow_direction, description)
  VALUES
    (p_story_id, 'story_metadata', 'canonical_portable', 'downstream_only',
     'Story title, status, tech_stack, domain, project_preview'),
    (p_story_id, 'rulesets', 'canonical_portable', 'downstream_only',
     'Expert rules and ruleset fingerprints'),
    (p_story_id, 'knowledge_items', 'canonical_portable', 'promote_on_approval',
     'Knowledge items content — local additions can be promoted upstream'),
    (p_story_id, 'build_config', 'canonical_portable', 'downstream_only',
     'Portable build configuration shared across instances'),
    (p_story_id, 'sync_policies', 'canonical_portable', 'downstream_only',
     'Sync policy definitions themselves'),
    (p_story_id, 'embeddings', 'derived_reproducible', 'no_sync',
     'Vector embeddings — rebuilt locally from knowledge items'),
    (p_story_id, 'knowledge_chunks', 'derived_reproducible', 'no_sync',
     'Chunked text for RAG — rebuilt locally'),
    (p_story_id, 'audit_journal', 'sovereign_local', 'local_only',
     'Audit log — never leaves the instance'),
    (p_story_id, 'ai_trace_events', 'sovereign_local', 'local_only',
     'AI agent traces and session logs'),
    (p_story_id, 'endpoint_bindings', 'sovereign_local', 'local_only',
     'Instance-specific endpoint URLs and auth refs'),
    (p_story_id, 'sessions', 'sovereign_local', 'local_only',
     'AISHA session state — workspace-specific'),
    (p_story_id, 'story_entries', 'sovereign_local', 'local_only',
     'Timeline/discussion entries never leave the instance')
  ON CONFLICT (story_id, data_domain) DO NOTHING;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'story_id', p_story_id,
    'policies_created', v_count
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.seed_default_sync_policies(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.seed_default_sync_policies(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/send_intranet_message.sql
-- -----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.send_intranet_message(
  p_channel_slug text,
  p_content text
)
RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_channel_id uuid;
  v_message_id uuid;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF p_content IS NULL OR length(trim(p_content)) = 0 THEN
    RAISE EXCEPTION 'empty_message';
  END IF;

  SELECT c.id INTO v_channel_id
  FROM intranet_chat_channels c
  JOIN intranet_chat_members m ON m.channel_id = c.id AND m.user_id = v_caller
  WHERE c.slug = p_channel_slug AND NOT c.is_archived;

  IF v_channel_id IS NULL THEN
    RAISE EXCEPTION 'channel_not_found_or_not_member';
  END IF;

  INSERT INTO intranet_chat_messages (channel_id, user_id, content)
  VALUES (v_channel_id, v_caller, trim(p_content))
  RETURNING id INTO v_message_id;

  RETURN v_message_id;
END;
$$;

REVOKE ALL ON FUNCTION send_intranet_message(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION send_intranet_message(text, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_active_ai_model_admin.sql
-- -----------------------------------------------------------------------------

-- set_active_ai_model_admin — Admin/staff override pro aktivní AI model.
--
-- Permission gated (is_admin_or_staff), audit-traced (audit_journal entry s
-- metadata = ID + state, žádná PII). Při aktivaci jiných modelů pro stejný
-- provider deaktivuje předchozí override.
--
-- Tier-based auto selection (get_adaptive_model_tiers) zůstává primární mechanismus
-- pro automatický runtime výběr — admin override je výjimka, ne pravidlo.
--
-- EVAL-BEFORE-MIGRATION GATE (G4, odysseus impl/14 + impl/13 §5.2):
-- aktivace modelu = změna operativního defaultu pro daný provider. Bez zeleného
-- evalu se default NEMĚNÍ: model musí mít eval_status IN ('tested','approved')
-- (self-test/benchmark lifecycle) A aktuální benchmark v ai_model_benchmarks
-- s overall_score >= system_config['ai_runtime'].eval_min_overall_score
-- (fallback 0.6). CHYBĚJÍCÍ eval výsledek = gate FAIL (fail-closed, žádné
-- tiché povolení). Deaktivace gate nepodléhá. Harness: benchmarkRunner
-- .benchmarkModels → record_model_benchmark (REPLACE semantics per task_type).
--
-- Migration: 20260428112918_insight_maestro_provider.sql
-- Hooks/MCP: src/hooks/useAiModels.ts (useSetActiveAiModel)
-- VS Code extension: extensions/aisha-dirigent/src/admin-model-switch.ts

CREATE OR REPLACE FUNCTION public.set_active_ai_model_admin(
  p_provider text,
  p_model_id text,
  p_is_active boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_model_record_id uuid;
  v_previous_state boolean;
  v_eval_status text;
  v_best_score numeric;
  v_min_score numeric;
BEGIN
  -- Permission check: admin or staff only
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Permission denied: admin or staff role required to override AI model selection'
      USING ERRCODE = '42501';
  END IF;

  v_user_id := auth.uid();

  -- Validate model exists in registry
  SELECT id, is_admin_active, eval_status
    INTO v_model_record_id, v_previous_state, v_eval_status
    FROM public.ai_model_registry
    WHERE provider = p_provider AND model_id = p_model_id;

  IF v_model_record_id IS NULL THEN
    RAISE EXCEPTION 'Model not found in registry: provider=%, model_id=%', p_provider, p_model_id
      USING ERRCODE = 'P0002';
  END IF;

  -- ── Eval-before-migration gate (G4) — BEFORE any mutation ────────────────
  -- Fail-closed: no benchmark result → FAIL (never a silent pass).
  IF p_is_active THEN
    v_min_score := COALESCE(
      (SELECT (value->>'eval_min_overall_score')::numeric
         FROM public.system_config WHERE key = 'ai_runtime'),
      0.6);

    SELECT max(overall_score)
      INTO v_best_score
      FROM public.ai_model_benchmarks
      WHERE model_registry_id = v_model_record_id
        AND overall_score IS NOT NULL;

    IF v_eval_status NOT IN ('tested', 'approved')
       OR v_best_score IS NULL
       OR v_best_score < v_min_score THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = format(
          'Eval-before-migration gate: cannot activate %s/%s — eval_status=%s, best overall_score=%s, required >= %s. '
          'Run the benchmark harness first (benchmarkModels → record_model_benchmark), then approve.',
          p_provider, p_model_id, COALESCE(v_eval_status, 'NULL'),
          COALESCE(v_best_score::text, 'NONE'), v_min_score::text);
    END IF;
  END IF;

  -- When activating: deactivate other admin overrides for the SAME provider
  -- (prevents conflicting overrides; auto tier selection still uses non-admin defaults).
  IF p_is_active THEN
    UPDATE public.ai_model_registry
      SET is_admin_active = false,
          updated_at = now()
      WHERE provider = p_provider
        AND id <> v_model_record_id
        AND is_admin_active = true;
  END IF;

  -- Apply the override
  UPDATE public.ai_model_registry
    SET is_admin_active = p_is_active,
        updated_at = now()
    WHERE id = v_model_record_id;

  -- Audit (no PII — only IDs and metadata)
  INSERT INTO public.audit_journal (
    user_id,
    action,
    metadata
  )
  VALUES (
    v_user_id,
    'ai_model_admin_override',
    jsonb_build_object(
      'model_record_id', v_model_record_id,
      'provider', p_provider,
      'model_id', p_model_id,
      'previous_state', v_previous_state,
      'new_state', p_is_active,
      'eval_status', v_eval_status,
      'eval_best_overall_score', v_best_score,
      'eval_min_required', v_min_score
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'provider', p_provider,
    'model_id', p_model_id,
    'is_admin_active', p_is_active,
    'previous_state', v_previous_state
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.set_active_ai_model_admin(text, text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_active_ai_model_admin(text, text, boolean) TO authenticated;

COMMENT ON FUNCTION public.set_active_ai_model_admin(text, text, boolean) IS
  'Admin/staff override pro aktivní AI model. Permission gated (is_admin_or_staff), audit-traced. '
  'Při aktivaci jiných modelů pro stejný provider deaktivuje předchozí override. '
  'Tier-based auto selection (get_adaptive_model_tiers) zůstává primární mechanismus '
  'pro automatický runtime výběr — admin override je výjimka, ne pravidlo. '
  'EVAL-BEFORE-MIGRATION GATE (G4): aktivace vyžaduje eval_status tested/approved '
  'a benchmark overall_score >= ai_runtime.eval_min_overall_score (fail-closed, bez evalu nelze aktivovat).';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_ai_budget_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: set_ai_budget_audited
-- Mission Control governance — upsert a scope's AI spend cap (admin/staff).
-- "You're the board — set the ceiling." NULL limit = that dimension uncapped.
-- Security: SECURITY DEFINER + is_admin_or_staff() guard + audit_journal.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.set_ai_budget_audited(
  p_scope_type     text,
  p_scope_id       uuid,
  p_token_limit    int DEFAULT NULL,
  p_cost_limit numeric DEFAULT NULL,
  p_period         text DEFAULT 'lifetime'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_row public.ai_budget%ROWTYPE;
BEGIN
  -- Authorization: admin or staff only.
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff required' USING ERRCODE = '42501';
  END IF;

  -- Validate inputs.
  IF p_scope_type IS NULL OR p_scope_type NOT IN ('story', 'partner', 'agent') THEN
    RAISE EXCEPTION 'Invalid scope_type: %', p_scope_type USING ERRCODE = '22023';
  END IF;
  IF p_scope_id IS NULL THEN
    RAISE EXCEPTION 'p_scope_id is required' USING ERRCODE = '22023';
  END IF;
  IF p_period IS NULL OR p_period NOT IN ('lifetime', 'daily', 'monthly') THEN
    RAISE EXCEPTION 'Invalid period: %', p_period USING ERRCODE = '22023';
  END IF;
  IF p_token_limit IS NOT NULL AND p_token_limit < 0 THEN
    RAISE EXCEPTION 'p_token_limit must be >= 0' USING ERRCODE = '22023';
  END IF;
  IF p_cost_limit IS NOT NULL AND p_cost_limit < 0 THEN
    RAISE EXCEPTION 'p_cost_limit must be >= 0' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.ai_budget (
    scope_type, scope_id, period, token_limit, cost_limit, created_by
  ) VALUES (
    p_scope_type, p_scope_id, p_period, p_token_limit, p_cost_limit, auth.uid()
  )
  ON CONFLICT (scope_type, scope_id, period) DO UPDATE SET
    token_limit    = EXCLUDED.token_limit,
    cost_limit = EXCLUDED.cost_limit,
    updated_at     = now()
  -- Explicit column list (security gate: no SELECT */RETURNING * on real tables).
  -- Order matches public.ai_budget definition for %ROWTYPE compatibility.
  RETURNING id, scope_type, scope_id, period, token_limit, cost_limit,
            consumed_tokens, consumed_cost, last_reset_at,
            created_by, created_at, updated_at
  INTO v_row;

  -- Audit (mutation of a governance control — always logged, IDs + limits, no PII).
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'ai.budget.set',
    jsonb_build_object(
      'scope_type',     p_scope_type,
      'scope_id',       p_scope_id,
      'period',         p_period,
      'token_limit',    p_token_limit,
      'cost_limit', p_cost_limit
    )
  );

  RETURN jsonb_build_object(
    'id',                v_row.id,
    'scope_type',        v_row.scope_type,
    'scope_id',          v_row.scope_id,
    'period',            v_row.period,
    'token_limit',       v_row.token_limit,
    'cost_limit',    v_row.cost_limit,
    'consumed_tokens',   v_row.consumed_tokens,
    'consumed_cost', v_row.consumed_cost
  );
END;
$$;

REVOKE ALL ON FUNCTION public.set_ai_budget_audited(text, uuid, int, numeric, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_ai_budget_audited(text, uuid, int, numeric, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.set_ai_budget_audited(text, uuid, int, numeric, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_ai_resolver_policy_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: set_ai_resolver_policy_audited
-- Purpose: Upsert one ai_resolver_policy row (operator tuning of the orchestration-decision
--          weights/thresholds). NULL params INHERIT — from the existing row on update, or from
--          the always-present GLOBAL row when authoring a new scoped row — so a partial edit
--          never violates the NOT NULL columns and never silently zeroes a weight. Passing
--          p_deactivate=true retires the row (is_active=false); the GLOBAL row should not be
--          deactivated (the resolver fails loud without it).
-- Security: SECURITY DEFINER + is_admin_or_staff() guard + audit_journal (clone of
--           set_ai_spend_policy_audited).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.set_ai_resolver_policy_audited(
  p_scope_type                   text    DEFAULT 'global',
  p_scope_id                     uuid    DEFAULT NULL,
  p_task_kind                    text    DEFAULT NULL,
  p_bench_weight                 numeric DEFAULT NULL,
  p_local_bonus                  numeric DEFAULT NULL,
  p_cost_match_weight            numeric DEFAULT NULL,
  p_tool_match_weight            numeric DEFAULT NULL,
  p_vision_match_weight          numeric DEFAULT NULL,
  p_budget_remaining_floor   numeric DEFAULT NULL,
  p_budget_max_cost          numeric DEFAULT NULL,
  p_premium_max_cost         numeric DEFAULT NULL,
  p_batch_min_deadline_hours     integer DEFAULT NULL,
  p_batch_min_tokens             integer DEFAULT NULL,
  p_health_allow_set             text[]  DEFAULT NULL,
  p_default_bench                numeric DEFAULT NULL,
  p_default_expected_tokens      integer DEFAULT NULL,
  p_default_deadline_hours       integer DEFAULT NULL,
  p_default_max_cost         numeric DEFAULT NULL,
  p_default_budget_remaining numeric DEFAULT NULL,
  p_deactivate                   boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_task_kind text := NULLIF(btrim(COALESCE(p_task_kind, '')), '');
  v_base public.ai_resolver_policy%ROWTYPE;
  v_row  public.ai_resolver_policy%ROWTYPE;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff required' USING ERRCODE = '42501';
  END IF;

  -- JIT-provision the admin actor so the audit_journal insert can't FK-violate (23503).
  PERFORM public.ensure_current_user();

  IF p_scope_type NOT IN ('global', 'story', 'instance') THEN
    RAISE EXCEPTION 'Invalid scope_type: %', p_scope_type USING ERRCODE = '22023';
  END IF;
  IF (p_scope_type = 'global') <> (p_scope_id IS NULL) THEN
    RAISE EXCEPTION 'scope_id must be NULL for global scope and set otherwise' USING ERRCODE = '22023';
  END IF;

  -- Inherit base: the existing row for this exact scope (partial update), else the GLOBAL row
  -- (authoring a new scoped row inherits the platform default). The GLOBAL row always exists.
  SELECT * INTO v_base FROM public.ai_resolver_policy
   WHERE scope_type = p_scope_type
     AND scope_id IS NOT DISTINCT FROM p_scope_id
     AND task_kind IS NOT DISTINCT FROM v_task_kind;
  IF NOT FOUND THEN
    SELECT * INTO v_base FROM public.ai_resolver_policy
     WHERE scope_type = 'global' AND task_kind IS NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'ai_resolver_policy GLOBAL row missing — cannot author a policy without a base'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  INSERT INTO public.ai_resolver_policy (
    scope_type, scope_id, task_kind,
    bench_weight, local_bonus, cost_match_weight, tool_match_weight, vision_match_weight,
    budget_remaining_floor, budget_max_cost, premium_max_cost,
    batch_min_deadline_hours, batch_min_tokens, health_allow_set,
    default_bench, default_expected_tokens, default_deadline_hours,
    default_max_cost, default_budget_remaining,
    is_active, created_by
  ) VALUES (
    p_scope_type, p_scope_id, v_task_kind,
    COALESCE(p_bench_weight, v_base.bench_weight),
    COALESCE(p_local_bonus, v_base.local_bonus),
    COALESCE(p_cost_match_weight, v_base.cost_match_weight),
    COALESCE(p_tool_match_weight, v_base.tool_match_weight),
    COALESCE(p_vision_match_weight, v_base.vision_match_weight),
    COALESCE(p_budget_remaining_floor, v_base.budget_remaining_floor),
    COALESCE(p_budget_max_cost, v_base.budget_max_cost),
    COALESCE(p_premium_max_cost, v_base.premium_max_cost),
    COALESCE(p_batch_min_deadline_hours, v_base.batch_min_deadline_hours),
    COALESCE(p_batch_min_tokens, v_base.batch_min_tokens),
    COALESCE(p_health_allow_set, v_base.health_allow_set),
    COALESCE(p_default_bench, v_base.default_bench),
    COALESCE(p_default_expected_tokens, v_base.default_expected_tokens),
    COALESCE(p_default_deadline_hours, v_base.default_deadline_hours),
    COALESCE(p_default_max_cost, v_base.default_max_cost),
    COALESCE(p_default_budget_remaining, v_base.default_budget_remaining),
    NOT COALESCE(p_deactivate, false), auth.uid()
  )
  ON CONFLICT ON CONSTRAINT ai_resolver_policy_scope_kind_uniq DO UPDATE SET
    bench_weight                 = COALESCE(p_bench_weight, v_base.bench_weight),
    local_bonus                  = COALESCE(p_local_bonus, v_base.local_bonus),
    cost_match_weight            = COALESCE(p_cost_match_weight, v_base.cost_match_weight),
    tool_match_weight            = COALESCE(p_tool_match_weight, v_base.tool_match_weight),
    vision_match_weight          = COALESCE(p_vision_match_weight, v_base.vision_match_weight),
    budget_remaining_floor   = COALESCE(p_budget_remaining_floor, v_base.budget_remaining_floor),
    budget_max_cost          = COALESCE(p_budget_max_cost, v_base.budget_max_cost),
    premium_max_cost         = COALESCE(p_premium_max_cost, v_base.premium_max_cost),
    batch_min_deadline_hours     = COALESCE(p_batch_min_deadline_hours, v_base.batch_min_deadline_hours),
    batch_min_tokens             = COALESCE(p_batch_min_tokens, v_base.batch_min_tokens),
    health_allow_set             = COALESCE(p_health_allow_set, v_base.health_allow_set),
    default_bench                = COALESCE(p_default_bench, v_base.default_bench),
    default_expected_tokens      = COALESCE(p_default_expected_tokens, v_base.default_expected_tokens),
    default_deadline_hours       = COALESCE(p_default_deadline_hours, v_base.default_deadline_hours),
    default_max_cost         = COALESCE(p_default_max_cost, v_base.default_max_cost),
    default_budget_remaining = COALESCE(p_default_budget_remaining, v_base.default_budget_remaining),
    is_active                    = NOT COALESCE(p_deactivate, false),
    updated_at                   = now()
  RETURNING * INTO v_row;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'ai.resolver_policy.set',
    jsonb_strip_nulls(jsonb_build_object(
      'policy_id', v_row.id,
      'scope_type', v_row.scope_type,
      'scope_id', v_row.scope_id,
      'task_kind', v_row.task_kind,
      'bench_weight', v_row.bench_weight,
      'local_bonus', v_row.local_bonus,
      'cost_match_weight', v_row.cost_match_weight,
      'tool_match_weight', v_row.tool_match_weight,
      'vision_match_weight', v_row.vision_match_weight,
      'budget_max_cost', v_row.budget_max_cost,
      'premium_max_cost', v_row.premium_max_cost,
      'is_active', v_row.is_active
    ))
  );

  RETURN jsonb_build_object(
    'success', true,
    'policy_id', v_row.id,
    'is_active', v_row.is_active,
    'updated_at', v_row.updated_at
  );
END;
$$;

REVOKE ALL ON FUNCTION public.set_ai_resolver_policy_audited(text, uuid, text, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, integer, integer, text[], numeric, integer, integer, numeric, numeric, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_ai_resolver_policy_audited(text, uuid, text, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, integer, integer, text[], numeric, integer, integer, numeric, numeric, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.set_ai_resolver_policy_audited(text, uuid, text, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, integer, integer, text[], numeric, integer, integer, numeric, numeric, boolean) TO service_role;

COMMENT ON FUNCTION public.set_ai_resolver_policy_audited(text, uuid, text, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, integer, integer, text[], numeric, integer, integer, numeric, numeric, boolean) IS
  'Upsert one ai_resolver_policy row (operator tuning of resolver weights/thresholds). NULL params inherit from the existing row or the GLOBAL base. Admin/staff, audited.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_ai_risk_policy_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: set_ai_risk_policy_audited
-- Purpose: Upsert one ai_risk_policies row — the user-driven risk-threshold
--          matrix that decides governance for a task of a given kind:
--            evaluated risk <= auto_allow_at_or_below → allow (silent)
--            evaluated risk >  ask_above              → ask (human approval)
--            evaluated risk >  deny_above             → deny (hard ceiling)
--          Risk levels are the fixed ordinal scale returned by
--          fn_evaluate_proposal_risk(): 'low' < 'medium' < 'high' < 'critical'.
--          This is the risk-governance mirror of set_ai_spend_policy_audited
--          (USD thresholds): governance = POLICY thresholds computed against the
--          clow's risk, NOT a maintained roster of permitted entities.
--          Resolution (most specific active row wins) and the catalog fallback
--          live in ai_risk_policies (table SoT) + the reader RPC.
-- Security: SECURITY DEFINER + is_admin_or_staff() guard + audit_journal.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.set_ai_risk_policy_audited(
  p_auto_allow_at_or_below text,
  p_ask_above              text,
  p_deny_above             text,
  p_scope_type             text    DEFAULT 'global',
  p_scope_id               uuid    DEFAULT NULL,
  p_task_kind              text    DEFAULT NULL,
  p_is_active              boolean DEFAULT true
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_policy_id uuid;
  v_task_kind text;
  -- Fixed ordinal risk scale (the value's own domain type, not an editable
  -- allow-list): rank(level) lets us validate membership + threshold ordering
  -- without any maintained list of permitted things.
  v_allow_rank int;
  v_ask_rank   int;
  v_deny_rank  int;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff required' USING ERRCODE = '42501';
  END IF;

  -- JIT-provision the admin actor so the audit_journal insert below can't
  -- FK-violate (23503) for a Keycloak admin created after bootstrap import.
  PERFORM public.ensure_current_user();

  IF p_scope_type NOT IN ('global', 'story', 'partner') THEN
    RAISE EXCEPTION 'Invalid scope_type: %', p_scope_type USING ERRCODE = '22023';
  END IF;
  IF (p_scope_type = 'global') <> (p_scope_id IS NULL) THEN
    RAISE EXCEPTION 'scope_id must be NULL for global scope and set otherwise'
      USING ERRCODE = '22023';
  END IF;

  -- Map each threshold onto the fixed risk scale. Anything off the scale is
  -- rejected — the scale is invariant, so there is nothing to maintain here.
  v_allow_rank := CASE p_auto_allow_at_or_below
    WHEN 'low' THEN 0 WHEN 'medium' THEN 1 WHEN 'high' THEN 2 WHEN 'critical' THEN 3 END;
  v_ask_rank := CASE p_ask_above
    WHEN 'low' THEN 0 WHEN 'medium' THEN 1 WHEN 'high' THEN 2 WHEN 'critical' THEN 3 END;
  v_deny_rank := CASE p_deny_above
    WHEN 'low' THEN 0 WHEN 'medium' THEN 1 WHEN 'high' THEN 2 WHEN 'critical' THEN 3 END;

  IF v_allow_rank IS NULL OR v_ask_rank IS NULL OR v_deny_rank IS NULL THEN
    RAISE EXCEPTION 'Risk thresholds must be one of low|medium|high|critical (got allow=%, ask=%, deny=%)',
      p_auto_allow_at_or_below, p_ask_above, p_deny_above USING ERRCODE = '22023';
  END IF;

  -- allow_at_or_below <= ask_above <= deny_above (mirror of the spend-policy
  -- threshold-order invariant, expressed over the ordinal risk rank).
  IF v_allow_rank > v_ask_rank OR v_ask_rank > v_deny_rank THEN
    RAISE EXCEPTION 'Risk thresholds out of order: allow(%) <= ask(%) <= deny(%) required',
      p_auto_allow_at_or_below, p_ask_above, p_deny_above USING ERRCODE = '22023';
  END IF;

  v_task_kind := NULLIF(btrim(COALESCE(p_task_kind, '')), '');

  INSERT INTO public.ai_risk_policies (
    scope_type, scope_id, task_kind,
    auto_allow_at_or_below, ask_above, deny_above,
    is_active, created_by
  ) VALUES (
    p_scope_type, p_scope_id, v_task_kind,
    p_auto_allow_at_or_below, p_ask_above, p_deny_above,
    COALESCE(p_is_active, true), auth.uid()
  )
  ON CONFLICT (scope_type, scope_id, task_kind) DO UPDATE SET
    auto_allow_at_or_below = EXCLUDED.auto_allow_at_or_below,
    ask_above              = EXCLUDED.ask_above,
    deny_above             = EXCLUDED.deny_above,
    is_active              = EXCLUDED.is_active,
    updated_at             = now()
  RETURNING id INTO v_policy_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'risk_policy_set',
    jsonb_strip_nulls(jsonb_build_object(
      'policy_id', v_policy_id,
      'scope_type', p_scope_type,
      'scope_id', p_scope_id,
      'task_kind', v_task_kind,
      'auto_allow_at_or_below', p_auto_allow_at_or_below,
      'ask_above', p_ask_above,
      'deny_above', p_deny_above,
      'is_active', COALESCE(p_is_active, true)
    ))
  );

  RETURN v_policy_id;
END;
$$;

REVOKE ALL ON FUNCTION public.set_ai_risk_policy_audited(text, text, text, text, uuid, text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_ai_risk_policy_audited(text, text, text, text, uuid, text, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.set_ai_risk_policy_audited(text, text, text, text, uuid, text, boolean) TO service_role;

COMMENT ON FUNCTION public.set_ai_risk_policy_audited(text, text, text, text, uuid, text, boolean) IS
  'Upsert one ai_risk_policies row (allow/ask/deny risk-level thresholds per scope×task-kind). Admin/staff, audited (risk_policy_set).';


