-- Creates or updates a branding profile (draft or published).
-- Admin-only with audit journal logging.
-- Publishing sets published_at and increments profile_version.
--
-- Multi-brand-aware: callers may pass `p_profile_id` to target a specific
-- brand row by primary key (required when the same partner_id slot —
-- typically `partner_id IS NULL` for platform-level brands — holds more
-- than one published row). When `p_profile_id` is omitted, the function
-- falls back to the legacy per-partner upsert behaviour.

CREATE OR REPLACE FUNCTION public.set_branding_profile_admin(
  p_color_accent text DEFAULT NULL,
  p_color_background text DEFAULT NULL,
  p_color_destructive text DEFAULT NULL,
  p_color_foreground text DEFAULT NULL,
  p_color_muted text DEFAULT NULL,
  p_color_primary text DEFAULT NULL,
  p_color_secondary text DEFAULT NULL,
  p_color_surface text DEFAULT NULL,
  p_dark_color_background text DEFAULT NULL,
  p_dark_color_foreground text DEFAULT NULL,
  p_dark_color_muted text DEFAULT NULL,
  p_dark_color_primary text DEFAULT NULL,
  p_dark_color_surface text DEFAULT NULL,
  p_email_footer_text text DEFAULT NULL,
  p_email_header_bg text DEFAULT NULL,
  p_favicon_path text DEFAULT NULL,
  p_font_family_body text DEFAULT NULL,
  p_font_family_brand text DEFAULT NULL,
  p_font_family_code text DEFAULT NULL,
  p_login_accent_color text DEFAULT NULL,
  p_login_background_color text DEFAULT NULL,
  p_login_card_bg text DEFAULT NULL,
  p_login_logo_path text DEFAULT NULL,
  p_logo_dark_path text DEFAULT NULL,
  p_logo_path text DEFAULT NULL,
  p_operator_address text DEFAULT NULL,
  p_operator_email text DEFAULT NULL,
  p_operator_name text DEFAULT NULL,
  p_operator_phone text DEFAULT NULL,
  p_operator_url text DEFAULT NULL,
  p_partner_id uuid DEFAULT NULL,
  p_profile_id uuid DEFAULT NULL,
  p_publish boolean DEFAULT false,
  p_font_faces jsonb DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_profile_id uuid;
  v_new_status text;
  v_version integer;
BEGIN
  -- Authorization: admin only
  IF NOT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = v_user_id AND role IN ('admin')
  ) THEN
    RAISE EXCEPTION 'Unauthorized: admin role required';
  END IF;

  v_new_status := CASE WHEN p_publish THEN 'published' ELSE 'draft' END;

  -- Existing-row discovery: prefer p_profile_id (multi-brand caller),
  -- fall back to partner-id slot (legacy caller).
  IF p_profile_id IS NOT NULL THEN
    SELECT id INTO v_profile_id
    FROM branding_profiles
    WHERE id = p_profile_id;
  ELSE
    SELECT id INTO v_profile_id
    FROM branding_profiles
    WHERE COALESCE(partner_id, '00000000-0000-0000-0000-000000000000'::uuid)
        = COALESCE(p_partner_id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND status = 'published'
    LIMIT 1;
  END IF;

  -- Publishing transitions the existing published partner slot to draft
  -- before promoting the target — preserves the "one published per partner"
  -- invariant. For platform-level multi-brand (partner_id IS NULL),
  -- callers MUST pass p_profile_id to disambiguate; otherwise the
  -- partner-id slot lookup would match the first published platform brand
  -- arbitrarily.
  IF p_publish AND p_partner_id IS NOT NULL THEN
    UPDATE branding_profiles
    SET status = 'draft', updated_at = now(), updated_by = v_user_id
    WHERE partner_id = p_partner_id
      AND status = 'published'
      AND (v_profile_id IS NULL OR id <> v_profile_id);
  END IF;

  IF v_profile_id IS NULL THEN
    INSERT INTO branding_profiles (
      partner_id, status,
      color_primary, color_secondary, color_accent,
      color_background, color_foreground, color_muted,
      color_surface, color_destructive,
      dark_color_primary, dark_color_background,
      dark_color_foreground, dark_color_surface, dark_color_muted,
      font_family_brand, font_family_body, font_family_code, font_faces,
      logo_path, logo_dark_path, favicon_path, login_logo_path,
      operator_name, operator_email, operator_phone, operator_address, operator_url,
      email_header_bg, email_footer_text,
      login_background_color, login_card_bg, login_accent_color,
      updated_by,
      published_at
    ) VALUES (
      p_partner_id, v_new_status,
      COALESCE(p_color_primary, '23 100% 55%'),
      COALESCE(p_color_secondary, '210 16% 95%'),
      COALESCE(p_color_accent, '22 100% 88%'),
      COALESCE(p_color_background, '210 20% 98%'),
      COALESCE(p_color_foreground, '0 0% 10%'),
      COALESCE(p_color_muted, '220 9% 46%'),
      COALESCE(p_color_surface, '0 0% 100%'),
      COALESCE(p_color_destructive, '0 85% 66%'),
      p_dark_color_primary,
      p_dark_color_background,
      p_dark_color_foreground,
      p_dark_color_surface,
      p_dark_color_muted,
      COALESCE(p_font_family_brand, 'Nunito Sans, sans-serif'),
      COALESCE(p_font_family_body, 'Nunito Sans, sans-serif'),
      COALESCE(p_font_family_code, 'JetBrains Mono, monospace'),
      p_font_faces,
      p_logo_path, p_logo_dark_path, p_favicon_path,
      p_login_logo_path,
      COALESCE(p_operator_name, 'Platform'),
      COALESCE(p_operator_email, 'support@platform.com'),
      p_operator_phone, p_operator_address, p_operator_url,
      p_email_header_bg, p_email_footer_text,
      p_login_background_color, p_login_card_bg, p_login_accent_color,
      v_user_id,
      CASE WHEN p_publish THEN now() ELSE NULL END
    )
    RETURNING id, profile_version INTO v_profile_id, v_version;
  ELSE
    UPDATE branding_profiles
    SET
      status = v_new_status,
      color_primary = COALESCE(p_color_primary, color_primary),
      color_secondary = COALESCE(p_color_secondary, color_secondary),
      color_accent = COALESCE(p_color_accent, color_accent),
      color_background = COALESCE(p_color_background, color_background),
      color_foreground = COALESCE(p_color_foreground, color_foreground),
      color_muted = COALESCE(p_color_muted, color_muted),
      color_surface = COALESCE(p_color_surface, color_surface),
      color_destructive = COALESCE(p_color_destructive, color_destructive),
      dark_color_primary = COALESCE(p_dark_color_primary, dark_color_primary),
      dark_color_background = COALESCE(p_dark_color_background, dark_color_background),
      dark_color_foreground = COALESCE(p_dark_color_foreground, dark_color_foreground),
      dark_color_surface = COALESCE(p_dark_color_surface, dark_color_surface),
      dark_color_muted = COALESCE(p_dark_color_muted, dark_color_muted),
      font_family_brand = COALESCE(p_font_family_brand, font_family_brand),
      font_family_body = COALESCE(p_font_family_body, font_family_body),
      font_family_code = COALESCE(p_font_family_code, font_family_code),
      font_faces = COALESCE(p_font_faces, font_faces),
      logo_path = COALESCE(p_logo_path, logo_path),
      logo_dark_path = COALESCE(p_logo_dark_path, logo_dark_path),
      favicon_path = COALESCE(p_favicon_path, favicon_path),
      login_logo_path = COALESCE(p_login_logo_path, login_logo_path),
      operator_name = COALESCE(p_operator_name, operator_name),
      operator_email = COALESCE(p_operator_email, operator_email),
      operator_phone = COALESCE(p_operator_phone, operator_phone),
      operator_address = COALESCE(p_operator_address, operator_address),
      operator_url = COALESCE(p_operator_url, operator_url),
      email_header_bg = COALESCE(p_email_header_bg, email_header_bg),
      email_footer_text = COALESCE(p_email_footer_text, email_footer_text),
      login_background_color = COALESCE(p_login_background_color, login_background_color),
      login_card_bg = COALESCE(p_login_card_bg, login_card_bg),
      login_accent_color = COALESCE(p_login_accent_color, login_accent_color),
      profile_version = profile_version + 1,
      updated_at = now(),
      updated_by = v_user_id,
      published_at = CASE WHEN p_publish THEN now() ELSE published_at END
    WHERE id = v_profile_id
    RETURNING profile_version INTO v_version;
  END IF;

  -- Audit
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'BRANDING_PROFILE_UPSERT',
    jsonb_build_object(
      'area', 'admin',
      'severity', 'info',
      'entity_type', 'branding_profile',
      'entity_id', v_profile_id,
      'partner_id', p_partner_id,
      'profile_id', p_profile_id,
      'publish', p_publish,
      'version', v_version
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'profile_id', v_profile_id,
    'profile_version', v_version,
    'status', v_new_status
  );
END;
$$;

REVOKE ALL ON FUNCTION public.set_branding_profile_admin(
  text, text, text, text, text, text, text, text, text, text, text, text, text,
  text, text, text, text, text, text, text, text, text, text, text, text, text,
  text, text, text, text, uuid, uuid, boolean, jsonb
) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION public.set_branding_profile_admin(
  text, text, text, text, text, text, text, text, text, text, text, text, text,
  text, text, text, text, text, text, text, text, text, text, text, text, text,
  text, text, text, text, uuid, uuid, boolean, jsonb
) TO authenticated;

COMMENT ON FUNCTION public.set_branding_profile_admin(
  text, text, text, text, text, text, text, text, text, text, text, text, text,
  text, text, text, text, text, text, text, text, text, text, text, text, text,
  text, text, text, text, uuid, uuid, boolean, jsonb
) IS
  'Admin-only: upsert branding profile with draft/publish workflow and audit '
  'logging. Pass p_profile_id to target a specific brand by id (multi-brand '
  'platforms); omit it for legacy per-partner upsert.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_data_source_config.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: set_data_source_config
-- Popis: Změní konfiguraci zdroje dat z administrace. Slučuje, nepřepisuje.
--
-- ⛔ PROČ VZNIKÁ. Systém uměl zdroj ZALOŽIT s konfigurací (materialize_data_source)
-- a od 2026-09-01 ho i zapnout a vypnout — ale ZMĚNIT konfiguraci ne. Naměřeno
-- téhož dne: faktury se z ERP netahaly, protože zdroj měl v `doc_markers` jediný
-- marker, zatímco mapy pro obě faktury ležely v instančním bundlu hotové. Změna
-- na dva řádky se musela udělat přímým UPDATEm do databáze a zápis do žurnálu
-- dopsat ručně. Vznik měl cestu, změna ne.
--
-- ⭐ SLUČUJE, NEPŘEPISUJE. `config` nese i správu (owner, legal_basis, retention);
-- přepis celým objektem by je tiše shodil, protože volající pošle jen to, co mění.
--
-- ⭐ NEZNÁMÝ KLÍČ JE VADA, NE NOVÁ VLASTNOST. Překlep v názvu by se jinak zapsal
-- a NIC by neudělal — tichý no-op, tedy přesně ten tvar poruchy, který se nepozná.
-- Povolené klíče se NEVYJMENOVÁVAJÍ (druhý udržovaný seznam by se rozešel):
-- odvozují se z toho, co zdroj UŽ deklaruje. Vědomé přidání klíče se řekne
-- `p_allow_new_keys := true`.
--
-- ⛔ TAJEMSTVÍ SEM NEPATŘÍ. `config` je čitelná jsonb, kterou administrace
-- zobrazuje; pověření mají vlastní šifrovanou tabulku
-- (`agent_knowledge_source_secrets` + `set_data_source_secrets`).
--
-- ⚠️ CO TAHLE FUNKCE NEMĚŘÍ: že marker má v instančním bundlu mapu. Mapy nejsou
-- v databázi (žijí v bundlu a čte je engine), takže SQL na ně nedosáhne. Zapnout
-- marker bez mapy tedy jde — projeví se to tak, že doklady dorazí a engine je
-- nepřečte. Ověřuje se to spuštěním, ne tady.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.set_data_source_config(
  p_source_slug    text,
  p_patch          jsonb,
  p_allow_new_keys boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_source_id uuid;
  v_config    jsonb;
  v_nove      text[];
  v_tajne     text[];
  v_zmenene   text[];
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' THEN
    RAISE EXCEPTION 'set_data_source_config: p_patch musí být objekt {klíč: hodnota}';
  END IF;

  SELECT id, coalesce(config, '{}'::jsonb) INTO v_source_id, v_config
    FROM public.agent_knowledge_sources
   WHERE source_slug = p_source_slug;

  IF v_source_id IS NULL THEN
    RAISE EXCEPTION 'set_data_source_config: zdroj % neexistuje', p_source_slug;
  END IF;

  -- Pověření do konfigurace nepatří — mají šifrovanou tabulku.
  SELECT coalesce(array_agg(k ORDER BY k), '{}') INTO v_tajne
    FROM jsonb_object_keys(p_patch) k
   WHERE k ~* '(heslo|password|secret|token|apikey|api_key|credential)';
  IF array_length(v_tajne, 1) > 0 THEN
    RAISE EXCEPTION 'set_data_source_config: % patří do set_data_source_secrets, ne do config',
      array_to_string(v_tajne, ', ');
  END IF;

  -- Neznámý klíč = překlep, dokud volající neřekne opak.
  IF NOT p_allow_new_keys THEN
    SELECT coalesce(array_agg(k ORDER BY k), '{}') INTO v_nove
      FROM jsonb_object_keys(p_patch) k
     WHERE NOT (v_config ? k);
    IF array_length(v_nove, 1) > 0 THEN
      RAISE EXCEPTION 'set_data_source_config: zdroj % nemá klíče: %. Zdroj zná: %. Nový klíč se přidává s p_allow_new_keys := true.',
        p_source_slug,
        array_to_string(v_nove, ', '),
        coalesce((SELECT string_agg(k, ', ' ORDER BY k) FROM jsonb_object_keys(v_config) k), '(žádné)');
    END IF;
  END IF;

  -- Idempotence: co se hodnotou neliší, není změna.
  SELECT coalesce(array_agg(k ORDER BY k), '{}') INTO v_zmenene
    FROM jsonb_object_keys(p_patch) k
   WHERE v_config -> k IS DISTINCT FROM p_patch -> k;

  IF array_length(v_zmenene, 1) IS NULL THEN
    RETURN jsonb_build_object('source_slug', p_source_slug, 'changed', '[]'::jsonb);
  END IF;

  UPDATE public.agent_knowledge_sources
     SET config = v_config || p_patch, updated_at = now()
   WHERE id = v_source_id;

  -- ⛔ Do žurnálu jdou JMÉNA klíčů a jen u nich stará/nová hodnota by mohla nést
  -- data zdroje — proto jen jména. Kdo chce vidět obsah, čte config.
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'DATA_SOURCE_CONFIG_CHANGED', jsonb_build_object(
    'area', 'ingest', 'severity', 'warning',
    'source_slug', p_source_slug, 'source_id', v_source_id,
    'keys', to_jsonb(v_zmenene), 'new_keys_allowed', p_allow_new_keys
  ));

  RETURN jsonb_build_object('source_slug', p_source_slug, 'changed', to_jsonb(v_zmenene));
END;
$$;

COMMENT ON FUNCTION public.set_data_source_config(text, jsonb, boolean) IS
  'Sloučí patch do config zdroje. Neznámý klíč odmítne (překlep by byl tichý no-op), tajemství odkáže do set_data_source_secrets. Idempotentní, auditované. Admin/staff nebo service_role.';

REVOKE ALL ON FUNCTION public.set_data_source_config(text, jsonb, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_data_source_config(text, jsonb, boolean) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/resolve_absorbed_ingest_source_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: resolve_absorbed_ingest_source_admin
-- Popis: Srovná TWINY se zdrojem, který registr zdrojů už pohltil jiným:
--        duplikáty archivuje, jedinečné vazby převede pod kanonický zdroj,
--        nejasné případy jen vyjmenuje. Jedno ROZHODNUTÍ ČLOVĚKA, vratné.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (admin/staff nebo service_role)
--
-- ⛔ PROČ VZNIKLA (naměřeno 2026-09-19 v produkci riq, jen čtením). Přehrání
--    tří balíčků se jménem aplikace `aisha-local-ingest` (30. 8.) založilo
--    839 twinů `company` (21 % všech) vedle twinů `local-ingest` téhož ingestu.
--    2 189 klíčů existuje pod oběma zdroji, pokaždé na JINÝ twin. Registr zdrojů
--    to 2026-09-02 sjednotil pohlcením (config.superseded_by), twiny ne — a ty
--    se „táhly" dál. Majitel: projekt má JEDEN ingest (`local-ingest`).
--
-- ⭐ KRITÉRIUM JE ZDROJ, O JEHOŽ POHLCENÍ UŽ ROZHODL ČLOVĚK. Funkce nerozhoduje,
--    že dvě jména znamenají totéž — to je tvrzení o světě a zapisuje ho
--    set_data_source_config (config.nahrazuje → superseded_by). Tady se jen
--    dotahuje do twinů. Nepohlcený zdroj = odmítnutí, ne odhad.
--
-- ⭐ TŘÍDY TWINŮ (klíče porovnané po normalizaci: jen písmena a číslice, malá):
--    · duplikat — twin nemá žádnou vazbu kanonického zdroje, KAŽDÝ jeho živý klíč
--      drží kanonický zdroj, všechny u JEDNOHO a téhož jiného twinu téhož druhu
--      entity → twin 'archived', jeho vazby pohlceného zdroje 'superseded'.
--    · prevest  — žádný jeho klíč kanonický zdroj jinde nedrží → vazby pohlceného
--      zdroje se převedou pod kanonický; kde už stejnou vazbu (druh + klíč) má
--      týž twin od kanonického zdroje, stará se jen ukončí ('superseded').
--    · nejasne  — všechno ostatní, kde se nějaký klíč potká s jiným twinem:
--      twin má vazby OBOU zdrojů, NEBO jen část jeho klíčů kanonický zdroj zná,
--      NEBO jeho klíče vedou na víc různých twinů, NEBO na twin jiného druhu.
--      To je spor, ne dvojí import → nesahá se, jen se vyjmenuje člověku.
--
-- ⛔ PROČ ÚPLNÁ SHODA (2026-09-28, majitel: „slučovat, pokud máme shodu";
--    „neslučovat jen podle jednoho klíče"). Původně stačil JEDEN shodný klíč:
--    duplikát se archivoval a jeho ostatní klíče (IČO, DIČ, jméno, které
--    kanonický zdroj nezná) se ukončily. Změřeno v produkci riq jen čtením:
--    z 759 twinů bez kanonické vazby má 563 úplnou shodu (1 987 klíčů → vždy
--    týž twin), 37 jen částečnou a 30 klíče u víc twinů. Stará třída by
--    archivovala i těch 67 a ukončila jejich 34 IČO, 36 DIČ a 135 jmen, tedy
--    sloučila firmy podle jediného společného klíče (typicky jména, které
--    v čase může patřit jiné firmě).
--
-- ⭐ NÁHLED JE VÝCHOZÍ (p_dry_run = true): počty a ukázka nejasných, nic nezapíše.
-- ⭐ DOHLEDATELNÉ A VRATNÉ: ostrý běh = řádek audit_journal (entity_type
--    'twin_decision', id = decision_id) se stavem PŘED zásahem u každého twinu
--    a každé vazby; twin nese v metadata `archivovano_rozhodnutim`. Vrácení:
--    revert_twin_decision_admin, přehled: get_decisions_admin.
--
-- Kontrakt: (text, text, boolean) ->
--   jsonb {ok, dry_run, decision_id?, zdroj, kanon, twinu:{duplikat,prevest,nejasne},
--          vazeb:{nahradit,prevest,duplikat_bez_protejsku} | {nahrazeno,prevedeno},
--          nejasne_ukazka} | {ok:false, error}
-- ============================================================================

CREATE OR REPLACE FUNCTION public.resolve_absorbed_ingest_source_admin(
  p_absorbed_source text,
  p_reason          text,
  p_dry_run         boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_kanon     text;
  v_decision  uuid := gen_random_uuid();
  v_tridy     jsonb;
  v_nejasne   jsonb;
  v_n_nahr    integer;
  v_n_prev    integer;
  v_n_zanik   integer;
  v_twiny     jsonb := '[]'::jsonb;
  v_nahrazene jsonb := '[]'::jsonb;
  v_prevedene jsonb := '[]'::jsonb;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff(auth.uid())) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nedostatečné oprávnění');
  END IF;
  IF coalesce(btrim(p_absorbed_source), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'p_absorbed_source je povinný');
  END IF;
  IF coalesce(btrim(p_reason), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'důvod (p_reason) je povinný — rozhodnutí bez důvodu nejde doložit');
  END IF;

  SELECT btrim(s.config ->> 'superseded_by') INTO v_kanon
    FROM public.agent_knowledge_sources s
   WHERE s.source_slug = p_absorbed_source
     AND NOT s.is_active
     AND coalesce(btrim(s.config ->> 'superseded_by'), '') <> '';
  IF v_kanon IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error',
      'zdroj není v registru pohlcený — o pohlcení rozhoduje člověk přes set_data_source_config (config.nahrazuje)');
  END IF;

  -- Živé vazby obou zdrojů s normalizovaným klíčem.
  CREATE TEMPORARY TABLE IF NOT EXISTS _pohl_vazby (
    ref_id uuid PRIMARY KEY, twin_id uuid, ref_kind text, k text, state text, valid_to timestamptz
  ) ON COMMIT DROP;
  CREATE TEMPORARY TABLE IF NOT EXISTS _kanon_vazby (
    twin_id uuid, ref_kind text, k text
  ) ON COMMIT DROP;
  CREATE TEMPORARY TABLE IF NOT EXISTS _pohl_twiny (
    twin_id uuid PRIMARY KEY, trida text
  ) ON COMMIT DROP;
  TRUNCATE _pohl_vazby, _kanon_vazby, _pohl_twiny;

  INSERT INTO _pohl_vazby
  SELECT r.id, r.twin_id, r.ref_kind, lower(regexp_replace(r.source_key, '[^[:alnum:]]', '', 'g')), r.state, r.valid_to
    FROM public.twin_external_refs r
   WHERE r.source = p_absorbed_source AND r.valid_to IS NULL AND r.state IN ('proposed', 'confirmed');

  INSERT INTO _kanon_vazby
  SELECT r.twin_id, r.ref_kind, lower(regexp_replace(r.source_key, '[^[:alnum:]]', '', 'g'))
    FROM public.twin_external_refs r
   WHERE r.source = v_kanon AND r.valid_to IS NULL AND r.state IN ('proposed', 'confirmed');

  -- Třída z ÚPLNÉ shody (viz hlavička): duplikát jen tehdy, když KAŽDÝ živý
  -- klíč twinu drží kanonický zdroj a všechny vedou na JEDEN twin téhož druhu
  -- entity. Částečná shoda, klíče rozdělené mezi víc twinů nebo twin jiného
  -- druhu = spor → nejasne; nikdy archivace podle jednoho klíče.
  WITH par AS (
    SELECT a.twin_id, a.ref_id, c.twin_id AS kanon_twin
      FROM _pohl_vazby a
      LEFT JOIN _kanon_vazby c
        ON c.ref_kind = a.ref_kind AND c.k = a.k AND c.twin_id <> a.twin_id
  ), souhrn AS (
    SELECT twin_id,
           count(DISTINCT ref_id)                                        AS klicu,
           count(DISTINCT ref_id) FILTER (WHERE kanon_twin IS NOT NULL)  AS sparovano,
           count(DISTINCT kanon_twin)                                    AS kanon_twinu,
           min(kanon_twin::text)::uuid                                   AS kanon_twin
      FROM par
     GROUP BY twin_id
  )
  INSERT INTO _pohl_twiny
  SELECT s.twin_id,
         CASE
           WHEN s.sparovano = 0 THEN 'prevest'
           WHEN NOT EXISTS (SELECT 1 FROM _kanon_vazby c WHERE c.twin_id = s.twin_id)
                AND s.sparovano = s.klicu
                AND s.kanon_twinu = 1
                AND (SELECT te.entity_type FROM public.twin_entities te WHERE te.id = s.twin_id)
                    = (SELECT tk.entity_type FROM public.twin_entities tk WHERE tk.id = s.kanon_twin)
             THEN 'duplikat'
           ELSE 'nejasne'
         END
    FROM souhrn s;

  SELECT jsonb_build_object(
           'duplikat', count(*) FILTER (WHERE trida = 'duplikat'),
           'prevest',  count(*) FILTER (WHERE trida = 'prevest'),
           'nejasne',  count(*) FILTER (WHERE trida = 'nejasne'))
    INTO v_tridy FROM _pohl_twiny;
  SELECT coalesce(jsonb_agg(twin_id ORDER BY twin_id), '[]'::jsonb) INTO v_nejasne
    FROM _pohl_twiny WHERE trida = 'nejasne';

  -- Vazby k ukončení: všechny u duplikátů + u převáděných ty, které týž twin
  -- už má od kanonického zdroje (převod by vyrobil dvojí vazbu).
  SELECT count(*) INTO v_n_nahr
    FROM _pohl_vazby a JOIN _pohl_twiny t ON t.twin_id = a.twin_id
   WHERE t.trida = 'duplikat'
      OR (t.trida = 'prevest' AND EXISTS (SELECT 1 FROM _kanon_vazby c
                                           WHERE c.twin_id = a.twin_id AND c.ref_kind = a.ref_kind AND c.k = a.k));
  SELECT count(*) INTO v_n_prev
    FROM _pohl_vazby a JOIN _pohl_twiny t ON t.twin_id = a.twin_id
   WHERE t.trida = 'prevest'
     AND NOT EXISTS (SELECT 1 FROM _kanon_vazby c
                      WHERE c.twin_id = a.twin_id AND c.ref_kind = a.ref_kind AND c.k = a.k);

  -- Klíče duplikátů, které kanonický zdroj NIKDE nezná: ukončením zmizí z živých
  -- vazeb (řádek zůstává jako historie). Náhled je ukazuje, aby o ztrátě
  -- rozhodoval člověk vědomě — rozhodnutí je nepřiřazuje jinému twinu sám.
  SELECT count(*) INTO v_n_zanik
    FROM _pohl_vazby a JOIN _pohl_twiny t ON t.twin_id = a.twin_id
   WHERE t.trida = 'duplikat'
     AND NOT EXISTS (SELECT 1 FROM _kanon_vazby c WHERE c.ref_kind = a.ref_kind AND c.k = a.k);

  IF p_dry_run THEN
    RETURN jsonb_build_object('ok', true, 'dry_run', true, 'zdroj', p_absorbed_source, 'kanon', v_kanon,
                              'twinu', v_tridy,
                              'vazeb', jsonb_build_object('nahradit', v_n_nahr, 'prevest', v_n_prev,
                                                          'duplikat_bez_protejsku', v_n_zanik),
                              'nejasne_ukazka', (SELECT coalesce(jsonb_agg(x), '[]'::jsonb)
                                                   FROM (SELECT jsonb_array_elements(v_nejasne) x LIMIT 20) s));
  END IF;

  -- 1) Ukončit vazby (stav a platnost PŘED zásahem jdou do rozhodnutí).
  WITH zmenene AS (
    UPDATE public.twin_external_refs r
       SET state = 'superseded', valid_to = now(), updated_at = now()
      FROM _pohl_vazby a JOIN _pohl_twiny t ON t.twin_id = a.twin_id
     WHERE r.id = a.ref_id
       AND (t.trida = 'duplikat'
            OR (t.trida = 'prevest' AND EXISTS (SELECT 1 FROM _kanon_vazby c
                                                 WHERE c.twin_id = a.twin_id AND c.ref_kind = a.ref_kind AND c.k = a.k)))
    RETURNING r.id, a.state AS pred_state
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', id, 'pred_state', pred_state) ORDER BY id), '[]'::jsonb)
    INTO v_nahrazene FROM zmenene;

  -- 2) Převést zbylé vazby převáděných twinů pod kanonický zdroj.
  WITH prevedene AS (
    UPDATE public.twin_external_refs r
       SET source = v_kanon, updated_at = now()
      FROM _pohl_vazby a JOIN _pohl_twiny t ON t.twin_id = a.twin_id
     WHERE r.id = a.ref_id
       AND t.trida = 'prevest'
       AND r.valid_to IS NULL
       AND r.source = p_absorbed_source
    RETURNING r.id
  )
  SELECT coalesce(jsonb_agg(id ORDER BY id), '[]'::jsonb) INTO v_prevedene FROM prevedene;

  -- 3) Archivovat duplikáty (stav PŘED zásahem jde do rozhodnutí).
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'pred_status', e.status) ORDER BY e.id), '[]'::jsonb)
    INTO v_twiny
    FROM public.twin_entities e JOIN _pohl_twiny t ON t.twin_id = e.id
   WHERE t.trida = 'duplikat';
  UPDATE public.twin_entities e
     SET status = 'archived',
         metadata = coalesce(e.metadata, '{}'::jsonb) || jsonb_build_object('archivovano_rozhodnutim', v_decision),
         updated_at = now()
    FROM _pohl_twiny t
   WHERE e.id = t.twin_id AND t.trida = 'duplikat';

  INSERT INTO public.audit_journal (id, user_id, action, action_type, area, entity_type, entity_id,
                                    summary, details, metadata)
  VALUES (v_decision, auth.uid(), 'twin.absorbed_source_resolved', 'update', 'twin',
          'twin_decision', v_decision::text,
          format('Pohlcený zdroj %s → %s: archivováno %s twinů, převedeno %s vazeb, ukončeno %s vazeb, nejasných %s — %s',
                 p_absorbed_source, v_kanon, jsonb_array_length(v_twiny), jsonb_array_length(v_prevedene),
                 jsonb_array_length(v_nahrazene), jsonb_array_length(v_nejasne), p_reason),
          jsonb_build_object('zdroj', p_absorbed_source, 'kanon', v_kanon, 'duvod', p_reason,
                             'kriterium', jsonb_build_object(
                               'pohlceny_zdroj', p_absorbed_source, 'kanon', v_kanon,
                               'klic', 'druh vazby + klíč jen z písmen a číslic, malými'),
                             'pocty', jsonb_build_object(
                               'twinu_archivovano', jsonb_array_length(v_twiny),
                               'vazeb_prevedeno', jsonb_array_length(v_prevedene),
                               'vazeb_ukonceno', jsonb_array_length(v_nahrazene),
                               'twinu_nejasnych', jsonb_array_length(v_nejasne)),
                             'twinu', v_tridy, 'archivovane_twiny', v_twiny,
                             'nahrazene_vazby', v_nahrazene, 'prevedene_vazby', v_prevedene,
                             'nejasne_twiny', v_nejasne, 'duplikat_bez_protejsku', v_n_zanik,
                             'vratne', true),
          jsonb_build_object('twinu', v_tridy,
                             'vazeb', jsonb_build_object('nahrazeno', jsonb_array_length(v_nahrazene),
                                                         'prevedeno', jsonb_array_length(v_prevedene))));

  RETURN jsonb_build_object('ok', true, 'dry_run', false, 'decision_id', v_decision,
                            'zdroj', p_absorbed_source, 'kanon', v_kanon, 'twinu', v_tridy,
                            'vazeb', jsonb_build_object('nahrazeno', jsonb_array_length(v_nahrazene),
                                                        'prevedeno', jsonb_array_length(v_prevedene)),
                            'nejasne_ukazka', (SELECT coalesce(jsonb_agg(x), '[]'::jsonb)
                                                 FROM (SELECT jsonb_array_elements(v_nejasne) x LIMIT 20) s));
END;
$function$;

REVOKE ALL ON FUNCTION public.resolve_absorbed_ingest_source_admin(text, text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.resolve_absorbed_ingest_source_admin(text, text, boolean) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_data_source_secrets.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: set_data_source_secrets
-- Popis: Uloží (nebo přepíše) pověření ke zdroji. Šifrovaně, auditovaně.
--
-- Tvar vstupu je ROVNOU tvar, který plugin o sobě tvrdí: klíče odpovídají
-- `config_schema.properties.*` s `secret: true`. Administrace tedy formulář
-- NEVYMÝŠLÍ — vykreslí ho ze schématu a pošle sem, co člověk vyplnil.
--
-- ⛔ PRÁZDNÁ HODNOTA MAŽE, NEULOŽÍ PRÁZDNO. „Vymazat pověření" je legitimní
-- úkon a musí mít vyjádření; uložený prázdný řetězec by naopak vypadal jako
-- vyplněný a stráž při aktivaci by ho pustila dál.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.set_data_source_secrets(
  p_source_slug text,
  p_secrets     jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
  v_source_id uuid;
  v_key       text;
  v_val       text;
  v_ulozeno   int := 0;
  v_smazano   int := 0;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  IF p_secrets IS NULL OR jsonb_typeof(p_secrets) <> 'object' THEN
    RAISE EXCEPTION 'set_data_source_secrets: p_secrets musí být objekt {klíč: hodnota}';
  END IF;

  SELECT id INTO v_source_id
    FROM public.agent_knowledge_sources
   WHERE source_slug = p_source_slug;

  IF v_source_id IS NULL THEN
    RAISE EXCEPTION 'set_data_source_secrets: zdroj % neexistuje', p_source_slug;
  END IF;

  FOR v_key, v_val IN SELECT k, v FROM jsonb_each_text(p_secrets) AS e(k, v) LOOP
    IF v_val IS NULL OR length(btrim(v_val)) = 0 THEN
      DELETE FROM public.agent_knowledge_source_secrets
       WHERE source_id = v_source_id AND secret_key = v_key;
      v_smazano := v_smazano + 1;
    ELSE
      INSERT INTO public.agent_knowledge_source_secrets (source_id, secret_key, value_enc, set_by)
      VALUES (v_source_id, v_key,
              public.aisha_encrypt_column_audited(v_val, jsonb_build_object(
                'ucel', 'ulozeni_povereni', 'entita', 'agent_knowledge_source',
                'entita_id', v_source_id::text, 'zdroj', p_source_slug, 'klic', v_key)),
              auth.uid())
      ON CONFLICT (source_id, secret_key) DO UPDATE
        SET value_enc = EXCLUDED.value_enc,
            set_by    = EXCLUDED.set_by,
            updated_at = now();
      v_ulozeno := v_ulozeno + 1;
    END IF;
  END LOOP;

  -- ⛔ Do žurnálu jdou JMÉNA klíčů, nikdy hodnoty ani jejich délky.
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'DATA_SOURCE_SECRETS_SET', jsonb_build_object(
    'area', 'ingest', 'severity', 'warning',
    'source_slug', p_source_slug,
    'keys', (SELECT jsonb_agg(k ORDER BY k) FROM jsonb_object_keys(p_secrets) k),
    'stored', v_ulozeno, 'cleared', v_smazano
  ));

  RETURN jsonb_build_object('source_slug', p_source_slug, 'stored', v_ulozeno, 'cleared', v_smazano);
END;
$$;

COMMENT ON FUNCTION public.set_data_source_secrets(text, jsonb) IS
  'Uloží pověření ke zdroji šifrovaně (aisha_encrypt_column_audited). Prázdná hodnota klíč MAŽE. Hodnoty se nikdy nevracejí ani neloggují. Admin/staff nebo service_role.';

REVOKE ALL ON FUNCTION public.set_data_source_secrets(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_data_source_secrets(text, jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_github_app_installation_suspended.sql
-- -----------------------------------------------------------------------------

-- Function: public.set_github_app_installation_suspended
-- Named, audited replacement for the two raw_query_admin UPDATEs in
-- svc-github-app/routes/webhook-bridge.ts (installation.suspend / deleted /
-- unsuspend webhooks). Toggles the suspended_at soft-delete marker:
--   p_suspended = true  -> suspended_at = now()  (suspend / uninstall)
--   p_suspended = false -> suspended_at = NULL   (unsuspend / reactivate)
-- Security: SECURITY DEFINER (service_role-invoked via rpcService), search_path pinned.

CREATE OR REPLACE FUNCTION public.set_github_app_installation_suspended(
  p_installation_id bigint,
  p_suspended boolean
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF p_installation_id IS NULL THEN
    RAISE EXCEPTION 'installation_id is required' USING ERRCODE = 'check_violation';
  END IF;

  IF p_suspended IS NULL THEN
    RAISE EXCEPTION 'p_suspended is required' USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.github_app_installations
     SET suspended_at = CASE WHEN p_suspended THEN now() ELSE NULL END,
         updated_at   = now()
   WHERE installation_id = p_installation_id;
END;
$function$;

COMMENT ON FUNCTION public.set_github_app_installation_suspended(bigint, boolean) IS
  'Toggles the suspended_at soft-delete marker on a GitHub App installation (suspend/uninstall vs unsuspend).';

REVOKE ALL ON FUNCTION public.set_github_app_installation_suspended(bigint, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_github_app_installation_suspended(bigint, boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_knowledge_source_concept_id.sql
-- -----------------------------------------------------------------------------

-- Function: set_knowledge_source_concept_id (Brick5 cross-lingual dedup)
--
-- source_concept_id = source-node identity. All locale variants of one source node
-- share a source_id, so they group under the same concept; items without a source_id
-- (ad-hoc/manual) are singletons (concept = own id). Retrieval (mcp_search_knowledge
-- v2/v3) dedups by source_concept_id so cross-lingual near-duplicates collapse to one
-- winning variant. Behaviour-neutral until retrieval reads it.
CREATE OR REPLACE FUNCTION public.set_knowledge_source_concept_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.source_concept_id := COALESCE(NEW.source_id, NEW.id);
  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.set_knowledge_source_concept_id() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_knowledge_source_concept_id() TO authenticated;
GRANT EXECUTE ON FUNCTION public.set_knowledge_source_concept_id() TO service_role;


