-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_slot_model_mapping.sql
-- -----------------------------------------------------------------------------

-- Function: set_slot_model_mapping
-- Soulforge: admin/staff RPC to bind a (slot, tier) pair to a specific model.
-- Writes to ai_model_registry.slot_affinity (jsonb).
-- Audit-traced; idempotent (overwrites the same slot:tier key).
-- Validates slot + tier enums and the target model existence.

CREATE OR REPLACE FUNCTION public.set_slot_model_mapping(
  p_slot     text,
  p_tier     text,
  p_model_id text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_target_registry_id uuid;
  v_user_id            uuid;
  v_key                text;
  v_old_value          text;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'admin_or_staff role required' USING ERRCODE = '22023';
  END IF;

  -- Validate slot enum (mirror of TaskSlot in soulforge.ts)
  IF p_slot NOT IN ('spark','ember','webSearch','desloppify','verify','compact','semantic','default') THEN
    RAISE EXCEPTION 'Invalid slot: %', p_slot USING ERRCODE = '22023';
  END IF;

  -- Validate tier enum (mirror of MessageComplexity)
  IF p_tier NOT IN ('greeting','simple','moderate','complex','deep_analysis') THEN
    RAISE EXCEPTION 'Invalid tier: %', p_tier USING ERRCODE = '22023';
  END IF;

  IF p_model_id IS NULL OR p_model_id = '' THEN
    RAISE EXCEPTION 'p_model_id is required' USING ERRCODE = '22023';
  END IF;

  -- Locate the model row this mapping should be attached to.
  SELECT id INTO v_target_registry_id
  FROM ai_model_registry
  WHERE model_id = p_model_id
  ORDER BY (NOT is_deprecated) DESC, last_seen_at DESC
  LIMIT 1;

  IF v_target_registry_id IS NULL THEN
    RAISE EXCEPTION 'Model % not found in ai_model_registry', p_model_id USING ERRCODE = '22023';
  END IF;

  v_key := p_slot || ':' || p_tier;

  -- Capture prior value for audit
  SELECT slot_affinity ->> v_key INTO v_old_value
  FROM ai_model_registry
  WHERE id = v_target_registry_id;

  UPDATE ai_model_registry
  SET slot_affinity = COALESCE(slot_affinity, '{}'::jsonb)
                     || jsonb_build_object(v_key, p_model_id),
      updated_at = now()
  WHERE id = v_target_registry_id;

  -- Defensive: remove any DUPLICATE binding of the same slot:tier on OTHER rows
  -- (slot:tier should map to exactly one model).
  UPDATE ai_model_registry
  SET slot_affinity = slot_affinity - v_key,
      updated_at = now()
  WHERE id != v_target_registry_id
    AND slot_affinity ? v_key;

  v_user_id := auth.uid();

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'soulforge.slot_mapping_updated',
    jsonb_build_object(
      'slot', p_slot,
      'tier', p_tier,
      'model_id', p_model_id,
      'old_model_id', v_old_value,
      'registry_id', v_target_registry_id
    )
  );

  RETURN jsonb_build_object(
    'status', 'updated',
    'slot', p_slot,
    'tier', p_tier,
    'model_id', p_model_id,
    'previous', v_old_value
  );
END;
$$;

COMMENT ON FUNCTION public.set_slot_model_mapping(text, text, text) IS
  'Soulforge: admin/staff updates ai_model_registry.slot_affinity for a slot×tier pair. '
  'Audit-traced. Validates enum membership and deduplicates the slot:tier key '
  'across registry rows.';

REVOKE ALL ON FUNCTION public.set_slot_model_mapping(text, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_slot_model_mapping(text, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.set_slot_model_mapping(text, text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_surface_section_override_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: set_surface_section_override_admin
-- Popis: JEDINÝ zapisovatel zákaznických úprav navigace. Administrace mění
--        sekci PATCHEM s uzavřenou množinou klíčů; neznámý klíč RAISE (uložit
--        nepochopené = trvalý neviditelný překlep). Prázdný patch {} = RESET
--        na šablonu (smazání override) — reset musí být jedna čitelná akce.
--
--        Jména NIKDY textem: title_key/group_key/reason_key jsou KLÍČE do
--        `translations`. Přejmenování sekce = upsert_translation pod klíčem +
--        (volitelně) tento override, pokud má sekce dostat klíč vlastní.
--
--        Optimistické zamykání po vzoru set_system_config_admin:
--        p_expected_updated_at chrání proti přepsání cizí souběžné změny.
-- Bezpečnost: SECURITY DEFINER + admin-only (nastavení instance, ne provoz).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.set_surface_section_override_admin(
  p_surface             text,
  p_patch               jsonb DEFAULT '{}'::jsonb,
  p_expected_updated_at timestamptz DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_uid     uuid  := auth.uid();
  v_patch   jsonb := COALESCE(p_patch, '{}'::jsonb);
  v_stray   text;
  v_current timestamptz;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = v_uid AND role = 'admin') THEN
    RAISE EXCEPTION 'Unauthorized: admin role required' USING ERRCODE = '42501';
  END IF;

  IF p_surface IS NULL OR btrim(p_surface) = '' THEN
    RAISE EXCEPTION 'surface cannot be empty' USING ERRCODE = '22023';
  END IF;

  -- Override bez šablony nemá k čemu patřit: FK by to shodil i tak, ale tahle
  -- hláška říká PROČ — sekci nejdřív deklaruje overlay, teprve pak se ladí.
  IF NOT EXISTS (SELECT 1 FROM public.surface_sections s WHERE s.surface = p_surface) THEN
    RAISE EXCEPTION 'section % is not declared by the instance template', p_surface
      USING ERRCODE = 'P0002';
  END IF;

  SELECT string_agg(k, ', ') INTO v_stray
    FROM jsonb_object_keys(v_patch) k
   WHERE k NOT IN ('title_key','icon','group_key','group_order','position','state','reason_key');
  IF v_stray IS NOT NULL THEN
    RAISE EXCEPTION 'unknown override key(s): %', v_stray USING ERRCODE = '22023';
  END IF;

  SELECT o.updated_at INTO v_current
    FROM public.surface_section_overrides o WHERE o.surface = p_surface;

  IF p_expected_updated_at IS NOT NULL
     AND v_current IS NOT NULL
     AND v_current IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'concurrent modification: override changed at %', v_current
      USING ERRCODE = '40001';
  END IF;

  IF v_patch = '{}'::jsonb THEN
    DELETE FROM public.surface_section_overrides WHERE surface = p_surface;
  ELSE
    INSERT INTO public.surface_section_overrides AS o
      (surface, title_key, icon, group_key, group_order, position, state, reason_key, updated_at, updated_by)
    VALUES (
      p_surface,
      v_patch->>'title_key',
      v_patch->>'icon',
      v_patch->>'group_key',
      (v_patch->>'group_order')::int,
      (v_patch->>'position')::int,
      v_patch->>'state',
      v_patch->>'reason_key',
      now(), v_uid)
    ON CONFLICT (surface) DO UPDATE SET
      -- PATCH sémantika: klíč nepřítomný v patchi ponechá dosavadní hodnotu,
      -- klíč s JSON null ji vrací šabloně. Bez toho by každý zápis musel
      -- opakovat celý override a dvě okna administrace by si přepisovala osy.
      title_key   = CASE WHEN v_patch ? 'title_key'   THEN v_patch->>'title_key'   ELSE o.title_key   END,
      icon        = CASE WHEN v_patch ? 'icon'        THEN v_patch->>'icon'        ELSE o.icon        END,
      group_key   = CASE WHEN v_patch ? 'group_key'   THEN v_patch->>'group_key'   ELSE o.group_key   END,
      group_order = CASE WHEN v_patch ? 'group_order' THEN (v_patch->>'group_order')::int ELSE o.group_order END,
      position    = CASE WHEN v_patch ? 'position'    THEN (v_patch->>'position')::int    ELSE o.position    END,
      state       = CASE WHEN v_patch ? 'state'       THEN v_patch->>'state'       ELSE o.state       END,
      reason_key  = CASE WHEN v_patch ? 'reason_key'  THEN v_patch->>'reason_key'  ELSE o.reason_key  END,
      updated_at  = now(),
      updated_by  = v_uid;
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_uid, 'surface.section_override_set',
          jsonb_build_object('surface', p_surface, 'patch', v_patch));

  RETURN jsonb_build_object('ok', true, 'surface', p_surface,
                            'reset', v_patch = '{}'::jsonb);
END;
$$;

REVOKE ALL ON FUNCTION public.set_surface_section_override_admin(text, jsonb, timestamptz) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_surface_section_override_admin(text, jsonb, timestamptz) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_system_config_admin.sql
-- -----------------------------------------------------------------------------

-- Function: set_system_config_admin
-- Purpose: Admin RPC for upserting system configuration entries
-- Security: SECURITY DEFINER + admin-only

DROP FUNCTION IF EXISTS public.set_system_config_admin(TEXT, JSONB, TEXT, TEXT, BOOLEAN);
DROP FUNCTION IF EXISTS public.set_system_config_admin(TEXT, JSONB, TEXT, TEXT, BOOLEAN, TIMESTAMPTZ);

CREATE OR REPLACE FUNCTION set_system_config_admin(
  p_category TEXT DEFAULT NULL,
  p_description TEXT DEFAULT NULL,
  p_expected_updated_at TIMESTAMPTZ DEFAULT NULL,
  p_is_public BOOLEAN DEFAULT false,
  p_key TEXT DEFAULT NULL,
  p_value JSONB DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_category TEXT := COALESCE(NULLIF(p_category, ''), 'general');
  v_existing_updated_at TIMESTAMPTZ;
  v_new_updated_at TIMESTAMPTZ := now();
BEGIN
  -- Authorization: admin only
  IF NOT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = v_user_id
      AND role IN ('admin')
  ) THEN
    RAISE EXCEPTION 'Unauthorized: admin role required';
  END IF;

  IF p_key IS NULL OR btrim(p_key) = '' THEN
    RAISE EXCEPTION 'key cannot be empty' USING ERRCODE = '22023';
  END IF;

  IF p_value IS NULL THEN
    RAISE EXCEPTION 'value cannot be null' USING ERRCODE = '22023';
  END IF;

  SELECT updated_at
  INTO v_existing_updated_at
  FROM system_config
  WHERE key = p_key
  FOR UPDATE;

  IF p_expected_updated_at IS NOT NULL
     AND v_existing_updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING
      MESSAGE = 'system_config_conflict',
      ERRCODE = '40001';
  END IF;

  INSERT INTO system_config (key, value, description, category, is_public, updated_at, updated_by)
  VALUES (p_key, p_value, p_description, v_category, p_is_public, v_new_updated_at, v_user_id)
  ON CONFLICT (key)
  DO UPDATE SET
    value = EXCLUDED.value,
    description = COALESCE(EXCLUDED.description, system_config.description),
    category = EXCLUDED.category,
    is_public = EXCLUDED.is_public,
    updated_at = v_new_updated_at,
    updated_by = v_user_id;

  -- Audit log (no sensitive values)
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'ADMIN_SET_SYSTEM_CONFIG',
    jsonb_build_object(
      'area', 'admin',
      'severity', 'info',
      'key', p_key,
      'category', v_category,
      'is_public', p_is_public
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'key', p_key,
    'category', v_category,
    'is_public', p_is_public,
    'updated_at', v_new_updated_at
  );
END;
$$;

-- Permissions
REVOKE ALL ON FUNCTION set_system_config_admin(TEXT, TEXT, TIMESTAMPTZ, BOOLEAN, TEXT, JSONB) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION set_system_config_admin(TEXT, TEXT, TIMESTAMPTZ, BOOLEAN, TEXT, JSONB) TO authenticated;

COMMENT ON FUNCTION set_system_config_admin(TEXT, TEXT, TIMESTAMPTZ, BOOLEAN, TEXT, JSONB) IS 'Admin-only: Upsert system_config entries with audit logging and optional CAS guard';


