-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_user_memory_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.set_user_memory_audited
-- Arguments: p_key text, p_value jsonb, p_source text DEFAULT 'inferred', p_confidence real DEFAULT 1.0, p_target_user_id uuid DEFAULT NULL
-- Security: SECURITY DEFINER
-- Source: Phase 4 — Agent Loop & Memory

CREATE OR REPLACE FUNCTION public.set_user_memory_audited(p_key text, p_value jsonb, p_source text DEFAULT 'inferred', p_confidence real DEFAULT 1.0, p_target_user_id uuid DEFAULT NULL)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_target   uuid := COALESCE(p_target_user_id, v_actor_id);
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_source NOT IN ('user_explicit', 'inferred', 'admin_set', 'agent_derived') THEN
    RAISE EXCEPTION USING MESSAGE = format('Invalid source: %s', p_source), ERRCODE = '22023';
  END IF;

  IF v_target <> v_actor_id AND p_source <> 'admin_set' THEN
    IF NOT is_admin_or_staff() THEN
      RAISE EXCEPTION 'Access denied: admin or staff required for cross-user memory write';
    END IF;
  END IF;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (v_actor_id, 'AI_MEMORY_WRITE', jsonb_build_object(
    'area', 'ai', 'severity', 'info',
    'target_user_id', v_target::text,
    'key', p_key, 'source', p_source,
    'confidence', p_confidence,
    'self_access', (v_target = v_actor_id)
  ));

  INSERT INTO ai_user_memory (user_id, key, value, confidence, source, last_updated)
  VALUES (v_target, p_key, p_value, p_confidence, p_source, now())
  ON CONFLICT (user_id, key)
  DO UPDATE SET value = EXCLUDED.value, confidence = EXCLUDED.confidence, source = EXCLUDED.source, last_updated = now();
END;
$$;

REVOKE ALL ON FUNCTION public.set_user_memory_audited(text, jsonb, text, real, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_user_memory_audited(text, jsonb, text, real, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_user_memory_for_agent.sql
-- -----------------------------------------------------------------------------

-- Function: public.set_user_memory_for_agent
-- Arguments: p_user_id uuid, p_key text, p_value jsonb, p_source text DEFAULT 'agent_derived', p_confidence real DEFAULT 0.8
-- Security: SECURITY DEFINER
-- Source: Phase 4 — Agent Loop & Memory

CREATE OR REPLACE FUNCTION public.set_user_memory_for_agent(p_user_id uuid, p_key text, p_value jsonb, p_source text DEFAULT 'agent_derived', p_confidence real DEFAULT 0.8)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $$
DECLARE
  v_actor_id uuid := auth.uid();
BEGIN
  IF v_actor_id IS NOT NULL AND NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (COALESCE(v_actor_id, p_user_id), 'AI_MEMORY_WRITE', jsonb_build_object(
    'area', 'ai', 'severity', 'info',
    'target_user_id', p_user_id::text,
    'key', p_key, 'source', p_source,
    'confidence', p_confidence, 'via', 'agent'
  ));

  INSERT INTO ai_user_memory (user_id, key, value, confidence, source, last_updated)
  VALUES (p_user_id, p_key, p_value, p_confidence, p_source, now())
  ON CONFLICT (user_id, key)
  DO UPDATE SET value = EXCLUDED.value, confidence = GREATEST(ai_user_memory.confidence, EXCLUDED.confidence), source = EXCLUDED.source, last_updated = now();
END;
$$;

REVOKE ALL ON FUNCTION public.set_user_memory_for_agent(uuid, text, jsonb, text, real) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_user_memory_for_agent(uuid, text, jsonb, text, real) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/should_auto_approve_order.sql
-- -----------------------------------------------------------------------------

-- Function: public.should_auto_approve_order
-- Arguments: p_user_id uuid, p_order_value numeric
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:28:06+01:00

CREATE OR REPLACE FUNCTION public.should_auto_approve_order(p_user_id uuid, p_order_value numeric)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule RECORD;
  v_has_role boolean;
  v_cert_level integer;
  v_uid uuid := auth.uid();
BEGIN
  -- ⛔ PREDIKÁT O TŘETÍ OSOBĚ JE ORÁKULUM (naměřeno 2026-09-19). Pravidla
  -- automatického schválení se ptají na roli (`user_roles`) a certifikační
  -- úroveň partnera, takže „schválil by se uuid X nákup za částku Y?" je
  -- binární vyhledávání cizí role a úrovně — pro libovolné uuid.
  --
  -- Odpovídá se jen o VOLAJÍCÍM; služba a správa na kohokoli. Změřeno, že to nic
  -- nerozbije: v repu ji nevolá žádná politika, funkce ani klient.
  -- `false` = „neschválit automaticky", tedy bezpečná výchozí cesta.
  IF v_uid IS NULL OR p_user_id IS DISTINCT FROM v_uid THEN
    IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
      RETURN false;
    END IF;
  END IF;

  -- Get user's certification level
  SELECT certification_level INTO v_cert_level
  FROM public.partner_profiles
  WHERE user_id = p_user_id;
  
  -- Check each active rule
  FOR v_rule IN
    SELECT required_role, min_certification_level, max_order_value
    FROM public.order_approval_rules
    WHERE is_active = true
    ORDER BY priority DESC
  LOOP
    -- Check role requirement
    IF v_rule.required_role IS NOT NULL THEN
      SELECT EXISTS(
        SELECT 1 FROM public.user_roles 
        WHERE user_id = p_user_id AND role = v_rule.required_role
      ) INTO v_has_role;
      IF NOT v_has_role THEN CONTINUE; END IF;
    END IF;
    
    -- Check certification level
    IF v_rule.min_certification_level IS NOT NULL THEN
      IF v_cert_level IS NULL OR v_cert_level < v_rule.min_certification_level THEN
        CONTINUE;
      END IF;
    END IF;
    
    -- Check order value
    IF v_rule.max_order_value IS NOT NULL AND p_order_value > v_rule.max_order_value THEN
      CONTINUE;
    END IF;
    
    -- All conditions passed - auto-approve
    RETURN true;
  END LOOP;
  
  RETURN false;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.should_auto_approve_order(p_user_id uuid, p_order_value numeric) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.should_auto_approve_order(p_user_id uuid, p_order_value numeric) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/simulate_model_tier_cost.sql
-- -----------------------------------------------------------------------------

-- Function: simulate_model_tier_cost
-- Simulate monthly cost for current model tier assignments.
-- Uses real pricing from ai_model_registry and average token usage from traces.
-- Source: migration 20260418130100_cost_intelligence_and_hippocampus.sql

CREATE OR REPLACE FUNCTION public.simulate_model_tier_cost(
  p_monthly_call_count integer DEFAULT 10000,
  p_task_type text DEFAULT 'chat'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_tiers jsonb;
  v_result jsonb := '{}'::jsonb;
  v_tier text;
  v_model_id text;
  v_model record;
  v_avg_tokens_in integer;
  v_avg_tokens_out integer;
  v_cost_per_call numeric;
  v_monthly_cost numeric;
  v_tier_keys text[] := ARRAY['greeting','simple','moderate','complex','deep_analysis'];
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = 'P0003';
  END IF;

  -- Get current tier assignments
  v_tiers := get_adaptive_model_tiers(p_task_type);

  -- Get average tokens from recent traces (or sensible defaults)
  SELECT
    COALESCE(avg((te.cost_json->>'tokens_in')::integer) FILTER (
      WHERE te.cost_json->>'tokens_in' IS NOT NULL), 500)::integer,
    COALESCE(avg((te.cost_json->>'tokens_out')::integer) FILTER (
      WHERE te.cost_json->>'tokens_out' IS NOT NULL), 200)::integer
  INTO v_avg_tokens_in, v_avg_tokens_out
  FROM ai_trace_events te
  WHERE te.created_at > now() - interval '7 days'
    AND te.cost_json IS NOT NULL;

  -- Calculate cost for each tier
  FOREACH v_tier IN ARRAY v_tier_keys
  LOOP
    v_model_id := v_tiers ->> v_tier;
    IF v_model_id IS NOT NULL THEN
      SELECT
        r.input_price_per_m,
        r.model_id,
        r.output_price_per_m,
        r.provider
      INTO v_model
      FROM ai_model_registry r
      WHERE r.model_id = v_model_id
      LIMIT 1;

      IF v_model IS NOT NULL THEN
        v_cost_per_call := (
          COALESCE(v_model.input_price_per_m, 0) * v_avg_tokens_in / 1000000.0 +
          COALESCE(v_model.output_price_per_m, 0) * v_avg_tokens_out / 1000000.0
        );
        v_monthly_cost := v_cost_per_call * p_monthly_call_count;

        v_result := v_result || jsonb_build_object(v_tier, jsonb_build_object(
          'avg_tokens_in', v_avg_tokens_in,
          'avg_tokens_out', v_avg_tokens_out,
          'cost_per_call', round(v_cost_per_call, 6),
          'model_id', v_model_id,
          'monthly_cost', round(v_monthly_cost, 2),
          'provider', v_model.provider
        ));
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'monthly_call_count', p_monthly_call_count,
    'simulation_date', now(),
    'task_type', p_task_type,
    'tiers', v_result,
    'total_monthly', round((
      SELECT COALESCE(sum((t.value->>'monthly_cost')::numeric), 0)
      FROM jsonb_each(v_result) t
    ), 2)
  );
END;
$function$;

COMMENT ON FUNCTION simulate_model_tier_cost(integer, text) IS
  'Simulate monthly cost for current model tier assignments. '
  'Uses real pricing from ai_model_registry and average token usage from traces.';

REVOKE ALL ON FUNCTION public.simulate_model_tier_cost(integer, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.simulate_model_tier_cost(integer, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.simulate_model_tier_cost(integer, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/start_playwright_run.sql
-- -----------------------------------------------------------------------------

-- start_playwright_run
-- Creates a queued Playwright run targeting a deployed environment.
-- staging_auto: invoked by WF_DEPLOY_STORY after staging deploy (service_role).
-- production_manual: invoked by admin via webhook (sets approval_required=true,
--   runner waits until approve_playwright_run is called).
-- scheduled: cron-like, optional, follow-up.
--
-- Production integration (migration 20260518040000):
--   p_app_name → derive target_base_url from coolify_app_slots when 'auto', capture active_slot
--   p_story_id → emit qa_playwright_requested story_entry (mirrors web_artifact_upload)

CREATE OR REPLACE FUNCTION public.start_playwright_run(
  p_trigger_kind public.playwright_run_trigger,
  p_target_env text,
  p_target_base_url text,
  p_suite text DEFAULT 'all',
  p_deploy_ref text DEFAULT NULL,
  p_metadata jsonb DEFAULT '{}'::jsonb,
  p_story_id uuid DEFAULT NULL,
  p_app_name text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_run_id uuid;
  v_is_service boolean;
  v_approval_required boolean;
  v_target_base_url text;
  v_active_slot text;
  v_resolved record;
BEGIN
  v_is_service := public.is_service_role();

  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin/staff or service_role required';
  END IF;

  IF p_target_env IS NULL OR p_target_env = '' THEN
    RAISE EXCEPTION 'target_env required';
  END IF;

  v_target_base_url := p_target_base_url;

  -- Derive from coolify_app_slots when caller wants live URL.
  IF p_app_name IS NOT NULL THEN
    SELECT * INTO v_resolved FROM public.resolve_deployed_url(p_app_name);
    IF v_resolved.target_base_url IS NOT NULL THEN
      v_active_slot := v_resolved.active_slot;
      IF v_target_base_url IS NULL OR v_target_base_url IN ('', 'auto') THEN
        v_target_base_url := v_resolved.target_base_url;
      END IF;
    ELSIF v_target_base_url IS NULL OR v_target_base_url IN ('', 'auto') THEN
      RAISE EXCEPTION 'app_name % has no live slot in coolify_app_slots; pass explicit target_base_url', p_app_name;
    END IF;
  END IF;

  IF v_target_base_url IS NULL OR v_target_base_url !~ '^https?://' THEN
    RAISE EXCEPTION 'target_base_url must be a valid http(s) URL (got %)', v_target_base_url;
  END IF;
  IF p_trigger_kind = 'staging_auto' AND NOT v_is_service THEN
    RAISE EXCEPTION 'staging_auto trigger requires service_role';
  END IF;

  -- production runs always need explicit approval.
  v_approval_required := (p_trigger_kind = 'production_manual');

  INSERT INTO public.playwright_runs (
    trigger_kind, target_env, target_base_url, suite, deploy_ref,
    status, approval_required, requested_by, metadata,
    app_name, active_slot, story_id
  ) VALUES (
    p_trigger_kind, p_target_env, v_target_base_url, p_suite, p_deploy_ref,
    'queued', v_approval_required, auth.uid(), COALESCE(p_metadata, '{}'::jsonb),
    p_app_name, v_active_slot, p_story_id
  )
  RETURNING id INTO v_run_id;

  -- Story-link the request so the storyloop chat reflects QA work.
  IF p_story_id IS NOT NULL THEN
    INSERT INTO public.story_entries (story_id, entry_type, content, metadata, created_by)
    VALUES (
      p_story_id, 'qa_playwright_requested', NULL,
      jsonb_build_object(
        'type', 'qa_playwright_requested',
        'run_id', v_run_id,
        'trigger_kind', p_trigger_kind::text,
        'target_env', p_target_env,
        'target_base_url', v_target_base_url,
        'app_name', p_app_name,
        'active_slot', v_active_slot,
        'suite', p_suite,
        'deploy_ref', p_deploy_ref,
        'approval_required', v_approval_required
      ),
      auth.uid()
    );
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'PLAYWRIGHT_RUN_START',
    jsonb_build_object(
      'area', 'qa',
      'severity', 'info',
      'entity_type', 'playwright_run',
      'entity_id', v_run_id::text,
      'trigger_kind', p_trigger_kind::text,
      'target_env', p_target_env,
      'target_base_url', v_target_base_url,
      'approval_required', v_approval_required,
      'app_name', p_app_name,
      'active_slot', v_active_slot,
      'story_id', p_story_id,
      'tags', ARRAY['stack', 'qa', 'playwright', p_trigger_kind::text]
    )
  );

  RETURN v_run_id;
END;
$$;

REVOKE ALL ON FUNCTION public.start_playwright_run(public.playwright_run_trigger, text, text, text, text, jsonb, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.start_playwright_run(public.playwright_run_trigger, text, text, text, text, jsonb, uuid, text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/start_test_attempt.sql
-- -----------------------------------------------------------------------------

-- Function: public.start_test_attempt
-- Arguments: p_template_id uuid
-- Description: Opens a System-B test attempt for the caller against a per-cohort test
--   template. Access is gated on enrollment: the caller must be enrolled in a study
--   that offers this template (study_test_templates). SECURITY DEFINER so attempt rows
--   are server-created — clients hold no write grant on test_attempts (see grants), so
--   a passing attempt cannot be forged.
-- Security: SECURITY DEFINER, authenticated only.

CREATE OR REPLACE FUNCTION public.start_test_attempt(p_template_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_active boolean;
  v_attempt_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_template_id IS NULL THEN
    RAISE EXCEPTION 'Missing template id';
  END IF;

  SELECT is_active INTO v_active FROM public.test_templates WHERE id = p_template_id;
  IF NOT FOUND OR NOT COALESCE(v_active, false) THEN
    RAISE EXCEPTION 'Test template not available';
  END IF;

  -- Per-cohort access: the caller must be enrolled in a study that offers this template.
  IF NOT EXISTS (
    SELECT 1
    FROM public.study_test_templates stt
    JOIN public.study_registrations sr ON sr.study_id = stt.study_id
    WHERE stt.template_id = p_template_id
      AND sr.user_id = v_user_id
      AND sr.status IN ('enrolled', 'active')
  ) THEN
    RAISE EXCEPTION 'Not enrolled in a study offering this test' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.test_attempts (user_id, template_id, started_at)
  VALUES (v_user_id, p_template_id, now())
  RETURNING id INTO v_attempt_id;

  RETURN v_attempt_id;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.start_test_attempt(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.start_test_attempt(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.start_test_attempt(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/start_web_artifact_ingest.sql
-- -----------------------------------------------------------------------------

-- start_web_artifact_ingest
-- Creates a new web artifact ingest job (or returns existing on idempotency-key match).
-- Authz: admin/staff OR story participant OR service_role.
--
-- Appends a story_entries row (entry_type=web_artifact_upload | web_artifact_scrape)
-- so the storyloop timeline reflects the new operator turn. Default seed and
-- redesign sources do not append from here.

CREATE OR REPLACE FUNCTION public.start_web_artifact_ingest(
  p_story_id uuid,
  p_kind public.web_artifact_kind,
  p_source_type public.web_artifact_source_type,
  p_source_url text DEFAULT NULL,
  p_source_storage_path text DEFAULT NULL,
  p_idempotency_key text DEFAULT NULL,
  p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  v_job_id uuid;
  v_is_service boolean;
  v_existing_id uuid;
  v_idempotency_key text;
  v_entry_type text;
  v_entry_metadata jsonb;
BEGIN
  v_is_service := public.is_service_role();

  IF p_idempotency_key IS NULL OR p_idempotency_key = '' THEN
    RAISE EXCEPTION 'idempotency_key required';
  END IF;
  v_idempotency_key := p_idempotency_key;

  IF NOT v_is_service
     AND NOT public.is_admin_or_staff()
     AND (p_story_id IS NULL OR NOT public.is_story_participant(auth.uid(), p_story_id))
  THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, story participant, or service_role required';
  END IF;

  IF p_source_type = 'default_seed' AND NOT v_is_service THEN
    RAISE EXCEPTION 'default_seed source_type is service_role only';
  END IF;

  IF p_source_type IN ('folder_upload', 'url_scrape') AND p_story_id IS NULL THEN
    RAISE EXCEPTION 'story_id required for source_type %', p_source_type;
  END IF;

  SELECT id INTO v_existing_id
  FROM public.web_artifact_jobs
  WHERE idempotency_key = v_idempotency_key;

  IF v_existing_id IS NOT NULL THEN
    RETURN v_existing_id;
  END IF;

  INSERT INTO public.web_artifact_jobs (
    story_id, kind, source_type, source_url, source_storage_path,
    idempotency_key, created_by, metadata, status
  ) VALUES (
    p_story_id, p_kind, p_source_type, p_source_url, p_source_storage_path,
    v_idempotency_key, auth.uid(), COALESCE(p_metadata, '{}'::jsonb), 'pending'
  )
  RETURNING id INTO v_job_id;

  IF p_story_id IS NOT NULL AND p_source_type IN ('folder_upload', 'url_scrape') THEN
    v_entry_type := CASE p_source_type
      WHEN 'folder_upload' THEN 'web_artifact_upload'
      WHEN 'url_scrape' THEN 'web_artifact_scrape'
    END;
    v_entry_metadata := jsonb_build_object(
      'type', v_entry_type,
      'job_id', v_job_id,
      'source_url', p_source_url,
      'source_storage_path', p_source_storage_path,
      'source_filename', COALESCE(p_metadata->>'source_filename', NULL)
    );
    INSERT INTO public.story_entries (story_id, entry_type, content, metadata, created_by)
    VALUES (p_story_id, v_entry_type, NULL, v_entry_metadata, auth.uid());
  END IF;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'WEB_ARTIFACT_INGEST_START',
    jsonb_build_object(
      'area', 'content',
      'severity', 'info',
      'entity_type', 'web_artifact_job',
      'entity_id', v_job_id::text,
      'story_id', p_story_id,
      'kind', p_kind::text,
      'source_type', p_source_type::text,
      'tags', ARRAY['stack', 'story', 'web_artifact', 'ingest']
    )
  );

  RETURN v_job_id;
END;
$$;

REVOKE ALL ON FUNCTION public.start_web_artifact_ingest(uuid, public.web_artifact_kind, public.web_artifact_source_type, text, text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.start_web_artifact_ingest(uuid, public.web_artifact_kind, public.web_artifact_source_type, text, text, text, jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/store_dashboard_hash.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: store_dashboard_hash
-- Popis: Insert nový render record. Volat po každém pokusu o build (i když skipnutý).
--        Validuje publish_status a triggered_by enum.
-- Volá: WF_APPSMITH_DASHBOARD_BUILDER po importu / skipu / failure
-- Auth: service_role nebo admin/staff
-- ============================================================================

CREATE OR REPLACE FUNCTION public.store_dashboard_hash(
  p_content_hash    text,
  p_triggered_by    text,
  p_publish_status  text,
  p_dashboard_slug  text DEFAULT 'aisha-ops',
  p_appsmith_app_id text DEFAULT NULL,
  p_diff_summary    jsonb DEFAULT NULL,
  p_publish_error   text DEFAULT NULL,
  p_duration_ms     int DEFAULT NULL,
  p_metadata        jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id uuid;
  v_is_service boolean;
BEGIN
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '22023';
  END IF;

  IF p_publish_status NOT IN ('pending', 'published', 'skipped_no_change', 'failed') THEN
    RAISE EXCEPTION 'Invalid publish_status: %', p_publish_status USING ERRCODE = '22023';
  END IF;
  IF p_triggered_by NOT IN ('cron_30min', 'manual_webhook', 'first_bootstrap', 'force_rebuild') THEN
    RAISE EXCEPTION 'Invalid triggered_by: %', p_triggered_by USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.dashboard_render_history (
    dashboard_slug, content_hash, triggered_by, diff_summary,
    appsmith_app_id, publish_status, publish_error, duration_ms, metadata
  )
  VALUES (
    p_dashboard_slug, p_content_hash, p_triggered_by, p_diff_summary,
    p_appsmith_app_id, p_publish_status, p_publish_error, p_duration_ms, p_metadata
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.store_dashboard_hash(text, text, text, text, text, jsonb, text, int, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.store_dashboard_hash(text, text, text, text, text, jsonb, text, int, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.store_dashboard_hash(text, text, text, text, text, jsonb, text, int, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/storno_values_param.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: storno_values_param
-- Popis: KÓDY STORNA ZDROJE — parametr instance `storno_values` ze
--        source_params bloku (pole řetězců). Které hodnoty pole `storno`
--        znamenají stornovaný doklad, je kódování zdroje (Money: 1 = stornovaný,
--        2 = stornovací doklad, naměřeno 2026-09-26), ne vlastnost platformy.
--        Chybí-li, je to prázdné pole = instance storno nedeklarovala a nic se
--        za storno nepovažuje. Jiný tvar než pole řetězců = chyba (22023).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.storno_values_param(p_params jsonb)
RETURNS text[]
LANGUAGE plpgsql
IMMUTABLE
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v jsonb := p_params->'storno_values';
BEGIN
  IF v IS NULL OR v = 'null'::jsonb THEN
    RETURN '{}'::text[];
  END IF;
  IF jsonb_typeof(v) <> 'array'
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(v) x WHERE jsonb_typeof(x) <> 'string') THEN
    RAISE EXCEPTION 'storno_values musí být pole řetězců (kódy storna zdroje), je %', v
      USING ERRCODE = '22023';
  END IF;
  RETURN ARRAY(SELECT jsonb_array_elements_text(v));
END;
$$;

REVOKE ALL ON FUNCTION public.storno_values_param(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.storno_values_param(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_counterparty_aging.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_counterparty_aging
-- Popis: blok `chart` (bar) — kolik protistrana dluží podle STÁŘÍ dluhu:
--        ještě nesplatné · 1–30 · 31–90 · 91–365 · přes rok (dní po splatnosti).
--        Hodnota = Kč (amount_unpaid vydaných faktur), stav pásma: ok → warning
--        → loss. Pásmo bez dluhu se NEKRESLÍ (JAZYK-03), pořadí je stáří.
--        Co dnes dluží, rozhoduje invoice_state (předepsané a storno mimo).
-- Popisek pásma je číselný rozsah (jazykově neutrální); „nesplatné" nese
-- `label_key`, protože slovo se překládá.
-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, dohoda 2026-09-24 „opraví se v PR karty"):
--    `freshness_at` = nejnovější příchod verze dokladu (`created_at`) ve STEJNÉM univerzu
--    dokladů protistrany, ze kterého je hodnota — ne čas zavolání. Karta tak neřekne
--    „dnes", když poslední doklad té firmy dorazil před týdny. Prázdné univerzum →
--    `trace_id` nese `:no_data` a `now()` je jen záloha coalesce.
--    Univerzum = VŠECHNY vydané faktury protistrany: prázdné pásmo („nedluží")
--    je tvrzení platné k poslednímu dokladu, ne jen k otevřeným.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_counterparty_aging(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  with id as (select icos, names, twins, label from public.counterparty_resolve(p_params)),
  cfg as (select public.receivable_from_param(p_params) as od, public.storno_values_param(p_params) as storno),
  -- Jen doklady, které DNES dluží (invoice_state: vystaveno / po splatnosti).
  -- Předepsané (pohledávka teprve vznikne), storno a dobropis stáří nemají.
  fa as (
    select (d.fields->'amount_unpaid'->>'value')::numeric as zbyva,
           case when d.fields->'due_date'->>'value' ~ '^\d{4}-\d{2}-\d{2}$'
                then current_date - (d.fields->'due_date'->>'value')::date end as dni
    from id, cfg, public.counterparty_docs(id.icos, id.names, 'invoice') d
    where d.fields->'document_subtype'->>'value' = 'issued'
      and public.invoice_state(d.fields, cfg.od, cfg.storno) in ('open', 'overdue')
  ),
  pasma(poradi, label, label_key, od, do_, stav) as (values
    (1, '≤ 0',   'app.cp.aging.not_due', null::int, 0,    'ok'),
    (2, '1–30',   null,                   1,         30,   'warning'),
    (3, '31–90',  null,                   31,        90,   'warning'),
    (4, '91–365', null,                   91,        365,  'loss'),
    (5, '365+',   null,                   366,       null, 'loss')
  ),
  s as (
    select p.poradi, p.label, p.label_key, p.stav, round(sum(fa.zbyva)) as castka, count(*) as n
      from pasma p join fa
        -- faktura BEZ splatnosti do žádného pásma nepatří (stáří neznáme) —
        -- přiřadit ji „nesplatným" by byl vymyšlený údaj
        on fa.dni is not null
       and fa.dni >= coalesce(p.od, -100000) and fa.dni <= coalesce(p.do_, 100000)
     group by 1, 2, 3, 4
  ),
  celkem as (select sum(castka) c from s),
  cas as (
    select max(d.created_at) as vznik
      from id, public.counterparty_docs(id.icos, id.names, 'invoice') d
     where d.fields->'document_subtype'->>'value' = 'issued'
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'kind', 'bar',
      'unit_key', 'app.units.czk',
      'points', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                  'label', s.label, 'label_key', s.label_key, 'value', s.castka,
                  'pct', round(100 * s.castka / nullif((select c from celkem), 0), 1),
                  'state', s.stav)) order by s.poradi) from s), '[]'::jsonb)),
    'provenance', jsonb_build_object(
      'source_slug', 'li-source-registry',
      'trace_id', 'counterparty-aging' || case when (select vznik from cas) is null then ':no_data' else '' end,
      'freshness_at', to_char(coalesce((select vznik from cas), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')));
$$;

REVOKE ALL ON FUNCTION public.get_counterparty_aging(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_counterparty_aging(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_counterparty_card.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_counterparty_card
-- Popis: blok `record_detail` — hlavička karty protistrany: kdo to je, kolik
--        twinů ho v modelu nese, pod jakými jmény vystupoval v čase, s kým z nás
--        obchoduje. Vstup {debtor} nebo {twin_id} (counterparty_resolve).
--
-- Odznaky (i18n klíče) nesou NÁLEZ identity: víc twinů téhož IČO = roztříštěná
-- identita (k úklidu), žádný twin = protistrana v modelu neexistuje. Obojí je
-- stav dat, který má správce vidět u konkrétní firmy, ne v souhrnu.
-- Jména v čase se berou z DOKLADŮ (jméno · první–poslední doklad), protože firma
-- se přejmenovává a jméno není identita (jméno je parametr v čase). Období je
-- výskyt jména v NAŠICH dokladech, ne platnost jména v rejstříku — popisek to
-- říká slovy („v našich dokladech").
--
-- ⭐ SOUČASNOST PRVNÍ (majitel 2026-09-28): uživatel se ptá na aktuální stav,
--    historie doplňuje. Hned pod identitou proto stojí VZTAH V ČASE
--    (counterparty_periods — tatáž pravda jako Ask): odběratel / dodavatel
--    první → poslední vystavený doklad do dneška, a doklady, k nimž zdroj
--    NEDODAL stav úhrady (počet + období). Bez nich karta u firmy, s níž
--    naposledy obchodovala před lety, ukazovala „bez dluhu" a nic o čase.
-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, dohoda 2026-09-24 „opraví se v PR karty"):
--    `freshness_at` = nejnovější příchod verze dokladu (`created_at`) ve STEJNÉM univerzu
--    dokladů protistrany, ze kterého je hodnota — ne čas zavolání. Karta tak neřekne
--    „dnes", když poslední doklad té firmy dorazil před týdny. Prázdné univerzum →
--    `trace_id` nese `:no_data` a `now()` je jen záloha coalesce.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_counterparty_card(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  with id as (select icos, names, twins, label from public.counterparty_resolve(p_params)),
  fa as (
    select d.fields f, d.created_at vznik from id, public.counterparty_docs(id.icos, id.names, 'invoice') d
  ),
  -- smlouvy podle IČO i navržené k twinu — týž výčet jako síť vazeb
  sm as (
    select count(*) n, count(*) filter (where c.certainty = 'proposed') navrzeno
      from id, public.counterparty_contracts(id.icos, id.names, id.twins) c
  ),
  -- vztah v čase: role × období (kódy storna z parametrů bloku, jsou-li)
  vz as (
    select p.* from id, public.counterparty_periods(id.icos, id.names, public.storno_values_param(p_params)) p
  ),
  jm as (
    select f->'counterparty'->>'value' as jmeno,
           min(f->'issue_date'->>'value') filter (where f->'issue_date'->>'value' ~ '^\d{4}-\d{2}-\d{2}$') as od,
           max(f->'issue_date'->>'value') filter (where f->'issue_date'->>'value' ~ '^\d{4}-\d{2}-\d{2}$') as do_
      from fa where f->'counterparty'->>'value' is not null group by 1
  ),
  -- ⭐ SCHVÁLENÉ JMÉNO (majitel 2026-09-28): název platí po schválení; změna jména na
  -- dokladu má přijít jako návrh ingestu a UPOZORNIT. Pole „Název" je proto ke kontrole,
  -- když firma schválený název nemá, nebo když se nejnovější jméno z dokladů od
  -- schváleného liší (firma se přejmenovala a návrh čeká na schválení).
  schv as (
    select r.source_key as jmeno
      from id
      cross join lateral jsonb_array_elements(id.twins) t
      join public.twin_external_refs r on r.twin_id = (t->>'id')::uuid
     where r.ref_kind in ('company_name', 'nase_firma') and r.state = 'confirmed'
       and (r.valid_to is null or r.valid_to > now())
     order by r.valid_from desc nulls last, r.confirmed_at desc nulls last
     limit 1
  ),
  posledni as (
    select btrim(f->'counterparty'->>'value') as jmeno from fa
     where length(btrim(coalesce(f->'counterparty'->>'value', ''))) between 2 and 80
     order by f->'issue_date'->>'value' desc nulls last limit 1
  ),
  pole as (
    select jsonb_build_array(
      jsonb_build_object('key','nazev', 'label_key','app.cp.field.name',  'value', (select label from id),
        'state', case when (select jmeno from schv) is null then 'needs_review'
                      when (select jmeno from posledni) is not null
                           and lower((select jmeno from posledni)) <> lower((select jmeno from schv)) then 'needs_review'
                      else 'auto_pass' end),
      jsonb_build_object('key','ico',   'label_key','app.cp.field.ico',   'value', nullif(array_to_string((select icos from id), ', '), '')),
      jsonb_build_object('key','dic',   'label_key','app.cp.field.vat_id','value',
        (select string_agg(distinct f->'counterparty_vat_id'->>'value', ', ') from fa)),
      jsonb_build_object('key','adresa','label_key','app.cp.field.address','value',
        (select f->'counterparty_address'->>'value' from fa
          where f->'counterparty_address'->>'value' is not null
          order by f->'issue_date'->>'value' desc nulls last limit 1)),
      -- období jako data (ISO, jazykově neutrální); slova nese label_key
      jsonb_build_object('key','odberatel','label_key','app.cp.field.as_customer','value',
        (select to_char(prvni, 'YYYY-MM-DD') || ' → ' || to_char(posledni, 'YYYY-MM-DD') from vz where vztah = 'customer')),
      jsonb_build_object('key','dodavatel','label_key','app.cp.field.as_supplier','value',
        (select to_char(prvni, 'YYYY-MM-DD') || ' → ' || to_char(posledni, 'YYYY-MM-DD') from vz where vztah = 'supplier')),
      -- stav úhrady je snímek zdroje; kde chybí, karta to PŘIZNÁ (dlaždice ukážou „—")
      jsonb_build_object('key','bez_stavu','label_key','app.cp.field.payment_unknown','value',
        (select bez_stavu || ' (' || to_char(bez_stavu_prvni, 'YYYY-MM-DD') || ' → ' || to_char(bez_stavu_posledni, 'YYYY-MM-DD') || ')'
           from vz where vztah = 'customer' and bez_stavu > 0)),
      jsonb_build_object('key','identita','label_key','app.cp.field.twins',
        'value', jsonb_array_length((select twins from id))::text,
        'state', case jsonb_array_length((select twins from id)) when 1 then 'auto_pass' else 'needs_review' end),
      jsonb_build_object('key','jmena','label_key','app.cp.field.names_in_time','value',
        (select string_agg(jmeno || ' (' || coalesce(left(od, 7), '?') || ' → ' || coalesce(left(do_, 7), '?') || ')', ' · ' order by od nulls last) from jm)),
      jsonb_build_object('key','firmy','label_key','app.cp.field.our_companies','value',
        (select string_agg(distinct f->'owner_company'->>'value', ' · ') from fa where f->'owner_company'->>'value' <> '')),
      jsonb_build_object('key','faktury','label_key','app.cp.field.invoices','value',
        (select count(*) filter (where f->'document_subtype'->>'value' = 'issued') || ' / ' ||
                count(*) filter (where f->'document_subtype'->>'value' = 'received') from fa)),
      -- smlouva jen NAVRŽENÁ k twinu = strana nepotvrzená → k potvrzení (sm_identifikace).
      -- Bez návrhu klíč `state` VYNECHAT, ne null: maska record_detail null nezná a zahodila
      -- by celou kartu („Zatím není co zobrazit") — chytil kontrakt bloků v CI kola 7.
      jsonb_build_object('key','smlouvy','label_key','app.cp.field.contracts','value', (select n::text from sm))
        || case when (select navrzeno from sm) > 0 then jsonb_build_object('state','needs_review') else '{}'::jsonb end
    ) as arr
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'record_id', coalesce((select icos[1] from id), (select label from id)),
      'badges', to_jsonb(array_remove(array[
         case when jsonb_array_length((select twins from id)) > 1 then 'app.cp.badge.identity_split' end,
         case when jsonb_array_length((select twins from id)) = 0 then 'app.cp.badge.no_twin' end], null)),
      -- JAZYK-03: prázdný údaj se nekreslí — pole bez hodnoty z pole vypadne
      'fields', coalesce((select jsonb_agg(x) from pole, jsonb_array_elements(pole.arr) x
                           where x->>'value' is not null and x->>'value' <> ''), '[]'::jsonb)),
    'provenance', jsonb_build_object(
      'source_slug', 'twin+doc-evidence',
      'trace_id', 'counterparty-card' || case when (select max(vznik) from fa) is null then ':no_data' else '' end,
      'freshness_at', to_char(coalesce((select max(vznik) from fa), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')));
$$;

REVOKE ALL ON FUNCTION public.get_counterparty_card(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_counterparty_card(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_counterparty_metric.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_counterparty_metric
-- Popis: blok `kpi_tile` — jedno číslo karty protistrany. Jeden RPC, víc
--        otázek: `metric` v source_params bloku.
--          receivable_open     K ÚHRADĚ: vystaveno (ve splatnosti) + po splatnosti − dobropisy
--          receivable_overdue  DLUH = po splatnosti (majitel 2026-09-26: dluhem je
--                              faktura po datu splatnosti); dobropis odečítá hned
--          oldest_overdue_days nejstarší dluh ve dnech po splatnosti
--          scheduled           PŘEDEPSÁNO: faktury, jejichž pohledávka teprve vznikne
--          invoiced_12m        vyfakturováno za [dnes − 365, dnes] (bez storna)
--        `receivable_from` v source_params: od kterého data je doklad
--        pohledávkou (výchozí datum vystavení — rozhodnutí majitele 2026-09-25).
-- Stav dokladu NEPOČÍTÁ tahle funkce — bere ho z invoice_state (jeden slovník
-- pro kartu, stáří, faktury odběratele i dlužníky). Naměřeno 2026-09-25 na
-- kartě Inspirace: faktury vystavené dopředu se sčítaly jako dluh
-- (588 383 Kč místo 259 597 Kč) a okno 12 m nemělo horní mez.
-- Pohledávky = JEN VYDANÉ faktury (document_subtype = issued). Změřeno
-- 2026-09-23: všech 268 faktur s dluhem po splatnosti je vydaných — přijatá
-- faktura je náš závazek, ne jeho dluh.
-- Stav dlaždice: po splatnosti > 0 → warning; nejstarší dluh > 365 dní → loss.
-- ⭐ NEZNÁMÉ ≠ 0 (majitel 2026-09-28): stav úhrady je SNÍMEK zdroje. Metriky
--    úhrady (receivable_open, receivable_overdue, oldest_overdue_days,
--    scheduled) se počítají jen z dokladů, k nimž zdroj stav dodal; když ho
--    nenese ŽÁDNÝ vydaný doklad protistrany, dlaždice je NEMĚŘENO (null, „—"),
--    ne 0 „ok". Naměřeno 2026-09-28: 929 protistran / 5 104 faktur bez jediného
--    stavu úhrady (export ERP bez zůstatku) hlásilo „K úhradě 0 Kč" a síť vazeb
--    „bez dluhu". Kolik dokladů stav nenese a z kdy, přizná hlavička karty
--    (counterparty_periods). invoiced_12m je součet vystavených částek — stav
--    úhrady nepotřebuje.
-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, dohoda 2026-09-24 „opraví se v PR karty"):
--    `freshness_at` = nejnovější příchod verze dokladu (`created_at`) ve STEJNÉM univerzu
--    dokladů protistrany, ze kterého je hodnota — ne čas zavolání. Karta tak neřekne
--    „dnes", když poslední doklad té firmy dorazil před týdny. Prázdné univerzum →
--    `trace_id` nese `:no_data` a `now()` je jen záloha coalesce.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_counterparty_metric(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  with id as (select icos, names, twins, label from public.counterparty_resolve(p_params)),
  cfg as (select public.receivable_from_param(p_params) as od, public.storno_values_param(p_params) as storno),
  fa as (
    select
      public.invoice_state(d.fields, cfg.od, cfg.storno) as stav,
      case when d.fields->'amount_unpaid'->>'value' ~ '^-?[0-9]+(\.[0-9]+)?$'
           then (d.fields->'amount_unpaid'->>'value')::numeric end as zbyva,
      case when d.fields->'total_amount'->>'value' ~ '^-?[0-9]+(\.[0-9]+)?$'
           then (d.fields->'total_amount'->>'value')::numeric end as celkem,
      case when d.fields->'due_date'->>'value' ~ '^\d{4}-\d{2}-\d{2}$'
           then (d.fields->'due_date'->>'value')::date end as splatnost,
      case when d.fields->'issue_date'->>'value' ~ '^\d{4}-\d{2}-\d{2}$'
           then (d.fields->'issue_date'->>'value')::date end as vystaveno,
      d.created_at as vznik
    from id, cfg, public.counterparty_docs(id.icos, id.names, 'invoice') d
    where d.fields->'document_subtype'->>'value' = 'issued'
  ),
  m as (
    select
      sum(zbyva) filter (where stav in ('open', 'overdue', 'correction'))              as otevreno,
      sum(zbyva) filter (where stav in ('overdue', 'correction'))                      as po_splatnosti,
      max(current_date - splatnost) filter (where stav = 'overdue')                    as nejstarsi,
      sum(zbyva) filter (where stav = 'scheduled')                                     as predepsano,
      sum(celkem) filter (where stav <> 'storno'
                            and vystaveno between current_date - 365 and current_date) as za_rok,
      count(*) as dokladu,
      count(*) filter (where stav <> 'unknown') as se_stavem,
      max(vznik) as vznik
    from fa
  ),
  v as (
    select case p_params->>'metric'
             when 'receivable_open'     then round(coalesce(otevreno, 0))
             when 'receivable_overdue'  then round(coalesce(po_splatnosti, 0))
             when 'oldest_overdue_days' then coalesce(nejstarsi, 0)
             when 'scheduled'           then round(coalesce(predepsano, 0))
             when 'invoiced_12m'        then round(coalesce(za_rok, 0))
           end as hodnota,
           case when p_params->>'metric' = 'oldest_overdue_days' then 'app.units.days' else 'app.units.czk' end as jednotka,
           case when coalesce(nejstarsi, 0) > 365 and p_params->>'metric' in ('receivable_overdue','oldest_overdue_days') then 'loss'
                when coalesce(po_splatnosti, 0) > 0.005 and p_params->>'metric' in ('receivable_open','receivable_overdue','oldest_overdue_days') then 'warning'
                else 'ok' end as stav,
           dokladu, se_stavem, vznik
    from m
  )
  -- Klíče `data` DOSLOVNĚ (brána block-data-keys-fit-contract je čte ze zdroje):
  -- value null = NEMĚŘENO („—", ne nula) — protistrana bez vydaných faktur,
  -- nebo metrika úhrady nad doklady, z nichž ŽÁDNÝ stav úhrady nenese.
  select jsonb_build_object(
    'data', jsonb_build_object(
      'value', case when dokladu = 0 then null
                    when se_stavem = 0 and p_params->>'metric' <> 'invoiced_12m' then null
                    else hodnota end,
      'unit_key', jednotka,
      'state', stav),
    'provenance', jsonb_build_object(
      'source_slug', 'li-source-registry',
      'trace_id', 'counterparty-metric:' || coalesce(p_params->>'metric', '?')
                  || case when vznik is null then ':no_data' else '' end,
      'freshness_at', to_char(coalesce((vznik), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')))
  from v;
$$;

REVOKE ALL ON FUNCTION public.get_counterparty_metric(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_counterparty_metric(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/answer_verified_facts.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- answer_verified_facts — deterministický odpovídač nad OVĚŘENÝMI fakty.
--
-- SoT ZACHRÁNĚN 2026-07-29: funkce žila jen v generované baseline a v živé DB
-- (nikdy neměla zdrojový soubor), takže ji nešlo opravit pipeline cestou a
-- žádný test na ni nemířil. Odteď je zdrojem TENHLE soubor; baseline ji dostává
-- výhradně regenem, běžící instance přes heals.
--
-- Tři osy kognitivního testu (VĚDĚT, ne odhadnout): věcnost · doložený zdroj ·
-- ZDRŽENLIVOST. Mezera je správná odpověď; sebevědomé číslo na nesouvisející
-- otázku je propadák. Naměřeno 2026-07-29 na produkci:
--   „kolik je hodin?"      → přehled nájemců, coverage FULL   (catch-all ‚kolik')
--   „kdo platí nejmíň?"    → vrátil NEJVYŠŠÍ nájem            (šablona ignoruje otázku)
--   „jakou má BRIMS plochu?"→ unknown                          (regex ‚plocha' nechytí ‚plochu')
-- Proto: žádný holý catch-all, superlativ se čte z otázky, kmeny místo tvarů.
--
-- Jazyková vrstva je záměrně primitivní (regex) — je to deterministický
-- FALLBACK. Plnohodnotný intent+formulace patří lokálnímu modelu přes answer
-- chain (fakta VŽDY jen z RPC pod scopem, model jazyk — nikdy čísla z vah).
-- ============================================================================

-- ── 2026-07-30: SCOPE JE AUTORITATIVNÍ VSTUP, text otázky už jen doplňuje ────
-- Do 07-30 si tahle funkce scope HÁDALA z textu otázky (token labelu proti 1 194
-- firemním twinům) a jiný zdroj pravdy neměla. Když nad tím vznikl přepínač
-- pohledu, byly zdroje dva — a ten nezamýšlený (slova v otázce) přebíjel ten
-- zamýšlený (volba uživatele). To je šum z definice, ne vada formulace.
-- Odteď: `p_scope` (vektor souřadnic, ověřený jediným vlastníkem pravidla
-- `scope_effective`) rozhoduje. Dohad z textu smí VYPLNIT chybějící dimenzi, a to
-- výhradně označený jako `guessed_from_text` s jistotou < 1 — nikdy volbu přebít.
-- Vrácená obálka nese `scope`: vektor, pod kterým odpověď VZNIKLA, aby se dala
-- po měsíci přečíst a přiřadit odpovědnost (zapisuje ho get_answer_block do ai_runs).
-- ── 2026-08-04: NÁJEM SE DERIVUJE Z DOKLADŮ, NEČTE SE ZE SEEDU ──────────────
-- Do 08-04 četly obě nájemní větve 33 `lease` událostí nasypaných seedem
-- z jednorázového exportu. Naměřeno proti fakturám v korpusu: pole se jmenovalo
-- `annual_rent_czk`, ale hodnota byla MĚSÍČNÍ (25/33 sedělo 1:1 na jednu měsíční
-- fakturu), 21 z nich už neplatilo po valorizaci, a faktury znaly 101 plátců
-- místo 33. Odpovídač tedy hlásil „roční nájem 851 408 Kč" tam, kde je pravda
-- ~40,5 M ročně — a k tomu `coverage: full`, tedy plnou jistotu nad snímkem.
--
-- Nově obě větve čtou `get_rent_current` (derivace z fakturovaných položek).
-- Vzory nájmu jsou DATA a přicházejí v `p_config` z instančního bloku — platforma
-- české texty faktur znát nesmí. Bez konfigurace se NIC nederivuje a odpověď to
-- PŘIZNÁ (coverage none), místo aby mlčela nebo si domyslela.
-- ⛔ STARÉ PŘETÍŽENÍ SE MUSÍ ZAHODIT VÝSLOVNĚ.
-- `create or replace` mění funkci TÉŽE signatury; přidáním čtvrtého parametru
-- vznikla NOVÁ funkce a tříparametrová verze zůstala žít vedle ní. Naměřeno na
-- produkci 2026-08-04: `pg_proc` vracel answer_verified_facts dvakrát (3 a 4
-- argumenty). Volající s třemi argumenty by tiše dostal STAROU logiku, tedy
-- nájem ze seedu — přesně tu vadu, kterou tahle změna odstraňuje. Dvě pravdy
-- pod jedním jménem jsou horší než jedna špatná: nepozná se, která odpověděla.
drop function if exists public.answer_verified_facts(text, text, jsonb);

create or replace function public.answer_verified_facts(
  p_question text,
  p_style    text default 'strucny',
  p_scope    jsonb default '[]'::jsonb,
  p_config   jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public, pg_temp
as $fn$
declare
  q text := norm_text(p_question);
  v_intent text; v_coverage text; v_source text;
  v_firm record; v_target_firm uuid; v_firm_label text;
  v_obj record; v_target_object uuid; v_obj_label text;
  v_data jsonb := '{}'::jsonb; v_rows jsonb := '[]'::jsonb; v_answer text;
  v_rent jsonb;
  -- záměr `debt`: parametry čteček karty protistrany (twin + receivable_from z instance)
  v_cp jsonb;
  v_style text := coalesce(p_style,'strucny');
  -- Ověřený vektor (jen souřadnice, za které se substrát zaručil) + vektor,
  -- pod kterým odpověď skutečně vznikla (ověřené + doplněné dohady).
  v_scope      jsonb := public.scope_effective(p_scope);
  v_scope_used jsonb := coalesce(v_scope->'effective', '[]'::jsonb);
  -- Superlativ Z OTÁZKY: „nejmíň" musí dostat nejnižší konec řady, ne šablonu
  -- s natvrdo nejvyšším. NULL = bez superlativu (souhrn).
  v_super text := case
    when q ~ '(nejmen|nejmin|nejniz)' then 'min'
    when q ~ '(nejvic|nejvys|nejvet)' then 'max'
    else null end;
begin
  -- ── FIRMA: nejdřív VOLBA (ověřená souřadnice), teprve pak dohad z textu ────
  select (c->>'value')::uuid into v_target_firm
  from jsonb_array_elements(v_scope_used) c
  where c->>'dim' = 'company' and c->>'resolver' = 'twin'
  limit 1;
  if v_target_firm is not null then
    -- Label bere z twinu, ne z otázky: jméno v odpovědi musí patřit uzlu, na
    -- kterém čtenář stojí, i když v otázce padlo jméno jiné firmy.
    select e.label into v_firm_label from twin_entities e where e.id = v_target_firm;
  else
    -- Dohad: firma, jejíž CELÝ název otázka nese (po slovech), jinak ta, které
    -- v otázce chybí nejméně význačných slov názvu; teprve potom nejdelší shodné
    -- slovo a delší název.
    --
    -- ⛔ NAMĚŘENO 2026-09-28: „Co víme o firmě SFR Motor s.r.o.?" vybralo „SFR Motor
    -- SERVIS s.r.o." (jiná firma, IČO 08263370, jen přijaté faktury) místo „SFR Motor
    -- s.r.o." (IČO 08263523, 60 vydaných faktur). Obě sdílí nejdelší shodné slovo
    -- „motor" a při shodě vyhrával DELŠÍ název — i když jeho slovo „servis" v otázce
    -- vůbec není. Odpověď pak tvrdila „vydané faktury nemáme".
    select e.id, e.label into v_firm
    from twin_entities e
    cross join lateral (
      select count(*) filter (where q like '%'||t.tok||'%')      as shodnych,
             count(*) filter (where q not like '%'||t.tok||'%')  as chybejicich,
             max(length(t.tok)) filter (where q like '%'||t.tok||'%') as nejdelsi
        from (select regexp_replace(norm_text(w),'[^a-z0-9]','','g') tok
                from regexp_split_to_table(e.label,'\s+') w) t
       where length(t.tok)>=4
         and t.tok not in ('spol','group')
    ) s
    where e.entity_type='company'
      and s.shodnych > 0
    order by (' '||regexp_replace(q,'[^a-z0-9]+',' ','g')||' ')
               like ('% '||btrim(regexp_replace(norm_text(e.label),'[^a-z0-9]+',' ','g'))||' %') desc,
             s.chybejicich asc,
             s.nejdelsi desc,
             char_length(e.label) desc
    limit 1;
    v_target_firm := v_firm.id; v_firm_label := v_firm.label;
    if v_target_firm is not null then
      -- Doplněná dimenze se do vektoru zapisuje PŘIZNANĚ: origin guessed_from_text
      -- a jistota < 1. Bez toho by se za měsíc nedalo poznat, že souřadnici
      -- nevybral člověk, ale regex nad formulací dotazu.
      v_scope_used := v_scope_used || jsonb_build_array(jsonb_build_object(
        'dim','company','value',v_target_firm::text,'origin','guessed_from_text',
        'confidence',0.5,'detail','label token found in question text','resolver','twin'));
    end if;
  end if;

  -- Jméno firmy v odpovědi = AKTUÁLNÍ jméno z dokladů (counterparty_resolve, táž
  -- pravda jako karta protistrany), ne název dvojčete: ten bývá adresa nebo IČO
  -- (naměřeno 2026-09-28: 53 firem s IČO pojmenovaných adresou, 28 samotným IČO).
  -- Uzel se nemění — jméno patří téže firmě (tomuž IČO), jen jeho aktuální podobě.
  if v_target_firm is not null then
    select coalesce(nullif(id.label, ''), v_firm_label) into v_firm_label
      from public.counterparty_resolve(jsonb_build_object('twin_id', v_target_firm::text)) id;
  end if;

  -- ── OBJEKT/areál: týž řád — volba, pak dohad ───────────────────────────────
  select (c->>'value')::uuid into v_target_object
  from jsonb_array_elements(v_scope_used) c
  where c->>'dim' = 'object' and c->>'resolver' = 'twin'
  limit 1;
  if v_target_object is not null then
    select o.label into v_obj_label from twin_entities o where o.id = v_target_object;
  else
    select o.id, o.label into v_obj
    from twin_entities o
    cross join lateral (select regexp_replace(norm_text(w),'[^a-z0-9]','','g') tok
                        from regexp_split_to_table(o.label,'\s+') w) t
    where o.entity_type='object' and length(t.tok)>=4 and q like '%'||t.tok||'%'
    order by length(t.tok) desc limit 1;
    v_target_object := v_obj.id; v_obj_label := v_obj.label;
    if v_target_object is not null then
      v_scope_used := v_scope_used || jsonb_build_array(jsonb_build_object(
        'dim','object','value',v_target_object::text,'origin','guessed_from_text',
        'confidence',0.5,'detail','label token found in question text','resolver','twin'));
    end if;
  end if;

  -- Klasifikace záměru. KMENY, ne tvary (ploch- chytí plochu/ploše/plochy).
  -- ŽÁDNÝ holý catch-all: otázka bez nájemního kontextu spadne do 'unknown'
  -- a dostane poctivé „nezařadil jsem" s coverage none — ne vymyšlený přehled.
  v_intent := case
    -- DLUH první: „Kolik dluží…" předvyplňuje sama karta protistrany
    -- (app.cp.ask.prefill) a do 2026-09-26 padala na `kolik` → tenant_rent, tedy
    -- na nájem bez DPH za nejnovější (i budoucí) období. Kmeny, ne tvary.
    when q ~ '(dluz|dluh|pohledav|splatnost|nedoplat|neuhraz|nezaplac)' then 'debt'
    -- VZTAH V ČASE (2026-09-28): „je náš zákazník?", „kdy naposledy?", „jaké
    -- faktury má?" — dřív padalo na `contract_terms` (kmen faktur) nebo na
    -- „nezařadil". Jen s firmou: bez ní by „dodavatel elektřiny" ukradl energii.
    when v_target_firm is not null
     and q ~ '(zakaznik|odberatel|klient|nas dodavatel|spoluprac|obchodujeme|obchodovali|naposledy|posledni (faktur|obchod|doklad)|(jake|ktere|kolik) faktur|obchodni vztah)'
      then 'relationship'
    when q ~ '(vypovedn|lhut|prava|povinnost|dodatek|dodatk|faktur|predavac|protokol)' then 'contract_terms'
    when q ~ '(sidlo|adresa|ico)' then 'tenant_seat'
    when q ~ '(ploch|vymer|metr|m2|rozloh)' then 'tenant_area'
    -- kniha jízd / telematika — KONTROLNÍ SKUPINA kognitivního testu (A blok)
    when q ~ '(najezdil|najezd|kilometr|kniha jizd|jizd|motohodin|odvezl|prevezl|tonaz|tun[ay ]|vytizen)' then 'machine_ops'
    when q ~ '(spotreb|energi|kwh|elektr|plyn|voda|mericu?|merak)' then
         case when q ~ '(3 mesic|mesicn|obdobi|kvartal|ctvrtlet)' then 'energy_timeseries'
              else 'energy_consumption' end
    when q ~ '(zaloh|zalohy|predpis)' then 'tenant_deposits'
    when v_target_object is not null and v_target_firm is null and q ~ '(prehled|areal|objekt|budov|najem|najemn|plati|najemc)' then 'object_summary'
    when q ~ '(prehled|seznam|kdo (vsechno )?plati|najemnic|najemc[iu]|kolik najemc)' and v_target_firm is null then 'tenant_overview'
    when v_target_firm is not null and q ~ '(najem|najemn|plati|kolik)' then 'tenant_rent'
    when q ~ '(najem|najemn)' then 'tenant_overview'
    when v_super is not null and q ~ 'plati' then 'tenant_overview'
    else 'unknown'
  end;

  if v_intent='tenant_overview' then
    v_rent   := public.get_rent_current(coalesce(p_config->'rent','{}'::jsonb));
    v_source := 'fakturované položky nájmu (odvozeno k období '
              || coalesce(v_rent->'data'->'summary'->>'period','?') || ')';
    if not coalesce((v_rent->'data'->'summary'->>'configured')::boolean, false) then
      -- Prázdno z prázdné konfigurace je nerozeznatelné od „podnik nemá nájemce".
      v_coverage := 'none';
      v_data := jsonb_build_object('poznamka',
        'instance nemá nastavené vzory nájemních položek — nájem se nederivuje');
    else
      v_data := v_rent->'data'->'summary';
      select jsonb_agg(t order by (t->>'monthly_amount')::numeric desc) into v_rows
      from jsonb_array_elements(v_rent->'data'->'tenants') t
      where (t->>'active')::boolean;
      -- `partial`, ne `full`: derivace vidí jen nájemce, kterým se FAKTURUJE.
      -- Kdo má smlouvu a nedostal fakturu, tu není — a tvrdit nad tím plné
      -- pokrytí je přesně ta lež, kvůli které tahle větev vznikla.
      v_coverage := case when (v_data->>'active_tenants')::int > 0 then 'partial' else 'none' end;
    end if;

  elsif v_intent='debt' then
    -- ⭐ TYTÉŽ RPC JAKO KARTA PROTISTRANY (jedna pravda): dluh, k úhradě,
    -- nejstarší dluh a předepsáno z get_counterparty_metric (stav dokladu
    -- z invoice_state), smlouvy z counterparty_contracts. Odpovídač nic
    -- nepočítá sám — kdyby počítal, karta a odpověď by se rozešly.
    -- ⭐ DLUH = FAKTURA PO SPLATNOSTI (majitel 2026-09-26). Vystavená faktura
    -- ve splatnosti je „k úhradě", ne dluh; vystavená dopředu „předepsáno".
    -- Údaje ze zdroje (Money) se nemění — změní-li je účetní ve zdroji, projeví
    -- se tu samy (storno, úhrada).
    -- `receivable_from` přichází v p_config->'receivables' z instančního bloku.
    v_source := 'vydané faktury a smlouvy protistrany (tytéž čtečky jako karta protistrany)';
    if v_target_firm is null then
      v_coverage := 'none';
      v_data := jsonb_build_object('poznamka','není zřejmé, o které firmě je řeč — vyberte ji v pohledu nebo ji jmenujte');
    else
      v_cp := coalesce(p_config->'receivables','{}'::jsonb) || jsonb_build_object('twin_id', v_target_firm::text);
      v_data := jsonb_build_object(
        'firma',         v_firm_label,
        'dluh',          public.get_counterparty_metric(v_cp || '{"metric":"receivable_overdue"}'::jsonb)->'data'->'value',
        'k_uhrade',      public.get_counterparty_metric(v_cp || '{"metric":"receivable_open"}'::jsonb)->'data'->'value',
        'nejstarsi_dni', public.get_counterparty_metric(v_cp || '{"metric":"oldest_overdue_days"}'::jsonb)->'data'->'value',
        'predepsano',    public.get_counterparty_metric(v_cp || '{"metric":"scheduled"}'::jsonb)->'data'->'value');
      select v_data || jsonb_build_object('smluv', count(*), 'smluv_navrzeno', count(*) filter (where c.certainty = 'proposed'),
                                          -- „na jakých smlouvách": prvních pár názvů dokumentů, ne jen počet
                                          'smlouvy', coalesce((array_agg(c.filename order by c.filename)
                                                               filter (where coalesce(c.filename, '') <> ''))[1:3], '{}'::text[]))
        into v_data
        from public.counterparty_resolve(v_cp) id, public.counterparty_contracts(id.icos, id.names, id.twins) c;
      -- ⭐ SOUČASNOST A NEZNÁMÉ (2026-09-28): z téže pravdy jako hlavička karty
      -- (counterparty_periods) — poslední vydaná faktura, kolik vydaných faktur
      -- stav úhrady ve zdroji NENESE a z kdy; vyfakturováno za 12 m z dlaždice.
      -- NEMĚŘENO (null) u dluhu teď znamená dvojí: žádná vydaná faktura, nebo
      -- faktury bez stavu úhrady — odpověď je musí rozlišit.
      select v_data || jsonb_build_object(
               'vydanych',           coalesce(p.dokladu, 0) + coalesce(p.predepsano, 0),
               'posledni_vydana',    to_char(p.posledni, 'YYYY-MM-DD'),
               'bez_stavu',          coalesce(p.bez_stavu, 0),
               'bez_stavu_prvni',    to_char(p.bez_stavu_prvni, 'YYYY-MM-DD'),
               'bez_stavu_posledni', to_char(p.bez_stavu_posledni, 'YYYY-MM-DD'),
               'vydano_12m',         public.get_counterparty_metric(v_cp || '{"metric":"invoiced_12m"}'::jsonb)->'data'->'value')
        into v_data
        from public.counterparty_resolve(v_cp) id
        left join lateral public.counterparty_periods(id.icos, id.names, public.storno_values_param(v_cp)) p
          on p.vztah = 'customer';
      -- „od kdy": den splatnosti nejstaršího dluhu (dnes − dní po splatnosti)
      if coalesce((v_data->>'nejstarsi_dni')::numeric, 0) > 0 then
        v_data := v_data || jsonb_build_object('dluh_od',
          to_char(current_date - (v_data->>'nejstarsi_dni')::int, 'FMDD. FMMM. YYYY'));
      end if;
      -- `partial`: evidence vidí jen doklady ze zdrojů, které do ní tečou (Money),
      -- a strany smluv jsou zatím jen navržené. NEMĚŘENO (null) = dluh neumím
      -- doložit (žádná vydaná faktura, nebo žádná se stavem úhrady).
      v_coverage := case when jsonb_typeof(v_data->'k_uhrade') = 'number' then 'partial' else 'none' end;
    end if;

  elsif v_intent='relationship' then
    -- ⭐ VZTAH V ČASE (majitel 2026-09-28): uživatel se ptá na AKTUÁLNÍ stav,
    -- historie doplňuje a nesmí převážit. Odpověď proto začíná SOUČASNOSTÍ
    -- (poslední doklad, vyfakturováno za 12 m) a teprve pak období rolí.
    -- Data z téže čtečky jako hlavička karty (counterparty_periods); práh
    -- „aktivní / spící" platforma nezná a nehádá — říká data, ne nálepku.
    -- Dodáky ani smlouvy role neurčují: dodáky ze živého zdroje zatím nenesou
    -- IČO (naměřeno 2026-09-28) a přiřadit je jménem by bylo hádání.
    v_source := 'vydané a přijaté faktury protistrany (tytéž čtečky jako karta protistrany)';
    v_cp := coalesce(p_config->'receivables','{}'::jsonb) || jsonb_build_object('twin_id', v_target_firm::text);
    select jsonb_build_object(
             'firma',        v_firm_label,
             'odberatel_od', to_char(max(p.prvni)    filter (where p.vztah = 'customer'), 'YYYY-MM-DD'),
             'odberatel_do', to_char(max(p.posledni) filter (where p.vztah = 'customer'), 'YYYY-MM-DD'),
             'vydanych',     coalesce(max(p.dokladu) filter (where p.vztah = 'customer'), 0),
             'predepsanych', coalesce(max(p.predepsano) filter (where p.vztah = 'customer'), 0),
             'dodavatel_od', to_char(max(p.prvni)    filter (where p.vztah = 'supplier'), 'YYYY-MM-DD'),
             'dodavatel_do', to_char(max(p.posledni) filter (where p.vztah = 'supplier'), 'YYYY-MM-DD'),
             'prijatych',    coalesce(max(p.dokladu) filter (where p.vztah = 'supplier'), 0),
             'posledni',     to_char(max(p.posledni), 'YYYY-MM-DD'))
      into v_data
      from public.counterparty_resolve(v_cp) id
      left join lateral public.counterparty_periods(id.icos, id.names, public.storno_values_param(v_cp)) p on true;
    select v_data || jsonb_build_object('smluv', count(*),
             'vydano_12m', public.get_counterparty_metric(v_cp || '{"metric":"invoiced_12m"}'::jsonb)->'data'->'value')
      into v_data
      from public.counterparty_resolve(v_cp) id, public.counterparty_contracts(id.icos, id.names, id.twins) c;
    v_coverage := case when (v_data->>'vydanych')::int + (v_data->>'prijatych')::int > 0 then 'partial' else 'none' end;

  elsif v_intent='tenant_rent' then
    v_rent   := public.get_rent_current(coalesce(p_config->'rent','{}'::jsonb));
    v_source := 'fakturované položky nájmu (odvozeno k období '
              || coalesce(v_rent->'data'->'summary'->>'period','?') || ')';
    if not coalesce((v_rent->'data'->'summary'->>'configured')::boolean, false) then
      -- Bez vzorů nájmu se nederivuje nic — „nenašel jsem" by bylo tvrzení o datech,
      -- která se vůbec nečetla. Stejně jako tenant_overview to odpověď PŘIZNÁ.
      v_coverage := 'none';
      v_data := jsonb_build_object('firma', v_firm_label, 'poznamka',
        'instance nemá nastavené vzory nájemních položek — nájem se nederivuje');
    else
      -- ⭐ Plátce nájmu se páruje JMÉNY FIRMY Z DOKLADŮ (jména v čase pro její IČO,
      -- counterparty_resolve — táž pravda jako karta a dluh), ne názvem dvojčete:
      -- ten bývá adresa nebo IČO, a pak se nájemce „nenašel" (naměřeno 2026-09-28).
      select t into v_data
        from jsonb_array_elements(v_rent->'data'->'tenants') t
       where public.norm_text(btrim(t->>'tenant')) in (
               select public.norm_text(btrim(n))
                 from public.counterparty_resolve(coalesce(p_config->'receivables','{}'::jsonb)
                                                  || jsonb_build_object('twin_id', v_target_firm::text)) id,
                      unnest(id.names || coalesce(v_firm_label, '')) n
                where btrim(n) <> '')
       order by (t->>'active')::boolean desc, t->>'period' desc
       limit 1;
      v_coverage := case when v_data is null then 'none' else 'partial' end;
      if v_data is null then
        v_data := jsonb_build_object('firma', v_firm_label,
                                     'obdobi', v_rent->'data'->'summary'->>'period');
      end if;
    end if;

  elsif v_intent='energy_consumption' then
    v_source := 'twin energy (sez-fakturace, elektřina)';
    if v_target_firm is not null then
      select jsonb_build_object('firma',v_firm_label,
        'spotreba_kwh', sum((ev.attrs->>'consumption_kwh')::numeric),
        'naklad_czk', sum((ev.attrs->>'cost_czk')::numeric),
        'udalosti', count(*))
      into v_data from twin_events ev where ev.event_type='energy' and ev.twin_id=v_target_firm;
      v_coverage := case when (v_data->>'udalosti')::int>0 then 'partial' else 'none' end;
    elsif v_target_object is not null then
      select jsonb_build_object('objekt',v_obj_label,
        'spotreba_kwh', coalesce(sum((ev.attrs->>'consumption_kwh')::numeric),0),
        'naklad_czk', coalesce(sum((ev.attrs->>'cost_czk')::numeric),0),
        'firem_s_energii', count(distinct ev.twin_id))
      into v_data from twin_events ev
      where ev.event_type='energy' and ev.twin_id in (
        select twin_id from twin_events where event_type='lease' and place_twin_id=v_target_object);
      v_data := jsonb_set(v_data,'{firma}', to_jsonb(v_obj_label));
      v_coverage := case when (v_data->>'firem_s_energii')::int>0 then 'partial' else 'none' end;
    else
      select jsonb_build_object('firem_s_energii', count(*),
        'spotreba_kwh_celkem', sum(s.kwh), 'naklad_czk_celkem', sum(s.czk)),
        jsonb_agg(jsonb_build_object('firma',s.firma,'kwh',s.kwh,'czk',s.czk) order by s.czk desc)
      into v_data, v_rows from (
          select e.label firma, sum((ev.attrs->>'consumption_kwh')::numeric) kwh,
                 sum((ev.attrs->>'cost_czk')::numeric) czk
          from twin_events ev join twin_entities e on e.id=ev.twin_id
          where ev.event_type='energy' group by e.label) s;
      v_coverage := 'partial';  -- jen elektřina; plyn/voda zatím ne
    end if;

  elsif v_intent='object_summary' then
    -- ⚠️ NÁJEM ZA OBJEKT SE DNES ODVODIT NEDÁ — a je poctivější to říct.
    -- Derivace z faktur zná NÁJEMCE a ČÁSTKU, ale ne OBJEKT: doklad nenese,
    -- které budovy se nájem týká. Ta vazba žila jen v seedu, který byl chybný
    -- (měsíční pod jménem `annual`, snímek 33 z 101). Dopočítat ji z místa
    -- doručení by bylo hádání vydávané za měření, takže se nájem za objekt
    -- NEUVÁDÍ; energie ano, ta k místu vázaná je.
    v_source := 'twin energy (elektřina); nájem per objekt zatím neodvoditelný';
    v_data := jsonb_build_object('objekt', v_obj_label);
    v_data := v_data || (
      select jsonb_build_object('energie_kwh',coalesce(sum((e.attrs->>'consumption_kwh')::numeric),0),
             'energie_czk',coalesce(sum((e.attrs->>'cost_czk')::numeric),0))
      from twin_events e where e.event_type='energy' and e.twin_id in (
        select twin_id from twin_events where event_type='lease' and place_twin_id=v_target_object));
    v_coverage := 'full';

  elsif v_intent='machine_ops' then
    -- Kniha jízd: lane EXISTUJE (telematika), ale živě zatím neteče — sekce
    -- Provozy je deklarovaná jako čekající. Poctivost > dojem: přiznat mezeru.
    -- A2 test na konfabulaci: goods_value je v Kč, TONÁŽ SE NEMĚŘÍ — kdo
    -- vyrobí tuny dopočtem, propadl. Odmítnutí je tu správná odpověď.
    v_source := 'kniha jízd (telematika — lane zatím nenapojena)';
    v_coverage := 'none';
    v_data := jsonb_build_object('poznamka', case
      when q ~ '(tonaz|tun[ay ])' then 'hodnota nákladu je v Kč; tonáž se neměří — dopočet odmítám'
      else 'kniha jízd zatím do stacku neteče; sekce Provozy čeká na napojení telematiky' end);

  elsif v_intent='contract_terms' then
    v_source := 'obsah smlouvy (zatím strojově nevytěžený)';
    v_coverage := 'none';
    v_data := jsonb_build_object('firma',v_firm_label,
      'poznamka','údaj je v OBSAHU smlouvy; dnes není tvrdě ověřený (chybí NLP extrakce). Dokument je dostupný k nahlédnutí oprávněnému.');

  elsif v_intent='tenant_seat' then
    -- IČO a adresa z HLAVIČKY KARTY protistrany (jedna pravda): IČO z vazeb
    -- twinu, adresa z POSLEDNÍHO dokladu — současnost, ne nejčastější hodnota.
    -- Dřív tu stálo „IČO zatím není v twinu" i u firmy, jejíž twin IČO nese.
    v_source := 'hlavička karty protistrany (IČO z vazeb twinu, adresa z posledního dokladu)';
    v_data := jsonb_build_object('firma', v_firm_label);
    if v_target_firm is not null then
      select v_data || coalesce(jsonb_object_agg(f->>'key', f->>'value'), '{}'::jsonb)
        into v_data
        from jsonb_array_elements(public.get_counterparty_card(
               jsonb_build_object('twin_id', v_target_firm::text))->'data'->'fields') f
       where f->>'key' in ('ico', 'dic', 'adresa');
    end if;
    v_coverage := case when v_data ? 'ico' or v_data ? 'adresa' then 'partial' else 'none' end;
    if v_coverage = 'none' then
      v_data := v_data || jsonb_build_object('poznamka','sídlo/IČO nenese twin ani doklad; navázat z ARES nebo obsahu smlouvy.');
    end if;

  elsif v_intent='tenant_area' then
    v_source := 'plocha z OCR smlouvy (nespolehlivá)';
    v_coverage := 'none';
    v_data := jsonb_build_object('firma',v_firm_label,'poznamka','OCR uvádí plochu celé budovy (5704 m² pro více firem) — netvrdím jako pravdu; potřebuje ověřenou extrakci.');

  elsif v_intent='energy_timeseries' then
    v_source := 'twin energy (jen souhrnné období)';
    v_coverage := 'none';
    v_data := jsonb_build_object('firma',v_firm_label,'poznamka','měsíční řada zatím není; máme souhrnnou fakturační periodu, ne 3měsíční rozpad.');

  elsif v_intent='tenant_deposits' then
    v_source := 'zálohy (zatím nevytěženo z faktur/předpisů)';
    v_coverage := 'none';
    v_data := jsonb_build_object('firma',v_firm_label,'poznamka','zálohy nejsou vytěžené z faktur/předpisů; potřebuje ingest.');

  else
    v_source := 'žádný'; v_coverage := 'none';
    v_data := jsonb_build_object('poznamka','dotaz jsem nezařadil k žádné ověřené oblasti.');
  end if;

  v_answer := case v_intent
    -- ⚠️ MĚSÍČNÍ a K OBDOBÍ. Roční se uvádí jako DOPOČET (×12) a je označené —
    -- dřív tu stálo „roční" nad měsíční hodnotou a lhalo to o řád.
    when 'tenant_overview' then
      case when v_coverage='none' then
        coalesce(v_data->>'poznamka','Nájem se nepodařilo odvodit.')
      else
        (v_data->>'active_tenants')||' aktivních nájemců, měsíčně celkem '||
        fmt_num_cs((v_data->>'monthly_amount')::numeric)||' Kč (období '||
        coalesce(v_data->>'period','?')||'; ročním tempem '||
        fmt_num_cs((v_data->>'monthly_amount')::numeric * 12)||' Kč). '||
        case when v_super='min' then
          'Nejnižší: '||(v_rows->-1->>'tenant')||' ('||fmt_num_cs((v_rows->-1->>'monthly_amount')::numeric)||' Kč/měs).'
        else
          'Nejvyšší: '||(v_rows->0->>'tenant')||' ('||fmt_num_cs((v_rows->0->>'monthly_amount')::numeric)||' Kč/měs).'
        end ||
        -- Rozdíl mezi „známe" a „aktivní" je odpověď, ne šum: říká, kolik
        -- nájemců v datech je, ale zrovna se jim nefakturuje.
        ' Historicky známe '||(v_data->>'known_tenants')||' plátců nájmu.'
      end
    when 'debt' then
      -- Dluh = po splatnosti (majitel 2026-09-26); k úhradě a předepsáno jsou
      -- jiná čísla a odpověď je tak i pojmenuje.
      case when v_target_firm is null then 'Nevím, o které firmě je řeč — vyberte ji v pohledu nebo ji jmenujte.'
      when coalesce((v_data->>'vydanych')::int, 0) = 0 then coalesce(v_firm_label,'Tahle firma')||': vydané faktury v evidenci nemáme, dluh tedy neumím doložit.'
      -- faktury JSOU, ale žádná nenese stav úhrady → neznámo, ne „0 Kč"
      when v_coverage='none' then v_firm_label||': stav úhrady neznáme — '||
           (v_data->>'bez_stavu')||' vydaných faktur ('||coalesce(to_char((v_data->>'bez_stavu_prvni')::date, 'FMDD. FMMM. YYYY'), '?')||' → '||
           coalesce(to_char((v_data->>'bez_stavu_posledni')::date, 'FMDD. FMMM. YYYY'), '?')||') nenese ve zdroji zůstatek, dluh tedy neumím doložit. '||
           'Poslední vydaná faktura '||coalesce(to_char((v_data->>'posledni_vydana')::date, 'FMDD. FMMM. YYYY'), '—')||
           '; za posledních 12 měsíců vyfakturováno '||fmt_num_cs(coalesce((v_data->>'vydano_12m')::numeric, 0))||' Kč. '||
           'Smlouvy: '||(v_data->>'smluv')||'.'
      else v_firm_label||': dluh po splatnosti '||fmt_num_cs((v_data->>'dluh')::numeric)||' Kč'||
           case when (v_data->>'nejstarsi_dni')::numeric > 0
                then ' (nejstarší '||(v_data->>'nejstarsi_dni')||' dní po splatnosti, splatný od '||(v_data->>'dluh_od')||')' else '' end||
           '; k úhradě celkem '||fmt_num_cs((v_data->>'k_uhrade')::numeric)||' Kč včetně faktur ve splatnosti'||
           case when (v_data->>'predepsano')::numeric > 0
                then '; předepsáno dopředu (ještě nevystaveno) '||fmt_num_cs((v_data->>'predepsano')::numeric)||' Kč' else '' end||
           '. Smlouvy: '||(v_data->>'smluv')||
           case when (v_data->>'smluv_navrzeno')::int > 0
                then ' (z toho '||(v_data->>'smluv_navrzeno')||' jen navržené — strany nepotvrzené)' else '' end||
           case when jsonb_array_length(coalesce(v_data->'smlouvy','[]'::jsonb)) > 0
                then ' — '||(select string_agg(x, ', ') from jsonb_array_elements_text(v_data->'smlouvy') x)||
                     case when (v_data->>'smluv')::int > 3 then ' a další' else '' end
                else '' end||'.'||
           -- přiznat doklady bez stavu úhrady: v číslech výše NEJSOU
           case when coalesce((v_data->>'bez_stavu')::int, 0) > 0
                then ' U '||(v_data->>'bez_stavu')||' vydaných faktur ('||coalesce(to_char((v_data->>'bez_stavu_prvni')::date, 'FMDD. FMMM. YYYY'), '?')||' → '||
                     coalesce(to_char((v_data->>'bez_stavu_posledni')::date, 'FMDD. FMMM. YYYY'), '?')||') zdroj stav úhrady nedodal — v číslech nejsou.' else '' end||
           ' Poslední vydaná faktura '||coalesce(to_char((v_data->>'posledni_vydana')::date, 'FMDD. FMMM. YYYY'), '—')||'.'
      end
    when 'relationship' then
      -- SOUČASNOST PRVNÍ, historie za ní
      case when v_coverage='none' then coalesce(v_firm_label,'Tahle firma')||
           ': v evidenci nemáme žádnou fakturu — obchodní vztah z dokladů neumím doložit. Smlouvy: '||(v_data->>'smluv')||'.'
      else v_firm_label||': poslední doklad '||coalesce(to_char((v_data->>'posledni')::date, 'FMDD. FMMM. YYYY'), '?')||
           '; za posledních 12 měsíců vyfakturováno '||fmt_num_cs(coalesce((v_data->>'vydano_12m')::numeric, 0))||' Kč.'||
           case when (v_data->>'vydanych')::int > 0
                then ' Odběratel (naše vydané faktury): '||coalesce(to_char((v_data->>'odberatel_od')::date, 'FMDD. FMMM. YYYY'), '?')||' → '||
                     coalesce(to_char((v_data->>'odberatel_do')::date, 'FMDD. FMMM. YYYY'), '?')||', dokladů '||(v_data->>'vydanych')||'.' else '' end||
           case when (v_data->>'predepsanych')::int > 0
                then ' Předepsáno dopředu (ještě nevystaveno): '||(v_data->>'predepsanych')||'.' else '' end||
           case when (v_data->>'prijatych')::int > 0
                then ' Dodavatel (přijaté faktury): '||coalesce(to_char((v_data->>'dodavatel_od')::date, 'FMDD. FMMM. YYYY'), '?')||' → '||
                     coalesce(to_char((v_data->>'dodavatel_do')::date, 'FMDD. FMMM. YYYY'), '?')||', dokladů '||(v_data->>'prijatych')||'.' else '' end||
           ' Smlouvy: '||(v_data->>'smluv')||'.'
      end
    when 'tenant_rent' then
      -- „fakturuje se", ne „platí": částka je z VYSTAVENÝCH faktur (bez DPH),
      -- o úhradě nic neříká — to je záměr `debt`.
      -- Odpověď VŽDY jmenuje firmu, o které mluví: u volby v pohledu je jinak
      -- nerozeznatelné, jestli platila volba, nebo jméno z otázky.
      case when v_coverage='none' and v_data ? 'poznamka' then
             coalesce(v_firm_label, 'Tahle firma')||': nájem se nederivuje — instance nemá nastavené vzory nájemních položek.'
           when v_coverage='none' then
             coalesce(v_firm_label, 'Tuhle firmu')||': mezi plátci nájmu (fakturované nájemní položky, období '||
             coalesce(v_data->>'obdobi','?')||') jsem ji nenašel.'
      else (v_data->>'tenant')||': nájem se fakturuje '||fmt_num_cs((v_data->>'monthly_amount')::numeric)||
           ' Kč bez DPH měsíčně (naposledy fakturováno '||coalesce(v_data->>'period','?')||
           case when (v_data->>'active')::boolean then ')' else ', tedy NE v aktuálním období)' end||'.' end
    when 'energy_consumption' then
      case when v_target_firm is not null and v_coverage<>'none' then
        (v_data->>'firma')||': spotřeba '||fmt_num_cs((v_data->>'spotreba_kwh')::numeric,1)||' kWh, náklad '||
        fmt_num_cs((v_data->>'naklad_czk')::numeric)||' Kč (elektřina, zdroj sez-fakturace). Pozn.: plyn/voda zatím nevytěženo.'
      when v_target_firm is not null then 'Pro tuto firmu nemáme naměřenou spotřebu.'
      when v_target_object is not null then
        'Areál '||(v_data->>'objekt')||' (elektřina): '||fmt_num_cs((v_data->>'spotreba_kwh')::numeric,1)||' kWh, '||
        fmt_num_cs((v_data->>'naklad_czk')::numeric)||' Kč, '||(v_data->>'firem_s_energii')||' firem s měřením. Pozn.: jen elektřina.'
      when v_super is not null and jsonb_array_length(v_rows)>0 then
        -- superlativ i u energie: „kdo má největší spotřebu" → konkrétní firma
        case when v_super='min' then 'Nejnižší spotřebu (elektřina) má '||(v_rows->-1->>'firma')||': '||fmt_num_cs((v_rows->-1->>'kwh')::numeric,1)||' kWh ('||fmt_num_cs((v_rows->-1->>'czk')::numeric)||' Kč).'
             else 'Největší spotřebu (elektřina) má '||(v_rows->0->>'firma')||': '||fmt_num_cs((v_rows->0->>'kwh')::numeric,1)||' kWh ('||fmt_num_cs((v_rows->0->>'czk')::numeric)||' Kč).' end
        ||' Pozn.: jen elektřina; plyn/voda zatím ne.'
      else 'Elektřina areálu: '||(v_data->>'firem_s_energii')||' firem, '||
        fmt_num_cs((v_data->>'spotreba_kwh_celkem')::numeric,1)||' kWh, '||
        fmt_num_cs((v_data->>'naklad_czk_celkem')::numeric)||' Kč. Pozn.: jen elektřina; plyn/voda zatím ne.' end
    when 'object_summary' then
      'Objekt '||(v_data->>'objekt')||': elektřina '||
      fmt_num_cs((v_data->>'energie_kwh')::numeric,1)||' kWh ('||fmt_num_cs((v_data->>'energie_czk')::numeric)||' Kč). '||
      'Nájem za jednotlivý objekt zatím neumím doložit — doklad nenese, které budovy se týká.'
    when 'machine_ops' then
      case when q ~ '(tonaz|tun[ay ])' then
        'Tonáž neměříme — v datech je hodnota nákladu v Kč, ne hmotnost. Dopočet tun by byl odhad, a ten nedělám.'
      else
        'Kniha jízd zatím do stacku neteče (sekce Provozy čeká na napojení telematiky). Nemám co doložit — nehádám.' end
    when 'contract_terms' then
      'Toto ('||regexp_replace(p_question,'\s+',' ','g')||') je v OBSAHU smlouvy'||
      coalesce(' firmy '||v_firm_label,'')||', který zatím není strojově ověřený jako tvrdá pravda. '||
      'Nechci hádat — dokument je ale dostupný k nahlédnutí oprávněnému uživateli.'
    when 'tenant_seat' then
      case when v_coverage='none' then 'Sídlo/IČO'||coalesce(' firmy '||v_firm_label,'')||' zatím není v ověřených datech (navázat z ARES/smlouvy).'
      else v_firm_label||':'||coalesce(' IČO '||(v_data->>'ico'),'')||coalesce(', DIČ '||(v_data->>'dic'),'')||
           coalesce(case when v_data ? 'ico' then ';' else '' end||' adresa podle posledního dokladu: '||(v_data->>'adresa'),'')||'.' end
    when 'tenant_area' then 'Plochu'||coalesce(' firmy '||v_firm_label,'')||' dnes neumím tvrdě ověřit — OCR ze smlouvy uvádí plochu celé budovy, ne pronajaté jednotky. Potřebuje ověřenou extrakci.'
    when 'energy_timeseries' then '3měsíční rozpad spotřeby zatím nemáme — jen souhrnnou fakturační periodu.'
    when 'tenant_deposits' then 'Zálohy'||coalesce(' firmy '||v_firm_label,'')||' zatím nejsou vytěžené z faktur/předpisů.'
    else 'Dotaz jsem nezařadil k žádné ověřené oblasti dat.'
  end;

  if v_style='detailni' and jsonb_array_length(v_rows)>0 then
    v_answer := v_answer||' Detail: '||(select string_agg((r->>'firma')||' '||coalesce(r->>'rocni_najem_czk',r->>'czk')||'',', ') from jsonb_array_elements(v_rows) r limit 1);
  end if;
  if v_style='odborny' then v_answer := v_answer||' [zdroj: '||v_source||']'; end if;
  -- Kanonické pořadí i pro doplněné souřadnice: vektor, který se zapisuje do
  -- ai_runs a čte se po měsíci, musí být bajtově stejný pro stejné zadání.
  select coalesce(jsonb_agg(c order by c->>'dim'), '[]'::jsonb) into v_scope_used
  from jsonb_array_elements(v_scope_used) c;

  return jsonb_build_object('question',p_question,'intent',v_intent,'coverage',v_coverage,
    'answer',v_answer,'source',v_source,'data',v_data,'rows',v_rows,
    -- Pod jakým vektorem odpověď vznikla + co z požadovaného nepřežilo.
    -- Bez těchhle dvou polí je odpověď nepřiřaditelná: nešlo by poznat, jestli
    -- číslo platí pro firmu, kterou si čtenář vybral, nebo pro tu, kterou
    -- omylem zmínil v otázce.
    'scope',v_scope_used,'scope_dropped',coalesce(v_scope->'dropped','[]'::jsonb));
end
$fn$;

revoke all on function public.answer_verified_facts(text, text, jsonb, jsonb) from public, anon;
grant execute on function public.answer_verified_facts(text, text, jsonb, jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_counterparty_trend.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_counterparty_trend
-- Popis: blok `chart` (trend) — vyfakturováno protistraně po měsících (vydané
--        faktury podle data vystavení) a v `compare` z toho UHRAZENO
--        (celkem − zbývá). Jedna otázka („platí, co fakturujeme?"), dvě řady.
--        `months` v source_params (výchozí 24, strop 60). Měsíc bez faktury = 0,
--        aby osa času nelhala o mezerách.
-- ⚠ „Uhrazeno" je stav DNES u faktur vystavených v daném měsíci, ne platba
--   v tom měsíci — datum úhrady doklad nenese. Legenda to říká slovem.
-- ⭐ NEZNÁMÉ ≠ UHRAZENO (2026-09-28): „uhrazeno" = celkem − zbývá. Doklad, ke
--   kterému zdroj zůstatek NEDODAL, by s „zbývá = 0" vyšel jako plně uhrazený.
--   Nese-li kterákoli faktura v okně neznámý stav, druhá řada se NEVYDÁ (ani
--   její legenda): graf ukáže jen vyfakturováno, protože „platí, co
--   fakturujeme?" nad tím zodpovědět nejde. Kolik dokladů stav nenese, přizná
--   hlavička karty (counterparty_periods).
-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, dohoda 2026-09-24 „opraví se v PR karty"):
--    `freshness_at` = nejnovější příchod verze dokladu (`created_at`) ve STEJNÉM univerzu
--    dokladů protistrany, ze kterého je hodnota — ne čas zavolání. Karta tak neřekne
--    „dnes", když poslední doklad té firmy dorazil před týdny. Prázdné univerzum →
--    `trace_id` nese `:no_data` a `now()` je jen záloha coalesce.
--    Univerzum trendu = VŠECHNY vydané faktury protistrany, ne jen okno: „v okně nic"
--    je tvrzení platné k poslednímu dokladu, který evidence o té firmě má.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_counterparty_trend(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  with id as (select icos, names, twins, label from public.counterparty_resolve(p_params)),
  cfg as (select least(greatest(coalesce(nullif(p_params->>'months', '')::int, 24), 3), 60) as m,
                public.receivable_from_param(p_params) as od,
                public.storno_values_param(p_params) as storno),
  mesice as (
    select to_char(date_trunc('month', current_date) - make_interval(months => g), 'YYYY-MM') as mes, g
      from cfg, generate_series(0, (select m from cfg) - 1) g
  ),
  -- Storno nebylo vyfakturováno; doklad s datem vystavení v budoucnu ještě ne
  -- (okno končí dneškem — stejně jako invoiced_12m v get_counterparty_metric).
  fa as (
    select left(d.fields->'issue_date'->>'value', 7) as mes,
           (d.fields->'total_amount'->>'value')::numeric as celkem,
           case when d.fields->'amount_unpaid'->>'value' ~ '^-?[0-9]+(\.[0-9]+)?$'
                then (d.fields->'amount_unpaid'->>'value')::numeric end as zbyva
    from id, cfg, public.counterparty_docs(id.icos, id.names, 'invoice') d
    where d.fields->'document_subtype'->>'value' = 'issued'
      -- CASE drží pořadí: přetypování až po regexu (AND pořadí nezaručuje)
      and case when d.fields->'issue_date'->>'value' ~ '^\d{4}-\d{2}-\d{2}$'
               then (d.fields->'issue_date'->>'value')::date end <= current_date
      and d.fields->'total_amount'->>'value' ~ '^-?[0-9]+(\.[0-9]+)?$'
      and public.invoice_state(d.fields, cfg.od, cfg.storno) <> 'storno'
  ),
  s as (
    select m.mes, m.g, round(coalesce(sum(fa.celkem), 0)) as fakt,
           round(coalesce(sum(fa.celkem - greatest(coalesce(fa.zbyva, 0), 0)), 0)) as uhr,
           count(fa.celkem) as n,
           count(fa.celkem) filter (where fa.zbyva is null) as bez_stavu
      from mesice m left join fa on fa.mes = m.mes
     group by m.mes, m.g
  ),
  -- druhá řada jen nad známým stavem úhrady všech faktur v okně
  srovnani as (select coalesce(sum(bez_stavu), 0) = 0 as lze from s),
  cas as (
    select max(d.created_at) as vznik
      from id, public.counterparty_docs(id.icos, id.names, 'invoice') d
     where d.fields->'document_subtype'->>'value' = 'issued'
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'kind', 'trend',
      'unit_key', 'app.units.czk',
      'legend_keys', case when (select lze from srovnani)
                          then jsonb_build_array('app.cp.trend.invoiced', 'app.cp.trend.paid')
                          else jsonb_build_array('app.cp.trend.invoiced') end,
      -- bez jediné faktury v okně je graf prázdný (JAZYK-03), ne řada nul
      'points', case when (select sum(n) from s) = 0 then '[]'::jsonb else
        (select jsonb_agg(jsonb_build_object('label', mes, 'value', fakt) order by g desc) from s) end,
      'compare', case when (select sum(n) from s) = 0 or not (select lze from srovnani) then '[]'::jsonb else
        (select jsonb_agg(jsonb_build_object('label', mes, 'value', uhr) order by g desc) from s) end),
    'provenance', jsonb_build_object(
      'source_slug', 'li-source-registry',
      'trace_id', 'counterparty-trend' || case when (select vznik from cas) is null then ':no_data' else '' end,
      'freshness_at', to_char(coalesce((select vznik from cas), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')));
$$;

REVOKE ALL ON FUNCTION public.get_counterparty_trend(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_counterparty_trend(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_debtor_invoices.sql
-- -----------------------------------------------------------------------------

-- Data RPC: FAKTURY JEDNOHO ODBĚRATELE — druhé patro prokliku z pohledávek.
--
-- Bez tohohle byla tabulka dlužníků slepá ulička: řádek řekl „315 471 / 896 dní
-- / 7 dokladů" a dál se nešlo. Uživatel se nedostal ani na čísla faktur, ani na
-- to, co z nich máme vytěženo — a AI chat mlčel ze stejného důvodu, protože
-- agregát dostal, ale k dokladu se nedostal.
--
-- ⭐ ČTE SE PODLE IDENTITY, NE PODLE JMÉNA
-- `counterparty_id` (IČO) je klíč; jméno je záložní cesta pro odběratele bez
-- IČO (fyzické osoby v korpusu je běžně nemají). Kdyby se párovalo jen jménem,
-- „KILINC s.r.o." a „KILINC  s.r.o." (dvě mezery) by byly dva různí dlužníci —
-- a naopak dvě firmy téhož jména by splynuly. Řádek z get_receivables_overdue
-- proto nese `id` = IČO, pokud existuje, jinak jméno; sem se posílá beze změny.
--
-- ⭐ POLE SE ČTOU SVÝMI SKUTEČNÝMI JMÉNY
-- Registr nese `invoice_number` a `total_amount`. Starší čtečka se ptala na
-- `doc_number`/`amount_total`, což jsou klíče, které v datech NEJSOU — a
-- chybějící klíč v JSONB vrací NULL, ne chybu. Tabulka se proto vykreslila,
-- součty seděly a detail tiše chyběl. Nová pole (money_id, note, doc_kind)
-- přibyla 2026-08-05; u starší generace dokladů jsou prázdná, což je poctivé
-- „nevíme", ne chyba.
--
-- Opravné doklady (záporné) se NEfiltrují: v seznamu patří vidět, protože
-- vysvětlují, proč je součet nižší než prostý součet faktur.
--
-- Konfigurace (p_params):
--   debtor        : POVINNÉ — IČO nebo jméno odběratele (hodnota `id` z řádku)
--   owner_company : nepovinné — omezení na jednu naši firmu
--   only_open     : 'true' = jen s nenulovým zůstatkem (default), jinak vše
--   limit         : default 200, strop 1000
--
-- SECURITY INVOKER → RLS rozhoduje; bez nároku prázdno, ne chyba.
-- Kontrakt: (jsonb) -> jsonb {data:{columns[], rows[]}, provenance}.

create or replace function public.get_debtor_invoices(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with cfg as (
    select
      nullif(p_params->>'debtor', '')                                as debtor,
      nullif(p_params->>'owner_company', '')                         as company,
      coalesce(nullif(p_params->>'only_open', ''), 'true') = 'true'   as only_open,
      least(coalesce(nullif(p_params->>'limit', '')::int, 200), 1000) as lim,
      public.receivable_from_param(p_params)                          as od,
      public.storno_values_param(p_params)                            as storno
  ),
  faktury as (
    select
      r.created_at                                           as vznik,
      r.fields->'invoice_number'->>'value'                   as cislo,
      r.fields->'variable_symbol'->>'value'                  as vs,
      r.fields->'issue_date'->>'value'                       as vystaveno,
      r.fields->'due_date'->>'value'                         as splatnost,
      r.fields->'total_amount'->>'value'                     as celkem,
      r.fields->'amount_unpaid'->>'value'                    as zbyva,
      r.fields->'note'->>'value'                             as poznamka,
      -- Klíč pro třetí patro. `get_document_detail` UŽ EXISTUJE a ptá se na
      -- `doc_slug` — proklik proto posílá jeho, ne money_id. (Psát druhou
      -- detailní čtečku podle money_id by znamenalo dvě pravdy o tomtéž.)
      r.doc_slug                                             as klic,
      -- Stav z JEDNOHO slovníku (invoice_state) — týž jako karta a dlužníci.
      public.invoice_state(r.fields, cfg.od, cfg.storno)                 as _stav,
      (case when (r.fields->'amount_unpaid'->>'value') ~ '^-?[0-9]+(\.[0-9]+)?$'
            then (r.fields->'amount_unpaid'->>'value')::numeric end) as _zbyva_num,
      (case when (r.fields->'due_date'->>'value') ~ '^\d{4}-\d{2}-\d{2}$'
            then (r.fields->'due_date'->>'value')::date end)         as _splatnost_dt
    from public.li_source_registry r, cfg
    where r.doc_type = 'invoice'
      and r.superseded_by is null
      and cfg.debtor is not null
      -- Identita (IČO) NEBO jméno — řádek posílá to, co má.
      and (r.counterparty_id_value = cfg.debtor
           or r.counterparty_value = cfg.debtor)
      and (cfg.company is null or r.owner_company_value = cfg.company)
  ),
  vybrane as (
    select f.*,
           case when f._splatnost_dt is not null and f._zbyva_num > 0.005
                then (current_date - f._splatnost_dt) end as dni
    from faktury f, cfg
    -- „jen otevřené" = vše, co není uhrazené ani stornované (předepsané zůstává:
    -- ještě se bude platit; bez stavu úhrady zůstává: nevíme)
    where not cfg.only_open
       or f._stav not in ('paid', 'storno')
    order by f._splatnost_dt desc nulls last
    limit (select lim from cfg)
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'columns', jsonb_build_array(
        jsonb_build_object('key','cislo',     'label_key','app.cols.invoice_number'),
        jsonb_build_object('key','vs',        'label_key','app.cols.variable_symbol'),
        jsonb_build_object('key','vystaveno', 'label_key','app.cols.issue_date'),
        jsonb_build_object('key','splatnost', 'label_key','app.cols.due_date'),
        jsonb_build_object('key','dni',       'label_key','app.cols.overdue_days','align','right'),
        jsonb_build_object('key','celkem',    'label_key','app.cols.total_amount', 'align','right'),
        jsonb_build_object('key','zbyva',     'label_key','app.cols.amount_unpaid','align','right'),
        -- Stav dokladu jako ŠTÍTEK (vzor prototypu: Uhrazeno / Po splatnosti) —
        -- buňka je i18n klíč (`value_keys`), slovo i glyf dodá plocha.
        jsonb_build_object('key','stav',      'label_key','app.cols.state',       'value_keys', true),
        jsonb_build_object('key','poznamka',  'label_key','app.cols.note')
      ),
      -- Řádek je DOKLAD: jeho `id` je doc slug, takže druhé patro
      -- prokliku otevírá čtečku dokladů. Viz row_kind v get_receivables_overdue.
      'row_kind', 'document',
      'rows', coalesce((
        select jsonb_agg(jsonb_build_object(
                 -- `id` = klíč pro třetí patro (get_document_detail)
                 'id',        v.klic,
                 'cislo',     coalesce(v.cislo, '—'),
                 'vs',        coalesce(v.vs, '—'),
                 'vystaveno', coalesce(v.vystaveno, '—'),
                 'splatnost', coalesce(v.splatnost, '—'),
                 'dni',       coalesce(v.dni::text, '—'),
                 'celkem',    coalesce(v.celkem, '—'),
                 'zbyva',     coalesce(v.zbyva, '—'),
                 -- klíče DOSLOVNĚ (i18n brány je hledají ve zdroji), stav z invoice_state
                 'stav',      case v._stav
                                when 'storno'     then 'app.inv.state.storno'
                                when 'unknown'    then 'app.inv.state.unknown'
                                when 'paid'       then 'app.inv.state.paid'
                                when 'scheduled'  then 'app.inv.state.scheduled'
                                when 'correction' then 'app.inv.state.correction'
                                when 'overdue'    then 'app.inv.state.overdue'
                                else                   'app.inv.state.open'
                              end,
                 'poznamka',  coalesce(v.poznamka, ''))
               order by v._splatnost_dt desc nulls last)
        from vybrane v), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'li-source-registry',
      -- ČERSTVOST Z DAT (brána `cerstvost-z-dat`): nejnovější příchod verze dokladu
      -- (`created_at`) mezi fakturami TOHO odběratele — univerzum, ze kterého je tabulka
      -- (i „jen otevřené" je výběr z nich). Prázdno → `:no_data`, now() jen záloha.
      'freshness_at', to_char(coalesce((select max(vznik) from faktury), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'debtor-invoices'
                      || case when (select max(vznik) from faktury) is null then ':no_data' else '' end
    ) || public.scope_applied(p_params, 'owner_company')
  );
$$;

comment on function public.get_debtor_invoices(jsonb) is
  'Faktury jednoho odběratele — druhé patro prokliku z get_receivables_overdue. Páruje podle counterparty_id (IČO), jméno je záloha pro odběratele bez IČO. Opravné doklady se nefiltrují: v seznamu vysvětlují, proč je součet nižší. p_params.debtor je povinné, jinak prázdno.';

revoke all on function public.get_debtor_invoices(jsonb) from public, anon;
grant execute on function public.get_debtor_invoices(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_receivables_overdue.sql
-- -----------------------------------------------------------------------------

-- Data RPC pro blok 'table': POHLEDÁVKY PO SPLATNOSTI — kdo kolik dluží k datu.
--
-- Odpovídá na otázku, kterou tabulka dokladů zodpovědět neumí: registr je
-- per-doklad, kdežto dlužník je AGREGÁT přes doklady jednoho odběratele. Proto
-- to nesmí počítat klient (pravidlo „žádné klientské agregace nad li_*") a proto
-- to není jen další filtr nad get_document_register.
--
-- ⭐ CO JE „PO SPLATNOSTI" (a co to NENÍ)
-- Pravdu o platbě nese `amount_unpaid` (Money `UhradyZbyva`): 0 = uhrazeno,
-- > 0 = dluh včetně částečné úhrady. NIKOLI `settled` — to je Money
-- `PriznakVyrizeno` a u UHRAZENÉ faktury bývá False; kdyby na něm blok stál,
-- tvrdil by miliardové nedoplatky (naměřeno 2026-07-30: 22 762 z 22 916 faktur
-- „neuhrazeno", včetně dokladů z 2016). A `KUhrade` taky ne: u uhrazené faktury
-- se rovná celkové částce stejně jako u neuhrazené.
--
-- ⭐⭐ OPRAVNÝ DOKLAD ODEČÍTÁ (rozhodnutí majitele 2026-08-05)
-- Dobropis nese ZÁPORNÉ `amount_unpaid`. Dřív ho podmínka `dluh > 0` odřízla
-- NA ÚROVNI DOKLADU, takže dlužník platil plnou částku, i když mu ji oprava
-- snížila. Naměřeno na produkci: KILINC 315 471 → 292 072 (dvě opravy −23 399);
-- napříč tabulkou 77 → 72 dlužníků (pět jich oprava vynuluje úplně) a
-- 8 197 070 → 8 070 801.
--
-- Z toho plynou tři pravidla, která spolu drží:
--   1. Záporné doklady se ZAPOČÍTÁVAJÍ, nefiltrují se pryč.
--   2. Práh „> 0" patří až na AGREGÁT dlužníka — kdo má po odečtu nulu nebo
--      míň, není dlužník a v tabulce nemá co dělat.
--   3. `due_date < dnes` platí JEN pro kladné doklady. Oprava musí snížit dluh
--      hned, jinak by dluh chvíli „přebýval" jen proto, že dobropis je čerstvý.
--      Ze stejného důvodu se na opravy nevztahuje ani `min_days`.
--
-- Doklad bez `amount_unpaid` (starší korpus bez stavu úhrady) se NEPOČÍTÁ —
-- mlčet je správnější než tvrdit dluh z pole, které pravdu o platbě nenese.
--
-- Stav dokladu (po splatnosti / dobropis / storno / předepsáno) rozhoduje
-- invoice_state — jeden slovník s kartou protistrany (2026-09-26). Storno a
-- faktura vystavená dopředu nejsou dluh; přijatá faktura taky ne.
--
-- ⛔ DLUŽNÍK = IČO, NE JMÉNO (majitel 2026-09-29, podnět idata #114): řádek je klíčovaný
-- IČO (bez IČO jménem — fyzické osoby, doklady bez IČO; totéž pravidlo jako karta
-- v counterparty_docs). Dřív `group by klient` (jméno z faktury): naměřeno na riq
-- 14 IČO s víc jmény (přejmenovaná firma = VÍC řádků) a 6 jmen s víc IČO
-- („Slezské kamenolomy a.s." = 29243661 dnes Business Park Ďáblická + 08300283 →
-- jeden řádek 142 268 Kč místo 117 975 + 24 293). Zobrazené jméno je AKTUÁLNÍ
-- (counterparty_labels — týž výběr jako karta), ne text staré faktury.
-- `firma` = VŠECHNY naše věřitelské firmy dlužníka (dřív max() — 16 IČO dluží
-- víc našim firmám a řádek ukázal jen jednu).
--
-- Konfigurace (p_params, vše volitelné — blok je DATA):
--   owner_company : jen doklady té firmy (osa pohledu „podle firmy")
--   min_days      : jen dluhy starší než N dní po splatnosti (na opravy neplatí)
--   limit         : kolik dlužníků vrátit (default 50, strop 500)
--   classes       : [{key,label_key,pattern}] — vzory položek (týž katalog jako rozpad
--                   get_rent_breakdown; data instance)
--   tridy_vztahu  : klíče tříd, které ZAKLÁDAJÍ vztah (bez = všechny třídy z classes)
-- Klientský parametr (volba uživatele):
--   jen_tridy_vztahu : bool — jen dlužníci, se kterými má TÁŽ naše firma vztah
--                      doložený aspoň jednou vydanou položkou z tříd vztahu (např.
--                      „jen nájemní dlužníci": odběratelé kameniva kamenolomů vypadnou,
--                      naměřeno 2026-09-29 24 → 1). Kolik dlužníků filtr skryl, nese
--                      provenance.coverage (n z m) — nic se nezahazuje potichu.
--                      Rozhoduje VZTAH (firma × protistrana), ne položky konkrétní
--                      faktury: úroky, penále a staré faktury bez položek patří k nájmu,
--                      i když samy vzor nemají.
--
-- SECURITY INVOKER → RLS na li_source_registry rozhoduje; bez nároku prázdno,
-- ne chyba (týž fail-closed vzor jako ostatní li_* čtečky).
--
-- Kontrakt: (jsonb) -> jsonb {data:{columns[], rows[]}, provenance}.

-- ⭐ ČERSTVOST Z DAT (brána `cerstvost-z-dat`, 2026-09-27): `freshness_at` = nejnovější čas
-- univerza bloku, spočtený ze STEJNÝCH řádků jako hodnota. Pořadí zdrojů času: čas ze zdroje
-- (u Money `source_modified_at`, až bude úplný; u jízd/událostí `occurred_at`) › příchod verze
-- dokladu (`created_at`). NE `ingested_at`/`updated_at` — ty přepisuje KAŽDÝ import (naměřeno
-- 2026-09-27: 813 smluv = jediný čas), takže by lhaly jako faktury zamrzlé na exportu ze 6. 8.
-- Hranice `created_at`: backfill starých dokladů má čas dnešní — pravda o příchodu, ne o obsahu.
-- Prázdné univerzum → `trace_id` nese `:no_data` a čas je jen záloha `coalesce(…, now())`.
-- Stav linky (běží/neběží) sem NEPATŘÍ — je to jiný signál.
create or replace function public.get_receivables_overdue(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with cfg as (
    select
      nullif(p_params->>'owner_company', '')                        as company,
      greatest(coalesce(nullif(p_params->>'min_days', '')::int, 0), 0) as min_days,
      least(coalesce(nullif(p_params->>'limit', '')::int, 50), 500)    as lim,
      public.receivable_from_param(p_params)                        as od,
      public.storno_values_param(p_params)                          as storno,
      coalesce(p_params->'classes', '[]'::jsonb)                    as classes,
      case when jsonb_typeof(p_params->'tridy_vztahu') = 'array'
           then array(select jsonb_array_elements_text(p_params->'tridy_vztahu')) end as tridy_vztahu,
      coalesce((p_params->>'jen_tridy_vztahu')::boolean, false)     as jen_vztah
  ),
  -- Vztah (naše firma × protistrana) doložený aspoň jednou vydanou položkou z tříd vztahu.
  -- Počítá se jen, když o filtr uživatel požádal.
  vztahy as (
    select distinct
           r.fields->'owner_company'->>'value' as firma,
           coalesce(case when (r.fields->'counterparty_id'->>'value') ~ '^[0-9]{6,8}$'
                         then r.fields->'counterparty_id'->>'value' end,
                    'jmeno:' || coalesce(r.fields->'counterparty'->>'value', '—')) as klic
      from public.li_source_registry r
      cross join cfg
      cross join lateral jsonb_array_elements(coalesce(r.line_items, '[]'::jsonb)) li
     where cfg.jen_vztah
       and r.doc_type = 'invoice'
       and r.superseded_by is null
       and r.fields->'document_subtype'->>'value' = 'issued'
       and exists (select 1 from jsonb_array_elements(cfg.classes) t(c)
                    where (li->'fields'->'item_name'->>'value') ~* (c->>'pattern')
                      and (cfg.tridy_vztahu is null or c->>'key' = any (cfg.tridy_vztahu)))
  ),
  -- Rozbalení dokladů: hodnoty pole nesou tvar {value, status, confidence…},
  -- takže se čte `->'x'->>'value'`, ne `->>'x'`. Datum se validuje regexem —
  -- vytěžená hodnota nemusí být datum a ::date by shodilo celý blok.
  doklady as (
    select
      r.created_at as vznik,
      coalesce(r.fields->'counterparty'->>'value', '—')      as klient,
      -- IČO jen v platném tvaru (jako counterparty_resolve); jiné = bez IČO → jménem
      case when (r.fields->'counterparty_id'->>'value') ~ '^[0-9]{6,8}$'
           then r.fields->'counterparty_id'->>'value' end    as ico,
      r.fields->'owner_company'->>'value'                    as firma,
      (r.fields->'amount_unpaid'->>'value')::numeric         as castka,
      (r.fields->'due_date'->>'value')::date                 as splatnost,
      -- Stav z JEDNOHO slovníku (invoice_state) — týž jako karta protistrany:
      -- storno není dluh, předepsaná faktura (vznik v budoucnu) taky ne.
      public.invoice_state(r.fields, cfg.od, cfg.storno)                 as stav
    from public.li_source_registry r, cfg
    where r.doc_type = 'invoice'
      and r.superseded_by is null
      -- Pohledávka = VYDANÁ faktura; přijatá je náš závazek, ne jeho dluh.
      and r.fields->'document_subtype'->>'value' = 'issued'
      and r.fields ? 'amount_unpaid'
      and (r.fields->'amount_unpaid'->>'value') ~ '^-?[0-9]+(\.[0-9]+)?$'
      and (r.fields->'due_date'->>'value') ~ '^\d{4}-\d{2}-\d{2}$'
      and (cfg.company is null or r.fields->'owner_company'->>'value' = cfg.company)
  ),
  -- Kladné jen po splatnosti; záporné (opravy) VŽDY — viz pravidlo 3 výše.
  zapocitane_vse as (
    select d.*, (current_date - d.splatnost) as dni
    from doklady d, cfg
    where (d.stav = 'overdue' and (current_date - d.splatnost) >= cfg.min_days)
       or d.stav = 'correction'
  ),
  zapocitane as (
    select z.* from zapocitane_vse z, cfg
     where not cfg.jen_vztah
        or exists (select 1 from vztahy v
                    where v.firma = z.firma and v.klic = coalesce(z.ico, 'jmeno:' || z.klient))
  ),
  -- kolik dlužníků by bylo BEZ filtru vztahu (pro provenance.coverage)
  dluznici_bez_filtru as (
    select count(*) as m from (
      select 1 from zapocitane_vse group by coalesce(ico, 'jmeno:' || klient) having sum(castka) > 0.005) x
  ),
  -- Dlužník = odběratel, ne doklad. `max(dni)` jen přes KLADNÉ doklady — „jak
  -- dlouho to visí" se ptá na nezaplacenou fakturu, ne na dobropis.
  dluznici as (
    select
      coalesce(ico, 'jmeno:' || klient)                           as klic,
      min(klient)                                                 as klient,
      max(ico)                                                    as ico,
      string_agg(distinct firma, ' · ' order by firma)            as firma,
      round(sum(castka))::text                                    as castka,
      (max(dni) filter (where castka > 0.005))::text              as dni,
      (count(*) filter (where castka > 0.005))::text              as dokladu,
      (count(*) filter (where castka < -0.005))::text             as oprav,
      sum(castka)                                                 as _sort
    from zapocitane
    group by coalesce(ico, 'jmeno:' || klient)
    -- Práh až na agregátu (pravidlo 2): koho oprava vynulovala, není dlužník.
    having sum(castka) > 0.005
    order by sum(castka) desc
    limit (select lim from cfg)
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      'columns', jsonb_build_array(
        jsonb_build_object('key','klient',  'label_key','app.cols.counterparty'),
        jsonb_build_object('key','firma',   'label_key','app.cols.owner_company'),
        jsonb_build_object('key','castka',  'label_key','app.cols.overdue_amount','align','right'),
        jsonb_build_object('key','dni',     'label_key','app.cols.overdue_days',  'align','right'),
        jsonb_build_object('key','dokladu', 'label_key','app.cols.documents',     'align','right'),
        jsonb_build_object('key','oprav',   'label_key','app.cols.corrections',   'align','right')
      ),
      -- CO řádek JE. Bez tohohle pole má shell pro `id` jediný význam
      -- („dokument") a klik na dlužníka poslal IČO čtečce dokladů — ta na něj
      -- nic nenašla a vydala PRÁZDNOU kartu místo chyby (naměřeno 08-07).
      -- Druh vydává RPC, protože jedině ona ví, co do `id` dala.
      'row_kind', 'counterparty',
      'rows', coalesce((
        select jsonb_agg(jsonb_build_object(
                 -- `id` je klíč pro proklik na seznam faktur dlužníka
                 -- (get_debtor_invoices bere counterparty_id, jinak jméno).
                 'id',      coalesce(d.ico, d.klient),
                 'klient',  coalesce(l.label, d.klient),
                 'firma',   coalesce(d.firma, '—'),
                 'castka',  d.castka,
                 'dni',     coalesce(d.dni, '0'),
                 'dokladu', d.dokladu,
                 'oprav',   d.oprav)
               order by d._sort desc)
        from dluznici d
        left join public.counterparty_labels((select array_agg(ico) from dluznici)) l on l.ico = d.ico),
        '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'li-source-registry',
      'freshness_at', to_char(coalesce((select max(vznik) from doklady), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'receivables-overdue'
                      || case when (select max(vznik) from doklady) is null then ':no_data' else '' end
    ) || case when (select jen_vztah from cfg) then jsonb_build_object('coverage', jsonb_build_object(
           'n', (select count(*) from (select 1 from zapocitane group by coalesce(ico, 'jmeno:' || klient) having sum(castka) > 0.005) y),
           'm', (select m from dluznici_bez_filtru),
           'label_key', 'app.prov.coverage.relation_debtors'))
         else '{}'::jsonb end
      || public.scope_applied(p_params, 'owner_company')
  );
$$;

comment on function public.get_receivables_overdue(jsonb) is
  'Pohledávky po splatnosti agregované na odběratele. Stojí na stavu úhrady z účetnictví (Money UhradyZbyva), NIKOLI na settled/PriznakVyrizeno. Opravné doklady (záporné amount_unpaid) ODEČÍTAJÍ a nepodléhají filtru splatnosti; práh „dluží“ se uplatní až na agregátu, takže koho oprava vynuluje, ten v tabulce není. Doklad bez amount_unpaid se nepočítá.';

revoke all on function public.get_receivables_overdue(jsonb) from public, anon;
grant execute on function public.get_receivables_overdue(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/story_branch_deploy_rail.sql
-- -----------------------------------------------------------------------------

-- Function: public.story_branch_deploy_rail
-- Description: Compact "rail" snapshot for the BranchDeployRail UI strip —
--   shows the story's current default_branch + most recent B/G slot state
--   per app + last rollback per app. Returns one row per associated app.
--
--   This is a flatter, smaller payload than story_timeline; the rail UI
--   uses it to render the vertical "branch → switches → rollbacks" axis
--   without having to filter the full timeline.
-- Security: SECURITY DEFINER, same admin-or-participant guard as
--   story_timeline.

CREATE OR REPLACE FUNCTION public.story_branch_deploy_rail(
  p_story_id uuid
)
RETURNS TABLE (
  app_name              text,
  active_slot           text,
  active_image_tag      text,
  inactive_image_tag    text,
  active_health         text,
  last_switch_at        timestamptz,
  default_branch        text,
  last_rollback_at      timestamptz,
  last_rollback_status  text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id  uuid := auth.uid();
  v_is_admin boolean := false;
  v_branch   text;
BEGIN
  IF v_user_id IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  v_is_admin := public.is_admin_or_staff(v_user_id);

  IF NOT v_is_admin
     AND NOT EXISTS (
       SELECT 1 FROM public.partner_stories ps
       WHERE ps.id = p_story_id
         AND (
           ps.is_stack_default = true
           OR EXISTS (
             SELECT 1 FROM public.story_participants sp
             WHERE sp.story_id = ps.id AND sp.user_id = v_user_id
           )
         )
     )
  THEN
    RAISE EXCEPTION 'Access denied: story participant or admin/staff required'
      USING ERRCODE = '42501';
  END IF;

  SELECT ps.default_branch INTO v_branch
  FROM public.partner_stories ps
  WHERE ps.id = p_story_id;

  RETURN QUERY
  WITH last_rb AS (
    SELECT DISTINCT ON (rh.app_name)
      rh.app_name,
      rh.triggered_at,
      COALESCE(rh.execution_status, rh.approval_status) AS rb_status
    FROM public.rollback_history rh
    WHERE rh.app_name IN (
      SELECT cs.app_name FROM public.coolify_app_slots cs WHERE cs.story_id = p_story_id
    )
    ORDER BY rh.app_name, rh.triggered_at DESC
  )
  SELECT
    cs.app_name,
    cs.active_slot,
    CASE WHEN cs.active_slot = 'blue' THEN cs.blue_image_tag ELSE cs.green_image_tag END
      AS active_image_tag,
    CASE WHEN cs.active_slot = 'blue' THEN cs.green_image_tag ELSE cs.blue_image_tag END
      AS inactive_image_tag,
    CASE WHEN cs.active_slot = 'blue' THEN cs.blue_health ELSE cs.green_health END
      AS active_health,
    cs.last_switch_at,
    v_branch                  AS default_branch,
    lr.triggered_at            AS last_rollback_at,
    lr.rb_status               AS last_rollback_status
  FROM public.coolify_app_slots cs
  LEFT JOIN last_rb lr ON lr.app_name = cs.app_name
  WHERE cs.story_id = p_story_id
  ORDER BY cs.app_name ASC;
END;
$$;

REVOKE ALL ON FUNCTION public.story_branch_deploy_rail(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.story_branch_deploy_rail(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.story_branch_deploy_rail(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/story_timeline.sql
-- -----------------------------------------------------------------------------

-- Function: public.story_timeline
-- Description: Unified chronological feed for one story — what AISHA + the
--   deploy pipeline have been doing. UNIONs three sources:
--     1. ai_trace_events for the story's ai_runs (LLM calls, tool calls,
--        patches, route decisions, critic reviews, escalations, etc.)
--     2. rollback_history rows whose app_name matches one of the story's
--        coolify_app_slots
--     3. Synthetic 'bg_switch' rows from coolify_app_slots.last_switch_at
--        for the story's apps
-- Security: SECURITY DEFINER. Admin/staff see all; otherwise the caller
--   must be a story_participants member (matches kanban_stories_view +
--   get_story_rulesets pattern).
-- See also: ai_trace_events (table), rollback_history (table),
--   coolify_app_slots (table), useStoryTimeline (UI hook).

-- A currency-suffixed name (`*_usd`) was removed from this function's signature.
-- The TYPES did not change, so CREATE OR REPLACE matches the deployed function and
-- Postgres refuses to rename in place ("cannot change name of input parameter", or
-- "cannot change return type" when the renamed name is a RETURNS TABLE column).
-- DROP-first is the convention used elsewhere in this directory; the REVOKE/GRANT
-- below re-applies whatever privileges the drop clears.
DROP FUNCTION IF EXISTS public.story_timeline(uuid, integer);

CREATE OR REPLACE FUNCTION public.story_timeline(
  p_story_id uuid,
  p_limit    int DEFAULT 50
)
RETURNS TABLE (
  event_id        uuid,
  event_kind      text,       -- 'trace' | 'rollback' | 'bg_switch'
  trace_event_type text,      -- ai_event_type::text (NULL for non-trace)
  ts              timestamptz,
  agent_slug      text,
  operation       text,
  status          text,
  duration_ms     int,
  cost        numeric,
  story_id        uuid,
  run_id          uuid,
  app_name        text,
  files_changed   text[],
  payload         jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id  uuid := auth.uid();
  v_is_admin boolean := false;
BEGIN
  IF v_user_id IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  v_is_admin := public.is_admin_or_staff(v_user_id);

  -- Authorization: admin/staff OR participant OR stack-default story.
  IF NOT v_is_admin
     AND NOT EXISTS (
       SELECT 1 FROM public.partner_stories ps
       WHERE ps.id = p_story_id
         AND (
           ps.is_stack_default = true
           OR EXISTS (
             SELECT 1 FROM public.story_participants sp
             WHERE sp.story_id = ps.id AND sp.user_id = v_user_id
           )
         )
     )
  THEN
    RAISE EXCEPTION 'Access denied: story participant or admin/staff required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH story_runs AS (
    SELECT ar.id AS run_id
    FROM public.ai_runs ar
    WHERE ar.story_id = p_story_id
  ),
  story_apps AS (
    SELECT cs.app_name, cs.last_switch_at, cs.active_slot,
           cs.blue_image_tag, cs.green_image_tag
    FROM public.coolify_app_slots cs
    WHERE cs.story_id = p_story_id
  ),
  trace_rows AS (
    SELECT
      ate.id                       AS event_id,
      'trace'::text                AS event_kind,
      ate.event_type::text         AS trace_event_type,
      ate.created_at               AS ts,
      ate.agent_slug,
      ate.operation,
      ate.status,
      ate.duration_ms,
      NULLIF(ate.cost_json ->> 'total', '')::numeric AS cost,
      p_story_id                   AS story_id,
      ate.run_id,
      NULL::text                   AS app_name,
      CASE
        WHEN ate.event_type = 'patch_applied'
             AND jsonb_typeof(ate.response_summary -> 'files') = 'array'
          THEN ARRAY(SELECT jsonb_array_elements_text(ate.response_summary -> 'files'))
        ELSE NULL
      END                          AS files_changed,
      jsonb_strip_nulls(jsonb_build_object(
        'provider',         ate.provider,
        'request_summary',  ate.request_summary,
        'response_summary', ate.response_summary,
        'error',            ate.error_json
      ))                           AS payload
    FROM public.ai_trace_events ate
    WHERE ate.run_id IN (SELECT run_id FROM story_runs)
  ),
  rollback_rows AS (
    SELECT
      rh.id                        AS event_id,
      'rollback'::text             AS event_kind,
      NULL::text                   AS trace_event_type,
      rh.triggered_at              AS ts,
      NULL::text                   AS agent_slug,
      format('rollback %s→%s', rh.from_slot, rh.to_slot) AS operation,
      COALESCE(rh.execution_status, rh.approval_status)   AS status,
      NULL::int                    AS duration_ms,
      NULL::numeric                AS cost,
      p_story_id                   AS story_id,
      NULL::uuid                   AS run_id,
      rh.app_name,
      NULL::text[]                 AS files_changed,
      jsonb_strip_nulls(jsonb_build_object(
        'from_slot',         rh.from_slot,
        'to_slot',           rh.to_slot,
        'from_image_tag',    rh.from_image_tag,
        'to_image_tag',      rh.to_image_tag,
        'triggered_by',      rh.triggered_by,
        'approval_status',   rh.approval_status,
        'execution_status',  rh.execution_status,
        'sentry_correlation', rh.sentry_correlation
      ))                           AS payload
    FROM public.rollback_history rh
    WHERE rh.app_name IN (SELECT app_name FROM story_apps)
  ),
  bg_switch_rows AS (
    SELECT
      gen_random_uuid()            AS event_id,
      'bg_switch'::text            AS event_kind,
      NULL::text                   AS trace_event_type,
      sa.last_switch_at            AS ts,
      NULL::text                   AS agent_slug,
      format('B/G switch → %s', sa.active_slot) AS operation,
      'succeeded'::text            AS status,
      NULL::int                    AS duration_ms,
      NULL::numeric                AS cost,
      p_story_id                   AS story_id,
      NULL::uuid                   AS run_id,
      sa.app_name,
      NULL::text[]                 AS files_changed,
      jsonb_build_object(
        'active_slot',      sa.active_slot,
        'blue_image_tag',   sa.blue_image_tag,
        'green_image_tag',  sa.green_image_tag
      )                            AS payload
    FROM story_apps sa
    WHERE sa.last_switch_at IS NOT NULL
  )
  SELECT * FROM (
    SELECT * FROM trace_rows
    UNION ALL
    SELECT * FROM rollback_rows
    UNION ALL
    SELECT * FROM bg_switch_rows
  ) merged
  ORDER BY ts DESC NULLS LAST
  LIMIT LEAST(p_limit, 500);
END;
$$;

REVOKE ALL ON FUNCTION public.story_timeline(uuid, int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.story_timeline(uuid, int) TO authenticated;
GRANT EXECUTE ON FUNCTION public.story_timeline(uuid, int) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/submit_ai_feedback.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- Function: submit_ai_feedback
-- Purpose: Submit user feedback on an AI response (for ALE training data)
-- Part of: AISHA Learning Engine (ALE) — Phase 1
--
-- Oprava 2026-09-29 (SELF_IMPROVEMENT_LOOP.md §3, K-16) — naměřeno na main 9087ef3df:
--   Funkce byla SECURITY INVOKER, ale chat_messages má jedinou čtecí politiku — pro
--   správce. Běžný uživatel tak neviděl ani VLASTNÍ zprávu: conversation_id zůstal NULL
--   a process_feedback_to_training takovou zpětnou vazbu vždy přeskočila (bez konverzace
--   nenajde otázku). Zpětná vazba uživatelů se tedy NIKDY nestala trénovacím párem.
--   Současně funkce přijala od volajícího libovolné message_id, run_id a trace_event_id
--   — jakmile by dráha začala fungovat, šlo by „opravovat" cizí odpovědi a otrávit data.
--   org_id se navíc bralo z libovolného partnerského profilu (join na roli, ne na profil).
-- Teď (SECURITY DEFINER, stráž uvnitř):
--   * hodnotit smí jen odpověď asistenta ve VLASTNÍ konverzaci; neexistující i cizí
--     zpráva = táž chyba (žádné orákulum);
--   * run_id a trace_event_id se odvozují ze zprávy; od volajícího se přijmou jen tehdy,
--     když běh patří volajícímu (bez zprávy);
--   * org_id jen z vlastního partnerského profilu.
-- Funkce nebyla v heals — běžící DB držela verzi z cold startu.
-- =============================================================================

CREATE OR REPLACE FUNCTION public.submit_ai_feedback(
  p_correction_text text DEFAULT NULL,
  p_domain_tags text[] DEFAULT '{}'::text[],
  p_feedback_category text DEFAULT 'general',
  p_message_id uuid DEFAULT NULL,
  p_metadata jsonb DEFAULT '{}'::jsonb,
  p_rating smallint DEFAULT 0,
  p_run_id uuid DEFAULT NULL,
  p_trace_event_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid;
  v_conversation_id uuid;
  v_org_id uuid;
  v_story_id uuid;
  v_run_id uuid;
  v_trace_event_id uuid;
  v_feedback_id uuid;
  v_recent_count integer;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  -- Rate limit: max 30 feedback per hour per user
  SELECT count(*) INTO v_recent_count
  FROM public.ai_feedback
  WHERE user_id = v_user_id
    AND created_at > now() - interval '1 hour';

  IF v_recent_count >= 30 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'rate_limit_exceeded',
      'message', 'Maximum 30 feedback submissions per hour'
    );
  END IF;

  IF p_message_id IS NOT NULL THEN
    -- Jen odpověď asistenta ve vlastní konverzaci. Cizí i neexistující = táž chyba.
    SELECT cm.conversation_id, NULLIF(cm.content_metadata->>'aisha_run_id', '')::uuid
      INTO v_conversation_id, v_run_id
    FROM public.chat_messages cm
    JOIN public.chat_conversations c ON c.id = cm.conversation_id
    WHERE cm.id = p_message_id
      AND cm.role = 'assistant'
      AND c.user_id = v_user_id;

    IF v_conversation_id IS NULL THEN
      RAISE EXCEPTION 'Message not found' USING ERRCODE = 'P0002';
    END IF;
  ELSIF p_run_id IS NOT NULL THEN
    -- Bez zprávy: běh přijmeme jen tehdy, když patří volajícímu.
    SELECT ar.id INTO v_run_id
    FROM public.ai_runs ar
    WHERE ar.id = p_run_id AND ar.actor_user_id = v_user_id;
  END IF;

  IF v_run_id IS NOT NULL THEN
    SELECT ar.story_id INTO v_story_id
    FROM public.ai_runs ar
    WHERE ar.id = v_run_id;

    -- trace_event_id od volajícího jen z téhož běhu; jinak poslední llm_call běhu.
    IF p_trace_event_id IS NOT NULL THEN
      SELECT ate.id INTO v_trace_event_id
      FROM public.ai_trace_events ate
      WHERE ate.id = p_trace_event_id AND ate.run_id = v_run_id;
    END IF;
    IF v_trace_event_id IS NULL THEN
      SELECT ate.id INTO v_trace_event_id
      FROM public.ai_trace_events ate
      WHERE ate.run_id = v_run_id
        AND ate.event_type = 'llm_call'
      ORDER BY ate.created_at DESC
      LIMIT 1;
    END IF;
  END IF;

  -- Organizace jen z vlastního partnerského profilu.
  SELECT pp.id INTO v_org_id
  FROM public.partner_profiles pp
  WHERE pp.user_id = v_user_id
  LIMIT 1;

  INSERT INTO public.ai_feedback (
    trace_event_id,
    conversation_id,
    message_id,
    user_id,
    org_id,
    story_id,
    run_id,
    rating,
    correction_text,
    feedback_category,
    domain_tags,
    metadata
  ) VALUES (
    v_trace_event_id,
    v_conversation_id,
    p_message_id,
    v_user_id,
    v_org_id,
    v_story_id,
    v_run_id,
    p_rating,
    p_correction_text,
    p_feedback_category,
    p_domain_tags,
    p_metadata
  )
  RETURNING id INTO v_feedback_id;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'AI_FEEDBACK_SUBMITTED',
    jsonb_build_object(
      'feedback_id', v_feedback_id,
      'rating', p_rating,
      'category', p_feedback_category,
      'has_correction', p_correction_text IS NOT NULL,
      'has_run_id', v_run_id IS NOT NULL,
      'has_story_id', v_story_id IS NOT NULL
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'feedback_id', v_feedback_id,
    'run_id', v_run_id,
    'story_id', v_story_id,
    'trace_event_id', v_trace_event_id
  );
END;
$$;

REVOKE ALL ON FUNCTION public.submit_ai_feedback(text, text[], text, uuid, jsonb, smallint, uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.submit_ai_feedback(text, text[], text, uuid, jsonb, smallint, uuid, uuid) TO authenticated;

COMMENT ON FUNCTION public.submit_ai_feedback(text, text[], text, uuid, jsonb, smallint, uuid, uuid) IS
  'Zpětná vazba uživatele na odpověď asistenta ve VLASTNÍ konverzaci (ALE). run/trace se odvozují ze zprávy; '
  'cizí i neexistující zpráva = Message not found. Limit 30/h.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/submit_batch_job.sql
-- -----------------------------------------------------------------------------

-- Function: submit_batch_job
-- Registers a batch job in ai_batch_jobs after the provider's batch endpoint
-- has accepted the JSONL request. Returns the local UUID of the batch row.
-- The actual provider POST is performed by the TS batchSubmitter helper —
-- this RPC is the authoritative state-write.

-- A currency-suffixed name (`*_usd`) was removed from this function's signature.
-- The TYPES did not change, so CREATE OR REPLACE matches the deployed function and
-- Postgres refuses to rename in place ("cannot change name of input parameter", or
-- "cannot change return type" when the renamed name is a RETURNS TABLE column).
-- DROP-first is the convention used elsewhere in this directory; the REVOKE/GRANT
-- below re-applies whatever privileges the drop clears.
DROP FUNCTION IF EXISTS public.submit_batch_job(text, text, integer, jsonb, uuid, text, uuid, numeric);

CREATE OR REPLACE FUNCTION public.submit_batch_job(
  p_provider text,
  p_external_batch_id text,
  p_request_count int,
  p_metadata jsonb DEFAULT '{}'::jsonb,
  p_related_run_id uuid DEFAULT NULL,
  p_agent_slug text DEFAULT 'aisha',
  p_story_id uuid DEFAULT NULL,
  p_estimated_cost numeric DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id      uuid;
  v_user_id uuid;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
  END IF;
  IF p_provider NOT IN ('anthropic', 'openai') THEN
    RAISE EXCEPTION 'Invalid provider: %', p_provider USING ERRCODE = '22023';
  END IF;
  IF p_external_batch_id IS NULL OR p_external_batch_id = '' THEN
    RAISE EXCEPTION 'p_external_batch_id is required' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(p_request_count, 0) <= 0 THEN
    RAISE EXCEPTION 'p_request_count must be > 0' USING ERRCODE = '22023';
  END IF;

  v_user_id := auth.uid();

  INSERT INTO ai_batch_jobs (
    provider,
    external_batch_id,
    status,
    request_count,
    estimated_cost,
    related_run_id,
    agent_slug,
    story_id,
    metadata,
    created_by
  )
  VALUES (
    p_provider,
    p_external_batch_id,
    'submitted',
    p_request_count,
    p_estimated_cost,
    p_related_run_id,
    p_agent_slug,
    p_story_id,
    COALESCE(p_metadata, '{}'::jsonb),
    v_user_id
  )
  RETURNING id INTO v_id;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'batch.job_submitted',
    jsonb_build_object(
      'batch_job_id', v_id,
      'provider', p_provider,
      'external_batch_id', p_external_batch_id,
      'request_count', p_request_count,
      'related_run_id', p_related_run_id,
      'agent_slug', p_agent_slug,
      'story_id', p_story_id
    )
  );

  RETURN v_id;
END;
$$;

COMMENT ON FUNCTION public.submit_batch_job(text, text, int, jsonb, uuid, text, uuid, numeric) IS
  'Records a batch job after provider acceptance. Returns local UUID of ai_batch_jobs row.';

REVOKE ALL ON FUNCTION public.submit_batch_job(text, text, int, jsonb, uuid, text, uuid, numeric) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_batch_job(text, text, int, jsonb, uuid, text, uuid, numeric) TO authenticated;
GRANT EXECUTE ON FUNCTION public.submit_batch_job(text, text, int, jsonb, uuid, text, uuid, numeric) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/submit_longevity_assessment_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.submit_longevity_assessment_audited
-- Description: Submit OS-SUBJECTIVE questionnaire and calculate Longevity Score
-- Security: SECURITY DEFINER with audit logging
-- sensitive data: Yes - writes questionnaire responses

CREATE OR REPLACE FUNCTION public.submit_longevity_assessment_audited(
  p_responses JSONB,
  p_study_registration_id UUID DEFAULT NULL
)
RETURNS longevity_score_result
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_questionnaire_id UUID;
  v_response_id UUID;
  v_domain_scores JSONB;
  v_cls_score NUMERIC;
  v_valid_domains INTEGER := 0;
  v_domain JSONB;
  v_result longevity_score_result;
BEGIN
  -- Get OS-SUBJECTIVE questionnaire ID
  SELECT id INTO v_questionnaire_id
  FROM questionnaires
  WHERE code = 'OS-SUBJECTIVE';
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OS-SUBJECTIVE questionnaire not found';
  END IF;
  
  -- Calculate scores
  v_domain_scores := calculate_domain_scores(p_responses);
  
  -- Calculate CLS
  FOR v_domain IN SELECT * FROM jsonb_array_elements(v_domain_scores) LOOP
    IF (v_domain->>'percentage') IS NOT NULL THEN
      v_cls_score := COALESCE(v_cls_score, 0) + (v_domain->>'percentage')::NUMERIC;
      v_valid_domains := v_valid_domains + 1;
    END IF;
  END LOOP;
  
  IF v_valid_domains > 0 THEN
    v_cls_score := ROUND(v_cls_score / v_valid_domains, 1);
  END IF;
  
  -- Insert response
  INSERT INTO questionnaire_responses (
    user_id,
    questionnaire_id,
    responses,
    score,
    completed_at,
    study_registration_id
  )
  VALUES (
    auth.uid(),
    v_questionnaire_id,
    p_responses,
    ROUND(v_cls_score)::INTEGER,
    NOW(),
    p_study_registration_id
  )
  RETURNING id INTO v_response_id;
  
  -- Build result
  v_result.response_id := v_response_id;
  v_result.user_id := auth.uid();
  v_result.completed_at := NOW();
  v_result.cls_score := v_cls_score;
  v_result.domain_scores := v_domain_scores;
  
  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'sensitive data_WRITE',
    jsonb_build_object(
      'area', 'longevity_score',
      'severity', 'info',
      'entity_type', 'questionnaire_response',
      'entity_id', v_response_id,
      'cls_score', v_cls_score,
      'study_registration_id', p_study_registration_id
    )
  );
  
  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.submit_longevity_assessment_audited(jsonb, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_longevity_assessment_audited(jsonb, uuid) TO authenticated;

COMMENT ON FUNCTION public.submit_longevity_assessment_audited(jsonb, uuid) IS 'Submit OS-SUBJECTIVE assessment and calculate Longevity Score';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/submit_partner_certification.sql
-- -----------------------------------------------------------------------------

-- Function: public.submit_partner_certification
-- Arguments: p_answers jsonb, p_profile_data jsonb
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:28:07+01:00

CREATE OR REPLACE FUNCTION public.submit_partner_certification(p_answers jsonb, p_profile_data jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_result jsonb;
  v_passed boolean;
  v_score integer;
  v_total integer;
  v_correct integer := 0;
  v_question record;
  v_user_answer text;
  v_is_production_provider boolean := false;
  v_cert_level partner_certification_level;
  v_role_to_grant app_role;
  v_existing_profile_id uuid;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Check if profile data indicates production provider
  IF p_profile_data IS NOT NULL THEN
    v_is_production_provider := COALESCE((p_profile_data->>'is_production_provider')::boolean, false);
  END IF;

  -- Check existing profile if no profile data provided
  IF p_profile_data IS NULL THEN
    SELECT id, is_production_provider 
    INTO v_existing_profile_id, v_is_production_provider
    FROM partner_profiles
    WHERE user_id = v_user_id;
  END IF;

  -- Determine certification level and role based on partner type
  IF v_is_production_provider THEN
    v_cert_level := 'certified_provider';
    v_role_to_grant := 'practitioner';
  ELSE
    v_cert_level := 'certified_partner';
    v_role_to_grant := 'partner';
  END IF;

  -- Count total questions
  SELECT COUNT(*) INTO v_total
  FROM test_questions
  WHERE test_type = 'certification' AND is_active = true;

  -- Check each answer
  FOR v_question IN 
    SELECT id, correct_answer 
    FROM test_questions 
    WHERE test_type = 'certification' AND is_active = true
  LOOP
    v_user_answer := p_answers->>v_question.id::text;
    IF v_user_answer IS NOT NULL AND LOWER(v_user_answer) = LOWER(v_question.correct_answer) THEN
      v_correct := v_correct + 1;
    END IF;
  END LOOP;

  -- Calculate score
  v_score := CASE WHEN v_total > 0 
    THEN ROUND((v_correct::numeric / v_total::numeric) * 100)
    ELSE 0 
  END;
  
  v_passed := v_score >= 75;

  -- Record certification attempt
  INSERT INTO partner_certifications (user_id, answers, score, passed)
  VALUES (v_user_id, p_answers, v_score, v_passed);

  -- If passed, update partner profile and grant role
  IF v_passed THEN
    -- Sanction the privilege-column write (is_production_provider) for the
    -- partner_profiles_privilege_guard trigger. Transaction-local; a direct client
    -- cannot set this GUC (set_config is not reachable as a PostgREST RPC).
    PERFORM set_config('aisha.partner_priv_write', 'on', true);

    -- Create or update partner profile
    IF p_profile_data IS NOT NULL THEN
      INSERT INTO partner_profiles (
        user_id,
        display_name,
        business_name,
        city,
        country,
        is_production_provider,
        certification_level,
        certification_score,
        certification_passed_at,
        is_visible
      ) VALUES (
        v_user_id,
        COALESCE(p_profile_data->>'display_name', 'Partner'),
        p_profile_data->>'business_name',
        COALESCE(p_profile_data->>'city', 'Unknown'),
        COALESCE(p_profile_data->>'country', 'CZ'),
        v_is_production_provider,
        v_cert_level,
        v_score,
        now(),
        true
      )
      ON CONFLICT (user_id) DO UPDATE SET
        display_name = COALESCE(EXCLUDED.display_name, partner_profiles.display_name),
        business_name = COALESCE(EXCLUDED.business_name, partner_profiles.business_name),
        city = COALESCE(EXCLUDED.city, partner_profiles.city),
        is_production_provider = v_is_production_provider,
        certification_level = v_cert_level,
        certification_score = v_score,
        certification_passed_at = now(),
        updated_at = now();
    ELSE
      -- Update existing profile
      UPDATE partner_profiles
      SET 
        certification_level = v_cert_level,
        certification_score = v_score,
        certification_passed_at = now(),
        updated_at = now()
      WHERE user_id = v_user_id;
    END IF;

    -- Grant appropriate role (partner or practitioner)
    INSERT INTO user_roles (user_id, role, granted_by)
    VALUES (v_user_id, v_role_to_grant, v_user_id)
    ON CONFLICT (user_id, role) DO NOTHING;

    -- Log to audit journal
    INSERT INTO audit_journal (action, 
      user_id,
      action_type,
      area,
      entity_type,
      entity_id,
      severity,
      summary,
      details
    ) VALUES ('SUBMIT_CERTIFICATION', 
      v_user_id,
      'create',
      'user_management',
      'partner_certification',
      v_user_id::text,
      'info',
      'Partner certification passed',
      jsonb_build_object(
        'score', v_score,
        'certification_level', v_cert_level::text,
        'role_granted', v_role_to_grant::text,
        'is_production_provider', v_is_production_provider
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'passed', v_passed,
    'score', v_score,
    'total_questions', v_total,
    'correct_count', v_correct,
    'certification_level', v_cert_level::text,
    'role_granted', CASE WHEN v_passed THEN v_role_to_grant::text ELSE NULL END
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.submit_partner_certification(p_answers jsonb, p_profile_data jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_partner_certification(p_answers jsonb, p_profile_data jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/submit_plugin.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- submit_plugin(p_artifact_sha256, p_artifact_url, p_manifest)
-- =============================================================================
-- Creates a new plugin entry in plugin_catalog + (optionally) an initial version.
-- Status starts as 'submitted'. Logs to plugin_audit_events.
--
-- Authorization (two distinct publisher classes):
--   * admin/staff       — may submit ANY plugin kind (executable artifact required).
--   * certified partner — may submit ONLY kind='agent' (agent marketplace).
--                         The submission is identity-bound (author_partner_id) and
--                         forced to trust_tier='partner'.
--
-- Artifact is OPTIONAL: declarative agents (kind='agent', run-as-story) carry no
-- code artifact — their template lives in plugin_catalog.agent_spec and no
-- plugin_versions row is created. Every non-agent plugin (and executable/call-mode
-- agents, Phase 2) MUST provide artifact_sha256 + artifact_url.
--
-- Re-submission upserts by slug. A certified partner may only re-submit a slug
-- they already own; admin/staff may re-submit anything. Partners cannot hijack an
-- admin-owned (author_partner_id IS NULL) slug.
--
-- Approval on re-submission (canary/ga): kept when nothing changed; CARRIED OVER
-- to new code when admin/staff submits an internal plugin whose permissions do
-- not expand (owner decision 2026-09-27, audit PLUGIN_APPROVAL_CARRIED_OVER);
-- otherwise reset to 'submitted' (audit PLUGIN_APPROVAL_RESET with the reason).
-- =============================================================================

CREATE OR REPLACE FUNCTION public.submit_plugin(
  p_artifact_sha256 text DEFAULT NULL,
  p_artifact_url    text DEFAULT NULL,
  p_manifest        jsonb DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_plugin_id      uuid;
  v_version_id     uuid;
  v_user_id        uuid := auth.uid();
  v_slug           text;
  v_version        text;
  v_kind           text;
  v_is_admin       boolean;
  v_partner_id     uuid;
  v_trust_tier     public.plugin_trust_tier;
  v_existing_owner uuid;
  v_slug_exists    boolean;
  v_puvodni        public.plugin_catalog%ROWTYPE;
  v_beze_zmeny     boolean := false;
  v_status         public.plugin_status;
  v_prenos         boolean := false;   -- schválení se přenese na nový kód (viz níž)
  v_rozsireni      text[]  := '{}';    -- co by nová verze ROZŠÍŘILA (důvod resetu)
  v_zmeneno        text[]  := '{}';    -- co se změnilo BEZ rozšíření (do auditu přenosu)
  v_puvodni_verze  text;
  v_puvodni_sha    text;
  v_sb_old         jsonb;
  v_sb_new         jsonb;
  v_k              text;
BEGIN
  -- ⭐ SYSTÉMOVÝ PLUGIN SMÍ PODAT STROJ, AKTIVOVAT HO SMÍ JEN ČLOVĚK.
  --
  -- Rozhodnutí majitele 2026-09-04: „spíš bych byl pro to, aby to službě mohl
  -- uživatel povolit a následně schválit … systémové pluginy by mohly stačit
  -- u servisních rolí."
  --
  -- Do dneška vyžadovalo podání `auth.uid()`, protože je to model PODÁNÍ:
  -- někdo nabízí, někdo schvaluje. U pluginů, které přicházejí S PLATFORMOU,
  -- ale žádný „někdo" není — jsou součástí nasazení. Vynucený uživatel proto
  -- znamenal, že heslo bootstrap účtu muselo ležet v compose (rohatka
  -- `build-time-mnozina` to právem odmítla: 62 tajemství proti stropu 60).
  --
  -- ⛔ CO SERVISNÍ ROLE **NESMÍ**, a proč je to bezpečné:
  --   · `trust_tier` je natvrdo `internal` — stroj NIKDY nepodá `partner`
  --     ani `external`; ty dál vyžadují člověka s odpovědností.
  --   · `status` zůstává výchozí `submitted`. Podání NENÍ aktivace: do provozu
  --     se plugin dostane až přes `transition_plugin_status`, které vyžaduje
  --     `is_admin_or_staff()`. Stroj tedy smí NAVRHNOUT, ne ZAPNOUT.
  --   · `author_partner_id` zůstává NULL — strojové podání nemá autora
  --     a nesmí se tvářit, že ho má.
  IF public.is_service_role() AND v_user_id IS NULL THEN
    v_is_admin   := false;
    v_trust_tier := 'internal';
    v_partner_id := NULL;
  ELSIF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_manifest IS NULL THEN
    RAISE EXCEPTION 'Manifest is required';
  END IF;

  v_slug    := p_manifest->>'id';
  v_version := p_manifest->>'version';
  v_kind    := p_manifest->>'kind';

  -- Validate required fields
  IF v_slug IS NULL OR v_version IS NULL OR v_kind IS NULL THEN
    RAISE EXCEPTION 'Manifest must contain id, version and kind';
  END IF;

  -- ===== AUTHORIZATION =====
  IF v_trust_tier IS NULL THEN
  v_is_admin := public.is_admin_or_staff();
  IF v_is_admin THEN
    -- Admin/staff: any kind; trust tier from manifest (default external).
    v_trust_tier := COALESCE((p_manifest->>'trust_tier')::public.plugin_trust_tier, 'external');
  ELSIF public.is_certified_partner() AND v_kind = 'agent' THEN
    -- Certified guild member: agents only, identity-bound, partner trust tier.
    SELECT id INTO v_partner_id
      FROM public.partner_profiles
     WHERE user_id = v_user_id;
    IF v_partner_id IS NULL THEN
      RAISE EXCEPTION 'Certified partner profile not found for caller';
    END IF;
    v_trust_tier := 'partner';
  ELSIF public.current_user_has_permission('publish_plugins') THEN
    -- ⭐ ÚZKÁ PUBLIKAČNÍ DRÁHA pro SERVISNÍ účty (naměřeno 2026-09-02).
    --
    -- Bez ní musí stroj, který má do katalogu dostat NAŠE vlastní pluginy,
    -- dostat roli `admin`/`staff` — a tím i všechno ostatní, co ta role smí.
    -- Hůř: až někdo staffovi přidá další právo, servisní účet ho TIŠE dostane
    -- taky, aniž by takové rozhodnutí kdokoli udělal. Role odpovídá na „kdo to
    -- je“, oprávnění na „co smí“; servisní účet není staff, má JEDEN úkol.
    --
    -- ⛔ TIER JE PEVNÝ, NEVOLÍ SE Z MANIFESTU. Tím je tahle cesta UŽŠÍ než
    -- adminova, i když publikuje důvěryhodnější obsah: admin si tier vybírá,
    -- tenhle účet ne — takže nemůže vydat cizí plugin za interní. Kdyby si tier
    -- směl zvolit, bylo by udělené právo fakticky mocnější než role, kterou
    -- nahrazuje, a celý smysl zúžení by padl.
    v_trust_tier := 'internal';
  ELSE
    RAISE EXCEPTION
      'Unauthorized: admin/staff may submit any plugin; certified partners may submit agents only; a holder of the publish_plugins permission may submit internal plugins';
  END IF;
  END IF;

  -- ===== ARTIFACT INVARIANT =====
  -- Non-agent plugins always ship code. Agents may be declarative (no artifact).
  IF v_kind <> 'agent' AND (p_artifact_sha256 IS NULL OR p_artifact_url IS NULL) THEN
    RAISE EXCEPTION 'Plugin kind % requires artifact_sha256 and artifact_url', v_kind;
  END IF;

  -- ===== OWNERSHIP PRE-CHECK (re-submission) =====
  SELECT author_partner_id INTO v_existing_owner
    FROM public.plugin_catalog
   WHERE slug = v_slug;
  v_slug_exists := FOUND;

  IF v_slug_exists AND NOT v_is_admin THEN
    -- A certified partner may only re-submit a slug they already own.
    IF v_existing_owner IS DISTINCT FROM v_partner_id THEN
      RAISE EXCEPTION 'Plugin slug % exists and is not owned by you', v_slug;
    END IF;
  END IF;

  -- Upsert plugin catalog (slug conflict → re-submit / new version)
  -- ⛔ NAMĚŘENO 2026-09-16: ON CONFLICT natvrdo nastavil status='submitted'.
  -- `plugin-publish-init` volá submit_plugin při KAŽDÉM nasazení core, takže
  -- člověkem schválený plugin (canary/ga) spadl zpět na submitted, katalog ho
  -- přestal vydávat a /execute vracel 404 — po každém deployi.
  --
  -- Reset ale není jen vada: katalog servíruje NEJNOVĚJŠÍ verzi a
  -- `plugin_versions` ON CONFLICT (plugin_id, version) přepíše artefakt. Reset
  -- byl jediné, co bránilo, aby pod schváleným pluginem běžel jiný kód. Proto se
  -- schválení zachová JEN tehdy, když se nezměnilo nic, co schvaloval člověk:
  -- druh, důvěra, capabilities, sandbox, konfigurace, lifecycle, všechny spec
  -- — a KÓD (táž verze se stejným otiskem artefaktu už je zapsaná). Jméno,
  -- popis a autor schválení neruší.
  SELECT * INTO v_puvodni FROM public.plugin_catalog WHERE slug = v_slug;
  IF FOUND THEN
    v_beze_zmeny :=
          v_puvodni.kind::text       IS NOT DISTINCT FROM v_kind
      AND v_puvodni.trust_tier       IS NOT DISTINCT FROM v_trust_tier
      AND v_puvodni.capabilities     IS NOT DISTINCT FROM COALESCE(p_manifest->'capabilities', '[]'::jsonb)
      AND v_puvodni.config_schema    IS NOT DISTINCT FROM p_manifest->'config_schema'
      AND v_puvodni.sandbox_policy   IS NOT DISTINCT FROM p_manifest->'sandbox'
      AND v_puvodni.lifecycle        IS NOT DISTINCT FROM p_manifest->'lifecycle'
      AND v_puvodni.agent_spec       IS NOT DISTINCT FROM p_manifest->'agent_spec'
      AND v_puvodni.provider_spec    IS NOT DISTINCT FROM p_manifest->'provider_spec'
      AND v_puvodni.node_spec        IS NOT DISTINCT FROM p_manifest->'node_spec'
      AND v_puvodni.auth_spec        IS NOT DISTINCT FROM p_manifest->'auth_spec'
      AND v_puvodni.tracking_spec    IS NOT DISTINCT FROM p_manifest->'tracking_spec'
      AND v_puvodni.source_spec      IS NOT DISTINCT FROM p_manifest->'source_spec'
      AND (
        -- deklarativní podání (bez artefaktu) kód nemění
        (p_artifact_sha256 IS NULL AND p_artifact_url IS NULL)
        OR EXISTS (
          SELECT 1 FROM public.plugin_versions pv
           WHERE pv.plugin_id = v_puvodni.id
             AND pv.version = v_version
             AND pv.artifact_sha256 = p_artifact_sha256
        )
      );

    -- ⭐ PŘENESENÍ SCHVÁLENÍ NA NOVÝ KÓD (rozhodnutí majitele 2026-09-27: „schválení
    -- se přenáší"). NAMĚŘENO téhož dne: každé kolo s novou verzí pluginu vrátilo
    -- T-CARS / Webdispečink / AVP na `submitted` a data přestala téct, dokud někdo
    -- neklikl „Schválit do provozu". Člověk schvaluje OPRÁVNĚNÍ, ne každý build.
    --
    -- Přenese se jen tehdy, když
    --   · plugin JE schválený (canary/ga) a podání NENÍ shodné (to řeší v_beze_zmeny);
    --   · podává SPRÁVA (admin/staff — plugin-publish-init nese AISHA_ADMIN_JWT).
    --     Holá servisní role dál jen NAVRHUJE (doktrína výš): její token drží víc
    --     služeb a podvržený kód by jinak běžel bez člověka;
    --   · důvěra je `internal` před i po (kód z CI vlastního repa) a druh se nemění;
    --   · nic z toho, co je OPRÁVNĚNÍ, se nerozšíří:
    --       capabilities, sandbox.rpc_allowlist, sandbox.network_allowlist — jen ⊆;
    --       sandbox.timeout_ms, sandbox.max_memory_mb — jen ≤ (strop zdrojů);
    --       ostatní klíče sandboxu, source_spec.source_slug a .namespace (KAM plugin
    --       zapisuje — broker podle source_slug pouští p_source_slug), agent/provider/
    --       node/auth/tracking_spec (registrované chování, obecně neklasifikovatelné)
    --       — beze změny.
    -- Oprávněním NENÍ: kód (verze, otisk), lifecycle (vstupní soubor, strategie
    -- načtení), config_schema (JAKÁ pole plugin čte — hodnoty dává instance ze
    -- zdroje, ne katalog), source_spec.adapter_entry a .default_config (výchozí
    -- rozvrh a meze; konfigurace instance při materializaci vyhrává).
    IF NOT v_beze_zmeny AND v_puvodni.status IN ('canary'::public.plugin_status, 'ga'::public.plugin_status) THEN
      SELECT pv.version, pv.artifact_sha256 INTO v_puvodni_verze, v_puvodni_sha
        FROM public.plugin_versions pv WHERE pv.plugin_id = v_puvodni.id
       ORDER BY pv.created_at DESC LIMIT 1;

      IF v_puvodni.kind::text IS DISTINCT FROM v_kind THEN v_rozsireni := v_rozsireni || 'kind'::text; END IF;
      IF v_puvodni.trust_tier IS DISTINCT FROM v_trust_tier THEN v_rozsireni := v_rozsireni || 'trust_tier'::text; END IF;

      -- Množiny: prvek nové verze, který v původní není (neřetězcový prvek se nepozná
      -- jako shodný — počítá se jako rozšíření, raději reset než tichý průchod).
      SELECT v_rozsireni || COALESCE(array_agg('capabilities: +' || x ORDER BY x), '{}')
        INTO v_rozsireni
        FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(p_manifest->'capabilities') = 'array'
                                            THEN p_manifest->'capabilities' ELSE '[]'::jsonb END) x
       WHERE NOT (COALESCE(v_puvodni.capabilities, '[]'::jsonb) ? x);

      v_sb_old := CASE WHEN jsonb_typeof(v_puvodni.sandbox_policy) = 'object' THEN v_puvodni.sandbox_policy ELSE '{}'::jsonb END;
      v_sb_new := CASE WHEN jsonb_typeof(p_manifest->'sandbox') = 'object' THEN p_manifest->'sandbox' ELSE '{}'::jsonb END;
      FOREACH v_k IN ARRAY ARRAY['rpc_allowlist', 'network_allowlist'] LOOP
        SELECT v_rozsireni || COALESCE(array_agg(format('sandbox.%s: +%s', v_k, x) ORDER BY x), '{}')
          INTO v_rozsireni
          FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_sb_new->v_k) = 'array' THEN v_sb_new->v_k ELSE '[]'::jsonb END) x
         WHERE NOT (CASE WHEN jsonb_typeof(v_sb_old->v_k) = 'array' THEN v_sb_old->v_k ELSE '[]'::jsonb END ? x);
      END LOOP;
      FOREACH v_k IN ARRAY ARRAY['timeout_ms', 'max_memory_mb'] LOOP
        IF (v_sb_new->v_k) IS DISTINCT FROM (v_sb_old->v_k)
           AND NOT (jsonb_typeof(v_sb_new->v_k) = 'number' AND jsonb_typeof(v_sb_old->v_k) = 'number'
                    AND (v_sb_new->>v_k)::numeric <= (v_sb_old->>v_k)::numeric) THEN
          v_rozsireni := v_rozsireni || format('sandbox.%s: %s → %s', v_k,
                                               COALESCE(v_sb_old->>v_k, '∅'), COALESCE(v_sb_new->>v_k, '∅'));
        END IF;
      END LOOP;
      FOR v_k IN SELECT k FROM (SELECT jsonb_object_keys(v_sb_old) AS k UNION SELECT jsonb_object_keys(v_sb_new)) s
                  WHERE k NOT IN ('rpc_allowlist', 'network_allowlist', 'timeout_ms', 'max_memory_mb') ORDER BY k LOOP
        IF (v_sb_new->v_k) IS DISTINCT FROM (v_sb_old->v_k) THEN v_rozsireni := v_rozsireni || ('sandbox.' || v_k); END IF;
      END LOOP;

      IF (v_puvodni.source_spec IS NULL) IS DISTINCT FROM (p_manifest->'source_spec' IS NULL)
         OR (v_puvodni.source_spec->>'source_slug') IS DISTINCT FROM (p_manifest->'source_spec'->>'source_slug') THEN
        v_rozsireni := v_rozsireni || 'source_spec.source_slug'::text;
      END IF;
      IF (v_puvodni.source_spec->>'namespace') IS DISTINCT FROM (p_manifest->'source_spec'->>'namespace') THEN
        v_rozsireni := v_rozsireni || 'source_spec.namespace'::text;
      END IF;
      IF v_puvodni.agent_spec    IS DISTINCT FROM p_manifest->'agent_spec'    THEN v_rozsireni := v_rozsireni || 'agent_spec'::text;    END IF;
      IF v_puvodni.provider_spec IS DISTINCT FROM p_manifest->'provider_spec' THEN v_rozsireni := v_rozsireni || 'provider_spec'::text; END IF;
      IF v_puvodni.node_spec     IS DISTINCT FROM p_manifest->'node_spec'     THEN v_rozsireni := v_rozsireni || 'node_spec'::text;     END IF;
      IF v_puvodni.auth_spec     IS DISTINCT FROM p_manifest->'auth_spec'     THEN v_rozsireni := v_rozsireni || 'auth_spec'::text;     END IF;
      IF v_puvodni.tracking_spec IS DISTINCT FROM p_manifest->'tracking_spec' THEN v_rozsireni := v_rozsireni || 'tracking_spec'::text; END IF;

      -- Co se změnilo BEZ rozšíření — audit přenosu říká, co správa nepřezkoumala.
      IF v_puvodni_sha IS DISTINCT FROM p_artifact_sha256 THEN v_zmeneno := v_zmeneno || 'kód'::text; END IF;
      IF v_puvodni.capabilities   IS DISTINCT FROM COALESCE(p_manifest->'capabilities', '[]'::jsonb) THEN v_zmeneno := v_zmeneno || 'capabilities (zúžení)'::text; END IF;
      IF v_puvodni.sandbox_policy IS DISTINCT FROM p_manifest->'sandbox'      THEN v_zmeneno := v_zmeneno || 'sandbox (zúžení)'::text; END IF;
      IF v_puvodni.config_schema  IS DISTINCT FROM p_manifest->'config_schema' THEN v_zmeneno := v_zmeneno || 'config_schema'::text; END IF;
      IF v_puvodni.lifecycle      IS DISTINCT FROM p_manifest->'lifecycle'     THEN v_zmeneno := v_zmeneno || 'lifecycle'::text; END IF;
      IF v_puvodni.source_spec    IS DISTINCT FROM p_manifest->'source_spec'   THEN v_zmeneno := v_zmeneno || 'source_spec (adapter_entry/default_config)'::text; END IF;

      v_prenos := v_is_admin
              AND v_trust_tier = 'internal'::public.plugin_trust_tier
              AND v_puvodni.trust_tier = 'internal'::public.plugin_trust_tier
              AND cardinality(v_rozsireni) = 0;
    END IF;
  END IF;

  INSERT INTO public.plugin_catalog (
    slug, name, description, author,
    kind, trust_tier, capabilities,
    config_schema, sandbox_policy, lifecycle, agent_spec,
    -- ⛔ VŠECH ŠEST DRUHŮ, NE JEN AGENT. Naměřeno 2026-09-06: tři pluginy
    -- `kind=data_source` dorazily do katalogu, došly až do `ga` — a materializace
    -- je TIŠE přeskočila (`{skipped: 'no source_spec'}`), protože `source_spec`
    -- se sem nikdy nezapsal. Zdroj `webdispecink-fleet` tak zůstal `is_active`
    -- BEZ vykonavatele, `plugin_schedules` prázdné a z ingestu nevyšlo nic.
    -- Tabulka ty sloupce má a jejich komentář říká, že matching `materialize_*`
    -- je jejich JEDINÝ čtenář; když je nikdo nenaplní, čtenář nemá co číst.
    -- Týž tvar jako `materialize_plugin` popisuje o patro výš (6 druhů
    -- deklarováno, 1 zapojen) — jen o úroveň níž, v zápisu místo v dispečeru.
    provider_spec, node_spec, auth_spec, tracking_spec, source_spec,
    author_partner_id
  ) VALUES (
    v_slug,
    p_manifest->>'name',
    p_manifest->>'description',
    p_manifest->>'author',
    v_kind::public.plugin_kind,
    v_trust_tier,
    COALESCE(p_manifest->'capabilities', '[]'::jsonb),
    p_manifest->'config_schema',
    p_manifest->'sandbox',
    p_manifest->'lifecycle',
    p_manifest->'agent_spec',
    p_manifest->'provider_spec',
    p_manifest->'node_spec',
    p_manifest->'auth_spec',
    p_manifest->'tracking_spec',
    p_manifest->'source_spec',
    v_partner_id
  )
  ON CONFLICT (slug) DO UPDATE SET
    name          = EXCLUDED.name,
    description   = EXCLUDED.description,
    author        = EXCLUDED.author,
    kind          = EXCLUDED.kind,
    trust_tier    = EXCLUDED.trust_tier,
    capabilities  = EXCLUDED.capabilities,
    config_schema = EXCLUDED.config_schema,
    sandbox_policy = EXCLUDED.sandbox_policy,
    lifecycle     = EXCLUDED.lifecycle,
    agent_spec    = EXCLUDED.agent_spec,
    provider_spec = EXCLUDED.provider_spec,
    node_spec     = EXCLUDED.node_spec,
    auth_spec     = EXCLUDED.auth_spec,
    tracking_spec = EXCLUDED.tracking_spec,
    source_spec   = EXCLUDED.source_spec,
    -- Preserve the original owner once set (admin updates never null it out).
    author_partner_id = COALESCE(plugin_catalog.author_partner_id, EXCLUDED.author_partner_id),
    status        = CASE WHEN v_beze_zmeny OR v_prenos THEN plugin_catalog.status
                         ELSE 'submitted'::public.plugin_status END,
    updated_at    = now()
  RETURNING id, status INTO v_plugin_id, v_status;

  -- Create version record only when an artifact is supplied.
  IF p_artifact_sha256 IS NOT NULL AND p_artifact_url IS NOT NULL THEN
    INSERT INTO public.plugin_versions (
      plugin_id, version, artifact_sha256, artifact_url, submitted_by
    ) VALUES (
      v_plugin_id, v_version, p_artifact_sha256, p_artifact_url, v_user_id
    )
    ON CONFLICT (plugin_id, version) DO UPDATE SET
      artifact_sha256 = EXCLUDED.artifact_sha256,
      artifact_url    = EXCLUDED.artifact_url,
      submitted_by    = EXCLUDED.submitted_by
    RETURNING id INTO v_version_id;
  END IF;

  -- Přenos schválení: registr podle nové verze (týž krok jako přechod do canary/ga
  -- v transition_plugin_status — „schválený manifest ⇒ řádek registru"; konfigurace
  -- instance při tom vyhrává a is_active se nemění) + audit, CO se nepřezkoumalo.
  IF v_prenos THEN
    PERFORM public.materialize_plugin(v_plugin_id);
    INSERT INTO public.plugin_audit_events (plugin_id, actor_id, action, metadata)
    VALUES (v_plugin_id, v_user_id, 'PLUGIN_APPROVAL_CARRIED_OVER', jsonb_build_object(
      'slug', v_slug, 'status', v_status::text,
      'from_version', v_puvodni_verze, 'to_version', v_version,
      'from_artifact_sha256', v_puvodni_sha, 'to_artifact_sha256', p_artifact_sha256,
      'zmeneno', to_jsonb(v_zmeneno),
      'duvod', 'internal, podává správa, oprávnění nerozšířena (rozhodnutí majitele 2026-09-27)'));
  ELSIF v_puvodni.id IS NOT NULL AND NOT v_beze_zmeny
        AND v_puvodni.status IN ('canary'::public.plugin_status, 'ga'::public.plugin_status) THEN
    -- Reset schváleného pluginu se HLÁSÍ i s důvodem — správa vidí, CO má přezkoumat.
    INSERT INTO public.plugin_audit_events (plugin_id, actor_id, action, metadata)
    VALUES (v_plugin_id, v_user_id, 'PLUGIN_APPROVAL_RESET', jsonb_build_object(
      'slug', v_slug, 'from_status', v_puvodni.status::text,
      'from_version', v_puvodni_verze, 'to_version', v_version,
      'rozsireni', to_jsonb(v_rozsireni),
      'duvod', CASE
        WHEN cardinality(v_rozsireni) > 0 THEN 'nová verze rozšiřuje oprávnění'
        WHEN NOT COALESCE(v_is_admin, false) THEN 'podání strojem (servisní role) schválení nepřenáší'
        ELSE 'důvěra není internal' END));
  END IF;

  -- Audit log
  INSERT INTO public.plugin_audit_events (plugin_id, actor_id, action, metadata)
  VALUES (
    v_plugin_id, v_user_id, 'PLUGIN_SUBMITTED',
    jsonb_build_object(
      'version', v_version,
      'slug', v_slug,
      'kind', v_kind,
      'trust_tier', v_trust_tier::text,
      'declarative', (v_version_id IS NULL),
      'author_partner_id', v_partner_id
    )
  );

  RETURN jsonb_build_object(
    'plugin_id', v_plugin_id,
    'version_id', v_version_id,
    'slug', v_slug,
    'version', v_version,
    'kind', v_kind,
    'status', v_status::text,
    'schvaleni_zachovano', v_beze_zmeny OR v_prenos,
    'schvaleni_preneseno', v_prenos,
    'rozsireni', to_jsonb(v_rozsireni)
  );
END;
$$;

COMMENT ON FUNCTION public.submit_plugin(text, text, jsonb) IS
  'Submit a new plugin/agent or new version. Admin/staff (any kind) or certified partners (agents only). Artifact optional for declarative agents.';

REVOKE ALL ON FUNCTION public.submit_plugin(text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_plugin(text, text, jsonb) TO authenticated;
-- ⭐ Servisní role smí podat SYSTÉMOVÝ plugin (viz větev `is_service_role()`
-- v těle). Grant je nutný, ale sám o sobě nic neotevírá: funkce servisní roli
-- natvrdo přiděluje `trust_tier='internal'`, `author_partner_id=NULL`
-- a výchozí `status='submitted'`. Do provozu se plugin dostane až přes
-- `transition_plugin_status`, které vyžaduje `is_admin_or_staff()` — stroj
-- tedy smí NAVRHNOUT, ne ZAPNOUT.
GRANT EXECUTE ON FUNCTION public.submit_plugin(text, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/submit_study_rating.sql
-- -----------------------------------------------------------------------------

-- Function: public.submit_study_rating
-- Arguments: p_study_id uuid, p_rating integer, p_comment text, p_registration_id uuid
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:28:09+01:00

CREATE OR REPLACE FUNCTION public.submit_study_rating(p_study_id uuid, p_rating integer, p_comment text DEFAULT NULL::text, p_registration_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_rating_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  -- Check if user already has a rating for this study
  SELECT id INTO v_rating_id
  FROM study_ratings
  WHERE study_id = p_study_id AND user_id = v_user_id;
  
  IF v_rating_id IS NOT NULL THEN
    -- Update existing rating
    UPDATE study_ratings
    SET rating = p_rating,
        review = p_comment,
        registration_id = COALESCE(p_registration_id, registration_id)
    WHERE id = v_rating_id;
  ELSE
    -- Insert new rating
    INSERT INTO study_ratings (study_id, user_id, rating, review, registration_id, is_visible)
    VALUES (p_study_id, v_user_id, p_rating, p_comment, p_registration_id, true)
    RETURNING id INTO v_rating_id;
  END IF;
  
  RETURN v_rating_id;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.submit_study_rating(p_study_id uuid, p_rating integer, p_comment text, p_registration_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_study_rating(p_study_id uuid, p_rating integer, p_comment text, p_registration_id uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/subscribe_to_expert_rule.sql
-- -----------------------------------------------------------------------------

-- Function: public.subscribe_to_expert_rule
-- Arguments: p_rule_id uuid
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.subscribe_to_expert_rule(p_rule_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id uuid;
  v_was_active boolean;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Rule must be published
  PERFORM 1 FROM expert_rules WHERE id = p_rule_id AND status = 'published';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Rule not found or not published';
  END IF;

  -- Check if already subscribed (active)
  SELECT is_active INTO v_was_active
  FROM expert_rule_subscriptions
  WHERE user_id = v_caller_id AND rule_id = p_rule_id;

  IF v_was_active IS TRUE THEN
    -- Already subscribed — no-op
    RETURN true;
  END IF;

  INSERT INTO expert_rule_subscriptions (user_id, rule_id)
  VALUES (v_caller_id, p_rule_id)
  ON CONFLICT (user_id, rule_id) DO UPDATE SET is_active = true;

  -- Only increment when actually adding new/reactivated subscription
  UPDATE expert_rules SET subscriber_count = subscriber_count + 1
  WHERE id = p_rule_id;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (v_caller_id, 'EXPERT_RULE_SUBSCRIBE', jsonb_build_object(
    'area', 'knowledge', 'severity', 'info', 'rule_id', p_rule_id
  ));

  RETURN true;
END;
$function$;

REVOKE ALL ON FUNCTION public.subscribe_to_expert_rule(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.subscribe_to_expert_rule(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.subscribe_to_expert_rule(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/surface_audience_allows.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: surface_audience_allows
-- Popis: Sdílený predikát „smí tenhle uživatel vidět tohle umístění?" nad
--        deklarací surface_layouts.audience. JEDINÉ místo, které deklaraci
--        publika interpretuje — RLS ji jen zavolá, čtenáři layoutu (get_surface_layout,
--        list_surface_sections) se nemění ani o řádek.
--
-- PROČ VZNIKLO: sloupec `audience jsonb` existoval od začátku s komentářem
-- „Vyhodnocení se doplní do RLS/RPC — sloupec drží deklaraci", ale nikdo ho
-- nečetl. Důsledek naměřený naživo: KAŽDÝ přihlášený dostal z
-- list_surface_sections() všech šest sekcí včetně 'admin', protože jediná
-- policy pro authenticated měla v USING pouze `is_active = true`. Data bloku
-- RLS ořeže, ale JMÉNA SEKCÍ prosákla — a povrch, který má člověku ukázat
-- výhradně jeho práci, nesmí prozradit, co všechno existuje.
--
-- MODEL (majitel 07-25): oprávnění neplyne z role jako jmenovky, plyne z toho,
-- s čím je člověk spojen. Deklarace je proto ZÁMĚRNĚ malá a skládá jen
-- vlastnosti, které umí doložit existující mašinerie:
--
--   {}                              ungated — vidí každý přihlášený
--   {"roles": ["admin","staff"]}    aspoň jedna z rolí (has_role)
--   {"min_tier": "qualified"}       úroveň účasti (audience_user_meets_tier_requirement)
--   {"udeleni": "smlouvy"}          uživatel má na sekci UDĚLENÍ (surface_section_grants)
--
-- ⭐ OSA UDĚLENÍ (rozhodnutí majitele 2026-09-28): přístup do sekce se nastavuje
-- u uživatele v administraci, ne rolí — „přístup k datům z úhlu pohledu je jedna
-- věc, přístup do sekce extranetu je další úroveň". Udělení otevírá umístění;
-- co v sekci uvidí, dál řídí nárok na data (RLS). Hodnota = klíč sekce
-- (^[a-z][a-z0-9_]*$), jiný tvar = DENY.
--
-- Obojí zároveň = AND (obě podmínky musí platit). Prázdná deklarace propouští
-- schválně: je to parita s 2-arg tier funkcí, která na NULL požadavek vrací
-- true, a znamená to, že zavedení téhle brány nemůže samo o sobě nikomu nic
-- vzít — dokud instance nedeklaruje, nic se nemění.
--
-- FAIL CLOSED NA NEZNÁMÝ KLÍČ: deklarace s klíčem, kterému tahle funkce
-- nerozumí, DENY. Překlep (`role` místo `roles`) jinak tiše otevře sekci všem
-- a nikdo si toho nevšimne — tichá díra je horší než hlasité prázdno.
--
-- ADMIN/STAFF BYPASS: kdo provoz řídí, vidí všechna umístění. Bez toho by
-- deklarace na sekci uzamkla i toho, kdo ji spravuje, a jediná policy pro
-- authenticated nemá kudy uhnout.
--
-- PROČ DEFINER: 2-arg audience_user_meets_tier_requirement(text, uuid) je
-- grantovaná POUZE service_role. Výraz v RLS se vyhodnocuje právy dotazujícího,
-- takže přímé použití v policy pro authenticated skončí „permission denied for
-- function", ne prázdnem. DEFINER wrapper grantovaný authenticated je kanonická
-- cesta — přesně tak to dělá document_visible_to.
--
-- PROČ plpgsql: tělo se při CREATE neparsuje, takže funkce nezávisí na pořadí
-- vzniku ostatních funkcí a baseline projde na ČISTÉ DB (tatáž úvaha jako u
-- workflow_step_visible_to).
--
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- ============================================================================

CREATE OR REPLACE FUNCTION public.surface_audience_allows(
  p_uid      uuid,
  p_audience jsonb
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_key       text;
  v_role      text;
  v_role_hit  boolean := false;
  v_min_tier  text;
  v_sekce     text;
BEGIN
  -- Oracle guard: přihlášený smí vyhodnocovat JEN SVOJI viditelnost, jinak by
  -- predikát šel použít jako čtečka cizích oprávnění (tatáž úvaha jako
  -- document_visible_to). IS NOT DISTINCT FROM = NULL-safe.
  IF NOT (p_uid IS NOT DISTINCT FROM auth.uid()
          OR public.is_service_role()
          OR public.is_admin_or_staff()) THEN
    RETURN false;
  END IF;

  -- Kdo provoz řídí, vidí všechno.
  IF public.is_admin_or_staff(p_uid) THEN
    RETURN true;
  END IF;

  -- Ungated: žádná deklarace = žádné omezení.
  IF p_audience IS NULL OR p_audience = '{}'::jsonb THEN
    RETURN true;
  END IF;

  -- Neznámý klíč = DENY (viz hlavička). Kontroluje se PŘED vyhodnocením, aby
  -- deklarace `{"roles":[…], "rols":[…]}` neprošla po první rozpoznané ose.
  FOR v_key IN SELECT jsonb_object_keys(p_audience) LOOP
    IF v_key NOT IN ('roles', 'min_tier', 'udeleni') THEN
      RETURN false;
    END IF;
  END LOOP;

  -- Osa ROLE: stačí jedna z vyjmenovaných. Hodnota mimo enum app_role nikdy
  -- nematchne (has_role srovnává role::text = p_role) — proto je prázdné pole
  -- deklarace, kterou nikdo nesplní, a je to tak zamýšlené.
  IF p_audience ? 'roles' THEN
    IF jsonb_typeof(p_audience->'roles') <> 'array' THEN
      RETURN false;
    END IF;
    FOR v_role IN SELECT jsonb_array_elements_text(p_audience->'roles') LOOP
      IF public.has_role(p_uid, v_role) THEN
        v_role_hit := true;
        EXIT;
      END IF;
    END LOOP;
    IF NOT v_role_hit THEN
      RETURN false;
    END IF;
  END IF;

  -- Osa ÚROVEŇ ÚČASTI: deleguje na existující tier mašinerii (2-arg forma má
  -- vlastní NULL guard a fail-closed odvození úrovně).
  IF p_audience ? 'min_tier' THEN
    v_min_tier := nullif(p_audience->>'min_tier', '');
    IF v_min_tier IS NULL THEN
      RETURN false;
    END IF;
    IF NOT COALESCE(public.audience_user_meets_tier_requirement(v_min_tier, p_uid), false) THEN
      RETURN false;
    END IF;
  END IF;

  -- Osa UDĚLENÍ: uživatel má na sekci udělení (zapisuje jen surface_udel_admin).
  IF p_audience ? 'udeleni' THEN
    v_sekce := p_audience->>'udeleni';
    IF jsonb_typeof(p_audience->'udeleni') <> 'string' OR v_sekce !~ '^[a-z][a-z0-9_]*$' THEN
      RETURN false;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.surface_section_grants g
                    WHERE g.user_id = p_uid AND g.surface = v_sekce) THEN
      RETURN false;
    END IF;
  END IF;

  -- Všechny deklarované osy prošly.
  RETURN true;
END;
$function$;

REVOKE ALL ON FUNCTION public.surface_audience_allows(uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.surface_audience_allows(uuid, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.surface_audience_allows(uuid, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/edge_notification_campaigns.sql
-- -----------------------------------------------------------------------------

-- Function: public.edge_notification_campaigns
-- Purpose: Edge-safe notification campaign scheduler operations.

CREATE OR REPLACE FUNCTION public.edge_notification_campaigns(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_sekce text;
  v_publikum jsonb;
BEGIN
  -- ⛔ SECURITY DEFINER pomocník MUSÍ autorizovat sám sebe. Do 2026-09-21 tahle
  -- funkce stráž NEMĚLA a přitom má `GRANT EXECUTE … TO authenticated`, takže
  -- KAŽDÝ přihlášený si mohl akcí `get_all_profile_user_ids` vytáhnout seznam
  -- všech uživatelů instance. Bylo to vedené jako známá výjimka v
  -- `security-known-issues.ts`; výjimka se ruší, protože skutečný volající je
  -- jediný — worker svc-push pod service_role (ověřeno: plocha ani mobil ji
  -- nevolají, jen generované typy ji zmiňují).
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Unauthorized' USING errcode = '42501';
  END IF;

  IF p_action = 'claim_schedule' THEN
    UPDATE public.notification_campaign_schedules
    SET
      last_run_at = COALESCE(NULLIF(p_payload ->> 'now', '')::timestamptz, now()),
      status = 'running',
      updated_at = now()
    WHERE id = NULLIF(p_payload ->> 'schedule_id', '')::uuid
      AND status = 'scheduled'
    RETURNING id INTO v_id;

    RETURN jsonb_build_object('claimed', v_id IS NOT NULL);
  END IF;

  IF p_action = 'get_active_study_user_ids' THEN
    RETURN jsonb_build_object(
      'rows',
      COALESCE(
        (
          SELECT jsonb_agg(jsonb_build_object('user_id', s.user_id))
          FROM public.study_registrations s
          WHERE s.study_id = NULLIF(p_payload ->> 'study_id', '')::uuid
            AND s.status = 'active'
        ),
        '[]'::jsonb
      )
    );
  END IF;

  IF p_action = 'get_all_profile_user_ids' THEN
    RETURN jsonb_build_object(
      'rows',
      COALESCE(
        (
          SELECT jsonb_agg(jsonb_build_object('user_id', p.user_id))
          FROM public.profiles p
          WHERE p.user_id IS NOT NULL
        ),
        '[]'::jsonb
      )
    );
  END IF;

  -- ⭐ Publikum podle SEKCE povrchu: kdo sekci SMÍ VIDĚT, ten smí dostat její
  -- oznámení. Oprávnění se tím NEODVOZUJE z role, ale z TÉŽE deklarace, podle
  -- které se sekce zobrazuje — jeden rozhodovač (`surface_audience_allows`),
  -- ne druhý názor vedle něj.
  --
  -- ⛔ FAIL CLOSED na neznámou nebo neaktivní sekci: překlep v `section` by jinak
  -- tiše vydal prázdné publikum a kampaň by „proběhla" bez jediného příjemce.
  -- Prázdné publikum a NEEXISTUJÍCÍ sekce musí jít rozlišit.
  IF p_action = 'get_section_audience_user_ids' THEN
    v_sekce := NULLIF(p_payload ->> 'section', '');
    IF v_sekce IS NULL THEN
      RAISE EXCEPTION 'get_section_audience_user_ids: chybí `section`' USING errcode = '22023';
    END IF;

    SELECT s.audience INTO v_publikum
    FROM public.surface_sections s
    WHERE s.surface = v_sekce AND s.state = 'active';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'neznámá nebo neaktivní sekce: %', v_sekce USING errcode = '22023';
    END IF;

    -- Predikát je ze své podstaty PER UŽIVATELE (ptá se na vazby toho člověka),
    -- takže tady je per-row správně — je to semi-join nad uživateli, ne režie
    -- v RLS predikátu. Deklarace sekce se přitom načte JEDNOU, do proměnné.
    RETURN jsonb_build_object(
      'rows',
      COALESCE(
        (
          SELECT jsonb_agg(jsonb_build_object('user_id', p.user_id))
          FROM public.profiles p
          WHERE p.user_id IS NOT NULL
            AND public.surface_audience_allows(p.user_id, v_publikum)
        ),
        '[]'::jsonb
      )
    );
  END IF;

  IF p_action = 'get_campaigns' THEN
    RETURN jsonb_build_object(
      'rows',
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'audience_filter', c.audience_filter,
              'audience_type', c.audience_type,
              'base_locale', c.base_locale,
              'body_key', c.body_key,
              'data', c.data,
              'id', c.id,
              'is_active', c.is_active,
              'link', c.link,
              'name', c.name,
              'send_inapp', c.send_inapp,
              'send_push', c.send_push,
              'title_key', c.title_key
            )
          )
          FROM public.notification_campaigns c
          WHERE c.id = ANY(
            COALESCE(
              (
                SELECT array_agg(value::uuid)
                FROM jsonb_array_elements_text(COALESCE(p_payload -> 'campaign_ids', '[]'::jsonb)) AS t(value)
              ),
              ARRAY[]::uuid[]
            )
          )
            AND c.is_active = true
        ),
        '[]'::jsonb
      )
    );
  END IF;

  IF p_action = 'get_due_schedules' THEN
    RETURN jsonb_build_object(
      'rows',
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'campaign_id', s.campaign_id,
              'id', s.id,
              'next_run_at', s.next_run_at,
              'repeat_interval_minutes', s.repeat_interval_minutes
            )
          )
          FROM public.notification_campaign_schedules s
          WHERE s.next_run_at <= COALESCE(NULLIF(p_payload ->> 'now', '')::timestamptz, now())
            AND s.status = 'scheduled'
        ),
        '[]'::jsonb
      )
    );
  END IF;

  IF p_action = 'insert_run' THEN
    INSERT INTO public.notification_campaign_runs (
      campaign_id,
      errors,
      inapp_sent,
      push_sent,
      recipients_count,
      run_at,
      schedule_id,
      status
    )
    VALUES (
      NULLIF(p_payload ->> 'campaign_id', '')::uuid,
      CASE WHEN p_payload ? 'errors' THEN p_payload -> 'errors' ELSE NULL END,
      COALESCE(NULLIF(p_payload ->> 'inapp_sent', '')::integer, 0),
      COALESCE(NULLIF(p_payload ->> 'push_sent', '')::integer, 0),
      COALESCE(NULLIF(p_payload ->> 'recipients_count', '')::integer, 0),
      COALESCE(NULLIF(p_payload ->> 'run_at', '')::timestamptz, now()),
      NULLIF(p_payload ->> 'schedule_id', '')::uuid,
      COALESCE(NULLIF(p_payload ->> 'status', ''), 'sent')
    )
    RETURNING id INTO v_id;

    RETURN jsonb_build_object('id', v_id, 'ok', true);
  END IF;

  IF p_action = 'update_schedule' THEN
    UPDATE public.notification_campaign_schedules
    SET
      last_run_at = CASE WHEN p_payload ? 'last_run_at' THEN NULLIF(p_payload ->> 'last_run_at', '')::timestamptz ELSE last_run_at END,
      next_run_at = CASE WHEN p_payload ? 'next_run_at' THEN NULLIF(p_payload ->> 'next_run_at', '')::timestamptz ELSE next_run_at END,
      status = COALESCE(NULLIF(p_payload ->> 'status', ''), status),
      updated_at = now()
    WHERE id = NULLIF(p_payload ->> 'schedule_id', '')::uuid;

    RETURN jsonb_build_object('ok', true, 'updated', FOUND);
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$function$;

REVOKE ALL ON FUNCTION public.edge_notification_campaigns(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edge_notification_campaigns(text, jsonb) TO service_role;
-- ⛔ `authenticated` grant ZRUŠEN 2026-09-21. Změřeno: jediný volající je worker
-- svc-push pod service_role; administrace má vlastní `*_admin` funkce
-- (get_notification_campaigns_admin a spol.) a tuhle nevolá, plocha ani mobil
-- taky ne. Grant byl vnější dveře, které stály otevřené u funkce bez stráže.
REVOKE EXECUTE ON FUNCTION public.edge_notification_campaigns(text, jsonb) FROM authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/surface_client_params_filter.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: surface_client_params_filter
-- Popis: KONTRAKT KLIENTSKÝCH PARAMETRŮ restricted bloku (ADR-003, program K3).
--   Z parametrů volajícího propustí JEN klíče, které konfigurace bloku výslovně
--   deklaruje v `source_params.client_params`, jejichž hodnota projde
--   deklarovaným typem, a které NEKOLIDUJÍ s klíčem konfigurace.
--
-- PROČ: W4 (2026-09-03) správně zavřel díru U4-5 — restricted blok nebral
-- parametry klienta vůbec, protože `columns` nebo `view` od klienta by nad
-- definer zdrojem (běží pod právy vlastníka) znamenaly čtení libovolných
-- sloupců napříč RLS.
-- Jenže tím zmizela i legální cesta pro detail záznamu (`twin_id`), hledání
-- (`q`) a osu pohledu (`cohort_id`). Jediný způsob, jak parametr protlačit,
-- bylo označit blok `internal` — obcházení, ne návrh. Tohle je návrh:
--   · deklarace je DATA (řádek bloku v overlayi), ne kód;
--   · typ se ověřuje (uuid, text ≤200, date, timestamptz, int, bool, enum);
--   · konfigurace zůstává AUTORITATIVNÍ — deklarovaný klíč, který už
--     konfigurace nese, se nepropustí nikdy (klient si `view` nepřepíše, ani
--     kdyby ho instance omylem deklarovala);
--   · nedeklarovaný nebo neplatný klíč se tiše zahodí — blok vrátí to, co
--     vydá konfigurace sama (poctivá degradace, žádná výjimka).
--
-- Tvar deklarace:
--   "client_params": {"twin_id":"uuid", "q":"text", "since":"date",
--                     "tier":{"enum":["registered","active"]}, "n":"int", "flag":"bool"}
--
-- ⭐ OBJEKTOVÁ DEKLARACE (2026-09-29, ovladače v extranetu). Tentýž parametr smí nést
-- i to, jak ho má shell NABÍDNOUT — popisek, druh ovladače, popisky hodnot:
--   "mesic":     {"type":"date", "ui":"month", "label_key":"…"}
--   "min_days":  {"type":"int", "ui":"toggle", "on":365, "label_key":"…"}
--   "jen_tridy": {"enum":["N","E","P"], "multi":true, "label_key":"…", "value_label_prefix":"…"}
-- Typ se u objektu čte z `type` (nebo z `enum`); UI klíče tu nic neznamenají — shell
-- je dostane přes get_surface_layout_ui. `multi` = pole řetězců, každý z výčtu (1–50).
-- Řetězcová deklarace platí beze změny.
--
-- IMMUTABLE: čistá funkce svých argumentů, nic nečte. INVOKER: nemá co obcházet.
-- (Pozn. pro analyzátor bran: v komentáři záměrně není literál definer velkými
-- písmeny — security.gate čte soubory textově a vzal by ho za deklaraci
-- funkce bez autorizace.)
-- ============================================================================
CREATE OR REPLACE FUNCTION public.surface_client_params_filter(p_source_params jsonb, p_client jsonb)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  SELECT coalesce(jsonb_object_agg(d.key, c.value), '{}'::jsonb)
  FROM jsonb_each(
         CASE WHEN jsonb_typeof(p_source_params->'client_params') = 'object'
              THEN p_source_params->'client_params' ELSE '{}'::jsonb END) AS d(key, spec)
  -- Typ parametru: řetězcová deklarace JE typ; objektová ho nese v `type`.
  CROSS JOIN LATERAL (
    SELECT CASE WHEN jsonb_typeof(d.spec) = 'object' THEN d.spec->>'type' ELSE d.spec #>> '{}' END AS ty
  ) AS t
  JOIN jsonb_each(coalesce(p_client, '{}'::jsonb)) AS c(key, value) ON c.key = d.key
  WHERE d.key <> 'client_params'
    -- konfigurace je autoritativní: klíč, který konfigurace nese, klient nepřepíše
    AND NOT ((coalesce(p_source_params, '{}'::jsonb) - 'client_params') ? d.key)
    AND (
      CASE
        WHEN jsonb_typeof(d.spec) = 'object' AND d.spec ? 'enum' AND d.spec->'multi' = 'true'::jsonb
          THEN jsonb_typeof(c.value) = 'array'
           AND jsonb_array_length(c.value) BETWEEN 1 AND 50
           AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(c.value) AS e(v)
                            WHERE jsonb_typeof(e.v) <> 'string' OR NOT (d.spec->'enum') ? (e.v #>> '{}'))
        WHEN jsonb_typeof(d.spec) = 'object' AND d.spec ? 'enum'
          THEN jsonb_typeof(c.value) = 'string' AND (d.spec->'enum') ? (c.value #>> '{}')
        WHEN t.ty = 'uuid'
          THEN jsonb_typeof(c.value) = 'string'
           AND (c.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        WHEN t.ty = 'text'
          THEN jsonb_typeof(c.value) = 'string'
           AND length(c.value #>> '{}') BETWEEN 1 AND 200
        WHEN t.ty = 'date'
          THEN jsonb_typeof(c.value) = 'string'
           AND (c.value #>> '{}') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        WHEN t.ty = 'timestamptz'
          THEN jsonb_typeof(c.value) = 'string'
           AND (c.value #>> '{}') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}'
        WHEN t.ty = 'int'
          THEN (jsonb_typeof(c.value) = 'number' AND (c.value #>> '{}') ~ '^-?[0-9]+$')
            OR (jsonb_typeof(c.value) = 'string' AND (c.value #>> '{}') ~ '^-?[0-9]{1,9}$')
        WHEN t.ty = 'bool'
          THEN jsonb_typeof(c.value) = 'boolean'
        ELSE false
      END);
$$;

REVOKE ALL ON FUNCTION public.surface_client_params_filter(jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.surface_client_params_filter(jsonb, jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_block_data.sql
-- -----------------------------------------------------------------------------

-- Dispatcher: zavolá datové RPC konfigurované v bloku, VÝHRADNĚ přes allowlist
-- surface_data_rpcs (format %I — žádný passthrough libovolného jména). SECURITY INVOKER:
-- blok i cílové RPC běží pod právy volajícího (RLS rozhoduje).

create or replace function public.get_block_data(
  p_block_slug text,
  p_params     jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_block  public.surface_blocks%rowtype;
  v_result jsonb;
begin
  select * into v_block
  from public.surface_blocks
  where block_slug = p_block_slug
    and is_active;
  if not found then
    raise exception 'unknown or inactive block' using errcode = 'P0002';
  end if;

  -- allowlist gate (běhová pojistka nad FK): RPC musí být aktivní řádek allowlistu
  perform 1 from public.surface_data_rpcs
   where rpc_name = v_block.source_rpc and is_active;
  if not found then
    raise exception 'data rpc not allowlisted' using errcode = '42501';
  end if;

  -- ⛔ PUBLIKUM JE HRANICE DAT, NE JEN VÝPISU (naměřeno 2026-09-03, audit U4-5).
  -- `audience` v surface_layouts dosud hlídalo jen list_surface_sections;
  -- sem se dalo přijít rovnou se slugem bloku a data dostat, i když sekce
  -- byla jen pro admin/staff. Blok, který volající nesmí VIDĚT, nesmí ani
  -- ČÍST: musí existovat aktivní umístění, jehož publikum ho pustí. Blok bez
  -- umístění nemá koho pustit — proto nic (service role je výjimka: seedy
  -- a doktor blok čtou bez sekce).
  if not public.is_service_role() then
    perform 1
      from public.surface_layouts l
     where l.block_id = v_block.id
       and l.is_active
       and public.surface_audience_allows(auth.uid(), coalesce(l.audience, '{}'::jsonb));
    if not found then
      raise exception 'block not available to caller' using errcode = '42501';
    end if;
  end if;

  -- Klient smí konfiguraci DOPLNIT — kalendář nad frontou to potřebuje
  -- (absolutní den přebíjí `due='today'`, viz heals 2026-08-05). U bloku
  -- s citlivostí `restricted` je ale konfigurace autoritativní: `columns`
  -- a `event_type` od klienta by nad SECURITY DEFINER zdrojem znamenaly
  -- čtení libovolných sloupců napříč RLS (W4, audit U4-5).
  --
  -- ⭐ KONTRAKT KLIENTSKÝCH PARAMETRŮ (ADR-003 K3, 2026-09-05). Restricted blok
  -- bere od klienta JEN klíče, které jeho konfigurace výslovně deklaruje
  -- v `source_params.client_params` (typ ověřen, kolize s konfigurací
  -- zahozena) — surface_client_params_filter. Tím dostal detail záznamu,
  -- hledání a osa pohledu legální cestu; do té doby šlo parametr protlačit
  -- jen snížením citlivosti bloku, což bylo obcházení, ne návrh.
  -- Samotná deklarace se RPC nepředává (není to parametr dotazu).
  execute format('select public.%I($1)', v_block.source_rpc)
    into v_result
    using case
      when v_block.sensitivity = 'restricted'
        then (coalesce(v_block.source_params, '{}'::jsonb) - 'client_params')
             || public.surface_client_params_filter(v_block.source_params, p_params)
      else (coalesce(v_block.source_params, '{}'::jsonb) - 'client_params')
             || coalesce(p_params, '{}'::jsonb)
    end;

  if v_result is null then
    raise exception 'data rpc returned null' using errcode = 'P0002';
  end if;

  -- Obálka bloku: kontraktní pole doplní hodnoty z definice (data + provenance dodává RPC).
  return v_result || jsonb_build_object(
    'schema_version', v_block.schema_version,
    'block_slug',     v_block.block_slug,
    'block_type',     v_block.block_type,
    'title_key',      v_block.title_key,
    'sensitivity',    v_block.sensitivity
  );
end;
$$;

-- Kontrakt na cílová RPC (dokumentační): přijímají jsonb, vracejí jsonb s poli
-- 'data' a 'provenance' {source_slug, freshness_at, trace_id}; SECURITY INVOKER; RLS-safe.

-- Grants: authenticated + service_role (NOT anon, #566 floor); RLS on the underlying
-- tables is the real access boundary (SECURITY INVOKER — runs as the caller).
REVOKE ALL ON FUNCTION public.get_block_data(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_block_data(text, jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/surface_presence_ok.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: surface_presence_ok
-- Popis: Vyhodnotí SONDU DAT sekce (surface_sections.presence) pro volajícího:
--        má v sekci pro něj něco být? list_surface_sections podle ní skryje
--        běžnému uživateli sekci, ve které nic nemá (rozhodnutí majitele
--        2026-09-28: „není potřeba, aby danou sekci viděl, byť do ní má přístup").
--
-- Druhy sondy (uzavřený seznam, jako osy publika):
--   {"doklady": ["contract", "invoice"]} — existuje aspoň jeden PLATNÝ doklad
--       těch typů, který volající vidí (SECURITY INVOKER → rozhoduje RLS
--       li_source_registry_read, tedy i nárok z vazeb).
--
-- ⛔ Sonda NENÍ hranice přístupu (tu drží publikum a RLS). Neznámý druh nebo
--   chybný tvar proto sekci NESKRYJE — vrátí true a zapíše WARNING do logu DB;
--   tichá chyba by jinak vypadala jako „nemáte data".
-- ============================================================================

CREATE OR REPLACE FUNCTION public.surface_presence_ok(p_presence jsonb)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_typy text[];
BEGIN
  IF p_presence IS NULL OR p_presence = '{}'::jsonb THEN
    RETURN true;
  END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(p_presence)) <> 1
     OR NOT (p_presence ? 'doklady')
     OR jsonb_typeof(p_presence->'doklady') <> 'array' THEN
    RAISE WARNING 'surface_presence_ok: neznámá sonda %, sekce se neskrývá', p_presence;
    RETURN true;
  END IF;
  v_typy := ARRAY(SELECT jsonb_array_elements_text(p_presence->'doklady'));
  RETURN EXISTS (
    SELECT 1 FROM public.li_source_registry d
     WHERE d.superseded_by IS NULL AND d.doc_type = ANY (v_typy)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.surface_presence_ok(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.surface_presence_ok(jsonb) TO authenticated, service_role;

COMMENT ON FUNCTION public.surface_presence_ok(jsonb) IS
  'Sonda dat sekce pro volajícího (INVOKER, pod RLS): {"doklady":[typy]} = vidí aspoň jeden platný doklad těch typů. Není hranice přístupu; neznámá sonda sekci neskryje.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/list_surface_sections.sql
-- -----------------------------------------------------------------------------

-- Sekce extranetu, které volající SMÍ vidět — SLOUČENÝ tvar navigace.
--
-- Sekce jsou DATA (surface_layouts.surface je otevřený text) — klient je tedy
-- musí OBJEVIT, ne znát. Tři prameny, v tomhle pořadí síly:
--
--   1. rozvržení (surface_layouts) — sekce s bloky; RLS default-deny rozhoduje,
--      kdo ji vidí (SECURITY INVOKER, viz níž)
--   2. šablona (surface_sections) — skupina, pořadí, ikona, klíč jména,
--      deklarované NEAKTIVNÍ sekce; publikum šablonové sekce hlídá
--      surface_audience_allows (rozvržení žádné nemá, RLS by ji neořezala)
--   3. override (surface_section_overrides) — co si zákazník přejmenoval
--      v administraci; efektivní hodnota = coalesce(override, šablona)
--
-- ⚠️ ZMĚNA ROZHODNUTÍ (2026-07-29): dřívější verze sekce bez bloků ZAMLČELA
-- („sekce, kde by se nevykreslilo nic, je v navigaci horší než žádná").
-- To platilo, dokud stavy byly dva. Třetí stav je lepší odpověď na týž
-- problém: sekce deklarovaná šablonou, ale bez napojeného zdroje, se vrací
-- jako state='inactive' s reason_key — viditelná, neklikatelná, s důvodem.
-- Skrýt ji tvrdí zákazníkovi, že to produkt neumí; prázdná aktivní vypadá
-- jako chyba. Sekce, kterou nedeklaruje ani rozvržení, ani šablona,
-- neexistuje pořád.
--
-- Tvar položky (aditivní vůči původnímu — staří klienti čtou section +
-- block_count a nové osy ignorují):
--   { section, block_count, title_key?, icon?, group_key?, group_order,
--     position, state: 'active'|'inactive', reason_key? }
--
-- SECURITY INVOKER: běží jako volající, takže o viditelnosti sekcí s bloky
-- rozhoduje RLS nad surface_layouts. Uživatel bez grantů dostane prázdné pole,
-- ne chybu — neprozrazovat existenci sekce, na kterou nemá nárok.

create or replace function public.list_surface_sections()
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with lay as (
    -- Číslo v navigaci = kolik bloků sekce VYKRESLÍ. Blok detailu stojí v sekci
    -- jen kvůli oprávnění (dispečer pustí jen umístěný blok) a kreslí se až po
    -- prokliku — `presentation:"detail"`, stejné pravidlo jako shell
    -- (PRESENTATION_DETAIL_ONLY). Řádek sekce zůstává i s nulou.
    select l.surface,
           count(*) filter (where coalesce(b.source_params->>'presentation', '') <> 'detail') as n
    from public.surface_layouts l
    join public.surface_blocks b on b.id = l.block_id and b.is_active
    where l.is_active
    group by l.surface
  ),
  tpl as (
    select s.surface, s.title_key, s.icon, s.group_key, s.group_order,
           s.position, s.state, s.reason_key, s.audience, s.presence
    from public.surface_sections s
    where s.is_active
  ),
  merged as (
    select
      coalesce(t.surface, l.surface)                            as surface,
      coalesce(l.n, 0)                                          as n,
      coalesce(o.title_key,  t.title_key)                       as title_key,
      coalesce(o.icon,       t.icon)                            as icon,
      coalesce(o.group_key,  t.group_key)                       as group_key,
      coalesce(o.group_order, t.group_order, 0)                 as group_order,
      coalesce(o.position,   t.position, 0)                     as position,
      -- Bez bloků není co otevřít, ať šablona tvrdí cokoli — proto se stav
      -- 'inactive' vynucuje i tehdy, když by deklarace říkala 'active'.
      case when coalesce(l.n, 0) = 0 then 'inactive'
           else coalesce(o.state, t.state, 'active') end        as state,
      coalesce(o.reason_key, t.reason_key)                      as reason_key,
      t.audience                                                as audience,
      t.presence                                                as presence
    from tpl t
    full outer join lay l on l.surface = t.surface
    left join public.surface_section_overrides o on o.surface = coalesce(t.surface, l.surface)
  )
  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object(
        'section',     m.surface,
        'block_count', m.n,
        'title_key',   m.title_key,
        'icon',        m.icon,
        'group_key',   m.group_key,
        'group_order', m.group_order,
        'position',    m.position,
        'state',       m.state,
        'reason_key',  m.reason_key
      ))
      order by m.group_order, m.position, m.surface
    ),
    '[]'::jsonb
  )
  from merged m
  where
    (
      -- sekce s bloky: viditelnost už rozhodla RLS nad surface_layouts (INVOKER)
      m.n > 0
      -- šablonová (typicky neaktivní) sekce: publikum hlídá sdílený interpret;
      -- bez deklarace audience ({} default) ji vidí každý přihlášený
      or (m.audience is not null
          and public.surface_audience_allows(auth.uid(), m.audience))
    )
    -- ⭐ SONDA DAT (2026-09-28): běžný uživatel sekci, ve které pro něj nic
    -- není, nevidí, i když do ní přístup má. Správa vidí vždy.
    and (m.presence is null
         or public.is_admin_or_staff()
         or public.surface_presence_ok(m.presence));
$$;

-- Grants: authenticated + service_role (NOT anon, #566 floor); RLS na
-- surface_layouts je skutečná hranice přístupu (SECURITY INVOKER).
REVOKE ALL ON FUNCTION public.list_surface_sections() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.list_surface_sections() TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/surface_udeleni_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: surface_udeleni_admin
-- Popis: Pro správu v administraci u uživatele: udělitelné sekce extranetu
--        (aktivní umístění nebo šablona s osou publika "udeleni") a zda je
--        uživatel má udělené. Pořadí jako v navigaci.
-- Bezpečnost: SECURITY DEFINER; jen správa.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.surface_udeleni_admin(p_user_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: jen správa' USING ERRCODE = '42501';
  END IF;
  RETURN coalesce((
    WITH udelitelne AS (
      SELECT DISTINCT l.audience->>'udeleni' AS surface
        FROM public.surface_layouts l
       WHERE l.is_active AND l.audience ? 'udeleni'
      UNION
      SELECT s.audience->>'udeleni'
        FROM public.surface_sections s
       WHERE s.is_active AND s.audience ? 'udeleni'
    )
    SELECT jsonb_agg(jsonb_build_object(
             'surface',    u.surface,
             'title_key',  s.title_key,
             'udeleno',    g.user_id IS NOT NULL,
             'granted_at', g.granted_at)
           ORDER BY coalesce(s.group_order, 0), coalesce(s.position, 0), u.surface)
      FROM udelitelne u
      LEFT JOIN public.surface_sections s ON s.surface = u.surface
      LEFT JOIN public.surface_section_grants g ON g.surface = u.surface AND g.user_id = p_user_id
     WHERE u.surface ~ '^[a-z][a-z0-9_]*$'
  ), '[]'::jsonb);
END;
$$;

REVOKE ALL ON FUNCTION public.surface_udeleni_admin(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.surface_udeleni_admin(uuid) TO authenticated, service_role;

COMMENT ON FUNCTION public.surface_udeleni_admin(uuid) IS
  'Správa: udělitelné sekce extranetu a stav udělení pro uživatele (administrace u uživatele).';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/sync_checkin_to_metrics.sql
-- -----------------------------------------------------------------------------

-- Function: public.sync_checkin_to_metrics
-- Description: Trigger function to sync health_check_ins to health_metrics
-- Security: SECURITY DEFINER (trigger function)
-- sensitive data: Yes - copies health data between tables

CREATE OR REPLACE FUNCTION public.sync_checkin_to_metrics()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
BEGIN
  -- Only sync if we have relevant metrics
  IF NEW.energy_level IS NOT NULL 
     OR NEW.mood_level IS NOT NULL 
     OR NEW.pain_level IS NOT NULL 
     OR NEW.sleep_quality IS NOT NULL THEN
    
    INSERT INTO health_metrics (
      user_id,
      study_registration_id,
      measured_at,
      energy_level,
      mental_state,  -- mood_level maps to mental_state
      pain_level,
      sleep_quality,
      source,
      source_id
    ) VALUES (
      NEW.user_id,
      NEW.study_registration_id,
      COALESCE(NEW.check_in_date::TIMESTAMPTZ, NEW.created_at),
      NEW.energy_level,
      NEW.mood_level,
      NEW.pain_level,
      NEW.sleep_quality,
      'check_in',
      NEW.id
    );
  END IF;

  RETURN NEW;
END;
$$;

-- Create trigger (idempotent)
DROP TRIGGER IF EXISTS sync_health_metrics_trigger ON health_check_ins;

CREATE TRIGGER sync_health_metrics_trigger
AFTER INSERT ON health_check_ins
FOR EACH ROW
EXECUTE FUNCTION sync_checkin_to_metrics();

-- Permissions - trigger function, not called directly via RPC
REVOKE ALL ON FUNCTION public.sync_checkin_to_metrics() FROM PUBLIC;

COMMENT ON FUNCTION public.sync_checkin_to_metrics() IS 'Automatically sync health check-in data to health_metrics table';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/sync_expert_rule_to_knowledge_item.sql
-- -----------------------------------------------------------------------------

-- Function: sync_expert_rule_to_knowledge_item

CREATE OR REPLACE FUNCTION public.sync_expert_rule_to_knowledge_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_author_name text;
  v_ki_id uuid;
BEGIN
  -- Get author display name
  SELECT display_name INTO v_author_name
  FROM partner_profiles WHERE id = NEW.author_partner_id;

  -- Upsert into knowledge_items
  INSERT INTO knowledge_items (
    item_type,
    source_type,
    source_id,
    source_slug,
    locale,
    title,
    summary,
    body_markdown,
    ai_instructions,
    ai_context_tags,
    category,
    expertise_area_id,
    status,
    visibility,
    version,
    author_id,
    author_display_name,
    usage_count,
    rating_avg,
    is_verified,
    published_at,
    created_at,
    updated_at
  ) VALUES (
    'expert_rule',
    'guild_db',
    NEW.id,
    NEW.slug,
    'global',  -- expert rules are language-agnostic; the locale-widened unique needs a value
    NEW.title,
    NEW.summary,
    NEW.body_markdown,
    NEW.ai_instructions,
    NEW.ai_context_tags,
    NEW.category::text,
    NEW.expertise_area_id,
    CASE WHEN NEW.status = 'published' THEN 'active' ELSE 'pending_review' END,
    NEW.visibility,
    NEW.version,
    NEW.author_partner_id,
    v_author_name,
    NEW.usage_count,
    NEW.rating_avg,
    NEW.is_verified,
    NEW.published_at,
    NEW.created_at,
    NEW.updated_at
  )
  -- Brick4 widened idx_knowledge_items_source_unique to (source_type, source_id,
  -- locale); the conflict target must match it (the 2-col target lost its backing
  -- index, which silently broke this upsert).
  ON CONFLICT (source_type, source_id, locale) WHERE source_type = 'guild_db'
  DO UPDATE SET
    source_slug = EXCLUDED.source_slug,
    title = EXCLUDED.title,
    summary = EXCLUDED.summary,
    body_markdown = EXCLUDED.body_markdown,
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    category = EXCLUDED.category,
    expertise_area_id = EXCLUDED.expertise_area_id,
    status = EXCLUDED.status,
    visibility = EXCLUDED.visibility,
    version = EXCLUDED.version,
    author_display_name = EXCLUDED.author_display_name,
    usage_count = EXCLUDED.usage_count,
    rating_avg = EXCLUDED.rating_avg,
    is_verified = EXCLUDED.is_verified,
    published_at = EXCLUDED.published_at,
    updated_at = now();

  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION sync_expert_rule_to_knowledge_item() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION sync_expert_rule_to_knowledge_item() TO PUBLIC;
GRANT EXECUTE ON FUNCTION sync_expert_rule_to_knowledge_item() TO authenticated;
GRANT EXECUTE ON FUNCTION sync_expert_rule_to_knowledge_item() TO service_role;


