 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.link IS NOT NULL AND NEW.action_url IS NULL THEN
    NEW.action_url := NEW.link;
  ELSIF NEW.action_url IS NOT NULL AND NEW.link IS NULL THEN
    NEW.link := NEW.action_url;
  END IF;
  RETURN NEW;
END;
$function$
;

