-- =============================================================================
-- transition_plugin_status(p_plugin_id, p_new_status, p_metadata)
-- =============================================================================
-- State machine for plugin lifecycle transitions.
-- Validates against plugin_transition_rules, checks role requirement,
-- updates status, logs to plugin_audit_events.
-- Pattern: identical to transition_story_delivery_status.
-- =============================================================================

CREATE OR REPLACE FUNCTION public.transition_plugin_status(
  p_metadata    jsonb DEFAULT '{}'::jsonb,
  p_new_status  text DEFAULT NULL,
  p_plugin_id   uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_current_status  public.plugin_status;
  v_target_status   public.plugin_status;
  v_requires_role   text;
  v_user_id         uuid := auth.uid();
  v_slug            text;
  v_kind            public.plugin_kind;
BEGIN
  IF p_plugin_id IS NULL OR p_new_status IS NULL THEN
    RAISE EXCEPTION 'p_plugin_id and p_new_status are required';
  END IF;

  v_target_status := p_new_status::public.plugin_status;

  -- Lock and get current status
  SELECT status, slug, kind INTO v_current_status, v_slug, v_kind
  FROM public.plugin_catalog
  WHERE id = p_plugin_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Plugin % not found', p_plugin_id;
  END IF;

  -- Validate transition against rules
  SELECT ptr.requires_role INTO v_requires_role
  FROM public.plugin_transition_rules ptr
  WHERE ptr.from_status = v_current_status
    AND ptr.to_status = v_target_status;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', format('Transition %s → %s not allowed', v_current_status, v_target_status)
    );
  END IF;

  -- Check role requirement
  IF v_requires_role = 'admin' AND NOT public.is_admin_or_staff() THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Admin role required for this transition'
    );
  END IF;

  IF v_requires_role = 'staff' AND NOT public.is_admin_or_staff() THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Staff role required for this transition'
    );
  END IF;

  -- Execute transition
  UPDATE public.plugin_catalog
  SET status = v_target_status, updated_at = now()
  WHERE id = p_plugin_id;

  -- Keep the agent runtime (agent_catalog) in sync with the plugin lifecycle:
  -- disabled/archived → de-provision (kill-switch); canary/ga → (re)materialize.
  -- Both are idempotent and a no-op for non-agents / executable agents.
  -- EVERY kind materializes/deactivates through the dispatchers — "approved
  -- manifest ⇒ resolver-visible registry row" holds for the whole surface,
  -- not just agents (plugin-kind-has-materializer doctrine, 2026-07-26).
  IF v_target_status IN ('disabled'::public.plugin_status, 'archived'::public.plugin_status) THEN
    PERFORM public.deactivate_plugin_runtime(p_plugin_id);
  ELSIF v_target_status IN ('canary'::public.plugin_status, 'ga'::public.plugin_status) THEN
    PERFORM public.materialize_plugin(p_plugin_id);
  END IF;

  -- Audit log
  INSERT INTO public.plugin_audit_events (plugin_id, actor_id, action, metadata)
  VALUES (
    p_plugin_id, v_user_id,
    'PLUGIN_STATUS_CHANGE',
    jsonb_build_object(
      'from_status', v_current_status::text,
      'to_status', v_target_status::text,
      'slug', v_slug
    ) || COALESCE(p_metadata, '{}'::jsonb)
  );

  RETURN jsonb_build_object(
    'success', true,
    'plugin_id', p_plugin_id,
    'slug', v_slug,
    'from_status', v_current_status::text,
    'to_status', v_target_status::text
  );
END;
$$;

COMMENT ON FUNCTION public.transition_plugin_status(jsonb, text, uuid) IS
  'State machine transition for plugin status. Validates rules + role, logs audit.';

REVOKE ALL ON FUNCTION public.transition_plugin_status(jsonb, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.transition_plugin_status(jsonb, text, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/approve_internal_plugin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: approve_internal_plugin
-- Popis: Správce schválí NÁŠ VLASTNÍ plugin (trust_tier `internal`) do provozu
--        jedním úkonem — stavový automat se projde až do `canary`.
--
-- ⛔ PROČ VZNIKÁ (naměřeno 2026-09-26 v produkci instance): zdroje
-- `webdispecink-fleet` a `tcars-fleet` jsou aktivní, pověření vyplněná — a ani
-- jeden nikdy nestahoval. Oba pluginy byly člověkem posunuté až do `ga`
-- (2026-09-07 i 2026-09-20), ale další nasazení s novým kódem je vrátilo na
-- `submitted`. To je SPRÁVNĚ (`submit_plugin`: schválení drží jen shodný otisk
-- artefaktu — pod schváleným pluginem nesmí běžet jiný kód), jenže znovu
-- schválit nebylo kde: `transition_plugin_status` nevolá žádné UI ani služba,
-- fronta moderace pluginy nenese. Pojistka „stroj navrhne, člověk zapne" tak
-- měla jen první půlku — a z pojistky se stala trvalá zeď.
--
-- ⭐ JEN `internal`. Interní plugin staví a publikuje NAŠE CI z našeho repa
-- (`submit_plugin` ho strojem jinak než jako internal podat neumí) a jeho kód
-- prošel branami PR. Sandbox test ze stavového automatu (`sandbox_testing →
-- approved`, v pravidlech „auto po průchodu sandboxem") tu nahrazuje právě tohle
-- — a metadata každého kroku to říkají nahlas. Partner a external dál vyžadují
-- skutečné přezkoumání přes `transition_plugin_status` krok po kroku.
--
-- ⭐ KAŽDÝ KROK JDE PŘES `transition_plugin_status`. Pravidla přechodů
-- (`plugin_transition_rules`), role, materializace a audit zůstávají JEDINÝM
-- domovem — tady se jen volají za sebou v jedné transakci. Odmítne-li automat
-- kterýkoli krok, spadne celé schválení (nic napůl).
--
-- ⭐ Schvaluje se KONKRÉTNÍ artefakt: do metadat každého kroku jde verze
-- a otisk nejnovějšího artefaktu, takže audit říká, CO přesně správce pustil.
-- Když nasazení přinese jiný kód, `submit_plugin` plugin vrátí na `submitted`
-- a stav zdrojů (`get_data_source_feed_health_block`) ukáže „neschváleno".
--
-- Idempotentní: `canary`/`ga` = nic se nemění (`zmena: false`). Vypnutý nebo
-- archivovaný plugin se tudy NEschvaluje — vypnutí je vědomé rozhodnutí a jeho
-- zrušení patří do přezkoumání (`disabled → reviewing`), ne do jednoho kliknutí.
--
-- Bezpečnost: SECURITY DEFINER + stráž `is_admin_or_staff()` (automat by ji
-- stejně vynutil u každého kroku; tady je dřív, aby cizí volající nezjistil
-- ani existenci pluginu). Volá se z plochy přes `surface_actions`.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.approve_internal_plugin(p_plugin_slug text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  c_cesta    CONSTANT text[] := ARRAY['reviewing', 'sandbox_testing', 'approved', 'canary'];
  v_id       uuid;
  v_status   public.plugin_status;
  v_tier     public.plugin_trust_tier;
  v_version  text;
  v_sha      text;
  v_krok     text;
  v_vysledek jsonb;
  v_kroky    jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'approve_internal_plugin: jen správa (admin/staff)' USING ERRCODE = '42501';
  END IF;

  IF p_plugin_slug IS NULL OR btrim(p_plugin_slug) = '' THEN
    RAISE EXCEPTION 'approve_internal_plugin: chybí slug pluginu' USING ERRCODE = '22023';
  END IF;

  SELECT pc.id, pc.status, pc.trust_tier
    INTO v_id, v_status, v_tier
    FROM public.plugin_catalog pc
   WHERE pc.slug = p_plugin_slug
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'approve_internal_plugin: plugin % není v katalogu', p_plugin_slug USING ERRCODE = '22023';
  END IF;

  IF v_tier IS DISTINCT FROM 'internal'::public.plugin_trust_tier THEN
    RAISE EXCEPTION 'approve_internal_plugin: plugin % má důvěru %, jedním úkonem se schvaluje jen internal — projděte přezkoumání krok po kroku',
      p_plugin_slug, v_tier USING ERRCODE = '42501';
  END IF;

  IF v_status IN ('canary'::public.plugin_status, 'ga'::public.plugin_status) THEN
    RETURN jsonb_build_object('ok', true, 'slug', p_plugin_slug, 'status', v_status::text,
                              'zmena', false, 'kroky', '[]'::jsonb);
  END IF;

  IF v_status IN ('disabled'::public.plugin_status, 'archived'::public.plugin_status) THEN
    RAISE EXCEPTION 'approve_internal_plugin: plugin % je %, vypnutí se ruší přezkoumáním (disabled → reviewing), ne jedním kliknutím',
      p_plugin_slug, v_status USING ERRCODE = '22023';
  END IF;

  SELECT pv.version, pv.artifact_sha256
    INTO v_version, v_sha
    FROM public.plugin_versions pv
   WHERE pv.plugin_id = v_id
   ORDER BY pv.created_at DESC
   LIMIT 1;
  IF v_sha IS NULL THEN
    RAISE EXCEPTION 'approve_internal_plugin: plugin % nemá artefakt — není co schválit', p_plugin_slug USING ERRCODE = '22023';
  END IF;

  FOREACH v_krok IN ARRAY c_cesta LOOP
    -- Stav, který už je na cestě za tímhle krokem, se přeskočí (submitted na
    -- cestě není → array_position NULL → projde se od začátku).
    IF array_position(c_cesta, v_status::text) >= array_position(c_cesta, v_krok) THEN
      CONTINUE;
    END IF;
    v_vysledek := public.transition_plugin_status(
      p_metadata   => jsonb_build_object(
                        'via', 'approve_internal_plugin',
                        'version', v_version,
                        'artifact_sha256', v_sha,
                        'sandbox', 'internal: kód z CI vlastního repa místo sandbox testu'),
      p_new_status => v_krok,
      p_plugin_id  => v_id);
    IF NOT coalesce((v_vysledek->>'success')::boolean, false) THEN
      RAISE EXCEPTION 'approve_internal_plugin: krok → % odmítnut: %', v_krok, coalesce(v_vysledek->>'error', v_vysledek::text)
        USING ERRCODE = '42501';
    END IF;
    v_kroky := v_kroky || to_jsonb(v_krok);
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'slug', p_plugin_slug, 'status', 'canary', 'zmena', true,
                            'kroky', v_kroky, 'version', v_version, 'artifact_sha256', v_sha);
END;
$$;

COMMENT ON FUNCTION public.approve_internal_plugin(text) IS
  'Admin/staff: approve OUR OWN (trust_tier internal) plugin into production in one action — walks transition_plugin_status up to canary, audit per step with the approved artifact hash. Idempotent; refuses partner/external and disabled/archived.';

REVOKE ALL ON FUNCTION public.approve_internal_plugin(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.approve_internal_plugin(text) FROM anon;
GRANT EXECUTE ON FUNCTION public.approve_internal_plugin(text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/transition_story_delivery_status.sql
-- -----------------------------------------------------------------------------

-- Function: transition_story_delivery_status

CREATE OR REPLACE FUNCTION public.transition_story_delivery_status(p_story_id uuid, p_new_status text, p_trigger_source text DEFAULT 'manual'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_current_status text;
  v_transition_rule RECORD;
  v_user_id uuid := auth.uid();
  v_transition_id uuid;
BEGIN
  -- 0. Stráž (can_access_story.sql) — PŘED dohledáním, ať cizí a neexistující story vypadají stejně.
  IF NOT public.can_access_story(p_story_id, true) THEN
    RAISE EXCEPTION 'Access denied to story %', p_story_id USING ERRCODE = '42501';
  END IF;

  -- 1. Get current delivery_status
  SELECT delivery_status INTO v_current_status
  FROM partner_stories
  WHERE id = p_story_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Story not found: %', p_story_id USING ERRCODE = 'P0002';
  END IF;

  -- 2. Check if transition is allowed
  SELECT * INTO v_transition_rule
  FROM delivery_transition_rules
  WHERE is_active = true
    AND (from_status IS NOT DISTINCT FROM v_current_status)
    AND to_status = p_new_status;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', format('Transition from %s to %s is not allowed',
        COALESCE(v_current_status, 'NULL'), p_new_status),
      'current_status', v_current_status
    );
  END IF;

  -- 3. Check role requirement
  IF v_transition_rule.requires_role IS NOT NULL THEN
    IF NOT is_admin_or_staff() THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', format('Transition to %s requires role: %s', p_new_status, v_transition_rule.requires_role),
        'current_status', v_current_status
      );
    END IF;
  END IF;

  -- 4. Update delivery_status
  UPDATE partner_stories
  SET delivery_status = p_new_status,
      updated_at = now()
  WHERE id = p_story_id;

  -- 5. Record transition
  INSERT INTO delivery_transitions (story_id, from_status, to_status, triggered_by, trigger_source, metadata)
  VALUES (p_story_id, v_current_status, p_new_status, v_user_id, p_trigger_source, p_metadata)
  RETURNING id INTO v_transition_id;

  -- 6. Audit
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    'DELIVERY_STATUS_TRANSITION',
    jsonb_build_object(
      'area', 'delivery',
      'severity', 'info',
      'story_id', p_story_id,
      'from_status', v_current_status,
      'to_status', p_new_status,
      'trigger_source', p_trigger_source,
      'transition_id', v_transition_id
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'transition_id', v_transition_id,
    'from_status', v_current_status,
    'to_status', p_new_status,
    'story_id', p_story_id
  );
END;
$function$;

REVOKE ALL ON FUNCTION transition_story_delivery_status(uuid, text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION transition_story_delivery_status(uuid,text,text,jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION transition_story_delivery_status(uuid,text,text,jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/trg_update_training_dataset_counts.sql
-- -----------------------------------------------------------------------------

-- Function: trg_update_training_dataset_counts
-- Trigger function: maintains record_count and validated_count on training_datasets
-- Triggered by: INSERT, UPDATE (is_validated), DELETE on training_examples

CREATE OR REPLACE FUNCTION public.trg_update_training_dataset_counts()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.training_datasets
    SET record_count = record_count + 1,
        validated_count = validated_count + CASE WHEN NEW.is_validated THEN 1 ELSE 0 END,
        updated_at = now()
    WHERE id = NEW.dataset_id;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.training_datasets
    SET record_count = GREATEST(record_count - 1, 0),
        validated_count = GREATEST(validated_count - CASE WHEN OLD.is_validated THEN 1 ELSE 0 END, 0),
        updated_at = now()
    WHERE id = OLD.dataset_id;
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' AND OLD.is_validated IS DISTINCT FROM NEW.is_validated THEN
    UPDATE public.training_datasets
    SET validated_count = validated_count + CASE WHEN NEW.is_validated THEN 1 ELSE -1 END,
        updated_at = now()
    WHERE id = NEW.dataset_id;
    RETURN NEW;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;

REVOKE EXECUTE ON FUNCTION public.trg_update_training_dataset_counts() FROM PUBLIC;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/trigger_auto_create_story_on_registration.sql
-- -----------------------------------------------------------------------------

-- Function: trigger_auto_create_story_on_registration
-- Purpose: Auto-create a partner_stories row when member registration becomes active.
--          This ensures add_system_timeline_entry() has a target story and does not
--          silently skip entries with { success: false, reason: 'no_story' }.
-- Tables: study_registrations -> partner_stories
-- Security: SECURITY DEFINER (trigger context, no auth.uid())

CREATE OR REPLACE FUNCTION public.trigger_auto_create_story_on_registration()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_story_exists BOOLEAN;
  v_partner_id UUID;
  v_study_title TEXT;
  v_story_id UUID;
BEGIN
  -- Only fire when status changes to 'active'
  IF NOT (
    (TG_OP = 'INSERT' AND NEW.status = 'active')
    OR (TG_OP = 'UPDATE' AND NEW.status = 'active' AND OLD.status IS DISTINCT FROM NEW.status)
  ) THEN
    RETURN NEW;
  END IF;

  -- Check if story already exists for this user + study
  SELECT EXISTS (
    SELECT 1 FROM partner_stories
    WHERE user_id = NEW.user_id
      AND study_id = NEW.study_id
  ) INTO v_story_exists;

  IF v_story_exists THEN
    RETURN NEW;
  END IF;

  -- Get study title for the story name
  SELECT title INTO v_study_title
  FROM studies
  WHERE id = NEW.study_id;

  -- Resolve partner: prefer explicit consultant assignment, fallback to any approved
  -- consultant in the study with active consent from this member.
  -- (Mirrors create_story_audited partner resolution logic, lines 57-79)
  SELECT sc.partner_id
    INTO v_partner_id
  FROM study_consultants sc
  JOIN data_sharing_consents dsc
    ON dsc.user_id = NEW.user_id
   AND dsc.partner_id = sc.partner_id
   AND dsc.revoked_at IS NULL
   AND (dsc.expires_at IS NULL OR dsc.expires_at > now())
  WHERE sc.study_id = NEW.study_id
    AND sc.status = 'approved'
    AND (
      (NEW.consultant_id IS NOT NULL AND sc.id = NEW.consultant_id)
      OR NEW.consultant_id IS NULL
    )
  ORDER BY
    CASE WHEN NEW.consultant_id IS NOT NULL AND sc.id = NEW.consultant_id THEN 0 ELSE 1 END,
    sc.approved_at DESC NULLS LAST,
    sc.created_at DESC
  LIMIT 1;

  -- Skip story creation when no partner found (partner_id is NOT NULL in schema).
  -- The story will be created later when a partner is assigned or consent is granted.
  IF v_partner_id IS NULL THEN
    INSERT INTO audit_journal (user_id, action, metadata)
    VALUES (
      NEW.user_id,
      'STORY_AUTO_CREATE_SKIPPED',
      jsonb_build_object(
        'area', 'member_timeline',
        'severity', 'warning',
        'reason', 'no_partner_found',
        'study_id', NEW.study_id,
        'registration_id', NEW.id
      )
    );
    RETURN NEW;
  END IF;

  -- Create story with resolved partner
  INSERT INTO partner_stories (
    partner_id, user_id, study_id, title, status
  ) VALUES (
    v_partner_id,
    NEW.user_id,
    NEW.study_id,
    COALESCE(v_study_title, 'Timeline') || ' — ' || to_char(now(), 'YYYY-MM-DD'),
    'inbox'
  )
  RETURNING id INTO v_story_id;

  -- Audit log (no sensitive data - only IDs)
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    NEW.user_id,
    'STORY_AUTO_CREATED',
    jsonb_build_object(
      'area', 'member_timeline',
      'severity', 'info',
      'entity_type', 'partner_stories',
      'entity_id', v_story_id,
      'study_id', NEW.study_id,
      'partner_id', v_partner_id,
      'registration_id', NEW.id
    )
  );

  RETURN NEW;
END;
$$;

-- Permissions: Trigger function - prevent direct invocation
REVOKE ALL ON FUNCTION public.trigger_auto_create_story_on_registration() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.trigger_auto_create_story_on_registration() FROM anon;
-- Note: Triggers run with table owner privileges, not caller privileges


