        COALESCE(mhs.icon, '🩺')
      INTO v_state_name, v_state_icon
      FROM member_health_states mhs
      WHERE mhs.id = NEW.state_id;
    END IF;

    -- Add timeline entry (NO sensitive data: no severity value, no notes!)
