-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_accounts_missing.sql
-- -----------------------------------------------------------------------------

-- Function: public.twin_accounts_missing
-- Arguments: p_entity_type text, p_limit integer, p_hledat text
-- Security: SECURITY DEFINER, jen admin/staff nebo service_role (PII)
--
-- Pracovní seznam správce: KDO MÁ TWIN, ALE NEMÁ ÚČET.
--
-- ⭐ ZADÁNÍ MAJITELE (2026-09-10): „ingest má identifikovat, kdo by měl mít
-- účet, ale potřebujeme ho spřáhnout s tím twinem, aby viděl věci, co má."
-- Ingest tedy dodá OSOBU (twin + `primary_id` vazby na zdroje); tenhle seznam
-- říká, u koho ještě chybí druhá půlka — vazba na účet.
--
-- ⛔ ŽÁDNÁ NOVÁ ENTITA. Seznam je ODVOZENÝ, ne uložený: „nemá účet" je
-- nepřítomnost potvrzené `account` vazby, ne vlastnost k zapsání. Uložený
-- příznak by se rozešel s vazbami při prvním schválení mimo tuhle cestu.
--
-- ⛔ `entity_type` SE NEDOSAZUJE. Typy vznikají z dat (`twin_parameter_definitions`,
-- `metadata->>'ingest_field'`), ne z konstant v kódu — „parametry rozhodují,
-- čím entita je". Napsat sem `'driver'` natvrdo by znamenalo, že seznam
-- v instanci s jiným pojmenováním tiše vrátí prázdno. Filtr je proto parametr,
-- stejně jako u `twin_identity_list_unmatched`.
--
-- ⛔ TOHLE NENÍ DRUHÁ CESTA K ZÁPISU. Vazby navrhuje INGEST
-- (`twin-producer.ts` → `twin_identity_propose_binding`) a potvrzuje je člověk
-- v review lane (`get_twin_ref_review_block`). Tahle funkce jen ČTE — odpovídá
-- na otázku, kterou review lane neumí: ne „co čeká na potvrzení", ale „o kom
-- nikdo nenavrhl NIC". Bez toho se nedá rozhodnout, komu poslat pozvánku.
--
-- ⭐ TŘI ODPOVĚDI, NE JEDNA. Správce se u každé osoby rozhoduje mezi
-- „přiděl existující účet" a „pošli pozvánku" (zadání majitele 2026-09-10),
-- a k tomu potřebuje vědět, jestli se o to už někdo nepostaral:
--   · `refs`        — čím je člověk doložený ve zdrojích (kdo to je),
--   · `pozvanky`    — už se poslalo, čeká se na uplatnění,
--   · `navrhy_uctu` — ingest něco navrhl, chce to ratifikaci.
--
-- ⭐ VRACÍ I ZDROJOVÉ VAZBY. Bez nich se rozhodnout NEDÁ: `label` je jméno,
-- a jmen bývá víc stejných. Teprve `source_key` (osobní číslo, id ve
-- Webdispečinku) člověka jednoznačně určí.

--
-- ⭐ HLEDÁNÍ NA SERVERU + ÚKOLY (2026-09-23, HR obrazovka „Lidé a účty").
--   · `p_hledat` — řidičů je v instanci přes tisíc (1 479 twinů, 09-15) a strop
--     500 by seznam TIŠE uřízl: správce by hledal člověka, který „není", protože
--     je až za hranou. Hledá se ve jméně i v klíčích zdrojů (osobní číslo, id
--     ve Webdispečinku) — jmen bývá víc stejných, klíč je jednoznačný.
--   · `limitovano` — true, když za hranou další osoby jsou. „Našlo se 500" a
--     „našlo se všech 500" jsou dvě různé odpovědi a UI je musí rozlišit.
--   · `kroky` — kolik úkolů (lidských kroků workflow) nese twin jako
--     `authorized_twin_id`, a kolik z nich ČEKÁ. Podle toho správce pozná, který
--     z úlomků téhož člověka je ten „hlavní" (09-15: „KOŽUŠNÍK" 2 709 × „p.
--     Kožušník" 1). Počítá se přes funkční index `idx_pws_authorized_twin`
--     (výraz musí sedět PŘESNĚ — cast je na naší straně, ne na indexované).
--     Žádný kód kroku se NEDOSAZUJE: kroky jsou data šablony instance.
CREATE OR REPLACE FUNCTION public.twin_accounts_missing(
  p_entity_type text DEFAULT NULL,
  p_limit integer DEFAULT 100,
  p_hledat text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_items jsonb;
  v_limit int := GREATEST(1, LEAST(COALESCE(p_limit, 100), 500));
  v_limitovano boolean := false;
  -- Hledaný text jako TEXT, ne jako vzor-jazyk: `%` a `_` v zadání jsou znaky.
  v_vzor text := CASE WHEN p_hledat IS NULL OR btrim(p_hledat) = '' THEN NULL
                      ELSE '%' || replace(replace(replace(btrim(p_hledat), '\', '\\'), '%', '\%'), '_', '\_') || '%'
                 END;
BEGIN
  IF NOT ((SELECT public.is_service_role()) OR (SELECT public.is_admin_or_staff())) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'twin_label'), '[]'::jsonb)
    INTO v_items
  FROM (
    SELECT jsonb_build_object(
             'twin_id', t.id,
             'twin_label', t.label,
             'entity_type', t.entity_type,
             'status', t.status,
             -- Čím je člověk doložený ve zdrojích — podklad pro rozhodnutí.
             'refs', COALESCE(
               (SELECT jsonb_agg(jsonb_build_object(
                          'source', r.source, 'source_key', r.source_key,
                          'ref_kind', r.ref_kind, 'state', r.state)
                        ORDER BY r.source)
                  FROM public.twin_external_refs r
                 WHERE r.twin_id = t.id
                   AND r.ref_kind <> 'account'
                   AND r.state = 'confirmed'
                   AND (r.valid_to IS NULL OR r.valid_to > now())),
               '[]'::jsonb),
             -- ⭐ ROZESLANÉ POZVÁNKY. Bez nich by správce viděl „nemá účet"
             -- a pozval člověka podruhé — twin totiž zůstává v seznamu, dokud
             -- pozvánku někdo neuplatní, a to je správně (dokud ji neuplatnil,
             -- účet opravdu nemá). Rozdíl mezi „nikdo se o to nepostaral"
             -- a „čeká se na člověka" musí být VIDĚT, jinak se z toho stane
             -- fronta, kterou nikdo nedočte.
             'pozvanky', COALESCE(
               (SELECT jsonb_agg(jsonb_build_object(
                          'invitation_id', i.id, 'email', i.email,
                          'created_at', i.created_at, 'expires_at', i.expires_at,
                          'used_count', i.used_count, 'is_active', i.is_active)
                        ORDER BY i.created_at DESC)
                  FROM public.invitations i
                 WHERE i.twin_id = t.id),
               '[]'::jsonb),
             -- Návrhy účtu, které čekají na ratifikaci. Prázdné pole =
             -- nenavrhl nikdo, tedy práce pro člověka od nuly.
             'navrhy_uctu', COALESCE(
               (SELECT jsonb_agg(jsonb_build_object(
                          'ref_id', r.id, 'source_key', r.source_key,
                          'proposed_by', r.proposed_by, 'confidence', r.confidence)
                        ORDER BY r.confidence DESC NULLS LAST)
                  FROM public.twin_external_refs r
                 WHERE r.twin_id = t.id
                   AND r.ref_kind = 'account'
                   AND r.state = 'proposed'),
               '[]'::jsonb),
             -- Úkoly nesené tímhle twinem (viz hlavička: výběr hlavního úlomku).
             'kroky', (SELECT jsonb_build_object(
                                'celkem', count(*),
                                'ceka', count(*) FILTER (WHERE s.status = 'pending'))
                         FROM public.production_workflow_steps s
                        WHERE (s.input_data->>'authorized_twin_id') = t.id::text)
           ) AS x
      FROM public.twin_entities t
     WHERE (p_entity_type IS NULL OR t.entity_type = p_entity_type)
       AND t.status = 'active'
       AND (v_vzor IS NULL
            OR t.label ILIKE v_vzor
            OR EXISTS (SELECT 1 FROM public.twin_external_refs r
                        WHERE r.twin_id = t.id
                          AND r.ref_kind <> 'account'
                          AND r.state = 'confirmed'
                          AND r.source_key ILIKE v_vzor))
       -- ⛔ JÁDRO PODMÍNKY: nemá POTVRZENOU a PLATNOU vazbu na účet.
       -- `valid_to` se počítá: ukončená vazba (řidič odešel) znamená, že
       -- twin účet zase nemá — a musí se v seznamu objevit znovu.
       AND NOT EXISTS (
             SELECT 1 FROM public.twin_external_refs r
              WHERE r.twin_id = t.id
                AND r.ref_kind = 'account'
                AND r.state = 'confirmed'
                AND r.valid_from <= now()
                AND (r.valid_to IS NULL OR r.valid_to > now()))
     ORDER BY t.label
     -- O jeden víc: pozná se tak, jestli za hranou ještě někdo je.
     LIMIT v_limit + 1
  ) s;

  IF jsonb_array_length(v_items) > v_limit THEN
    v_items := v_items - v_limit;
    v_limitovano := true;
  END IF;

  RETURN jsonb_build_object('items', v_items, 'count', jsonb_array_length(v_items),
                            'limitovano', v_limitovano);
END;
$$
;

-- Permissions
REVOKE ALL ON FUNCTION public.twin_accounts_missing(text, integer, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.twin_accounts_missing(text, integer, text) TO authenticated, service_role;

-- Stará signatura musí ZMIZET: s DEFAULT u nového parametru by volání se dvěma
-- argumenty bylo nejednoznačné (42725) — nebo hůř, trefilo by starou verzi bez
-- hledání a bez úkolů.
DROP FUNCTION IF EXISTS public.twin_accounts_missing(text, integer);


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_catalog_source_findings.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_catalog_source_findings
-- Popis: NÁLEZY autority zdroje v katalogu parametrů. U aditivní veličiny
--        (aggregation 'sum' / historization 'event_log') čtečka twin_param_values
--        počítá jen události zdroje, kterého katalog jmenuje. Když ten zdroj nic
--        nezapsal nebo vůbec neexistuje, veličina je NEMĚŘENO — a tahle funkce
--        řekne proč, místo aby pravidlo tiše mlčelo.
--
--   trida 'nezname'  = VADA DAT katalogu: ani `source`, ani jeho část před ':'
--                      neodpovídá žádnému zdroji (agent_knowledge_sources.source_slug
--                      nebo poslední část jeho `namespace`, kde zdroj deklaruje
--                      doménu dodavatele — 'telematics/webdispecink'), pluginu
--                      (plugin_catalog.slug) ani zdroji/dráze žádné existující
--                      reference či události. Veličina se neukáže NIKDY → brána.
--   trida 'bez_dat'  = INFORMACE: zdroj existuje, ale událost toho typu z něj
--                      zatím není (plugin neschválen, vazby nepotvrzeny…).
--
-- Vrací: [{code, source, trida}] (žádné hodnoty — jen kódy a jména zdrojů)
-- Bezpečnost: SECURITY DEFINER (čte registr zdrojů a pluginů, který je jen pro
--             správu); service_role nebo admin/staff.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.twin_catalog_source_findings()
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_nalezy jsonb;
BEGIN
  IF NOT public.is_service_role() AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'twin_catalog_source_findings: service role or admin/staff required'
      USING ERRCODE = '42501';
  END IF;

  WITH kat AS (
    SELECT d.code,
           btrim(d.source)                     AS src,
           split_part(btrim(d.source), ':', 1) AS koren,
           COALESCE(d.metadata->>'event_type',
                    CASE WHEN d.metadata->>'shape' = 'code_value'
                         THEN 'twin_parameter' END) AS event_type
      FROM public.twin_parameter_definitions d
     WHERE (lower(COALESCE(d.aggregation, '')) = 'sum'
            OR lower(COALESCE(d.historization, '')) = 'event_log')
       AND NULLIF(btrim(d.source), '') IS NOT NULL
  ),
  hodnoceni AS (
    SELECT k.code, k.src,
           (   EXISTS (SELECT 1 FROM public.agent_knowledge_sources s
                        WHERE s.source_slug = k.koren
                           OR regexp_replace(s.namespace, '^.*/', '') = k.koren)
            OR EXISTS (SELECT 1 FROM public.plugin_catalog p WHERE p.slug = k.koren)
            OR EXISTS (SELECT 1 FROM public.twin_external_refs r
                        WHERE r.source = k.koren OR starts_with(r.source, k.koren || ':'))
            OR EXISTS (SELECT 1 FROM public.twin_events e
                        WHERE e.source = k.koren OR starts_with(e.source, k.koren || ':'))
           ) AS znamy,
           EXISTS (SELECT 1 FROM public.twin_events e
                    WHERE (k.event_type IS NULL OR e.event_type = k.event_type)
                      AND (e.source = k.src OR starts_with(e.source, k.src || ':'))) AS ma_data
      FROM kat k
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'code',   h.code,
           'source', h.src,
           'trida',  CASE WHEN NOT h.znamy THEN 'nezname' ELSE 'bez_dat' END)
           ORDER BY (NOT h.znamy) DESC, h.code), '[]'::jsonb)
    INTO v_nalezy
    FROM hodnoceni h
   WHERE NOT h.znamy OR NOT h.ma_data;

  RETURN v_nalezy;
END;
$$;

REVOKE ALL ON FUNCTION public.twin_catalog_source_findings() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.twin_catalog_source_findings() TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_entities_propagate_entity_type.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_entities_propagate_entity_type (trigger funkce)
-- Popis: Změní-li dvojče druh, změní se i druh jeho vazeb (twin_external_refs
--        .entity_type je odvozená kopie). Kdyby tím vznikla dvojí potvrzená
--        vazba téhož klíče v novém druhu, změna SPADNE na unikátním indexu —
--        nahlas, ne tichým ukončením cizí vazby.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.twin_entities_propagate_entity_type()
RETURNS trigger
LANGUAGE plpgsql
-- DEFINER: druh se čte z twin_entities bez ohledu na to, co vidí volající
-- (RLS by jinak druh schovala a vložení vazby spadlo na NOT NULL).
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
BEGIN
  UPDATE public.twin_external_refs
     SET entity_type = NEW.entity_type
   WHERE twin_id = NEW.id
     AND entity_type IS DISTINCT FROM NEW.entity_type;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public.twin_entities_propagate_entity_type() FROM PUBLIC, anon, authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_external_refs_set_entity_type.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_external_refs_set_entity_type (trigger funkce)
-- Popis: Druh entity vazby se ODVOZUJE z dvojčete, na které vazba ukazuje —
--        nikdy nepřichází od volajícího (ani ho nesmí přepsat). Je součástí
--        klíče jedinečnosti potvrzené vazby (uq_twin_external_refs_active_owner),
--        takže kdyby šel zadat ručně, šla by pojistka obejít.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.twin_external_refs_set_entity_type()
RETURNS trigger
LANGUAGE plpgsql
-- DEFINER: druh se čte z twin_entities bez ohledu na to, co vidí volající
-- (RLS by jinak druh schovala a vložení vazby spadlo na NOT NULL).
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
BEGIN
  SELECT t.entity_type INTO NEW.entity_type
    FROM public.twin_entities t
   WHERE t.id = NEW.twin_id;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public.twin_external_refs_set_entity_type() FROM PUBLIC, anon, authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_for_account.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_for_account
-- Popis: Dvojče (entita jádra), na které ukazuje POTVRZENÁ a platná reference
--        účtu (`twin_external_refs.ref_kind='account'`). ADR-003 (K1): identita
--        je dvojče, účet je jedna potvrzená reference. Vrací NULL, dokud účet
--        dvojče nemá (před backfillem) — volající s tím musí počítat, nikdy
--        nehádat.
--
-- SECURITY INVOKER záměrně: čte se pod právy volajícího, RLS nad
-- twin_external_refs rozhoduje, co je vidět. Pohledy audience modulu ji volají
-- z DEFINER blokových RPC (vlastník → vidí vše), člen z vlastní session vidí
-- jen svou referenci. Konvence klíče je táž, kterou používá
-- workflow_step_visible_to: source_key = účet jako text.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.twin_for_account(p_user_id uuid)
RETURNS uuid
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  SELECT r.twin_id
  FROM public.twin_external_refs r
  WHERE r.ref_kind = 'account'
    AND r.source_key = p_user_id::text
    AND r.state = 'confirmed'
    AND r.valid_to IS NULL
  ORDER BY r.confirmed_at DESC NULLS LAST
  LIMIT 1;
$$;

REVOKE ALL ON FUNCTION public.twin_for_account(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.twin_for_account(uuid) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/submit_surface_action.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: submit_surface_action
-- Popis: JEDINÁ zápisová cesta akcí správy z plochy (ADR-003, program K4).
--   Klient posílá `action_slug` + cíl + payload; tady se slug přeloží přes
--   allowlist `surface_actions` (RLS: aktivní a publikum volajícího), cíl se
--   ověří a doplní (twin → účet přes potvrzenou referenci, actor → twin),
--   payload se ověří proti deklaraci `fields` (typ, povinnost, výčet; neznámé
--   klíče se zahodí), argumenty se složí podle `arg_map` POJMENOVANĚ
--   (`p_x => ($1)[n]::typ`, hodnoty jako parametr) a zavolá se cílové RPC.
--   Každé volání má audit (jen klíče payloadu, nikdy hodnoty).
--   Typ pole `secret` (heslo, klíč dodavatele): bez výchozí hodnoty, v chybě ani
--   v auditu se neobjeví, klient ho kreslí jako skryté pole a nevrací ho.
--
-- BEZPEČNOST:
--   · SECURITY INVOKER — běží jako volající: RLS nad surface_actions rozhoduje,
--     co vůbec existuje; cílové RPC drží VLASTNÍ autorizaci (is_admin_or_staff,
--     adresát taktu, subjekt) a spouští se s právy volajícího. Tenhle dispečer
--     nikomu nic nepřidává — jen překládá a hlídá tvar.
--   · Jméno RPC pochází z tabulky (CHECK identifikátor) a jde do SQL přes %I;
--     hodnoty jdou VŽDY jako PARAMETR (EXECUTE … USING, `($1)[n]`) s explicitním
--     castem na typ z povoleného výčtu. Nic z klienta se do SQL neskládá jako
--     text — ani jako literál, protože text příkazu končí v logu chyb.
--   · Neviditelná akce = 42501, ne „nenalezeno" (nic se neprozrazuje).
--
-- Vrací {ok, action_slug, result} (result = to_jsonb návratu RPC, null u void).
-- ============================================================================
-- BEZ PŘÍPONY `_audited` ZÁMĚRNĚ: přípona je smlouva „běží jako DEFINER" (brána
-- audited-function-integrity). Tohle RPC musí být INVOKER — cílová funkce běží
-- s právy VOLAJÍCÍHO (EXECUTE + RLS + její vlastní is_admin_or_staff), ne jako
-- vlastník; audit se zapisuje přes audience_log_event stejně jako jinde.
CREATE OR REPLACE FUNCTION public.submit_surface_action(
  p_action_slug text,
  p_target      jsonb DEFAULT '{}'::jsonb,
  p_payload     jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_uid      uuid := auth.uid();
  v_act      public.surface_actions%rowtype;
  v_twin     uuid;
  v_user     uuid;
  v_story    uuid;
  v_payload  jsonb := '{}'::jsonb;
  v_field    jsonb;
  v_key      text;
  v_ftype    text;
  v_val      text;
  v_missing  text[] := '{}';
  v_arg      jsonb;
  v_from     text;
  v_atype    text;
  v_args     text[] := '{}';
  v_vals     text[] := '{}';
  v_res      jsonb;
  v_uuid_re  constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_action_slug IS NULL OR p_action_slug !~ '^[a-z][a-z0-9_.]*$' THEN
    RAISE EXCEPTION 'action slug is required' USING ERRCODE = '22023';
  END IF;

  -- 1. allowlist (RLS: aktivní + publikum volajícího)
  SELECT * INTO v_act FROM public.surface_actions a WHERE a.action_slug = p_action_slug;
  IF NOT FOUND OR NOT v_act.is_active THEN
    RAISE EXCEPTION 'action % is not available to you', p_action_slug USING ERRCODE = '42501';
  END IF;

  -- 2. cíl
  p_target := coalesce(p_target, '{}'::jsonb);
  CASE v_act.target_kind
    WHEN 'twin' THEN
      IF coalesce(p_target->>'twin_id', '') !~ v_uuid_re THEN
        RAISE EXCEPTION 'target twin_id is required' USING ERRCODE = '22023';
      END IF;
      v_twin := (p_target->>'twin_id')::uuid;
      SELECT r.source_key::uuid INTO v_user
      FROM public.twin_external_refs r
      WHERE r.twin_id = v_twin AND r.ref_kind = 'account' AND r.state = 'confirmed'
        AND r.valid_to IS NULL AND r.source_key ~ v_uuid_re
      ORDER BY r.confirmed_at DESC NULLS LAST LIMIT 1;
    WHEN 'actor' THEN
      IF coalesce(p_target->>'user_id', '') !~ v_uuid_re THEN
        RAISE EXCEPTION 'target user_id is required' USING ERRCODE = '22023';
      END IF;
      v_user := (p_target->>'user_id')::uuid;
      v_twin := public.twin_for_account(v_user);
    WHEN 'story' THEN
      IF coalesce(p_target->>'story_id', '') !~ v_uuid_re THEN
        RAISE EXCEPTION 'target story_id is required' USING ERRCODE = '22023';
      END IF;
      v_story := (p_target->>'story_id')::uuid;
    ELSE
      NULL;
  END CASE;

  -- 3. payload podle deklarace polí (neznámé klíče se zahodí)
  FOR v_field IN SELECT * FROM jsonb_array_elements(coalesce(v_act.fields, '[]'::jsonb)) LOOP
    v_key   := v_field->>'key';
    v_ftype := coalesce(v_field->>'type', 'text');
    -- Klíč jde jen do jsonb (payload, payload_json), nikdy do SQL jako identifikátor,
    -- takže smí i camelCase: konfigurace pluginů (`baseUrl`) má klíče tak, jak je
    -- plugin čte (2026-09-26, připojení zdroje z administrace).
    CONTINUE WHEN v_key IS NULL OR v_key !~ '^[a-zA-Z][a-zA-Z0-9_]*$';
    v_val := nullif(btrim(coalesce(p_payload->>v_key, '')), '');
    IF v_val IS NULL THEN
      IF v_ftype <> 'secret' AND v_field ? 'default' AND nullif(v_field->>'default', '') IS NOT NULL THEN
        v_val := v_field->>'default';
      ELSIF coalesce((v_field->>'required')::boolean, false) THEN
        v_missing := v_missing || v_key;
        CONTINUE;
      ELSE
        CONTINUE;
      END IF;
    END IF;
    CASE v_ftype
      WHEN 'uuid' THEN
        IF v_val !~ v_uuid_re THEN RAISE EXCEPTION 'field % must be a uuid', v_key USING ERRCODE = '22023'; END IF;
      WHEN 'date' THEN
        IF v_val !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'field % must be a date (YYYY-MM-DD)', v_key USING ERRCODE = '22023'; END IF;
      WHEN 'timestamptz' THEN
        -- Přijímá ISO 8601 z formuláře (datetime-local: 2026-09-10T09:00) i textový
        -- tvar Postgresu (2026-09-07 22:40:05.12+00 — posun může být jen HH).
        IF v_val !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9]{2}:[0-9]{2}(:[0-9]{2}(\.[0-9]+)?)?)?([Zz]|[+-][0-9]{2}(:?[0-9]{2})?)?$' THEN
          RAISE EXCEPTION 'field % must be a timestamp', v_key USING ERRCODE = '22023';
        END IF;
      WHEN 'integer' THEN
        IF v_val !~ '^-?[0-9]{1,12}$' THEN RAISE EXCEPTION 'field % must be an integer', v_key USING ERRCODE = '22023'; END IF;
      WHEN 'boolean' THEN
        IF lower(v_val) NOT IN ('true', 'false') THEN RAISE EXCEPTION 'field % must be true/false', v_key USING ERRCODE = '22023'; END IF;
        v_val := lower(v_val);
      WHEN 'enum' THEN
        IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(v_field->'options', '[]'::jsonb)) o WHERE o->>'value' = v_val) THEN
          RAISE EXCEPTION 'field % has a value outside its options', v_key USING ERRCODE = '22023';
        END IF;
      WHEN 'secret' THEN
        -- Tajná hodnota (heslo, klíč dodavatele): ověří se jen délka a do chyby se
        -- NIKDY nevypisuje. Výchozí hodnotu mít nesmí (deklarace je čitelná všem, kdo
        -- akci vidí) — `default` u tajného pole se ignoruje výš: prázdné = chybí.
        IF length(v_val) > 4000 THEN RAISE EXCEPTION 'field % is too long', v_key USING ERRCODE = '22023'; END IF;
      ELSE -- text | textarea
        IF length(v_val) > 4000 THEN RAISE EXCEPTION 'field % is too long', v_key USING ERRCODE = '22023'; END IF;
    END CASE;
    v_payload := v_payload || jsonb_build_object(v_key, v_val);
  END LOOP;
  IF coalesce(array_length(v_missing, 1), 0) > 0 THEN
    RAISE EXCEPTION 'missing required field(s): %', array_to_string(v_missing, ', ') USING ERRCODE = '22023';
  END IF;

  -- 4. argumenty podle arg_map — pojmenovaně, s explicitním typem, HODNOTY JAKO PARAMETR
  --
  -- ⛔ NE LITERÁLY V TEXTU PŘÍKAZU (2026-09-26). Hodnoty se dřív skládaly do textu
  -- (`p_x => 'hodnota'::text`). Když cílové RPC spadlo, Postgres zalogoval chybu
  -- i s kontextem PL/pgSQL („SQL statement …") — tedy s hodnotou; v provozu je
  -- log_min_error_statement=error. U tajného pole (heslo dodavatele) by to byl
  -- únik do logu serveru. Teď jde každá hodnota jako prvek pole `$1` přes
  -- EXECUTE … USING: text příkazu nese jen `($1)[n]::typ`.
  FOR v_arg IN SELECT * FROM jsonb_array_elements(coalesce(v_act.arg_map, '[]'::jsonb)) LOOP
    v_from  := v_arg->>'from';
    v_atype := coalesce(v_arg->>'type', 'text');
    IF coalesce(v_arg->>'name', '') !~ '^[a-z][a-z0-9_]*$' THEN
      RAISE EXCEPTION 'arg_map entry without a valid name' USING ERRCODE = '22023';
    END IF;
    IF v_atype NOT IN ('uuid','text','timestamptz','date','integer','boolean','numeric','jsonb','uuid[]','text[]') THEN
      RAISE EXCEPTION 'arg_map type % is not allowed', v_atype USING ERRCODE = '22023';
    END IF;
    v_val := CASE v_from
      WHEN 'target.twin_id'   THEN v_twin::text
      WHEN 'target.user_id'   THEN v_user::text
      WHEN 'target.user_ids'  THEN CASE WHEN v_user IS NULL THEN NULL ELSE '{' || v_user::text || '}' END
      WHEN 'target.story_id'  THEN v_story::text
      WHEN 'caller.user_id'   THEN v_uid::text
      WHEN 'const'            THEN v_arg->>'value'
      WHEN 'payload'          THEN v_payload->>(v_arg->>'key')
      WHEN 'payload_json'     THEN v_payload::text
      ELSE NULL
    END;
    IF v_from NOT IN ('target.twin_id','target.user_id','target.user_ids','target.story_id','caller.user_id','const','payload','payload_json') THEN
      RAISE EXCEPTION 'arg_map source % is not allowed', v_from USING ERRCODE = '22023';
    END IF;
    IF v_val IS NULL AND v_arg->>'fallback' = 'caller.user_id' THEN
      v_val := v_uid::text;
    END IF;
    IF v_val IS NULL THEN
      IF coalesce((v_arg->>'required')::boolean, true) THEN
        RAISE EXCEPTION 'argument % has no value (source %)', v_arg->>'name', v_from USING ERRCODE = '22023';
      END IF;
      v_args := v_args || format('%I => NULL::%s', v_arg->>'name', v_atype);
    ELSE
      v_vals := v_vals || v_val;
      v_args := v_args || format('%I => ($1)[%s]::%s', v_arg->>'name', array_length(v_vals, 1), v_atype);
    END IF;
  END LOOP;

  -- 5. volání cílového RPC (jméno z allowlistu, %I; argumenty pojmenované)
  IF coalesce(v_act.returns_void, false) THEN
    EXECUTE format('select public.%I(%s)', v_act.rpc_name, array_to_string(v_args, ', ')) USING v_vals;
    v_res := 'null'::jsonb;
  ELSE
    EXECUTE format('select to_jsonb(public.%I(%s))', v_act.rpc_name, array_to_string(v_args, ', ')) INTO v_res USING v_vals;
  END IF;

  -- 6. audit (bez PII: cíl jako id, jen klíče payloadu)
  PERFORM public.audience_log_event(
    'surface_action',
    p_action_slug,
    v_act.target_kind,
    coalesce(v_twin, v_user, v_story, v_uid),
    format('Surface action %s (%s)', p_action_slug, v_act.rpc_name),
    jsonb_build_object(
      'target', p_target,
      'payload_keys', (SELECT coalesce(jsonb_agg(k), '[]'::jsonb) FROM jsonb_object_keys(v_payload) k),
      'rpc', v_act.rpc_name,
      'result', v_res)
  );

  RETURN jsonb_build_object('ok', true, 'action_slug', p_action_slug, 'result', v_res);
END;
$$;

REVOKE ALL ON FUNCTION public.submit_surface_action(text, jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_surface_action(text, jsonb, jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_graph_descendants.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_graph_descendants
-- Popis: Vše POD uzlem twinsverse K DATU — rekurzivní sjezd po hranách
--        s platností. Základ pro agregace po větvích (jednotka vs nadřazený
--        celek) a pro derive_audience (publikum / auditorium / elektorát).
--
--        Směr: hrana se čte „source —kind→ target"; „pod uzlem X" jsou
--        entity, jejichž řetěz hran VEDE DO X (WHERE target = X, sbírají se
--        sources). Dotaz na JEDEN uzel tak vrací JEHO podstrom — ne agregát
--        celku, do kterého uzel patří (přesně vada bloku E).
--
--        p_at: hrana platí, když valid_from <= p_at < COALESCE(valid_to, ∞).
--        Tentýž dotaz s jiným datem = jiná množina — to je vlastnost, ne bug.
--
-- Bezpečnost: SECURITY INVOKER ZÁMĚRNĚ — viditelnost hran řeší RLS
--        (twin_relations_read), tahle funkce ji DĚDÍ a nesmí ji obcházet.
--        Definer varianta by četla hrany, na které volající nemá nárok.
--
-- Ochrana proti cyklu: cesta se nese v poli a uzel se podruhé nevstupuje;
--        p_max_depth je pojistka proti degenerovaným grafům, a když se
--        ZAŘÍZNE O LIMIT, funkce to ŘEKNE (truncated) — tichý ořez by
--        vypadal jako úplná odpověď (zákon: žádné tiché stropy).
--
-- ⭐ JEDEN ŘÁDEK NA UZEL (DISTINCT ON) — naměřeno testem 31 při zavádění:
--        surová rekurze vrací uzel TOLIKRÁT, KOLIKA CESTAMI je dosažitelný.
--        Na fixtuře se dvěma druhy hran mezi touž dvojicí vyšlo 4 řádky na
--        2 uzly. Agregace „vše pod uzlem" by tím DVAKRÁT ZAPOČÍTALA týž
--        podřízený celek — přesně ta třída chyby, kvůli které tahle funkce
--        vzniká (blok E: dotaz na jednotku vrací agregát). Vrací se proto
--        NEJKRATŠÍ cesta k uzlu; kdo potřebuje všechny cesty, ptá se hran.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_graph_descendants(
  p_root_twin_id uuid,
  p_kinds        text[]      DEFAULT NULL,   -- NULL = všechny druhy vztahů
  p_at           timestamptz DEFAULT now(),
  p_max_depth    integer     DEFAULT 32
)
RETURNS TABLE (twin_id uuid, depth integer, via_kind text, truncated boolean)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH RECURSIVE walk AS (
    SELECT r.source_twin_id AS twin_id,
           1                AS depth,
           r.relation_kind  AS via_kind,
           ARRAY[p_root_twin_id, r.source_twin_id] AS path
      FROM public.twin_relations r
     WHERE r.target_twin_id = p_root_twin_id
       AND (p_kinds IS NULL OR r.relation_kind = ANY (p_kinds))
       AND r.valid_from <= p_at
       AND (r.valid_to IS NULL OR r.valid_to > p_at)

    UNION ALL

    SELECT r.source_twin_id,
           w.depth + 1,
           r.relation_kind,
           w.path || r.source_twin_id
      FROM walk w
      JOIN public.twin_relations r ON r.target_twin_id = w.twin_id
     WHERE w.depth < p_max_depth
       AND NOT r.source_twin_id = ANY (w.path)   -- cyklus se nevstupuje podruhé
       AND (p_kinds IS NULL OR r.relation_kind = ANY (p_kinds))
       AND r.valid_from <= p_at
       AND (r.valid_to IS NULL OR r.valid_to > p_at)
  )
  -- Jeden řádek na uzel: nejkratší cesta vyhrává; při shodné hloubce rozhoduje
  -- druh vztahu abecedně, aby dva běhy nad týmiž daty daly TÝŽ výsledek
  -- (nedeterministický artefakt by se v agregacích projevil jako šum).
  SELECT DISTINCT ON (w.twin_id)
         w.twin_id,
         w.depth,
         w.via_kind,
         w.depth >= p_max_depth AS truncated
    FROM walk w
   ORDER BY w.twin_id, w.depth, w.via_kind;
$function$;

REVOKE ALL ON FUNCTION public.twin_graph_descendants(uuid, text[], timestamptz, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.twin_graph_descendants(uuid, text[], timestamptz, integer) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_identity_confirm_binding.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_identity_confirm_binding
-- Popis: LIDSKÁ ratifikace navržené vazby — jediná cesta, jak se cross-source
--        vazba stává autoritativní. Výhradně admin/staff s reálným auth.uid()
--        (confirmed_by = audit trail); service_role NEMÁ ratifikovat — import
--        navrhuje, člověk potvrzuje.
--        Drží-li klíč jiné dvojče (předání čipu), potvrzení bez p_supersede
--        selže; s p_supersede=true se starému vlastníku ukončí platnost
--        (valid_to = now(), state zůstává confirmed = historie) a nová vazba
--        se potvrdí — handover bez ztráty historie.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT
-- Audit: twin_external_refs.confirmed (bez source_key)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_identity_confirm_binding(
  p_ref_id uuid,
  p_supersede boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_reviewer uuid := auth.uid();
  v_ref record;
  v_owner record;
  v_superseded uuid;
BEGIN
  -- Lidská ratifikace: admin/staff s reálnou identitou (NE service_role)
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff required (human ratification)';
  END IF;
  IF v_reviewer IS NULL THEN
    RAISE EXCEPTION 'Ratification requires an authenticated reviewer (auth.uid() is null)';
  END IF;

  SELECT r.id, r.twin_id, r.source, r.source_key, r.ref_kind, r.entity_type, r.state
    INTO v_ref
    FROM public.twin_external_refs r WHERE r.id = p_ref_id;
  IF v_ref.id IS NULL THEN
    RAISE EXCEPTION 'binding % not found', p_ref_id;
  END IF;
  IF v_ref.state <> 'proposed' THEN
    RAISE EXCEPTION 'binding % is %, only proposed can be confirmed', p_ref_id, v_ref.state;
  END IF;

  -- Aktivní potvrzený vlastník téhož klíče V RÁMCI DRUHU (2026-09-27: vozidlo 5
  -- a osoba 5 téhož zdroje si klíč neberou — potvrzení osoby dřív spadlo na
  -- „key already confirmed for another twin", protože klíč držel vůz).
  SELECT r.id, r.twin_id INTO v_owner
  FROM public.twin_external_refs r
  WHERE r.source = v_ref.source
    AND r.source_key = v_ref.source_key
    AND r.ref_kind = v_ref.ref_kind
    AND r.entity_type = v_ref.entity_type
    AND r.state = 'confirmed'
    AND r.valid_to IS NULL
  LIMIT 1;

  IF v_owner.id IS NOT NULL THEN
    IF v_owner.twin_id = v_ref.twin_id THEN
      -- Totéž dvojče už klíč drží — návrh je bezpředmětný
      UPDATE public.twin_external_refs
      SET state = 'superseded', updated_at = now()
      WHERE id = p_ref_id;
      RETURN jsonb_build_object('ref_id', v_owner.id, 'state', 'confirmed', 'already', true);
    END IF;
    IF NOT p_supersede THEN
      RAISE EXCEPTION 'key already confirmed for another twin (%) — pass p_supersede => true to hand over', v_owner.twin_id;
    END IF;
    -- Handover: starému vlastníku končí platnost, historie zůstává
    UPDATE public.twin_external_refs
    SET valid_to = now(), updated_at = now()
    WHERE id = v_owner.id;
    v_superseded := v_owner.id;
  END IF;

  UPDATE public.twin_external_refs
  SET state = 'confirmed',
      confirmed_by = v_reviewer,
      confirmed_at = now(),
      valid_from = now(),
      updated_at = now()
  WHERE id = p_ref_id;

  -- Audit log (bez source_key — klíč zdroje může být osobní údaj)
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    v_reviewer,
    'twin_external_refs.confirmed',
    jsonb_build_object(
      'ref_id', p_ref_id,
      'twin_id', v_ref.twin_id,
      'source', v_ref.source,
      'ref_kind', v_ref.ref_kind,
      'superseded_ref_id', v_superseded
    )
  );

  RETURN jsonb_build_object(
    'ref_id', p_ref_id,
    'state', 'confirmed',
    'superseded_ref_id', v_superseded
  );
END;
$$;

REVOKE ALL ON FUNCTION public.twin_identity_confirm_binding(uuid, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.twin_identity_confirm_binding(uuid, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.twin_identity_confirm_binding(uuid, boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_identity_list_unmatched.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_identity_list_unmatched
-- Popis: Ratifikační fronta — navržené (proposed) vazby čekající na lidské
--        rozhodnutí, nejstarší první. Zdroj pro surface blok „nespárované
--        identity" (extranet/admin): reviewer vidí evidenci návrhu
--        (proposed_by, confidence) i source_key (bez něj nelze rozhodnout —
--        oprávněné čtení admin/staff, viz RLS na twin_external_refs).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (jen admin/staff — PII)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_identity_list_unmatched(
  p_entity_type text DEFAULT NULL,
  p_limit integer DEFAULT 100
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_items jsonb;
BEGIN
  -- Ratifikace je lidská práce: jen admin/staff (service_role frontu nečte)
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff required';
  END IF;

  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 500 THEN
    RAISE EXCEPTION 'p_limit must be between 1 and 500';
  END IF;

  SELECT COALESCE(jsonb_agg(item ORDER BY item->>'created_at'), '[]'::jsonb) INTO v_items
  FROM (
    SELECT jsonb_build_object(
      'ref_id', r.id,
      'twin_id', r.twin_id,
      'twin_label', t.label,
      'entity_type', t.entity_type,
      'source', r.source,
      'source_key', r.source_key,
      'ref_kind', r.ref_kind,
      'proposed_by', r.proposed_by,
      'confidence', r.confidence,
      'note', r.note,
      'created_at', r.created_at,
      -- ⛔ PŘEVZETÍ KLÍČE MUSÍ BÝT VIDĚT (naměřeno 2026-09-20 při review):
      -- když tentýž klíč UŽ potvrzeně patří JINÉMU dvojčeti, je návrh ve
      -- skutečnosti žádost o PŘEDÁNÍ. Příznak `conflict` do té doby žil jen
      -- v návratové hodnotě propose_binding a v auditu, ve frontě nebyl —
      -- recenzent viděl obyčejný návrh a potvrzení mu pak spadlo na výjimku
      -- „key already confirmed for another twin", které nemusel rozumět.
      -- Pojistka v confirm_binding drží dál; tohle jen vrací člověku informaci.
      'conflict', EXISTS (
        SELECT 1 FROM public.twin_external_refs c
         WHERE c.source = r.source AND c.source_key = r.source_key
           AND c.ref_kind = r.ref_kind AND c.entity_type = r.entity_type
           AND c.state = 'confirmed'
           AND c.valid_to IS NULL AND c.twin_id <> r.twin_id)
    ) AS item
    FROM public.twin_external_refs r
    JOIN public.twin_entities t ON t.id = r.twin_id
    WHERE r.state = 'proposed'
      AND (p_entity_type IS NULL OR t.entity_type = p_entity_type)
    ORDER BY r.created_at
    LIMIT p_limit
  ) AS q;

  RETURN v_items;
END;
$$;

REVOKE ALL ON FUNCTION public.twin_identity_list_unmatched(text, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.twin_identity_list_unmatched(text, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.twin_identity_list_unmatched(text, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_twin_identity_queue.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'review_queue' block: proposed twin-identity bindings awaiting
-- HUMAN ratification (pověření). AISHA proposes cross-source bindings from the
-- sources (twin_identity_propose_binding, state='proposed'); a human confirms or
-- rejects them here. This is the surface-side (consumer) of the binding seam —
-- the queue where "AISHA identified an entity, now authorize its twin".
--
-- Seam, not new domain: it delegates to twin_identity_list_unmatched (the existing
-- DEFINER'd, admin/staff-gated ratification queue — source_key is PII) and merely
-- RESHAPES its bare array into the review_queue {items, actions} contract that
-- get_block_data + BlockRenderer already speak (mirrors get_obligation_queue).
--
-- Access degrades gracefully: non-staff callers get an empty queue (not an error),
-- so get_block_data never 500s for a normal extranet user.
--
-- Contract: (jsonb) -> jsonb {data:{entity_kind:'twin_identity', items[], actions[]}, provenance}.

create or replace function public.get_twin_identity_queue(p_params jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public, pg_temp
as $$
declare
  v_raw   jsonb := '[]'::jsonb;
  v_items jsonb;
begin
  -- Ratification is admin/staff work (source_key is PII); everyone else sees an
  -- empty queue rather than a 'Unauthorized' exception bubbling through the block.
  if public.is_admin_or_staff() then
    v_raw := public.twin_identity_list_unmatched(
      nullif(p_params->>'entity_type', ''),
      coalesce(nullif(p_params->>'limit', '')::int, 100)
    );
  end if;

  select coalesce(jsonb_agg(
           jsonb_build_object(
             'id',           e->>'ref_id',
             'title',        coalesce(nullif(e->>'twin_label', ''), e->>'source_key'),
             'subtitle_key', 'app.twins.review.proposed',
             'state',        'needs_review',
             'fields',       jsonb_build_array(
               jsonb_build_object('key', 'entity_type', 'label_key', 'app.twins.field.entity_type', 'value', e->>'entity_type'),
               jsonb_build_object('key', 'source',      'label_key', 'app.twins.field.source',      'value', e->>'source'),
               jsonb_build_object('key', 'source_key',  'label_key', 'app.twins.field.source_key',  'value', e->>'source_key'),
               jsonb_build_object('key', 'ref_kind',    'label_key', 'app.twins.field.ref_kind',    'value', e->>'ref_kind'),
               jsonb_build_object('key', 'proposed_by', 'label_key', 'app.twins.field.proposed_by', 'value', e->>'proposed_by'),
               jsonb_build_object('key', 'confidence',  'label_key', 'app.twins.field.confidence',  'value', e->>'confidence'),
               -- Převzetí klíče od jiného dvojčete = jiné rozhodnutí než nová vazba.
               -- Text, ne boolean: maska tabulky/fronty boolean nepřipouští.
               jsonb_build_object('key', 'conflict',    'label_key', 'app.twins.field.conflict',
                                  'value', CASE WHEN (e->>'conflict')::boolean THEN 'true' ELSE 'false' END)
             )
           )
           order by e->>'created_at'
         ), '[]'::jsonb)
    into v_items
  from jsonb_array_elements(v_raw) as e;

  return jsonb_build_object(
    'data', jsonb_build_object(
      'entity_kind', 'twin_identity',
      'items', v_items,
      'actions', jsonb_build_array(
        jsonb_build_object('action_key', 'app.twins.action.confirm', 'decision', 'confirmed', 'intent', 'approve'),
        jsonb_build_object('action_key', 'app.twins.action.reject',  'decision', 'rejected',  'intent', 'reject')
      )
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'twin-core',
      'freshness_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'twin-identity-queue'
    )
  );
end;
$$;

revoke all on function public.get_twin_identity_queue(jsonb) from public, anon;
grant execute on function public.get_twin_identity_queue(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_identity_match_candidates.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_identity_match_candidates
-- Popis: Co ještě stojí za POROVNÁNÍ napříč světy — navržené reference jednoho
--        zdroje (typicky identifikační parametry z ingestu, např. e-mail
--        z Raynetu), jejichž dvojče ZATÍM nemá potvrzenou vazbu na cílový
--        zdroj (typicky účty aplikace).
--
-- ⛔ DOPORUČENÍ, NE VAZBA. Tahle funkce nic nespojuje ani nenavrhuje — jen
-- říká, na co se má porovnávací pruh zeptat zdroje. Návrh zakládá až
-- twin_identity_propose_match, potvrzení výhradně člověk v kokpitu
-- (submit_evidence_review_audited → twin_identity_confirm_binding). Týž vzor
-- jako advisory artefakty ingestu (li_entity_suggestions): DŮKAZ, ne fakt.
--
-- ⚠ PII: `value` je hodnota identifikačního parametru (e-mail). Proto
-- service_role nebo admin/staff, nikdy `authenticated` naslepo — a volající
-- ji nesmí nikam uložit; slouží jen k porovnání v paměti.
--
-- Vrací: [{ref_id, twin_id, twin_label, value}] , nejstarší návrhy první.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.twin_identity_match_candidates(
  p_from_source text,
  p_ref_kind text,
  p_to_source text,
  p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_items jsonb;
BEGIN
  IF NOT public.is_service_role() AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'twin_identity_match_candidates: service role or admin/staff required'
      USING ERRCODE = '42501';
  END IF;
  IF coalesce(btrim(p_from_source), '') = '' OR coalesce(btrim(p_ref_kind), '') = ''
     OR coalesce(btrim(p_to_source), '') = '' THEN
    RAISE EXCEPTION 'twin_identity_match_candidates: from_source, ref_kind and to_source are required'
      USING ERRCODE = '22023';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 1000 THEN
    RAISE EXCEPTION 'twin_identity_match_candidates: limit must be between 1 and 1000'
      USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(jsonb_agg(i ORDER BY i->>'created_at'), '[]'::jsonb) INTO v_items
  FROM (
    SELECT jsonb_build_object(
             'ref_id', r.id,
             'twin_id', r.twin_id,
             'twin_label', t.label,
             'value', r.source_key,
             'created_at', r.created_at) AS i
    FROM public.twin_external_refs r
    JOIN public.twin_entities t ON t.id = r.twin_id
    WHERE r.source = p_from_source
      AND r.ref_kind = p_ref_kind
      AND r.state = 'proposed'
      AND r.valid_to IS NULL
      -- dvojče, které už do cílového světa POTVRZENĚ patří, porovnávat nepotřebuje
      AND NOT EXISTS (
        SELECT 1 FROM public.twin_external_refs c
         WHERE c.twin_id = r.twin_id AND c.source = p_to_source
           AND c.state = 'confirmed' AND c.valid_to IS NULL)
    ORDER BY r.created_at
    LIMIT p_limit
  ) s;

  RETURN v_items;
END;
$function$;

REVOKE ALL ON FUNCTION public.twin_identity_match_candidates(text, text, text, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.twin_identity_match_candidates(text, text, text, integer) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_identity_propose_binding.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_identity_propose_binding
-- Popis: NÁVRH cross-source vazby identity (řidič↔platformní user, čip↔osoba,
--        osoba↔ERP zaměstnanec…). Zdroj/pravidlo navrhuje S EVIDENCÍ
--        (proposed_by, confidence) — nikdy nic nepotvrzuje samo: potvrzení
--        je výhradně lidské (twin_identity_confirm_binding).
--        Idempotence: existující potvrzená vazba téhož dvojčete → vrací ji
--        beze změny; existující shodný návrh → vrací jej (žádné duplicity
--        ve frontě). Návrh na klíč potvrzený JINÉMU dvojčeti se založí
--        (conflict=true) — jde do review, NIKDY nepřepisuje potvrzené.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT
-- Audit: twin_external_refs.proposed (bez source_key)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_identity_propose_binding(
  p_twin_id uuid,
  p_source text,
  p_source_key text,
  p_ref_kind text,
  p_proposed_by text,
  p_confidence numeric DEFAULT NULL,
  p_note text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean := public.is_service_role();
  v_ref uuid;
  v_owner uuid;
  v_conflict boolean := false;
BEGIN
  -- Authorization check (FIRST, before any data access)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  -- Input validation
  IF p_twin_id IS NULL THEN
    RAISE EXCEPTION 'p_twin_id must not be null';
  END IF;
  IF p_source IS NULL OR btrim(p_source) = '' THEN
    RAISE EXCEPTION 'p_source must not be blank';
  END IF;
  IF p_source_key IS NULL OR btrim(p_source_key) = '' THEN
    RAISE EXCEPTION 'p_source_key must not be blank';
  END IF;
  -- ⛔ JEDNA SKUTEČNOST, JEDNA IDENTITA (2026-09-19). Zdroj pohlcený jiným
  -- (registr: neaktivní + superseded_by) se zapisuje pod toho, kdo ho pohltil.
  -- Bez toho přehrání starého balíčku s historickým jménem (`aisha-local-ingest`)
  -- nenajde existující twin a založí duplikát — 30. 8. to bylo 839 firem.
  -- Viz canonical_ingest_source.
  p_source := public.canonical_ingest_source(p_source);
  IF p_ref_kind IS NULL OR btrim(p_ref_kind) = '' THEN
    RAISE EXCEPTION 'p_ref_kind must not be blank';
  END IF;
  IF p_proposed_by IS NULL OR btrim(p_proposed_by) = '' THEN
    RAISE EXCEPTION 'p_proposed_by must not be blank';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.twin_entities t WHERE t.id = p_twin_id) THEN
    RAISE EXCEPTION 'twin % not found', p_twin_id;
  END IF;

  -- Aktivní potvrzený vlastník klíče V RÁMCI DRUHU navrhovaného dvojčete
  -- (2026-09-27: vozidlo 5 a osoba 5 téhož zdroje jsou dvě různé vazby —
  -- dřív se návrh pro osobu tiše přeskočil jako „konflikt s vozidlem").
  SELECT r.id, r.twin_id INTO v_ref, v_owner
  FROM public.twin_external_refs r
  WHERE r.source = p_source
    AND r.source_key = p_source_key
    AND r.ref_kind = p_ref_kind
    AND r.entity_type = (SELECT t.entity_type FROM public.twin_entities t WHERE t.id = p_twin_id)
    AND r.state = 'confirmed'
    AND r.valid_to IS NULL
  LIMIT 1;

  IF v_owner IS NOT NULL AND v_owner = p_twin_id THEN
    -- Už potvrzeno témuž dvojčeti — idempotentně vracíme, nic se nemění
    RETURN jsonb_build_object('ref_id', v_ref, 'state', 'confirmed', 'already', true);
  END IF;
  v_conflict := v_owner IS NOT NULL;  -- klíč drží jiné dvojče → návrh jde do review

  -- Shodný čekající návrh — idempotentně vracíme (fronta bez duplicit)
  SELECT r.id INTO v_ref
  FROM public.twin_external_refs r
  WHERE r.twin_id = p_twin_id
    AND r.source = p_source
    AND r.source_key = p_source_key
    AND r.ref_kind = p_ref_kind
    AND r.state = 'proposed'
  LIMIT 1;

  IF v_ref IS NOT NULL THEN
    RETURN jsonb_build_object('ref_id', v_ref, 'state', 'proposed', 'already', true, 'conflict', v_conflict);
  END IF;

  INSERT INTO public.twin_external_refs (
    twin_id, source, source_key, ref_kind, state, proposed_by, confidence, note
  )
  VALUES (
    p_twin_id, p_source, p_source_key, p_ref_kind, 'proposed', p_proposed_by, p_confidence, p_note
  )
  RETURNING id INTO v_ref;

  -- Audit log (bez source_key — klíč zdroje může být osobní údaj)
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'twin_external_refs.proposed',
    jsonb_build_object(
      'ref_id', v_ref,
      'twin_id', p_twin_id,
      'source', p_source,
      'ref_kind', p_ref_kind,
      'proposed_by', p_proposed_by,
      'conflict', v_conflict
    )
  );

  RETURN jsonb_build_object('ref_id', v_ref, 'state', 'proposed', 'already', false, 'conflict', v_conflict);
END;
$$;

REVOKE ALL ON FUNCTION public.twin_identity_propose_binding(uuid, text, text, text, text, numeric, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.twin_identity_propose_binding(uuid, text, text, text, text, numeric, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.twin_identity_propose_binding(uuid, text, text, text, text, numeric, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/hr_prirad_ucet_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: hr_prirad_ucet_admin
-- Popis: HR přiřadí ÚČET k OSOBĚ (twinu) — jedním krokem, atomicky.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT; jen admin/staff S REÁLNOU
--             identitou (lidské rozhodnutí; service_role NE — import navrhuje,
--             člověk potvrzuje)
-- Audit: twin_external_refs.confirmed (píše twin_identity_confirm_binding)
--
-- ⭐ ZADÁNÍ MAJITELE (2026-09-23): obrazovka HR, „účty v KC propojujeme
-- s entitami z twinverse".
--
-- ⛔ ŽÁDNÁ NOVÁ CESTA K ZÁPISU VAZBY. Jen složí dvě existující:
--   twin_identity_propose_binding  → návrh (idempotentní, vrací ref_id)
--   twin_identity_confirm_binding  → lidská ratifikace (confirmed_by = HR)
-- Obě v JEDNÉ transakci: nikdy nezůstane „navrženo, ale nepotvrzeno" jen
-- proto, že druhé volání z prohlížeče nedoběhlo.
--
-- ⭐ ÚČET SMÍ PŘEJÍT K JINÉ OSOBĚ (p_supersede = true na straně ÚČTU): účet
-- navázaný třeba na automaticky založenou osobu (twin_ensure_for_account)
-- se přepojí na řidiče; staré vazbě skončí platnost (valid_to), historie
-- zůstane. Předchozí osoba se vrátí, aby ji UI ukázalo.
--
-- ⛔ OSOBU, KTERÁ UŽ MÁ JINÝ ÚČET, NEPŘEBÍRÁ. „Jeden twin = jeden účet" hlídá
-- uq_twin_external_refs_active_account_twin a důvod je bezpečnostní: přebývající
-- přístup nikdo nenahlásí. Tady se to řekne SROZUMITELNĚ dřív, než by index
-- odpověděl unique_violation — správce musí nejdřív vědomě odvázat ten druhý
-- účet (hr_odvaz_ucet_admin).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.hr_prirad_ucet_admin(
  p_user_id uuid,
  p_twin_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_hr uuid := auth.uid();
  v_jiny_ucet text;
  v_predchozi uuid;
  v_navrh jsonb;
  v_potvrzeni jsonb;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff required';
  END IF;
  IF v_hr IS NULL THEN
    RAISE EXCEPTION 'Assignment requires an authenticated person (auth.uid() is null)';
  END IF;
  IF p_user_id IS NULL OR p_twin_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id and p_twin_id are required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id = p_user_id) THEN
    RAISE EXCEPTION 'account % not found (has it signed in at least once?)', p_user_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.twin_entities t WHERE t.id = p_twin_id AND t.status = 'active') THEN
    RAISE EXCEPTION 'person % not found or not active', p_twin_id;
  END IF;

  -- Osoba už má JINÝ účet → stop (viz hlavička).
  SELECT r.source_key INTO v_jiny_ucet
    FROM public.twin_external_refs r
   WHERE r.twin_id = p_twin_id
     AND r.ref_kind = 'account'
     AND r.state = 'confirmed'
     AND r.valid_to IS NULL
     AND r.source_key <> p_user_id::text
   LIMIT 1;
  IF v_jiny_ucet IS NOT NULL THEN
    RAISE EXCEPTION 'person_has_other_account'
      USING DETAIL = 'Person already bound to another account; unbind it first.',
            HINT = v_jiny_ucet;
  END IF;

  -- Kde je účet navázaný teď (UI ukáže „přesunuto z …").
  SELECT r.twin_id INTO v_predchozi
    FROM public.twin_external_refs r
   WHERE r.ref_kind = 'account'
     AND r.source_key = p_user_id::text
     AND r.state = 'confirmed'
     AND r.valid_to IS NULL
   LIMIT 1;

  v_navrh := public.twin_identity_propose_binding(
    p_twin_id, 'aisha_auth', p_user_id::text, 'account',
    'hr:' || v_hr::text, 1.0, 'HR: přiřazení účtu k osobě');

  IF v_navrh->>'state' = 'confirmed' THEN
    -- Účet už je na TÉTO osobě — nic se nemění.
    RETURN jsonb_build_object('ref_id', v_navrh->>'ref_id', 'already', true,
                              'predchozi_twin_id', NULL);
  END IF;

  v_potvrzeni := public.twin_identity_confirm_binding((v_navrh->>'ref_id')::uuid, true);

  RETURN jsonb_build_object(
    'ref_id', v_potvrzeni->>'ref_id',
    'already', false,
    'superseded_ref_id', v_potvrzeni->>'superseded_ref_id',
    'predchozi_twin_id', CASE WHEN v_predchozi = p_twin_id THEN NULL ELSE v_predchozi END
  );
END;
$$;

REVOKE ALL ON FUNCTION public.hr_prirad_ucet_admin(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.hr_prirad_ucet_admin(uuid, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_ensure_for_account.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_ensure_for_account
-- Popis: Zajistí, že účet (aisha_auth.users.id) má DVOJČE — entitu jádra — a
--        POTVRZENOU referenci ref_kind='account'. ADR-003, program K1.
--        Idempotentní mint-or-match: existující aktivní potvrzená reference
--        účtu vyhrává; jinak se dvojče založí (nebo se použije p_twin_id) a
--        reference účtu se potvrdí SYSTÉMEM (confirmed_by NULL — táž konvence
--        jako primary_id vlastního zdroje v twin_upsert_entity_audited).
--
-- PROČ: audience modul byl klíčovaný na účet (profiles.user_id). Kolega bez
-- účtu, firma ani kontaktní osoba klienta se tak nedaly vyjádřit — dva světy
-- vedle sebe. Od teď je identita dvojče a účet je jedna z jeho referencí.
--
-- PROČ potvrzeno systémem a ne review: reference účtu je dokázaná přihlášením.
-- Cross-source reference (CRM export, pošta) tudy NEJDOU — ty navrhuje
-- twin_identity_propose_binding a potvrzuje člověk (Z2: fakt jen potvrzením).
--
-- KONFLIKT: má-li účet už potvrzené dvojče a volající nabídne jiné p_twin_id,
-- nic se nepřepisuje — na p_twin_id vznikne NÁVRH vazby k review a vrací se
-- dosavadní dvojče. Import nikdy nepřepisuje potvrzené (kontrakt tabulky).
--
-- AUTORIZACE váže SUBJEKT (Z6): služba a operátoři kterýkoli účet, člověk jen
-- svůj. Cizí účet = 42501, ne tiché NULL (existence účtu se neprozrazuje
-- jinak než odmítnutím, které je stejné pro neexistující i cizí).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.twin_ensure_for_account(
  p_user_id     uuid,
  p_label       text DEFAULT NULL,
  p_entity_type text DEFAULT 'person',
  p_twin_id     uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_is_service boolean := public.is_service_role();
  v_caller     uuid    := auth.uid();
  v_twin       uuid;
  v_label      text;
  v_type       text    := COALESCE(nullif(btrim(p_entity_type), ''), 'person');
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required' USING ERRCODE = '22023';
  END IF;
  IF NOT (v_is_service OR public.is_admin_or_staff() OR p_user_id = v_caller) THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM aisha_auth.users u WHERE u.id = p_user_id) THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  -- 1. existující potvrzená aktivní reference účtu vyhrává (mint-or-match)
  SELECT r.twin_id INTO v_twin
  FROM public.twin_external_refs r
  WHERE r.ref_kind = 'account'
    AND r.source_key = p_user_id::text
    AND r.state = 'confirmed'
    AND r.valid_to IS NULL
  ORDER BY r.confirmed_at DESC NULLS LAST
  LIMIT 1;

  IF v_twin IS NOT NULL THEN
    IF p_twin_id IS NOT NULL AND p_twin_id <> v_twin THEN
      -- Jiné dvojče chce tentýž účet: návrh k review, nikdy přepis. Vedlejší
      -- účinek nesmí zničit akt (Z7) — selhání návrhu se jen zaznamená.
      BEGIN
        PERFORM public.twin_identity_propose_binding(
          p_twin_id, 'aisha_auth', p_user_id::text, 'account',
          'twin_ensure_for_account', 0.5, 'account already bound to another twin');
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'twin_ensure_for_account: conflicting binding not proposed (%)', SQLERRM;
      END;
    END IF;
    RETURN v_twin;
  END IF;

  -- 2. štítek: z volání, jinak z profilu (jméno, nakonec e-mail)
  SELECT COALESCE(p_label, nullif(btrim(p.display_name), ''), p.email)
    INTO v_label
  FROM public.profiles p
  WHERE p.user_id = p_user_id;
  v_label := COALESCE(v_label, p_label);

  -- 3. dvojče: dané volajícím, nebo nově ražené s primární identitou účtu
  IF p_twin_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.twin_entities t WHERE t.id = p_twin_id) THEN
      RAISE EXCEPTION 'twin % not found', p_twin_id USING ERRCODE = '22023';
    END IF;
    v_twin := p_twin_id;
  ELSE
    INSERT INTO public.twin_entities (entity_type, label, status, metadata)
    VALUES (v_type, v_label, 'active', '{}'::jsonb)
    RETURNING id INTO v_twin;

    INSERT INTO public.twin_external_refs
      (twin_id, source, source_key, ref_kind, state, proposed_by, confirmed_by, confirmed_at)
    VALUES
      (v_twin, 'aisha_auth', p_user_id::text, 'primary_id', 'confirmed', 'account', NULL, now());
  END IF;

  -- 4. reference účtu — potvrzená systémem (dokázaná přihlášením)
  INSERT INTO public.twin_external_refs
    (twin_id, source, source_key, ref_kind, state, proposed_by, confirmed_by, confirmed_at)
  VALUES
    (v_twin, 'aisha_auth', p_user_id::text, 'account', 'confirmed', 'account', NULL, now());

  -- Audit bez PII: jen id a druh.
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_caller, 'twin_entities.ensure_for_account',
          jsonb_build_object('twin_id', v_twin, 'entity_type', v_type,
                             'minted', p_twin_id IS NULL));
  RETURN v_twin;
END;
$$;

REVOKE ALL ON FUNCTION public.twin_ensure_for_account(uuid, text, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.twin_ensure_for_account(uuid, text, text, uuid) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_backfill_accounts_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_backfill_accounts_admin
-- Popis: Dorodí dvojčata účtům, které ještě žádné nemají (profily založené
--        před ADR-003 / K1). Jednorázově po nasazení, opakovatelně bez
--        vedlejšího účinku (idempotentní přes twin_ensure_for_account).
--        Vrací počet dorozených účtů. p_limit chrání dlouhou transakci na
--        velké instanci — volá se opakovaně, dokud nevrátí 0.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.twin_backfill_accounts_admin(p_limit integer DEFAULT 5000)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  r     record;
  v_n   integer := 0;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;
  FOR r IN
    SELECT p.user_id, COALESCE(nullif(btrim(p.display_name), ''), p.email) AS label
    FROM public.profiles p
    WHERE NOT EXISTS (
      SELECT 1 FROM public.twin_external_refs x
      WHERE x.ref_kind = 'account' AND x.source_key = p.user_id::text
        AND x.state = 'confirmed' AND x.valid_to IS NULL)
    ORDER BY p.created_at
    LIMIT greatest(coalesce(p_limit, 5000), 1)
  LOOP
    PERFORM public.twin_ensure_for_account(r.user_id, r.label, 'person', NULL);
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END;
$$;

REVOKE ALL ON FUNCTION public.twin_backfill_accounts_admin(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.twin_backfill_accounts_admin(integer) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_identity_propose.sql
-- -----------------------------------------------------------------------------

-- Calling-convention wrapper: single-jsonb entrypoint over the scalar
-- twin_identity_propose_binding, so AISHA can propose bindings through the
-- agent_tools contract (dispatcher calls pgrestUser.rpc(handler_ref,{p_params:{...}})).
--
-- Glue only — it unwraps p_params and delegates. ALL logic (idempotence, conflict
-- handling, "never overwrite a confirmed binding", auth) stays in the scalar
-- twin_identity_propose_binding. If domain logic ever creeps in here, that's the
-- recycling anti-pattern (a second proposer) — keep this a pure shape adapter.
--
-- Confirmation is deliberately NOT wrapped: twin_identity_confirm_binding stays a
-- human UI act (pověření), never an AISHA tool. AISHA only proposes.

create or replace function public.twin_identity_propose(p_params jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
begin
  return public.twin_identity_propose_binding(
    (p_params->>'twin_id')::uuid,
    p_params->>'source',
    p_params->>'source_key',
    p_params->>'ref_kind',
    coalesce(nullif(p_params->>'proposed_by', ''), 'rule:aisha'),
    nullif(p_params->>'confidence', '')::numeric,
    nullif(p_params->>'note', '')
  );
end;
$$;

revoke all on function public.twin_identity_propose(jsonb) from public, anon;
grant execute on function public.twin_identity_propose(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_identity_propose_match.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_identity_propose_match
-- Popis: Založí DOPORUČENÍ vazby identity napříč světy (porovnávací pruh
--        ingestu: „tenhle kontakt z CRM vypadá jako tenhle účet"). Obal nad
--        twin_identity_propose_binding, který navíc ctí LIDSKÉ „NE".
--
-- ⛔ ZAMÍTNUTÝ NÁVRH SE NEVRACÍ. twin_identity_propose_binding je idempotentní
-- vůči potvrzeným a navrženým vazbám, ale NE vůči zamítnutým — pruh, který by
-- ho volal každý takt, by rozhodnutí člověka přehlasoval tím, že mu tentýž pár
-- nabídne znovu. Fronta by nikdy nezkonvergovala (týž nález jako u ratifikační
-- fronty mapy toku). Proto se tu zamítnutý pár přeskakuje a řekne se to nahlas
-- ve výsledku, ne mlčky.
--
-- Nic nepotvrzuje: potvrzení je výhradně lidské, z kokpitu přes
-- submit_evidence_review_audited (kind 'twin_identity').
--
-- Vrací: {state: proposed|confirmed|skipped_rejected, ref_id, already, conflict}
-- ============================================================================
CREATE OR REPLACE FUNCTION public.twin_identity_propose_match(
  p_twin_id uuid,
  p_to_source text,
  p_source_key text,
  p_ref_kind text DEFAULT 'primary_id',
  p_proposed_by text DEFAULT 'rule:match',
  p_confidence numeric DEFAULT NULL,
  p_note text DEFAULT NULL)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rejected uuid;
BEGIN
  IF NOT public.is_service_role() AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'twin_identity_propose_match: service role or admin/staff required'
      USING ERRCODE = '42501';
  END IF;

  SELECT r.id INTO v_rejected
  FROM public.twin_external_refs r
  WHERE r.twin_id = p_twin_id
    AND r.source = p_to_source
    AND r.source_key = p_source_key
    AND r.ref_kind = p_ref_kind
    AND r.state = 'rejected'
  ORDER BY r.updated_at DESC NULLS LAST
  LIMIT 1;

  IF v_rejected IS NOT NULL THEN
    RETURN jsonb_build_object('state', 'skipped_rejected', 'ref_id', v_rejected, 'already', true);
  END IF;

  RETURN public.twin_identity_propose_binding(
    p_twin_id, p_to_source, p_source_key, p_ref_kind, p_proposed_by, p_confidence, p_note);
END;
$function$;

REVOKE ALL ON FUNCTION public.twin_identity_propose_match(uuid, text, text, text, text, numeric, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.twin_identity_propose_match(uuid, text, text, text, text, numeric, text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_identity_reject_binding.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_identity_reject_binding
-- Popis: Lidské zamítnutí navržené vazby (proposed → rejected). Řádek zůstává
--        jako záznam rozhodnutí (kdo, kdy, proč) — zamítnutý návrh se
--        idempotentně nevrací do fronty (propose týchž hodnot založí nový
--        řádek, reviewer vidí historii zamítnutí).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT
-- Audit: twin_external_refs.rejected (bez source_key)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_identity_reject_binding(
  p_ref_id uuid,
  p_note text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_reviewer uuid := auth.uid();
  v_ref record;
BEGIN
  -- Lidské rozhodnutí: admin/staff s reálnou identitou (NE service_role)
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff required (human ratification)';
  END IF;
  IF v_reviewer IS NULL THEN
    RAISE EXCEPTION 'Ratification requires an authenticated reviewer (auth.uid() is null)';
  END IF;

  SELECT r.id, r.twin_id, r.source, r.ref_kind, r.state
    INTO v_ref
    FROM public.twin_external_refs r WHERE r.id = p_ref_id;
  IF v_ref.id IS NULL THEN
    RAISE EXCEPTION 'binding % not found', p_ref_id;
  END IF;
  IF v_ref.state <> 'proposed' THEN
    RAISE EXCEPTION 'binding % is %, only proposed can be rejected', p_ref_id, v_ref.state;
  END IF;

  UPDATE public.twin_external_refs
  SET state = 'rejected',
      confirmed_by = v_reviewer,
      confirmed_at = now(),
      note = COALESCE(p_note, note),
      updated_at = now()
  WHERE id = p_ref_id;

  -- Audit log (bez source_key — klíč zdroje může být osobní údaj)
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    v_reviewer,
    'twin_external_refs.rejected',
    jsonb_build_object(
      'ref_id', p_ref_id,
      'twin_id', v_ref.twin_id,
      'source', v_ref.source,
      'ref_kind', v_ref.ref_kind
    )
  );

  RETURN jsonb_build_object('ref_id', p_ref_id, 'state', 'rejected');
END;
$$;

REVOKE ALL ON FUNCTION public.twin_identity_reject_binding(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.twin_identity_reject_binding(uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.twin_identity_reject_binding(uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_identity_resolve.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_identity_resolve
-- Popis: Runtime lookup identity: (source, source_key, ref_kind) → twin_id.
--        Čte VÝHRADNĚ potvrzené a časově platné vazby (autoritativní jen
--        confirmed — návrhy runtime nikdy nevidí). p_at umožňuje historický
--        dotaz „čí byl tenhle čip v čase T" (jízda z minulého měsíce se
--        resolvne na tehdejšího držitele, ne dnešního).
--        Nenalezeno → NULL (ne výjimka): chybějící vazba je běžný stav,
--        adaptér na něj reaguje návrhem (twin_identity_propose_binding).
--        ⭐ p_entity_type (2026-09-27): vazba je jedinečná v rámci DRUHU entity
--        (vozidlo 5 a osoba 5 téhož zdroje jsou dvě vazby). Kdo druh zná, ať ho
--        předá; bez něj jedno dvojče → vrátí ho, víc druhů → výjimka.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_identity_resolve(
  p_source text,
  p_source_key text,
  p_ref_kind text DEFAULT 'primary_id',
  p_at timestamptz DEFAULT NULL,
  p_entity_type text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean := public.is_service_role();
  v_at timestamptz := COALESCE(p_at, now());
  v_twin uuid;
  v_druhu integer;
BEGIN
  -- Authorization check (FIRST, before any data access)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  IF p_source IS NULL OR btrim(p_source) = '' THEN
    RAISE EXCEPTION 'p_source must not be blank';
  END IF;
  IF p_source_key IS NULL OR btrim(p_source_key) = '' THEN
    RAISE EXCEPTION 'p_source_key must not be blank';
  END IF;

  -- Víc DRUHŮ pod týmž klíčem (vozidlo 5 × osoba 5) bez p_entity_type = výjimka,
  -- ne náhodný výběr: tichá záměna řidiče za vozidlo je přesně ta vada, kvůli
  -- které je druh entity v klíči vazby.
  SELECT count(DISTINCT r.entity_type) INTO v_druhu
  FROM public.twin_external_refs r
  WHERE r.source = p_source
    AND r.source_key = p_source_key
    AND r.ref_kind = COALESCE(p_ref_kind, 'primary_id')
    AND r.state = 'confirmed'
    AND r.valid_from <= v_at
    AND (r.valid_to IS NULL OR r.valid_to > v_at)
    AND (p_entity_type IS NULL OR r.entity_type = p_entity_type);
  IF v_druhu > 1 THEN
    RAISE EXCEPTION 'twin_identity_resolve: klíč zdroje % patří % druhům entit — předej p_entity_type', p_source, v_druhu
      USING ERRCODE = '21000';
  END IF;

  SELECT r.twin_id INTO v_twin
  FROM public.twin_external_refs r
  WHERE r.source = p_source
    AND r.source_key = p_source_key
    AND r.ref_kind = COALESCE(p_ref_kind, 'primary_id')
    AND r.state = 'confirmed'
    AND r.valid_from <= v_at
    AND (r.valid_to IS NULL OR r.valid_to > v_at)
    AND (p_entity_type IS NULL OR r.entity_type = p_entity_type)
  ORDER BY r.valid_from DESC
  LIMIT 1;

  RETURN v_twin;
END;
$$;

REVOKE ALL ON FUNCTION public.twin_identity_resolve(text, text, text, timestamptz, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.twin_identity_resolve(text, text, text, timestamptz, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.twin_identity_resolve(text, text, text, timestamptz, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_ids_v_rozsahu.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_ids_v_rozsahu
-- Popis: Dvojčata, která smí volající ČÍST, protože je s nimi spojen vazbou:
--          • identity, na které má platnou vazbu druhu z twin_scope_doc_rules,
--          • jeho vlastní osoba (jen když nějakou takovou vazbu má),
--          • protistrany dokladů v jeho rozsahu (li_doc_slugs_v_rozsahu — z vazeb
--            i z udělených zdrojů dat) —
--            firmy podle IČO (company_ico, ne zamítnuté) nebo podle názvu,
--            stejně jako je dohledává counterparty_resolve.
--        Množinový člen politik twin_entities_read / twin_external_refs_read /
--        twin_relations_read.
--
-- ⭐ PROČ (2026-09-28): karta dlužníka, síť vazeb a registry čtou dvojčata
--   (SECURITY INVOKER). Dvojčata dosud četla jen správa, takže běžný uživatel
--   by viděl faktury dlužníka, ale kartu prázdnou.
--
-- ⛔ Bez vazby a bez uděleného zdroje dat (dokladů ani dvojčat) prázdno — ani vlastní osoba.
--   Řidič s potvrzeným účtem tak nezíská nic nového; tahle funkce mění jen třídy
--   „uživatel s vazbou na identitu" a „uživatel s uděleným zdrojem dat".
--
-- Bezpečnost: SECURITY DEFINER + oracle guard (jen SVŮJ rozsah; service_role /
--   správa za kohokoliv). Správa vidí vše prvním členem politik → prázdno.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_ids_v_rozsahu(p_uid uuid)
RETURNS SETOF uuid
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
BEGIN
  IF p_uid IS NULL
     OR NOT (p_uid = auth.uid() OR public.is_service_role() OR public.is_admin_or_staff()) THEN
    RETURN;
  END IF;
  IF public.is_admin_or_staff(p_uid) THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH osoba AS (
    SELECT a.twin_id
      FROM public.twin_external_refs a
     WHERE a.ref_kind = 'account' AND a.state = 'confirmed'
       AND a.source_key = p_uid::text
       AND a.valid_from <= now() AND (a.valid_to IS NULL OR a.valid_to > now())
  ),
  identita AS (
    SELECT DISTINCT v.source_twin_id AS osoba_id, v.target_twin_id AS twin_id
      FROM osoba o
      JOIN public.twin_relations v ON v.source_twin_id = o.twin_id
     WHERE v.valid_from <= now() AND (v.valid_to IS NULL OR v.valid_to > now())
       AND EXISTS (SELECT 1 FROM public.twin_scope_doc_rules p
                    WHERE p.is_active AND p.relation_kind = v.relation_kind)
  ),
  -- Protistrany dokladů v rozsahu z předpočítaných klíčů (bez rozbalování fields).
  protistrana AS (
    SELECT s.field_key, s.hodnota
      FROM public.li_doc_scope_keys s
     WHERE s.field_key IN ('counterparty_id', 'counterparty')
       AND s.doc_slug IN (SELECT public.li_doc_slugs_v_rozsahu(p_uid))
  )
  SELECT i.twin_id FROM identita i
  UNION
  SELECT i.osoba_id FROM identita i
  UNION
  SELECT r.twin_id
    FROM public.twin_external_refs r
   WHERE r.ref_kind = 'company_ico' AND r.state <> 'rejected'
     AND r.source_key IN (SELECT p.hodnota FROM protistrana p WHERE p.field_key = 'counterparty_id')
  UNION
  SELECT t.id
    FROM public.twin_entities t
   WHERE t.entity_type = 'company' AND t.status = 'active'
     AND lower(btrim(t.label)) IN (SELECT p.hodnota FROM protistrana p WHERE p.field_key = 'counterparty')
  UNION
  -- ⭐ UDĚLENÝ ZDROJ DVOJČAT (2026-09-28, majitel: „všechna data, ale rozdělená po zdrojích"):
  -- `udalosti:<zdroj>` pustí dvojčata, o kterých ten zdroj nese data (twin_events.source) —
  -- např. jednotky ze sez-vyuctovani s nájemcem a obsazeností.
  SELECT DISTINCT e.twin_id
    FROM public.data_source_grants g
    JOIN public.twin_events e ON lower(g.zdroj) = 'udalosti:' || lower(e.source)
   WHERE g.user_id = p_uid;
END;
$$;

REVOKE ALL ON FUNCTION public.twin_ids_v_rozsahu(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.twin_ids_v_rozsahu(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.twin_ids_v_rozsahu(uuid) TO service_role;

COMMENT ON FUNCTION public.twin_ids_v_rozsahu(uuid) IS
  'Dvojčata čitelná z vazeb: identity s platnou vazbou (druh z twin_scope_doc_rules), vlastní osoba a protistrany dokladů v rozsahu (IČO / název). Bez vazby prázdno.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_list_mine.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_list_mine
-- Popis: „Moje věci" — twiny přiřazené přihlášenému uživateli. Model majitele
--        (07-17): ŽÁDNÁ role „řidič" — právo = přístup k části (modulu),
--        a uživatel s právem vidí SVOJE věci přes přiřazení twinu:
--        doklad → Ride/Vehicle twin → (account ref) → uživatel.
--        Konvence vazby: twin_external_refs s ref_kind='account' a
--        source_key = uuid platformního uživatele (source = slug IdP,
--        např. 'keycloak' — na slugu NEzáleží, vazba se hledá jen přes
--        ref_kind + source_key = auth.uid()). Vzniká ratifikací
--        (twin_identity_propose/confirm_binding) — nikdy automaticky.
--        Vrací jen potvrzené, časově platné vazby. Přístupné KAŽDÉMU
--        přihlášenému (scoping = vlastní uid, žádná data cizích).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_list_mine(
  p_entity_type text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_items jsonb;
BEGIN
  -- Scoping na vlastní identitu — bez přihlášení není „moje"
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: authenticated user required';
  END IF;

  SELECT COALESCE(jsonb_agg(item ORDER BY item->>'label'), '[]'::jsonb) INTO v_items
  FROM (
    SELECT jsonb_build_object(
      'twin_id', t.id,
      'entity_type', t.entity_type,
      'label', t.label,
      'status', t.status,
      'bound_since', r.valid_from
    ) AS item
    FROM public.twin_external_refs r
    JOIN public.twin_entities t ON t.id = r.twin_id
    WHERE r.ref_kind = 'account'
      AND r.source_key = v_uid::text
      AND r.state = 'confirmed'
      AND r.valid_from <= now()
      AND (r.valid_to IS NULL OR r.valid_to > now())
      AND (p_entity_type IS NULL OR t.entity_type = p_entity_type)
  ) AS q;

  RETURN v_items;
END;
$$;

REVOKE ALL ON FUNCTION public.twin_list_mine(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.twin_list_mine(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.twin_list_mine(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_param_values.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_param_values
-- Popis: Hodnoty JEDNOHO parametru dvojčat v čase — a jediné místo v jádře,
--        které ví, KDE ta hodnota leží. Kde přesně, říká katalog
--        (`twin_parameter_definitions.metadata`), tedy DATA instance:
--          {"event_type":"trip","attr":"distance_km"}  → veličina v atributu události
--          {"shape":"code_value"}                      → dvojice {code,value}
--                                                        (vzor seedů a get_twin_register)
--        a volitelně PŘEVOD do jednotky parametru:
--          {"scale":0.001}      hodnota × 0,001   (kg → t)
--          {"scale_div":3600}   hodnota ÷ 3600    (s → h; dělení je přesné
--                                                  a čitelnější než 0,000277…)
--        Převod patří sem, protože `unit` je vlastnost PARAMETRU: tachograf
--        posílá sekundy, ale parametr „doba řízení" je v hodinách pro každý
--        blok stejně. Kdyby si násobil každý blok, dvě dlaždice nad týmž
--        parametrem by se mohly lišit — a porovnání se zákonným limitem
--        (561/2006) by záviselo na tom, kdo blok deklaroval.
--        U ADITIVNÍ veličiny (aggregation 'sum' / historization 'event_log')
--        katalog navíc určuje AUTORITU: počítají se jen události zdroje
--        z `source` (nebo jeho dráhy '<source>:…'). Jinak by jízda, kterou
--        hlásí dva dodavatelé, přičetla kilometry dvakrát. Hodnoty se stavem
--        zůstávají vícezdrojové. Nálezy katalogu: twin_catalog_source_findings.
--        Čtečky ploch pak neznají ani typ události, ani jméno atributu: doména
--        je řádek v katalogu, ne řádek v kódu (ADR-003 §3, zákon jmen).
--
-- ⛔ PROČ VZNIKL: do 2026-09 se každá otázka nad flotilou psala jako vlastní
--        funkce (šest `get_fleet_*` se jmény událostí, atributů a limitů uvnitř
--        jádra). Další doména by znamenala další šestici. Tenhle pomocník je
--        šev, za kterým se domény střídají beze změny kódu.
--
-- Nečíselná hodnota se vrací jako NULL, ne jako nula: „nepřečetl jsem to"
--        není „naměřil jsem nulu" (týž zákon jako `value: null` u kpi_tile).
--
-- Bezpečnost: SECURITY INVOKER — o tom, kdo co uvidí, rozhoduje RLS na
--        `twin_events`/`twin_entities`, ne tahle funkce. Fail-closed: bez
--        práva prostě nepřijdou žádné řádky.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.twin_param_values(
  p_code        text,
  p_from        timestamptz DEFAULT NULL,
  p_to          timestamptz DEFAULT NULL,
  p_entity_type text        DEFAULT NULL
)
RETURNS TABLE (twin_id uuid, twin_label text, occurred_at timestamptz, value numeric, source text)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
  WITH def AS (
    SELECT
      d.code,
      COALESCE(d.metadata->>'shape', 'attr')                         AS shape,
      -- Tvar {code,value} má dohodnutý typ události; atributový tvar ho MUSÍ
      -- deklarovat — bez něj by čtečka sáhla přes všechny typy najednou.
      COALESCE(d.metadata->>'event_type',
               CASE WHEN d.metadata->>'shape' = 'code_value'
                    THEN 'twin_parameter' END)                       AS event_type,
      d.metadata->>'attr'                                            AS attr,
      -- Druh entity z katalogu je výchozí; volající ho smí zúžit, ne rozšířit.
      NULLIF(COALESCE(d.metadata->>'entity_type', d.entity_type), '') AS entity_type,
      -- Nečíselný (nebo nulový) převod se IGNORUJE, ne aby dělil nulou:
      -- překlep v katalogu nesmí shodit plochu, jen zůstane původní jednotka.
      CASE WHEN d.metadata->>'scale' ~ '^-?[0-9]+(\.[0-9]+)?$'
                AND (d.metadata->>'scale')::numeric <> 0
           THEN (d.metadata->>'scale')::numeric ELSE 1 END                AS scale_mul,
      CASE WHEN d.metadata->>'scale_div' ~ '^-?[0-9]+(\.[0-9]+)?$'
                AND (d.metadata->>'scale_div')::numeric <> 0
           THEN (d.metadata->>'scale_div')::numeric ELSE 1 END            AS scale_div,
      -- AUTORITA ZDROJE jen pro ADITIVNÍ veličinu (součet, záznam událostí):
      -- tam by dva zdroje TÉŽE jízdy/tankování sečetly kilometry či litry
      -- dvakrát. Hodnota se stavem (`last`) smí mít zdrojů víc — vyhraje
      -- poslední a původ je vidět (IČO z rejstříku i z dokladů je legitimní).
      CASE WHEN lower(COALESCE(d.aggregation, '')) = 'sum'
             OR lower(COALESCE(d.historization, '')) = 'event_log'
           THEN NULLIF(btrim(d.source), '') END                           AS autorita
    FROM public.twin_parameter_definitions d
    WHERE d.code = p_code
  )
  SELECT
    e.twin_id,
    t.label,
    e.occurred_at,
    -- Bez zaokrouhlení: zaokrouhluje se až AGREGÁT. Kdyby se ořezávala každá
    -- hodnota, týdenní součet 7 dní by se od pravdy lišil o minuty — a proti
    -- limitu 56 h se minuty počítají.
    CASE WHEN r.raw ~ '^-?[0-9]+(\.[0-9]+)?$'
         THEN r.raw::numeric * d.scale_mul / d.scale_div END,
    e.source
  FROM def d
  JOIN public.twin_events e
    ON e.event_type = d.event_type
   AND (d.shape <> 'code_value' OR e.attrs->>'code' = d.code)
  JOIN public.twin_entities t
    ON t.id = e.twin_id
  CROSS JOIN LATERAL (
    SELECT CASE WHEN d.shape = 'code_value' THEN e.attrs->>'value'
                ELSE e.attrs->>d.attr END AS raw
  ) r
  WHERE (p_from IS NULL OR e.occurred_at >= p_from)
    AND (p_to   IS NULL OR e.occurred_at <  p_to)
    -- ZÚŽENÍ, ne přebití: platí OBĚ podmínky, takže volající smí množinu jen
    -- zmenšit. Do 2026-09-20 tu stálo `COALESCE(p_entity_type, d.entity_type)`,
    -- což katalogovou deklaraci PŘEBÍJELO — blok si mohl říct o jiný druh
    -- entity, než parametr popisuje, a dostal data z cizí domény. Komentář
    -- sliboval zúžení, kód dělal záměnu; teď to vynucuje kód.
    -- Nesouhlasná dvojice nevrátí nic: konfigurační chyba se přizná jako
    -- NEMĚŘENO, což je pravdivější než čísla, o která nikdo nežádal.
    AND (d.entity_type IS NULL OR t.entity_type = d.entity_type)
    AND (p_entity_type IS NULL OR t.entity_type = p_entity_type)
    -- Autorita: událost od zdroje, kterého katalog jmenuje, nebo z jeho dráhy
    -- ('eurowag-telematics:trip' pro 'eurowag-telematics'). `starts_with`,
    -- ne LIKE — podtržítko ve slugu by bylo zástupný znak. Volba zdroje je
    -- DATA katalogu (administrace), ne kód; radši veličinu neukázat než
    -- ukázat sečtenou ze dvou zdrojů. Katalog jmenující zdroj, který nic
    -- nezapsal nebo neexistuje, hlásí twin_catalog_source_findings — nahlas.
    AND (d.autorita IS NULL
         OR e.source = d.autorita
         OR starts_with(e.source, d.autorita || ':'));
$$;

COMMENT ON FUNCTION public.twin_param_values(text, timestamptz, timestamptz, text) IS
  'Hodnoty parametru dvojčat v okně; kde hodnota leží a v jaké jednotce, říká katalog (metadata.event_type/attr nebo shape=code_value, volitelně scale/scale_div). SECURITY INVOKER — vidí jen to, co pustí RLS.';

REVOKE ALL ON FUNCTION public.twin_param_values(text, timestamptz, timestamptz, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.twin_param_values(text, timestamptz, timestamptz, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.twin_param_values(text, timestamptz, timestamptz, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_twin_metric_kpi_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_twin_metric_kpi_block
-- Popis: GENERICKÁ dlaždice čísla (maska `kpi_tile`) nad substrátem dvojčat.
--        Co se počítá, říká KONFIGURACE bloku, ne kód: `param` je kód
--        z katalogu (`twin_parameter_definitions`), `agg` je uzavřená množina
--        agregací a okno je od–do. Sourozenec `get_audience_view_kpi_block`
--        (tamtéž nad pohledy publika), jen substrát je jiný.
--
-- Konfigurace (p_params):
--   param        POVINNÉ   kód parametru v katalogu
--   agg          volitelné sum (default) | avg | count | count_distinct | last
--                          | max | min | ratio | days_since_last
--                          UZAVŘENÁ množina; neznámá hodnota degraduje na 'sum'
--   per_param    u `ratio` POVINNÉ — jmenovatel (Σ param / Σ per_param)
--   factor       u `ratio` volitelné násobení (l/100 km = Σ l / Σ km × 100)
--   entity_type  volitelné zúžení druhu entity (katalog dává výchozí)
--   date_from,
--   date_to      volitelné ABSOLUTNÍ okno ('YYYY-MM-DD' nebo ISO čas)
--   days         volitelné relativní okno (default 7), když od–do nepřijde
--   tz           volitelné pásmo, ve kterém se čte HOLÉ datum a v němž
--                          začíná den (default 'UTC'). Pro dopravce v Česku
--                          patří do bloku 'Europe/Prague': den začíná půlnocí
--                          v Praze, ne v Londýně — jízda v 00:30 by jinak
--                          spadla do předchozího dne. Neznámé pásmo degraduje
--                          na UTC, nezhasne blok.
--   compare      volitelné 'previous' → delta_pct proti stejně dlouhému oknu PŘED
--   unit_key     volitelné i18n klíč jednotky
--   state        volitelné 'ok' (default) | 'warning' | 'loss' — STAV JE
--                          DEKLARACE: funkce neví, jestli je víc lépe, nebo hůř
--
-- ⭐ `value: null` = NEMĚŘENO a je to platná odpověď: prázdné okno, parametr,
--    který katalog nezná, i chybějící právo vypadají stejně — nula by tvrdila
--    měření, které nikdo neprovedl. Důvod nese `trace_id`, ne data. Platí to
--    i pro POČÍTADLA: `count`/`count_distinct` nad prázdnem vrací 0, ale „nic
--    nejezdilo" a „nikdo neměřil" jsou dvě různé věty a substrát je nerozliší.
--
-- Provenance se ODVOZUJE z dat: `source_slug` je seznam zdrojů, které do okna
--    přispěly, `freshness_at` je čas POSLEDNÍ hodnoty (ne `now()` — čerstvost
--    měřidla není čerstvost dotazu). Bez dat je čerstvost `now()` a trace
--    končí `:no_data`, aby se prázdno nedalo číst jako aktuální nula.
--
-- Bezpečnost: SECURITY INVOKER — RLS na twin_* fail-closed (viz twin_param_values).
-- Kontrakt: (jsonb) -> jsonb {data:{value,unit_key,delta_pct,state}, provenance}.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.get_twin_metric_kpi_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_param    text := NULLIF(btrim(COALESCE(p_params->>'param', '')), '');
  v_per      text := NULLIF(btrim(COALESCE(p_params->>'per_param', '')), '');
  v_factor   numeric := COALESCE((p_params->>'factor')::numeric, 1);
  v_agg      text := lower(COALESCE(NULLIF(btrim(COALESCE(p_params->>'agg', '')), ''), 'sum'));
  v_entity   text := NULLIF(btrim(COALESCE(p_params->>'entity_type', '')), '');
  v_unit     text := NULLIF(btrim(COALESCE(p_params->>'unit_key', '')), '');
  v_state    text := lower(COALESCE(NULLIF(btrim(COALESCE(p_params->>'state', '')), ''), 'ok'));
  v_compare  text := lower(COALESCE(NULLIF(btrim(COALESCE(p_params->>'compare', '')), ''), ''));
  v_tz      text := COALESCE(NULLIF(btrim(COALESCE(p_params->>'tz', '')), ''), 'UTC');
  v_now      timestamptz := now();
  v_from     timestamptz;
  v_to       timestamptz;
  v_len      interval;
  v_value    numeric;
  v_prev     numeric;
  v_delta    numeric;
  v_fresh    timestamptz;
  v_sources  text;
  v_reason   text := '';
BEGIN
  -- Neznámé pásmo (překlep v deklaraci bloku) NESMÍ shodit plochu: degraduje
  -- na UTC. Ověřuje se proti katalogu pásem, ne proti vlastnímu seznamu.
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names z WHERE z.name = v_tz) THEN v_tz := 'UTC'; END IF;

  IF v_agg NOT IN ('sum','avg','count','count_distinct','last','max','min','ratio','days_since_last')
    THEN v_agg := 'sum'; END IF;
  IF v_state NOT IN ('ok','warning','loss') THEN v_state := 'ok'; END IF;

  -- Okno: ABSOLUTNÍ přebíjí relativní. Tvar se OVĚŘUJE, nepřetypovává naslepo —
  -- překlep v datu jinak neshodí filtr, ale celý blok.
  IF p_params->>'date_from' ~ '^\d{4}-\d{2}-\d{2}' AND p_params->>'date_to' ~ '^\d{4}-\d{2}-\d{2}' THEN
    -- Holé datum = půlnoc V PÁSMU BLOKU; údaj s časem zůstává absolutním
    -- okamžikem (kdo pošle čas i posun, ví, co chce).
    v_from := CASE WHEN p_params->>'date_from' ~ '^\d{4}-\d{2}-\d{2}$'
                   THEN (p_params->>'date_from')::timestamp AT TIME ZONE v_tz
                   ELSE (p_params->>'date_from')::timestamptz END;
    -- Den „do" je včetně: konec okna je půlnoc NÁSLEDUJÍCÍHO dne v témže pásmu.
    v_to := CASE WHEN p_params->>'date_to' ~ '^\d{4}-\d{2}-\d{2}$'
                 THEN ((p_params->>'date_to')::date + 1)::timestamp AT TIME ZONE v_tz
                 ELSE (p_params->>'date_to')::timestamptz END;
  ELSE
    v_to   := v_now;
    v_from := v_now - make_interval(days => GREATEST(COALESCE((p_params->>'days')::int, 7), 1));
  END IF;
  v_len := v_to - v_from;

  IF v_param IS NULL OR (v_agg = 'ratio' AND v_per IS NULL) THEN
    RETURN jsonb_build_object(
      'data', jsonb_build_object('value', NULL, 'state', v_state),
      'provenance', jsonb_build_object(
        'source_slug', 'twin-metric',
        'freshness_at', to_char(v_now AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'trace_id', 'twin-metric-kpi:missing_config'));
  END IF;

  -- Katalog rozhoduje, kde hodnota leží; parametr, který nezná, je NEMĚŘENO
  -- (ne pád) — plocha smí být napřed před slovníkem, ale nesmí si vymýšlet.
  IF NOT EXISTS (SELECT 1 FROM public.twin_parameter_definitions d WHERE d.code = v_param) THEN
    v_reason := ':unknown_param';
  END IF;

  SELECT
    CASE v_agg
      WHEN 'sum'            THEN sum(v.value)
      WHEN 'avg'            THEN avg(v.value)
      WHEN 'count'          THEN count(*)::numeric
      WHEN 'count_distinct' THEN count(DISTINCT v.twin_id)::numeric
      WHEN 'max'            THEN max(v.value)
      WHEN 'min'            THEN min(v.value)
      WHEN 'days_since_last' THEN floor(extract(epoch FROM (v_now - max(v.occurred_at))) / 86400)
      ELSE NULL
    END,
    max(v.occurred_at),
    string_agg(DISTINCT v.source, '+' ORDER BY v.source)
  INTO v_value, v_fresh, v_sources
  FROM public.twin_param_values(v_param, v_from, v_to, v_entity) v;

  IF v_agg = 'last' THEN
    SELECT v.value INTO v_value
    FROM public.twin_param_values(v_param, v_from, v_to, v_entity) v
    WHERE v.value IS NOT NULL
    ORDER BY v.occurred_at DESC
    LIMIT 1;
  ELSIF v_agg = 'ratio' THEN
    -- Vážený poměr: Σ čitatele / Σ jmenovatele. NE průměr poměrů po řádcích —
    -- ten dá krátké jízdě tutéž váhu jako dlouhé a l/100 km pak lže.
    SELECT v_factor * sum(v.value)
                 / NULLIF((SELECT sum(w.value)
                           FROM public.twin_param_values(v_per, v_from, v_to, v_entity) w), 0)
    INTO v_value
    FROM public.twin_param_values(v_param, v_from, v_to, v_entity) v;
  END IF;

  -- ⭐ POČÍTADLO NAD PRÁZDNEM není nula. `count`/`count_distinct` vrátí nad
  -- prázdnou množinou 0, a dlaždice „aktivní vozidla" by tak tvrdila „žádné
  -- nejezdí" i tam, kde jen nikdo neměří. Rozlišit „zdroj mlčí" od „nic se
  -- nedělo" substrát neumí — a když to neumí, je pravdivá odpověď NEMĚŘENO.
  -- `v_fresh` je NULL přesně tehdy, když do okna nepřišel ani jeden řádek.
  IF v_fresh IS NULL THEN v_value := NULL; END IF;

  -- Zaokrouhlení JEDNOU, až nad hotovou agregací — hodnoty přicházejí v jednotce
  -- parametru (katalog umí převod s → h) a ta dává periodická desetinná místa.
  v_value := trim_scale(round(v_value, 2));

  IF v_compare = 'previous' AND v_value IS NOT NULL AND v_agg <> 'days_since_last' THEN
    SELECT
      CASE v_agg
        WHEN 'sum'            THEN sum(v.value)
        WHEN 'avg'            THEN avg(v.value)
        WHEN 'count'          THEN count(*)::numeric
        WHEN 'count_distinct' THEN count(DISTINCT v.twin_id)::numeric
        WHEN 'max'            THEN max(v.value)
        WHEN 'min'            THEN min(v.value)
        ELSE NULL
      END
    INTO v_prev
    FROM public.twin_param_values(v_param, v_from - v_len, v_from, v_entity) v;

    IF v_agg = 'ratio' THEN
      SELECT v_factor * sum(v.value)
                   / NULLIF((SELECT sum(w.value)
                             FROM public.twin_param_values(v_per, v_from - v_len, v_from, v_entity) w), 0)
      INTO v_prev
      FROM public.twin_param_values(v_param, v_from - v_len, v_from, v_entity) v;
    ELSIF v_agg = 'last' THEN
      SELECT v.value INTO v_prev
      FROM public.twin_param_values(v_param, v_from - v_len, v_from, v_entity) v
      WHERE v.value IS NOT NULL
      ORDER BY v.occurred_at DESC
      LIMIT 1;
    END IF;

    -- Srovnávané období projde TOUTÉŽ cestou: kdyby se zaokrouhlilo jen jedno
    -- z čísel, změna by se vykázala i tam, kde se nic nestalo. A prázdné
    -- minulé období je taky NEMĚŘENO — nula by vyrobila skok o 100 %.
    IF NOT EXISTS (SELECT 1 FROM public.twin_param_values(v_param, v_from - v_len, v_from, v_entity))
      THEN v_prev := NULL; END IF;
    v_prev := trim_scale(round(v_prev, 2));

    IF v_prev IS NOT NULL AND v_prev <> 0 THEN
      v_delta := round((v_value - v_prev) / abs(v_prev) * 100, 1);
    END IF;
  END IF;

  IF v_value IS NULL AND v_reason = '' THEN v_reason := ':no_data'; END IF;

  -- `value` stojí MIMO jsonb_strip_nulls: null je tu odpověď (NEMĚŘENO), ne
  -- chybějící pole. Maska kpi_tile má `value` povinné a null výslovně povoluje;
  -- kdyby ho strip smazal, shell celou dlaždici zahodí jako porušení kontraktu
  -- (naměřeno v produkci 2026-09-24: 7/7 dlaždic vozového parku bez dat zmizelo).
  -- Ostatní klíče null nesmí nést vůbec, proto je strip dál čistí.
  RETURN jsonb_build_object(
    'data', jsonb_build_object('value', v_value)
            || jsonb_strip_nulls(jsonb_build_object(
                 'unit_key', v_unit,
                 'delta_pct', v_delta,
                 'state', v_state)),
    'provenance', jsonb_build_object(
      'source_slug', COALESCE(v_sources, 'twin-metric'),
      'freshness_at', to_char(COALESCE(v_fresh, v_now) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id', 'twin-metric-kpi:' || v_param || ':' || v_agg || v_reason));
END;
$$;

COMMENT ON FUNCTION public.get_twin_metric_kpi_block(jsonb) IS
  'Generická dlaždice čísla nad dvojčaty: parametr z katalogu × uzavřená agregace × okno od–do; hodnota null = NEMĚŘENO, provenance z dat.';

REVOKE ALL ON FUNCTION public.get_twin_metric_kpi_block(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_twin_metric_kpi_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_twin_metric_kpi_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_twin_register.sql
-- -----------------------------------------------------------------------------

-- Data RPC for a 'table' block: a domain register over the twin substrate.
-- ONE generic reader serves ANY entity_type (meter, and every future domain)
-- because the domain is a PARAMETER (p_params->>'entity_type'), not code — a new
-- analytical area is a row in surface_blocks with different source_params, never a
-- new function. Columns are derived from twin_parameter_definitions for that type;
-- each row is a twin_entity plus its latest value per parameter from twin_events.
--
-- Seam, not new domain: it is a pure READ join of three existing substrates
-- (twin_entities × twin_events × twin_parameter_definitions) exposed through the
-- existing get_block_data dispatcher, mirroring get_document_register/get_obligation_queue.
-- SECURITY INVOKER → RLS on twin_* fails closed (non-staff get an empty register,
-- not an error), same doctrine as the li_* readers.
--
-- Contract: (jsonb) -> jsonb {data:{entity_kind, columns[], rows[]}, provenance}.

create or replace function public.get_twin_register(p_params jsonb default '{}'::jsonb)
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with cfg as (
    -- ⭐ OSA „PODLE FIRMY" (2026-09-28). Zvolená firma (`owner_company`, hodnota z hlavičky
    -- dokladu) chodí do každého bloku sekce, ale registr twinů ji nemá kde přečíst —
    -- twin nemá hlavičku. Jak firmu na doménu PŘELOŽIT, řekne konfigurace bloku
    -- (`source_params.scope_map.owner_company`), protože u jednotek a u nájemců je to jiná
    -- cesta a obě musí vést přes IDENTITU, ne přes jméno (jméno není identita —
    -- counterparty_resolve; naměřeno 2026-09-28: pronajímatel „Areál Avant Ďáblická,
    -- družstvo" u 23 jednotek ≠ agenda „Areál Avant Ďáblická", textová shoda by je tiše ztratila):
    --   via 'doc_field' {param, doc_field}   twin, jehož poslední hodnota parametru `param`
    --        je v poli `doc_field` některého platného dokladu té firmy (nájemce ↔ IČO
    --        protistrany dokladů: company_ico ∈ counterparty_id).
    --   via 'relation' {relation_kind, target_ref}   twin s PLATNOU vazbou `relation_kind`
    --        (twin = zdroj hrany) na twin, který nese POTVRZENÝ odkaz `target_ref` s klíčem
    --        = zvolená firma (jednotka —pronajimatel→ naše firma; „naše firma" potvrzuje člověk).
    -- Bez konfigurace blok osu nečte a neohlásí ji (scope_applied) — klient ho označí jako
    -- nefiltrovaný. Neznámé `via` = totéž, nic se neodhaduje.
    select nullif(p_params->>'owner_company', '')                      as firma,
           p_params#>>'{scope_map,owner_company,via}'                  as via,
           p_params#>>'{scope_map,owner_company,param}'                as param,
           p_params#>>'{scope_map,owner_company,doc_field}'            as doc_field,
           p_params#>>'{scope_map,owner_company,relation_kind}'        as rel_kind,
           p_params#>>'{scope_map,owner_company,target_ref}'           as target_ref
  ),
  cols as (
    -- Leading 'label' column = the entity name (twin.label), so a register row reads
    -- "which entity + its parameters" (the mobile BlockRenderer shows the first 3 columns).
    select (
      jsonb_build_array(jsonb_build_object(
        'key', 'label', 'label', 'Název', 'label_key', 'app.twins.col.label', 'align', 'left'
      ))
      || coalesce(jsonb_agg(
             jsonb_build_object(
               'key',       d.code,
               'label',     d.name,
               'label_key', 'app.twins.col.' || d.code,
               'unit',      d.unit,
               'align',     case when d.data_type in ('decimal','numeric','integer','number') then 'right' else 'left' end
             ) order by d.code
           ), '[]'::jsonb)
    ) as columns
    from public.twin_parameter_definitions d
    where d.entity_type = coalesce(nullif(p_params->>'entity_type', ''), 'meter')
      -- Registr ukazuje, JAKÁ entita je (stav, atributy), ne kolik se jí za okno
      -- přihodilo. Veličina vedená jako záznam událostí (`event_log`: ujeto,
      -- natankováno) „poslední hodnotu" nemá — patří do dlaždice nebo tabulky
      -- s oknem, ne do sloupce, který by zůstal navždy prázdný (produkce RIQ
      -- 2026-09-24: čtyři sloupce registru vozidel samé „—").
      and coalesce(d.historization, '') <> 'event_log'
  ),
  -- Kódy, jejichž hodnotu katalog vede v atributu události (čte je `latest_ev`).
  -- MATERIALIZED = katalog pod RLS se projde JEDNOU. Jako `not exists` přímo
  -- v `latest_cv` z něj planner udělal Nested Loop Anti Join a katalog procházel
  -- pro KAŽDOU událost: produkce 581 × ~1,1 ms = 646 ms, i u druhu bez jediné takové
  -- definice (jednotky 0,2–0,6 s → 1,0–1,3 s; 2026-09-30).
  kody_udalosti as materialized (
    select dd.code from public.twin_parameter_definitions dd where dd.metadata ? 'event_type'
  ),
  -- Hodnota ve tvaru {code,value} (atributy: RZ, VIN, jednotka…).
  latest_cv as (
    select distinct on (e.twin_id, e.attrs->>'code')
      e.twin_id,
      e.attrs->>'code'  as code,
      e.attrs->>'value' as val,
      e.occurred_at
    from public.twin_events e
    join public.twin_entities t on t.id = e.twin_id
    where t.entity_type = coalesce(nullif(p_params->>'entity_type', ''), 'meter')
      and e.attrs ? 'code'
      -- Kód, jehož hodnotu katalog vede v atributu události, se čte níž švem —
      -- jinak by jeden sloupec měl dva zdroje a vyhrál by ten náhodný.
      and not exists (select 1 from kody_udalosti k where k.code = e.attrs->>'code')
    order by e.twin_id, e.attrs->>'code', e.occurred_at desc
  ),
  -- Hodnota, která podle KATALOGU leží v atributu události (časová řada: hladina,
  -- tachometr). Čte se týmž švem jako čtečky veličin (`twin_param_values`), takže
  -- jednotku a převod určuje katalog na jednom místě, ne tady.
  -- `twin_param_values` má SET search_path, takže se NEinlinuje (Function Scan,
  -- ROWS 1000). Volá se po DEFINICI, ne po twinu — proto odhad drží a JIT nenaskočí.
  -- Nepřesouvat do laterálu po twinu (2026-09-30, Optimalizace).
  latest_ev as (
    select distinct on (v.twin_id, d.code)
      v.twin_id,
      d.code,
      trim_scale(v.value)::text as val,
      v.occurred_at
    from public.twin_parameter_definitions d
    cross join lateral public.twin_param_values(d.code, null, null, d.entity_type) v
    where d.entity_type = coalesce(nullif(p_params->>'entity_type', ''), 'meter')
      and d.metadata ? 'event_type'
      and coalesce(d.historization, '') <> 'event_log'
      and v.value is not null
    order by v.twin_id, d.code, v.occurred_at desc
  ),
  latest as (
    select twin_id, code, val, occurred_at from latest_cv
    union all
    select twin_id, code, val, occurred_at from latest_ev
  ),
  -- Hodnoty pole `doc_field` v platných dokladech zvolené firmy (osa přes `doc_field`).
  -- MATERIALIZED = spočítá se JEDNOU a každé další čtení bere hotový výsledek. Bez plotu
  -- planner (latest odhadne na 1 řádek, skutečně 69) prošel celý registr dokladů pro
  -- KAŽDÝ řádek latest: nájemci se zvolenou firmou 19–35 s (69 × 38 186 dokladů firmy,
  -- 2,6 mil. rozbalení jsonb; 2026-09-30). Mimo `doc_field` se nečte vůbec (one-time filtr).
  doc_hodnoty as materialized (
    select distinct d.fields->(select doc_field from cfg)->>'value' as val
      from public.li_source_registry d
     where (select via from cfg) = 'doc_field'
       and (select firma from cfg) is not null
       and d.superseded_by is null
       and d.fields->'owner_company'->>'value' = (select firma from cfg)
  ),
  reg as (
    select
      t.id::text as id,
      t.label,
      coalesce(jsonb_object_agg(l.code, l.val) filter (where l.code is not null), '{}'::jsonb) as vals,
      max(l.occurred_at) as _sort
    from public.twin_entities t
    left join latest l on l.twin_id = t.id
    where t.entity_type = coalesce(nullif(p_params->>'entity_type', ''), 'meter')
      and t.status = 'active'
      -- `has_param`: jen entity, o kterých TO KONKRÉTNÍ víme. Bez toho filtru vrací
      -- registr celou doménu — u firem 1 354 protistran z účetnictví místo devadesáti
      -- nájemců, a z přehledu je zase sklad. Doména není totéž co množina, na kterou
      -- se ptáme; filtr je proto parametr bloku, ne nová funkce.
      --
      -- ⛔ FILTRY NÍŽ JSOU NEKORELOVANÉ `t.id in (…)`, NE `exists (… = t.id)` (2026-09-30).
      -- Korelovanou EXISTS pod OR planner převede na AlternativeSubPlan a OCENÍ ji první
      -- (řádkovou) variantou, i když za běhu použije hashovanou: rameno `doc_field`
      -- (Hash Semi Join 33 180) × řádky twinů → odhad 132,7 mil. → plný JIT (268 funkcí)
      -- u KAŽDÉHO registru, i u 12 vozidel: 2,0–2,4 s místo 130–240 ms, výstup shodný.
      -- Nekorelovaný IN je hashovaný SubPlan oceněný JEDNOU. Týž vzor jako věž a časová
      -- osa (kolo 13); hlídá brána korelovana-exists-pod-or.
      and (nullif(p_params->>'has_param','') is null
           or t.id in (select he.twin_id from public.twin_events he
                        where he.attrs->>'code' = p_params->>'has_param'))
      -- `param_eq` {kód: hodnota}: jen entity, jejichž POSLEDNÍ hodnota parametru se rovná
      -- (2026-09-29, „neobsazené a volné prostory“ = unit_occupied 'ne'). has_param výš ptá
      -- jen na přítomnost; bez rovnosti by blok volných jednotek musel být vlastní funkce.
      -- Twin projde, když sedí VŠECHNY páry: počet shodných RŮZNÝCH kódů = počet párů
      -- (latest má jeden řádek na twin × kód a klíče objektu jsou jedinečné; distinct drží
      -- rovnost, i kdyby jedno z toho přestalo platit). Prázdný objekt `{}` nefiltruje —
      -- „žádný pár nechybí“ platí vždy — a počet 0 by jinak nepropustil nic.
      and (jsonb_typeof(p_params->'param_eq') is distinct from 'object'
           or p_params->'param_eq' = '{}'::jsonb
           or t.id in (
                select lq.twin_id
                  from latest lq
                  join jsonb_each_text(p_params->'param_eq') pe
                    on pe.key = lq.code and pe.value = lq.val
                 group by lq.twin_id
                having count(distinct lq.code) = (select count(*) from jsonb_each_text(p_params->'param_eq'))))
      and ((select firma from cfg) is null
           or (select via from cfg) is null
           or (select via from cfg) not in ('doc_field', 'relation')
           or ((select via from cfg) = 'doc_field' and t.id in (
                 select lf.twin_id from latest lf
                  where lf.code = (select param from cfg)
                    and lf.val in (select h.val from doc_hodnoty h)))
           or ((select via from cfg) = 'relation' and t.id in (
                 select rel.source_twin_id
                   from public.twin_relations rel
                   join public.twin_external_refs x on x.twin_id = rel.target_twin_id
                  cross join cfg
                  where rel.relation_kind = cfg.rel_kind
                    and rel.valid_from <= now()
                    and (rel.valid_to is null or rel.valid_to > now())
                    and x.ref_kind = cfg.target_ref
                    and x.state = 'confirmed'
                    and x.source_key = cfg.firma
                    and (x.valid_to is null or x.valid_to > now()))))
    group by t.id, t.label
  )
  select jsonb_build_object(
    'data', jsonb_build_object(
      -- `entity_kind` se sem ZÁMĚRNĚ nevrací (odstraněno 2026-08-08). Kontrakt
      -- tabulky ho nezná, žádný renderer ho nečetl — a přitom kvůli němu bloky
      -- nj_jednotky, nj_najemci a registry z obrazovky TIŠE mizely. Co řádek JE,
      -- říká `row_kind`; to je kanál, který na to existuje.
      'columns', (select columns from cols),
      -- `id` je twin, ne doklad. Druh řádku smí ZÚŽIT konfigurace bloku
      -- (`source_params.row_kind`, např. 'company' u registru nájemců): id je
      -- pořád twin, ale instance ho otevře jinou kartou (detail_by_kind) — firma
      -- kartou protistrany, vozidlo kartou twinu. Bez parametru beze změny.
      'row_kind', coalesce(nullif(p_params->>'row_kind', ''), 'twin'),
      'rows', coalesce((
        select jsonb_agg(
                 jsonb_build_object('id', reg.id, 'label', reg.label) || reg.vals
                 order by reg.label nulls last, reg.id
               )
        from reg
      ), '[]'::jsonb)
    ),
    'provenance', jsonb_build_object(
      'source_slug',  'twin-core',
      'freshness_at', to_char(coalesce((select max(_sort) from reg), now()) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id',     'twin-register'
    ) || case when (select via from cfg) in ('doc_field', 'relation')
              then public.scope_applied(p_params, 'owner_company')
              else '{}'::jsonb end
  );
$$;

revoke all on function public.get_twin_register(jsonb) from public, anon;
grant execute on function public.get_twin_register(jsonb) to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_param_agg.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_param_agg
-- Popis: Jedna agregace jednoho parametru PO DVOJČATECH — společný počitadlový
--        krok tabulky i grafu nad substrátem dvojčat. Sesbírá i to, čím se
--        číslo doloží: čas poslední hodnoty a zdroje, které do okna přispěly.
--
-- `ratio` je VÁŽENÝ poměr (Σ čitatele / Σ jmenovatele × factor), ne průměr
--        poměrů po řádcích: průměr poměrů dá krátké jízdě tutéž váhu jako
--        dlouhé, a l/100 km pak tvrdí něco jiného než palivová bilance.
--
-- Neznámá agregace degraduje na `sum` místo pádu — nová deklarace bloku nesmí
--        shodit starší databázi (týž idiom jako `kind` v grafu).
--
-- Bezpečnost: SECURITY INVOKER; veškerý dosah má `twin_param_values` a RLS.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.twin_param_agg(
  p_code        text,
  p_agg         text        DEFAULT 'sum',
  p_from        timestamptz DEFAULT NULL,
  p_to          timestamptz DEFAULT NULL,
  p_entity_type text        DEFAULT NULL,
  p_per_code    text        DEFAULT NULL,
  p_factor      numeric     DEFAULT 1
)
RETURNS TABLE (twin_id uuid, twin_label text, value numeric, last_at timestamptz, sources text)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
  WITH agg AS (
    SELECT lower(COALESCE(p_agg, 'sum')) AS name
  ),
  per AS (
    SELECT v.twin_id, sum(v.value) AS denom
    FROM public.twin_param_values(p_per_code, p_from, p_to, p_entity_type) v
    GROUP BY v.twin_id
  )
  SELECT
    g.twin_id,
    g.twin_label,
    -- Zaokrouhluje se JEDNOU, až tady: hodnoty vstupují v jednotce parametru
    -- (katalog umí převod, např. s → h) a ty dávají periodická desetinná místa.
    -- `trim_scale` pak odřízne nuly, aby počet kusů zůstal „3", ne „3.00".
    trim_scale(round(g.value, 2)),
    g.last_at,
    g.sources
  FROM (
    SELECT
      b.twin_id,
      min(b.twin_label) AS twin_label,
      CASE (SELECT name FROM agg)
        WHEN 'avg'             THEN avg(b.value)
        WHEN 'count'           THEN count(*)::numeric
        WHEN 'max'             THEN max(b.value)
        WHEN 'min'             THEN min(b.value)
        WHEN 'last'            THEN (array_agg(b.value ORDER BY b.occurred_at DESC)
                                       FILTER (WHERE b.value IS NOT NULL))[1]
        WHEN 'days_since_last' THEN floor(extract(epoch FROM (now() - max(b.occurred_at))) / 86400)
        WHEN 'ratio'           THEN COALESCE(p_factor, 1) * sum(b.value)
                                    / NULLIF((SELECT p.denom FROM per p WHERE p.twin_id = b.twin_id), 0)
        ELSE sum(b.value)
      END AS value,
      max(b.occurred_at) AS last_at,
      string_agg(DISTINCT b.source, '+' ORDER BY b.source) AS sources
    FROM public.twin_param_values(p_code, p_from, p_to, p_entity_type) b
    GROUP BY b.twin_id
  ) g;
$$;

COMMENT ON FUNCTION public.twin_param_agg(text, text, timestamptz, timestamptz, text, text, numeric) IS
  'Agregace parametru po dvojčatech (sum/avg/count/max/min/last/days_since_last/ratio) i s časem poslední hodnoty a zdroji — počitadlo pro tabulku a graf.';

REVOKE ALL ON FUNCTION public.twin_param_agg(text, text, timestamptz, timestamptz, text, text, numeric) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.twin_param_agg(text, text, timestamptz, timestamptz, text, text, numeric) TO authenticated;
GRANT EXECUTE ON FUNCTION public.twin_param_agg(text, text, timestamptz, timestamptz, text, text, numeric) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_twin_metric_chart_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_twin_metric_chart_block
-- Popis: GENERICKÝ graf nad substrátem dvojčat (maska `chart`). Dvě osy, jedna
--        funkce: `bar` = veličina PO ENTITÁCH (kdo pije nejvíc), `trend` =
--        tatáž veličina PO OBDOBÍCH (jak to šlo v čase). Co se kreslí, říká
--        konfigurace bloku; jméno události ani atributu funkce nezná (katalog).
--
-- Konfigurace (p_params):
--   param       POVINNÉ  kód parametru z katalogu
--   agg         volitelné sum (default) | avg | count | max | min | ratio
--   per_param,
--   factor      u `ratio` jmenovatel a násobitel (l/100 km = Σ l / Σ km × 100)
--   entity_type volitelné zúžení druhu entity
--   kind        volitelné 'bar' (default) | 'trend'
--   bucket      u `trend` 'day' (default) | 'week' | 'month'
--   note_param,
--   note_agg    volitelné druhá veličina jako POZNÁMKA u sloupce — tím se
--                        spotřeba normalizuje délkou trasy, aniž by se míchala
--                        do jednoho čísla
--   date_from/date_to nebo days (default 7 u bar, 30 u trend)
--   limit       volitelné default 20, strop 100
--   unit_key    volitelné i18n klíč jednotky
--
-- ⭐ Bod bez hodnoty se NEKRESLÍ (nula by tvrdila měření). Prázdná množina
--    vrátí prázdné body a renderer ukáže „nic k zobrazení", ne osu s nulami.
--
-- Bezpečnost: SECURITY INVOKER — RLS na twin_* fail-closed.
-- Kontrakt: (jsonb) -> jsonb {data:{kind,unit_key,points[]}, provenance}.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.get_twin_metric_chart_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_param   text := NULLIF(btrim(COALESCE(p_params->>'param', '')), '');
  v_agg     text := lower(COALESCE(NULLIF(btrim(COALESCE(p_params->>'agg', '')), ''), 'sum'));
  v_per     text := NULLIF(btrim(COALESCE(p_params->>'per_param', '')), '');
  v_factor  numeric := COALESCE((p_params->>'factor')::numeric, 1);
  v_entity  text := NULLIF(btrim(COALESCE(p_params->>'entity_type', '')), '');
  v_kind    text := lower(COALESCE(NULLIF(btrim(COALESCE(p_params->>'kind', '')), ''), 'bar'));
  v_bucket  text := lower(COALESCE(NULLIF(btrim(COALESCE(p_params->>'bucket', '')), ''), 'day'));
  v_note    text := NULLIF(btrim(COALESCE(p_params->>'note_param', '')), '');
  v_noteagg text := COALESCE(p_params->>'note_agg', 'avg');
  v_unit    text := NULLIF(btrim(COALESCE(p_params->>'unit_key', '')), '');
  v_limit   int := LEAST(GREATEST(COALESCE((p_params->>'limit')::int, 20), 1), 100);
  v_tz      text := COALESCE(NULLIF(btrim(COALESCE(p_params->>'tz', '')), ''), 'UTC');
  v_now     timestamptz := now();
  v_from    timestamptz;
  v_to      timestamptz;
  v_points  jsonb := '[]'::jsonb;
  v_fresh   timestamptz;
  v_src     text;
BEGIN
  -- Neznámé pásmo (překlep v deklaraci bloku) NESMÍ shodit plochu: degraduje
  -- na UTC. Ověřuje se proti katalogu pásem, ne proti vlastnímu seznamu.
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names z WHERE z.name = v_tz) THEN v_tz := 'UTC'; END IF;

  IF v_kind NOT IN ('bar', 'trend') THEN v_kind := 'bar'; END IF;
  IF v_bucket NOT IN ('day', 'week', 'month') THEN v_bucket := 'day'; END IF;

  IF p_params->>'date_from' ~ '^\d{4}-\d{2}-\d{2}' AND p_params->>'date_to' ~ '^\d{4}-\d{2}-\d{2}' THEN
    -- Holé datum = půlnoc V PÁSMU BLOKU; údaj s časem zůstává absolutním
    -- okamžikem (kdo pošle čas i posun, ví, co chce).
    v_from := CASE WHEN p_params->>'date_from' ~ '^\d{4}-\d{2}-\d{2}$'
                   THEN (p_params->>'date_from')::timestamp AT TIME ZONE v_tz
                   ELSE (p_params->>'date_from')::timestamptz END;
    -- Den „do" je včetně: konec okna je půlnoc NÁSLEDUJÍCÍHO dne v témže pásmu.
    v_to := CASE WHEN p_params->>'date_to' ~ '^\d{4}-\d{2}-\d{2}$'
                 THEN ((p_params->>'date_to')::date + 1)::timestamp AT TIME ZONE v_tz
                 ELSE (p_params->>'date_to')::timestamptz END;
  ELSE
    v_to   := v_now;
    v_from := v_now - make_interval(days => GREATEST(
                COALESCE((p_params->>'days')::int, CASE WHEN v_kind = 'trend' THEN 30 ELSE 7 END), 1));
  END IF;

  IF v_param IS NULL OR (v_agg = 'ratio' AND v_per IS NULL) THEN
    RETURN jsonb_build_object(
      'data', jsonb_build_object('kind', v_kind, 'points', '[]'::jsonb),
      'provenance', jsonb_build_object(
        'source_slug', 'twin-metric',
        'freshness_at', to_char(v_now AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'trace_id', 'twin-metric-chart:missing_config'));
  END IF;

  IF v_kind = 'bar' THEN
    SELECT COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
             'label', p.twin_label, 'value', p.value, 'note', p.note))
             ORDER BY p.value DESC NULLS LAST), '[]'::jsonb),
           max(p.last_at),
           string_agg(DISTINCT p.sources, '+' ORDER BY p.sources)
    INTO v_points, v_fresh, v_src
    FROM (
      SELECT a.twin_label, a.value, a.last_at, a.sources,
             (SELECT n.value::text FROM public.twin_param_agg(v_note, v_noteagg, v_from, v_to, v_entity) n
               WHERE n.twin_id = a.twin_id) AS note
      FROM public.twin_param_agg(v_param, v_agg, v_from, v_to, v_entity, v_per, v_factor) a
      WHERE a.value IS NOT NULL
      ORDER BY a.value DESC
      LIMIT v_limit
    ) p;
  ELSE
    SELECT COALESCE(jsonb_agg(jsonb_build_object('label', to_char(b.bucket, 'YYYY-MM-DD'), 'value', b.value)
                              ORDER BY b.bucket), '[]'::jsonb),
           max(b.last_at),
           string_agg(DISTINCT b.sources, '+' ORDER BY b.sources)
    INTO v_points, v_fresh, v_src
    FROM (
      SELECT g.bucket,
             -- Zaokrouhlení JEDNOU nad hotovou agregací (jako twin_param_agg):
             -- hodnoty jsou v jednotce parametru, a katalogový převod (s → h)
             -- dává periodická desetinná místa.
             trim_scale(round(CASE v_agg
               WHEN 'avg'   THEN g.v_avg
               WHEN 'count' THEN g.v_cnt
               WHEN 'max'   THEN g.v_max
               WHEN 'min'   THEN g.v_min
               -- Jmenovatel se počítá PO OBDOBÍCH a připojuje se spojením.
               -- Korelovaný poddotaz se tu nabízel, ale sahal by na
               -- `v.occurred_at` mimo seskupení — což PostgreSQL odmítne AŽ při
               -- plánování, tedy při prvním volání, ne při vytvoření funkce.
               WHEN 'ratio' THEN v_factor * g.v_sum / NULLIF(d.denom, 0)
               ELSE g.v_sum
             END, 2)) AS value,
             g.last_at, g.sources
      FROM (
        -- Koš = den/týden/měsíc V PÁSMU BLOKU. `date_trunc` nad timestamptz
        -- jinak seká podle pásma SPOJENÍ (u nás UTC), takže by se noční jízda
        -- počítala do předchozího dne a týden by se lámal ve 2:00 ráno.
        SELECT date_trunc(v_bucket, v.occurred_at AT TIME ZONE v_tz) AS bucket,
               sum(v.value)   AS v_sum,
               avg(v.value)   AS v_avg,
               count(*)::numeric AS v_cnt,
               max(v.value)   AS v_max,
               min(v.value)   AS v_min,
               max(v.occurred_at) AS last_at,
               string_agg(DISTINCT v.source, '+' ORDER BY v.source) AS sources
        FROM public.twin_param_values(v_param, v_from, v_to, v_entity) v
        GROUP BY 1
      ) g
      LEFT JOIN (
        SELECT date_trunc(v_bucket, w.occurred_at AT TIME ZONE v_tz) AS bucket, sum(w.value) AS denom
        FROM public.twin_param_values(v_per, v_from, v_to, v_entity) w
        GROUP BY 1
      ) d ON d.bucket = g.bucket
      ORDER BY g.bucket DESC
      LIMIT v_limit
    ) b
    WHERE b.value IS NOT NULL;
  END IF;

  -- `data` DOSLOVNĚ: klíče jsou kontrakt bloku a brána block-data-keys-fit-contract
  -- je čte ze zdroje (obal jsonb_strip_nulls pro ni byl nečitelný). NULL tu smí
  -- být jen volitelný unit_key — kontrakt chartu ho zná jen jako řetězec, takže
  -- bez jednotky klíč odchází celý. Body nully nenesou (bar je čistí po bodech,
  -- trend filtruje b.value IS NOT NULL), `kind` je vždy vyplněný.
  RETURN jsonb_build_object(
    'data', jsonb_build_object(
      'kind', v_kind,
      'unit_key', v_unit,
      'points', v_points) - CASE WHEN v_unit IS NULL THEN 'unit_key' ELSE '' END,
    'provenance', jsonb_build_object(
      'source_slug', COALESCE(v_src, 'twin-metric'),
      'freshness_at', to_char(COALESCE(v_fresh, v_now) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id', 'twin-metric-chart:' || v_param || ':' || v_kind
                  || CASE WHEN v_fresh IS NULL THEN ':no_data' ELSE '' END));
END;
$$;

COMMENT ON FUNCTION public.get_twin_metric_chart_block(jsonb) IS
  'Generický graf nad dvojčaty: bar = veličina po entitách, trend = po obdobích; parametr a agregace z konfigurace bloku, bod bez hodnoty se nekreslí.';

REVOKE ALL ON FUNCTION public.get_twin_metric_chart_block(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_twin_metric_chart_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_twin_metric_chart_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_twin_metric_table_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_twin_metric_table_block
-- Popis: GENERICKÁ tabulka „entita × několik veličin" nad substrátem dvojčat
--        (maska `table`). Sloupce jsou KONFIGURACE bloku: každý nese kód
--        parametru z katalogu a agregaci; volitelně druhý parametr pro poměr
--        nebo pro rozdíl. Tím se z jedné funkce skládá palivová bilance
--        (natankováno − spotřeba = Δ), spotřeba proti délce trasy i seznam
--        odstavených vozidel — bez řádku kódu na doménu.
--
-- Konfigurace (p_params):
--   entity_type POVINNÉ  druh entity (řádky tabulky)
--   columns     POVINNÉ  [{key, label_key, param, agg?, per_param?, factor?,
--                          minus_param?, minus_agg?, numeric?, as?}]
--                        `as:"last_at"` udělá ze sloupce ČAS poslední hodnoty
--                        parametru („kdy naposledy jel"), ne její velikost
--                        key ~ ^[a-z][a-z0-9_]*$; `label` je vyhrazený klíč
--   date_from,
--   date_to     volitelné absolutní okno; jinak `days` (default 7)
--   sort        volitelné {key, dir asc|desc} — jinak podle názvu entity
--   limit       volitelné default 50, strop 200
--   only_with_data volitelné true = entity bez jediné hodnoty se nevypíšou
--
-- ⭐ Prázdná buňka zůstává NULL (renderer kreslí „—"). Nula by u vozu bez dat
--    tvrdila, že nenatankoval — přesně ta vada, kterou měla palivová bilance.
--    Řádek nese `id` dvojčete, takže z tabulky vede proklik na kartu.
--
-- Bezpečnost: SECURITY INVOKER — RLS na twin_* fail-closed.
-- Kontrakt: (jsonb) -> jsonb {data:{row_kind,columns[],rows[]}, provenance}.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.get_twin_metric_table_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_entity  text := NULLIF(btrim(COALESCE(p_params->>'entity_type', '')), '');
  v_cols    jsonb := COALESCE(p_params->'columns', '[]'::jsonb);
  v_limit   int := LEAST(GREATEST(COALESCE((p_params->>'limit')::int, 50), 1), 200);
  v_sortkey text := NULLIF(btrim(COALESCE(p_params->'sort'->>'key', '')), '');
  v_sortdir text := lower(COALESCE(NULLIF(btrim(COALESCE(p_params->'sort'->>'dir', '')), ''), 'desc'));
  v_only    boolean := COALESCE((p_params->>'only_with_data')::boolean, false);
  v_tz      text := COALESCE(NULLIF(btrim(COALESCE(p_params->>'tz', '')), ''), 'UTC');
  v_now     timestamptz := now();
  v_from    timestamptz;
  v_to      timestamptz;
  v_col     jsonb;
  v_key     text;
  v_vals    jsonb := '{}'::jsonb;   -- klíč sloupce → {twin_id: hodnota}
  v_one     jsonb;
  v_last    jsonb;
  v_asof    boolean;
  v_minus   jsonb;
  v_cols_out jsonb := jsonb_build_array(
    jsonb_build_object('key', 'label', 'label_key', 'app.twins.col.label', 'align', 'left'));
  v_rows    jsonb := '[]'::jsonb;
  v_fresh   timestamptz;
  v_src     text;
BEGIN
  -- Neznámé pásmo (překlep v deklaraci bloku) NESMÍ shodit plochu: degraduje
  -- na UTC. Ověřuje se proti katalogu pásem, ne proti vlastnímu seznamu.
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names z WHERE z.name = v_tz) THEN v_tz := 'UTC'; END IF;

  IF p_params->>'date_from' ~ '^\d{4}-\d{2}-\d{2}' AND p_params->>'date_to' ~ '^\d{4}-\d{2}-\d{2}' THEN
    -- Holé datum = půlnoc V PÁSMU BLOKU; údaj s časem zůstává absolutním
    -- okamžikem (kdo pošle čas i posun, ví, co chce).
    v_from := CASE WHEN p_params->>'date_from' ~ '^\d{4}-\d{2}-\d{2}$'
                   THEN (p_params->>'date_from')::timestamp AT TIME ZONE v_tz
                   ELSE (p_params->>'date_from')::timestamptz END;
    -- Den „do" je včetně: konec okna je půlnoc NÁSLEDUJÍCÍHO dne v témže pásmu.
    v_to := CASE WHEN p_params->>'date_to' ~ '^\d{4}-\d{2}-\d{2}$'
                 THEN ((p_params->>'date_to')::date + 1)::timestamp AT TIME ZONE v_tz
                 ELSE (p_params->>'date_to')::timestamptz END;
  ELSE
    v_to   := v_now;
    v_from := v_now - make_interval(days => GREATEST(COALESCE((p_params->>'days')::int, 7), 1));
  END IF;

  -- Poctivá degradace: chybějící konfigurace vrátí PRÁZDNOU tabulku v platném
  -- tvaru, ne výjimku. Blok se přizná v provenance a plocha drží (vzor
  -- get_twin_events_table_block).
  IF v_entity IS NULL OR jsonb_typeof(v_cols) <> 'array' OR jsonb_array_length(v_cols) = 0 THEN
    RETURN jsonb_build_object(
      'data', jsonb_build_object('row_kind', 'twin', 'columns', v_cols_out, 'rows', '[]'::jsonb),
      'provenance', jsonb_build_object(
        'source_slug', 'twin-metric',
        'freshness_at', to_char(v_now AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'trace_id', 'twin-metric-table:missing_config'));
  END IF;

  FOR v_col IN SELECT * FROM jsonb_array_elements(v_cols) LOOP
    v_key := v_col->>'key';
    CONTINUE WHEN v_key IS NULL OR v_key !~ '^[a-z][a-z0-9_]*$' OR v_key = 'label'
              OR NULLIF(btrim(COALESCE(v_col->>'param', '')), '') IS NULL;

    v_asof := lower(COALESCE(v_col->>'as', 'value')) = 'last_at';

    -- Jedním průchodem obojí: hodnota i ČAS poslední hodnoty. Sloupec „kdy
    -- naposledy" tak nestojí na druhém dotazu, který by se mohl rozejít.
    SELECT jsonb_object_agg(a.twin_id::text, a.value) FILTER (WHERE a.value IS NOT NULL),
           jsonb_object_agg(a.twin_id::text,
                            to_char(a.last_at AT TIME ZONE 'UTC', 'YYYY-MM-DD'))
             FILTER (WHERE a.last_at IS NOT NULL),
           max(a.last_at),
           string_agg(DISTINCT a.sources, '+' ORDER BY a.sources)
    INTO v_one, v_last, v_fresh, v_src
    FROM public.twin_param_agg(
           v_col->>'param',
           COALESCE(v_col->>'agg', 'sum'),
           v_from, v_to, v_entity,
           NULLIF(btrim(COALESCE(v_col->>'per_param', '')), ''),
           COALESCE((v_col->>'factor')::numeric, 1)) a;

    IF v_asof THEN v_one := v_last; END IF;

    -- Rozdíl dvou veličin (Δ nádrž = natankováno − spotřeba) je pořád JEDEN
    -- sloupec: odečítá se až tady, aby obě strany šly i samostatně.
    IF NULLIF(btrim(COALESCE(v_col->>'minus_param', '')), '') IS NOT NULL THEN
      SELECT jsonb_object_agg(a.twin_id::text, a.value) FILTER (WHERE a.value IS NOT NULL)
      INTO v_minus
      FROM public.twin_param_agg(
             v_col->>'minus_param',
             COALESCE(v_col->>'minus_agg', 'sum'),
             v_from, v_to, v_entity) a;

      SELECT jsonb_object_agg(k, val) INTO v_one
      FROM (
        SELECT k,
               trim_scale(round(COALESCE((COALESCE(v_one, '{}'::jsonb)->>k)::numeric, 0)
                     - COALESCE((COALESCE(v_minus, '{}'::jsonb)->>k)::numeric, 0), 2)) AS val
        FROM (
          SELECT jsonb_object_keys(COALESCE(v_one, '{}'::jsonb)) AS k
          UNION
          SELECT jsonb_object_keys(COALESCE(v_minus, '{}'::jsonb))
        ) ks
      ) d;
    END IF;

    v_vals := v_vals || jsonb_build_object(v_key, COALESCE(v_one, '{}'::jsonb));
    v_cols_out := v_cols_out || jsonb_build_array(jsonb_build_object(
      'key', v_key,
      'label_key', COALESCE(v_col->>'label_key', 'app.twins.col.' || v_key),
      'align', CASE WHEN COALESCE((v_col->>'numeric')::boolean, NOT v_asof) THEN 'right' ELSE 'left' END));
  END LOOP;

  -- Řádky se skládají nad REGISTREM entit, ne nad naměřenými hodnotami: vůz
  -- bez jediné hodnoty je „neměřeno", a to je jiná informace než „nebyl".
  SELECT COALESCE(jsonb_agg(r ORDER BY r_sort_num, r_label), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT
      jsonb_build_object('id', t.id::text, 'label', t.label)
        || COALESCE((SELECT jsonb_object_agg(c.key, (v_vals->(c.key))->(t.id::text))
                     FROM jsonb_object_keys(v_vals) c(key)), '{}'::jsonb) AS r,
      t.label AS r_label,
      -- Řadit jde jen podle ČÍSELNÉHO sloupce; text („kdy naposledy") by
      -- přetypování shodil. Neplatný klíč = řazení podle názvu, ne pád.
      CASE WHEN v_sortkey IS NULL
             OR ((v_vals->(v_sortkey))->>(t.id::text)) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN NULL
           WHEN v_sortdir = 'asc'
             THEN  ((v_vals->(v_sortkey))->>(t.id::text))::numeric
           ELSE   -((v_vals->(v_sortkey))->>(t.id::text))::numeric
      END AS r_sort_num
    FROM public.twin_entities t
    WHERE t.entity_type = v_entity
      AND t.status = 'active'
      AND (NOT v_only OR EXISTS (
            SELECT 1 FROM jsonb_object_keys(v_vals) c(key)
            WHERE (v_vals->(c.key)) ? (t.id::text)))
    LIMIT v_limit
  ) s;

  RETURN jsonb_build_object(
    'data', jsonb_build_object('row_kind', 'twin', 'columns', v_cols_out, 'rows', v_rows),
    'provenance', jsonb_build_object(
      'source_slug', COALESCE(v_src, 'twin-metric'),
      'freshness_at', to_char(COALESCE(v_fresh, v_now) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'trace_id', 'twin-metric-table:' || v_entity || CASE WHEN v_fresh IS NULL THEN ':no_data' ELSE '' END));
END;
$$;

COMMENT ON FUNCTION public.get_twin_metric_table_block(jsonb) IS
  'Generická tabulka entita × veličiny nad dvojčaty; sloupce jsou konfigurace bloku (parametr z katalogu, agregace, poměr, rozdíl). Prázdná buňka zůstává NULL.';

REVOKE ALL ON FUNCTION public.get_twin_metric_table_block(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_twin_metric_table_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_twin_metric_table_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_propose_identity_by_signals.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_propose_identity_by_signals
-- Popis: NÁVRHY vazeb identity ze SHODY SIGNÁLŮ napříč zdroji. Zdroj (plugin)
--        popíše své objekty (vozidlo: RZ, evidenční číslo, palubní jednotka…)
--        a tahle funkce najde dvojčata, jejichž reference JINÝCH zdrojů nesou
--        tutéž hodnotu. Čím víc nezávislých signálů se shoduje, tím vyšší
--        jistota návrhu — a tím snáz ho člověk potvrdí (dávkově, stejná třída).
--
-- ⛔ NIKDY NOVÉ DVOJČE. Objekt zdroje bez kandidáta zůstane nenapárovaný (jen
-- se spočítá). Dvojčata zakládá ingest, ne dodavatel telematiky — jinak by
-- každý zdroj vyrobil vlastní kopii téhož vozidla (majitel 2026-09-24:
-- „vazby z ingestu, potvrzené z několika stran").
--
-- ⛔ NIC NEPOTVRZUJE. Zakládá návrh přes twin_identity_propose_match, který
-- ctí lidské „NE" (zamítnutý pár se nevrací). Potvrzení je výhradně lidské
-- (kokpit → submit_evidence_review_audited → twin_identity_confirm_binding).
--
-- Platforma nezná jména polí dodavatele: řádek nese signály jako druhy
-- referencí (`ref_kind`), které už svět dvojčat používá. Adaptér zdroje říká,
-- který jeho údaj odpovídá kterému druhu — mapování je v pluginu, ne tady.
--
-- Vstup p_rows: [{ "source_key": "<id objektu ve zdroji>",
--                  "signals": [{ "kinds": ["vehicle_plate","vehicle_machine_plate"],
--                                "value": "1AB 2345", "weight": 0.6 }, …] }, …]
--   weight = síla jednoho signálu (0,05–0,9; výchozí 0,6). Jistota návrhu je
--   1 − Π(1 − weight) přes shodné signály, strop 0,95 (jistotu dává člověk).
--   Signály ukazující na VÍC dvojčat: návrh každému s poloviční jistotou —
--   rozpor dat patří před člověka, ne do tichého výběru.
--
-- Porovnání hodnot: velká písmena, bez mezer/pomlček/teček, bez úvodních nul
-- čistě číselného klíče („1AB-2345" = „1ab 2345", „0872" = „872").
--
-- Vrací: {objektu, potvrzeno, navrzeno, uz_navrzeno, zamitnuto_clovekem,
--         bez_kandidata, nejednoznacne}
--   (žádné klíče ani hodnoty — mohou to být osobní údaje)
-- Bezpečnost: SECURITY DEFINER; jen service_role (zdroj navrhuje, člověk potvrzuje).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.twin_propose_identity_by_signals(
  p_source      text,
  p_entity_type text,
  p_rows        jsonb,
  p_proposed_by text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_source      text;
  v_row         jsonb;
  v_key         text;
  v_kand        jsonb;
  v_cand        jsonb;
  v_kandidatu   integer;
  v_res         jsonb;
  v_objektu     integer := 0;
  v_potvrzeno   integer := 0;
  v_navrzeno    integer := 0;
  v_uz          integer := 0;
  v_zamitnuto   integer := 0;
  v_bez         integer := 0;
  v_nejedno     integer := 0;
BEGIN
  -- Volá ji zdroj (plugin přes broker), ne člověk: člověk návrhy POTVRZUJE.
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'twin_propose_identity_by_signals: service role required'
      USING ERRCODE = '42501';
  END IF;
  IF coalesce(btrim(p_source), '') = '' OR coalesce(btrim(p_entity_type), '') = '' THEN
    RAISE EXCEPTION 'twin_propose_identity_by_signals: source and entity_type are required'
      USING ERRCODE = '22023';
  END IF;
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'twin_propose_identity_by_signals: p_rows must be a jsonb array'
      USING ERRCODE = '22023';
  END IF;
  -- Pohlcený zdroj se zapisuje pod toho, kdo ho pohltil (jedna identita).
  v_source := public.canonical_ingest_source(btrim(p_source));

  FOR v_row IN SELECT r FROM jsonb_array_elements(p_rows) AS r LOOP
    v_key := nullif(btrim(v_row->>'source_key'), '');
    CONTINUE WHEN v_key IS NULL;
    v_objektu := v_objektu + 1;

    -- Objekt, který už k dvojčeti patří, se znovu nenavrhuje.
    IF EXISTS (
      SELECT 1 FROM public.twin_external_refs r
       WHERE r.source = v_source AND r.source_key = v_key AND r.ref_kind = 'primary_id'
         AND r.state = 'confirmed' AND r.valid_to IS NULL
    ) THEN
      v_potvrzeno := v_potvrzeno + 1;
      CONTINUE;
    END IF;

    -- Kandidáti se spočítají jednou, návrhy se zakládají po nich.
    WITH sig AS (
      SELECT x.ord,
             ARRAY(SELECT jsonb_array_elements_text(x.s->'kinds')) AS kinds,
             regexp_replace(upper(regexp_replace(x.s->>'value', '[[:space:].-]', '', 'g')),
                            '^0+([0-9])', '\1') AS val,
             least(greatest(coalesce(
               CASE WHEN x.s->>'weight' ~ '^[0-9]+(\.[0-9]+)?$' THEN (x.s->>'weight')::numeric END,
               0.6), 0.05), 0.9) AS weight
        FROM jsonb_array_elements(coalesce(v_row->'signals', '[]'::jsonb)) WITH ORDINALITY AS x(s, ord)
       WHERE jsonb_typeof(x.s->'kinds') = 'array'
         AND coalesce(btrim(x.s->>'value'), '') <> ''
    ),
    shody AS (
      -- Jedna shoda = (dvojče, signál); víc referencí téhož signálu nesčítá.
      SELECT DISTINCT ON (r.twin_id, sig.ord) r.twin_id, sig.ord, sig.weight, r.ref_kind
        FROM sig
        JOIN public.twin_external_refs r
          ON r.ref_kind = ANY (sig.kinds)
         AND r.source <> v_source
         AND r.state IN ('proposed', 'confirmed')
         AND r.valid_to IS NULL
        JOIN public.twin_entities t
          ON t.id = r.twin_id AND t.entity_type = p_entity_type AND t.status = 'active'
       WHERE sig.val <> ''
         AND regexp_replace(upper(regexp_replace(r.source_key, '[[:space:].-]', '', 'g')),
                            '^0+([0-9])', '\1') = sig.val
       ORDER BY r.twin_id, sig.ord, (r.state = 'confirmed') DESC
    ),
    na_dvojce AS (
      SELECT s.twin_id,
             least(1 - exp(sum(ln(1 - s.weight))), 0.95) AS jistota,
             string_agg(DISTINCT s.ref_kind, '+' ORDER BY s.ref_kind) AS druhy
        FROM shody s
       GROUP BY s.twin_id
    )
    SELECT coalesce(jsonb_agg(jsonb_build_object(
             'twin_id', n.twin_id, 'jistota', n.jistota, 'druhy', n.druhy)
             ORDER BY n.jistota DESC, n.twin_id), '[]'::jsonb)
      INTO v_kand
      FROM na_dvojce n;

    v_kandidatu := jsonb_array_length(v_kand);
    IF v_kandidatu = 0 THEN
      v_bez := v_bez + 1;
      CONTINUE;
    END IF;
    IF v_kandidatu > 1 THEN
      v_nejedno := v_nejedno + 1;
    END IF;

    FOR v_cand IN SELECT c FROM jsonb_array_elements(v_kand) AS c LOOP
      -- `proposed_by` nese DŮKAZ (které druhy se shodly), protože ho fronta
      -- ratifikace ukazuje — hodnoty ne, mohou to být osobní údaje.
      v_res := public.twin_identity_propose_match(
        (v_cand->>'twin_id')::uuid, v_source, v_key, 'primary_id',
        coalesce(nullif(btrim(p_proposed_by), ''), 'rule:signals') || ':' || (v_cand->>'druhy'),
        round((v_cand->>'jistota')::numeric / CASE WHEN v_kandidatu > 1 THEN 2 ELSE 1 END, 3),
        CASE WHEN v_kandidatu > 1
             THEN 'nejednoznačné: ' || v_kandidatu || ' kandidátů' END);
      CASE
        WHEN v_res->>'state' = 'skipped_rejected' THEN v_zamitnuto := v_zamitnuto + 1;
        WHEN coalesce((v_res->>'already')::boolean, false) THEN v_uz := v_uz + 1;
        ELSE v_navrzeno := v_navrzeno + 1;
      END CASE;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'objektu',            v_objektu,
    'potvrzeno',          v_potvrzeno,
    'navrzeno',           v_navrzeno,
    'uz_navrzeno',        v_uz,
    'zamitnuto_clovekem', v_zamitnuto,
    'bez_kandidata',      v_bez,
    'nejednoznacne',      v_nejedno
  );
END;
$$;

REVOKE ALL ON FUNCTION public.twin_propose_identity_by_signals(text, text, jsonb, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.twin_propose_identity_by_signals(text, text, jsonb, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/avp_propose_identity.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: avp_propose_identity
-- Popis: TENKÝ ADAPTÉR karet a čipů AVP (obecná surová dráha
--        source_catalog_rows, zdroj 'avp-portal') → NÁVRHY vazeb identity.
--        Nic nezakládá a nic nepotvrzuje — předloží člověku, která karta AVP
--        je které vozidlo či řidič, a který čip patří ke které kartě.
--
-- KARTY (/cards, druh 'card'; vozidlo a řidič se liší `card_type`) → obecné
-- jádro twin_propose_identity_by_signals, klíč 'karta:<id>' (primary_id):
--   vozidlo  vehicle_type (SPZ nebo VIN, ~7 %) → vehicle_plate/_machine_plate/_vin  0,6
--            RZ ve jménu karty („MAN 7Z9 2093“)  → vehicle_plate/_machine_plate    0,5
--            inventární číslo (~22 %)           → vehicle_machine_id              0,5
--   řidič    jméno karty                        → driver_name                     0,3
--
-- ČIPY (/chips, druh 'chip': chip_code → card_id; karta jich může mít víc) —
-- TRANZITIVNĚ: čip, jehož karta už má POTVRZENOU vazbu, se navrhne na totéž
-- dvojče (klíč 'cip:<kód>', ref_kind field_identity, jistota 0,7,
-- „rule:avp-cip-karta“). Nižší jistota, protože API dává jen AKTUÁLNÍ
-- přiřazení čipu, ne historii přesunů; potvrzením platí vazba od té chvíle.
-- Čipy AVP nejsou tachografové karty — mezi systémy klíčem nejsou.
--
-- Klíče 'karta:' / 'cip:' musí být STEJNÉ jako v avp_project_fuelings.
--
-- Vrací: {vozidla, ridici: <výsledek jádra>, cipy: {kandidatu, navrzeno,
--         uz_navrzeno, zamitnuto_clovekem, potvrzeno}}
-- Bezpečnost: SECURITY DEFINER; jen service_role (volá plugin přes broker).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.avp_propose_identity()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  c_source    constant text := 'avp-portal';
  v_source    text;
  v_vozidla   jsonb;
  v_ridici    jsonb;
  v_cip       record;
  v_res       jsonb;
  v_kandidatu integer := 0;
  v_navrzeno  integer := 0;
  v_uz        integer := 0;
  v_zamitnuto integer := 0;
  v_potvrzeno integer := 0;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'avp_propose_identity: service role required'
      USING ERRCODE = '42501';
  END IF;
  v_source := public.canonical_ingest_source(c_source);

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'source_key', 'karta:' || c.external_id,
           'signals', jsonb_path_query_array(jsonb_build_array(
             jsonb_build_object('kinds', jsonb_build_array('vehicle_plate', 'vehicle_machine_plate', 'vehicle_vin'),
                                'value', nullif(btrim(c.fields->>'vehicle_type'), ''), 'weight', 0.6),
             jsonb_build_object('kinds', jsonb_build_array('vehicle_plate', 'vehicle_machine_plate'),
                                'value', x.rz[1] || x.rz[2], 'weight', 0.5),
             jsonb_build_object('kinds', jsonb_build_array('vehicle_machine_id'),
                                'value', nullif(btrim(c.fields->>'inventory_number'), ''), 'weight', 0.5)),
             '$[*] ? (@.value != null)')
         ) ORDER BY c.external_id), '[]'::jsonb)
    INTO v_vozidla
    FROM public.source_catalog_rows c
    -- Česká RZ ve jménu karty („MAN 7Z9 2093“ → 7Z92093); bez shody žádný signál.
    CROSS JOIN LATERAL (
      SELECT regexp_match(upper(coalesce(c.fields->>'name', '')), '([0-9][A-Z][A-Z0-9]) ?([0-9]{4})') AS rz
    ) x
   WHERE c.source_slug = c_source AND c.kind = 'card'
     AND lower(coalesce(c.fields->>'card_type', '')) = 'vehicle';

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'source_key', 'karta:' || c.external_id,
           'signals', jsonb_path_query_array(jsonb_build_array(
             jsonb_build_object('kinds', jsonb_build_array('driver_name'),
                                'value', nullif(btrim(c.fields->>'name'), ''), 'weight', 0.3)),
             '$[*] ? (@.value != null)')
         ) ORDER BY c.external_id), '[]'::jsonb)
    INTO v_ridici
    FROM public.source_catalog_rows c
   WHERE c.source_slug = c_source AND c.kind = 'card'
     AND lower(coalesce(c.fields->>'card_type', '')) = 'driver';

  FOR v_cip IN
    SELECT 'cip:' || upper(btrim(ch.fields->>'chip_code')) AS klic, k.twin_id
      FROM public.source_catalog_rows ch
      JOIN public.twin_external_refs k
        ON k.source = v_source
       AND k.source_key = 'karta:' || (ch.fields->>'card_id')
       AND k.ref_kind = 'primary_id'
       AND k.state = 'confirmed'
       AND k.valid_to IS NULL
     WHERE ch.source_slug = c_source AND ch.kind = 'chip'
       AND nullif(btrim(ch.fields->>'chip_code'), '') IS NOT NULL
       AND nullif(ch.fields->>'card_id', '') IS NOT NULL
     ORDER BY 1
  LOOP
    v_kandidatu := v_kandidatu + 1;
    IF EXISTS (SELECT 1 FROM public.twin_external_refs r
                WHERE r.source = v_source AND r.source_key = v_cip.klic
                  AND r.ref_kind = 'field_identity' AND r.state = 'confirmed' AND r.valid_to IS NULL) THEN
      v_potvrzeno := v_potvrzeno + 1;
      CONTINUE;
    END IF;
    v_res := public.twin_identity_propose_match(
      v_cip.twin_id, v_source, v_cip.klic, 'field_identity', 'rule:avp-cip-karta', 0.7, NULL);
    CASE
      WHEN v_res->>'state' = 'skipped_rejected' THEN v_zamitnuto := v_zamitnuto + 1;
      WHEN coalesce((v_res->>'already')::boolean, false) THEN v_uz := v_uz + 1;
      ELSE v_navrzeno := v_navrzeno + 1;
    END CASE;
  END LOOP;

  RETURN jsonb_build_object(
    'vozidla', public.twin_propose_identity_by_signals(c_source, 'vehicle', v_vozidla, 'rule:signals'),
    'ridici',  public.twin_propose_identity_by_signals(c_source, 'driver',  v_ridici,  'rule:signals'),
    'cipy',    jsonb_build_object(
                 'kandidatu',          v_kandidatu,
                 'navrzeno',           v_navrzeno,
                 'uz_navrzeno',        v_uz,
                 'zamitnuto_clovekem', v_zamitnuto,
                 'potvrzeno',          v_potvrzeno)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.avp_propose_identity() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.avp_propose_identity() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/ew_propose_identity.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: ew_propose_identity
-- Popis: TENKÝ ADAPTÉR číselníků Eurowagu (obecná surová dráha
--        source_catalog_rows, zdroj 'eurowag-telematics', druhy 'vehicle'
--        a 'driver') → twin_propose_identity_by_signals. Nic nezakládá a nic
--        nepotvrzuje — předloží člověku, které vozidlo/řidič Eurowagu je které
--        dvojče.
--
-- Klíče nesou druh objektu: 'vozidlo:<monitoredObjectId>', 'osoba:<driver id>'
-- — Eurowag čísluje vozidla i řidiče vlastní řadou a vazba identity je
-- jedinečná jen v (source, source_key, ref_kind), bez druhu entity (třída
-- chyby nalezená u T-cars 2026-09-27; verze 0.1.0 pluginu ji měla latentně).
-- Stejné klíče skládá ew_project_catalog.
--
-- Signály a síla (1 − Π(1 − w) přes shodné):
--   vozidlo  SPZ (`rn`)        → vehicle_plate/_machine_plate  0,6
--   řidič    jméno a příjmení  → driver_name                   0,3
--
-- Vrací: {vozidla, ridici: <výsledek jádra>}
-- Bezpečnost: SECURITY DEFINER; jen service_role (volá plugin přes broker).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.ew_propose_identity()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  c_source  constant text := 'eurowag-telematics';
  v_vozidla jsonb;
  v_ridici  jsonb;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'ew_propose_identity: service role required'
      USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'source_key', 'vozidlo:' || c.external_id,
           'signals', jsonb_path_query_array(jsonb_build_array(
             jsonb_build_object('kinds', jsonb_build_array('vehicle_plate', 'vehicle_machine_plate'),
                                'value', nullif(btrim(c.fields->>'rn'), ''), 'weight', 0.6)),
             '$[*] ? (@.value != null)')
         ) ORDER BY c.external_id), '[]'::jsonb)
    INTO v_vozidla
    FROM public.source_catalog_rows c
   WHERE c.source_slug = c_source AND c.kind = 'vehicle';

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'source_key', 'osoba:' || c.external_id,
           'signals', jsonb_path_query_array(jsonb_build_array(
             jsonb_build_object('kinds', jsonb_build_array('driver_name'),
                                'value', nullif(btrim(concat_ws(' ', c.fields->>'name', c.fields->>'surname')), ''),
                                'weight', 0.3)),
             '$[*] ? (@.value != null)')
         ) ORDER BY c.external_id), '[]'::jsonb)
    INTO v_ridici
    FROM public.source_catalog_rows c
   WHERE c.source_slug = c_source AND c.kind = 'driver';

  RETURN jsonb_build_object(
    'vozidla', public.twin_propose_identity_by_signals(c_source, 'vehicle', v_vozidla, 'rule:signals'),
    'ridici',  public.twin_propose_identity_by_signals(c_source, 'driver',  v_ridici,  'rule:signals')
  );
END;
$$;

REVOKE ALL ON FUNCTION public.ew_propose_identity() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.ew_propose_identity() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/tc_propose_identity.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: tc_propose_identity
-- Popis: TENKÝ ADAPTÉR T-cars → twin_propose_identity_by_signals. Řekne, který
--        údaj číselníku T-cars odpovídá kterému druhu reference ve světě
--        dvojčat; párování, jistotu a návrhy dělá obecné jádro. Nic nezakládá
--        a nic nepotvrzuje — jen předloží člověku návrhy vazeb.
--
-- Signály a jejich síla (1 − Π(1 − w) přes shodné):
--   vozidlo  palubní jednotka  → vehicle_telemetry_unit        0,8 (výrobní číslo)
--            RZ                → vehicle_plate, vehicle_machine_plate  0,6
--            evidenční číslo   → vehicle_machine_id            0,5 (číslování firmy)
--   řidič    osobní číslo      → driver_personal_number        0,7
--            jméno             → driver_name                   0,3 (shoda jmen)
-- Jméno řidiče se NEPOROVNÁVÁ s cizím `primary_id`: co je primární klíč jiného
-- zdroje, ví jen ten zdroj (u ingestu jde o text, jehož tvar se liší).
--
-- ⛔ KLÍČ NESE DRUH OBJEKTU ('vozidlo:<vozidloId>', 'osoba:<osobaId>'). T-cars
-- čísluje vozidla a osoby ve DVOU nezávislých řadách, kdežto vazba identity je
-- jedinečná jen v (source, source_key, ref_kind) — bez druhu entity. S holým
-- číslem by si vozidlo 5 a osoba 5 vzaly týž klíč: potvrzené vozidlo by
-- „zabralo" řidiče a jízda by za řidiče dostala vozidlo (nalezeno 2026-09-27
-- před prvním spuštěním, v datech nic nevzniklo). Totéž platí v tc_project_rides.
--
-- Vrací: {vozidla: <výsledek jádra>, ridici: <výsledek jádra>}
-- Bezpečnost: SECURITY DEFINER; jen service_role (volá plugin přes broker).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.tc_propose_identity()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  c_source  constant text := 'tcars-fleet';
  v_vozidla jsonb;
  v_ridici  jsonb;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'tc_propose_identity: service role required'
      USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'source_key', 'vozidlo:' || v.tc_vehicle_id,
           'signals', jsonb_path_query_array(jsonb_build_array(
             jsonb_build_object('kinds', jsonb_build_array('vehicle_telemetry_unit'),
                                'value', v.unit_no, 'weight', 0.8),
             jsonb_build_object('kinds', jsonb_build_array('vehicle_plate', 'vehicle_machine_plate'),
                                'value', v.plate, 'weight', 0.6),
             jsonb_build_object('kinds', jsonb_build_array('vehicle_machine_id'),
                                'value', v.evidence_no, 'weight', 0.5)),
             '$[*] ? (@.value != null)')
         ) ORDER BY v.tc_vehicle_id), '[]'::jsonb)
    INTO v_vozidla
    FROM public.tc_vehicles v
   WHERE v.active;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'source_key', 'osoba:' || d.tc_driver_id,
           'signals', jsonb_path_query_array(jsonb_build_array(
             jsonb_build_object('kinds', jsonb_build_array('driver_personal_number'),
                                'value', d.personal_number, 'weight', 0.7),
             jsonb_build_object('kinds', jsonb_build_array('driver_name'),
                                'value', d.name, 'weight', 0.3)),
             '$[*] ? (@.value != null)')
         ) ORDER BY d.tc_driver_id), '[]'::jsonb)
    INTO v_ridici
    FROM public.tc_drivers d
   WHERE d.active;

  RETURN jsonb_build_object(
    'vozidla', public.twin_propose_identity_by_signals(c_source, 'vehicle', v_vozidla, 'rule:signals'),
    'ridici',  public.twin_propose_identity_by_signals(c_source, 'driver',  v_ridici,  'rule:signals')
  );
END;
$$;

REVOKE ALL ON FUNCTION public.tc_propose_identity() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.tc_propose_identity() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_record_events_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_record_events_audited
-- Popis: Idempotentní batch zápis událostí dvojčat (jízdy, příjezdy,
--        přiřazení, plánované úkoly…). Dedup přes (source, event_type,
--        source_ref): opakovaný import stejného okna aktualizuje ended_at/
--        attrs/časy (zdroje opravují zpětně — vzor wd_rides), neduplikuje.
--        Položky bez source_ref se vkládají bez dedupu (jednorázové události).
--        Adaptér resolvuje twin_id PŘED zápisem (twin_identity_resolve /
--        twin_upsert_entity_audited) — RPC identity neřeší, jen validuje.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT
-- Audit: twin_events.import_completed s počty (bez PII)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_record_events_audited(
  p_events jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean := public.is_service_role();
  v_batch jsonb;
  v_plain jsonb;
  v_total integer;
  v_updated integer := 0;
  v_inserted integer := 0;
BEGIN
  -- Authorization check (FIRST, before any data access)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  -- Input validation
  IF p_events IS NULL OR jsonb_typeof(p_events) <> 'array' THEN
    RAISE EXCEPTION 'p_events must be a jsonb array';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_events) AS item
    WHERE item->>'event_type' IS NULL OR btrim(item->>'event_type') = ''
       OR item->>'twin_id' IS NULL
       OR item->>'occurred_at' IS NULL
       OR item->>'source' IS NULL OR btrim(item->>'source') = ''
  ) THEN
    RAISE EXCEPTION 'each event requires event_type, twin_id, occurred_at, source';
  END IF;

  -- Dedup uvnitř dávky podle (source, event_type, source_ref) — poslední výskyt
  -- vyhrává (novější stav v odpovědi zdroje); ON CONFLICT nesmí zasáhnout
  -- stejný řádek dvakrát.
  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON (item->>'source', item->>'event_type', item->>'source_ref') item
    FROM (
      SELECT item, ordinality
      FROM jsonb_array_elements(p_events) WITH ORDINALITY AS e(item, ordinality)
    ) AS ordered
    WHERE item->>'source_ref' IS NOT NULL
    ORDER BY item->>'source', item->>'event_type', item->>'source_ref', ordinality DESC
  ) AS deduped;

  SELECT COALESCE(jsonb_agg(item), '[]'::jsonb) INTO v_plain
  FROM jsonb_array_elements(p_events) AS item
  WHERE item->>'source_ref' IS NULL;

  v_total := jsonb_array_length(v_batch) + jsonb_array_length(v_plain);

  SELECT count(*) INTO v_updated
  FROM public.twin_events e
  JOIN jsonb_array_elements(v_batch) AS item
    ON e.source = item->>'source'
   AND e.event_type = item->>'event_type'
   AND e.source_ref = item->>'source_ref';

  -- Deduplikovatelné události: upsert podle (source, event_type, source_ref)
  INSERT INTO public.twin_events (
    event_type, twin_id, related_twin_id, place_twin_id, story_id,
    occurred_at, ended_at, attrs, source, source_ref
  )
  SELECT
    item->>'event_type',
    (item->>'twin_id')::uuid,
    (item->>'related_twin_id')::uuid,
    (item->>'place_twin_id')::uuid,
    (item->>'story_id')::uuid,
    (item->>'occurred_at')::timestamptz,
    (item->>'ended_at')::timestamptz,
    COALESCE(item->'attrs', '{}'::jsonb),
    item->>'source',
    item->>'source_ref'
  FROM jsonb_array_elements(v_batch) AS item
  ON CONFLICT (source, event_type, source_ref) WHERE source_ref IS NOT NULL
  DO UPDATE SET
    twin_id         = EXCLUDED.twin_id,
    related_twin_id = EXCLUDED.related_twin_id,
    place_twin_id   = EXCLUDED.place_twin_id,
    story_id        = COALESCE(EXCLUDED.story_id, public.twin_events.story_id),
    occurred_at     = EXCLUDED.occurred_at,
    ended_at        = EXCLUDED.ended_at,
    attrs           = EXCLUDED.attrs;

  -- Jednorázové události bez source_ref: prostý insert
  INSERT INTO public.twin_events (
    event_type, twin_id, related_twin_id, place_twin_id, story_id,
    occurred_at, ended_at, attrs, source
  )
  SELECT
    item->>'event_type',
    (item->>'twin_id')::uuid,
    (item->>'related_twin_id')::uuid,
    (item->>'place_twin_id')::uuid,
    (item->>'story_id')::uuid,
    (item->>'occurred_at')::timestamptz,
    (item->>'ended_at')::timestamptz,
    COALESCE(item->'attrs', '{}'::jsonb),
    item->>'source'
  FROM jsonb_array_elements(v_plain) AS item;

  v_inserted := v_total - v_updated;

  -- Audit log
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'twin_events.import_completed',
    jsonb_build_object(
      'total', v_total,
      'inserted', v_inserted,
      'updated', v_updated
    )
  );

  RETURN jsonb_build_object(
    'total', v_total,
    'inserted', v_inserted,
    'updated', v_updated
  );
END;
$$;

REVOKE ALL ON FUNCTION public.twin_record_events_audited(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.twin_record_events_audited(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.twin_record_events_audited(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_project_events.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_project_events
-- Popis: Záznamy ZDROJE → události dvojčat. Obecné jádro projekce: nezná
--        dodavatele ani jeho tabulky — dostane řádky v jednom tvaru a zdroj,
--        jehož vazby identity platí. Jízda, tankování, činnost řidiče z
--        tachografu i hladina ze sondy jsou tentýž tvar: KDO (subjekt), s KÝM
--        (druhá strana), KDY, CO (atributy) — liší se typem události a dráhou.
--        Adaptér zdroje (vendor tabulka nebo řady source_catalog_rows) jen
--        přeloží své řádky; jádro se při přepojení zdroje nemění.
--
-- IDENTITA: subjekt i druhá strana se resolvují přes twin_identity_resolve
-- VÝHRADNĚ pro zdroj `p_source`, podle `ref_kind` řádku (primární klíč, čip…)
-- a k ČASU UDÁLOSTI — jen potvrzené a tehdy platné vazby (čip se tak přiřadí
-- tehdejšímu držiteli, ne dnešnímu). Navíc musí dvojče mít DRUH, který řádek
-- čeká (`entity_type`): vazba identity je dnes jedinečná jen v (source,
-- source_key, ref_kind), bez druhu entity, takže adaptér, který by zapomněl
-- odlišit klíč vozidla od klíče osoby, by jinak přiřadil jízdu řidiči-vozidlu
-- (nalezeno 2026-09-27 u T-cars). Adaptéry klíče rozlišují samy; tohle je
-- druhá pojistka.
--
-- Nerozřešený subjekt se NEZAPÍŠE a nic se kvůli němu nezakládá — jen se
-- spočítá. Adaptér posílá každý dosud nepromítnutý záznam znovu, takže se
-- promítne sám, až člověk vazbu potvrdí. Nerozřešená druhá strana událost
-- neblokuje, jen ji nemá.
--
-- ZÁPIS: jen NOVÉ nebo ZMĚNĚNÉ události (porovnání s twin_events); zdroje
-- opravují zpětně a adaptéry čtou s překryvem, bez porovnání by každé volání
-- zauditovalo celé okno. Zápis přes twin_record_events_audited (dedup
-- (source, event_type, source_ref)). `source` události = '<p_source>:<lane>'.
--
-- Vstup p_rows: [{ "event_type": "trip", "lane": "trip",
--                  "source_ref": "<id záznamu ve zdroji>",
--                  "subject": {"key": "…", "ref_kind": "primary_id", "entity_type": "vehicle"},
--                  "related": {"key": "…", "ref_kind": "field_identity", "entity_type": "driver"} | null,
--                  "occurred_at": "<ISO>", "ended_at": "<ISO>" | null,
--                  "attrs": { … } }, …]
--   `lane` chybí → rovná se typu události; `ref_kind` chybí → 'primary_id'.
--   Jména typů událostí, drah, druhů entit i atributů určují DATA (katalog
--   parametrů, adaptér), ne tahle funkce.
--
-- Vrací: {prijato, nove, zmenene, beze_zmeny, bez_vazby, jiny_druh, neplatne}
--   bez_vazby = subjekt bez potvrzené a k času platné vazby;
--   jiny_druh = vazba vede na dvojče jiného druhu, než řádek čeká (subjekt
--               se pak nezapíše, druhá strana se vynechá) — vada adaptéru;
--   neplatne  = chybí povinný údaj nebo konec před začátkem.
-- Bezpečnost: SECURITY DEFINER; jen service_role (projekci spouští zdroj).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.twin_project_events(
  p_source text,
  p_rows   jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_source   text;
  v_prijato  integer;
  v_neplatne integer;
  v_bez      integer;
  v_druh     integer;
  v_nove     integer;
  v_zmenene  integer;
  v_udalosti integer;
  v_zapis    jsonb;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'twin_project_events: service role required'
      USING ERRCODE = '42501';
  END IF;
  IF coalesce(btrim(p_source), '') = '' THEN
    RAISE EXCEPTION 'twin_project_events: source is required'
      USING ERRCODE = '22023';
  END IF;
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'twin_project_events: p_rows must be a jsonb array'
      USING ERRCODE = '22023';
  END IF;
  v_source := public.canonical_ingest_source(btrim(p_source));

  WITH vstup AS (
    SELECT nullif(btrim(r->>'event_type'), '')                           AS event_type,
           coalesce(nullif(btrim(r->>'lane'), ''), nullif(btrim(r->>'event_type'), '')) AS lane,
           nullif(btrim(r->>'source_ref'), '')                           AS source_ref,
           nullif(btrim(r->'subject'->>'key'), '')                       AS s_key,
           coalesce(nullif(btrim(r->'subject'->>'ref_kind'), ''), 'primary_id') AS s_kind,
           nullif(btrim(r->'subject'->>'entity_type'), '')               AS s_type,
           nullif(btrim(r->'related'->>'key'), '')                       AS r_key,
           coalesce(nullif(btrim(r->'related'->>'ref_kind'), ''), 'primary_id') AS r_kind,
           nullif(btrim(r->'related'->>'entity_type'), '')               AS r_type,
           CASE WHEN jsonb_typeof(r->'attrs') = 'object' THEN r->'attrs' ELSE '{}'::jsonb END AS attrs,
           nullif(r->>'occurred_at', '')                                 AS occurred_raw,
           nullif(r->>'ended_at', '')                                    AS ended_raw
      FROM jsonb_array_elements(p_rows) AS r
  ),
  platne AS (
    -- Bez typu, klíče záznamu, subjektu (i jeho druhu) nebo času nemá událost
    -- kam patřit ani jak se deduplikovat. Konec před začátkem (dodavatel to
    -- umí) by odmítla tabulka a shodila celou dávku — neplatný řádek. Nečitelný
    -- čas naopak SPADNE nahlas: adaptér čte typované hodnoty, takže je to vada
    -- adaptéru, ne dat.
    SELECT v.event_type, v.lane, v.source_ref, v.s_key, v.s_kind, v.s_type,
           v.r_key, v.r_kind, v.r_type, v.attrs,
           v.occurred_raw::timestamptz AS occurred_at,
           v.ended_raw::timestamptz    AS ended_at
      FROM vstup v
     WHERE v.event_type IS NOT NULL
       AND v.source_ref IS NOT NULL
       AND v.s_key IS NOT NULL
       AND v.s_type IS NOT NULL
       AND v.occurred_raw IS NOT NULL
  ),
  platne_casy AS (
    SELECT p.event_type, p.lane, p.source_ref, p.s_key, p.s_kind, p.s_type,
           p.r_key, p.r_kind, p.r_type, p.attrs, p.occurred_at, p.ended_at
      FROM platne p
     WHERE p.ended_at IS NULL OR p.ended_at >= p.occurred_at
  ),
  rozreseno AS (
    SELECT p.event_type, p.lane, p.source_ref, p.s_type, p.r_type, p.attrs,
           p.occurred_at, p.ended_at,
           public.twin_identity_resolve(v_source, p.s_key, p.s_kind, p.occurred_at) AS s_twin,
           CASE WHEN p.r_key IS NOT NULL
                THEN public.twin_identity_resolve(v_source, p.r_key, p.r_kind, p.occurred_at)
           END AS r_twin
      FROM platne_casy p
  ),
  s_druhem AS (
    SELECT r.event_type, r.lane, r.source_ref, r.attrs, r.occurred_at, r.ended_at,
           r.s_twin,
           (r.s_twin IS NOT NULL AND ts.entity_type IS DISTINCT FROM r.s_type) AS s_jiny,
           CASE WHEN r.r_twin IS NOT NULL
                 AND (r.r_type IS NULL OR tr.entity_type = r.r_type)
                THEN r.r_twin END AS r_twin,
           (r.r_twin IS NOT NULL AND r.r_type IS NOT NULL
            AND tr.entity_type IS DISTINCT FROM r.r_type) AS r_jiny
      FROM rozreseno r
      LEFT JOIN public.twin_entities ts ON ts.id = r.s_twin
      LEFT JOIN public.twin_entities tr ON tr.id = r.r_twin
  ),
  udalosti AS (
    SELECT d.event_type, d.source_ref, d.attrs, d.occurred_at, d.ended_at,
           d.s_twin, d.r_twin,
           v_source || ':' || d.lane AS draha,
           e.id AS existujici,
           (e.id IS NOT NULL AND (
              e.twin_id IS DISTINCT FROM d.s_twin
              OR e.related_twin_id IS DISTINCT FROM d.r_twin
              OR e.occurred_at IS DISTINCT FROM d.occurred_at
              OR e.ended_at IS DISTINCT FROM d.ended_at
              OR e.attrs IS DISTINCT FROM d.attrs)) AS zmena
      FROM s_druhem d
      LEFT JOIN public.twin_events e
        ON e.source = v_source || ':' || d.lane
       AND e.event_type = d.event_type
       AND e.source_ref = d.source_ref
     WHERE d.s_twin IS NOT NULL AND NOT d.s_jiny
  )
  SELECT
    (SELECT count(*) FROM vstup),
    (SELECT count(*) FROM vstup) - (SELECT count(*) FROM platne_casy),
    (SELECT count(*) FROM s_druhem WHERE s_twin IS NULL),
    (SELECT count(*) FROM s_druhem WHERE s_jiny OR r_jiny),
    (SELECT count(*) FROM udalosti WHERE existujici IS NULL),
    (SELECT count(*) FROM udalosti WHERE zmena),
    (SELECT count(*) FROM udalosti),
    (SELECT coalesce(jsonb_agg(jsonb_build_object(
              'event_type',      u.event_type,
              'twin_id',         u.s_twin,
              'related_twin_id', u.r_twin,
              'occurred_at',     u.occurred_at,
              'ended_at',        u.ended_at,
              'attrs',           u.attrs,
              'source',          u.draha,
              'source_ref',      u.source_ref)), '[]'::jsonb)
       FROM udalosti u
      WHERE u.existujici IS NULL OR u.zmena)
  INTO v_prijato, v_neplatne, v_bez, v_druh, v_nove, v_zmenene, v_udalosti, v_zapis;

  -- Prázdná dávka nic nezapisuje ani neaudituje (takt beze změn).
  IF jsonb_array_length(v_zapis) > 0 THEN
    PERFORM public.twin_record_events_audited(v_zapis);
  END IF;

  RETURN jsonb_build_object(
    'prijato',    v_prijato,
    'nove',       v_nove,
    'zmenene',    v_zmenene,
    'beze_zmeny', v_udalosti - v_nove - v_zmenene,
    'bez_vazby',  v_bez,
    'jiny_druh',  v_druh,
    'neplatne',   v_neplatne
  );
END;
$$;

REVOKE ALL ON FUNCTION public.twin_project_events(text, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.twin_project_events(text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/avp_project_fuelings.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: avp_project_fuelings
-- Popis: TENKÝ ADAPTÉR výdejů AVP (obecná surová dráha source_catalog_rows,
--        zdroj 'avp-portal', druh 'fueling') → twin_project_events. Přeloží
--        řádky do tvaru jádra; identitu, druh entity, porovnání a zápis dělá
--        jádro. Událost 'fueling' na dvojčeti vozidla, řidič = druhá strana,
--        dráha 'avp-portal:fueling' (katalog fueling_liters čte atribut liters).
--
-- KDO TANKOVAL (soupis ostré instance 19. 8., 9 880 výdejů): výdej nese kartu
-- vozidla (vehicleId, jen 70 %) a kartu řidiče (driverId, 98 %) z /cards,
-- a vždy kódy čipů. Subjekt = karta vozidla ('karta:<id>', primary_id); kde
-- karta chybí, čip vozidla ('cip:<kód>', field_identity — resolve k ČASU
-- výdeje, čip se může přesunout). Řidič stejně. Výdej bez karty i čipu
-- vozidla nemá komu patřit (kanystr, neznámé) — jen se spočítá.
--
-- PLATNÁ VERZE (tamtéž, naivní filtr nafoukne počet o ~19 %): poslední článek
-- řetězu oprav parent_id ∧ ¬hidden ∧ ¬removed. Posílají se VŠECHNY verze, litry
-- ale nese jen platná; nahrazená/skrytá/odstraněná má liters = null a `stav`.
-- Oprava, která přijde později, tak předchozí verzi v dvojčeti VYNULUJE jako
-- změnu události — součet ji přestane počítat, nic se nemaže.
--
-- Které výdeje posílá (šetrně, volá se po každé synchronizaci):
--   • dosud NEPROMÍTNUTÉ výdeje s platnou vazbou subjektu k času výdeje,
--   • výdeje, na které synchronizace sáhla v posledních `p_okno_min` minutách,
--   • RODIČE takových výdejů (jejich platnost se novou opravou změnila).
-- Cena (unit_price bývá 0) ani dopočtený stav nádrže se nepřenáší.
--
-- Vrací: výsledek twin_project_events + {ceka_na_vazbu, bez_vozidla}
-- Bezpečnost: SECURITY DEFINER; jen service_role (volá plugin přes broker).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.avp_project_fuelings(
  p_okno_min integer DEFAULT 180,
  p_limit    integer DEFAULT 5000
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  c_source   constant text := 'avp-portal';
  v_source   text;
  v_lane     text;
  v_rows     jsonb;
  v_ceka     integer;
  v_bez      integer;
  v_vysledek jsonb;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'avp_project_fuelings: service role required'
      USING ERRCODE = '42501';
  END IF;
  IF p_okno_min IS NULL OR p_okno_min < 0 OR p_okno_min > 10080 THEN
    RAISE EXCEPTION 'avp_project_fuelings: p_okno_min must be between 0 and 10080'
      USING ERRCODE = '22023';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 20000 THEN
    RAISE EXCEPTION 'avp_project_fuelings: p_limit must be between 1 and 20000'
      USING ERRCODE = '22023';
  END IF;
  v_source := public.canonical_ingest_source(c_source);
  v_lane   := v_source || ':fueling';

  WITH vydeje AS (
    SELECT c.external_id, c.occurred_at, c.synced_at, c.fields
      FROM public.source_catalog_rows c
     WHERE c.source_slug = c_source AND c.kind = 'fueling' AND c.occurred_at IS NOT NULL
  ),
  rodice AS (
    -- Množina nahrazených verzí se spočítá JEDNOU (hash), ne dotazem na řádek.
    -- Z katalogu, ne z odpovědi API: rodič bývá mimo aktuální okno synchronizace.
    SELECT DISTINCT v.fields->>'parent_id' AS pid
      FROM vydeje v
     WHERE nullif(v.fields->>'parent_id', '') IS NOT NULL
  ),
  urceni AS (
    SELECT v.external_id, v.occurred_at, v.synced_at, v.fields,
           CASE WHEN nullif(v.fields->>'vehicle_id', '') IS NOT NULL THEN 'karta:' || (v.fields->>'vehicle_id')
                WHEN nullif(v.fields->>'vehicle_chip', '') IS NOT NULL THEN 'cip:' || upper(v.fields->>'vehicle_chip')
           END AS v_key,
           CASE WHEN nullif(v.fields->>'vehicle_id', '') IS NOT NULL THEN 'primary_id' ELSE 'field_identity' END AS v_kind,
           CASE WHEN nullif(v.fields->>'driver_id', '') IS NOT NULL THEN 'karta:' || (v.fields->>'driver_id')
                WHEN nullif(v.fields->>'driver_chip', '') IS NOT NULL THEN 'cip:' || upper(v.fields->>'driver_chip')
           END AS d_key,
           CASE WHEN nullif(v.fields->>'driver_id', '') IS NOT NULL THEN 'primary_id' ELSE 'field_identity' END AS d_kind,
           CASE WHEN coalesce((v.fields->>'removed')::boolean, false) THEN 'odstraneno'
                WHEN coalesce((v.fields->>'hidden')::boolean, false)  THEN 'skryto'
                WHEN r.pid IS NOT NULL                                THEN 'nahrazeno'
                ELSE 'platne' END AS stav
      FROM vydeje v
      LEFT JOIN rodice r ON r.pid = v.external_id
  ),
  vse AS (
    SELECT u.external_id, u.occurred_at, u.synced_at, u.fields, u.v_key, u.v_kind, u.d_key, u.d_kind, u.stav,
           EXISTS (SELECT 1 FROM public.twin_events e
                    WHERE e.source = v_lane AND e.event_type = 'fueling' AND e.source_ref = u.external_id) AS promitnuto,
           -- Levné předběžné síto: vazba subjektu k času výdeje; rozhoduje jádro.
           EXISTS (SELECT 1 FROM public.twin_external_refs b
                    WHERE b.source = v_source AND b.source_key = u.v_key AND b.ref_kind = u.v_kind
                      AND b.state = 'confirmed'
                      AND b.valid_from <= u.occurred_at
                      AND (b.valid_to IS NULL OR b.valid_to > u.occurred_at)) AS vazba
      FROM urceni u
     WHERE u.v_key IS NOT NULL
  ),
  nedavne AS (
    SELECT a.external_id, a.fields->>'parent_id' AS pid
      FROM vse a
     WHERE a.synced_at >= now() - make_interval(mins => p_okno_min)
  ),
  kandidati AS (
    SELECT a.external_id, a.occurred_at, a.fields, a.v_key, a.v_kind, a.d_key, a.d_kind, a.stav
      FROM vse a
     WHERE a.vazba
       AND (NOT a.promitnuto
            OR EXISTS (SELECT 1 FROM nedavne n WHERE n.external_id = a.external_id)
            OR EXISTS (SELECT 1 FROM nedavne n WHERE n.pid = a.external_id))
     ORDER BY a.occurred_at
     LIMIT p_limit
  )
  SELECT
    (SELECT coalesce(jsonb_agg(jsonb_build_object(
              'event_type',  'fueling',
              'lane',        'fueling',
              'source_ref',  k.external_id,
              'subject',     jsonb_build_object('key', k.v_key, 'ref_kind', k.v_kind, 'entity_type', 'vehicle'),
              'related',     CASE WHEN k.d_key IS NOT NULL
                                  THEN jsonb_build_object('key', k.d_key, 'ref_kind', k.d_kind, 'entity_type', 'driver')
                             END,
              'occurred_at', k.occurred_at,
              'attrs',       jsonb_strip_nulls(jsonb_build_object(
                               'liters',             CASE WHEN k.stav = 'platne' THEN k.fields->'liters' END,
                               'compensated_liters', CASE WHEN k.stav = 'platne' THEN k.fields->'compensated_liters' END,
                               'duration_s',         k.fields->'duration_s',
                               'tank_id',            k.fields->'tank_id',
                               'stav',               k.stav,
                               'vozidlo_z_cipu',     CASE WHEN k.v_kind = 'field_identity' THEN true END))
            ) ORDER BY k.occurred_at), '[]'::jsonb)
       FROM kandidati k),
    -- Kolik výdejů čeká na člověka (vazba vozidla chybí nebo k času výdeje neplatí).
    (SELECT count(*) FROM vse a WHERE NOT a.promitnuto AND NOT a.vazba)
  INTO v_rows, v_ceka;

  SELECT count(*) INTO v_bez
    FROM public.source_catalog_rows c
   WHERE c.source_slug = c_source AND c.kind = 'fueling'
     AND nullif(c.fields->>'vehicle_id', '') IS NULL
     AND nullif(c.fields->>'vehicle_chip', '') IS NULL;

  v_vysledek := public.twin_project_events(c_source, v_rows);
  RETURN v_vysledek || jsonb_build_object('ceka_na_vazbu', v_ceka, 'bez_vozidla', v_bez);
END;
$$;

REVOKE ALL ON FUNCTION public.avp_project_fuelings(integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.avp_project_fuelings(integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_project_trips.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_project_trips
-- Popis: Jízdy ZDROJE → události 'trip' na dvojčeti vozidla (řidič = druhá
--        strana). Obecné jádro projekce: nezná dodavatele ani jeho tabulky —
--        dostane řádky v jednom tvaru a zdroj, jehož vazby identity platí.
--        Adaptér zdroje (dnes čte vendor tabulku, zítra řady source_catalog_rows)
--        jen přeloží své řádky do tohoto tvaru; jádro se při přepojení nemění.
--
-- IDENTITA: vozidlo i řidič se resolvují přes twin_identity_resolve VÝHRADNĚ
-- pro zdroj `p_source` a k ČASU JÍZDY. Jen potvrzené a tehdy platné vazby —
-- návrhy runtime nevidí. Jízda bez vazby vozidla se NEZAPÍŠE a nic se kvůli ní
-- nezakládá (jen se spočítá); promítne se při dalším volání, až bude vazba
-- potvrzená a platná (adaptér posílá každou dosud nepromítnutou jízdu).
-- Řidič bez vazby jízdu neblokuje — událost ho prostě nemá.
--
-- ZÁPIS: jen NOVÉ nebo ZMĚNĚNÉ události (porovnává s tím, co už v twin_events
-- leží). Zdroje opravují jízdy zpětně a adaptéry čtou s překryvem oken — bez
-- porovnání by každé volání přepsalo a zauditovalo celé okno beze změny.
-- Samotný zápis jde přes twin_record_events_audited (dedup přes
-- (source, event_type, source_ref), audit bez osobních údajů).
--
-- `source` události = '<p_source>:trip' (dráha zdroje, vzor Eurowagu), takže
-- čtečky vidí, kdo co tvrdí, a dedup jízd se nepotká s jinými událostmi zdroje.
--
-- Vstup p_rows: [{ "source_ref": "<id jízdy ve zdroji>",
--                  "vehicle_key": "<id vozidla ve zdroji>",
--                  "driver_key":  "<id řidiče ve zdroji>" | null,
--                  "started_at": "<ISO>", "ended_at": "<ISO>" | null,
--                  "attrs": { "distance_km": …, "consumption_l": …, … } }, …]
--   Jména atributů určuje katalog parametrů (`twin_parameter_definitions.
--   metadata.attr`), ne tahle funkce.
--
-- Od 2026-09-27 OBAL nad twin_project_events (viz tělo) — chování i tvar beze změny,
-- navíc `jiny_druh` (vazba vedla na dvojče jiného druhu → nezapsáno).
--
-- Vrací: {prijato, nove, zmenene, beze_zmeny, bez_vazby_vozidla, jiny_druh, neplatne}
-- Bezpečnost: SECURITY DEFINER; jen service_role (projekci spouští zdroj).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.twin_project_trips(
  p_source text,
  p_rows   jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_obecne   jsonb;
  v_vysledek jsonb;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'twin_project_trips: service role required'
      USING ERRCODE = '42501';
  END IF;
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'twin_project_trips: p_rows must be a jsonb array'
      USING ERRCODE = '22023';
  END IF;

  -- Jízda = obecná událost 'trip' na dvojčeti vozidla, řidič je druhá strana.
  -- Od 2026-09-27 je to jen OBAL nad twin_project_events (identita, druh
  -- entity, porovnání a zápis žijí na jednom místě); tvar vstupu i výsledku
  -- zůstal, aby adaptéry jízd nemusely nic měnit. Druh entity lze v řádku
  -- přebít (`vehicle_type`, `driver_type`), výchozí je slovník, který jádro
  -- dvojčat používá i jinde.
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'event_type',  'trip',
           'lane',        'trip',
           'source_ref',  r->'source_ref',
           'subject',     jsonb_build_object(
                            'key',         r->'vehicle_key',
                            'ref_kind',    'primary_id',
                            'entity_type', coalesce(nullif(btrim(r->>'vehicle_type'), ''), 'vehicle')),
           'related',     CASE WHEN nullif(btrim(r->>'driver_key'), '') IS NOT NULL
                               THEN jsonb_build_object(
                                      'key',         r->'driver_key',
                                      'ref_kind',    'primary_id',
                                      'entity_type', coalesce(nullif(btrim(r->>'driver_type'), ''), 'driver'))
                          END,
           'occurred_at', r->'started_at',
           'ended_at',    r->'ended_at',
           'attrs',       r->'attrs'
         )), '[]'::jsonb)
    INTO v_obecne
    FROM jsonb_array_elements(p_rows) AS r;

  v_vysledek := public.twin_project_events(p_source, v_obecne);

  RETURN jsonb_build_object(
    'prijato',           v_vysledek->'prijato',
    'nove',              v_vysledek->'nove',
    'zmenene',           v_vysledek->'zmenene',
    'beze_zmeny',        v_vysledek->'beze_zmeny',
    'bez_vazby_vozidla', v_vysledek->'bez_vazby',
    'jiny_druh',         v_vysledek->'jiny_druh',
    'neplatne',          v_vysledek->'neplatne'
  );
END;
$$;

REVOKE ALL ON FUNCTION public.twin_project_trips(text, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.twin_project_trips(text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/ew_project_catalog.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: ew_project_catalog
-- Popis: TENKÝ ADAPTÉR surové dráhy Eurowagu (source_catalog_rows, zdroj
--        'eurowag-telematics') → obecné jádro projekce. Přeloží řádky do tvaru
--        jádra; identitu, druh entity, porovnání a zápis dělá jádro.
--
--   jízdy ('trip')          → twin_project_trips, dráha 'eurowag-telematics:trip':
--                             km, spotřeba, l/100 km, doba, palivo, CO₂, náklad.
--                             Katalog určuje, co se sčítá: nájezd má autoritu
--                             Webdispečink (majitel 2026-09-27), spotřeba Eurowag.
--   stavy ('vehicle_state') → twin_project_events 'vehicle_state', dráha
--                             'eurowag-telematics:vehicle-state': tachometr (km),
--                             hladina (l), zapalování — ŽÁDNÁ poloha (plugin ji
--                             ani neukládá).
--
-- Klíče stejné jako ew_propose_identity: 'vozidlo:<monitoredObjectId>',
-- 'osoba:<driver id>'.
--
-- Které záznamy posílá (šetrně — volá se po každé synchronizaci):
--   • dosud NEPROMÍTNUTÉ záznamy vozidel s potvrzenou a k času platnou vazbou,
--   • záznamy, které synchronizace uložila v posledních `p_okno_min` minutách.
-- Stavy jen za posledních `p_stavy_dni` dní: řada roste po hodinách a hladina
-- se čte jako POSLEDNÍ hodnota — staré nepromítnuté stavy by jen zdržovaly.
-- Záznamy bez platné vazby se spočítají (`ceka_na_vazbu`) a promítnou se samy,
-- až člověk vazbu potvrdí.
--
-- Vrací: {jizdy: <výsledek twin_project_trips> + ceka_na_vazbu,
--         stavy: <výsledek twin_project_events> + ceka_na_vazbu}
-- Bezpečnost: SECURITY DEFINER; jen service_role (volá plugin přes broker).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.ew_project_catalog(
  p_okno_min   integer DEFAULT 180,
  p_limit      integer DEFAULT 5000,
  p_stavy_dni  integer DEFAULT 30
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  c_source     constant text := 'eurowag-telematics';
  v_source     text;
  v_jizdy      jsonb;
  v_stavy      jsonb;
  v_ceka_j     integer;
  v_ceka_s     integer;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'ew_project_catalog: service role required'
      USING ERRCODE = '42501';
  END IF;
  IF p_okno_min IS NULL OR p_okno_min < 0 OR p_okno_min > 10080 THEN
    RAISE EXCEPTION 'ew_project_catalog: p_okno_min must be between 0 and 10080'
      USING ERRCODE = '22023';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 20000 THEN
    RAISE EXCEPTION 'ew_project_catalog: p_limit must be between 1 and 20000'
      USING ERRCODE = '22023';
  END IF;
  IF p_stavy_dni IS NULL OR p_stavy_dni < 1 OR p_stavy_dni > 366 THEN
    RAISE EXCEPTION 'ew_project_catalog: p_stavy_dni must be between 1 and 366'
      USING ERRCODE = '22023';
  END IF;
  v_source := public.canonical_ingest_source(c_source);

  -- ── jízdy ─────────────────────────────────────────────────────────────────
  WITH vse AS (
    SELECT c.external_id, c.occurred_at, c.synced_at, c.fields,
           'vozidlo:' || (c.fields->>'monitored_object_id') AS v_key,
           EXISTS (SELECT 1 FROM public.twin_events e
                    WHERE e.source = v_source || ':trip' AND e.event_type = 'trip'
                      AND e.source_ref = c.external_id) AS promitnuto,
           EXISTS (SELECT 1 FROM public.twin_external_refs b
                    WHERE b.source = v_source
                      AND b.source_key = 'vozidlo:' || (c.fields->>'monitored_object_id')
                      AND b.ref_kind = 'primary_id' AND b.state = 'confirmed'
                      AND b.valid_from <= c.occurred_at
                      AND (b.valid_to IS NULL OR b.valid_to > c.occurred_at)) AS vazba
      FROM public.source_catalog_rows c
     WHERE c.source_slug = c_source AND c.kind = 'trip' AND c.occurred_at IS NOT NULL
       AND nullif(c.fields->>'monitored_object_id', '') IS NOT NULL
  ),
  kandidati AS (
    SELECT a.external_id, a.occurred_at, a.fields, a.v_key
      FROM vse a
     WHERE a.vazba
       AND (NOT a.promitnuto OR a.synced_at >= now() - make_interval(mins => p_okno_min))
     ORDER BY a.occurred_at
     LIMIT p_limit
  )
  SELECT
    (SELECT coalesce(jsonb_agg(jsonb_build_object(
              'source_ref',  k.external_id,
              'vehicle_key', k.v_key,
              'driver_key',  'osoba:' || nullif(k.fields->>'driver_id', ''),
              'started_at',  k.occurred_at,
              'ended_at',    nullif(k.fields->>'end_time', ''),
              'attrs',       jsonb_strip_nulls(jsonb_build_object(
                               'distance_km',         k.fields->'distance_km',
                               'consumption_l',       k.fields->'consumption_l',
                               'consumption_l_100km', k.fields->'consumption_l_100km',
                               'duration_seconds',    k.fields->'duration_s',
                               'fuel_type',           k.fields->'fuel_type',
                               'co2_emission',        k.fields->'co2_emission',
                               'cargo_weight_kg',     k.fields->'cargo_weight_kg'))
            ) ORDER BY k.occurred_at), '[]'::jsonb)
       FROM kandidati k),
    (SELECT count(*) FROM vse a WHERE NOT a.promitnuto AND NOT a.vazba)
  INTO v_jizdy, v_ceka_j;

  -- ── stavy vozidel ─────────────────────────────────────────────────────────
  WITH vse AS (
    SELECT c.external_id, c.occurred_at, c.synced_at, c.fields,
           'vozidlo:' || (c.fields->>'monitored_object_id') AS v_key,
           EXISTS (SELECT 1 FROM public.twin_events e
                    WHERE e.source = v_source || ':vehicle-state' AND e.event_type = 'vehicle_state'
                      AND e.source_ref = c.external_id) AS promitnuto,
           EXISTS (SELECT 1 FROM public.twin_external_refs b
                    WHERE b.source = v_source
                      AND b.source_key = 'vozidlo:' || (c.fields->>'monitored_object_id')
                      AND b.ref_kind = 'primary_id' AND b.state = 'confirmed'
                      AND b.valid_from <= c.occurred_at
                      AND (b.valid_to IS NULL OR b.valid_to > c.occurred_at)) AS vazba
      FROM public.source_catalog_rows c
     WHERE c.source_slug = c_source AND c.kind = 'vehicle_state'
       AND c.occurred_at >= now() - make_interval(days => p_stavy_dni)
       AND nullif(c.fields->>'monitored_object_id', '') IS NOT NULL
  ),
  kandidati AS (
    SELECT a.external_id, a.occurred_at, a.fields, a.v_key
      FROM vse a
     WHERE a.vazba
       AND (NOT a.promitnuto OR a.synced_at >= now() - make_interval(mins => p_okno_min))
     ORDER BY a.occurred_at
     LIMIT p_limit
  )
  SELECT
    (SELECT coalesce(jsonb_agg(jsonb_build_object(
              'event_type',  'vehicle_state',
              'lane',        'vehicle-state',
              'source_ref',  k.external_id,
              'subject',     jsonb_build_object('key', k.v_key, 'ref_kind', 'primary_id', 'entity_type', 'vehicle'),
              'occurred_at', k.occurred_at,
              'attrs',       jsonb_strip_nulls(jsonb_build_object(
                               'odometer_km',  k.fields->'odometer_km',
                               'fuel_level_l', k.fields->'fuel_level_l',
                               'ignition',     k.fields->'ignition'))
            ) ORDER BY k.occurred_at), '[]'::jsonb)
       FROM kandidati k),
    (SELECT count(*) FROM vse a WHERE NOT a.promitnuto AND NOT a.vazba)
  INTO v_stavy, v_ceka_s;

  RETURN jsonb_build_object(
    'jizdy', public.twin_project_trips(c_source, v_jizdy) || jsonb_build_object('ceka_na_vazbu', v_ceka_j),
    'stavy', public.twin_project_events(c_source, v_stavy) || jsonb_build_object('ceka_na_vazbu', v_ceka_s)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.ew_project_catalog(integer, integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.ew_project_catalog(integer, integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/tc_project_rides.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: tc_project_rides
-- Popis: TENKÝ ADAPTÉR T-cars → twin_project_trips. Přeloží řádky kniha jízd
--        (tc_rides) do tvaru obecného jádra a nic víc: identitu, porovnání
--        a zápis dělá jádro. Až T-cars přejde na obecnou surovou dráhu
--        (source_catalog_rows), nahradí se JEN tahle funkce — jádro zůstane.
--
-- Které jízdy posílá (šetrně — volá se po každé synchronizaci):
--   • dosud NEPROMÍTNUTÉ jízdy vozidel, jejichž vazba je k času jízdy potvrzená
--     a platná (levné předběžné síto; rozhoduje jádro přes twin_identity_resolve),
--   • a jízdy, na které synchronizace sáhla v posledních `p_okno_min` minutách
--     (překryv oken: dodavatel opravuje zpětně). Jádro z nich zapíše jen ty,
--     které se opravdu změnily.
-- Klíče vozidla a řidiče nesou druh objektu ('vozidlo:…', 'osoba:…') — T-cars
-- čísluje obojí zvlášť a vazba identity je jedinečná bez druhu entity (viz
-- tc_propose_identity). Adaptér a návrhy musí klíč skládat STEJNĚ.
--
-- Jízdy vozidel bez platné vazby se neposílají, jen spočítají
-- (`ceka_na_vazbu`) — promítnou se samy, až člověk vazbu potvrdí.
--
-- Atributy = jen to, co měří katalog a co je o VOZIDLE: kilometry, tachometr,
-- soukromá jízda, země. Místa začátku a konce se NEPŘENÁŠEJÍ: polohy majitel
-- nepovolil a adresa soukromé jízdy je osobní údaj řidiče.
--
-- Vrací: výsledek twin_project_trips + {ceka_na_vazbu}
-- Bezpečnost: SECURITY DEFINER; jen service_role (volá plugin přes broker).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.tc_project_rides(
  p_okno_min integer DEFAULT 180,
  p_limit    integer DEFAULT 5000
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  c_source  constant text := 'tcars-fleet';
  v_lane    text;
  v_rows    jsonb;
  v_ceka    integer;
  v_vysledek jsonb;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'tc_project_rides: service role required'
      USING ERRCODE = '42501';
  END IF;
  IF p_okno_min IS NULL OR p_okno_min < 0 OR p_okno_min > 10080 THEN
    RAISE EXCEPTION 'tc_project_rides: p_okno_min must be between 0 and 10080'
      USING ERRCODE = '22023';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 20000 THEN
    RAISE EXCEPTION 'tc_project_rides: p_limit must be between 1 and 20000'
      USING ERRCODE = '22023';
  END IF;
  v_lane := public.canonical_ingest_source(c_source) || ':trip';

  WITH kandidati AS (
    SELECT r.tc_ride_id, r.tc_vehicle_id, r.tc_driver_id, r.start_time, r.end_time,
           r.distance_km, r.odometer_start_km, r.odometer_end_km, r.private, r.country
      FROM public.tc_rides r
     WHERE r.start_time IS NOT NULL
       AND EXISTS (
             SELECT 1 FROM public.twin_external_refs b
              WHERE b.source = public.canonical_ingest_source(c_source)
                AND b.source_key = 'vozidlo:' || r.tc_vehicle_id
                AND b.ref_kind = 'primary_id'
                AND b.state = 'confirmed'
                AND b.valid_from <= r.start_time
                AND (b.valid_to IS NULL OR b.valid_to > r.start_time))
       AND (r.updated_at >= now() - make_interval(mins => p_okno_min)
            OR NOT EXISTS (
                 SELECT 1 FROM public.twin_events e
                  WHERE e.source = v_lane AND e.event_type = 'trip'
                    AND e.source_ref = r.tc_ride_id::text))
     ORDER BY r.start_time
     LIMIT p_limit
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'source_ref',  k.tc_ride_id::text,
           'vehicle_key', 'vozidlo:' || k.tc_vehicle_id,
           'driver_key',  'osoba:' || k.tc_driver_id,
           'started_at',  k.start_time,
           'ended_at',    k.end_time,
           'attrs',       jsonb_strip_nulls(jsonb_build_object(
                            'distance_km',       k.distance_km,
                            'odometer_start_km', k.odometer_start_km,
                            'odometer_end_km',   k.odometer_end_km,
                            'private',           k.private,
                            'country',           k.country))
         ) ORDER BY k.start_time), '[]'::jsonb)
    INTO v_rows
    FROM kandidati k;

  -- Kolik jízd čeká na člověka (vazba vozidla chybí nebo k času jízdy neplatí).
  SELECT count(*) INTO v_ceka
    FROM public.tc_rides r
   WHERE NOT EXISTS (
           SELECT 1 FROM public.twin_events e
            WHERE e.source = v_lane AND e.event_type = 'trip'
              AND e.source_ref = r.tc_ride_id::text)
     AND NOT EXISTS (
           SELECT 1 FROM public.twin_external_refs b
            WHERE b.source = public.canonical_ingest_source(c_source)
              AND b.source_key = 'vozidlo:' || r.tc_vehicle_id
              AND b.ref_kind = 'primary_id'
              AND b.state = 'confirmed'
              AND b.valid_from <= r.start_time
              AND (b.valid_to IS NULL OR b.valid_to > r.start_time));

  v_vysledek := public.twin_project_trips(c_source, v_rows);
  RETURN v_vysledek || jsonb_build_object('ceka_na_vazbu', v_ceka);
END;
$$;

REVOKE ALL ON FUNCTION public.tc_project_rides(integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.tc_project_rides(integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_ref_davka_vratit.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_ref_davka_vratit
-- Popis: VRÁCENÍ hromadného schválení návrhů identit (twin_ref_group_decide).
--        Majitel: „vše vratné, s původem u dat". Kontrakt dávek (2026-09-23):
--        po položkách v OPAČNÉM pořadí přes batch_id; co se od dávky změnilo,
--        se nevrací a zapíše se jako `preskoceno_zmenene`.
--
-- Položka se vrací jen tehdy, když ji od dávky nikdo nezměnil:
--   potvrzeno     → návrh je pořád confirmed, platný (valid_to NULL) a nese
--                   confirmed_at zapsané dávkou → zpět na proposed
--   uz_potvrzeno  → návrh je pořád superseded (bezpředmětný) → zpět na proposed
-- Chybové položky dávka nezměnila, vracet není co.
-- Audit: jeden záznam vrácení s počty (bez klíčů zdroje).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_ref_davka_vratit(p_batch_id uuid, p_note text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_vraceno integer := 0;
  v_skip    integer := 0;
  v_hit     integer;
  r         record;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff required' USING ERRCODE = '42501';
  END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Revert requires an authenticated reviewer (auth.uid() is null)' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.twin_ref_davky WHERE batch_id = p_batch_id) THEN
    RAISE EXCEPTION 'batch % not found', p_batch_id USING ERRCODE = 'P0002';
  END IF;

  FOR r IN
    SELECT d.ref_id, d.vysledek, d.potvrzeno_at, d.platnost_pred
      FROM public.twin_ref_davky d
     WHERE d.batch_id = p_batch_id AND d.vraceno IS NULL AND d.vysledek <> 'chyba'
     ORDER BY d.poradi DESC
     FOR UPDATE
  LOOP
    IF r.vysledek = 'potvrzeno' THEN
      UPDATE public.twin_external_refs
         SET state = 'proposed', confirmed_by = NULL, confirmed_at = NULL,
             valid_from = r.platnost_pred, updated_at = now()
       WHERE id = r.ref_id AND state = 'confirmed' AND valid_to IS NULL
         AND confirmed_at IS NOT DISTINCT FROM r.potvrzeno_at;
    ELSE
      UPDATE public.twin_external_refs
         SET state = 'proposed', updated_at = now()
       WHERE id = r.ref_id AND state = 'superseded';
    END IF;
    GET DIAGNOSTICS v_hit = ROW_COUNT;

    UPDATE public.twin_ref_davky
       SET vraceno = CASE WHEN v_hit > 0 THEN 'vraceno' ELSE 'preskoceno_zmenene' END,
           vraceno_at = now(), vratil = v_uid
     WHERE batch_id = p_batch_id AND ref_id = r.ref_id;
    IF v_hit > 0 THEN v_vraceno := v_vraceno + 1; ELSE v_skip := v_skip + 1; END IF;
  END LOOP;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (v_uid, 'twin_external_refs.batch_reverted', 'twin_external_refs.batch_reverted', 'content', 'info',
          array['surface', 'write', 'twin_identity', 'batch'],
          jsonb_build_object('batch_id', p_batch_id, 'vraceno', v_vraceno,
                             'preskoceno_zmenene', v_skip, 'note', p_note));

  RETURN jsonb_build_object('batch_id', p_batch_id, 'vraceno', v_vraceno, 'preskoceno_zmenene', v_skip);
END;
$$;

REVOKE ALL ON FUNCTION public.twin_ref_davka_vratit(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.twin_ref_davka_vratit(uuid, text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_ref_tridy.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_ref_tridy
-- Popis: TŘÍDA SHODY návrhů identit (twin_external_refs, stav proposed) —
--        JEDINÝ vlastník pravidla „smí se tenhle návrh schválit v dávce?".
--        Blok skupin (get_twin_ref_group_block) z něj skládá nabídku, dávka
--        (twin_ref_group_decide) ho volá ZNOVU v okamžiku provedení; co mezitím
--        přestalo platit, do dávky nepadne.
--
-- ⛔ PRAVIDLO MAJITELE (2026-09-28): „teprve dva zdroje pravdy se shodou sto
-- procent opravňují k návrhu na hromadné sloučení"; „pokud jméno nemá IČO, může
-- to být soukromá osoba"; „co se týká IČO, je to v závislosti na časovém údaji";
-- „pokud je IČO a název a odpovídá to datum z veřejného rejstříku, můžeme to brát
-- jako potvrzení existence". Důkazy se odvozují ŽIVĚ z dokladů, které ingest drží
-- teď — ne z poznámky exportu, ze kterého návrh kdysi vznikl.
--
-- ZDROJ PRAVDY = třída dokladu, kterou přiděluje ingest (li_source_registry
-- .doc_class, např. záznamy účetnictví × smluvní dokumenty) + výpis z veřejného
-- rejstříku (doc_type z konfigurace). Dva exporty téhož účetnictví jsou JEDEN
-- zdroj — naměřeno 2026-09-28: 844 z 879 návrhů IČO stálo jen na účetnictví.
--
-- JMÉNO V ČASE: firma se přejmenuje a staré jméno může převzít jiná firma, takže
-- se jméno z dokladu porovnává se jménem PLATNÝM K DATU dokladu, ne s dnešním.
--   · s výpisem z rejstříku: každý datovaný doklad musí nést jméno, které rejstřík
--     k jeho datu vede; jinak rozpor. Shoda = aspoň jeden takový doklad + dnešní
--     jméno z rejstříku sedí na dvojče.
--   · bez výpisu: rozpor = dvě různá jména téhož IČO v překrývajícím se období;
--     shoda = totéž (poslední) jméno ve dvou třídách dokladů a v celém rozpětí,
--     kdy ho uvádějí, žádné jiné jméno; poslední jméno sedí na dvojče.
--
-- TŘÍDY: shoda_dva_zdroje | jeden_zdroj | rozpor | jmeno_nesedi_na_twin |
--        smisene_dvojce (dvojče nese i jméno, které IČO nikdy nemělo) |
--        bez_data | bez_dokladu | nepodporovano (jiný druh klíče než IČO —
--        samotné jméno může patřit soukromé osobě, hromadně nikdy).
--
-- Konfigurace (p_params = source_params bloku skupin):
--   source       POVINNÉ  twin_external_refs.source
--   entity_type  volitelné twin_entities.entity_type
--   date_fields  POVINNÉ  {doc_type: [pole data, …]} — první vyplněné je datum
--                         dokladu (schémata časovou osu nedeklarují)
--   register     volitelné {doc_type, ico_field, name_field, from_field, to_field}
--                         — výpis z rejstříku: IČO v hlavičce, období jmen v položkách
-- p_ref_ids: omezení na konkrétní návrhy (NULL = všechny navržené ze zdroje).
--
-- SECURITY INVOKER: volající vidí jen doklady, na které má nárok. Blok i dávka
-- jsou pro správu, která vidí vše — třída tak nezávisí na tom, kdo se ptá.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_ref_tridy(p_params jsonb, p_ref_ids uuid[] DEFAULT NULL)
RETURNS TABLE (ref_id uuid, ref_kind text, twin_id uuid, trida text, group_key text,
               zdroje text[], jmeno_ted text)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  with cfg as (
    select p_params->>'source'                       as src,
           nullif(p_params->>'entity_type', '')      as etype,
           coalesce(p_params->'date_fields', '{}')   as df,
           p_params->'register'                      as reg
  ),
  n as (
    select r.id, r.ref_kind, r.twin_id, r.source_key, t.label,
           case when r.ref_kind = 'company_ico' and btrim(r.source_key) ~ '^\d{1,8}$'
                then lpad(btrim(r.source_key), 8, '0') end as ico
    from public.twin_external_refs r
    join public.twin_entities t on t.id = r.twin_id
    cross join cfg
    where r.source = cfg.src
      and r.state = 'proposed'
      and (cfg.etype is null or t.entity_type = cfg.etype)
      and (p_ref_ids is null or r.id = any (p_ref_ids))
  ),
  ica as (select distinct ico from n where ico is not null),
  -- Klíč původu nese IČO tak, jak ho zapsal doklad; s úvodními nulami i bez nich.
  hk as (select ico, ico as h from ica union select ico, ltrim(ico, '0') from ica),
  -- Doklady, které IČO nesou (klíče původu), s třídou, jménem a datem dokladu.
  dk as (
    select distinct on (hk.ico, d.source_sha256)
           hk.ico, d.source_sha256, d.doc_class as zdroj,
           public.nazev_firmy_klic(case
             when k.field_key = 'supplier_id' then d.fields->'supplier_name'->>'value'
             when k.field_key = 'counterparty_id' then d.fields->'counterparty'->>'value'
             when lpad(btrim(coalesce(d.fields->'supplier_id'->>'value', '')), 8, '0') = hk.ico
               then d.fields->'supplier_name'->>'value'
             when lpad(btrim(coalesce(d.fields->'counterparty_id'->>'value', '')), 8, '0') = hk.ico
               then d.fields->'counterparty'->>'value' end) as jmeno,
           (select left(d.fields->f->>'value', 10)::date
              from jsonb_array_elements_text(coalesce((select df from cfg)->d.doc_type, '[]')) f
             where d.fields->f->>'value' ~ '^\d{4}-\d{2}-\d{2}'
             limit 1) as dt
    from hk
    join public.li_doc_scope_keys k
      on k.hodnota = hk.h and k.field_key in ('counterparty_id', 'supplier_id', '@firma')
    join public.li_source_registry d
      on d.source_sha256 = k.source_sha256 and d.superseded_by is null
    where d.doc_type is distinct from ((select reg from cfg)->>'doc_type')
    order by hk.ico, d.source_sha256, k.field_key
  ),
  dd as (select ico, source_sha256, zdroj, jmeno, dt from dk where dt is not null and jmeno is not null),
  -- Období jmen z výpisu rejstříku [od, do); do NULL = platí dosud.
  rg as (
    select x.ico, x.jmeno, x.od, x.do_
    from cfg c
    join public.li_source_registry d
      on c.reg is not null and d.doc_type = c.reg->>'doc_type' and d.superseded_by is null
    cross join lateral jsonb_array_elements(coalesce(d.line_items, '[]')) li
    cross join lateral (select
        lpad(regexp_replace(coalesce(d.fields->(c.reg->>'ico_field')->>'value', ''), '\D', '', 'g'), 8, '0') as ico,
        public.nazev_firmy_klic(li->'fields'->(c.reg->>'name_field')->>'value') as jmeno,
        case when li->'fields'->(c.reg->>'from_field')->>'value' ~ '^\d{4}-\d{2}-\d{2}'
             then left(li->'fields'->(c.reg->>'from_field')->>'value', 10)::date end as od,
        case when li->'fields'->(c.reg->>'to_field')->>'value' ~ '^\d{4}-\d{2}-\d{2}'
             then left(li->'fields'->(c.reg->>'to_field')->>'value', 10)::date end as do_) x
    where x.od is not null and x.jmeno is not null
      and x.ico in (select ico from ica)
  ),
  -- Každý datovaný doklad vs. jméno, které rejstřík vede k jeho datu.
  vs_rg as (
    select dd.ico, dd.source_sha256, dd.zdroj,
           bool_or(rg.jmeno = dd.jmeno and rg.od <= dd.dt and (rg.do_ is null or dd.dt < rg.do_)) as sedi
    from dd join rg on rg.ico = dd.ico
    group by dd.ico, dd.source_sha256, dd.zdroj
  ),
  a_rg as (
    select ico, bool_or(not sedi) as rozpor, bool_or(sedi) as shoda,
           array_agg(distinct zdroj) filter (where sedi) as zdroje
    from vs_rg group by ico
  ),
  ted_rg as (
    select distinct on (ico) ico, jmeno from rg where do_ is null order by ico, od desc, jmeno
  ),
  -- Bez rejstříku: období jména v každé třídě dokladů.
  iv as (select ico, zdroj, jmeno, min(dt) as od, max(dt) as do_ from dd group by 1, 2, 3),
  rozpor_dk as (
    select distinct a.ico from iv a join iv b
      on a.ico = b.ico and a.jmeno <> b.jmeno and a.od <= b.do_ and b.od <= a.do_
  ),
  -- Shoda bez rejstříku: totéž jméno ve dvou třídách dokladů a v celém rozpětí, kdy ho
  -- zdroje uvádějí, žádné jiné jméno (přejmenování mezi nimi = shoda neplatí).
  n_rozpeti as (
    select ico, jmeno, min(od) as od, max(do_) as do_, count(distinct zdroj) as zdroju
    from iv where zdroj is not null group by ico, jmeno
  ),
  shoda_dk as (
    select u.ico, u.jmeno from n_rozpeti u
    where u.zdroju >= 2
      and not exists (select 1 from iv o where o.ico = u.ico and o.jmeno <> u.jmeno
                        and o.od <= u.do_ and u.od <= o.do_)
  ),
  ted_dd as (select distinct on (ico) ico, jmeno from dd order by ico, dt desc, jmeno),
  zdroje_dk as (select ico, jmeno, array_agg(distinct zdroj) as zdroje from iv group by ico, jmeno),
  s_dokladem as (select distinct ico from dk),
  s_datem as (select distinct ico from dd),
  s_rejstrikem as (select distinct ico from rg),
  -- Jména, která IČO v čase neslo (doklady i rejstřík).
  jmena_ico as (select ico, jmeno from dd union select ico, jmeno from rg),
  -- Jména FIRMY dvojčete: návrhy a potvrzení company_name (název dvojčete bývá adresa,
  -- PSČ nebo číslo účtu — naměřeno 2026-09-28 — takže sám o sobě jménem není).
  tj as (
    select x.twin_id, public.nazev_firmy_klic(x.source_key) as jmeno
    from public.twin_external_refs x
    where x.ref_kind = 'company_name' and x.state in ('proposed', 'confirmed')
      and x.twin_id in (select twin_id from n)
  ),
  -- Smíšené dvojče: nese i jméno, které IČO nikdy nemělo (jiná firma v témže dvojčeti).
  smisene as (
    select distinct n.id from n
    join tj on tj.twin_id = n.twin_id and tj.jmeno is not null
    where n.ico is not null
      and not exists (select 1 from jmena_ico ji where ji.ico = n.ico and ji.jmeno = tj.jmeno)
  ),
  souhrn as (
    select i.ico,
           sd.ico is not null as ma_doklad,
           st.ico is not null as ma_datum,
           sr.ico is not null as ma_rejstrik,
           coalesce(ar.rozpor, false) as rozpor_rg,
           coalesce(ar.shoda, false) as shoda_rg,
           ar.zdroje as zdroje_rg,
           rd.ico is not null as rozpor_dk,
           coalesce(tr.jmeno, td.jmeno) as jmeno_ted
    from ica i
    left join a_rg ar on ar.ico = i.ico
    left join rozpor_dk rd on rd.ico = i.ico
    left join ted_rg tr on tr.ico = i.ico
    left join ted_dd td on td.ico = i.ico
    left join s_dokladem sd on sd.ico = i.ico
    left join s_datem st on st.ico = i.ico
    left join s_rejstrikem sr on sr.ico = i.ico
  ),
  k as (
    select n.id, n.ref_kind, n.twin_id, s.jmeno_ted,
      case
        when n.ico is null then 'nepodporovano'
        when not s.ma_doklad and not s.ma_rejstrik then 'bez_dokladu'
        when s.ma_rejstrik and s.rozpor_rg then 'rozpor'
        when s.ma_rejstrik and not s.shoda_rg then 'jeden_zdroj'
        when not s.ma_rejstrik and not s.ma_datum then 'bez_data'
        when not s.ma_rejstrik and s.rozpor_dk then 'rozpor'
        when s.jmeno_ted is null
          or not (s.jmeno_ted = public.nazev_firmy_klic(n.label)
                  or exists (select 1 from tj where tj.twin_id = n.twin_id and tj.jmeno = s.jmeno_ted))
          then 'jmeno_nesedi_na_twin'
        when sm.id is not null then 'smisene_dvojce'
        when s.ma_rejstrik then 'shoda_dva_zdroje'
        when sk.ico is not null then 'shoda_dva_zdroje'
        else 'jeden_zdroj'
      end as trida,
      case when s.ma_rejstrik then coalesce(s.zdroje_rg, '{}') || array['rejstrik']
           else zd.zdroje end as zdroje
    from n
    left join souhrn s on s.ico = n.ico
    left join shoda_dk sk on sk.ico = n.ico and sk.jmeno = s.jmeno_ted
    left join zdroje_dk zd on zd.ico = n.ico and zd.jmeno = s.jmeno_ted
    left join smisene sm on sm.id = n.id
  )
  select k.id, k.ref_kind, k.twin_id, k.trida,
         'twin_identity:' || k.ref_kind || ':' || k.trida, k.zdroje, k.jmeno_ted
  from k;
$$;

COMMENT ON FUNCTION public.twin_ref_tridy(jsonb, uuid[]) IS
  'Třída shody navržených identit (dva nezávislé zdroje pravdy v čase: třídy dokladů + výpis z rejstříku). Jediný vlastník pravidla pro blok skupin i dávku.';

REVOKE ALL ON FUNCTION public.twin_ref_tridy(jsonb, uuid[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.twin_ref_tridy(jsonb, uuid[]) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_twin_ref_group_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_twin_ref_group_block
-- Popis: 'review_queue' blok SKUPIN návrhů identit — jedna položka = jedna třída
--        shody (twin_ref_tridy), kterou konfigurace bloku povoluje schválit
--        hromadně. Potvrzení položky schválí celou skupinu: dispečer
--        submit_evidence_review_audited (entity_kind 'twin_identity_group') →
--        twin_ref_group_decide, který třídu v okamžiku provedení spočítá ZNOVU.
--        Týž vzor jako skupiny návrhů vazeb (položka fronty = skupina) — žádná
--        nová pole v masce, žádný nový ovladač v klientech.
--
-- ⛔ Majitel 2026-09-28: „teprve dva zdroje pravdy se shodou sto procent
-- opravňují k návrhu na hromadné sloučení". Které třídy smějí do dávky, říkají
-- DATA bloku (`batch_classes`), ne kód; třída, která tam není, se nenabídne.
--
-- Konfigurace (p_params) — táž jako twin_ref_tridy, navíc:
--   batch_classes   POVINNÉ  pole tříd, které smějí do dávky (např. ["shoda_dva_zdroje"])
--   title_template  POVINNÉ  placeholdery {trida} {pocet} {zdroje}
--   quote_template  POVINNÉ  tytéž placeholdery
--   class_titles    volitelné {trida: text} — text za {trida} (jinak kód třídy)
--
-- Id položky = md5('twin_ref_group:' || source || ':' || entity_type || ':' ||
-- group_key)::uuid — deterministické, takže dávka najde konfiguraci v bloku
-- (surface_blocks) a nic se neukládá navíc.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_twin_ref_group_block(p_params jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
-- SECURITY INVOKER jako sesterský get_twin_ref_review_block (bezpečnostní oprava
-- 2026-07-31): RLS nad návrhy a doklady se uplatní a guard níž je nárok, ne přihlášení.
SECURITY INVOKER
SET search_path TO 'public', 'pg_temp'
AS $$
  with akce as (
    select jsonb_build_array(
      jsonb_build_object('action_key', 'app.twins.action.confirm', 'decision', 'confirmed', 'intent', 'approve')
    ) as a
  ),
  cfg as (
    select p_params->>'source' as src,
           coalesce(p_params->>'entity_type', '') as etype,
           p_params->'batch_classes' as bc,
           p_params->>'title_template' as t_tpl,
           p_params->>'quote_template' as q_tpl,
           coalesce(p_params->'class_titles', '{}') as ct
  ),
  -- Třídy se spočítají JEDNOU (jeden průchod pravidlem nese celý korpus).
  t as (select x.group_key, x.trida, x.zdroje from public.twin_ref_tridy(p_params) x),
  skupiny as (
    select t.group_key, t.trida, count(*) as pocet,
           (select string_agg(distinct z, ' + ' order by z)
              from t t2 cross join lateral unnest(t2.zdroje) z
             where t2.group_key = t.group_key) as zdroje
    from t
    where t.trida in (select jsonb_array_elements_text((select bc from cfg)))
    group by t.group_key, t.trida
  ),
  -- ČERSTVOST Z DAT: nejnovější změna návrhů, ze kterých fronta vzniká (ne hodiny
  -- serveru); prázdná fronta → trace_id přizná :no_data.
  cerstvost as (
    select max(r.updated_at) as vznik
    from public.twin_external_refs r
    where r.source = (select src from cfg) and r.state = 'proposed'
  ),
  polozky as (
    select md5('twin_ref_group:' || (select src from cfg) || ':' || (select etype from cfg)
               || ':' || s.group_key)::uuid as id,
           s.pocet,
           replace(replace(replace((select t_tpl from cfg),
             '{trida}', coalesce((select ct from cfg)->>s.trida, s.trida)),
             '{pocet}', s.pocet::text),
             '{zdroje}', coalesce(s.zdroje, '')) as title,
           replace(replace(replace((select q_tpl from cfg),
             '{trida}', coalesce((select ct from cfg)->>s.trida, s.trida)),
             '{pocet}', s.pocet::text),
             '{zdroje}', coalesce(s.zdroje, '')) as quote
    from skupiny s
  )
  select case
    when not (public.is_admin_or_staff() or public.is_service_role()) then
      jsonb_build_object('data', jsonb_build_object('entity_kind', 'twin_identity_group',
          'items', '[]'::jsonb, 'actions', (select a from akce)),
        'provenance', jsonb_build_object('source_slug', 'twin-identity',
          'trace_id', 'twin-ref-group:unauthenticated', 'freshness_at', now()))
    when (select src from cfg) is null or (select t_tpl from cfg) is null
      or (select q_tpl from cfg) is null or jsonb_typeof((select bc from cfg)) is distinct from 'array'
      or p_params->'date_fields' is null then
      jsonb_build_object('data', jsonb_build_object('entity_kind', 'twin_identity_group',
          'items', '[]'::jsonb, 'actions', (select a from akce)),
        'provenance', jsonb_build_object('source_slug', 'twin-identity',
          'trace_id', 'twin-ref-group:missing_config', 'freshness_at', now()))
    else jsonb_build_object(
      'data', jsonb_build_object('entity_kind', 'twin_identity_group', 'items', coalesce(
        (select jsonb_agg(jsonb_build_object('id', id, 'title', title, 'quote', quote)
                          order by pocet desc, id) from polozky), '[]'::jsonb),
        'actions', (select a from akce)),
      'provenance', jsonb_build_object('source_slug', 'twin-identity',
        'trace_id', 'twin-ref-group:' || (select src from cfg)
          || case when (select vznik from cerstvost) is null then ':no_data' else '' end,
        'freshness_at', coalesce((select vznik from cerstvost), now())))
  end;
$$;

REVOKE ALL ON FUNCTION public.get_twin_ref_group_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_twin_ref_group_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_twin_ref_group_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_ref_group_decide.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_ref_group_decide
-- Popis: HROMADNÉ schválení skupiny návrhů identit z bloku get_twin_ref_group_block
--        (entity_kind 'twin_identity_group' v submit_evidence_review_audited).
--
-- ⛔ Majitel 2026-09-28: „teprve dva zdroje pravdy se shodou sto procent opravňují
-- k návrhu na hromadné sloučení" + „vše vratné, s původem u dat". Proto:
--   1. Skupina se najde v DATECH: aktivní blok get_twin_ref_group_block, jehož
--      konfigurace dává totéž id skupiny (md5 zdroje, druhu entity a group_key)
--      a jehož `batch_classes` třídu povolují. Jinak chyba — žádné hádání.
--   2. Třída se spočítá ZNOVU teď (twin_ref_tridy). Do dávky jde jen to, co do
--      skupiny patří v okamžiku provedení; co mezitím přestalo platit, nepadne.
--   3. Každá položka jde TOUŽ lidskou ratifikací jako jednotlivé schválení
--      (twin_identity_confirm_binding: správa, reálné auth.uid(), audit položky)
--      ve vlastním savepointu — chyba položky dávku nezastaví, zapíše se.
--   4. Deník twin_ref_davky nese, co dávka udělala; vrácení twin_ref_davka_vratit.
--   5. Předání klíče jinému dvojčeti (p_supersede) dávka NEDĚLÁ — zůstává vědomým
--      úkonem u jednotlivé položky; v dávce skončí jako chyba položky.
-- Rozhodnutí je jen 'confirmed' — hromadné zamítnutí se nenabízí.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_ref_group_decide(
  p_group_id uuid,
  p_decision text,
  p_note     text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_uid       uuid := auth.uid();
  v_params    jsonb;
  v_group_key text;
  v_batch     uuid := gen_random_uuid();
  v_poradi    integer := 0;
  v_ok        integer := 0;
  v_uz        integer := 0;
  v_chyb      integer := 0;
  v_res       jsonb;
  v_err       text;
  v_pred      timestamptz;
  r           record;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff required (human ratification)' USING ERRCODE = '42501';
  END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Ratification requires an authenticated reviewer (auth.uid() is null)' USING ERRCODE = '42501';
  END IF;
  IF p_decision NOT IN ('confirmed', 'approved', 'HUMAN_CONFIRMED') THEN
    RAISE EXCEPTION 'decision % not supported for twin_identity_group (confirmed only)', p_decision
      USING ERRCODE = '22023';
  END IF;

  -- 1. Skupina z dat bloku.
  SELECT b.source_params, g.group_key
    INTO v_params, v_group_key
    FROM public.surface_blocks b
    CROSS JOIN LATERAL jsonb_array_elements_text(b.source_params->'batch_classes') bc(trida)
    CROSS JOIN LATERAL (
      SELECT DISTINCT 'twin_identity:' || x.ref_kind || ':' || bc.trida AS group_key
        FROM public.twin_external_refs x
       WHERE x.source = b.source_params->>'source' AND x.state = 'proposed'
    ) g
   WHERE b.source_rpc = 'get_twin_ref_group_block'
     AND b.is_active
     AND jsonb_typeof(b.source_params->'batch_classes') = 'array'
     AND md5('twin_ref_group:' || (b.source_params->>'source') || ':'
             || coalesce(b.source_params->>'entity_type', '') || ':' || g.group_key)::uuid = p_group_id
   LIMIT 1;
  IF v_group_key IS NULL THEN
    RAISE EXCEPTION 'group % not found in any active group block (configuration changed?)', p_group_id
      USING ERRCODE = 'P0002';
  END IF;

  -- 2.–4. Členové skupiny TEĎ, deterministicky po položkách.
  FOR r IN
    SELECT t.ref_id FROM public.twin_ref_tridy(v_params) t
     WHERE t.group_key = v_group_key
     ORDER BY t.ref_id
  LOOP
    v_poradi := v_poradi + 1;
    SELECT x.valid_from INTO v_pred FROM public.twin_external_refs x WHERE x.id = r.ref_id;
    BEGIN
      v_res := public.twin_identity_confirm_binding(r.ref_id);
      IF coalesce((v_res->>'already')::boolean, false) THEN
        v_uz := v_uz + 1;
        INSERT INTO public.twin_ref_davky (batch_id, poradi, ref_id, group_key, vysledek, stav_pred,
                                           platnost_pred, provedl)
        VALUES (v_batch, v_poradi, r.ref_id, v_group_key, 'uz_potvrzeno', 'proposed', v_pred, v_uid);
      ELSE
        v_ok := v_ok + 1;
        INSERT INTO public.twin_ref_davky (batch_id, poradi, ref_id, group_key, vysledek, stav_pred,
                                           platnost_pred, potvrzeno_at, provedl)
        SELECT v_batch, v_poradi, r.ref_id, v_group_key, 'potvrzeno', 'proposed', v_pred, x.confirmed_at, v_uid
          FROM public.twin_external_refs x WHERE x.id = r.ref_id;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_err = MESSAGE_TEXT;
      v_chyb := v_chyb + 1;
      INSERT INTO public.twin_ref_davky (batch_id, poradi, ref_id, group_key, vysledek, chyba, stav_pred,
                                         platnost_pred, provedl)
      VALUES (v_batch, v_poradi, r.ref_id, v_group_key, 'chyba', left(v_err, 500), 'proposed', v_pred, v_uid);
    END;
  END LOOP;

  -- Audit dávky (bez klíčů zdroje — IČO/jméno mohou být osobní údaj).
  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (v_uid, 'twin_external_refs.batch_confirmed', 'twin_external_refs.batch_confirmed', 'content', 'info',
          array['surface', 'write', 'twin_identity', 'batch'],
          jsonb_build_object('batch_id', v_batch, 'group_id', p_group_id, 'group_key', v_group_key,
                             'potvrzeno', v_ok, 'uz_potvrzeno', v_uz, 'chyba', v_chyb,
                             'celkem', v_poradi, 'note', p_note));

  RETURN jsonb_build_object('batch_id', v_batch, 'group_key', v_group_key, 'celkem', v_poradi,
                            'potvrzeno', v_ok, 'uz_potvrzeno', v_uz, 'chyba', v_chyb);
END;
$$;

REVOKE ALL ON FUNCTION public.twin_ref_group_decide(uuid, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.twin_ref_group_decide(uuid, text, text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_relation_propose.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_relation_propose
-- Popis: Navrhovatel (zdroj, ingest, importér instančních dat) předá SKUPINU
--        návrhů hran mezi dvojčaty s důkazem. Nic se tu neotevírá — návrh
--        čeká na člověka (twin_relation_proposal_decide).
-- Bezpečnost: SECURITY DEFINER + service_role/admin/staff + REVOKE/GRANT.
--
-- Vstup:
--   p_group     {group_key, source, rule_key, title?, evidence?}
--   p_proposals [{proposal_key, source_twin_id, target_twin_id, relation_kind,
--                 valid_from?, confidence?, evidence?}]
--
-- Pravidla (každé z nich je měřené v src/tests/db/navrhy-vazeb.test.ts):
--   · IDEMPOTENCE: týž group_key / proposal_key trefí týž řádek. Instanční
--     data se přehrávají při KAŽDÉM nasazení, takže neidempotentní návrh by
--     frontu zdvojoval s každým deployem.
--   · ROZHODNUTÍ JE LEPKAVÉ: schválený ani zamítnutý návrh se neaktualizuje
--     a neoživuje. Lidské „ne" se nevrací (týž princip jako
--     twin_propose_identity_by_signals); počítá se do `decided_kept`.
--   · FAKT NEČEKÁ NA SCHVÁLENÍ: když hrana už platí, návrh se uloží jako
--     'superseded' s odkazem na ni — do fronty nepatří, není o čem rozhodovat.
--   · SKUPINA PATŘÍ SVÉMU ZDROJI: cizí zdroj skupinu nepřepíše a návrh nepřejde
--     do jiné skupiny — jinak by jeden navrhovatel mohl přepsat důkaz druhého.
--   · Vadný vstup PADÁ (22023), nic se tiše nepřeskakuje: tichý přeskok by
--     vypadal jako „nic k navržení".
--
-- Proč hook instančních dat smí volat: přehrává SQL jako `service_role`
-- (scripts/deploy/instance-data-hook.sh, PGOPTIONS role) — is_service_role()
-- tu cestu zná, takže importér nemusí opisovat pravidla do vlastního INSERTu.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_relation_propose(
  p_group     jsonb,
  p_proposals jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_key       text := nullif(btrim(p_group->>'group_key'), '');
  v_source    text := nullif(btrim(p_group->>'source'), '');
  v_rule      text := nullif(btrim(p_group->>'rule_key'), '');
  v_title     text := nullif(btrim(p_group->>'title'), '');
  v_gevidence jsonb := COALESCE(p_group->'evidence', '{}'::jsonb);
  v_group_id  uuid;
  v_owner     text;
  p           jsonb;
  v_pkey      text;
  v_src       uuid;
  v_tgt       uuid;
  v_kind      text;
  v_from      timestamptz;
  v_conf      numeric;
  v_ev        jsonb;
  v_old       public.twin_relation_proposals%ROWTYPE;
  v_rel       uuid;
  n_new       int := 0;
  n_upd       int := 0;
  n_same      int := 0;
  n_kept      int := 0;
  n_fact      int := 0;
BEGIN
  IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'twin_relation_propose: service_role or admin/staff only'
      USING ERRCODE = '42501';
  END IF;
  IF v_key IS NULL OR v_source IS NULL OR v_rule IS NULL THEN
    RAISE EXCEPTION 'twin_relation_propose: group needs group_key, source and rule_key'
      USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_proposals) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'twin_relation_propose: proposals must be a JSON array'
      USING ERRCODE = '22023';
  END IF;

  -- ── Skupina ────────────────────────────────────────────────────────────────
  -- ON CONFLICT místo „select, pak insert": dva souběžní navrhovatelé téhož
  -- klíče se jinak oba rozhodnou vložit a druhý spadne na unikátnosti.
  INSERT INTO public.twin_relation_proposal_groups (group_key, source, rule_key, title, evidence)
  VALUES (v_key, v_source, v_rule, v_title, v_gevidence)
  ON CONFLICT (group_key) DO NOTHING
  RETURNING id INTO v_group_id;

  IF v_group_id IS NULL THEN
    SELECT g.id, g.source INTO v_group_id, v_owner
      FROM public.twin_relation_proposal_groups g
     WHERE g.group_key = v_key
       FOR UPDATE;
    IF v_owner IS DISTINCT FROM v_source THEN
      RAISE EXCEPTION 'twin_relation_propose: skupina % patří zdroji %, ne %',
        v_key, v_owner, v_source
        USING ERRCODE = '42501';
    END IF;
    UPDATE public.twin_relation_proposal_groups g
       SET rule_key = v_rule,
           title    = COALESCE(v_title, g.title),
           evidence = v_gevidence
     WHERE g.id = v_group_id
       AND (g.rule_key, g.title, g.evidence)
           IS DISTINCT FROM (v_rule, COALESCE(v_title, g.title), v_gevidence);
  END IF;

  -- ── Návrhy ────────────────────────────────────────────────────────────────
  FOR p IN SELECT value FROM jsonb_array_elements(p_proposals) LOOP
    v_pkey := nullif(btrim(p->>'proposal_key'), '');
    v_src  := nullif(p->>'source_twin_id', '')::uuid;
    v_tgt  := nullif(p->>'target_twin_id', '')::uuid;
    v_kind := nullif(btrim(p->>'relation_kind'), '');
    v_from := nullif(p->>'valid_from', '')::timestamptz;
    v_conf := nullif(p->>'confidence', '')::numeric;
    v_ev   := COALESCE(p->'evidence', '{}'::jsonb);

    IF v_pkey IS NULL OR v_src IS NULL OR v_tgt IS NULL OR v_kind IS NULL THEN
      RAISE EXCEPTION 'twin_relation_propose: návrh potřebuje proposal_key, source_twin_id, target_twin_id a relation_kind (%)',
        left(p::text, 200)
        USING ERRCODE = '22023';
    END IF;

    -- Hrana už platí → není o čem rozhodovat.
    SELECT r.id INTO v_rel
      FROM public.twin_relations r
     WHERE r.source_twin_id = v_src
       AND r.target_twin_id = v_tgt
       AND r.relation_kind  = v_kind
       AND r.valid_to IS NULL
     LIMIT 1;

    SELECT * INTO v_old
      FROM public.twin_relation_proposals x
     WHERE x.proposal_key = v_pkey
       FOR UPDATE;

    IF NOT FOUND THEN
      INSERT INTO public.twin_relation_proposals
        (group_id, proposal_key, source_twin_id, target_twin_id, relation_kind,
         valid_from, confidence, evidence, state, relation_id)
      VALUES
        (v_group_id, v_pkey, v_src, v_tgt, v_kind, v_from, v_conf, v_ev,
         CASE WHEN v_rel IS NULL THEN 'proposed' ELSE 'superseded' END, v_rel);
      IF v_rel IS NULL THEN n_new := n_new + 1; ELSE n_fact := n_fact + 1; END IF;
      CONTINUE;
    END IF;

    IF v_old.group_id <> v_group_id THEN
      RAISE EXCEPTION 'twin_relation_propose: návrh % patří jiné skupině', v_pkey
        USING ERRCODE = '22023';
    END IF;

    IF v_old.state <> 'proposed' THEN
      n_kept := n_kept + 1;                 -- lepkavé rozhodnutí: nesahat
    ELSIF v_rel IS NOT NULL THEN
      UPDATE public.twin_relation_proposals
         SET state = 'superseded', relation_id = v_rel
       WHERE id = v_old.id;
      n_fact := n_fact + 1;
    ELSIF (v_old.source_twin_id, v_old.target_twin_id, v_old.relation_kind,
           v_old.valid_from, v_old.confidence, v_old.evidence)
          IS NOT DISTINCT FROM (v_src, v_tgt, v_kind, v_from, v_conf, v_ev) THEN
      n_same := n_same + 1;
    ELSE
      UPDATE public.twin_relation_proposals
         SET source_twin_id = v_src, target_twin_id = v_tgt, relation_kind = v_kind,
             valid_from = v_from, confidence = v_conf, evidence = v_ev
       WHERE id = v_old.id;
      n_upd := n_upd + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'group_id',     v_group_id,
    'inserted',     n_new,
    'updated',      n_upd,
    'unchanged',    n_same,
    'decided_kept', n_kept,
    'already_fact', n_fact
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.twin_relation_propose(jsonb, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.twin_relation_propose(jsonb, jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_upsert_entity_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_upsert_entity_audited
-- Popis: Idempotentní vstupní sloveso adaptérů: „tahle entita existuje
--        ve zdroji pod tímhle klíčem". Resolvne potvrzenou primární identitu
--        (source, source_key, ref_kind='primary_id'); existuje-li, jen
--        aktualizuje label/status/metadata dvojčete. Jinak založí dvojče
--        + POTVRZENOU primární ref (confirmed_by NULL = systémové potvrzení:
--        identita ve VLASTNÍM zdroji nepotřebuje lidskou ratifikaci — ta je
--        pro cross-source vazby přes twin_identity_*_binding).
--        Entity se nikdy nemažou — deaktivace přes p_status='inactive'.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT
-- Audit: twin_entities.upsert (bez source_key — klíč může být osobní údaj)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_upsert_entity_audited(
  p_entity_type text,
  p_source text,
  p_source_key text,
  p_label text DEFAULT NULL,
  p_status text DEFAULT NULL,
  p_metadata jsonb DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  -- Canonical boolean-NOT-NULL service check (is_service_role.sql, #588):
  -- COALESCEs to false, so the deny-guard below fails CLOSED.
  v_is_service boolean := public.is_service_role();
  v_twin uuid;
  v_created boolean := false;
BEGIN
  -- Authorization check (FIRST, before any data access)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  -- Input validation
  IF p_entity_type IS NULL OR btrim(p_entity_type) = '' THEN
    RAISE EXCEPTION 'p_entity_type must not be blank';
  END IF;
  IF p_source IS NULL OR btrim(p_source) = '' THEN
    RAISE EXCEPTION 'p_source must not be blank';
  END IF;
  IF p_source_key IS NULL OR btrim(p_source_key) = '' THEN
    RAISE EXCEPTION 'p_source_key must not be blank';
  END IF;
  -- ⛔ JEDNA SKUTEČNOST, JEDNA IDENTITA (2026-09-19). Zdroj pohlcený jiným
  -- (registr: neaktivní + superseded_by) se zapisuje pod toho, kdo ho pohltil.
  -- Bez toho přehrání starého balíčku s historickým jménem (`aisha-local-ingest`)
  -- nenajde existující twin a založí duplikát — 30. 8. to bylo 839 firem.
  -- Viz canonical_ingest_source.
  p_source := public.canonical_ingest_source(p_source);
  IF p_status IS NOT NULL AND p_status NOT IN ('active', 'inactive', 'archived') THEN
    RAISE EXCEPTION 'p_status must be active/inactive/archived';
  END IF;

  -- Resolve přes potvrzenou, časově platnou primární identitu TÉHOŽ DRUHU.
  -- ⛔ 2026-09-27: bez druhu by osoba 5 našla VOZIDLO 5 téhož zdroje a níž by
  -- mu přepsala jméno a metadata (Eurowag: monitoredObjectId × driver id).
  SELECT r.twin_id INTO v_twin
  FROM public.twin_external_refs r
  WHERE r.source = p_source
    AND r.source_key = p_source_key
    AND r.ref_kind = 'primary_id'
    AND r.entity_type = p_entity_type
    AND r.state = 'confirmed'
    AND r.valid_to IS NULL
  LIMIT 1;

  IF v_twin IS NULL THEN
    INSERT INTO public.twin_entities (entity_type, label, status, metadata)
    VALUES (
      p_entity_type,
      p_label,
      COALESCE(p_status, 'active'),
      COALESCE(p_metadata, '{}'::jsonb)
    )
    RETURNING id INTO v_twin;

    -- Primární identita vlastního zdroje: potvrzeno systémem (confirmed_by NULL)
    INSERT INTO public.twin_external_refs (
      twin_id, source, source_key, ref_kind,
      state, proposed_by, confirmed_by, confirmed_at
    )
    VALUES (
      v_twin, p_source, p_source_key, 'primary_id',
      'confirmed', 'import', NULL, now()
    );

    v_created := true;
  ELSE
    UPDATE public.twin_entities SET
      -- ⛔ JMÉNO ZVOLENÉ ČLOVĚKEM SE NEPŘEPISUJE (2026-09-23). Po sjednocení osoby
      --    (hr_sjednot_osobu_admin) vede na jeden twin víc klíčů zdroje („KOŽUŠNÍK",
      --    „p. Kožušník") a každé doručení by jméno přepsalo zápisem, který přišel
      --    naposled. `label_hr` = jméno určil člověk, ingest ho jen doplňuje jinde.
      label      = CASE WHEN COALESCE(metadata, '{}'::jsonb) ? 'label_hr' THEN label
                        ELSE COALESCE(p_label, label) END,
      status     = COALESCE(p_status, status),
      -- ⛔ ZNAČKY ROZHODNUTÍ PŘEŽIJÍ NÁHRADU METADAT: bez nich by rozhodnutí
      --    nešlo vrátit (revert_twin_decision_admin je hledá) a zámek jména by
      --    zmizel s prvním balíkem. Ingest posílá metadata celá, ne rozdíl.
      metadata   = CASE WHEN p_metadata IS NULL THEN metadata
                        ELSE p_metadata || jsonb_strip_nulls(jsonb_build_object(
                               'label_hr', metadata -> 'label_hr',
                               'label_hr_rozhodnutim', metadata -> 'label_hr_rozhodnutim',
                               'archivovano_rozhodnutim', metadata -> 'archivovano_rozhodnutim',
                               'sjednoceno_do', metadata -> 'sjednoceno_do')) END,
      updated_at = now()
    WHERE id = v_twin;
  END IF;

  -- Audit log (bez source_key — klíč zdroje může být osobní údaj)
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'twin_entities.upsert',
    jsonb_build_object(
      'twin_id', v_twin,
      'entity_type', p_entity_type,
      'source', p_source,
      'created', v_created
    )
  );

  RETURN jsonb_build_object('twin_id', v_twin, 'created', v_created);
END;
$$;

REVOKE ALL ON FUNCTION public.twin_upsert_entity_audited(text, text, text, text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.twin_upsert_entity_audited(text, text, text, text, text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.twin_upsert_entity_audited(text, text, text, text, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_provision_federated_member.sql
-- -----------------------------------------------------------------------------

-- Function: audience_provision_federated_member

CREATE OR REPLACE FUNCTION public.audience_provision_federated_member(p_source_uuid uuid, p_email text, p_display_name text DEFAULT NULL::text, p_language text DEFAULT 'en'::text, p_tier text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID := p_source_uuid;
  v_twin jsonb;  -- reuse source uuid as aisha identity
BEGIN
  IF p_source_uuid IS NULL OR p_email IS NULL THEN
    RAISE EXCEPTION 'provision_federated_member: source_uuid and email required';
  END IF;

  -- 1. aisha_auth.users — the FK target for profiles + RLS auth.uid()
  INSERT INTO aisha_auth.users (id, email, raw_user_meta_data, created_at, updated_at)
  VALUES (
    v_uid, p_email,
    jsonb_build_object(
      'source', 'source-federation',
      'federated_from', 'source-api',
      'community_member', true,
      'source_tier', p_tier
    ),
    now(), now()
  )
  ON CONFLICT (id) DO UPDATE
    SET email = EXCLUDED.email,
        raw_user_meta_data = aisha_auth.users.raw_user_meta_data
          || jsonb_build_object('community_member', true, 'source_tier', p_tier),
        updated_at = now();

  -- 2. public.profiles — display identity for the audience module
  INSERT INTO public.profiles (id, user_id, email, display_name, preferred_language, created_at, updated_at)
  VALUES (gen_random_uuid(), v_uid, p_email, p_display_name, COALESCE(p_language, 'en'), now(), now())
  ON CONFLICT (user_id) DO UPDATE
    SET email = EXCLUDED.email,
        display_name = COALESCE(EXCLUDED.display_name, public.profiles.display_name),
        preferred_language = EXCLUDED.preferred_language,
        updated_at = now();

  -- 2b. Dvojče + reference účtu (ADR-003 K1): identita je entita, účet je
  --     jedna potvrzená reference. Primární identita zdroje je potvrzená
  --     systémem — binding zdroje je schválený jako celek (approve_source),
  --     per-člen review by byl jen šum. Vedlejší účinek nesmí zničit akt (Z7).
  BEGIN
    v_twin := public.twin_upsert_entity_audited('person', 'source-federation', p_source_uuid::text,
                                                p_display_name, NULL, NULL);
    PERFORM public.twin_ensure_for_account(v_uid, p_display_name, 'person', (v_twin->>'twin_id')::uuid);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'twin not ensured for federated member %: %', v_uid, SQLERRM;
  END;

  -- 3. Audit the federation event
  PERFORM public.audience_log_event(
    'provision', 'federated_member', 'actor', v_uid,
    'Source-federated member provisioned',
    jsonb_build_object('email', p_email, 'tier', p_tier, 'source', 'source-api')
  );

  RETURN v_uid;
END;
$function$

;

REVOKE ALL ON FUNCTION audience_provision_federated_member(uuid,text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_provision_federated_member(uuid,text,text,text,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/twin_upsert_parameter_definitions_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: twin_upsert_parameter_definitions_audited
-- Popis: Seed most katalogu parametrů: JSON v gitu (instance data, formát
--        riq_parameter_definitions.v1 — camelCase entityType/dataType) →
--        twin_parameter_definitions (runtime). Přijímá v1 položky přímo
--        (camelCase i snake_case), upsert podle code — nové parametry se
--        přidávají DATY, žádná změna schématu.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT
-- Audit: twin_parameter_definitions.seed_completed s počty (bez PII)
-- ⛔ VLASTNICTVÍ KÓDU (2026-09-29): `code` je GLOBÁLNÍ klíč katalogu. Dřív
--    `ON CONFLICT (code) DO UPDATE` přepsal i `source`, typ a druh definice, kterou
--    deklaroval JINÝ zdroj — volající s právem na funkci (služba, plugin přes broker)
--    tak pod vlastním jménem převzal slovník cizího zdroje. Existující definici smí
--    aktualizovat jen týž zdroj; jinak 42501 s kódem a vlastníkem. Stráž je dvojí:
--    kontrola předem (čitelná chyba) a podmínka v DO UPDATE (atomicky i při souběhu).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.twin_upsert_parameter_definitions_audited(
  p_definitions jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean := public.is_service_role();
  v_batch jsonb;
  v_total integer;
  v_updated integer;
  v_inserted integer;
  v_cizi_kod text;
  v_cizi_zdroj text;
BEGIN
  -- Authorization check (FIRST, before any data access)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  -- Input validation (camelCase = v1 formát, snake_case = tolerovaný alias)
  IF p_definitions IS NULL OR jsonb_typeof(p_definitions) <> 'array' THEN
    RAISE EXCEPTION 'p_definitions must be a jsonb array';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_definitions) AS item
    WHERE COALESCE(item->>'code', '') = ''
       OR COALESCE(item->>'name', '') = ''
       OR COALESCE(item->>'entityType', item->>'entity_type', '') = ''
       OR COALESCE(item->>'dataType', item->>'data_type', '') = ''
  ) THEN
    RAISE EXCEPTION 'each definition requires code, name, entityType, dataType';
  END IF;

  -- Dedup podle code — ON CONFLICT nesmí zasáhnout stejný řádek dvakrát
  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON (item->>'code') item
    FROM jsonb_array_elements(p_definitions) AS item
  ) AS deduped;

  v_total := jsonb_array_length(v_batch);

  -- Vlastnictví: existující kód jiného zdroje se nepřevezme (viz hlavička).
  SELECT d.code, d.source INTO v_cizi_kod, v_cizi_zdroj
    FROM public.twin_parameter_definitions d
    JOIN jsonb_array_elements(v_batch) AS item ON item->>'code' = d.code
   WHERE d.source IS DISTINCT FROM item->>'source'
   ORDER BY d.code
   LIMIT 1
   FOR UPDATE OF d;
  IF FOUND THEN
    RAISE EXCEPTION 'parameter definition % belongs to source %', v_cizi_kod, COALESCE(v_cizi_zdroj, '(none)')
      USING ERRCODE = '42501';
  END IF;

  SELECT count(*) INTO v_updated
  FROM public.twin_parameter_definitions d
  WHERE d.code IN (
    SELECT item->>'code' FROM jsonb_array_elements(v_batch) AS item
  );

  INSERT INTO public.twin_parameter_definitions (
    code, name, entity_type, data_type, unit, source, aggregation,
    historization, description, metadata, updated_at
  )
  SELECT
    item->>'code',
    item->>'name',
    COALESCE(item->>'entityType', item->>'entity_type'),
    COALESCE(item->>'dataType', item->>'data_type'),
    item->>'unit',
    item->>'source',
    item->>'aggregation',
    item->>'historization',
    item->>'description',
    COALESCE(item->'metadata', '{}'::jsonb),
    now()
  FROM jsonb_array_elements(v_batch) AS item
  ON CONFLICT (code) DO UPDATE SET
    name          = EXCLUDED.name,
    entity_type   = EXCLUDED.entity_type,
    data_type     = EXCLUDED.data_type,
    unit          = EXCLUDED.unit,
    source        = EXCLUDED.source,
    aggregation   = EXCLUDED.aggregation,
    historization = EXCLUDED.historization,
    description   = EXCLUDED.description,
    metadata      = EXCLUDED.metadata,
    updated_at    = now()
  WHERE public.twin_parameter_definitions.source IS NOT DISTINCT FROM EXCLUDED.source;

  v_inserted := v_total - v_updated;

  -- Audit log
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'twin_parameter_definitions.seed_completed',
    jsonb_build_object(
      'total', v_total,
      'inserted', v_inserted,
      'updated', v_updated
    )
  );

  RETURN jsonb_build_object(
    'total', v_total,
    'inserted', v_inserted,
    'updated', v_updated
  );
END;
$$;

REVOKE ALL ON FUNCTION public.twin_upsert_parameter_definitions_audited(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.twin_upsert_parameter_definitions_audited(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.twin_upsert_parameter_definitions_audited(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/unsubscribe_from_expert_rule.sql
-- -----------------------------------------------------------------------------

-- Function: public.unsubscribe_from_expert_rule
-- Arguments: p_rule_id uuid
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.unsubscribe_from_expert_rule(p_rule_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id uuid;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  UPDATE expert_rule_subscriptions SET is_active = false
  WHERE user_id = v_caller_id AND rule_id = p_rule_id;

  IF FOUND THEN
    UPDATE expert_rules SET subscriber_count = GREATEST(subscriber_count - 1, 0)
    WHERE id = p_rule_id;
  END IF;

  RETURN true;
END;
$function$;

REVOKE ALL ON FUNCTION public.unsubscribe_from_expert_rule(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.unsubscribe_from_expert_rule(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.unsubscribe_from_expert_rule(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/update_agent_catalog_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.update_agent_catalog_admin
-- Arguments: p_id uuid, p_updates jsonb
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.update_agent_catalog_admin(p_id uuid, p_updates jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old record;
  v_old_snapshot jsonb;
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Permission denied' USING ERRCODE = 'P0003';
  END IF;

  -- Snapshot current state BEFORE update (audit trail)
  SELECT slug, default_model, model_overrides, safety_level,
         autonomy_level, allowed_tools, denied_tools, max_loops, is_active
  INTO v_old
  FROM agent_catalog WHERE id = p_id;

  IF v_old IS NULL THEN
    RAISE EXCEPTION 'Agent not found: %', p_id USING ERRCODE = 'P0002';
  END IF;

  v_old_snapshot := jsonb_build_object(
    'allowed_tools', to_jsonb(v_old.allowed_tools),
    'autonomy_level', v_old.autonomy_level,
    'default_model', v_old.default_model,
    'denied_tools', to_jsonb(v_old.denied_tools),
    'is_active', v_old.is_active,
    'max_loops', v_old.max_loops,
    'model_overrides', v_old.model_overrides,
    'safety_level', v_old.safety_level
  );

  UPDATE agent_catalog
  SET
    display_name = COALESCE(p_updates->>'display_name', display_name),
    purpose = COALESCE(p_updates->>'purpose', purpose),
    default_model = COALESCE(p_updates->>'default_model', default_model),
    default_context_profile = COALESCE(p_updates->>'default_context_profile', default_context_profile),
    safety_level = COALESCE((p_updates->>'safety_level')::text, safety_level),
    max_loops = COALESCE((p_updates->>'max_loops')::int, max_loops),
    is_active = COALESCE((p_updates->>'is_active')::boolean, is_active),
    model_overrides = COALESCE(
      CASE WHEN p_updates ? 'model_overrides' THEN p_updates->'model_overrides' ELSE NULL END,
      model_overrides
    ),
    allowed_tools = COALESCE(
      CASE WHEN p_updates ? 'allowed_tools'
        THEN ARRAY(SELECT jsonb_array_elements_text(p_updates->'allowed_tools'))
        ELSE NULL END,
      allowed_tools
    ),
    denied_tools = COALESCE(
      CASE WHEN p_updates ? 'denied_tools'
        THEN ARRAY(SELECT jsonb_array_elements_text(p_updates->'denied_tools'))
        ELSE NULL END,
      denied_tools
    ),
    autonomy_level = COALESCE((p_updates->>'autonomy_level')::text, autonomy_level),
    updated_at = now()
  WHERE id = p_id;

  -- Audit: log WHO changed WHAT, with before-state snapshot
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'AGENT_CATALOG_UPDATE',
    jsonb_build_object(
      'agent_id', p_id,
      'agent_slug', v_old.slug,
      'area', 'ai',
      'previous_state', v_old_snapshot,
      'requested_changes', p_updates,
      'severity', 'info'
    )
  );

  RETURN p_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.update_agent_catalog_admin(uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_agent_catalog_admin(uuid, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.update_agent_catalog_admin(uuid, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/update_agent_run_status.sql
-- -----------------------------------------------------------------------------

-- Function: public.update_agent_run_status
-- Description: Update status + metadata for an existing agent run.
--   Called exclusively by svc-agent-runner (service_role JWT) to report progress.
--   Sets started_at / finished_at automatically based on status transition.
-- Security: SECURITY DEFINER, grants to service_role only

-- p_outputs (jsonb) was appended after the original 7-arg form shipped, changing
-- the signature — DROP the old one first (CREATE OR REPLACE only replaces an
-- identical arg list; without this the 7-arg overload lingers and a 7-arg call
-- becomes ambiguous against the new default-8th form). Appended LAST so existing
-- positional 7-arg callers stay valid (the 8th defaults).
DROP FUNCTION IF EXISTS public.update_agent_run_status(uuid, text, integer, text, text, text, text);

CREATE OR REPLACE FUNCTION public.update_agent_run_status(
  p_run_id              uuid,
  p_status              text,
  p_exit_code           integer DEFAULT NULL,
  p_error_summary       text    DEFAULT NULL,
  p_outputs_s3_uri      text    DEFAULT NULL,
  p_host                text    DEFAULT NULL,
  p_langfuse_trace_id   text    DEFAULT NULL,
  p_outputs             jsonb   DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  UPDATE public.agent_runs SET
    status              = p_status,
    exit_code           = COALESCE(p_exit_code, exit_code),
    error_summary       = COALESCE(p_error_summary, error_summary),
    outputs_s3_uri      = COALESCE(p_outputs_s3_uri, outputs_s3_uri),
    outputs             = COALESCE(p_outputs, outputs),
    host                = COALESCE(p_host, host),
    langfuse_trace_id   = COALESCE(p_langfuse_trace_id, langfuse_trace_id),
    started_at          = CASE WHEN p_status = 'running'  THEN now() ELSE started_at  END,
    finished_at         = CASE WHEN p_status IN ('succeeded', 'failed', 'timeout', 'cancelled')
                               THEN now() ELSE finished_at END
  WHERE id = p_run_id;
END;
$$;

REVOKE ALL ON FUNCTION public.update_agent_run_status(uuid, text, integer, text, text, text, text, jsonb)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_agent_run_status(uuid, text, integer, text, text, text, text, jsonb)
  TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/update_ai_run_status.sql
-- -----------------------------------------------------------------------------

-- Function: update_ai_run_status
-- Updates the status of an ai_run with lifecycle transition validation.
-- Pipeline Executor calls this after each agent step.

CREATE OR REPLACE FUNCTION public.update_ai_run_status(
  p_metadata jsonb DEFAULT '{}'::jsonb,
  p_run_id uuid DEFAULT NULL,
  p_status text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_current_status text;
  v_valid_transitions jsonb := '{
    "running": ["completed", "failed", "blocked", "awaiting_approval"],
    "awaiting_approval": ["running", "completed", "failed", "blocked"],
    "blocked": ["running", "failed"]
  }'::jsonb;
  v_allowed text[];
BEGIN
  -- Validate inputs
  IF p_run_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'p_run_id is required');
  END IF;
  IF p_status IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'p_status is required');
  END IF;

  -- Get current status
  SELECT status INTO v_current_status
  FROM ai_runs
  WHERE id = p_run_id;

  IF v_current_status IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Run not found');
  END IF;

  -- Check if transition is valid
  SELECT ARRAY(
    SELECT jsonb_array_elements_text(v_valid_transitions -> v_current_status)
  ) INTO v_allowed;

  IF v_allowed IS NULL OR NOT (p_status = ANY(v_allowed)) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', format('Invalid transition: %s → %s', v_current_status, p_status),
      'allowed', to_jsonb(COALESCE(v_allowed, ARRAY[]::text[]))
    );
  END IF;

  -- Update the run
  UPDATE ai_runs
  SET
    status = p_status,
    finished_at = CASE
      WHEN p_status IN ('completed', 'failed') THEN now()
      ELSE finished_at
    END,
    metadata = metadata || p_metadata || jsonb_build_object(
      'last_status_change', jsonb_build_object(
        'from', v_current_status,
        'to', p_status,
        'at', now()::text
      )
    )
  WHERE id = p_run_id;

  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'AI_RUN_STATUS_UPDATE',
    jsonb_build_object(
      'area', 'ai_orchestration',
      'severity', 'info',
      'entity_type', 'ai_run',
      'entity_id', p_run_id::text,
      'from_status', v_current_status,
      'to_status', p_status
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'run_id', p_run_id,
    'previous_status', v_current_status,
    'new_status', p_status
  );
END;
$$;

-- Permissions
REVOKE ALL ON FUNCTION public.update_ai_run_status(jsonb, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_ai_run_status(jsonb, uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.update_ai_run_status(jsonb, uuid, text) TO service_role;

COMMENT ON FUNCTION public.update_ai_run_status(jsonb, uuid, text) IS
  'Updates ai_run status with lifecycle validation. '
  'Valid transitions: running→completed/failed/blocked/awaiting_approval, '
  'awaiting_approval→running/completed/failed/blocked, blocked→running/failed.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/update_ai_task_progress.sql
-- -----------------------------------------------------------------------------

-- Function: public.update_ai_task_progress
-- Arguments: p_task_id uuid, p_status text DEFAULT NULL, p_progress int DEFAULT NULL, p_current_step int DEFAULT NULL, p_result jsonb DEFAULT NULL, p_error_message text DEFAULT NULL
-- Security: SECURITY DEFINER
-- Source: Phase 4 — Agent Loop & Memory

CREATE OR REPLACE FUNCTION public.update_ai_task_progress(p_task_id uuid, p_status text DEFAULT NULL, p_progress int DEFAULT NULL, p_current_step int DEFAULT NULL, p_result jsonb DEFAULT NULL, p_error_message text DEFAULT NULL)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $$
DECLARE
  v_actor_id uuid := auth.uid();
BEGIN
  IF v_actor_id IS NOT NULL AND NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied: admin or staff required';
  END IF;

  UPDATE ai_tasks SET
    status        = COALESCE(p_status, status),
    progress      = COALESCE(p_progress, progress),
    current_step  = COALESCE(p_current_step, current_step),
    result        = COALESCE(p_result, result),
    error_message = COALESCE(p_error_message, error_message),
    started_at    = CASE WHEN p_status = 'running' AND started_at IS NULL THEN now() ELSE started_at END,
    completed_at  = CASE WHEN p_status IN ('done', 'failed', 'cancelled') THEN now() ELSE completed_at END,
    updated_at    = now()
  WHERE id = p_task_id;
END;
$$;

REVOKE ALL ON FUNCTION public.update_ai_task_progress(uuid, text, integer, integer, jsonb, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_ai_task_progress(uuid, text, integer, integer, jsonb, text) TO authenticated;


