-- Function: public.update_consultation_recording_egress
-- Tracks the LiveKit egress id on a consultation session when recording starts
-- (svc-livekit routes/recording.ts). The route has already verified session
-- membership + recording consent before calling this.
-- Security: SECURITY DEFINER (service_role-invoked via rpcService), search_path pinned.

CREATE OR REPLACE FUNCTION public.update_consultation_recording_egress(
  p_recording_egress_id text,
  p_session_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required' USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.consultation_sessions
     SET recording_egress_id = p_recording_egress_id
   WHERE id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Consultation session not found: %', p_session_id USING ERRCODE = 'no_data_found';
  END IF;
END;
$function$;

COMMENT ON FUNCTION public.update_consultation_recording_egress(text, uuid) IS
  'Sets consultation_sessions.recording_egress_id when a LiveKit recording egress starts.';

REVOKE ALL ON FUNCTION public.update_consultation_recording_egress(text, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.update_consultation_recording_egress(text, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/update_consultation_status.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- update_consultation_status
-- =============================================================================
-- Handles all status transitions (active/declined/ended/missed).
-- =============================================================================

CREATE OR REPLACE FUNCTION public.update_consultation_status(
  p_duration_seconds integer DEFAULT NULL,
  p_session_id uuid DEFAULT NULL,
  p_status text DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_voice_room_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_session_id IS NULL OR p_status IS NULL THEN
    RAISE EXCEPTION 'Missing required parameters';
  END IF;

  -- Verify caller or callee
  SELECT voice_room_id INTO v_voice_room_id
  FROM consultation_sessions
  WHERE id = p_session_id
    AND (caller_id = v_user_id OR callee_id = v_user_id);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session not found or not authorized';
  END IF;

  IF p_status = 'active' THEN
    UPDATE consultation_sessions
    SET status = 'active', started_at = now()
    WHERE id = p_session_id;

  ELSIF p_status = 'declined' THEN
    UPDATE consultation_sessions
    SET status = 'declined', ended_at = now()
    WHERE id = p_session_id;

  ELSIF p_status IN ('ended', 'missed') THEN
    UPDATE consultation_sessions
    SET status = p_status,
        ended_at = now(),
        duration_seconds = COALESCE(p_duration_seconds, 0)
    WHERE id = p_session_id;

    -- Deactivate voice room
    UPDATE voice_rooms
    SET is_active = false
    WHERE id = v_voice_room_id;
  END IF;
END;
$function$;

REVOKE ALL ON FUNCTION public.update_consultation_status(integer, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_consultation_status(integer, uuid, text) TO authenticated;


