-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/update_distribution_adjustment_timestamp.sql
-- -----------------------------------------------------------------------------

-- Function: public.update_distribution_adjustment_timestamp
-- Arguments: (none)
