-- File: aisha/db/sql/functions/update_expert_rule_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.update_expert_rule_audited
-- Arguments: p_rule_id uuid, p_title text DEFAULT NULL::text, p_summary text DEFAULT NULL::text, p_body_markdown text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_expertise_area_slug text DEFAULT NULL::text, p_visibility text DEFAULT NULL::text, p_ai_instructions text DEFAULT NULL::text, p_ai_context_tags text[] DEFAULT NULL::text[], p_change_note text DEFAULT NULL::text
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.update_expert_rule_audited(p_rule_id uuid, p_title text DEFAULT NULL::text, p_summary text DEFAULT NULL::text, p_body_markdown text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_expertise_area_slug text DEFAULT NULL::text, p_visibility text DEFAULT NULL::text, p_ai_instructions text DEFAULT NULL::text, p_ai_context_tags text[] DEFAULT NULL::text[], p_change_note text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id uuid;
  v_rule record;
  v_expertise_area_id uuid;
  v_new_version int;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Must be owner
  SELECT er.* INTO v_rule
  FROM expert_rules er
  JOIN partner_profiles pp ON pp.id = er.author_partner_id
  WHERE er.id = p_rule_id AND pp.user_id = v_caller_id;

  IF v_rule IS NULL THEN
    RAISE EXCEPTION 'Rule not found or not owned by caller';
  END IF;

  -- Resolve expertise area
  IF p_expertise_area_slug IS NOT NULL THEN
    SELECT id INTO v_expertise_area_id
    FROM guild_expertise_areas WHERE slug = p_expertise_area_slug AND is_active = true;
  ELSE
    v_expertise_area_id := v_rule.expertise_area_id;
  END IF;

  -- Create version snapshot if body changed
  IF p_body_markdown IS NOT NULL AND p_body_markdown IS DISTINCT FROM v_rule.body_markdown THEN
    v_new_version := v_rule.version + 1;

    INSERT INTO expert_rule_versions (rule_id, version_no, body_markdown, ai_instructions, change_note, created_by)
    VALUES (p_rule_id, v_new_version,
      COALESCE(p_body_markdown, v_rule.body_markdown),
      COALESCE(p_ai_instructions, v_rule.ai_instructions),
      COALESCE(p_change_note, 'Updated'),
      v_caller_id
    );
  ELSE
    v_new_version := v_rule.version;
  END IF;

  UPDATE expert_rules SET
    title = COALESCE(p_title, title),
    summary = COALESCE(p_summary, summary),
    body_markdown = COALESCE(p_body_markdown, body_markdown),
    category = COALESCE(p_category::expert_rule_category, category),
    expertise_area_id = v_expertise_area_id,
    visibility = COALESCE(p_visibility, visibility),
    ai_instructions = COALESCE(p_ai_instructions, ai_instructions),
    ai_context_tags = COALESCE(p_ai_context_tags, ai_context_tags),
    version = v_new_version
  WHERE id = p_rule_id;

  -- Audit
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (v_caller_id, 'EXPERT_RULE_UPDATE', jsonb_build_object(
    'area', 'knowledge',
    'severity', 'info',
    'rule_id', p_rule_id,
    'new_version', v_new_version
  ));

  RETURN true;
END;
$function$;

REVOKE ALL ON FUNCTION public.update_expert_rule_audited(uuid, text, text, text, text, text, text, text, text[][], text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_expert_rule_audited(uuid, text, text, text, text, text, text, text, text[][], text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.update_expert_rule_audited(uuid, text, text, text, text, text, text, text, text[][], text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/update_integration_health.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: update_integration_health
-- Popis: Aktualizuje health status integrační služby a zapíše log.
--        Voláno Aishou periodicky (health check workflow).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.update_integration_health(
  p_service_name    text,
  p_health_status   text,
  p_duration_ms     integer DEFAULT NULL,
  p_error_message   text DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_service_id uuid;
BEGIN
  -- Authorization: admin/staff only
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff role required';
  END IF;

  -- Update health status
  UPDATE public.integration_services
  SET
    health_status     = p_health_status,
    last_health_check = now(),
    updated_at        = now()
  WHERE service_name = p_service_name
  RETURNING id INTO v_service_id;

  IF v_service_id IS NULL THEN
    RAISE EXCEPTION 'Integration service not found: %', p_service_name;
  END IF;

  -- Log health check
  INSERT INTO public.integration_service_logs (
    service_id, action, action_detail, status, error_message, duration_ms
  )
  VALUES (
    v_service_id,
    'health_check',
    jsonb_build_object('health_status', p_health_status),
    CASE WHEN p_health_status = 'healthy' THEN 'success' ELSE 'failure' END,
    p_error_message,
    p_duration_ms
  );
END;
$$;

REVOKE ALL ON FUNCTION public.update_integration_health(text, text, integer, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_integration_health(text, text, integer, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/update_leaderboard_rankings.sql
-- -----------------------------------------------------------------------------

-- Function: public.update_leaderboard_rankings
-- Arguments: (none)
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:28:18+01:00

CREATE OR REPLACE FUNCTION public.update_leaderboard_rankings()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_period RECORD;
BEGIN
  -- Ensure periods exist first
  PERFORM ensure_leaderboard_periods();

  -- Update rankings for all active periods
  FOR v_period IN
    SELECT id, period_type, period_start, period_end
    FROM leaderboard_periods
    WHERE period_end >= CURRENT_DATE
  LOOP
    -- Use a single UPSERT operation instead of DELETE + INSERT
    WITH user_stats AS (
      SELECT
        ta.user_id,
        COALESCE(ta.balance, 0)::INTEGER as total_points,
        (
          SELECT COUNT(*)::INTEGER
          FROM reminder_completions rc
          WHERE rc.user_id = ta.user_id
            AND DATE(rc.completed_at) BETWEEN v_period.period_start AND v_period.period_end
        ) as completions_count,
        -- Calculate streak for period
        (
          WITH daily_activity AS (
            SELECT DISTINCT DATE(completed_at) as activity_date
            FROM reminder_completions
            WHERE user_id = ta.user_id
              AND DATE(completed_at) BETWEEN v_period.period_start AND LEAST(v_period.period_end, CURRENT_DATE)
            UNION
            SELECT DISTINCT check_in_date
            FROM health_check_ins
            WHERE user_id = ta.user_id
              AND check_in_date BETWEEN v_period.period_start AND LEAST(v_period.period_end, CURRENT_DATE)
          ),
          streak_groups AS (
            SELECT
              activity_date,
              activity_date - (ROW_NUMBER() OVER (ORDER BY activity_date) * INTERVAL '1 day') as grp
            FROM daily_activity
          )
          SELECT COALESCE(MAX(cnt), 0)::INTEGER
          FROM (SELECT COUNT(*) as cnt FROM streak_groups GROUP BY grp) sub
        ) as streak_days
      FROM token_allocations ta
      WHERE ta.balance > 0
    ),
    ranked_users AS (
      SELECT
        user_id,
        total_points,
        completions_count,
        streak_days,
        ROW_NUMBER() OVER (ORDER BY total_points DESC, completions_count DESC) as rank
      FROM user_stats
      WHERE total_points > 0
    )
    INSERT INTO leaderboard_entries (period_id, user_id, total_points, completions_count, streak_days, rank, updated_at)
    SELECT
      v_period.id,
      user_id,
      total_points,
      completions_count,
      streak_days,
      rank::INTEGER,
      now()
    FROM ranked_users
    ON CONFLICT (period_id, user_id) DO UPDATE SET
      total_points = EXCLUDED.total_points,
      completions_count = EXCLUDED.completions_count,
      streak_days = EXCLUDED.streak_days,
      rank = EXCLUDED.rank,
      updated_at = now();
  END LOOP;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.update_leaderboard_rankings() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_leaderboard_rankings() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/update_mcp_status_admin.sql
-- -----------------------------------------------------------------------------

-- Function: update_mcp_status_admin
-- Operator status transition for mcp_server_registry. Unlike provider
-- registry (binary on/off toggle), MCP servers have a 7-state lifecycle
-- and only specific transitions are valid:
--
--   discovered    → tested_ok / tested_failed / rejected
--   tested_ok     → enabled / rejected / deprecated
--   enabled       → in_use / deprecated
--   in_use        → deprecated   (cannot go back without re-test)
--   tested_failed → tested_ok    (after retry succeeded — usually via probe)
--   deprecated    → enabled      (operator override / reactivation)
--   rejected      → discovered   (operator override / wants to re-evaluate)
--
-- The transitions enforced here are operator-driven (admin UI buttons).
-- WF_MCP_PROBE writes status transitions via aisha_record_mcp_test_result
-- (probe-driven), and those bypass this validation (probe outcomes are
-- authoritative for tested_ok/tested_failed).
--
-- Audits via audit_journal action='MCP_STATUS_UPDATED'.

CREATE OR REPLACE FUNCTION public.update_mcp_status_admin(
  p_mcp_id      uuid,
  p_new_status  text,
  p_note        text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_slug          text;
  v_old_status    text;
  v_valid_transition boolean := false;
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Admin or staff role required' USING ERRCODE = '22023';
  END IF;

  IF p_mcp_id IS NULL THEN
    RAISE EXCEPTION 'p_mcp_id required' USING ERRCODE = '22023';
  END IF;

  IF p_new_status NOT IN ('discovered', 'tested_ok', 'tested_failed', 'enabled', 'in_use', 'deprecated', 'rejected') THEN
    RAISE EXCEPTION 'Invalid p_new_status: % (allowed: discovered|tested_ok|tested_failed|enabled|in_use|deprecated|rejected)', p_new_status
      USING ERRCODE = '22023';
  END IF;

  SELECT slug, status INTO v_slug, v_old_status
  FROM   mcp_server_registry
  WHERE  id = p_mcp_id
  FOR    UPDATE;

  IF v_slug IS NULL THEN
    RAISE EXCEPTION 'MCP server not found: %', p_mcp_id USING ERRCODE = '22023';
  END IF;

  -- No-op idempotency: same status → success but no audit/update
  IF v_old_status = p_new_status THEN
    RETURN jsonb_build_object(
      'success',         true,
      'slug',            v_slug,
      'old_status',      v_old_status,
      'new_status',      p_new_status,
      'transition',      'no_change'
    );
  END IF;

  -- Validate operator-driven transitions. We enforce these explicitly rather
  -- than letting any → any to prevent accidental footguns. The probe path
  -- (aisha_record_mcp_test_result) bypasses this — it's authoritative for
  -- tested_ok / tested_failed.
  v_valid_transition := CASE
    WHEN v_old_status = 'discovered'    AND p_new_status IN ('tested_ok', 'tested_failed', 'rejected') THEN true
    WHEN v_old_status = 'tested_ok'     AND p_new_status IN ('enabled', 'rejected', 'deprecated')      THEN true
    WHEN v_old_status = 'enabled'       AND p_new_status IN ('in_use', 'deprecated')                   THEN true
    WHEN v_old_status = 'in_use'        AND p_new_status IN ('deprecated')                             THEN true
    WHEN v_old_status = 'tested_failed' AND p_new_status IN ('tested_ok', 'rejected')                  THEN true
    WHEN v_old_status = 'deprecated'    AND p_new_status IN ('enabled')                                THEN true
    WHEN v_old_status = 'rejected'      AND p_new_status IN ('discovered')                             THEN true
    ELSE false
  END;

  IF NOT v_valid_transition THEN
    RAISE EXCEPTION 'Invalid transition: % → % (run aisha_test_mcp_server to probe first, or check allowed transitions in update_mcp_status_admin docs)',
      v_old_status, p_new_status USING ERRCODE = '22023';
  END IF;

  UPDATE mcp_server_registry
  SET    status     = p_new_status,
         updated_at = now()
  WHERE  id = p_mcp_id;

  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'MCP_STATUS_UPDATED',
    jsonb_build_object(
      'area',         'mcp',
      'severity',     'info',
      'entity_type',  'mcp_server_registry',
      'entity_id',    p_mcp_id::text,
      'slug',         v_slug,
      'old_status',   v_old_status,
      'new_status',   p_new_status,
      'note',         LEFT(COALESCE(p_note, ''), 200)
    )
  );

  RETURN jsonb_build_object(
    'success',    true,
    'slug',       v_slug,
    'old_status', v_old_status,
    'new_status', p_new_status,
    'transition', v_old_status || ' → ' || p_new_status
  );
END;
$$;

REVOKE ALL ON FUNCTION public.update_mcp_status_admin(uuid, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_mcp_status_admin(uuid, text, text) TO authenticated;

COMMENT ON FUNCTION public.update_mcp_status_admin(uuid, text, text) IS
  'AdminMcpServerRegistry UI status transition RPC — operator-driven lifecycle. Enforces valid transitions per state machine. Probe-driven transitions bypass this via aisha_record_mcp_test_result. Audits MCP_STATUS_UPDATED.';


