REVOKE ALL ON FUNCTION public.update_my_storyloop_ui_preferences(jsonb, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_my_storyloop_ui_preferences(jsonb, boolean) TO authenticated;


