-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/update_user_wallet_balance.sql
-- -----------------------------------------------------------------------------

-- Function: public.update_user_wallet_balance
-- Trigger helper: keeps user_wallets in sync with token_transactions inserts.

CREATE OR REPLACE FUNCTION public.update_user_wallet_balance()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.user_id IS NULL OR NEW.token_type IS NULL OR NEW.amount IS NULL THEN
    RETURN NEW;
  END IF;

  -- D4: 'aisha' is a first-class balance column — it must NOT be dropped on the
  -- floor. The accepted set includes every wallet token type.
  IF NEW.token_type NOT IN ('governance', 'impact', 'data', 'aisha') THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.user_wallets (
    user_id,
    governance_tokens,
    impact_tokens,
    data_tokens,
    aisha_tokens,
    created_at,
    updated_at
  )
  VALUES (
    NEW.user_id,
    CASE WHEN NEW.token_type = 'governance' THEN NEW.amount ELSE 0 END,
    CASE WHEN NEW.token_type = 'impact' THEN NEW.amount ELSE 0 END,
    CASE WHEN NEW.token_type = 'data' THEN NEW.amount ELSE 0 END,
    CASE WHEN NEW.token_type = 'aisha' THEN NEW.amount ELSE 0 END,
    now(),
    now()
  )
  ON CONFLICT (user_id) DO UPDATE
  SET
    governance_tokens = public.user_wallets.governance_tokens + CASE WHEN NEW.token_type = 'governance' THEN NEW.amount ELSE 0 END,
    impact_tokens = public.user_wallets.impact_tokens + CASE WHEN NEW.token_type = 'impact' THEN NEW.amount ELSE 0 END,
    data_tokens = public.user_wallets.data_tokens + CASE WHEN NEW.token_type = 'data' THEN NEW.amount ELSE 0 END,
    aisha_tokens = public.user_wallets.aisha_tokens + CASE WHEN NEW.token_type = 'aisha' THEN NEW.amount ELSE 0 END,
    updated_at = now();

  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.update_user_wallet_balance() FROM PUBLIC;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_agent_tool_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.upsert_agent_tool_admin
-- Description: Create or update an agent tool entry. Admin/staff only.
-- Security: SECURITY DEFINER, admin/staff only
-- Created: Phase 2 — Tool System

CREATE OR REPLACE FUNCTION public.upsert_agent_tool_admin(
  p_id uuid DEFAULT NULL,
  p_name text DEFAULT NULL,
  p_display_name_key text DEFAULT '',
  p_description text DEFAULT '',
  p_parameters_schema jsonb DEFAULT '{}',
  p_handler_type text DEFAULT 'rpc',
  p_handler_ref text DEFAULT '',
  p_access_tier_min text DEFAULT 'basic',
  p_requires_consent boolean DEFAULT false,
  p_audit_action text DEFAULT NULL,
  p_is_active boolean DEFAULT true,
  p_metadata jsonb DEFAULT '{}'
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id uuid;
  v_user_id uuid := auth.uid();
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = 'P0003';
  END IF;

  IF p_id IS NOT NULL THEN
    -- UPDATE existing
    UPDATE agent_tools SET
      name = COALESCE(NULLIF(p_name, ''), name),
      display_name_key = p_display_name_key,
      description = p_description,
      parameters_schema = p_parameters_schema,
      handler_type = p_handler_type::tool_handler_type,
      handler_ref = p_handler_ref,
      access_tier_min = p_access_tier_min,
      requires_consent = p_requires_consent,
      audit_action = p_audit_action,
      is_active = p_is_active,
      metadata = p_metadata,
      updated_by = v_user_id
    WHERE id = p_id
    RETURNING id INTO v_id;

    IF v_id IS NULL THEN
      RAISE EXCEPTION 'Tool not found: %', p_id USING ERRCODE = 'P0002';
    END IF;
  ELSE
    -- INSERT new
    INSERT INTO agent_tools (
      name, display_name_key, description, parameters_schema,
      handler_type, handler_ref, access_tier_min,
      requires_consent, audit_action, is_active, metadata,
      created_by, updated_by
    ) VALUES (
      p_name, p_display_name_key, p_description, p_parameters_schema,
      p_handler_type::tool_handler_type, p_handler_ref, p_access_tier_min,
      p_requires_consent, p_audit_action, p_is_active, p_metadata,
      v_user_id, v_user_id
    )
    RETURNING id INTO v_id;
  END IF;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.upsert_agent_tool_admin(uuid, text, text, text, jsonb, text, text, text, boolean, text, boolean, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.upsert_agent_tool_admin(uuid, text, text, text, jsonb, text, text, text, boolean, text, boolean, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_call_participant.sql
-- -----------------------------------------------------------------------------

-- Function: public.upsert_call_participant
-- Records a participant join into a voice room (svc-livekit routes/token.ts,
-- after issuing the room access token). Idempotent on (voice_room_id, user_id):
-- a re-join refreshes joined_at/role and clears left_at.
-- Security: SECURITY DEFINER (service_role-invoked via rpcService), search_path pinned.

CREATE OR REPLACE FUNCTION public.upsert_call_participant(
  p_joined_at timestamptz,
  p_role text,
  p_user_id uuid,
  p_voice_room_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF p_user_id IS NULL OR p_voice_room_id IS NULL THEN
    RAISE EXCEPTION 'user_id and voice_room_id are required' USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.call_participants (voice_room_id, user_id, joined_at, role)
  VALUES (p_voice_room_id, p_user_id, COALESCE(p_joined_at, now()), COALESCE(p_role, 'participant'))
  ON CONFLICT (voice_room_id, user_id) DO UPDATE
    SET joined_at = EXCLUDED.joined_at,
        role      = EXCLUDED.role,
        left_at   = NULL;
END;
$function$;

COMMENT ON FUNCTION public.upsert_call_participant(timestamptz, text, uuid, uuid) IS
  'Upserts a voice-room participant join (idempotent on voice_room_id + user_id).';

REVOKE ALL ON FUNCTION public.upsert_call_participant(timestamptz, text, uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.upsert_call_participant(timestamptz, text, uuid, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_contract_extract_audited.sql
-- -----------------------------------------------------------------------------

-- Function: upsert_contract_extract_audited
-- Evidence layer (E5): upserts the structured extract for a registered contract
-- document and ATOMICALLY replaces its obligations. Service-role only (NULL-safe
-- guard). Invariants:
--   * re-extract DROPS human_verified (a human must re-confirm after content change),
--   * obligations are replaced as a set and are ALWAYS born human_confirmed=false
--     (legal content is never authoritative without a human).

CREATE OR REPLACE FUNCTION public.upsert_contract_extract_audited(
  p_document_id uuid,
  p_extract jsonb,
  p_confidence numeric DEFAULT NULL::numeric,
  p_counterparty text DEFAULT NULL::text,
  p_subject text DEFAULT NULL::text,
  p_valid_from date DEFAULT NULL::date,
  p_valid_to date DEFAULT NULL::date,
  p_obligations jsonb DEFAULT '[]'::jsonb
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contract_id uuid;
  v_obligation_count integer := 0;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM public.document_registry WHERE id = p_document_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown document' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.contract_register AS cr (
    document_id, counterparty, subject, valid_from, valid_to, extract, confidence
  )
  VALUES (
    p_document_id, p_counterparty, p_subject, p_valid_from, p_valid_to,
    COALESCE(p_extract, '{}'::jsonb), p_confidence
  )
  ON CONFLICT (document_id) DO UPDATE SET
    counterparty   = EXCLUDED.counterparty,
    subject        = EXCLUDED.subject,
    valid_from     = EXCLUDED.valid_from,
    valid_to       = EXCLUDED.valid_to,
    extract        = EXCLUDED.extract,
    confidence     = EXCLUDED.confidence,
    -- re-extract invalidates prior human verification
    human_verified = false,
    verified_by    = NULL,
    verified_at    = NULL,
    updated_at     = now()
  RETURNING cr.id INTO v_contract_id;

  -- atomic obligation replacement (same tx): delete-then-insert from the payload
  DELETE FROM public.obligation_register WHERE contract_id = v_contract_id;
  INSERT INTO public.obligation_register (
    contract_id, obliged_party, action, due_rule, consequence, source_clause
  )
  SELECT
    v_contract_id,
    o->>'obliged_party',
    o->>'action',
    COALESCE(o->'due_rule', '{}'::jsonb),
    o->>'consequence',
    o->'source_clause'
  FROM jsonb_array_elements(COALESCE(p_obligations, '[]'::jsonb)) AS o;
  GET DIAGNOSTICS v_obligation_count = ROW_COUNT;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (auth.uid(), 'CONTRACT_EXTRACT_UPSERTED', 'CONTRACT_EXTRACT_UPSERTED', 'content', 'info',
          ARRAY['evidence', 'contract'],
          jsonb_build_object('document_id', p_document_id, 'confidence', p_confidence,
                             'obligations', v_obligation_count));

  RETURN jsonb_build_object('contract_id', v_contract_id, 'obligations', v_obligation_count);
END;
$function$

;

REVOKE ALL ON FUNCTION upsert_contract_extract_audited(uuid,jsonb,numeric,text,text,date,date,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION upsert_contract_extract_audited(uuid,jsonb,numeric,text,text,date,date,jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_design_profile.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- Function: upsert_design_profile — Occipitum: create/update design DNA
-- =============================================================================
CREATE OR REPLACE FUNCTION public.upsert_design_profile(
  p_brand_dna jsonb DEFAULT NULL,
  p_design_constraints jsonb DEFAULT NULL,
  p_partner_id uuid DEFAULT NULL,
  p_style_preferences jsonb DEFAULT NULL,
  p_ux_persona jsonb DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_caller_id uuid;
  v_partner_owner uuid;
  v_profile_id uuid;
  v_version integer;
BEGIN
  v_caller_id := auth.uid();

  SELECT user_id INTO v_partner_owner
  FROM public.partner_profiles
  WHERE id = p_partner_id;

  IF v_partner_owner IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Partner not found');
  END IF;

  IF v_caller_id != v_partner_owner AND NOT is_admin_or_staff() THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Unauthorized');
  END IF;

  INSERT INTO public.design_profiles (partner_id, brand_dna, ux_persona, style_preferences, design_constraints)
  VALUES (
    p_partner_id,
    COALESCE(p_brand_dna, '{}'::jsonb),
    COALESCE(p_ux_persona, '{}'::jsonb),
    COALESCE(p_style_preferences, '{}'::jsonb),
    COALESCE(p_design_constraints, '{}'::jsonb)
  )
  ON CONFLICT (partner_id) DO UPDATE SET
    brand_dna = COALESCE(p_brand_dna, design_profiles.brand_dna),
    ux_persona = COALESCE(p_ux_persona, design_profiles.ux_persona),
    style_preferences = COALESCE(p_style_preferences, design_profiles.style_preferences),
    design_constraints = COALESCE(p_design_constraints, design_profiles.design_constraints),
    profile_version = design_profiles.profile_version + 1,
    updated_at = now()
  RETURNING id, profile_version INTO v_profile_id, v_version;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    v_caller_id,
    'DESIGN_PROFILE_UPSERT',
    jsonb_build_object(
      'area', 'occipitum',
      'severity', 'info',
      'entity_type', 'design_profile',
      'entity_id', v_profile_id,
      'partner_id', p_partner_id,
      'version', v_version
    )
  );

  RETURN jsonb_build_object(
    'status', 'ok',
    'profile_id', v_profile_id,
    'profile_version', v_version
  );
END;
$$;

REVOKE ALL ON FUNCTION public.upsert_design_profile(jsonb, jsonb, uuid, jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.upsert_design_profile(jsonb, jsonb, uuid, jsonb, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.upsert_design_profile(jsonb, jsonb, uuid, jsonb, jsonb) TO service_role;

COMMENT ON FUNCTION public.upsert_design_profile(jsonb, jsonb, uuid, jsonb, jsonb) IS
  'Occipitum: create or update design DNA profile with audit logging.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_discovered_model.sql
-- -----------------------------------------------------------------------------

-- Function: upsert_discovered_model

-- Signature change (odysseus G1): +p_cached_input_price_per_m (prompt-cache READ rate).
-- Added at the END with a DEFAULT so the first 15 positional args stay compatible, but
-- Postgres keeps the prior 15-arg function as a separate overload — which makes a
-- 15-arg call ambiguous. Drop the old signature first so only the 16-arg version exists.
DROP FUNCTION IF EXISTS public.upsert_discovered_model(text, text, text, text, boolean, boolean, boolean, boolean, boolean, boolean, integer, integer, numeric, numeric, jsonb);

-- ⛔ Signature change 2026-09-13: +p_embedding_dimensions (MĚŘENÝ rozměr vektoru).
-- Discovery rozměr embedding modelu dosud nenesl — v registru stála jen deklarace
-- ze seedu, ačkoli alias (EMBED_ALIAS) volí instance a pod týmž jménem může běžet
-- model jiného rozměru. Resolver prostoru (fn_resolve_embedding_model_for_space:
-- 1024 → v1, 2560 → v2) se o rozměr opírá; nesedící vektor pak Postgres odmítne až
-- při zápisu do sloupce. Stejný důvod pro DROP jako výš: 16-arg přetížení by vedle
-- 17-arg zůstalo a PostgREST by volání bez nového parametru hlásil nejednoznačné.
DROP FUNCTION IF EXISTS public.upsert_discovered_model(text, text, text, text, boolean, boolean, boolean, boolean, boolean, boolean, integer, integer, numeric, numeric, jsonb, numeric);

CREATE OR REPLACE FUNCTION public.upsert_discovered_model(p_provider text, p_model_id text, p_display_name text DEFAULT NULL::text, p_model_family text DEFAULT NULL::text, p_is_chat_capable boolean DEFAULT true, p_is_reasoning boolean DEFAULT false, p_is_vision boolean DEFAULT false, p_is_code_optimized boolean DEFAULT false, p_is_function_calling boolean DEFAULT false, p_is_embedding boolean DEFAULT false, p_context_window integer DEFAULT NULL::integer, p_max_output_tokens integer DEFAULT NULL::integer, p_input_price_per_m numeric DEFAULT NULL::numeric, p_output_price_per_m numeric DEFAULT NULL::numeric, p_provider_metadata jsonb DEFAULT '{}'::jsonb, p_cached_input_price_per_m numeric DEFAULT NULL::numeric, p_embedding_dimensions integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_model_id uuid;
  v_is_new boolean := false;
  v_was_unavailable boolean := false;
  v_dimensions integer;
BEGIN
  -- Service role only (called by edge function)
  IF NOT (
    public.is_service_role()
    OR is_admin_or_staff()
  ) THEN
    RAISE EXCEPTION 'Service role or admin required';
  END IF;

  -- Rozměr je měření, ne volba: nula nebo záporné číslo není rozměr, je to vada sondy.
  IF p_embedding_dimensions IS NOT NULL AND p_embedding_dimensions <= 0 THEN
    RAISE EXCEPTION 'p_embedding_dimensions must be positive (got %)', p_embedding_dimensions;
  END IF;

  -- Check if model already exists
  SELECT id, NOT is_available INTO v_model_id, v_was_unavailable
  FROM ai_model_registry
  WHERE provider = p_provider AND model_id = p_model_id;

  IF v_model_id IS NULL THEN
    -- New model discovered
    v_is_new := true;

    INSERT INTO ai_model_registry (
      provider, model_id, display_name, model_family,
      is_chat_capable, is_reasoning, is_vision, is_code_optimized, is_function_calling, is_embedding,
      embedding_dimensions,
      context_window, max_output_tokens,
      input_price_per_m, output_price_per_m, cached_input_price_per_m,
      provider_metadata, eval_status, provider_registry_id
    ) VALUES (
      p_provider, p_model_id, p_display_name, p_model_family,
      p_is_chat_capable, p_is_reasoning, p_is_vision, p_is_code_optimized, p_is_function_calling, p_is_embedding,
      p_embedding_dimensions,
      p_context_window, p_max_output_tokens,
      p_input_price_per_m, p_output_price_per_m, p_cached_input_price_per_m,
      p_provider_metadata, 'pending',
      -- Link to the provider registry so the capability resolvers can JOIN by id.
      -- A model's `provider` is the family key; the registry `slug` is the
      -- addressable provider id (they differ for google/vllm) — normalize here so
      -- a freshly DISCOVERED Gemini/vLLM model is not silently dropped by the JOIN.
      (SELECT id FROM ai_provider_registry
        WHERE slug = CASE p_provider
                       WHEN 'google' THEN 'google-genai'
                       WHEN 'vllm'   THEN 'vllm-local'
                       ELSE p_provider
                     END)
    )
    RETURNING id, embedding_dimensions INTO v_model_id, v_dimensions;
  ELSE
    -- Update existing model
    UPDATE ai_model_registry
    SET last_seen_at = now(),
        is_available = true,
        display_name = COALESCE(p_display_name, display_name),
        model_family = COALESCE(p_model_family, model_family),
        is_chat_capable = p_is_chat_capable,
        is_reasoning = p_is_reasoning,
        is_vision = p_is_vision,
        is_code_optimized = p_is_code_optimized,
        is_function_calling = p_is_function_calling,
        is_embedding = p_is_embedding,
        -- MĚŘENÍ PŘEBÍJÍ DEKLARACI: změřený rozměr nahradí seedovaný. Nezměřeno (NULL)
        -- dosavadní hodnotu nechá — sonda, která neodpověděla, nic nevyvrací.
        embedding_dimensions = COALESCE(p_embedding_dimensions, embedding_dimensions),
        context_window = COALESCE(p_context_window, context_window),
        max_output_tokens = COALESCE(p_max_output_tokens, max_output_tokens),
        input_price_per_m = COALESCE(p_input_price_per_m, input_price_per_m),
        output_price_per_m = COALESCE(p_output_price_per_m, output_price_per_m),
        -- COALESCE: a scan that doesn't report a cache rate must not wipe an existing one.
        cached_input_price_per_m = COALESCE(p_cached_input_price_per_m, cached_input_price_per_m),
        -- Změřená metadata discovery přepisuje CELÁ (klíč, který sken přestal hlásit,
        -- nesmí zůstat se starou hodnotou). Jmenný prostor `declared` ale nepatří
        -- měření: je to DEKLARACE instance (např. pin vah embedderu, z nějž se skládá
        -- živá identita vektorů — idata 50_ai_provider_local_model.sql). Discovery ho
        -- proto ZACHOVÁ; bez toho by první sken pin smazal a platformní dopočet
        -- vektorů by přestal znát identitu runtime (fail-closed, ale tiché pro pokrytí).
        provider_metadata = p_provider_metadata
          || jsonb_strip_nulls(jsonb_build_object('declared', ai_model_registry.provider_metadata->'declared'))
    WHERE id = v_model_id
    RETURNING embedding_dimensions INTO v_dimensions;
  END IF;

  RETURN jsonb_build_object(
    'model_registry_id', v_model_id,
    'is_new', v_is_new,
    'was_unavailable', v_was_unavailable,
    'provider', p_provider,
    'model_id', p_model_id,
    -- Aktuální rozměr v registru (po zápisu) — discovery podle něj pozná, jestli
    -- je co měřit, a nemusí sondovat pomalý CPU embedding při každém průchodu.
    'embedding_dimensions', v_dimensions
  );
END;
$function$;

REVOKE ALL ON FUNCTION upsert_discovered_model(text, text, text, text, boolean, boolean, boolean, boolean, boolean, boolean, integer, integer, numeric, numeric, jsonb, numeric, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION upsert_discovered_model(text,text,text,text,boolean,boolean,boolean,boolean,boolean,boolean,integer,integer,numeric,numeric,jsonb,numeric,integer) TO authenticated;
GRANT EXECUTE ON FUNCTION upsert_discovered_model(text,text,text,text,boolean,boolean,boolean,boolean,boolean,boolean,integer,integer,numeric,numeric,jsonb,numeric,integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_featured_product_admin.sql
-- -----------------------------------------------------------------------------

-- Function: upsert_featured_product_admin
-- Description: Create or update featured product (admin only)
-- Security: SECURITY DEFINER with admin check + audit
-- Created: 2026-02-03

CREATE OR REPLACE FUNCTION upsert_featured_product_admin(
  p_id uuid DEFAULT NULL,
  p_product_id uuid DEFAULT NULL,
  p_badge_key text DEFAULT NULL,
  p_title_key text DEFAULT NULL,
  p_subtitle_key text DEFAULT NULL,
  p_feature_keys text[] DEFAULT NULL,
  p_cta_text_key text DEFAULT NULL,
  p_cta_url text DEFAULT NULL,
  p_price_period_days int4 DEFAULT NULL,
  p_show_price bool DEFAULT NULL,
  p_image_url text DEFAULT NULL,
  p_background_gradient text DEFAULT NULL,
  p_display_location text DEFAULT NULL,
  p_sort_order int4 DEFAULT NULL,
  p_is_active bool DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
DECLARE
  v_result_id uuid;
  v_is_insert bool := false;
BEGIN
  -- Authorization check
  IF NOT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = auth.uid()
    AND role IN ('admin', 'staff')
  ) THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff role required';
  END IF;

  -- Validate product exists
  IF p_product_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM products WHERE id = p_product_id
  ) THEN
    RAISE EXCEPTION 'Product not found: %', p_product_id;
  END IF;

  IF p_id IS NULL THEN
    -- INSERT new
    v_is_insert := true;
    INSERT INTO featured_products (
      product_id,
      badge_key,
      title_key,
      subtitle_key,
      feature_keys,
      cta_text_key,
      cta_url,
      price_period_days,
      show_price,
      image_url,
      background_gradient,
      display_location,
      sort_order,
      is_active
    ) VALUES (
      COALESCE(p_product_id, (SELECT id FROM products WHERE is_active LIMIT 1)),
      COALESCE(p_badge_key, 'featured.default.badge'),
      COALESCE(p_title_key, 'featured.default.title'),
      p_subtitle_key,
      COALESCE(p_feature_keys, ARRAY[]::text[]),
      COALESCE(p_cta_text_key, 'featured.default.cta'),
      p_cta_url,
      COALESCE(p_price_period_days, 30),
      COALESCE(p_show_price, true),
      p_image_url,
      COALESCE(p_background_gradient, 'from-primary/5 via-primary/10 to-secondary/10'),
      COALESCE(p_display_location, 'homepage'),
      COALESCE(p_sort_order, 0),
      COALESCE(p_is_active, true)
    )
    RETURNING id INTO v_result_id;
  ELSE
    -- UPDATE existing
    UPDATE featured_products SET
      product_id = COALESCE(p_product_id, product_id),
      badge_key = COALESCE(p_badge_key, badge_key),
      title_key = COALESCE(p_title_key, title_key),
      subtitle_key = COALESCE(p_subtitle_key, subtitle_key),
      feature_keys = COALESCE(p_feature_keys, feature_keys),
      cta_text_key = COALESCE(p_cta_text_key, cta_text_key),
      cta_url = COALESCE(p_cta_url, cta_url),
      price_period_days = COALESCE(p_price_period_days, price_period_days),
      show_price = COALESCE(p_show_price, show_price),
      image_url = COALESCE(p_image_url, image_url),
      background_gradient = COALESCE(p_background_gradient, background_gradient),
      display_location = COALESCE(p_display_location, display_location),
      sort_order = COALESCE(p_sort_order, sort_order),
      is_active = COALESCE(p_is_active, is_active),
      updated_at = NOW()
    WHERE id = p_id
    RETURNING id INTO v_result_id;

    IF v_result_id IS NULL THEN
      RAISE EXCEPTION 'Featured product not found: %', p_id;
    END IF;
  END IF;

  -- Audit log
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    CASE WHEN v_is_insert THEN 'ADMIN_CREATE' ELSE 'ADMIN_UPDATE' END,
    jsonb_build_object(
      'area', 'featured_products',
      'entity_id', v_result_id,
      'severity', 'info'
    )
  );

  RETURN v_result_id;
END;
$$;

-- Security
REVOKE ALL ON FUNCTION upsert_featured_product_admin(uuid, uuid, text, text, text, text[][], text, text, integer, boolean, text, text, text, integer, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION upsert_featured_product_admin(uuid, uuid, text, text, text, text[][], text, text, integer, boolean, text, text, text, integer, boolean) TO authenticated;

COMMENT ON FUNCTION upsert_featured_product_admin(uuid, uuid, text, text, text, text[][], text, text, integer, boolean, text, text, text, integer, boolean) IS 'Create or update featured product configuration (admin only)';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_github_app_installation.sql
-- -----------------------------------------------------------------------------

-- Function: public.upsert_github_app_installation
-- Named, audited replacement for the raw_query_admin INSERT..ON CONFLICT in
-- svc-github-app/routes/webhook-bridge.ts (installation.created webhook).
-- Registers/refreshes a GitHub App installation row. Idempotent on installation_id;
-- a re-install (created event after a prior suspend/uninstall) clears suspended_at.
-- Security: SECURITY DEFINER (service_role-invoked via rpcService), search_path pinned.

CREATE OR REPLACE FUNCTION public.upsert_github_app_installation(
  p_installation_id bigint,
  p_account_login text,
  p_account_type text,
  p_permissions jsonb DEFAULT '{}'::jsonb,
  p_repository_selection text DEFAULT 'selected'
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF p_installation_id IS NULL THEN
    RAISE EXCEPTION 'installation_id is required' USING ERRCODE = 'check_violation';
  END IF;

  IF p_account_login IS NULL OR p_account_type IS NULL THEN
    RAISE EXCEPTION 'account_login and account_type are required' USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.github_app_installations
    (installation_id, account_login, account_type, permissions, repository_selection)
  VALUES
    (p_installation_id,
     p_account_login,
     p_account_type,
     COALESCE(p_permissions, '{}'::jsonb),
     COALESCE(NULLIF(p_repository_selection, ''), 'selected'))
  ON CONFLICT (installation_id) DO UPDATE
    SET account_login        = EXCLUDED.account_login,
        account_type         = EXCLUDED.account_type,
        permissions          = EXCLUDED.permissions,
        repository_selection = EXCLUDED.repository_selection,
        suspended_at         = NULL,
        updated_at           = now();
END;
$function$;

COMMENT ON FUNCTION public.upsert_github_app_installation(bigint, text, text, jsonb, text) IS
  'Registers/refreshes a GitHub App installation (idempotent on installation_id; clears suspended_at on re-install).';

REVOKE ALL ON FUNCTION public.upsert_github_app_installation(bigint, text, text, jsonb, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.upsert_github_app_installation(bigint, text, text, jsonb, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_github_app_repositories.sql
-- -----------------------------------------------------------------------------

-- Function: public.upsert_github_app_repositories
-- Named, audited replacement for the raw_query_admin upsert in
-- svc-github-app/routes/webhook-bridge.ts (installation_repositories webhook).
-- Bulk-upserts the repo cache from a jsonb array of rows. Idempotent on
-- (installation_id, repo_id).
-- Security: SECURITY DEFINER (service_role-invoked via rpcService), search_path pinned.

CREATE OR REPLACE FUNCTION public.upsert_github_app_repositories(
  p_rows jsonb
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'p_rows must be a jsonb array' USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.github_app_repositories
    (installation_id, repo_id, repo_full_name, is_private, default_branch, is_active, updated_at)
  SELECT
    (r ->> 'installation_id')::bigint,
    (r ->> 'repo_id')::bigint,
    r ->> 'repo_full_name',
    COALESCE((r ->> 'is_private')::boolean, true),
    COALESCE(NULLIF(r ->> 'default_branch', ''), 'main'),
    COALESCE((r ->> 'is_active')::boolean, true),
    COALESCE((r ->> 'updated_at')::timestamptz, now())
  FROM jsonb_array_elements(p_rows) AS r
  ON CONFLICT (installation_id, repo_id) DO UPDATE
    SET repo_full_name = EXCLUDED.repo_full_name,
        is_private     = EXCLUDED.is_private,
        default_branch = EXCLUDED.default_branch,
        is_active      = EXCLUDED.is_active,
        updated_at     = now();
END;
$function$;

COMMENT ON FUNCTION public.upsert_github_app_repositories(jsonb) IS
  'Bulk-upsert of the GitHub App repo cache from a jsonb array (idempotent on installation_id + repo_id).';

REVOKE ALL ON FUNCTION public.upsert_github_app_repositories(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.upsert_github_app_repositories(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_integration_service.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: upsert_integration_service
-- Popis: Zaregistruje nebo aktualizuje integrační službu.
--        Používá Aisha při bootstrapu NocoDB/Langfuse.
-- ⛔ VLASTNICTVÍ A POVĚŘENÍ (2026-09-29): `service_name` je globální klíč. Dřív
--    DO UPDATE přepsal `managed_by` (převzetí služby jiného správce) a s NOVOU
--    `base_url` ponechal uložený `api_token` (COALESCE) — kdo změnil URL, poslal
--    tím cizí token na svůj server. Teď: existující službu aktualizuje jen týž
--    `managed_by` (jinak 42501 s klíčem a vlastníkem); při změně `base_url` platí
--    jen token předaný SPOLU s ní (bez něj NULL = zneplatněný); při stejné URL
--    zůstává uložený token jako dřív.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.upsert_integration_service(
  p_service_name  text,
  p_display_name  text,
  p_service_type  text,
  p_base_url      text,
  p_api_token     text DEFAULT NULL,
  p_config        jsonb DEFAULT '{}'::jsonb,
  p_managed_by    text DEFAULT 'aisha'
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_id uuid;
  v_vlastnik text;
BEGIN
  -- Authorization: admin/staff only
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff role required';
  END IF;

  SELECT i.managed_by INTO v_vlastnik
    FROM public.integration_services i
   WHERE i.service_name = p_service_name
   FOR UPDATE;
  IF FOUND AND v_vlastnik IS DISTINCT FROM p_managed_by THEN
    RAISE EXCEPTION 'integration service % is managed by %', p_service_name, COALESCE(v_vlastnik, '(none)')
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.integration_services (
    service_name, display_name, service_type, base_url, api_token, config, managed_by
  )
  VALUES (
    p_service_name, p_display_name, p_service_type, p_base_url, p_api_token, p_config, p_managed_by
  )
  ON CONFLICT (service_name) DO UPDATE SET
    display_name  = EXCLUDED.display_name,
    service_type  = EXCLUDED.service_type,
    base_url      = EXCLUDED.base_url,
    -- Nová URL → jen nový token (nebo žádný); stejná URL → uložený token zůstává.
    api_token     = CASE WHEN EXCLUDED.base_url IS DISTINCT FROM integration_services.base_url
                         THEN EXCLUDED.api_token
                         ELSE COALESCE(EXCLUDED.api_token, integration_services.api_token) END,
    config        = integration_services.config || EXCLUDED.config,
    updated_at    = now()
  WHERE integration_services.managed_by IS NOT DISTINCT FROM EXCLUDED.managed_by
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    -- Souběh: služba změnila správce mezi kontrolou a zápisem — nic se nepřevzalo.
    RAISE EXCEPTION 'integration service % is managed by another owner', p_service_name USING ERRCODE = '42501';
  END IF;

  -- Audit log
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'INTEGRATION_UPSERT',
    jsonb_build_object(
      'area', 'integrations',
      'severity', 'info',
      'service_name', p_service_name,
      'service_type', p_service_type,
      'managed_by', p_managed_by
    )
  );

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.upsert_integration_service(text, text, text, text, text, jsonb, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.upsert_integration_service(text, text, text, text, text, jsonb, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_leaderboard_reward_config_admin.sql
-- -----------------------------------------------------------------------------

-- upsert_leaderboard_reward_config_admin: Create or update leaderboard reward configuration
CREATE OR REPLACE FUNCTION public.upsert_leaderboard_reward_config_admin(
  p_bonus_token_type text DEFAULT 'aisha',
  p_bonus_tokens integer DEFAULT 0,
  p_id uuid DEFAULT NULL,
  p_is_active boolean DEFAULT true,
  p_period_type text DEFAULT 'weekly',
  p_rank_from integer DEFAULT 1,
  p_rank_to integer DEFAULT 1,
  p_voucher_product_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_admin_id uuid := auth.uid();
  v_result_id uuid;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  IF p_id IS NOT NULL THEN
    UPDATE public.leaderboard_reward_config SET
      bonus_token_type = p_bonus_token_type,
      bonus_tokens = p_bonus_tokens,
      is_active = p_is_active,
      period_type = p_period_type,
      rank_from = p_rank_from,
      rank_to = p_rank_to,
      voucher_product_id = p_voucher_product_id,
      updated_at = now()
    WHERE id = p_id
    RETURNING id INTO v_result_id;
  ELSE
    INSERT INTO public.leaderboard_reward_config (
      bonus_token_type,
      bonus_tokens,
      is_active,
      period_type,
      rank_from,
      rank_to,
      voucher_product_id
    ) VALUES (
      p_bonus_token_type,
      p_bonus_tokens,
      p_is_active,
      p_period_type,
      p_rank_from,
      p_rank_to,
      p_voucher_product_id
    )
    RETURNING id INTO v_result_id;
  END IF;

  -- Audit log
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_admin_id, 'LEADERBOARD_REWARD_CONFIG_UPSERT', jsonb_build_object(
    'area', 'admin',
    'severity', 'info',
    'config_id', v_result_id,
    'period_type', p_period_type,
    'rank_from', p_rank_from,
    'rank_to', p_rank_to
  ));

  RETURN v_result_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.upsert_leaderboard_reward_config_admin(text, integer, uuid, boolean, text, integer, integer, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.upsert_leaderboard_reward_config_admin(text, integer, uuid, boolean, text, integer, integer, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_product_catalog_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.upsert_product_catalog_admin
-- Arguments: p_id uuid DEFAULT NULL::uuid, p_code text DEFAULT NULL::text, p_category text DEFAULT 'product'::text, p_icon text DEFAULT '💊'::text, p_color text DEFAULT '#6366f1'::text, p_default_dose_amount numeric DEFAULT NULL::numeric, p_default_dose_unit text DEFAULT NULL::text, p_default_doses_per_day integer DEFAULT NULL::integer, p_default_dose_timing text[] DEFAULT NULL::text[], p_sort_order integer DEFAULT 0, p_is_active boolean DEFAULT true, p_translations jsonb DEFAULT NULL::jsonb
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.upsert_product_catalog_admin(p_id uuid DEFAULT NULL::uuid, p_code text DEFAULT NULL::text, p_category text DEFAULT 'product'::text, p_icon text DEFAULT '💊'::text, p_color text DEFAULT '#6366f1'::text, p_default_dose_amount numeric DEFAULT NULL::numeric, p_default_dose_unit text DEFAULT NULL::text, p_default_doses_per_day integer DEFAULT NULL::integer, p_default_dose_timing text[] DEFAULT NULL::text[], p_sort_order integer DEFAULT 0, p_is_active boolean DEFAULT true, p_translations jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id UUID;
  v_locale TEXT;
  v_trans JSONB;
  v_action TEXT;
BEGIN
  -- Authorization: admin only
  IF NOT has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized: admin role required';
  END IF;

  IF p_id IS NOT NULL THEN
    -- UPDATE existing
    UPDATE product_catalog SET
      code = COALESCE(p_code, code),
      category = COALESCE(p_category, category),
      icon = COALESCE(p_icon, icon),
      color = COALESCE(p_color, color),
      default_dose_amount = COALESCE(p_default_dose_amount, default_dose_amount),
      default_dose_unit = COALESCE(p_default_dose_unit, default_dose_unit),
      default_doses_per_day = COALESCE(p_default_doses_per_day, default_doses_per_day),
      default_dose_timing = COALESCE(p_default_dose_timing, default_dose_timing),
      sort_order = COALESCE(p_sort_order, sort_order),
      is_active = COALESCE(p_is_active, is_active),
      updated_at = now()
    WHERE id = p_id
    RETURNING id INTO v_id;

    v_action := 'update';
  ELSE
    -- INSERT new
    IF p_code IS NULL THEN
      RAISE EXCEPTION 'Code is required for new catalog entry';
    END IF;

    INSERT INTO product_catalog (
      code, category, icon, color,
      default_dose_amount, default_dose_unit, default_doses_per_day, default_dose_timing,
      sort_order, is_active
    ) VALUES (
      p_code, p_category, p_icon, p_color,
      p_default_dose_amount, p_default_dose_unit, p_default_doses_per_day, p_default_dose_timing,
      p_sort_order, p_is_active
    )
    RETURNING id INTO v_id;

    v_action := 'create';
  END IF;

  -- Upsert translations if provided
  IF p_translations IS NOT NULL AND p_code IS NOT NULL THEN
    FOR v_locale IN SELECT jsonb_object_keys(p_translations) LOOP
      v_trans := p_translations -> v_locale;

      -- Name translation
      IF v_trans ? 'name' THEN
        INSERT INTO translations (locale, namespace, key, value, updated_at)
        VALUES (v_locale, 'product_catalog', p_code || '.name', v_trans->>'name', now())
        ON CONFLICT (locale, namespace, key)
        DO UPDATE SET value = EXCLUDED.value, updated_at = now();
      END IF;

      -- Description translation
      IF v_trans ? 'description' THEN
        INSERT INTO translations (locale, namespace, key, value, updated_at)
        VALUES (v_locale, 'product_catalog', p_code || '.description', v_trans->>'description', now())
        ON CONFLICT (locale, namespace, key)
        DO UPDATE SET value = EXCLUDED.value, updated_at = now();
      END IF;
    END LOOP;
  END IF;

  -- Audit
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'CATALOG_' || upper(v_action),
    jsonb_build_object(
      'area', 'product_catalog',
      'severity', 'info',
      'entity_type', 'product_catalog',
      'entity_id', v_id,
      'code', p_code
    )
  );

  RETURN v_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.upsert_product_catalog_admin(uuid, text, text, text, text, numeric, text, integer, text[][], integer, boolean, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.upsert_product_catalog_admin(uuid, text, text, text, text, numeric, text, integer, text[][], integer, boolean, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.upsert_product_catalog_admin(uuid, text, text, text, text, numeric, text, integer, text[][], integer, boolean, jsonb) TO service_role;


