-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_translations.sql
-- -----------------------------------------------------------------------------

-- Function: public.upsert_translations
-- Arguments: p_translations jsonb
-- Security: service_role nebo admin bez omezení; staff jen obsahové namespacy
--           (web/news/pages/extranet) — viz rozvahu v těle funkce.
-- Extracted: 2026-01-08T18:28:34+01:00

CREATE OR REPLACE FUNCTION public.upsert_translations(p_translations jsonb)
 RETURNS TABLE(id uuid, key text, locale text, value text, namespace text, created_at timestamptz, updated_at timestamptz)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
    item JSONB;
    v_keys TEXT[];
    -- Boot-time /seed-default ingests a design folder's i18n.json as service_role
    -- (sub-less system runner, auth.uid() NULL). Admit it alongside admins; the
    -- translation admin UI path is unchanged.
    v_is_service boolean := (current_setting('request.jwt.claims', true)::jsonb->>'role') = 'service_role';
    v_is_admin boolean;
    v_cizi_namespace text;
    -- ⛔ OBSAHOVÉ NAMESPACY — jen tyhle smí zapisovat `staff` (2026-09-21).
    --
    -- Naměřená asymetrie: článek novinek smí vytvořit i upravit admin NEBO staff
    -- (policy „Admin/staff can manage news", USING is_admin_or_staff()), ale
    -- TEXTY toho článku šly zapsat jen adminovi. Editor plátna proto staffovi
    -- uložil článek a překlady zahodil — a SPA to umí jen ohlásit hláškou
    -- (CanvasEditor, builder.status.translationsDenied). Kdo smí obsah napsat,
    -- musí smět zapsat i jeho texty, jinak je ta role nefunkční.
    --
    -- Rozšíření je ÚZKÉ ZÁMĚRNĚ: `translations` nese i texty UI celé platformy
    -- (namespace `common`, `notifications`, …). Staff dostává jen namespacy
    -- obsahu, který smí spravovat — web, novinky, stránky, extranet. Všechno
    -- ostatní zůstává adminovi; neznámý namespace se odmítne, nedovolí.
    v_obsahove_namespacy text[] := ARRAY['web', 'news', 'pages', 'extranet'];
BEGIN
    v_is_admin := public.has_role(auth.uid(), 'admin');

    IF NOT (v_is_service OR v_is_admin) THEN
        IF NOT public.is_admin_or_staff(auth.uid()) THEN
            RAISE EXCEPTION 'Access denied: admin role required';
        END IF;

        SELECT COALESCE(prvek->>'namespace', 'questionnaires')
          INTO v_cizi_namespace
          FROM jsonb_array_elements(p_translations) AS prvek
         WHERE COALESCE(prvek->>'namespace', 'questionnaires') <> ALL (v_obsahove_namespacy)
         LIMIT 1;

        IF v_cizi_namespace IS NOT NULL THEN
            RAISE EXCEPTION 'Access denied: role staff may write only content namespaces (%), got %',
                array_to_string(v_obsahove_namespacy, ', '), v_cizi_namespace;
        END IF;
    END IF;

    v_keys := ARRAY[]::TEXT[];

    FOR item IN SELECT * FROM jsonb_array_elements(p_translations)
    LOOP
        v_keys := array_append(v_keys, item->>'key');
        
        INSERT INTO public.translations (key, locale, value, namespace, updated_at)
        VALUES (
            item->>'key',
            item->>'locale', 
            item->>'value',
            COALESCE(item->>'namespace', 'questionnaires'),
            NOW()
        )
        ON CONFLICT (key, locale, namespace) 
        DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();
    END LOOP;

    RETURN QUERY SELECT t.id, t.key, t.locale, t.value, t.namespace, t.created_at, t.updated_at
    FROM public.translations t
    WHERE t.key = ANY(v_keys);
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.upsert_translations(p_translations jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.upsert_translations(p_translations jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/news_article_apply_texts.sql
-- -----------------------------------------------------------------------------

-- Function: public.news_article_apply_texts
-- Description: Zapíše texty článku ({locale: {title, excerpt, content}}) do
--              `translations` pod klíče článku — přes `upsert_translations`,
--              aby platila TÁŽ autorizace (admin bez omezení, staff jen obsahové
--              namespacy) a týž zápis jako z administrace. Prázdný text se
--              přeskočí, ne smaže (stejně jako to dělal klient).
-- Security: SECURITY DEFINER; autorizaci nese upsert_translations (auth.uid()
--           je pořád volající). Volá se z publish/restore/draft RPC novinek.
-- Created: 2026-09-24

CREATE OR REPLACE FUNCTION public.news_article_apply_texts(p_article_id uuid, p_texts jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_a record;
  v_pole jsonb;
BEGIN
  IF NOT (public.is_admin_or_staff() OR public.is_service_role()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF p_texts IS NULL OR jsonb_typeof(p_texts) <> 'object' THEN
    RETURN;
  END IF;

  SELECT title_key, excerpt_key, content_key INTO v_a
  FROM public.news_articles WHERE id = p_article_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Article not found';
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
           'key', k.klic, 'locale', l.locale, 'namespace', 'news', 'value', l.texty ->> k.pole))
    INTO v_pole
  FROM jsonb_each(p_texts) AS l(locale, texty)
  CROSS JOIN LATERAL (VALUES ('title', v_a.title_key), ('excerpt', v_a.excerpt_key), ('content', v_a.content_key)) AS k(pole, klic)
  WHERE k.klic IS NOT NULL
    AND jsonb_typeof(l.texty) = 'object'
    AND COALESCE(l.texty ->> k.pole, '') <> '';

  IF v_pole IS NOT NULL AND jsonb_array_length(v_pole) > 0 THEN
    PERFORM public.upsert_translations(v_pole);
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.news_article_apply_texts(uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.news_article_apply_texts(uuid, jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/publish_news_article_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.publish_news_article_admin
-- Description: Zveřejní článek: koncept (je-li) + to, co přišlo v parametrech,
--              se přelije do news_articles, article dostane is_published = true
--              (published_at se nastaví jen poprvé — opakované zveřejnění
--              nemění pořadí na webu), koncept se smaže a do historie jde snímek
--              kind = 'published'. Vrací nové razítko (news_article_edit_stamp).
--
--              Parametry plátna/hlavičky jsou pro editor, který zveřejňuje
--              rovnou z rozpracovaného stavu („Zveřejnit"); NULL = vezmi koncept,
--              a není-li, živý stav.
-- Security: SECURITY DEFINER; admin/staff NEBO service_role (seed).
-- Created: 2026-09-24

CREATE OR REPLACE FUNCTION public.publish_news_article_admin(
  p_article_id uuid,
  p_canvas_css text DEFAULT NULL,
  p_canvas_data jsonb DEFAULT NULL,
  p_canvas_html text DEFAULT NULL,
  p_expected_stamp timestamptz DEFAULT NULL,
  p_fields jsonb DEFAULT NULL
)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_a public.news_articles%ROWTYPE;
  v_d_canvas_data jsonb;
  v_d_canvas_html text;
  v_d_canvas_css text;
  v_d_fields jsonb;
  v_d_updated timestamptz;
  v_stamp timestamptz;
  v_fields jsonb;
  v_new timestamptz;
BEGIN
  IF NOT (public.is_admin_or_staff() OR public.is_service_role()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  PERFORM public.news_article_check_fields(p_fields);

  SELECT * INTO v_a FROM public.news_articles WHERE id = p_article_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Article not found';
  END IF;

  SELECT d.canvas_data, d.canvas_html, d.canvas_css, d.fields, d.updated_at
    INTO v_d_canvas_data, v_d_canvas_html, v_d_canvas_css, v_d_fields, v_d_updated
  FROM public.news_article_versions d
  WHERE d.article_id = p_article_id AND d.kind = 'draft'
  FOR UPDATE;

  v_stamp := GREATEST(v_a.updated_at, COALESCE(v_d_updated, v_a.updated_at));
  IF p_expected_stamp IS NOT NULL AND v_stamp <> p_expected_stamp THEN
    RAISE EXCEPTION 'Article changed since it was loaded (stamp % vs expected %)', v_stamp, p_expected_stamp
      USING ERRCODE = 'PT409';
  END IF;

  v_fields := COALESCE(v_d_fields, '{}'::jsonb) || COALESCE(p_fields, '{}'::jsonb);

  UPDATE public.news_articles SET
    canvas_data   = COALESCE(p_canvas_data, v_d_canvas_data, news_articles.canvas_data),
    canvas_html   = COALESCE(p_canvas_html, v_d_canvas_html, news_articles.canvas_html),
    canvas_css    = COALESCE(p_canvas_css,  v_d_canvas_css,  news_articles.canvas_css),
    image_url     = CASE WHEN v_fields ? 'image_url' THEN NULLIF(v_fields ->> 'image_url', '') ELSE news_articles.image_url END,
    image_focus_x = COALESCE((v_fields ->> 'image_focus_x')::numeric, news_articles.image_focus_x),
    image_focus_y = COALESCE((v_fields ->> 'image_focus_y')::numeric, news_articles.image_focus_y),
    image_zoom    = COALESCE((v_fields ->> 'image_zoom')::numeric, news_articles.image_zoom),
    tags          = CASE WHEN v_fields ? 'tags'
                         THEN (SELECT COALESCE(array_agg(x.v), '{}'::text[]) FROM jsonb_array_elements_text(v_fields -> 'tags') AS x(v))
                         ELSE news_articles.tags END,
    is_published  = true,
    published_at  = COALESCE(news_articles.published_at, now()),
    updated_at    = now()
  WHERE news_articles.id = p_article_id
  RETURNING news_articles.updated_at INTO v_new;

  IF v_fields ? 'texts' THEN
    PERFORM public.news_article_apply_texts(p_article_id, v_fields -> 'texts');
  END IF;

  DELETE FROM public.news_article_versions d
  WHERE d.article_id = p_article_id AND d.kind = 'draft';

  PERFORM public.create_news_article_version(p_article_id, 'published', NULL);

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'NEWS_PUBLISH',
          jsonb_build_object('area', 'content', 'severity', 'info', 'entity_type', 'news_article',
                             'entity_id', p_article_id::text, 'had_draft', v_d_updated IS NOT NULL));
  RETURN v_new;
END;
$$;

REVOKE ALL ON FUNCTION public.publish_news_article_admin(uuid, text, jsonb, text, timestamptz, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.publish_news_article_admin(uuid, text, jsonb, text, timestamptz, jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/save_news_article_draft_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.save_news_article_draft_admin
-- Description: JEDINÁ cesta, kudy jde OBSAH článku (plátno, obrázek, ohnisko,
--              přiblížení, štítky, texty) z editoru do databáze. Kam přesně,
--              rozhoduje server, ne klient:
--                • článek NENÍ zveřejněný → zapíše se rovnou do news_articles
--                  (není vidět, koncept by byl jen zdvojení);
--                • článek JE zveřejněný → zapíše se do KONCEPTU (řádek
--                  news_article_versions kind='draft'); web dál servíruje
--                  poslední zveřejněný stav, dokud nepřijde publish_news_article_admin.
--
--              Částečný zápis: NULL v p_canvas_* nebo chybějící klíč v p_fields
--              znamená „nech, co je" (v konceptu, jinak v živém stavu). Koncept
--              se při prvním zápisu ZALOŽÍ ZE ŽIVÉHO stavu, takže je vždy úplný
--              snímek, ne rozdíl.
--
--              Souběh: `p_expected_stamp` = razítko, které klient četl
--              (news_article_edit_stamp). Nesedí-li, zápis skončí 409 (PT409);
--              NULL = bez kontroly (importy, obnova verze). Vrací nové razítko.
--
-- ⛔ Naměřeno 2026-09-24: autosave plátna (5 s po změně) u zveřejněného článku
--    šel přímo do canvas_html, které čte veřejná stránka. Tahle funkce je oprava.
-- Security: SECURITY DEFINER; admin/staff NEBO service_role.
-- Created: 2026-09-24

CREATE OR REPLACE FUNCTION public.save_news_article_draft_admin(
  p_article_id uuid,
  p_canvas_css text DEFAULT NULL,
  p_canvas_data jsonb DEFAULT NULL,
  p_canvas_html text DEFAULT NULL,
  p_expected_stamp timestamptz DEFAULT NULL,
  p_fields jsonb DEFAULT NULL
)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_a public.news_articles%ROWTYPE;
  v_d_canvas_data jsonb;
  v_d_canvas_html text;
  v_d_canvas_css text;
  v_d_fields jsonb;
  v_d_updated timestamptz;
  v_stamp timestamptz;
  v_fields jsonb;
  v_new timestamptz;
BEGIN
  IF NOT (public.is_admin_or_staff() OR public.is_service_role()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  PERFORM public.news_article_check_fields(p_fields);

  SELECT * INTO v_a FROM public.news_articles WHERE id = p_article_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Article not found';
  END IF;

  SELECT d.canvas_data, d.canvas_html, d.canvas_css, d.fields, d.updated_at
    INTO v_d_canvas_data, v_d_canvas_html, v_d_canvas_css, v_d_fields, v_d_updated
  FROM public.news_article_versions d
  WHERE d.article_id = p_article_id AND d.kind = 'draft'
  FOR UPDATE;

  v_stamp := GREATEST(v_a.updated_at, COALESCE(v_d_updated, v_a.updated_at));
  IF p_expected_stamp IS NOT NULL AND v_stamp <> p_expected_stamp THEN
    RAISE EXCEPTION 'Article changed since it was loaded (stamp % vs expected %)', v_stamp, p_expected_stamp
      USING ERRCODE = 'PT409';
  END IF;

  IF NOT v_a.is_published THEN
    -- Nezveřejněný článek: živý zápis, nikdo ho nevidí.
    UPDATE public.news_articles SET
      canvas_data   = COALESCE(p_canvas_data, news_articles.canvas_data),
      canvas_html   = COALESCE(p_canvas_html, news_articles.canvas_html),
      canvas_css    = COALESCE(p_canvas_css,  news_articles.canvas_css),
      image_url     = CASE WHEN p_fields ? 'image_url' THEN NULLIF(p_fields ->> 'image_url', '') ELSE news_articles.image_url END,
      image_focus_x = COALESCE((p_fields ->> 'image_focus_x')::numeric, news_articles.image_focus_x),
      image_focus_y = COALESCE((p_fields ->> 'image_focus_y')::numeric, news_articles.image_focus_y),
      image_zoom    = COALESCE((p_fields ->> 'image_zoom')::numeric, news_articles.image_zoom),
      tags          = CASE WHEN p_fields ? 'tags'
                           THEN (SELECT COALESCE(array_agg(x.v), '{}'::text[]) FROM jsonb_array_elements_text(p_fields -> 'tags') AS x(v))
                           ELSE news_articles.tags END,
      updated_at    = now()
    WHERE news_articles.id = p_article_id
    RETURNING news_articles.updated_at INTO v_new;

    IF p_fields ? 'texts' THEN
      PERFORM public.news_article_apply_texts(p_article_id, p_fields -> 'texts');
    END IF;

    INSERT INTO public.audit_journal (user_id, action, metadata)
    VALUES (auth.uid(), 'NEWS_UPDATE',
            jsonb_build_object('area', 'content', 'severity', 'info', 'entity_type', 'news_article',
                               'entity_id', p_article_id::text, 'target', 'live'));
    RETURN v_new;
  END IF;

  -- Zveřejněný článek: koncept. Založí se ze živého stavu, pak se přepíše tím, co přišlo.
  v_fields := COALESCE(v_d_fields, public.news_article_live_fields(p_article_id)) || COALESCE(p_fields, '{}'::jsonb);

  INSERT INTO public.news_article_versions (
    article_id, version_number, kind, canvas_data, canvas_html, canvas_css, fields, created_by, updated_at
  ) VALUES (
    p_article_id, 0, 'draft',
    COALESCE(p_canvas_data, v_d_canvas_data, v_a.canvas_data),
    COALESCE(p_canvas_html, v_d_canvas_html, v_a.canvas_html),
    COALESCE(p_canvas_css,  v_d_canvas_css,  v_a.canvas_css),
    v_fields, auth.uid(), now()
  )
  ON CONFLICT (article_id) WHERE kind = 'draft' DO UPDATE SET
    canvas_data = EXCLUDED.canvas_data,
    canvas_html = EXCLUDED.canvas_html,
    canvas_css  = EXCLUDED.canvas_css,
    fields      = EXCLUDED.fields,
    updated_at  = now()
  RETURNING news_article_versions.updated_at INTO v_new;

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'NEWS_DRAFT_SAVE',
          jsonb_build_object('area', 'content', 'severity', 'info', 'entity_type', 'news_article',
                             'entity_id', p_article_id::text, 'target', 'draft'));
  RETURN v_new;
END;
$$;

REVOKE ALL ON FUNCTION public.save_news_article_draft_admin(uuid, text, jsonb, text, timestamptz, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_news_article_draft_admin(uuid, text, jsonb, text, timestamptz, jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/restore_news_article_version.sql
-- -----------------------------------------------------------------------------

-- Function: public.restore_news_article_version
-- Description: Vrátí článek k vybrané verzi — kam, rozhoduje stav článku:
--                • zveřejněný → verze se nahraje do KONCEPTU (web se nezmění,
--                  dokud autor nezveřejní; obnova je tedy vratná);
--                • nezveřejněný → do živého stavu, ale nejdřív se uloží snímek
--                  'auto: before restore', aby šlo i obnovu vrátit.
--              Obě cesty jdou přes save_news_article_draft_admin — jeden zápis
--              hlavičky, textů i plátna. Vrací nové razítko.
--
--              Verze bez plátna (článek z importu) plátno nemění: COALESCE
--              v zápisu bere „NULL = nech" — historie takový článek nemá čím
--              přepsat a mazat plátno obnovou by bylo horší.
-- Security: SECURITY DEFINER, admin/staff.
-- Created: 2026-09-24 (zrcadlí restore_web_page_version)

CREATE OR REPLACE FUNCTION public.restore_news_article_version(
  p_article_id uuid,
  p_version_id uuid
)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_v public.news_article_versions%ROWTYPE;
  v_published boolean;
  v_new timestamptz;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT * INTO v_v FROM public.news_article_versions v
  WHERE v.id = p_version_id AND v.article_id = p_article_id AND v.kind <> 'draft';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Version not found';
  END IF;

  SELECT a.is_published INTO v_published FROM public.news_articles a WHERE a.id = p_article_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Article not found';
  END IF;

  IF NOT v_published THEN
    PERFORM public.create_news_article_version(p_article_id, 'auto', 'auto: before restore');
  END IF;

  v_new := public.save_news_article_draft_admin(
    p_article_id, v_v.canvas_css, v_v.canvas_data, v_v.canvas_html, NULL, v_v.fields
  );

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'NEWS_VERSION_RESTORE',
          jsonb_build_object('area', 'content', 'severity', 'warning', 'entity_type', 'news_article_version',
                             'entity_id', p_version_id::text, 'article_id', p_article_id::text,
                             'target', CASE WHEN v_published THEN 'draft' ELSE 'live' END));
  RETURN v_new;
END;
$$;

REVOKE ALL ON FUNCTION public.restore_news_article_version(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.restore_news_article_version(uuid, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/update_news_article_admin.sql
-- -----------------------------------------------------------------------------

-- Source of truth for update_news_article_admin
-- Admin updates the STRUCTURAL fields of a news article (slug, pořadí, zveřejnění,
-- klíče textů) with audit logging.
--
-- 2026-09-24: OBSAH (plátno, obrázek, ohnisko, přiblížení, štítky, texty) jde přes
-- save_news_article_draft_admin — ta rozhodne, zda do konceptu (zveřejněný článek),
-- nebo živě. `p_image_url` tu zůstává pro volající z doby před 2026-09-24 a píše
-- ŽIVĚ; nový klient obrázek posílá v `p_fields` konceptu.
--   • p_is_published = true u nezveřejněného článku = ZVEŘEJNĚNÍ → jde přes
--     publish_news_article_admin (přelije koncept, udělá snímek 'published').
--   • p_is_published = false u zveřejněného článku = stažení z webu; rozdělaný
--     koncept se přitom přelije do (teď neviditelného) živého stavu, aby se
--     práce neztratila, a koncept zanikne.
--   • p_expected_stamp = razítko z načtení (news_article_edit_stamp); nesedí-li,
--     zápis skončí 409 (PT409) místo tichého přepsání cizí práce.
-- Vrací nové razítko. Nový parametr + návratový typ = nový podpis, proto DROP.

DROP FUNCTION IF EXISTS public.update_news_article_admin(uuid, text, text, text, boolean, timestamptz, text, integer, text);

CREATE OR REPLACE FUNCTION public.update_news_article_admin(
  p_id uuid,
  p_content_key text DEFAULT NULL,
  p_excerpt_key text DEFAULT NULL,
  p_expected_stamp timestamptz DEFAULT NULL,
  p_image_url text DEFAULT NULL,
  p_is_published boolean DEFAULT NULL,
  p_published_at timestamptz DEFAULT NULL,
  p_slug text DEFAULT NULL,
  p_sort_order integer DEFAULT NULL,
  p_title_key text DEFAULT NULL
)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_published boolean;
  v_stamp timestamptz;
  v_d public.news_article_versions%ROWTYPE;
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT a.is_published INTO v_published FROM public.news_articles a WHERE a.id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Article not found';
  END IF;

  v_stamp := public.news_article_edit_stamp(p_id);
  IF p_expected_stamp IS NOT NULL AND v_stamp <> p_expected_stamp THEN
    RAISE EXCEPTION 'Article changed since it was loaded (stamp % vs expected %)', v_stamp, p_expected_stamp
      USING ERRCODE = 'PT409';
  END IF;

  IF p_is_published = true AND NOT v_published THEN
    PERFORM public.publish_news_article_admin(p_id, NULL, NULL, NULL, NULL, NULL);
  END IF;

  UPDATE public.news_articles SET
    content_key  = COALESCE(p_content_key, content_key),
    excerpt_key  = COALESCE(p_excerpt_key, excerpt_key),
    image_url    = COALESCE(p_image_url, image_url),
    is_published = COALESCE(p_is_published, is_published),
    published_at = CASE
                     WHEN p_is_published = true AND published_at IS NULL
                       THEN COALESCE(p_published_at, now())
                     WHEN p_published_at IS NOT NULL
                       THEN p_published_at
                     ELSE published_at
                   END,
    slug         = COALESCE(p_slug, slug),
    sort_order   = COALESCE(p_sort_order, sort_order),
    title_key    = COALESCE(p_title_key, title_key),
    updated_at   = now()
  WHERE id = p_id;

  -- Stažení z webu: rozdělaný koncept se přelije do živého (teď neviditelného) stavu.
  IF p_is_published = false AND v_published THEN
    SELECT * INTO v_d FROM public.news_article_versions d
    WHERE d.article_id = p_id AND d.kind = 'draft' FOR UPDATE;
    IF FOUND THEN
      DELETE FROM public.news_article_versions d WHERE d.id = v_d.id;
      PERFORM public.save_news_article_draft_admin(p_id, v_d.canvas_css, v_d.canvas_data, v_d.canvas_html, NULL, v_d.fields);
    END IF;
  END IF;

  -- Audit
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'NEWS_UPDATE',
    jsonb_build_object(
      'area', 'content',
      'severity', 'info',
      'entity_type', 'news_article',
      'entity_id', p_id
    )
  );

  RETURN public.news_article_edit_stamp(p_id);
END;
$$;

REVOKE ALL ON FUNCTION public.update_news_article_admin(uuid, text, text, timestamptz, text, boolean, timestamptz, text, integer, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_news_article_admin(uuid, text, text, timestamptz, text, boolean, timestamptz, text, integer, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_user_session.sql
-- -----------------------------------------------------------------------------

-- Function: public.upsert_user_session
-- Arguments: p_session_id text, p_user_agent text, p_ip_address text
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:28:35+01:00

CREATE OR REPLACE FUNCTION public.upsert_user_session(p_session_id text, p_user_agent text, p_ip_address text DEFAULT NULL::text)
 RETURNS TABLE(id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO user_sessions (user_id, session_id, user_agent, ip_address, last_active_at)
  VALUES (auth.uid(), p_session_id, p_user_agent, p_ip_address, now())
  ON CONFLICT (user_id, session_id) DO UPDATE SET
    last_active_at = now(),
    user_agent = EXCLUDED.user_agent,
    ip_address = COALESCE(EXCLUDED.ip_address, user_sessions.ip_address)
  RETURNING user_sessions.id INTO v_id;

  RETURN QUERY SELECT v_id;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.upsert_user_session(p_session_id text, p_user_agent text, p_ip_address text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.upsert_user_session(p_session_id text, p_user_agent text, p_ip_address text) TO authenticated;


