-- -----------------------------------------------------------------------------

/**
 * upsert_vulnerability_finding — Insert or update a vulnerability finding.
 *
 * Called by vulnerability-aggregator edge function (service_role) during scans.
 * Uses ON CONFLICT on (project_slug, package_name, title) to upsert.
 *
 * @param p_first_detected_at timestamptz — When the finding was first detected
 * @param p_fixed_in text — Version that fixes the vulnerability (nullable)
 * @param p_is_resolved boolean — Whether the vulnerability is resolved
 * @param p_package_name text — Package name
 * @param p_project_slug text — Project slug
 * @param p_severity text — Severity level
 * @param p_source text — Source of the finding (e.g., security-headers, ssl-check)
 * @param p_title text — Vulnerability title
 * @param p_url text — Reference URL (nullable)
 */
CREATE OR REPLACE FUNCTION public.upsert_vulnerability_finding(
  p_first_detected_at timestamptz DEFAULT now(),
  p_fixed_in text DEFAULT NULL,
  p_is_resolved boolean DEFAULT false,
  p_package_name text DEFAULT NULL,
  p_project_slug text DEFAULT NULL,
  p_severity text DEFAULT 'info',
  p_source text DEFAULT 'npm_audit',
  p_title text DEFAULT NULL,
  p_url text DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY INVOKER
AS $$
BEGIN
  IF p_project_slug IS NULL OR p_package_name IS NULL OR p_title IS NULL THEN
    RAISE EXCEPTION 'p_project_slug, p_package_name, and p_title are required';
  END IF;

  INSERT INTO public.project_vulnerabilities (
    first_detected_at,
    fixed_in,
    is_resolved,
    package_name,
    project_slug,
    severity,
    source,
    title,
    url
  ) VALUES (
    p_first_detected_at,
    p_fixed_in,
    p_is_resolved,
    p_package_name,
    p_project_slug,
    p_severity,
    p_source,
    p_title,
    p_url
  )
  ON CONFLICT (project_slug, package_name, title)
  DO UPDATE SET
    first_detected_at = EXCLUDED.first_detected_at,
    fixed_in = EXCLUDED.fixed_in,
    is_resolved = EXCLUDED.is_resolved,
    severity = EXCLUDED.severity,
    source = EXCLUDED.source,
    url = EXCLUDED.url,
    updated_at = now();
END;
$$;

REVOKE ALL ON FUNCTION public.upsert_vulnerability_finding(
  timestamptz, text, boolean, text, text, text, text, text, text
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.upsert_vulnerability_finding(
  timestamptz, text, boolean, text, text, text, text, text, text
) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_wearable_connection.sql
-- -----------------------------------------------------------------------------

-- Function: upsert_wearable_connection
-- Purpose: Create or update a wearable device connection for the current user
-- Access: authenticated
-- Security: SECURITY DEFINER with audit logging

CREATE OR REPLACE FUNCTION public.upsert_wearable_connection(
  p_connection_status text DEFAULT 'connected',
  p_device_model text DEFAULT NULL,
  p_device_name text DEFAULT NULL,
  p_device_type text DEFAULT NULL,
  p_last_sync_batch_id uuid DEFAULT NULL,
  p_metadata jsonb DEFAULT '{}'::jsonb,
  p_permissions_granted text[] DEFAULT '{}',
  p_platform text DEFAULT 'ios'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id UUID;
  v_connection_id UUID;
  v_is_new BOOLEAN := false;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Validate inputs
  IF p_device_type IS NULL OR p_device_type = '' THEN
    RAISE EXCEPTION 'device_type is required';
  END IF;

  IF p_platform NOT IN ('ios', 'android') THEN
    RAISE EXCEPTION 'platform must be ios or android';
  END IF;

  IF p_connection_status NOT IN ('connected', 'disconnected', 'paused') THEN
    RAISE EXCEPTION USING MESSAGE = format('Invalid connection_status: %s', p_connection_status), ERRCODE = '22023';
  END IF;

  -- Upsert: insert or update based on unique constraint (user_id, device_type, platform)
  INSERT INTO member_wearable_connections (
    user_id,
    device_type,
    device_name,
    device_model,
    platform,
    connection_status,
    permissions_granted,
    last_sync_batch_id,
    last_sync_at,
    metadata,
    disconnected_at
  )
  VALUES (
    v_user_id,
    p_device_type,
    p_device_name,
    p_device_model,
    p_platform,
    p_connection_status,
    p_permissions_granted,
    p_last_sync_batch_id,
    CASE WHEN p_last_sync_batch_id IS NOT NULL THEN now() ELSE NULL END,
    p_metadata,
    CASE WHEN p_connection_status = 'disconnected' THEN now() ELSE NULL END
  )
  ON CONFLICT (user_id, device_type, platform)
  DO UPDATE SET
    device_name = COALESCE(EXCLUDED.device_name, member_wearable_connections.device_name),
    device_model = COALESCE(EXCLUDED.device_model, member_wearable_connections.device_model),
    connection_status = EXCLUDED.connection_status,
    permissions_granted = EXCLUDED.permissions_granted,
    last_sync_batch_id = COALESCE(EXCLUDED.last_sync_batch_id, member_wearable_connections.last_sync_batch_id),
    last_sync_at = CASE
      WHEN EXCLUDED.last_sync_batch_id IS NOT NULL THEN now()
      ELSE member_wearable_connections.last_sync_at
    END,
    sync_count = CASE
      WHEN EXCLUDED.last_sync_batch_id IS NOT NULL THEN member_wearable_connections.sync_count + 1
      ELSE member_wearable_connections.sync_count
    END,
    metadata = member_wearable_connections.metadata || EXCLUDED.metadata,
    disconnected_at = CASE
      WHEN EXCLUDED.connection_status = 'disconnected' THEN now()
      ELSE NULL
    END,
    updated_at = now()
  RETURNING id, (xmax = 0) INTO v_connection_id, v_is_new;

  -- Audit log (no sensitive data)
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    CASE WHEN v_is_new THEN 'WEARABLE_CONNECTED' ELSE 'WEARABLE_UPDATED' END,
    jsonb_build_object(
      'area', 'wearable',
      'severity', 'info',
      'connection_id', v_connection_id,
      'device_type', p_device_type,
      'platform', p_platform,
      'connection_status', p_connection_status
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'connection_id', v_connection_id,
    'is_new', v_is_new
  );
END;
$$;

REVOKE ALL ON FUNCTION public.upsert_wearable_connection(text, text, text, text, uuid, jsonb, text[][], text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.upsert_wearable_connection(text, text, text, text, uuid, jsonb, text[][], text) TO authenticated;

COMMENT ON FUNCTION public.upsert_wearable_connection(text, text, text, text, uuid, jsonb, text[][], text) IS
  'Create or update a wearable device connection for the current user. Supports multi-device per user.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_web_push_subscription.sql
-- -----------------------------------------------------------------------------

-- Function: public.upsert_web_push_subscription
-- Arguments: p_subscription jsonb
-- Description: Upsert current browser push subscription for authenticated user.
-- Security: SECURITY DEFINER (uses auth.uid()).
-- ⛔ VLASTNICTVÍ ENDPOINTU (2026-09-29): `endpoint` je globální klíč. Dřív
--    `ON CONFLICT (endpoint) DO UPDATE SET user_id = EXCLUDED.user_id` — kdokoli
--    přihlášený, kdo znal cizí endpoint, ho převzal (notifikace oběti šly jemu
--    zpět do prohlížeče oběti pod jeho účtem, oběť svoje přestala dostávat).
--    Převzít cizí endpoint smí jen DRŽITEL téže subscription: shodné `p256dh`
--    a `auth` zná jen prohlížeč, který ji vytvořil (legitimní případ: na témž
--    prohlížeči se odhlásí A a přihlásí B). Samotný endpoint → 42501. Vlastní
--    řádek se aktualizuje jako dřív. Stráž je dvojí: kontrola předem (čitelná
--    chyba) a podmínka v DO UPDATE (atomicky).

CREATE OR REPLACE FUNCTION public.upsert_web_push_subscription(
  p_subscription jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_id uuid;
  v_endpoint text;
  v_p256dh text;
  v_auth text;
  v_expiration_time timestamptz;
  v_user_agent text;
  v_locale text;
  v_timezone text;
  v_vlastnik uuid;
  v_drzitel boolean;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_endpoint := NULLIF(trim(p_subscription ->> 'endpoint'), '');
  v_p256dh := NULLIF(trim(p_subscription #>> '{keys,p256dh}'), '');
  v_auth := NULLIF(trim(p_subscription #>> '{keys,auth}'), '');
  v_user_agent := NULLIF(trim(p_subscription ->> 'userAgent'), '');
  v_locale := NULLIF(trim(p_subscription ->> 'locale'), '');
  v_timezone := NULLIF(trim(p_subscription ->> 'timezone'), '');
  v_expiration_time := NULL;

  IF v_endpoint IS NULL OR v_p256dh IS NULL OR v_auth IS NULL THEN
    RAISE EXCEPTION 'Invalid subscription payload' USING ERRCODE = '22023';
  END IF;

  IF p_subscription ? 'expirationTime' THEN
    BEGIN
      IF jsonb_typeof(p_subscription -> 'expirationTime') = 'number' THEN
        v_expiration_time := to_timestamp((p_subscription ->> 'expirationTime')::double precision / 1000.0);
      ELSIF jsonb_typeof(p_subscription -> 'expirationTime') = 'string'
        AND NULLIF(trim(p_subscription ->> 'expirationTime'), '') IS NOT NULL THEN
        v_expiration_time := to_timestamp((p_subscription ->> 'expirationTime')::double precision / 1000.0);
      END IF;
    EXCEPTION
      WHEN others THEN
        v_expiration_time := NULL;
    END;
  END IF;

  SELECT w.user_id, (w.p256dh = v_p256dh AND w.auth = v_auth)
    INTO v_vlastnik, v_drzitel
    FROM public.web_push_subscriptions w
   WHERE w.endpoint = v_endpoint
   FOR UPDATE;
  IF FOUND AND v_vlastnik IS DISTINCT FROM v_user_id AND NOT v_drzitel THEN
    RAISE EXCEPTION 'push endpoint belongs to another user' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.web_push_subscriptions (
    user_id,
    endpoint,
    p256dh,
    auth,
    expiration_time,
    user_agent,
    locale,
    timezone,
    is_active,
    last_seen_at,
    last_error_at,
    last_error_reason,
    updated_at
  )
  VALUES (
    v_user_id,
    v_endpoint,
    v_p256dh,
    v_auth,
    v_expiration_time,
    v_user_agent,
    v_locale,
    v_timezone,
    true,
    now(),
    NULL,
    NULL,
    now()
  )
  ON CONFLICT (endpoint) DO UPDATE SET
    user_id = EXCLUDED.user_id,
    p256dh = EXCLUDED.p256dh,
    auth = EXCLUDED.auth,
    expiration_time = EXCLUDED.expiration_time,
    user_agent = COALESCE(EXCLUDED.user_agent, public.web_push_subscriptions.user_agent),
    locale = COALESCE(EXCLUDED.locale, public.web_push_subscriptions.locale),
    timezone = COALESCE(EXCLUDED.timezone, public.web_push_subscriptions.timezone),
    is_active = true,
    last_seen_at = now(),
    last_error_at = NULL,
    last_error_reason = NULL,
    updated_at = now()
  WHERE public.web_push_subscriptions.user_id = EXCLUDED.user_id
     OR (public.web_push_subscriptions.p256dh = EXCLUDED.p256dh
         AND public.web_push_subscriptions.auth = EXCLUDED.auth)
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    -- Souběh: řádek změnil vlastníka mezi kontrolou a zápisem — nic se nepřevzalo.
    RAISE EXCEPTION 'push endpoint belongs to another user' USING ERRCODE = '42501';
  END IF;

  RETURN v_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.upsert_web_push_subscription(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.upsert_web_push_subscription(jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/use_invitation.sql
-- -----------------------------------------------------------------------------

-- Function: public.use_invitation
-- Arguments: p_code text
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:28:35+01:00

CREATE OR REPLACE FUNCTION public.use_invitation(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invitation RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  
  SELECT * INTO v_invitation FROM invitations
  WHERE code = p_code AND is_active = true
    AND (expires_at IS NULL OR expires_at > now())
    AND (max_uses IS NULL OR used_count < max_uses);
    
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid or expired invitation');
  END IF;
  
  UPDATE invitations SET used_count = used_count + 1 WHERE id = v_invitation.id;
  
  IF v_invitation.role IS NOT NULL THEN
    INSERT INTO user_roles (user_id, role)
    VALUES (auth.uid(), v_invitation.role::user_role)
    ON CONFLICT DO NOTHING;
  END IF;
  
  RETURN jsonb_build_object('success', true, 'study_id', v_invitation.study_id, 'role', v_invitation.role);
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.use_invitation(p_code text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.use_invitation(p_code text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/user_can_chat.sql
-- -----------------------------------------------------------------------------

-- Function: public.user_can_chat
-- Arguments: p_user_id uuid
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:28:35+01:00

CREATE OR REPLACE FUNCTION public.user_can_chat(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_has_registration BOOLEAN := false;
  v_has_membership BOOLEAN := false;
  v_uid uuid := auth.uid();
BEGIN
  -- ⛔ PREDIKÁT O TŘETÍ OSOBĚ JE ORÁKULUM (naměřeno 2026-09-19). Odpověď
  -- skládá dvě skutečnosti o účtu — aktivní registraci do studie a aktivní
  -- členství — a přihlášený je uměl zjistit pro libovolné uuid.
  --
  -- Odpovídá se jen o VOLAJÍCÍM; služba a správa na kohokoli. Změřeno, že to nic
  -- nerozbije: oba volající v repu (create_chat_conversation_audited,
  -- deliver_pending_news_to_chat) předávají `v_user_id := auth.uid()`.
  -- `false` = totéž co „nemůže chatovat", takže zamítnutí nic neprozradí.
  IF v_uid IS NULL OR p_user_id IS DISTINCT FROM v_uid THEN
    IF NOT (public.is_service_role() OR public.is_admin_or_staff()) THEN
      RETURN false;
    END IF;
  END IF;

  -- Check if user has any active study registration
  SELECT EXISTS (
    SELECT 1 FROM public.study_registrations 
    WHERE user_id = p_user_id 
    AND status IN ('active', 'completed')
  ) INTO v_has_registration;
  
  -- Check if user has active membership
  SELECT EXISTS (
    SELECT 1 FROM public.memberships 
    WHERE user_id = p_user_id 
    AND status = 'active'
  ) INTO v_has_membership;
  
  RETURN v_has_registration OR v_has_membership;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.user_can_chat(p_user_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.user_can_chat(p_user_id uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/deliver_pending_news_to_chat.sql
-- -----------------------------------------------------------------------------

-- Source of truth for deliver_pending_news_to_chat
-- Delivers unread published news articles to user's chat as assistant messages
-- with localized titles and excerpts, tracking delivery to avoid duplicates

CREATE OR REPLACE FUNCTION deliver_pending_news_to_chat()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id         uuid := auth.uid();
  v_locale          text;
  v_article         RECORD;
  v_conversation_id uuid;
  v_message_id      uuid;
  v_title           text;
  v_excerpt         text;
  v_msg_body        text;
  v_greeting        text;
  v_cta             text;
  v_delivered_count integer := 0;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Only deliver to users who can chat
  IF NOT public.user_can_chat(v_user_id) THEN
    RETURN 0;
  END IF;

  -- Get user's preferred language (terminal failover: en)
  SELECT COALESCE(p.preferred_language, 'en')
    INTO v_locale
    FROM public.profiles p
   WHERE p.id = v_user_id;

  IF v_locale IS NULL THEN
    v_locale := 'en';
  END IF;

  -- Prepare greeting/CTA per locale
  CASE v_locale
    WHEN 'cs' THEN
      v_greeting := 'Ahoj! Mám pro tebe novinku:';
      v_cta      := 'Chceš vědět víc? Klidně se ptej!';
    WHEN 'de' THEN
      v_greeting := 'Hallo! Ich habe Neuigkeiten für dich:';
      v_cta      := 'Möchtest du mehr erfahren? Frag einfach!';
    WHEN 'fr' THEN
      v_greeting := 'Salut ! J''ai des nouvelles pour toi :';
      v_cta      := 'Tu veux en savoir plus ? N''hésite pas à demander !';
    WHEN 'ru' THEN
      v_greeting := 'Привет! У меня для тебя новость:';
      v_cta      := 'Хочешь узнать больше? Спрашивай!';
    WHEN 'th' THEN
      v_greeting := 'สวัสดี! ฉันมีข่าวสำหรับคุณ:';
      v_cta      := 'อยากทราบเพิ่มเติมไหม? ถามฉันได้เลย!';
    ELSE
      v_greeting := 'Hi! I have news for you:';
      v_cta      := 'Want to know more? Feel free to ask!';
  END CASE;

  -- Iterate undelivered published articles
  FOR v_article IN
    SELECT na.id, na.title_key, na.excerpt_key, na.slug
      FROM public.news_articles na
     WHERE na.is_published = true
       AND na.published_at IS NOT NULL
       AND NOT EXISTS (
             SELECT 1 FROM public.news_article_deliveries nad
              WHERE nad.news_article_id = na.id
                AND nad.user_id = v_user_id
           )
     ORDER BY na.published_at ASC
  LOOP
    -- Resolve title from translations
    SELECT t.value INTO v_title
      FROM public.translations t
     WHERE t.key = v_article.title_key
       AND t.namespace = 'news'
       AND t.locale = v_locale;

    -- Fallback to en if not found
    IF v_title IS NULL AND v_locale <> 'en' THEN
      SELECT t.value INTO v_title
        FROM public.translations t
       WHERE t.key = v_article.title_key
         AND t.namespace = 'news'
         AND t.locale = 'en';
    END IF;

    v_title := COALESCE(v_title, v_article.title_key);

    -- Resolve excerpt from translations
    IF v_article.excerpt_key IS NOT NULL THEN
      SELECT t.value INTO v_excerpt
        FROM public.translations t
       WHERE t.key = v_article.excerpt_key
         AND t.namespace = 'news'
         AND t.locale = v_locale;

      IF v_excerpt IS NULL AND v_locale <> 'en' THEN
        SELECT t.value INTO v_excerpt
          FROM public.translations t
         WHERE t.key = v_article.excerpt_key
           AND t.namespace = 'news'
           AND t.locale = 'en';
      END IF;
    END IF;

    -- Compose message body
    v_msg_body := v_greeting || E'\n\n' || v_title;
    IF v_excerpt IS NOT NULL THEN
      v_msg_body := v_msg_body || E'\n\n' || v_excerpt;
    END IF;
    v_msg_body := v_msg_body || E'\n\n' || v_cta;

    -- Find latest active conversation (or create one)
    SELECT cc.id INTO v_conversation_id
      FROM public.chat_conversations cc
     WHERE cc.user_id = v_user_id
       AND cc.status = 'active'
     ORDER BY cc.last_message_at DESC NULLS LAST
     LIMIT 1;

    IF v_conversation_id IS NULL THEN
      INSERT INTO public.chat_conversations (user_id, title, status)
      VALUES (v_user_id, 'Chat', 'active')
      RETURNING id INTO v_conversation_id;
    END IF;

    -- Insert assistant message
    INSERT INTO public.chat_messages (
      content,
      content_metadata,
      conversation_id,
      role,
      routing_category
    ) VALUES (
      v_msg_body,
      jsonb_build_object(
        'type', 'news_article',
        'news_article_id', v_article.id,
        'slug', v_article.slug
      ),
      v_conversation_id,
      'assistant',
      'news'
    )
    RETURNING id INTO v_message_id;

    -- Update conversation metadata
    UPDATE public.chat_conversations
       SET last_message_at = now(),
           message_count = message_count + 1,
           updated_at = now()
     WHERE id = v_conversation_id;

    -- Track delivery
    INSERT INTO public.news_article_deliveries (
      conversation_id,
      message_id,
      news_article_id,
      user_id
    ) VALUES (
      v_conversation_id,
      v_message_id,
      v_article.id,
      v_user_id
    );

    v_delivered_count := v_delivered_count + 1;
  END LOOP;

  -- Audit if anything was delivered
  IF v_delivered_count > 0 THEN
    INSERT INTO audit_journal (user_id, action, metadata)
    VALUES (
      v_user_id,
      'NEWS_CHAT_DELIVERY',
      jsonb_build_object(
        'area', 'content',
        'severity', 'info',
        'count', v_delivered_count
      )
    );
  END IF;

  RETURN v_delivered_count;
END;
$$;

REVOKE ALL ON FUNCTION deliver_pending_news_to_chat() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION deliver_pending_news_to_chat() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/user_has_admin_role.sql
-- -----------------------------------------------------------------------------

-- Function: public.user_has_admin_role
-- Arguments: p_user_id uuid, _user_id uuid (alias)
-- Description: Checks if user has admin role.
-- Security: SECURITY DEFINER with search_path set.
-- Updated: 2026-01-11 - Added _user_id alias for TypeScript compatibility

CREATE OR REPLACE FUNCTION public.user_has_admin_role(
  p_user_id uuid DEFAULT NULL,
  -- TypeScript compatibility alias
  _user_id uuid DEFAULT NULL
)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- ⛔ PREDIKÁT O TŘETÍ OSOBĚ JE ORÁKULUM (naměřeno 2026-09-19) — tatáž třída
  -- jako has_role: kterýkoli přihlášený se pro libovolné uuid dozvěděl, zda je
  -- to administrátor. Veřejný adresář partnerů vydá `user_id` účtů, takže
  -- z obecného seznamu cílů je seznam ADRESNÝ.
  --
  -- Odpovídá se jen o VOLAJÍCÍM; služba a správa na kohokoli. Změřeno, že to nic
  -- nerozbije: v repu ji nevolá žádná politika, funkce ani klient (grep přes
  -- sql/ts/tsx/json). CASE drží NULL (anonym, prázdný argument) v ELSE = false.
  SELECT CASE
    WHEN COALESCE(p_user_id, _user_id) IS NULL THEN false
    WHEN COALESCE(p_user_id, _user_id) = auth.uid()
      OR public.is_service_role()
      OR public.is_admin_or_staff()
    THEN EXISTS (
      SELECT 1
      FROM public.user_roles ur
      JOIN public.roles r ON r.name = ur.role
      WHERE ur.user_id = COALESCE(p_user_id, _user_id) AND r.is_admin = true
    )
    ELSE false
  END
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.user_has_admin_role(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.user_has_admin_role(uuid, uuid) TO authenticated;


