-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/validate_invitation.sql
-- -----------------------------------------------------------------------------

-- Function: public.validate_invitation
-- Arguments: p_invite_code text
-- Description: Validates an invitation code and returns study/partner info. Used during registration.
-- Security: SECURITY DEFINER - public validation for registration flow.
-- @security: public
-- @audit: none

CREATE OR REPLACE FUNCTION public.validate_invitation(p_invite_code text)
 RETURNS TABLE(invited_email text, is_valid boolean, parent_study_id uuid, parent_study_name text, partner_id uuid, partner_name text, prefill_first_name text, prefill_last_name text, prefill_notes text, prefill_phone text, study_id uuid, study_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_invitation RECORD;
    v_study RECORD;
    v_parent_study RECORD;
    v_partner RECORD;
BEGIN
    -- Find the invitation
    SELECT 
        i.id, 
        i.study_id, 
        i.is_active, 
        i.expires_at, 
        i.max_uses, 
        i.used_count,
        i.created_by,
        i.email,
        i.prefill_first_name,
        i.prefill_last_name,
        i.prefill_phone,
        i.prefill_notes
    INTO v_invitation
    FROM invitations i
    WHERE i.code = p_invite_code;
    
    -- Check if invitation exists and is valid
    IF v_invitation IS NULL THEN
        RETURN QUERY SELECT 
            NULL::TEXT, FALSE, NULL::UUID, NULL::TEXT, NULL::UUID, NULL::TEXT,
            NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::UUID, NULL::TEXT;
        RETURN;
    END IF;
    
    IF NOT v_invitation.is_active THEN
        RETURN QUERY SELECT 
            NULL::TEXT, FALSE, NULL::UUID, NULL::TEXT, NULL::UUID, NULL::TEXT,
            NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::UUID, NULL::TEXT;
        RETURN;
    END IF;
    
    IF v_invitation.expires_at IS NOT NULL AND v_invitation.expires_at < NOW() THEN
        RETURN QUERY SELECT 
            NULL::TEXT, FALSE, NULL::UUID, NULL::TEXT, NULL::UUID, NULL::TEXT,
            NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::UUID, NULL::TEXT;
        RETURN;
    END IF;
    
    IF v_invitation.max_uses IS NOT NULL AND v_invitation.used_count >= v_invitation.max_uses THEN
        RETURN QUERY SELECT 
            NULL::TEXT, FALSE, NULL::UUID, NULL::TEXT, NULL::UUID, NULL::TEXT,
            NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::UUID, NULL::TEXT;
        RETURN;
    END IF;
    
    -- Get study info if present
    IF v_invitation.study_id IS NOT NULL THEN
        SELECT s.id, s.name, s.parent_study_id
        INTO v_study
        FROM studies s
        WHERE s.id = v_invitation.study_id;
        
        -- Get parent study info if this is a child study
        IF v_study.parent_study_id IS NOT NULL THEN
            SELECT ps.id, ps.name
            INTO v_parent_study
            FROM studies ps
            WHERE ps.id = v_study.parent_study_id;
        END IF;
    END IF;
    
    -- Get partner info if invitation creator is a partner
    SELECT pp.id, pp.display_name
    INTO v_partner
    FROM partner_profiles pp
    WHERE pp.user_id = v_invitation.created_by
      AND pp.is_certified = TRUE;
    
    -- Return columns in alphabetical order to match TypeScript types
    RETURN QUERY SELECT 
        v_invitation.email,
        TRUE,
        v_parent_study.id,
        v_parent_study.name,
        v_partner.id,
        v_partner.display_name,
        v_invitation.prefill_first_name,
        v_invitation.prefill_last_name,
        v_invitation.prefill_notes,
        v_invitation.prefill_phone,
        v_study.id,
        v_study.name;
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.validate_invitation(p_invite_code text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.validate_invitation(p_invite_code text) TO public;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/validate_mcp_token.sql
-- -----------------------------------------------------------------------------

-- Function: public.validate_mcp_token
-- Arguments: p_token_hash text, p_tool_name text DEFAULT NULL::text, p_project_id uuid DEFAULT NULL::uuid
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.validate_mcp_token(p_token_hash text, p_tool_name text DEFAULT NULL::text, p_project_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_token RECORD;
BEGIN
  SELECT * INTO v_token
  FROM mcp_auth_tokens
  WHERE token_hash = p_token_hash
    AND is_active = true
    AND (expires_at IS NULL OR expires_at > now());

  IF v_token IS NULL THEN
    RETURN jsonb_build_object('valid', false, 'reason', 'token_not_found_or_expired');
  END IF;

  -- Check scope
  IF v_token.scope = 'project' AND v_token.project_id != p_project_id THEN
    RETURN jsonb_build_object('valid', false, 'reason', 'project_scope_mismatch');
  END IF;

  -- Check tool permission
  IF p_tool_name IS NOT NULL THEN
    IF v_token.denied_tools @> ARRAY[p_tool_name] THEN
      RETURN jsonb_build_object('valid', false, 'reason', 'tool_denied');
    END IF;
    IF array_length(v_token.allowed_tools, 1) > 0
       AND NOT (v_token.allowed_tools @> ARRAY[p_tool_name]) THEN
      RETURN jsonb_build_object('valid', false, 'reason', 'tool_not_allowed');
    END IF;
  END IF;

  -- Update usage
  UPDATE mcp_auth_tokens
  SET last_used_at = now(), usage_count = usage_count + 1
  WHERE id = v_token.id;

  RETURN jsonb_build_object(
    'valid', true,
    'user_id', v_token.user_id,                 -- §8: chargeback/audit identity (req.user.sub)
    'story_id', v_token.scoped_to_story_id,      -- §8.5: derived story scope (NULL ⇒ caller fail-closes)
    'scoped_to_story_id', v_token.scoped_to_story_id,
    'scope', v_token.scope,
    'account_id', v_token.account_id,
    'project_id', v_token.project_id,
    'rate_limit_rpm', v_token.rate_limit_rpm,
    'rate_limit_daily', v_token.rate_limit_daily,
    -- Seznamy nástrojů pro autorizaci VOLAJÍCÍ služby (svc-mcp-knowledge filtruje
    -- tools/list a odmítá tools/call týmž predikátem). Bez nich by musela volat
    -- tuhle funkci pro každý nástroj zvlášť — a každé volání navyšuje usage_count.
    -- Sémantika shodná s kontrolou výše: prázdné allowed_tools = bez omezení.
    'allowed_tools', to_jsonb(COALESCE(v_token.allowed_tools, '{}'::text[])),
    'denied_tools', to_jsonb(COALESCE(v_token.denied_tools, '{}'::text[]))
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.validate_mcp_token(text, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.validate_mcp_token(text, text, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.validate_mcp_token(text, text, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/validate_sync_authorization.sql
-- -----------------------------------------------------------------------------

-- Function: public.validate_sync_authorization
-- Arguments: p_instance_id uuid, p_instance_token text, p_operation_type text, p_story_id uuid
-- Description: Core authorization logic for sync operations. Validates:
--   1. Instance exists and belongs to story
--   2. Instance is active
--   3. Token is valid (SHA-256 hash match), not revoked, not expired
--   4. Token has required scope for operation type ('sync:' || operation_type,
--      so 'promote' requires scope 'sync:promote')
--   5. Origin protection (export only from origin, no direct import into origin,
--      promote only FROM a non-origin replica towards the origin)
--   6. Flow direction compliance (blocked domains returned for caller to skip;
--      for 'promote' every domain whose flow_direction is not
--      'promote_on_approval' is blocked)
-- Security: SECURITY DEFINER — callable from other RPC functions

CREATE OR REPLACE FUNCTION public.validate_sync_authorization(
  p_instance_id uuid,
  p_instance_token text,
  p_operation_type text,
  p_story_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_token_hash text;
  v_token_record record;
  v_instance record;
  v_required_scope text;
  v_violations jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v_instance
  FROM story_instances
  WHERE id = p_instance_id AND story_id = p_story_id;

  IF v_instance.id IS NULL THEN
    RETURN jsonb_build_object(
      'authorized', false,
      'reason', 'Instance not found or does not belong to this story'
    );
  END IF;

  IF v_instance.status != 'active' THEN
    RETURN jsonb_build_object(
      'authorized', false,
      'reason', 'Instance is not active (status: ' || v_instance.status || ')'
    );
  END IF;

  v_token_hash := encode(digest(p_instance_token, 'sha256'), 'hex');

  SELECT * INTO v_token_record
  FROM instance_auth_tokens
  WHERE instance_id = p_instance_id
    AND token_hash = v_token_hash
    AND revoked_at IS NULL
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_token_record.id IS NULL THEN
    -- user_id = auth.uid() (nullable): sync auth runs under a token/service actor
    -- (auth.uid() NULL); the COALESCE fallback to '00000000-…0000' is not a real
    -- aisha_auth.users id → audit_journal_user_id_fkey violation on the failure
    -- path. NULL is FK-safe.
    INSERT INTO audit_journal (user_id, action, metadata)
    VALUES (auth.uid(), 'SYNC_AUTH_FAILED', jsonb_build_object(
      'area', 'story_sync', 'severity', 'warning',
      'instance_id', p_instance_id,
      'story_id', p_story_id,
      'operation_type', p_operation_type,
      'reason', 'invalid_token'
    ));
    RETURN jsonb_build_object(
      'authorized', false,
      'reason', 'Invalid or revoked token'
    );
  END IF;

  IF v_token_record.expires_at IS NOT NULL AND v_token_record.expires_at < now() THEN
    RETURN jsonb_build_object(
      'authorized', false,
      'reason', 'Token expired at ' || v_token_record.expires_at
    );
  END IF;

  v_required_scope := 'sync:' || p_operation_type;
  IF NOT (v_token_record.scopes ? v_required_scope) THEN
    RETURN jsonb_build_object(
      'authorized', false,
      'reason', 'Token missing required scope: ' || v_required_scope,
      'token_scopes', v_token_record.scopes
    );
  END IF;

  IF p_operation_type = 'export' AND NOT v_instance.is_origin THEN
    RETURN jsonb_build_object(
      'authorized', false,
      'reason', 'Only the origin instance can export bundles'
    );
  END IF;

  IF p_operation_type = 'import' AND v_instance.is_origin THEN
    RETURN jsonb_build_object(
      'authorized', false,
      'reason', 'Cannot import directly into origin instance. Use promote operation for upstream changes.'
    );
  END IF;

  -- Promote is the upstream direction: a replica proposes changes to the origin.
  -- The origin never promotes to itself.
  IF p_operation_type = 'promote' AND v_instance.is_origin THEN
    RETURN jsonb_build_object(
      'authorized', false,
      'reason', 'Origin does not promote to itself'
    );
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'data_domain', sp.data_domain,
    'flow_direction', sp.flow_direction::text,
    'blocked', CASE
      WHEN p_operation_type = 'import' AND sp.flow_direction IN ('local_only', 'no_sync') THEN true
      WHEN p_operation_type = 'export' AND sp.flow_direction = 'local_only' THEN true
      -- Promote allows only domains explicitly opted into upstream flow
      WHEN p_operation_type = 'promote' AND sp.flow_direction <> 'promote_on_approval' THEN true
      ELSE false
    END
  ) ORDER BY sp.data_domain), '[]'::jsonb) INTO v_violations
  FROM story_sync_policies sp
  WHERE sp.story_id = p_story_id
    AND (
      (p_operation_type = 'import' AND sp.flow_direction IN ('local_only', 'no_sync'))
      OR (p_operation_type = 'export' AND sp.flow_direction = 'local_only')
      OR (p_operation_type = 'promote' AND sp.flow_direction <> 'promote_on_approval')
    );

  RETURN jsonb_build_object(
    'authorized', true,
    'instance_id', p_instance_id,
    'instance_type', v_instance.instance_type,
    'is_origin', v_instance.is_origin,
    'token_id', v_token_record.id,
    'scope_used', v_required_scope,
    'blocked_domains', v_violations,
    'note', CASE
      WHEN jsonb_array_length(v_violations) > 0
      THEN 'Some data domains are blocked by sync policies. They will be skipped during ' || p_operation_type || '.'
      ELSE 'All data domains allowed for ' || p_operation_type
    END
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.validate_sync_authorization(uuid, text, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.validate_sync_authorization(uuid, text, text, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/export_story_bundle.sql
-- -----------------------------------------------------------------------------

-- Function: public.export_story_bundle
-- Arguments: p_story_id uuid, p_instance_token text DEFAULT NULL, p_source_instance_id uuid DEFAULT NULL
-- Description: Exports canonical portable data from a story into a versioned bundle.
--              Collects story metadata, rulesets (incl. ai_instructions since 1.1.0),
--              knowledge items, sync policies, and portable config into a single
--              manifest. Computes SHA-256 manifest hash for integrity verification
--              on import. Two auth modes:
--                1. Role-based (UI export): no token, requires auth.uid() + admin/staff
--                2. Token-based (M2M sync): instance token validated via
--                   validate_sync_authorization; auth.uid() MAY be NULL. Domains
--                   blocked by sync policies (flow_direction = local_only) are
--                   emptied in the manifest and reported as skipped_domains.
-- Security: SECURITY DEFINER — admin/staff or valid instance token

-- Drop legacy 1-arg overload (replaced by 3-arg with token auth)
DROP FUNCTION IF EXISTS public.export_story_bundle(uuid);

CREATE OR REPLACE FUNCTION public.export_story_bundle(
  p_story_id uuid,
  p_instance_token text DEFAULT NULL,
  p_source_instance_id uuid DEFAULT NULL
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user_id uuid;
  v_story record;
  v_ruleset record;
  v_context record;
  v_origin_instance record;
  v_next_version integer;
  v_bundle_id uuid;
  v_operation_id uuid;
  v_portable_manifest jsonb;
  v_artifact_summary jsonb;
  v_knowledge_items jsonb;
  v_sync_policies jsonb;
  v_expert_rules jsonb;
  v_ruleset_section jsonb;
  v_story_metadata jsonb;
  v_build_config jsonb;
  v_manifest_hash text;
  v_auth_result jsonb;
  v_blocked_domains jsonb := '[]'::jsonb;
  v_skipped_domains text[] := '{}';
  v_actor_ref text;
  v_actor_type text;
  v_metadata_blocked boolean := false;
  v_rules_blocked boolean := false;
  v_knowledge_blocked boolean := false;
  v_build_blocked boolean := false;
BEGIN
  v_user_id := auth.uid();

  -- ===== AUTHORIZATION =====
  -- Token-based (M2M sync): auth.uid() MAY be NULL, instance token is validated.
  -- Role-based (UI export): auth.uid() + admin/staff required, nothing blocked.
  IF p_instance_token IS NOT NULL THEN
    IF p_source_instance_id IS NULL THEN
      RAISE EXCEPTION 'Source instance id required for token-based export' USING ERRCODE = '22023';
    END IF;

    v_auth_result := public.validate_sync_authorization(
      p_source_instance_id, p_instance_token, 'export', p_story_id
    );

    IF NOT (v_auth_result->>'authorized')::boolean THEN
      -- user_id may be NULL (M2M actor) — FK-safe, see validate_sync_authorization
      INSERT INTO audit_journal (user_id, action, metadata)
      VALUES (v_user_id, 'SYNC_EXPORT_DENIED', jsonb_build_object(
        'area', 'story_sync', 'severity', 'warning',
        'story_id', p_story_id,
        'source_instance_id', p_source_instance_id,
        'reason', v_auth_result->>'reason'
      ));

      RETURN jsonb_build_object(
        'status', 'denied',
        'reason', v_auth_result->>'reason'
      );
    END IF;

    v_blocked_domains := COALESCE(v_auth_result->'blocked_domains', '[]'::jsonb);
    v_actor_type := 'instance';
    v_actor_ref := 'instance:' || p_source_instance_id;
  ELSE
    IF v_user_id IS NULL THEN
      RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Only admin/staff can export without a token; nothing is blocked for admins
    IF NOT public.is_admin_or_staff() THEN
      RAISE EXCEPTION 'Unauthorized: admin or staff role required';
    END IF;

    v_actor_type := 'human';
    v_actor_ref := v_user_id::text;
  END IF;

  -- Resolve blocked manifest sections from sync policy domains
  v_metadata_blocked := EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_blocked_domains) bd
    WHERE bd->>'data_domain' = 'story_metadata' AND (bd->>'blocked')::boolean
  );
  v_rules_blocked := EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_blocked_domains) bd
    WHERE bd->>'data_domain' = 'rulesets' AND (bd->>'blocked')::boolean
  );
  v_knowledge_blocked := EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_blocked_domains) bd
    WHERE bd->>'data_domain' = 'knowledge_items' AND (bd->>'blocked')::boolean
  );
  v_build_blocked := EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_blocked_domains) bd
    WHERE bd->>'data_domain' = 'build_config' AND (bd->>'blocked')::boolean
  );

  -- Load story
  SELECT * INTO v_story
  FROM partner_stories
  WHERE id = p_story_id;

  IF v_story.id IS NULL THEN
    RAISE EXCEPTION 'Story not found: %', p_story_id;
  END IF;

  -- Resolve origin instance — MUST exist for export
  SELECT * INTO v_origin_instance
  FROM story_instances
  WHERE story_id = p_story_id AND is_origin = true;

  IF v_origin_instance.id IS NULL THEN
    RAISE EXCEPTION 'No origin instance registered for story %. Register one first.', p_story_id;
  END IF;

  -- Load current ruleset
  SELECT * INTO v_ruleset
  FROM story_rulesets sr
  JOIN story_contexts sc ON sc.ruleset_id = sr.id
  WHERE sc.story_id = p_story_id;

  -- Load story context
  SELECT * INTO v_context
  FROM story_contexts
  WHERE story_id = p_story_id;

  -- Serialize concurrent exports of the same story (tx-scoped advisory lock)
  -- so MAX(bundle_version)+1 cannot race into a duplicate version
  PERFORM pg_advisory_xact_lock(hashtext('story_bundle_export'), hashtext(p_story_id::text));

  -- Calculate next bundle version
  SELECT COALESCE(MAX(bundle_version), 0) + 1 INTO v_next_version
  FROM story_bundles
  WHERE story_id = p_story_id;

  -- Collect portable knowledge items (content + metadata, not embeddings).
  -- Manifest keys map to columns: slug→source_slug, content→body_markdown,
  -- tags→ai_context_tags, verified→is_verified. metadata carries the fields
  -- import needs to re-insert the row (item_type is NOT NULL enum).
  IF v_knowledge_blocked THEN
    v_knowledge_items := '[]'::jsonb;
    v_skipped_domains := v_skipped_domains || 'knowledge_items'::text;
  ELSE
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', ki.id,
      'title', ki.title,
      'slug', ki.source_slug,
      'content', ki.body_markdown,
      'category', ki.category,
      'tags', ki.ai_context_tags,
      'status', ki.status,
      'version', ki.version,
      'verified', ki.is_verified,
      'metadata', jsonb_build_object(
        'item_type', ki.item_type::text,
        'source_type', ki.source_type,
        'summary', ki.summary,
        'ai_instructions', ki.ai_instructions,
        'locale', ki.locale
      )
    )), '[]'::jsonb) INTO v_knowledge_items
    FROM knowledge_items ki
    WHERE ki.story_id = p_story_id
      AND ki.status = 'active';
  END IF;

  -- Collect sync policies
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'data_domain', sp.data_domain,
    'data_class', sp.data_class::text,
    'flow_direction', sp.flow_direction::text,
    'description', sp.description
  )), '[]'::jsonb) INTO v_sync_policies
  FROM story_sync_policies sp
  WHERE sp.story_id = p_story_id;

  -- Collect expert rules content (schema 1.1.0 adds ai_instructions — part of the
  -- ruleset fingerprint). Manifest keys map to columns: content→body_markdown,
  -- tags→ai_context_tags. sub_category has no backing column (kept for shape).
  IF v_rules_blocked THEN
    v_expert_rules := '[]'::jsonb;
    v_ruleset_section := '{}'::jsonb;
    v_skipped_domains := v_skipped_domains || 'rulesets'::text;
  ELSE
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', er.id,
      'slug', er.slug,
      'title', er.title,
      'category', er.category::text,
      'sub_category', NULL::text,
      'content', er.body_markdown,
      'ai_instructions', er.ai_instructions,
      'version', er.version,
      'tags', er.ai_context_tags
    )), '[]'::jsonb) INTO v_expert_rules
    FROM unnest(v_ruleset.rule_ids) AS rid
    JOIN expert_rules er ON er.id = rid
    WHERE er.status = 'published';

    v_ruleset_section := jsonb_build_object(
      'fingerprint', v_ruleset.ruleset_fingerprint,
      'rule_ids', to_jsonb(v_ruleset.rule_ids),
      'rule_versions', v_ruleset.rule_versions,
      'context_profile', v_ruleset.context_profile
    );
  END IF;

  -- Story metadata section
  IF v_metadata_blocked THEN
    v_story_metadata := '{}'::jsonb;
    v_skipped_domains := v_skipped_domains || 'story_metadata'::text;
  ELSE
    v_story_metadata := jsonb_build_object(
      'id', v_story.id,
      'title', v_story.title,
      'status', v_story.status,
      'tech_stack', v_story.tech_stack,
      'domain', v_story.domain,
      'project_preview', v_story.project_preview,
      'risk_profile', v_story.risk_profile,
      'repo_url', v_story.repo_url,
      'repo_provider', v_story.repo_provider,
      'default_branch', v_story.default_branch
    );
  END IF;

  -- Build config section
  IF v_build_blocked THEN
    v_build_config := '{}'::jsonb;
    v_skipped_domains := v_skipped_domains || 'build_config'::text;
  ELSE
    v_build_config := COALESCE(v_context.build_config, '{}'::jsonb);
  END IF;

  -- Build portable manifest (1.1.0: expert_rules carry ai_instructions)
  v_portable_manifest := jsonb_build_object(
    'schema_version', '1.1.0',
    'story_metadata', v_story_metadata,
    'ruleset', v_ruleset_section,
    'expert_rules', v_expert_rules,
    'knowledge_items', v_knowledge_items,
    'sync_policies', v_sync_policies,
    'portable_config', COALESCE(v_context.portable_config, '{}'::jsonb),
    'build_config', v_build_config
  );

  -- Artifact summary (counts, no content)
  v_artifact_summary := jsonb_build_object(
    'rule_count', jsonb_array_length(v_expert_rules),
    'knowledge_item_count', jsonb_array_length(v_knowledge_items),
    'sync_policy_count', jsonb_array_length(v_sync_policies),
    'skipped_domains', to_jsonb(v_skipped_domains)
  );

  -- Compute manifest integrity hash
  v_manifest_hash := encode(digest(v_portable_manifest::text, 'sha256'), 'hex');

  -- Insert bundle with manifest hash
  INSERT INTO story_bundles (
    story_id, bundle_version, ruleset_fingerprint,
    schema_version, portable_manifest, bundle_manifest_hash,
    artifact_summary, exported_by, exported_from_instance_id
  ) VALUES (
    p_story_id, v_next_version, COALESCE(v_ruleset.ruleset_fingerprint, 'unknown'),
    '1.1.0', v_portable_manifest, v_manifest_hash,
    v_artifact_summary,
    COALESCE(v_user_id::text, 'instance:' || p_source_instance_id),
    v_origin_instance.id
  ) RETURNING id INTO v_bundle_id;

  -- Create sync operation record
  INSERT INTO story_sync_operations (
    story_id, bundle_id, bundle_version, operation_type,
    source_instance_id, ruleset_fingerprint,
    actor_ref, actor_type, outcome, committed_at,
    metadata
  ) VALUES (
    p_story_id, v_bundle_id, v_next_version, 'export',
    v_origin_instance.id, COALESCE(v_ruleset.ruleset_fingerprint, 'unknown'),
    v_actor_ref, v_actor_type, 'success', now(),
    jsonb_build_object(
      'manifest_hash', v_manifest_hash,
      'skipped_domains', to_jsonb(v_skipped_domains)
    )
  ) RETURNING id INTO v_operation_id;

  -- Audit journal (user_id nullable — M2M export runs without auth.uid())
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (v_user_id, 'STORY_BUNDLE_EXPORT', jsonb_build_object(
    'area', 'story_sync',
    'severity', 'info',
    'entity_type', 'story_bundle',
    'entity_id', v_bundle_id,
    'story_id', p_story_id,
    'bundle_version', v_next_version,
    'operation_id', v_operation_id,
    'manifest_hash', v_manifest_hash,
    'actor_ref', v_actor_ref,
    'skipped_domains', to_jsonb(v_skipped_domains)
  ));

  RETURN jsonb_build_object(
    'bundle_id', v_bundle_id,
    'bundle_version', v_next_version,
    'operation_id', v_operation_id,
    'manifest_hash', v_manifest_hash,
    'ruleset_fingerprint', COALESCE(v_ruleset.ruleset_fingerprint, 'unknown'),
    'artifact_summary', v_artifact_summary,
    'skipped_domains', to_jsonb(v_skipped_domains)
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.export_story_bundle(uuid, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.export_story_bundle(uuid, text, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.export_story_bundle(uuid, text, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/import_story_bundle.sql
-- -----------------------------------------------------------------------------

-- Function: public.import_story_bundle
-- Arguments: p_bundle_id uuid, p_instance_token text DEFAULT NULL, p_target_instance_id uuid DEFAULT NULL
-- Description: Imports a story bundle into a target instance. Supports two auth modes:
--              1. Token-based (M2M sync): pass p_instance_token for scoped auth;
--                 auth.uid() MAY be NULL (actor_type 'instance')
--              2. Role-based (UI import): admin/staff without token
--              Validates manifest integrity (SHA-256), respects sync policies,
--              blocks domains where flow direction forbids import, and materializes
--              expert rules, the story ruleset and knowledge items server-side.
--              Ruleset fingerprint is recomputed locally and verified against the
--              manifest (schema_version >= 1.1.0); mismatch yields outcome 'partial'.
--              Embeddings are rebuilt by the existing knowledge-item trigger.
-- Security: SECURITY DEFINER — valid instance token or auth.uid() + admin/staff

-- Drop legacy 2-arg overload (replaced by 3-arg with token auth)
DROP FUNCTION IF EXISTS public.import_story_bundle(uuid, uuid);

CREATE OR REPLACE FUNCTION public.import_story_bundle(
  p_bundle_id uuid,
  p_instance_token text DEFAULT NULL,
  p_target_instance_id uuid DEFAULT NULL
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user_id uuid;
  v_bundle record;
  v_manifest jsonb;
  v_target_instance record;
  v_operation_id uuid;
  v_story_id uuid;
  v_imported_policies integer := 0;
  v_policy_item jsonb;
  v_auth_result jsonb;
  v_computed_hash text;
  v_blocked_domains jsonb := '[]'::jsonb;
  v_skipped_domains text[] := '{}';
  v_actor_ref text;
  v_actor_type text;
  v_rules_blocked boolean := false;
  v_knowledge_blocked boolean := false;
  v_rules_materialized boolean := false;
  v_rule_item jsonb;
  v_ki_item jsonb;
  v_slug text;
  v_local_rule record;
  v_local_ki record;
  v_category expert_rule_category;
  v_item_type knowledge_item_type;
  v_tags text[];
  v_locale text;
  v_incoming_version integer;
  v_author_partner_id uuid;
  v_materialized_rules integer := 0;
  v_updated_rules integer := 0;
  v_skipped_rules integer := 0;
  v_skipped_shared_rules integer := 0;
  v_shared_rule_slugs text[] := '{}';
  v_txt text;
  v_verified boolean;
  v_materialized_knowledge_items integer := 0;
  v_updated_knowledge_items integer := 0;
  v_skipped_knowledge_items integer := 0;
  v_local_rule_ids uuid[] := '{}';
  v_rule_versions jsonb := '{}'::jsonb;
  v_ruleset_id uuid;
  v_local_fingerprint text;
  v_manifest_fingerprint text;
  v_fingerprint_verified boolean;
  v_manifest_schema text;
  v_manifest_is_v11 boolean := false;
  v_outcome sync_operation_outcome := 'success';
  v_note text;
BEGIN
  -- auth.uid() may be NULL for M2M sync — a valid instance token is required then
  v_user_id := auth.uid();

  -- Load bundle first to get story_id
  SELECT id, story_id, bundle_version, portable_manifest, schema_version,
         exported_from_instance_id, ruleset_fingerprint, bundle_manifest_hash
  INTO v_bundle
  FROM story_bundles
  WHERE id = p_bundle_id;

  IF v_bundle.id IS NULL THEN
    RAISE EXCEPTION 'Bundle not found: %', p_bundle_id USING ERRCODE = '22023';
  END IF;

  v_story_id := v_bundle.story_id;
  v_manifest := v_bundle.portable_manifest;

  -- Load target instance
  SELECT id, story_id, is_origin, last_bundle_version, schema_version
  INTO v_target_instance
  FROM story_instances
  WHERE id = p_target_instance_id;

  IF v_target_instance.id IS NULL THEN
    RAISE EXCEPTION 'Target instance not found: %', p_target_instance_id USING ERRCODE = '22023';
  END IF;

  IF v_target_instance.story_id != v_story_id THEN
    RAISE EXCEPTION 'Instance % does not belong to story %', p_target_instance_id, v_story_id USING ERRCODE = '22023';
  END IF;

  -- ===== AUTHORIZATION =====
  -- If token provided: validate via instance auth (M2M sync, auth.uid() may be NULL)
  -- If no token: require auth.uid() + admin/staff (manual import from UI)
  IF p_instance_token IS NOT NULL THEN
    v_auth_result := public.validate_sync_authorization(
      p_target_instance_id, p_instance_token, 'import', v_story_id
    );

    IF NOT (v_auth_result->>'authorized')::boolean THEN
      -- Record failed attempt in audit (user_id nullable — FK-safe)
      INSERT INTO audit_journal (user_id, action, metadata)
      VALUES (v_user_id, 'SYNC_IMPORT_DENIED', jsonb_build_object(
        'area', 'story_sync', 'severity', 'warning',
        'story_id', v_story_id,
        'target_instance_id', p_target_instance_id,
        'bundle_id', p_bundle_id,
        'reason', v_auth_result->>'reason'
      ));

      RETURN jsonb_build_object(
        'status', 'denied',
        'reason', v_auth_result->>'reason'
      );
    END IF;

    -- Collect blocked domains from auth result
    v_blocked_domains := COALESCE(v_auth_result->'blocked_domains', '[]'::jsonb);
  ELSE
    -- No token: authenticated admin/staff required
    IF v_user_id IS NULL THEN
      RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
    END IF;

    IF NOT public.is_admin_or_staff() THEN
      RAISE EXCEPTION 'Unauthorized: provide instance token or use admin/staff account' USING ERRCODE = '22023';
    END IF;

    -- Admin/staff can still not import into origin
    IF v_target_instance.is_origin THEN
      RAISE EXCEPTION 'Cannot import into origin instance. Use promote operation for upstream changes.' USING ERRCODE = '22023';
    END IF;

    v_blocked_domains := '[]'::jsonb;
  END IF;

  v_actor_ref := COALESCE(v_user_id::text, 'instance:' || p_target_instance_id);
  v_actor_type := CASE WHEN v_user_id IS NULL THEN 'instance' ELSE 'human' END;

  v_rules_blocked := EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_blocked_domains) bd
    WHERE bd->>'data_domain' = 'rulesets' AND (bd->>'blocked')::boolean
  );
  v_knowledge_blocked := EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_blocked_domains) bd
    WHERE bd->>'data_domain' = 'knowledge_items' AND (bd->>'blocked')::boolean
  );

  -- Manifest schema version gate: 1.1.0 bundles carry ai_instructions in
  -- expert_rules, so the locally recomputed fingerprint is comparable.
  v_manifest_schema := COALESCE(v_manifest->>'schema_version', '1.0.0');
  IF v_manifest_schema ~ '^\d+\.\d+\.\d+$' THEN
    v_manifest_is_v11 := string_to_array(v_manifest_schema, '.')::int[] >= ARRAY[1, 1, 0];
  END IF;

  -- ===== INTEGRITY VERIFICATION =====
  IF v_bundle.bundle_manifest_hash IS NOT NULL THEN
    v_computed_hash := encode(digest(v_manifest::text, 'sha256'), 'hex');

    IF v_computed_hash != v_bundle.bundle_manifest_hash THEN
      INSERT INTO audit_journal (user_id, action, metadata)
      VALUES (v_user_id, 'SYNC_INTEGRITY_VIOLATION', jsonb_build_object(
        'area', 'story_sync', 'severity', 'critical',
        'story_id', v_story_id,
        'bundle_id', p_bundle_id,
        'expected_hash', v_bundle.bundle_manifest_hash,
        'computed_hash', v_computed_hash
      ));

      RETURN jsonb_build_object(
        'status', 'integrity_error',
        'reason', 'Bundle manifest hash mismatch — possible tampering detected'
      );
    END IF;
  END IF;

  -- Idempotency: skip if already at this version or newer
  IF v_target_instance.last_bundle_version >= v_bundle.bundle_version THEN
    RETURN jsonb_build_object(
      'status', 'skipped',
      'reason', 'Instance already at bundle version ' || v_target_instance.last_bundle_version,
      'bundle_version', v_bundle.bundle_version
    );
  END IF;

  -- Create pending sync operation
  INSERT INTO story_sync_operations (
    story_id, bundle_id, bundle_version, operation_type,
    source_instance_id, target_instance_id, ruleset_fingerprint,
    actor_ref, actor_type, outcome
  ) VALUES (
    v_story_id, p_bundle_id, v_bundle.bundle_version, 'import',
    v_bundle.exported_from_instance_id, p_target_instance_id,
    v_bundle.ruleset_fingerprint,
    v_actor_ref, v_actor_type, 'pending'
  ) RETURNING id INTO v_operation_id;

  -- Update story_contexts: portable config (merge, don't overwrite local_overlay)
  UPDATE story_contexts SET
    portable_config = COALESCE(v_manifest->'portable_config', '{}'::jsonb),
    build_config = COALESCE(v_manifest->'build_config', build_config),
    active_instance_id = p_target_instance_id,
    active_bundle_version = v_bundle.bundle_version,
    updated_at = now()
  WHERE story_id = v_story_id;

  -- Upsert sync policies from manifest (skip blocked domains)
  IF v_manifest ? 'sync_policies' AND jsonb_typeof(v_manifest->'sync_policies') = 'array' THEN
    FOR v_policy_item IN SELECT value FROM jsonb_array_elements(v_manifest->'sync_policies') AS value
    LOOP
      -- Check if domain is blocked by flow direction
      IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_blocked_domains) bd
        WHERE (bd->>'data_domain') = (v_policy_item->>'data_domain')
          AND (bd->>'blocked')::boolean = true
      ) THEN
        v_skipped_domains := v_skipped_domains || (v_policy_item->>'data_domain');
        CONTINUE;
      END IF;

      INSERT INTO story_sync_policies (story_id, data_domain, data_class, flow_direction, description)
      VALUES (
        v_story_id,
        v_policy_item->>'data_domain',
        (v_policy_item->>'data_class')::sync_data_class,
        (v_policy_item->>'flow_direction')::sync_flow_direction,
        v_policy_item->>'description'
      )
      ON CONFLICT (story_id, data_domain) DO UPDATE SET
        data_class = EXCLUDED.data_class,
        flow_direction = EXCLUDED.flow_direction,
        description = EXCLUDED.description,
        updated_at = now();
      v_imported_policies := v_imported_policies + 1;
    END LOOP;
  END IF;

  -- ===== MATERIALIZATION: EXPERT RULES (domain 'rulesets') =====
  -- Manifest keys map to columns: content→body_markdown, tags→ai_context_tags.
  -- slug is matched by SELECT (no reliance on a unique constraint).
  IF v_rules_blocked THEN
    IF NOT ('rulesets' = ANY(v_skipped_domains)) THEN
      v_skipped_domains := v_skipped_domains || 'rulesets'::text;
    END IF;
  ELSIF jsonb_typeof(v_manifest->'expert_rules') = 'array'
    AND jsonb_array_length(v_manifest->'expert_rules') > 0 THEN

    -- expert_rules.author_partner_id is NOT NULL: resolve from the story's
    -- partner, else reuse the earliest local author (replica bootstraps have
    -- no partner context of their own). Without any candidate, inserts are skipped.
    SELECT ps.partner_id INTO v_author_partner_id
    FROM partner_stories ps
    WHERE ps.id = v_story_id;

    IF v_author_partner_id IS NULL THEN
      SELECT er.author_partner_id INTO v_author_partner_id
      FROM expert_rules er
      ORDER BY er.created_at ASC
      LIMIT 1;
    END IF;

    FOR v_rule_item IN SELECT value FROM jsonb_array_elements(v_manifest->'expert_rules') AS value
    LOOP
      v_slug := v_rule_item->>'slug';
      IF v_slug IS NULL OR v_slug = '' THEN
        v_skipped_rules := v_skipped_rules + 1;
        CONTINUE;
      END IF;

      -- Strict cast guard: manifest is untrusted input
      v_txt := v_rule_item->>'version';
      IF v_txt IS NULL THEN
        v_incoming_version := 1;
      ELSIF v_txt ~ '^[0-9]+$' THEN
        v_incoming_version := v_txt::integer;
      ELSE
        RAISE EXCEPTION 'Invalid version "%" for expert rule slug "%": expected a non-negative integer', v_txt, v_slug
          USING ERRCODE = '22023';
      END IF;

      IF EXISTS (
        SELECT 1 FROM unnest(enum_range(NULL::expert_rule_category)) e
        WHERE e::text = v_rule_item->>'category'
      ) THEN
        v_category := (v_rule_item->>'category')::expert_rule_category;
      ELSE
        v_category := 'other';
      END IF;

      SELECT COALESCE(array_agg(t.val), '{}'::text[]) INTO v_tags
      FROM jsonb_array_elements_text(
        CASE WHEN jsonb_typeof(v_rule_item->'tags') = 'array'
             THEN v_rule_item->'tags' ELSE '[]'::jsonb END
      ) AS t(val);

      SELECT er.id, er.version INTO v_local_rule
      FROM expert_rules er
      WHERE er.slug = v_slug
      ORDER BY er.version DESC, er.created_at DESC
      LIMIT 1;

      IF v_local_rule.id IS NULL THEN
        IF v_author_partner_id IS NULL THEN
          -- No resolvable author for a NOT NULL column — skip, reported in metadata
          v_skipped_rules := v_skipped_rules + 1;
          CONTINUE;
        END IF;

        INSERT INTO expert_rules (
          slug, title, category, body_markdown, ai_instructions,
          version, ai_context_tags, status, author_partner_id, published_at
        ) VALUES (
          v_slug,
          COALESCE(v_rule_item->>'title', v_slug),
          v_category,
          COALESCE(v_rule_item->>'content', ''),
          v_rule_item->>'ai_instructions',
          v_incoming_version,
          v_tags,
          'published',
          v_author_partner_id,
          now()
        );
        v_materialized_rules := v_materialized_rules + 1;
      ELSIF v_incoming_version > COALESCE(v_local_rule.version, 0) THEN
        -- Cross-story guard: never mutate a rule referenced by another story's
        -- ruleset — an import must not tamper with shared rules
        IF EXISTS (
          SELECT 1
          FROM story_rulesets r
          JOIN story_contexts sc ON sc.ruleset_id = r.id
          WHERE v_local_rule.id = ANY(r.rule_ids)
            AND sc.story_id <> v_story_id
        ) THEN
          v_skipped_shared_rules := v_skipped_shared_rules + 1;
          v_shared_rule_slugs := v_shared_rule_slugs || v_slug;
          CONTINUE;
        END IF;

        UPDATE expert_rules SET
          title = COALESCE(v_rule_item->>'title', title),
          category = v_category,
          body_markdown = COALESCE(v_rule_item->>'content', body_markdown),
          ai_instructions = v_rule_item->>'ai_instructions',
          version = v_incoming_version,
          ai_context_tags = v_tags,
          status = 'published',
          updated_at = now()
        WHERE id = v_local_rule.id;
        v_updated_rules := v_updated_rules + 1;

        INSERT INTO audit_journal (user_id, action, metadata)
        VALUES (v_user_id, 'SYNC_RULE_OVERWRITTEN', jsonb_build_object(
          'area', 'story_sync', 'severity', 'info',
          'entity_type', 'expert_rule',
          'entity_id', v_local_rule.id,
          'story_id', v_story_id,
          'bundle_id', p_bundle_id,
          'slug', v_slug,
          'old_version', v_local_rule.version,
          'new_version', v_incoming_version
        ));
      END IF;
      -- else: local version is same or newer — skip silently (no downgrade)
    END LOOP;

    -- One aggregated audit record for all shared-rule skips
    IF v_skipped_shared_rules > 0 THEN
      INSERT INTO audit_journal (user_id, action, metadata)
      VALUES (v_user_id, 'SYNC_RULE_SHARED_SKIPPED', jsonb_build_object(
        'area', 'story_sync', 'severity', 'warning',
        'entity_type', 'expert_rule',
        'story_id', v_story_id,
        'bundle_id', p_bundle_id,
        'slugs', to_jsonb(v_shared_rule_slugs)
      ));
    END IF;

    -- Resolve local rule ids for the manifest slugs (deterministic: ORDER BY slug;
    -- duplicate slugs collapse to the highest local version)
    SELECT COALESCE(array_agg(s.id ORDER BY s.slug), '{}'::uuid[]),
           COALESCE(jsonb_object_agg(s.slug, s.version), '{}'::jsonb)
    INTO v_local_rule_ids, v_rule_versions
    FROM (
      SELECT DISTINCT ON (er.slug) er.id, er.slug, er.version
      FROM expert_rules er
      WHERE er.slug IN (
        SELECT DISTINCT r.value->>'slug'
        FROM jsonb_array_elements(v_manifest->'expert_rules') AS r(value)
        WHERE r.value->>'slug' IS NOT NULL
      )
      ORDER BY er.slug, er.version DESC, er.created_at DESC
    ) s;

    -- Recompute ruleset fingerprint locally (same formula as
    -- fn_recalculate_ruleset_fingerprint: published rules only)
    SELECT md5(string_agg(
      er.slug || ':' || er.version::text || ':' || COALESCE(er.ai_instructions, ''),
      '|' ORDER BY er.slug
    ))
    INTO v_local_fingerprint
    FROM expert_rules er
    WHERE er.id = ANY(v_local_rule_ids)
      AND er.status = 'published';

    v_local_fingerprint := COALESCE(v_local_fingerprint, 'empty');

    -- Materialize the story ruleset and bind it to the story context
    SELECT sc.ruleset_id INTO v_ruleset_id
    FROM story_contexts sc
    WHERE sc.story_id = v_story_id;

    IF v_ruleset_id IS NOT NULL THEN
      UPDATE story_rulesets SET
        rule_ids = v_local_rule_ids,
        rule_versions = v_rule_versions,
        context_profile = COALESCE(v_manifest->'ruleset'->>'context_profile', context_profile),
        ruleset_fingerprint = v_local_fingerprint
      WHERE id = v_ruleset_id;
    ELSE
      INSERT INTO story_rulesets (
        story_id, ruleset_fingerprint, rule_ids, rule_versions, context_profile, created_by
      ) VALUES (
        v_story_id, v_local_fingerprint, v_local_rule_ids, v_rule_versions,
        COALESCE(v_manifest->'ruleset'->>'context_profile', 'repo_plus_rules'),
        v_actor_ref
      ) RETURNING id INTO v_ruleset_id;

      -- story_contexts has PRIMARY KEY (story_id) — ON CONFLICT is safe
      INSERT INTO story_contexts (story_id, ruleset_id, active_instance_id, active_bundle_version)
      VALUES (v_story_id, v_ruleset_id, p_target_instance_id, v_bundle.bundle_version)
      ON CONFLICT (story_id) DO UPDATE SET
        ruleset_id = EXCLUDED.ruleset_id,
        updated_at = now();
    END IF;

    v_rules_materialized := true;
  END IF;

  -- ===== FINGERPRINT VERIFICATION =====
  -- Only meaningful when rules were materialized and the manifest carries
  -- ai_instructions (schema >= 1.1.0). 1.0.0 bundles: fingerprint_verified stays NULL.
  IF v_rules_materialized AND v_manifest_is_v11 THEN
    v_manifest_fingerprint := v_manifest->'ruleset'->>'fingerprint';
    v_fingerprint_verified := (v_manifest_fingerprint IS NOT NULL
                               AND v_local_fingerprint = v_manifest_fingerprint);

    IF NOT v_fingerprint_verified THEN
      v_outcome := 'partial';
      INSERT INTO audit_journal (user_id, action, metadata)
      VALUES (v_user_id, 'SYNC_FINGERPRINT_MISMATCH', jsonb_build_object(
        'area', 'story_sync', 'severity', 'warning',
        'story_id', v_story_id,
        'bundle_id', p_bundle_id,
        'operation_id', v_operation_id,
        'manifest_fingerprint', v_manifest_fingerprint,
        'local_fingerprint', v_local_fingerprint
      ));
    END IF;
  END IF;

  -- ===== MATERIALIZATION: KNOWLEDGE ITEMS (domain 'knowledge_items') =====
  -- Matched by (story_id, slug→source_slug). Embeddings are rebuilt by the
  -- existing knowledge-item trigger — not touched here.
  IF v_knowledge_blocked THEN
    IF NOT ('knowledge_items' = ANY(v_skipped_domains)) THEN
      v_skipped_domains := v_skipped_domains || 'knowledge_items'::text;
    END IF;
  ELSIF jsonb_typeof(v_manifest->'knowledge_items') = 'array' THEN
    FOR v_ki_item IN SELECT value FROM jsonb_array_elements(v_manifest->'knowledge_items') AS value
    LOOP
      v_slug := v_ki_item->>'slug';
      IF v_slug IS NULL OR v_slug = '' THEN
        -- Items without a slug cannot be idempotently matched — skip
        v_skipped_knowledge_items := v_skipped_knowledge_items + 1;
        CONTINUE;
      END IF;

      -- Strict cast guards: manifest is untrusted input
      v_txt := v_ki_item->>'version';
      IF v_txt IS NULL THEN
        v_incoming_version := 1;
      ELSIF v_txt ~ '^[0-9]+$' THEN
        v_incoming_version := v_txt::integer;
      ELSE
        RAISE EXCEPTION 'Invalid version "%" for knowledge item slug "%": expected a non-negative integer', v_txt, v_slug
          USING ERRCODE = '22023';
      END IF;

      v_txt := v_ki_item->>'verified';
      IF v_txt IS NULL THEN
        v_verified := NULL;  -- COALESCE defaults apply below
      ELSIF lower(v_txt) IN ('true', 'false', 't', 'f') THEN
        v_verified := lower(v_txt) IN ('true', 't');
      ELSE
        RAISE EXCEPTION 'Invalid verified flag "%" for knowledge item slug "%": expected true/false/t/f', v_txt, v_slug
          USING ERRCODE = '22023';
      END IF;

      v_locale := COALESCE(v_ki_item->'metadata'->>'locale', 'global');

      SELECT COALESCE(array_agg(t.val), '{}'::text[]) INTO v_tags
      FROM jsonb_array_elements_text(
        CASE WHEN jsonb_typeof(v_ki_item->'tags') = 'array'
             THEN v_ki_item->'tags' ELSE '[]'::jsonb END
      ) AS t(val);

      SELECT ki.id, ki.version INTO v_local_ki
      FROM knowledge_items ki
      WHERE ki.story_id = v_story_id
        AND ki.source_slug = v_slug
      ORDER BY ki.version DESC, ki.created_at DESC
      LIMIT 1;

      IF v_local_ki.id IS NULL THEN
        -- Unique index (source_slug, locale) is global — a slug owned by another
        -- story/context must not be hijacked; skip instead of failing the import
        IF EXISTS (
          SELECT 1 FROM knowledge_items k2
          WHERE k2.source_slug = v_slug AND k2.locale = v_locale
        ) THEN
          v_skipped_knowledge_items := v_skipped_knowledge_items + 1;
          CONTINUE;
        END IF;

        IF EXISTS (
          SELECT 1 FROM unnest(enum_range(NULL::knowledge_item_type)) e
          WHERE e::text = v_ki_item->'metadata'->>'item_type'
        ) THEN
          v_item_type := (v_ki_item->'metadata'->>'item_type')::knowledge_item_type;
        ELSE
          v_item_type := 'domain_doc';
        END IF;

        INSERT INTO knowledge_items (
          item_type, source_type, source_slug, title, summary, body_markdown,
          ai_instructions, ai_context_tags, category, status, version,
          is_verified, story_id, locale
        ) VALUES (
          v_item_type,
          COALESCE(v_ki_item->'metadata'->>'source_type', 'story_sync'),
          v_slug,
          COALESCE(v_ki_item->>'title', v_slug),
          v_ki_item->'metadata'->>'summary',
          COALESCE(v_ki_item->>'content', ''),
          v_ki_item->'metadata'->>'ai_instructions',
          v_tags,
          v_ki_item->>'category',
          COALESCE(v_ki_item->>'status', 'active'),
          v_incoming_version,
          COALESCE(v_verified, false),
          v_story_id,
          v_locale
        );
        v_materialized_knowledge_items := v_materialized_knowledge_items + 1;
      ELSIF v_incoming_version > COALESCE(v_local_ki.version, 0) THEN
        UPDATE knowledge_items SET
          title = COALESCE(v_ki_item->>'title', title),
          summary = COALESCE(v_ki_item->'metadata'->>'summary', summary),
          body_markdown = COALESCE(v_ki_item->>'content', body_markdown),
          ai_instructions = COALESCE(v_ki_item->'metadata'->>'ai_instructions', ai_instructions),
          ai_context_tags = v_tags,
          category = COALESCE(v_ki_item->>'category', category),
          status = COALESCE(v_ki_item->>'status', status),
          version = v_incoming_version,
          is_verified = COALESCE(v_verified, is_verified),
          updated_at = now()
        WHERE id = v_local_ki.id;
        v_updated_knowledge_items := v_updated_knowledge_items + 1;
      END IF;
      -- else: local version is same or newer — skip silently (no downgrade)
    END LOOP;
  END IF;

  -- Update instance tracking
  UPDATE story_instances SET
    last_bundle_version = v_bundle.bundle_version,
    last_sync_at = now(),
    schema_version = v_bundle.schema_version,
    updated_at = now()
  WHERE id = p_target_instance_id;

  v_note := 'Rules and knowledge items materialized server-side. Embeddings rebuild via trigger.';
  IF NOT v_manifest_is_v11 THEN
    v_note := v_note || ' Fingerprint verification skipped: manifest schema_version '
      || v_manifest_schema || ' has no ai_instructions in expert_rules.';
  END IF;

  -- Mark operation outcome ('partial' on fingerprint mismatch, never fail)
  UPDATE story_sync_operations SET
    outcome = v_outcome,
    committed_at = now(),
    metadata = jsonb_build_object(
      'imported_policies', v_imported_policies,
      'skipped_domains', to_jsonb(v_skipped_domains),
      'knowledge_items_in_manifest', jsonb_array_length(COALESCE(v_manifest->'knowledge_items', '[]'::jsonb)),
      'rules_in_manifest', jsonb_array_length(COALESCE(v_manifest->'expert_rules', '[]'::jsonb)),
      'integrity_verified', v_bundle.bundle_manifest_hash IS NOT NULL,
      'materialized_rules', v_materialized_rules,
      'updated_rules', v_updated_rules,
      'skipped_rules', v_skipped_rules,
      'skipped_shared_rules', v_skipped_shared_rules,
      'materialized_knowledge_items', v_materialized_knowledge_items,
      'updated_knowledge_items', v_updated_knowledge_items,
      'skipped_knowledge_items', v_skipped_knowledge_items,
      'ruleset_fingerprint_verified', v_fingerprint_verified,
      'local_ruleset_fingerprint', v_local_fingerprint
    )
  WHERE id = v_operation_id;

  -- Audit journal (user_id nullable — M2M import runs without auth.uid())
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (v_user_id, 'STORY_BUNDLE_IMPORT', jsonb_build_object(
    'area', 'story_sync',
    'severity', 'info',
    'entity_type', 'story_bundle',
    'entity_id', p_bundle_id,
    'story_id', v_story_id,
    'target_instance_id', p_target_instance_id,
    'bundle_version', v_bundle.bundle_version,
    'operation_id', v_operation_id,
    'actor_ref', v_actor_ref,
    'integrity_verified', v_bundle.bundle_manifest_hash IS NOT NULL,
    'skipped_domains', to_jsonb(v_skipped_domains),
    'materialized_rules', v_materialized_rules,
    'updated_rules', v_updated_rules,
    'materialized_knowledge_items', v_materialized_knowledge_items,
    'ruleset_fingerprint_verified', v_fingerprint_verified
  ));

  RETURN jsonb_build_object(
    'status', v_outcome::text,
    'operation_id', v_operation_id,
    'bundle_version', v_bundle.bundle_version,
    'imported_policies', v_imported_policies,
    'skipped_domains', to_jsonb(v_skipped_domains),
    'integrity_verified', v_bundle.bundle_manifest_hash IS NOT NULL,
    'materialized_rules', v_materialized_rules,
    'updated_rules', v_updated_rules,
    'materialized_knowledge_items', v_materialized_knowledge_items,
    'ruleset_fingerprint_verified', v_fingerprint_verified,
    'note', v_note
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.import_story_bundle(uuid, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.import_story_bundle(uuid, text, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.import_story_bundle(uuid, text, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/import_story_bundle_from_manifest.sql
-- -----------------------------------------------------------------------------

-- Function: public.import_story_bundle_from_manifest
-- Arguments: p_manifest jsonb, p_bundle_version integer, p_manifest_hash text,
--            p_source_label text DEFAULT NULL, p_instance_token text DEFAULT NULL,
--            p_target_instance_id uuid DEFAULT NULL
-- Description: Transport RPC for replica instances — accepts a portable manifest
--              shipped from a remote origin, materializes it as a local
--              story_bundles row (idempotent on story_id + bundle_version), then
--              delegates the actual import to public.import_story_bundle.
--              Verifies manifest integrity (SHA-256), story existence AND
--              authorization (instance token or admin/staff) BEFORE persisting
--              the bundle row; the delegate re-validates authorization.
-- Security: SECURITY DEFINER — needed to persist the bundle row (story_bundles
--           has RLS with no policies); token/role validation runs here before
--           any write and again in import_story_bundle.

CREATE OR REPLACE FUNCTION public.import_story_bundle_from_manifest(
  p_manifest jsonb,
  p_bundle_version integer,
  p_manifest_hash text,
  p_source_label text DEFAULT NULL,
  p_instance_token text DEFAULT NULL,
  p_target_instance_id uuid DEFAULT NULL
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_computed_hash text;
  v_story_id uuid;
  v_bundle_id uuid;
  v_auth jsonb;
BEGIN
  -- ===== INTEGRITY VERIFICATION =====
  v_computed_hash := encode(digest(p_manifest::text, 'sha256'), 'hex');
  IF v_computed_hash != p_manifest_hash THEN
    RAISE EXCEPTION 'Manifest hash mismatch — expected %, computed %',
      p_manifest_hash, v_computed_hash USING ERRCODE = '22023';
  END IF;

  IF p_manifest->'story_metadata'->>'id' IS NULL THEN
    RAISE EXCEPTION 'Manifest missing story_metadata.id' USING ERRCODE = '22023';
  END IF;
  v_story_id := (p_manifest->'story_metadata'->>'id')::uuid;

  -- Story must already exist locally (created by bootstrap)
  IF NOT EXISTS (SELECT 1 FROM partner_stories WHERE id = v_story_id) THEN
    RAISE EXCEPTION 'Story % does not exist on this instance', v_story_id
      USING ERRCODE = '22023', HINT = 'Run bootstrap_story_replica first';
  END IF;

  -- ===== AUTHORIZATION (before any write — prevents bundle poisoning) =====
  -- The delegate re-validates; this gate ensures no story_bundles row is
  -- persisted for an unauthorized caller.
  IF p_instance_token IS NOT NULL THEN
    v_auth := public.validate_sync_authorization(
      p_target_instance_id, p_instance_token, 'import', v_story_id
    );

    IF NOT (v_auth->>'authorized')::boolean THEN
      RAISE EXCEPTION 'Unauthorized manifest import: %',
        COALESCE(v_auth->>'reason', 'invalid instance token')
        USING ERRCODE = '22023';
    END IF;
  ELSE
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Not authenticated: provide instance token or sign in as admin/staff'
        USING ERRCODE = '22023';
    END IF;

    IF NOT public.is_admin_or_staff() THEN
      RAISE EXCEPTION 'Unauthorized: provide instance token or use admin/staff account'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  -- ===== BUNDLE MATERIALIZATION (idempotent on story_id + bundle_version) =====
  SELECT id INTO v_bundle_id
  FROM story_bundles
  WHERE story_id = v_story_id
    AND bundle_version = p_bundle_version;

  IF v_bundle_id IS NULL THEN
    INSERT INTO story_bundles (
      story_id, bundle_version, ruleset_fingerprint,
      schema_version, portable_manifest, bundle_manifest_hash,
      artifact_summary, exported_by, exported_from_instance_id
    ) VALUES (
      v_story_id,
      p_bundle_version,
      COALESCE(p_manifest->'ruleset'->>'fingerprint', 'unknown'),
      COALESCE(p_manifest->>'schema_version', '1.0.0'),
      p_manifest,
      p_manifest_hash,
      jsonb_build_object(
        'rule_count', jsonb_array_length(COALESCE(p_manifest->'expert_rules', '[]'::jsonb)),
        'knowledge_item_count', jsonb_array_length(COALESCE(p_manifest->'knowledge_items', '[]'::jsonb)),
        'sync_policy_count', jsonb_array_length(COALESCE(p_manifest->'sync_policies', '[]'::jsonb))
      ),
      COALESCE(p_source_label, 'remote'),
      NULL  -- origin instance lives on the remote stack, not in this registry
    ) RETURNING id INTO v_bundle_id;
  END IF;

  -- ===== DELEGATE (authorization + apply logic live there) =====
  RETURN public.import_story_bundle(v_bundle_id, p_instance_token, p_target_instance_id);
END;
$function$;

REVOKE ALL ON FUNCTION public.import_story_bundle_from_manifest(jsonb, integer, text, text, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.import_story_bundle_from_manifest(jsonb, integer, text, text, text, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.import_story_bundle_from_manifest(jsonb, integer, text, text, text, uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/promote_story_bundle.sql
-- -----------------------------------------------------------------------------

-- Function: public.promote_story_bundle
-- Arguments: p_manifest jsonb, p_manifest_hash text, p_source_instance_id uuid, p_instance_token text DEFAULT NULL
-- Description: Proposes upstream changes from a replica to the origin (promote flow).
--              Runs on the ORIGIN side: verifies manifest integrity (SHA-256),
--              authorizes the source replica (token with scope 'sync:promote', or
--              admin/staff without token), filters manifest sections by sync
--              policies (only 'promote_on_approval' domains are promotable — v1
--              materializes knowledge_items only) and records a PENDING
--              story_sync_operations row holding the promotable payload.
--              Nothing is materialized here — approve_story_promotion does that.
-- Security: SECURITY DEFINER — token-authorized replica (auth.uid() may be NULL)
--           or admin/staff account

CREATE OR REPLACE FUNCTION public.promote_story_bundle(
  p_manifest jsonb,
  p_manifest_hash text,
  p_source_instance_id uuid,
  p_instance_token text DEFAULT NULL
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user_id uuid;
  v_story_id_text text;
  v_story_id uuid;
  v_story_exists boolean;
  v_source_instance record;
  v_origin_instance_id uuid;
  v_auth_result jsonb;
  v_blocked_domains jsonb;
  v_computed_hash text;
  v_knowledge_items jsonb;
  v_ki_count integer := 0;
  v_payload jsonb := '{}'::jsonb;
  v_blocked_domain_names text[] := '{}';
  v_operation_id uuid;
BEGIN
  v_user_id := auth.uid();  -- may be NULL for token-authenticated replica calls

  IF p_manifest IS NULL OR jsonb_typeof(p_manifest) != 'object' THEN
    RAISE EXCEPTION 'Manifest must be a JSON object' USING ERRCODE = '22023';
  END IF;

  IF p_manifest_hash IS NULL THEN
    RAISE EXCEPTION 'Manifest hash is required' USING ERRCODE = '22023';
  END IF;

  -- Resolve story from manifest (story_metadata.id; top-level story_id tolerated).
  -- Read as text and validate the UUID shape before casting — a malformed id
  -- must fail as 22023 validation, not as a cast error.
  v_story_id_text := COALESCE(
    p_manifest->'story_metadata'->>'id',
    p_manifest->>'story_id'
  );

  IF v_story_id_text IS NULL
     OR v_story_id_text !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    RAISE EXCEPTION 'Invalid or missing story id in manifest' USING ERRCODE = '22023';
  END IF;
  v_story_id := v_story_id_text::uuid;

  SELECT EXISTS (
    SELECT 1 FROM partner_stories WHERE id = v_story_id
  ) INTO v_story_exists;

  IF NOT v_story_exists THEN
    RAISE EXCEPTION 'Story not found: %', v_story_id USING ERRCODE = '22023';
  END IF;

  -- Load source instance (the promoting replica)
  SELECT si.id, si.story_id, si.is_origin, si.status
  INTO v_source_instance
  FROM story_instances si
  WHERE si.id = p_source_instance_id;

  IF v_source_instance.id IS NULL THEN
    RAISE EXCEPTION 'Source instance not found: %', p_source_instance_id USING ERRCODE = '22023';
  END IF;

  IF v_source_instance.story_id != v_story_id THEN
    RAISE EXCEPTION 'Instance % does not belong to story %', p_source_instance_id, v_story_id USING ERRCODE = '22023';
  END IF;

  -- ===== AUTHORIZATION =====
  -- Token provided: validate via instance auth (scope 'sync:promote' + origin rules
  -- + blocked domains). No token: require admin/staff and apply the same policy
  -- filter directly.
  IF p_instance_token IS NOT NULL THEN
    v_auth_result := public.validate_sync_authorization(
      p_source_instance_id, p_instance_token, 'promote', v_story_id
    );

    IF NOT (v_auth_result->>'authorized')::boolean THEN
      -- user_id may be NULL (token/service actor) — FK-safe, see
      -- validate_sync_authorization.sql
      INSERT INTO audit_journal (user_id, action, metadata)
      VALUES (v_user_id, 'SYNC_PROMOTE_DENIED', jsonb_build_object(
        'area', 'story_sync', 'severity', 'warning',
        'story_id', v_story_id,
        'source_instance_id', p_source_instance_id,
        'reason', v_auth_result->>'reason'
      ));

      RETURN jsonb_build_object(
        'status', 'denied',
        'reason', v_auth_result->>'reason'
      );
    END IF;

    v_blocked_domains := COALESCE(v_auth_result->'blocked_domains', '[]'::jsonb);
  ELSE
    IF v_user_id IS NULL THEN
      RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '22023';
    END IF;

    IF NOT public.is_admin_or_staff() THEN
      RAISE EXCEPTION 'Unauthorized: provide instance token or use admin/staff account' USING ERRCODE = '22023';
    END IF;

    -- Same origin rule as the token path: origin does not promote to itself
    IF v_source_instance.is_origin THEN
      RAISE EXCEPTION 'Origin does not promote to itself' USING ERRCODE = '22023';
    END IF;

    -- Same policy filter as validate_sync_authorization for 'promote'
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'data_domain', sp.data_domain,
      'flow_direction', sp.flow_direction::text,
      'blocked', true
    ) ORDER BY sp.data_domain), '[]'::jsonb) INTO v_blocked_domains
    FROM story_sync_policies sp
    WHERE sp.story_id = v_story_id
      AND sp.flow_direction <> 'promote_on_approval';
  END IF;

  -- ===== INTEGRITY VERIFICATION =====
  v_computed_hash := encode(digest(p_manifest::text, 'sha256'), 'hex');

  IF v_computed_hash != p_manifest_hash THEN
    INSERT INTO audit_journal (user_id, action, metadata)
    VALUES (v_user_id, 'SYNC_INTEGRITY_VIOLATION', jsonb_build_object(
      'area', 'story_sync', 'severity', 'critical',
      'story_id', v_story_id,
      'source_instance_id', p_source_instance_id,
      'operation_type', 'promote',
      'expected_hash', p_manifest_hash,
      'computed_hash', v_computed_hash
    ));

    RETURN jsonb_build_object(
      'status', 'integrity_error',
      'reason', 'Manifest hash mismatch — possible tampering detected'
    );
  END IF;

  -- ===== PROMOTABLE PAYLOAD =====
  -- Domain → manifest section mapping: 'knowledge_items' → knowledge_items.
  -- v1 materializes knowledge_items only; other promote_on_approval domains
  -- would extend v_payload here.
  SELECT COALESCE(array_agg(bd->>'data_domain'), '{}')
  INTO v_blocked_domain_names
  FROM jsonb_array_elements(v_blocked_domains) bd
  WHERE (bd->>'blocked')::boolean = true;

  IF NOT ('knowledge_items' = ANY (v_blocked_domain_names))
     AND jsonb_typeof(p_manifest->'knowledge_items') = 'array'
  THEN
    v_knowledge_items := p_manifest->'knowledge_items';
    v_ki_count := jsonb_array_length(v_knowledge_items);
  END IF;

  IF v_ki_count = 0 THEN
    RETURN jsonb_build_object(
      'status', 'nothing_to_promote',
      'reason', 'Manifest carries no data in promotable domains (v1: knowledge_items)',
      'blocked_domains', v_blocked_domains
    );
  END IF;

  v_payload := jsonb_build_object('knowledge_items', v_knowledge_items);

  -- Resolve the origin instance of the story (promotion target)
  SELECT si.id INTO v_origin_instance_id
  FROM story_instances si
  WHERE si.story_id = v_story_id AND si.is_origin = true;

  IF v_origin_instance_id IS NULL THEN
    RAISE EXCEPTION 'No origin instance registered for story %', v_story_id USING ERRCODE = '22023';
  END IF;

  -- Create PENDING promote operation carrying the promotable payload
  INSERT INTO story_sync_operations (
    story_id, operation_type,
    source_instance_id, target_instance_id,
    ruleset_fingerprint,
    actor_ref, actor_type, outcome,
    metadata
  ) VALUES (
    v_story_id, 'promote',
    p_source_instance_id, v_origin_instance_id,
    p_manifest->'ruleset'->>'fingerprint',
    COALESCE(v_user_id::text, 'instance:' || p_source_instance_id::text),
    CASE WHEN p_instance_token IS NOT NULL THEN 'instance' ELSE 'human' END,
    'pending',
    jsonb_build_object(
      'manifest_hash', p_manifest_hash,
      'manifest_schema_version', p_manifest->>'schema_version',
      'payload', v_payload,
      'counts', jsonb_build_object('knowledge_items', v_ki_count),
      'blocked_domains', v_blocked_domains
    )
  ) RETURNING id INTO v_operation_id;

  -- Audit journal (user_id may be NULL — FK-safe)
  INSERT INTO audit_journal (user_id, action, metadata)
  VALUES (v_user_id, 'STORY_PROMOTE_PROPOSED', jsonb_build_object(
    'area', 'story_sync',
    'severity', 'info',
    'entity_type', 'story_sync_operation',
    'entity_id', v_operation_id,
    'story_id', v_story_id,
    'source_instance_id', p_source_instance_id,
    'target_instance_id', v_origin_instance_id,
    'manifest_hash', p_manifest_hash,
    'promotable_items', v_ki_count
  ));

  RETURN jsonb_build_object(
    'operation_id', v_operation_id,
    'status', 'pending',
    'promotable_items', v_ki_count
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.promote_story_bundle(jsonb, text, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.promote_story_bundle(jsonb, text, uuid, text) TO authenticated;
-- Token-authenticated replicas call through the stack backend under service_role
-- (auth.uid() IS NULL) — the token itself is validated inside.
GRANT EXECUTE ON FUNCTION public.promote_story_bundle(jsonb, text, uuid, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/validate_test_answers.sql
-- -----------------------------------------------------------------------------

-- Function: public.validate_test_answers
-- Arguments: p_test_type text, p_answers jsonb
-- Description: Validates test answers and returns score. Used in public quiz flow.
-- Security: SECURITY DEFINER - public quiz validation.
-- @security: public
-- @audit: none

CREATE OR REPLACE FUNCTION public.validate_test_answers(p_test_type text, p_answers jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total_questions integer;
  v_correct_count integer := 0;
  v_question record;
  v_user_answer text;
BEGIN
  -- Count total active questions for this test type
  SELECT COUNT(*) INTO v_total_questions
  FROM test_questions
  WHERE test_type = p_test_type AND is_active = true;

  -- Check each answer
  FOR v_question IN 
    SELECT id, correct_answer 
    FROM test_questions 
    WHERE test_type = p_test_type AND is_active = true
  LOOP
    v_user_answer := p_answers->>v_question.id::text;
    IF v_user_answer IS NOT NULL AND v_user_answer = v_question.correct_answer THEN
      v_correct_count := v_correct_count + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'total_questions', v_total_questions,
    'correct_count', v_correct_count,
    'score', CASE WHEN v_total_questions > 0 
      THEN ROUND((v_correct_count::numeric / v_total_questions::numeric) * 100)
      ELSE 0 
    END,
    'passed', CASE WHEN v_total_questions > 0 
      THEN (v_correct_count::numeric / v_total_questions::numeric) >= 0.75
      ELSE false 
    END
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.validate_test_answers(p_test_type text, p_answers jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.validate_test_answers(p_test_type text, p_answers jsonb) TO public;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/assign_member_role_after_qualification.sql
-- -----------------------------------------------------------------------------

-- Function: public.assign_member_role_after_qualification
-- Arguments: p_test_type text, p_answers jsonb
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:25:52+01:00

CREATE OR REPLACE FUNCTION public.assign_member_role_after_qualification(p_test_type text, p_answers jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
  v_user_id uuid;
  v_passed boolean;
  v_existing_role_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'User not authenticated'
    );
  END IF;

  -- Validate test answers using existing function
  v_result := validate_test_answers(p_test_type, p_answers);
  v_passed := (v_result->>'passed')::boolean;

  -- Record server-authored evidence of every qualification attempt. This is the
  -- non-forgeable source of truth for is_qualified() — clients no longer hold write
  -- access to qualification_results (see grants), so only this SECURITY DEFINER path
  -- can attest a pass. Score is the server-graded value, never client-supplied.
  IF p_test_type = 'qualification' THEN
    INSERT INTO public.qualification_results (user_id, score, passed, completed_at, answers)
    VALUES (
      v_user_id,
      COALESCE((v_result->>'score')::integer, 0),
      v_passed,
      now(),
      p_answers
    );
  END IF;

  -- If passed qualification test, assign member role
  IF v_passed AND p_test_type = 'qualification' THEN
    SELECT id INTO v_existing_role_id
    FROM public.user_roles
    WHERE user_id = v_user_id AND role = 'member';

    IF v_existing_role_id IS NULL THEN
      INSERT INTO public.user_roles (user_id, role)
      VALUES (v_user_id, 'member');
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'passed', v_passed,
    'total_questions', v_result->'total_questions',
    'correct_count', v_result->'correct_count',
    'score', v_result->'score',
    'role_assigned', (v_passed AND p_test_type = 'qualification')
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.assign_member_role_after_qualification(p_test_type text, p_answers jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.assign_member_role_after_qualification(p_test_type text, p_answers jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/validate_voucher_code.sql
-- -----------------------------------------------------------------------------

-- Function: public.validate_voucher_code
-- Validates a voucher code without redeeming. Returns voucher details if valid.

CREATE OR REPLACE FUNCTION public.validate_voucher_code(
  p_code text
)
RETURNS TABLE (
  id uuid,
  code text,
  product_id uuid,
  status text,
  points_cost int4,
  expires_at timestamptz
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_normalized_code text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_code IS NULL OR btrim(p_code) = '' THEN
    RAISE EXCEPTION 'Voucher code is required' USING ERRCODE = '22023';
  END IF;

  v_normalized_code := upper(btrim(p_code));

  RETURN QUERY
  SELECT
    pv.id,
    pv.code,
    pv.product_id,
    pv.status,
    pv.points_cost,
    pv.expires_at
  FROM public.product_vouchers pv
  WHERE pv.code = v_normalized_code
    AND pv.status = 'active'
    AND (pv.user_id IS NULL OR pv.user_id = v_user_id)
    AND (pv.expires_at IS NULL OR pv.expires_at > now());
END;
$function$;

REVOKE ALL ON FUNCTION public.validate_voucher_code(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.validate_voucher_code(text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/vault_create_secret.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: vault.create_secret
--
-- Zašifruje hodnotu klíčem trezoru a uloží ji do vault.secrets; vrátí id.
-- Dřív jen v infra/postgres/001_vault_pgcrypto.sql (initdb) s klíčem z GUC
-- a BEZ `REVOKE … FROM PUBLIC` — spustit ji tak mohl kdokoli s USAGE na
-- schématu vault (authenticated ho má). Domov je teď tady + heals.sql.
-- ============================================================================

-- ⛔ pgcrypto leží ve schématu `extensions` (000_init_roles_schemas.sql). Původní
-- initdb definice měla `search_path = vault, public` a pgp_sym_encrypt tak
-- nenašla — naměřeno 2026-09-25 (test:db:tajemstvi). Volá se proto s výslovným
-- schématem.
CREATE OR REPLACE FUNCTION vault.create_secret(
    new_secret text,
    new_name text DEFAULT NULL,
    new_description text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'  -- vše výslovně kvalifikované: vault.*, extensions.*, public.*
AS $$
DECLARE
    v_id uuid;
BEGIN
    INSERT INTO vault.secrets (name, secret, description)
    VALUES (
        new_name,
        extensions.pgp_sym_encrypt(new_secret, public.aisha_vault_encryption_key()),
        new_description
    )
    RETURNING id INTO v_id;

    RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION vault.create_secret(text, text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION vault.create_secret(text, text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/vault_update_secret.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of truth: vault.update_secret
--
-- Přepíše tajemství podle id (hodnotu zašifruje klíčem trezoru). Dřív jen
-- v infra/postgres/001_vault_pgcrypto.sql (initdb) s klíčem z GUC a BEZ
-- `REVOKE … FROM PUBLIC`. Domov je teď tady + heals.sql.
-- ============================================================================

-- ⛔ pgcrypto leží ve schématu `extensions` (000_init_roles_schemas.sql). Původní
-- initdb definice měla `search_path = vault, public` a pgp_sym_encrypt tak
-- nenašla — naměřeno 2026-09-25 (test:db:tajemstvi). Volá se proto s výslovným
-- schématem.
CREATE OR REPLACE FUNCTION vault.update_secret(
    secret_id uuid,
    new_secret text DEFAULT NULL,
    new_name text DEFAULT NULL,
    new_description text DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'pg_temp'  -- vše výslovně kvalifikované: vault.*, extensions.*, public.*
AS $$
BEGIN
    UPDATE vault.secrets
    SET
        -- ⛔ NAMĚŘENO 2026-09-28 (Cleenack, UPGRADE #1080 nad PG17): `secret` je `text`
        -- (substrát 000_init), pgp_sym_encrypt vrací `bytea` → CASE bez přetypování
        -- padal „CASE types bytea and text cannot be matched" a KAŽDÁ změna tajemství
        -- selhala. `::text` = týž I/O tvar ('\x…'), jaký zapíše přiřazení v create_secret
        -- a jaký vault.decrypted_secrets čte zpět přes `::bytea`.
        secret      = CASE
                        WHEN new_secret IS NULL THEN secret
                        ELSE extensions.pgp_sym_encrypt(new_secret, public.aisha_vault_encryption_key())::text
                      END,
        name        = COALESCE(new_name, name),
        description = COALESCE(new_description, description),
        updated_at  = now()
    WHERE id = secret_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'vault secret with id % not found', secret_id;
    END IF;
END;
$$;

REVOKE ALL ON FUNCTION vault.update_secret(uuid, text, text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION vault.update_secret(uuid, text, text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/vehicle_dq_status.sql
-- -----------------------------------------------------------------------------

-- Function: vehicle_dq_status
-- Focused read of the vehicle data-quality posture for the AISHA management
-- surface ("kolik a jakých" — how many / what kinds). Returns the LATEST
-- AITG-DAT-* run per test joined to the catalog (title, remediation_ref,
-- severity_weight) plus a rollup. Reads ONLY the generic AITG tables
-- (aitg_runs × aitg_test_catalog, layer='dat'); whoever writes the runs — an
-- instance's data-quality runner, a plugin, a scheduled probe — is outside this
-- function's contract. Called by svc-mcp-knowledge (routes/mcp.ts, lib/aitg-tools.ts).
-- Mirrors aitg_health_summary_audited (SECURITY DEFINER + service_role/admin
-- authZ + audited read).

CREATE OR REPLACE FUNCTION public.vehicle_dq_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_service boolean;
  v_out jsonb;
BEGIN
  -- Kanonická čtečka, ne ruční parsování claimu: `current_setting(…, true)` vrací
  -- při chybějícím claimu NULL, takže `NULL = 'service_role'` je NULL a `NOT NULL`
  -- je zase NULL — deny větev se pak NEPROVEDE a guard je fail-OPEN, přestože
  -- vypadá přísně (brána deny-guard-null-fold, #588). is_service_role() je totální.
  v_is_service := public.is_service_role();
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'AITG_INSUFFICIENT_PRIVILEGE' USING ERRCODE = '42501';
  END IF;

  WITH latest AS (
    SELECT DISTINCT ON (r.test_id)
           r.test_id, r.status, r.severity, r.build_sha, r.details, r.finished_at
    FROM public.aitg_runs r
    WHERE r.test_id ~ '^AITG-DAT-[56][0-9]$'   -- reserved vehicle-registry block (50..69); excludes framework probe AITG-DAT-02
    ORDER BY r.test_id, r.finished_at DESC NULLS LAST
  ),
  joined AS (
    SELECT l.test_id, c.title, c.remediation_ref, c.severity_weight,
           l.status, l.severity, l.build_sha,
           l.details->'observed' AS observed, l.finished_at
    FROM latest l
    JOIN public.aitg_test_catalog c ON c.test_id = l.test_id AND c.layer = 'dat'
  )
  SELECT jsonb_build_object(
    'snapshot',      (SELECT max(build_sha) FROM joined),
    'checks_total',  (SELECT count(*)::int FROM joined),
    'failed',        (SELECT count(*)::int FROM joined WHERE status = 'failed'),
    'passed',        (SELECT count(*)::int FROM joined WHERE status = 'passed'),
    'worst_severity',(SELECT severity FROM joined WHERE status = 'failed'
                       ORDER BY CASE severity WHEN 'critical' THEN 0 WHEN 'high' THEN 1
                                              WHEN 'medium' THEN 2 WHEN 'low' THEN 3 ELSE 4 END
                       LIMIT 1),
    'checks', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'test_id', test_id, 'title', title, 'status', status, 'severity', severity,
               'observed', observed, 'remediation_ref', remediation_ref,
               'snapshot', build_sha, 'checked_at', finished_at)
             ORDER BY CASE status WHEN 'failed' THEN 0 ELSE 1 END,
                      CASE severity WHEN 'critical' THEN 0 WHEN 'high' THEN 1
                                    WHEN 'medium' THEN 2 WHEN 'low' THEN 3 ELSE 4 END)
      FROM joined), '[]'::jsonb)
  ) INTO v_out;

  INSERT INTO public.audit_journal (user_id, action, action_type, area, severity, tags, details)
  VALUES (auth.uid(), 'vehicle_dq.status_read', 'vehicle_dq.status_read',
          'data_quality', 'info', ARRAY['vehicle','dq'], v_out);

  RETURN v_out;
END;
$function$
;

REVOKE ALL ON FUNCTION public.vehicle_dq_status() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.vehicle_dq_status() TO authenticated;
GRANT EXECUTE ON FUNCTION public.vehicle_dq_status() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/wd_list_sync_vehicle_ids.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_list_sync_vehicle_ids
-- Popis: Seznam wd_car_id aktivních vozidel pro per-vozidlo sync
--        (kniha jízd _getCarLogBook4 se volá po jednom vozidle).
--        Volá svc-webdispecink před importem jízd.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT; read-only (STABLE)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.wd_list_sync_vehicle_ids()
RETURNS TABLE (wd_car_id integer)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  -- Canonical boolean-NOT-NULL service check (is_service_role.sql, #588): the
  -- prior inline claims idiom folds to SQL NULL without a role claim and the
  -- negative deny-guard below then fails OPEN. is_service_role() COALESCEs to
  -- false, so the guard is total (fails CLOSED).
  v_is_service boolean := public.is_service_role();
BEGIN
  -- Authorization check (FIRST, before any data access)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  RETURN QUERY
  SELECT v.wd_car_id
  FROM public.wd_vehicles v
  WHERE v.active = true
  ORDER BY v.wd_car_id;
END;
$$;

REVOKE ALL ON FUNCTION public.wd_list_sync_vehicle_ids() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.wd_list_sync_vehicle_ids() TO authenticated;
GRANT EXECUTE ON FUNCTION public.wd_list_sync_vehicle_ids() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/wd_project_rides.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_project_rides
-- Popis: TENKÝ ADAPTÉR kniha jízd Webdispečinku (wd_rides) → twin_project_trips.
--        Přeloží řádky do tvaru jádra; identitu, druh entity, porovnání
--        a zápis dělá jádro (dráha 'webdispecink:trip').
--
-- Klíče stejné jako wd_propose_identity: vozidlo = holé wd_car_id, řidič =
-- 'ridic:<wd_driver_id>' (zdroj identity 'webdispecink').
--
-- Které jízdy posílá (šetrně — volá se po každé synchronizaci):
--   • dosud NEPROMÍTNUTÉ jízdy vozidel s potvrzenou a k času jízdy platnou
--     vazbou (levné předběžné síto; rozhoduje jádro),
--   • jízdy, na které synchronizace sáhla v posledních `p_okno_min` minutách
--     (dodavatel opravuje zpětně; jádro zapíše jen skutečné změny).
-- Jízdy bez platné vazby se jen spočítají (`ceka_na_vazbu`) a promítnou se
-- samy, až člověk vazbu potvrdí.
--
-- Atributy = jen to, co je o VOZIDLE a jízdě: kilometry, tachometr, doba jízdy
-- a stání, druh jízdy. Místa začátku a konce, účel, posádka ani poznámka se
-- NEPŘENÁŠEJÍ (polohy majitel nepovolil, adresa soukromé jízdy i posádka jsou
-- osobní údaje); nejvyšší rychlost také ne (hodnocení chování řidiče).
--
-- Vrací: výsledek twin_project_trips + {ceka_na_vazbu}
-- Bezpečnost: SECURITY DEFINER; jen service_role (volá plugin přes broker).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.wd_project_rides(
  p_okno_min integer DEFAULT 180,
  p_limit    integer DEFAULT 5000
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  c_source   constant text := 'webdispecink';
  v_source   text;
  v_lane     text;
  v_rows     jsonb;
  v_ceka     integer;
  v_vysledek jsonb;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'wd_project_rides: service role required'
      USING ERRCODE = '42501';
  END IF;
  IF p_okno_min IS NULL OR p_okno_min < 0 OR p_okno_min > 10080 THEN
    RAISE EXCEPTION 'wd_project_rides: p_okno_min must be between 0 and 10080'
      USING ERRCODE = '22023';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 20000 THEN
    RAISE EXCEPTION 'wd_project_rides: p_limit must be between 1 and 20000'
      USING ERRCODE = '22023';
  END IF;
  v_source := public.canonical_ingest_source(c_source);
  v_lane   := v_source || ':trip';

  WITH vse AS (
    SELECT r.wd_ride_id, r.wd_car_id, r.wd_driver_id, r.start_time, r.end_time,
           r.distance_km, r.odometer_start_km, r.odometer_end_km, r.driving_seconds,
           r.standing_seconds, r.ride_type, r.updated_at,
           EXISTS (SELECT 1 FROM public.twin_events e
                    WHERE e.source = v_lane AND e.event_type = 'trip'
                      AND e.source_ref = r.wd_ride_id::text) AS promitnuto,
           EXISTS (SELECT 1 FROM public.twin_external_refs b
                    WHERE b.source = v_source AND b.source_key = r.wd_car_id::text
                      AND b.ref_kind = 'primary_id' AND b.state = 'confirmed'
                      AND b.valid_from <= r.start_time
                      AND (b.valid_to IS NULL OR b.valid_to > r.start_time)) AS vazba
      FROM public.wd_rides r
     WHERE r.start_time IS NOT NULL
  ),
  kandidati AS (
    SELECT a.wd_ride_id, a.wd_car_id, a.wd_driver_id, a.start_time, a.end_time,
           a.distance_km, a.odometer_start_km, a.odometer_end_km, a.driving_seconds,
           a.standing_seconds, a.ride_type
      FROM vse a
     WHERE a.vazba
       AND (NOT a.promitnuto OR a.updated_at >= now() - make_interval(mins => p_okno_min))
     ORDER BY a.start_time
     LIMIT p_limit
  )
  SELECT
    (SELECT coalesce(jsonb_agg(jsonb_build_object(
              'source_ref',  k.wd_ride_id::text,
              'vehicle_key', k.wd_car_id::text,
              'driver_key',  'ridic:' || k.wd_driver_id,
              'started_at',  k.start_time,
              'ended_at',    k.end_time,
              'attrs',       jsonb_strip_nulls(jsonb_build_object(
                               'distance_km',       k.distance_km,
                               'odometer_start_km', k.odometer_start_km,
                               'odometer_end_km',   k.odometer_end_km,
                               'driving_seconds',   k.driving_seconds,
                               'standing_seconds',  k.standing_seconds,
                               'ride_type',         k.ride_type))
            ) ORDER BY k.start_time), '[]'::jsonb)
       FROM kandidati k),
    (SELECT count(*) FROM vse a WHERE NOT a.promitnuto AND NOT a.vazba)
  INTO v_rows, v_ceka;

  v_vysledek := public.twin_project_trips(c_source, v_rows);
  RETURN v_vysledek || jsonb_build_object('ceka_na_vazbu', v_ceka);
END;
$$;

REVOKE ALL ON FUNCTION public.wd_project_rides(integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.wd_project_rides(integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/wd_project_worktime.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_project_worktime
-- Popis: TENKÝ ADAPTÉR denních výkonů řidičů z tachografu Webdispečinku
--        (wd_worktime, _getDriverWorkTacho) → twin_project_events. Událost
--        'driver_hours_day' na dvojčeti ŘIDIČE, dráha 'webdispecink:tachograph'
--        — přesně tvar, který čte katalog (driver_drive_h: attr drive_seconds,
--        převod na hodiny dělá katalog, ne adaptér).
--
-- Jeden řádek = řidič × den × vozidlo (tachograf dělí den podle vozidla); jedna
-- událost na řádek, takže součet za den je součet řádků. `occurred_at` je
-- půlnoc UTC daného dne a je to ŠTÍTEK PŘIHRÁDKY, ne okamžik — dodavatel dává
-- kalendářní den bez zóny; autoritativní je `attrs.work_date`.
--
-- Klíč řidiče 'ridic:<wd_driver_id>' (stejně jako wd_propose_identity).
-- Pracovní doba řidiče je osobní údaj: přenáší se jen souhrnné doby za den
-- a SPZ vozidla z tachografu, žádná místa ani nepřítomnosti (absences).
--
-- Které dny posílá: nepromítnuté dny řidičů s potvrzenou a k danému dni
-- platnou vazbou + dny, na které synchronizace sáhla v posledních `p_okno_min`
-- minutách (dnešek se doplňuje, ověřené dny chodí později).
--
-- Vrací: výsledek twin_project_events + {ceka_na_vazbu}
-- Bezpečnost: SECURITY DEFINER; jen service_role (volá plugin přes broker).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.wd_project_worktime(
  p_okno_min integer DEFAULT 180,
  p_limit    integer DEFAULT 5000
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  c_source   constant text := 'webdispecink';
  v_source   text;
  v_lane     text;
  v_rows     jsonb;
  v_ceka     integer;
  v_vysledek jsonb;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'wd_project_worktime: service role required'
      USING ERRCODE = '42501';
  END IF;
  IF p_okno_min IS NULL OR p_okno_min < 0 OR p_okno_min > 10080 THEN
    RAISE EXCEPTION 'wd_project_worktime: p_okno_min must be between 0 and 10080'
      USING ERRCODE = '22023';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 20000 THEN
    RAISE EXCEPTION 'wd_project_worktime: p_limit must be between 1 and 20000'
      USING ERRCODE = '22023';
  END IF;
  v_source := public.canonical_ingest_source(c_source);
  v_lane   := v_source || ':tachograph';

  WITH dny AS (
    SELECT w.wd_driver_id, w.work_date, w.car_identifikator, w.day_type,
           w.total_drive_seconds, w.total_work_seconds, w.total_rest_seconds,
           w.total_standby_seconds, w.night_drive_seconds, w.distance_km, w.updated_at,
           w.wd_driver_id || ':' || w.work_date || ':' || w.car_identifikator AS klic_dne,
           (w.work_date::timestamp AT TIME ZONE 'UTC') AS stitek
      FROM public.wd_worktime w
  ),
  vse AS (
    SELECT d.wd_driver_id, d.work_date, d.car_identifikator, d.day_type,
           d.total_drive_seconds, d.total_work_seconds, d.total_rest_seconds,
           d.total_standby_seconds, d.night_drive_seconds, d.distance_km, d.updated_at,
           d.klic_dne, d.stitek,
           EXISTS (SELECT 1 FROM public.twin_events e
                    WHERE e.source = v_lane AND e.event_type = 'driver_hours_day'
                      AND e.source_ref = d.klic_dne) AS promitnuto,
           EXISTS (SELECT 1 FROM public.twin_external_refs b
                    WHERE b.source = v_source AND b.source_key = 'ridic:' || d.wd_driver_id
                      AND b.ref_kind = 'primary_id' AND b.state = 'confirmed'
                      AND b.valid_from <= d.stitek
                      AND (b.valid_to IS NULL OR b.valid_to > d.stitek)) AS vazba
      FROM dny d
  ),
  kandidati AS (
    SELECT a.wd_driver_id, a.work_date, a.car_identifikator, a.day_type,
           a.total_drive_seconds, a.total_work_seconds, a.total_rest_seconds,
           a.total_standby_seconds, a.night_drive_seconds, a.distance_km, a.klic_dne, a.stitek
      FROM vse a
     WHERE a.vazba
       AND (NOT a.promitnuto OR a.updated_at >= now() - make_interval(mins => p_okno_min))
     ORDER BY a.work_date, a.wd_driver_id
     LIMIT p_limit
  )
  SELECT
    (SELECT coalesce(jsonb_agg(jsonb_build_object(
              'event_type',  'driver_hours_day',
              'lane',        'tachograph',
              'source_ref',  k.klic_dne,
              'subject',     jsonb_build_object('key', 'ridic:' || k.wd_driver_id,
                                                'ref_kind', 'primary_id', 'entity_type', 'driver'),
              'occurred_at', k.stitek,
              'attrs',       jsonb_strip_nulls(jsonb_build_object(
                               'work_date',            k.work_date,
                               'drive_seconds',        k.total_drive_seconds,
                               'work_seconds',         k.total_work_seconds,
                               'rest_seconds',         k.total_rest_seconds,
                               'availability_seconds', k.total_standby_seconds,
                               'night_drive_seconds',  k.night_drive_seconds,
                               'distance_km',          k.distance_km,
                               'day_type',             k.day_type,
                               'car',                  nullif(k.car_identifikator, '')))
            ) ORDER BY k.work_date, k.wd_driver_id), '[]'::jsonb)
       FROM kandidati k),
    (SELECT count(*) FROM vse a WHERE NOT a.promitnuto AND NOT a.vazba)
  INTO v_rows, v_ceka;

  v_vysledek := public.twin_project_events(c_source, v_rows);
  RETURN v_vysledek || jsonb_build_object('ceka_na_vazbu', v_ceka);
END;
$$;

REVOKE ALL ON FUNCTION public.wd_project_worktime(integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.wd_project_worktime(integer, integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/wd_propose_identity.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_propose_identity
-- Popis: TENKÝ ADAPTÉR číselníků Webdispečinku (wd_vehicles, wd_drivers) →
--        twin_propose_identity_by_signals. Řekne, který údaj WD odpovídá
--        kterému druhu reference ve světě dvojčat; párování, jistotu a návrhy
--        dělá obecné jádro. Nic nezakládá a nic nepotvrzuje.
--
-- Zdroj identity je 'webdispecink' — kanonický slug světa dvojčat (stejný jako
-- wd_twin_fleet_current), ne slug pluginu 'webdispecink-fleet'.
-- Klíče: vozidlo = HOLÉ wd_car_id (konvence jádra, wd_twin_fleet_current),
-- řidič = 'ridic:<wd_driver_id>' — vazba identity je jedinečná jen v (source,
-- source_key, ref_kind), bez druhu entity, a WD čísluje vozidla i řidiče
-- vlastní řadou; holé číslo řidiče by kolidovalo s vozidlem (třída chyby
-- nalezená u T-cars 2026-09-27). Stejné klíče musí skládat wd_project_rides
-- i wd_project_worktime. Změřeno 2026-09-27: v produkci pod 'webdispecink'
-- žádná vazba neexistuje, nový tvar tedy nic nezdvojí.
--
-- Signály a síla (1 − Π(1 − w) přes shodné):
--   vozidlo  identifikátor (SPZ nebo název) → vehicle_plate/_machine_plate/_machine_id  0,6
--            RZ v popisu vozidla             → vehicle_plate/_machine_plate              0,5
--   řidič    osobní číslo                    → driver_personal_number                    0,7
--            jméno a příjmení                → driver_name                               0,3
--
-- Vrací: {vozidla, ridici: <výsledek jádra>}
-- Bezpečnost: SECURITY DEFINER; jen service_role (volá plugin přes broker).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.wd_propose_identity()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  c_source  constant text := 'webdispecink';
  v_vozidla jsonb;
  v_ridici  jsonb;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'wd_propose_identity: service role required'
      USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'source_key', v.wd_car_id::text,
           'signals', jsonb_path_query_array(jsonb_build_array(
             jsonb_build_object('kinds', jsonb_build_array('vehicle_plate', 'vehicle_machine_plate', 'vehicle_machine_id'),
                                'value', nullif(btrim(v.identifier), ''), 'weight', 0.6),
             jsonb_build_object('kinds', jsonb_build_array('vehicle_plate', 'vehicle_machine_plate'),
                                'value', x.rz[1] || x.rz[2], 'weight', 0.5)),
             '$[*] ? (@.value != null)')
         ) ORDER BY v.wd_car_id), '[]'::jsonb)
    INTO v_vozidla
    FROM public.wd_vehicles v
    CROSS JOIN LATERAL (
      SELECT regexp_match(upper(coalesce(v.description, '')), '([0-9][A-Z][A-Z0-9]) ?([0-9]{4})') AS rz
    ) x
   WHERE v.active;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'source_key', 'ridic:' || d.wd_driver_id,
           'signals', jsonb_path_query_array(jsonb_build_array(
             jsonb_build_object('kinds', jsonb_build_array('driver_personal_number'),
                                'value', nullif(btrim(d.personal_number), ''), 'weight', 0.7),
             jsonb_build_object('kinds', jsonb_build_array('driver_name'),
                                'value', nullif(btrim(concat_ws(' ', d.first_name, d.last_name)), ''), 'weight', 0.3)),
             '$[*] ? (@.value != null)')
         ) ORDER BY d.wd_driver_id), '[]'::jsonb)
    INTO v_ridici
    FROM public.wd_drivers d
   WHERE d.active;

  RETURN jsonb_build_object(
    'vozidla', public.twin_propose_identity_by_signals(c_source, 'vehicle', v_vozidla, 'rule:signals'),
    'ridici',  public.twin_propose_identity_by_signals(c_source, 'driver',  v_ridici,  'rule:signals')
  );
END;
$$;

REVOKE ALL ON FUNCTION public.wd_propose_identity() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.wd_propose_identity() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/wd_record_import_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_record_import_audited
-- Popis: Životní cyklus záznamu ve wd_import_log. Volá svc-webdispecink:
--        p_action='start'  → založí běh (import_type), vrátí import_id
--        p_action='finish' → uzavře běh (status, počty, chyba)
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT
-- Audit: wd_import.started / wd_import.finished
-- ============================================================================

CREATE OR REPLACE FUNCTION public.wd_record_import_audited(
  p_action text,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  -- Canonical boolean-NOT-NULL service check (is_service_role.sql, #588): the
  -- prior inline claims idiom folds to SQL NULL without a role claim and the
  -- negative deny-guard below then fails OPEN. is_service_role() COALESCEs to
  -- false, so the guard is total (fails CLOSED).
  v_is_service boolean := public.is_service_role();
  v_import_id uuid;
  v_status text;
BEGIN
  -- Authorization check (FIRST, before any data access)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  IF p_action = 'start' THEN
    IF p_payload->>'import_type' IS NULL THEN
      RAISE EXCEPTION 'import_type required';
    END IF;

    INSERT INTO public.wd_import_log (import_type, status, started_at)
    VALUES (p_payload->>'import_type', 'running', now())
    RETURNING id INTO v_import_id;

    INSERT INTO public.audit_journal (user_id, action, metadata)
    VALUES (
      auth.uid(),
      'wd_import.started',
      jsonb_build_object(
        'import_id', v_import_id,
        'import_type', p_payload->>'import_type'
      )
    );

    RETURN jsonb_build_object('import_id', v_import_id);
  END IF;

  IF p_action = 'finish' THEN
    IF p_payload->>'import_id' IS NULL THEN
      RAISE EXCEPTION 'import_id required';
    END IF;

    v_import_id := (p_payload->>'import_id')::uuid;
    v_status := COALESCE(p_payload->>'status', 'success');
    IF v_status NOT IN ('success', 'error') THEN
      RAISE EXCEPTION 'status must be success or error';
    END IF;

    UPDATE public.wd_import_log SET
      status           = v_status,
      finished_at      = now(),
      records_total    = (p_payload->>'records_total')::integer,
      records_upserted = (p_payload->>'records_upserted')::integer,
      records_failed   = (p_payload->>'records_failed')::integer,
      error_message    = p_payload->>'error_message',
      details          = p_payload->'details'
    WHERE id = v_import_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Import run % not found', v_import_id;
    END IF;

    INSERT INTO public.audit_journal (user_id, action, metadata)
    VALUES (
      auth.uid(),
      'wd_import.finished',
      jsonb_build_object(
        'import_id', v_import_id,
        'status', v_status,
        'records_total', (p_payload->>'records_total')::integer,
        'records_upserted', (p_payload->>'records_upserted')::integer
      )
    );

    RETURN jsonb_build_object('import_id', v_import_id, 'status', v_status);
  END IF;

  RAISE EXCEPTION 'Unsupported action: %', p_action;
END;
$$;

REVOKE ALL ON FUNCTION public.wd_record_import_audited(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.wd_record_import_audited(text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.wd_record_import_audited(text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/wd_twin_fleet_current.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_twin_fleet_current
-- Popis: Dispečerská mapa v DOMÉNOVÉM tvaru (zadání digital twin §7: extranet
--        nezná raw strukturu zdroje): aktuální polohy z wd_vehicle_positions_
--        current obohacené o twin identity — vozidlo přes potvrzenou primární
--        ref, řidič TEMPORÁLNĚ přes čip (ref_kind='field_identity',
--        driver_card, platnost k position_time — jízda se resolvne na
--        TEHDEJŠÍHO držitele čipu, ne dnešního).
--        Patří do wd_* domény (kanonický slug zdroje 'webdispecink' — stejná
--        vendor vazba jako wd_* tabulky); twin jádro samo zůstává generické.
--        Vozidla bez twinu se vracejí s vehicle_twin_id NULL (mapa je úplná,
--        chybějící mapování je vidět — kandidát na twin_upsert adaptérem).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (admin/staff/service — polohy
--        celé flotily nejsou „moje věci", viz twin_list_mine)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.wd_twin_fleet_current(
  p_limit integer DEFAULT 500
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean := public.is_service_role();
  v_items jsonb;
BEGIN
  -- Authorization check (FIRST, before any data access)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 2000 THEN
    RAISE EXCEPTION 'p_limit must be between 1 and 2000';
  END IF;

  SELECT COALESCE(jsonb_agg(item ORDER BY item->>'position_time' DESC), '[]'::jsonb) INTO v_items
  FROM (
    SELECT jsonb_build_object(
      'vehicle_twin_id', vt.twin_id,
      'vehicle_label', COALESCE(te.label, v.identifier),
      'wd_car_id', p.wd_car_id,
      'driver_twin_id', dt.twin_id,
      'driver_label', de.label,
      'position_time', p.position_time,
      'latitude', p.latitude,
      'longitude', p.longitude,
      'speed_kmh', p.speed_kmh,
      'moving', p.moving,
      'location_text', p.location_text,
      'odometer_km', p.odometer_km,
      'fuel_level', p.fuel_level
    ) AS item
    FROM public.wd_vehicle_positions_current p
    LEFT JOIN public.wd_vehicles v ON v.wd_car_id = p.wd_car_id
    -- vozidlo: potvrzená primární identita ve zdroji 'webdispecink'
    LEFT JOIN public.twin_external_refs vt
      ON vt.source = 'webdispecink'
     AND vt.ref_kind = 'primary_id'
     AND vt.entity_type = 'vehicle'
     AND vt.source_key = p.wd_car_id::text
     AND vt.state = 'confirmed'
     AND vt.valid_to IS NULL
    LEFT JOIN public.twin_entities te ON te.id = vt.twin_id
    -- řidič: čip TEMPORÁLNĚ k času polohy (handover-safe)
    LEFT JOIN public.twin_external_refs dt
      ON dt.source = 'webdispecink'
     AND dt.ref_kind = 'field_identity'
     AND dt.entity_type = 'driver'
     AND dt.source_key = p.driver_card
     AND dt.state = 'confirmed'
     AND dt.valid_from <= p.position_time
     AND (dt.valid_to IS NULL OR dt.valid_to > p.position_time)
    LEFT JOIN public.twin_entities de ON de.id = dt.twin_id
    ORDER BY p.position_time DESC
    LIMIT p_limit
  ) AS q;

  RETURN v_items;
END;
$$;

REVOKE ALL ON FUNCTION public.wd_twin_fleet_current(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.wd_twin_fleet_current(integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.wd_twin_fleet_current(integer) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/wd_upsert_drivers_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_upsert_drivers_audited
-- Popis: Batch upsert řidičů z Webdispečinku. Volá svc-webdispecink po
--        stažení _getDriversList2. Řidiči se nikdy nemažou — deaktivace
--        přijde z API přes pole active. Ruční mapování erp_employee_ref
--        se importem nepřepisuje. Vrací počty inserted/updated.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT
-- Audit: wd_drivers.import_completed s počty (bez PII)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.wd_upsert_drivers_audited(
  p_drivers jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  -- Canonical boolean-NOT-NULL service check (is_service_role.sql, #588): the
  -- prior inline claims idiom folds to SQL NULL without a role claim and the
  -- negative deny-guard below then fails OPEN. is_service_role() COALESCEs to
  -- false, so the guard is total (fails CLOSED).
  v_is_service boolean := public.is_service_role();
  v_batch jsonb;
  v_total integer;
  v_updated integer;
  v_inserted integer;
BEGIN
  -- Authorization check (FIRST, before any data access)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  -- Input validation
  IF p_drivers IS NULL OR jsonb_typeof(p_drivers) <> 'array' THEN
    RAISE EXCEPTION 'p_drivers must be a jsonb array';
  END IF;

  -- Dedup podle wd_driver_id — ON CONFLICT nesmí zasáhnout stejný řádek dvakrát
  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON ((item->>'wd_driver_id')::integer) item
    FROM jsonb_array_elements(p_drivers) AS item
    WHERE item->>'wd_driver_id' IS NOT NULL
  ) AS deduped;

  v_total := jsonb_array_length(v_batch);

  SELECT count(*) INTO v_updated
  FROM public.wd_drivers d
  WHERE d.wd_driver_id IN (
    SELECT (item->>'wd_driver_id')::integer
    FROM jsonb_array_elements(v_batch) AS item
  );

  INSERT INTO public.wd_drivers (
    wd_driver_id, first_name, last_name, personal_number,
    group_id, group_name, card_identifier, phone, active,
    assigned_vehicle, raw_data, last_import_at, updated_at
  )
  SELECT
    (item->>'wd_driver_id')::integer,
    item->>'first_name',
    item->>'last_name',
    item->>'personal_number',
    (item->>'group_id')::integer,
    item->>'group_name',
    item->>'card_identifier',
    item->>'phone',
    COALESCE((item->>'active')::boolean, true),
    item->>'assigned_vehicle',
    item->'raw',
    now(),
    now()
  FROM jsonb_array_elements(v_batch) AS item
  ON CONFLICT (wd_driver_id) DO UPDATE SET
    first_name       = EXCLUDED.first_name,
    last_name        = EXCLUDED.last_name,
    personal_number  = EXCLUDED.personal_number,
    group_id         = EXCLUDED.group_id,
    group_name       = EXCLUDED.group_name,
    card_identifier  = EXCLUDED.card_identifier,
    phone            = EXCLUDED.phone,
    active           = EXCLUDED.active,
    assigned_vehicle = EXCLUDED.assigned_vehicle,
    raw_data         = EXCLUDED.raw_data,
    last_import_at   = EXCLUDED.last_import_at,
    updated_at       = now();

  v_inserted := v_total - v_updated;

  -- Audit log (jen počty — jména a osobní čísla do auditu nepatří)
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'wd_drivers.import_completed',
    jsonb_build_object(
      'total', v_total,
      'inserted', v_inserted,
      'updated', v_updated
    )
  );

  RETURN jsonb_build_object(
    'total', v_total,
    'inserted', v_inserted,
    'updated', v_updated
  );
END;
$$;

REVOKE ALL ON FUNCTION public.wd_upsert_drivers_audited(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.wd_upsert_drivers_audited(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.wd_upsert_drivers_audited(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/wd_upsert_positions_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_upsert_positions_audited
-- Popis: Batch zápis poloh z _getAllCarsPosition. Do historie appenduje
--        (dedup UNIQUE wd_car_id+position_time — stojící vozidlo vrací
--        stejnou polohu), poslední polohu upsertuje do current (jen novější).
--        wd_driver_id dopočítává z driver_card ↔ wd_drivers.card_identifier.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT
-- Audit: wd_positions.import_completed s počty (bez PII)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.wd_upsert_positions_audited(
  p_positions jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  -- Canonical boolean-NOT-NULL service check (is_service_role.sql, #588): the
  -- prior inline claims idiom folds to SQL NULL without a role claim and the
  -- negative deny-guard below then fails OPEN. is_service_role() COALESCEs to
  -- false, so the guard is total (fails CLOSED).
  v_is_service boolean := public.is_service_role();
  v_batch jsonb;
  v_total integer;
  v_history_inserted integer;
  v_current_upserted integer;
BEGIN
  -- Authorization check (FIRST, before any data access)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  -- Input validation
  IF p_positions IS NULL OR jsonb_typeof(p_positions) <> 'array' THEN
    RAISE EXCEPTION 'p_positions must be a jsonb array';
  END IF;

  -- Dedup: poslední poloha na (wd_car_id, position_time)
  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON ((item->>'wd_car_id')::integer, (item->>'position_time')::timestamptz) item
    FROM jsonb_array_elements(p_positions) AS item
    WHERE item->>'wd_car_id' IS NOT NULL
      AND NULLIF(item->>'position_time', '') IS NOT NULL
  ) AS deduped;

  v_total := jsonb_array_length(v_batch);

  INSERT INTO public.wd_vehicles (
    wd_car_id, raw_data, last_import_at, updated_at
  )
  SELECT DISTINCT
    (item->>'wd_car_id')::integer,
    jsonb_build_object('placeholder', true, 'source', 'wd_upsert_positions_audited'),
    now(),
    now()
  FROM jsonb_array_elements(v_batch) AS item
  ON CONFLICT (wd_car_id) DO NOTHING;

  -- Historie: append-only, konflikt = poloha už uložená z předchozího pollu
  WITH src AS (
    SELECT
      (item->>'wd_car_id')::integer AS wd_car_id,
      NULLIF(item->>'driver_card', '') AS driver_card,
      (item->>'position_time')::timestamptz AS position_time,
      (item->>'latitude')::numeric AS latitude,
      (item->>'longitude')::numeric AS longitude,
      (item->>'speed_kmh')::numeric AS speed_kmh,
      (item->>'moving')::boolean AS moving,
      NULLIF(item->>'location_text', '') AS location_text,
      (item->>'odometer_km')::numeric AS odometer_km,
      (item->>'fuel_level')::numeric AS fuel_level,
      (item->>'used_fuel')::numeric AS used_fuel,
      item->'raw' AS raw_data
    FROM jsonb_array_elements(v_batch) AS item
  ),
  ins AS (
    INSERT INTO public.wd_vehicle_positions_history (
      wd_car_id, wd_driver_id, driver_card, position_time,
      latitude, longitude, speed_kmh, moving, location_text,
      odometer_km, fuel_level, used_fuel, raw_data
    )
    SELECT
      s.wd_car_id, d.wd_driver_id, s.driver_card, s.position_time,
      s.latitude, s.longitude, s.speed_kmh, s.moving, s.location_text,
      s.odometer_km, s.fuel_level, s.used_fuel, s.raw_data
    FROM src s
    LEFT JOIN public.wd_drivers d
      ON s.driver_card IS NOT NULL AND d.card_identifier = s.driver_card
    ON CONFLICT (wd_car_id, position_time) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_history_inserted FROM ins;

  -- Current: jeden řádek na vozidlo, přepsat jen novější polohou
  WITH src AS (
    SELECT DISTINCT ON ((item->>'wd_car_id')::integer)
      (item->>'wd_car_id')::integer AS wd_car_id,
      NULLIF(item->>'driver_card', '') AS driver_card,
      (item->>'position_time')::timestamptz AS position_time,
      (item->>'latitude')::numeric AS latitude,
      (item->>'longitude')::numeric AS longitude,
      (item->>'speed_kmh')::numeric AS speed_kmh,
      (item->>'moving')::boolean AS moving,
      NULLIF(item->>'location_text', '') AS location_text,
      (item->>'odometer_km')::numeric AS odometer_km,
      (item->>'fuel_level')::numeric AS fuel_level,
      (item->>'used_fuel')::numeric AS used_fuel,
      item->'raw' AS raw_data
    FROM jsonb_array_elements(v_batch) AS item
    ORDER BY (item->>'wd_car_id')::integer, (item->>'position_time')::timestamptz DESC
  ),
  up AS (
    INSERT INTO public.wd_vehicle_positions_current (
      wd_car_id, wd_driver_id, driver_card, position_time,
      latitude, longitude, speed_kmh, moving, location_text,
      odometer_km, fuel_level, used_fuel, raw_data, updated_at
    )
    SELECT
      s.wd_car_id, d.wd_driver_id, s.driver_card, s.position_time,
      s.latitude, s.longitude, s.speed_kmh, s.moving, s.location_text,
      s.odometer_km, s.fuel_level, s.used_fuel, s.raw_data, now()
    FROM src s
    LEFT JOIN public.wd_drivers d
      ON s.driver_card IS NOT NULL AND d.card_identifier = s.driver_card
    ON CONFLICT (wd_car_id) DO UPDATE SET
      wd_driver_id  = EXCLUDED.wd_driver_id,
      driver_card   = EXCLUDED.driver_card,
      position_time = EXCLUDED.position_time,
      latitude      = EXCLUDED.latitude,
      longitude     = EXCLUDED.longitude,
      speed_kmh     = EXCLUDED.speed_kmh,
      moving        = EXCLUDED.moving,
      location_text = EXCLUDED.location_text,
      odometer_km   = EXCLUDED.odometer_km,
      fuel_level    = EXCLUDED.fuel_level,
      used_fuel     = EXCLUDED.used_fuel,
      raw_data      = EXCLUDED.raw_data,
      updated_at    = now()
    WHERE wd_vehicle_positions_current.position_time <= EXCLUDED.position_time
    RETURNING 1
  )
  SELECT count(*) INTO v_current_upserted FROM up;

  -- Audit log (počty; polohy samotné jsou v datových tabulkách)
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'wd_positions.import_completed',
    jsonb_build_object(
      'total', v_total,
      'history_inserted', v_history_inserted,
      'current_upserted', v_current_upserted
    )
  );

  RETURN jsonb_build_object(
    'total', v_total,
    'history_inserted', v_history_inserted,
    'current_upserted', v_current_upserted
  );
END;
$$;

REVOKE ALL ON FUNCTION public.wd_upsert_positions_audited(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.wd_upsert_positions_audited(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.wd_upsert_positions_audited(jsonb) TO service_role;


