-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_upsert_rides_audited
-- Popis: Batch upsert knihy jízd z _getCarLogBook4. Upsert podle wd_ride_id
--        — kniha jízd se zpětně opravuje, opakovaný import stejného okna
--        aktualizuje existující jízdy (vč. dokončení rozpracované jízdy).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT
-- Audit: wd_rides.import_completed s počty (bez PII)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.wd_upsert_rides_audited(
  p_rides jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  -- Canonical boolean-NOT-NULL service check (is_service_role.sql, #588): the
  -- prior inline claims idiom folds to SQL NULL without a role claim and the
  -- negative deny-guard below then fails OPEN. is_service_role() COALESCEs to
  -- false, so the guard is total (fails CLOSED).
  v_is_service boolean := public.is_service_role();
  v_batch jsonb;
  v_total integer;
  v_updated integer;
  v_inserted integer;
BEGIN
  -- Authorization check (FIRST, before any data access)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  -- Input validation
  IF p_rides IS NULL OR jsonb_typeof(p_rides) <> 'array' THEN
    RAISE EXCEPTION 'p_rides must be a jsonb array';
  END IF;

  -- Dedup podle wd_ride_id — ON CONFLICT nesmí zasáhnout stejný řádek dvakrát
  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON ((item->>'wd_ride_id')::bigint) item
    FROM jsonb_array_elements(p_rides) AS item
    WHERE item->>'wd_ride_id' IS NOT NULL
      AND item->>'wd_car_id' IS NOT NULL
  ) AS deduped;

  v_total := jsonb_array_length(v_batch);

  SELECT count(*) INTO v_updated
  FROM public.wd_rides r
  WHERE r.wd_ride_id IN (
    SELECT (item->>'wd_ride_id')::bigint
    FROM jsonb_array_elements(v_batch) AS item
  );

  INSERT INTO public.wd_vehicles (
    wd_car_id, raw_data, last_import_at, updated_at
  )
  SELECT DISTINCT
    (item->>'wd_car_id')::integer,
    jsonb_build_object('placeholder', true, 'source', 'wd_upsert_rides_audited'),
    now(),
    now()
  FROM jsonb_array_elements(v_batch) AS item
  ON CONFLICT (wd_car_id) DO NOTHING;

  WITH src AS (
    SELECT
      (item->>'wd_ride_id')::bigint AS wd_ride_id,
      (item->>'wd_car_id')::integer AS wd_car_id,
      NULLIF(item->>'wd_driver_id', '')::integer AS raw_wd_driver_id,
      NULLIF(item->>'driver_name', '') AS driver_name,
      NULLIF(item->>'start_time', '')::timestamptz AS start_time,
      NULLIF(item->>'end_time', '')::timestamptz AS end_time,
      NULLIF(item->>'start_place', '') AS start_place,
      NULLIF(item->>'end_place', '') AS end_place,
      NULLIF(item->>'purpose', '') AS purpose,
      (item->>'ride_type')::integer AS ride_type,
      (item->>'distance_km')::numeric AS distance_km,
      (item->>'odometer_start_km')::numeric AS odometer_start_km,
      (item->>'odometer_end_km')::numeric AS odometer_end_km,
      (item->>'driving_seconds')::integer AS driving_seconds,
      (item->>'standing_seconds')::integer AS standing_seconds,
      (item->>'max_speed_kmh')::numeric AS max_speed_kmh,
      (item->>'avg_speed_kmh')::numeric AS avg_speed_kmh,
      NULLIF(item->>'crew', '') AS crew,
      NULLIF(item->>'note', '') AS note,
      item->'raw' AS raw_data
    FROM jsonb_array_elements(v_batch) AS item
  )
  INSERT INTO public.wd_rides (
    wd_ride_id, wd_car_id, wd_driver_id, driver_name,
    start_time, end_time, start_place, end_place, purpose, ride_type,
    distance_km, odometer_start_km, odometer_end_km,
    driving_seconds, standing_seconds, max_speed_kmh, avg_speed_kmh,
    crew, note, raw_data, last_import_at, updated_at
  )
  SELECT
    s.wd_ride_id,
    s.wd_car_id,
    d.wd_driver_id,
    s.driver_name,
    s.start_time,
    s.end_time,
    s.start_place,
    s.end_place,
    s.purpose,
    s.ride_type,
    s.distance_km,
    s.odometer_start_km,
    s.odometer_end_km,
    s.driving_seconds,
    s.standing_seconds,
    s.max_speed_kmh,
    s.avg_speed_kmh,
    s.crew,
    s.note,
    s.raw_data,
    now(),
    now()
  FROM src s
  LEFT JOIN public.wd_drivers d
    ON s.raw_wd_driver_id IS NOT NULL AND d.wd_driver_id = s.raw_wd_driver_id
  ON CONFLICT (wd_ride_id) DO UPDATE SET
    wd_car_id         = EXCLUDED.wd_car_id,
    wd_driver_id      = EXCLUDED.wd_driver_id,
    driver_name       = EXCLUDED.driver_name,
    start_time        = EXCLUDED.start_time,
    end_time          = EXCLUDED.end_time,
    start_place       = EXCLUDED.start_place,
    end_place         = EXCLUDED.end_place,
    purpose           = EXCLUDED.purpose,
    ride_type         = EXCLUDED.ride_type,
    distance_km       = EXCLUDED.distance_km,
    odometer_start_km = EXCLUDED.odometer_start_km,
    odometer_end_km   = EXCLUDED.odometer_end_km,
    driving_seconds   = EXCLUDED.driving_seconds,
    standing_seconds  = EXCLUDED.standing_seconds,
    max_speed_kmh     = EXCLUDED.max_speed_kmh,
    avg_speed_kmh     = EXCLUDED.avg_speed_kmh,
    crew              = EXCLUDED.crew,
    note              = EXCLUDED.note,
    raw_data          = EXCLUDED.raw_data,
    last_import_at    = EXCLUDED.last_import_at,
    updated_at        = now();

  v_inserted := v_total - v_updated;

  -- Audit log (jen počty — jména řidičů do auditu nepatří)
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'wd_rides.import_completed',
    jsonb_build_object(
      'total', v_total,
      'inserted', v_inserted,
      'updated', v_updated
    )
  );

  RETURN jsonb_build_object(
    'total', v_total,
    'inserted', v_inserted,
    'updated', v_updated
  );
END;
$$;

REVOKE ALL ON FUNCTION public.wd_upsert_rides_audited(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.wd_upsert_rides_audited(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.wd_upsert_rides_audited(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/wd_upsert_vehicles_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_upsert_vehicles_audited
-- Popis: Batch upsert vozidel z Webdispečinku. Volá svc-webdispecink po
--        stažení _getCarsList2. Vozidla se nikdy nemažou — deaktivace přijde
--        z API přes pole active. Vrací počty inserted/updated.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT
-- Audit: wd_vehicles.import_completed s počty (bez PII)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.wd_upsert_vehicles_audited(
  p_vehicles jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  -- Canonical boolean-NOT-NULL service check (is_service_role.sql, #588): the
  -- prior inline claims idiom folds to SQL NULL without a role claim and the
  -- negative deny-guard below then fails OPEN. is_service_role() COALESCEs to
  -- false, so the guard is total (fails CLOSED).
  v_is_service boolean := public.is_service_role();
  v_batch jsonb;
  v_total integer;
  v_updated integer;
  v_inserted integer;
BEGIN
  -- Authorization check (FIRST, before any data access)
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  -- Input validation
  IF p_vehicles IS NULL OR jsonb_typeof(p_vehicles) <> 'array' THEN
    RAISE EXCEPTION 'p_vehicles must be a jsonb array';
  END IF;

  -- Dedup podle wd_car_id — ON CONFLICT nesmí zasáhnout stejný řádek dvakrát
  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON ((item->>'wd_car_id')::integer) item
    FROM jsonb_array_elements(p_vehicles) AS item
    WHERE item->>'wd_car_id' IS NOT NULL
  ) AS deduped;

  v_total := jsonb_array_length(v_batch);

  SELECT count(*) INTO v_updated
  FROM public.wd_vehicles v
  WHERE v.wd_car_id IN (
    SELECT (item->>'wd_car_id')::integer
    FROM jsonb_array_elements(v_batch) AS item
  );

  INSERT INTO public.wd_vehicles (
    wd_car_id, car_group_id, identifier, description, vehicle_type,
    default_driver, active, online, odometer_km,
    installation_date, disable_date, raw_data, last_import_at, updated_at
  )
  SELECT
    (item->>'wd_car_id')::integer,
    (item->>'car_group_id')::integer,
    item->>'identifier',
    item->>'description',
    (item->>'vehicle_type')::integer,
    item->>'default_driver',
    COALESCE((item->>'active')::boolean, true),
    (item->>'online')::boolean,
    (item->>'odometer_km')::numeric,
    NULLIF(item->>'installation_date', '')::timestamptz,
    NULLIF(item->>'disable_date', '')::timestamptz,
    item->'raw',
    now(),
    now()
  FROM jsonb_array_elements(v_batch) AS item
  ON CONFLICT (wd_car_id) DO UPDATE SET
    car_group_id      = EXCLUDED.car_group_id,
    identifier        = EXCLUDED.identifier,
    description       = EXCLUDED.description,
    vehicle_type      = EXCLUDED.vehicle_type,
    default_driver    = EXCLUDED.default_driver,
    active            = EXCLUDED.active,
    online            = EXCLUDED.online,
    odometer_km       = EXCLUDED.odometer_km,
    installation_date = EXCLUDED.installation_date,
    disable_date      = EXCLUDED.disable_date,
    raw_data          = EXCLUDED.raw_data,
    last_import_at    = EXCLUDED.last_import_at,
    updated_at        = now();

  v_inserted := v_total - v_updated;

  -- Audit log
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    auth.uid(),
    'wd_vehicles.import_completed',
    jsonb_build_object(
      'total', v_total,
      'inserted', v_inserted,
      'updated', v_updated
    )
  );

  RETURN jsonb_build_object(
    'total', v_total,
    'inserted', v_inserted,
    'updated', v_updated
  );
END;
$$;

REVOKE ALL ON FUNCTION public.wd_upsert_vehicles_audited(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.wd_upsert_vehicles_audited(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.wd_upsert_vehicles_audited(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/workflow_step_open_beat.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: workflow_step_open_beat
-- Popis: KLOUB KROK ↔ TAKT (ADR-003, program K2; TWIN_PULSE_MODEL §5, řádek
--        „production milestone"). Otevře TAKT pro jeden lidský uzel běhu:
--        „subjekt běhu dluží akci tohoto uzlu do termínu, dluží ji přiřazený
--        člověk (nebo držitelé role)". Idempotentní podle (source_type=
--        'workflow_step', source_id=krok): otevřený takt téhož kroku se vrací.
--
-- CO JE LIDSKÝ UZEL: má adresáta — assigned_user_id, assigned_role, nebo
-- vazbu na dvojče (input_data.authorized_twin_id). Strojový uzel takt nemá
-- (nikdo nic nedluží); vrací NULL, ne chybu.
--
-- SUBJEKT taktu (v tomto pořadí): input_data.subject_twin_id → subject_actor_id
-- → authorized_twin_id → story běhu. Běh bez subjektu takt nemá (NULL): takt
-- bez subjektu by byl řádek fronty, který nejde vyřešit.
--
-- TERMÍN: input_data.due_at → created_at + input_data.due_in (interval)
-- → production_date běhu (17:00) → created_at + 7 dní. Takt vyžaduje due_at.
--
-- PROČ PŘÍMÝ INSERT a ne create_pulse_beat_audited: to RPC váže autorizaci na
-- SUBJEKT (operátor / vlastní účet). Kloub ale otevírá takt DALŠÍHO uzlu při
-- potvrzení předchozího libovolným oprávněným účastníkem (držitel role,
-- vázaný účet) — ten nad subjektem oprávnění nemá a mít nemusí. Autorizace
-- tady je autorizace BĚHU: volá se jen z DEFINER funkcí běhu
-- (ensure_workflow_run_for_subject, complete_workflow_step), grant má pouze
-- service_role — táž třída jako append_subject_entry_service. Tvar řádku i
-- typový záznam 'pulse_beat_opened' na ose subjektu jsou stejné jako v RPC.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.workflow_step_open_beat(p_step_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_step         public.production_workflow_steps%rowtype;
  v_batch        public.production_batches%rowtype;
  v_subject_type text;
  v_subject_id   uuid;
  v_due          timestamptz;
  v_beat_type    text;
  v_beat_id      uuid;
  v_entry_id     uuid;
  v_caller       uuid := auth.uid();
BEGIN
  SELECT * INTO v_step FROM public.production_workflow_steps WHERE id = p_step_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'workflow step % not found', p_step_id USING ERRCODE = '22023';
  END IF;
  IF v_step.status IS DISTINCT FROM 'pending' THEN
    RETURN NULL;
  END IF;
  IF v_step.assigned_user_id IS NULL
     AND v_step.assigned_role IS NULL
     AND nullif(v_step.input_data->>'authorized_twin_id', '') IS NULL THEN
    RETURN NULL;  -- strojový uzel: nikdo nic nedluží
  END IF;

  -- idempotence: otevřený takt tohoto kroku už existuje
  SELECT b.id INTO v_beat_id
  FROM public.story_pulse_beats b
  WHERE b.source_type = 'workflow_step' AND b.source_id = p_step_id AND b.status = 'open'
  LIMIT 1;
  IF v_beat_id IS NOT NULL THEN
    RETURN v_beat_id;
  END IF;

  SELECT * INTO v_batch FROM public.production_batches WHERE id = v_step.batch_id;

  IF nullif(v_step.input_data->>'subject_twin_id', '') IS NOT NULL THEN
    v_subject_type := 'twin';  v_subject_id := (v_step.input_data->>'subject_twin_id')::uuid;
  ELSIF nullif(v_step.input_data->>'subject_actor_id', '') IS NOT NULL THEN
    v_subject_type := 'actor'; v_subject_id := (v_step.input_data->>'subject_actor_id')::uuid;
  ELSIF nullif(v_step.input_data->>'authorized_twin_id', '') IS NOT NULL THEN
    v_subject_type := 'twin';  v_subject_id := (v_step.input_data->>'authorized_twin_id')::uuid;
  ELSIF v_batch.story_id IS NOT NULL THEN
    v_subject_type := 'story'; v_subject_id := v_batch.story_id;
  ELSE
    RETURN NULL;  -- běh bez subjektu: není komu/za koho dlužit
  END IF;

  v_due := COALESCE(
    nullif(v_step.input_data->>'due_at', '')::timestamptz,
    CASE WHEN nullif(v_step.input_data->>'due_in', '') IS NOT NULL
         THEN v_step.created_at + (v_step.input_data->>'due_in')::interval END,
    CASE WHEN v_batch.production_date IS NOT NULL
         THEN v_batch.production_date::timestamptz + interval '17 hours' END,
    v_step.created_at + interval '7 days');
  v_beat_type := COALESCE(nullif(v_step.input_data->>'beat_type', ''), v_step.step_code, 'step');

  INSERT INTO public.story_pulse_beats (
    subject_type, subject_id, beat_type, status, due_at,
    assigned_to_user_id, source_type, source_id, note, metadata, created_by
  ) VALUES (
    v_subject_type, v_subject_id, v_beat_type, 'open', v_due,
    v_step.assigned_user_id, 'workflow_step', p_step_id,
    COALESCE(nullif(v_step.description, ''), v_step.step_name),
    jsonb_build_object('batch_id', v_step.batch_id, 'step_code', v_step.step_code,
                       'assigned_role', v_step.assigned_role),
    v_caller
  )
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_beat_id;

  IF v_beat_id IS NULL THEN
    -- Tentýž otevřený slot (subjekt, typ, termín, zdroj) už drží jiný řádek.
    SELECT b.id INTO v_beat_id FROM public.story_pulse_beats b
    WHERE b.status = 'open' AND b.subject_type = v_subject_type AND b.subject_id = v_subject_id
      AND b.beat_type = v_beat_type AND b.due_at = v_due
      AND b.source_type = 'workflow_step' AND b.source_id = p_step_id
    LIMIT 1;
    RETURN v_beat_id;
  END IF;

  -- Otevření je samo typový záznam na ose subjektu (jako v create_pulse_beat_audited).
  v_entry_id := public.append_subject_entry_service(
    p_subject_type := v_subject_type,
    p_subject_id   := v_subject_id,
    p_entry_type   := 'pulse_beat_opened',
    p_content      := COALESCE(nullif(v_step.description, ''), v_step.step_name),
    p_metadata     := jsonb_build_object('beat_id', v_beat_id, 'beat_type', v_beat_type,
                        'due_at', v_due, 'assigned_to_user_id', v_step.assigned_user_id,
                        'source_type', 'workflow_step', 'source_id', p_step_id,
                        'batch_id', v_step.batch_id),
    p_created_by   := v_caller,
    p_story_id     := CASE WHEN v_subject_type = 'story' THEN v_subject_id ELSE NULL END,
    p_is_internal  := true,
    p_occurred_at  := now());

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_caller, 'workflow.beat_opened',
          jsonb_build_object('beat_id', v_beat_id, 'step_id', p_step_id,
                             'batch_id', v_step.batch_id, 'entry_id', v_entry_id));
  RETURN v_beat_id;
END;
$$;

REVOKE ALL ON FUNCTION public.workflow_step_open_beat(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.workflow_step_open_beat(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/ensure_workflow_run_for_subject.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: ensure_workflow_run_for_subject
-- Popis: Otevře běh procesu pro JEDEN předmět (doklad, objednávka, zakázka —
--        cokoli, o čem ten běh je) a přiřadí jeho lidské uzly konkrétním lidem.
--        Idempotentní podle p_run_code.
--
-- PROČ VZNIKLA: tři RPC, které běh potřebuje, existovaly, ale NIKDO je nevolal —
-- grep přes celý strom vracel jen definice a generované typy. Batch bez
-- materializace nemá jediný krok, batch bez story spolkne celou naraci mlčky
-- (v complete_workflow_step je narace i goal re-evaluace pod `if story_id is not
-- null`). Chybějící sloveso, ne chybějící mašinerie.
--
-- PROČ NE create_production_batch_admin: guard má `is_admin_or_staff(auth.uid())`
-- a GRANT jen pro authenticated, takže lane běžící jako service_role jím batch
-- nezaloží. Navíc castuje `p_purpose::batch_purpose` bez ošetření NULL a ten
-- enum má jen study/retail/sample/internal_testing — pro dodávku tam není
-- sémanticky správná hodnota. Zakládá se proto přímo, pod vlastní autorizací.
--
-- IDEMPOTENCE JE POVINNÁ, ne pohodlí: `batch_code` nemá unique ani index, takže
-- dvojí spuštění lane pro tentýž doklad by tiše vyrobilo DVA běhy a dvě sady
-- kroků — a řidič by tutéž dodávku potvrzoval dvakrát. Existující běh se proto
-- vrací beze změny.
--
-- PŘIŘAZENÍ UZLŮ (p_node_bindings) je to, kvůli čemu tahle funkce hlavně je.
-- Šablona je sdílená, ale KDO tenhle konkrétní běh veze, je vlastnost běhu.
-- Materializer bere assigned_user_id z uzlu šablony, takže per-běh se to jinak
-- doplnit nedá. Zapisuje se do input_data, odkud to čte sdílený predikát
-- workflow_step_visible_to.
--   ⚠️ Uzel, který má `assigned_role`, uvidí KAŽDÝ držitel té role — predikát
--   vyhodnocuje roli PŘED vazbou a při shodě rovnou vrací true. Kdo chce „jen
--   svoje řádky", musí mít uzel BEZ role a s authorized_twin_id.
--
-- authorized_twin_ref → authorized_twin_id (překlad na vstupu): deklarant běhu
-- (ingest bundle) platformní UUID twinu nezná z podstaty — smí proto poslat
-- REFERENCI {entity_type, source, source_key, label?} a překlad se udělá tady,
-- přes twin_upsert_entity_audited (idempotentní mint-or-match na potvrzené
-- primární identitě zdroje; auditovaný). Táž (source, source_key) identita,
-- jakou navrhuje twin-producer z entity profilů → obě lane konvergují na TÝŽ
-- twin. Viditelnost tím NEvzniká: workflow_step_visible_to pustí jen účet
-- s POTVRZENOU vazbou ref_kind='account' na ten twin — ratifikace zůstává
-- člověku, mint dopředu je bezpečný (do potvrzení uzel nevidí nikdo mimo
-- admin/staff). Metadata twinu se při překladu NEposílají (NULL): UPDATE větev
-- twin_upsertu by jimi PŘEPSALA evidenci, kterou twin nese z profilové lane.
-- Překlad běží PŘED založením batche: vadná reference odmítne CELÝ běh, nikdy
-- nevznikne půlka změny (běh bez vazby, který by idempotence už nikdy nedovázala).
--
-- p_subject se vlévá do input_data VŠECH uzlů: je to popis téhož předmětu a
-- povrch si z něj bere sloupce (`input:<cesta>`), ať už stojí u kteréhokoli
-- milníku. Klíče z p_subject NIKDY nepřepíší klíče uzlu — konfigurace procesu
-- má přednost před daty jedné instance běhu.
--
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- ============================================================================

CREATE OR REPLACE FUNCTION public.ensure_workflow_run_for_subject(
  p_template_name  text,
  p_run_code       text,
  p_subject_label  text    DEFAULT NULL,
  p_due_date       date    DEFAULT NULL,
  p_subject        jsonb   DEFAULT '{}'::jsonb,
  p_node_bindings  jsonb   DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_template_id uuid;
  v_first_step  uuid;
  v_first_beat  uuid;
  v_batch_id    uuid;
  v_existing    uuid;
  v_steps       jsonb;
  v_story       jsonb;
  v_bound       int := 0;
  v_bindings    jsonb := coalesce(p_node_bindings, '{}'::jsonb);
  v_step_code   text;
  v_binding     jsonb;
  v_ref         jsonb;
  v_ref_bad     text;
  v_twin        jsonb;
  v_resolved    int := 0;
BEGIN
  IF NOT (public.is_admin_or_staff(auth.uid()) OR public.is_service_role()) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'admin, staff or service role required');
  END IF;

  IF coalesce(btrim(p_run_code), '') = '' THEN
    -- Bez kódu není idempotence, a bez idempotence vzniknou duplicitní běhy.
    RETURN jsonb_build_object('ok', false, 'error', 'p_run_code is required (idempotence key)');
  END IF;

  -- Překlad referencí PŘED vším ostatním (viz hlavička: žádná půlka změny).
  FOR v_step_code, v_binding IN SELECT key, value FROM jsonb_each(v_bindings) LOOP
    CONTINUE WHEN NOT (v_binding ? 'authorized_twin_ref');
    v_ref := v_binding->'authorized_twin_ref';

    -- Uzavřená množina klíčů + povinné hodnoty: reference s překlepem se odmítá,
    -- nikdy tiše neignoruje (jinak by běh vypadal otevřený a vazba by chyběla).
    SELECT string_agg(k, ', ') INTO v_ref_bad
    FROM jsonb_object_keys(v_ref) AS k
    WHERE k NOT IN ('entity_type', 'source', 'source_key', 'label');
    IF v_ref_bad IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'error',
        format('node %L: unknown authorized_twin_ref keys: %s', v_step_code, v_ref_bad));
    END IF;
    IF coalesce(btrim(v_ref->>'entity_type'), '') = ''
       OR coalesce(btrim(v_ref->>'source'), '') = ''
       OR coalesce(btrim(v_ref->>'source_key'), '') = '' THEN
      RETURN jsonb_build_object('ok', false, 'error',
        format('node %L: authorized_twin_ref requires entity_type, source, source_key',
               v_step_code));
    END IF;

    -- Twin identity vrstva je VOLITELNÝ subsystém (viz workflow_step_visible_to):
    -- bez ní se reference nedá přeložit a mlčky ji zahodit nesmíme.
    IF to_regprocedure('public.twin_upsert_entity_audited(text,text,text,text,text,jsonb)')
       IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error',
        format('node %L: authorized_twin_ref given but the twin identity layer '
               || 'is not installed', v_step_code));
    END IF;

    -- Mint-or-match; metadata NULL (nepřepsat evidenci profilové lane), status NULL.
    EXECUTE 'SELECT public.twin_upsert_entity_audited($1, $2, $3, $4, NULL, NULL)'
    INTO v_twin
    USING v_ref->>'entity_type', v_ref->>'source', v_ref->>'source_key',
          nullif(btrim(coalesce(v_ref->>'label', '')), '');

    v_bindings := jsonb_set(
      v_bindings, ARRAY[v_step_code],
      (v_binding - 'authorized_twin_ref')
        || jsonb_build_object('authorized_twin_id', v_twin->>'twin_id'));
    v_resolved := v_resolved + 1;
  END LOOP;

  SELECT id INTO v_template_id
  FROM public.production_workflow_templates
  WHERE name = p_template_name AND coalesce(is_active, true)
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_template_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', format('no active template named %L', p_template_name));
  END IF;

  -- Už otevřený? Běh se NEOTEVÍRÁ podruhé (idempotence, viz hlavička), ale
  -- POPIS PŘEDMĚTU se obnoví. `subject` je evidence O DOKLADU (číslo, protistrana,
  -- adresa, řidič, vozidlo), ne provozní stav běhu — a doklad se dozvídáme po
  -- částech: 20 213 běhů expedice vzniklo z podmnožiny polí a řidiče se SPZ
  -- (12 212 / 11 319 dokladů v registru) by beze změny nikdy nespatřily, protože
  -- ta větev vracela metadata nedotčená. Čerstvější čtení dokladu tedy popis
  -- doplní; kdo už běh potvrzuje, tím není dotčen.
  --
  -- Slévá se JEN klíč `subject` (`||` nad celým metadata by sebral evidenci
  -- ostatních lane) a jen když volající nějaký předmět poslal — prázdný vstup
  -- nesmí popis vymazat.
  SELECT id INTO v_existing FROM public.production_batches WHERE batch_code = p_run_code LIMIT 1;
  IF v_existing IS NOT NULL THEN
    IF p_subject IS NOT NULL AND jsonb_typeof(p_subject) = 'object'
       AND p_subject <> '{}'::jsonb THEN
      UPDATE public.production_batches
         SET metadata = coalesce(metadata, '{}'::jsonb)
                        || jsonb_build_object('subject',
                             coalesce(metadata->'subject', '{}'::jsonb) || p_subject),
             updated_at = now()
       WHERE id = v_existing;

      -- …a TAM, ODKUD SE ČTE. Metadata dávky jsou evidence; povrchy (fronta
      -- předání, dispečink) berou hodnoty z `input_data` KROKU, kam se předmět
      -- vlévá při zakládání běhu. Bez tohohle UPDATE by obnova skončila v místě,
      -- kam se nikdo nedívá: naměřeno 2026-07-30 — 12 211 dávek mělo řidiče
      -- v metadatech a dispečink jich zobrazil NULA.
      --
      -- Pořadí slučování je TOTOŽNÉ se zakládáním (p_subject || input_data):
      -- předmět je základ, konfigurace uzlu ho přebíjí. Doplní se tedy klíče,
      -- které krok ještě nemá, a nic existujícího se nepřepíše — ani ruční
      -- úprava, ani vazbou přiřazený uzel.
      UPDATE public.production_workflow_steps s
         SET input_data = p_subject || coalesce(s.input_data, '{}'::jsonb),
             updated_at = now()
       WHERE s.batch_id = v_existing
         AND NOT (coalesce(s.input_data, '{}'::jsonb) @> p_subject);

      RETURN jsonb_build_object('ok', true, 'already_open', true, 'subject_refreshed', true,
                                'batch_id', v_existing, 'run_code', p_run_code);
    END IF;
    RETURN jsonb_build_object('ok', true, 'already_open', true,
                              'batch_id', v_existing, 'run_code', p_run_code);
  END IF;

  INSERT INTO public.production_batches
    (batch_code, product_name, production_date, workflow_template_id, status, metadata, created_by)
  VALUES
    (p_run_code, p_subject_label, p_due_date, v_template_id, 'planned',
     jsonb_build_object('subject', coalesce(p_subject, '{}'::jsonb)), auth.uid())
  RETURNING id INTO v_batch_id;

  -- Story PŘED materializací: complete_workflow_step přeskočí naraci i goal
  -- re-evaluaci mlčky, když batch story nemá, a doplnit ji zpětně by znamenalo
  -- běh, jehož první milníky se nikam nezapsaly.
  v_story := public.ensure_production_batch_story(v_batch_id, NULL, p_subject_label);

  v_steps := public.create_production_workflow_steps_from_template(v_batch_id);
  IF NOT coalesce((v_steps->>'ok')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'error', coalesce(v_steps->>'error', 'materialization failed'),
                              'batch_id', v_batch_id);
  END IF;

  -- Předmět do všech uzlů + per-uzel přiřazení. `||` má vpravo přednost, proto
  -- se p_subject aplikuje ZLEVA: konfigurace uzlu přebije data běhu.
  -- (v_bindings = p_node_bindings s referencemi přeloženými na authorized_twin_id.)
  UPDATE public.production_workflow_steps s
     SET input_data = coalesce(p_subject, '{}'::jsonb)
                      || coalesce(s.input_data, '{}'::jsonb)
                      || coalesce(v_bindings->s.step_code, '{}'::jsonb),
         assigned_user_id = coalesce(
           nullif(v_bindings->s.step_code->>'assigned_user_id', '')::uuid,
           s.assigned_user_id),
         -- Vazbou přiřazený uzel ROLI ZTRÁCÍ. Jinak by ji predikát vyhodnotil
         -- dřív a pustil k němu každého držitele té role — čímž by přiřazení
         -- konkrétnímu člověku nezúžilo vůbec nic.
         assigned_role = CASE
           WHEN v_bindings->s.step_code ? 'authorized_twin_id' THEN NULL
           ELSE s.assigned_role END,
         updated_at = now()
   WHERE s.batch_id = v_batch_id
     AND (p_subject <> '{}'::jsonb OR v_bindings ? s.step_code);
  GET DIAGNOSTICS v_bound = ROW_COUNT;

  -- ── twin puls (ADR-003 K2): první lidský uzel dluží hned od otevření běhu ──
  -- Kloub workflow_step_open_beat vrací NULL pro strojový uzel nebo běh bez
  -- subjektu; selhání kloubu nesmí shodit založený běh (Z7) — zapíše se.
  BEGIN
    SELECT s.id INTO v_first_step
      FROM public.production_workflow_steps s
     WHERE s.batch_id = v_batch_id AND s.status = 'pending'
     ORDER BY s.step_order, s.created_at
     LIMIT 1;
    IF v_first_step IS NOT NULL THEN
      v_first_beat := public.workflow_step_open_beat(v_first_step);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO public.audit_journal (user_id, action, metadata)
    VALUES (auth.uid(), 'workflow.beat_joint_failed',
            jsonb_build_object('batch_id', v_batch_id, 'error', SQLERRM));
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'batch_id', v_batch_id,
    'run_code', p_run_code,
    'story_id', v_story->>'story_id',
    'steps_created', v_steps->>'created',
    'steps_bound', v_bound,
    'twin_refs_resolved', v_resolved,
    'first_beat_id', v_first_beat);
END;
$function$;

REVOKE ALL ON FUNCTION public.ensure_workflow_run_for_subject(text, text, text, date, jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.ensure_workflow_run_for_subject(text, text, text, date, jsonb, jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.ensure_workflow_run_for_subject(text, text, text, date, jsonb, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_admin_create_followup.sql
-- -----------------------------------------------------------------------------

-- Function: audience_admin_create_followup
--
-- Follow-up je BĚH z jednouzlové šablony `follow-up` (ADR-003 K2, D4): práce je
-- vždy krok běhu, ne řádek úkolové tabulky. Otevření běhu otevře takt prvního
-- lidského uzlu (kloub workflow_step_open_beat), takt nese subjekt = dvojče
-- aktéra (má-li ho) nebo aktér sám, adresát = přiřazený operátor. Vrací ID
-- TAKTU — to je klíč řádku fronty (audience_admin_followup_queue_v.task_id).
--
-- PROČ UŽ ŽÁDNÝ ai_tasks řádek: dvě pravdy o téže práci (takt + úkol) byly
-- kompatibilita pro fronty čtoucí ai_tasks; fronta i overlay teď čtou takty.
-- audience_admin_complete_followup umí uzavřít i staré takty se zdrojem
-- 'ai_task', takže nic rozdělaného se neztratí.
--
-- PROČ ŠABLONA JMÉNEM: instance smí pojmenovat vlastní běhy jak chce, ale
-- audience modul potřebuje jeden generický jednouzlový běh — dodává ho seed
-- jádra (aisha/db/seed/core/17_workflow_templates_generic.sql). Chybí-li,
-- selhání je hlasité a pojmenované, nikdy tichý návrat k úkolové tabulce.
CREATE OR REPLACE FUNCTION public.audience_admin_create_followup(p_actor_id uuid, p_due_at timestamp with time zone, p_note text, p_assigned_to uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_run      jsonb;
  v_batch_id uuid;
  v_beat_id  uuid;
  v_twin_id  uuid;
  v_run_code text;
  v_assignee uuid := COALESCE(p_assigned_to, auth.uid());
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  IF p_actor_id IS NULL OR p_due_at IS NULL THEN
    RAISE EXCEPTION 'actor and due_at are required' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM aisha_auth.users u WHERE u.id = p_actor_id) THEN
    RAISE EXCEPTION 'Subject not found: actor %', p_actor_id USING ERRCODE = '22023';
  END IF;

  -- identita: dvojče účtu, má-li ho (před backfillem NULL → subjekt = aktér)
  SELECT r.twin_id INTO v_twin_id
  FROM public.twin_external_refs r
  WHERE r.ref_kind = 'account' AND r.source_key = p_actor_id::text
    AND r.state = 'confirmed' AND r.valid_to IS NULL
  LIMIT 1;

  v_run_code := 'follow-up:' || p_actor_id::text || ':' || gen_random_uuid()::text;

  v_run := public.ensure_workflow_run_for_subject(
    p_template_name := 'follow-up',
    p_run_code      := v_run_code,
    p_subject_label := COALESCE(nullif(btrim(p_note), ''), 'follow-up'),
    p_due_date      := p_due_at::date,
    p_subject       := jsonb_build_object(
                         'subject_actor_id', p_actor_id,
                         'subject_twin_id',  v_twin_id,
                         'due_at',           p_due_at,
                         'note',             p_note),
    p_node_bindings := jsonb_build_object(
                         'follow_up', jsonb_build_object('assigned_user_id', v_assignee)));

  IF NOT COALESCE((v_run->>'ok')::boolean, false) THEN
    RAISE EXCEPTION 'follow-up run not opened: %', COALESCE(v_run->>'error', 'unknown');
  END IF;
  v_batch_id := (v_run->>'batch_id')::uuid;
  v_beat_id  := nullif(v_run->>'first_beat_id', '')::uuid;

  IF v_beat_id IS NULL THEN
    -- kloub takt neotevřel (např. uzel bez adresáta) — řekni to, netvař se hotově
    RAISE EXCEPTION 'follow-up run % opened but no beat was issued for its first node', v_batch_id;
  END IF;

  PERFORM public.audience_log_event(
    'create_followup',
    'audience_admin_create_followup',
    'story_pulse_beat',
    v_beat_id,
    format('Scheduled follow-up for actor %s', p_actor_id),
    jsonb_build_object('actor_id', p_actor_id, 'twin_id', v_twin_id, 'due_at', p_due_at,
                       'note', p_note, 'batch_id', v_batch_id, 'beat_id', v_beat_id)
  );
  RETURN v_beat_id;
END;
$function$
;
REVOKE ALL ON FUNCTION audience_admin_create_followup(uuid,timestamp with time zone,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audience_admin_create_followup(uuid,timestamp with time zone,text,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION audience_admin_create_followup(uuid,timestamp with time zone,text,uuid) TO authenticator;
GRANT EXECUTE ON FUNCTION audience_admin_create_followup(uuid,timestamp with time zone,text,uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_admin_create_twin_followup.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: audience_admin_create_twin_followup
-- Popis: Follow-up nad DVOJČETEM — i nad entitou bez účtu (kontakt z Raynetu,
--        organizace, externí člověk). Týž běh `follow-up` jako
--        audience_admin_create_followup, jen subjekt taktu je dvojče.
--
-- ⛔ PROČ (naměřeno 2026-09-15 v demu extranetu): akce „Naplánovat follow-up"
-- brala `target.user_id`; u dvojčete bez účtu je NULL → dispečer 22023. Tak se
-- nedalo pracovat s NIKÝM z 907 záznamů převzatých z Raynetu — přesně s těmi,
-- kvůli kterým migrace vznikla. Kloub workflow_step_open_beat subjekt dvojče
-- umí odjakživa (subject_twin_id má přednost); chyběla jen zápisová cesta.
--
-- Účet, má-li ho dvojče, jde do subjektu jako subject_actor_id — fronta
-- (audience_admin_followup_queue_v) pak ukáže jméno profilu, jinak jméno dvojčete.
-- Vrací ID TAKTU (klíč řádku fronty).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.audience_admin_create_twin_followup(
  p_twin_id uuid,
  p_due_at timestamp with time zone,
  p_note text,
  p_assigned_to uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_run      jsonb;
  v_batch_id uuid;
  v_beat_id  uuid;
  v_actor_id uuid;
  v_label    text;
  v_assignee uuid := COALESCE(p_assigned_to, auth.uid());
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;
  IF p_twin_id IS NULL OR p_due_at IS NULL THEN
    RAISE EXCEPTION 'twin and due_at are required' USING ERRCODE = '22023';
  END IF;
  SELECT t.label INTO v_label FROM public.twin_entities t WHERE t.id = p_twin_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Subject not found: twin %', p_twin_id USING ERRCODE = '22023';
  END IF;

  -- účet dvojčete, má-li ho (jinak NULL — subjektem je dvojče samo)
  SELECT r.source_key::uuid INTO v_actor_id
  FROM public.twin_external_refs r
  WHERE r.twin_id = p_twin_id AND r.ref_kind = 'account' AND r.state = 'confirmed'
    AND r.valid_to IS NULL
    AND r.source_key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
  ORDER BY r.confirmed_at DESC NULLS LAST
  LIMIT 1;

  v_run := public.ensure_workflow_run_for_subject(
    p_template_name := 'follow-up',
    p_run_code      := 'follow-up:twin:' || p_twin_id::text || ':' || gen_random_uuid()::text,
    p_subject_label := COALESCE(nullif(btrim(p_note), ''), v_label, 'follow-up'),
    p_due_date      := p_due_at::date,
    p_subject       := jsonb_build_object(
                         'subject_twin_id',  p_twin_id,
                         'subject_actor_id', v_actor_id,
                         'due_at',           p_due_at,
                         'note',             p_note),
    p_node_bindings := jsonb_build_object(
                         'follow_up', jsonb_build_object('assigned_user_id', v_assignee)));

  IF NOT COALESCE((v_run->>'ok')::boolean, false) THEN
    RAISE EXCEPTION 'follow-up run not opened: %', COALESCE(v_run->>'error', 'unknown');
  END IF;
  v_batch_id := (v_run->>'batch_id')::uuid;
  v_beat_id  := nullif(v_run->>'first_beat_id', '')::uuid;
  IF v_beat_id IS NULL THEN
    RAISE EXCEPTION 'follow-up run % opened but no beat was issued for its first node', v_batch_id;
  END IF;

  PERFORM public.audience_log_event(
    'create_followup',
    'audience_admin_create_twin_followup',
    'story_pulse_beat',
    v_beat_id,
    format('Scheduled follow-up for twin %s', p_twin_id),
    jsonb_build_object('twin_id', p_twin_id, 'actor_id', v_actor_id, 'due_at', p_due_at,
                       'note', p_note, 'batch_id', v_batch_id, 'beat_id', v_beat_id));
  RETURN v_beat_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.audience_admin_create_twin_followup(uuid, timestamp with time zone, text, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.audience_admin_create_twin_followup(uuid, timestamp with time zone, text, uuid) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/workflow_step_visible_to.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: workflow_step_visible_to
-- Popis: Sdílený predikát viditelnosti milníku procesu. Tři cesty:
--          1. přímé přiřazení (assigned_user_id)
--          2. role (has_role)
--          3. potvrzená twin vazba — VOLITELNÁ, viz níže
--        Tohle je JEDINÉ místo, které o twin identity vrstvě ví; všechny
--        ostatní workflow funkce volají tento predikát (žádné inline kopie).
--          4. dispečerský rozsah (p_scope='dispatch') — VŠECHNY kroky, ale jen
--             pro admin/staff.
--          5. ÚČET ZAŘÍZENÍ (tablet, F2 2026-09-29) — kroky, které pokrývá aktivní
--             řádek `kiosk_rozsah` (DATA instance: step_code + input_match), a jen
--             s PLATNÝM průkazem (schválený, neodvolaný, nevypršelý — kontrola při
--             každém volání). Kód kroku musí předat volající z ŘÁDKU (`p_step_code`);
--             bez něj cesta neplatí (fail-closed: kdo ho nepředá, tabletu nic neukáže).
--             Od 2026-09-30 řádek s `jen_flotila` pustí JEN krok NAŠÍ flotily: potvrzené
--             párování řidiče nebo vozidla s Webdispečinkem (`kiosk_krok_nasi_flotily`).
--
-- PROČ JE ROZŠÍŘENÍ TADY A NE VE VOLAJÍCÍM (2026-07-30):
--   Dispečink potřebuje vidět cizí kroky. První verze to řešila ve volajícím:
--     and (case when cfg.want_all and is_admin_or_staff() then true
--               else workflow_step_visible_to(...) end)
--   To je bezpečnostní pojistka jako ŘÁDEK — kdo ji smaže, promění příznak
--   v `source_params` (a bloky zakládá instanční SQL) v tichou eskalaci práv.
--   Pojistka, která má důvod, nesmí být odstranitelná omylem.
--   Rozsah proto rozhoduje TENHLE predikát: volající ho volá BEZPODMÍNEČNĚ a
--   nemá jak ho obejít — jen mu předá, co chce vidět. Zrušit kontrolu znamená
--   sáhnout do sdílené bezpečnostní funkce, na které stojí všechny workflow
--   povrchy; takový zásah je hlučný a rozbije zbytek, ne jen dispečink.
--   Doplňkově to drží brána: volající nesmí obsahovat vlastní logiku viditelnosti.
--
-- VOLITELNÁ ZÁVISLOST (proč dynamic SQL):
--   Twin identity vrstva (`twin_external_refs`) je nepovinný subsystém — jádro
--   ji nemusí mít nainstalovanou. Statická reference by se validovala už při
--   CREATE FUNCTION (u LANGUAGE sql), takže baseline by na ČISTÉ DB neprošel a
--   cold-start každé nové instance by spadl. Proto: plpgsql (tělo se při CREATE
--   neparsuje) + to_regclass guard + EXECUTE. Když vrstva chybí, tahle cesta se
--   prostě neuplatní; když je nainstalovaná, chová se přesně jako dřív.
--
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- ============================================================================

CREATE OR REPLACE FUNCTION public.workflow_step_visible_to(
  p_uid uuid,
  p_assigned_user uuid,
  p_assigned_role text,
  p_input jsonb,
  -- Co chce volající vidět. NULL/cokoli jiného = jen svoje (výchozí je vždy užší
  -- pohled). 'dispatch' = všechny kroky — a platí JEN pro admin/staff; komu role
  -- chybí, dostane svou frontu, ne chybu: fail-closed tu znamená degradovat, ne
  -- spadnout, jinak by blok ze sekce zmizel a nikdo by nevěděl proč.
  p_scope text DEFAULT NULL,
  -- Kód kroku (production_workflow_steps.step_code) — jen pro pátou cestu (tablet).
  -- Předává ho volající z řádku, který autorizuje; NULL = cesta zařízení neplatí.
  p_step_code text DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
-- ⛔ COST NECHAT VÝCHOZÍ — NEZVEDAT (2026-09-30, revize kola 13, měřeno na produkci).
-- Kolo 13 sem dalo `COST 100000` („realistická cena ~0,56 ms"), aby planner
-- nepouštěl predikát před levný předfiltr. Jenže cenu restrikční podmínky účtuje
-- planner za KAŽDÝ PROSKENOVANÝ ŘÁDEK (costsize.c cost_seqscan: cpu_per_tuple
-- × baserel->tuples), ne za kandidáty, kteří k ní dojdou: sken kroků s predikátem
-- minus bez něj = 30 809,25 = přesně 123 237 × 0,25. S COST 100000 → +30,8 mil.
-- a get_kiosk_rozvozy by při každém volání kompiloval plný JIT. Pořadí drahého
-- predikátu se řeší PLOTEM u volajícího (MATERIALIZED CTE / množiny předem, viz
-- li_doc_slugs_claimed_by), ne cenou. Hlídá brána predikat-naroku-vychozi-cost.
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_bound boolean := false;
BEGIN
  -- Oracle guard: přihlášený volající smí vyhodnocovat JEN SVOJI viditelnost;
  -- service_role / admin smí za kohokoliv (definer-interní volající předávají
  -- auth.uid() volajícího).
  -- ⛔ STRÁŽ MUSÍ BÝT ODOLNÁ VŮČI NULL (naměřeno 2026-09-19, tip kolegy z upstreamu).
  -- Tvar `IF NOT (p_x = auth.uid() OR …)` se při NEPŘIHLÁŠENÉM volajícím
  -- NEPROVEDE: `auth.uid()` je NULL, porovnání dá NULL, `NULL OR false OR false`
  -- je NULL, `NOT NULL` je NULL — a `IF NULL THEN` je stejné jako `IF false`.
  -- Stráž se tedy přeskočila a funkce odpověděla o TŘETÍ OSOBĚ přesně tomu,
  -- komu odpovídat neměla. `… IS NOT TRUE` zavírá: NULL i false vedou k zamítnutí.
  IF (p_uid = auth.uid() OR public.is_service_role() OR public.is_admin_or_staff()) IS NOT TRUE THEN
    RETURN false;
  END IF;

  -- 4. Dispečerský rozsah. Konjunkce s rolí je JEDINÉ místo, kde se rozhoduje;
  --    žádný příznak z konfigurace ji neobejde, protože volající sem musí přijít.
  IF p_scope = 'dispatch' AND public.is_admin_or_staff() THEN
    RETURN true;
  END IF;

  -- 5. Účet zařízení (tablet). MUSÍ stát PŘED twin větví: kroky předání nesou
  --    `authorized_twin_id` a twin větev vrací výsledek hned, takže by sem nedošlo.
  --    Účet zařízení nemá roli ani přiřazení — jiná cesta ho nepustí.
  --    Krok pustí aktivní řádek `kiosk_rozsah` (DATA instance), který ho pokrývá (kód kroku
  --    + zúžení `input_match`); řádek s `jen_flotila` navíc jen krok NAŠÍ flotily —
  --    potvrzené párování řidiče nebo vozidla s Webdispečinkem (`kiosk_krok_nasi_flotily`;
  --    majitel 2026-09-30: „naše“ určuje párování, ne tablet). Přechod mezi řádky řídí data.
  IF p_step_code IS NOT NULL AND public.je_ucet_zarizeni_platny(p_uid) THEN
    RETURN EXISTS (
      SELECT 1 FROM public.kiosk_rozsah r
       WHERE r.aktivni
         AND r.step_code = p_step_code
         AND COALESCE(p_input, '{}'::jsonb) @> r.input_match
         AND (NOT r.jen_flotila OR public.kiosk_krok_nasi_flotily(COALESCE(p_input, '{}'::jsonb))));
  END IF;

  IF p_assigned_user IS NOT NULL AND p_assigned_user = p_uid THEN
    RETURN true;
  END IF;

  IF p_assigned_role IS NOT NULL AND public.has_role(p_uid, p_assigned_role) THEN
    RETURN true;
  END IF;

  -- Volitelná twin vazba — jen když je identity vrstva nainstalovaná.
  IF p_input ? 'authorized_twin_id'
     AND to_regclass('public.twin_external_refs') IS NOT NULL THEN
    EXECUTE $q$
      SELECT EXISTS (
        SELECT 1 FROM public.twin_external_refs r
        WHERE r.twin_id = $1::uuid
          AND r.ref_kind = 'account'
          AND r.source_key = $2::text
          AND r.state = 'confirmed'
          AND r.valid_from <= now()
          AND (r.valid_to IS NULL OR r.valid_to > now()))
    $q$
    INTO v_bound
    USING (p_input->>'authorized_twin_id'), p_uid;
    RETURN COALESCE(v_bound, false);
  END IF;

  RETURN false;
END;
$function$;

REVOKE ALL ON FUNCTION public.workflow_step_visible_to(uuid,uuid,text,jsonb,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.workflow_step_visible_to(uuid,uuid,text,jsonb,text,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.workflow_step_visible_to(uuid,uuid,text,jsonb,text,text) TO service_role;
-- Pětiargumentový podpis (před F2) musí ZMIZET ze stejného důvodu jako čtyřargumentový
-- níž: volání s 5 argumenty by bylo nejednoznačné (42725), nebo by trefilo verzi BEZ
-- páté cesty. Nový podpis ho pokrývá výchozí hodnotou.
DROP FUNCTION IF EXISTS public.workflow_step_visible_to(uuid,uuid,text,jsonb,text);
-- Starý 4-argumentový podpis musí ZMIZET: `CREATE OR REPLACE` s novým DEFAULT
-- parametrem vytvoří DRUHOU funkci a volání se 4 argumenty by bylo nejednoznačné
-- (42725) — nebo hůř, trefilo by starou verzi BEZ dispečerské větve.
DROP FUNCTION IF EXISTS public.workflow_step_visible_to(uuid,uuid,text,jsonb);


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/complete_workflow_step.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: complete_workflow_step
-- Popis: Dokončení milníku člověkem (kanonické jméno — autorizace má 3 cesty a je interní věc). Narace + nudge při odchylce + odměna deklarovaná NA UZLU šablony + goal re-evaluace. FOR UPDATE = double-award guard.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- Pozn.: definice = regenerát z nasazené DB (ověřeno provozním testem 07-25).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.complete_workflow_step(p_step_id uuid, p_output_data jsonb DEFAULT '{}'::jsonb, p_notes text DEFAULT NULL::text, p_has_deviation boolean DEFAULT false, p_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_step production_workflow_steps%rowtype;
  v_uid uuid := auth.uid();
  -- F2: odbavení z TABLETU (účet zařízení). kid je ověřený proti průkazu účtu
  -- (current_device_kid), jinak NULL — člověk nebo podvržený claim.
  v_device_kid text := public.current_device_kid();
  v_at timestamptz := coalesce(p_occurred_at, now());
  v_status text;
  v_reward jsonb;
  v_award jsonb := null;
  v_amount int;
  v_story_id uuid;
  v_beat_id uuid;
  v_beat_subject_type text;
  v_beat_subject_id uuid;
  v_beat_type text;
  v_beat_entry uuid;
  v_beat_next uuid;
  v_beat_outcome text;
begin
  if v_uid is null then
    return jsonb_build_object('ok',false,'error','not authenticated');
  end if;
  select * into v_step from production_workflow_steps where id = p_step_id for update;
  if not found then
    return jsonb_build_object('ok',false,'error','workflow step not found');
  end if;
  -- Kód kroku z ŘÁDKU (p_step_code) — jen pro pátou cestu (tablet); jinak beze změny.
  if not (workflow_step_visible_to(v_uid, v_step.assigned_user_id, v_step.assigned_role, v_step.input_data,
                                   null, v_step.step_code)
          or is_admin_or_staff(v_uid)) then
    return jsonb_build_object('ok',false,'error','not allowed to complete this step (not assigned, missing role '||coalesce(v_step.assigned_role,'?')||', and no confirmed twin binding)');
  end if;
  if v_step.status = 'completed' then
    return jsonb_build_object('ok',false,'error','step already completed');
  end if;
  v_status := case when p_has_deviation then 'failed' else 'completed' end;
  update production_workflow_steps set
    status = v_status, completed_by = v_uid, completed_at = v_at,
    output_data = coalesce(p_output_data,'{}'::jsonb),
    has_deviation = p_has_deviation,
    deviation_notes = case when p_has_deviation then p_notes else deviation_notes end,
    notes = coalesce(p_notes, notes), updated_at = now()
  where id = p_step_id;

  -- ── twin puls, KLOUB KROK ↔ TAKT (ADR-003 K2) ──────────────────────────────
  -- Potvrzení kroku uzavírá jeho takt (s typovým záznamem na ose subjektu) a
  -- otevírá takt dalšího lidského uzlu běhu. Vedlejší účinek nesmí zničit akt
  -- (Z7): selhání se zapíše do audit_journal, krok zůstává dokončený.
  v_beat_outcome := case when v_status = 'failed' or coalesce(p_output_data->>'outcome','') = 'cancelled'
                         then 'cancelled' else 'done' end;
  begin
    -- Na krok připadá nejvýš JEDEN otevřený takt (idempotence kloubu drží
    -- partial UNIQUE + lookup podle zdroje), takže stačí jeden UPDATE.
    update story_pulse_beats b
       set status = v_beat_outcome, closed_at = v_at, closed_by = v_uid, updated_at = now()
     where b.source_type = 'workflow_step' and b.source_id = p_step_id and b.status = 'open'
    returning b.id, b.subject_type, b.subject_id, b.beat_type
      into v_beat_id, v_beat_subject_type, v_beat_subject_id, v_beat_type;

    if v_beat_id is not null then
      v_beat_entry := append_subject_entry_service(
        p_subject_type := v_beat_subject_type,
        p_subject_id   := v_beat_subject_id,
        p_entry_type   := 'pulse_beat_closed',
        p_content      := coalesce(p_notes, v_step.step_name),
        p_metadata     := jsonb_strip_nulls(jsonb_build_object('beat_id', v_beat_id, 'beat_type', v_beat_type,
                            'outcome', v_beat_outcome, 'step_id', p_step_id, 'batch_id', v_step.batch_id,
                            'device_kid', v_device_kid)),
        p_created_by   := v_uid,
        p_story_id     := case when v_beat_subject_type = 'story' then v_beat_subject_id else null end,
        p_is_internal  := false,
        p_occurred_at  := v_at);
      update story_pulse_beats set closing_entry_id = v_beat_entry where id = v_beat_id;
    end if;

    -- Další lidský uzel běhu dluží od teď.
    select s.id into v_beat_next
      from production_workflow_steps s
     where s.batch_id = v_step.batch_id and s.status = 'pending' and s.step_order > v_step.step_order
     order by s.step_order, s.created_at
     limit 1;
    if v_beat_next is not null then
      perform workflow_step_open_beat(v_beat_next);
    end if;
  exception when others then
    insert into audit_journal (user_id, action, metadata)
    values (v_uid, 'workflow.beat_joint_failed',
            jsonb_build_object('step_id', p_step_id, 'batch_id', v_step.batch_id, 'error', SQLERRM));
  end;
  select b.story_id into v_story_id from production_batches b where b.id = v_step.batch_id;
  if v_story_id is not null then
    perform add_story_system_entry(
      v_story_id, 'tracking_event',
      case when p_has_deviation then 'workflow.timeline.step_deviation'
           else 'workflow.timeline.step_completed' end,
      jsonb_build_object('step_code',v_step.step_code,'step_name',v_step.step_name,
                         'step_order',v_step.step_order,'status',v_status,
                         'has_deviation',p_has_deviation,'batch_id',v_step.batch_id,
                         'completed_by',v_uid)
        -- Na KTERÉM tabletu k předání došlo (F2); u člověka klíč chybí.
        || case when v_device_kid is null then '{}'::jsonb
                else jsonb_build_object('device_kid', v_device_kid) end,
      v_at, 'production_workflow_steps', p_step_id);
    if p_has_deviation then
      insert into dirigent_nudges (story_id, event_origin, severity, message, metadata, expires_at)
      values (v_story_id, 'compliance_engine', 'warn', 'workflow.nudge.step_deviation',
              jsonb_build_object('step_id',p_step_id,'step_code',v_step.step_code,
                                 'batch_id',v_step.batch_id,'notes',p_notes),
              now() + interval '48 hours');
    end if;
  end if;
  -- ⛔ Odměnu NEdostane účet zařízení (F2): tablet není člověk a tokeny na něm by
  -- nic neznamenaly (a šly by zneužít). Komu odměna u odbavení z tabletu patří
  -- (řidiči podle vazby?), je otevřené rozhodnutí — do té doby se nevyplácí, s důvodem.
  -- Rozhoduje ÚČET (vazba průkazu), ne claim v tokenu — ten by mohl chybět.
  if v_status = 'completed'
     and exists (select 1 from knock_device_credentials d where d.ucet_id = v_uid) then
    v_award := jsonb_build_object('success', false, 'skipped', 'device', 'kid', v_device_kid);
  elsif v_status = 'completed' then
    v_reward := v_step.input_data->'reward';
    if v_reward is not null and v_reward ? 'token_type' then
      begin
        v_amount := floor((v_reward->>'amount')::numeric)::int;
        if v_amount > 0 then
          v_award := award_tokens(v_uid, v_reward->>'token_type', v_amount,
                                  'workflow_step', p_step_id, v_step.step_name);
        end if;
      exception when others then
        v_award := jsonb_build_object('success',false,'error',SQLERRM);
      end;
    end if;
  end if;
  -- story-loop: re-evaluate the goal (non-fatal side effect)
  if v_story_id is not null then
    begin
      perform evaluate_story_process_goal(v_story_id);
        exception when others then
      -- goal re-evaluation is a side effect and must never roll back the
      -- operational fact — but the failure is LOGGED, never swallowed
      insert into audit_journal (user_id, action, metadata)
      values (auth.uid(), 'workflow.goal_evaluation_failed',
              jsonb_build_object('error', SQLERRM));
    end;
  end if;
  return jsonb_build_object('ok',true,'step_id',p_step_id,'status',v_status,
    'completed_by',v_uid,'completed_at',v_at,'step_name',v_step.step_name,
    'story_id',v_story_id,'reward',v_award);
end $function$;

REVOKE ALL ON FUNCTION public.complete_workflow_step(uuid,jsonb,text,boolean,timestamp with time zone) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.complete_workflow_step(uuid,jsonb,text,boolean,timestamp with time zone) TO authenticated;
GRANT EXECUTE ON FUNCTION public.complete_workflow_step(uuid,jsonb,text,boolean,timestamp with time zone) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_batch_workflow_progress.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_batch_workflow_progress
-- Popis: Průběh běhu: pos = completed/total, state = poslední dosažený milník (zdroj pravdy stavu fyzického procesu), zdroj ovál projekce.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- Pozn.: definice = regenerát z nasazené DB (ověřeno provozním testem 07-25).
--
-- ČASY NA KROCÍCH (2026-08-05): `steps` vydává i `started_at`/`completed_at`.
-- Věž z nich počítá „jak dlouho to v téhle fázi stojí" (`ent`) a „jak dlouho
-- trvaly hotové fáze" (`done`) — dokud je krok nevydával, neměla je odkud vzít
-- a StoryLoopMC kreslil statickou desku. Sloupce v tabulce EXISTUJÍ odjakživa
-- (started_at, completed_at); jen se nepromítaly ven.
--
-- ⚠️ Vydává se ČAS, ne spočítaná délka. Kdo měří, ať měří u sebe: délka fáze
-- závisí na tom, kdy se ptáš (běžící fáze roste), takže uložit ji do projekce
-- znamená vyrobit číslo, které je v okamžiku doručení už neplatné. NULL je tu
-- legitimní odpověď — krok, který nezačal, prostě nemá kdy začít.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_batch_workflow_progress(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_visible boolean;
  v_story_id uuid;
  v_result jsonb;
begin
  if v_uid is null and not is_service_role() then
    return jsonb_build_object('ok',false,'error','not authenticated');
  end if;
  -- visibility: admin/staff/service, or the batch has a step visible to me
  -- (assigned · role · twin binding) — same predicate family as completion.
  -- Viditelnost přes SDÍLENÝ predikát (žádná inline kopie twin logiky).
  v_visible := is_service_role() or is_admin_or_staff(v_uid) or exists (
    select 1 from production_workflow_steps s
    where s.batch_id = p_batch_id
      and public.workflow_step_visible_to(v_uid, s.assigned_user_id, s.assigned_role, s.input_data)
  );
  if not v_visible then
    return jsonb_build_object('ok',false,'error','not visible');
  end if;
  select b.story_id into v_story_id from production_batches b where b.id = p_batch_id;
  select jsonb_build_object(
    'ok', true,
    'batch_id', p_batch_id,
    'story_id', v_story_id,
    'total', count(*),
    'completed', count(*) filter (where status='completed'),
    'failed', count(*) filter (where status='failed'),
    'pos', round(coalesce(count(*) filter (where status='completed')::numeric
                 / nullif(count(*),0), 0), 2),
    'state', coalesce((select s2.step_code from production_workflow_steps s2
                       where s2.batch_id = p_batch_id and s2.status='completed'
                       order by s2.step_order desc limit 1), 'created'),
    'current_step', (select jsonb_build_object('code',s3.step_code,'name',s3.step_name,'order',s3.step_order)
                     from production_workflow_steps s3
                     where s3.batch_id = p_batch_id and s3.status not in ('completed','failed')
                     order by s3.step_order limit 1),
    'steps', coalesce(jsonb_agg(jsonb_build_object(
               'code',step_code,'name',step_name,'order',step_order,'status',status,
               -- Syrové časy pro měření fází; viz hlavička (délku počítá čtenář).
               'started_at',started_at,'completed_at',completed_at,
               -- Čím se popíše BRÁNA (krok čekající na člověka): co se po něm chce
               -- a čí je to práce. `assigned_role` je ROLE, ne jméno — na věž se
               -- osobní údaj nedostane ani oklikou.
               'description',description,'assigned_role',assigned_role)
               order by step_order), '[]'::jsonb)
  ) into v_result
  from production_workflow_steps where batch_id = p_batch_id;
  return v_result;
end $function$;

REVOKE ALL ON FUNCTION public.get_batch_workflow_progress(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_batch_workflow_progress(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_batch_workflow_progress(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_kiosk_rozvozy.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_kiosk_rozvozy
-- Popis: DNEŠNÍ ROZVOZY PRO TABLET (F2-C) — výběr „podle řidiče“ nebo „podle vozidla“
--        a seznam kroků k předání. Volá JEN účet zařízení s platným průkazem
--        (relace F2-B); člověk ani admin tudy nejde (mají své bloky).
--
-- ⭐ Majitel 2026-09-29: „Obojí na výběr“ (řidič i vozidlo); „jen k našim dodákům“;
--    osobní údaje odběratele na tablet NEJDOU.
--
-- VIDITELNOST: o každém kroku rozhoduje JEDINÝ rozhodovač workflow_step_visible_to
--   (pátá cesta: účet zařízení + aktivní řádek kiosk_rozsah — u `jen_flotila` jen NAŠE
--   flotila spárovaná s Webdispečinkem — + platný průkaz). Tady se jen LEVNĚ předvybírají kandidáti (okno,
--   kódy kroků z rozsahu), aby se predikát volal nad desítkami řádků, ne nad historií.
--
-- ⭐ NEDORUČENÉ, NE JEN DNEŠNÍ (majitel 2026-09-30: „minimálně dodáky, o kterých víme,
--   že jsou nedodané, podle řidičů a podle aut“): nevyřízený krok (pending/in_progress)
--   s production_date v okně [dnes − okno_zpet, dnes + okno_dopredu] řádku rozsahu,
--   plus kroky dnes dokončené. Výchozí okno 0/0 = jen dnešek (chování F2).
--   Doklad, který zdroj hlásí jako vyřízený (`zdroj_stav` řádku, tvar `source_state`
--   bloku řidičovy pásky), mezi nedoručenými NENÍ — týž význam jako na pásce řidiče.
--   Fail-open jako tam: bez ukazatele na doklad nebo bez řádku registru krok zůstává.
--
-- PROJEKCE: z input_data jde ven JEN to, co pustí kiosk_projekce (`pole` řádků rozsahu,
--   které krok pokrývají). Výběr podle řidiče/vozidla je dostupný, JEN když rozsah dané pole
--   pustí (driver_name / vehicle_registration) — seznam jmen je taky projekce.
--
-- VOZIDLO = TAHAČ: vehicle_registration nese i soupravu („1T2 3456/2T3 4567“, „…+…“).
--   Tahač = první část před / , + ; velká písmena A–Z0–9 (měření RIQi 29. 9.).
--
-- Parametry: p_rezim NULL → nabídka {ridici[], vozidla[]}; 'ridic'|'vozidlo' + p_hodnota
--   → {rozvozy[]}. Okno: z řádků rozsahu (viz výše) + dnes dokončené.
-- Bezpečnost: SECURITY DEFINER, grant authenticated (rozhoduje stráž níž).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_kiosk_rozvozy(p_rezim text DEFAULT NULL, p_hodnota text DEFAULT NULL)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_me uuid := auth.uid();
  v_vysledek jsonb;
BEGIN
  IF v_me IS NULL OR NOT public.je_ucet_zarizeni_platny(v_me) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'jen_zarizeni');
  END IF;
  IF p_rezim IS NOT NULL AND p_rezim NOT IN ('ridic', 'vozidlo') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'rezim');
  END IF;
  IF p_rezim IS NOT NULL AND nullif(btrim(coalesce(p_hodnota, '')), '') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'hodnota');
  END IF;

  WITH okno AS (
    -- Vnější mez pro index: nejširší okno ze všech aktivních řádků.
    SELECT coalesce(max(r.okno_zpet), 0) AS zpet, coalesce(max(r.okno_dopredu), 0) AS dopredu
      FROM public.kiosk_rozsah r
     WHERE r.aktivni
  ),
  predvyber AS (
    SELECT s.id, s.step_code, s.status, s.completed_at, s.input_data, s.assigned_user_id, s.assigned_role, b.production_date
      FROM public.production_workflow_steps s
      JOIN public.production_batches b ON b.id = s.batch_id
      CROSS JOIN okno o
     WHERE s.step_code IN (SELECT r.step_code FROM public.kiosk_rozsah r WHERE r.aktivni)
       AND ((s.status IN ('pending', 'in_progress')
             AND b.production_date BETWEEN current_date - o.zpet AND current_date + o.dopredu)
            OR (s.status = 'completed' AND s.completed_at::date = current_date))
  ),
  kandidati AS (
    -- Okno a stav zdroje podle řádků, které krok SKUTEČNĚ pouštějí — stejná podmínka jako
    -- větev zařízení predikátu (step_code + zúžení + u `jen_flotila` naše flotila).
    SELECT p.*, cfg.zdroj_stav
      FROM predvyber p
      CROSS JOIN LATERAL (
        SELECT max(r.okno_zpet) AS zpet,
               max(r.okno_dopredu) AS dopredu,
               (array_agg(r.zdroj_stav ORDER BY r.kod) FILTER (WHERE r.zdroj_stav <> '{}'::jsonb))[1] AS zdroj_stav
          FROM public.kiosk_rozsah r
         WHERE r.aktivni
           AND r.step_code = p.step_code
           AND coalesce(p.input_data, '{}'::jsonb) @> r.input_match
           AND (NOT r.jen_flotila OR public.kiosk_krok_nasi_flotily(coalesce(p.input_data, '{}'::jsonb)))
      ) cfg
     WHERE cfg.zpet IS NOT NULL
       AND (p.status = 'completed'
            OR p.production_date BETWEEN current_date - cfg.zpet AND current_date + cfg.dopredu)
  ),
  nedorucene AS (
    -- Stav dokladu ze zdroje: TÝŽ ukazatel napřed, identita až potom, jako páska řidiče
    -- (get_workflow_my_steps_block) — obě čtení míří na částečné indexy registru
    -- (`superseded_by IS NULL`: doc_slug btree, fields GIN jsonb_path_ops).
    SELECT k.*
      FROM kandidati k
      LEFT JOIN LATERAL (
        SELECT reg.fields
          FROM public.li_source_registry reg
         WHERE k.zdroj_stav IS NOT NULL
           AND reg.superseded_by IS NULL
           AND reg.doc_slug = k.input_data->>'doc_slug'
         ORDER BY reg.ingested_at DESC
         LIMIT 1
      ) src_ptr ON true
      LEFT JOIN LATERAL (
        SELECT reg.fields
          FROM public.li_source_registry reg
         WHERE src_ptr.fields IS NULL
           AND k.zdroj_stav ? 'stable_key'
           AND nullif(k.input_data->>(k.zdroj_stav->>'stable_key'), '') IS NOT NULL
           AND reg.superseded_by IS NULL
           AND reg.fields @> jsonb_build_object(
                 k.zdroj_stav->>'stable_key',
                 jsonb_build_object('value', k.input_data->>(k.zdroj_stav->>'stable_key')))
         ORDER BY reg.ingested_at DESC
         LIMIT 1
      ) src_id ON true
     WHERE k.status = 'completed'
        OR k.zdroj_stav IS NULL
        OR lower(coalesce(coalesce(src_ptr.fields, src_id.fields) -> (k.zdroj_stav->>'field') ->> 'value', ''))
           IS DISTINCT FROM lower(k.zdroj_stav->>'closed_when')
  ),
  videne AS (
    SELECT k.*,
           -- Projekce: JEDINÉ pravidlo, co smí na tablet (kiosk_projekce).
           public.kiosk_projekce(k.step_code, k.input_data) AS proj
      FROM nedorucene k
     WHERE public.workflow_step_visible_to(v_me, k.assigned_user_id, k.assigned_role, k.input_data, NULL, k.step_code)
  ),
  s_pohledem AS (
    -- Řidič i tahač se berou z PROMÍTNUTÉHO objektu: co rozsah nepustí, nejde ani do nabídky.
    SELECT v.*,
           nullif(btrim(v.proj->>'driver_name'), '') AS ridic,
           public.kiosk_tahac(v.proj->>'vehicle_registration') AS tahac
      FROM videne v
  )
  SELECT CASE
           WHEN p_rezim IS NULL THEN jsonb_build_object(
             'ok', true,
             'ridici', coalesce((SELECT jsonb_agg(jsonb_build_object('hodnota', x.ridic, 'k_predani', x.k, 'hotovo', x.h) ORDER BY x.ridic)
                                   FROM (SELECT ridic, count(*) FILTER (WHERE status <> 'completed') AS k,
                                                count(*) FILTER (WHERE status = 'completed') AS h
                                           FROM s_pohledem WHERE ridic IS NOT NULL GROUP BY ridic) x), '[]'::jsonb),
             'vozidla', coalesce((SELECT jsonb_agg(jsonb_build_object('hodnota', x.tahac, 'k_predani', x.k, 'hotovo', x.h) ORDER BY x.tahac)
                                    FROM (SELECT tahac, count(*) FILTER (WHERE status <> 'completed') AS k,
                                                 count(*) FILTER (WHERE status = 'completed') AS h
                                            FROM s_pohledem WHERE tahac IS NOT NULL GROUP BY tahac) x), '[]'::jsonb))
           ELSE jsonb_build_object(
             'ok', true,
             'rezim', p_rezim,
             'hodnota', p_hodnota,
             'rozvozy', coalesce((SELECT jsonb_agg(jsonb_build_object(
                                     'id', sp.id,
                                     'step_code', sp.step_code,
                                     'stav', sp.status,
                                     'dokonceno', sp.completed_at,
                                     'den', sp.production_date,
                                     'pole', sp.proj)
                                   ORDER BY (sp.status = 'completed'), sp.completed_at, sp.id)
                                    FROM s_pohledem sp
                                   WHERE (p_rezim = 'ridic' AND sp.ridic = btrim(p_hodnota))
                                      OR (p_rezim = 'vozidlo' AND sp.tahac = public.kiosk_tahac(p_hodnota))), '[]'::jsonb))
         END
    INTO v_vysledek;

  RETURN v_vysledek;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_kiosk_rozvozy(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_kiosk_rozvozy(text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_kiosk_rozvozy(text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_timing_tower_block.sql
-- -----------------------------------------------------------------------------

-- Timing tower — živé pořadí běhů.
--
-- ROZSAH (2026-08-05): řidič vidí SVÉ běhy, admin/staff VŠECHNY — a je to
-- jedno pravidlo pro obě publika, ne dvě plochy. Nárok se odvozuje ze tří
-- ramen shodných s `workflow_step_visible_to`: přiřazení · role · POTVRZENÁ
-- vazba účtu na twin (`ref_kind='account'`, `state='confirmed'`).
--
-- Historie, ať se to nevrátí: do 2026-08-03 tu stála podmínka podle členství
-- (blok nevracel nikomu nic, protože taková vazba v datech není), pak `where
-- true` jako VĚDOMĚ širší pravidlo. Obojí bylo měřitelně vadné — proč, viz
-- tři důvody u `where` níž.
-- SECURITY DEFINER zůstává kvůli čtení napříč tabulkami.
--
-- SEKTORY NEJSOU ZADRÁTOVANÉ. Chodí ze šablony procesu daného běhu
-- (get_batch_workflow_progress → steps: code/name/order/status), takže jiná
-- šablona = jiné sektory bez zásahu do kódu. Zadrátovat pět fází z makety by
-- znamenalo zapsat si do rendereru JEDEN proces jednoho zákazníka.
--
-- VLAJKA se odvozuje z OBECNÝCH polí (status kroků), ne z doménových stavů:
--   finish  — všechny kroky hotové (běh dojel)
--   red     — některý krok selhal (blokováno, eskalace)
--   box     — čeká na člověka (krok ve stavu awaiting/blocked → pit wall)
--   green   — jede po trati
-- `predani`/`nakladka` jsou slova RIQ; `completed`/`failed` jsou slova platformy.
-- Odvození drží na těch druhých, proto přežije jinou doménu.

create or replace function public.get_timing_tower_block(p_params jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
stable
security definer
SET search_path TO 'public', 'pg_temp'
as $$
declare
  v_uid   uuid := auth.uid();
  v_limit int  := least(coalesce((p_params->>'limit')::int, 20), 100);
  -- Věž JEDNOHO procesu. Bez tohohle filtru kreslí sekce měřidel i dodávky a
  -- naopak — jedna deska pro nesouvisející práci není přehled, je to šum.
  -- NULL (klíč chybí) = všechny procesy, tedy původní chování.
  v_tpl   text := nullif(btrim(coalesce(p_params->>'template', '')), '');
  v_runs  jsonb;
begin
  -- Fail-closed parita s ostatními block RPC: bez identity prázdno, ne chyba.
  if v_uid is null and not is_service_role() then
    return jsonb_build_object(
      'data', jsonb_build_object('runs', '[]'::jsonb),
      'provenance', jsonb_build_object(
        'source_slug', 'production_workflow',
        'trace_id', 'wf:tower',
        'freshness_at', now()));
  end if;

  -- FILTR JE NAD SESTAVENÝM `run`, ne nad `p.prog` uvnitř. `cross join lateral`
  -- s voláním funkce se totiž vyhodnotí zvlášť pro `where` a zvlášť pro
  -- projekci, takže podmínka nad `p.prog->>'pos'` filtruje JINOU hodnotu, než
  -- se pak vydá. Naměřeno 2026-08-03: s filtrem uvnitř prošlo 20 běhů, a všech
  -- 20 mělo ve výstupu `pos` prázdné. Filtrovat se musí to, co se opravdu vydává.
  with scope as (
    -- NÁROK JAKO MNOŽINY, spočítané JEDNOU za dotaz (InitPlan). Doslovná kopie
    -- CTE z get_workflow_my_steps_block — a to ZÁMĚRNĚ: tamní hlavička nese
    -- dvě ZMĚŘENÉ slepé uličky (inlinovatelný predikát 97 s; sdílená množinová
    -- funkce 917 ms proti 36 ms) a končí pokynem „kdo bude nárok potřebovat
    -- v dalším bloku, ať zkopíruje CTE scope a NE ať staví množinovou funkci".
    -- Per-row workflow_step_visible_to je tu obzvlášť drahé: je SECURITY
    -- DEFINER (žádný inline) a nad 20 599 běhy by se volalo pro každý krok.
    select (select auth.uid()) as me,
           -- ⚠️ `is_admin_or_staff()` service_role NEPOKRÝVÁ — proto ta disjunkce.
           -- Kontrola nahoře (`v_uid is null and not is_service_role()`) servisního
           -- volajícího vědomě pouští dál a ten má `auth.uid()` prázdné; bez tohohle
           -- ramene by mu obě další ramena nároku nesedla na nic a věž by servisnímu
           -- čtení oslepla. Sousední get_batch_workflow_progress testuje obojí taky
           -- zvlášť (`is_service_role() or is_admin_or_staff(v_uid)`).
           (select public.is_admin_or_staff() or public.is_service_role()) as is_admin,
           coalesce((select array_agg(ur.role::text)
                     from public.user_roles ur
                     where ur.user_id = (select auth.uid())), '{}'::text[]) as my_roles,
           coalesce((select array_agg(r.twin_id::text)
                     from public.twin_external_refs r
                     where r.ref_kind = 'account'
                       and r.source_key = (select auth.uid())::text
                       and r.state = 'confirmed' and r.valid_from <= now()
                       and (r.valid_to is null or r.valid_to > now())), '{}'::text[]) as my_twins
  )
  -- `batch_id` na konci = rozhodčí shod (viz `order by … b.id` níž).
  select coalesce(jsonb_agg(run order by (run->>'pos')::numeric desc, run->>'entered_at', run->>'batch_id')
                    filter (where jsonb_typeof(run->'pos') = 'number'), '[]'::jsonb)
    into v_runs
  from (
    select jsonb_build_object(
      'batch_id',   b.id,
      'story_id',   b.story_id,
      'title',      ps.title,
      -- Vlastník = priorita běhu jako štítek; jméno člověka sem NEPATŘÍ
      -- (tower je veřejný v rámci pohledu, jméno je osobní údaj navíc).
      'priority',   coalesce(ps.priority, ''),
      'status',     ps.status,
      'state',      p.prog->>'state',
      'pos',        (p.prog->>'pos')::numeric,
      'total',      (p.prog->>'total')::int,
      'completed',  (p.prog->>'completed')::int,
      'failed',     (p.prog->>'failed')::int,
      -- Sektory = kroky šablony. Tower je vykreslí, kolik jich je.
      'sectors',    coalesce(p.prog->'steps', '[]'::jsonb),
      'flag',       case
                      when (p.prog->>'failed')::int > 0                              then 'red'
                      when (p.prog->>'completed')::int >= (p.prog->>'total')::int
                           and (p.prog->>'total')::int > 0                           then 'finish'
                      when exists (
                        select 1 from jsonb_array_elements(coalesce(p.prog->'steps','[]'::jsonb)) s
                        where s->>'status' in ('awaiting_approval','blocked','needs_review')
                      )                                                              then 'box'
                      else 'green'
                    end,
      -- Měření fází a brána (viz lateral `g` níž). `ent`/`gate` smějí být prázdné
      -- a je to poctivá odpověď: „neměřeno" a „na nikoho se nečeká".
      'ent',        g.ent,
      'done',       coalesce(g.done, '[]'::jsonb),
      'gate',       g.gate,
      -- Kdy běh vstoupil do současného stavu — tower z toho počítá „v sektoru".
      'entered_at', greatest(ps.last_activity_at, ps.updated_at),
      'updated_at', greatest(ps.last_activity_at, ps.updated_at)
    ) as run
    from production_batches b
    join partner_stories ps on ps.id = b.story_id
    cross join scope sc
    cross join lateral (select get_batch_workflow_progress(b.id) as prog) p
    -- ČAS VE FÁZI, ČASY HOTOVÝCH FÁZÍ A BRÁNA. Do 2026-08-05 se neposílalo nic
    -- z toho a StoryLoopMC kreslil statickou desku: `ent` chybělo, takže věž
    -- ukazovala '—' místo „stojí to tu 40 minut", a region `panel` (inženýr
    -- u brány) zůstával vypnutý, protože bez `gate` by byl prázdný.
    --
    -- Počítá se TADY, ne v producentovi kroků: délka běžící fáze závisí na tom,
    -- KDY se ptáš, takže uložená do projekce je v okamžiku doručení neplatná.
    cross join lateral (
      select
        -- ent = jak dlouho běh stojí v aktuální (první nedokončené) fázi.
        -- Krok bez `started_at` ho NEDOSTANE: komponenta pozná chybějící hodnotu
        -- (`entKnown`) a nakreslí '—', kdežto dosazená nula by tvrdila měření,
        -- které nikdo neprovedl.
        (select round(extract(epoch from now() - (s->>'started_at')::timestamptz))
           from jsonb_array_elements(coalesce(p.prog->'steps','[]'::jsonb)) s
          where s->>'status' not in ('completed','failed')
            and s->>'started_at' is not null
          order by (s->>'order')::int
          limit 1) as ent,
        -- done = délky fází V POŘADÍ FÁZÍ, aby indexy seděly na kotvy trati.
        -- Fáze bez obou časů dostane `null` a komponenta si na jejím místě vezme
        -- průměr (`avg`) — proto se pole NESMÍ zhustit jen na změřené kusy;
        -- posunulo by to všechny následující fáze o jednu.
        (select jsonb_agg(
                  case when s->>'started_at' is not null and s->>'completed_at' is not null
                       then round(extract(epoch from (s->>'completed_at')::timestamptz
                                                   - (s->>'started_at')::timestamptz))
                  end order by (s->>'order')::int)
           from jsonb_array_elements(coalesce(p.prog->'steps','[]'::jsonb)) s) as done,
        -- gate = krok, který čeká na ČLOVĚKA (pit wall). Tytéž stavy, ze kterých
        -- se odvozuje vlajka 'box' — jedno pravidlo, dvě podoby, takže věž nemůže
        -- svítit modře a v panelu tvrdit, že se na nic nečeká.
        (select jsonb_strip_nulls(jsonb_build_object(
                  'label', s->>'name',
                  'desc',  s->>'description',
                  'owner', s->>'assigned_role'))
           from jsonb_array_elements(coalesce(p.prog->'steps','[]'::jsonb)) s
          where s->>'status' in ('awaiting_approval','blocked','needs_review')
          order by (s->>'order')::int
          limit 1) as gate
    ) g
    -- ROZSAH: přihlášený vidí VŠE. Držet věž na členství znamenalo, že majitel
    -- firmy v ní neviděl nic — naměřeno 2026-08-03 na nasazeném extranetu:
    -- 20 599 běhů v `production_batches`, a blok hlásil „Aktivní: 0", protože
    -- k žádnému z nich nevede vazba `user_id` ani `story_participants`.
    -- Sousední blok téže sekce (get_workflow_progress_block, tentýž ovál) přitom
    -- žádný rozsah nemá — dvě neslučitelná pravidla vedle sebe. Sjednoceno na
    -- to širší; přihlášení zůstává podmínkou (viz kontrola v_uid výše).
    --
    -- ✅ 2026-08-05 — TEN „DALŠÍ KROK" JE TENHLE. Nárok je výslovný (CTE `scope`
    -- výše) a odpovídá tomu, co plocha slibuje: řidič své běhy, admin/staff
    -- všechny. Ramena jsou 1:1 s `workflow_step_visible_to`, která zůstává
    -- vlastníkem pravidla pro JEDNOTLIVÝ krok — tady je týž nárok množinově,
    -- přesně jak to předepisuje get_workflow_my_steps_block („kdo bude nárok
    -- potřebovat v dalším bloku, ať zkopíruje CTE scope“).
    --
    -- ⛔ TŘI DŮVODY, PROČ TO NESMÍ ZŮSTAT NA `where true`:
    --   1. Nárok tu fakticky DRŽEL AŽ TICHÝ VEDLEJŠÍ ÚČINEK: cizí běh spadl na
    --      `not visible` v get_batch_workflow_progress, tedy `pos = null`, a
    --      vypadl na filtru `jsonb_typeof(run->'pos') = 'number'`. Pravidlo,
    --      které drží filtr na JINÉ vlastnosti, je pravidlo, které první úprava
    --      toho filtru mlčky zruší.
    --   2. LIMIT SE APLIKOVAL PŘED NÁROKEM. Vybralo se 20 globálně nejnovějších
    --      běhů a teprve z nich se odfiltrovaly cizí — takže řidič, jehož
    --      dodávky mezi posledními dvaceti napříč firmou nejsou, viděl PRÁZDNOU
    --      věž, přestože běhy má. Nad 20 599 běhy je to pravidlo, ne okrajový
    --      případ. Filtr proto musí stát PŘED `limit`.
    --   3. Cizí běh se stejně načetl a spočítal (per-row SECURITY DEFINER
    --      volání progressu), jen se pak zahodil — práce navíc za data, která
    --      volající nesmí vidět.
    --
    -- BĚH BEZ SPOČÍTANÉHO POKROKU SE NEVYDÁVÁ. `get_batch_workflow_progress`
    -- je citlivá na autorizaci a místo pokroku umí vrátit
    -- `{"ok":false,"error":"not authenticated"}` — pak jsou `pos`, `total`,
    -- `completed` i `failed` prázdné. Maska bloku přitom `pos` vyžaduje jako
    -- číslo 0–1, takže takový řádek shodí kontrakt povrchu.
    --
    -- Naměřeno 2026-08-03 (transakce nad produkcí, rollback): pod syntetickou
    -- identitou vyšlo `"pos": null, "sectors": []`, pod skutečným uživatelem
    -- kompletní běh se třemi sektory. Dokud věž filtrovala podle členství, byla
    -- prázdná a tahle vada se nemohla projevit — odkryl ji až širší rozsah.
    --
    -- Doplnit nuly by znamenalo VYMYSLET si měření: zákon jazyka zní „žádné
    -- číslo bez zdroje". Běh, jehož pokrok neumíme spočítat, proto na věž
    -- nepatří — odfiltruje ho `filter (where …)` u agregace výše, nad hodnotou,
    -- která se skutečně vydává.
    --
    -- ⛔ `x OR EXISTS(korelovaný)` DÁVÁ PLANNERU LŽIVÝ ODHAD (naměřeno 2026-09-29).
    -- EXISTS pod OR se nedá převést na semi-join; planner z něj udělá
    -- AlternativeSubPlan (po řádcích / hashovaný). Za běhu vybere hashovaný, ale
    -- CENU počítá z první alternativy — costsize.c: „Arbitrarily use the first
    -- alternative plan for costing". Odhad tak zaplatil poddotaz za každý běh:
    -- 7,4 mil. jednotek u práce za ~170 ms, JIT se zapnul a kompiloval 1,3–1,5 s.
    -- Nekorelovaný `IN (select …)` je jediná (hashovaná) varianta a oceňuje se
    -- jednou. Rozsah se čte ze `scope` UVNITŘ poddotazu — odkaz na `sc` z vnějšího
    -- FROM by poddotaz zase zkoreloval. Ramena beze změny.
    where (v_tpl is null or b.workflow_template_id in (
            select tpl.id from production_workflow_templates tpl
            where tpl.name = v_tpl))
      and (sc.is_admin
       or b.id in (
            select s.batch_id
              from production_workflow_steps s
             cross join scope x
             where s.assigned_user_id = x.me
                or (s.assigned_role is not null and s.assigned_role = any(x.my_roles))
                or ((s.input_data->>'authorized_twin_id') = any(x.my_twins))
          ))
    -- ⛔ ŘAZENÍ MUSÍ BÝT ÚPLNÉ (naměřeno 2026-09-29): 126 běhů šablony „Odečet
    -- měřidla" má IDENTICKÉ `last_activity_at` (hromadný import 2026-09-01
    -- 01:22:11), takže `limit 30` bral libovolných 30 — výběr závisel na plánu a
    -- věž mezi voláními ukazovala jiné běhy. `b.id` jako rozhodčí to ustálí.
    order by greatest(ps.last_activity_at, ps.updated_at) desc, b.id
    limit v_limit
  ) t;

  return jsonb_build_object(
    'data', jsonb_build_object('runs', v_runs),
    'provenance', jsonb_build_object(
      'source_slug', 'production_workflow',
      'trace_id', 'wf:tower',
      'freshness_at', now()));
end;
$$;

REVOKE ALL ON FUNCTION public.get_timing_tower_block(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_timing_tower_block(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_workflow_progress_block.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_workflow_progress_block
-- Popis: Surface blok goal_progress: aktivní procesní běhy viditelné volajícímu (ovál kontrakt: pos, milestones, goal).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- Pozn.: definice = regenerát z nasazené DB (ověřeno provozním testem 07-25).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_workflow_progress_block(p_params jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_limit int := coalesce((p_params->>'limit')::int, 8);
  v_runs jsonb;
begin
  if v_uid is null and not is_service_role() then
    return jsonb_build_object('data', jsonb_build_object('runs','[]'::jsonb),
      'provenance', jsonb_build_object('source_slug','production_workflow','trace_id','wf:progress','freshness_at',now()));
  end if;
  select coalesce(jsonb_agg(run order by run->>'updated_at' desc), '[]'::jsonb) into v_runs
  from (
    select jsonb_build_object(
      'batch_id', b.id, 'story_id', b.story_id,
      'title', ps.title, 'state', prog->>'state', 'pos', (prog->>'pos')::numeric,
      'total', (prog->>'total')::int, 'completed', (prog->>'completed')::int,
      'failed', (prog->>'failed')::int,
      'milestones', prog->'steps',
      'goal', gs.last_evaluator_output,
      'updated_at', greatest(ps.last_activity_at, ps.updated_at)) as run
    from production_batches b
    join partner_stories ps on ps.id = b.story_id
    left join story_goal_state gs on gs.story_id = b.story_id
    cross join lateral (select get_batch_workflow_progress(b.id) as prog) p
    where b.story_id is not null
      and ps.status = 'active'
      and (p_params->>'batch_id' is null or b.id = (p_params->>'batch_id')::uuid)
      and (p_params->>'story_id' is null or b.story_id = (p_params->>'story_id')::uuid)
      and (prog->>'ok')::boolean   -- visibility enforced inside progress fn
    limit v_limit
  ) t;
  return jsonb_build_object(
    'data', jsonb_build_object('runs', v_runs),
    'provenance', jsonb_build_object('source_slug','production_workflow',
      'trace_id','wf:progress','freshness_at',now()));
end $function$;

REVOKE ALL ON FUNCTION public.get_workflow_progress_block(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_workflow_progress_block(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_workflow_progress_block(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_workflow_step_detail.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_workflow_step_detail
-- Popis: JEDEN milník procesu podle id — čtení pro obrazovku, která ho odbavuje.
--        Terénní fronta (`get_my_workflow_steps`) je z principu OSOBNÍ a řadí
--        se podle termínu; tohle je opačná otázka: „ukaž mi TENHLE krok".
--
-- PROČ VZNIKLA (2026-08-05, zadání majitele):
--   „Chci si jako admin vybrat dodák a vidět ho tak, jak to je v reálu — jaký
--    má stav a čí je. A platí to úplně plošně."
--   Dispečerská fronta (blok `all_assignees`) cizí předání UKAZOVALA, ale
--   otevřít je nešlo: potvrzovací obrazovka appky čte `get_my_workflow_steps`,
--   která vrací jen vlastní kroky. Admin tedy viděl seznam a neměl jak do něj
--   vstoupit. Chybějící článek nebyl nárok (ten už existoval), ale ČTENÍ
--   JEDNOHO KROKU s dispečerským rozsahem.
--
-- ⭐ ROZSAH ROZHODUJE PREDIKÁT, NE TAHLE FUNKCE
--   Volá se `workflow_step_visible_to(..., 'dispatch')` BEZPODMÍNEČNĚ: tahle
--   funkce jen říká, CO chce vidět, a predikát rozhodne, kdo to smí. Kdo není
--   admin/staff, projde běžnými rameny (přiřazení · role · potvrzená twin
--   vazba) a cizí krok nedostane. Žádná role-logika tady tedy není a být nesmí
--   (brána workflow-visibility-single-decider), jinak by šla smazat jedním
--   řádkem v obyčejné čtecí funkci.
--
-- ⭐ REALITA, NE PŘEVTĚLENÍ
--   Admin NEVIDÍ krok „jako řidič" v tom smyslu, že by se za něj vydával —
--   vidí ho takový, jaký je, VČETNĚ toho, komu patří (`assigned_to`,
--   `assigned_twin`) a jak dopadl (`status`, `has_deviation`, `completed_by_name`).
--   `is_mine` říká, jestli by na krok dosáhl i BEZ dispečerského rozsahu, takže
--   klient umí čestně napsat „potvrzujete za někoho jiného". Zápis pak stejně
--   nese pravdu: `complete_workflow_step` ukládá `completed_by = auth.uid()`,
--   tedy toho, kdo doopravdy klikl. Kdyby se identita v pohledu podvrhla,
--   evidence by tvrdila něco jiného než audit.
--
-- ⚠️ JMÉNA ÚČTŮ jen tomu, kdo dispečuje (nebo o sobě). `profiles.display_name`
--   je osobní údaj; kolega, který krok vidí přes SDÍLENOU ROLI, dostane label
--   twinu (ten je i v konfiguraci fronty jako `input:driver_name`), ale ne
--   identitu účtu. Je to podmínka NAD SLOUPCEM, ne ve výběru řádků — řádek už
--   je autorizovaný výše.
--
-- ⚠️ Neexistující krok a krok BEZ NÁROKU vracejí obojí PRÁZDNO, ne chybu.
--   Rozlišit je by z funkce udělalo orákulum na existenci cizích běhů.
--
-- Výkon: čte JEDEN řádek podle primárního klíče, takže per-row cena predikátu
-- (SECURITY DEFINER = žádný inline) tu nehraje roli. Množinová varianta téhož
-- nároku patří do bloků — viz CTE `scope` v get_workflow_my_steps_block.
--
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_workflow_step_detail(p_step_id uuid)
 RETURNS TABLE(
   step_id uuid, step_code text, step_name text, step_order integer, status text,
   batch_id uuid, batch_code text, product_name text, production_date date,
   assigned_role text, description text, input_data jsonb, output_data jsonb,
   started_at timestamp with time zone, completed_at timestamp with time zone,
   has_deviation boolean, notes text,
   assigned_to text, assigned_twin text, completed_by_name text, is_mine boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_s      public.production_workflow_steps%rowtype;
  v_b      public.production_batches%rowtype;
  v_mine   boolean;
  v_named  boolean;
  -- Účet zařízení (tablet, F2): dostane jen PROJEKCI kroku — viz níž.
  v_zarizeni boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN;
  END IF;

  SELECT * INTO v_s FROM public.production_workflow_steps s WHERE s.id = p_step_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Rozsah deklaruje volající, POVOLUJE ho predikát. Viz hlavička.
  -- Kód kroku z ŘÁDKU: bez něj pátá cesta predikátu (tablet) neplatí (F2, 2026-09-29).
  IF NOT public.workflow_step_visible_to(
           v_uid, v_s.assigned_user_id, v_s.assigned_role, v_s.input_data, 'dispatch', v_s.step_code) THEN
    RETURN;
  END IF;

  -- Týž predikát BEZ rozsahu = „dosáhl bych na to i jako řadový uživatel?".
  -- Odpověď je to, co klient napíše člověku na obrazovku, ne kosmetika.
  v_mine := public.workflow_step_visible_to(
              v_uid, v_s.assigned_user_id, v_s.assigned_role, v_s.input_data, NULL, v_s.step_code);

  -- ⛔ TABLET DOSTANE JEN PROJEKCI (F2-C, majitel 2026-09-29: osobní údaje odběratele
  -- na tablet NEJDOU). input_data jen přes kiosk_projekce (`pole` rozsahu instance);
  -- output_data (přebírající, podpis z dřívějšího potvrzení), poznámka, název běhu
  -- (subject_label = „{odběratel} — {DL}“) a štítek dvojčete se účtu zařízení nevydají.
  -- Příznak nese SERVER (vazba průkazu), ne klient ani metadata účtu.
  v_zarizeni := EXISTS (SELECT 1 FROM public.knock_device_credentials d WHERE d.ucet_id = v_uid);

  SELECT * INTO v_b FROM public.production_batches b WHERE b.id = v_s.batch_id;

  -- Identitu ÚČTU vydáváme jen dispečerovi; člověk o sobě ji dostane vždycky
  -- (podmínka u sloupce níž). Viz hlavička.
  --
  -- ⛔ `v_mine` tu ZÁMĚRNĚ NENÍ, i když se to nabízí. Predikát vrací true i pro
  --    viditelnost přes SDÍLENOU ROLI — na krok tedy dosáhne celá směna, a jméno
  --    kolegy, kterému je přiřazený, jim do fronty nepatří. Změřeno sondou
  --    workflow-step-detail (případ „kolega vidí krok, ale ne jméno").
  v_named := public.is_admin_or_staff();

  RETURN QUERY
  SELECT
    v_s.id, v_s.step_code, v_s.step_name, v_s.step_order, v_s.status,
    v_s.batch_id, v_b.batch_code,
    CASE WHEN v_zarizeni THEN NULL ELSE v_b.product_name END,
    v_b.production_date,
    v_s.assigned_role, v_s.description,
    CASE WHEN v_zarizeni THEN public.kiosk_projekce(v_s.step_code, v_s.input_data) ELSE v_s.input_data END,
    CASE WHEN v_zarizeni THEN NULL ELSE v_s.output_data END,
    v_s.started_at, v_s.completed_at, v_s.has_deviation,
    CASE WHEN v_zarizeni THEN NULL ELSE v_s.notes END,
    CASE WHEN v_s.assigned_user_id IS NOT NULL
              AND (v_named OR v_s.assigned_user_id = v_uid)
         THEN (SELECT p.display_name FROM public.profiles p
                WHERE p.user_id = v_s.assigned_user_id LIMIT 1) END,
    -- Twin, na který je uzel vázaný (u dodáku řidič). Label, ne id: id je klíč,
    -- jméno je to, co dispečer čte.
    -- ⚠️ Tvar se OVĚŘUJE před přetypováním. `input_data` je konfigurace uzlu, tedy
    -- DATA instance — nečíselné id by tu jinak neshodilo jedno jméno, ale celé
    -- čtení kroku, a obrazovka by hlásila „nenalezeno" místo „vazba je pokažená".
    CASE WHEN NOT v_zarizeni AND v_s.input_data->>'authorized_twin_id'
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         THEN (SELECT te.label FROM public.twin_entities te
                WHERE te.id = (v_s.input_data->>'authorized_twin_id')::uuid) END,
    CASE WHEN v_s.completed_by IS NOT NULL
              AND (v_named OR v_s.completed_by = v_uid)
         THEN (SELECT p.display_name FROM public.profiles p
                WHERE p.user_id = v_s.completed_by LIMIT 1) END,
    v_mine;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_workflow_step_detail(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_workflow_step_detail(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_workflow_step_detail(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_workflow_step_polozky.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: get_workflow_step_polozky(p_step_id uuid) → jsonb
-- Popis: POLOŽKY DOKLADU KROKU — co, kolik a čeho odvézt — pro toho, kdo KROK vidí.
--
-- ⭐ Majitel 2026-09-30: „v mobilní aplikaci řidiče nevidím detail dodávky/dokladu —
--    co, kolik a čeho odvézt“. Položky na dokladu JSOU (li_source_registry.line_items,
--    RIQi read-only 30. 9.: 17/17 předání v okně tabletu, klíče item_code / item_name /
--    quantity / unit), ale tablet se k nim nedostal: detail kroku mu nevydá doc_slug
--    a registr účtu zařízení žádný doklad neukáže (nárok registru jde přes
--    li_doc_slugs_claimed_by, který rameno zařízení nezná).
--
-- PROČ POLOŽKY JDOU S KROKEM, NE PŘES REGISTR: nárok na KROK už rozhoduje jediný
--   rozhodce (workflow_step_visible_to, tady se stejným rozsahem jako detail kroku).
--   Rozšířit RLS registru o zařízení by otevřelo celý doklad (hlavička, odběratel,
--   částky); tady jde ven JEN seznam položek toho jednoho dokladu, na který ukazuje
--   krok. doc_slug ani registr volající nedostane.
--
-- PROJEKCE: tablet (účet zařízení) dostane z řádku položky JEN klíče `pole_polozek`
--   řádků kiosk_rozsah, které krok pouštějí (stejná podmínka jako větev zařízení
--   predikátu). Prázdné = nic (fail-closed). Člověk s nárokem na krok dostane celý
--   řádek (hodnoty bez provenance). Druhá cesta pro člověka s nárokem na DOKLAD
--   (get_document_detail) zůstává, jak je — tohle ji nenahrazuje ani nezastupuje.
--   Neprázdný řádek nese i `stav_radku` (stav řádku v registru, tj. prošel/neprošel
--   branami), aby povrch mohl přiznat „čeká na kontrolu“ — řádek bez pustitelných
--   klíčů se nevydá vůbec (ani se stavem).
--
-- VERZE DOKLADU: krok nese ukazatel `doc_slug` z doby, kdy vznikl; novější verze
--   dokladu má jiný slug a starou označí `superseded_by`. Položky se proto berou
--   z PLATNÉ verze po řetězu (nejvýš 10 kroků); bez platné verze z poslední známé.
--   Klíč identity dokladu se nehádá — řetěz vede registr sám.
--
-- Vrací {ok, doklad, polozky[]}. Neexistující krok i krok bez nároku = týž
--   {ok:false, error:'nenalezeno'} (žádná věštírna na cizí běhy). Krok bez dokladu
--   v registru = {ok:true, doklad:false, polozky:[]} — poctivé „nevím“, ne chyba.
--
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern (authenticated + service_role).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_workflow_step_polozky(p_step_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid      uuid := auth.uid();
  v_s        public.production_workflow_steps%rowtype;
  v_zarizeni boolean;
  v_klice    text[] := '{}'::text[];
  v_slug     text;
  v_radky    jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nenalezeno');
  END IF;

  SELECT * INTO v_s FROM public.production_workflow_steps s WHERE s.id = p_step_id;
  -- Týž rozsah jako get_workflow_step_detail: kód kroku z ŘÁDKU (pátá cesta — tablet).
  IF NOT FOUND OR NOT public.workflow_step_visible_to(
       v_uid, v_s.assigned_user_id, v_s.assigned_role, v_s.input_data, 'dispatch', v_s.step_code) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nenalezeno');
  END IF;

  -- Příznak zařízení nese SERVER (vazba průkazu), ne klient — jako v detailu kroku.
  v_zarizeni := EXISTS (SELECT 1 FROM public.knock_device_credentials d WHERE d.ucet_id = v_uid);
  IF v_zarizeni THEN
    SELECT coalesce(array_agg(DISTINCT k.klic), '{}'::text[]) INTO v_klice
      FROM public.kiosk_rozsah r
      CROSS JOIN LATERAL unnest(r.pole_polozek) AS k(klic)
     WHERE r.aktivni
       AND r.step_code = v_s.step_code
       AND coalesce(v_s.input_data, '{}'::jsonb) @> r.input_match
       AND (NOT r.jen_flotila OR public.kiosk_krok_nasi_flotily(coalesce(v_s.input_data, '{}'::jsonb)));
  END IF;

  WITH RECURSIVE verze AS (
    SELECT r.doc_slug, r.superseded_by, r.line_items, r.ingested_at, 1 AS hloubka
      FROM public.li_source_registry r
     WHERE r.doc_slug = v_s.input_data->>'doc_slug'
    UNION ALL
    SELECT n.doc_slug, n.superseded_by, n.line_items, n.ingested_at, v.hloubka + 1
      FROM verze v
      JOIN public.li_source_registry n ON n.doc_slug = v.superseded_by
     WHERE v.superseded_by IS NOT NULL
       AND v.hloubka < 10
  )
  SELECT v.doc_slug, v.line_items INTO v_slug, v_radky
    FROM verze v
   ORDER BY (v.superseded_by IS NULL) DESC, v.hloubka DESC, v.ingested_at DESC
   LIMIT 1;

  RETURN jsonb_build_object(
    'ok', true,
    'doklad', v_slug IS NOT NULL,
    'polozky', coalesce((
      SELECT jsonb_agg(
               CASE WHEN jsonb_typeof(p.stav) = 'string'
                    THEN p.radek || jsonb_build_object('stav_radku', p.stav)
                    ELSE p.radek END
               ORDER BY p.poradi)
        FROM (
          SELECT li.poradi,
                 li.polozka->'status' AS stav,
                 (SELECT coalesce(jsonb_object_agg(f.key, f.value->'value'), '{}'::jsonb)
                    FROM jsonb_each(CASE WHEN jsonb_typeof(li.polozka->'fields') = 'object'
                                         THEN li.polozka->'fields' ELSE '{}'::jsonb END) f
                   WHERE jsonb_typeof(f.value) = 'object'
                     AND f.value ? 'value'
                     AND (NOT v_zarizeni OR f.key = ANY (v_klice))) AS radek
            FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_radky) = 'array' THEN v_radky ELSE '[]'::jsonb END)
                 WITH ORDINALITY AS li(polozka, poradi)
        ) p
       WHERE p.radek <> '{}'::jsonb), '[]'::jsonb));
END;
$function$;

REVOKE ALL ON FUNCTION public.get_workflow_step_polozky(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_workflow_step_polozky(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_workflow_step_polozky(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/li_doc_slugs_claimed_by.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: li_doc_slugs_claimed_by
-- Popis: Doklady, na které má volající STRUKTURÁLNÍ nárok — „tenhle doklad
--        vezu já". Vrací `doc_slug` kroků procesu, které jsou volajícího
--        (přiřazení, nebo potvrzená vazba účtu na `authorized_twin_id`).
--        Rozhodovač je JEDEN: `workflow_step_visible_to`. Tahle funkce nic
--        nerozhoduje, jen mu dává kroky a sbírá `doc_slug`.
--
-- PROČ FUNKCE, A NE PODDOTAZ V POLITICE (naměřeno 2026-09-10):
--   Politika `li_source_registry_read` (6c65216f4, 2026-09-01) nesla týž
--   poddotaz inline. Jenže výraz politiky se vyhodnocuje pod rolí VOLAJÍCÍHO,
--   a `production_workflow_steps` má jedinou politiku — `is_admin_or_staff`.
--   Pro řidiče (role `authenticated`) proto poddotaz vracel 0 řádků a člen
--   nikdy nic nepustil: řidič svůj doklad neviděl ani po „opravě". Test, který
--   to měl hlídat (`doklad-narok-strukturalni-runtime`), nikdo nespouštěl.
--   Změřeno pod `SET ROLE authenticated` s jwt.claims řidiče:
--     kroky přímo 0 · poddotaz členu 0 · registr 0 · vazba potvrzená 1
--   SECURITY DEFINER čte kroky vlastníkem — a rozsah drží guard níž, ne RLS.
--
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern; volající smí
--   vyhodnocovat JEN SVŮJ nárok (service_role / admin za kohokoliv).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.li_doc_slugs_claimed_by(p_uid uuid)
RETURNS SETOF text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_twins text[] := '{}';
  v_roles text[] := '{}';
BEGIN
  -- Oracle guard: přihlášený volající smí vyhodnocovat JEN SVŮJ nárok.
  IF p_uid IS NULL
     OR NOT (p_uid = auth.uid() OR public.is_service_role() OR public.is_admin_or_staff()) THEN
    RETURN;
  END IF;

  -- ⛔ VAZBY JEDNOU, NE PER KROK (naměřeno 2026-09-10). Predikát je plpgsql
  -- s dynamickým SQL a stojí ~0,34 ms na volání. Předfiltr `input_data ?
  -- 'authorized_twin_id'` pouštěl ke drahému predikátu KAŽDÝ krok, který ten
  -- klíč má — tedy i cizí. Řidič s JEDINÝM vlastním krokem platil za všechny:
  --     cizích kroků    0 → 10 ms · 1 000 → 309 ms · 5 000 → 1 716 ms
  -- Při stotisících krocích je to desítky sekund na výpis dokladů, a spustí to
  -- kterýkoli přihlášený. Přesně ta DoS páka, před kterou varuje hlavička
  -- `li_source_registry_read`. Vazba je přitom vlastnost VOLAJÍCÍHO, ne kroku,
  -- takže se čte jednou dopředu.
  --
  -- ⚠️ Volitelný subsystém: `twin_external_refs` nemusí být nainstalovaný
  -- (týž důvod pro dynamic SQL jako ve `workflow_step_visible_to`).
  IF to_regclass('public.twin_external_refs') IS NOT NULL THEN
    EXECUTE $q$
      SELECT coalesce(array_agg(r.twin_id::text), '{}')
        FROM public.twin_external_refs r
       WHERE r.ref_kind = 'account' AND r.state = 'confirmed'
         AND r.source_key = $1::text
         AND r.valid_from <= now()
         AND (r.valid_to IS NULL OR r.valid_to > now())
    $q$ INTO v_twins USING p_uid;
  END IF;

  -- ⛔ ROLE JEDNOU, NE PER KROK (naměřeno 2026-09-29 na produkci, člen bez role,
  -- 123 237 kroků, 9 495 s `doc_slug`). Tatáž lekce jako u vazeb výš, jen
  -- nedotažená: `has_role(p_uid, s.assigned_role)` se volal pro 6 330 kroků
  -- s rolí — 4 908 ms samotného předfiltru. Role jsou vlastnost VOLAJÍCÍHO;
  -- pole jednou dopředu → 80 ms, výsledek shodný. Guard výš už vynucuje totéž,
  -- co `has_role` (odpovídá jen o volajícím, službě a správě o komkoli), takže
  -- přímé čtení `user_roles` pro `p_uid` nic neprozradí navíc.
  SELECT coalesce(array_agg(ur.role::text), '{}')
    INTO v_roles
    FROM public.user_roles ur
   WHERE ur.user_id = p_uid;

  -- ⛔ PŘEDFILTR MUSÍ BĚŽET PŘED PREDIKÁTEM — a Postgres to nezaručí
  -- (naměřeno 2026-09-29). Podmínky v jednom WHERE řadí planner podle
  -- deklarované COST, ne podle pořadí v textu; predikát má COST 100 a OR
  -- předfiltru vyšel o chlup dráž, takže plán zněl
  --   Filter: (input_data ? 'doc_slug') AND workflow_step_visible_to(…) AND (předfiltr)
  -- a drahý predikát (~0,56 ms) běžel na VŠECH 9 495 krocích s dokladem:
  -- 5,4 s na každé čtení registru běžným uživatelem (politika
  -- `li_source_registry_read` volá tuhle funkci), pro 0 vrácených řádků.
  -- MATERIALIZED CTE je optimalizační plot: predikát dostane JEN kandidáty.
  RETURN QUERY
    WITH kandidati AS MATERIALIZED (
      SELECT s.assigned_user_id, s.assigned_role, s.input_data
        FROM public.production_workflow_steps s
       WHERE s.input_data ? 'doc_slug'
         -- Brána, ne pravidlo: předfiltr je přesně SJEDNOCENÍ větví, na kterých
         -- predikát vrací pravdu (přiřazení · role · potvrzená vazba). Nesmí být
         -- užší, jinak zmizí viditelnost, kterou predikát dává; širší být může,
         -- ale platí se to jeho voláním. Rozhodnutí zůstává na predikátu níž.
         AND (s.assigned_user_id = p_uid
              OR s.input_data->>'authorized_twin_id' = ANY (v_twins)
              OR s.assigned_role = ANY (v_roles))
    )
    SELECT DISTINCT k.input_data->>'doc_slug'
      FROM kandidati k
     WHERE public.workflow_step_visible_to(p_uid, k.assigned_user_id, k.assigned_role, k.input_data);
END;
$$;

REVOKE ALL ON FUNCTION public.li_doc_slugs_claimed_by(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.li_doc_slugs_claimed_by(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.li_doc_slugs_claimed_by(uuid) TO service_role;

COMMENT ON FUNCTION public.li_doc_slugs_claimed_by(uuid) IS
  'Doklady se strukturálním nárokem volajícího (doc_slug kroků, které jsou jeho). Definer: poddotaz pod rolí volajícího narážel na admin-only RLS kroků.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/resolve_entity_reference.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: resolve_entity_reference
-- Popis: PŘESNÝ KLÍČ → ENTITA. „12345" → tenhle dodák. Nic víc a hlavně nic
--        chytřejšího: shoda je EXAKTNÍ, takže odpověď je buď jistá, nebo žádná.
--
-- PROČ VZNIKLA (2026-08-05, zadání majitele):
--   „Dohledat to přes dotaz AIŠE, která by nás na ten list měla nasměrovat…
--    a dodáky jí samozřejmě chceme dát taky, vše." + „multi twinverse".
--
--   Odpovídač si dodnes rozřazuje otázku REGEXEM nad kmeny a dodák mezi jeho
--   záměry vůbec není. Přidat tam další regex by bylo stavění na tom, co už
--   jednou selhalo (odpovídač vrátil na „kolik je hodin?" přehled nájemců
--   s pokrytím FULL). Číslo dokladu ale NENÍ úloha pro model — je to KLÍČ.
--   Proto tahle funkce: hledá SHODU, nehádá záměr. Když nenajde, mlčí.
--
-- ⭐ KLÍČE JSOU DATA, NE KÓD (a proto to nese celý twinverse)
--   Které pole je identita, se čte z `twin_parameter_definitions`
--   (`metadata->>'identity' = 'true'`) — tedy z KATALOGU, který instance plní
--   svými parametry. V téhle funkci proto nestojí ani jedno instanční slovo:
--   žádné 'dl_number', žádné 'cislo_om'. Nový druh entity s vlastní identitou
--   = ŘÁDEK v katalogu, ne větev tady a ne release. (Hlídá to i split-rule
--   brána: generické kanály nesmí jmenovat instanci.)
--
-- ⛔ NEJEDNOZNAČNOST = ŽÁDNÝ VÝSLEDEK.
--   Když týž klíč sedí na víc záznamů, funkce nevrátí NIC a řekne proč. Vybrat
--   „ten první" by znamenalo poslat člověka na doklad, který si nevybral —
--   a on by to nepoznal, protože by dostal platně vypadající obrazovku.
--   (Čísla dokladů se přes firmy opakují; naměřeno 804 kolizí.)
--
-- ⚠️ NÁROK SE NEOBCHÁZÍ. Krok se vrátí jen tomu, kdo na něj dosáhne —
--   rozhoduje TÝŽ sdílený predikát a týmž způsobem jako všude jinde: rozsah
--   'dispatch' se předává bezpodmínečně a povoluje ho predikát, ne tahle
--   funkce. Bez toho by z resolveru bylo orákulum na cizí doklady: „existuje
--   dodák 12345?" by šlo zjistit i bez práva ho vidět.
--
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- ============================================================================

CREATE OR REPLACE FUNCTION public.resolve_entity_reference(p_key text)
 RETURNS TABLE(entity_kind text, entity_id uuid, label text, matched_by text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_key text := nullif(btrim(coalesce(p_key, '')), '');
BEGIN
  IF v_uid IS NULL OR v_key IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH hits AS (
    -- Kandidáti: kroky, jejichž konfigurace nese IDENTITNÍ parametr s touhle
    -- hodnotou. Katalog říká, které kódy to jsou; funkce žádný nezná jménem.
    --
    -- `@>` (containment), ne `->> = `: sahá na GIN index nad input_data, kdežto
    -- extrakce klíče by znamenala průchod všemi kroky pro každý kód katalogu.
    -- Týž tvar používá `input_match` ve frontě.
    SELECT s.id AS step_id, d.code AS code, b.batch_code AS run_label
      FROM public.twin_parameter_definitions d
      JOIN public.production_workflow_steps s
        ON s.input_data @> jsonb_build_object(d.code, v_key)
      JOIN public.production_batches b ON b.id = s.batch_id
     WHERE d.metadata->>'identity' = 'true'
       -- Nárok: rozsah deklaruje volající, POVOLUJE ho predikát (viz hlavička).
       AND public.workflow_step_visible_to(
             v_uid, s.assigned_user_id, s.assigned_role, s.input_data, 'dispatch')
     -- Dva stačí: rozhoduje se JEDEN × VÍC NEŽ JEDEN, ne kolik přesně.
     LIMIT 2
  )
  SELECT 'workflow_step'::text, h.step_id, coalesce(h.run_label, v_key), h.code
    FROM hits h
   -- ⛔ Nejistota znamená ŽÁDNÝ výsledek, ne „ten první". Viz hlavička.
   WHERE (SELECT count(*) FROM hits) = 1;
END;
$function$;

REVOKE ALL ON FUNCTION public.resolve_entity_reference(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.resolve_entity_reference(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_entity_reference(text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/get_answer_block.sql
-- -----------------------------------------------------------------------------

-- get_answer_block — blok „Zeptej se".
--
-- Kontrakt bloku: první sloupec je prozaická odpověď, každý další je číslo/údaj
-- zobrazený vedle ní (AskPanel to čte podle DEKLAROVANÝCH sloupců, ne podle jmen).
--
-- ── 2026-07-30: SCOPE JAKO VEKTOR, ZANESENÝ DO SYSTÉMU ──────────────────────
-- Dřív tahle funkce poslala otázku odpovídači a vrátila dva sloupce. Scope si
-- odpovídač HÁDAL z textu otázky a nikde se nezapsalo, kdo se pod jakým pohledem
-- co dozvěděl. Dvě důsledky, oba naměřené, ne teoretické:
--   ŠUM — dva zdroje pravdy o scope (volba uživatele × slova v otázce) a silnější
--   byl ten nezamýšlený: „kolik je hodin?" → přehled nájemců, coverage FULL
--   (produkce 07-29, zapsáno v hlavičce answer_verified_facts).
--   ODPOVĚDNOST — funkce spočítala `intent` a `source` a poslala na drát jen
--   `answer` + `coverage`. Doklad o tom, čím je odpověď podložená, se zahodil
--   v posledním kroku.
-- Odteď: scope je AUTORITATIVNÍ vstup (`p_params.scope`, vektor souřadnic),
-- rozřeší ho JEDINÝ vlastník pravidla (`scope_effective`), běh se ZAPÍŠE do
-- `ai_runs` + `ai_trace_events` s vazbou na story (`scope_story_id`) a vrácená
-- provenance nese `scope_requested` / `scope_effective` / `run_id`.
--
-- PROČ JE FUNKCE VOLATILE (byla `stable`): zapisuje běh. Deklarovat ji dál jako
-- stable by byla lež směrem k plánovači i k PostgRESTu.
--
-- ZPĚTNÁ KOMPATIBILITA JAKO VLASTNOST, NE JAKO OHLED: nová pole v `provenance`
-- se posílají VÝHRADNĚ tomu, kdo scope poslal. Ajv je all-or-nothing — jedno
-- neznámé pole zneplatní CELÝ blok, get_block_data se nezavolá a na obrazovce je
-- „data se nepodařilo načíst". Povrchy se přitom nasazují jinou kadencí než jádro
-- (jádro NEpřebuduje povrch), takže obě pořadí nasazení musí být bezpečná:
-- starý klient scope neposílá → dostane bajtově tutéž obálku jako dřív.
-- Běh se ale zapisuje VŽDY: autoritou je záznam, ne jeho ozvěna v odpovědi.

create or replace function public.get_answer_block(p_params jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
security definer
SET search_path TO 'public', 'pg_temp'
as $$
declare
  v_uid uuid := auth.uid();
  v_q text := coalesce(p_params->>'question', p_params->>'q', '');
  v_a jsonb;
  v_scope_req jsonb;
  v_story jsonb;
  v_run uuid;
  v_run_note text;
  v_prov jsonb;
  /** Na CO odpověď ukazuje (entity_kind + id), když se dal najít přesný klíč. */
  v_target jsonb;
  v_cols jsonb := jsonb_build_array(
    jsonb_build_object('key','odpoved','label_key','app.cols.answer'),
    jsonb_build_object('key','pokryti','label_key','app.cols.coverage'),
    -- Zdroj patří VEDLE odpovědi. Odpovídač ho počítá od začátku; do 07-30 ho
    -- tenhle blok zahazoval, takže na obrazovce stálo tvrzení bez doložení.
    jsonb_build_object('key','zdroj','label_key','app.cols.source'));
  v_empty jsonb := jsonb_build_object(
    'data', jsonb_build_object('columns', v_cols, 'rows', '[]'::jsonb),
    'provenance', jsonb_build_object(
      'source_slug',  'answer_verified_facts',
      'trace_id',     'answer_chain:answer',
      'freshness_at', now()));
begin
  -- ⛔ FAIL-CLOSED STRÁŽ — a musí ověřovat NÁROK, ne jen přihlášení.
  --
  -- `security definer` obchází RLS, takže tahle funkce si autorizaci musí udělat
  -- SAMA. Do 2026-08-01 se ptala jen „je někdo přihlášen?", a to nestačí:
  -- naměřeno na produkci, že uživatel BEZ JEDINÉ ROLE dostal z chatu celkový
  -- roční nájem i největšího nájemce jménem — zatímco z každého bloku nad TÝMIŽ
  -- daty dostal 0 řádků. Sesterská cesta mlčela, tahle mluvila; přesně tak se
  -- tenhle druh díry pozná.
  --
  -- Nárok se tu proto ptá stejně, jak ho RLS vyhodnocuje blokům. Odpověď je
  -- PRÁZDNÁ, ne chyba — kdo nemá nárok, se nemá dozvědět ani to, že se ptal na
  -- něco existujícího; a prázdná větev zůstává bajtově stejná i pro volajícího
  -- se scope.
  if not (public.is_service_role() or public.is_admin_or_staff()) then
    return v_empty;
  end if;

  if v_q = '' then
    return v_empty;
  end if;

  -- Vadný vektor je CHYBA, ne tichý průchod: odpovědět nezúženě na dotaz, který
  -- si zúžení vyžádal, je přesně ta lež, kvůli které tenhle mechanismus vznikl.
  -- Padne jen tenhle blok (App loguje a přeskočí ho), ne celá konzole.
  v_scope_req := public.scope_normalize(p_params->'scope');

  -- Instanční konfigurace PROCHÁZÍ, neinterpretuje se tady: `source_params`
  -- bloku jsou už v `p_params` (get_block_data je slévá s parametry volajícího),
  -- takže vzory nájemních položek — vlastnost PODNIKU, ne platformy — dorazí
  -- k odpovídači, aniž by je platforma musela znát. Bez nich derivace mlčí
  -- a přizná to, místo aby si domyslela.
  v_a := public.answer_verified_facts(
           v_q,
           coalesce(p_params->>'style', 'strucny'),
           v_scope_req,
           coalesce(p_params->'config', '{}'::jsonb));

  -- ── ZÁPIS BĚHU ────────────────────────────────────────────────────────────
  -- Vazba na story je to, co dělá z odpovědi přiřaditelný akt: běh vždy patří ke
  -- story. Když scope story neurčuje, `scope_story_id` vrátí NULL i DŮVOD —
  -- trigger běh zakotví do stack-default story a důvod jde do metadat, takže
  -- „tenhle pohled ještě není uzel" je čitelný fakt, ne mlčení.
  v_story := public.scope_story_id(v_scope_req);
  begin
    v_run := public.create_ai_run(
      'chat',
      nullif(v_story->>'story_id','')::uuid,
      v_uid,
      jsonb_build_object(
        'source',       'answer_verified_facts',
        'deterministic', true,
        'scope',        v_a->'scope',
        'story_origin', v_story->>'origin',
        'story_detail', v_story->>'detail'),
      -- Odpověď je deterministické čtení ověřených faktů: žádné volání modelu,
      -- tedy nula. Bez tohohle by se běh admitoval proti p90 odhadu druhu
      -- „chat" a na přečerpané story by se ZÁZNAM ztratil právě tam, kde je
      -- odpovědnost nejdůležitější.
      0);

    insert into public.ai_trace_events
      (run_id, event_type, agent_slug, operation, status, duration_ms, cost_json,
       request_summary, response_summary)
    values
      (v_run, 'memory_read', 'answer', 'answer_verified_facts', 'ok', 0,
       jsonb_build_object('usd', 0),
       -- Co se ptalo a POD JAKÝM vektorem. Bez otázky je záznam nečitelný,
       -- bez vektoru nepřiřaditelný.
       jsonb_build_object('question', v_q, 'scope', v_a->'scope',
                          'scope_dropped', v_a->'scope_dropped'),
       jsonb_build_object('intent', v_a->>'intent', 'coverage', v_a->>'coverage',
                          'source', v_a->>'source'));

    perform public.finish_ai_run(v_run, 'succeeded', jsonb_build_object(
      'intent', v_a->>'intent', 'coverage', v_a->>'coverage', 'source', v_a->>'source',
      'scope', v_a->'scope', 'scope_dropped', v_a->'scope_dropped'));
  exception when others then
    -- VÝJIMKA JE DIAGNOSTIKA: odpověď už vznikla z dat, na která volající PRÁVO
    -- MÁ (RLS ji pustila), takže ji nezadržíme — ale důvod, proč není záznam,
    -- se PŘIZNÁ v provenance. Tichý discard by z chybějícího záznamu udělal
    -- neexistující problém. Typický případ: spend admission vrátí ask/deny.
    v_run := null;
    v_run_note := left(coalesce(sqlerrm, 'run not recorded'), 200);
  end;

  v_prov := jsonb_build_object(
    'source_slug',  'answer_verified_facts',
    'trace_id',     'answer_chain:answer',
    'freshness_at', now());

  -- Nová pole jen tomu, kdo se pod pohledem ptal (viz hlavička).
  if v_scope_req <> '[]'::jsonb then
    v_prov := v_prov || jsonb_build_object(
      'scope_requested', v_scope_req,
      'scope_effective', coalesce(v_a->'scope', '[]'::jsonb),
      'scope_dropped',   coalesce(v_a->'scope_dropped', '[]'::jsonb))
      || case when v_run is not null
              then jsonb_build_object('run_id', v_run::text)
              else jsonb_build_object('run_note', coalesce(v_run_note, 'run not recorded')) end;
  end if;

  -- ── CÍL: „a je to tenhle záznam" ──────────────────────────────────────────
  --
  -- Odpověď uměla TVRDIT, ale ne UKÁZAT. Aby na dotaz „kde je dodák 12345"
  -- mohl klient ten doklad otevřít, musí odpověď nést cíl — a ten kanál vzniká
  -- DŘÍV než chytrost, protože bez něj je nasměrování nevyjádřitelné, ať je
  -- rozřazení záměru jakkoli dobré.
  --
  -- ⭐ NEROZŠIŘUJE SE TÍM KLASIFIKACE. `resolve_entity_reference` hledá EXAKTNÍ
  --    shodu klíče, nehádá záměr: každé slovo otázky se zkusí jako klíč a uspěje
  --    jen jednoznačná shoda. Přidat místo toho další regex do klasifikátoru by
  --    bylo stavění na tom, co už jednou selhalo.
  --
  -- ⚠️ VÝHRADNĚ NA VYŽÁDÁNÍ (`p_params.want_target`). Ajv je all-or-nothing:
  --    jedno neznámé pole zneplatní CELÝ blok a na obrazovce je „data se
  --    nepodařilo načíst". Povrchy se nasazují jinou kadencí než jádro, takže
  --    starý klient nepožádá a dostane bajtově tutéž obálku jako dosud —
  --    přesně týž postup jako u scope polí výš.
  if coalesce((p_params->>'want_target')::boolean, false) then
    select jsonb_build_object('entity_kind', r.entity_kind,
                              'entity_id',   r.entity_id::text,
                              'label',       r.label)
      into v_target
      from unnest(regexp_split_to_array(v_q, '[^[:alnum:]/_-]+')) tok
      cross join lateral public.resolve_entity_reference(tok) r
     -- Krátké tokeny se nezkoušejí: „a", „to", „DL" by trefily leda náhodou
     -- a náhodná shoda je horší než žádná — poslala by člověka na cizí doklad.
     where length(tok) >= 4
     limit 1;
  end if;

  return jsonb_build_object(
    'data', jsonb_build_object(
      'columns', v_cols,
      'rows', jsonb_build_array(jsonb_build_object(
        'odpoved', v_a->>'answer',
        'pokryti', v_a->>'coverage',
        'zdroj',   coalesce(v_a->>'source', '')))),
    'provenance', v_prov)
    || case when v_target is not null
            then jsonb_build_object('target', v_target)
            else '{}'::jsonb end;
end;
$$;

comment on function public.get_answer_block(jsonb) is
  'Ask block: scope vector is the authoritative input (p_params.scope), resolved by scope_effective, the run is recorded in ai_runs/ai_trace_events with its story binding, and provenance returns scope_requested/scope_effective/run_id — but only to a caller that asked under a scope, so older bundles keep the byte-identical envelope.';

REVOKE ALL ON FUNCTION public.get_answer_block(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_answer_block(jsonb) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/submit_meter_reading_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: submit_meter_reading_audited
-- Popis: Terénní odečet měřidla — hodnota POTVRZENÁ tím, kdo ji pořizuje,
--        zapsaná jako pozorování k twinu MĚŘIDLA + dokončení milníku úkolu.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- ============================================================================
--
-- ⭐ HODNOTA JDE S POTVRZENÍM, NE PO NĚM (zadání majitele 2026-08-05).
-- Appka na místě z fotky hodnotu VYČTE, ukáže ji člověku a ten ji potvrdí nebo
-- opraví. Odesílá se tedy HODNOTA, ne úkol vyčíst ji později. Stroj pomáhá,
-- ale **validace zůstává na tom, kdo pořizuje**: `p_value` je povinné a není tu
-- žádná větev „hodnota bude doplněna dodatečně“.
--
-- ⚠️ PŘEPSÁNO 2026-08-05 — předchozí verze (regenerát z 07-25) dělala PRAVÝ OPAK
-- a je poučné, v čem:
--   · zapisovala `attrs.verification = 'pending'`, tedy hodnotu jako NÁVRH
--     čekající na ratifikaci. Tím se potvrzení pořizovatele měnilo v doporučení
--     a odečet ve dvoukolové schvalování tam, kde stačí jeden člověk u měřidla;
--   · věšela událost na OBJEKT (lokalitu) nebo nájemce a měřidlo nesla jen jako
--     `attrs.meter_ref` — tedy text. Historie konkrétního měřidla se z toho
--     číst nedala, přestože měřidla jsou twins (`entity_type='meter'`, 63 v
--     produkci);
--   · identifikovala přes `label` (`WHERE label = p_object_label LIMIT 1`), což
--     je vyhledávání podle jména, ne podle identity;
--   · autorizovala `is_service_role() OR is_admin_or_staff() OR v_uid IS NOT NULL`
--     — poslední člen znamená „kdokoli přihlášený“, takže to nebyla kontrola.
-- Nikdo ji nevolal (jen generované typy), takže se přepisuje, ne obchází.
--
-- ⭐ MĚŘIDLO NENÍ ZVLÁŠTNÍ DRUH DAT, jen zvláštní ZPŮSOB VSTUPU.
-- Hodnota z HomeAssistantu, z T-CARS, od našeho člověka s appkou i od nájemníka
-- s fotkou — všechno je totéž pozorování k téže entitě. Liší se `source` (kanál)
-- a kdo za údaj ručí. Proto `twin_events` vedle telemetrie a NE vlastní tabulka:
-- nové silo = druhá pravda o téže veličině a graf „stav v čase“ ze dvou míst.
--
-- FOTO JE VOLITELNÉ. Doklad je užitečný (dá se zpětně ověřit, jestli se
-- odečítač nespletl), ale odečet na něm nestojí — hodnotu potvrdil člověk.
-- Když foto je, nese se jako REFERENCE na objekt v MinIO (nahraný přes
-- create_entity_evidence_preflight_audited), nikdy jako obsah.
--
-- ⚠️ NÁROK PLYNE Z PRÁCE, ne z role. `twin_record_events_audited` vyžaduje
-- admin/staff/service (je to dávkový zapisovatel pro adaptéry), takže odečítač
-- v terénu do něj nedosáhne. Tady autorizuje TÝŽ predikát jako dokončení
-- milníku: kdo má na to měřidlo otevřený úkol, ten smí zapsat odečet.
-- Oprávnění vzniká i zaniká s úkolem, bez zvláštní role a bez správy seznamu.

CREATE OR REPLACE FUNCTION public.submit_meter_reading_audited(
  p_step_id     uuid,
  p_value       numeric,
  p_note        text        DEFAULT NULL,
  p_occurred_at timestamptz DEFAULT NULL,
  p_photo_key   text        DEFAULT NULL,
  -- Co appka vyčetla, NEŽ to člověk potvrdil. Drží se jen jako stopa kvality
  -- čtečky (jak často se strojní návrh liší od potvrzené hodnoty); autoritou
  -- je vždy `p_value`.
  p_suggested   numeric     DEFAULT NULL,
  p_unit        text        DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid      uuid := auth.uid();
  v_twin_id  uuid;
  v_batch_id uuid;
  v_story_id uuid;
  v_at       timestamptz := coalesce(p_occurred_at, now());
  v_event_id uuid;
  v_step     jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  -- Odečet bez čísla není odečet, je to jen návštěva.
  IF p_value IS NULL THEN
    RAISE EXCEPTION 'reading value is required — a confirmed reading is the point'
      USING ERRCODE = '22023';
  END IF;

  -- Nárok z práce (viz hlavička) — týž sdílený predikát jako dokončení milníku.
  SELECT s.batch_id, (s.input_data->>'subject_twin_id')::uuid
    INTO v_batch_id, v_twin_id
    FROM public.production_workflow_steps s
   WHERE s.id = p_step_id
     AND public.workflow_step_visible_to(v_uid, s.assigned_user_id, s.assigned_role, s.input_data);

  IF v_batch_id IS NULL THEN
    -- Nerozlišuje se „neexistuje“ od „nesmíš“, jinak by šel krok vyzkoušet.
    RAISE EXCEPTION 'workflow step not found or not visible' USING ERRCODE = '42501';
  END IF;

  IF v_twin_id IS NULL THEN
    RAISE EXCEPTION 'step % has no subject_twin_id — a reading needs the meter it belongs to', p_step_id
      USING ERRCODE = '22023';
  END IF;

  SELECT b.story_id INTO v_story_id FROM public.production_batches b WHERE b.id = v_batch_id;

  -- ── Pozorování k twinu MĚŘIDLA ────────────────────────────────────────────
  -- `source_ref` = krok, takže opakované odeslání téhož odečtu (retry z offline
  -- fronty na mizerné síti) hodnotu AKTUALIZUJE místo aby vyrobilo druhý údaj
  -- o témže odečtu. Idempotence stojí na kroku, nikdy na čase.
  --
  -- ⚠️ `ON CONFLICT` opakuje i predikát: uq_twin_events_source_ref je PARTIÁLNÍ
  -- index (`WHERE source_ref IS NOT NULL`) a bez shodné podmínky by Postgres
  -- arbitr nenašel a příkaz spadl až za běhu (42P10).
  INSERT INTO public.twin_events
    (event_type, twin_id, story_id, occurred_at, attrs, source, source_ref)
  VALUES ('meter_reading', v_twin_id, v_story_id, v_at,
          jsonb_strip_nulls(jsonb_build_object(
            'value',        p_value,
            'unit',         p_unit,
            -- Kdo za údaj RUČÍ. U IoT by tu byl adaptér, tady člověk — a to je
            -- celý rozdíl mezi kanály, ne jiný datový tvar.
            'confirmed_by', v_uid::text,
            'suggested',    p_suggested,
            'photo_key',    p_photo_key,
            'note',         p_note,
            'step_id',      p_step_id::text)),
          'field-reading', p_step_id::text)
  ON CONFLICT (source, event_type, source_ref) WHERE source_ref IS NOT NULL DO UPDATE
    SET attrs = excluded.attrs, occurred_at = excluded.occurred_at
  RETURNING public.twin_events.id INTO v_event_id;

  -- ── Milník ────────────────────────────────────────────────────────────────
  -- Dokončení je součástí TÉHOŽ úkonu: člověk u měřidla potvrdil hodnotu, tím
  -- je odečet hotový. Nechat krok otevřený by znamenalo, že se čeká na někoho
  -- dalšího — a na nikoho dalšího se nečeká.
  v_step := public.complete_workflow_step(
    p_step_id     => p_step_id,
    p_output_data => jsonb_strip_nulls(jsonb_build_object(
                       'value', p_value, 'unit', p_unit,
                       'via', 'field_reading', 'event_id', v_event_id::text)),
    p_notes       => p_note,
    p_occurred_at => v_at);

  IF NOT coalesce((v_step->>'ok')::boolean, false) THEN
    RAISE EXCEPTION 'milestone not completed: %', coalesce(v_step->>'error', 'unknown')
      USING ERRCODE = '42501';
  END IF;

  -- Audit nese FAKT a hodnotu, nikdy obrázek (ten žije v MinIO pod klíčem).
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_uid, 'METER_READING_SUBMITTED',
          jsonb_build_object('twin_id', v_twin_id, 'value', p_value, 'unit', p_unit,
                             'step_id', p_step_id, 'has_photo', p_photo_key IS NOT NULL,
                             'suggested_differs', p_suggested IS NOT NULL AND p_suggested <> p_value));

  RETURN jsonb_build_object('ok', true, 'event_id', v_event_id, 'value', p_value, 'step', v_step);
END;
$function$;

REVOKE ALL ON FUNCTION public.submit_meter_reading_audited(uuid,numeric,text,timestamptz,text,numeric,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.submit_meter_reading_audited(uuid,numeric,text,timestamptz,text,numeric,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.submit_meter_reading_audited(uuid,numeric,text,timestamptz,text,numeric,text) TO service_role;

-- ⚠️ Starý TEXTOVÝ podpis musí zmizet, jinak by vedle nové funkce žil dál a
-- volání by mohlo trefit tu starou (zapisuje `verification:'pending'` na objekt
-- místo potvrzené hodnoty na měřidlo). DROP ale NEPATŘÍ SEM, nýbrž do heals.sql
-- — viz tamní blok. Důvod je provozní: SoT soubor se přehrává při KAŽDÉM
-- migrate, takže DROP v něm by se pokoušel padnout pokaždé, a na běžící DB na
-- funkci můžou viset policies/views („cannot drop function … because other
-- objects depend on it" — u is_admin_or_staff to bylo 253 policies).
-- Hlídá to brána rls-predikat-a-indexy.


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/workflow_step_derived_position.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: workflow_step_derived_position
-- Popis: Kde se milník odehrál — ODVOZENO, nikdy z klienta.
--
--   Poloha je u předání důkaz, a důkaz nesmí dodávat ten, koho dokumentuje.
--   Geolokace z prohlížeče navíc hlásí telefon řidiče, ne vozidlo: je
--   podvržitelná, potřebuje souhlas s oprávněním a duplikuje signál, který už
--   vlastníme s lepší provenancí (identita z tachografu).
--
--   Dvě cesty, v tomhle pořadí:
--     1. PŘÍJEZDOVÝ SIGNÁL — uzel téhož běhu, který se dokončuje signálem
--        (`input_data ? 'complete_on'`), nese v `output_data->'payload'` to, co
--        adaptér poslal. Když v něm je poloha, je to přesně poloha předání.
--     2. TELEMATIKA — když signál polohu nenese, ale jmenuje vozidlo, vezme se
--        poslední známá poloha toho vozidla do času milníku.
--
--   Když neodpoví ani jedna, vrátí `geo_source='unavailable'` s důvodem. Prázdno
--   je signál k dotažení lane, ne důvod psát nulové souřadnice.
--
--   ⚠️ Shoda vozidla je VÝHRADNĚ rovnost na `wd_vehicles.identifier`. Volnější
--   párování (description, normalizace SPZ) by tu vyrobilo falešnou shodu, a
--   falešná shoda je u důkazu horší než mezera.
--
--   `position_time` se vrací vždy, když se poloha našla — čtenář musí vidět,
--   jak stará je. Skrytý práh „čerstvosti" by tichounce zahodil pravdivý údaj.
--
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT. Čte jen wd_* a běh, nic nezapisuje.
--   ⚠️ AUTORIZUJE SAMA SEBE, a musí. První verze spoléhala na to, že ji volá
--   výhradně submit_evidence_review_audited po kontrole milníku — jenže
--   `security definer` obchází RLS, takže grant pro `authenticated` z ní dělal
--   ORÁKULUM POLOHY: kdokoli přihlášený by dosazoval cizí step_id a dostával
--   souřadnice cizích vozidel. Chytila to brána security.gate (SEC_DEF_NO_AUTH),
--   ne já.
--   Dvojí obrana: grant má jen service_role (definer volající projdou i tak),
--   a tělo navíc ptá TÝŽ sdílený predikát jako fronta — workflow_step_visible_to
--   (přiřazení · role · potvrzená twin vazba). Kdo krok nesmí vidět, nesmí znát
--   ani místo, kde se odehrál.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.workflow_step_derived_position(p_step_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_step     public.production_workflow_steps%rowtype;
  v_uid      uuid := auth.uid();
  v_batch    uuid;
  v_at       timestamptz;
  v_payload  jsonb;
  v_lat      numeric;
  v_lon      numeric;
  v_vehicle  text;
  v_car      integer;
  v_pos      record;
BEGIN
  SELECT * INTO v_step
    FROM public.production_workflow_steps s
   WHERE s.id = p_step_id;

  -- Neexistující krok vypadá stejně jako krok, na který volající nemá nárok —
  -- záměrně. Rozlišit je by z odpovědi udělalo test existence cizích běhů.
  IF NOT FOUND THEN
    RETURN jsonb_build_object('geo_source', 'unavailable', 'reason', 'step_not_found');
  END IF;

  IF NOT (public.is_service_role()
          OR public.is_admin_or_staff()
          OR public.workflow_step_visible_to(
               v_uid, v_step.assigned_user_id, v_step.assigned_role, v_step.input_data,
               NULL, v_step.step_code)) THEN
    RETURN jsonb_build_object('geo_source', 'unavailable', 'reason', 'step_not_found');
  END IF;

  v_batch := v_step.batch_id;
  v_at    := coalesce(v_step.completed_at, now());

  -- Poslední signálem dokončený uzel téhož běhu = příjezd na místo.
  SELECT s.output_data->'payload'
    INTO v_payload
    FROM public.production_workflow_steps s
   WHERE s.batch_id = v_batch
     AND s.input_data ? 'complete_on'
     AND s.output_data ? 'payload'
   ORDER BY s.step_order DESC
   LIMIT 1;

  IF v_payload IS NULL THEN
    RETURN jsonb_build_object('geo_source', 'unavailable', 'reason', 'no_arrival_signal');
  END IF;

  v_lat := nullif(v_payload->>'lat', '')::numeric;
  v_lon := nullif(v_payload->>'lon', '')::numeric;

  IF v_lat IS NOT NULL AND v_lon IS NOT NULL THEN
    RETURN jsonb_strip_nulls(jsonb_build_object(
      'geo_source', 'arrival_signal',
      'lat', v_lat, 'lon', v_lon,
      'place', v_payload->>'place'));
  END IF;

  v_vehicle := nullif(btrim(coalesce(v_payload->>'vehicle', '')), '');
  IF v_vehicle IS NULL THEN
    RETURN jsonb_strip_nulls(jsonb_build_object(
      'geo_source', 'unavailable', 'reason', 'signal_without_position_or_vehicle',
      'place', v_payload->>'place'));
  END IF;

  SELECT v.wd_car_id INTO v_car
    FROM public.wd_vehicles v
   WHERE v.identifier = v_vehicle
   LIMIT 1;

  IF v_car IS NULL THEN
    RETURN jsonb_strip_nulls(jsonb_build_object(
      'geo_source', 'unavailable', 'reason', 'vehicle_not_in_telematics',
      'vehicle', v_vehicle, 'place', v_payload->>'place'));
  END IF;

  SELECT h.latitude, h.longitude, h.position_time, h.location_text
    INTO v_pos
    FROM public.wd_vehicle_positions_history h
   WHERE h.wd_car_id = v_car
     AND h.position_time <= v_at
     AND h.latitude IS NOT NULL
     AND h.longitude IS NOT NULL
   ORDER BY h.position_time DESC
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_strip_nulls(jsonb_build_object(
      'geo_source', 'unavailable', 'reason', 'no_position_before_milestone',
      'vehicle', v_vehicle, 'place', v_payload->>'place'));
  END IF;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'geo_source', 'telematics',
    'lat', v_pos.latitude, 'lon', v_pos.longitude,
    'position_time', v_pos.position_time,
    'place', coalesce(v_pos.location_text, v_payload->>'place'),
    'vehicle', v_vehicle));
END;
$$;

-- Žádný grant pro `authenticated`: tohle není blokové RPC, klient ho nevolá.
-- Jediná cesta k němu vede přes submit_evidence_review_audited, který je
-- SECURITY DEFINER, takže grant nepotřebuje.
REVOKE ALL ON FUNCTION public.workflow_step_derived_position(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.workflow_step_derived_position(uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/write_audit_journal.sql
-- -----------------------------------------------------------------------------

-- Function: public.write_audit_journal
-- Arguments: p_action_type journal_action_type, p_area journal_area, p_details jsonb, p_entity_id text, p_entity_type text, p_new_values jsonb, p_old_values jsonb, p_severity journal_severity, p_summary text, p_tags text[], p_user_id uuid
-- Description: Unified audit journal writer with alphabetically ordered parameters.
--   blockchain_hash (v2): deterministic SHA-256 over the STORED row columns only
--   (action, entity_type, entity_id, created_at epoch, new_data, metadata minus the hash
--   itself) — no now()::text salt, no unstored inputs — so fn_verify_audit_journal_entry
--   can recompute and verify it. Written to the blockchain_hash COLUMN (what
--   get_audit_journal returns) and mirrored into metadata for backward compatibility.
--   user_id is deliberately excluded (FK ON DELETE SET NULL mutates it on user erasure).
-- Security: SECURITY DEFINER with search_path set. PRIVILEGED PRIMITIVE — the caller chooses the
--   actor via p_user_id, so the caller must already be trusted. Reachable only by service_role and
--   by the ~358 in-DB SECURITY DEFINER callers (which run as the OWNER and therefore need no
--   grant). NOT callable with a user JWT — browsers use write_my_audit_journal_entry, which has no
--   p_user_id and pins the actor to auth.uid().
--   2026-07-15 IDOR fix (docs/security/IDOR_P_USER_ID_AUDIT_2026-07-15.md): the `authenticated`
--   grant let ANY logged-in user author an audit entry attributed to someone else — evidence
--   fabrication in the tamper-evident ledger, and the forged row received a VALID blockchain_hash,
--   so fn_verify_audit_chain attested it as authentic (the hash proves the row was not altered
--   after insertion; it says nothing about who authored it). A guard cannot fix this: the in-DB
--   callers legitimately pass a p_user_id that is not auth.uid() (system entries pass NULL), and a
--   JWT-reading guard cannot tell them apart from a direct PostgREST call, since SECURITY DEFINER
--   swaps current_user but not the JWT claims. Restricting the CALLER is the fix.
--   n8n (AishaAudit, AishaNodeFactory) authenticates with serviceRoleKey and is unaffected.
-- Updated: 2026-07-15 (revoked from `authenticated`; was audit-attribution forgery)
-- Updated: 2026-07-03 (deterministic v2 hash; was salted with session-local now()::text)

CREATE OR REPLACE FUNCTION public.write_audit_journal(
  p_action_type journal_action_type,
  p_area journal_area DEFAULT 'system'::journal_area,
  p_details jsonb DEFAULT NULL,
  p_entity_id text DEFAULT NULL,
  p_entity_type text DEFAULT 'unknown',
  p_new_values jsonb DEFAULT NULL,
  p_old_values jsonb DEFAULT NULL,
  p_severity journal_severity DEFAULT 'info'::journal_severity,
  p_summary text DEFAULT '',
  p_tags text[] DEFAULT '{}',
  p_user_id uuid DEFAULT NULL  -- callers should pass auth.uid() explicitly via named arg or rely on COALESCE in body
  )
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_journal_id uuid;
  v_user_role text;
  v_actual_user_id uuid;
  v_now timestamptz;
  v_new_data jsonb;
  v_metadata jsonb;
  v_hash text;
BEGIN
  v_actual_user_id := COALESCE(p_user_id, auth.uid());

  -- Defensive actor resolution: audit_journal.user_id FKs aisha_auth.users
  -- (ON DELETE SET NULL). An authenticated-but-not-yet-provisioned caller
  -- (see public.ensure_current_user) yields a uid absent from aisha_auth.users
  -- — inserting it raises FK 23503 and ROLLS BACK the very operation being
  -- audited. Audit must never block a real operation, and a dangling actor
  -- reference is meaningless: coalesce the unknown actor to NULL (system).
  IF v_actual_user_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM aisha_auth.users u WHERE u.id = v_actual_user_id)
  THEN
    v_actual_user_id := NULL;
  END IF;

  IF v_actual_user_id IS NOT NULL THEN
    SELECT ur.role::text INTO v_user_role
    FROM public.user_roles ur
    WHERE ur.user_id = v_actual_user_id
    LIMIT 1;
  END IF;
  
  v_now := now();
  v_new_data := COALESCE(p_details, p_new_values);
  v_metadata := jsonb_build_object(
    'area', p_area::text,
    'severity', p_severity::text,
    'summary', p_summary,
    'user_role', v_user_role,
    'tags', p_tags
  );

  -- Deterministic v2 hash — every input is a stored column of the row being
  -- inserted (created_at as timezone-independent epoch microseconds; jsonb::text
  -- is canonical), so fn_verify_audit_journal_entry can recompute + verify it.
  v_hash := 'v2:' || encode(digest(convert_to(jsonb_build_object(
    'schema', 'aisha.audit_journal.hash.v2',
    'action', p_action_type::text,
    'entity_type', p_entity_type,
    'entity_id', p_entity_id,
    'created_at_epoch_us', (extract(epoch FROM v_now) * 1000000)::bigint,
    'new_data', v_new_data,
    'metadata', v_metadata
  )::text, 'UTF8'), 'sha256'), 'hex');

  INSERT INTO public.audit_journal (
    user_id,
    action,
    entity_type,
    entity_id,
    metadata,
    new_data,
    blockchain_hash,
    created_at
  ) VALUES (
    v_actual_user_id,
    p_action_type::text,
    p_entity_type,
    p_entity_id,
    v_metadata || jsonb_build_object('blockchain_hash', v_hash),
    v_new_data,
    v_hash,
    v_now
  )
  RETURNING id INTO v_journal_id;
  
  RETURN v_journal_id;
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.write_audit_journal(
  p_action_type journal_action_type,
  p_area journal_area,
  p_details jsonb,
  p_entity_id text,
  p_entity_type text,
  p_new_values jsonb,
  p_old_values jsonb,
  p_severity journal_severity,
  p_summary text,
  p_tags text[],
  p_user_id uuid
  ) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION public.write_audit_journal(
  p_action_type journal_action_type,
  p_area journal_area,
  p_details jsonb,
  p_entity_id text,
  p_entity_type text,
  p_new_values jsonb,
  p_old_values jsonb,
  p_severity journal_severity,
  p_summary text,
  p_tags text[],
  p_user_id uuid
  ) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/acknowledge_production_sensor_alert_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.acknowledge_production_sensor_alert_admin
-- Arguments: p_alert_id uuid, p_resolution_notes text
-- Description: Acknowledge (and optionally resolve) a production sensor alert.
-- Security: SECURITY DEFINER, admin/staff only
-- Source: Migration 20260219180000_production_enhancements.sql

CREATE OR REPLACE FUNCTION public.acknowledge_production_sensor_alert_admin(
  p_alert_id uuid DEFAULT NULL,
  p_resolution_notes text DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_admin_or_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or staff role required';
  END IF;

  UPDATE production_sensor_alerts
  SET
    acknowledged_by = auth.uid(),
    acknowledged_at = now(),
    resolved_by = CASE WHEN p_resolution_notes IS NOT NULL THEN auth.uid() ELSE resolved_by END,
    resolved_at = CASE WHEN p_resolution_notes IS NOT NULL THEN now() ELSE resolved_at END,
    resolution_notes = COALESCE(p_resolution_notes, resolution_notes)
  WHERE id = p_alert_id;

  PERFORM public.write_audit_journal(
    p_action_type := 'update'::public.journal_action_type,
    p_area := 'production'::public.journal_area,
    p_details := NULL,
    p_entity_id := p_alert_id::text,
    p_entity_type := 'production_sensor_alert',
    p_new_values := jsonb_build_object('acknowledged', true),
    p_old_values := NULL,
    p_severity := 'info'::public.journal_severity,
    p_summary := 'Sensor alert acknowledged',
    p_tags := ARRAY['admin', 'sensor', 'alert_ack'],
    p_user_id := auth.uid()
  );

  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION public.acknowledge_production_sensor_alert_admin(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.acknowledge_production_sensor_alert_admin(uuid, text) TO authenticated;


