GRANT EXECUTE ON FUNCTION public.archive_chat_conversation_audited(p_conversation_id uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/archive_label_template_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.archive_label_template_admin
-- Arguments: p_template_id uuid, p_archived_by text
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:25:52+01:00

CREATE OR REPLACE FUNCTION public.archive_label_template_admin(p_template_id uuid, p_archived_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_template RECORD;
BEGIN
  -- Check if user is admin or staff
  IF NOT is_admin_or_staff(auth.uid()) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin access required');
  END IF;

  -- Get template
  SELECT * INTO v_template
  FROM product_label_templates
  WHERE id = p_template_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Template not found');
  END IF;

  -- Create archive entry
  INSERT INTO product_label_archive (
    product_id,
    template_id,
    version,
    version_date,
    label_data,
    pdf_url,
    archived_by,
    archive_reason
  ) VALUES (
    v_template.product_id,
    v_template.id,
    v_template.version,
    v_template.version_date,
    to_jsonb(v_template),
    v_template.label_pdf_url,
    COALESCE(p_archived_by, auth.uid()::TEXT),
    'Manual archive'
  );

  -- Update template status
  UPDATE product_label_templates
  SET status = 'archived', updated_at = now()
  WHERE id = p_template_id;

  PERFORM public.write_audit_journal(
      p_action_type := 'update'::public.journal_action_type,
      p_area := 'products'::public.journal_area,
      p_details := NULL,
      p_entity_id := p_template_id::text,
      p_entity_type := 'label_template',
      p_new_values := jsonb_build_object('id', p_template_id),
      p_old_values := NULL,
      p_severity := 'notice'::public.journal_severity,
      p_summary := 'Admin archived label template',
      p_tags := ARRAY['admin', 'label_template', 'archive'],
      p_user_id := auth.uid()
  );

  RETURN jsonb_build_object('success', true);
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.archive_label_template_admin(p_template_id uuid, p_archived_by text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.archive_label_template_admin(p_template_id uuid, p_archived_by text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/award_tokens_admin_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.award_tokens_admin_audited
-- Arguments: p_amount integer, p_description text, p_reference_id uuid, p_reference_type text, p_token_type text, p_user_id uuid
-- Description: Admin path for granting tokens. Companion to award_tokens, which became
--   service_role-only in the 2026-07-15 IDOR fix (docs/security/IDOR_P_USER_ID_AUDIT_2026-07-15.md).
--
--   WHY A WRAPPER INSTEAD OF GRANTING award_tokens: the admin UI (src/hooks/useTokens.ts) calls
--   the RPC with a user JWT (role=authenticated). Its only protection used to be
--   useAdminGuard.guardAdminMutation — CLIENT-side React, which enforces nothing in the database,
--   so any logged-in user could POST /rest/v1/rpc/award_tokens directly and mint themselves
--   unlimited governance tokens. Here the admin check is enforced IN THE DATABASE: the grant lets
--   an admin's JWT reach the function, is_admin_or_staff() decides whether it proceeds.
--
-- Security: SECURITY DEFINER; is_admin_or_staff() fail-closed as the FIRST statement. That guard is
--   the ONLY authorization on this path — award_tokens itself performs none (its GRANT is its
--   boundary), and we reach it only because SECURITY DEFINER runs us as the owner, who holds
--   EXECUTE by ownership. Do not remove the guard without replacing it.
-- Params: alphabetical (generated TS types are ordered alphabetically — see
--   src/tests/db/rpc-params-alphabetical.test.ts). PostgreSQL requires defaults to trail, so the
--   required p_token_type/p_user_id carry defaults and are NULL-checked in the body instead.
-- @audit: token.admin_awarded — an admin touching someone else's ledger MUST leave a trace; the
--   token_transactions row alone is not one, since the admin authored it.

CREATE OR REPLACE FUNCTION public.award_tokens_admin_audited(
  p_amount         integer,
  p_description    text DEFAULT NULL::text,
  p_reference_id   uuid DEFAULT NULL::uuid,
  p_reference_type text DEFAULT NULL::text,
  p_token_type     text DEFAULT NULL::text,
  p_user_id        uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  -- AUTHORIZATION FIRST — before the audit row and before any ledger touch.
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin or staff required' USING ERRCODE = '42501';
  END IF;

  -- Required despite carrying defaults (see Params note above) — fail loud, do not coalesce.
  IF p_user_id IS NULL OR p_token_type IS NULL THEN
    RAISE EXCEPTION 'p_user_id and p_token_type are required' USING ERRCODE = '22023';
  END IF;

  -- award_tokens validates the amount and token type and does the minting.
  v_result := public.award_tokens(
    p_user_id, p_token_type, p_amount, p_reference_type, p_reference_id, p_description
  );

  PERFORM public.write_audit_journal(
    p_action_type := 'update'::journal_action_type,
    p_area        := 'tokens'::journal_area,
    p_details     := jsonb_build_object(
      'target_user_id', p_user_id,
      'token_type', p_token_type,
      'amount', p_amount,
      'reference_type', p_reference_type,
      'reference_id', p_reference_id,
      'description', p_description
    ),
    p_entity_id   := p_user_id::text,
    p_entity_type := 'token_transaction',
    p_severity    := 'warning'::journal_severity,
    p_summary     := format('Admin awarded %s %s tokens', p_amount, p_token_type),
    p_tags        := ARRAY['tokens', 'admin', 'ledger'],
    p_user_id     := auth.uid()
  );

  RETURN v_result;
END;
$function$
;

-- Permissions
-- The GRANT lets an admin's browser JWT reach the function; is_admin_or_staff() above decides
-- whether it proceeds. A non-admin authenticated caller gets 42501.
REVOKE ALL ON FUNCTION public.award_tokens_admin_audited(p_amount integer, p_description text, p_reference_id uuid, p_reference_type text, p_token_type text, p_user_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.award_tokens_admin_audited(p_amount integer, p_description text, p_reference_id uuid, p_reference_type text, p_token_type text, p_user_id uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.award_tokens_admin_audited(p_amount integer, p_description text, p_reference_id uuid, p_reference_type text, p_token_type text, p_user_id uuid) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/bootstrap_default_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.bootstrap_default_admin
-- Arguments: (none)
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:25:54+01:00

CREATE OR REPLACE FUNCTION public.bootstrap_default_admin()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_admin_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_admin_count FROM public.user_roles WHERE role = 'admin';

  PERFORM public.write_audit_journal(
      p_action_type := 'view'::public.journal_action_type,
      p_area := 'admin'::public.journal_area,
      p_details := NULL,
      p_entity_id := NULL,
      p_entity_type := 'system_config',
      p_new_values := jsonb_build_object('admin_count', v_admin_count),
      p_old_values := NULL,
      p_severity := 'info'::public.journal_severity,
      p_summary := 'User checked default admin status',
      p_tags := ARRAY['system', 'bootstrap'],
      p_user_id := auth.uid()
  );

  IF v_admin_count > 0 THEN
    RETURN jsonb_build_object('success', true, 'message', 'Admin user already exists', 'admin_count', v_admin_count);
  END IF;

  RETURN jsonb_build_object('success', false, 'message', 'No admin user exists. Please create one manually.', 'admin_count', 0);
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.bootstrap_default_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.bootstrap_default_admin() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/cast_governance_vote.sql
-- -----------------------------------------------------------------------------

-- Function: public.cast_governance_vote
-- Custodial cast-vote RPC (LOCKED DECISION D3): records a member's ballot into the
-- LOCAL governance_votes ledger, derives vote WEIGHT server-side from the member's
-- governance token holdings (memberships.tokens_governance — never a client value),
-- recomputes the proposal tally, and BINDS the ballot to the immutable hash chain
-- by inserting a blockchain_audit_records row keyed on
-- reference_table='governance_votes'. One ballot per member per proposal
-- (re-voting updates the same ballot).
-- Security: SECURITY DEFINER, search_path pinned, authenticated members only.

CREATE OR REPLACE FUNCTION public.cast_governance_vote(
  p_proposal_id uuid,
  p_choice text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_proposal public.governance_proposals%ROWTYPE;
  v_weight numeric;
  v_vote_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_choice NOT IN ('for', 'against', 'abstain') THEN
    RAISE EXCEPTION 'Invalid choice "%": allowed = for|against|abstain', p_choice
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_proposal
  FROM public.governance_proposals
  WHERE id = p_proposal_id
  FOR UPDATE;

  IF v_proposal.id IS NULL THEN
    RAISE EXCEPTION 'Unknown proposal %', p_proposal_id USING ERRCODE = 'no_data_found';
  END IF;

  IF v_proposal.status <> 'open' THEN
    RAISE EXCEPTION 'Proposal % is not open for voting (status=%)', p_proposal_id, v_proposal.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_proposal.closes_at IS NOT NULL AND v_proposal.closes_at < now() THEN
    RAISE EXCEPTION 'Voting has closed for proposal %', p_proposal_id
      USING ERRCODE = 'check_violation';
  END IF;

  -- Vote weight DERIVES from governance token holdings (not a client-supplied
  -- number). memberships has UNIQUE(user_id).
  SELECT COALESCE(tokens_governance, 0) INTO v_weight
  FROM public.memberships
  WHERE user_id = v_user_id;
  v_weight := COALESCE(v_weight, 0);

  IF v_weight <= 0 THEN
    RAISE EXCEPTION 'No governance token holdings — cannot vote'
      USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.governance_votes (proposal_id, user_id, choice, weight)
  VALUES (p_proposal_id, v_user_id, p_choice, v_weight)
  ON CONFLICT (proposal_id, user_id) DO UPDATE
    SET choice = EXCLUDED.choice,
        weight = EXCLUDED.weight,
        created_at = now()
  RETURNING id INTO v_vote_id;

  -- Recompute the running tally from the ballots (quorum evaluated by callers).
  UPDATE public.governance_proposals p
     SET tally = (
       SELECT jsonb_build_object(
         'for',     COALESCE(SUM(v.weight) FILTER (WHERE v.choice = 'for'), 0),
         'against', COALESCE(SUM(v.weight) FILTER (WHERE v.choice = 'against'), 0),
         'abstain', COALESCE(SUM(v.weight) FILTER (WHERE v.choice = 'abstain'), 0),
         'voter_count', COUNT(*)
       )
       FROM public.governance_votes v
       WHERE v.proposal_id = p_proposal_id
     ),
     updated_at = now()
   WHERE p.id = p_proposal_id;

  -- Anchor the ballot into the immutable hash chain (D3: each ballot writes a
  -- blockchain_audit_records row keyed on governance_votes). Idempotent per ballot.
  INSERT INTO public.blockchain_audit_records (
    record_type, data, status, reference_table, reference_id
  ) VALUES (
    'governance_vote',
    jsonb_build_object(
      'proposal_id', p_proposal_id,
      'user_id', v_user_id,
      'choice', p_choice,
      'weight', v_weight
    ),
    'queued',
    'governance_votes',
    v_vote_id
  )
  ON CONFLICT (reference_table, reference_id) WHERE reference_id IS NOT NULL
  DO NOTHING;

  PERFORM public.write_audit_journal(
    p_action_type := 'create'::journal_action_type,
    p_area := 'blockchain'::journal_area,
    p_details := jsonb_build_object('proposal_id', p_proposal_id, 'choice', p_choice, 'weight', v_weight),
    p_entity_id := v_vote_id::text,
    p_entity_type := 'governance_vote',
    p_severity := 'info'::journal_severity,
    p_summary := 'Governance ballot cast',
    p_user_id := v_user_id
  );

  RETURN jsonb_build_object(
    'vote_id', v_vote_id,
    'proposal_id', p_proposal_id,
    'choice', p_choice,
    'weight', v_weight
  );
END;
$function$;

COMMENT ON FUNCTION public.cast_governance_vote(uuid, text) IS
  'D3 custodial cast-vote: local governance_votes ballot + token-derived weight + '
  'tally recompute + blockchain_audit_records anchor (reference_table=governance_votes).';

REVOKE ALL ON FUNCTION public.cast_governance_vote(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.cast_governance_vote(uuid, text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/claim_cosmos_reward.sql
-- -----------------------------------------------------------------------------

-- Function: claim_cosmos_reward
-- User RPC: claims on-chain token reward by deducting balance and creating outbox record.
-- Flow: deduct memberships balance → token_transaction INSERT → fn_queue_blockchain_sync trigger → outbox
-- Only governance (ugov) and aisha (uash) tokens are eligible for on-chain claims (GDPR filter in trigger).
-- Requires cosmos_address set on profile (via update_my_cosmos_address).

CREATE OR REPLACE FUNCTION public.claim_cosmos_reward(
  p_amount bigint,
  p_denom text DEFAULT 'uash'
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_cosmos_address text;
  v_token_type text;
  v_membership_id uuid;
  v_current_balance integer;
  v_new_balance integer;
  v_claim_id uuid;
  v_transaction_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  -- Validate amount
  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'Amount must be positive'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Map denom to token_type (only on-chain eligible types)
  v_token_type := CASE p_denom
    WHEN 'uash' THEN 'aisha'
    WHEN 'ugov' THEN 'governance'
    ELSE NULL
  END;

  IF v_token_type IS NULL THEN
    RAISE EXCEPTION 'Unsupported denom: %. Use uash or ugov.', p_denom
      USING ERRCODE = 'check_violation';
  END IF;

  -- Check cosmos_address exists on profile
  SELECT cosmos_address INTO v_cosmos_address
  FROM profiles
  WHERE id = v_user_id;

  IF v_cosmos_address IS NULL THEN
    RAISE EXCEPTION 'Cosmos address not set. Register your wallet first.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Get current balance from memberships
  SELECT id,
    CASE v_token_type
      WHEN 'governance' THEN COALESCE(tokens_governance, 0)
      WHEN 'aisha' THEN COALESCE(tokens_aisha, 0)
    END
  INTO v_membership_id, v_current_balance
  FROM memberships
  WHERE user_id = v_user_id
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF v_membership_id IS NULL THEN
    RAISE EXCEPTION 'No membership found'
      USING ERRCODE = 'no_data_found';
  END IF;

  IF v_current_balance < p_amount THEN
    RAISE EXCEPTION 'Insufficient balance'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Deduct balance
  v_new_balance := v_current_balance - p_amount;

  IF v_token_type = 'governance' THEN
    UPDATE memberships SET tokens_governance = v_new_balance WHERE id = v_membership_id;
  ELSIF v_token_type = 'aisha' THEN
    UPDATE memberships SET tokens_aisha = v_new_balance WHERE id = v_membership_id;
  END IF;

  -- Create token_transaction → triggers fn_queue_blockchain_sync → outbox
  INSERT INTO token_transactions (
    user_id,
    token_type,
    transaction_type,
    amount,
    balance_after,
    description
  ) VALUES (
    v_user_id,
    v_token_type,
    'claim',
    -p_amount,
    v_new_balance,
    format('On-chain claim: %s %s', p_amount, p_denom)
  ) RETURNING id INTO v_transaction_id;

  -- Create reward_claims record for tracking, LINKED to the originating
  -- token_transaction (D4: no double-fulfilment — the outbox fulfilment is bound
  -- 1:1 to a single ledger row).
  INSERT INTO reward_claims (user_id, amount, denom, status, transaction_id)
  VALUES (v_user_id, p_amount, p_denom, 'pending', v_transaction_id)
  RETURNING id INTO v_claim_id;

  -- Audit journal (no PII — only IDs)
  PERFORM public.write_audit_journal(
    p_action_type := 'create'::journal_action_type,
    p_area := 'blockchain'::journal_area,
    p_details := jsonb_build_object(
      'amount', p_amount,
      'denom', p_denom
    ),
    p_entity_id := v_claim_id::text,
    p_entity_type := 'reward_claims',
    p_severity := 'info'::journal_severity,
    p_summary := 'Cosmos reward claimed',
    p_user_id := v_user_id
  );

  RETURN v_claim_id;
END;
$function$;

REVOKE ALL ON FUNCTION claim_cosmos_reward(bigint, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION claim_cosmos_reward(bigint, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/claim_invitation.sql
-- -----------------------------------------------------------------------------

-- Function: public.claim_invitation
-- Arguments: p_code text
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:25:58+01:00

CREATE OR REPLACE FUNCTION public.claim_invitation(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invitation RECORD;
  v_user_id UUID := auth.uid();
  v_twin_navrzeno BOOLEAN := false;
  v_adresovana BOOLEAN := false;
  v_result JSONB;
BEGIN
  -- Get the invitation
  SELECT * INTO v_invitation
  FROM invitations
  WHERE code = p_code
    AND is_active = true
    AND (expires_at IS NULL OR expires_at > now())
    AND (max_uses IS NULL OR used_count < max_uses)
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'INVALID_OR_EXPIRED');
  END IF;

  -- Check if already claimed by this user
  IF EXISTS (
    SELECT 1 FROM invitation_claims 
    WHERE invitation_id = v_invitation.id AND user_id = v_user_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'ALREADY_CLAIMED');
  END IF;

  -- Insert claim record
  INSERT INTO invitation_claims (invitation_id, user_id)
  VALUES (v_invitation.id, v_user_id);

  -- Update used_count
  UPDATE invitations
  SET used_count = used_count + 1
  WHERE id = v_invitation.id;

  -- Deactivate if max uses reached
  IF v_invitation.max_uses IS NOT NULL AND v_invitation.used_count + 1 >= v_invitation.max_uses THEN
    UPDATE invitations SET is_active = false WHERE id = v_invitation.id;
  END IF;

  -- Assign role if specified
  IF v_invitation.role IS NOT NULL THEN
    INSERT INTO user_roles (user_id, role)
    VALUES (v_user_id, v_invitation.role::app_role)
    ON CONFLICT (user_id, role) DO NOTHING;
  END IF;

  -- Enroll in study if specified
  IF v_invitation.study_id IS NOT NULL THEN
    INSERT INTO study_registrations (user_id, study_id, status)
    VALUES (v_user_id, v_invitation.study_id, 'enrolled')
    ON CONFLICT (user_id, study_id) DO NOTHING;
  END IF;

  -- ── PROPOJENÍ BUDOUCÍ IDENTITY S ENTITOU (2026-09-10) ─────────────────────
  --
  -- ⭐ ZADÁNÍ MAJITELE, které určilo tvar: „pozvánka je propojení BUDOUCÍ
  -- identity s entitou v systému."
  --
  -- Z toho plyne všechno ostatní. Pozvánka je ZÁMĚR vyslovený dopředu, ne fakt:
  -- v okamžiku jejího vystavení ten účet ještě neexistuje. Uplatnění dodá
  -- KANDIDÁTA („tenhle účet přišel s tím kódem"), ne důkaz totožnosti — kód je
  -- přenositelný a `claim_invitation` adresáta nekontroluje.
  --
  -- ⭐ AUTORIZACI PŘEDPŘIPRAVIL ODESÍLATEL (majitel): „přijetí pozvánky
  -- a přihlášení — autorizace uživatele je další krok, ale už schválený, resp.
  -- předpřipravený tím, kdo tu pozvánku posílá."
  --
  -- Otázka při uplatnění tedy NENÍ „smí ten člověk dovnitř?" — to už správce
  -- rozhodl. Je to „JE TO ON?". A právě tam byla díra: pozvánka nemusela být
  -- ADRESOVANÁ, takže se jí prokázal kdokoli, kdo získal kód.
  --
  -- Proto dvě větve, které se liší jen tím, jestli je komu to platí:
  --
  --   ADRESOVANÁ (má `email` a sedí s účtem)  → `confirmed`
  --       Předpřipravená autorizace platí pro TOHO adresáta a ten se přihlásil.
  --       Potvrzujícím zůstává SPRÁVCE (`confirmed_by = created_by`), ne ten,
  --       kdo pozvánku uplatnil — rozhodl přece on.
  --
  --   NEADRESOVANÁ (kód předaný jinak)        → `proposed`
  --       Není koho ověřit, takže předpřipravená autorizace nemá nositele.
  --       Ratifikuje člověk v review lane, která běží.
  --
  -- ⭐ SPOR JE VIDĚT: dva kandidáti na jednu entitu vyrobí dva návrhy vedle
  -- sebe. Dřív by druhý tiše prošel — a „vidím víc" nikdo nenahlásí.
  --
  -- Neúspěch NESHODÍ uplatnění: člověk musí dostat účet i roli, i když je
  -- s vazbou spor — ten rozsekne správce. Twin zůstane v `twin_accounts_missing`.
  IF v_invitation.twin_id IS NOT NULL THEN
    BEGIN
      -- Adresovaná = pozvánka nese e-mail A účet, který ji uplatňuje, ho má.
      -- Porovnává se bez ohledu na velikost písmen a okolní mezery; e-mail je
      -- case-insensitive a opsaný ručně bývá s mezerou.
      SELECT lower(btrim(v_invitation.email)) IS NOT NULL
             AND lower(btrim(v_invitation.email)) = lower(btrim(pr.email))
        INTO v_adresovana
        FROM public.profiles pr
       WHERE pr.user_id = v_user_id
       LIMIT 1;
      v_adresovana := COALESCE(v_adresovana, false);

      INSERT INTO public.twin_external_refs (
        twin_id, source, source_key, ref_kind, state, proposed_by, confidence,
        confirmed_by, confirmed_at, note
      ) VALUES (
        v_invitation.twin_id, 'aisha_auth', v_user_id::text, 'account',
        CASE WHEN v_adresovana THEN 'confirmed' ELSE 'proposed' END,
        'invitation:' || v_invitation.id::text, 1.0,
        CASE WHEN v_adresovana THEN v_invitation.created_by END,
        CASE WHEN v_adresovana THEN now() END,
        CASE WHEN v_adresovana
             THEN 'Adresovaná pozvánka uplatněna účtem se shodným e-mailem.'
             ELSE 'Pozvánka bez adresáta — čeká na ratifikaci člověkem.' END
      )
      ON CONFLICT DO NOTHING;
      v_twin_navrzeno := FOUND;
    EXCEPTION WHEN unique_violation THEN
      v_twin_navrzeno := false;
    END;
  END IF;

  -- Write audit
  PERFORM public.write_audit_journal(
      p_action_type := 'create'::journal_action_type,
      p_area := 'invitation'::journal_area,
      p_details := jsonb_build_object('code', v_invitation.code, 'role', v_invitation.role, 'study_id', v_invitation.study_id, 'twin_id', v_invitation.twin_id, 'twin_navrzeno', v_twin_navrzeno),
      p_entity_id := 'Invitation claimed',
      p_entity_type := 'invitation_claim',
      p_severity := NULL,
      p_summary := v_invitation.id::text,
    p_user_id := v_user_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'invitation_id', v_invitation.id,
    'role', v_invitation.role,
    'study_id', v_invitation.study_id,
    -- ⛔ `twin_navrzeno` NENÍ „máš přístup". Vazba čeká na potvrzení člověkem;
    -- do té doby `my_twins` neobsahuje nic a uživatel svoje věci NEVIDÍ. Kdyby
    -- se tenhle údaj četl jako hotovo, vzniklo by UI, které slibuje přístup,
    -- jenž ještě neplatí.
    'twin_id', v_invitation.twin_id,
    'twin_navrzeno', v_twin_navrzeno,
    'twin_potvrzeno', v_adresovana,
    'prefill_first_name', v_invitation.prefill_first_name,
    'prefill_last_name', v_invitation.prefill_last_name,
    'prefill_phone', v_invitation.prefill_phone,
    'prefill_notes', v_invitation.prefill_notes
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.claim_invitation(p_code text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.claim_invitation(p_code text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/claim_user_as_partner.sql
-- -----------------------------------------------------------------------------

-- Function: public.claim_user_as_partner
-- Arguments: p_onboarding_id uuid
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:25:59+01:00

CREATE OR REPLACE FUNCTION public.claim_user_as_partner(p_onboarding_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id uuid := auth.uid();
  v_partner_id uuid;
  v_user_id uuid;
BEGIN
  -- Get partner_id
  SELECT pp.id INTO v_partner_id 
  FROM partner_profiles pp 
  WHERE pp.user_id = v_caller_id
  AND pp.certification_passed_at IS NOT NULL;

  IF v_partner_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: must be certified partner';
  END IF;

  -- Get user_id from onboarding
  SELECT uo.user_id INTO v_user_id
  FROM onboarding_responses uo
  WHERE uo.id = p_onboarding_id
  AND uo.assigned_partner_id IS NULL;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Onboarding not found or already claimed';
  END IF;

  -- Assign partner
  UPDATE onboarding_responses uo SET
    assigned_partner_id = v_partner_id
  WHERE uo.id = p_onboarding_id;

  -- Audit log with correct enum values
  PERFORM public.write_audit_journal(
      p_action_type := 'create',
      p_area := 'partner_matching',
      p_details := jsonb_build_object(
      'partner_id', v_partner_id,
      'user_id', v_user_id,
      'onboarding_id', p_onboarding_id,
      'action_detail', 'partner_assignment'
    ),
      p_entity_id := p_onboarding_id::text,
      p_entity_type := -- Changed from 'assign' to 'create' 
    'onboarding_responses',
      p_new_values := NULL,
      p_old_values := NULL,
      p_severity := 'notice',
      p_summary := 'Partner claimed user from onboarding pool',
      p_tags := ARRAY['partner', 'matching', 'assignment'],
      p_user_id := v_caller_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'user_id', v_user_id,
    'partner_id', v_partner_id
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.claim_user_as_partner(p_onboarding_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.claim_user_as_partner(p_onboarding_id uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/close_pulse_beat_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.close_pulse_beat_audited
-- Arguments: p_beat_id uuid, p_outcome text, p_content text, p_metadata jsonb
-- Description: Closes a BEAT with a CONFIRMATION — the third stroke of the
--              pulse. The confirmation is a typed record on the subject's
--              timeline, and the beat points back at it (closing_entry_id), so
--              "what was owed" and "what proves it was done" are one link apart.
-- Security: SECURITY DEFINER. Who may close: operators, the person the beat is
--           addressed to, or the subject themselves (an actor confirming their
--           own dose/practice). The entry type is confined to the pulse
--           namespace so a caller cannot mint arbitrary typed records through
--           this door.

CREATE OR REPLACE FUNCTION public.close_pulse_beat_audited(
  p_beat_id uuid,
  p_outcome text DEFAULT 'done',
  p_content text DEFAULT NULL,
  p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id uuid := auth.uid();
  v_is_service boolean := (auth.role() = 'service_role');
  v_beat public.story_pulse_beats%ROWTYPE;
  v_entry_id uuid;
  v_entry_type text;
BEGIN
  IF v_caller_id IS NULL AND NOT v_is_service THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_outcome IS NULL OR p_outcome NOT IN ('done', 'cancelled') THEN
    RAISE EXCEPTION 'outcome must be done or cancelled' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_beat FROM public.story_pulse_beats WHERE id = p_beat_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Beat not found' USING ERRCODE = '22023';
  END IF;
  IF v_beat.status <> 'open' THEN
    -- Already settled: report the existing proof rather than closing twice.
    RETURN v_beat.closing_entry_id;
  END IF;

  IF NOT (
    v_is_service
    OR public.is_admin_or_staff()
    OR v_beat.assigned_to_user_id = v_caller_id
    OR (v_beat.subject_type = 'actor' AND v_beat.subject_id = v_caller_id)
  ) THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  v_entry_type := CASE WHEN p_outcome = 'cancelled' THEN 'pulse_beat_cancelled' ELSE 'pulse_beat_closed' END;

  v_entry_id := public.append_subject_entry_service(
    p_subject_type := v_beat.subject_type,
    p_subject_id   := v_beat.subject_id,
    p_entry_type   := v_entry_type,
    p_content      := p_content,
    p_metadata     := jsonb_build_object(
      'beat_id', v_beat.id,
      'beat_type', v_beat.beat_type,
      'outcome', p_outcome,
      'due_at', v_beat.due_at,
      'source_type', v_beat.source_type,
      'source_id', v_beat.source_id
    ) || COALESCE(p_metadata, '{}'::jsonb),
    p_created_by   := v_caller_id,
    p_story_id     := CASE WHEN v_beat.subject_type = 'story' THEN v_beat.subject_id ELSE NULL END,
    p_is_internal  := true,
    p_occurred_at  := now()
  );

  UPDATE public.story_pulse_beats
  SET status = CASE WHEN p_outcome = 'cancelled' THEN 'cancelled' ELSE 'done' END,
      closed_at = now(),
      closed_by = v_caller_id,
      closing_entry_id = v_entry_id
  WHERE id = v_beat.id;

  PERFORM public.write_audit_journal(
    p_action_type := 'update'::public.journal_action_type,
    p_area        := 'system'::public.journal_area,
    p_details     := jsonb_build_object(
      'beat_id', v_beat.id,
      'beat_type', v_beat.beat_type,
      'outcome', p_outcome,
      'subject_type', v_beat.subject_type,
      'subject_user_id', CASE WHEN v_beat.subject_type = 'actor' THEN v_beat.subject_id ELSE NULL END,
      'entry_id', v_entry_id
    ),
    p_entity_id   := v_beat.id::text,
    p_entity_type := 'story_pulse_beats',
    p_severity    := 'info'::public.journal_severity,
    p_summary     := format('Pulse beat %s (%s)', p_outcome, v_beat.beat_type),
    p_user_id     := v_caller_id
  );

  RETURN v_entry_id;
END;
$function$
;

