REVOKE EXECUTE ON FUNCTION public.close_pulse_beat_audited(uuid, text, text, jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.close_pulse_beat_audited(uuid, text, text, jsonb) TO authenticated;
