-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_admin_complete_followup.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: audience_admin_complete_followup
-- Description: Settles a follow-up. Since ADR-003 K2 a follow-up is a BEAT
--   (p_task_id = story_pulse_beats.id, the queue row key). A beat that came
--   from a workflow step is settled by COMPLETING THE STEP (the single write
--   path of work: complete_workflow_step → narration → goal re-evaluation → the
--   step↔beat joint closes the beat and opens the next). A beat with any other
--   source is closed directly. Legacy follow-ups created before K2 (beat with
--   source_type='ai_task', or the ai_tasks id itself) are still recognised and
--   settled, and their compatibility ai_tasks row is closed with them.
--   Returns true when THIS call settled it, false when it was already settled.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.audience_admin_complete_followup(
  p_task_id uuid,
  p_note text DEFAULT NULL,
  p_outcome text DEFAULT 'done'
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_beat   public.story_pulse_beats%rowtype;
  v_res    jsonb;
  v_actor  uuid;
  v_updated int := 0;
BEGIN
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;
  IF p_outcome IS NULL OR p_outcome NOT IN ('done', 'cancelled') THEN
    RAISE EXCEPTION 'outcome must be done or cancelled' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_beat FROM public.story_pulse_beats b WHERE b.id = p_task_id;
  IF NOT FOUND THEN
    -- legacy: caller passed the ai_tasks id of a pre-K2 follow-up
    SELECT * INTO v_beat FROM public.story_pulse_beats b
    WHERE b.source_type = 'ai_task' AND b.source_id = p_task_id
    ORDER BY (b.status = 'open') DESC, b.created_at DESC
    LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Follow-up not found' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_beat.status <> 'open' THEN
    RETURN false;  -- already settled (idempotent)
  END IF;

  v_actor := CASE WHEN v_beat.subject_type = 'actor' THEN v_beat.subject_id ELSE NULL END;

  IF v_beat.source_type = 'workflow_step' THEN
    -- Práce se uzavírá krokem; kloub v complete_workflow_step uzavře takt.
    v_res := public.complete_workflow_step(
      v_beat.source_id,
      jsonb_build_object('outcome', p_outcome, 'note', p_note),
      p_note,
      false,
      now());
    IF NOT COALESCE((v_res->>'ok')::boolean, false) THEN
      RAISE EXCEPTION 'follow-up step not completed: %', COALESCE(v_res->>'error', 'unknown');
    END IF;
    -- Kloub běží jako chráněný vedlejší účinek; kdyby selhal, takt by zůstal
    -- otevřený a tahle funkce by lhala, že je hotovo. Proto se to dohlíží tady.
    IF EXISTS (SELECT 1 FROM public.story_pulse_beats b WHERE b.id = v_beat.id AND b.status = 'open') THEN
      RAISE EXCEPTION 'step completed but beat % stayed open (joint failed — see audit_journal workflow.beat_joint_failed)', v_beat.id;
    END IF;
    v_updated := 1;
  ELSE
    PERFORM public.close_pulse_beat_audited(
      p_beat_id := v_beat.id,
      p_outcome := p_outcome,
      p_content := p_note);
    v_updated := 1;
  END IF;

  -- legacy compatibility row (pre-K2 follow-ups)
  IF v_beat.source_type = 'ai_task' AND v_beat.source_id IS NOT NULL THEN
    UPDATE public.ai_tasks
    SET status = CASE WHEN p_outcome = 'cancelled' THEN 'cancelled' ELSE 'done' END,
        completed_at = now(),
        updated_at = now(),
        result = COALESCE(result, '{}'::jsonb)
                   || jsonb_build_object('outcome', p_outcome, 'note', p_note, 'beat_id', v_beat.id)
    WHERE id = v_beat.source_id
      AND task_type = 'follow_up'
      AND status NOT IN ('done', 'cancelled');
  END IF;

  PERFORM public.audience_log_event(
    'complete_followup',
    'audience_admin_complete_followup',
    'story_pulse_beat',
    v_beat.id,
    format('Completed follow-up (%s) for %s %s', p_outcome, v_beat.subject_type, v_beat.subject_id),
    jsonb_build_object('actor_id', v_actor, 'subject_type', v_beat.subject_type,
                       'subject_id', v_beat.subject_id, 'outcome', p_outcome,
                       'beat_id', v_beat.id, 'source_type', v_beat.source_type,
                       'source_id', v_beat.source_id, 'note', p_note)
  );
  RETURN v_updated > 0;
END;
$function$
;
-- Permissions
REVOKE ALL ON FUNCTION public.audience_admin_complete_followup(uuid, text, text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.audience_admin_complete_followup(uuid, text, text) FROM anon;
GRANT EXECUTE ON FUNCTION public.audience_admin_complete_followup(uuid, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.audience_admin_complete_followup(uuid, text, text) TO authenticator;
GRANT EXECUTE ON FUNCTION public.audience_admin_complete_followup(uuid, text, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/complete_onboarding_assessment.sql
-- -----------------------------------------------------------------------------

-- Function: public.complete_onboarding_assessment
-- Arguments: none
-- Description: Creates a completed onboarding assessment for the current user.
--              Used when user completes the reInvented Immunology onboarding questionnaire.
--              If an existing in_progress assessment exists, updates it to completed.
-- Security: SECURITY DEFINER, authenticated only

CREATE OR REPLACE FUNCTION public.complete_onboarding_assessment()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_assessment_id uuid;
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  -- Check for existing onboarding assessment
  SELECT id INTO v_assessment_id
  FROM public.operational_assessments
  WHERE user_id = v_user_id
    AND assessment_type = 'onboarding'
  ORDER BY created_at DESC
  LIMIT 1;
  
  IF v_assessment_id IS NOT NULL THEN
    -- Update existing to completed
    UPDATE public.operational_assessments
    SET status = 'completed',
        updated_at = now()
    WHERE id = v_assessment_id;
  ELSE
    -- Create new completed assessment
    INSERT INTO public.operational_assessments (user_id, assessment_type, status)
    VALUES (v_user_id, 'onboarding', 'completed')
    RETURNING id INTO v_assessment_id;
  END IF;
  
  -- Audit log
  PERFORM public.write_audit_journal(
      p_action_type := 'update'::journal_action_type,
      p_area := 'member'::journal_area,
      p_details := NULL,
      p_entity_id := 'Onboarding questionnaire completed',
      p_entity_type := 'operational_assessment',
      p_old_values := jsonb_build_object('assessment_type', 'onboarding', 'status', 'completed'),
      p_severity := 'info'::journal_severity,
      p_summary := v_assessment_id::text,
    p_user_id := v_user_id
  );
  
  RETURN v_assessment_id;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.complete_onboarding_assessment() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.complete_onboarding_assessment() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/complete_operational_assessment.sql
-- -----------------------------------------------------------------------------

-- Function: public.complete_operational_assessment
-- Arguments: p_assessment_id uuid, p_overall_score numeric, p_interpretation text, p_alert_flags text[], p_has_critical_flags boolean
-- Security: SECURITY DEFINER
-- Source: Extracted from local DB (source-of-truth sync)

CREATE OR REPLACE FUNCTION public.complete_operational_assessment(p_assessment_id uuid, p_overall_score numeric, p_interpretation text, p_alert_flags text[], p_has_critical_flags boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_previous_score numeric;
BEGIN
  -- Verify ownership
  IF NOT EXISTS (SELECT 1 FROM public.operational_assessments WHERE id = p_assessment_id AND user_id = auth.uid()) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  
  -- Get previous score for trend
  SELECT overall_score INTO v_previous_score
  FROM public.operational_assessments
  WHERE user_id = auth.uid()
    AND status = 'completed'
    AND id != p_assessment_id
  ORDER BY completed_at DESC
  LIMIT 1;
  
  UPDATE public.operational_assessments
  SET 
    status = 'completed',
    overall_score = p_overall_score,
    interpretation = p_interpretation,
    alert_flags = p_alert_flags,
    has_critical_flags = p_has_critical_flags,
    trend_vs_baseline = CASE WHEN v_previous_score IS NOT NULL THEN p_overall_score - v_previous_score ELSE NULL END,
    completed_at = now(),
    updated_at = now()
  WHERE id = p_assessment_id;
  
  -- Audit log
  PERFORM public.write_audit_journal(
      p_action_type := 'update'::journal_action_type,
      p_area := 'member'::journal_area,
      p_details := NULL,
      p_entity_id := 'Operational assessment completed',
      p_entity_type := 'operational_assessment',
      p_old_values := jsonb_build_object('overall_score', p_overall_score, 'interpretation', p_interpretation),
      p_severity := 'info'::journal_severity,
      p_summary := p_assessment_id::text,
    p_user_id := auth.uid()
  );
  
  RETURN true;
END;
$function$;

REVOKE ALL ON FUNCTION public.complete_operational_assessment(uuid, numeric, text, text[][], boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.complete_operational_assessment(uuid, numeric, text, text[][], boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.complete_operational_assessment(uuid, numeric, text, text[][], boolean) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/complete_reminder.sql
-- -----------------------------------------------------------------------------

-- Function: public.complete_reminder
-- Arguments: p_reminder_id uuid, p_quick_response jsonb, p_questionnaire_response_id uuid, p_health_check_in_id uuid
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:00+01:00

CREATE OR REPLACE FUNCTION public.complete_reminder(p_reminder_id uuid, p_quick_response jsonb DEFAULT NULL::jsonb, p_questionnaire_response_id uuid DEFAULT NULL::uuid, p_health_check_in_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_points INTEGER;
  v_completion_id UUID;
  v_new_balance NUMERIC;
  v_reminder_title TEXT;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- RATE LIMITING: 20 requests per minute
  PERFORM enforce_rate_limit('complete_reminder', 60000, 20);

  -- Get reminder details and verify ownership
  SELECT points_per_completion, title INTO v_points, v_reminder_title
  FROM user_reminders
  WHERE id = p_reminder_id AND user_id = v_user_id;

  IF v_points IS NULL THEN
    RAISE EXCEPTION 'Reminder not found or access denied';
  END IF;

  -- Check if already completed today
  IF EXISTS (
    SELECT 1 FROM reminder_completions
    WHERE reminder_id = p_reminder_id
      AND user_id = v_user_id
      AND DATE(completed_at) = CURRENT_DATE
  ) THEN
    RAISE EXCEPTION 'Reminder already completed today';
  END IF;

  -- Create completion record
  INSERT INTO reminder_completions (
    user_id,
    reminder_id,
    quick_response,
    questionnaire_response_id,
    health_check_in_id,
    points_awarded,
    scheduled_for,
    completed_at
  ) VALUES (
    v_user_id,
    p_reminder_id,
    p_quick_response,
    p_questionnaire_response_id,
    p_health_check_in_id,
    v_points,
    now(), -- Simplified: should calculate actual scheduled time
    now()
  )
  RETURNING id INTO v_completion_id;

  -- Award points via token system
  INSERT INTO token_transactions (
    to_user_id,
    amount,
    transaction_type,
    reference_type,
    reference_id,
    description,
    created_at
  ) VALUES (
    v_user_id,
    v_points,
    'reward',
    'reminder_completion',
    v_completion_id,
    format('Completed: %s', v_reminder_title),
    now()
  );

  -- Update user token balance
  INSERT INTO token_allocations (user_id, balance, updated_at)
  VALUES (v_user_id, v_points, now())
  ON CONFLICT (user_id)
  DO UPDATE SET
    balance = token_allocations.balance + v_points,
    updated_at = now()
  RETURNING balance INTO v_new_balance;

  -- Audit log
  PERFORM public.write_audit_journal(
      p_action_type := 'insert'::journal_action_type,
      p_area := 'mobile'::journal_area,
      p_details := jsonb_build_object(
      'reminder_id', p_reminder_id,
      'points_awarded', v_points
    ),
      p_entity_id := v_completion_id,
      p_entity_type := 'reminder_completions',
      p_new_values := NULL,
      p_old_values := NULL,
      p_severity := 'notice'::journal_severity,
      p_summary := 'User completed reminder',
      p_tags := ARRAY['mobile', 'gamification', 'reminder'],
      p_user_id := v_user_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'completion_id', v_completion_id,
    'points_awarded', v_points,
    'new_balance', v_new_balance
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.complete_reminder(p_reminder_id uuid, p_quick_response jsonb, p_questionnaire_response_id uuid, p_health_check_in_id uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.complete_reminder(p_reminder_id uuid, p_quick_response jsonb, p_questionnaire_response_id uuid, p_health_check_in_id uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/compute_production_angels_share_report_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.compute_production_angels_share_report_admin
-- Arguments: p_batch_id uuid, p_date_from timestamptz, p_date_to timestamptz, p_substance_id uuid
-- Description: Server-side computation for Angels' Share (production loss) customs authority reporting.
-- Security: SECURITY DEFINER, admin/staff only
-- Source: Migration 20260219180000_production_enhancements.sql

CREATE OR REPLACE FUNCTION public.compute_production_angels_share_report_admin(
  p_batch_id uuid DEFAULT NULL,
  p_date_from timestamptz DEFAULT NULL,
  p_date_to timestamptz DEFAULT NULL,
  p_substance_id uuid DEFAULT NULL
)
RETURNS TABLE(
  batch_id uuid,
  batch_code text,
  substance_id uuid,
  substance_name text,
  substance_cas_number text,
  regulatory_class text,
  total_input_volume_l numeric,
  total_input_pure_l numeric,
  total_output_volume_l numeric,
  total_output_pure_l numeric,
  total_waste_volume_l numeric,
  total_waste_pure_l numeric,
  loss_volume_l numeric,
  loss_pure_l numeric,
  loss_pct numeric,
  loss_pure_pct numeric,
  record_count bigint,
  first_record_date timestamptz,
  last_record_date timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_admin_or_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or staff role required';
  END IF;

  -- Audit this sensitive report access
  PERFORM public.write_audit_journal(
    p_action_type := 'export'::public.journal_action_type,
    p_area := 'production'::public.journal_area,
    p_details := NULL,
    p_entity_id := COALESCE(p_batch_id::text, 'all'),
    p_entity_type := 'angels_share_report',
    p_new_values := jsonb_build_object(
      'date_from', p_date_from,
      'date_to', p_date_to,
      'substance_id', p_substance_id
    ),
    p_old_values := NULL,
    p_severity := 'notice'::public.journal_severity,
    p_summary := 'Angels Share report generated for customs authority',
    p_tags := ARRAY['admin', 'angels_share', 'customs_report', 'regulatory'],
    p_user_id := auth.uid()
  );

  RETURN QUERY
  WITH filtered_records AS (
    SELECT
      r.batch_id AS r_batch_id,
      r.substance_id AS r_substance_id,
      r.source_node_id,
      r.target_node_id,
      r.volume_l,
      r.pure_amount_l,
      r.flow_date,
      sn.node_type AS source_type,
      tn.node_type AS target_type
    FROM production_flow_records r
    JOIN production_flow_nodes sn ON sn.id = r.source_node_id
    JOIN production_flow_nodes tn ON tn.id = r.target_node_id
    WHERE r.is_storno = false
      AND (p_batch_id IS NULL OR r.batch_id = p_batch_id)
      AND (p_substance_id IS NULL OR r.substance_id = p_substance_id)
      AND (p_date_from IS NULL OR r.flow_date >= p_date_from)
      AND (p_date_to IS NULL OR r.flow_date <= p_date_to)
  ),
  aggregated AS (
    SELECT
      fr.r_batch_id,
      fr.r_substance_id,
      -- Input = volume dispatched FROM supplier nodes
      SUM(CASE WHEN fr.source_type = 'supplier' THEN fr.volume_l ELSE 0 END) AS input_vol,
      SUM(CASE WHEN fr.source_type = 'supplier' THEN fr.pure_amount_l ELSE 0 END) AS input_pure,
      -- Output = volume received BY finished nodes
      SUM(CASE WHEN fr.target_type = 'finished' THEN fr.volume_l ELSE 0 END) AS output_vol,
      SUM(CASE WHEN fr.target_type = 'finished' THEN fr.pure_amount_l ELSE 0 END) AS output_pure,
      -- Waste = volume received BY waste nodes
      SUM(CASE WHEN fr.target_type = 'waste' THEN fr.volume_l ELSE 0 END) AS waste_vol,
      SUM(CASE WHEN fr.target_type = 'waste' THEN fr.pure_amount_l ELSE 0 END) AS waste_pure,
      COUNT(*) AS rec_count,
      MIN(fr.flow_date) AS first_date,
      MAX(fr.flow_date) AS last_date
    FROM filtered_records fr
    GROUP BY fr.r_batch_id, fr.r_substance_id
  )
  SELECT
    a.r_batch_id AS batch_id,
    pb.batch_code,
    a.r_substance_id AS substance_id,
    fs.substance_name,
    fs.cas_number AS substance_cas_number,
    fs.regulatory_class,
    a.input_vol AS total_input_volume_l,
    a.input_pure AS total_input_pure_l,
    a.output_vol AS total_output_volume_l,
    a.output_pure AS total_output_pure_l,
    a.waste_vol AS total_waste_volume_l,
    a.waste_pure AS total_waste_pure_l,
    (a.input_vol - a.output_vol - a.waste_vol) AS loss_volume_l,
    (a.input_pure - a.output_pure - a.waste_pure) AS loss_pure_l,
    CASE WHEN a.input_vol > 0
      THEN ROUND(((a.input_vol - a.output_vol - a.waste_vol) / a.input_vol) * 100, 4)
      ELSE 0 END AS loss_pct,
    CASE WHEN a.input_pure > 0
      THEN ROUND(((a.input_pure - a.output_pure - a.waste_pure) / a.input_pure) * 100, 4)
      ELSE 0 END AS loss_pure_pct,
    a.rec_count AS record_count,
    a.first_date AS first_record_date,
    a.last_date AS last_record_date
  FROM aggregated a
  JOIN production_batches pb ON pb.id = a.r_batch_id
  JOIN production_flow_substances fs ON fs.id = a.r_substance_id
  ORDER BY pb.batch_code, fs.substance_name;
END;
$$;

REVOKE ALL ON FUNCTION public.compute_production_angels_share_report_admin(uuid, timestamptz, timestamptz, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.compute_production_angels_share_report_admin(uuid, timestamptz, timestamptz, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/compute_production_flow_balance_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.compute_production_flow_balance_admin
-- Computes substance balance per batch: per-node receipts/dispatches, total input,
-- total accounted, loss (Angels' Share), loss percentage.
-- This is the KEY function for dynamic recalculation of flow balances.
-- SECURITY DEFINER with admin guard and audit log

CREATE OR REPLACE FUNCTION public.compute_production_flow_balance_admin(
  p_batch_id uuid DEFAULT NULL,
  p_substance_id uuid DEFAULT NULL
)
RETURNS TABLE(
  node_id uuid,
  node_code text,
  node_name text,
  node_type text,
  total_received_volume_l numeric,
  total_received_pure_l numeric,
  total_dispatched_volume_l numeric,
  total_dispatched_pure_l numeric,
  balance_volume_l numeric,
  balance_pure_l numeric,
  avg_concentration_pct numeric,
  record_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin_or_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or staff role required';
  END IF;

  IF p_batch_id IS NULL THEN
    RAISE EXCEPTION 'batch_id is required for balance computation';
  END IF;

  IF p_substance_id IS NULL THEN
    RAISE EXCEPTION 'substance_id is required for balance computation';
  END IF;

  PERFORM public.write_audit_journal(
    p_action_type := 'read'::public.journal_action_type,
    p_area := 'products'::public.journal_area,
    p_details := NULL,
    p_entity_id := p_batch_id::text,
    p_entity_type := 'production_flow_balance',
    p_new_values := jsonb_build_object('batch_id', p_batch_id, 'substance_id', p_substance_id),
    p_old_values := NULL,
    p_severity := 'notice'::public.journal_severity,
    p_summary := 'Admin computed flow balance',
    p_tags := ARRAY['admin', 'flow_tracking', 'balance'],
    p_user_id := auth.uid()
  );

  RETURN QUERY
  WITH received AS (
    SELECT
      r.target_node_id AS nid,
      COALESCE(SUM(r.volume_l), 0) AS vol,
      COALESCE(SUM(r.pure_amount_l), 0) AS pure,
      COUNT(*) AS cnt
    FROM public.production_flow_records r
    WHERE r.batch_id = p_batch_id
      AND r.substance_id = p_substance_id
    GROUP BY r.target_node_id
  ),
  dispatched AS (
    SELECT
      r.source_node_id AS nid,
      COALESCE(SUM(r.volume_l), 0) AS vol,
      COALESCE(SUM(r.pure_amount_l), 0) AS pure,
      COUNT(*) AS cnt
    FROM public.production_flow_records r
    WHERE r.batch_id = p_batch_id
      AND r.substance_id = p_substance_id
    GROUP BY r.source_node_id
  ),
  all_nodes AS (
    SELECT nid FROM received
    UNION
    SELECT nid FROM dispatched
  )
  SELECT
    n.id,
    n.node_code,
    n.node_name,
    n.node_type,
    COALESCE(recv.vol, 0),
    COALESCE(recv.pure, 0),
    COALESCE(disp.vol, 0),
    COALESCE(disp.pure, 0),
    COALESCE(recv.vol, 0) - COALESCE(disp.vol, 0),
    COALESCE(recv.pure, 0) - COALESCE(disp.pure, 0),
    CASE
      WHEN COALESCE(recv.vol, 0) - COALESCE(disp.vol, 0) > 0 THEN
        (COALESCE(recv.pure, 0) - COALESCE(disp.pure, 0)) /
        (COALESCE(recv.vol, 0) - COALESCE(disp.vol, 0)) * 100.0
      ELSE 0
    END,
    COALESCE(recv.cnt, 0) + COALESCE(disp.cnt, 0)
  FROM all_nodes an
  JOIN public.production_flow_nodes n ON n.id = an.nid
  LEFT JOIN received recv ON recv.nid = an.nid
  LEFT JOIN dispatched disp ON disp.nid = an.nid
  ORDER BY n.node_type, n.node_code;
END;
$function$;

REVOKE ALL ON FUNCTION public.compute_production_flow_balance_admin(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.compute_production_flow_balance_admin(uuid, uuid) TO authenticated;


