-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_entity_evidence_preflight_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: create_entity_evidence_preflight_audited
-- Popis: Preflight fotografické evidence POŘÍZENÉ V TERÉNU — autorizuje upload
--        a zaregistruje snímek jako UDÁLOST K ENTITĚ (twin_events).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT pattern
-- ============================================================================
--
-- JEDNA DRÁHA, DVĚ POUŽITÍ. Řidič u sklopky vyfotí předání; správce vyfotí
-- elektroměr na zdi. Akvizice je TÁŽ (telefon → MinIO → záznam), liší se jen
-- entita, ke které snímek patří, a kdo na ni má nárok. Proto tu není „foto
-- předání" a vedle „foto měřidla", ale jedno RPC s dispatchem — druhá kopie by
-- se rozešla při první změně a měřidla by zůstala o opravu pozadu.
--
-- PROČ twin_events A NE NOVÁ TABULKA: snímek je informace K ENTITĚ, a přesně to
-- twin_events jsou („místo setkání plán × skutečnost × doklad", append-only).
-- `event_type` je volný slug (slovník je doménová volba), `attrs` unese odkaz na
-- objekt a dvojice (source, source_ref) dává idempotenci zdarma. Nové silo by
-- znamenalo druhou pravdu o tomtéž a majitel ho pro odečty výslovně odmítl.
--
-- IDEMPOTENCE JE OBJEKTOVÝ KLÍČ, NE ČAS. `source_ref = p_file_path`, a ten je
-- v object key vyrobený z uuid — týž preflight zavolaný dvakrát (retry na
-- mizerné síti v lomu) proto nezaloží druhou událost. Kdyby klíčem byl čas,
-- každý retry by vyrobil nový „doklad" o téže fotce.
--
-- OBRÁZEK SE SEM NEDOSTANE. Ukládá se REFERENCE (bucket, klíč, velikost, typ);
-- binárka žije v MinIO. Jsonb není úložiště souborů — TOASTovaná fotka v řádku,
-- který čte fronta při každém načtení, je jistá cesta k pomalé ploše.
--
-- ⚠️ NÁROK NENÍ „PŘIHLÁŠENÝ". Kdo smí fotit, se ptá TÉŽE autority jako kdo smí
-- krok dokončit — sdíleného predikátu workflow_step_visible_to. Kdyby tu stála
-- vlastní kopie pravidla, rozešla by se s ním a řidič by směl fotit k běhu,
-- který nesmí ani vidět.
--
-- ⛔ KROK BEZ TWIN VAZBY FOTIT NELZE, a je to VĚDOMÁ hranice, ne opomenutí:
-- událost musí vědět, KOHO/ČEHO se týká. Uzel řízený rolí (naložení, přeprava)
-- takovou vazbu nemá; dosadit twin „nějak" by znamenalo vyrobit doklad o entitě,
-- kterou nikdo neurčil. Funkce to proto řekne nahlas místo tichého uložení
-- vedle. Rozšíření = dát uzlu vazbu v šabloně, ne změkčit tuhle podmínku.

CREATE OR REPLACE FUNCTION public.create_entity_evidence_preflight_audited(
  p_file_path   text,
  p_file_name   text,
  p_file_size   integer,
  p_mime_type   text,
  p_entity_kind text,
  p_entity_id   uuid,
  p_slot        text DEFAULT NULL
)
RETURNS TABLE(id uuid, file_path text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid           uuid := auth.uid();
  v_twin_id       uuid;
  v_actor_twin_id uuid;
  v_story_id      uuid;
  v_batch_id      uuid;
  v_event_id      uuid;
  v_attrs         jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  -- Cesta musí patřit volajícímu. Táž konvence jako u zdravotních dokumentů:
  -- object key začíná uid, takže podvržená cesta do cizí složky neprojde.
  IF p_file_path IS NULL OR p_file_path NOT LIKE v_uid::text || '/%' THEN
    RAISE EXCEPTION 'Invalid file path' USING ERRCODE = '22023';
  END IF;

  IF p_file_size IS NULL OR p_file_size <= 0 THEN
    RAISE EXCEPTION 'file size must be positive' USING ERRCODE = '22023';
  END IF;

  -- Jen obrázky. Velikost a MIME hlídá i brána storage-auth; tady se to opakuje
  -- proto, že RPC je grantnuté `authenticated` a dá se zavolat i mimo ni.
  IF p_mime_type IS NULL OR p_mime_type NOT LIKE 'image/%' THEN
    RAISE EXCEPTION 'evidence must be an image (got %)', coalesce(p_mime_type, '<null>')
      USING ERRCODE = '22023';
  END IF;

  IF p_entity_id IS NULL THEN
    RAISE EXCEPTION 'entity id is required' USING ERRCODE = '22023';
  END IF;

  -- ── Dispatch podle druhu entity ────────────────────────────────────────────
  -- Uzavřená množina a neznámý druh RAISE. Fail-closed: druh, kterému nerozumíme,
  -- nesmí skončit uložený, jako bychom mu rozuměli.
  IF p_entity_kind = 'workflow_step' THEN
    SELECT s.batch_id,
           -- KOMU UDÁLOST PATŘÍ: tomu, ČEHO se týká (subjekt běhu), a teprve
           -- když subjekt není znám, tomu, KDO ji pořídil. Není to fallback,
           -- ale deklarované pořadí: u odečtu je subjektem měřidlo a událost
           -- patří jemu, u předání zná uzel jen oprávněnou osobu. Kdyby foto
           -- měřidla viselo na odečítači, historie měřidla by ho neobsahovala —
           -- a právě ta je smyslem časové řady k entitě.
           coalesce((s.input_data->>'subject_twin_id')::uuid,
                    (s.input_data->>'authorized_twin_id')::uuid),
           (s.input_data->>'authorized_twin_id')::uuid
      INTO v_batch_id, v_twin_id, v_actor_twin_id
      FROM public.production_workflow_steps s
     WHERE s.id = p_entity_id
       -- TÁŽ autorita jako u dokončení kroku — žádná inline kopie pravidla.
       AND public.workflow_step_visible_to(v_uid, s.assigned_user_id, s.assigned_role, s.input_data);

    IF v_batch_id IS NULL THEN
      -- Nerozlišuje se „neexistuje" od „nesmíš": jinak by se dal existující krok
      -- vyzkoušet podle toho, která chyba přijde.
      RAISE EXCEPTION 'workflow step not found or not visible' USING ERRCODE = '42501';
    END IF;

    IF v_twin_id IS NULL THEN
      RAISE EXCEPTION 'step % has no subject_twin_id nor authorized_twin_id — evidence needs an entity to belong to', p_entity_id
        USING ERRCODE = '22023';
    END IF;

    SELECT b.story_id INTO v_story_id FROM public.production_batches b WHERE b.id = v_batch_id;

  ELSIF p_entity_kind = 'twin' THEN
    -- Odečet měřidla: entita JE twin (elektroměr, vodoměr).
    --
    -- ⛔ RLS TU NEPOMŮŽE. Tahle funkce je SECURITY DEFINER, takže čtení
    -- twin_entities běží s právy vlastníka a policy se NEUPLATNÍ — „SELECT
    -- vrátil řádek" by tedy neznamenalo „volající na něj má nárok", jen „twin
    -- existuje". Spoléhat se tu na RLS je klasická fail-open díra.
    --
    -- Nárok je proto výslovný a plyne z PRÁCE: fotit smíš to, na co máš otevřený
    -- úkol. To je přesně model odečtů — úkol s termínem říká, kdo kam má jít co
    -- změřit — a znamená, že oprávnění vzniká i zaniká s úkolem, bez zvláštní
    -- role a bez ruční správy seznamu.
    IF NOT (
      public.is_admin_or_staff()
      OR EXISTS (
           SELECT 1
             FROM public.production_workflow_steps s
            WHERE (s.input_data->>'subject_twin_id')::uuid = p_entity_id
              AND s.status NOT IN ('completed', 'failed')
              AND public.workflow_step_visible_to(v_uid, s.assigned_user_id, s.assigned_role, s.input_data)
         )
    ) THEN
      RAISE EXCEPTION 'twin not found or no open task authorizes capturing it' USING ERRCODE = '42501';
    END IF;

    SELECT t.id INTO v_twin_id FROM public.twin_entities t WHERE t.id = p_entity_id;
    IF v_twin_id IS NULL THEN
      RAISE EXCEPTION 'twin not found or no open task authorizes capturing it' USING ERRCODE = '42501';
    END IF;

  ELSE
    RAISE EXCEPTION 'unknown entity kind: % (allowed: workflow_step, twin)', coalesce(p_entity_kind, '<null>')
      USING ERRCODE = '22023';
  END IF;

  v_attrs := jsonb_strip_nulls(jsonb_build_object(
    'bucket',      'entity-evidence',
    'object_key',  p_file_path,
    'file_name',   p_file_name,
    'file_size',   p_file_size,
    'mime_type',   p_mime_type,
    'slot',        p_slot,
    'entity_kind', p_entity_kind,
    -- U kroku si událost drží i to, KTERÝ milník ji vyvolal; twin sám by řekl
    -- „patří k řidiči", ne „vznikla při tomhle předání".
    'step_id',     CASE WHEN p_entity_kind = 'workflow_step' THEN p_entity_id::text END,
    'captured_by', v_uid::text));

  -- occurred_at = TEĎ, protože preflight běží v okamžiku pořízení. Kdyby čas
  -- posílal klient, byl by to údaj od dokumentovaného o sobě samém.
  -- `related_twin_id` = kdo snímek pořídil, když se liší od subjektu. U odečtu
  -- tak zůstane u události měřidla i to, kdo tam byl — bez toho by časová řada
  -- entity věděla „co", ale ne „od koho".
  --
  -- ⚠️ `ON CONFLICT` musí opakovat i predikát: uq_twin_events_source_ref je
  -- PARTIÁLNÍ index (`WHERE source_ref IS NOT NULL`) a bez shodné podmínky by
  -- Postgres arbitr nenašel a příkaz by spadl na 42P10 — tedy až za běhu.
  INSERT INTO public.twin_events (event_type, twin_id, related_twin_id, story_id, occurred_at, attrs, source, source_ref)
  VALUES ('evidence_photo', v_twin_id,
          CASE WHEN v_actor_twin_id IS DISTINCT FROM v_twin_id THEN v_actor_twin_id END,
          v_story_id, now(), v_attrs, 'field-capture', p_file_path)
  ON CONFLICT (source, event_type, source_ref) WHERE source_ref IS NOT NULL DO UPDATE
    SET attrs = excluded.attrs
  RETURNING public.twin_events.id INTO v_event_id;

  -- ⛔ OBLAST AUDITU JE ENUM (journal_area) a 'evidence' v něm NENÍ. Do
  -- 2026-09-29 tu stálo holé `'evidence'` — literál bez přetypování v
  -- pojmenovaném argumentu brána enum-consistency nevidí, a preflight proto
  -- padal na 22P02 až za běhu, u každé fotky z terénu (naměřeno runtime testem
  -- prezdivka-meridla). Přetypování je explicitní, aby ho brána příště viděla.
  PERFORM public.write_audit_journal(
    p_action_type := 'create'::journal_action_type,
    p_area        := 'operational_data'::journal_area,
    p_details     := jsonb_build_object(
                       'entity_kind', p_entity_kind,
                       'entity_id',   p_entity_id::text,
                       'file_size',   p_file_size,
                       'mime_type',   p_mime_type,
                       'slot',        p_slot),
    p_entity_id   := v_event_id::text,
    p_entity_type := 'twin_event',
    p_new_values  := NULL,
    p_old_values  := NULL,
    p_severity    := 'info',
    p_summary     := 'Field evidence photo registered',
    p_tags        := ARRAY['evidence','upload','field'],
    p_user_id     := v_uid
  );

  RETURN QUERY SELECT v_event_id, p_file_path;
END;
$function$;

REVOKE ALL ON FUNCTION public.create_entity_evidence_preflight_audited(text,text,integer,text,text,uuid,text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.create_entity_evidence_preflight_audited(text,text,integer,text,text,uuid,text) FROM anon;
GRANT EXECUTE ON FUNCTION public.create_entity_evidence_preflight_audited(text,text,integer,text,text,uuid,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.create_entity_evidence_preflight_audited(text,text,integer,text,text,uuid,text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_health_document_preflight_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_health_document_preflight_audited
-- Arguments: p_file_name text, p_file_path text, p_file_size integer, p_mime_type text, p_category health_document_category,
--            p_title text, p_description text, p_document_date date, p_study_registration_id uuid
-- Description: Creates a member_health_documents row for an upload preflight (owner only). Audited.

CREATE OR REPLACE FUNCTION public.create_health_document_preflight_audited(
  p_file_name text,
  p_file_path text,
  p_file_size integer,
  p_mime_type text,
  p_category health_document_category,
  p_title text DEFAULT NULL::text,
  p_description text DEFAULT NULL::text,
  p_document_date date DEFAULT NULL::date,
  p_study_registration_id uuid DEFAULT NULL::uuid
)
RETURNS TABLE(
  id uuid,
  file_path text,
  file_name text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_registration_user_id uuid;
  v_doc_id uuid;
  v_doc_path text;
  v_doc_name text;
  v_quarantine_on boolean;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Parametric activation of the upload AV/quarantine flow. While OFF (default — key absent
  -- ⇒ '{}' ≠ 'true'), a new document starts 'clear' (servable immediately, exactly the
  -- pre-feature behaviour — no regression). It is flipped ON only once the full coherent flow
  -- is in place (quarantine-bucket routing + clamd scan→promote worker + serving gates), so
  -- 'flagged' is never set without a promoter to clear it. Doubles as an ops kill-switch.
  v_quarantine_on := public.get_system_config('av.upload_quarantine_enabled') = 'true'::jsonb;

  IF p_file_path IS NULL OR p_file_path NOT LIKE v_user_id::text || '/%' THEN
    RAISE EXCEPTION 'Invalid file path' USING ERRCODE = '22023';
  END IF;

  IF p_study_registration_id IS NOT NULL THEN
    SELECT se.user_id
    INTO v_registration_user_id
    FROM public.study_registrations se
    WHERE se.id = p_study_registration_id;

    IF v_registration_user_id IS NULL OR v_registration_user_id <> v_user_id THEN
      RAISE EXCEPTION 'Invalid study registration' USING ERRCODE = '22023';
    END IF;
  END IF;

  INSERT INTO public.member_health_documents (
    user_id,
    file_name,
    file_path,
    file_size,
    mime_type,
    category,
    title,
    description,
    document_date,
    study_registration_id,
    quarantine_status
  ) VALUES (
    v_user_id,
    p_file_name,
    p_file_path,
    p_file_size,
    p_mime_type,
    COALESCE(p_category, 'other'::health_document_category),
    p_title,
    p_description,
    p_document_date,
    p_study_registration_id,
    -- Flag-gated: when the upload AV/quarantine flow is ON, a new upload starts 'flagged'
    -- (fail-closed — blocked until record_document_av_scan_audited promotes it to 'clear').
    -- When OFF (default) it starts 'clear', matching the pre-feature behaviour so there is
    -- never a 'flagged' row without a scan→promote worker to clear it.
    CASE WHEN v_quarantine_on THEN 'flagged' ELSE 'clear' END
  )
  RETURNING member_health_documents.id, member_health_documents.file_path, member_health_documents.file_name
  INTO v_doc_id, v_doc_path, v_doc_name;

  PERFORM public.write_audit_journal(
      p_action_type := 'create',
      p_area := 'documents',
      p_details := jsonb_build_object(
      'category', COALESCE(p_category::text, 'other'),
      'file_size', COALESCE(p_file_size, 0),
      'has_study_registration', p_study_registration_id IS NOT NULL
    ),
      p_entity_id := v_doc_id::text,
      p_entity_type := 'member_health_document',
      p_new_values := NULL,
      p_old_values := NULL,
      p_severity := 'info',
      p_summary := 'Health document upload preflight created',
      p_tags := ARRAY['phi','documents','upload'],
      p_user_id := v_user_id
  );

  RETURN QUERY SELECT v_doc_id, v_doc_path, v_doc_name;
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.create_health_document_preflight_audited(text, text, integer, text, health_document_category, text, text, date, uuid) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.create_health_document_preflight_audited(text, text, integer, text, health_document_category, text, text, date, uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.create_health_document_preflight_audited(text, text, integer, text, health_document_category, text, text, date, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_hero_slide_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_hero_slide_admin
-- Arguments: p_id, p_base_locale, p_title_key, p_subtitle_key, p_badge_key, p_cta_text_key,
--            p_circle_icon_key, p_circle_text_key, p_target_audience, p_background_image_url,
--            p_background_gradient, p_cta_url, p_linked_product_id, p_is_active, p_sort_order
-- Description: Creates a new hero slide. Requires admin role.
-- Security: SECURITY DEFINER with search_path set.
-- Extracted: 2026-01-09
-- Updated: 2026-01-30 - Migrated to translation keys

-- Drop old overloads (no longer exist, safe cleanup)
DROP FUNCTION IF EXISTS public.create_hero_slide_admin(uuid, text, text, text, text, text, text, text, text, text, text, text, uuid, boolean, integer);

CREATE OR REPLACE FUNCTION public.create_hero_slide_admin(
  p_id uuid DEFAULT NULL,
  p_base_locale text DEFAULT 'en',
  p_title_key text DEFAULT NULL,
  p_subtitle_key text DEFAULT NULL,
  p_badge_key text DEFAULT NULL,
  p_cta_text_key text DEFAULT NULL,
  p_circle_icon_key text DEFAULT NULL,
  p_circle_text_key text DEFAULT NULL,
  p_target_audience text DEFAULT 'all',
  p_background_image_url text DEFAULT NULL,
  p_background_gradient text DEFAULT NULL,
  p_cta_url text DEFAULT NULL,
  p_linked_product_id uuid DEFAULT NULL,
  p_is_active boolean DEFAULT true,
  p_sort_order integer DEFAULT 0
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
DECLARE
  v_id uuid;
  v_base_locale text;
  v_title_key text;
  v_subtitle_key text;
  v_badge_key text;
  v_cta_text_key text;
  v_circle_icon_key text;
  v_circle_text_key text;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  v_id := COALESCE(p_id, gen_random_uuid());
  v_base_locale := COALESCE(p_base_locale, 'en');
  v_title_key := COALESCE(p_title_key, 'hero.' || v_id || '.title');
  v_subtitle_key := COALESCE(p_subtitle_key, 'hero.' || v_id || '.subtitle');
  v_badge_key := COALESCE(p_badge_key, 'hero.' || v_id || '.badge');
  v_cta_text_key := COALESCE(p_cta_text_key, 'hero.' || v_id || '.cta_text');
  v_circle_icon_key := COALESCE(p_circle_icon_key, 'hero.' || v_id || '.circle_icon');
  v_circle_text_key := COALESCE(p_circle_text_key, 'hero.' || v_id || '.circle_text');

  INSERT INTO hero_slides (
    id,
    base_locale,
    title_key,
    subtitle_key,
    badge_key,
    cta_text_key,
    circle_icon_key,
    circle_text_key,
    target_audience,
    background_image_url, background_gradient,
    cta_url,
    linked_product_id, is_active, sort_order
  ) VALUES (
    v_id,
    v_base_locale,
    v_title_key,
    v_subtitle_key,
    v_badge_key,
    v_cta_text_key,
    v_circle_icon_key,
    v_circle_text_key,
    p_target_audience,
    p_background_image_url, p_background_gradient,
    p_cta_url,
    p_linked_product_id, p_is_active, p_sort_order
  )
  RETURNING id INTO v_id;

  PERFORM public.write_audit_journal(
      p_action_type := 'create'::public.journal_action_type,
      p_area := 'content'::public.journal_area,
      p_details := NULL,
      p_entity_id := v_id::text,
      p_entity_type := 'hero_slide',
      p_new_values := jsonb_build_object('title_key', v_title_key, 'target_audience', p_target_audience),
      p_old_values := NULL,
      p_severity := 'notice'::public.journal_severity,
      p_summary := 'Admin created hero slide',
      p_tags := ARRAY['admin', 'content', 'hero_slide', 'create'],
      p_user_id := auth.uid()
  );

  RETURN v_id;
END;
$$;

-- Permissions
REVOKE ALL ON FUNCTION public.create_hero_slide_admin(
  uuid, text, text, text, text, text, text, text,
  text, text, text, text, uuid, boolean, integer
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_hero_slide_admin(
  uuid, text, text, text, text, text, text, text,
  text, text, text, text, uuid, boolean, integer
) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_knowledge_post_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_knowledge_post_audited
-- Description: Creates a new discussion post in a knowledge topic with audit logging.
-- Security: SECURITY DEFINER - authenticated access with audit.
-- @security: authenticated
-- @audit: write_audit_journal

CREATE OR REPLACE FUNCTION public.create_knowledge_post_audited(
  p_topic_id uuid,
  p_body text,
  p_original_locale text DEFAULT 'en'
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_post_id uuid;
  v_topic_exists boolean;
BEGIN
  -- Get current user
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Validate topic exists and is not locked
  SELECT EXISTS(
    SELECT 1 FROM knowledge_topics kt
    WHERE kt.id = p_topic_id
      AND kt.is_locked IS NOT TRUE
      AND kt.visibility IN ('public', 'members')
  ) INTO v_topic_exists;

  IF NOT v_topic_exists THEN
    RAISE EXCEPTION 'Topic not found or locked';
  END IF;

  -- Validate body is not empty
  IF TRIM(p_body) = '' THEN
    RAISE EXCEPTION 'Post body cannot be empty' USING ERRCODE = '22023';
  END IF;

  -- Insert new post
  INSERT INTO knowledge_posts (
    topic_id,
    author_user_id,
    body_original,
    original_locale,
    status
  ) VALUES (
    p_topic_id,
    v_user_id,
    TRIM(p_body),
    p_original_locale,
    'visible'
  )
  RETURNING id INTO v_post_id;

  -- Write audit journal entry
  PERFORM public.write_audit_journal(
    p_action_type := 'create'::journal_action_type,
    p_area := 'content'::journal_area,
    p_details := jsonb_build_object(
      'post_id', v_post_id,
      'topic_id', p_topic_id,
      'locale', p_original_locale
    ),
    p_severity := 'info',
    p_user_id := v_user_id
  );

  RETURN v_post_id;
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.create_knowledge_post_audited(uuid, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_knowledge_post_audited(uuid, text, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_knowledge_topic.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_knowledge_topic
-- Description: Creates a new knowledge topic and its initial version.
-- Security: SECURITY DEFINER - admin only.
-- @category: ADMIN
-- @audit: true

CREATE OR REPLACE FUNCTION public.create_knowledge_topic(
  p_slug text,
  p_title_key text,
  p_summary_key text DEFAULT NULL,
  p_visibility text DEFAULT 'members',
  p_initial_locale text DEFAULT 'en',
  p_initial_title text DEFAULT '',
  p_initial_summary text DEFAULT '',
  p_initial_body text DEFAULT ''
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_topic_id uuid;
  v_version_id uuid;
BEGIN
  -- 1. Check permissions (Admin/Staff)
  IF NOT public.has_role(auth.uid(), 'admin') AND NOT public.has_role(auth.uid(), 'staff') THEN
    RAISE EXCEPTION 'Access denied. Admin or Staff role required.';
  END IF;

  -- 2. Validate input
  IF p_slug IS NULL OR length(p_slug) < 3 THEN
    RAISE EXCEPTION 'Slug is required and must be at least 3 characters.';
  END IF;

  -- 3. Insert Topic
  INSERT INTO knowledge_topics (
    slug,
    title_key,
    summary_key,
    visibility,
    source_locale,
    verification_status,
    created_at,
    updated_at
  ) VALUES (
    p_slug,
    p_title_key,
    p_summary_key,
    p_visibility,
    p_initial_locale,
    'verified', -- Admins create verified topics by default
    now(),
    now()
  )
  RETURNING id INTO v_topic_id;

  -- 4. Insert Initial Version
  INSERT INTO knowledge_topic_versions (
    topic_id,
    version_no,
    body_markdown,
    change_note,
    created_at
  ) VALUES (
    v_topic_id,
    1,
    p_initial_body,
    'Initial version created by admin',
    now()
  )
  RETURNING id INTO v_version_id;

  -- 5. Audit Log
  PERFORM public.write_audit_journal(
    p_action_type := 'create'::journal_action_type,
    p_area := 'content'::journal_area,
    p_details := jsonb_build_object(
      'topic_id', v_topic_id,
      'slug', p_slug,
      'version_id', v_version_id
    ),
    p_severity := 'info',
    p_user_id := auth.uid()
  );

  RETURN v_topic_id;
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.create_knowledge_topic(text, text, text, text, text, text, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_knowledge_topic(text, text, text, text, text, text, text, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_lab_results_from_document_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_lab_results_from_document_audited
-- Arguments: p_document_id uuid, p_test_date date, p_lab_name text, p_results jsonb, p_notes text, p_status lab_result_status
-- Description: Creates lab_results from reviewed document data. Audited.

CREATE OR REPLACE FUNCTION public.create_lab_results_from_document_audited(
  p_document_id uuid,
  p_test_date date DEFAULT NULL::date,
  p_lab_name text DEFAULT NULL::text,
  p_results jsonb DEFAULT '{}'::jsonb,
  p_notes text DEFAULT NULL::text,
  p_status lab_result_status DEFAULT 'pending'::lab_result_status
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_partner_id uuid;
  v_is_admin boolean;
  v_doc record;
  v_status lab_result_status;
  v_test_date date;
  v_lab_name text;
  v_lab_result_id uuid;
  v_reviewed_by uuid;
  v_reviewed_at timestamptz;
  v_value text;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT id, user_id, study_registration_id, document_date, category
  INTO v_doc
  FROM public.member_health_documents
  WHERE id = p_document_id;

  IF v_doc.id IS NULL THEN
    RAISE EXCEPTION 'Document not found';
  END IF;

  IF v_doc.category <> 'lab_results' THEN
    RAISE EXCEPTION 'Document category is not lab_results';
  END IF;

  v_is_admin := public.is_admin_or_staff(v_user_id);
  SELECT pp.id INTO v_partner_id FROM public.partner_profiles pp WHERE pp.user_id = v_user_id;

  IF NOT (
    v_is_admin
    OR (
      v_partner_id IS NOT NULL
      AND public.has_data_sharing_consent(v_doc.user_id, v_user_id)
      AND EXISTS (
        SELECT 1
        FROM public.document_sharing_permissions dsp
        WHERE dsp.document_id = v_doc.id
          AND dsp.revoked_at IS NULL
          AND dsp.can_view = true
          AND (
            dsp.shared_with_partner_id = v_partner_id
            OR (dsp.shared_with_study_id IS NOT NULL AND public.is_study_consultant(dsp.shared_with_study_id))
          )
      )
    )
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  v_status := COALESCE(p_status, 'pending'::lab_result_status);
  IF v_status NOT IN ('pending', 'completed', 'reviewed') THEN
    v_status := 'pending'::lab_result_status;
  END IF;

  IF v_status = 'reviewed' THEN
    v_reviewed_by := v_user_id;
    v_reviewed_at := now();
  END IF;

  v_test_date := COALESCE(p_test_date, v_doc.document_date);
  IF v_test_date IS NULL THEN
    BEGIN
      v_test_date := NULLIF(p_results->>'test_date', '')::date;
    EXCEPTION WHEN others THEN
      v_test_date := NULL;
    END;
  END IF;

  v_lab_name := COALESCE(NULLIF(p_lab_name, ''), NULLIF(p_results->>'lab_name', ''), NULLIF(p_results->>'laboratory', ''), NULLIF(p_results->>'lab', ''), 'Unknown');

  INSERT INTO public.lab_results (
    user_id,
    study_registration_id,
    document_id,
    test_date,
    lab_name,
    status,
    crp,
    esr,
    wbc,
    rbc,
    hemoglobin,
    platelets,
    glucose,
    hba1c,
    insulin,
    cholesterol_total,
    ldl,
    hdl,
    triglycerides,
    alt,
    ast,
    creatinine,
    urea,
    vitamin_d,
    vitamin_b12,
    nk_cells,
    cd4_count,
    cd8_count,
    il_4,
    il_6,
    tnf_alpha,
    nad_nadh_ratio,
    omega3_index,
    results,
    raw_data,
    notes,
    reviewed_by,
    reviewed_at
  ) VALUES (
    v_doc.user_id,
    v_doc.study_registration_id,
    v_doc.id,
    COALESCE(v_test_date, CURRENT_DATE),
    v_lab_name,
    v_status,
    NULLIF(replace(regexp_replace(p_results->>'crp', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'esr', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'wbc', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'rbc', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'hemoglobin', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'platelets', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'glucose', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'hba1c', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'insulin', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'cholesterol_total', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'ldl', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'hdl', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'triglycerides', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'alt', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'ast', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'creatinine', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'urea', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'vitamin_d', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'vitamin_b12', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'nk_cells', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'cd4_count', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'cd8_count', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'il_4', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'il_6', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'tnf_alpha', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'nad_nadh_ratio', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    NULLIF(replace(regexp_replace(p_results->>'omega3_index', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric,
    p_results,
    jsonb_build_object(
      'source', 'health_document',
      'document_id', p_document_id,
      'extracted_data', p_results
    ),
    p_notes,
    v_reviewed_by,
    v_reviewed_at
  )
  RETURNING id INTO v_lab_result_id;

  UPDATE public.member_health_documents
  SET
    verified_at = COALESCE(verified_at, now()),
    verified_by = COALESCE(verified_by, v_user_id),
    review_notes = COALESCE(p_notes, review_notes),
    updated_at = now()
  WHERE id = p_document_id;

  PERFORM public.write_audit_journal(
      p_action_type := 'create',
      p_area := 'documents',
      p_details := jsonb_build_object(
      'document_id', p_document_id,
      'status', v_status::text
    ),
      p_entity_id := v_lab_result_id::text,
      p_entity_type := 'lab_result',
      p_new_values := NULL,
      p_old_values := NULL,
      p_severity := 'info',
      p_summary := 'Lab results created from document',
      p_tags := ARRAY['phi','documents','lab_results'],
      p_user_id := v_user_id
  );

  RETURN jsonb_build_object('lab_result_id', v_lab_result_id);
END;
$function$;

