-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_order_with_items_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_order_with_items_audited
-- Arguments: p_total numeric, p_shipping_address jsonb, p_billing_address jsonb, p_product_id text, p_quantity integer, p_items jsonb, p_shipping_method text, p_packeta_branch_id integer, p_currency text, p_voucher_code text, p_payment_method text, p_carrier_id integer, p_carrier_name text
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:26:07+01:00

CREATE OR REPLACE FUNCTION public.create_order_with_items_audited(
  p_total numeric,
  p_shipping_address jsonb,
  p_billing_address jsonb,
  p_product_id text DEFAULT NULL::text,
  p_quantity integer DEFAULT 1,
  p_items jsonb DEFAULT NULL::jsonb,
  p_shipping_method text DEFAULT NULL::text,
  p_packeta_branch_id integer DEFAULT NULL::integer,
  p_currency text DEFAULT public.commerce_base_currency(),
  p_voucher_code text DEFAULT NULL::text,
  p_payment_method text DEFAULT 'bank_transfer'::text,
  p_carrier_id integer DEFAULT NULL::integer,
  p_carrier_name text DEFAULT NULL::text
)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_order_id UUID;
  v_item JSONB;
  v_product_price_base NUMERIC;
  v_item_price NUMERIC;
  v_subtotal NUMERIC := 0;
  v_shipping NUMERIC := 0;
  v_currency TEXT := upper(COALESCE(p_currency, public.commerce_base_currency()));
  v_base_currency TEXT := public.commerce_base_currency();
  v_country TEXT := NULL;
  v_voucher_id UUID;
  v_voucher_product_id UUID;
  v_voucher_discount NUMERIC := 0;
  v_voucher_applied BOOLEAN := false;
BEGIN
  -- Authorization check
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  -- Resolve base currency for product prices (system-configurable)
  SELECT COALESCE(value #>> '{}', public.commerce_base_currency())
  INTO v_base_currency
  FROM public.system_config
  WHERE key = 'commerce_base_currency'
  LIMIT 1;

  v_base_currency := upper(COALESCE(v_base_currency, public.commerce_base_currency()));
  v_country := COALESCE(p_shipping_address->>'country', 'CZ');
  v_shipping := COALESCE(public.get_shipping_cost(p_shipping_method, v_country, v_currency), 0);

  -- Validate voucher up front if provided.
  IF p_voucher_code IS NOT NULL AND length(p_voucher_code) > 0 THEN
    SELECT id, product_id
    INTO v_voucher_id, v_voucher_product_id
    FROM public.product_vouchers
    WHERE code = upper(btrim(p_voucher_code))
      AND status = 'active'
      AND (user_id IS NULL OR user_id = v_user_id)
      AND (expires_at IS NULL OR expires_at > now())
    FOR UPDATE;

    IF v_voucher_id IS NULL THEN
      RAISE EXCEPTION 'Invalid or expired voucher code' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- Create order with shipping method and packeta branch (totals set after items)
  INSERT INTO orders (
    user_id, 
    total,
    subtotal,
    shipping,
    currency,
    shipping_address, 
    billing_address, 
    status,
    shipping_method,
    packeta_branch_id,
    carrier_id,
    carrier_name
  )
  VALUES (
    v_user_id, 
    0,
    0,
    v_shipping,
    v_currency,
    p_shipping_address, 
    p_billing_address, 
    'pending',
    p_shipping_method,
    p_packeta_branch_id,
    p_carrier_id,
    p_carrier_name
  )
  RETURNING id INTO v_order_id;

  -- Insert order items from array
  IF p_items IS NOT NULL AND jsonb_array_length(p_items) > 0 THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      SELECT price INTO v_product_price_base 
      FROM products 
      WHERE id = (v_item->>'product_id')::UUID;

      v_item_price := COALESCE(
        public.convert_currency_amount(v_product_price_base, v_base_currency, v_currency),
        v_product_price_base,
        0
      );

      -- Apply voucher discount once if the matching product is in cart.
      IF v_voucher_id IS NOT NULL
         AND (v_item->>'product_id')::UUID = v_voucher_product_id
         AND NOT v_voucher_applied THEN
        v_voucher_discount := v_item_price;
        v_voucher_applied := true;
      END IF;

      v_subtotal := v_subtotal + (v_item_price * (v_item->>'quantity')::INTEGER);

      INSERT INTO order_items (order_id, product_id, quantity, price, price_at_purchase)
      VALUES (
        v_order_id, 
        (v_item->>'product_id')::UUID, 
        (v_item->>'quantity')::INTEGER, 
        COALESCE(v_product_price_base, 0),
        COALESCE(v_item_price, 0)
      );
    END LOOP;
  -- Or insert single item
  ELSIF p_product_id IS NOT NULL THEN
    SELECT price INTO v_product_price_base 
    FROM products 
    WHERE id = p_product_id::UUID;

    v_item_price := COALESCE(
      public.convert_currency_amount(v_product_price_base, v_base_currency, v_currency),
      v_product_price_base,
      0
    );

    IF v_voucher_id IS NOT NULL AND p_product_id::UUID = v_voucher_product_id THEN
      v_voucher_discount := v_item_price;
      v_voucher_applied := true;
    END IF;

    v_subtotal := v_item_price * p_quantity;
    
    INSERT INTO order_items (order_id, product_id, quantity, price, price_at_purchase)
    VALUES (
      v_order_id, 
      p_product_id::UUID, 
      p_quantity, 
      COALESCE(v_product_price_base, 0),
      COALESCE(v_item_price, 0)
    );
  END IF;

  IF p_voucher_code IS NOT NULL AND NOT v_voucher_applied THEN
    RAISE EXCEPTION 'Voucher valid but applicable product not found in cart' USING ERRCODE = 'P0002';
  END IF;

  IF v_voucher_applied THEN
    UPDATE public.product_vouchers
    SET
      status = 'used',
      used_at = now(),
      user_id = COALESCE(user_id, v_user_id),
      metadata = jsonb_set(COALESCE(metadata, '{}'::jsonb), '{order_id}', to_jsonb(v_order_id)),
      updated_at = now()
    WHERE id = v_voucher_id;
  END IF;

  -- Update totals (server-authoritative)
  UPDATE orders
  SET
    subtotal = v_subtotal,
    total = GREATEST(0, v_subtotal + v_shipping - v_voucher_discount),
    updated_at = NOW()
  WHERE id = v_order_id;

  -- Audit log
  PERFORM public.write_audit_journal(
      p_action_type := 'create'::journal_action_type,
      p_area := 'commerce'::journal_area,
      p_details := jsonb_build_object(
      'total', GREATEST(0, v_subtotal + v_shipping - v_voucher_discount),
      'subtotal', v_subtotal,
      'discount', v_voucher_discount,
      'voucher_code', p_voucher_code,
      'shipping_method', p_shipping_method,
      'has_packeta', p_packeta_branch_id IS NOT NULL,
      'carrier_id', p_carrier_id,
      'carrier_name', p_carrier_name,
      'currency', v_currency
    ),
      p_entity_id := v_order_id::TEXT,
      p_entity_type := 'order',
      p_new_values := NULL,
      p_old_values := NULL,
      p_severity := 'info'::journal_severity,
      p_summary := 'User created order' || CASE WHEN v_voucher_applied THEN ' with voucher' ELSE '' END,
      p_tags := ARRAY['order', 'commerce'],
      p_user_id := v_user_id
  );

  -- Clear cart
  DELETE FROM cart_items WHERE user_id = v_user_id;

  RETURN v_order_id;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.create_order_with_items_audited(p_total numeric, p_shipping_address jsonb, p_billing_address jsonb, p_product_id text, p_quantity integer, p_items jsonb, p_shipping_method text, p_packeta_branch_id integer, p_currency text, p_voucher_code text, p_payment_method text, p_carrier_id integer, p_carrier_name text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.create_order_with_items_audited(p_total numeric, p_shipping_address jsonb, p_billing_address jsonb, p_product_id text, p_quantity integer, p_items jsonb, p_shipping_method text, p_packeta_branch_id integer, p_currency text, p_voucher_code text, p_payment_method text, p_carrier_id integer, p_carrier_name text) FROM anon;
GRANT EXECUTE ON FUNCTION public.create_order_with_items_audited(p_total numeric, p_shipping_address jsonb, p_billing_address jsonb, p_product_id text, p_quantity integer, p_items jsonb, p_shipping_method text, p_packeta_branch_id integer, p_currency text, p_voucher_code text, p_payment_method text, p_carrier_id integer, p_carrier_name text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_product_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_product_admin
-- Arguments: p_name, p_slug, p_description, p_short_description, p_price, p_compare_at_price,
--            p_images, p_category, p_in_stock, p_stock_quantity, p_is_active, p_image_url,
--            p_name_key, p_description_key, p_short_description_key, p_target_audience, p_use_case,
--            p_base_locale, p_badge_key, p_tagline_key, p_image_alt_key, p_benefits_title_key,
--            p_composition_title_key, p_usage_title_key, p_origin_content, p_benefits_content,
--            p_substances_content, p_usage_content
-- Description: Create a product with localization keys, images, and marketing content.
-- Security: SECURITY DEFINER, admin/staff only.
-- Updated: 2026-01-24 - Added marketing content columns

CREATE OR REPLACE FUNCTION public.create_product_admin(
  p_name text,
  p_slug text,
  p_description text DEFAULT NULL,
  p_short_description text DEFAULT NULL,
  p_price numeric DEFAULT 0,
  p_compare_at_price numeric DEFAULT NULL,
  p_images jsonb DEFAULT '[]'::jsonb,
  p_category text DEFAULT NULL,
  p_in_stock boolean DEFAULT true,
  p_stock_quantity integer DEFAULT 0,
  p_doses_per_package integer DEFAULT 30,
  p_is_active boolean DEFAULT true,
  p_image_url text DEFAULT NULL,
  p_name_key text DEFAULT NULL,
  p_description_key text DEFAULT NULL,
  p_short_description_key text DEFAULT NULL,
  p_target_audience text DEFAULT NULL,
  p_use_case text DEFAULT NULL,
  -- Translation metadata
  p_base_locale text DEFAULT 'en'::text,
  -- Marketing content translation keys
  p_badge_key text DEFAULT NULL,
  p_tagline_key text DEFAULT NULL,
  p_image_alt_key text DEFAULT NULL,
  p_benefits_title_key text DEFAULT NULL,
  p_composition_title_key text DEFAULT NULL,
  p_usage_title_key text DEFAULT NULL,
  p_origin_content jsonb DEFAULT NULL,
  p_benefits_content jsonb DEFAULT NULL,
  p_substances_content jsonb DEFAULT NULL,
  p_usage_content jsonb DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_name_key text;
  v_description_key text;
  v_short_description_key text;
  v_base_locale text;
  v_badge_key text;
  v_tagline_key text;
  v_image_alt_key text;
  v_benefits_title_key text;
  v_composition_title_key text;
  v_usage_title_key text;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied: admin or staff role required';
  END IF;

  v_name_key := COALESCE(p_name_key, 'products.' || p_slug || '.name');
  v_description_key := COALESCE(p_description_key, 'products.' || p_slug || '.description');
  v_short_description_key := COALESCE(p_short_description_key, 'products.' || p_slug || '.short_description');
  v_base_locale := COALESCE(p_base_locale, 'en');
  v_badge_key := COALESCE(p_badge_key, 'products.' || p_slug || '.badge');
  v_tagline_key := COALESCE(p_tagline_key, 'products.' || p_slug || '.tagline');
  v_image_alt_key := COALESCE(p_image_alt_key, 'products.' || p_slug || '.image_alt');
  v_benefits_title_key := COALESCE(p_benefits_title_key, 'products.' || p_slug || '.benefits_title');
  v_composition_title_key := COALESCE(p_composition_title_key, 'products.' || p_slug || '.composition_title');
  v_usage_title_key := COALESCE(p_usage_title_key, 'products.' || p_slug || '.usage_title');

  INSERT INTO public.products (
    name,
    slug,
    description,
    short_description,
    price,
    compare_at_price,
    images,
    category,
    in_stock,
    stock_quantity,
    doses_per_package,
    is_active,
    image_url,
    name_key,
    description_key,
    short_description_key,
    target_audience,
    use_case,
    -- Translation metadata
    base_locale,
    -- Marketing content translation keys
    badge_key,
    tagline_key,
    image_alt_key,
    benefits_title_key,
    composition_title_key,
    usage_title_key,
    origin_content,
    benefits_content,
    substances_content,
    usage_content
  )
  VALUES (
    p_name,
    p_slug,
    p_description,
    p_short_description,
    p_price,
    p_compare_at_price,
    COALESCE((SELECT array_agg(elem::text) FROM jsonb_array_elements_text(p_images) AS elem), ARRAY[]::text[]),
    p_category,
    p_in_stock,
    p_stock_quantity,
    p_doses_per_package,
    p_is_active,
    p_image_url,
    v_name_key,
    v_description_key,
    v_short_description_key,
    p_target_audience,
    p_use_case,
    -- Translation metadata
    v_base_locale,
    -- Marketing content keys
    v_badge_key,
    v_tagline_key,
    v_image_alt_key,
    v_benefits_title_key,
    v_composition_title_key,
    v_usage_title_key,
    p_origin_content,
    p_benefits_content,
    p_substances_content,
    p_usage_content
  )
  RETURNING id INTO v_id;

  PERFORM public.write_audit_journal(
      p_action_type := 'create'::public.journal_action_type,
      p_area := 'shop'::public.journal_area,
      p_details := NULL,
      p_entity_id := v_id::text,
      p_entity_type := 'product',
      p_new_values := jsonb_build_object('slug', p_slug, 'price', p_price),
      p_old_values := NULL,
      p_severity := 'info'::public.journal_severity,
      p_summary := 'Created product: ' || p_name,
      p_tags := ARRAY['admin', 'shop', 'product', 'create'],
      p_user_id := auth.uid()
  );

  RETURN v_id;
END;
$function$;

