-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_pulse_beat_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_pulse_beat_audited
-- Arguments: p_subject_type text, p_subject_id uuid, p_beat_type text, p_due_at timestamptz,
--            p_assigned_to_user_id uuid, p_source_type text, p_source_id uuid,
--            p_note text, p_metadata jsonb
-- Description: Opens a BEAT — "subject X owes an action of type T by time D,
--              owed by person P" — and records the opening as a typed record on
--              the subject's timeline. Idempotent per (subject, kind, deadline,
--              originating regime): re-running a regime generator re-uses the
--              open beat instead of stacking duplicates.
-- Security: SECURITY DEFINER. Authorization is SUBJECT-side: operators may open
--           a beat on any twin, a member only on their own. Self-ASSIGNMENT is
--           deliberately NOT a source of authority — gating on "the addressee is
--           me" would let any caller write onto a stranger's twin simply by
--           addressing the beat to themselves (the caller-controlled-id class
--           closed in #797).

CREATE OR REPLACE FUNCTION public.create_pulse_beat_audited(
  p_subject_type text,
  p_subject_id uuid,
  p_beat_type text,
  p_due_at timestamptz,
  p_assigned_to_user_id uuid DEFAULT NULL,
  p_source_type text DEFAULT NULL,
  p_source_id uuid DEFAULT NULL,
  p_note text DEFAULT NULL,
  p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id uuid := auth.uid();
  v_is_service boolean := (auth.role() = 'service_role');
  v_beat_id uuid;
  v_entry_id uuid;
BEGIN
  IF v_caller_id IS NULL AND NOT v_is_service THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_subject_type IS NULL OR btrim(p_subject_type) = '' THEN
    RAISE EXCEPTION 'subject_type is required' USING ERRCODE = '22023';
  END IF;
  IF p_subject_id IS NULL THEN
    RAISE EXCEPTION 'subject_id is required' USING ERRCODE = '22023';
  END IF;
  IF p_beat_type IS NULL OR btrim(p_beat_type) = '' THEN
    RAISE EXCEPTION 'beat_type is required' USING ERRCODE = '22023';
  END IF;
  IF p_due_at IS NULL THEN
    RAISE EXCEPTION 'due_at is required' USING ERRCODE = '22023';
  END IF;

  -- Authorization binds the SUBJECT, never the addressee.
  IF NOT (
    v_is_service
    OR public.is_admin_or_staff()
    OR (p_subject_type = 'actor' AND p_subject_id = v_caller_id)
  ) THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  -- Existence of the subject is checked per kind. The polymorphic axis carries
  -- no FK, so an unchecked subject_id would let a beat point at nothing and
  -- surface later as a queue row nobody can resolve.
  CASE p_subject_type
    WHEN 'actor' THEN
      IF NOT EXISTS (SELECT 1 FROM aisha_auth.users u WHERE u.id = p_subject_id) THEN
        RAISE EXCEPTION 'Subject not found: actor %', p_subject_id USING ERRCODE = '22023';
      END IF;
    WHEN 'story' THEN
      IF NOT EXISTS (SELECT 1 FROM public.partner_stories ps WHERE ps.id = p_subject_id) THEN
        RAISE EXCEPTION 'Subject not found: story %', p_subject_id USING ERRCODE = '22023';
      END IF;
    ELSE
      -- Open axis by design (equipment, batch, … are implementation-seeded
      -- kinds). Operators/services only — a member may address their own twin
      -- and nothing else, which the gate above already enforces.
      NULL;
  END CASE;

  INSERT INTO public.story_pulse_beats (
    subject_type, subject_id, beat_type, status, due_at,
    assigned_to_user_id, source_type, source_id, note, metadata, created_by
  ) VALUES (
    p_subject_type, p_subject_id, p_beat_type, 'open', p_due_at,
    p_assigned_to_user_id, p_source_type, p_source_id, p_note,
    COALESCE(p_metadata, '{}'::jsonb), v_caller_id
  )
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_beat_id;

  -- Idempotence: the partial UNIQUE index already holds this exact open slot.
  IF v_beat_id IS NULL THEN
    SELECT b.id INTO v_beat_id
    FROM public.story_pulse_beats b
    WHERE b.status = 'open'
      AND b.subject_type = p_subject_type
      AND b.subject_id = p_subject_id
      AND b.beat_type = p_beat_type
      AND b.due_at = p_due_at
      AND COALESCE(b.source_type, '') = COALESCE(p_source_type, '')
      AND COALESCE(b.source_id, '00000000-0000-0000-0000-000000000000'::uuid)
          = COALESCE(p_source_id, '00000000-0000-0000-0000-000000000000'::uuid)
    LIMIT 1;
    RETURN v_beat_id;
  END IF;

  -- The opening is itself a typed record on the twin's timeline. occurred_at is
  -- NOW (when the beat was opened) and never the deadline: occurred_at means
  -- "when it happened" everywhere else in this schema, and back/forward-dating
  -- it would scramble the ordering of the whole axis.
  v_entry_id := public.append_subject_entry_service(
    p_subject_type := p_subject_type,
    p_subject_id   := p_subject_id,
    p_entry_type   := 'pulse_beat_opened',
    p_content      := p_note,
    p_metadata     := jsonb_build_object(
      'beat_id', v_beat_id,
      'beat_type', p_beat_type,
      'due_at', p_due_at,
      'assigned_to_user_id', p_assigned_to_user_id,
      'source_type', p_source_type,
      'source_id', p_source_id
    ),
    p_created_by   := v_caller_id,
    p_story_id     := CASE WHEN p_subject_type = 'story' THEN p_subject_id ELSE NULL END,
    p_is_internal  := true,
    p_occurred_at  := now()
  );

  PERFORM public.write_audit_journal(
    p_action_type := 'create'::public.journal_action_type,
    p_area        := 'system'::public.journal_area,
    p_details     := jsonb_build_object(
      'beat_id', v_beat_id,
      'subject_type', p_subject_type,
      'subject_user_id', CASE WHEN p_subject_type = 'actor' THEN p_subject_id ELSE NULL END,
      'beat_type', p_beat_type,
      'due_at', p_due_at,
      'entry_id', v_entry_id
    ),
    p_entity_id   := v_beat_id::text,
    p_entity_type := 'story_pulse_beats',
    p_severity    := 'info'::public.journal_severity,
    p_summary     := format('Pulse beat opened (%s)', p_beat_type),
    p_user_id     := v_caller_id
  );

  RETURN v_beat_id;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.create_pulse_beat_audited(text, uuid, text, timestamptz, uuid, text, uuid, text, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.create_pulse_beat_audited(text, uuid, text, timestamptz, uuid, text, uuid, text, jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.create_pulse_beat_audited(text, uuid, text, timestamptz, uuid, text, uuid, text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.create_pulse_beat_audited(text, uuid, text, timestamptz, uuid, text, uuid, text, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/audience_admin_log_touch.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: audience_admin_log_touch
-- Popis: Operátor zaznamená DOTEK se subjektem (hovor, schůzka, poznámka, …)
--   jako typový záznam na jeho ose (ADR-003: každá práce s aktérem = záznam
--   ve story). Subjekt je dvojče, účet nebo story; typ záznamu přichází z
--   katalogu instance (entry_type_definitions) — tady se ověřuje jen tvar.
--   Volitelný termín navazujícího kroku: má-li subjekt účet, založí se
--   follow-up jako BĚH (K2, audience_admin_create_followup); jinak takt na
--   dvojčeti (create_pulse_beat_audited). Vrací id záznamu.
-- Autorizace: is_admin_or_staff — operátorská obálka nad
-- append_subject_entry_service (privilegovaný zapisovač osy).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.audience_admin_log_touch(
  p_subject_type  text,
  p_subject_id    uuid,
  p_entry_type    text,
  p_content       text,
  p_occurred_at   timestamptz DEFAULT NULL,
  p_follow_up_at  timestamptz DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_entry  uuid;
  v_user   uuid;
  v_beat   uuid;
  v_story  uuid;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;
  IF p_subject_type IS NULL OR p_subject_type NOT IN ('twin', 'actor', 'story') THEN
    RAISE EXCEPTION 'subject_type must be twin, actor or story' USING ERRCODE = '22023';
  END IF;
  IF p_subject_id IS NULL THEN
    RAISE EXCEPTION 'subject_id is required' USING ERRCODE = '22023';
  END IF;
  IF p_entry_type IS NULL OR p_entry_type !~ '^[a-z][a-z0-9_-]*$' THEN
    RAISE EXCEPTION 'entry_type is required' USING ERRCODE = '22023';
  END IF;
  IF nullif(btrim(coalesce(p_content, '')), '') IS NULL THEN
    RAISE EXCEPTION 'content is required' USING ERRCODE = '22023';
  END IF;

  CASE p_subject_type
    WHEN 'twin' THEN
      IF NOT EXISTS (SELECT 1 FROM public.twin_entities t WHERE t.id = p_subject_id) THEN
        RAISE EXCEPTION 'Subject not found: twin %', p_subject_id USING ERRCODE = '22023';
      END IF;
      SELECT r.source_key::uuid INTO v_user
      FROM public.twin_external_refs r
      WHERE r.twin_id = p_subject_id AND r.ref_kind = 'account' AND r.state = 'confirmed' AND r.valid_to IS NULL
        AND r.source_key ~ '^[0-9a-fA-F-]{36}$'
      LIMIT 1;
    WHEN 'actor' THEN
      IF NOT EXISTS (SELECT 1 FROM aisha_auth.users u WHERE u.id = p_subject_id) THEN
        RAISE EXCEPTION 'Subject not found: actor %', p_subject_id USING ERRCODE = '22023';
      END IF;
      v_user := p_subject_id;
    WHEN 'story' THEN
      IF NOT EXISTS (SELECT 1 FROM public.partner_stories ps WHERE ps.id = p_subject_id) THEN
        RAISE EXCEPTION 'Subject not found: story %', p_subject_id USING ERRCODE = '22023';
      END IF;
      v_story := p_subject_id;
  END CASE;

  v_entry := public.append_subject_entry_service(
    p_subject_type := p_subject_type,
    p_subject_id   := p_subject_id,
    p_entry_type   := p_entry_type,
    p_content      := btrim(p_content),
    p_metadata     := jsonb_strip_nulls(jsonb_build_object(
                        'source', 'surface_action',
                        'follow_up_at', p_follow_up_at,
                        'logged_by', v_uid)),
    p_created_by   := v_uid,
    p_story_id     := v_story,
    p_is_internal  := false,
    p_occurred_at  := coalesce(p_occurred_at, now()));

  IF p_follow_up_at IS NOT NULL THEN
    IF v_user IS NOT NULL THEN
      v_beat := public.audience_admin_create_followup(v_user, p_follow_up_at, btrim(p_content), v_uid);
    ELSE
      v_beat := public.create_pulse_beat_audited(
        p_subject_type := p_subject_type, p_subject_id := p_subject_id,
        p_beat_type := 'follow_up', p_due_at := p_follow_up_at,
        p_assigned_to_user_id := v_uid, p_source_type := 'touch', p_source_id := v_entry,
        p_note := btrim(p_content));
    END IF;
  END IF;

  PERFORM public.audience_log_event(
    'log_touch', 'audience_admin_log_touch', p_subject_type, p_subject_id,
    format('Touch %s logged on %s', p_entry_type, p_subject_type),
    jsonb_build_object('entry_id', v_entry, 'entry_type', p_entry_type,
                       'follow_up_at', p_follow_up_at, 'beat_id', v_beat));
  RETURN v_entry;
END;
$$;

REVOKE ALL ON FUNCTION public.audience_admin_log_touch(text, uuid, text, text, timestamptz, timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.audience_admin_log_touch(text, uuid, text, text, timestamptz, timestamptz) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_question_block_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_question_block_admin
-- Description: Creates a question block with unified translation keys.
-- Security: SECURITY DEFINER, admin/staff only.

CREATE OR REPLACE FUNCTION public.create_question_block_admin(
  p_block_key text,
  p_description_key text DEFAULT NULL::text,
  p_is_active boolean DEFAULT true,
  p_question_type text DEFAULT 'textarea'::text,
  p_questions jsonb DEFAULT '[]'::jsonb,
  p_sort_order integer DEFAULT 0,
  p_text_key text DEFAULT NULL::text
)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_text_key text;
  v_description_key text;
BEGIN
  IF NOT is_admin_or_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or staff role required';
  END IF;

  v_text_key := COALESCE(p_text_key, format('questionnaires.blocks.%s.text', p_block_key));
  v_description_key := COALESCE(p_description_key, format('questionnaires.blocks.%s.description', p_block_key));

  INSERT INTO public.question_blocks (
    base_locale,
    code,
    config,
    created_by,
    description_key,
    is_active,
    is_required_default,
    question_type,
    questions,
    sort_order,
    text_key
  ) VALUES (
    'en',
    p_block_key,
    jsonb_build_object('questions', COALESCE(p_questions, '[]'::jsonb)),
    auth.uid(),
    v_description_key,
    COALESCE(p_is_active, true),
    false,
    COALESCE(p_question_type, 'textarea'),
    COALESCE(p_questions, '[]'::jsonb),
    COALESCE(p_sort_order, 0),
    v_text_key
  )
  RETURNING id INTO v_id;

  PERFORM public.write_audit_journal(
      p_action_type := 'create'::journal_action_type,
      p_area := 'research'::journal_area,
      p_entity_id := v_id::text,
      p_entity_type := 'question_block',
      p_summary := format('Created question block: %s', p_block_key),
    p_user_id := auth.uid()
  );

  RETURN v_id;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.create_question_block_admin(text, text, boolean, text, jsonb, integer, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_question_block_admin(text, text, boolean, text, jsonb, integer, text) TO authenticated;



