)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF NOT is_admin_or_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or staff role required';
  END IF;

  INSERT INTO public.questionnaires (
    base_locale,
    code,
    description_key,
    is_active,
    name,
    name_key,
    points_reward,
    questionnaire_type,
    questions,
    token_reward,
    version
  ) VALUES (
    COALESCE(p_base_locale, 'en'),
