-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_user_reminder.sql
-- -----------------------------------------------------------------------------

-- Function: public.create_user_reminder
-- Purpose: Generic create for a reminder DEFINITION (the schedule that drives
--          tracked actions). Fills a real gap — there was no generic reminder
--          CRUD, only create_story_reminder_audited for an unrelated CRM table.
--          Named user_reminder, not tracked_action: a reminder is the recurring
--          DEFINITION, distinct from the ACTION/event it later produces.
-- Access: authenticated member only (auth.uid()); SECURITY DEFINER + audit.

CREATE OR REPLACE FUNCTION public.create_user_reminder(p_title text, p_reminder_type text, p_frequency text, p_time_of_day time without time zone, p_description text DEFAULT NULL::text, p_questionnaire_id uuid DEFAULT NULL::uuid, p_product_id uuid DEFAULT NULL::uuid, p_study_registration_id uuid DEFAULT NULL::uuid, p_custom_frequency_days integer[] DEFAULT NULL::integer[], p_days_of_week integer[] DEFAULT NULL::integer[], p_quick_question text DEFAULT NULL::text, p_quick_response_type text DEFAULT NULL::text, p_points_per_completion integer DEFAULT 10, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_user_timezone text DEFAULT 'Europe/Prague'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_id uuid;
  v_targets integer;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  PERFORM enforce_rate_limit('create_user_reminder', 60000, 30);

  IF p_title IS NULL OR btrim(p_title) = '' THEN
    RAISE EXCEPTION 'title is required';
  END IF;
  IF p_reminder_type IS NULL OR btrim(p_reminder_type) = '' THEN
    RAISE EXCEPTION 'reminder_type is required';
  END IF;
  IF p_time_of_day IS NULL THEN
    RAISE EXCEPTION 'time_of_day is required';
  END IF;
  IF p_frequency IS NULL OR p_frequency NOT IN ('daily', 'weekly', 'biweekly', 'monthly', 'custom') THEN
    RAISE EXCEPTION 'invalid frequency: %', COALESCE(p_frequency, '(null)');
  END IF;
  IF p_frequency = 'custom' AND (p_custom_frequency_days IS NULL OR array_length(p_custom_frequency_days, 1) IS NULL) THEN
    RAISE EXCEPTION 'custom frequency requires custom_frequency_days';
  END IF;

  -- A reminder targets at most one of questionnaire / product / study.
  v_targets := (CASE WHEN p_questionnaire_id IS NOT NULL THEN 1 ELSE 0 END)
             + (CASE WHEN p_product_id IS NOT NULL THEN 1 ELSE 0 END)
             + (CASE WHEN p_study_registration_id IS NOT NULL THEN 1 ELSE 0 END);
  IF v_targets > 1 THEN
    RAISE EXCEPTION 'a reminder may target at most one of questionnaire/product/study';
  END IF;

  INSERT INTO user_reminders (
    user_id, title, description, reminder_type, questionnaire_id, product_id,
    study_registration_id, frequency, custom_frequency_days, time_of_day,
    days_of_week, quick_question, quick_response_type, points_per_completion,
    is_active, start_date, end_date, user_timezone
  ) VALUES (
    v_user_id, btrim(p_title), p_description, btrim(p_reminder_type), p_questionnaire_id, p_product_id,
    p_study_registration_id, p_frequency, p_custom_frequency_days, p_time_of_day,
    p_days_of_week, p_quick_question, p_quick_response_type, COALESCE(p_points_per_completion, 10),
    true, COALESCE(p_start_date, CURRENT_DATE), p_end_date, COALESCE(p_user_timezone, 'Europe/Prague')
  )
  RETURNING id INTO v_id;

  PERFORM public.write_audit_journal(
      p_action_type := 'create'::journal_action_type,
      p_area := 'member'::journal_area,
      p_details := jsonb_build_object('reminder_type', btrim(p_reminder_type), 'frequency', p_frequency),
      p_entity_id := v_id::text,
      p_entity_type := 'user_reminders',
      p_new_values := NULL,
      p_old_values := NULL,
      p_severity := 'notice'::journal_severity,
      p_summary := 'Member created a reminder',
      p_tags := ARRAY['member', 'reminder'],
      p_user_id := v_user_id
  );

  RETURN v_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.create_user_reminder(text, text, text, time without time zone, text, uuid, uuid, uuid, integer[], integer[], text, text, integer, date, date, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_user_reminder(text, text, text, time without time zone, text, uuid, uuid, uuid, integer[], integer[], text, text, integer, date, date, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/create_wearable_analysis_file_reference.sql
-- -----------------------------------------------------------------------------

-- Function: create_wearable_analysis_file_reference
-- Purpose: Store reference to wearable analysis output file for current user
-- Access: authenticated
-- Security: SECURITY DEFINER with ownership checks

CREATE OR REPLACE FUNCTION public.create_wearable_analysis_file_reference(
  p_sync_batch_id uuid,
  p_file_path text,
  p_file_name text,
  p_data_source text DEFAULT 'wearable',
  p_analysis_kind text DEFAULT 'daily_summary',
  p_file_bucket text DEFAULT 'wearable-analysis',
  p_checksum_sha256 text DEFAULT NULL,
  p_metadata jsonb DEFAULT '{}'::jsonb,
  p_user_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid;
  v_role text;
  v_file_id uuid;
  v_is_new boolean := false;
BEGIN
  v_user_id := auth.uid();
  v_role := auth.role();

  IF v_user_id IS NULL THEN
    IF v_role = 'service_role' AND p_user_id IS NOT NULL THEN
      v_user_id := p_user_id;
    ELSE
      RAISE EXCEPTION 'Not authenticated';
    END IF;
  END IF;

  IF p_sync_batch_id IS NULL THEN
    RAISE EXCEPTION 'sync_batch_id is required';
  END IF;

  IF p_file_path IS NULL OR btrim(p_file_path) = '' THEN
    RAISE EXCEPTION 'file_path is required';
  END IF;

  IF p_file_name IS NULL OR btrim(p_file_name) = '' THEN
    RAISE EXCEPTION 'file_name is required';
  END IF;

  -- Ensure the referenced sync batch belongs to the current user.
  IF NOT EXISTS (
    SELECT 1
    FROM public.health_data_sync_log hsl
    WHERE hsl.sync_batch_id = p_sync_batch_id
      AND hsl.user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'Sync batch not found for current user';
  END IF;

  INSERT INTO public.wearable_analysis_files (
    user_id,
    sync_batch_id,
    data_source,
    analysis_kind,
    file_bucket,
    file_path,
    file_name,
    checksum_sha256,
    metadata
  )
  VALUES (
    v_user_id,
    p_sync_batch_id,
    COALESCE(NULLIF(btrim(p_data_source), ''), 'wearable'),
    COALESCE(NULLIF(btrim(p_analysis_kind), ''), 'daily_summary'),
    COALESCE(NULLIF(btrim(p_file_bucket), ''), 'wearable-analysis'),
    p_file_path,
    p_file_name,
    p_checksum_sha256,
    COALESCE(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (sync_batch_id, file_path)
  DO UPDATE SET
    file_name = EXCLUDED.file_name,
    checksum_sha256 = COALESCE(EXCLUDED.checksum_sha256, wearable_analysis_files.checksum_sha256),
    metadata = wearable_analysis_files.metadata || EXCLUDED.metadata
  RETURNING id, (xmax = 0) INTO v_file_id, v_is_new;

  -- Audit without sensitive data payload.
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (
    v_user_id,
    CASE
      WHEN v_is_new THEN 'WEARABLE_ANALYSIS_REFERENCE_CREATED'
      ELSE 'WEARABLE_ANALYSIS_REFERENCE_UPDATED'
    END,
    jsonb_build_object(
      'area', 'wearable',
      'severity', 'info',
      'entity_type', 'wearable_analysis_file',
      'entity_id', v_file_id,
      'sync_batch_id', p_sync_batch_id,
      'analysis_kind', COALESCE(NULLIF(btrim(p_analysis_kind), ''), 'daily_summary')
    )
  );


  -- Audit log
  PERFORM public.write_audit_journal(
      p_action_type := 'create'::public.journal_action_type,
      p_area := 'health'::public.journal_area,
      p_details := NULL,
      p_entity_id := p_sync_batch_id::text,
      p_entity_type := 'wearable_analysis_file_reference',
      p_new_values := jsonb_build_object('sync_batch_id', p_sync_batch_id, 'file_path', p_file_path, 'data_source', p_data_source, 'analysis_kind', p_analysis_kind, 'file_bucket', p_file_bucket),
      p_old_values := NULL,
      p_severity := 'info'::public.journal_severity,
      p_summary := 'Admin created wearable analysis file reference',
      p_tags := ARRAY['admin', 'wearable_analysis_file_reference', 'create'],
      p_user_id := auth.uid()
  );

  RETURN jsonb_build_object(
    'success', true,
    'file_id', v_file_id,
    'sync_batch_id', p_sync_batch_id,
    'is_new', v_is_new
  );
END;
$$;

REVOKE ALL ON FUNCTION public.create_wearable_analysis_file_reference(uuid, text, text, text, text, text, text, jsonb, uuid) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.create_wearable_analysis_file_reference(uuid, text, text, text, text, text, text, jsonb, uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.create_wearable_analysis_file_reference(uuid, text, text, text, text, text, text, jsonb, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.create_wearable_analysis_file_reference(uuid, text, text, text, text, text, text, jsonb, uuid) TO service_role;

COMMENT ON FUNCTION public.create_wearable_analysis_file_reference(uuid, text, text, text, text, text, text, jsonb, uuid) IS
  'Creates or updates a wearable analysis output file reference for the current user sync batch.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/deactivate_user_reminder.sql
-- -----------------------------------------------------------------------------

-- Function: public.deactivate_user_reminder
-- Purpose: Soft-retire a reminder DEFINITION (is_active = false), preserving its
--          history (completions, tracked actions). Ownership-scoped to the caller.
-- Access: authenticated member only (auth.uid()); SECURITY DEFINER + audit.

CREATE OR REPLACE FUNCTION public.deactivate_user_reminder(p_reminder_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  PERFORM enforce_rate_limit('deactivate_user_reminder', 60000, 30);

  UPDATE user_reminders SET
    is_active = false,
    updated_at = now()
  WHERE id = p_reminder_id AND user_id = v_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Reminder not found or access denied';
  END IF;

  PERFORM public.write_audit_journal(
      p_action_type := 'update'::journal_action_type,
      p_area := 'member'::journal_area,
      p_details := jsonb_build_object('reminder_id', p_reminder_id, 'is_active', false),
      p_entity_id := p_reminder_id::text,
      p_entity_type := 'user_reminders',
      p_new_values := NULL,
      p_old_values := NULL,
      p_severity := 'notice'::journal_severity,
      p_summary := 'Member deactivated a reminder',
      p_tags := ARRAY['member', 'reminder'],
      p_user_id := v_user_id
  );

  RETURN true;
END;
$function$;

REVOKE ALL ON FUNCTION public.deactivate_user_reminder(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.deactivate_user_reminder(uuid) TO authenticated;


