-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/ensure_member_story_exists.sql
-- -----------------------------------------------------------------------------

-- Function: public.ensure_member_story_exists
-- Arguments: (none)
-- Description: Idempotent — returns existing story ID for the authenticated member,
--              or auto-creates a story when an eligible active registration + consented
--              partner are found. Returns NULL when no eligible setup exists.
-- Security: SECURITY DEFINER; member-only (authenticated).

CREATE OR REPLACE FUNCTION public.ensure_member_story_exists()
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id     uuid := auth.uid();
  v_story_id    uuid;
  v_partner_id  uuid;
  v_study_id    uuid;
  v_study_title text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- 1. Return existing story if any (most-recent first)
  SELECT ps.id INTO v_story_id
  FROM public.partner_stories ps
  WHERE ps.user_id = v_user_id
    AND ps.status NOT IN ('trash')
  ORDER BY ps.last_activity_at DESC
  LIMIT 1;

  IF v_story_id IS NOT NULL THEN
    RETURN v_story_id;
  END IF;

  -- 2. Find an eligible active registration with a consented partner
  SELECT
    se.study_id,
    sc.partner_id,
    s.name
  INTO
    v_study_id,
    v_partner_id,
    v_study_title
  FROM public.study_registrations se
  JOIN public.study_consultants sc
    ON sc.study_id = se.study_id
   AND sc.status = 'approved'
  JOIN public.data_sharing_consents dsc
    ON dsc.user_id        = v_user_id
   AND dsc.partner_id     = sc.partner_id
   AND dsc.revoked_at     IS NULL
   AND (dsc.expires_at IS NULL OR dsc.expires_at > now())
  JOIN public.studies s
    ON s.id = se.study_id
  WHERE se.user_id = v_user_id
    AND se.status  = 'active'
  ORDER BY se.enrolled_at DESC
  LIMIT 1;

  IF v_partner_id IS NULL THEN
    -- No eligible registration / consent — return null gracefully
    RETURN NULL;
  END IF;

  -- 3. Auto-create story (idempotent: double-checked above)
  INSERT INTO public.partner_stories (
    partner_id,
    user_id,
    study_id,
    title,
    status,
    priority
  )
  VALUES (
    v_partner_id,
    v_user_id,
    v_study_id,
    COALESCE(v_study_title, 'My Story'),
    'inbox',
    'normal'
  )
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_story_id;

  -- If conflict prevented insert, fetch the existing row
  IF v_story_id IS NULL THEN
    SELECT ps.id INTO v_story_id
    FROM public.partner_stories ps
    WHERE ps.user_id = v_user_id
      AND ps.study_id   = v_study_id
    LIMIT 1;
  END IF;

  IF v_story_id IS NOT NULL THEN
    PERFORM public.write_audit_journal(
      p_action_type := 'create'::public.journal_action_type,
      p_area        := 'member'::public.journal_area,
      p_details     := jsonb_build_object(
        'auto_created', true,
        'study_id',     v_study_id,
        'partner_id',   v_partner_id
      ),
      p_entity_id   := v_story_id,
      p_entity_type := 'partner_stories',
      p_severity    := 'notice'::public.journal_severity,
      p_summary     := 'Auto-created story for member diary access',
    p_user_id := v_user_id
  );
  END IF;

  RETURN v_story_id;
END;
$$;

-- Permissions
REVOKE ALL     ON FUNCTION public.ensure_member_story_exists() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.ensure_member_story_exists() FROM anon;
GRANT  EXECUTE ON FUNCTION public.ensure_member_story_exists() TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/fn_queue_blockchain_sync.sql
-- -----------------------------------------------------------------------------

-- Function: fn_queue_blockchain_sync
-- Trigger function for token_transactions INSERT → queue blockchain sync
-- Fires in SAME transaction as the token_transaction INSERT (transactional outbox).
--
-- GDPR filter: only 'governance' and 'aisha' token types go on-chain.
-- 'impact' and 'data' tokens are NEVER sent to blockchain (GDPR Art. 17).
--
-- Pattern: fn_queue_embedding_generation (pg_notify + pg_net + graceful degradation)
--
-- Requires app settings (optional, graceful degradation):
--   app.settings.supabase_functions_internal_url  (e.g. http://gateway:8000)
--   app.settings.supabase_service_role_key        (service role JWT)

CREATE OR REPLACE FUNCTION public.fn_queue_blockchain_sync()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_correlation_id uuid;
  v_payload jsonb;
  v_functions_url text;
  v_service_key text;
  v_request_id bigint;
  v_ledger_enabled boolean;
  v_participates boolean;
  v_anchor_on_chain boolean;
BEGIN
  -- GDPR filter: only on-chain eligible token types
  IF NEW.token_type NOT IN ('governance', 'aisha') THEN
    RETURN NEW;
  END IF;

  -- D2 opt-out DECISION POINT: the IN-DB hash-chain book (the outbox INSERT below
  -- plus the unconditional chain-link/guard triggers) is ALWAYS ON. Only NEW
  -- on-chain / personal anchoring (dispatch to the Cosmos chain) is opt-out-able,
  -- gated by BOTH the per-instance LEDGER_ENABLED flag (read as the ledger_enabled
  -- GUC, default on) AND the member's ledger_participation (default true / absent =
  -- participating). This never stops the book from recording.
  v_ledger_enabled := COALESCE(
    NULLIF(current_setting('app.settings.ledger_enabled', true), ''), 'true'
  ) NOT IN ('false', '0', 'off', 'no');

  SELECT lp.participates INTO v_participates
  FROM public.ledger_participation lp
  WHERE lp.user_id = NEW.user_id;
  v_participates := COALESCE(v_participates, true);

  v_anchor_on_chain := v_ledger_enabled AND v_participates;

  v_correlation_id := gen_random_uuid();

  -- Transactional outbox: INSERT in SAME TX as token_transaction
  -- ON CONFLICT = idempotency (duplicate trigger protection)
  INSERT INTO blockchain_audit_records (
    record_type,
    data,
    status,
    correlation_id,
    token_transaction_id,
    reference_table,
    reference_id
  ) VALUES (
    'token_sync',
    jsonb_build_object(
      'user_id', NEW.user_id,
      'amount', NEW.amount,
      'token_type', NEW.token_type,
      'transaction_type', NEW.transaction_type,
      'description', NEW.description,
      -- D2: whether this book row may be anchored on-chain (layer 2). The
      -- svc-blockchain dispatcher honours this flag before broadcasting.
      'on_chain_anchor', v_anchor_on_chain
    ),
    'queued',
    v_correlation_id,
    NEW.id,
    'token_transactions',
    NEW.id
  )
  ON CONFLICT (reference_table, reference_id) WHERE reference_id IS NOT NULL
  DO NOTHING;

  -- If ON CONFLICT hit, skip dispatch (already queued)
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  -- Audit trail — the book row was recorded regardless of the anchor decision.
  PERFORM public.write_audit_journal(
    p_action_type := 'create'::journal_action_type,
    p_area := 'blockchain'::journal_area,
    p_details := jsonb_build_object(
      'token_type', NEW.token_type,
      'correlation_id', v_correlation_id,
      'on_chain_anchor', v_anchor_on_chain
    ),
    p_entity_id := NEW.id::text,
    p_entity_type := 'token_transaction',
    p_severity := 'info'::journal_severity,
    p_summary := CASE WHEN v_anchor_on_chain
                   THEN 'Blockchain sync queued'
                   ELSE 'Ledger book recorded (on-chain anchoring opted out)' END,
    p_user_id := COALESCE(auth.uid(), NEW.user_id)
  );

  -- On-chain DISPATCH (layer 2) — skipped entirely when the instance
  -- (LEDGER_ENABLED) or the member (ledger_participation) has opted out. The book
  -- row above still exists and stays tamper-evident; only the Cosmos broadcast is
  -- suppressed.
  IF v_anchor_on_chain THEN
    -- Build notification payload
    v_payload := jsonb_build_object(
      'correlation_id', v_correlation_id,
      'token_transaction_id', NEW.id,
      'token_type', NEW.token_type,
      'triggered_at', now()
    );

    -- 1. pg_notify for external listeners (n8n, custom workers)
    PERFORM pg_notify('blockchain_sync', v_payload::text);

    -- 2. Direct edge function call via pg_net (if configured)
    BEGIN
      v_functions_url := current_setting('app.settings.supabase_functions_internal_url', true);
      v_service_key := current_setting('app.settings.supabase_service_role_key', true);

      IF v_functions_url IS NOT NULL AND v_functions_url != ''
         AND v_service_key IS NOT NULL AND v_service_key != ''
      THEN
        SELECT net.http_post(
          url     := v_functions_url || '/functions/v1/blockchain-dispatch',
          body    := v_payload,
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || v_service_key
          )
        ) INTO v_request_id;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      -- pg_net not available or HTTP call failed — pg_notify still works
      PERFORM public.write_audit_journal(
        p_action_type := 'error'::journal_action_type,
        p_area := 'blockchain'::journal_area,
        p_details := jsonb_build_object('error', SQLERRM),
        p_entity_id := NEW.id::text,
        p_entity_type := 'token_transaction',
        p_severity := 'warning'::journal_severity,
        p_summary := 'Blockchain dispatch failed',
        p_user_id := COALESCE(auth.uid(), NEW.user_id)
      );
      NULL;
    END;
  END IF;

  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION fn_queue_blockchain_sync() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_queue_blockchain_sync() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/generate_invoice_for_order.sql
-- -----------------------------------------------------------------------------

-- generate_invoice_for_order: Atomically assigns invoice number to order
CREATE OR REPLACE FUNCTION public.generate_invoice_for_order(
  p_order_id uuid,
  p_prefix text DEFAULT 'FAK'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_invoice_number text;
  v_order_status text;
  v_existing_invoice text;
BEGIN
  -- 1. Authorization: admin only
  IF NOT public.has_role(v_user_id, 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  -- 2. Check order exists and get current state
  SELECT o.status, o.invoice_number
  INTO v_order_status, v_existing_invoice
  FROM public.orders o
  WHERE o.id = p_order_id;

  IF v_order_status IS NULL THEN
    RAISE EXCEPTION 'Order not found: %', p_order_id;
  END IF;

  -- 3. If invoice already exists, return it (idempotent)
  IF v_existing_invoice IS NOT NULL THEN
    RETURN jsonb_build_object(
      'invoice_number', v_existing_invoice,
      'already_existed', true
    );
  END IF;

  -- 4. Generate next invoice number atomically
  v_invoice_number := public.generate_next_invoice_number(p_prefix);

  -- 5. Update order with invoice data
  UPDATE public.orders
  SET
    invoice_number = v_invoice_number,
    invoice_generated_at = now(),
    updated_at = now()
  WHERE id = p_order_id;

  -- 6. Audit log
  PERFORM public.write_audit_journal(
    p_action_type := 'create',
    p_area := 'admin',
    p_details := jsonb_build_object(
      'invoice_number', v_invoice_number,
      'prefix', p_prefix
    ),
    p_entity_id := p_order_id::text,
    p_entity_type := 'invoice',
    p_new_values := NULL,
    p_old_values := NULL,
    p_severity := 'notice',
    p_summary := 'Invoice generated for order',
    p_tags := ARRAY['admin', 'invoice', 'orders'],
    p_user_id := v_user_id
  );

  RETURN jsonb_build_object(
    'invoice_number', v_invoice_number,
    'already_existed', false
  );
END;
$function$;

