    tt.amount::numeric,
    tt.balance_after::numeric,
    tt.created_at::text,
    tt.description,
    tt.id,
    tt.reference_id,
    tt.reference_type,
    tt.token_type,
    tt.transaction_type,
    tt.user_id
  FROM token_transactions tt
  WHERE 
    (p_token_type IS NULL OR tt.token_type = p_token_type)
