-- -----------------------------------------------------------------------------

-- Function: get_flow_node_sensor_summary_admin
-- Returns aggregated sensor data per flow node and reading type
-- Used for monitoring dashboard to show latest sensor values per node
-- Security: SECURITY DEFINER, admin/staff only, audited

CREATE OR REPLACE FUNCTION public.get_flow_node_sensor_summary_admin(
  p_flow_node_id uuid DEFAULT NULL,
  p_hours_back integer DEFAULT 24
)
RETURNS TABLE(
  flow_node_id uuid,
  node_code text,
  node_name text,
  reading_type text,
  avg_value numeric,
  min_value numeric,
  max_value numeric,
  latest_value numeric,
  latest_unit text,
  reading_count bigint,
  latest_recorded_at timestamptz,
  has_excursion boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin_or_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or staff role required';
  END IF;

  PERFORM public.write_audit_journal(
    p_action_type := 'read'::public.journal_action_type,
    p_area := 'products'::public.journal_area,
    p_details := NULL,
    p_entity_id := p_flow_node_id,
    p_entity_type := 'production_sensor_reading',
    p_new_values := jsonb_build_object('flow_node_id', p_flow_node_id, 'hours_back', p_hours_back),
    p_old_values := NULL,
    p_severity := 'notice'::public.journal_severity,
    p_summary := 'Admin read flow node sensor summary',
    p_tags := ARRAY['admin', 'production_sensor_reading', 'flow_node_summary'],
    p_user_id := auth.uid()
  );

  RETURN QUERY
  SELECT
    pfn.id AS flow_node_id,
    pfn.node_code,
    pfn.node_name,
    psr.reading_type,
    ROUND(AVG(psr.value), 4) AS avg_value,
    MIN(psr.value) AS min_value,
    MAX(psr.value) AS max_value,
    (ARRAY_AGG(psr.value ORDER BY psr.recorded_at DESC))[1] AS latest_value,
    (ARRAY_AGG(psr.unit ORDER BY psr.recorded_at DESC))[1] AS latest_unit,
    COUNT(*)::bigint AS reading_count,
    MAX(psr.recorded_at) AS latest_recorded_at,
    BOOL_OR(psr.is_excursion) AS has_excursion
  FROM public.production_flow_nodes pfn
  INNER JOIN public.production_sensor_readings psr ON psr.flow_node_id = pfn.id
  WHERE pfn.is_active = true
    AND psr.recorded_at >= (now() - (p_hours_back || ' hours')::interval)
    AND (p_flow_node_id IS NULL OR pfn.id = p_flow_node_id)
  GROUP BY pfn.id, pfn.node_code, pfn.node_name, psr.reading_type
  ORDER BY pfn.node_code, psr.reading_type;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_flow_node_sensor_summary_admin(uuid, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_flow_node_sensor_summary_admin(uuid, integer) TO authenticated;


