)
RETURNS TABLE(
  id uuid,
  cost_element_code text,
  cost_element_name text,
  cost_group text,
  rate numeric,
  uom text,
  valid_from date,
  valid_to date,
  is_active boolean,
  notes text,
  created_at timestamptz
)
LANGUAGE plpgsql
