      p_tags := ARRAY['admin', 'studies_overview'],
      p_user_id := auth.uid()
  );

  RETURN QUERY
  SELECT
    s.id,
    s.code,
    s.name,
    s.name_key,
    s.description,
    s.description_key,
    s.study_type::text,
    s.target_condition,
    s.products,
    s.duration_weeks,
    s.target_registration,
    s.min_participants,
    s.max_participants,
    s.funding_goal,
    s.funding_deadline,
    s.funding_status::text,
    s.is_blinded,
    s.is_active,
    s.is_umbrella,
    s.starts_at,
    s.ends_at,
    s.protocol_url,
    s.current_registration,
    s.current_funding,
    s.informed_consent_version,
    s.informed_consent_special_provisions,
    s.created_at,
    s.updated_at,
    COUNT(DISTINCT se.id)::bigint AS registrations_count,
    COUNT(DISTINCT sc_contrib.id)::bigint AS contributions_count,
