-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/process_due_story_reminders.sql
-- -----------------------------------------------------------------------------

-- Function: process_due_story_reminders

CREATE OR REPLACE FUNCTION public.process_due_story_reminders()
 RETURNS TABLE(processed_count integer, processed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer := 0;
  v_reminder RECORD;
  v_notification_id uuid;
  v_link text;
BEGIN
  FOR v_reminder IN
    SELECT
      sr.id,
      sr.story_id,
      sr.partner_id,
      sr.message,
      sr.remind_at,
      ps.title AS story_title,
      ps.user_id AS story_user_id,
      pp.user_id AS partner_user_id
    FROM public.story_reminders sr
    JOIN public.partner_stories ps ON ps.id = sr.story_id
    JOIN public.partner_profiles pp ON pp.id = sr.partner_id
    WHERE sr.is_completed = false
      AND sr.remind_at <= now()
    ORDER BY sr.remind_at ASC
    FOR UPDATE OF sr SKIP LOCKED
  LOOP
    -- Build deep link to the story in partner workspace
    v_link := '/partner/storyloop?story=' || v_reminder.story_id::text;

    -- Create notification for the partner (who set the reminder)
    INSERT INTO public.notifications (user_id, type, title, message, link, metadata)
    VALUES (
      v_reminder.partner_user_id,
      'story_reminder',
      COALESCE(v_reminder.story_title, 'Story'),
      COALESCE(v_reminder.message, 'Naplánovaná připomínka'),
      v_link,
      jsonb_build_object(
        'reminder_id', v_reminder.id,
        'story_id', v_reminder.story_id,
        'remind_at', v_reminder.remind_at
      )
    )
    RETURNING id INTO v_notification_id;

    -- Mark reminder as completed
    UPDATE public.story_reminders
    SET is_completed = true, completed_at = now()
    WHERE id = v_reminder.id;

    -- Audit log (system action, no user context)
    PERFORM public.write_audit_journal(
      p_action_type := 'scheduled_task'::public.journal_action_type,
      p_area        := 'system'::public.journal_area,
      p_details     := jsonb_build_object(
        'reminder_id', v_reminder.id,
        'story_id', v_reminder.story_id,
        'notification_id', v_notification_id,
        'remind_at', v_reminder.remind_at,
        'partner_user_id', v_reminder.partner_user_id
      ),
      p_entity_id   := v_reminder.id::text,
      p_entity_type := 'story_reminders',
      p_severity    := 'info'::public.journal_severity,
      p_summary     := 'Processed due story reminder',
    p_user_id := auth.uid()
  );

    v_count := v_count + 1;
  END LOOP;

  RETURN QUERY SELECT v_count, now();
END;
$function$;

REVOKE ALL ON FUNCTION process_due_story_reminders() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION process_due_story_reminders() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/propose_production_flow_node.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: propose_production_flow_node
-- Popis: Přijme JEDEN návrh uzlu mapy toku od ingestu (flow_map_artifact,
--        kind='node') a založí ho NEAKTIVNÍ. Aktivace je lidský akt
--        v administraci — tahle funkce ji z principu neumí provést.
--
-- PROČ VZNIKLA: ingest mapu toku měří a emituje autonomně
-- (flow_map_export.py), ale artefakt neměl na platformě žádného čtenáře —
-- táž díra, jakou měl workflow_runs_artifact (vyřešena ensure_workflow_run_
-- for_subject). Chybějící sloveso, ne chybějící mašinerie.
--
-- PROČ NE upsert_production_flow_node_admin: guard má
-- `is_admin_or_staff(auth.uid())` a GRANT jen pro authenticated, takže lane
-- běžící jako service_role jím uzel nezaloží. Guard _admin funkce se
-- NEROZŠIŘUJE (návrh musí mít vlastní sloveso) — a hlavně: admin verb umí
-- `p_is_active := true`, což návrh nikdy nesmí. Tady je neaktivita VYNUCENA
-- tvarem INSERTu, ne kázní volajícího.
--
-- CO SE NIKDY NEDĚLÁ:
--   · AKTIVNÍ uzel se nikdy nemění — je to ratifikovaný provoz; nový důkaz
--     z ingestu ho nesmí přepsat ani deaktivovat (vrací already_active).
--   · Neaktivní uzel BEZ metadata.proposal (založil ho člověk ručně) se
--     nechává být (exists_unmanaged) — návrh nesmí přepsat lidskou práci.
--   · node_type se nevaliduje tady: CHECK na tabulce je jediný zdroj pravdy
--     a vadná hodnota selže nahlas per řádek (drain řádek zaloguje, bundle
--     pokračuje).
--
-- IDEMPOTENCE podle node_code (UNIQUE na tabulce): opakovaný drain téhož
-- bundle vrátí existující návrh; nový běh ingestu s čerstvějším měřením
-- návrhu OBNOVÍ důkaz (metadata.proposal.measured) — ratifikátor má vidět
-- poslední stav, ne první.
--
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (service_role + authenticated),
-- vzor ensure_workflow_run_for_subject. Audit: write_audit_journal snese
-- NULL p_user_id (systémový zápis service_role).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.propose_production_flow_node(
  p_node_code text,
  p_node_name text,
  p_node_type text  DEFAULT 'storage',
  p_measured  jsonb DEFAULT '{}'::jsonb,
  p_pair      jsonb DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id        uuid;
  v_is_active boolean;
  v_meta      jsonb;
  v_proposal  jsonb;
BEGIN
  IF NOT (public.is_admin_or_staff(auth.uid()) OR public.is_service_role()) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'admin, staff or service role required');
  END IF;

  IF coalesce(btrim(p_node_code), '') = '' OR coalesce(btrim(p_node_name), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'node_code and node_name are required');
  END IF;

  v_proposal := jsonb_build_object(
    'measured',    coalesce(p_measured, '{}'::jsonb),
    'pair',        p_pair,
    'proposed_by', 'ingest/flow_map',
    'proposed_at', now());

  SELECT id, is_active, coalesce(metadata, '{}'::jsonb)
    INTO v_id, v_is_active, v_meta
  FROM public.production_flow_nodes
  WHERE node_code = p_node_code
  LIMIT 1;

  IF v_id IS NULL THEN
    INSERT INTO public.production_flow_nodes
      (node_code, node_name, node_type, is_active, metadata, created_by)
    VALUES
      (p_node_code, p_node_name, p_node_type,
       false,  -- návrh NIKDY neaktivuje provoz — vynuceno tvarem, ne kázní
       jsonb_build_object('proposal', v_proposal),
       auth.uid())
    RETURNING id INTO v_id;

    PERFORM public.write_audit_journal(
      p_action_type := 'create'::public.journal_action_type,
      p_area        := 'products'::public.journal_area,
      p_details     := NULL,
      p_entity_id   := v_id::text,
      p_entity_type := 'production_flow_node',
      p_new_values  := jsonb_build_object('node_code', p_node_code,
                                          'node_type', p_node_type,
                                          'is_active', false),
      p_old_values  := NULL,
      p_severity    := 'notice'::public.journal_severity,
      p_summary     := format('Ingest proposed flow node %s (inactive, awaiting ratification)',
                              p_node_code),
      p_tags        := ARRAY['ingest', 'flow_tracking', 'proposal'],
      p_user_id     := auth.uid());

    RETURN jsonb_build_object('ok', true, 'node_id', v_id, 'created', true);
  END IF;

  IF v_is_active THEN
    -- Ratifikovaný provoz: důkaz z ingestu ho nemění ani nedeaktivuje.
    RETURN jsonb_build_object('ok', true, 'node_id', v_id, 'already_active', true);
  END IF;

  IF NOT (v_meta ? 'proposal') THEN
    -- Neaktivní, ale založený člověkem: návrh nesmí přepsat lidskou práci.
    RETURN jsonb_build_object('ok', true, 'node_id', v_id, 'exists_unmanaged', true);
  END IF;

  -- Neratifikovaný návrh patří celý ingestu: čerstvé měření smí obnovit
  -- i jméno a typ, ratifikátor má posuzovat poslední stav.
  --
  -- LIDSKÝ VERDIKT ALE PŘEŽIJE MĚŘENÍ. Zamítnutý návrh zůstává zamítnutý:
  -- kdyby ho refresh přepsal, každý další drain by ho vrátil do ratifikační
  -- fronty a člověk by donekonečna rozhodoval o týchž stovkách míst
  -- (fronta v get_flow_node_queue filtruje právě na NEPŘÍTOMNOST verdiktu).
  -- Důkaz se aktualizuje, rozhodnutí se dědí.
  UPDATE public.production_flow_nodes
     SET metadata   = v_meta || jsonb_build_object('proposal',
                        v_proposal || coalesce(
                          jsonb_strip_nulls(jsonb_build_object(
                            'decision',     v_meta->'proposal'->'decision',
                            'decided_by',   v_meta->'proposal'->'decided_by',
                            'decided_at',   v_meta->'proposal'->'decided_at',
                            'decided_note', v_meta->'proposal'->'decided_note')),
                          '{}'::jsonb)),
         node_name  = p_node_name,
         node_type  = p_node_type,
         updated_at = now()
   WHERE id = v_id;

  RETURN jsonb_build_object('ok', true, 'node_id', v_id, 'refreshed', true,
                            'decision', v_meta->'proposal'->>'decision');
END;
$function$;

REVOKE ALL ON FUNCTION public.propose_production_flow_node(text, text, text, jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.propose_production_flow_node(text, text, text, jsonb, jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.propose_production_flow_node(text, text, text, jsonb, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/propose_production_workflow_template.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: propose_production_workflow_template
-- Popis: Přijme CELOU mapu toku od ingestu (flow_map_artifact) a založí z ní
--        JEDNU NAVRŽENOU verzi výrobní šablony — neaktivní a nikdy výchozí.
--        Ratifikace je lidský akt v administraci; tahle funkce ji z principu
--        neumí provést.
--
-- PROČ CELOU MAPU A NE HRANU PO HRANĚ: uzel bez hran je bod bez toho, co mezi
-- ním teče, a hrana bez uzlů je šipka odnikud nikam. `propose_production_flow_node`
-- (PR #37) uzavřel jen třetinu rodiny `flow_map_proposal` — z běhu nad 36 724
-- jízdami dorazilo 435 uzlů, ale 1 665 hran a 141 podpisů pohybu nemělo
-- konzumenta. Hledat jim vlastní tabulku by ale znamenalo postavit druhý graf
-- VEDLE výroby:
--   · production_flow_records je pohyb LÁTKY (substance_id, volume_l,
--     concentration_pct — vše NOT NULL). Pozorovaný přechod A→B objem ani
--     koncentraci nemá; doplnit je = vymyslet si data.
--   · production_flow_nodes nemá pro vazbu sloupec.
--   · flowboard_graphs je uživatelsky kreslený graf a vyžaduje auth.uid().
-- Hrana tedy nemá vlastní domov a nemá ho mít. Patří DOVNITŘ návrhu procesu:
--   uzly    → workflow_steps (kroky, čím se prochází)
--   hrany   → workflow_data.transitions (přechody mezi kroky)
--   podpisy → workflow_data.movers (jakou roli hraje který stroj: rover/shuttle)
-- Tím se měření sváže s tím, co už existuje, místo aby vedle toho žilo zvlášť.
--
-- A ZAVÍRÁ TO SMYČKU: ratifikovaná šablona pohání
-- ensure_workflow_run_for_subject → production_batches →
-- production_workflow_steps → get_workflow_my_steps_block, tedy přesně to, co
-- řidič potvrzuje na pásce. Od pozorované jízdy k potvrzení v telefonu vede
-- jedna cesta, ne dvě.
--
-- PROČ NE create/update_production_workflow_template*_admin: oba mají guard
-- `is_admin_or_staff(auth.uid())`, takže lane běžící jako service_role jimi
-- nezaloží nic — a hlavně umí `is_active := true`, což návrh nikdy nesmí.
-- Guard _admin funkcí se NEROZŠIŘUJE; návrh musí mít vlastní sloveso, kde je
-- neaktivita vynucena TVAREM INSERTu, ne kázní volajícího.
--
-- CO SE NIKDY NEDĚLÁ (shodně s propose_production_flow_node):
--   · AKTIVNÍ šablona se nikdy nemění — je to ratifikovaný proces, podle
--     kterého se možná právě teď potvrzují dodávky (already_active).
--   · Neaktivní šablona BEZ metadata.proposal ve workflow_data (založil ji
--     člověk) se nechává být (exists_unmanaged) — návrh nesmí přepsat ruční práci.
--   · is_default se nenastavuje NIKDY; výchozí proces vybírá člověk.
--
-- IDEMPOTENCE podle `name` (deterministické z p_source_key): opakovaný drain
-- téhož balíčku vrátí existující návrh; čerstvější běh ingestu důkaz OBNOVÍ
-- a přidá VERZI, takže ratifikátor vidí poslední stav a zároveň historii toho,
-- jak se proces měřením vyvíjel (production_workflow_template_versions je
-- právě na to — variabilní, verzovatelné flow).
--
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT (service_role + authenticated).
-- Audit: write_audit_journal snese NULL p_user_id (systémový zápis).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.propose_production_workflow_template(
  p_source_key  text,
  p_steps       jsonb DEFAULT '[]'::jsonb,
  p_transitions jsonb DEFAULT '[]'::jsonb,
  p_movers      jsonb DEFAULT '[]'::jsonb,
  p_measured    jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_name      text;
  v_id        uuid;
  v_is_active boolean;
  v_data      jsonb;
  v_proposal  jsonb;
  v_payload   jsonb;
  v_version   integer;
BEGIN
  IF NOT (public.is_admin_or_staff(auth.uid()) OR public.is_service_role()) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'admin, staff or service role required');
  END IF;

  IF coalesce(btrim(p_source_key), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'source_key is required');
  END IF;

  -- Prázdný návrh se NEZAKLÁDÁ. Šablona bez kroků by v administraci vypadala
  -- jako hotová práce, ke které se jen nikdo nedostal — a ratifikovat by nešlo
  -- co. Mlčení o prázdné mapě je horší než odmítnutí.
  IF jsonb_typeof(p_steps) <> 'array' OR jsonb_array_length(p_steps) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'steps must be a non-empty array');
  END IF;

  v_name := 'Ingest: ' || p_source_key;

  v_proposal := jsonb_build_object(
    'measured',    coalesce(p_measured, '{}'::jsonb),
    'source_key',  p_source_key,
    'proposed_by', 'ingest/flow_map',
    'proposed_at', now());

  -- Přechody a role strojů jsou SOUČÁST návrhu procesu, ne vedlejší tabulka.
  v_payload := jsonb_build_object(
    'transitions', coalesce(p_transitions, '[]'::jsonb),
    'movers',      coalesce(p_movers, '[]'::jsonb),
    'proposal',    v_proposal);

  SELECT id, coalesce(is_active, false), coalesce(workflow_data, '{}'::jsonb)
    INTO v_id, v_is_active, v_data
  FROM public.production_workflow_templates
  WHERE name = v_name
  LIMIT 1;

  IF v_id IS NULL THEN
    INSERT INTO public.production_workflow_templates
      (name, description, steps, workflow_data, is_active, is_default, created_by)
    SELECT
      v_name,
      format('Návrh procesu z pozorování ingestu (%s kroků, %s přechodů, %s strojů) — NERATIFIKOVÁNO',
             jsonb_array_length(p_steps),
             jsonb_array_length(coalesce(p_transitions, '[]'::jsonb)),
             jsonb_array_length(coalesce(p_movers, '[]'::jsonb))),
      p_steps,
      v_payload,
      false,  -- návrh NIKDY neaktivuje proces — vynuceno tvarem, ne kázní
      false,  -- a nikdy se nestane výchozím
      auth.uid()
    RETURNING id INTO v_id;

    INSERT INTO public.production_workflow_template_versions
      (template_id, version_number, version_label, workflow_data, workflow_steps,
       change_summary, created_by)
    VALUES
      (v_id, 1, 'ingest-1', v_payload, p_steps,
       'První návrh procesu z mapy toku ingestu', auth.uid())
    RETURNING version_number INTO v_version;

    PERFORM public.write_audit_journal(
      p_action_type := 'create'::public.journal_action_type,
      p_area        := 'products'::public.journal_area,
      p_details     := NULL,
      p_entity_id   := v_id::text,
      p_entity_type := 'production_workflow_template',
      p_new_values  := jsonb_build_object('name', v_name, 'is_active', false,
                                          'steps', jsonb_array_length(p_steps)),
      p_old_values  := NULL,
      p_severity    := 'notice'::public.journal_severity,
      p_summary     := format('Ingest proposed process %s (inactive, awaiting ratification)', v_name),
      p_tags        := ARRAY['ingest', 'flow_tracking', 'proposal'],
      p_user_id     := auth.uid());

    RETURN jsonb_build_object('ok', true, 'template_id', v_id, 'created', true,
                              'version', v_version);
  END IF;

  IF v_is_active THEN
    -- Ratifikovaný proces: možná podle něj právě teď běží dodávky.
    RETURN jsonb_build_object('ok', true, 'template_id', v_id, 'already_active', true);
  END IF;

  IF NOT (v_data ? 'proposal') THEN
    -- Neaktivní, ale založená člověkem: návrh nesmí přepsat lidskou práci.
    RETURN jsonb_build_object('ok', true, 'template_id', v_id, 'exists_unmanaged', true);
  END IF;

  -- Neratifikovaný návrh patří celý ingestu. Čerstvé měření ho OBNOVÍ a přidá
  -- verzi — ratifikátor vidí poslední stav i to, jak se proces měřením vyvíjel.
  SELECT coalesce(max(version_number), 0) + 1 INTO v_version
  FROM public.production_workflow_template_versions WHERE template_id = v_id;

  UPDATE public.production_workflow_templates
     SET steps         = p_steps,
         workflow_data = v_data || v_payload,
         description   = format('Návrh procesu z pozorování ingestu (%s kroků, %s přechodů, %s strojů) — NERATIFIKOVÁNO',
                                jsonb_array_length(p_steps),
                                jsonb_array_length(coalesce(p_transitions, '[]'::jsonb)),
                                jsonb_array_length(coalesce(p_movers, '[]'::jsonb))),
         updated_at    = now()
   WHERE id = v_id;

  INSERT INTO public.production_workflow_template_versions
    (template_id, version_number, version_label, workflow_data, workflow_steps,
     change_summary, created_by)
  VALUES
    (v_id, v_version, 'ingest-' || v_version, v_payload, p_steps,
     'Obnovený návrh z čerstvějšího měření ingestu', auth.uid());

  RETURN jsonb_build_object('ok', true, 'template_id', v_id, 'refreshed', true,
                            'version', v_version);
END;
$function$;

REVOKE ALL ON FUNCTION public.propose_production_workflow_template(text, jsonb, jsonb, jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.propose_production_workflow_template(text, jsonb, jsonb, jsonb, jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.propose_production_workflow_template(text, jsonb, jsonb, jsonb, jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/rate_chat_message.sql
-- -----------------------------------------------------------------------------

-- Function: public.rate_chat_message
-- Arguments: p_message_id uuid, p_rating smallint, p_feedback text
-- Description: User rating for AI chat messages (-1, 0, 1) with optional feedback
-- Security: SECURITY DEFINER, authenticated only
-- Source: supabase/migrations/20260302100000_phase3_evaluation_system.sql

CREATE OR REPLACE FUNCTION public.rate_chat_message(
  p_message_id uuid,
  p_rating smallint,
  p_feedback text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid;
  v_conv_owner uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT cc.user_id INTO v_conv_owner
  FROM chat_messages cm
  JOIN chat_conversations cc ON cc.id = cm.conversation_id
  WHERE cm.id = p_message_id;

  IF v_conv_owner IS NULL THEN
    RAISE EXCEPTION 'Message not found';
  END IF;

  IF v_conv_owner <> v_user_id THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF p_rating NOT IN (-1, 0, 1) THEN
    RAISE EXCEPTION 'Rating must be -1, 0, or 1';
  END IF;

  UPDATE chat_messages
  SET user_rating = p_rating,
      user_feedback = p_feedback
  WHERE id = p_message_id;

  PERFORM write_audit_journal(
    p_action_type := 'update'::journal_action_type,
    p_area := 'chat'::journal_area,
    p_details := jsonb_build_object('rating', p_rating, 'has_feedback', p_feedback IS NOT NULL),
    p_entity_id := p_message_id::text,
    p_entity_type := 'chat_message',
    p_severity := 'info'::journal_severity,
    p_summary := 'User rated AI response',
    p_user_id := v_user_id
  );

  RETURN jsonb_build_object('success', true);
END;
$$;

REVOKE ALL ON FUNCTION public.rate_chat_message(uuid, smallint, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rate_chat_message(uuid, smallint, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_audit_log.sql
-- -----------------------------------------------------------------------------

-- Function: public.record_audit_log
-- Arguments: p_action text, p_resource_type text, p_resource_id text, p_user_id uuid, p_details jsonb
-- Description: Wrapper for integration audit logs (edge functions, service role).
-- Security: SECURITY DEFINER. Thin wrapper over write_audit_journal, so it inherits that
--   function's privilege: it forwards p_user_id straight through as the journal actor.
--   2026-07-15 IDOR fix (docs/security/IDOR_P_USER_ID_AUDIT_2026-07-15.md): despite the
--   "edge functions, service role" description above, it was GRANTed to `authenticated` — so it
--   was a second, unguarded door to exactly the audit-attribution forgery that revoking
--   write_audit_journal closes. Revoking only the inner function would have left this one open,
--   which is why both ship in the same commit. Its sole in-DB caller,
--   handle_order_payment_completed, is SECURITY DEFINER and runs as the owner, so it is unaffected.
--   No frontend or service code calls this RPC.

CREATE OR REPLACE FUNCTION public.record_audit_log(
  p_action text,
  p_resource_type text,
  p_resource_id text,
  p_user_id uuid DEFAULT NULL::uuid,
  p_details jsonb DEFAULT NULL::jsonb
)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_summary text;
BEGIN
  v_summary := format('Integration event: %s', p_action);

  RETURN public.write_audit_journal(
    p_action_type := 'integration'::journal_action_type,
    p_area := 'integration'::journal_area,
    p_details := jsonb_build_object(
      'action', p_action,
      'details', p_details
    ),
    p_entity_id := p_resource_id,
    p_entity_type := p_resource_type,
    p_new_values := NULL,
    p_old_values := NULL,
    p_severity := 'info'::journal_severity,
    p_summary := v_summary,
    p_tags := ARRAY['integration', 'audit'],
    p_user_id := p_user_id
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.record_audit_log(p_action text, p_resource_type text, p_resource_id text, p_user_id uuid, p_details jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.record_audit_log(p_action text, p_resource_type text, p_resource_id text, p_user_id uuid, p_details jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.record_audit_log(p_action text, p_resource_type text, p_resource_id text, p_user_id uuid, p_details jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/handle_order_payment_completed.sql
-- -----------------------------------------------------------------------------

-- Function: public.handle_order_payment_completed
-- Arguments: (none)
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:27:51+01:00

CREATE OR REPLACE FUNCTION public.handle_order_payment_completed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_auto_create JSONB;
  v_schedule_id UUID;
  v_schedule_date DATE;
BEGIN
  -- Only trigger on status change to 'paid'
  IF NEW.status = 'paid' AND (OLD.status IS NULL OR OLD.status != 'paid') THEN
    
    -- Check if auto-create is enabled
    SELECT value INTO v_auto_create
    FROM public.shipment_settings
    WHERE key = 'auto_create_packeta';
    
    -- If auto-create is enabled and shipping is not personal pickup
    IF v_auto_create->>'enabled' = 'true' AND NEW.shipping_method != 'personal_pickup' THEN
      -- Find or create today's distribution schedule
      v_schedule_date := CURRENT_DATE;
      
      SELECT id INTO v_schedule_id
      FROM public.distribution_schedule
      WHERE scheduled_date = v_schedule_date
      AND status = 'pending';
      
      IF v_schedule_id IS NULL THEN
        INSERT INTO public.distribution_schedule (scheduled_date, orders_count)
        VALUES (v_schedule_date, 1)
        RETURNING id INTO v_schedule_id;
      ELSE
        UPDATE public.distribution_schedule
        SET orders_count = orders_count + 1
        WHERE id = v_schedule_id;
      END IF;
      
      -- Add order to schedule
      INSERT INTO public.distribution_schedule_orders (schedule_id, order_id)
      VALUES (v_schedule_id, NEW.id)
      ON CONFLICT (schedule_id, order_id) DO NOTHING;
    END IF;
    
    -- Log the payment event.
    -- ⛔ p_resource_id je TEXT. Do 2026-10-04 tu šlo holé NEW.id (uuid) a uuid
    -- nemá implicitní přetypování na text — Postgres funkci nenašel a KAŽDÝ
    -- přechod objednávky na 'paid' (webhook Stripe, párování bankovní platby)
    -- spadl celý, včetně zápisu, který ho vyvolal.
    PERFORM public.record_audit_log(
      'order_paid',
      'orders',
      NEW.id::text,
      NULL,
      jsonb_build_object('total', NEW.total, 'shipping_method', NEW.shipping_method)
    );
  END IF;
  
  RETURN NEW;
END;
$function$
;

