REVOKE ALL ON FUNCTION public.handle_order_payment_completed() FROM PUBLIC;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_chain_head_anchor.sql
-- -----------------------------------------------------------------------------

-- Function: public.record_chain_head_anchor
-- Arguments: p_cosmos_tx_hash text, p_error_message text, p_head_hash text, p_rows_verified bigint, p_status text
-- Description: Persist the result of a Path-2 chain-head on-chain attestation.
--   Called by svc-blockchain's /chain-head-anchor route AFTER it reads the DB
--   chain head (fn_verify_audit_chain head_hash) and broadcasts it to the Cosmos
--   ledger as an attestation memo. Inserts one immutable row into
--   chain_head_anchors (the external tamper-evidence ledger) and writes an audit
--   journal entry. Returns the new anchor row id.
-- Security: SECURITY DEFINER, search_path pinned, service_role only (writes are
--   driven exclusively by the service route, never by end users).

CREATE OR REPLACE FUNCTION public.record_chain_head_anchor(
  p_cosmos_tx_hash text DEFAULT NULL,
  p_error_message text DEFAULT NULL,
  p_head_hash text DEFAULT NULL,
  p_rows_verified bigint DEFAULT NULL,
  p_status text DEFAULT 'confirmed'
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_anchor_id uuid;
BEGIN
  -- Least-privilege: only the service_role (the svc-blockchain route) may record
  -- an attestation. Fail loud otherwise — no silent no-op.
  IF NOT (current_setting('role', true) = 'service_role' OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Access denied: service_role required to record a chain-head anchor';
  END IF;

  IF p_head_hash IS NULL OR length(p_head_hash) = 0 THEN
    RAISE EXCEPTION 'record_chain_head_anchor: p_head_hash is required';
  END IF;

  IF p_status NOT IN ('confirmed', 'failed') THEN
    RAISE EXCEPTION 'record_chain_head_anchor: invalid status %', p_status;
  END IF;

  INSERT INTO public.chain_head_anchors (
    head_hash, rows_verified, cosmos_tx_hash, status, error_message
  ) VALUES (
    p_head_hash, p_rows_verified, p_cosmos_tx_hash, p_status, p_error_message
  )
  RETURNING id INTO v_anchor_id;

  PERFORM public.write_audit_journal(
    p_action_type := 'integration'::public.journal_action_type,
    p_area := 'blockchain'::public.journal_area,
    p_details := jsonb_build_object(
      'head_hash', p_head_hash,
      'rows_verified', p_rows_verified,
      'cosmos_tx_hash', p_cosmos_tx_hash,
      'status', p_status),
    p_entity_id := v_anchor_id::text,
    p_entity_type := 'chain_head_anchor',
    p_new_values := jsonb_build_object(
      'head_hash', p_head_hash,
      'cosmos_tx_hash', p_cosmos_tx_hash,
      'status', p_status),
    p_severity := CASE WHEN p_status = 'failed' THEN 'warning'::public.journal_severity
                       ELSE 'info'::public.journal_severity END,
    p_summary := 'Chain-head anchored on Cosmos ledger',
    p_tags := ARRAY['blockchain', 'chain_head_anchor', 'attestation']
  );

  RETURN v_anchor_id;
END;
$function$;

COMMENT ON FUNCTION public.record_chain_head_anchor(text, text, text, bigint, text) IS
  'Persists a Path-2 chain-head on-chain attestation (head_hash + Cosmos tx hash) '
  'into chain_head_anchors and writes an audit journal entry; service_role only.';

-- Permissions
REVOKE ALL ON FUNCTION public.record_chain_head_anchor(text, text, text, bigint, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_chain_head_anchor(text, text, text, bigint, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/record_tracked_action.sql
-- -----------------------------------------------------------------------------

-- Function: public.record_tracked_action
-- Purpose: Universal WRITE verb for the tracked_action surface — record that the
--          member did / reacted to something, in the same generic vocabulary the
--          read model (get_my_tracked_actions) exposes. Lands in the additive
--          tracked_actions table. Rich domain events (a dose, a check-in, a
--          reminder completion) keep their specialized writers
--          (create_dosing_log_audited / create_health_check_in /
--          complete_reminder) — this is only for actions with no thematic home.
-- Access: authenticated member only (auth.uid()); SECURITY DEFINER + audit.

CREATE OR REPLACE FUNCTION public.record_tracked_action(p_action_type text, p_payload jsonb DEFAULT '{}'::jsonb, p_reminder_id uuid DEFAULT NULL::uuid, p_occurred_at timestamptz DEFAULT NULL::timestamptz)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  IF p_action_type IS NULL OR btrim(p_action_type) = '' THEN
    RAISE EXCEPTION 'action_type is required';
  END IF;

  PERFORM enforce_rate_limit('record_tracked_action', 60000, 60);

  -- A referenced reminder must belong to the caller.
  IF p_reminder_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM user_reminders WHERE id = p_reminder_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'Reminder not found or access denied';
  END IF;

  INSERT INTO tracked_actions (user_id, action_type, occurred_at, reminder_id, payload)
  VALUES (
    v_user_id,
    btrim(p_action_type),
    COALESCE(p_occurred_at, now()),
    p_reminder_id,
    COALESCE(p_payload, '{}'::jsonb)
  )
  RETURNING id INTO v_id;

  PERFORM public.write_audit_journal(
      p_action_type := 'create'::journal_action_type,
      p_area := 'member'::journal_area,
      p_details := jsonb_build_object('action_type', btrim(p_action_type), 'reminder_id', p_reminder_id),
      p_entity_id := v_id::text,
      p_entity_type := 'tracked_actions',
      p_new_values := NULL,
      p_old_values := NULL,
      p_severity := 'notice'::journal_severity,
      p_summary := 'Member recorded a tracked action',
      p_tags := ARRAY['member', 'tracked_action'],
      p_user_id := v_user_id
  );

  RETURN v_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.record_tracked_action(text, jsonb, uuid, timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_tracked_action(text, jsonb, uuid, timestamptz) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/register_custom_node.sql
-- -----------------------------------------------------------------------------

-- Function: public.register_custom_node
-- Arguments: p_node_name text, p_display_name text, p_version text, p_description text, p_category text, p_source_request_id uuid, p_package_json jsonb, p_n8n_node_type text
-- Description: Register a new custom node in the registry after successful deployment.
-- Security: SECURITY DEFINER with search_path set.
-- Created: 2026-03-05

CREATE OR REPLACE FUNCTION public.register_custom_node(
  p_node_name text,
  p_display_name text,
  p_version text DEFAULT '0.1.0',
  p_description text DEFAULT NULL,
  p_category text DEFAULT 'aisha',
  p_source_request_id uuid DEFAULT NULL,
  p_package_json jsonb DEFAULT NULL,
  p_n8n_node_type text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_node_id uuid;
BEGIN
  -- Authorization: only admin or staff
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: only admin or staff can register custom nodes'
      USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO custom_node_registry (
    node_name,
    display_name,
    version,
    description,
    category,
    source_request_id,
    package_json,
    n8n_node_type,
    is_active,
    deployed_to_n8n
  ) VALUES (
    p_node_name,
    p_display_name,
    p_version,
    p_description,
    p_category,
    p_source_request_id,
    p_package_json,
    p_n8n_node_type,
    true,
    true
  )
  ON CONFLICT (node_name, version) DO UPDATE SET
    display_name = EXCLUDED.display_name,
    description = EXCLUDED.description,
    package_json = EXCLUDED.package_json,
    n8n_node_type = EXCLUDED.n8n_node_type,
    deployed_to_n8n = true,
    is_active = true
  RETURNING id INTO v_node_id;

  -- Audit
  PERFORM write_audit_journal(
    p_action_type := 'create'::journal_action_type,
    p_area := 'system'::journal_area,
    p_details := jsonb_build_object(
      'node_name', p_node_name,
      'version', p_version,
      'category', p_category,
      'source_request_id', p_source_request_id
    ),
    p_entity_id := v_node_id::text,
    p_entity_type := 'custom_node',
    p_severity := 'info'::journal_severity,
    p_summary := 'Custom node registered: ' || p_node_name || '@' || p_version,
    p_user_id := auth.uid()
  );

  RETURN v_node_id;
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.register_custom_node(text, text, text, text, text, uuid, jsonb, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.register_custom_node(text, text, text, text, text, uuid, jsonb, text) TO authenticated;
