-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/remove_story_participant_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.remove_story_participant_audited
-- Arguments: p_story_id uuid, p_target_user_id uuid
-- Description: Remove a participant from a story. Supports self-removal. Last owner cannot be removed.
-- Security: SECURITY DEFINER, authenticated only (owner, admin/staff, or self)
-- Source: Migration 20260329230000_story_participants_foundation.sql

CREATE OR REPLACE FUNCTION public.remove_story_participant_audited(
  p_story_id uuid,
  p_target_user_id uuid
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_is_self_removal boolean;
  v_target_role text;
  v_partner_count integer;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_is_self_removal := (v_user_id = p_target_user_id);

  -- Get target's role
  SELECT sp.role INTO v_target_role
  FROM public.story_participants sp
  WHERE sp.story_id = p_story_id AND sp.user_id = p_target_user_id;

  IF v_target_role IS NULL THEN
    RAISE EXCEPTION 'User is not a participant of this story';
  END IF;

  -- Authorization: self-removal is always allowed, otherwise need partner role or admin/staff
  IF NOT v_is_self_removal THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.story_participants sp
      WHERE sp.story_id = p_story_id AND sp.user_id = v_user_id AND sp.role = 'partner'
    ) AND NOT is_admin_or_staff() THEN
      RAISE EXCEPTION 'Unauthorized: Only story owner can remove participants';
    END IF;
  END IF;

  -- Prevent last partner removal
  IF v_target_role = 'partner' THEN
    SELECT COUNT(*) INTO v_partner_count
    FROM public.story_participants sp
    WHERE sp.story_id = p_story_id AND sp.role = 'partner';

    IF v_partner_count <= 1 THEN
      RAISE EXCEPTION 'Cannot remove the last owner of a story' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- Delete participant
  DELETE FROM public.story_participants
  WHERE story_id = p_story_id AND user_id = p_target_user_id;

  -- Audit
  PERFORM public.write_audit_journal(
    p_action_type := 'delete'::public.journal_action_type,
    p_area := 'partner'::public.journal_area,
    p_details := jsonb_build_object(
      'story_id', p_story_id,
      'target_user_id', p_target_user_id,
      'self_removal', v_is_self_removal,
      'removed_role', v_target_role
    ),
    p_entity_id := p_story_id::text,
    p_entity_type := 'story_participants',
    p_severity := 'notice'::public.journal_severity,
    p_summary := CASE
      WHEN v_is_self_removal THEN 'User left story'
      ELSE 'Removed participant from story'
    END,
    p_user_id := v_user_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'story_id', p_story_id,
    'removed_user_id', p_target_user_id,
    'self_removal', v_is_self_removal
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.remove_story_participant_audited(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.remove_story_participant_audited(uuid, uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/request_data_sharing_consent.sql
-- -----------------------------------------------------------------------------

-- Function: public.request_data_sharing_consent
-- Arguments: p_user_id uuid, p_message text
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:28:00+01:00

CREATE OR REPLACE FUNCTION public.request_data_sharing_consent(p_user_id uuid, p_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id uuid;
  v_is_assigned_partner boolean;
  v_partner_profile_id uuid;
  v_result jsonb;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Check if caller is assigned partner
  v_is_assigned_partner := EXISTS (
    SELECT 1 FROM onboarding_responses
    WHERE user_id = p_user_id AND assigned_partner_id = v_caller_id
  );

  IF NOT v_is_assigned_partner THEN
    RAISE EXCEPTION 'Access denied: You are not assigned to this user';
  END IF;

  -- Get partner_profile_id for the caller
  SELECT id INTO v_partner_profile_id
  FROM partner_profiles
  WHERE user_id = v_caller_id;

  IF v_partner_profile_id IS NULL THEN
    RAISE EXCEPTION 'Partner profile not found';
  END IF;

  -- Insert consent request (revoked_at NULL means pending/granted)
  INSERT INTO data_sharing_consents (user_id, partner_id)
  VALUES (p_user_id, v_partner_profile_id)
  ON CONFLICT (user_id, partner_id) DO NOTHING;

  -- Audit the request
  PERFORM public.write_audit_journal(
      p_action_type := 'create'::journal_action_type,
      p_area := 'partner_action'::journal_area,
      p_details := jsonb_build_object(
      'partner_id', v_caller_id,
      'user_id', p_user_id,
      -- Do NOT log free-text messages (may contain sensitive data/PII). Record only presence/size.
      'message_provided', (p_message IS NOT NULL AND length(btrim(p_message)) > 0),
      'message_length', length(coalesce(p_message, ''))
    ),
      p_entity_id := NULL,
      p_entity_type := 'data_sharing_consent',
      p_new_values := NULL,
      p_old_values := NULL,
      p_severity := 'notice',
      p_summary := 'Partner requested data sharing consent from user',
      p_tags := ARRAY['partner', 'consent', 'request'],
      p_user_id := v_caller_id
  );

  v_result := jsonb_build_object(
    'success', true,
    'message', 'Consent request sent to user'
  );

  RETURN v_result;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.request_data_sharing_consent(p_user_id uuid, p_message text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.request_data_sharing_consent(p_user_id uuid, p_message text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/reset_stale_processing.sql
-- -----------------------------------------------------------------------------

-- Function: reset_stale_processing
-- Sweeper RPC: resets records stuck in 'processing' for > p_timeout_minutes.
-- Prevents consumer crashes from permanently locking records.
-- Should be called periodically (e.g. cron every 5 min).

CREATE OR REPLACE FUNCTION public.reset_stale_processing(
  p_timeout_minutes integer DEFAULT 5
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
  v_is_service_role boolean;
BEGIN
  -- Auth check: service_role or admin/staff (called from n8n cron or admin panel)
  v_is_service_role := COALESCE(
    public.get_jwt_role() = 'service_role',
    false
  );
  IF NOT v_is_service_role AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Service role or admin/staff required'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  WITH stale AS (
    UPDATE blockchain_audit_records
    SET
      status = CASE
        WHEN retry_count >= max_attempts THEN 'exhausted'
        ELSE 'failed'
      END,
      error_message = 'Processing timeout after ' || p_timeout_minutes || ' minutes',
      next_retry_at = CASE
        WHEN retry_count >= max_attempts THEN NULL
        ELSE now() + (power(3, retry_count) * interval '1 minute')
      END,
      updated_at = now()
    WHERE status = 'processing'
      AND processing_started_at < now() - (p_timeout_minutes || ' minutes')::interval
    RETURNING id
  )
  SELECT count(*) INTO v_count FROM stale;

  IF v_count > 0 THEN
    PERFORM public.write_audit_journal(
      p_action_type := 'update'::journal_action_type,
      p_area := 'blockchain'::journal_area,
      p_details := jsonb_build_object(
        'count', v_count,
        'timeout_minutes', p_timeout_minutes
      ),
      p_entity_type := 'blockchain_audit_records',
      p_severity := 'warning'::journal_severity,
      p_summary := 'Blockchain stale processing reset',
      p_user_id := auth.uid()
    );
  END IF;

  RETURN v_count;
END;
$function$;

REVOKE ALL ON FUNCTION reset_stale_processing(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION reset_stale_processing(integer) TO service_role;
GRANT EXECUTE ON FUNCTION reset_stale_processing(integer) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/respond_to_story_block_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.respond_to_story_block_audited
-- Arguments: p_action text, p_action_data jsonb, p_entry_id uuid, p_story_id uuid
-- Description: Update metadata on a story entry for block actions (accept/decline meeting, send reminder, etc.)
-- Security: SECURITY DEFINER with search_path

CREATE OR REPLACE FUNCTION public.respond_to_story_block_audited(
  p_action text,
  p_action_data jsonb DEFAULT '{}'::jsonb,
  p_entry_id uuid DEFAULT NULL,
  p_story_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_partner_id UUID;
  v_story_partner_id UUID;
  v_story_user_id UUID;
  v_owner_mode TEXT;
  v_entry_type TEXT;
  v_current_metadata JSONB;
  v_new_metadata JSONB;
  v_result JSONB;
BEGIN
  -- 1. Authentication
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- 2. Validate required params
  IF p_entry_id IS NULL OR p_story_id IS NULL THEN
    RAISE EXCEPTION 'entry_id and story_id are required';
  END IF;

  IF p_action IS NULL OR p_action = '' THEN
    RAISE EXCEPTION 'action is required';
  END IF;

  -- 3. Authorization — verify story ownership
  v_partner_id := public.get_current_partner_id();

  SELECT ps.partner_id, ps.user_id
  INTO v_story_partner_id, v_story_user_id
  FROM public.partner_stories ps
  WHERE ps.id = p_story_id;

  IF v_story_partner_id IS NULL THEN
    RAISE EXCEPTION 'Story not found';
  END IF;

  IF v_partner_id IS NOT NULL AND v_story_partner_id = v_partner_id THEN
    v_owner_mode := 'partner';
  ELSIF v_story_user_id = v_user_id THEN
    v_owner_mode := 'member';
  ELSE
    RAISE EXCEPTION 'Unauthorized: Story access denied';
  END IF;

  -- 4. Fetch the entry and verify it belongs to the story
  SELECT se.entry_type, se.metadata
  INTO v_entry_type, v_current_metadata
  FROM public.story_entries se
  WHERE se.id = p_entry_id
    AND se.story_id = p_story_id;

  IF v_entry_type IS NULL THEN
    RAISE EXCEPTION 'Entry not found in this story';
  END IF;

  -- 5. Process action based on entry type and action
  v_new_metadata := v_current_metadata;

  CASE p_action
    -- Meeting actions (partner only)
    WHEN 'accept_meeting' THEN
      IF v_entry_type <> 'meeting_request' THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid action for entry type %s', v_entry_type), ERRCODE = '22023';
      END IF;
      v_new_metadata := v_new_metadata || jsonb_build_object(
        'status', 'accepted',
        'accepted_time', COALESCE(p_action_data->>'accepted_time', now()::text),
        'responded_by', v_user_id,
        'responded_at', now()
      );

    WHEN 'decline_meeting' THEN
      IF v_entry_type <> 'meeting_request' THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid action for entry type %s', v_entry_type), ERRCODE = '22023';
      END IF;
      v_new_metadata := v_new_metadata || jsonb_build_object(
        'status', 'declined',
        'declined_reason', COALESCE(p_action_data->>'reason', ''),
        'responded_by', v_user_id,
        'responded_at', now()
      );

    WHEN 'reschedule_meeting' THEN
      IF v_entry_type <> 'meeting_request' THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid action for entry type %s', v_entry_type), ERRCODE = '22023';
      END IF;
      v_new_metadata := v_new_metadata || jsonb_build_object(
        'status', 'rescheduled',
        'responded_by', v_user_id,
        'responded_at', now()
      );

    -- Questionnaire reminder (partner only)
    WHEN 'send_questionnaire_reminder' THEN
      IF v_entry_type <> 'questionnaire_request' THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid action for entry type %s', v_entry_type), ERRCODE = '22023';
      END IF;
      IF v_owner_mode <> 'partner' THEN
        RAISE EXCEPTION 'Unauthorized: Only partner can send reminders';
      END IF;
      v_new_metadata := v_new_metadata || jsonb_build_object(
        'reminder_sent', true,
        'reminder_sent_at', now(),
        'reminder_sent_by', v_user_id
      );

    -- Consent resend (partner only)
    WHEN 'resend_consent_request' THEN
      IF v_entry_type <> 'consent_request' THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid action for entry type %s', v_entry_type), ERRCODE = '22023';
      END IF;
      IF v_owner_mode <> 'partner' THEN
        RAISE EXCEPTION 'Unauthorized: Only partner can resend consent';
      END IF;
      v_new_metadata := v_new_metadata || jsonb_build_object(
        'last_resent_at', now(),
        'resent_by', v_user_id,
        'resent_count', COALESCE((v_current_metadata->>'resent_count')::int, 0) + 1
      );

    -- Flowboard consent-gate approval: the run owner approves a halted gate so the (stateless)
    -- executor reads metadata.flowboard.status='approved' on a resume re-invoke and continues past
    -- the gate. Story-access (member/partner) is already verified above; no extra owner restriction
    -- (the run owner reviews their own automation before a sensitive step). Distinct from the
    -- clinical consent_request block (metadata.type), which has no metadata.flowboard.kind.
    WHEN 'approve_flow_gate' THEN
      IF v_entry_type <> 'consent_request' THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid action for entry type %s', v_entry_type), ERRCODE = '22023';
      END IF;
      IF v_current_metadata->'flowboard'->>'kind' IS DISTINCT FROM 'consent_request' THEN
        RAISE EXCEPTION USING MESSAGE = 'approve_flow_gate applies only to a Flowboard consent gate', ERRCODE = '22023';
      END IF;
      v_new_metadata := jsonb_set(
        v_new_metadata,
        '{flowboard}',
        COALESCE(v_new_metadata->'flowboard', '{}'::jsonb) || jsonb_build_object(
          'status', 'approved',
          'approved_by', v_user_id,
          'approved_at', now()
        )
      );

    -- Repricing decision: the responsible person confirms/rejects a reprice IN the story
    -- (the human gate the user described). Like the Flowboard gate, this only STAMPS the
    -- entry; a fork-additive trigger reflects metadata.reprice.status into the
    -- hub_reprice_proposal projection (executor-reads-stamp). Story access already verified
    -- above, so authorization is story ownership/participation — not a global role.
    WHEN 'confirm_reprice' THEN
      IF v_entry_type <> 'reprice_proposal' THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid action for entry type %s', v_entry_type), ERRCODE = '22023';
      END IF;
      v_new_metadata := jsonb_set(
        v_new_metadata, '{reprice}',
        COALESCE(v_new_metadata->'reprice', '{}'::jsonb) || jsonb_build_object(
          'status', 'confirmed', 'responded_by', v_user_id, 'responded_at', now()));

    WHEN 'reject_reprice' THEN
      IF v_entry_type <> 'reprice_proposal' THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid action for entry type %s', v_entry_type), ERRCODE = '22023';
      END IF;
      v_new_metadata := jsonb_set(
        v_new_metadata, '{reprice}',
        COALESCE(v_new_metadata->'reprice', '{}'::jsonb) || jsonb_build_object(
          'status', 'rejected', 'responded_by', v_user_id, 'responded_at', now(),
          'reject_reason', COALESCE(p_action_data->>'reason', '')));

    ELSE
      RAISE EXCEPTION 'Unknown action: %', p_action;
  END CASE;

  -- 6. Update entry metadata
  UPDATE public.story_entries
  SET metadata = v_new_metadata
  WHERE id = p_entry_id
    AND story_id = p_story_id;

  -- 7. Update story last_activity
  UPDATE public.partner_stories
  SET last_activity_at = now()
  WHERE id = p_story_id;

  -- 8. Build result
  v_result := jsonb_build_object(
    'success', true,
    'action', p_action,
    'entry_id', p_entry_id,
    'updated_metadata', v_new_metadata
  );

  -- 9. Audit log (no sensitive data)
  PERFORM public.write_audit_journal(
    p_action_type := 'update'::public.journal_action_type,
    p_area := CASE
      WHEN v_owner_mode = 'partner' THEN 'partner'::public.journal_area
      ELSE 'member'::public.journal_area
    END,
    p_details := jsonb_build_object(
      'owner_mode', v_owner_mode,
      'story_id', p_story_id,
      'entry_id', p_entry_id,
      'entry_type', v_entry_type,
      'action', p_action
    ),
    p_entity_id := p_entry_id::text,
    p_entity_type := 'story_entries',
    p_severity := 'info'::public.journal_severity,
    p_summary := format('Block action: %s on %s', p_action, v_entry_type),
    p_user_id := v_user_id
  );

  RETURN v_result;
END;
$function$
;

COMMENT ON FUNCTION public.respond_to_story_block_audited(text, jsonb, uuid, uuid) IS
'Processes block actions (accept/decline meeting, send reminder, resend consent, approve flowboard gate, confirm/reject reprice) on story entries. Audited.';

