-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/restore_production_workflow_template_version_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.restore_production_workflow_template_version_admin
-- Arguments: p_template_id uuid, p_version_number integer
-- Description: Restore template to a specific version. Creates a new version from old data (non-destructive).
-- Security: SECURITY DEFINER, admin/staff only
-- Source: Migration 20260219180000_production_enhancements.sql

CREATE OR REPLACE FUNCTION public.restore_production_workflow_template_version_admin(
  p_template_id uuid DEFAULT NULL,
  p_version_number integer DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_data jsonb;
  v_steps jsonb;
  v_next_version integer;
BEGIN
  IF NOT public.is_admin_or_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or staff role required';
  END IF;

  -- Get version data
  SELECT v.workflow_data, v.workflow_steps INTO v_data, v_steps
  FROM production_workflow_template_versions v
  WHERE v.template_id = p_template_id AND v.version_number = p_version_number;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Version % not found for template %', p_version_number, p_template_id;
  END IF;

  -- Create a new version (restore is not overwrite — it's a new version from old data)
  SELECT COALESCE(MAX(version_number), 0) + 1 INTO v_next_version
  FROM production_workflow_template_versions
  WHERE template_id = p_template_id;

  INSERT INTO production_workflow_template_versions (
    template_id, version_number, version_label,
    workflow_data, workflow_steps,
    change_summary, created_by
  ) VALUES (
    p_template_id, v_next_version,
    'v' || v_next_version || ' (restored from v' || p_version_number || ')',
    v_data, v_steps,
    format('Restored from version %s', p_version_number),
    auth.uid()
  );

  UPDATE production_workflow_templates
  SET
    workflow_data = v_data,
    workflow_steps = v_steps,
    current_version_number = v_next_version,
    updated_at = now()
  WHERE id = p_template_id;

  PERFORM public.write_audit_journal(
    p_action_type := 'update'::public.journal_action_type,
    p_area := 'production'::public.journal_area,
    p_details := NULL,
    p_entity_id := p_template_id::text,
    p_entity_type := 'production_workflow_template',
    p_new_values := jsonb_build_object(
      'restored_from_version', p_version_number,
      'new_version', v_next_version
    ),
    p_old_values := NULL,
    p_severity := 'info'::public.journal_severity,
    p_summary := format('Template restored from version %s to v%s', p_version_number, v_next_version),
    p_tags := ARRAY['admin', 'workflow_template', 'version_restore'],
    p_user_id := auth.uid()
  );

  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION public.restore_production_workflow_template_version_admin(uuid, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.restore_production_workflow_template_version_admin(uuid, integer) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/reveal_hippocampus_content_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.reveal_hippocampus_content_audited
-- Description: Returns the full (unmasked) content of a hippocampus
--   memory row. Every reveal is recorded in audit_journal with action
--   'access' + tag 'pii_reveal' so reveals are forensically traceable.
-- Security: SECURITY DEFINER. Admin/staff only — participants can see
--   masked preview via list_hippocampus_signals; full reveal is an
--   admin-only operation.

CREATE OR REPLACE FUNCTION public.reveal_hippocampus_content_audited(
  p_memory_id uuid,
  p_reason    text DEFAULT NULL
)
RETURNS TABLE (
  memory_id    uuid,
  agent_slug   text,
  memory_type  text,
  content      text,
  importance   int,
  expires_at   timestamptz,
  created_at   timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_agent_slug text;
BEGIN
  IF v_user_id IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_admin_or_staff(v_user_id) THEN
    RAISE EXCEPTION 'Admin or staff role required for hippocampus content reveal'
      USING ERRCODE = '42501';
  END IF;

  SELECT am.agent_slug INTO v_agent_slug
  FROM public.agent_memories am
  WHERE am.id = p_memory_id;

  IF v_agent_slug IS NULL THEN
    RAISE EXCEPTION 'Memory not found: %', p_memory_id USING ERRCODE = 'P0002';
  END IF;

  IF v_agent_slug NOT LIKE 'hippocampus:%' THEN
    RAISE EXCEPTION 'Memory % is not a hippocampus signal (agent_slug=%)',
      p_memory_id, v_agent_slug USING ERRCODE = '22023';
  END IF;

  PERFORM public.write_audit_journal(
    p_action_type := 'access'::public.journal_action_type,
    p_area        := 'admin'::public.journal_area,
    p_details     := jsonb_build_object(
      'memory_id', p_memory_id,
      'agent_slug', v_agent_slug,
      'reason', COALESCE(p_reason, '(no reason provided)')
    ),
    p_entity_id   := p_memory_id::text,
    p_entity_type := 'agent_memories',
    p_new_values  := NULL,
    p_old_values  := NULL,
    p_severity    := 'notice'::public.journal_severity,
    p_summary     := format(
      'Hippocampus content reveal — memory_id=%s, agent=%s',
      p_memory_id, v_agent_slug
    ),
    p_tags        := ARRAY['pii_reveal', 'hippocampus'],
    p_user_id     := v_user_id
  );

  RETURN QUERY
  SELECT am.id, am.agent_slug, am.memory_type, am.content,
         am.importance, am.expires_at, am.created_at
  FROM public.agent_memories am
  WHERE am.id = p_memory_id;
END;
$$;

REVOKE ALL ON FUNCTION public.reveal_hippocampus_content_audited(uuid, text)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.reveal_hippocampus_content_audited(uuid, text)
  TO authenticated;
GRANT EXECUTE ON FUNCTION public.reveal_hippocampus_content_audited(uuid, text)
  TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/review_lab_results_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.review_lab_results_audited
-- Arguments: p_lab_result_id uuid, p_status lab_result_status, p_notes text, p_results jsonb
-- Description: Reviews or updates lab results with permissions. Audited.

CREATE OR REPLACE FUNCTION public.review_lab_results_audited(
  p_lab_result_id uuid,
  p_status lab_result_status DEFAULT 'reviewed'::lab_result_status,
  p_notes text DEFAULT NULL::text,
  p_results jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_partner_id uuid;
  v_is_admin boolean;
  v_lab record;
  v_status lab_result_status;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT l.id, l.user_id, l.document_id
  INTO v_lab
  FROM public.lab_results l
  WHERE l.id = p_lab_result_id;

  IF v_lab.id IS NULL THEN
    RAISE EXCEPTION 'Lab result not found';
  END IF;

  v_is_admin := public.is_admin_or_staff(v_user_id);
  SELECT pp.id INTO v_partner_id FROM public.partner_profiles pp WHERE pp.user_id = v_user_id;

  IF NOT (
    v_is_admin
    OR (
      v_partner_id IS NOT NULL
      AND public.has_data_sharing_consent(v_lab.user_id, v_user_id)
      AND EXISTS (
        SELECT 1
        FROM public.document_sharing_permissions dsp
        WHERE dsp.document_id = v_lab.document_id
          AND dsp.revoked_at IS NULL
          AND dsp.can_view = true
          AND (
            dsp.shared_with_partner_id = v_partner_id
            OR (dsp.shared_with_study_id IS NOT NULL AND public.is_study_consultant(dsp.shared_with_study_id))
          )
      )
    )
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  v_status := COALESCE(p_status, 'reviewed'::lab_result_status);
  IF v_status NOT IN ('pending', 'completed', 'reviewed') THEN
    v_status := 'reviewed'::lab_result_status;
  END IF;

  UPDATE public.lab_results
  SET
    status = v_status,
    reviewed_by = CASE WHEN v_status = 'reviewed' THEN v_user_id ELSE reviewed_by END,
    reviewed_at = CASE WHEN v_status = 'reviewed' THEN now() ELSE reviewed_at END,
    notes = COALESCE(p_notes, notes),
    crp = COALESCE(NULLIF(replace(regexp_replace(p_results->>'crp', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, crp),
    esr = COALESCE(NULLIF(replace(regexp_replace(p_results->>'esr', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, esr),
    wbc = COALESCE(NULLIF(replace(regexp_replace(p_results->>'wbc', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, wbc),
    rbc = COALESCE(NULLIF(replace(regexp_replace(p_results->>'rbc', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, rbc),
    hemoglobin = COALESCE(NULLIF(replace(regexp_replace(p_results->>'hemoglobin', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, hemoglobin),
    platelets = COALESCE(NULLIF(replace(regexp_replace(p_results->>'platelets', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, platelets),
    glucose = COALESCE(NULLIF(replace(regexp_replace(p_results->>'glucose', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, glucose),
    hba1c = COALESCE(NULLIF(replace(regexp_replace(p_results->>'hba1c', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, hba1c),
    insulin = COALESCE(NULLIF(replace(regexp_replace(p_results->>'insulin', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, insulin),
    cholesterol_total = COALESCE(NULLIF(replace(regexp_replace(p_results->>'cholesterol_total', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, cholesterol_total),
    ldl = COALESCE(NULLIF(replace(regexp_replace(p_results->>'ldl', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, ldl),
    hdl = COALESCE(NULLIF(replace(regexp_replace(p_results->>'hdl', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, hdl),
    triglycerides = COALESCE(NULLIF(replace(regexp_replace(p_results->>'triglycerides', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, triglycerides),
    alt = COALESCE(NULLIF(replace(regexp_replace(p_results->>'alt', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, alt),
    ast = COALESCE(NULLIF(replace(regexp_replace(p_results->>'ast', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, ast),
    creatinine = COALESCE(NULLIF(replace(regexp_replace(p_results->>'creatinine', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, creatinine),
    urea = COALESCE(NULLIF(replace(regexp_replace(p_results->>'urea', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, urea),
    vitamin_d = COALESCE(NULLIF(replace(regexp_replace(p_results->>'vitamin_d', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, vitamin_d),
    vitamin_b12 = COALESCE(NULLIF(replace(regexp_replace(p_results->>'vitamin_b12', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, vitamin_b12),
    nk_cells = COALESCE(NULLIF(replace(regexp_replace(p_results->>'nk_cells', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, nk_cells),
    cd4_count = COALESCE(NULLIF(replace(regexp_replace(p_results->>'cd4_count', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, cd4_count),
    cd8_count = COALESCE(NULLIF(replace(regexp_replace(p_results->>'cd8_count', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, cd8_count),
    il_4 = COALESCE(NULLIF(replace(regexp_replace(p_results->>'il_4', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, il_4),
    il_6 = COALESCE(NULLIF(replace(regexp_replace(p_results->>'il_6', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, il_6),
    tnf_alpha = COALESCE(NULLIF(replace(regexp_replace(p_results->>'tnf_alpha', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, tnf_alpha),
    nad_nadh_ratio = COALESCE(NULLIF(replace(regexp_replace(p_results->>'nad_nadh_ratio', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, nad_nadh_ratio),
    omega3_index = COALESCE(NULLIF(replace(regexp_replace(p_results->>'omega3_index', '[^0-9,.-]', '', 'g'), ',', '.'), '')::numeric, omega3_index),
    raw_data = CASE WHEN p_results IS NULL THEN raw_data ELSE jsonb_set(COALESCE(raw_data, '{}'::jsonb), '{reviewed_values}', p_results, true) END,
    updated_at = now()
  WHERE id = p_lab_result_id;

  PERFORM public.write_audit_journal(
      p_action_type := 'update',
      p_area := 'documents',
      p_details := jsonb_build_object('status', v_status::text),
      p_entity_id := p_lab_result_id::text,
      p_entity_type := 'lab_result',
      p_new_values := NULL,
      p_old_values := NULL,
      p_severity := 'info',
      p_summary := 'Lab result reviewed',
      p_tags := ARRAY['phi','documents','lab_results','review'],
      p_user_id := v_user_id
  );

  RETURN jsonb_build_object('success', true);
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.review_lab_results_audited(uuid, lab_result_status, text, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.review_lab_results_audited(uuid, lab_result_status, text, jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.review_lab_results_audited(uuid, lab_result_status, text, jsonb) TO authenticated;


