  'seed) or admin/staff. Feeds get_web_page_by_slug(slug, hostname) multi-site routing.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_agent_knowledge_binding_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.set_agent_knowledge_binding_audited
-- Description: Idempotent upsert for an agent ↔ expert_rule binding.
--   Creates a new row when no active matching binding exists, otherwise
--   updates priority / version / notes / is_active in place. Writes an
--   audit_journal entry on every mutation (action_type='update'/'create').
-- Security: SECURITY DEFINER. Admin/staff only.

CREATE OR REPLACE FUNCTION public.set_agent_knowledge_binding_audited(
  p_agent_slug        text,
  p_knowledge_item_id uuid,
  p_binding_type      text DEFAULT 'rule',
  p_priority          int  DEFAULT 100,
  p_version           int  DEFAULT NULL,
  p_is_active         boolean DEFAULT true,
  p_story_id          uuid DEFAULT NULL,
  p_notes             text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id   uuid := auth.uid();
  v_binding_id uuid;
  v_existing_id uuid;
  v_existing_priority int;
  v_existing_version int;
  v_existing_notes text;
  v_existing_active boolean;
  v_action_type public.journal_action_type;
BEGIN
  IF v_user_id IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_admin_or_staff(v_user_id) THEN
    RAISE EXCEPTION 'Admin or staff role required to manage bindings'
      USING ERRCODE = '42501';
  END IF;

  -- Validate FK: expert_rules row must exist.
  IF NOT EXISTS (SELECT 1 FROM public.expert_rules WHERE id = p_knowledge_item_id) THEN
    RAISE EXCEPTION 'Expert rule not found: %', p_knowledge_item_id
      USING ERRCODE = 'P0002';
  END IF;

  -- Validate story FK when scoped (NULL = global, always OK).
  IF p_story_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.partner_stories WHERE id = p_story_id)
  THEN
    RAISE EXCEPTION 'Story not found: %', p_story_id USING ERRCODE = 'P0002';
  END IF;

  -- Look for an existing matching binding (active or inactive).
  SELECT akb.id, akb.priority, akb.version, akb.notes, akb.is_active
    INTO v_existing_id, v_existing_priority, v_existing_version,
         v_existing_notes, v_existing_active
  FROM public.agent_knowledge_bindings akb
  WHERE akb.agent_slug         = p_agent_slug
    AND akb.knowledge_item_id  = p_knowledge_item_id
    AND akb.binding_type       = p_binding_type
    AND akb.story_id IS NOT DISTINCT FROM p_story_id
  ORDER BY akb.is_active DESC, akb.updated_at DESC
  LIMIT 1;

  IF v_existing_id IS NULL THEN
    INSERT INTO public.agent_knowledge_bindings (
      agent_slug, knowledge_item_id, binding_type, priority,
      version, is_active, story_id, notes, created_by
    ) VALUES (
      p_agent_slug, p_knowledge_item_id, p_binding_type, p_priority,
      p_version, p_is_active, p_story_id, p_notes, v_user_id
    )
    RETURNING id INTO v_binding_id;
    v_action_type := 'create'::public.journal_action_type;
  ELSE
    UPDATE public.agent_knowledge_bindings
       SET priority   = p_priority,
           version    = p_version,
           is_active  = p_is_active,
           notes      = p_notes,
           updated_at = now()
     WHERE id = v_existing_id
    RETURNING id INTO v_binding_id;
    v_action_type := 'update'::public.journal_action_type;
  END IF;

  PERFORM public.write_audit_journal(
    p_action_type := v_action_type,
    p_area        := 'admin'::public.journal_area,
    p_details     := jsonb_build_object(
      'agent_slug',        p_agent_slug,
      'knowledge_item_id', p_knowledge_item_id,
      'binding_type',      p_binding_type,
      'priority',          p_priority,
      'version',           p_version,
      'is_active',         p_is_active,
      'story_id',          p_story_id
    ),
    p_entity_id   := v_binding_id::text,
    p_entity_type := 'agent_knowledge_bindings',
    p_new_values  := jsonb_build_object(
      'priority',   p_priority,
      'is_active',  p_is_active,
      'notes',      p_notes
    ),
    p_old_values  := CASE
      WHEN v_existing_id IS NULL THEN NULL
      ELSE jsonb_build_object(
        'priority',  v_existing_priority,
        'is_active', v_existing_active,
        'notes',     v_existing_notes
      )
    END,
    p_severity    := 'info'::public.journal_severity,
    p_summary     := format(
      '%s agent_knowledge_binding (%s ↔ %s, %s)',
      CASE WHEN v_existing_id IS NULL THEN 'Created' ELSE 'Updated' END,
      p_agent_slug, p_knowledge_item_id, p_binding_type
    ),
    p_user_id     := v_user_id
  );

  RETURN v_binding_id;
END;
$$;

REVOKE ALL ON FUNCTION public.set_agent_knowledge_binding_audited(
  text, uuid, text, int, int, boolean, uuid, text
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_agent_knowledge_binding_audited(
  text, uuid, text, int, int, boolean, uuid, text
) TO authenticated;
GRANT EXECUTE ON FUNCTION public.set_agent_knowledge_binding_audited(
  text, uuid, text, int, int, boolean, uuid, text
) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_health_document_processing_status_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.set_health_document_processing_status_audited
-- Arguments: p_document_id uuid, p_status document_processing_status, p_reason text
-- Description: Updates processing status for a health document (owner only). Audited.

CREATE OR REPLACE FUNCTION public.set_health_document_processing_status_audited(
  p_document_id uuid,
  p_status document_processing_status,
  p_reason text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_doc record;
  v_processed_at timestamptz;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT id, user_id, processing_status
  INTO v_doc
  FROM public.member_health_documents
  WHERE id = p_document_id;

  IF v_doc.id IS NULL OR v_doc.user_id <> v_user_id THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF p_status IN ('completed', 'failed') THEN
    v_processed_at := now();
  ELSE
    v_processed_at := NULL;
  END IF;

  UPDATE public.member_health_documents
  SET
    processing_status = p_status,
    processed_at = v_processed_at,
    updated_at = now()
  WHERE id = p_document_id;

  PERFORM public.write_audit_journal(
      p_action_type := 'update',
      p_area := 'documents',
      p_details := jsonb_build_object(
      'previous_status', v_doc.processing_status::text,
      'status', p_status::text,
      'reason', NULLIF(p_reason, '')
    ),
      p_entity_id := p_document_id::text,
      p_entity_type := 'member_health_document',
      p_new_values := NULL,
      p_old_values := NULL,
      p_severity := 'info',
      p_summary := 'Health document processing status updated',
      p_tags := ARRAY['phi','documents','analysis'],
      p_user_id := v_user_id
  );

  RETURN jsonb_build_object('success', true, 'status', p_status::text);
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.set_health_document_processing_status_audited(uuid, document_processing_status, text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.set_health_document_processing_status_audited(uuid, document_processing_status, text) FROM anon;
GRANT EXECUTE ON FUNCTION public.set_health_document_processing_status_audited(uuid, document_processing_status, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/set_memory_governance_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.set_memory_governance_audited
-- Description: Governance mutations on a hippocampus memory row. Three
--   modes: 'promote' (importance=10), 'forget' (expires_at=now()),
--   'suspend' (importance=0). Every mutation is audit-journaled.
-- Security: SECURITY DEFINER, admin/staff only.

CREATE OR REPLACE FUNCTION public.set_memory_governance_audited(
  p_memory_id uuid,
  p_mode      text,   -- 'promote' | 'forget' | 'suspend'
  p_reason    text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_old_importance int;
  v_old_expires_at timestamptz;
  v_new_importance int;
  v_new_expires_at timestamptz;
  v_agent_slug text;
BEGIN
  IF v_user_id IS NULL
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_admin_or_staff(v_user_id) THEN
    RAISE EXCEPTION 'Admin or staff role required to govern hippocampus memories'
      USING ERRCODE = '42501';
  END IF;

  IF p_mode NOT IN ('promote', 'forget', 'suspend') THEN
    RAISE EXCEPTION USING
      MESSAGE = format('Invalid mode: %s (expected promote|forget|suspend)', p_mode),
      ERRCODE = '22023';
  END IF;

  SELECT am.importance, am.expires_at, am.agent_slug
    INTO v_old_importance, v_old_expires_at, v_agent_slug
  FROM public.agent_memories am
  WHERE am.id = p_memory_id;

  IF v_agent_slug IS NULL THEN
    RAISE EXCEPTION 'Memory not found: %', p_memory_id USING ERRCODE = 'P0002';
  END IF;

  IF v_agent_slug NOT LIKE 'hippocampus:%' THEN
    RAISE EXCEPTION 'Memory % is not a hippocampus signal (agent_slug=%)',
      p_memory_id, v_agent_slug USING ERRCODE = '22023';
  END IF;

  v_new_importance := v_old_importance;
  v_new_expires_at := v_old_expires_at;

  IF p_mode = 'promote' THEN
    v_new_importance := 10;
  ELSIF p_mode = 'forget' THEN
    v_new_expires_at := now();
  ELSIF p_mode = 'suspend' THEN
    v_new_importance := 0;
  END IF;

  UPDATE public.agent_memories
     SET importance = v_new_importance,
         expires_at = v_new_expires_at,
         updated_at = now()
   WHERE id = p_memory_id;

  PERFORM public.write_audit_journal(
    p_action_type := 'update'::public.journal_action_type,
    p_area        := 'admin'::public.journal_area,
    p_details     := jsonb_build_object(
      'memory_id',  p_memory_id,
      'agent_slug', v_agent_slug,
      'mode',       p_mode,
      'reason',     COALESCE(p_reason, '(no reason provided)')
    ),
    p_entity_id   := p_memory_id::text,
    p_entity_type := 'agent_memories',
    p_new_values  := jsonb_build_object(
      'importance', v_new_importance,
      'expires_at', v_new_expires_at
    ),
    p_old_values  := jsonb_build_object(
      'importance', v_old_importance,
      'expires_at', v_old_expires_at
    ),
    p_severity    := 'info'::public.journal_severity,
    p_summary     := format(
      'Hippocampus memory governance — %s (memory_id=%s)',
      p_mode, p_memory_id
    ),
    p_tags        := ARRAY['hippocampus', 'governance', p_mode],
    p_user_id     := v_user_id
  );

  RETURN p_memory_id;
END;
$$;

REVOKE ALL ON FUNCTION public.set_memory_governance_audited(uuid, text, text)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_memory_governance_audited(uuid, text, text)
  TO authenticated;
GRANT EXECUTE ON FUNCTION public.set_memory_governance_audited(uuid, text, text)
  TO service_role;


