        p_new_values := NULL,
        p_old_values := NULL,
        p_severity := 'notice'::public.journal_severity,
        p_summary := 'Admin updated partner profile visibility',
        p_tags := ARRAY['admin', 'partners', 'visibility'],
        p_user_id := auth.uid()
    );
  END IF;

  RETURN v_updated;
