-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/setup_bank_transfer_for_order.sql
-- -----------------------------------------------------------------------------

-- setup_bank_transfer_for_order: Setup bank transfer payment for a pending order
CREATE OR REPLACE FUNCTION public.setup_bank_transfer_for_order(
  p_order_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_order orders%ROWTYPE;
  v_vs text;
  v_iban text;
  v_bic text;
  v_due_days int;
  v_due_date timestamptz;
  v_invoice_header jsonb;
  v_payment_methods jsonb;
BEGIN
  -- Authorization: must be order owner
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id AND user_id = v_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found or unauthorized' USING ERRCODE = '42501';
  END IF;

  IF v_order.status NOT IN ('pending') THEN
    RAISE EXCEPTION 'Order is not in pending status' USING ERRCODE = 'P0001';
  END IF;

  -- Get invoice header config (IBAN, BIC)
  SELECT value INTO v_invoice_header
  FROM public.system_config WHERE key = 'invoice_header';

  v_iban := COALESCE(v_invoice_header ->> 'bank_account_iban', '');
  v_bic := COALESCE(v_invoice_header ->> 'bank_account_bic', '');

  IF v_iban = '' THEN
    RAISE EXCEPTION 'Bank account IBAN not configured in system settings' USING ERRCODE = 'P0001';
  END IF;

  -- Get payment methods config (due days)
  SELECT value INTO v_payment_methods
  FROM public.system_config WHERE key = 'payment_methods';

  v_due_days := COALESCE((v_payment_methods ->> 'bank_transfer_due_days')::int, 7);
  v_due_date := now() + (v_due_days || ' days')::interval;

  -- Generate variable symbol
  v_vs := public.generate_variable_symbol(p_order_id);

  -- Update order with bank transfer details
  UPDATE public.orders SET
    payment_method = 'bank_transfer',
    payment_status = 'awaiting_transfer',
    status = 'awaiting_payment',
    variable_symbol = v_vs,
    bank_transfer_iban = v_iban,
    bank_transfer_bic = v_bic,
    bank_transfer_amount = total,
    bank_transfer_due_date = v_due_date,
    updated_at = now()
  WHERE id = p_order_id;

  -- Audit
  PERFORM public.write_audit_journal(
    p_action_type := 'update'::journal_action_type,
    p_area := 'commerce'::journal_area,
    p_details := jsonb_build_object(
      'payment_method', 'bank_transfer',
      'variable_symbol', v_vs,
      'amount', v_order.total,
      'due_date', v_due_date
    ),
    p_entity_id := p_order_id::text,
    p_entity_type := 'order',
    p_new_values := NULL,
    p_old_values := NULL,
    p_severity := 'info'::journal_severity,
    p_summary := 'Bank transfer payment setup for order',
    p_tags := ARRAY['order', 'payment', 'bank_transfer'],
    p_user_id := v_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'variable_symbol', v_vs,
    'iban', v_iban,
    'bic', v_bic,
    'amount', v_order.total,
    'currency', v_order.currency,
    'due_date', v_due_date
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.setup_bank_transfer_for_order(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.setup_bank_transfer_for_order(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/submit_block_response_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.submit_block_response_audited
-- Arguments: p_context_type text, p_block_code text, p_question_type text, p_response jsonb, p_context_id uuid
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:28:06+01:00

CREATE OR REPLACE FUNCTION public.submit_block_response_audited(p_context_type text, p_block_code text, p_question_type text, p_response jsonb, p_context_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_block_record record;
  v_response_id uuid;
  v_result jsonb;
BEGIN
  -- Get current user
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'User not authenticated';
  END IF;

  -- Validate block exists and get its config
  SELECT id, question_type, config, is_required
  INTO v_block_record
  FROM question_blocks
  WHERE block_code = p_block_code
    AND is_active = true;

  IF v_block_record IS NULL THEN
    RAISE EXCEPTION 'Question block not found or inactive: %', p_block_code;
  END IF;

  -- Validate question type matches
  IF v_block_record.question_type != p_question_type THEN
    RAISE EXCEPTION 'Question type mismatch: expected %, got %', v_block_record.question_type, p_question_type;
  END IF;

  -- For tags type, validate selected values against allowed options
  IF p_question_type = 'tags' THEN
    DECLARE
      v_allowed_values text[];
      v_selected_values text[];
      v_invalid_values text[];
    BEGIN
      SELECT array_agg(opt->>'value')
      INTO v_allowed_values
      FROM jsonb_array_elements(v_block_record.config->'options') AS opt;

      IF p_response ? 'values' THEN
        SELECT array_agg(val::text)
        INTO v_selected_values
        FROM jsonb_array_elements_text(p_response->'values') AS val;
      ELSIF p_response ? 'value' THEN
        v_selected_values := ARRAY[p_response->>'value'];
      END IF;

      SELECT array_agg(sv)
      INTO v_invalid_values
      FROM unnest(v_selected_values) AS sv
      WHERE sv != ALL(v_allowed_values);

      IF v_invalid_values IS NOT NULL AND array_length(v_invalid_values, 1) > 0 THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid tag values: %s', array_to_string(v_invalid_values, ', ')), ERRCODE = '22023';
      END IF;
    END;
  END IF;

  -- For feeling_preset type, validate preset_id against allowed presets
  IF p_question_type = 'feeling_preset' THEN
    DECLARE
      v_allowed_presets text[];
      v_selected_preset text;
    BEGIN
      SELECT array_agg(preset->>'id')
      INTO v_allowed_presets
      FROM jsonb_array_elements(v_block_record.config->'presets') AS preset;

      v_selected_preset := p_response->>'preset_id';

      IF v_selected_preset != ALL(v_allowed_presets) THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid feeling preset: %s', v_selected_preset), ERRCODE = '22023';
      END IF;
    END;
  END IF;

  v_response_id := gen_random_uuid();

  v_result := jsonb_build_object(
    'response_id', v_response_id,
    'block_code', p_block_code,
    'question_type', p_question_type,
    'context_type', p_context_type,
    'context_id', p_context_id,
    'response', p_response,
    'validated', true
  );

  PERFORM public.write_audit_journal(
      p_action_type := 'create'::journal_action_type,
      p_area := 'health'::journal_area,
      p_details := 'Block response submitted: ' || p_block_code,
      p_entity_id := NULL,
      p_entity_type := 'block_response',
      p_old_values := 'info'::journal_severity,
      p_severity := v_result,
      p_summary := v_response_id::text,
    p_user_id := v_user_id
  );

  RETURN v_result;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.submit_block_response_audited(p_context_type text, p_block_code text, p_question_type text, p_response jsonb, p_context_id uuid) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.submit_block_response_audited(p_context_type text, p_block_code text, p_question_type text, p_response jsonb, p_context_id uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.submit_block_response_audited(p_context_type text, p_block_code text, p_question_type text, p_response jsonb, p_context_id uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/submit_health_document_analysis_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.submit_health_document_analysis_audited
-- Arguments: p_document_id uuid, p_extracted_data jsonb, p_ai_summary text, p_ai_insights jsonb, p_ai_categories text[], p_tokens_awarded integer
-- Description: Stores AI analysis results for a health document and optionally awards tokens (owner only). Audited.

CREATE OR REPLACE FUNCTION public.submit_health_document_analysis_audited(
  p_document_id uuid,
  p_extracted_data jsonb DEFAULT NULL::jsonb,
  p_ai_summary text DEFAULT NULL::text,
  p_ai_insights jsonb DEFAULT NULL::jsonb,
  p_ai_categories text[] DEFAULT NULL::text[],
  p_tokens_awarded integer DEFAULT NULL::integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_doc record;
  v_award_now boolean := false;
  v_tokens integer := 0;
  v_tokens_awarded_at timestamptz := NULL;
  v_award_error text := NULL;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT id, user_id, tokens_awarded, tokens_awarded_at
  INTO v_doc
  FROM public.member_health_documents
  WHERE id = p_document_id;

  IF v_doc.id IS NULL OR v_doc.user_id <> v_user_id THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  v_tokens := GREATEST(0, COALESCE(p_tokens_awarded, 0));
  v_award_now := v_tokens > 0 AND v_doc.tokens_awarded_at IS NULL;

  IF v_award_now THEN
    BEGIN
      PERFORM public.award_tokens(
        v_user_id,
        'data',
        v_tokens,
        'health_document',
        p_document_id,
        'Document analysis reward'
      );
      v_tokens_awarded_at := now();
    EXCEPTION WHEN others THEN
      v_award_error := SQLERRM;
      v_award_now := false;
      v_tokens := 0;
      v_tokens_awarded_at := NULL;
    END;
  END IF;

  UPDATE public.member_health_documents
  SET
    processing_status = 'completed',
    processed_at = now(),
    extracted_data = COALESCE(p_extracted_data, extracted_data),
    ai_summary = COALESCE(p_ai_summary, ai_summary),
    ai_insights = COALESCE(p_ai_insights, ai_insights),
    ai_categories = COALESCE(p_ai_categories, ai_categories),
    tokens_awarded = CASE WHEN v_award_now THEN v_tokens ELSE tokens_awarded END,
    tokens_awarded_at = CASE WHEN v_award_now THEN v_tokens_awarded_at ELSE tokens_awarded_at END,
    updated_at = now()
  WHERE id = p_document_id;

  PERFORM public.write_audit_journal(
      p_action_type := 'update',
      p_area := 'documents',
      p_details := jsonb_build_object(
      'tokens_awarded', v_tokens,
      'award_attempted', v_award_now,
      'award_error', NULLIF(v_award_error, '')
    ),
      p_entity_id := p_document_id::text,
      p_entity_type := 'member_health_document',
      p_new_values := NULL,
      p_old_values := NULL,
      p_severity := 'info',
      p_summary := 'Health document analysis stored',
      p_tags := ARRAY['phi','documents','analysis'],
      p_user_id := v_user_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'tokens_awarded', v_tokens,
    'tokens_awarded_at', v_tokens_awarded_at
  );
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.submit_health_document_analysis_audited(uuid, jsonb, text, jsonb, text[], integer) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.submit_health_document_analysis_audited(uuid, jsonb, text, jsonb, text[], integer) FROM anon;
GRANT EXECUTE ON FUNCTION public.submit_health_document_analysis_audited(uuid, jsonb, text, jsonb, text[], integer) TO authenticated;


