-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/submit_study_consent_acceptance.sql
-- -----------------------------------------------------------------------------

-- Function: public.submit_study_consent_acceptance
-- Arguments: p_study_id uuid, p_consent_template_id uuid, p_granted boolean, p_signature_data text, p_ip_address inet
-- Description: Submit user acceptance of a study consent requirement.
-- Security: SECURITY DEFINER, authenticated users only
-- Updated: 2026-01-09 - Added p_ip_address param for audit trail

CREATE OR REPLACE FUNCTION public.submit_study_consent_acceptance(
  p_study_id uuid, 
  p_consent_template_id uuid, 
  p_granted boolean DEFAULT true,
  p_signature_data text DEFAULT NULL,
  p_ip_address inet DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_requirement public.study_consent_requirements%ROWTYPE;
  v_template public.consent_templates%ROWTYPE;
  v_acceptance_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF p_study_id IS NULL OR p_consent_template_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Missing parameters');
  END IF;

  -- If not granted, we don't record acceptance
  IF NOT COALESCE(p_granted, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Consent not granted');
  END IF;

  SELECT * INTO v_requirement
  FROM public.study_consent_requirements
  WHERE study_id = p_study_id
    AND consent_template_id = p_consent_template_id
    AND is_active = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Consent requirement not found');
  END IF;

  SELECT * INTO v_template
  FROM public.consent_templates
  WHERE id = p_consent_template_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Consent template not found');
  END IF;

  -- Integrity guards (evidence must be trustworthy):
  -- 1) the template must currently be active (no accepting a retired/pre-ratified version).
  IF NOT v_template.is_active THEN
    RETURN jsonb_build_object('success', false, 'error', 'Consent template is not active');
  END IF;

  -- 2) if this template requires a signature, a non-empty signature is mandatory —
  --    a signature-required consent must never be recorded with a NULL/blank pad.
  IF v_template.requires_signature AND COALESCE(btrim(p_signature_data), '') = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Signature required');
  END IF;

  -- 3) enforce the requirement's validity window (if set) against now().
  IF v_requirement.valid_from IS NOT NULL AND now() < v_requirement.valid_from THEN
    RETURN jsonb_build_object('success', false, 'error', 'Consent requirement not yet valid');
  END IF;
  IF v_requirement.valid_until IS NOT NULL AND now() > v_requirement.valid_until THEN
    RETURN jsonb_build_object('success', false, 'error', 'Consent requirement has expired');
  END IF;

  INSERT INTO public.study_consent_acceptances (
    user_id, study_id, consent_template_id, consent_template_version,
    granted_at, signature_data, ip_address
  ) VALUES (
    v_user_id, p_study_id, p_consent_template_id, 
    -- Convert "1.0" text version to integer (extract major version number)
    floor(v_requirement.consent_template_version::numeric)::integer,
    now(), p_signature_data, p_ip_address
  )
  ON CONFLICT (user_id, study_id, consent_template_id, consent_template_version)
  DO UPDATE SET
    granted_at = EXCLUDED.granted_at,
    revoked_at = NULL,
    -- Immutable-once-set: keep the originally recorded signature; only fill if it was
    -- NULL. A signed acceptance must not be silently overwritten by a re-grant of the
    -- same template version (a genuinely new signature belongs to a new version).
    signature_data = COALESCE(public.study_consent_acceptances.signature_data, EXCLUDED.signature_data),
    ip_address = COALESCE(public.study_consent_acceptances.ip_address, EXCLUDED.ip_address)
  RETURNING id INTO v_acceptance_id;

  IF v_template.consent_type IS NOT NULL THEN
    INSERT INTO public.consents (
      user_id,
      study_id,
      consent_type,
      granted,
      granted_at,
      revoked_at,
      signature_data,
      document_url,
      version,
      ip_address
    ) VALUES (
      v_user_id,
      p_study_id,
      v_template.consent_type,
      true,
      now(),
      NULL,
      p_signature_data,
      v_template.document_url,
      v_requirement.consent_template_version::text,
      p_ip_address
    )
    ON CONFLICT (user_id, consent_type, study_id)
    DO UPDATE SET
      granted = true,
      granted_at = now(),
      revoked_at = NULL,
      -- Immutable-once-set (mirror of the acceptances guard above).
      signature_data = COALESCE(public.consents.signature_data, EXCLUDED.signature_data),
      document_url = COALESCE(EXCLUDED.document_url, public.consents.document_url),
      version = EXCLUDED.version,
      ip_address = COALESCE(public.consents.ip_address, EXCLUDED.ip_address);
  END IF;

  PERFORM public.write_audit_journal(
      p_action_type := 'update'::journal_action_type,
      p_area := 'consents'::journal_area,
      p_details := jsonb_build_object(
      'study_id', p_study_id,
      'consent_template_id', p_consent_template_id,
      'has_ip_address', p_ip_address IS NOT NULL
    ),
      p_entity_id := v_acceptance_id::text,
      p_entity_type := 'consent',
      p_severity := 'info'::journal_severity,
      p_summary := 'User granted study consent',
    p_user_id := v_user_id
  );

  RETURN jsonb_build_object('success', true, 'id', v_acceptance_id, 'version', v_requirement.consent_template_version);
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.submit_study_consent_acceptance(uuid, uuid, boolean, text, inet) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_study_consent_acceptance(uuid, uuid, boolean, text, inet) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/submit_study_participant_consent.sql
-- -----------------------------------------------------------------------------

-- Function: public.submit_study_participant_consent
-- Arguments: p_study_id uuid, p_consent_type text, p_signature_data text
-- Description: User submits their own consent for study participation. Self-service function.
-- Security: SECURITY DEFINER - user can only submit their own consent (auth.uid()).
-- @audit: required
-- @phi: false (user manages own consent, not accessing others' data)

CREATE OR REPLACE FUNCTION public.submit_study_participant_consent(p_study_id uuid, p_consent_type text, p_signature_data text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_consent_id UUID;
  v_version TEXT;
BEGIN
  -- Owner check: user_id = auth.uid() (self-service only)
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF p_study_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Study required');
  END IF;

  IF p_consent_type IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Consent type required');
  END IF;

  IF p_consent_type = 'informed_consent' THEN
    SELECT informed_consent_version INTO v_version
    FROM studies
    WHERE id = p_study_id;
  END IF;

  v_version := COALESCE(v_version, '1.0');

  INSERT INTO consents (
    user_id,
    study_id,
    consent_type,
    granted,
    granted_at,
    signature_data,
    version
  ) VALUES (
    v_user_id,
    p_study_id,
    p_consent_type::consent_type,
    true,
    now(),
    p_signature_data,
    v_version
  )
  ON CONFLICT (user_id, consent_type, study_id)
  DO UPDATE SET
    granted = true,
    granted_at = now(),
    revoked_at = NULL,
    signature_data = COALESCE(EXCLUDED.signature_data, consents.signature_data),
    version = EXCLUDED.version
  RETURNING id INTO v_consent_id;

  PERFORM public.write_audit_journal(
      p_action_type := 'update'::journal_action_type,
      p_area := 'consents'::journal_area,
      p_details := jsonb_build_object(
      'consent_type', p_consent_type,
      'study_id', p_study_id
    ),
      p_entity_id := v_consent_id::text,
      p_entity_type := 'consent',
      p_severity := 'info'::journal_severity,
      p_summary := 'User granted consent',
      p_tags := ARRAY['consent', 'self'],
      p_user_id := v_user_id
  );

  RETURN jsonb_build_object('success', true, 'id', v_consent_id, 'version', v_version);
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.submit_study_participant_consent(p_study_id uuid, p_consent_type text, p_signature_data text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_study_participant_consent(p_study_id uuid, p_consent_type text, p_signature_data text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/submit_test_attempt.sql
-- -----------------------------------------------------------------------------

-- Function: public.submit_test_attempt
-- Arguments: p_attempt_id uuid, p_answers jsonb
-- Description: Grades a System-B test attempt server-side against test_questions for the
--   attempt's template and records the verdict on the attempt row. The score/pass are
--   computed here (never trusted from the client) and correct_answer is read under
--   SECURITY DEFINER (test_questions is admin-only via RLS). One submission per attempt.
-- Security: SECURITY DEFINER, authenticated only.

CREATE OR REPLACE FUNCTION public.submit_test_attempt(p_attempt_id uuid, p_answers jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_attempt public.test_attempts%ROWTYPE;
  v_passing integer;
  v_total integer := 0;
  v_correct integer := 0;
  v_score integer := 0;
  v_passed boolean := false;
  v_q record;
  v_answer text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_attempt FROM public.test_attempts WHERE id = p_attempt_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Attempt not found';
  END IF;
  IF v_attempt.user_id <> v_user_id THEN
    RAISE EXCEPTION 'Not authorized for this attempt' USING ERRCODE = '42501';
  END IF;
  IF v_attempt.completed_at IS NOT NULL THEN
    RAISE EXCEPTION 'Attempt already submitted';
  END IF;

  SELECT COALESCE(passing_score, 80) INTO v_passing
  FROM public.test_templates WHERE id = v_attempt.template_id;

  SELECT count(*) INTO v_total
  FROM public.test_questions
  WHERE template_id = v_attempt.template_id AND is_active = true;

  IF v_total > 0 THEN
    FOR v_q IN
      SELECT id, correct_answer FROM public.test_questions
      WHERE template_id = v_attempt.template_id AND is_active = true
    LOOP
      v_answer := p_answers ->> v_q.id::text;
      IF v_answer IS NOT NULL AND v_answer = v_q.correct_answer THEN
        v_correct := v_correct + 1;
      END IF;
    END LOOP;
    v_score := round((v_correct::numeric / v_total::numeric) * 100);
  END IF;

  v_passed := v_total > 0 AND v_score >= COALESCE(v_passing, 80);

  UPDATE public.test_attempts
  SET answers = p_answers,
      score = v_score,
      passed = v_passed,
      completed_at = now()
  WHERE id = p_attempt_id;

  PERFORM public.write_audit_journal(
    p_action_type := 'update'::journal_action_type,
    p_area := 'studies'::journal_area,
    p_details := jsonb_build_object(
      'template_id', v_attempt.template_id,
      'score', v_score,
      'passed', v_passed
    ),
    p_entity_id := p_attempt_id::text,
    p_entity_type := 'test_attempt',
    p_severity := 'info'::journal_severity,
    p_summary := 'Member submitted a study test attempt',
    p_user_id := v_user_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'passed', v_passed,
    'score', v_score,
    'total_questions', v_total,
    'correct_count', v_correct,
    'passing_score', COALESCE(v_passing, 80)
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.submit_test_attempt(uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_test_attempt(uuid, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.submit_test_attempt(uuid, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/surface_udel_admin.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: surface_udel_admin
-- Popis: Udělí / odebere uživateli přístup do sekce extranetu (osa publika
--        „udeleni"). Správa v administraci u uživatele — rozhodnutí majitele
--        2026-09-28: přístup do sekce je u uživatele, ne role; data v sekci dál
--        řídí nárok z vazeb.
--
-- Udělit jde jen sekci, kterou některé aktivní umístění nebo šablona sekce
-- deklaruje jako udělitelnou (audience obsahuje "udeleni": "<sekce>") — jinak by
-- udělení nic neotevřelo a v administraci by vypadalo jako funkční.
-- Každá změna jde do audit_journal (kdo, komu, jakou sekci, udělil/odebral).
--
-- Bezpečnost: SECURITY DEFINER; jen správa (is_admin_or_staff).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.surface_udel_admin(
  p_user_id uuid,
  p_surface text,
  p_udelit  boolean
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_pocet integer;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: jen správa uděluje sekce' USING ERRCODE = '42501';
  END IF;
  IF p_user_id IS NULL OR NOT EXISTS (SELECT 1 FROM aisha_auth.users u WHERE u.id = p_user_id) THEN
    RAISE EXCEPTION 'user_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF p_surface IS NULL OR p_surface !~ '^[a-z][a-z0-9_]*$' THEN
    RAISE EXCEPTION 'invalid_surface' USING ERRCODE = '22023';
  END IF;
  IF p_udelit AND NOT (
       EXISTS (SELECT 1 FROM public.surface_layouts l
                WHERE l.is_active AND l.audience->>'udeleni' = p_surface)
       OR EXISTS (SELECT 1 FROM public.surface_sections s
                   WHERE s.is_active AND s.audience->>'udeleni' = p_surface)) THEN
    RAISE EXCEPTION 'surface_not_grantable: sekce % nemá umístění s osou udeleni', p_surface
      USING ERRCODE = '22023';
  END IF;

  IF p_udelit THEN
    INSERT INTO public.surface_section_grants (user_id, surface, granted_by)
    VALUES (p_user_id, p_surface, auth.uid())
    ON CONFLICT (user_id, surface) DO NOTHING;
  ELSE
    DELETE FROM public.surface_section_grants
     WHERE user_id = p_user_id AND surface = p_surface;
  END IF;
  GET DIAGNOSTICS v_pocet = ROW_COUNT;

  IF v_pocet > 0 THEN
    PERFORM public.write_audit_journal(
      p_action_type := (CASE WHEN p_udelit THEN 'create' ELSE 'delete' END)::public.journal_action_type,
      p_area        := 'admin'::public.journal_area,
      p_details     := jsonb_build_object('surface', p_surface, 'target_user_id', p_user_id, 'udelit', p_udelit),
      p_entity_id   := p_user_id::text,
      p_entity_type := 'surface_section_grants',
      p_new_values  := NULL,
      p_old_values  := NULL,
      p_severity    := 'notice'::public.journal_severity,
      p_summary     := format('%s sekce %s', CASE WHEN p_udelit THEN 'Udělena' ELSE 'Odebrána' END, p_surface),
      p_tags        := ARRAY['admin', 'surface', 'udeleni'],
      p_user_id     := auth.uid()
    );
  END IF;

  RETURN jsonb_build_object('ok', true, 'surface', p_surface, 'udeleno', p_udelit, 'zmena', v_pocet > 0);
END;
$$;

REVOKE ALL ON FUNCTION public.surface_udel_admin(uuid, text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.surface_udel_admin(uuid, text, boolean) TO authenticated, service_role;

COMMENT ON FUNCTION public.surface_udel_admin(uuid, text, boolean) IS
  'Správa: udělí/odebere uživateli sekci extranetu (osa publika udeleni). Jen udělitelné sekce, audit.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/sync_health_data.sql
-- -----------------------------------------------------------------------------

-- Function: public.sync_health_data
-- Arguments: p_health_entries jsonb
-- Security: See function definition below.
-- Extracted: 2026-01-08T18:28:09+01:00

CREATE OR REPLACE FUNCTION public.sync_health_data(p_health_entries jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_count INTEGER := 0;
  v_entry JSONB;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RETURN json_build_object('success', false, 'error_code', 'auth.not_authenticated');
  END IF;

  IF jsonb_typeof(p_health_entries) IS DISTINCT FROM 'array' THEN
    RETURN json_build_object('success', false, 'error_code', 'health.invalid_payload');
  END IF;

  FOR v_entry IN SELECT * FROM jsonb_array_elements(p_health_entries)
  LOOP
    -- Basic payload validation (fail-closed per entry, do not accept partial/invalid rows)
    IF (v_entry ? 'data_type') IS FALSE
      OR (v_entry ? 'value') IS FALSE
      OR (v_entry ? 'unit') IS FALSE
      OR (v_entry ? 'recorded_at') IS FALSE
    THEN
      CONTINUE;
    END IF;

    INSERT INTO health_data (
      user_id,
      data_type,
      value,
      unit,
      metadata,
      recorded_at,
      source
    ) VALUES (
      v_user_id,
      v_entry->>'data_type',
      (v_entry->>'value')::numeric,
      v_entry->>'unit',
      COALESCE(v_entry->'metadata', '{}'::jsonb),
      (v_entry->>'recorded_at')::timestamptz,
      COALESCE(v_entry->>'source', 'manual')
    )
    ON CONFLICT (user_id, data_type, recorded_at)
    DO UPDATE SET
      value = EXCLUDED.value,
      unit = EXCLUDED.unit,
      metadata = EXCLUDED.metadata,
      source = EXCLUDED.source;

    v_count := v_count + 1;
  END LOOP;

  PERFORM public.write_audit_journal(
      p_action_type := 'create'::journal_action_type,
      p_area := 'health'::journal_area,
      p_details := jsonb_build_object('entries_count', v_count),
      p_entity_id := v_user_id::text,
      p_entity_type := 'health_data',
      p_severity := 'info'::journal_severity,
      p_summary := 'Synced ' || v_count || ' health data entries',
    p_user_id := v_user_id
  );

  RETURN json_build_object('success', true, 'synced_count', v_count);
EXCEPTION WHEN OTHERS THEN
  -- Do not return SQLERRM (can leak internal schema/constraint details).
  PERFORM public.write_audit_journal(
      p_action_type := 'create'::journal_action_type,
      p_area := 'health'::journal_area,
      p_details := jsonb_build_object('sqlstate', SQLSTATE),
      p_entity_id := v_user_id::text,
      p_entity_type := 'health_data',
      p_severity := 'error'::journal_severity,
      p_summary := 'Health data sync failed',
    p_user_id := v_user_id
  );

  RETURN json_build_object('success', false, 'error_code', 'health.sync_failed');
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.sync_health_data(p_health_entries jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.sync_health_data(p_health_entries jsonb) FROM anon;
GRANT EXECUTE ON FUNCTION public.sync_health_data(p_health_entries jsonb) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/sync_health_data_with_conflict_resolution.sql
-- -----------------------------------------------------------------------------

-- Function: public.sync_health_data_with_conflict_resolution
-- Arguments: p_health_records jsonb, p_conflict_resolution text
-- Description: Sync health data from mobile app (sensitive data)
-- @security: authenticated
-- @audit: required
-- @phi: true

CREATE OR REPLACE FUNCTION public.sync_health_data_with_conflict_resolution(p_health_records jsonb, p_conflict_resolution text DEFAULT 'server_wins'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_sync_batch_id UUID;
  v_record JSONB;
  v_existing RECORD;
  v_inserted_count INTEGER := 0;
  v_updated_count INTEGER := 0;
  v_skipped_count INTEGER := 0;
  v_conflict_count INTEGER := 0;
  v_points_awarded INTEGER := 0;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Audit sensitive data sync
  PERFORM public.write_audit_journal(
      p_action_type := 'update'::journal_action_type,
      p_area := 'studies'::journal_area,
      p_details := jsonb_build_object('records_count', jsonb_array_length(p_health_records), 'conflict_resolution', p_conflict_resolution),
      p_entity_id := NULL,
      p_entity_type := 'health_data',
      p_new_values := NULL,
      p_old_values := NULL,
      p_severity := 'notice',
      p_summary := 'Member synced health data',
      p_tags := ARRAY['phi','member','health_sync'],
      p_user_id := v_user_id
  );

  -- Rate limiting
  PERFORM enforce_rate_limit('sync_health_data_with_conflict_resolution', 60000, 10);

  -- Validate input
  IF jsonb_typeof(p_health_records) != 'array' THEN
    RAISE EXCEPTION 'p_health_records must be an array';
  END IF;

  IF jsonb_array_length(p_health_records) > 100 THEN
    RAISE EXCEPTION 'Maximum 100 records per sync';
  END IF;

  v_sync_batch_id := gen_random_uuid();

  FOR v_record IN SELECT * FROM jsonb_array_elements(p_health_records)
  LOOP
    -- Check for existing record
    SELECT * INTO v_existing
    FROM health_check_ins
    WHERE user_id = v_user_id
      AND check_in_date = (v_record->>'check_in_date')::DATE
      AND data_source = COALESCE(v_record->>'data_source', 'manual');

    IF v_existing IS NOT NULL THEN
      -- Conflict detection
      IF p_conflict_resolution = 'server_wins' THEN
        -- Skip, keep server version
        v_skipped_count := v_skipped_count + 1;

      ELSIF p_conflict_resolution = 'client_wins' THEN
        -- Update with client data
        UPDATE health_check_ins SET
          steps_count = COALESCE((v_record->>'steps_count')::INTEGER, steps_count),
          sleep_hours = COALESCE((v_record->>'sleep_hours')::NUMERIC, sleep_hours),
          sleep_quality = COALESCE((v_record->>'sleep_quality')::INTEGER, sleep_quality),
          energy_level = COALESCE((v_record->>'energy_level')::INTEGER, energy_level),
          mood_level = COALESCE((v_record->>'mood_level')::INTEGER, mood_level),
          pain_level = COALESCE((v_record->>'pain_level')::INTEGER, pain_level),
          heart_rate_avg = COALESCE((v_record->>'heart_rate_avg')::INTEGER, heart_rate_avg),
          client_synced_at = COALESCE((v_record->>'client_synced_at')::TIMESTAMPTZ, now()),
          sync_status = 'synced',
          synced_at = now(),
          sync_batch_id = v_sync_batch_id
        WHERE id = v_existing.id;
        v_updated_count := v_updated_count + 1;

      ELSIF p_conflict_resolution = 'merge' THEN
        -- Merge: take non-null values from client, keep server values for nulls
        UPDATE health_check_ins SET
          steps_count = COALESCE((v_record->>'steps_count')::INTEGER, steps_count),
          sleep_hours = COALESCE((v_record->>'sleep_hours')::NUMERIC, sleep_hours),
          sleep_quality = COALESCE((v_record->>'sleep_quality')::INTEGER, sleep_quality),
          energy_level = COALESCE((v_record->>'energy_level')::INTEGER, energy_level),
          mood_level = COALESCE((v_record->>'mood_level')::INTEGER, mood_level),
          pain_level = COALESCE((v_record->>'pain_level')::INTEGER, pain_level),
          heart_rate_avg = GREATEST(
            COALESCE((v_record->>'heart_rate_avg')::INTEGER, 0),
            COALESCE(heart_rate_avg, 0)
          ),
          heart_rate_min = LEAST(
            COALESCE((v_record->>'heart_rate_min')::INTEGER, 999),
            COALESCE(heart_rate_min, 999)
          ),
          heart_rate_max = GREATEST(
            COALESCE((v_record->>'heart_rate_max')::INTEGER, 0),
            COALESCE(heart_rate_max, 0)
          ),
          active_energy_burned = GREATEST(
            COALESCE((v_record->>'active_energy_burned')::INTEGER, 0),
            COALESCE(active_energy_burned, 0)
          ),
          distance_meters = GREATEST(
            COALESCE((v_record->>'distance_meters')::INTEGER, 0),
            COALESCE(distance_meters, 0)
          ),
          client_synced_at = COALESCE((v_record->>'client_synced_at')::TIMESTAMPTZ, now()),
          sync_status = 'synced',
          synced_at = now(),
          sync_batch_id = v_sync_batch_id
        WHERE id = v_existing.id;
        v_updated_count := v_updated_count + 1;
      END IF;

      v_conflict_count := v_conflict_count + 1;
    ELSE
      -- No conflict, insert new record
      INSERT INTO health_check_ins (
        user_id, check_in_date, check_in_type, steps_count, sleep_hours,
        sleep_quality, energy_level, mood_level, pain_level, activity_minutes,
        heart_rate_avg, heart_rate_min, heart_rate_max,
        active_energy_burned, distance_meters,
        data_source, device_info, sync_batch_id, synced_at,
        client_synced_at, sync_status
      ) VALUES (
        v_user_id,
        (v_record->>'check_in_date')::DATE,
        COALESCE(v_record->>'check_in_type', 'daily'),
        (v_record->>'steps_count')::INTEGER,
        (v_record->>'sleep_hours')::NUMERIC,
        (v_record->>'sleep_quality')::INTEGER,
        (v_record->>'energy_level')::INTEGER,
        (v_record->>'mood_level')::INTEGER,
        (v_record->>'pain_level')::INTEGER,
        (v_record->>'activity_minutes')::INTEGER,
        (v_record->>'heart_rate_avg')::INTEGER,
        (v_record->>'heart_rate_min')::INTEGER,
        (v_record->>'heart_rate_max')::INTEGER,
        (v_record->>'active_energy_burned')::INTEGER,
        (v_record->>'distance_meters')::INTEGER,
        COALESCE(v_record->>'data_source', 'manual'),
        v_record->>'device_info',
        v_sync_batch_id,
        now(),
        (v_record->>'client_synced_at')::TIMESTAMPTZ,
        'synced'
      );
      v_inserted_count := v_inserted_count + 1;
    END IF;
  END LOOP;

  -- Award points for new records only
  v_points_awarded := v_inserted_count * 10;

  IF v_points_awarded > 0 THEN
    INSERT INTO token_allocations (user_id, balance, updated_at)
    VALUES (v_user_id, v_points_awarded, now())
    ON CONFLICT (user_id)
    DO UPDATE SET
      balance = token_allocations.balance + v_points_awarded,
      updated_at = now();

    INSERT INTO token_transactions (
      to_user_id, amount, transaction_type, reference_type, reference_id,
      description, created_at
    ) VALUES (
      v_user_id, v_points_awarded, 'reward', 'health_sync', v_sync_batch_id,
      format('Health sync with conflict resolution: %s new records', v_inserted_count), now()
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'inserted_count', v_inserted_count,
    'updated_count', v_updated_count,
    'skipped_count', v_skipped_count,
    'conflict_count', v_conflict_count,
    'conflict_resolution', p_conflict_resolution,
    'sync_batch_id', v_sync_batch_id,
    'points_awarded', v_points_awarded
  );
END;
$function$
;

