-- Function: public.update_news_article_canvas_admin
-- Description: Vstup editoru plátna (CanvasEditor → useUpdateNewsArticleCanvas).
--              Od 2026-09-24 už sám nezapisuje: rozhoduje jen mezi „ulož"
--              (save_news_article_draft_admin — u zveřejněného článku KONCEPT,
--              jinak živý stav) a „zveřejni" (publish_news_article_admin).
--              Vrací nové razítko pro souběžnou kontrolu (p_expected_stamp).
--
-- ⛔ Do 2026-09-24 psala rovnou do canvas_html, které čte veřejná stránka —
--    autosave 5 s po změně tak u zveřejněného článku šel na web i s nedopsanou
--    větou. Nový parametr + návratový typ = nový podpis, proto DROP (PostgREST by
--    jinak měl dvě přetížení a volání s pojmenovanými argumenty odmítl).
-- Security: SECURITY DEFINER; autorizuje sám (admin/staff) — i když volané
--           funkce autorizují znovu, delegát bez vlastní stráže je orákulum.
--           Audit: zápisy auditují volané funkce; zveřejnění z editoru se navíc
--           zapíše jako událost editoru (write_audit_journal).

DROP FUNCTION IF EXISTS public.update_news_article_canvas_admin(uuid, jsonb, text, text, boolean);

CREATE OR REPLACE FUNCTION public.update_news_article_canvas_admin(
  p_id uuid,
  p_canvas_data jsonb DEFAULT NULL,
  p_canvas_html text DEFAULT NULL,
  p_canvas_css text DEFAULT NULL,
  p_publish boolean DEFAULT false,
  p_expected_stamp timestamptz DEFAULT NULL
)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_stamp timestamptz;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  IF p_publish THEN
    v_stamp := public.publish_news_article_admin(p_id, p_canvas_css, p_canvas_data, p_canvas_html, p_expected_stamp, NULL);
    PERFORM public.write_audit_journal(
      p_action_type := 'update'::public.journal_action_type,
      p_area := 'content'::public.journal_area,
      p_details := NULL,
      p_entity_id := p_id::text,
      p_entity_type := 'news_article',
      p_new_values := jsonb_build_object('publish', true, 'source', 'canvas_editor'),
      p_old_values := NULL,
      p_severity := 'info'::public.journal_severity,
      p_summary := 'Published news article from the canvas editor',
      p_tags := ARRAY['admin', 'content', 'news_article', 'canvas'],
      p_user_id := auth.uid()
    );
    RETURN v_stamp;
  END IF;

  RETURN public.save_news_article_draft_admin(p_id, p_canvas_css, p_canvas_data, p_canvas_html, p_expected_stamp, NULL);
END;
$$;

REVOKE ALL ON FUNCTION public.update_news_article_canvas_admin(uuid, jsonb, text, text, boolean, timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_news_article_canvas_admin(uuid, jsonb, text, text, boolean, timestamptz) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/update_node_factory_request_status.sql
-- -----------------------------------------------------------------------------

-- Function: public.update_node_factory_request_status
-- Arguments: p_request_id uuid, p_status text, p_error_message text, p_generated_code text, p_validation_result jsonb
-- Description: Update the status and results of a node factory request.
-- Security: SECURITY DEFINER with search_path set.
-- Created: 2026-03-05

CREATE OR REPLACE FUNCTION public.update_node_factory_request_status(
  p_request_id uuid,
  p_status text,
  p_error_message text DEFAULT NULL,
  p_generated_code text DEFAULT NULL,
  p_validation_result jsonb DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_old_status text;
BEGIN
  -- Authorization: only admin, staff, or service_role
  IF NOT is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: only admin or staff can update request status'
      USING ERRCODE = 'P0001';
  END IF;

  -- Validate status value
  IF p_status NOT IN ('pending', 'generating', 'validating', 'testing', 'deploying', 'deployed', 'failed', 'cancelled') THEN
    RAISE EXCEPTION USING MESSAGE = format('Invalid status: %s', p_status), ERRCODE = 'P0001';
  END IF;

  -- Get old status for audit
  SELECT nfr.status INTO v_old_status
  FROM node_factory_requests nfr
  WHERE nfr.id = p_request_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Request not found: %', p_request_id
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE node_factory_requests SET
    status = p_status,
    error_message = COALESCE(p_error_message, node_factory_requests.error_message),
    generated_code = COALESCE(p_generated_code, node_factory_requests.generated_code),
    validation_result = COALESCE(p_validation_result, node_factory_requests.validation_result),
    deployed_at = CASE WHEN p_status = 'deployed' THEN now() ELSE node_factory_requests.deployed_at END
  WHERE id = p_request_id;

  -- Audit status transition
  PERFORM write_audit_journal(
    p_action_type := 'update'::journal_action_type,
    p_area := 'system'::journal_area,
    p_details := jsonb_build_object(
      'old_status', v_old_status,
      'new_status', p_status,
      'has_error', p_error_message IS NOT NULL
    ),
    p_entity_id := p_request_id::text,
    p_entity_type := 'node_factory_request',
    p_severity := CASE WHEN p_status = 'failed' THEN 'warning' ELSE 'info' END::journal_severity,
    p_summary := 'Node factory request status: ' || v_old_status || ' → ' || p_status,
    p_user_id := auth.uid()
  );

  RETURN true;
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.update_node_factory_request_status(uuid, text, text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_node_factory_request_status(uuid, text, text, text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.update_node_factory_request_status(uuid, text, text, text, jsonb) TO service_role;


