-- -----------------------------------------------------------------------------

-- Function: public.upsert_study_questionnaire_admin
-- Arguments: p_description_key, p_display_order, p_ends_after_days, p_frequency_days,
--   p_frequency_type, p_id, p_is_active, p_is_required, p_questionnaire_id,
--   p_questionnaire_type, p_questionnaire_version, p_starts_after_days, p_study_id,
--   p_title_key, p_token_reward
-- Description: Upsert study questionnaire configuration. Admin/staff only.
--   Translations are stored in "translations" table via keys, NOT as _cs/_en columns.
-- Security: SECURITY DEFINER, admin/staff only

CREATE OR REPLACE FUNCTION public.upsert_study_questionnaire_admin(
  p_study_id UUID,
  p_description_key TEXT DEFAULT NULL,
  p_display_order INTEGER DEFAULT 0,
  p_ends_after_days INTEGER DEFAULT NULL,
  p_frequency_days INTEGER DEFAULT NULL,
  p_frequency_type TEXT DEFAULT 'one_time',
  p_id UUID DEFAULT NULL,
  p_is_active BOOLEAN DEFAULT TRUE,
  p_is_required BOOLEAN DEFAULT TRUE,
  p_questionnaire_id UUID DEFAULT NULL,
  p_questionnaire_type TEXT DEFAULT 'custom',
  p_questionnaire_version INTEGER DEFAULT 1,
  p_starts_after_days INTEGER DEFAULT 0,
  p_title_key TEXT DEFAULT NULL,
  p_token_reward INTEGER DEFAULT 25
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_id UUID;
  v_version INTEGER;
BEGIN
  IF NOT is_admin_or_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or staff role required';
  END IF;

  -- Get questionnaire version if linked
  IF p_questionnaire_id IS NOT NULL AND p_questionnaire_version IS NULL THEN
    SELECT version INTO v_version FROM public.questionnaires WHERE id = p_questionnaire_id;
  ELSE
    v_version := p_questionnaire_version;
  END IF;

  INSERT INTO public.study_questionnaires (
    id,
    study_id,
    questionnaire_id,
    questionnaire_type,
    is_required,
    is_active,
    frequency_type,
    frequency_days,
    token_reward,
    display_order,
    starts_after_days,
    ends_after_days,
    title_key,
    description_key,
    questionnaire_version
  ) VALUES (
    COALESCE(p_id, gen_random_uuid()),
    p_study_id,
    p_questionnaire_id,
    p_questionnaire_type,
    COALESCE(p_is_required, TRUE),
    COALESCE(p_is_active, TRUE),
    COALESCE(p_frequency_type, 'one_time'),
    p_frequency_days,
    COALESCE(p_token_reward, 25),
    COALESCE(p_display_order, 0),
    COALESCE(p_starts_after_days, 0),
    p_ends_after_days,
    p_title_key,
    p_description_key,
    COALESCE(v_version, 1)
  )
  ON CONFLICT (study_id, questionnaire_type)
  DO UPDATE SET
    questionnaire_id = EXCLUDED.questionnaire_id,
    is_required = EXCLUDED.is_required,
    is_active = EXCLUDED.is_active,
    frequency_type = EXCLUDED.frequency_type,
    frequency_days = EXCLUDED.frequency_days,
    token_reward = EXCLUDED.token_reward,
    display_order = EXCLUDED.display_order,
    starts_after_days = EXCLUDED.starts_after_days,
    ends_after_days = EXCLUDED.ends_after_days,
    title_key = EXCLUDED.title_key,
    description_key = EXCLUDED.description_key,
    questionnaire_version = EXCLUDED.questionnaire_version,
    updated_at = now()
  RETURNING id INTO v_id;

  PERFORM public.write_audit_journal(
      p_action_type := 'update'::journal_action_type,
      p_area := 'research'::journal_area,
      p_entity_id := v_id::text,
      p_entity_type := 'study_questionnaire',
      p_summary := 'Upserted study questionnaire',
    p_user_id := auth.uid()
  );

  RETURN v_id;
END;
$function$;

COMMENT ON FUNCTION public.upsert_study_questionnaire_admin(uuid, text, integer, integer, integer, text, uuid, boolean, boolean, uuid, text, integer, integer, text, integer) IS 
  'Upsert study questionnaire configuration. Admin/staff only. Translations via keys.';

-- Permissions
REVOKE ALL ON FUNCTION public.upsert_study_questionnaire_admin(uuid, text, integer, integer, integer, text, uuid, boolean, boolean, uuid, text, integer, integer, text, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.upsert_study_questionnaire_admin(uuid, text, integer, integer, integer, text, uuid, boolean, boolean, uuid, text, integer, integer, text, integer) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/upsert_web_page_admin.sql
-- -----------------------------------------------------------------------------

-- Function: public.upsert_web_page_admin
-- Description: Creates or updates web page metadata. Requires admin role.
--   Multi-site: accepts branding_profile_id (NULL = global / unchanged).
-- Security: SECURITY DEFINER, authenticated only
-- Created: 2026-04-11

CREATE OR REPLACE FUNCTION public.upsert_web_page_admin(
  p_id uuid DEFAULT NULL,
  p_slug text DEFAULT NULL,
  p_title_key text DEFAULT NULL,
  p_description_key text DEFAULT NULL,
  p_status text DEFAULT 'draft',
  p_sort_order integer DEFAULT 0,
  p_og_image_url text DEFAULT NULL,
  p_branding_profile_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
SET search_path = public
AS $$
DECLARE
  v_id uuid;
  -- Boot-time web-artifact ingest (svc-web-artifact /seed-default) calls this as
  -- service_role with no auth.uid() (sub-less system runner) — admit it, same as
  -- the rest of the seed chain (apply_web_artifact_to_page allows the seed story
  -- participant; seed_branding_site admits service_role). Admin/staff UI path
  -- (page editor) is unchanged.
  v_is_service boolean := (current_setting('request.jwt.claims', true)::jsonb->>'role') = 'service_role';
BEGIN
  IF NOT (v_is_service OR public.is_admin_or_staff()) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  IF p_id IS NOT NULL THEN
    SELECT web_pages.id INTO v_id
    FROM web_pages
    WHERE web_pages.id = p_id;
  ELSIF p_slug IS NOT NULL THEN
    SELECT web_pages.id INTO v_id
    FROM web_pages
    WHERE web_pages.slug = p_slug
      AND web_pages.branding_profile_id IS NOT DISTINCT FROM p_branding_profile_id
    LIMIT 1;
  END IF;

  IF v_id IS NOT NULL THEN
    UPDATE web_pages SET
      slug = COALESCE(p_slug, web_pages.slug),
      title_key = COALESCE(p_title_key, web_pages.title_key),
      description_key = COALESCE(p_description_key, web_pages.description_key),
      status = COALESCE(p_status, web_pages.status),
      sort_order = COALESCE(p_sort_order, web_pages.sort_order),
      og_image_url = COALESCE(p_og_image_url, web_pages.og_image_url),
      branding_profile_id = COALESCE(p_branding_profile_id, web_pages.branding_profile_id),
      updated_at = now()
    WHERE web_pages.id = v_id
    RETURNING web_pages.id INTO v_id;

    PERFORM public.write_audit_journal(
      p_action_type := 'update'::public.journal_action_type,
      p_area := 'content'::public.journal_area,
      p_details := NULL,
      p_entity_id := v_id::text,
      p_entity_type := 'web_page',
      p_new_values := jsonb_build_object('slug', p_slug, 'status', p_status, 'branding_profile_id', p_branding_profile_id),
      p_old_values := NULL,
      p_severity := 'info'::public.journal_severity,
      p_summary := 'Updated web page metadata',
      p_tags := ARRAY['admin', 'content', 'web_page', 'update'],
      p_user_id := auth.uid()
    );
  ELSE
    v_id := COALESCE(p_id, gen_random_uuid());

    INSERT INTO web_pages (id, slug, title_key, description_key, status, sort_order, og_image_url, branding_profile_id)
    VALUES (
      v_id,
      COALESCE(p_slug, 'new-page-' || substring(v_id::text from 1 for 8)),
      COALESCE(p_title_key, 'web.pages.' || COALESCE(p_slug, v_id::text) || '.title'),
      p_description_key,
      COALESCE(p_status, 'draft'),
      COALESCE(p_sort_order, 0),
      p_og_image_url,
      p_branding_profile_id
    );

    PERFORM public.write_audit_journal(
      p_action_type := 'create'::public.journal_action_type,
      p_area := 'content'::public.journal_area,
      p_details := NULL,
      p_entity_id := v_id::text,
      p_entity_type := 'web_page',
      p_new_values := jsonb_build_object('slug', p_slug, 'title_key', p_title_key, 'branding_profile_id', p_branding_profile_id),
      p_old_values := NULL,
      p_severity := 'notice'::public.journal_severity,
      p_summary := 'Created web page',
      p_tags := ARRAY['admin', 'content', 'web_page', 'create'],
      p_user_id := auth.uid()
    );
  END IF;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.upsert_web_page_admin(uuid, text, text, text, text, integer, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.upsert_web_page_admin(uuid, text, text, text, text, integer, text, uuid) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/validate_dose_proposal.sql
-- -----------------------------------------------------------------------------

-- File: aisha/db/sql/functions/validate_dose_proposal.sql
-- -----------------------------------------------------------------------------

-- CONCEPT (why "dose" is misleading — read docs/architecture/RECURRING_INTERACTION_CADENCE.md):
--   "Dose" is not really about medication. The platform models a RECURRING,
--   PLANNED INTERACTION with two axes — FREQUENCY (how often it recurs:
--   doses_per_day / timing) and INTENSITY (how much per beat: dose_amount). The
--   load-bearing abstraction is the FREQUENCY OF INTERACTIONS; medical dosing is
--   one instance (a daily check-in / reminder / practice beat is the same model,
--   with intensity collapsing to yes/no). This RPC validates the INTENSITY axis of
--   one beat; the FREQUENCY axis lives in the prescribed plan / member realization.
--   Vocabulary map (technical → concept):
--     product_dose_units          → RECOMMENDED ENVELOPE   (soft bounds, advisory)
--     study_distribution_protocols→ PRESCRIBED PLAN        (the study's cadence)
--     member_distribution_plans   → MEMBER REALIZATION     (chosen cadence + notes)
--     distribution_adjustments    → TRUST-SCOPED RE-TUNING (consultant, consent, audit)
--     dosing_logs                 → REALIZED BEATS         (free-form, real-world)
--   This RPC is the ADVISORY CHECK AT THE MOMENT OF PROPOSING a beat. It never
--   blocks; its tiers gate WHO MAY READ a member's cadence, not whether a beat may
--   be logged — consistent with the distribution_adjustments access boundary.
-- -----------------------------------------------------------------------------

-- Function: public.validate_dose_proposal
-- Arguments: p_product_id uuid, p_dose_amount numeric, p_dose_unit text,
--            p_member_distribution_plan_id uuid DEFAULT NULL
-- Description: Advisory validation for a proposed dose. Two tiers, one function:
--
--   (1) PRODUCT TIER — pass just (product, amount, unit). Anonymous-friendly
--       pre-write check (mobile dose slider, web plan editor): evaluates the
--       amount against the per-product/unit bounds in product_dose_units. No
--       member/PHI data is touched, so it stays GRANTable to anon — exactly the
--       posture of its companion get_product_dose_options.
--
--   (2) MEMBER/STUDY TIER — also pass p_member_distribution_plan_id. This is the
--       consultant-facing path (validate a *proposed adjustment* against a real
--       member's plan). Reading a member's plan is PHI access, so this tier is
--       held to the SAME access contract as create_distribution_adjustment /
--       get_distribution_adjustments_audited:
--         • authenticated (auth.uid() must resolve),
--         • caller is admin/staff OR has the 'consultant' role,
--         • data-sharing consent on the member (admin/staff bypass — platform
--           operators),
--         • the access is written to the audit journal (PHI view).
--       It then adds context warnings: deviation from the study-prescribed
--       protocol dose, and from the member's current plan dose.
--
-- Advisory ALWAYS: `valid` is always true and the dose is NEVER blocked — the
-- platform's data-collection contract requires accepting out-of-range entries.
-- The member tier gates *who may read the member context*, not whether the dose
-- may be logged. No hardcoded thresholds — all product bounds come from
-- product_dose_units rows.
--
-- Companion: get_product_dose_options(uuid) returns the product bounds; this RPC
-- evaluates a specific proposed dose against them (+ optional member/study context).
--
-- Return shape (jsonb):
--   {
--     "valid": true,
--     "warnings": [ {level: low|high|info, field, context, message, …}, … ],
--     "recommended": { default_amount, min_amount, max_amount, step_amount } | null,
--     "product_unit_match": bool,
--     "context": { has_member_context: bool, has_study_context: bool }
--   }

-- Drop the 3-arg product-only signature so the 4-arg member-aware version is the
-- only overload (a 3-arg call resolves to it via the DEFAULT). No-op on a fresh
-- baseline apply (the 3-arg never shipped). Idempotent.
DROP FUNCTION IF EXISTS public.validate_dose_proposal(uuid, numeric, text);

CREATE OR REPLACE FUNCTION public.validate_dose_proposal(
  p_product_id uuid,
  p_dose_amount numeric,
  p_dose_unit text,
  p_member_distribution_plan_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_limits product_dose_units%ROWTYPE;
  v_warnings jsonb := '[]'::jsonb;
  v_recommended jsonb;
  v_match boolean := false;
  -- Member/study tier
  v_caller uuid;
  v_member uuid;
  v_protocol_id uuid;
  v_plan_dose numeric;
  v_custom_dose numeric;
  v_protocol_dose numeric;
  v_current_dose numeric;
  v_has_member boolean := (p_member_distribution_plan_id IS NOT NULL);
  v_has_study boolean := false;
BEGIN
  -- ── MEMBER/STUDY TIER: access control (mirrors create_distribution_adjustment) ─
  -- Reading a member's plan is PHI access, so the member tier requires auth +
  -- consultant/admin role + data-sharing consent, and is audited. The dose itself
  -- is still advisory; this guard governs READING the member context, not logging.
  IF v_has_member THEN
    v_caller := auth.uid();
    IF v_caller IS NULL THEN
      RAISE EXCEPTION 'Authentication required to validate against a member plan'
        USING ERRCODE = '42501';
    END IF;

    IF NOT (public.is_admin_or_staff(v_caller) OR public.has_role(v_caller, 'consultant')) THEN
      RAISE EXCEPTION 'Only consultants or admin/staff may validate a member plan dose'
        USING ERRCODE = '42501';
    END IF;

    SELECT mdp.user_id, mdp.protocol_id, mdp.dose_amount, mdp.custom_dose_amount
      INTO v_member, v_protocol_id, v_plan_dose, v_custom_dose
    FROM member_distribution_plans mdp
    WHERE mdp.id = p_member_distribution_plan_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Member distribution plan not found: %', p_member_distribution_plan_id
        USING ERRCODE = 'P0002';
    END IF;

    -- Consultant must hold data-sharing consent on the member; admin/staff bypass.
    IF NOT public.is_admin_or_staff(v_caller)
       AND NOT public.has_data_sharing_consent(v_member, v_caller) THEN
      RAISE EXCEPTION 'Data-sharing consent required to validate this member''s dose'
        USING ERRCODE = '42501';
    END IF;

    -- Audit the PHI access (member plan read), matching the dosing audit pattern.
    PERFORM public.write_audit_journal(
      p_action_type := 'view',
      p_area        := 'studies',
      p_details     := jsonb_build_object(
        'member_distribution_plan_id', p_member_distribution_plan_id,
        'proposed_dose_amount', p_dose_amount,
        'proposed_dose_unit', p_dose_unit
      ),
      p_entity_id   := p_member_distribution_plan_id::text,
      p_entity_type := 'dose_validation',
      p_severity    := 'info',
      p_summary     := 'Validated a proposed dose against a member distribution plan',
      p_tags        := ARRAY['phi', 'member', 'dose_validation'],
      p_user_id     := v_caller
    );
  END IF;

  -- ── PRODUCT TIER: bounds from product_dose_units (always evaluated) ───────────
  SELECT * INTO v_limits
  FROM product_dose_units
  WHERE product_id = p_product_id
    AND dose_unit_code = p_dose_unit
  LIMIT 1;

  IF FOUND THEN
    v_match := true;
    v_recommended := jsonb_build_object(
      'default_amount', v_limits.default_amount,
      'min_amount',     v_limits.min_amount,
      'max_amount',     v_limits.max_amount,
      'step_amount',    v_limits.step_amount
    );

    IF v_limits.min_amount IS NOT NULL AND p_dose_amount < v_limits.min_amount THEN
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
        'level', 'low', 'field', 'dose_amount', 'context', 'product_minimum',
        'message', 'Dose is below the recommended minimum for this product/unit.',
        'recommended_min', v_limits.min_amount, 'proposed', p_dose_amount));
    END IF;

    IF v_limits.max_amount IS NOT NULL AND p_dose_amount > v_limits.max_amount THEN
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
        'level', 'high', 'field', 'dose_amount', 'context', 'product_maximum',
        'message', 'Dose is above the recommended maximum for this product/unit.',
        'recommended_max', v_limits.max_amount, 'proposed', p_dose_amount));
    END IF;

    IF v_limits.step_amount IS NOT NULL AND v_limits.step_amount > 0 THEN
      IF (p_dose_amount - COALESCE(v_limits.min_amount, 0)) % v_limits.step_amount <> 0 THEN
        v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
          'level', 'info', 'field', 'dose_amount', 'context', 'product_step_granularity',
          'message', 'Dose is not aligned to the recommended step granularity.',
          'recommended_step', v_limits.step_amount, 'proposed', p_dose_amount));
      END IF;
    END IF;
  ELSE
    v_recommended := NULL;
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'level', 'info', 'field', 'dose_unit', 'context', 'unknown_product_unit',
      'message', 'No recommended bounds configured for this product/unit combination.',
      'product_id', p_product_id, 'dose_unit', p_dose_unit));
  END IF;

  -- ── STUDY TIER: deviation from the study-prescribed protocol dose ─────────────
  IF v_has_member AND v_protocol_id IS NOT NULL THEN
    SELECT sdp.dose_amount INTO v_protocol_dose
    FROM study_distribution_protocols sdp
    WHERE sdp.id = v_protocol_id;
    IF FOUND AND v_protocol_dose IS NOT NULL THEN
      v_has_study := true;
      IF p_dose_amount <> v_protocol_dose THEN
        v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
          'level', 'info', 'field', 'dose_amount', 'context', 'study_protocol_deviation',
          'message', 'Proposed dose differs from the study-prescribed protocol dose.',
          'protocol_prescribed', v_protocol_dose, 'proposed', p_dose_amount,
          'delta', p_dose_amount - v_protocol_dose));
      END IF;
    END IF;
  END IF;

  -- ── MEMBER TIER: deviation from the member's current effective plan dose ──────
  IF v_has_member THEN
    v_current_dose := COALESCE(v_custom_dose, v_plan_dose, v_protocol_dose);
    IF v_current_dose IS NOT NULL AND p_dose_amount <> v_current_dose THEN
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
        'level', 'info', 'field', 'dose_amount', 'context', 'member_plan_deviation',
        'message', 'Proposed dose differs from the member''s current plan dose.',
        'current_plan', v_current_dose, 'proposed', p_dose_amount,
        'delta', p_dose_amount - v_current_dose));
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'valid',              true,
    'warnings',           v_warnings,
    'recommended',        v_recommended,
    'product_unit_match', v_match,
    'context', jsonb_build_object(
      'has_member_context', v_has_member,
      'has_study_context',  v_has_study
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION public.validate_dose_proposal(uuid, numeric, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.validate_dose_proposal(uuid, numeric, text, uuid) TO anon;
GRANT EXECUTE ON FUNCTION public.validate_dose_proposal(uuid, numeric, text, uuid) TO authenticated;

COMMENT ON FUNCTION public.validate_dose_proposal(uuid, numeric, text, uuid) IS
'Advisory dose validation. Product tier (product,amount,unit) is anon-friendly and never blocks. The optional p_member_distribution_plan_id adds the consultant tier: PHI access held to the dosing access contract (auth + consultant/admin role + data-sharing consent, audited) and warnings for deviation from the study protocol + the member''s current plan. valid is always true; the guard governs reading member context, not logging the dose.';


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/verify_health_document_audited.sql
-- -----------------------------------------------------------------------------

-- Function: public.verify_health_document_audited
-- Arguments: p_document_id uuid, p_review_notes text
-- Description: Marks a health document as verified by admin/staff or authorized partner. Audited.

CREATE OR REPLACE FUNCTION public.verify_health_document_audited(
  p_document_id uuid,
  p_review_notes text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_partner_id uuid;
  v_is_admin boolean;
  v_doc record;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT id, user_id, study_registration_id
  INTO v_doc
  FROM public.member_health_documents
  WHERE id = p_document_id;

  IF v_doc.id IS NULL THEN
    RAISE EXCEPTION 'Document not found';
  END IF;

  v_is_admin := public.is_admin_or_staff(v_user_id);
  SELECT pp.id INTO v_partner_id FROM public.partner_profiles pp WHERE pp.user_id = v_user_id;

  IF NOT (
    v_is_admin
    OR (
      v_partner_id IS NOT NULL
      AND public.has_data_sharing_consent(v_doc.user_id, v_user_id)
      AND EXISTS (
        SELECT 1
        FROM public.document_sharing_permissions dsp
        WHERE dsp.document_id = v_doc.id
          AND dsp.revoked_at IS NULL
          AND dsp.can_view = true
          AND (
            dsp.shared_with_partner_id = v_partner_id
            OR (dsp.shared_with_study_id IS NOT NULL AND public.is_study_consultant(dsp.shared_with_study_id))
          )
      )
    )
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  UPDATE public.member_health_documents
  SET
    verified_at = now(),
    verified_by = v_user_id,
    review_notes = COALESCE(p_review_notes, review_notes),
    updated_at = now()
  WHERE id = p_document_id;

  PERFORM public.write_audit_journal(
      p_action_type := 'update',
      p_area := 'documents',
      p_details := jsonb_build_object('reviewer_role', CASE WHEN v_is_admin THEN 'admin_or_staff' ELSE 'partner' END),
      p_entity_id := p_document_id::text,
      p_entity_type := 'member_health_document',
      p_new_values := NULL,
      p_old_values := NULL,
      p_severity := 'info',
      p_summary := 'Health document verified',
      p_tags := ARRAY['phi','documents','review'],
      p_user_id := v_user_id
  );

  RETURN jsonb_build_object('success', true);
END;
$function$;

-- Permissions
REVOKE ALL ON FUNCTION public.verify_health_document_audited(uuid, text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.verify_health_document_audited(uuid, text) FROM anon;
GRANT EXECUTE ON FUNCTION public.verify_health_document_audited(uuid, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/wd_upsert_driver_stats_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_upsert_driver_stats_audited
-- Popis: Batch upsert statistiky řidičů z _getStaDrivers. Jeden snapshot per
--        řidič — upsert podle wd_driver_id (poslední okno přepisuje).
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT + fail-closed auth guard.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.wd_upsert_driver_stats_audited(
  p_stats jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean := public.is_service_role();
  v_batch jsonb;
  v_total integer;
  v_updated integer;
BEGIN
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  IF p_stats IS NULL OR jsonb_typeof(p_stats) <> 'array' THEN
    RAISE EXCEPTION 'p_stats must be a jsonb array';
  END IF;

  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON ((item->>'wd_driver_id')::integer) item
    FROM jsonb_array_elements(p_stats) AS item
    WHERE item->>'wd_driver_id' IS NOT NULL
  ) AS deduped;

  v_total := jsonb_array_length(v_batch);

  SELECT count(*) INTO v_updated
  FROM public.wd_driver_stats s
  JOIN jsonb_array_elements(v_batch) AS item
    ON s.wd_driver_id = (item->>'wd_driver_id')::integer;

  INSERT INTO public.wd_driver_stats (
    wd_driver_id, period_from, period_to, total_km, service_km, private_km,
    driving_seconds, driving_service_seconds, driving_private_seconds,
    driving_service_day_seconds, driving_service_night_seconds, commute_count,
    raw_data, last_import_at, updated_at
  )
  SELECT
    (item->>'wd_driver_id')::integer,
    NULLIF(item->>'period_from', '')::date,
    NULLIF(item->>'period_to', '')::date,
    NULLIF(item->>'total_km', '')::numeric,
    NULLIF(item->>'service_km', '')::numeric,
    NULLIF(item->>'private_km', '')::numeric,
    NULLIF(item->>'driving_seconds', '')::integer,
    NULLIF(item->>'driving_service_seconds', '')::integer,
    NULLIF(item->>'driving_private_seconds', '')::integer,
    NULLIF(item->>'driving_service_day_seconds', '')::integer,
    NULLIF(item->>'driving_service_night_seconds', '')::integer,
    NULLIF(item->>'commute_count', '')::integer,
    item->'raw',
    now(),
    now()
  FROM jsonb_array_elements(v_batch) AS item
  ON CONFLICT (wd_driver_id) DO UPDATE SET
    period_from                   = EXCLUDED.period_from,
    period_to                     = EXCLUDED.period_to,
    total_km                      = EXCLUDED.total_km,
    service_km                    = EXCLUDED.service_km,
    private_km                    = EXCLUDED.private_km,
    driving_seconds               = EXCLUDED.driving_seconds,
    driving_service_seconds       = EXCLUDED.driving_service_seconds,
    driving_private_seconds       = EXCLUDED.driving_private_seconds,
    driving_service_day_seconds   = EXCLUDED.driving_service_day_seconds,
    driving_service_night_seconds = EXCLUDED.driving_service_night_seconds,
    commute_count                 = EXCLUDED.commute_count,
    raw_data                      = EXCLUDED.raw_data,
    last_import_at                = now(),
    updated_at                    = now();

  -- Sufix `_audited` je SLIB, ne ozdoba: brána `audited-function-integrity`
  -- vyžaduje, aby funkce s tímhle jménem do žurnálu opravdu psala. Bez toho
  -- je jméno tvrzení, které nikdo nesplnil.
  --
  -- ⭐ Jeden zápis za DÁVKU, ne za řádek. Import běží po tisících vět a audit
  -- per řádek by z jednoho běhu udělal tisíce zápisů — tedy z měřidla zátěž.
  -- ⛔ Do detailu jdou jen POČTY a jméno tabulky. Žádná SPZ, žádné jméno
  -- řidiče: doklad nese tvrzení, ne identitu, a žurnál není kopie dat.
  PERFORM public.write_audit_journal(
    p_action_type := 'integration'::public.journal_action_type,
    p_area        := 'system'::public.journal_area,
    p_details     := jsonb_build_object(
      'table', 'wd_driver_stats',
      'total', v_total,
      'updated', v_updated,
      'inserted', v_total - v_updated,
      'via_service_role', v_is_service
    ),
    p_entity_type := 'wd_driver_stats',
    p_summary     := 'Import statistik řidičů z Webdispečinku',
    p_user_id     := auth.uid()
  );

  RETURN jsonb_build_object('total', v_total, 'updated', v_updated, 'inserted', v_total - v_updated);
END;
$$;

REVOKE ALL ON FUNCTION public.wd_upsert_driver_stats_audited(jsonb) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.wd_upsert_driver_stats_audited(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/wd_upsert_overspeed_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_upsert_overspeed_audited
-- Popis: Batch upsert překročení rychlosti z _getCarOverSpeed. Upsert podle
--        (wd_car_id, time_from) — opakovaný import okna aktualizuje úseky.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT + fail-closed auth guard.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.wd_upsert_overspeed_audited(
  p_events jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean := public.is_service_role();
  v_batch jsonb;
  v_total integer;
  v_updated integer;
BEGIN
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  IF p_events IS NULL OR jsonb_typeof(p_events) <> 'array' THEN
    RAISE EXCEPTION 'p_events must be a jsonb array';
  END IF;

  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON ((item->>'wd_car_id')::integer, (item->>'time_from')::timestamptz) item
    FROM jsonb_array_elements(p_events) AS item
    WHERE item->>'wd_car_id' IS NOT NULL
      AND item->>'time_from' IS NOT NULL
  ) AS deduped;

  v_total := jsonb_array_length(v_batch);

  SELECT count(*) INTO v_updated
  FROM public.wd_overspeed o
  JOIN jsonb_array_elements(v_batch) AS item
    ON o.wd_car_id = (item->>'wd_car_id')::integer
   AND o.time_from = (item->>'time_from')::timestamptz;

  INSERT INTO public.wd_overspeed (
    wd_car_id, wd_driver_id, max_speed_kmh, time_from, time_to, lat, lon,
    distance_km, raw_data, last_import_at, updated_at
  )
  SELECT
    (item->>'wd_car_id')::integer,
    NULLIF(item->>'wd_driver_id', '')::integer,
    NULLIF(item->>'max_speed_kmh', '')::numeric,
    (item->>'time_from')::timestamptz,
    NULLIF(item->>'time_to', '')::timestamptz,
    NULLIF(item->>'lat', '')::numeric,
    NULLIF(item->>'lon', '')::numeric,
    NULLIF(item->>'distance_km', '')::numeric,
    item->'raw',
    now(),
    now()
  FROM jsonb_array_elements(v_batch) AS item
  ON CONFLICT (wd_car_id, time_from) DO UPDATE SET
    wd_driver_id   = EXCLUDED.wd_driver_id,
    max_speed_kmh  = EXCLUDED.max_speed_kmh,
    time_to        = EXCLUDED.time_to,
    lat            = EXCLUDED.lat,
    lon            = EXCLUDED.lon,
    distance_km    = EXCLUDED.distance_km,
    raw_data       = EXCLUDED.raw_data,
    last_import_at = now(),
    updated_at     = now();

  -- Sufix `_audited` je SLIB, ne ozdoba: brána `audited-function-integrity`
  -- vyžaduje, aby funkce s tímhle jménem do žurnálu opravdu psala. Bez toho
  -- je jméno tvrzení, které nikdo nesplnil.
  --
  -- ⭐ Jeden zápis za DÁVKU, ne za řádek. Import běží po tisících vět a audit
  -- per řádek by z jednoho běhu udělal tisíce zápisů — tedy z měřidla zátěž.
  -- ⛔ Do detailu jdou jen POČTY a jméno tabulky. Žádná SPZ, žádné jméno
  -- řidiče: doklad nese tvrzení, ne identitu, a žurnál není kopie dat.
  PERFORM public.write_audit_journal(
    p_action_type := 'integration'::public.journal_action_type,
    p_area        := 'system'::public.journal_area,
    p_details     := jsonb_build_object(
      'table', 'wd_overspeed',
      'total', v_total,
      'updated', v_updated,
      'inserted', v_total - v_updated,
      'via_service_role', v_is_service
    ),
    p_entity_type := 'wd_overspeed',
    p_summary     := 'Import překročení rychlosti z Webdispečinku',
    p_user_id     := auth.uid()
  );

  RETURN jsonb_build_object('total', v_total, 'updated', v_updated, 'inserted', v_total - v_updated);
END;
$$;

REVOKE ALL ON FUNCTION public.wd_upsert_overspeed_audited(jsonb) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.wd_upsert_overspeed_audited(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/wd_upsert_worktime_audited.sql
-- -----------------------------------------------------------------------------

-- ============================================================================
-- Source of Truth: wd_upsert_worktime_audited
-- Popis: Batch upsert výkonů řidičů podle tachografu z _getDriverWorkTacho.
--        Upsert podle (wd_driver_id, work_date, car_identifikator) —
--        tacho se zpětně dopočítává, opakovaný import stejného okna aktualizuje.
-- Bezpečnost: SECURITY DEFINER + REVOKE/GRANT + fail-closed auth guard.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.wd_upsert_worktime_audited(
  p_worktime jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_is_service boolean := public.is_service_role();
  v_batch jsonb;
  v_total integer;
  v_updated integer;
BEGIN
  -- Authorization (FIRST, before any data access). is_service_role() COALESCEs
  -- to false → guard fails CLOSED without a role claim.
  IF NOT v_is_service AND NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Unauthorized: admin, staff, or service_role required';
  END IF;

  IF p_worktime IS NULL OR jsonb_typeof(p_worktime) <> 'array' THEN
    RAISE EXCEPTION 'p_worktime must be a jsonb array';
  END IF;

  -- Dedup podle (wd_driver_id, work_date, car_identifikator) — ON CONFLICT nesmí
  -- zasáhnout stejný řádek v jedné dávce dvakrát.
  SELECT COALESCE(jsonb_agg(deduped.item), '[]'::jsonb) INTO v_batch
  FROM (
    SELECT DISTINCT ON (
      (item->>'wd_driver_id')::integer,
      (item->>'work_date')::date,
      COALESCE(item->>'car_identifikator', '')
    ) item
    FROM jsonb_array_elements(p_worktime) AS item
    WHERE item->>'wd_driver_id' IS NOT NULL
      AND item->>'work_date' IS NOT NULL
  ) AS deduped;

  v_total := jsonb_array_length(v_batch);

  SELECT count(*) INTO v_updated
  FROM public.wd_worktime w
  JOIN jsonb_array_elements(v_batch) AS item
    ON w.wd_driver_id = (item->>'wd_driver_id')::integer
   AND w.work_date = (item->>'work_date')::date
   AND w.car_identifikator = COALESCE(item->>'car_identifikator', '');

  INSERT INTO public.wd_worktime (
    wd_driver_id, car_identifikator, work_date, day_type, work_from, work_to,
    total_drive_seconds, total_work_seconds, total_rest_seconds, total_standby_seconds,
    night_drive_seconds, night_work_seconds, night_rest_seconds, night_standby_seconds,
    distance_km, absences, raw_data, last_import_at, updated_at
  )
  SELECT
    (item->>'wd_driver_id')::integer,
    COALESCE(item->>'car_identifikator', ''),
    (item->>'work_date')::date,
    NULLIF(item->>'day_type', ''),
    NULLIF(item->>'work_from', '')::time,
    NULLIF(item->>'work_to', '')::time,
    NULLIF(item->>'total_drive_seconds', '')::integer,
    NULLIF(item->>'total_work_seconds', '')::integer,
    NULLIF(item->>'total_rest_seconds', '')::integer,
    NULLIF(item->>'total_standby_seconds', '')::integer,
    NULLIF(item->>'night_drive_seconds', '')::integer,
    NULLIF(item->>'night_work_seconds', '')::integer,
    NULLIF(item->>'night_rest_seconds', '')::integer,
    NULLIF(item->>'night_standby_seconds', '')::integer,
    NULLIF(item->>'distance_km', '')::numeric,
    item->'absences',
    item->'raw',
    now(),
    now()
  FROM jsonb_array_elements(v_batch) AS item
  ON CONFLICT (wd_driver_id, work_date, car_identifikator) DO UPDATE SET
    day_type              = EXCLUDED.day_type,
    work_from             = EXCLUDED.work_from,
    work_to               = EXCLUDED.work_to,
    total_drive_seconds   = EXCLUDED.total_drive_seconds,
    total_work_seconds    = EXCLUDED.total_work_seconds,
    total_rest_seconds    = EXCLUDED.total_rest_seconds,
    total_standby_seconds = EXCLUDED.total_standby_seconds,
    night_drive_seconds   = EXCLUDED.night_drive_seconds,
    night_work_seconds    = EXCLUDED.night_work_seconds,
    night_rest_seconds    = EXCLUDED.night_rest_seconds,
    night_standby_seconds = EXCLUDED.night_standby_seconds,
    distance_km           = EXCLUDED.distance_km,
    absences              = EXCLUDED.absences,
    raw_data              = EXCLUDED.raw_data,
    last_import_at        = now(),
    updated_at            = now();

  -- Sufix `_audited` je SLIB, ne ozdoba: brána `audited-function-integrity`
  -- vyžaduje, aby funkce s tímhle jménem do žurnálu opravdu psala. Bez toho
  -- je jméno tvrzení, které nikdo nesplnil.
  --
  -- ⭐ Jeden zápis za DÁVKU, ne za řádek. Import běží po tisících vět a audit
  -- per řádek by z jednoho běhu udělal tisíce zápisů — tedy z měřidla zátěž.
  -- ⛔ Do detailu jdou jen POČTY a jméno tabulky. Žádná SPZ, žádné jméno
  -- řidiče: doklad nese tvrzení, ne identitu, a žurnál není kopie dat.
  PERFORM public.write_audit_journal(
    p_action_type := 'integration'::public.journal_action_type,
    p_area        := 'system'::public.journal_area,
    p_details     := jsonb_build_object(
      'table', 'wd_worktime',
      'total', v_total,
      'updated', v_updated,
      'inserted', v_total - v_updated,
      'via_service_role', v_is_service
    ),
    p_entity_type := 'wd_worktime',
    p_summary     := 'Import výkonů řidičů z Webdispečinku',
    p_user_id     := auth.uid()
  );

  RETURN jsonb_build_object('total', v_total, 'updated', v_updated, 'inserted', v_total - v_updated);
END;
$$;

REVOKE ALL ON FUNCTION public.wd_upsert_worktime_audited(jsonb) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.wd_upsert_worktime_audited(jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/write_my_audit_journal_entry.sql
-- -----------------------------------------------------------------------------

-- Function: public.write_my_audit_journal_entry
-- Arguments: p_action_type journal_action_type, p_area journal_area, p_details jsonb, p_entity_id text, p_entity_type text, p_new_values jsonb, p_old_values jsonb, p_summary text
-- Description: Self-attributed audit entry from a browser session. The ONLY audit-journal writer
--   reachable with a user JWT; write_audit_journal itself is service_role-only as of 2026-07-15.
--
--   WHY THIS EXISTS: write_audit_journal was GRANTed to `authenticated`, and it takes p_user_id.
--   Any logged-in user could therefore POST /rest/v1/rpc/write_audit_journal and author an entry
--   attributed to SOMEONE ELSE — fabricating evidence in the tamper-evident ledger. Worse, the
--   forged row got a VALID blockchain_hash, so fn_verify_audit_chain would attest it as authentic:
--   the hash proves the row was not altered AFTER the fact, it says nothing about who authored it.
--   Revoking the generic writer is the fix; the browser keeps this narrow, self-pinned door.
--   See docs/security/IDOR_P_USER_ID_AUDIT_2026-07-15.md.
--
-- Security: SECURITY DEFINER. There is deliberately NO p_user_id parameter — the actor is pinned
--   to auth.uid() and cannot be chosen by the caller, which is what makes attribution forgery
--   structurally impossible rather than merely guarded. Severity is likewise fixed at 'info' so a
--   caller cannot forge 'critical' entries and drown real signals. p_action_type/p_area stay
--   caller-supplied but are ENUM-constrained by the database.
-- Params: alphabetical (see src/tests/db/rpc-params-alphabetical.test.ts).
-- @audit: none — this IS the audit writer.

CREATE OR REPLACE FUNCTION public.write_my_audit_journal_entry(
  p_action_type journal_action_type,
  p_area        journal_area DEFAULT 'system'::journal_area,
  p_details     jsonb DEFAULT NULL,
  p_entity_id   text DEFAULT NULL,
  p_entity_type text DEFAULT 'unknown',
  p_new_values  jsonb DEFAULT NULL,
  p_old_values  jsonb DEFAULT NULL,
  p_summary     text DEFAULT ''
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  -- Fail closed: an unauthenticated caller has no identity to attribute the entry to, and an
  -- unattributed "self" entry is meaningless. anon has no grant either — this is defence in depth.
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  RETURN public.write_audit_journal(
    p_action_type := p_action_type,
    p_area        := p_area,
    p_details     := p_details,
    p_entity_id   := p_entity_id,
    p_entity_type := p_entity_type,
    p_new_values  := p_new_values,
    p_old_values  := p_old_values,
    p_severity    := 'info'::journal_severity,
    p_summary     := p_summary,
    p_tags        := ARRAY['self-reported'],
    p_user_id     := auth.uid()
  );
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.write_my_audit_journal_entry(p_action_type journal_action_type, p_area journal_area, p_details jsonb, p_entity_id text, p_entity_type text, p_new_values jsonb, p_old_values jsonb, p_summary text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.write_my_audit_journal_entry(p_action_type journal_action_type, p_area journal_area, p_details jsonb, p_entity_id text, p_entity_type text, p_new_values jsonb, p_old_values jsonb, p_summary text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.write_my_audit_journal_entry(p_action_type journal_action_type, p_area journal_area, p_details jsonb, p_entity_id text, p_entity_type text, p_new_values jsonb, p_old_values jsonb, p_summary text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/zaloz_ucet_zarizeni_interni.sql
-- -----------------------------------------------------------------------------

-- Function: zaloz_ucet_zarizeni_interni
-- Založí (idempotentně) vlastní účet tabletu. JEDINÁ cesta, kudy účet zařízení vzniká —
-- volá ji definer admin_set_knock_device_approval při schválení tabletu (a heals při
-- jednorázovém dorovnání dříve schválených tabletů). Klient ji volat nesmí (bez grantu).
--
-- ⛔ POŘADÍ JE BEZPEČNOSTNÍ VLASTNOST (revize Aisha Guru 29. 9.): vazba
-- knock_device_credentials.ucet_id se zapíše DŘÍV, než vznikne uživatel. Trigger
-- handle_new_user pak pozná účet zařízení podle téhle vazby (strana serveru) a roli
-- `member` nepřidá. Příznak v raw_user_meta_data by šel nastavit i běžnou registrací.
CREATE OR REPLACE FUNCTION public.zaloz_ucet_zarizeni_interni(p_kid text)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_d public.knock_device_credentials%ROWTYPE;
  v_ucet uuid;
BEGIN
  SELECT * INTO v_d FROM public.knock_device_credentials WHERE kid = p_kid FOR UPDATE;
  IF NOT FOUND OR v_d.druh <> 'tablet' THEN
    RETURN NULL;
  END IF;
  IF v_d.ucet_id IS NOT NULL THEN
    RETURN v_d.ucet_id;
  END IF;

  v_ucet := gen_random_uuid();
  UPDATE public.knock_device_credentials SET ucet_id = v_ucet, updated_at = now() WHERE kid = p_kid;
  INSERT INTO aisha_auth.users (id, email, raw_user_meta_data)
  VALUES (v_ucet, NULL, jsonb_build_object('display_name', 'Tablet ' || p_kid));

  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (auth.uid(), 'knock_device_account_created', jsonb_build_object('kid', p_kid, 'ucet_id', v_ucet));
  RETURN v_ucet;
END;
$function$;

REVOKE ALL ON FUNCTION public.zaloz_ucet_zarizeni_interni(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.zaloz_ucet_zarizeni_interni(text) FROM anon, authenticated;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/admin_set_knock_device_approval.sql
-- -----------------------------------------------------------------------------

-- Function: public.admin_set_knock_device_approval
-- Arguments: p_kid text, p_approved boolean
-- Security: SECURITY DEFINER, jen admin/staff nebo service_role.
--
-- Schválení a odvolání zařízení. Tohle je JEDINÉ místo, kde se o vstupu
-- rozhoduje — `register_knock_device` schválit nesmí (viz jeho hlavička).
--
-- ⛔ ODVOLÁNÍ ZÁZNAM NEMAŽE. Smazaný řádek vypadá jako „nikdy nebyl", takže by
-- z ničeho nešlo poznat, že zařízení kdysi schválené bylo — a to je přesně
-- údaj, který při vyšetřování potřebuješ. Odvolané zařízení musí zaťukat
-- ručně; žádná zvláštní větev pro to není potřeba, `unknown-kid` a odvolaný
-- průkaz se z pohledu telefonu chovají stejně (dveře mlčí).

CREATE OR REPLACE FUNCTION public.admin_set_knock_device_approval(p_kid text, p_approved boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_dotceno int;
BEGIN
  IF NOT ((SELECT public.is_service_role()) OR (SELECT public.is_admin_or_staff())) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  IF p_approved THEN
    UPDATE public.knock_device_credentials
       SET approved_at = now(), approved_by = v_uid,
           revoked_at = NULL, revoked_by = NULL, updated_at = now()
     WHERE kid = p_kid;
  ELSE
    UPDATE public.knock_device_credentials
       SET revoked_at = now(), revoked_by = v_uid,
           approved_at = NULL, approved_by = NULL, updated_at = now()
     WHERE kid = p_kid;
  END IF;

  GET DIAGNOSTICS v_dotceno = ROW_COUNT;
  IF v_dotceno = 0 THEN
    RAISE EXCEPTION 'zařízení % neexistuje', p_kid;
  END IF;

  -- F2: schválený TABLET dostane vlastní účet (jediné místo, kde účet zařízení vzniká;
  -- idempotentní). Odvolání účet NEmaže — zůstane kvůli auditu a jen ztratí platnost
  -- (pátá cesta viditelnosti se ptá na platný průkaz při každém volání).
  IF p_approved THEN
    PERFORM public.zaloz_ucet_zarizeni_interni(p_kid);
  END IF;

  -- Audit nese JEN identifikátory, nikdy klíč ani PII.
  INSERT INTO public.audit_journal (user_id, action, metadata)
  VALUES (v_uid,
          CASE WHEN p_approved THEN 'knock_device_approved' ELSE 'knock_device_revoked' END,
          jsonb_build_object('kid', p_kid));

  RETURN true;
END;
$function$
;

-- Permissions
REVOKE ALL ON FUNCTION public.admin_set_knock_device_approval(text, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_set_knock_device_approval(text, boolean) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/zarizeni_deklarace_cteni.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- zarizeni_deklarace_cteni() — deklarace zařízení pro storage-auth.
--
-- Vrací `{ deklarace, commit, zapsano }`, nebo NULL, když instance nic
-- nedeklarovala (schopnost vypnutá). storage-auth ji čte za běhu — při startu,
-- v intervalu srovnání úložiště a při dotazu kiosku na seznam appek.
--
-- ⛔ Jen service role: deklarace nese výbavu tabletu (adresu API, dveře) a otisky
--    balíčků; administrace ji dostává přes storage-auth `/zarizeni/konfigurace`.
-- =============================================================================
CREATE OR REPLACE FUNCTION public.zarizeni_deklarace_cteni()
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v jsonb;
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized: service_role required' USING errcode = '42501';
  END IF;
  SELECT jsonb_build_object('deklarace', d.deklarace, 'commit', d.zdroj_commit, 'zapsano', d.zapsano)
    INTO v
    FROM public.zarizeni_deklarace d
   WHERE d.jedina;
  RETURN v;
END;
$$;

REVOKE ALL ON FUNCTION public.zarizeni_deklarace_cteni() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.zarizeni_deklarace_cteni() TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/zarizeni_deklarace_zapis.sql
-- -----------------------------------------------------------------------------

-- =============================================================================
-- zarizeni_deklarace_zapis(deklarace, commit) — zapíše deklaraci zařízení.
--
-- Volá ji hák dat instance (`NN_zarizeni_deklarace.sql` v datech instance,
-- psql jako service_role) s DOSLOVNÝM obsahem `zarizeni/hlidac.json`.
--
-- ⛔ Hlídá jen, že jde o JSON objekt s `applicationId` — celý tvar ověřuje CI dat
--    instance před sloučením a storage-auth při čtení (viz tables/zarizeni_deklarace.sql).
--    Nesmysl tady = chyba = červená migrace, stejně jako u ostatních dat instance.
-- ⛔ Jen service role: zápis deklarace určuje, co se instaluje na tablety.
-- =============================================================================
CREATE OR REPLACE FUNCTION public.zarizeni_deklarace_zapis(p_deklarace jsonb, p_commit text DEFAULT NULL)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Unauthorized: service_role required' USING errcode = '42501';
  END IF;
  IF p_deklarace IS NULL OR jsonb_typeof(p_deklarace) <> 'object' OR NOT (p_deklarace ? 'applicationId') THEN
    RAISE EXCEPTION 'deklarace zařízení musí být JSON objekt s applicationId' USING errcode = '22023';
  END IF;
  INSERT INTO public.zarizeni_deklarace (jedina, deklarace, zdroj_commit, zapsano)
  VALUES (true, p_deklarace, NULLIF(p_commit, ''), now())
  ON CONFLICT (jedina) DO UPDATE
    SET deklarace = EXCLUDED.deklarace,
        zdroj_commit = EXCLUDED.zdroj_commit,
        zapsano = now();
END;
$$;

REVOKE ALL ON FUNCTION public.zarizeni_deklarace_zapis(jsonb, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.zarizeni_deklarace_zapis(jsonb, text) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/aisha_choose_execution_strategy.sql
-- -----------------------------------------------------------------------------

-- Function: aisha_choose_execution_strategy
-- AISHA core autopilot decision. Reads task + context, returns full execution plan:
--   { graph_id, mode, slot, profile, batch_eligible, strategy, required_capabilities,
--     audit_anchor, estimated_cost, reasoning }
--
-- This is the single source of truth for AISHA's "what to do" decision per task.
-- Downstream: svc-langgraph-runner uses graph_id; svc-ai-chat uses slot/profile;
-- batch routing uses strategy; cosmos anchor uses audit_anchor; OpenClaw plan/sandbox
-- triggered when required_capabilities contains openclaw_plan or openclaw_sandbox.

CREATE OR REPLACE FUNCTION public.aisha_choose_execution_strategy(
  p_task jsonb,
  p_context jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  -- Task inputs
  v_description       text   := p_task->>'description';
  v_task_type         text   := COALESCE(p_task->>'type', 'chat');
  v_deadline_hours    int    := COALESCE((p_task->>'deadline_hours')::int, 24);
  v_criticality       text   := COALESCE(p_task->>'criticality', 'normal');
  v_risk_level        text   := COALESCE(p_task->>'risk_level', 'low');
  v_expected_tokens   int    := COALESCE((p_task->>'expected_tokens')::int, 5000);
  v_agent_slug        text   := COALESCE(p_task->>'agent_slug', 'aisha');
  v_story_id          uuid   := NULLIF(p_task->>'story_id', '')::uuid;
  -- Context inputs
  v_session_id        text   := p_context->>'session_id';
  v_budget_remaining  numeric := COALESCE((p_context->>'budget_remaining')::numeric, 5.00);
  v_recent_error_rate numeric := COALESCE((p_context->>'recent_error_rate')::numeric, 0.0);
  -- Decision outputs
  v_graph_id          uuid;
  v_graph_slug        text;
  v_mode              text;
  v_slot              text;
  v_profile           text;
  v_batch_eligible    boolean := false;
  v_strategy          text;
  v_audit_anchor      boolean := false;
  v_caps              text[] := ARRAY[]::text[];
  v_needs             jsonb;   -- derived clow capability needs (write/internet/tools/runtime)
  v_estimated_cost    numeric;
  v_reasoning         text;
  v_pricing_per_1k    numeric := 0.001;  -- conservative default
  v_batch_threshold   int     := 24;     -- AISHA_BATCH_THRESHOLD_DEADLINE_HOURS default
BEGIN
  -- Auth: any authenticated caller or service_role
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF v_description IS NULL OR v_description = '' THEN
    RAISE EXCEPTION 'p_task.description is required';
  END IF;

  -- ============================================================
  -- 1. Mode (strict / creative / hybrid)
  -- ============================================================
  v_mode := CASE
    WHEN v_criticality IN ('critical', 'high') THEN 'strict'
    WHEN v_task_type IN ('creative', 'story_plan', 'brand_voice') THEN 'creative'
    WHEN v_task_type IN ('reflection', 'analyze') THEN 'hybrid'
    ELSE 'strict'
  END;

  -- ============================================================
  -- 2. Audit anchor (cosmos blockchain hash)
  -- ============================================================
  v_audit_anchor := (v_criticality IN ('critical', 'high'))
                 OR (v_task_type = 'deploy')
                 OR (v_risk_level = 'high');

  -- ============================================================
  -- 3. Required capabilities
  -- ============================================================
  IF v_risk_level = 'high' THEN
    v_caps := v_caps || ARRAY['openclaw_sandbox'];
  END IF;

  -- Multi-step orchestration patterns
  IF v_description ~* '\y(deploy|migration|delivery|complex refactor|rollout)\y' THEN
    v_caps := v_caps || ARRAY['openclaw_plan'];
  END IF;

  IF v_mode = 'creative' THEN
    v_caps := v_caps || ARRAY['occipitum_creative'];
  END IF;

  IF v_audit_anchor THEN
    v_caps := v_caps || ARRAY['cosmos_anchor'];
  END IF;

  -- Hippocampus is enabled when we have a story_id (per-story scoped learnings)
  -- or when running reflection on AISHA's own work
  IF v_story_id IS NOT NULL OR v_task_type IN ('reflection', 'deploy') THEN
    v_caps := v_caps || ARRAY['hippocampus'];
  END IF;

  -- ============================================================
  -- 4. Graph selection
  -- ============================================================
  -- Derive the clow's capability needs ONCE (single producer; openclaw_resolve_clow
  -- re-derives the same from the run task so fn_resolve_runtime gets real needs).
  v_needs := derive_clow_needs(p_task);

  v_graph_slug := CASE
    WHEN v_task_type = 'deploy' THEN 'deploy-reflect'
    WHEN v_task_type IN ('reflection', 'story_plan') AND v_story_id IS NOT NULL THEN 'story-plan-reflect'
    ELSE NULL  -- No graph → direct provider call (existing flow)
  END;

  -- A task whose work needs a non-direct_llm executor (write/internet/tools or an
  -- explicit runtime hint) but matches no specific reflection graph → the
  -- runtime-execute graph, which derives the runtime + dispatches via the adapter.
  -- This is what makes openclaw/hermes REACHABLE instead of dead-in-practice.
  IF v_graph_slug IS NULL AND (v_needs->>'has_capability_need')::boolean THEN
    v_graph_slug := 'runtime-execute';
  END IF;

  IF v_graph_slug IS NOT NULL THEN
    SELECT id INTO v_graph_id
    FROM ai_workflow_definitions
    WHERE name = v_graph_slug AND is_active = true
    ORDER BY version DESC
    LIMIT 1;
  END IF;

  -- ============================================================
  -- 5. Slot classification (Soulforge heuristic, DB-side mirror of TS)
  -- ============================================================
  v_slot := CASE
    WHEN v_description ~* '\y(read|explore|fetch|open|show|browse|load)\y' AND length(v_description) < 400 THEN 'spark'
    WHEN v_description ~* '\y(write|edit|create|implement|fix|refactor|build|add)\y' THEN 'ember'
    WHEN v_description ~* '\y(review|test|check|verify|audit|validate)\y' THEN 'verify'
    WHEN v_description ~* '\y(summariz|condens|shorten|tldr)' THEN 'compact'
    WHEN v_description ~* '\y(analyz|explain|compar|evaluat|diagnos)' THEN 'semantic'
    WHEN v_description ~* '\y(search|google|lookup|web|find)\y' THEN 'webSearch'
    WHEN v_description ~* '\y(clean|format|lint|tidy)\y' THEN 'desloppify'
    ELSE 'default'
  END;

  -- ============================================================
  -- 6. Profile (budget / balanced / maxQuality)
  -- ============================================================
  v_profile := CASE
    WHEN v_budget_remaining < 1.00 THEN 'budget'
    WHEN v_criticality IN ('critical', 'high') THEN 'maxQuality'
    WHEN v_recent_error_rate > 0.10 THEN 'maxQuality'  -- escalate on flaky runs
    ELSE 'balanced'
  END;

  -- ============================================================
  -- 7. Strategy: sync vs batch
  -- ============================================================
  -- Hard blacklists for batch
  IF v_criticality IN ('critical', 'high') THEN
    v_batch_eligible := false;
  ELSIF v_deadline_hours < 1 THEN
    v_batch_eligible := false;
  ELSIF v_task_type IN ('chat') THEN
    v_batch_eligible := false;   -- interactive UX
  -- Batch eligibility heuristic
  ELSIF v_deadline_hours >= v_batch_threshold AND v_expected_tokens >= 50000 THEN
    v_batch_eligible := true;
  ELSIF v_task_type IN ('analyze', 'report', 'eval') AND v_deadline_hours >= v_batch_threshold THEN
    v_batch_eligible := true;
  END IF;

  v_strategy := CASE WHEN v_batch_eligible THEN 'batch' ELSE 'sync' END;

  -- ============================================================
  -- 8. Cost estimation (rough — refined by llmRouter at execution)
  -- ============================================================
  -- Lookup approximate $/1K tokens from get_model_pricing (existing RPC)
  -- Fallback to conservative 0.001
  BEGIN
    SELECT COALESCE(
      (get_model_pricing(NULL)->>'avg_per_1k')::numeric,
      0.001
    )
    INTO v_pricing_per_1k;
  EXCEPTION WHEN OTHERS THEN
    v_pricing_per_1k := 0.001;
  END;

  v_estimated_cost := (v_expected_tokens / 1000.0) * v_pricing_per_1k;
  IF v_strategy = 'batch' THEN
    v_estimated_cost := v_estimated_cost * 0.5;  -- 50% off batch pricing
  END IF;

  -- ============================================================
  -- 9. Reasoning string (transparency)
  -- ============================================================
  v_reasoning := format(
    'type=%s, criticality=%s, deadline=%sh, risk=%s, tokens=%s, budget=%s, errors=%s → '
    'mode=%s, slot=%s, profile=%s, strategy=%s, graph=%s, caps=%s, anchor=%s',
    v_task_type, v_criticality, v_deadline_hours, v_risk_level, v_expected_tokens,
    v_budget_remaining, v_recent_error_rate,
    v_mode, v_slot, v_profile, v_strategy, COALESCE(v_graph_slug, '<none>'),
    array_to_string(v_caps, ','), v_audit_anchor
  );

  -- Audit (deferred — STABLE prevents insert from succeeding in some contexts,
  -- so we use a write-via-trigger pattern in non-stable wrapper if needed).
  -- Here we skip inline audit because STABLE; callers should audit via
  -- decisionProvenance.record() on the AISHA side.

  RETURN jsonb_build_object(
    'graph_id', v_graph_id,
    'graph_slug', v_graph_slug,
    'mode', v_mode,
    'slot', v_slot,
    'profile', v_profile,
    'batch_eligible', v_batch_eligible,
    'strategy', v_strategy,
    'required_capabilities', to_jsonb(v_caps),
    'capability_needs', v_needs,
    'audit_anchor', v_audit_anchor,
    'estimated_cost', round(v_estimated_cost, 6),
    'reasoning', v_reasoning
  );
END;
$$;

COMMENT ON FUNCTION public.aisha_choose_execution_strategy(jsonb, jsonb) IS
  'AISHA core autopilot decision. Pure STABLE function — same input always yields '
  'same output. Returns full execution plan for downstream orchestration. '
  'Audit is the caller''s responsibility (decisionProvenance.record).';

REVOKE ALL ON FUNCTION public.aisha_choose_execution_strategy(jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aisha_choose_execution_strategy(jsonb, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.aisha_choose_execution_strategy(jsonb, jsonb) TO service_role;


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/functions/derive_clow_needs.sql
-- -----------------------------------------------------------------------------

-- Function: derive_clow_needs
-- Derives a clow's CAPABILITY NEEDS (needs_write / needs_internet / needs_tools +
-- an optional runtime hint) from the task's semantics, so the runtime resolver
-- (fn_resolve_runtime) and the graph chooser (aisha_choose_execution_strategy) can
-- pick an executor that MATCHES the work — instead of every task defaulting to
-- direct_llm because nothing ever set the needs (the audit's static-link gap).
--
-- This is the SINGLE producer of clow needs, reused by both the chooser (to route a
-- capability-needing task to the runtime-execute graph) and openclaw_resolve_clow
-- (to populate the clow before fn_resolve_runtime). Precedence:
--   1. EXPLICIT task.needs_* / task.runtime ALWAYS win (a producer that knows the
--      task's requirements declares them precisely — this is NOT a gate).
--   2. Otherwise a SEMANTIC intent derivation from type + risk_level + a keyword
--      scan of the description, reusing the same keyword style the chooser already
--      uses for slot classification (write→ember, web→webSearch). It is intent
--      detection, NOT a roster of permitted names.
--
-- hermes (the reflexive-learning rail) is hinted only for a story-bound self-eval /
-- story-closure task — it executes evaluate_story_self(story_id), which needs both.

CREATE OR REPLACE FUNCTION public.derive_clow_needs(p_task jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
STABLE
AS $$
DECLARE
  v_desc  text    := COALESCE(p_task->>'description', '') || ' ' || COALESCE(p_task->>'purpose', '');
  v_type  text    := lower(COALESCE(p_task->>'type', p_task->>'task_kind', ''));
  v_risk  text    := COALESCE(p_task->>'risk_level', 'low');
  v_story uuid    := NULLIF(p_task->>'story_id', '')::uuid;
  v_write boolean;
  v_net   boolean;
  v_tools boolean;
  v_hint  text;
BEGIN
  IF auth.uid() IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- needs_write — side-effecting / mutating work
  v_write := COALESCE((p_task->>'needs_write')::boolean,
      v_type IN ('deploy', 'execute', 'code', 'agentic')
      OR v_desc ~* '\y(deploy|write|edit|create|implement|fix|refactor|build|migrat|rollout|delete|provision|install|publish)\y');

  -- needs_internet — outbound network / web access
  v_net := COALESCE((p_task->>'needs_internet')::boolean,
      v_desc ~* '\y(search|google|lookup|web|fetch|crawl|scrape|download|browse|http|api call)\y');

  -- needs_tools — tool-use / sandbox / multi-step agentic execution
  v_tools := COALESCE((p_task->>'needs_tools')::boolean,
      v_risk = 'high'
      OR v_type IN ('agentic', 'deploy', 'execute')
      OR v_desc ~* '\y(tool|agent|sandbox|orchestrat|multi.?step|run command|pipeline)\y');

  -- runtime hint — hermes is the learning rail (needs a story to evaluate)
  v_hint := CASE
    WHEN COALESCE(p_task->>'runtime', '') <> '' THEN p_task->>'runtime'   -- explicit override
    -- hermes only for genuine story-CLOSURE/eval tasks. NOT 'reflection'/'story_plan'
    -- — those route to the story-plan-reflect graph (which doesn't runtime-dispatch),
    -- so a hermes hint there would be derived-but-never-used (a dead signal).
    WHEN v_story IS NOT NULL AND v_type IN ('self_eval', 'story_closure', 'evaluate', 'learn')
      THEN 'hermes'
    ELSE NULL
  END;

  RETURN jsonb_build_object(
    'needs_write', v_write,
    'needs_internet', v_net,
    'needs_tools', v_tools,
    'runtime', v_hint,
    'has_capability_need', (v_write OR v_net OR v_tools OR v_hint IS NOT NULL)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.derive_clow_needs(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.derive_clow_needs(jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.derive_clow_needs(jsonb) TO service_role;

COMMENT ON FUNCTION public.derive_clow_needs(jsonb) IS
  'Single producer of clow capability needs (needs_write/internet/tools + runtime hint) from task semantics; explicit task.needs_*/runtime win. Reused by aisha_choose_execution_strategy (routing) + openclaw_resolve_clow (clow population) so runtime selection is fed dynamically, not hardcoded direct_llm.';


