-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/policies/twin_events_read.sql
-- -----------------------------------------------------------------------------

DROP POLICY IF EXISTS "twin_events_read" ON public.twin_events;
CREATE POLICY twin_events_read ON public.twin_events
  -- plný přístup k datům (2026-09-28): parametry v čase (nájemce, obsazenost jednotky…)
  -- udělený rozsah (vazby, zdroje dat, zdroje dvojčat): parametry v čase dvojčat, která smí
  -- číst (nájemce a obsazenost jednotky, sídlo protistrany…) — 2026-09-28
  FOR SELECT USING ((SELECT public.is_admin_or_staff()) OR (SELECT public.ma_plny_pristup_k_datum((SELECT auth.uid())))
                    OR twin_id IN (SELECT public.twin_ids_v_rozsahu((SELECT auth.uid()))));


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/policies/twin_events_service.sql
-- -----------------------------------------------------------------------------

DROP POLICY IF EXISTS "twin_events_service" ON public.twin_events;
CREATE POLICY twin_events_service ON public.twin_events
  FOR ALL USING (auth.jwt() ->> 'role' = 'service_role');


-- -----------------------------------------------------------------------------
-- File: aisha/db/sql/policies/twin_external_refs_read.sql
-- -----------------------------------------------------------------------------

DROP POLICY IF EXISTS "twin_external_refs_read" ON public.twin_external_refs;
CREATE POLICY twin_external_refs_read ON public.twin_external_refs
  FOR SELECT USING (
    (SELECT public.is_admin_or_staff())
    -- plný přístup k datům: identifikátory ano, vazby ÚČTŮ (kdo je čí uživatel) ne
    OR (ref_kind <> 'account' AND (SELECT public.ma_plny_pristup_k_datum((SELECT auth.uid()))))
    OR (ref_kind <> 'account'
        AND twin_id IN (SELECT public.twin_ids_v_rozsahu((SELECT auth.uid()))))
  );


