DROP POLICY IF EXISTS "Admins can delete archive scans" ON storage.objects;
CREATE POLICY "Admins can delete archive scans"
ON storage.objects
FOR DELETE
TO authenticated
USING (
  bucket_id = 'archive-scans'
  AND (SELECT public.is_admin_or_staff())
